def act(obs, state):
    """
    Closed-loop policy: each step reads the tile_map and decides the next
    placement based on what's actually there.

    Strategy:
    - Phase 0: Place coal power plant
    - Phase 1: Extend wire from power plant outward (spine)
    - Phase 2: Extend road adjacent to wire spine
    - Phase 3: Place residential zones adjacent to road
    - Phase 4: Add commercial/industrial zones for balance
    - Continuously: check if power/road coverage needs extension
    """

    cx, cy = WORLD_W // 2, WORLD_H // 2

    # Initialize state
    if "phase" not in state:
        state["phase"] = 0
        state["tick"] = 0

    state["tick"] += 1
    tick = state["tick"]

    tm = obs.tile_map

    # Helper: is position valid and empty (or road/wire safe to place on)?
    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def is_empty(x, y):
        if not in_bounds(x, y): return False
        return empty_mask[y, x]

    def has_wire(x, y):
        if not in_bounds(x, y): return False
        return wire_mask[y, x]

    def has_road(x, y):
        if not in_bounds(x, y): return False
        return road_mask[y, x]

    def has_plant(x, y):
        if not in_bounds(x, y): return False
        return plant_mask[y, x]

    def has_res(x, y):
        if not in_bounds(x, y): return False
        return res_mask[y, x]

    # Phase 0: Place coal power plant
    # Put it at cx-4, cy (left of spine)
    plant_x, plant_y = cx - 4, cy
    if not has_plant(plant_x, plant_y):
        # Check if we've already tried - just do it if no plant nearby
        if not np.any(plant_mask[cy-3:cy+4, cx-7:cx+1]):
            return (Tool.COALPOWER, plant_x, plant_y)

    # Phase 1 & 2: Build wire spine (vertical at cx) and road (at cx+1)
    # Scan to find the extent of existing wire/road
    # Wire column: cx, from cy-15 to cy+15
    # Road column: cx+1, from cy-15 to cy+15

    spine_x = cx  # wire column
    road_x = cx + 1  # road column

    # Find missing wire segments first (priority: power)
    wire_range = range(max(0, cy - 14), min(WORLD_H - 1, cy + 15))
    for wy in wire_range:
        if not has_wire(spine_x, wy) and not has_plant(spine_x, wy):
            # Check adjacency: only place if connected to existing wire or plant
            adj_has_power = (has_wire(spine_x, wy-1) or has_wire(spine_x, wy+1) or
                           has_plant(spine_x, wy-1) or has_plant(spine_x, wy+1) or
                           has_plant(spine_x-1, wy) or has_plant(spine_x+1, wy))
            # For first wire, connect from plant
            if has_plant(plant_x, plant_y):
                # Plant at cx-4, wire at cx - connect wire adjacent to plant
                # Wire at cx-3 -> cx-2 -> cx-1 -> cx (spine)
                # Actually place wire at cx directly but need path from plant
                # Simplification: place wire if in range, prioritizing center
                if adj_has_power or wy == cy:
                    return (Tool.WIRE, spine_x, wy)

    # Connect plant to wire spine with horizontal wire
    for wx in range(plant_x + 2, spine_x):
        if not has_wire(wx, cy) and not has_plant(wx, cy):
            adj = (has_plant(wx-1, cy) or has_wire(wx-1, cy) or 
                   has_wire(wx+1, cy))
            if adj:
                return (Tool.WIRE, wx, cy)

    # Find missing road segments
    road_range = range(max(0, cy - 14), min(WORLD_H - 1, cy + 15))
    for ry in road_range:
        if not has_road(road_x, ry):
            adj_road = (has_road(road_x, ry-1) or has_road(road_x, ry+1) or 
                       ry == cy)
            if adj_road:
                return (Tool.ROAD, road_x, ry)

    # Phase 3: Place residential zones
    # Zones on the right side of road: center at road_x+2 (so left edge at road_x+1=road)
    # Zones on the left side of wire: center at spine_x-2 (so right edge at spine_x-1)
    # Every 3 rows

    for dy in range(-12, 13, 3):
        zy = cy + dy
        if not in_bounds(road_x + 2, zy): continue
        if not in_bounds(spine_x - 2, zy): continue

        # Right side zone (center at road_x+2, zy)
        rx, ry = road_x + 2, zy
        if not has_res(rx, ry) and not np.any(res_mask[max(0,ry-2):ry+3, max(0,rx-2):rx+3]):
            # Check road access nearby
            road_nearby = any(has_road(road_x, zy + d) for d in range(-1, 2))
            if road_nearby:
                return (Tool.RESIDENTIAL, rx, ry)

        # Left side zone (center at spine_x-3, zy)
        lx, ly = spine_x - 3, zy
        if not has_res(lx, ly) and not np.any(res_mask[max(0,ly-2):ly+3, max(0,lx-2):lx+3]):
            # Check wire/road nearby for power
            wire_nearby = any(has_wire(spine_x, zy + d) for d in range(-1, 2))
            if wire_nearby:
                return (Tool.RESIDENTIAL, lx, ly)

    # Phase 4: Add commercial zones further out if residential is growing
    if obs.res_pop > 50:
        # Place commercial zones at road_x + 5
        for dy in range(-9, 10, 3):
            zy = cy + dy
            cx2 = road_x + 5
            if not in_bounds(cx2, zy): continue
            # Need road access: extend road
            if not has_road(road_x + 3, zy):
                if has_road(road_x + 3, zy - 1) or has_road(road_x + 3, zy + 1) or has_road(road_x, zy):
                    return (Tool.ROAD, road_x + 3, zy)
            if not np.any(res_mask[max(0,zy-2):zy+3, max(0,cx2-2):cx2+3]):
                if not np.any(com_mask[max(0,zy-2):zy+3, max(0,cx2-2):cx2+3]):
                    return (Tool.COMMERCIAL, cx2, zy)

    # Add industrial zones
    if obs.res_pop > 30:
        for dy in range(-9, 10, 6):
            zy = cy + dy
            ix = spine_x - 6
            if not in_bounds(ix, zy): continue
            # Need road: add horizontal road from spine area
            if not has_road(spine_x - 4, zy):
                return (Tool.ROAD, spine_x - 4, zy)
            if not np.any(ind_mask[max(0,zy-2):zy+3, max(0,ix-2):ix+3]):
                return (Tool.INDUSTRIAL, ix, zy)

    # Default: extend spine if anything missing
    # Re-check wire completeness
    for wy in wire_range:
        if not has_wire(spine_x, wy) and not has_plant(spine_x, wy):
            return (Tool.WIRE, spine_x, wy)

    return None

def act(obs, state):
    # Closed-loop policy: read the map each step and decide what to place next.
    # Strategy:
    # 1. Place coal power plant if none exists.
    # 2. Extend wire from power plant toward the spine column.
    # 3. Build a vertical road spine next to the wire column.
    # 4. Place residential zones adjacent to road, powered by wire.
    # 5. Add commercial/industrial zones for balance.

    cx, cy = WORLD_W // 2, WORLD_H // 2
    tile = obs.tile_map

    # Phase tracking: 0=power, 1=wire_spine, 2=road_spine, 3=zones, 4=extra
    phase = state.get("phase", 0)

    # --- Helper: check if a coord is in bounds ---
    def inbounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- PHASE 0: Ensure coal plant exists ---
    if phase == 0:
        pm = plant_mask(tile)
        if not pm.any():
            # Place coal plant at cx-4, cy (left of spine)
            state["phase"] = 0  # stay until placed
            return (Tool.COALPOWER, cx - 4, cy)
        else:
            state["phase"] = 1
            state["wire_row"] = cy - 12
            phase = 1

    # --- PHASE 1: Build vertical wire spine at column cx-1 from cy-12 to cy+12 ---
    if phase == 1:
        wrow = state.get("wire_row", cy - 12)
        target_col = cx - 1
        # Scan from wrow onward to find next unwired row
        for row in range(wrow, cy + 13):
            if not inbounds(target_col, row):
                continue
            wm = wire_mask(tile)
            pm = plant_mask(tile)
            if not wm[row, target_col] and not pm[row, target_col]:
                state["wire_row"] = row + 1
                return (Tool.WIRE, target_col, row)
        # Wire spine done
        state["phase"] = 2
        state["road_row"] = cy - 12
        phase = 2

    # --- PHASE 2: Build vertical road spine at column cx from cy-12 to cy+12 ---
    if phase == 2:
        rrow = state.get("road_row", cy - 12)
        target_col = cx
        for row in range(rrow, cy + 13):
            if not inbounds(target_col, row):
                continue
            rm = road_mask(tile)
            if not rm[row, target_col]:
                state["road_row"] = row + 1
                return (Tool.ROAD, target_col, row)
        state["phase"] = 3
        state["zone_index"] = 0
        phase = 3

    # --- PHASE 3: Place zones reactively adjacent to road/wire ---
    if phase == 3:
        zi = state.get("zone_index", 0)
        # Build zone positions: centers at cx-3 (left) and cx+3 (right)
        # every 3 rows from cy-12 to cy+12
        zone_rows = list(range(cy - 12, cy + 13, 3))
        # Alternate RES, COM, IND for diversity
        zone_types = [Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.INDUSTRIAL]
        zones = []
        for i, row in enumerate(zone_rows):
            # Left side: center at cx-3
            zones.append((zone_types[i % 3], cx - 3, row))
            # Right side: center at cx+3
            zones.append((zone_types[(i + 1) % 3], cx + 3, row))

        if zi < len(zones):
            tool, zx, zy = zones[zi]
            # Check if road spine is built enough - road col cx should have coverage
            rm = road_mask(tile)
            # Check if road exists near zone row
            road_nearby = False
            for dy in range(-1, 2):
                for dx in range(-1, 2):
                    nx, ny = cx + dx, zy + dy
                    if inbounds(nx, ny) and rm[ny, nx]:
                        road_nearby = True
                        break

            # Check if zone center already occupied by a zone
            res = res_mask(tile)
            com = com_mask(tile)
            ind = ind_mask(tile)
            already_zone = (res[zy, zx] or com[zy, zx] or ind[zy, zx]) if inbounds(zx, zy) else True

            if already_zone:
                state["zone_index"] = zi + 1
                return None

            if road_nearby or obs.step > len(zones) * 2:
                state["zone_index"] = zi + 1
                return (tool, zx, zy)
            else:
                # Wait for road
                return None
        else:
            state["phase"] = 4
            phase = 4

    # --- PHASE 4: Reactive expansion - extend road and add more zones ---
    if phase == 4:
        # Look for powered zones that lack adjacent road, or empty areas near road
        rm = road_mask(tile)
        em = empty_mask(tile)
        wm = wire_mask(tile)
        pm = plant_mask(tile)
        res = res_mask(tile)

        # Try to extend road horizontally from spine to serve more area
        ext_col = state.get("ext_col", cx + 1)
        ext_dir = state.get("ext_dir", 1)  # 1=right, -1=left
        ext_row = state.get("ext_row", cy)

        # Extend road right from cx
        if ext_col < cx + 8 and ext_dir == 1:
            if inbounds(ext_col, ext_row) and not rm[ext_row, ext_col]:
                state["ext_col"] = ext_col + 1
                return (Tool.ROAD, ext_col, ext_row)
            else:
                state["ext_col"] = ext_col + 1
                return None

        # Switch to left extension
        if ext_dir == 1 and ext_col >= cx + 8:
            state["ext_dir"] = -1
            state["ext_col"] = cx - 2
            return None

        if ext_dir == -1 and ext_col > cx - 9:
            if inbounds(ext_col, ext_row) and not rm[ext_row, ext_col]:
                state["ext_col"] = ext_col - 1
                return (Tool.ROAD, ext_col, ext_row)
            else:
                state["ext_col"] = ext_col - 1
                return None

        # Add more residential zones along extended road
        add_idx = state.get("add_idx", 0)
        extra_zones = []
        for col in [cx - 6, cx + 6]:
            for row in range(cy - 9, cy + 10, 3):
                extra_zones.append((Tool.RESIDENTIAL, col, row))

        if add_idx < len(extra_zones):
            tool, zx, zy = extra_zones[add_idx]
            state["add_idx"] = add_idx + 1
            if inbounds(zx, zy):
                return (tool, zx, zy)

        # Add wires to newly placed zones if not powered
        # Scan for res zones not near wire
        for y in range(max(0, cy - 15), min(WORLD_H, cy + 15)):
            for x in range(max(0, cx - 10), min(WORLD_W, cx + 10)):
                if res[y, x]:
                    # Check wire nearby
                    has_wire = False
                    for dy2 in range(-2, 3):
                        for dx2 in range(-2, 3):
                            nx, ny = x + dx2, y + dy2
                            if inbounds(nx, ny) and (wm[ny, nx] or pm[ny, nx]):
                                has_wire = True
                                break
                    if not has_wire:
                        # Place wire adjacent
                        return (Tool.WIRE, x - 1, y)

        return None

    return None

def act(obs, state):
    """
    Closed-loop policy: each step reads the current tile_map and decides
    what to place next based on observed state of power, roads, and zones.
    """
    tm = obs.tile_map
    cx, cy = WORLD_W // 2, WORLD_H // 2

    # Phase tracker: 0=plant, 1=wire_spine, 2=roads, 3=zones, 4=expand
    if "phase" not in state:
        state["phase"] = 0
        state["wire_dy"] = 0
        state["road_dy"] = 0
        state["zone_dy"] = -12
        state["zone_side"] = 0  # 0=left, 1=right

    phase = state["phase"]

    # --- Phase 0: Place coal power plant ---
    if phase == 0:
        # Check if plant already exists near cx-2, cy
        plants = plant_mask(tm)
        if not plants.any():
            state["phase"] = 1
            return (Tool.COALPOWER, cx - 2, cy)
        state["phase"] = 1

    # --- Phase 1: Extend wire spine vertically from plant to zones ---
    if phase == 1:
        dy = state["wire_dy"]
        # Wire connects from plant outward along column cx
        # Connect plant at cx-2,cy to spine at cx via wire at cx-1
        if dy == 0:
            # First lay horizontal wire from plant to spine
            state["wire_dy"] = 1
            return (Tool.WIRE, cx - 1, cy)

        # Check current wire coverage
        wire = wire_mask(tm)

        # Find the range we need to cover (-15 to +15)
        target_range = range(-15, 16)
        for ddy in target_range:
            ty = cy + ddy
            if 0 <= ty < WORLD_H:
                if not wire[ty, cx]:
                    state["wire_dy"] = ddy
                    return (Tool.WIRE, cx, ty)

        # All wires placed, move to roads
        state["phase"] = 2

    # --- Phase 2: Lay road spine adjacent to wire spine ---
    if phase == 2:
        road = road_mask(tm)
        wire = wire_mask(tm)

        # Road at cx+1 (right of wire) - vertical spine
        for ddy in range(-15, 16):
            ty = cy + ddy
            if 0 <= ty < WORLD_H:
                if not road[ty, cx + 1]:
                    return (Tool.ROAD, cx + 1, ty)

        # Road at cx-1 (left of wire) - vertical spine for left zones
        for ddy in range(-15, 16):
            ty = cy + ddy
            if 0 <= ty < WORLD_H:
                if not road[ty, cx - 1]:
                    return (Tool.ROAD, cx - 1, ty)

        # Horizontal road at cy
        for ddx in range(-8, 10):
            tx = cx + ddx
            if 0 <= tx < WORLD_W:
                if not road[cy, tx]:
                    return (Tool.ROAD, tx, cy)

        state["phase"] = 3

    # --- Phase 3: Place zones adjacent to roads, powered by wire spine ---
    if phase == 3:
        road = road_mask(tm)
        wire = wire_mask(tm)
        res = res_mask(tm)
        com = com_mask(tm)
        ind = ind_mask(tm)

        # Place zones at intervals along the spine
        # Right side: residential at cx+3 (road at cx+1 provides access)
        # Left side: residential at cx-3 (road at cx-1 provides access)

        dy = state["zone_dy"]
        side = state["zone_side"]

        if dy > 12:
            state["phase"] = 4
        else:
            ty = cy + dy
            if side == 0:
                tx = cx + 3
                # Check zone not already placed
                zone_exists = res[ty, tx] or com[ty, tx] or ind[ty, tx]
                state["zone_side"] = 1
                if not zone_exists and 3 <= tx < WORLD_W - 3 and 3 <= ty < WORLD_H - 3:
                    # Alternate res/com based on position
                    if dy % 6 == 0:
                        tool = Tool.COMMERCIAL
                    else:
                        tool = Tool.RESIDENTIAL
                    return (tool, tx, ty)
            else:
                tx = cx - 3
                zone_exists = res[ty, tx] or com[ty, tx] or ind[ty, tx]
                state["zone_side"] = 0
                state["zone_dy"] = dy + 3
                if not zone_exists and 3 <= tx < WORLD_W - 3 and 3 <= ty < WORLD_H - 3:
                    if dy % 9 == 0:
                        tool = Tool.INDUSTRIAL
                    elif dy % 6 == 0:
                        tool = Tool.COMMERCIAL
                    else:
                        tool = Tool.RESIDENTIAL
                    return (tool, tx, ty)

    # --- Phase 4: Closed-loop expansion based on observed map ---
    tm = obs.tile_map
    res = res_mask(tm)
    com = com_mask(tm)
    ind = ind_mask(tm)
    emp = empty_mask(tm)
    road = road_mask(tm)
    wire = wire_mask(tm)
    plants = plant_mask(tm)

    # Extend wire to any road tile that lacks adjacent wire (for power spread)
    # Find road tiles that are NOT adjacent to wire
    wire_nbr = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    wire_nbr[1:, :] |= wire[:-1, :]
    wire_nbr[:-1, :] |= wire[1:, :]
    wire_nbr[:, 1:] |= wire[:, :-1]
    wire_nbr[:, :-1] |= wire[:, 1:]

    # Find empty tiles adjacent to existing wire (to extend wire network)
    emp_near_wire = emp & wire_nbr

    # Find roads that are near zones but not near wire - add wire there
    zone_any = res | com | ind
    zone_nbr = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    zone_nbr[1:, :] |= zone_any[:-1, :]
    zone_nbr[:-1, :] |= zone_any[1:, :]
    zone_nbr[:, 1:] |= zone_any[:, :-1]
    zone_nbr[:, :-1] |= zone_any[:, 1:]

    road_nbr = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    road_nbr[1:, :] |= road[:-1, :]
    road_nbr[:-1, :] |= road[1:, :]
    road_nbr[:, 1:] |= road[:, :-1]
    road_nbr[:, :-1] |= road[:, 1:]

    # Priority 1: If powered zones are low, try to extend wire to unconnected zones
    if obs.powered_zones < (res | com | ind).sum() // 9:
        # Find zone tiles not near wire - place wire adjacent
        zone_no_power = zone_any & ~wire_nbr
        if zone_no_power.any():
            ys, xs = np.where(zone_no_power)
            # Pick closest to existing wire
            k = int(obs.step) % len(xs)
            zx, zy = int(xs[k]), int(ys[k])
            # Place wire adjacent to this zone toward the wire spine
            if zx > cx:
                return (Tool.WIRE, zx - 1, zy)
            else:
                return (Tool.WIRE, zx + 1, zy)

    # Priority 2: Find empty tiles adjacent to roads AND wire -> good zone spots
    good_zone = emp & road_nbr & wire_nbr
    if good_zone.any():
        ys, xs = np.where(good_zone)
        # Filter to reasonable map area
        mask = (xs >= 3) & (xs < WORLD_W - 3) & (ys >= 3) & (ys < WORLD_H - 3)
        xs, ys = xs[mask], ys[mask]
        if len(xs) > 0:
            k = int(tm.sum() + obs.step * 7) % len(xs)
            tx, ty = int(xs[k]), int(ys[k])
            # Pick zone type based on location
            if (tx + ty) % 7 == 0:
                tool = Tool.COMMERCIAL
            elif (tx + ty) % 11 == 0:
                tool = Tool.INDUSTRIAL
            else:
                tool = Tool.RESIDENTIAL
            return (tool, tx, ty)

    # Priority 3: Extend roads to reach more zone candidates
    # Find zone tiles not adjacent to road
    zone_no_road = zone_any & ~road_nbr
    if zone_no_road.any():
        ys, xs = np.where(zone_no_road)
        k = int(obs.step * 3) % len(xs)
        zx, zy = int(xs[k]), int(ys[k])
        # Place road toward existing road network
        if road_nbr[zy, min(zx + 1, WORLD_W - 1)]:
            return (Tool.ROAD, zx + 1, zy)
        elif road_nbr[zy, max(zx - 1, 0)]:
            return (Tool.ROAD, zx - 1, zy)
        elif zy + 1 < WORLD_H and road_nbr[min(zy + 1, WORLD_H - 1), zx]:
            return (Tool.ROAD, zx, zy + 1)
        elif zy > 0 and road_nbr[max(zy - 1, 0), zx]:
            return (Tool.ROAD, zx, zy - 1)

    # Priority 4: Expand road/wire outward from existing spine for new zone rows
    # Find empty tiles adjacent to road
    emp_near_road = emp & road_nbr
    if emp_near_road.any():
        ys, xs = np.where(emp_near_road)
        # Choose near map center
        dist = np.abs(xs - cx) + np.abs(ys - cy)
        idx = np.argmin(dist)
        tx, ty = int(xs[idx]), int(ys[idx])
        # Lay road to extend network
        return (Tool.ROAD, tx, ty)

    return None

def act(obs, state):
    if "plan" not in state:
        plan = []

        # Central cluster: power plant at (60, 50), zones spread around it
        cx, cy = 60, 50

        # Coal power plant - place it away from zones
        plan.append((Tool.COALPOWER, cx, cy - 10))

        # Wire from plant down to main horizontal spine
        for dy in range(-9, 1):
            plan.append((Tool.WIRE, cx, cy + dy))

        # Main horizontal road spine at cy
        for dx in range(-15, 16):
            plan.append((Tool.ROAD, cx + dx, cy))

        # Also wire the spine so all zones get power
        for dx in range(-15, 16):
            plan.append((Tool.WIRE, cx + dx, cy - 1))

        # Vertical roads branching north and south from spine
        for dx in range(-12, 13, 6):
            for dy in range(-9, 10):
                plan.append((Tool.ROAD, cx + dx, cy + dy))

        # Place zones in a grid pattern
        # North of spine: Residential
        for dx in range(-12, 13, 6):
            for dy in range(-9, 0, 3):
                plan.append((Tool.RESIDENTIAL, cx + dx, cy + dy))

        # South of spine: Commercial and Industrial alternating
        for dx in range(-12, 13, 6):
            for i, dy in enumerate(range(3, 10, 3)):
                if i % 2 == 0:
                    plan.append((Tool.COMMERCIAL, cx + dx, cy + dy))
                else:
                    plan.append((Tool.INDUSTRIAL, cx + dx, cy + dy))

        # Second power plant for more coverage
        plan.append((Tool.COALPOWER, cx - 20, cy - 10))

        # Wire from second plant to spine
        for dy in range(-9, 1):
            plan.append((Tool.WIRE, cx - 20, cy + dy))
        for dx in range(-19, -14):
            plan.append((Tool.WIRE, cx + dx, cy - 1))

        # Services
        plan.append((Tool.FIRESTATION, cx + 15, cy - 6))
        plan.append((Tool.POLICESTATION, cx - 15, cy - 6))
        plan.append((Tool.FIRESTATION, cx + 15, cy + 6))
        plan.append((Tool.POLICESTATION, cx - 15, cy + 6))

        # Second cluster to the right
        cx2, cy2 = 95, 35
        plan.append((Tool.COALPOWER, cx2, cy2 - 8))
        for dy in range(-7, 1):
            plan.append((Tool.WIRE, cx2, cy2 + dy))
        for dx in range(-8, 9):
            plan.append((Tool.ROAD, cx2 + dx, cy2))
            plan.append((Tool.WIRE, cx2 + dx, cy2 - 1))
        for dx in range(-6, 7, 6):
            for dy in range(-6, 7):
                plan.append((Tool.ROAD, cx2 + dx, cy2 + dy))
        for dx in range(-6, 7, 6):
            for dy in range(-6, 1, 3):
                plan.append((Tool.RESIDENTIAL, cx2 + dx, cy2 + dy))
            for dy in range(3, 7, 3):
                plan.append((Tool.COMMERCIAL, cx2 + dx, cy2 + dy))

        state["plan"] = plan
        state["i"] = 0

    i = state["i"]
    plan = state["plan"]

    if i >= len(plan):
        return None

    state["i"] = i + 1
    tool, x, y = plan[i]
    x = max(0, min(WORLD_W - 1, x))
    y = max(0, min(WORLD_H - 1, y))
    return (tool, x, y)

def act(obs, state):
    """
    Closed-loop policy: each step reads the current map and decides the next
    placement based on what's actually there.

    Strategy:
    1. If no power plant exists, place one near center.
    2. Extend wire from plant toward zones/spine.
    3. Lay road spine adjacent to wire.
    4. Place zones adjacent to roads where power is nearby.
    5. Add more infrastructure reactively as city grows.
    """
    tm = obs.tile_map
    cx, cy = WORLD_W // 2, WORLD_H // 2

    emp = empty_mask(tm)
    wire = wire_mask(tm)
    road = road_mask(tm)
    plant = plant_mask(tm)
    res = res_mask(tm)
    com = com_mask(tm)
    ind = ind_mask(tm)

    # Helper: check if any cell in a 3x3 block is non-empty
    def region_empty(cx_, cy_):
        for dy in range(-1, 2):
            for dx in range(-1, 2):
                nx, ny = cx_ + dx, cy_ + dy
                if 0 <= nx < WORLD_W and 0 <= ny < WORLD_H:
                    if not emp[ny, nx]:
                        return False
        return True

    # Step 1: Ensure we have a coal power plant
    plant_coords = np.argwhere(plant)
    if len(plant_coords) == 0:
        # Place coal plant at a fixed offset from center
        return (Tool.COALPOWER, cx - 5, cy)

    # Plant location (use first found)
    py_p, px_p = plant_coords[0]

    # Step 2: Build wire spine from plant rightward to cx (spine column)
    # Spine: wire at column cx, road at column cx+1, road at column cx-1
    spine_x = cx

    # Connect plant to spine with wire
    wire_coords = np.argwhere(wire)

    # Check if spine column has wire at plant's row
    if not wire[py_p, spine_x]:
        # Lay wire from plant to spine horizontally
        # Find rightmost wire connected near plant row
        row = py_p
        # Find any wire in this row
        row_wire = np.where(wire[row, :])[0]
        if len(row_wire) == 0:
            # Start from plant+1
            wx = px_p + 4  # just right of plant (plant is 4 wide)
            if wx < spine_x:
                return (Tool.WIRE, wx, row)
            else:
                return (Tool.WIRE, spine_x, row)
        else:
            rightmost = row_wire.max()
            if rightmost < spine_x:
                return (Tool.WIRE, rightmost + 1, row)

    # Step 3: Extend wire spine vertically from plant row
    # Target: wire at spine_x from cy-15 to cy+15
    target_ys = list(range(cy - 15, cy + 16))
    for ty in target_ys:
        if 0 <= ty < WORLD_H and not wire[ty, spine_x]:
            # Check if adjacent wire exists (connectivity)
            has_adj = False
            for dy in [-1, 1]:
                ny = ty + dy
                if 0 <= ny < WORLD_H and wire[ny, spine_x]:
                    has_adj = True
                    break
            if has_adj:
                return (Tool.WIRE, spine_x, ty)

    # Step 4: Lay road at spine_x+1 and spine_x-1 (parallel to wire)
    road_x_right = spine_x + 1
    road_x_left = spine_x - 1

    for ty in target_ys:
        if 0 <= ty < WORLD_H:
            if not road[ty, road_x_right] and emp[ty, road_x_right]:
                return (Tool.ROAD, road_x_right, ty)
            if not road[ty, road_x_left] and emp[ty, road_x_left]:
                return (Tool.ROAD, road_x_left, ty)

    # Step 5: Add horizontal roads every 3 rows for zone access
    for dy_off in range(-12, 13, 3):
        ty = cy + dy_off
        if 0 <= ty < WORLD_H:
            for dx in range(-6, 8):
                tx = spine_x + dx
                if 0 <= tx < WORLD_W and not road[ty, tx] and emp[ty, tx]:
                    return (Tool.ROAD, tx, ty)

    # Step 6: Place zones adjacent to roads, powered by nearby wire
    # Find tiles adjacent to roads
    adj_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    adj_road[1:, :] |= road[:-1, :]
    adj_road[:-1, :] |= road[1:, :]
    adj_road[:, 1:] |= road[:, :-1]
    adj_road[:, :-1] |= road[:, 1:]

    # Find tiles adjacent to wire or plant (powered area)
    adj_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    power_src = wire | plant
    for r in range(1, 4):  # zones 3x3 so check wider neighborhood
        shifted = np.zeros_like(power_src)
        shifted[r:, :] |= power_src[:-r, :]
        shifted[:-r, :] |= power_src[r:, :]
        shifted[:, r:] |= power_src[:, :-r]
        shifted[:, :-r] |= power_src[:, r:]
        adj_power |= shifted

    # Candidate zone centers: empty, near road, near power
    zone_placed = res | com | ind

    def try_place_zone(tool, offset_x, offset_y_range):
        for dy_off in offset_y_range:
            ty = cy + dy_off
            tx = spine_x + offset_x
            if 0 <= tx < WORLD_W and 0 <= ty < WORLD_H:
                if emp[ty, tx] and adj_road[ty, tx] and adj_power[ty, tx]:
                    return (tool, tx, ty)
        return None

    # Residential right side
    for dy_off in range(-12, 13, 3):
        ty = cy + dy_off
        for side, ox in [(1, 3), (-1, -3)]:
            tx = spine_x + ox * side if side == 1 else spine_x + ox
            tx = spine_x + (3 if side == 1 else -3)
            if 0 <= tx < WORLD_W and 0 <= ty < WORLD_H:
                if emp[ty, tx] and adj_road[ty, tx]:
                    return (Tool.RESIDENTIAL, tx, ty)

    # Commercial further out
    for dy_off in range(-6, 7, 6):
        ty = cy + dy_off
        for ox in [6, -6]:
            tx = spine_x + ox
            if 0 <= tx < WORLD_W and 0 <= ty < WORLD_H:
                if emp[ty, tx] and adj_road[ty, tx]:
                    return (Tool.COMMERCIAL, tx, ty)

    # Industrial
    for dy_off in range(-9, 10, 9):
        ty = cy + dy_off
        tx = spine_x - 9
        if 0 <= tx < WORLD_W and 0 <= ty < WORLD_H:
            if emp[ty, tx] and adj_road[ty, tx]:
                return (Tool.INDUSTRIAL, tx, ty)

    # Fallback: find any empty tile near road and place residential
    cands = np.argwhere(emp & adj_road & adj_power)
    if len(cands) > 0:
        idx = obs.step % len(cands)
        cy2, cx2 = cands[idx]
        tool = [Tool.RESIDENTIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.RESIDENTIAL][obs.step % 4]
        return (tool, int(cx2), int(cy2))

    return None

def build_plan():
    plan = []

    # === Central cluster (from Parent B's successful approach) ===
    cx, cy = WORLD_W // 2, WORLD_H // 2  # 60, 50

    # Coal power plant - placed so wire column connects naturally
    plan.append((Tool.COALPOWER, cx - 2, cy))

    # Vertical wire spine + road spine for central cluster
    for dy in range(-12, 13):
        plan.append((Tool.WIRE, cx, cy + dy))
        plan.append((Tool.ROAD, cx + 1, cy + dy))

    # Horizontal connector roads every 3 rows for better road access
    for dy in range(-12, 13, 3):
        for dx in range(-5, 6):
            if dx != 0:  # don't overwrite wire spine
                plan.append((Tool.ROAD, cx + dx, cy + dy))

    # Mixed zoning: residential left, commercial/industrial right (from Parent A)
    for i, dy in enumerate(range(-12, 13, 3)):
        # Left side: residential
        plan.append((Tool.RESIDENTIAL, cx - 3, cy + dy))
        # Right side: alternate commercial and industrial for balance
        if i % 3 == 0:
            plan.append((Tool.COMMERCIAL, cx + 4, cy + dy))
        elif i % 3 == 1:
            plan.append((Tool.INDUSTRIAL, cx + 4, cy + dy))
        else:
            plan.append((Tool.RESIDENTIAL, cx + 4, cy + dy))

    # Services for central cluster
    plan.append((Tool.FIRESTATION, cx - 3, cy - 15))
    plan.append((Tool.POLICESTATION, cx - 3, cy + 15))

    # === Second cluster (from Parent A's dual-neighborhood idea) ===
    cx2, cy2 = 25, 50

    # Second coal plant
    plan.append((Tool.COALPOWER, cx2 - 2, cy2))

    # Wire + road spine for second cluster
    for dy in range(-9, 10):
        plan.append((Tool.WIRE, cx2, cy2 + dy))
        plan.append((Tool.ROAD, cx2 + 1, cy2 + dy))

    # Horizontal roads every 3 rows
    for dy in range(-9, 10, 3):
        for dx in range(-4, 5):
            if dx != 0:
                plan.append((Tool.ROAD, cx2 + dx, cy2 + dy))

    # Zones for second cluster
    for i, dy in enumerate(range(-9, 10, 3)):
        plan.append((Tool.RESIDENTIAL, cx2 - 3, cy2 + dy))
        if i % 2 == 0:
            plan.append((Tool.COMMERCIAL, cx2 + 4, cy2 + dy))
        else:
            plan.append((Tool.INDUSTRIAL, cx2 + 4, cy2 + dy))

    plan.append((Tool.FIRESTATION, cx2, cy2 - 12))

    # === Third cluster (right side) ===
    cx3, cy3 = 95, 50

    plan.append((Tool.COALPOWER, cx3 - 2, cy3))

    for dy in range(-9, 10):
        plan.append((Tool.WIRE, cx3, cy3 + dy))
        plan.append((Tool.ROAD, cx3 + 1, cy3 + dy))

    for dy in range(-9, 10, 3):
        for dx in range(-4, 5):
            if dx != 0:
                plan.append((Tool.ROAD, cx3 + dx, cy3 + dy))

    for i, dy in enumerate(range(-9, 10, 3)):
        plan.append((Tool.RESIDENTIAL, cx3 - 3, cy3 + dy))
        if i % 2 == 0:
            plan.append((Tool.COMMERCIAL, cx3 + 4, cy3 + dy))
        else:
            plan.append((Tool.INDUSTRIAL, cx3 + 4, cy3 + dy))

    plan.append((Tool.FIRESTATION, cx3, cy3 - 12))

    return plan


def act(obs, state):
    if "plan" not in state:
        state["plan"] = build_plan()
        state["i"] = 0

    i = state["i"]
    plan = state["plan"]

    if i >= len(plan):
        return None

    state["i"] = i + 1
    tool, x, y = plan[i]
    # Clamp to valid range
    x = max(0, min(WORLD_W - 1, x))
    y = max(0, min(WORLD_H - 1, y))
    return (tool, x, y)

def act(obs, state):
    # Closed-loop policy: each step reads the map and decides next placement
    # based on what's already there.

    tile_map = obs.tile_map
    step = obs.step

    # Phase tracking
    if "phase" not in state:
        state["phase"] = "power_plant"
        state["road_head"] = None
        state["wire_head"] = None
        state["zone_count"] = 0
        state["last_road_y"] = None

    # Constants for our cluster center
    CX, CY = 40, 50  # center of our main cluster

    # --- Helper: check if coord is valid ---
    def valid(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Phase 1: Place coal power plant if none exists ---
    plants = plant_mask(tile_map)
    if not plants.any():
        # Place coal power plant at a fixed spot
        px, py = CX - 8, CY
        return (Tool.COALPOWER, px, py)

    # Find plant location
    plant_ys, plant_xs = np.where(plants)
    px, py = int(plant_xs[0]), int(plant_ys[0])

    # --- Phase 2: Wire from plant rightward to CX ---
    # Check if wire reaches CX
    wires = wire_mask(tile_map)
    roads = road_mask(tile_map)

    # Wire from plant to spine column CX
    # Wire should go from px+2 (just right of plant) to CX
    wire_connected = False
    for wx in range(px + 2, CX + 1):
        if valid(wx, py):
            if wires[py, wx]:
                continue
            else:
                # Place wire here
                return (Tool.WIRE, wx, py)
    wire_connected = True

    # --- Phase 3: Vertical wire spine at CX ---
    # Extend wire spine from CY-12 to CY+12 at column CX
    spine_top = CY - 12
    spine_bot = CY + 12

    for wy in range(spine_top, spine_bot + 1):
        if valid(CX, wy) and not wires[wy, CX] and not roads[wy, CX]:
            # Check if tile at CX,wy is the power plant itself
            if plants[wy, CX]:
                continue
            return (Tool.WIRE, CX, wy)

    # --- Phase 4: Road spine at CX+1 ---
    road_col = CX + 1
    for ry in range(spine_top, spine_bot + 1):
        if valid(road_col, ry) and not roads[ry, road_col]:
            return (Tool.ROAD, road_col, ry)

    # --- Phase 5: Horizontal roads every 3 rows for zone access ---
    # Road rows at spine_top, spine_top+3, ...
    for row_offset in range(0, spine_bot - spine_top + 1, 3):
        ry = spine_top + row_offset
        # Horizontal roads from CX+1 to CX+5 (right side)
        for rx in range(CX + 1, CX + 6):
            if valid(rx, ry) and not roads[ry, rx]:
                return (Tool.ROAD, rx, ry)
        # Horizontal roads from CX-1 to CX-5 (left side)
        for rx in range(CX - 1, CX - 6, -1):
            if valid(rx, ry) and not roads[ry, rx]:
                return (Tool.ROAD, rx, ry)

    # --- Phase 6: Place zones adjacent to roads ---
    # Scan for road tiles and place zones nearby if empty
    res = res_mask(tile_map)
    com = com_mask(tile_map)
    ind = ind_mask(tile_map)
    empty = empty_mask(tile_map)

    # Count existing zones
    n_res = res.sum()
    n_com = com.sum()
    n_ind = ind.sum()
    total_zones = n_res + n_com + n_ind

    # Place zones: for each road-adjacent empty spot, place a zone
    # Strategy: zones at centers of 3x3 areas, placed at road rows +/- 2
    zone_placed = False
    for row_offset in range(0, spine_bot - spine_top + 1, 3):
        ry = spine_top + row_offset

        # Right side zones at (CX+4, ry) -- center of 3x3 touching road at CX+1..CX+5
        zx_r = CX + 4
        if valid(zx_r, ry):
            center_empty = empty[ry, zx_r]
            if center_empty:
                # Decide zone type based on row
                idx = row_offset // 3
                if idx % 3 == 0:
                    return (Tool.RESIDENTIAL, zx_r, ry)
                elif idx % 3 == 1:
                    return (Tool.COMMERCIAL, zx_r, ry)
                else:
                    return (Tool.INDUSTRIAL, zx_r, ry)

        # Left side zones at (CX-4, ry)
        zx_l = CX - 4
        if valid(zx_l, ry):
            center_empty = empty[ry, zx_l]
            if center_empty:
                idx = row_offset // 3
                if idx % 3 == 0:
                    return (Tool.RESIDENTIAL, zx_l, ry)
                elif idx % 3 == 1:
                    return (Tool.COMMERCIAL, zx_l, ry)
                else:
                    return (Tool.INDUSTRIAL, zx_l, ry)

    # --- Phase 7: Add services if zones exist ---
    if total_zones > 5:
        # Fire station
        fs_x, fs_y = CX + 7, CY
        if valid(fs_x, fs_y) and empty[fs_y, fs_x]:
            return (Tool.FIRESTATION, fs_x, fs_y)
        # Police station
        ps_x, ps_y = CX - 7, CY
        if valid(ps_x, ps_y) and empty[ps_y, ps_x]:
            return (Tool.POLICESTATION, ps_x, ps_y)

    # --- Phase 8: Expand with a second cluster if population growing ---
    if obs.city_pop > 100 or (total_zones > 10 and step > obs.n_steps // 2):
        # Second cluster to the right
        CX2, CY2 = 80, 50
        # Wire bridge from CX to CX2
        for wx in range(CX + 1, CX2 + 1):
            if valid(wx, CY) and not wires[CY, wx] and not roads[CY, wx]:
                # Don't overwrite zones
                if not (res[CY, wx] or com[CY, wx] or ind[CY, wx]):
                    return (Tool.WIRE, wx, CY)

        # Vertical spine at CX2
        for wy in range(CY - 12, CY + 13):
            if valid(CX2, wy) and not wires[wy, CX2] and not roads[wy, CX2]:
                return (Tool.WIRE, CX2, wy)

        # Road at CX2-1
        for ry in range(CY - 12, CY + 13):
            if valid(CX2 - 1, ry) and not roads[ry, CX2 - 1]:
                return (Tool.ROAD, CX2 - 1, ry)

        # Zones at CX2+3
        for row_offset in range(0, 25, 3):
            ry = CY - 12 + row_offset
            zx = CX2 + 3
            if valid(zx, ry) and empty[ry, zx]:
                idx = row_offset // 3
                if idx % 3 == 0:
                    return (Tool.RESIDENTIAL, zx, ry)
                elif idx % 3 == 1:
                    return (Tool.COMMERCIAL, zx, ry)
                else:
                    return (Tool.INDUSTRIAL, zx, ry)

    # Nothing left to do
    return None

def act(obs, state):
    # Closed-loop policy: read map each step and decide next action reactively.
    # Strategy: build a single compact cluster around a central spine.
    # Phase 0: place coal power plant
    # Phase 1: extend wire from plant toward spine
    # Phase 2: build vertical road spine
    # Phase 3: place zones adjacent to road spine (with wire nearby)
    # Phase 4: expand wire network to reach more zones
    # Phase 5: add services

    tile_map = obs.tile_map
    step = obs.step
    funds = obs.funds

    # Central spine location
    CX, CY = 60, 50  # center of map

    # Initialize state
    if "phase" not in state:
        state["phase"] = 0
        state["spine_built"] = 0  # how many spine tiles placed
        state["zone_row"] = 0     # which zone row we're on
        state["wire_extend"] = 0  # wire extension index

    phase = state["phase"]

    # Helper: check if a tile is empty
    def is_empty(x, y):
        if x < 0 or x >= WORLD_W or y < 0 or y >= WORLD_H:
            return False
        return empty_mask[y, x]

    def has_road(x, y):
        if x < 0 or x >= WORLD_W or y < 0 or y >= WORLD_H:
            return False
        return road_mask[y, x]

    def has_wire(x, y):
        if x < 0 or x >= WORLD_W or y < 0 or y >= WORLD_H:
            return False
        return wire_mask[y, x]

    def has_plant(x, y):
        if x < 0 or x >= WORLD_W or y < 0 or y >= WORLD_H:
            return False
        return plant_mask[y, x]

    # Phase 0: Place coal power plant at CX-8, CY
    if phase == 0:
        px, py = CX - 8, CY
        # Power plant is 3x3, check center
        state["phase"] = 1
        return (Tool.COALPOWER, px, py)

    # Phase 1: Lay wire from plant to spine road column
    # Plant center at CX-8, CY. Wire from CX-7 to CX-1 at row CY
    if phase == 1:
        # Find leftmost wire gap between plant and spine
        plant_x = CX - 8
        # Wire should run from plant_x+2 (right edge of plant) to CX-1
        for wx in range(plant_x + 2, CX):
            if not has_wire(wx, CY) and not has_plant(wx, CY):
                return (Tool.WIRE, wx, CY)
        # All wire placed, move to phase 2
        state["phase"] = 2
        state["spine_y_start"] = CY - 15
        state["spine_y_end"] = CY + 15
        state["spine_cur"] = CY - 15

    # Phase 2: Build vertical road spine at CX, from CY-15 to CY+15
    # Also lay wire alongside at CX-1
    if phase == 2:
        cur = state["spine_cur"]
        end = state["spine_y_end"]
        if cur <= end:
            state["spine_cur"] = cur + 1
            # Place road at CX, wire at CX-1 for this row
            # Alternate: place road first, then wire
            if not has_road(CX, cur):
                return (Tool.ROAD, CX, cur)
            if not has_wire(CX - 1, cur):
                return (Tool.WIRE, CX - 1, cur)
        state["phase"] = 3
        state["zone_idx"] = 0

    # Phase 3: Place zones adjacent to road spine
    # Zones on left side (CX-4) and right side (CX+4) at each 3-row interval
    if phase == 3:
        zone_positions = []
        for dy in range(-15, 16, 3):
            zy = CY + dy
            # Left: residential
            zone_positions.append((Tool.RESIDENTIAL, CX - 4, zy))
            # Right: alternate commercial/industrial
            if (dy // 3) % 2 == 0:
                zone_positions.append((Tool.COMMERCIAL, CX + 4, zy))
            else:
                zone_positions.append((Tool.INDUSTRIAL, CX + 4, zy))

        idx = state["zone_idx"]
        if idx < len(zone_positions):
            state["zone_idx"] = idx + 1
            tool, zx, zy = zone_positions[idx]
            # Only place if we have road nearby (reactive check)
            # Check if road exists within 2 tiles horizontally
            road_nearby = any(has_road(zx + dx, zy) for dx in range(-3, 4))
            road_nearby = road_nearby or any(has_road(zx, zy + dy2) for dy2 in range(-3, 4))
            # Place road connector if missing
            if not road_nearby:
                # Place a short horizontal road from spine to zone
                if zx < CX:
                    return (Tool.ROAD, zx + 1, zy)
                else:
                    return (Tool.ROAD, zx - 1, zy)
            return (tool, zx, zy)
        state["phase"] = 4
        state["wire_ext_x"] = CX + 1

    # Phase 4: Extend wire to right side zones (wire at CX+1 through CX+3 at CY)
    if phase == 4:
        # Wire spine horizontally to reach right-side zones
        for wx in range(CX + 1, CX + 5):
            if not has_wire(wx, CY):
                return (Tool.WIRE, wx, CY)
        # Vertical wire on right side at CX+3
        for wy in range(CY - 15, CY + 16):
            if not has_wire(CX + 3, wy) and not has_plant(CX + 3, wy):
                return (Tool.WIRE, CX + 3, wy)
        # Also add horizontal roads connecting zones to spine
        state["phase"] = 5
        state["road_conn_idx"] = 0

    # Phase 5: Add horizontal road connections and services
    if phase == 5:
        conn_idx = state.get("road_conn_idx", 0)
        connections = []
        for dy in range(-15, 16, 3):
            zy = CY + dy
            # Left connection: road from CX-1 to CX-3 at zy
            for dx in range(1, 4):
                connections.append((Tool.ROAD, CX - dx, zy))
            # Right connection: road from CX+1 to CX+3 at zy
            for dx in range(1, 4):
                connections.append((Tool.ROAD, CX + dx, zy))

        # Services
        connections.append((Tool.FIRESTATION, CX, CY - 18))
        connections.append((Tool.POLICESTATION, CX, CY + 18))

        # Reactive: only place if not already there
        placed = False
        while conn_idx < len(connections):
            tool, cx2, cy2 = connections[conn_idx]
            conn_idx += 1
            state["road_conn_idx"] = conn_idx
            # Check if already road/wire/zone there
            if tool == Tool.ROAD and not has_road(cx2, cy2):
                return (Tool.ROAD, cx2, cy2)
            elif tool in (Tool.FIRESTATION, Tool.POLICESTATION):
                return (tool, cx2, cy2)
            elif tool == Tool.ROAD:
                continue  # already has road, skip
        state["phase"] = 6

    # Phase 6: Reactive expansion - scan for unpowered/unconnected zones
    if phase == 6:
        # Find zones that might need more wire or road
        # Look for residential zones that are far from wire
        res = np.argwhere(res_mask)  # shape (N, 2) as (row, col)
        wire = np.argwhere(wire_mask)

        if len(res) > 0 and len(wire) > 0:
            # Find the residential zone farthest from any wire
            # Simple: for each res zone, check if wire within 3 tiles
            for ry, rx in res:
                wire_near = False
                for wy2 in range(max(0, ry-3), min(WORLD_H, ry+4)):
                    for wx2 in range(max(0, rx-3), min(WORLD_W, rx+4)):
                        if wire_mask[wy2, wx2]:
                            wire_near = True
                            break
                    if wire_near:
                        break
                if not wire_near:
                    # Place wire adjacent to this zone
                    return (Tool.WIRE, rx, ry - 1)

        # Add more zones if funds allow - expand spine upward/downward
        # Find the topmost and bottommost road on spine
        spine_roads = [(y2, CX) for y2 in range(WORLD_H) if has_road(CX, y2)]
        if spine_roads:
            top_y = min(r[0] for r in spine_roads)
            bot_y = max(r[0] for r in spine_roads)
            # Try to extend spine
            if top_y > 5 and not has_road(CX, top_y - 1):
                return (Tool.ROAD, CX, top_y - 1)
            if bot_y < 95 and not has_road(CX, bot_y + 1):
                return (Tool.ROAD, CX, bot_y + 1)

        # Add extra residential zones reactively based on pop
        if obs.city_pop < 1000:
            # Find empty spots near road for new zones
            for y2 in range(CY - 20, CY + 21, 3):
