def act(obs, state):
    tm = obs.tile_map
    emp = empty_mask(tm)
    res = res_mask(tm)
    rds = road_mask(tm)
    wrs = wire_mask(tm)
    plt = plant_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    # Phase 0: Place coal power plant if none exists
    if not np.any(plt):
        return (Tool.COALPOWER, cx, cy)

    # Find power plant location
    plant_ys, plant_xs = np.where(plt)
    px, py = int(plant_xs[0]), int(plant_ys[0])

    # Phase 1: Ensure a vertical wire spine exists (column cx+2 from py-12 to py+12)
    spine_x = cx + 2
    for dy in range(-12, 13):
        ny = py + dy
        if 0 <= ny < WORLD_H and 0 <= spine_x < WORLD_W:
            if not wrs[ny, spine_x] and not plt[ny, spine_x]:
                # Check if we need wire here (connect plant to spine)
                return (Tool.WIRE, spine_x, ny)

    # Phase 2: Connect plant to spine with horizontal wire
    for dx in range(1, spine_x - px + 1):
        wx = px + dx
        if 0 <= wx < WORLD_W:
            if not wrs[py, wx] and not plt[py, wx] and wx != spine_x:
                return (Tool.WIRE, wx, py)

    # Phase 3: Ensure road column exists at spine_x+1
    road_x = spine_x + 1
    for dy in range(-12, 13):
        ny = py + dy
        if 0 <= ny < WORLD_H and 0 <= road_x < WORLD_W:
            if not rds[ny, road_x]:
                return (Tool.ROAD, road_x, ny)

    # Phase 4: Reactively place zones and extend infrastructure
    # Find all powered wires (adjacent to plant or other wires connected to plant)
    # Use road positions to decide where to place residential zones
    # Place residential zones to the right of road column
    res_start_x = road_x + 2  # zones at road_x+2 (center of 3x3)

    # Check where residential zones can be placed (need road access and power nearby)
    # Scan for empty spots near road
    best = None
    for dy in range(-11, 12, 3):
        ny = py + dy
        # Try different columns for zones
        for col_offset in range(0, 4):
            zx = res_start_x + col_offset * 4
            zy = ny
            if 0 <= zx < WORLD_W - 1 and 1 <= zy < WORLD_H - 1:
                # Check if area is mostly empty
                region = tm[max(0,zy-1):zy+2, max(0,zx-1):zx+2]
                e_region = emp[max(0,zy-1):zy+2, max(0,zx-1):zx+2]
                if e_region.sum() >= 6:  # mostly empty
                    if not np.any(res[max(0,zy-1):zy+2, max(0,zx-1):zx+2]):
                        # Need wire to reach this zone for power
                        # Place wire between spine and zone if needed
                        # First check if there's a wire branch at this row
                        wire_row_exists = np.any(wrs[zy, spine_x:zx])
                        if not wire_row_exists:
                            # Place horizontal wire from spine to zone
                            for wx in range(spine_x + 1, zx - 1):
                                if 0 <= wx < WORLD_W and not wrs[zy, wx] and not plt[zy, wx]:
                                    return (Tool.WIRE, wx, zy)
                        # Also need road connection
                        road_exists = np.any(rds[zy, road_x:zx+2])
                        if not road_exists:
                            for rx in range(road_x, zx - 1):
                                if 0 <= rx < WORLD_W and not rds[zy, rx]:
                                    return (Tool.ROAD, rx, zy)
                        if best is None:
                            best = (Tool.RESIDENTIAL, zx, zy)

    if best is not None:
        return best

    # Phase 5: Closed-loop expansion - find existing residential and expand near road
    # Find candidates: empty cells adjacent to existing residential zones
    nbr = np.zeros_like(emp)
    nbr[1:, :] |= res[:-1, :]
    nbr[:-1, :] |= res[1:, :]
    nbr[:, 1:] |= res[:, :-1]
    nbr[:, :-1] |= res[:, 1:]
    cand = emp & nbr

    # Prefer candidates near roads
    road_nbr = np.zeros_like(emp)
    road_nbr[1:, :] |= rds[:-1, :]
    road_nbr[:-1, :] |= rds[1:, :]
    road_nbr[:, 1:] |= rds[:, :-1]
    road_nbr[:, :-1] |= rds[:, 1:]

    good = cand & road_nbr
    ys, xs = np.where(good)
    if len(xs) > 0:
        k = int(tm.sum()) % len(xs)
        return (Tool.RESIDENTIAL, int(xs[k]), int(ys[k]))

    # Fallback: any candidate near existing res
    ys, xs = np.where(cand)
    if len(xs) > 0:
        k = int(tm.sum()) % len(xs)
        return (Tool.RESIDENTIAL, int(xs[k]), int(ys[k]))

    # Add commercial/industrial mix if lots of residential already
    if obs.res_pop > 50:
        com_cand = emp & road_nbr
        cys, cxs = np.where(com_cand)
        if len(cxs) > 0:
            k = (int(tm.sum()) + 7) % len(cxs)
            tool = Tool.COMMERCIAL if obs.com_pop < obs.res_pop // 3 else Tool.INDUSTRIAL
            return (tool, int(cxs[k]), int(cys[k]))

    return None

def act(obs, state):
