def act(obs, state):
    """
    Closed-loop policy: each step reads the current map and decides
    what to place next based on observed state.

    Strategy:
    1. If no power plant exists, place one
    2. Extend wires from power plant toward target area
    3. Build roads in a grid pattern
    4. Place zones adjacent to roads that have power nearby
    """
    tm = obs.tile_map
    emp = empty_mask(tm)
    roads = road_mask(tm)
    wires = wire_mask(tm)
    plants = plant_mask(tm)
    res = res_mask(tm)
    com = com_mask(tm)
    ind = ind_mask(tm)

    # Target center for our city cluster
    CX, CY = 60, 50

    # --- Phase 0: Place coal power plant if none exists ---
    if not plants.any():
        # Place plant at fixed offset from center
        px, py = CX - 15, CY - 10
        px = max(2, min(WORLD_W - 3, px))
        py = max(2, min(WORLD_H - 3, py))
        return (Tool.COALPOWER, px, py)

    # Find power plant location (center of plant tile cluster)
    plant_ys, plant_xs = np.where(plants)
    plant_x = int(plant_xs.mean())
    plant_y = int(plant_ys.mean())

    # --- Phase 1: Extend wires from plant toward city center ---
    # We need wires to reach the road grid area
    # Target wire endpoint: (CX-8, CY) - just left of city center
    wire_target_x = CX - 8
    wire_target_y = CY

    powered = wires | plants

    # Check if wire already reaches target area
    wire_reached = powered[max(0, wire_target_y-2):wire_target_y+3,
                           max(0, wire_target_x-2):wire_target_x+3].any()

    if not wire_reached:
        # Find the wire/plant frontier closest to target and extend it
        pow_ys, pow_xs = np.where(powered)
        if len(pow_xs) > 0:
            # Find powered tile closest to target
            dists = (pow_xs - wire_target_x)**2 + (pow_ys - wire_target_y)**2
            best = np.argmin(dists)
            wx, wy = int(pow_xs[best]), int(pow_ys[best])

            # Step toward target
            dx = wire_target_x - wx
            dy = wire_target_y - wy

            if abs(dx) >= abs(dy):
                nx = wx + (1 if dx > 0 else -1)
                ny = wy
            else:
                nx = wx
                ny = wy + (1 if dy > 0 else -1)

            nx = max(0, min(WORLD_W - 1, nx))
            ny = max(0, min(WORLD_H - 1, ny))

            # Don't overwrite the plant itself
            if not plants[ny, nx]:
                return (Tool.WIRE, nx, ny)

    # --- Phase 2: Build road grid ---
    # Main horizontal road at CY, vertical roads at intervals
    # Road grid: horizontal roads at CY-6, CY, CY+6
    # Vertical roads at CX-6, CX, CX+6

    road_rows = [CY - 6, CY, CY + 6]
    road_cols = [CX - 9, CX - 3, CX + 3, CX + 9]

    # Check and build horizontal roads
    for ry in road_rows:
        if ry < 1 or ry >= WORLD_H - 1:
            continue
        for rx in range(CX - 11, CX + 12):
            if rx < 1 or rx >= WORLD_W - 1:
                continue
            if not roads[ry, rx] and not plants[ry, rx]:
                return (Tool.ROAD, rx, ry)

    # Check and build vertical roads
    for rc in road_cols:
        if rc < 1 or rc >= WORLD_W - 1:
            continue
        for ry in range(CY - 8, CY + 9):
            if ry < 1 or ry >= WORLD_H - 1:
                continue
            if not roads[ry, rc] and not plants[ry, rc]:
                return (Tool.ROAD, rc, ry)

    # --- Phase 3: Extend wires along roads for power distribution ---
    # Wire the main horizontal road row at CY to distribute power
    # Wire runs 2 tiles above main road
    wire_row = CY - 2
    if wire_row >= 0:
        for wx in range(CX - 11, CX + 12):
            if wx < 0 or wx >= WORLD_W:
                continue
            if not powered[wire_row, wx] and not plants[wire_row, wx] and not roads[wire_row, wx]:
                # Only place wire if adjacent to existing power
                adj_powered = False
                for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nx2, ny2 = wx + ddx, wire_row + ddy
                    if 0 <= nx2 < WORLD_W and 0 <= ny2 < WORLD_H:
                        if powered[ny2, nx2]:
                            adj_powered = True
                            break
                if adj_powered:
                    return (Tool.WIRE, wx, wire_row)

    # Also wire vertically from wire row down to zone areas
    for wc in [CX - 6, CX, CX + 6]:
        if wc < 0 or wc >= WORLD_W:
            continue
        for wy in range(CY - 2, CY + 2):
            if wy < 0 or wy >= WORLD_H:
                continue
            if not powered[wy, wc] and not plants[wy, wc] and not roads[wy, wc]:
                adj_powered = False
                for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nx2, ny2 = wc + ddx, wy + ddy
                    if 0 <= nx2 < WORLD_W and 0 <= ny2 < WORLD_H:
                        if powered[ny2, nx2]:
                            adj_powered = True
                            break
                if adj_powered:
                    return (Tool.WIRE, wc, wy)

    # --- Phase 4: Place zones in open cells between roads ---
    # Count existing zones to determine what to place
    n_res = int(res.sum())
    n_com = int(com.sum())
    n_ind = int(ind.sum())

    # Target ratio: 4 res : 2 com : 2 ind
    if n_res == 0 or (n_com > 0 and n_ind > 0 and n_res < n_com * 2):
        next_tool = Tool.RESIDENTIAL
    elif n_com * 2 < n_res:
        next_tool = Tool.COMMERCIAL
    elif n_ind * 2 < n_res:
        next_tool = Tool.INDUSTRIAL
    else:
        next_tool = Tool.RESIDENTIAL

    # Find a good zone placement:
    # Must be adjacent to a road and near power
    # Zone center must be away from roads/wires/plants
    all_zones = res | com | ind

    # Candidate centers for 3x3 zones
    # Look in the grid blocks between roads
    zone_candidates = []

    for zy in range(CY - 8, CY + 9, 3):
        for zx in range(CX - 10, CX + 11, 3):
            # Check bounds
            if zx - 1 < 0 or zx + 1 >= WORLD_W or zy - 1 < 0 or zy + 1 >= WORLD_H:
                continue
            # Check 3x3 area is mostly empty (no plants/zones)
            area = tm[zy-1:zy+2, zx-1:zx+2]
            area_plants = plants[zy-1:zy+2, zx-1:zx+2]
            area_zones = all_zones[zy-1:zy+2, zx-1:zx+2]
            area_roads = roads[zy-1:zy+2, zx-1:zx+2]

            if area_plants.any() or area_zones.any():
                continue
            # Don't place if too many roads in the 3x3 (zone needs mostly empty)
            if area_roads.sum() > 3:
                continue

            # Check adjacency to road (within 2 tiles of center)
            road_near = roads[max(0,zy-2):zy+3, max(0,zx-2):zx+3].any()
            if not road_near:
                continue

            # Check power nearby (within 3 tiles)
            pow_near = powered[max(0,zy-3):zy+4, max(0,zx-3):zx+4].any()

            dist = abs(zx - CX) + abs(zy - CY)
            zone_candidates.append((dist, pow_near, zx, zy))

    if zone_candidates:
        # Sort: prefer powered, then close to center
        zone_candidates.sort(key=lambda c: (0 if c[1] else 1, c[0]))
        _, _, zx, zy = zone_candidates[0]
        return (next_tool, zx, zy)

    # Fallback: place road extending outward from existing road network
    if roads.any():
        road_ys, road_xs = np.where(roads)
        # Find road tile closest to center
        dists = abs(road_xs - CX) + abs(road_ys - CY)
        # Try extending roads outward
        for idx in np.argsort(dists)[:20]:
            rx, ry = int(road_xs[idx]), int(road_ys[idx])
            for ddx, ddy in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx + ddx, ry + ddy
                if 0 <= nx2 < WORLD_W and 0 <= ny2 < WORLD_H:
                    if emp[ny2, nx2] and not plants[ny2, nx2]:
                        return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map each step and places next tile
    based on current state of the city. Uses a phase system but each
    phase decision is driven by observations.
    """
    tm = obs.tile_map
    cx, cy = WORLD_W // 2, WORLD_H // 2

    # Initialize state
    if "phase" not in state:
        state["phase"] = "plant"
        state["wire_frontier"] = [(cx, cy)]  # wire grows from plant
        state["road_col_y"] = cy - 15  # road column progress
        state["zone_dy_idx"] = 0
        state["expand_dir"] = 1  # direction for expansion

    phase = state["phase"]

    # --- Phase 1: Place coal power plant ---
    if phase == "plant":
        # Check if plant already exists
        plants = plant_mask(tm)
        if not plants.any():
            state["phase"] = "wire_spine"
            return (Tool.COALPOWER, cx - 3, cy)
        else:
            state["phase"] = "wire_spine"

    # --- Phase 2: Grow wire spine vertically from plant ---
    if phase == "wire_spine":
        wire = wire_mask(tm)
        plants = plant_mask(tm)
        emp = empty_mask(tm)

        # Wire spine at column cx, from cy-15 to cy+15
        # Find the first unwired position in the spine
        for dy in range(-15, 16):
            wx, wy = cx, cy + dy
            if 0 <= wx < WORLD_W and 0 <= wy < WORLD_H:
                if not wire[wy, wx] and not plants[wy, wx]:
                    # Check adjacency to existing wire or plant
                    adj_powered = False
                    for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nx2, ny2 = wx+ddx, wy+ddy
                        if 0 <= nx2 < WORLD_W and 0 <= ny2 < WORLD_H:
                            if wire[ny2, nx2] or plants[ny2, nx2]:
                                adj_powered = True
                                break
                    if adj_powered or (wx == cx and wy == cy):
                        state["phase"] = "wire_spine"
                        return (Tool.WIRE, wx, wy)

        # Also wire from plant to spine
        if not wire[cy, cx-1] and not wire[cy, cx-2]:
            return (Tool.WIRE, cx-1, cy)
        if not wire[cy, cx-2]:
            return (Tool.WIRE, cx-2, cy)

        state["phase"] = "road_spine"

    # --- Phase 3: Grow road spine (col cx+1) ---
    if phase == "road_spine":
        road = road_mask(tm)

        for dy in range(-15, 16):
            rx, ry = cx + 1, cy + dy
            if 0 <= rx < WORLD_W and 0 <= ry < WORLD_H:
                if not road[ry, rx]:
                    state["phase"] = "road_spine"
                    return (Tool.ROAD, rx, ry)

        # Also left road col (cx-1) for left-side zones
        for dy in range(-15, 16):
            rx, ry = cx - 1, cy + dy
            if 0 <= rx < WORLD_W and 0 <= ry < WORLD_H:
                if not road[ry, rx]:
                    return (Tool.ROAD, rx, ry)

        state["phase"] = "zones"

    # --- Phase 4: Closed-loop zone placement ---
    # Read current state of roads, wires, zones
    wire = wire_mask(tm)
    road = road_mask(tm)
    plants = plant_mask(tm)
    res = res_mask(tm)
    com = com_mask(tm)
    ind = ind_mask(tm)
    emp = empty_mask(tm)

    # Count what we have
    n_res = int(res.sum())
    n_com = int(com.sum())
    n_ind = int(ind.sum())

    # Find tiles adjacent to roads (road access)
    adj_road = np.zeros((WORLD_H, WORLD_W), bool)
    adj_road[1:, :] |= road[:-1, :]
    adj_road[:-1, :] |= road[1:, :]
    adj_road[:, 1:] |= road[:, :-1]
    adj_road[:, :-1] |= road[:, 1:]

    # Find tiles adjacent to wire or plant (powered)
    powered_adj = np.zeros((WORLD_H, WORLD_W), bool)
    powered_adj[1:, :] |= (wire[:-1, :] | plants[:-1, :])
    powered_adj[:-1, :] |= (wire[1:, :] | plants[1:, :])
    powered_adj[:, 1:] |= (wire[:, :-1] | plants[:, :-1])
    powered_adj[:, :-1] |= (wire[:, 1:] | plants[:, 1:])

    # Good zone placement: empty, near road, near power
    good_spots = emp & adj_road & powered_adj

    # Also extend roads if needed
    # If powered_zones < expected, we may need more roads or wires
    if obs.powered_zones < 3 and obs.step > 50:
        # Try to lay more wire horizontally from spine to reach further zones
        for dy in range(-15, 16, 3):
            for dx in range(2, 8):
                wx, wy = cx + dx, cy + dy
                if 0 <= wx < WORLD_W and 0 <= wy < WORLD_H:
                    if emp[wy, wx] and not wire[wy, wx]:
                        # Check adjacent wire
                        for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]:
                            if 0 <= wx+ddx < WORLD_W and 0 <= wy+ddy < WORLD_H:
                                if wire[wy+ddy, wx+ddx] or plants[wy+ddy, wx+ddx]:
                                    return (Tool.WIRE, wx, wy)

    if good_spots.any():
        ys, xs = np.where(good_spots)

        # Decide tool based on balance
        step = obs.step
        if n_ind < max(2, n_res // 4):
            tool = Tool.INDUSTRIAL
        elif n_com < max(2, n_res // 3):
            tool = Tool.COMMERCIAL
        else:
            tool = Tool.RESIDENTIAL

        # Pick the candidate closest to center with some variation
        dists = np.abs(xs - cx) + np.abs(ys - cy)
        # Add small hash-based noise for variation
        noise = (tm[ys, xs].astype(int) + step) % 5
        scores = dists + noise * 2
        best = int(np.argmin(scores))

        return (tool, int(xs[best]), int(ys[best]))

    # If no good spots, try extending road near existing zones or wires
    # Find positions adjacent to existing roads but not yet roads
    adj_road_but_not = np.zeros((WORLD_H, WORLD_W), bool)
    for dy in range(-1, 2):
        for dx in range(-1, 2):
            if abs(dx)+abs(dy) != 1:
                continue
            shifted = np.zeros((WORLD_H, WORLD_W), bool)
            sy, sx = dy, dx
            if sy > 0:
                shifted[sy:, :] = road[:-sy, :]
            elif sy < 0:
                shifted[:sy, :] = road[-sy:, :]
            else:
                shifted = road.copy()
            if sx > 0:
                shifted2 = np.zeros((WORLD_H, WORLD_W), bool)
                shifted2[:, sx:] = shifted[:, :-sx]
                shifted = shifted2
            elif sx < 0:
                shifted2 = np.zeros((WORLD_H, WORLD_W), bool)
                shifted2[:, :sx] = shifted[:, -sx:]
                shifted = shifted2
            adj_road_but_not |= shifted
    extend_road = emp & adj_road_but_not & ~road

    if extend_road.any():
        ys, xs = np.where(extend_road)
        # Extend towards center
        dists = np.abs(xs - cx) + np.abs(ys - cy)
        best = int(np.argmin(dists))
        return (Tool.ROAD, int(xs[best]), int(ys[best]))

    # Fallback: place residential near center
    if emp[cy, cx+4]:
        return (Tool.RESIDENTIAL, cx+4, cy)

    return None

def act(obs, state):
    """
    Closed-loop policy: each step reads the map and decides what to place next.
    Strategy:
    - Place a coal power plant first if none exists.
    - Extend wires from the power plant outward to form a spine.
    - Build roads adjacent to the wire spine.
    - Place residential zones adjacent to roads (with power nearby).
    - Add commercial/industrial for balance once res zones exist.
    """
    tm = obs.tile_map
    step = obs.step

    cx, cy = WORLD_W // 2, WORLD_H // 2

    # Check what's on the map using masks
    has_plant = np.any(plant_mask(tm))
    has_wire = np.any(wire_mask(tm))
    has_road = np.any(road_mask(tm))
    res_count = np.sum(res_mask(tm))
    com_count = np.sum(com_mask(tm))
    ind_count = np.sum(ind_mask(tm))

    # Phase 1: Place coal power plant if missing
    if not has_plant:
        return (Tool.COALPOWER, cx - 4, cy)

    # Helper: find all wire tile positions
    wm = wire_mask(tm)
    wire_positions = list(zip(*np.where(wm)))  # (row, col) pairs

    # Helper: find all road tile positions
    rm = road_mask(tm)
    road_positions = list(zip(*np.where(rm)))

    # Helper: find plant positions
    pm = plant_mask(tm)
    plant_positions = list(zip(*np.where(pm)))

    em = empty_mask(tm)

    # Phase 2: Extend wire spine vertically from power plant area
    # Wire column at cx-1 (adjacent to plant center)
    wire_col = cx - 1
    # Find the current wire extent in the wire column
    wire_col_rows = [r for (r, c) in wire_positions if c == wire_col]

    if not wire_col_rows:
        # Start wire adjacent to plant (plant center at cx-4, cy => right edge at cx-4+1=cx-3)
        # Place wire at cx-3 to cx-1 bridging to spine
        # Actually connect from plant: plant occupies cx-4 center, so tiles cx-6..cx-2, cy-1..cy+1
        # Place wire at cx-2 first (just right of plant footprint edge)
        # Plant center cx-4, footprint cx-6..cx-2 => wire at cx-1 is adjacent
        if em[cy, cx - 1]:
            return (Tool.WIRE, cx - 1, cy)
        else:
            return (Tool.WIRE, cx, cy)
    else:
        # Extend wire column upward and downward from current extent
        min_row = min(wire_col_rows)
        max_row = max(wire_col_rows)
        target_min = cy - 12
        target_max = cy + 12

        # Try to extend downward first, then upward
        if max_row < target_max and max_row + 1 < WORLD_H:
            nr = max_row + 1
            nc = wire_col
            if em[nr, nc] or wire_mask(tm)[nr, nc]:
                return (Tool.WIRE, nc, nr)
        if min_row > target_min and min_row - 1 >= 0:
            nr = min_row - 1
            nc = wire_col
            if em[nr, nc] or wire_mask(tm)[nr, nc]:
                return (Tool.WIRE, nc, nr)

    # Phase 3: Build road column adjacent to wire spine
    road_col = cx  # road at cx, wire at cx-1
    road_col_rows = [r for (r, c) in road_positions if c == road_col]
    wire_col_rows_sorted = sorted(wire_col_rows) if wire_col_rows else []

    if wire_col_rows_sorted:
        # For each wire row, ensure there's a road at road_col, same row
        for r in wire_col_rows_sorted:
            if 0 <= r < WORLD_H and 0 <= road_col < WORLD_W:
                if not rm[r, road_col]:
                    if em[r, road_col]:
                        return (Tool.ROAD, road_col, r)

    # Phase 4: Place residential zones to the LEFT of wire (cx-1-2=cx-3 center)
    # and to the RIGHT of road (cx+3 center)
    # Zones are 3x3, placed by center. Adjacent to wire/road.
    # Left zones: center at cx-4, rows spaced by 3
    # Right zones: center at cx+3, rows spaced by 3

    res_positions = list(zip(*np.where(res_mask(tm))))
    res_centers_left = [(r, cx - 4) for r in range(cy - 12, cy + 13, 3)]
    res_centers_right = [(r, cx + 3) for r in range(cy - 12, cy + 13, 3)]

    # Check if a zone center position is free (3x3 area all empty or same zone)
    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                # Allow empty tiles
                if not em[rr, rc]:
                    return False
        return True

    # Place zones only where wire/road coverage exists at that row
    for (zr, zc) in res_centers_left + res_centers_right:
        if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
            # Check wire exists at this row (for power) and road exists (for access)
            wire_here = wire_col_rows and (zr in wire_col_rows or
                        any(abs(zr - wr) <= 1 for wr in wire_col_rows))
            road_here = any(abs(zr - rr) <= 2 for (rr, rc) in road_positions if rc == road_col)
            if wire_here and road_here:
                # Check not already a res zone nearby
                already = any(abs(zr - pr) <= 1 and abs(zc - pc) <= 1
                              for (pr, pc) in res_positions)
                if not already and zone_area_free(zr, zc):
                    # Decide type: mostly residential, some commercial/industrial
                    if com_count < res_count // 4 and zc == cx + 3:
                        return (Tool.COMMERCIAL, zc, zr)
                    elif ind_count < res_count // 4 and zc == cx - 4 and zr > cy:
                        return (Tool.INDUSTRIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

    # Phase 5: If zones exist but unpowered, add more wire laterally to reach zones
    # Connect wire from spine to zone columns
    # Left zone col = cx-4, wire col = cx-1 => need wire at cx-2, cx-3 at matching rows
    for wr in wire_col_rows_sorted:
        for wc in [cx - 2, cx - 3]:
            if 0 <= wc < WORLD_W and em[wr, wc]:
                return (Tool.WIRE, wc, wr)
        # Road extension right
        for rc in [cx + 1, cx + 2]:
            if 0 <= rc < WORLD_W and em[wr, rc]:
                return (Tool.ROAD, rc, wr)

    # Phase 6: Add more zone rows if population growing well
    if obs.city_pop > 200:
        for dy in range(-15, 16, 3):
            for (zc, zr) in [(cx - 4, cy + dy), (cx + 3, cy + dy)]:
                if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                    already = any(abs(zr - pr) <= 1 and abs(zc - pc) <= 1
                                  for (pr, pc) in res_positions)
                    if not already and zone_area_free(zr, zc):
                        return (Tool.RESIDENTIAL, zc, zr)

    return None

def act(obs, state):
    tm = obs.tile_map
    cx, cy = WORLD_W // 2, WORLD_H // 2

    # Phase 0: Place coal power plant if not present
    plants = plant_mask(tm)
    if not plants.any():
        return (Tool.COALPOWER, cx, cy)

    # Find the power plant location
    plant_ys, plant_xs = np.where(plants)
    px, py = int(plant_xs[0]), int(plant_ys[0])

    # Phase 1: Extend wire network from plant outward
    # Wire goes left from plant to create a power spine
    wires = wire_mask(tm)
    roads = road_mask(tm)
    emp = empty_mask(tm)

    # Find the leftmost extent of wire going left from plant
    # We want a vertical wire spine going left of the plant
    # and a road column just to the left of zones

    # Strategy: 
    # - Wire column at cx-1 (vertical power spine)
    # - Road column at cx+2 (access road)
    # - Zones at cx-4 (left) and cx+5 (right) of road
    # All reactive: check what's missing and place it

    wire_col = cx - 2
    road_col = cx + 2

    # First ensure wire spine exists vertically near plant
    # Check if wire exists at wire_col, py
    if emp[py, wire_col]:
        return (Tool.WIRE, wire_col, py)

    # Extend wire spine vertically from existing wire
    if wires[:, wire_col].any():
        wy = np.where(wires[:, wire_col])[0]
        top_w = int(wy.min())
        bot_w = int(wy.max())
        # Extend upward
        if top_w > max(5, py - 15) and emp[top_w - 1, wire_col]:
            return (Tool.WIRE, wire_col, top_w - 1)
        # Extend downward
        if bot_w < min(WORLD_H - 6, py + 15) and emp[bot_w + 1, wire_col]:
            return (Tool.WIRE, wire_col, bot_w + 1)
    else:
        # Wire from plant to wire_col horizontally
        # Connect plant to wire col
        for x in range(min(px, wire_col), max(px, wire_col) + 1):
            if emp[py, x]:
                return (Tool.WIRE, x, py)

    # Connect wire spine to road col with horizontal wire if needed
    if wires[:, wire_col].any() and not roads[:, road_col].any():
        wy = np.where(wires[:, wire_col])[0]
        mid_y = int(wy[len(wy)//2])
        # Lay horizontal wire from wire_col to road_col
        for x in range(wire_col + 1, road_col + 1):
            if emp[mid_y, x]:
                return (Tool.WIRE, x, mid_y)

    # Ensure road column exists
    if roads[:, road_col].any():
        ry = np.where(roads[:, road_col])[0]
        top_r = int(ry.min())
        bot_r = int(ry.max())
        # Extend road upward
        if top_r > max(3, py - 15) and emp[top_r - 1, road_col]:
            return (Tool.ROAD, road_col, top_r - 1)
        # Extend road downward
        if bot_r < min(WORLD_H - 4, py + 15) and emp[bot_r + 1, road_col]:
            return (Tool.ROAD, road_col, bot_r + 1)
    else:
        # Start road at plant row
        if emp[py, road_col]:
            return (Tool.ROAD, road_col, py)

    # Place zones adjacent to road and wire
    # Residential to the left of road (center at road_col - 3)
    # Commercial to the right of road (center at road_col + 3)
    res = res_mask(tm)
    com = com_mask(tm)
    ind = ind_mask(tm)

    # Find road rows and place zones reactively
    if roads[:, road_col].any():
        road_rows = np.where(roads[:, road_col])[0]
        # Try to place zones at every 3rd road row
        for ry in road_rows:
            ry = int(ry)
            # Left residential zone center at (road_col - 3, ry)
            zx_left = road_col - 3
            if (2 <= zx_left <= WORLD_W - 3 and 2 <= ry <= WORLD_H - 3):
                # Check if zone already there
                zone_present = res[ry, zx_left] or com[ry, zx_left] or ind[ry, zx_left]
                # Check tile around center is empty-ish
                region = tm[max(0,ry-1):ry+2, max(0,zx_left-1):zx_left+2]
                if not zone_present and emp[ry, zx_left]:
                    # Also need wire nearby - check if wire spine serves this row
                    if wires[ry, wire_col] or any(wires[ry, wire_col:road_col]):
                        # Alternate residential/commercial/industrial based on position
                        tool = Tool.RESIDENTIAL if (ry // 3) % 3 == 0 else (Tool.COMMERCIAL if (ry // 3) % 3 == 1 else Tool.INDUSTRIAL)
                        return (tool, zx_left, ry)

            # Right commercial zone center at (road_col + 3, ry)
            zx_right = road_col + 3
            if (2 <= zx_right <= WORLD_W - 3 and 2 <= ry <= WORLD_H - 3):
                zone_present = res[ry, zx_right] or com[ry, zx_right] or ind[ry, zx_right]
                if not zone_present and emp[ry, zx_right]:
                    if wires[ry, wire_col] or any(wires[ry, wire_col:road_col]):
                        tool = Tool.COMMERCIAL if (ry // 3) % 3 == 0 else (Tool.RESIDENTIAL if (ry // 3) % 3 == 1 else Tool.INDUSTRIAL)
                        return (tool, zx_right, ry)

    # Fallback: find any empty cell near road and place residential
    if roads.any() and wires.any():
        nbr = np.zeros_like(emp)
        nbr[1:, :] |= roads[:-1, :]
        nbr[:-1, :] |= roads[1:, :]
        nbr[:, 1:] |= roads[:, :-1]
        nbr[:, :-1] |= roads[:, 1:]
        cand = emp & nbr
        # Also near wire
        wnbr = np.zeros_like(emp)
        wnbr[1:, :] |= wires[:-1, :]
        wnbr[:-1, :] |= wires[1:, :]
        wnbr[:, 1:] |= wires[:, :-1]
        wnbr[:, :-1] |= wires[:, 1:]
        cand = cand & wnbr
        ys, xs = np.where(cand)
        if len(xs) > 0:
            k = int(tm.sum()) % len(xs)
            return (Tool.RESIDENTIAL, int(xs[k]), int(ys[k]))

    return None

def act(obs, state):
    """
    Improved policy with:
    - TWO neighborhoods (left and right clusters) connected by a horizontal road/wire spine
    - Better zone mix: 50% res, 25% com, 25% ind
    - Horizontal layout instead of vertical spine
    - Two power plants for better coverage
    """
    tm = obs.tile_map
    step = obs.step

    # Two neighborhood centers
    # Left cluster around (30, 50), Right cluster around (85, 50)
    lx, ly = 30, 50
    rx, ry = 85, 50

    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    has_plant = np.any(pm)
    plant_positions = list(zip(*np.where(pm)))
    wire_positions = list(zip(*np.where(wm)))
    road_positions = list(zip(*np.where(rm)))
    res_positions = list(zip(*np.where(res_mask(tm))))
    com_positions = list(zip(*np.where(com_mask(tm))))
    ind_positions = list(zip(*np.where(ind_mask(tm))))

    res_count = len(res_positions)
    com_count = len(com_positions)
    ind_count = len(ind_positions)

    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def pick_zone_type(zc, zr, cluster_center_x):
        # Balance: 50% res, 25% com, 25% ind
        total = res_count + com_count + ind_count + 1
        if com_count / total < 0.25 and (zr % 3 == 0):
            return Tool.COMMERCIAL
        elif ind_count / total < 0.25 and (zr % 3 == 1):
            return Tool.INDUSTRIAL
        else:
            return Tool.RESIDENTIAL

    # Phase 1: Place left power plant
    if not has_plant:
        return (Tool.COALPOWER, lx - 5, ly)

    # Phase 2: Place right power plant if only one exists
    num_plants = len(plant_positions)
    if num_plants < 2:
        # Check if right plant area is free
        rpx, rpy = rx - 5, ry
        # just try to place it
        return (Tool.COALPOWER, rpx, rpy)

    # Phase 3: Build horizontal wire spine connecting both plants
    # Wire spine at row ly (same as both clusters)
    # Connect from left plant right edge to right plant left edge
    # Left plant center (lx-5, ly), footprint lx-7..lx-3
    # Right plant center (rx-5, ry), footprint rx-7..rx-3
    # Wire spine: row ly, cols lx-2 to rx-6
    spine_row = ly
    spine_start = lx - 2
    spine_end = rx - 6

    wire_spine_cols = [c for (r, c) in wire_positions if r == spine_row]
    if wire_spine_cols:
        max_wc = max(wire_spine_cols)
        min_wc = min(wire_spine_cols)
    else:
        max_wc = spine_start - 1
        min_wc = spine_start

    # Extend wire spine rightward
    if max_wc < spine_end:
        nc = max_wc + 1
        if 0 <= nc < WORLD_W:
            return (Tool.WIRE, nc, spine_row)

    # Phase 4: Build road spines (horizontal) slightly above and below wire
    # Road row at ly - 2 and ly + 2 (parallel to wire)
    for road_row in [ly - 2, ly + 2]:
        road_cols_here = [c for (r, c) in road_positions if r == road_row]
        if road_cols_here:
            max_rc = max(road_cols_here)
        else:
            max_rc = spine_start - 1
        if max_rc < spine_end + 5:
            nc = max_rc + 1
            if 0 <= nc < WORLD_W:
                return (Tool.ROAD, nc, road_row)

    # Phase 5: Build vertical connector roads at intervals
    # Every 6 cols from lx to rx, connect road rows to wire spine row
    for conn_col in range(lx, rx, 6):
        for conn_row in range(ly - 2, ly + 3):
            if not rm[conn_row, conn_col] and not wm[conn_row, conn_col]:
                if 0 <= conn_col < WORLD_W and 0 <= conn_row < WORLD_H:
                    return (Tool.ROAD, conn_col, conn_row)

    # Phase 6: Place zones above and below road spines
    # Zone rows: ly-5, ly-8, ly-11 (above), ly+5, ly+8, ly+11 (below)
    # Zone cols: spaced every 6 starting from lx-1 to rx
    zone_rows_above = [ly - 5, ly - 8, ly - 11, ly - 14]
    zone_rows_below = [ly + 5, ly + 8, ly + 11, ly + 14]
    zone_cols = list(range(lx - 1, rx + 1, 6))

    for zr in zone_rows_above + zone_rows_below:
        for zc in zone_cols:
            if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                # Check road access nearby
                road_near = any(
                    abs(zr - rr) <= 3 and abs(zc - rc) <= 3
                    for (rr, rc) in road_positions
                )
                # Check wire access nearby
                wire_near = any(
                    abs(zr - wr) <= 5 and abs(zc - wc) <= 5
                    for (wr, wc) in wire_positions
                )
                if road_near and wire_near:
                    already = any(
                        abs(zr - pr) <= 1 and abs(zc - pc) <= 1
                        for (pr, pc) in res_positions + com_positions + ind_positions
                    )
                    if not already and zone_area_free(zr, zc):
                        return (pick_zone_type(zc, zr, lx), zc, zr)

    # Phase 7: Add lateral wires to reach zones that aren't powered
    # Add wire branches off spine going up/down at zone columns
    for zc in zone_cols:
        for zr in zone_rows_above:
            if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                # wire from spine row up to zone row at this col
                for wr in range(spine_row - 1, zr - 1, -1):
                    if not wm[wr, zc] and not rm[wr, zc]:
                        if em[wr, zc]:
                            return (Tool.WIRE, zc, wr)
                        break
        for zr in zone_rows_below:
            if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                for wr in range(spine_row + 1, zr + 2):
                    if not wm[wr, zc] and not rm[wr, zc]:
                        if em[wr, zc]:
                            return (Tool.WIRE, zc, wr)
                        break

    # Phase 8: If population is growing, expand zone area
    if obs.city_pop > 100:
        extra_rows = [ly - 17, ly + 17, ly - 20, ly + 20]
        for zr in extra_rows:
            for zc in zone_cols:
                if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                    already = any(
                        abs(zr - pr) <= 1 and abs(zc - pc) <= 1
                        for (pr, pc) in res_positions + com_positions + ind_positions
                    )
                    if not already and zone_area_free(zr, zc):
                        road_near = any(
                            abs(zr - rr) <= 4 and abs(zc - rc) <= 4
                            for (rr, rc) in road_positions
                        )
                        if road_near:
                            return (pick_zone_type(zc, zr, lx), zc, zr)

    # Fill remaining steps with roads to improve connectivity
    for zc in zone_cols:
        for road_row in [ly - 2, ly + 2]:
            if 0 <= zc < WORLD_W and 0 <= road_row < WORLD_H:
                if not rm[road_row, zc]:
                    return (Tool.ROAD, zc, road_row)

    return None

def act(obs, state):
    """
    Redesigned policy:
    - Single compact cluster centered at (60, 50)
    - Nuclear power plant for stronger power coverage
    - Grid road layout (horizontal + vertical roads every 6 tiles)
    - Wire runs along roads to power zones
    - Dense zone placement: 40% res, 30% com, 30% ind
    - Build infrastructure first, then zones
    """
    tm = obs.tile_map
    step = obs.step

    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    # Cluster center
    cx, cy = 60, 50

    # Build a sequential plan stored in state
    if 'plan' not in state:
        plan = []

        # 1. Place nuclear power plant at top-left of cluster
        px, py = cx - 20, cy - 10
        plan.append((Tool.NUCLEARPOWER, px, py))

        # 2. Build a grid of roads
        # Horizontal roads at rows: cy-12, cy-6, cy, cy+6, cy+12
        # Vertical roads at cols: cx-18, cx-12, cx-6, cx, cx+6, cx+12, cx+18
        h_rows = [cy - 12, cy - 6, cy, cy + 6, cy + 12]
        v_cols = [cx - 18, cx - 12, cx - 6, cx, cx + 6, cx + 12, cx + 18]

        for row in h_rows:
            for col in range(cx - 20, cx + 21):
                if 0 <= col < WORLD_W and 0 <= row < WORLD_H:
                    plan.append((Tool.ROAD, col, row))

        for col in v_cols:
            for row in range(cy - 14, cy + 15):
                if 0 <= col < WORLD_W and 0 <= row < WORLD_H:
                    plan.append((Tool.ROAD, col, row))

        # 3. Wire from plant along top horizontal road to connect power
        # Wire runs along cy-12 row from plant edge to cluster
        for col in range(px + 3, cx + 19):
            if 0 <= col < WORLD_W:
                plan.append((Tool.WIRE, col, cy - 12))

        # Wire branches down each vertical road column
        for col in v_cols:
            for row in range(cy - 12, cy + 13):
                if 0 <= col < WORLD_W and 0 <= row < WORLD_H:
                    plan.append((Tool.WIRE, col, row))

        # 4. Place zones in the grid cells between roads
        # Zone centers are at intersections offset by 3 from road rows/cols
        # Between h_rows: cy-9, cy-3, cy+3, cy+9
        # Between v_cols pairs
        zone_rows = [cy - 9, cy - 3, cy + 3, cy + 9]
        zone_cols = [cx - 15, cx - 9, cx - 3, cx + 3, cx + 9, cx + 15]

        zone_seq = 0
        for zr in zone_rows:
            for zc in zone_cols:
                if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                    # 40% res, 30% com, 30% ind
                    if zone_seq % 10 < 4:
                        tool = Tool.RESIDENTIAL
                    elif zone_seq % 10 < 7:
                        tool = Tool.COMMERCIAL
                    else:
                        tool = Tool.INDUSTRIAL
                    plan.append((tool, zc, zr))
                    zone_seq += 1

        # 5. Second power plant for extra coverage
        plan.append((Tool.COALPOWER, cx + 20, cy - 10))
        # Wire from second plant leftward along top road
        for col in range(cx + 19, cx - 1, -1):
            if 0 <= col < WORLD_W:
                plan.append((Tool.WIRE, col, cy - 12))

        # 6. Expand with more zones if steps allow
        extra_zone_rows = [cy - 15, cy + 15]
        for zr in extra_zone_rows:
            for zc in zone_cols:
                if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                    if zone_seq % 10 < 4:
                        tool = Tool.RESIDENTIAL
                    elif zone_seq % 10 < 7:
                        tool = Tool.COMMERCIAL
                    else:
                        tool = Tool.INDUSTRIAL
                    plan.append((tool, zc, zr))
                    zone_seq += 1

        # Roads for extra rows
        for zr in extra_zone_rows:
            for col in range(cx - 20, cx + 21):
                if 0 <= col < WORLD_W and 0 <= zr < WORLD_H:
                    plan.insert(len(plan) - zone_seq, (Tool.ROAD, col, zr))

        state['plan'] = plan
        state['idx'] = 0

    idx = state['idx']
    plan = state['plan']

    if idx < len(plan):
        action = plan[idx]
        state['idx'] = idx + 1
        return action

    # After plan exhausted, try to add more zones reactively
    # Find empty spots near roads and wire
    road_positions = list(zip(*np.where(rm)))
    wire_positions = list(zip(*np.where(wm)))
    all_zones = list(zip(*np.where(res_mask(tm) | com_mask(tm) | ind_mask(tm))))

    if not road_positions or not wire_positions:
        return None

    # Try to place zones near existing infrastructure
    for attempt in range(20):
        # Pick a road tile and try placing a zone 3 tiles away
        ridx = (step + attempt * 7) % len(road_positions)
        rr, rc = road_positions[ridx]
        for offset in [3, -3]:
            for zr, zc in [(rr + offset, rc), (rr, rc + offset)]:
                if 2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3:
                    # Check 3x3 area is empty
                    area = tm[zr-1:zr+2, zc-1:zc+2]
                    if np.all(em[zr-1:zr+2, zc-1:zc+2]):
                        near_zone = any(
                            abs(zr - zz) <= 3 and abs(zc - zc2) <= 3
                            for (zz, zc2) in all_zones
                        )
                        if not near_zone:
                            seq = step + attempt
                            if seq % 10 < 4:
                                tool = Tool.RESIDENTIAL
                            elif seq % 10 < 7:
                                tool = Tool.COMMERCIAL
                            else:
                                tool = Tool.INDUSTRIAL
                            return (tool, zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop policy: each step scans the current map and places the next
    most-needed tile based on what already exists.

    Strategy:
    - Phase 0: Place coal plant at center-left
    - Phase 1: Extend wire column downward from plant, then upward
    - Phase 2: Extend road column adjacent to wire
    - Phase 3: Place residential zones next to road+wire
    - Phase 4: Add commercial/industrial zones for variety
    - Throughout: react to actual map state
    """
    cx, cy = WORLD_W // 2, WORLD_H // 2

    # Initialize state
    if "phase" not in state:
        state["phase"] = 0
        state["step_in_phase"] = 0

    tile_map = obs.tile_map

    # Helper: check if a position has a tile of given mask
    def has_plant(x, y):
        if 0 <= y < WORLD_H and 0 <= x < WORLD_W:
            return plant_mask[y, x]
        return False

    def has_wire(x, y):
        if 0 <= y < WORLD_H and 0 <= x < WORLD_W:
            return wire_mask[y, x]
        return False

    def has_road(x, y):
        if 0 <= y < WORLD_H and 0 <= x < WORLD_W:
            return road_mask[y, x]
        return False

    def is_empty(x, y):
        if 0 <= y < WORLD_H and 0 <= x < WORLD_W:
            return empty_mask[y, x]
        return False

    def has_res(x, y):
        if 0 <= y < WORLD_H and 0 <= x < WORLD_W:
            return res_mask[y, x]
        return False

    def has_com(x, y):
        if 0 <= y < WORLD_H and 0 <= x < WORLD_W:
            return com_mask[y, x]
        return False

    def has_ind(x, y):
        if 0 <= y < WORLD_H and 0 <= x < WORLD_W:
            return ind_mask[y, x]
        return False

    # Phase 0: Place coal plant if not present near center
    # Plant center at (cx-4, cy), occupies 3x3: cols cx-5..cx-3, rows cy-1..cy+1
    plant_x, plant_y = cx - 4, cy
    if not np.any(plant_mask):
        return (Tool.COALPOWER, plant_x, plant_y)

    # Phase 1: Build wire column at cx-1 (right edge of plant area + 1)
    # Wire column at x = cx-1, from cy-14 to cy+14
    wire_col = cx - 1
    wire_range = range(cy - 14, cy + 15)

    # Find topmost wire in the column to extend from
    # First check if wire column needs filling
    for wy in wire_range:
        if not has_wire(wire_col, wy) and not has_plant(wire_col, wy):
            # Check if adjacent to existing wire or plant
            adjacent_powered = (
                has_plant(wire_col - 1, wy) or has_plant(wire_col + 1, wy) or
                has_plant(wire_col, wy - 1) or has_plant(wire_col, wy + 1) or
                has_wire(wire_col - 1, wy) or has_wire(wire_col + 1, wy) or
                has_wire(wire_col, wy - 1) or has_wire(wire_col, wy + 1)
            )
            if adjacent_powered:
                return (Tool.WIRE, wire_col, wy)

    # Phase 2: Build road column at cx (adjacent to wire)
    road_col = cx
    for ry in range(cy - 14, cy + 15):
        if not has_road(road_col, ry) and not has_plant(road_col, ry) and not has_wire(road_col, ry):
            # Check if adjacent to existing road or at start
            adjacent_road = (
                has_road(road_col, ry - 1) or has_road(road_col, ry + 1) or
                ry == cy  # start at center
            )
            if adjacent_road or not np.any(road_mask):
                return (Tool.ROAD, road_col, ry)

    # Also extend road column further if needed
    for ry in range(cy - 14, cy + 15):
        if not has_road(road_col, ry) and not has_plant(road_col, ry):
            adjacent_road = (
                has_road(road_col, ry - 1) or has_road(road_col, ry + 1)
            )
            if adjacent_road:
                return (Tool.ROAD, road_col, ry)

    # Phase 3: Place residential zones to the LEFT of wire column
    # Centers at cx-4 (but plant is there), so use cx-5 and cx+3
    # Left zones: center x = wire_col - 3 = cx-4... but plant is at cx-4
    # Use left side at x = wire_col - 4 = cx-5, right side at x = road_col + 3 = cx+3

    left_zone_x = wire_col - 4   # cx - 5
    right_zone_x = road_col + 3  # cx + 3

    # Place residential zones every 3 rows, alternating left/right
    res_rows = list(range(cy - 12, cy + 13, 3))

    for zone_y in res_rows:
        # Try left side first
        if not has_res(left_zone_x, zone_y) and not has_plant(left_zone_x, zone_y):
            # Check wire is nearby (within 1 tile of zone edge = within 2 of center)
            wire_nearby = any(has_wire(wire_col, zone_y + dy) for dy in range(-2, 3))
            if wire_nearby:
                return (Tool.RESIDENTIAL, left_zone_x, zone_y)

        # Try right side
        if not has_res(right_zone_x, zone_y) and not has_plant(right_zone_x, zone_y):
            road_nearby = any(has_road(road_col, zone_y + dy) for dy in range(-2, 3))
            if road_nearby:
                return (Tool.RESIDENTIAL, right_zone_x, zone_y)

    # Phase 4: Add commercial zones further right for economic diversity
    com_zone_x = road_col + 7  # cx + 7
    # Need road connection: add road from road_col to com_zone_x
    for rx in range(road_col + 1, com_zone_x + 1):
        if not has_road(rx, cy) and not has_plant(rx, cy):
            # connect horizontally at cy
            if has_road(rx - 1, cy) or has_road(rx + 1, cy):
                return (Tool.ROAD, rx, cy)

    # Add wire along same horizontal to power right-side zones
    for wx in range(wire_col + 1, com_zone_x - 1):
        if not has_wire(wx, cy) and not has_road(wx, cy) and not has_plant(wx, cy):
            if has_wire(wx - 1, cy) or has_wire(wx + 1, cy):
                return (Tool.WIRE, wx, cy)

    for zone_y in res_rows:
        if not has_com(com_zone_x, zone_y) and not has_res(com_zone_x, zone_y):
            road_nearby = any(has_road(road_col + dx, zone_y) for dx in range(0, 8))
            if road_nearby:
                return (Tool.COMMERCIAL, com_zone_x, zone_y)

    # Phase 5: Add industrial zones on far left for jobs
    ind_zone_x = wire_col - 8  # cx - 9
    for wx in range(ind_zone_x + 2, wire_col):
        if not has_wire(wx, cy) and not has_plant(wx, cy):
            if has_wire(wx + 1, cy) or has_wire(wx - 1, cy) or has_plant(wx + 1, cy):
                return (Tool.WIRE, wx, cy)

    for zone_y in res_rows:
        if not has_ind(ind_zone_x, zone_y) and not has_res(ind_zone_x, zone_y):
            wire_nearby = any(has_wire(wire_col - dx, zone_y) for dx in range(0, 8))
            if wire_nearby:
                return (Tool.INDUSTRIAL, ind_zone_x, zone_y)

    # Phase 6: If population is low, add more residential zones above/below current range
    if obs.city_pop < 500:
        # Extend wire column further
        for wy in range(cy - 20, cy - 14):
            if not has_wire(wire_col, wy):
                if has_wire(wire_col, wy + 1):
                    return (Tool.WIRE, wire_col, wy)
        for wy in range(cy + 15, cy + 21):
            if not has_wire(wire_col, wy):
                if has_wire(wire_col, wy - 1):
                    return (Tool.WIRE, wire_col, wy)
        # Extend road column
        for ry in range(cy - 20, cy - 14):
            if not has_road(road_col, ry):
                if has_road(road_col, ry + 1):
                    return (Tool.ROAD, road_col, ry)
        for ry in range(cy + 15, cy + 21):
            if not has_road(road_col, ry):
                if has_road(road_col, ry - 1):
                    return (Tool.ROAD, road_col, ry)
        # More residential zones
        ext_rows = list(range(cy - 18, cy - 12, 3)) + list(range(cy + 15, cy + 21, 3))
        for zone_y in ext_rows:
            if not has_res(left_zone_x, zone_y):
                return (Tool.RESIDENTIAL, left_zone_x, zone_y)
            if not has_res(right_zone_x, zone_y):
                return (Tool.RESIDENTIAL, right_zone_x, zone_y)

    return None

def act(obs, state):
    """
    Closed-loop policy: each step reads the current map and decides
    the next placement based on what's actually there.

    Strategy:
    - Phase 0: Place coal power plant
    - Phase 1: Extend wire from power plant outward (scan for frontier)
    - Phase 2: Place road parallel to wire
    - Phase 3: Place residential zones adjacent to road
    - Uses obs.tile_map to find where things are and where to grow next
    """

    cx, cy = WORLD_W // 2, WORLD_H // 2

    # Initialize state
    if "phase" not in state:
        state["phase"] = 0
        state["wire_col"] = cx
        state["road_col"] = cx + 1
        state["spine_y_min"] = cy - 14
        state["spine_y_max"] = cy + 14
        state["res_placed"] = 0

    tm = obs.tile_map

    # --- Phase 0: Place coal power plant ---
    if state["phase"] == 0:
        # Check if plant already exists near our target location
        plant_x, plant_y = cx - 4, cy
        if plant_mask(tm).any():
            state["phase"] = 1
        else:
            state["phase"] = 1
            return (Tool.COALPOWER, plant_x, plant_y)

    # --- Phase 1: Extend wire column downward/upward from plant ---
    if state["phase"] == 1:
        wcol = state["wire_col"]
        y_min = state["spine_y_min"]
        y_max = state["spine_y_max"]

        # Find lowest wire in our column
        wm = wire_mask(tm)
        pm = plant_mask(tm)

        # Scan the wire column for gaps
        for y in range(y_min, y_max + 1):
            if 0 <= y < WORLD_H and 0 <= wcol < WORLD_W:
                # Check if this cell needs wire (not already wire or plant)
                if not wm[y, wcol] and not pm[y, wcol]:
                    return (Tool.WIRE, wcol, y)

        # All wire placed, move to road phase
        state["phase"] = 2

    # --- Phase 2: Place road column adjacent to wire ---
    if state["phase"] == 2:
        rcol = state["road_col"]
        y_min = state["spine_y_min"]
        y_max = state["spine_y_max"]

        rm = road_mask(tm)

        for y in range(y_min, y_max + 1):
            if 0 <= y < WORLD_H and 0 <= rcol < WORLD_W:
                if not rm[y, rcol]:
                    return (Tool.ROAD, rcol, y)

        # All road placed, move to zone phase
        state["phase"] = 3

    # --- Phase 3: Place residential zones reactively ---
    if state["phase"] == 3:
        wcol = state["wire_col"]
        rcol = state["road_col"]
        y_min = state["spine_y_min"]
        y_max = state["spine_y_max"]

        rm = road_mask(tm)
        wm = wire_mask(tm)

        # Left zones: center at wcol-3, right zones: center at rcol+2
        # Place zones where road is present nearby and no zone exists yet

        # Check right side first: center x = rcol+2
        right_x = rcol + 2
        for y in range(y_min, y_max + 1, 3):
            if 0 <= y < WORLD_H:
                # Check if road exists adjacent to zone
                road_nearby = False
                for dy in range(-1, 2):
                    ny = y + dy
                    if 0 <= ny < WORLD_H and 0 <= rcol < WORLD_W:
                        if rm[ny, rcol]:
                            road_nearby = True
                            break

                if road_nearby:
                    # Check if zone already placed here
                    zm = res_mask(tm)
                    # Check 3x3 area around center
                    already_there = False
                    for dy in range(-1, 2):
                        for dx in range(-1, 2):
                            ny, nx = y + dy, right_x + dx
                            if 0 <= ny < WORLD_H and 0 <= nx < WORLD_W:
                                if zm[ny, nx]:
                                    already_there = True
                    if not already_there:
                        return (Tool.RESIDENTIAL, right_x, y)

        # Left side: center x = wcol-3
        left_x = wcol - 3
        for y in range(y_min, y_max + 1, 3):
            if 0 <= y < WORLD_H:
                road_nearby = False
                # Road is at rcol; left zones are far left, need wire access
                # Check wire adjacency
                for dy in range(-1, 2):
                    ny = y + dy
                    if 0 <= ny < WORLD_H and 0 <= wcol < WORLD_W:
                        if wm[ny, wcol]:
                            road_nearby = True
                            break

                if road_nearby:
                    zm = res_mask(tm)
                    already_there = False
                    for dy in range(-1, 2):
                        for dx in range(-1, 2):
                            ny, nx = y + dy, left_x + dx
                            if 0 <= ny < WORLD_H and 0 <= nx < WORLD_W:
                                if zm[ny, nx]:
                                    already_there = True
                    if not already_there:
                        return (Tool.RESIDENTIAL, left_x, y)

        # All zones placed, add commercial/industrial for variety
        state["phase"] = 4

    # --- Phase 4: Add commercial zones to boost economy ---
    if state["phase"] == 4:
        rcol = state["road_col"]
        y_min = state["spine_y_min"]
        y_max = state["spine_y_max"]

        rm = road_mask(tm)
        cm = com_mask(tm)

        # Place commercial zones on far right side
        com_x = rcol + 6
        for y in range(y_min, y_max + 1, 3):
            if 0 <= y < WORLD_H and 0 <= com_x < WORLD_W:
                # Need road connection first - extend road
                if not rm[y, rcol + 3]:
                    return (Tool.ROAD, rcol + 3, y)

                already_there = False
                for dy in range(-1, 2):
                    for dx in range(-1, 2):
                        ny, nx = y + dy, com_x + dx
                        if 0 <= ny < WORLD_H and 0 <= nx < WORLD_W:
                            if cm[ny, nx]:
                                already_there = True
                if not already_there:
                    return (Tool.COMMERCIAL, com_x, y)

        # Add industrial zones
        state["phase"] = 5

    # --- Phase 5: Add industrial zones ---
    if state["phase"] == 5:
        rcol = state["road_col"]
        y_min = state["spine_y_min"]
        y_max = state["spine_y_max"]

        rm = road_mask(tm)
        im = ind_mask(tm)

        ind_x = rcol + 10
        for y in range(y_min + 1, y_max, 3):
            if 0 <= y < WORLD_H and 0 <= ind_x < WORLD_W:
                # Extend road if needed
                if not rm[y, rcol + 7]:
                    return (Tool.ROAD, rcol + 7, y)

                already_there = False
                for dy in range(-1, 2):
                    for dx in range(-1, 2):
                        ny, nx = y + dy, ind_x + dx
                        if 0 <= ny < WORLD_H and 0 <= nx < WORLD_W:
                            if im[ny, nx]:
                                already_there = True
                if not already_there:
                    return (Tool.INDUSTRIAL, ind_x, y)

        state["phase"] = 6

    # --- Phase 6: Reactive gap-filling ---
    # Check if there are unpowered zones and try to add more wire
    if state["phase"] == 6:
        powered = obs.powered_zones
        total_res = res_mask(tm).sum()

        # If not enough powered zones, add more wire connections
        if powered < total_res // 9 and powered > 0:
            # Find a wire cell and extend it
            wm = wire_mask(tm)
            wire_positions = np.argwhere(wm)
            if len(wire_positions) > 0:
                # Pick a wire cell and try to extend right
                for wp in wire_positions[:5]:
                    wy, wx = wp
                    if wx + 1 < WORLD_W and not wm[wy, wx + 1]:
                        return (Tool.WIRE, wx + 1, wy)

        # Keep placing more residential zones reactively
        rm = road_mask(tm)
        zm = res_mask(tm)

        # Find road cells and place zones near them
        road_positions = np.argwhere(rm)
        for rp in road_positions:
            ry, rx = rp
            # Try to place zone 3 tiles from road
            for offset in [3, -3]:
                tx = rx + offset
                ty = ry
                if 2 <= tx <= WORLD_W - 3 and 2 <= ty <= WORLD_H - 3:
                    if empty_mask(tm)[ty, tx]:
                        # Check 3x3 area is mostly empty
                        area = tm[ty-1:ty+2, tx-1:tx+2]
                        if (area == 0).sum() >= 6:
                            return (Tool.RESIDENTIAL, tx, ty)

    return None

def act(obs, state):
    if "plan" not in state:
        plan = []

        # Strategy: Build a compact grid-based city centered around (60, 50)
        # with a coal power plant, grid roads, wires, and mixed zoning

        cx, cy = 60, 50  # center

        # Coal power plant at top-left of cluster
        px, py = cx - 15, cy - 15
        plan.append((Tool.COALPOWER, px, py))

        # Wire horizontal from plant rightward along top
        for x in range(px, cx + 20):
            plan.append((Tool.WIRE, x, py))

        # Wire vertical from plant downward
        for y in range(py, cy + 20):
            plan.append((Tool.WIRE, px, y))

        # Wire horizontal mid
        for x in range(px, cx + 20):
            plan.append((Tool.WIRE, x, cy))

        # Wire vertical right side
        for y in range(py, cy + 20):
            plan.append((Tool.WIRE, cx + 18, y))

        # Grid roads: horizontal roads every 4 rows
        for ry in range(py + 2, cy + 18, 4):
            for x in range(px + 2, cx + 18):
                plan.append((Tool.ROAD, x, ry))

        # Grid roads: vertical roads every 4 cols
        for rx in range(px + 2, cx + 18, 4):
            for y in range(py + 2, cy + 18):
                plan.append((Tool.ROAD, rx, y))

        # Place zones in grid cells: 3x3 zones centered between roads
        # Roads at px+2, px+6, px+10, px+14, px+18 (every 4)
        # Zone centers at px+4, px+8, px+12, px+16
        zone_xs = list(range(px + 4, cx + 16, 4))
        zone_ys = list(range(py + 4, cy + 16, 4))

        zone_count = 0
        for zi, zy in enumerate(zone_ys):
            for zj, zx in enumerate(zone_xs):
                # Mix of zones: RCI pattern
                r = (zi * len(zone_xs) + zj) % 9
                if r < 4:
                    tool = Tool.RESIDENTIAL
                elif r < 7:
                    tool = Tool.COMMERCIAL
                else:
                    tool = Tool.INDUSTRIAL
                plan.append((tool, zx, zy))
                zone_count += 1

        # Second coal plant on right side for more power
        px2, py2 = cx + 18, cy
        plan.append((Tool.COALPOWER, px2, py2))

        # Fire and police stations
        plan.append((Tool.FIRESTATION, cx, py + 1))
        plan.append((Tool.POLICESTATION, cx + 10, cy + 15))

        # Second cluster: smaller, offset to lower-right
        cx2, cy2 = 90, 70
        plan.append((Tool.COALPOWER, cx2 - 5, cy2 - 5))

        # Wires for second cluster
        for x in range(cx2 - 5, cx2 + 12):
            plan.append((Tool.WIRE, x, cy2 - 5))
        for y in range(cy2 - 5, cy2 + 12):
            plan.append((Tool.WIRE, cx2 - 5, y))
        for x in range(cx2 - 5, cx2 + 12):
            plan.append((Tool.WIRE, x, cy2 + 10))
        for y in range(cy2 - 5, cy2 + 12):
            plan.append((Tool.WIRE, cx2 + 10, y))

        # Roads for second cluster grid
        for ry in range(cy2 - 3, cy2 + 10, 4):
            for x in range(cx2 - 3, cx2 + 10):
                plan.append((Tool.ROAD, x, ry))
        for rx in range(cx2 - 3, cx2 + 10, 4):
            for y in range(cy2 - 3, cy2 + 10):
                plan.append((Tool.ROAD, rx, y))

        # Zones for second cluster - more commercial focus
        for zi, zy in enumerate(range(cy2 - 1, cy2 + 10, 4)):
            for zj, zx in enumerate(range(cx2 - 1, cx2 + 10, 4)):
                r = (zi * 3 + zj) % 6
                if r < 2:
                    tool = Tool.RESIDENTIAL
                elif r < 5:
                    tool = Tool.COMMERCIAL
                else:
                    tool = Tool.INDUSTRIAL
                plan.append((tool, zx, zy))

        # Connect clusters with road
        for x in range(cx + 18, cx2 - 5):
            plan.append((Tool.ROAD, x, cy + 5))
        # Wire connection between clusters
        for x in range(cx + 18, cx2 - 5):
            plan.append((Tool.WIRE, x, cy + 6))

        state["plan"] = plan
        state["i"] = 0

    i = state["i"]
    plan = state["plan"]

    if i < len(plan):
        state["i"] = i + 1
        tool, x, y = plan[i]
        # Clamp coordinates
        x = max(0, min(119, x))
        y = max(0, min(99, y))
        return (tool, x, y)

    # Reactive phase: add more zones near existing roads
    tm = obs.tile_map
    emp = empty_mask(tm)
    road = road_mask(tm)
    res = res_mask(tm)
    com = com_mask(tm)
    ind = ind_mask(tm)

    # Find empty tiles adjacent to roads
    nbr_road = np.zeros((100, 120), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        ry = np.clip(np.arange(100)[:, None] + dy, 0, 99)
        rx = np.clip(np.arange(120)[None, :] + dx, 0, 119)
        nbr_road |= road[ry, rx]

    cand = emp & nbr_road
    ys, xs = np.where(cand)

    if len(xs) == 0:
        return None

    k = int(obs.step * 7 + tm.sum() % 100) % len(xs)
    x, y = int(xs[k]), int(ys[k])

    # Prefer more residential/commercial
    r = (obs.step * 11 + k) % 10
    if r < 4:
        tool = Tool.RESIDENTIAL
    elif r < 7:
        tool = Tool.COMMERCIAL
    elif r < 9:
        tool = Tool.INDUSTRIAL
    else:
        tool = Tool.ROAD

    return (tool, x, y)

def act(obs, state):
    # Closed-loop policy: each step reads the map and decides next action.
    # Strategy: build a compact cluster centered on map center.
    # Phase 0: place coal plant
    # Phase 1: extend wire spine vertically from plant
    # Phase 2: extend road column adjacent to wire
    # Phase 3: place residential zones flanking road
    # Phase 4: add commercial/industrial zones for balance
    # All phases check current tile_map before acting.

    cx, cy = WORLD_W // 2, WORLD_H // 2

    # Power plant target position (left of spine)
    plant_x, plant_y = cx - 2, cy

    # Wire spine at column cx, road at column cx + 1
    # Zones: residential left at cx-4, right at cx+4
    # Spine extends from cy-15 to cy+15

    SPINE_RANGE = range(cy - 15, cy + 16)

    # Check if power plant already placed
    pm = plant_mask(obs.tile_map)
    rm_road = road_mask(obs.tile_map)
    wm = wire_mask(obs.tile_map)
    res_m = res_mask(obs.tile_map)
    com_m = com_mask(obs.tile_map)
    ind_m = ind_mask(obs.tile_map)
    emp = empty_mask(obs.tile_map)

    def has_tile(mask, x, y):
        if 0 <= y < WORLD_H and 0 <= x < WORLD_W:
            return bool(mask[y, x])
        return False

    # Phase 0: ensure coal plant placed
    if not has_tile(pm, plant_x, plant_y):
        return (Tool.COALPOWER, plant_x, plant_y)

    # Phase 1: place wire along spine column cx for all rows in SPINE_RANGE
    # Find first missing wire in spine
    for dy in SPINE_RANGE:
        if not has_tile(wm, cx, dy) and not has_tile(pm, cx, dy):
            return (Tool.WIRE, cx, dy)

    # Phase 2: place road along column cx+1 for all rows in SPINE_RANGE
    for dy in SPINE_RANGE:
        if not has_tile(rm_road, cx + 1, dy):
            return (Tool.ROAD, cx + 1, dy)

    # Phase 3: place residential zones flanking road
    # Left side: center at cx-4, right side: center at cx+4
    # Zone every 3 rows, center rows in SPINE_RANGE step 3
    for dy in range(cy - 15, cy + 16, 3):
        if 0 <= dy < WORLD_H:
            # Left zone at cx-4
            if not has_tile(res_m, cx - 4, dy) and not has_tile(pm, cx - 4, dy):
                # Check if wire column has power nearby (wire at cx,dy exists)
                if has_tile(wm, cx, dy):
                    return (Tool.RESIDENTIAL, cx - 4, dy)
            # Right zone at cx+4
            if not has_tile(res_m, cx + 4, dy) and not has_tile(pm, cx + 4, dy):
                if has_tile(wm, cx, dy):
                    return (Tool.RESIDENTIAL, cx + 4, dy)

    # Phase 4: add commercial zones on second road column (cx+2 wire, cx+3 road)
    # First ensure second wire and road columns exist
    for dy in SPINE_RANGE:
        if not has_tile(wm, cx + 2, dy) and not has_tile(rm_road, cx + 2, dy):
            return (Tool.WIRE, cx + 2, dy)

    for dy in SPINE_RANGE:
        if not has_tile(rm_road, cx + 3, dy):
            return (Tool.ROAD, cx + 3, dy)

    # Add commercial zones on right side further out at cx+7
    for dy in range(cy - 15, cy + 16, 3):
        if 0 <= dy < WORLD_H:
            if not has_tile(com_m, cx + 7, dy):
                if has_tile(wm, cx + 2, dy):
                    return (Tool.COMMERCIAL, cx + 7, dy)

    # Add industrial zones further left at cx-8
    # Need wire to reach there: place wire from cx-1 leftward
    for dy in range(cy - 15, cy + 16, 3):
        if 0 <= dy < WORLD_H:
            # Wire horizontal connector from cx to cx-7
            for wx in range(cx - 1, cx - 8, -1):
                if not has_tile(wm, wx, dy) and not has_tile(pm, wx, dy):
                    return (Tool.WIRE, wx, dy)

    for dy in range(cy - 15, cy + 16, 3):
        if 0 <= dy < WORLD_H:
            if not has_tile(ind_m, cx - 8, dy):
                if has_tile(wm, cx - 7, dy):
                    return (Tool.INDUSTRIAL, cx - 8, dy)

    # Add a second coal plant if population is growing and funds allow
    if obs.city_pop > 200 and not has_tile(pm, cx + 10, cy):
        # Wire from cx+3 to cx+9
        for wx in range(cx + 4, cx + 10):
            if not has_tile(wm, wx, cy):
                return (Tool.WIRE, wx, cy)
        return (Tool.COALPOWER, cx + 10, cy)

    # Fill in more residential zones on left side second tier
    for dy in range(cy - 14, cy + 16, 3):
        if 0 <= dy < WORLD_H:
            lx = cx - 11
            if not has_tile(res_m, lx, dy):
                # need road nearby
                if has_tile(rm_road, lx + 2, dy) or has_tile(rm_road, lx + 1, dy):
                    return (Tool.RESIDENTIAL, lx, dy)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Read the map every step to decide next action.
    - Place coal plant, then wire spine horizontally, then roads, then zones.
    - Adapt based on what's already on the map.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    # Use center of map as anchor
    cx, cy = 60, 50

    # ---- Phase 1: Ensure power plant exists ----
    if not np.any(pm):
        # Place coal plant with center at (cx-10, cy)
        return (Tool.COALPOWER, cx - 10, cy)

    # Get plant tile positions
    plant_positions = list(zip(*np.where(pm)))  # (row, col)
    # Find bounding box of plant
    if plant_positions:
        plant_cols = [c for (r, c) in plant_positions]
        plant_rows = [r for (r, c) in plant_positions]
        plant_right = max(plant_cols)  # rightmost col of plant footprint
        plant_cy = (min(plant_rows) + max(plant_rows)) // 2  # vertical center of plant

    # ---- Phase 2: Extend horizontal wire spine from plant rightward ----
    # Wire row = plant_cy, from plant_right+1 to cx+20
    wire_row = plant_cy
    wire_start = plant_right + 1
    wire_end = cx + 20

    # Find existing wire positions
    wire_positions = set(zip(*np.where(wm))) if np.any(wm) else set()
    wire_row_cols = sorted([c for (r, c) in wire_positions if r == wire_row])

    # Extend wire along wire_row
    if not wire_row_cols:
        # Start wire adjacent to plant
        if 0 <= wire_row < WORLD_H and 0 <= wire_start < WORLD_W:
            return (Tool.WIRE, wire_start, wire_row)
    else:
        max_wc = max(wire_row_cols)
        if max_wc < wire_end:
            nc = max_wc + 1
            if 0 <= wire_row < WORLD_H and 0 <= nc < WORLD_W:
                return (Tool.WIRE, nc, wire_row)

    # ---- Phase 3: Build vertical road spines at intervals along wire ----
    # Place roads at columns wire_start+2, wire_start+6, wire_start+10, ...
    # Road runs vertically from wire_row-10 to wire_row+10
    road_cols = [wire_start + 2 + i * 7 for i in range(6) if wire_start + 2 + i * 7 <= wire_end]

    road_positions = set(zip(*np.where(rm))) if np.any(rm) else set()

    for rc in road_cols:
        if rc >= WORLD_W:
            continue
        # Check if wire reaches this column
        if rc not in wire_row_cols:
            continue
        # Build vertical road from wire_row-10 to wire_row+10
        road_rows_at_col = sorted([r for (r, c) in road_positions if c == rc])
        target_rows = list(range(max(0, wire_row - 10), min(WORLD_H, wire_row + 11)))
        for rr in target_rows:
            if (rr, rc) not in road_positions:
                if 0 <= rr < WORLD_H:
                    return (Tool.ROAD, rc, rr)

    # ---- Phase 4: Connect wire vertically to reach zone area ----
    # At each road column, extend wire vertically so zones get power
    for rc in road_cols:
        if rc >= WORLD_W or rc not in wire_row_cols:
            continue
        # Extend wire along same road column (or adjacent)
        wc = rc - 1  # wire column just left of road
        for rr in range(max(0, wire_row - 10), min(WORLD_H, wire_row + 11)):
            if (rr, wc) not in wire_positions and 0 <= wc < WORLD_W:
                if em[rr, wc]:
                    return (Tool.WIRE, wc, rr)

    # ---- Phase 5: Place zones adjacent to roads ----
    res_mask_arr = res_mask(tm)
    com_mask_arr = com_mask(tm)
    ind_mask_arr = ind_mask(tm)
    res_count = np.sum(res_mask_arr)
    com_count = np.sum(com_mask_arr)
    ind_count = np.sum(ind_mask_arr)

    res_positions = set(zip(*np.where(res_mask_arr)))
    com_positions = set(zip(*np.where(com_mask_arr)))
    ind_positions = set(zip(*np.where(ind_mask_arr)))

    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc2 = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc2 < 0 or rc2 >= WORLD_W:
                    return False
                if not em[rr, rc2]:
                    return False
        return True

    def has_power_nearby(cr, cc):
        # Check wire or plant within 3 tiles
        for dr in range(-3, 4):
            for dc in range(-3, 4):
                rr, rc2 = cr + dr, cc + dc
                if 0 <= rr < WORLD_H and 0 <= rc2 < WORLD_W:
                    if wm[rr, rc2] or pm[rr, rc2]:
                        return True
        return False

    def has_road_nearby(cr, cc):
        for dr in range(-2, 3):
            for dc in range(-2, 3):
                rr, rc2 = cr + dr, cc + dc
                if 0 <= rr < WORLD_H and 0 <= rc2 < WORLD_W:
                    if rm[rr, rc2]:
                        return True
        return False

    def zone_occupied(cr, cc, zone_set):
        for (pr, pc) in zone_set:
            if abs(pr - cr) <= 2 and abs(pc - cc) <= 2:
                return True
        return False

    # For each road column, try to place zones to the left and right
    for rc in road_cols:
        if rc >= WORLD_W or rc not in wire_row_cols:
            continue
        for zr in range(max(1, wire_row - 9), min(WORLD_H - 1, wire_row + 10), 3):
            # Zone to right of road: center at rc+3
            zc_right = rc + 3
            # Zone to left of road: center at rc-3
            for zc in [rc + 3, rc - 4]:
                if 1 <= zc <= WORLD_W - 2 and 1 <= zr <= WORLD_H - 2:
                    if zone_area_free(zr, zc) and has_power_nearby(zr, zc) and has_road_nearby(zr, zc):
                        all_zones = res_positions | com_positions | ind_positions
                        if not zone_occupied(zr, zc, all_zones):
                            # Decide zone type for balance
                            if com_count < max(1, res_count // 3):
                                return (Tool.COMMERCIAL, zc, zr)
                            elif ind_count < max(1, res_count // 3):
                                return (Tool.INDUSTRIAL, zc, zr)
                            else:
                                return (Tool.RESIDENTIAL, zc, zr)

    # ---- Phase 6: Expand wire spine further if pop is growing ----
    if obs.city_pop > 100:
        # Extend wire spine further
        if wire_row_cols:
            mc = max(wire_row_cols)
            if mc < cx + 35:
                return (Tool.WIRE, mc + 1, wire_row)
        # Add more road columns
        extra_road_cols = [wire_start + 2 + i * 7 for i in range(10)
                          if wire_start + 2 + i * 7 <= cx + 35 and wire_start + 2 + i * 7 < WORLD_W]
        for rc in extra_road_cols:
            if (wire_row, rc) not in wire_positions:
                continue
            for rr in range(max(0, wire_row - 12), min(WORLD_H, wire_row + 13)):
                if (rr, rc) not in road_positions:
                    return (Tool.ROAD, rc, rr)

    # ---- Phase 7: Add stadium or park for score boost ----
    if obs.city_pop > 300 and 'stadium' not in state:
        # Find open area
        sc, sr = cx + 5, cy - 15
        if zone_area_free(sr, sc):
            state['stadium'] = True
            return (Tool.STADIUM, sc, sr)

    return None

def act(obs, state):
    # Strategy: Build a horizontal-spine city with road running east-west,
    # power plant at left, wire along road, zones above and below road.
    # Mix of residential, commercial, industrial for balanced growth.
    # Two neighborhoods: main cluster near center, secondary cluster offset.

    cx, cy = WORLD_W // 2, WORLD_H // 2

    # Main cluster: horizontal road at cy, wire just below at cy+1
    # Power plant at (cx-20, cy)
    # Road from cx-18 to cx+18 at cy
    # Wire from cx-18 to cx+18 at cy+1
    # Zones above (cy-3, cy-6, cy-9) and below (cy+4, cy+7, cy+10) road
    # Zone columns every 3 tiles from cx-18 to cx+18

    ROAD_Y = cy
    WIRE_Y = cy + 1
    PLANT_X = cx - 20
    PLANT_Y = cy
    ROAD_X_START = cx - 18
    ROAD_X_END = cx + 18

    pm = plant_mask(obs.tile_map)
    rm = road_mask(obs.tile_map)
    wm = wire_mask(obs.tile_map)
    res_m = res_mask(obs.tile_map)
    com_m = com_mask(obs.tile_map)
    ind_m = ind_mask(obs.tile_map)

    def has_tile(mask, x, y):
        if 0 <= y < WORLD_H and 0 <= x < WORLD_W:
            return bool(mask[y, x])
        return False

    def any_mask(x, y):
        """Check if something non-empty is at x,y."""
        for m in [pm, rm, wm, res_m, com_m, ind_m]:
            if has_tile(m, x, y):
                return True
        return False

    # Phase 0: place coal power plant
    if not has_tile(pm, PLANT_X, PLANT_Y):
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    # Phase 1: place road along ROAD_Y from ROAD_X_START to ROAD_X_END
    for x in range(ROAD_X_START, ROAD_X_END + 1):
        if not has_tile(rm, x, ROAD_Y) and not has_tile(pm, x, ROAD_Y):
            return (Tool.ROAD, x, ROAD_Y)

    # Phase 2: place wire along WIRE_Y (below road) same x range
    for x in range(ROAD_X_START, ROAD_X_END + 1):
        if not has_tile(wm, x, WIRE_Y) and not has_tile(pm, x, WIRE_Y):
            return (Tool.WIRE, x, WIRE_Y)

    # Connect power plant to wire spine with horizontal wire
    # Wire from plant_x+2 to ROAD_X_START at PLANT_Y (same row as plant)
    # Then vertical wire from (ROAD_X_START, PLANT_Y) to (ROAD_X_START, WIRE_Y)
    for x in range(PLANT_X + 2, ROAD_X_START):
        if not has_tile(wm, x, PLANT_Y) and not has_tile(pm, x, PLANT_Y) and not has_tile(rm, x, PLANT_Y):
            return (Tool.WIRE, x, PLANT_Y)

    # Vertical connector from PLANT_Y to WIRE_Y at ROAD_X_START
    if PLANT_Y != WIRE_Y:
        y_lo = min(PLANT_Y, WIRE_Y)
        y_hi = max(PLANT_Y, WIRE_Y)
        for y in range(y_lo, y_hi + 1):
            if not has_tile(wm, ROAD_X_START, y) and not has_tile(pm, ROAD_X_START, y) and not has_tile(rm, ROAD_X_START, y):
                return (Tool.WIRE, ROAD_X_START, y)

    # Phase 3: place zones above and below road
    # Zone centers at ROAD_Y-3 (above), ROAD_Y+4 (below, skip wire at WIRE_Y=cy+1)
    # Also ROAD_Y-6, ROAD_Y+7 for second tier
    # Zone columns every 3 tiles
    zone_xs = list(range(ROAD_X_START + 1, ROAD_X_END, 3))

    zone_rows_above = [ROAD_Y - 3, ROAD_Y - 6]
    zone_rows_below = [ROAD_Y + 4, ROAD_Y + 7]

    # Cycle zone types: R, R, C, I, R, C, I...
    zone_types = [Tool.RESIDENTIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL,
                  Tool.INDUSTRIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL,
                  Tool.INDUSTRIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL,
                  Tool.INDUSTRIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL,
                  Tool.INDUSTRIAL]

    def get_zone_type(idx):
        return zone_types[idx % len(zone_types)]

    # Place zones above road
    for row in zone_rows_above:
        if 2 <= row < WORLD_H - 2:
            for i, x in enumerate(zone_xs):
                if 2 <= x < WORLD_W - 2:
                    zt = get_zone_type(i)
                    zm = res_m if zt == Tool.RESIDENTIAL else (com_m if zt == Tool.COMMERCIAL else ind_m)
                    if not has_tile(zm, x, row) and not has_tile(pm, x, row):
                        # need wire nearby - check wire at WIRE_Y or PLANT_Y
                        return (zt, x, row)

    # Place zones below road
    for row in zone_rows_below:
        if 2 <= row < WORLD_H - 2:
            for i, x in enumerate(zone_xs):
                if 2 <= x < WORLD_W - 2:
                    zt = get_zone_type(i + 3)
                    zm = res_m if zt == Tool.RESIDENTIAL else (com_m if zt == Tool.COMMERCIAL else ind_m)
                    if not has_tile(zm, x, row) and not has_tile(pm, x, row):
                        return (zt, x, row)

    # Phase 4: second neighborhood - offset by 30 rows down
    cy2 = cy + 30
    ROAD_Y2 = cy2
    WIRE_Y2 = cy2 + 1
    PLANT_X2 = cx - 20
    PLANT_Y2 = cy2

    if ROAD_Y2 < WORLD_H - 5 and WIRE_Y2 < WORLD_H - 2:
        # Second power plant
        if not has_tile(pm, PLANT_X2, PLANT_Y2):
            return (Tool.COALPOWER, PLANT_X2, PLANT_Y2)

        # Road
        for x in range(ROAD_X_START, ROAD_X_END + 1):
            if not has_tile(rm, x, ROAD_Y2) and not has_tile(pm, x, ROAD_Y2):
                return (Tool.ROAD, x, ROAD_Y2)

        # Wire
        for x in range(ROAD_X_START, ROAD_X_END + 1):
            if not has_tile(wm, x, WIRE_Y2) and not has_tile(pm, x, WIRE_Y2):
                return (Tool.WIRE, x, WIRE_Y2)

        # Connect plant2 to wire
        for x in range(PLANT_X2 + 2, ROAD_X_START):
            if not has_tile(wm, x, PLANT_Y2) and not has_tile(pm, x, PLANT_Y2) and not has_tile(rm, x, PLANT_Y2):
                return (Tool.WIRE, x, PLANT_Y2)

        # Vertical connector
        y_lo2 = min(PLANT_Y2, WIRE_Y2)
        y_hi2 = max(PLANT_Y2, WIRE_Y2)
        for y in range(y_lo2, y_hi2 + 1):
            if not has_tile(wm, ROAD_X_START, y) and not has_tile(pm, ROAD_X_START, y) and not has_tile(rm, ROAD_X_START, y):
                return (Tool.WIRE, ROAD_X_START, y)

        # Zones for second neighborhood
        zone_rows_above2 = [ROAD_Y2 - 3]
        zone_rows_below2 = [ROAD_Y2 + 4]

        for row in zone_rows_above2:
            if 2 <= row < WORLD_H - 2:
                for i, x in enumerate(zone_xs):
                    if 2 <= x < WORLD_W - 2:
                        zt = get_zone_type(i + 1)
                        zm = res_m if zt == Tool.RESIDENTIAL else (com_m if zt == Tool.COMMERCIAL else ind_m)
                        if not has_tile(zm, x, row) and not has_tile(pm, x, row):
                            return (zt, x, row)

        for row in zone_rows_below2:
            if 2 <= row < WORLD_H - 2:
                for i, x in enumerate(zone_xs):
                    if 2 <= x < WORLD_W - 2:
                        zt = get_zone_type(i + 2)
                        zm = res_m if zt == Tool.RESIDENTIAL else (com_m if zt == Tool.COMMERCIAL else ind_m)
                        if not has_tile(zm, x, row) and not has_tile(pm, x, row):
                            return (zt, x, row)

    # Add police/fire stations for city services
    if obs.city_pop > 100:
        svc_x = cx
        if not any_mask(svc_x, ROAD_Y - 10):
            return (Tool.FIRESTATION, svc_x, ROAD_Y - 10)
        if not any_mask(svc_x + 5, ROAD_Y - 10):
            return (Tool.POLICESTATION, svc_x + 5, ROAD_Y - 10)

    return None

def act(obs, state):
    """
    Improved policy: build a horizontal layout with two power plants,
    a horizontal road/wire spine, and zones above and below.
    Mix of residential, commercial, and industrial zones.
    """
    tm = obs.tile_map
    step = obs.step

    # Use a horizontal spine in the middle of the map
    spine_y = WORLD_H // 2  # row 50
    start_x = 20
    end_x = 100

    em = empty_mask(tm)
    rm = road_mask(tm)
    wm = wire_mask(tm)
    pm = plant_mask(tm)

    res_positions = list(zip(*np.where(res_mask(tm))))
    com_positions = list(zip(*np.where(com_mask(tm))))
    ind_positions = list(zip(*np.where(ind_mask(tm))))

    res_count = len(res_positions)
    com_count = len(com_positions)
    ind_count = len(ind_positions)

    # Phase 1: Place two coal power plants
    # Plant 1 at (25, spine_y), Plant 2 at (75, spine_y+offset)
    plant1_x, plant1_y = 22, spine_y
    plant2_x, plant2_y = 72, spine_y

    plant_positions = list(zip(*np.where(pm)))
    plant_count = len(plant_positions)

    if plant_count == 0:
        return (Tool.COALPOWER, plant1_x, plant1_y)

    # Check if second plant exists (plant occupies 3x3, center at plant2_x, plant2_y)
    # Look for plant tiles near plant2
    has_plant2 = any(abs(r - plant2_y) <= 1 and abs(c - plant2_x) <= 1 
                     for (r, c) in plant_positions)
    if not has_plant2 and plant_count > 0:
        # Only place second plant once we have enough steps
        if step > 30:
            return (Tool.COALPOWER, plant2_x, plant2_y)

    # Phase 2: Build horizontal wire spine from plant1 to end
    wire_y = spine_y
    # Wire from plant1_x+2 to end_x
    wire_start = plant1_x + 2  # right edge of plant1 footprint +1

    # Find current wire extent along spine_y row
    wire_row_cols = sorted([c for (r, c) in zip(*np.where(wm)) if r == wire_y]) if np.any(wm) else []

    if not wire_row_cols:
        # Start wire adjacent to plant
        wc = plant1_x + 2
        if 0 <= wc < WORLD_W:
            return (Tool.WIRE, wc, wire_y)
    else:
        max_wc = max(wire_row_cols)
        # Extend wire rightward
        if max_wc < end_x:
            nc = max_wc + 1
            # Skip over plant2 footprint area (bulldoze-safe: just place wire through)
            if 0 <= nc < WORLD_W:
                return (Tool.WIRE, nc, wire_y)

    wire_row_cols = sorted([c for (r, c) in zip(*np.where(wm)) if r == wire_y]) if np.any(wm) else []

    # Phase 3: Build road above and below the wire spine
    road_above_y = spine_y - 2  # row above for zones above
    road_below_y = spine_y + 2  # row below for zones below

    road_above_cols = set(c for (r, c) in zip(*np.where(rm)) if r == road_above_y) if np.any(rm) else set()
    road_below_cols = set(c for (r, c) in zip(*np.where(rm)) if r == road_below_y) if np.any(rm) else set()

    # Build roads parallel to wire, for columns where wire exists
    for wc in wire_row_cols:
        if wc not in road_above_cols:
            if 0 <= road_above_y < WORLD_H:
                t = tm[road_above_y, wc]
                # Don't overwrite zones or plants
                if em[road_above_y, wc] or rm[road_above_y, wc]:
                    return (Tool.ROAD, wc, road_above_y)
        if wc not in road_below_cols:
            if 0 <= road_below_y < WORLD_H:
                if em[road_below_y, wc] or rm[road_below_y, wc]:
                    return (Tool.ROAD, wc, road_below_y)

    # Phase 4: Place zones above and below roads
    # Zones above: center_y = road_above_y - 2 = spine_y - 4
    # Zones below: center_y = road_below_y + 2 = spine_y + 4
    zone_above_y = road_above_y - 2  # spine_y - 4 = 46
    zone_below_y = road_below_y + 2  # spine_y + 4 = 54

    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def near_road(cr, cc, road_y):
        # Check if any road tile within distance 2 of zone center
        for dc in [-2, -1, 0, 1, 2]:
            rc = cc + dc
            if 0 <= rc < WORLD_W and rm[road_y, rc]:
                return True
        return False

    def near_wire(cr, cc):
        # Check wire within 3 tiles
        for dr in [-3, -2, -1, 0, 1, 2, 3]:
            for dc in [-3, -2, -1, 0, 1, 2, 3]:
                rr, rc = cr + dr, cc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if wm[rr, rc]:
                        return True
        return False

    # Place zones at every 3 columns along the wire extent
    all_zone_slots = []
    for wc in wire_row_cols:
        # Only place zones at multiples of 3 offset from start
        if (wc - start_x) % 3 == 0:
            all_zone_slots.append((zone_above_y, wc, 'above'))
            all_zone_slots.append((zone_below_y, wc, 'below'))

    # Determine zone type based on position and current counts
    for (zy, zx, side) in all_zone_slots:
        if 0 <= zy < WORLD_H and 0 <= zx < WORLD_W:
            # Check if already occupied
            already_res = any(abs(zy - pr) <= 1 and abs(zx - pc) <= 1 for (pr, pc) in res_positions)
            already_com = any(abs(zy - pr) <= 1 and abs(zx - pc) <= 1 for (pr, pc) in com_positions)
            already_ind = any(abs(zy - pr) <= 1 and abs(zx - pc) <= 1 for (pr, pc) in ind_positions)

            if already_res or already_com or already_ind:
                continue

            road_y_check = road_above_y if side == 'above' else road_below_y

            if near_wire(zy, zx) and near_road(zy, zx, road_y_check) and zone_area_free(zy, zx):
                # Zone type selection: 
                # - Left third: mostly industrial
                # - Middle third: mixed res/com
                # - Right third: mostly residential
                zone_range = end_x - start_x
                rel_x = zx - start_x

                if rel_x < zone_range // 3:
                    # Left: industrial
                    if ind_count < res_count * 0.4 + 1:
                        return (Tool.INDUSTRIAL, zx, zy)
                    else:
                        return (Tool.RESIDENTIAL, zx, zy)
                elif rel_x < 2 * zone_range // 3:
                    # Middle: commercial
                    if com_count < res_count * 0.4 + 1:
                        return (Tool.COMMERCIAL, zx, zy)
                    else:
                        return (Tool.RESIDENTIAL, zx, zy)
                else:
                    # Right: residential
                    return (Tool.RESIDENTIAL, zx, zy)

    # Phase 5: Add vertical connector roads to reach more zones
    # Add a second tier of zones further out
    zone_above2_y = zone_above_y - 4  # spine_y - 8
    zone_below2_y = zone_below_y + 4  # spine_y + 8
    road_above2_y = zone_above_y - 2  # spine_y - 6
    road_below2_y = zone_below_y + 2  # spine_y + 6

    if obs.city_pop > 100:
        road_above2_cols = set(c for (r, c) in zip(*np.where(rm)) if r == road_above2_y) if np.any(rm) else set()
        road_below2_cols = set(c for (r, c) in zip(*np.where(rm)) if r == road_below2_y) if np.any(rm) else set()

        for wc in wire_row_cols:
            if (wc - start_x) % 3 == 0:
                if wc not in road_above2_cols and 0 <= road_above2_y < WORLD_H:
                    if em[road_above2_y, wc] or rm[road_above2_y, wc]:
                        return (Tool.ROAD, wc, road_above2_y)
                if wc not in road_below2_cols and 0 <= road_below2_y < WORLD_H:
                    if em[road_below2_y, wc] or rm[road_below2_y, wc]:
                        return (Tool.ROAD, wc, road_below2_y)

        # Connect vertical roads between road_above_y and road_above2_y
        for wc in wire_row_cols:
            if (wc - start_x) % 6 == 0:
                for ry in range(road_above2_y, road_above_y + 1):
                    if 0 <= ry < WORLD_H and (em[ry, wc] or rm[ry, wc]):
                        if not rm[ry, wc]:
                            return (Tool.ROAD, wc, ry)
                for ry in range(road_below_y, road_below2_y + 1):
                    if 0 <= ry < WORLD_H and (em[ry, wc] or rm[ry, wc]):
                        if not rm[ry, wc]:
                            return (Tool.ROAD, wc, ry)

    if obs.city_pop > 100:
        for (zy, zx, side) in [(zone_above2_y, wc, 'above2') for wc in wire_row_cols if (wc - start_x) % 3 == 0] + \
                               [(zone_below2_y, wc, 'below2') for wc in wire_row_cols if (wc - start_x) % 3 == 0]:
            if 0 <= zy < WORLD_H and 0 <= zx < WORLD_W:
                already_res = any(abs(zy - pr) <= 1 and abs(zx - pc) <= 1 for (pr, pc) in res_positions)
                already_com = any(abs(zy - pr) <= 1 and abs(zx - pc) <= 1 for (pr, pc) in com_positions)
                already_ind = any(abs(zy - pr) <= 1 and abs(zx - pc) <= 1 for (pr, pc) in ind_positions)
                if already_res or already_com or already_ind:
                    continue
                road_y_check = road_above2_y if side == 'above2' else road_below2_y
                if near_wire(zy, zx) and near_road(zy, zx, road_y_check) and zone_area_free(zy, zx):
                    return (Tool.RESIDENTIAL, zx, zy)

    return None

def act(obs, state):
    # Closed-loop policy: reads tile_map each step to decide next action.
    # Strategy: build a compact cluster around center with coal power + wire spine + roads + zones.
    # Adapts based on what's actually on the map.

    tm = obs.tile_map
    pm = plant_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)
    emp = empty_mask(tm)

    cx, cy = 60, 50  # map center

    def has(mask, x, y):
        if 0 <= x < WORLD_W and 0 <= y < WORLD_H:
            return bool(mask[y, x])
        return False

    def is_empty(x, y):
        if 0 <= x < WORLD_W and 0 <= y < WORLD_H:
            return bool(emp[y, x])
        return False

    # ---- Phase 0: Place coal power plant ----
    px, py = cx - 2, cy
    if not has(pm, px, py):
        return (Tool.COALPOWER, px, py)

    # ---- Phase 1: Wire spine vertically from plant at column cx ----
    # Wire from cy-15 to cy+15 at cx
    for dy in range(cy - 15, cy + 16):
        if 0 <= dy < WORLD_H:
            if not has(wm, cx, dy) and not has(pm, cx, dy):
                return (Tool.WIRE, cx, dy)

    # ---- Phase 2: Road column at cx+1 (right of wire spine) ----
    for dy in range(cy - 15, cy + 16):
        if 0 <= dy < WORLD_H:
            if not has(rm, cx + 1, dy):
                return (Tool.ROAD, cx + 1, dy)

    # ---- Phase 3: Road column at cx-1 (left of wire spine) ----
    for dy in range(cy - 15, cy + 16):
        if 0 <= dy < WORLD_H:
            if not has(rm, cx - 1, dy):
                return (Tool.ROAD, cx - 1, dy)

    # ---- Phase 4: Residential zones at cx+4 and cx-4, every 3 rows ----
    for dy in range(cy - 12, cy + 13, 3):
        if 0 <= dy < WORLD_H:
            # Right residential
            if not has(res_m, cx + 4, dy) and not has(pm, cx + 4, dy):
                if has(wm, cx, dy) and has(rm, cx + 1, dy):
                    return (Tool.RESIDENTIAL, cx + 4, dy)
            # Left residential
            if not has(res_m, cx - 4, dy) and not has(pm, cx - 4, dy):
                if has(wm, cx, dy) and has(rm, cx - 1, dy):
                    return (Tool.RESIDENTIAL, cx - 4, dy)

    # ---- Phase 5: Second wire column at cx+2, road at cx+3 ----
    for dy in range(cy - 15, cy + 16):
        if 0 <= dy < WORLD_H:
            if not has(wm, cx + 2, dy) and not has(rm, cx + 2, dy) and not has(pm, cx + 2, dy):
                return (Tool.WIRE, cx + 2, dy)

    for dy in range(cy - 15, cy + 16):
        if 0 <= dy < WORLD_H:
            if not has(rm, cx + 3, dy):
                return (Tool.ROAD, cx + 3, dy)

    # ---- Phase 6: Commercial zones at cx+7 ----
    for dy in range(cy - 12, cy + 13, 3):
        if 0 <= dy < WORLD_H:
            if not has(com_m, cx + 7, dy) and not has(pm, cx + 7, dy):
                if has(wm, cx + 2, dy) and has(rm, cx + 3, dy):
                    return (Tool.COMMERCIAL, cx + 7, dy)

    # ---- Phase 7: Wire left, road left, industrial at cx-8 ----
    # Wire horizontal connectors at zone rows from cx-1 leftward to cx-7
    for dy in range(cy - 12, cy + 13, 3):
        if 0 <= dy < WORLD_H:
            for wx in range(cx - 1, cx - 8, -1):
                if not has(wm, wx, dy) and not has(pm, wx, dy) and not has(rm, wx, dy):
                    return (Tool.WIRE, wx, dy)

    # Road at cx-2 column (already have cx-1)
    for dy in range(cy - 15, cy + 16):
        if 0 <= dy < WORLD_H:
            if not has(rm, cx - 3, dy) and not has(pm, cx - 3, dy):
                # Only if wire exists at cx-1,dy
                if has(wm, cx - 1, dy) or has(wm, cx, dy):
                    return (Tool.ROAD, cx - 3, dy)

    for dy in range(cy - 12, cy + 13, 3):
        if 0 <= dy < WORLD_H:
            if not has(ind_m, cx - 8, dy) and not has(pm, cx - 8, dy):
                if has(wm, cx - 7, dy):
                    return (Tool.INDUSTRIAL, cx - 8, dy)

    # ---- Phase 8: Second power plant if city growing ----
    px2, py2 = cx + 15, cy
    if obs.city_pop > 100 and not has(pm, px2, py2):
        # Wire from cx+3 to px2-1
        for wx in range(cx + 4, px2):
            if not has(wm, wx, cy) and not has(rm, wx, cy):
                return (Tool.WIRE, wx, cy)
        return (Tool.COALPOWER, px2, py2)

    # Wire spine for second plant
    if has(pm, px2, py2):
        for dy in range(cy - 12, cy + 13):
            if 0 <= dy < WORLD_H:
                if not has(wm, px2 + 2, dy) and not has(pm, px2 + 2, dy):
                    return (Tool.WIRE, px2 + 2, dy)
        for dy in range(cy - 12, cy + 13):
            if 0 <= dy < WORLD_H:
                if not has(rm, px2 + 3, dy):
                    return (Tool.ROAD, px2 + 3, dy)
        for dy in range(cy - 9, cy + 10, 3):
            if 0 <= dy < WORLD_H:
                if not has(res_m, px2 + 6, dy) and not has(pm, px2 + 6, dy):
                    if has(wm, px2 + 2, dy):
                        return (Tool.RESIDENTIAL, px2 + 6, dy)

    # ---- Phase 9: Services ----
    if obs.city_pop > 50:
        if not has(pm, cx, cy - 18) and not has(rm, cx, cy - 18):
            # Check if fire station needed
            if is_empty(cx + 2, cy - 18):
                return (Tool.FIRESTATION, cx + 2, cy - 18)
        if is_empty(cx - 3, cy + 18):
            return (Tool.POLICESTATION, cx - 3, cy + 18)

    # ---- Reactive gap-fill: scan for empty tiles adjacent to roads with wire nearby ----
    # Find powered rows (wire present)
    powered_rows = set()
    for dy in range(WORLD_H):
        for dx in range(WORLD_W):
            if has(wm, dx, dy) or has(pm, dx, dy):
                powered_rows.add(dy)

    # Find empty cells near roads in powered rows
    candidates = []
    for dy in range(1, WORLD_H - 1):
        if dy not in powered_rows:
            continue
        for dx in range(1, WORLD_W - 1):
            if not is_empty(dx, dy):
                continue
            # Near a road?
            near_road = (has(rm, dx-1, dy) or has(rm, dx+1, dy) or
                         has(rm, dx, dy-1) or has(rm, dx, dy+1))
            if near_road:
                candidates.append((dx, dy))

    if candidates:
        # Pick deterministically
        k = (obs.step * 7 + int(tm[cy, cx])) % len(candidates)
        x, y = candidates[k]
        # Zone mix based on existing counts
        n_res = int(res_m.sum())
        n_com = int(com_m.sum())
        n_ind = int(ind_m.sum())
        total = n_res + n_com + n_ind + 1
        if n_res / total < 0.5:
            return (Tool.RESIDENTIAL, x, y)
        elif n_com / total < 0.3:
            return (Tool.COMMERCIAL, x, y)
        elif n_ind / total < 0.2:
            return (Tool.INDUSTRIAL, x, y)
        else:
            return (Tool.RESIDENTIAL, x, y)

    return None

def act(obs, state):
    """
    Closed-loop policy: each step reads the current map and decides
    what to place next based on observed state.

    Strategy:
    - Phase 0: Place coal power plant at center-left
    - Phase 1: Extend wire spine vertically from plant
    - Phase 2: Extend road spine adjacent to wire
    - Phase 3: Place zones adjacent to roads/wires
    - Ongoing: React to map, fill gaps, add services
    """
    tm = obs.tile_map
    step = obs.step

    # Light state: just a phase tracker
    if "phase" not in state:
        state["phase"] = 0
        state["tick"] = 0

    state["tick"] += 1

    # Core layout constants
    cx, cy = 60, 50  # center of map

    # Get current masks
    emp = empty_mask(tm)
    roads = road_mask(tm)
    wires = wire_mask(tm)
    plants = plant_mask(tm)
    res = res_mask(tm)
    com = com_mask(tm)
    ind = ind_mask(tm)
    any_zone = res | com | ind

    # Helper: is tile in bounds?
    def ok(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Helper: check if a tile is empty
    def is_empty(x, y):
        return ok(x, y) and emp[y, x]

    # Helper: find nearest empty tile in a direction from a set
    def find_frontier(mask, direction_priority):
        ys, xs = np.where(mask)
        if len(xs) == 0:
            return None
        # Try extending in each direction
        for dy, dx in direction_priority:
            for i in range(len(xs)):
                nx, ny = int(xs[i]) + dx, int(ys[i]) + dy
                if is_empty(nx, ny):
                    return nx, ny
        return None

    # Phase 0: Place the coal power plant
    if not np.any(plants):
        # No plant yet, place one
        px, py = cx - 3, cy
        if ok(px, py):
            return (Tool.COALPOWER, px, py)

    # Phase 1: Build vertical wire spine from plant upward/downward
    # Wire column at cx-2
    wire_col = cx - 2
    # Count existing wires in our column
    wire_in_col = np.sum(wires[:, wire_col]) if ok(wire_col, 0) else 0

    # We want wires from cy-14 to cy+14
    wire_top = cy - 14
    wire_bot = cy + 14

    # Find gaps in wire column
    if ok(wire_col, cy):
        for dy in range(0, 15):
            for sign in [1, -1]:
                wy = cy + sign * dy
                if ok(wire_col, wy) and not wires[wy, wire_col] and not plants[wy, wire_col]:
                    if wire_top <= wy <= wire_bot:
                        return (Tool.WIRE, wire_col, wy)

    # Phase 2: Build road spine adjacent to wire (cx-1 column)
    road_col = cx - 1
    # Also a road column on the other side: cx
    road_col2 = cx

    for dy in range(0, 15):
        for sign in [1, -1]:
            ry = cy + sign * dy
            if ok(road_col, ry) and not roads[ry, road_col] and not wires[ry, road_col] and not plants[ry, road_col]:
                if wire_top <= ry <= wire_bot:
                    return (Tool.ROAD, road_col, ry)

    # Also add road on the right side of wire
    for dy in range(0, 15):
        for sign in [1, -1]:
            ry = cy + sign * dy
            if ok(road_col2, ry) and not roads[ry, road_col2] and not wires[ry, road_col2] and not plants[ry, road_col2]:
                if wire_top <= ry <= wire_bot:
                    return (Tool.ROAD, road_col2, ry)

    # Phase 3: Place zones flanking the road/wire spine
    # Left zones at cx-4 (center of 3x3 = road at cx-1, so zone center at cx-4)
    # Right zones at cx+2

    # Determine zone type based on position and population ratios
    def pick_zone(y_pos, x_pos):
        # Mix of zones: mostly residential, some commercial, some industrial
        h = (y_pos * 17 + x_pos * 7 + step * 3) % 10
        if h < 5:
            return Tool.RESIDENTIAL
        elif h < 7:
            return Tool.COMMERCIAL
        else:
            return Tool.INDUSTRIAL

    # Place left-side zones (center at cx-4, flanking road_col)
    left_zx = cx - 4
    right_zx = cx + 3

    # Scan for zone placements
    # Each zone is 3x3, centers every 3 rows
    for dy in range(-12, 13, 3):
        zy = cy + dy
        if not ok(left_zx, zy):
            continue
        # Check if there's no zone near this spot
        already = any_zone[max(0,zy-1):min(100,zy+2), max(0,left_zx-1):min(120,left_zx+2)]
        if not np.any(already):
            # Check road adjacency (within 2 tiles)
            road_near = np.any(roads[max(0,zy-2):min(100,zy+3), max(0,left_zx-2):min(120,left_zx+3)])
            wire_near = np.any(wires[max(0,zy-2):min(100,zy+3), max(0,left_zx-2):min(120,left_zx+3)])
            if road_near or wire_near:
                return (pick_zone(zy, left_zx), left_zx, zy)

    for dy in range(-12, 13, 3):
        zy = cy + dy
        if not ok(right_zx, zy):
            continue
        already = any_zone[max(0,zy-1):min(100,zy+2), max(0,right_zx-1):min(120,right_zx+2)]
        if not np.any(already):
            road_near = np.any(roads[max(0,zy-2):min(100,zy+3), max(0,right_zx-2):min(120,right_zx+3)])
            wire_near = np.any(wires[max(0,zy-2):min(100,zy+3), max(0,right_zx-2):min(120,right_zx+3)])
            if road_near or wire_near:
                return (pick_zone(zy, right_zx), right_zx, zy)

    # Phase 4: Expand horizontally - add more road/wire spines
    # Add horizontal roads connecting to extend the grid
    # Horizontal road at cy (middle)
    for dx in range(-15, 15):
        hx = cx + dx
        hy = cy
        if ok(hx, hy) and not roads[hy, hx] and not wires[hy, hx] and not plants[hy, hx]:
            # Only extend if adjacent to existing road/wire
            adj_road = any(
                (ok(hx+ddx, hy+ddy) and (roads[hy+ddy, hx+ddx] or wires[hy+ddy, hx+ddx] or plants[hy+ddy, hx+ddx]))
                for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]
                if ok(hx+ddx, hy+ddy)
            )
            if adj_road:
                return (Tool.ROAD, hx, hy)

    # Phase 5: Add a second power cluster to the right
    if obs.city_pop > 100:
        cx2 = cx + 20
        # Check if we have a plant there
        plant_right = np.any(plants[:, max(0,cx2-3):min(120,cx2+3)])
        if not plant_right:
            return (Tool.COALPOWER, cx2 + 2, cy)

        # Wire spine for right cluster
        wire_col2 = cx2 + 2
        for dy in range(0, 12):
            for sign in [1, -1]:
                wy = cy + sign * dy
                if ok(wire_col2, wy) and not wires[wy, wire_col2] and not plants[wy, wire_col2]:
                    if wire_top <= wy <= wire_bot:
                        return (Tool.WIRE, wire_col2, wy)

        # Road for right cluster
        road_col3 = cx2 + 1
        for dy in range(0, 12):
            for sign in [1, -1]:
                ry = cy + sign * dy
                if ok(road_col3, ry) and not roads[ry, road_col3] and not wires[ry, road_col3] and not plants[ry, road_col3]:
                    if wire_top <= ry <= wire_bot:
                        return (Tool.ROAD, road_col3, ry)

        # Zones for right cluster
        for dy in range(-9, 10, 3):
            zy = cy + dy
            rzx = cx2 - 1
            if ok(rzx, zy):
                already = any_zone[max(0,zy-1):min(100,zy+2), max(0,rzx-1):min(120,rzx+2)]
                if not np.any(already):
                    road_near = np.any(roads[max(0,zy-2):min(100,zy+3), max(0,rzx-2):min(120,rzx+3)])
                    wire_near = np.any(wires[max(0,zy-2):min(100,zy+3), max(0,rzx-2):min(120,rzx+3)])
                    if road_near or wire_near:
                        return (pick_zone(zy, rzx), rzx, zy)

            rzx2 = cx2 + 5
            if ok(rzx2, zy):
                already = any_zone[max(0,zy-1):min(100,zy+2), max(0,rzx2-1):min(120,rzx2+2)]
                if not np.any(already):
                    road_near = np.any(roads[max(0,zy-2):min(100,zy+3), max(0,rzx2-2):min(120,rzx2+3)])
                    wire_near = np.any(wires[max(0,zy-2):min(100,zy+3), max(0,rzx2-2):min(120,rzx2+3)])
                    if road_near or wire_near:
                        return (pick_zone(zy, rzx2), rzx2, zy)

    # Phase 6: Add services if population growing
    if obs.city_pop > 50:
        # Add fire/police stations
        fs_placed = False
        for y in range(WORLD_H):
            for x in range(WORLD_W):
                tid = tm[y, x]
                # Check if it's a fire station tile (rough check)
                if tid in range(428, 436):
                    fs_placed = True
                    break
        if not fs_placed:
            return (Tool.FIRESTATION, cx - 8, cy)

    if obs.city_pop > 150:
        ps_placed = False
        for y in range(WORLD_H):
            for x in range(WORLD_W):
                tid = tm[y, x]
                if tid in range(436, 444):
                    ps_placed = True
                    break
        if not ps_placed:
            return (Tool.POLICESTATION, cx + 8, cy)

    # Reactive fallback: find any empty tile near road and place a zone
    # Build neighbor road mask
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1),(-2,0),(2,0),(0,-2),(0,2)]:
        ys_r = np.arange(WORLD_H)
        xs_r = np.arange(WORLD_W)
        ny = np.clip(ys_r + dy, 0, WORLD_H-1)
        nx = np.clip(xs_r + dx, 0, WORLD_W-1)
        nbr_road |= roads[np.ix_(ny, xs_r)]
        nbr_road |= roads[np.ix_(ys_r, nx)]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1),(-2,0),(2,0),(0,-2),(0,2)]:
        ys_r = np.arange(WORLD_H)
        xs_r = np.arange(WORLD_W)
        ny = np.clip(ys_r + dy, 0, WORLD_H-1)
        nx = np.clip(xs_r + dx, 0, WORLD_W-1)
        nbr_wire |= wires[np.ix_(ny, xs_r)]
        nbr_wire |= wires[np.ix_(ys_r, nx)]

    cand = emp & (nbr_road | nbr_wire)
    ys_c, xs_c = np.where(cand)

    if len(xs_c) > 0:
        k = (step * 13 + state["tick"] * 7) % len(xs_c)
        x, y = int(xs_c[k]), int(ys_c[k])
        tool = pick_zone(y, x)
        return (tool, x, y)

    return None

def act(obs, state):
    """
    Closed-loop policy: each step reads the current tile_map and decides
    what to place based on what actually exists on the map.

    Strategy:
    1. If no power plant exists, place one.
    2. Extend wires from the power plant outward (vertical spine).
    3. Extend roads parallel to wires for zone access.
    4. Place zones (RES, COM, IND mix) adjacent to roads and powered areas.
    5. React to map state each step rather than replaying a fixed plan.
    """
    tm = obs.tile_map

    # Anchor column layout: power spine at cx, road at cx+1, zones at cx-3 and cx+4
    cx = WORLD_W // 2  # 60
    cy = WORLD_H // 2  # 50

    emp = empty_mask(tm)
    wires = wire_mask(tm)
    roads = road_mask(tm)
    plants = plant_mask(tm)
    res = res_mask(tm)
    com = com_mask(tm)
    ind = ind_mask(tm)

    # Step 1: Ensure we have a power plant
    # Check if any plant exists
    if not np.any(plants):
        # Place coal power plant - it's 4x4, place center at cx, cy
        return (Tool.COALPOWER, cx, cy)

    # Find plant location (approximate center)
    plant_ys, plant_xs = np.where(plants)
    if len(plant_xs) == 0:
        return (Tool.COALPOWER, cx, cy)

    # Step 2: Extend wire spine vertically from plant area
    # Wire runs along column cx, from plant outward
    # Find extent of current wire
    wire_col = wires[:, cx]  # boolean array of height 100
    wire_rows = np.where(wire_col)[0]

    # Target wire extent: 15 rows above and below cy
    wire_top_target = max(cy - 15, 2)
    wire_bot_target = min(cy + 15, 97)

    # Try to extend wire upward
    if len(wire_rows) > 0:
        top_wire = wire_rows.min()
        bot_wire = wire_rows.max()
    else:
        # No wire yet - place wire adjacent to plant
        # Plant is around cx, cy - place wire just above
        if cy - 1 >= 0 and emp[cy - 1, cx]:
            return (Tool.WIRE, cx, cy - 1)
        elif cy + 1 < WORLD_H and emp[cy + 1, cx]:
            return (Tool.WIRE, cx, cy + 1)
        else:
            return (Tool.WIRE, cx, cy - 2)

    # Extend wire if not at target
    if top_wire > wire_top_target:
        new_y = top_wire - 1
        if 0 <= new_y < WORLD_H:
            return (Tool.WIRE, cx, new_y)
    if bot_wire < wire_bot_target:
        new_y = bot_wire + 1
        if 0 <= new_y < WORLD_H:
            return (Tool.WIRE, cx, new_y)

    # Step 3: Extend road spine parallel to wire (column cx+2)
    road_col_x = cx + 2
    road_col = roads[:, road_col_x]
    road_rows = np.where(road_col)[0]

    road_top_target = wire_top_target
    road_bot_target = wire_bot_target

    if len(road_rows) > 0:
        top_road = road_rows.min()
        bot_road = road_rows.max()

        if top_road > road_top_target:
            new_y = top_road - 1
            if 0 <= new_y < WORLD_H:
                return (Tool.ROAD, road_col_x, new_y)
        if bot_road < road_bot_target:
            new_y = bot_road + 1
            if 0 <= new_y < WORLD_H:
                return (Tool.ROAD, road_col_x, new_y)
    else:
        # Place initial road segment near plant
        return (Tool.ROAD, road_col_x, cy)

    # Step 4: Place zones adjacent to roads
    # Zones need road access and power
    # Residential left of wire spine: cx - 3
    # Commercial/Industrial right of road: cx + 5

    # Count existing zone types
    n_res = np.sum(res)
    n_com = np.sum(com)
    n_ind = np.sum(ind)

    # Determine what to place next based on balance
    # Aim for roughly 3:1:1 res:com:ind ratio
    if n_com * 3 < n_res and n_res > 3:
        zone_tool = Tool.COMMERCIAL
        zone_col = cx + 5
    elif n_ind * 3 < n_res and n_res > 3:
        zone_tool = Tool.INDUSTRIAL
        zone_col = cx + 5
    else:
        zone_tool = Tool.RESIDENTIAL
        zone_col = cx - 3

    # Find a good row: look for wire coverage row and empty spot at zone_col
    # Scan road rows to find placement near existing infrastructure
    all_road_rows = np.where(roads[:, road_col_x])[0]
    all_wire_rows = np.where(wires[:, cx])[0]

    if len(all_wire_rows) == 0:
        return None

    # Find rows with wire coverage (powered), pick one without a zone yet
    zones_combined = res | com | ind

    # Try rows where wire exists, spaced by 3 (zone size)
    for wr in all_wire_rows[::3]:
        # Check if zone_col area is empty (3x3 center at zone_col, wr)
        y_lo = max(0, wr - 1)
        y_hi = min(WORLD_H - 1, wr + 1)
        x_lo = max(0, zone_col - 1)
        x_hi = min(WORLD_W - 1, zone_col + 1)

        # Check if this 3x3 area is mostly empty (no existing zones)
        area_zones = zones_combined[y_lo:y_hi+1, x_lo:x_hi+1]
        if not np.any(area_zones):
            # Verify road is nearby (within 2 cols)
            road_nearby = np.any(roads[y_lo:y_hi+1, max(0,x_lo-2):min(WORLD_W,x_hi+3)])
            if road_nearby or zone_col == cx - 3:
                # For left zones, connect with a short road to wire col
                if zone_col == cx - 3:
                    # Check if there's a road connection
                    road_bridge = roads[wr, cx-2:cx+1]
                    if not np.any(road_bridge):
                        # Place a road connector at cx-2, wr
                        return (Tool.ROAD, cx - 1, wr)
                return (zone_tool, zone_col, int(wr))

    # Fallback: place residential near any existing road
    road_ys, road_xs = np.where(roads)
    if len(road_xs) > 0:
        # Find empty spot near a road
        for i in range(len(road_xs)):
            rx, ry = int(road_xs[i]), int(road_ys[i])
            # Try placing zone 2 tiles away from road
            for dx in [-3, 3]:
                nx = rx + dx
                ny = ry
                if 1 <= nx <= WORLD_W - 2 and 1 <= ny <= WORLD_H - 2:
                    y_lo = max(0, ny - 1)
                    y_hi = min(WORLD_H - 1, ny + 1)
                    x_lo = max(0, nx - 1)
                    x_hi = min(WORLD_W - 1, nx + 1)
                    if not np.any(zones_combined[y_lo:y_hi+1, x_lo:x_hi+1]):
                        if not np.any(plants[y_lo:y_hi+1, x_lo:x_hi+1]):
                            return (Tool.RESIDENTIAL, nx, ny)

    # If completely stuck, try to extend road further
    if len(all_road_rows) > 0:
        return (Tool.ROAD, road_col_x, int(all_road_rows.max()) + 1)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map each step and places next tile
    based on what's actually on the map.

    Strategy:
    - Place coal power plant first
    - Extend wires from plant outward (BFS-like: find frontier of wire)
    - Lay a road grid in a compact area around center
    - Place zones where road+wire access exists
    - React to what's actually on the map each step
    """
    tm = obs.tile_map
    step = obs.step

    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    # City center
    CX, CY = 60, 50

    # Count existing structures
    has_plant = np.any(pm)
    plant_pos = list(zip(*np.where(pm))) if has_plant else []
    wire_pos = set(zip(*np.where(wm))) if np.any(wm) else set()
    road_pos = set(zip(*np.where(rm))) if np.any(rm) else set()
    zone_pos = set(zip(*np.where(resm | comm | indm)))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Phase 1: Place power plant if none exists
    if not has_plant:
        # Place at CX-10, CY (center-left area)
        px, py = CX - 10, CY
        return (Tool.COALPOWER, px, py)

    # Plant anchor: use first plant found
    pr0, pc0 = plant_pos[0]
    # Plant footprint spans pc0-1..pc0+1, pr0-1..pr0+1 (3x3)
    # Wire should start adjacent to plant

    # Phase 2: Extend wire network from plant outward
    # Target: wire along row CY from plant to CX+30, plus branches up/down
    # We do this by finding the rightmost wire on row CY and extending right,
    # or if that row is covered, do vertical branches

    # Find wire frontier: extend wire rightward along spine row
    spine_row = pr0  # use plant row as spine
    plant_right = pc0 + 2  # right edge of plant footprint

    # Collect wire columns on spine row
    spine_wires = sorted([c for (r, c) in wire_pos if r == spine_row])

    # Target: extend wire to CX+35
    wire_target_col = min(CX + 35, WORLD_W - 2)
    wire_target_row_min = max(spine_row - 20, 5)
    wire_target_row_max = min(spine_row + 20, WORLD_H - 2)

    if spine_wires:
        max_wire_col = max(spine_wires)
    else:
        max_wire_col = plant_right - 1

    if max_wire_col < wire_target_col:
        nc = max_wire_col + 1
        # Don't place wire on plant tiles
        if em[spine_row, nc] or wm[spine_row, nc]:
            if not pm[spine_row, nc]:
                return (Tool.WIRE, nc, spine_row)

    # Phase 3: Vertical wire branches at regular intervals
    # Every 6 cols, run wire from spine up and down to create power reach
    branch_cols = list(range(plant_right + 2, wire_target_col + 1, 6))
    for bc in branch_cols:
        if 0 <= bc < WORLD_W:
            # Check if spine wire exists at this col
            if (spine_row, bc) not in wire_pos:
                continue
            # Extend up
            for wr in range(spine_row - 1, wire_target_row_min - 1, -1):
                if 0 <= wr < WORLD_H:
                    if (wr, bc) not in wire_pos and not pm[wr, bc]:
                        if em[wr, bc] or wm[wr, bc]:
                            return (Tool.WIRE, bc, wr)
                        break
            # Extend down
            for wr in range(spine_row + 1, wire_target_row_max + 1):
                if 0 <= wr < WORLD_H:
                    if (wr, bc) not in wire_pos and not pm[wr, bc]:
                        if em[wr, bc] or wm[wr, bc]:
                            return (Tool.WIRE, bc, wr)
                        break

    # Phase 4: Road grid
    # Horizontal roads at spine_row-3 and spine_row+3
    # Vertical roads every 6 cols connecting the two horizontal roads
    road_row_above = spine_row - 3
    road_row_below = spine_row + 3
    road_col_start = plant_right + 3
    road_col_end = wire_target_col + 3

    # Build horizontal roads
    for rrow in [road_row_above, road_row_below]:
        if 0 <= rrow < WORLD_H:
            road_cols_here = sorted([c for (r, c) in road_pos if r == rrow])
            if road_cols_here:
                max_rc = max(road_cols_here)
            else:
                max_rc = road_col_start - 1
            if max_rc < road_col_end:
                nc = max_rc + 1
                if 0 <= nc < WORLD_W and not pm[rrow, nc]:
                    return (Tool.ROAD, nc, rrow)

    # Build vertical connector roads every 6 cols
    for vc in range(road_col_start, road_col_end + 1, 6):
        if 0 <= vc < WORLD_W:
            for vr in range(road_row_above, road_row_below + 1):
                if 0 <= vr < WORLD_H:
                    if (vr, vc) not in road_pos and not pm[vr, vc]:
                        return (Tool.ROAD, vc, vr)

    # Phase 5: Place zones where road AND wire access exists
    # Zone centers: placed between roads, offset by 1 from road rows
    # Zone rows above road: road_row_above - 2 (center of 3x3 zone touching road)
    # Zone rows below road: road_row_below + 2
    # Multiple rows of zones

    zone_row_sets = [
        road_row_above - 2,
        road_row_above - 5,
        road_row_above - 8,
        road_row_below + 2,
        road_row_below + 5,
        road_row_below + 8,
    ]
    zone_cols_list = list(range(road_col_start + 1, road_col_end, 6))

    def has_road_access(zy, zx, radius=3):
        for dr in range(-radius, radius + 1):
            for dc in range(-radius, radius + 1):
                rr, rc = zy + dr, zx + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if (rr, rc) in road_pos:
                        return True
        return False

    def has_wire_access(zy, zx, radius=5):
        for dr in range(-radius, radius + 1):
            for dc in range(-radius, radius + 1):
                rr, rc = zy + dr, zx + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if (rr, rc) in wire_pos or pm[rr, rc]:
                        return True
        return False

    def zone_area_clear(zy, zx):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zy + dr, zx + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                # Must be empty or existing zone tiles (will bulldoze)
                if not em[rr, rc] and (rr, rc) not in zone_pos:
                    return False
        return True

    def near_existing_zone(zy, zx):
        for (zpr, zpc) in zone_pos:
            if abs(zy - zpr) < 3 and abs(zx - zpc) < 3:
                return True
        return False

    def pick_tool():
        # Balance: 50% res, 25% com, 25% ind
        t = total_zones + 1
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    for zr in zone_row_sets:
        for zc in zone_cols_list:
            if 2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3:
                if not near_existing_zone(zr, zc) and zone_area_clear(zr, zc):
                    if has_road_access(zr, zc) and has_wire_access(zr, zc):
                        return (pick_tool(), zc, zr)

    # Phase 6: If zones placed but not all powered, add more wires
    # Find zones with no nearby wire and add wire toward them
    all_zone_list = list(zone_pos)
    for (zyr, zxc) in all_zone_list[:20]:
        if not has_wire_access(zyr, zxc, radius=4):
            # Find closest wire and extend toward zone
            if wire_pos:
                closest_w = min(wire_pos, key=lambda p: abs(p[0]-zyr)+abs(p[1]-zxc))
                wr, wc = closest_w
                # Step toward zone
                nr = wr + (1 if zyr > wr else -1 if zyr < wr else 0)
                nc = wc + (1 if zxc > wc else -1 if zxc < wc else 0)
                if 0 <= nr < WORLD_H and 0 <= nc < WORLD_W and em[nr, nc]:
                    return (Tool.WIRE, nc, nr)

    # Phase 7: Expand if population growing - add second power plant further out
    if obs.city_pop > 200 and len(plant_pos) < 2:
        px2, py2 = CX + 25, CY
        if em[py2, px2]:
            return (Tool.COALPOWER, px2, py2)

    # Phase 8: More zone rows if space exists
    extra_zone_rows = [
        road_row_above - 11,
        road_row_below + 11,
    ]
    for zr in extra_zone_rows:
        for zc in zone_cols_list:
            if 2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3:
                if not near_existing_zone(zr, zc) and zone_area_clear(zr, zc):
                    if has_road_access(zr, zc, radius=4) and has_wire_access(zr, zc, radius=6):
                        return (pick_tool(), zc, zr)

    # Fill: additional roads for connectivity
    for zc in zone_cols_list:
        for rrow in [road_row_above, road_row_below]:
            if 0 <= rrow < WORLD_H and 0 <= zc < WORLD_W:
                if (rrow, zc) not in road_pos and not pm[rrow, zc]:
                    return (Tool.ROAD, zc, rrow)

    return None

def act(obs, state):
    # Strategy: build a compact grid with proper power + roads
    # Use a horizontal road grid with vertical wire spine
    # Place coal plant, run wire horizontally, place roads parallel
    # Mix RES/COM/IND zones in a checkerboard pattern

    # Initialize state
    if 'phase' not in state:
        state['phase'] = 0
        state['action_queue'] = []

    # Base position - offset from center for variety
    cx, cy = 45, 50  # shifted left from center

    pm = plant_mask(obs.tile_map)
    rm = road_mask(obs.tile_map)
    wm = wire_mask(obs.tile_map)
    res_m = res_mask(obs.tile_map)
    com_m = com_mask(obs.tile_map)
    ind_m = ind_mask(obs.tile_map)

    def has_tile(mask, x, y):
        if 0 <= y < WORLD_H and 0 <= x < WORLD_W:
            return bool(mask[y, x])
        return False

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Layout:
    # Coal plant at (cx, cy)
    # Wire runs horizontally: row cy, from cx to cx+40
    # Roads run horizontally at cy-2, cy+2, cy-5, cy+5, cy-8, cy+8
    # Zones placed between roads with wire connections

    plant_x, plant_y = cx, cy

    # Phase 0: place coal plant
    if not has_tile(pm, plant_x, plant_y):
        return (Tool.COALPOWER, plant_x, plant_y)

    # Phase 1: wire spine horizontally
    wire_y = cy
    wire_x_start = cx - 1  # just left of plant (plant occupies 3 tiles centered)
    wire_x_end = cx + 42

    for x in range(wire_x_start, wire_x_end + 1):
        if not has_tile(wm, x, wire_y) and not has_tile(pm, x, wire_y):
            return (Tool.WIRE, x, wire_y)

    # Also extend wire vertically to reach road rows
    # Wire columns at x=cx+2, cx+5, cx+8, ... every 3 up to cx+39
    road_offsets = [-8, -5, -2, 2, 5, 8]  # rows relative to cy for roads
    zone_rows = [-9, -6, -3, 0, 3, 6, 9]  # zone center rows relative to cy (not on roads)

    # Vertical wires: at every 3rd x position from cx+3 to cx+39
    for wx in range(cx + 3, cx + 42, 3):
        for vy in range(cy - 10, cy + 11):
            if not in_bounds(wx, vy):
                continue
            if not has_tile(wm, wx, vy) and not has_tile(pm, wx, vy):
                return (Tool.WIRE, wx, vy)

    # Phase 2: place horizontal roads
    for ro in road_offsets:
        ry = cy + ro
        if not in_bounds(0, ry):
            continue
        for x in range(cx - 1, cx + 43):
            if not in_bounds(x, ry):
                continue
            if not has_tile(rm, x, ry):
                return (Tool.ROAD, x, ry)

    # Phase 3: place zones in grid pattern
    # Zone centers at x positions: cx+3, cx+6, cx+9, ... cx+39
    # Zone rows relative to cy: use zone_rows but avoid road rows
    actual_zone_rows = [-9, -6, -3, 0, 3, 6, 9]  # rows where zones go (between roads)

    zone_x_positions = list(range(cx + 3, cx + 42, 3))

    # Zone type cycling: RES, RES, COM, IND, COM, RES ...
    def zone_type(xi, yi):
        idx = (xi + yi * 3) % 6
        if idx < 3:
            return Tool.RESIDENTIAL
        elif idx < 5:
            return Tool.COMMERCIAL
        else:
            return Tool.INDUSTRIAL

    def zone_placed(x, y):
        return (has_tile(res_m, x, y) or has_tile(com_m, x, y) or
                has_tile(ind_m, x, y))

    for zi, zx in enumerate(zone_x_positions):
        for zyi, zyr in enumerate(actual_zone_rows):
            zy = cy + zyr
            if not in_bounds(zx, zy):
                continue
            if not zone_placed(zx, zy) and not has_tile(pm, zx, zy):
                # Check wire nearby for power
                powered = False
                for dx in [-1, 0, 1]:
                    for dy2 in [-1, 0, 1]:
                        if has_tile(wm, zx + dx, zy + dy2) or has_tile(pm, zx + dx, zy + dy2):
                            powered = True
                            break
                    if powered:
                        break
                if powered:
                    return (zone_type(zi, zyi), zx, zy)

    # Phase 4: add second coal plant if needed for more coverage
    plant2_x, plant2_y = cx + 45, cy
    if not has_tile(pm, plant2_x, plant2_y):
        # Wire to connect it
        for wx in range(cx + 42, plant2_x):
            if not has_tile(wm, wx, wire_y) and not has_tile(pm, wx, wire_y):
                return (Tool.WIRE, wx, wire_y)
        return (Tool.COALPOWER, plant2_x, plant2_y)

    # Extend roads and zones further right
    for ro in road_offsets:
        ry = cy + ro
        if not in_bounds(0, ry):
            continue
        for x in range(cx + 42, cx + 75):
            if not in_bounds(x, ry):
                continue
            if not has_tile(rm, x, ry):
                return (Tool.ROAD, x, ry)

    # More vertical wires on right side
    for wx in range(cx + 48, cx + 75, 3):
        for vy in range(cy - 10, cy + 11):
            if not in_bounds(wx, vy):
                continue
            if not has_tile(wm, wx, vy) and not has_tile(pm, wx, vy):
                return (Tool.WIRE, wx, vy)

    zone_x_positions2 = list(range(cx + 48, cx + 75, 3))
    for zi, zx in enumerate(zone_x_positions2):
        for zyi, zyr in enumerate(actual_zone_rows):
            zy = cy + zyr
            if not in_bounds(zx, zy):
                continue
            if not zone_placed(zx, zy) and not has_tile(pm, zx, zy):
                powered = False
                for dx in [-1, 0, 1]:
                    for dy2 in [-1, 0, 1]:
                        if has_tile(wm, zx + dx, zy + dy2) or has_tile(pm, zx + dx, zy + dy2):
                            powered = True
                            break
                    if powered:
                        break
                if powered:
                    return (zone_type(zi + 5, zyi), zx, zy)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads the map every step to decide next action
    - Places coal plant, then extends wires from plant outward
    - Builds roads parallel to wire spine
    - Places zones adjacent to roads+wire coverage
    - Adapts to what's actually on the map
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # Map center
    cx, cy = 57, 50

    has_plant = np.any(pm)
    res_count = int(np.sum(res_m))
    com_count = int(np.sum(com_m))
    ind_count = int(np.sum(ind_m))

    # Plant goes left of center
    plant_cx, plant_cy = cx - 6, cy

    # --- Phase 1: Place power plant ---
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    plant_positions = list(zip(*np.where(pm)))
    wire_positions = list(zip(*np.where(wm))) if np.any(wm) else []
    road_positions = list(zip(*np.where(rm))) if np.any(rm) else []

    # Wire spine runs vertically at column cx-1
    # Road column at cx (adjacent to wire)
    # Left zones at cx-4, right zones at cx+3

    wire_col = cx - 1
    road_col = cx

    wire_col_rows = sorted([r for (r, c) in wire_positions if c == wire_col])
    road_col_rows = sorted([r for (r, c) in road_positions if c == road_col])

    # Target wire extent: cy-15 to cy+15
    target_min = cy - 15
    target_max = cy + 15

    # --- Phase 2: Start wire adjacent to plant if none on spine ---
    if not wire_col_rows:
        # Plant footprint: plant_cx-1..plant_cx+1, plant_cy-1..plant_cy+1
        # Place wire at wire_col=cx-1 at row cy
        if 0 <= cy < WORLD_H and 0 <= wire_col < WORLD_W:
            return (Tool.WIRE, wire_col, cy)

    # --- Phase 3: Extend wire spine vertically ---
    if wire_col_rows:
        min_wr = min(wire_col_rows)
        max_wr = max(wire_col_rows)
        # Extend downward
        if max_wr < target_max:
            nr = max_wr + 1
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if min_wr > target_min:
            nr = min_wr - 1
            if nr >= 0 and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    # --- Phase 4: Build road column adjacent to wire spine ---
    if wire_col_rows:
        for r in wire_col_rows:
            if 0 <= r < WORLD_H and 0 <= road_col < WORLD_W:
                if not rm[r, road_col]:
                    if em[r, road_col]:
                        return (Tool.ROAD, road_col, r)

    # --- Phase 5: Add lateral wires toward left zone column ---
    # Left zone center col = cx-4, need wire at cx-2, cx-3
    left_zone_col = cx - 4
    right_zone_col = cx + 3

    if wire_col_rows:
        for wr in wire_col_rows:
            # Wire leftward to reach left zones
            for wc in [cx - 2, cx - 3]:
                if 0 <= wc < WORLD_W and 0 <= wr < WORLD_H:
                    if em[wr, wc] and not wm[wr, wc]:
                        return (Tool.WIRE, wc, wr)
            # Road rightward to reach right zones
            for rc in [cx + 1, cx + 2]:
                if 0 <= rc < WORLD_W and 0 <= wr < WORLD_H:
                    if em[wr, rc] and not rm[wr, rc]:
                        return (Tool.ROAD, rc, wr)

    # --- Helper: check if 3x3 area is free ---
    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    # --- Phase 6: Place zones where powered + road access ---
    all_zone_positions = list(zip(*np.where(res_m | com_m | ind_m))) if (res_count + com_count + ind_count > 0) else []

    if wire_col_rows:
        # Try zone centers on left (cx-4) and right (cx+3) at wire rows
        for zr in wire_col_rows:
            for zc in [left_zone_col, right_zone_col]:
                if not (0 <= zr < WORLD_H and 0 <= zc < WORLD_W):
                    continue
                # Check wire nearby (within 3 tiles)
                wire_near = any(abs(zr - wr) <= 2 and abs(zc - wc) <= 3
                                for (wr, wc) in wire_positions)
                # Check road nearby
                road_near = any(abs(zr - rr) <= 2 and abs(zc - rc) <= 2
                                for (rr, rc) in road_positions)
                if not (wire_near and road_near):
                    continue
                # Check not already a zone nearby
                already = any(abs(zr - pr) <= 1 and abs(zc - pc) <= 1
                              for (pr, pc) in all_zone_positions)
                if already:
                    continue
                if not zone_area_free(zr, zc):
                    continue
                # Pick zone type for balance
                total = res_count + com_count + ind_count + 1
                if com_count * 4 < total and zc == right_zone_col and zr % 6 == 0:
                    return (Tool.COMMERCIAL, zc, zr)
                elif ind_count * 4 < total and zc == left_zone_col and zr > cy:
                    return (Tool.INDUSTRIAL, zc, zr)
                else:
                    return (Tool.RESIDENTIAL, zc, zr)

    # --- Phase 7: Expand if population growing ---
    if obs.city_pop > 150 and wire_col_rows:
        extra_target_min = cy - 25
        extra_target_max = cy + 25
        min_wr = min(wire_col_rows)
        max_wr = max(wire_col_rows)
        if max_wr < extra_target_max:
            nr = max_wr + 1
            if nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        if min_wr > extra_target_min:
            nr = min_wr - 1
            if nr >= 0 and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    # --- Phase 8: Second power plant for more coverage ---
    if obs.city_pop > 300:
        num_plants = len(plant_positions)
        if num_plants < 2:
            p2x, p2y = cx + 15, cy
            return (Tool.COALPOWER, p2x, p2y)

    # --- Fallback: fill any missing road/wire in covered range ---
    if wire_col_rows:
        for r in range(min(wire_col_rows), max(wire_col_rows) + 1):
            if not rm[r, road_col] and em[r, road_col]:
                return (Tool.ROAD, road_col, r)
            if not wm[r, wire_col] and em[r, wire_col]:
                return (Tool.WIRE, wire_col, r)

    return None

def act(obs, state):
    # Closed-loop policy: each step scans the tile_map and places the most needed tile.
    # Strategy: build a compact powered cluster around map center.
    # Uses masks to detect current state and react accordingly.

    cx, cy = WORLD_W // 2, WORLD_H // 2

    # Key positions
    plant_x, plant_y = cx - 2, cy
    wire_col = cx
    road_col = cx + 1

    # Vertical range for the spine
    spine_half = 12

    # Get current masks
    pm = plant_mask(obs.tile_map)
    wm = wire_mask(obs.tile_map)
    rm = road_mask(obs.tile_map)
    res_m = res_mask(obs.tile_map)
    com_m = com_mask(obs.tile_map)
    ind_m = ind_mask(obs.tile_map)
    emp = empty_mask(obs.tile_map)

    def has(mask, x, y):
        if 0 <= x < WORLD_W and 0 <= y < WORLD_H:
            return bool(mask[y, x])
        return False

    def any_adjacent(mask, x, y):
        for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
            if has(mask, x+dx, y+dy):
                return True
        return False

    # Phase 0: Coal power plant
    if not has(pm, plant_x, plant_y):
        return (Tool.COALPOWER, plant_x, plant_y)

    # Phase 1: Wire spine from plant upward/downward
    # Grow wire vertically from existing wire or from plant
    # First wire adjacent to plant if missing
    if not has(wm, wire_col, plant_y) and not has(pm, wire_col, plant_y):
        return (Tool.WIRE, wire_col, plant_y)

    # Extend wire spine: find topmost and bottommost wire in wire_col
    wire_rows = [r for r in range(cy - spine_half, cy + spine_half + 1)
                 if has(wm, wire_col, r)]

    if wire_rows:
        top_w = min(wire_rows)
        bot_w = max(wire_rows)
        # Extend downward first if not at limit
        if bot_w < cy + spine_half:
            ny = bot_w + 1
            if not has(pm, wire_col, ny):
                return (Tool.WIRE, wire_col, ny)
        # Extend upward
        if top_w > cy - spine_half:
            ny = top_w - 1
            if not has(pm, wire_col, ny):
                return (Tool.WIRE, wire_col, ny)
    else:
        # No wire yet adjacent to plant - place at plant_y in wire_col
        return (Tool.WIRE, wire_col, plant_y)

    # Phase 2: Road spine - extend road adjacent to wire
    # Road at road_col wherever wire exists at wire_col
    for dy in range(cy - spine_half, cy + spine_half + 1):
        if has(wm, wire_col, dy) and not has(rm, road_col, dy):
            return (Tool.ROAD, road_col, dy)

    # Phase 3: Residential zones flanking the spine
    # Left zones at cx-3 (3x3 center), right zones at cx+4 (adjacent to road)
    # Place where wire and road are present at that row, every 3 rows
    for dy in range(cy - spine_half, cy + spine_half + 1, 3):
        # Left residential: center at cx-3, adjacent to wire col
        lx = cx - 3
        if (not has(res_m, lx, dy) and not has(pm, lx, dy)
                and has(wm, wire_col, dy)):
            return (Tool.RESIDENTIAL, lx, dy)
        # Right residential: center at cx + 4, adjacent to road col
        rx = cx + 4
        if (not has(res_m, rx, dy) and not has(pm, rx, dy)
                and has(rm, road_col, dy)):
            return (Tool.RESIDENTIAL, rx, dy)

    # Phase 4: Second wire column and more zones
    wire2_col = cx - 5
    road2_col = cx - 6

    # Wire from plant leftward horizontally at plant_y
    for wx in range(cx - 1, wire2_col - 1, -1):
        if not has(wm, wx, plant_y) and not has(pm, wx, plant_y):
            return (Tool.WIRE, wx, plant_y)

    # Vertical wire at wire2_col
    for dy in range(cy - spine_half, cy + spine_half + 1):
        if has(wm, wire2_col, plant_y) and not has(wm, wire2_col, dy) and not has(pm, wire2_col, dy):
            # Only place if adjacent to existing wire
            if any_adjacent(wm, wire2_col, dy):
                return (Tool.WIRE, wire2_col, dy)

    # Road at road2_col
    for dy in range(cy - spine_half, cy + spine_half + 1):
        if has(wm, wire2_col, dy) and not has(rm, road2_col, dy):
            return (Tool.ROAD, road2_col, dy)

    # Commercial zones left side at cx-8
    for dy in range(cy - spine_half, cy + spine_half + 1, 3):
        cx8 = cx - 8
        if (not has(com_m, cx8, dy) and not has(pm, cx8, dy)
                and has(wm, wire2_col, dy) and has(rm, road2_col, dy)):
            return (Tool.COMMERCIAL, cx8, dy)

    # Industrial zones right side at cx+7
    # Need road and wire there: extend road_col rightward via wire
    wire3_col = cx + 2
    road3_col = cx + 3

    for dy in range(cy - spine_half, cy + spine_half + 1):
        if has(rm, road_col, dy) and not has(wm, wire3_col, dy) and not has(pm, wire3_col, dy):
            return (Tool.WIRE, wire3_col, dy)

    for dy in range(cy - spine_half, cy + spine_half + 1):
        if has(wm, wire3_col, dy) and not has(rm, road3_col, dy):
            return (Tool.ROAD, road3_col, dy)

    for dy in range(cy - spine_half, cy + spine_half + 1, 3):
        ix = cx + 7
        if (not has(ind_m, ix, dy) and not has(pm, ix, dy)
                and has(wm, wire3_col, dy) and has(rm, road3_col, dy)):
            return (Tool.INDUSTRIAL, ix, dy)

    # Second coal plant if population growing
    if obs.city_pop > 150:
        plant2_x, plant2_y = cx + 10, cy
        if not has(pm, plant2_x, plant2_y):
            # Wire bridge from wire3_col to plant2
            for wx in range(wire3_col + 1, plant2_x):
                if not has(wm, wx, cy) and not has(pm, wx, cy):
                    return (Tool.WIRE, wx, cy)
            return (Tool.COALPOWER, plant2_x, plant2_y)

    # Fill more residential if funds/pop allow
    if obs.city_pop > 50:
        for dy in range(cy - spine_half, cy + spine_half + 1, 3):
            # Extra left residential at cx-11
            ex = cx - 11
            if (not has(res_m, ex, dy) and not has(pm, ex, dy)
                    and has(rm, road2_col, dy)):
                return (Tool.RESIDENTIAL, ex, dy)

    return None

def act(obs, state):
    """
    Closed-loop city builder. Each step reads the tile_map and reacts.
    Strategy:
    1. Place coal power plant near center-left if none exists
    2. Extend wires from plant in a cross/spine pattern
    3. Build road grid adjacent to wire network
    4. Place zones (R/C/I) where both road and wire access exist
    5. Add services (police/fire) once population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    CX, CY = 40, 50  # primary cluster center

    has_plant = np.any(pm)
    plant_ys, plant_xs = np.where(pm)

    # --- Phase 1: Place power plant ---
    if not has_plant:
        return (Tool.COALPOWER, CX, CY)

    # Plant anchor (use centroid of plant tiles)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    wire_ys, wire_xs = np.where(wm)
    road_ys, road_xs = np.where(rm)
    res_ys, res_xs = np.where(resm)
    com_ys, com_xs = np.where(comm)
    ind_ys, ind_xs = np.where(indm)

    wire_set = set(zip(wire_ys.tolist(), wire_xs.tolist()))
    road_set = set(zip(road_ys.tolist(), road_xs.tolist()))
    zone_set = set(zip(
        np.concatenate([res_ys, com_ys, ind_ys]).tolist(),
        np.concatenate([res_xs, com_xs, ind_xs]).tolist()
    ))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def can_wire(x, y):
        return in_bounds(x, y) and bool(em[y, x]) and not bool(pm[y, x])

    def can_road(x, y):
        return in_bounds(x, y) and not bool(pm[y, x])

    # --- Phase 2: Wire spine - vertical from plant ---
    # Vertical wire spine at px (column of plant center)
    spine_x = px
    # Extend wire up from plant
    for dy in range(1, 18):
        wy, wx = py - dy, spine_x
        if not in_bounds(wx, wy):
            break
        if (wy, wx) not in wire_set and can_wire(wx, wy):
            return (Tool.WIRE, wx, wy)
        elif not (bool(wm[wy, wx]) or bool(pm[wy, wx])):
            break

    # Extend wire down from plant
    for dy in range(1, 18):
        wy, wx = py + dy, spine_x
        if not in_bounds(wx, wy):
            break
        if (wy, wx) not in wire_set and can_wire(wx, wy):
            return (Tool.WIRE, wx, wy)
        elif not (bool(wm[wy, wx]) or bool(pm[wy, wx])):
            break

    # Horizontal wire at py (row of plant center), extending right
    for dx in range(1, 35):
        wy, wx = py, px + dx
        if not in_bounds(wx, wy):
            break
        if (wy, wx) not in wire_set and can_wire(wx, wy):
            return (Tool.WIRE, wx, wy)
        elif not (bool(wm[wy, wx]) or bool(pm[wy, wx])):
            break

    # --- Phase 3: Road grid ---
    # Two horizontal road spines flanking the wire spine
    road_row_top = py - 4
    road_row_bot = py + 4
    road_col_start = px + 2
    road_col_end = min(px + 32, WORLD_W - 3)

    # Build top horizontal road
    top_road_cols = sorted([c for (r, c) in road_set if r == road_row_top])
    max_top = max(top_road_cols) if top_road_cols else road_col_start - 1
    if max_top < road_col_end and in_bounds(max_top + 1, road_row_top):
        nc = max_top + 1
        if can_road(nc, road_row_top):
            return (Tool.ROAD, nc, road_row_top)

    # Build bottom horizontal road
    bot_road_cols = sorted([c for (r, c) in road_set if r == road_row_bot])
    max_bot = max(bot_road_cols) if bot_road_cols else road_col_start - 1
    if max_bot < road_col_end and in_bounds(max_bot + 1, road_row_bot):
        nc = max_bot + 1
        if can_road(nc, road_row_bot):
            return (Tool.ROAD, nc, road_row_bot)

    # Vertical connector roads every 4 cols
    for vc in range(road_col_start, road_col_end + 1, 4):
        if not in_bounds(vc, road_row_top):
            continue
        for vr in range(road_row_top, road_row_bot + 1):
            if (vr, vc) not in road_set and can_road(vc, vr):
                return (Tool.ROAD, vc, vr)

    # Also road spine adjacent to wire spine (one col to the right)
    road_spine_x = spine_x + 1
    for dy in range(-14, 15):
        ry, rx = py + dy, road_spine_x
        if not in_bounds(rx, ry):
            continue
        if (ry, rx) not in road_set and can_road(rx, ry):
            return (Tool.ROAD, rx, ry)

    # --- Phase 4: Place zones where road AND wire nearby ---
    def has_road_near(zx, zy, r=3):
        for dr in range(-r, r + 1):
            for dc in range(-r, r + 1):
                if (zy + dr, zx + dc) in road_set:
                    return True
        return False

    def has_wire_near(zx, zy, r=5):
        for dr in range(-r, r + 1):
            for dc in range(-r, r + 1):
                nr, nc = zy + dr, zx + dc
                if (nr, nc) in wire_set:
                    return True
                if in_bounds(nc, nr) and pm[nr, nc]:
                    return True
        return False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    def pick_tool():
        t = max(total_zones, 1)
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Zone rows above and below roads
    zone_rows = [
        road_row_top - 2, road_row_top - 5, road_row_top - 8,
        road_row_bot + 2, road_row_bot + 5, road_row_bot + 8,
    ]
    zone_cols = list(range(road_col_start + 1, road_col_end, 4))

    # Also check near spine_x on left side
    zone_cols_left = list(range(px - 12, px - 2, 4))
    zone_rows_left = [py - 2, py + 2, py - 5, py + 5]

    for zr in zone_rows:
        for zc in zone_cols:
            if not (2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3):
                continue
            if zone_clear(zc, zr) and has_road_near(zc, zr) and has_wire_near(zc, zr):
                return (pick_tool(), zc, zr)

    for zr in zone_rows_left:
        for zc in zone_cols_left:
            if not (2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3):
                continue
            if zone_clear(zc, zr) and has_road_near(zc, zr) and has_wire_near(zc, zr):
                return (pick_tool(), zc, zr)

    # --- Phase 5: Extend wires toward unserved zones ---
    all_zone_list = list(zone_set)
    for (zyr, zxc) in all_zone_list[:30]:
        if not has_wire_near(zxc, zyr, r=4):
            if wire_set:
                closest_w = min(wire_set, key=lambda p: abs(p[0] - zyr) + abs(p[1] - zxc))
                wr, wc = closest_w
                # Step toward zone
                step_r = (1 if zyr > wr else -1 if zyr < wr else 0)
                step_c = (1 if zxc > wc else -1 if zxc < wc else 0)
                # Try row-first then col
                for nr, nc in [(wr + step_r, wc), (wr, wc + step_c)]:
                    if in_bounds(nc, nr) and can_wire(nc, nr):
                        return (Tool.WIRE, nc, nr)

    # --- Phase 6: Second power plant if population growing ---
    if obs.city_pop > 300 and np.sum(pm) < 9:
        nx2, ny2 = CX + 40, CY
        if in_bounds(nx2, ny2) and em[ny2, nx2]:
            return (Tool.COALPOWER, nx2, ny2)

    # --- Phase 7: Services ---
    if obs.city_pop > 100:
        # Fire station
        fx, fy = px + 5, py - 10
        if in_bounds(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
        # Police station
        fx2, fy2 = px + 5, py + 10
        if in_bounds(fx2, fy2) and em[fy2, fx2]:
            return (Tool.POLICESTATION, fx2, fy2)

    # --- Phase 8: Fill more road and zones reactively ---
    # If there are still empty spots near existing roads, try placing zones
    road_arr = rm.astype(np.uint8)
    # Dilate road mask by 3
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand = em & nbr_road & nbr_wire
    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        k = int((obs.step * 17 + int(tm.sum()) % 100)) % len(cxs)
        zx, zy = int(cxs[k]), int(cys[k])
        # Check zone_clear
        if zone_clear(zx, zy):
            return (pick_tool(), zx, zy)

    # Last resort: extend road from existing road frontier
    if len(road_xs) > 0:
        # pick random road tile and extend
        k = int(obs.step * 7) % len(road_xs)
        rx, ry = int(road_xs[k]), int(road_ys[k])
        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx + dx, ry + dy
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop policy:
    - Reads tile_map each step to decide next action
    - Builds a compact cluster: coal plant -> wire spine -> road grid -> zones
    - Reacts to what's actually on the map
    """
    tm = obs.tile_map
    step = obs.step

    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    # Cluster center
    cx, cy = 60, 50

    # --- Phase 1: Place coal power plant if none exists ---
    if not np.any(pm):
        # Place plant at fixed offset from center
        px, py = cx - 20, cy
        return (Tool.COALPOWER, px, py)

    # Find plant positions
    plant_ys, plant_xs = np.where(pm)
    # Use first plant as anchor
    p0x, p0y = int(plant_xs[0]), int(plant_ys[0])

    # --- Phase 2: Build horizontal wire spine from plant rightward ---
    # Wire spine at row = p0y, from p0x+2 to cx+25
    spine_row = p0y
    spine_x_start = p0x + 2
    spine_x_end = cx + 25

    # Find rightmost wire on spine row
    wire_on_spine = [(c, r) for (r, c) in zip(*np.where(wm)) if r == spine_row]
    if wire_on_spine:
        max_wire_x = max(x for x, _ in wire_on_spine)
    else:
        max_wire_x = spine_x_start - 1

    if max_wire_x < spine_x_end:
        nx = max_wire_x + 1
        if 0 <= nx < WORLD_W and em[spine_row, nx]:
            return (Tool.WIRE, nx, spine_row)
        elif 0 <= nx < WORLD_W and not wm[spine_row, nx]:
            # bulldoze and wire
            return (Tool.WIRE, nx, spine_row)

    # --- Phase 3: Build two horizontal roads parallel to wire spine ---
    road_rows = [spine_row - 3, spine_row + 3]
    road_x_start = p0x + 2
    road_x_end = spine_x_end

    for rr in road_rows:
        if rr < 0 or rr >= WORLD_H:
            continue
        road_on_row = [c for (r, c) in zip(*np.where(rm)) if r == rr]
        if road_on_row:
            max_road_x = max(road_on_row)
        else:
            max_road_x = road_x_start - 1
        if max_road_x < road_x_end:
            nx = max_road_x + 1
            if 0 <= nx < WORLD_W:
                return (Tool.ROAD, nx, rr)

    # --- Phase 4: Build vertical roads connecting the two road rows at intervals ---
    # Every 6 cols, run a vertical road from spine_row-3 to spine_row+3
    for col in range(road_x_start, road_x_end + 1, 6):
        for row in range(spine_row - 3, spine_row + 4):
            if 0 <= row < WORLD_H and 0 <= col < WORLD_W:
                if not rm[row, col] and not wm[row, col]:
                    return (Tool.ROAD, col, row)

    # --- Phase 5: Build vertical wires from spine up/down to reach zone rows ---
    zone_rows_above = [spine_row - 6, spine_row - 10, spine_row - 14]
    zone_rows_below = [spine_row + 6, spine_row + 10, spine_row + 14]
    zone_cols = list(range(road_x_start + 2, road_x_end, 6))

    for zc in zone_cols:
        if not (0 <= zc < WORLD_W):
            continue
        # Wire upward from spine
        for zr_target in zone_rows_above:
            if zr_target < 0:
                continue
            # Check if wire already reaches
            wire_col = [r for (r, c) in zip(*np.where(wm)) if c == zc]
            if wire_col:
                min_wr = min(wire_col)
            else:
                min_wr = spine_row
            if min_wr > zr_target:
                # Need to extend wire upward
                nr = min_wr - 1
                if nr >= 0 and not rm[nr, zc] and not wm[nr, zc]:
                    return (Tool.WIRE, zc, nr)
                break

        for zr_target in zone_rows_below:
            if zr_target >= WORLD_H:
                continue
            wire_col = [r for (r, c) in zip(*np.where(wm)) if c == zc]
            if wire_col:
                max_wr = max(wire_col)
            else:
                max_wr = spine_row
            if max_wr < zr_target:
                nr = max_wr + 1
                if nr < WORLD_H and not rm[nr, zc] and not wm[nr, zc]:
                    return (Tool.WIRE, zc, nr)
                break

    # --- Phase 6: Place zones adjacent to roads and wires ---
    all_zone_rows = zone_rows_above + zone_rows_below
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count + 1

    def pick_zone_type(zc, zr):
        if com_count / total_zones < 0.25:
            return Tool.COMMERCIAL
        elif ind_count / total_zones < 0.25:
            return Tool.INDUSTRIAL
        else:
            return Tool.RESIDENTIAL

    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr2, rc2 = cr + dr, cc + dc
                if rr2 < 0 or rr2 >= WORLD_H or rc2 < 0 or rc2 >= WORLD_W:
                    return False
                # Allow placing on empty tiles only
                if not em[rr2, rc2]:
                    return False
        return True

    def road_near(zr, zc):
        r0, r1 = max(0, zr - 2), min(WORLD_H, zr + 3)
        c0, c1 = max(0, zc - 2), min(WORLD_W, zc + 3)
        return np.any(rm[r0:r1, c0:c1])

    def wire_near(zr, zc):
        r0, r1 = max(0, zr - 4), min(WORLD_H, zr + 5)
        c0, c1 = max(0, zc - 4), min(WORLD_W, zc + 5)
        return np.any(wm[r0:r1, c0:c1])

    for zr in all_zone_rows:
        if zr < 1 or zr >= WORLD_H - 1:
            continue
        for zc in zone_cols:
            if zc < 1 or zc >= WORLD_W - 1:
                continue
            if road_near(zr, zc) and wire_near(zr, zc) and zone_area_free(zr, zc):
                return (pick_zone_type(zc, zr), zc, zr)

    # --- Phase 7: Expand zones further if population growing ---
    if obs.city_pop > 50 or step > obs.n_steps // 2:
        extra_rows = [spine_row - 18, spine_row + 18, spine_row - 22, spine_row + 22]
        for zr in extra_rows:
            if zr < 1 or zr >= WORLD_H - 1:
                continue
            for zc in zone_cols:
                if zc < 1 or zc >= WORLD_W - 1:
                    continue
                if road_near(zr, zc) and wire_near(zr, zc) and zone_area_free(zr, zc):
                    return (pick_zone_type(zc, zr), zc, zr)

        # Extend roads to reach extra rows
        for zr in extra_rows:
            if zr < 0 or zr >= WORLD_H:
                continue
            for zc in zone_cols:
                if not (0 <= zc < WORLD_W):
                    continue
                # Check if road exists near this col at an intermediate row
                for mid_r in range(min(zr, spine_row - 3), max(zr, spine_row + 3) + 1):
                    if 0 <= mid_r < WORLD_H and not rm[mid_r, zc] and not wm[mid_r, zc]:
                        return (Tool.ROAD, zc, mid_r)

    # --- Phase 8: Add more roads connecting zone columns horizontally at zone rows ---
    for zr in all_zone_rows:
        if zr < 0 or zr >= WORLD_H:
            continue
        road_on_zrow = [c for (r, c) in zip(*np.where(rm)) if r == zr]
        if road_on_zrow:
            max_rc = max(road_on_zrow)
        else:
            max_rc = road_x_start - 1
        if max_rc < road_x_end:
            nx = max_rc + 1
            if 0 <= nx < WORLD_W and not wm[zr, nx]:
                return (Tool.ROAD, nx, zr)

    return None

def act(obs, state):
    # Closed-loop policy: every step reads the current tile_map and decides
    # the single most useful next placement based on what actually exists.
    #
    # Strategy:
    #   1. Ensure a coal plant exists near center-left.
    #   2. Grow a wire spine vertically from the plant outward (closed-loop: find gaps).
    #   3. Grow a road column adjacent to wire spine (closed-loop: find gaps).
    #   4. Place residential zones flanking the road where wire and road both exist.
    #   5. Add commercial/industrial for balance once res zones appear.
    #   6. Expand outward reactively as the city grows.

    cx, cy = WORLD_W // 2, WORLD_H // 2

    tm = obs.tile_map
    pm   = plant_mask(tm)
    wm   = wire_mask(tm)
    rm   = road_mask(tm)
    res  = res_mask(tm)
    com  = com_mask(tm)
    ind  = ind_mask(tm)
    emp  = empty_mask(tm)

    def ok(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def has(mask, x, y):
        return ok(x, y) and bool(mask[y, x])

    # Determine how far to extend the spine based on population growth
    base_half = 8
    pop = obs.city_pop
    if pop > 500:
        half = min(18, base_half + (pop - 500) // 200)
    else:
        half = base_half

    plant_x, plant_y = cx - 2, cy
    wire_col  = cx        # vertical wire spine
    road_col  = cx + 1    # vertical road
    lzone_x   = cx - 4    # left residential column center
    rzone_x   = cx + 4    # right residential column center
    czone_x   = cx + 7    # commercial column
    izone_x   = cx - 7    # industrial column

    spine_rows = range(cy - half, cy + half + 1)

    # ── Phase 0: coal power plant ──────────────────────────────────────────────
    if not has(pm, plant_x, plant_y):
        return (Tool.COALPOWER, plant_x, plant_y)

    # ── Phase 1: wire spine – find first gap (closed-loop scan) ───────────────
    # Wire from plant outward; skip the plant cell itself
    for dy in spine_rows:
        if dy == plant_y and wire_col == plant_x:
            continue
        if not has(wm, wire_col, dy) and not has(pm, wire_col, dy):
            return (Tool.WIRE, wire_col, dy)

    # ── Phase 2: road column – find first gap ─────────────────────────────────
    for dy in spine_rows:
        if not has(rm, road_col, dy):
            return (Tool.ROAD, road_col, dy)

    # ── Phase 3: residential zones left & right of road ───────────────────────
    # Place a zone only where the wire spine exists at that row (power reachable)
    # and the road also exists (road access).
    for dy in range(cy - half, cy + half + 1, 3):
        if not ok(lzone_x, dy) or not ok(rzone_x, dy):
            continue
        wire_ok  = has(wm, wire_col, dy)
        road_ok  = has(rm, road_col, dy)
        if not (wire_ok and road_ok):
            continue
        # Left zone
        if not has(res, lzone_x, dy) and not has(pm, lzone_x, dy):
            return (Tool.RESIDENTIAL, lzone_x, dy)
        # Right zone
        if not has(res, rzone_x, dy) and not has(pm, rzone_x, dy):
            return (Tool.RESIDENTIAL, rzone_x, dy)

    # ── Phase 4: add horizontal wire connectors to outer zones ────────────────
    # Connect wire from spine to industrial/commercial columns at every 3rd row
    for dy in range(cy - half, cy + half + 1, 3):
        if not has(wm, wire_col, dy):
            continue
        # Leftward wire to izone_x+1
        for wx in range(wire_col - 1, izone_x, -1):
            if not has(wm, wx, dy) and not has(pm, wx, dy) and not has(rm, wx, dy):
                return (Tool.WIRE, wx, dy)
        # Rightward wire to czone_x-1
        for wx in range(wire_col + 2, czone_x):
            if not has(wm, wx, dy) and not has(rm, wx, dy) and not has(pm, wx, dy):
                return (Tool.WIRE, wx, dy)

    # ── Phase 5: commercial zones (right outer) ────────────────────────────────
    for dy in range(cy - half, cy + half + 1, 3):
        if not ok(czone_x, dy):
            continue
        if has(wm, czone_x - 1, dy) or has(wm, czone_x, dy):
            if not has(com, czone_x, dy) and not has(pm, czone_x, dy):
                return (Tool.COMMERCIAL, czone_x, dy)

    # ── Phase 6: industrial zones (left outer) ────────────────────────────────
    for dy in range(cy - half, cy + half + 1, 3):
        if not ok(izone_x, dy):
            continue
        if has(wm, izone_x + 1, dy) or has(wm, izone_x, dy):
            if not has(ind, izone_x, dy) and not has(pm, izone_x, dy):
                return (Tool.INDUSTRIAL, izone_x, dy)

    # ── Phase 7: second coal plant if needed ──────────────────────────────────
    p2x, p2y = cx + 12, cy
    if pop > 300 and not has(pm, p2x, p2y):
        # Wire bridge from road_col+1 to p2x-1
        for wx in range(road_col + 1, p2x):
            if not has(wm, wx, p2y) and not has(rm, wx, p2y) and not has(pm, wx, p2y):
                return (Tool.WIRE, wx, p2y)
        return (Tool.COALPOWER, p2x, p2y)

    # ── Phase 8: reactive gap-fill – place res near existing res neighbors ────
    nbr = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    nbr[1:, :]  |= res[:-1, :]
    nbr[:-1, :] |= res[1:, :]
    nbr[:, 1:]  |= res[:, :-1]
    nbr[:, :-1] |= res[:, 1:]
    cand = emp & nbr
    # Prefer tiles near road or wire
    road_near = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    road_near[1:, :]  |= rm[:-1, :]
    road_near[:-1, :] |= rm[1:, :]
    road_near[:, 1:]  |= rm[:, :-1]
    road_near[:, :-1] |= rm[:, 1:]
    good = cand & road_near
    ys, xs = np.where(good)
    if len(xs) > 0:
        k = int(tm.sum() % len(xs))
        return (Tool.RESIDENTIAL, int(xs[k]), int(ys[k]))

    # Fallback: any candidate neighbor
    ys, xs = np.where(cand)
    if len(xs) > 0:
        k = int(tm.sum() % len(xs))
        return (Tool.RESIDENTIAL, int(xs[k]), int(ys[k]))

    return None

def act(obs, state):
    """
    Closed-loop policy: reads the current map each step and decides
    the next placement based on what already exists.

    Strategy:
    - Place a coal power plant near (25, 50)
    - Extend wires from the plant rightward along row 50
    - Extend roads along row 47 and row 53 (parallel to wire)
    - Place vertical connector roads every 6 columns
    - Place zones (res/com/ind mix) above and below the roads
    - Add vertical wires from spine to zones as needed
    """
    tm = obs.tile_map
    step = obs.step

    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    # Count existing zones
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Key layout parameters
    spine_row = 50          # wire spine row
    road_row_top = 47       # road above spine
    road_row_bot = 53       # road below spine
    plant_x, plant_y = 20, 50  # power plant center
    spine_start = 25        # wire starts here
    spine_end = 100         # wire ends here

    # Zone columns: every 6 from spine_start to spine_end
    zone_cols = list(range(spine_start, spine_end, 6))
    # Zone rows above and below roads
    zone_rows_above = [44, 41, 38, 35]
    zone_rows_below = [56, 59, 62, 65]

    def is_in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def area_placeable(cx, cy):
        """Check 3x3 zone area is within bounds"""
        for dy in [-1, 0, 1]:
            for dx in [-1, 0, 1]:
                nx, ny = cx + dx, cy + dy
                if not is_in_bounds(nx, ny):
                    return False
        return True

    def has_road_nearby(cx, cy, radius=4):
        """Check if there's a road within radius of (cx, cy)"""
        y0 = max(0, cy - radius)
        y1 = min(WORLD_H, cy + radius + 1)
        x0 = max(0, cx - radius)
        x1 = min(WORLD_W, cx + radius + 1)
        return bool(np.any(rm[y0:y1, x0:x1]))

    def has_wire_nearby(cx, cy, radius=6):
        """Check if there's a wire or plant within radius"""
        y0 = max(0, cy - radius)
        y1 = min(WORLD_H, cy + radius + 1)
        x0 = max(0, cx - radius)
        x1 = min(WORLD_W, cx + radius + 1)
        return bool(np.any(wm[y0:y1, x0:x1])) or bool(np.any(pm[y0:y1, x0:x1]))

    def zone_already_placed(cx, cy, radius=2):
        """Check if a zone already exists nearby"""
        y0 = max(0, cy - radius)
        y1 = min(WORLD_H, cy + radius + 1)
        x0 = max(0, cx - radius)
        x1 = min(WORLD_W, cx + radius + 1)
        return (bool(np.any(resm[y0:y1, x0:x1])) or
                bool(np.any(comm[y0:y1, x0:x1])) or
                bool(np.any(indm[y0:y1, x0:x1])))

    def pick_zone_type(zc, zr):
        """Pick zone type based on current balance"""
        t = total_zones + 1
        # Target: 50% res, 25% com, 25% ind
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        elif ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        else:
            return Tool.RESIDENTIAL

    # --- Phase 1: Place power plant ---
    if not np.any(pm):
        return (Tool.COALPOWER, plant_x, plant_y)

    # Find rightmost wire on spine row
    wire_on_spine = [c for c in range(WORLD_W) if wm[spine_row, c]]
    road_on_top = [c for c in range(WORLD_W) if rm[road_row_top, c]]
    road_on_bot = [c for c in range(WORLD_W) if rm[road_row_bot, c]]

    max_wire_col = max(wire_on_spine) if wire_on_spine else spine_start - 1
    max_road_top = max(road_on_top) if road_on_top else spine_start - 1
    max_road_bot = max(road_on_bot) if road_on_bot else spine_start - 1

    # --- Phase 2: Extend wire spine rightward ---
    if max_wire_col < spine_end:
        nc = max_wire_col + 1
        if is_in_bounds(nc, spine_row):
            # Don't overwrite plant
            if not pm[spine_row, nc]:
                return (Tool.WIRE, nc, spine_row)

    # --- Phase 3: Extend top road rightward ---
    if max_road_top < spine_end + 5:
        nc = max_road_top + 1
        if is_in_bounds(nc, road_row_top):
            return (Tool.ROAD, nc, road_row_top)

    # --- Phase 4: Extend bottom road rightward ---
    if max_road_bot < spine_end + 5:
        nc = max_road_bot + 1
        if is_in_bounds(nc, road_row_bot):
            return (Tool.ROAD, nc, road_row_bot)

    # --- Phase 5: Vertical connector roads at zone columns ---
    # Connect road_row_top to road_row_bot through spine at each zone col
    for zc in zone_cols:
        for conn_row in range(road_row_top, road_row_bot + 1):
            if is_in_bounds(zc, conn_row):
                if not rm[conn_row, zc] and not wm[conn_row, zc] and not pm[conn_row, zc]:
                    return (Tool.ROAD, zc, conn_row)

    # --- Phase 6: Place vertical wires from spine to zone rows ---
    # Wires going up from spine to zone rows above
    for zc in zone_cols:
        for zr in zone_rows_above:
            if not is_in_bounds(zc, zr):
                continue
            # Wire from spine_row up to zr at column zc
            for wr in range(spine_row - 1, zr - 1, -1):
                if pm[wr, zc]:
                    break
                if not wm[wr, zc] and not rm[wr, zc]:
                    if is_in_bounds(zc, wr):
                        return (Tool.WIRE, zc, wr)
                    break
                elif wm[wr, zc] or rm[wr, zc]:
                    continue

    # Wires going down from spine to zone rows below
    for zc in zone_cols:
        for zr in zone_rows_below:
            if not is_in_bounds(zc, zr):
                continue
            for wr in range(spine_row + 1, zr + 2):
                if pm[wr, zc]:
                    break
                if not wm[wr, zc] and not rm[wr, zc]:
                    if is_in_bounds(zc, wr):
                        return (Tool.WIRE, zc, wr)
                    break
                elif wm[wr, zc] or rm[wr, zc]:
