    # --- Phase 7: Place zones where road and power reach ---
    for zr in zone_rows_above + zone_rows_below:
        for zc in zone_cols:
            if not is_in_bounds(zc, zr):
                continue
            if not area_placeable(zc, zr):
                continue
            if zone_already_placed(zc, zr, radius=2):
                continue
            if has_road_nearby(zc, zr, radius=5) and has_wire_nearby(zc, zr, radius=7):
                return (pick_zone_type(zc, zr), zc, zr)

    # --- Phase 8: Second power plant for right side if population growing ---
    num_plants = int(np.sum(pm)) // 9  # rough count (plant is 3x3=9 tiles)
    if num_plants < 2 and obs.city_pop > 50:
        # Place second plant at right side
        rpx, rpy = 95, 50
        if is_in_bounds(rpx, rpy) and not pm[rpy, rpx]:
