    # --- Phase 9: Extend zones further if city is growing ---
    if obs.city_pop > 200:
        extra_rows_above = [32, 29, 26]
        extra_rows_below = [68, 71, 74]
        for zr in extra_rows_above + extra_rows_below:
            for zc in zone_cols:
                if not is_in_bounds(zc, zr):
                    continue
                if not area_placeable(zc, zr):
                    continue
                if zone_already_placed(zc, zr, radius=2):
                    continue
                # Add wire connection first if needed
                if not has_wire_nearby(zc, zr, radius=4):
                    # Try to place wire adjacent to existing wire
                    for dy in range(-1, 2):
                        for dx in range(-1, 2):
                            ny, nx = zr + dy, zc + dx
                            if is_in_bounds(nx, ny) and em[ny, nx]:
                                # Check if adjacent to existing wire
                                for ay in range(-1, 2):
                                    for ax in range(-1, 2):
                                        aay, aax = ny + ay, nx + ax
                                        if is_in_bounds(aax, aay) and wm[aay, aax]:
                                            return (Tool.WIRE, nx, ny)
                if has_road_nearby(zc, zr, radius=5) and has_wire_nearby(zc, zr, radius=8):
                    return (pick_zone_type(zc, zr), zc, zr)

    # --- Fallback: extend roads further or add more wires ---
    # Try to extend roads a bit more to cover more zone columns
    for zc in zone_cols:
        for road_row in [road_row_top, road_row_bot]:
            if is_in_bounds(zc, road_row) and not rm[road_row, zc]:
                return (Tool.ROAD, zc, road_row)

    return None

