def act(obs, state):
    """
    Closed-loop policy: reads the current map each step and decides
    what to place next based on what already exists.

    Strategy:
    - Phase 0: Place coal power plant
    - Phase 1: Extend wire from power plant outward (spine)
    - Phase 2: Extend road alongside wire
    - Phase 3: Place residential zones adjacent to road+wire coverage
    - Phase 4: Add commercial/industrial for balance
    - Continuously check powered_zones and road coverage
    """

    cx, cy = WORLD_W // 2, WORLD_H // 2

    # Initialize state
    if "phase" not in state:
        state["phase"] = 0
        state["wire_extent"] = 0  # how far we've extended wire from cy
        state["road_extent"] = 0
        state["res_rows_placed"] = set()
        state["com_rows_placed"] = set()
        state["ind_rows_placed"] = set()

    tile_map = obs.tile_map

    # Helper: check if a tile is empty
    def is_empty(x, y):
        if x < 0 or x >= WORLD_W or y < 0 or y >= WORLD_H:
            return False
        return empty_mask[y, x]

    def has_wire(x, y):
        if x < 0 or x >= WORLD_W or y < 0 or y >= WORLD_H:
            return False
        return wire_mask[y, x]

    def has_road(x, y):
        if x < 0 or x >= WORLD_W or y < 0 or y >= WORLD_H:
            return False
        return road_mask[y, x]

    def has_plant(x, y):
        if x < 0 or x >= WORLD_W or y < 0 or y >= WORLD_H:
            return False
        return plant_mask[y, x]

    def has_res(x, y):
        if x < 0 or x >= WORLD_W or y < 0 or y >= WORLD_H:
            return False
        return res_mask[y, x]

    # Phase 0: Place coal power plant if not present
    # Plant center at (cx-4, cy)
    plant_x, plant_y = cx - 4, cy
    plant_present = np.any(plant_mask)

    if not plant_present:
        return (Tool.COALPOWER, plant_x, plant_y)

    # Phase 1: Build wire spine vertically at cx-1
    # Wire column at cx-1, connecting from power plant outward
    wire_col = cx - 1
    road_col = cx
    res_col_left = cx - 4
    res_col_right = cx + 3

    # Scan wire column: find topmost and bottommost wire
    wire_ys = []
    for y in range(WORLD_H):
        if has_wire(wire_col, y) or has_plant(wire_col, y):
            wire_ys.append(y)

    # Also check plant adjacency - plant at (cx-4, cy) spans cx-5 to cx-3, cy-1 to cy+1
    # Wire needs to touch plant. Place wire at cx-3 first if not present
    if not has_wire(wire_col, cy) and not has_plant(wire_col, cy):
        # Place wire adjacent to plant
        return (Tool.WIRE, wire_col, cy)

    # Extend wire spine upward/downward from cy
    # Target: extend to cy-12 and cy+12
    max_extent = 14

    # Find current wire extent
    wire_top = cy
    wire_bot = cy
    for y in range(max_extent + 1):
        if has_wire(wire_col, cy - y) or has_plant(wire_col, cy - y):
            wire_top = cy - y
        else:
            break

    wire_bot_found = cy
    for y in range(max_extent + 1):
        if has_wire(wire_col, cy + y) or has_plant(wire_col, cy + y):
            wire_bot_found = cy + y
        else:
            break

    # Try to extend wire upward
    next_wire_up = wire_top - 1
    if next_wire_up >= cy - max_extent and next_wire_up >= 1:
        if not has_wire(wire_col, next_wire_up) and not has_plant(wire_col, next_wire_up):
            return (Tool.WIRE, wire_col, next_wire_up)

    # Try to extend wire downward
    next_wire_down = wire_bot_found + 1
    if next_wire_down <= cy + max_extent and next_wire_down < WORLD_H - 1:
        if not has_wire(wire_col, next_wire_down) and not has_plant(wire_col, next_wire_down):
            return (Tool.WIRE, wire_col, next_wire_down)

    # Phase 2: Build road spine at road_col
    # Scan road extent
    road_top = cy
    road_bot = cy

    for y in range(max_extent + 1):
        if has_road(road_col, cy - y):
            road_top = cy - y
        else:
            break

    for y in range(max_extent + 1):
        if has_road(road_col, cy + y):
            road_bot = cy + y
        else:
            break

    # Wire must precede road: only place road where wire exists at same y
    next_road_up = road_top - 1
    if next_road_up >= cy - max_extent and next_road_up >= 1:
        if (has_wire(wire_col, next_road_up) or has_plant(wire_col, next_road_up)) and not has_road(road_col, next_road_up):
            return (Tool.ROAD, road_col, next_road_up)

    next_road_down = road_bot + 1
    if next_road_down <= cy + max_extent and next_road_down < WORLD_H - 1:
        if (has_wire(wire_col, next_road_down) or has_plant(wire_col, next_road_down)) and not has_road(road_col, next_road_down):
            return (Tool.ROAD, road_col, next_road_down)

    # Phase 3: Place residential zones where road and wire exist
    # Left zones: center at (cx-4, row) where row is multiple of 3 from cy
    # Right zones: center at (cx+3, row)

    for dy in range(-max_extent + 1, max_extent, 3):
        row = cy + dy
        if row < 2 or row >= WORLD_H - 2:
            continue

        # Check wire and road reach this row
        wire_ok = has_wire(wire_col, row) or has_plant(wire_col, row)
        road_ok = has_road(road_col, row)

        if wire_ok and road_ok:
            # Left residential: center at res_col_left, row
            if not has_res(res_col_left, row) and not has_plant(res_col_left, row):
                # Check it's reasonably clear (center tile)
                return (Tool.RESIDENTIAL, res_col_left, row)

            # Right residential: center at res_col_right, row
            if not has_res(res_col_right, row):
                return (Tool.RESIDENTIAL, res_col_right, row)

    # Phase 4: Add a second road column further right for more zones
    road_col2 = cx + 6
    wire_col2 = cx + 5
    res_col_right2 = cx + 9

    # Need wire from plant to right side - add horizontal wire at cy
    # First ensure horizontal connection
    for hx in range(wire_col + 1, wire_col2 + 1):
        if not has_wire(hx, cy) and not has_road(hx, cy) and not has_plant(hx, cy):
            # Only if previous tile has wire
            if has_wire(hx - 1, cy) or has_plant(hx - 1, cy):
                return (Tool.WIRE, hx, cy)

    # Second vertical wire spine
    if has_wire(wire_col2, cy):
        for y in range(max_extent + 1):
            if not has_wire(wire_col2, cy - y):
                if has_wire(wire_col2, cy - y + 1) or has_plant(wire_col2, cy - y + 1):
                    return (Tool.WIRE, wire_col2, cy - y)
                break
            if not has_wire(wire_col2, cy + y):
                if has_wire(wire_col2, cy + y - 1) or has_plant(wire_col2, cy + y - 1):
                    return (Tool.WIRE, wire_col2, cy + y)
                break

    # Second road spine
    if has_wire(wire_col2, cy):
        for y in range(-max_extent + 1, max_extent):
            row = cy + y
            if row < 1 or row >= WORLD_H - 1:
                continue
            if has_wire(wire_col2, row) and not has_road(road_col2, row):
                return (Tool.ROAD, road_col2, row)

    # More zones on right side
    for dy in range(-max_extent + 1, max_extent, 3):
        row = cy + dy
        if row < 2 or row >= WORLD_H - 2:
            continue
        if has_wire(wire_col2, row) and has_road(road_col2, row):
            if not has_res(res_col_right2, row):
                return (Tool.RESIDENTIAL, res_col_right2, row)

    # If nothing else to do, check if any zone lacks road access and add it
    # Also try commercial zones for balance
    for dy in range(-max_extent + 1, max_extent, 6):
        row = cy + dy
        if row < 2 or row >= WORLD_H - 2:
            continue
        if has_wire(wire_col, row) and has_road(road_col, row):
            com_x = cx - 7
            if com_x >= 2 and not has_res(com_x, row):
                return (Tool.COMMERCIAL, com_x, row)

    return None

