    def tile_empty(x, y):
        return in_bounds(x, y) and bool(em[y, x])

    def tile_wire_or_plant(x, y):
        return in_bounds(x, y) and (bool(wm[y, x]) or bool(pm[y, x]))

    # --- Phase 1: Place power plant if none exists ---
    has_plant = np.any(pm)
    if not has_plant:
        return (Tool.COALPOWER, CX, CY)

    # Plant anchor
    plant_ys, plant_xs = np.where(pm)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    # Current zone counts
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(total_zones, 1)
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Build sets for fast lookup
    wire_ys, wire_xs = np.where(wm)
    road_ys, road_xs = np.where(rm)
    res_ys, res_xs = np.where(resm)
    com_ys, com_xs = np.where(comm)
    ind_ys, ind_xs = np.where(indm)

    wire_set = set(zip(wire_ys.tolist(), wire_xs.tolist()))
    road_set = set(zip(road_ys.tolist(), road_xs.tolist()))
    zone_ys = np.concatenate([res_ys, com_ys, ind_ys])
    zone_xs = np.concatenate([res_xs, com_xs, ind_xs])
    zone_set = set(zip(zone_ys.tolist(), zone_xs.tolist()))

    # --- Phase 2: Build wire spine from plant ---
    # Horizontal wire spine at py, extending right
    spine_y = py
    # Wire rightward along spine
    rightmost_wire_x = px
    for (wr, wc) in wire_set:
        if wr == spine_y and wc > rightmost_wire_x:
            rightmost_wire_x = wc

    target_wire_x = px + 45  # how far right to extend wire
    if rightmost_wire_x < target_wire_x:
        nx = rightmost_wire_x + 1
        ny = spine_y
        if in_bounds(nx, ny) and tile_empty(nx, ny):
            return (Tool.WIRE, nx, ny)

    # Wire vertically from plant (both directions)
    for dy in range(1, 20):
        wy, wx = py - dy, px
        if not in_bounds(wx, wy): break
        if (wy, wx) not in wire_set and tile_empty(wx, wy):
            return (Tool.WIRE, wx, wy)
        if not tile_wire_or_plant(wx, wy): break

    for dy in range(1, 20):
        wy, wx = py + dy, px
        if not in_bounds(wx, wy): break
        if (wy, wx) not in wire_set and tile_empty(wx, wy):
            return (Tool.WIRE, wx, wy)
        if not tile_wire_or_plant(wx, wy): break

    # --- Phase 3: Build road grid ---
    # Two horizontal road spines offset from wire spine
    road_row_top = spine_y - 4
    road_row_bot = spine_y + 4
    road_x_start = px + 3
    road_x_end = px + 43

    # Extend top road rightward
    top_cols = [c for (r, c) in road_set if r == road_row_top and c >= road_x_start]
    max_top = max(top_cols) if top_cols else road_x_start - 1
    if max_top < road_x_end:
        nx, ny = max_top + 1, road_row_top
        if in_bounds(nx, ny) and not bool(pm[ny, nx]):
            return (Tool.ROAD, nx, ny)

    # Extend bottom road rightward
    bot_cols = [c for (r, c) in road_set if r == road_row_bot and c >= road_x_start]
    max_bot = max(bot_cols) if bot_cols else road_x_start - 1
    if max_bot < road_x_end:
        nx, ny = max_bot + 1, road_row_bot
        if in_bounds(nx, ny) and not bool(pm[ny, nx]):
            return (Tool.ROAD, nx, ny)

    # Vertical connector roads every 5 cols
    for vc in range(road_x_start, road_x_end + 1, 5):
        if not in_bounds(vc, road_row_top): continue
        for vr in range(road_row_top, road_row_bot + 1):
            if (vr, vc) not in road_set and in_bounds(vc, vr) and not bool(pm[vr, vc]):
                return (Tool.ROAD, vc, vr)

    # Also: road adjacent to wire spine (one col right of spine)
    road_spine_x = px + 1
    for dy in range(-16, 17):
        ry, rx = spine_y + dy, road_spine_x
        if not in_bounds(rx, ry): continue
        if (ry, rx) not in road_set and not bool(pm[ry, rx]):
            return (Tool.ROAD, rx, ry)

    # Additional parallel roads for more zone coverage
    road_row_top2 = spine_y - 9
    road_row_bot2 = spine_y + 9
    for rrow in [road_row_top2, road_row_bot2]:
        rcols = [c for (r, c) in road_set if r == rrow and c >= road_x_start]
        max_rc = max(rcols) if rcols else road_x_start - 1
        if max_rc < road_x_end:
            nx, ny = max_rc + 1, rrow
            if in_bounds(nx, ny) and not bool(pm[ny, nx]):
                return (Tool.ROAD, nx, ny)

    # --- Phase 4: Dilate masks for zone placement ---
    # Compute "near road" and "near wire" masks via dilation
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr): return False
                if not em[nr, nc] and (nr, nc) not in zone_set: return False
        return True

    # --- Phase 5: Place zones in candidate locations ---
    # Scan in a structured way: zone rows near roads, zone cols near wire spine
    zone_rows_above = [road_row_top - 2, road_row_top - 5, road_row_top - 8,
                       road_row_top2 - 2, road_row_top2 - 5]
    zone_rows_below = [road_row_bot + 2, road_row_bot + 5, road_row_bot + 8,
                       road_row_bot2 + 2, road_row_bot2 + 5]
    zone_rows_all = zone_rows_above + zone_rows_below
    zone_cols_all = list(range(road_x_start + 1, road_x_end, 5))

    for zr in zone_rows_all:
        for zc in zone_cols_all:
            if not (2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3): continue
            if zone_clear(zc, zr) and nbr_road[zr, zc] and nbr_wire[zr, zc]:
                return (pick_tool(), zc, zr)

    # Reactive: use the candidate mask to find any eligible spot
    cand = em & nbr_road & nbr_wire
    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        # Sort by proximity to spine center, pick best
        dists = np.abs(cys - spine_y) + np.abs(cxs - (px + 20))
        order = np.argsort(dists)
        for idx in order[:30]:
            zx, zy = int(cxs[idx]), int(cys[idx])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # --- Phase 6: Extend wire toward unserved zones ---
    for (zyr, zxc) in list(zone_set)[:20]:
        if not nbr_wire[zyr, zxc]:
            # Find closest wire tile and step toward zone
            if wire_set:
                closest_w = min(wire_set, key=lambda p: abs(p[0] - zyr) + abs(p[1] - zxc))
                wr, wc = closest_w
                # Step toward zone row-first
                step_r = (1 if zyr > wr else -1 if zyr < wr else 0)
                step_c = (1 if zxc > wc else -1 if zxc < wc else 0)
                for nr, nc in [(wr + step_r, wc), (wr, wc + step_c)]:
                    if in_bounds(nc, nr) and tile_empty(nc, nr):
                        return (Tool.WIRE, nc, nr)

    # --- Phase 7: Second power plant when zones grow ---
    if obs.city_pop > 200 and np.sum(pm) < 9:
        # Place second plant further right
        nx2, ny2 = px + 35, py
        if in_bounds(nx2, ny2) and tile_empty(nx2, ny2):
            return (Tool.COALPOWER, nx2, ny2)

    # --- Phase 8: Services ---
    if obs.city_pop > 150:
        fx, fy = px + 4, py - 12
        if in_bounds(fx, fy) and tile_empty(fx, fy):
            return (Tool.FIRESTATION, fx, fy)
        fx2, fy2 = px + 4, py + 12
        if in_bounds(fx2, fy2) and tile_empty(fx2, fy2):
            return (Tool.POLICESTATION, fx2, fy2)

    # --- Phase 9: Extend road from frontier ---
    if len(road_xs) > 0:
        k = int(obs.step * 13 + obs.city_pop) % len(road_xs)
        rx, ry = int(road_xs[k]), int(road_ys[k])
        for dx, dy in [(1, 0), (0, 1), (-1, 0), (0, -1)]:
            nx2, ny2 = rx + dx, ry + dy
            if in_bounds(nx2, ny2) and tile_empty(nx2, ny2) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads current map state each step and decides next action.
    Strategy:
    - Place coal power plant near center-left
    - Extend wires from plant rightward
    - Extend roads parallel to wires
    - Place zones adjacent to existing roads/wires, adapting to what's already there
    """
    tm = obs.tile_map
    step = obs.step

    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    # Counts
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Plant info
    plant_cells = list(zip(*np.where(pm))) if np.any(pm) else []
    has_plant = len(plant_cells) > 0

    # Wire, road info
    wire_cells = list(zip(*np.where(wm))) if np.any(wm) else []
    road_cells = list(zip(*np.where(rm))) if np.any(rm) else []

    # Configuration: horizontal layout
    # Power plant 1 at (20, 50), power plant 2 at (90, 50)
    P1X, P1Y = 20, 50
    P2X, P2Y = 90, 50
    SPINE_Y = 50
    ROAD1_Y = 47  # road above spine
    ROAD2_Y = 53  # road below spine

    # Helper: check if 3x3 area centered at (cx, cy) is free
    def area_free_3x3(cy, cx):
        for dy in [-1, 0, 1]:
            for dx in [-1, 0, 1]:
                ny, nx = cy + dy, cx + dx
                if ny < 0 or ny >= WORLD_H or nx < 0 or nx >= WORLD_W:
                    return False
                if not em[ny, nx]:
                    return False
        return True

    # Helper: is there a road or wire within distance d of (cy, cx)?
    def road_wire_near(cy, cx, d=3):
        y0 = max(0, cy - d)
        y1 = min(WORLD_H - 1, cy + d)
        x0 = max(0, cx - d)
        x1 = min(WORLD_W - 1, cx + d)
        return bool(np.any(rm[y0:y1+1, x0:x1+1]) or np.any(wm[y0:y1+1, x0:x1+1]))

    def wire_near(cy, cx, d=4):
        y0 = max(0, cy - d)
        y1 = min(WORLD_H - 1, cy + d)
        x0 = max(0, cx - d)
        x1 = min(WORLD_W - 1, cx + d)
        return bool(np.any(wm[y0:y1+1, x0:x1+1]) or np.any(pm[y0:y1+1, x0:x1+1]))

    # Phase 1: Place first power plant
    if not has_plant:
        return (Tool.COALPOWER, P1X, P1Y)

    # Count plants by scanning for second plant
    num_plants = len(plant_cells)
    # Plant footprint is 4x4, center tile marks. Use count of plant cells as proxy.
    # If only one plant cluster exists, place second
    # Find rightmost plant col
    if plant_cells:
        plant_cols = [c for (r, c) in plant_cells]
        max_plant_col = max(plant_cols)
    else:
        max_plant_col = P1X

    # Phase 2: Place second power plant if first exists and second not yet placed
    if max_plant_col < P2X - 10:
        # Check area around P2X, P2Y
        p2_area_ok = True
        for dy in range(-2, 3):
            for dx in range(-2, 3):
                ny, nx = P2Y + dy, P2X + dx
                if 0 <= ny < WORLD_H and 0 <= nx < WORLD_W:
                    if pm[ny, nx]:
                        p2_area_ok = False
                        break
        if p2_area_ok:
            return (Tool.COALPOWER, P2X, P2Y)

    # Phase 3: Extend wire spine from existing wire/plant rightward
    # Wire spine at row SPINE_Y, from col 24 to col 86
    spine_wire_cols = sorted([c for (r, c) in wire_cells if r == SPINE_Y])
    if spine_wire_cols:
        max_wc = max(spine_wire_cols)
    else:
        # Start wire just right of plant 1
        max_wc = P1X + 1

    spine_target = P2X - 2  # connect up to second plant
    if max_wc < spine_target:
        nc = max_wc + 1
        if 0 <= nc < WORLD_W and em[SPINE_Y, nc]:
            return (Tool.WIRE, nc, SPINE_Y)
        elif 0 <= nc < WORLD_W and wm[SPINE_Y, nc]:
            pass  # already wire, move on handled by max
        elif 0 <= nc < WORLD_W:
            # Bulldoze and place wire
            return (Tool.WIRE, nc, SPINE_Y)

    # Phase 4: Extend road1 (above spine)
    road1_cols = sorted([c for (r, c) in road_cells if r == ROAD1_Y])
    if road1_cols:
        max_r1c = max(road1_cols)
    else:
        max_r1c = P1X - 1

    road_target = P2X + 5
    if max_r1c < road_target:
        nc = max_r1c + 1
        if 0 <= nc < WORLD_W:
            return (Tool.ROAD, nc, ROAD1_Y)

    # Phase 5: Extend road2 (below spine)
    road2_cols = sorted([c for (r, c) in road_cells if r == ROAD2_Y])
    if road2_cols:
        max_r2c = max(road2_cols)
    else:
        max_r2c = P1X - 1

    if max_r2c < road_target:
        nc = max_r2c + 1
        if 0 <= nc < WORLD_W:
            return (Tool.ROAD, nc, ROAD2_Y)

    # Phase 6: Place vertical connector roads every 6 cols
    zone_cols = list(range(P1X + 3, P2X, 6))
    for zc in zone_cols:
        # Connect ROAD1_Y to ROAD2_Y through spine
        for conn_y in range(ROAD1_Y, ROAD2_Y + 1):
            if 0 <= zc < WORLD_W and 0 <= conn_y < WORLD_H:
                if not rm[conn_y, zc] and not wm[conn_y, zc] and not pm[conn_y, zc]:
                    return (Tool.ROAD, zc, conn_y)

    # Phase 7: Place vertical wires from spine up/down toward zone positions
    # Zones above: rows ROAD1_Y-3, ROAD1_Y-6, ROAD1_Y-9
    zone_rows_above = [ROAD1_Y - 3, ROAD1_Y - 6, ROAD1_Y - 9, ROAD1_Y - 12]
    zone_rows_below = [ROAD2_Y + 3, ROAD2_Y + 6, ROAD2_Y + 9, ROAD2_Y + 12]

    # Extend wires up from spine at zone cols
    for zc in zone_cols:
        for zr in zone_rows_above:
            if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                # Check if wire reaches from spine up to zr
                for wr in range(SPINE_Y - 1, zr - 2, -1):
                    if 0 <= wr < WORLD_H:
                        if wm[wr, zc] or pm[wr, zc]:
                            break  # already wired here
                        if em[wr, zc]:
                            return (Tool.WIRE, zc, wr)
                        break

    for zc in zone_cols:
        for zr in zone_rows_below:
            if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                for wr in range(SPINE_Y + 1, zr + 3):
                    if 0 <= wr < WORLD_H:
                        if wm[wr, zc] or pm[wr, zc]:
                            break
                        if em[wr, zc]:
                            return (Tool.WIRE, zc, wr)
                        break

    # Phase 8: Place zones at positions with road and wire access
    def pick_zone_type():
        total = res_count + com_count + ind_count + 1
        if com_count / total < 0.25:
            return Tool.COMMERCIAL
        elif ind_count / total < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    all_zone_positions = []
    for zr in zone_rows_above + zone_rows_below:
        for zc in zone_cols:
            all_zone_positions.append((zr, zc))

    for (zr, zc) in all_zone_positions:
        if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
            if road_wire_near(zr, zc, 3) and wire_near(zr, zc, 5):
                if area_free_3x3(zr, zc):
                    return (pick_zone_type(), zc, zr)

    # Phase 9: Dynamically scan map for empty 3x3 areas near roads
    # that have wire access — place zones there
    for scan_y in range(5, WORLD_H - 5, 3):
        for scan_x in range(5, WORLD_W - 5, 3):
            if road_wire_near(scan_y, scan_x, 2) and wire_near(scan_y, scan_x, 5):
                if area_free_3x3(scan_y, scan_x):
                    return (pick_zone_type(), scan_x, scan_y)

    # Phase 10: Extend wire from nearest wire cell to uncovered areas
    if wire_cells:
        # Find rightmost wire and extend
        rightmost = max(wire_cells, key=lambda x: x[1])
        nr, nc = rightmost[0], rightmost[1] + 1
        if 0 <= nc < WORLD_W and em[nr, nc]:
            return (Tool.WIRE, nc, nr)

    # Phase 11: Add more roads if needed
    for scan_y in range(ROAD1_Y - 15, ROAD1_Y + 16, 3):
        for scan_x in range(P1X, P2X, 3):
            if 0 <= scan_y < WORLD_H and 0 <= scan_x < WORLD_W:
                if not rm[scan_y, scan_x] and wire_near(scan_y, scan_x, 6):
                    if em[scan_y, scan_x]:
                        return (Tool.ROAD, scan_x, scan_y)

    return None

def act(obs, state):
    """
    Closed-loop policy: each step reads the current tile_map and decides
    what to place next based on what already exists.

    Strategy:
    1. If no power plant exists, place a coal plant at a fixed anchor.
    2. Extend wires from the power plant toward zones/empty areas.
    3. Build roads in a grid pattern around the power plant.
    4. Place zones (RES/COM/IND) adjacent to roads, prioritizing powered tiles.
    5. Add services (police/fire) periodically.
    """
    tm = obs.tile_map
    step = obs.step

    # Masks
    emp = empty_mask(tm)
    road = road_mask(tm)
    wire = wire_mask(tm)
    plant = plant_mask(tm)
    res = res_mask(tm)
    com = com_mask(tm)
    ind = ind_mask(tm)
    any_zone = res | com | ind

    # Phase counter for deterministic cycling
    phase = state.get("phase", 0)

    # Anchor: our main build center
    CX, CY = 40, 50

    # --- STEP 1: Ensure power plant exists ---
    plant_locs = np.argwhere(plant)
    if len(plant_locs) == 0:
        state["phase"] = 1
        return (Tool.COALPOWER, CX, CY)

    # Primary plant location
    py, px = plant_locs[0]

    # --- STEP 2: Extend wire network from plant ---
    # Wire should form a cross/spine from the plant
    # Find all wired tiles
    wired = wire | plant

    # Build wire spine: vertical from plant
    wire_targets = []
    for dy in range(-15, 16):
        wy = CY + dy
        wx = CX
        if 0 <= wy < 100 and 0 <= wx < 120:
            if not wired[wy, wx] and emp[wy, wx]:
                # Check if adjacent to wired tile
                for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]:
                    ny2, nx2 = wy + ddy, wx + ddx
                    if 0 <= ny2 < 100 and 0 <= nx2 < 120 and wired[ny2, nx2]:
                        wire_targets.append((wx, wy))
                        break

    # Horizontal wire spines at intervals
    for dy in [-9, -3, 3, 9]:
        wy = CY + dy
        for dx in range(-15, 16):
            wx = CX + dx
            if 0 <= wy < 100 and 0 <= wx < 120:
                if not wired[wy, wx] and emp[wy, wx]:
                    for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]:
                        ny2, nx2 = wy + ddy, wx + ddx
                        if 0 <= ny2 < 100 and 0 <= nx2 < 120 and wired[ny2, nx2]:
                            wire_targets.append((wx, wy))
                            break

    # Place wire if needed (prioritize early steps)
    if wire_targets and (step % 3 == 0 or np.sum(wired) < 20):
        wt = wire_targets[0]
        return (Tool.WIRE, wt[0], wt[1])

    # --- STEP 3: Build road grid ---
    # Roads on either side of wire spine, and cross-streets
    road_targets = []

    # Vertical roads flanking the wire spine
    for dy in range(-12, 13):
        for dx_off in [-1, 1, -2, 2]:
            rx = CX + dx_off
            ry = CY + dy
            if 0 <= ry < 100 and 0 <= rx < 120:
                if not road[ry, rx] and emp[ry, rx]:
                    # Adjacent to existing road or at start position
                    is_near_road = False
                    for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]:
                        ny2, nx2 = ry + ddy, rx + ddx
                        if 0 <= ny2 < 100 and 0 <= nx2 < 120:
                            if road[ny2, nx2] or (abs(rx - CX) <= 2 and abs(ry - CY) <= 1):
                                is_near_road = True
                                break
                    if is_near_road:
                        road_targets.append((rx, ry))

    # Horizontal roads at zone intervals
    for dy in range(-12, 13, 3):
        ry = CY + dy
        for dx in range(-12, 13):
            rx = CX + dx
            if 0 <= ry < 100 and 0 <= rx < 120:
                if not road[ry, rx] and emp[ry, rx]:
                    for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]:
                        ny2, nx2 = ry + ddy, rx + ddx
                        if 0 <= ny2 < 100 and 0 <= nx2 < 120 and road[ny2, nx2]:
                            road_targets.append((rx, ry))
                            break

    # Expand roads right side too (second cluster)
    CX2, CY2 = 80, 50
    for dy in range(-12, 13):
        for dx_off in [-1, 1]:
            rx = CX2 + dx_off
            ry = CY2 + dy
            if 0 <= ry < 100 and 0 <= rx < 120:
                if not road[ry, rx] and emp[ry, rx]:
                    for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]:
                        ny2, nx2 = ry + ddy, rx + ddx
                        if 0 <= ny2 < 100 and 0 <= nx2 < 120 and road[ny2, nx2]:
                            road_targets.append((rx, ry))
                            break

    # Road from CX to CX2 (horizontal)
    n_roads = int(np.sum(road))
    if n_roads > 5:
        for rx in range(CX + 3, CX2 - 1):
            ry = CY
            if 0 <= ry < 100 and 0 <= rx < 120:
                if not road[ry, rx] and emp[ry, rx]:
                    for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]:
                        ny2, nx2 = ry + ddy, rx + ddx
                        if 0 <= ny2 < 100 and 0 <= nx2 < 120 and road[ny2, nx2]:
                            road_targets.append((rx, ry))
                            break

    # Place road if we need more infrastructure
    n_zones = int(np.sum(any_zone))
    if road_targets and (step % 2 == 1 or n_zones < 5):
        rt = road_targets[step % max(1, len(road_targets))]
        return (Tool.ROAD, rt[0], rt[1])

    # --- STEP 4: Place zones adjacent to roads ---
    # Find empty tiles with road neighbors (zone needs road access)
    near_road = np.zeros((100, 120), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1),(-2,0),(2,0),(0,-2),(0,2)]:
        ys_r = np.arange(100)
        xs_r = np.arange(120)
        ny_r = np.clip(ys_r + dy, 0, 99)
        nx_r = np.clip(xs_r + dx, 0, 119)
        near_road |= road[np.ix_(ny_r, np.arange(120))]
        near_road |= road[np.ix_(np.arange(100), nx_r)]

    # Prefer tiles also near wires (powered)
    near_wire = np.zeros((100, 120), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1),(-2,0),(2,0),(0,-2),(0,2)]:
        ny_w = np.clip(np.arange(100) + dy, 0, 99)
        nx_w = np.clip(np.arange(120) + dx, 0, 119)
        near_wire |= wired[np.ix_(ny_w, np.arange(120))]
        near_wire |= wired[np.ix_(np.arange(100), nx_w)]

    # Zone candidates: empty, near road, near wire
    zone_cand = emp & near_road & near_wire
    ys_z, xs_z = np.where(zone_cand)

    if len(xs_z) == 0:
        # Relax: just near road
        zone_cand = emp & near_road
        ys_z, xs_z = np.where(zone_cand)

    if len(xs_z) > 0:
        # Pick based on distance to center (prefer close to CX, CY)
        dists = np.abs(xs_z - CX) + np.abs(ys_z - CY)
        # Prioritize closer tiles with some step-based variation
        k = int(step * 7 + obs.city_pop) % max(1, len(xs_z))
        # Sort by distance, pick from top candidates
        top_n = max(1, len(xs_z) // 4)
        sorted_idx = np.argsort(dists)[:top_n]
        k2 = k % top_n
        idx = sorted_idx[k2]
        x, y = int(xs_z[idx]), int(ys_z[idx])

        # Zone mix: 4 RES : 3 COM : 3 IND
        r = (step * 11 + obs.city_pop * 3) % 10
        if obs.com_pop < obs.res_pop // 3 + 1:
            tool = Tool.COMMERCIAL
        elif obs.ind_pop < obs.res_pop // 3 + 1:
            tool = Tool.INDUSTRIAL
        elif r < 4:
            tool = Tool.RESIDENTIAL
        elif r < 7:
            tool = Tool.COMMERCIAL
        else:
            tool = Tool.INDUSTRIAL

        return (tool, x, y)

    # --- STEP 5: Add second power plant if needed ---
    if obs.powered_zones < n_zones // 2 and n_zones > 10:
        # Place nuclear near second cluster
        if emp[CY2, CX2]:
            return (Tool.NUCLEARPOWER, CX2, CY2)
        # Wire to second cluster
        for wx in range(CX + 2, CX2):
            if 0 <= wx < 120 and emp[CY - 1, wx]:
                return (Tool.WIRE, wx, CY - 1)

    # --- STEP 6: Services ---
    if step % 50 == 30:
        if emp[CY - 15, CX]:
            return (Tool.FIRESTATION, CX, CY - 15)
    if step % 50 == 35:
        if emp[CY + 15, CX]:
            return (Tool.POLICESTATION, CX, CY + 15)

    # --- FALLBACK: place road next to existing road ---
    ys_r, xs_r = np.where(road)
    if len(xs_r) > 0:
        k = step % len(xs_r)
        rx, ry = int(xs_r[k]), int(ys_r[k])
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx2, ny2 = rx + ddx, ry + ddy
            if 0 <= nx2 < 120 and 0 <= ny2 < 100 and emp[ny2, nx2]:
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop policy: each step reads the current tile_map and decides
    what to place next based on what's already there.

    Strategy:
    - Phase 0: Place coal power plant if not present
    - Phase 1: Extend wire spine from plant outward (vertically)
    - Phase 2: Extend road column adjacent to wire spine
    - Phase 3: Place residential zones adjacent to road
    - Phase 4: Add commercial/industrial zones for balance
    - Throughout: check connectivity, fill gaps
    """

    cx = WORLD_W // 2  # 60
    cy = WORLD_H // 2  # 50

    # Wire spine at cx, road at cx+1, zones to left (cx-3) and right (cx+4)
    spine_x = cx
    road_x = cx + 1
    left_zone_x = cx - 3
    right_zone_x = cx + 4

    # Vertical range for infrastructure
    y_min = cy - 15
    y_max = cy + 15

    # --- Phase 0: Ensure coal plant exists ---
    # Plant at (cx-2, cy) - just left of spine
    plant_x, plant_y = cx - 2, cy
    if not np.any(plant_mask(obs.tile_map)):
        return (Tool.COALPOWER, plant_x, plant_y)

    # --- Phase 1: Extend wire spine vertically ---
    # Find wire that's already placed, extend from there
    wires = wire_mask(obs.tile_map)
    roads = road_mask(obs.tile_map)

    # Check for missing wires in spine column
    for dy in range(y_min - cy, y_max - cy + 1):
        y = cy + dy
        if y < 1 or y >= WORLD_H - 1:
            continue
        if not wires[y, spine_x]:
            # Place wire here if it's reachable (adjacent to existing wire or plant)
            # Check adjacency
            has_adj_power = False
            # Check if adjacent to plant footprint (3x3 centered at plant_x, plant_y)
            for px in range(plant_x - 1, plant_x + 2):
                for py in range(plant_y - 1, plant_y + 2):
                    if abs(px - spine_x) <= 1 and abs(py - y) <= 1:
                        has_adj_power = True
            # Check adjacent wires
            for dx2, dy2 in [(-1,0),(1,0),(0,-1),(0,1)]:
                nx, ny = spine_x + dx2, y + dy2
                if 0 <= nx < WORLD_W and 0 <= ny < WORLD_H:
                    if wires[ny, nx]:
                        has_adj_power = True
            if has_adj_power or not np.any(wires[:, spine_x]):
                return (Tool.WIRE, spine_x, y)

    # --- Phase 2: Extend road column ---
    for dy in range(y_min - cy, y_max - cy + 1):
        y = cy + dy
        if y < 1 or y >= WORLD_H - 1:
            continue
        if not roads[y, road_x]:
            # Check adjacency to existing road
            has_adj = False
            for dx2, dy2 in [(-1,0),(1,0),(0,-1),(0,1)]:
                nx, ny = road_x + dx2, y + dy2
                if 0 <= nx < WORLD_W and 0 <= ny < WORLD_H:
                    if roads[ny, nx]:
                        has_adj = True
            if has_adj or not np.any(roads[:, road_x]):
                return (Tool.ROAD, road_x, y)

    # --- Phase 3: Place residential zones ---
    res = res_mask(obs.tile_map)
    com = com_mask(obs.tile_map)
    ind = ind_mask(obs.tile_map)

    # Count zones on left vs right
    left_zones = np.sum(res[:, left_zone_x-1:left_zone_x+2]) + \
                 np.sum(com[:, left_zone_x-1:left_zone_x+2]) + \
                 np.sum(ind[:, left_zone_x-1:left_zone_x+2])
    right_zones = np.sum(res[:, right_zone_x-1:right_zone_x+2]) + \
                  np.sum(com[:, right_zone_x-1:right_zone_x+2]) + \
                  np.sum(ind[:, right_zone_x-1:right_zone_x+2])

    # Place zones every 3 rows, alternating sides, mix of types
    zone_ys = list(range(y_min + 1, y_max - 1, 3))

    for zy in zone_ys:
        if zy < 2 or zy >= WORLD_H - 2:
            continue
        # Determine zone type based on position (mostly res, some com/ind)
        idx = zone_ys.index(zy)
        if idx % 5 == 2:
            ztype = Tool.COMMERCIAL
        elif idx % 7 == 4:
            ztype = Tool.INDUSTRIAL
        else:
            ztype = Tool.RESIDENTIAL

        # Check left side
        lx = left_zone_x
        # Check if zone center area is not already zoned
        zone_tiles = obs.tile_map[zy-1:zy+2, lx-1:lx+2]
        has_res_l = np.any(res[zy-1:zy+2, lx-1:lx+2])
        has_com_l = np.any(com[zy-1:zy+2, lx-1:lx+2])
        has_ind_l = np.any(ind[zy-1:zy+2, lx-1:lx+2])
        if not (has_res_l or has_com_l or has_ind_l):
            # Check road access: road should be within 1 tile of zone edge
            road_nearby = np.any(roads[zy-2:zy+3, lx-2:lx+3])
            if road_nearby or roads[zy, road_x]:
                return (ztype, lx, zy)

        # Check right side
        rx = right_zone_x
        has_res_r = np.any(res[zy-1:zy+2, rx-1:rx+2])
        has_com_r = np.any(com[zy-1:zy+2, rx-1:rx+2])
        has_ind_r = np.any(ind[zy-1:zy+2, rx-1:rx+2])
        if not (has_res_r or has_com_r or has_ind_r):
            road_nearby = np.any(roads[zy-2:zy+3, rx-2:rx+3])
            if road_nearby or roads[zy, road_x]:
                return (ztype, rx, zy)

    # --- Phase 4: Second road column for better road access ---
    road_x2 = cx + 2
    for dy in range(y_min - cy, y_max - cy + 1):
        y = cy + dy
        if y < 1 or y >= WORLD_H - 1:
            continue
        if not roads[y, road_x2]:
            has_adj = False
            for dx2, dy2 in [(-1,0),(1,0),(0,-1),(0,1)]:
                nx, ny = road_x2 + dx2, y + dy2
                if 0 <= nx < WORLD_W and 0 <= ny < WORLD_H:
                    if roads[ny, nx]:
                        has_adj = True
            if has_adj:
                return (Tool.ROAD, road_x2, y)

    # --- Phase 5: Expand further left with more wire and zones ---
    wire_x2 = cx - 4
    for dy in range(y_min - cy, y_max - cy + 1):
        y = cy + dy
        if y < 1 or y >= WORLD_H - 1:
            continue
        if not wires[y, wire_x2]:
            has_adj = False
            for dx2, dy2 in [(-1,0),(1,0),(0,-1),(0,1)]:
                nx, ny = wire_x2 + dx2, y + dy2
                if 0 <= nx < WORLD_W and 0 <= ny < WORLD_H:
                    if wires[ny, nx]:
                        has_adj = True
            if has_adj:
                return (Tool.WIRE, wire_x2, y)

    # Place extra residential zones further left
    extra_left_x = cx - 7
    for zy in zone_ys:
        if zy < 2 or zy >= WORLD_H - 2:
            continue
        lx = extra_left_x
        if lx < 2:
            continue
        has_any = np.any(res[zy-1:zy+2, lx-1:lx+2]) or \
                  np.any(com[zy-1:zy+2, lx-1:lx+2]) or \
                  np.any(ind[zy-1:zy+2, lx-1:lx+2])
        if not has_any:
            wire_nearby = np.any(wires[zy-2:zy+3, lx-2:lx+3])
            road_nearby = np.any(roads[zy-2:zy+3, lx-2:lx+3])
            if wire_nearby and road_nearby:
                return (Tool.RESIDENTIAL, lx, zy)

    # Add horizontal roads to connect zones
    for zy in zone_ys:
        if zy < 1 or zy >= WORLD_H - 1:
            continue
        # Connect road_x to left zone
        for rx in range(left_zone_x, road_x):
            if not roads[zy, rx]:
                has_adj = False
                for dx2, dy2 in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nx, ny = rx + dx2, zy + dy2
                    if 0 <= nx < WORLD_W and 0 <= ny < WORLD_H:
                        if roads[ny, nx]:
                            has_adj = True
                if has_adj:
                    return (Tool.ROAD, rx, zy)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map each step to decide next action
    - Places coal plant, then extends wire to reach zones, then roads, then zones
    - Adapts to what's actually on the map
    """
    tm = obs.tile_map
    step = obs.step

    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    plant_ys, plant_xs = np.where(pm)
    wire_ys, wire_xs = np.where(wm)
    road_ys, road_xs = np.where(rm)
    res_ys, res_xs = np.where(resm)
    com_ys, com_xs = np.where(comm)
    ind_ys, ind_xs = np.where(indm)

    has_plant = len(plant_xs) > 0
    has_wire = len(wire_xs) > 0
    has_road = len(road_xs) > 0

    n_res = len(res_xs)
    n_com = len(com_xs)
    n_ind = len(ind_xs)
    n_zones = n_res + n_com + n_ind

    # Target layout: power plant at (20, 50), wire spine going right along row 50
    # Road at row 47 and row 53 (parallel)
    # Zones placed between roads and wire spine
    PLANT_X, PLANT_Y = 20, 50
    SPINE_ROW = 50
    ROAD_ROW1 = 47
    ROAD_ROW2 = 53
    SPINE_START = 25  # where wire starts after plant
    SPINE_END = 100   # how far wire extends

    def is_empty_3x3(cx, cy):
        for dy in [-1, 0, 1]:
            for dx in [-1, 0, 1]:
                ny, nx = cy + dy, cx + dx
                if ny < 0 or ny >= WORLD_H or nx < 0 or nx >= WORLD_W:
                    return False
                if not em[ny, nx]:
                    return False
        return True

    def zone_type_for(cx, cy):
        # 50% res, 25% com, 25% ind based on current counts
        total = n_zones + 1
        if n_com / total < 0.25:
            return Tool.COMMERCIAL
        if n_ind / total < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def near_road(cx, cy, dist=3):
        for i in range(len(road_xs)):
            if abs(road_xs[i] - cx) <= dist and abs(road_ys[i] - cy) <= dist:
                return True
        return False

    def near_wire_or_plant(cx, cy, dist=5):
        for i in range(len(wire_xs)):
            if abs(wire_xs[i] - cx) <= dist and abs(wire_ys[i] - cy) <= dist:
                return True
        for i in range(len(plant_xs)):
            if abs(plant_xs[i] - cx) <= dist and abs(plant_ys[i] - cy) <= dist:
                return True
        return False

    # Step 1: Place coal power plant if none exists
    if not has_plant:
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    # Step 2: Extend wire spine eastward along SPINE_ROW
    # Find rightmost wire on spine row
    spine_wire_cols = wire_xs[wire_ys == SPINE_ROW] if has_wire else np.array([])
    if len(spine_wire_cols) > 0:
        max_wire_col = int(spine_wire_cols.max())
    else:
        # Start wire adjacent to plant (plant is 3x3, center at PLANT_X)
        max_wire_col = PLANT_X + 1  # just right of plant footprint

    if max_wire_col < SPINE_END:
        next_col = max_wire_col + 1
        if 0 <= next_col < WORLD_W:
            # Don't overwrite plant
            if not pm[SPINE_ROW, next_col]:
                return (Tool.WIRE, next_col, SPINE_ROW)

    # Step 3: Build road along ROAD_ROW1 (above spine)
    road1_cols = road_xs[road_ys == ROAD_ROW1] if has_road else np.array([])
    if len(road1_cols) > 0:
        max_road1 = int(road1_cols.max())
    else:
        max_road1 = SPINE_START - 1

    if max_road1 < SPINE_END:
        nc = max_road1 + 1
        if 0 <= nc < WORLD_W and not pm[ROAD_ROW1, nc]:
            return (Tool.ROAD, nc, ROAD_ROW1)

    # Step 4: Build road along ROAD_ROW2 (below spine)
    road2_cols = road_xs[road_ys == ROAD_ROW2] if has_road else np.array([])
    if len(road2_cols) > 0:
        max_road2 = int(road2_cols.max())
    else:
        max_road2 = SPINE_START - 1

    if max_road2 < SPINE_END:
        nc = max_road2 + 1
        if 0 <= nc < WORLD_W and not pm[ROAD_ROW2, nc]:
            return (Tool.ROAD, nc, ROAD_ROW2)

    # Step 5: Build vertical connector roads between ROAD_ROW1 and ROAD_ROW2 at intervals
    for conn_col in range(SPINE_START, SPINE_END + 1, 6):
        for conn_row in range(ROAD_ROW1, ROAD_ROW2 + 1):
            if 0 <= conn_col < WORLD_W and 0 <= conn_row < WORLD_H:
                if not rm[conn_row, conn_col] and not wm[conn_row, conn_col] and not pm[conn_row, conn_col]:
                    return (Tool.ROAD, conn_col, conn_row)

    # Step 6: Place zones above ROAD_ROW1 and below ROAD_ROW2
    # Zone rows: centered at ROAD_ROW1-3, ROAD_ROW1-6, ROAD_ROW1-9
    #            and ROAD_ROW2+3, ROAD_ROW2+6, ROAD_ROW2+9
    zone_rows_above = [ROAD_ROW1 - 3, ROAD_ROW1 - 6, ROAD_ROW1 - 9, ROAD_ROW1 - 12]
    zone_rows_below = [ROAD_ROW2 + 3, ROAD_ROW2 + 6, ROAD_ROW2 + 9, ROAD_ROW2 + 12]
    zone_cols = list(range(SPINE_START + 2, SPINE_END, 6))

    for zr in zone_rows_above + zone_rows_below:
        for zc in zone_cols:
            if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                if is_empty_3x3(zc, zr):
                    if near_road(zc, zr, dist=4) and near_wire_or_plant(zc, zr, dist=8):
                        return (zone_type_for(zc, zr), zc, zr)

    # Step 7: Extend wire vertically to reach zones that need power
    # Check if any zone lacks wire nearby and add vertical wire branches
    all_zone_xs = list(res_xs) + list(com_xs) + list(ind_xs)
    all_zone_ys = list(res_ys) + list(com_ys) + list(ind_ys)
    for i in range(len(all_zone_xs)):
        zx, zy = int(all_zone_xs[i]), int(all_zone_ys[i])
        if not near_wire_or_plant(zx, zy, dist=4):
            # Try to add wire connecting from spine to this zone
            # Go vertically from spine row toward zone
            direction = -1 if zy < SPINE_ROW else 1
            for wr in range(SPINE_ROW + direction, zy, direction):
                if 0 <= wr < WORLD_H and 0 <= zx < WORLD_W:
                    if not wm[wr, zx] and not pm[wr, zx]:
                        if em[wr, zx]:
                            return (Tool.WIRE, zx, wr)
                        break

    # Step 8: Add second power plant if funded and population growing
    if obs.city_pop > 500 and len(plant_xs) < 2:
        px2, py2 = 80, 50
        if is_empty_3x3(px2, py2):
            return (Tool.COALPOWER, px2, py2)

    # Step 9: Try to place more zones in expanded area if pop is growing
    if obs.city_pop > 200:
        extra_rows = [ROAD_ROW1 - 15, ROAD_ROW2 + 15]
        for zr in extra_rows:
            for zc in zone_cols:
                if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                    if is_empty_3x3(zc, zr):
                        if near_road(zc, zr, dist=5):
                            return (zone_type_for(zc, zr), zc, zr)

    # Step 10: Fill gaps in roads
    for road_row in [ROAD_ROW1, ROAD_ROW2]:
        for nc in range(SPINE_START, SPINE_END + 1):
            if 0 <= nc < WORLD_W and 0 <= road_row < WORLD_H:
                if not rm[road_row, nc] and not pm[road_row, nc]:
                    return (Tool.ROAD, nc, road_row)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map each step to decide next action
    - Places coal plant, then extends wire and road from existing infrastructure
    - Places zones adjacent to powered roads
    - Adapts to what's already on the map
    """
    tm = obs.tile_map
    step = obs.step

    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # Map center
    cx, cy = 60, 50

    # Power plant position (left of center, row 50)
    plant_x, plant_y = cx - 8, cy

    def tile_ok(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def has_tile(mask, x, y):
        return tile_ok(x, y) and bool(mask[y, x])

    def zone_area_free(cx_, cy_):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                r, c = cy_ + dr, cx_ + dc
                if not tile_ok(c, r) or not em[r, c]:
                    return False
        return True

    # Phase 0: Place coal plant if missing
    if not np.any(pm):
        return (Tool.COALPOWER, plant_x, plant_y)

    # Find existing plant location(s)
    plant_ys, plant_xs = np.where(pm)
    # Use first plant as anchor
    p0x, p0y = int(plant_xs[0]), int(plant_ys[0])

    # Phase 1: Extend horizontal wire spine from plant rightward
    # Spine at row p0y, from p0x+2 to cx+35
    spine_y = p0y
    spine_start = p0x + 2
    spine_end = cx + 35  # ~95

    # Find rightmost wire on spine row
    wire_on_spine = [int(c) for (r, c) in zip(*np.where(wm)) if int(r) == spine_y]
    if wire_on_spine:
        max_wire_x = max(wire_on_spine)
    else:
        max_wire_x = spine_start - 1

    if max_wire_x < spine_end:
        nx = max_wire_x + 1
        if tile_ok(nx, spine_y) and not has_tile(pm, nx, spine_y):
            return (Tool.WIRE, nx, spine_y)

    # Phase 2: Extend road spine just below wire (spine_y + 2)
    road_y = spine_y + 2
    road_start = p0x + 2
    road_end = spine_end

    road_on_row = [int(c) for (r, c) in zip(*np.where(rm)) if int(r) == road_y]
    if road_on_row:
        max_road_x = max(road_on_row)
    else:
        max_road_x = road_start - 1

    if max_road_x < road_end:
        nx = max_road_x + 1
        if tile_ok(nx, road_y):
            return (Tool.ROAD, nx, road_y)

    # Also extend road above wire (spine_y - 2)
    road_y2 = spine_y - 2
    road_on_row2 = [int(c) for (r, c) in zip(*np.where(rm)) if int(r) == road_y2]
    if road_on_row2:
        max_road_x2 = max(road_on_row2)
    else:
        max_road_x2 = road_start - 1

    if max_road_x2 < road_end:
        nx = max_road_x2 + 1
        if tile_ok(nx, road_y2):
            return (Tool.ROAD, nx, road_y2)

    # Phase 3: Place zones adjacent to roads
    # Scan for road tiles and try to place zones nearby
    road_ys, road_xs = np.where(rm)
    res_count = int(np.sum(res_m))
