    for dy in range(1, 22):
        for sign in [-1, 1]:
            wy, wx = spine_y + sign * dy, spine_x
            if not in_bounds(wx, wy):
                continue
            if not (bool(wm[wy, wx]) or bool(pm[wy, wx])):
                if bool(em[wy, wx]):
                    return (Tool.WIRE, wx, wy)
                break

    # Horizontal wire spine (rightward from plant)
    for dx in range(1, 50):
        wy, wx = spine_y, spine_x + dx
