        if in_bounds(fx2, fy2) and bool(em[fy2, fx2]):
            return (Tool.POLICESTATION, fx2, fy2)

    # --- Last resort: extend road frontier ---
    if len(road_xs) > 0:
        k = int(obs.step * 11) % len(road_xs)
        rx, ry = int(road_xs[k]), int(road_ys[k])
        for dx2, dy2 in [(1, 0), (0, 1), (-1, 0), (0, -1)]:
            nx2, ny2 = rx + dx2, ry + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # --- Extend wire toward farthest road tile without wire access ---
    if len(road_xs) > 0 and len(wire_xs) > 0:
        # Find road tiles far from wire
        max_dist = 0
        target = None
        sample = list(zip(road_ys.tolist(), road_xs.tolist()))
        for (rr, rc) in sample[::max(1, len(sample)//20)]:
            if not nbr_wire[rr, rc]:
                # Find closest wire
                dists = [abs(rr - wr) + abs(rc - wc) for (wr, wc) in wire_set]
                if dists:
                    d = min(dists)
