        return (Tool.COALPOWER, cx, cy)

    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    # Phase 2: Build horizontal wire spine from plant outward
    # Plant center at cx, cy. Footprint: cx-1..cx+1, cy-1..cy+1
    # Wire row = cy, extend left and right
    wire_row = cy
    wire_row_cols = [c for (r, c) in wire_positions if r == wire_row]

    if not wire_row_cols:
        # Start wire to the right of plant
        return (Tool.WIRE, cx + 2, wire_row)
    else:
        min_col = min(wire_row_cols)
        max_col = max(wire_row_cols)
        target_min = cx - 18
        target_max = cx + 18

        if max_col < target_max and max_col + 1 < WORLD_W:
            nc = max_col + 1
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)
        if min_col > target_min and min_col - 1 >= 0:
            nc = min_col - 1
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    wire_row_cols_sorted = sorted(wire_row_cols)

    # Phase 3: Build vertical roads at regular intervals along the wire spine
    # Road columns every 4 tiles along the wire spine
    road_cols = list(range(cx - 16, cx + 17, 4))

    for rc in road_cols:
        if rc < 0 or rc >= WORLD_W:
            continue
        # Only build road column if wire exists at this col row
        if rc not in wire_row_cols_sorted:
            continue
        # Build road column from cy-10 to cy+10
        road_col_rows = [r for (r, c) in road_positions if c == rc]
        for r in range(cy - 10, cy + 11):
            if 0 <= r < WORLD_H and r not in road_col_rows:
                if em[r, rc]:
                    return (Tool.ROAD, rc, r)

    # Phase 4: Build horizontal roads connecting the vertical roads
    # Two horizontal roads: cy-6 and cy+6
    h_road_rows = [cy - 6, cy + 6]
    for hr in h_road_rows:
        if hr < 0 or hr >= WORLD_H:
            continue
        for c in range(cx - 16, cx + 17):
            if 0 <= c < WORLD_W:
                if not rm[hr, c]:
                    if em[hr, c]:
