    # Zone columns between road columns, zone rows between horizontal roads
    # Zone positions: between each pair of road cols, above/below horizontal roads

    # Determine zone placement grid
    # Between road cols (spaced 4 apart), zone centers at rc+2 (middle between rc and rc+4)
    zone_col_offsets = [2]  # offset from road col to zone center col
    # Zone rows: cy-9 (above top h_road), cy-3 (between h_roads top half),
    #            cy+3 (between h_roads bottom half), cy+9 (below bottom h_road)
    zone_rows = [cy - 9, cy - 3, cy + 3, cy + 9]

    # Build zone list
    planned_zones = []
    for rci in range(len(road_cols) - 1):
        rc1 = road_cols[rci]
        rc2 = road_cols[rci + 1]
        zc = (rc1 + rc2) // 2
        for zr in zone_rows:
            planned_zones.append((zr, zc))

    # Place zones with R:C:I = 2:1:1 ratio
    zone_idx = [0]  # track which zone type to place next

    for (zr, zc) in planned_zones:
        if zr < 0 or zr >= WORLD_H or zc < 0 or zc >= WORLD_W:
            continue
        # Check if near a road
        near_road = any(
            abs(zr - rr) <= 2 or abs(zc - rc) <= 2
            for (rr, rc) in road_positions
        )
        if not near_road:
            continue
        # Check not already placed
        already = any(abs(zr - pr) <= 1 and abs(zc - pc) <= 1
                      for (pr, pc) in res_positions)
        if already:
            continue
        if zone_area_free(zr, zc):
            # Determine zone type based on counts
            total = res_count + com_count + ind_count
            if total == 0 or res_count < (total + 1) // 2:
                return (Tool.RESIDENTIAL, zc, zr)
            elif com_count <= ind_count:
                return (Tool.COMMERCIAL, zc, zr)
            else:
                return (Tool.INDUSTRIAL, zc, zr)

    # Phase 6: Extend wire vertically to reach zones above/below wire row
    # Wire at cy, zones at cy-9, cy-3, cy+3, cy+9 - need vertical wire connectors
    for wc in wire_row_cols_sorted:
        for wr in [cy - 6, cy + 6, cy - 9, cy + 9, cy - 3, cy + 3]:
            if 0 <= wr < WORLD_H and 0 <= wc < WORLD_W:
                if em[wr, wc]:
                    # Check if this column needs wire (has a road col nearby)
                    if any(abs(wc - rc) <= 1 for rc in road_cols):
                        return (Tool.WIRE, wc, wr)

    # Phase 7: Add second power plant if population is large enough
    if obs.city_pop > 500 and not any(
        abs(cy - r) <= 1 and abs(cx + 20 - c) <= 1
        for (r, c) in list(zip(*np.where(plant_mask(tm))))
