            elif not wm[py, wx]:
                break

    # Phase 3: Short vertical wires from spine every 4 cols (to reach zones above/below)
    # Wire goes 3 up and 3 down from spine
    for wx in range(px + 4, wire_end_x, 4):
        if not in_bounds(wx, py):
            continue
        if (py, wx) not in wire_coords and not pm[py, wx]:
            continue  # spine not built yet here
        for wy in list(range(py - 3, py)) + list(range(py + 1, py + 4)):
            if not in_bounds(wx, wy):
                continue
            if (wy, wx) not in wire_coords and not pm[wy, wx] and em[wy, wx]:
                return (Tool.WIRE, wx, wy)

    # Phase 4: Build road grid
    # Two horizontal roads: py-4 and py+4, from px+3 to wire_end_x
    road_y_top = py - 4
    road_y_bot = py + 4
    road_x_start = px + 3
    road_x_end = min(px + 55, WORLD_W - 3)

    # Top road
    for rx in range(road_x_start, road_x_end + 1):
        if not in_bounds(rx, road_y_top):
            continue
        if (road_y_top, rx) not in road_coords and not pm[road_y_top, rx]:
            return (Tool.ROAD, rx, road_y_top)

    # Bottom road
    for rx in range(road_x_start, road_x_end + 1):
        if not in_bounds(rx, road_y_bot):
            continue
        if (road_y_bot, rx) not in road_coords and not pm[road_y_bot, rx]:
            return (Tool.ROAD, rx, road_y_bot)

    # Vertical connector roads every 4 cols between top and bottom roads
    for rx in range(road_x_start, road_x_end + 1, 4):
        for ry in range(road_y_top, road_y_bot + 1):
            if not in_bounds(rx, ry):
                continue
            if (ry, rx) not in road_coords and not pm[ry, rx]:
                return (Tool.ROAD, rx, ry)

    # Phase 5: Place zones adjacent to roads
    # Zones go in rows py-7, py-10, py+7, py+10 (above/below road spines)
    # centered at zone cols
    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                # Allow zone tiles and empty
                if not em[nr, nc] and (nr, nc) not in zone_coords:
                    return False
        return True

    def has_road_near(zx, zy, r=4):
        for dr in range(-r, r + 1):
            for dc in range(-r, r + 1):
                if (zy + dr, zx + dc) in road_coords:
                    return True
        return False

    def has_wire_near(zx, zy, r=5):
        for dr in range(-r, r + 1):
            for dc in range(-r, r + 1):
                nr, nc = zy + dr, zx + dc
                if (nr, nc) in wire_coords:
                    return True
                if in_bounds(nc, nr) and pm[nr, nc]:
                    return True
        return False

    zone_rows = [road_y_top - 2, road_y_top - 5, road_y_top - 8,
                 road_y_bot + 2, road_y_bot + 5, road_y_bot + 8]
    zone_cols = list(range(road_x_start + 1, road_x_end, 3))

    for zr in zone_rows:
        for zc in zone_cols:
            if not (2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3):
                continue
            if zone_clear(zc, zr) and has_road_near(zc, zr) and has_wire_near(zc, zr):
                return (pick_tool(), zc, zr)

    # Phase 6: If pop growing, add second power plant further right
    if obs.city_pop > 200 and np.sum(pm) < 9:
        nx2, ny2 = px + 50, py
        if in_bounds(nx2, ny2) and em[ny2, nx2]:
            return (Tool.COALPOWER, nx2, ny2)

    # Phase 7: Services
    if obs.city_pop > 150:
        fx, fy = px + 8, py - 12
        if in_bounds(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
        fx2, fy2 = px + 8, py + 12
        if in_bounds(fx2, fy2) and em[fy2, fx2]:
            return (Tool.POLICESTATION, fx2, fy2)

    # Phase 8: Reactively extend road toward empty areas near wire
    # Find frontier: road tiles with empty neighbor
    road_list = list(road_coords)
    if road_list:
        k = (obs.step * 13) % len(road_list)
        ry, rx = road_list[k]
        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx + dx, ry + dy
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                return (Tool.ROAD, nx2, ny2)

    # Phase 9: Fill zones near any road+wire using dilated masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            r0 = max(0, dy); sr0 = max(0, -dy)
            c0 = max(0, dx); sc0 = max(0, -dx)
            nbr_road[r0:, c0:] |= rm[sr0:WORLD_H - max(0, dy), sc0:WORLD_W - max(0, dx)]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            r0 = max(0, dy); sr0 = max(0, -dy)
            c0 = max(0, dx); sc0 = max(0, -dx)
            nbr_wire[r0:, c0:] |= wm[sr0:WORLD_H - max(0, dy), sc0:WORLD_W - max(0, dx)]
            nbr_wire[r0:, c0:] |= pm[sr0:WORLD_H - max(0, dy), sc0:WORLD_W - max(0, dx)]

    cand = em & nbr_road & nbr_wire
    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        k = (obs.step * 17) % len(cxs)
        zx, zy = int(cxs[k]), int(cys[k])
        if zone_clear(zx, zy):
            return (pick_tool(), zx, zy)

    return None

def act(obs, state):
    # Strategy: Build a horizontal layout instead of vertical spine
    # Two power plants, horizontal wire rows, roads between zone bands
    # Mixed RES/COM/IND in horizontal strips

    cx, cy = WORLD_W // 2, WORLD_H // 2

    pm = plant_mask(obs.tile_map)
    rm_road = road_mask(obs.tile_map)
    wm = wire_mask(obs.tile_map)
    res_m = res_mask(obs.tile_map)
    com_m = com_mask(obs.tile_map)
    ind_m = ind_mask(obs.tile_map)

    def has_tile(mask, x, y):
        if 0 <= y < WORLD_H and 0 <= x < WORLD_W:
            return bool(mask[y, x])
        return False

    # Layout:
    # Row cy-6: wire (horizontal power distribution)
    # Row cy-5: road
    # Row cy-4 to cy-2: RES zone centers at cy-3 (strip)
    # Row cy-1: road
    # Row cy:   wire
    # Row cy+1: road
    # Row cy+2 to cy+4: COM zone centers at cy+3
    # Row cy+5: road
    # Row cy+6: wire
    # Row cy+7 to cy+9: IND zone centers at cy+8
    # Power plants at x=cx-20, cy and x=cx+20, cy (on wire row cy)

    # X range for horizontal layout
    X_START = cx - 25
    X_END = cx + 25
    X_RANGE = range(X_START, X_END + 1)

    # Phase 0: Place first coal plant
    p1x, p1y = cx - 20, cy
    if not has_tile(pm, p1x, p1y):
        return (Tool.COALPOWER, p1x, p1y)

    # Phase 1: Lay horizontal wire at row cy from p1x to X_END
    for x in range(p1x + 2, X_END + 1):
        if not has_tile(wm, x, cy) and not has_tile(pm, x, cy):
            return (Tool.WIRE, x, cy)

    # Also wire at cy-6 (connect via vertical wire from p1x)
    # Vertical wire from plant up to cy-6
    for y in range(cy - 6, cy):
        if not has_tile(wm, p1x, y) and not has_tile(pm, p1x, y):
            return (Tool.WIRE, p1x, y)

    # Horizontal wire at cy-6
    for x in range(p1x, X_END + 1):
        if not has_tile(wm, x, cy - 6) and not has_tile(pm, x, cy - 6):
            return (Tool.WIRE, x, cy - 6)

    # Vertical wire from plant down to cy+6
    for y in range(cy + 1, cy + 7):
        if not has_tile(wm, p1x, y) and not has_tile(pm, p1x, y):
            return (Tool.WIRE, p1x, y)

    # Horizontal wire at cy+6
    for x in range(p1x, X_END + 1):
        if not has_tile(wm, x, cy + 6) and not has_tile(pm, x, cy + 6):
            return (Tool.WIRE, x, cy + 6)

    # Phase 2: Place roads at cy-5, cy-1, cy+1, cy+5
    for road_y in [cy - 5, cy - 1, cy + 1, cy + 5]:
        for x in X_RANGE:
            if not has_tile(rm_road, x, road_y):
                return (Tool.ROAD, x, road_y)

    # Phase 3: Place RES zones in strip around cy-3, every 3 cols
    for x in range(X_START + 1, X_END - 1, 3):
        if not has_tile(res_m, x, cy - 3) and not has_tile(pm, x, cy - 3):
            if has_tile(wm, x, cy - 6) or has_tile(rm_road, x, cy - 5):
                return (Tool.RESIDENTIAL, x, cy - 3)

    # Phase 4: Place COM zones in strip around cy+3, every 3 cols
    for x in range(X_START + 1, X_END - 1, 3):
        if not has_tile(com_m, x, cy + 3) and not has_tile(pm, x, cy + 3):
            if has_tile(wm, x, cy) or has_tile(rm_road, x, cy + 1):
                return (Tool.COMMERCIAL, x, cy + 3)

    # Phase 5: Place IND zones in strip around cy+8, every 3 cols
    for x in range(X_START + 1, X_END - 1, 3):
        if not has_tile(ind_m, x, cy + 8) and not has_tile(pm, x, cy + 8):
            if has_tile(wm, x, cy + 6) or has_tile(rm_road, x, cy + 5):
                return (Tool.INDUSTRIAL, x, cy + 8)

    # Phase 6: Second power plant on right side
    p2x, p2y = cx + 20, cy
    if not has_tile(pm, p2x, p2y):
        return (Tool.COALPOWER, p2x, p2y)

    # Phase 7: More RES above cy-6 (second tier)
    # Wire at cy-12, road at cy-11
    for x in range(p1x, X_END + 1):
        if not has_tile(wm, x, cy - 12) and not has_tile(pm, x, cy - 12):
            return (Tool.WIRE, x, cy - 12)

    # Vertical connectors at p1x from cy-12 to cy-6
    for y in range(cy - 11, cy - 6):
        if not has_tile(wm, p1x, y) and not has_tile(pm, p1x, y):
            return (Tool.WIRE, p1x, y)

    for x in X_RANGE:
        if not has_tile(rm_road, x, cy - 11):
            return (Tool.ROAD, x, cy - 11)

    for x in range(X_START + 1, X_END - 1, 3):
        if not has_tile(res_m, x, cy - 9) and not has_tile(pm, x, cy - 9):
            if has_tile(wm, x, cy - 12) or has_tile(rm_road, x, cy - 11):
                return (Tool.RESIDENTIAL, x, cy - 9)

    # Phase 8: Police/fire stations for coverage
    if not has_tile(plant_mask(obs.tile_map), cx, cy - 3):
        # place fire station near center of res zone
        pass

    return None

def act(obs, state):
    """
    Closed-loop policy: each step reads the current map and decides
    what to place next based on observed state.

    Strategy:
    1. Place coal power plant if none exists
    2. Extend wires from power plant toward zones
    3. Place roads adjacent to wired areas
    4. Place zones adjacent to roads
    5. React to what's already on the map
    """
    tm = obs.tile_map

    # Initialize light state
    if "phase" not in state:
        state["phase"] = 0
        state["cx"] = WORLD_W // 2
        state["cy"] = WORLD_H // 2

    cx, cy = state["cx"], state["cy"]

    emp = empty_mask(tm)
    wires = wire_mask(tm)
    roads = road_mask(tm)
    plants = plant_mask(tm)
    res = res_mask(tm)
    com = com_mask(tm)
    ind = ind_mask(tm)

    has_plant = plants.any()
    has_wire = wires.any()
    has_road = roads.any()

    # Helper: find empty neighbor of a boolean mask
    def empty_neighbors_of(mask):
        """Return (ys, xs) of empty tiles adjacent to mask=True tiles"""
        nbr = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        nbr[1:, :] |= mask[:-1, :]
        nbr[:-1, :] |= mask[1:, :]
        nbr[:, 1:] |= mask[:, :-1]
        nbr[:, :-1] |= mask[:, 1:]
        cand = emp & nbr
        return np.where(cand)

    def closest_to_center(ys, xs, tx, ty):
        """Pick index of (xs[i], ys[i]) closest to (tx, ty)"""
        dists = (xs - tx)**2 + (ys - ty)**2
        return int(np.argmin(dists))

    # Step 1: Ensure we have a coal power plant
    if not has_plant:
        # Place coal plant left of center
        px, py = cx - 5, cy
        px = max(2, min(px, WORLD_W - 3))
        py = max(2, min(py, WORLD_H - 3))
        return (Tool.COALPOWER, px, py)

    # Find plant location
    plant_ys, plant_xs = np.where(plants)
    plant_x = int(plant_xs[0])
    plant_y = int(plant_ys[0])

    # Step 2: Extend wire network from plant
    # We want a wire spine going right from plant to cx, then a vertical spine
    n_wires = int(wires.sum())
    n_roads = int(roads.sum())
    n_res = int(res.sum())
    n_com = int(com.sum())
    n_ind = int(ind.sum())
    n_zones = n_res + n_com + n_ind

    # Wire budget: build wires to cover the area
    # We need wires adjacent to zones for power
    # Strategy: extend wire toward center, then vertically

    if not has_wire:
        # Start wire adjacent to plant (to the right)
        wx = plant_x + 2  # 2 to avoid overwriting plant (3x3)
        wy = plant_y
        wx = max(0, min(wx, WORLD_W - 1))
        wy = max(0, min(wy, WORLD_H - 1))
        return (Tool.WIRE, wx, wy)

    # Check if we need more wires
    # Count wire extent
    wire_xs = np.where(wires)[1]
    wire_ys = np.where(wires)[0]
    wire_max_x = int(wire_xs.max()) if len(wire_xs) > 0 else plant_x
    wire_min_x = int(wire_xs.min()) if len(wire_xs) > 0 else plant_x
    wire_center_y = int(wire_ys.mean()) if len(wire_ys) > 0 else cy

    # Extend wire rightward to reach cx+1 (spine column)
    target_wire_x = cx  # vertical wire spine at cx

    if wire_max_x < target_wire_x:
        # Extend wire to the right along plant_y row
        return (Tool.WIRE, wire_max_x + 1, plant_y)

    # Extend vertical wire spine at cx
    wire_at_spine = wires[:, cx] if cx < WORLD_W else wires[:, WORLD_W-1]
    spine_ys = np.where(wire_at_spine)[0]

    if len(spine_ys) == 0:
        # Start spine at plant_y
        return (Tool.WIRE, cx, plant_y)

    spine_min_y = int(spine_ys.min())
    spine_max_y = int(spine_ys.max())

    # Extend spine vertically (both up and down) to cover zone range
    zone_range = 15  # cover +-15 rows from center

    if spine_min_y > cy - zone_range:
        ny = spine_min_y - 1
        if ny >= 0:
            return (Tool.WIRE, cx, ny)

    if spine_max_y < cy + zone_range:
        ny = spine_max_y + 1
        if ny < WORLD_H:
            return (Tool.WIRE, cx, ny)

    # Step 3: Build road spine parallel to wire (at cx+1)
    road_col = cx + 1
    road_at_col = roads[:, road_col] if road_col < WORLD_W else roads[:, WORLD_W-1]
    road_ys = np.where(road_at_col)[0]

    if len(road_ys) == 0:
        return (Tool.ROAD, road_col, cy)

    road_min_y = int(road_ys.min())
    road_max_y = int(road_ys.max())

    if road_min_y > cy - zone_range:
        ny = road_min_y - 1
        if ny >= 0:
            return (Tool.ROAD, road_col, ny)

    if road_max_y < cy + zone_range:
        ny = road_max_y + 1
        if ny < WORLD_H:
            return (Tool.ROAD, road_col, ny)

    # Step 4: Place horizontal roads to serve zones on both sides
    # Every 3 rows, place a short horizontal road connecting zones to the spine
    # Left side: roads at cx-1 row-level connectors
    # Right side: roads at cx+2

    # Find rows where we have road spine coverage
    road_spine_ys = np.where(road_at_col)[0]

    # Place horizontal connectors and zones
    # Check each candidate row (every 3 rows)
    for dy_offset in range(-zone_range, zone_range + 1, 3):
        row_y = cy + dy_offset
        if row_y < 3 or row_y >= WORLD_H - 3:
            continue

        # Left zone center at cx-3, right at cx+4
        # Left connector: road at cx-1, cx-2 at row_y
        for lx in [cx - 1, cx - 2]:
            if 0 <= lx < WORLD_W and emp[row_y, lx]:
                return (Tool.ROAD, lx, row_y)

        # Right connector: road at cx+2, cx+3 at row_y  
        for rx in [cx + 2, cx + 3]:
            if 0 <= rx < WORLD_W and emp[row_y, rx]:
                return (Tool.ROAD, rx, row_y)

        # Left residential zone (center at cx-3, needs road neighbor)
        lzx, lzy = cx - 3, row_y
        if 2 <= lzx <= WORLD_W - 3 and 2 <= lzy <= WORLD_H - 3:
            # Check if this spot is clear (3x3 area mostly empty)
            area = tm[lzy-1:lzy+2, lzx-1:lzx+2]
            if emp[lzy, lzx] and (area == 0).sum() >= 5:
                # Determine what to place based on ratio
                if n_com * 4 < n_res:
                    return (Tool.COMMERCIAL, lzx, lzy)
                elif n_ind * 4 < n_res:
                    return (Tool.INDUSTRIAL, lzx, lzy)
                else:
                    return (Tool.RESIDENTIAL, lzx, lzy)

        # Right zone (center at cx+4)
        rzx, rzy = cx + 4, row_y
        if 2 <= rzx <= WORLD_W - 3 and 2 <= rzy <= WORLD_H - 3:
            area = tm[rzy-1:rzy+2, rzx-1:rzx+2]
            if emp[rzy, rzx] and (area == 0).sum() >= 5:
                if n_com * 4 < n_res:
                    return (Tool.COMMERCIAL, rzx, rzy)
                elif n_ind * 4 < n_res:
                    return (Tool.INDUSTRIAL, rzx, rzy)
                else:
                    return (Tool.RESIDENTIAL, rzx, rzy)

    # Step 5: If zones exist but few powered, extend wire to reach them
    if n_zones > 0 and obs.powered_zones < n_zones:
        # Find unpowered zones by looking at zone tiles not near wires
        # Extend wires toward zones
        zone_mask_all = res | com | ind
        ys_z, xs_z = np.where(zone_mask_all)
        if len(xs_z) > 0:
            # Find zone farthest from wire
            for i in range(len(xs_z)):
                zx, zy = int(xs_z[i]), int(ys_z[i])
                # Check if wire nearby
                wy0, wy1 = max(0, zy-2), min(WORLD_H, zy+3)
                wx0, wx1 = max(0, zx-2), min(WORLD_W, zx+3)
                if not wires[wy0:wy1, wx0:wx1].any():
                    # Place wire adjacent to this zone
                    for ddx, ddy in [(0,-1),(0,1),(-1,0),(1,0)]:
                        nx, ny = zx + ddx, zy + ddy
                        if 0 <= nx < WORLD_W and 0 <= ny < WORLD_H and emp[ny, nx]:
                            return (Tool.WIRE, nx, ny)

    # Step 6: Expand outward - more zones further from center
    # Find empty tiles adjacent to roads and place zones there
    ys_r, xs_r = empty_neighbors_of(roads)
    if len(xs_r) > 0:
        # Pick one that's 3 away from road (zone center)
        idx = int(obs.step) % len(xs_r)
        zx, zy = int(xs_r[idx]), int(ys_r[idx])
        if 2 <= zx <= WORLD_W - 3 and 2 <= zy <= WORLD_H - 3:
            if n_com * 4 < n_res:
                return (Tool.COMMERCIAL, zx, zy)
            elif n_ind * 4 < n_res:
                return (Tool.INDUSTRIAL, zx, zy)
            else:
                return (Tool.RESIDENTIAL, zx, zy)

    # Step 7: Add more road connectivity
    ys_rd, xs_rd = empty_neighbors_of(roads)
    if len(xs_rd) > 0:
        idx = int(obs.step) % len(xs_rd)
        return (Tool.ROAD, int(xs_rd[idx]), int(ys_rd[idx]))

    return None

def act(obs, state):
    """
    Redesigned city builder with a different layout:
    - Uses a vertical wire spine instead of horizontal
    - Builds roads horizontally branching from the spine
    - Places zones in a grid pattern on both sides of the spine
    - Earlier second power plant
    - Better zone mix enforcement
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    # Use state as a simple step counter / plan tracker
    if 'phase' not in state:
        state['phase'] = 0
        state['plant2_placed'] = False

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Anchor: plant at left-center
    CX, CY = 20, 50

    has_plant = np.any(pm)
    if not has_plant:
        return (Tool.COALPOWER, CX, CY)

    plant_ys, plant_xs = np.where(pm)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    wire_ys, wire_xs = np.where(wm)
    road_ys, road_xs = np.where(rm)
    res_ys, res_xs = np.where(resm)
    com_ys, com_xs = np.where(comm)
    ind_ys, ind_xs = np.where(indm)

    wire_set = set(zip(wire_ys.tolist(), wire_xs.tolist()))
    road_set = set(zip(road_ys.tolist(), road_xs.tolist()))
    zone_set = set(zip(
        np.concatenate([res_ys, com_ys, ind_ys]).tolist(),
        np.concatenate([res_xs, com_xs, ind_xs]).tolist()
    ))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        c = com_count / t
        i = ind_count / t
        # Want ~30% commercial, ~30% industrial, ~40% residential
        if c < 0.28:
            return Tool.COMMERCIAL
        if i < 0.28:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    # === VERTICAL wire spine from plant ===
    spine_x = px + 2  # just to the right of the plant
    spine_y_start = py - 20
    spine_y_end = py + 20

    # Build vertical wire spine
    for sy in range(max(2, spine_y_start), min(WORLD_H - 2, spine_y_end + 1)):
        if not (bool(wm[sy, spine_x]) or bool(pm[sy, spine_x])):
            if bool(em[sy, spine_x]):
                return (Tool.WIRE, spine_x, sy)

    # === Horizontal wire branches from spine every 6 rows ===
    branch_rows = list(range(spine_y_start + 2, spine_y_end - 1, 6))
    branch_length = 30  # extend wire rightward

    for brow in branch_rows:
        if not in_bounds(spine_x, brow):
            continue
        for dx in range(1, branch_length + 1):
            wx = spine_x + dx
            if not in_bounds(wx, brow):
                break
            if not (bool(wm[brow, wx]) or bool(pm[brow, wx])):
                if bool(em[brow, wx]):
                    return (Tool.WIRE, wx, brow)
                break

    # === Road rows: one row above and below each wire branch ===
    road_col_start = spine_x + 1
    road_col_end = spine_x + branch_length

    for brow in branch_rows:
        for road_row in [brow - 1, brow + 1]:
            if not in_bounds(road_col_start, road_row):
                continue
            if road_row < 2 or road_row >= WORLD_H - 2:
                continue
            # Find next missing road tile in this row
            existing_cols = sorted([c for (r, c) in road_set if r == road_row and road_col_start <= c <= road_col_end])
            next_col = road_col_start
            if existing_cols:
                # Find first gap
                for ec in range(road_col_start, road_col_end + 1):
                    if ec not in set(existing_cols):
                        next_col = ec
                        break
                else:
                    continue
            if next_col <= road_col_end and in_bounds(next_col, road_row):
                if not bool(pm[road_row, next_col]) and not bool(wm[road_row, next_col]):
                    return (Tool.ROAD, next_col, road_row)

    # === Also build vertical connector roads along spine_x col ===
    for sy in range(max(2, spine_y_start - 1), min(WORLD_H - 2, spine_y_end + 2)):
        rc = spine_x - 1  # road column just left of wire spine
        if in_bounds(rc, sy) and (sy, rc) not in road_set and not bool(pm[sy, rc]) and bool(em[sy, rc]):
            return (Tool.ROAD, rc, sy)

    # === Zone placement near roads ===
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        step_hash = int(obs.step * 17 + int(tm[50, 50]) * 11) % max(len(cxs), 1)
        for offset in range(min(len(cxs), 40)):
            k = (step_hash + offset * 11) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # === Second power plant when needed ===
    if (obs.city_pop > 100 or total_zones > 5) and not state['plant2_placed']:
        # Place second plant at the right end of the wire branches
        p2x = spine_x + branch_length + 3
        p2y = py
        nearby_plant = False
        for dy in range(-6, 7):
            for dx in range(-6, 7):
                ny, nx2 = p2y + dy, p2x + dx
                if in_bounds(nx2, ny) and bool(pm[ny, nx2]):
                    nearby_plant = True
        if not nearby_plant and in_bounds(p2x, p2y):
            state['plant2_placed'] = True
            return (Tool.COALPOWER, p2x, p2y)

    # === Services ===
    if obs.city_pop > 200:
        fx, fy = spine_x + 5, py - 10
        if in_bounds(fx, fy) and bool(em[fy, fx]):
            return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 300:
        fx2, fy2 = spine_x + 5, py + 10
        if in_bounds(fx2, fy2) and bool(em[fy2, fx2]):
            return (Tool.POLICESTATION, fx2, fy2)

    # === Last resort: extend road ===
    if len(road_xs) > 0:
        k = int(obs.step * 7) % len(road_xs)
        rx, ry = int(road_xs[k]), int(road_ys[k])
        for dx2, dy2 in [(1, 0), (0, 1), (-1, 0), (0, -1)]:
            nx2, ny2 = rx + dx2, ry + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    # Strategy: build a horizontal layout with road spine going east-west
    # Power plant at center-left, wire runs east along horizontal spine
    # Roads run parallel above and below the wire spine
    # RES zones above road, COM zones below road, IND zones at edges
    # This creates a different layout than parent's vertical spine

    cx, cy = WORLD_W // 2, WORLD_H // 2

    # Power plant at center
    plant_x, plant_y = cx - 10, cy

    # Wire spine runs horizontally at row cy
    # Road runs at cy-2 (above) and cy+2 (below)
    # Zones: RES at cy-5 (above road), COM at cy+5 (below road), IND at extremes

    SPINE_COLS = range(cx - 10, cx + 20)  # columns for wire spine

    pm = plant_mask(obs.tile_map)
    rm = road_mask(obs.tile_map)
    wm = wire_mask(obs.tile_map)
    res_m = res_mask(obs.tile_map)
    com_m = com_mask(obs.tile_map)
    ind_m = ind_mask(obs.tile_map)

    def has_tile(mask, x, y):
        if 0 <= y < WORLD_H and 0 <= x < WORLD_W:
            return bool(mask[y, x])
        return False

    # Phase 0: place coal power plant
    if not has_tile(pm, plant_x, plant_y):
        return (Tool.COALPOWER, plant_x, plant_y)

    # Phase 1: wire spine horizontally at cy from plant eastward
    for dx in SPINE_COLS:
        if not has_tile(wm, dx, cy) and not has_tile(pm, dx, cy):
            return (Tool.WIRE, dx, cy)

    # Phase 2: road above wire spine at cy-2
    for dx in SPINE_COLS:
        if not has_tile(rm, dx, cy - 2):
            return (Tool.ROAD, dx, cy - 2)

    # Phase 3: road below wire spine at cy+2
    for dx in SPINE_COLS:
        if not has_tile(rm, dx, cy + 2):
            return (Tool.ROAD, dx, cy + 2)

    # Phase 4: vertical wire connectors from spine to roads (every 3 cols)
    # Connect cy to cy-2 and cy to cy+2 at zone centers
    for dx in range(cx - 7, cx + 20, 3):
        if 0 <= dx < WORLD_W:
            # wire up to road above
            if not has_tile(wm, dx, cy - 1) and not has_tile(rm, dx, cy - 1):
                return (Tool.WIRE, dx, cy - 1)
            # wire down to road below
            if not has_tile(wm, dx, cy + 1) and not has_tile(rm, dx, cy + 1):
                return (Tool.WIRE, dx, cy + 1)

    # Phase 5: place RES zones above at cy-5 (road at cy-2 provides access)
    for dx in range(cx - 7, cx + 20, 3):
        if 0 <= dx < WORLD_W and 0 <= cy - 5 < WORLD_H:
            if not has_tile(res_m, dx, cy - 5) and not has_tile(pm, dx, cy - 5):
                if has_tile(wm, dx, cy - 1) or has_tile(wm, dx, cy):
                    return (Tool.RESIDENTIAL, dx, cy - 5)

    # Phase 6: place COM zones below at cy+5 (road at cy+2 provides access)
    for dx in range(cx - 7, cx + 20, 3):
        if 0 <= dx < WORLD_W and 0 <= cy + 5 < WORLD_H:
            if not has_tile(com_m, dx, cy + 5) and not has_tile(pm, dx, cy + 5):
                if has_tile(wm, dx, cy + 1) or has_tile(wm, dx, cy):
                    return (Tool.COMMERCIAL, dx, cy + 5)

    # Phase 7: place IND zones at far right, powered by wire
    # Wire vertically up/down at far right column
    ind_start_x = cx + 12
    for dx in range(ind_start_x, cx + 20, 3):
        if 0 <= dx < WORLD_W:
            # vertical wire from spine to ind row
            for dy in [cy - 8, cy + 8]:
                if 0 <= dy < WORLD_H:
                    # wire the gap from road to zone
                    mid_y = (cy + dy) // 2
                    for wy in range(min(cy, dy), max(cy, dy) + 1):
                        if not has_tile(wm, dx, wy) and not has_tile(rm, dx, wy) and not has_tile(pm, dx, wy):
                            return (Tool.WIRE, dx, wy)

    for dx in range(ind_start_x, cx + 20, 3):
        if 0 <= dx < WORLD_W:
            for dy in [cy - 8, cy + 8]:
                if 0 <= dy < WORLD_H:
                    if not has_tile(ind_m, dx, dy) and not has_tile(pm, dx, dy):
                        if has_tile(wm, dx, dy) or has_tile(wm, dx, cy):
                            return (Tool.INDUSTRIAL, dx, dy)

    # Phase 8: second power plant if population growing
    plant2_x, plant2_y = cx + 18, cy
    if obs.city_pop > 100 and not has_tile(pm, plant2_x, plant2_y):
        # wire to connect
        for wx in range(cx + 10, plant2_x):
            if not has_tile(wm, wx, cy) and not has_tile(pm, wx, cy):
                return (Tool.WIRE, wx, cy)
        return (Tool.COALPOWER, plant2_x, plant2_y)

    # Phase 9: more residential zones second row above (cy-8)
    for dx in range(cx - 7, cx + 15, 3):
        if 0 <= dx < WORLD_W and 0 <= cy - 8 < WORLD_H:
            # need road at cy-8+2 = cy-6
            if not has_tile(rm, dx, cy - 6):
                return (Tool.ROAD, dx, cy - 6)

    for dx in range(cx - 7, cx + 15, 3):
        if 0 <= dx < WORLD_W and 0 <= cy - 8 < WORLD_H:
            if not has_tile(wm, dx, cy - 3) and not has_tile(rm, dx, cy - 3):
                return (Tool.WIRE, dx, cy - 3)
            if not has_tile(res_m, dx, cy - 8):
                if has_tile(wm, dx, cy - 3):
                    return (Tool.RESIDENTIAL, dx, cy - 8)

    # Phase 10: police/fire stations for city services
    if not has_tile(obs.tile_map.__class__, cx, cy + 8):
        # check tile directly
        if obs.tile_map[cy + 8, cx] == 0:  # empty
            return (Tool.FIRESTATION, cx, cy + 8)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map each step and reacts to actual map state.
    Strategy:
    1. Place coal power plant
    2. Extend wire from plant rightward along spine
    3. Lay horizontal roads above/below spine
    4. Place zones adjacent to roads with wire access
    5. Expand reactively based on what's on the map
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    # Working area center
    CX, CY = 55, 50

    has_plant = np.any(pm)
    plant_rows, plant_cols = np.where(pm)
    wire_rows, wire_cols = np.where(wm)
    road_rows, road_cols = np.where(rm)
    res_rows, res_cols = np.where(resm)
    com_rows, com_cols = np.where(comm)
    ind_rows, ind_cols = np.where(indm)

    wire_set = set(zip(wire_rows.tolist(), wire_cols.tolist()))
    road_set = set(zip(road_rows.tolist(), road_cols.tolist()))
    zone_set = set(zip(
        np.where(resm | comm | indm)[0].tolist(),
        np.where(resm | comm | indm)[1].tolist()
    ))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Phase 1: Place power plant
    if not has_plant:
        px, py = CX - 15, CY
        return (Tool.COALPOWER, px, py)

    # Find plant anchor (centroid of plant tiles)
    pc0 = int(np.median(plant_cols)) if len(plant_cols) > 0 else CX - 15
    pr0 = int(np.median(plant_rows)) if len(plant_rows) > 0 else CY
    plant_right = pc0 + 2  # right edge of 3x3 plant

    spine_row = pr0  # wire spine along plant row

    # Phase 2: Extend wire rightward from plant along spine
    wire_target_col = min(CX + 40, WORLD_W - 3)

    # Find rightmost wire on spine row
    spine_wire_cols = [c for (r, c) in wire_set if r == spine_row]
    if spine_wire_cols:
        max_wire_col = max(spine_wire_cols)
    else:
        max_wire_col = plant_right

    if max_wire_col < wire_target_col:
        nc = max_wire_col + 1
        if 0 <= nc < WORLD_W and not pm[spine_row, nc]:
            return (Tool.WIRE, nc, spine_row)

    # Phase 3: Vertical wire branches every 6 cols from spine
    branch_step = 6
    branch_cols = list(range(plant_right + 3, wire_target_col + 1, branch_step))
    branch_extent_up = spine_row - 15
    branch_extent_dn = spine_row + 15

    for bc in branch_cols:
        if not (0 <= bc < WORLD_W):
            continue
        if (spine_row, bc) not in wire_set:
            continue
        # Extend upward
        for wr in range(spine_row - 1, max(branch_extent_up - 1, 2), -1):
            if (wr, bc) not in wire_set and not pm[wr, bc]:
                if em[wr, bc]:
                    return (Tool.WIRE, bc, wr)
                break
        # Extend downward
        for wr in range(spine_row + 1, min(branch_extent_dn + 1, WORLD_H - 2)):
            if (wr, bc) not in wire_set and not pm[wr, bc]:
                if em[wr, bc]:
                    return (Tool.WIRE, bc, wr)
                break

    # Phase 4: Horizontal roads above and below spine
    road_row_above = spine_row - 4
    road_row_below = spine_row + 4
    road_col_start = plant_right + 2
    road_col_end = wire_target_col + 2

    for rrow in [road_row_above, road_row_below]:
        if not (2 <= rrow < WORLD_H - 2):
            continue
        road_here = sorted([c for (r, c) in road_set if r == rrow])
        max_rc = max(road_here) if road_here else road_col_start - 1
        if max_rc < road_col_end:
            nc = max_rc + 1
            if 0 <= nc < WORLD_W and not pm[rrow, nc] and not wm[rrow, nc]:
                return (Tool.ROAD, nc, rrow)

    # Phase 5: Vertical connector roads every 6 cols
    for vc in range(road_col_start, road_col_end + 1, 6):
        if not (0 <= vc < WORLD_W):
            continue
        for vr in range(road_row_above, road_row_below + 1):
            if not (0 <= vr < WORLD_H):
                continue
            if (vr, vc) not in road_set and not pm[vr, vc]:
                return (Tool.ROAD, vc, vr)

    # Helper functions
    def has_road_nearby(zy, zx, r=3):
        for dr in range(-r, r+1):
            for dc in range(-r, r+1):
                rr, rc = zy+dr, zx+dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if (rr, rc) in road_set:
                        return True
        return False

    def has_power_nearby(zy, zx, r=5):
        for dr in range(-r, r+1):
            for dc in range(-r, r+1):
                rr, rc = zy+dr, zx+dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if (rr, rc) in wire_set or pm[rr, rc]:
                        return True
        return False

    def zone_footprint_ok(zy, zx):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zy+dr, zx+dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if pm[rr, rc]:
                    return False
                if wm[rr, rc]:
                    return False
                if rm[rr, rc]:
                    return False
        return True

    def zone_overlaps_existing(zy, zx):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if (zy+dr, zx+dc) in zone_set:
                    return True
        return False

    def pick_tool():
        t = max(total_zones, 1)
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Phase 6: Place zones adjacent to roads
    # Zone rows: just outside the road rows (zone center 2 away from road)
    zone_rows_above = [road_row_above - 2, road_row_above - 5, road_row_above - 8]
    zone_rows_below = [road_row_below + 2, road_row_below + 5, road_row_below + 8]
    zone_col_centers = list(range(road_col_start + 2, road_col_end, 6))

    for zr in zone_rows_above + zone_rows_below:
        for zc in zone_col_centers:
            if not (2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3):
                continue
            if zone_overlaps_existing(zr, zc):
                continue
            if not zone_footprint_ok(zr, zc):
                continue
            if has_road_nearby(zr, zc, 4) and has_power_nearby(zr, zc, 6):
                return (pick_tool(), zc, zr)

    # Phase 7: If zones lack power, wire toward them
    all_zones = list(zone_set)
    for (zyr, zxc) in all_zones[:30]:
        if not has_power_nearby(zyr, zxc, r=4):
            if wire_set:
                closest_w = min(wire_set, key=lambda p: abs(p[0]-zyr)+abs(p[1]-zxc))
                wr, wc = closest_w
                nr = wr + (1 if zyr > wr else (-1 if zyr < wr else 0))
                nc = wc + (1 if zxc > wc else (-1 if zxc < wc else 0))
                if 0 <= nr < WORLD_H and 0 <= nc < WORLD_W and em[nr, nc]:
                    return (Tool.WIRE, nc, nr)

    # Phase 8: Second power plant if population growing
    if obs.city_pop > 150 and len(plant_cols) < 9:  # 9 tiles = 1 plant
        px2, py2 = CX + 30, CY
        if 0 <= py2 < WORLD_H and 0 <= px2 < WORLD_W and em[py2, px2]:
            return (Tool.COALPOWER, px2, py2)

    # Phase 9: More zone rows if there's space
    extra_rows = [road_row_above - 11, road_row_above - 14, road_row_below + 11, road_row_below + 14]
    for zr in extra_rows:
        for zc in zone_col_centers:
            if not (2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3):
                continue
            if zone_overlaps_existing(zr, zc):
                continue
            if not zone_footprint_ok(zr, zc):
                continue
            if has_road_nearby(zr, zc, 5) and has_power_nearby(zr, zc, 8):
                return (pick_tool(), zc, zr)

    # Phase 10: More horizontal roads extending coverage
    road_col_extended = road_col_end + 12
    for rrow in [road_row_above, road_row_below]:
        if not (2 <= rrow < WORLD_H - 2):
            continue
        road_here = sorted([c for (r, c) in road_set if r == rrow])
        max_rc = max(road_here) if road_here else road_col_end
        if max_rc < road_col_extended:
            nc = max_rc + 1
            if 0 <= nc < WORLD_W and not pm[rrow, nc]:
                return (Tool.ROAD, nc, rrow)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map every step and reacts to current state.
    Strategy:
    - Place coal plant near center-left
    - Grow wire spine horizontally from plant, then vertical branches
    - Grow road grid adjacent to wire coverage
    - Place zones where road+wire access confirmed from actual tile_map
    - Add second plant if population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    CX, CY = 60, 50
    PLANT_X, PLANT_Y = CX - 12, CY

    # Precompute positions from masks
    has_plant = np.any(pm)
    wire_pos = set(zip(*(np.where(wm)))) if np.any(wm) else set()
    road_pos = set(zip(*(np.where(rm)))) if np.any(rm) else set()
    zone_mask = resm | comm | indm
    zone_pos = set(zip(*(np.where(zone_mask)))) if np.any(zone_mask) else set()

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def is_empty_or_wire(x, y):
        return in_bounds(x, y) and (em[y, x] or wm[y, x]) and not pm[y, x]

    # Phase 1: Place coal power plant
    if not has_plant:
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    # Find plant center from mask
    plant_rows, plant_cols = np.where(pm)
    pr = int(np.mean(plant_rows))
    pc = int(np.mean(plant_cols))

    spine_row = pr  # horizontal wire spine row = plant row
    plant_right = pc + 2  # right edge of plant

    # Phase 2: Extend wire spine rightward from plant to CX+38
    wire_target_col = min(CX + 38, WORLD_W - 3)
    spine_wires = sorted([c for (r, c) in wire_pos if r == spine_row])
    max_wire_col = max(spine_wires) if spine_wires else plant_right

    if max_wire_col < wire_target_col:
        nc = max_wire_col + 1
        if in_bounds(nc, spine_row) and not pm[spine_row, nc]:
            return (Tool.WIRE, nc, spine_row)

    # Phase 3: Vertical wire branches every 4 cols along spine
    branch_start = plant_right + 2
    branch_end = wire_target_col
    branch_cols = list(range(branch_start, branch_end + 1, 4))
    vert_reach = 12  # how far up/down branches extend

    for bc in branch_cols:
        if not in_bounds(bc, spine_row):
            continue
        if (spine_row, bc) not in wire_pos:
            continue
        # Extend up
        for wr in range(spine_row - 1, max(spine_row - vert_reach - 1, 2), -1):
            if not in_bounds(bc, wr):
                break
            if (wr, bc) in wire_pos:
                continue
            if pm[wr, bc]:
                break
            if em[wr, bc]:
                return (Tool.WIRE, bc, wr)
            break
        # Extend down
        for wr in range(spine_row + 1, min(spine_row + vert_reach + 1, WORLD_H - 2)):
            if not in_bounds(bc, wr):
                break
            if (wr, bc) in wire_pos:
                continue
            if pm[wr, bc]:
                break
            if em[wr, bc]:
                return (Tool.WIRE, bc, wr)
            break

    # Phase 4: Road grid
    road_col_start = plant_right + 3
    road_col_end = min(wire_target_col + 2, WORLD_W - 3)
    road_row_above = spine_row - 4
    road_row_below = spine_row + 4

    # Horizontal roads above and below spine
    for rrow in [road_row_above, road_row_below]:
        if not (0 <= rrow < WORLD_H):
            continue
        row_roads = sorted([c for (r, c) in road_pos if r == rrow])
        max_rc = max(row_roads) if row_roads else road_col_start - 1
        if max_rc < road_col_end:
            nc = max_rc + 1
            if in_bounds(nc, rrow) and not pm[rrow, nc]:
                return (Tool.ROAD, nc, rrow)

    # Vertical connector roads every 4 cols
    for vc in range(road_col_start, road_col_end + 1, 4):
        for vr in range(road_row_above, road_row_below + 1):
            if in_bounds(vc, vr) and (vr, vc) not in road_pos and not pm[vr, vc]:
                return (Tool.ROAD, vc, vr)

    # Phase 5: Place zones where road AND wire confirmed from tile_map
    zone_row_offsets = [-2, -5, -8, 2, 5, 8]
    zone_rows = [road_row_above + off if off < 0 else road_row_below + off
                 for off in zone_row_offsets]
    zone_cols = list(range(road_col_start + 2, road_col_end, 4))

    def has_road_near(zy, zx, r=4):
        for dr in range(-r, r+1):
            for dc in range(-r, r+1):
                rr, rc = zy+dr, zx+dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if (rr, rc) in road_pos:
                        return True
        return False

    def has_wire_near(zy, zx, r=5):
        for dr in range(-r, r+1):
            for dc in range(-r, r+1):
                rr, rc = zy+dr, zx+dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if (rr, rc) in wire_pos or pm[rr, rc]:
                        return True
        return False

    def zone_clear(zy, zx):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zy+dr, zx+dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if pm[rr, rc]:
                    return False
                if not em[rr, rc] and (rr, rc) not in zone_pos:
                    return False
        return True

    def no_zone_overlap(zy, zx):
        for (zr, zc) in zone_pos:
            if abs(zy - zr) < 3 and abs(zx - zc) < 3:
                return False
        return True

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones + 1
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    for zr in zone_rows:
        for zc in zone_cols:
            if not (2 <= zr <= WORLD_H-3 and 2 <= zc <= WORLD_W-3):
                continue
            if no_zone_overlap(zr, zc) and zone_clear(zr, zc):
                if has_road_near(zr, zc) and has_wire_near(zr, zc):
                    return (pick_tool(), zc, zr)

    # Phase 6: Wire zones that lack power - find closest wire and step toward zone
    for (zyr, zxc) in list(zone_pos)[:30]:
        if not has_wire_near(zyr, zxc, r=4):
            if wire_pos:
                closest = min(wire_pos, key=lambda p: abs(p[0]-zyr)+abs(p[1]-zxc))
                wr, wc = closest
                dr = (1 if zyr > wr else -1 if zyr < wr else 0)
                dc = (1 if zxc > wc else -1 if zxc < wc else 0)
                nr, nc = wr+dr, wc+dc
                if in_bounds(nc, nr) and em[nr, nc] and not pm[nr, nc]:
                    return (Tool.WIRE, nc, nr)

    # Phase 7: Second coal plant if city growing
    if obs.city_pop > 100 and np.sum(pm) < 9:
        px2, py2 = CX + 20, CY
        if in_bounds(px2, py2) and em[py2, px2]:
            # Wire from current max to new plant
            for wx in range(max_wire_col + 1, px2 - 1):
                if in_bounds(wx, spine_row) and em[spine_row, wx]:
                    return (Tool.WIRE, wx, spine_row)
            return (Tool.COALPOWER, px2, py2)

    # Phase 8: Extra zone rows further out
    extra_rows = [road_row_above - 11, road_row_below + 11]
    for zr in extra_rows:
        for zc in zone_cols:
            if not (2 <= zr <= WORLD_H-3 and 2 <= zc <= WORLD_W-3):
                continue
            if no_zone_overlap(zr, zc) and zone_clear(zr, zc):
                if has_road_near(zr, zc, r=5) and has_wire_near(zr, zc, r=7):
                    return (pick_tool(), zc, zr)

    # Fill missing road segments
    for vc in range(road_col_start, road_col_end + 1, 4):
        for rrow in [road_row_above, road_row_below]:
            if in_bounds(vc, rrow) and (rrow, vc) not in road_pos and not pm[rrow, vc]:
                return (Tool.ROAD, vc, rrow)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map every step and reacts to current state.
    Strategy:
    - Place coal power plant near center-left.
    - Grow wire spine horizontally then vertically from plant.
    - Build road column parallel to wire spine.
    - Place zones (res/com/ind) adjacent to roads with wire coverage.
    - Dynamically extend infrastructure as population grows.
    """
    tm = obs.tile_map
    step = obs.step

    # Build center of operations slightly left of center
    cx, cy = WORLD_W // 2 - 5, WORLD_H // 2

    # Mask queries
    has_plant = np.any(plant_mask(tm))
    wm = wire_mask(tm)
    rm = road_mask(tm)
    em = empty_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    res_count = int(np.sum(res_m))
    com_count = int(np.sum(com_m))
    ind_count = int(np.sum(ind_m))

    # Phase 1: Place coal power plant if missing
    if not has_plant:
        # Plant center at cx, cy; 3x3 footprint
        return (Tool.COALPOWER, cx, cy)

    # Get positions of existing infrastructure
    wire_positions = set(zip(*np.where(wm))) if np.any(wm) else set()  # (row, col)
    road_positions = set(zip(*np.where(rm))) if np.any(rm) else set()  # (row, col)
    plant_positions = set(zip(*np.where(plant_mask(tm)))) if has_plant else set()
    res_positions = set(zip(*np.where(res_m))) if res_count > 0 else set()

    # Find power plant bounding box to avoid placing wire on it
    def is_plant_tile(r, c):
        return (r, c) in plant_positions

    # Wire spine: vertical column at cx+2 (just right of plant footprint)
    # Plant footprint: cx-1 to cx+1 columns, cy-1 to cy+1 rows
    wire_col = cx + 2
    road_col = cx + 4  # road at cx+4

    # Find wire extent in wire_col
    wire_col_rows = sorted([r for (r, c) in wire_positions if c == wire_col])

    # Phase 2: Build initial wire connection from plant to wire spine
    # Plant right edge is cx+1, so wire at cx+2 is adjacent
    if not wire_col_rows:
        # Place first wire at wire_col, cy
        if em[cy, wire_col]:
            return (Tool.WIRE, wire_col, cy)
        else:
            # Try nearby
            for dc in range(1, 5):
                if 0 <= wire_col + dc < WORLD_W and em[cy, wire_col + dc]:
                    return (Tool.WIRE, wire_col + dc, cy)

    # Phase 3: Extend wire spine vertically
    if wire_col_rows:
        min_row = min(wire_col_rows)
        max_row = max(wire_col_rows)
        # Target extent based on population
        extent = min(15 + obs.city_pop // 30, 20)
        target_min = cy - extent
        target_max = cy + extent

        # Extend downward
        if max_row < target_max and max_row + 1 < WORLD_H:
            nr, nc = max_row + 1, wire_col
            if not is_plant_tile(nr, nc) and (em[nr, nc] or wm[nr, nc]):
                return (Tool.WIRE, nc, nr)

        # Extend upward
        if min_row > target_min and min_row - 1 >= 0:
            nr, nc = min_row - 1, wire_col
            if not is_plant_tile(nr, nc) and (em[nr, nc] or wm[nr, nc]):
                return (Tool.WIRE, nc, nr)

    # Phase 4: Build road column at road_col, covering same rows as wire
    if wire_col_rows:
        wire_row_set = set(wire_col_rows)
        road_col_rows = set(r for (r, c) in road_positions if c == road_col)

        for r in sorted(wire_col_rows):
            if r not in road_col_rows:
                if 0 <= r < WORLD_H and 0 <= road_col < WORLD_W:
                    if em[r, road_col]:
                        return (Tool.ROAD, road_col, r)

    # Phase 5: Connect wire to road with horizontal connectors every 2 rows
    if wire_col_rows:
        for r in sorted(wire_col_rows):
            # Connect wire_col to road_col with wire/road at intermediate cols
            for c in range(wire_col + 1, road_col):
                if 0 <= c < WORLD_W and 0 <= r < WORLD_H:
                    if em[r, c]:
                        # Use wire for connection (power reaches road)
                        return (Tool.WIRE, c, r)

    # Phase 6: Place zones
    # Left zones: center at cx-3, spaced 3 rows apart (left of plant area)
    # Right zones: center at cx+7, spaced 3 rows apart (right of road)
    left_zone_col = cx - 4
    right_zone_col = cx + 7

    def zone_area_clear(zr, zc):
        """Check if 3x3 zone area is all empty."""
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def near_existing_zone(zr, zc):
        """Check if a zone already exists nearby."""
        for pr, pc in res_positions:
            if abs(zr - pr) <= 2 and abs(zc - pc) <= 2:
                return True
        return False

    def has_wire_nearby(zr, zc):
        """Check if wire is within 2 tiles."""
        for dr in range(-2, 3):
            for dc in range(-2, 3):
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if wm[rr, rc]:
                        return True
        return False

    def has_road_nearby(zr, zc):
        """Check if road is within 2 tiles."""
        for dr in range(-2, 3):
            for dc in range(-2, 3):
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if rm[rr, rc]:
                        return True
        return False

    if wire_col_rows:
        extent = min(15 + obs.city_pop // 30, 20)
        zone_rows = list(range(cy - extent + 1, cy + extent, 3))

        for zr in zone_rows:
            for zc in [right_zone_col, left_zone_col]:
                if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                    if has_wire_nearby(zr, zc) and has_road_nearby(zr, zc):
                        if not near_existing_zone(zr, zc) and zone_area_clear(zr, zc):
                            # Decide zone type based on ratios
                            if com_count < res_count // 3:
                                return (Tool.COMMERCIAL, zc, zr)
                            elif ind_count < res_count // 3:
                                return (Tool.INDUSTRIAL, zc, zr)
                            else:
                                return (Tool.RESIDENTIAL, zc, zr)

    # Phase 7: Add lateral wire branches to reach left zone column
    if wire_col_rows:
        for r in sorted(wire_col_rows):
            # Wire from wire_col leftward toward left_zone_col
            for c in range(wire_col - 1, left_zone_col - 2, -1):
                if 0 <= c < WORLD_W and 0 <= r < WORLD_H:
                    if em[r, c] and not is_plant_tile(r, c):
                        return (Tool.WIRE, c, r)

    # Phase 8: Add roads to serve left zones
    left_road_col = left_zone_col + 2
    if wire_col_rows:
        for r in sorted(wire_col_rows):
            if 0 <= r < WORLD_H and 0 <= left_road_col < WORLD_W:
                if em[r, left_road_col]:
                    return (Tool.ROAD, left_road_col, r)

    # Phase 9: If population is growing, add more zones further out
    if obs.city_pop > 300:
        far_right_col = cx + 11
        for zr in range(cy - 18, cy + 19, 3):
            if 0 <= zr < WORLD_H and 0 <= far_right_col < WORLD_W:
                if has_wire_nearby(zr, far_right_col) and has_road_nearby(zr, far_right_col):
                    if not near_existing_zone(zr, far_right_col) and zone_area_clear(zr, far_right_col):
                        return (Tool.RESIDENTIAL, far_right_col, zr)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder.
    Key improvements over parent:
    - Fix wire/road building to actually make progress (parent got stuck after one wire row)
    - Build wires first to cover area, then roads, then zones
    - Use a simpler state machine with phase tracking
    - Ensure road rows are at spine_y-2 and spine_y+2 but with correct column tracking
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    # Anchor
    CX, CY = 30, 50

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def is_free(x, y):
        return in_bounds(x, y) and bool(em[y, x])

    def has_infra(y, x):
        return bool(wm[y, x]) or bool(pm[y, x]) or bool(rm[y, x])

    # Step 1: Place coal power plant
    if not np.any(pm):
        return (Tool.COALPOWER, CX, CY)

    # Find plant center
    plant_ys, plant_xs = np.where(pm)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    wire_ys, wire_xs = np.where(wm)
    road_ys, road_xs = np.where(rm)
    res_ys, res_xs = np.where(resm)
    com_ys, com_xs = np.where(comm)
    ind_ys, ind_xs = np.where(indm)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    zone_set = set(zip(
        np.concatenate([res_ys, com_ys, ind_ys]).tolist(),
        np.concatenate([res_xs, com_xs, ind_xs]).tolist()
    ))

    def pick_tool():
        t = max(total_zones, 1)
        r = res_count / t
        c = com_count / t
        i = ind_count / t
        if c < 0.20:
            return Tool.COMMERCIAL
        if i < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    # ---- Build wire spine horizontally from plant ----
    # Wire spine at row py, from px+2 to px+50
    spine_y = py
    wire_end_x = min(px + 55, WORLD_W - 4)

    # Extend horizontal wire spine
    for wx in range(px + 2, wire_end_x + 1):
        wy = spine_y
        if not in_bounds(wx, wy):
            break
        if not bool(wm[wy, wx]) and not bool(pm[wy, wx]):
            if bool(em[wy, wx]):
                return (Tool.WIRE, wx, wy)
            # If blocked (maybe road or zone), try to skip
            break

    # Vertical wire branches every 6 cols from spine
    branch_cols = list(range(px + 6, wire_end_x + 1, 6))
    for bx in branch_cols:
        if not in_bounds(bx, spine_y):
            continue
        if not (bool(wm[spine_y, bx]) or bool(pm[spine_y, bx])):
            continue  # spine not wired here yet
        for sign in [-1, 1]:
            for dy in range(1, 8):
                wy, wx = spine_y + sign * dy, bx
                if not in_bounds(wx, wy):
                    break
                if bool(wm[wy, wx]) or bool(pm[wy, wx]):
                    continue
                if bool(em[wy, wx]):
                    return (Tool.WIRE, wx, wy)
                break  # blocked

    # ---- Build road rows parallel to wire spine ----
    road_top = spine_y - 2
    road_bot = spine_y + 2
    road_start = px + 2
    road_end = min(px + 54, WORLD_W - 4)

    # Build top road row incrementally
    for rx in range(road_start, road_end + 1):
        ry = road_top
        if not in_bounds(rx, ry):
            break
        if not bool(rm[ry, rx]) and not bool(pm[ry, rx]) and not bool(wm[ry, rx]):
            if bool(em[ry, rx]):
                return (Tool.ROAD, rx, ry)
            break

    # Build bottom road row incrementally
    for rx in range(road_start, road_end + 1):
        ry = road_bot
        if not in_bounds(rx, ry):
            break
        if not bool(rm[ry, rx]) and not bool(pm[ry, rx]) and not bool(wm[ry, rx]):
            if bool(em[ry, rx]):
                return (Tool.ROAD, rx, ry)
            break

    # Vertical connector roads every 4 cols between road_top and road_bot
    for vc in range(road_start, road_end + 1, 4):
        for vr in range(road_top, road_bot + 1):
            if not in_bounds(vc, vr):
                continue
            if not bool(rm[vr, vc]) and not bool(pm[vr, vc]) and not bool(wm[vr, vc]):
                if bool(em[vr, vc]):
                    return (Tool.ROAD, vc, vr)

    # ---- Zone placement near roads and wires ----
    # Build neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Candidate zone centers: empty tile with road + wire nearby, interior
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Deterministic but reactive scan
        step_hash = int(obs.step * 17 + int(obs.city_pop * 3)) % max(len(cxs), 1)
        for offset in range(min(len(cxs), 40)):
            k = (step_hash + offset * 11) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # ---- Second power plant when many zones ----
    if total_zones > 10 or obs.city_pop > 300:
        p2x = min(px + 50, WORLD_W - 5)
        p2y = py
        nearby_plant = False
        for dy in range(-6, 7):
            for dx in range(-6, 7):
                ny, nx2 = p2y + dy, p2x + dx
                if in_bounds(nx2, ny) and bool(pm[ny, nx2]):
                    nearby_plant = True
        if not nearby_plant and in_bounds(p2x, p2y) and bool(em[p2y, p2x]):
            return (Tool.COALPOWER, p2x, p2y)

    # ---- Services ----
    if obs.city_pop > 100:
        fx, fy = px + 5, py - 8
        if in_bounds(fx, fy) and bool(em[fy, fx]):
            return (Tool.FIRESTATION, fx, fy)
        fx2, fy2 = px + 5, py + 8
        if in_bounds(fx2, fy2) and bool(em[fy2, fx2]):
            return (Tool.POLICESTATION, fx2, fy2)

    # ---- Extend roads outward from existing road frontier ----
    if len(road_xs) > 0:
        step_k = int(obs.step * 13) % max(len(road_xs), 1)
        rx_s, ry_s = int(road_xs[step_k]), int(road_ys[step_k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx_s + dx2, ry_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # ---- Extend wires from existing wire frontier ----
    wire_set = set(zip(wire_ys.tolist(), wire_xs.tolist()))
    if wire_set:
        step_k2 = int(obs.step * 7) % max(len(wire_xs), 1)
        wx_s, wy_s = int(wire_xs[step_k2]), int(wire_ys[step_k2])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = wx_s + dx2, wy_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Redesigned city builder with:
    - Two separate neighborhoods (left and right clusters)
    - Proper wire connectivity from plant to both clusters
    - Road grid within each cluster
    - Mixed zones (RES/COM/IND balanced)
    - Uses state to track build phase
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Initialize state
    if 'phase' not in state:
        state['phase'] = 0
        state['plan'] = []
        state['plan_idx'] = 0

    # Build a fixed plan of actions on first call
    if not state['plan']:
        plan = []

        # Power plant at (20, 30)
        PX, PY = 20, 30
        plan.append((Tool.COALPOWER, PX, PY))

        # Second power plant at (80, 30)
        P2X, P2Y = 80, 30

        # Wire from plant rightward along y=30
        for x in range(PX + 3, P2X - 2):
            plan.append((Tool.WIRE, x, PY))

        # Second plant
        plan.append((Tool.COALPOWER, P2X, P2Y))

        # Wire from second plant to edges
        for x in range(P2X + 3, min(P2X + 20, WORLD_W - 2)):
            plan.append((Tool.WIRE, x, PY))

        # Wire branches downward for cluster 1 (centered around x=20, y=50)
        C1X, C1Y = 20, 50
        for y in range(PY + 1, C1Y + 8):
            plan.append((Tool.WIRE, PX, y))

        # Wire branches for cluster 2 (centered around x=80, y=50)
        C2X, C2Y = 80, 50
        for y in range(PY + 1, C2Y + 8):
            plan.append((Tool.WIRE, P2X, y))

        # Also wire horizontal branches at cluster level
        for x in range(PX - 8, PX + 12):
            if in_bounds(x, C1Y):
                plan.append((Tool.WIRE, x, C1Y))
        for x in range(P2X - 8, P2X + 12):
            if in_bounds(x, C2Y):
                plan.append((Tool.WIRE, x, C2Y))

        # Road grid for cluster 1
        # Two horizontal roads
        for x in range(C1X - 8, C1X + 10):
            if in_bounds(x, C1Y - 4):
                plan.append((Tool.ROAD, x, C1Y - 4))
            if in_bounds(x, C1Y + 4):
                plan.append((Tool.ROAD, x, C1Y + 4))
        # Vertical connectors every 3 cols
        for x in range(C1X - 8, C1X + 10, 3):
            for y in range(C1Y - 4, C1Y + 5):
                if in_bounds(x, y):
                    plan.append((Tool.ROAD, x, y))

        # Road grid for cluster 2
        for x in range(C2X - 8, C2X + 10):
            if in_bounds(x, C2Y - 4):
                plan.append((Tool.ROAD, x, C2Y - 4))
            if in_bounds(x, C2Y + 4):
                plan.append((Tool.ROAD, x, C2Y + 4))
        for x in range(C2X - 8, C2X + 10, 3):
            for y in range(C2Y - 4, C2Y + 5):
                if in_bounds(x, y):
                    plan.append((Tool.ROAD, x, y))

        # Zones for cluster 1: place in a grid pattern around C1X, C1Y
        zone_counts = [0, 0, 0]  # RES, COM, IND
        zone_tools = [Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.INDUSTRIAL]
        z_idx = 0
        for zy in [C1Y - 7, C1Y, C1Y + 7]:
            for zx in [C1X - 6, C1X - 3, C1X, C1X + 3, C1X + 6]:
                if in_bounds(zx, zy) and in_bounds(zx - 1, zy - 1) and in_bounds(zx + 1, zy + 1):
                    tool = zone_tools[z_idx % 3]
                    zone_counts[z_idx % 3] += 1
                    plan.append((tool, zx, zy))
                    z_idx += 1

        # Zones for cluster 2
        for zy in [C2Y - 7, C2Y, C2Y + 7]:
            for zx in [C2X - 6, C2X - 3, C2X, C2X + 3, C2X + 6]:
                if in_bounds(zx, zy) and in_bounds(zx - 1, zy - 1) and in_bounds(zx + 1, zy + 1):
                    tool = zone_tools[z_idx % 3]
                    plan.append((tool, zx, zy))
                    z_idx += 1

        # Fire station and police station for each cluster
        plan.append((Tool.FIRESTATION, C1X + 9, C1Y))
        plan.append((Tool.POLICESTATION, C1X - 9, C1Y))
        plan.append((Tool.FIRESTATION, C2X + 9, C2Y))
        plan.append((Tool.POLICESTATION, C2X - 9, C2Y))

        # Additional zones - third cluster at bottom
        C3X, C3Y = 50, 70
        for y in range(PY, C3Y + 5):
            plan.append((Tool.WIRE, 50, y))
        for x in range(C3X - 8, C3X + 10):
            plan.append((Tool.ROAD, x, C3Y - 4))
            plan.append((Tool.ROAD, x, C3Y + 4))
        for x in range(C3X - 8, C3X + 10, 3):
            for y in range(C3Y - 4, C3Y + 5):
                plan.append((Tool.ROAD, x, y))
        for x in range(C3X - 10, C3X + 12):
            plan.append((Tool.WIRE, x, C3Y))
        for zy in [C3Y - 7, C3Y, C3Y + 7]:
            for zx in [C3X - 6, C3X - 3, C3X, C3X + 3, C3X + 6]:
                if in_bounds(zx, zy) and in_bounds(zx - 1, zy - 1) and in_bounds(zx + 1, zy + 1):
                    tool = zone_tools[z_idx % 3]
                    plan.append((tool, zx, zy))
                    z_idx += 1

        state['plan'] = plan
        state['plan_idx'] = 0

    # Execute plan step by step
    idx = state['plan_idx']
    plan = state['plan']

    if idx < len(plan):
        action = plan[idx]
        state['plan_idx'] += 1
        tool, x, y = action
        # Skip if not in bounds
        if not in_bounds(x, y):
            return None
        # Skip placing wire/road on plant
        if bool(pm[y, x]) and tool in (Tool.WIRE, Tool.ROAD):
            return None
        return action

    # After plan done: reactive zone filling near existing roads
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        r = res_count / total_zones
        c = com_count / total_zones
        i = ind_count / total_zones
        if c < 0.25:
            return Tool.COMMERCIAL
        if i < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    zone_set = set(zip(
        np.where(resm | comm | indm)[0].tolist(),
        np.where(resm | comm | indm)[1].tolist()
    ))

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    # Neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        step_hash = int(obs.step * 17) % max(len(cxs), 1)
        for offset in range(min(len(cxs), 40)):
            k = (step_hash + offset * 11) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    return None

def act(obs, state):
    tm = obs.tile_map
    cx, cy = WORLD_W // 2, WORLD_H // 2

    # Phase 0: Place coal power plant if no plant exists
    pm = plant_mask(tm)
    if not pm.any():
        return (Tool.COALPOWER, cx, cy)

    # Find power plant location
    py_arr, px_arr = np.where(pm)
    px, py = int(px_arr[0]), int(py_arr[0])

    wm = wire_mask(tm)
    rm = road_mask(tm)
    res = res_mask(tm)
    com = com_mask(tm)
    ind = ind_mask(tm)
    emp = empty_mask(tm)
    any_zone = res | com | ind

    # Helper: neighbors of a mask
    def dilate(mask):
        d = np.zeros_like(mask)
        d[1:, :] |= mask[:-1, :]
        d[:-1, :] |= mask[1:, :]
        d[:, 1:] |= mask[:, :-1]
        d[:, :-1] |= mask[:, 1:]
        return d

    # Power grid = plant + wires adjacent to plant or other wires
    powered_grid = pm | wm

    # We want to extend wire from power grid toward zones
    # Road grid
    road_grid = rm

    # Step 1: If there are zones not adjacent to road, extend road toward them
    zone_needs_road = any_zone & ~dilate(road_grid)
    if zone_needs_road.any():
        # Extend road from existing road toward nearest zone needing road
        road_frontier = emp & dilate(road_grid)
        if road_frontier.any():
            fy, fx = np.where(road_frontier)
            # Find zone needing road
            zy, zx = np.where(zone_needs_road)
            # Pick road frontier tile closest to a zone needing road
            best = None; best_d = 1e9
            # Sample to keep fast
            for i in range(min(len(fy), 20)):
                for j in range(min(len(zy), 10)):
                    d = abs(int(fy[i])-int(zy[j])) + abs(int(fx[i])-int(zx[j]))
                    if d < best_d:
                        best_d = d; best = (int(fx[i]), int(fy[i]))
            if best:
                return (Tool.ROAD, best[0], best[1])

    # Step 2: If zones not powered (no wire adjacent), extend wire toward them
    zone_needs_power = any_zone & ~dilate(powered_grid)
    if zone_needs_power.any():
        wire_frontier = emp & dilate(powered_grid)
        if wire_frontier.any():
            fy, fx = np.where(wire_frontier)
            zy, zx = np.where(zone_needs_power)
            best = None; best_d = 1e9
            for i in range(min(len(fy), 20)):
                for j in range(min(len(zy), 10)):
                    d = abs(int(fy[i])-int(zy[j])) + abs(int(fx[i])-int(zx[j]))
                    if d < best_d:
                        best_d = d; best = (int(fx[i]), int(fy[i]))
            if best:
                return (Tool.WIRE, best[0], best[1])

    # Step 3: Place a new zone adjacent to existing road AND wire coverage
    # Prefer tiles adjacent to road and within 3 tiles of wire
    road_adj = dilate(road_grid)
    wire_adj = dilate(powered_grid)

    # Good zone locations: empty, adjacent to road, adjacent to wire
    good = emp & road_adj & wire_adj
    # Avoid placing on road/wire tiles themselves
    good = good & ~rm & ~wm & ~pm

    if good.any():
        gy, gx = np.where(good)
        # Use tile_map sum mod count for deterministic but reactive choice
        k = int(tm.sum() % 65537) % len(gx)
        # Alternate R/C/I based on current populations
        rp, cp, ip = obs.res_pop, obs.com_pop, obs.ind_pop
        if ip <= cp and ip <= rp:
            tool = Tool.INDUSTRIAL
        elif cp <= rp:
            tool = Tool.COMMERCIAL
        else:
            tool = Tool.RESIDENTIAL
        return (tool, int(gx[k]), int(gy[k]))

    # Step 4: Extend road from road frontier (no zone nearby yet)
    road_frontier = emp & dilate(road_grid) & ~wm & ~pm
    if road_frontier.any():
        ry, rx = np.where(road_frontier)
        # Prefer extending outward from center
        k = int(tm.sum() % 65537) % len(rx)
        return (Tool.ROAD, int(rx[k]), int(ry[k]))

    # Step 5: Bootstrap - lay initial road + wire cross from plant
    # Road to the right of plant
    for dx in range(1, 15):
        nx = px + dx
        if 0 <= nx < WORLD_W:
            tile_val = tm[py, nx]
            # Check if empty
            if emp[py, nx]:
                return (Tool.ROAD, nx, py)

    # Wire upward from plant
    for dy in range(1, 15):
        ny = py - dy
        if 0 <= ny < WORLD_H and emp[ny, px]:
            return (Tool.WIRE, px, ny)

    # Wire downward
    for dy in range(1, 15):
        ny = py + dy
        if 0 <= ny < WORLD_H and emp[ny, px]:
            return (Tool.WIRE, px, ny)

    # Fallback: place residential near center if anything empty
    emp_y, emp_x = np.where(emp)
    if len(emp_x) > 0:
        k = int(tm.sum() % 65537) % len(emp_x)
        return (Tool.RESIDENTIAL, int(emp_x[k]), int(emp_y[k]))

    return None

def act(obs, state):
    """
    Closed-loop policy: reads the map each step and reacts to current state.
    Strategy:
    - Place coal power plant near center-left if none exists.
    - Grow wire spine vertically from the plant.
    - Grow road column adjacent to wire.
    - Place zones adjacent to road+wire coverage, alternating types.
    - Connect wire laterally to reach left-side zones.
    - Extend road laterally to reach right-side zones.
    - Add second road column further right for more zones.
    """
    tm = obs.tile_map
    step = obs.step

    cx, cy = WORLD_W // 2, WORLD_H // 2

    has_plant = np.any(plant_mask(tm))
    has_wire = np.any(wire_mask(tm))
    has_road = np.any(road_mask(tm))
    res_count = np.sum(res_mask(tm))
    com_count = np.sum(com_mask(tm))
    ind_count = np.sum(ind_mask(tm))

    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    # Phase 1: Place coal power plant
    if not has_plant:
        # Plant center at (cx-4, cy), footprint cx-6..cx-2, cy-1..cy+1
        return (Tool.COALPOWER, cx - 4, cy)

    wire_positions = list(zip(*np.where(wm)))   # (row, col)
    road_positions = list(zip(*np.where(rm)))
    res_positions = list(zip(*np.where(res_mask(tm))))
    com_positions = list(zip(*np.where(com_mask(tm))))
    ind_positions = list(zip(*np.where(ind_mask(tm))))

    # Wire spine column
    wire_col = cx - 1
    wire_col_rows = sorted([r for (r, c) in wire_positions if c == wire_col])

    # Phase 2: Initialize wire adjacent to plant
    if not wire_col_rows:
        # Plant footprint: cx-6..cx-2, cy-1..cy+1. Place wire at cx-1, cy
        return (Tool.WIRE, wire_col, cy)

    # Phase 3: Extend wire spine vertically
    min_row = min(wire_col_rows)
    max_row = max(wire_col_rows)
    target_min = cy - 14
    target_max = cy + 14

    if max_row < target_max and max_row + 1 < WORLD_H:
        nr, nc = max_row + 1, wire_col
        if em[nr, nc] or wm[nr, nc]:
            return (Tool.WIRE, nc, nr)
    if min_row > target_min and min_row - 1 >= 0:
        nr, nc = min_row - 1, wire_col
        if em[nr, nc] or wm[nr, nc]:
            return (Tool.WIRE, nc, nr)

    # Phase 4: Build primary road column adjacent to wire (cx)
    road_col1 = cx
    road_col1_rows = sorted([r for (r, c) in road_positions if c == road_col1])

    for r in wire_col_rows:
        if 0 <= r < WORLD_H and not rm[r, road_col1]:
            if em[r, road_col1]:
                return (Tool.ROAD, road_col1, r)

    # Phase 5: Place zones - left of wire and right of road
    # Left zone column center: cx-4 (adjacent to plant / wire left side)
    # Right zone column center: cx+3
    # Second right zone column: cx+7

    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def near_wire(zr):
        return any(abs(zr - wr) <= 2 for (wr, wc) in wire_positions)

    def near_road(zr):
        return any(abs(zr - rr) <= 2 for (rr, rc) in road_positions)

    def already_zone(zr, zc, zone_list):
        return any(abs(zr - pr) <= 1 and abs(zc - pc) <= 1 for (pr, pc) in zone_list)

    all_zone_pos = res_positions + com_positions + ind_positions

    # Build candidate zone centers
    zone_rows = list(range(cy - 12, cy + 13, 3))
    # Left: cx-4, Right1: cx+3, Right2: cx+7
    left_col = cx - 4
    right_col1 = cx + 3
    right_col2 = cx + 7

    candidates = []
    for zr in zone_rows:
        for zc in [left_col, right_col1, right_col2]:
            candidates.append((zr, zc))

    for (zr, zc) in candidates:
        if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
            if near_wire(zr) and near_road(zr):
                already = already_zone(zr, zc, all_zone_pos)
                if not already and zone_area_free(zr, zc):
                    # Determine zone type
                    total = res_count + com_count + ind_count
                    if com_count < total // 5 + 1:
                        zt = Tool.COMMERCIAL
                    elif ind_count < total // 5 + 1:
                        zt = Tool.INDUSTRIAL
                    else:
                        zt = Tool.RESIDENTIAL
                    return (zt, zc, zr)

    # Phase 6: Extend wire laterally to reach left zones
    for wr in wire_col_rows:
        for wc in [cx - 2, cx - 3]:
            if 0 <= wc < WORLD_W and em[wr, wc]:
                return (Tool.WIRE, wc, wr)

    # Phase 7: Extend road laterally to reach right zones
    for rr in wire_col_rows:
        for rc in [cx + 1, cx + 2]:
            if 0 <= rc < WORLD_W and em[rr, rc]:
                return (Tool.ROAD, rc, rr)

    # Phase 8: Second road column for right2 zones
    road_col2 = cx + 5
    for r in wire_col_rows:
        if 0 <= r < WORLD_H and not rm[r, road_col2]:
            if em[r, road_col2]:
                return (Tool.ROAD, road_col2, r)

    # Phase 9: Expand wire/road range further if population growing
    if obs.city_pop > 150:
        new_target_min = cy - 20
        new_target_max = cy + 20
        if wire_col_rows:
            min_row = min(wire_col_rows)
            max_row = max(wire_col_rows)
            if max_row < new_target_max and max_row + 1 < WORLD_H:
                nr, nc = max_row + 1, wire_col
                if em[nr, nc] or wm[nr, nc]:
                    return (Tool.WIRE, nc, nr)
            if min_row > new_target_min and min_row - 1 >= 0:
                nr, nc = min_row - 1, wire_col
                if em[nr, nc] or wm[nr, nc]:
                    return (Tool.WIRE, nc, nr)

    # Phase 10: Fill in more zones in expanded range
    if obs.city_pop > 200:
        extra_rows = list(range(cy - 18, cy + 19, 3))
        for zr in extra_rows:
            for zc in [left_col, right_col1, right_col2]:
                if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                    if near_wire(zr) and near_road(zr):
                        already = already_zone(zr, zc, all_zone_pos)
                        if not already and zone_area_free(zr, zc):
                            return (Tool.RESIDENTIAL, zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Each step reads the current tile_map and decides what to place next
    - Strategy: coal plant -> wire spine -> road grid -> zones
    - All decisions based on current map state, not precomputed plan
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    # City anchor - slightly left of center to give room to expand right
    CX, CY = 55, 50

    # Analyze current map
    has_plant = np.any(pm)

    # --- Phase 1: Place coal power plant ---
    if not has_plant:
        return (Tool.COALPOWER, CX - 15, CY)

    # Find plant center (look for plant tiles, pick centroid col)
    plant_rows, plant_cols = np.where(pm)
    pc = int(np.mean(plant_cols))
    pr = int(np.mean(plant_rows))
    # Plant right edge
    plant_right = int(np.max(plant_cols)) + 1

    # Wire and road sets for fast lookup
    wire_set = set(zip(map(int, *np.where(wm)[:1]), map(int, *np.where(wm)[1:]))) if np.any(wm) else set()
    # Rebuild properly
    if np.any(wm):
        wr_arr, wc_arr = np.where(wm)
        wire_set = set(zip(wr_arr.tolist(), wc_arr.tolist()))
    else:
        wire_set = set()

    if np.any(rm):
        rr_arr, rc_arr = np.where(rm)
        road_set = set(zip(rr_arr.tolist(), rc_arr.tolist()))
    else:
        road_set = set()

    # Zone positions
    zone_mask = resm | comm | indm
    if np.any(zone_mask):
        zr_arr, zc_arr = np.where(zone_mask)
        zone_set = set(zip(zr_arr.tolist(), zc_arr.tolist()))
    else:
        zone_set = set()

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Layout parameters
    spine_row = pr  # wire spine along plant row
    wire_end_col = min(CX + 40, WORLD_W - 3)
    road_row_above = spine_row - 4
    road_row_below = spine_row + 4
    road_col_start = plant_right + 2
    road_col_end = min(wire_end_col + 2, WORLD_W - 3)

    # --- Phase 2: Extend wire spine rightward from plant ---
    # Find rightmost wire on spine row
    spine_wire_cols = [c for (r, c) in wire_set if r == spine_row]
    if spine_wire_cols:
        max_spine_wire = max(spine_wire_cols)
    else:
        max_spine_wire = plant_right - 1

    if max_spine_wire < wire_end_col:
        nc = max_spine_wire + 1
        if 0 <= nc < WORLD_W and not pm[spine_row, nc]:
            return (Tool.WIRE, nc, spine_row)

    # --- Phase 3: Vertical wire branches every 5 cols ---
    branch_step = 5
    vert_reach = 8  # how far up/down to extend wire branches
    for bc in range(road_col_start, wire_end_col + 1, branch_step):
        if bc >= WORLD_W:
            continue
        if (spine_row, bc) not in wire_set:
            continue
        # Extend up from spine
        for wr in range(spine_row - 1, max(spine_row - vert_reach - 1, 2), -1):
            if (wr, bc) in wire_set:
                break
            if not pm[wr, bc] and (em[wr, bc] or wm[wr, bc]):
                return (Tool.WIRE, bc, wr)
            break
        # Extend down from spine
        for wr in range(spine_row + 1, min(spine_row + vert_reach + 1, WORLD_H - 2)):
            if (wr, bc) in wire_set:
                break
            if not pm[wr, bc] and (em[wr, bc] or wm[wr, bc]):
                return (Tool.WIRE, bc, wr)
            break

    # --- Phase 4: Build horizontal roads above and below spine ---
    for rrow in [road_row_above, road_row_below]:
        if not (2 <= rrow < WORLD_H - 2):
            continue
        road_here = sorted([c for (r, c) in road_set if r == rrow])
        if road_here:
            max_rc = max(road_here)
        else:
            max_rc = road_col_start - 1
        if max_rc < road_col_end:
            nc = max_rc + 1
            if 0 <= nc < WORLD_W and not pm[rrow, nc]:
                return (Tool.ROAD, nc, rrow)

    # --- Phase 5: Vertical connector roads every 5 cols ---
    for vc in range(road_col_start, road_col_end + 1, branch_step):
        if not (0 <= vc < WORLD_W):
            continue
        for vr in range(road_row_above, road_row_below + 1):
            if not (0 <= vr < WORLD_H):
                continue
            if (vr, vc) not in road_set and not pm[vr, vc]:
                return (Tool.ROAD, vc, vr)

    # Helper: check road access within radius
    def has_road_access(zy, zx, r=3):
        r1, r2 = max(0, zy - r), min(WORLD_H, zy + r + 1)
        c1, c2 = max(0, zx - r), min(WORLD_W, zx + r + 1)
        return bool(np.any(rm[r1:r2, c1:c2]))

    # Helper: check wire/power access within radius
    def has_power_access(zy, zx, r=5):
        r1, r2 = max(0, zy - r), min(WORLD_H, zy + r + 1)
        c1, c2 = max(0, zx - r), min(WORLD_W, zx + r + 1)
        return bool(np.any(wm[r1:r2, c1:c2])) or bool(np.any(pm[r1:r2, c1:c2]))

    # Helper: check zone footprint is placeable (auto-bulldoze handles most)
    def zone_ok(zy, zx):
        if zy < 2 or zy >= WORLD_H - 2 or zx < 2 or zx >= WORLD_W - 2:
            return False
        # Don't place on plant or roads
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zy + dr, zx + dc
                if pm[rr, rc] or rm[rr, rc] or wm[rr, rc]:
                    return False
        return True

    # Helper: zone already nearby
    def zone_nearby(zy, zx):
        for dr in range(-3, 4):
            for dc in range(-3, 4):
                if (zy + dr, zx + dc) in zone_set:
                    return True
        return False

    # Pick zone type based on balance
    def pick_tool():
        t = max(total_zones, 1)
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # --- Phase 6: Place zones between roads ---
    # Zone rows: rows adjacent to roads (road ± 2 = zone center)
    zone_row_options = []
    for base_row in [road_row_above, road_row_below]:
        if base_row == road_row_above:
            # zones above the top road
            for offset in [2, 5, 8]:
                zone_row_options.append(base_row - offset)
        else:
            # zones below the bottom road
            for offset in [2, 5, 8]:
                zone_row_options.append(base_row + offset)

    zone_col_options = list(range(road_col_start + 2, road_col_end, branch_step))

    for zr in zone_row_options:
        for zc in zone_col_options:
            if zone_ok(zr, zc) and not zone_nearby(zr, zc):
                if has_road_access(zr, zc, r=4) and has_power_access(zr, zc, r=6):
                    return (pick_tool(), zc, zr)

    # --- Phase 7: Add second power plant if population growing ---
    if obs.city_pop > 300 and np.sum(pm) < 10:
        px2, py2 = CX + 30, CY
        if all(em[py2 + dr, px2 + dc] for dr in [-1,0,1] for dc in [-1,0,1]
               if 0 <= py2+dr < WORLD_H and 0 <= px2+dc < WORLD_W):
            return (Tool.COALPOWER, px2, py2)

    # --- Phase 8: Reactive wire fill - connect unpowered zones ---
    for (zyr, zxc) in list(zone_set)[:15]:
        if not has_power_access(zyr, zxc, r=4):
            # Find nearest wire and step toward zone
            if wire_set:
                closest = min(wire_set, key=lambda p: abs(p[0]-zyr) + abs(p[1]-zxc))
                wr, wc = closest
                # Move one step toward zone
                dr = (1 if zyr > wr else -1 if zyr < wr else 0)
                dc = (1 if zxc > wc else -1 if zxc < wc else 0)
                nr, nc = wr + dr, wc + dc
                if 0 <= nr < WORLD_H and 0 <= nc < WORLD_W:
                    if em[nr, nc] and not pm[nr, nc]:
                        return (Tool.WIRE, nc, nr)

    # --- Phase 9: Extend road coverage further right if zones are filling ---
    if total_zones > 10:
        extended_end = min(road_col_end + 15, WORLD_W - 3)
        for rrow in [road_row_above, road_row_below]:
            if not (2 <= rrow < WORLD_H - 2):
                continue
            road_here = sorted([c for (r, c) in road_set if r == rrow])
            if road_here:
                max_rc = max(road_here)
                if max_rc < extended_end:
                    nc = max_rc + 1
                    if 0 <= nc < WORLD_W and not pm[rrow, nc]:
                        return (Tool.ROAD, nc, rrow)

    # --- Phase 10: Fill extra zone rows if we have lots of steps left ---
    remaining = obs.n_steps - obs.step
    if remaining > 50:
        extra_rows = [road_row_above - 11, road_row_below + 11]
        for zr in extra_rows:
            for zc in zone_col_options:
                if zone_ok(zr, zc) and not zone_nearby(zr, zc):
                    if has_road_access(zr, zc, r=5) and has_power_access(zr, zc, r=8):
                        return (pick_tool(), zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder.
    Key changes from parent:
    - Scan actual wire/road frontier each step from tile_map directly
    - Place wires by BFS from plant, then roads adjacent to wires, then zones near roads
    - More compact vertical layout to ensure connectivity
    - Power plant + immediate wire neighbors before anything else
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # ---- Phase 0: Place first coal plant ----
    has_plant = np.any(pm)
    if not has_plant:
        # Place near left-center
        return (Tool.COALPOWER, 20, 50)

    # Find plant center
    plant_ys, plant_xs = np.where(pm)
    # Use first plant cluster
    px = int(np.median(plant_xs))
    py = int(np.median(plant_ys))

    wire_ys, wire_xs = np.where(wm)
    road_ys, road_xs = np.where(rm)
    res_ys, res_xs = np.where(resm)
    com_ys, com_xs = np.where(comm)
    ind_ys, ind_xs = np.where(indm)

    wire_set = set(zip(wire_ys.tolist(), wire_xs.tolist()))
    road_set = set(zip(road_ys.tolist(), road_xs.tolist()))
    zone_ys = np.concatenate([res_ys, com_ys, ind_ys])
    zone_xs = np.concatenate([res_xs, com_xs, ind_xs])
    zone_set = set(zip(zone_ys.tolist(), zone_xs.tolist()))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        r = res_count / t
        c = com_count / t
        i = ind_count / t
        if c < 0.20:
            return Tool.COMMERCIAL
        if i < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    # ---- Phase 1: Extend wires from plant/wire frontier ----
    # Build a combined powered set (plant tiles + wires)
    powered_set = wire_set | set(zip(plant_ys.tolist(), plant_xs.tolist()))

    # BFS-like: find tiles adjacent to powered_set that are empty -> place wire
    # Use a deterministic scan order: prioritize right, then down, then up
    # to build a horizontal spine + vertical branches
    dirs = [(0, 1), (1, 0), (-1, 0), (0, -1)]

    # Target: build wire spine rightward from plant, to x=80
    # Then branch every 6 cols up/down to y=40 and y=60
    spine_y = py
    spine_target_x = 80

    # First: ensure horizontal spine exists from plant to spine_target_x
    for wx in range(px + 2, spine_target_x + 1):
        if not in_bounds(wx, spine_y):
            break
        if not (bool(wm[spine_y, wx]) or bool(pm[spine_y, wx])):
            # Check if previous cell is powered
            if (spine_y, wx - 1) in powered_set or bool(pm[spine_y, wx - 1]):
                if bool(em[spine_y, wx]):
                    return (Tool.WIRE, wx, spine_y)
            break

    # Branch wires vertically every 6 cols
    branch_cols = list(range(px + 6, spine_target_x + 1, 6))
    for bx in branch_cols:
        if not in_bounds(bx, spine_y):
            continue
        if not ((spine_y, bx) in powered_set or bool(pm[spine_y, bx])):
            continue
        # Extend up
        for dy in range(1, 9):
            wy, wx2 = spine_y - dy, bx
            if not in_bounds(wx2, wy):
                break
            if not (bool(wm[wy, wx2]) or bool(pm[wy, wx2])):
                if (wy + 1, wx2) in powered_set or bool(pm[wy + 1, wx2]):
                    if bool(em[wy, wx2]):
                        return (Tool.WIRE, wx2, wy)
                break
        # Extend down
        for dy in range(1, 9):
            wy, wx2 = spine_y + dy, bx
            if not in_bounds(wx2, wy):
                break
            if not (bool(wm[wy, wx2]) or bool(pm[wy, wx2])):
                if (wy - 1, wx2) in powered_set or bool(pm[wy - 1, wx2]):
                    if bool(em[wy, wx2]):
                        return (Tool.WIRE, wx2, wy)
                break

    # ---- Phase 2: Build roads adjacent to/parallel to wire branches ----
    # Road rows: spine_y-2 and spine_y+2 (above and below wire spine)
    # Road columns: spine_y-1+/-branches
    # Actually: build roads at y = spine_y-2 and y = spine_y+2, from px+2 to spine_target_x
    road_rows = [spine_y - 2, spine_y + 2]
    for rrow in road_rows:
        if not in_bounds(0, rrow):
            continue
        for rx in range(px + 2, spine_target_x + 1):
            if not in_bounds(rx, rrow):
                break
            if (rrow, rx) not in road_set and not bool(pm[rrow, rx]):
                # Only build if previous col has road or we're at start
                if rx == px + 2 or (rrow, rx - 1) in road_set:
                    return (Tool.ROAD, rx, rrow)

    # Vertical connector roads between the two road rows, every 3 cols
    for vc in range(px + 2, spine_target_x + 1, 3):
        for vr in range(min(road_rows), max(road_rows) + 1):
            if not in_bounds(vc, vr):
                continue
            if (vr, vc) not in road_set and not bool(pm[vr, vc]):
                return (Tool.ROAD, vc, vr)

    # ---- Phase 3: Place zones near roads and wires ----
    # Build neighbor proximity masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, :2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Scan deterministically, prefer near road rows
        best = None
        best_score = 1e9
        step_offset = int(obs.step * 7) % max(len(cxs), 1)
        for offset in range(min(len(cxs), 40)):
            k = (step_offset + offset * 11) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                # Score: prefer near road rows
                score = min(abs(zy - road_rows[0]), abs(zy - road_rows[1]))
                if score < best_score:
                    best_score = score
                    best = (zx, zy)
        if best is not None:
            return (pick_tool(), best[0], best[1])

    # ---- Phase 4: Second power plant if many zones ----
    if total_zones > 10 or obs.city_pop > 300:
        p2x = min(px + 50, WORLD_W - 5)
        p2y = spine_y
        nearby = any(
            in_bounds(p2x + dx, p2y + dy) and bool(pm[p2y + dy, p2x + dx])
            for dy in range(-6, 7) for dx in range(-6, 7)
        )
        if not nearby and in_bounds(p2x, p2y) and bool(em[p2y, p2x]):
            return (Tool.COALPOWER, p2x, p2y)

    # ---- Phase 5: Services ----
    if obs.city_pop > 200:
        fx, fy = px + 5, spine_y - 10
        if in_bounds(fx, fy) and bool(em[fy, fx]):
            return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 400:
        fx, fy = px + 5, spine_y + 10
        if in_bounds(fx, fy) and bool(em[fy, fx]):
            return (Tool.POLICESTATION, fx, fy)

    # ---- Fallback: extend road from existing road frontier ----
    if len(road_xs) > 0:
        k = int(obs.step * 13) % len(road_xs)
        rx, ry = int(road_xs[k]), int(road_ys[k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx + dx2, ry + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop city builder: each step reads the map and reacts.
    - Places coal power plant if none exists
    - Extends wire spine from plant
    - Builds roads adjacent to wire
    - Places zones (R/C/I) where road and wire access exist
    - Adapts to what actually exists on the map
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2  # map center

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Phase 1: Place power plant if none exists ---
    if not np.any(pm):
        return (Tool.COALPOWER, cx - 4, cy)

    # Get plant centroid
    pys, pxs = np.where(pm)
    px = int(np.mean(pxs))
    py = int(np.mean(pys))

    # Build fast lookup sets
    wire_set = set(zip(*np.where(wm))) if np.any(wm) else set()
    road_set = set(zip(*np.where(rm))) if np.any(rm) else set()
    res_ys, res_xs = np.where(resm)
    com_ys, com_xs = np.where(comm)
    ind_ys, ind_xs = np.where(indm)
    zone_set = set(zip(
        np.concatenate([res_ys, com_ys, ind_ys]).tolist(),
        np.concatenate([res_xs, com_xs, ind_xs]).tolist()
    ))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Wire spine column: one col to the right of plant center
    spine_x = px + 2

    # --- Phase 2: Extend wire spine vertically ---
    # Wire spine at spine_x from cy-15 to cy+15
    for dy in range(-15, 16):
        wy, wx = py + dy, spine_x
        if not in_bounds(wx, wy):
            continue
        if (wy, wx) not in wire_set and not pm[wy, wx]:
            # Only place wire if adjacent to existing wire or plant
            adjacent_power = False
            for ddr, ddc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = wy+ddr, wx+ddc
                if in_bounds(nc, nr) and (pm[nr, nc] or (nr, nc) in wire_set):
                    adjacent_power = True
                    break
            if adjacent_power:
                return (Tool.WIRE, wx, wy)

    # Wire connection from plant to spine
    for dx in range(1, spine_x - px + 2):
        wx = px + dx
        wy = py
        if not in_bounds(wx, wy):
            break
        if (wy, wx) not in wire_set and not pm[wy, wx]:
            adjacent_power = False
            for ddr, ddc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = wy+ddr, wx+ddc
                if in_bounds(nc, nr) and (pm[nr, nc] or (nr, nc) in wire_set):
                    adjacent_power = True
                    break
            if adjacent_power:
                return (Tool.WIRE, wx, wy)

    # --- Phase 3: Road grid adjacent to wire spine ---
    road_left_x = spine_x - 1
    road_right_x = spine_x + 1

    for dy in range(-15, 16):
        for rx in [road_left_x, road_right_x]:
            ry = py + dy
            if not in_bounds(rx, ry):
                continue
            if (ry, rx) not in road_set and not pm[ry, rx]:
                # Only place road if adjacent to existing road or to spine
                adj_road = False
                for ddr, ddc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = ry+ddr, rx+ddc
                    if in_bounds(nc, nr) and ((nr, nc) in road_set or nc == spine_x):
                        adj_road = True
                        break
                if adj_road:
                    return (Tool.ROAD, rx, ry)

    # Horizontal road connectors every 3 rows
    for dy in range(-15, 16, 3):
        ry = py + dy
        if not in_bounds(road_left_x, ry):
            continue
        # extend road left from road_left_x
        for dx in range(1, 7):
            rx = road_left_x - dx
            if not in_bounds(rx, ry):
                break
            if (ry, rx) not in road_set and not pm[ry, rx]:
                adj_road = any((ry, rx+1) in road_set or (ry, rx-1) in road_set
                               or (ry-1, rx) in road_set or (ry+1, rx) in road_set
                               for _ in [1])
                if (ry, rx+1) in road_set or (ry+1, rx) in road_set or (ry-1, rx) in road_set:
                    return (Tool.ROAD, rx, ry)
        # extend road right
        for dx in range(1, 7):
            rx = road_right_x + dx
            if not in_bounds(rx, ry):
                break
            if (ry, rx) not in road_set and not pm[ry, rx]:
                if (ry, rx-1) in road_set or (ry+1, rx) in road_set or (ry-1, rx) in road_set:
                    return (Tool.ROAD, rx, ry)

    # --- Helpers for zone placement ---
    def has_road_near(zx, zy, r=3):
        for dr in range(-r, r+1):
            for dc in range(-r, r+1):
                if (zy+dr, zx+dc) in road_set:
                    return True
        return False

    def has_wire_near(zx, zy, r=5):
        for dr in range(-r, r+1):
            for dc in range(-r, r+1):
                nr, nc = zy+dr, zx+dc
                if (nr, nc) in wire_set:
                    return True
                if in_bounds(nc, nr) and pm[nr, nc]:
                    return True
        return False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy+dr, zx+dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    def pick_tool():
        t = max(total_zones, 1)
        if res_count / t < 0.5:
            return Tool.RESIDENTIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # --- Phase 4: Place zones in a reactive grid pattern ---
    # Zone columns: 3 left and 3 right of roads
    zone_col_offsets = [-4, -7, 4, 7]
    zone_row_offsets = list(range(-14, 15, 3))

    for dy in zone_row_offsets:
        zy = py + dy
        for dc in zone_col_offsets:
            zx = spine_x + dc
            if not (2 <= zy <= WORLD_H - 3 and 2 <= zx <= WORLD_W - 3):
                continue
            if zone_clear(zx, zy) and has_road_near(zx, zy) and has_wire_near(zx, zy):
                return (pick_tool(), zx, zy)

    # --- Phase 5: Dilated scan for any good zone spot ---
    # Compute road neighborhood (r=3) and wire neighborhood (r=5)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr = slice(max(0,-dy), min(WORLD_H, WORLD_H-dy))
            sc = slice(max(0,-dx), min(WORLD_W, WORLD_W-dx))
            dr = slice(max(0,dy), min(WORLD_H, WORLD_H+dy))
            dc_sl = slice(max(0,dx), min(WORLD_W, WORLD_W+dx))
            nbr_road[dr, dc_sl] |= rm[sr, sc]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr = slice(max(0,-dy), min(WORLD_H, WORLD_H-dy))
            sc = slice(max(0,-dx), min(WORLD_W, WORLD_W-dx))
            dr = slice(max(0,dy), min(WORLD_H, WORLD_H+dy))
            dc_sl = slice(max(0,dx), min(WORLD_W, WORLD_W+dx))
            nbr_wire[dr, dc_sl] |= wm[sr, sc]
            nbr_wire[dr, dc_sl] |= pm[sr, sc]

    cand = em & nbr_road & nbr_wire
    # Mask out edges
    cand[:2, :] = False; cand[-2:, :] = False
    cand[:, :2] = False; cand[:, -2:] = False
    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        k = int(obs.step * 13 + int(tm.sum()) % 97) % len(cxs)
        zx, zy = int(cxs[k]), int(cys[k])
        if zone_clear(zx, zy):
            return (pick_tool(), zx, zy)

    # --- Phase 6: Second power plant if growing ---
    if obs.city_pop > 400 and np.sum(pm) < 9:
        nx2, ny2 = px + 30, py
        if in_bounds(nx2, ny2) and em[ny2, nx2]:
            return (Tool.COALPOWER, nx2, ny2)

    # --- Phase 7: Services once we have population ---
    if obs.city_pop > 200:
        fx, fy = spine_x + 2, py - 12
        if in_bounds(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
        fx2, fy2 = spine_x + 2, py + 12
        if in_bounds(fx2, fy2) and em[fy2, fx2]:
            return (Tool.POLICESTATION, fx2, fy2)

    # --- Phase 8: Extend wire toward any unserved zone ---
    for (zyr, zxc) in list(zone_set)[:20]:
        if not has_wire_near(zxc, zyr, r=4):
            if wire_set:
                closest_w = min(wire_set, key=lambda p: abs(p[0]-zyr)+abs(p[1]-zxc))
                wr, wc = closest_w
                step_r = (1 if zyr > wr else -1 if zyr < wr else 0)
                step_c = (1 if zxc > wc else -1 if zxc < wc else 0)
                for nr, nc in [(wr+step_r, wc), (wr, wc+step_c)]:
                    if in_bounds(nc, nr) and em[nr, nc] and not pm[nr, nc]:
                        return (Tool.WIRE, nc, nr)

    # --- Phase 9: Extend road frontier ---
    rys, rxs = np.where(rm)
    if len(rxs) > 0:
        k = int(obs.step * 7) % len(rxs)
        rr, rc = int(rys[k]), int(rxs[k])
        for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx2, ny2 = rc+dx, rr+dy
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads the current map each step and decides
    the next placement based on what actually exists.

    Strategy:
    - Place a coal power plant first
    - Grow a wire network outward from the plant
    - Grow a road network adjacent to wires
    - Place zones (res/com/ind) adjacent to roads with wire coverage nearby
    - All decisions are based on current observed state
    """
    tm = obs.tile_map
    step = obs.step

    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    has_plant = np.any(pm)
    plant_cells = list(zip(*np.where(pm))) if has_plant else []
    wire_cells = list(zip(*np.where(wm)))
    road_cells = list(zip(*np.where(rm)))
    res_cells = list(zip(*np.where(resm)))
    com_cells = list(zip(*np.where(comm)))
    ind_cells = list(zip(*np.where(indm)))

    zone_cells = res_cells + com_cells + ind_cells
    res_count = len(res_cells)
    com_count = len(com_cells)
    ind_count = len(ind_cells)

    # --- Helper: check if 3x3 area centered at (cx, cy) is all empty ---
    def zone_area_free(cx, cy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, cc = cy + dr, cx + dc
                if rr < 0 or rr >= WORLD_H or cc < 0 or cc >= WORLD_W:
                    return False
                if not em[rr, cc]:
                    return False
        return True

    # --- Helper: is there wire coverage within radius r of (cx, cy)? ---
    def wire_near(cx, cy, r=4):
        for (wr, wc) in wire_cells:
            if abs(cy - wr) <= r and abs(cx - wc) <= r:
                return True
        return False

    # --- Helper: is there road within radius r of (cx, cy)? ---
    def road_near(cx, cy, r=3):
        for (rr, rc) in road_cells:
            if abs(cy - rr) <= r and abs(cx - rc) <= r:
                return True
        return False

    # --- Helper: pick zone type for balance ---
    def pick_zone():
        total = res_count + com_count + ind_count + 1
        if com_count / total < 0.25:
            return Tool.COMMERCIAL
        elif ind_count / total < 0.25:
            return Tool.INDUSTRIAL
        else:
            return Tool.RESIDENTIAL

    # Phase 1: Place power plant if none exists
    if not has_plant:
        # Plant center at (25, 50), footprint 23-27, 48-52
        return (Tool.COALPOWER, 25, 50)

    # Phase 2: Extend wire network from existing wire/plant cells
    # Find the frontier of wire: cells adjacent to wire that are empty
    # We want to grow wire rightward and in a structured way

    # Identify power source boundary: plant cells + wire cells
    power_cells = plant_cells + wire_cells

    # Target area: build wire along row 50 from plant rightward, then branches
    # and a second branch row at 50 going toward right cluster

    # Wire spine: row 50, from col 28 (right of plant at 25) to col 95
    SPINE_ROW = 50
    SPINE_START = 28  # just right of plant footprint
    SPINE_END = 95

    # Wire branch rows (vertical branches at intervals)
    BRANCH_COLS = list(range(30, 96, 8))  # cols 30,38,46,...
    BRANCH_UP = 35    # wire branch goes up to row 35
    BRANCH_DOWN = 65  # wire branch goes down to row 65

    # Road rows (parallel to spine)
    ROAD_ROW_UP = 40
    ROAD_ROW_DOWN = 60
    ROAD_START = 28
    ROAD_END = 95

    # Check spine wire coverage
    spine_wire_cols = sorted([wc for (wr, wc) in wire_cells if wr == SPINE_ROW and wc >= SPINE_START])
    if spine_wire_cols:
        max_spine_wc = max(spine_wire_cols)
    else:
        max_spine_wc = SPINE_START - 1

    # Extend spine wire if not complete
    if max_spine_wc < SPINE_END:
        nc = max_spine_wc + 1
        if 0 <= nc < WORLD_W and em[SPINE_ROW, nc]:
            return (Tool.WIRE, nc, SPINE_ROW)
        elif 0 <= nc < WORLD_W:
            # try bulldoze and rewire
            return (Tool.WIRE, nc, SPINE_ROW)

    # Phase 3: Grow vertical wire branches at each branch column
    for bc in BRANCH_COLS:
        # Check if spine wire exists at this col
        if not wm[SPINE_ROW, bc]:
            continue
        # Extend upward branch
        for wr in range(SPINE_ROW - 1, BRANCH_UP - 1, -1):
            if wm[wr, bc]:
                break
            if em[wr, bc]:
                return (Tool.WIRE, bc, wr)
            break
        # Extend downward branch
        for wr in range(SPINE_ROW + 1, BRANCH_DOWN + 1):
            if wm[wr, bc]:
                break
            if em[wr, bc]:
                return (Tool.WIRE, bc, wr)
            break

    # Phase 4: Build road along ROAD_ROW_UP from ROAD_START to ROAD_END
    road_up_cols = sorted([rc for (rr, rc) in road_cells if rr == ROAD_ROW_UP and rc >= ROAD_START])
    if road_up_cols:
        max_road_up = max(road_up_cols)
    else:
        max_road_up = ROAD_START - 1

    if max_road_up < ROAD_END:
        nc = max_road_up + 1
        if 0 <= nc < WORLD_W and 0 <= ROAD_ROW_UP < WORLD_H:
            return (Tool.ROAD, nc, ROAD_ROW_UP)

    # Phase 5: Build road along ROAD_ROW_DOWN
    road_dn_cols = sorted([rc for (rr, rc) in road_cells if rr == ROAD_ROW_DOWN and rc >= ROAD_START])
    if road_dn_cols:
        max_road_dn = max(road_dn_cols)
    else:
        max_road_dn = ROAD_START - 1

    if max_road_dn < ROAD_END:
        nc = max_road_dn + 1
        if 0 <= nc < WORLD_W and 0 <= ROAD_ROW_DOWN < WORLD_H:
            return (Tool.ROAD, nc, ROAD_ROW_DOWN)

    # Phase 6: Build vertical connector roads between up/down road rows at branch cols
    for bc in BRANCH_COLS:
        for rr in range(ROAD_ROW_UP, ROAD_ROW_DOWN + 1):
            if not rm[rr, bc] and not wm[rr, bc]:
                if 0 <= rr < WORLD_H and 0 <= bc < WORLD_W:
                    return (Tool.ROAD, bc, rr)

    # Phase 7: Place zones adjacent to roads with wire coverage nearby
    # Zone centers: 3 tiles above road_up row, 3 tiles below road_down row
    # and between the two road rows
    zone_target_rows = [
        ROAD_ROW_UP - 3, ROAD_ROW_UP - 6, ROAD_ROW_UP - 9,
        ROAD_ROW_DOWN + 3, ROAD_ROW_DOWN + 6, ROAD_ROW_DOWN + 9,
        SPINE_ROW  # between roads
    ]
    zone_target_cols = list(range(32, 94, 6))

    for zr in zone_target_rows:
        for zc in zone_target_cols:
            if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                # Already a zone near here?
                already = any(
                    abs(zr - pr) <= 2 and abs(zc - pc) <= 2
                    for (pr, pc) in zone_cells
                )
                if not already and zone_area_free(zc, zr):
                    if road_near(zc, zr, r=4) and wire_near(zc, zr, r=6):
                        return (pick_zone(), zc, zr)

    # Phase 8: Place second power plant if many zones exist and underpowered
    num_plants = len(plant_cells) // 9  # approximate (plant is 3x3)
    # More accurate: count plant tiles
    plant_tile_count = np.sum(pm)
    if plant_tile_count < 15 and len(zone_cells) > 20:
        # Place second plant
        if em[50, 95] and em[50, 94] and em[50, 96]:
            return (Tool.COALPOWER, 95, 50)

    # Phase 9: Wire up toward zones that lack power
    # Find zones without wire coverage
    for (zr, zc) in zone_cells:
        if not wire_near(zc, zr, r=5):
            # Find closest wire cell
            if wire_cells:
                dists = [(abs(zr - wr) + abs(zc - wc), wr, wc) for (wr, wc) in wire_cells]
                dists.sort()
                _, nearest_wr, nearest_wc = dists[0]
                # Step toward zone from nearest wire
                dr = zr - nearest_wr
                dc = zc - nearest_wc
                # Move one step
                if abs(dc) >= abs(dr):
                    step_c = nearest_wc + (1 if dc > 0 else -1)
                    step_r = nearest_wr
                else:
                    step_c = nearest_wc
                    step_r = nearest_wr + (1 if dr > 0 else -1)
                if 0 <= step_r < WORLD_H and 0 <= step_c < WORLD_W:
                    if em[step_r, step_c]:
                        return (Tool.WIRE, step_c, step_r)

    # Phase 10: Expand zone placement further from center if population growing
    if obs.city_pop > 50:
        extra_rows = [ROAD_ROW_UP - 12, ROAD_ROW_DOWN + 12]
        for zr in extra_rows:
            for zc in zone_target_cols:
                if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                    already = any(
                        abs(zr - pr) <= 2 and abs(zc - pc) <= 2
                        for (pr, pc) in zone_cells
                    )
                    if not already and zone_area_free(zc, zr):
                        if road_near(zc, zr, r=5):
                            return (pick_zone(), zc, zr)

    # Phase 11: Fill gaps in roads
    for bc in zone_target_cols:
        for rr in [ROAD_ROW_UP, ROAD_ROW_DOWN]:
            if 0 <= rr < WORLD_H and 0 <= bc < WORLD_W:
                if not rm[rr, bc] and em[rr, bc]:
                    return (Tool.ROAD, bc, rr)

    # Phase 12: Add more zones reactively if lots of road/wire coverage
    for zr in range(38, 63, 3):
        for zc in zone_target_cols:
            if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                already = any(
                    abs(zr - pr) <= 2 and abs(zc - pc) <= 2
                    for (pr, pc) in zone_cells
                )
                if not already and zone_area_free(zc, zr):
                    if road_near(zc, zr, r=3) and wire_near(zc, zr, r=5):
                        return (pick_zone(), zc, zr)

    return None

def act(obs, state):
    """
    Combined policy: horizontal wire spine + vertical road grid + zone clusters.

    Strategy:
    1. Place coal power plant at a fixed location
    2. Build horizontal wire spine from plant rightward
    3. Build vertical wire branches every 6 cols for power coverage
    4. Build two horizontal roads (above and below spine) for access
    5. Build vertical connector roads every 6 cols
    6. Place zones in a grid pattern between the roads
    7. Add lateral wires to reach zones
    8. Second power plant if population grows
    """
    tm = obs.tile_map

    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    # Layout constants - centered on map
    CX, CY = 60, 50

    # Power plant at left of center
    PLANT_X, PLANT_Y = CX - 20, CY

    # Wire spine runs along PLANT_Y row from plant rightward
    SPINE_ROW = PLANT_Y
    PLANT_RIGHT_EDGE = PLANT_X + 2  # right tile of 3x3 plant footprint

    # Roads above and below spine
    ROAD_ROW_ABOVE = SPINE_ROW - 4
    ROAD_ROW_BELOW = SPINE_ROW + 4

    # Horizontal extent
    COL_START = PLANT_X + 4
    COL_END = min(CX + 35, WORLD_W - 4)

    # Vertical wire branches every 6 cols
    BRANCH_COLS = list(range(COL_START, COL_END + 1, 6))

    # Zone columns (centered between branch cols)
    ZONE_COLS = list(range(COL_START + 3, COL_END, 6))

    # Gather current state
    has_plant = np.any(pm)
    plant_tiles = list(zip(*np.where(pm))) if has_plant else []

    wire_set = set(zip(*np.where(wm))) if np.any(wm) else set()
    road_set = set(zip(*np.where(rm))) if np.any(rm) else set()
    res_tiles = set(zip(*np.where(resm))) if np.any(resm) else set()
    com_tiles = set(zip(*np.where(comm))) if np.any(comm) else set()
    ind_tiles = set(zip(*np.where(indm))) if np.any(indm) else set()
    zone_tiles = res_tiles | com_tiles | ind_tiles

    res_count = len(res_tiles)
    com_count = len(com_tiles)
    ind_count = len(ind_tiles)
    total_zones = res_count + com_count + ind_count

    # Phase 1: Place power plant
    if not has_plant:
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    # Phase 2: Extend horizontal wire spine rightward from plant
    spine_wires = sorted([c for (r, c) in wire_set if r == SPINE_ROW])
    if spine_wires:
        max_spine_wire = max(spine_wires)
    else:
        max_spine_wire = PLANT_RIGHT_EDGE - 1

    if max_spine_wire < COL_END:
        nc = max_spine_wire + 1
        if 0 <= nc < WORLD_W and not pm[SPINE_ROW, nc]:
            if em[SPINE_ROW, nc] or wm[SPINE_ROW, nc]:
                return (Tool.WIRE, nc, SPINE_ROW)

    # Phase 3: Vertical wire branches at branch cols
    BRANCH_MIN_ROW = max(ROAD_ROW_ABOVE - 1, 2)
    BRANCH_MAX_ROW = min(ROAD_ROW_BELOW + 1, WORLD_H - 3)

    for bc in BRANCH_COLS:
        if 0 <= bc < WORLD_W and (SPINE_ROW, bc) in wire_set:
            # Extend upward
            for wr in range(SPINE_ROW - 1, BRANCH_MIN_ROW - 1, -1):
                if (wr, bc) not in wire_set and not pm[wr, bc]:
                    if em[wr, bc]:
                        return (Tool.WIRE, bc, wr)
                    break
            # Extend downward
            for wr in range(SPINE_ROW + 1, BRANCH_MAX_ROW + 1):
                if (wr, bc) not in wire_set and not pm[wr, bc]:
                    if em[wr, bc]:
                        return (Tool.WIRE, bc, wr)
                    break

    # Phase 4: Build horizontal roads above and below spine
    for rrow in [ROAD_ROW_ABOVE, ROAD_ROW_BELOW]:
        if 0 <= rrow < WORLD_H:
            road_cols_here = sorted([c for (r, c) in road_set if r == rrow])
            max_rc = max(road_cols_here) if road_cols_here else COL_START - 1
            if max_rc < COL_END:
                nc = max_rc + 1
                if 0 <= nc < WORLD_W and not pm[rrow, nc]:
                    return (Tool.ROAD, nc, rrow)

    # Phase 5: Vertical connector roads every 6 cols
    for vc in BRANCH_COLS:
        if 0 <= vc < WORLD_W:
            for vr in range(ROAD_ROW_ABOVE, ROAD_ROW_BELOW + 1):
                if 0 <= vr < WORLD_H:
                    if (vr, vc) not in road_set and not pm[vr, vc]:
                        return (Tool.ROAD, vc, vr)

    # Zone placement helpers
    def has_road_access(zy, zx, radius=4):
        for dr in range(-radius, radius + 1):
            for dc in range(-radius, radius + 1):
                rr, rc = zy + dr, zx + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if (rr, rc) in road_set:
                        return True
        return False

    def has_wire_access(zy, zx, radius=5):
        for dr in range(-radius, radius + 1):
            for dc in range(-radius, radius + 1):
                rr, rc = zy + dr, zx + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if (rr, rc) in wire_set or pm[rr, rc]:
                        return True
        return False

    def zone_area_clear(zy, zx):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zy + dr, zx + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc] and (rr, rc) not in zone_tiles:
                    return False
        return True

    def near_existing_zone(zy, zx):
        for (zpr, zpc) in zone_tiles:
            if abs(zy - zpr) <= 2 and abs(zx - zpc) <= 2:
                return True
        return False

    def pick_tool():
        t = max(total_zones, 1)
        if com_count * 4 < t:
            return Tool.COMMERCIAL
        if ind_count * 4 < t:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Phase 6: Place zones in rows above and below roads
    zone_row_sets = [
        ROAD_ROW_ABOVE - 2,
        ROAD_ROW_ABOVE - 5,
        ROAD_ROW_ABOVE - 8,
        ROAD_ROW_BELOW + 2,
        ROAD_ROW_BELOW + 5,
        ROAD_ROW_BELOW + 8,
    ]

    for zr in zone_row_sets:
        for zc in ZONE_COLS:
            if 2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3:
                if not near_existing_zone(zr, zc) and zone_area_clear(zr, zc):
                    if has_road_access(zr, zc) and has_wire_access(zr, zc):
                        return (pick_tool(), zc, zr)

    # Phase 7: Lateral wires to reach zone rows
    # Add horizontal wire at ROAD_ROW_ABOVE-2 and ROAD_ROW_BELOW+2 rows
    for wrow in [ROAD_ROW_ABOVE - 1, ROAD_ROW_BELOW + 1]:
        if 0 <= wrow < WORLD_H:
            wcols_here = sorted([c for (r, c) in wire_set if r == wrow])
            max_wc = max(wcols_here) if wcols_here else COL_START - 1
            # Only extend if there's already a branch wire at this row
            # Check if any wire in column direction reaches this row
            for bc in BRANCH_COLS:
                if (wrow, bc) in wire_set and max_wc < COL_END:
                    # Extend laterally from this branch
                    for nc in range(bc - 1, COL_START - 1, -1):
                        if (wrow, nc) not in wire_set and not pm[wrow, nc]:
                            if em[wrow, nc]:
                                return (Tool.WIRE, nc, wrow)
                            break
                    for nc in range(bc + 1, COL_END + 1):
                        if (wrow, nc) not in wire_set and not pm[wrow, nc]:
                            if em[wrow, nc]:
                                return (Tool.WIRE, nc, wrow)
                            break

    # Phase 8: Second power plant if growing
    if obs.city_pop > 300 and len([p for p in plant_tiles]) < 9:
        # 3x3 plant, so ~9 tiles for 1 plant
        px2, py2 = CX + 20, CY
        if 2 <= px2 <= WORLD_W - 3 and 2 <= py2 <= WORLD_H - 3:
            area_ok = True
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if not em[py2 + dr, px2 + dc]:
                        area_ok = False
            if area_ok:
                return (Tool.COALPOWER, px2, py2)

    # Phase 9: Extra zone rows if population growing
    if obs.city_pop > 150:
        extra_rows = [
            ROAD_ROW_ABOVE - 11,
            ROAD_ROW_BELOW + 11,
        ]
        for zr in extra_rows:
            for zc in ZONE_COLS:
                if 2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3:
                    if not near_existing_zone(zr, zc) and zone_area_clear(zr, zc):
                        if has_road_access(zr, zc, radius=5) and has_wire_access(zr, zc, radius=7):
                            return (pick_tool(), zc, zr)

    # Phase 10: Fill missing road segments
    for vc in BRANCH_COLS:
        for rrow in [ROAD_ROW_ABOVE, ROAD_ROW_BELOW]:
            if 0 <= rrow < WORLD_H and 0 <= vc < WORLD_W:
                if (rrow, vc) not in road_set and not pm[rrow, vc]:
                    return (Tool.ROAD, vc, rrow)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy.
    - Reads current map each step to decide next action.
    - Places coal plant, then grows wire spine, roads, and zones reactively.
    - Adapts based on what's already on the map.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    has_plant = np.any(pm)
    has_wire = np.any(wm)
    has_road = np.any(rm)

    # Use center-left area for the cluster
    cx, cy = 58, 50

    # Phase 1: Place coal power plant
    if not has_plant:
        return (Tool.COALPOWER, cx - 6, cy)

    # Find plant center region
    plant_rows, plant_cols = np.where(pm)
    if len(plant_rows) == 0:
        return None
    # Approximate plant center from tile positions
    pc_r = int(np.median(plant_rows))
    pc_c = int(np.median(plant_cols))

    wire_positions = set(zip(*np.where(wm))) if np.any(wm) else set()
    road_positions = set(zip(*np.where(rm))) if np.any(rm) else set()

    # Phase 2: Connect wire from plant to spine column
    # Spine wire column: cx (which is cx-6+6=plant_center_col+~3)
    # Plant center col roughly pc_c, wire spine at pc_c + 3
    wire_spine_col = pc_c + 4  # column for vertical wire spine

    # First, make sure wire connects from plant rightward to spine col
    # Wire at same row as plant center, from pc_c+2 to wire_spine_col
    for wc in range(pc_c + 2, wire_spine_col + 1):
        if 0 <= wc < WORLD_W and 0 <= pc_r < WORLD_H:
            if not wm[pc_r, wc] and em[pc_r, wc]:
                return (Tool.WIRE, wc, pc_r)

    # Phase 3: Extend wire spine vertically
    spine_rows = sorted([r for (r, c) in wire_positions if c == wire_spine_col])
    target_min_r = cy - 14
    target_max_r = cy + 14

    if not spine_rows:
        # Place initial spine wire at plant row
        if em[pc_r, wire_spine_col]:
            return (Tool.WIRE, wire_spine_col, pc_r)
    else:
        min_r = min(spine_rows)
        max_r = max(spine_rows)
        # Extend downward
        if max_r < target_max_r and max_r + 1 < WORLD_H:
            nr = max_r + 1
            if em[nr, wire_spine_col] or wm[nr, wire_spine_col]:
                return (Tool.WIRE, wire_spine_col, nr)
        # Extend upward
        if min_r > target_min_r and min_r - 1 >= 0:
            nr = min_r - 1
            if em[nr, wire_spine_col] or wm[nr, wire_spine_col]:
                return (Tool.WIRE, wire_spine_col, nr)

    # Phase 4: Build road spine one column to the right of wire spine
    road_spine_col = wire_spine_col + 1
    spine_rows_set = set(spine_rows)

    for r in sorted(spine_rows):
        if 0 <= r < WORLD_H and 0 <= road_spine_col < WORLD_W:
            if not rm[r, road_spine_col] and em[r, road_spine_col]:
                return (Tool.ROAD, road_spine_col, r)

    # Phase 5: Place zones reactively
    # Left zones: center at wire_spine_col - 3 (just left of wire)
    # Right zones: center at road_spine_col + 3 (just right of road)
    left_zone_col = wire_spine_col - 3
    right_zone_col = road_spine_col + 3

    res_count = np.sum(resm)
    com_count = np.sum(comm)
    ind_count = np.sum(indm)

    def zone_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def has_power_nearby(r, c, radius=3):
        # Check if wire or plant tile exists within radius
        r0, r1 = max(0, r - radius), min(WORLD_H, r + radius + 1)
        c0, c1 = max(0, c - radius), min(WORLD_W, c + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(r, c, radius=3):
        r0, r1 = max(0, r - radius), min(WORLD_H, r + radius + 1)
        c0, c1 = max(0, c - radius), min(WORLD_W, c + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    # Scan zones from center outward
    zone_rows = list(range(cy, cy - 15, -3)) + list(range(cy + 3, cy + 15, 3))

    for zr in zone_rows:
        for zc in [left_zone_col, right_zone_col]:
            if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                if zone_free(zr, zc) and has_power_nearby(zr, zc) and has_road_nearby(zr, zc):
                    # Choose zone type based on balance
                    if ind_count < res_count // 5:
                        tool = Tool.INDUSTRIAL
                    elif com_count < res_count // 4:
                        tool = Tool.COMMERCIAL
                    else:
                        tool = Tool.RESIDENTIAL
                    return (tool, zc, zr)

    # Phase 6: Add lateral wires to reach left zones
    for r in sorted(spine_rows):
        for wc in range(wire_spine_col - 1, left_zone_col, -1):
            if 0 <= wc < WORLD_W and 0 <= r < WORLD_H:
                if not wm[r, wc] and em[r, wc]:
                    return (Tool.WIRE, wc, r)

    # Phase 7: Extend road laterally to reach right zones
    for r in sorted(spine_rows):
        for rc in range(road_spine_col + 1, right_zone_col + 1):
            if 0 <= rc < WORLD_W and 0 <= r < WORLD_H:
                if not rm[r, rc] and em[r, rc]:
                    return (Tool.ROAD, rc, r)

    # Phase 8: Add more zones if population is growing
    if obs.city_pop > 100:
        for zr in range(cy - 20, cy + 21, 3):
            for zc in [left_zone_col, right_zone_col, left_zone_col - 6, right_zone_col + 6]:
                if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                    if zone_free(zr, zc) and has_power_nearby(zr, zc, 4) and has_road_nearby(zr, zc, 4):
                        return (Tool.RESIDENTIAL, zc, zr)

    # Phase 9: Add second power plant if needed
    if obs.powered_zones < (res_count + com_count + ind_count) // 10 and obs.funds > 5000:
        # Place another coal plant far from first
        nx, ny = pc_c + 20, cy
        if 0 <= nx + 2 < WORLD_W and 0 <= ny + 2 < WORLD_H:
            area_empty = all(em[ny + dr, nx + dc]
                             for dr in range(-1, 2) for dc in range(-1, 2)
                             if 0 <= ny + dr < WORLD_H and 0 <= nx + dc < WORLD_W)
            if area_empty:
                return (Tool.COALPOWER, nx, ny)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder.
    Each step reads the tile_map and decides next action based on current state.

    Strategy:
    1. Place coal power plant
    2. Extend wire spine horizontally from plant
    3. Extend vertical wire branches from spine
    4. Build road rows above and below wire spine
    5. Build vertical road connectors
    6. Place zones where road+wire access exists
    7. Add second plant when needed, services when population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    CX, CY = 35, 50

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Step 1: Place coal power plant if none exists
    if not np.any(pm):
        return (Tool.COALPOWER, CX, CY)

    # Find plant center
    plant_ys, plant_xs = np.where(pm)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    # Gather zone info
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    zone_ys = np.concatenate([np.where(resm)[0], np.where(comm)[0], np.where(indm)[0]])
    zone_xs = np.concatenate([np.where(resm)[1], np.where(comm)[1], np.where(indm)[1]])
    zone_set = set(zip(zone_ys.tolist(), zone_xs.tolist()))

    def pick_tool():
        t = max(total_zones, 1)
        if com_count / t < 0.20:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    # Wire spine parameters
    spine_y = py
    wire_start = px + 2
    wire_end = min(px + 60, WORLD_W - 4)

    # Step 2: Extend horizontal wire spine from plant rightward
    for wx in range(wire_start, wire_end + 1):
        wy = spine_y
        if not in_bounds(wx, wy):
            break
        if not bool(wm[wy, wx]) and not bool(pm[wy, wx]):
            if bool(em[wy, wx]):
                return (Tool.WIRE, wx, wy)
            break  # blocked

    # Step 3: Vertical wire branches every 5 cols from spine
    branch_cols = list(range(wire_start + 3, wire_end + 1, 5))
    for bx in branch_cols:
        if not in_bounds(bx, spine_y):
            continue
        if not (bool(wm[spine_y, bx]) or bool(pm[spine_y, bx])):
            continue  # spine not wired here yet
        for sign in [-1, 1]:
            for dy in range(1, 9):
                wy2 = spine_y + sign * dy
                if not in_bounds(bx, wy2):
                    break
                if bool(wm[wy2, bx]) or bool(pm[wy2, bx]):
                    continue
                if bool(em[wy2, bx]):
                    return (Tool.WIRE, bx, wy2)
                break  # blocked

    # Step 4: Road rows above and below spine
    road_top = spine_y - 3
    road_bot = spine_y + 3
    road_start = wire_start
    road_end = min(wire_end, WORLD_W - 4)

    # Build top road row
    for rx in range(road_start, road_end + 1):
        ry = road_top
        if not in_bounds(rx, ry):
            break
        if not bool(rm[ry, rx]) and not bool(pm[ry, rx]) and not bool(wm[ry, rx]):
            if bool(em[ry, rx]):
                return (Tool.ROAD, rx, ry)
            break

    # Build bottom road row
    for rx in range(road_start, road_end + 1):
        ry = road_bot
        if not in_bounds(rx, ry):
            break
        if not bool(rm[ry, rx]) and not bool(pm[ry, rx]) and not bool(wm[ry, rx]):
            if bool(em[ry, rx]):
                return (Tool.ROAD, rx, ry)
            break

    # Step 5: Vertical road connectors every 5 cols
    for vc in range(road_start, road_end + 1, 5):
        for vr in range(road_top, road_bot + 1):
            if not in_bounds(vc, vr):
                continue
            if not bool(rm[vr, vc]) and not bool(pm[vr, vc]) and not bool(wm[vr, vc]):
                if bool(em[vr, vc]):
                    return (Tool.ROAD, vc, vr)

    # Step 6: Zone placement - build neighbor proximity masks efficiently
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            r0s = max(0, -dy); r0e = min(WORLD_H, WORLD_H - dy)
            c0s = max(0, -dx); c0e = min(WORLD_W, WORLD_W - dx)
            r1s = max(0, dy);  r1e = min(WORLD_H, WORLD_H + dy)
            c1s = max(0, dx);  c1e = min(WORLD_W, WORLD_W + dx)
            nbr_road[r1s:r1e, c1s:c1e] |= rm[r0s:r0e, c0s:c0e]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            r0s = max(0, -dy); r0e = min(WORLD_H, WORLD_H - dy)
            c0s = max(0, -dx); c0e = min(WORLD_W, WORLD_W - dx)
            r1s = max(0, dy);  r1e = min(WORLD_H, WORLD_H + dy)
            c1s = max(0, dx);  c1e = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r1s:r1e, c1s:c1e] |= wm[r0s:r0e, c0s:c0e]
            nbr_wire[r1s:r1e, c1s:c1e] |= pm[r0s:r0e, c0s:c0e]

    # Candidate zone centers
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Deterministic scan with step-based offset for variety
        step_hash = int(obs.step * 17 + int(obs.city_pop * 3)) % max(len(cxs), 1)
        for offset in range(min(len(cxs), 60)):
            k = (step_hash + offset * 11) % len(cxs)
            zx2, zy2 = int(cxs[k]), int(cys[k])
            if zone_clear(zx2, zy2):
                return (pick_tool(), zx2, zy2)

    # Step 7: Second power plant when many zones
    if total_zones > 15 or obs.city_pop > 400:
        p2x = min(px + 55, WORLD_W - 5)
        p2y = py
        nearby_plant = any(
            in_bounds(p2x + dx, p2y + dy) and bool(pm[p2y + dy, p2x + dx])
            for dy in range(-6, 7) for dx in range(-6, 7)
        )
        if not nearby_plant and in_bounds(p2x, p2y) and bool(em[p2y, p2x]):
            return (Tool.COALPOWER, p2x, p2y)

    # Step 8: Services when population warrants
    if obs.city_pop > 150:
        fx, fy = px + 6, py - 8
        if in_bounds(fx, fy) and bool(em[fy, fx]):
            return (Tool.FIRESTATION, fx, fy)
        px2, py2 = px + 6, py + 8
        if in_bounds(px2, py2) and bool(em[py2, px2]):
            return (Tool.POLICESTATION, px2, py2)

    # Step 9: Extend roads outward from existing road frontier (reactive)
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = int(obs.step * 13) % max(len(road_xs), 1)
        rx_s, ry_s = int(road_xs[step_k]), int(road_ys[step_k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx_s + dx2, ry_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # Step 10: Extend wires from existing wire frontier (reactive)
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        step_k2 = int(obs.step * 7) % max(len(wire_xs), 1)
        wx_s, wy_s = int(wire_xs[step_k2]), int(wire_ys[step_k2])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = wx_s + dx2, wy_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    if "plan" not in state:
        plan = []

        # Strategy: Build a compact grid-based city with proper power distribution
        # Use a cross-shaped road network with zones on all sides
        # Center cluster at (60, 50) - middle of map

        cx, cy = 60, 50

        # Place coal power plant first (top-left of center)
        plan.append((Tool.COALPOWER, cx - 15, cy))

        # Second coal plant for more power
        plan.append((Tool.COALPOWER, cx + 15, cy))

        # Main horizontal road spine
        for x in range(cx - 25, cx + 26):
            plan.append((Tool.ROAD, x, cy))

        # Main vertical road spine
        for y in range(cy - 20, cy + 21):
            plan.append((Tool.ROAD, cx, y))

        # Horizontal wire just above main road (power distribution)
        for x in range(cx - 25, cx + 26):
            plan.append((Tool.WIRE, x, cy - 1))

        # Vertical wire alongside vertical road
        for y in range(cy - 20, cy + 21):
            plan.append((Tool.WIRE, cx + 1, y))

        # Connect power plants to wire grid
        for x in range(cx - 15, cx + 1):
            plan.append((Tool.WIRE, x, cy - 1))
        for x in range(cx, cx + 16):
            plan.append((Tool.WIRE, x, cy - 1))

        # Parallel horizontal roads (every 4 rows)
        for dy in [-8, -4, 4, 8, 12, -12]:
            for x in range(cx - 24, cx + 25):
                plan.append((Tool.ROAD, x, cy + dy))

        # Parallel vertical roads (every 4 cols)
        for dx in [-8, -4, 4, 8, 12, 16, -12, -16, 20, -20]:
            for y in range(cy - 19, cy + 20):
                plan.append((Tool.ROAD, cx + dx, y))

        # Wire along each horizontal road for power
        for dy in [-8, -4, 4, 8, 12, -12]:
            for x in range(cx - 24, cx + 25):
                plan.append((Tool.WIRE, x, cy + dy - 1))

        # Place zones in a grid pattern - varied mix
        # Grid of zones: place centers every 4 tiles, between roads
        zone_positions = []
        for gy in range(-15, 16, 4):
            for gx in range(-22, 23, 4):
                # Skip if too close to power plant positions
                if abs(gx + 15) < 3 and abs(gy) < 3:
                    continue
                if abs(gx - 15) < 3 and abs(gy) < 3:
                    continue
                # Skip road spines (center col and row)
                if abs(gx) < 2 or abs(gy) < 2:
                    continue
                zone_positions.append((cx + gx, cy + gy))

        # Assign zone types: mostly residential, some commercial and industrial
        for i, (zx, zy) in enumerate(zone_positions):
            # Keep within bounds
            if zx < 3 or zx > 116 or zy < 3 or zy > 96:
                continue
            r = i % 9
            if r < 4:
                tool = Tool.RESIDENTIAL
            elif r < 6:
                tool = Tool.COMMERCIAL
            elif r < 8:
                tool = Tool.INDUSTRIAL
            else:
                tool = Tool.RESIDENTIAL
            plan.append((tool, zx, zy))

        # Add services
        plan.append((Tool.FIRESTATION, cx - 20, cy - 15))
        plan.append((Tool.POLICESTATION, cx + 20, cy - 15))
        plan.append((Tool.FIRESTATION, cx - 20, cy + 15))
        plan.append((Tool.POLICESTATION, cx + 20, cy + 15))

        # Stadium for city appeal
        plan.append((Tool.STADIUM, cx, cy - 15))

        # Second neighborhood to the north
        cx2, cy2 = 60, 20
        plan.append((Tool.COALPOWER, cx2 - 10, cy2))
        for x in range(cx2 - 18, cx2 + 19):
            plan.append((Tool.ROAD, x, cy2))
        for y in range(cy2 - 8, cy2 + 9):
            plan.append((Tool.ROAD, cx2, y))
        for x in range(cx2 - 18, cx2 + 19):
            plan.append((Tool.WIRE, x, cy2 - 1))
        for y in range(cy2 - 8, cy2 + 9):
            plan.append((Tool.WIRE, cx2 + 1, y))

        for gy in range(-6, 7, 3):
            for gx in range(-15, 16, 3):
                if abs(gx) < 2 or abs(gy) < 2:
                    continue
                if abs(gx + 10) < 2 and abs(gy) < 2:
                    continue
                zx2, zy2 = cx2 + gx, cy2 + gy
                if zx2 < 3 or zx2 > 116 or zy2 < 3 or zy2 > 96:
                    continue
                idx = (gx + gy) % 6
                if idx < 2:
                    tool = Tool.COMMERCIAL
                elif idx < 4:
                    tool = Tool.RESIDENTIAL
                else:
                    tool = Tool.INDUSTRIAL
                plan.append((tool, zx2, zy2))

        # Connect the two neighborhoods with road and wire
        for y in range(cy2 + 1, cy - 1):
            plan.append((Tool.ROAD, cx, y))
            plan.append((Tool.WIRE, cx + 1, y))

        state["plan"] = plan
        state["i"] = 0

    i = state["i"]
    plan = state["plan"]

    if i < len(plan):
        state["i"] = i + 1
        return plan[i]

    # Reactive phase: add more zones near roads
    tm = obs.tile_map
    emp = empty_mask(tm)
    road = road_mask(tm)
    res = res_mask(tm)
    com = com_mask(tm)
    ind = ind_mask(tm)

    # Find empty cells with road neighbors
    nbr_road = np.zeros((100, 120), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1),(-2,0),(2,0),(0,-2),(0,2),(-3,0),(3,0),(0,-3),(0,3)]:
        r_shifted = np.roll(road, dy, axis=0)
        r_shifted = np.roll(r_shifted, dx, axis=1)
        nbr_road |= r_shifted

    any_zone = res | com | ind
    nbr_zone = np.zeros((100, 120), dtype=bool)
    for dy, dx in [(-3,0),(3,0),(0,-3),(0,3),(-6,0),(6,0),(0,-6),(0,6)]:
        z_shifted = np.roll(any_zone, dy, axis=0)
        z_shifted = np.roll(z_shifted, dx, axis=1)
        nbr_zone |= z_shifted

    cand = emp & nbr_road & nbr_zone
    ys, xs = np.where(cand)

    if len(xs) == 0:
        cand2 = emp & nbr_road
        ys, xs = np.where(cand2)
        if len(xs) == 0:
            return None

    k = int((obs.step * 17 + int(tm.sum()) % 1000) % len(xs))
    x, y = int(xs[k]), int(ys[k])

    # More commercial bias in reactive phase
    r = (obs.step * 7 + k * 3) % 10
    if r < 3:
        tool = Tool.RESIDENTIAL
    elif r < 6:
        tool = Tool.COMMERCIAL
    elif r < 9:
        tool = Tool.INDUSTRIAL
    else:
        tool = Tool.ROAD

    return (tool, x, y)

def act(obs, state):
    """
    Closed-loop city builder: each step reads the map and decides placement
    based on current state of infrastructure and zones.
    """
    tm = obs.tile_map
    cx, cy = WORLD_W // 2, WORLD_H // 2

    # Phase tracker: 0=plant, 1=wire spine, 2=road spine, 3=zones, 4=expand
    if "phase" not in state:
        state["phase"] = 0
        state["wire_dy"] = -15
        state["road_dy"] = -15
        state["zone_dy"] = -12

    phase = state["phase"]

    # --- Phase 0: Place coal power plant ---
    if phase == 0:
        # Place coal plant if not already there
        pm = plant_mask(tm)
        if not pm.any():
            state["phase"] = 1
            return (Tool.COALPOWER, cx - 3, cy)
        state["phase"] = 1

    # --- Phase 1: Extend wire spine vertically from plant ---
    if phase == 1:
        dy = state["wire_dy"]
        pm = plant_mask(tm)
        wm = wire_mask(tm)

        # Wire column at cx-1 (connects plant to spine at cx)
        # and wire column at cx (vertical spine)
        # Find the next wire position that isn't already wired
        target_x = cx - 1
        for try_dy in range(dy, 16):
            wy = cy + try_dy
            if 0 <= wy < WORLD_H:
                if not wm[wy, target_x] and not pm[wy, target_x]:
                    state["wire_dy"] = try_dy + 1
                    return (Tool.WIRE, target_x, wy)
        # Also wire at cx (vertical)
        for try_dy in range(-15, 16):
            wy = cy + try_dy
            if 0 <= wy < WORLD_H:
                if not wm[wy, cx] and not pm[wy, cx]:
                    return (Tool.WIRE, cx, wy)
        state["phase"] = 2

    # --- Phase 2: Extend road spines ---
    if phase == 2:
        rm = road_mask(tm)
        wm = wire_mask(tm)
        pm = plant_mask(tm)

        # Road at cx+1 (right of wire spine) and cx-2 (left side)
        for dx_offset in [cx + 1, cx - 2]:
            for try_dy in range(-15, 16):
                ry = cy + try_dy
                if 0 <= ry < WORLD_H:
                    if not rm[ry, dx_offset] and not pm[ry, dx_offset]:
                        return (Tool.ROAD, dx_offset, ry)

        # Horizontal road connector at cy
        for try_dx in range(cx - 6, cx + 8):
            if 0 <= try_dx < WORLD_W:
                if not rm[cy, try_dx] and not pm[cy, try_dx] and not wm[cy, try_dx]:
                    return (Tool.ROAD, try_dx, cy)

        state["phase"] = 3

    # --- Phase 3: Place zones based on current infrastructure ---
    if phase == 3:
        rm = road_mask(tm)
        wm = wire_mask(tm)
        em = empty_mask(tm)
        pm = plant_mask(tm)

        def near_road(x, y, radius=2):
            for dy in range(-radius, radius + 1):
                for dx in range(-radius, radius + 1):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < WORLD_H and 0 <= nx < WORLD_W:
                        if rm[ny, nx]:
                            return True
            return False

        def near_wire_or_plant(x, y, radius=3):
            for dy in range(-radius, radius + 1):
                for dx in range(-radius, radius + 1):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < WORLD_H and 0 <= nx < WORLD_W:
                        if wm[ny, nx] or pm[ny, nx]:
                            return True
            return False

        def can_place_zone(x, y):
            # Check 3x3 footprint is valid
            for dy in range(-1, 2):
                for dx in range(-1, 2):
                    ny, nx = y + dy, x + dx
                    if ny < 0 or ny >= WORLD_H or nx < 0 or nx >= WORLD_W:
                        return False
                    if pm[ny, nx]:
                        return False
            return near_road(x, y) and near_wire_or_plant(x, y)

        # Try to place zones in a structured grid pattern
        # Residential left of wire spine, right of road-left
        # Right of road spine, commercial further right
        dy = state["zone_dy"]
        placed = False

        for try_dy in range(dy, 13, 3):
            zy = cy + try_dy
            if 0 <= zy < WORLD_H:
                # Left residential at cx-5
                if can_place_zone(cx - 5, zy) and em[zy, cx - 5]:
                    state["zone_dy"] = try_dy + 3
                    tool = Tool.RESIDENTIAL if (obs.step % 6 < 4) else Tool.COMMERCIAL
                    return (tool, cx - 5, zy)
                # Right residential at cx+4
                if can_place_zone(cx + 4, zy) and em[zy, cx + 4]:
                    state["zone_dy"] = try_dy + 3
                    return (Tool.RESIDENTIAL, cx + 4, zy)
                # Industrial left
                if can_place_zone(cx - 8, zy) and em[zy, cx - 8]:
                    state["zone_dy"] = try_dy + 3
                    return (Tool.INDUSTRIAL, cx - 8, zy)

        # Also try negative dy side
        for try_dy in range(-12, 0, 3):
            zy = cy + try_dy
            if 0 <= zy < WORLD_H:
                if can_place_zone(cx - 5, zy) and em[zy, cx - 5]:
                    tool = Tool.RESIDENTIAL if (obs.step % 6 < 4) else Tool.COMMERCIAL
                    return (tool, cx - 5, zy)
                if can_place_zone(cx + 4, zy) and em[zy, cx + 4]:
                    return (Tool.RESIDENTIAL, cx + 4, zy)
                if can_place_zone(cx - 8, zy) and em[zy, cx - 8]:
                    return (Tool.INDUSTRIAL, cx - 8, zy)

        state["phase"] = 4

    # --- Phase 4: Reactive expansion ---
    # Read current map state and expand from existing zones
    rm = road_mask(tm)
    wm = wire_mask(tm)
    em = empty_mask(tm)
    pm = plant_mask(tm)
    res = res_mask(tm)
    com = com_mask(tm)
    ind = ind_mask(tm)

    def near_infra(x, y, radius=3):
        """Check if position is near road AND near wire/plant"""
        has_road = False
        has_power = False
        for dy in range(-radius, radius + 1):
            for dx in range(-radius, radius + 1):
                ny, nx = y + dy, x + dx
                if 0 <= ny < WORLD_H and 0 <= nx < WORLD_W:
                    if rm[ny, nx]:
                        has_road = True
                    if wm[ny, nx] or pm[ny, nx]:
                        has_power = True
        return has_road and has_power

    # Find empty cells adjacent to existing zones
    zone_mask_combined = res | com | ind
    nbr_zone = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    nbr_zone[1:, :] |= zone_mask_combined[:-1, :]
    nbr_zone[:-1, :] |= zone_mask_combined[1:, :]
    nbr_zone[:, 1:] |= zone_mask_combined[:, :-1]
    nbr_zone[:, :-1] |= zone_mask_combined[:, 1:]

    # Find candidates: empty, near zones, near infra
    candidates = []
    ys, xs = np.where(em & nbr_zone)
    for y, x in zip(ys, xs):
        if near_infra(x, y):
            # Check 3x3 footprint
            valid = True
            for dy in range(-1, 2):
                for dx in range(-1, 2):
                    ny2, nx2 = y + dy, x + dx
                    if ny2 < 0 or ny2 >= WORLD_H or nx2 < 0 or nx2 >= WORLD_W:
                        valid = False
                        break
                    if pm[ny2, nx2]:
                        valid = False
                        break
                if not valid:
                    break
            if valid:
                candidates.append((x, y))

    if candidates:
        # Deterministic selection based on current map state
        k = int(tm.sum() % len(candidates))
        x, y = candidates[k]

        # Decide tool based on current population balance
        r = obs.res_pop
        c = obs.com_pop
        ind_p = obs.ind_pop
        total = r + c + ind_p + 1

        if r / total < 0.5:
            tool = Tool.RESIDENTIAL
        elif c / total < 0.25:
            tool = Tool.COMMERCIAL
        elif ind_p / total < 0.25:
            tool = Tool.INDUSTRIAL
        else:
            tool = Tool.RESIDENTIAL

        return (tool, x, y)

    # If no zone candidates, try extending roads near existing road network
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        # Find empty cells adjacent to roads
        nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        nbr_road[1:, :] |= rm[:-1, :]
        nbr_road[:-1, :] |= rm[1:, :]
        nbr_road[:, 1:] |= rm[:, :-1]
        nbr_road[:, :-1] |= rm[:, 1:]

        road_cands = np.where(em & nbr_road & ~pm)
        if len(road_cands[0]) > 0:
            k = int(tm.sum() % len(road_cands[0]))
            ry, rx = road_cands[0][k], road_cands[1][k]
            return (Tool.ROAD, int(rx), int(ry))

    # Fallback: extend wires
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        nbr_wire[1:, :] |= wm[:-1, :]
        nbr_wire[:-1, :] |= wm[1:, :]
        nbr_wire[:, 1:] |= wm[:, :-1]
        nbr_wire[:, :-1] |= wm[:, 1:]
        wire_cands = np.where(em & nbr_wire & ~pm)
        if len(wire_cands[0]) > 0:
            k = int(tm.sum() % len(wire_cands[0]))
            wy, wx = wire_cands[0][k], wire_cands[1][k]
            return (Tool.WIRE, int(wx), int(wy))

    return None

def act(obs, state):
    """
    Improved city builder with a different layout:
    - Vertical wire spine instead of horizontal
    - Roads perpendicular to wire (horizontal roads)
    - Denser zone placement with balanced R/C/I mix
    - Two power plants placed early
    - More systematic zone placement
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    # Initialize state
    if 'phase' not in state:
        state['phase'] = 0
        state['plan'] = []

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Anchor point - center-left area
    SPINE_X = 30  # vertical wire spine column
    SPINE_Y_START = 20
    SPINE_Y_END = 80
    PLANT1_X = SPINE_X
    PLANT1_Y = 30
    PLANT2_X = SPINE_X
    PLANT2_Y = 65

    has_plant = np.any(pm)
    plant_ys, plant_xs = (np.where(pm) if has_plant else (np.array([]), np.array([])))

    wire_ys, wire_xs = np.where(wm)
    road_ys, road_xs = np.where(rm)
    res_ys, res_xs = np.where(resm)
    com_ys, com_xs = np.where(comm)
    ind_ys, ind_xs = np.where(indm)

    wire_set = set(zip(wire_ys.tolist(), wire_xs.tolist()))
    road_set = set(zip(road_ys.tolist(), road_xs.tolist()))
    zone_set = set(zip(
        np.concatenate([res_ys, com_ys, ind_ys]).tolist(),
        np.concatenate([res_xs, com_xs, ind_xs]).tolist()
    ))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        # Target: 50% res, 25% com, 25% ind
        t = max(total_zones, 1)
        r = res_count / t
        c = com_count / t
        i = ind_count / t
        if c < 0.25:
            return Tool.COMMERCIAL
        if i < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    # Phase 1: Place first power plant
    if not has_plant:
        return (Tool.COALPOWER, PLANT1_X, PLANT1_Y)

    # Phase 2: Build vertical wire spine
    for wy in range(SPINE_Y_START, SPINE_Y_END + 1):
        wx = SPINE_X
        if not in_bounds(wx, wy):
            continue
        if not (bool(wm[wy, wx]) or bool(pm[wy, wx])):
            if bool(em[wy, wx]):
                return (Tool.WIRE, wx, wy)
            # bulldoze if needed (auto-bulldoze is on, just place)
            return (Tool.WIRE, wx, wy)

    # Phase 3: Place second power plant connected to wire spine
    p2y, p2x = PLANT2_Y, PLANT2_X
    nearby_plant2 = any(
        in_bounds(p2x + dx, p2y + dy) and bool(pm[p2y + dy, p2x + dx])
        for dx in range(-4, 5) for dy in range(-4, 5)
        if not (dx == 0 and dy == 0)
    )
    if not nearby_plant2:
        # Check if spine wire reaches plant2 area
        spine_complete_to_p2 = all(
            bool(wm[y, SPINE_X]) or bool(pm[y, SPINE_X])
            for y in range(SPINE_Y_START, PLANT2_Y + 1)
        )
        if spine_complete_to_p2:
            if bool(em[p2y, p2x]) or (not bool(pm[p2y, p2x])):
                return (Tool.COALPOWER, p2x, p2y)

    # Phase 4: Build horizontal roads branching from spine
    # Roads at intervals of 6 rows, to the right of spine
    road_rows = list(range(SPINE_Y_START + 3, SPINE_Y_END - 2, 6))
    road_x_start = SPINE_X + 2
    road_x_end = min(SPINE_X + 50, WORLD_W - 3)

    for rrow in road_rows:
        if not in_bounds(road_x_start, rrow):
            continue
        # Find how far road extends in this row
        existing_in_row = sorted([c for (r, c) in road_set if r == rrow and c >= road_x_start])
        next_col = road_x_start if not existing_in_row else max(existing_in_row) + 1
        if next_col <= road_x_end and in_bounds(next_col, rrow):
            if not bool(pm[rrow, next_col]) and not bool(wm[rrow, next_col]):
                return (Tool.ROAD, next_col, rrow)

    # Phase 5: Branch wires horizontally from spine to reach road rows
    for rrow in road_rows:
        # Check if wire reaches the road start
        for wx2 in range(SPINE_X + 1, road_x_start + 1):
            wy2 = rrow
            if not in_bounds(wx2, wy2):
                break
            if not (bool(wm[wy2, wx2]) or bool(pm[wy2, wx2]) or bool(rm[wy2, wx2])):
                if bool(em[wy2, wx2]):
                    return (Tool.WIRE, wx2, wy2)
                break

    # Phase 6: Extend wires along road rows (under roads essentially)
    # Actually place wire on spine-adjacent tile then roads cover further
    # Add vertical connector wires every 12 cols from spine
    for branch_col in range(road_x_start + 3, road_x_end, 8):
        for wy3 in range(SPINE_Y_START, SPINE_Y_END + 1):
            wx3 = branch_col
            if not in_bounds(wx3, wy3):
                continue
            if not (bool(wm[wy3, wx3]) or bool(pm[wy3, wx3]) or bool(rm[wy3, wx3])):
                # Only extend if connected row has wire
                # Check if horizontal wire reaches this column from spine
                has_h_wire = any(bool(wm[wy3, c]) or bool(pm[wy3, c]) for c in range(SPINE_X, wx3))
                if has_h_wire and bool(em[wy3, wx3]):
                    return (Tool.WIRE, wx3, wy3)

    # Phase 7: Place zones near roads with wire access
    # Build neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        step_hash = int(obs.step * 17 + int(tm[50, 30]) * 11) % max(len(cxs), 1)
        for offset in range(min(len(cxs), 40)):
            k = (step_hash + offset * 11) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # Phase 8: Services when population grows
    if obs.city_pop > 100:
        fx, fy = SPINE_X + 8, PLANT1_Y - 6
        if in_bounds(fx, fy) and bool(em[fy, fx]):
            return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 300:
        px2, py2 = SPINE_X + 8, PLANT2_Y + 6
        if in_bounds(px2, py2) and bool(em[py2, px2]):
            return (Tool.POLICESTATION, px2, py2)

    # Phase 9: Extend roads further right if zones saturated
    if total_zones > 20:
        for rrow in road_rows:
            existing_in_row = sorted([c for (r, c) in road_set if r == rrow])
            if existing_in_row:
                nc = max(existing_in_row) + 1
                if nc < min(SPINE_X + 70, WORLD_W - 3) and in_bounds(nc, rrow):
                    if bool(em[rrow, nc]):
                        return (Tool.ROAD, nc, rrow)

    # Phase 10: Third coal plant if needed
    if total_zones > 30:
        p3x = SPINE_X + 20
        p3y = PLANT1_Y
        nearby = any(
            in_bounds(p3x + dx, p3y + dy) and bool(pm[p3y + dy, p3x + dx])
            for dx in range(-5, 6) for dy in range(-5, 6)
        )
        if not nearby and in_bounds(p3x, p3y) and bool(em[p3y, p3x]):
            return (Tool.COALPOWER, p3x, p3y)

    # Fallback: extend wire from spine toward road areas
    if len(road_xs) > 0 and len(wire_xs) > 0:
        sample = list(zip(road_ys.tolist(), road_xs.tolist()))
        for rr, rc in sample[::max(1, len(sample) // 20)]:
            if not nbr_wire[rr, rc]:
                if wire_set:
                    closest_w = min(wire_set, key=lambda p: abs(p[0] - rr) + abs(p[1] - rc))
                    wr, wc = closest_w
                    sr = (1 if rr > wr else -1 if rr < wr else 0)
                    sc = (1 if rc > wc else -1 if rc < wc else 0)
                    for nr2, nc2 in [(wr + sr, wc), (wr, wc + sc)]:
                        if in_bounds(nc2, nr2) and bool(em[nr2, nc2]) and not bool(pm[nr2, nc2]):
                            return (Tool.WIRE, nc2, nr2)

    return None

def act(obs, state):
    """
    Improved city builder with a different layout strategy:
    - Place power plant at top-left area
    - Build horizontal wire spine from plant
    - Build TWO parallel road spines (above and below wire)
    - Place mixed zones (R/C/I) in blocks adjacent to roads
    - Add second coal plant after growth
    - More aggressive zone placement
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    # Use state to track placement queue
    if 'phase' not in state:
        state['phase'] = 0
        state['queue'] = []

    # Plant at (20, 30) - left-center area
    PX, PY = 20, 30

    has_plant = np.any(pm)
    plant_ys, plant_xs = np.where(pm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Phase 1: Place coal power plant ---
    if not has_plant:
        return (Tool.COALPOWER, PX, PY)

    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    wire_ys, wire_xs = np.where(wm)
    road_ys, road_xs = np.where(rm)
    res_ys, res_xs = np.where(resm)
    com_ys, com_xs = np.where(comm)
    ind_ys, ind_xs = np.where(indm)

    wire_set = set(zip(wire_ys.tolist(), wire_xs.tolist()))
    road_set = set(zip(road_ys.tolist(), road_xs.tolist()))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def can_wire(x, y):
        return in_bounds(x, y) and not bool(pm[y, x])

    def can_road(x, y):
        return in_bounds(x, y) and not bool(pm[y, x])

    # --- Phase 2: Build horizontal wire spine from plant going RIGHT ---
    # Wire at py row from px+2 to px+70
    wire_end = min(px + 70, WORLD_W - 4)
    for wx in range(px + 2, wire_end + 1):
        wy = py
        if (wy, wx) not in wire_set and can_wire(wx, wy) and em[wy, wx]:
            return (Tool.WIRE, wx, wy)

    # Also extend wire vertically for second cluster
    # Vertical wire going down at px+40
    branch_x = px + 40
    for wy in range(py + 1, py + 20):
        wx = branch_x
        if not in_bounds(wx, wy):
            break
        if (wy, wx) not in wire_set and can_wire(wx, wy) and em[wy, wx]:
            return (Tool.WIRE, wx, wy)

    # --- Phase 3: Road grid - two horizontal spines ---
    road_top = py - 4   # road above wire spine
    road_bot = py + 4   # road below wire spine
    road_start = px + 3
    road_end = min(px + 65, WORLD_W - 4)

    # Build top horizontal road
    for rx in range(road_start, road_end + 1):
        ry = road_top
        if (ry, rx) not in road_set and can_road(rx, ry):
            return (Tool.ROAD, rx, ry)

    # Build bottom horizontal road
    for rx in range(road_start, road_end + 1):
        ry = road_bot
        if (ry, rx) not in road_set and can_road(rx, ry):
            return (Tool.ROAD, rx, ry)

    # Vertical connector roads every 6 cols
    for vc in range(road_start, road_end + 1, 6):
        for vr in range(road_top, road_bot + 1):
            if (vr, vc) not in road_set and can_road(vc, vr):
                return (Tool.ROAD, vc, vr)

    # Second cluster roads (around py+12 to py+18)
    road2_top = py + 12
    road2_bot = py + 18
    road2_start = branch_x - 15
    road2_end = min(branch_x + 20, WORLD_W - 4)
    if road2_top < WORLD_H - 4 and road2_bot < WORLD_H - 4:
        for rx in range(road2_start, road2_end + 1):
            if (road2_top, rx) not in road_set and can_road(rx, road2_top):
                return (Tool.ROAD, rx, road2_top)
        for rx in range(road2_start, road2_end + 1):
            if (road2_bot, rx) not in road_set and can_road(rx, road2_bot):
                return (Tool.ROAD, rx, road2_bot)
        for vc in range(road2_start, road2_end + 1, 6):
            for vr in range(road2_top, road2_bot + 1):
                if (vr, vc) not in road_set and can_road(vc, vr):
                    return (Tool.ROAD, vc, vr)

    # --- Phase 4: Zone placement ---
    def has_road_near(zx, zy, r=3):
        for dr in range(-r, r + 1):
            for dc in range(-r, r + 1):
                if (zy + dr, zx + dc) in road_set:
                    return True
        return False

    def has_power_near(zx, zy, r=5):
        for dr in range(-r, r + 1):
            for dc in range(-r, r + 1):
                nr, nc = zy + dr, zx + dc
                if (nr, nc) in wire_set:
                    return True
                if in_bounds(nc, nr) and pm[nr, nc]:
                    return True
        return False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                # Allow placing on empty or existing zone tiles
                if not em[nr, nc] and not resm[nr, nc] and not comm[nr, nc] and not indm[nr, nc]:
                    return False
        return True

    def pick_tool(zx, zy):
        # Vary zone type based on position for diversity
        t = max(total_zones, 1)
        cr = com_count / t
        ir = ind_count / t
        rr = res_count / t
        # Target: 50% R, 25% C, 25% I
        if cr < 0.20:
            return Tool.COMMERCIAL
        if ir < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Zone rows above/below both road spines
    zone_candidates = []
    for offset in [-2, -5, -8, 2, 5, 8]:
        zr = road_top + offset
        if 2 <= zr <= WORLD_H - 3:
            for zc in range(road_start + 1, road_end, 4):
                if 2 <= zc <= WORLD_W - 3:
                    zone_candidates.append((zr, zc))

    for offset in [-2, -5, 2, 5]:
        zr = road_bot + offset
        if 2 <= zr <= WORLD_H - 3:
            for zc in range(road_start + 1, road_end, 4):
                if 2 <= zc <= WORLD_W - 3:
                    zone_candidates.append((zr, zc))

    # Second cluster zones
    for offset in [-2, -5, 2, 5]:
        zr = road2_top + offset
        if 2 <= zr <= WORLD_H - 3:
            for zc in range(road2_start + 1, road2_end, 4):
                if 2 <= zc <= WORLD_W - 3:
                    zone_candidates.append((zr, zc))

    for zr, zc in zone_candidates:
        if zone_clear(zc, zr) and has_road_near(zc, zr) and has_power_near(zc, zr):
            return (pick_tool(zc, zr), zc, zr)

    # --- Phase 5: Second power plant ---
    if obs.city_pop > 200 or (np.sum(pm) < 9 and obs.step > 200):
        nx2, ny2 = px + 45, py - 10
        if in_bounds(nx2, ny2) and em[ny2, nx2]:
            return (Tool.COALPOWER, nx2, ny2)

    # --- Phase 6: Services ---
    if obs.city_pop > 100:
        fx, fy = px + 10, py - 8
        if in_bounds(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
        fx2, fy2 = px + 18, py + 8
        if in_bounds(fx2, fy2) and em[fy2, fx2]:
            return (Tool.POLICESTATION, fx2, fy2)

    # --- Phase 7: Reactive zone fill using dilated masks ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand = em & nbr_road & nbr_wire
    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        k = int((obs.step * 13 + int(tm[50, 60]) * 7)) % len(cxs)
        zx, zy = int(cxs[k]), int(cys[k])
        if zone_clear(zx, zy):
            return (pick_tool(zx, zy), zx, zy)

    # Extend road from frontier
    if len(road_xs) > 0:
        k = int(obs.step * 11) % len(road_xs)
        rx2, ry2 = int(road_xs[k]), int(road_ys[k])
        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx2 + dx, ry2 + dy
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    # Closed-loop adaptive policy:
    # Read current map each step, find frontier of existing infrastructure,
    # and extend power/roads/zones toward where they're needed.

    cx, cy = WORLD_W // 2, WORLD_H // 2

    tm = obs.tile_map
    pm = plant_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)
    emp = empty_mask(tm)

    def valid(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def has(mask, x, y):
        return valid(x, y) and bool(mask[y, x])

    def is_powered_or_plant(x, y):
        return has(pm, x, y) or has(wm, x, y)

    # --- Phase 0: Place first coal plant ---
    plant_x, plant_y = cx - 3, cy
    if not np.any(pm):
        return (Tool.COALPOWER, plant_x, plant_y)

    # Find actual plant center (first plant tile region)
    plant_locs = np.argwhere(pm)
    if len(plant_locs) > 0:
        # Use approximate center of plant cluster
        py_c = int(plant_locs[:, 0].mean())
        px_c = int(plant_locs[:, 1].mean())
    else:
        py_c, px_c = plant_y, plant_x

    # --- Phase 1: Extend wire spine vertically from plant ---
    # Wire column at px_c+2, from cy-12 to cy+12
    wire_col = px_c + 2
    spine_rows = range(cy - 12, cy + 13)

    for row in spine_rows:
        if valid(wire_col, row) and not has(wm, wire_col, row) and not has(pm, wire_col, row):
            # Check if wire is connected: adjacent to plant or existing wire
            connected = (
                has(pm, wire_col - 1, row) or has(pm, wire_col + 1, row) or
                has(pm, wire_col, row - 1) or has(pm, wire_col, row + 1) or
                has(wm, wire_col, row - 1) or has(wm, wire_col, row + 1) or
                has(wm, wire_col - 1, row) or has(wm, wire_col + 1, row)
            )
            if connected:
                return (Tool.WIRE, wire_col, row)
            # If not connected yet, try connecting from plant
            if row == cy:
                # Place wire from plant rightward to wire_col
                for wx in range(px_c + 1, wire_col + 1):
                    if not has(wm, wx, cy) and not has(pm, wx, cy):
                        return (Tool.WIRE, wx, cy)

    # Ensure horizontal wire connector at cy from plant to wire_col
    for wx in range(px_c + 1, wire_col + 1):
        if not has(wm, wx, cy) and not has(pm, wx, cy):
            return (Tool.WIRE, wx, cy)

    # --- Phase 2: Road column adjacent to wire spine ---
    road_col = wire_col + 1
    for row in spine_rows:
        if valid(road_col, row) and not has(rm, road_col, row):
            return (Tool.ROAD, road_col, row)

    # --- Phase 3: Place residential zones to the right of road ---
    # Zones at road_col+2 (centers), every 3 rows
    res_col = road_col + 2
    for row in range(cy - 12, cy + 13, 3):
        if valid(res_col, row) and not has(res_m, res_col, row) and not has(pm, res_col, row):
            # Need power: wire nearby
            powered = any(is_powered_or_plant(res_col + dx, row + dy)
                         for dx in range(-1, 2) for dy in range(-1, 2))
            roaded = any(has(rm, res_col + dx, row + dy)
                        for dx in range(-2, 3) for dy in range(-2, 3))
            if powered or roaded:
                # Ensure wire reaches this zone: place wire horizontally
                # from wire_col to res_col-1
                for wx in range(wire_col + 1, res_col):
                    if not has(wm, wx, row) and not has(rm, wx, row):
                        return (Tool.WIRE, wx, row)
                return (Tool.RESIDENTIAL, res_col, row)

    # --- Phase 3b: Residential zones to the LEFT of wire spine ---
    # Wire horizontally left, road left, zones further left
    left_wire_col = wire_col - 1
    left_road_col = wire_col - 2
    left_res_col = wire_col - 4

    for row in range(cy - 12, cy + 13, 3):
        # Extend wire leftward at each zone row
        for wx in range(left_wire_col, left_wire_col - 3, -1):
            if valid(wx, row) and not has(wm, wx, row) and not has(pm, wx, row):
                if any(is_powered_or_plant(wx + dx, row) for dx in [1, -1]) or \
                   any(is_powered_or_plant(wx, row + dy) for dy in [1, -1]):
                    return (Tool.WIRE, wx, row)

    for row in range(cy - 12, cy + 13, 3):
        if valid(left_road_col, row) and not has(rm, left_road_col, row):
            return (Tool.ROAD, left_road_col, row)

    for row in range(cy - 12, cy + 13, 3):
        if valid(left_res_col, row) and not has(res_m, left_res_col, row) and not has(pm, left_res_col, row):
            powered = any(is_powered_or_plant(left_res_col + dx, row + dy)
                         for dx in range(-1, 2) for dy in range(-1, 2))
            if powered:
                return (Tool.RESIDENTIAL, left_res_col, row)

    # --- Phase 4: Commercial zones further right ---
    com_col = res_col + 3
    # Extend road to com_col
    for row in range(cy - 12, cy + 13, 6):
        if valid(road_col + 3, row) and not has(rm, road_col + 3, row):
            return (Tool.ROAD, road_col + 3, row)

    for row in range(cy - 9, cy + 10, 3):
        if valid(com_col, row) and not has(com_m, com_col, row) and not has(pm, com_col, row):
            powered = any(is_powered_or_plant(com_col + dx, row + dy)
                         for dx in range(-2, 3) for dy in range(-2, 3))
            if powered:
                # Place wire to reach com_col
                for wx in range(wire_col + 1, com_col):
                    if not has(wm, wx, row) and not has(rm, wx, row):
                        return (Tool.WIRE, wx, row)
                return (Tool.COMMERCIAL, com_col, row)

    # --- Phase 5: Industrial zones far left ---
    ind_col = left_res_col - 4
    for row in range(cy - 9, cy + 10, 3):
        if valid(ind_col, row) and not has(ind_m, ind_col, row) and not has(pm, ind_col, row):
            # Wire reach
            for wx in range(ind_col + 1, left_wire_col):
                if valid(wx, row) and not has(wm, wx, row) and not has(pm, wx, row):
                    return (Tool.WIRE, wx, row)
            powered = any(is_powered_or_plant(ind_col + dx, row + dy)
                         for dx in range(-1, 2) for dy in range(-1, 2))
            if powered:
                return (Tool.INDUSTRIAL, ind_col, row)

    # --- Phase 6: Second coal plant if population growing ---
    if obs.city_pop > 100:
        plant2_x, plant2_y = cx + 20, cy
        if not has(pm, plant2_x, plant2_y):
            # Wire from com_col to plant2
            for wx in range(com_col + 1, plant2_x):
                if valid(wx, cy) and not has(wm, wx, cy) and not has(pm, wx, cy):
                    return (Tool.WIRE, wx, cy)
            return (Tool.COALPOWER, plant2_x, plant2_y)

    # --- Phase 7: Extend spine further and add more zones reactively ---
    # Scan for unpowered zones and wire to them
    for y in range(WORLD_H):
        for x in range(WORLD_W):
            if has(res_m, x, y) or has(com_m, x, y) or has(ind_m, x, y):
                # Check if powered
                powered = any(is_powered_or_plant(x + dx, y + dy)
                             for dx in range(-1, 2) for dy in range(-1, 2))
                if not powered:
                    # Try to place wire adjacent toward wire_col
                    if x > wire_col:
                        return (Tool.WIRE, x - 1, y)
                    elif x < wire_col:
                        return (Tool.WIRE, x + 1, y)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder.
    Reads tile_map each step and decides next placement based on current state.
    Strategy:
    - Place coal power plant near center-left
    - Build horizontal wire spine from plant rightward
    - Build vertical wire branches from spine
    - Build two horizontal road rows parallel to spine
    - Place zones between/near roads with power access
    - Add services and second plant when population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # City anchor
    CX, CY = 40, 50

    # Step 1: Place coal power plant if none exists
    if not np.any(pm):
        return (Tool.COALPOWER, CX, CY)

    # Find plant center
    plant_ys, plant_xs = np.where(pm)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    # Counts
    res_ys, res_xs = np.where(resm)
    com_ys, com_xs = np.where(comm)
    ind_ys, ind_xs = np.where(indm)
    wire_ys, wire_xs = np.where(wm)
    road_ys, road_xs = np.where(rm)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    zone_ys = np.concatenate([res_ys, com_ys, ind_ys]) if total_zones > 0 else np.array([])
    zone_xs = np.concatenate([res_xs, com_xs, ind_xs]) if total_zones > 0 else np.array([])
    zone_set = set(zip(zone_ys.astype(int).tolist(), zone_xs.astype(int).tolist()))

    def pick_tool():
        t = max(total_zones, 1)
        if com_count / t < 0.22:
            return Tool.COMMERCIAL
        if ind_count / t < 0.22:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    # Wire spine parameters
    spine_y = py
    wire_end_x = min(px + 60, WORLD_W - 4)
    wire_start_x = px + 2

    # Step 2: Build horizontal wire spine from plant rightward
    # Find leftmost gap in spine
    for wx in range(wire_start_x, wire_end_x + 1):
        wy = spine_y
        if not in_bounds(wx, wy):
            break
        if bool(pm[wy, wx]):
            continue  # skip plant tiles
        if not bool(wm[wy, wx]):
            if bool(em[wy, wx]):
                return (Tool.WIRE, wx, wy)
            else:
                break  # blocked by something, stop spine here

    # Step 3: Vertical wire branches every 6 cols
    branch_cols = list(range(wire_start_x + 4, wire_end_x + 1, 6))
    for bx in branch_cols:
        if not in_bounds(bx, spine_y):
            continue
        # Only branch if spine wire exists here
        if not (bool(wm[spine_y, bx]) or bool(pm[spine_y, bx])):
            continue
        for sign in [-1, 1]:
            for dy in range(1, 10):
                wy = spine_y + sign * dy
                wx = bx
                if not in_bounds(wx, wy):
                    break
                if bool(pm[wy, wx]):
                    break
                if bool(wm[wy, wx]):
                    continue
                if bool(em[wy, wx]):
                    return (Tool.WIRE, wx, wy)
                break  # blocked

    # Road parameters
    road_top = spine_y - 3
    road_bot = spine_y + 3
    road_start = wire_start_x
    road_end = min(px + 58, WORLD_W - 4)

    # Step 4: Build top road row (find leftmost gap)
    for rx in range(road_start, road_end + 1):
        ry = road_top
        if not in_bounds(rx, ry):
            break
        if bool(pm[ry, rx]) or bool(wm[ry, rx]):
            continue
        if not bool(rm[ry, rx]):
            if bool(em[ry, rx]):
                return (Tool.ROAD, rx, ry)
            break

    # Step 5: Build bottom road row
    for rx in range(road_start, road_end + 1):
        ry = road_bot
        if not in_bounds(rx, ry):
            break
        if bool(pm[ry, rx]) or bool(wm[ry, rx]):
            continue
        if not bool(rm[ry, rx]):
            if bool(em[ry, rx]):
                return (Tool.ROAD, rx, ry)
            break

    # Step 6: Vertical connector roads every 6 cols
    for vc in range(road_start, road_end + 1, 6):
        for vr in range(road_top, road_bot + 1):
            if not in_bounds(vc, vr):
                continue
            if bool(pm[vr, vc]) or bool(wm[vr, vc]):
                continue
            if not bool(rm[vr, vc]):
                if bool(em[vr, vc]):
                    return (Tool.ROAD, vc, vr)

    # Step 7: Place zones near roads and wires
    # Build neighbor masks for road proximity (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Wire/power proximity (within 5 tiles)
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Candidate zone centers
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        step_hash = int(obs.step * 17 + int(obs.city_pop * 3)) % max(len(cxs), 1)
        for offset in range(min(len(cxs), 60)):
            k = (step_hash + offset * 11) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # Step 8: Second power plant when many zones
    if total_zones > 12 or obs.city_pop > 250:
        p2x = min(px + 55, WORLD_W - 6)
        p2y = py
        nearby_plant = False
        for dy in range(-7, 8):
            for dx in range(-7, 8):
                ny, nx2 = p2y + dy, p2x + dx
                if in_bounds(nx2, ny) and bool(pm[ny, nx2]):
                    nearby_plant = True
        if not nearby_plant and in_bounds(p2x, p2y) and bool(em[p2y, p2x]):
            return (Tool.COALPOWER, p2x, p2y)

    # Step 9: Wire from second plant back to first if second plant exists
    plant_count = int(np.any(pm))
    all_plant_ys, all_plant_xs = np.where(pm)
    if len(all_plant_xs) > 9:  # second plant exists (plant is 3x3=9 tiles)
        # Find rightmost plant area and wire toward it from spine
        rp_x = int(np.max(all_plant_xs))
        rp_y = int(np.mean(all_plant_ys[all_plant_xs == np.max(all_plant_xs)]))
        # Wire from wire_end_x to second plant
        for wx2 in range(wire_end_x, rp_x - 2):
            wy2 = spine_y
            if not in_bounds(wx2, wy2):
                break
            if bool(pm[wy2, wx2]):
                break
            if not bool(wm[wy2, wx2]) and bool(em[wy2, wx2]):
                return (Tool.WIRE, wx2, wy2)

    # Step 10: Services
    if obs.city_pop > 150:
        fx, fy = px + 6, py - 10
        if in_bounds(fx, fy) and bool(em[fy, fx]):
            return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 200:
        fx2, fy2 = px + 6, py + 10
        if in_bounds(fx2, fy2) and bool(em[fy2, fx2]):
            return (Tool.POLICESTATION, fx2, fy2)

    # Step 11: Extend roads from road frontier
    if len(road_xs) > 0:
        step_k = int(obs.step * 13) % max(len(road_xs), 1)
        rx_s = int(road_xs[step_k])
        ry_s = int(road_ys[step_k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx_s + dx2, ry_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # Step 12: Extend wires from wire frontier
    if len(wire_xs) > 0:
        step_k2 = int(obs.step * 7) % max(len(wire_xs), 1)
        wx_s = int(wire_xs[step_k2])
        wy_s = int(wire_ys[step_k2])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = wx_s + dx2, wy_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Redesigned policy:
    - Single compact cluster centered at (60, 50)
    - Coal power plant placed first, adjacent zones get power
    - Grid road layout: roads every 4 tiles in both directions
    - Zones placed at intersections of road grid
    - Wire runs along roads to distribute power
    - Mix: 40% res, 30% com, 30% ind
    """
    tm = obs.tile_map
    step = obs.step

    # Initialize state
    if 'phase' not in state:
        state['phase'] = 0
        state['action_queue'] = []

    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_pos = list(zip(*np.where(res_mask(tm)))) if np.any(res_mask(tm)) else []
    com_pos = list(zip(*np.where(com_mask(tm)))) if np.any(com_mask(tm)) else []
    ind_pos = list(zip(*np.where(ind_mask(tm)))) if np.any(ind_mask(tm)) else []

    res_count = len(res_pos)
    com_count = len(com_pos)
    ind_count = len(ind_pos)
    total_zones = res_count + com_count + ind_count + 1

    # Center of city
    cx, cy = 60, 50

    # Power plant at (cx-12, cy) - left of cluster
    plant_x, plant_y = cx - 12, cy

    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def pick_zone_type():
        # 40% res, 30% com, 30% ind
        if com_count / total_zones < 0.30:
            return Tool.COMMERCIAL
        elif ind_count / total_zones < 0.30:
            return Tool.INDUSTRIAL
        else:
            return Tool.RESIDENTIAL

    # Phase 0: Place coal power plant
    if not np.any(pm):
        return (Tool.COALPOWER, plant_x, plant_y)

    # Phase 1: Build horizontal wire spine from plant rightward
    # Spine at row cy, from plant_x+2 to cx+18
    spine_row = cy
    spine_start = plant_x + 3
    spine_end = cx + 18

    # Check current wire extent on spine row
    wire_cols_on_spine = [c for (r, c) in zip(*np.where(wm)) if r == spine_row] if np.any(wm) else []
    if wire_cols_on_spine:
        max_wc = max(wire_cols_on_spine)
    else:
        max_wc = spine_start - 1

    if max_wc < spine_end:
        nc = max_wc + 1
        if 0 <= nc < WORLD_W:
            return (Tool.WIRE, nc, spine_row)

    # Phase 2: Build horizontal roads above and below spine
    # Roads at cy-4, cy-8, cy+4, cy+8
    road_rows = [cy - 4, cy - 8, cy + 4, cy + 8]
    road_start = plant_x + 2
    road_end = cx + 18

    road_positions = list(zip(*np.where(rm))) if np.any(rm) else []

    for rrow in road_rows:
        if 0 <= rrow < WORLD_H:
            road_cols_here = [c for (r, c) in road_positions if r == rrow]
            if road_cols_here:
                max_rc = max(road_cols_here)
            else:
                max_rc = road_start - 1
            if max_rc < road_end:
                nc = max_rc + 1
                if 0 <= nc < WORLD_W:
                    return (Tool.ROAD, nc, rrow)

    # Phase 3: Build vertical roads connecting road rows
    # Vertical roads at x intervals: every 6 cols from road_start to road_end
    vert_cols = list(range(road_start, road_end + 1, 6))
    all_road_rows = [cy - 8, cy - 4, cy, cy + 4, cy + 8]  # cy uses wire but also add road on top

    for vc in vert_cols:
        for vr in range(cy - 8, cy + 9):
            if 0 <= vr < WORLD_H and 0 <= vc < WORLD_W:
                if not rm[vr, vc] and not wm[vr, vc]:
                    if em[vr, vc]:
                        return (Tool.ROAD, vc, vr)

    # Phase 4: Add vertical wires from spine to zone rows (for power)
    # Wire branches at zone columns
    zone_rows = [cy - 6, cy - 10, cy + 6, cy + 10]
    zone_cols = list(range(plant_x + 4, cx + 19, 6))

    for zc in zone_cols:
        if 0 <= zc < WORLD_W:
            # Upward wires from spine
            for wr in range(spine_row - 1, cy - 12, -1):
                if 0 <= wr < WORLD_H:
                    if not wm[wr, zc] and not rm[wr, zc] and em[wr, zc]:
                        return (Tool.WIRE, zc, wr)
                    elif not em[wr, zc] and not wm[wr, zc]:
                        break
            # Downward wires from spine
            for wr in range(spine_row + 1, cy + 13):
                if 0 <= wr < WORLD_H:
                    if not wm[wr, zc] and not rm[wr, zc] and em[wr, zc]:
                        return (Tool.WIRE, zc, wr)
                    elif not em[wr, zc] and not wm[wr, zc]:
                        break

    # Phase 5: Place zones
    # Zone centers: between road rows, at zone cols
    # zone rows: cy-6, cy-10, cy+6, cy+10
    all_zone_rows = [cy - 6, cy - 10, cy + 6, cy + 10]

    all_zones = res_pos + com_pos + ind_pos

    for zr in all_zone_rows:
        for zc in zone_cols:
            if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                # Check not already placed nearby
                already = any(
                    abs(zr - pr) <= 2 and abs(zc - pc) <= 2
                    for (pr, pc) in all_zones
                )
                if not already and zone_area_free(zr, zc):
                    # Check road access (within 5 tiles)
                    road_near = any(
                        abs(zr - rr) <= 5 and abs(zc - rc) <= 5
                        for (rr, rc) in road_positions
                    )
                    wire_near = (
                        np.any(wm[max(0, zr-5):min(WORLD_H, zr+6), max(0, zc-5):min(WORLD_W, zc+6)])
                    )
                    if road_near and wire_near:
                        return (pick_zone_type(), zc, zr)

    # Phase 6: Expand with more zones if population growing
    if obs.city_pop > 50:
        extra_rows = [cy - 14, cy + 14]
        extra_cols = zone_cols
