    if not has_tile(pm, plant2_x, plant2_y):
        return (Tool.COALPOWER, plant2_x, plant2_y)

    # Phase 1: wire along row cy (the horizontal spine)
    for dx in SPINE_RANGE_X:
        if not has_tile(wm, dx, cy) and not has_tile(pm, dx, cy):
            return (Tool.WIRE, dx, cy)

    # Phase 2: road along row cy-1 (above wire, zones go above this)
    for dx in SPINE_RANGE_X:
        if not has_tile(rm_road, dx, cy - 1):
            return (Tool.ROAD, dx, cy - 1)

    # Phase 3: road along row cy+1 (below wire, zones go below this)
    for dx in SPINE_RANGE_X:
        if not has_tile(rm_road, dx, cy + 1):
            return (Tool.ROAD, dx, cy + 1)

    # Phase 4: place zones above the upper road (centered at cy-4)
    # Residential, commercial, industrial rotating every 3 cols
    zone_row_above = cy - 4
    zone_row_below = cy + 4
    for dx in range(cx - 18, cx + 19, 3):
        if 0 <= dx < WORLD_W and 0 <= zone_row_above < WORLD_H:
            idx = (dx - (cx - 18)) // 3
            if idx % 3 == 0:
                tool, mask = Tool.RESIDENTIAL, res_m
            elif idx % 3 == 1:
                tool, mask = Tool.COMMERCIAL, com_m
            else:
                tool, mask = Tool.INDUSTRIAL, ind_m
            if not has_tile(mask, dx, zone_row_above) and not has_tile(pm, dx, zone_row_above):
                # Check road nearby
                if has_tile(rm_road, dx, cy - 1):
                    return (tool, dx, zone_row_above)

    # Phase 5: place zones below the lower road (centered at cy+4)
    for dx in range(cx - 18, cx + 19, 3):
        if 0 <= dx < WORLD_W and 0 <= zone_row_below < WORLD_H:
            idx = (dx - (cx - 18)) // 3
            # Shift pattern so it's different from above
            if idx % 3 == 0:
                tool, mask = Tool.COMMERCIAL, com_m
            elif idx % 3 == 1:
                tool, mask = Tool.RESIDENTIAL, res_m
            else:
                tool, mask = Tool.INDUSTRIAL, ind_m
            if not has_tile(mask, dx, zone_row_below) and not has_tile(pm, dx, zone_row_below):
                if has_tile(rm_road, dx, cy + 1):
                    return (tool, dx, zone_row_below)

    # Phase 6: second tier - wire rows cy-7 and cy+7, road cy-8/cy+8, more zones
    wire_row_up2 = cy - 7
    road_row_up2 = cy - 8
    zone_row_up2 = cy - 11

    wire_row_dn2 = cy + 7
    road_row_dn2 = cy + 8
    zone_row_dn2 = cy + 11

    # Vertical wires connecting spine to second tier (at zone centers)
    for dx in range(cx - 18, cx + 19, 3):
        if 0 <= dx < WORLD_W:
            # Connect up
            for wy in range(cy - 1, wire_row_up2 - 1, -1):
                if not has_tile(wm, dx, wy) and not has_tile(pm, dx, wy) and not has_tile(rm_road, dx, wy):
                    return (Tool.WIRE, dx, wy)
            # Connect down
            for wy in range(cy + 1, wire_row_dn2 + 2):
