    for dx in SPINE_RANGE_X:
        if not has_tile(rm_road, dx, road_row_dn2):
            return (Tool.ROAD, dx, road_row_dn2)

    # Second tier zones
    for dx in range(cx - 18, cx + 19, 3):
        if 0 <= dx < WORLD_W and 0 <= zone_row_up2 < WORLD_H:
            idx = (dx - (cx - 18)) // 3
            if idx % 3 == 0:
                tool, mask = Tool.RESIDENTIAL, res_m
            elif idx % 3 == 1:
                tool, mask = Tool.RESIDENTIAL, res_m
            else:
                tool, mask = Tool.COMMERCIAL, com_m
            if not has_tile(mask, dx, zone_row_up2) and not has_tile(pm, dx, zone_row_up2):
                if has_tile(rm_road, dx, road_row_up2):
                    return (tool, dx, zone_row_up2)

    for dx in range(cx - 18, cx + 19, 3):
        if 0 <= dx < WORLD_W and 0 <= zone_row_dn2 < WORLD_H:
            idx = (dx - (cx - 18)) // 3
            if idx % 3 == 0:
                tool, mask = Tool.RESIDENTIAL, res_m
