            if not has_tile(wm, cx, wy) and not has_tile(pm, cx, wy) and not has_tile(rm_road, cx, wy):
                return (Tool.WIRE, cx, wy)
        return (Tool.COALPOWER, cx, cy - 15)

    return None

def act(obs, state):
    """
    Improved policy with:
    - Two power plants for better coverage
    - Horizontal road spine instead of vertical wire spine
    - Mixed zones in a grid pattern (RES/COM/IND balanced)
    - Two separate neighborhoods (left and right clusters)
    """
    tm = obs.tile_map
    step = obs.step

    # Use two cluster centers
    # Left cluster around (30, 50), right cluster around (85, 50)
    clusters = [
        {'cx': 30, 'cy': 50},
        {'cx': 85, 'cy': 50},
    ]

    em = empty_mask(tm)
    rm = road_mask(tm)
    wm = wire_mask(tm)
    pm = plant_mask(tm)

    has_plant = np.any(pm)
    plant_positions = list(zip(*np.where(pm)))

    res_count = np.sum(res_mask(tm))
    com_count = np.sum(com_mask(tm))
    ind_count = np.sum(ind_mask(tm))

    # Build a plan queue in state
    if 'plan' not in state:
        plan = []
        for cl in clusters:
            cx, cy = cl['cx'], cl['cy']
            # Place coal power plant to the left of each cluster
            plan.append((Tool.COALPOWER, cx - 8, cy))
            # Wire from plant right edge to cluster
            for wc in range(cx - 5, cx + 10):
                plan.append((Tool.WIRE, wc, cy))
            # Horizontal road spine at cy-1 and cy+1
            for rc in range(cx - 5, cx + 12):
                plan.append((Tool.ROAD, rc, cy - 1))
                plan.append((Tool.ROAD, rc, cy + 1))
            # Vertical roads every 4 cols to connect horizontal spines
            for rc in range(cx - 4, cx + 12, 4):
                for rr in range(cy - 8, cy + 9):
                    plan.append((Tool.ROAD, rc, rr))
            # Wire extensions vertical to power zones
            for wc in range(cx - 5, cx + 10, 2):
                for wr in range(cy - 8, cy + 9):
                    plan.append((Tool.WIRE, wc, wr))

        # Zone placement in grid around each cluster
        for cl in clusters:
            cx, cy = cl['cx'], cl['cy']
            zone_idx = 0
            for zr in range(cy - 9, cy + 10, 3):
                for zc in range(cx - 3, cx + 10, 4):
                    # Mix zones: RES dominant, some COM and IND
                    mod = zone_idx % 5
                    if mod in (0, 1, 2):
                        tool = Tool.RESIDENTIAL
                    elif mod == 3:
                        tool = Tool.COMMERCIAL
                    else:
                        tool = Tool.INDUSTRIAL
                    plan.append((tool, zc, zr))
                    zone_idx += 1

        # Additional wire runs connecting the two clusters
        mid_y = 50
        for wc in range(35, 80):
            plan.append((Tool.WIRE, wc, mid_y))
            plan.append((Tool.ROAD, wc, mid_y - 1))

        state['plan'] = plan
        state['idx'] = 0

    idx = state.get('idx', 0)
    plan = state['plan']

    def zone_area_clear(cr, cc, tm_local):
        """Check if 3x3 zone area is safe to place (empty or already same type)."""
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
        return True

    # Execute plan steps, skip if already placed
    while idx < len(plan):
        tool, x, y = plan[idx]
        idx += 1
        state['idx'] = idx

        # Clamp coords
        x = max(0, min(WORLD_W - 1, x))
        y = max(0, min(WORLD_H - 1, y))

        # Skip if it's a zone and area not clear enough
        if tool in (Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.INDUSTRIAL):
            if not zone_area_clear(y, x, tm):
                continue
            # Skip if already a zone nearby
            res_pos = list(zip(*np.where(res_mask(tm)))) if np.any(res_mask(tm)) else []
            com_pos = list(zip(*np.where(com_mask(tm)))) if np.any(com_mask(tm)) else []
            ind_pos = list(zip(*np.where(ind_mask(tm)))) if np.any(ind_mask(tm)) else []
            all_zones = res_pos + com_pos + ind_pos
            if any(abs(y - zr) <= 1 and abs(x - zc) <= 1 for (zr, zc) in all_zones):
                continue

        # Skip wires on power plant tiles
        if tool == Tool.WIRE and np.any(pm):
            if any(abs(y - pr) <= 2 and abs(x - pc) <= 2 for (pr, pc) in plant_positions):
                continue

        return (tool, x, y)

    # Fallback: reactive zone placement if plan exhausted
    # Try to fill gaps near roads with residential zones
    road_pos = list(zip(*np.where(rm)))
    if road_pos:
        for rr, rc in road_pos[::3]:
            for dz in [(-3, 0), (3, 0), (0, -3), (0, 3)]:
                zr, zc = rr + dz[0], rc + dz[1]
                if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                    if zone_area_clear(zr, zc, tm):
                        res_pos = list(zip(*np.where(res_mask(tm)))) if np.any(res_mask(tm)) else []
                        if not any(abs(zr - pr) <= 1 and abs(zc - pc) <= 1 for (pr, pc) in res_pos):
                            tool = Tool.RESIDENTIAL
                            if com_count < res_count // 3:
                                tool = Tool.COMMERCIAL
                            elif ind_count < res_count // 4:
                                tool = Tool.INDUSTRIAL
                            return (tool, zc, zr)

    return None

