    res_m = res_mask(obs.tile_map)
    com_m = com_mask(obs.tile_map)
    ind_m = ind_mask(obs.tile_map)

    def already_placed(tool, x, y):
        if not (0 <= x < WORLD_W and 0 <= y < WORLD_H):
            return True  # skip out of bounds
        if tool == Tool.COALPOWER:
            return bool(pm[y, x])
        if tool == Tool.ROAD:
            return bool(rm_road[y, x])
        if tool == Tool.WIRE:
            return bool(wm[y, x]) or bool(rm_road[y, x]) or bool(pm[y, x])
        if tool == Tool.RESIDENTIAL:
