    """
    tm = obs.tile_map
    step = obs.step

    # Initialize state
    if 'phase' not in state:
        state['phase'] = 'plant'
        state['queue'] = []
        state['built'] = set()

    # Use center-left area for main cluster
    CX, CY = 55, 50

    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    has_plant = np.any(pm)
    wire_pos = set(zip(*np.where(wm))) if np.any(wm) else set()
    road_pos = set(zip(*np.where(rm))) if np.any(rm) else set()
    zone_pos = set(zip(*np.where(resm | comm | indm)))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # --- Build plan generation ---
    # We'll build a grid:
    # Power plant at (CX-12, CY)
    # Wire spine along CY from plant rightward
    # Roads at CY-4, CY+4 (horizontal)
    # Vertical roads every 6 cols
    # Zones in the blocks between roads

    PLANT_X, PLANT_Y = CX - 12, CY
    SPINE_ROW = CY
    ROAD_ABOVE = CY - 4
    ROAD_BELOW = CY + 4
    # Second row of zones further out
    ROAD_ABOVE2 = CY - 10
    ROAD_BELOW2 = CY + 10

    COL_START = CX - 6
    COL_END = CX + 36

    def pick_tool(idx):
        # Pattern: RRC RIC RCC repeating => more residential but good com/ind mix
        pattern = [Tool.RESIDENTIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL,
                   Tool.RESIDENTIAL, Tool.INDUSTRIAL, Tool.COMMERCIAL]
        return pattern[idx % len(pattern)]

    def has_road_nearby(zy, zx, r=4):
        for dr in range(-r, r+1):
            for dc in range(-r, r+1):
                rr, rc = zy+dr, zx+dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if (rr, rc) in road_pos:
                        return True
        return False

    def has_power_nearby(zy, zx, r=6):
        for dr in range(-r, r+1):
            for dc in range(-r, r+1):
                rr, rc = zy+dr, zx+dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if (rr, rc) in wire_pos or pm[rr, rc]:
                        return True
        return False

    def zone_placeable(zy, zx):
        if not (2 <= zy <= WORLD_H-3 and 2 <= zx <= WORLD_W-3):
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zy+dr, zx+dc
                if pm[rr, rc]:
                    return False
                if rm[rr, rc]:
                    return False
        return True

    # Phase 1: Power plant
    if not has_plant:
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    # Phase 2: Wire spine along SPINE_ROW from plant to COL_END+2
    # Plant center is PLANT_X, PLANT_Y; right edge is PLANT_X+1
    wire_start_col = PLANT_X + 2
    wire_end_col = COL_END + 2

    # Extend wire rightward along spine
    spine_wires = sorted([c for (r, c) in wire_pos if r == SPINE_ROW])
    max_spine_wire = max(spine_wires) if spine_wires else (PLANT_X + 1)

    if max_spine_wire < wire_end_col:
        nc = max_spine_wire + 1
        if 0 <= nc < WORLD_W and not pm[SPINE_ROW, nc]:
            if not rm[SPINE_ROW, nc]:  # don't overwrite roads
                return (Tool.WIRE, nc, SPINE_ROW)

    # Phase 3: Vertical wires at each zone column (every 6 cols) connecting spine to road rows
    zone_cols = list(range(COL_START, COL_END + 1, 6))

    for bc in zone_cols:
        if not (0 <= bc < WORLD_W):
            continue
        if (SPINE_ROW, bc) not in wire_pos:
            continue
        # Extend wire up to ROAD_ABOVE - 1 (so wire reaches zone above road)
        for wr in range(SPINE_ROW - 1, ROAD_ABOVE - 2, -1):
            if wr < 0:
                break
            if (wr, bc) in wire_pos:
                continue
            if pm[wr, bc] or rm[wr, bc]:
                break
            return (Tool.WIRE, bc, wr)
        # Extend wire down to ROAD_BELOW + 1
        for wr in range(SPINE_ROW + 1, ROAD_BELOW + 2):
            if wr >= WORLD_H:
                break
            if (wr, bc) in wire_pos:
                continue
            if pm[wr, bc] or rm[wr, bc]:
                break
            return (Tool.WIRE, bc, wr)

    # Phase 4: Horizontal roads (ROAD_ABOVE and ROAD_BELOW)
    road_col_start = COL_START - 3
    road_col_end = COL_END + 3

    for rrow in [ROAD_ABOVE, ROAD_BELOW, ROAD_ABOVE2, ROAD_BELOW2]:
        if not (0 <= rrow < WORLD_H):
            continue
        row_roads = sorted([c for (r, c) in road_pos if r == rrow])
        max_rc = max(row_roads) if row_roads else road_col_start - 1
        if max_rc < road_col_end:
            nc = max_rc + 1
            if 0 <= nc < WORLD_W and not pm[rrow, nc]:
                return (Tool.ROAD, nc, rrow)

    # Phase 5: Vertical connector roads at zone columns
    for vc in zone_cols:
        if not (0 <= vc < WORLD_W):
            continue
        for vr in range(ROAD_ABOVE2, ROAD_BELOW2 + 1):
            if not (0 <= vr < WORLD_H):
                continue
            if (vr, vc) not in road_pos and not pm[vr, vc] and not wm[vr, vc]:
                return (Tool.ROAD, vc, vr)

    # Phase 6: Place zones in blocks between roads
    # Inner blocks: between ROAD_ABOVE and ROAD_BELOW (zone rows: ROAD_ABOVE-2, ROAD_BELOW+2... wait)
    # Actually zones go OUTSIDE the roads:
    # Above ROAD_ABOVE: zone centers at ROAD_ABOVE-2, ROAD_ABOVE-5
    # Below ROAD_BELOW: zone centers at ROAD_BELOW+2, ROAD_BELOW+5
    # Also second band:
    zone_rows = [
        ROAD_ABOVE - 2,   # just above inner road
        ROAD_ABOVE - 5,   # second row above
        ROAD_BELOW + 2,   # just below inner road
        ROAD_BELOW + 5,   # second row below
        ROAD_ABOVE2 - 2,  # above outer road
        ROAD_BELOW2 + 2,  # below outer road
    ]

    zone_idx = 0
    for zr in zone_rows:
        for zc in zone_cols:
            if not (2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3):
                zone_idx += 1
                continue
            # Check if already a zone nearby (within 3 tiles)
            already = any(abs(zr - zy) < 3 and abs(zc - zx) < 3 
                         for (zy, zx) in zone_pos)
            if not already and zone_placeable(zr, zc):
                if has_road_nearby(zr, zc, r=4) and has_power_nearby(zr, zc, r=6):
                    tool = pick_tool(zone_idx)
                    return (tool, zc, zr)
            zone_idx += 1

    # Phase 7: Second power plant if population growing
    if obs.city_pop > 100:
        PLANT2_X, PLANT2_Y = CX + 28, CY
        if not pm[PLANT2_Y, PLANT2_X]:
            # Check area is not occupied by important things
            can_place = True
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    rr, rc = PLANT2_Y + dr, PLANT2_X + dc
                    if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                        if rm[rr, rc] or (resm | comm | indm)[rr, rc]:
                            can_place = False
            if can_place:
                return (Tool.COALPOWER, PLANT2_X, PLANT2_Y)

    # Phase 8: Wire from second plant along spine if it exists
    plant_tiles = list(zip(*np.where(pm))) if has_plant else []
    if len(plant_tiles) > 9:  # second plant exists (each plant ~9 tiles)
        # Extend wire further right
        if max_spine_wire < wire_end_col + 10:
            nc = max_spine_wire + 1
            if 0 <= nc < WORLD_W and not pm[SPINE_ROW, nc] and not rm[SPINE_ROW, nc]:
                return (Tool.WIRE, nc, SPINE_ROW)

    # Phase 9: Extra wire coverage for unpowered zones
    for (zy, zx) in list(zone_pos)[:30]:
        if not has_power_nearby(zy, zx, r=3):
            # Find closest wire
            if wire_pos:
                cw = min(wire_pos, key=lambda p: abs(p[0]-zy)+abs(p[1]-zx))
                wr, wc = cw
                # Step toward zone
                nr = wr + (1 if zy > wr else -1 if zy < wr else 0)
                nc = wc + (1 if zx > wc else -1 if zx < wc else 0)
                if 0 <= nr < WORLD_H and 0 <= nc < WORLD_W:
                    if em[nr, nc] and not pm[nr, nc] and not rm[nr, nc]:
                        return (Tool.WIRE, nc, nr)

    # Phase 10: Add more zone columns if budget allows
    extra_cols = list(range(COL_END + 6, COL_END + 25, 6))
    for zc in extra_cols:
        if not (2 <= zc <= WORLD_W - 3):
            continue
        for zr in [ROAD_ABOVE - 2, ROAD_BELOW + 2]:
            if not (2 <= zr <= WORLD_H - 3):
                continue
            already = any(abs(zr - zy) < 3 and abs(zc - zx) < 3 
                         for (zy, zx) in zone_pos)
            if not already and zone_placeable(zr, zc):
                if has_road_nearby(zr, zc, r=5) and has_power_nearby(zr, zc, r=8):
                    return (pick_tool(zone_idx), zc, zr)
            zone_idx += 1

    return None

def act(obs, state):
    """
    Closed-loop policy: reads the map each step and decides the next placement
    based on what is actually observed. Uses a simple phase counter in state.

    Layout:
    - One coal power plant at (20, 50)
    - Wire spine going right from plant along row 50
    - Road at row 48 and row 52 (parallel, for zone access)
    - Zones placed in rows 45, 42, 39, 55, 58, 61 centered on zone columns
    - Vertical wires branch off spine to reach zone rows
    - Vertical roads connect road spines
    """
    tm = obs.tile_map
    step = obs.step

    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    # Cluster parameters
    plant_x, plant_y = 18, 50
    spine_row = 50
    road_row_n = 48  # north road
    road_row_s = 52  # south road
    spine_start = plant_x + 3  # first wire col after plant (plant is 3x3)
    spine_end = 110

    # Zone columns: every 6 cols starting from spine_start+3
    zone_cols = list(range(spine_start + 3, spine_end - 2, 6))

    # Zone rows (above and below roads)
    zone_rows_n = [45, 42, 39, 36]
    zone_rows_s = [55, 58, 61, 64]

    # --- Helper: is a 3x3 zone area clear? ---
    def zone_area_free(cy, cx):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cy + dr, cx + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    # --- Pick zone type based on current counts ---
    def pick_zone(cy, cx):
        rc = int(np.sum(resm))
        cc = int(np.sum(comm))
        ic = int(np.sum(indm))
        total = rc + cc + ic + 1
        if cc / total < 0.20:
            return Tool.COMMERCIAL
        elif ic / total < 0.20:
            return Tool.INDUSTRIAL
        else:
            return Tool.RESIDENTIAL

    # --- Check if a tile has wire or plant nearby (within manhattan 3) ---
    def powered_nearby(cy, cx, radius=5):
        r0 = max(0, cy - radius)
        r1 = min(WORLD_H, cy + radius + 1)
        c0 = max(0, cx - radius)
        c1 = min(WORLD_W, cx + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def road_nearby(cy, cx, radius=3):
        r0 = max(0, cy - radius)
        r1 = min(WORLD_H, cy + radius + 1)
        c0 = max(0, cx - radius)
        c1 = min(WORLD_W, cx + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    # ============================================================
    # PHASE 1: Place coal power plant if missing
    # ============================================================
    if not np.any(pm):
        return (Tool.COALPOWER, plant_x, plant_y)

    # ============================================================
    # PHASE 2: Extend wire spine rightward from plant
    # Find current rightmost wire on spine_row
    # ============================================================
    spine_wire_cols = [c for c in range(WORLD_W) if wm[spine_row, c]]
    plant_cols = [c for c in range(WORLD_W) if pm[spine_row, c]]

    if spine_wire_cols:
        max_wire_col = max(spine_wire_cols)
    elif plant_cols:
        max_wire_col = max(plant_cols)  # start from plant
    else:
        max_wire_col = spine_start - 1

    if max_wire_col < spine_end:
        next_col = max_wire_col + 1
        # Don't overwrite plant
        if not pm[spine_row, next_col]:
            return (Tool.WIRE, next_col, spine_row)

    # ============================================================
    # PHASE 3: Extend north road (road_row_n) rightward
    # ============================================================
    road_n_cols = [c for c in range(WORLD_W) if rm[road_row_n, c]]
    if road_n_cols:
        max_rn = max(road_n_cols)
    else:
        max_rn = spine_start - 1

    if max_rn < spine_end:
        nc = max_rn + 1
        if 0 <= nc < WORLD_W:
            return (Tool.ROAD, nc, road_row_n)

    # ============================================================
    # PHASE 4: Extend south road (road_row_s) rightward
    # ============================================================
    road_s_cols = [c for c in range(WORLD_W) if rm[road_row_s, c]]
    if road_s_cols:
        max_rs = max(road_s_cols)
    else:
        max_rs = spine_start - 1

    if max_rs < spine_end:
        nc = max_rs + 1
        if 0 <= nc < WORLD_W:
            return (Tool.ROAD, nc, road_row_s)

    # ============================================================
    # PHASE 5: Add vertical wire branches from spine to zone rows
    # For each zone column, run wire from spine_row toward zone rows
    # ============================================================
    for zc in zone_cols:
        if not (0 <= zc < WORLD_W):
            continue
        # Only branch if wire exists at this column on spine
        if not wm[spine_row, zc]:
            continue
        # North branch: wire from spine_row-1 up to zone_rows_n[-1]-1
        for wr in range(spine_row - 1, zone_rows_n[-1] - 1, -1):
            if wr < 0:
                break
            if wm[wr, zc] or pm[wr, zc]:
                continue
            if rm[wr, zc]:
                break  # road blocks wire path; stop here
            if em[wr, zc]:
                return (Tool.WIRE, zc, wr)
            break
        # South branch: wire from spine_row+1 down to zone_rows_s[-1]+1
        for wr in range(spine_row + 1, zone_rows_s[-1] + 2):
            if wr >= WORLD_H:
                break
            if wm[wr, zc] or pm[wr, zc]:
                continue
            if rm[wr, zc]:
                break
            if em[wr, zc]:
                return (Tool.WIRE, zc, wr)
            break

    # ============================================================
    # PHASE 6: Place zones adjacent to roads and powered by wire
    # ============================================================
    all_zone_rows = zone_rows_n + zone_rows_s
    for zr in all_zone_rows:
        for zc in zone_cols:
            if not (0 <= zr < WORLD_H and 0 <= zc < WORLD_W):
                continue
            # Skip if already a zone nearby
            already = (
                np.any(resm[max(0,zr-2):min(WORLD_H,zr+3), max(0,zc-2):min(WORLD_W,zc+3)]) or
                np.any(comm[max(0,zr-2):min(WORLD_H,zr+3), max(0,zc-2):min(WORLD_W,zc+3)]) or
                np.any(indm[max(0,zr-2):min(WORLD_H,zr+3), max(0,zc-2):min(WORLD_W,zc+3)])
            )
            if already:
                continue
            if not zone_area_free(zr, zc):
                continue
            if not powered_nearby(zr, zc, 6):
                continue
            if not road_nearby(zr, zc, 4):
                continue
            return (pick_zone(zr, zc), zc, zr)

    # ============================================================
    # PHASE 7: Add vertical connector roads between road_row_n and road_row_s
    # at zone columns to improve connectivity
    # ============================================================
    for zc in zone_cols:
        for conn_row in range(road_row_n, road_row_s + 1):
            if 0 <= conn_row < WORLD_H and 0 <= zc < WORLD_W:
                if not rm[conn_row, zc] and not pm[conn_row, zc]:
                    if em[conn_row, zc]:
                        return (Tool.ROAD, zc, conn_row)

    # ============================================================
    # PHASE 8: Expand zone rows further if population growing
    # ============================================================
    if obs.city_pop > 50:
        extra_rows_n = [33, 30, 27]
        extra_rows_s = [67, 70, 73]
        for zr in extra_rows_n + extra_rows_s:
            for zc in zone_cols:
                if not (0 <= zr < WORLD_H and 0 <= zc < WORLD_W):
                    continue
                already = (
                    np.any(resm[max(0,zr-2):min(WORLD_H,zr+3), max(0,zc-2):min(WORLD_W,zc+3)]) or
                    np.any(comm[max(0,zr-2):min(WORLD_H,zr+3), max(0,zc-2):min(WORLD_W,zc+3)]) or
                    np.any(indm[max(0,zr-2):min(WORLD_H,zr+3), max(0,zc-2):min(WORLD_W,zc+3)])
                )
                if already:
                    continue
                if not zone_area_free(zr, zc):
                    continue
                if road_nearby(zr, zc, 4) and powered_nearby(zr, zc, 6):
                    return (pick_zone(zr, zc), zc, zr)
                # Add road toward these zones
                if powered_nearby(zr, zc, 6):
                    # Try to build road from nearest road row
                    if zr < road_row_n:
                        for rr in range(road_row_n - 1, zr - 1, -1):
                            if not rm[rr, zc] and em[rr, zc]:
                                return (Tool.ROAD, zc, rr)
                            elif rm[rr, zc]:
                                break
                    elif zr > road_row_s:
                        for rr in range(road_row_s + 1, zr + 2):
                            if not rm[rr, zc] and em[rr, zc]:
                                return (Tool.ROAD, zc, rr)
                            elif rm[rr, zc]:
                                break

    # ============================================================
    # PHASE 9: Lay additional wires toward unpowered zones
    # ============================================================
    res_pos = list(zip(*np.where(resm))) if np.any(resm) else []
    com_pos = list(zip(*np.where(comm))) if np.any(comm) else []
    ind_pos = list(zip(*np.where(indm))) if np.any(indm) else []
    all_zones = res_pos + com_pos + ind_pos

    for (zr, zc) in all_zones:
        if not powered_nearby(zr, zc, 4):
            # Find nearest wire and try to extend toward zone
            wire_ys, wire_xs = np.where(wm)
            if len(wire_xs) == 0:
                continue
            dists = np.abs(wire_ys - zr) + np.abs(wire_xs - zc)
            idx = np.argmin(dists)
            wy, wx = wire_ys[idx], wire_xs[idx]
            # Step one tile toward zone
            dy = np.sign(zr - wy)
            dx = np.sign(zc - wx)
            if dy != 0:
                ny, nx = wy + dy, wx
            else:
                ny, nx = wy, wx + dx
            if 0 <= ny < WORLD_H and 0 <= nx < WORLD_W:
                if em[ny, nx] and not rm[ny, nx]:
                    return (Tool.WIRE, nx, ny)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder.
    Reads tile_map every step and decides next action based on current state.

    Strategy:
    1. Place coal power plant at fixed anchor
    2. Extend wires outward from plant/existing wires toward road network
    3. Build a road grid in a compact cluster
    4. Place zones (R/C/I) adjacent to roads with wire access
    5. Add services when population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    # Cluster anchor - plant goes here
    PLANT_X, PLANT_Y = 30, 50

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Phase 1: Place power plant ---
    has_plant = np.any(pm)
    if not has_plant:
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    # Find plant center
    plant_ys, plant_xs = np.where(pm)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    # Current network state
    wire_ys, wire_xs = np.where(wm)
    road_ys, road_xs = np.where(rm)
    res_ys, res_xs = np.where(resm)
    com_ys, com_xs = np.where(comm)
    ind_ys, ind_xs = np.where(indm)

    wire_set = set(zip(wire_ys.tolist(), wire_xs.tolist()))
    road_set = set(zip(road_ys.tolist(), road_xs.tolist()))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def is_powered(x, y, r=5):
        """Check if (x,y) is near a wire or plant."""
        for dr in range(-r, r+1):
            for dc in range(-r, r+1):
                nr, nc = y+dr, x+dc
                if not in_bounds(nc, nr):
                    continue
                if (nr, nc) in wire_set:
                    return True
                if pm[nr, nc]:
                    return True
        return False

    def has_road_near(x, y, r=3):
        for dr in range(-r, r+1):
            for dc in range(-r, r+1):
                if (y+dr, x+dc) in road_set:
                    return True
        return False

    def zone_clear(x, y):
        """All 3x3 tiles around center must be empty or zone."""
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = y+dr, x+dc
                if not in_bounds(nc, nr):
                    return False
                # Allow if empty OR already a zone tile
                if not (em[nr, nc] or resm[nr, nc] or comm[nr, nc] or indm[nr, nc]):
                    return False
        return True

    def pick_tool():
        t = max(total_zones, 1)
        if res_count / t < 0.50:
            return Tool.RESIDENTIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # --- Phase 2: Build wire spine from plant outward ---
    # Wire runs right from plant along py row, then branches vertically
    # First: wire right from plant
    wire_right_target = min(px + 40, WORLD_W - 3)
    for wx in range(px + 2, wire_right_target):
        wy = py
        if not in_bounds(wx, wy):
            break
        if not (wm[wy, wx] or pm[wy, wx]):
            # Check connectivity: left neighbor must be wire or plant
            if wm[wy, wx-1] or pm[wy, wx-1] or (wx > px+2 and wm[wy, wx-1]):
                if em[wy, wx] or wm[wy, wx]:
                    return (Tool.WIRE, wx, wy)
            break  # gap, stop

    # Wire vertical branches from the horizontal spine
    # At every 6 cols, run wire up/down 10 tiles
    spine_ys, spine_xs = np.where(wm)
    if len(spine_xs) > 0:
        # Find rightmost wire on py row
        on_spine = [(r, c) for (r, c) in zip(spine_ys.tolist(), spine_xs.tolist()) if r == py]
        if on_spine:
            for branch_x in range(px + 4, wire_right_target, 6):
                if not in_bounds(branch_x, py):
                    continue
                if not (wm[py, branch_x] or pm[py, branch_x]):
                    continue
                # Extend wire up
                for dy in range(1, 12):
                    ny2 = py - dy
                    if not in_bounds(branch_x, ny2):
                        break
                    if wm[ny2, branch_x] or pm[ny2, branch_x]:
                        continue
                    if not (wm[ny2+1, branch_x] or pm[ny2+1, branch_x]):
                        break
                    if em[ny2, branch_x]:
                        return (Tool.WIRE, branch_x, ny2)
                    break
                # Extend wire down
                for dy in range(1, 12):
                    ny2 = py + dy
                    if not in_bounds(branch_x, ny2):
                        break
                    if wm[ny2, branch_x] or pm[ny2, branch_x]:
                        continue
                    if not (wm[ny2-1, branch_x] or pm[ny2-1, branch_x]):
                        break
                    if em[ny2, branch_x]:
                        return (Tool.WIRE, branch_x, ny2)
                    break

    # --- Phase 3: Road grid ---
    # Horizontal roads at py-5 and py+5, from px+3 to px+38
    road_start = px + 3
    road_end = min(px + 38, WORLD_W - 3)
    road_rows = [py - 5, py + 5, py - 10, py + 10]

    for rrow in road_rows:
        if not in_bounds(road_start, rrow):
            continue
        # Find where road already exists in this row
        row_road_cols = sorted([c for (r, c) in road_set if r == rrow and c >= road_start])
        next_col = road_start if not row_road_cols else max(row_road_cols) + 1
        if next_col <= road_end and in_bounds(next_col, rrow):
            if not pm[rrow, next_col]:
                return (Tool.ROAD, next_col, rrow)

    # Vertical connector roads every 5 cols between road rows
    for vc in range(road_start, road_end + 1, 5):
        if not in_bounds(vc, road_rows[0]):
            continue
        for rr in range(min(road_rows), max(road_rows) + 1):
            if not in_bounds(vc, rr):
                continue
            if (rr, vc) not in road_set and not pm[rr, vc]:
                # Only place if adjacent to existing road or start col
                neighbors_road = any((rr+dr, vc+dc) in road_set 
                                     for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)])
                if neighbors_road or vc == road_start:
                    return (Tool.ROAD, vc, rr)

    # --- Phase 4: Place zones reactively ---
    # Scan grid for good zone positions
    zone_rows_above = [py - 7, py - 4, py - 11, py - 14]
    zone_rows_below = [py + 7, py + 4, py + 11, py + 14]
    zone_cols = list(range(road_start + 1, road_end, 4))

    all_zone_rows = zone_rows_above + zone_rows_below
    for zr in all_zone_rows:
        for zc in zone_cols:
            if not in_bounds(zc, zr):
                continue
            if not (2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3):
                continue
            if zone_clear(zc, zr) and has_road_near(zc, zr) and is_powered(zc, zr):
                return (pick_tool(), zc, zr)

    # --- Phase 5: Extend wires toward roads that lack power ---
    # Find road tiles without nearby wire
    if len(road_xs) > 0 and len(wire_xs) > 0:
        for i in range(min(len(road_xs), 50)):
            rxi = int(road_xs[i])
            ryi = int(road_ys[i])
            if not is_powered(rxi, ryi, r=3):
                # Find closest wire and step toward road
                dists = np.abs(wire_ys - ryi) + np.abs(wire_xs - rxi)
                closest_idx = int(np.argmin(dists))
                wxi = int(wire_xs[closest_idx])
                wyi = int(wire_ys[closest_idx])
                # Step from wire toward road
                step_y = 1 if ryi > wyi else (-1 if ryi < wyi else 0)
                step_x = 1 if rxi > wxi else (-1 if rxi < wxi else 0)
                for ny2, nx2 in [(wyi + step_y, wxi), (wyi, wxi + step_x)]:
                    if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                        return (Tool.WIRE, nx2, ny2)

    # --- Phase 6: Services once pop grows ---
    if obs.city_pop > 150:
        fx, fy = px + 8, py - 15
        if in_bounds(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
        fx2, fy2 = px + 8, py + 15
        if in_bounds(fx2, fy2) and em[fy2, fx2]:
            return (Tool.POLICESTATION, fx2, fy2)

    # Second power plant if needed
    if obs.city_pop > 400 and np.sum(pm) < 9:
        nx2, ny2 = px + 42, py
        if in_bounds(nx2, ny2) and em[ny2, nx2]:
            return (Tool.COALPOWER, nx2, ny2)

    # --- Phase 7: Fill any empty powered+roaded spot with a zone ---
    # Use numpy dilation to find candidates
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            r0 = max(0, dy); sr0 = max(0, -dy)
            c0 = max(0, dx); sc0 = max(0, -dx)
            h = WORLD_H - abs(dy); w = WORLD_W - abs(dx)
            if h > 0 and w > 0:
                nbr_road[r0:r0+h, c0:c0+w] |= rm[sr0:sr0+h, sc0:sc0+w]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            r0 = max(0, dy); sr0 = max(0, -dy)
            c0 = max(0, dx); sc0 = max(0, -dx)
            h = WORLD_H - abs(dy); w = WORLD_W - abs(dx)
            if h > 0 and w > 0:
                nbr_wire[r0:r0+h, c0:c0+w] |= wm[sr0:sr0+h, sc0:sc0+w]
                nbr_wire[r0:r0+h, c0:c0+w] |= pm[sr0:sr0+h, sc0:sc0+w]

    cand = em & nbr_road & nbr_wire
    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        # Pick deterministically but vary by step
        k = (obs.step * 13 + int(obs.city_pop)) % len(cxs)
        zx, zy = int(cxs[k]), int(cys[k])
        if (2 <= zx <= WORLD_W - 3) and (2 <= zy <= WORLD_H - 3):
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # --- Last resort: extend road from frontier ---
    if len(road_xs) > 0:
        k = (obs.step * 7) % len(road_xs)
        rxi, ryi = int(road_xs[k]), int(road_ys[k])
        # Prefer extending rightward / toward cluster
        for dx, dy in [(1, 0), (0, 1), (0, -1), (-1, 0)]:
            nx2, ny2 = rxi + dx, ryi + dy
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop city builder with high reactivity.
    Reads tile_map each step to decide next action.
    Strategy:
    - Place coal plant if none exists
    - Grow wire network BFS-style from plant toward planned zone area
    - Build road grid in parallel
    - Place zones (R>C>I ratio) where road+wire coverage exists
    - Add second plant and services when population warrants
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Cluster center: build to the RIGHT of plant
    PLANT_X, PLANT_Y = 20, 50
    # Zone area: columns 26..80, rows 36..64
    ZONE_X_START = 26
    ZONE_X_END = 80
    ZONE_Y_START = 36
    ZONE_Y_END = 64

    # --- Phase 1: Place power plant ---
    has_plant = np.any(pm)
    if not has_plant:
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    plant_ys, plant_xs = np.where(pm)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    wire_ys, wire_xs = np.where(wm)
    road_ys, road_xs = np.where(rm)
    res_ys, res_xs = np.where(resm)
    com_ys, com_xs = np.where(comm)
    ind_ys, ind_xs = np.where(indm)

    wire_set = set(zip(wire_ys.tolist(), wire_xs.tolist()))
    road_set = set(zip(road_ys.tolist(), road_xs.tolist()))
    zone_ys = np.concatenate([res_ys, com_ys, ind_ys]) if (len(res_ys)+len(com_ys)+len(ind_ys))>0 else np.array([],dtype=int)
    zone_xs = np.concatenate([res_xs, com_xs, ind_xs]) if (len(res_xs)+len(com_xs)+len(ind_xs))>0 else np.array([],dtype=int)
    zone_set = set(zip(zone_ys.tolist(), zone_xs.tolist()))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # --- Phase 2: Wire spine ---
    # Horizontal wire from plant rightward to ZONE_X_END, at row py
    wire_row = py
    # Extend wire rightward
    for wx in range(px + 2, ZONE_X_END + 2):
        if not in_bounds(wx, wire_row):
            break
        if (wire_row, wx) in wire_set:
            continue
        # Don't place on existing plant or road
        if pm[wire_row, wx]:
            continue
        # Place wire here
        return (Tool.WIRE, wx, wire_row)

    # Vertical wire spines at key columns: connect to road rows
    # Road rows at wire_row-5 and wire_row+5
    road_row_top = wire_row - 6
    road_row_bot = wire_row + 6

    # Vertical wires at every 6 columns in zone area
    for vx in range(ZONE_X_START, ZONE_X_END + 1, 6):
        if not in_bounds(vx, wire_row):
            continue
        # Up from wire spine to road_row_top
        for vy in range(wire_row - 1, road_row_top - 2, -1):
            if not in_bounds(vx, vy):
                break
            if pm[vy, vx]:
                break
            if (vy, vx) not in wire_set:
                return (Tool.WIRE, vx, vy)
            # already has wire, continue
        # Down from wire spine to road_row_bot
        for vy in range(wire_row + 1, road_row_bot + 2):
            if not in_bounds(vx, vy):
                break
            if pm[vy, vx]:
                break
            if (vy, vx) not in wire_set:
                return (Tool.WIRE, vx, vy)

    # --- Phase 3: Road grid ---
    road_x_start = px + 2
    road_x_end = ZONE_X_END + 3

    # Top horizontal road at road_row_top
    for rx in range(road_x_start, road_x_end):
        if not in_bounds(rx, road_row_top):
            continue
        if (road_row_top, rx) not in road_set:
            if not pm[road_row_top, rx]:
                return (Tool.ROAD, rx, road_row_top)

    # Bottom horizontal road at road_row_bot
    for rx in range(road_x_start, road_x_end):
        if not in_bounds(rx, road_row_bot):
            continue
        if (road_row_bot, rx) not in road_set:
            if not pm[road_row_bot, rx]:
                return (Tool.ROAD, rx, road_row_bot)

    # Middle road at wire_row (useful for access)
    for rx in range(road_x_start, road_x_end):
        if not in_bounds(rx, wire_row):
            continue
        if (wire_row, rx) not in road_set:
            if not (wm[wire_row, rx] or pm[wire_row, rx]):
                return (Tool.ROAD, rx, wire_row)

    # Vertical connector roads every 6 cols between top and bot road rows
    for vcx in range(road_x_start, road_x_end, 6):
        if not in_bounds(vcx, road_row_top):
            continue
        for vry in range(road_row_top, road_row_bot + 1):
            if not in_bounds(vcx, vry):
                continue
            if (vry, vcx) not in road_set:
                if not pm[vry, vcx]:
                    return (Tool.ROAD, vcx, vry)

    # Extra road rows for more zones
    road_row_top2 = road_row_top - 6
    road_row_bot2 = road_row_bot + 6

    for rx in range(road_x_start, road_x_end):
        if not in_bounds(rx, road_row_top2):
            continue
        if (road_row_top2, rx) not in road_set:
            if not pm[road_row_top2, rx]:
                return (Tool.ROAD, rx, road_row_top2)

    for rx in range(road_x_start, road_x_end):
        if not in_bounds(rx, road_row_bot2):
            continue
        if (road_row_bot2, rx) not in road_set:
            if not pm[road_row_bot2, rx]:
                return (Tool.ROAD, rx, road_row_bot2)

    # --- Phase 4: Place zones ---
    # Compute road neighbor mask (within 3 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            r0 = max(0, dy); r1 = WORLD_H + min(0, dy)
            c0 = max(0, dx); c1 = WORLD_W + min(0, dx)
            sr0 = max(0, -dy); sr1 = WORLD_H + min(0, -dy)
            sc0 = max(0, -dx); sc1 = WORLD_W + min(0, -dx)
            if r1 > r0 and c1 > c0:
                nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Compute wire/plant neighbor mask (within 5 tiles)
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            r0 = max(0, dy); r1 = WORLD_H + min(0, dy)
            c0 = max(0, dx); c1 = WORLD_W + min(0, dx)
            sr0 = max(0, -dy); sr1 = WORLD_H + min(0, -dy)
            sc0 = max(0, -dx); sc1 = WORLD_W + min(0, -dx)
            if r1 > r0 and c1 > c0:
                nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
                nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    # Candidate zone positions: rows flanking road rows, cols in zone area
    zone_row_candidates = [
        road_row_top - 2, road_row_top - 5, road_row_top2 - 2,
        road_row_bot + 2, road_row_bot + 5, road_row_bot2 + 2,
        wire_row,  # middle row
    ]
    zone_col_candidates = list(range(road_x_start + 2, road_x_end - 1, 3))

    for zr in zone_row_candidates:
        for zc in zone_col_candidates:
            if not (2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3):
                continue
            if nbr_road[zr, zc] and nbr_wire[zr, zc] and zone_clear(zc, zr):
                return (pick_tool(), zc, zr)

    # --- Phase 5: Reactive zone placement using dilated masks ---
    cand = em & nbr_road & nbr_wire
    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        # pick based on step for determinism but reactive to map
        seed = int(obs.step * 31 + int(tm[50, 50]) + int(tm[40, 40]))
        k = seed % len(cxs)
        zx, zy = int(cxs[k]), int(cys[k])
        if zone_clear(zx, zy):
            return (pick_tool(), zx, zy)

    # --- Phase 6: Second power plant ---
    if obs.city_pop > 200 and np.sum(pm) < 9:
        # Place second plant at px+40
        nx2, ny2 = px + 40, py
        if in_bounds(nx2, ny2) and em[ny2, nx2]:
            return (Tool.COALPOWER, nx2, ny2)

    # --- Phase 7: Services ---
    if obs.city_pop > 150:
        fx, fy = px + 4, py - 10
        if in_bounds(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
        fx2, fy2 = px + 4, py + 10
        if in_bounds(fx2, fy2) and em[fy2, fx2]:
            return (Tool.POLICESTATION, fx2, fy2)

    # --- Phase 8: Extend road reactively from existing road frontier ---
    if len(road_xs) > 0:
        k = int(obs.step * 13 + int(obs.city_pop)) % len(road_xs)
        rx, ry = int(road_xs[k]), int(road_ys[k])
        # Prefer extending toward zone area
        directions = [(1, 0), (0, 1), (-1, 0), (0, -1)]
        for ddx, ddy in directions:
            nx2, ny2 = rx + ddx, ry + ddy
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                return (Tool.ROAD, nx2, ny2)

    # --- Phase 9: Extend wire from frontier ---
    if len(wire_xs) > 0:
        k = int(obs.step * 7) % len(wire_xs)
        wx2, wy2 = int(wire_xs[k]), int(wire_ys[k])
        for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = wx2 + ddx, wy2 + ddy
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Build a compact city with:
    - Single central power plant connected via wires
    - Grid road network
    - Mixed zones around roads
    - Focus on getting zones powered and road-adjacent
    """

    def build_plan():
        p = []

        # Central power plant at (20, 20)
        PLANT_X, PLANT_Y = 20, 20
        p.append((Tool.COALPOWER, PLANT_X, PLANT_Y))

        # Second power plant for larger coverage
        PLANT_X2, PLANT_Y2 = 80, 20
        p.append((Tool.COALPOWER, PLANT_X2, PLANT_Y2))

        # === CLUSTER 1: centered at (40, 50) ===
        CX, CY = 40, 50

        # Horizontal wire from plant to cluster center (at road level y=50)
        # First run wire from plant down to y=50, x=20
        for dy in range(20, 51):
            p.append((Tool.WIRE, PLANT_X, dy))
        # Then horizontal wire from x=20 to x=40 at y=50
        for dx in range(20, 41):
            p.append((Tool.WIRE, dx, CY))

        # Grid roads for cluster 1
        # Horizontal roads
        for y_off in [-6, 0, 6]:
            for dx in range(-12, 14):
                p.append((Tool.ROAD, CX + dx, CY + y_off))
        # Vertical roads
        for x_off in [-9, -3, 3, 9]:
            for dy in range(-8, 9):
                p.append((Tool.ROAD, CX + x_off, CY + dy))

        # Wire grid to power all zones in cluster 1
        # Vertical wire along x=CX to distribute power to horizontal wires
        for dy in range(-8, 9):
            p.append((Tool.WIRE, CX, CY + dy))
        # Horizontal wires along zone rows
        for y_off in [-6, 0, 6]:
            for dx in range(-12, 13):
                p.append((Tool.WIRE, CX + dx, CY + y_off - 1))  # wire just above road

        # Place zones in a grid pattern around cluster 1
        # RES on left columns, COM in center, IND on right
        for col_x, tool in [(-9, Tool.RESIDENTIAL), (-3, Tool.COMMERCIAL), 
                              (3, Tool.INDUSTRIAL), (9, Tool.RESIDENTIAL)]:
            for row_y in [-6, 0, 6]:
                p.append((tool, CX + col_x, CY + row_y))

        # === CLUSTER 2: centered at (80, 50) ===
        CX2, CY2 = 80, 50

        # Wire from plant2 down to cluster 2
        for dy in range(20, 51):
            p.append((Tool.WIRE, PLANT_X2, dy))
        # Horizontal wire from x=80 plant to cluster center
        for dx in range(60, 81):
            p.append((Tool.WIRE, dx, CY2))

        # Grid roads for cluster 2
        for y_off in [-6, 0, 6]:
            for dx in range(-12, 14):
                p.append((Tool.ROAD, CX2 + dx, CY2 + y_off))
        for x_off in [-9, -3, 3, 9]:
            for dy in range(-8, 9):
                p.append((Tool.ROAD, CX2 + x_off, CY2 + dy))

        # Wire grid for cluster 2
        for dy in range(-8, 9):
            p.append((Tool.WIRE, CX2, CY2 + dy))
        for y_off in [-6, 0, 6]:
            for dx in range(-12, 13):
                p.append((Tool.WIRE, CX2 + dx, CY2 + y_off - 1))

        # Place zones in cluster 2 - different mix: more COM and IND
        for col_x, tool in [(-9, Tool.COMMERCIAL), (-3, Tool.RESIDENTIAL),
                              (3, Tool.COMMERCIAL), (9, Tool.INDUSTRIAL)]:
            for row_y in [-6, 0, 6]:
                p.append((tool, CX2 + col_x, CY2 + row_y))

        # Connect both clusters with a road along y=50
        for x in range(46, 68):
            p.append((Tool.ROAD, x, CY))
        # And a wire connecting the two power systems
        for x in range(41, 68):
            p.append((Tool.WIRE, x, CY - 2))

        # === CLUSTER 3: lower area, centered at (60, 75) ===
        CX3, CY3 = 60, 75

        # Wire from cluster1's vertical wire down to cluster3
        for dy in range(51, 76):
            p.append((Tool.WIRE, CX, dy))
        for dx in range(40, 61):
            p.append((Tool.WIRE, dx, CY3))

        # Simple grid for cluster 3
        for y_off in [-6, 0, 6]:
            for dx in range(-9, 11):
                p.append((Tool.ROAD, CX3 + dx, CY3 + y_off))
        for x_off in [-6, 0, 6]:
            for dy in range(-8, 9):
                p.append((Tool.ROAD, CX3 + x_off, CY3 + dy))

        for dy in range(-8, 9):
            p.append((Tool.WIRE, CX3, CY3 + dy))

        # More residential focus for cluster 3
        for col_x, tool in [(-6, Tool.RESIDENTIAL), (0, Tool.RESIDENTIAL),
                              (6, Tool.COMMERCIAL)]:
            for row_y in [-6, 0, 6]:
                p.append((tool, CX3 + col_x, CY3 + row_y))

        # Additional industrial zones near cluster 3
        for row_y in [-6, 0, 6]:
            p.append((Tool.INDUSTRIAL, CX3 + 9, CY3 + row_y))

        return p

    if "p" not in state:
        state["p"] = build_plan()
        state["i"] = 0

    if state["i"] < len(state["p"]):
        a = state["p"][state["i"]]
        state["i"] += 1
        return a

    # Reactive phase: add more zones adjacent to existing powered roads
    tm = obs.tile_map
    r_mask = res_mask(tm)
    c_mask = com_mask(tm)
    i_mask = ind_mask(tm)
    rd_mask = road_mask(tm)
    emp = empty_mask(tm)

    n_res = int(r_mask.sum())
    n_com = int(c_mask.sum())
    n_ind = int(i_mask.sum())

    # Target 3:2:2 ratio
    if n_com * 3 < n_res * 2:
        tool = Tool.COMMERCIAL
    elif n_ind * 3 < n_res * 2:
        tool = Tool.INDUSTRIAL
    else:
        tool = Tool.RESIDENTIAL

    # Find empty tiles near roads
    nbr = np.zeros_like(emp)
    nbr[1:, :] |= rd_mask[:-1, :]
    nbr[:-1, :] |= rd_mask[1:, :]
    nbr[:, 1:] |= rd_mask[:, :-1]
    nbr[:, :-1] |= rd_mask[:, 1:]

    cand = emp & nbr
    ys, xs = np.where(cand)
    if len(xs) == 0:
        return None

    k = (obs.step * 7 + int(tm[50, 60])) % len(xs)
    return (tool, int(xs[k]), int(ys[k]))

def act(obs, state):
    """
    Closed-loop policy: reads map each step, extends infrastructure
    adjacent to what already exists. Uses a phase counter for ordering.
    Layout: single cluster centered at (60, 50), coal plant at (45, 50),
    wire spine along row 50, roads at rows 47 and 53, zones above/below.
    """
    tm = obs.tile_map
    step = obs.step

    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    # Cluster center
    cx, cy = 60, 50
    plant_x, plant_y = 45, 50
    spine_row = cy          # wire row
    road_row_up = cy - 3    # road above
    road_row_dn = cy + 3    # road below
    spine_start = plant_x + 3  # just right of plant footprint
    spine_end = cx + 30

    # Zone columns: every 6 cols from plant_x+6 to spine_end
    zone_cols = list(range(plant_x + 6, spine_end + 1, 6))
    zone_rows_above = [cy - 7, cy - 13, cy - 19]
    zone_rows_below = [cy + 7, cy + 13, cy + 19]

    # --- Phase 1: Place coal power plant if missing ---
    if not np.any(pm):
        return (Tool.COALPOWER, plant_x, plant_y)

    # --- Phase 2: Extend wire spine rightward from plant ---
    # Find rightmost wire in spine_row
    wire_in_spine = np.where(wm[spine_row, :])[0]
    if len(wire_in_spine) == 0:
        # Start wire just right of plant
        wx = plant_x + 3
        if 0 <= wx < WORLD_W and em[spine_row, wx]:
            return (Tool.WIRE, wx, spine_row)
        else:
            return (Tool.WIRE, plant_x + 3, spine_row)
    else:
        max_wx = int(wire_in_spine.max())
        if max_wx < spine_end:
            nx = max_wx + 1
            if 0 <= nx < WORLD_W:
                return (Tool.WIRE, nx, spine_row)

    # --- Phase 3: Extend upper road rightward ---
    road_up_cols = np.where(rm[road_row_up, :])[0]
    if len(road_up_cols) == 0:
        # Start road at same x as leftmost wire
        lx_road = plant_x + 3
        return (Tool.ROAD, lx_road, road_row_up)
    else:
        max_rc = int(road_up_cols.max())
        if max_rc < spine_end:
            return (Tool.ROAD, max_rc + 1, road_row_up)

    # --- Phase 4: Extend lower road rightward ---
    road_dn_cols = np.where(rm[road_row_dn, :])[0]
    if len(road_dn_cols) == 0:
        lx_road = plant_x + 3
        return (Tool.ROAD, lx_road, road_row_dn)
    else:
        max_rc = int(road_dn_cols.max())
        if max_rc < spine_end:
            return (Tool.ROAD, max_rc + 1, road_row_dn)

    # --- Phase 5: Place vertical connector roads at zone columns ---
    for zc in zone_cols:
        if not (0 <= zc < WORLD_W):
            continue
        # Connect road_row_up to spine_row
        for row in range(road_row_up, spine_row + 1):
            if 0 <= row < WORLD_H:
                if not rm[row, zc] and not wm[row, zc] and not pm[row, zc]:
                    return (Tool.ROAD, zc, row)
        # Connect spine_row to road_row_dn
        for row in range(spine_row, road_row_dn + 1):
            if 0 <= row < WORLD_H:
                if not rm[row, zc] and not wm[row, zc] and not pm[row, zc]:
                    return (Tool.ROAD, zc, row)

    # --- Phase 6: Add vertical wires from spine to zone rows ---
    def has_power_near(zr, zc, radius=5):
        r0, r1 = max(0, zr - radius), min(WORLD_H, zr + radius + 1)
        c0, c1 = max(0, zc - radius), min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_near(zr, zc, radius=3):
        r0, r1 = max(0, zr - radius), min(WORLD_H, zr + radius + 1)
        c0, c1 = max(0, zc - radius), min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    def zone_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                r, c = zr + dr, zc + dc
                if not (0 <= r < WORLD_H and 0 <= c < WORLD_W):
                    return False
                if not em[r, c]:
                    return False
        return True

    def zone_occupied(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                r, c = zr + dr, zc + dc
                if not (0 <= r < WORLD_H and 0 <= c < WORLD_W):
                    continue
                if resm[r, c] or comm[r, c] or indm[r, c]:
                    return True
        return False

    # Wire branches upward from spine to above-zone rows
    for zc in zone_cols:
        if not (0 <= zc < WORLD_W):
            continue
        for zr in zone_rows_above:
            if not (0 <= zr < WORLD_H):
                continue
            # Lay wire from spine_row-1 up to zr+2
            for wr in range(spine_row - 1, zr + 1, -1):
                if 0 <= wr < WORLD_H:
                    if not wm[wr, zc] and not rm[wr, zc] and not pm[wr, zc] and em[wr, zc]:
                        return (Tool.WIRE, zc, wr)
    # Wire branches downward
    for zc in zone_cols:
        if not (0 <= zc < WORLD_W):
            continue
        for zr in zone_rows_below:
            if not (0 <= zr < WORLD_H):
                continue
            for wr in range(spine_row + 1, zr):
                if 0 <= wr < WORLD_H:
                    if not wm[wr, zc] and not rm[wr, zc] and not pm[wr, zc] and em[wr, zc]:
                        return (Tool.WIRE, zc, wr)

    # --- Phase 7: Place zones where powered + road access ---
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count + 1

    def pick_type(idx):
        if com_count / total_zones < 0.25 and idx % 4 == 0:
            return Tool.COMMERCIAL
        elif ind_count / total_zones < 0.25 and idx % 4 == 1:
            return Tool.INDUSTRIAL
        else:
            return Tool.RESIDENTIAL

    idx = 0
    for zr in zone_rows_above + zone_rows_below:
        for zc in zone_cols:
            if not (0 <= zr < WORLD_H and 0 <= zc < WORLD_W):
                continue
            if zone_occupied(zr, zc):
                idx += 1
                continue
            if has_road_near(zr, zc, 4) and has_power_near(zr, zc, 6) and zone_free(zr, zc):
                return (pick_type(idx), zc, zr)
            idx += 1

    # --- Phase 8: If city growing, add extra zone rows ---
    if obs.city_pop > 50:
        extra_rows = [cy - 25, cy + 25, cy - 31, cy + 31]
        idx2 = 100
        for zr in extra_rows:
            for zc in zone_cols:
                if not (0 <= zr < WORLD_H and 0 <= zc < WORLD_W):
                    continue
                if zone_occupied(zr, zc):
                    continue
                if has_road_near(zr, zc, 5) and has_power_near(zr, zc, 8) and zone_free(zr, zc):
                    return (pick_type(idx2), zc, zr)
                idx2 += 1

    # --- Phase 9: Fill gaps in roads ---
    for zc in zone_cols:
        if not (0 <= zc < WORLD_W):
            continue
        for rr in [road_row_up, road_row_dn]:
            if 0 <= rr < WORLD_H and not rm[rr, zc] and em[rr, zc]:
                return (Tool.ROAD, zc, rr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy.
    Strategy:
    - Read current map each step to decide next action.
    - Place coal plant near center-left if none exists.
    - Grow wire spine vertically from plant.
    - Build road column adjacent to wire.
    - Place zones (RES/COM/IND) on both sides of road/wire where powered+roaded.
    - Connect zones laterally to wire spine.
    - Expand outward as population grows.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    cx, cy = 60, 50  # map center

    has_plant = np.any(pm)
    has_wire = np.any(wm)
    has_road = np.any(rm)

    # Phase 1: place coal power plant
    plant_cx, plant_cy = cx - 6, cy
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Compute current map info
    wire_positions = set(zip(*np.where(wm))) if has_wire else set()
    road_positions = set(zip(*np.where(rm))) if has_road else set()
    res_positions = set(zip(*np.where(res_mask(tm))))
    com_positions = set(zip(*np.where(com_mask(tm))))
    ind_positions = set(zip(*np.where(ind_mask(tm))))

    res_count = len(res_positions)
    com_count = len(com_positions)
    ind_count = len(ind_positions)

    # Wire spine column: just right of plant footprint
    # Plant center at (plant_cx, plant_cy), footprint occupies cols plant_cx-1..plant_cx+1
    wire_col = plant_cx + 3  # cx-3
    road_col = wire_col + 1  # cx-2

    # Vertical span for wire/road: grow based on population
    base_span = 8
    extra_span = min(20, obs.city_pop // 50)
    target_span = base_span + extra_span

    # Phase 2: extend wire spine vertically
    # Find current wire in wire_col
    wire_rows_in_col = sorted(r for (r, c) in wire_positions if c == wire_col)

    if not wire_rows_in_col:
        # Place first wire adjacent to plant
        if em[plant_cy, wire_col]:
            return (Tool.WIRE, wire_col, plant_cy)
        else:
            return (Tool.WIRE, wire_col, plant_cy - 1)
    else:
        min_wr = min(wire_rows_in_col)
        max_wr = max(wire_rows_in_col)
        tmin = max(1, cy - target_span)
        tmax = min(WORLD_H - 2, cy + target_span)

        # Extend downward first
        if max_wr < tmax:
            nr = max_wr + 1
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if min_wr > tmin:
            nr = min_wr - 1
            if 0 <= nr >= 0 and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    # Phase 3: build road column adjacent to wire
    if wire_rows_in_col:
        road_rows_in_col = sorted(r for (r, c) in road_positions if c == road_col)
        road_rows_set = set(road_rows_in_col)
        for wr in wire_rows_in_col:
            if wr not in road_rows_set and 0 <= road_col < WORLD_W:
                if em[wr, road_col]:
                    return (Tool.ROAD, road_col, wr)

    # Phase 4: place zones adjacent to road/wire
    # Left zone column: center at wire_col - 3 (so zone right edge touches wire)
    # Right zone column: center at road_col + 3 (so zone left edge touches road)
    left_zone_col = wire_col - 3
    right_zone_col = road_col + 3

    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def already_zone_nearby(zr, zc, all_zones):
        return any(abs(zr - pr) <= 1 and abs(zc - pc) <= 1 for (pr, pc) in all_zones)

    all_zones = res_positions | com_positions | ind_positions

    # Only place zones where wire row coverage exists AND road row coverage exists
    wire_rows_set = set(wire_rows_in_col)
    road_rows_set2 = set(r for (r, c) in road_positions if c == road_col)

    zone_rows = sorted(wire_rows_in_col)

    for zr in zone_rows:
        # Check road coverage within 2 rows
        road_nearby = any(abs(zr - rr) <= 2 for rr in road_rows_set2)
        wire_nearby = any(abs(zr - wr) <= 1 for wr in wire_rows_set)

        if not (road_nearby and wire_nearby):
            continue

        for zc in [left_zone_col, right_zone_col]:
            if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                if not already_zone_nearby(zr, zc, all_zones) and zone_area_free(zr, zc):
                    # Decide zone type based on counts
                    # Aim for ~50% res, ~25% com, ~25% ind
                    if ind_count * 4 < res_count and zc == left_zone_col and zr > cy:
                        return (Tool.INDUSTRIAL, zc, zr)
                    elif com_count * 4 < res_count and zc == right_zone_col:
                        return (Tool.COMMERCIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

    # Phase 5: add lateral wires from spine to left zones
    for wr in wire_rows_in_col:
        for wc in range(wire_col - 1, left_zone_col + 1, -1):
            if 0 <= wc < WORLD_W and em[wr, wc]:
                return (Tool.WIRE, wc, wr)

    # Phase 6: add lateral roads from road col to right zones
    for wr in wire_rows_in_col:
        for rc in range(road_col + 1, right_zone_col):
            if 0 <= rc < WORLD_W and em[wr, rc]:
                return (Tool.ROAD, rc, wr)

    # Phase 7: if population growing, add a second road column further right
    if obs.city_pop > 300:
        road_col2 = road_col + 7
        right_zone_col2 = road_col2 + 3
        for wr in wire_rows_in_col:
            if 0 <= road_col2 < WORLD_W and em[wr, road_col2]:
                # First ensure wire reaches there
                for wc in range(wire_col + 1, road_col2):
                    if em[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                return (Tool.ROAD, road_col2, wr)
        for zr in zone_rows:
            for zc in [right_zone_col2]:
                if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                    if not already_zone_nearby(zr, zc, all_zones) and zone_area_free(zr, zc):
                        return (Tool.RESIDENTIAL, zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map each step and decides next placement.
    Strategy:
    - Place coal power plant near center-left.
    - Extend wires vertically from plant.
    - Build roads parallel to wire spine (one tile to the right).
    - Place zones on both sides: RES left of wire, RES/COM/IND right of road.
    - Add lateral wires to connect zones to spine.
    - React to current map state each step.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    has_plant = np.any(pm)
    has_wire = np.any(wm)
    has_road = np.any(rm)

    res_count = np.sum(res_mask(tm))
    com_count = np.sum(com_mask(tm))
    ind_count = np.sum(ind_mask(tm))

    # Phase 1: Place coal power plant if missing
    if not has_plant:
        return (Tool.COALPOWER, cx - 5, cy)

    # Find existing positions
    wire_positions = list(zip(*np.where(wm)))  # (row, col)
    road_positions = list(zip(*np.where(rm)))
    res_positions = list(zip(*np.where(res_mask(tm))))

    # Wire spine column: cx-2 (right side of plant footprint: plant center cx-5, footprint cx-7..cx-3)
    wire_col = cx - 2
    road_col = cx  # road column one tile right of wire

    wire_col_rows = sorted([r for (r, c) in wire_positions if c == wire_col])
    road_col_rows = sorted([r for (r, c) in road_positions if c == road_col])

    # Phase 2: Start wire adjacent to plant if none in wire_col
    if not wire_col_rows:
        # Plant center at cx-5, footprint cx-7..cx-3; wire_col=cx-2 is adjacent
        if em[cy, wire_col]:
            return (Tool.WIRE, wire_col, cy)
        else:
            # Try nearby rows
            for dy in range(1, 5):
                for nr in [cy + dy, cy - dy]:
                    if 0 <= nr < WORLD_H and em[nr, wire_col]:
                        return (Tool.WIRE, wire_col, nr)
        return None

    # Phase 3: Extend wire spine vertically
    target_min = max(0, cy - 15)
    target_max = min(WORLD_H - 1, cy + 15)

    min_row = min(wire_col_rows)
    max_row = max(wire_col_rows)

    # Extend downward
    if max_row < target_max:
        nr = max_row + 1
        if nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
            return (Tool.WIRE, wire_col, nr)

    # Extend upward
    if min_row > target_min:
        nr = min_row - 1
        if nr >= 0 and (em[nr, wire_col] or wm[nr, wire_col]):
            return (Tool.WIRE, wire_col, nr)

    # Phase 4: Build road column adjacent to wire spine
    # Road at road_col, for each row in wire_col_rows
    for r in wire_col_rows:
        if 0 <= r < WORLD_H and 0 <= road_col < WORLD_W:
            if not rm[r, road_col] and em[r, road_col]:
                return (Tool.ROAD, road_col, r)

    # Phase 5: Add lateral wire connections to left zone column
    # Left zone center at cx-5-2=cx-7? No: plant is at cx-5, zones left of wire at wire_col-3=cx-5
    # Zone left center col: cx - 5 (plant center)... but plant is there.
    # Use cx - 6 for left zones, cx + 3 for right zones
    left_zone_col = cx - 6
    right_zone_col = cx + 3

    # Left zone needs wire connection: wire at wire_col-1, wire_col-2, wire_col-3 at zone rows
    # Right zone needs road extension: road at road_col+1, road_col+2, road_col+3 at zone rows

    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def zone_already_placed(zr, zc):
        return any(abs(zr - pr) <= 1 and abs(zc - pc) <= 1 for (pr, pc) in res_positions)

    # Phase 6: Place zones where wire AND road coverage exists
    # Zone rows spaced by 3
    zone_rows = list(range(max(1, cy - 14), min(WORLD_H - 1, cy + 15), 3))

    for zr in zone_rows:
        wire_near = any(abs(zr - wr) <= 2 for wr in wire_col_rows)
        road_near = any(abs(zr - rr) <= 2 for (rr, rc) in road_positions if rc == road_col)

        if wire_near and road_near:
            # Try left zone
            zc = left_zone_col
            if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                already = zone_already_placed(zr, zc)
                if not already and zone_area_free(zr, zc):
                    if ind_count < res_count // 3 and zr > cy:
                        return (Tool.INDUSTRIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

            # Try right zone
            zc = right_zone_col
            if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                already = zone_already_placed(zr, zc)
                if not already and zone_area_free(zr, zc):
                    if com_count < res_count // 3:
                        return (Tool.COMMERCIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

    # Phase 7: Lateral wires to connect left zones (wire_col-1, wire_col-2, wire_col-3)
    for wr in wire_col_rows:
        for wc in range(wire_col - 1, left_zone_col - 1, -1):
            if 0 <= wc < WORLD_W and em[wr, wc]:
                return (Tool.WIRE, wc, wr)

    # Phase 8: Road extensions to reach right zones
    for wr in wire_col_rows:
        for rc in range(road_col + 1, right_zone_col + 2):
            if 0 <= rc < WORLD_W and em[wr, rc] and not rm[wr, rc]:
                return (Tool.ROAD, rc, wr)

    # Phase 9: Expand zone coverage further if population growing
    if obs.city_pop > 150:
        extra_rows = list(range(max(1, cy - 20), min(WORLD_H - 1, cy + 21), 3))
        for zr in extra_rows:
            for zc in [left_zone_col, right_zone_col, cx - 9, cx + 6]:
                if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                    already = zone_already_placed(zr, zc)
                    if not already and zone_area_free(zr, zc):
                        # Check rough power/road proximity
                        road_near = any(abs(zr - rr) <= 3 and abs(zc - rc2) <= 4
                                        for (rr, rc2) in road_positions)
                        if road_near:
                            return (Tool.RESIDENTIAL, zc, zr)

    # Phase 10: More wire and road for second power ring
    if obs.city_pop > 300:
        wire2_col = cx - 2 + (cx + 3 - (cx - 2)) // 2  # mid between wire and right zones
        for wr in wire_col_rows:
            if 0 <= wire2_col < WORLD_W and em[wr, wire2_col] and not wm[wr, wire2_col]:
                return (Tool.WIRE, wire2_col, wr)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map each step.
    Strategy:
    1. Place coal power plant near center-left
    2. Extend wire spine rightward from plant
    3. Add vertical wire branches
    4. Build horizontal roads parallel to spine
    5. Place zones where road+wire access exists
    Adapts each step by scanning actual tile_map state.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    CX, CY = 60, 50

    has_plant = np.any(pm)
    plant_rows, plant_cols = np.where(pm)
    wire_rows, wire_cols = np.where(wm)
    road_rows, road_cols = np.where(rm)

    wire_pos = set(zip(wire_rows.tolist(), wire_cols.tolist()))
    road_pos = set(zip(road_rows.tolist(), road_cols.tolist()))
    zone_mask = resm | comm | indm
    zone_rows, zone_cols = np.where(zone_mask)
    zone_pos = set(zip(zone_rows.tolist(), zone_cols.tolist()))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Phase 1: Place power plant
    if not has_plant:
        px, py = CX - 15, CY
        return (Tool.COALPOWER, px, py)

    # Plant center
    pc0 = int(plant_cols[len(plant_cols)//2])
    pr0 = int(plant_rows[len(plant_rows)//2])
    plant_right = pc0 + 2

    spine_row = pr0
    wire_target_col = min(CX + 40, WORLD_W - 3)

    # Phase 2: Extend wire spine rightward from plant
    spine_wires = sorted([c for (r, c) in wire_pos if r == spine_row and c >= plant_right])
    if spine_wires:
        max_wire_col = max(spine_wires)
    else:
        max_wire_col = plant_right - 1

    if max_wire_col < wire_target_col:
        nc = max_wire_col + 1
        if 0 <= nc < WORLD_W and not pm[spine_row, nc]:
            if em[spine_row, nc] or wm[spine_row, nc]:
                return (Tool.WIRE, nc, spine_row)

    # Phase 3: Vertical wire branches every 6 cols
    branch_cols = list(range(plant_right + 2, wire_target_col + 1, 6))
    vert_min = max(spine_row - 18, 3)
    vert_max = min(spine_row + 18, WORLD_H - 3)

    for bc in branch_cols:
        if 0 <= bc < WORLD_W:
            if (spine_row, bc) not in wire_pos:
                continue
            # Extend up from spine
            for wr in range(spine_row - 1, vert_min - 1, -1):
                if (wr, bc) not in wire_pos and not pm[wr, bc]:
                    if em[wr, bc]:
                        return (Tool.WIRE, bc, wr)
                    break
                elif (wr, bc) in wire_pos:
                    continue
                else:
                    break
            # Extend down from spine
            for wr in range(spine_row + 1, vert_max + 1):
                if (wr, bc) not in wire_pos and not pm[wr, bc]:
                    if em[wr, bc]:
                        return (Tool.WIRE, bc, wr)
                    break
                elif (wr, bc) in wire_pos:
                    continue
                else:
                    break

    # Phase 4: Horizontal roads
    road_row_above = spine_row - 4
    road_row_below = spine_row + 4
    road_col_start = plant_right + 1
    road_col_end = wire_target_col + 2

    for rrow in [road_row_above, road_row_below]:
        if 0 <= rrow < WORLD_H:
            road_here = sorted([c for (r, c) in road_pos if r == rrow])
            max_rc = max(road_here) if road_here else road_col_start - 1
            if max_rc < road_col_end:
                nc = max_rc + 1
                if 0 <= nc < WORLD_W and not pm[rrow, nc]:
                    return (Tool.ROAD, nc, rrow)

    # Vertical connector roads
    for vc in range(road_col_start, road_col_end + 1, 6):
        if 0 <= vc < WORLD_W:
            for vr in range(road_row_above, road_row_below + 1):
                if 0 <= vr < WORLD_H:
                    if (vr, vc) not in road_pos and not pm[vr, vc]:
                        return (Tool.ROAD, vc, vr)

    # Phase 5: Place zones
    zone_col_list = list(range(road_col_start + 1, road_col_end, 6))
    zone_row_sets = [
        road_row_above - 2,
        road_row_above - 5,
        road_row_above - 8,
        road_row_below + 2,
        road_row_below + 5,
        road_row_below + 8,
    ]

    def has_road_access(zy, zx, radius=4):
        r1, r2 = max(0, zy-radius), min(WORLD_H, zy+radius+1)
        c1, c2 = max(0, zx-radius), min(WORLD_W, zx+radius+1)
        return np.any(rm[r1:r2, c1:c2])

    def has_wire_access(zy, zx, radius=5):
        r1, r2 = max(0, zy-radius), min(WORLD_H, zy+radius+1)
        c1, c2 = max(0, zx-radius), min(WORLD_W, zx+radius+1)
        return np.any(wm[r1:r2, c1:c2]) or np.any(pm[r1:r2, c1:c2])

    def zone_clear(zy, zx):
        if zy < 1 or zy >= WORLD_H-1 or zx < 1 or zx >= WORLD_W-1:
            return False
        patch = tm[zy-1:zy+2, zx-1:zx+2]
        # all must be empty or road or wire (auto-bulldoze handles the rest, but avoid placing on roads)
        patch_em = em[zy-1:zy+2, zx-1:zx+2]
        patch_zone = zone_mask[zy-1:zy+2, zx-1:zx+2]
        patch_plant = pm[zy-1:zy+2, zx-1:zx+2]
        if np.any(patch_plant):
            return False
        if np.any(patch_zone):
            return False
        return True

    def near_zone(zy, zx):
        for (zr, zc) in zone_pos:
            if abs(zy - zr) < 4 and abs(zx - zc) < 4:
                return True
        return False

    def pick_tool():
        t = total_zones + 1
        r = res_count / t
        c = com_count / t
        i = ind_count / t
        if c < 0.20:
            return Tool.COMMERCIAL
        if i < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    for zr in zone_row_sets:
        for zc in zone_col_list:
            if 2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3:
                if not near_zone(zr, zc) and zone_clear(zr, zc):
                    if has_road_access(zr, zc) and has_wire_access(zr, zc):
                        return (pick_tool(), zc, zr)

    # Phase 6: Fix unpowered zones - extend wire toward zones lacking power
    for (zyr, zxc) in list(zone_pos)[:30]:
        if not has_wire_access(zyr, zxc, radius=4):
            if wire_pos:
                closest_w = min(wire_pos, key=lambda p: abs(p[0]-zyr)+abs(p[1]-zxc))
                wr, wc = closest_w
                dr = 1 if zyr > wr else (-1 if zyr < wr else 0)
                dc = 1 if zxc > wc else (-1 if zxc < wc else 0)
                # Try row step first, then col
                for nr, nc in [(wr+dr, wc), (wr, wc+dc), (wr+dr, wc+dc)]:
                    if 0 <= nr < WORLD_H and 0 <= nc < WORLD_W:
                        if em[nr, nc] and not pm[nr, nc]:
                            return (Tool.WIRE, nc, nr)

    # Phase 7: Second power plant if needed
    if obs.city_pop > 100 and len(plant_cols) < 9:
        # Roughly <9 cells means one plant (3x3=9)
        px2, py2 = CX + 20, CY
        if em[py2, px2]:
            return (Tool.COALPOWER, px2, py2)

    # Phase 8: More zone rows
    extra_rows = [road_row_above - 11, road_row_below + 11]
    for zr in extra_rows:
        for zc in zone_col_list:
            if 2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3:
                if not near_zone(zr, zc) and zone_clear(zr, zc):
                    if has_road_access(zr, zc, radius=5) and has_wire_access(zr, zc, radius=7):
                        return (pick_tool(), zc, zr)

    # Phase 9: Fill missing road segments
    for zc in zone_col_list:
        for rrow in [road_row_above, road_row_below]:
            if 0 <= rrow < WORLD_H and 0 <= zc < WORLD_W:
                if (rrow, zc) not in road_pos and not pm[rrow, zc]:
                    return (Tool.ROAD, zc, rrow)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy.
    Improvements over parent:
    - Denser zone placement: alternate RES/COM/IND more aggressively
    - Add a second wire+road corridor further right for more zones
    - Use road connections both sides of wire spine
    - React to powered_zones count to decide expansion direction
    - Place police/fire stations once pop grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    cx, cy = 58, 50  # map center slightly left

    has_plant = np.any(pm)

    # Phase 1: place coal power plant
    plant_cx, plant_cy = cx - 8, cy
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Recompute live positions every step (closed-loop)
    wire_positions = set(zip(*np.where(wm))) if np.any(wm) else set()
    road_positions = set(zip(*np.where(rm))) if np.any(rm) else set()
    res_pos = set(zip(*np.where(res_mask(tm))))
    com_pos = set(zip(*np.where(com_mask(tm))))
    ind_pos = set(zip(*np.where(ind_mask(tm))))
    all_zones = res_pos | com_pos | ind_pos

    res_count = len(res_pos)
    com_count = len(com_pos)
    ind_count = len(ind_pos)

    # Wire spine column just right of plant
    wire_col = plant_cx + 4   # e.g. cx-4
    road_col_L = wire_col - 1  # road on LEFT of wire spine
    road_col_R = wire_col + 1  # road on RIGHT of wire spine

    # Zone columns
    left_zone_col = wire_col - 4   # zones on far left
    right_zone_col = wire_col + 4  # zones on far right

    # Vertical span grows with pop
    base_span = 10
    extra_span = min(25, obs.city_pop // 40)
    target_span = base_span + extra_span
    tmin = max(2, cy - target_span)
    tmax = min(WORLD_H - 3, cy + target_span)

    wire_rows_in_col = sorted(r for (r, c) in wire_positions if c == wire_col)

    # --- Phase 2: extend wire spine vertically ---
    if not wire_rows_in_col:
        return (Tool.WIRE, wire_col, plant_cy)

    min_wr = min(wire_rows_in_col)
    max_wr = max(wire_rows_in_col)

    if max_wr < tmax:
        nr = max_wr + 1
        if 0 < nr < WORLD_H:
            return (Tool.WIRE, wire_col, nr)
    if min_wr > tmin:
        nr = min_wr - 1
        if 0 <= nr < WORLD_H:
            return (Tool.WIRE, wire_col, nr)

    wire_rows_set = set(wire_rows_in_col)

    # --- Phase 3: build road columns on BOTH sides of wire spine ---
    road_rows_L = set(r for (r, c) in road_positions if c == road_col_L)
    road_rows_R = set(r for (r, c) in road_positions if c == road_col_R)

    for wr in wire_rows_in_col:
        if wr not in road_rows_L and 0 <= road_col_L < WORLD_W:
            if em[wr, road_col_L]:
                return (Tool.ROAD, road_col_L, wr)
        if wr not in road_rows_R and 0 <= road_col_R < WORLD_W:
            if em[wr, road_col_R]:
                return (Tool.ROAD, road_col_R, wr)

    # --- Helper: check if 3x3 zone area is clear ---
    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def already_zone_nearby(zr, zc):
        return any(abs(zr - pr) <= 2 and abs(zc - pc) <= 2 for (pr, pc) in all_zones)

    # --- Phase 4: place zones adjacent to road/wire ---
    # Decide zone type: aim ~50% RES, ~25% COM, ~25% IND
    def pick_zone(zr, zc):
        # More industrial in lower half, more commercial in upper half
        if ind_count == 0 or (ind_count * 3 < res_count and zr >= cy):
            return Tool.INDUSTRIAL
        if com_count == 0 or (com_count * 3 < res_count):
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    road_rows_L_set = set(r for (r, c) in road_positions if c == road_col_L)
    road_rows_R_set = set(r for (r, c) in road_positions if c == road_col_R)

    for zr in wire_rows_in_col:
        road_L_nearby = any(abs(zr - rr) <= 2 for rr in road_rows_L_set)
        road_R_nearby = any(abs(zr - rr) <= 2 for rr in road_rows_R_set)

        # Left zone (needs left road)
        if road_L_nearby:
            zc = left_zone_col
            if 0 <= zc < WORLD_W and 2 <= zr < WORLD_H - 2:
                if not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                    return (pick_zone(zr, zc), zc, zr)

        # Right zone (needs right road)
        if road_R_nearby:
            zc = right_zone_col
            if 0 <= zc < WORLD_W and 2 <= zr < WORLD_H - 2:
                if not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                    return (pick_zone(zr, zc), zc, zr)

    # --- Phase 5: lateral wires from spine to left zones ---
    for wr in wire_rows_in_col:
        for wc in range(wire_col - 1, left_zone_col + 1, -1):
            if 0 <= wc < WORLD_W and em[wr, wc]:
                return (Tool.WIRE, wc, wr)

    # --- Phase 6: lateral roads from right road col to right zones ---
    for wr in wire_rows_in_col:
        for rc in range(road_col_R + 1, right_zone_col):
            if 0 <= rc < WORLD_W and em[wr, rc]:
                return (Tool.ROAD, rc, wr)

    # --- Phase 7: second corridor further right if pop growing ---
    if obs.city_pop > 200:
        wire_col2 = wire_col + 9
        road_col2L = wire_col2 - 1
        road_col2R = wire_col2 + 1
        left_zone_col2 = wire_col2 - 4
        right_zone_col2 = wire_col2 + 4

        wire_rows2 = sorted(r for (r, c) in wire_positions if c == wire_col2)

        # Build wire spine 2 by extending from existing wire rows horizontally first
        if not wire_rows2:
            # Connect horizontally from wire_col to wire_col2
            for wr in wire_rows_in_col:
                for wc in range(wire_col + 1, wire_col2 + 1):
                    if em[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                break  # just one row at a time
        else:
            min_wr2 = min(wire_rows2)
            max_wr2 = max(wire_rows2)
            if max_wr2 < tmax:
                nr = max_wr2 + 1
                if 0 < nr < WORLD_H:
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > tmin:
                nr = min_wr2 - 1
                if 0 <= nr < WORLD_H:
                    return (Tool.WIRE, wire_col2, nr)

            # Roads for second corridor
            road2L = set(r for (r, c) in road_positions if c == road_col2L)
            road2R = set(r for (r, c) in road_positions if c == road_col2R)
            for wr in wire_rows2:
                if wr not in road2L and 0 <= road_col2L < WORLD_W:
                    if em[wr, road_col2L]:
                        return (Tool.ROAD, road_col2L, wr)
                if wr not in road2R and 0 <= road_col2R < WORLD_W:
                    if em[wr, road_col2R]:
                        return (Tool.ROAD, road_col2R, wr)

            road2L_set = set(r for (r, c) in road_positions if c == road_col2L)
            road2R_set = set(r for (r, c) in road_positions if c == road_col2R)

            for zr in wire_rows2:
                if any(abs(zr - rr) <= 2 for rr in road2L_set):
                    zc = left_zone_col2
                    if 0 <= zc < WORLD_W and 2 <= zr < WORLD_H - 2:
                        if not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                            return (pick_zone(zr, zc), zc, zr)
                if any(abs(zr - rr) <= 2 for rr in road2R_set):
                    zc = right_zone_col2
                    if 0 <= zc < WORLD_W and 2 <= zr < WORLD_H - 2:
                        if not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                            return (pick_zone(zr, zc), zc, zr)

    # --- Phase 8: add services once pop is sufficient ---
    if obs.city_pop > 400:
        # Place fire station near center if not present
        fire_x, fire_y = wire_col + 6, cy - 5
        if 0 <= fire_x < WORLD_W and 0 <= fire_y < WORLD_H:
            if zone_area_free(fire_y, fire_x):
                return (Tool.FIRESTATION, fire_x, fire_y)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map every step and reacts to current state.
    Strategy:
    - Place coal power plant near center-left
    - Extend wire spine vertically from plant
    - Build road column adjacent to wire spine
    - Place zones on both sides of wire+road corridor
    - Add lateral wires to power left zones
    - Extend road to reach right zones
    - Expand outward as population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Phase 1: Place coal power plant if missing
    if not np.any(pm):
        return (Tool.COALPOWER, cx - 8, cy)

    # Find plant center by looking at plant tiles
    plant_rows, plant_cols = np.where(pm)
    # Use centroid of plant tiles
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Wire spine: just right of plant footprint
    wire_col = plant_cx + 2
    road_col = wire_col + 2  # road 2 tiles right of wire spine
    left_zone_col = wire_col - 3   # zone centers left of wire
    right_zone_col = road_col + 3  # zone centers right of road

    # Clamp columns
    wire_col = max(2, min(WORLD_W - 3, wire_col))
    road_col = max(2, min(WORLD_W - 3, road_col))
    left_zone_col = max(2, min(WORLD_W - 3, left_zone_col))
    right_zone_col = max(2, min(WORLD_W - 3, right_zone_col))

    # Current wire and road positions
    wire_rows_on_spine = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])
    road_rows_on_col = sorted([r for r in range(WORLD_H) if rm[r, road_col]])

    # How far to extend wire spine based on population
    if obs.city_pop < 100:
        spine_extent = 8
    elif obs.city_pop < 300:
        spine_extent = 14
    elif obs.city_pop < 600:
        spine_extent = 20
    else:
        spine_extent = 28

    target_min = max(1, cy - spine_extent)
    target_max = min(WORLD_H - 2, cy + spine_extent)

    # Phase 2: Start wire adjacent to plant if none on spine
    if not wire_rows_on_spine:
        for dy in range(0, 5):
            for nr in [plant_cy + dy, plant_cy - dy]:
                if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                    return (Tool.WIRE, wire_col, nr)
        return None

    min_wire_row = min(wire_rows_on_spine)
    max_wire_row = max(wire_rows_on_spine)

    # Phase 3: Extend wire spine downward
    if max_wire_row < target_max:
        nr = max_wire_row + 1
        if nr < WORLD_H and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Phase 4: Extend wire spine upward
    if min_wire_row > target_min:
        nr = min_wire_row - 1
        if nr >= 0 and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Phase 5: Build road column adjacent to wire spine
    for r in wire_rows_on_spine:
        if 0 <= r < WORLD_H and 0 <= road_col < WORLD_W:
            if not rm[r, road_col] and em[r, road_col]:
                return (Tool.ROAD, road_col, r)

    # Helper: check if 3x3 zone area is clear (empty or zone tiles only)
    all_zone_mask = resm | comm | indm
    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        # Check if zone center already placed (nearby zone tile)
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Phase 6: Place zones where wire AND road coverage exists
    zone_rows = list(range(max(1, target_min), min(WORLD_H - 1, target_max + 1), 3))

    for zr in zone_rows:
        wire_near = any(abs(zr - wr) <= 2 for wr in wire_rows_on_spine)
        road_near = any(abs(zr - rr) <= 2 for rr in road_rows_on_col)

        if wire_near and road_near:
            # Try left zone (powered by wire spine)
            zc = left_zone_col
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc) and has_road_nearby(zr, zc):
                    return (pick_tool(), zc, zr)
                elif has_wire_nearby(zr, zc, 6):
                    return (Tool.RESIDENTIAL, zc, zr)

            # Try right zone (powered by road which needs wire extension)
            zc = right_zone_col
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_road_nearby(zr, zc) and has_wire_nearby(zr, zc):
                    return (pick_tool(), zc, zr)

    # Phase 7: Lateral wires to connect left zones to spine
    for wr in wire_rows_on_spine:
        # Extend wire leftward from spine to left_zone_col
        for wc in range(wire_col - 1, left_zone_col - 2, -1):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc]:
                    break  # already wired to here
                if em[wr, wc] and not pm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc]:
                    break  # blocked

    # Phase 8: Road extensions to reach right zones
    for rr in wire_rows_on_spine:
        if not rm[rr, road_col]:
            continue
        for rc in range(road_col + 1, right_zone_col + 2):
            if 0 <= rc < WORLD_W:
                if rm[rr, rc]:
                    break
                if em[rr, rc] and not pm[rr, rc]:
                    return (Tool.ROAD, rc, rr)
                elif not em[rr, rc]:
                    break

    # Phase 9: Wire to right zone column for power
    for wr in wire_rows_on_spine:
        for wc in range(wire_col + 1, right_zone_col + 2):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)

    # Phase 10: Second coal plant if population demands more power
    if obs.city_pop > 400 and np.sum(pm) < 9:  # less than 2 plants
        # Place second plant further right
        px2, py2 = plant_cx + 18, plant_cy
        if 2 <= py2 <= WORLD_H - 3 and 2 <= px2 <= WORLD_W - 3:
            if em[py2, px2]:
                return (Tool.COALPOWER, px2, py2)

    # Phase 11: Expand coverage if city growing
    if obs.city_pop > 200:
        extra_zone_cols = [left_zone_col - 4, right_zone_col + 4]
        for zc in extra_zone_cols:
            if 2 <= zc <= WORLD_W - 3:
                for zr in zone_rows:
                    if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                        if has_road_nearby(zr, zc, 5) and has_wire_nearby(zr, zc, 6):
                            return (Tool.RESIDENTIAL, zc, zr)

    # Phase 12: Horizontal road segments connecting vertical spine to zones
    if obs.city_pop > 100:
        # Add horizontal roads at top/bottom of covered range
        h_road_rows = [min_wire_row + 1, max_wire_row - 1]
        for rr in h_road_rows:
            if 0 <= rr < WORLD_H:
                for rc in range(left_zone_col - 1, right_zone_col + 2):
                    if 0 <= rc < WORLD_W and em[rr, rc] and not pm[rr, rc]:
                        return (Tool.ROAD, rc, rr)

    return None

def act(obs, state):
    tm = obs.tile_map

    # Phase counter: 0=plant, 1=extend_wire, 2=extend_road, 3=place_zone
    if "phase" not in state:
        state["phase"] = 0
        state["step"] = 0

    state["step"] += 1

    cx, cy = WORLD_W // 2, WORLD_H // 2

    # --- Phase 0: Place coal power plant if not present ---
    plants = plant_mask(tm)
    if not plants.any():
        # Place coal plant
        return (Tool.COALPOWER, cx, cy)

    # Find plant location
    py_arr, px_arr = np.where(plants)
    # Use centroid of plant tiles
    px_c = int(px_arr.mean())
    py_c = int(py_arr.mean())

    wires = wire_mask(tm)
    roads = road_mask(tm)
    emp = empty_mask(tm)

    # --- Phase 1: Ensure wire connectivity from plant outward ---
    # Wire column: cx+1 going up and down from plant
    # We want a vertical wire spine at cx+1
    wire_col = cx + 1

    # Find topmost and bottommost wire in our column
    wire_in_col = wires[:, wire_col]
    road_in_col = roads[:, wire_col]

    # Build wire spine: extend from plant up and down
    # Check if plant area is wired - adjacent to plant
    # Plant center ~ (px_c, py_c), plant is 4 tiles (2x2 area for coal)
    # Wire should be adjacent to plant

    # Check wire connectivity: find wire tiles adjacent to plant
    # First ensure wire immediately right of plant top
    # Coal plant center placed at (cx, cy), it occupies ~(cx-1..cx+1, cy-1..cy+1)
    # Let's wire at (cx+2, cy) to connect outward

    # Strategy: wire spine at x = cx+2, road at x = cx+3
    wire_x = cx + 2
    road_x = cx + 3

    # Extend wire vertically - find gaps in wire column at wire_x
    wire_col_mask = wires[:, wire_x]

    # Find extent of existing wire
    if wire_col_mask.any():
        wire_ys = np.where(wire_col_mask)[0]
        wire_min = wire_ys.min()
        wire_max = wire_ys.max()
    else:
        # No wire yet - place first wire adjacent to plant
        # Plant at cx,cy - place wire to its right
        return (Tool.WIRE, wire_x, cy)

    # Extend wire up or down if range < 20 tiles
    target_min = cy - 12
    target_max = cy + 12

    if wire_min > target_min:
        ny = wire_min - 1
        if 0 <= ny < WORLD_H:
            return (Tool.WIRE, wire_x, ny)
    if wire_max < target_max:
        ny = wire_max + 1
        if 0 <= ny < WORLD_H:
            return (Tool.WIRE, wire_x, ny)

    # --- Phase 2: Extend road parallel to wire ---
    road_col_mask = roads[:, road_x]
    if road_col_mask.any():
        road_ys = np.where(road_col_mask)[0]
        road_min = road_ys.min()
        road_max = road_ys.max()
    else:
        return (Tool.ROAD, road_x, cy)

    if road_min > target_min:
        ny = road_min - 1
        if 0 <= ny < WORLD_H:
            return (Tool.ROAD, road_x, ny)
    if road_max < target_max:
        ny = road_max + 1
        if 0 <= ny < WORLD_H:
            return (Tool.ROAD, road_x, ny)

    # --- Phase 3: Place zones adjacent to road ---
    # Residential zones at cx+5 (center, so 3x3 fits), spaced every 3 rows
    # Also try commercial and industrial for variety
    res = res_mask(tm)
    com = com_mask(tm)
    ind = ind_mask(tm)

    # Zone columns: left side and right side of road
    zone_cols_left = [road_x - 3]   # left of road
    zone_cols_right = [road_x + 3]  # right of road

    # Scan for empty spots at zone rows
    for row in range(target_min + 1, target_max, 3):
        if row < 1 or row >= WORLD_H - 1:
            continue
        for zx in zone_cols_left + zone_cols_right:
            if zx < 1 or zx >= WORLD_W - 1:
                continue
            # Check if zone center is empty
            if emp[row, zx]:
                # Decide zone type based on position
                zone_count = int(res.sum() + com.sum() + ind.sum())
                if obs.res_pop < obs.com_pop * 3 + obs.ind_pop * 2:
                    tool = Tool.RESIDENTIAL
                elif obs.com_pop < obs.res_pop // 3:
                    tool = Tool.COMMERCIAL
                elif obs.ind_pop < obs.res_pop // 4:
                    tool = Tool.INDUSTRIAL
                else:
                    tool = Tool.RESIDENTIAL
                return (tool, zx, row)

    # --- Phase 4: Closed-loop reactive expansion ---
    # Find residential zones and expand outward
    res_arr = res_mask(tm)
    emp_arr = empty_mask(tm)

    # Find candidates: empty tiles neighboring existing zones
    nbr = np.zeros_like(emp_arr)
    nbr[1:, :] |= res_arr[:-1, :]
    nbr[:-1, :] |= res_arr[1:, :]
    nbr[:, 1:] |= res_arr[:, :-1]
    nbr[:, :-1] |= res_arr[:, 1:]

    cand = emp_arr & nbr
    ys, xs = np.where(cand)

    if len(xs) > 0:
        # Pick candidate nearest to road
        dists = np.abs(xs - road_x)
        k = int(np.argmin(dists))
        # Decide what to place based on current city needs
        if obs.com_pop * 4 < obs.res_pop:
            tool = Tool.COMMERCIAL
        elif obs.ind_pop * 5 < obs.res_pop:
            tool = Tool.INDUSTRIAL
        else:
            tool = Tool.RESIDENTIAL
        return (tool, int(xs[k]), int(ys[k]))

    # Fallback: extend wire/road further
    # Try adding road cross-streets
    road_row_candidates = list(range(target_min, target_max + 1, 3))
    for rr in road_row_candidates:
        if 0 <= rr < WORLD_H:
            for cx2 in range(road_x - 5, road_x + 6):
                if 0 <= cx2 < WORLD_W and emp[rr, cx2]:
                    return (Tool.ROAD, cx2, rr)

    return None

def act(obs, state):
    """
    Hybrid policy combining Parent A's multi-neighborhood planning with
    Parent B's reactive closed-loop approach.

    Strategy:
    - Build a compact, powered, road-served cluster near center
    - Coal plant first, then wire spine, then road column, then zones
    - Expand with multiple columns as population grows
    - Use reactive phase detection to fill gaps
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    # Center of operations
    cx, cy = 55, 50

    has_plant = np.any(pm)
    has_wire = np.any(wm)
    has_road = np.any(rm)

    # Phase 1: Place coal power plant
    plant_cx, plant_cy = cx - 8, cy
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Gather positions
    wire_positions = set(zip(*np.where(wm))) if has_wire else set()
    road_positions = set(zip(*np.where(rm))) if has_road else set()
    res_positions = set(zip(*np.where(res_mask(tm))))
    com_positions = set(zip(*np.where(com_mask(tm))))
    ind_positions = set(zip(*np.where(ind_mask(tm))))
    all_zones = res_positions | com_positions | ind_positions

    res_count = len(res_positions)
    com_count = len(com_positions)
    ind_count = len(ind_positions)
    total_zones = res_count + com_count + ind_count + 1

    # Wire spine column (just right of plant footprint)
    wire_col = plant_cx + 3   # main wire spine
    road_col1 = wire_col + 1  # first road column (right of wire)
    road_col2 = wire_col - 1  # second road column (left of wire)

    # Zone columns
    right_zone_col1 = road_col1 + 3
    left_zone_col1 = road_col2 - 3

    # Vertical span based on population
    base_span = 10
    extra_span = min(25, obs.city_pop // 30)
    target_span = base_span + extra_span
    tmin = max(2, cy - target_span)
    tmax = min(WORLD_H - 3, cy + target_span)

    # Phase 2: Extend wire spine vertically
    wire_rows_in_col = sorted(r for (r, c) in wire_positions if c == wire_col)

    if not wire_rows_in_col:
        # Place first wire adjacent to plant
        if 0 <= plant_cy < WORLD_H and em[plant_cy, wire_col]:
            return (Tool.WIRE, wire_col, plant_cy)
        else:
            for dy in range(-2, 3):
                ny = plant_cy + dy
                if 0 <= ny < WORLD_H and em[ny, wire_col]:
                    return (Tool.WIRE, wire_col, ny)
    else:
        min_wr = min(wire_rows_in_col)
        max_wr = max(wire_rows_in_col)
        # Extend downward first
        if max_wr < tmax:
            nr = max_wr + 1
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if min_wr > tmin:
            nr = min_wr - 1
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    wire_rows_set = set(wire_rows_in_col)

    # Phase 3: Build road columns adjacent to wire
    if wire_rows_in_col:
        # Right road column
        road_rows_right = set(r for (r, c) in road_positions if c == road_col1)
        for wr in wire_rows_in_col:
            if wr not in road_rows_right and 0 <= road_col1 < WORLD_W:
                if em[wr, road_col1]:
                    return (Tool.ROAD, road_col1, wr)
        # Left road column
        road_rows_left = set(r for (r, c) in road_positions if c == road_col2)
        for wr in wire_rows_in_col:
            if wr not in road_rows_left and 0 <= road_col2 >= 0:
                if em[wr, road_col2]:
                    return (Tool.ROAD, road_col2, wr)

    # Helper functions
    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def already_zone_nearby(zr, zc):
        return any(abs(zr - pr) <= 1 and abs(zc - pc) <= 1 for (pr, pc) in all_zones)

    def choose_zone_type(zc, zr):
        # Aim for ~50% res, ~25% com, ~25% ind
        if ind_count * 4 < res_count and zc == left_zone_col1:
            return Tool.INDUSTRIAL
        elif com_count * 4 < res_count and zc == right_zone_col1:
            return Tool.COMMERCIAL
        else:
            return Tool.RESIDENTIAL

    # Phase 4: Place zones adjacent to road/wire
    road_rows_right2 = set(r for (r, c) in road_positions if c == road_col1)
    road_rows_left2 = set(r for (r, c) in road_positions if c == road_col2)

    zone_rows = sorted(wire_rows_in_col)
    for zr in zone_rows:
        road_nearby_right = any(abs(zr - rr) <= 2 for rr in road_rows_right2)
        road_nearby_left = any(abs(zr - rr) <= 2 for rr in road_rows_left2)
        wire_nearby = any(abs(zr - wr) <= 1 for wr in wire_rows_set)

        if not wire_nearby:
            continue

        # Right zone column
        if road_nearby_right:
            zc = right_zone_col1
            if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                if not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                    tool = choose_zone_type(zc, zr)
                    return (tool, zc, zr)

        # Left zone column
        if road_nearby_left:
            zc = left_zone_col1
            if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                if not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                    tool = choose_zone_type(zc, zr)
                    return (tool, zc, zr)

    # Phase 5: Add lateral roads/wires to reach zones
    for wr in wire_rows_in_col:
        # Lateral road to right zone
        for rc in range(road_col1 + 1, right_zone_col1):
            if 0 <= rc < WORLD_W and em[wr, rc]:
                return (Tool.ROAD, rc, wr)
        # Lateral wire to left zone
        for wc in range(wire_col - 1, left_zone_col1 + 1, -1):
            if 0 <= wc < WORLD_W and em[wr, wc]:
                return (Tool.WIRE, wc, wr)

    # Phase 6: Second expansion cluster when population is growing
    if obs.city_pop > 200:
        # Add a second wire/road/zone column further right
        wire_col2 = right_zone_col1 + 4
        road_col3 = wire_col2 + 1
        right_zone_col2 = road_col3 + 3

        wire_rows_col2 = sorted(r for (r, c) in wire_positions if c == wire_col2)

        if not wire_rows_col2:
            # Connect wire horizontally from main spine at cy
            if 0 <= cy < WORLD_H and em[cy, wire_col2]:
                # First lay horizontal wire connection
                for wc in range(wire_col + 1, wire_col2 + 1):
                    if 0 <= wc < WORLD_W and em[cy, wc]:
                        return (Tool.WIRE, wc, cy)
        else:
            min_wr2 = min(wire_rows_col2)
            max_wr2 = max(wire_rows_col2)
            tmax2 = min(WORLD_H - 3, cy + target_span)
            tmin2 = max(2, cy - target_span)

            if max_wr2 < tmax2:
                nr = max_wr2 + 1
                if 0 <= nr < WORLD_H and (em[nr, wire_col2] or wm[nr, wire_col2]):
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > tmin2:
                nr = min_wr2 - 1
                if 0 <= nr < WORLD_H and (em[nr, wire_col2] or wm[nr, wire_col2]):
                    return (Tool.WIRE, wire_col2, nr)

            # Build road col3
            road_rows_col3 = set(r for (r, c) in road_positions if c == road_col3)
            for wr in wire_rows_col2:
                if wr not in road_rows_col3 and 0 <= road_col3 < WORLD_W:
                    if em[wr, road_col3]:
                        return (Tool.ROAD, road_col3, wr)

            # Place zones
            road_rows_col3_list = sorted(r for (r, c) in road_positions if c == road_col3)
            for zr in sorted(wire_rows_col2):
                wire_nearby2 = any(abs(zr - wr) <= 1 for wr in wire_rows_col2)
                road_nearby2 = any(abs(zr - rr) <= 2 for rr in road_rows_col3_list)
                if wire_nearby2 and road_nearby2:
                    zc = right_zone_col2
                    if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                        if not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                            if com_count * 4 < res_count:
                                return (Tool.COMMERCIAL, zc, zr)
                            else:
                                return (Tool.RESIDENTIAL, zc, zr)

            # Lateral roads to right zone col2
            for wr in wire_rows_col2:
                for rc in range(road_col3 + 1, right_zone_col2):
                    if 0 <= rc < WORLD_W and em[wr, rc]:
                        return (Tool.ROAD, rc, wr)

    # Phase 7: If still idle, add a second coal plant for more power when large
    if obs.city_pop > 500 and not state.get("second_plant", False):
        plant2_cx, plant2_cy = cx + 20, cy
        # Check if area is empty enough
        plant2_clear = True
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = plant2_cy + dr, plant2_cx + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if not em[rr, rc]:
                        plant2_clear = False
                        break
        if plant2_clear:
            state["second_plant"] = True
            return (Tool.COALPOWER, plant2_cx, plant2_cy)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads current map each step
    - Extends power/road/zones from what already exists
    - Compact single cluster near center
    """
    tm = obs.tile_map
    step = obs.step

    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # Cluster center
    cx, cy = 55, 50

    # Phase 1: Place coal power plant if none exists
    if not np.any(pm):
        return (Tool.COALPOWER, cx - 20, cy)

    # Get current positions
    plant_ys, plant_xs = np.where(pm)
    wire_ys, wire_xs = np.where(wm)
    road_ys, road_xs = np.where(rm)
    res_ys, res_xs = np.where(res_m)
    com_ys, com_xs = np.where(com_m)
    ind_ys, ind_xs = np.where(ind_m)

    plant_positions = list(zip(plant_ys.tolist(), plant_xs.tolist()))
    wire_positions = list(zip(wire_ys.tolist(), wire_xs.tolist()))
    road_positions = list(zip(road_ys.tolist(), road_xs.tolist()))
    res_positions = list(zip(res_ys.tolist(), res_xs.tolist()))
    com_positions = list(zip(com_ys.tolist(), com_xs.tolist()))
    ind_positions = list(zip(ind_ys.tolist(), ind_xs.tolist()))
    all_zone_pos = res_positions + com_positions + ind_positions

    res_count = len(res_positions)
    com_count = len(com_positions)
    ind_count = len(ind_positions)
    total_zones = res_count + com_count + ind_count

    # Second power plant if we have many zones but only one plant
    num_plants = len(plant_positions)
    if num_plants < 2 and total_zones > 8:
        return (Tool.COALPOWER, cx + 20, cy)

    # Helper: check if 3x3 area centered at (cr,cc) is all empty
    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    # Choose zone type to balance 50% res, 25% com, 25% ind
    def pick_zone_type():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        r_frac = res_count / (total_zones + 1)
        c_frac = com_count / (total_zones + 1)
        i_frac = ind_count / (total_zones + 1)
        if c_frac < 0.25:
            return Tool.COMMERCIAL
        elif i_frac < 0.25:
            return Tool.INDUSTRIAL
        else:
            return Tool.RESIDENTIAL

    # Phase 2: Extend wire from nearest wire/plant toward cluster center
    # Wire spine: horizontal at row cy from plant to cx+25
    # Find leftmost plant x
    plant_min_x = min(plant_xs.tolist()) if len(plant_xs) > 0 else cx - 20
    plant_max_x = max(plant_xs.tolist()) if len(plant_xs) > 0 else cx - 20

    # Wire horizontal spine at cy
    spine_row = cy
    # We want wire from plant_min_x+3 to cx+25
    wire_target_end = cx + 25

    # Find rightmost wire on spine row
    spine_wire_cols = [c for (r, c) in wire_positions if r == spine_row]
    if spine_wire_cols:
        max_wc = max(spine_wire_cols)
    else:
        max_wc = plant_min_x + 2  # start just after plant footprint

    if max_wc < wire_target_end:
        nc = max_wc + 1
        if 0 <= nc < WORLD_W and em[spine_row, nc]:
            return (Tool.WIRE, nc, spine_row)

    # Phase 3: Build horizontal road at cy-2 (just above spine)
    road_row = cy - 2
    road_wire_cols = [c for (r, c) in road_positions if r == road_row]
    road_start = plant_min_x + 3
    road_end = wire_target_end + 3
    if road_wire_cols:
        max_rc = max(road_wire_cols)
    else:
        max_rc = road_start - 1
    if max_rc < road_end:
        nc = max_rc + 1
        if 0 <= nc < WORLD_W and em[road_row, nc]:
            return (Tool.ROAD, nc, road_row)

    # Phase 4: Build horizontal road at cy+2 (just below spine)
    road_row2 = cy + 2
    road_wire_cols2 = [c for (r, c) in road_positions if r == road_row2]
    if road_wire_cols2:
        max_rc2 = max(road_wire_cols2)
    else:
        max_rc2 = road_start - 1
    if max_rc2 < road_end:
        nc = max_rc2 + 1
        if 0 <= nc < WORLD_W and em[road_row2, nc]:
            return (Tool.ROAD, nc, road_row2)

    # Phase 5: Add vertical connector roads every 6 cols between the two road rows
    for conn_col in range(road_start, road_end + 1, 6):
        for conn_row in range(road_row, road_row2 + 1):
            if 0 <= conn_col < WORLD_W and 0 <= conn_row < WORLD_H:
                if not rm[conn_row, conn_col] and em[conn_row, conn_col]:
                    return (Tool.ROAD, conn_col, conn_row)

    # Phase 6: Add vertical wires from spine up/down to power zone rows
    zone_rows_above = [cy - 5, cy - 8, cy - 11, cy - 14, cy - 17]
    zone_rows_below = [cy + 5, cy + 8, cy + 11, cy + 14, cy + 17]
    zone_cols = list(range(road_start + 2, road_end, 6))

    for zc in zone_cols:
        if not (0 <= zc < WORLD_W):
            continue
        # Wire upward from spine
        for zr in zone_rows_above:
            if not (0 <= zr < WORLD_H):
                continue
            for wr in range(spine_row - 1, zr - 1, -1):
                if 0 <= wr < WORLD_H:
                    if not wm[wr, zc] and not rm[wr, zc]:
                        if em[wr, zc]:
                            return (Tool.WIRE, zc, wr)
                        break
                    elif wm[wr, zc]:
                        continue
                    else:
                        break
        # Wire downward from spine
        for zr in zone_rows_below:
            if not (0 <= zr < WORLD_H):
                continue
            for wr in range(spine_row + 1, zr + 2):
                if 0 <= wr < WORLD_H:
                    if not wm[wr, zc] and not rm[wr, zc]:
                        if em[wr, zc]:
                            return (Tool.WIRE, zc, wr)
                        break
                    elif wm[wr, zc]:
                        continue
                    else:
                        break

    # Phase 7: Place zones adjacent to roads, powered by wires nearby
    # Reactively scan each candidate zone position
    for zr in zone_rows_above + zone_rows_below:
        for zc in zone_cols:
            if not (2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2):
                continue
            # Check road access (road within 2 tiles)
            road_near = False
            for dr in range(-2, 3):
                for dc in range(-2, 3):
                    nr, nc = zr + dr, zc + dc
                    if 0 <= nr < WORLD_H and 0 <= nc < WORLD_W:
                        if rm[nr, nc]:
                            road_near = True
                            break
                if road_near:
                    break
            if not road_near:
                continue
            # Check wire access (wire within 5 tiles)
            wire_near = False
            for dr in range(-5, 6):
                for dc in range(-5, 6):
                    nr, nc = zr + dr, zc + dc
                    if 0 <= nr < WORLD_H and 0 <= nc < WORLD_W:
                        if wm[nr, nc] or pm[nr, nc]:
                            wire_near = True
                            break
                if wire_near:
                    break
            if not wire_near:
                continue
            # Check no existing zone nearby
            zone_near = False
            for (pr, pc) in all_zone_pos:
                if abs(zr - pr) <= 2 and abs(zc - pc) <= 2:
                    zone_near = True
                    break
            if zone_near:
                continue
            if zone_area_free(zr, zc):
                return (pick_zone_type(), zc, zr)

    # Phase 8: Expand zone columns if doing well
    if obs.city_pop > 50 or total_zones > 6:
        extra_cols = list(range(road_start - 4, road_start, 6)) + list(range(road_end + 2, road_end + 14, 6))
        for zc in extra_cols:
            for zr in zone_rows_above + zone_rows_below:
                if not (2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2):
                    continue
                road_near = False
                for dr in range(-3, 4):
                    for dc in range(-3, 4):
                        nr, nc2 = zr + dr, zc + dc
                        if 0 <= nr < WORLD_H and 0 <= nc2 < WORLD_W:
                            if rm[nr, nc2]:
                                road_near = True
                                break
                    if road_near:
                        break
                if not road_near:
                    continue
                zone_near = False
                for (pr, pc) in all_zone_pos:
                    if abs(zr - pr) <= 2 and abs(zc - pc) <= 2:
                        zone_near = True
                        break
                if zone_near:
                    continue
                if zone_area_free(zr, zc):
                    return (pick_zone_type(), zc, zr)

    # Fallback: extend road/wire a bit more
    if max_wc < wire_target_end + 10:
        nc = max_wc + 1
        if 0 <= nc < WORLD_W and em[spine_row, nc]:
            return (Tool.WIRE, nc, spine_row)

    return None

def act(obs, state):
    """
    Improved city builder with:
    - TWO neighborhoods (left cluster + right cluster)
    - Better wire routing (wire before roads, connect to zones)
    - Mixed zoning: residential, commercial, industrial balanced
    - More aggressive road + zone placement
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    # Two cluster centers
    CX1, CY1 = 30, 40   # left cluster
    CX2, CY2 = 75, 60   # right cluster

    has_plant = np.any(pm)
    plant_ys, plant_xs = np.where(pm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Phase 1: Place first power plant ---
    if not has_plant:
        return (Tool.COALPOWER, CX1, CY1)

    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    wire_ys, wire_xs = np.where(wm)
    road_ys, road_xs = np.where(rm)
    res_ys, res_xs = np.where(resm)
    com_ys, com_xs = np.where(comm)
    ind_ys, ind_xs = np.where(indm)

    wire_set = set(zip(wire_ys.tolist(), wire_xs.tolist()))
    road_set = set(zip(road_ys.tolist(), road_xs.tolist()))
    zone_set = set(zip(
        np.concatenate([res_ys, com_ys, ind_ys]).tolist(),
        np.concatenate([res_xs, com_xs, ind_xs]).tolist()
    ))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    num_plants = int(np.sum(pm)) // 6  # rough plant count (6x6 = ~6 tiles each)

    def can_wire(x, y):
        return in_bounds(x, y) and bool(em[y, x]) and not bool(pm[y, x])

    def can_road(x, y):
        return in_bounds(x, y) and not bool(pm[y, x])

    def has_road_near(zx, zy, r=3):
        for dr in range(-r, r+1):
            for dc in range(-r, r+1):
                if (zy+dr, zx+dc) in road_set:
                    return True
        return False

    def has_wire_near(zx, zy, r=5):
        for dr in range(-r, r+1):
            for dc in range(-r, r+1):
                nr, nc = zy+dr, zx+dc
                if (nr, nc) in wire_set:
                    return True
                if in_bounds(nc, nr) and pm[nr, nc]:
                    return True
        return False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy+dr, zx+dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    def pick_tool(total, res, com, ind):
        # Target: 50% res, 25% com, 25% ind
        if total == 0:
            return Tool.RESIDENTIAL
        if com / max(total, 1) < 0.25:
            return Tool.COMMERCIAL
        if ind / max(total, 1) < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # --- Phase 2: Wire from plant - horizontal spine right ---
    spine_y = py
    spine_x = px
    # Wire right from plant
    for dx in range(1, 55):
        wx, wy = spine_x + dx, spine_y
        if not in_bounds(wx, wy):
            break
        if (wy, wx) not in wire_set and can_wire(wx, wy):
            return (Tool.WIRE, wx, wy)
        elif not (bool(wm[wy, wx]) or bool(pm[wy, wx])):
            break

    # Wire up from plant
    for dy in range(1, 20):
        wx, wy = spine_x, spine_y - dy
        if not in_bounds(wx, wy):
            break
        if (wy, wx) not in wire_set and can_wire(wx, wy):
            return (Tool.WIRE, wx, wy)
        elif not (bool(wm[wy, wx]) or bool(pm[wy, wx])):
            break

    # Wire down from plant
    for dy in range(1, 20):
        wx, wy = spine_x, spine_y + dy
        if not in_bounds(wx, wy):
            break
        if (wy, wx) not in wire_set and can_wire(wx, wy):
            return (Tool.WIRE, wx, wy)
        elif not (bool(wm[wy, wx]) or bool(pm[wy, wx])):
            break

    # --- Phase 3: Second power plant for right cluster ---
    # Place when wire reaches near CX2
    wire_right = max([c for (r, c) in wire_set], default=spine_x)
    if wire_right >= CX2 - 5 and not any(pm[CY2-1:CY2+2, CX2-1:CX2+2].any() for _ in [0]):
        # Check if second plant already placed near CX2, CY2
        area = pm[max(0,CY2-5):min(WORLD_H,CY2+5), max(0,CX2-5):min(WORLD_W,CX2+5)]
        if not np.any(area):
            if in_bounds(CX2, CY2) and em[CY2, CX2]:
                return (Tool.COALPOWER, CX2, CY2)

    # --- Phase 4: Road grid for cluster 1 ---
    # Roads flanking the wire spine (rows py-4 and py+4)
    r1_top = py - 4
    r1_bot = py + 4
    road_start1 = spine_x + 2
    road_end1 = min(spine_x + 28, WORLD_W - 3)

    # Horizontal top road cluster 1
    for cx in range(road_start1, road_end1 + 1):
        if in_bounds(cx, r1_top) and (r1_top, cx) not in road_set and can_road(cx, r1_top):
            return (Tool.ROAD, cx, r1_top)

    # Horizontal bottom road cluster 1
    for cx in range(road_start1, road_end1 + 1):
        if in_bounds(cx, r1_bot) and (r1_bot, cx) not in road_set and can_road(cx, r1_bot):
            return (Tool.ROAD, cx, r1_bot)

    # Vertical connectors cluster 1 every 4 cols
    for vc in range(road_start1, road_end1 + 1, 4):
        for vr in range(r1_top, r1_bot + 1):
            if in_bounds(vc, vr) and (vr, vc) not in road_set and can_road(vc, vr):
                return (Tool.ROAD, vc, vr)

    # --- Phase 5: Road grid for cluster 2 ---
    r2_top = CY2 - 4
    r2_bot = CY2 + 4
    road_start2 = CX2 - 12
    road_end2 = CX2 + 15

    for cx in range(road_start2, road_end2 + 1):
        if in_bounds(cx, r2_top) and (r2_top, cx) not in road_set and can_road(cx, r2_top):
            return (Tool.ROAD, cx, r2_top)

    for cx in range(road_start2, road_end2 + 1):
        if in_bounds(cx, r2_bot) and (r2_bot, cx) not in road_set and can_road(cx, r2_bot):
            return (Tool.ROAD, cx, r2_bot)

    for vc in range(road_start2, road_end2 + 1, 4):
        for vr in range(r2_top, r2_bot + 1):
            if in_bounds(vc, vr) and (vr, vc) not in road_set and can_road(vc, vr):
                return (Tool.ROAD, vc, vr)

    # --- Phase 6: Place zones cluster 1 ---
    zone_rows1 = [r1_top - 2, r1_top - 5, r1_top - 8, r1_bot + 2, r1_bot + 5, r1_bot + 8]
    zone_cols1 = list(range(road_start1 + 1, road_end1, 4))

    for zr in zone_rows1:
        for zc in zone_cols1:
            if not (2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3):
                continue
            if zone_clear(zc, zr) and has_road_near(zc, zr) and has_wire_near(zc, zr):
                return (pick_tool(total_zones, res_count, com_count, ind_count), zc, zr)

    # --- Phase 7: Place zones cluster 2 ---
    zone_rows2 = [r2_top - 2, r2_top - 5, r2_top - 8, r2_bot + 2, r2_bot + 5, r2_bot + 8]
    zone_cols2 = list(range(road_start2 + 1, road_end2, 4))

    for zr in zone_rows2:
        for zc in zone_cols2:
            if not (2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3):
                continue
            if zone_clear(zc, zr) and has_road_near(zc, zr) and has_wire_near(zc, zr):
                return (pick_tool(total_zones, res_count, com_count, ind_count), zc, zr)

    # --- Phase 8: Wire branch to cluster 2 if not yet connected ---
    # Extend wire toward CX2 from existing wire frontier
    right_frontier = max([c for (r, c) in wire_set if r == spine_y], default=spine_x)
    if right_frontier < CX2 - 2:
        wy, wx = spine_y, right_frontier + 1
        if in_bounds(wx, wy) and can_wire(wx, wy):
            return (Tool.WIRE, wx, wy)

    # Wire branches at CX2 vertical
    for dy in range(1, 15):
        for sign in [-1, 1]:
            wx, wy = CX2, CY2 + sign * dy
            if not in_bounds(wx, wy):
                continue
            if (wy, wx) not in wire_set and can_wire(wx, wy):
                return (Tool.WIRE, wx, wy)

    # --- Phase 9: Services ---
    if obs.city_pop > 100:
        fx, fy = spine_x + 3, py - 12
        if in_bounds(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
        fx2, fy2 = spine_x + 3, py + 12
        if in_bounds(fx2, fy2) and em[fy2, fx2]:
            return (Tool.POLICESTATION, fx2, fy2)

    if obs.city_pop > 500:
        fx3, fy3 = CX2 + 3, CY2 - 12
        if in_bounds(fx3, fy3) and em[fy3, fx3]:
            return (Tool.FIRESTATION, fx3, fy3)
        fx4, fy4 = CX2 + 3, CY2 + 12
        if in_bounds(fx4, fy4) and em[fy4, fx4]:
            return (Tool.POLICESTATION, fx4, fy4)

    # --- Phase 10: Reactive zone fill near roads and wires ---
    # Dilate road mask
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand = em & nbr_road & nbr_wire
    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        k = int((obs.step * 13 + int(tm.sum()) % 97)) % len(cxs)
        zx, zy = int(cxs[k]), int(cys[k])
        if zone_clear(zx, zy):
            return (pick_tool(total_zones, res_count, com_count, ind_count), zx, zy)

    # Last resort: extend road
    if len(road_xs) > 0:
        k = int(obs.step * 11) % len(road_xs)
        rx, ry = int(road_xs[k]), int(road_ys[k])
        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx + dx, ry + dy
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Improved city builder with better zone placement and power connectivity.
    Key changes from parent:
    1. Place power plant first, then immediately run wires TO zones (not away)
    2. Build road grid FIRST, then power, ensuring connectivity
    3. Use a denser, more organized grid layout
    4. Better zone placement ensuring road adjacency
    5. Two neighborhoods: left cluster and right cluster
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

