    if 'phase' not in state:
        state['phase'] = 0
        state['action_queue'] = []

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Use a pre-planned action queue approach
    # Build the plan once and execute it
    if 'plan' not in state:
        plan = []

        # Cluster 1: centered at (35, 45)
        # Power plant at (10, 45)
        PP1X, PP1Y = 10, 45
        plan.append((Tool.COALPOWER, PP1X, PP1Y))

        # Wire horizontally from plant to cluster
        for x in range(PP1X + 2, 70):
            plan.append((Tool.WIRE, x, PP1Y))

        # Wire vertically at x=68 to cover more rows
        for y in range(30, 65):
            plan.append((Tool.WIRE, 68, y))

        # Build horizontal roads at y=38, y=42, y=48, y=52, y=56
        road_rows = [38, 42, 48, 52, 56]
        road_x_start = 15
        road_x_end = 65
        for ry in road_rows:
            for rx in range(road_x_start, road_x_end + 1):
                plan.append((Tool.ROAD, rx, ry))

        # Build vertical roads every 6 columns
        for rx in range(road_x_start, road_x_end + 1, 6):
            for ry in range(road_rows[0], road_rows[-1] + 1):
                plan.append((Tool.ROAD, rx, ry))

        # Wire spine at y=45 (middle) connecting to zones
        for x in range(road_x_start, road_x_end + 1):
            plan.append((Tool.WIRE, x, 45))

        # Vertical wires at road columns to distribute power
        for rx in range(road_x_start, road_x_end + 1, 6):
            for ry in range(road_rows[0] - 2, road_rows[-1] + 3):
                plan.append((Tool.WIRE, rx, ry))

        # Place zones in the grid cells between roads
        # Zones go at centers of 3x3 blocks between road rows
        # Between road_rows[0]=38 and road_rows[1]=42: centers at y=40
        # Between road_rows[1]=42 and road_rows[2]=48: centers at y=45 (wire row, skip)
        # Between road_rows[2]=48 and road_rows[3]=52: centers at y=50
        # etc.
        zone_y_positions = [35, 40, 50, 55, 60]
        zone_x_positions = list(range(road_x_start + 3, road_x_end - 2, 6))

        # Mix of zones: 50% R, 25% C, 25% I
        zone_idx = 0
        for zy in zone_y_positions:
            for zx in zone_x_positions:
                if not in_bounds(zx, zy):
                    continue
                mod = zone_idx % 4
                if mod == 0 or mod == 1:
                    t = Tool.RESIDENTIAL
                elif mod == 2:
                    t = Tool.COMMERCIAL
                else:
                    t = Tool.INDUSTRIAL
                plan.append((t, zx, zy))
                zone_idx += 1

        # Second cluster: centered at (90, 50)
        PP2X, PP2Y = 75, 50
        plan.append((Tool.COALPOWER, PP2X, PP2Y))

        # Wire from PP2 outward
        for x in range(PP2X + 2, 115):
            plan.append((Tool.WIRE, x, PP2Y))
        for y in range(35, 65):
            plan.append((Tool.WIRE, PP2X + 1, y))
        for y in range(35, 65):
            plan.append((Tool.WIRE, 110, y))

        # Roads for second cluster
        road2_x_start = 78
        road2_x_end = 112
        for ry in road_rows:
            for rx in range(road2_x_start, road2_x_end + 1):
                plan.append((Tool.ROAD, rx, ry))
        for rx in range(road2_x_start, road2_x_end + 1, 6):
            for ry in range(road_rows[0], road_rows[-1] + 1):
                plan.append((Tool.ROAD, rx, ry))

        # Wire spine for second cluster
        for x in range(road2_x_start, road2_x_end + 1):
            plan.append((Tool.WIRE, x, 50))
        for rx in range(road2_x_start, road2_x_end + 1, 6):
            for ry in range(road_rows[0] - 2, road_rows[-1] + 3):
                plan.append((Tool.WIRE, rx, ry))

        # Zones for second cluster
        zone_x_positions2 = list(range(road2_x_start + 3, road2_x_end - 2, 6))
        for zy in zone_y_positions:
            for zx in zone_x_positions2:
                if not in_bounds(zx, zy):
                    continue
                mod = zone_idx % 4
                if mod == 0 or mod == 1:
                    t = Tool.RESIDENTIAL
                elif mod == 2:
                    t = Tool.COMMERCIAL
                else:
                    t = Tool.INDUSTRIAL
                plan.append((t, zx, zy))
                zone_idx += 1

        # Services
        plan.append((Tool.FIRESTATION, 35, 33))
        plan.append((Tool.POLICESTATION, 45, 33))
        plan.append((Tool.FIRESTATION, 90, 33))
        plan.append((Tool.POLICESTATION, 100, 33))

        # Connect the two clusters with a road
        for rx in range(road_x_end + 1, road2_x_start):
            plan.append((Tool.ROAD, rx, 48))
        for rx in range(road_x_end + 1, road2_x_start):
            plan.append((Tool.WIRE, rx, 48))

        state['plan'] = plan
        state['plan_idx'] = 0

    # Execute plan steps, but skip already-placed tiles
    plan = state['plan']
    idx = state['plan_idx']

    # Try to find an action that makes sense
    attempts = 0
    while idx < len(plan) and attempts < 50:
        action = plan[idx]
        idx += 1
        attempts += 1
        tool, x, y = action

        if not in_bounds(x, y):
            continue

        # Skip if it's a zone placement and area is not clear
        if tool in (Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.INDUSTRIAL):
            # Check 3x3 area is mostly clear
            clear = True
            for dy in range(-1, 2):
                for dx in range(-1, 2):
                    nx, ny = x + dx, y + dy
                    if not in_bounds(nx, ny):
                        clear = False
                        break
                    # Allow empty, road (will be bulldozed), or zone tiles
                    tile = tm[ny, nx]
                    if not (em[ny, nx] or rm[ny, nx]):
                        clear = False
                        break
                if not clear:
                    break
            if not clear:
                continue
            # Check road nearby
            has_road = False
            for dy in range(-4, 5):
                for dx in range(-4, 5):
                    nx2, ny2 = x + dx, y + dy
                    if in_bounds(nx2, ny2) and rm[ny2, nx2]:
                        has_road = True
                        break
                if has_road:
                    break
            if not has_road:
                continue

        elif tool == Tool.WIRE:
            # Don't overwrite power plant
            if pm[y, x]:
                continue
            if wm[y, x]:
                continue  # already wire
            # OK to place wire on empty or road

        elif tool == Tool.ROAD:
            if rm[y, x]:
                continue  # already road
            if pm[y, x]:
                continue  # don't bulldoze plant

        elif tool == Tool.COALPOWER:
            # Need clear 3x3
            clear = True
            for dy in range(-1, 2):
                for dx in range(-1, 2):
                    nx, ny = x + dx, y + dy
                    if not in_bounds(nx, ny) or not em[ny, nx]:
                        clear = False
                        break
                if not clear:
                    break
            if not clear:
                continue

        state['plan_idx'] = idx
        return action

    state['plan_idx'] = idx

    # Reactive phase: if we've exhausted the plan, try to place more zones
    # near roads and wires
    road_ys, road_xs = np.where(rm)
    wire_ys, wire_xs = np.where(wm)

    if len(road_xs) == 0:
        return None

    # Dilate road and wire masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cys, cxs = np.where(cand_mask)

    if len(cxs) > 0:
        k = (step * 31 + 7) % len(cxs)
        zx, zy = int(cxs[k]), int(cys[k])

        # Check 3x3 clearance
        clear = True
        for dy in range(-1, 2):
            for dx in range(-1, 2):
                nx, ny = zx + dx, zy + dy
                if not in_bounds(nx, ny) or not em[ny, nx]:
                    clear = False
                    break
            if not clear:
                break

        if clear:
            total = int(np.sum(resm)) + int(np.sum(comm)) + int(np.sum(indm))
            rc = int(np.sum(resm))
            cc = int(np.sum(comm))
            ic = int(np.sum(indm))
            t = max(total, 1)
            if cc / t < 0.25:
                tool = Tool.COMMERCIAL
            elif ic / t < 0.25:
                tool = Tool.INDUSTRIAL
            else:
                tool = Tool.RESIDENTIAL
            return (tool, zx, zy)

    return None

def act(obs, state):
    """
    Revised city builder:
    - Places coal plant first, then builds a clear wire backbone
    - Builds roads in a grid pattern near the wire
    - Places zones systematically in a grid with proper spacing
    - Balances RES/COM/IND more explicitly
    - Adds a second power plant mid-game
