        state['wire_idx'] = 0
        state['road_queue'] = []
        state['zone_queue'] = []
        state['second_plant'] = False

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Core anchor
    PLANT_X, PLANT_Y = 30, 50
    PLANT2_X, PLANT2_Y = 75, 50

    has_plant = np.any(pm)

    # Phase 1: Place first coal power plant
    if not has_plant:
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    plant_ys, plant_xs = np.where(pm)
    wire_ys, wire_xs = np.where(wm)
    road_ys, road_xs = np.where(rm)
    res_ys, res_xs = np.where(resm)
    com_ys, com_xs = np.where(comm)
    ind_ys, ind_xs = np.where(indm)

    wire_set = set(zip(wire_ys.tolist(), wire_xs.tolist()))
    road_set = set(zip(road_ys.tolist(), road_xs.tolist()))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def is_plant(x, y):
        return in_bounds(x, y) and bool(pm[y, x])

    def is_wire_or_plant(x, y):
        return in_bounds(x, y) and (bool(wm[y, x]) or bool(pm[y, x]))

    def is_empty(x, y):
        return in_bounds(x, y) and bool(em[y, x])

    def pick_tool():
        t = max(total_zones, 1)
        r = res_count / t
        c = com_count / t
        i = ind_count / t
        if c < 0.25:
            return Tool.COMMERCIAL
        if i < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                # Allow empty, or existing zone tile (center)
                if not bool(em[nr, nc]):
                    # Check if it's part of a zone already placed at this center
                    cell = tm[nr, nc]
                    # Only accept if truly empty
                    return False
        return True

    # Build horizontal wire spine from plant rightward
    # Spine row = PLANT_Y
    spine_y = PLANT_Y
    spine_start = PLANT_X + 2  # just past plant (plant is 3x3, center at PLANT_X)
    spine_end = PLANT2_X - 2   # up to second plant

    # Extend wire spine rightward
    for wx in range(spine_start, spine_end + 1):
        if not is_wire_or_plant(wx, spine_y):
            if is_empty(wx, spine_y):
                return (Tool.WIRE, wx, spine_y)
            # If blocked, skip (auto-bulldoze handles it, but be safe)
            break

    # Build vertical wire branches every 6 columns
    branch_cols = list(range(spine_start + 2, spine_end, 6))
    for bx in branch_cols:
        if not is_wire_or_plant(bx, spine_y):
            continue  # spine not yet at this col
        for sign in [-1, 1]:
            for dy in range(1, 10):
                wy = spine_y + sign * dy
                if not in_bounds(bx, wy):
                    break
                if not is_wire_or_plant(bx, wy):
                    if is_empty(bx, wy):
                        return (Tool.WIRE, bx, wy)
                    break

    # Place second power plant
    if not state['second_plant']:
        # Check if there's a plant near PLANT2
        near_plant2 = False
        for dy in range(-3, 4):
            for dx in range(-3, 4):
                ny, nx = PLANT2_Y + dy, PLANT2_X + dx
                if in_bounds(nx, ny) and bool(pm[ny, nx]):
                    near_plant2 = True
        if not near_plant2:
            # Only place if wire has reached close to PLANT2_X
            wire_cols_on_spine = [c for (r, c) in wire_set if r == spine_y]
            if wire_cols_on_spine and max(wire_cols_on_spine) >= PLANT2_X - 5:
                if is_empty(PLANT2_X, PLANT2_Y):
                    state['second_plant'] = True
                    return (Tool.COALPOWER, PLANT2_X, PLANT2_Y)
        else:
            state['second_plant'] = True

    # Build roads: two horizontal roads at spine_y-3 and spine_y+3
    road_top = spine_y - 3
    road_bot = spine_y + 3
    road_left = spine_start
    road_right = min(spine_end + 2, WORLD_W - 3)

    for row in [road_top, road_bot]:
        for cx in range(road_left, road_right + 1):
            if in_bounds(cx, row) and (row, cx) not in road_set:
                if not bool(pm[row, cx]):
                    return (Tool.ROAD, cx, row)

    # Vertical connector roads every 6 cols
    for vc in range(road_left, road_right + 1, 6):
        for vr in range(road_top, road_bot + 1):
            if in_bounds(vc, vr) and (vr, vc) not in road_set:
                if not bool(pm[vr, vc]):
                    return (Tool.ROAD, vc, vr)

    # Zone placement: place zones between road rows
    # Zones go at row offsets from spine: rows spine_y-6, spine_y+6
    # and between spine_y-3 and spine_y+3 (above road_top and below road_bot)

    # Build neighbor masks for road and wire/plant
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Systematically place zones in a grid above and below road rows
    # Above road_top: centers at road_top - 2 (y), spaced every 3 cols
    # Below road_bot: centers at road_bot + 2 (y), spaced every 3 cols
    zone_rows = [road_top - 2, road_bot + 2]
    zone_col_start = road_left + 1
    zone_col_step = 4

    for zr in zone_rows:
        if not in_bounds(0, zr):
            continue
        for zc in range(zone_col_start, road_right - 1, zone_col_step):
            if not in_bounds(zc, zr):
                continue
            if not bool(em[zr, zc]):
                continue
            if not nbr_road[zr, zc]:
                continue
            if not nbr_wire[zr, zc]:
                continue
            if zone_clear(zc, zr):
                return (pick_tool(), zc, zr)

    # Also try zones directly adjacent to roads (above/below)
    for zr in [road_top - 2, road_bot + 2, road_top - 5, road_bot + 5]:
        for zc in range(road_left, road_right, 4):
            if not in_bounds(zc, zr):
                continue
            if not bool(em[zr, zc]):
                continue
            if nbr_road[zr, zc] and nbr_wire[zr, zc]:
                if zone_clear(zc, zr):
                    return (pick_tool(), zc, zr)

    # Generic candidate search
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        step_hash = int(obs.step * 13) % max(len(cxs), 1)
        for offset in range(min(len(cxs), 50)):
            k = (step_hash + offset * 7) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # Services once population grows
    if obs.city_pop > 300:
        fx, fy = PLANT_X + 5, spine_y - 10
        if in_bounds(fx, fy) and bool(em[fy, fx]):
            return (Tool.FIRESTATION, fx, fy)
        px2, py2 = PLANT_X + 5, spine_y + 10
        if in_bounds(px2, py2) and bool(em[py2, px2]):
            return (Tool.POLICESTATION, px2, py2)

    # Extend roads if we have road tiles
    if len(road_xs) > 0:
        k = int(obs.step * 11) % len(road_xs)
        rx, ry = int(road_xs[k]), int(road_ys[k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx + dx2, ry + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Improved policy: horizontal road/wire layout instead of vertical spine.
    Build two parallel horizontal road rows with zones above and below,
    powered by a coal plant connected via horizontal wire.
    Also add a second neighborhood when population grows.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    # Use state as a queue-based plan
    if 'plan' not in state:
        state['plan'] = []
        state['plan_idx'] = 0

    # Center of map
    cx, cy = 60, 50

    has_plant = np.any(pm)

    # Phase 1: Place coal power plant at left side
    plant_cx, plant_cy = 20, cy
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Gather masks
    wire_positions = set(zip(*np.where(wm))) if np.any(wm) else set()
    road_positions = set(zip(*np.where(rm))) if np.any(rm) else set()
    res_pos = set(zip(*np.where(res_mask(tm))))
    com_pos = set(zip(*np.where(com_mask(tm))))
    ind_pos = set(zip(*np.where(ind_mask(tm))))
    all_zones = res_pos | com_pos | ind_pos

    res_count = len(res_pos)
    com_count = len(com_pos)
    ind_count = len(ind_pos)

    # Layout: horizontal wire row at cy, roads at cy-2 and cy+2
    # Zones above (cy-5) and below (cy+5) the roads
    wire_row = cy
    road_row_top = cy - 2
    road_row_bot = cy + 2
    zone_row_top = cy - 5
    zone_row_bot = cy + 5

    # Horizontal extent
    x_start = plant_cx + 3  # just right of plant
    x_end = min(100, cx + 35)

    # Phase 2: Extend wire horizontally from plant
    wire_cols_in_row = sorted(c for (r, c) in wire_positions if r == wire_row)
    if not wire_cols_in_row:
        # Start wire right next to plant
        first_wc = plant_cx + 2
        if 0 <= first_wc < WORLD_W and em[wire_row, first_wc]:
            return (Tool.WIRE, first_wc, wire_row)
        else:
            return (Tool.WIRE, plant_cx + 2, wire_row)
    else:
        max_wc = max(wire_cols_in_row)
        min_wc = min(wire_cols_in_row)
        if max_wc < x_end:
            nc = max_wc + 1
            if 0 <= nc < WORLD_W and (em[wire_row, nc] or wm[wire_row, nc]):
                return (Tool.WIRE, nc, wire_row)

    wire_cols_set = set(wire_cols_in_row)

    # Phase 3: Build top road row where we have wire coverage
    road_cols_top = set(c for (r, c) in road_positions if r == road_row_top)
    for wc in sorted(wire_cols_in_row):
        if wc not in road_cols_top and 0 <= road_row_top < WORLD_H and 0 <= wc < WORLD_W:
            if em[road_row_top, wc]:
                return (Tool.ROAD, wc, road_row_top)

    # Phase 4: Build bottom road row
    road_cols_bot = set(c for (r, c) in road_positions if r == road_row_bot)
    for wc in sorted(wire_cols_in_row):
        if wc not in road_cols_bot and 0 <= road_row_bot < WORLD_H and 0 <= wc < WORLD_W:
            if em[road_row_bot, wc]:
                return (Tool.ROAD, wc, road_row_bot)

    # Helper: check if 3x3 area around (zr,zc) is all empty
    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def already_zone_nearby(zr, zc):
        return any(abs(zr - pr) <= 1 and abs(zc - pc) <= 1 for (pr, pc) in all_zones)

    def choose_zone(zc):
        # Rotate: 50% res, 25% com, 25% ind
        total = res_count + com_count + ind_count + 1
        if ind_count * 4 < total:
            return Tool.INDUSTRIAL
        elif com_count * 4 < total:
            return Tool.COMMERCIAL
        else:
            return Tool.RESIDENTIAL

    # Phase 5: Place zones above top road (zone_row_top)
    # Zone columns every 3 tiles, spaced properly
    road_cols_top_list = sorted(road_cols_top)
    for zc in range(x_start + 1, x_end, 3):
        if any(abs(zc - rc) <= 2 for rc in road_cols_top_list):
            zr = zone_row_top
            if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                if not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                    return (choose_zone(zc), zc, zr)

    # Phase 6: Place zones below bottom road (zone_row_bot)
    road_cols_bot_list = sorted(road_cols_bot)
    for zc in range(x_start + 1, x_end, 3):
        if any(abs(zc - rc) <= 2 for rc in road_cols_bot_list):
            zr = zone_row_bot
            if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                if not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                    return (choose_zone(zc), zc, zr)

    # Phase 7: Second neighborhood above/below when population grows
    if obs.city_pop > 150:
        # Second horizontal cluster: wire_row2 = cy - 14, roads at cy-12 and cy-16
        wire_row2 = cy - 14
        road_row2_top = cy - 16
        road_row2_bot = cy - 12
        zone_row2_top = cy - 19
        zone_row2_bot = cy - 9

        wire_cols2 = sorted(c for (r, c) in wire_positions if r == wire_row2)

        if not wire_cols2:
            # Start wire for cluster 2 connected vertically from main wire
            # Find a column where we have wire on main row
            if wire_cols_in_row:
                connect_col = wire_cols_in_row[len(wire_cols_in_row)//2]
                # Lay vertical wire from wire_row up to wire_row2
                for ry in range(wire_row2, wire_row):
                    if em[ry, connect_col] or wm[ry, connect_col]:
                        if not wm[ry, connect_col]:
                            return (Tool.WIRE, connect_col, ry)
                # Then start horizontal
                if 0 <= wire_row2 < WORLD_H and em[wire_row2, connect_col]:
                    return (Tool.WIRE, connect_col, wire_row2)
        else:
            max_wc2 = max(wire_cols2)
            if max_wc2 < x_end:
                nc = max_wc2 + 1
                if 0 <= nc < WORLD_W and (em[wire_row2, nc] or wm[wire_row2, nc]):
                    return (Tool.WIRE, nc, wire_row2)

            wire_cols2_set = set(wire_cols2)

            # Road rows for cluster 2
            road_cols2_top = set(c for (r, c) in road_positions if r == road_row2_top)
            for wc in sorted(wire_cols2):
                if wc not in road_cols2_top and 0 <= road_row2_top < WORLD_H and 0 <= wc < WORLD_W:
                    if em[road_row2_top, wc]:
                        return (Tool.ROAD, wc, road_row2_top)

            road_cols2_bot = set(c for (r, c) in road_positions if r == road_row2_bot)
            for wc in sorted(wire_cols2):
                if wc not in road_cols2_bot and 0 <= road_row2_bot < WORLD_H and 0 <= wc < WORLD_W:
                    if em[road_row2_bot, wc]:
                        return (Tool.ROAD, wc, road_row2_bot)

            # Zones for cluster 2
            road_cols2_top_list = sorted(road_cols2_top)
            road_cols2_bot_list = sorted(road_cols2_bot)

            for zc in range(x_start + 1, x_end, 3):
                if any(abs(zc - rc) <= 2 for rc in road_cols2_top_list):
                    zr = zone_row2_top
                    if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                        if not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                            return (choose_zone(zc), zc, zr)

            for zc in range(x_start + 1, x_end, 3):
                if any(abs(zc - rc) <= 2 for rc in road_cols2_bot_list):
                    zr = zone_row2_bot
                    if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                        if not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                            return (choose_zone(zc), zc, zr)

    # Phase 8: Third neighborhood below when big
    if obs.city_pop > 400:
        wire_row3 = cy + 14
        road_row3_top = cy + 12
        road_row3_bot = cy + 16
        zone_row3_top = cy + 9
        zone_row3_bot = cy + 19

        wire_cols3 = sorted(c for (r, c) in wire_positions if r == wire_row3)

        if not wire_cols3:
            if wire_cols_in_row:
                connect_col = wire_cols_in_row[len(wire_cols_in_row)//2]
                for ry in range(wire_row + 1, wire_row3 + 1):
                    if not wm[ry, connect_col]:
                        if em[ry, connect_col]:
                            return (Tool.WIRE, connect_col, ry)
        else:
            max_wc3 = max(wire_cols3)
            if max_wc3 < x_end:
                nc = max_wc3 + 1
                if 0 <= nc < WORLD_W and (em[wire_row3, nc] or wm[wire_row3, nc]):
                    return (Tool.WIRE, nc, wire_row3)

            road_cols3_top = set(c for (r, c) in road_positions if r == road_row3_top)
            for wc in sorted(wire_cols3):
                if wc not in road_cols3_top and 0 <= road_row3_top < WORLD_H and 0 <= wc < WORLD_W:
                    if em[road_row3_top, wc]:
                        return (Tool.ROAD, wc, road_row3_top)

            road_cols3_bot = set(c for (r, c) in road_positions if r == road_row3_bot)
            for wc in sorted(wire_cols3):
                if wc not in road_cols3_bot and 0 <= road_row3_bot < WORLD_H and 0 <= wc < WORLD_W:
                    if em[road_row3_bot, wc]:
                        return (Tool.ROAD, wc, road_row3_bot)

            road_cols3_top_list = sorted(road_cols3_top)
            road_cols3_bot_list = sorted(road_cols3_bot)

            for zc in range(x_start + 1, x_end, 3):
                if any(abs(zc - rc) <= 2 for rc in road_cols3_top_list):
                    zr = zone_row3_top
                    if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                        if not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                            return (choose_zone(zc), zc, zr)
            for zc in range(x_start + 1, x_end, 3):
                if any(abs(zc - rc) <= 2 for rc in road_cols3_bot_list):
                    zr = zone_row3_bot
                    if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                        if not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                            return (choose_zone(zc), zc, zr)

    # Phase 9: Second power plant if city is large and powered zones stalling
    if obs.city_pop > 600 and not state.get('plant2', False):
        p2x, p2y = plant_cx + 40, cy
        clear = all(
            em[p2y + dr, p2x + dc]
            for dr in [-1, 0, 1] for dc in [-1, 0, 1]
            if 0 <= p2y + dr < WORLD_H and 0 <= p2x + dc < WORLD_W
        )
        if clear:
            state['plant2'] = True
            return (Tool.COALPOWER, p2x, p2y)

    return None

def act(obs, state):
    """
    Combined policy: takes best ideas from both parents.
    - Compact vertical spine of wire + road
    - Zones flanking spine with proper power and road access
    - Balanced R/C/I ratio
    - Adaptive expansion based on population
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def has_tile(mask, x, y):
        if 0 <= y < WORLD_H and 0 <= x < WORLD_W:
            return bool(mask[y, x])
        return False

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        all_zone = resm | comm | indm
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone[rr, rc]:
                    return False
        return True

    def zone_present(zr, zc):
        all_zone = resm | comm | indm
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone[rr, rc]:
                        return True
        return False

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Layout:
    # plant at (plant_x, cy)
    # wire spine at wire_col
    # road at road_col = wire_col + 1
    # left zones at left_zcol (wire_col - 3)
    # right zones at right_zcol (road_col + 3)

    plant_x = cx - 6
    plant_y = cy
    wire_col = cx - 1
    road_col = cx       # road right next to wire
    left_zcol = wire_col - 3
    right_zcol = road_col + 3

    # Clamp
    wire_col = max(2, min(WORLD_W - 3, wire_col))
    road_col = max(2, min(WORLD_W - 3, road_col))
    left_zcol = max(2, min(WORLD_W - 3, left_zcol))
    right_zcol = max(2, min(WORLD_W - 3, right_zcol))
    plant_x = max(2, min(WORLD_W - 3, plant_x))

    # Adaptive spine extent
    if obs.city_pop < 50:
        spine_half = 8
    elif obs.city_pop < 200:
        spine_half = 12
    elif obs.city_pop < 500:
        spine_half = 18
    else:
        spine_half = 24

    spine_min = max(1, cy - spine_half)
    spine_max = min(WORLD_H - 2, cy + spine_half)
    spine_range = range(spine_min, spine_max + 1)

    # Phase 0: Place coal power plant
    if not np.any(pm):
        return (Tool.COALPOWER, plant_x, plant_y)

    # Phase 1: Wire spine vertical column
    for dy in spine_range:
        if not has_tile(wm, wire_col, dy) and not has_tile(pm, wire_col, dy):
            # Don't bulldoze road
            if not has_tile(rm, wire_col, dy):
                return (Tool.WIRE, wire_col, dy)

    # Phase 2: Road column adjacent to wire
    for dy in spine_range:
        if not has_tile(rm, road_col, dy) and not has_tile(pm, road_col, dy):
            if not has_tile(wm, road_col, dy):
                return (Tool.ROAD, road_col, dy)

    # Collect wired rows for zone placement check
    wire_rows = [r for r in spine_range if wm[r, wire_col]]
    road_rows = [r for r in spine_range if rm[r, road_col]]

    # Phase 3: Place zones flanking wire+road spine
    zone_rows = list(range(spine_min + 1, spine_max - 1, 3))

    for zr in zone_rows:
        wire_near = any(abs(zr - wr) <= 2 for wr in wire_rows)
        road_near = any(abs(zr - rr) <= 2 for rr in road_rows)

        if wire_near and road_near:
            # Left zone
            zc = left_zcol
            if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                return (pick_tool(), zc, zr)

            # Right zone
            zc = right_zcol
            if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                return (pick_tool(), zc, zr)

    # Phase 4: Lateral wires to power left zones
    for wr in wire_rows:
        for wc in range(wire_col - 1, left_zcol - 2, -1):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc] or pm[wr, wc]:
                    break
                if em[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                else:
                    break

    # Phase 5: Wire to reach right zones from spine
    for wr in wire_rows:
        if not rm[wr, road_col]:
            continue
        for wc in range(road_col + 1, right_zcol + 2):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc] or pm[wr, wc]:
                    break
                if em[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif rm[wr, wc]:
                    continue
                else:
                    break

    # Phase 6: Second coal plant if population is large enough
    if obs.city_pop > 300 and np.sum(pm) < 9:
        px2 = plant_x + 20
        py2 = plant_y
        if 2 <= px2 <= WORLD_W - 3 and 2 <= py2 <= WORLD_H - 3:
            if em[py2, px2]:
                return (Tool.COALPOWER, px2, py2)

    # Phase 7: Expand to second tier of zones if city growing
    if obs.city_pop > 150:
        left2_zcol = left_zcol - 4
        right2_zcol = right_zcol + 4
        left2_zcol = max(2, min(WORLD_W - 3, left2_zcol))
        right2_zcol = max(2, min(WORLD_W - 3, right2_zcol))

        for zr in zone_rows:
            wire_near = any(abs(zr - wr) <= 2 for wr in wire_rows)
            road_near = any(abs(zr - rr) <= 2 for rr in road_rows)
            if wire_near and road_near:
                for zc in [left2_zcol, right2_zcol]:
                    if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                        # Check wire nearby
                        r0 = max(0, zr - 5); r1 = min(WORLD_H, zr + 6)
                        c0 = max(0, zc - 5); c1 = min(WORLD_W, zc + 6)
                        if np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1]):
                            if np.any(rm[r0:r1, c0:c1]):
                                return (pick_tool(), zc, zr)

    # Phase 8: Add horizontal roads to improve connectivity
    if obs.city_pop > 100:
        for rr in [spine_min + 1, spine_max - 1]:
            if 0 <= rr < WORLD_H:
                for rc in range(left_zcol - 1, right_zcol + 2):
                    if 0 <= rc < WORLD_W and em[rr, rc] and not pm[rr, rc]:
                        return (Tool.ROAD, rc, rr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Read map each step, decide based on current state
    - Build: coal plant -> wire spine -> road column -> zones
    - Expand reactively based on what already exists
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    has_plant = np.any(pm)
    has_wire = np.any(wm)
    has_road = np.any(rm)

    cx, cy = 58, 50  # center of operations

    # Phase 1: Place coal power plant if none exists
    if not has_plant:
        return (Tool.COALPOWER, cx - 6, cy)

    # Get positions
    wire_positions = list(zip(*np.where(wm))) if has_wire else []
    road_positions = list(zip(*np.where(rm))) if has_road else []
    plant_positions = list(zip(*np.where(pm)))

    res_pos = list(zip(*np.where(res_mask(tm))))
    com_pos = list(zip(*np.where(com_mask(tm))))
    ind_pos = list(zip(*np.where(ind_mask(tm))))
    res_count = len(res_pos)
    com_count = len(com_pos)
    ind_count = len(ind_pos)
    all_zones = set(res_pos) | set(com_pos) | set(ind_pos)

    # Wire spine column: just right of plant
    # Plant center at (cx-6, cy), footprint cols cx-8..cx-4
    wire_col = cx - 3  # wire spine at cx-3
    road_col = cx - 2  # road at cx-2 (adjacent to wire)
    left_zone_col = cx - 7   # zones left of wire (cx-3-4)
    right_zone_col = cx + 1  # zones right of road (cx-2+3)

    # Compute wire extent in spine column
    wire_col_rows = sorted(r for (r, c) in wire_positions if c == wire_col)

    # Dynamic vertical span based on population
    span = min(20, 8 + obs.city_pop // 25)
    tmin = max(2, cy - span)
    tmax = min(WORLD_H - 3, cy + span)

    # Phase 2: Build wire spine
    if not wire_col_rows:
        # Start wire adjacent to plant
        if 0 <= cy < WORLD_H and 0 <= wire_col < WORLD_W and em[cy, wire_col]:
            return (Tool.WIRE, wire_col, cy)
        # Try nearby rows
        for dy in range(-3, 4):
            ny = cy + dy
            if 0 <= ny < WORLD_H and em[ny, wire_col]:
                return (Tool.WIRE, wire_col, ny)
    else:
        min_wr = min(wire_col_rows)
        max_wr = max(wire_col_rows)
        # Extend downward
        if max_wr < tmax:
            nr = max_wr + 1
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if min_wr > tmin:
            nr = min_wr - 1
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    wire_rows_set = set(wire_col_rows)

    # Phase 3: Build road column adjacent to wire spine
    if wire_col_rows:
        road_col_rows = set(r for (r, c) in road_positions if c == road_col)
        for wr in wire_col_rows:
            if wr not in road_col_rows and 0 <= road_col < WORLD_W and 0 <= wr < WORLD_H:
                if em[wr, road_col]:
                    return (Tool.ROAD, road_col, wr)

    # Helper: check if 3x3 area is all empty
    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def zone_nearby(zr, zc):
        return any(abs(zr - pr) <= 2 and abs(zc - pc) <= 2 for (pr, pc) in all_zones)

    def pick_zone_type(zc, zr):
        if com_count * 4 < res_count and zc == right_zone_col:
            return Tool.COMMERCIAL
        if ind_count * 4 < res_count and zc == left_zone_col and zr > cy:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Phase 4: Place lateral wires/roads and zones
    road_col_rows_set = set(r for (r, c) in road_positions if c == road_col)

    if wire_col_rows:
        for wr in wire_col_rows:
            wire_here = wr in wire_rows_set
            road_here = any(abs(wr - rr) <= 1 for rr in road_col_rows_set)

            if not wire_here:
                continue

            # Lateral wire to left zone column: need wire at wire_col-1 .. left_zone_col+1
            for wc in range(wire_col - 1, left_zone_col, -1):
                if 0 <= wc < WORLD_W and em[wr, wc]:
                    return (Tool.WIRE, wc, wr)

            # Place left zone
            if road_here or wire_here:
                zr, zc = wr, left_zone_col
                if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                    if not zone_nearby(zr, zc) and zone_area_free(zr, zc):
                        return (pick_zone_type(zc, zr), zc, zr)

            # Lateral road to right zone column
            for rc in range(road_col + 1, right_zone_col):
                if 0 <= rc < WORLD_W and em[wr, rc]:
                    return (Tool.ROAD, rc, wr)

            # Place right zone
            if road_here:
                zr, zc = wr, right_zone_col
                if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                    if not zone_nearby(zr, zc) and zone_area_free(zr, zc):
                        return (pick_zone_type(zc, zr), zc, zr)

    # Phase 5: Second cluster when population grows
    if obs.city_pop > 150:
        wire_col2 = right_zone_col + 4
        road_col2 = wire_col2 + 1
        right_zone_col2 = road_col2 + 3

        wire_col2_rows = sorted(r for (r, c) in wire_positions if c == wire_col2)

        if not wire_col2_rows:
            # Connect horizontally from main wire spine at cy
            for wc in range(wire_col + 1, wire_col2 + 1):
                if 0 <= wc < WORLD_W and em[cy, wc]:
                    return (Tool.WIRE, wc, cy)
        else:
            min_wr2 = min(wire_col2_rows)
            max_wr2 = max(wire_col2_rows)
            span2 = min(18, 6 + obs.city_pop // 30)
            tmin2 = max(2, cy - span2)
            tmax2 = min(WORLD_H - 3, cy + span2)

            if max_wr2 < tmax2:
                nr = max_wr2 + 1
                if 0 <= nr < WORLD_H and (em[nr, wire_col2] or wm[nr, wire_col2]):
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > tmin2:
                nr = min_wr2 - 1
                if 0 <= nr < WORLD_H and (em[nr, wire_col2] or wm[nr, wire_col2]):
                    return (Tool.WIRE, wire_col2, nr)

            road_col2_rows = set(r for (r, c) in road_positions if c == road_col2)
            for wr in wire_col2_rows:
                if wr not in road_col2_rows and 0 <= road_col2 < WORLD_W:
                    if em[wr, road_col2]:
                        return (Tool.ROAD, road_col2, wr)

            for wr in wire_col2_rows:
                road_here2 = any(abs(wr - rr) <= 1 for rr in road_col2_rows)
                if road_here2:
                    # Lateral road to right zone col2
                    for rc in range(road_col2 + 1, right_zone_col2):
                        if 0 <= rc < WORLD_W and em[wr, rc]:
                            return (Tool.ROAD, rc, wr)
                    zr, zc = wr, right_zone_col2
                    if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                        if not zone_nearby(zr, zc) and zone_area_free(zr, zc):
                            if com_count * 3 < res_count:
                                return (Tool.COMMERCIAL, zc, zr)
                            else:
                                return (Tool.RESIDENTIAL, zc, zr)

    # Phase 6: Second power plant when large
    if obs.city_pop > 500 and not state.get("plant2_placed", False):
        p2x, p2y = cx + 25, cy
        clear = all(
            em[p2y + dr, p2x + dc]
            for dr in [-1, 0, 1] for dc in [-1, 0, 1]
            if 0 <= p2y + dr < WORLD_H and 0 <= p2x + dc < WORLD_W
        )
        if clear:
            state["plant2_placed"] = True
            return (Tool.COALPOWER, p2x, p2y)

    return None

def act(obs, state):
    """
    New policy: horizontal spine instead of vertical, with zones above and below.
    Uses a central horizontal road + wire spine, zones placed at regular intervals
    above and below. Better balanced R/C/I ratio and more compact layout.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def has_tile(mask, x, y):
        if 0 <= y < WORLD_H and 0 <= x < WORLD_W:
            return bool(mask[y, x])
        return False

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        all_zone = resm | comm | indm
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone[rr, rc]:
                    return False
        return True

    def zone_present(zr, zc):
        all_zone = resm | comm | indm
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone[rr, rc]:
                        return True
        return False

    def pick_tool():
        # More aggressive commercial/industrial mix
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        # Target: 50% R, 30% C, 20% I
        if com_count / t < 0.30:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Horizontal layout:
    # wire_row = cy - 1 (horizontal wire spine)
    # road_row = cy     (horizontal road spine)
    # plant at left side
    # zones above (top_zrow = cy - 4) and below (bot_zrow = cy + 4)

    plant_x = cx - 20
    plant_y = cy - 1
    wire_row = cy - 1
    road_row = cy
    top_zrow = cy - 4
    bot_zrow = cy + 4

    # Clamp
    wire_row = max(2, min(WORLD_H - 3, wire_row))
    road_row = max(2, min(WORLD_H - 3, road_row))
    top_zrow = max(2, min(WORLD_H - 3, top_zrow))
    bot_zrow = max(2, min(WORLD_H - 3, bot_zrow))
    plant_x = max(2, min(WORLD_W - 3, plant_x))
    plant_y = max(2, min(WORLD_H - 3, plant_y))

    # Adaptive spine extent based on population
    if obs.city_pop < 50:
        spine_half = 15
    elif obs.city_pop < 200:
        spine_half = 20
    elif obs.city_pop < 500:
        spine_half = 28
    else:
        spine_half = 35

    spine_min = max(2, cx - spine_half)
    spine_max = min(WORLD_W - 3, cx + spine_half)
    spine_range = range(spine_min, spine_max + 1)

    # Phase 0: Place coal power plant
    if not np.any(pm):
        return (Tool.COALPOWER, plant_x, plant_y)

    # Phase 1: Wire spine - horizontal row
    for dx in spine_range:
        if not has_tile(wm, dx, wire_row) and not has_tile(pm, dx, wire_row):
            if not has_tile(rm, dx, wire_row):
                return (Tool.WIRE, dx, wire_row)

    # Phase 2: Road spine - horizontal row just below wire
    for dx in spine_range:
        if not has_tile(rm, dx, road_row) and not has_tile(pm, dx, road_row):
            if not has_tile(wm, dx, road_row):
                return (Tool.ROAD, dx, road_row)

    wire_cols = [c for c in spine_range if wm[wire_row, c]]
    road_cols = [c for c in spine_range if rm[road_row, c]]

    # Phase 3: Place zones above and below the spine
    zone_cols = list(range(spine_min + 1, spine_max - 1, 4))

    for zc in zone_cols:
        wire_near = any(abs(zc - wc) <= 3 for wc in wire_cols)
        road_near = any(abs(zc - rc) <= 3 for rc in road_cols)

        if wire_near and road_near:
            # Zone above spine
            zr = top_zrow
            if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                return (pick_tool(), zc, zr)

            # Zone below spine
            zr = bot_zrow
            if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                return (pick_tool(), zc, zr)

    # Phase 4: Vertical wires connecting spine to top zones
    for wc in wire_cols:
        for wr in range(wire_row - 1, top_zrow - 2, -1):
            if 0 <= wr < WORLD_H:
                if wm[wr, wc] or pm[wr, wc]:
                    break
                if em[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif rm[wr, wc]:
                    continue
                else:
                    break

    # Phase 5: Vertical wires connecting spine to bottom zones
    for wc in wire_cols:
        for wr in range(road_row + 1, bot_zrow + 2):
            if 0 <= wr < WORLD_H:
                if wm[wr, wc] or pm[wr, wc]:
                    break
                if em[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif rm[wr, wc]:
                    continue
                else:
                    break

    # Phase 6: Second coal plant if population growing
    if obs.city_pop > 200 and np.sum(pm) < 9:
        px2 = cx + 20
        py2 = wire_row
        if 2 <= px2 <= WORLD_W - 3 and 2 <= py2 <= WORLD_H - 3:
            if em[py2, px2]:
                return (Tool.COALPOWER, px2, py2)

    # Phase 7: Second tier zones (further above and below)
    if obs.city_pop > 100:
        top2_zrow = top_zrow - 4
        bot2_zrow = bot_zrow + 4
        top2_zrow = max(2, min(WORLD_H - 3, top2_zrow))
        bot2_zrow = max(2, min(WORLD_H - 3, bot2_zrow))

        for zc in zone_cols:
            wire_near = any(abs(zc - wc) <= 3 for wc in wire_cols)
            road_near = any(abs(zc - rc) <= 3 for rc in road_cols)
            if wire_near and road_near:
                for zr in [top2_zrow, bot2_zrow]:
                    if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                        r0 = max(0, zr - 5); r1 = min(WORLD_H, zr + 6)
                        c0 = max(0, zc - 5); c1 = min(WORLD_W, zc + 6)
                        if np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1]):
                            if np.any(rm[r0:r1, c0:c1]):
                                return (pick_tool(), zc, zr)

    # Phase 8: Vertical roads for better connectivity
    if obs.city_pop > 150:
        for rc in [spine_min + 2, spine_max - 2]:
            if 0 <= rc < WORLD_W:
                for rr in range(top_zrow - 1, bot_zrow + 2):
                    if 0 <= rr < WORLD_H and em[rr, rc] and not pm[rr, rc]:
                        return (Tool.ROAD, rc, rr)

    # Phase 9: Add police/fire for city services
    if obs.city_pop > 300:
        service_x = cx + 5
        service_y = cy - 8
        if 2 <= service_x <= WORLD_W - 3 and 2 <= service_y <= WORLD_H - 3:
            if em[service_y, service_x]:
                return (Tool.POLICESTATION, service_x, service_y)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map every step and adapts.
    Strategy:
    - Place coal power plant near center-left if none exists.
    - Grow wire spine NORTHWARD first (vertical column), then southward.
    - Build road column one tile RIGHT of wire spine.
    - Place zones on both sides of road, alternating RES/COM/IND.
    - Extend wire laterally to reach zones for power.
    - React to powered_zones and city_pop to decide what to build next.
    """
    tm = obs.tile_map
    step = obs.step

    # Center anchor
    cx, cy = WORLD_W // 2, WORLD_H // 2

    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    has_plant = np.any(pm)
    has_wire = np.any(wm)
    has_road = np.any(rm)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))

    # Phase 1: Place coal power plant
    if not has_plant:
        # Place plant at cx-5, cy (center). Footprint cx-7..cx-3
        px, py = cx - 5, cy
        return (Tool.COALPOWER, px, py)

    # Identify plant footprint to avoid overwriting
    plant_positions = list(zip(*np.where(pm)))

    # Wire column: cx - 1 (just right of plant footprint if plant at cx-5)
    # Plant footprint cols: cx-7 to cx-3. Wire starts at cx-2.
    wire_col = cx - 2
    road_col = cx - 1  # road just right of wire
    left_zone_col = cx - 6   # left of wire: center at wire_col - 4
    right_zone_col = cx + 2  # right of road: center at road_col + 3

    wire_rows = sorted([r for (r, c) in zip(*np.where(wm)) if c == wire_col]) if has_wire else []
    road_rows = sorted([r for (r, c) in zip(*np.where(rm)) if c == road_col]) if has_road else []

    def is_plant_tile(r, c):
        return pm[r, c]

    def safe_wire(c, r):
        if 0 <= r < WORLD_H and 0 <= c < WORLD_W:
            if not is_plant_tile(r, c) and (em[r, c] or wm[r, c]):
                return True
        return False

    def safe_road(c, r):
        if 0 <= r < WORLD_H and 0 <= c < WORLD_W:
            if not is_plant_tile(r, c) and (em[r, c] or rm[r, c]):
                return True
        return False

    # Phase 2: Initialize wire spine adjacent to plant
    if not wire_rows:
        # Plant center cx-5, footprint cols cx-7..cx-3
        # Wire at cx-2, cy
        if safe_wire(wire_col, cy):
            return (Tool.WIRE, wire_col, cy)
        elif safe_wire(wire_col + 1, cy):
            return (Tool.WIRE, wire_col + 1, cy)

    # Phase 3: Extend wire spine vertically
    target_min = max(2, cy - 18)
    target_max = min(WORLD_H - 3, cy + 18)

    if wire_rows:
        min_wr = wire_rows[0]
        max_wr = wire_rows[-1]

        # Extend upward (northward) first
        if min_wr > target_min:
            nr = min_wr - 1
            if safe_wire(wire_col, nr):
                return (Tool.WIRE, wire_col, nr)
        # Extend downward
        if max_wr < target_max:
            nr = max_wr + 1
            if safe_wire(wire_col, nr):
                return (Tool.WIRE, wire_col, nr)

    # Phase 4: Build road adjacent to wire spine
    if wire_rows:
        for wr in wire_rows:
            if not rm[wr, road_col] and safe_road(road_col, wr):
                return (Tool.ROAD, road_col, wr)

    # Helper: check 3x3 zone area is clear
    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if is_plant_tile(rr, rc):
                    return False
                if not em[rr, rc]:
                    return False
        return True

    res_positions = list(zip(*np.where(resm)))

    def zone_exists_near(zr, zc, margin=2):
        for (pr, pc) in res_positions:
            if abs(zr - pr) <= margin and abs(zc - pc) <= margin:
                return True
        com_positions = list(zip(*np.where(comm)))
        for (pr, pc) in com_positions:
            if abs(zr - pr) <= margin and abs(zc - pc) <= margin:
                return True
        ind_positions = list(zip(*np.where(indm)))
        for (pr, pc) in ind_positions:
            if abs(zr - pr) <= margin and abs(zc - pc) <= margin:
                return True
        return False

    # Phase 5: Place zones where wire and road coverage exists
    # Right side zones: center at right_zone_col, road at road_col (adjacent)
    # Left side zones: center at left_zone_col, wire at wire_col (adjacent)
    if wire_rows and road_rows:
        covered_rows = set(wire_rows) & set(road_rows)

        # Try placing zones at road-adjacent rows
        for zr in sorted(covered_rows):
            # Right side: center at road_col + 3
            rzc = road_col + 3
            if 0 <= zr < WORLD_H and 0 <= rzc < WORLD_W:
                if not zone_exists_near(zr, rzc, 2) and zone_area_free(zr, rzc):
                    # Balance: RES mostly, some COM and IND
                    if com_count * 4 < res_count:
                        return (Tool.COMMERCIAL, rzc, zr)
                    elif ind_count * 4 < res_count:
                        return (Tool.INDUSTRIAL, rzc, zr)
                    else:
                        return (Tool.RESIDENTIAL, rzc, zr)

            # Left side: center at wire_col - 4
            lzc = wire_col - 4
            if 0 <= zr < WORLD_H and 0 <= lzc < WORLD_W:
                if not zone_exists_near(zr, lzc, 2) and zone_area_free(zr, lzc):
                    if com_count * 4 < res_count:
                        return (Tool.COMMERCIAL, lzc, zr)
                    elif ind_count * 4 < res_count:
                        return (Tool.INDUSTRIAL, lzc, zr)
                    else:
                        return (Tool.RESIDENTIAL, lzc, zr)

    # Phase 6: Extend wire laterally to power left-side zones
    if wire_rows:
        lzc = wire_col - 4
        for wr in wire_rows:
            # Wire from wire_col-1 to wire_col-3 to reach left zones
            for wc in [wire_col - 1, wire_col - 2, wire_col - 3]:
                if 0 <= wc < WORLD_W and safe_wire(wc, wr) and not wm[wr, wc]:
                    return (Tool.WIRE, wc, wr)

        # Extend road rightward to reach right-side zones
        for wr in wire_rows:
            for rc in [road_col + 1, road_col + 2]:
                if 0 <= rc < WORLD_W and safe_road(rc, wr) and not rm[wr, rc]:
                    return (Tool.ROAD, rc, wr)

    # Phase 7: If city is growing, expand wire/road/zone range further
    if obs.city_pop > 300 and wire_rows:
        new_target_min = max(2, cy - 24)
        new_target_max = min(WORLD_H - 3, cy + 24)
        min_wr = wire_rows[0]
        max_wr = wire_rows[-1]
        if min_wr > new_target_min:
            nr = min_wr - 1
            if safe_wire(wire_col, nr):
                return (Tool.WIRE, wire_col, nr)
        if max_wr < new_target_max:
            nr = max_wr + 1
            if safe_wire(wire_col, nr):
                return (Tool.WIRE, wire_col, nr)

    # Phase 8: Add a second road column further right for more zone access
    if obs.city_pop > 500 and wire_rows:
        road_col2 = road_col + 6
        for wr in wire_rows:
            if 0 <= road_col2 < WORLD_W and not rm[wr, road_col2] and em[wr, road_col2]:
                return (Tool.ROAD, road_col2, wr)

    return None

def act(obs, state):
    """
    Improved city builder with:
    - Two parallel road corridors with zones between them
    - Better wire coverage with horizontal spine + vertical branches
    - Balanced zone mix (RES/COM/IND)
    - Second power plant connected by wire
    - Services placed early
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    # Anchor - shifted to give more room
    CX, CY = 20, 50

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Place first coal power plant
    if not np.any(pm):
        return (Tool.COALPOWER, CX, CY)

    plant_ys, plant_xs = np.where(pm)
    px = int(np.median(plant_xs))
    py = int(np.median(plant_ys))

    wire_ys, wire_xs = np.where(wm)
    road_ys, road_xs = np.where(rm)
    res_ys, res_xs = np.where(resm)
    com_ys, com_xs = np.where(comm)
    ind_ys, ind_xs = np.where(indm)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    zone_set = set(zip(
        np.concatenate([res_ys, com_ys, ind_ys]).tolist(),
        np.concatenate([res_xs, com_xs, ind_xs]).tolist()
    ))

    def pick_tool():
        t = max(total_zones, 1)
        r = res_count / t
        c = com_count / t
        i = ind_count / t
        # Aim for 50% RES, 25% COM, 25% IND
        if c < 0.25:
            return Tool.COMMERCIAL
        if i < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    # Layout:
    # Wire spine at py (row 50)
    # Road at py - 5 (row 45) - upper corridor
    # Road at py + 5 (row 55) - lower corridor
    # Zones fill between roads
    # Additional road corridors at py-12 and py+12

    spine_y = py
    road1_y = py - 5   # upper road
    road2_y = py + 5   # lower road
    road3_y = py - 12  # far upper road
    road4_y = py + 12  # far lower road

    road_start = px + 2
    road_end = min(px + 70, WORLD_W - 4)

    # --- Step 1: Wire spine horizontally from plant ---
    for wx in range(px + 2, road_end + 1):
        wy = spine_y
        if not in_bounds(wx, wy):
            break
        if not bool(wm[wy, wx]) and not bool(pm[wy, wx]):
            if bool(em[wy, wx]):
                return (Tool.WIRE, wx, wy)
            break  # blocked

    # --- Step 2: Vertical wire branches to reach zone rows ---
    branch_cols = list(range(px + 4, road_end + 1, 4))
    for bx in branch_cols:
        if not in_bounds(bx, spine_y):
            continue
        if not (bool(wm[spine_y, bx]) or bool(pm[spine_y, bx])):
            continue  # spine not reached here yet
        for sign in [-1, 1]:
            for dy in range(1, 16):
                wy2, wx2 = spine_y + sign * dy, bx
                if not in_bounds(wx2, wy2):
                    break
                if bool(wm[wy2, wx2]) or bool(pm[wy2, wx2]) or bool(rm[wy2, wx2]):
                    continue
                if bool(em[wy2, wx2]):
                    return (Tool.WIRE, wx2, wy2)
                break

    # --- Step 3: Build road rows ---
    for road_y in [road1_y, road2_y, road3_y, road4_y]:
        if not in_bounds(road_start, road_y):
            continue
        for rx in range(road_start, road_end + 1):
            ry = road_y
            if not in_bounds(rx, ry):
                break
            if not bool(rm[ry, rx]) and not bool(pm[ry, rx]):
                if bool(em[ry, rx]):
                    return (Tool.ROAD, rx, ry)
                break

    # --- Step 4: Vertical connector roads every 6 cols ---
    for vc in range(road_start, road_end + 1, 6):
        for vr in range(road3_y, road4_y + 1):
            if not in_bounds(vc, vr):
                continue
            if (bool(rm[vr, vc]) or bool(pm[vr, vc]) or
                    bool(wm[vr, vc])):
                continue
            if bool(em[vr, vc]):
                return (Tool.ROAD, vc, vr)

    # --- Step 5: Second power plant ---
    p2x = min(px + 65, WORLD_W - 5)
    p2y = py
    nearby_plant = False
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            ny2, nx2 = p2y + dy, p2x + dx
            if in_bounds(nx2, ny2) and bool(pm[ny2, nx2]):
                nearby_plant = True
    if not nearby_plant and in_bounds(p2x, p2y) and bool(em[p2y, p2x]):
        return (Tool.COALPOWER, p2x, p2y)

    # --- Step 6: Zone placement ---
    # Build neighbor masks for road proximity
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        step_hash = int(obs.step * 17 + int(obs.city_pop * 3)) % max(len(cxs), 1)
        for offset in range(min(len(cxs), 60)):
            k = (step_hash + offset * 7) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # --- Step 7: Services ---
    if obs.city_pop > 50 or total_zones > 8:
        fx, fy = px + 4, py - 9
        if in_bounds(fx, fy) and bool(em[fy, fx]):
            return (Tool.FIRESTATION, fx, fy)
        fx2, fy2 = px + 4, py + 9
        if in_bounds(fx2, fy2) and bool(em[fy2, fx2]):
            return (Tool.POLICESTATION, fx2, fy2)

    # --- Step 8: Extend roads from frontier ---
    if len(road_xs) > 0:
        step_k = int(obs.step * 13) % max(len(road_xs), 1)
        rx_s, ry_s = int(road_xs[step_k]), int(road_ys[step_k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx_s + dx2, ry_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # --- Step 9: Extend wires from frontier ---
    if len(wire_xs) > 0:
        step_k2 = int(obs.step * 7) % max(len(wire_xs), 1)
        wx_s, wy_s = int(wire_xs[step_k2]), int(wire_ys[step_k2])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = wx_s + dx2, wy_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map every step and adapts placement.
    Strategy:
    - Place coal power plant near center-left if none exists.
    - Grow wire spine horizontally then vertically from plant.
    - Build road column parallel to wire spine.
    - Place zones (RES/COM/IND) adjacent to roads with power coverage.
    - Scan for gaps and fill them reactively.
    """
    tm = obs.tile_map
    step = obs.step

    # Center anchor
    cx, cy = 60, 50

    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    has_plant = np.any(pm)
    plant_positions = list(zip(*np.where(pm)))
    wire_positions = list(zip(*np.where(wm)))
    road_positions = list(zip(*np.where(rm)))
    res_positions = list(zip(*np.where(resm)))

    res_count = len(res_positions)
    com_count = np.sum(comm)
    ind_count = np.sum(indm)

    # --- Phase 1: Place power plant ---
    if not has_plant:
        px, py = cx - 8, cy
        return (Tool.COALPOWER, px, py)

    # Find plant bounding box to know where to start wire
    if plant_positions:
        plant_rows = [r for r, c in plant_positions]
        plant_cols = [c for r, c in plant_positions]
        plant_center_r = (min(plant_rows) + max(plant_rows)) // 2
        plant_center_c = (min(plant_cols) + max(plant_cols)) // 2
    else:
        plant_center_r, plant_center_c = cy, cx - 8

    # Wire spine: vertical column at cx-1
    wire_col = cx - 1
    road_col = cx + 1

    wire_col_rows = sorted([r for (r, c) in wire_positions if c == wire_col])
    road_col_rows = sorted([r for (r, c) in road_positions if c == road_col])

    # Helper: check if 3x3 zone area is clear
    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    # --- Phase 2: Connect plant to wire spine (horizontal bridge) ---
    # Plant footprint right edge ~ plant_center_c + 2
    # We need wire from plant_center_c+3 to wire_col (cx-1)
    bridge_row = plant_center_r
    bridge_start = plant_center_c + 3
    bridge_end = wire_col
    if bridge_start <= bridge_end:
        for bc in range(bridge_start, bridge_end + 1):
            if 0 <= bc < WORLD_W and not wm[bridge_row, bc] and (em[bridge_row, bc] or wm[bridge_row, bc]):
                if em[bridge_row, bc]:
                    return (Tool.WIRE, bc, bridge_row)

    # --- Phase 3: Grow wire spine vertically ---
    target_min = cy - 15
    target_max = cy + 15

    if not wire_col_rows:
        # Start wire spine at plant row
        if 0 <= wire_col < WORLD_W and em[bridge_row, wire_col]:
            return (Tool.WIRE, wire_col, bridge_row)
    else:
        max_row = max(wire_col_rows)
        min_row = min(wire_col_rows)
        # Extend downward
        if max_row < target_max:
            nr = max_row + 1
            if 0 <= nr < WORLD_H and em[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if min_row > target_min:
            nr = min_row - 1
            if 0 <= nr >= 0 and em[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # --- Phase 4: Grow road column parallel to wire ---
    if wire_col_rows:
        for wr in wire_col_rows:
            # Road at road_col same row
            if 0 <= road_col < WORLD_W and not rm[wr, road_col] and em[wr, road_col]:
                return (Tool.ROAD, road_col, wr)
            # Also road at wire_col+1 as connector if not road_col directly reachable
            if not rm[wr, wire_col + 1] and em[wr, wire_col + 1]:
                return (Tool.ROAD, wire_col + 1, wr)

    # --- Phase 5: Lateral wire to left zone column ---
    # Left zones at cx-5, need wire at cx-2, cx-3, cx-4 for power
    for wr in wire_col_rows:
        for wc in range(wire_col - 1, cx - 6, -1):
            if 0 <= wc < WORLD_W and not wm[wr, wc] and em[wr, wc]:
                return (Tool.WIRE, wc, wr)

    # --- Phase 6: Place zones ---
    # Left zones: center at cx-5, spaced by 3 rows
    # Right zones: center at cx+4, spaced by 3 rows
    left_zc = cx - 5
    right_zc = cx + 4

    zone_rows = range(target_min + 1, target_max, 3)

    def has_wire_nearby(zr, zc, radius=3):
        for dr in range(-radius, radius + 1):
            for dc in range(-radius, radius + 1):
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if wm[rr, rc] or pm[rr, rc]:
                        return True
        return False

    def has_road_nearby(zr, zc, radius=3):
        for dr in range(-radius, radius + 1):
            for dc in range(-radius, radius + 1):
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if rm[rr, rc]:
                        return True
        return False

    def already_zone_nearby(zr, zc):
        return any(abs(zr - pr) <= 2 and abs(zc - pc) <= 2
                   for (pr, pc) in res_positions)

    for zr in zone_rows:
        for zc in [left_zc, right_zc]:
            if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                powered = has_wire_nearby(zr, zc)
                roaded = has_road_nearby(zr, zc)
                if powered and roaded and not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                    # Decide zone type based on balance
                    total = res_count + 1
                    if com_count < total // 4:
                        tool = Tool.COMMERCIAL
                    elif ind_count < total // 4:
                        tool = Tool.INDUSTRIAL
                    else:
                        tool = Tool.RESIDENTIAL
                    return (tool, zc, zr)

    # --- Phase 7: Reactive gap fill - scan for unpowered/unroaded zones and fix ---
    # If there are res zones not powered, extend wire toward them
    if res_positions and wire_positions:
        for (pr, pc) in res_positions:
            if not has_wire_nearby(pr, pc, radius=2):
                # Find closest wire position
                closest = min(wire_positions, key=lambda wp: abs(wp[0]-pr)+abs(wp[1]-pc))
                wr, wc = closest
                # Step toward zone
                dr = 0 if pr == wr else (1 if pr > wr else -1)
                dc = 0 if pc == wc else (1 if pc > wc else -1)
                nr, nc = wr + dr, wc + dc
                if 0 <= nr < WORLD_H and 0 <= nc < WORLD_W and em[nr, nc]:
                    return (Tool.WIRE, nc, nr)

    # --- Phase 8: Expand spine if population growing ---
    if obs.city_pop > 100 and wire_col_rows:
        ext_min = cy - 20
        ext_max = cy + 20
        max_row = max(wire_col_rows)
        min_row = min(wire_col_rows)
        if max_row < ext_max:
            nr = max_row + 1
            if 0 <= nr < WORLD_H and em[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)
        if min_row > ext_min:
            nr = min_row - 1
            if nr >= 0 and em[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # --- Phase 9: Extra zone columns further right if population high ---
    if obs.city_pop > 300:
        extra_road_col = cx + 6
        extra_zone_col = cx + 9
        # Extend road
        for wr in wire_col_rows:
            for rc in range(road_col + 1, extra_road_col + 1):
                if 0 <= rc < WORLD_W and not rm[wr, rc] and em[wr, rc]:
                    return (Tool.ROAD, rc, wr)
        # Place zones
        for zr in zone_rows:
            zc = extra_zone_col
            if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                if has_wire_nearby(zr, zc) and has_road_nearby(zr, zc):
                    if not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                        return (Tool.RESIDENTIAL, zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop city builder: reads tile_map each step, reacts to what's on map.
    Strategy:
    1. Place coal power plant if none exists
    2. Extend wire spine rightward from plant, then vertical branches
    3. Build road grid (two horizontal roads + vertical connectors)
    4. Place zones where road+wire access exists
    5. Add second plant when spine reaches far enough
    6. Keep scanning and filling gaps reactively
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Anchor positions
    PLANT_X, PLANT_Y = 25, 50
    PLANT2_X, PLANT2_Y = 85, 50

    has_plant = np.any(pm)

    # Phase 1: Place first coal plant
    if not has_plant:
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    # Read current state from map
    wire_ys, wire_xs = np.where(wm)
    road_ys, road_xs = np.where(rm)
    res_ys, res_xs = np.where(resm)
    com_ys, com_xs = np.where(comm)
    ind_ys, ind_xs = np.where(indm)
    plant_ys, plant_xs = np.where(pm)

    wire_set = set(zip(wire_ys.tolist(), wire_xs.tolist()))
    road_set = set(zip(road_ys.tolist(), road_xs.tolist()))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Find plant bounding box to know where wire starts
    plant_max_x = int(np.max(plant_xs)) if len(plant_xs) > 0 else PLANT_X + 1
    plant_min_x = int(np.min(plant_xs)) if len(plant_xs) > 0 else PLANT_X - 1
    spine_y = PLANT_Y  # wire spine row

    # Spine runs from plant rightward to PLANT2_X
    spine_start = plant_max_x + 1
    spine_end = PLANT2_X - 2

    def pick_tool():
        t = max(total_zones, 1)
        c_ratio = com_count / t
        i_ratio = ind_count / t
        if c_ratio < 0.25:
            return Tool.COMMERCIAL
        if i_ratio < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def is_near_power(cy, cx, radius=5):
        y0 = max(0, cy - radius); y1 = min(WORLD_H, cy + radius + 1)
        x0 = max(0, cx - radius); x1 = min(WORLD_W, cx + radius + 1)
        return bool(np.any(wm[y0:y1, x0:x1])) or bool(np.any(pm[y0:y1, x0:x1]))

    def is_near_road(cy, cx, radius=3):
        y0 = max(0, cy - radius); y1 = min(WORLD_H, cy + radius + 1)
        x0 = max(0, cx - radius); x1 = min(WORLD_W, cx + radius + 1)
        return bool(np.any(rm[y0:y1, x0:x1]))

    def zone_placeable(zx, zy):
        # Check 3x3 footprint is all empty or already part of this zone
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not bool(em[nr, nc]):
                    return False
        return True

    # Phase 2: Extend horizontal wire spine from plant to spine_end
    spine_wire_cols = sorted([c for (r, c) in wire_set if r == spine_y])
    max_spine_col = max(spine_wire_cols) if spine_wire_cols else (plant_max_x)

    if max_spine_col < spine_end:
        nc = max_spine_col + 1
        if in_bounds(nc, spine_y) and not bool(pm[spine_y, nc]):
            if bool(em[spine_y, nc]) or bool(wm[spine_y, nc]):
                return (Tool.WIRE, nc, spine_y)
            else:
                # blocked, bulldoze first
                return (Tool.BULLDOZER, nc, spine_y)

    # Phase 3: Vertical wire branches every 6 cols along spine
    branch_cols = list(range(spine_start + 1, spine_end, 6))
    branch_reach = 9  # how far up/down from spine
    for bx in branch_cols:
        if bx >= WORLD_W:
            continue
        if (spine_y, bx) not in wire_set:
            continue  # spine not laid here yet
        for sign in [-1, 1]:
            for dy in range(1, branch_reach + 1):
                wy = spine_y + sign * dy
                if not in_bounds(bx, wy):
                    break
                if bool(pm[wy, bx]):
                    break
                if (wy, bx) not in wire_set:
                    if bool(em[wy, bx]):
                        return (Tool.WIRE, bx, wy)
                    else:
                        break  # blocked

    # Phase 4: Place second power plant once spine reaches far enough
    near_plant2 = bool(np.any(pm[PLANT2_Y-3:PLANT2_Y+4, PLANT2_X-3:PLANT2_X+4]))
    if not near_plant2:
        if max_spine_col >= PLANT2_X - 6:
            return (Tool.COALPOWER, PLANT2_X, PLANT2_Y)

    # Phase 5: Build road grid
    road_top = spine_y - 4
    road_bot = spine_y + 4
    road_left = spine_start
    road_right = min(spine_end + 2, WORLD_W - 3)

    # Horizontal roads
    for row in [road_top, road_bot]:
        if not in_bounds(0, row):
            continue
        for cx in range(road_left, road_right + 1):
            if in_bounds(cx, row) and (row, cx) not in road_set and not bool(pm[row, cx]):
                return (Tool.ROAD, cx, row)

    # Vertical connector roads every 6 cols
    for vc in range(road_left, road_right + 1, 6):
        for vr in range(road_top, road_bot + 1):
            if in_bounds(vc, vr) and (vr, vc) not in road_set and not bool(pm[vr, vc]):
                return (Tool.ROAD, vc, vr)

    # Phase 6: Place zones reactively
    # Scan candidate zone centers in rows above/below road rows
    zone_row_candidates = []
    for offset in range(2, 15, 3):
        zone_row_candidates.append(road_top - offset)
        zone_row_candidates.append(road_bot + offset)

    for zr in zone_row_candidates:
        if not in_bounds(0, zr) or not in_bounds(0, zr - 1) or not in_bounds(0, zr + 1):
            continue
        for zc in range(road_left + 1, road_right, 4):
            if not in_bounds(zc + 1, zr + 1) or not in_bounds(zc - 1, zr - 1):
                continue
            if not bool(em[zr, zc]):
                continue
            if not is_near_road(zr, zc, radius=4):
                continue
            if not is_near_power(zr, zc, radius=6):
                continue
            if zone_placeable(zc, zr):
                return (pick_tool(), zc, zr)

    # Phase 7: Build additional wire toward zones that lack power
    # Find any zone tile lacking wire access and extend wire toward it
    zone_mask = resm | comm | indm
    zone_locs = list(zip(*np.where(zone_mask)))
    for (zy, zx) in zone_locs[:30]:
        if not is_near_power(zy, zx, radius=4):
            # Find closest wire/plant tile
            if len(wire_xs) > 0:
                dists = np.abs(wire_ys - zy) + np.abs(wire_xs - zx)
                k = int(np.argmin(dists))
                wr, wc = int(wire_ys[k]), int(wire_xs[k])
                # Step wire toward zone
                step_r = wr + (1 if zy > wr else -1 if zy < wr else 0)
                step_c = wc + (1 if zx > wc else -1 if zx < wc else 0)
                if in_bounds(step_c, step_r) and bool(em[step_r, step_c]):
                    return (Tool.WIRE, step_c, step_r)

    # Phase 8: Add more horizontal wire rows to expand power reach
    # Extend wire along road_top-1 and road_bot+1 rows
    for extra_wy in [road_top - 1, road_bot + 1]:
        if not in_bounds(0, extra_wy):
            continue
        extra_wires = sorted([c for (r, c) in wire_set if r == extra_wy])
        max_ew = max(extra_wires) if extra_wires else road_left - 1
        if max_ew < road_right:
            nc = max_ew + 1
            if in_bounds(nc, extra_wy) and bool(em[extra_wy, nc]) and not bool(pm[extra_wy, nc]):
                return (Tool.WIRE, nc, extra_wy)

    # Phase 9: Extend road grid further out if population is growing
    if obs.city_pop > 100:
        extra_road_top = road_top - 7
        extra_road_bot = road_bot + 7
        for row in [extra_road_top, extra_road_bot]:
            if not in_bounds(0, row):
                continue
            for cx in range(road_left, road_right + 1):
                if in_bounds(cx, row) and (row, cx) not in road_set and not bool(pm[row, cx]):
                    if bool(em[row, cx]):
                        return (Tool.ROAD, cx, row)

    # Phase 10: Generic scan for empty powered+roaded spots
    # Build neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand = em & nbr_road & nbr_wire
    cand[0:2, :] = False
    cand[WORLD_H-2:, :] = False
    cand[:, 0:2] = False
    cand[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        # Try step-based offset for variety
        offset = (obs.step * 17) % len(cxs)
        for i in range(min(len(cxs), 30)):
            k = (offset + i * 7) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_placeable(zx, zy):
                return (pick_tool(), zx, zy)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map each step to decide next placement.
    Strategy:
    - Place coal power plant at fixed position.
    - Build a wire spine vertically from the plant.
    - Build a road column adjacent to the wire spine.
    - Place zones (RES/COM/IND) on both sides, connected to wire and road.
    - Lateral wires connect zones to spine; lateral roads connect right zones.
    - Expand outward as city grows.
    Key differences from parent:
    - More compact layout: zones closer to wire/road spine.
    - Wire spine on both sides of plant for better coverage.
    - More balanced RES/COM/IND ratio.
    - Extend further when population grows.
    - Build a second road column for right zones.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    # Use center-left area for layout
    cx, cy = 55, 50

    # Power plant position (center of 3x3 footprint)
    plant_x, plant_y = cx - 6, cy

    has_plant = np.any(pm)

    # Phase 1: Place coal power plant
    if not has_plant:
        return (Tool.COALPOWER, plant_x, plant_y)

    # Find plant location
    plant_positions = list(zip(*np.where(pm)))
    if plant_positions:
        plant_row, plant_col = plant_positions[0]
        plant_y, plant_x = plant_row, plant_col

    # Wire spine column: just right of plant footprint
    wire_col = plant_x + 4  # right edge of plant + 1
    road_col = wire_col + 2  # road 2 cols right of wire
    road_col2 = road_col + 4  # second road for far-right zones

    wire_positions = list(zip(*np.where(wm)))
    road_positions = list(zip(*np.where(rm)))
    res_positions = list(zip(*np.where(res_mask(tm))))
    com_positions = list(zip(*np.where(com_mask(tm))))
    ind_positions = list(zip(*np.where(ind_mask(tm))))

    wire_col_rows = sorted([r for (r, c) in wire_positions if c == wire_col])
    road_col_rows = sorted([r for (r, c) in road_positions if c == road_col])
    road2_col_rows = sorted([r for (r, c) in road_positions if c == road_col2])

    res_count = len(res_positions)
    com_count = len(com_positions)
    ind_count = len(ind_positions)

    # Phase 2: Start wire adjacent to plant if none
    if not wire_col_rows:
        # Plant footprint: plant_x-1..plant_x+1, plant_y-1..plant_y+1
        # Wire col is plant_x+4, row plant_y
        for dy in range(0, 5):
            for nr in [plant_y + dy, plant_y - dy]:
                if 0 <= nr < WORLD_H and 0 <= wire_col < WORLD_W:
                    # Auto-bulldoze handles non-empty tiles
                    return (Tool.WIRE, wire_col, nr)
        return None

    # Phase 3: Extend wire spine vertically
    target_min = max(1, plant_y - 18)
    target_max = min(WORLD_H - 2, plant_y + 18)

    min_row = min(wire_col_rows)
    max_row = max(wire_col_rows)

    # Extend downward first
    if max_row < target_max:
        nr = max_row + 1
        if nr < WORLD_H:
            return (Tool.WIRE, wire_col, nr)

    # Extend upward
    if min_row > target_min:
        nr = min_row - 1
        if nr >= 0:
            return (Tool.WIRE, wire_col, nr)

    # Phase 4: Build primary road column
    for r in sorted(wire_col_rows):
        if 0 <= road_col < WORLD_W and not rm[r, road_col]:
            return (Tool.ROAD, road_col, r)

    # Phase 5: Lateral wire from spine to left zone positions
    left_zone_col = wire_col - 3
    # Connect spine to left zone col at each wire row
    for r in wire_col_rows:
        for c in range(wire_col - 1, left_zone_col - 1, -1):
            if 0 <= c < WORLD_W and not wm[r, c] and c != plant_x:
                # Don't overwrite plant (plant is at plant_x +/- 1)
                if abs(c - plant_x) > 1 or abs(r - plant_y) > 1:
                    return (Tool.WIRE, c, r)
        break  # do one row at a time

    # Phase 6: Lateral road from primary road to right zone col
    right_zone_col = road_col + 3
    for r in road_col_rows:
        for c in range(road_col + 1, right_zone_col + 2):
            if 0 <= c < WORLD_W and not rm[r, c]:
                return (Tool.ROAD, c, r)
        break

    # Helper: check if 3x3 area is free of plants
    def zone_area_clear(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                # Don't place over plant
                if pm[rr, rc]:
                    return False
        return True

    def zone_exists_near(zr, zc, all_zone_pos):
        return any(abs(zr - pr) <= 1 and abs(zc - pc) <= 1 for (pr, pc) in all_zone_pos)

    all_zone_pos = res_positions + com_positions + ind_positions

    # Phase 7: Place zones where wire AND road coverage exists
    zone_rows = sorted(set(
        list(range(max(1, plant_y - 17), min(WORLD_H - 2, plant_y + 18), 3))
    ))

    for zr in zone_rows:
        wire_near = any(abs(zr - wr) <= 2 for wr in wire_col_rows)
        road_near = any(abs(zr - rr) <= 2 for (rr, rc) in road_positions if rc == road_col)

        if wire_near and road_near:
            # Left zone (connected via lateral wire)
            zc = left_zone_col
            if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                if not zone_exists_near(zr, zc, all_zone_pos) and zone_area_clear(zr, zc):
                    # Balance: want ~1/4 IND, 1/4 COM, 1/2 RES
                    total = res_count + com_count + ind_count
                    if ind_count * 4 < total + 1:
                        return (Tool.INDUSTRIAL, zc, zr)
                    elif com_count * 4 < total + 1:
                        return (Tool.COMMERCIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

            # Right zone (road access)
            zc = right_zone_col
            if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                if not zone_exists_near(zr, zc, all_zone_pos) and zone_area_clear(zr, zc):
                    total = res_count + com_count + ind_count
                    if com_count * 4 < total + 1:
                        return (Tool.COMMERCIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

    # Phase 8: Continue lateral wires for all rows (catch stragglers)
    for r in wire_col_rows:
        for c in range(wire_col - 1, left_zone_col - 1, -1):
            if 0 <= c < WORLD_W and not wm[r, c]:
                if abs(c - plant_x) > 1 or abs(r - plant_y) > 1:
                    return (Tool.WIRE, c, r)

    # Phase 9: Continue lateral roads for all rows
    for r in road_col_rows:
        for c in range(road_col + 1, right_zone_col + 2):
            if 0 <= c < WORLD_W and not rm[r, c]:
                return (Tool.ROAD, c, r)

    # Phase 10: Expand further if growing
    if obs.city_pop > 200:
        far_left_col = left_zone_col - 4
        far_right_col = right_zone_col + 4

        # Extend wire left
        for r in wire_col_rows:
            for c in range(wire_col - 1, far_left_col - 1, -1):
                if 0 <= c < WORLD_W and not wm[r, c]:
                    if abs(c - plant_x) > 1 or abs(r - plant_y) > 1:
                        return (Tool.WIRE, c, r)
            break

        # Second road column
        for r in road_col_rows:
            if 0 <= road_col2 < WORLD_W and not rm[r, road_col2]:
                return (Tool.ROAD, road_col2, r)

        # More zones
        extra_rows = list(range(max(1, plant_y - 20), min(WORLD_H - 2, plant_y + 21), 3))
        for zr in extra_rows:
            for zc in [far_left_col, far_right_col]:
                if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                    if not zone_exists_near(zr, zc, all_zone_pos) and zone_area_clear(zr, zc):
                        road_near = any(
                            abs(zr - rr) <= 3 and abs(zc - rc2) <= 5
                            for (rr, rc2) in road_positions
                        )
                        wire_near2 = any(
                            abs(zr - wr) <= 3 and abs(zc - wc2) <= 5
                            for (wr, wc2) in wire_positions
                        )
                        if road_near and wire_near2:
                            return (Tool.RESIDENTIAL, zc, zr)

    # Phase 11: Nuclear power if very large
    if obs.city_pop > 500:
        nuke_x, nuke_y = plant_x - 8, plant_y + 8
        if 1 <= nuke_y < WORLD_H - 1 and 1 <= nuke_x < WORLD_W - 1:
            if not np.any(pm[nuke_y - 1:nuke_y + 2, nuke_x - 1:nuke_x + 2]):
                return (Tool.NUCLEARPOWER, nuke_x, nuke_y)

    return None

def act(obs, state):
    """
    Different layout: horizontal spine (road + wire rows) with zones above/below.
    Two power plants. Balanced R/C/I. Wider coverage.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def has_tile(mask, x, y):
        if 0 <= y < WORLD_H and 0 <= x < WORLD_W:
            return bool(mask[y, x])
        return False

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        all_zone = resm | comm | indm
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone[rr, rc]:
                    return False
        return True

    def zone_present(zr, zc):
        all_zone = resm | comm | indm
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone[rr, rc]:
                        return True
        return False

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        # Target: 50% RES, 30% COM, 20% IND
        if com_count / t < 0.30:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Horizontal spine layout:
    # wire_row: horizontal wire row
    # road_row: horizontal road row (wire_row + 1)
    # zones above: top_zrow = wire_row - 3
    # zones below: bot_zrow = road_row + 3
    # plant at left side of wire row

    wire_row = cy - 1
    road_row = cy        # road just below wire
    top_zrow = wire_row - 3
    bot_zrow = road_row + 3

    # Clamp
    wire_row = max(2, min(WORLD_H - 3, wire_row))
    road_row = max(2, min(WORLD_H - 3, road_row))
    top_zrow = max(2, min(WORLD_H - 3, top_zrow))
    bot_zrow = max(2, min(WORLD_H - 3, bot_zrow))

    plant_x = cx - 20
    plant_y = wire_row
    plant_x = max(2, min(WORLD_W - 3, plant_x))

    # Adaptive spine extent
    if obs.city_pop < 50:
        spine_half = 10
    elif obs.city_pop < 200:
        spine_half = 18
    elif obs.city_pop < 500:
        spine_half = 28
    else:
        spine_half = 40

    spine_min = max(1, cx - spine_half)
    spine_max = min(WORLD_W - 2, cx + spine_half)
    spine_range = range(spine_min, spine_max + 1)

    # Phase 0: Place first coal power plant
    if not np.any(pm):
        return (Tool.COALPOWER, plant_x, plant_y)

    # Phase 1: Wire spine horizontal row
    for dx in spine_range:
        if not has_tile(wm, dx, wire_row) and not has_tile(pm, dx, wire_row):
            if not has_tile(rm, dx, wire_row):
                return (Tool.WIRE, dx, wire_row)

    # Phase 2: Road row adjacent to wire
    for dx in spine_range:
        if not has_tile(rm, dx, road_row) and not has_tile(pm, dx, road_row):
            if not has_tile(wm, dx, road_row):
                return (Tool.ROAD, dx, road_row)

    wire_cols = [c for c in spine_range if wm[wire_row, c]]
    road_cols = [c for c in spine_range if rm[road_row, c]]

    # Phase 3: Place zones above and below the spine
    zone_cols = list(range(spine_min + 1, spine_max - 1, 4))

    for zc in zone_cols:
        wire_near = any(abs(zc - wc) <= 3 for wc in wire_cols)
        road_near = any(abs(zc - rc) <= 3 for rc in road_cols)

        if wire_near and road_near:
            # Top zone
            zr = top_zrow
            if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                return (pick_tool(), zc, zr)

            # Bottom zone
            zr = bot_zrow
            if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                return (pick_tool(), zc, zr)

    # Phase 4: Vertical wires to connect top zones to wire row
    for wc in wire_cols:
        for wr in range(wire_row - 1, top_zrow - 1, -1):
            if 0 <= wr < WORLD_H:
                if wm[wr, wc] or pm[wr, wc]:
                    break
                if em[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif rm[wr, wc]:
                    continue
                else:
                    break

    # Phase 5: Vertical wires to connect bottom zones via road row
    for rc in road_cols:
        for wr in range(road_row + 1, bot_zrow + 2):
            if 0 <= wr < WORLD_H:
                if wm[wr, rc] or pm[wr, rc]:
                    break
                if em[wr, rc] and not rm[wr, rc]:
                    return (Tool.WIRE, rc, wr)
                elif rm[wr, rc]:
                    continue
                else:
                    break

    # Phase 6: Second coal plant if growing
    if obs.city_pop > 200 and int(np.sum(pm)) < 9:
        px2 = cx + 20
        py2 = wire_row
        px2 = max(2, min(WORLD_W - 3, px2))
        if 2 <= py2 <= WORLD_H - 3:
            if em[py2, px2]:
                return (Tool.COALPOWER, px2, py2)

    # Phase 7: Second tier of zones further out
    if obs.city_pop > 150:
        top2_zrow = top_zrow - 4
        bot2_zrow = bot_zrow + 4
        top2_zrow = max(2, min(WORLD_H - 3, top2_zrow))
        bot2_zrow = max(2, min(WORLD_H - 3, bot2_zrow))

        for zc in zone_cols:
            wire_near = any(abs(zc - wc) <= 3 for wc in wire_cols)
            road_near = any(abs(zc - rc) <= 3 for rc in road_cols)
            if wire_near and road_near:
                for zr in [top2_zrow, bot2_zrow]:
                    if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                        r0 = max(0, zr - 5); r1 = min(WORLD_H, zr + 6)
                        c0 = max(0, zc - 5); c1 = min(WORLD_W, zc + 6)
                        if np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1]):
                            if np.any(rm[r0:r1, c0:c1]):
                                return (pick_tool(), zc, zr)

    # Phase 8: Add vertical roads at zone columns to improve road access
    if obs.city_pop > 80:
        for zc in zone_cols[::2]:
            if 0 <= zc < WORLD_W:
                for zr in range(top_zrow - 1, bot_zrow + 2):
                    if 0 <= zr < WORLD_H and em[zr, zc] and not pm[zr, zc] and not wm[zr, zc]:
                        return (Tool.ROAD, zc, zr)

    # Phase 9: Add a second horizontal road for better connectivity
    if obs.city_pop > 300:
        road2_row = bot_zrow + 1
        if 0 <= road2_row < WORLD_H:
            for dx in spine_range:
                if em[road2_row, dx] and not pm[road2_row, dx]:
                    return (Tool.ROAD, dx, road2_row)

    return None

def act(obs, state):
    """
    Closed-loop policy: each step reads the current map and decides
    what to place next based on observed state.

    Strategy:
    1. If no power plant exists, place one near center
    2. Extend wires from the power plant toward target zones
    3. Build roads in a grid pattern near powered areas
    4. Place zones (RES/COM/IND) adjacent to roads and powered areas
    5. Reactively fill gaps based on current map state
    """
    tm = obs.tile_map
    step = obs.step

    # Read current map state
    res = res_mask(tm)
    com = com_mask(tm)
    ind = ind_mask(tm)
    roads = road_mask(tm)
    wires = wire_mask(tm)
    plants = plant_mask(tm)
    empty = empty_mask(tm)

    # Core working area: left-center cluster
    # Build around (40, 45) as the hub
    HUB_X, HUB_Y = 40, 45

    # === Phase 1: Ensure we have a power plant ===
    if not plants.any():
        # Place coal plant at hub
        return (Tool.COALPOWER, HUB_X, HUB_Y)

    # Find the power plant location
    plant_ys, plant_xs = np.where(plants)
    px, py = int(plant_xs[0]), int(plant_ys[0])

    # === Phase 2: Build wire network outward from plant ===
    # Wire should spread out in a cross/grid pattern
    # Count existing wires
    n_wires = int(wires.sum())
    n_roads = int(roads.sum())
    n_res = int(res.sum())
    n_com = int(com.sum())
    n_ind = int(ind.sum())
    n_zones = n_res + n_com + n_ind

    # We need enough wires before roads and zones
    # Target: wire along key corridors

    # Define wire corridors (horizontal and vertical from plant)
    wire_targets = []
    # Horizontal wire rightward from plant
    for dx in range(1, 25):
        wire_targets.append((px + dx, py))
    # Vertical wire upward
    for dy in range(1, 20):
        wire_targets.append((px, py - dy))
    # Vertical wire downward
    for dy in range(1, 20):
        wire_targets.append((px, py + dy))
    # Secondary horizontal at offset
    for dx in range(0, 20):
        wire_targets.append((px + dx, py - 6))
        wire_targets.append((px + dx, py + 6))

    # Place wires not yet placed, adjacent to existing wire/plant
    # A wire is valid if it's empty and adjacent to existing power infrastructure
    def has_power_neighbor(x, y):
        for dx2, dy2 in [(-1,0),(1,0),(0,-1),(0,1)]:
            nx, ny = x+dx2, y+dy2
            if 0 <= nx < WORLD_W and 0 <= ny < WORLD_H:
                if wires[ny, nx] or plants[ny, nx]:
                    return True
        return False

    def has_road_neighbor(x, y):
        for dx2, dy2 in [(-1,0),(1,0),(0,-1),(0,1)]:
            nx, ny = x+dx2, y+dy2
            if 0 <= nx < WORLD_W and 0 <= ny < WORLD_H:
                if roads[ny, nx]:
                    return True
        return False

    # Check if we need more wires (need to power zones)
    # Try to extend wire to an unconnected wire target
    if n_wires < 40:
        for (wx, wy) in wire_targets:
            if 0 <= wx < WORLD_W and 0 <= wy < WORLD_H:
                if empty[wy, wx] and has_power_neighbor(wx, wy):
                    return (Tool.WIRE, wx, wy)

    # === Phase 3: Build road grid ===
    # Roads run parallel/perpendicular to wire corridors
    road_targets = []
    # Main horizontal road just above wire line
    for dx in range(-2, 22):
        road_targets.append((px + dx, py - 1))
    for dx in range(-2, 22):
        road_targets.append((px + dx, py + 1))
    # Vertical roads every 6 columns
    for col_offset in range(0, 22, 6):
        for dy in range(-10, 12):
            road_targets.append((px + col_offset, py + dy))
    # More horizontal roads spaced 6 rows apart
    for row_offset in range(-6, 13, 6):
        for dx in range(-2, 22):
            road_targets.append((px + dx, py + row_offset))

    if n_roads < 80:
        for (rx, ry) in road_targets:
            if 0 <= rx < WORLD_W and 0 <= ry < WORLD_H:
                if empty[ry, rx] and has_road_neighbor(rx, ry):
                    return (Tool.ROAD, rx, ry)
        # Bootstrap: place first road adjacent to plant
        for dx2, dy2 in [(1,0),(0,1),(-1,0),(0,-1)]:
            rx, ry = px+dx2, py+dy2
            if 0 <= rx < WORLD_W and 0 <= ry < WORLD_H and empty[ry, rx]:
                return (Tool.ROAD, rx, ry)

    # === Phase 4: Place zones near roads and powered areas ===
    # Zones need road access (within 1 tile) and power (wire/plant within 1 tile or connected)

    # Compute "powered" mask: tiles adjacent to wire or plant
    powered = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    src = wires | plants
    powered[1:, :] |= src[:-1, :]
    powered[:-1, :] |= src[1:, :]
    powered[:, 1:] |= src[:, :-1]
    powered[:, :-1] |= src[:, 1:]
    powered |= src

    # Compute "road_adjacent" mask
    road_adj = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    road_adj[1:, :] |= roads[:-1, :]
    road_adj[:-1, :] |= roads[1:, :]
    road_adj[:, 1:] |= roads[:, :-1]
    road_adj[:, :-1] |= roads[:, 1:]

    # Good zone locations: empty, adjacent to road, adjacent to power
    good = empty & road_adj & powered

    # Decide what zone type to place based on current balance
    total = n_zones + 1
    if n_com / total < 0.20:
        preferred_tool = Tool.COMMERCIAL
    elif n_ind / total < 0.15:
        preferred_tool = Tool.INDUSTRIAL
    else:
        preferred_tool = Tool.RESIDENTIAL

    if good.any():
        ys, xs = np.where(good)
        # Pick deterministically but vary by step to avoid getting stuck
        k = (step * 13 + int(obs.city_pop) * 7) % len(xs)
        cx, cy = int(xs[k]), int(ys[k])
        return (preferred_tool, cx, cy)

    # === Phase 5: Extend wires further if zones exist but need power ===
    if n_wires < 80:
        for (wx, wy) in wire_targets:
            if 0 <= wx < WORLD_W and 0 <= wy < WORLD_H:
                if empty[wy, wx] and has_power_neighbor(wx, wy):
                    return (Tool.WIRE, wx, wy)

    # === Phase 6: More roads if needed ===
    if n_roads < 150:
        for (rx, ry) in road_targets:
            if 0 <= rx < WORLD_W and 0 <= ry < WORLD_H:
                if empty[ry, rx]:
                    # Place even if not yet adjacent (bootstrapping)
                    return (Tool.ROAD, rx, ry)

    # === Phase 7: Add a second power plant if population warrants ===
    if obs.city_pop > 500 and n_zones > 30:
        # Place nuclear plant further east
        nuke_x, nuke_y = HUB_X + 30, HUB_Y
        if 0 <= nuke_x < WORLD_W and 0 <= nuke_y < WORLD_H:
            if empty[nuke_y, nuke_x]:
                return (Tool.NUCLEARPOWER, nuke_x, nuke_y)

    # Fallback: place residential near any road
    if road_adj.any():
        cand = empty & road_adj
        if cand.any():
            ys, xs = np.where(cand)
            k = step % len(xs)
            return (Tool.RESIDENTIAL, int(xs[k]), int(ys[k]))

    return None

def act(obs, state):
    if "plan" not in state:
        plan = []

        # Strategy: Build a grid-based city with clear road network
        # Use a central power plant with roads radiating outward
        # Focus on dense zone placement with proper power/road access

        # Central coal power plant at (60, 50)
        cx, cy = 60, 50
        plan.append((Tool.COALPOWER, cx, cy))

        # Wire grid: horizontal and vertical spines from plant
        # Horizontal wire spine
        for x in range(20, 100):
            plan.append((Tool.WIRE, x, cy))
        # Vertical wire spine
        for y in range(20, 80):
            plan.append((Tool.WIRE, cx, y))

        # Road grid: parallel roads every 4 tiles
        # Horizontal roads above and below wire spine
        for offset in [-4, -8, -12, 4, 8, 12]:
            ry = cy + offset
            if 5 <= ry <= 94:
                for x in range(20, 100):
                    plan.append((Tool.ROAD, x, ry))

        # Vertical roads left and right of wire spine
        for offset in [-4, -8, -12, -16, 4, 8, 12, 16]:
            rx = cx + offset
            if 5 <= rx <= 114:
                for y in range(20, 80):
                    plan.append((Tool.ROAD, rx, y))

        # Now place zones in the grid cells between roads
        # Each cell is bounded by roads; place zone center in middle of cell
        # Grid cells: x from 20..99, y from 20..79
        # Roads at y: 38, 42, 46(wire), 50, 54, 58, 62
        # Roads at x: 44, 48, 52(wire), 56, 60, 64, 68, 72, 76

        # Place zones systematically
        # Rows of zones between horizontal roads
        zone_rows = [cy - 6, cy - 10, cy + 2, cy + 6, cy + 10]
        zone_cols = list(range(cx - 14, cx + 17, 4))

        for i, zy in enumerate(zone_rows):
            if not (5 <= zy <= 94):
                continue
            for j, zx in enumerate(zone_cols):
                if not (5 <= zx <= 114):
                    continue
                # Skip positions too close to power plant
                if abs(zx - cx) < 4 and abs(zy - cy) < 4:
                    continue
                # Zone mix: outer = industrial, middle = commercial, inner = residential
                dist = abs(zx - cx) + abs(zy - cy)
                if dist > 20:
                    tool = Tool.INDUSTRIAL
                elif dist > 12:
                    tool = Tool.COMMERCIAL
                else:
                    tool = Tool.RESIDENTIAL
                plan.append((tool, zx, zy))

        # Second power plant (nuclear) for the far areas
        plan.append((Tool.NUCLEARPOWER, 30, 50))
        # Wire from second plant to main wire spine
        for x in range(30, 61):
            plan.append((Tool.WIRE, x, cy))

        # Third coal plant on right
        plan.append((Tool.COALPOWER, 85, 50))
        for x in range(61, 86):
            plan.append((Tool.WIRE, x, cy))

        # Fire and police stations
        plan.append((Tool.FIRESTATION, cx - 6, cy - 16))
        plan.append((Tool.POLICESTATION, cx + 6, cy - 16))
        plan.append((Tool.FIRESTATION, cx - 6, cy + 16))
        plan.append((Tool.POLICESTATION, cx + 6, cy + 16))

        # Extra zones in a second cluster further out
        # Upper cluster around y=30
        cx2, cy2 = 60, 30
        plan.append((Tool.COALPOWER, cx2, cy2))
        for x in range(35, 85):
            plan.append((Tool.WIRE, x, cy2))
        for offset in [-4, 4]:
            for x in range(35, 85):
                plan.append((Tool.ROAD, x, cy2 + offset))
        # Connect upper cluster vertically
        for y in range(30, 50):
            plan.append((Tool.WIRE, cx, y))
        for offset in [-4, 4]:
            for y in range(30, 50):
                plan.append((Tool.ROAD, cx + offset, y))

        for zx in range(38, 82, 4):
            for zy in [cy2 - 2, cy2 + 2]:
                if abs(zx - cx2) < 3 and abs(zy - cy2) < 3:
                    continue
                dist = abs(zx - cx2)
                if dist > 14:
                    tool = Tool.INDUSTRIAL
                elif dist > 8:
                    tool = Tool.COMMERCIAL
                else:
                    tool = Tool.RESIDENTIAL
                plan.append((tool, zx, zy))

        state["plan"] = plan
        state["i"] = 0

    i = state["i"]
    plan = state["plan"]

    if i < len(plan):
        state["i"] = i + 1
        tool, x, y = plan[i]
        # Clamp coordinates
        x = max(0, min(119, x))
        y = max(0, min(99, y))
        return (tool, x, y)

    # Reactive phase: add more zones near roads that are empty
    tm = obs.tile_map
    emp = empty_mask(tm)
    road = road_mask(tm)

    # Expand road adjacency
    road_near = np.zeros((100, 120), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1),(-2,0),(2,0),(0,-2),(0,2)]:
        shifted_y = np.clip(np.arange(100).reshape(-1,1) + dy, 0, 99)
        shifted_x = np.clip(np.arange(120).reshape(1,-1) + dx, 0, 119)
        road_near |= road[shifted_y, shifted_x]

    cand = emp & road_near
    ys, xs = np.where(cand)

    if len(xs) == 0:
        return None

    k = int((obs.step * 17 + obs.city_pop * 3) % len(xs))
    x, y = int(xs[k]), int(ys[k])

    # More commercial bias in reactive phase
    r = (obs.step + k * 7) % 9
    if r < 3:
        tool = Tool.RESIDENTIAL
    elif r < 7:
        tool = Tool.COMMERCIAL
    else:
        tool = Tool.INDUSTRIAL

    return (tool, x, y)

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Read map each step, find where wire/road/zones already exist
    - Extend incrementally from actual observed state
    - Place power plant, then wire to zones, then roads, then zones
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    # City anchor: compact zone in the middle
    CX, CY = 55, 50

    has_plant = np.any(pm)
    plant_ys, plant_xs = np.where(pm)
    wire_ys, wire_xs = np.where(wm)
    road_ys, road_xs = np.where(rm)
    zone_mask = resm | comm | indm
    zone_ys, zone_xs = np.where(zone_mask)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # --- Phase 1: Place coal power plant ---
    if not has_plant:
        return (Tool.COALPOWER, CX - 15, CY)

    # Plant center (use leftmost/topmost plant tile as anchor)
    # Find approximate plant center
    px_center = int(np.mean(plant_xs))
    py_center = int(np.mean(plant_ys))
    # Plant right edge
    plant_right = int(np.max(plant_xs)) + 1

    # --- Phase 2: Wire spine rightward from plant ---
    # Spine row = plant center row
    spine_y = py_center
    wire_end_target = CX + 40

    # Find rightmost wire on spine row
    spine_wire_cols = [c for (r, c) in zip(wire_ys, wire_xs) if r == spine_y]
    if spine_wire_cols:
        max_spine_wire = max(spine_wire_cols)
    else:
        max_spine_wire = plant_right - 1

    # Extend wire rightward along spine
    if max_spine_wire < wire_end_target:
        nc = max_spine_wire + 1
        if 0 <= nc < WORLD_W and 0 <= spine_y < WORLD_H:
            if not pm[spine_y, nc]:
                return (Tool.WIRE, nc, spine_y)

    # --- Phase 3: Vertical wire branches at intervals ---
    branch_spacing = 6
    branch_cols = list(range(plant_right + 2, wire_end_target + 1, branch_spacing))
    vert_reach = 18  # how far up/down to extend wire

    wire_set = set(zip(wire_ys.tolist(), wire_xs.tolist()))
    plant_set = set(zip(plant_ys.tolist(), plant_xs.tolist()))

    for bc in branch_cols:
        if not (0 <= bc < WORLD_W):
            continue
        if (spine_y, bc) not in wire_set:
            continue
        # Extend upward
        for wr in range(spine_y - 1, max(spine_y - vert_reach, 2) - 1, -1):
            if (wr, bc) in wire_set:
                continue
            if (wr, bc) in plant_set:
                break
            if em[wr, bc]:
                return (Tool.WIRE, bc, wr)
            break
        # Extend downward
        for wr in range(spine_y + 1, min(spine_y + vert_reach, WORLD_H - 2) + 1):
            if (wr, bc) in wire_set:
                continue
            if (wr, bc) in plant_set:
                break
            if em[wr, bc]:
                return (Tool.WIRE, bc, wr)
            break

    # --- Phase 4: Horizontal roads above and below spine ---
    road_above_y = spine_y - 4
    road_below_y = spine_y + 4
    road_start_x = plant_right + 2
    road_end_x = wire_end_target + 4

    road_set = set(zip(road_ys.tolist(), road_xs.tolist()))

    for rrow in [road_above_y, road_below_y]:
        if not (2 <= rrow < WORLD_H - 2):
            continue
        # Find rightmost road on this row
        row_road_cols = [c for (r, c) in road_set if r == rrow]
        if row_road_cols:
            max_rc = max(row_road_cols)
        else:
            max_rc = road_start_x - 1
        if max_rc < road_end_x:
            nc = max_rc + 1
            if 0 <= nc < WORLD_W and not pm[rrow, nc]:
                return (Tool.ROAD, nc, rrow)

    # --- Phase 5: Vertical connector roads every branch_spacing cols ---
    for vc in branch_cols:
        if not (0 <= vc < WORLD_W):
            continue
        for vr in range(road_above_y, road_below_y + 1):
            if not (0 <= vr < WORLD_H):
                continue
            if (vr, vc) not in road_set and not pm[vr, vc]:
                return (Tool.ROAD, vc, vr)

    # --- Phase 6: Place zones reactively ---
    # Zone centers offset from roads; check road and wire proximity
    zone_cols = list(range(road_start_x + 3, road_end_x - 1, branch_spacing))
    zone_row_offsets = [
        road_above_y - 2,
        road_above_y - 5,
        road_above_y - 8,
        road_below_y + 2,
        road_below_y + 5,
        road_below_y + 8,
    ]

    zone_set = set(zip(zone_ys.tolist(), zone_xs.tolist()))

    def road_nearby(zy, zx, r=4):
        for dr in range(-r, r+1):
            for dc in range(-r, r+1):
                if (zy+dr, zx+dc) in road_set:
                    return True
        return False

    def wire_nearby(zy, zx, r=5):
        for dr in range(-r, r+1):
            for dc in range(-r, r+1):
                rr, rc = zy+dr, zx+dc
                if (rr, rc) in wire_set:
                    return True
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W and pm[rr, rc]:
                    return True
        return False

    def zone_footprint_ok(zy, zx):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zy+dr, zx+dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if pm[rr, rc]:
                    return False
                if not em[rr, rc] and (rr, rc) not in zone_set:
                    return False
        return True

    def overlaps_zone(zy, zx):
        for dr in [-2, -1, 0, 1, 2]:
            for dc in [-2, -1, 0, 1, 2]:
                if (zy+dr, zx+dc) in zone_set:
                    return True
        return False

    def pick_tool():
        t = max(total_zones, 1)
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    for zr in zone_row_offsets:
        for zc in zone_cols:
            if not (2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3):
                continue
            if overlaps_zone(zr, zc):
                continue
            if not zone_footprint_ok(zr, zc):
                continue
            if road_nearby(zr, zc) and wire_nearby(zr, zc):
                return (pick_tool(), zc, zr)

    # --- Phase 7: Add more wire toward unpowered zones ---
    for i in range(min(len(zone_ys), 20)):
        zy, zx = int(zone_ys[i]), int(zone_xs[i])
        if not wire_nearby(zy, zx, r=4):
            if wire_set:
                closest = min(wire_set, key=lambda p: abs(p[0]-zy)+abs(p[1]-zx))
                wr, wc = closest
                # Move one step toward zone
                nr = wr + (1 if zy > wr else -1 if zy < wr else 0)
                nc = wc + (1 if zx > wc else -1 if zx < wc else 0)
                if 0 <= nr < WORLD_H and 0 <= nc < WORLD_W and em[nr, nc]:
                    return (Tool.WIRE, nc, nr)

    # --- Phase 8: Second power plant if population growing ---
    if obs.city_pop > 300 and len(plant_xs) < 6:
        p2x, p2y = CX + 30, CY
        if 0 <= p2y < WORLD_H and 0 <= p2x < WORLD_W and em[p2y, p2x]:
            return (Tool.COALPOWER, p2x, p2y)

    # --- Phase 9: More zone rows further out ---
    extra_rows = [road_above_y - 11, road_below_y + 11]
    for zr in extra_rows:
        for zc in zone_cols:
            if not (2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3):
                continue
            if overlaps_zone(zr, zc):
                continue
            if not zone_footprint_ok(zr, zc):
                continue
            if road_nearby(zr, zc, r=5) and wire_nearby(zr, zc, r=7):
                return (pick_tool(), zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads current map state each step and reacts.
    Strategy:
    - Place coal plant first, then extend wire spine, then roads, then zones.
    - Each step scans the map to find where to extend next.
    - Adapts to what's already placed.
    """
    tm = obs.tile_map
    step = obs.step

    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # Count existing zones
    res_count = int(np.sum(res_m))
    com_count = int(np.sum(com_m))
    ind_count = int(np.sum(ind_m))
    total_zones = res_count + com_count + ind_count

    # Central spine parameters
    spine_y = 50
    plant_x = 20
    spine_x_start = 23  # just right of plant footprint edge
    spine_x_end = 100

    # Road rows (parallel to wire spine)
    road_row_top = spine_y - 3
    road_row_bot = spine_y + 3

    # Zone rows
    zone_rows_above = [spine_y - 7, spine_y - 11, spine_y - 15, spine_y - 19]
    zone_rows_below = [spine_y + 7, spine_y + 11, spine_y + 15, spine_y + 19]
    # Zone columns: every 6 cols from spine_x_start+2
    zone_cols = list(range(spine_x_start + 2, spine_x_end, 6))

    # Helper: is area free for 3x3 zone centered at (cx, cy)?
    def zone_area_free(cx, cy):
        for dy in [-1, 0, 1]:
            for dx in [-1, 0, 1]:
                ny, nx = cy + dy, cx + dx
                if ny < 0 or ny >= WORLD_H or nx < 0 or nx >= WORLD_W:
                    return False
                if not em[ny, nx]:
                    return False
        return True

    def pick_zone_type():
        total = res_count + com_count + ind_count + 1
        r_frac = res_count / total
        c_frac = com_count / total
        i_frac = ind_count / total
        if i_frac < 0.20:
            return Tool.INDUSTRIAL
        elif c_frac < 0.25:
            return Tool.COMMERCIAL
        else:
            return Tool.RESIDENTIAL

    # --- Phase 1: Ensure coal plant exists ---
    if not np.any(pm):
        # Place plant: center at (plant_x, spine_y)
        return (Tool.COALPOWER, plant_x, spine_y)

    # --- Phase 2: Extend horizontal wire spine ---
    # Find rightmost wire in spine row
    wire_in_spine = [(c) for c in range(WORLD_W) if wm[spine_y, c]]
    if wire_in_spine:
        max_wire_x = max(wire_in_spine)
    else:
        # Start wire just right of plant
        max_wire_x = plant_x + 1  # plant occupies plant_x-1..plant_x+1

    if max_wire_x < spine_x_end:
        nx = max_wire_x + 1
        if 0 <= nx < WORLD_W:
            # Don't overwrite plant
            if not pm[spine_y, nx]:
                return (Tool.WIRE, nx, spine_y)

    # --- Phase 3: Build road spine top and bottom ---
    for road_y in [road_row_top, road_row_bot]:
        road_in_row = [c for c in range(WORLD_W) if rm[road_y, c]]
        if road_in_row:
            max_road_x = max(road_in_row)
        else:
            max_road_x = spine_x_start - 1
        if max_road_x < spine_x_end:
            nx = max_road_x + 1
            if 0 <= nx < WORLD_W and em[road_y, nx]:
                return (Tool.ROAD, nx, road_y)

    # --- Phase 4: Build vertical connector roads at zone columns ---
    for zc in zone_cols:
        if zc < 0 or zc >= WORLD_W:
            continue
        # Connect from road_row_top up to zone rows above
        for zr in zone_rows_above:
            # Wire branch from spine upward to zone row at this col
            if zr < 0 or zr >= WORLD_H:
                continue
            # Check if we need vertical wire from spine_y to zr at col zc
            for wr in range(spine_y - 1, zr - 1, -1):
                if wr < 0 or wr >= WORLD_H:
                    break
                if wm[wr, zc] or pm[wr, zc]:
                    break  # already wired here, done
                if em[wr, zc]:
                    return (Tool.WIRE, zc, wr)
                else:
                    break  # blocked

        for zr in zone_rows_below:
            if zr < 0 or zr >= WORLD_H:
                continue
            for wr in range(spine_y + 1, zr + 2):
                if wr < 0 or wr >= WORLD_H:
                    break
                if wm[wr, zc] or pm[wr, zc]:
                    break
                if em[wr, zc]:
                    return (Tool.WIRE, zc, wr)
                else:
                    break

    # --- Phase 5: Place zones near roads and wires ---
    all_zone_rows = zone_rows_above + zone_rows_below
    for zr in all_zone_rows:
        if zr < 3 or zr >= WORLD_H - 3:
            continue
        for zc in zone_cols:
            if zc < 3 or zc >= WORLD_W - 3:
                continue
            # Check road access: within 4 tiles
            road_near = False
            for dy in range(-4, 5):
                for dx in range(-4, 5):
                    ny2, nx2 = zr + dy, zc + dx
                    if 0 <= ny2 < WORLD_H and 0 <= nx2 < WORLD_W:
                        if rm[ny2, nx2]:
                            road_near = True
                            break
                if road_near:
                    break

            # Check wire/power access: within 6 tiles
            power_near = False
            for dy in range(-6, 7):
                for dx in range(-6, 7):
                    ny2, nx2 = zr + dy, zc + dx
                    if 0 <= ny2 < WORLD_H and 0 <= nx2 < WORLD_W:
                        if wm[ny2, nx2] or pm[ny2, nx2]:
                            power_near = True
                            break
                if power_near:
                    break

            if road_near and power_near and zone_area_free(zc, zr):
                return (pick_zone_type(), zc, zr)

    # --- Phase 6: If we have good population, add a second plant ---
    num_plants = int(np.sum(pm)) // 6  # rough count (plant is ~6x6 tiles... actually 3x3=9)
    plant_cells = int(np.sum(pm))
    if plant_cells < 18 and obs.city_pop > 50:
        # Place second plant at right side
        p2x = 95
        if zone_area_free(p2x, spine_y):
            return (Tool.COALPOWER, p2x, spine_y)

    # --- Phase 7: Extend wire to second plant if it exists ---
    if plant_cells >= 18:
        # Find all plant positions, extend wire from max_wire_x to second plant
        if max_wire_x < spine_x_end:
            nx = max_wire_x + 1
            if 0 <= nx < WORLD_W and em[spine_y, nx]:
                return (Tool.WIRE, nx, spine_y)

    # --- Phase 8: Add connector roads between road rows and spine ---
    for zc in zone_cols:
        if zc < 0 or zc >= WORLD_W:
            continue
        # Short vertical roads from road row to edge of zones
        for road_y in [road_row_top, road_row_bot]:
            if not rm[road_y, zc] and em[road_y, zc]:
                return (Tool.ROAD, zc, road_y)

    # --- Phase 9: Fill in more road coverage ---
    # Try to place roads between zone cols to ensure connectivity
    for road_y in [road_row_top, road_row_bot]:
        for cx in range(spine_x_start, spine_x_end + 1):
            if 0 <= cx < WORLD_W and em[road_y, cx]:
                return (Tool.ROAD, cx, road_y)

    return None

def act(obs, state):
    """
    Horizontal spine layout (vs parent's vertical spine).
    - Road runs horizontally across the map center
    - Wire runs horizontally just above the road
    - Zones placed above and below the road/wire spine
    - Multiple power plants connected via wire
    - Balanced R/C/I with more commercial emphasis
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def has_tile(mask, x, y):
        if 0 <= y < WORLD_H and 0 <= x < WORLD_W:
            return bool(mask[y, x])
        return False

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        all_zone = resm | comm | indm
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone[rr, rc]:
                    return False
        return True

    def zone_present(zr, zc):
        all_zone = resm | comm | indm
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone[rr, rc]:
                        return True
        return False

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        # More commercial emphasis than parent
        if com_count / t < 0.35:
            return Tool.COMMERCIAL
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Horizontal spine layout
    # wire_row: horizontal wire row
    # road_row: horizontal road row (just below wire)
    # zones above: top_zrow = wire_row - 3
    # zones below: bot_zrow = road_row + 3
    # plant at left side of wire row

    wire_row = cy - 1
    road_row = cy      # road just below wire
    top_zrow = wire_row - 3
    bot_zrow = road_row + 3

    # Clamp rows
    wire_row = max(2, min(WORLD_H - 3, wire_row))
    road_row = max(2, min(WORLD_H - 3, road_row))
    top_zrow = max(2, min(WORLD_H - 3, top_zrow))
    bot_zrow = max(2, min(WORLD_H - 3, bot_zrow))

    # Plant position: left side
    plant_x = 8
    plant_y = wire_row

    # Adaptive spine extent based on population
    if obs.city_pop < 50:
        spine_half = 10
    elif obs.city_pop < 200:
        spine_half = 18
    elif obs.city_pop < 500:
        spine_half = 30
    else:
        spine_half = 45

    spine_min = max(2, cx - spine_half)
    spine_max = min(WORLD_W - 3, cx + spine_half)
    spine_range = range(spine_min, spine_max + 1)

    # Phase 0: Place coal power plant
    if not np.any(pm):
        return (Tool.COALPOWER, plant_x, plant_y)

    # Phase 1: Wire spine horizontal row
    for dx in spine_range:
        if not has_tile(wm, dx, wire_row) and not has_tile(pm, dx, wire_row):
            if not has_tile(rm, dx, wire_row):
                return (Tool.WIRE, dx, wire_row)

    # Phase 2: Road row adjacent (below wire)
    for dx in spine_range:
        if not has_tile(rm, dx, road_row) and not has_tile(pm, dx, road_row):
            if not has_tile(wm, dx, road_row):
                return (Tool.ROAD, dx, road_row)

    # Collect wired cols and road cols
    wire_cols = [c for c in spine_range if wm[wire_row, c]]
    road_cols = [c for c in spine_range if rm[road_row, c]]

    # Phase 3: Place zones flanking wire+road spine (above and below)
    zone_cols = list(range(spine_min + 1, spine_max - 1, 4))

    for zc in zone_cols:
        wire_near = any(abs(zc - wc) <= 2 for wc in wire_cols)
        road_near = any(abs(zc - rc) <= 2 for rc in road_cols)

        if wire_near and road_near:
            # Top zone (above wire)
            zr = top_zrow
            if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                return (pick_tool(), zc, zr)

            # Bottom zone (below road)
            zr = bot_zrow
            if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                return (pick_tool(), zc, zr)

    # Phase 4: Vertical wires to connect top zones to horizontal wire
    for wc in wire_cols:
        # Connect wire up to top zone row
        for wr in range(wire_row - 1, top_zrow - 2, -1):
            if 0 <= wr < WORLD_H:
                if wm[wr, wc] or pm[wr, wc]:
                    break
                if em[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                else:
                    break

    # Phase 5: Vertical wires to connect bottom zones from road row
    for rc in road_cols:
        for wr in range(road_row + 1, bot_zrow + 2):
            if 0 <= wr < WORLD_H:
                if wm[wr, rc] or pm[wr, rc]:
                    break
                if em[wr, rc] and not rm[wr, rc]:
                    return (Tool.WIRE, rc, wr)
                elif rm[wr, rc]:
                    continue
                else:
                    break

    # Phase 6: Second coal plant if population growing
    if obs.city_pop > 200 and int(np.sum(pm)) < 9:
        px2 = WORLD_W - 10
        py2 = wire_row
        if 2 <= px2 <= WORLD_W - 3 and 2 <= py2 <= WORLD_H - 3:
            if em[py2, px2]:
                return (Tool.COALPOWER, px2, py2)

    # Phase 7: Second tier of zones (further from spine)
    if obs.city_pop > 100:
        top2_zrow = top_zrow - 4
        bot2_zrow = bot_zrow + 4
        top2_zrow = max(2, min(WORLD_H - 3, top2_zrow))
        bot2_zrow = max(2, min(WORLD_H - 3, bot2_zrow))

        for zc in zone_cols:
            wire_near = any(abs(zc - wc) <= 2 for wc in wire_cols)
            road_near = any(abs(zc - rc) <= 2 for rc in road_cols)
            if wire_near and road_near:
                for zr in [top2_zrow, bot2_zrow]:
                    if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                        r0 = max(0, zr - 5); r1 = min(WORLD_H, zr + 6)
                        c0 = max(0, zc - 5); c1 = min(WORLD_W, zc + 6)
                        if np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1]):
                            if np.any(rm[r0:r1, c0:c1]):
                                return (pick_tool(), zc, zr)

    # Phase 8: Vertical roads connecting zones above/below spine
    if obs.city_pop > 150:
        for vc in [spine_min + 1, spine_max - 1, cx]:
            if 0 <= vc < WORLD_W:
                for vr in range(top_zrow - 1, bot_zrow + 2):
                    if 0 <= vr < WORLD_H and em[vr, vc] and not pm[vr, vc]:
                        return (Tool.ROAD, vc, vr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map every step to decide next placement
    - Places coal plant, builds wire spine, road columns, then zones
    - Expands reactively based on what already exists
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    has_plant = np.any(pm)
    has_wire = np.any(wm)
    has_road = np.any(rm)

    # Fixed anchor positions
    cx, cy = 55, 50
    plant_cx, plant_cy = cx - 8, cy

    # Layout columns relative to plant
    wire_col = plant_cx + 3    # wire spine just right of plant
    road_col_r = wire_col + 1  # road right of wire
    road_col_l = wire_col - 1  # road left of wire
    zone_col_r = road_col_r + 3  # right zone column
    zone_col_l = road_col_l - 3  # left zone column

    # Phase 1: Place coal power plant
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Gather current state from map
    plant_pos = list(zip(*np.where(pm)))
    if plant_pos:
        plant_cy_actual, plant_cx_actual = plant_pos[0]
    else:
        plant_cy_actual, plant_cx_actual = plant_cy, plant_cx

    # Re-derive columns if plant moved
    wire_col = plant_cx_actual + 3
    road_col_r = wire_col + 1
    road_col_l = wire_col - 1
    zone_col_r = road_col_r + 3
    zone_col_l = road_col_l - 3

    wire_positions = set(zip(*np.where(wm))) if has_wire else set()
    road_positions = set(zip(*np.where(rm))) if has_road else set()
    res_positions = set(zip(*np.where(res_m)))
    com_positions = set(zip(*np.where(com_m)))
    ind_positions = set(zip(*np.where(ind_m)))
    all_zones = res_positions | com_positions | ind_positions

    res_count = len(res_positions)
    com_count = len(com_positions)
    ind_count = len(ind_positions)
    total_zones = res_count + com_count + ind_count

    # Vertical span: grow with population
    base_span = 12
    extra_span = min(30, obs.city_pop // 20)
    target_span = base_span + extra_span
    tmin = max(2, plant_cy_actual - target_span)
    tmax = min(WORLD_H - 3, plant_cy_actual + target_span)

    # Wire rows in main spine column
    wire_rows_in_col = sorted(r for (r, c) in wire_positions if c == wire_col)

    # Phase 2: Extend wire spine vertically
    if not wire_rows_in_col:
        # Place first wire adjacent to plant
        for dy in range(-2, 3):
            ny = plant_cy_actual + dy
            if 0 <= ny < WORLD_H and 0 <= wire_col < WORLD_W:
                if em[ny, wire_col]:
                    return (Tool.WIRE, wire_col, ny)
                else:
                    return (Tool.WIRE, wire_col, ny)  # auto-bulldoze handles it
    else:
        min_wr = min(wire_rows_in_col)
        max_wr = max(wire_rows_in_col)
        # Extend downward
        if max_wr < tmax:
            nr = max_wr + 1
            if 0 <= nr < WORLD_H:
                return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if min_wr > tmin:
            nr = min_wr - 1
            if 0 <= nr < WORLD_H:
                return (Tool.WIRE, wire_col, nr)

    wire_rows_set = set(wire_rows_in_col)
    road_rows_r = set(r for (r, c) in road_positions if c == road_col_r)
    road_rows_l = set(r for (r, c) in road_positions if c == road_col_l)

    # Phase 3: Build road columns parallel to wire spine
    if wire_rows_in_col:
        for wr in wire_rows_in_col:
            if wr not in road_rows_r and 0 <= road_col_r < WORLD_W:
                return (Tool.ROAD, road_col_r, wr)
        for wr in wire_rows_in_col:
            if wr not in road_rows_l and 0 <= road_col_l >= 0:
                return (Tool.ROAD, road_col_l, wr)

    # Helper: check if 3x3 area is entirely free
    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def already_zone_nearby(zr, zc):
        return any(abs(zr - pr) <= 1 and abs(zc - pc) <= 1 for (pr, pc) in all_zones)

    def choose_zone_type(zc):
        # ~50% res, ~25% com, ~25% ind
        if total_zones == 0:
            return Tool.RESIDENTIAL
        if ind_count * 4 < total_zones + 1:
            return Tool.INDUSTRIAL
        if com_count * 4 < total_zones + 1:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Phase 4: Place zones adjacent to road + wire
    for zr in sorted(wire_rows_in_col):
        wire_nearby = any(abs(zr - wr) <= 1 for wr in wire_rows_set)
        if not wire_nearby:
            continue

        road_nearby_r = any(abs(zr - rr) <= 2 for rr in road_rows_r)
        road_nearby_l = any(abs(zr - rr) <= 2 for rr in road_rows_l)

        # Right zone column
        if road_nearby_r:
            zc = zone_col_r
            if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                if not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                    return (choose_zone_type(zc), zc, zr)

        # Left zone column
        if road_nearby_l:
            zc = zone_col_l
            if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                if not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                    return (choose_zone_type(zc), zc, zr)

    # Phase 5: Lateral roads/wires to bridge from spine to zone columns
    for wr in wire_rows_in_col:
        # Lateral road to right zone col
        for rc in range(road_col_r + 1, zone_col_r):
            if 0 <= rc < WORLD_W and em[wr, rc]:
                return (Tool.ROAD, rc, wr)
        # Lateral wire to left zone col
        for wc in range(wire_col - 1, zone_col_l, -1):
            if 0 <= wc < WORLD_W and em[wr, wc]:
                return (Tool.WIRE, wc, wr)

    # Phase 6: Expand to a second cluster when population grows
    if obs.city_pop > 150:
        wire_col2 = zone_col_r + 4
        road_col2r = wire_col2 + 1
        zone_col2r = road_col2r + 3

        wire_rows2 = sorted(r for (r, c) in wire_positions if c == wire_col2)

        if not wire_rows2:
            # Horizontal wire bridge from main spine to second spine
            for wc in range(wire_col + 1, wire_col2 + 1):
                if 0 <= wc < WORLD_W and em[plant_cy_actual, wc]:
                    return (Tool.WIRE, wc, plant_cy_actual)
                elif 0 <= wc < WORLD_W:
                    return (Tool.WIRE, wc, plant_cy_actual)
        else:
            min_wr2 = min(wire_rows2)
            max_wr2 = max(wire_rows2)
            tmin2 = max(2, plant_cy_actual - target_span)
            tmax2 = min(WORLD_H - 3, plant_cy_actual + target_span)

            if max_wr2 < tmax2:
                nr = max_wr2 + 1
                if 0 <= nr < WORLD_H:
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > tmin2:
                nr = min_wr2 - 1
                if 0 <= nr < WORLD_H:
                    return (Tool.WIRE, wire_col2, nr)

            wire_rows2_set = set(wire_rows2)
            road_rows2r = set(r for (r, c) in road_positions if c == road_col2r)

            for wr in wire_rows2:
                if wr not in road_rows2r and 0 <= road_col2r < WORLD_W:
                    return (Tool.ROAD, road_col2r, wr)

            for zr in sorted(wire_rows2):
                wire_nearby2 = any(abs(zr - wr) <= 1 for wr in wire_rows2_set)
                road_nearby2 = any(abs(zr - rr) <= 2 for rr in road_rows2r)
                if wire_nearby2 and road_nearby2:
                    zc = zone_col2r
                    if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                        if not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                            return (choose_zone_type(zc), zc, zr)

            # Lateral roads to zone_col2r
            for wr in wire_rows2:
                for rc in range(road_col2r + 1, zone_col2r):
                    if 0 <= rc < WORLD_W and em[wr, rc]:
                        return (Tool.ROAD, rc, wr)

    # Phase 7: Second power plant when city is large
    if obs.city_pop > 400 and not state.get("second_plant", False):
        p2x, p2y = plant_cx_actual + 20, plant_cy_actual
        area_ok = True
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = p2y + dr, p2x + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if pm[rr, rc]:
                        area_ok = False
        if area_ok and 1 <= p2y < WORLD_H - 1 and 1 <= p2x < WORLD_W - 1:
            state["second_plant"] = True
            return (Tool.COALPOWER, p2x, p2y)

    # Phase 8: Fill any remaining gaps in wire/road spine
    if wire_rows_in_col:
        for wr in wire_rows_in_col:
            if wr not in road_rows_r and 0 <= road_col_r < WORLD_W:
                return (Tool.ROAD, road_col_r, wr)
            if wr not in road_rows_l and 0 <= road_col_l >= 0:
                return (Tool.ROAD, road_col_l, wr)

    return None

def act(obs, state):
    """
    Closed-loop city builder: reads tile_map every step and reacts.
    Combines best ideas from both parents:
    - Parent A: rich road grid, zone placement logic, services
    - Parent B: vertical wire spine, adjacent road column, left/right zones
    Strategy:
    1. Place coal plant near center-left
    2. Extend vertical wire spine from plant
    3. Build road column adjacent to wire
    4. Place zones on both sides of corridor
    5. Extend lateral wires to power zones
    6. Add services and second plant as population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    all_zone_mask = resm | comm | indm

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = float(total_zones)
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    # --- Phase 1: Place coal plant ---
    if not np.any(pm):
        return (Tool.COALPOWER, WORLD_W // 2 - 10, WORLD_H // 2)

    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Layout columns relative to plant
    wire_col = plant_cx + 2
    road_col = wire_col + 1
    left_zone_col = wire_col - 3
    right_zone_col = road_col + 3

    wire_col = max(2, min(WORLD_W - 3, wire_col))
    road_col = max(2, min(WORLD_W - 3, road_col))
    left_zone_col = max(2, min(WORLD_W - 3, left_zone_col))
    right_zone_col = max(2, min(WORLD_W - 3, right_zone_col))

    # Spine extent based on population
    if obs.city_pop < 100:
        spine_extent = 10
    elif obs.city_pop < 300:
        spine_extent = 16
    elif obs.city_pop < 600:
        spine_extent = 22
    else:
        spine_extent = 30

    cy = WORLD_H // 2
    target_min = max(1, cy - spine_extent)
    target_max = min(WORLD_H - 2, cy + spine_extent)

    wire_rows_on_spine = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])
    road_rows_on_col = sorted([r for r in range(WORLD_H) if rm[r, road_col]])

    # --- Phase 2: Start wire adjacent to plant if none on spine ---
    if not wire_rows_on_spine:
        for dy in range(0, 6):
            for nr in [plant_cy + dy, plant_cy - dy]:
                if 0 <= nr < WORLD_H:
                    if em[nr, wire_col] or wm[nr, wire_col]:
                        return (Tool.WIRE, wire_col, nr)
        return None

    min_wire_row = min(wire_rows_on_spine)
    max_wire_row = max(wire_rows_on_spine)

    # --- Phase 3: Extend wire spine downward ---
    if max_wire_row < target_max:
        nr = max_wire_row + 1
        if nr < WORLD_H and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # --- Phase 4: Extend wire spine upward ---
    if min_wire_row > target_min:
        nr = min_wire_row - 1
        if nr >= 0 and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # --- Phase 5: Build road column adjacent to wire spine ---
    for r in wire_rows_on_spine:
        if 0 <= r < WORLD_H and 0 <= road_col < WORLD_W:
            if not rm[r, road_col] and em[r, road_col] and not pm[r, road_col]:
                return (Tool.ROAD, road_col, r)

    # --- Phase 6: Lateral wires leftward from spine ---
    for wr in wire_rows_on_spine:
        for wc in range(wire_col - 1, left_zone_col - 2, -1):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc] or pm[wr, wc]:
                    break
                if em[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                else:
                    break

    # --- Phase 7: Place zones where wire AND road coverage exists ---
    zone_rows = list(range(max(1, target_min), min(WORLD_H - 1, target_max + 1), 3))

    for zr in zone_rows:
        wire_near = any(abs(zr - wr) <= 2 for wr in wire_rows_on_spine)
        road_near = any(abs(zr - rr) <= 2 for rr in road_rows_on_col)

        if wire_near and road_near:
            # Try left zone (powered by lateral wires from spine)
            zc = left_zone_col
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc, 5) and has_road_nearby(zr, zc, 5):
                    return (pick_tool(), zc, zr)

            # Try right zone (road side)
            zc = right_zone_col
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_road_nearby(zr, zc, 5) and has_wire_nearby(zr, zc, 5):
                    return (pick_tool(), zc, zr)

    # --- Phase 8: Road extensions to reach right zones ---
    for rr in wire_rows_on_spine:
        if not rm[rr, road_col]:
            continue
        for rc in range(road_col + 1, right_zone_col + 2):
            if 0 <= rc < WORLD_W:
                if rm[rr, rc]:
                    break
                if em[rr, rc] and not pm[rr, rc]:
                    return (Tool.ROAD, rc, rr)
                else:
                    break

    # --- Phase 9: Wire to right zone column ---
    for wr in wire_rows_on_spine:
        for wc in range(wire_col + 1, right_zone_col + 2):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc] or pm[wr, wc]:
                    break
                if em[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)

    # --- Phase 10: Second coal plant if population demands more power ---
    if obs.city_pop > 400 and np.sum(pm) < 9:
        px2, py2 = plant_cx + 20, plant_cy
        if 2 <= py2 <= WORLD_H - 3 and 2 <= px2 <= WORLD_W - 3:
            if em[py2, px2]:
                return (Tool.COALPOWER, px2, py2)

    # --- Phase 11: Services once population grows ---
    if obs.city_pop > 150:
        fx, fy = wire_col + 2, plant_cy - 12
        if in_bounds(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
        fx2, fy2 = wire_col + 2, plant_cy + 12
        if in_bounds(fx2, fy2) and em[fy2, fx2]:
            return (Tool.POLICESTATION, fx2, fy2)

    # --- Phase 12: Expand extra zone columns as city grows ---
    if obs.city_pop > 200:
        extra_cols = [left_zone_col - 4, right_zone_col + 4]
        for zc in extra_cols:
            if 2 <= zc <= WORLD_W - 3:
                for zr in zone_rows:
                    if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                        if has_road_nearby(zr, zc, 6) and has_wire_nearby(zr, zc, 7):
                            return (Tool.RESIDENTIAL, zc, zr)

    # --- Phase 13: Horizontal roads connecting corridor to extra zones ---
    if obs.city_pop > 100 and wire_rows_on_spine:
        h_rows = [min_wire_row, max_wire_row]
        for rr in h_rows:
            if 0 <= rr < WORLD_H:
                for rc in range(left_zone_col - 1, right_zone_col + 3):
                    if 0 <= rc < WORLD_W and em[rr, rc] and not pm[rr, rc]:
                        return (Tool.ROAD, rc, rr)

    # --- Phase 14: Reactive fill - scan for empty spots near road+wire ---
    # Build dilated road and wire neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = sr0 + dy; r1 = sr1 + dy
            c0 = sc0 + dx; c1 = sc1 + dx
            if sr1 > sr0 and sc1 > sc0:
                nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = sr0 + dy; r1 = sr1 + dy
            c0 = sc0 + dx; c1 = sc1 + dx
            if sr1 > sr0 and sc1 > sc0:
                nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
                nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand = em & nbr_road & nbr_wire
    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        # Use step-based index for variety
        k = int((obs.step * 13 + 7)) % len(cxs)
        zx, zy = int(cxs[k]), int(cys[k])
        if zone_area_ok(zy, zx) and not zone_already_there(zy, zx):
            return (pick_tool(), zx, zy)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map each step and places next tile
    based on current state of the map. Uses a phase system but decisions
    are reactive to what's actually on the map.
    """
    tm = obs.tile_map
    emp = empty_mask(tm)
    road = road_mask(tm)
    wire = wire_mask(tm)
    plant = plant_mask(tm)
    res = res_mask(tm)
    com = com_mask(tm)
    ind = ind_mask(tm)

    step = obs.step

    # Helper: find empty tile adjacent to mask
    def adjacent_empty(mask):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
            shifted = np.roll(mask, (dy, dx), axis=(0,1))
            # Zero out wrapped edges
            if dy > 0: shifted[:dy, :] = False
            elif dy < 0: shifted[dy:, :] = False
            if dx > 0: shifted[:, :dx] = False
            elif dx < 0: shifted[:, dx:] = False
            result |= shifted
        return result & emp

    # Helper: find empty tile near mask (within 2)
    def nearby_empty(mask, dist=2):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-dist, dist+1):
            for dx in range(-dist, dist+1):
                if dy == 0 and dx == 0: continue
                shifted = np.roll(mask, (dy, dx), axis=(0,1))
                if dy > 0: shifted[:dy, :] = False
                elif dy < 0: shifted[dy:, :] = False
                if dx > 0: shifted[:, :dx] = False
                elif dx < 0: shifted[:, dx:] = False
                result |= shifted
        return result & emp

    # Phase 1: Place coal power plant if none exists
    plant_tiles = np.where(plant)
    if len(plant_tiles[0]) == 0:
        # Place coal plant at (30, 50)
        return (Tool.COALPOWER, 30, 50)

    # Phase 2: Ensure we have a second plant if population is large enough
    if obs.city_pop > 500 and len(plant_tiles[0]) < 2:
        # Check if nuclear plant area is clear
        nx2, ny2 = 85, 50
        if emp[ny2, nx2]:
            return (Tool.NUCLEARPOWER, nx2, ny2)

    # Get plant positions
    py, px = plant_tiles[0][0], plant_tiles[1][0]

    # Phase 3: Extend wire from plant if wire coverage is thin
    wire_tiles = np.where(wire)
    n_wire = len(wire_tiles[0])

    # Check if plant is isolated (no wire adjacent)
    plant_mask_arr = plant(tm) if callable(plant) else plant
    adj_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        ny2 = np.clip(py + dy, 0, WORLD_H-1)
        nx2 = np.clip(px + dx, 0, WORLD_W-1)
        if wire[ny2, nx2] or road[ny2, nx2]:
            pass  # plant has road/wire neighbor

    # Build wire spine vertically from plant if needed
    # Check how many wire tiles are near plant
    plant_region_wire = wire[max(0,py-15):min(WORLD_H,py+15), 
                              max(0,px-5):min(WORLD_W,px+5)]

    if n_wire < 25:
        # Lay wire along vertical spine from plant
        # Find the next missing wire position in the spine
        spine_x = px
        for dy in range(-12, 13):
            wy = py + dy
            if 0 <= wy < WORLD_H and 0 <= spine_x < WORLD_W:
                if not wire[wy, spine_x] and not plant[wy, spine_x]:
                    return (Tool.WIRE, spine_x, wy)
        # If spine is full, extend horizontally
        for dx in range(1, 10):
            wx = px + dx
            if 0 <= wx < WORLD_W:
                if not wire[py, wx] and not plant[py, wx]:
                    return (Tool.WIRE, wx, py)

    # Phase 4: Build road network adjacent to wires
    n_road = int(road.sum())

    if n_road < 30:
        # Build vertical road parallel to wire spine (one column right of plant)
        road_x = px + 1
        if road_x >= WORLD_W:
            road_x = px - 1
        for dy in range(-12, 13):
            ry = py + dy
            if 0 <= ry < WORLD_H and 0 <= road_x < WORLD_W:
                if not road[ry, road_x] and not plant[ry, road_x]:
                    return (Tool.ROAD, road_x, ry)
        # Also left side
        road_x2 = px - 1
        if road_x2 >= 0:
            for dy in range(-12, 13):
                ry = py + dy
                if 0 <= ry < WORLD_H:
                    if not road[ry, road_x2] and not plant[ry, road_x2]:
                        return (Tool.ROAD, road_x2, ry)

    # Phase 5: Reactive zone placement
    # Compute which empty tiles are:
    # (a) adjacent to road
    # (b) adjacent to wire (for power)
    near_road = adjacent_empty(road)
    near_wire = nearby_empty(wire, dist=4) | adjacent_empty(wire)

    any_zone = res | com | ind
    near_zone = nearby_empty(any_zone, dist=3)

    # Count zones
    n_res = int(res.sum())
    n_com = int(com.sum())
    n_ind = int(ind.sum())
    n_zones = n_res + n_com + n_ind

    # Good spots: near road AND near wire
    good_spots = near_road & near_wire

    if good_spots.any():
        ys, xs = np.where(good_spots)
        # Pick spot closest to plant for compactness
        dists = np.abs(ys - py) + np.abs(xs - px)
        # Add some variety based on step
        sorted_idx = np.argsort(dists)
        idx = sorted_idx[step % max(1, min(5, len(sorted_idx)))]
        x, y = int(xs[idx]), int(ys[idx])

        # Determine zone type based on current balance
        if n_res == 0 or (n_com + n_ind) > n_res * 2:
            return (Tool.RESIDENTIAL, x, y)
        elif n_com < n_res * 0.4:
            return (Tool.COMMERCIAL, x, y)
        elif n_ind < n_res * 0.3:
            return (Tool.INDUSTRIAL, x, y)
        else:
            # Mix based on step
            r = step % 10
            if r < 5:
                return (Tool.RESIDENTIAL, x, y)
            elif r < 8:
                return (Tool.COMMERCIAL, x, y)
            else:
                return (Tool.INDUSTRIAL, x, y)

    # Phase 6: Extend roads toward empty areas
    # Find frontier: road tiles with empty neighbors
    road_frontier = adjacent_empty(road)
    if road_frontier.any():
        ys, xs = np.where(road_frontier)
        # Extend road outward from plant
        dists = np.abs(ys - py) + np.abs(xs - px)
        # Pick a tile at medium distance to expand outward
        sorted_idx = np.argsort(dists)
        # Pick the farthest of the nearest cluster
        pick = min(len(sorted_idx)-1, max(0, len(sorted_idx)//3))
        idx = sorted_idx[pick]
        x, y = int(xs[idx]), int(ys[idx])
        return (Tool.ROAD, x, y)

    # Phase 7: Extend wire to cover more zones
    wire_frontier = adjacent_empty(wire)
    # Prefer extending toward zones without power
    if wire_frontier.any():
        ys, xs = np.where(wire_frontier)
        # Extend toward unpowered zones or just outward
        dists = np.abs(ys - py) + np.abs(xs - px)
        idx = np.argmin(dists + np.random.RandomState(step).randint(0, 3, len(dists)))
        x, y = int(xs[idx]), int(ys[idx])
        return (Tool.WIRE, x, y)

    # Fallback: place residential near any road
    near_road2 = adjacent_empty(road)
    if near_road2.any():
        ys, xs = np.where(near_road2)
        k = step % len(xs)
        return (Tool.RESIDENTIAL, int(xs[k]), int(ys[k]))

    return None

def act(obs, state):
    """
    Closed-loop policy: each step reads the map and decides what to place next.
    Combines Parent A's grid expansion with Parent B's vertical spine approach.

    Strategy:
    1. Place coal power plant if none exists
    2. Extend wire spine outward (horizontal + vertical) from plant
    3. Build roads adjacent to wire
    4. Place zones where both road and wire access exist
    5. React to actual map state each step
    """
    tm = obs.tile_map

    # Read current map state
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    has_plant = np.any(pm)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # City center
    CX, CY = 60, 50

    # Phase 1: Place coal power plant if none exists
    if not has_plant:
        px, py = CX - 8, CY
        return (Tool.COALPOWER, px, py)

    # Get plant position info
    plant_positions = list(zip(*np.where(pm)))
    # Find plant center area (approximate from plant tiles)
    plant_rows = [r for r, c in plant_positions]
    plant_cols = [c for r, c in plant_positions]
    p_center_r = int(np.median(plant_rows)) if plant_rows else CY
    p_center_c = int(np.median(plant_cols)) if plant_cols else CX - 8

    wire_positions = set(zip(*np.where(wm))) if np.any(wm) else set()
    road_positions = set(zip(*np.where(rm))) if np.any(rm) else set()

    # Plant right edge
    plant_right_c = max(plant_cols) + 1 if plant_cols else p_center_c + 2

    # Phase 2: Build wire spine - horizontal from plant then vertical branches
    # Horizontal spine along plant row, from plant rightward
    spine_row = p_center_r
    spine_target_c = min(CX + 30, WORLD_W - 3)

    # Find rightmost wire on spine row
    spine_wire_cols = sorted([c for (r, c) in wire_positions if r == spine_row])

    if not spine_wire_cols:
        # Start wire just to the right of plant
        wc = plant_right_c
        if 0 <= wc < WORLD_W and not pm[spine_row, wc]:
            return (Tool.WIRE, wc, spine_row)
    else:
        max_spine_c = max(spine_wire_cols)
        if max_spine_c < spine_target_c:
            nc = max_spine_c + 1
            if 0 <= nc < WORLD_W and not pm[spine_row, nc]:
                if em[spine_row, nc] or wm[spine_row, nc]:
                    return (Tool.WIRE, nc, spine_row)

    # Phase 3: Vertical wire branches every 6 cols from spine
    branch_interval = 6
    vert_extent = 15  # rows up/down from spine

    if spine_wire_cols:
        spine_min_c = min(spine_wire_cols)
        spine_max_c = max(spine_wire_cols)

        for bc in range(spine_min_c, spine_max_c + 1, branch_interval):
            if (spine_row, bc) not in wire_positions:
                continue
            # Extend upward
            for wr in range(spine_row - 1, max(spine_row - vert_extent - 1, 1), -1):
                if (wr, bc) in wire_positions:
                    break
                if not pm[wr, bc] and (em[wr, bc]):
                    return (Tool.WIRE, bc, wr)
                elif not em[wr, bc] and not wm[wr, bc]:
                    break
            # Extend downward
            for wr in range(spine_row + 1, min(spine_row + vert_extent + 1, WORLD_H - 1)):
                if (wr, bc) in wire_positions:
                    break
                if not pm[wr, bc] and (em[wr, bc]):
                    return (Tool.WIRE, bc, wr)
                elif not em[wr, bc] and not wm[wr, bc]:
                    break

    # Phase 4: Build roads parallel to spine (one row above and below)
    road_above = spine_row - 3
    road_below = spine_row + 3

    road_col_start = plant_right_c + 1
    road_col_end = min(spine_target_c + 2, WORLD_W - 2)

    for rrow in [road_above, road_below]:
        if 1 <= rrow <= WORLD_H - 2:
            # Find rightmost road on this row
            row_road_cols = sorted([c for (r, c) in road_positions if r == rrow])
            max_rc = max(row_road_cols) if row_road_cols else road_col_start - 1
            if max_rc < road_col_end:
                nc = max_rc + 1
                if 0 <= nc < WORLD_W and not pm[rrow, nc] and em[rrow, nc]:
                    return (Tool.ROAD, nc, rrow)

    # Vertical connecting roads every 6 cols
    for vc in range(road_col_start, road_col_end + 1, branch_interval):
        if 0 <= vc < WORLD_W:
            for vr in range(road_above, road_below + 1):
                if 0 <= vr < WORLD_H:
                    if (vr, vc) not in road_positions and not pm[vr, vc] and em[vr, vc]:
                        return (Tool.ROAD, vc, vr)

    # Phase 5: Place zones where road AND wire access exists
    def has_road_nearby(zy, zx, r=3):
        for dr in range(-r, r+1):
            for dc in range(-r, r+1):
                rr, rc = zy+dr, zx+dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if (rr, rc) in road_positions:
                        return True
        return False

    def has_power_nearby(zy, zx, r=5):
        for dr in range(-r, r+1):
            for dc in range(-r, r+1):
                rr, rc = zy+dr, zx+dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if (rr, rc) in wire_positions or pm[rr, rc]:
                        return True
        return False

    def zone_clear(zy, zx):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zy+dr, zx+dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones + 1
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Zone placement rows: above and below roads
    zone_rows = [
        road_above - 2, road_above - 5, road_above - 8,
        road_below + 2, road_below + 5, road_below + 8,
    ]
    zone_cols = list(range(road_col_start + 2, road_col_end, branch_interval))

    all_zones = set(zip(*np.where(resm | comm | indm))) if np.any(resm | comm | indm) else set()

    for zr in zone_rows:
        for zc in zone_cols:
            if 2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3:
                # Check no existing zone too close
                too_close = any(abs(zr-er) < 3 and abs(zc-ec) < 3 for (er, ec) in all_zones)
                if not too_close and zone_clear(zr, zc):
                    if has_road_nearby(zr, zc) and has_power_nearby(zr, zc):
                        return (pick_tool(), zc, zr)

    # Phase 6: If zones exist but unpowered, extend wire laterally toward zones
    if np.any(resm | comm | indm):
        zone_list = list(all_zones)
        for (zr, zc) in zone_list[:15]:
            if not has_power_nearby(zr, zc, r=4):
                # Find nearest wire and step toward zone
                if wire_positions:
                    nearest = min(wire_positions, key=lambda p: abs(p[0]-zr)+abs(p[1]-zc))
                    wr, wc = nearest
                    nr = wr + (1 if zr > wr else -1 if zr < wr else 0)
                    nc = wc + (1 if zc > wc else -1 if zc < wc else 0)
                    if 0 <= nr < WORLD_H and 0 <= nc < WORLD_W and em[nr, nc] and not pm[nr, nc]:
                        return (Tool.WIRE, nc, nr)

    # Phase 7: Add second power plant if population growing
    if obs.city_pop > 300:
        plant_count = len(set((r//3, c//3) for r, c in plant_positions))
        if plant_count < 2:
            px2, py2 = CX + 20, CY
            if 0 <= py2 < WORLD_H and 0 <= px2 < WORLD_W and em[py2, px2]:
                return (Tool.COALPOWER, px2, py2)

    # Phase 8: Extend road and zone coverage further
    if obs.city_pop > 100:
        extra_zone_rows = [road_above - 11, road_below + 11]
        for zr in extra_zone_rows:
            for zc in zone_cols:
                if 2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3:
                    too_close = any(abs(zr-er) < 3 and abs(zc-ec) < 3 for (er, ec) in all_zones)
                    if not too_close and zone_clear(zr, zc):
                        if has_road_nearby(zr, zc, r=5) and has_power_nearby(zr, zc, r=7):
                            return (pick_tool(), zc, zr)

    # Fill gaps in roads
    for rrow in [road_above, road_below]:
        if 1 <= rrow <= WORLD_H - 2:
            for rc in range(road_col_start, road_col_end + 1):
                if 0 <= rc < WORLD_W and (rrow, rc) not in road_positions and not pm[rrow, rc] and em[rrow, rc]:
                    return (Tool.ROAD, rc, rrow)

    return None

def act(obs, state):
    """
    Improved policy: builds TWO neighborhoods side by side,
    one to the left and one to the right of a central power+wire spine.
    Uses a horizontal wire bus to connect both neighborhoods.
    Better zone mix: ~40% RES, ~30% COM, ~30% IND.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    cx, cy = 60, 50  # map center

    has_plant = np.any(pm)

    # Phase 1: place coal power plant slightly left of center
    plant_cx, plant_cy = cx - 5, cy
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    wire_positions = set(zip(*np.where(wm))) if np.any(wm) else set()
    road_positions = set(zip(*np.where(rm))) if np.any(rm) else set()
    res_positions = set(zip(*np.where(res_mask(tm))))
    com_positions = set(zip(*np.where(com_mask(tm))))
    ind_positions = set(zip(*np.where(ind_mask(tm))))

    res_count = len(res_positions)
    com_count = len(com_positions)
    ind_count = len(ind_positions)
    all_zones = res_positions | com_positions | ind_positions

    # Central wire spine column
    wire_col = plant_cx + 3   # 58
    # Two road columns, one on each side
    left_road_col = wire_col - 4   # 54
    right_road_col = wire_col + 4  # 62

    # Zone columns
    left_zone_col = left_road_col - 3   # 51
    right_zone_col = right_road_col + 3  # 65

    # Vertical span based on population
    base_span = 10
    extra_span = min(25, obs.city_pop // 40)
    target_span = base_span + extra_span

    tmin = max(2, cy - target_span)
    tmax = min(WORLD_H - 3, cy + target_span)

    wire_rows_in_col = sorted(r for (r, c) in wire_positions if c == wire_col)

    # Phase 2: extend wire spine vertically
    if not wire_rows_in_col:
        if em[plant_cy, wire_col]:
            return (Tool.WIRE, wire_col, plant_cy)
        else:
            return (Tool.WIRE, wire_col, plant_cy - 1)
    else:
        min_wr = min(wire_rows_in_col)
        max_wr = max(wire_rows_in_col)

        if max_wr < tmax:
            nr = max_wr + 1
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        if min_wr > tmin:
            nr = min_wr - 1
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    wire_rows_set = set(wire_rows_in_col)
    zone_rows = sorted(wire_rows_in_col)

    # Phase 3: build LEFT road column
    if wire_rows_in_col:
        left_road_rows = set(r for (r, c) in road_positions if c == left_road_col)
        for wr in wire_rows_in_col:
            if wr not in left_road_rows and 0 <= left_road_col < WORLD_W:
                if em[wr, left_road_col]:
                    return (Tool.ROAD, left_road_col, wr)

    # Phase 4: build RIGHT road column
    if wire_rows_in_col:
        right_road_rows = set(r for (r, c) in road_positions if c == right_road_col)
        for wr in wire_rows_in_col:
            if wr not in right_road_rows and 0 <= right_road_col < WORLD_W:
                if em[wr, right_road_col]:
                    return (Tool.ROAD, right_road_col, wr)

    # Helper: check 3x3 area free
    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def already_zone_nearby(zr, zc):
        return any(abs(zr - pr) <= 1 and abs(zc - pc) <= 1 for (pr, pc) in all_zones)

    left_road_rows_set = set(r for (r, c) in road_positions if c == left_road_col)
    right_road_rows_set = set(r for (r, c) in road_positions if c == right_road_col)

    # Phase 5: place zones on both sides
    for zr in zone_rows:
        left_road_ok = any(abs(zr - rr) <= 2 for rr in left_road_rows_set)
        right_road_ok = any(abs(zr - rr) <= 2 for rr in right_road_rows_set)

        for (zc, road_ok) in [(left_zone_col, left_road_ok), (right_zone_col, right_road_ok)]:
            if not road_ok:
                continue
            if 1 <= zr < WORLD_H-1 and 1 <= zc < WORLD_W-1:
                if not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                    # Zone type: aim ~40% RES, ~30% COM, ~30% IND
                    total = res_count + com_count + ind_count + 1
                    if res_count / total < 0.40:
                        return (Tool.RESIDENTIAL, zc, zr)
                    elif com_count / total < 0.30:
                        return (Tool.COMMERCIAL, zc, zr)
                    elif ind_count / total < 0.30:
                        return (Tool.INDUSTRIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

    # Phase 6: lateral wires from spine to left road col (to power left zones)
    for wr in wire_rows_in_col:
        for wc in range(wire_col - 1, left_road_col, -1):
            if 0 <= wc < WORLD_W and em[wr, wc]:
                return (Tool.WIRE, wc, wr)

    # Phase 7: lateral wires from spine to right road col (to power right zones)
    for wr in wire_rows_in_col:
        for wc in range(wire_col + 1, right_road_col):
            if 0 <= wc < WORLD_W and em[wr, wc]:
                return (Tool.WIRE, wc, wr)

    # Phase 8: if population growing well, add a third neighborhood far right
    if obs.city_pop > 400:
        far_right_road = right_road_col + 8  # 70
        far_right_zone = far_right_road + 3  # 73
        far_right_road_rows = set(r for (r, c) in road_positions if c == far_right_road)

        # Wire to far right road col first
        for wr in wire_rows_in_col:
            for wc in range(right_road_col + 1, far_right_road):
                if em[wr, wc]:
                    return (Tool.WIRE, wc, wr)

        for wr in wire_rows_in_col:
            if wr not in far_right_road_rows and 0 <= far_right_road < WORLD_W:
                if em[wr, far_right_road]:
                    return (Tool.ROAD, far_right_road, wr)

        far_right_road_rows_set = set(r for (r, c) in road_positions if c == far_right_road)
        for zr in zone_rows:
            road_ok = any(abs(zr - rr) <= 2 for rr in far_right_road_rows_set)
            if not road_ok:
                continue
            zc = far_right_zone
            if 1 <= zr < WORLD_H-1 and 1 <= zc < WORLD_W-1:
                if not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                    total = res_count + com_count + ind_count + 1
                    if com_count / total < 0.35:
                        return (Tool.COMMERCIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

    return None

def act(obs, state):
    """
    New policy: Single compact cluster centered at (60, 50)
    - Coal power plant at (60, 50) center
    - Cross-shaped road network radiating outward
    - Wires along roads to carry power
    - Dense zone placement around roads
    - Mix: 40% res, 30% com, 30% ind
    """
    tm = obs.tile_map
    step = obs.step

    # Initialize state
    if 'plan' not in state:
        state['plan'] = []
        state['plan_idx'] = 0

        # Central power plant position
        px, py = 60, 50

        actions = []

        # 1. Place coal power plant at center
        actions.append((Tool.COALPOWER, px, py))

        # 2. Build road grid: horizontal roads at py-4, py+4, py-8, py+8
        #    vertical roads at px-6, px+6, px-12, px+12
        # Main horizontal spine at py (shifted to avoid plant: py-4 and py+4)

        road_rows = [py - 4, py + 4, py - 8, py + 8, py - 12, py + 12]
        road_cols_range = list(range(px - 20, px + 22, 1))

        for row in road_rows:
            if 0 <= row < WORLD_H:
                for col in road_cols_range:
                    if 0 <= col < WORLD_W:
                        actions.append((Tool.ROAD, col, row))

        vert_cols = [px - 6, px + 6, px - 12, px + 12, px - 18, px + 18]
        road_rows_range = list(range(py - 12, py + 14, 1))

        for col in vert_cols:
            if 0 <= col < WORLD_W:
                for row in road_rows_range:
                    if 0 <= row < WORLD_H:
                        actions.append((Tool.ROAD, col, row))

        # 3. Wire from power plant outward along roads (rows and cols)
        # Wire along py-4 and py+4 rows
        for row in [py - 4, py + 4]:
            if 0 <= row < WORLD_H:
                for col in range(px - 20, px + 22):
                    if 0 <= col < WORLD_W:
                        actions.append((Tool.WIRE, col, row))

        # Wire along vertical cols
        for col in vert_cols:
            if 0 <= col < WORLD_W:
                for row in range(py - 12, py + 14):
                    if 0 <= row < WORLD_H:
                        actions.append((Tool.WIRE, col, row))

        # 4. Place zones in grid pattern
        # Zone centers spaced 6 apart, between roads
        zone_positions = []
        # Between horizontal roads and around them
        for zr in [py - 6, py - 10, py - 14, py + 6, py + 10, py + 14]:
            for zc in range(px - 18, px + 20, 6):
                zone_positions.append((zc, zr))

        # Assign types: cycle through R, R, C, R, R, I
        zone_types = [Tool.RESIDENTIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL,
                      Tool.RESIDENTIAL, Tool.RESIDENTIAL, Tool.INDUSTRIAL]

        for i, (zc, zr) in enumerate(zone_positions):
            if 3 <= zc <= WORLD_W - 4 and 3 <= zr <= WORLD_H - 4:
                t = zone_types[i % len(zone_types)]
                actions.append((t, zc, zr))

        # 5. Add second coal plant for more power coverage
        actions.append((Tool.COALPOWER, px - 18, py))
        actions.append((Tool.COALPOWER, px + 18, py))

        # 6. Wire connections from side plants to main grid
        for col in range(px - 18, px + 19):
            if 0 <= col < WORLD_W:
                actions.append((Tool.WIRE, col, py - 4))
                actions.append((Tool.WIRE, col, py + 4))

        # 7. More zones further out if steps allow
        for zr in [py - 18, py + 18]:
            for zc in range(px - 18, px + 20, 6):
                if 3 <= zc <= WORLD_W - 4 and 3 <= zr <= WORLD_H - 4:
                    t = zone_types[(zc // 6) % len(zone_types)]
                    actions.append((t, zc, zr))
                    actions.append((Tool.ROAD, zc, zr - 1))
                    actions.append((Tool.ROAD, zc, zr + 1))
                    actions.append((Tool.WIRE, zc, zr - 1))
                    actions.append((Tool.WIRE, zc, zr + 1))

        state['plan'] = actions
        state['plan_idx'] = 0

    idx = state['plan_idx']
    if idx < len(state['plan']):
        state['plan_idx'] += 1
        return state['plan'][idx]

    # After plan exhausted: scan for unpowered/unroaded zones and fix
    em = empty_mask(tm)
    rm = road_mask(tm)
    wm = wire_mask(tm)

    # Try to add more zones in empty areas near existing roads
    res_pos = list(zip(*np.where(res_mask(tm)))) if np.any(res_mask(tm)) else []
    com_pos = list(zip(*np.where(com_mask(tm)))) if np.any(com_mask(tm)) else []
    ind_pos = list(zip(*np.where(ind_mask(tm)))) if np.any(ind_mask(tm)) else []
    all_zones = res_pos + com_pos + ind_pos

    res_count = len(res_pos)
    com_count = len(com_pos)
    ind_count = len(ind_pos)
    total = res_count + com_count + ind_count + 1

    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def pick_type():
        if com_count / total < 0.30:
            return Tool.COMMERCIAL
        elif ind_count / total < 0.30:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Find empty 3x3 spots near roads
    for zr in range(3, WORLD_H - 3, 3):
        for zc in range(3, WORLD_W - 3, 3):
            if zone_area_free(zr, zc):
                # Check road nearby
                road_near = False
                wire_near = False
                for dr in range(-3, 4):
                    for dc in range(-3, 4):
                        nr, nc = zr + dr, zc + dc
                        if 0 <= nr < WORLD_H and 0 <= nc < WORLD_W:
                            if rm[nr, nc]:
                                road_near = True
                            if wm[nr, nc]:
                                wire_near = True
                if road_near and wire_near:
                    return (pick_type(), zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy v2.
    Key changes from parent:
    - Detect plant position dynamically from map each step.
    - Build wire spine from plant outward reactively.
    - Place zones more aggressively on both sides, with lateral wire/road connections.
    - Use a second wire spine column for denser coverage.
    - React to powered_zones count to decide when to expand vs consolidate.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    has_plant = np.any(pm)

    # Fixed plant location (center-left area)
    plant_cx, plant_cy = 54, 50

    # Phase 1: place coal plant if none exists
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Find actual plant tile positions to anchor wire
    plant_rows, plant_cols = np.where(pm)
    if len(plant_rows) == 0:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Use centroid of plant tiles as anchor
    pc_r = int(np.mean(plant_rows))
    pc_c = int(np.mean(plant_cols))

    # Wire spine column: just right of plant
    wire_col = pc_c + 3
    road_col = wire_col + 2  # road column with gap for zone placement

    wire_rows_in_col = sorted(int(r) for r in np.where(wm[:, wire_col])[0]) if wire_col < WORLD_W else []
    road_rows_in_col = sorted(int(r) for r in np.where(rm[:, road_col])[0]) if road_col < WORLD_W else []

    # Dynamic span based on population
    base_span = 10
    extra_span = min(25, obs.city_pop // 30)
    target_span = base_span + extra_span
    tmin = max(2, pc_r - target_span)
    tmax = min(WORLD_H - 3, pc_r + target_span)

    # Phase 2: build wire spine vertically
    if not wire_rows_in_col:
        # Start wire adjacent to plant
        for dy in [0, 1, -1, 2, -2]:
            wr = pc_r + dy
            if 0 <= wr < WORLD_H and 0 <= wire_col < WORLD_W:
                if em[wr, wire_col]:
                    return (Tool.WIRE, wire_col, wr)
    else:
        min_wr = min(wire_rows_in_col)
        max_wr = max(wire_rows_in_col)
        # Extend downward
        if max_wr < tmax:
            nr = max_wr + 1
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if min_wr > tmin:
            nr = min_wr - 1
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    wire_rows_set = set(wire_rows_in_col)
    road_rows_set = set(road_rows_in_col)

    # Phase 3: build road column
    if wire_rows_in_col:
        for wr in wire_rows_in_col:
            if wr not in road_rows_set and 0 <= road_col < WORLD_W:
                if em[wr, road_col]:
                    return (Tool.ROAD, road_col, wr)

    # Zone placement helpers
    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    all_zones = set(zip(*np.where(res_m | com_m | ind_m))) if np.any(res_m | com_m | ind_m) else set()

    def zone_nearby(zr, zc):
        return any(abs(zr - pr) <= 2 and abs(zc - pc) <= 2 for (pr, pc) in all_zones)

    res_count = int(np.sum(res_m)) // 9 + 1
    com_count = int(np.sum(com_m)) // 9 + 1
    ind_count = int(np.sum(ind_m)) // 9 + 1

    def pick_zone_type(zc, zr):
        # Balance: ~50% res, ~25% com, ~25% ind
        if ind_count * 2 < res_count:
            return Tool.INDUSTRIAL
        elif com_count * 2 < res_count:
            return Tool.COMMERCIAL
        else:
            return Tool.RESIDENTIAL

    # Zone columns: left of wire and right of road
    left_zone_col = wire_col - 3
    right_zone_col = road_col + 3

    zone_rows = sorted(wire_rows_in_col)

    # Phase 4: place zones
    for zr in zone_rows:
        road_nearby = any(abs(zr - rr) <= 2 for rr in road_rows_set)
        wire_nearby = any(abs(zr - wr) <= 1 for wr in wire_rows_set)
        if not (road_nearby and wire_nearby):
            continue

        for zc in [left_zone_col, right_zone_col]:
            if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                if not zone_nearby(zr, zc) and zone_area_free(zr, zc):
                    return (pick_zone_type(zc, zr), zc, zr)

    # Phase 5: lateral wires to left zones
    for wr in zone_rows:
        for wc in range(wire_col - 1, left_zone_col + 1, -1):
            if 0 <= wc < WORLD_W and em[wr, wc]:
