                return (Tool.ROAD, rc, wr)

    # Phase 7: second expansion column if pop growing
    if obs.city_pop > 200:
        wire_col2 = road_col + 7
        road_col2 = wire_col2 + 2
        right_zone_col2 = road_col2 + 3

        wire_rows2 = sorted(int(r) for r in np.where(wm[:, wire_col2])[0]) if wire_col2 < WORLD_W else []
        road_rows2 = set(int(r) for r in np.where(rm[:, road_col2])[0]) if road_col2 < WORLD_W else set()

        # Connect wire_col2 to wire_col via horizontal wires at pc_r
        for wc in range(wire_col + 1, wire_col2):
            if 0 <= wc < WORLD_W and em[pc_r, wc]:
                return (Tool.WIRE, wc, pc_r)

        # Extend wire_col2 vertically
        if not wire_rows2:
            if 0 <= wire_col2 < WORLD_W and em[pc_r, wire_col2]:
                return (Tool.WIRE, wire_col2, pc_r)
        else:
            min_wr2 = min(wire_rows2)
            max_wr2 = max(wire_rows2)
            if max_wr2 < tmax:
                nr = max_wr2 + 1
                if 0 <= nr < WORLD_H and 0 <= wire_col2 < WORLD_W and em[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > tmin:
                nr = min_wr2 - 1
