        if not wire_rows_left:
            if 0 <= wire_col_left < WORLD_W and em[pc_r, wire_col_left]:
                return (Tool.WIRE, wire_col_left, pc_r)
        else:
            min_wl = min(wire_rows_left)
            max_wl = max(wire_rows_left)
            if max_wl < tmax:
                nr = max_wl + 1
                if 0 <= nr < WORLD_H and em[nr, wire_col_left]:
                    return (Tool.WIRE, wire_col_left, nr)
            if min_wl > tmin:
                nr = min_wl - 1
                if 0 <= nr < WORLD_H and em[nr, wire_col_left]:
                    return (Tool.WIRE, wire_col_left, nr)

        road_rows_left = set(int(r) for r in np.where(rm[:, road_col_left])[0]) if 0 <= road_col_left < WORLD_W else set()
        for wr in wire_rows_left:
            if wr not in road_rows_left and 0 <= road_col_left < WORLD_W and em[wr, road_col_left]:
                return (Tool.ROAD, road_col_left, wr)

        wire_rows_left_set = set(wire_rows_left)
        for zr in sorted(wire_rows_left):
            road_nearby3 = any(abs(zr - rr) <= 2 for rr in road_rows_left)
            wire_nearby3 = any(abs(zr - wr) <= 1 for wr in wire_rows_left_set)
            if not (road_nearby3 and wire_nearby3):
                continue
            for zc in [left_zone_col2, wire_col_left + 3]:
                if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                    if not zone_nearby(zr, zc) and zone_area_free(zr, zc):
                        return (Tool.RESIDENTIAL, zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map every step and reacts to current state.
    Strategy:
    - Place coal power plant near left-center
    - Build wire spine vertically from plant
    - Build road column 2 tiles right of wire spine
    - Place zones on both sides of road (R zone left, C/I right)
    - Add lateral wires from spine to power left zones
    - Add horizontal roads to connect zones
    - Expand when population grows
    Key improvements over parent:
    - Wire spine is placed adjacent to plant (touching), ensuring power connectivity
    - Road is placed touching wire spine (1 tile gap) for better zone coverage
    - Zones placed touching road for guaranteed road access
    - Left zones get lateral wires at every zone row, not just spine rows
    - More aggressive expansion triggers
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    all_zone_mask = resm | comm | indm

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Phase 1: Place coal power plant if missing
    if not np.any(pm):
        # Place plant left of center
        return (Tool.COALPOWER, cx - 15, cy)

    # Find plant centroid
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Wire spine immediately right of plant (plant footprint is 4 tiles wide approx)
    # Plant center -> plant occupies cx-1..cx+1 cols, so rightmost is plant_cx+2
    wire_col = plant_cx + 3   # wire spine column, adjacent to plant right edge
    road_col = wire_col + 2   # road 2 tiles right of wire
    left_zone_col = wire_col - 4   # zone centers left of wire (touching wire from left)
    right_zone_col = road_col + 3  # zone centers right of road

    # Clamp
    wire_col = max(2, min(WORLD_W - 3, wire_col))
    road_col = max(2, min(WORLD_W - 3, road_col))
    left_zone_col = max(2, min(WORLD_W - 3, left_zone_col))
    right_zone_col = max(2, min(WORLD_W - 3, right_zone_col))

    wire_rows_on_spine = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])
    road_rows_on_col = sorted([r for r in range(WORLD_H) if rm[r, road_col]])

    # Spine extent grows with population
    if obs.city_pop < 100:
        spine_extent = 10
    elif obs.city_pop < 300:
        spine_extent = 16
    elif obs.city_pop < 600:
        spine_extent = 22
    else:
        spine_extent = 30

    target_min = max(2, cy - spine_extent)
    target_max = min(WORLD_H - 3, cy + spine_extent)

    # Phase 2: Start wire adjacent to plant if none on spine
    if not wire_rows_on_spine:
        # Try to place wire at plant_cy on wire_col
        for dy in range(0, 6):
            for nr in [plant_cy + dy, plant_cy - dy]:
                if 0 <= nr < WORLD_H:
                    if em[nr, wire_col] or wm[nr, wire_col]:
                        return (Tool.WIRE, wire_col, nr)
        return None

    min_wire_row = min(wire_rows_on_spine)
    max_wire_row = max(wire_rows_on_spine)

    # Phase 3: Extend wire spine downward
    if max_wire_row < target_max:
        nr = max_wire_row + 1
        if 0 <= nr < WORLD_H and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Phase 4: Extend wire spine upward
    if min_wire_row > target_min:
        nr = min_wire_row - 1
        if 0 <= nr < WORLD_H and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Phase 5: Build road column adjacent to wire spine
    for r in wire_rows_on_spine:
        if 0 <= r < WORLD_H and 0 <= road_col < WORLD_W:
            if not rm[r, road_col] and (em[r, road_col] or rm[r, road_col]):
                if em[r, road_col]:
                    return (Tool.ROAD, road_col, r)

    # Helper functions
    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    zone_rows = list(range(max(2, target_min), min(WORLD_H - 2, target_max + 1), 3))

    # Phase 6: Lateral wires from spine to reach left zone column
    # Do this BEFORE placing zones so zones get powered
    for wr in wire_rows_on_spine:
        # Extend wire leftward from spine to left_zone_col + 1 (just past zone edge)
        for wc in range(wire_col - 1, max(0, left_zone_col - 2), -1):
            if wm[wr, wc]:
                break  # already wired here
            if pm[wr, wc]:
                break  # don't overwrite plant
            if em[wr, wc]:
                return (Tool.WIRE, wc, wr)
            else:
                break  # blocked

    # Phase 7: Place zones where wire AND road coverage exists
    for zr in zone_rows:
        wire_near = any(abs(zr - wr) <= 3 for wr in wire_rows_on_spine)
        road_near = any(abs(zr - rr) <= 2 for rr in road_rows_on_col)

        if wire_near and road_near:
            # Try left zone
            zc = left_zone_col
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc, 4) and has_road_nearby(zr, zc, 5):
                    return (pick_tool(), zc, zr)
                elif has_wire_nearby(zr, zc, 6):
                    # Place anyway, road may come later
                    return (Tool.RESIDENTIAL, zc, zr)

            # Try right zone
            zc = right_zone_col
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_road_nearby(zr, zc, 4) and has_wire_nearby(zr, zc, 6):
                    return (pick_tool(), zc, zr)

    # Phase 8: Road extensions to right zone column
    for rr in wire_rows_on_spine:
        if not rm[rr, road_col]:
            continue
        for rc in range(road_col + 1, right_zone_col + 2):
            if 0 <= rc < WORLD_W:
                if rm[rr, rc]:
                    break
                if em[rr, rc] and not pm[rr, rc]:
                    return (Tool.ROAD, rc, rr)
                elif not em[rr, rc]:
                    break

    # Phase 9: Wire to right zone column for power
    for wr in wire_rows_on_spine:
        for wc in range(wire_col + 1, right_zone_col + 2):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif rm[wr, wc]:
                    # Road is here, skip but continue (road doesn't conduct)
                    continue
                else:
                    break

    # Phase 10: Second coal plant if needed
    if obs.city_pop > 300 and int(np.sum(pm)) < 9:
        # Check if powered zones are low compared to total zones
        if obs.powered_zones < total_zones // 9 + 1:
            px2 = plant_cx + 20
            py2 = plant_cy
            if 2 <= py2 <= WORLD_H - 3 and 2 <= px2 <= WORLD_W - 3:
                # Check area is clear enough
                if em[py2, px2]:
                    return (Tool.COALPOWER, px2, py2)

    # Phase 11: Horizontal roads connecting vertical spine area
    if obs.city_pop > 150:
        for rr in zone_rows:
            if 0 <= rr < WORLD_H:
                for rc in range(max(1, left_zone_col - 1), min(WORLD_W - 1, right_zone_col + 2)):
                    if 0 <= rc < WORLD_W and em[rr, rc] and not pm[rr, rc]:
                        if has_wire_nearby(rr, rc, 3) or has_road_nearby(rr, rc, 2):
                            return (Tool.ROAD, rc, rr)

    # Phase 12: Expand to third zone column when growing
    if obs.city_pop > 400:
        far_right_col = right_zone_col + 7
        far_left_col = left_zone_col - 7
        for zc in [far_right_col, far_left_col]:
            if 2 <= zc <= WORLD_W - 3:
                for zr in zone_rows:
                    if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                        if has_road_nearby(zr, zc, 6) and has_wire_nearby(zr, zc, 7):
                            return (Tool.RESIDENTIAL, zc, zr)

    # Phase 13: Add parks near zones for happiness if idle
    if obs.city_pop > 500:
        # Scan for empty tiles near zones
        zone_rows_actual, zone_cols_actual = np.where(all_zone_mask)
        if len(zone_rows_actual) > 0:
            idx = obs.step % len(zone_rows_actual)
            zr = int(zone_rows_actual[idx])
            zc = int(zone_cols_actual[idx])
            # Try placing park adjacent
            for dr, dc in [(0, 4), (4, 0), (0, -4), (-4, 0)]:
                pr, pc = zr + dr, zc + dc
                if 0 <= pr < WORLD_H and 0 <= pc < WORLD_W and em[pr, pc]:
                    return (Tool.PARK, pc, pr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy.
    Each step reads tile_map and decides next placement based on current state.
    Strategy:
    - Place coal power plant first
    - Build vertical wire spine adjacent to plant
    - Build road columns on both sides of wire spine
    - Place zones (RES/COM/IND mix) adjacent to roads
    - Lateral wires connect left zones to spine
    - Expand vertically and add second corridor as city grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    # Fixed layout anchor
    cx, cy = 58, 50

    # Phase 1: Place coal power plant
    plant_cx, plant_cy = cx - 8, cy
    has_plant = np.any(pm)
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Find actual plant location from map
    plant_locs = list(zip(*np.where(pm)))
    if plant_locs:
        plant_cy_actual, plant_cx_actual = plant_locs[0]
    else:
        plant_cy_actual, plant_cx_actual = plant_cy, plant_cx

    # Spine layout relative to plant
    wire_col = plant_cx_actual + 4
    road_col_L = wire_col - 1   # road left of wire
    road_col_R = wire_col + 1   # road right of wire
    left_zone_col = wire_col - 4
    right_zone_col = wire_col + 4

    # Collect positions from map
    wire_positions = set(zip(*np.where(wm))) if np.any(wm) else set()
    road_positions = set(zip(*np.where(rm))) if np.any(rm) else set()
    res_pos = set(zip(*np.where(res_mask(tm))))
    com_pos = set(zip(*np.where(com_mask(tm))))
    ind_pos = set(zip(*np.where(ind_mask(tm))))
    all_zones = res_pos | com_pos | ind_pos

    res_count = len(res_pos)
    com_count = len(com_pos)
    ind_count = len(ind_pos)
    total_zones = res_count + com_count + ind_count

    # Expand vertical span based on population
    base_span = 12
    extra_span = min(30, obs.city_pop // 30)
    target_span = base_span + extra_span
    tmin = max(2, cy - target_span)
    tmax = min(WORLD_H - 3, cy + target_span)

    # Wire spine rows in the main column
    wire_rows = sorted(r for (r, c) in wire_positions if c == wire_col)

    # Phase 2: Start wire spine adjacent to plant
    if not wire_rows:
        return (Tool.WIRE, wire_col, plant_cy_actual)

    min_wr = min(wire_rows)
    max_wr = max(wire_rows)

    # Phase 3: Extend wire spine vertically
    if max_wr < tmax:
        nr = max_wr + 1
        if nr < WORLD_H:
            return (Tool.WIRE, wire_col, nr)
    if min_wr > tmin:
        nr = min_wr - 1
        if nr >= 0:
            return (Tool.WIRE, wire_col, nr)

    wire_rows_set = set(wire_rows)
    road_L_rows = set(r for (r, c) in road_positions if c == road_col_L)
    road_R_rows = set(r for (r, c) in road_positions if c == road_col_R)

    # Phase 4: Build road columns on both sides of wire spine
    for wr in wire_rows:
        if wr not in road_L_rows and 0 <= road_col_L < WORLD_W:
            if em[wr, road_col_L]:
                return (Tool.ROAD, road_col_L, wr)
        if wr not in road_R_rows and 0 <= road_col_R < WORLD_W:
            if em[wr, road_col_R]:
                return (Tool.ROAD, road_col_R, wr)

    # Helper: check if 3x3 zone footprint is clear of non-empty tiles
    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def zone_exists_nearby(zr, zc):
        return any(abs(zr - pr) <= 2 and abs(zc - pc) <= 2 for (pr, pc) in all_zones)

    def pick_zone(zr, zc):
        # Balance: ~50% RES, ~25% COM, ~25% IND
        # More IND in lower rows, more COM in upper rows
        t = total_zones + 1
        if ind_count == 0 or (ind_count * 4 < t and zr >= cy):
            return Tool.INDUSTRIAL
        if com_count == 0 or (com_count * 4 < t):
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Phase 5: Place zones along the wire rows
    for wr in wire_rows:
        road_L_near = any(abs(wr - rr) <= 2 for rr in road_L_rows)
        road_R_near = any(abs(wr - rr) <= 2 for rr in road_R_rows)

        # Left zone: needs left road nearby
        if road_L_near:
            zc = left_zone_col
            if 2 <= wr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                if not zone_exists_nearby(wr, zc) and zone_area_free(wr, zc):
                    return (pick_zone(wr, zc), zc, wr)

        # Right zone: needs right road nearby
        if road_R_near:
            zc = right_zone_col
            if 2 <= wr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                if not zone_exists_nearby(wr, zc) and zone_area_free(wr, zc):
                    return (pick_zone(wr, zc), zc, wr)

    # Phase 6: Lateral wires from spine to left zones
    for wr in wire_rows:
        for wc in range(wire_col - 1, left_zone_col - 1, -1):
            if 0 <= wc < WORLD_W and em[wr, wc]:
                return (Tool.WIRE, wc, wr)

    # Phase 7: Second corridor to the right if population growing
    if obs.city_pop > 150:
        wire_col2 = wire_col + 9
        road_col2L = wire_col2 - 1
        road_col2R = wire_col2 + 1
        left_zone_col2 = wire_col2 - 4
        right_zone_col2 = wire_col2 + 4

        wire_rows2 = sorted(r for (r, c) in wire_positions if c == wire_col2)

        if not wire_rows2:
            # Extend wire horizontally from spine to second spine
            for wr in wire_rows:
                for wc in range(wire_col + 1, wire_col2 + 1):
                    if 0 <= wc < WORLD_W and em[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                break
        else:
            min_wr2 = min(wire_rows2)
            max_wr2 = max(wire_rows2)

            if max_wr2 < tmax:
                nr = max_wr2 + 1
                if nr < WORLD_H:
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > tmin:
                nr = min_wr2 - 1
                if nr >= 0:
                    return (Tool.WIRE, wire_col2, nr)

            road2L_rows = set(r for (r, c) in road_positions if c == road_col2L)
            road2R_rows = set(r for (r, c) in road_positions if c == road_col2R)

            for wr in wire_rows2:
                if wr not in road2L_rows and 0 <= road_col2L < WORLD_W:
                    if em[wr, road_col2L]:
                        return (Tool.ROAD, road_col2L, wr)
                if wr not in road2R_rows and 0 <= road_col2R < WORLD_W:
                    if em[wr, road_col2R]:
                        return (Tool.ROAD, road_col2R, wr)

            for wr in wire_rows2:
                road2L_near = any(abs(wr - rr) <= 2 for rr in road2L_rows)
                road2R_near = any(abs(wr - rr) <= 2 for rr in road2R_rows)

                if road2L_near:
                    zc = left_zone_col2
                    if 2 <= wr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                        if not zone_exists_nearby(wr, zc) and zone_area_free(wr, zc):
                            return (pick_zone(wr, zc), zc, wr)

                if road2R_near:
                    zc = right_zone_col2
                    if 2 <= wr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                        if not zone_exists_nearby(wr, zc) and zone_area_free(wr, zc):
                            return (pick_zone(wr, zc), zc, wr)

            # Lateral wires for second corridor left zones
            for wr in wire_rows2:
                for wc in range(wire_col2 - 1, left_zone_col2 - 1, -1):
                    if 0 <= wc < WORLD_W and em[wr, wc]:
                        return (Tool.WIRE, wc, wr)

    # Phase 8: Services when population sufficient
    if obs.city_pop > 300:
        fire_x, fire_y = wire_col + 6, cy - 8
        if 2 <= fire_x < WORLD_W - 2 and 2 <= fire_y < WORLD_H - 2:
            if zone_area_free(fire_y, fire_x):
                return (Tool.FIRESTATION, fire_x, fire_y)

    if obs.city_pop > 500:
        police_x, police_y = wire_col + 6, cy + 8
        if 2 <= police_x < WORLD_W - 2 and 2 <= police_y < WORLD_H - 2:
            if zone_area_free(police_y, police_x):
                return (Tool.POLICESTATION, police_x, police_y)

    return None

def act(obs, state):
    """
    Closed-loop city builder with improved reactivity.
    Key changes from parent:
    - Build road FIRST from plant, then wire alongside it (roads draw zones)
    - Wire placed adjacent to road spine, not separate
    - Zone placement is purely reactive: scan for tiles near existing road+wire
    - Use BFS-like frontier expansion instead of fixed grid
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Plant center for the cluster
    PLANT_X, PLANT_Y = 30, 50

    # --- Phase 1: Place power plant if none exists ---
    if not np.any(pm):
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    # Find plant centroid
    plant_ys, plant_xs = np.where(pm)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    # Collect current sets
    wire_ys, wire_xs = np.where(wm)
    road_ys, road_xs = np.where(rm)
    res_ys, res_xs = np.where(resm)
    com_ys, com_xs = np.where(comm)
    ind_ys, ind_xs = np.where(indm)

    wire_set = set(zip(wire_ys.tolist(), wire_xs.tolist()))
    road_set = set(zip(road_ys.tolist(), road_xs.tolist()))
    zone_ys = np.concatenate([res_ys, com_ys, ind_ys])
    zone_xs = np.concatenate([res_xs, com_xs, ind_xs])
    zone_set = set(zip(zone_ys.tolist(), zone_xs.tolist()))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        r = res_count / t
        c = com_count / t
        i = ind_count / t
        if c < 0.25:
            return Tool.COMMERCIAL
        if i < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Road spine: horizontal from plant, extending right
    # Wire spine: one row above road spine, parallel
    ROAD_Y = py + 2      # road row
    WIRE_Y = py + 1      # wire row (between plant and road)
    ROAD_START = px + 2
    ROAD_END = min(px + 60, WORLD_W - 4)

    # Also second road below plant
    ROAD_Y2 = py - 2
    WIRE_Y2 = py - 1

    # --- Phase 2: Wire from plant to road spine ---
    # Connect plant to wire row (vertical wire segment)
    # Plant occupies ~3x3 around (px,py). Wire row is WIRE_Y.
    # If WIRE_Y != py, we need a vertical wire connecting them.
    if WIRE_Y != py:
        step = 1 if WIRE_Y > py else -1
        for wy in range(py + step, WIRE_Y + step, step):
            if not in_bounds(px, wy):
                break
            if not wm[wy, px] and not pm[wy, px]:
                if em[wy, px]:
                    return (Tool.WIRE, px, wy)
                break

    # --- Phase 3: Extend wire spine horizontally ---
    # Wire at WIRE_Y from plant outward
    wire_in_row = sorted([c for (r, c) in wire_set if r == WIRE_Y])
    max_wire_col = max(wire_in_row) if wire_in_row else px
    if max_wire_col < ROAD_END:
        nc = max_wire_col + 1
        if in_bounds(nc, WIRE_Y):
            if em[WIRE_Y, nc] or wm[WIRE_Y, nc]:
                if em[WIRE_Y, nc]:
                    return (Tool.WIRE, nc, WIRE_Y)
            # If blocked, skip this row

    # Wire at WIRE_Y2
    wire_in_row2 = sorted([c for (r, c) in wire_set if r == WIRE_Y2])
    max_wire_col2 = max(wire_in_row2) if wire_in_row2 else px
    if max_wire_col2 < ROAD_END:
        nc = max_wire_col2 + 1
        if in_bounds(nc, WIRE_Y2) and em[WIRE_Y2, nc]:
            return (Tool.WIRE, nc, WIRE_Y2)

    # Vertical wire connector from wire spine every few cols
    for vc in range(px + 2, ROAD_END + 1, 4):
        if not in_bounds(vc, WIRE_Y):
            continue
        if wm[WIRE_Y, vc] or pm[WIRE_Y, vc]:
            # Extend vertical wire down to ROAD_Y
            step = 1 if ROAD_Y > WIRE_Y else -1
            for wy in range(WIRE_Y + step, ROAD_Y + step, step):
                if not in_bounds(vc, wy):
                    break
                if not wm[wy, vc] and not rm[wy, vc] and not pm[wy, vc]:
                    if em[wy, vc]:
                        return (Tool.WIRE, vc, wy)
                    break

    # --- Phase 4: Road spine ---
    road_in_row = sorted([c for (r, c) in road_set if r == ROAD_Y])
    max_road_col = max(road_in_row) if road_in_row else ROAD_START - 1
    if max_road_col < ROAD_END:
        nc = max_road_col + 1
        if in_bounds(nc, ROAD_Y) and not pm[ROAD_Y, nc]:
            return (Tool.ROAD, nc, ROAD_Y)

    # Second road spine (above plant)
    road_in_row2 = sorted([c for (r, c) in road_set if r == ROAD_Y2])
    max_road_col2 = max(road_in_row2) if road_in_row2 else ROAD_START - 1
    if max_road_col2 < ROAD_END:
        nc = max_road_col2 + 1
        if in_bounds(nc, ROAD_Y2) and not pm[ROAD_Y2, nc]:
            return (Tool.ROAD, nc, ROAD_Y2)

    # Vertical connector roads between the two road spines every 4 cols
    for vc in range(ROAD_START, ROAD_END + 1, 4):
        if not in_bounds(vc, ROAD_Y):
            continue
        min_r, max_r = min(ROAD_Y, ROAD_Y2), max(ROAD_Y, ROAD_Y2)
        for vr in range(min_r, max_r + 1):
            if not in_bounds(vc, vr):
                continue
            if (vr, vc) not in road_set and not pm[vr, vc]:
                if em[vr, vc] or not rm[vr, vc]:
                    return (Tool.ROAD, vc, vr)

    # Extend additional horizontal roads further from spine
    for extra_offset in [5, 8, 11]:
        for base_y in [ROAD_Y + extra_offset, ROAD_Y - extra_offset,
                       ROAD_Y2 + extra_offset, ROAD_Y2 - extra_offset]:
            if not in_bounds(0, base_y):
                continue
            road_in_extra = sorted([c for (r, c) in road_set if r == base_y])
            max_extra = max(road_in_extra) if road_in_extra else ROAD_START - 1
            if max_extra < ROAD_END:
                nc = max_extra + 1
                if in_bounds(nc, base_y) and not pm[base_y, nc]:
                    return (Tool.ROAD, nc, base_y)

    # --- Phase 5: Reactive zone placement ---
    # Build dilated road and wire masks for fast lookup
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    # Find candidate zone centers: must be near road AND wire AND clear
    cand = em & nbr_road & nbr_wire
    # Avoid edges
    cand[:2, :] = False; cand[-2:, :] = False
    cand[:, :2] = False; cand[:, -2:] = False
    cys, cxs = np.where(cand)

    if len(cxs) > 0:
        # Pick deterministically based on step but vary
        # Try first valid one in a sweep
        step_mod = obs.step % max(len(cxs), 1)
        # Try a few candidates
        for offset in range(min(20, len(cxs))):
            k = (step_mod + offset * 7) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # --- Phase 6: Second power plant if population growing ---
    if obs.city_pop > 500 and np.sum(pm) < 18:
        nx2, ny2 = px + 35, py
        if in_bounds(nx2, ny2) and em[ny2, nx2]:
            return (Tool.COALPOWER, nx2, ny2)
        # Try nearby empty spot
        for dy in range(-3, 4):
            for dx in range(-3, 4):
                tx, ty = nx2 + dx, ny2 + dy
                if in_bounds(tx, ty) and em[ty, tx]:
                    return (Tool.COALPOWER, tx, ty)

    # --- Phase 7: Services ---
    if obs.city_pop > 150:
        fx, fy = px + 3, py - 8
        if in_bounds(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
        fx2, fy2 = px + 3, py + 8
        if in_bounds(fx2, fy2) and em[fy2, fx2]:
            return (Tool.POLICESTATION, fx2, fy2)

    # --- Phase 8: Extend road reactively from frontier ---
    if len(road_xs) > 0:
        k = (obs.step * 13) % len(road_xs)
        rx, ry = int(road_xs[k]), int(road_ys[k])
        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx + dx, ry + dy
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                return (Tool.ROAD, nx2, ny2)

    # --- Phase 9: Extend wire from frontier ---
    if len(wire_xs) > 0:
        k = (obs.step * 11) % len(wire_xs)
        wx2, wy2 = int(wire_xs[k]), int(wire_ys[k])
        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = wx2 + dx, wy2 + dy
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop city builder - reactive version.
    Each step reads the map and places the next needed tile.
    Strategy:
    1. Place coal power plant if none exists
    2. Build wire spine from plant outward (reactive: check what's already there)
    3. Build road grid near wire (reactive: extend from existing roads)
    4. Place zones adjacent to roads+wires
    5. Add more plants/services as city grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Phase 1: Ensure power plant exists ---
    has_plant = np.any(pm)
    if not has_plant:
        # Place plant at a good central-left position
        return (Tool.COALPOWER, 30, 50)

    # Get plant center
    plant_ys, plant_xs = np.where(pm)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    wire_ys, wire_xs = np.where(wm)
    road_ys, road_xs = np.where(rm)
    res_ys, res_xs = np.where(resm)
    com_ys, com_xs = np.where(comm)
    ind_ys, ind_xs = np.where(indm)

    wire_set = set(zip(wire_ys.tolist(), wire_xs.tolist()))
    road_set = set(zip(road_ys.tolist(), road_xs.tolist()))
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # --- Phase 2: Reactive wire spine ---
    # We want wires extending: right from plant (horizontal spine)
    # and vertical spines branching off

    # Main horizontal wire spine at py row, going right
    spine_y = py
    spine_x_start = px + 2  # right of plant
    spine_x_end = min(px + 50, WORLD_W - 3)

    for wx in range(spine_x_start, spine_x_end + 1):
        if (spine_y, wx) not in wire_set:
            if in_bounds(wx, spine_y) and not pm[spine_y, wx]:
                return (Tool.WIRE, wx, spine_y)
            break

    # Vertical wire branches every 6 columns
    for bx in range(spine_x_start, spine_x_end, 6):
        # Up branch
        for dy in range(1, 9):
            wy, wx2 = spine_y - dy, bx
            if not in_bounds(wx2, wy):
                break
            if (wy, wx2) not in wire_set:
                if not pm[wy, wx2]:
                    return (Tool.WIRE, wx2, wy)
                break
            # already wired, continue
        # Down branch
        for dy in range(1, 9):
            wy, wx2 = spine_y + dy, bx
            if not in_bounds(wx2, wy):
                break
            if (wy, wx2) not in wire_set:
                if not pm[wy, wx2]:
                    return (Tool.WIRE, wx2, wy)
                break

    # --- Phase 3: Reactive road building ---
    # Build horizontal roads 4 rows above and below spine
    road_above_y = spine_y - 4
    road_below_y = spine_y + 4
    road_x_start = spine_x_start
    road_x_end = min(spine_x_end + 2, WORLD_W - 3)

    # Top road
    for rx in range(road_x_start, road_x_end + 1):
        if (road_above_y, rx) not in road_set:
            if in_bounds(rx, road_above_y) and not pm[road_above_y, rx]:
                return (Tool.ROAD, rx, road_above_y)
            break

    # Bottom road
    for rx in range(road_x_start, road_x_end + 1):
        if (road_below_y, rx) not in road_set:
            if in_bounds(rx, road_below_y) and not pm[road_below_y, rx]:
                return (Tool.ROAD, rx, road_below_y)
            break

    # Vertical connector roads every 6 cols
    for vcx in range(road_x_start, road_x_end + 1, 6):
        for vcy in range(road_above_y, road_below_y + 1):
            if (vcy, vcx) not in road_set:
                if in_bounds(vcx, vcy) and not pm[vcy, vcx]:
                    return (Tool.ROAD, vcx, vcy)

    # Second tier roads further out
    road_above2_y = spine_y - 9
    road_below2_y = spine_y + 9
    for rx in range(road_x_start, road_x_end + 1):
        if (road_above2_y, rx) not in road_set:
            if in_bounds(rx, road_above2_y) and not pm[road_above2_y, rx]:
                return (Tool.ROAD, rx, road_above2_y)
            break
    for rx in range(road_x_start, road_x_end + 1):
        if (road_below2_y, rx) not in road_set:
            if in_bounds(rx, road_below2_y) and not pm[road_below2_y, rx]:
                return (Tool.ROAD, rx, road_below2_y)
            break

    # --- Phase 4: Reactive zone placement ---
    def pick_tool():
        t = max(total_zones, 1)
        if res_count / t < 0.5:
            return Tool.RESIDENTIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc]:
                    return False
        return True

    # Build neighbor masks reactively
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Zone rows: between roads and slightly beyond
    zone_rows = [
        road_above_y - 2, road_above_y + 2,
        road_below_y - 2, road_below_y + 2,
        road_above2_y - 2, road_above2_y + 2,
        road_below2_y - 2, road_below2_y + 2,
    ]
    zone_cols = list(range(road_x_start + 1, road_x_end, 3))

    for zr in zone_rows:
        for zc in zone_cols:
            if not (2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3):
                continue
            if zone_clear(zc, zr) and nbr_road[zr, zc] and nbr_wire[zr, zc]:
                return (pick_tool(), zc, zr)

    # Scan more broadly for good zone spots
    cand = em & nbr_road & nbr_wire
    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        # Try multiple candidates in a deterministic order
        step_hash = obs.step % max(len(cxs), 1)
        for offset in range(min(50, len(cxs))):
            k = (step_hash + offset * 7) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if 2 <= zy <= WORLD_H - 3 and 2 <= zx <= WORLD_W - 3:
                if zone_clear(zx, zy):
                    return (pick_tool(), zx, zy)

    # --- Phase 5: Second power plant if population growing ---
    if obs.city_pop > 500 and np.sum(pm) < 9:
        nx2, ny2 = px + 25, py
        if in_bounds(nx2, ny2) and em[ny2, nx2]:
            return (Tool.COALPOWER, nx2, ny2)

    # --- Phase 6: Services ---
    if obs.city_pop > 200:
        fx, fy = px + 5, py - 12
        if in_bounds(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
        fx2, fy2 = px + 5, py + 12
        if in_bounds(fx2, fy2) and em[fy2, fx2]:
            return (Tool.POLICESTATION, fx2, fy2)

    # --- Fallback: extend road from frontier ---
    if len(road_xs) > 0:
        k = obs.step % len(road_xs)
        rx, ry = int(road_xs[k]), int(road_ys[k])
        for dx, dy in [(1, 0), (0, 1), (-1, 0), (0, -1)]:
            nx2, ny2 = rx + dx, ry + dy
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                return (Tool.ROAD, nx2, ny2)

    # Extend wire from closest wire to unserved zone
    zone_arr = np.where(resm | comm | indm)
    for i in range(min(20, len(zone_arr[0]))):
        zyr, zxc = int(zone_arr[0][i]), int(zone_arr[1][i])
        if not nbr_wire[zyr, zxc]:
            if wire_set:
                closest_w = min(wire_set, key=lambda p: abs(p[0] - zyr) + abs(p[1] - zxc))
                wr, wc = closest_w
                step_r = (1 if zyr > wr else -1 if zyr < wr else 0)
                step_c = (1 if zxc > wc else -1 if zxc < wc else 0)
                for nr, nc in [(wr + step_r, wc), (wr, wc + step_c)]:
                    if in_bounds(nc, nr) and em[nr, nc] and not pm[nr, nc]:
                        return (Tool.WIRE, nc, nr)

    return None

def act(obs, state):
    """
    Improved policy: Two parallel road corridors with zones on both sides,
    connected by a central wire spine. Better zone mix (RES/COM/IND balance).
    Nuclear power for more capacity. Wider coverage.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    step = obs.step

    # Initialize state
    if 'phase' not in state:
        state['phase'] = 0
        state['action_queue'] = []

    # Build action queue if empty
    if not state['action_queue']:
        # We'll compute actions based on current map state
        pass

    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    res_count = int(np.sum(res_m))
    com_count = int(np.sum(com_m))
    ind_count = int(np.sum(ind_m))

    # Layout: center around (60, 50)
    # Power plant at (30, 50) - left side
    # Wire spine at col 34 (just right of plant footprint 27..33)
    # Road A at col 37, Road B at col 42
    # Left zones at col 34-3=31... but plant is there. Use left of plant.
    # Actually: plant center (30,50), footprint cols 27-33
    # Wire spine col 35 (adjacent to plant right edge 33+2=35? No, edge at 33, so 34 is adjacent)
    # Wire col = 35
    # Road col A = 38 (3 right of wire)
    # Road col B = 44 (6 right of road A)  
    # Left zones col = 35 (wire col) - but zones need to be left of wire
    # Zone L col = 31 (left of plant? plant at 30, footprint 27-33... no)
    # Let's rethink: plant center at (25, 50)
    # footprint: x=22..28, y=47..53
    # wire spine col = 30
    # road col A = 33
    # road col B = 40
    # Left zone col = 36 (right of road A, left of road B)
    # Right zone col = 43 (right of road B)

    px, py = 25, 50   # plant center
    wire_col = 30     # wire spine (adjacent to plant right edge at 28)
    road_col_a = 34   # first road
    road_col_b = 41   # second road (7 tiles right)
    zone_col_l = 37   # zones between roads (center)
    zone_col_r = 45   # zones right of road B
    zone_col_ll = 22  # zones left of plant (left side)

    has_plant = np.any(pm)

    # Phase 1: Place nuclear power plant
    if not has_plant:
        return (Tool.COALPOWER, px, py)

    wire_rows = sorted([r for (r, c) in zip(*np.where(wm)) if c == wire_col])
    road_a_rows = sorted([r for (r, c) in zip(*np.where(rm)) if c == road_col_a])
    road_b_rows = sorted([r for (r, c) in zip(*np.where(rm)) if c == road_col_b])

    target_min = max(1, py - 18)
    target_max = min(WORLD_H - 2, py + 18)

    # Phase 2: Start wire spine adjacent to plant
    if not wire_rows:
        if 0 <= wire_col < WORLD_W and em[py, wire_col]:
            return (Tool.WIRE, wire_col, py)
        for dy in range(1, 6):
            for nr in [py + dy, py - dy]:
                if 0 <= nr < WORLD_H and em[nr, wire_col]:
                    return (Tool.WIRE, wire_col, nr)
        return None

    min_row = min(wire_rows)
    max_row = max(wire_rows)

    # Phase 3: Extend wire spine vertically
    if max_row < target_max:
        nr = max_row + 1
        if nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
            return (Tool.WIRE, wire_col, nr)

    if min_row > target_min:
        nr = min_row - 1
        if nr >= 0 and (em[nr, wire_col] or wm[nr, wire_col]):
            return (Tool.WIRE, wire_col, nr)

    # Phase 4: Build road A (col 34)
    for r in wire_rows:
        if 0 <= r < WORLD_H and not rm[r, road_col_a]:
            if em[r, road_col_a] or rm[r, road_col_a]:
                return (Tool.ROAD, road_col_a, r)

    # Phase 5: Build road B (col 41) - parallel road for second lane
    for r in wire_rows:
        if 0 <= r < WORLD_H and not rm[r, road_col_b]:
            if em[r, road_col_b]:
                return (Tool.ROAD, road_col_b, r)

    # Phase 6: Connect road A to wire spine with lateral wires
    for r in wire_rows:
        for c in range(wire_col + 1, road_col_a):
            if 0 <= c < WORLD_W and em[r, c] and not wm[r, c]:
                return (Tool.WIRE, c, r)

    # Phase 7: Connect road B to wire via horizontal road/wire
    for r in wire_rows:
        for c in range(road_col_a + 1, road_col_b):
            if 0 <= c < WORLD_W and em[r, c] and not rm[r, c] and not wm[r, c]:
                return (Tool.WIRE, c, r)

    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    all_road_rows = sorted(set(road_a_rows + road_b_rows))

    # Phase 8: Place zones between and around roads
    zone_rows = list(range(target_min + 1, target_max, 3))

    for zr in zone_rows:
        road_a_near = any(abs(zr - rr) <= 2 for rr in road_a_rows)
        road_b_near = any(abs(zr - rr) <= 2 for rr in road_b_rows)
        wire_near = any(abs(zr - wr) <= 2 for wr in wire_rows)

        # Left of road A (between wire and road A) - zone_col_l = 37
        if road_a_near and wire_near:
            zc = zone_col_l
            if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1 and zone_area_free(zr, zc):
                # Zone mix: balanced RES/COM/IND
                if ind_count < res_count // 2:
                    return (Tool.INDUSTRIAL, zc, zr)
                elif com_count < res_count // 2:
                    return (Tool.COMMERCIAL, zc, zr)
                else:
                    return (Tool.RESIDENTIAL, zc, zr)

        # Right of road B
        if road_b_near and wire_near:
            zc = zone_col_r
            if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1 and zone_area_free(zr, zc):
                if com_count < res_count:
                    return (Tool.COMMERCIAL, zc, zr)
                else:
                    return (Tool.RESIDENTIAL, zc, zr)

    # Phase 9: Add wire to connect right zones to power
    for wr in wire_rows:
        for c in range(road_col_b + 1, zone_col_r + 2):
            if 0 <= c < WORLD_W and em[wr, c] and not wm[wr, c] and not rm[wr, c]:
                return (Tool.WIRE, c, wr)

    # Phase 10: Left side - zones left of plant
    if obs.city_pop > 200:
        # Wire to left
        wire_col_left = px - 4  # left of plant footprint
        for r in wire_rows:
            for c in range(wire_col - 1, wire_col_left - 1, -1):
                if 0 <= c < WORLD_W and em[r, c] and not wm[r, c] and not pm[r, c]:
                    return (Tool.WIRE, c, r)

        # Road left
        road_col_left = px - 7
        if 0 <= road_col_left < WORLD_W:
            for r in wire_rows:
                if em[r, road_col_left] and not rm[r, road_col_left]:
                    return (Tool.ROAD, road_col_left, r)

        # Zones left
        zc_left = px - 10
        if 1 <= zc_left < WORLD_W - 1:
            for zr in zone_rows:
                road_left_near = any(abs(zr - r) <= 2 for (r, c) in zip(*np.where(rm)) if c == road_col_left) if np.any(rm) else False
                wire_near2 = any(abs(zr - wr) <= 3 for wr in wire_rows)
                if wire_near2 and 1 <= zr < WORLD_H - 1 and zone_area_free(zr, zc_left):
                    return (Tool.RESIDENTIAL, zc_left, zr)

    # Phase 11: Expand zone columns further if growing
    if obs.city_pop > 400:
        zone_col_far = zone_col_r + 7
        if zone_col_far < WORLD_W - 2:
            for zr in zone_rows:
                if zone_area_free(zr, zone_col_far):
                    # Need road there too
                    road_far = zone_col_r + 3
                    if 0 <= road_far < WORLD_W:
                        for r in wire_rows:
                            if em[r, road_far] and not rm[r, road_far]:
                                return (Tool.ROAD, road_far, r)
                    return (Tool.RESIDENTIAL, zone_col_far, zr)

    # Phase 12: Add second power plant if needed
    if obs.city_pop > 600 and obs.powered_zones < 10:
        # Place second coal plant connected to wire spine
        plant2_x = wire_col + 20
        plant2_y = py
        if 3 <= plant2_x < WORLD_W - 3 and 3 <= plant2_y < WORLD_H - 3:
            if zone_area_free(plant2_y, plant2_x):
                return (Tool.COALPOWER, plant2_x, plant2_y)

    return None

def act(obs, state):
    # Closed-loop reactive policy:
    # 1. Place coal plant if not present
    # 2. Extend wire from plant outward (BFS-like: find powered tiles, extend to neighbors)
    # 3. Place roads adjacent to wire
    # 4. Place zones adjacent to roads that are powered (wire within 1 tile)
    # 5. Add more power plants if needed

    tm = obs.tile_map
    pm = plant_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)
    emp = empty_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    def safe(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def get(mask, x, y):
        return bool(mask[y, x]) if safe(x, y) else False

    # Phase 0: ensure coal plant at (cx-2, cy)
    plant_x, plant_y = cx - 2, cy
    if not np.any(pm):
        return (Tool.COALPOWER, plant_x, plant_y)

    # Find all plant tile positions
    plant_positions = list(zip(*np.where(pm)))  # (row, col)

    # "Powered" tiles = plant tiles or wire tiles
    powered = wm | pm

    # Phase 1: Extend wire from powered region
    # Find a powered tile that has an empty neighbor, place wire there
    # Priority: extend downward/upward along a spine, then horizontally
    # Scan for empty neighbors of powered tiles in a structured way
    # We'll extend a vertical wire spine from the plant, then horizontal branches

    # Determine wire spine column = plant_x + 2 (i.e., cx)
    spine_x = cx
    # Extend wire spine vertically from cy-20 to cy+20
    spine_rows = list(range(cy - 20, cy + 21))

    # Check if spine column has continuous wire from plant row
    # First connect plant to spine if not connected
    # Plant center is at plant_x, plant_y. The plant occupies ~3x3 around it.
    # Wire from plant_x+1 (=cx-1) to spine_x (=cx)
    for wx in range(plant_x + 1, spine_x + 1):
        if not get(powered, wx, plant_y):
            return (Tool.WIRE, wx, plant_y)

    # Extend wire along spine vertically - find gaps
    # Go outward from cy
    for dist in range(0, 21):
        for dy in [cy + dist, cy - dist]:
            if dy in spine_rows:
                if not get(powered, spine_x, dy):
                    # Only extend if adjacent powered tile exists
                    for nx, ny in [(spine_x, dy-1), (spine_x, dy+1), (spine_x-1, dy), (spine_x+1, dy)]:
                        if get(powered, nx, ny):
                            return (Tool.WIRE, spine_x, dy)

    # Phase 2: Place road column at spine_x + 1
    road_x = spine_x + 1
    for dy in spine_rows:
        if not get(rm, road_x, dy):
            return (Tool.ROAD, road_x, dy)

    # Also place road on left side: spine_x - 5
    road_x_left = spine_x - 5
    # Need wire to reach there: horizontal wire at each zone row
    zone_rows = list(range(cy - 18, cy + 19, 3))
    for dy in zone_rows:
        if not safe(road_x_left, dy):
            continue
        # Wire from spine to road_x_left-1
        for wx in range(spine_x - 1, road_x_left, -1):
            if not get(powered, wx, dy):
                if get(powered, wx + 1, dy):
                    return (Tool.WIRE, wx, dy)
        # Road at road_x_left
        if not get(rm, road_x_left, dy):
            if get(powered, road_x_left + 1, dy):
                return (Tool.ROAD, road_x_left, dy)

    # Phase 3: Place zones
    # Right side residential: center at road_x + 2 (road is at road_x, zone center 2 right)
    res_x_right = road_x + 2
    com_x_right = road_x + 5
    ind_x_left = road_x_left - 3

    for dy in zone_rows:
        if not safe(res_x_right, dy):
            continue
        # Check powered nearby (wire within 2 tiles)
        powered_nearby = any(get(powered, res_x_right + dx, dy + ddx)
                             for dx in range(-2, 3) for ddx in range(-2, 3)
                             if safe(res_x_right + dx, dy + ddx))
        road_nearby = any(get(rm, res_x_right + dx, dy + ddx)
                          for dx in [-1, 0, 1] for ddx in [-1, 0, 1]
                          if safe(res_x_right + dx, dy + ddx))
        if powered_nearby and road_nearby and not get(res_m, res_x_right, dy):
            return (Tool.RESIDENTIAL, res_x_right, dy)

    # Commercial zones right
    for dy in zone_rows:
        if not safe(com_x_right, dy):
            continue
        # Need wire to reach com_x_right
        for wx in range(spine_x + 1, com_x_right):
            if not get(powered, wx, dy) and not get(rm, wx, dy):
                if get(powered, wx - 1, dy):
                    return (Tool.WIRE, wx, dy)
        # Road at com_x_right - 1
        if not get(rm, com_x_right - 1, dy):
            if get(powered, com_x_right - 1, dy):
                return (Tool.ROAD, com_x_right - 1, dy)
        powered_nearby = any(get(powered, com_x_right + dx, dy + ddx)
                             for dx in range(-2, 3) for ddx in range(-2, 3)
                             if safe(com_x_right + dx, dy + ddx))
        road_nearby = any(get(rm, com_x_right + dx, dy + ddx)
                          for dx in [-1, 0, 1] for ddx in [-1, 0, 1]
                          if safe(com_x_right + dx, dy + ddx))
        if powered_nearby and road_nearby and not get(com_m, com_x_right, dy):
            return (Tool.COMMERCIAL, com_x_right, dy)

    # Industrial zones left
    for dy in zone_rows:
        if not safe(ind_x_left, dy):
            continue
        powered_nearby = any(get(powered, ind_x_left + dx, dy + ddx)
                             for dx in range(-2, 3) for ddx in range(-2, 3)
                             if safe(ind_x_left + dx, dy + ddx))
        road_nearby = any(get(rm, ind_x_left + dx, dy + ddx)
                          for dx in [-1, 0, 1] for ddx in [-1, 0, 1]
                          if safe(ind_x_left + dx, dy + ddx))
        if powered_nearby and road_nearby and not get(ind_m, ind_x_left, dy):
            return (Tool.INDUSTRIAL, ind_x_left, dy)

    # Phase 4: Second coal plant if population growing
    plant2_x, plant2_y = cx + 12, cy
    if obs.city_pop > 100 and not get(pm, plant2_x, plant2_y):
        # Wire from road_x outward to plant2
        for wx in range(road_x + 1, plant2_x):
            if not get(powered, wx, plant2_y):
                if get(powered, wx - 1, plant2_y):
                    return (Tool.WIRE, wx, plant2_y)
        return (Tool.COALPOWER, plant2_x, plant2_y)

    # Phase 5: More residential zones using second plant power
    res2_x = com_x_right + 4
    for dy in zone_rows:
        if not safe(res2_x, dy):
            continue
        powered_nearby = any(get(powered, res2_x + dx, dy + ddx)
                             for dx in range(-3, 4) for ddx in range(-3, 4)
                             if safe(res2_x + dx, dy + ddx))
        road_nearby = any(get(rm, res2_x + dx, dy + ddx)
                          for dx in [-1, 0, 1] for ddx in [-1, 0, 1]
                          if safe(res2_x + dx, dy + ddx))
        if powered_nearby and road_nearby and not get(res_m, res2_x, dy):
            return (Tool.RESIDENTIAL, res2_x, dy)

    # Fill in extra roads near second plant area
    road2_x = plant2_x - 2
    for dy in spine_rows:
        if safe(road2_x, dy) and not get(rm, road2_x, dy):
            if get(powered, road2_x - 1, dy) or get(powered, road2_x + 1, dy):
                return (Tool.ROAD, road2_x, dy)

    return None

def act(obs, state):
    """
    Variation: horizontal corridor layout instead of vertical spine.
    - Power plant top-left area
    - Horizontal wire row running across the map
    - Roads above and below wire row
    - Zones placed above and below roads
    - Multiple horizontal corridors stacked vertically
    - Aggressive zone mix with balanced RES/COM/IND
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    has_plant = np.any(pm)

    # Power plant location
    plant_x, plant_y = 10, 50

    if not has_plant:
        return (Tool.COALPOWER, plant_x, plant_y)

    wire_positions = set(zip(*np.where(wm))) if np.any(wm) else set()
    road_positions = set(zip(*np.where(rm))) if np.any(rm) else set()
    res_pos = set(zip(*np.where(res_mask(tm))))
    com_pos = set(zip(*np.where(com_mask(tm))))
    ind_pos = set(zip(*np.where(ind_mask(tm))))
    all_zones = res_pos | com_pos | ind_pos

    res_count = len(res_pos)
    com_count = len(com_pos)
    ind_count = len(ind_pos)

    # Define horizontal corridors: each has a wire_row, road above, road below, zone rows
    # Corridors centered around plant_y
    corridors = [
        {'wire_row': 50, 'road_above': 49, 'road_below': 51, 'zone_above': 46, 'zone_below': 54},
        {'wire_row': 60, 'road_above': 59, 'road_below': 61, 'zone_above': 56, 'zone_below': 64},
        {'wire_row': 40, 'road_above': 39, 'road_below': 41, 'zone_above': 36, 'zone_below': 44},
        {'wire_row': 70, 'road_above': 69, 'road_below': 71, 'zone_above': 66, 'zone_below': 74},
    ]

    # How far to extend wires horizontally
    base_reach = 20
    extra_reach = min(50, obs.city_pop // 20)
    target_reach = min(WORLD_W - 5, plant_x + base_reach + extra_reach)

    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def already_zone_nearby(zr, zc, dist=3):
        return any(abs(zr - pr) <= dist and abs(zc - pc) <= dist for (pr, pc) in all_zones)

    def pick_zone(zr, zc, idx):
        # Cycle through zone types: corridor 0=RES, 1=COM, 2=IND, 3=RES
        # Also balance counts
        total = res_count + com_count + ind_count + 1
        r_frac = res_count / total
        c_frac = com_count / total
        i_frac = ind_count / total
        # Target: 50% RES, 25% COM, 25% IND
        if i_frac < 0.20:
            return Tool.INDUSTRIAL
        if c_frac < 0.20:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Process corridors in order
    for cidx, corr in enumerate(corridors):
        wr = corr['wire_row']
        ra = corr['road_above']
        rb = corr['road_below']
        za = corr['zone_above']
        zb = corr['zone_below']

        # Skip corridors far from plant until pop grows
        if cidx >= 2 and obs.city_pop < 100:
            continue
        if cidx >= 3 and obs.city_pop < 300:
            continue

        # Wire cols in this row
        wire_cols_in_row = sorted(c for (r, c) in wire_positions if r == wr)

        # Extend wire from plant_x rightward
        if not wire_cols_in_row:
            # Need to connect from plant: place wire at plant_x in this row
            if em[wr, plant_x + 4]:
                return (Tool.WIRE, plant_x + 4, wr)
        else:
            max_wc = max(wire_cols_in_row)
            min_wc = min(wire_cols_in_row)
            if max_wc < target_reach:
                nc = max_wc + 1
                if 0 <= nc < WORLD_W and (em[wr, nc] or wm[wr, nc]):
                    return (Tool.WIRE, nc, wr)
            # Also extend left toward plant
            if min_wc > plant_x + 4:
                nc = min_wc - 1
                if 0 <= nc < WORLD_W and em[wr, nc]:
                    return (Tool.WIRE, nc, wr)

        if not wire_cols_in_row:
            continue

        wire_cols_set = set(wire_cols_in_row)

        # Build roads above and below wire row
        road_cols_above = set(c for (r, c) in road_positions if r == ra)
        road_cols_below = set(c for (r, c) in road_positions if r == rb)

        for wc in wire_cols_in_row:
            if wc not in road_cols_above and 0 <= ra < WORLD_H and 0 <= wc < WORLD_W:
                if em[ra, wc]:
                    return (Tool.ROAD, wc, ra)
            if wc not in road_cols_below and 0 <= rb < WORLD_H and 0 <= wc < WORLD_W:
                if em[rb, wc]:
                    return (Tool.ROAD, wc, rb)

        # Place zones above and below roads
        # Zone every 4 columns to keep separation
        for wc in wire_cols_in_row:
            if wc % 4 == 0:
                # Zone above road
                if 2 <= za < WORLD_H - 2 and 2 <= wc < WORLD_W - 2:
                    road_nearby_above = any(abs(wc - rc) <= 2 for (r, rc) in road_positions if r == ra)
                    if road_nearby_above and not already_zone_nearby(za, wc) and zone_area_free(za, wc):
                        return (pick_zone(za, wc, cidx), wc, za)
                # Zone below road
                if 2 <= zb < WORLD_H - 2 and 2 <= wc < WORLD_W - 2:
                    road_nearby_below = any(abs(wc - rc) <= 2 for (r, rc) in road_positions if r == rb)
                    if road_nearby_below and not already_zone_nearby(zb, wc) and zone_area_free(zb, wc):
                        return (pick_zone(zb, wc, cidx), wc, zb)

    # Add vertical wire connections between corridors for power distribution
    if obs.city_pop > 50:
        for cidx in range(len(corridors) - 1):
            wr1 = corridors[cidx]['wire_row']
            wr2 = corridors[cidx + 1]['wire_row']
            connect_col = plant_x + 6
            if 0 <= connect_col < WORLD_W:
                for vr in range(min(wr1, wr2), max(wr1, wr2) + 1):
                    if 0 <= vr < WORLD_H and not wm[vr, connect_col] and em[vr, connect_col]:
                        return (Tool.WIRE, connect_col, vr)

    # Add services
    if obs.city_pop > 200:
        fs_x, fs_y = plant_x + 15, 50
        if 2 <= fs_y < WORLD_H - 2 and 2 <= fs_x < WORLD_W - 2:
            if zone_area_free(fs_y, fs_x):
                return (Tool.FIRESTATION, fs_x, fs_y)

    if obs.city_pop > 400:
        ps_x, ps_y = plant_x + 15, 60
        if 2 <= ps_y < WORLD_H - 2 and 2 <= ps_x < WORLD_W - 2:
            if zone_area_free(ps_y, ps_x):
                return (Tool.POLICESTATION, ps_x, ps_y)

    return None

def act(obs, state):
    """
    Improved policy: Two neighborhoods with better zone placement and power.
    Strategy:
    - Place coal power plant early
    - Build a compact road grid (horizontal + vertical)
    - Wire along roads for power distribution
    - Place zones densely near roads with balanced RCI mix
    - Add second power plant for second neighborhood
    """
    tm = obs.tile_map
    step = obs.step

    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    # Use state as a simple step counter / plan index
    if 'plan' not in state:
        state['plan'] = []
        state['plan_idx'] = 0

    # Build plan on first call
    if state['plan_idx'] == 0 and len(state['plan']) == 0:
        plan = []

        # --- Neighborhood 1: centered at (45, 45) ---
        # Coal power plant at (30, 45)
        plan.append((Tool.COALPOWER, 30, 45))

        # Horizontal road grid: rows 40, 46, 52 from x=33 to x=60
        for row in [40, 46, 52]:
            for x in range(33, 63):
                plan.append((Tool.ROAD, x, row))

        # Vertical roads every 6 columns connecting rows 40-52
        for x in range(33, 63, 6):
            for y in range(40, 53):
                plan.append((Tool.ROAD, x, y))

        # Wire along spine row 46 from plant to x=62
        for x in range(33, 63):
            plan.append((Tool.WIRE, x, 46))

        # Vertical wire branches every 6 cols from row 40 to 52
        for x in range(33, 63, 6):
            for y in range(40, 53):
                plan.append((Tool.WIRE, x, y))

        # Zones: place between roads
        # Rows above top road (40): centers at 37, 34, 31
        # Rows below bottom road (52): centers at 55, 58, 61
        # Cols: between vertical roads, centers at 36, 42, 48, 54, 60
        zone_cols = [36, 42, 48, 54, 60]
        zone_rows_above = [37]  # just one row above to keep compact
        zone_rows_below = [55]  # just one row below

        tools_cycle = [Tool.RESIDENTIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.INDUSTRIAL, Tool.RESIDENTIAL]
        ti = 0
        for zr in zone_rows_above + zone_rows_below:
            for zc in zone_cols:
                if 2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3:
                    plan.append((tools_cycle[ti % len(tools_cycle)], zc, zr))
                    ti += 1

        # Middle row zones between roads 40 and 46 (center row 43)
        for zc in zone_cols:
            plan.append((tools_cycle[ti % len(tools_cycle)], zc, 43))
            ti += 1
        # Between roads 46 and 52 (center row 49)
        for zc in zone_cols:
            plan.append((tools_cycle[ti % len(tools_cycle)], zc, 49))
            ti += 1

        # --- Neighborhood 2: centered at (85, 45) ---
        # Second coal power plant at (70, 45)
        plan.append((Tool.COALPOWER, 70, 45))

        # Horizontal roads: rows 40, 46, 52 from x=73 to x=100
        for row in [40, 46, 52]:
            for x in range(73, 103):
                plan.append((Tool.ROAD, x, row))

        # Vertical roads every 6 cols
        for x in range(73, 103, 6):
            for y in range(40, 53):
                plan.append((Tool.ROAD, x, y))

        # Wire along spine row 46
        for x in range(73, 103):
            plan.append((Tool.WIRE, x, 46))

        # Vertical wire branches
        for x in range(73, 103, 6):
            for y in range(40, 53):
                plan.append((Tool.WIRE, x, y))

        # Zones for neighborhood 2
        zone_cols2 = [76, 82, 88, 94, 100]
        ti2 = 2  # offset tool cycle
        for zr in [37, 55]:
            for zc in zone_cols2:
                if 2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3:
                    plan.append((tools_cycle[ti2 % len(tools_cycle)], zc, zr))
                    ti2 += 1
        for zc in zone_cols2:
            plan.append((tools_cycle[ti2 % len(tools_cycle)], zc, 43))
            ti2 += 1
        for zc in zone_cols2:
            plan.append((tools_cycle[ti2 % len(tools_cycle)], zc, 49))
            ti2 += 1

        # Add extra wire to ensure zones get powered
        # Wire rows 40 and 52 for both neighborhoods
        for x in range(33, 103):
            plan.append((Tool.WIRE, x, 40))
            plan.append((Tool.WIRE, x, 52))

        # Connect two plants with wire along row 46
        for x in range(31, 73):
            plan.append((Tool.WIRE, x, 46))

        state['plan'] = plan

    # Execute plan step by step
    idx = state['plan_idx']
    plan = state['plan']

    if idx < len(plan):
        action = plan[idx]
        state['plan_idx'] = idx + 1
        tool, x, y = action
        # Validate coords
        if 0 <= x < WORLD_W and 0 <= y < WORLD_H:
            return action
        else:
            state['plan_idx'] = idx + 1
            return None

    # After plan is done, reactively fill in gaps
    # Try to place more zones where there's road and wire access
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    road_pos = set(zip(*np.where(rm))) if np.any(rm) else set()
    wire_pos = set(zip(*np.where(wm))) if np.any(wm) else set()
    zone_pos = set(zip(*np.where(resm | comm | indm)))

    def has_road_access(zy, zx, radius=3):
        for dr in range(-radius, radius + 1):
            for dc in range(-radius, radius + 1):
                rr, rc = zy + dr, zx + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if (rr, rc) in road_pos:
                        return True
        return False

    def has_wire_access(zy, zx, radius=5):
        for dr in range(-radius, radius + 1):
            for dc in range(-radius, radius + 1):
                rr, rc = zy + dr, zx + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if (rr, rc) in wire_pos or pm[rr, rc]:
                        return True
        return False

    def near_existing_zone(zy, zx):
        for (zpr, zpc) in zone_pos:
            if abs(zy - zpr) < 3 and abs(zx - zpc) < 3:
                return True
        return False

    def pick_tool():
        t = max(total_zones, 1)
        if com_count / t < 0.3:
            return Tool.COMMERCIAL
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Scan for empty spots near roads/wires
    for y in range(5, WORLD_H - 5, 3):
        for x in range(5, WORLD_W - 5, 3):
            if not near_existing_zone(y, x):
                # Check 3x3 area is clear
                clear = True
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if not em[y + dr, x + dc] and (y + dr, x + dc) not in zone_pos:
                            clear = False
                            break
                if clear and has_road_access(y, x) and has_wire_access(y, x):
                    return (pick_tool(), x, y)

    return None

def act(obs, state):
    tm = obs.tile_map
    cx, cy = WORLD_W // 2, WORLD_H // 2

    # Initialize lightweight state
    if "phase" not in state:
        state["phase"] = "plant"
        state["wire_dy"] = 0      # how far we've extended wire vertically
        state["road_dy"] = 0      # how far we've extended road vertically
        state["zone_turns"] = 0

    phase = state["phase"]

    # --- Phase 1: Place coal power plant ---
    if phase == "plant":
        state["phase"] = "wire_right"
        return (Tool.COALPOWER, cx - 3, cy)

    # --- Phase 2: Extend wire from plant to spine column cx ---
    if phase == "wire_right":
        # Wire: cx-2, cx-1, cx  at row cy
        for wx in [cx - 2, cx - 1, cx]:
            tid = tm[cy, wx]
            if wire_mask(tm)[cy, wx] or plant_mask(tm)[cy, wx]:
                continue
            return (Tool.WIRE, wx, cy)
        state["phase"] = "spine"
        state["spine_dy"] = -15

    # --- Phase 3: Build vertical wire+road spine ---
    if phase == "spine":
        dy = state["spine_dy"]
        if dy <= 15:
            state["spine_dy"] = dy + 1
            y = cy + dy
            if 0 <= y < WORLD_H:
                # wire at cx, road at cx+1 and cx-1
                # Check what's missing
                if not wire_mask(tm)[y, cx] and not plant_mask(tm)[y, cx]:
                    return (Tool.WIRE, cx, y)
                if cx + 1 < WORLD_W and not road_mask(tm)[y, cx + 1]:
                    return (Tool.ROAD, cx + 1, y)
                if cx - 1 >= 0 and not road_mask(tm)[y, cx - 1]:
                    return (Tool.ROAD, cx - 1, y)
        else:
            state["phase"] = "zones"

    # --- Phase 4: Closed-loop zone + road placement ---
    # Read current map state
    res = res_mask(tm)
    com = com_mask(tm)
    ind = ind_mask(tm)
    emp = empty_mask(tm)
    road = road_mask(tm)
    wire = wire_mask(tm)
    plant = plant_mask(tm)

    powered = wire | plant

    # Expand road access: find powered+road adjacent cells that are empty, place road
    # Neighbor helpers
    def neighbors(mask):
        n = np.zeros((WORLD_H, WORLD_W), bool)
        n[1:, :] |= mask[:-1, :]
        n[:-1, :] |= mask[1:, :]
        n[:, 1:] |= mask[:, :-1]
        n[:, :-1] |= mask[:, 1:]
        return n

    nbr_road = neighbors(road)
    nbr_powered = neighbors(powered)
    nbr_res = neighbors(res)
    nbr_com = neighbors(com)
    nbr_ind = neighbors(ind)
    nbr_zone = neighbors(res | com | ind)

    step = obs.step

    # Priority 1: If there are unpowered areas near the spine, extend wire
    # along the spine extensions
    spine_col = cx
    # Try to extend spine wire if needed
    for dy in range(-15, 16):
        y = cy + dy
        if 0 <= y < WORLD_H:
            if not wire_mask(tm)[y, spine_col] and not plant_mask(tm)[y, spine_col]:
                # Check if adjacent cell is powered
                if (y > 0 and powered[y-1, spine_col]) or (y < WORLD_H-1 and powered[y+1, spine_col]):
                    return (Tool.WIRE, spine_col, y)

    # Priority 2: Extend road along both sides of spine if missing
    for dy in range(-15, 16):
        y = cy + dy
        if 0 <= y < WORLD_H:
            for rx in [cx - 1, cx + 1]:
                if 0 <= rx < WORLD_W and not road_mask(tm)[y, rx]:
                    # Only place if adjacent to existing road
                    if nbr_road[y, rx]:
                        return (Tool.ROAD, rx, y)

    # Priority 3: Place zones adjacent to roads AND powered areas
    # Find candidates: empty cells near roads and power
    zone_cand = emp & nbr_road & nbr_powered

    if zone_cand.any():
        ys, xs = np.where(zone_cand)
        # Score candidates: prefer closer to spine center
        scores = np.abs(xs - cx) + np.abs(ys - cy)
        # Also prefer near existing zones for density
        near_zone = nbr_zone[ys, xs].astype(int) * 5
        final_scores = scores - near_zone
        best_idx = np.argmin(final_scores)
        bx, by = int(xs[best_idx]), int(ys[best_idx])

        # Choose zone type based on population balance
        rp = obs.res_pop
        cp = obs.com_pop
        ip = obs.ind_pop
        total = rp + cp + ip + 1

        # Aim for ~50% res, ~30% com, ~20% ind
        if rp / total < 0.5:
            tool = Tool.RESIDENTIAL
        elif cp / total < 0.3:
            tool = Tool.COMMERCIAL
        elif ip / total < 0.2:
            tool = Tool.INDUSTRIAL
        else:
            tool = Tool.RESIDENTIAL

        return (tool, bx, by)

    # Priority 4: Extend wire to reach empty powered-adjacent areas
    wire_cand = emp & nbr_powered & ~nbr_road
    if wire_cand.any():
        ys, xs = np.where(wire_cand)
        scores = np.abs(xs - cx) + np.abs(ys - cy)
        best_idx = np.argmin(scores)
        return (Tool.WIRE, int(xs[best_idx]), int(ys[best_idx]))

    # Priority 5: Extend road to reach new empty areas
    road_cand = emp & nbr_road
    if road_cand.any():
        ys, xs = np.where(road_cand)
        scores = np.abs(xs - cx) + np.abs(ys - cy)
        best_idx = np.argmin(scores)
        return (Tool.ROAD, int(xs[best_idx]), int(ys[best_idx]))

    return None

def act(obs, state):
    """
    Closed-loop reactive policy combining best ideas from both parents.
    Each step reads the current map and decides what to place next.

    Strategy:
    - Place coal plant near center-left
    - Grow wire spine vertically from plant (reading current wire extent)
    - Build road column adjacent to wire (reading current road extent)
    - Place zones (RES/COM/IND) flanking road, spacing every 3 rows
    - Connect zones laterally to power via wires
    - Expand to second cluster if population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    cx, cy = 60, 50  # map center

    # Power plant position (center of 3x3 footprint)
    plant_x, plant_y = cx - 8, cy

    # Wire spine column just right of plant
    wire_col = plant_x + 4   # col 56
    road_col = wire_col + 1  # col 57

    # Zone columns flanking road/wire
    left_zone_col = wire_col - 4   # col 52
    right_zone_col = road_col + 4  # col 61

    # Vertical range for infrastructure - grows with population
    pop = obs.city_pop
    half_span = 8 + min(15, pop // 60)
    y_min = max(2, cy - half_span)
    y_max = min(WORLD_H - 3, cy + half_span)

    # --- Phase 0: Place coal power plant if missing ---
    has_plant = np.any(pm)
    if not has_plant:
        return (Tool.COALPOWER, plant_x, plant_y)

    # --- Helper: check if tile is within plant footprint ---
    def in_plant(y, x):
        return (plant_y - 1 <= y <= plant_y + 1) and (plant_x - 1 <= x <= plant_x + 1)

    # --- Phase 1: Extend wire spine vertically ---
    # Find current wire extent in wire_col
    wire_rows = [r for r in range(WORLD_H) if wm[r, wire_col]]

    if not wire_rows:
        # Place first wire adjacent to plant (same row as plant)
        if not in_plant(plant_y, wire_col):
            return (Tool.WIRE, wire_col, plant_y)
    else:
        cur_min = min(wire_rows)
        cur_max = max(wire_rows)
        # Extend downward
        if cur_max < y_max:
            nr = cur_max + 1
            if 0 <= nr < WORLD_H and not in_plant(nr, wire_col):
                return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if cur_min > y_min:
            nr = cur_min - 1
            if 0 <= nr < WORLD_H and not in_plant(nr, wire_col):
                return (Tool.WIRE, wire_col, nr)

    # Re-read wire rows after possible placement
    wire_rows = sorted(r for r in range(WORLD_H) if wm[r, wire_col])
    wire_rows_set = set(wire_rows)

    # --- Phase 2: Build road column adjacent to wire ---
    road_rows = set(r for r in range(WORLD_H) if rm[r, road_col])
    for wr in wire_rows:
        if wr not in road_rows and 0 <= road_col < WORLD_W:
            if not in_plant(wr, road_col):
                return (Tool.ROAD, road_col, wr)

    road_rows = set(r for r in range(WORLD_H) if rm[r, road_col])

    # --- Phase 3: Place zones flanking road/wire ---
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)
    all_zone_m = res_m | com_m | ind_m

    res_count = int(np.sum(res_m))
    com_count = int(np.sum(com_m))
    ind_count = int(np.sum(ind_m))

    def zone_area_free(zr, zc):
        """Check 3x3 area around zone center is empty."""
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def zone_exists_near(zr, zc):
        """Check if any zone tile exists within 2 cells."""
        r0 = max(0, zr - 2)
        r1 = min(WORLD_H, zr + 3)
        c0 = max(0, zc - 2)
        c1 = min(WORLD_W, zc + 3)
        return bool(np.any(all_zone_m[r0:r1, c0:c1]))

    # Place zones every 3 rows where wire and road coverage exist
    for zr in range(y_min, y_max + 1, 3):
        # Need wire nearby and road nearby
        wire_nearby = any(abs(zr - wr) <= 1 for wr in wire_rows_set)
        road_nearby = any(abs(zr - rr) <= 2 for rr in road_rows)
        if not (wire_nearby and road_nearby):
            continue

        for zc in [left_zone_col, right_zone_col]:
            if not (0 <= zr < WORLD_H and 0 <= zc < WORLD_W):
                continue
            if zone_exists_near(zr, zc):
                continue
            if not zone_area_free(zr, zc):
                continue
            # Zone type selection: aim for ~50% res, ~25% com, ~25% ind
            total = res_count + com_count + ind_count
            if total == 0 or res_count * 2 <= total:
                return (Tool.RESIDENTIAL, zc, zr)
            elif com_count * 4 < res_count:
                return (Tool.COMMERCIAL, zc, zr)
            elif ind_count * 4 < res_count:
                return (Tool.INDUSTRIAL, zc, zr)
            else:
                return (Tool.RESIDENTIAL, zc, zr)

    # --- Phase 4: Extend wire laterally to left zones ---
    for wr in wire_rows:
        for wc in range(wire_col - 1, left_zone_col, -1):
            if 0 <= wc < WORLD_W and em[wr, wc] and not in_plant(wr, wc):
                return (Tool.WIRE, wc, wr)

    # --- Phase 5: Extend road laterally to right zones ---
    for wr in wire_rows:
        for rc in range(road_col + 1, right_zone_col):
            if 0 <= rc < WORLD_W and em[wr, rc]:
                return (Tool.ROAD, rc, wr)

    # --- Phase 6: Second expansion cluster if population growing ---
    if pop > 200:
        wire_col2 = road_col + 8   # col 65
        road_col2 = wire_col2 + 1  # col 66
        right_zone_col2 = road_col2 + 4  # col 70

        # Wire horizontal connector from wire_col to wire_col2 at center row
        connector_row = cy
        for wc in range(wire_col + 1, wire_col2 + 1):
            if em[connector_row, wc] and 0 <= wc < WORLD_W:
                return (Tool.WIRE, wc, connector_row)

        # Vertical wire spine 2
        wire_rows2 = sorted(r for r in range(WORLD_H) if wm[r, wire_col2])
        if not wire_rows2:
            if wm[connector_row, wire_col2 - 1]:
                return (Tool.WIRE, wire_col2, connector_row)
        else:
            cur_min2 = min(wire_rows2)
            cur_max2 = max(wire_rows2)
            if cur_max2 < y_max:
                return (Tool.WIRE, wire_col2, cur_max2 + 1)
            if cur_min2 > y_min:
                return (Tool.WIRE, wire_col2, cur_min2 - 1)

        wire_rows2 = sorted(r for r in range(WORLD_H) if wm[r, wire_col2])
        road_rows2 = set(r for r in range(WORLD_H) if rm[r, road_col2])
        for wr in wire_rows2:
            if wr not in road_rows2 and 0 <= road_col2 < WORLD_W:
                return (Tool.ROAD, road_col2, wr)

        road_rows2 = set(r for r in range(WORLD_H) if rm[r, road_col2])
        wire_rows2_set = set(wire_rows2)
        for zr in range(y_min, y_max + 1, 3):
            wire_nearby2 = any(abs(zr - wr) <= 1 for wr in wire_rows2_set)
            road_nearby2 = any(abs(zr - rr) <= 2 for rr in road_rows2)
            if not (wire_nearby2 and road_nearby2):
                continue
            for zc in [right_zone_col2]:
                if not (0 <= zr < WORLD_H and 0 <= zc < WORLD_W):
                    continue
                if zone_exists_near(zr, zc):
                    continue
                if not zone_area_free(zr, zc):
                    continue
                return (Tool.RESIDENTIAL, zc, zr)

    # --- Phase 7: Add second coal plant if powered zones insufficient ---
    if pop > 400 and obs.powered_zones < 10:
        plant2_x, plant2_y = cx + 15, cy
        if not np.any(pm[plant2_y - 1:plant2_y + 2, plant2_x - 1:plant2_x + 2]):
            # Wire connector to plant2
            for wc in range(wire_col + 1, plant2_x):
                if em[cy, wc]:
                    return (Tool.WIRE, wc, cy)
            return (Tool.COALPOWER, plant2_x, plant2_y)

    return None

def act(obs, state):
    """
    Improved city builder with:
    - Two separate neighborhoods (left and right clusters)
    - Better wire routing (along zone rows, not just spine)
    - Roads every 4 rows to give more zones road access
    - Balanced RCI mix
    - Multiple power plants
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Two cluster anchors
    # Left cluster: power plant at (20, 45), zones spread right/up/down
    # Right cluster: power plant at (75, 55), zones spread left/up/down
    P1X, P1Y = 20, 45
    P2X, P2Y = 75, 55

    plant_ys, plant_xs = np.where(pm)
    has_plant1 = False
    has_plant2 = False
    for py_, px_ in zip(plant_ys.tolist(), plant_xs.tolist()):
        if abs(px_ - P1X) < 8 and abs(py_ - P1Y) < 8:
            has_plant1 = True
        if abs(px_ - P2X) < 8 and abs(py_ - P2Y) < 8:
            has_plant2 = True

    # Step 1: Place power plants first
    if not has_plant1:
        return (Tool.COALPOWER, P1X, P1Y)
    if not has_plant2:
        return (Tool.COALPOWER, P2X, P2Y)

    res_ys, res_xs = np.where(resm)
    com_ys, com_xs = np.where(comm)
    ind_ys, ind_xs = np.where(indm)
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    zone_set = set(zip(
        np.concatenate([res_ys, com_ys, ind_ys]).tolist(),
        np.concatenate([res_xs, com_xs, ind_xs]).tolist()
    ))

    def pick_tool():
        t = max(total_zones, 1)
        r = res_count / t
        c = com_count / t
        i_frac = ind_count / t
        # Target: 50% res, 25% com, 25% ind
        if c < 0.22:
            return Tool.COMMERCIAL
        if i_frac < 0.22:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    # Build infrastructure for each cluster
    # Cluster 1: plant at P1X,P1Y; wire spine at P1Y; roads at P1Y-3, P1Y+3
    # Cluster 2: plant at P2X,P2Y; wire spine at P2Y; roads at P2Y-3, P2Y+3

    clusters = [
        {'px': P1X, 'py': P1Y, 'x_start': P1X+3, 'x_end': min(P1X+45, 65)},
        {'px': P2X, 'py': P2Y, 'x_start': max(P2X-45, 66), 'x_end': min(P2X+20, WORLD_W-4)},
    ]

    for cl in clusters:
        px, py = cl['px'], cl['py']
        x_start, x_end = cl['x_start'], cl['x_end']
        spine_y = py

        # Wire spine horizontally
        for wx in range(min(x_start, px+2), x_end+1):
            wy = spine_y
            if not in_bounds(wx, wy):
                break
            if not bool(wm[wy, wx]) and not bool(pm[wy, wx]):
                if bool(em[wy, wx]):
                    return (Tool.WIRE, wx, wy)
                break  # blocked, stop

        # Vertical wire branches every 6 cols
        for bx in range(x_start, x_end+1, 6):
            if not in_bounds(bx, spine_y):
                continue
            if not (bool(wm[spine_y, bx]) or bool(pm[spine_y, bx])):
                continue
            for sign in [-1, 1]:
                for dy in range(1, 10):
                    wy2 = spine_y + sign * dy
                    if not in_bounds(bx, wy2):
                        break
                    if bool(wm[wy2, bx]) or bool(pm[wy2, bx]):
                        continue
                    if bool(em[wy2, bx]):
                        return (Tool.WIRE, bx, wy2)
                    break

        # Road rows at spine_y-3 and spine_y+3
        for road_offset in [-3, 3]:
            ry = spine_y + road_offset
            xs_r = range(x_start, x_end+1) if x_start < x_end else range(x_end, x_start+1)
            for rx in xs_r:
                if not in_bounds(rx, ry):
                    break
                if not bool(rm[ry, rx]) and not bool(pm[ry, rx]) and not bool(wm[ry, rx]):
                    if bool(em[ry, rx]):
                        return (Tool.ROAD, rx, ry)
                    break

        # Additional road rows at spine_y-6 and spine_y+6
        for road_offset in [-6, 6]:
            ry = spine_y + road_offset
            if not in_bounds(x_start, ry):
                continue
            xs_r = range(x_start, x_end+1) if x_start < x_end else range(x_end, x_start+1)
            for rx in xs_r:
                if not in_bounds(rx, ry):
                    break
                if not bool(rm[ry, rx]) and not bool(pm[ry, rx]) and not bool(wm[ry, rx]):
                    if bool(em[ry, rx]):
                        return (Tool.ROAD, rx, ry)
                    break

        # Vertical connector roads every 6 cols between outer roads
        for vc in range(x_start, x_end+1, 6):
            for vr in range(spine_y-6, spine_y+7):
                if not in_bounds(vc, vr):
                    continue
                if not bool(rm[vr, vc]) and not bool(pm[vr, vc]) and not bool(wm[vr, vc]):
                    if bool(em[vr, vc]):
                        return (Tool.ROAD, vc, vr)

    # Zone placement near roads and wires
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        step_hash = int(obs.step * 17 + int(obs.city_pop * 3)) % max(len(cxs), 1)
        for offset in range(min(len(cxs), 60)):
            k = (step_hash + offset * 11) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # Services
    if obs.city_pop > 150:
        for fx, fy in [(P1X+3, P1Y-10), (P2X-3, P2Y+10)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 200:
        for fx, fy in [(P1X+3, P1Y+10), (P2X-3, P2Y-10)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.POLICESTATION, fx, fy)

    # Fallback: extend roads from existing road frontier
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = int(obs.step * 13) % max(len(road_xs2), 1)
        rx_s, ry_s = int(road_xs2[step_k]), int(road_ys2[step_k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx_s + dx2, ry_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wires
    wire_ys2, wire_xs2 = np.where(wm)
    if len(wire_xs2) > 0:
        step_k2 = int(obs.step * 7) % max(len(wire_xs2), 1)
        wx_s, wy_s = int(wire_xs2[step_k2]), int(wire_ys2[step_k2])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = wx_s + dx2, wy_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop policy: each step reads the map and decides the next action
    based on what's actually there. Uses a phase counter for high-level flow.

    Strategy:
    - Place coal plant at (25, 50)
    - Extend wire rightward from plant to x=95
    - Build road at y=48 and y=52 from x=20 to x=95
    - Place zones (3x3 centered) above/below roads
    - Branch wires up/down to reach zones
    """
    tm = obs.tile_map
    step = obs.step

    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    # Key layout constants
    PLANT_X, PLANT_Y = 25, 50
    WIRE_ROW = 50
    ROAD_ROW_TOP = 47
    ROAD_ROW_BOT = 53
    WIRE_START = 28   # just right of plant footprint (plant is 3x3, center 25,50 => cols 23-27)
    WIRE_END = 96
    ROAD_START = 20
    ROAD_END = 96
    # Zone columns every 6 steps starting from 23
    ZONE_COLS = list(range(23, 97, 6))
    # Zone rows: above top road and below bot road
    ZONE_ROWS_ABOVE = [44, 41, 38]
    ZONE_ROWS_BELOW = [56, 59, 62]

    # Helper: is area free for 3x3 zone centered at (cx, cy)?
    def zone_area_free(cx, cy):
        for dy in [-1, 0, 1]:
            for dx in [-1, 0, 1]:
                r, c = cy + dy, cx + dx
                if r < 0 or r >= WORLD_H or c < 0 or c >= WORLD_W:
                    return False
                if not em[r, c]:
                    return False
        return True

    # Helper: pick zone type based on current counts
    def pick_zone(zc, zr):
        rc = np.sum(resm)
        cc = np.sum(comm)
        ic = np.sum(indm)
        total = rc + cc + ic + 1
        if cc / total < 0.25:
            return Tool.COMMERCIAL
        elif ic / total < 0.25:
            return Tool.INDUSTRIAL
        else:
            return Tool.RESIDENTIAL

    # Phase 1: Ensure coal plant exists
    if not np.any(pm):
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    # Phase 2: Extend wire rightward along WIRE_ROW
    # Find rightmost wire in wire row
    wire_in_row = np.where(wm[WIRE_ROW, :])[0]
    if len(wire_in_row) == 0:
        rightmost_wire = WIRE_START - 1
    else:
        rightmost_wire = int(wire_in_row.max())

    if rightmost_wire < WIRE_END:
        nc = rightmost_wire + 1
        # Don't place wire on top of plant
        if not pm[WIRE_ROW, nc]:
            return (Tool.WIRE, nc, WIRE_ROW)

    # Phase 3: Build top road (ROAD_ROW_TOP)
    road_top_cols = np.where(rm[ROAD_ROW_TOP, :])[0]
    if len(road_top_cols) == 0:
        rightmost_road_top = ROAD_START - 1
    else:
        rightmost_road_top = int(road_top_cols.max())
    if rightmost_road_top < ROAD_END:
        nc = rightmost_road_top + 1
        return (Tool.ROAD, nc, ROAD_ROW_TOP)

    # Phase 4: Build bottom road (ROAD_ROW_BOT)
    road_bot_cols = np.where(rm[ROAD_ROW_BOT, :])[0]
    if len(road_bot_cols) == 0:
        rightmost_road_bot = ROAD_START - 1
    else:
        rightmost_road_bot = int(road_bot_cols.max())
    if rightmost_road_bot < ROAD_END:
        nc = rightmost_road_bot + 1
        return (Tool.ROAD, nc, ROAD_ROW_BOT)

    # Phase 5: Place vertical connecting roads between road rows at zone columns
    for zc in ZONE_COLS:
        if 0 <= zc < WORLD_W:
            for conn_r in range(ROAD_ROW_TOP, ROAD_ROW_BOT + 1):
                if not rm[conn_r, zc] and not wm[conn_r, zc] and not pm[conn_r, zc]:
                    return (Tool.ROAD, zc, conn_r)

    # Phase 6: Place zones above top road, checking road access
    for zr in ZONE_ROWS_ABOVE:
        for zc in ZONE_COLS:
            if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                # Check if already has zone nearby
                already = (
                    np.any(resm[max(0,zr-2):zr+3, max(0,zc-2):zc+3]) or
                    np.any(comm[max(0,zr-2):zr+3, max(0,zc-2):zc+3]) or
                    np.any(indm[max(0,zr-2):zr+3, max(0,zc-2):zc+3])
                )
                if already:
                    continue
                # Need road access: road within 2 rows
                road_near = np.any(rm[max(0,zr-2):zr+3, max(0,zc-2):zc+3])
                # Need wire access: wire within 4 tiles
                wire_near = np.any(wm[max(0,zr-4):zr+5, max(0,zc-4):zc+5])
                if road_near and wire_near and zone_area_free(zc, zr):
                    return (pick_zone(zc, zr), zc, zr)

    # Phase 7: Place zones below bottom road
    for zr in ZONE_ROWS_BELOW:
        for zc in ZONE_COLS:
            if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                already = (
                    np.any(resm[max(0,zr-2):zr+3, max(0,zc-2):zc+3]) or
                    np.any(comm[max(0,zr-2):zr+3, max(0,zc-2):zc+3]) or
                    np.any(indm[max(0,zr-2):zr+3, max(0,zc-2):zc+3])
                )
                if already:
                    continue
                road_near = np.any(rm[max(0,zr-2):zr+3, max(0,zc-2):zc+3])
                wire_near = np.any(wm[max(0,zr-4):zr+5, max(0,zc-4):zc+5])
                if road_near and wire_near and zone_area_free(zc, zr):
                    return (pick_zone(zc, zr), zc, zr)

    # Phase 8: Extend wire branches vertically to reach zones that lack wire
    # For above zones: wire from WIRE_ROW upward at zone columns
    for zc in ZONE_COLS:
        if 0 <= zc < WORLD_W:
            # Wire branch upward to reach top zone rows
            for wr in range(WIRE_ROW - 1, ZONE_ROWS_ABOVE[-1] - 1, -1):
                if 0 <= wr < WORLD_H:
                    if wm[wr, zc] or pm[wr, zc]:
                        break  # already has wire/plant here, stop
                    if rm[wr, zc]:
                        continue  # road, skip but continue looking upward... actually roads don't conduct
                    if em[wr, zc]:
                        return (Tool.WIRE, zc, wr)
                    else:
                        break  # blocked

    for zc in ZONE_COLS:
        if 0 <= zc < WORLD_W:
            # Wire branch downward
            for wr in range(WIRE_ROW + 1, ZONE_ROWS_BELOW[-1] + 2):
                if 0 <= wr < WORLD_H:
                    if wm[wr, zc] or pm[wr, zc]:
                        break
                    if rm[wr, zc]:
                        continue
                    if em[wr, zc]:
                        return (Tool.WIRE, zc, wr)
                    else:
                        break

    # Phase 9: If city growing well, expand further out
    if obs.city_pop > 50:
        extra_above = [35, 32, 29]
        extra_below = [65, 68, 71]
        for zr in extra_above + extra_below:
            for zc in ZONE_COLS:
                if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                    already = (
                        np.any(resm[max(0,zr-2):zr+3, max(0,zc-2):zc+3]) or
                        np.any(comm[max(0,zr-2):zr+3, max(0,zc-2):zc+3]) or
                        np.any(indm[max(0,zr-2):zr+3, max(0,zc-2):zc+3])
                    )
                    if already:
                        continue
                    road_near = np.any(rm[max(0,zr-3):zr+4, max(0,zc-3):zc+4])
                    wire_near = np.any(wm[max(0,zr-5):zr+6, max(0,zc-5):zc+6])
                    if road_near and wire_near and zone_area_free(zc, zr):
                        return (pick_zone(zc, zr), zc, zr)

    # Phase 10: Add more roads for connectivity
    # Extend horizontal roads further if needed
    for road_row in [ROAD_ROW_TOP, ROAD_ROW_BOT]:
        road_cols = np.where(rm[road_row, :])[0]
        if len(road_cols) > 0:
            rmax = int(road_cols.max())
            if rmax < 100:
                return (Tool.ROAD, rmax + 1, road_row)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy.
    Reads current map each step to decide next action.
    Strategy:
    - Place coal plant at fixed location
    - Build vertical wire spine from plant
    - Build road column adjacent to wire
    - Place zones on both sides, with lateral wire/road connections
    - Expand vertically and add second cluster when pop grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    cx, cy = 60, 50  # map center

    # Plant location
    plant_cx, plant_cy = 54, 50

    # Wire spine column (3 right of plant center)
    wire_col = plant_cx + 4   # col 58
    road_col = wire_col + 2   # col 60

    # Zone columns
    left_zone_col = wire_col - 3   # col 55
    right_zone_col = road_col + 3  # col 63

    has_plant = np.any(pm)

    # Phase 1: Place coal power plant
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Gather current state
    wire_positions = set(zip(*np.where(wm))) if np.any(wm) else set()
    road_positions = set(zip(*np.where(rm))) if np.any(rm) else set()
    res_positions = set(zip(*np.where(res_m))) if np.any(res_m) else set()
    com_positions = set(zip(*np.where(com_m))) if np.any(com_m) else set()
    ind_positions = set(zip(*np.where(ind_m))) if np.any(ind_m) else set()
    all_zones = res_positions | com_positions | ind_positions

    res_count = len(res_positions)
    com_count = len(com_positions)
    ind_count = len(ind_positions)

    # Dynamic vertical span based on population
    base_span = 10
    extra_span = min(25, obs.city_pop // 40)
    target_span = base_span + extra_span
    tmin = max(2, cy - target_span)
    tmax = min(WORLD_H - 3, cy + target_span)

    # Wire rows in wire_col
    wire_rows_in_col = sorted(r for (r, c) in wire_positions if c == wire_col)

    # Phase 2: Extend wire spine vertically
    if not wire_rows_in_col:
        # Place first wire adjacent to plant
        for try_r in [plant_cy, plant_cy - 1, plant_cy + 1]:
            if 0 <= try_r < WORLD_H and em[try_r, wire_col]:
                return (Tool.WIRE, wire_col, try_r)
    else:
        min_wr = min(wire_rows_in_col)
        max_wr = max(wire_rows_in_col)

        # Extend downward first
        if max_wr < tmax:
            nr = max_wr + 1
            if 0 < nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if min_wr > tmin:
            nr = min_wr - 1
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    if not wire_rows_in_col:
        return None

    wire_rows_set = set(wire_rows_in_col)
    road_rows_in_col = sorted(r for (r, c) in road_positions if c == road_col)
    road_rows_set = set(road_rows_in_col)

    # Phase 3: Build road column (matching wire column coverage)
    for wr in wire_rows_in_col:
        if wr not in road_rows_set and 0 <= road_col < WORLD_W:
            if em[wr, road_col]:
                return (Tool.ROAD, road_col, wr)

    # Helper: check if 3x3 area around center is clear
    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def already_zone_nearby(zr, zc, zones):
        return any(abs(zr - pr) <= 1 and abs(zc - pc) <= 1 for (pr, pc) in zones)

    # Phase 4: Place zones adjacent to road/wire
    # Use every other wire row to space zones apart
    for zr in sorted(wire_rows_in_col):
        road_nearby = any(abs(zr - rr) <= 2 for rr in road_rows_set)
        if not road_nearby:
            continue

        for zc in [left_zone_col, right_zone_col]:
            if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                if not already_zone_nearby(zr, zc, all_zones) and zone_area_free(zr, zc):
                    # Decide zone type: aim ~50% res, ~25% com, ~25% ind
                    if res_count == 0:
                        return (Tool.RESIDENTIAL, zc, zr)
                    elif ind_count * 4 < res_count:
                        return (Tool.INDUSTRIAL, zc, zr)
                    elif com_count * 4 < res_count:
                        return (Tool.COMMERCIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

    # Phase 5: Lateral wires from spine to left zones
    for wr in wire_rows_in_col:
        for wc in range(wire_col - 1, max(left_zone_col - 1, 0), -1):
            if 0 <= wc < WORLD_W and em[wr, wc]:
                return (Tool.WIRE, wc, wr)

    # Phase 6: Lateral roads from road col to right zones
    for wr in wire_rows_in_col:
        for rc in range(road_col + 1, min(right_zone_col + 2, WORLD_W)):
            if 0 <= rc < WORLD_W and em[wr, rc]:
                return (Tool.ROAD, rc, wr)

    # Phase 7: Second cluster to the right when pop >= 200
    if obs.city_pop >= 200:
        wire_col2 = road_col + 8   # col 68
        road_col2 = wire_col2 + 2  # col 70
        left_zone_col2 = wire_col2 - 3   # col 65
        right_zone_col2 = road_col2 + 3  # col 73

        wire_rows2 = sorted(r for (r, c) in wire_positions if c == wire_col2)
        road_rows2 = set(r for (r, c) in road_positions if c == road_col2)

        # Connect wire horizontally to second column at cy
        if not wire_rows2:
            # First build horizontal bridge at plant_cy level
            for wc in range(wire_col + 1, wire_col2 + 1):
                if em[plant_cy, wc] or wm[plant_cy, wc]:
                    if em[plant_cy, wc]:
                        return (Tool.WIRE, wc, plant_cy)
        else:
            # Extend wire2 spine
            min_wr2 = min(wire_rows2)
            max_wr2 = max(wire_rows2)
            if max_wr2 < tmax:
                nr = max_wr2 + 1
                if 0 < nr < WORLD_H and em[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > tmin:
                nr = min_wr2 - 1
                if 0 <= nr < WORLD_H and em[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)

            # Road2
            for wr in wire_rows2:
                if wr not in road_rows2 and 0 <= road_col2 < WORLD_W:
                    if em[wr, road_col2]:
                        return (Tool.ROAD, road_col2, wr)

            # Zones around second cluster
            for zr in sorted(wire_rows2):
                road_nearby2 = any(abs(zr - rr) <= 2 for rr in road_rows2)
                if not road_nearby2:
                    continue
                for zc in [left_zone_col2, right_zone_col2]:
                    if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                        if not already_zone_nearby(zr, zc, all_zones) and zone_area_free(zr, zc):
                            if ind_count * 4 < res_count:
                                return (Tool.INDUSTRIAL, zc, zr)
                            elif com_count * 4 < res_count:
                                return (Tool.COMMERCIAL, zc, zr)
                            else:
                                return (Tool.RESIDENTIAL, zc, zr)

            # Lateral wires to left zone2
            for wr in wire_rows2:
                for wc in range(wire_col2 - 1, max(left_zone_col2 - 1, 0), -1):
                    if 0 <= wc < WORLD_W and em[wr, wc]:
                        return (Tool.WIRE, wc, wr)

            # Lateral roads to right zone2
            for wr in wire_rows2:
                for rc in range(road_col2 + 1, min(right_zone_col2 + 2, WORLD_W)):
                    if 0 <= rc < WORLD_W and em[wr, rc]:
                        return (Tool.ROAD, rc, wr)

    # Phase 8: Third cluster to the left for high pop
    if obs.city_pop >= 400:
        wire_col3 = wire_col - 8   # col 50
        road_col3 = wire_col3 - 2  # col 48
        left_zone_col3 = road_col3 - 3  # col 45
        right_zone_col3 = wire_col3 + 3  # col 53

        wire_rows3 = sorted(r for (r, c) in wire_positions if c == wire_col3)
        road_rows3 = set(r for (r, c) in road_positions if c == road_col3)

        if not wire_rows3:
            for wc in range(wire_col - 1, wire_col3 - 1, -1):
                if em[plant_cy, wc] or wm[plant_cy, wc]:
                    if em[plant_cy, wc]:
                        return (Tool.WIRE, wc, plant_cy)
        else:
            min_wr3 = min(wire_rows3)
            max_wr3 = max(wire_rows3)
            if max_wr3 < tmax:
                nr = max_wr3 + 1
                if 0 < nr < WORLD_H and em[nr, wire_col3]:
                    return (Tool.WIRE, wire_col3, nr)
            if min_wr3 > tmin:
                nr = min_wr3 - 1
                if 0 <= nr < WORLD_H and em[nr, wire_col3]:
                    return (Tool.WIRE, wire_col3, nr)

            for wr in wire_rows3:
                if wr not in road_rows3 and 0 <= road_col3 < WORLD_W:
                    if em[wr, road_col3]:
                        return (Tool.ROAD, road_col3, wr)

            for zr in sorted(wire_rows3):
                road_nearby3 = any(abs(zr - rr) <= 2 for rr in road_rows3)
                if not road_nearby3:
                    continue
                for zc in [left_zone_col3, right_zone_col3]:
                    if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                        if not already_zone_nearby(zr, zc, all_zones) and zone_area_free(zr, zc):
                            if ind_count * 4 < res_count:
                                return (Tool.INDUSTRIAL, zc, zr)
                            elif com_count * 4 < res_count:
                                return (Tool.COMMERCIAL, zc, zr)
                            else:
                                return (Tool.RESIDENTIAL, zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map each step to decide placement.
    Strategy: Build a compact cluster around a coal plant.
    - Place coal plant first
    - Grow wire from plant outward to cover zones
    - Build road spine adjacent to wire
    - Place zones where both wire and road are nearby
    - Adapt to what's already on the map each step
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # Fixed anchor for the cluster
    PLANT_X, PLANT_Y = 50, 50

    # Phase 1: Ensure coal power plant exists
    if not np.any(pm):
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    # Find actual plant center (use first plant tile found, estimate center)
    plant_rows, plant_cols = np.where(pm)
    if len(plant_rows) > 0:
        # Plant footprint is 3x3, take centroid
        PLANT_Y = int(np.mean(plant_rows))
        PLANT_X = int(np.mean(plant_cols))

    # Layout columns
    # Wire spine: 3 cols right of plant center
    WIRE_COL = PLANT_X + 4
    # Road spine: 2 cols right of wire
    ROAD_COL = WIRE_COL + 2
    # Zone columns
    LEFT_ZONE_COL = WIRE_COL - 3   # zones left of wire, powered via wire
    RIGHT_ZONE_COL = ROAD_COL + 3  # zones right of road, road access

    # Row range for building
    ROW_MIN = max(2, PLANT_Y - 20)
    ROW_MAX = min(WORLD_H - 3, PLANT_Y + 20)

    # Count zones
    res_count = int(np.sum(res_m))
    com_count = int(np.sum(com_m))
    ind_count = int(np.sum(ind_m))
    total_zones = res_count + com_count + ind_count

    # --- Phase 2: Grow wire spine from plant outward ---
    # Wire should cover ROW_MIN to ROW_MAX on WIRE_COL
    # Find gaps in wire spine
    for r in range(PLANT_Y, ROW_MAX + 1):
        if 0 <= r < WORLD_H and 0 <= WIRE_COL < WORLD_W:
            if not wm[r, WIRE_COL] and not pm[r, WIRE_COL]:
                return (Tool.WIRE, WIRE_COL, r)
    for r in range(PLANT_Y - 1, ROW_MIN - 1, -1):
        if 0 <= r < WORLD_H and 0 <= WIRE_COL < WORLD_W:
            if not wm[r, WIRE_COL] and not pm[r, WIRE_COL]:
                return (Tool.WIRE, WIRE_COL, r)

    # Connect plant to wire spine with a horizontal wire bridge
    # Plant right edge is PLANT_X+1, wire col is PLANT_X+4
    for c in range(PLANT_X + 2, WIRE_COL + 1):
        if 0 <= c < WORLD_W and not wm[PLANT_Y, c] and not pm[PLANT_Y, c]:
            return (Tool.WIRE, c, PLANT_Y)

    # --- Phase 3: Build road spine ---
    # Road on ROAD_COL for same rows as wire spine
    wire_rows = [r for r in range(ROW_MIN, ROW_MAX + 1)
                 if 0 <= r < WORLD_H and wm[r, WIRE_COL]]
    for r in wire_rows:
        if 0 <= ROAD_COL < WORLD_W and not rm[r, ROAD_COL]:
            return (Tool.ROAD, ROAD_COL, r)

    # --- Phase 4: Lateral wires from spine to left zone column ---
    # For rows that have wire, extend wire leftward to LEFT_ZONE_COL
    for r in wire_rows:
        for c in range(WIRE_COL - 1, LEFT_ZONE_COL - 2, -1):
            if 0 <= c < WORLD_W:
                if not wm[r, c] and not pm[r, c]:
                    return (Tool.WIRE, c, r)

    # --- Phase 5: Lateral roads from road spine to right zone column ---
    road_rows = [r for r in range(ROW_MIN, ROW_MAX + 1)
                 if 0 <= r < WORLD_H and rm[r, ROAD_COL]]
    for r in road_rows:
        for c in range(ROAD_COL + 1, RIGHT_ZONE_COL + 2):
            if 0 <= c < WORLD_W and not rm[r, c]:
                return (Tool.ROAD, c, r)

    # --- Helper: check zone placement ---
    def can_place_zone(zr, zc):
        """Check if 3x3 area is valid and doesn't overlap plant."""
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if pm[rr, rc]:
                    return False
        return True

    def zone_occupied(zr, zc):
        """Check if any zone tile exists in 3x3."""
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if res_m[rr, rc] or com_m[rr, rc] or ind_m[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=3):
        r0, r1 = max(0, zr - radius), min(WORLD_H, zr + radius + 1)
        c0, c1 = max(0, zc - radius), min(WORLD_W, zc + radius + 1)
        return bool(np.any(wm[r0:r1, c0:c1]))

    def has_road_nearby(zr, zc, radius=3):
        r0, r1 = max(0, zr - radius), min(WORLD_H, zr + radius + 1)
        c0, c1 = max(0, zc - radius), min(WORLD_W, zc + radius + 1)
        return bool(np.any(rm[r0:r1, c0:c1]))

    def pick_zone_type():
        """Balance zone types: ~50% RES, 25% COM, 25% IND."""
        t = total_zones + 1
        if ind_count * 4 < t:
            return Tool.INDUSTRIAL
        elif com_count * 4 < t:
            return Tool.COMMERCIAL
        else:
            return Tool.RESIDENTIAL

    # --- Phase 6: Place zones at left column (wire-powered) ---
    zone_rows = list(range(ROW_MIN + 1, ROW_MAX, 3))
    for zr in zone_rows:
        zc = LEFT_ZONE_COL
        if can_place_zone(zr, zc) and not zone_occupied(zr, zc):
            if has_wire_nearby(zr, zc) and has_road_nearby(zr, zc):
                return (pick_zone_type(), zc, zr)

    # --- Phase 7: Place zones at right column (road-served) ---
    for zr in zone_rows:
        zc = RIGHT_ZONE_COL
        if can_place_zone(zr, zc) and not zone_occupied(zr, zc):
            if has_wire_nearby(zr, zc) and has_road_nearby(zr, zc):
                t = total_zones + 1
                if com_count * 3 < t:
                    return (Tool.COMMERCIAL, zc, zr)
                else:
                    return (Tool.RESIDENTIAL, zc, zr)

    # --- Phase 8: If city growing, add more zones further out ---
    if obs.city_pop > 100 or total_zones > 5:
        EXT_LEFT = LEFT_ZONE_COL - 4
        EXT_RIGHT = RIGHT_ZONE_COL + 4
        EXT_ROW_MIN = max(2, PLANT_Y - 30)
        EXT_ROW_MAX = min(WORLD_H - 3, PLANT_Y + 30)
        ext_zone_rows = list(range(EXT_ROW_MIN, EXT_ROW_MAX, 3))

        # Extend wire spine further
        for r in range(ROW_MAX + 1, EXT_ROW_MAX + 1):
            if 0 <= r < WORLD_H and not wm[r, WIRE_COL] and not pm[r, WIRE_COL]:
                return (Tool.WIRE, WIRE_COL, r)
        for r in range(ROW_MIN - 1, EXT_ROW_MIN - 1, -1):
            if 0 <= r < WORLD_H and not wm[r, WIRE_COL] and not pm[r, WIRE_COL]:
                return (Tool.WIRE, WIRE_COL, r)

        # Extend road spine
        all_wire_rows = [r for r in range(EXT_ROW_MIN, EXT_ROW_MAX + 1)
                         if 0 <= r < WORLD_H and wm[r, WIRE_COL]]
        for r in all_wire_rows:
            if not rm[r, ROAD_COL]:
                return (Tool.ROAD, ROAD_COL, r)

        # Extend lateral wires to far left
        for r in all_wire_rows:
            for c in range(WIRE_COL - 1, EXT_LEFT - 2, -1):
                if 0 <= c < WORLD_W and not wm[r, c] and not pm[r, c]:
                    return (Tool.WIRE, c, r)

        # Extend lateral roads to far right
        all_road_rows = [r for r in range(EXT_ROW_MIN, EXT_ROW_MAX + 1)
                         if 0 <= r < WORLD_H and rm[r, ROAD_COL]]
        for r in all_road_rows:
            for c in range(ROAD_COL + 1, EXT_RIGHT + 2):
                if 0 <= c < WORLD_W and not rm[r, c]:
                    return (Tool.ROAD, c, r)

        # Place extended zones
        for zr in ext_zone_rows:
            for zc in [EXT_LEFT, EXT_RIGHT]:
                if can_place_zone(zr, zc) and not zone_occupied(zr, zc):
                    if has_wire_nearby(zr, zc, 4) and has_road_nearby(zr, zc, 4):
                        return (Tool.RESIDENTIAL, zc, zr)

    # --- Phase 9: Nuclear power if large city ---
    if obs.city_pop > 500:
        nuke_x = PLANT_X - 8
        nuke_y = PLANT_Y + 8
        if 1 <= nuke_y < WORLD_H - 1 and 1 <= nuke_x < WORLD_W - 1:
            if not np.any(pm[nuke_y-1:nuke_y+2, nuke_x-1:nuke_x+2]):
                return (Tool.NUCLEARPOWER, nuke_x, nuke_y)
            # Connect nuke to wire
            for c in range(nuke_x + 2, WIRE_COL):
                if not wm[nuke_y, c] and not pm[nuke_y, c]:
                    return (Tool.WIRE, c, nuke_y)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map each step and reacts to current state.
    Strategy:
    - Place coal power plant at fixed anchor.
    - Grow wire spine FROM the plant by finding the frontier of existing wires.
    - Grow road column adjacent to wire spine, also from frontier.
    - Place zones where both power (wire nearby) and road access exist.
    - All decisions based on current tile_map scan, not precomputed plan.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    # Fixed anchor positions
    PLANT_X, PLANT_Y = 50, 50
    WIRE_COL = PLANT_X + 4   # wire spine column
    ROAD_COL = WIRE_COL + 2  # road column

    # Step 1: Ensure power plant exists
    if not np.any(pm):
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    # Find actual plant center
    plant_rows, plant_cols = np.where(pm)
    if len(plant_rows) > 0:
        PLANT_Y = int(np.median(plant_rows))
        PLANT_X = int(np.median(plant_cols))
        WIRE_COL = PLANT_X + 4
        ROAD_COL = WIRE_COL + 2

    # Step 2: Connect plant to wire spine if not already connected
    # Check if wire spine has any tiles
    wire_in_col = np.where(wm[:, WIRE_COL])[0]

    if len(wire_in_col) == 0:
        # Place first wire adjacent to plant
        wy = PLANT_Y
        if 0 <= wy < WORLD_H and 0 <= WIRE_COL < WORLD_W:
            return (Tool.WIRE, WIRE_COL, wy)

    # Step 3: Extend wire spine vertically from current frontier
    if len(wire_in_col) > 0:
        wire_min = int(wire_in_col.min())
        wire_max = int(wire_in_col.max())

        # Target range: plant_y +/- 20
        target_min = max(1, PLANT_Y - 20)
        target_max = min(WORLD_H - 2, PLANT_Y + 20)

        # Also bridge any gaps in the wire column
        for r in range(wire_min, wire_max + 1):
            if not wm[r, WIRE_COL]:
                return (Tool.WIRE, WIRE_COL, r)

        # Extend downward
        if wire_max < target_max:
            nr = wire_max + 1
            if nr < WORLD_H:
                return (Tool.WIRE, WIRE_COL, nr)

        # Extend upward
        if wire_min > target_min:
            nr = wire_min - 1
            if nr >= 0:
                return (Tool.WIRE, WIRE_COL, nr)

    # Step 4: Build road column alongside wire spine
    # For each row with a wire, place road if missing
    wire_rows = set(np.where(wm[:, WIRE_COL])[0].tolist())
    road_in_col = set(np.where(rm[:, ROAD_COL])[0].tolist())

    if 0 <= ROAD_COL < WORLD_W:
        for r in sorted(wire_rows):
            if r not in road_in_col:
                return (Tool.ROAD, ROAD_COL, r)

    # Step 5: Lateral wires from spine to left zone column
    LEFT_ZONE_COL = WIRE_COL - 3
    if LEFT_ZONE_COL >= 1:
        for r in sorted(wire_rows):
            # Check if lateral wire exists at this row to left zone
            for c in range(WIRE_COL - 1, LEFT_ZONE_COL - 1, -1):
                if 0 <= c < WORLD_W:
                    # Don't overwrite plant
                    if pm[r, c]:
                        break
                    if not wm[r, c] and not pm[r, c]:
                        return (Tool.WIRE, c, r)

    # Step 6: Now place zones where both wire and road are accessible
    res_pos = list(zip(*np.where(res_mask(tm)))) if np.any(res_mask(tm)) else []
    com_pos = list(zip(*np.where(com_mask(tm)))) if np.any(com_mask(tm)) else []
    ind_pos = list(zip(*np.where(ind_mask(tm)))) if np.any(ind_mask(tm)) else []
    all_zone_pos = res_pos + com_pos + ind_pos

    res_count = len(res_pos)
    com_count = len(com_pos)
    ind_count = len(ind_pos)

    def zone_area_clear(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if pm[rr, rc]:
                    return False
        return True

    def zone_exists_near(zr, zc):
        return any(abs(zr - pr) <= 2 and abs(zc - pc) <= 2 for (pr, pc) in all_zone_pos)

    def wire_near(zr, zc, radius=3):
        r0, r1 = max(0, zr - radius), min(WORLD_H, zr + radius + 1)
        c0, c1 = max(0, zc - radius), min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def road_near(zr, zc, radius=3):
        r0, r1 = max(0, zr - radius), min(WORLD_H, zr + radius + 1)
        c0, c1 = max(0, zc - radius), min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    def pick_zone_type():
        total = res_count + com_count + ind_count + 1
        if ind_count / total < 0.2:
            return Tool.INDUSTRIAL
        elif com_count / total < 0.25:
            return Tool.COMMERCIAL
        else:
            return Tool.RESIDENTIAL

    # Zone rows spaced by 3 around plant
    zone_rows = list(range(max(2, PLANT_Y - 18), min(WORLD_H - 2, PLANT_Y + 19), 3))

    RIGHT_ZONE_COL = ROAD_COL + 3

    for zr in zone_rows:
        # Left zone (wire-powered)
        zc = LEFT_ZONE_COL
        if 1 <= zc < WORLD_W - 1 and 1 <= zr < WORLD_H - 1:
            if not zone_exists_near(zr, zc) and zone_area_clear(zr, zc):
                if wire_near(zr, zc) and road_near(zr, zc):
                    return (pick_zone_type(), zc, zr)

        # Right zone (road-powered, needs wire too)
        zc = RIGHT_ZONE_COL
        if 1 <= zc < WORLD_W - 1 and 1 <= zr < WORLD_H - 1:
            if not zone_exists_near(zr, zc) and zone_area_clear(zr, zc):
                if road_near(zr, zc):
                    # Need lateral wire to right zone too
                    if wire_near(zr, zc):
                        return (pick_zone_type(), zc, zr)
                    else:
                        # Lay wire toward right zone
                        for c in range(WIRE_COL + 1, zc + 2):
                            if 0 <= c < WORLD_W and not wm[zr, c] and not pm[zr, c]:
                                return (Tool.WIRE, c, zr)

    # Step 7: Lateral roads to right zone col
    for r in sorted(road_in_col):
        for c in range(ROAD_COL + 1, RIGHT_ZONE_COL + 2):
            if 0 <= c < WORLD_W and not rm[r, c]:
                return (Tool.ROAD, c, r)

    # Step 8: If city is growing, extend further
    if obs.city_pop > 100:
        ext_target_min = max(1, PLANT_Y - 30)
        ext_target_max = min(WORLD_H - 2, PLANT_Y + 30)

        if len(wire_in_col) > 0:
            if int(wire_in_col.max()) < ext_target_max:
                return (Tool.WIRE, WIRE_COL, int(wire_in_col.max()) + 1)
            if int(wire_in_col.min()) > ext_target_min:
                return (Tool.WIRE, WIRE_COL, int(wire_in_col.min()) - 1)

    # Step 9: Add second power plant if underpowered
    if obs.city_pop > 300 and obs.powered_zones < (res_count + com_count + ind_count) // 2:
        nuke_x = PLANT_X - 8
        nuke_y = PLANT_Y + 10
        if 1 <= nuke_y < WORLD_H - 1 and 1 <= nuke_x < WORLD_W - 1:
            if not np.any(pm[nuke_y-1:nuke_y+2, nuke_x-1:nuke_x+2]):
                return (Tool.COALPOWER, nuke_x, nuke_y)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy.
    Changes from parent:
    - Use a horizontal road spine instead of vertical wire spine
    - Place power plant near left edge, wire runs horizontally across map
    - Zones placed above and below the horizontal road/wire spine
    - More compact zone placement with tighter spacing
    - React to what's actually on the map each step
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    # Center row for our horizontal spine
    spine_row = 50
    plant_x, plant_y = 10, spine_row

    has_plant = np.any(pm)

    # Phase 1: place coal power plant
    if not has_plant:
        return (Tool.COALPOWER, plant_x, plant_y)

    # Recompute positions from map each step
    wire_cols_on_spine = sorted(c for (r, c) in zip(*np.where(wm)) if r == spine_row) if np.any(wm) else []
    road_cols_on_spine = sorted(c for (r, c) in zip(*np.where(rm)) if r == spine_row) if np.any(rm) else []

    res_pos = set(zip(*np.where(res_mask(tm)))) if np.any(res_mask(tm)) else set()
    com_pos = set(zip(*np.where(com_mask(tm)))) if np.any(com_mask(tm)) else set()
    ind_pos = set(zip(*np.where(ind_mask(tm)))) if np.any(ind_mask(tm)) else set()
    all_zones = res_pos | com_pos | ind_pos

    res_count = len(res_pos)
    com_count = len(com_pos)
    ind_count = len(ind_pos)

    # Wire spine extends horizontally from plant
    wire_spine_start = plant_x + 4  # right of plant
    wire_spine_end = min(110, wire_spine_start + 60 + min(40, obs.city_pop // 10))

    # Road spine is one row below wire spine
    road_row = spine_row + 1
    # Also a road row above
    road_row_above = spine_row - 1

    # Zone rows: above and below
    zone_row_above = spine_row - 4  # zone centers above spine
    zone_row_below = spine_row + 4  # zone centers below spine

    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def already_zone_nearby(zr, zc, dist=3):
        return any(abs(zr - pr) <= dist and abs(zc - pc) <= dist for (pr, pc) in all_zones)

    def pick_zone(zr, zc):
        # Aim for ~50% RES, ~25% COM, ~25% IND
        if ind_count == 0 or (ind_count * 3 < res_count and zr >= spine_row):
            return Tool.INDUSTRIAL
        if com_count == 0 or (com_count * 3 < res_count):
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Phase 2: extend wire spine horizontally
    if not wire_cols_on_spine:
        # Start wire right next to plant
        return (Tool.WIRE, plant_x + 4, spine_row)

    max_wc = max(wire_cols_on_spine)
    min_wc = min(wire_cols_on_spine)

    if max_wc < wire_spine_end:
        nc = max_wc + 1
        if 0 <= nc < WORLD_W:
            return (Tool.WIRE, nc, spine_row)

    wire_cols_set = set(wire_cols_on_spine)

    # Phase 3: build road row just below wire spine
    road_cols_below = set(c for (r, c) in zip(*np.where(rm)) if r == road_row) if np.any(rm) else set()
    for wc in wire_cols_on_spine:
        if wc not in road_cols_below and 0 <= road_row < WORLD_H:
            if em[road_row, wc]:
                return (Tool.ROAD, wc, road_row)

    # Phase 4: build road row just above wire spine
    road_cols_above = set(c for (r, c) in zip(*np.where(rm)) if r == road_row_above) if np.any(rm) else set()
    for wc in wire_cols_on_spine:
        if wc not in road_cols_above and 0 <= road_row_above < WORLD_H:
            if em[road_row_above, wc]:
                return (Tool.ROAD, road_row_above, wc)

    # Phase 5: place zones above and below spine
    # Zones every 4 columns along spine
    zone_spacing = 4
    for wc in range(wire_spine_start + 2, wire_spine_end - 1, zone_spacing):
        # Check road access: need road within 2 tiles
        has_road_access = (wc in road_cols_below or wc in road_cols_above or
                          any(abs(wc - rc) <= 2 for rc in road_cols_below) or
                          any(abs(wc - rc) <= 2 for rc in road_cols_above))
        if not has_road_access:
            continue

        # Try zone below spine
        zr = zone_row_below
        zc = wc
        if (2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3 and
                not already_zone_nearby(zr, zc) and zone_area_free(zr, zc)):
            return (pick_zone(zr, zc), zc, zr)

        # Try zone above spine
        zr = zone_row_above
        zc = wc
        if (2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3 and
                not already_zone_nearby(zr, zc) and zone_area_free(zr, zc)):
            return (pick_zone(zr, zc), zc, zr)

    # Phase 6: add a second row of zones further out if pop growing
    if obs.city_pop > 150:
        zone_row_below2 = spine_row + 8
        zone_row_above2 = spine_row - 8
        # Need vertical road connectors
        for wc in range(wire_spine_start + 2, wire_spine_end - 1, zone_spacing):
            if wc not in road_cols_below:
                continue
            # Build road vertically from road_row down to zone_row_below2
            road_col_set = set(c for (r, c) in zip(*np.where(rm)) if c == wc) if np.any(rm) else set()
            for rr in range(road_row, zone_row_below2 + 1):
                if 0 <= rr < WORLD_H and rr not in road_col_set:
                    if em[rr, wc]:
                        return (Tool.ROAD, wc, rr)

            # Zone at second level below
            zr, zc = zone_row_below2, wc
            if (2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3 and
                    not already_zone_nearby(zr, zc) and zone_area_free(zr, zc)):
                return (pick_zone(zr, zc), zc, zr)

            # Build road vertically from road_row_above up to zone_row_above2
            for rr in range(zone_row_above2, road_row_above):
                if 0 <= rr < WORLD_H and rr not in road_col_set:
                    if em[rr, wc]:
                        return (Tool.ROAD, wc, rr)

            zr, zc = zone_row_above2, wc
            if (2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3 and
                    not already_zone_nearby(zr, zc) and zone_area_free(zr, zc)):
                return (pick_zone(zr, zc), zc, zr)

    # Phase 7: add services
    if obs.city_pop > 300:
        fire_x = wire_spine_start + 10
        fire_y = spine_row + 12
        if 2 <= fire_y <= WORLD_H - 3 and 2 <= fire_x <= WORLD_W - 3:
            if zone_area_free(fire_y, fire_x):
                return (Tool.FIRESTATION, fire_x, fire_y)

    if obs.city_pop > 500:
        police_x = wire_spine_start + 20
        police_y = spine_row - 12
        if 2 <= police_y <= WORLD_H - 3 and 2 <= police_x <= WORLD_W - 3:
            if zone_area_free(police_y, police_x):
                return (Tool.POLICESTATION, police_x, police_y)

    return None

def act(obs, state):
    """
    Hybrid policy combining:
    - Parent A's dual-cluster layout with mixed zones and road grid
    - Parent B's closed-loop sensing and incremental building
    Strategy:
    1. Build a coal power plant
    2. Wire spine from plant
    3. Road grid adjacent to wire
    4. Place RES/COM/IND zones in a compact cluster
    5. Expand reactively based on population
    """
    tm = obs.tile_map
    step = obs.step

    # City center
    cx, cy = 60, 50

    # Use state to track a pre-planned sequence first, then switch to reactive
    if "plan" not in state:
        plan = []

        # Power plant at (cx-10, cy-2) - left of center
        px, py = cx - 10, cy - 2
        plan.append((Tool.COALPOWER, px, py))

        # Wire spine: horizontal from plant rightward, then vertical
        # Horizontal wire from plant to cx+1
        for x in range(px + 2, cx + 2):
            plan.append((Tool.WIRE, x, py))

        # Vertical wire spine at cx+1, from cy-14 to cy+14
        for y in range(cy - 14, cy + 15):
            plan.append((Tool.WIRE, cx + 1, y))

        # Road column at cx+2 (adjacent to wire spine)
        for y in range(cy - 14, cy + 15):
            plan.append((Tool.ROAD, cx + 2, y))

        # Horizontal roads every 3 rows to connect zones
        for dy in range(-12, 13, 3):
            for x in range(cx - 8, cx + 10):
                plan.append((Tool.ROAD, x, cy + dy))

        # Left zone column: RES at cx-4, various rows
        # Right zone column: COM/IND at cx+6, various rows
        zone_rows = list(range(cy - 12, cy + 13, 3))
        for i, yr in enumerate(zone_rows):
            # Left column: residential
            plan.append((Tool.RESIDENTIAL, cx - 4, yr))
            # Right column: commercial or industrial alternating
            if i % 3 == 0:
                plan.append((Tool.COMMERCIAL, cx + 6, yr))
            elif i % 3 == 1:
                plan.append((Tool.INDUSTRIAL, cx + 6, yr))
            else:
                plan.append((Tool.RESIDENTIAL, cx + 6, yr))

        # Additional lateral wires to reach left zones
        for yr in zone_rows:
            for x in range(cx - 3, cx + 1):
                plan.append((Tool.WIRE, x, yr))

        # Second power plant for more coverage (right side)
        px2, py2 = cx + 15, cy - 2
        plan.append((Tool.COALPOWER, px2, py2))
        # Wire from second plant leftward to spine
        for x in range(cx + 2, px2):
            plan.append((Tool.WIRE, x, py2))
        # Vertical wire from second plant
        for y in range(cy - 14, cy + 15):
            plan.append((Tool.WIRE, cx + 14, y))
        # Road at cx+15
        for y in range(cy - 14, cy + 15):
            plan.append((Tool.ROAD, cx + 15, y))

        # More residential zones on far right
        for yr in zone_rows:
            plan.append((Tool.RESIDENTIAL, cx + 18, yr))
            # Lateral wire to reach far right zones
            for x in range(cx + 15, cx + 17):
                plan.append((Tool.WIRE, x, yr))

        state["plan"] = plan
        state["idx"] = 0

    # Execute plan
    if state["idx"] < len(state["plan"]):
        action = state["plan"][state["idx"]]
        state["idx"] += 1
        # Validate coords
        tool, x, y = action
        if 0 <= x < WORLD_W and 0 <= y < WORLD_H:
            return action
        return None

    # Reactive phase: expand based on current city state
    res_count = int(np.sum(res_mask(tm)))
    com_count = int(np.sum(com_mask(tm)))
    ind_count = int(np.sum(ind_mask(tm)))
    em = empty_mask(tm)
    rm = road_mask(tm)
    wm = wire_mask(tm)

    # Find road positions
    road_ys, road_xs = np.where(rm)

    if len(road_xs) == 0:
        return None

    # Pick tool based on balance (3 res : 1 com : 1 ind)
    if com_count * 3 < res_count:
        tool = Tool.COMMERCIAL
    elif ind_count * 3 < res_count:
        tool = Tool.INDUSTRIAL
    else:
        tool = Tool.RESIDENTIAL

    # Find empty 3x3 areas adjacent to roads
    # Check candidate zone centers
    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    # Try to place zones near existing roads with wire access
    all_zones = res_mask(tm) | com_mask(tm) | ind_mask(tm)

    # Candidate centers: offset from roads
    tried = 0
    for i in range(0, len(road_xs), max(1, len(road_xs) // 50)):
        ry, rx = int(road_ys[i]), int(road_xs[i])
        for dc in [-3, 3, -6, 6]:
            zc, zr = rx + dc, ry
            if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                if zone_area_free(zr, zc):
                    # Check wire nearby
                    wire_near = False
                    for wr in range(max(0, zr - 3), min(WORLD_H, zr + 4)):
                        for wc in range(max(0, zc - 3), min(WORLD_W, zc + 4)):
                            if wm[wr, wc]:
                                wire_near = True
                                break
                        if wire_near:
                            break
                    if wire_near:
                        return (tool, zc, zr)
        tried += 1
        if tried > 30:
            break

    # If no wired area found, extend wire from existing wire toward empty road areas
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        # Find empty tile adjacent to wire
        for i in range(0, len(wire_xs), max(1, len(wire_xs) // 20)):
            wy, wx = int(wire_ys[i]), int(wire_xs[i])
            for dy, dx in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                ny, nx = wy + dy, wx + dx
                if 0 <= ny < WORLD_H and 0 <= nx < WORLD_W and em[ny, nx]:
                    # Extend wire toward zone areas
                    return (Tool.WIRE, nx, ny)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map every step to decide placement
    - Single coal power plant, vertical wire spine, roads on both sides
    - Places zones adjacent to roads, powers via wire spine
    - Expands vertically based on current state
    - Balanced RCI mix
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Fixed anchor: plant left of center, wire spine 4 cols right
    plant_cx, plant_cy = 50, 50
    wire_col = plant_cx + 5   # col 55: vertical wire spine
    road_col_L = wire_col - 1  # col 54
    road_col_R = wire_col + 1  # col 56
    zone_col_L = wire_col - 5  # col 50
    zone_col_R = wire_col + 5  # col 60

    has_plant = np.any(pm)
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Connect plant to wire spine with a horizontal wire if needed
    # Check if wire at (plant_cy, wire_col) exists
    # We need a wire bridge from plant to spine
    # Plant occupies 3x3 around plant_cx,plant_cy
    # Wire bridge: row plant_cy, cols plant_cx+2 .. wire_col
    for bridge_x in range(plant_cx + 2, wire_col):
        if in_bounds(bridge_x, plant_cy):
            if not wm[plant_cy, bridge_x] and not pm[plant_cy, bridge_x]:
                if em[plant_cy, bridge_x]:
                    return (Tool.WIRE, bridge_x, plant_cy)
                # If blocked, try row above/below
                for dy in [-1, 1]:
                    ny = plant_cy + dy
                    if in_bounds(bridge_x, ny) and em[ny, bridge_x]:
                        return (Tool.WIRE, bridge_x, ny)

    # Gather current state
    wire_positions = set(zip(*np.where(wm))) if np.any(wm) else set()
    road_positions = set(zip(*np.where(rm))) if np.any(rm) else set()
    res_cells = set(zip(*np.where(resm)))
    com_cells = set(zip(*np.where(comm)))
    ind_cells = set(zip(*np.where(indm)))
    all_zones = res_cells | com_cells | ind_cells

    res_count = max(int(np.sum(resm)), 1)
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Vertical span grows with pop
    base_span = 12
    extra = min(30, obs.city_pop // 30)
    target_span = base_span + extra
    tmin = max(2, plant_cy - target_span)
    tmax = min(WORLD_H - 3, plant_cy + target_span)

    # Wire spine: extend vertically
    wire_rows = sorted(r for (r, c) in wire_positions if c == wire_col)

    if not wire_rows:
        return (Tool.WIRE, wire_col, plant_cy)

    min_wr = min(wire_rows)
    max_wr = max(wire_rows)

    if max_wr < tmax:
        nr = max_wr + 1
        if in_bounds(wire_col, nr) and (em[nr, wire_col] or wm[nr, wire_col]):
            return (Tool.WIRE, wire_col, nr)
    if min_wr > tmin:
        nr = min_wr - 1
        if in_bounds(wire_col, nr) and (em[nr, wire_col] or wm[nr, wire_col]):
            return (Tool.WIRE, wire_col, nr)

    wire_rows_set = set(wire_rows)

    # Build roads on both sides of wire spine
    road_L = set(r for (r, c) in road_positions if c == road_col_L)
    road_R = set(r for (r, c) in road_positions if c == road_col_R)

    for wr in wire_rows:
        if wr not in road_L and in_bounds(road_col_L, wr) and em[wr, road_col_L]:
            return (Tool.ROAD, road_col_L, wr)
        if wr not in road_R and in_bounds(road_col_R, wr) and em[wr, road_col_R]:
            return (Tool.ROAD, road_col_R, wr)

    # Zone placement helpers
    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not in_bounds(rc, rr):
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def already_zone_nearby(zr, zc, dist=3):
        for (pr, pc) in all_zones:
            if abs(zr - pr) <= dist and abs(zc - pc) <= dist:
                return True
        return False

    def pick_zone(zr):
        # Target ~50% RES, 25% COM, 25% IND
        if ind_count == 0 or (ind_count * 4 < total_zones):
            return Tool.INDUSTRIAL
        if com_count == 0 or (com_count * 4 < total_zones):
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    road_L_set = set(r for (r, c) in road_positions if c == road_col_L)
    road_R_set = set(r for (r, c) in road_positions if c == road_col_R)

    # Place zones adjacent to roads
    for wr in wire_rows:
        if 2 <= wr < WORLD_H - 2:
            road_L_near = any(abs(wr - rr) <= 2 for rr in road_L_set)
            road_R_near = any(abs(wr - rr) <= 2 for rr in road_R_set)

            # Left zone
            if road_L_near:
                zc = zone_col_L
                if in_bounds(zc, wr) and not already_zone_nearby(wr, zc) and zone_area_free(wr, zc):
                    return (pick_zone(wr), zc, wr)

            # Right zone
            if road_R_near:
                zc = zone_col_R
                if in_bounds(zc, wr) and not already_zone_nearby(wr, zc) and zone_area_free(wr, zc):
                    return (pick_zone(wr), zc, wr)

    # Lateral wires to left zones (to power them)
    for wr in wire_rows:
        for wc in range(wire_col - 1, zone_col_L - 1, -1):
            if in_bounds(wc, wr) and em[wr, wc]:
                return (Tool.WIRE, wc, wr)
            elif not em[wr, wc] and not wm[wr, wc]:
                break  # blocked

    # Lateral roads from right road to right zones
    for wr in wire_rows:
        for rc in range(road_col_R + 1, zone_col_R):
            if in_bounds(rc, wr) and em[wr, rc]:
                return (Tool.ROAD, rc, wr)
            elif not em[wr, rc]:
                break

    # Second corridor: expand right if population is growing
    if obs.city_pop > 150:
        wire_col2 = wire_col + 12  # col 67
        road_col2L = wire_col2 - 1
        road_col2R = wire_col2 + 1
        zone_col2L = wire_col2 - 5
        zone_col2R = wire_col2 + 5

        wire_rows2 = sorted(r for (r, c) in wire_positions if c == wire_col2)

        # Connect wire_col to wire_col2 horizontally at a wire row
        if not wire_rows2:
            if wire_rows:
                ref_row = wire_rows[len(wire_rows) // 2]
                for wc in range(wire_col + 1, wire_col2 + 1):
                    if in_bounds(wc, ref_row) and em[ref_row, wc]:
                        return (Tool.WIRE, wc, ref_row)
        else:
            min_wr2 = min(wire_rows2)
            max_wr2 = max(wire_rows2)
            if max_wr2 < tmax:
                nr = max_wr2 + 1
                if in_bounds(wire_col2, nr) and (em[nr, wire_col2] or wm[nr, wire_col2]):
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > tmin:
                nr = min_wr2 - 1
                if in_bounds(wire_col2, nr) and (em[nr, wire_col2] or wm[nr, wire_col2]):
                    return (Tool.WIRE, wire_col2, nr)

            road2L = set(r for (r, c) in road_positions if c == road_col2L)
            road2R = set(r for (r, c) in road_positions if c == road_col2R)
            for wr2 in wire_rows2:
                if wr2 not in road2L and in_bounds(road_col2L, wr2) and em[wr2, road_col2L]:
                    return (Tool.ROAD, road_col2L, wr2)
                if wr2 not in road2R and in_bounds(road_col2R, wr2) and em[wr2, road_col2R]:
                    return (Tool.ROAD, road_col2R, wr2)

            road2L_set = set(r for (r, c) in road_positions if c == road_col2L)
            road2R_set = set(r for (r, c) in road_positions if c == road_col2R)
            for wr2 in wire_rows2:
                if 2 <= wr2 < WORLD_H - 2:
                    if any(abs(wr2 - rr) <= 2 for rr in road2L_set):
                        zc = zone_col2L
                        if in_bounds(zc, wr2) and not already_zone_nearby(wr2, zc) and zone_area_free(wr2, zc):
                            return (pick_zone(wr2), zc, wr2)
                    if any(abs(wr2 - rr) <= 2 for rr in road2R_set):
                        zc = zone_col2R
                        if in_bounds(zc, wr2) and not already_zone_nearby(wr2, zc) and zone_area_free(wr2, zc):
                            return (pick_zone(wr2), zc, wr2)

    # Services once population is sufficient
    if obs.city_pop > 300:
        fs_x, fs_y = wire_col + 8, plant_cy - 8
        if in_bounds(fs_x, fs_y) and zone_area_free(fs_y, fs_x):
            return (Tool.FIRESTATION, fs_x, fs_y)

    if obs.city_pop > 500:
        ps_x, ps_y = wire_col + 8, plant_cy + 8
        if in_bounds(ps_x, ps_y) and zone_area_free(ps_y, ps_x):
            return (Tool.POLICESTATION, ps_x, ps_y)

    return None

def act(obs, state):
    """
    Closed-loop city builder:
    - Reads tile_map each step to decide next action
    - Grows wire/road/zones reactively from what exists
    - Balances RES/COM/IND based on current counts
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Count existing zones
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        r = res_count / t
        c = com_count / t
        i_frac = ind_count / t
        if c < 0.20:
            return Tool.COMMERCIAL
        if i_frac < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def is_empty(x, y):
        return in_bounds(x, y) and bool(em[y, x])

    def is_wire_or_plant(x, y):
        return in_bounds(x, y) and (bool(wm[y, x]) or bool(pm[y, x]))

    def is_road(x, y):
        return in_bounds(x, y) and bool(rm[y, x])

    def zone_clear(zx, zy):
        # Check 3x3 area centered at (zx, zy) is empty
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not bool(em[nr, nc]):
                    return False
        return True

    # ---- Step 1: Place first coal plant if none exists ----
    has_plant = np.any(pm)
    PLANT_X, PLANT_Y = 35, 50
    if not has_plant:
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    # Find plant locations
    plant_ys, plant_xs = np.where(pm)
    # Use the first plant as anchor
    anchor_x = int(plant_xs[0])
    anchor_y = int(plant_ys[0])

    # ---- Step 2: Grow wire rightward from plant ----
    # We want a horizontal wire spine at anchor_y extending right
    # and also left to cover more area
    spine_y = anchor_y

    # Find rightmost wire on spine row
    wire_on_spine = [(c, r) for r, c in zip(*np.where(wm)) if r == spine_y]
    plant_on_spine = [(c, r) for r, c in zip(*np.where(pm)) if r == spine_y]
    all_powered_on_spine = sorted([c for c, r in wire_on_spine] + [c for c, r in plant_on_spine])

    # Extend wire right from plant
    target_right = min(PLANT_X + 50, WORLD_W - 4)
    target_left = max(PLANT_X - 15, 3)

    if all_powered_on_spine:
        rightmost = max(all_powered_on_spine)
        leftmost = min(all_powered_on_spine)
    else:
        rightmost = anchor_x
        leftmost = anchor_x

    # Extend right if not at target
    if rightmost < target_right:
        nx = rightmost + 1
        if in_bounds(nx, spine_y) and not is_wire_or_plant(nx, spine_y):
            return (Tool.WIRE, nx, spine_y)

    # Place second plant if wire is extended enough and no second plant yet
    plant_count = int(np.sum(pm)) // 9  # approximate, each plant is 4x4 tiles approx
    # More reliable: count distinct plant regions
    total_plant_tiles = int(np.sum(pm))
    # Coal power is roughly 4x4 = 16 tiles? Actually 3x3=9
    if total_plant_tiles < 18 and rightmost >= PLANT_X + 40:
        # Place second plant at right end of wire
        p2x = min(rightmost + 2, WORLD_W - 6)
        p2y = spine_y
        # Check area clear
        if is_empty(p2x, p2y):
            return (Tool.COALPOWER, p2x, p2y)

    # ---- Step 3: Build vertical wire branches at intervals ----
    branch_interval = 6
    branch_range_y = 8

    for bx in range(PLANT_X - 2, target_right, branch_interval):
        if not is_wire_or_plant(bx, spine_y):
            continue
        # Grow branch upward
        for dy in range(1, branch_range_y + 1):
            wy = spine_y - dy
            if not in_bounds(bx, wy):
                break
            if not is_wire_or_plant(bx, wy):
                if is_empty(bx, wy):
                    return (Tool.WIRE, bx, wy)
                break
        # Grow branch downward
        for dy in range(1, branch_range_y + 1):
            wy = spine_y + dy
            if not in_bounds(bx, wy):
                break
            if not is_wire_or_plant(bx, wy):
                if is_empty(bx, wy):
                    return (Tool.WIRE, bx, wy)
                break

    # ---- Step 4: Build roads parallel to spine (above and below) ----
    road_offset = 4  # roads 4 rows above/below spine
    road_top = spine_y - road_offset
    road_bot = spine_y + road_offset
    road_left = PLANT_X - 10
    road_right = min(rightmost + 2, WORLD_W - 3)

    # Build horizontal roads
    for ry in [road_top, road_bot]:
        if not in_bounds(0, ry):
            continue
        # Find current rightmost road on this row
        road_on_row = [c for c, r in zip(*[np.where(rm)[1], np.where(rm)[0]]) if r == ry]
        if road_on_row:
            cur_right = max(road_on_row)
            cur_left = min(road_on_row)
        else:
            # Start road near plant
            cur_right = PLANT_X - 1
            cur_left = PLANT_X

        # Extend road right
        if cur_right < road_right:
            nx = cur_right + 1
            if in_bounds(nx, ry) and not bool(pm[ry, nx]) and not is_road(nx, ry):
                return (Tool.ROAD, nx, ry)
        # Extend road left
        if cur_left > road_left:
            nx = cur_left - 1
            if in_bounds(nx, ry) and not bool(pm[ry, nx]) and not is_road(nx, ry):
                return (Tool.ROAD, nx, ry)

    # Vertical connector roads every 6 cols connecting top and bottom road
    for vc in range(road_left, road_right + 1, 6):
        for vr in range(road_top, road_bot + 1):
            if in_bounds(vc, vr) and not is_road(vc, vr) and not bool(pm[vr, vc]):
                return (Tool.ROAD, vc, vr)

    # ---- Step 5: Place zones near roads and wires ----
    # Build neighbor masks reactively from current state
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            shifted_rm = np.zeros((WORLD_H, WORLD_W), dtype=bool)
            r0s = max(0, dy); r1s = min(WORLD_H, WORLD_H + dy)
            c0s = max(0, dx); c1s = min(WORLD_W, WORLD_W + dx)
            r0d = max(0, -dy); r1d = min(WORLD_H, WORLD_H - dy)
            c0d = max(0, -dx); c1d = min(WORLD_W, WORLD_W - dx)
            shifted_rm[r0d:r1d, c0d:c1d] = rm[r0s:r1s, c0s:c1s]
            nbr_road |= shifted_rm

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    power_src = wm | pm
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            r0s = max(0, dy); r1s = min(WORLD_H, WORLD_H + dy)
            c0s = max(0, dx); c1s = min(WORLD_W, WORLD_W + dx)
            r0d = max(0, -dy); r1d = min(WORLD_H, WORLD_H - dy)
            c0d = max(0, -dx); c1d = min(WORLD_W, WORLD_W - dx)
            shifted = np.zeros((WORLD_H, WORLD_W), dtype=bool)
            shifted[r0d:r1d, c0d:c1d] = power_src[r0s:r1s, c0s:c1s]
            nbr_wire |= shifted

    # Find candidate zone centers: empty, near road, near wire, 1+ from edges
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Try candidates in a deterministic but step-varied order
        # Prefer candidates on zone_rows (above/below roads)
        preferred_rows = {road_top - 2, road_top - 5, road_bot + 2, road_bot + 5}
        # Try preferred rows first
        for pr in preferred_rows:
            for k in range(len(cxs)):
                if int(cys[k]) == pr:
                    zx, zy = int(cxs[k]), int(cys[k])
                    if zone_clear(zx, zy):
                        return (pick_tool(), zx, zy)
        # Fallback: scan all candidates
        step_hash = (obs.step * 17) % max(len(cxs), 1)
        for offset in range(min(len(cxs), 80)):
            k = (step_hash + offset * 11) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # ---- Step 6: Services if population warrants ----
    if obs.city_pop > 200:
        # Place fire station
        fx, fy = PLANT_X + 6, spine_y - 10
        if in_bounds(fx, fy) and bool(em[fy, fx]):
            return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 400:
        px2, py2 = PLANT_X + 12, spine_y - 10
        if in_bounds(px2, py2) and bool(em[py2, px2]):
            return (Tool.POLICESTATION, px2, py2)

    # ---- Step 7: Extend roads reactively from existing road ends ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        k = (obs.step * 13) % len(road_xs)
        rx, ry2 = int(road_xs[k]), int(road_ys[k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx + dx2, ry2 + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    New policy: horizontal spine layout instead of vertical.
    - Road runs horizontally through center
    - Wire runs horizontally one row above road
    - Zones placed above and below the spine
    - Coal plant on left side, second plant on right for bigger cities
    - Better R/C/I balance: ~50% R, 30% C, 20% I
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def has_tile(mask, x, y):
        if 0 <= y < WORLD_H and 0 <= x < WORLD_W:
            return bool(mask[y, x])
        return False

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        all_zone = resm | comm | indm
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone[rr, rc]:
                    return False
        return True

    def zone_present(zr, zc):
        all_zone = resm | comm | indm
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone[rr, rc]:
                        return True
        return False

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        # Target: 50% R, 30% C, 20% I
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        if com_count / t < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Horizontal layout:
    # wire_row: horizontal wire
    # road_row: horizontal road (one below wire)
    # upper zones: wire_row - 3
    # lower zones: road_row + 3
    # plant on left side

    wire_row = cy - 1
    road_row = cy        # road just below wire
    upper_zrow = wire_row - 3   # zone centers above
    lower_zrow = road_row + 3   # zone centers below

    # Clamp rows
    wire_row = max(2, min(WORLD_H - 3, wire_row))
    road_row = max(2, min(WORLD_H - 3, road_row))
    upper_zrow = max(2, min(WORLD_H - 3, upper_zrow))
    lower_zrow = max(2, min(WORLD_H - 3, lower_zrow))

    # Plant position: left side, between wire and road rows vertically
    plant_x = cx - 20
    plant_y = cy - 1  # plant center at wire_row area
    plant_x = max(2, min(WORLD_W - 3, plant_x))
    plant_y = max(2, min(WORLD_H - 3, plant_y))

    # Adaptive spine extent based on population
    if obs.city_pop < 50:
        spine_half = 10
    elif obs.city_pop < 200:
        spine_half = 18
    elif obs.city_pop < 500:
        spine_half = 25
    else:
        spine_half = 35

    spine_min = max(2, cx - spine_half)
    spine_max = min(WORLD_W - 3, cx + spine_half)
    spine_range = range(spine_min, spine_max + 1)

    # Phase 0: Place coal power plant
    if not np.any(pm):
        return (Tool.COALPOWER, plant_x, plant_y)

    # Phase 1: Wire spine horizontal row
    for dx in spine_range:
        if not has_tile(wm, dx, wire_row) and not has_tile(pm, dx, wire_row):
            if not has_tile(rm, dx, wire_row):
                return (Tool.WIRE, dx, wire_row)

    # Phase 2: Road row adjacent below wire
    for dx in spine_range:
        if not has_tile(rm, dx, road_row) and not has_tile(pm, dx, road_row):
            if not has_tile(wm, dx, road_row):
                return (Tool.ROAD, dx, road_row)

    # Collect wired cols and road cols
    wire_cols = [c for c in spine_range if wm[wire_row, c]]
    road_cols = [c for c in spine_range if rm[road_row, c]]

    # Phase 3: Place zones above and below spine
    zone_cols = list(range(spine_min + 1, spine_max - 1, 4))

    for zc in zone_cols:
        wire_near = any(abs(zc - wc) <= 3 for wc in wire_cols)
        road_near = any(abs(zc - rc) <= 3 for rc in road_cols)

        if wire_near and road_near:
            # Upper zone (above wire)
            zr = upper_zrow
            if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                return (pick_tool(), zc, zr)

            # Lower zone (below road)
            zr = lower_zrow
            if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                return (pick_tool(), zc, zr)

    # Phase 4: Vertical wires to connect upper zones to wire spine
    for wc in wire_cols:
        for wr in range(wire_row - 1, upper_zrow - 1, -1):
            if 0 <= wr < WORLD_H:
                if wm[wr, wc] or pm[wr, wc]:
                    break
                if em[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                else:
                    break

    # Phase 5: Vertical wires to connect lower zones from road
    for rc in road_cols:
        for wr in range(road_row + 1, lower_zrow + 2):
            if 0 <= wr < WORLD_H:
                if wm[wr, rc] or pm[wr, rc]:
                    break
                if em[wr, rc] and not rm[wr, rc]:
                    return (Tool.WIRE, rc, wr)
                elif rm[wr, rc]:
                    continue
                else:
                    break

    # Phase 6: Second coal plant if population growing
    if obs.city_pop > 200 and np.sum(pm) < 9:
        px2 = cx + 20
        py2 = cy - 1
        px2 = max(2, min(WORLD_W - 3, px2))
        py2 = max(2, min(WORLD_H - 3, py2))
        if em[py2, px2]:
            return (Tool.COALPOWER, px2, py2)

    # Phase 7: Second tier zones further up/down
    if obs.city_pop > 150:
        upper2_zrow = upper_zrow - 4
        lower2_zrow = lower_zrow + 4
        upper2_zrow = max(2, min(WORLD_H - 3, upper2_zrow))
        lower2_zrow = max(2, min(WORLD_H - 3, lower2_zrow))

        for zc in zone_cols:
            wire_near = any(abs(zc - wc) <= 3 for wc in wire_cols)
            road_near = any(abs(zc - rc) <= 3 for rc in road_cols)
            if wire_near and road_near:
                for zr in [upper2_zrow, lower2_zrow]:
                    if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                        r0 = max(0, zr - 5); r1 = min(WORLD_H, zr + 6)
                        c0 = max(0, zc - 5); c1 = min(WORLD_W, zc + 6)
                        if np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1]):
                            if np.any(rm[r0:r1, c0:c1]):
                                return (pick_tool(), zc, zr)

    # Phase 8: Vertical roads for better connectivity
    if obs.city_pop > 100:
        for vc in [spine_min + 1, spine_max - 1]:
            if 0 <= vc < WORLD_W:
                for vr in range(upper_zrow - 1, lower_zrow + 2):
                    if 0 <= vr < WORLD_H and em[vr, vc] and not pm[vr, vc]:
                        return (Tool.ROAD, vc, vr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy.
    Improvements over parent:
    - Use a wider zone layout: two road columns on each side of wire spine
    - Build wire spine horizontally (row-based) instead of vertically for diversity
    - More reactive zone placement: scan for road+wire adjacency dynamically
    - Police/fire stations added for city score boost
    - Expand zone grid more aggressively
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    cx, cy = 60, 50  # map center

    has_plant = np.any(pm)
    has_wire = np.any(wm)
    has_road = np.any(rm)

    # Plant near center
    plant_cx, plant_cy = 55, 50

    # Phase 1: place coal power plant
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Compute current positions
    wire_positions = set(zip(*np.where(wm))) if has_wire else set()
    road_positions = set(zip(*np.where(rm))) if has_road else set()
    res_pos = set(zip(*np.where(res_mask(tm))))
    com_pos = set(zip(*np.where(com_mask(tm))))
    ind_pos = set(zip(*np.where(ind_mask(tm))))
    all_zones = res_pos | com_pos | ind_pos

    res_count = len(res_pos)
    com_count = len(com_pos)
    ind_count = len(ind_pos)

    # Wire spine: horizontal row just below plant footprint
    wire_row = plant_cy + 3   # row 53
    road_row = wire_row + 1   # row 54

    # Grow horizontal span based on population
    base_span = 10
    extra_span = min(25, obs.city_pop // 40)
    target_span = base_span + extra_span

    wire_cols_in_row = sorted(c for (r, c) in wire_positions if r == wire_row)
    road_cols_in_row = sorted(c for (r, c) in road_positions if r == road_row)

    tmin_col = max(2, cx - target_span)
    tmax_col = min(WORLD_W - 3, cx + target_span)

    # Phase 2: extend wire spine horizontally
    if not wire_cols_in_row:
        # Start wire adjacent to plant
        wc = plant_cx + 2
        if 0 <= wc < WORLD_W:
            return (Tool.WIRE, wc, wire_row)
    else:
        min_wc = min(wire_cols_in_row)
        max_wc = max(wire_cols_in_row)
        # Extend right first
        if max_wc < tmax_col:
            nc = max_wc + 1
            if 0 <= nc < WORLD_W and (em[wire_row, nc] or wm[wire_row, nc]):
                return (Tool.WIRE, nc, wire_row)
        # Extend left
        if min_wc > tmin_col:
            nc = min_wc - 1
            if 0 <= nc < WORLD_W and (em[wire_row, nc] or wm[wire_row, nc]):
                return (Tool.WIRE, nc, wire_row)

    # Phase 3: build road row adjacent to wire
    if wire_cols_in_row:
        road_cols_set = set(road_cols_in_row)
        for wc in wire_cols_in_row:
            if wc not in road_cols_set and 0 <= road_row < WORLD_H:
                if em[road_row, wc]:
                    return (Tool.ROAD, wc, road_row)

    # Phase 4: place zones above and below road row
    # Zones above wire: center at wire_row - 3
    # Zones below road: center at road_row + 3
    top_zone_row = wire_row - 3   # row 50
    bot_zone_row = road_row + 3   # row 58

    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def already_zone_nearby(zr, zc):
        return any(abs(zr - pr) <= 2 and abs(zc - pc) <= 2 for (pr, pc) in all_zones)

    wire_cols_set = set(wire_cols_in_row)
    road_cols_set2 = set(road_cols_in_row)

    # Place zones at each wire column position
    for zc in wire_cols_in_row:
        wire_nearby = zc in wire_cols_set
        road_nearby = any(abs(zc - rc) <= 1 for rc in road_cols_set2)
        if not (wire_nearby and road_nearby):
            continue
        for zr in [top_zone_row, bot_zone_row]:
            if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                if not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                    # Decide zone type
                    total = res_count + com_count + ind_count + 1
                    if ind_count / total < 0.25 and zr == bot_zone_row:
                        return (Tool.INDUSTRIAL, zc, zr)
                    elif com_count / total < 0.25:
                        return (Tool.COMMERCIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

    # Phase 5: add vertical wires from spine up to top zones
    for wc in wire_cols_in_row:
        for wr in range(wire_row - 1, top_zone_row - 1, -1):
            if 0 <= wr < WORLD_H and em[wr, wc]:
                return (Tool.WIRE, wc, wr)

    # Phase 6: add vertical roads from road row down to bottom zones
    for wc in wire_cols_in_row:
        for rr in range(road_row + 1, bot_zone_row + 1):
            if 0 <= rr < WORLD_H and em[rr, wc]:
                return (Tool.ROAD, wc, rr)

    # Phase 7: second tier zones (further up/down) if population growing
    if obs.city_pop > 200:
        top_zone_row2 = wire_row - 7
        bot_zone_row2 = road_row + 7
        for wc in wire_cols_in_row:
            for zr in [top_zone_row2, bot_zone_row2]:
                if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                    if not already_zone_nearby(zr, wc) and zone_area_free(zr, wc):
                        # Wire connecting
                        if zr == top_zone_row2:
                            for wr in range(top_zone_row - 1, top_zone_row2 - 1, -1):
                                if 0 <= wr < WORLD_H and em[wr, wc]:
                                    return (Tool.WIRE, wc, wr)
                        else:
                            for rr in range(bot_zone_row + 1, bot_zone_row2 + 1):
                                if 0 <= rr < WORLD_H and em[rr, wc]:
                                    return (Tool.ROAD, wc, rr)
                        total = res_count + com_count + ind_count + 1
                        if com_count / total < 0.25:
                            return (Tool.COMMERCIAL, wc, zr)
                        return (Tool.RESIDENTIAL, wc, zr)

    # Phase 8: place police/fire station if enough zones
    if obs.city_pop > 100 and len(all_zones) > 5:
        # Place a police station near center if none nearby
        fire_placed = False
        police_placed = False
        for r in range(WORLD_H):
            for c in range(WORLD_W):
                t = tm[r, c]
                if 700 <= t <= 750:  # rough fire station range
                    fire_placed = True
                if 750 <= t <= 800:  # rough police range
                    police_placed = True
        if not fire_placed:
            # Near center
            fc, fr = cx + 5, cy + 5
            if 0 <= fc < WORLD_W and 0 <= fr < WORLD_H and zone_area_free(fr, fc):
                return (Tool.FIRESTATION, fc, fr)
        if not police_placed and obs.city_pop > 200:
            pc2, pr2 = cx - 5, cy + 5
            if 0 <= pc2 < WORLD_W and 0 <= pr2 < WORLD_H and zone_area_free(pr2, pc2):
                return (Tool.POLICESTATION, pc2, pr2)

    # Phase 9: expand wire span if needed for more zones
    if obs.city_pop > 400:
        extra2 = min(35, obs.city_pop // 30)
        tmax2 = min(WORLD_W - 3, cx + base_span + extra2)
        tmin2 = max(2, cx - base_span - extra2)
        if wire_cols_in_row:
            max_wc = max(wire_cols_in_row)
            if max_wc < tmax2:
                nc = max_wc + 1
                if em[wire_row, nc]:
                    return (Tool.WIRE, nc, wire_row)
            min_wc = min(wire_cols_in_row)
            if min_wc > tmin2:
                nc = min_wc - 1
                if em[wire_row, nc]:
                    return (Tool.WIRE, nc, wire_row)

    return None

def act(obs, state):
    """
    Redesigned city builder:
    - Uses a vertical wire spine instead of horizontal
    - Places roads horizontally on both sides of the spine
    - Places zones in a checkerboard pattern with balanced RES/COM/IND
    - Two coal plants at top and bottom of spine
    - More aggressive zone placement
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Vertical spine at x=60 (center of map), from y=10 to y=90
    SPINE_X = 60
    SPINE_Y_START = 10
    SPINE_Y_END = 90
    PLANT1_X, PLANT1_Y = SPINE_X, 15   # top plant
    PLANT2_X, PLANT2_Y = SPINE_X, 80   # bottom plant

    has_plant = np.any(pm)

    # Phase 1: Place first coal power plant
    if not has_plant:
        return (Tool.COALPOWER, PLANT1_X, PLANT1_Y)

    plant_ys, plant_xs = np.where(pm)
    wire_set = set(zip(*np.where(wm))) if np.any(wm) else set()
    road_set = set(zip(*np.where(rm))) if np.any(rm) else set()

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def is_plant(x, y):
        return in_bounds(x, y) and bool(pm[y, x])

    def is_wire_or_plant(x, y):
        return in_bounds(x, y) and (bool(wm[y, x]) or bool(pm[y, x]))

    def is_empty(x, y):
        return in_bounds(x, y) and bool(em[y, x])

    def pick_tool():
        t = max(total_zones, 1)
        r = res_count / t
        c = com_count / t
        i = ind_count / t
        # Want roughly 50% RES, 25% COM, 25% IND
        if c < 0.22:
            return Tool.COMMERCIAL
        if i < 0.22:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not bool(em[nr, nc]):
                    return False
        return True

    # Step 1: Build vertical wire spine from PLANT1_Y+2 to PLANT2_Y-2
    spine_y_from = PLANT1_Y + 2
    spine_y_to = PLANT2_Y - 2
    for wy in range(spine_y_from, spine_y_to + 1):
        if not is_wire_or_plant(SPINE_X, wy):
            if is_empty(SPINE_X, wy):
                return (Tool.WIRE, SPINE_X, wy)

    # Step 2: Place second power plant once spine is extended enough
    near_plant2 = any(bool(pm[PLANT2_Y + dy, PLANT2_X + dx])
                      for dy in range(-3, 4) for dx in range(-3, 4)
                      if in_bounds(PLANT2_X + dx, PLANT2_Y + dy))
    if not near_plant2:
        wire_rows_on_spine = [r for (r, c) in wire_set if c == SPINE_X]
        if wire_rows_on_spine and max(wire_rows_on_spine) >= PLANT2_Y - 5:
            return (Tool.COALPOWER, PLANT2_X, PLANT2_Y)

    # Step 3: Build horizontal wire branches from spine every 6 rows
    branch_rows = list(range(spine_y_from + 2, spine_y_to, 6))
    for by in branch_rows:
        if not is_wire_or_plant(SPINE_X, by):
            continue  # spine not yet here
        for sign in [-1, 1]:
            for dx in range(1, 12):
                bx = SPINE_X + sign * dx
                if not in_bounds(bx, by):
                    break
                if not is_wire_or_plant(bx, by):
                    if is_empty(bx, by):
                        return (Tool.WIRE, bx, by)
                    break

    # Step 4: Build vertical roads parallel to spine, 3 cols left and right
    road_left_x = SPINE_X - 3
    road_right_x = SPINE_X + 3
    road_y_start = spine_y_from - 1
    road_y_end = spine_y_to + 1

    for rx in [road_left_x, road_right_x]:
        for ry in range(road_y_start, road_y_end + 1):
            if in_bounds(rx, ry) and (ry, rx) not in road_set:
                if not bool(pm[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    # Step 5: Build horizontal connector roads every 6 rows
    for hy in branch_rows:
        for hx in range(road_left_x, road_right_x + 1):
            if in_bounds(hx, hy) and (hy, hx) not in road_set:
                if not bool(pm[hy, hx]):
                    return (Tool.ROAD, hx, hy)

    # Step 6: Extended horizontal roads further out for more zone area
    road_far_left = SPINE_X - 10
    road_far_right = SPINE_X + 10
    for hy in branch_rows:
        for hx in range(road_far_left, road_far_right + 1):
            if in_bounds(hx, hy) and (hy, hx) not in road_set:
                if not bool(pm[hy, hx]):
                    return (Tool.ROAD, hx, hy)

    # Build neighbor masks for road and wire/plant proximity
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Step 7: Place zones systematically in grid on both sides of spine
    # Zones at x offsets: SPINE_X +/- 6, spaced every 4 rows
    zone_cols = []
    for side in [-1, 1]:
        for col_off in [6, 10, 14]:
            zone_cols.append(SPINE_X + side * col_off)

    zone_rows_list = list(range(spine_y_from + 1, spine_y_to, 4))

    for zc in zone_cols:
        for zr in zone_rows_list:
            if not in_bounds(zc, zr):
                continue
            if not bool(em[zr, zc]):
                continue
            if not nbr_road[zr, zc]:
                continue
            if not nbr_wire[zr, zc]:
                continue
            if zone_clear(zc, zr):
                return (pick_tool(), zc, zr)

    # Step 8: Generic candidate search for any valid zone location
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        step_hash = int(obs.step * 17) % max(len(cxs), 1)
        for offset in range(min(len(cxs), 80)):
            k = (step_hash + offset * 11) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # Services once population grows
    if obs.city_pop > 200:
        fx, fy = SPINE_X - 15, PLANT1_Y + 5
        if in_bounds(fx, fy) and bool(em[fy, fx]):
            return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 400:
        px2, py2 = SPINE_X + 15, PLANT1_Y + 5
        if in_bounds(px2, py2) and bool(em[py2, px2]):
            return (Tool.POLICESTATION, px2, py2)

    # Extend roads near existing road tiles
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        k = int(obs.step * 13) % len(road_xs)
        rx2, ry2 = int(road_xs[k]), int(road_ys[k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx2 + dx2, ry2 + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy.
    Reads current map each step. 
    Key changes from parent:
    - More compact zone placement (zones every 3 rows instead of every other wire row)
    - Wire runs directly adjacent to zones on both sides
    - Road runs through middle between zone clusters
    - Denser layout: wire_col, road_col, zone_cols tighter
    - Two power plants for higher pop
    - Prioritize connecting road to zones before extending spine
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # Primary cluster layout (tighter)
    plant_cx, plant_cy = 55, 50
    wire_col = 58    # wire spine (adjacent to plant)
    road_col = 61    # road spine
    left_zone_col = 55   # zones left of wire
    right_zone_col = 64  # zones right of road

    has_plant = np.any(pm)

    # Phase 1: Place coal power plant
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Current positions
    wire_positions = set(zip(*np.where(wm))) if np.any(wm) else set()
    road_positions = set(zip(*np.where(rm))) if np.any(rm) else set()
    res_positions = set(zip(*np.where(res_m))) if np.any(res_m) else set()
    com_positions = set(zip(*np.where(com_m))) if np.any(com_m) else set()
    ind_positions = set(zip(*np.where(ind_m))) if np.any(ind_m) else set()
    all_zones = res_positions | com_positions | ind_positions

    res_count = len(res_positions)
    com_count = len(com_positions)
    ind_count = len(ind_positions)

    # Dynamic vertical span
    cy = 50
    base_span = 12
    extra_span = min(28, obs.city_pop // 30)
    target_span = base_span + extra_span
    tmin = max(2, cy - target_span)
    tmax = min(WORLD_H - 3, cy + target_span)

    wire_rows_in_col = sorted(r for (r, c) in wire_positions if c == wire_col)
    road_rows_in_col = sorted(r for (r, c) in road_positions if c == road_col)
    wire_rows_set = set(wire_rows_in_col)
    road_rows_set = set(road_rows_in_col)

    # Helper: check if 3x3 area around center is clear
    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def already_zone_nearby(zr, zc, zones, dist=2):
        return any(abs(zr - pr) <= dist and abs(zc - pc) <= dist for (pr, pc) in zones)

    def pick_zone_type():
        if res_count == 0:
            return Tool.RESIDENTIAL
        elif ind_count * 4 < res_count:
            return Tool.INDUSTRIAL
        elif com_count * 4 < res_count:
            return Tool.COMMERCIAL
        else:
            return Tool.RESIDENTIAL

    # Phase 2: Extend wire spine from plant
    if not wire_rows_in_col:
        # First wire: connect to plant (plant occupies plant_cx-1..plant_cx+1, plant_cy-1..plant_cy+1)
        # wire_col=58, plant right edge at plant_cx+1=56, so place at plant_cy
        for try_r in [plant_cy, plant_cy - 1, plant_cy + 1]:
            if 0 <= try_r < WORLD_H and em[try_r, wire_col]:
                return (Tool.WIRE, wire_col, try_r)
        return (Tool.WIRE, wire_col, plant_cy)
    else:
        min_wr = min(wire_rows_in_col)
        max_wr = max(wire_rows_in_col)
        # Extend downward first
        if max_wr < tmax:
            nr = max_wr + 1
            if 0 < nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if min_wr > tmin:
            nr = min_wr - 1
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    if not wire_rows_in_col:
        return None

    # Phase 3: Build road spine (matching wire coverage)
    for wr in wire_rows_in_col:
        if wr not in road_rows_set and 0 <= road_col < WORLD_W:
            if em[wr, road_col]:
                return (Tool.ROAD, road_col, wr)

    # Phase 4: Place zones - check every 3 rows for compactness
    # Place left zones (col 55) adjacent to wire col 58 (gap of 2 tiles)
    # Place right zones (col 64) adjacent to road col 61 (gap of 2 tiles)
    # Add lateral wires to left zones, lateral roads to right zones

    # Collect rows where both wire and road exist (powered + road access)
    active_rows = sorted(wire_rows_set & road_rows_set)

    for zr in active_rows:
        for zc in [left_zone_col, right_zone_col]:
            if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                if not already_zone_nearby(zr, zc, all_zones, 2) and zone_area_free(zr, zc):
                    return (pick_zone_type(), zc, zr)

    # Phase 5: Lateral infrastructure - wire from spine to left zones
    for wr in wire_rows_in_col:
        # Wire from wire_col-1 down to left_zone_col+2 (stop before zone area)
        for wc in range(wire_col - 1, left_zone_col + 1, -1):
            if 0 <= wc < WORLD_W and em[wr, wc]:
                return (Tool.WIRE, wc, wr)

    # Phase 6: Lateral roads from road col to right zones
    for wr in wire_rows_in_col:
        for rc in range(road_col + 1, right_zone_col - 1):
            if 0 <= rc < WORLD_W and em[wr, rc]:
                return (Tool.ROAD, rc, wr)

    # Phase 7: Second power plant when pop >= 150
    if obs.city_pop >= 150:
        plant_cx2, plant_cy2 = 55, 30
        # Check if second plant exists near that location
        plant_rows, plant_cols = np.where(pm)
        has_plant2 = any(abs(r - plant_cy2) <= 1 and abs(c - plant_cx2) <= 1 
                        for r, c in zip(plant_rows, plant_cols)) if len(plant_rows) > 1 else False
        if not has_plant2 and len(plant_rows) < 2:
            # Check area is clear
            clear = True
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    rr, rc = plant_cy2 + dr, plant_cx2 + dc
                    if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                        if not em[rr, rc]:
                            clear = False
                            break
            if clear:
                return (Tool.COALPOWER, plant_cx2, plant_cy2)

    # Phase 8: Second cluster to the right when pop >= 200
    if obs.city_pop >= 200:
        wire_col2 = road_col + 7    # col 68
        road_col2 = wire_col2 + 3   # col 71
        left_zone_col2 = wire_col2 - 3   # col 65
        right_zone_col2 = road_col2 + 3  # col 74

        wire_rows2 = sorted(r for (r, c) in wire_positions if c == wire_col2)
        road_rows2_set = set(r for (r, c) in road_positions if c == road_col2)

        if not wire_rows2:
            # Build horizontal wire bridge from wire_col to wire_col2
            for wc in range(wire_col + 1, wire_col2 + 1):
                if em[plant_cy, wc]:
                    return (Tool.WIRE, wc, plant_cy)
        else:
            min_wr2 = min(wire_rows2)
            max_wr2 = max(wire_rows2)
            if max_wr2 < tmax:
                nr = max_wr2 + 1
                if 0 < nr < WORLD_H and em[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > tmin:
                nr = min_wr2 - 1
                if 0 <= nr < WORLD_H and em[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)

            for wr in wire_rows2:
                if wr not in road_rows2_set and 0 <= road_col2 < WORLD_W:
                    if em[wr, road_col2]:
                        return (Tool.ROAD, road_col2, wr)

            active_rows2 = sorted(set(wire_rows2) & road_rows2_set)
            for zr in active_rows2:
                for zc in [left_zone_col2, right_zone_col2]:
                    if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                        if not already_zone_nearby(zr, zc, all_zones, 2) and zone_area_free(zr, zc):
                            return (pick_zone_type(), zc, zr)

            # Lateral wires/roads for cluster 2
            for wr in wire_rows2:
                for wc in range(wire_col2 - 1, left_zone_col2 + 1, -1):
                    if 0 <= wc < WORLD_W and em[wr, wc]:
                        return (Tool.WIRE, wc, wr)
            for wr in wire_rows2:
                for rc in range(road_col2 + 1, right_zone_col2 - 1):
                    if 0 <= rc < WORLD_W and em[wr, rc]:
                        return (Tool.ROAD, rc, wr)

    # Phase 9: Third cluster to the left when pop >= 400
    if obs.city_pop >= 400:
        wire_col3 = wire_col - 7    # col 51
        road_col3 = wire_col3 - 3   # col 48
        left_zone_col3 = road_col3 - 3  # col 45
        right_zone_col3 = wire_col3 + 3  # col 54

        wire_rows3 = sorted(r for (r, c) in wire_positions if c == wire_col3)
        road_rows3_set = set(r for (r, c) in road_positions if c == road_col3)

        if not wire_rows3:
            for wc in range(wire_col - 1, wire_col3 - 1, -1):
                if em[plant_cy, wc]:
                    return (Tool.WIRE, wc, plant_cy)
        else:
            min_wr3 = min(wire_rows3)
            max_wr3 = max(wire_rows3)
            if max_wr3 < tmax:
                nr = max_wr3 + 1
                if 0 < nr < WORLD_H and em[nr, wire_col3]:
                    return (Tool.WIRE, wire_col3, nr)
            if min_wr3 > tmin:
                nr = min_wr3 - 1
                if 0 <= nr < WORLD_H and em[nr, wire_col3]:
                    return (Tool.WIRE, wire_col3, nr)

            for wr in wire_rows3:
                if wr not in road_rows3_set and 0 <= road_col3 < WORLD_W:
                    if em[wr, road_col3]:
                        return (Tool.ROAD, road_col3, wr)

            active_rows3 = sorted(set(wire_rows3) & road_rows3_set)
            for zr in active_rows3:
                for zc in [left_zone_col3, right_zone_col3]:
                    if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                        if not already_zone_nearby(zr, zc, all_zones, 2) and zone_area_free(zr, zc):
                            return (pick_zone_type(), zc, zr)

            for wr in wire_rows3:
                for wc in range(wire_col3 - 1, left_zone_col3 + 1, -1):
                    if 0 <= wc < WORLD_W and em[wr, wc]:
                        return (Tool.WIRE, wc, wr)
            for wr in wire_rows3:
                for rc in range(road_col3 + 1, right_zone_col3 - 1):
                    if 0 <= rc < WORLD_W and em[wr, rc]:
                        return (Tool.ROAD, rc, wr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy combining best of both parents.
    Each step reads the current map and decides the next action based on
    what actually exists, not a pre-planned sequence.

    Strategy:
    1. Place coal power plant if none exists
    2. Extend wire spine from plant (vertical)
    3. Build road column adjacent to wire spine
    4. Place zones (RES/COM/IND) adjacent to road, wired areas
    5. Connect zones to wire with lateral wires
    6. Expand laterally as population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # Fixed reference columns
    plant_cx, plant_cy = 54, 50
    wire_col = plant_cx + 3   # 57
    road_col = wire_col + 1   # 58

    # Phase 1: ensure coal plant exists
    if not np.any(pm):
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Gather current positions
    wire_rows_in_col = sorted(r for r in range(WORLD_H) if wm[r, wire_col])
    road_rows_in_col = sorted(r for r in range(WORLD_H) if rm[r, road_col])
    road_rows_set = set(road_rows_in_col)
    wire_rows_set = set(wire_rows_in_col)

    res_count = int(np.sum(res_m))
    com_count = int(np.sum(com_m))
    ind_count = int(np.sum(ind_m))

    # Dynamic span based on population
    base_span = 10
    extra_span = min(25, obs.city_pop // 30)
    target_span = base_span + extra_span
    tmin = max(2, plant_cy - target_span)
    tmax = min(WORLD_H - 3, plant_cy + target_span)

    # Phase 2: extend wire spine vertically from plant
    if not wire_rows_in_col:
        # Seed wire adjacent to plant
        for try_col in [wire_col, wire_col - 1, wire_col + 1]:
            if 0 <= try_col < WORLD_W and (em[plant_cy, try_col] or wm[plant_cy, try_col]):
                return (Tool.WIRE, try_col, plant_cy)
        return (Tool.WIRE, wire_col, plant_cy)
    else:
        min_wr = min(wire_rows_in_col)
        max_wr = max(wire_rows_in_col)
        # Extend downward
        if max_wr < tmax:
            nr = max_wr + 1
            if 0 < nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if min_wr > tmin:
            nr = min_wr - 1
            if 0 <= nr < WORLD_H - 1 and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    # Phase 3: build road column alongside wire
    if wire_rows_in_col:
        for wr in wire_rows_in_col:
            if wr not in road_rows_set:
                if 0 <= road_col < WORLD_W and em[wr, road_col]:
                    return (Tool.ROAD, road_col, wr)

    # Zone placement helpers
    left_zone_col = wire_col - 3   # 54 -- but plant is there, use 51
    left_zone_col = wire_col - 4   # 53
    right_zone_col = road_col + 3  # 61

    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc]:
                    return False
        return True

    all_zone_m = res_m | com_m | ind_m

    def zone_nearby(zr, zc):
        r0, r1 = max(0, zr - 2), min(WORLD_H, zr + 3)
        c0, c1 = max(0, zc - 2), min(WORLD_W, zc + 3)
        return bool(np.any(all_zone_m[r0:r1, c0:c1]))

    # Phase 4: place zones adjacent to road/wire coverage
    for zr in sorted(wire_rows_in_col, key=lambda r: abs(r - plant_cy)):
        road_near = any(abs(zr - rr) <= 1 for rr in road_rows_set)
        wire_near = zr in wire_rows_set

        if not (road_near and wire_near):
            continue

        for zc in [right_zone_col, left_zone_col]:
            if not (2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2):
                continue
            if not zone_nearby(zr, zc) and zone_area_free(zr, zc):
                # Determine zone type
                total = res_count + com_count + ind_count + 1
                if ind_count * 4 < res_count:
                    zt = Tool.INDUSTRIAL
                elif com_count * 4 < res_count:
                    zt = Tool.COMMERCIAL
                else:
                    zt = Tool.RESIDENTIAL
                return (zt, zc, zr)

    # Phase 5: lateral wires from spine to left zones (power them)
    for wr in wire_rows_in_col:
        for wc in range(wire_col - 1, max(1, left_zone_col - 1), -1):
            if em[wr, wc]:
                return (Tool.WIRE, wc, wr)

    # Phase 6: lateral roads from road col to right zones
    for wr in wire_rows_in_col:
        for rc in range(road_col + 1, min(WORLD_W - 1, right_zone_col + 1)):
            if em[wr, rc]:
                return (Tool.ROAD, rc, wr)

    # Phase 7: expand right with a second road column if population is growing
    if obs.city_pop > 200:
        road_col2 = road_col + 8  # 66
        right_zone_col2 = road_col2 + 3  # 69
        wire_col_mid = wire_col  # power via horizontal wire

        # Ensure horizontal wire reaches road_col2 area at plant_cy level
        for wr in wire_rows_in_col:
            for wc in range(wire_col + 1, road_col2):
                if em[wr, wc]:
                    return (Tool.WIRE, wc, wr)
            # Road column 2
            if 0 <= road_col2 < WORLD_W and em[wr, road_col2]:
                return (Tool.ROAD, road_col2, wr)

        # Zones right of road2
        for zr in sorted(wire_rows_in_col, key=lambda r: abs(r - plant_cy)):
            if 2 <= zr < WORLD_H - 2 and 2 <= right_zone_col2 < WORLD_W - 2:
                if not zone_nearby(zr, right_zone_col2) and zone_area_free(zr, right_zone_col2):
                    return (Tool.RESIDENTIAL, right_zone_col2, zr)

    # Phase 8: close-loop fallback - find any res zone neighbor spot that's powered+roaded
    # and place a residential zone there
    if obs.city_pop > 100:
        cand_res = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        cand_res[1:, :] |= res_m[:-1, :]
        cand_res[:-1, :] |= res_m[1:, :]
        cand_res[:, 1:] |= res_m[:, :-1]
        cand_res[:, :-1] |= res_m[:, 1:]
        cand_res &= em
        # Also need road nearby
        road_dil = np.zeros_like(rm)
        road_dil[1:, :] |= rm[:-1, :]
        road_dil[:-1, :] |= rm[1:, :]
        road_dil[:, 1:] |= rm[:, :-1]
        road_dil[:, :-1] |= rm[:, 1:]
        cand_res &= road_dil
        ys, xs = np.where(cand_res)
        if len(xs) > 0:
            # Pick one near center
            dists = np.abs(xs - 60) + np.abs(ys - 50)
            k = int(np.argmin(dists))
            zr, zc = int(ys[k]), int(xs[k])
            if zone_area_free(zr, zc):
                return (Tool.RESIDENTIAL, zc, zr)

    return None

def act(obs, state):
    """
    Hybrid policy combining:
    - Parent A's vertical spine approach (wire col + road col + zones on sides)
    - Parent B's horizontal spine for wider coverage
    - Multiple clusters/power plants for scaling
    - Better zone type balancing
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    res_count = int(np.sum(res_m))
    com_count = int(np.sum(com_m))
    ind_count = int(np.sum(ind_m))
    total_zones = res_count + com_count + ind_count

    cx, cy = 60, 50

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        # Target: 50% RES, 25% COM, 25% IND
        if res_count == 0:
            return Tool.RESIDENTIAL
        if ind_count * 4 < res_count:
            return Tool.INDUSTRIAL
        if com_count * 4 < res_count:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_area_free(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def zone_present_nearby(zr, zc):
        all_zone = res_m | com_m | ind_m
        for dr in range(-2, 3):
            for dc in range(-2, 3):
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone[rr, rc]:
                        return True
        return False

    # ---- Layout parameters ----
    # Primary vertical cluster centered around (60, 50)
    # Wire spine at col 57, road col at 59
    # Zones at col 54 (left) and 62 (right)
    plant_cx, plant_cy = 54, 50
    wire_col = 57
    road_col = 59
    left_zone_col = 54
    right_zone_col = 62

    has_plant = np.any(pm)

    # Phase 0: Place coal power plant
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    wire_positions = set(zip(*np.where(wm))) if np.any(wm) else set()
    road_positions = set(zip(*np.where(rm))) if np.any(rm) else set()

    # Dynamic vertical span
    base_span = 12
    extra_span = min(30, obs.city_pop // 30)
    target_span = base_span + extra_span
    tmin = max(2, cy - target_span)
    tmax = min(WORLD_H - 3, cy + target_span)

    wire_rows_in_col = sorted(r for (r, c) in wire_positions if c == wire_col)
    road_rows_set = set(r for (r, c) in road_positions if c == road_col)

    # Phase 1: Extend wire spine vertically
    if not wire_rows_in_col:
        # First wire adjacent to plant
        for try_r in [plant_cy, plant_cy - 1, plant_cy + 1]:
            if 0 <= try_r < WORLD_H and em[try_r, wire_col]:
                return (Tool.WIRE, wire_col, try_r)
    else:
        min_wr = min(wire_rows_in_col)
        max_wr = max(wire_rows_in_col)
        if max_wr < tmax:
            nr = max_wr + 1
            if 0 < nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        if min_wr > tmin:
            nr = min_wr - 1
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    if not wire_rows_in_col:
        return None

    wire_rows_set = set(wire_rows_in_col)

    # Phase 2: Build road column matching wire spine
    for wr in wire_rows_in_col:
        if wr not in road_rows_set and 0 <= road_col < WORLD_W:
            if em[wr, road_col]:
                return (Tool.ROAD, road_col, wr)

    # Phase 3: Place zones adjacent to road/wire
    for zr in sorted(wire_rows_in_col):
        road_nearby = any(abs(zr - rr) <= 2 for rr in road_rows_set)
        if not road_nearby:
            continue
        for zc in [left_zone_col, right_zone_col]:
            if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                if not zone_present_nearby(zr, zc) and zone_area_free(zr, zc):
                    return (pick_tool(), zc, zr)

    # Phase 4: Lateral wires from spine to left zones
    for wr in wire_rows_in_col:
        for wc in range(wire_col - 1, max(left_zone_col - 2, 0), -1):
            if 0 <= wc < WORLD_W and em[wr, wc]:
                return (Tool.WIRE, wc, wr)

    # Phase 5: Lateral roads from road col to right zones
    for wr in wire_rows_in_col:
        for rc in range(road_col + 1, min(right_zone_col + 2, WORLD_W)):
            if 0 <= rc < WORLD_W and em[wr, rc]:
                return (Tool.ROAD, rc, wr)

    # Phase 6: Horizontal wire row to connect multiple clusters
    # Build a horizontal wire at cy connecting left and right clusters
    h_wire_row = cy
    h_wire_left = max(2, plant_cx - 2)
    h_wire_right = min(WORLD_W - 3, wire_col - 1)
    for wc in range(h_wire_left, h_wire_right + 1):
        if not wm[h_wire_row, wc] and not pm[h_wire_row, wc] and em[h_wire_row, wc]:
            return (Tool.WIRE, wc, h_wire_row)

    # Phase 7: Second cluster (right side) when pop >= 100
    if obs.city_pop >= 100:
        wire_col2 = 66
        road_col2 = 68
        left_zone_col2 = 63
        right_zone_col2 = 71

        wire_rows2 = sorted(r for (r, c) in wire_positions if c == wire_col2)
        road_rows2 = set(r for (r, c) in road_positions if c == road_col2)

        # Connect horizontal wire from wire_col to wire_col2 at cy
        if not wire_rows2:
            for wc in range(wire_col + 1, wire_col2 + 1):
                if em[cy, wc] or wm[cy, wc]:
                    if em[cy, wc]:
                        return (Tool.WIRE, wc, cy)
        else:
            min_wr2 = min(wire_rows2)
            max_wr2 = max(wire_rows2)
            if max_wr2 < tmax:
                nr = max_wr2 + 1
                if 0 < nr < WORLD_H and em[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > tmin:
                nr = min_wr2 - 1
                if 0 <= nr < WORLD_H and em[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)

            for wr in wire_rows2:
                if wr not in road_rows2 and em[wr, road_col2]:
                    return (Tool.ROAD, road_col2, wr)

            for zr in sorted(wire_rows2):
                road_nearby2 = any(abs(zr - rr) <= 2 for rr in road_rows2)
                if not road_nearby2:
                    continue
                for zc in [left_zone_col2, right_zone_col2]:
                    if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                        if not zone_present_nearby(zr, zc) and zone_area_free(zr, zc):
                            return (pick_tool(), zc, zr)

            for wr in wire_rows2:
                for wc in range(wire_col2 - 1, max(left_zone_col2 - 2, 0), -1):
                    if 0 <= wc < WORLD_W and em[wr, wc]:
                        return (Tool.WIRE, wc, wr)

            for wr in wire_rows2:
                for rc in range(road_col2 + 1, min(right_zone_col2 + 2, WORLD_W)):
                    if 0 <= rc < WORLD_W and em[wr, rc]:
                        return (Tool.ROAD, rc, wr)

    # Phase 8: Third cluster (left side) when pop >= 200
    if obs.city_pop >= 200:
        wire_col3 = 51
        road_col3 = 49
        left_zone_col3 = 46
        right_zone_col3 = 54

        wire_rows3 = sorted(r for (r, c) in wire_positions if c == wire_col3)
        road_rows3 = set(r for (r, c) in road_positions if c == road_col3)

        if not wire_rows3:
            for wc in range(wire_col - 1, wire_col3 - 1, -1):
