        else:
            min_wr3 = min(wire_rows3)
            max_wr3 = max(wire_rows3)
            if max_wr3 < tmax:
                nr = max_wr3 + 1
                if 0 < nr < WORLD_H and em[nr, wire_col3]:
                    return (Tool.WIRE, wire_col3, nr)
            if min_wr3 > tmin:
                nr = min_wr3 - 1
                if 0 <= nr < WORLD_H and em[nr, wire_col3]:
                    return (Tool.WIRE, wire_col3, nr)

            for wr in wire_rows3:
                if wr not in road_rows3 and em[wr, road_col3]:
                    return (Tool.ROAD, road_col3, wr)

            for zr in sorted(wire_rows3):
                road_nearby3 = any(abs(zr - rr) <= 2 for rr in road_rows3)
                if not road_nearby3:
                    continue
                for zc in [left_zone_col3, right_zone_col3]:
                    if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                        if not zone_present_nearby(zr, zc) and zone_area_free(zr, zc):
                            return (pick_tool(), zc, zr)

            for wr in wire_rows3:
                for wc in range(wire_col3 - 1, max(left_zone_col3 - 2, 0), -1):
                    if 0 <= wc < WORLD_W and em[wr, wc]:
                        return (Tool.WIRE, wc, wr)

            for wr in wire_rows3:
                for rc in range(road_col3 + 1, min(right_zone_col3 + 2, WORLD_W)):
                    if 0 <= rc < WORLD_W and em[wr, rc]:
                        return (Tool.ROAD, rc, wr)

    # Phase 9: Second power plant for large city
    if obs.city_pop >= 300:
        plant_count = int(np.sum(pm))
        if plant_count < 9:  # coalpower is 3x3=9 tiles
            px2, py2 = 66, 50
            if 2 <= py2 <= WORLD_H - 3 and 2 <= px2 <= WORLD_W - 3:
                # Check area free
                area_ok = True
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if not em[py2 + dr, px2 + dc]:
                            area_ok = False
                if area_ok:
                    return (Tool.COALPOWER, px2, py2)

    # Phase 10: Fourth cluster further right for very high pop
    if obs.city_pop >= 400:
        wire_col4 = 75
        road_col4 = 77
        left_zone_col4 = 72
        right_zone_col4 = 80

        wire_rows4 = sorted(r for (r, c) in wire_positions if c == wire_col4)
        road_rows4 = set(r for (r, c) in road_positions if c == road_col4)

        if not wire_rows4:
            for wc in range(68, wire_col4 + 1):
                if em[cy, wc] or wm[cy, wc]:
                    if em[cy, wc]:
                        return (Tool.WIRE, wc, cy)
        else:
            min_wr4 = min(wire_rows4)
            max_wr4 = max(wire_rows4)
            if max_wr4 < tmax:
                nr = max_wr4 + 1
                if 0 < nr < WORLD_H and em[nr, wire_col4]:
                    return (Tool.WIRE, wire_col4, nr)
            if min_wr4 > tmin:
                nr = min_wr4 - 1
                if 0 <= nr < WORLD_H and em[nr, wire_col4]:
                    return (Tool.WIRE, wire_col4, nr)

            for wr in wire_rows4:
                if wr not in road_rows4 and em[wr, road_col4]:
                    return (Tool.ROAD, road_col4, wr)

            for zr in sorted(wire_rows4):
                road_nearby4 = any(abs(zr - rr) <= 2 for rr in road_rows4)
                if not road_nearby4:
                    continue
                for zc in [left_zone_col4, right_zone_col4]:
                    if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                        if not zone_present_nearby(zr, zc) and zone_area_free(zr, zc):
                            return (pick_tool(), zc, zr)

            for wr in wire_rows4:
                for wc in range(wire_col4 - 1, max(left_zone_col4 - 2, 0), -1):
                    if 0 <= wc < WORLD_W and em[wr, wc]:
                        return (Tool.WIRE, wc, wr)

            for wr in wire_rows4:
                for rc in range(road_col4 + 1, min(right_zone_col4 + 2, WORLD_W)):
                    if 0 <= rc < WORLD_W and em[wr, rc]:
                        return (Tool.ROAD, rc, wr)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder.
    Strategy:
    - Place a coal power plant first, then extend wires FROM existing plant/wire tiles
    - Extend roads FROM existing road tiles
    - Place zones adjacent to both road AND wire coverage
    - Adapt every step by reading the current tile_map
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def safe_empty(x, y):
        return in_bounds(x, y) and bool(em[y, x])

    # --- Phase 0: Ensure at least one power plant exists ---
    plant_count = int(np.sum(pm))
    if plant_count == 0:
        # Place first coal plant at a fixed anchor
        return (Tool.COALPOWER, 10, 50)

    # Place a second plant if population growing and only 1 plant
    if plant_count == 1 and obs.city_pop > 300:
        # Find a good spot far from first plant
        plant_ys, plant_xs = np.where(pm)
        if len(plant_xs) > 0:
            p1x, p1y = int(plant_xs[0]), int(plant_ys[0])
            p2x, p2y = min(p1x + 50, 90), p1y
            if safe_empty(p2x, p2y):
                return (Tool.COALPOWER, p2x, p2y)

    # --- Helper: neighbors of a boolean mask ---
    def frontier_of(mask, step_mod=1):
        """Find empty tiles adjacent to mask tiles, returning list of (x,y)."""
        results = []
        ys, xs = np.where(mask)
        if len(xs) == 0:
            return results
        # Use step to vary which tiles we consider
        indices = list(range(0, len(xs), step_mod)) if step_mod > 1 else list(range(len(xs)))
        for i in indices:
            cx, cy = int(xs[i]), int(ys[i])
            for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx, ny = cx+dx, cy+dy
                if in_bounds(nx, ny) and bool(em[ny, nx]):
                    results.append((nx, ny))
        return results

    # --- Phase 1: Extend wires from plant/wire frontier ---
    # Check if wire network is large enough relative to what we want
    wire_count = int(np.sum(wm))
    plant_ys, plant_xs = np.where(pm)

    # Determine target wire directions: extend wires rightward from plant
    # and also up/down to serve zone rows
    # Read current state of wires to decide next extension
    p1x, p1y = int(plant_xs[0]), int(plant_ys[0])

    # Wire spine: horizontal from plant rightward
    # Wire branches: vertical every 6 cols
    # We do this reactively: find the rightmost wire on spine_y and extend it
    spine_y = p1y
    wire_and_plant = wm | pm

    # Find rightmost wire/plant on spine row
    spine_row = wire_and_plant[spine_y, :]
    spine_xs = np.where(spine_row)[0]

    max_wire_x = int(spine_xs.max()) if len(spine_xs) > 0 else p1x
    target_wire_x_end = min(p1x + 60, WORLD_W - 5)

    # Extend spine wire rightward if not complete
    if max_wire_x < target_wire_x_end:
        nx, ny = max_wire_x + 1, spine_y
        if safe_empty(nx, ny):
            return (Tool.WIRE, nx, ny)
        elif in_bounds(nx, ny) and not bool(wire_and_plant[ny, nx]):
            # Blocked, try to route around (skip for now, try next step)
            pass

    # Extend vertical wire branches every 6 cols from spine
    # Find branch columns where wire exists on spine
    branch_cols = list(range(p1x, target_wire_x_end + 1, 6))
    step_mod = max(1, obs.step % 7 + 1)

    for bx in branch_cols:
        if not in_bounds(bx, spine_y):
            continue
        if not bool(wire_and_plant[spine_y, bx]):
            continue
        # Extend upward
        for sign in [-1, 1]:
            for dist in range(1, 8):
                wy = spine_y + sign * dist
                if not in_bounds(bx, wy):
                    break
                if bool(wire_and_plant[wy, bx]):
                    continue
                if bool(em[wy, bx]):
                    return (Tool.WIRE, bx, wy)
                break

    # --- Phase 2: Extend roads ---
    # Road rows at spine_y - 4 and spine_y + 4, running horizontally
    road_target_ys = [spine_y - 4, spine_y + 4, spine_y - 8, spine_y + 8]
    road_x_start = p1x + 2
    road_x_end = target_wire_x_end

    for ry in road_target_ys:
        if not in_bounds(road_x_start, ry):
            continue
        # Find rightmost road on this row
        row_road = rm[ry, :]
        road_on_row = np.where(row_road)[0]
        if len(road_on_row) == 0:
            # Start a road connected via vertical connector
            # First check if a vertical connector exists near p1x
            for startx in range(road_x_start, road_x_start + 3):
                if in_bounds(startx, ry) and safe_empty(startx, ry):
                    return (Tool.ROAD, startx, ry)
        else:
            max_road_x = int(road_on_row.max())
            if max_road_x < road_x_end:
                nx2, ny2 = max_road_x + 1, ry
                if safe_empty(nx2, ny2):
                    return (Tool.ROAD, nx2, ny2)

    # Vertical road connectors every 6 cols between road rows
    for vc in range(road_x_start, road_x_end + 1, 6):
        y_top = spine_y - 8
        y_bot = spine_y + 8
        for vr in range(y_top, y_bot + 1):
            if not in_bounds(vc, vr):
                continue
            if bool(rm[vr, vc]) or bool(pm[vr, vc]) or bool(wm[vr, vc]):
                continue
            if bool(em[vr, vc]):
                return (Tool.ROAD, vc, vr)

    # --- Phase 3: Place zones where road AND wire both nearby ---
    # Compute neighbor masks
    def expand_mask(mask, radius):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-radius, radius + 1):
            for dx in range(-radius, radius + 1):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                result[r0:r1, c0:c1] |= mask[sr0:sr1, sc0:sc1]
        return result

    near_road = expand_mask(rm, 2)
    near_wire = expand_mask(wire_and_plant, 4)

    # Candidate tiles: empty, near road, near wire, not at border
    cand = em & near_road & near_wire
    cand[0:3, :] = False
    cand[WORLD_H-3:, :] = False
    cand[:, 0:3] = False
    cand[:, WORLD_W-3:] = False

    zone_set = set()
    for mask_ in [resm, comm, indm]:
        ys_, xs_ = np.where(mask_)
        for yy, xx in zip(ys_.tolist(), xs_.tolist()):
            zone_set.add((yy, xx))

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not bool(em[nr, nc]) and (nr, nc) not in zone_set:
                    return False
        return True

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        r_frac = res_count / total
        c_frac = com_count / total
        i_frac = ind_count / total
        if c_frac < 0.22:
            return Tool.COMMERCIAL
        if i_frac < 0.22:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        # Use step-based hash for variety
        h = (obs.step * 31 + int(obs.city_pop * 7)) % len(cxs)
        for offset in range(min(len(cxs), 80)):
            k = (h + offset * 13) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # --- Phase 4: Services ---
    if obs.city_pop > 200:
        for fx, fy in [(p1x + 6, spine_y - 12), (p1x + 30, spine_y + 12)]:
            if in_bounds(fx, fy) and safe_empty(fx, fy):
                return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 400:
        for fx, fy in [(p1x + 18, spine_y - 12), (p1x + 42, spine_y + 12)]:
            if in_bounds(fx, fy) and safe_empty(fx, fy):
                return (Tool.POLICESTATION, fx, fy)

    # --- Fallback: extend roads from any road frontier ---
    road_frontier = frontier_of(rm, step_mod=3)
    for (fx2, fy2) in road_frontier[:20]:
        if safe_empty(fx2, fy2):
            return (Tool.ROAD, fx2, fy2)

    # --- Fallback: extend wire from wire frontier ---
    wire_frontier = frontier_of(wire_and_plant, step_mod=3)
    for (fx3, fy3) in wire_frontier[:20]:
        if safe_empty(fx3, fy3):
            return (Tool.WIRE, fx3, fy3)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map each step and extends power/road/zones
    reactively based on what already exists on the map.

    Strategy:
    - Phase 0: Place a coal power plant at a fixed anchor
    - Phase 1: Extend wires from the power plant outward (scan for wire frontier)
    - Phase 2: Extend roads along a spine adjacent to wires
    - Phase 3: Place zones adjacent to roads that have power nearby
    - Repeat phase 2-3 to keep growing
    """

    # Initialize state
    if "phase" not in state:
        state["phase"] = 0
        state["step_in_phase"] = 0
        state["anchor_x"] = 25
        state["anchor_y"] = 50

    tile = obs.tile_map  # (100, 120)

    # Helper: check bounds
    def inbounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Helper: is a tile powered (has wire or plant nearby)?
    def has_wire_nearby(x, y, radius=3):
        x0, x1 = max(0, x - radius), min(WORLD_W, x + radius + 1)
        y0, y1 = max(0, y - radius), min(WORLD_H, y + radius + 1)
        return wire_mask[y0:y1, x0:x1].any() or plant_mask[y0:y1, x0:x1].any()

    # Helper: is a tile road-accessible nearby?
    def has_road_nearby(x, y, radius=2):
        x0, x1 = max(0, x - radius), min(WORLD_W, x + radius + 1)
        y0, y1 = max(0, y - radius), min(WORLD_H, y + radius + 1)
        return road_mask[y0:y1, x0:x1].any()

    # Helper: find frontier cells adjacent to existing wire/plant
    def find_wire_frontier():
        # Find empty cells adjacent to wire or plant
        combined = wire_mask | plant_mask
        candidates = []
        ys, xs = np.where(combined)
        for y, x in zip(ys.tolist(), xs.tolist()):
            for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx, ny = x+dx, y+dy
                if inbounds(nx, ny) and empty_mask[ny, nx]:
                    candidates.append((nx, ny))
        return candidates

    # Helper: find frontier cells adjacent to existing road
    def find_road_frontier():
        candidates = []
        ys, xs = np.where(road_mask)
        for y, x in zip(ys.tolist(), xs.tolist()):
            for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx, ny = x+dx, y+dy
                if inbounds(nx, ny) and empty_mask[ny, nx]:
                    candidates.append((nx, ny))
        return candidates

    ax, ay = state["anchor_x"], state["anchor_y"]

    # Phase 0: Place coal power plant
    if state["phase"] == 0:
        state["phase"] = 1
        return (Tool.COALPOWER, ax, ay)

    # Phase 1: Build wire spine horizontally and vertically from plant
    # Use a BFS-like expansion: find wire frontier, extend toward target direction
    if state["phase"] == 1:
        s = state["step_in_phase"]
        state["step_in_phase"] = s + 1

        # Build wire corridor: horizontal spine at y=ay from ax outward
        # and a vertical branch
        wire_frontier = find_wire_frontier()

        if not wire_frontier:
            # No frontier yet, place wire adjacent to plant
            return (Tool.WIRE, ax + 4, ay)

        # Prefer extending rightward along horizontal spine
        # Find wire extent
        ys, xs = np.where(wire_mask | plant_mask)
        if len(xs) == 0:
            return (Tool.WIRE, ax + 1, ay)

        max_wx = int(xs.max())
        min_wx = int(xs.min())

        # Extend horizontal wire spine rightward up to x=95
        if max_wx < 95:
            # Place wire to the right of current max
            target_x = max_wx + 1
            target_y = ay
            if inbounds(target_x, target_y) and empty_mask[target_y, target_x]:
                if s < 80:  # Build wire for first 80 steps in phase
                    return (Tool.WIRE, target_x, target_y)

        # Also extend leftward to x=10 for left zones
        if min_wx > 10:
            target_x = min_wx - 1
            target_y = ay
            if inbounds(target_x, target_y) and empty_mask[target_y, target_x]:
                return (Tool.WIRE, target_x, target_y)

        # Switch to road/zone phase
        state["phase"] = 2
        state["step_in_phase"] = 0
        return None

    # Phase 2: Build roads parallel to wire spine, then place zones
    if state["phase"] == 2:
        s = state["step_in_phase"]
        state["step_in_phase"] = s + 1

        # Build road one row above wire spine (ay-1) and one below (ay+1)
        ys_w, xs_w = np.where(wire_mask | plant_mask)
        if len(xs_w) == 0:
            state["phase"] = 1
            return None

        max_wx = int(xs_w.max())
        min_wx = int(xs_w.min())

        # Check road extent above wire
        road_y1 = ay - 1
        road_y2 = ay + 1

        # Find empty spots on road row above
        for rx_try in range(min_wx, max_wx + 1):
            if inbounds(rx_try, road_y1) and empty_mask[road_y1, rx_try]:
                return (Tool.ROAD, rx_try, road_y1)

        for rx_try in range(min_wx, max_wx + 1):
            if inbounds(rx_try, road_y2) and empty_mask[road_y2, rx_try]:
                return (Tool.ROAD, rx_try, road_y2)

        # Also add vertical roads every 6 columns for zone access
        for vx in range(min_wx + 3, max_wx - 2, 6):
            for vy in range(ay - 12, ay + 13):
                if inbounds(vx, vy) and empty_mask[vy, vx]:
                    return (Tool.ROAD, vx, vy)

        state["phase"] = 3
        state["step_in_phase"] = 0
        return None

    # Phase 3: Place zones where we have road AND wire access
    if state["phase"] == 3:
        s = state["step_in_phase"]
        state["step_in_phase"] = s + 1

        # Scan map for good zone placement spots:
        # - empty 3x3 area (center must be empty)
        # - road within 2 tiles
        # - wire within 4 tiles

        # Determine zone type based on current city needs
        r_pop = obs.res_pop
        c_pop = obs.com_pop
        i_pop = obs.ind_pop

        # Balance: more residential, some commercial, some industrial
        if r_pop <= c_pop * 3 and r_pop <= i_pop * 3:
            preferred = [Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.INDUSTRIAL]
        elif c_pop < r_pop // 4:
            preferred = [Tool.COMMERCIAL, Tool.RESIDENTIAL, Tool.INDUSTRIAL]
        elif i_pop < r_pop // 4:
            preferred = [Tool.INDUSTRIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL]
        else:
            preferred = [Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.INDUSTRIAL]

        # Scan for placement candidates
        # Look in a band around the wire spine
        ys_w, xs_w = np.where(wire_mask | plant_mask)
        if len(xs_w) == 0:
            state["phase"] = 1
            return None

        min_wx = int(xs_w.min())
        max_wx = int(xs_w.max())

        # Try placing zones above and below the road rows
        zone_rows = [ay - 4, ay - 7, ay - 10, ay + 4, ay + 7, ay + 10,
                     ay - 13, ay + 13, ay - 16, ay + 16]

        best_candidates = []
        for zy in zone_rows:
            for zx in range(min_wx + 3, max_wx - 2, 3):
                if not inbounds(zx, zy):
                    continue
                if not empty_mask[zy, zx]:
                    continue
                if has_road_nearby(zx, zy, 2) and has_wire_nearby(zx, zy, 4):
                    best_candidates.append((zx, zy))

        if best_candidates:
            # Pick first one based on step counter
            idx = s % len(best_candidates)
            zx, zy = best_candidates[idx]
            tool = preferred[s % len(preferred)]
            return (tool, zx, zy)

        # No good spots yet, add more vertical wires/roads
        state["phase"] = 4
        state["step_in_phase"] = 0
        return None

    # Phase 4: Add vertical wire branches and second power plant
    if state["phase"] == 4:
        s = state["step_in_phase"]
        state["step_in_phase"] = s + 1

        ys_w, xs_w = np.where(wire_mask | plant_mask)
        if len(xs_w) == 0:
            state["phase"] = 1
            return None

        max_wx = int(xs_w.max())
        min_wx = int(xs_w.min())

        # Add second coal plant on the right
        if not plant_mask[ay, min(max_wx + 5, 119)]:
            # Place second plant
            px = min(max_wx + 5, 115)
            if inbounds(px, ay) and empty_mask[ay, px]:
                return (Tool.COALPOWER, px, ay)

        # Add vertical wire spines every 6 cols
        for vwx in range(min_wx + 3, max_wx, 6):
            for vwy in range(ay - 15, ay + 16):
                if inbounds(vwx, vwy) and empty_mask[vwy, vwx]:
                    # Check if wire spine is connected at ay
                    if wire_mask[ay, vwx] or plant_mask[ay, vwx]:
                        return (Tool.WIRE, vwx, vwy)
                    else:
                        return (Tool.WIRE, vwx, ay)

        # Add services
        if s == 0:
            return (Tool.FIRESTATION, ax + 10, ay - 15)
        if s == 1:
            return (Tool.POLICESTATION, ax + 30, ay + 15)
        if s == 2:
            return (Tool.FIRESTATION, ax + 50, ay - 15)

        # Go back to zone placement
        state["phase"] = 3
        state["step_in_phase"] = 0
        return None

    # Fallback: cycle through phases 2-4
    state["phase"] = 2
    state["step_in_phase"] = 0
    return None

def act(obs, state):
    """
    Closed-loop policy: reads map each step and places next tile based on
    current state of the map. Uses a phase counter in state for high-level
    guidance, but all placement decisions are reactive to obs.tile_map.

    Layout:
    - Coal plant at fixed anchor
    - Wire column extending from plant
    - Road column adjacent to wire
    - Zones placed where wire+road are nearby
    - Lateral wires/roads extended reactively
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    # Fixed layout columns
    plant_x = cx - 8
    plant_y = cy
    wire_col = cx - 2
    road_col = cx        # road right next to wire col

    # Zone columns: zones are placed with center here
    left_zcol = wire_col - 3   # center col for left zones
    right_zcol = road_col + 3  # center col for right zones

    # Clamp everything
    wire_col = max(2, min(WORLD_W - 3, wire_col))
    road_col = max(2, min(WORLD_W - 3, road_col))
    left_zcol = max(2, min(WORLD_W - 3, left_zcol))
    right_zcol = max(2, min(WORLD_W - 3, right_zcol))
    plant_x = max(2, min(WORLD_W - 3, plant_x))

    # Adaptive spine extent based on current population
    pop = obs.city_pop
    if pop < 50:
        spine_half = 10
    elif pop < 200:
        spine_half = 15
    elif pop < 500:
        spine_half = 22
    else:
        spine_half = 30

    spine_min = max(2, cy - spine_half)
    spine_max = min(WORLD_H - 3, cy + spine_half)

    def has_tile(mask, x, y):
        if 0 <= y < WORLD_H and 0 <= x < WORLD_W:
            return bool(mask[y, x])
        return False

    def is_clear(x, y):
        """Cell is empty or already what we want to overwrite"""
        if 0 <= y < WORLD_H and 0 <= x < WORLD_W:
            return bool(em[y, x])
        return False

    def zone_footprint_ok(zc, zr):
        """Check 3x3 footprint is clear (or already zoned)"""
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        all_zone = resm | comm | indm
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone[rr, rc]:
                    return False
        return True

    def zone_already_present(zc, zr):
        all_zone = resm | comm | indm
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone[rr, rc]:
                        return True
        return False

    def pick_tool():
        total = int(np.sum(resm | comm | indm))
        rc = int(np.sum(resm))
        cc = int(np.sum(comm))
        ic = int(np.sum(indm))
        if total == 0:
            return Tool.RESIDENTIAL
        if cc / total < 0.25:
            return Tool.COMMERCIAL
        if ic / total < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # --- PHASE 0: Place power plant if none exists ---
    if not np.any(pm):
        return (Tool.COALPOWER, plant_x, plant_y)

    # Find actual plant location reactively
    plant_locs = np.argwhere(pm)
    if len(plant_locs) > 0:
        # Use first plant found
        py0, px0 = plant_locs[0]
    else:
        py0, px0 = plant_y, plant_x

    # --- PHASE 1: Extend wire column from plant toward spine ---
    # First connect plant to wire column if needed
    # Place wire from plant_x toward wire_col at plant_y row
    if px0 != wire_col:
        step = 1 if wire_col > px0 else -1
        for wx in range(px0 + step, wire_col + step, step):
            if 0 <= wx < WORLD_W:
                if not has_tile(wm, wx, py0) and not has_tile(pm, wx, py0):
                    if not has_tile(rm, wx, py0):
                        return (Tool.WIRE, wx, py0)

    # --- PHASE 2: Wire spine - extend vertically from plant row ---
    # Find current wire extent on wire_col
    wire_ys = [y for y in range(spine_min, spine_max + 1) if has_tile(wm, wire_col, y) or has_tile(pm, wire_col, y)]

    # Extend wire upward from any connected wire
    for dy in range(spine_min, spine_max + 1):
        if not has_tile(wm, wire_col, dy) and not has_tile(pm, wire_col, dy):
            # Check if adjacent wire exists (to maintain connectivity)
            adj_wire = (has_tile(wm, wire_col, dy-1) or has_tile(pm, wire_col, dy-1) or
                       has_tile(wm, wire_col, dy+1) or has_tile(pm, wire_col, dy+1))
            if adj_wire and not has_tile(rm, wire_col, dy):
                return (Tool.WIRE, wire_col, dy)

    # --- PHASE 3: Road column ---
    for dy in range(spine_min, spine_max + 1):
        if not has_tile(rm, road_col, dy) and not has_tile(pm, road_col, dy):
            if not has_tile(wm, road_col, dy):
                return (Tool.ROAD, road_col, dy)

    # --- Collect active spine rows ---
    active_wire_rows = [y for y in range(spine_min, spine_max + 1) if has_tile(wm, wire_col, y) or has_tile(pm, wire_col, y)]
    active_road_rows = [y for y in range(spine_min, spine_max + 1) if has_tile(rm, road_col, y)]

    # --- PHASE 4: Place zones where wire and road are both nearby ---
    # Scan zone positions reactively: place where wire and road within 2 tiles
    zone_rows = list(range(spine_min + 1, spine_max - 1, 3))

    for zr in zone_rows:
        wire_near = any(abs(zr - wr) <= 2 for wr in active_wire_rows)
        road_near = any(abs(zr - rr) <= 2 for rr in active_road_rows)

        if wire_near and road_near:
            # Left zone
            for zc in [left_zcol, left_zcol - 4]:
                zc = max(2, min(WORLD_W - 3, zc))
                if not zone_already_present(zc, zr) and zone_footprint_ok(zc, zr):
                    # Check wire reachable nearby
                    r0 = max(0, zr - 3); r1 = min(WORLD_H, zr + 4)
                    c0 = max(0, zc - 3); c1 = min(WORLD_W, zc + 4)
                    if np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1]):
                        if np.any(rm[r0:r1, c0:c1]):
                            return (pick_tool(), zc, zr)
                    # Place zone anyway if close to spine (road+wire will reach)
                    elif zc >= wire_col - 4:
                        return (pick_tool(), zc, zr)

            # Right zone
            for zc in [right_zcol, right_zcol + 4]:
                zc = max(2, min(WORLD_W - 3, zc))
                if not zone_already_present(zc, zr) and zone_footprint_ok(zc, zr):
                    r0 = max(0, zr - 3); r1 = min(WORLD_H, zr + 4)
                    c0 = max(0, zc - 3); c1 = min(WORLD_W, zc + 4)
                    if np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1]):
                        if np.any(rm[r0:r1, c0:c1]):
                            return (pick_tool(), zc, zr)
                    elif zc <= road_col + 4:
                        return (pick_tool(), zc, zr)

    # --- PHASE 5: Lateral wires to unpowered left zones ---
    # Find zones without adjacent wire and extend wire to them
    all_zone = resm | comm | indm
    zone_locs = np.argwhere(all_zone)
    for zy, zx in zone_locs:
        # Check if this zone has wire nearby
        r0 = max(0, zy - 2); r1 = min(WORLD_H, zy + 3)
        c0 = max(0, zx - 2); c1 = min(WORLD_W, zx + 3)
        if not np.any(wm[r0:r1, c0:c1]) and not np.any(pm[r0:r1, c0:c1]):
            # Need to extend wire to this zone
            # Find nearest wire
            if len(active_wire_rows) > 0:
                # Extend horizontally from wire_col toward zone
                nearest_wr = min(active_wire_rows, key=lambda r: abs(r - zy))
                if nearest_wr == zy or has_tile(wm, wire_col, nearest_wr):
                    step = 1 if zx > wire_col else -1
                    for wx in range(wire_col + step, zx, step):
                        if 0 <= wx < WORLD_W and 0 <= nearest_wr < WORLD_H:
                            if not has_tile(wm, wx, nearest_wr) and not has_tile(pm, wx, nearest_wr):
                                if not has_tile(rm, wx, nearest_wr) and em[nearest_wr, wx]:
                                    return (Tool.WIRE, wx, nearest_wr)

    # --- PHASE 6: Lateral roads to improve zone road access ---
    # Find zones without road nearby
    for zy, zx in zone_locs:
        r0 = max(0, zy - 2); r1 = min(WORLD_H, zy + 3)
        c0 = max(0, zx - 2); c1 = min(WORLD_W, zx + 3)
        if not np.any(rm[r0:r1, c0:c1]):
            # Extend road from road_col toward zone
            if len(active_road_rows) > 0:
                nearest_rr = min(active_road_rows, key=lambda r: abs(r - zy))
                step = 1 if zx > road_col else -1
                for rx in range(road_col + step, zx + step, step):
                    if 0 <= rx < WORLD_W and 0 <= nearest_rr < WORLD_H:
                        if not has_tile(rm, rx, nearest_rr) and not has_tile(pm, rx, nearest_rr):
                            if not has_tile(wm, rx, nearest_rr) and em[nearest_rr, rx]:
                                return (Tool.ROAD, rx, nearest_rr)

    # --- PHASE 7: Second power plant if large city ---
    if pop > 400 and int(np.sum(pm)) < 9:
        px2 = plant_x + 18
        py2 = plant_y
        if 2 <= px2 <= WORLD_W - 3:
            if em[py2, px2]:
                return (Tool.COALPOWER, px2, py2)

    # --- PHASE 8: Horizontal connecting roads for better connectivity ---
    if pop > 80:
        for connect_y in [spine_min + 1, cy, spine_max - 1]:
            if 0 <= connect_y < WORLD_H:
                for rc in range(left_zcol - 1, right_zcol + 2):
                    if 0 <= rc < WORLD_W:
                        if em[connect_y, rc] and not pm[connect_y, rc] and not wm[connect_y, rc]:
                            return (Tool.ROAD, rc, connect_y)

    # --- PHASE 9: Wire horizontal near zones for power ---
    # Look for zones with no wire and place wire adjacent
    for zy, zx in zone_locs:
        # Try to place wire adjacent to zone
        for wx, wy in [(zx - 2, zy), (zx + 2, zy), (zx, zy - 2), (zx, zy + 2)]:
            if 0 <= wx < WORLD_W and 0 <= wy < WORLD_H:
                if em[wy, wx] and not rm[wy, wx]:
                    # Check if this wire would connect to existing power
                    for nx, ny in [(wx-1, wy), (wx+1, wy), (wx, wy-1), (wx, wy+1)]:
                        if 0 <= nx < WORLD_W and 0 <= ny < WORLD_H:
                            if has_tile(wm, nx, ny) or has_tile(pm, nx, ny):
                                return (Tool.WIRE, wx, wy)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Each step reads tile_map to find existing infrastructure and extends it.
    - Places coal plant first, then grows wire/road/zone clusters reactively.
    - Scans for frontier: where wire ends -> extend wire; where road ends -> extend road;
      where powered+roaded area exists -> place zone.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    rz = res_mask(tm)
    cz = com_mask(tm)
    iz = ind_mask(tm)

    # ---- Phase tracking ----
    if 'phase' not in state:
        state['phase'] = 0
    if 'wire_dir' not in state:
        state['wire_dir'] = 1  # 1=down, -1=up

    # Fixed anchor: plant at (30, 50), wire spine col=35, road col=38
    PLANT_X, PLANT_Y = 30, 50
    WIRE_COL = 35
    ROAD_COL = 38
    WIRE_MIN_ROW = 10
    WIRE_MAX_ROW = 89

    # ---- Step 1: Ensure power plant exists ----
    if not np.any(pm):
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    # Find actual plant center
    plant_rows, plant_cols = np.where(pm)
    if len(plant_rows) > 0:
        # Use centroid
        pr = int(np.mean(plant_rows))
        pc = int(np.mean(plant_cols))
    else:
        pr, pc = PLANT_Y, PLANT_X

    # ---- Step 2: Ensure at least one wire adjacent to plant ----
    # Wire spine at WIRE_COL, bridging from plant to zones
    wire_col_set = set(r for r in range(WORLD_H) if wm[r, WIRE_COL])

    if not wire_col_set:
        # Place first wire adjacent to plant (horizontal bridge)
        # Plant occupies pc-1..pc+1, pr-1..pr+1
        # Wire col is WIRE_COL; need horizontal wires from plant edge to WIRE_COL
        for c in range(pc + 2, WIRE_COL + 1):
            if 0 <= c < WORLD_W:
                if not wm[pr, c] and not pm[pr, c]:
                    return (Tool.WIRE, c, pr)
        return (Tool.WIRE, WIRE_COL, pr)

    # ---- Step 3: Grow wire spine vertically (reactive: find current extent) ----
    min_wire_row = min(wire_col_set)
    max_wire_row = max(wire_col_set)

    # Extend downward
    if max_wire_row < WIRE_MAX_ROW:
        nr = max_wire_row + 1
        if 0 <= nr < WORLD_H:
            return (Tool.WIRE, WIRE_COL, nr)

    # Extend upward
    if min_wire_row > WIRE_MIN_ROW:
        nr = min_wire_row - 1
        if nr >= 0:
            return (Tool.WIRE, WIRE_COL, nr)

    # ---- Step 4: Build horizontal bridge from plant to wire spine ----
    # Check if bridge at plant row exists
    for c in range(pc + 2, WIRE_COL):
        if not wm[pr, c] and not pm[pr, c] and 0 <= c < WORLD_W:
            return (Tool.WIRE, c, pr)

    # ---- Step 5: Build road column at ROAD_COL ----
    road_col_set = set(r for r in range(WORLD_H) if rm[r, ROAD_COL])
    # Road should parallel wire spine
    for wr in sorted(wire_col_set):
        if not rm[wr, ROAD_COL] and 0 <= ROAD_COL < WORLD_W:
            return (Tool.ROAD, ROAD_COL, wr)

    # ---- Step 6: Place zones reactively ----
    # Zone placement: scan rows where wire and road both exist
    # Left zones at WIRE_COL - 3, right zones at ROAD_COL + 3
    LEFT_ZONE_COL = WIRE_COL - 3
    RIGHT_ZONE_COL = ROAD_COL + 3

    zone_rows_available = sorted(wire_col_set & road_col_set)

    res_count = int(np.sum(rz))
    com_count = int(np.sum(cz))
    ind_count = int(np.sum(iz))
    total_zones = res_count + com_count + ind_count

    all_zone_mask = rz | cz | iz

    def area_clear_of_zones_and_plant(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if pm[rr, rc]:
                    return False
                if all_zone_mask[rr, rc]:
                    return False
        return True

    def pick_zone_type():
        # ~50% RES, ~25% COM, ~25% IND
        if total_zones == 0:
            return Tool.RESIDENTIAL
        if ind_count * 4 < total_zones + 1:
            return Tool.INDUSTRIAL
        if com_count * 4 < total_zones + 1:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Try left zones (connected to wire spine via proximity)
    for zr in zone_rows_available[::3]:
        zc = LEFT_ZONE_COL
        if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
            if area_clear_of_zones_and_plant(zr, zc):
                # Add lateral wire from spine to zone
                # Check if wire connects zone to spine
                zone_wired = False
                for c in range(zc, WIRE_COL + 1):
                    if wm[zr, c]:
                        zone_wired = True
                        break
                if not zone_wired:
                    # Lay wire from wire_col toward zone
                    for c in range(WIRE_COL - 1, zc - 1, -1):
                        if not wm[zr, c] and not pm[zr, c] and 0 <= c < WORLD_W:
                            return (Tool.WIRE, c, zr)
                return (pick_zone_type(), zc, zr)

    # Try right zones (connected to road via proximity)
    for zr in zone_rows_available[1::3]:
        zc = RIGHT_ZONE_COL
        if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
            if area_clear_of_zones_and_plant(zr, zc):
                # Need wire access: lay lateral wire from spine to right zone
                zone_wired = False
                for c in range(WIRE_COL, zc + 2):
                    if wm[zr, c]:
                        zone_wired = True
                        break
                if not zone_wired:
                    for c in range(WIRE_COL + 1, zc + 2):
                        if not wm[zr, c] and not pm[zr, c] and not rm[zr, c]:
                            if 0 <= c < WORLD_W:
                                return (Tool.WIRE, c, zr)
                # Also need road from road_col to zone
                road_ok = False
                for c in range(ROAD_COL, zc + 2):
                    if rm[zr, c]:
                        road_ok = True
                        break
                if not road_ok:
                    for c in range(ROAD_COL + 1, zc + 2):
                        if not rm[zr, c] and 0 <= c < WORLD_W:
                            return (Tool.ROAD, c, zr)
                return (pick_zone_type(), zc, zr)

    # ---- Step 7: Fill lateral wires for all wire spine rows ----
    for wr in sorted(wire_col_set):
        for c in range(WIRE_COL - 1, LEFT_ZONE_COL - 1, -1):
            if 0 <= c < WORLD_W and not wm[wr, c] and not pm[wr, c]:
                return (Tool.WIRE, c, wr)

    # ---- Step 8: Fill lateral roads from road col to right zone col ----
    for rr in sorted(road_col_set):
        for c in range(ROAD_COL + 1, RIGHT_ZONE_COL + 2):
            if 0 <= c < WORLD_W and not rm[rr, c]:
                return (Tool.ROAD, c, rr)

    # ---- Step 9: Expand if city is growing ----
    if obs.city_pop > 100 or total_zones > 5:
        # Add more road and wire rows interleaved with zones
        ROAD_COL2 = ROAD_COL + 8
        FAR_RIGHT_COL = ROAD_COL2 + 3

        for wr in sorted(wire_col_set):
            if not rm[wr, ROAD_COL2] and 0 <= ROAD_COL2 < WORLD_W:
                return (Tool.ROAD, ROAD_COL2, wr)

        for zr in zone_rows_available[2::3]:
            zc = FAR_RIGHT_COL
            if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                if area_clear_of_zones_and_plant(zr, zc):
                    # Wire to far right zone
                    for c in range(WIRE_COL + 1, zc + 2):
                        if not wm[zr, c] and not pm[zr, c] and 0 <= c < WORLD_W:
                            return (Tool.WIRE, c, zr)
                    return (Tool.RESIDENTIAL, zc, zr)

    # ---- Step 10: Nuclear upgrade if very rich ----
    if obs.city_pop > 800:
        nuke_x = pc - 10
        nuke_y = pr + 10
        if 1 <= nuke_x < WORLD_W - 1 and 1 <= nuke_y < WORLD_H - 1:
            if not np.any(pm[nuke_y-1:nuke_y+2, nuke_x-1:nuke_x+2]):
                return (Tool.NUCLEARPOWER, nuke_x, nuke_y)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder.
    Reads tile_map each step, grows infrastructure from what already exists.
    Strategy:
    - Place coal plant at anchor
    - Grow wire spine vertically from plant
    - Grow road column adjacent to wire spine
    - Place zones on both sides of road/wire
    - Connect zones with lateral wires and roads
    - Expand to second/third clusters as population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Anchor positions
    plant_cx, plant_cy = 58, 50

    # Primary cluster columns
    wire_col  = plant_cx + 4   # 62
    road_col  = wire_col + 2   # 64
    lzone_col = wire_col - 4   # 58 (left zone centers)
    rzone_col = road_col + 4   # 68 (right zone centers)

    has_plant = np.any(pm)

    # Step 1: Place plant if missing
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Gather positions
    wire_pos = set(zip(*np.where(wm))) if np.any(wm) else set()
    road_pos = set(zip(*np.where(rm))) if np.any(rm) else set()
    res_pos  = set(zip(*np.where(res_m))) if np.any(res_m) else set()
    com_pos  = set(zip(*np.where(com_m))) if np.any(com_m) else set()
    ind_pos  = set(zip(*np.where(ind_m))) if np.any(ind_m) else set()
    all_zones = res_pos | com_pos | ind_pos

    res_count = len(res_pos)
    com_count = len(com_pos)
    ind_count = len(ind_pos)
    total_zones = res_count + com_count + ind_count

    def pick_zone_tool():
        if total_zones == 0 or res_count == 0:
            return Tool.RESIDENTIAL
        if ind_count * 4 < res_count:
            return Tool.INDUSTRIAL
        if com_count * 4 < res_count:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not in_bounds(rc, rr):
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def zone_too_close(zr, zc):
        # Check if any existing zone center is within 3 tiles
        return any(abs(zr - pr) <= 2 and abs(zc - pc) <= 2 for (pr, pc) in all_zones)

    # Dynamic vertical span
    base_span = 12
    extra_span = min(30, obs.city_pop // 20)
    target_span = base_span + extra_span
    tmin = max(2, plant_cy - target_span)
    tmax = min(WORLD_H - 3, plant_cy + target_span)

    # Helper: grow a wire spine on a given column
    def try_grow_wire_spine(col, t_min, t_max):
        rows = sorted(r for (r, c) in wire_pos if c == col)
        if not rows:
            # Start wire adjacent to plant or at center
            for try_r in [plant_cy, plant_cy - 1, plant_cy + 1]:
                if in_bounds(col, try_r) and em[try_r, col]:
                    return (Tool.WIRE, col, try_r)
            return None
        min_r, max_r = min(rows), max(rows)
        # Extend downward
        if max_r < t_max:
            nr = max_r + 1
            if in_bounds(col, nr) and (em[nr, col] or wm[nr, col]):
                if em[nr, col]:
                    return (Tool.WIRE, col, nr)
        # Extend upward
        if min_r > t_min:
            nr = min_r - 1
            if in_bounds(col, nr) and (em[nr, col] or wm[nr, col]):
                if em[nr, col]:
                    return (Tool.WIRE, col, nr)
        return None

    # Helper: grow road along a column, matching wire coverage
    def try_grow_road_col(col, wire_col_ref):
        wire_rows = sorted(r for (r, c) in wire_pos if c == wire_col_ref)
        road_rows_set = set(r for (r, c) in road_pos if c == col)
        for wr in wire_rows:
            if wr not in road_rows_set and in_bounds(col, wr):
                if em[wr, col]:
                    return (Tool.ROAD, col, wr)
        return None

    # Helper: place zones on both sides
    def try_place_zones(lzc, rzc, wire_col_ref, road_col_ref):
        wire_rows = sorted(r for (r, c) in wire_pos if c == wire_col_ref)
        road_rows_set = set(r for (r, c) in road_pos if c == road_col_ref)
        for zr in wire_rows:
            road_near = any(abs(zr - rr) <= 2 for rr in road_rows_set)
            if not road_near:
                continue
            for zc in [lzc, rzc]:
                if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                    if not zone_too_close(zr, zc) and zone_area_free(zr, zc):
                        return (pick_zone_tool(), zc, zr)
        return None

    # Helper: fill lateral wires from wire spine to left zone col
    def try_lateral_wire(wire_col_ref, dest_col):
        wire_rows = sorted(r for (r, c) in wire_pos if c == wire_col_ref)
        step_dir = -1 if dest_col < wire_col_ref else 1
        for wr in wire_rows:
            for wc in range(wire_col_ref + step_dir, dest_col + step_dir, step_dir):
                if in_bounds(wc, wr):
                    already = wm[wr, wc] or pm[wr, wc]
                    if not already and em[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    if already:
                        continue
                    break
        return None

    # Helper: fill lateral roads from road col to right zone col
    def try_lateral_road(road_col_ref, dest_col):
        wire_rows = sorted(r for (r, c) in wire_pos if c == (road_col_ref - 2))
        step_dir = 1 if dest_col > road_col_ref else -1
        for wr in wire_rows:
            for rc in range(road_col_ref + step_dir, dest_col + step_dir, step_dir):
                if in_bounds(rc, wr):
                    if rm[wr, rc]:
                        continue
                    if em[wr, rc]:
                        return (Tool.ROAD, rc, wr)
                    break
        return None

    # ---- PRIMARY CLUSTER ----
    # 1. Grow wire spine
    r = try_grow_wire_spine(wire_col, tmin, tmax)
    if r: return r

    wire_rows_primary = sorted(r for (r, c) in wire_pos if c == wire_col)
    if not wire_rows_primary:
        return None

    # 2. Build road column
    r = try_grow_road_col(road_col, wire_col)
    if r: return r

    # 3. Place zones
    r = try_place_zones(lzone_col, rzone_col, wire_col, road_col)
    if r: return r

    # 4. Lateral wires to left zones
    r = try_lateral_wire(wire_col, lzone_col)
    if r: return r

    # 5. Lateral roads to right zones
    r = try_lateral_road(road_col, rzone_col)
    if r: return r

    # ---- SECOND CLUSTER (right) when pop >= 150 ----
    if obs.city_pop >= 150:
        wire_col2 = road_col + 10   # 74
        road_col2 = wire_col2 + 2   # 76
        lzone_col2 = wire_col2 - 4  # 70
        rzone_col2 = road_col2 + 4  # 80

        wire_rows2 = sorted(r for (r, c) in wire_pos if c == wire_col2)
        if not wire_rows2:
            # Build horizontal bridge from primary wire col to wire_col2 at plant_cy
            for wc in range(wire_col + 1, wire_col2 + 1):
                already = wm[plant_cy, wc] or pm[plant_cy, wc]
                if not already and in_bounds(wc, plant_cy) and em[plant_cy, wc]:
                    return (Tool.WIRE, wc, plant_cy)
        else:
            r = try_grow_wire_spine(wire_col2, tmin, tmax)
            if r: return r
            r = try_grow_road_col(road_col2, wire_col2)
            if r: return r
            r = try_place_zones(lzone_col2, rzone_col2, wire_col2, road_col2)
            if r: return r
            r = try_lateral_wire(wire_col2, lzone_col2)
            if r: return r
            r = try_lateral_road(road_col2, rzone_col2)
            if r: return r

    # ---- THIRD CLUSTER (left) when pop >= 350 ----
    if obs.city_pop >= 350:
        wire_col3 = wire_col - 10   # 52
        road_col3 = wire_col3 - 2   # 50
        lzone_col3 = road_col3 - 4  # 46
        rzone_col3 = wire_col3 + 4  # 56

        wire_rows3 = sorted(r for (r, c) in wire_pos if c == wire_col3)
        if not wire_rows3:
            for wc in range(wire_col - 1, wire_col3 - 1, -1):
                already = wm[plant_cy, wc] or pm[plant_cy, wc]
                if not already and in_bounds(wc, plant_cy) and em[plant_cy, wc]:
                    return (Tool.WIRE, wc, plant_cy)
        else:
            r = try_grow_wire_spine(wire_col3, tmin, tmax)
            if r: return r
            r = try_grow_road_col(road_col3, wire_col3)
            if r: return r
            r = try_place_zones(lzone_col3, rzone_col3, wire_col3, road_col3)
            if r: return r
            r = try_lateral_wire(wire_col3, lzone_col3)
            if r: return r
            r = try_lateral_road(road_col3, rzone_col3)
            if r: return r

    # ---- FOURTH CLUSTER (far right) when pop >= 600 ----
    if obs.city_pop >= 600:
        wire_col4 = wire_col + 22   # 84
        road_col4 = wire_col4 + 2   # 86
        lzone_col4 = wire_col4 - 4  # 80
        rzone_col4 = road_col4 + 4  # 90

        wire_rows4 = sorted(r for (r, c) in wire_pos if c == wire_col4)
        if not wire_rows4:
            for wc in range(wire_col + 1, wire_col4 + 1):
                already = wm[plant_cy, wc] or pm[plant_cy, wc]
                if not already and in_bounds(wc, plant_cy) and em[plant_cy, wc]:
                    return (Tool.WIRE, wc, plant_cy)
        else:
            r = try_grow_wire_spine(wire_col4, tmin, tmax)
            if r: return r
            r = try_grow_road_col(road_col4, wire_col4)
            if r: return r
            r = try_place_zones(lzone_col4, rzone_col4, wire_col4, road_col4)
            if r: return r

    # Services for high pop
    if obs.city_pop > 500:
        fx, fy = plant_cx - 5, plant_cy - 8
        if in_bounds(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
        px2, py2 = plant_cx + 5, plant_cy + 8
        if in_bounds(px2, py2) and em[py2, px2]:
            return (Tool.POLICESTATION, px2, py2)

    return None

def act(obs, state):
    """
    Closed-loop city builder - reactive version.
    Reads the map each step and extends infrastructure from what already exists.
    Strategy:
    1. Place coal plant near (30, 50)
    2. Grow wire from plant/existing wires toward target zone area
    3. Grow roads from existing roads
    4. Place zones adjacent to road+wire coverage
    5. Add second plant if city grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    has_plant = np.any(pm)
    plant_ys, plant_xs = np.where(pm)
    wire_ys, wire_xs = np.where(wm)
    road_ys, road_xs = np.where(rm)
    res_ys, res_xs = np.where(resm)
    com_ys, com_xs = np.where(comm)
    ind_ys, ind_xs = np.where(indm)

    wire_set = set(zip(wire_ys.tolist(), wire_xs.tolist()))
    road_set = set(zip(road_ys.tolist(), road_xs.tolist()))
    zone_set = set(zip(
        np.concatenate([res_ys, com_ys, ind_ys]).tolist(),
        np.concatenate([res_xs, com_xs, ind_xs]).tolist()
    ))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Primary cluster: plant at (30,50), zones spread right and down
    PLANT_X, PLANT_Y = 30, 50
    # Zone field: columns 34..90, rows 40..70
    ZONE_X_START = 34
    ZONE_X_END = 90
    ZONE_Y_START = 40
    ZONE_Y_END = 70

    # --- Phase 1: Place power plant ---
    if not has_plant:
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    def pick_tool():
        t = max(total_zones, 1)
        if com_count / t < 0.20:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # --- Phase 2: Grow wire reactively from existing wire/plant frontier ---
    # Target: wire spine along row py (horizontal) from plant rightward to ZONE_X_END
    # and vertical spines at intervals

    def is_powered(x, y, r=1):
        """Check if (x,y) is within r of a wire or plant tile."""
        for dr in range(-r, r+1):
            for dc in range(-r, r+1):
                nr, nc = y+dr, x+dc
                if not in_bounds(nc, nr):
                    continue
                if wm[nr, nc] or pm[nr, nc]:
                    return True
        return False

    def is_roaded(x, y, r=2):
        for dr in range(-r, r+1):
            for dc in range(-r, r+1):
                if (y+dr, x+dc) in road_set:
                    return True
        return False

    def wire_frontier_step(target_x, target_y):
        """Find a wire tile adjacent to (target_x, target_y) direction, 
        then step from wire set toward target."""
        if not wire_set and not np.any(pm):
            return None
        # Find closest wire or plant tile to target
        best = None
        best_dist = 99999
        for (wr, wc) in wire_set:
            d = abs(wr - target_y) + abs(wc - target_x)
            if d < best_dist:
                best_dist = d
                best = (wr, wc)
        # Also consider plant tiles
        for i in range(len(plant_ys)):
            wr, wc = int(plant_ys[i]), int(plant_xs[i])
            d = abs(wr - target_y) + abs(wc - target_x)
            if d < best_dist:
                best_dist = d
                best = (wr, wc)
        if best is None:
            return None
        wr, wc = best
        # Step from (wr,wc) toward (target_y, target_x)
        dy = target_y - wr
        dx = target_x - wc
        # Prefer axis with larger delta
        steps = []
        if abs(dy) >= abs(dx):
            sr = 1 if dy > 0 else -1
            steps = [(wr + sr, wc), (wr, wc + (1 if dx > 0 else -1))]
        else:
            sc = 1 if dx > 0 else -1
            steps = [(wr, wc + sc), (wr + (1 if dy > 0 else -1), wc)]
        for (nr, nc) in steps:
            if in_bounds(nc, nr) and em[nr, nc] and not pm[nr, nc]:
                return (Tool.WIRE, nc, nr)
            # If occupied by road, wire on top is ok? No, auto-bulldoze.
            # Only place on empty
        return None

    # Horizontal wire spine at py from px to ZONE_X_END
    # Check if spine is complete
    spine_missing = []
    for wx in range(px + 2, ZONE_X_END + 1):
        if not (wm[py, wx] or pm[py, wx]):
            spine_missing.append(wx)

    if spine_missing:
        # Find leftmost gap adjacent to existing wire/plant
        for wx in spine_missing:
            # Is previous tile wire or plant?
            if wx > 0 and (wm[py, wx-1] or pm[py, wx-1]):
                if em[py, wx]:
                    return (Tool.WIRE, wx, py)
                break
            # Is next tile wire?
            if wx < WORLD_W-1 and (wm[py, wx+1] or pm[py, wx+1]):
                if em[py, wx]:
                    return (Tool.WIRE, wx, py)
                break

    # Vertical wire spines every 6 cols in zone area
    for spine_col in range(ZONE_X_START, ZONE_X_END + 1, 6):
        # Spine from py up to ZONE_Y_START and down to ZONE_Y_END
        for wy in list(range(ZONE_Y_START, py)) + list(range(py+1, ZONE_Y_END+1)):
            if not (wm[wy, spine_col] or pm[wy, spine_col]):
                # Is adjacent tile on spine wired?
                adj_wired = False
                if wy > 0 and (wm[wy-1, spine_col] or pm[wy-1, spine_col]):
                    adj_wired = True
                if wy < WORLD_H-1 and (wm[wy+1, spine_col] or pm[wy+1, spine_col]):
                    adj_wired = True
                if wm[py, spine_col] or pm[py, spine_col]:
                    adj_wired = True  # horizontal spine at py connects
                if adj_wired and em[wy, spine_col]:
                    return (Tool.WIRE, spine_col, wy)

    # --- Phase 3: Grow roads reactively ---
    # Horizontal road lanes: rows py-3, py+3, and every 6 rows in zone area
    road_rows = [py - 3, py + 3]
    for ry in range(ZONE_Y_START + 2, ZONE_Y_END - 2, 6):
        road_rows.append(ry)

    road_col_start = px + 2
    road_col_end = ZONE_X_END + 2

    for rr in road_rows:
        if not in_bounds(road_col_start, rr):
            continue
        # Find rightmost road tile in this row, extend rightward
        row_roads = sorted([c for (r, c) in road_set if r == rr])
        if not row_roads:
            # Start from road_col_start if adjacent to wire
            if is_powered(road_col_start, rr, r=2) or in_bounds(road_col_start-1, rr) and rm[rr, max(0,road_col_start-1)]:
                if em[rr, road_col_start]:
                    return (Tool.ROAD, road_col_start, rr)
            # Connect from adjacent row roads
            for (rr2, rc2) in road_set:
                if abs(rr2 - rr) == 1 and road_col_start <= rc2 <= road_col_end:
                    if in_bounds(rc2, rr) and em[rr, rc2]:
                        return (Tool.ROAD, rc2, rr)
        else:
            mr = max(row_roads)
            if mr < road_col_end:
                nc = mr + 1
                if in_bounds(nc, rr) and em[rr, nc]:
                    return (Tool.ROAD, nc, rr)

    # Vertical connector roads every 6 cols
    for vc in range(road_col_start, road_col_end + 1, 6):
        row_min = min(road_rows) if road_rows else py - 3
        row_max = max(road_rows) if road_rows else py + 3
        # Fill vertical column
        col_roads = sorted([r for (r, c) in road_set if c == vc])
        for vr in range(row_min, row_max + 1):
            if (vr, vc) not in road_set and in_bounds(vc, vr) and em[vr, vc]:
                # Adjacent to existing road?
                adj = any((vr+d, vc) in road_set for d in [-1, 1])
                adj |= any((vr, vc+d) in road_set for d in [-1, 1])
                if adj:
                    return (Tool.ROAD, vc, vr)

    # --- Phase 4: Place zones where road AND wire coverage exists ---
    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    # Scan zone placement candidates in zone area
    # Place zones at centers between road rows and wire spines
    # Zone centers: between road rows, between wire spine cols
    zone_row_centers = []
    sorted_rrows = sorted(set(road_rows))
    for i in range(len(sorted_rrows) - 1):
        mid = (sorted_rrows[i] + sorted_rrows[i+1]) // 2
        zone_row_centers.append(mid)

    zone_col_centers = []
    for sc in range(ZONE_X_START + 3, ZONE_X_END - 2, 6):
        zone_col_centers.append(sc)

    for zr in zone_row_centers:
        for zc in zone_col_centers:
            if not (2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3):
                continue
            if zone_clear(zc, zr) and is_roaded(zc, zr, r=3) and is_powered(zc, zr, r=5):
                return (pick_tool(), zc, zr)

    # Also try reactive scan: find empty 3x3 areas near road+wire
    # Build dilated road/wire masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            r0 = max(0, dy); c0 = max(0, dx)
            r1 = min(WORLD_H, WORLD_H+dy); c1 = min(WORLD_W, WORLD_W+dx)
            sr0 = max(0, -dy); sc0 = max(0, -dx)
            sr1 = min(WORLD_H, WORLD_H-dy); sc1 = min(WORLD_W, WORLD_W-dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            r0 = max(0, dy); c0 = max(0, dx)
            r1 = min(WORLD_H, WORLD_H+dy); c1 = min(WORLD_W, WORLD_W+dx)
            sr0 = max(0, -dy); sc0 = max(0, -dx)
            sr1 = min(WORLD_H, WORLD_H-dy); sc1 = min(WORLD_W, WORLD_W-dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand = em & nbr_road & nbr_wire
    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        # Try multiple candidates
        step_hash = obs.step * 13 + int(tm[py, px]) % 50
        for ki in range(min(30, len(cxs))):
            k = (step_hash + ki * 7) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if 2 <= zy <= WORLD_H-3 and 2 <= zx <= WORLD_W-3:
                if zone_clear(zx, zy):
                    return (pick_tool(), zx, zy)

    # --- Phase 5: Second power plant if city growing ---
    if obs.city_pop > 500 and np.sum(pm) < 9:
        nx2, ny2 = PLANT_X + 50, PLANT_Y
        if in_bounds(nx2, ny2) and em[ny2, nx2]:
            return (Tool.COALPOWER, nx2, ny2)

    # --- Phase 6: Services ---
    if obs.city_pop > 200:
        fx, fy = px + 8, py - 8
        if in_bounds(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
        fx2, fy2 = px + 8, py + 8
        if in_bounds(fx2, fy2) and em[fy2, fx2]:
            return (Tool.POLICESTATION, fx2, fy2)

    # --- Phase 7: Extend wire toward any unserved zone ---
    for (zyr, zxc) in list(zone_set)[:20]:
        if not is_powered(zxc, zyr, r=4):
            result = wire_frontier_step(zxc, zyr)
            if result:
                return result

    # --- Phase 8: Extend road frontier ---
    if len(road_xs) > 0:
        k = (obs.step * 11) % len(road_xs)
        rx, ry = int(road_xs[k]), int(road_ys[k])
        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx + dx, ry + dy
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                if ZONE_X_START <= nx2 <= ZONE_X_END and ZONE_Y_START <= ny2 <= ZONE_Y_END:
                    return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy.
    Reads map each step to decide placement.
    Strategy:
    - Place coal plant at fixed anchor.
    - Extend wire spine vertically from plant, then branch horizontally.
    - Build roads parallel to wire spine.
    - Place zones adjacent to roads, powered via wire branches.
    - Expand outward reactively as population and powered_zones grow.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    # Anchor: plant center
    plant_cx, plant_cy = 54, 50

    has_plant = np.any(pm)

    # Phase 1: place coal power plant
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Gather current positions
    wire_positions = set(zip(*np.where(wm))) if np.any(wm) else set()
    road_positions = set(zip(*np.where(rm))) if np.any(rm) else set()
    res_pos = set(zip(*np.where(res_mask(tm))))
    com_pos = set(zip(*np.where(com_mask(tm))))
    ind_pos = set(zip(*np.where(ind_mask(tm))))
    all_zones = res_pos | com_pos | ind_pos

    res_count = len(res_pos)
    com_count = len(com_pos)
    ind_count = len(ind_pos)

    # Wire spine: column to the right of plant
    wire_col = plant_cx + 3  # col 57
    road_col_L = wire_col - 2  # col 55 (left road)
    road_col_R = wire_col + 2  # col 59 (right road)
    zone_col_L = wire_col - 5  # col 52 (left zones)
    zone_col_R = wire_col + 5  # col 62 (right zones)

    # Vertical span grows with population
    base_span = 10
    extra_span = min(30, obs.city_pop // 30)
    target_span = base_span + extra_span
    tmin = max(2, plant_cy - target_span)
    tmax = min(WORLD_H - 3, plant_cy + target_span)

    # Helper: check if 3x3 area is clear
    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def already_zone_nearby(zr, zc):
        return any(abs(zr - pr) <= 2 and abs(zc - pc) <= 2 for (pr, pc) in all_zones)

    # Wire spine rows in wire_col
    wire_rows_in_col = sorted(r for (r, c) in wire_positions if c == wire_col)

    # Phase 2: build vertical wire spine
    if not wire_rows_in_col:
        # Start wire adjacent to plant
        if em[plant_cy, wire_col]:
            return (Tool.WIRE, wire_col, plant_cy)
        elif em[plant_cy - 1, wire_col]:
            return (Tool.WIRE, wire_col, plant_cy - 1)
    else:
        min_wr = min(wire_rows_in_col)
        max_wr = max(wire_rows_in_col)
        # Extend downward
        if max_wr < tmax:
            nr = max_wr + 1
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if min_wr > tmin:
            nr = min_wr - 1
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    if not wire_rows_in_col:
        return None

    wire_rows_set = set(wire_rows_in_col)

    # Phase 3: build left road column
    road_L_rows = set(r for (r, c) in road_positions if c == road_col_L)
    for wr in wire_rows_in_col:
        if wr not in road_L_rows and 0 <= road_col_L < WORLD_W and em[wr, road_col_L]:
            return (Tool.ROAD, road_col_L, wr)

    # Phase 4: build right road column
    road_R_rows = set(r for (r, c) in road_positions if c == road_col_R)
    for wr in wire_rows_in_col:
        if wr not in road_R_rows and 0 <= road_col_R < WORLD_W and em[wr, road_col_R]:
            return (Tool.ROAD, road_col_R, wr)

    # Phase 5: connect road cols to wire spine with horizontal wires
    # Connect every 3 rows to reduce wire usage
    for wr in wire_rows_in_col:
        if wr % 3 == 0:
            # Left wire bridge: wire_col-1 to road_col_L+1
            for wc in range(wire_col - 1, road_col_L, -1):
                if em[wr, wc]:
                    return (Tool.WIRE, wc, wr)
            # Right wire bridge: wire_col+1 to road_col_R-1
            for wc in range(wire_col + 1, road_col_R):
                if em[wr, wc]:
                    return (Tool.WIRE, wc, wr)

    # Phase 6: place zones adjacent to roads
    for zr in wire_rows_in_col:
        road_L_nearby = any(abs(zr - rr) <= 2 for rr in road_L_rows)
        road_R_nearby = any(abs(zr - rr) <= 2 for rr in road_R_rows)

        for (zc, road_ok) in [(zone_col_L, road_L_nearby), (zone_col_R, road_R_nearby)]:
            if not road_ok:
                continue
            if 2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3:
                if not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                    # Choose zone type: aim ~50% res, ~25% com, ~25% ind
                    total = res_count + com_count + ind_count
                    if total == 0 or ind_count * 4 < res_count:
                        return (Tool.INDUSTRIAL, zc, zr)
                    elif com_count * 4 < res_count:
                        return (Tool.COMMERCIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

    # Phase 7: expand to second pair of zone columns if pop growing
    if obs.city_pop > 200:
        zone_col_L2 = zone_col_L - 5  # col 47
        zone_col_R2 = zone_col_R + 5  # col 67
        road_col_L2 = zone_col_L2 + 2  # col 49
        road_col_R2 = zone_col_R2 - 2  # col 65

        # First extend wires outward to new road columns
        for wr in wire_rows_in_col:
            if wr % 3 == 0:
                for wc in range(road_col_L - 1, road_col_L2, -1):
                    if em[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                for wc in range(road_col_R + 1, road_col_R2 + 1):
                    if em[wr, wc]:
                        return (Tool.WIRE, wc, wr)

        road_L2_rows = set(r for (r, c) in road_positions if c == road_col_L2)
        road_R2_rows = set(r for (r, c) in road_positions if c == road_col_R2)

        for wr in wire_rows_in_col:
            if wr not in road_L2_rows and 0 <= road_col_L2 < WORLD_W and em[wr, road_col_L2]:
                return (Tool.ROAD, road_col_L2, wr)
            if wr not in road_R2_rows and 0 <= road_col_R2 < WORLD_W and em[wr, road_col_R2]:
                return (Tool.ROAD, road_col_R2, wr)

        for zr in wire_rows_in_col:
            road_L2_nearby = any(abs(zr - rr) <= 2 for rr in road_L2_rows)
            road_R2_nearby = any(abs(zr - rr) <= 2 for rr in road_R2_rows)
            for (zc, road_ok) in [(zone_col_L2, road_L2_nearby), (zone_col_R2, road_R2_nearby)]:
                if not road_ok:
                    continue
                if 2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3:
                    if not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                        total = res_count + com_count + ind_count
                        if total == 0 or ind_count * 4 < res_count:
                            return (Tool.INDUSTRIAL, zc, zr)
                        elif com_count * 4 < res_count:
                            return (Tool.COMMERCIAL, zc, zr)
                        else:
                            return (Tool.RESIDENTIAL, zc, zr)

    return None

