                            if wm[ny, nx]:
                                wire_near = True

                if road_near and wire_near:
                    # Not too close to existing zone
                    too_close = any(abs(cy_s - pr) <= 2 and abs(cx_s - pc) <= 2
                                    for (pr, pc) in all_zones)
                    if not too_close:
                        if ind_count / total < 0.2:
                            return (Tool.INDUSTRIAL, cx_s, cy_s)
                        elif com_count / total < 0.3:
                            return (Tool.COMMERCIAL, cx_s, cy_s)
                        else:
                            return (Tool.RESIDENTIAL, cx_s, cy_s)

    return None

def act(obs, state):
    """
    Combined policy:
    - Uses a pre-built plan (from Parent A's approach) for the skeleton
    - Then uses closed-loop reactive placement (from Parent B) to fill gaps
    - Two coal power plants with wire networks
    - Grid road network connecting zones
    - Mixed R/C/I zones in proper ratios
    """

    def build_plan():
        p = []

        # Primary cluster centered at (45, 50)
        # Secondary cluster centered at (85, 50)

        for cx, cy in [(45, 50), (85, 50)]:
            # Coal power plant - place it clearly
            p.append((Tool.COALPOWER, cx - 10, cy))

            # Wire from plant rightward along cy row to connect to zones
            for dx in range(-9, 15):
                p.append((Tool.WIRE, cx + dx, cy))

            # Vertical wire spine at cx+4
            for dy in range(-10, 11):
                p.append((Tool.WIRE, cx + 4, cy + dy))

            # Horizontal roads above and below wire spine
            for dx in range(-8, 16):
                p.append((Tool.ROAD, cx + dx, cy - 4))
                p.append((Tool.ROAD, cx + dx, cy + 4))

            # Vertical roads to connect the horizontal roads
            for dy in range(-4, 5):
                p.append((Tool.ROAD, cx - 6, cy + dy))
                p.append((Tool.ROAD, cx + 2, cy + dy))
                p.append((Tool.ROAD, cx + 10, cy + dy))

            # Additional wire to serve zone rows
            for dx in range(-8, 16):
                p.append((Tool.WIRE, cx + dx, cy - 4))
                p.append((Tool.WIRE, cx + dx, cy + 4))

            # Residential zones (left columns)
            for zy in [cy - 7, cy - 10, cy + 7, cy + 10]:
                for zx in [cx - 5, cx - 2]:
                    p.append((Tool.RESIDENTIAL, zx, zy))

            # Commercial zones (center)
            for zy in [cy - 7, cy + 7]:
                p.append((Tool.COMMERCIAL, cx + 5, zy))

            # Industrial zones (right columns)
            for zy in [cy - 7, cy - 10, cy + 7, cy + 10]:
                p.append((Tool.INDUSTRIAL, cx + 12, zy))

        # Connect two clusters with road
        for x in range(53, 78):
            p.append((Tool.ROAD, x, 50))
            p.append((Tool.WIRE, x, 50))

        # More residential zones near roads
        for cx, cy in [(45, 50), (85, 50)]:
            for zx in [cx - 8, cx - 5, cx - 2, cx + 5, cx + 8, cx + 11]:
                for zy in [cy - 13, cy + 13]:
                    p.append((Tool.RESIDENTIAL, zx, zy))

            # Extra road rows
            for dx in range(-8, 16):
                p.append((Tool.ROAD, cx + dx, cy - 8))
                p.append((Tool.ROAD, cx + dx, cy + 8))

        return p

    # Initialize state
    if "p" not in state:
        state["p"] = build_plan()
        state["i"] = 0

    # Execute pre-built plan first
    if state["i"] < len(state["p"]):
        a = state["p"][state["i"]]
        state["i"] += 1
        tool, x, y = a
        # Clamp to valid range
        x = max(1, min(WORLD_W - 2, x))
        y = max(1, min(WORLD_H - 2, y))
        return (tool, x, y)

    # --- Reactive phase ---
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def pick_tool():
        if com_count / total_zones < 0.25:
            return Tool.COMMERCIAL
        if ind_count / total_zones < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc]:
                    return False
        return True

    # Compute road and wire neighborhoods
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Find empty tiles near both road and wire - good for zones
    cand = em & nbr_road & nbr_wire
    cys, cxs = np.where(cand)

    if len(cxs) > 0:
        # Try to place zones in valid spots
        step_hash = int((obs.step * 17 + int(tm[50, 45]) + int(tm[50, 85])) % max(len(cxs), 1))
        attempts = min(50, len(cxs))
        for attempt in range(attempts):
            k = (step_hash + attempt * 7) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            # Ensure zone fits (3x3, centered)
            if 1 <= zx <= WORLD_W - 2 and 1 <= zy <= WORLD_H - 2:
                if zone_clear(zx, zy):
                    return (pick_tool(), zx, zy)

    # Extend roads from existing road frontier
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        k = int(obs.step * 13) % len(road_xs)
        rx, ry = int(road_xs[k]), int(road_ys[k])
        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx + dx, ry + dy
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                return (Tool.ROAD, nx2, ny2)

    # Extend wires if zones lack power
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        k = int(obs.step * 11) % len(wire_xs)
        wx, wy = int(wire_xs[k]), int(wire_ys[k])
        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = wx + dx, wy + dy
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Variation: horizontal spine instead of vertical, with zones above and below.
    Two neighborhoods side by side, better C/I balance, explicit wire connections.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def has_tile(mask, x, y):
        if 0 <= y < WORLD_H and 0 <= x < WORLD_W:
            return bool(mask[y, x])
        return False

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        all_zone = resm | comm | indm
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone[rr, rc]:
                    return False
        return True

    def zone_present(zr, zc):
        all_zone = resm | comm | indm
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone[rr, rc]:
                        return True
        return False

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        # target: 50% R, 30% C, 20% I
        if com_count / t < 0.30:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Horizontal layout:
    # Power plant at (plant_x, plant_y)
    # Wire spine: horizontal row at wire_row
    # Road row: wire_row + 1
    # Upper zones: wire_row - 3
    # Lower zones: road_row + 3

    plant_x = cx - 20
    plant_y = cy
    wire_row = cy - 1
    road_row = cy      # road right below wire
    upper_zrow = wire_row - 3
    lower_zrow = road_row + 3

    # Spine horizontal extent
    if obs.city_pop < 50:
        spine_half = 10
    elif obs.city_pop < 200:
        spine_half = 18
    elif obs.city_pop < 500:
        spine_half = 28
    else:
        spine_half = 38

    spine_min = max(1, cx - spine_half)
    spine_max = min(WORLD_W - 2, cx + spine_half)
    spine_range = range(spine_min, spine_max + 1)

    # Clamp rows
    wire_row = max(3, min(WORLD_H - 5, wire_row))
    road_row = max(3, min(WORLD_H - 5, road_row))
    upper_zrow = max(2, min(WORLD_H - 3, upper_zrow))
    lower_zrow = max(2, min(WORLD_H - 3, lower_zrow))
    plant_x = max(2, min(WORLD_W - 3, plant_x))
    plant_y = max(2, min(WORLD_H - 3, plant_y))

    # Phase 0: Place coal power plant
    if not np.any(pm):
        return (Tool.COALPOWER, plant_x, plant_y)

    # Phase 1: Wire spine horizontal row
    for dx in spine_range:
        if not has_tile(wm, dx, wire_row) and not has_tile(pm, dx, wire_row):
            if not has_tile(rm, dx, wire_row):
                return (Tool.WIRE, dx, wire_row)

    # Phase 2: Road row adjacent to wire
    for dx in spine_range:
        if not has_tile(rm, dx, road_row) and not has_tile(pm, dx, road_row):
            if not has_tile(wm, dx, road_row):
                return (Tool.ROAD, dx, road_row)

    wire_cols = [c for c in spine_range if wm[wire_row, c]]
    road_cols = [c for c in spine_range if rm[road_row, c]]

    # Phase 3: Place zones above and below spine
    zone_cols = list(range(spine_min + 1, spine_max - 1, 4))

    for zc in zone_cols:
        wire_near = any(abs(zc - wc) <= 3 for wc in wire_cols)
        road_near = any(abs(zc - rc) <= 3 for rc in road_cols)

        if wire_near and road_near:
            # Upper zone (above wire)
            zr = upper_zrow
            if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                return (pick_tool(), zc, zr)

            # Lower zone (below road)
            zr = lower_zrow
            if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                return (pick_tool(), zc, zr)

    # Phase 4: Vertical wires to connect upper zones to wire spine
    for wc in wire_cols:
        for wr in range(wire_row - 1, upper_zrow - 2, -1):
            if 0 <= wr < WORLD_H:
                if wm[wr, wc] or pm[wr, wc]:
                    break
                if em[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                else:
                    break

    # Phase 5: Vertical wires to connect lower zones from road row
    for wc in wire_cols:
        for wr in range(road_row + 1, lower_zrow + 2):
            if 0 <= wr < WORLD_H:
                if wm[wr, wc] or pm[wr, wc]:
                    break
                if em[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif rm[wr, wc]:
                    continue
                else:
                    break

    # Phase 6: Second neighborhood above (if population > 200)
    if obs.city_pop > 200:
        upper2_zrow = upper_zrow - 6
        upper2_zrow = max(2, upper2_zrow)
        wire2_row = upper_zrow - 2
        road2_row = upper_zrow - 1
        wire2_row = max(2, min(WORLD_H - 3, wire2_row))
        road2_row = max(2, min(WORLD_H - 3, road2_row))

        for dx in spine_range:
            if not has_tile(wm, dx, wire2_row) and not has_tile(pm, dx, wire2_row):
                if not has_tile(rm, dx, wire2_row):
                    return (Tool.WIRE, dx, wire2_row)

        for dx in spine_range:
            if not has_tile(rm, dx, road2_row) and not has_tile(pm, dx, road2_row):
                if not has_tile(wm, dx, road2_row):
                    return (Tool.ROAD, dx, road2_row)

        wire2_cols = [c for c in spine_range if wm[wire2_row, c]]
        road2_cols = [c for c in spine_range if rm[road2_row, c]]

        for zc in zone_cols:
            w2_near = any(abs(zc - wc) <= 3 for wc in wire2_cols)
            r2_near = any(abs(zc - rc) <= 3 for rc in road2_cols)
            if w2_near and r2_near:
                zr = upper2_zrow
                if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                    return (pick_tool(), zc, zr)

    # Phase 7: Second coal plant if population large
    if obs.city_pop > 300 and np.sum(pm) < 9:
        px2 = plant_x + 40
        py2 = plant_y
        px2 = max(2, min(WORLD_W - 3, px2))
        if em[py2, px2]:
            return (Tool.COALPOWER, px2, py2)

    # Phase 8: Cross-roads for connectivity
    if obs.city_pop > 100:
        for rc in [spine_min + 2, cx, spine_max - 2]:
            if 0 <= rc < WORLD_W:
                for rr in range(upper_zrow - 1, lower_zrow + 2):
                    if 0 <= rr < WORLD_H and em[rr, rc] and not pm[rr, rc]:
                        return (Tool.ROAD, rc, rr)

    return None

def act(obs, state):
    """
    Closed-loop policy: each step reads the current map and decides
    the next action based on what's actually there.

    Strategy:
    - Place a coal power plant first
    - Grow a wire spine rightward from the plant
    - Grow a road spine parallel to the wire
    - Place zones adjacent to roads, powered by nearby wires
    - Add vertical road/wire branches to connect zones
    """
    tm = obs.tile_map
    step = obs.step

    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    # Scan current state
    plant_yx = list(zip(*np.where(pm))) if np.any(pm) else []
    wire_yx = list(zip(*np.where(wm))) if np.any(wm) else []
    road_yx = list(zip(*np.where(rm))) if np.any(rm) else []
    res_yx = list(zip(*np.where(resm))) if np.any(resm) else []
    com_yx = list(zip(*np.where(comm))) if np.any(comm) else []
    ind_yx = list(zip(*np.where(indm))) if np.any(indm) else []

    res_count = len(res_yx)
    com_count = len(com_yx)
    ind_count = len(ind_yx)
    zone_count = res_count + com_count + ind_count

    # Configuration
    PLANT_X, PLANT_Y = 10, 50  # power plant center
    WIRE_ROW = 50               # horizontal wire spine row
    ROAD_ROW_A = 47             # road above
    ROAD_ROW_B = 53             # road below
    WIRE_START_X = 14           # wire starts right of plant
    ROAD_START_X = 14
    SPINE_END_X = 110           # how far right we go

    # Helper: check if 3x3 area around (cy, cx) is clear for a zone
    def can_place_zone(cy, cx):
        for dy in [-1, 0, 1]:
            for dx in [-1, 0, 1]:
                ny, nx = cy + dy, cx + dx
                if ny < 0 or ny >= WORLD_H or nx < 0 or nx >= WORLD_W:
                    return False
                if not em[ny, nx]:
                    return False
        return True

    def has_road_nearby(cy, cx, radius=3):
        for ry, rx in road_yx:
            if abs(ry - cy) <= radius and abs(rx - cx) <= radius:
                return True
        return False

    def has_wire_nearby(cy, cx, radius=5):
        for wy, wx in wire_yx:
            if abs(wy - cy) <= radius and abs(wx - cx) <= radius:
                return True
        # also check if plant nearby
        for py, px in plant_yx:
            if abs(py - cy) <= radius and abs(px - cx) <= radius:
                return True
        return False

    def pick_zone_type():
        total = zone_count + 1
        if res_count / total < 0.5:
            return Tool.RESIDENTIAL
        elif com_count / total < 0.25:
            return Tool.COMMERCIAL
        elif ind_count / total < 0.25:
            return Tool.INDUSTRIAL
        else:
            return Tool.RESIDENTIAL

    # --- Phase 1: Place power plant if none exists ---
    if not plant_yx:
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    # --- Phase 2: Extend wire spine rightward from plant ---
    # Find rightmost wire on WIRE_ROW
    wire_on_spine = [wx for (wy, wx) in wire_yx if wy == WIRE_ROW]
    if wire_on_spine:
        max_wire_x = max(wire_on_spine)
    else:
        max_wire_x = WIRE_START_X - 1

    # Check if plant is adjacent to wire start
    # Plant at (PLANT_Y, PLANT_X), footprint x: PLANT_X-1..PLANT_X+1
    # Wire should start at PLANT_X + 2 or so
    if max_wire_x < SPINE_END_X:
        next_wire_x = max_wire_x + 1
        if next_wire_x < WORLD_W:
            # Don't place wire on plant tiles
            if not pm[WIRE_ROW, next_wire_x]:
                return (Tool.WIRE, next_wire_x, WIRE_ROW)

    # --- Phase 3: Extend road spines ---
    for road_row in [ROAD_ROW_A, ROAD_ROW_B]:
        road_on_spine = [rx for (ry, rx) in road_yx if ry == road_row]
        if road_on_spine:
            max_road_x = max(road_on_spine)
        else:
            max_road_x = ROAD_START_X - 1

        if max_road_x < SPINE_END_X:
            next_road_x = max_road_x + 1
            if next_road_x < WORLD_W:
                if not pm[road_row, next_road_x]:
                    return (Tool.ROAD, next_road_x, road_row)

    # --- Phase 4: Add vertical connectors between road rows and wire at intervals ---
    # Every 6 cols, connect road rows to wire spine with roads
    for conn_x in range(ROAD_START_X, SPINE_END_X + 1, 6):
        if conn_x >= WORLD_W:
            break
        # Connect ROAD_ROW_A to WIRE_ROW (rows 47..50)
        for conn_y in range(ROAD_ROW_A, WIRE_ROW + 1):
            if not rm[conn_y, conn_x] and not wm[conn_y, conn_x] and not pm[conn_y, conn_x]:
                if em[conn_y, conn_x]:
                    return (Tool.ROAD, conn_x, conn_y)
        # Connect WIRE_ROW to ROAD_ROW_B (rows 50..53)
        for conn_y in range(WIRE_ROW, ROAD_ROW_B + 1):
            if not rm[conn_y, conn_x] and not wm[conn_y, conn_x] and not pm[conn_y, conn_x]:
                if em[conn_y, conn_x]:
                    return (Tool.ROAD, conn_x, conn_y)

    # --- Phase 5: Place zones adjacent to roads, powered ---
    # Zone rows: above ROAD_ROW_A and below ROAD_ROW_B, spaced by 3
    zone_rows_above = [ROAD_ROW_A - 2, ROAD_ROW_A - 5, ROAD_ROW_A - 8,
                       ROAD_ROW_A - 11, ROAD_ROW_A - 14, ROAD_ROW_A - 17]
    zone_rows_below = [ROAD_ROW_B + 2, ROAD_ROW_B + 5, ROAD_ROW_B + 8,
                       ROAD_ROW_B + 11, ROAD_ROW_B + 14, ROAD_ROW_B + 17]
    zone_cols = list(range(ROAD_START_X + 2, SPINE_END_X - 1, 6))

    for zr in zone_rows_above + zone_rows_below:
        for zc in zone_cols:
            if zr < 2 or zr >= WORLD_H - 2 or zc < 2 or zc >= WORLD_W - 2:
                continue
            # Check if a zone already nearby
            already = any(
                abs(zr - yr) <= 2 and abs(zc - xr) <= 2
                for (yr, xr) in res_yx + com_yx + ind_yx
            )
            if already:
                continue
            if can_place_zone(zr, zc) and has_road_nearby(zr, zc, 3) and has_wire_nearby(zr, zc, 6):
                return (pick_zone_type(), zc, zr)

    # --- Phase 6: Add vertical wire branches to power zones ---
    for zc in zone_cols:
        # Wire from WIRE_ROW upward to reach upper zones
        for zr in zone_rows_above:
            if zr < 0 or zr >= WORLD_H:
                continue
            # Check if wire already reaches there
            if not has_wire_nearby(zr, zc, 2):
                # Place wire vertically from wire row up
                for wy in range(WIRE_ROW - 1, zr - 1, -1):
                    if 0 <= wy < WORLD_H and not wm[wy, zc] and not rm[wy, zc] and not pm[wy, zc]:
                        if em[wy, zc]:
                            return (Tool.WIRE, zc, wy)
                        break  # blocked, stop

        # Wire from WIRE_ROW downward to reach lower zones
        for zr in zone_rows_below:
            if zr < 0 or zr >= WORLD_H:
                continue
            if not has_wire_nearby(zr, zc, 2):
                for wy in range(WIRE_ROW + 1, zr + 2):
                    if 0 <= wy < WORLD_H and not wm[wy, zc] and not rm[wy, zc] and not pm[wy, zc]:
                        if em[wy, zc]:
                            return (Tool.WIRE, zc, wy)
                        break

    # --- Phase 7: Second power plant on right side if large city ---
    if obs.city_pop > 500 or (obs.step > obs.n_steps // 2 and len(plant_yx) < 2):
        rp_x, rp_y = 100, 50
        # Check if right plant area is reasonable
        if not any(abs(py - rp_y) <= 2 and abs(px - rp_x) <= 2 for (py, px) in plant_yx):
            return (Tool.COALPOWER, rp_x, rp_y)

    # --- Phase 8: Fill gaps in roads ---
    for road_row in [ROAD_ROW_A, ROAD_ROW_B]:
        for rx_val in range(ROAD_START_X, SPINE_END_X + 1):
            if rx_val >= WORLD_W:
                break
            if not rm[road_row, rx_val] and not pm[road_row, rx_val]:
                if em[road_row, rx_val]:
                    return (Tool.ROAD, rx_val, road_row)

    # --- Phase 9: Extend zones further if population growing ---
    if obs.city_pop > 200:
        extra_rows = [ROAD_ROW_A - 20, ROAD_ROW_A - 23, ROAD_ROW_B + 20, ROAD_ROW_B + 23]
        for zr in extra_rows:
            for zc in zone_cols:
                if zr < 2 or zr >= WORLD_H - 2 or zc < 2 or zc >= WORLD_W - 2:
                    continue
                already = any(
                    abs(zr - yr) <= 2 and abs(zc - xr) <= 2
                    for (yr, xr) in res_yx + com_yx + ind_yx
                )
                if not already and can_place_zone(zr, zc) and has_road_nearby(zr, zc, 4):
                    return (pick_zone_type(), zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Phase 0: Place coal power plant
    - Phase 1: Extend wires from plant outward
    - Phase 2: Extend roads adjacent to wires
    - Phase 3: Place zones (R/C/I) adjacent to roads with power nearby
    - React to actual tile_map each step
    """

    tile_map = obs.tile_map

    # Helper: check bounds
    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Phase tracking
    if "phase" not in state:
        state["phase"] = 0
        state["plant_x"] = 20
        state["plant_y"] = 50
        state["zone_cycle"] = 0

    phase = state["phase"]

    # --- Phase 0: Place the power plant ---
    if phase == 0:
        px, py = state["plant_x"], state["plant_y"]
        state["phase"] = 1
        return (Tool.COALPOWER, px, py)

    # --- Phase 1: Extend wires from plant area rightward/outward ---
    if phase == 1:
        # Find all wire/plant tiles, extend wire to the right
        wm = wire_mask(tile_map)
        pm = plant_mask(tile_map)
        powered = wm | pm

        # Find rightmost powered tile in middle row band (y=48..52)
        best_x = -1
        best_y = 50
        for y in range(45, 56):
            for x in range(WORLD_W - 1, -1, -1):
                if powered[y, x]:
                    if x > best_x:
                        best_x = x
                        best_y = y
                    break

        if best_x < 0:
            # Plant may not show as wire yet, just place wire next to plant
            px, py = state["plant_x"], state["plant_y"]
            return (Tool.WIRE, px + 2, py)

        # Extend wire rightward if we haven't reached far enough
        if best_x < 100:
            # Place wire to the right
            nx, ny = best_x + 1, best_y
            if in_bounds(nx, ny) and not powered[ny, nx]:
                return (Tool.WIRE, nx, ny)
            else:
                # Already wired there, move to next phase
                state["phase"] = 2
        else:
            state["phase"] = 2

        return None

    # --- Phase 2: Place roads adjacent to wires (vertical roads through wire corridor) ---
    if phase == 2:
        wm = wire_mask(tile_map)
        rm = road_mask(tile_map)

        # Find wire tiles and place roads adjacent (parallel corridor)
        # Strategy: for each wire column, ensure road exists at wire_y+1 or wire_y-1
        # Scan for wires, place road nearby if missing

        # Find a wire tile that doesn't have a road neighbor
        for x in range(15, 105):
            for y in range(40, 62):
                if wm[y, x]:
                    # Check if there's a road at y+2 (give space for zones)
                    road_y = y + 2
                    if in_bounds(x, road_y) and not rm[road_y, x]:
                        return (Tool.ROAD, x, road_y)
                    road_y2 = y - 2
                    if in_bounds(x, road_y2) and not rm[road_y2, x]:
                        return (Tool.ROAD, x, road_y2)

        state["phase"] = 3
        return None

    # --- Phase 3: Place zones reactively ---
    # Also maintain infrastructure: extend wires/roads as needed

    wm = wire_mask(tile_map)
    pm = plant_mask(tile_map)
    rm = road_mask(tile_map)
    em = empty_mask(tile_map)

    powered = wm | pm

    # First: ensure we have a second power plant if population is growing
    if obs.city_pop > 300 and not state.get("plant2_placed", False):
        state["plant2_placed"] = True
        return (Tool.COALPOWER, 95, 50)

    # Connect second plant with wires if placed
    if state.get("plant2_placed") and not state.get("plant2_wired", False):
        # Check if plant2 area has wires going left
        if powered[50, 93]:
            state["plant2_wired"] = True
        else:
            # Extend wire leftward from plant2
            for x in range(93, 70, -1):
                if powered[50, x]:
                    # Extend right from here
                    if not powered[50, x + 1] and in_bounds(x + 1, 50):
                        return (Tool.WIRE, x + 1, 50)
                    break
            else:
                return (Tool.WIRE, 93, 50)

    # Add vertical wire spines periodically
    if not state.get("vspines_done", False):
        # Place vertical wires every 10 columns to power more zones
        for x in range(25, 100, 10):
            for y in range(38, 63):
                if not powered[y, x] and in_bounds(x, y):
                    # Check if there's a horizontal wire at y=50
                    if powered[50, x]:
                        return (Tool.WIRE, x, y)
        state["vspines_done"] = True

    # Add more roads: vertical roads for zone access
    if not state.get("vroads_done", False):
        for x in range(25, 100, 10):
            for y in range(38, 63):
                if not rm[y, x] and in_bounds(x, y):
                    if rm[y, x-1] or rm[y, x+1] or rm[y-1, x] or rm[y+1, x]:
                        return (Tool.ROAD, x, y)
        state["vroads_done"] = True

    # Place zones: scan for empty 3x3 areas adjacent to roads with power nearby
    zone_types = [Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.INDUSTRIAL]
    cycle = state["zone_cycle"]

    # Scan for good zone placement spots
    best = None
    best_score = -1

    for y in range(40, 60, 3):
        for x in range(15, 108, 3):
            cx, cy = x, y  # center of potential 3x3 zone

            # Check 3x3 area is mostly empty
            empty_count = 0
            for dy in range(-1, 2):
                for dx in range(-1, 2):
                    nx, ny = cx + dx, cy + dy
                    if in_bounds(nx, ny) and em[ny, nx]:
                        empty_count += 1

            if empty_count < 5:
                continue

            # Check road access (within 2 tiles)
            has_road = False
            for dy in range(-2, 3):
                for dx in range(-2, 3):
                    nx, ny = cx + dx, cy + dy
                    if in_bounds(nx, ny) and rm[ny, nx]:
                        has_road = True
                        break
                if has_road:
                    break

            if not has_road:
                continue

            # Check power (within 3 tiles)
            has_power = False
            for dy in range(-3, 4):
                for dx in range(-3, 4):
                    nx, ny = cx + dx, cy + dy
                    if in_bounds(nx, ny) and powered[ny, nx]:
                        has_power = True
                        break
                if has_power:
                    break

            if not has_power:
                continue

            score = empty_count + (1 if has_power else 0) + (1 if has_road else 0)
            if score > best_score:
                best_score = score
                best = (cx, cy)

    if best is not None:
        cx, cy = best
        zone = zone_types[cycle % 3]
        state["zone_cycle"] = (cycle + 1) % 3

        # Bias zone type by position
        if cx < 45:
            zone = Tool.RESIDENTIAL
        elif cx < 75:
            zone = Tool.COMMERCIAL
        else:
            zone = Tool.INDUSTRIAL

        return (zone, cx, cy)

    # Fallback: extend infrastructure
    # Try to extend horizontal wire
    for x in range(15, 102):
        if powered[50, x] and not powered[50, x+1] and in_bounds(x+1, 50):
            return (Tool.WIRE, x+1, 50)

    # Try to extend road
    for x in range(15, 102):
        if rm[52, x] and not rm[52, x+1] and in_bounds(x+1, 52):
            return (Tool.ROAD, x+1, 52)

    # Add services if we have enough zones
    if obs.city_pop > 500 and not state.get("services_placed", False):
        state["services_placed"] = True
        return (Tool.FIRESTATION, 60, 45)

    if obs.city_pop > 600 and not state.get("police_placed", False):
        state["police_placed"] = True
        return (Tool.POLICESTATION, 60, 55)

    return None

def act(obs, state):
    """
    Closed-loop policy: each step reads tile_map and places the next
    logical piece based on what already exists.

    Layout concept:
      - Coal plant at (47, 50)
      - Wire spine at col 50, running vertically
      - Road at col 51 (right of wire)
      - Road at col 49 (left of wire) 
      - RES zones at col 54 (right side)
      - IND zones at col 46 (left side)
      - COM zones alternating
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    # Key columns
    PLANT_CX, PLANT_CY = 47, 50
    WIRE_COL = 50
    ROAD_R = 51   # road right of wire
    ROAD_L = 49   # road left of wire
    ZONE_R = 54   # zone centers right
    ZONE_L = 46   # zone centers left

    # Vertical range based on current city size
    pop = obs.city_pop
    half_span = 8 + min(20, pop // 20)
    Y_MIN = max(3, PLANT_CY - half_span)
    Y_MAX = min(WORLD_H - 4, PLANT_CY + half_span)

    has_plant = np.any(pm)
    has_wire = np.any(wm)

    # --- Phase 1: Place coal plant ---
    if not has_plant:
        return (Tool.COALPOWER, PLANT_CX, PLANT_CY)

    # --- Phase 2: Build wire spine adjacent to plant ---
    wire_col_rows = sorted(r for r in range(WORLD_H) if wm[r, WIRE_COL])

    if not wire_col_rows:
        # Start wire at plant center y
        if em[PLANT_CY, WIRE_COL]:
            return (Tool.WIRE, WIRE_COL, PLANT_CY)
        else:
            # Find nearest empty in wire col
            for dy in range(1, 5):
                for sign in [0, 1, -1]:
                    ny = PLANT_CY + sign * dy
                    if 0 <= ny < WORLD_H and em[ny, WIRE_COL]:
                        return (Tool.WIRE, WIRE_COL, ny)
    else:
        # Extend wire spine downward then upward
        max_wr = max(wire_col_rows)
        min_wr = min(wire_col_rows)
        if max_wr < Y_MAX:
            nr = max_wr + 1
            if 0 <= nr < WORLD_H and (em[nr, WIRE_COL] or wm[nr, WIRE_COL]):
                return (Tool.WIRE, WIRE_COL, nr)
        if min_wr > Y_MIN:
            nr = min_wr - 1
            if 0 <= nr < WORLD_H and (em[nr, WIRE_COL] or wm[nr, WIRE_COL]):
                return (Tool.WIRE, WIRE_COL, nr)

    wire_rows_set = set(wire_col_rows)

    # --- Phase 3: Build road columns along wire ---
    road_r_rows = set(r for r in range(WORLD_H) if rm[r, ROAD_R])
    road_l_rows = set(r for r in range(WORLD_H) if rm[r, ROAD_L])

    # Right road: fill any wire row that lacks road
    for wr in sorted(wire_col_rows):
        if wr not in road_r_rows and 0 <= ROAD_R < WORLD_W:
            if em[wr, ROAD_R]:
                return (Tool.ROAD, ROAD_R, wr)
    # Left road
    for wr in sorted(wire_col_rows):
        if wr not in road_l_rows and 0 <= ROAD_L >= 0:
            if em[wr, ROAD_L]:
                return (Tool.ROAD, ROAD_L, wr)

    # --- Helper: check zone area is placeable ---
    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    # Check existing zones
    rzm = res_mask(tm)
    czm = com_mask(tm)
    izm = ind_mask(tm)

    res_rows_r = set(r for r in range(WORLD_H) if rzm[r, ZONE_R] or 
                     (ZONE_R+1 < WORLD_W and rzm[r, ZONE_R+1]) or
                     (ZONE_R-1 >= 0 and rzm[r, ZONE_R-1]))
    com_rows_r = set(r for r in range(WORLD_H) if czm[r, ZONE_R] or 
                     (ZONE_R+1 < WORLD_W and czm[r, ZONE_R+1]) or
                     (ZONE_R-1 >= 0 and czm[r, ZONE_R-1]))
    ind_rows_l = set(r for r in range(WORLD_H) if izm[r, ZONE_L] or
                     (ZONE_L+1 < WORLD_W and izm[r, ZONE_L+1]) or
                     (ZONE_L-1 >= 0 and izm[r, ZONE_L-1]))

    zone_rows_r = res_rows_r | com_rows_r

    res_count = int(np.sum(rzm))
    com_count = int(np.sum(czm))
    ind_count = int(np.sum(izm))

    # --- Phase 4: Place zones where road and wire both exist ---
    # We need a bridge road from ROAD_R to ZONE_R (cols 51..54 = 3 cols apart, need roads at 52,53)
    # Actually ZONE_R=54, ROAD_R=51. Zone center at col 54 touches road at col 51 only if span <=3.
    # 54-51=3, so zone at col 54 has left edge at 53. Road at 51 is 2 away. Need bridging road at 52,53? 
    # Let's try ZONE_R=53 to be adjacent to ROAD_R=51 (zone spans 52..54 so left edge 52, road at 51 = adjacent).
    # Actually let's just be smarter: use zone center col 54, but add road at 52 and 53 as bridges.

    # Place zones right side - need road bridge
    for wr in sorted(wire_col_rows):
        road_nearby = wr in road_r_rows
        if not road_nearby:
            continue
        # Check if lateral road bridge exists
        bridge_ok = all(not em[wr, c] == False for c in range(ROAD_R+1, ZONE_R))
        # Actually check if road or wire at bridge cols
        bridge_exists = all(rm[wr, c] or not em[wr, c] for c in range(ROAD_R+1, ZONE_R))
        # Simpler: lay road at cols 52, 53
        for bc in range(ROAD_R + 1, ZONE_R):
            if 0 <= bc < WORLD_W and em[wr, bc]:
                return (Tool.ROAD, bc, wr)
        # Zone center
        if zone_area_free(wr, ZONE_R) and wr not in zone_rows_r:
            # Alternate COM and RES
            if com_count * 3 < res_count:
                return (Tool.COMMERCIAL, ZONE_R, wr)
            else:
                return (Tool.RESIDENTIAL, ZONE_R, wr)

    # Place zones left side (IND)
    for wr in sorted(wire_col_rows):
        road_nearby = wr in road_l_rows
        if not road_nearby:
            continue
        # Bridge road left
        for bc in range(ZONE_L + 1, ROAD_L):
            if 0 <= bc < WORLD_W and em[wr, bc]:
                return (Tool.ROAD, bc, wr)
        if zone_area_free(wr, ZONE_L) and wr not in ind_rows_l:
            if ind_count * 4 < res_count + 1:
                return (Tool.INDUSTRIAL, ZONE_L, wr)
            else:
                return (Tool.RESIDENTIAL, ZONE_L, wr)

    # --- Phase 5: Second cluster if population growing ---
    if pop > 150:
        # Second wire column further right
        WIRE_COL2 = 62
        ROAD_R2 = 63
        ZONE_R2 = 66

        wire2_rows = sorted(r for r in range(WORLD_H) if wm[r, WIRE_COL2])

        if not wire2_rows:
            # Lay horizontal wire from WIRE_COL to WIRE_COL2 at center
            for wc in range(WIRE_COL + 1, WIRE_COL2 + 1):
                if 0 <= wc < WORLD_W and em[PLANT_CY, wc]:
                    return (Tool.WIRE, wc, PLANT_CY)
        else:
            max_w2 = max(wire2_rows)
            min_w2 = min(wire2_rows)
            if max_w2 < Y_MAX:
                nr = max_w2 + 1
                if em[nr, WIRE_COL2] or wm[nr, WIRE_COL2]:
                    return (Tool.WIRE, WIRE_COL2, nr)
            if min_w2 > Y_MIN:
                nr = min_w2 - 1
                if em[nr, WIRE_COL2] or wm[nr, WIRE_COL2]:
                    return (Tool.WIRE, WIRE_COL2, nr)

            road2_rows = set(r for r in range(WORLD_H) if rm[r, ROAD_R2])
            for wr in sorted(wire2_rows):
                if wr not in road2_rows and em[wr, ROAD_R2]:
                    return (Tool.ROAD, ROAD_R2, wr)

            res2_rows = set(r for r in range(WORLD_H) 
                           if (rzm[r, ZONE_R2] or czm[r, ZONE_R2] or
                               (ZONE_R2+1 < WORLD_W and (rzm[r, ZONE_R2+1] or czm[r, ZONE_R2+1])) or
                               (ZONE_R2-1 >= 0 and (rzm[r, ZONE_R2-1] or czm[r, ZONE_R2-1]))))

            for wr in sorted(wire2_rows):
                if wr not in road2_rows:
                    continue
                for bc in range(ROAD_R2 + 1, ZONE_R2):
                    if 0 <= bc < WORLD_W and em[wr, bc]:
                        return (Tool.ROAD, bc, wr)
                if zone_area_free(wr, ZONE_R2) and wr not in res2_rows:
                    if com_count * 3 < res_count:
                        return (Tool.COMMERCIAL, ZONE_R2, wr)
                    else:
                        return (Tool.RESIDENTIAL, ZONE_R2, wr)

    # --- Phase 6: Second power plant if needed ---
    if pop > 400 and not state.get("plant2", False):
        P2X, P2Y = 60, 50
        ok = all(em[P2Y + dr, P2X + dc] 
                 for dr in [-1,0,1] for dc in [-1,0,1]
                 if 0 <= P2Y+dr < WORLD_H and 0 <= P2X+dc < WORLD_W)
        if ok:
            state["plant2"] = True
            return (Tool.COALPOWER, P2X, P2Y)

    return None

def act(obs, state):
    """
    Hybrid policy combining best ideas from both parents:
    - Dynamic spine extent based on population (Parent B)
    - Multi-cluster expansion (Parent A)
    - Reactive closed-loop reading of tile_map (both)
    - Better zone placement with wire+road checks (Parent B)
    - Second power plant for large cities (Parent B)
    - Lateral wire and road extensions (both)
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    all_zone_mask = resm | comm | indm

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    # Phase 1: Place first coal power plant
    if not np.any(pm):
        return (Tool.COALPOWER, cx - 8, cy)

    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Main cluster geometry
    wire_col = plant_cx + 4
    road_col = wire_col + 2
    left_zone_col = wire_col - 3
    right_zone_col = road_col + 3

    wire_col = max(2, min(WORLD_W - 3, wire_col))
    road_col = max(2, min(WORLD_W - 3, road_col))
    left_zone_col = max(2, min(WORLD_W - 3, left_zone_col))
    right_zone_col = max(2, min(WORLD_W - 3, right_zone_col))

    # Dynamic spine extent
    if obs.city_pop < 100:
        spine_extent = 10
    elif obs.city_pop < 300:
        spine_extent = 16
    elif obs.city_pop < 600:
        spine_extent = 22
    else:
        spine_extent = 30

    target_min = max(1, cy - spine_extent)
    target_max = min(WORLD_H - 2, cy + spine_extent)

    wire_rows_on_spine = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])
    road_rows_on_col = sorted([r for r in range(WORLD_H) if rm[r, road_col]])
    road_rows_set = set(road_rows_on_col)

    # Phase 2: Start wire adjacent to plant
    if not wire_rows_on_spine:
        for dy in range(0, 6):
            for nr in [plant_cy + dy, plant_cy - dy]:
                if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                    return (Tool.WIRE, wire_col, nr)
        return None

    min_wire_row = min(wire_rows_on_spine)
    max_wire_row = max(wire_rows_on_spine)

    # Phase 3: Extend wire spine downward
    if max_wire_row < target_max:
        nr = max_wire_row + 1
        if nr < WORLD_H and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Phase 4: Extend wire spine upward
    if min_wire_row > target_min:
        nr = min_wire_row - 1
        if nr >= 0 and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Phase 5: Build road column along wire spine
    for r in wire_rows_on_spine:
        if 0 <= r < WORLD_H and 0 <= road_col < WORLD_W:
            if not rm[r, road_col] and em[r, road_col]:
                return (Tool.ROAD, road_col, r)

    # Phase 6: Place zones along the corridor
    zone_rows = list(range(max(1, target_min), min(WORLD_H - 1, target_max + 1), 3))

    for zr in zone_rows:
        wire_near = any(abs(zr - wr) <= 2 for wr in wire_rows_on_spine)
        road_near = any(abs(zr - rr) <= 2 for rr in road_rows_on_col)

        if wire_near and road_near:
            # Try left zone
            zc = left_zone_col
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc, 5) and has_road_nearby(zr, zc, 5):
                    return (pick_tool(), zc, zr)
                elif has_wire_nearby(zr, zc, 5):
                    return (Tool.RESIDENTIAL, zc, zr)

            # Try right zone
            zc = right_zone_col
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_road_nearby(zr, zc, 5) and has_wire_nearby(zr, zc, 6):
                    return (pick_tool(), zc, zr)

    # Phase 7: Lateral wires from spine to left zones
    for wr in wire_rows_on_spine:
        for wc in range(wire_col - 1, max(left_zone_col - 2, 0), -1):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc]:
                    break

    # Phase 8: Road extensions to reach right zones
    for rr in wire_rows_on_spine:
        if not rm[rr, road_col]:
            continue
        for rc in range(road_col + 1, right_zone_col + 2):
            if 0 <= rc < WORLD_W:
                if rm[rr, rc]:
                    break
                if em[rr, rc] and not pm[rr, rc]:
                    return (Tool.ROAD, rc, rr)
                elif not em[rr, rc]:
                    break

    # Phase 9: Wire extensions to right zone for power
    for wr in wire_rows_on_spine:
        for wc in range(wire_col + 1, right_zone_col + 2):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc] and not rm[wr, wc]:
                    break

    # Phase 10: Second power plant when pop grows
    if obs.city_pop > 350 and int(np.sum(pm)) < 9:
        px2, py2 = plant_cx + 20, plant_cy
        if 2 <= py2 <= WORLD_H - 3 and 2 <= px2 <= WORLD_W - 3:
            # Check plant area is clear
            area_clear = True
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if not (em[py2 + dr, px2 + dc] or pm[py2 + dr, px2 + dc]):
                        area_clear = False
            if area_clear:
                return (Tool.COALPOWER, px2, py2)

    # Phase 11: Second cluster to the right when pop >= 200
    if obs.city_pop >= 200:
        wire_col2 = road_col + 8
        road_col2 = wire_col2 + 2
        left_zone_col2 = wire_col2 - 3
        right_zone_col2 = road_col2 + 3

        wire_col2 = max(2, min(WORLD_W - 3, wire_col2))
        road_col2 = max(2, min(WORLD_W - 3, road_col2))
        left_zone_col2 = max(2, min(WORLD_W - 3, left_zone_col2))
        right_zone_col2 = max(2, min(WORLD_W - 3, right_zone_col2))

        wire_rows2 = sorted([r for r in range(WORLD_H) if wm[r, wire_col2]])
        road_rows2 = set(r for r in range(WORLD_H) if rm[r, road_col2])

        if not wire_rows2:
            # Build horizontal wire bridge from main spine to cluster2
            for wc in range(wire_col + 1, wire_col2 + 1):
                if 0 <= wc < WORLD_W:
                    if not wm[plant_cy, wc] and em[plant_cy, wc]:
                        return (Tool.WIRE, wc, plant_cy)
                    elif not em[plant_cy, wc] and not wm[plant_cy, wc]:
                        break
        else:
            min_wr2 = min(wire_rows2)
            max_wr2 = max(wire_rows2)

            if max_wr2 < target_max:
                nr = max_wr2 + 1
                if nr < WORLD_H and em[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > target_min:
                nr = min_wr2 - 1
                if nr >= 0 and em[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)

            for wr in wire_rows2:
                if wr not in road_rows2 and em[wr, road_col2]:
                    return (Tool.ROAD, road_col2, wr)

            for zr in zone_rows:
                wire_near2 = any(abs(zr - wr) <= 2 for wr in wire_rows2)
                road_near2 = any(abs(zr - rr) <= 2 for rr in road_rows2)
                if wire_near2 and road_near2:
                    for zc in [left_zone_col2, right_zone_col2]:
                        if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                            if has_wire_nearby(zr, zc, 6) and has_road_nearby(zr, zc, 5):
                                return (pick_tool(), zc, zr)

            for wr in wire_rows2:
                for wc in range(wire_col2 - 1, max(left_zone_col2 - 2, 0), -1):
                    if 0 <= wc < WORLD_W:
                        if wm[wr, wc]: break
                        if em[wr, wc] and not pm[wr, wc]:
                            return (Tool.WIRE, wc, wr)
                        elif not em[wr, wc]: break

            for wr in wire_rows2:
                if not rm[wr, road_col2]: continue
                for rc in range(road_col2 + 1, right_zone_col2 + 2):
                    if 0 <= rc < WORLD_W:
                        if rm[wr, rc]: break
                        if em[wr, rc] and not pm[wr, rc]:
                            return (Tool.ROAD, rc, wr)
                        elif not em[wr, rc]: break

    # Phase 12: Third cluster to the left when pop >= 400
    if obs.city_pop >= 400:
        wire_col3 = wire_col - 10
        road_col3 = wire_col3 - 2
        left_zone_col3 = road_col3 - 3
        right_zone_col3 = wire_col3 + 3

        wire_col3 = max(2, min(WORLD_W - 3, wire_col3))
        road_col3 = max(2, min(WORLD_W - 3, road_col3))
        left_zone_col3 = max(2, min(WORLD_W - 3, left_zone_col3))
        right_zone_col3 = max(2, min(WORLD_W - 3, right_zone_col3))

        wire_rows3 = sorted([r for r in range(WORLD_H) if wm[r, wire_col3]])
        road_rows3 = set(r for r in range(WORLD_H) if rm[r, road_col3])

        if not wire_rows3:
            for wc in range(wire_col - 1, wire_col3 - 1, -1):
                if 0 <= wc < WORLD_W:
                    if not wm[plant_cy, wc] and em[plant_cy, wc]:
                        return (Tool.WIRE, wc, plant_cy)
                    elif not em[plant_cy, wc] and not wm[plant_cy, wc]:
                        break
        else:
            min_wr3 = min(wire_rows3)
            max_wr3 = max(wire_rows3)

            if max_wr3 < target_max:
                nr = max_wr3 + 1
                if nr < WORLD_H and em[nr, wire_col3]:
                    return (Tool.WIRE, wire_col3, nr)
            if min_wr3 > target_min:
                nr = min_wr3 - 1
                if nr >= 0 and em[nr, wire_col3]:
                    return (Tool.WIRE, wire_col3, nr)

            for wr in wire_rows3:
                if wr not in road_rows3 and em[wr, road_col3]:
                    return (Tool.ROAD, road_col3, wr)

            for zr in zone_rows:
                wire_near3 = any(abs(zr - wr) <= 2 for wr in wire_rows3)
                road_near3 = any(abs(zr - rr) <= 2 for rr in road_rows3)
                if wire_near3 and road_near3:
                    for zc in [left_zone_col3, right_zone_col3]:
                        if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                            if has_wire_nearby(zr, zc, 6) and has_road_nearby(zr, zc, 5):
                                return (pick_tool(), zc, zr)

            for wr in wire_rows3:
                for wc in range(wire_col3 + 1, min(right_zone_col3 + 2, WORLD_W)):
                    if 0 <= wc < WORLD_W:
                        if wm[wr, wc]: break
                        if em[wr, wc] and not pm[wr, wc]:
                            return (Tool.WIRE, wc, wr)
                        elif not em[wr, wc]: break

            for wr in wire_rows3:
                if not rm[wr, road_col3]: continue
                for rc in range(road_col3 - 1, max(left_zone_col3 - 2, 0), -1):
                    if 0 <= rc < WORLD_W:
                        if rm[wr, rc]: break
                        if em[wr, rc] and not pm[wr, rc]:
                            return (Tool.ROAD, rc, wr)
                        elif not em[wr, rc]: break

    # Phase 13: Extra zone columns when pop > 300
    if obs.city_pop > 300:
        extra_cols = [left_zone_col - 5, right_zone_col + 5]
        for zc in extra_cols:
            if 2 <= zc <= WORLD_W - 3:
                for zr in zone_rows:
                    if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                        if has_road_nearby(zr, zc, 6) and has_wire_nearby(zr, zc, 7):
                            return (Tool.RESIDENTIAL, zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop city builder. Each step reads tile_map and places next tile
    based on what currently exists. Uses a simple phase to track progress.

    Layout:
    - Coal plant at fixed anchor
    - Wire spine running vertically from plant
    - Road column adjacent to wire spine
    - Zones placed where both power (wire) and road access exist
    - Reactive: scans map each step to find what's missing
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    # Fixed anchor positions
    PLANT_X, PLANT_Y = 50, 50
    WIRE_COL = PLANT_X + 4   # wire spine column
    ROAD_COL = WIRE_COL + 2  # primary road column

    # Vertical range for spine
    SPINE_MIN_Y = PLANT_Y - 15
    SPINE_MAX_Y = PLANT_Y + 15

    # Step 1: Ensure coal plant exists
    if not np.any(pm):
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    # Find actual plant location from map
    plant_rows, plant_cols = np.where(pm)
    if len(plant_rows) > 0:
        PLANT_Y = int(plant_rows[0])
        PLANT_X = int(plant_cols[0])
        WIRE_COL = PLANT_X + 4
        ROAD_COL = WIRE_COL + 2
        SPINE_MIN_Y = max(1, PLANT_Y - 15)
        SPINE_MAX_Y = min(WORLD_H - 2, PLANT_Y + 15)

    # Step 2: Wire from plant to wire spine column (horizontal bridge)
    # Connect plant rightward to wire col at plant row
    for c in range(PLANT_X + 2, WIRE_COL + 1):
        if 0 <= c < WORLD_W:
            if not wm[PLANT_Y, c] and not pm[PLANT_Y, c]:
                return (Tool.WIRE, c, PLANT_Y)

    # Step 3: Build wire spine vertically - extend from existing wire
    wire_in_col = [r for r in range(WORLD_H) if wm[r, WIRE_COL] if 0 <= WIRE_COL < WORLD_W]

    if not wire_in_col:
        # Start wire spine at plant row
        if 0 <= WIRE_COL < WORLD_W:
            return (Tool.WIRE, WIRE_COL, PLANT_Y)
    else:
        min_w = min(wire_in_col)
        max_w = max(wire_in_col)

        # Extend downward
        if max_w < SPINE_MAX_Y:
            nr = max_w + 1
            if 0 <= nr < WORLD_H and not pm[nr, WIRE_COL]:
                return (Tool.WIRE, WIRE_COL, nr)

        # Extend upward
        if min_w > SPINE_MIN_Y:
            nr = min_w - 1
            if 0 <= nr >= 0 and not pm[nr, WIRE_COL]:
                return (Tool.WIRE, WIRE_COL, nr)

    # Step 4: Build road spine - scan for missing road next to wire spine
    wire_rows = set(r for r in range(WORLD_H) if 0 <= WIRE_COL < WORLD_W and wm[r, WIRE_COL])

    for r in sorted(wire_rows):
        if 0 <= ROAD_COL < WORLD_W and not rm[r, ROAD_COL]:
            return (Tool.ROAD, ROAD_COL, r)

    # Step 5: Place zones - scan for spots adjacent to both road and wire
    # Zone cols: left of wire spine and right of road spine
    LEFT_ZONE_COL = WIRE_COL - 3   # zones to the left, powered by wire
    RIGHT_ZONE_COL = ROAD_COL + 3  # zones to the right, served by road

    # Helper: check 3x3 zone area is clear of plants
    def zone_ok(zr, zc):
        if zr < 1 or zr >= WORLD_H - 1 or zc < 1 or zc >= WORLD_W - 1:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if pm[rr, rc]:
                    return False
        return True

    def has_zone_near(zr, zc):
        rm2 = res_mask(tm)
        cm2 = com_mask(tm)
        im2 = ind_mask(tm)
        for dr in range(-2, 3):
            for dc in range(-2, 3):
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if rm2[rr, rc] or cm2[rr, rc] or im2[rr, rc]:
                        return True
        return False

    res_p = list(zip(*np.where(res_mask(tm)))) if np.any(res_mask(tm)) else []
    com_p = list(zip(*np.where(com_mask(tm)))) if np.any(com_mask(tm)) else []
    ind_p = list(zip(*np.where(ind_mask(tm)))) if np.any(ind_mask(tm)) else []
    rc = len(res_p)
    cc = len(com_p)
    ic = len(ind_p)
    total = rc + cc + ic

    road_rows = set(r for r in range(WORLD_H) if 0 <= ROAD_COL < WORLD_W and rm[r, ROAD_COL])

    # Place zones at every 3rd row where infrastructure exists
    for row_offset in range(-15, 16, 3):
        zr = PLANT_Y + row_offset
        if zr < 1 or zr >= WORLD_H - 1:
            continue

        wire_nearby = any(abs(zr - wr) <= 2 for wr in wire_rows)
        road_nearby = any(abs(zr - rr) <= 2 for rr in road_rows)

        if wire_nearby:
            # Left zone: lateral wire connection
            zc = LEFT_ZONE_COL
            if zone_ok(zr, zc) and not has_zone_near(zr, zc):
                # First lay lateral wire to connect left zone to spine
                for lc in range(WIRE_COL - 1, zc - 1, -1):
                    if 0 <= lc < WORLD_W and not wm[zr, lc] and not pm[zr, lc]:
                        return (Tool.WIRE, lc, zr)
                # Also need road access - lay road from road col leftward to zone
                for lc in range(ROAD_COL - 1, zc - 1, -1):
                    if 0 <= lc < WORLD_W and not rm[zr, lc] and not pm[zr, lc]:
                        return (Tool.ROAD, lc, zr)
                # Place zone
                if ic * 4 < total + 1:
                    return (Tool.INDUSTRIAL, zc, zr)
                elif cc * 4 < total + 1:
                    return (Tool.COMMERCIAL, zc, zr)
                else:
                    return (Tool.RESIDENTIAL, zc, zr)

        if road_nearby and wire_nearby:
            # Right zone: road access + wire connection
            zc = RIGHT_ZONE_COL
            if zone_ok(zr, zc) and not has_zone_near(zr, zc):
                # Lateral road from road col to zone
                for lc in range(ROAD_COL + 1, zc + 2):
                    if 0 <= lc < WORLD_W and not rm[zr, lc] and not pm[zr, lc]:
                        return (Tool.ROAD, lc, zr)
                # Lateral wire from wire col to right zone
                for lc in range(WIRE_COL + 1, zc + 2):
                    if 0 <= lc < WORLD_W and not wm[zr, lc] and not pm[zr, lc]:
                        return (Tool.WIRE, lc, zr)
                if cc * 4 < total + 1:
                    return (Tool.COMMERCIAL, zc, zr)
                else:
                    return (Tool.RESIDENTIAL, zc, zr)

    # Step 6: If city is growing, expand spine range
    if obs.city_pop > 100:
        SPINE_MIN_Y = max(1, PLANT_Y - 25)
        SPINE_MAX_Y = min(WORLD_H - 2, PLANT_Y + 25)

        wire_in_col2 = [r for r in range(WORLD_H) if 0 <= WIRE_COL < WORLD_W and wm[r, WIRE_COL]]
        if wire_in_col2:
            min_w2 = min(wire_in_col2)
            max_w2 = max(wire_in_col2)
            if max_w2 < SPINE_MAX_Y:
                return (Tool.WIRE, WIRE_COL, max_w2 + 1)
            if min_w2 > SPINE_MIN_Y:
                return (Tool.WIRE, WIRE_COL, min_w2 - 1)

    # Step 7: Fill any gaps in road col where wire exists but road missing
    for r in sorted(wire_rows):
        if 0 <= ROAD_COL < WORLD_W and not rm[r, ROAD_COL]:
            return (Tool.ROAD, ROAD_COL, r)

    # Step 8: Add nuclear plant for more power if large city
    if obs.city_pop > 400:
        nuke_x = PLANT_X - 10
        nuke_y = PLANT_Y
        if 1 <= nuke_x < WORLD_W - 1 and 1 <= nuke_y < WORLD_H - 1:
            if not np.any(pm[nuke_y - 1:nuke_y + 2, nuke_x - 1:nuke_x + 2]):
                return (Tool.NUCLEARPOWER, nuke_x, nuke_y)

    return None

def act(obs, state):
    # Strategy: Build a horizontal strip city instead of vertical spine
    # Use a road running horizontally with wire below it
    # Place zones above and below the road in a compact grid
    # Mixed RCI zones for better growth

