    com_m = com_mask(obs.tile_map)
    ind_m = ind_mask(obs.tile_map)
    emp = empty_mask(obs.tile_map)

    def has_tile(mask, x, y):
        if 0 <= y < WORLD_H and 0 <= x < WORLD_W:
            return bool(mask[y, x])
        return False

    # Phase 0: place coal power plant
    if not has_tile(pm, plant_x, plant_y):
        return (Tool.COALPOWER, plant_x, plant_y)

    # Phase 1: wire row at cy+2 (below road, connected to plant)
    for dx in STRIP_COLS:
        if not has_tile(wm, dx, cy + 2) and not has_tile(pm, dx, cy + 2):
            return (Tool.WIRE, dx, cy + 2)

    # Phase 2: road row at cy (main artery)
    for dx in STRIP_COLS:
        if not has_tile(rm_road, dx, cy):
            return (Tool.ROAD, dx, cy)

    # Phase 3: vertical wires connecting wire row to road row and zone rows
    # at every 3 cols, place a vertical wire connector from cy+2 up to cy-2
    for dx in range(cx - 18, cx + 19, 3):
        for wy in range(cy - 2, cy + 3):
            if not has_tile(wm, dx, wy) and not has_tile(rm_road, dx, wy) and not has_tile(pm, dx, wy):
                return (Tool.WIRE, dx, wy)

    # Phase 4: place zones above road
    # Row of zone centers at cy-3 (just above road), mixed RCI
    zone_rows_above = [cy - 3, cy - 6]
    zone_rows_below = [cy + 3, cy + 6]

    zone_cols = list(range(cx - 18, cx + 19, 3))

    # Above: residential and commercial alternating
    for i, dx in enumerate(zone_cols):
        dy = cy - 3
        if not has_tile(res_m, dx, dy) and not has_tile(com_m, dx, dy) and not has_tile(ind_m, dx, dy):
            # Check wire connectivity nearby
            if has_tile(wm, dx, dy + 1) or has_tile(wm, dx, cy + 2):
                if i % 3 == 0:
                    return (Tool.COMMERCIAL, dx, dy)
                else:
                    return (Tool.RESIDENTIAL, dx, dy)

    # Below road: industrial and residential
    for i, dx in enumerate(zone_cols):
        dy = cy + 3
        if not has_tile(res_m, dx, dy) and not has_tile(com_m, dx, dy) and not has_tile(ind_m, dx, dy):
            if has_tile(wm, dx, cy + 2) or has_tile(wm, dx, dy - 1):
