            # need wire connector up there
            for wy in range(cy - 5, cy - 2):
                if not has_tile(wm, dx, wy) and not has_tile(rm_road, dx, wy) and not has_tile(pm, dx, wy):
                    return (Tool.WIRE, dx, wy)
            if has_tile(wm, dx, cy - 3) or has_tile(wm, dx, cy - 4):
