        num_plants = len(plant_positions)
        if num_plants < 2:
            # Place second plant near second cluster
            return (Tool.COALPOWER, 78, plant_cy)

    return None

def act(obs, state):
    """
    Hybrid policy combining:
    - Parent B's vertical wire spine + bilateral road columns (proven to work)
    - Parent A's dual cluster idea (two power plants, wider coverage)
    - Denser zone placement with multiple zone columns per corridor
    - Progressive expansion based on population
    - Services when population warrants
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Two power plant positions, centered vertically
    P1X, P1Y = 45, 50   # primary plant
    P2X, P2Y = 75, 50   # secondary plant (activated later)

    plant_ys, plant_xs = np.where(pm)
    has_plant1 = False
    has_plant2 = False
    for py_, px_ in zip(plant_ys.tolist(), plant_xs.tolist()):
        if abs(px_ - P1X) <= 5 and abs(py_ - P1Y) <= 5:
            has_plant1 = True
        if abs(px_ - P2X) <= 5 and abs(py_ - P2Y) <= 5:
            has_plant2 = True

    # Phase 1: place primary power plant
    if not has_plant1:
        return (Tool.COALPOWER, P1X, P1Y)

    # Gather zone counts
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_zone(zr):
        # ~50% RES, ~25% COM, ~25% IND; more IND in lower half
        if ind_count == 0 or (ind_count * 3 < res_count and zr >= P1Y):
            return Tool.INDUSTRIAL
        if com_count == 0 or (com_count * 3 < res_count):
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not in_bounds(rc, rr):
                    return False
                if not bool(em[rr, rc]):
                    return False
        return True

    # Corridor 1: wire spine at x=P1X+4, roads at x±1, zones at x±4, x±7
    def build_corridor(wire_col, plant_cy, cy_ref, phase2_pop=0):
        """Returns an action for the corridor, or None if nothing to do."""
        road_col_L = wire_col - 1
        road_col_R = wire_col + 1
        zone_cols_L = [wire_col - 4, wire_col - 7]
        zone_cols_R = [wire_col + 4, wire_col + 7]

        # Vertical span grows with pop
        base_span = 12
        extra_span = min(30, obs.city_pop // 20)
        target_span = base_span + extra_span
        tmin = max(2, cy_ref - target_span)
        tmax = min(WORLD_H - 3, cy_ref + target_span)

        wire_positions = set(zip(*np.where(wm))) if np.any(wm) else set()
        road_positions = set(zip(*np.where(rm))) if np.any(rm) else set()
        all_zones_rows = set(r for r, c in (
            list(zip(*np.where(resm))) + list(zip(*np.where(comm))) + list(zip(*np.where(indm)))
        )) if (np.any(resm) or np.any(comm) or np.any(indm)) else set()

        wire_rows_in_col = sorted(r for (r, c) in wire_positions if c == wire_col)

        # Extend wire spine
        if not wire_rows_in_col:
            if in_bounds(wire_col, plant_cy):
                return (Tool.WIRE, wire_col, plant_cy)
        else:
            min_wr = min(wire_rows_in_col)
            max_wr = max(wire_rows_in_col)
            if max_wr < tmax:
                nr = max_wr + 1
                if in_bounds(wire_col, nr) and bool(em[nr, wire_col]):
                    return (Tool.WIRE, wire_col, nr)
            if min_wr > tmin:
                nr = min_wr - 1
                if in_bounds(wire_col, nr) and bool(em[nr, wire_col]):
                    return (Tool.WIRE, wire_col, nr)

        wire_rows_set = set(wire_rows_in_col)
        road_rows_L = set(r for (r, c) in road_positions if c == road_col_L)
        road_rows_R = set(r for (r, c) in road_positions if c == road_col_R)

        # Build road columns adjacent to wire
        for wr in wire_rows_in_col:
            if wr not in road_rows_L and in_bounds(road_col_L, wr):
                if bool(em[wr, road_col_L]):
                    return (Tool.ROAD, road_col_L, wr)
            if wr not in road_rows_R and in_bounds(road_col_R, wr):
                if bool(em[wr, road_col_R]):
                    return (Tool.ROAD, road_col_R, wr)

        road_rows_L_set = set(r for (r, c) in road_positions if c == road_col_L)
        road_rows_R_set = set(r for (r, c) in road_positions if c == road_col_R)

        # Place zones adjacent to roads
        for wr in wire_rows_in_col:
            if not in_bounds(wire_col, wr) or wr < 2 or wr >= WORLD_H - 2:
                continue
            road_L_nearby = any(abs(wr - rr) <= 1 for rr in road_rows_L_set)
            road_R_nearby = any(abs(wr - rr) <= 1 for rr in road_rows_R_set)

            for zc in zone_cols_L:
                if road_L_nearby and in_bounds(zc, wr) and 2 <= zc < WORLD_W - 2:
                    if zone_area_free(wr, zc):
                        return (pick_zone(wr), zc, wr)

            for zc in zone_cols_R:
                if road_R_nearby and in_bounds(zc, wr) and 2 <= zc < WORLD_W - 2:
                    if zone_area_free(wr, zc):
                        return (pick_zone(wr), zc, wr)

        # Lateral wires from spine to left zone columns
        for wr in wire_rows_in_col:
            for wc in range(wire_col - 1, max(wire_col - 8, 0) - 1, -1):
                if in_bounds(wc, wr) and not bool(wm[wr, wc]) and not bool(pm[wr, wc]) and not bool(rm[wr, wc]):
                    if bool(em[wr, wc]):
                        return (Tool.WIRE, wc, wr)
                    break

        # Lateral roads from right road col to right zone columns
        for wr in wire_rows_in_col:
            for rc in range(road_col_R + 1, min(wire_col + 9, WORLD_W)):
                if in_bounds(rc, wr) and not bool(rm[wr, rc]) and not bool(pm[wr, rc]) and not bool(wm[wr, rc]):
                    if bool(em[wr, rc]):
                        return (Tool.ROAD, rc, wr)
                    break

        return None

    # Build corridor 1 (primary)
    wire_col1 = P1X + 4  # = 49
    action = build_corridor(wire_col1, P1Y, P1Y)
    if action is not None:
        return action

    # Phase 2: second power plant and corridor once population grows
    if obs.city_pop > 100:
        if not has_plant2:
            return (Tool.COALPOWER, P2X, P2Y)

        # Connect plant2 to wire spine 1 via horizontal wire
        wire_col2 = P2X + 4  # = 79
        # First connect plant2 area to wire_col2
        wire_positions2 = set(zip(*np.where(wm))) if np.any(wm) else set()
        wire_rows2 = sorted(r for (r, c) in wire_positions2 if c == wire_col2)

        # Connect plant2 horizontally to wire_col2
        if not wire_rows2:
            # Lay wire from plant2 rightward to wire_col2
            for wc in range(P2X + 2, wire_col2 + 1):
                if in_bounds(wc, P2Y) and bool(em[P2Y, wc]) and not bool(pm[P2Y, wc]):
                    return (Tool.WIRE, wc, P2Y)
                elif not bool(em[P2Y, wc]) and not bool(pm[P2Y, wc]) and not bool(wm[P2Y, wc]):
                    break

        action2 = build_corridor(wire_col2, P2Y, P2Y)
        if action2 is not None:
            return action2

    # Services
    if obs.city_pop > 300:
        fx, fy = wire_col1 + 6, P1Y - 8
        if in_bounds(fx, fy) and zone_area_free(fy, fx):
            return (Tool.FIRESTATION, fx, fy)

    if obs.city_pop > 500:
        px2, py2 = wire_col1 - 6, P1Y + 8
        if in_bounds(px2, py2) and zone_area_free(py2, px2):
            return (Tool.POLICESTATION, px2, py2)

    # Fallback: extend roads from existing road tiles
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = int(obs.step * 13) % max(len(road_xs), 1)
        rx_s, ry_s = int(road_xs[step_k]), int(road_ys[step_k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx_s + dx2, ry_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wires
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        step_k2 = int(obs.step * 7) % max(len(wire_xs), 1)
        wx_s, wy_s = int(wire_xs[step_k2]), int(wire_ys[step_k2])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = wx_s + dx2, wy_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map each step and places the next
    most-needed infrastructure or zone adjacent to what already exists.
    Strategy:
    - Coal plant near center-left
    - Vertical wire spine extending from plant
    - Road column parallel to wire spine
    - Zones placed left and right of road, checked for power+road proximity
    - Lateral wires to feed left zones, road extensions to right zones
    - Second plant + expansion cluster when population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    all_zone = resm | comm | indm
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not (em[rr, rc] or all_zone[rr, rc]):
                    return False
        return True

    def zone_already_there(zr, zc):
        r0 = max(0, zr - 1); r1 = min(WORLD_H, zr + 2)
        c0 = max(0, zc - 1); c1 = min(WORLD_W, zc + 2)
        return np.any(all_zone[r0:r1, c0:c1])

    def has_wire_nearby(zr, zc, radius=5):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    # Phase 1: Place first coal power plant
    if not np.any(pm):
        return (Tool.COALPOWER, cx - 10, cy)

    # Find plant centroid
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Layout geometry
    wire_col = plant_cx + 4
    road_col = wire_col + 2
    left_zone_col = wire_col - 3
    right_zone_col = road_col + 3

    wire_col = max(2, min(WORLD_W - 3, wire_col))
    road_col = max(2, min(WORLD_W - 3, road_col))
    left_zone_col = max(2, min(WORLD_W - 3, left_zone_col))
    right_zone_col = max(2, min(WORLD_W - 3, right_zone_col))

    # Dynamic spine extent based on population
    if obs.city_pop < 80:
        spine_extent = 8
    elif obs.city_pop < 200:
        spine_extent = 14
    elif obs.city_pop < 400:
        spine_extent = 20
    else:
        spine_extent = 28

    target_min = max(1, cy - spine_extent)
    target_max = min(WORLD_H - 2, cy + spine_extent)

    # Read current wire and road on spine columns
    wire_rows_on_spine = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])
    road_rows_set = set(r for r in range(WORLD_H) if rm[r, road_col])
    road_rows_list = sorted(road_rows_set)

    # Phase 2: Bootstrap wire adjacent to plant
    if not wire_rows_on_spine:
        for dy in range(0, 8):
            for nr in [plant_cy + dy, plant_cy - dy]:
                if 0 <= nr < WORLD_H:
                    if em[nr, wire_col] or wm[nr, wire_col]:
                        return (Tool.WIRE, wire_col, nr)
        return None

    min_wire_row = min(wire_rows_on_spine)
    max_wire_row = max(wire_rows_on_spine)

    # Phase 3: Extend wire spine downward
    if max_wire_row < target_max:
        nr = max_wire_row + 1
        if nr < WORLD_H and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Phase 4: Extend wire spine upward
    if min_wire_row > target_min:
        nr = min_wire_row - 1
        if nr >= 0 and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Phase 5: Build road column alongside wire spine (scan for gaps)
    # Find the first wire row that doesn't have a road yet
    for r in wire_rows_on_spine:
        if r not in road_rows_set and 0 <= road_col < WORLD_W:
            if em[r, road_col]:
                return (Tool.ROAD, road_col, r)

    # Phase 6: Place zones where power and road both reach
    zone_rows = list(range(max(1, target_min), min(WORLD_H - 1, target_max + 1), 3))

    for zr in zone_rows:
        wire_near = any(abs(zr - wr) <= 2 for wr in wire_rows_on_spine)
        road_near = any(abs(zr - rr) <= 2 for rr in road_rows_list)

        if wire_near and road_near:
            # Left zone
            zc = left_zone_col
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc) and has_road_nearby(zr, zc):
                    return (pick_tool(), zc, zr)
                elif has_wire_nearby(zr, zc):
                    # place anyway, road might be close enough
                    return (Tool.RESIDENTIAL, zc, zr)

            # Right zone
            zc = right_zone_col
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_road_nearby(zr, zc) and has_wire_nearby(zr, zc, 6):
                    return (pick_tool(), zc, zr)

    # Phase 7: Lateral wires from spine toward left zones
    for wr in wire_rows_on_spine:
        for wc in range(wire_col - 1, max(left_zone_col - 3, 0), -1):
            if wm[wr, wc]:
                break
            if em[wr, wc] and not pm[wr, wc]:
                return (Tool.WIRE, wc, wr)
            elif not em[wr, wc]:
                break

    # Phase 8: Road extensions from road col toward right zones
    for rr in wire_rows_on_spine:
        if rr not in road_rows_set:
            continue
        for rc in range(road_col + 1, right_zone_col + 3):
            if rc >= WORLD_W:
                break
            if rm[rr, rc]:
                break
            if em[rr, rc] and not pm[rr, rc]:
                return (Tool.ROAD, rc, rr)
            elif not em[rr, rc]:
                break

    # Phase 9: Wire extensions toward right zones for power
    for wr in wire_rows_on_spine:
        for wc in range(wire_col + 1, right_zone_col + 3):
            if wc >= WORLD_W:
                break
            if wm[wr, wc]:
                break
            if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                return (Tool.WIRE, wc, wr)
            elif not em[wr, wc] and not rm[wr, wc]:
                break

    # Phase 10: Second power plant when city grows
    plant_count = int(np.sum(pm))
    if obs.city_pop > 300 and plant_count < 9:
        px2 = plant_cx + 20
        py2 = plant_cy
        if 2 <= py2 <= WORLD_H - 3 and 2 <= px2 <= WORLD_W - 3:
            area_clear = all(
                em[py2 + dr, px2 + dc] or pm[py2 + dr, px2 + dc]
                for dr in [-1, 0, 1]
                for dc in [-1, 0, 1]
            )
            if area_clear:
                return (Tool.COALPOWER, px2, py2)

    # Phase 11: Second cluster to the right (when pop >= 150)
    if obs.city_pop >= 150:
        wire_col2 = road_col + 8
        road_col2 = wire_col2 + 2
        lzc2 = wire_col2 - 3
        rzc2 = road_col2 + 3

        wire_col2 = max(2, min(WORLD_W - 3, wire_col2))
        road_col2 = max(2, min(WORLD_W - 3, road_col2))
        lzc2 = max(2, min(WORLD_W - 3, lzc2))
        rzc2 = max(2, min(WORLD_W - 3, rzc2))

        wire_rows2 = sorted(r for r in range(WORLD_H) if wm[r, wire_col2])
        road_rows2 = set(r for r in range(WORLD_H) if rm[r, road_col2])

        if not wire_rows2:
            # Build horizontal wire bridge from main spine
            bridge_row = plant_cy
            for wc in range(wire_col + 1, wire_col2 + 1):
                if wc >= WORLD_W:
                    break
                if wm[bridge_row, wc]:
                    continue
                if em[bridge_row, wc]:
                    return (Tool.WIRE, wc, bridge_row)
                else:
                    break
        else:
            min_wr2 = min(wire_rows2)
            max_wr2 = max(wire_rows2)
            if max_wr2 < target_max:
                nr = max_wr2 + 1
                if nr < WORLD_H and em[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > target_min:
                nr = min_wr2 - 1
                if nr >= 0 and em[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)

            for wr in wire_rows2:
                if wr not in road_rows2 and em[wr, road_col2]:
                    return (Tool.ROAD, road_col2, wr)

            road_list2 = sorted(road_rows2)
            for zr in zone_rows:
                wire_near2 = any(abs(zr - wr) <= 2 for wr in wire_rows2)
                road_near2 = any(abs(zr - rr) <= 2 for rr in road_list2)
                if wire_near2 and road_near2:
                    for zc in [lzc2, rzc2]:
                        if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                            if has_wire_nearby(zr, zc, 6) and has_road_nearby(zr, zc, 5):
                                return (pick_tool(), zc, zr)

            for wr in wire_rows2:
                for wc in range(wire_col2 - 1, max(lzc2 - 3, 0), -1):
                    if wm[wr, wc]: break
                    if em[wr, wc] and not pm[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    elif not em[wr, wc]: break

            for wr in wire_rows2:
                if wr not in road_rows2: continue
                for rc in range(road_col2 + 1, rzc2 + 3):
                    if rc >= WORLD_W: break
                    if rm[wr, rc]: break
                    if em[wr, rc] and not pm[wr, rc]:
                        return (Tool.ROAD, rc, wr)
                    elif not em[wr, rc]: break

    # Phase 12: Left cluster (when pop >= 350)
    if obs.city_pop >= 350:
        wire_col3 = wire_col - 10
        road_col3 = wire_col3 - 2
        lzc3 = road_col3 - 3
        rzc3 = wire_col3 + 3

        wire_col3 = max(2, min(WORLD_W - 3, wire_col3))
        road_col3 = max(2, min(WORLD_W - 3, road_col3))
        lzc3 = max(2, min(WORLD_W - 3, lzc3))
        rzc3 = max(2, min(WORLD_W - 3, rzc3))

        wire_rows3 = sorted(r for r in range(WORLD_H) if wm[r, wire_col3])
        road_rows3 = set(r for r in range(WORLD_H) if rm[r, road_col3])

        if not wire_rows3:
            bridge_row = plant_cy
            for wc in range(wire_col - 1, wire_col3 - 1, -1):
                if wc < 0: break
                if wm[bridge_row, wc]: continue
                if em[bridge_row, wc]:
                    return (Tool.WIRE, wc, bridge_row)
                else: break
        else:
            min_wr3 = min(wire_rows3)
            max_wr3 = max(wire_rows3)
            if max_wr3 < target_max:
                nr = max_wr3 + 1
                if nr < WORLD_H and em[nr, wire_col3]:
                    return (Tool.WIRE, wire_col3, nr)
            if min_wr3 > target_min:
                nr = min_wr3 - 1
                if nr >= 0 and em[nr, wire_col3]:
                    return (Tool.WIRE, wire_col3, nr)

            for wr in wire_rows3:
                if wr not in road_rows3 and em[wr, road_col3]:
                    return (Tool.ROAD, road_col3, wr)

            road_list3 = sorted(road_rows3)
            for zr in zone_rows:
                wire_near3 = any(abs(zr - wr) <= 2 for wr in wire_rows3)
                road_near3 = any(abs(zr - rr) <= 2 for rr in road_list3)
                if wire_near3 and road_near3:
                    for zc in [lzc3, rzc3]:
                        if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                            if has_wire_nearby(zr, zc, 6) and has_road_nearby(zr, zc, 5):
                                return (pick_tool(), zc, zr)

            for wr in wire_rows3:
                for wc in range(wire_col3 + 1, min(rzc3 + 3, WORLD_W)):
                    if wm[wr, wc]: break
                    if em[wr, wc] and not pm[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    elif not em[wr, wc]: break

            for wr in wire_rows3:
                if wr not in road_rows3: continue
                for rc in range(road_col3 - 1, max(lzc3 - 3, 0), -1):
                    if rm[wr, rc]: break
                    if em[wr, rc] and not pm[wr, rc]:
                        return (Tool.ROAD, rc, wr)
                    elif not em[wr, rc]: break

    # Phase 13: Extra zone columns closer in when pop > 250
    if obs.city_pop > 250:
        extra_cols = [left_zone_col - 4, right_zone_col + 4]
        for zc in extra_cols:
            if 2 <= zc <= WORLD_W - 3:
                for zr in zone_rows:
                    if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                        if has_road_nearby(zr, zc, 5) and has_wire_nearby(zr, zc, 6):
                            return (pick_tool(), zc, zr)

    return None

def act(obs, state):
    """
    Redesigned policy:
    - Horizontal spine (road row + wire row) instead of vertical
    - Power plant on left side, zones above and below the spine
    - Two neighborhoods: one central, one offset right
    - Better R/C/I balance
    - Explicit lateral wiring to all zones
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def has_tile(mask, x, y):
        if 0 <= y < WORLD_H and 0 <= x < WORLD_W:
            return bool(mask[y, x])
        return False

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        all_zone = resm | comm | indm
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone[rr, rc]:
                    return False
        return True

    def zone_present(zr, zc):
        all_zone = resm | comm | indm
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone[rr, rc]:
                        return True
        return False

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        if com_count / t < 0.30:
            return Tool.COMMERCIAL
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Horizontal layout:
    # wire_row: horizontal wire spine
    # road_row: horizontal road spine (wire_row + 1)
    # zones above: row = wire_row - 3, wire_row - 6, ...
    # zones below: row = road_row + 3, road_row + 6, ...
    # plant at left end of wire row

    wire_row = cy - 1
    road_row = cy       # road right below wire
    plant_x = cx - 20
    plant_y = wire_row

    wire_row = max(2, min(WORLD_H - 3, wire_row))
    road_row = max(2, min(WORLD_H - 3, road_row))
    plant_x = max(2, min(WORLD_W - 3, plant_x))
    plant_y = max(2, min(WORLD_H - 3, plant_y))

    # Adaptive spine extent
    if obs.city_pop < 50:
        spine_half = 10
    elif obs.city_pop < 200:
        spine_half = 16
    elif obs.city_pop < 500:
        spine_half = 22
    else:
        spine_half = 30

    spine_min = max(1, cx - spine_half)
    spine_max = min(WORLD_W - 2, cx + spine_half)
    spine_range = range(spine_min, spine_max + 1)

    # Phase 0: Place coal power plant
    if not np.any(pm):
        return (Tool.COALPOWER, plant_x, plant_y)

    # Phase 1: Wire spine horizontal row
    for dx in spine_range:
        if not has_tile(wm, dx, wire_row) and not has_tile(pm, dx, wire_row):
            if not has_tile(rm, dx, wire_row):
                return (Tool.WIRE, dx, wire_row)

    # Phase 2: Road row adjacent to wire (one row below)
    for dx in spine_range:
        if not has_tile(rm, dx, road_row) and not has_tile(pm, dx, road_row):
            if not has_tile(wm, dx, road_row):
                return (Tool.ROAD, dx, road_row)

    # Collect wired cols and road cols
    wire_cols = [c for c in spine_range if wm[wire_row, c]]
    road_cols = [c for c in spine_range if rm[road_row, c]]

    # Zone columns spaced every 3 along spine
    zone_cols = list(range(spine_min + 1, spine_max - 1, 3))

    # Above zones: wire_row - 3 (center of 3x3 zone touching wire at wire_row-1)
    above_zrow = wire_row - 3
    below_zrow = road_row + 3

    # Phase 3: Place zones above spine
    for zc in zone_cols:
        wire_near = any(abs(zc - wc) <= 2 for wc in wire_cols)
        road_near = any(abs(zc - rc) <= 2 for rc in road_cols)
        if wire_near and road_near:
            zr = above_zrow
            if 1 <= zr <= WORLD_H - 2:
                if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                    return (pick_tool(), zc, zr)

    # Phase 4: Place zones below spine
    for zc in zone_cols:
        wire_near = any(abs(zc - wc) <= 2 for wc in wire_cols)
        road_near = any(abs(zc - rc) <= 2 for rc in road_cols)
        if wire_near and road_near:
            zr = below_zrow
            if 1 <= zr <= WORLD_H - 2:
                if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                    return (pick_tool(), zc, zr)

    # Phase 5: Vertical wires from wire spine up to above zones
    for wc in wire_cols:
        for wr in range(wire_row - 1, above_zrow - 2, -1):
            if 0 <= wr < WORLD_H:
                if wm[wr, wc] or pm[wr, wc]:
                    break
                if em[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                else:
                    break

    # Phase 6: Vertical wires/roads from road spine down to below zones
    for rc in road_cols:
        for wr in range(road_row + 1, below_zrow + 2):
            if 0 <= wr < WORLD_H:
                if wm[wr, rc] or pm[wr, rc]:
                    break
                if em[wr, rc]:
                    return (Tool.WIRE, rc, wr)
                else:
                    break

    # Phase 7: Second power plant if city growing
    if obs.city_pop > 200 and int(np.sum(pm)) < 9:
        px2 = plant_x + 40
        py2 = plant_y
        if 2 <= px2 <= WORLD_W - 3 and 2 <= py2 <= WORLD_H - 3:
            if em[py2, px2]:
                return (Tool.COALPOWER, px2, py2)

    # Phase 8: Second tier zones (farther above and below)
    if obs.city_pop > 100:
        above2_zrow = wire_row - 7
        below2_zrow = road_row + 7
        for zc in zone_cols:
            wire_near = any(abs(zc - wc) <= 2 for wc in wire_cols)
            road_near = any(abs(zc - rc) <= 2 for rc in road_cols)
            if wire_near and road_near:
                for zr in [above2_zrow, below2_zrow]:
                    if 1 <= zr <= WORLD_H - 2:
                        r0 = max(0, zr - 5); r1 = min(WORLD_H, zr + 6)
                        c0 = max(0, zc - 5); c1 = min(WORLD_W, zc + 6)
                        if np.any(wm[r0:r1, c0:c1]) and np.any(rm[r0:r1, c0:c1]):
                            if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                                return (pick_tool(), zc, zr)

    # Phase 9: Add vertical roads for better connectivity
    if obs.city_pop > 150:
        for vc in [spine_min + 1, cx, spine_max - 1]:
            if 0 <= vc < WORLD_W:
                for vr in range(wire_row - 1, above_zrow - 1, -1):
                    if 0 <= vr < WORLD_H and em[vr, vc] and not pm[vr, vc]:
                        return (Tool.ROAD, vc, vr)
                for vr in range(road_row + 1, below_zrow + 1):
                    if 0 <= vr < WORLD_H and em[vr, vc] and not pm[vr, vc]:
                        return (Tool.ROAD, vc, vr)

    return None

def act(obs, state):
    """
    Hybrid policy combining best ideas from both parents:
    - Compact cluster near center-left (Parent B's positioning)
    - Vertical wire spine from plant (both parents)
    - Horizontal road spines above/below wire (Parent A's grid idea)
    - Zones placed systematically near wire+road (both parents)
    - Proper zone balance (Parent B's ratio logic)
    - Services and expansion when population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    # Plant at a good central-left position
    PLANT_X, PLANT_Y = 45, 50

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Phase 1: Place coal power plant
    if not np.any(pm):
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    # Find plant anchor
    plant_ys, plant_xs = np.where(pm)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    # Wire spine: one column to the right of plant
    wire_col = px + 3

    # Road columns flanking zones
    road_col_right = wire_col + 3   # right of wire spine
    road_col_left = px - 3          # left of plant

    # Zone columns
    zone_col_right1 = wire_col + 6
    zone_col_right2 = wire_col + 10
    zone_col_left1 = px - 7

    # Wire spine extent
    wire_top = max(2, py - 20)
    wire_bot = min(WORLD_H - 3, py + 20)

    # Precompute masks
    wire_rows_in_spine = [r for r in range(wire_top, wire_bot + 1) if wm[r, wire_col]]
    road_right_rows = [r for r in range(wire_top, wire_bot + 1) if rm[r, road_col_right]]
    road_left_rows = [r for r in range(wire_top, wire_bot + 1) if rm[r, road_col_left]]

    res_ys, res_xs = np.where(resm)
    com_ys, com_xs = np.where(comm)
    ind_ys, ind_xs = np.where(indm)
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        if ind_count * 4 < t + 1:
            return Tool.INDUSTRIAL
        elif com_count * 4 < t + 1:
            return Tool.COMMERCIAL
        else:
            return Tool.RESIDENTIAL

    def zone_area_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zy + dr, zx + dc
                if not in_bounds(rc, rr):
                    return False
                if pm[rr, rc]:
                    return False
        return True

    def zone_exists_near(zx, zy):
        for dr in range(-2, 3):
            for dc in range(-2, 3):
                rr, rc = zy + dr, zx + dc
                if in_bounds(rc, rr):
                    if resm[rr, rc] or comm[rr, rc] or indm[rr, rc]:
                        return True
        return False

    def has_wire_near(zx, zy, r=5):
        for dr in range(-r, r + 1):
            for dc in range(-r, r + 1):
                nr, nc = zy + dr, zx + dc
                if in_bounds(nc, nr):
                    if wm[nr, nc] or pm[nr, nc]:
                        return True
        return False

    def has_road_near(zx, zy, r=4):
        for dr in range(-r, r + 1):
            for dc in range(-r, r + 1):
                nr, nc = zy + dr, zx + dc
                if in_bounds(nc, nr) and rm[nr, nc]:
                    return True
        return False

    # Phase 2: Build vertical wire spine
    all_wire_spine = [r for r in range(wire_top, wire_bot + 1) if wm[r, wire_col]]
    if len(all_wire_spine) < (wire_bot - wire_top + 1):
        # Extend from plant row outward
        for r in range(py, wire_bot + 1):
            if in_bounds(wire_col, r) and not wm[r, wire_col] and not pm[r, wire_col]:
                return (Tool.WIRE, wire_col, r)
        for r in range(py, wire_top - 1, -1):
            if in_bounds(wire_col, r) and not wm[r, wire_col] and not pm[r, wire_col]:
                return (Tool.WIRE, wire_col, r)

    # Phase 3: Build right road column adjacent to wire spine
    if len(road_right_rows) < (wire_bot - wire_top + 1):
        for r in range(wire_top, wire_bot + 1):
            if in_bounds(road_col_right, r) and not rm[r, road_col_right] and not pm[r, road_col_right]:
                return (Tool.ROAD, road_col_right, r)

    # Phase 4: Build left road column
    if len(road_left_rows) < (wire_bot - wire_top + 1):
        for r in range(wire_top, wire_bot + 1):
            if in_bounds(road_col_left, r) and not rm[r, road_col_left] and not pm[r, road_col_left]:
                return (Tool.ROAD, road_col_left, r)

    # Phase 5: Lateral wires from spine to left zone col
    lat_wire_col = zone_col_left1
    for r in range(wire_top, wire_bot + 1, 3):
        if wm[r, wire_col]:  # spine exists at this row
            for c in range(wire_col - 1, lat_wire_col - 1, -1):
                if in_bounds(c, r) and not wm[r, c] and not pm[r, c]:
                    return (Tool.WIRE, c, r)

    # Phase 6: Lateral roads from right road col to right zone cols
    for r in range(wire_top, wire_bot + 1, 3):
        if rm[r, road_col_right]:
            for c in range(road_col_right + 1, zone_col_right2 + 2):
                if in_bounds(c, r) and not rm[r, c] and not pm[r, c]:
                    return (Tool.ROAD, c, r)

    # Phase 7: Place zones systematically
    zone_rows = list(range(wire_top + 1, wire_bot, 3))
    zone_cols_options = [zone_col_left1, zone_col_right1, zone_col_right2]

    for zr in zone_rows:
        for zc in zone_cols_options:
            if not (2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3):
                continue
            if zone_area_clear(zc, zr) and not zone_exists_near(zc, zr):
                if has_wire_near(zc, zr, r=6) and has_road_near(zc, zr, r=5):
                    return (pick_tool(), zc, zr)

    # Phase 8: Reactive zone placement near roads+wires
    # Dilate wire mask
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    cand = em & nbr_wire & nbr_road
    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        k = int((obs.step * 13 + int(tm[py, px]) % 50)) % len(cxs)
        zx, zy = int(cxs[k]), int(cys[k])
        if 2 <= zy <= WORLD_H - 3 and 2 <= zx <= WORLD_W - 3:
            if zone_area_clear(zx, zy) and not zone_exists_near(zx, zy):
                return (pick_tool(), zx, zy)

    # Phase 9: Services once population growing
    if obs.city_pop > 150:
        fx, fy = px + 8, py - 12
        if in_bounds(fx, fy) and em[fy, fx] and zone_area_clear(fx, fy):
            return (Tool.FIRESTATION, fx, fy)
        fx2, fy2 = px + 8, py + 12
        if in_bounds(fx2, fy2) and em[fy2, fx2] and zone_area_clear(fx2, fy2):
            return (Tool.POLICESTATION, fx2, fy2)

    # Phase 10: Second power plant if needed
    if obs.city_pop > 400 and np.sum(pm) < 9:
        nx2, ny2 = px + 30, py
        if in_bounds(nx2, ny2) and em[ny2, nx2]:
            return (Tool.COALPOWER, nx2, ny2)

    # Phase 11: Extend wire to reach unserved zones
    zone_ys = np.concatenate([res_ys, com_ys, ind_ys])
    zone_xs = np.concatenate([res_xs, com_xs, ind_xs])
    for i in range(min(len(zone_xs), 20)):
        zx, zy = int(zone_xs[i]), int(zone_ys[i])
        if not has_wire_near(zx, zy, r=4):
            wire_ys2, wire_xs2 = np.where(wm)
            if len(wire_xs2) > 0:
                dists = np.abs(wire_ys2 - zy) + np.abs(wire_xs2 - zx)
                best = np.argmin(dists)
                wr, wc = int(wire_ys2[best]), int(wire_xs2[best])
                sr = (1 if zy > wr else -1 if zy < wr else 0)
                sc = (1 if zx > wc else -1 if zx < wc else 0)
                for nr, nc in [(wr + sr, wc), (wr, wc + sc)]:
                    if in_bounds(nc, nr) and not pm[nr, nc] and not wm[nr, nc]:
                        return (Tool.WIRE, nc, nr)

    # Phase 12: Extend roads from existing road frontier
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        k = int(obs.step * 7) % len(road_xs2)
        rx, ry = int(road_xs2[k]), int(road_ys2[k])
        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx + dx, ry + dy
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Improved city builder with:
    - Vertical wire spine (not horizontal) to avoid plant collision
    - Two parallel road columns flanking the spine
    - Zones placed in a grid pattern between roads
    - Better power coverage with second plant
    - Mixed RCI zones
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Primary anchor: plant at (60, 20) - upper center area
    PLANT_X, PLANT_Y = 60, 20

    # Step 1: Place primary coal power plant
    if not np.any(pm):
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    # Find plant location
    plant_ys, plant_xs = np.where(pm)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    res_ys, res_xs = np.where(resm)
    com_ys, com_xs = np.where(comm)
    ind_ys, ind_xs = np.where(indm)
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    zone_set = set(zip(
        np.concatenate([res_ys, com_ys, ind_ys]).tolist() if total_zones > 0 else [],
        np.concatenate([res_xs, com_xs, ind_xs]).tolist() if total_zones > 0 else []
    ))

    def pick_tool():
        t = max(total_zones, 1)
        r = res_count / t
        c = com_count / t
        i = ind_count / t
        # Balanced mix: ~50% R, ~25% C, ~25% I
        if c < 0.22:
            return Tool.COMMERCIAL
        if i < 0.22:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    # Layout: 
    # Wire spine: vertical at x=px+4, from py+2 down to py+50
    # Road columns at x=px+1 and x=px+7
    # Zones in columns at x=px+1+2=px+3 (between left road and spine) and x=px+7+2=px+9 (right of right road)
    # Actually: road at x=spine-3 and x=spine+3, zones between

    spine_x = px + 4  # vertical wire spine
    road_left = spine_x - 4   # road column left of spine
    road_right = spine_x + 4  # road column right of spine
    wire_start_y = py + 2
    wire_end_y = min(py + 60, WORLD_H - 4)
    road_start_y = py + 2
    road_end_y = min(py + 60, WORLD_H - 4)

    # Build vertical wire spine
    for wy in range(wire_start_y, wire_end_y + 1):
        wx = spine_x
        if not in_bounds(wx, wy):
            break
        if not bool(wm[wy, wx]) and not bool(pm[wy, wx]):
            if bool(em[wy, wx]):
                return (Tool.WIRE, wx, wy)
            break  # blocked

    # Build left road column
    for ry in range(road_start_y, road_end_y + 1):
        rx = road_left
        if not in_bounds(rx, ry):
            break
        if not bool(rm[ry, rx]) and not bool(pm[ry, rx]) and not bool(wm[ry, rx]):
            if bool(em[ry, rx]):
                return (Tool.ROAD, rx, ry)
            break

    # Build right road column
    for ry in range(road_start_y, road_end_y + 1):
        rx = road_right
        if not in_bounds(rx, ry):
            break
        if not bool(rm[ry, rx]) and not bool(pm[ry, rx]) and not bool(wm[ry, rx]):
            if bool(em[ry, rx]):
                return (Tool.ROAD, rx, ry)
            break

    # Horizontal cross roads every 6 rows between the two road columns
    for hy in range(road_start_y + 3, road_end_y + 1, 6):
        for hx in range(road_left, road_right + 1):
            if not in_bounds(hx, hy):
                continue
            if not bool(rm[hy, hx]) and not bool(pm[hy, hx]) and not bool(wm[hy, hx]):
                if bool(em[hy, hx]):
                    return (Tool.ROAD, hx, hy)

    # Horizontal wire branches from spine every 6 rows to reach zones
    for hy in range(wire_start_y + 3, wire_end_y + 1, 6):
        if not in_bounds(spine_x, hy) or not (bool(wm[hy, spine_x]) or bool(pm[hy, spine_x])):
            continue
        # Extend wire left to road_left and right to road_right
        for hx in range(spine_x - 1, road_left - 2, -1):
            if not in_bounds(hx, hy):
                break
            if bool(wm[hy, hx]) or bool(pm[hy, hx]):
                continue
            if bool(em[hy, hx]):
                return (Tool.WIRE, hx, hy)
            break
        for hx in range(spine_x + 1, road_right + 3):
            if not in_bounds(hx, hy):
                break
            if bool(wm[hy, hx]) or bool(pm[hy, hx]):
                continue
            if bool(em[hy, hx]):
                return (Tool.WIRE, hx, hy)
            break

    # Zone placement: build neighbor masks for road and wire proximity
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        step_hash = int(obs.step * 17 + int(obs.city_pop * 3)) % max(len(cxs), 1)
        for offset in range(min(len(cxs), 60)):
            k = (step_hash + offset * 11) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # Second power plant when zone count grows
    if total_zones > 15 or obs.city_pop > 200:
        p2x = spine_x
        p2y = min(py + 65, WORLD_H - 5)
        nearby_plant = False
        for dy in range(-6, 7):
            for dx in range(-6, 7):
                ny, nx2 = p2y + dy, p2x + dx
                if in_bounds(nx2, ny) and bool(pm[ny, nx2]):
                    nearby_plant = True
        if not nearby_plant and in_bounds(p2x, p2y) and bool(em[p2y, p2x]):
            return (Tool.COALPOWER, p2x, p2y)

    # Also add a second neighborhood cluster to the left of plant
    if total_zones > 20 or obs.city_pop > 400:
        # Second spine to the left
        spine2_x = px - 6
        spine2_start_y = py + 2
        spine2_end_y = min(py + 40, WORLD_H - 4)
        if in_bounds(spine2_x, spine2_start_y):
            for wy in range(spine2_start_y, spine2_end_y + 1):
                if not in_bounds(spine2_x, wy):
                    break
                if not bool(wm[wy, spine2_x]) and not bool(pm[wy, spine2_x]):
                    if bool(em[wy, spine2_x]):
                        return (Tool.WIRE, spine2_x, wy)
                    break

    # Services after some population
    if obs.city_pop > 150:
        fx, fy = spine_x - 1, py - 6
        if in_bounds(fx, fy) and bool(em[fy, fx]):
            return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 300:
        fx2, fy2 = spine_x + 1, py - 6
        if in_bounds(fx2, fy2) and bool(em[fy2, fx2]):
            return (Tool.POLICESTATION, fx2, fy2)

    # Fallback: extend wires from existing wire frontier
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        step_k = int(obs.step * 7) % len(wire_xs)
        wx_s, wy_s = int(wire_xs[step_k]), int(wire_ys[step_k])
        for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx2, ny2 = wx_s + dx2, wy_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)

    # Fallback: extend roads
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = int(obs.step * 13) % len(road_xs)
        rx_s, ry_s = int(road_xs[step_k]), int(road_ys[step_k])
        for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx2, ny2 = rx_s + dx2, ry_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Hybrid policy combining best ideas from both parents:
    - Vertical wire+road spine (from Parent B) for reliable power/road
    - Two power plants for better coverage (from Parent A)
    - Zones flanking spine with lateral wires
    - Balanced R/C/I ratio
    - Compact, reliable infrastructure first
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    cx, cy = 60, 50  # center of map

    def has_tile(mask, x, y):
        if 0 <= y < WORLD_H and 0 <= x < WORLD_W:
            return bool(mask[y, x])
        return False

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        all_zone = resm | comm | indm
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone[rr, rc]:
                    return False
        return True

    def zone_present(zr, zc):
        all_zone = resm | comm | indm
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone[rr, rc]:
                        return True
        return False

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Layout:
    # wire spine col1 and col2 (two parallel wires for better coverage)
    # road between them or adjacent
    # plant to the left of left wire
    # zones on both sides

    wire_col1 = cx - 1   # left wire spine
    wire_col2 = cx + 1   # right wire spine (parallel)
    road_col = cx        # road between the two wires

    left_zcol = wire_col1 - 4   # left zone column
    right_zcol = wire_col2 + 4  # right zone column

    plant1_x = wire_col1 - 8
    plant1_y = cy
    plant2_x = wire_col2 + 8
    plant2_y = cy

    # Adaptive spine extent
    if obs.city_pop < 100:
        spine_half = 10
    elif obs.city_pop < 300:
        spine_half = 18
    elif obs.city_pop < 600:
        spine_half = 24
    else:
        spine_half = 30

    spine_min = max(1, cy - spine_half)
    spine_max = min(WORLD_H - 2, cy + spine_half)
    spine_range = range(spine_min, spine_max + 1)

    num_plants = int(np.sum(pm)) // 9  # rough count (plant is 3x3=9 tiles)
    plant_tiles = np.sum(pm)

    # Phase 0: Place first coal power plant
    if plant_tiles == 0:
        return (Tool.COALPOWER, plant1_x, plant1_y)

    # Phase 1: Wire spine - left column
    for dy in spine_range:
        if not has_tile(wm, wire_col1, dy) and not has_tile(pm, wire_col1, dy):
            if not has_tile(rm, wire_col1, dy):
                return (Tool.WIRE, wire_col1, dy)

    # Phase 2: Road column (center)
    for dy in spine_range:
        if not has_tile(rm, road_col, dy) and not has_tile(pm, road_col, dy):
            if not has_tile(wm, road_col, dy):
                return (Tool.ROAD, road_col, dy)

    # Phase 3: Wire spine - right column
    for dy in spine_range:
        if not has_tile(wm, wire_col2, dy) and not has_tile(pm, wire_col2, dy):
            if not has_tile(rm, wire_col2, dy):
                return (Tool.WIRE, wire_col2, dy)

    # Phase 4: Place second power plant (right side)
    if plant_tiles < 18:  # only one plant so far
        if 2 <= plant2_x <= WORLD_W - 3 and 2 <= plant2_y <= WORLD_H - 3:
            # Check area is mostly empty
            area_ok = True
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    if not (0 <= plant2_y + dr < WORLD_H and 0 <= plant2_x + dc < WORLD_W):
                        area_ok = False
                    elif pm[plant2_y + dr, plant2_x + dc]:
                        area_ok = False  # already a plant tile
            if area_ok and em[plant2_y, plant2_x]:
                return (Tool.COALPOWER, plant2_x, plant2_y)

    wire_rows1 = [r for r in spine_range if wm[r, wire_col1]]
    wire_rows2 = [r for r in spine_range if wm[r, wire_col2]]
    road_rows = [r for r in spine_range if rm[r, road_col]]

    # Phase 5: Lateral wires from left spine to left zones
    for wr in wire_rows1:
        for wc in range(wire_col1 - 1, left_zcol - 2, -1):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc] or pm[wr, wc]:
                    break
                if em[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif rm[wr, wc]:
                    continue
                else:
                    break

    # Phase 6: Lateral wires from right spine to right zones
    for wr in wire_rows2:
        for wc in range(wire_col2 + 1, right_zcol + 2):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc] or pm[wr, wc]:
                    break
                if em[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif rm[wr, wc]:
                    continue
                else:
                    break

    # Phase 7: Place zones flanking spine
    zone_rows = list(range(spine_min + 1, spine_max - 1, 3))

    for zr in zone_rows:
        wire_near_l = any(abs(zr - wr) <= 2 for wr in wire_rows1)
        wire_near_r = any(abs(zr - wr) <= 2 for wr in wire_rows2)
        road_near = any(abs(zr - rr) <= 2 for rr in road_rows)

        if road_near:
            # Left zone
            if wire_near_l:
                zc = left_zcol
                if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                    return (pick_tool(), zc, zr)

            # Right zone
            if wire_near_r:
                zc = right_zcol
                if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                    return (pick_tool(), zc, zr)

    # Phase 8: Second tier of zones further out if city growing
    if obs.city_pop > 100:
        left2_zcol = max(2, left_zcol - 4)
        right2_zcol = min(WORLD_W - 3, right_zcol + 4)

        for zr in zone_rows:
            road_near = any(abs(zr - rr) <= 2 for rr in road_rows)
            if not road_near:
                continue
            for zc in [left2_zcol, right2_zcol]:
                if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                    r0 = max(0, zr - 5); r1 = min(WORLD_H, zr + 6)
                    c0 = max(0, zc - 5); c1 = min(WORLD_W, zc + 6)
                    if np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1]):
                        return (pick_tool(), zc, zr)

    # Phase 9: Additional lateral roads for connectivity at zone rows
    if obs.city_pop > 50:
        for zr in zone_rows[::2]:
            if 0 <= zr < WORLD_H:
                for rc in range(left_zcol - 1, right_zcol + 2):
                    if 0 <= rc < WORLD_W:
                        if em[zr, rc] and not pm[zr, rc] and not wm[zr, rc]:
                            return (Tool.ROAD, rc, zr)

    # Phase 10: Third power plant if needed
    if obs.city_pop > 400 and plant_tiles < 27:
        px3 = cx
        py3 = spine_min - 5
        if 2 <= px3 <= WORLD_W - 3 and 2 <= py3 <= WORLD_H - 3:
            if em[py3, px3]:
                return (Tool.COALPOWER, px3, py3)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy.
    Strategy:
    - Read current map each step to decide next action.
    - Place coal plant, build wire spine, road, then zones.
    - Expand in both directions (up/down AND left/right) based on current coverage.
    - Use dual-spine approach: wire col + road col on each side.
    - Zones placed where wire+road coverage confirmed each step.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    cx, cy = 60, 50  # map center

    has_plant = np.any(pm)
    has_wire = np.any(wm)
    has_road = np.any(rm)

    # Phase 1: place coal power plant at a fixed anchor
    plant_cx, plant_cy = cx - 10, cy
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Gather positions
    wire_positions = set(zip(*np.where(wm))) if has_wire else set()
    road_positions = set(zip(*np.where(rm))) if has_road else set()
    res_pos = set(zip(*np.where(res_mask(tm))))
    com_pos = set(zip(*np.where(com_mask(tm))))
    ind_pos = set(zip(*np.where(ind_mask(tm))))
    all_zones = res_pos | com_pos | ind_pos

    res_count = len(res_pos)
    com_count = len(com_pos)
    ind_count = len(ind_pos)

    # Layout: wire spine on wire_col, road on road_col (to the right)
    # Left zones at left_zone_col, right zones at right_zone_col
    wire_col = plant_cx + 3
    road_col = wire_col + 2
    left_zone_col = wire_col - 3
    right_zone_col = road_col + 3

    # Vertical span grows with population
    base_span = 10
    extra_span = min(25, obs.city_pop // 40)
    target_span = base_span + extra_span
    tmin = max(2, cy - target_span)
    tmax = min(WORLD_H - 3, cy + target_span)

    # Wire rows in spine column
    wire_rows_in_col = sorted(r for (r, c) in wire_positions if c == wire_col)
    road_rows_in_col = sorted(r for (r, c) in road_positions if c == road_col)
    wire_rows_set = set(wire_rows_in_col)
    road_rows_set = set(road_rows_in_col)

    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def zone_nearby(zr, zc):
        return any(abs(zr - pr) <= 2 and abs(zc - pc) <= 2 for (pr, pc) in all_zones)

    # Phase 2: extend wire spine vertically (from plant level outward)
    if not wire_rows_in_col:
        # First wire adjacent to plant
        return (Tool.WIRE, wire_col, plant_cy)
    else:
        min_wr = min(wire_rows_in_col)
        max_wr = max(wire_rows_in_col)
        # Extend downward first
        if max_wr < tmax:
            nr = max_wr + 1
            if 0 < nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if min_wr > tmin:
            nr = min_wr - 1
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    # Phase 3: build road column - for each wire row, add road if missing
    if wire_rows_in_col:
        for wr in wire_rows_in_col:
            if wr not in road_rows_set and 0 <= road_col < WORLD_W:
                if em[wr, road_col]:
                    return (Tool.ROAD, road_col, wr)

    # Phase 4: lateral wires from spine to left zone column
    # For each wire row, fill wire between wire_col-1 down to left_zone_col+1
    if wire_rows_in_col and left_zone_col >= 0:
        for wr in wire_rows_in_col:
            for wc in range(wire_col - 1, left_zone_col, -1):
                if 0 <= wc < WORLD_W and em[wr, wc]:
                    return (Tool.WIRE, wc, wr)

    # Phase 5: lateral roads from road col to right zone column
    if wire_rows_in_col and right_zone_col < WORLD_W:
        for wr in wire_rows_in_col:
            for rc in range(road_col + 1, right_zone_col):
                if 0 <= rc < WORLD_W and em[wr, rc]:
                    return (Tool.ROAD, rc, wr)

    # Phase 6: place zones where powered (wire nearby) and roaded
    zone_rows = sorted(wire_rows_in_col)
    for zr in zone_rows:
        wire_near = any(abs(zr - wr) <= 1 for wr in wire_rows_set)
        road_near = any(abs(zr - rr) <= 2 for rr in road_rows_set)
        if not (wire_near and road_near):
            continue

        for zc in [left_zone_col, right_zone_col]:
            if 2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3:
                if not zone_nearby(zr, zc) and zone_area_free(zr, zc):
                    # Zone type selection: balanced mix
                    total = res_count + com_count + ind_count
                    if total == 0:
                        return (Tool.RESIDENTIAL, zc, zr)
                    ri = res_count / max(total, 1)
                    ci = com_count / max(total, 1)
                    ii = ind_count / max(total, 1)
                    # Target: ~50% res, ~25% com, ~25% ind
                    if ii < 0.22 and zr >= cy:
                        return (Tool.INDUSTRIAL, zc, zr)
                    elif ci < 0.22:
                        return (Tool.COMMERCIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

    # Phase 7: second wire column further right for expansion if pop > 200
    if obs.city_pop > 200:
        wire_col2 = road_col + 7
        road_col2 = wire_col2 + 2
        right_zone_col2 = road_col2 + 3

        wire_rows2 = sorted(r for (r, c) in wire_positions if c == wire_col2)
        road_rows2 = set(r for (r, c) in road_positions if c == road_col2)

        if wire_col2 < WORLD_W:
            # Connect wire from wire_col to wire_col2 on center row
            for wr in wire_rows_in_col:
                for wc in range(wire_col + 1, wire_col2):
                    if 0 <= wc < WORLD_W and em[wr, wc]:
                        return (Tool.WIRE, wc, wr)

            # Extend wire2 vertically
            if not wire_rows2:
                if em[cy, wire_col2]:
                    return (Tool.WIRE, wire_col2, cy)
            else:
                min_wr2 = min(wire_rows2)
                max_wr2 = max(wire_rows2)
                if max_wr2 < tmax:
                    nr = max_wr2 + 1
                    if 0 < nr < WORLD_H and (em[nr, wire_col2] or wm[nr, wire_col2]):
                        return (Tool.WIRE, wire_col2, nr)
                if min_wr2 > tmin:
                    nr = min_wr2 - 1
                    if 0 <= nr < WORLD_H and (em[nr, wire_col2] or wm[nr, wire_col2]):
                        return (Tool.WIRE, wire_col2, nr)

            # Road on road_col2
            for wr in wire_rows2:
                if wr not in road_rows2 and 0 <= road_col2 < WORLD_W and em[wr, road_col2]:
                    return (Tool.ROAD, road_col2, wr)

            # Zones on right_zone_col2
            for zr in sorted(wire_rows2):
                wire_near2 = any(abs(zr - wr) <= 1 for wr in wire_rows2)
                road_near2 = wr in road_rows2 for wr in [zr]
                # simplified check
                if 2 <= zr <= WORLD_H - 3 and 2 <= right_zone_col2 <= WORLD_W - 3:
                    if not zone_nearby(zr, right_zone_col2) and zone_area_free(zr, right_zone_col2):
                        return (Tool.RESIDENTIAL, right_zone_col2, zr)

    return None

def act(obs, state):
    """
    Closed-loop city builder:
    - Each step reads the current map and decides the next action reactively
    - Places coal plant, then extends wire FROM existing wire/plant
    - Extends roads FROM existing roads
    - Places zones adjacent to both roads and power
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # ---- Power plant placement ----
    has_plant = np.any(pm)
    if not has_plant:
        return (Tool.COALPOWER, 20, 50)

    # ---- Count zones ----
    res_count = int(np.sum(resm)) // 9 + 1
    com_count = int(np.sum(comm)) // 9 + 1
    ind_count = int(np.sum(indm)) // 9 + 1
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        r = res_count / total_zones
        c = com_count / total_zones
        i = ind_count / total_zones
        if c < 0.25:
            return Tool.COMMERCIAL
        if i < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # ---- Extend wire from existing wire/plant toward the right ----
    # Find the rightmost wire or plant tile on rows near y=50
    spine_y = 50
    wire_ys, wire_xs = np.where(wm)
    plant_ys, plant_xs = np.where(pm)

    # All powered tiles (wire or plant)
    powered = wm | pm

    # Find frontier: empty tiles adjacent to powered tiles (4-connected)
    # We want to extend wire rightward first, then branch vertically
    powered_coords = list(zip(plant_ys.tolist(), plant_xs.tolist())) + \
                     list(zip(wire_ys.tolist(), wire_xs.tolist()))

    # Build a set for fast lookup
    powered_set = set(powered_coords)

    # Find rightmost powered x on spine row
    spine_powered_xs = [x for (y, x) in powered_set if abs(y - spine_y) <= 2]
    max_powered_x = max(spine_powered_xs) if spine_powered_xs else 20

    # Target: extend wire to x=90
    wire_target_x = 90
    if max_powered_x < wire_target_x:
        # Try to place wire at (max_powered_x+1, spine_y)
        nx, ny = max_powered_x + 1, spine_y
        if in_bounds(nx, ny) and not bool(pm[ny, nx]):
            # Check if adjacent to powered
            for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
                ax, ay = nx+dx, ny+dy
                if in_bounds(ax, ay) and bool(powered[ay, ax]):
                    return (Tool.WIRE, nx, ny)
        # Fallback: find any empty tile adjacent to powered on spine
        for px_c, py_c in sorted(powered_coords, key=lambda c: -c[1]):
            wy, wx = py_c, px_c
            if abs(wy - spine_y) <= 3:
                rx, ry = wx + 1, wy
                if in_bounds(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    return (Tool.WIRE, rx, ry)

    # ---- Second power plant if wire has extended far ----
    if max_powered_x >= 70:
        # Check if second plant exists near x=90
        near2 = False
        for dy in range(-3, 4):
            for dx2 in range(-3, 4):
                ny2, nx2 = 50 + dy, 90 + dx2
                if in_bounds(nx2, ny2) and bool(pm[ny2, nx2]):
                    near2 = True
        if not near2 and bool(em[50, 90]):
            return (Tool.COALPOWER, 90, 50)

    # ---- Build vertical wire branches from spine ----
    # Every 8 columns, extend wire 6 tiles up and down
    branch_cols = list(range(25, 91, 8))
    for bx in branch_cols:
        if not bool(powered[spine_y, bx]):
            continue
        for sign in [-1, 1]:
            for dy in range(1, 7):
                wy2, wx2 = spine_y + sign * dy, bx
                if not in_bounds(wx2, wy2):
                    break
                if bool(powered[wy2, wx2]):
                    continue
                if bool(em[wy2, wx2]):
                    return (Tool.WIRE, wx2, wy2)
                break

    # ---- Build horizontal roads parallel to spine ----
    road_ys_arr, road_xs_arr = np.where(rm)
    road_set = set(zip(road_ys_arr.tolist(), road_xs_arr.tolist()))

    # Roads at spine_y - 4 and spine_y + 4
    for road_row in [spine_y - 4, spine_y + 4]:
        if not in_bounds(0, road_row):
            continue
        # Find leftmost/rightmost powered column near this row
        nearby_powered_xs = [x for (y, x) in powered_set if abs(y - road_row) <= 5]
        if not nearby_powered_xs:
            continue
        min_px = max(min(nearby_powered_xs) - 1, 2)
        max_px = min(max(nearby_powered_xs) + 1, WORLD_W - 3)
        # Extend road rightward from existing road endpoint
        road_on_row = sorted([x for (y, x) in road_set if y == road_row])
        if road_on_row:
            # Extend from rightmost
            ext_x = road_on_row[-1] + 1
            if ext_x <= max_px and bool(em[road_row, ext_x]) and not bool(pm[road_row, ext_x]):
                return (Tool.ROAD, ext_x, road_row)
            # Extend from leftmost
            ext_x2 = road_on_row[0] - 1
            if ext_x2 >= min_px and bool(em[road_row, ext_x2]) and not bool(pm[road_row, ext_x2]):
                return (Tool.ROAD, ext_x2, road_row)
        else:
            # Start road adjacent to nearest powered tile
            for start_x in range(min_px, max_px + 1):
                if bool(em[road_row, start_x]) and not bool(pm[road_row, start_x]):
                    return (Tool.ROAD, start_x, road_row)

    # ---- Vertical connector roads every 8 cols ----
    for vc in range(22, 93, 8):
        for vr in range(spine_y - 4, spine_y + 5):
            if not in_bounds(vc, vr):
                continue
            if (vr, vc) not in road_set and bool(em[vr, vc]) and not bool(pm[vr, vc]):
                # Only if adjacent to existing road
                adj_road = any((vr+dy2, vc+dx2) in road_set
                               for dx2, dy2 in [(1,0),(-1,0),(0,1),(0,-1)])
                if adj_road or vr == spine_y - 4 or vr == spine_y + 4:
                    return (Tool.ROAD, vc, vr)

    # ---- Zone placement: scan for tiles near both road and wire ----
    # Compute neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= powered[sr0:sr1, sc0:sc1]

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not bool(em[nr, nc]):
                    return False
        return True

    # Candidate zone locations: rows near roads, powered
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    # Also exclude the spine row itself and road rows
    for exclude_y in [spine_y, spine_y-4, spine_y+4]:
        if 0 <= exclude_y < WORLD_H:
            cand_mask[exclude_y, :] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prefer zones near spine (within 10 rows), spaced out
        best = None
        best_score = -1
        step_seed = obs.step % max(len(cxs), 1)
        for offset in range(min(len(cxs), 80)):
            k = (step_seed + offset * 7) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                score = 10 - abs(zy - spine_y)  # prefer near spine
                if score > best_score:
                    best_score = score
                    best = (zx, zy)
                if best_score >= 9:
                    break
        if best:
            return (pick_tool(), best[0], best[1])

    # ---- Services once population grows ----
    if obs.city_pop > 500:
        for fx, fy in [(25, spine_y - 10), (60, spine_y - 10)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 800:
        for px2, py2 in [(25, spine_y + 10), (60, spine_y + 10)]:
            if in_bounds(px2, py2) and bool(em[py2, px2]):
                return (Tool.POLICESTATION, px2, py2)

    # ---- Fallback: extend any road ----
    if len(road_xs_arr) > 0:
        k = int(obs.step * 11) % len(road_xs_arr)
        rx, ry = int(road_xs_arr[k]), int(road_ys_arr[k])
        for dx2, dy2 in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx2, ny2 = rx + dx2, ry + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Hybrid policy combining best ideas from both parents:
    - Parent B's compact wire+road spine layout (wire_col, road_col adjacent)
    - Parent A's balanced zone ratios and lateral connections
    - Dynamic span expansion based on population
    - Lateral wires to left zones, lateral roads to right zones
    - Second road column expansion when population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    cx, cy = 60, 50

    has_plant = np.any(pm)

    # Phase 1: Place coal power plant
    plant_cx, plant_cy = cx - 6, cy
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Find actual plant position
    plant_positions = list(zip(*np.where(pm)))
    if plant_positions:
        plant_row, plant_col = plant_positions[0]
        plant_cy, plant_cx = plant_row, plant_col

    # Wire spine column just right of plant footprint
    wire_col = plant_cx + 3
    road_col = wire_col + 1  # road immediately right of wire

    # Zone columns
    left_zone_col = wire_col - 3
    right_zone_col = road_col + 3

    # Dynamic span based on population
    base_span = 10
    extra_span = min(25, obs.city_pop // 40)
    target_span = base_span + extra_span
    tmin = max(1, cy - target_span)
    tmax = min(WORLD_H - 2, cy + target_span)

    wire_positions = set(zip(*np.where(wm))) if np.any(wm) else set()
    road_positions = set(zip(*np.where(rm))) if np.any(rm) else set()
    res_positions = set(zip(*np.where(res_mask(tm))))
    com_positions = set(zip(*np.where(com_mask(tm))))
    ind_positions = set(zip(*np.where(ind_mask(tm))))

    res_count = len(res_positions)
    com_count = len(com_positions)
    ind_count = len(ind_positions)

    wire_rows_in_col = sorted(r for (r, c) in wire_positions if c == wire_col)
    road_rows_in_col = sorted(r for (r, c) in road_positions if c == road_col)
    wire_rows_set = set(wire_rows_in_col)
    road_rows_set = set(road_rows_in_col)

    # Phase 2: Extend wire spine vertically
    if not wire_rows_in_col:
        return (Tool.WIRE, wire_col, plant_cy)
    else:
        min_wr = min(wire_rows_in_col)
        max_wr = max(wire_rows_in_col)
        # Extend downward first
        if max_wr < tmax:
            nr = max_wr + 1
            if 0 <= nr < WORLD_H:
                return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if min_wr > tmin:
            nr = min_wr - 1
            if 0 <= nr < WORLD_H:
                return (Tool.WIRE, wire_col, nr)

    # Phase 3: Build road column adjacent to wire spine
    for wr in wire_rows_in_col:
        if wr not in road_rows_set and 0 <= road_col < WORLD_W:
            return (Tool.ROAD, road_col, wr)

    # Helper functions
    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def already_zone_nearby(zr, zc, all_zones):
        return any(abs(zr - pr) <= 1 and abs(zc - pc) <= 1 for (pr, pc) in all_zones)

    all_zones = res_positions | com_positions | ind_positions

    # Phase 4: Add lateral wires from spine to left zone column
    for wr in wire_rows_in_col:
        for wc in range(wire_col - 1, left_zone_col - 1, -1):
            if 0 <= wc < WORLD_W and em[wc if False else wc, wr if False else wr]:
                # correct indexing: em[row, col]
                break
        for wc in range(wire_col - 1, left_zone_col - 1, -1):
            if 0 <= wc < WORLD_W and em[wr, wc]:
                # Don't overwrite plant area
                if not pm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
        break  # one row at a time

    # Phase 4b: continue lateral wires for all rows
    for wr in wire_rows_in_col:
        for wc in range(wire_col - 1, left_zone_col - 1, -1):
            if 0 <= wc < WORLD_W and em[wr, wc] and not pm[wr, wc]:
                return (Tool.WIRE, wc, wr)

    # Phase 5: Add lateral roads from road col to right zone column
    for wr in wire_rows_in_col:
        for rc in range(road_col + 1, right_zone_col + 1):
            if 0 <= rc < WORLD_W and em[wr, rc]:
                return (Tool.ROAD, rc, wr)

    # Phase 6: Place zones
    def pick_zone_type(zc, zr):
        total = res_count + com_count + ind_count + 1
        # ~50% RES, ~25% COM, ~25% IND
        if ind_count * 4 < total:
            return Tool.INDUSTRIAL
        elif com_count * 4 < total:
            return Tool.COMMERCIAL
        else:
            return Tool.RESIDENTIAL

    for zr in wire_rows_in_col:
        road_nearby = any(abs(zr - rr) <= 2 for rr in road_rows_set)
        wire_nearby = zr in wire_rows_set

        if not (road_nearby and wire_nearby):
            continue

        # Left zone
        zc = left_zone_col
        if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
            if not already_zone_nearby(zr, zc, all_zones) and zone_area_free(zr, zc):
                zt = pick_zone_type(zc, zr)
                all_zones = all_zones | {(zr, zc)}  # update locally
                return (zt, zc, zr)

        # Right zone
        zc = right_zone_col
        if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
            if not already_zone_nearby(zr, zc, all_zones) and zone_area_free(zr, zc):
                # Right side prefers RES/COM
                total = res_count + com_count + ind_count + 1
                if com_count * 4 < total:
                    zt = Tool.COMMERCIAL
                else:
                    zt = Tool.RESIDENTIAL
                all_zones = all_zones | {(zr, zc)}
                return (zt, zc, zr)

    # Phase 7: Expand with second road column when population grows
    if obs.city_pop > 250:
        road_col2 = road_col + 7
        right_zone_col2 = road_col2 + 3

        # Extend wire horizontally to reach road_col2
        for wr in wire_rows_in_col:
            for wc in range(wire_col + 1, road_col2):
                if 0 <= wc < WORLD_W and em[wr, wc]:
                    return (Tool.WIRE, wc, wr)
            break

        # Build second road column
        for wr in wire_rows_in_col:
            if 0 <= road_col2 < WORLD_W and wr not in set(r for (r, c) in road_positions if c == road_col2):
                if em[wr, road_col2]:
                    return (Tool.ROAD, road_col2, wr)

        # Lateral roads to second right zone col
        for wr in wire_rows_in_col:
            for rc in range(road_col2 + 1, right_zone_col2 + 1):
                if 0 <= rc < WORLD_W and em[wr, rc]:
                    return (Tool.ROAD, rc, wr)

        # Zones at second right zone col
        for zr in wire_rows_in_col:
            zc = right_zone_col2
            if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                if not already_zone_nearby(zr, zc, all_zones) and zone_area_free(zr, zc):
                    return (Tool.RESIDENTIAL, zc, zr)

    # Phase 8: Also expand left if population high
    if obs.city_pop > 400:
        far_left_col = left_zone_col - 4
        # More lateral wires
        for wr in wire_rows_in_col:
            for wc in range(left_zone_col - 1, far_left_col - 1, -1):
                if 0 <= wc < WORLD_W and em[wr, wc] and not pm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
            break
        # Zones far left
        for zr in wire_rows_in_col:
            zc = far_left_col
            if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                if not already_zone_nearby(zr, zc, all_zones) and zone_area_free(zr, zc):
                    return (Tool.RESIDENTIAL, zc, zr)

    # Phase 9: Add nuclear power if very large population
    if obs.city_pop > 600:
        nuke_x = plant_cx - 8
        nuke_y = plant_cy + 8
        if 1 <= nuke_y < WORLD_H - 1 and 1 <= nuke_x < WORLD_W - 1:
            area = pm[max(0, nuke_y-1):nuke_y+2, max(0, nuke_x-1):nuke_x+2]
            if not np.any(area):
                return (Tool.NUCLEARPOWER, nuke_x, nuke_y)

    return None

def act(obs, state):
    """
    Evolved policy combining best ideas from both parents:
    - Compact vertical spine: wire col + road col
    - Lateral wires to power left zones
    - Balanced R/C/I zones flanking spine
    - Adaptive spine length
    - Multiple power plants as city grows
    - Horizontal roads for connectivity
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def has_tile(mask, x, y):
        if 0 <= y < WORLD_H and 0 <= x < WORLD_W:
            return bool(mask[y, x])
        return False

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Layout constants
    # Plant left of wire spine
    plant_x = cx - 6
    plant_y = cy
    wire_col = cx - 1      # vertical wire spine
    road_col = cx          # vertical road spine (adjacent to wire)
    left_zcol = wire_col - 3   # left zone column (center)
    right_zcol = road_col + 3  # right zone column (center)

    # Clamp
    wire_col  = max(2, min(WORLD_W - 3, wire_col))
    road_col  = max(2, min(WORLD_W - 3, road_col))
    left_zcol = max(2, min(WORLD_W - 3, left_zcol))
    right_zcol= max(2, min(WORLD_W - 3, right_zcol))
    plant_x   = max(2, min(WORLD_W - 3, plant_x))

    # Adaptive spine half-length
    pop = obs.city_pop
    if pop < 50:
        spine_half = 10
    elif pop < 200:
        spine_half = 15
    elif pop < 500:
        spine_half = 20
    else:
        spine_half = 25

    spine_min = max(1, cy - spine_half)
    spine_max = min(WORLD_H - 2, cy + spine_half)
    spine_range = range(spine_min, spine_max + 1)

    # ---- Phase 0: Place first coal plant ----
    if not np.any(pm):
        return (Tool.COALPOWER, plant_x, plant_y)

    # ---- Phase 1: Wire spine (vertical) ----
    for dy in spine_range:
        if not has_tile(wm, wire_col, dy) and not has_tile(pm, wire_col, dy) and not has_tile(rm, wire_col, dy):
            return (Tool.WIRE, wire_col, dy)

    # ---- Phase 2: Road column adjacent to wire ----
    for dy in spine_range:
        if not has_tile(rm, road_col, dy) and not has_tile(pm, road_col, dy) and not has_tile(wm, road_col, dy):
            return (Tool.ROAD, road_col, dy)

    # Precompute wire/road rows
    wire_rows = [r for r in spine_range if wm[r, wire_col]]
    road_rows = [r for r in spine_range if rm[r, road_col]]

    # ---- Phase 3: Lateral wires to power left zones ----
    # For each wire row, extend wire leftward to reach left_zcol + 2
    target_left_wire = left_zcol + 2
    for wr in wire_rows:
        # Extend from wire_col-1 leftward
        for wc in range(wire_col - 1, target_left_wire - 1, -1):
            if not (0 <= wc < WORLD_W):
                break
            if wm[wr, wc] or pm[wr, wc]:
                break  # already wired or blocked by plant
            if rm[wr, wc]:
                break  # don't wire over road
            if em[wr, wc]:
                return (Tool.WIRE, wc, wr)
            else:
                break

    # ---- Phase 4: Place zones flanking spine ----
    # Zone rows spaced by 3 to avoid overlap
    zone_rows = list(range(spine_min + 1, spine_max - 1, 3))

    all_zone_m = resm | comm | indm

    def zone_area_clear(zr, zc):
        """Check 3x3 area centered at (zc, zr) is clear of non-zone tiles."""
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_m[rr, rc]:
                    return False
        return True

    def zone_present_near(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_m[rr, rc]:
                        return True
        return False

    for zr in zone_rows:
        wire_near = any(abs(zr - wr) <= 2 for wr in wire_rows)
        road_near = any(abs(zr - rr) <= 2 for rr in road_rows)
        if not (wire_near and road_near):
            continue

        # Left zone: check that lateral wire reaches it
        zc = left_zcol
        # Wire should exist at (zr, zc+2) or closer to spine
        lateral_wired = any(wm[zr, wc] for wc in range(zc - 1, wire_col) if 0 <= wc < WORLD_W)
        if lateral_wired and not zone_present_near(zr, zc) and zone_area_clear(zr, zc):
            return (pick_tool(), zc, zr)

        # Right zone: road is adjacent, zones on right need wire too
        zc = right_zcol
        # Wire from road_col+1 to right_zcol-2
        right_wired = any(wm[zr, wc] for wc in range(road_col, zc + 2) if 0 <= wc < WORLD_W)
        if right_wired and not zone_present_near(zr, zc) and zone_area_clear(zr, zc):
            return (pick_tool(), zc, zr)

    # ---- Phase 5: Lateral wires rightward to power right zones ----
    target_right_wire = right_zcol - 2
    for wr in wire_rows:
        for wc in range(road_col + 1, target_right_wire + 2):
            if not (0 <= wc < WORLD_W):
                break
            if wm[wr, wc] or pm[wr, wc]:
                break
            if rm[wr, wc]:
                continue  # road is ok to skip
            if em[wr, wc]:
                return (Tool.WIRE, wc, wr)
            else:
                break

    # ---- Phase 6: Second coal plant if population growing ----
    if pop > 200 and int(np.sum(pm)) < 9:
        px2 = plant_x + 22
        py2 = plant_y
        px2 = max(2, min(WORLD_W - 3, px2))
        if em[py2, px2]:
            # Wire connecting second plant to spine
            for wc in range(px2 - 1, road_col, -1):
                if 0 <= wc < WORLD_W:
                    if wm[py2, wc] or pm[py2, wc]:
                        break
                    if em[py2, wc]:
                        return (Tool.WIRE, wc, py2)
                    else:
                        break
            return (Tool.COALPOWER, px2, py2)

    # ---- Phase 7: Second tier of zones ----
    if pop > 150:
        left2_zcol  = max(2, min(WORLD_W - 3, left_zcol - 5))
        right2_zcol = max(2, min(WORLD_W - 3, right_zcol + 5))

        for zr in zone_rows:
            wire_near = any(abs(zr - wr) <= 2 for wr in wire_rows)
            road_near = any(abs(zr - rr) <= 2 for rr in road_rows)
            if not (wire_near and road_near):
                continue
            for zc in [left2_zcol, right2_zcol]:
                if not zone_present_near(zr, zc) and zone_area_clear(zr, zc):
                    # Check wire/road nearby
                    r0 = max(0, zr - 4); r1 = min(WORLD_H, zr + 5)
                    c0 = max(0, zc - 4); c1 = min(WORLD_W, zc + 5)
                    if np.any(wm[r0:r1, c0:c1]) and np.any(rm[r0:r1, c0:c1]):
                        return (pick_tool(), zc, zr)

    # ---- Phase 8: Horizontal roads at top/bottom of spine for connectivity ----
    if pop > 100:
        for rr in [spine_min, spine_max]:
            if 0 <= rr < WORLD_H:
                for rc in range(max(0, left_zcol - 1), min(WORLD_W, right_zcol + 2)):
                    if em[rr, rc] and not pm[rr, rc]:
                        return (Tool.ROAD, rc, rr)

    # ---- Phase 9: Third coal plant for large city ----
    if pop > 500 and int(np.sum(pm)) < 18:
        px3 = plant_x + 10
        py3 = plant_y - 20
        px3 = max(2, min(WORLD_W - 3, px3))
        py3 = max(2, min(WORLD_H - 3, py3))
        if em[py3, px3]:
            return (Tool.COALPOWER, px3, py3)

    return None

def act(obs, state):
    """
    Hybrid policy combining best of both parents:
    - Fixed plant location (Parent A approach, reliable)
    - Wire spine + road column (Parent A)
    - Zones on both sides with lateral connections (Parent A)
    - Better zone spacing and balance (Parent B ideas)
    - Multiple clusters as population grows (Parent A Phase 7/8)
    - More zones placed per iteration
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # Fixed layout anchored at map center-left
    plant_cx, plant_cy = 54, 50

    # Primary cluster columns
    wire_col = plant_cx + 4   # col 58
    road_col = wire_col + 2   # col 60
    left_zone_col = wire_col - 3   # col 55
    right_zone_col = road_col + 3  # col 63

    has_plant = np.any(pm)

    # Phase 1: Place coal power plant
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Collect positions
    wire_positions = set(zip(*np.where(wm))) if np.any(wm) else set()
    road_positions = set(zip(*np.where(rm))) if np.any(rm) else set()
    res_positions = set(zip(*np.where(res_m))) if np.any(res_m) else set()
    com_positions = set(zip(*np.where(com_m))) if np.any(com_m) else set()
    ind_positions = set(zip(*np.where(ind_m))) if np.any(ind_m) else set()
    all_zones = res_positions | com_positions | ind_positions

    res_count = len(res_positions)
    com_count = len(com_positions)
    ind_count = len(ind_positions)

    # Dynamic vertical span
    base_span = 12
    extra_span = min(30, obs.city_pop // 30)
    target_span = base_span + extra_span
    tmin = max(2, plant_cy - target_span)
    tmax = min(WORLD_H - 3, plant_cy + target_span)

    wire_rows_in_col = sorted(r for (r, c) in wire_positions if c == wire_col)
    road_rows_set = set(r for (r, c) in road_positions if c == road_col)

    # Phase 2: Extend wire spine vertically
    if not wire_rows_in_col:
        for try_r in [plant_cy, plant_cy - 1, plant_cy + 1]:
            if 0 <= try_r < WORLD_H and (em[try_r, wire_col] or wm[try_r, wire_col]):
                return (Tool.WIRE, wire_col, try_r)
        return (Tool.WIRE, wire_col, plant_cy)
    else:
        min_wr = min(wire_rows_in_col)
        max_wr = max(wire_rows_in_col)
        if max_wr < tmax:
            nr = max_wr + 1
            if 0 < nr < WORLD_H:
                return (Tool.WIRE, wire_col, nr)
        if min_wr > tmin:
            nr = min_wr - 1
            if 0 <= nr < WORLD_H:
                return (Tool.WIRE, wire_col, nr)

    wire_rows_set = set(wire_rows_in_col)

    # Phase 3: Build road column matching wire coverage
    for wr in wire_rows_in_col:
        if wr not in road_rows_set and 0 <= road_col < WORLD_W:
            return (Tool.ROAD, road_col, wr)

    # Helpers
    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def already_zone_nearby(zr, zc):
        return any(abs(zr - pr) <= 2 and abs(zc - pc) <= 2 for (pr, pc) in all_zones)

    def pick_zone_type(prefer_right=False):
        total = res_count + com_count + ind_count
        if res_count == 0:
            return Tool.RESIDENTIAL
        if ind_count * 4 < total + 1:
            return Tool.INDUSTRIAL
        if com_count * 4 < total + 1:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Phase 4: Place lateral wires from spine toward left zone col
    for wr in wire_rows_in_col:
        for wc in range(wire_col - 1, max(left_zone_col - 2, 0), -1):
            if 0 <= wc < WORLD_W and not wm[wr, wc] and em[wr, wc]:
                return (Tool.WIRE, wc, wr)

    # Phase 5: Place lateral roads from road col toward right zone col
    for wr in wire_rows_in_col:
        for rc in range(road_col + 1, min(right_zone_col + 2, WORLD_W)):
            if 0 <= rc < WORLD_W and not rm[wr, rc] and em[wr, rc]:
                return (Tool.ROAD, rc, wr)

    # Phase 6: Place zones (every 3 rows for spacing)
    for zr in sorted(wire_rows_in_col):
        road_nearby = any(abs(zr - rr) <= 2 for rr in road_rows_set)
        wire_nearby = any(abs(zr - wr) <= 2 for wr in wire_rows_in_col)
        if not road_nearby:
            continue

        for zc in [left_zone_col, right_zone_col]:
            if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                if not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                    return (pick_zone_type(zc == right_zone_col), zc, zr)

    # Phase 7: Second cluster to the right (pop >= 150)
    if obs.city_pop >= 150:
        wire_col2 = road_col + 8   # col 68
        road_col2 = wire_col2 + 2  # col 70
        left_zone_col2 = wire_col2 - 3
        right_zone_col2 = road_col2 + 3

        wire_rows2 = sorted(r for (r, c) in wire_positions if c == wire_col2)
        road_rows2 = set(r for (r, c) in road_positions if c == road_col2)

        if not wire_rows2:
            # Build horizontal bridge at plant_cy
            for wc in range(wire_col + 1, wire_col2 + 1):
                if em[plant_cy, wc]:
                    return (Tool.WIRE, wc, plant_cy)
        else:
            min_wr2 = min(wire_rows2)
            max_wr2 = max(wire_rows2)
            if max_wr2 < tmax:
                nr = max_wr2 + 1
                if 0 < nr < WORLD_H:
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > tmin:
                nr = min_wr2 - 1
                if 0 <= nr < WORLD_H:
                    return (Tool.WIRE, wire_col2, nr)

            for wr in wire_rows2:
                if wr not in road_rows2 and 0 <= road_col2 < WORLD_W:
                    return (Tool.ROAD, road_col2, wr)

            # Lateral wires for cluster 2
            for wr in wire_rows2:
                for wc in range(wire_col2 - 1, max(left_zone_col2 - 2, 0), -1):
                    if 0 <= wc < WORLD_W and not wm[wr, wc] and em[wr, wc]:
                        return (Tool.WIRE, wc, wr)

            # Lateral roads for cluster 2
            for wr in wire_rows2:
                for rc in range(road_col2 + 1, min(right_zone_col2 + 2, WORLD_W)):
                    if 0 <= rc < WORLD_W and not rm[wr, rc] and em[wr, rc]:
                        return (Tool.ROAD, rc, wr)

            for zr in sorted(wire_rows2):
                road_nearby2 = any(abs(zr - rr) <= 2 for rr in road_rows2)
                if not road_nearby2:
                    continue
                for zc in [left_zone_col2, right_zone_col2]:
                    if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                        if not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                            return (pick_zone_type(), zc, zr)

    # Phase 8: Third cluster to the left (pop >= 350)
    if obs.city_pop >= 350:
        wire_col3 = wire_col - 8   # col 50
        road_col3 = wire_col3 - 2  # col 48
        left_zone_col3 = road_col3 - 3
        right_zone_col3 = wire_col3 + 3

        wire_rows3 = sorted(r for (r, c) in wire_positions if c == wire_col3)
        road_rows3 = set(r for (r, c) in road_positions if c == road_col3)

        if not wire_rows3:
            for wc in range(wire_col - 1, wire_col3 - 1, -1):
                if em[plant_cy, wc]:
                    return (Tool.WIRE, wc, plant_cy)
        else:
            min_wr3 = min(wire_rows3)
            max_wr3 = max(wire_rows3)
            if max_wr3 < tmax:
                nr = max_wr3 + 1
                if 0 < nr < WORLD_H:
                    return (Tool.WIRE, wire_col3, nr)
            if min_wr3 > tmin:
                nr = min_wr3 - 1
                if 0 <= nr < WORLD_H:
                    return (Tool.WIRE, wire_col3, nr)

            for wr in wire_rows3:
                if wr not in road_rows3 and 0 <= road_col3 < WORLD_W:
                    return (Tool.ROAD, road_col3, wr)

            # Lateral wires for cluster 3
            for wr in wire_rows3:
                for wc in range(wire_col3 - 1, max(left_zone_col3 - 2, 0), -1):
                    if 0 <= wc < WORLD_W and not wm[wr, wc] and em[wr, wc]:
                        return (Tool.WIRE, wc, wr)

            # Lateral roads for cluster 3
            for wr in wire_rows3:
                for rc in range(road_col3 - 1, max(right_zone_col3 - 2, 0), -1):
                    if 0 <= rc < WORLD_W and not rm[wr, rc] and em[wr, rc]:
                        return (Tool.ROAD, rc, wr)

            for zr in sorted(wire_rows3):
                road_nearby3 = any(abs(zr - rr) <= 2 for rr in road_rows3)
                if not road_nearby3:
                    continue
                for zc in [left_zone_col3, right_zone_col3]:
                    if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                        if not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                            return (pick_zone_type(), zc, zr)

    # Phase 9: Add nuclear power for large cities
    if obs.city_pop >= 500:
        nuke_x, nuke_y = plant_cx - 10, plant_cy + 10
        if 2 <= nuke_y < WORLD_H - 2 and 2 <= nuke_x < WORLD_W - 2:
            area = pm[nuke_y - 1:nuke_y + 2, nuke_x - 1:nuke_x + 2]
            if not np.any(area):
                return (Tool.NUCLEARPOWER, nuke_x, nuke_y)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy.
    Each step, read the tile map and decide what to place next.
    Strategy:
    - Place coal plant at anchor.
    - Grow wire spine downward from plant.
    - Build roads parallel to wire on each side.
    - Connect zones to roads with horizontal wire branches.
    - Expand zone columns and additional power plants as city grows.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    # Anchor
    plant_cx, plant_cy = 60, 50

    has_plant = np.any(pm)

    # Phase 1: place coal power plant
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Find all plant tiles to determine plant locations
    plant_rows, plant_cols = np.where(pm)

    # Wire spine runs vertically at wire_col
    wire_col = plant_cx + 4  # col 64, just right of plant footprint

    # Road columns
    road_col_L = wire_col - 3  # col 61
    road_col_R = wire_col + 3  # col 67

    # Zone columns
    zone_col_L = wire_col - 6  # col 58
    zone_col_R = wire_col + 6  # col 70

    # Vertical span
    base_span = 15
    extra_span = min(35, obs.city_pop // 20)
    target_span = base_span + extra_span
    tmin = max(2, plant_cy - target_span)
    tmax = min(WORLD_H - 3, plant_cy + target_span)

    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    # Current zone counts
    res_pos = set(zip(*np.where(res_mask(tm)))) if np.any(res_mask(tm)) else set()
    com_pos = set(zip(*np.where(com_mask(tm)))) if np.any(com_mask(tm)) else set()
    ind_pos = set(zip(*np.where(ind_mask(tm)))) if np.any(ind_mask(tm)) else set()
    all_zones = res_pos | com_pos | ind_pos

    res_count = len(res_pos)
    com_count = len(com_pos)
    ind_count = len(ind_pos)

    def already_zone_nearby(zr, zc):
        return any(abs(zr - pr) <= 3 and abs(zc - pc) <= 3 for (pr, pc) in all_zones)

    def pick_zone_type():
        # Aim for ~1:1:2 ind:com:res ratio
        if ind_count == 0:
            return Tool.INDUSTRIAL
        if com_count == 0:
            return Tool.COMMERCIAL
        if res_count == 0:
            return Tool.RESIDENTIAL
        if ind_count * 2 < res_count:
            return Tool.INDUSTRIAL
        if com_count * 2 < res_count:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Wire spine rows
    wire_rows_in_col = sorted(r for r in range(WORLD_H) if wm[r, wire_col])

    # Phase 2: start wire spine adjacent to plant (above plant footprint)
    if not wire_rows_in_col:
        # Try to place wire next to plant
        for wr in [plant_cy - 2, plant_cy - 1, plant_cy, plant_cy + 1, plant_cy + 2]:
            if 0 <= wr < WORLD_H and 0 <= wire_col < WORLD_W and em[wr, wire_col]:
                return (Tool.WIRE, wire_col, wr)
        # Try column to connect to plant
        for wc in range(plant_cx + 2, wire_col + 1):
            if 0 <= plant_cy < WORLD_H and 0 <= wc < WORLD_W and em[plant_cy, wc]:
                return (Tool.WIRE, wc, plant_cy)
        return None

    min_wr = min(wire_rows_in_col)
    max_wr = max(wire_rows_in_col)

    # Phase 2b: extend wire spine
    if max_wr < tmax:
        nr = max_wr + 1
        if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
            return (Tool.WIRE, wire_col, nr)
    if min_wr > tmin:
        nr = min_wr - 1
        if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
            return (Tool.WIRE, wire_col, nr)

    wire_rows_set = set(wire_rows_in_col)

    # Phase 3: build left road column
    for wr in wire_rows_in_col:
        if 0 <= road_col_L < WORLD_W and 0 <= wr < WORLD_H and em[wr, road_col_L]:
            return (Tool.ROAD, road_col_L, wr)

    # Phase 4: build right road column
    for wr in wire_rows_in_col:
        if 0 <= road_col_R < WORLD_W and 0 <= wr < WORLD_H and em[wr, road_col_R]:
            return (Tool.ROAD, road_col_R, wr)

    # Road positions
    road_positions = set(zip(*np.where(rm))) if np.any(rm) else set()
    road_L_rows = set(r for (r, c) in road_positions if c == road_col_L)
    road_R_rows = set(r for (r, c) in road_positions if c == road_col_R)

    # Phase 5: horizontal wire bridges every 3 rows connecting spine to roads
    for wr in wire_rows_in_col:
        if wr % 3 == 0:
            # Left bridge
            for wc in range(wire_col - 1, road_col_L, -1):
                if em[wr, wc]:
                    return (Tool.WIRE, wc, wr)
            # Right bridge
            for wc in range(wire_col + 1, road_col_R):
                if em[wr, wc]:
                    return (Tool.WIRE, wc, wr)

    # Phase 6: place zones next to roads
    for zr in wire_rows_in_col:
        road_L_near = any(abs(zr - rr) <= 2 for rr in road_L_rows)
        road_R_near = any(abs(zr - rr) <= 2 for rr in road_R_rows)

        for (zc, road_ok) in [(zone_col_L, road_L_near), (zone_col_R, road_R_near)]:
            if not road_ok:
                continue
            if 2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3:
                if not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                    return (pick_zone_type(), zc, zr)

    # Phase 7: second power plant if needed
    if obs.city_pop > 500 and obs.powered_zones < (res_count + com_count + ind_count) // 4:
        # Place another coal plant far from first
        p2x, p2y = plant_cx - 20, plant_cy
        if 2 <= p2x <= WORLD_W - 4 and 2 <= p2y <= WORLD_H - 4:
            area_free = all(em[p2y + dr, p2x + dc]
                            for dr in [-1, 0, 1] for dc in [-1, 0, 1]
                            if 0 <= p2y + dr < WORLD_H and 0 <= p2x + dc < WORLD_W)
            if area_free:
                return (Tool.COALPOWER, p2x, p2y)

    # Phase 8: expand to second zone column pair
    if obs.city_pop > 300:
        zone_col_L2 = zone_col_L - 7  # col 51
        zone_col_R2 = zone_col_R + 7  # col 77
        road_col_L2 = zone_col_L2 + 3  # col 54
        road_col_R2 = zone_col_R2 - 3  # col 74

        # Extend wires outward
        for wr in wire_rows_in_col:
            if wr % 3 == 0:
                # Left extension
                for wc in range(road_col_L - 1, road_col_L2 - 1, -1):
                    if em[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                # Right extension
                for wc in range(road_col_R + 1, road_col_R2 + 1):
                    if em[wr, wc]:
                        return (Tool.WIRE, wc, wr)

        # Build new roads
        for wr in wire_rows_in_col:
            if 0 <= road_col_L2 < WORLD_W and em[wr, road_col_L2]:
                return (Tool.ROAD, road_col_L2, wr)
            if 0 <= road_col_R2 < WORLD_W and em[wr, road_col_R2]:
                return (Tool.ROAD, road_col_R2, wr)

        road_L2_rows = set(r for (r, c) in road_positions if c == road_col_L2)
        road_R2_rows = set(r for (r, c) in road_positions if c == road_col_R2)

        for zr in wire_rows_in_col:
            road_L2_near = any(abs(zr - rr) <= 2 for rr in road_L2_rows)
            road_R2_near = any(abs(zr - rr) <= 2 for rr in road_R2_rows)
            for (zc, road_ok) in [(zone_col_L2, road_L2_near), (zone_col_R2, road_R2_near)]:
                if not road_ok:
                    continue
                if 2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3:
                    if not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                        return (pick_zone_type(), zc, zr)

    # Phase 9: add horizontal roads to improve connectivity
    if obs.city_pop > 100:
        # Add horizontal road connecting left and right road columns at intervals
        for wr in wire_rows_in_col:
            if wr % 6 == 0:
                for wc in range(road_col_L + 1, road_col_R):
                    if em[wr, wc] and not rm[wr, wc]:
                        return (Tool.ROAD, wc, wr)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads the map each step and places the next tile
    based on what already exists. Uses a simple phase counter in state.

    Layout:
    - One coal plant at (20, 50)
    - Wire spine along row 50 from plant rightward
    - Road spine along row 47 (above) and row 53 (below)
    - Vertical connectors every 6 cols
    - Zones placed adjacent to roads, powered by nearby wires
    """
    tm = obs.tile_map
    step = obs.step

    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # Key layout parameters
    PLANT_X, PLANT_Y = 20, 50
    SPINE_ROW = 50
    ROAD_ROW_A = 47  # above spine
    ROAD_ROW_B = 53  # below spine
    SPINE_START = 23  # just right of plant footprint (plant takes ~17-23)
    SPINE_END = 110
    ZONE_COLS = list(range(26, 112, 6))
    ZONE_ROWS_A = [44, 41, 38]   # above road A
    ZONE_ROWS_B = [56, 59, 62]   # below road B

    # Count existing tiles
    n_res = int(np.sum(res_m))
    n_com = int(np.sum(com_m))
    n_ind = int(np.sum(ind_m))
    n_total = n_res + n_com + n_ind

    def is_free_3x3(cy, cx):
        """Check if 3x3 area centered at (cx,cy) is empty."""
        for dy in [-1, 0, 1]:
            for dx in [-1, 0, 1]:
                ny, nx = cy + dy, cx + dx
                if ny < 0 or ny >= WORLD_H or nx < 0 or nx >= WORLD_W:
                    return False
                if not em[ny, nx]:
                    return False
        return True

    def pick_zone():
        """Pick zone type to balance mix: 50% res, 25% com, 25% ind."""
        total = n_total + 1
        if n_com / total < 0.25:
            return Tool.COMMERCIAL
        elif n_ind / total < 0.25:
            return Tool.INDUSTRIAL
        else:
            return Tool.RESIDENTIAL

    def wire_reaches(cy, cx, radius=6):
        """Check if any wire or plant is within radius of (cx, cy)."""
        y0 = max(0, cy - radius)
        y1 = min(WORLD_H, cy + radius + 1)
        x0 = max(0, cx - radius)
        x1 = min(WORLD_W, cx + radius + 1)
        return np.any(wm[y0:y1, x0:x1]) or np.any(pm[y0:y1, x0:x1])

    def road_reaches(cy, cx, radius=4):
        """Check if any road is within radius of (cx, cy)."""
        y0 = max(0, cy - radius)
        y1 = min(WORLD_H, cy + radius + 1)
        x0 = max(0, cx - radius)
        x1 = min(WORLD_W, cx + radius + 1)
        return np.any(rm[y0:y1, x0:x1])

    # --- STEP 1: Place power plant if missing ---
    if not np.any(pm):
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    # --- STEP 2: Extend wire spine rightward ---
    # Find rightmost wire on SPINE_ROW
    wire_on_spine = np.where(wm[SPINE_ROW, :])[0]
    if len(wire_on_spine) == 0:
        # Start wire just right of plant
        return (Tool.WIRE, SPINE_START, SPINE_ROW)
    else:
        max_wx = int(np.max(wire_on_spine))
        if max_wx < SPINE_END:
            nx = max_wx + 1
            # Don't place wire on road
            if not rm[SPINE_ROW, nx]:
                return (Tool.WIRE, nx, SPINE_ROW)

    # --- STEP 3: Extend road spine A (row 47) ---
    road_on_A = np.where(rm[ROAD_ROW_A, :])[0]
    if len(road_on_A) == 0:
        max_rxa = SPINE_START - 1
    else:
        max_rxa = int(np.max(road_on_A))
    if max_rxa < SPINE_END:
        nx = max_rxa + 1
        if 0 <= nx < WORLD_W:
            return (Tool.ROAD, nx, ROAD_ROW_A)

    # --- STEP 4: Extend road spine B (row 53) ---
    road_on_B = np.where(rm[ROAD_ROW_B, :])[0]
    if len(road_on_B) == 0:
        max_rxb = SPINE_START - 1
    else:
        max_rxb = int(np.max(road_on_B))
    if max_rxb < SPINE_END:
        nx = max_rxb + 1
        if 0 <= nx < WORLD_W:
            return (Tool.ROAD, nx, ROAD_ROW_B)

    # --- STEP 5: Add vertical connector roads at zone columns ---
    for zc in ZONE_COLS:
        if zc < 0 or zc >= WORLD_W:
            continue
        # Connect road A down to spine row (rows 47..50)
        for yr in range(ROAD_ROW_A, SPINE_ROW + 1):
            if not rm[yr, zc] and not wm[yr, zc]:
                if em[yr, zc]:
                    return (Tool.ROAD, zc, yr)
                break
        # Connect road B up to spine row (rows 50..53)
        for yr in range(SPINE_ROW, ROAD_ROW_B + 1):
            if not rm[yr, zc] and not wm[yr, zc]:
                if em[yr, zc]:
                    return (Tool.ROAD, zc, yr)
                break

    # --- STEP 6: Add wire branches up/down from spine to reach zones ---
    for zc in ZONE_COLS:
        if zc < 0 or zc >= WORLD_W:
            continue
        # Wire upward from spine toward zone rows above
        for yr in range(SPINE_ROW - 1, ROAD_ROW_A - 2, -1):
            if yr < 0:
                break
            if wm[yr, zc]:
                break  # already have wire here, done going up
            if rm[yr, zc]:
                continue  # skip road tiles, wire can go under road logic
            if em[yr, zc]:
                return (Tool.WIRE, zc, yr)
            else:
                break
        # Wire downward from spine toward zone rows below
        for yr in range(SPINE_ROW + 1, ROAD_ROW_B + 3):
            if yr >= WORLD_H:
                break
            if wm[yr, zc]:
                break
            if rm[yr, zc]:
                continue
            if em[yr, zc]:
                return (Tool.WIRE, zc, yr)
            else:
                break

    # --- STEP 7: Place zones adjacent to roads, with power ---
    # Scan zone positions and place if road and wire nearby
    for zr in ZONE_ROWS_A + ZONE_ROWS_B:
        for zc in ZONE_COLS:
            if zr < 2 or zr >= WORLD_H - 2 or zc < 2 or zc >= WORLD_W - 2:
                continue
            # Check if already a zone here (any zone tile in 3x3)
            y0, y1 = zr - 1, zr + 2
            x0, x1 = zc - 1, zc + 2
            has_zone = (np.any(res_m[y0:y1, x0:x1]) or
                        np.any(com_m[y0:y1, x0:x1]) or
                        np.any(ind_m[y0:y1, x0:x1]))
            if has_zone:
                continue
            if not is_free_3x3(zr, zc):
                continue
            if not road_reaches(zr, zc, radius=4):
                continue
            if not wire_reaches(zr, zc, radius=7):
                continue
            return (pick_zone(), zc, zr)

    # --- STEP 8: If zones are placed but not powered, add more wires ---
    # Find any zone not covered by wire and try to extend wire toward it
    all_zone_m = res_m | com_m | ind_m
    zone_ys, zone_xs = np.where(all_zone_m)
    for zy, zx in zip(zone_ys, zone_xs):
        if not wire_reaches(int(zy), int(zx), radius=5):
            # Try to place a wire one step closer from spine
            # Walk from spine row toward zone
            step_y = 1 if zy > SPINE_ROW else -1
            for yr in range(SPINE_ROW + step_y, int(zy) + step_y, step_y):
                if yr < 0 or yr >= WORLD_H:
                    break
                if not wm[yr, zx] and em[yr, zx]:
                    return (Tool.WIRE, int(zx), yr)
                elif not wm[yr, zx]:
                    break

    # --- STEP 9: Extend zone area further if city growing ---
    if obs.city_pop > 50:
        extra_rows_a = [35, 32, 29]
        extra_rows_b = [65, 68, 71]
        for zr in extra_rows_a + extra_rows_b:
            for zc in ZONE_COLS:
                if zr < 2 or zr >= WORLD_H - 2 or zc < 2 or zc >= WORLD_W - 2:
                    continue
                y0, y1 = zr - 1, zr + 2
                x0, x1 = zc - 1, zc + 2
                has_zone = (np.any(res_m[y0:y1, x0:x1]) or
                            np.any(com_m[y0:y1, x0:x1]) or
                            np.any(ind_m[y0:y1, x0:x1]))
                if has_zone:
                    continue
                if not is_free_3x3(zr, zc):
                    continue
                if road_reaches(zr, zc, radius=5) and wire_reaches(zr, zc, radius=8):
                    return (pick_zone(), zc, zr)

    # --- STEP 10: Fill gaps in roads ---
    for zc in ZONE_COLS:
        for rr in [ROAD_ROW_A, ROAD_ROW_B]:
            if 0 <= zc < WORLD_W and 0 <= rr < WORLD_H:
                if not rm[rr, zc] and em[rr, zc]:
                    return (Tool.ROAD, zc, rr)

    return None

def act(obs, state):
    """
    Improved grid-based city builder.
    Strategy:
    - Place coal power plant at left side
    - Build a horizontal wire spine from plant
    - Build vertical road grid perpendicular to wire
    - Place zones in a grid pattern with balanced R/C/I mix
    - Expand horizontally as population grows
    - Add second power plant when needed
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Build a horizontal corridor layout
    # Plant on left side, wire runs horizontally, roads run vertically

    # Center row
    cy = WORLD_H // 2  # 50

    # Phase 1: Place coal power plant if missing
    if not np.any(pm):
        return (Tool.COALPOWER, 10, cy)

    # Find plant centroid
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Wire runs horizontally from plant to the right
    wire_row = plant_cy  # horizontal wire spine row

    # How far to extend wire based on population
    if obs.city_pop < 50:
        wire_extent = plant_cx + 12
    elif obs.city_pop < 200:
        wire_extent = plant_cx + 24
    elif obs.city_pop < 500:
        wire_extent = plant_cx + 40
    else:
        wire_extent = plant_cx + 55
    wire_extent = min(wire_extent, WORLD_W - 3)

    # Current wire extent
    wire_cols_on_row = sorted([c for c in range(WORLD_W) if wm[wire_row, c]])

    # Phase 2: Start wire from right edge of plant
    if not wire_cols_on_row:
        start_c = plant_cx + 2
        if 0 <= start_c < WORLD_W and (em[wire_row, start_c] or wm[wire_row, start_c]):
            return (Tool.WIRE, start_c, wire_row)
        return None

    max_wire_col = max(wire_cols_on_row)
    min_wire_col = min(wire_cols_on_row)

    # Phase 3: Extend wire horizontally to the right
    if max_wire_col < wire_extent:
        nc = max_wire_col + 1
        if nc < WORLD_W and not pm[wire_row, nc]:
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # Zone columns and road layout:
    # Zones placed in columns, roads run vertically between them
    # Layout: wire_row is horizontal spine
    # Zones above and below the wire row at offsets
    # Road columns placed every 4 tiles starting from plant_cx + 4

    zone_above_row = wire_row - 3   # zone center row above wire
    zone_below_row = wire_row + 3   # zone center row below wire
    zone_above2_row = wire_row - 7  # second row above
    zone_below2_row = wire_row + 7  # second row below

    # Road columns: every 4 tiles from start
    road_start_col = plant_cx + 4

    def get_road_cols():
        cols = []
        c = road_start_col
        while c <= wire_extent + 2:
            cols.append(c)
            c += 4
        return cols

    road_cols = get_road_cols()

    # Phase 4: Build vertical road segments at each road column
    # Roads run from wire_row-8 to wire_row+8 to cover zone rows
    road_top = wire_row - 8
    road_bot = wire_row + 8

    for rc in road_cols:
        if rc > max_wire_col + 1:
            break  # only build roads where wire exists
        if 0 <= rc < WORLD_W:
            for rr in range(max(0, road_top), min(WORLD_H, road_bot + 1)):
                if not rm[rr, rc] and em[rr, rc] and not pm[rr, rc]:
                    return (Tool.ROAD, rc, rr)

    # Phase 5: Connect wire to road columns via lateral wires
    # Wire row already horizontal; add vertical wires up/down from wire row at road cols
    for rc in road_cols:
        if rc > max_wire_col + 1:
            break
        # Extend wire vertically from wire_row to cover zone rows
        for wr in range(wire_row - 1, max(0, wire_row - 10), -1):
            if wm[wr, rc]:
                break
            if em[wr, rc] and not pm[wr, rc] and not rm[wr, rc]:
                return (Tool.WIRE, rc, wr)
            elif rm[wr, rc]:
                # Road there already, wire under/over won't work - skip
                break
        for wr in range(wire_row + 1, min(WORLD_H, wire_row + 10)):
            if wm[wr, rc]:
                break
            if em[wr, rc] and not pm[wr, rc] and not rm[wr, rc]:
                return (Tool.WIRE, rc, wr)
            elif rm[wr, rc]:
                break

    # Helper functions
    all_zone_mask = resm | comm | indm

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=5):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    def pick_tool(zc):
        # Vary zone type based on column position for diversity
        t = total_zones
        if t == 0:
            return Tool.RESIDENTIAL
        # Aim for ~50% R, 30% C, 20% I
        if com_count / t < 0.30:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Phase 6: Place zones between road columns
    # Zone centers sit between road columns (at col = rc + 2 for each road col)
    zone_col_offsets = [2]  # zone center between road cols (offset from road col)

    zone_rows_to_try = [zone_above_row, zone_below_row]
    if obs.city_pop > 150:
        zone_rows_to_try += [zone_above2_row, zone_below2_row]

    for zr in zone_rows_to_try:
        if zr < 1 or zr > WORLD_H - 2:
            continue
        for i, rc in enumerate(road_cols[:-1]):  # between consecutive road cols
            zc = rc + 2  # zone center between this road col and next
            if rc > max_wire_col:
                continue
            if zc < 1 or zc > WORLD_W - 2:
                continue
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_road_nearby(zr, zc, 4) and has_wire_nearby(zr, zc, 5):
                    return (pick_tool(zc), zc, zr)

    # Phase 7: Second coal power plant when first is insufficient
    if obs.city_pop > 300 and int(np.sum(pm)) < 9:
        px2 = plant_cx + 20
        py2 = plant_cy
        if 2 <= px2 <= WORLD_W - 3 and 2 <= py2 <= WORLD_H - 3:
            # Check area roughly empty
            area_ok = True
            for dr in range(-2, 3):
                for dc in range(-2, 3):
                    if 0 <= py2+dr < WORLD_H and 0 <= px2+dc < WORLD_W:
                        if not em[py2+dr, px2+dc]:
                            area_ok = False
            if area_ok:
                return (Tool.COALPOWER, px2, py2)

    # Phase 8: Add horizontal roads to improve connectivity
    if obs.city_pop > 100:
        # Horizontal road just above and below zone rows
        for h_row in [zone_above_row - 1, zone_below_row + 1]:
            if 0 <= h_row < WORLD_H:
                for rc in road_cols:
                    if rc > max_wire_col:
                        break
                    for c_span in range(rc - 3, rc + 4):
                        if 0 <= c_span < WORLD_W and em[h_row, c_span] and not pm[h_row, c_span]:
                            return (Tool.ROAD, c_span, h_row)

    # Phase 9: Extend zones to third row if population high
    if obs.city_pop > 400:
        zone_rows_ext = [wire_row - 11, wire_row + 11]
        for zr in zone_rows_ext:
            if zr < 1 or zr > WORLD_H - 2:
                continue
            for i, rc in enumerate(road_cols[:-1]):
                zc = rc + 2
                if rc > max_wire_col:
                    continue
                if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                    if has_road_nearby(zr, zc, 5) and has_wire_nearby(zr, zc, 6):
                        return (pick_tool(zc), zc, zr)

    return None

def act(obs, state):
    """
    Improved policy: builds a horizontal road spine with zones on both sides,
    powered by a coal plant connected via wires. Uses a different layout than
    parent (horizontal instead of vertical spine, bigger cluster, better zone mix).
    """
    tm = obs.tile_map
