    plant_cx, plant_cy = cx - 15, cy - 8
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Phase 2: Build horizontal wire spine at row cy-8
    # Wire row connects plant to zones area
    wire_row = plant_cy  # same row as plant center
    wire_cols_in_row = [c for (r, c) in wire_positions if r == wire_row]

    # Need wire from plant right edge (plant_cx+2) to cx+20
    wire_start = plant_cx + 2  # just right of plant footprint? plant cx+-1 => cx-16..cx-14
    # Actually plant footprint: center plant_cx, so tiles plant_cx-1..plant_cx+1 for a 3x3
    # Wait, COALPOWER is bigger. Let's just start wire at plant_cx + 3
    wire_start = plant_cx + 3
    wire_end = cx + 20

    if not wire_cols_in_row:
        # Place first wire adjacent to plant
        return (Tool.WIRE, wire_start, wire_row)
    else:
        max_wc = max(wire_cols_in_row)
        min_wc = min(wire_cols_in_row)
        if max_wc < wire_end:
            nc = max_wc + 1
            if 0 <= nc < WORLD_W:
                return (Tool.WIRE, nc, wire_row)

    # Phase 3: Build road rows above and below the wire spine
    road_row_above = wire_row - 2  # road 2 rows above wire
    road_row_below = wire_row + 2  # road 2 rows below wire

    # Extent: from cx-10 to cx+18
    road_start = cx - 10
    road_end = cx + 18

    # Build road above
    road_above_cols = [c for (r, c) in road_positions if r == road_row_above]
    if len(road_above_cols) < (road_end - road_start):
        for c in range(road_start, road_end + 1):
            if not rm[road_row_above, c] and 0 <= road_row_above < WORLD_H:
                return (Tool.ROAD, c, road_row_above)

    # Build road below
    road_below_cols = [c for (r, c) in road_positions if r == road_row_below]
    if len(road_below_cols) < (road_end - road_start):
        for c in range(road_start, road_end + 1):
            if not rm[road_row_below, c] and 0 <= road_row_below < WORLD_H:
                return (Tool.ROAD, c, road_row_below)

    # Phase 4: Add vertical wire connectors from spine to zone rows
    # Connect wire_row to road rows via vertical wires
    wire_cols_in_row = [c for (r, c) in wire_positions if r == wire_row]
    wire_col_set = set(wire_cols_in_row)

    # Add vertical wires at intervals to connect to road rows above and below
    for c in range(road_start, road_end + 1, 3):
        if c in wire_col_set:
            # Connect up to road_row_above
            for r in range(min(wire_row, road_row_above), max(wire_row, road_row_above) + 1):
                if not wm[r, c] and em[r, c]:
                    return (Tool.WIRE, c, r)
            # Connect down to road_row_below
            for r in range(min(wire_row, road_row_below), max(wire_row, road_row_below) + 1):
                if not wm[r, c] and em[r, c]:
                    return (Tool.WIRE, c, r)

    # Phase 5: Place zones above the upper road and below the lower road
    # Zone centers: row above road = road_row_above - 2, below road = road_row_below + 2
    zone_row_top = road_row_above - 2
    zone_row_bottom = road_row_below + 2
    # Also second rows further out
    zone_row_top2 = road_row_above - 5
    zone_row_bottom2 = road_row_below + 5

    zone_rows = [zone_row_top, zone_row_bottom, zone_row_top2, zone_row_bottom2]

    # Zone centers spaced by 3 horizontally from road_start+1 to road_end-1
    zone_cols = list(range(road_start + 1, road_end, 3))

    wire_col_set_full = set(c for (r, c) in wire_positions)

    for zr in zone_rows:
        for zc in zone_cols:
            if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                # Check road access: road within 2 rows
                road_access = rm[road_row_above, zc] if abs(zr - road_row_above) <= 3 else False
                road_access = road_access or (rm[road_row_below, zc] if abs(zr - road_row_below) <= 3 else False)
                # Check power: wire within reach
                power_ok = zc in wire_col_set_full or any(
                    abs(zc - wc) <= 2 for wc in wire_col_set_full
                )
                if road_access and power_ok:
                    already = any(abs(zr - pr) <= 1 and abs(zc - pc) <= 1
                                  for (pr, pc) in res_positions)
                    if not already and zone_area_free(zr, zc):
                        # Zone mix: 50% residential, 25% commercial, 25% industrial
                        # Use column position to decide
                        col_idx = zone_cols.index(zc) if zc in zone_cols else 0
                        if com_count * 2 < res_count and col_idx % 4 == 1:
                            return (Tool.COMMERCIAL, zc, zr)
                        elif ind_count * 2 < res_count and col_idx % 4 == 3:
                            return (Tool.INDUSTRIAL, zc, zr)
                        else:
                            return (Tool.RESIDENTIAL, zc, zr)

    # Phase 6: Add a second power plant if population is large enough
    if obs.city_pop > 500 and not np.any(plant_mask(tm)[cy + 5:, :]):
        # Second coal plant further right
        return (Tool.COALPOWER, cx + 25, cy - 8)

    # Phase 7: Extend road and wire further if doing well
    if obs.city_pop > 300:
        # Extend road rows further
        for c in range(road_end + 1, road_end + 10):
            if 0 <= c < WORLD_W:
                if not rm[road_row_above, c]:
                    return (Tool.ROAD, c, road_row_above)
                if not rm[road_row_below, c]:
                    return (Tool.ROAD, c, road_row_below)
        # Add more wire
        for c in range(road_end + 1, road_end + 10):
            if 0 <= c < WORLD_W and not wm[wire_row, c]:
                return (Tool.WIRE, c, wire_row)

    # Phase 8: Fill more zones around existing infrastructure
    if obs.city_pop > 100:
        for zr in range(zone_row_top2 - 3, zone_row_bottom2 + 4, 3):
            for zc in zone_cols:
                if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                    already = any(abs(zr - pr) <= 1 and abs(zc - pc) <= 1
                                  for (pr, pc) in res_positions)
                    if not already and zone_area_free(zr, zc):
                        return (Tool.RESIDENTIAL, zc, zr)

    return None

def act(obs, state):
    """
    Improved policy: Build a horizontal road/wire spine with zones on both sides,
    two power plants, and a better balanced zone mix (res/com/ind).
    Key differences from parent:
    - Horizontal spine instead of vertical
    - Two coal power plants for more coverage
    - More aggressive commercial/industrial placement
    - Wider zone spread
    """
    tm = obs.tile_map
    step = obs.step

    # Center of map
    cx, cy = WORLD_W // 2, WORLD_H // 2

    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    has_plant = np.any(pm)
    has_wire = np.any(wm)
    has_road = np.any(rm)

    res_count = np.sum(res_mask(tm))
    com_count = np.sum(com_mask(tm))
    ind_count = np.sum(ind_mask(tm))

    wire_positions = list(zip(*np.where(wm))) if has_wire else []
    road_positions = list(zip(*np.where(rm))) if has_road else []
    plant_positions = list(zip(*np.where(pm))) if has_plant else []

    # === Phase 1: Place two coal power plants ===
    # Plant 1: left side, Plant 2: right side
    plant1_cx, plant1_cy = cx - 20, cy
    plant2_cx, plant2_cy = cx + 20, cy

    plant_count = len([p for p in plant_positions])

    if plant_count == 0:
        return (Tool.COALPOWER, plant1_cx, plant1_cy)

    # Check if second plant exists (look for plant tiles near plant2 location)
    near_plant2 = any(abs(r - plant2_cy) <= 2 and abs(c - plant2_cx) <= 2 
                      for (r, c) in plant_positions)
    if not near_plant2 and obs.step > 20:
        return (Tool.COALPOWER, plant2_cx, plant2_cy)

    # === Phase 2: Build horizontal wire spine at cy ===
    # Wire row at cy, from left plant to right plant
    wire_row = cy
    wire_row_cols = sorted([c for (r, c) in wire_positions if r == wire_row])

    # Start wire from plant1 right edge (plant1_cx + 2) going right
    wire_start = plant1_cx + 2
    wire_end = plant2_cx - 2

    if not wire_row_cols:
        # Place first wire just right of plant1
        if em[wire_row, wire_start]:
            return (Tool.WIRE, wire_start, wire_row)
        else:
            return (Tool.WIRE, wire_start + 1, wire_row)
    else:
        max_col = max(wire_row_cols)
        min_col = min(wire_row_cols)
        # Extend wire rightward
        if max_col < wire_end:
            nc = max_col + 1
            if 0 <= nc < WORLD_W:
                return (Tool.WIRE, nc, wire_row)
        # Extend wire leftward to plant1
        if min_col > wire_start:
            nc = min_col - 1
            if 0 <= nc >= 0:
                return (Tool.WIRE, nc, wire_row)

    # === Phase 3: Build road spine just below wire (cy+1) ===
    road_row = cy + 2  # road row 2 below wire
    road_row_cols = sorted([c for (r, c) in road_positions if r == road_row])

    road_start = plant1_cx - 1
    road_end = plant2_cx + 1

    if wire_row_cols:
        if not road_row_cols:
            if 0 <= road_row < WORLD_H and 0 <= road_start < WORLD_W:
                return (Tool.ROAD, road_start, road_row)
        else:
            max_rc = max(road_row_cols)
            min_rc = min(road_row_cols)
            if max_rc < road_end:
                nc = max_rc + 1
                if 0 <= nc < WORLD_W:
                    return (Tool.ROAD, nc, road_row)
            if min_rc > road_start:
                nc = min_rc - 1
                if 0 <= nc >= 0:
                    return (Tool.ROAD, nc, road_row)

    # Also build road above wire (cy-2)
    road_row_up = cy - 2
    road_up_cols = sorted([c for (r, c) in road_positions if r == road_row_up])
    if wire_row_cols and len(wire_row_cols) > 5:
        if not road_up_cols:
            return (Tool.ROAD, road_start, road_row_up)
        else:
            max_rc = max(road_up_cols)
            if max_rc < road_end:
                return (Tool.ROAD, max_rc + 1, road_row_up)

    # === Phase 4: Place zones above and below road rows ===
    # Zones above road_row_up: centers at cy-2-3=cy-5 (above)
    # Zones below road_row: centers at cy+2+3=cy+5 (below)
    # Zones between wire and road_row: cy+... hmm, let's do:
    # Row above upper road: center_row = road_row_up - 2 = cy-4
    # Row below lower road: center_row = road_row + 2 = cy+4
    # Also zones just above wire: center_row = cy - 3

    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    res_positions = list(zip(*np.where(res_mask(tm))))

    # Define zone placement columns (spaced every 3 along road)
    # Zones placed with centers at road_row +/- 3 (adjacent to road)
    zone_cols = list(range(plant1_cx - 1, plant2_cx + 2, 3))

    # Zone rows: above upper road, below lower road, between
    zone_row_configs = [
        (road_row_up - 3, 'above'),   # above upper road
        (road_row + 3, 'below'),       # below lower road
        (cy - 6, 'far_above'),         # far above
        (cy + 6, 'far_below'),         # far below
    ]

    # Determine zone type based on position
    def pick_zone_type(col_idx, row_type):
        # Balance: 50% res, 25% com, 25% ind
        total = res_count + com_count + ind_count + 1
        res_frac = res_count / total
        com_frac = com_count / total
        ind_frac = ind_count / total

        if com_frac < 0.25:
            return Tool.COMMERCIAL
        if ind_frac < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Check road coverage at a column
    def has_road_nearby(zc, zr):
        for (rr, rc) in road_positions:
            if abs(rc - zc) <= 2 and abs(rr - zr) <= 3:
                return True
        return False

    def has_wire_nearby(zc, zr):
        for (wr, wc) in wire_positions:
            if abs(wc - zc) <= 3 and abs(wr - zr) <= 3:
                return True
        return False

    # Try placing zones
    for (zr, label) in zone_row_configs:
        if not (3 <= zr <= WORLD_H - 4):
            continue
        for col_idx, zc in enumerate(zone_cols):
            if not (3 <= zc <= WORLD_W - 4):
                continue
            if not has_road_nearby(zc, zr):
                continue
            if not has_wire_nearby(zc, zr):
                continue
            already = any(abs(zr - pr) <= 2 and abs(zc - pc) <= 2
                          for (pr, pc) in res_positions)
            # Also check com/ind
            cm_pos = list(zip(*np.where(com_mask(tm)))) if com_count > 0 else []
            im_pos = list(zip(*np.where(ind_mask(tm)))) if ind_count > 0 else []
            already_com = any(abs(zr - pr) <= 2 and abs(zc - pc) <= 2 for (pr, pc) in cm_pos)
            already_ind = any(abs(zr - pr) <= 2 and abs(zc - pc) <= 2 for (pr, pc) in im_pos)
            if not already and not already_com and not already_ind:
                if zone_area_free(zr, zc):
                    tool = pick_zone_type(col_idx, label)
                    return (tool, zc, zr)

    # === Phase 5: Vertical wire connectors to reach far zones ===
    # Add vertical wires from spine to connect to zone rows
    for target_row in [road_row_up - 3, road_row + 3, cy - 6, cy + 6]:
        if not (0 <= target_row < WORLD_H):
            continue
        # Use a wire column in the middle
        for wc in wire_row_cols[::5] if wire_row_cols else []:
            if 0 <= wc < WORLD_W:
                # Extend vertically
                if target_row < cy:
                    for r in range(cy - 1, target_row - 1, -1):
                        if em[r, wc]:
                            return (Tool.WIRE, wc, r)
                else:
                    for r in range(cy + 1, target_row + 1):
                        if em[r, wc]:
                            return (Tool.WIRE, wc, r)

    # === Phase 6: Add more zones if population is growing ===
    if obs.city_pop > 100:
        extra_rows = [road_row_up - 6, road_row + 6]
        for zr in extra_rows:
            if not (3 <= zr <= WORLD_H - 4):
                continue
            for zc in zone_cols:
                if not (3 <= zc <= WORLD_W - 4):
                    continue
                already = any(abs(zr - pr) <= 2 and abs(zc - pc) <= 2
                              for (pr, pc) in res_positions)
                if not already and zone_area_free(zr, zc):
                    if has_road_nearby(zc, zr) and has_wire_nearby(zc, zr):
                        return (Tool.RESIDENTIAL, zc, zr)

    # Add police/fire stations for zone happiness
    if obs.city_pop > 300 and step % 50 == 30:
        for zr in [cy - 8, cy + 8]:
            for zc in [cx - 10, cx + 10]:
                if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                    if em[zr, zc]:
                        return (Tool.POLICESTATION, zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop city builder:
    - Reads tile_map each step to decide next action
    - Places power plants, then grows wire/road/zones reactively
    - Two clusters, balanced RCI, services when population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def is_empty(x, y):
        return in_bounds(x, y) and bool(em[y, x])

    def is_wire_or_plant(x, y):
        return in_bounds(x, y) and (bool(wm[y, x]) or bool(pm[y, x]))

    def is_road(x, y):
        return in_bounds(x, y) and bool(rm[y, x])

    # Power plant anchor points
    P1X, P1Y = 25, 45
    P2X, P2Y = 75, 50

    # Detect existing plants
    plant_ys, plant_xs = np.where(pm)
    has_plant1 = any(abs(px_ - P1X) < 8 and abs(py_ - P1Y) < 8
                     for py_, px_ in zip(plant_ys.tolist(), plant_xs.tolist()))
    has_plant2 = any(abs(px_ - P2X) < 8 and abs(py_ - P2Y) < 8
                     for py_, px_ in zip(plant_ys.tolist(), plant_xs.tolist()))

    # Step 1: Place power plants
    if not has_plant1:
        return (Tool.COALPOWER, P1X, P1Y)
    if not has_plant2:
        return (Tool.COALPOWER, P2X, P2Y)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        c = com_count / t
        i_frac = ind_count / t
        if c < 0.22:
            return Tool.COMMERCIAL
        if i_frac < 0.22:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        """Check 3x3 area is empty (or already zone tiles)"""
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not bool(em[nr, nc]):
                    return False
        return True

    # --- Grow wires reactively from existing wire/plant frontier ---
    # For each cluster, extend wire spine horizontally, then branches vertically

    clusters = [
        {'px': P1X, 'py': P1Y, 'x_start': P1X + 2, 'x_end': min(P1X + 42, 67)},
        {'px': P2X, 'py': P2Y, 'x_start': max(P2X - 42, 68), 'x_end': min(P2X + 18, WORLD_W - 4)},
    ]

    for cl in clusters:
        px, py = cl['px'], cl['py']
        x_start, x_end = cl['x_start'], cl['x_end']
        spine_y = py

        # Extend horizontal wire spine: find leftmost gap in spine
        for wx in range(x_start, x_end + 1):
            if not in_bounds(wx, spine_y):
                break
            if not is_wire_or_plant(wx, spine_y):
                # Only extend if previous tile is wire/plant (connectivity)
                if is_wire_or_plant(wx - 1, spine_y) or (wx == x_start and is_wire_or_plant(px + 1, spine_y)):
                    if is_empty(wx, spine_y):
                        return (Tool.WIRE, wx, spine_y)
                break

        # Extend vertical wire branches every 6 cols
        for bx in range(x_start, x_end + 1, 6):
            if not in_bounds(bx, spine_y):
                continue
            if not is_wire_or_plant(bx, spine_y):
                continue
            for sign in [-1, 1]:
                for dy in range(1, 9):
                    wy2 = spine_y + sign * dy
                    if not in_bounds(bx, wy2):
                        break
                    if is_wire_or_plant(bx, wy2):
                        continue
                    # Only extend if previous is wire/plant
                    prev = spine_y + sign * (dy - 1)
                    if is_wire_or_plant(bx, prev):
                        if is_empty(bx, wy2):
                            return (Tool.WIRE, bx, wy2)
                    break

        # Build road rows at spine_y ± 3 and ± 6
        for road_offset in [-3, 3, -6, 6]:
            ry = spine_y + road_offset
            if not in_bounds(x_start, ry):
                continue
            xs_r = range(x_start, x_end + 1)
            for rx in xs_r:
                if not in_bounds(rx, ry):
                    break
                if bool(pm[ry, rx]):
                    continue
                if not bool(rm[ry, rx]):
                    # Only extend if previous tile is road or it's the start
                    if rx == x_start or bool(rm[ry, rx - 1]) or bool(rm[ry, rx + 1]):
                        if is_empty(rx, ry):
                            return (Tool.ROAD, rx, ry)
                    break

        # Vertical connector roads every 6 cols between outer roads
        for vc in range(x_start, x_end + 1, 6):
            for vr in range(spine_y - 6, spine_y + 7):
                if not in_bounds(vc, vr):
                    continue
                if bool(pm[vr, vc]):
                    continue
                if not bool(rm[vr, vc]) and not bool(wm[vr, vc]):
                    # Check neighbor connectivity
                    neighbors_road = (
                        (in_bounds(vc, vr-1) and bool(rm[vr-1, vc])) or
                        (in_bounds(vc, vr+1) and bool(rm[vr+1, vc])) or
                        (in_bounds(vc-1, vr) and bool(rm[vr, vc-1])) or
                        (in_bounds(vc+1, vr) and bool(rm[vr, vc+1]))
                    )
                    if neighbors_road and is_empty(vc, vr):
                        return (Tool.ROAD, vc, vr)

    # --- Zone placement: reactively find candidates near roads and wires ---
    # Build neighbor proximity masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    # Keep border margin for 3x3 zones
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Use city_pop and step to vary which candidate we pick (reactive)
        step_hash = int(obs.step * 17 + int(obs.city_pop * 3) + obs.powered_zones * 7) % max(len(cxs), 1)
        for offset in range(min(len(cxs), 80)):
            k = (step_hash + offset * 11) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # --- Services based on observed population ---
    if obs.city_pop > 150:
        for fx, fy in [(P1X + 4, P1Y - 10), (P2X - 4, P2Y + 10)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 250:
        for fx, fy in [(P1X + 4, P1Y + 10), (P2X - 4, P2Y - 10)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.POLICESTATION, fx, fy)

    # --- Fallback: grow roads from existing road frontier ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = int(obs.step * 13 + obs.city_pop) % max(len(road_xs2), 1)
        rx_s, ry_s = int(road_xs2[step_k]), int(road_ys2[step_k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx_s + dx2, ry_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # --- Fallback: grow wires from existing wire frontier ---
    wire_ys2, wire_xs2 = np.where(wm)
    if len(wire_xs2) > 0:
        step_k2 = int(obs.step * 7 + obs.powered_zones) % max(len(wire_xs2), 1)
        wx_s, wy_s = int(wire_xs2[step_k2]), int(wire_ys2[step_k2])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = wx_s + dx2, wy_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Combined policy:
    - Dynamic spine extent based on population (Parent A)
    - Multi-cluster expansion (Parent A)
    - Closed-loop reactive tile reading (both)
    - Better zone type balance (both)
    - Wire+road lateral extensions (both)
    - Second power plant when large (Parent A)
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        if ind_count / t < 0.22:
            return Tool.INDUSTRIAL
        if com_count / t < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    all_zone_mask = resm | comm | indm

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=5):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=5):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    # Phase 1: Place coal power plant
    plant_cx, plant_cy = cx - 8, cy
    if not np.any(pm):
        return (Tool.COALPOWER, plant_cx, plant_cy)

    plant_rows, plant_cols = np.where(pm)
    plant_cy_actual = int(np.mean(plant_rows))
    plant_cx_actual = int(np.mean(plant_cols))

    # Main cluster geometry
    wire_col = plant_cx_actual + 4
    road_col = wire_col + 1
    left_zone_col = wire_col - 3
    right_zone_col = road_col + 3

    wire_col = max(2, min(WORLD_W - 3, wire_col))
    road_col = max(2, min(WORLD_W - 3, road_col))
    left_zone_col = max(2, min(WORLD_W - 3, left_zone_col))
    right_zone_col = max(2, min(WORLD_W - 3, right_zone_col))

    # Dynamic spine extent based on population
    if obs.city_pop < 100:
        spine_extent = 10
    elif obs.city_pop < 300:
        spine_extent = 16
    elif obs.city_pop < 600:
        spine_extent = 22
    else:
        spine_extent = 30

    target_min = max(1, cy - spine_extent)
    target_max = min(WORLD_H - 2, cy + spine_extent)

    wire_rows_on_spine = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])
    road_rows_on_col = sorted([r for r in range(WORLD_H) if rm[r, road_col]])
    road_rows_set = set(road_rows_on_col)

    # Phase 2: Start wire adjacent to plant
    if not wire_rows_on_spine:
        for dy in range(0, 6):
            for nr in [plant_cy_actual + dy, plant_cy_actual - dy]:
                if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                    return (Tool.WIRE, wire_col, nr)
        return None

    min_wire_row = min(wire_rows_on_spine)
    max_wire_row = max(wire_rows_on_spine)

    # Phase 3: Extend wire spine downward
    if max_wire_row < target_max:
        nr = max_wire_row + 1
        if nr < WORLD_H and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Phase 4: Extend wire spine upward
    if min_wire_row > target_min:
        nr = min_wire_row - 1
        if nr >= 0 and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Phase 5: Build road column adjacent to wire spine
    for r in wire_rows_on_spine:
        if 0 <= r < WORLD_H and 0 <= road_col < WORLD_W:
            if not rm[r, road_col] and em[r, road_col]:
                return (Tool.ROAD, road_col, r)

    # Phase 6: Place zones along the corridor
    zone_rows = list(range(max(1, target_min), min(WORLD_H - 1, target_max + 1), 3))

    for zr in zone_rows:
        wire_near = any(abs(zr - wr) <= 2 for wr in wire_rows_on_spine)
        road_near = any(abs(zr - rr) <= 2 for rr in road_rows_on_col)

        if wire_near and road_near:
            # Try left zone
            zc = left_zone_col
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc, 5) and has_road_nearby(zr, zc, 5):
                    return (pick_tool(), zc, zr)
                elif has_wire_nearby(zr, zc, 5):
                    return (Tool.RESIDENTIAL, zc, zr)

            # Try right zone
            zc = right_zone_col
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_road_nearby(zr, zc, 5) and has_wire_nearby(zr, zc, 6):
                    return (pick_tool(), zc, zr)

    # Phase 7: Lateral wires from spine to left zones
    for wr in wire_rows_on_spine:
        for wc in range(wire_col - 1, max(left_zone_col - 2, 0), -1):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc]:
                    break

    # Phase 8: Road extensions to reach right zones
    for rr in wire_rows_on_spine:
        if not rm[rr, road_col]:
            continue
        for rc in range(road_col + 1, right_zone_col + 2):
            if 0 <= rc < WORLD_W:
                if rm[rr, rc]:
                    break
                if em[rr, rc] and not pm[rr, rc]:
                    return (Tool.ROAD, rc, rr)
                elif not em[rr, rc]:
                    break

    # Phase 9: Wire extensions to right zone for power
    for wr in wire_rows_on_spine:
        for wc in range(wire_col + 1, right_zone_col + 2):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc] and not rm[wr, wc]:
                    break

    # Phase 10: Second power plant when pop grows
    if obs.city_pop > 300 and int(np.sum(pm)) < 9:
        px2, py2 = plant_cx_actual + 22, plant_cy_actual
        px2 = max(2, min(WORLD_W - 3, px2))
        py2 = max(2, min(WORLD_H - 3, py2))
        area_clear = True
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = py2 + dr, px2 + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if not (em[rr, rc] or pm[rr, rc]):
                        area_clear = False
        if area_clear:
            return (Tool.COALPOWER, px2, py2)

    # Phase 11: Second cluster to the right when pop >= 150
    if obs.city_pop >= 150:
        wire_col2 = road_col + 8
        road_col2 = wire_col2 + 1
        left_zone_col2 = wire_col2 - 3
        right_zone_col2 = road_col2 + 3

        wire_col2 = max(2, min(WORLD_W - 3, wire_col2))
        road_col2 = max(2, min(WORLD_W - 3, road_col2))
        left_zone_col2 = max(2, min(WORLD_W - 3, left_zone_col2))
        right_zone_col2 = max(2, min(WORLD_W - 3, right_zone_col2))

        wire_rows2 = sorted([r for r in range(WORLD_H) if wm[r, wire_col2]])
        road_rows2 = set(r for r in range(WORLD_H) if rm[r, road_col2])

        if not wire_rows2:
            # Build horizontal wire bridge from main spine to cluster2
            for wc in range(wire_col + 1, wire_col2 + 1):
                if 0 <= wc < WORLD_W:
                    if not wm[plant_cy_actual, wc] and em[plant_cy_actual, wc]:
                        return (Tool.WIRE, wc, plant_cy_actual)
                    elif not em[plant_cy_actual, wc] and not wm[plant_cy_actual, wc]:
                        break
        else:
            min_wr2 = min(wire_rows2)
            max_wr2 = max(wire_rows2)

            if max_wr2 < target_max:
                nr = max_wr2 + 1
                if nr < WORLD_H and em[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > target_min:
                nr = min_wr2 - 1
                if nr >= 0 and em[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)

            for wr in wire_rows2:
                if wr not in road_rows2 and 0 <= road_col2 < WORLD_W and em[wr, road_col2]:
                    return (Tool.ROAD, road_col2, wr)

            for zr in zone_rows:
                wire_near2 = any(abs(zr - wr) <= 2 for wr in wire_rows2)
                road_near2 = any(abs(zr - rr) <= 2 for rr in road_rows2)
                if wire_near2 and road_near2:
                    for zc in [left_zone_col2, right_zone_col2]:
                        if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                            if has_wire_nearby(zr, zc, 6) and has_road_nearby(zr, zc, 5):
                                return (pick_tool(), zc, zr)

            for wr in wire_rows2:
                for wc in range(wire_col2 - 1, max(left_zone_col2 - 2, 0), -1):
                    if 0 <= wc < WORLD_W:
                        if wm[wr, wc]: break
                        if em[wr, wc] and not pm[wr, wc]:
                            return (Tool.WIRE, wc, wr)
                        elif not em[wr, wc]: break

            for wr in wire_rows2:
                if not rm[wr, road_col2]: continue
                for rc in range(road_col2 + 1, right_zone_col2 + 2):
                    if 0 <= rc < WORLD_W:
                        if rm[wr, rc]: break
                        if em[wr, rc] and not pm[wr, rc]:
                            return (Tool.ROAD, rc, wr)
                        elif not em[wr, rc]: break

    # Phase 12: Third cluster to the left when pop >= 350
    if obs.city_pop >= 350:
        wire_col3 = wire_col - 10
        road_col3 = wire_col3 - 1
        left_zone_col3 = road_col3 - 3
        right_zone_col3 = wire_col3 + 3

        wire_col3 = max(2, min(WORLD_W - 3, wire_col3))
        road_col3 = max(2, min(WORLD_W - 3, road_col3))
        left_zone_col3 = max(2, min(WORLD_W - 3, left_zone_col3))
        right_zone_col3 = max(2, min(WORLD_W - 3, right_zone_col3))

        wire_rows3 = sorted([r for r in range(WORLD_H) if wm[r, wire_col3]])
        road_rows3 = set(r for r in range(WORLD_H) if rm[r, road_col3])

        if not wire_rows3:
            for wc in range(wire_col - 1, wire_col3 - 1, -1):
                if 0 <= wc < WORLD_W:
                    if not wm[plant_cy_actual, wc] and em[plant_cy_actual, wc]:
                        return (Tool.WIRE, wc, plant_cy_actual)
                    elif not em[plant_cy_actual, wc] and not wm[plant_cy_actual, wc]:
                        break
        else:
            min_wr3 = min(wire_rows3)
            max_wr3 = max(wire_rows3)

            if max_wr3 < target_max:
                nr = max_wr3 + 1
                if nr < WORLD_H and em[nr, wire_col3]:
                    return (Tool.WIRE, wire_col3, nr)
            if min_wr3 > target_min:
                nr = min_wr3 - 1
                if nr >= 0 and em[nr, wire_col3]:
                    return (Tool.WIRE, wire_col3, nr)

            for wr in wire_rows3:
                if wr not in road_rows3 and 0 <= road_col3 < WORLD_W and em[wr, road_col3]:
                    return (Tool.ROAD, road_col3, wr)

            for zr in zone_rows:
                wire_near3 = any(abs(zr - wr) <= 2 for wr in wire_rows3)
                road_near3 = any(abs(zr - rr) <= 2 for rr in road_rows3)
                if wire_near3 and road_near3:
                    for zc in [left_zone_col3, right_zone_col3]:
                        if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                            if has_wire_nearby(zr, zc, 6) and has_road_nearby(zr, zc, 5):
                                return (pick_tool(), zc, zr)

            for wr in wire_rows3:
                for wc in range(wire_col3 + 1, min(right_zone_col3 + 2, WORLD_W)):
                    if 0 <= wc < WORLD_W:
                        if wm[wr, wc]: break
                        if em[wr, wc] and not pm[wr, wc]:
                            return (Tool.WIRE, wc, wr)
                        elif not em[wr, wc]: break

            for wr in wire_rows3:
                if not rm[wr, road_col3]: continue
                for rc in range(road_col3 - 1, max(left_zone_col3 - 2, 0), -1):
                    if 0 <= rc < WORLD_W:
                        if rm[wr, rc]: break
                        if em[wr, rc] and not pm[wr, rc]:
                            return (Tool.ROAD, rc, wr)
                        elif not em[wr, rc]: break

    # Phase 13: Extra zone columns when pop > 250
    if obs.city_pop > 250:
        extra_cols = [left_zone_col - 5, right_zone_col + 5]
        for zc in extra_cols:
            if 2 <= zc <= WORLD_W - 3:
                for zr in zone_rows:
                    if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                        if has_road_nearby(zr, zc, 6) and has_wire_nearby(zr, zc, 7):
                            return (pick_tool(), zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop policy: each step reads the current tile_map and reactively
    places the next most useful item based on what already exists.

    Strategy:
    1. First ensure a coal power plant exists
    2. Extend wires from the power plant toward target zones
    3. Build roads adjacent to wire network
    4. Place zones (R/C/I) adjacent to roads that have nearby power
    5. Add services (fire/police) periodically
    """

    # Helper: check bounds
    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Helper: get neighbors
    def neighbors4(x, y):
        for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx, ny = x+dx, y+dy
            if in_bounds(nx, ny):
                yield nx, ny

    # Read masks
    tile = obs.tile_map
    empty = empty_mask(tile)
    roads = road_mask(tile)
    wires = wire_mask(tile)
    plants = plant_mask(tile)
    res = res_mask(tile)
    com = com_mask(tile)
    ind = ind_mask(tile)

    # Phase tracking
    phase = state.get("phase", 0)
    step = obs.step

    # --- Phase 0: Place coal power plant ---
    if phase == 0:
        # Place power plant at fixed location
        px, py = 20, 50
        state["plant_x"] = px
        state["plant_y"] = py
        state["wire_frontier"] = [(px, py)]
        state["road_frontier"] = []
        state["zone_count"] = 0
        state["phase"] = 1
        return (Tool.COALPOWER, px, py)

    # Find power plant location
    if not plants.any():
        # No plant found, place one
        state["phase"] = 0
        return (Tool.COALPOWER, 20, 50)

    plant_ys, plant_xs = np.where(plants)
    # Use first plant as anchor
    anchor_x = int(plant_xs[0])
    anchor_y = int(plant_ys[0])

    # Count existing zones
    zone_count = int(res.sum() + com.sum() + ind.sum()) // 9  # approx

    # --- Phase 1: Extend wire network from plant ---
    # Target: build a wire spine going right from plant
    # Then branch roads off the wire spine

    # Find rightmost wire position along anchor_y row
    wire_row = wires[anchor_y, :]
    if wire_row.any():
        rightmost_wire_x = int(np.where(wire_row)[0].max())
    else:
        rightmost_wire_x = anchor_x

    # Target spine: extend wire rightward to x=100 along anchor_y
    spine_y = anchor_y

    if rightmost_wire_x < 100:
        # Extend wire rightward
        next_wire_x = rightmost_wire_x + 1
        if in_bounds(next_wire_x, spine_y):
            return (Tool.WIRE, next_wire_x, spine_y)

    # --- Phase 2: Build vertical roads at intervals off spine ---
    # Every 8 columns, build a vertical road
    road_col_targets = list(range(anchor_x + 4, 105, 8))

    for rx in road_col_targets:
        if not in_bounds(rx, spine_y):
            continue
        # Check if road column exists: build road segments up and down from spine
        # Find extent of road at this column
        col_roads = roads[:, rx]

        # Build road upward from spine
        road_top = spine_y
        for ry in range(spine_y, max(spine_y - 18, 1), -1):
            if roads[ry, rx]:
                road_top = ry
            else:
                road_top = ry
                break

        # If road doesn't reach high enough, extend up
        target_top = spine_y - 15
        if road_top > target_top:
            # Place road one step above current road top (or from spine)
            current_top = spine_y
            for ry in range(spine_y, max(spine_y - 18, 1), -1):
                if not roads[ry, rx]:
                    current_top = ry
                    break
                current_top = ry
            if current_top > target_top and in_bounds(rx, current_top):
                return (Tool.ROAD, rx, current_top)

        # Build road downward from spine
        target_bot = spine_y + 15
        current_bot = spine_y
        for ry in range(spine_y, min(spine_y + 18, WORLD_H - 1)):
            if not roads[ry, rx]:
                current_bot = ry
                break
            current_bot = ry
        if current_bot < target_bot and in_bounds(rx, current_bot):
            return (Tool.ROAD, rx, current_bot)

    # Also connect road columns to horizontal road along spine_y
    for rx in road_col_targets:
        if in_bounds(rx, spine_y) and not roads[spine_y, rx]:
            return (Tool.ROAD, rx, spine_y)

    # --- Phase 3: Place zones adjacent to roads with power ---
    # Scan for empty 3x3 areas adjacent to roads
    # Prioritize R > C > I in 2:1:1 ratio

    total_res = int(res.sum() // 9)
    total_com = int(com.sum() // 9)
    total_ind = int(ind.sum() // 9)

    # Determine next zone type needed
    if total_res == 0:
        next_zone = Tool.RESIDENTIAL
    elif total_com == 0:
        next_zone = Tool.COMMERCIAL
    elif total_ind == 0:
        next_zone = Tool.INDUSTRIAL
    else:
        # 2:1:1 ratio
        if total_res <= total_com + total_ind:
            next_zone = Tool.RESIDENTIAL
        elif total_com <= total_ind:
            next_zone = Tool.COMMERCIAL
        else:
            next_zone = Tool.INDUSTRIAL

    # Find candidate zone centers: must be adjacent to road, in empty area
    # Scan columns near road columns
    best_zone = None
    for col_x in road_col_targets:
        for sign in [-1, 1]:
            # Place zone center 3 tiles from road column
            zx = col_x + sign * 3
            # Scan vertically
            for zy in range(spine_y - 15, spine_y + 16, 3):
                if not in_bounds(zx, zy):
                    continue
                # Check 3x3 area is roughly empty (allow some non-critical tiles)
                clear = True
                for dy in range(-1, 2):
                    for dx in range(-1, 2):
                        tx, ty = zx + dx, zy + dy
                        if not in_bounds(tx, ty):
                            clear = False
                            break
                        # Reject if road/wire/plant already there
                        if roads[ty, tx] or wires[ty, tx] or plants[ty, tx]:
                            clear = False
                            break
                    if not clear:
                        break

                if not clear:
                    continue

                # Check adjacency to road (within 2 tiles)
                has_road = False
                for dy in range(-2, 3):
                    for dx in range(-2, 3):
                        tx, ty = zx + dx, zy + dy
                        if in_bounds(tx, ty) and roads[ty, tx]:
                            has_road = True
                            break
                    if has_road:
                        break

                if has_road:
                    best_zone = (next_zone, zx, zy)
                    break
            if best_zone:
                break
        if best_zone:
            break

    if best_zone:
        return best_zone

    # --- Phase 4: Services ---
    # Place fire station periodically
    if step % 50 == 30:
        # Find a spot near middle of road network
        for rx in road_col_targets[1:-1]:
            fy = spine_y - 18
            if in_bounds(rx, fy) and empty[fy, rx]:
                return (Tool.FIRESTATION, rx, fy)

    if step % 50 == 40:
        for rx in road_col_targets[1:-1]:
            py2 = spine_y + 18
            if in_bounds(rx, py2) and empty[py2, rx]:
                return (Tool.POLICESTATION, rx, py2)

    # --- Fallback: add second power plant if population is growing ---
    if obs.city_pop > 500 and step > obs.n_steps // 2:
        # Second plant on right side
        p2x, p2y = 95, 50
        if not plants[p2y, p2x]:
            return (Tool.COALPOWER, p2x, p2y)
        # Wire from right plant leftward to connect
        for wx in range(p2x - 1, 90, -1):
            if not wires[p2y, wx]:
                return (Tool.WIRE, wx, p2y)

    # Extend wire vertically at road columns to power more zones
    for col_x in road_col_targets:
        for zy in range(spine_y - 15, spine_y + 16):
            if in_bounds(col_x, zy) and not wires[zy, col_x] and not roads[zy, col_x]:
                # Only add wire if adjacent to existing wire
                adj_wire = False
                for nx2, ny2 in neighbors4(col_x, zy):
                    if wires[ny2, nx2]:
                        adj_wire = True
                        break
                if adj_wire:
                    return (Tool.WIRE, col_x, zy)

    return None

def act(obs, state):
    """
    Improved city builder:
    - Build a grid of roads first, then wire everything, then zone densely
    - Use a proper grid layout with road every 4 tiles
    - Better zone distribution (R/C/I balance)
    - Multiple power plants as city grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    CX, CY = 25, 50  # anchor

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Initialize state
    if 'phase' not in state:
        state['phase'] = 'power'
        state['road_idx'] = 0
        state['wire_idx'] = 0
        state['zone_idx'] = 0

    # Count zones
    res_count = int(np.sum(resm)) // 9
    com_count = int(np.sum(comm)) // 9
    ind_count = int(np.sum(indm)) // 9
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        r = res_count / t
        c = com_count / t
        i_r = ind_count / t
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Grid parameters: road rows/cols every 4 tiles in a block
    # Block: x from CX to CX+64, y from CY-20 to CY+20
    BX0, BY0 = CX, CY - 20
    BX1, BY1 = CX + 72, CY + 20

    # Road rows at BY0, BY0+4, BY0+8, ...
    road_rows = list(range(BY0, BY1 + 1, 4))
    # Road cols at BX0, BX0+4, BX0+8, ...
    road_cols = list(range(BX0, BX1 + 1, 4))

    # Step 1: Place power plant
    if not np.any(pm):
        return (Tool.COALPOWER, CX - 2, CY)

    plant_ys, plant_xs = np.where(pm)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    # Step 2: Build road grid
    # First build all road rows
    for ry in road_rows:
        for rx in range(BX0, BX1 + 1):
            if not in_bounds(rx, ry):
                continue
            if not bool(rm[ry, rx]) and not bool(pm[ry, rx]):
                return (Tool.ROAD, rx, ry)

    # Then build all road cols
    for rcx in road_cols:
        for rcy in range(BY0, BY1 + 1):
            if not in_bounds(rcx, rcy):
                continue
            if not bool(rm[rcy, rcx]) and not bool(pm[rcy, rcx]):
                return (Tool.ROAD, rcx, rcy)

    # Step 3: Build wire spine from plant through the block
    # Wire runs horizontally from plant to block, then vertically through block
    # Connect plant to BX0 via horizontal wire at py
    for wx in range(px + 2, BX0 + 1):
        wy = py
        if not in_bounds(wx, wy):
            break
        if not bool(wm[wy, wx]) and not bool(pm[wy, wx]) and not bool(rm[wy, wx]):
            return (Tool.WIRE, wx, wy)

    # Wire columns through the block at every road_col
    for wcx in road_cols[::2]:  # every other road col
        for wcy in range(BY0, BY1 + 1):
            if not in_bounds(wcx, wcy):
                continue
            if not bool(wm[wcy, wcx]) and not bool(pm[wcy, wcx]) and not bool(rm[wcy, wcx]):
                return (Tool.WIRE, wcx, wcy)

    # Wire rows through the block at every road_row
    for wry in road_rows[::2]:
        for wrx in range(BX0, BX1 + 1):
            if not in_bounds(wrx, wry):
                continue
            if not bool(wm[wry, wrx]) and not bool(pm[wry, wrx]) and not bool(rm[wry, wrx]):
                return (Tool.WIRE, wrx, wry)

    # Step 4: Place zones in the 3x3 cells between roads
    # Zone centers are at (road_col + 2, road_row + 2) for each cell
    zone_centers = []
    for i, ry in enumerate(road_rows[:-1]):
        for j, rcx in enumerate(road_cols[:-1]):
            # Center of cell
            zx = rcx + 2
            zy = ry + 2
            if in_bounds(zx, zy) and in_bounds(zx - 1, zy - 1) and in_bounds(zx + 1, zy + 1):
                zone_centers.append((zx, zy))

    zone_set = set(zip(
        np.concatenate([np.where(resm)[0], np.where(comm)[0], np.where(indm)[0]]).tolist(),
        np.concatenate([np.where(resm)[1], np.where(comm)[1], np.where(indm)[1]]).tolist()
    ))

    for (zx, zy) in zone_centers:
        # Check if already zoned (any zone tile in 3x3)
        already_zoned = False
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                if (zy + dr, zx + dc) in zone_set:
                    already_zoned = True
                    break
            if already_zoned:
                break
        if already_zoned:
            continue
        # Check if area is clear (empty or road/wire only)
        can_place = True
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                ny2, nx2 = zy + dr, zx + dc
                if not in_bounds(nx2, ny2):
                    can_place = False
                    break
                tile_ok = (bool(em[ny2, nx2]) or bool(rm[ny2, nx2]) or
                           bool(wm[ny2, nx2]))
                if not tile_ok:
                    can_place = False
                    break
            if not can_place:
                break
        if can_place:
            return (pick_tool(), zx, zy)

    # Step 5: Add second power plant when needed
    if total_zones > 15 or obs.city_pop > 500:
        p2x = BX1 + 4
        p2y = py
        nearby = False
        for dy in range(-5, 6):
            for dx in range(-5, 6):
                ny2, nx2 = p2y + dy, p2x + dx
                if in_bounds(nx2, ny2) and bool(pm[ny2, nx2]):
                    nearby = True
        if not nearby and in_bounds(p2x, p2y) and bool(em[p2y, p2x]):
            return (Tool.COALPOWER, p2x, p2y)

    # Step 6: Services
    if obs.city_pop > 200:
        fx, fy = BX0 + 2, BY0 - 4
        if in_bounds(fx, fy) and bool(em[fy, fx]):
            return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 400:
        px2, py2 = BX0 + 8, BY0 - 4
        if in_bounds(px2, py2) and bool(em[py2, px2]):
            return (Tool.POLICESTATION, px2, py2)

    # Step 7: Extend block further right if we have power
    EX1 = BX1 + 40
    for ery in road_rows:
        for erx in range(BX1 + 1, min(EX1 + 1, WORLD_W - 2)):
            if not in_bounds(erx, ery):
                break
            if not bool(rm[ery, erx]) and not bool(pm[ery, erx]):
                return (Tool.ROAD, erx, ery)

    # Wire the extension
    for wcx in range(BX1, min(EX1 + 1, WORLD_W - 2), 4):
        for wcy in range(BY0, BY1 + 1):
            if not in_bounds(wcx, wcy):
                continue
            if not bool(wm[wcy, wcx]) and not bool(pm[wcy, wcx]) and not bool(rm[wcy, wcx]):
                return (Tool.WIRE, wcx, wcy)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map each step, builds infrastructure
    reactively from what already exists on the map.

    Strategy:
    - Place coal plant first
    - Extend wire spine vertically from plant
    - Extend roads adjacent to wire
    - Place zones adjacent to roads, powered by wire
    - Second plant + corridor when pop grows
    - Services when warranted
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def zone_area_free(cy, cx):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                r, c = cy + dr, cx + dc
                if not in_bounds(c, r):
                    return False
                if not bool(em[r, c]):
                    return False
        return True

    def count_adjacent_road(cy, cx):
        """Count road tiles within 2 tiles of (cx, cy)"""
        count = 0
        for dr in range(-2, 3):
            for dc in range(-2, 3):
                r, c = cy + dr, cx + dc
                if in_bounds(c, r) and bool(rm[r, c]):
                    count += 1
        return count

    def count_adjacent_wire(cy, cx):
        """Count wire tiles within 2 tiles of (cx, cy)"""
        count = 0
        for dr in range(-2, 3):
            for dc in range(-2, 3):
                r, c = cy + dr, cx + dc
                if in_bounds(c, r) and bool(wm[r, c]):
                    count += 1
        return count

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))

    def pick_zone(row):
        # Balance zones: ~50% RES, ~25% COM, ~25% IND
        if ind_count == 0 or (res_count > 0 and ind_count * 4 < res_count):
            return Tool.INDUSTRIAL
        if com_count == 0 or (res_count > 0 and com_count * 4 < res_count):
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Power plant placement ---
    P1X, P1Y = 50, 50
    P2X, P2Y = 70, 50

    plant_ys, plant_xs = np.where(pm)
    has_plant1 = any(abs(px - P1X) <= 4 and abs(py - P1Y) <= 4
                     for py, px in zip(plant_ys.tolist(), plant_xs.tolist()))
    has_plant2 = any(abs(px - P2X) <= 4 and abs(py - P2Y) <= 4
                     for py, px in zip(plant_ys.tolist(), plant_xs.tolist()))

    if not has_plant1:
        return (Tool.COALPOWER, P1X, P1Y)

    # --- Closed-loop wire spine: extend from existing wires ---
    # Wire spine column at P1X + 3
    WIRE_COL1 = P1X + 3  # = 53

    # Compute current wire extent in spine column
    wire_in_col1 = sorted(int(r) for r in np.where(wm[:, WIRE_COL1])[0])

    # Determine target vertical span based on population
    pop = obs.city_pop
    half_span = 10 + min(35, pop // 15)
    tmin = max(2, P1Y - half_span)
    tmax = min(WORLD_H - 3, P1Y + half_span)

    # Start wire spine from plant if none exists
    if not wire_in_col1:
        # Start adjacent to plant
        start_y = P1Y
        if in_bounds(WIRE_COL1, start_y):
            if bool(em[start_y, WIRE_COL1]):
                return (Tool.WIRE, WIRE_COL1, start_y)
            # If not empty, try adjacent
            for dy in [1, -1, 2, -2]:
                ny = start_y + dy
                if in_bounds(WIRE_COL1, ny) and bool(em[ny, WIRE_COL1]):
                    return (Tool.WIRE, WIRE_COL1, ny)
    else:
        # Extend wire spine: check if we can extend up or down
        min_wr = wire_in_col1[0]
        max_wr = wire_in_col1[-1]
        # Prefer extending downward first, then upward
        if max_wr < tmax:
            nr = max_wr + 1
            if in_bounds(WIRE_COL1, nr) and bool(em[nr, WIRE_COL1]):
                return (Tool.WIRE, WIRE_COL1, nr)
        if min_wr > tmin:
            nr = min_wr - 1
            if in_bounds(WIRE_COL1, nr) and bool(em[nr, WIRE_COL1]):
                return (Tool.WIRE, WIRE_COL1, nr)

    # --- Road columns adjacent to wire spine ---
    ROAD_COL_L = WIRE_COL1 - 1  # = 52
    ROAD_COL_R = WIRE_COL1 + 1  # = 54

    wire_rows_set = set(wire_in_col1)
    road_rows_L = set(int(r) for r in np.where(rm[:, ROAD_COL_L])[0])
    road_rows_R = set(int(r) for r in np.where(rm[:, ROAD_COL_R])[0])

    # For each wire row, ensure roads exist on both sides
    for wr in sorted(wire_in_col1):
        if wr not in road_rows_L and in_bounds(ROAD_COL_L, wr) and bool(em[wr, ROAD_COL_L]):
            return (Tool.ROAD, ROAD_COL_L, wr)
        if wr not in road_rows_R and in_bounds(ROAD_COL_R, wr) and bool(em[wr, ROAD_COL_R]):
            return (Tool.ROAD, ROAD_COL_R, wr)

    # Refresh road sets after possible placement
    road_rows_L = set(int(r) for r in np.where(rm[:, ROAD_COL_L])[0])
    road_rows_R = set(int(r) for r in np.where(rm[:, ROAD_COL_R])[0])

    # --- Zone placement: scan wire rows and place zones outward ---
    # Zones at cols offset from spine; wire connects them
    ZONE_COLS_L = [WIRE_COL1 - 4, WIRE_COL1 - 8]   # [49, 45]
    ZONE_COLS_R = [WIRE_COL1 + 4, WIRE_COL1 + 8]   # [57, 61]

    for wr in sorted(wire_in_col1):
        if wr < 2 or wr >= WORLD_H - 2:
            continue
        road_L_near = any(abs(wr - rr) <= 1 for rr in road_rows_L)
        road_R_near = any(abs(wr - rr) <= 1 for rr in road_rows_R)

        for zc in ZONE_COLS_L:
            if road_L_near and in_bounds(zc, wr) and 2 <= zc < WORLD_W - 2:
                if zone_area_free(wr, zc):
                    return (pick_zone(wr), zc, wr)

        for zc in ZONE_COLS_R:
            if road_R_near and in_bounds(zc, wr) and 2 <= zc < WORLD_W - 2:
                if zone_area_free(wr, zc):
                    return (pick_zone(wr), zc, wr)

    # --- Lateral infrastructure to reach outer zone columns ---
    # Wire laterally to left zone columns
    for wr in sorted(wire_in_col1):
        if wr < 2 or wr >= WORLD_H - 2:
            continue
        # Extend wire leftward to reach left zone cols
        for wc in range(WIRE_COL1 - 1, max(WIRE_COL1 - 10, 0) - 1, -1):
            if not in_bounds(wc, wr):
                break
            if bool(wm[wr, wc]) or bool(pm[wr, wc]):
                break  # already wired or hits plant
            if bool(rm[wr, wc]):
                continue  # skip road tiles
            if bool(em[wr, wc]):
                return (Tool.WIRE, wc, wr)
            else:
                break

    # Road laterally to right zone columns
    for wr in sorted(wire_in_col1):
        if wr < 2 or wr >= WORLD_H - 2:
            continue
        for rc in range(ROAD_COL_R + 1, min(WIRE_COL1 + 10, WORLD_W)):
            if not in_bounds(rc, wr):
                break
            if bool(pm[wr, rc]):
                break
            if bool(rm[wr, rc]) or bool(wm[wr, rc]):
                continue
            if bool(em[wr, rc]):
                return (Tool.ROAD, rc, wr)
            else:
                break

    # --- Phase 2: second power plant + corridor ---
    if pop > 150:
        if not has_plant2:
            return (Tool.COALPOWER, P2X, P2Y)

        WIRE_COL2 = P2X + 3  # = 73
        wire_in_col2 = sorted(int(r) for r in np.where(wm[:, WIRE_COL2])[0])

        half_span2 = 8 + min(30, pop // 20)
        tmin2 = max(2, P2Y - half_span2)
        tmax2 = min(WORLD_H - 3, P2Y + half_span2)

        if not wire_in_col2:
            if in_bounds(WIRE_COL2, P2Y) and bool(em[P2Y, WIRE_COL2]):
                return (Tool.WIRE, WIRE_COL2, P2Y)
        else:
            min_wr2 = wire_in_col2[0]
            max_wr2 = wire_in_col2[-1]
            if max_wr2 < tmax2:
                nr = max_wr2 + 1
                if in_bounds(WIRE_COL2, nr) and bool(em[nr, WIRE_COL2]):
                    return (Tool.WIRE, WIRE_COL2, nr)
            if min_wr2 > tmin2:
                nr = min_wr2 - 1
                if in_bounds(WIRE_COL2, nr) and bool(em[nr, WIRE_COL2]):
                    return (Tool.WIRE, WIRE_COL2, nr)

        ROAD_COL2_L = WIRE_COL2 - 1
        ROAD_COL2_R = WIRE_COL2 + 1
        road_rows2_L = set(int(r) for r in np.where(rm[:, ROAD_COL2_L])[0])
        road_rows2_R = set(int(r) for r in np.where(rm[:, ROAD_COL2_R])[0])

        for wr in sorted(wire_in_col2):
            if wr not in road_rows2_L and in_bounds(ROAD_COL2_L, wr) and bool(em[wr, ROAD_COL2_L]):
                return (Tool.ROAD, ROAD_COL2_L, wr)
            if wr not in road_rows2_R and in_bounds(ROAD_COL2_R, wr) and bool(em[wr, ROAD_COL2_R]):
                return (Tool.ROAD, ROAD_COL2_R, wr)

        road_rows2_L = set(int(r) for r in np.where(rm[:, ROAD_COL2_L])[0])
        road_rows2_R = set(int(r) for r in np.where(rm[:, ROAD_COL2_R])[0])

        ZONE_COLS2_L = [WIRE_COL2 - 4, WIRE_COL2 - 8]
        ZONE_COLS2_R = [WIRE_COL2 + 4, WIRE_COL2 + 8]

        for wr in sorted(wire_in_col2):
            if wr < 2 or wr >= WORLD_H - 2:
                continue
            r2L = any(abs(wr - rr) <= 1 for rr in road_rows2_L)
            r2R = any(abs(wr - rr) <= 1 for rr in road_rows2_R)
            for zc in ZONE_COLS2_L:
                if r2L and in_bounds(zc, wr) and 2 <= zc < WORLD_W - 2:
                    if zone_area_free(wr, zc):
                        return (pick_zone(wr), zc, wr)
            for zc in ZONE_COLS2_R:
                if r2R and in_bounds(zc, wr) and 2 <= zc < WORLD_W - 2:
                    if zone_area_free(wr, zc):
                        return (pick_zone(wr), zc, wr)

        # Lateral wire/road for corridor 2
        for wr in sorted(wire_in_col2):
            for wc in range(WIRE_COL2 - 1, max(WIRE_COL2 - 10, 0) - 1, -1):
                if not in_bounds(wc, wr):
                    break
                if bool(wm[wr, wc]) or bool(pm[wr, wc]):
                    break
                if bool(rm[wr, wc]):
                    continue
                if bool(em[wr, wc]):
                    return (Tool.WIRE, wc, wr)
                else:
                    break

        for wr in sorted(wire_in_col2):
            for rc in range(ROAD_COL2_R + 1, min(WIRE_COL2 + 10, WORLD_W)):
                if not in_bounds(rc, wr):
                    break
                if bool(pm[wr, rc]):
                    break
                if bool(rm[wr, rc]) or bool(wm[wr, rc]):
                    continue
                if bool(em[wr, rc]):
                    return (Tool.ROAD, rc, wr)
                else:
                    break

    # --- Services: place reactively based on pop ---
    if pop > 300:
        # Fire station near zone cluster
        fsx, fsy = WIRE_COL1 + 7, P1Y - 10
        if in_bounds(fsx, fsy) and zone_area_free(fsy, fsx):
            return (Tool.FIRESTATION, fsx, fsy)

    if pop > 600:
        psx, psy = WIRE_COL1 - 7, P1Y + 10
        if in_bounds(psx, psy) and zone_area_free(psy, psx):
            return (Tool.POLICESTATION, psx, psy)

    # --- Fallback: scan for zones adjacent to roads but not wired, add wire ---
    # Find road tiles without nearby wire and add wire connection
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        # Try to find a road tile that needs wire
        for i in range(min(20, len(road_xs))):
            idx = (int(obs.step) * 7 + i * 13) % len(road_xs)
            rx, ry = int(road_xs[idx]), int(road_ys[idx])
            if count_adjacent_wire(ry, rx) == 0:
                # Find empty adjacent tile for wire
                for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nx, ny = rx + dx, ry + dy
                    if in_bounds(nx, ny) and bool(em[ny, nx]):
                        return (Tool.WIRE, nx, ny)

    # Fallback: extend any road
    if len(road_xs) > 0:
        idx = (int(obs.step) * 11) % len(road_xs)
        rx, ry = int(road_xs[idx]), int(road_ys[idx])
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx, ny = rx + dx, ry + dy
            if in_bounds(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                return (Tool.ROAD, nx, ny)

    return None

def act(obs, state):
    """
    Hybrid policy combining:
    - Vertical wire+road spine from Parent B (reliable power/road)
    - Multiple clusters/plants from Parent A
    - Lateral wires for zone powering from Parent B
    - Balanced RCI zones on both sides of spine
    - Expanded spine and multiple zone tiers
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def has_tile(mask, x, y):
        return 0 <= y < WORLD_H and 0 <= x < WORLD_W and bool(mask[y, x])

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    pop = obs.city_pop
    plant_count = int(np.sum(pm))

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.22:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Layout: two spines, left and right clusters
    # Left spine centered around x=40, right spine around x=75
    # Each spine: wire col, road col adjacent

    # Left cluster
    L_plant_x, L_plant_y = 35, 50
    L_wire_col = 40
    L_road_col = 41
    L_left_zcol = 36   # zones to the left of wire
    L_right_zcol = 44  # zones to the right of road

    # Right cluster
    R_plant_x, R_plant_y = 72, 50
    R_wire_col = 77
    R_road_col = 78
    R_left_zcol = 73
    R_right_zcol = 81

    # Adaptive spine half-length
    if pop < 50:
        spine_half = 12
    elif pop < 200:
        spine_half = 18
    elif pop < 500:
        spine_half = 24
    else:
        spine_half = 28

    cy = WORLD_H // 2
    spine_min = max(1, cy - spine_half)
    spine_max = min(WORLD_H - 2, cy + spine_half)
    spine_range = range(spine_min, spine_max + 1)

    # ---- Phase 0: Place power plants ----
    if not np.any(pm):
        return (Tool.COALPOWER, L_plant_x, L_plant_y)
    if not has_tile(pm, L_plant_x, L_plant_y) and not has_tile(pm, L_plant_x+1, L_plant_y) and not has_tile(pm, L_plant_x-1, L_plant_y):
        # check vicinity
        lp_exists = any(bool(pm[L_plant_y+dy, L_plant_x+dx])
                        for dy in range(-4,5) for dx in range(-4,5)
                        if 0<=L_plant_y+dy<WORLD_H and 0<=L_plant_x+dx<WORLD_W)
        if not lp_exists:
            return (Tool.COALPOWER, L_plant_x, L_plant_y)

    # ---- Phase 1: Left wire spine ----
    for dy in spine_range:
        if not has_tile(wm, L_wire_col, dy) and not has_tile(pm, L_wire_col, dy) and not has_tile(rm, L_wire_col, dy):
            return (Tool.WIRE, L_wire_col, dy)

    # ---- Phase 2: Left road spine ----
    for dy in spine_range:
        if not has_tile(rm, L_road_col, dy) and not has_tile(pm, L_road_col, dy) and not has_tile(wm, L_road_col, dy):
            return (Tool.ROAD, L_road_col, dy)

    # ---- Phase 3: Connect plant to wire spine ----
    # Wire from plant to wire col horizontally at plant_y
    for wx in range(L_plant_x + 2, L_wire_col):
        if not has_tile(wm, wx, L_plant_y) and not has_tile(pm, wx, L_plant_y):
            if has_tile(em, wx, L_plant_y):
                return (Tool.WIRE, wx, L_plant_y)
            break

    # ---- Phase 4: Lateral wires leftward from wire spine ----
    L_wire_rows = [r for r in spine_range if wm[r, L_wire_col]]
    target_left = L_left_zcol + 1
    for wr in L_wire_rows:
        for wc in range(L_wire_col - 1, target_left - 1, -1):
            if not (0 <= wc < WORLD_W):
                break
            if wm[wr, wc] or pm[wr, wc]:
                break
            if rm[wr, wc]:
                break
            if em[wr, wc]:
                return (Tool.WIRE, wc, wr)
            else:
                break

    # ---- Phase 5: Lateral wires rightward ----
    target_right = L_right_zcol + 1
    for wr in L_wire_rows:
        for wc in range(L_road_col + 1, target_right + 1):
            if not (0 <= wc < WORLD_W):
                break
            if wm[wr, wc] or pm[wr, wc]:
                break
            if rm[wr, wc]:
                continue
            if em[wr, wc]:
                return (Tool.WIRE, wc, wr)
            else:
                break

    # ---- Phase 6: Place left cluster zones ----
    all_zone_m = resm | comm | indm
    L_road_rows = [r for r in spine_range if rm[r, L_road_col]]

    def zone_area_clear(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_m[rr, rc]:
                    return False
        return True

    def zone_present_near(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_m[rr, rc]:
                        return True
        return False

    zone_rows = list(range(spine_min + 1, spine_max - 1, 3))

    for zr in zone_rows:
        wire_near = any(abs(zr - wr) <= 2 for wr in L_wire_rows)
        road_near = any(abs(zr - rr) <= 2 for rr in L_road_rows)
        if not (wire_near and road_near):
            continue
        # Left zone
        zc = L_left_zcol
        lateral_wired = any(wm[zr, wc] for wc in range(max(0,zc-1), L_wire_col) if 0 <= wc < WORLD_W)
        if lateral_wired and not zone_present_near(zr, zc) and zone_area_clear(zr, zc):
            return (pick_tool(), zc, zr)
        # Right zone
        zc = L_right_zcol
        right_wired = any(wm[zr, wc] for wc in range(L_road_col, min(WORLD_W, zc+2)))
        if right_wired and not zone_present_near(zr, zc) and zone_area_clear(zr, zc):
            return (pick_tool(), zc, zr)

    # ---- Phase 7: Second power plant (right cluster) ----
    if pop > 100 or total_zones > 10:
        rp_exists = any(bool(pm[R_plant_y+dy, R_plant_x+dx])
                        for dy in range(-5,6) for dx in range(-5,6)
                        if 0<=R_plant_y+dy<WORLD_H and 0<=R_plant_x+dx<WORLD_W)
        if not rp_exists:
            return (Tool.COALPOWER, R_plant_x, R_plant_y)

    # ---- Phase 8: Right wire spine ----
    for dy in spine_range:
        if not has_tile(wm, R_wire_col, dy) and not has_tile(pm, R_wire_col, dy) and not has_tile(rm, R_wire_col, dy):
            return (Tool.WIRE, R_wire_col, dy)

    # ---- Phase 9: Right road spine ----
    for dy in spine_range:
        if not has_tile(rm, R_road_col, dy) and not has_tile(pm, R_road_col, dy) and not has_tile(wm, R_road_col, dy):
            return (Tool.ROAD, R_road_col, dy)

    # Connect right plant to right wire spine
    for wx in range(R_plant_x + 2, R_wire_col):
        if not has_tile(wm, wx, R_plant_y) and not has_tile(pm, wx, R_plant_y):
            if has_tile(em, wx, R_plant_y):
                return (Tool.WIRE, wx, R_plant_y)
            break

    # Lateral wires for right cluster
    R_wire_rows = [r for r in spine_range if wm[r, R_wire_col]]
    R_road_rows = [r for r in spine_range if rm[r, R_road_col]]

    for wr in R_wire_rows:
        for wc in range(R_wire_col - 1, R_left_zcol, -1):
            if not (0 <= wc < WORLD_W): break
            if wm[wr, wc] or pm[wr, wc]: break
            if rm[wr, wc]: break
            if em[wr, wc]:
                return (Tool.WIRE, wc, wr)
            else: break

    for wr in R_wire_rows:
        for wc in range(R_road_col + 1, R_right_zcol + 2):
            if not (0 <= wc < WORLD_W): break
            if wm[wr, wc] or pm[wr, wc]: break
            if rm[wr, wc]: continue
            if em[wr, wc]:
                return (Tool.WIRE, wc, wr)
            else: break

    # Right cluster zones
    for zr in zone_rows:
        wire_near = any(abs(zr - wr) <= 2 for wr in R_wire_rows)
        road_near = any(abs(zr - rr) <= 2 for rr in R_road_rows)
        if not (wire_near and road_near):
            continue
        zc = R_left_zcol
        lateral_wired = any(wm[zr, wc] for wc in range(max(0,zc-1), R_wire_col) if 0 <= wc < WORLD_W)
        if lateral_wired and not zone_present_near(zr, zc) and zone_area_clear(zr, zc):
            return (pick_tool(), zc, zr)
        zc = R_right_zcol
        right_wired = any(wm[zr, wc] for wc in range(R_road_col, min(WORLD_W, zc+2)))
        if right_wired and not zone_present_near(zr, zc) and zone_area_clear(zr, zc):
            return (pick_tool(), zc, zr)

    # ---- Phase 10: Connect the two spines with horizontal road ----
    if pop > 50:
        connect_y = cy
        for cx in range(L_road_col + 1, R_wire_col):
            if not has_tile(rm, cx, connect_y) and not has_tile(pm, cx, connect_y) and has_tile(em, cx, connect_y):
                return (Tool.ROAD, cx, connect_y)

    # ---- Phase 11: Horizontal connector wires between spines ----
    if pop > 80:
        conn_wy = cy - 2
        for cx2 in range(L_wire_col + 1, R_wire_col):
            if not has_tile(wm, cx2, conn_wy) and not has_tile(pm, cx2, conn_wy) and has_tile(em, cx2, conn_wy):
                return (Tool.WIRE, cx2, conn_wy)

    # ---- Phase 12: Second tier zones (wider spread) ----
    if pop > 150:
        L_left2 = max(2, L_left_zcol - 5)
        L_right2 = min(WORLD_W - 3, L_right_zcol + 5)
        R_left2 = max(2, R_left_zcol - 5)
        R_right2 = min(WORLD_W - 3, R_right_zcol + 5)

        for zr in zone_rows:
            for zc in [L_left2, L_right2, R_left2, R_right2]:
                if not zone_present_near(zr, zc) and zone_area_clear(zr, zc):
                    r0 = max(0, zr-5); r1 = min(WORLD_H, zr+6)
                    c0 = max(0, zc-5); c1 = min(WORLD_W, zc+6)
                    if np.any(wm[r0:r1, c0:c1]) and np.any(rm[r0:r1, c0:c1]):
                        return (pick_tool(), zc, zr)

    # ---- Phase 13: Additional power plants ----
    if pop > 300 and plant_count < 18:
        for px3, py3 in [(L_plant_x, L_plant_y - 20), (R_plant_x, R_plant_y + 20),
                         (L_plant_x - 10, L_plant_y + 10), (R_plant_x + 10, R_plant_y - 10)]:
            px3 = max(2, min(WORLD_W - 3, px3))
            py3 = max(2, min(WORLD_H - 3, py3))
            if has_tile(em, px3, py3):
                area_clear = all(
                    has_tile(em, px3+dx, py3+dy) or has_tile(pm, px3+dx, py3+dy)
                    for dx in range(-2,3) for dy in range(-2,3)
                    if 0<=px3+dx<WORLD_W and 0<=py3+dy<WORLD_H
                )
                if area_clear:
                    return (Tool.COALPOWER, px3, py3)

    # ---- Phase 14: Services ----
    if pop > 200:
        for fx, fy in [(L_wire_col-2, spine_min-3), (R_wire_col+2, spine_max+3)]:
            fx = max(1, min(WORLD_W-2, fx))
            fy = max(1, min(WORLD_H-2, fy))
            if has_tile(em, fx, fy):
                return (Tool.FIRESTATION, fx, fy)
    if pop > 300:
        for fx, fy in [(L_road_col+2, spine_min-3), (R_road_col-2, spine_max+3)]:
            fx = max(1, min(WORLD_W-2, fx))
            fy = max(1, min(WORLD_H-2, fy))
            if has_tile(em, fx, fy):
                return (Tool.POLICESTATION, fx, fy)

    # ---- Fallback: extend roads from existing road frontier ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        k = int(obs.step * 13) % len(road_xs)
        rx_s, ry_s = int(road_xs[k]), int(road_ys[k])
        for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx, ny = rx_s+dx, ry_s+dy
            if 0<=nx<WORLD_W and 0<=ny<WORLD_H and bool(em[ny,nx]) and not bool(pm[ny,nx]):
                return (Tool.ROAD, nx, ny)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map every step and reacts to current state.
    Strategy:
    - Place coal power plant near center
    - Extend wire spine vertically from plant
    - Build TWO road columns (one each side of wire spine)
    - Place zones between road columns and wire spine
    - Add lateral wires to power zones on both sides
    - Second power plant when needed
    - Expand vertically and horizontally based on population
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Phase 1: Place coal power plant if missing
    if not np.any(pm):
        return (Tool.COALPOWER, cx - 6, cy)

    # Find plant centroid
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Layout columns relative to plant
    wire_col = plant_cx + 3       # wire spine just right of plant
    left_road_col = wire_col - 4  # road left of wire
    right_road_col = wire_col + 4 # road right of wire
    left_zone_col = wire_col - 7  # zone centers left of left road
    right_zone_col = wire_col + 7 # zone centers right of right road

    # Clamp columns
    wire_col = max(2, min(WORLD_W - 3, wire_col))
    left_road_col = max(2, min(WORLD_W - 3, left_road_col))
    right_road_col = max(2, min(WORLD_W - 3, right_road_col))
    left_zone_col = max(2, min(WORLD_W - 3, left_zone_col))
    right_zone_col = max(2, min(WORLD_W - 3, right_zone_col))

    # Current wire positions on spine
    wire_rows_on_spine = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])

    # Spine extent based on population
    if obs.city_pop < 50:
        spine_extent = 6
    elif obs.city_pop < 200:
        spine_extent = 12
    elif obs.city_pop < 500:
        spine_extent = 18
    elif obs.city_pop < 900:
        spine_extent = 24
    else:
        spine_extent = 32

    target_min = max(1, cy - spine_extent)
    target_max = min(WORLD_H - 2, cy + spine_extent)

    # Phase 2: Start wire adjacent to plant if none on spine
    if not wire_rows_on_spine:
        # Try rows near plant
        for dy in range(0, 6):
            for nr in [plant_cy + dy, plant_cy - dy]:
                if 0 <= nr < WORLD_H:
                    if em[nr, wire_col] or wm[nr, wire_col]:
                        return (Tool.WIRE, wire_col, nr)
        return None

    min_wire_row = min(wire_rows_on_spine)
    max_wire_row = max(wire_rows_on_spine)

    # Phase 3: Extend wire spine downward
    if max_wire_row < target_max:
        nr = max_wire_row + 1
        if nr < WORLD_H and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Phase 4: Extend wire spine upward
    if min_wire_row > target_min:
        nr = min_wire_row - 1
        if nr >= 0 and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Phase 5: Build left road column
    for r in wire_rows_on_spine:
        if 0 <= r < WORLD_H and 0 <= left_road_col < WORLD_W:
            if not rm[r, left_road_col] and em[r, left_road_col] and not pm[r, left_road_col]:
                return (Tool.ROAD, left_road_col, r)

    # Phase 6: Build right road column
    for r in wire_rows_on_spine:
        if 0 <= r < WORLD_H and 0 <= right_road_col < WORLD_W:
            if not rm[r, right_road_col] and em[r, right_road_col] and not pm[r, right_road_col]:
                return (Tool.ROAD, right_road_col, r)

    # Helper: check if 3x3 zone area is clear
    all_zone_mask = resm | comm | indm

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=5):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Phase 7: Lateral wires from spine to left and right zone columns
    # Wire left: spine -> left zones
    for wr in wire_rows_on_spine:
        for wc in range(wire_col - 1, left_zone_col - 2, -1):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc] or pm[wr, wc]:
                    break
                if em[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc] and not wm[wr, wc]:
                    break

    # Wire right: spine -> right zones
    for wr in wire_rows_on_spine:
        for wc in range(wire_col + 1, right_zone_col + 2):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc] or pm[wr, wc]:
                    break
                if em[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc] and not wm[wr, wc]:
                    break

    # Phase 8: Place zones in covered area
    left_road_rows = sorted([r for r in range(WORLD_H) if rm[r, left_road_col]])
    right_road_rows = sorted([r for r in range(WORLD_H) if rm[r, right_road_col]])

    zone_rows = list(range(max(1, target_min + 1), min(WORLD_H - 1, target_max), 3))

    for zr in zone_rows:
        wire_near = any(abs(zr - wr) <= 2 for wr in wire_rows_on_spine)

        # Left zone: needs left road and wire
        if wire_near:
            left_road_near = any(abs(zr - rr) <= 2 for rr in left_road_rows)
            if left_road_near:
                zc = left_zone_col
                if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                    if has_wire_nearby(zr, zc) and has_road_nearby(zr, zc):
                        return (pick_tool(), zc, zr)

            # Right zone: needs right road and wire
            right_road_near = any(abs(zr - rr) <= 2 for rr in right_road_rows)
            if right_road_near:
                zc = right_zone_col
                if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                    if has_wire_nearby(zr, zc) and has_road_nearby(zr, zc):
                        return (pick_tool(), zc, zr)

            # Inner left zone (between left road and wire spine)
            inner_left_col = wire_col - 2
            inner_left_col = max(2, min(WORLD_W - 3, inner_left_col))
            if inner_left_col != wire_col and inner_left_col != left_road_col:
                if not zone_already_there(zr, inner_left_col) and zone_area_ok(zr, inner_left_col):
                    if has_wire_nearby(zr, inner_left_col, 3) and has_road_nearby(zr, inner_left_col, 5):
                        return (pick_tool(), inner_left_col, zr)

            # Inner right zone (between wire spine and right road)
            inner_right_col = wire_col + 2
            inner_right_col = max(2, min(WORLD_W - 3, inner_right_col))
            if inner_right_col != wire_col and inner_right_col != right_road_col:
                if not zone_already_there(zr, inner_right_col) and zone_area_ok(zr, inner_right_col):
                    if has_wire_nearby(zr, inner_right_col, 3) and has_road_nearby(zr, inner_right_col, 5):
                        return (pick_tool(), inner_right_col, zr)

    # Phase 9: Second coal plant if population demands more power
    plant_count = int(np.sum(pm)) // 9  # each plant is 4x4=16 tiles but roughly 9
    if obs.city_pop > 300 and np.sum(pm) < 18:
        # Place second plant to the right
        px2, py2 = plant_cx + 20, plant_cy
        if 2 <= py2 <= WORLD_H - 3 and 2 <= px2 <= WORLD_W - 3:
            if em[py2, px2]:
                return (Tool.COALPOWER, px2, py2)

    # Phase 10: Extend spine even more for large populations
    if obs.city_pop > 600:
        extended_min = max(1, target_min - 6)
        extended_max = min(WORLD_H - 2, target_max + 6)
        if min_wire_row > extended_min:
            nr = min_wire_row - 1
            if nr >= 0 and not pm[nr, wire_col] and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        if max_wire_row < extended_max:
            nr = max_wire_row + 1
            if nr < WORLD_H and not pm[nr, wire_col] and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    # Phase 11: Extra zone columns far out for large populations
    if obs.city_pop > 400:
        far_left_col = left_zone_col - 4
        far_right_col = right_zone_col + 4
        for zc in [far_left_col, far_right_col]:
            if 2 <= zc <= WORLD_W - 3:
                for zr in zone_rows:
                    if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                        if has_road_nearby(zr, zc, 6) and has_wire_nearby(zr, zc, 7):
                            return (pick_tool(), zc, zr)

    # Phase 12: Connect roads horizontally at top and bottom of coverage
    if obs.city_pop > 150 and wire_rows_on_spine:
        for h_row in [min_wire_row, max_wire_row]:
            if 0 <= h_row < WORLD_H:
                for rc in range(min(left_road_col, left_zone_col) - 1,
                                max(right_road_col, right_zone_col) + 2):
                    if 0 <= rc < WORLD_W and em[h_row, rc] and not pm[h_row, rc] and not wm[h_row, rc]:
                        return (Tool.ROAD, rc, h_row)

    return None

def act(obs, state):
    """
    Improved policy with a horizontal road/wire layout instead of vertical,
    two power plants, and a balanced mix of residential/commercial/industrial zones.
    Uses a grid-based approach with horizontal wire spine and zones above/below.
    """
    tm = obs.tile_map
    step = obs.step

    # Use a more eastern starting position for a different cluster location
    cx, cy = WORLD_W // 2 + 10, WORLD_H // 2 - 5

    em = empty_mask(tm)
    rm = road_mask(tm)
    wm = wire_mask(tm)
    pm = plant_mask(tm)

    has_plant = np.any(pm)
    has_wire = np.any(wm)
    has_road = np.any(rm)
    res_count = np.sum(res_mask(tm))
    com_count = np.sum(com_mask(tm))
    ind_count = np.sum(ind_mask(tm))

    wire_positions = list(zip(*np.where(wm))) if has_wire else []
    road_positions = list(zip(*np.where(rm))) if has_road else []
    plant_positions = list(zip(*np.where(pm))) if has_plant else []

    # Phase 1: Place first coal power plant if missing
    if not has_plant:
        return (Tool.COALPOWER, cx - 10, cy)

    # Phase 2: Build horizontal wire spine at row cy
    # Wire runs from plant right edge eastward
    wire_row = cy
    wire_row_cols = sorted([c for (r, c) in wire_positions if r == wire_row])

    if not wire_row_cols:
        # Start wire just right of plant (plant center cx-10, footprint cx-12..cx-8)
        start_wc = cx - 7
        if em[wire_row, start_wc]:
            return (Tool.WIRE, start_wc, wire_row)
        else:
            return (Tool.WIRE, start_wc + 1, wire_row)
    else:
        min_col = min(wire_row_cols)
        max_col = max(wire_row_cols)
        target_min = cx - 12
        target_max = cx + 12

        # Extend wire rightward first
        if max_col < target_max and max_col + 1 < WORLD_W:
            nc = max_col + 1
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)
        # Extend wire leftward
        if min_col > target_min and min_col - 1 >= 0:
            nc = min_col - 1
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # Phase 3: Build road row just below wire spine (cy+1)
    road_row = cy + 2  # road row, wire at cy
    road_row_cols = sorted([c for (r, c) in road_positions if r == road_row])
    wire_row_cols_sorted = sorted(wire_row_cols) if wire_row_cols else []

    if wire_row_cols_sorted:
        for c in wire_row_cols_sorted:
            if 0 <= road_row < WORLD_H and 0 <= c < WORLD_W:
                if not rm[road_row, c]:
                    if em[road_row, c]:
                        return (Tool.ROAD, c, road_row)

    # Also add a second road row above wire (cy-2)
    road_row2 = cy - 2
    if wire_row_cols_sorted:
        for c in wire_row_cols_sorted:
            if 0 <= road_row2 < WORLD_H and 0 <= c < WORLD_W:
                if not rm[road_row2, c]:
                    if em[road_row2, c]:
                        return (Tool.ROAD, c, road_row2)

    # Phase 4: Place zones above and below the road rows
    # Above road (road_row2=cy-2): zone centers at cy-5 (above) 
    # Below road (road_row=cy+2): zone centers at cy+5 (below)
    # Zones spaced every 4 columns

    res_positions = list(zip(*np.where(res_mask(tm)))) if res_count > 0 else []

    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    # Zone rows: above (cy-5) and below (cy+5)
    zone_rows = [cy - 5, cy + 5]
    # Zone cols spaced by 4 across wire extent
    zone_cols = list(range(cx - 12, cx + 13, 4))

    # Counter for balanced mix
    total_zones = res_count + com_count + ind_count

    for zr in zone_rows:
        for zc in zone_cols:
            if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                # Check wire coverage in column zc
                wire_in_col = any(abs(zc - wc) <= 1 for (wr, wc) in wire_positions if wr == wire_row)
                # Check road coverage
                road_above = any(abs(zc - rc) <= 1 for (rr, rc) in road_positions if rr == road_row2)
                road_below = any(abs(zc - rc) <= 1 for (rr, rc) in road_positions if rr == road_row)
                road_ok = road_above or road_below

                if wire_in_col and road_ok:
                    already = any(abs(zr - pr) <= 2 and abs(zc - pc) <= 2
                                  for (pr, pc) in res_positions)
                    # Also check com/ind
                    cpos = list(zip(*np.where(com_mask(tm)))) if com_count > 0 else []
                    ipos = list(zip(*np.where(ind_mask(tm)))) if ind_count > 0 else []
                    already_c = any(abs(zr - pr) <= 2 and abs(zc - pc) <= 2 for (pr, pc) in cpos)
                    already_i = any(abs(zr - pr) <= 2 and abs(zc - pc) <= 2 for (pr, pc) in ipos)
                    already_any = already or already_c or already_i

                    if not already_any and zone_area_free(zr, zc):
                        # Balanced mix: 50% res, 25% com, 25% ind
                        idx = (zr * 31 + zc) % 4
                        if idx == 0 and com_count < res_count // 2 + 1:
                            return (Tool.COMMERCIAL, zc, zr)
                        elif idx == 1 and ind_count < res_count // 2 + 1:
                            return (Tool.INDUSTRIAL, zc, zr)
                        else:
                            return (Tool.RESIDENTIAL, zc, zr)

    # Phase 5: Add vertical wire connections from spine to zones
    for wc in wire_row_cols_sorted:
        # Connect upward to road_row2
        for wr in range(wire_row - 1, road_row2 - 1, -1):
            if 0 <= wr < WORLD_H and em[wr, wc]:
                if not wm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
        # Connect downward to road_row
        for wr in range(wire_row + 1, road_row + 2):
            if 0 <= wr < WORLD_H and em[wr, wc]:
                if not wm[wr, wc]:
                    return (Tool.WIRE, wc, wr)

    # Phase 6: Add a second power plant if population growing
    plant_count = len(plant_positions)
    if obs.city_pop > 300 and plant_count < 2:
        # Place second plant on the other side
        px2, py2 = cx + 12, cy
        if all(em[py2 + dr, px2 + dc]
               for dr in [-1, 0, 1] for dc in [-1, 0, 1]
               if 0 <= py2 + dr < WORLD_H and 0 <= px2 + dc < WORLD_W):
            return (Tool.COALPOWER, px2, py2)

    # Phase 7: Extend the cluster further if population high
    if obs.city_pop > 150:
        # Add more zone rows further out
        extra_zone_rows = [cy - 9, cy + 9]
        for zr in extra_zone_rows:
            for zc in zone_cols:
                if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                    wire_in_col = any(abs(zc - wc) <= 1 for (wr2, wc) in wire_positions if wr2 == wire_row)
                    if wire_in_col:
                        cpos = list(zip(*np.where(com_mask(tm)))) if com_count > 0 else []
                        ipos = list(zip(*np.where(ind_mask(tm)))) if ind_count > 0 else []
                        already = (any(abs(zr - pr) <= 2 and abs(zc - pc) <= 2 for (pr, pc) in res_positions) or
                                   any(abs(zr - pr) <= 2 and abs(zc - pc) <= 2 for (pr, pc) in cpos) or
                                   any(abs(zr - pr) <= 2 and abs(zc - pc) <= 2 for (pr, pc) in ipos))
                        if not already and zone_area_free(zr, zc):
                            # Add road at cy+/-6 or cy+/-8 for access
                            road_r = cy + 6 if zr > cy else cy - 6
                            if not rm[road_r, zc] and em[road_r, zc]:
                                return (Tool.ROAD, zc, road_r)
                            idx = (zr * 17 + zc) % 4
                            if idx == 0:
                                return (Tool.COMMERCIAL, zc, zr)
                            elif idx == 1:
                                return (Tool.INDUSTRIAL, zc, zr)
                            else:
                                return (Tool.RESIDENTIAL, zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map each step and reacts to current state.
    Strategy:
    - Place coal power plant at a fixed anchor.
    - Grow wire spine vertically from plant.
    - Grow road column adjacent to wire spine.
    - Place zones (RES/COM/IND) on both sides of the road/wire corridor.
    - Lateral wires connect zones to spine.
    - All decisions based on CURRENT map state, not a precomputed plan.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    cx, cy = 60, 50  # center of map

    # Anchor positions
    plant_cx, plant_cy = cx - 5, cy
    wire_col = plant_cx + 3  # column just right of plant footprint
    road_col = wire_col + 2  # road two cols right of wire spine
    left_zone_col = wire_col - 3  # zones left of wire (centered)
    right_zone_col = road_col + 3  # zones right of road

    # Phase 1: Place coal power plant if missing
    if not np.any(pm):
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Read current wire spine coverage
    wire_col_rows = sorted([r for (r, c) in zip(*np.where(wm)) if c == wire_col]) if np.any(wm) else []
    road_col_rows = sorted([r for (r, c) in zip(*np.where(rm)) if c == road_col]) if np.any(rm) else []

    # Phase 2: Start wire adjacent to plant if no wire on spine
    if not wire_col_rows:
        # Try plant_cy first, then nearby rows
        for dy in range(0, 6):
            for nr in ([plant_cy] if dy == 0 else [plant_cy + dy, plant_cy - dy]):
                if 0 <= nr < WORLD_H and 0 <= wire_col < WORLD_W:
                    if em[nr, wire_col] or wm[nr, wire_col]:
                        return (Tool.WIRE, wire_col, nr)
        return None

    # Phase 3: Extend wire spine vertically
    target_min = max(1, cy - 18)
    target_max = min(WORLD_H - 2, cy + 18)

    min_row = min(wire_col_rows)
    max_row = max(wire_col_rows)

    # Extend downward first
    if max_row < target_max:
        nr = max_row + 1
        if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
            return (Tool.WIRE, wire_col, nr)

    # Extend upward
    if min_row > target_min:
        nr = min_row - 1
        if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
            return (Tool.WIRE, wire_col, nr)

    # Phase 4: Build road column for each wire row
    for r in wire_col_rows:
        if 0 <= r < WORLD_H and 0 <= road_col < WORLD_W:
            if not rm[r, road_col] and (em[r, road_col] or wm[r, road_col]):
                return (Tool.ROAD, road_col, r)

    # Helper: check if 3x3 zone area is safe to place
    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                # Allow if empty or already same zone type
                if not em[rr, rc]:
                    return False
        return True

    # Existing zone positions for overlap check
    zone_m = res_m | com_m | ind_m
    zone_positions = list(zip(*np.where(zone_m))) if np.any(zone_m) else []

    def zone_already_placed(zr, zc):
        return any(abs(zr - pr) <= 2 and abs(zc - pc) <= 2 for (pr, pc) in zone_positions)

    res_count = int(np.sum(res_m))
    com_count = int(np.sum(com_m))
    ind_count = int(np.sum(ind_m))

    # Phase 5: Place zones at rows where wire AND road exist
    # Space zones 3 apart
    zone_rows = list(range(max(1, min_row + 1), min(WORLD_H - 2, max_row), 3))

    for zr in zone_rows:
        wire_near = any(abs(zr - wr) <= 2 for wr in wire_col_rows)
        road_near = any(zr == rr for rr in road_col_rows)

        if wire_near and road_near:
            # Try LEFT zone (powered by wire spine)
            zc = left_zone_col
            if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                if not zone_already_placed(zr, zc) and zone_area_free(zr, zc):
                    # Balance zone types
                    if ind_count * 4 < res_count:
                        return (Tool.INDUSTRIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

            # Try RIGHT zone (powered via road+wire)
            zc = right_zone_col
            if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                if not zone_already_placed(zr, zc) and zone_area_free(zr, zc):
                    if com_count * 4 < res_count:
                        return (Tool.COMMERCIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

    # Phase 6: Lateral wires from spine to left zones
    for wr in wire_col_rows:
        for wc in range(wire_col - 1, max(0, left_zone_col - 2), -1):
            if 0 <= wc < WORLD_W and em[wr, wc] and not wm[wr, wc]:
                return (Tool.WIRE, wc, wr)

    # Phase 7: Road extension to right zones
    for wr in wire_col_rows:
        for rc in range(road_col + 1, min(WORLD_W - 1, right_zone_col + 2)):
            if 0 <= rc < WORLD_W and em[wr, rc] and not rm[wr, rc]:
                return (Tool.ROAD, rc, wr)

    # Phase 8: Wire connections to right zones (over road gap)
    # Wire from spine to road: at zone center rows
    for wr in wire_col_rows:
        for wc in range(wire_col + 1, road_col):
            if 0 <= wc < WORLD_W and em[wr, wc] and not wm[wr, wc]:
                return (Tool.WIRE, wc, wr)

    # Phase 9: Expand if city is growing — add more zone columns
    if obs.city_pop > 200:
        extra_left_col = left_zone_col - 4
        extra_right_col = right_zone_col + 4
        extra_zone_rows = list(range(max(1, min_row + 1), min(WORLD_H - 2, max_row), 3))
        road_pos_set = set(road_col_rows)
        for zr in extra_zone_rows:
            road_near = (zr in road_pos_set) or any(abs(zr - rr) <= 2 for rr in road_col_rows)
            wire_near = any(abs(zr - wr) <= 3 for wr in wire_col_rows)
            if road_near and wire_near:
                for zc in [extra_left_col, extra_right_col]:
                    if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                        if not zone_already_placed(zr, zc) and zone_area_free(zr, zc):
                            return (Tool.RESIDENTIAL, zc, zr)

    # Phase 10: Extend wire and road further if city is large
    if obs.city_pop > 400:
        new_target_min = max(1, cy - 25)
        new_target_max = min(WORLD_H - 2, cy + 25)
        if max_row < new_target_max:
            nr = max_row + 1
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        if min_row > new_target_min:
            nr = min_row - 1
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder.
    - Reads tile_map every step to decide next action
    - Places power plants, then extends wires from existing power,
      extends roads from existing roads, then places zones near roads+wires
    - Two cluster anchors but all decisions based on current map state
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Two cluster power plant anchors
    P1X, P1Y = 30, 50
    P2X, P2Y = 85, 50

    # Check if plants exist near anchors
    plant_ys, plant_xs = np.where(pm)
    has_plant1 = any(abs(px - P1X) < 8 and abs(py - P1Y) < 8
                     for py, px in zip(plant_ys.tolist(), plant_xs.tolist()))
    has_plant2 = any(abs(px - P2X) < 8 and abs(py - P2Y) < 8
                     for py, px in zip(plant_ys.tolist(), plant_xs.tolist()))

    # Phase 1: ensure power plants exist
    if not has_plant1:
        return (Tool.COALPOWER, P1X, P1Y)
    if not has_plant2:
        return (Tool.COALPOWER, P2X, P2Y)

    # Count zone types for balanced placement
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        # Target: 50% res, 25% com, 25% ind
        t = max(total_zones, 1)
        if com_count / t < 0.22:
            return Tool.COMMERCIAL
        if ind_count / t < 0.22:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Phase 2: extend wires from power sources (plant or existing wire)
    # Build a "power frontier" - tiles adjacent to power that are empty
    power_source = pm | wm
    # Look for empty tiles adjacent to power sources
    # Prefer extending toward zone clusters or road clusters
    # Wire plan: vertical spine at P1X from P1Y-12 to P1Y+12
    #            vertical spine at P2X from P2Y-12 to P2Y+12
    #            horizontal wire at y=P1Y-1 from P1X to P1X+1 (connect to road)
    # We extend one wire per step along planned paths

    # Define wire targets: vertical spines
    wire_targets = []
    for dy in range(-12, 13):
        wire_targets.append((P1X, P1Y + dy))
        wire_targets.append((P2X, P2Y + dy))
    # Horizontal wire connecting spines at mid-level
    mid_y_wire = P1Y - 1
    for x in range(P1X, P2X + 1):
        wire_targets.append((x, mid_y_wire))

    for (wx, wy) in wire_targets:
        if not in_bounds(wx, wy):
            continue
        if bool(wm[wy, wx]) or bool(pm[wy, wx]):
            continue
        # Only place wire if adjacent to existing power
        adj_power = False
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx2, ny2 = wx+ddx, wy+ddy
            if in_bounds(nx2, ny2) and (bool(pm[ny2, nx2]) or bool(wm[ny2, nx2])):
                adj_power = True
                break
        if adj_power and bool(em[wy, wx]):
            return (Tool.WIRE, wx, wy)

    # Phase 3: extend roads
    # Road plan: vertical roads at P1X+1 and P1X-1, P2X+1 and P2X-1
    #            horizontal roads at P1Y+3, P1Y-3, P2Y+3, P2Y-3
    #            highway connecting clusters at y=P1Y
    road_targets = []
    # Vertical roads flanking each cluster spine
    for dy in range(-12, 13):
        road_targets.append((P1X + 1, P1Y + dy))
        road_targets.append((P1X - 1, P1Y + dy))
        road_targets.append((P2X + 1, P2Y + dy))
        road_targets.append((P2X - 1, P2Y + dy))
    # Horizontal roads at offsets
    for offset in [-6, -3, 0, 3, 6]:
        for x in range(P1X - 12, P1X + 13):
            road_targets.append((x, P1Y + offset))
        for x in range(P2X - 12, P2X + 13):
            road_targets.append((x, P2Y + offset))
    # Highway connecting clusters
    hy = P1Y + 3
    for x in range(P1X + 2, P2X - 1):
        road_targets.append((x, hy))

    for (rx, ry) in road_targets:
        if not in_bounds(rx, ry):
            continue
        if bool(rm[ry, rx]):
            continue
        if bool(pm[ry, rx]) or bool(wm[ry, rx]):
            continue
        # Only place road if adjacent to existing road OR near plant
        adj_road = False
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx2, ny2 = rx+ddx, ry+ddy
            if in_bounds(nx2, ny2) and bool(rm[ny2, nx2]):
                adj_road = True
                break
        # Also allow starting road from plant adjacency
        adj_plant = False
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1),(2,0),(-2,0),(0,2),(0,-2)]:
            nx2, ny2 = rx+ddx, ry+ddy
            if in_bounds(nx2, ny2) and bool(pm[ny2, nx2]):
                adj_plant = True
                break
        if (adj_road or adj_plant) and bool(em[ry, rx]):
            return (Tool.ROAD, rx, ry)

    # Phase 4: place zones near roads AND wires
    # Build neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Zone must have 3x3 clear space
    zone_mask = resm | comm | indm
    cand = em & nbr_road & nbr_power
    # Exclude map edges
    cand[0:2, :] = False
    cand[WORLD_H-2:, :] = False
    cand[:, 0:2] = False
    cand[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        # Pick candidate - use step+pop for deterministic but varying selection
        key = int(obs.step * 17 + int(obs.city_pop * 3) + 1) % len(cxs)
        for offset in range(min(len(cxs), 80)):
            k = (key + offset * 11) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            # Check 3x3 clearance
            ok = True
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    ny2, nx2 = zy + dr, zx + dc
                    if not in_bounds(nx2, ny2):
                        ok = False; break
                    tile_ok = bool(em[ny2, nx2]) or bool(zone_mask[ny2, nx2])
                    if not tile_ok:
                        ok = False; break
                if not ok:
                    break
            if ok:
                return (pick_tool(), zx, zy)

    # Phase 5: services when population warrants
    if obs.city_pop > 200:
        for fx, fy in [(P1X + 3, P1Y - 10), (P2X - 3, P2Y + 10)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 300:
        for fx, fy in [(P1X + 3, P1Y + 10), (P2X - 3, P2Y - 10)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.POLICESTATION, fx, fy)

    # Fallback: extend road from existing road frontier
    rys, rxs = np.where(rm)
    if len(rxs) > 0:
        k2 = int(obs.step * 13) % len(rxs)
        rx2, ry2 = int(rxs[k2]), int(rys[k2])
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx2, ny2 = rx2+ddx, ry2+ddy
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire from existing wire frontier
    wys, wxs = np.where(wm)
    if len(wxs) > 0:
        k3 = int(obs.step * 7) % len(wxs)
        wx2, wy2 = int(wxs[k3]), int(wys[k3])
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx2, ny2 = wx2+ddx, wy2+ddy
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map each step and places next tile
    based on current state of the map. Uses a phase system but each
    phase decision is driven by what we actually observe.
    """
    tile_map = obs.tile_map
    step = obs.step

    # Helper: check if coords are valid
    def valid(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Helper: check if a tile is empty
    def is_empty(x, y):
        if not valid(x, y):
            return False
        return empty_mask[y, x]

    # Helper: check if powered (wire or plant nearby)
    def has_wire(x, y):
        if not valid(x, y):
            return False
        return wire_mask[y, x] or plant_mask[y, x]

    # Helper: check if road nearby
    def has_road_adj(x, y):
        for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
            nx, ny = x+dx, y+dy
            if valid(nx, ny) and road_mask[ny, nx]:
                return True
        return False

    # Helper: find frontier of wire network (empty tiles adjacent to wire)
    def wire_frontier():
        positions = []
        wy, wx = np.where(wire_mask | plant_mask)
        for i in range(len(wy)):
            y, x = int(wy[i]), int(wx[i])
            for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
                nx, ny = x+dx, y+dy
                if valid(nx, ny) and is_empty(nx, ny):
                    positions.append((nx, ny))
        return positions

    # Helper: find frontier of road network
    def road_frontier():
        positions = []
        ry, rx = np.where(road_mask)
        for i in range(len(ry)):
            y, x = int(ry[i]), int(rx[i])
            for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
                nx, ny = x+dx, y+dy
                if valid(nx, ny) and is_empty(nx, ny):
                    positions.append((nx, ny))
        return positions

    # Core layout parameters
    CX, CY = 60, 50  # center of city

    # Phase tracking
    if "phase" not in state:
        state["phase"] = 0
        state["sub"] = 0

    phase = state["phase"]
    sub = state["sub"]

    # Count existing infrastructure
    n_plants = int(np.sum(plant_mask))
    n_wires = int(np.sum(wire_mask))
    n_roads = int(np.sum(road_mask))
    n_res = int(np.sum(res_mask))
    n_com = int(np.sum(com_mask))
    n_ind = int(np.sum(ind_mask))
    n_zones = n_res + n_com + n_ind

    # PHASE 0: Place first coal power plant if none exists
    if n_plants == 0:
        # Place coal power plant at fixed position
        return (Tool.COALPOWER, CX - 10, CY)

    # PHASE 1: Build wire spine from plant toward center
    # Find plant location
    py, px = np.where(plant_mask)
    if len(px) > 0:
        px0, py0 = int(px[0]), int(py[0])
    else:
        px0, py0 = CX - 10, CY

    # Build horizontal wire from plant toward CX
    # Check if wire reaches CX
    wire_at_cx = any(wire_mask[CY, x] or plant_mask[CY, x] for x in range(px0, CX+1))

    if not wire_at_cx and n_wires < 25:
        # Extend wire rightward from plant
        for x in range(px0 + 2, CX + 5):
            if valid(x, CY) and is_empty(x, CY):
                return (Tool.WIRE, x, CY)
        # If no empty, try next to existing wire
        frontier = wire_frontier()
        # Filter to rightward direction toward CX
        rightward = [(x, y) for x, y in frontier if x <= CX + 5 and x >= px0]
        if rightward:
            rightward.sort(key=lambda p: abs(p[0] - CX) + abs(p[1] - CY))
            return (Tool.WIRE, rightward[0][0], rightward[0][1])

    # PHASE 2: Build vertical wire spine at CX
    # Check vertical wire coverage
    wire_col_y = [y for y in range(CY-15, CY+16) if valid(CX, y) and (wire_mask[y, CX] or plant_mask[y, CX])]
    if len(wire_col_y) < 20:
        # Find the gap in vertical wire at CX
        for y in range(CY-15, CY+16):
            if valid(CX, y) and is_empty(CX, y):
                return (Tool.WIRE, CX, y)
        # Try extending from existing wire
        frontier = wire_frontier()
        col_frontier = [(x, y) for x, y in frontier if abs(x - CX) <= 1 and CY-15 <= y <= CY+15]
        if col_frontier:
            col_frontier.sort(key=lambda p: abs(p[1] - CY))
            return (Tool.WIRE, col_frontier[0][0], col_frontier[0][1])

    # PHASE 3: Build road parallel to wire spine (at CX+1)
    road_col_y = [y for y in range(CY-15, CY+16) if valid(CX+1, y) and road_mask[y, CX+1]]
    if len(road_col_y) < 20:
        for y in range(CY-15, CY+16):
            if valid(CX+1, y) and is_empty(CX+1, y):
                return (Tool.ROAD, CX+1, y)

    # PHASE 4: Build horizontal roads branching off the spine
    # Every 3 rows, place a horizontal road segment
    for row_offset in range(-12, 13, 3):
        ry = CY + row_offset
        if not valid(CX+1, ry):
            continue
        # Check if we have a horizontal road at this row going right
        road_count_right = sum(1 for x in range(CX+1, CX+9) if valid(x, ry) and road_mask[ry, x])
        if road_count_right < 6:
            for x in range(CX+2, CX+9):
                if valid(x, ry) and is_empty(x, ry):
                    return (Tool.ROAD, x, ry)
        # And going left
        road_count_left = sum(1 for x in range(CX-8, CX) if valid(x, ry) and road_mask[ry, x])
        if road_count_left < 6:
            for x in range(CX, CX-8, -1):
                if valid(x, ry) and is_empty(x, ry):
                    return (Tool.ROAD, x, ry)

    # PHASE 5: Place zones adjacent to roads and wires
    # Find tiles that have road access and wire access nearby
    # and place zones there

    # Look for good zone spots: 3x3 centered at (x,y) needs road adj and wire nearby
    def zone_score(x, y, tool):
        """Score a potential zone placement"""
        if not valid(x, y) or not is_empty(x, y):
            return -1
        # Check for road within 2 tiles
        road_near = False
        wire_near = False
        for dx in range(-2, 3):
            for dy in range(-2, 3):
                nx, ny = x+dx, y+dy
                if valid(nx, ny):
                    if road_mask[ny, nx]:
                        road_near = True
                    if wire_mask[ny, nx] or plant_mask[ny, nx]:
                        wire_near = True
        if not road_near or not wire_near:
            return -1
        return 1

    # Determine what zone type to place based on current balance
    # Want roughly 50% res, 25% com, 25% ind
    if n_res < n_com + n_ind:
        next_zone = Tool.RESIDENTIAL
    elif n_com <= n_ind:
        next_zone = Tool.COMMERCIAL
    else:
        next_zone = Tool.INDUSTRIAL

    # Scan around road network for zone placement
    best_zone_pos = None
    best_dist = 9999

    # Sample positions around the spine
    for row_offset in range(-12, 13, 3):
        zy = CY + row_offset
        # Right side zones
        for zx in [CX+3, CX+6]:
            if zone_score(zx, zy, next_zone) > 0:
                dist = abs(zx - CX) + abs(zy - CY)
                if dist < best_dist:
                    best_dist = dist
                    best_zone_pos = (zx, zy)
        # Left side zones
        for zx in [CX-3, CX-6]:
            if zone_score(zx, zy, next_zone) > 0:
                dist = abs(zx - CX) + abs(zy - CY)
                if dist < best_dist:
                    best_dist = dist
                    best_zone_pos = (zx, zy)

    if best_zone_pos is not None:
        return (next_zone, best_zone_pos[0], best_zone_pos[1])

    # PHASE 6: Extend infrastructure if we still have steps
    # Add second power plant if population is growing but zones aren't powered
    if obs.city_pop > 200 and n_plants < 2:
        # Place second plant on right side
        return (Tool.COALPOWER, CX + 15, CY)

    # Extend wire to cover more zones if needed
    if obs.powered_zones < n_zones * 0.7:
        # Extend wire spine
        frontier = wire_frontier()
        if frontier:
            # Find frontier closest to unpowered zones
            # Simple: extend toward center of gravity of zones
            res_y, res_x = np.where(res_mask)
            if len(res_x) > 0:
                target_x = int(np.mean(res_x))
                target_y = int(np.mean(res_y))
                frontier.sort(key=lambda p: abs(p[0]-target_x) + abs(p[1]-target_y))
                return (Tool.WIRE, frontier[0][0], frontier[0][1])
            frontier.sort(key=lambda p: abs(p[0]-CX) + abs(p[1]-CY))
            return (Tool.WIRE, frontier[0][0], frontier[0][1])

    # Extend roads to reach more potential zone spots
    road_frontier_pts = road_frontier()
    if road_frontier_pts:
        # Prefer extending toward unserved areas
        road_frontier_pts.sort(key=lambda p: abs(p[0]-CX) + abs(p[1]-CY))
        # Pick one that's not too far
        for rx, ry in road_frontier_pts[:5]:
            if abs(rx - CX) < 20 and abs(ry - CY) < 20:
                return (Tool.ROAD, rx, ry)

    # Add services if city has population
    if obs.city_pop > 100 and n_zones > 5:
        # Check if fire station exists (not in standard masks, use tile_map)
        # Place fire station near center
        fs_x, fs_y = CX - 5, CY - 18
        if valid(fs_x, fs_y):
            t = tile_map[fs_y, fs_x]
            # Simple check: if it looks empty-ish
            if is_empty(fs_x, fs_y):
                return (Tool.FIRESTATION, fs_x, fs_y)

    # Place more zones in wider area
    for row_offset in range(-15, 16, 3):
        zy = CY + row_offset
        for zx in range(CX-12, CX+13, 3):
            if zone_score(zx, zy, next_zone) > 0:
                return (next_zone, zx, zy)

    # Fallback: extend wire and road further out
    frontier = wire_frontier()
    if frontier:
        frontier.sort(key=lambda p: abs(p[0]-CX) + abs(p[1]-CY))
        if frontier[0][0] != CX or True:
            return (Tool.WIRE, frontier[0][0], frontier[0][1])

    return None

def act(obs, state):
    """
    Improved policy with a horizontal road/wire spine and zones on both sides.
    Strategy:
    - Place TWO coal power plants for more coverage
    - Build a horizontal wire spine across the map center
    - Build horizontal roads above and below the wire spine
    - Place zones in a grid pattern above and below roads
    - Better mix of R/C/I zones
    """
    tm = obs.tile_map
    step = obs.step

    # Use a fixed center but offset to leave room for expansion
    cx, cy = WORLD_W // 2, WORLD_H // 2

    em = empty_mask(tm)
    rm = road_mask(tm)
    wm = wire_mask(tm)
    pm = plant_mask(tm)

    has_plant = np.any(pm)
    plant_positions = list(zip(*np.where(pm)))

    # Helper: check if a 3x3 zone area is placeable
    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    # Phase 1: Place two coal power plants
    plant1_x, plant1_y = cx - 30, cy
    plant2_x, plant2_y = cx + 20, cy

    if not has_plant:
        return (Tool.COALPOWER, plant1_x, plant1_y)

    # Count plants
    plant_count = len(plant_positions)

    # Check if second plant exists (near plant2 location)
    has_plant2 = any(abs(r - plant2_y) <= 2 and abs(c - plant2_x) <= 2
                     for (r, c) in plant_positions)

    if not has_plant2 and plant_count < 9:
        # place second plant (needs 9 tiles for 3x3)
        # Check if enough steps remain and we have enough infra
        if step > 20:
            return (Tool.COALPOWER, plant2_x, plant2_y)

    # Phase 2: Build horizontal wire spine at cy
    # Wire from plant1 right edge to plant2 left edge
    wire_row = cy
    # Wire should cover from plant1_x+2 to plant2_x-2
    wire_start = plant1_x + 3  # just right of plant1
    wire_end = plant2_x - 3    # just left of plant2

    # Find current wire extent on wire_row
    wire_row_cols = sorted([c for (r, c) in zip(*np.where(wm)) if r == wire_row]) if np.any(wm) else []

    if not wire_row_cols:
        # Start wire adjacent to plant1 right side
        start_c = plant1_x + 3
        if 0 <= start_c < WORLD_W:
            if em[wire_row, start_c] or wm[wire_row, start_c]:
                return (Tool.WIRE, start_c, wire_row)
    else:
        max_c = max(wire_row_cols)
        min_c = min(wire_row_cols)
        # Extend rightward first
        if max_c < wire_end and max_c + 1 < WORLD_W:
            nc = max_c + 1
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)
        # Extend leftward
        if min_c > wire_start and min_c - 1 >= 0:
            nc = min_c - 1
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # Phase 3: Build horizontal roads above and below the wire spine
    road_row_above = cy - 3
    road_row_below = cy + 3

    # Road coverage: from wire_start to wire_end
    for road_row in [road_row_above, road_row_below]:
        if 0 <= road_row < WORLD_H:
            road_row_cols = sorted([c for (r, c) in zip(*np.where(rm)) if r == road_row]) if np.any(rm) else []
            if not road_row_cols:
                # Start road at wire_start
                sc = wire_start
                if 0 <= sc < WORLD_W and (em[road_row, sc] or rm[road_row, sc]):
                    return (Tool.ROAD, sc, road_row)
            else:
                max_c = max(road_row_cols)
                min_c = min(road_row_cols)
                if max_c < wire_end and max_c + 1 < WORLD_W:
                    nc = max_c + 1
                    if em[road_row, nc] or rm[road_row, nc]:
                        return (Tool.ROAD, nc, road_row)
                if min_c > wire_start and min_c - 1 >= 0:
                    nc = min_c - 1
                    if em[road_row, nc] or rm[road_row, nc]:
                        return (Tool.ROAD, nc, road_row)

    # Phase 4: Add vertical connecting roads (every 6 cols) between road rows
    if np.any(rm):
        road_above_cols = sorted([c for (r, c) in zip(*np.where(rm)) if r == road_row_above])
        road_below_cols = sorted([c for (r, c) in zip(*np.where(rm)) if r == road_row_below])
        for col in range(wire_start, wire_end + 1, 6):
            if col in road_above_cols and col in road_below_cols:
                # Connect vertically
                for r in range(road_row_above + 1, road_row_below):
                    if 0 <= r < WORLD_H and em[r, col]:
                        return (Tool.ROAD, col, r)

    # Phase 5: Add vertical wire connections to reach zones far from spine
    # Wire columns every 6 cols from spine up/down to reach zones
    if np.any(wm):
        wire_row_cols_cur = sorted([c for (r, c) in zip(*np.where(wm)) if r == wire_row])
        for col in range(wire_start, wire_end + 1, 6):
            if col in wire_row_cols_cur:
                # Extend wire up and down to cy-6 and cy+6
                for target_r in range(wire_row - 1, cy - 7, -1):
                    if 0 <= target_r < WORLD_H and em[target_r, col]:
                        return (Tool.WIRE, col, target_r)
                for target_r in range(wire_row + 1, cy + 7):
                    if 0 <= target_r < WORLD_H and em[target_r, col]:
                        return (Tool.WIRE, col, target_r)

    # Phase 6: Place zones in grid above road_row_above and below road_row_below
    res_pos = list(zip(*np.where(res_mask(tm)))) if np.any(res_mask(tm)) else []
    com_pos = list(zip(*np.where(com_mask(tm)))) if np.any(com_mask(tm)) else []
    ind_pos = list(zip(*np.where(ind_mask(tm)))) if np.any(ind_mask(tm)) else []

    res_count = len(res_pos)
    com_count = len(com_pos)
    ind_count = len(ind_pos)

    # Zone placement grid: above road = rows cy-6, cy-9, cy-12; below = cy+6, cy+9, cy+12
    zone_rows_above = [road_row_above - 3, road_row_above - 6, road_row_above - 9]
    zone_rows_below = [road_row_below + 3, road_row_below + 6, road_row_below + 9]
    zone_cols = list(range(wire_start + 3, wire_end - 2, 6))

    def near_road(zr, zc):
        for dr in range(-3, 4):
            for dc in range(-3, 4):
                r2, c2 = zr + dr, zc + dc
                if 0 <= r2 < WORLD_H and 0 <= c2 < WORLD_W:
                    if rm[r2, c2]:
                        return True
        return False

    def near_wire(zr, zc):
        for dr in range(-4, 5):
            for dc in range(-4, 5):
                r2, c2 = zr + dr, zc + dc
                if 0 <= r2 < WORLD_H and 0 <= c2 < WORLD_W:
                    if wm[r2, c2] or pm[r2, c2]:
                        return True
        return False

    for zr in zone_rows_above + zone_rows_below:
        for zc in zone_cols:
            if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                already = any(abs(zr - pr) <= 1 and abs(zc - pc) <= 1
                              for (pr, pc) in res_pos + com_pos + ind_pos)
                if not already and zone_area_free(zr, zc):
                    if near_road(zr, zc) and near_wire(zr, zc):
                        # Decide zone type: 50% res, 25% com, 25% ind
                        total = res_count + com_count + ind_count
                        if com_count < total * 0.25 or (com_count < res_count // 3):
                            return (Tool.COMMERCIAL, zc, zr)
                        elif ind_count < total * 0.25 or (ind_count < res_count // 3):
                            return (Tool.INDUSTRIAL, zc, zr)
                        else:
                            return (Tool.RESIDENTIAL, zc, zr)

    # Phase 7: Extend zone coverage further if population growing
    if obs.city_pop > 300:
        extra_rows = [road_row_above - 12, road_row_above - 15,
                      road_row_below + 12, road_row_below + 15]
        for zr in extra_rows:
            for zc in zone_cols:
                if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                    already = any(abs(zr - pr) <= 1 and abs(zc - pc) <= 1
                                  for (pr, pc) in res_pos + com_pos + ind_pos)
                    if not already and zone_area_free(zr, zc):
                        return (Tool.RESIDENTIAL, zc, zr)

    # Phase 8: Add a second horizontal road further out if population high
    if obs.city_pop > 500:
        for road_row in [cy - 9, cy + 9]:
            if 0 <= road_row < WORLD_H:
                road_row_cols = [c for (r, c) in zip(*np.where(rm)) if r == road_row] if np.any(rm) else []
                if len(road_row_cols) < wire_end - wire_start:
                    for col in range(wire_start, wire_end + 1):
                        if em[road_row, col]:
                            return (Tool.ROAD, col, road_row)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map each step and places the next tile
    based on what already exists. No precomputed plan.

    Strategy:
    1. Place coal power plant if none exists
    2. Extend wires from plant outward to build a power spine
    3. Build roads adjacent to wire spine
    4. Place zones (res/com/ind) adjacent to roads and near wires
    5. Add second plant if needed, expand iteratively
    """
    tm = obs.tile_map
    step = obs.step

    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    has_plant = np.any(pm)
    has_wire = np.any(wm)
    has_road = np.any(rm)

    n_res = int(res_m.sum())
    n_com = int(com_m.sum())
    n_ind = int(ind_m.sum())
    n_zones = n_res + n_com + n_ind

    cx, cy = WORLD_W // 2, WORLD_H // 2

    # --- Phase 1: Ensure we have a power plant ---
    if not has_plant:
        # Place first coal plant at center-left
        return (Tool.COALPOWER, cx - 15, cy)

    # Find plant center(s)
    plant_ys, plant_xs = np.where(pm)

    # --- Phase 2: Extend wire spine horizontally from plant ---
    # Wire row = same row as first plant
    wire_row = int(plant_ys[0])
    # Clamp wire_row to valid zone range
    wire_row = max(3, min(WORLD_H - 4, wire_row))

    wire_in_row = [(int(r), int(c)) for (r, c) in zip(*np.where(wm)) if r == wire_row]
    wire_cols_in_row = sorted([c for (r, c) in wire_in_row])

    # Build wire from plant rightward/leftward
    if not wire_cols_in_row:
        # Start wire adjacent to plant
        # Find rightmost plant tile in plant row
        plant_cols_in_row = [int(c) for (r, c) in zip(plant_ys, plant_xs) if r == wire_row]
        if plant_cols_in_row:
            start_c = max(plant_cols_in_row) + 1
        else:
            start_c = int(plant_xs[0]) + 2
        start_c = max(0, min(WORLD_W - 1, start_c))
        if em[wire_row, start_c]:
            return (Tool.WIRE, start_c, wire_row)
        else:
            # Try left side of plant
            plant_cols_in_row2 = [int(c) for (r, c) in zip(plant_ys, plant_xs) if r == wire_row]
            if plant_cols_in_row2:
                sc2 = min(plant_cols_in_row2) - 1
                if 0 <= sc2 < WORLD_W and em[wire_row, sc2]:
                    return (Tool.WIRE, sc2, wire_row)
    else:
        max_wc = max(wire_cols_in_row)
        min_wc = min(wire_cols_in_row)
        # Extend rightward up to cx+30
        target_right = min(cx + 35, WORLD_W - 4)
        target_left = max(cx - 35, 3)

        if max_wc < target_right:
            nc = max_wc + 1
            if em[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)
        if min_wc > target_left:
            nc = min_wc - 1
            if em[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # --- Phase 2b: Add second power plant if wire is long enough and pop is stagnant ---
    plant_count = len(set(zip(plant_ys.tolist(), plant_xs.tolist())))
    # Count distinct plant clusters
    if wire_cols_in_row and len(wire_cols_in_row) > 20:
        # Check if we have plant near right side
        right_plant = any(int(px) > cx + 5 for px in plant_xs)
        if not right_plant and (obs.city_pop < 50 or step > obs.n_steps // 3):
            # Place second plant on the right, adjacent to wire
            p2x = min(cx + 20, WORLD_W - 5)
            p2y = wire_row
            # Check if area is roughly clear
            if all(em[p2y + dy, p2x + dx] for dy in range(-2, 3) for dx in range(-2, 3)
                   if 0 <= p2y + dy < WORLD_H and 0 <= p2x + dx < WORLD_W):
                return (Tool.COALPOWER, p2x, p2y)

    # --- Phase 3: Build roads adjacent to wire spine ---
    # Road rows: wire_row + 2 and wire_row - 2
    road_row_down = wire_row + 2
    road_row_up = wire_row - 2

    # Extend road on down row
    if wire_cols_in_row:
        road_start = min(wire_cols_in_row) - 1
        road_end = max(wire_cols_in_row) + 1
        road_start = max(3, road_start)
        road_end = min(WORLD_W - 4, road_end)

        # Road row down
        if 3 <= road_row_down <= WORLD_H - 4:
            road_in_down = sorted([int(c) for (r, c) in zip(*np.where(rm)) if r == road_row_down])
            if not road_in_down:
                if em[road_row_down, road_start] or not em[road_row_down, road_start]:
                    return (Tool.ROAD, road_start, road_row_down)
            else:
                mrd = max(road_in_down)
                if mrd < road_end:
                    return (Tool.ROAD, mrd + 1, road_row_down)
                mrd_min = min(road_in_down)
                if mrd_min > road_start:
                    return (Tool.ROAD, mrd_min - 1, road_row_down)

        # Road row up
        if 3 <= road_row_up <= WORLD_H - 4:
            road_in_up = sorted([int(c) for (r, c) in zip(*np.where(rm)) if r == road_row_up])
            if not road_in_up:
                return (Tool.ROAD, road_start, road_row_up)
            else:
                mru = max(road_in_up)
                if mru < road_end:
                    return (Tool.ROAD, mru + 1, road_row_up)
                mru_min = min(road_in_up)
                if mru_min > road_start:
                    return (Tool.ROAD, mru_min - 1, road_row_up)

    # --- Phase 4: Place zones adjacent to roads, near wires ---
    # Find road tiles
    road_ys, road_xs = np.where(rm)
    if len(road_xs) == 0:
        return None

    # Determine next zone type to maintain 3:1:1 res:com:ind ratio
    if n_com * 3 < n_res + 1:
        next_tool = Tool.COMMERCIAL
    elif n_ind * 3 < n_res + 1:
        next_tool = Tool.INDUSTRIAL
    else:
        next_tool = Tool.RESIDENTIAL

    # Find candidate zone centers: 3 tiles away from road (zone is 3x3, center at distance 2-3)
    # For each road tile, look 3 rows above/below for zone center
    # Zone center must have 3x3 clear area and be near wire

    def is_clear_3x3(cr, cc):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def near_wire(cr, cc, dist=4):
        # Check if any wire within dist tiles
        r0, r1 = max(0, cr - dist), min(WORLD_H, cr + dist + 1)
        c0, c1 = max(0, cc - dist), min(WORLD_W, cc + dist + 1)
        return np.any(wm[r0:r1, c0:c1])

    def near_road(cr, cc, dist=3):
        r0, r1 = max(0, cr - dist), min(WORLD_H, cr + dist + 1)
        c0, c1 = max(0, cc - dist), min(WORLD_W, cc + dist + 1)
        return np.any(rm[r0:r1, c0:c1])

    # Scan road tiles and try to place zones nearby
    # Use step as a pseudo-random offset to avoid always picking same spot
    n_road = len(road_xs)
    offset = step % max(1, n_road)

    for i in range(n_road):
        idx = (i + offset) % n_road
        ry, rx = int(road_ys[idx]), int(road_xs[idx])

        # Try zone centers at ry +/- 3 (adjacent to road)
        for zr in [ry - 3, ry + 3, ry - 6, ry + 6]:
            if not (2 <= zr <= WORLD_H - 3):
                continue
            # Try zone cols spread along road
            for dc in range(-1, 2):
                zc = rx + dc * 3
                if not (2 <= zc <= WORLD_W - 3):
                    continue
                if not near_wire(zr, zc, 5):
                    continue
                if not near_road(zr, zc, 3):
                    continue
                if is_clear_3x3(zr, zc):
                    return (next_tool, zc, zr)

    # --- Phase 5: Add vertical wire branches to reach isolated areas ---
    if wire_cols_in_row and n_zones > 5:
        # Try extending wire vertically from spine
        mid_wc = wire_cols_in_row[len(wire_cols_in_row) // 2]
        for dr in [1, -1, 2, -2, 3, -3]:
            nr = wire_row + dr
            if 0 <= nr < WORLD_H and em[nr, mid_wc]:
                # Only add if not already wired
                if not wm[nr, mid_wc]:
                    return (Tool.WIRE, mid_wc, nr)

    # --- Phase 6: Add services if pop growing ---
    if obs.city_pop > 200 and step % 40 == 0:
        for sy, sx in [(cy - 10, cx), (cy + 10, cx), (cy, cx - 15), (cy, cx + 15)]:
            sy, sx = max(1, min(WORLD_H - 2, sy)), max(1, min(WORLD_W - 2, sx))
            if em[sy, sx]:
                if step % 80 < 40:
                    return (Tool.POLICESTATION, sx, sy)
                else:
                    return (Tool.FIRESTATION, sx, sy)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map every step to decide next action
    - Places power plant, then grows wire spine from actual wire endpoints
    - Grows road column adjacent to wire spine
    - Places zones where both wire and road are nearby
    - Expands spine and zones based on observed map state
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    all_zone_mask = resm | comm | indm

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def wire_near(r, c, rad=4):
        r0 = max(0, r - rad); r1 = min(WORLD_H, r + rad + 1)
        c0 = max(0, c - rad); c1 = min(WORLD_W, c + rad + 1)
        return bool(np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1]))

    def road_near(r, c, rad=4):
        r0 = max(0, r - rad); r1 = min(WORLD_H, r + rad + 1)
        c0 = max(0, c - rad); c1 = min(WORLD_W, c + rad + 1)
        return bool(np.any(rm[r0:r1, c0:c1]))

    # Step 1: Place coal power plant if none exists
    if not np.any(pm):
        return (Tool.COALPOWER, cx - 10, cy)

    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Fixed layout columns relative to plant
    wire_col = plant_cx + 4
    road_col = wire_col + 2
    left_zc = wire_col - 3
    right_zc = road_col + 3

    wire_col = max(2, min(WORLD_W - 3, wire_col))
    road_col = max(2, min(WORLD_W - 3, road_col))
    left_zc = max(2, min(WORLD_W - 3, left_zc))
    right_zc = max(2, min(WORLD_W - 3, right_zc))

    # Dynamic spine extent based on population
    pop = obs.city_pop
    if pop < 50:
        spine_ext = 8
    elif pop < 150:
        spine_ext = 14
    elif pop < 300:
        spine_ext = 20
    elif pop < 500:
        spine_ext = 28
    else:
        spine_ext = 36

    t_min = max(1, cy - spine_ext)
    t_max = min(WORLD_H - 2, cy + spine_ext)

    # Read actual wire spine state
    wire_rows = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])
    road_rows = set(r for r in range(WORLD_H) if rm[r, road_col])

    # Step 2: Start wire spine adjacent to plant if none on wire_col
    if not wire_rows:
        # Find a row near plant_cy that is empty on wire_col
        for dy in range(0, 8):
            for nr in [plant_cy + dy, plant_cy - dy]:
                if 0 <= nr < WORLD_H:
                    if em[nr, wire_col] or wm[nr, wire_col]:
                        return (Tool.WIRE, wire_col, nr)
        return None

    min_wr = min(wire_rows)
    max_wr = max(wire_rows)

    # Step 3: Extend wire spine downward to target
    if max_wr < t_max:
        nr = max_wr + 1
        if nr < WORLD_H and not pm[nr, wire_col] and em[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)

    # Step 4: Extend wire spine upward to target
    if min_wr > t_min:
        nr = min_wr - 1
        if nr >= 0 and not pm[nr, wire_col] and em[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)

    # Step 5: Build road column along wire rows
    for r in wire_rows:
        if r not in road_rows and em[r, road_col]:
            return (Tool.ROAD, road_col, r)

    # Step 6: Lateral wires to left zone column
    for wr in wire_rows:
        for wc in range(wire_col - 1, max(left_zc - 2, 0), -1):
            if wm[wr, wc]:
                break
            if em[wr, wc] and not pm[wr, wc]:
                return (Tool.WIRE, wc, wr)
            elif not em[wr, wc]:
                break

    # Step 7: Place zones along both columns where wire+road reachable
    zone_rows_list = list(range(max(1, t_min), min(WORLD_H - 1, t_max + 1), 3))

    for zr in zone_rows_list:
        w_near = any(abs(zr - wr) <= 2 for wr in wire_rows)
        r_near = any(abs(zr - rr) <= 2 for rr in road_rows)

        if w_near and r_near:
            # Try left column first
            if not zone_already_there(zr, left_zc) and zone_area_ok(zr, left_zc):
                if wire_near(zr, left_zc, 5) and road_near(zr, left_zc, 5):
                    return (pick_tool(), left_zc, zr)
            # Try right column
            if not zone_already_there(zr, right_zc) and zone_area_ok(zr, right_zc):
                if wire_near(zr, right_zc, 6) and road_near(zr, right_zc, 5):
                    return (pick_tool(), right_zc, zr)

    # Step 8: Road extensions to right zone column
    for wr in wire_rows:
        if wr not in road_rows:
            continue
        for rc in range(road_col + 1, right_zc + 2):
            if 0 <= rc < WORLD_W:
                if rm[wr, rc]:
                    break
                if em[wr, rc] and not pm[wr, rc]:
                    return (Tool.ROAD, rc, wr)
                elif not em[wr, rc]:
                    break

    # Step 9: Wire extensions toward right zone for power
    for wr in wire_rows:
        for wc in range(wire_col + 1, right_zc + 2):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc] and not rm[wr, wc]:
                    break

    # Step 10: Second power plant when population grows
    if pop > 300 and int(np.sum(pm)) < 9:
        px2 = plant_cx + 18
        py2 = plant_cy
        if 2 <= py2 <= WORLD_H - 3 and 2 <= px2 <= WORLD_W - 3:
            area_ok = all(
                em[py2 + dr, px2 + dc] or pm[py2 + dr, px2 + dc]
                for dr in [-1, 0, 1] for dc in [-1, 0, 1]
            )
            if area_ok:
                return (Tool.COALPOWER, px2, py2)

    # Step 11: Second cluster (right side) when population >= 150
    if pop >= 150:
        wc2 = road_col + 10
        rc2 = wc2 + 2
        lzc2 = wc2 - 3
        rzc2 = rc2 + 3
        wc2 = max(2, min(WORLD_W - 3, wc2))
        rc2 = max(2, min(WORLD_W - 3, rc2))
        lzc2 = max(2, min(WORLD_W - 3, lzc2))
        rzc2 = max(2, min(WORLD_W - 3, rzc2))

        wr2 = sorted([r for r in range(WORLD_H) if wm[r, wc2]])
        rr2 = set(r for r in range(WORLD_H) if rm[r, rc2])

        if not wr2:
            # Build horizontal wire bridge from main spine row to cluster2
            bridge_row = plant_cy
            for wc in range(wire_col + 1, wc2 + 1):
                if 0 <= wc < WORLD_W:
                    if wm[bridge_row, wc]:
                        continue
                    if em[bridge_row, wc] and not pm[bridge_row, wc]:
                        return (Tool.WIRE, wc, bridge_row)
                    elif not em[bridge_row, wc] and not wm[bridge_row, wc]:
                        break
        else:
            mnwr2 = min(wr2); mxwr2 = max(wr2)
            if mxwr2 < t_max:
                nr = mxwr2 + 1
                if nr < WORLD_H and em[nr, wc2]:
                    return (Tool.WIRE, wc2, nr)
            if mnwr2 > t_min:
                nr = mnwr2 - 1
                if nr >= 0 and em[nr, wc2]:
                    return (Tool.WIRE, wc2, nr)

            for wr in wr2:
                if wr not in rr2 and em[wr, rc2]:
                    return (Tool.ROAD, rc2, wr)

            for zr in zone_rows_list:
                wn2 = any(abs(zr - w) <= 2 for w in wr2)
                rn2 = any(abs(zr - r) <= 2 for r in rr2)
                if wn2 and rn2:
                    for zc in [lzc2, rzc2]:
                        if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                            if wire_near(zr, zc, 6) and road_near(zr, zc, 5):
                                return (pick_tool(), zc, zr)

            for wr in wr2:
                for wc in range(wc2 - 1, max(lzc2 - 2, 0), -1):
                    if wm[wr, wc]: break
                    if em[wr, wc] and not pm[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    elif not em[wr, wc]: break

            for wr in wr2:
                if wr not in rr2: continue
                for rc in range(rc2 + 1, rzc2 + 2):
                    if 0 <= rc < WORLD_W:
                        if rm[wr, rc]: break
                        if em[wr, rc] and not pm[wr, rc]:
                            return (Tool.ROAD, rc, wr)
                        elif not em[wr, rc]: break

    # Step 12: Left cluster when pop >= 350
    if pop >= 350:
        wc3 = wire_col - 10
        rc3 = wc3 - 2
        lzc3 = rc3 - 3
        rzc3 = wc3 + 3
        wc3 = max(2, min(WORLD_W - 3, wc3))
        rc3 = max(2, min(WORLD_W - 3, rc3))
        lzc3 = max(2, min(WORLD_W - 3, lzc3))
        rzc3 = max(2, min(WORLD_W - 3, rzc3))

        wr3 = sorted([r for r in range(WORLD_H) if wm[r, wc3]])
        rr3 = set(r for r in range(WORLD_H) if rm[r, rc3])

        if not wr3:
            bridge_row = plant_cy
            for wc in range(wire_col - 1, wc3 - 1, -1):
                if 0 <= wc < WORLD_W:
                    if wm[bridge_row, wc]:
                        continue
                    if em[bridge_row, wc] and not pm[bridge_row, wc]:
                        return (Tool.WIRE, wc, bridge_row)
                    elif not em[bridge_row, wc] and not wm[bridge_row, wc]:
                        break
        else:
            mnwr3 = min(wr3); mxwr3 = max(wr3)
            if mxwr3 < t_max:
                nr = mxwr3 + 1
                if nr < WORLD_H and em[nr, wc3]:
                    return (Tool.WIRE, wc3, nr)
            if mnwr3 > t_min:
                nr = mnwr3 - 1
                if nr >= 0 and em[nr, wc3]:
                    return (Tool.WIRE, wc3, nr)

            for wr in wr3:
                if wr not in rr3 and em[wr, rc3]:
                    return (Tool.ROAD, rc3, wr)

            for zr in zone_rows_list:
                wn3 = any(abs(zr - w) <= 2 for w in wr3)
                rn3 = any(abs(zr - r) <= 2 for r in rr3)
                if wn3 and rn3:
                    for zc in [lzc3, rzc3]:
                        if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                            if wire_near(zr, zc, 6) and road_near(zr, zc, 5):
                                return (pick_tool(), zc, zr)

            for wr in wr3:
                for wc in range(wc3 + 1, min(rzc3 + 2, WORLD_W)):
                    if wm[wr, wc]: break
                    if em[wr, wc] and not pm[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    elif not em[wr, wc]: break

            for wr in wr3:
                if wr not in rr3: continue
                for rc in range(rc3 - 1, max(lzc3 - 2, 0), -1):
                    if 0 <= rc < WORLD_W:
                        if rm[wr, rc]: break
                        if em[wr, rc] and not pm[wr, rc]:
                            return (Tool.ROAD, rc, wr)
                        elif not em[wr, rc]: break

    # Step 13: Extra zone placements near existing infrastructure
    if pop > 200:
        extra_cols = [left_zc - 5, right_zc + 5]
        for zc in extra_cols:
            if 2 <= zc <= WORLD_W - 3:
                for zr in zone_rows_list:
                    if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                        if road_near(zr, zc, 6) and wire_near(zr, zc, 7):
                            return (pick_tool(), zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map each step to decide next action
    - Builds power plant, then extends wires, roads, and zones
    - Two neighborhoods (left ~x=35, right ~x=85) with middle connection
    - Fully reactive: each step checks current map state
    """
    tm = obs.tile_map
    step = obs.step

    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # Key layout parameters
    lx, ly = 35, 50   # left neighborhood center
    rx, ry = 85, 50   # right neighborhood center
    mx = 60            # middle x

    # Helper: check if a 3x3 zone area is placeable (mostly empty, within bounds)
    def zone_placeable(cx, cy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cy + dr, cx + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                # Allow empty or same-type zones (auto-bulldoze handles it)
                # But don't overwrite roads, wires, or plants
                tid = tm[rr, rc]
                if rm[rr, rc] or wm[rr, rc] or pm[rr, rc]:
                    return False
        return True

    def place_if_empty(tool, x, y):
        if 0 <= x < WORLD_W and 0 <= y < WORLD_H and em[y, x]:
            return (tool, x, y)
        return None

    def place_wire(x, y):
        if 0 <= x < WORLD_W and 0 <= y < WORLD_H and (em[y, x] or (not pm[y, x] and not rm[y, x])):
            if not wm[y, x]:
                return (Tool.WIRE, x, y)
        return None

    def place_road(x, y):
        if 0 <= x < WORLD_W and 0 <= y < WORLD_H and em[y, x]:
            return (Tool.ROAD, x, y)
        return None

    # ----------------------------------------------------------------
    # PHASE 1: Ensure left power plant exists
    # Plant is 3x3 centered at (lx-8, ly)
    left_plant_area = any(pm[ly + dr, lx - 8 + dc]
                          for dr in [-1, 0, 1] for dc in [-1, 0, 1]
                          if 0 <= ly + dr < WORLD_H and 0 <= lx - 8 + dc < WORLD_W)
    if not left_plant_area:
        return (Tool.COALPOWER, lx - 8, ly)

    # ----------------------------------------------------------------
    # PHASE 2: Ensure right power plant exists
    right_plant_area = any(pm[ry + dr, rx + 8 + dc]
                           for dr in [-1, 0, 1] for dc in [-1, 0, 1]
                           if 0 <= ry + dr < WORLD_H and 0 <= rx + 8 + dc < WORLD_W)
    if not right_plant_area:
        return (Tool.COALPOWER, rx + 8, ry)

    # ----------------------------------------------------------------
    # PHASE 3: Extend wire from left plant to left spine (lx, ly)
    # Wire from lx-7 to lx along ly
    for wx in range(lx - 7, lx + 1):
        if 0 <= wx < WORLD_W and not wm[ly, wx] and em[ly, wx]:
            return (Tool.WIRE, wx, ly)

    # ----------------------------------------------------------------
    # PHASE 4: Extend left vertical wire spine at lx, from ly-12 to ly+12
    target_rows = range(max(0, ly - 12), min(WORLD_H, ly + 13))
    for wr in target_rows:
        if not wm[wr, lx] and em[wr, lx]:
            return (Tool.WIRE, lx, wr)

    # ----------------------------------------------------------------
    # PHASE 5: Extend left vertical road spine at lx+1
    for wr in target_rows:
        if not rm[wr, lx + 1] and em[wr, lx + 1]:
            return (Tool.ROAD, lx + 1, wr)

    # ----------------------------------------------------------------
    # PHASE 6: Extend right wire from right plant leftward to rx
    for wx in range(rx + 1, rx + 9):
        if 0 <= wx < WORLD_W and not wm[ry, wx] and em[ry, wx]:
            return (Tool.WIRE, wx, ry)

    # ----------------------------------------------------------------
    # PHASE 7: Extend right vertical wire spine at rx
    for wr in target_rows:
        if not wm[wr, rx] and em[wr, rx]:
            return (Tool.WIRE, rx, wr)

    # ----------------------------------------------------------------
    # PHASE 8: Extend right vertical road spine at rx-1
    for wr in target_rows:
        if not rm[wr, rx - 1] and em[wr, rx - 1]:
            return (Tool.ROAD, rx - 1, wr)

    # ----------------------------------------------------------------
    # PHASE 9: Horizontal road connecting left and right along ly
    for hx in range(lx + 2, rx - 1):
        if not rm[ly, hx] and em[ly, hx]:
            return (Tool.ROAD, hx, ly)

    # ----------------------------------------------------------------
    # PHASE 10: Middle wire spine at mx, vertical
    middle_rows = range(max(0, ly - 6), min(WORLD_H, ly + 7))
    for wr in middle_rows:
        if not wm[wr, mx] and em[wr, mx]:
            return (Tool.WIRE, mx, wr)

    # Wire from left spine to middle along ly
    for wx in range(lx + 1, mx + 1):
        if not wm[ly, wx] and em[ly, wx]:
            return (Tool.WIRE, wx, ly)

    # Wire from middle to right spine along ry
    for wx in range(mx, rx):
        if not wm[ry, wx] and em[ry, wx]:
            return (Tool.WIRE, wx, ry)

    # ----------------------------------------------------------------
    # PHASE 11: Second road for left residential (at lx-4)
    for wr in target_rows:
        if not rm[wr, lx - 4] and em[wr, lx - 4]:
            return (Tool.ROAD, lx - 4, wr)

    # ----------------------------------------------------------------
    # PHASE 12: Road for right industrial (at rx+5)
    for wr in target_rows:
        if not rm[wr, rx + 5] and em[wr, rx + 5]:
            return (Tool.ROAD, rx + 5, wr)

    # ----------------------------------------------------------------
    # PHASE 13: Place zones reactively based on current map
    # Check where wire spine rows exist (for power coverage)
    left_wire_rows = [r for r in range(WORLD_H) if wm[r, lx]]
    right_wire_rows = [r for r in range(WORLD_H) if wm[r, rx]]
    mid_wire_rows = [r for r in range(WORLD_H) if wm[r, mx]]

    res_count = int(np.sum(res_m))
    com_count = int(np.sum(com_m))
    ind_count = int(np.sum(ind_m))

    # Left residential zones (center at lx-3, spaced by 3)
    for dy in range(-12, 13, 3):
        zr, zc = ly + dy, lx - 3
        if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
            # Check powered row and road nearby
            powered = any(abs(zr - wr) <= 2 for wr in left_wire_rows)
            road_near = rm[zr, lx + 1] if 0 <= lx + 1 < WORLD_W else False
            road_near = road_near or (rm[zr, lx - 4] if 0 <= lx - 4 < WORLD_W else False)
            if powered and road_near and zone_placeable(zc, zr):
                if not res_m[zr, zc]:
                    return (Tool.RESIDENTIAL, zc, zr)

    # Left commercial zones (center at lx+4)
    for dy in range(-12, 13, 3):
        zr, zc = ly + dy, lx + 4
        if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
            powered = any(abs(zr - wr) <= 2 for wr in left_wire_rows)
            road_near = rm[zr, lx + 1] if 0 <= lx + 1 < WORLD_W else False
            if powered and road_near and zone_placeable(zc, zr):
                if not com_m[zr, zc] and com_count < res_count // 2 + 3:
                    return (Tool.COMMERCIAL, zc, zr)

    # Right industrial zones (center at rx+4)
    for dy in range(-12, 13, 3):
        zr, zc = ry + dy, rx + 4
        if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
            powered = any(abs(zr - wr) <= 2 for wr in right_wire_rows)
            road_near = rm[zr, rx - 1] if 0 <= rx - 1 < WORLD_W else False
            road_near = road_near or (rm[zr, rx + 5] if 0 <= rx + 5 < WORLD_W else False)
            if powered and road_near and zone_placeable(zc, zr):
                if not ind_m[zr, zc]:
                    return (Tool.INDUSTRIAL, zc, zr)

    # Right residential zones (center at rx-4)
    for dy in range(-12, 13, 3):
        zr, zc = ry + dy, rx - 4
        if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
            powered = any(abs(zr - wr) <= 2 for wr in right_wire_rows)
            road_near = rm[zr, rx - 1] if 0 <= rx - 1 < WORLD_W else False
            if powered and road_near and zone_placeable(zc, zr):
                if not res_m[zr, zc]:
                    return (Tool.RESIDENTIAL, zc, zr)

    # Middle commercial zones (center at mx+4 and mx-3)
    for dy in range(-6, 7, 3):
        for zc in [mx + 4, mx - 3]:
            zr = ly + dy
            if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                powered = any(abs(zr - wr) <= 2 for wr in mid_wire_rows)
                road_near = rm[zr, mx + 1] if 0 <= mx + 1 < WORLD_W else False
                road_near = road_near or (rm[zr, lx + 1] if 0 <= lx + 1 < WORLD_W else False)
                if powered and road_near and zone_placeable(zc, zr):
                    if not com_m[zr, zc] and com_count < res_count // 2 + 5:
                        return (Tool.COMMERCIAL, zc, zr)

    # ----------------------------------------------------------------
    # PHASE 14: Services if population is growing
    if obs.city_pop > 100:
        # Fire station left
        fsx, fsy = lx + 1, ly - 15
        if 0 <= fsx < WORLD_W and 0 <= fsy < WORLD_H and em[fsy, fsx]:
            return (Tool.FIRESTATION, fsx, fsy)
        # Police station right
        psx, psy = rx - 1, ry - 15
        if 0 <= psx < WORLD_W and 0 <= psy < WORLD_H and em[psy, psx]:
            return (Tool.POLICESTATION, psx, psy)

    # ----------------------------------------------------------------
    # PHASE 15: Extra residential rows if population growing well
    if obs.city_pop > 300:
        # Extended left residential
        for dy in range(-15, 16, 3):
            zr, zc = ly + dy, lx - 7
            if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                if zone_placeable(zc, zr) and not res_m[zr, zc]:
                    return (Tool.RESIDENTIAL, zc, zr)
        # Extended right residential
        for dy in range(-15, 16, 3):
            zr, zc = ry + dy, rx + 7
            if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                if zone_placeable(zc, zr) and not ind_m[zr, zc]:
                    return (Tool.INDUSTRIAL, zc, zr)

    # ----------------------------------------------------------------
    # PHASE 16: Reactive gap-filling - find wire rows without zones
    # Scan for any wire row on left spine that lacks a res zone
    for wr in left_wire_rows:
        for zc in [lx - 3, lx + 4]:
            if 0 <= zc < WORLD_W and 0 <= wr < WORLD_H:
                # Snap to nearest grid-3 row
                zr = (wr // 3) * 3
                if zr < 0 or zr >= WORLD_H:
                    continue
                if zone_placeable(zc, zr):
                    road_near = rm[zr, lx + 1] if 0 <= lx + 1 < WORLD_W else False
                    if road_near:
                        if zc == lx - 3 and not res_m[zr, zc]:
                            return (Tool.RESIDENTIAL, zc, zr)
                        elif zc == lx + 4 and not com_m[zr, zc] and com_count < res_count:
                            return (Tool.COMMERCIAL, zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads map each step to decide next action
    - Places power plant first, then extends wire/road from existing infrastructure
    - Places zones adjacent to road+wire coverage
    - Adapts based on what's actually on the map
    """
    tm = obs.tile_map
    step = obs.step

    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res = res_mask(tm)
    com = com_mask(tm)
    ind = ind_mask(tm)

    # Count existing features
    plant_tiles = list(zip(*np.where(pm))) if np.any(pm) else []
    wire_tiles = list(zip(*np.where(wm))) if np.any(wm) else []
    road_tiles = list(zip(*np.where(rm))) if np.any(rm) else []
    res_tiles = list(zip(*np.where(res))) if np.any(res) else []
    com_tiles = list(zip(*np.where(com))) if np.any(com) else []
    ind_tiles = list(zip(*np.where(ind))) if np.any(ind) else []

    all_zones = res_tiles + com_tiles + ind_tiles
    res_count = len(res_tiles)
    com_count = len(com_tiles)
    ind_count = len(ind_tiles)
    total_zones = res_count + com_count + ind_count

    # Target cluster center
    cx, cy = 55, 50  # center of map

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def zone_area_free(cy_, cx_):
        """Check if 3x3 area around center is empty"""
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                r, c = cy_ + dr, cx_ + dc
                if not in_bounds(c, r) or not em[r, c]:
                    return False
        return True

    def pick_zone_type():
        total = total_zones + 1
        r_frac = res_count / total
        c_frac = com_count / total
        i_frac = ind_count / total
        if r_frac <= 0.5:
            return Tool.RESIDENTIAL
        elif c_frac <= 0.25:
            return Tool.COMMERCIAL
        elif i_frac <= 0.25:
            return Tool.INDUSTRIAL
        else:
            return Tool.RESIDENTIAL

    # Phase 1: Place coal power plant if none exists
    if len(plant_tiles) == 0:
        # Place at a fixed spot left of center
        px, py = cx - 15, cy
        return (Tool.COALPOWER, px, py)

    # Phase 2: Place second power plant if only one and many zones
    if len(plant_tiles) == 1 and total_zones > 20:
        # Place right of center
        px, py = cx + 15, cy
        # Check if area is reasonably free
        if in_bounds(px, py) and em[py, px]:
            return (Tool.COALPOWER, px, py)

    # Phase 3: Extend wire from existing wire/plant outward toward center
    # Find frontiers: tiles adjacent to wire/plant that are empty
    # We want to build a wire spine along row cy from plant to zones
    plant_cols = [c for (r, c) in plant_tiles]
    plant_rows = [r for (r, c) in plant_tiles]

    if wire_tiles:
        wire_set = set(wire_tiles)
    else:
        wire_set = set()

    if road_tiles:
        road_set = set(road_tiles)
    else:
        road_set = set()

    plant_set = set(plant_tiles)

    # Build wire spine: horizontal at row cy, extending from plant toward cx+20
    # Find rightmost wire on spine row
    spine_row = cy
    wire_on_spine = [c for (r, c) in wire_tiles if r == spine_row]
    plant_on_spine = [c for (r, c) in plant_tiles if abs(r - spine_row) <= 1]

    # Determine wire target extent
    wire_target_left = cx - 25
    wire_target_right = cx + 25

    if wire_on_spine:
        max_wire_col = max(wire_on_spine)
        min_wire_col = min(wire_on_spine)
    elif plant_on_spine:
        # Start wire from right edge of plant
        max_wire_col = max(plant_on_spine) + 2
        min_wire_col = max_wire_col
    else:
        # Start wire from first plant location
        pr, pc = plant_tiles[0]
        # wire adjacent to plant
        for dc in [1, -1, 0]:
            for dr in [1, -1, 0]:
                nr, nc = pr + dr, pc + dc
                if in_bounds(nc, nr) and em[nr, nc]:
                    return (Tool.WIRE, nc, nr)
        return None

    # Extend wire spine rightward if not complete
    if max_wire_col < wire_target_right:
        nc = max_wire_col + 1
        if in_bounds(nc, spine_row) and em[spine_row, nc]:
            return (Tool.WIRE, nc, spine_row)
        elif in_bounds(nc, spine_row) and not em[spine_row, nc]:
            # bulldoze? skip and try next
            nc2 = max_wire_col + 2
            if in_bounds(nc2, spine_row) and em[spine_row, nc2]:
                return (Tool.WIRE, nc2, spine_row)

    # Extend wire spine leftward if not complete
    if min_wire_col > wire_target_left:
        nc = min_wire_col - 1
        if in_bounds(nc, spine_row) and em[spine_row, nc]:
            return (Tool.WIRE, nc, spine_row)

    # Phase 4: Build road grid
    # Roads at spine_row-2 and spine_row+2 (parallel to wire)
    road_row_above = spine_row - 2
    road_row_below = spine_row + 2

    for road_row in [road_row_above, road_row_below]:
        road_on_row = [c for (r, c) in road_tiles if r == road_row]
        if road_on_row:
            max_rc = max(road_on_row)
            min_rc = min(road_on_row)
        else:
            max_rc = wire_target_left - 1
            min_rc = wire_target_left

        if max_rc < wire_target_right + 2:
            nc = max_rc + 1
            if in_bounds(nc, road_row) and em[road_row, nc]:
                return (Tool.ROAD, nc, road_row)
        if min_rc > wire_target_left - 2:
            nc = min_rc - 1
            if in_bounds(nc, road_row) and em[road_row, nc]:
                return (Tool.ROAD, nc, road_row)

    # Phase 5: Build vertical roads every 6 columns connecting road rows through spine
    for conn_col in range(wire_target_left, wire_target_right + 1, 6):
        for conn_row in range(road_row_above, road_row_below + 1):
            if in_bounds(conn_col, conn_row):
                if not rm[conn_row, conn_col] and not wm[conn_row, conn_col] and not pm[conn_row, conn_col]:
                    if em[conn_row, conn_col]:
                        return (Tool.ROAD, conn_col, conn_row)

    # Phase 6: Place vertical wires from spine to zone rows
    zone_rows_above = [spine_row - 5, spine_row - 8, spine_row - 11, spine_row - 14, spine_row - 17]
    zone_rows_below = [spine_row + 5, spine_row + 8, spine_row + 11, spine_row + 14, spine_row + 17]
    zone_cols = list(range(wire_target_left + 2, wire_target_right, 6))

    # Extend wires vertically at zone columns
    for zc in zone_cols:
        # Check if there's wire at spine for this col
        has_spine_wire = wm[spine_row, zc] if in_bounds(zc, spine_row) else False
        if not has_spine_wire:
            continue

        for zr in zone_rows_above:
            if not in_bounds(zc, zr):
                continue
            # Check if wire reaches this row at this col
            wire_col = [r for (r, c) in wire_tiles if c == zc and r <= spine_row and r >= zr]
            if wire_col:
                min_wr = min(wire_col)
                # extend upward
                nr = min_wr - 1
                if nr >= zr and in_bounds(zc, nr) and em[nr, zc]:
                    return (Tool.WIRE, zc, nr)
            else:
                # start going up from spine
                nr = spine_row - 1
                if in_bounds(zc, nr) and em[nr, zc]:
                    return (Tool.WIRE, zc, nr)

        for zr in zone_rows_below:
            if not in_bounds(zc, zr):
                continue
            wire_col = [r for (r, c) in wire_tiles if c == zc and r >= spine_row and r <= zr]
            if wire_col:
                max_wr = max(wire_col)
                nr = max_wr + 1
                if nr <= zr and in_bounds(zc, nr) and em[nr, zc]:
                    return (Tool.WIRE, zc, nr)
            else:
                nr = spine_row + 1
                if in_bounds(zc, nr) and em[nr, zc]:
                    return (Tool.WIRE, zc, nr)

    # Phase 7: Place zones near roads and wire
    # Check powered_zones to know if wiring is working
    for zr in zone_rows_above + zone_rows_below:
        for zc in zone_cols:
            if not in_bounds(zc, zr):
                continue
            # Check road access (within 3 tiles)
            road_near = False
            for dr in range(-3, 4):
                for dc in range(-3, 4):
                    nr, nc = zr + dr, zc + dc
                    if in_bounds(nc, nr) and rm[nr, nc]:
                        road_near = True
                        break
                if road_near:
                    break

            # Check wire access (within 5 tiles)
            wire_near = False
            for dr in range(-5, 6):
                for dc in range(-5, 6):
                    nr, nc = zr + dr, zc + dc
                    if in_bounds(nc, nr) and wm[nr, nc]:
                        wire_near = True
                        break
                if wire_near:
                    break

            if road_near and wire_near:
                # Check not already a zone nearby
                zone_near = False
                for (zrr, zcc) in all_zones:
                    if abs(zrr - zr) <= 2 and abs(zcc - zc) <= 2:
                        zone_near = True
                        break

                if not zone_near and zone_area_free(zr, zc):
                    return (pick_zone_type(), zc, zr)

    # Phase 8: Try to extend zone placement to more rows if city is growing
    if obs.city_pop > 50:
        extra_rows = [spine_row - 20, spine_row + 20, spine_row - 23, spine_row + 23]
        for zr in extra_rows:
            for zc in zone_cols:
                if not in_bounds(zc, zr):
                    continue
                road_near = any(
                    in_bounds(zc + dc, zr + dr) and rm[zr + dr, zc + dc]
                    for dr in range(-4, 5) for dc in range(-4, 5)
                )
                if road_near and zone_area_free(zr, zc):
                    zone_near = any(
                        abs(zrr - zr) <= 2 and abs(zcc - zc) <= 2
                        for (zrr, zcc) in all_zones
                    )
                    if not zone_near:
                        return (pick_zone_type(), zc, zr)

    # Phase 9: Fill gaps - look for empty road spots on road rows
    for road_row in [road_row_above, road_row_below]:
        for nc in range(wire_target_left - 2, wire_target_right + 3):
            if in_bounds(nc, road_row) and em[road_row, nc]:
                # Check if neighbors have road
                has_road_neighbor = any(
                    in_bounds(nc + dc, road_row) and rm[road_row, nc + dc]
                    for dc in [-1, 1]
                )
                if has_road_neighbor:
                    return (Tool.ROAD, nc, road_row)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Read map each step, find existing infrastructure, extend it.
    - Power plant → wire spine (vertical) → road spine → zones on both sides
    - Lateral wires connect left zones; road extensions connect right zones.
    - Reacts to current tile_map state each step.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    # Working area: center of map
    cx, cy = 60, 50

    # ---- Phase 1: Place coal power plant ----
    if not np.any(pm):
        px, py = cx - 5, cy
        return (Tool.COALPOWER, px, py)

    # Find plant center (centroid of plant tiles)
    plant_rows, plant_cols = np.where(pm)
    pcx = int(np.mean(plant_cols))
    pcy = int(np.mean(plant_rows))

    # Wire spine column: just right of plant footprint
    # Plant footprint is 4x4 tiles; plant center pcx => footprint pcx-1..pcx+2
    wire_col = pcx + 3   # one tile right of plant right edge
    road_col = wire_col + 2  # road two tiles right of wire spine

    # Left zone center col (zones powered via lateral wire from spine)
    left_zone_col = wire_col - 3
    # Right zone center col (zones with road access)
    right_zone_col = road_col + 3

    # Vertical range for spine
    spine_min = max(1, pcy - 18)
    spine_max = min(WORLD_H - 2, pcy + 18)

    # ---- Phase 2: Extend wire spine vertically ----
    wire_in_col = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])

    if not wire_in_col:
        # Start wire adjacent to plant
        for dy in range(0, 4):
            for try_row in [pcy + dy, pcy - dy]:
                if spine_min <= try_row <= spine_max:
                    if em[try_row, wire_col] or wm[try_row, wire_col]:
                        return (Tool.WIRE, wire_col, try_row)
        return None

    w_min = min(wire_in_col)
    w_max = max(wire_in_col)

    # Extend downward first, then upward
    if w_max < spine_max:
        nr = w_max + 1
        if em[nr, wire_col] or wm[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)

    if w_min > spine_min:
        nr = w_min - 1
        if em[nr, wire_col] or wm[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)

    # ---- Phase 3: Build road spine parallel to wire ----
    road_in_col = sorted([r for r in range(WORLD_H) if rm[r, road_col]])

    # For each wire row, ensure road exists
    for wr in wire_in_col:
        if 0 <= road_col < WORLD_W and not rm[wr, road_col]:
            if em[wr, road_col]:
                return (Tool.ROAD, road_col, wr)

    # ---- Phase 4: Lateral wires to connect left zones ----
    # Wire from wire_col-1 to left_zone_col+1 at each wire row
    for wr in wire_in_col:
        for wc in range(wire_col - 1, left_zone_col - 1, -1):
            if 0 <= wc < WORLD_W:
                if not wm[wr, wc] and em[wr, wc]:
                    return (Tool.WIRE, wc, wr)

    # ---- Phase 5: Road extension to right zones ----
    for wr in wire_in_col:
        for rc in range(road_col + 1, right_zone_col + 2):
            if 0 <= rc < WORLD_W and not rm[wr, rc] and em[wr, rc]:
                return (Tool.ROAD, rc, wr)

    # ---- Phase 6: Place zones ----
    res_pos = list(zip(*np.where(res_mask(tm)))) if np.any(res_mask(tm)) else []
    com_pos = list(zip(*np.where(com_mask(tm)))) if np.any(com_mask(tm)) else []
    ind_pos = list(zip(*np.where(ind_mask(tm)))) if np.any(ind_mask(tm)) else []

    res_count = len(res_pos)
    com_count = len(com_pos)
    ind_count = len(ind_pos)

    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def zone_placed_near(zr, zc, positions):
        return any(abs(zr - pr) <= 1 and abs(zc - pc) <= 1 for (pr, pc) in positions)

    all_zone_pos = res_pos + com_pos + ind_pos

    # Zone rows spaced 3 apart along spine
    zone_rows = list(range(max(2, spine_min + 1), min(WORLD_H - 2, spine_max), 3))

    # Check power and road proximity reactively
    def has_wire_near(zr, zc, radius=3):
        for dr in range(-radius, radius + 1):
            for dc in range(-radius, radius + 1):
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if wm[rr, rc] or pm[rr, rc]:
                        return True
        return False

    def has_road_near(zr, zc, radius=3):
        for dr in range(-radius, radius + 1):
            for dc in range(-radius, radius + 1):
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if rm[rr, rc]:
                        return True
        return False

    for zr in zone_rows:
        # Left zone (powered by lateral wire)
        zc = left_zone_col
        if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
            if not zone_placed_near(zr, zc, all_zone_pos) and zone_area_free(zr, zc):
                if has_wire_near(zr, zc) and has_road_near(zr, zc):
                    if ind_count < max(1, res_count // 4):
                        return (Tool.INDUSTRIAL, zc, zr)
                    elif com_count < max(1, res_count // 3):
                        return (Tool.COMMERCIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

        # Right zone (has road access)
        zc = right_zone_col
        if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
            if not zone_placed_near(zr, zc, all_zone_pos) and zone_area_free(zr, zc):
                if has_wire_near(zr, zc) and has_road_near(zr, zc):
                    if com_count < max(1, res_count // 3):
                        return (Tool.COMMERCIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

    # ---- Phase 7: Second wire spine for more zones (reactive to population) ----
    if obs.city_pop > 200:
        wire2_col = right_zone_col + 3
        road2_col = wire2_col + 2
        left2_zone_col = wire2_col - 3
        right2_zone_col = road2_col + 3

        wire2_in_col = sorted([r for r in range(WORLD_H) if wm[r, wire2_col]])

        if not wire2_in_col:
            # Start from center row
            if em[pcy, wire2_col]:
                return (Tool.WIRE, wire2_col, pcy)
        else:
            w2_min = min(wire2_in_col)
            w2_max = max(wire2_in_col)

            if w2_max < spine_max:
                nr = w2_max + 1
                if em[nr, wire2_col]:
                    return (Tool.WIRE, wire2_col, nr)
            if w2_min > spine_min:
                nr = w2_min - 1
                if em[nr, wire2_col]:
                    return (Tool.WIRE, wire2_col, nr)

            for wr in wire2_in_col:
                if 0 <= road2_col < WORLD_W and not rm[wr, road2_col] and em[wr, road2_col]:
                    return (Tool.ROAD, road2_col, wr)

            for zr in zone_rows:
                for zc in [left2_zone_col, right2_zone_col]:
                    if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                        if not zone_placed_near(zr, zc, all_zone_pos) and zone_area_free(zr, zc):
                            if has_wire_near(zr, zc) and has_road_near(zr, zc):
                                if com_count < max(1, res_count // 3):
                                    return (Tool.COMMERCIAL, zc, zr)
                                else:
                                    return (Tool.RESIDENTIAL, zc, zr)

    # ---- Phase 8: Add more zones in expanded rows if population high ----
    if obs.city_pop > 400:
        extra_rows = list(range(max(2, spine_min - 6), min(WORLD_H - 2, spine_max + 6), 3))
        for zr in extra_rows:
            for zc in [left_zone_col, right_zone_col, left_zone_col - 6, right_zone_col + 6]:
                if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                    if not zone_placed_near(zr, zc, all_zone_pos) and zone_area_free(zr, zc):
                        if has_wire_near(zr, zc, 4) and has_road_near(zr, zc, 4):
                            return (Tool.RESIDENTIAL, zc, zr)

    return None

def act(obs, state):
    """
    Combined policy: compact cluster with vertical wire spine, parallel roads,
    and zones placed on both sides. Uses horizontal wire branches for power.
    Expands outward as population grows.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # Center of map
    cx, cy = 60, 50

    # Plant position (3x3 centered here)
    plant_cx, plant_cy = cx - 6, cy

    # Wire spine column, roads on either side, zones further out
    wire_col = cx        # col 60
    road_col_L = cx - 2  # col 58
    road_col_R = cx + 2  # col 62
    zone_col_L = cx - 5  # col 55
    zone_col_R = cx + 5  # col 65

    # Vertical span: grow with population
    base_span = 12
    extra_span = min(25, obs.city_pop // 20)
    target_span = base_span + extra_span
    tmin = max(3, cy - target_span)
    tmax = min(WORLD_H - 4, cy + target_span)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def has_tile(mask, x, y):
        if in_bounds(x, y):
            return bool(mask[y, x])
        return False

    def is_empty(x, y):
        if in_bounds(x, y):
            return bool(em[y, x])
        return False

    def is_plant(x, y):
        if in_bounds(x, y):
            return bool(pm[y, x])
        return False

    def zone_area_free(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rx, ry = zx + dc, zy + dr
                if not in_bounds(rx, ry):
                    return False
                if not em[ry, rx]:
                    return False
        return True

    # Gather zone info
    res_pos = set(zip(*np.where(res_m))) if np.any(res_m) else set()
    com_pos = set(zip(*np.where(com_m))) if np.any(com_m) else set()
    ind_pos = set(zip(*np.where(ind_m))) if np.any(ind_m) else set()
    all_zones = res_pos | com_pos | ind_pos

    res_count = len(res_pos)
    com_count = len(com_pos)
    ind_count = len(ind_pos)

    def already_zone_nearby(zy, zx):
        return any(abs(zy - pr) <= 2 and abs(zx - pc) <= 2 for (pr, pc) in all_zones)

    def choose_zone():
        total = res_count + com_count + ind_count
        if total == 0:
            return Tool.RESIDENTIAL
        # Target: ~50% res, ~30% com, ~20% ind
        if res_count == 0 or (res_count > 0 and ind_count * 5 < res_count):
            return Tool.INDUSTRIAL
        elif com_count * 3 < res_count:
            return Tool.COMMERCIAL
        else:
            return Tool.RESIDENTIAL

    # Phase 1: place coal power plant
    if not np.any(pm):
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Build wire spine from plant to wire_col (horizontal connector first)
    # Plant is at plant_cx=54, wire_col=60; connect with wire horizontally at cy
    for wx in range(plant_cx + 2, wire_col):
        if not has_tile(wm, wx, cy) and not is_plant(wx, cy):
            if is_empty(wx, cy) or has_tile(wm, wx, cy):
                return (Tool.WIRE, wx, cy)

    # Phase 2: build vertical wire spine at wire_col
    wire_rows = sorted(r for r in range(WORLD_H) if has_tile(wm, wire_col, r))

    if not wire_rows:
        # Start wire at wire_col, cy
        if is_empty(wire_col, cy):
            return (Tool.WIRE, wire_col, cy)
        return None

    min_wr = min(wire_rows)
    max_wr = max(wire_rows)

    # Extend downward
    if max_wr < tmax:
        nr = max_wr + 1
        if in_bounds(wire_col, nr) and (is_empty(wire_col, nr) or has_tile(wm, wire_col, nr)):
            return (Tool.WIRE, wire_col, nr)

    # Extend upward
    if min_wr > tmin:
        nr = min_wr - 1
        if in_bounds(wire_col, nr) and (is_empty(wire_col, nr) or has_tile(wm, wire_col, nr)):
            return (Tool.WIRE, wire_col, nr)

    wire_rows_set = set(wire_rows)

    # Phase 3: build left road column
    for wr in wire_rows:
        if not has_tile(rm, road_col_L, wr) and is_empty(road_col_L, wr):
            return (Tool.ROAD, road_col_L, wr)

    # Phase 4: build right road column
    for wr in wire_rows:
        if not has_tile(rm, road_col_R, wr) and is_empty(road_col_R, wr):
            return (Tool.ROAD, road_col_R, wr)

    # Phase 5: horizontal wire bridges every 3 rows from spine to roads
    for wr in wire_rows:
        if wr % 3 == 0:
            # Left bridge: wire_col-1 down to road_col_L+1
            for wc in range(wire_col - 1, road_col_L, -1):
                if is_empty(wc, wr):
                    return (Tool.WIRE, wc, wr)
            # Right bridge: wire_col+1 up to road_col_R-1
            for wc in range(wire_col + 1, road_col_R):
                if is_empty(wc, wr):
                    return (Tool.WIRE, wc, wr)

    # Phase 6: place zones adjacent to roads
    road_L_rows = set(r for r in range(WORLD_H) if has_tile(rm, road_col_L, r))
    road_R_rows = set(r for r in range(WORLD_H) if has_tile(rm, road_col_R, r))

    for wr in wire_rows:
        road_L_ok = any(abs(wr - rr) <= 2 for rr in road_L_rows)
        road_R_ok = any(abs(wr - rr) <= 2 for rr in road_R_rows)

        for (zx, road_ok) in [(zone_col_L, road_L_ok), (zone_col_R, road_R_ok)]:
            if not road_ok:
                continue
            if 3 <= wr <= WORLD_H - 4 and 3 <= zx <= WORLD_W - 4:
                if not already_zone_nearby(wr, zx) and zone_area_free(zx, wr):
                    return (choose_zone(), zx, wr)

    # Phase 7: second tier expansion if population growing
    if obs.city_pop > 100 or (len(wire_rows) > 15 and len(all_zones) > 5):
        zone_col_L2 = zone_col_L - 6   # col 49
        zone_col_R2 = zone_col_R + 6   # col 71
        road_col_L2 = zone_col_L2 + 2  # col 51
        road_col_R2 = zone_col_R2 - 2  # col 69

        # Extend horizontal wires outward every 3 rows
        for wr in wire_rows:
            if wr % 3 == 0:
                for wc in range(road_col_L - 1, road_col_L2, -1):
                    if is_empty(wc, wr):
                        return (Tool.WIRE, wc, wr)
                for wc in range(road_col_R + 1, road_col_R2 + 1):
                    if is_empty(wc, wr):
                        return (Tool.WIRE, wc, wr)

        # Build second tier roads
        road_L2_rows = set(r for r in range(WORLD_H) if has_tile(rm, road_col_L2, r))
        road_R2_rows = set(r for r in range(WORLD_H) if has_tile(rm, road_col_R2, r))

        for wr in wire_rows:
            if wr not in road_L2_rows and is_empty(road_col_L2, wr):
                return (Tool.ROAD, road_col_L2, wr)
            if wr not in road_R2_rows and is_empty(road_col_R2, wr):
                return (Tool.ROAD, road_col_R2, wr)

        # Place zones for second tier
        for wr in wire_rows:
            road_L2_ok = any(abs(wr - rr) <= 2 for rr in road_L2_rows)
            road_R2_ok = any(abs(wr - rr) <= 2 for rr in road_R2_rows)

            for (zx, road_ok) in [(zone_col_L2, road_L2_ok), (zone_col_R2, road_R2_ok)]:
                if not road_ok:
                    continue
                if 3 <= wr <= WORLD_H - 4 and 3 <= zx <= WORLD_W - 4:
                    if not already_zone_nearby(wr, zx) and zone_area_free(zx, wr):
                        return (choose_zone(), zx, wr)

    # Phase 8: add second power plant if large city
    if obs.city_pop > 500:
        plant2_x, plant2_y = cx + 15, cy
        if not has_tile(pm, plant2_x, plant2_y):
            # Wire to connect
            for wc in range(road_col_R + 1, plant2_x - 2):
                if is_empty(wc, cy):
                    return (Tool.WIRE, wc, cy)
            return (Tool.COALPOWER, plant2_x, plant2_y)

    return None

def act(obs, state):
    """
    Closed-loop city builder:
    - Each step reads the current map and decides what to place next
    - Extends power (wires) and roads from existing infrastructure
    - Places zones adjacent to powered+roaded areas
    - Adapts to what's actually on the map
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Phase tracking in state
    if 'phase' not in state:
        state['phase'] = 'plant'
        state['road_col'] = None
        state['wire_col'] = None

    # --- Step 1: Ensure we have at least one power plant ---
    plant_ys, plant_xs = np.where(pm)
    has_plant = len(plant_xs) > 0

    if not has_plant:
        # Place coal plant near center-left
        return (Tool.COALPOWER, 15, 50)

    # Find the primary plant location
    px0, py0 = int(plant_xs[0]), int(plant_ys[0])

    # --- Step 2: Extend wire from plant eastward ---
    # Wire spine runs along plant's row
    spine_y = py0

    # Find rightmost wire on spine_y
    wire_on_spine = wm[spine_y, :] | pm[spine_y, :]
    wire_xs_spine = np.where(wire_on_spine)[0]

    if len(wire_xs_spine) > 0:
        rightmost_wire = int(np.max(wire_xs_spine))
    else:
        rightmost_wire = px0

    # Extend wire eastward if not too far and we want more coverage
    target_wire_x = min(px0 + 60, WORLD_W - 4)
    if rightmost_wire < target_wire_x:
        nx = rightmost_wire + 1
        if in_bounds(nx, spine_y) and not bool(pm[spine_y, nx]):
            if bool(em[spine_y, nx]) or bool(wm[spine_y, nx]):
                if bool(em[spine_y, nx]):
                    return (Tool.WIRE, nx, spine_y)

    # --- Step 3: Add vertical wire branches at intervals ---
    # Branch wire up and down from spine every 6 columns
    for bx in range(px0 + 6, target_wire_x + 1, 6):
        if not in_bounds(bx, spine_y):
            continue
        if not (bool(wm[spine_y, bx]) or bool(pm[spine_y, bx])):
            continue
        # Branch up and down 4 tiles
        for sign in [-1, 1]:
            for dy in range(1, 5):
                wy2 = spine_y + sign * dy
                if not in_bounds(bx, wy2):
                    break
                if bool(pm[wy2, bx]):
                    break
                if not bool(wm[wy2, bx]):
                    if bool(em[wy2, bx]):
                        return (Tool.WIRE, bx, wy2)
                    break

    # --- Step 4: Build roads parallel to spine ---
    # Road rows at spine_y - 3 and spine_y + 3
    for road_dy in [-3, 3]:
        ry = spine_y + road_dy
        if not in_bounds(0, ry):
            continue
        # Find leftmost gap in road on this row
        road_on_row = rm[ry, :]
        # Build road from px0+3 to target_wire_x
        for rx in range(px0 + 3, target_wire_x + 1):
            if not in_bounds(rx, ry):
                break
            if not bool(rm[ry, rx]) and not bool(pm[ry, rx]) and not bool(wm[ry, rx]):
                if bool(em[ry, rx]):
                    return (Tool.ROAD, rx, ry)
                break

    # Additional road rows at spine_y - 6 and spine_y + 6
    for road_dy in [-6, 6]:
        ry = spine_y + road_dy
        if not in_bounds(0, ry):
            continue
        for rx in range(px0 + 3, target_wire_x + 1):
            if not in_bounds(rx, ry):
                break
            if not bool(rm[ry, rx]) and not bool(pm[ry, rx]) and not bool(wm[ry, rx]):
                if bool(em[ry, rx]):
                    return (Tool.ROAD, rx, ry)
                break

    # Vertical connector roads between outer roads every 6 cols
    for vc in range(px0 + 6, target_wire_x + 1, 6):
        for vr in range(spine_y - 6, spine_y + 7):
            if not in_bounds(vc, vr):
                continue
            if bool(pm[vr, vc]) or bool(wm[vr, vc]):
                continue
            if not bool(rm[vr, vc]) and bool(em[vr, vc]):
                return (Tool.ROAD, vc, vr)

    # --- Step 5: Place zones where there's road AND wire access ---
    # Compute neighbor masks
    def dilate(mask, radius):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-radius, radius + 1):
            for dx in range(-radius, radius + 1):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                result[r0:r1, c0:c1] |= mask[sr0:sr1, sc0:sc1]
        return result

    nbr_road = dilate(rm, 2)
    nbr_wire = dilate(wm | pm, 4)

    # Zone must be 3x3 clear
    zone_set = set()
    for arr in [resm, comm, indm]:
        ys, xs = np.where(arr)
        for y, x in zip(ys.tolist(), xs.tolist()):
            zone_set.add((y, x))

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not bool(em[nr, nc]) and (nr, nc) not in zone_set:
                    return False
        return True

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        r = res_count / max(total_zones, 1)
        c = com_count / max(total_zones, 1)
        i_frac = ind_count / max(total_zones, 1)
        if c < 0.22:
            return Tool.COMMERCIAL
        if i_frac < 0.22:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Use step + pop for deterministic but varying selection
        step_hash = (obs.step * 17 + int(obs.city_pop * 3)) % max(len(cxs), 1)
        for offset in range(min(len(cxs), 80)):
            k = (step_hash + offset * 13) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # --- Step 6: Services when population warrants ---
    if obs.city_pop > 200:
        for fx, fy in [(px0 + 6, spine_y - 9), (px0 + 30, spine_y + 9)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.FIRESTATION, fx, fy)

    if obs.city_pop > 300:
        for fx, fy in [(px0 + 18, spine_y - 9), (px0 + 42, spine_y + 9)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.POLICESTATION, fx, fy)

    # Second power plant if population growing
    if obs.city_pop > 500 and len(plant_xs) < 2:
        # Place second plant further right
        p2x = px0 + 50
        p2y = spine_y + 10
        if in_bounds(p2x, p2y) and bool(em[p2y, p2x]):
            return (Tool.COALPOWER, p2x, p2y)

    # --- Fallback: extend roads from existing road frontier ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (obs.step * 13) % max(len(road_xs2), 1)
        rx_s, ry_s = int(road_xs2[step_k]), int(road_ys2[step_k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx_s + dx2, ry_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # --- Fallback: extend wires ---
    wire_ys2, wire_xs2 = np.where(wm)
    if len(wire_xs2) > 0:
        step_k2 = (obs.step * 7) % max(len(wire_xs2), 1)
        wx_s, wy_s = int(wire_xs2[step_k2]), int(wire_ys2[step_k2])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = wx_s + dx2, wy_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map each step to decide next action.
    Strategy:
    - Place coal power plant first
    - Grow wire from plant edge, scan map each step
    - Grow road adjacent to wire spine
    - Place zones adjacent to road, powered by wire
    - React to current state: find frontier tiles dynamically
    """
    tm = obs.tile_map
    step = obs.step

    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    has_plant = np.any(pm)
    has_wire = np.any(wm)
    has_road = np.any(rm)

    # Center of map
    cx, cy = 60, 50

    # === Phase 1: Place coal power plant ===
    if not has_plant:
        return (Tool.COALPOWER, cx - 20, cy)

    # Get plant center (approximate from plant tiles)
    plant_ys, plant_xs = np.where(pm)
    plant_cx = int(np.mean(plant_xs))
    plant_cy = int(np.mean(plant_ys))

    # === Phase 2: Grow wire from plant rightward along spine row ===
    # Wire spine at plant_cy row, extending right
    spine_row = plant_cy

    if not has_wire:
        # Place first wire just right of plant (plant is 4x4, so +3)
        wx = plant_cx + 3
        if 0 <= wx < WORLD_W and 0 <= spine_row < WORLD_H:
            return (Tool.WIRE, wx, spine_row)

    # Find rightmost wire on spine row
    wire_on_spine = [(c) for (r, c) in zip(*np.where(wm)) if r == spine_row]

    # Find rightmost wire anywhere
    wire_ys, wire_xs = np.where(wm)

    if wire_on_spine:
        max_wire_x = max(wire_on_spine)
        min_wire_x = min(wire_on_spine)

        # Extend wire right up to cx+25
        target_right = min(cx + 25, WORLD_W - 5)
        if max_wire_x < target_right:
            nx = max_wire_x + 1
            if em[spine_row, nx]:
                return (Tool.WIRE, nx, spine_row)
            else:
                # bulldoze and place wire anyway (auto-bulldoze is on)
                return (Tool.WIRE, nx, spine_row)

        # Extend wire left from plant toward cx-25
        target_left = max(cx - 25, 5)
        # Find wires left of plant
        left_wires = [c for c in wire_on_spine if c < plant_cx]
        if not left_wires:
            # Start left extension from plant left edge
            lx = plant_cx - 3
            if lx >= 0:
                return (Tool.WIRE, lx, spine_row)
        else:
            min_left = min(left_wires)
            if min_left > target_left:
                nx = min_left - 1
                if nx >= 0:
                    return (Tool.WIRE, nx, spine_row)

    # === Phase 3: Build road spine 2 rows below wire spine ===
    road_row = spine_row + 2

    if wire_on_spine and len(wire_on_spine) > 3:
        wire_min_x = min(wire_on_spine)
        wire_max_x = max(wire_on_spine)

        road_on_row = [c for (r, c) in zip(*np.where(rm)) if r == road_row]

        road_start = wire_min_x
        road_end = wire_max_x

        if not road_on_row:
            if 0 <= road_row < WORLD_H and 0 <= road_start < WORLD_W:
                return (Tool.ROAD, road_start, road_row)
        else:
            max_road_x = max(road_on_row)
            min_road_x = min(road_on_row)
            if max_road_x < road_end:
                nx = max_road_x + 1
                if 0 <= nx < WORLD_W:
                    return (Tool.ROAD, nx, road_row)
            if min_road_x > road_start:
                nx = min_road_x - 1
                if nx >= 0:
                    return (Tool.ROAD, nx, road_row)

    # Also road 2 rows above wire spine
    road_row_up = spine_row - 2
    if wire_on_spine and len(wire_on_spine) > 3:
        wire_min_x = min(wire_on_spine)
        wire_max_x = max(wire_on_spine)
        road_up_on_row = [c for (r, c) in zip(*np.where(rm)) if r == road_row_up]
        road_start = wire_min_x
        road_end = wire_max_x
        if not road_up_on_row:
            if 0 <= road_row_up < WORLD_H and 0 <= road_start < WORLD_W:
                return (Tool.ROAD, road_start, road_row_up)
        else:
            max_road_x = max(road_up_on_row)
            min_road_x = min(road_up_on_row)
            if max_road_x < road_end:
                nx = max_road_x + 1
                if 0 <= nx < WORLD_W:
                    return (Tool.ROAD, nx, road_row_up)
            if min_road_x > road_start:
                nx = min_road_x - 1
                if nx >= 0:
                    return (Tool.ROAD, nx, road_row_up)

    # === Phase 4: Place zones adjacent to road, check wire coverage ===
    # Check if a 3x3 zone area at (cr,cc) is clear
    def zone_ok(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                # Must be empty (not road, not wire, not zone, not plant)
                if not em[rr, rc]:
                    return False
        return True

    def wire_nearby(cr, cc, radius=4):
        r0 = max(0, cr - radius)
        r1 = min(WORLD_H, cr + radius + 1)
        c0 = max(0, cc - radius)
        c1 = min(WORLD_W, cc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def road_nearby(cr, cc, radius=3):
        r0 = max(0, cr - radius)
        r1 = min(WORLD_H, cr + radius + 1)
        c0 = max(0, cc - radius)
        c1 = min(WORLD_W, cc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    def zone_occupied(cr, cc):
        r0 = max(0, cr - 2)
        r1 = min(WORLD_H, cr + 3)
        c0 = max(0, cc - 2)
        c1 = min(WORLD_W, cc + 3)
        sub = tm[r0:r1, c0:c1]
        has_res = np.any(res_m[r0:r1, c0:c1])
        has_com = np.any(com_m[r0:r1, c0:c1])
        has_ind = np.any(ind_m[r0:r1, c0:c1])
        return has_res or has_com or has_ind

    res_count = np.sum(res_m)
    com_count = np.sum(com_m)
    ind_count = np.sum(ind_m)

    def pick_zone():
        total = res_count + com_count + ind_count + 1
        if com_count / total < 0.25:
            return Tool.COMMERCIAL
        if ind_count / total < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Scan road rows, place zones above and below them
    all_road_ys, all_road_xs = np.where(rm)
    if len(all_road_xs) > 0:
        # For each road segment, try placing zone 3 rows above/below
        # Iterate over road positions sorted by x
        road_pts = sorted(zip(all_road_xs.tolist(), all_road_ys.tolist()))
        # Sample every 3rd road tile to find zone positions
        for rx, ry in road_pts[::3]:
            for offset in [-3, 3]:
                zr = ry + offset
                zc = rx
                if not (3 <= zr <= WORLD_H - 4 and 3 <= zc <= WORLD_W - 4):
                    continue
                if not road_nearby(zr, zc):
                    continue
                if not wire_nearby(zr, zc):
                    continue
                if zone_occupied(zr, zc):
                    continue
                if zone_ok(zr, zc):
                    return (pick_zone(), zc, zr)

    # === Phase 5: Second power plant if needed ===
    if np.sum(wm) > 15 and obs.powered_zones == 0:
        # Maybe plant isn't connected - try placing second plant further right
        if len(wire_on_spine) > 0:
            far_wx = max(wire_on_spine)
            if far_wx + 5 < WORLD_W:
                return (Tool.COALPOWER, far_wx + 5, spine_row)

    # === Phase 6: Add vertical wire connectors to reach far zones ===
    if wire_on_spine and len(wire_on_spine) > 5:
        # Connect wire vertically from spine toward zone rows
        sample_cols = wire_on_spine[::6]
        for wc in sample_cols:
            for target_r in [spine_row - 5, spine_row + 5]:
                if not (0 <= target_r < WORLD_H):
                    continue
                # Walk from spine toward target
                step_dir = -1 if target_r < spine_row else 1
                for r in range(spine_row + step_dir, target_r + step_dir, step_dir):
                    if 0 <= r < WORLD_H:
                        if not wm[r, wc] and not pm[r, wc]:
                            return (Tool.WIRE, wc, r)

    # === Phase 7: Police/Fire for city services ===
    if obs.city_pop > 200 and step % 100 == 50:
        for sr, sc in [(cy - 8, cx), (cy + 8, cx), (cy, cx - 15), (cy, cx + 15)]:
            if 0 <= sr < WORLD_H and 0 <= sc < WORLD_W:
                if em[sr, sc]:
                    return (Tool.POLICESTATION, sc, sr)

    if obs.city_pop > 400 and step % 100 == 70:
        for sr, sc in [(cy - 10, cx - 5), (cy + 10, cx + 5)]:
            if 0 <= sr < WORLD_H and 0 <= sc < WORLD_W:
                if em[sr, sc]:
                    return (Tool.FIRESTATION, sc, sr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map every step to find existing infrastructure
    - Builds compact corridor: plant -> wire spine -> road -> zones
    - Adapts placement to what's actually on the map
    - Uses 2 corridor layout: primary (center) and secondary (offset)
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    all_zone = resm | comm | indm

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(total_zones, 1)
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone[rr, rc]:
                    return False
        return True

    def zone_exists_near(zr, zc, r=2):
        r0 = max(0, zr - r); r1 = min(WORLD_H, zr + r + 1)
        c0 = max(0, zc - r); c1 = min(WORLD_W, zc + r + 1)
        return np.any(all_zone[r0:r1, c0:c1])

    def wire_near(zr, zc, radius=3):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def road_near(zr, zc, radius=3):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    # --- Phase 1: Place coal power plant if missing ---
    if not np.any(pm):
        # Place plant at a fixed location left of center
        px, py = cx - 10, cy
        return (Tool.COALPOWER, px, py)

    # Find plant location
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Define corridor geometry based on plant location
    wire_col = plant_cx + 3   # wire spine just right of plant
    road_col = wire_col + 2   # road column
    left_col  = wire_col - 3  # left zone column
    right_col = road_col + 3  # right zone column

    # Clamp
    wire_col  = max(2, min(WORLD_W - 3, wire_col))
    road_col  = max(2, min(WORLD_W - 3, road_col))
    left_col  = max(2, min(WORLD_W - 3, left_col))
    right_col = max(2, min(WORLD_W - 3, right_col))

    # Determine vertical extent based on population
    pop = obs.city_pop
    if pop < 50:
        half = 6
    elif pop < 200:
        half = 10
    elif pop < 500:
        half = 16
    else:
        half = 22

    y_min = max(1, cy - half)
    y_max = min(WORLD_H - 2, cy + half)

    # Current wire spine rows
    wire_rows = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])
    road_rows = sorted([r for r in range(WORLD_H) if rm[r, road_col]])

    # --- Phase 2: Start wire spine adjacent to plant ---
    if not wire_rows:
        # Find empty cell adjacent to plant, at wire_col
        for dy in range(0, 8):
            for nr in [plant_cy + dy, plant_cy - dy]:
                if 0 <= nr < WORLD_H and 0 <= wire_col < WORLD_W:
                    if em[nr, wire_col]:
                        return (Tool.WIRE, wire_col, nr)
        return None

    min_wr = min(wire_rows)
    max_wr = max(wire_rows)

    # --- Phase 3: Extend wire spine vertically ---
    # Prefer downward first
    if max_wr < y_max:
        nr = max_wr + 1
        if nr < WORLD_H and em[nr, wire_col] and not pm[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)

    if min_wr > y_min:
        nr = min_wr - 1
        if nr >= 0 and em[nr, wire_col] and not pm[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)

    # --- Phase 4: Build road column parallel to wire spine ---
    # Only build road where we have wire coverage
    for r in wire_rows:
        if y_min <= r <= y_max:
            if 0 <= road_col < WORLD_W and em[r, road_col] and not pm[r, road_col]:
                return (Tool.ROAD, road_col, r)

    # --- Phase 5: Connect plant to wire spine with wire if gap ---
    # Check if plant is connected (wire adjacent to plant)
    connected = False
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            rr, rc = plant_cy + dr, plant_cx + dc
            if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                if wm[rr, rc]:
                    connected = True
    if not connected and wire_rows:
        # Bridge from plant right edge to wire_col
        bridge_r = plant_cy
        for bc in range(plant_cx + 1, wire_col + 1):
            if 0 <= bc < WORLD_W:
                if wm[bridge_r, bc]:
                    break
                if em[bridge_r, bc]:
                    return (Tool.WIRE, bc, bridge_r)

    # --- Phase 6: Place zones along the corridor ---
    zone_rows = list(range(y_min, y_max + 1, 3))

    for zr in zone_rows:
        # Check wire and road coverage for this row
        w_close = any(abs(zr - wr) <= 2 for wr in wire_rows)
        r_close = any(abs(zr - rr) <= 2 for rr in road_rows)

        if w_close and r_close:
            # Try left zone (adjacent to wire spine)
            zc = left_col
            if not zone_exists_near(zr, zc) and zone_area_ok(zr, zc):
                if wire_near(zr, zc) and road_near(zr, zc):
                    return (pick_tool(), zc, zr)

            # Try right zone (adjacent to road)
            zc = right_col
            if not zone_exists_near(zr, zc) and zone_area_ok(zr, zc):
                if road_near(zr, zc) and wire_near(zr, zc, 5):
                    return (pick_tool(), zc, zr)

    # --- Phase 7: Lateral wires to left zones ---
    for wr in wire_rows:
        if y_min <= wr <= y_max:
            # Extend wire leftward from spine to left_col
            for wc in range(wire_col - 1, left_col - 2, -1):
                if wc < 0:
                    break
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc] and not wm[wr, wc]:
                    break

    # --- Phase 8: Extend road to right zones ---
    for rr in road_rows:
        if y_min <= rr <= y_max:
            for rc in range(road_col + 1, right_col + 2):
                if rc >= WORLD_W:
                    break
                if rm[rr, rc]:
                    break
                if em[rr, rc] and not pm[rr, rc]:
                    return (Tool.ROAD, rc, rr)
                elif not em[rr, rc]:
                    break

    # --- Phase 9: Wire to right zones ---
    for wr in wire_rows:
        if y_min <= wr <= y_max:
            for wc in range(wire_col + 1, right_col + 2):
                if wc >= WORLD_W:
                    break
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc] and not rm[wr, wc]:
                    break

    # --- Phase 10: Second power plant if needed ---
    plant_count = int(np.sum(pm)) // 9  # 3x3 footprint
    if pop > 300 and plant_count < 2:
        px2 = plant_cx + 20
        py2 = plant_cy
        if 2 <= px2 <= WORLD_W - 3 and 2 <= py2 <= WORLD_H - 3:
            if em[py2, px2]:
                return (Tool.COALPOWER, px2, py2)

    # --- Phase 11: Expand corridor vertically if population growing ---
    if pop > 150:
        new_y_min = max(1, cy - half - 4)
        new_y_max = min(WORLD_H - 2, cy + half + 4)
        if min_wr > new_y_min:
            nr = min_wr - 1
            if nr >= 0 and em[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)
        if max_wr < new_y_max:
            nr = max_wr + 1
            if nr < WORLD_H and em[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # --- Phase 12: Fill in zones that have coverage but were missed ---
    if pop > 100:
        for zr in range(y_min, y_max + 1, 3):
            for zc in [left_col - 4, right_col + 4]:
                zc_cl = max(2, min(WORLD_W - 3, zc))
                if not zone_exists_near(zr, zc_cl) and zone_area_ok(zr, zc_cl):
                    if wire_near(zr, zc_cl, 5) and road_near(zr, zc_cl, 5):
                        return (Tool.RESIDENTIAL, zc_cl, zr)

    # --- Phase 13: Horizontal roads to improve connectivity ---
    if pop > 200:
        for rr in [min_wr, max_wr]:
            if 0 <= rr < WORLD_H:
                for rc in range(left_col - 1, right_col + 2):
                    if 0 <= rc < WORLD_W and em[rr, rc] and not pm[rr, rc]:
                        return (Tool.ROAD, rc, rr)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder.
    Changes from parent:
    - More compact layout: road rows at spine±3, zones fill between
    - Build roads BEFORE wires so zones get road access sooner
    - Zone placement: scan systematically near existing roads
    - Wire extends from plant directly to each zone column
    - Second power plant earlier (>6 zones)
    - Services earlier
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    CX, CY = 25, 50

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    zone_set = set()
    for arr_y, arr_x in [(np.where(resm)), (np.where(comm)), (np.where(indm))]:
        for r, c in zip(arr_y, arr_x):
            zone_set.add((int(r), int(c)))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        r = res_count / t
        c = com_count / t
        i = ind_count / t
        if c < 0.25:
            return Tool.COMMERCIAL
        if i < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    # --- Step 1: Place coal power plant ---
    if not np.any(pm):
        return (Tool.COALPOWER, CX, CY)

    plant_ys, plant_xs = np.where(pm)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    road_ys, road_xs = np.where(rm)
    wire_ys, wire_xs = np.where(wm)

    spine_y = py
    road_top = spine_y - 3
    road_bot = spine_y + 3
    road_start = px + 4
    road_end = min(px + 60, WORLD_W - 4)

    # --- Step 2: Build top road row first (road access before wires) ---
    for rx in range(road_start, road_end + 1):
        ry = road_top
        if not in_bounds(rx, ry):
            break
        if not bool(rm[ry, rx]) and not bool(pm[ry, rx]):
            if bool(em[ry, rx]):
                return (Tool.ROAD, rx, ry)
            break  # blocked, stop

    # --- Step 3: Build bottom road row ---
    for rx in range(road_start, road_end + 1):
        ry = road_bot
        if not in_bounds(rx, ry):
            break
        if not bool(rm[ry, rx]) and not bool(pm[ry, rx]):
            if bool(em[ry, rx]):
                return (Tool.ROAD, rx, ry)
            break

    # --- Step 4: Wire spine from plant rightward ---
    wire_end_x = road_end
    for wx in range(px + 2, wire_end_x + 1):
        wy = spine_y
        if not in_bounds(wx, wy):
            break
        if not bool(wm[wy, wx]) and not bool(pm[wy, wx]):
            if bool(em[wy, wx]) or bool(rm[wy, wx]):
                # Place wire even over roads (wire can go on roads)
                if bool(em[wy, wx]):
                    return (Tool.WIRE, wx, wy)
            break

    # --- Step 5: Vertical wire branches every 6 cols ---
    branch_cols = list(range(px + 6, wire_end_x + 1, 6))
    for bx in branch_cols:
        if not in_bounds(bx, spine_y):
            continue
        if not (bool(wm[spine_y, bx]) or bool(pm[spine_y, bx])):
            continue
        for sign in [-1, 1]:
            for dy in range(1, 5):
                wy2, wx2 = spine_y + sign * dy, bx
                if not in_bounds(wx2, wy2):
                    break
                if bool(wm[wy2, wx2]) or bool(pm[wy2, wx2]):
                    continue
                if bool(em[wy2, wx2]):
                    return (Tool.WIRE, wx2, wy2)
                break

    # --- Step 6: Zone placement near roads and wires ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Scan by column then row for determinism
        best = None
        best_score = -1
        step_mod = obs.step % max(len(cxs), 1)
        for offset in range(min(len(cxs), 60)):
            k = (step_mod + offset * 7) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                # Prefer locations close to spine
                score = 100 - abs(zy - spine_y)
                if score > best_score:
                    best_score = score
                    best = (zx, zy)
        if best is not None:
            return (pick_tool(), best[0], best[1])

    # --- Step 7: Second power plant when >6 zones or pop > 200 ---
    if total_zones > 6 or obs.city_pop > 200:
        p2x = min(px + 52, WORLD_W - 5)
        p2y = py
        nearby_plant = any(
            in_bounds(p2x + dx, p2y + dy) and bool(pm[p2y + dy, p2x + dx])
            for dy in range(-5, 6) for dx in range(-5, 6)
        )
        if not nearby_plant and in_bounds(p2x, p2y) and bool(em[p2y, p2x]):
            return (Tool.COALPOWER, p2x, p2y)

    # --- Step 8: Services ---
    if obs.city_pop > 50:
        fx, fy = px + 4, py - 9
        if in_bounds(fx, fy) and bool(em[fy, fx]):
            return (Tool.FIRESTATION, fx, fy)
        px2, py2 = px + 4, py + 9
        if in_bounds(px2, py2) and bool(em[py2, px2]):
            return (Tool.POLICESTATION, px2, py2)

    # --- Step 9: Extend roads from frontier ---
    if len(road_xs) > 0:
        step_k = int(obs.step * 13) % max(len(road_xs), 1)
        rx_s, ry_s = int(road_xs[step_k]), int(road_ys[step_k])
        for dx2, dy2 in [(1, 0), (0, 1), (-1, 0), (0, -1)]:
            nx2, ny2 = rx_s + dx2, ry_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # --- Step 10: Extend wires from frontier ---
    if len(wire_xs) > 0:
        step_k2 = int(obs.step * 11) % max(len(wire_xs), 1)
        wx_s, wy_s = int(wire_xs[step_k2]), int(wire_ys[step_k2])
        for dx2, dy2 in [(1, 0), (0, 1), (-1, 0), (0, -1)]:
            nx2, ny2 = wx_s + dx2, wy_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Revised policy: horizontal road spine, vertical wire columns, compact grid layout.
    - Coal power plant placed left-center
    - Horizontal road spines at regular row intervals
    - Vertical wire column connecting plant to roads
    - Zones placed in a grid pattern between roads
    - Mix of R/C/I zones
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    # Use state to track build queue
    if 'phase' not in state:
        state['phase'] = 0
        state['built'] = set()

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Layout constants - horizontal road spines, vertical wire
    # Plant at left side, center height
    plant_x = 15
    plant_y = 50

    # Two horizontal road rows above and below center
    road_rows = [44, 50, 56]  # three horizontal roads
    wire_col = 22  # vertical wire spine connecting plant to roads

    # Zone columns between road rows
    # Zones placed at cols 25..100 every 4 cols, rows between road rows
    zone_cols = list(range(25, 95, 4))

    # Phase 1: Place coal power plant
    if not np.any(pm):
        return (Tool.COALPOWER, plant_x, plant_y)

    # Find plant location
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Phase 2: Build vertical wire from plant to road rows
    # Wire column connects plant to the horizontal road network
    wire_target_rows = list(range(min(road_rows) - 2, max(road_rows) + 3))
    for wr in wire_target_rows:
        if 0 <= wr < WORLD_H and 0 <= wire_col < WORLD_W:
            if not wm[wr, wire_col] and not pm[wr, wire_col]:
                if em[wr, wire_col]:
                    return (Tool.WIRE, wire_col, wr)

    # Also wire from plant to wire_col horizontally
    # Plant is at plant_cx, plant_cy - wire horizontally from plant right edge to wire_col
    plant_right = plant_cx + 2  # right edge of 4x4 plant
    for wc in range(plant_right, wire_col + 1):
        if 0 <= wc < WORLD_W:
            if not wm[plant_cy, wc] and not pm[plant_cy, wc]:
                if em[plant_cy, wc]:
                    return (Tool.WIRE, wc, plant_cy)

    # Phase 3: Build horizontal roads
    road_start_col = wire_col  # roads start at wire column
    road_end_col = max(zone_cols) + 3

    for rr in road_rows:
        for rc in range(road_start_col, road_end_col + 1):
            if 0 <= rc < WORLD_W and 0 <= rr < WORLD_H:
                if not rm[rr, rc] and not pm[rr, rc]:
                    if em[rr, rc]:
                        return (Tool.ROAD, rc, rr)

    # Phase 4: Build vertical wire columns at intervals to power zones
    # Wire columns every 8 cols from wire_col
    power_wire_cols = [wire_col + i for i in range(0, road_end_col - wire_col + 1, 8)]

    for pwc in power_wire_cols:
        if 0 <= pwc < WORLD_W:
            for wr in range(min(road_rows) - 1, max(road_rows) + 2):
                if 0 <= wr < WORLD_H:
                    if not wm[wr, pwc] and not pm[wr, pwc] and not rm[wr, pwc]:
                        if em[wr, pwc]:
                            return (Tool.WIRE, pwc, wr)

    # Phase 5: Place zones in grid between road rows
    # Zone rows: between road_rows[0] and road_rows[1], and between road_rows[1] and road_rows[2]
    zone_row_bands = [
        (road_rows[0] + 3, road_rows[1] - 3),  # between first and second road
        (road_rows[1] + 3, road_rows[2] - 3),  # between second and third road
    ]

    all_zone_mask = resm | comm | indm

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=6):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        # Target mix: 50% R, 30% C, 20% I
        if com_count / t < 0.30:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Place zones in bands around road rows
    for band_min, band_max in zone_row_bands:
        # Zone center rows: just above and below center of band
        for zr in [road_rows[0] - 3, road_rows[1], road_rows[2] + 3,
                   road_rows[0] - 3, road_rows[1], road_rows[2] + 3]:
            # Try a single center row for each band
            pass

    # Actually place zones: center row of each band
    zone_center_rows = []
    zone_center_rows.append(road_rows[0] - 3)  # above first road
    zone_center_rows.append((road_rows[0] + road_rows[1]) // 2)  # between 1st and 2nd
    zone_center_rows.append((road_rows[1] + road_rows[2]) // 2)  # between 2nd and 3rd
    zone_center_rows.append(road_rows[2] + 3)  # below last road

    for zr in zone_center_rows:
        if not (1 <= zr <= WORLD_H - 2):
            continue
        for zc in zone_cols:
            if not (1 <= zc <= WORLD_W - 2):
                continue
            if zone_already_there(zr, zc):
                continue
            if not zone_area_ok(zr, zc):
                continue
            if has_road_nearby(zr, zc, 5) and has_wire_nearby(zr, zc, 8):
                return (pick_tool(), zc, zr)

    # Phase 6: Second power plant if needed
    if obs.city_pop > 200 and int(np.sum(pm)) < 18:
        px2 = plant_cx + 25
        py2 = plant_cy
        if 2 <= px2 <= WORLD_W - 3 and 2 <= py2 <= WORLD_H - 3:
            if em[py2, px2]:
                return (Tool.COALPOWER, px2, py2)

    # Phase 7: Add more road rows for expansion
    if obs.city_pop > 100:
        extra_roads = [road_rows[0] - 6, road_rows[2] + 6]
        for rr in extra_roads:
            if 0 <= rr < WORLD_H:
                for rc in range(road_start_col, road_end_col + 1):
                    if 0 <= rc < WORLD_W and not rm[rr, rc] and not pm[rr, rc]:
                        if em[rr, rc]:
                            return (Tool.ROAD, rc, rr)

    # Phase 8: Add vertical roads to connect horizontal roads
    if obs.city_pop > 50:
        vert_road_cols = list(range(wire_col + 4, road_end_col, 12))
        for vrc in vert_road_cols:
            if 0 <= vrc < WORLD_W:
                for vr in range(min(road_rows) - 6, max(road_rows) + 7):
                    if 0 <= vr < WORLD_H and not rm[vr, vrc] and not pm[vr, vrc]:
                        if em[vr, vrc]:
                            return (Tool.ROAD, vrc, vr)

    return None

def act(obs, state):
    """
    Improved city builder with:
    - Two neighborhoods (left and right clusters)
    - Better wire connectivity (wires adjacent to zones, not just spine)
    - Roads at spine_y-3 and spine_y+3 with vertical connectors
    - Balanced zone mix: RES/COM/IND in ratio ~50/25/25
    - Second power plant placed earlier
    - Services placed earlier
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Two cluster anchors
    CX1, CY1 = 25, 45   # left cluster
    CX2, CY2 = 75, 45   # right cluster

    def find_plant_centers():
        ys, xs = np.where(pm)
        if len(xs) == 0:
            return []
        # group into clusters by proximity
        centers = []
        visited = set()
        for i in range(len(xs)):
            if i in visited:
                continue
            gx, gy = [xs[i]], [ys[i]]
            for j in range(len(xs)):
                if j != i and abs(int(xs[j])-int(xs[i])) < 5 and abs(int(ys[j])-int(ys[i])) < 5:
                    gx.append(xs[j]); gy.append(ys[j]); visited.add(j)
            visited.add(i)
            centers.append((int(np.mean(gx)), int(np.mean(gy))))
        return centers

    plant_centers = find_plant_centers()
    has_plant1 = any(abs(px-CX1)<6 and abs(py-CY1)<6 for px,py in plant_centers)
    has_plant2 = any(abs(px-CX2)<6 and abs(py-CY2)<6 for px,py in plant_centers)

    # Step 1: Place first power plant
    if not has_plant1:
        return (Tool.COALPOWER, CX1, CY1)

    # Step 2: Place second power plant early (after step 30)
    if not has_plant2 and obs.step > 30:
        return (Tool.COALPOWER, CX2, CY2)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    zone_set = set(zip(
        np.concatenate([np.where(resm)[0], np.where(comm)[0], np.where(indm)[0]]).tolist(),
        np.concatenate([np.where(resm)[1], np.where(comm)[1], np.where(indm)[1]]).tolist()
    ))

    def pick_tool():
        t = max(total_zones, 1)
        r = res_count / t
        c = com_count / t
        i = ind_count / t
        if c < 0.25:
            return Tool.COMMERCIAL
        if i < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    # Build infrastructure for each cluster
    def build_cluster_infra(cx, cy):
        """Return action to build wire/road for cluster centered at (cx,cy)"""
        spine_y = cy
        road_top = spine_y - 3
        road_bot = spine_y + 3

        # Wire spine horizontally from plant
        wire_start = cx + 3
        wire_end = min(cx + 30, WORLD_W - 4)
        for wx in range(wire_start, wire_end + 1):
            wy = spine_y
            if not in_bounds(wx, wy):
                break
            if not bool(wm[wy, wx]) and not bool(pm[wy, wx]):
                if bool(em[wy, wx]):
                    return (Tool.WIRE, wx, wy)
                break

        # Vertical wire branches every 6 cols
        for bx in range(wire_start + 3, wire_end + 1, 6):
            if not in_bounds(bx, spine_y):
                continue
            if not (bool(wm[spine_y, bx]) or bool(pm[spine_y, bx])):
                continue
            for sign in [-1, 1]:
                for dy in range(1, 5):
                    wy2, wx2 = spine_y + sign * dy, bx
                    if not in_bounds(wx2, wy2):
                        break
                    if bool(wm[wy2, wx2]) or bool(pm[wy2, wx2]):
                        continue
                    if bool(em[wy2, wx2]):
                        return (Tool.WIRE, wx2, wy2)
                    break

        # Road top row
        road_start = cx + 3
        road_end2 = min(cx + 28, WORLD_W - 4)
        for rx in range(road_start, road_end2 + 1):
            ry = road_top
            if not in_bounds(rx, ry):
                break
            if not bool(rm[ry, rx]) and not bool(pm[ry, rx]) and not bool(wm[ry, rx]):
                if bool(em[ry, rx]):
                    return (Tool.ROAD, rx, ry)
                break

        # Road bottom row
        for rx in range(road_start, road_end2 + 1):
            ry = road_bot
            if not in_bounds(rx, ry):
                break
            if not bool(rm[ry, rx]) and not bool(pm[ry, rx]) and not bool(wm[ry, rx]):
                if bool(em[ry, rx]):
                    return (Tool.ROAD, rx, ry)
                break

        # Vertical connector roads every 6 cols
        for vc in range(road_start, road_end2 + 1, 6):
            for vr in range(road_top, road_bot + 1):
                if not in_bounds(vc, vr):
                    continue
                if not bool(rm[vr, vc]) and not bool(pm[vr, vc]) and not bool(wm[vr, vc]):
                    if bool(em[vr, vc]):
                        return (Tool.ROAD, vc, vr)

        return None

    # Build cluster 1 infra
    action = build_cluster_infra(CX1, CY1)
    if action:
        return action

    # Build cluster 2 infra only if plant2 exists
    if has_plant2:
        action = build_cluster_infra(CX2, CY2)
        if action:
            return action

    # ---- Zone placement near roads and wires ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        step_hash = int(obs.step * 17 + int(obs.city_pop * 3)) % max(len(cxs), 1)
        for offset in range(min(len(cxs), 60)):
            k = (step_hash + offset * 11) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # ---- Services ----
    if obs.city_pop > 50:
        # Fire station for cluster 1
        fx, fy = CX1 + 5, CY1 - 6
        if in_bounds(fx, fy) and bool(em[fy, fx]):
            return (Tool.FIRESTATION, fx, fy)
        # Police station for cluster 1
        px2, py2 = CX1 + 5, CY1 + 6
        if in_bounds(px2, py2) and bool(em[py2, px2]):
            return (Tool.POLICESTATION, px2, py2)

    if obs.city_pop > 200:
        # Services for cluster 2
        fx2, fy2 = CX2 + 5, CY2 - 6
        if in_bounds(fx2, fy2) and bool(em[fy2, fx2]):
            return (Tool.FIRESTATION, fx2, fy2)
        px3, py3 = CX2 + 5, CY2 + 6
        if in_bounds(px3, py3) and bool(em[py3, px3]):
            return (Tool.POLICESTATION, px3, py3)

    # ---- Connect the two clusters with a road ----
    # Road at CY1 between CX1+30 and CX2
    if has_plant2:
        connect_y = CY1
        for rx in range(CX1 + 30, CX2 + 3):
            if not in_bounds(rx, connect_y):
                break
            if not bool(rm[connect_y, rx]) and bool(em[connect_y, rx]):
                return (Tool.ROAD, rx, connect_y)
        # Wire along same row for connectivity
        for wx in range(CX1 + 30, CX2 + 3):
            if not in_bounds(wx, connect_y):
                break
            if not bool(wm[connect_y, wx]) and not bool(pm[connect_y, wx]) and not bool(rm[connect_y, wx]) and bool(em[connect_y, wx]):
                return (Tool.WIRE, wx, connect_y)

    return None

def act(obs, state):
    """
    Closed-loop policy: each step reads tile_map and places the most useful next tile.

    Layout concept:
    - Coal power plant at fixed anchor
    - Wire spine running vertically from plant
    - Road column 2 tiles right of wire spine
    - Zones placed between wire and road (left) and right of road
    - Lateral wires connect left zones to spine
    - Lateral roads connect right zones to road

    Fully reactive: every decision based on current tile_map state.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # Fixed anchor positions
    PLANT_X, PLANT_Y = 58, 50
    WIRE_COL = PLANT_X + 3   # 61
    ROAD_COL = WIRE_COL + 2  # 63
    LEFT_ZONE_COL = WIRE_COL - 3  # 58... but plant is there, use 55
    LEFT_ZONE_COL = 55
    RIGHT_ZONE_COL = ROAD_COL + 3  # 66

    # Step 1: Place power plant if missing
    if not np.any(pm):
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    # Locate actual plant center from plant_mask
    plant_rows, plant_cols = np.where(pm)
    if len(plant_rows) > 0:
        # Use centroid of plant tiles
        PLANT_Y = int(np.median(plant_rows))
        PLANT_X = int(np.median(plant_cols))
        WIRE_COL = PLANT_X + 3
        ROAD_COL = WIRE_COL + 2
        LEFT_ZONE_COL = PLANT_X - 3
        RIGHT_ZONE_COL = ROAD_COL + 3

    # Helper: is a tile part of the plant footprint?
    def is_plant(r, c):
        return (0 <= r < WORLD_H and 0 <= c < WORLD_W and pm[r, c])

    # Helper: safe to place wire (not on plant)
    def can_wire(r, c):
        if r < 0 or r >= WORLD_H or c < 0 or c >= WORLD_W:
            return False
        if is_plant(r, c):
            return False
        return True

    # Step 2: Ensure wire is adjacent to plant (bridge plant to wire spine)
    # Connect plant right edge to wire column
    bridge_row = PLANT_Y
    # Wire from PLANT_X+2 to WIRE_COL
    for c in range(PLANT_X + 2, WIRE_COL + 1):
        if can_wire(bridge_row, c) and not wm[bridge_row, c]:
            return (Tool.WIRE, c, bridge_row)

    # Step 3: Grow wire spine vertically (reactive: extend from existing wire)
    wire_in_col = [(r, c) for r, c in zip(*np.where(wm)) if c == WIRE_COL]
    if not wire_in_col:
        if can_wire(PLANT_Y, WIRE_COL):
            return (Tool.WIRE, WIRE_COL, PLANT_Y)
    else:
        wire_rows_in_col = sorted([r for r, c in wire_in_col])
        target_min = max(2, PLANT_Y - 20)
        target_max = min(WORLD_H - 3, PLANT_Y + 20)
        cur_min = wire_rows_in_col[0]
        cur_max = wire_rows_in_col[-1]
        # Extend down
        if cur_max < target_max:
            nr = cur_max + 1
            if can_wire(nr, WIRE_COL):
                return (Tool.WIRE, WIRE_COL, nr)
        # Extend up
        if cur_min > target_min:
            nr = cur_min - 1
            if can_wire(nr, WIRE_COL):
                return (Tool.WIRE, WIRE_COL, nr)

    # Current wire spine rows
    wire_spine_rows = sorted([r for r, c in zip(*np.where(wm)) if c == WIRE_COL])
    if not wire_spine_rows:
        return None

    # Step 4: Build road column adjacent to wire spine (reactive)
    for wr in wire_spine_rows:
        if 0 <= ROAD_COL < WORLD_W and not rm[wr, ROAD_COL]:
            # Also need ROAD_COL-1 to be non-plant (gap tile is ok)
            return (Tool.ROAD, ROAD_COL, wr)

    road_rows_in_col = sorted([r for r, c in zip(*np.where(rm)) if c == ROAD_COL])

    # Step 5: Place lateral wires from spine to left zone positions
    # For every wire spine row, connect wire from WIRE_COL-1 down to LEFT_ZONE_COL
    for wr in wire_spine_rows:
        for c in range(WIRE_COL - 1, LEFT_ZONE_COL - 1, -1):
            if can_wire(wr, c) and not wm[wr, c] and not rm[wr, c]:
                return (Tool.WIRE, c, wr)

    # Step 6: Extend road right to RIGHT_ZONE_COL for each road row
    for rr in road_rows_in_col:
        for c in range(ROAD_COL + 1, RIGHT_ZONE_COL + 2):
            if 0 <= c < WORLD_W and not rm[rr, c] and not is_plant(rr, c):
                return (Tool.ROAD, c, rr)

    # Step 7: Place zones reactively
    res_count = int(np.sum(res_m))
    com_count = int(np.sum(com_m))
    ind_count = int(np.sum(ind_m))
    all_zone = res_m | com_m | ind_m

    def zone_area_free(zr, zc):
        """Check 3x3 footprint is clear of plants and existing zones."""
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                r2, c2 = zr + dr, zc + dc
                if r2 < 0 or r2 >= WORLD_H or c2 < 0 or c2 >= WORLD_W:
                    return False
                if pm[r2, c2]:
                    return False
                if all_zone[r2, c2]:
                    return False
        return True

    def has_wire_nearby(zr, zc, radius=3):
        r0, r1 = max(0, zr - radius), min(WORLD_H, zr + radius + 1)
        c0, c1 = max(0, zc - radius), min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=3):
        r0, r1 = max(0, zr - radius), min(WORLD_H, zr + radius + 1)
        c0, c1 = max(0, zc - radius), min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    def pick_zone_type():
        total = res_count + com_count + ind_count + 1
        # Target: 50% RES, 30% COM, 20% IND
        if ind_count / total < 0.20:
            return Tool.INDUSTRIAL
        elif com_count / total < 0.30:
            return Tool.COMMERCIAL
        else:
            return Tool.RESIDENTIAL

    # Zone rows: every 3 rows near wire spine
    zone_rows = list(range(max(2, min(wire_spine_rows) + 1), max(2, max(wire_spine_rows)), 3))

    for zr in zone_rows:
        # Left zone (needs wire nearby)
        zc = LEFT_ZONE_COL
        if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
            if zone_area_free(zr, zc) and has_wire_nearby(zr, zc) and has_road_nearby(zr, zc):
                return (pick_zone_type(), zc, zr)

        # Right zone (needs road nearby)
        zc = RIGHT_ZONE_COL
        if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
            if zone_area_free(zr, zc) and has_wire_nearby(zr, zc) and has_road_nearby(zr, zc):
                zt = Tool.COMMERCIAL if (com_count / (res_count + 1)) < 0.6 else Tool.RESIDENTIAL
                return (zt, zc, zr)

    # Step 8: If population growing, expand wire spine further
    pop = obs.city_pop
    extra_range = 5 + int(pop / 100)
    target_min2 = max(2, PLANT_Y - 20 - extra_range)
    target_max2 = min(WORLD_H - 3, PLANT_Y + 20 + extra_range)
    if wire_spine_rows:
        if wire_spine_rows[0] > target_min2:
            nr = wire_spine_rows[0] - 1
            if can_wire(nr, WIRE_COL):
                return (Tool.WIRE, WIRE_COL, nr)
        if wire_spine_rows[-1] < target_max2:
            nr = wire_spine_rows[-1] + 1
            if can_wire(nr, WIRE_COL):
                return (Tool.WIRE, WIRE_COL, nr)

    # Step 9: Place extra zones in extended area
    extended_rows = list(range(max(2, PLANT_Y - 25), min(WORLD_H - 2, PLANT_Y + 26), 3))
    for zr in extended_rows:
        for zc in [LEFT_ZONE_COL, RIGHT_ZONE_COL, LEFT_ZONE_COL - 4, RIGHT_ZONE_COL + 4]:
            if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                if zone_area_free(zr, zc) and has_wire_nearby(zr, zc, 4) and has_road_nearby(zr, zc, 4):
                    return (pick_zone_type(), zc, zr)

    # Step 10: Add nuclear plant if large
    if pop > 800:
        nuke_x, nuke_y = PLANT_X - 7, PLANT_Y + 8
        if 1 <= nuke_y < WORLD_H - 2 and 1 <= nuke_x < WORLD_W - 2:
            if not np.any(pm[nuke_y - 1:nuke_y + 2, nuke_x - 1:nuke_x + 2]):
                if not np.any(all_zone[nuke_y - 1:nuke_y + 2, nuke_x - 1:nuke_x + 2]):
                    return (Tool.NUCLEARPOWER, nuke_x, nuke_y)

    return None

def act(obs, state):
    """
    Variation: Two-neighborhood layout with a central power plant.
    Neighborhood 1 (left cluster): res+ind zones, wire spine, vertical road
    Neighborhood 2 (right cluster): res+com zones, wire spine, vertical road
    Both connected to same coal plant via horizontal wire bridge.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    has_plant = np.any(pm)
    res_count = np.sum(res_mask(tm))
    com_count = np.sum(com_mask(tm))
    ind_count = np.sum(ind_mask(tm))

    road_positions = list(zip(*np.where(rm)))

    # Power plant center at (cx, cy)
    plant_x, plant_y = cx, cy

    # Left cluster: wire spine at cx-8, road at cx-10, zones centered at cx-13 and cx-6
    # Right cluster: wire spine at cx+8, road at cx+10, zones centered at cx+5 and cx+13

    left_wire_col = cx - 8
    left_road_col = cx - 10
    left_zone_col_a = cx - 13  # left of road
    left_zone_col_b = cx - 5   # right of wire (between wire and plant)

    right_wire_col = cx + 8
    right_road_col = cx + 10
    right_zone_col_a = cx + 5  # left of wire (between plant and wire)
    right_zone_col_b = cx + 13 # right of road

    # Zone rows: centered around cy, spaced by 3
    zone_rows = list(range(max(1, cy - 12), min(WORLD_H - 2, cy + 13), 3))

    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def has_zone_near(zr, zc):
        rm2 = res_mask(tm)
        cm2 = com_mask(tm)
        im2 = ind_mask(tm)
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                rr, rc = zr+dr, zc+dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if rm2[rr, rc] or cm2[rr, rc] or im2[rr, rc]:
                        return True
        return False

    # Phase 1: Place coal power plant
    if not has_plant:
        return (Tool.COALPOWER, plant_x, plant_y)

    # Phase 2: Build horizontal wire bridge from plant to left wire spine
    # Plant footprint: px-1..px+1, py-1..py+1 (3x3 centered at plant_x, plant_y)
    # Wire from plant_x-2 leftward to left_wire_col at cy
    bridge_y = cy
    for wc in range(plant_x - 2, left_wire_col - 1, -1):
        if 0 <= wc < WORLD_W and not wm[bridge_y, wc] and em[bridge_y, wc]:
            return (Tool.WIRE, wc, bridge_y)

    # Phase 3: Build horizontal wire bridge from plant to right wire spine
    for wc in range(plant_x + 2, right_wire_col + 1):
        if 0 <= wc < WORLD_W and not wm[bridge_y, wc] and em[bridge_y, wc]:
            return (Tool.WIRE, wc, bridge_y)

    # Phase 4: Extend left wire spine vertically
    left_wire_rows = sorted([r for (r, c) in zip(*np.where(wm)) if c == left_wire_col])
    target_min = max(0, cy - 13)
    target_max = min(WORLD_H - 1, cy + 13)

    if not left_wire_rows:
        if em[cy, left_wire_col]:
            return (Tool.WIRE, left_wire_col, cy)
    else:
        min_r = min(left_wire_rows)
        max_r = max(left_wire_rows)
        if max_r < target_max:
            nr = max_r + 1
            if em[nr, left_wire_col] or wm[nr, left_wire_col]:
                return (Tool.WIRE, left_wire_col, nr)
        if min_r > target_min:
            nr = min_r - 1
            if em[nr, left_wire_col] or wm[nr, left_wire_col]:
                return (Tool.WIRE, left_wire_col, nr)

    # Phase 5: Extend right wire spine vertically
    right_wire_rows = sorted([r for (r, c) in zip(*np.where(wm)) if c == right_wire_col])

    if not right_wire_rows:
        if em[cy, right_wire_col]:
            return (Tool.WIRE, right_wire_col, cy)
    else:
        min_r = min(right_wire_rows)
        max_r = max(right_wire_rows)
        if max_r < target_max:
            nr = max_r + 1
            if em[nr, right_wire_col] or wm[nr, right_wire_col]:
                return (Tool.WIRE, right_wire_col, nr)
        if min_r > target_min:
            nr = min_r - 1
            if em[nr, right_wire_col] or wm[nr, right_wire_col]:
                return (Tool.WIRE, right_wire_col, nr)

    # Phase 6: Build left road column
    left_wire_rows_set = set(left_wire_rows)
    for r in sorted(left_wire_rows_set):
        if 0 <= left_road_col < WORLD_W and 0 <= r < WORLD_H:
            if not rm[r, left_road_col] and em[r, left_road_col]:
                return (Tool.ROAD, left_road_col, r)

    # Phase 7: Build right road column
    right_wire_rows_set = set(right_wire_rows)
    for r in sorted(right_wire_rows_set):
        if 0 <= right_road_col < WORLD_W and 0 <= r < WORLD_H:
            if not rm[r, right_road_col] and em[r, right_road_col]:
                return (Tool.ROAD, right_road_col, r)

    # Phase 8: Place zones - left cluster
    for zr in zone_rows:
        left_wire_near = any(abs(zr - wr) <= 2 for wr in left_wire_rows)
        left_road_near = any(abs(zr - rr) <= 2 for (rr, rc) in road_positions if rc == left_road_col)

        if left_wire_near and left_road_near:
            # Zone column A (left of road, needs road access)
            zc = left_zone_col_a
            if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                if not has_zone_near(zr, zc) and zone_area_free(zr, zc):
                    if ind_count < max(1, res_count // 3):
                        return (Tool.INDUSTRIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

            # Zone column B (right of wire, toward center)
            zc = left_zone_col_b
            if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                if not has_zone_near(zr, zc) and zone_area_free(zr, zc):
                    return (Tool.RESIDENTIAL, zc, zr)

    # Phase 9: Place zones - right cluster
    for zr in zone_rows:
        right_wire_near = any(abs(zr - wr) <= 2 for wr in right_wire_rows)
        right_road_near = any(abs(zr - rr) <= 2 for (rr, rc) in road_positions if rc == right_road_col)

        if right_wire_near and right_road_near:
            # Zone column A (left of wire, toward center)
            zc = right_zone_col_a
            if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                if not has_zone_near(zr, zc) and zone_area_free(zr, zc):
                    if com_count < max(1, res_count // 3):
                        return (Tool.COMMERCIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

            # Zone column B (right of road)
            zc = right_zone_col_b
            if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                if not has_zone_near(zr, zc) and zone_area_free(zr, zc):
                    if com_count < max(1, res_count // 2):
                        return (Tool.COMMERCIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

    # Phase 10: Lateral wires to reach zones that aren't near main spine
    # Left cluster: connect left_zone_col_b to left_wire_col
    for zr in zone_rows:
        if zr in left_wire_rows_set or any(abs(zr - wr) <= 0 for wr in left_wire_rows):
            for wc in range(left_wire_col + 1, left_zone_col_b + 1):
                if 0 <= wc < WORLD_W and em[zr, wc] and not wm[zr, wc]:
                    return (Tool.WIRE, wc, zr)

    # Right cluster: connect right_zone_col_a to right_wire_col
    for zr in zone_rows:
        if zr in right_wire_rows_set or any(abs(zr - wr) <= 0 for wr in right_wire_rows):
            for wc in range(right_zone_col_a, right_wire_col):
                if 0 <= wc < WORLD_W and em[zr, wc] and not wm[zr, wc]:
                    return (Tool.WIRE, wc, zr)

    # Phase 11: Extend road to reach outer zone columns
    for zr in zone_rows:
        left_road_near = any(abs(zr - rr) <= 2 for (rr, rc) in road_positions if rc == left_road_col)
        if left_road_near:
            # Extend road left to reach left_zone_col_a
            for rc in range(left_road_col - 1, left_zone_col_a - 2, -1):
                if 0 <= rc < WORLD_W and em[zr, rc] and not rm[zr, rc]:
                    return (Tool.ROAD, rc, zr)
            # Extend road right toward center
            for rc in range(left_road_col + 1, left_zone_col_b + 2):
                if 0 <= rc < WORLD_W and em[zr, rc] and not rm[zr, rc]:
                    return (Tool.ROAD, rc, zr)

        right_road_near = any(abs(zr - rr) <= 2 for (rr, rc) in road_positions if rc == right_road_col)
        if right_road_near:
            for rc in range(right_road_col + 1, right_zone_col_b + 2):
                if 0 <= rc < WORLD_W and em[zr, rc] and not rm[zr, rc]:
                    return (Tool.ROAD, rc, zr)
            for rc in range(right_road_col - 1, right_zone_col_a - 2, -1):
                if 0 <= rc < WORLD_W and em[zr, rc] and not rm[zr, rc]:
                    return (Tool.ROAD, rc, zr)

    # Phase 12: If population growing, add more zones in extended rows
    if obs.city_pop > 200:
        ext_rows = list(range(max(1, cy - 20), min(WORLD_H - 2, cy + 21), 3))
        for zr in ext_rows:
            for zc in [left_zone_col_a, left_zone_col_b, right_zone_col_a, right_zone_col_b]:
                if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                    if not has_zone_near(zr, zc) and zone_area_free(zr, zc):
                        road_near = any(abs(zr - rr) <= 3 and abs(zc - rc2) <= 4
                                       for (rr, rc2) in road_positions)
                        if road_near:
                            if com_count < res_count // 2:
                                return (Tool.COMMERCIAL, zc, zr)
                            elif ind_count < res_count // 3:
                                return (Tool.INDUSTRIAL, zc, zr)
                            else:
                                return (Tool.RESIDENTIAL, zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map each step and places the next tile
    based on what's already there. Grows a compact city from a seed point.

    Strategy:
    - Phase 0: Place coal power plant at seed
    - Phase 1: Extend wires from power plant outward (BFS-like, reactive)
    - Phase 2: Place roads adjacent to wires
    - Phase 3: Place zones adjacent to roads (balanced R/C/I)
    - Phase 4: Add more infrastructure reactively
    """

    # Seed location - center-left of map
    SEED_X, SEED_Y = 40, 50

    # Phase tracking
    if "phase" not in state:
        state["phase"] = 0
        state["step_in_phase"] = 0
        state["plant_placed"] = False
        state["zone_count"] = {"R": 0, "C": 0, "I": 0}

    tile_map = obs.tile_map
    step = obs.step

    # Helper: check bounds
    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Helper: is a tile empty?
    def is_empty(x, y):
        if not in_bounds(x, y):
            return False
        return empty_mask[y, x]

    # Helper: is a tile a road?
    def is_road(x, y):
        if not in_bounds(x, y):
            return False
        return road_mask[y, x]

    # Helper: is a tile wire?
    def is_wire(x, y):
        if not in_bounds(x, y):
            return False
        return wire_mask[y, x]

    # Helper: is a tile a power plant?
    def is_plant(x, y):
        if not in_bounds(x, y):
            return False
        return plant_mask[y, x]

    # Helper: is a tile a zone (R/C/I)?
    def is_zone(x, y):
        if not in_bounds(x, y):
            return False
        return res_mask[y, x] or com_mask[y, x] or ind_mask[y, x]

    # Helper: neighbors (4-directional)
    def neighbors4(x, y):
        for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
            nx, ny = x+dx, y+dy
            if in_bounds(nx, ny):
                yield nx, ny

    # Count existing plants
    plant_count = np.sum(plant_mask)
    wire_count = np.sum(wire_mask)
    road_count = np.sum(road_mask)
    zone_count = np.sum(res_mask) + np.sum(com_mask) + np.sum(ind_mask)

    # Step 1: Ensure we have at least one power plant
    # Place coal plant at seed if not present nearby
    # Check if plant exists near seed
    plant_near_seed = False
    for dy in range(-10, 11):
        for dx in range(-10, 11):
            cx, cy = SEED_X + dx, SEED_Y + dy
            if in_bounds(cx, cy) and plant_mask[cy, cx]:
                plant_near_seed = True
                state["plant_x"] = cx
                state["plant_y"] = cy
                break
        if plant_near_seed:
            break

    if not plant_near_seed:
        # Place coal power plant
        state["plant_x"] = SEED_X - 8
        state["plant_y"] = SEED_Y
        return (Tool.COALPOWER, SEED_X - 8, SEED_Y)

    plant_x = state.get("plant_x", SEED_X - 8)
    plant_y = state.get("plant_y", SEED_Y)

    # Step 2: If second plant needed (city growing large)
    if zone_count > 30 and plant_count < 2:
        # Place second plant on right side
        second_px = SEED_X + 32
        second_py = SEED_Y
        if in_bounds(second_px, second_py) and not plant_mask[second_py, second_px]:
            return (Tool.COALPOWER, second_px, second_py)

    # Step 3: Reactive wire extension from power plant
    # Find all powered (wire or plant) cells
    powered_cells = set()
    ys, xs = np.where(wire_mask | plant_mask)
    for y, x in zip(ys, xs):
        powered_cells.add((int(x), int(y)))

    # Find frontier: cells adjacent to powered that are empty or road (not yet wired)
    # Priority: extend wire along a spine first (horizontal then vertical branches)

    # Build a spine: horizontal wire from plant rightward to SEED_X+30
    # and vertical wires at intervals

    # Define the wire spine layout reactively:
    # Main horizontal spine at plant_y
    # Vertical branches every 8 cells

    # Check if main horizontal spine is complete
    spine_y = plant_y
    spine_start = plant_x
    spine_end = SEED_X + 35

    # Extend horizontal wire spine
    for wx in range(spine_start, spine_end + 1):
        if in_bounds(wx, spine_y) and not wire_mask[spine_y, wx] and not plant_mask[spine_y, wx]:
            # Check if adjacent to existing wire/plant
            adj_powered = False
            for nx, ny in neighbors4(wx, spine_y):
                if wire_mask[ny, nx] or plant_mask[ny, nx]:
                    adj_powered = True
                    break
            if adj_powered:
                return (Tool.WIRE, wx, spine_y)

    # Now extend vertical wire branches at x = plant_x+4, plant_x+12, plant_x+20, plant_x+28
    branch_xs = [plant_x + 4 + i*8 for i in range(6)]
    branch_xs = [bx for bx in branch_xs if bx <= spine_end]

    for bx in branch_xs:
        if not in_bounds(bx, spine_y):
            continue
        if not (wire_mask[spine_y, bx] or plant_mask[spine_y, bx]):
            continue
        # Extend wire upward and downward from spine
        for direction in [-1, 1]:
            for dist in range(1, 10):
                wy = spine_y + direction * dist
                if not in_bounds(bx, wy):
                    break
                if wire_mask[wy, bx] or plant_mask[wy, bx]:
                    continue
                # Check adjacent powered
                adj_powered = False
                for nx2, ny2 in neighbors4(bx, wy):
                    if wire_mask[ny2, nx2] or plant_mask[ny2, nx2]:
                        adj_powered = True
                        break
                if adj_powered:
                    return (Tool.WIRE, bx, wy)
                else:
                    break  # gap in wire, don't skip

    # Step 4: Place roads parallel to wire branches (one cell offset)
    # Road runs parallel to vertical wire branches, at bx+1
    for bx in branch_xs:
        road_x = bx + 1
        if not in_bounds(road_x, spine_y):
            continue
        # Road spine along vertical at road_x
        for direction in [-1, 1]:
            for dist in range(0, 9):
                ry2 = spine_y + direction * dist
                if not in_bounds(road_x, ry2):
                    break
                if road_mask[ry2, road_x]:
                    continue
                # Place road if wire exists at bx, ry2 or adjacent road
                wire_here = wire_mask[ry2, bx] if in_bounds(bx, ry2) else False
                adj_road = any(road_mask[ny2, nx2] for nx2, ny2 in neighbors4(road_x, ry2))
                if wire_here or adj_road or dist == 0:
                    # Check bounds ok
                    if in_bounds(road_x, ry2):
                        if not road_mask[ry2, road_x] and not plant_mask[ry2, road_x]:
                            return (Tool.ROAD, road_x, ry2)

    # Also add horizontal road along spine
    for rx2 in range(spine_start + 1, spine_end + 1):
        road_y = spine_y + 1  # one below spine wire
        if in_bounds(rx2, road_y) and not road_mask[road_y, rx2] and not plant_mask[road_y, rx2]:
            adj_road = any(road_mask[ny2, nx2] for nx2, ny2 in neighbors4(rx2, road_y))
            adj_wire = any(wire_mask[ny2, nx2] for nx2, ny2 in neighbors4(rx2, road_y))
            if adj_road or adj_wire:
                return (Tool.ROAD, rx2, road_y)

    # Step 5: Place zones adjacent to roads and wires reactively
    # Find all road cells, then try to place zones nearby
    road_ys, road_xs = np.where(road_mask)

    if len(road_xs) == 0:
        return None

    # Count current zones
    n_res = int(np.sum(res_mask))
    n_com = int(np.sum(com_mask))
    n_ind = int(np.sum(ind_mask))
    n_total = n_res + n_com + n_ind

    # Decide next zone type based on current ratio
    # Target: 50% R, 25% C, 25% I
    if n_total == 0:
        next_zone = Tool.RESIDENTIAL
    elif n_res < n_total * 0.5:
        next_zone = Tool.RESIDENTIAL
    elif n_com <= n_ind:
        next_zone = Tool.COMMERCIAL
    else:
        next_zone = Tool.INDUSTRIAL

    # Find a good spot for zone: 3x3, center must be placed
    # Zone center should be 2 away from road (so zone edge touches road)
    # and have wire within reach (zone edge touches wire)

    # Scan road cells and try zone centers at offset 2
    offsets = [(2,0),(-2,0),(0,2),(0,-2),(3,0),(-3,0),(0,3),(0,-3)]

    # Shuffle based on step for variety
    rng_seed = step % 8
    offsets_rotated = offsets[rng_seed:] + offsets[:rng_seed]

    best_spot = None

    for idx in range(min(len(road_xs), 50)):
        # Sample road cells: try spread across map
        sample_i = (step * 7 + idx * 13) % len(road_xs)
        rx2, ry2 = int(road_xs[sample_i]), int(road_ys[sample_i])

        for dx2, dy2 in offsets_rotated:
            zx, zy = rx2 + dx2, ry2 + dy2
            if not in_bounds(zx, zy):
                continue
            # Check 3x3 area around center is not blocked by plant/wire
            blocked = False
            for ddx in range(-1, 2):
                for ddy in range(-1, 2):
                    cx2, cy2 = zx + ddx, zy + ddy
                    if not in_bounds(cx2, cy2):
                        blocked = True
                        break
                    # Don't place on plant
                    if plant_mask[cy2, cx2]:
                        blocked = True
                        break
                if blocked:
                    break
            if blocked:
                continue

            # Check zone center not already a zone
            if is_zone(zx, zy):
                continue

            # Check adjacent road exists (for access)
            adj_road2 = False
            for ddx in range(-2, 3):
                for ddy in range(-2, 3):
                    cx2, cy2 = zx + ddx, zy + ddy
                    if in_bounds(cx2, cy2) and road_mask[cy2, cx2]:
                        adj_road2 = True
                        break
                if adj_road2:
                    break

            # Check adjacent wire exists (for power)
            adj_wire2 = False
            for ddx in range(-2, 3):
                for ddy in range(-2, 3):
                    cx2, cy2 = zx + ddx, zy + ddy
                    if in_bounds(cx2, cy2) and (wire_mask[cy2, cx2] or plant_mask[cy2, cx2]):
                        adj_wire2 = True
                        break
                if adj_wire2:
                    break

            if adj_road2 and adj_wire2:
                best_spot = (next_zone, zx, zy)
                break

        if best_spot:
            break

    if best_spot:
        return best_spot

    # Fallback: place services if we have zones
    if n_total > 10 and step % 30 == 0:
        # Place fire station near city center
        cx2, cy2 = SEED_X, SEED_Y - 12
        if in_bounds(cx2, cy2) and is_empty(cx2, cy2):
            return (Tool.FIRESTATION, cx2, cy2)

    if n_total > 20 and step % 40 == 0:
        cx2, cy2 = SEED_X + 10, SEED_Y - 12
        if in_bounds(cx2, cy2) and is_empty(cx2, cy2):
            return (Tool.POLICESTATION, cx2, cy2)

    # If stuck, try extending roads further out
    # Find road frontier and extend
    if len(road_xs) > 0:
        sample_i = step % len(road_xs)
        rx2, ry2 = int(road_xs[sample_i]), int(road_ys[sample_i])
        # Try to extend road
        for dx2, dy2 in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx2, ny2 = rx2 + dx2, ry2 + dy2
            if in_bounds(nx2, ny2) and not road_mask[ny2, nx2] and not plant_mask[ny2, nx2]:
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Improved policy with horizontal layout instead of vertical spine.
    Uses a horizontal road running east-west, with zones placed above and below.
    Two power plants for better coverage.
    More balanced zone mix: ~40% res, 30% com, 30% ind.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # Layout: horizontal road at row 50, wire at row 48
    # Zones above (rows 44-46) and below (rows 52-54)
    # Power plant at left side, connected via wire row

    wire_row = 50       # horizontal wire spine
    road_row = 52       # horizontal road
    top_zone_row = 46   # zones above wire
    bot_zone_row = 56   # zones below road

    plant1_cx, plant1_cy = 20, 50   # left power plant
    plant2_cx, plant2_cy = 80, 50   # right power plant (placed later)

    wire_positions = set(zip(*np.where(wm))) if np.any(wm) else set()
    road_positions = set(zip(*np.where(rm))) if np.any(rm) else set()
    res_positions = set(zip(*np.where(res_m))) if np.any(res_m) else set()
    com_positions = set(zip(*np.where(com_m))) if np.any(com_m) else set()
    ind_positions = set(zip(*np.where(ind_m))) if np.any(ind_m) else set()
    all_zones = res_positions | com_positions | ind_positions
    plant_positions = set(zip(*np.where(pm))) if np.any(pm) else set()

    res_count = len(res_positions)
    com_count = len(com_positions)
    ind_count = len(ind_positions)

    def has_plant_near(cx, cy, r=3):
        return any(abs(pr - cy) <= r and abs(pc - cx) <= r for (pr, pc) in plant_positions)

    # Phase 1: Place first power plant
    if not has_plant_near(plant1_cx, plant1_cy):
        return (Tool.COALPOWER, plant1_cx, plant1_cy)

    # Phase 2: Build horizontal wire spine from plant rightward
    wire_cols_in_row = sorted(c for (r, c) in wire_positions if r == wire_row)
    road_cols_in_row = sorted(c for (r, c) in road_positions if r == road_row)

    # Determine target horizontal extent based on population
    base_ext = 15
    extra_ext = min(40, obs.city_pop // 10)
    x_left = max(2, plant1_cx - 2)
    x_right = min(WORLD_W - 3, plant1_cx + base_ext + extra_ext)

    if obs.city_pop >= 300:
        x_right = min(WORLD_W - 3, 100)

    # Extend wire row leftward then rightward
    if not wire_cols_in_row:
        # Start wire adjacent to plant
        for tc in [plant1_cx + 3, plant1_cx + 2]:
            if 0 <= tc < WORLD_W and em[wire_row, tc]:
                return (Tool.WIRE, tc, wire_row)
    else:
        min_wc = min(wire_cols_in_row)
        max_wc = max(wire_cols_in_row)
        if max_wc < x_right:
            nc = max_wc + 1
            if 0 <= nc < WORLD_W and (em[wire_row, nc] or wm[wire_row, nc]):
                return (Tool.WIRE, nc, wire_row)
        if min_wc > x_left:
            nc = min_wc - 1
            if 0 <= nc < WORLD_W and (em[wire_row, nc] or wm[wire_row, nc]):
                return (Tool.WIRE, nc, wire_row)

    if not wire_cols_in_row:
        return None

    wire_cols_set = set(wire_cols_in_row)
    road_cols_set = set(road_cols_in_row)

    # Phase 3: Build horizontal road (row below wire)
    for wc in wire_cols_in_row:
        if wc not in road_cols_set and 0 <= road_row < WORLD_H:
            if em[road_row, wc]:
                return (Tool.ROAD, wc, road_row)

    # Helper: check 3x3 zone area free
    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def already_zone_nearby(zr, zc, zones):
        return any(abs(zr - pr) <= 2 and abs(zc - pc) <= 2 for (pr, pc) in zones)

    def pick_zone_type():
        # Target: 40% res, 30% com, 30% ind
        if res_count == 0:
            return Tool.RESIDENTIAL
        elif ind_count * 10 < res_count * 3:
            return Tool.INDUSTRIAL
        elif com_count * 10 < res_count * 3:
            return Tool.COMMERCIAL
        else:
            return Tool.RESIDENTIAL

    # Phase 4: Place zones above (top_zone_row) and below (bot_zone_row) along wire
    # Space zones every 3 columns
    for wc in sorted(wire_cols_in_row):
        # Check road access nearby (within 3 rows)
        road_near = any(abs(road_row - wire_row) <= 4 and wc in road_cols_set)
        if not road_near:
            road_near = wc in road_cols_set

        for zr in [top_zone_row, bot_zone_row]:
            if 2 <= zr < WORLD_H - 2 and 2 <= wc < WORLD_W - 2:
                if not already_zone_nearby(zr, wc, all_zones) and zone_area_free(zr, wc):
                    zt = pick_zone_type()
                    return (zt, wc, zr)

    # Phase 5: Vertical wires from spine to top zones
    for wc in wire_cols_in_row:
        if not any(abs(zr - top_zone_row) <= 2 and abs(zc - wc) <= 2 for (zr, zc) in all_zones):
            continue
        for wr in range(wire_row - 1, top_zone_row - 2, -1):
            if 0 <= wr < WORLD_H and em[wr, wc]:
                return (Tool.WIRE, wc, wr)

    # Phase 6: Vertical roads from road row to bottom zones
    for wc in road_cols_in_row:
        if not any(abs(zr - bot_zone_row) <= 2 and abs(zc - wc) <= 2 for (zr, zc) in all_zones):
            continue
        for wr in range(road_row + 1, bot_zone_row + 2):
            if 0 <= wr < WORLD_H and em[wr, wc]:
                return (Tool.ROAD, wc, wr)

    # Phase 7: Place second power plant when enough wire coverage
    if obs.city_pop >= 150 and not has_plant_near(plant2_cx, plant2_cy):
        # Connect second plant via wire horizontally first
        if wire_row in [r for (r, c) in wire_positions]:
            max_wc = max(wire_cols_in_row) if wire_cols_in_row else 0
            if max_wc >= plant2_cx - 5:
                return (Tool.COALPOWER, plant2_cx, plant2_cy)

    # Phase 8: Second horizontal cluster (different rows) for high pop
    if obs.city_pop >= 250:
        wire_row2 = 70
        road_row2 = 72
        top_zone_row2 = 66
        bot_zone_row2 = 76

        wire_cols2 = sorted(c for (r, c) in wire_positions if r == wire_row2)
        road_cols2 = set(c for (r, c) in road_positions if r == road_row2)

        # Connect wire row2 to plant2 vertically
        if not wire_cols2:
            # Build wire from plant2 downward
            for wr in range(plant2_cy + 3, wire_row2 + 1):
                if em[wr, plant2_cx]:
                    return (Tool.WIRE, plant2_cx, wr)
                elif wm[wr, plant2_cx]:
                    continue
                else:
                    break
        else:
            min_wc2 = min(wire_cols2)
            max_wc2 = max(wire_cols2)
            x_right2 = min(WORLD_W - 3, 100)
            x_left2 = max(2, 20)
            if max_wc2 < x_right2:
                nc = max_wc2 + 1
                if em[wire_row2, nc]:
                    return (Tool.WIRE, nc, wire_row2)
            if min_wc2 > x_left2:
                nc = min_wc2 - 1
                if em[wire_row2, nc]:
                    return (Tool.WIRE, nc, wire_row2)

            # Road row2
            for wc in wire_cols2:
                if wc not in road_cols2 and em[road_row2, wc]:
                    return (Tool.ROAD, wc, road_row2)

            # Zones around cluster 2
            for wc in sorted(wire_cols2):
                for zr in [top_zone_row2, bot_zone_row2]:
                    if 2 <= zr < WORLD_H - 2 and 2 <= wc < WORLD_W - 2:
                        if not already_zone_nearby(zr, wc, all_zones) and zone_area_free(zr, wc):
                            zt = pick_zone_type()
                            return (zt, wc, zr)

    # Phase 9: Third cluster above main for very high pop
    if obs.city_pop >= 500:
        wire_row3 = 30
        road_row3 = 32
        top_zone_row3 = 26
        bot_zone_row3 = 36

        wire_cols3 = sorted(c for (r, c) in wire_positions if r == wire_row3)
        road_cols3 = set(c for (r, c) in road_positions if r == road_row3)

        if not wire_cols3:
            for wr in range(plant1_cy - 3, wire_row3 - 1, -1):
                if em[wr, plant1_cx]:
                    return (Tool.WIRE, plant1_cx, wr)
        else:
            min_wc3 = min(wire_cols3)
            max_wc3 = max(wire_cols3)
            if max_wc3 < 100:
                nc = max_wc3 + 1
                if em[wire_row3, nc]:
                    return (Tool.WIRE, nc, wire_row3)
            if min_wc3 > 20:
                nc = min_wc3 - 1
                if em[wire_row3, nc]:
                    return (Tool.WIRE, nc, wire_row3)

            for wc in wire_cols3:
                if wc not in road_cols3 and em[road_row3, wc]:
                    return (Tool.ROAD, wc, road_row3)

            for wc in sorted(wire_cols3):
                for zr in [top_zone_row3, bot_zone_row3]:
                    if 2 <= zr < WORLD_H - 2 and 2 <= wc < WORLD_W - 2:
                        if not already_zone_nearby(zr, wc, all_zones) and zone_area_free(zr, wc):
                            zt = pick_zone_type()
                            return (zt, wc, zr)

    return None

def act(obs, state):
    """
    Variation: Horizontal wire spine instead of vertical, with zones above/below.
    Two power plants side by side. Roads run horizontally, zones stack vertically.
    This creates a very different city shape (horizontal band vs vertical column).
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def zone_area_free(cy, cx):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, cc = cy + dr, cx + dc
                if not in_bounds(cc, rr):
                    return False
                if not bool(em[rr, cc]):
                    return False
        return True

    # Power plant positions - two plants spaced horizontally
    P1X, P1Y = 40, 50
    P2X, P2Y = 70, 50

    plant_ys, plant_xs = np.where(pm)
    has_plant1 = any(abs(px_ - P1X) <= 5 and abs(py_ - P1Y) <= 5
                     for py_, px_ in zip(plant_ys.tolist(), plant_xs.tolist()))
    has_plant2 = any(abs(px_ - P2X) <= 5 and abs(py_ - P2Y) <= 5
                     for py_, px_ in zip(plant_ys.tolist(), plant_xs.tolist()))

    if not has_plant1:
        return (Tool.COALPOWER, P1X, P1Y)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))

    def pick_zone(cx):
        # Left side: industrial, middle: commercial, right: residential
        if cx < 45:
            if ind_count < res_count // 2 + 1:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL
        elif cx < 65:
            if com_count < res_count // 2 + 1:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            if ind_count < com_count:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    # Horizontal wire spine at row WIRE_ROW
    WIRE_ROW = 50
    ROAD_ROW_U = WIRE_ROW - 1  # road above spine
    ROAD_ROW_D = WIRE_ROW + 1  # road below spine

    # Zone rows above and below roads
    ZONE_ROWS_U = [WIRE_ROW - 4, WIRE_ROW - 7, WIRE_ROW - 10]
    ZONE_ROWS_D = [WIRE_ROW + 4, WIRE_ROW + 7, WIRE_ROW + 10]

    # Determine horizontal span based on population
    base_span = 15
    extra_span = min(35, obs.city_pop // 15)
    target_span = base_span + extra_span

    # Center span around plants
    center_col = (P1X + P2X) // 2
    col_min = max(2, center_col - target_span)
    col_max = min(WORLD_W - 3, center_col + target_span)

    wire_positions = set(zip(*np.where(wm))) if np.any(wm) else set()
    road_positions = set(zip(*np.where(rm))) if np.any(rm) else set()

    wire_cols_in_row = sorted(c for (r, c) in wire_positions if r == WIRE_ROW)

    # Extend horizontal wire spine
    if not wire_cols_in_row:
        # Start wire next to plant1
        sc = P1X + 2
        if in_bounds(sc, WIRE_ROW) and bool(em[WIRE_ROW, sc]):
            return (Tool.WIRE, sc, WIRE_ROW)
    else:
        min_wc = min(wire_cols_in_row)
        max_wc = max(wire_cols_in_row)
        if max_wc < col_max:
            nc = max_wc + 1
            if in_bounds(nc, WIRE_ROW) and bool(em[WIRE_ROW, nc]):
                return (Tool.WIRE, nc, WIRE_ROW)
        if min_wc > col_min:
            nc = min_wc - 1
            if in_bounds(nc, WIRE_ROW) and bool(em[WIRE_ROW, nc]):
                return (Tool.WIRE, nc, WIRE_ROW)

    wire_cols_set = set(wire_cols_in_row)
    road_cols_U = set(c for (r, c) in road_positions if r == ROAD_ROW_U)
    road_cols_D = set(c for (r, c) in road_positions if r == ROAD_ROW_D)

    # Build road rows adjacent to wire spine
    for wc in wire_cols_in_row:
        if wc not in road_cols_U and in_bounds(wc, ROAD_ROW_U) and bool(em[ROAD_ROW_U, wc]):
            return (Tool.ROAD, wc, ROAD_ROW_U)
        if wc not in road_cols_D and in_bounds(wc, ROAD_ROW_D) and bool(em[ROAD_ROW_D, wc]):
            return (Tool.ROAD, wc, ROAD_ROW_D)

    # Place zones above and below roads
    for wc in wire_cols_in_row:
        if wc < 2 or wc >= WORLD_W - 2:
            continue
        road_U_nearby = wc in road_cols_U or any(abs(wc - rc) <= 1 for rc in road_cols_U)
        road_D_nearby = wc in road_cols_D or any(abs(wc - rc) <= 1 for rc in road_cols_D)

        if road_U_nearby:
            for zr in ZONE_ROWS_U:
                if in_bounds(wc, zr) and 2 <= zr < WORLD_H - 2:
                    if zone_area_free(zr, wc):
                        return (pick_zone(wc), wc, zr)

        if road_D_nearby:
            for zr in ZONE_ROWS_D:
                if in_bounds(wc, zr) and 2 <= zr < WORLD_H - 2:
                    if zone_area_free(zr, wc):
                        return (pick_zone(wc), wc, zr)

    # Vertical wires from spine to zone rows (power the zones)
    for wc in wire_cols_in_row:
        # Wire upward to zone rows
        for wr in range(WIRE_ROW - 1, WIRE_ROW - 12, -1):
            if not in_bounds(wc, wr):
                break
            if bool(wm[wr, wc]) or bool(pm[wr, wc]):
                break
            if bool(rm[wr, wc]):
                continue
            if bool(em[wr, wc]):
                return (Tool.WIRE, wc, wr)
            break
        # Wire downward to zone rows
        for wr in range(WIRE_ROW + 1, WIRE_ROW + 12):
            if not in_bounds(wc, wr):
                break
            if bool(wm[wr, wc]) or bool(pm[wr, wc]):
                break
            if bool(rm[wr, wc]):
                continue
            if bool(em[wr, wc]):
                return (Tool.WIRE, wc, wr)
            break

    # Phase 2: second plant and second horizontal corridor
    if obs.city_pop > 150:
        if not has_plant2:
            return (Tool.COALPOWER, P2X, P2Y)

        # Second corridor at a different row
        WIRE_ROW2 = 65
        ROAD_ROW2_U = WIRE_ROW2 - 1
        ROAD_ROW2_D = WIRE_ROW2 + 1
        ZONE_ROWS2_U = [WIRE_ROW2 - 4, WIRE_ROW2 - 7]
        ZONE_ROWS2_D = [WIRE_ROW2 + 4, WIRE_ROW2 + 7]

        wire_cols2 = sorted(c for (r, c) in wire_positions if r == WIRE_ROW2)
        road_cols2_U = set(c for (r, c) in road_positions if r == ROAD_ROW2_U)
        road_cols2_D = set(c for (r, c) in road_positions if r == ROAD_ROW2_D)

        # Connect P2 to wire row 2
        if not wire_cols2:
            sc2 = P2X + 2
            if in_bounds(sc2, WIRE_ROW2) and bool(em[WIRE_ROW2, sc2]):
                return (Tool.WIRE, sc2, WIRE_ROW2)
        else:
            min_wc2 = min(wire_cols2)
            max_wc2 = max(wire_cols2)
            col_max2 = min(WORLD_W - 3, P2X + target_span // 2)
            col_min2 = max(2, P2X - target_span // 2)
            if max_wc2 < col_max2:
                nc2 = max_wc2 + 1
                if in_bounds(nc2, WIRE_ROW2) and bool(em[WIRE_ROW2, nc2]):
                    return (Tool.WIRE, nc2, WIRE_ROW2)
            if min_wc2 > col_min2:
                nc2 = min_wc2 - 1
                if in_bounds(nc2, WIRE_ROW2) and bool(em[WIRE_ROW2, nc2]):
                    return (Tool.WIRE, nc2, WIRE_ROW2)

        for wc2 in wire_cols2:
            if wc2 not in road_cols2_U and in_bounds(wc2, ROAD_ROW2_U) and bool(em[ROAD_ROW2_U, wc2]):
                return (Tool.ROAD, wc2, ROAD_ROW2_U)
            if wc2 not in road_cols2_D and in_bounds(wc2, ROAD_ROW2_D) and bool(em[ROAD_ROW2_D, wc2]):
                return (Tool.ROAD, wc2, ROAD_ROW2_D)

        for wc2 in wire_cols2:
            if wc2 < 2 or wc2 >= WORLD_W - 2:
                continue
            road2_U_nearby = wc2 in road_cols2_U or any(abs(wc2 - rc) <= 1 for rc in road_cols2_U)
            road2_D_nearby = wc2 in road_cols2_D or any(abs(wc2 - rc) <= 1 for rc in road_cols2_D)
            if road2_U_nearby:
                for zr2 in ZONE_ROWS2_U:
                    if in_bounds(wc2, zr2) and 2 <= zr2 < WORLD_H - 2:
                        if zone_area_free(zr2, wc2):
                            return (pick_zone(wc2), wc2, zr2)
            if road2_D_nearby:
                for zr2 in ZONE_ROWS2_D:
                    if in_bounds(wc2, zr2) and 2 <= zr2 < WORLD_H - 2:
                        if zone_area_free(zr2, wc2):
                            return (pick_zone(wc2), wc2, zr2)

        # Connect plant2 corridor to main corridor via vertical wire
        connect_col = P2X
        for wr_v in range(min(WIRE_ROW, WIRE_ROW2), max(WIRE_ROW, WIRE_ROW2) + 1):
            if in_bounds(connect_col, wr_v) and bool(em[wr_v, connect_col]) and not bool(pm[wr_v, connect_col]):
                return (Tool.WIRE, connect_col, wr_v)

    # Services
    if obs.city_pop > 300:
        fx, fy = center_col, WIRE_ROW - 14
        if in_bounds(fx, fy) and zone_area_free(fy, fx):
            return (Tool.FIRESTATION, fx, fy)

    if obs.city_pop > 500:
        px2, py2 = center_col, WIRE_ROW + 14
        if in_bounds(px2, py2) and zone_area_free(py2, px2):
            return (Tool.POLICESTATION, px2, py2)

    # Fallback: extend roads
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = int(obs.step * 13) % max(len(road_xs), 1)
        rx_s, ry_s = int(road_xs[step_k]), int(road_ys[step_k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx_s + dx2, ry_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wires
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        step_k2 = int(obs.step * 7) % max(len(wire_xs), 1)
        wx_s, wy_s = int(wire_xs[step_k2]), int(wire_ys[step_k2])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = wx_s + dx2, wy_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Variation: Horizontal wire spine instead of vertical, with roads above/below.
    Two clusters side by side, each with horizontal power distribution.
    Zones placed in rows above and below road rows.
    More balanced RES/COM/IND mix.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not in_bounds(rc, rr):
                    return False
                if not bool(em[rr, rc]):
                    return False
        return True

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))

    def pick_zone(col):
        # Cycle: RES heavy, with COM and IND columns interleaved
        # Use column position to vary zone type
        phase = (col // 6) % 4
        if phase == 0:
            return Tool.RESIDENTIAL
        elif phase == 1:
            return Tool.COMMERCIAL
        elif phase == 2:
            return Tool.RESIDENTIAL
        else:
            return Tool.INDUSTRIAL

    # Power plant 1: center-left area
    P1X, P1Y = 40, 50
    # Power plant 2: center-right area
    P2X, P2Y = 75, 50

    plant_ys, plant_xs = np.where(pm)
    has_plant1 = False
    has_plant2 = False
    for py_, px_ in zip(plant_ys.tolist(), plant_xs.tolist()):
        if abs(px_ - P1X) <= 5 and abs(py_ - P1Y) <= 5:
            has_plant1 = True
        if abs(px_ - P2X) <= 5 and abs(py_ - P2Y) <= 5:
            has_plant2 = True

    # Phase 1: place primary power plant
    if not has_plant1:
        return (Tool.COALPOWER, P1X, P1Y)

    # Horizontal wire spine row for cluster 1
    WIRE_ROW1 = P1Y  # row 50
    # Roads above and below wire spine
    ROAD_ROW_U1 = WIRE_ROW1 - 1  # row 49
    ROAD_ROW_D1 = WIRE_ROW1 + 1  # row 51
    # Zone rows: 3 above and 3 below roads
    ZONE_ROWS_U1 = [WIRE_ROW1 - 4, WIRE_ROW1 - 7]
    ZONE_ROWS_D1 = [WIRE_ROW1 + 4, WIRE_ROW1 + 7]

    # Horizontal span for cluster 1
    extra_span = min(25, obs.city_pop // 15)
    base_span = 15
    target_span = base_span + extra_span
    xmin1 = max(2, P1X - target_span)
    xmax1 = min(WORLD_W - 3, P1X + target_span)

    wire_positions = set(zip(*np.where(wm))) if np.any(wm) else set()
    road_positions = set(zip(*np.where(rm))) if np.any(rm) else set()

    wire_cols_in_row1 = sorted(c for (r, c) in wire_positions if r == WIRE_ROW1)

    # Extend horizontal wire spine
    if not wire_cols_in_row1:
        # Start at plant
        nx = P1X + 2
        if in_bounds(nx, WIRE_ROW1) and bool(em[WIRE_ROW1, nx]):
            return (Tool.WIRE, nx, WIRE_ROW1)
        return (Tool.WIRE, P1X + 2, WIRE_ROW1)
    else:
        min_wc = min(wire_cols_in_row1)
        max_wc = max(wire_cols_in_row1)
        if max_wc < xmax1:
            nc = max_wc + 1
            if in_bounds(nc, WIRE_ROW1) and bool(em[WIRE_ROW1, nc]):
                return (Tool.WIRE, nc, WIRE_ROW1)
        if min_wc > xmin1:
            nc = min_wc - 1
            if in_bounds(nc, WIRE_ROW1) and bool(em[WIRE_ROW1, nc]):
                return (Tool.WIRE, nc, WIRE_ROW1)

    wire_cols_set1 = set(wire_cols_in_row1)
    road_cols_U1 = set(c for (r, c) in road_positions if r == ROAD_ROW_U1)
    road_cols_D1 = set(c for (r, c) in road_positions if r == ROAD_ROW_D1)

    # Build road rows adjacent to wire spine
    for wc in wire_cols_in_row1:
        if wc not in road_cols_U1 and in_bounds(wc, ROAD_ROW_U1):
            if bool(em[ROAD_ROW_U1, wc]):
                return (Tool.ROAD, wc, ROAD_ROW_U1)
        if wc not in road_cols_D1 and in_bounds(wc, ROAD_ROW_D1):
            if bool(em[ROAD_ROW_D1, wc]):
                return (Tool.ROAD, wc, ROAD_ROW_D1)

    # Place zones in rows above and below
    for wc in wire_cols_in_row1:
        if wc < 2 or wc >= WORLD_W - 2:
            continue
        road_U_nearby = wc in road_cols_U1
        road_D_nearby = wc in road_cols_D1

        for zr in ZONE_ROWS_U1:
            if road_U_nearby and in_bounds(wc, zr) and 2 <= zr < WORLD_H - 2:
                if zone_area_free(zr, wc):
                    return (pick_zone(wc), wc, zr)

        for zr in ZONE_ROWS_D1:
            if road_D_nearby and in_bounds(wc, zr) and 2 <= zr < WORLD_H - 2:
                if zone_area_free(zr, wc):
                    return (pick_zone(wc), wc, zr)

    # Vertical wires from spine up to upper zone rows
    for wc in wire_cols_in_row1:
        for wr in range(WIRE_ROW1 - 1, max(WIRE_ROW1 - 9, 0) - 1, -1):
            if in_bounds(wc, wr) and not bool(wm[wr, wc]) and not bool(pm[wr, wc]) and not bool(rm[wr, wc]):
                if bool(em[wr, wc]):
                    return (Tool.WIRE, wc, wr)
                break

    # Vertical wires from spine down to lower zone rows
    for wc in wire_cols_in_row1:
        for wr in range(WIRE_ROW1 + 1, min(WIRE_ROW1 + 9, WORLD_H)):
            if in_bounds(wc, wr) and not bool(wm[wr, wc]) and not bool(pm[wr, wc]) and not bool(rm[wr, wc]):
                if bool(em[wr, wc]):
                    return (Tool.WIRE, wc, wr)
                break

    # Phase 2: second cluster with horizontal spine at different Y
    if obs.city_pop > 80:
        if not has_plant2:
            return (Tool.COALPOWER, P2X, P2Y)

        WIRE_ROW2 = P2Y - 10  # row 40 - offset for variety
        ROAD_ROW_U2 = WIRE_ROW2 - 1
        ROAD_ROW_D2 = WIRE_ROW2 + 1
        ZONE_ROWS_U2 = [WIRE_ROW2 - 4, WIRE_ROW2 - 7]
        ZONE_ROWS_D2 = [WIRE_ROW2 + 4, WIRE_ROW2 + 7]

        extra_span2 = min(20, obs.city_pop // 20)
        xmin2 = max(2, P2X - base_span - extra_span2)
        xmax2 = min(WORLD_W - 3, P2X + base_span + extra_span2)

        wire_cols_in_row2 = sorted(c for (r, c) in wire_positions if r == WIRE_ROW2)

        # Connect plant2 to wire row2 via vertical wire
        if not wire_cols_in_row2:
            # Start wire at plant2 column, WIRE_ROW2
            for wr in range(min(P2Y - 2, WIRE_ROW2), WIRE_ROW2 - 1, -1):
                if in_bounds(P2X, wr) and bool(em[wr, P2X]) and not bool(pm[wr, P2X]):
                    return (Tool.WIRE, P2X, wr)
            return (Tool.WIRE, P2X, WIRE_ROW2)

        min_wc2 = min(wire_cols_in_row2)
        max_wc2 = max(wire_cols_in_row2)
        if max_wc2 < xmax2:
            nc = max_wc2 + 1
            if in_bounds(nc, WIRE_ROW2) and bool(em[WIRE_ROW2, nc]):
                return (Tool.WIRE, nc, WIRE_ROW2)
        if min_wc2 > xmin2:
            nc = min_wc2 - 1
            if in_bounds(nc, WIRE_ROW2) and bool(em[WIRE_ROW2, nc]):
                return (Tool.WIRE, nc, WIRE_ROW2)

        road_cols_U2 = set(c for (r, c) in road_positions if r == ROAD_ROW_U2)
        road_cols_D2 = set(c for (r, c) in road_positions if r == ROAD_ROW_D2)

        for wc in wire_cols_in_row2:
            if wc not in road_cols_U2 and in_bounds(wc, ROAD_ROW_U2):
                if bool(em[ROAD_ROW_U2, wc]):
                    return (Tool.ROAD, wc, ROAD_ROW_U2)
            if wc not in road_cols_D2 and in_bounds(wc, ROAD_ROW_D2):
                if bool(em[ROAD_ROW_D2, wc]):
                    return (Tool.ROAD, wc, ROAD_ROW_D2)

        for wc in wire_cols_in_row2:
            if wc < 2 or wc >= WORLD_W - 2:
                continue
            road_U_nearby2 = wc in road_cols_U2
            road_D_nearby2 = wc in road_cols_D2

            for zr in ZONE_ROWS_U2:
                if road_U_nearby2 and in_bounds(wc, zr) and 2 <= zr < WORLD_H - 2:
                    if zone_area_free(zr, wc):
                        return (pick_zone(wc), wc, zr)

            for zr in ZONE_ROWS_D2:
                if road_D_nearby2 and in_bounds(wc, zr) and 2 <= zr < WORLD_H - 2:
                    if zone_area_free(zr, wc):
                        return (pick_zone(wc), wc, zr)

        # Vertical wires for cluster2
        for wc in wire_cols_in_row2:
            for wr in range(WIRE_ROW2 - 1, max(WIRE_ROW2 - 9, 0) - 1, -1):
                if in_bounds(wc, wr) and not bool(wm[wr, wc]) and not bool(pm[wr, wc]) and not bool(rm[wr, wc]):
                    if bool(em[wr, wc]):
                        return (Tool.WIRE, wc, wr)
                    break
            for wr in range(WIRE_ROW2 + 1, min(WIRE_ROW2 + 9, WORLD_H)):
                if in_bounds(wc, wr) and not bool(wm[wr, wc]) and not bool(pm[wr, wc]) and not bool(rm[wr, wc]):
                    if bool(em[wr, wc]):
                        return (Tool.WIRE, wc, wr)
                    break

    # Services
    if obs.city_pop > 200:
        fx, fy = P1X - 8, WIRE_ROW1 - 10
        if in_bounds(fx, fy) and zone_area_free(fy, fx):
            return (Tool.FIRESTATION, fx, fy)

    if obs.city_pop > 400:
        px2, py2 = P1X + 8, WIRE_ROW1 + 12
        if in_bounds(px2, py2) and zone_area_free(py2, px2):
            return (Tool.POLICESTATION, px2, py2)

    if obs.city_pop > 600:
        sx, sy = P2X + 10, WIRE_ROW1 + 5
        if in_bounds(sx, sy) and zone_area_free(sy, sx):
            return (Tool.STADIUM, sx, sy)

    # Fallback: extend roads
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = int(obs.step * 13) % max(len(road_xs), 1)
        rx_s, ry_s = int(road_xs[step_k]), int(road_ys[step_k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx_s + dx2, ry_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wires
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        step_k2 = int(obs.step * 7) % max(len(wire_xs), 1)
        wx_s, wy_s = int(wire_xs[step_k2]), int(wire_ys[step_k2])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = wx_s + dx2, wy_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Revised city builder - different approach:
    - Places power plant closer to center-left
    - Builds a cross/grid road network (horizontal + vertical roads)
    - Uses wire along roads to power zones
    - Places zones in a dense grid pattern between roads
    - Better RES/COM/IND balance (40/30/30)
    - Two power plants from the start plan
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Config ---
    # We'll build two neighborhoods: left cluster and right cluster
    # Left: centered around (25, 45), Right: centered around (70, 45)
    # Power plants at (10, 45) and (55, 45)
    # Horizontal road spine at y=45, vertical roads every 8 cols
    # Zones packed above and below roads

    PLANT_X, PLANT_Y = 10, 45
    PLANT2_X, PLANT2_Y = 58, 45

    # Road layout: two horizontal roads at y=38 and y=52
    # Vertical roads at x = 20, 28, 36, 44, 52, 60, 68, 76, 84
    H_ROAD1 = 38
    H_ROAD2 = 52
    ROAD_LEFT = 14
    ROAD_RIGHT = 90

    V_ROADS = list(range(20, 91, 8))

    has_plant = np.any(pm)

    # Phase 1: Place first coal power plant
    if not has_plant:
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    plant_ys, plant_xs = np.where(pm)
    wire_ys, wire_xs = np.where(wm)
    road_ys, road_xs = np.where(rm)
    res_ys, res_xs = np.where(resm)
    com_ys, com_xs = np.where(comm)
    ind_ys, ind_xs = np.where(indm)

    wire_set = set(zip(wire_ys.tolist(), wire_xs.tolist()))
    road_set = set(zip(road_ys.tolist(), road_xs.tolist()))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def is_wire_or_plant(x, y):
        return in_bounds(x, y) and (bool(wm[y, x]) or bool(pm[y, x]))

    def is_road(x, y):
        return in_bounds(x, y) and bool(rm[y, x])

    def is_empty(x, y):
        return in_bounds(x, y) and bool(em[y, x])

    def is_plant_tile(x, y):
        return in_bounds(x, y) and bool(pm[y, x])

    def pick_tool():
        t = max(total_zones, 1)
        r = res_count / t
        c = com_count / t
        i = ind_count / t
        # Target: 40% RES, 30% COM, 30% IND
        if c < 0.28:
            return Tool.COMMERCIAL
        if i < 0.28:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not bool(em[nr, nc]):
                    return False
        return True

    # Step 1: Place wire from plant to road grid
    # Wire horizontal spine at y=PLANT_Y from plant to connect to road system
    # Wire from plant rightward to first vertical road
    wire_spine_y = PLANT_Y  # y=45, between the two road rows
    plant_right_edge = PLANT_X + 2  # plant is 4x4 ish, center at PLANT_X

    # Connect plant to the road grid via wire along spine row
    for wx in range(plant_right_edge, ROAD_RIGHT + 1):
        if not in_bounds(wx, wire_spine_y):
            break
        if not is_wire_or_plant(wx, wire_spine_y):
            if not is_road(wx, wire_spine_y):
                return (Tool.WIRE, wx, wire_spine_y)
            else:
                # Road is there, lay wire under road? Wire on road col at spine
                return (Tool.WIRE, wx, wire_spine_y)

    # Step 2: Check/place second power plant
    near_plant2 = False
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            ny, nx = PLANT2_Y + dy, PLANT2_X + dx
            if in_bounds(nx, ny) and bool(pm[ny, nx]):
                near_plant2 = True
    if not near_plant2:
        # Place second plant once wire reaches far enough
        wire_cols = [c for (r, c) in wire_set if r == wire_spine_y]
        if wire_cols and max(wire_cols) >= PLANT2_X - 3:
            return (Tool.COALPOWER, PLANT2_X, PLANT2_Y)

    # Step 3: Build horizontal roads
    for ry_road in [H_ROAD1, H_ROAD2]:
        for cx in range(ROAD_LEFT, ROAD_RIGHT + 1):
            if in_bounds(cx, ry_road) and (ry_road, cx) not in road_set:
                if not is_plant_tile(cx, ry_road):
                    return (Tool.ROAD, cx, ry_road)

    # Step 4: Build vertical roads
    for vx in V_ROADS:
        for vy in range(H_ROAD1, H_ROAD2 + 1):
            if in_bounds(vx, vy) and (vy, vx) not in road_set:
                if not is_plant_tile(vx, vy):
                    return (Tool.ROAD, vx, vy)

    # Step 5: Wire along vertical roads to distribute power
    # Wire from spine to H_ROAD1 and H_ROAD2 along vertical road cols
    for vx in V_ROADS:
        # wire from spine_y up to H_ROAD1
        for wy in range(wire_spine_y - 1, H_ROAD1 - 1, -1):
            if not is_wire_or_plant(vx, wy) and not is_road(vx, wy):
                return (Tool.WIRE, vx, wy)
        # wire from spine_y down to H_ROAD2
        for wy in range(wire_spine_y + 1, H_ROAD2 + 1):
            if not is_wire_or_plant(vx, wy) and not is_road(vx, wy):
                return (Tool.WIRE, vx, wy)

    # Step 6: Build extended vertical roads above and below for more zone coverage
    for vx in V_ROADS:
        for vy in list(range(H_ROAD1 - 4, H_ROAD1)) + list(range(H_ROAD2 + 1, H_ROAD2 + 5)):
            if in_bounds(vx, vy) and (vy, vx) not in road_set:
                if not is_plant_tile(vx, vy):
                    return (Tool.ROAD, vx, vy)

    # Build neighbor masks for road and wire proximity
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Step 7: Zone placement in systematic grid
    # Place zones above H_ROAD1, between roads, and below H_ROAD2
    zone_band_rows = []
    # Above road 1
    for zr in range(H_ROAD1 - 2, H_ROAD1 - 8, -3):
        zone_band_rows.append(zr)
    # Below road 2
    for zr in range(H_ROAD2 + 2, H_ROAD2 + 8, 3):
        zone_band_rows.append(zr)
    # Between roads (if gap is big enough)
    mid_y = (H_ROAD1 + H_ROAD2) // 2
    if H_ROAD2 - H_ROAD1 > 8:
        zone_band_rows.append(mid_y)

    for zr in zone_band_rows:
        if not in_bounds(0, zr):
            continue
        for zc in range(ROAD_LEFT + 2, ROAD_RIGHT - 1, 4):
            if not in_bounds(zc, zr):
                continue
            if not bool(em[zr, zc]):
                continue
            if not nbr_road[zr, zc]:
                continue
            if not nbr_wire[zr, zc]:
                continue
            if zone_clear(zc, zr):
                return (pick_tool(), zc, zr)

    # Generic candidate zone placement
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        step_hash = int(obs.step * 17) % max(len(cxs), 1)
        for offset in range(min(len(cxs), 60)):
            k = (step_hash + offset * 11) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # Services
    if obs.city_pop > 200:
        for fx, fy in [(ROAD_LEFT + 3, H_ROAD1 - 10), (55, H_ROAD1 - 10)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 400:
        for px2, py2 in [(ROAD_LEFT + 3, H_ROAD2 + 10), (55, H_ROAD2 + 10)]:
            if in_bounds(px2, py2) and bool(em[py2, px2]):
                return (Tool.POLICESTATION, px2, py2)

    # Extend roads to create more connectivity
    if len(road_xs) > 0:
        k = int(obs.step * 13) % len(road_xs)
        rx, ry = int(road_xs[k]), int(road_ys[k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx + dx2, ry + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map every step to find current infrastructure
    - Places coal plant, extends wire spine, builds road column,
      then fills zones reactively based on actual power/road coverage.
    - Uses a wider layout with two road columns flanking a central wire spine.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    cx, cy = 60, 50  # center of map

    has_plant = np.any(pm)

    # Count zones
    res_count = int(np.sum(res_m))
    com_count = int(np.sum(com_m))
    ind_count = int(np.sum(ind_m))

    # Layout:
    # plant center: (px, py) = (cx - 8, cy)
    # wire spine column: px + 5 = cx - 3
    # left road column: wire_col - 2 = cx - 5
    # right road column: wire_col + 2 = cx - 1
    # left zone column: left_road - 3 = cx - 8  (same as plant... shift)
    # Actually use:
    # plant at (50, 50), wire_col=55, left_road=53, right_road=57
    # left zones at cx=50 (cx-10), right zones at cx+4

    plant_x, plant_y = cx - 10, cy
    wire_col = plant_x + 7   # 57... let's be explicit
    wire_col = 57
    left_road_col = wire_col - 3   # 54
    right_road_col = wire_col + 3  # 60

    left_zone_col = left_road_col - 3   # 51
    right_zone_col = right_road_col + 3  # 63

    # Phase 1: Place coal plant
    if not has_plant:
        px, py = plant_x, plant_y
        return (Tool.COALPOWER, px, py)

    # Find plant location
    plant_positions = list(zip(*np.where(pm)))
    if plant_positions:
        pr, pc = plant_positions[0]
        # Wire col is plant right edge + 1
        # plant footprint: center +/-2 => pc-2..pc+2, wire at pc+3
        wire_col = pc + 3
        if wire_col >= WORLD_W:
            wire_col = pc - 3
        left_road_col = wire_col - 3
        right_road_col = wire_col + 3
        left_zone_col = left_road_col - 3
        right_zone_col = right_road_col + 3
        plant_y = pr

    # Clamp columns
    wire_col = max(4, min(WORLD_W - 5, wire_col))
    left_road_col = max(1, min(WORLD_W - 2, wire_col - 3))
    right_road_col = max(1, min(WORLD_W - 2, wire_col + 3))
    left_zone_col = max(1, min(WORLD_W - 2, wire_col - 6))
    right_zone_col = max(1, min(WORLD_W - 2, wire_col + 6))

    # Wire spine rows: cy-20 to cy+20
    spine_top = max(1, plant_y - 20)
    spine_bot = min(WORLD_H - 2, plant_y + 20)

    # Current wire rows in wire_col
    wire_rows_in_col = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])

    # Phase 2: Start wire adjacent to plant if none exist
    if not wire_rows_in_col:
        # Place wire at (wire_col, plant_y) - adjacent to plant
        if 0 <= wire_col < WORLD_W and 0 <= plant_y < WORLD_H:
            return (Tool.WIRE, wire_col, plant_y)

    # Phase 3: Extend wire spine to cover spine range
    if wire_rows_in_col:
        cur_min = min(wire_rows_in_col)
        cur_max = max(wire_rows_in_col)
        # Extend downward
        if cur_max < spine_bot:
            nr = cur_max + 1
            if nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if cur_min > spine_top:
            nr = cur_min - 1
            if nr >= 0 and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    # Phase 4: Build left and right road columns for all wire rows
    for wr in wire_rows_in_col:
        # Left road
        if 0 <= left_road_col < WORLD_W and not rm[wr, left_road_col]:
            return (Tool.ROAD, left_road_col, wr)
        # Right road
        if 0 <= right_road_col < WORLD_W and not rm[wr, right_road_col]:
            return (Tool.ROAD, right_road_col, wr)

    # Helper: check if 3x3 zone footprint is clear
    def zone_clear(zr, zc):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                r2, c2 = zr + dr, zc + dc
                if r2 < 0 or r2 >= WORLD_H or c2 < 0 or c2 >= WORLD_W:
                    return False
                if not em[r2, c2]:
                    return False
        return True

    # Helper: check if zone is already placed nearby
    def zone_exists_near(zr, zc, mask):
        # Check if any mask tile within 2 tiles
        r1, r2 = max(0, zr - 2), min(WORLD_H, zr + 3)
        c1, c2 = max(0, zc - 2), min(WORLD_W, zc + 3)
        return np.any(mask[r1:r2, c1:c2])

    # Helper: check power proximity (wire within 2 tiles of zone)
    def near_wire(zr, zc):
        r1, r2 = max(0, zr - 2), min(WORLD_H, zr + 3)
        c1, c2 = max(0, zc - 2), min(WORLD_W, zc + 3)
        return np.any(wm[r1:r2, c1:c2])

    # Helper: check road proximity
    def near_road(zr, zc):
        r1, r2 = max(0, zr - 2), min(WORLD_H, zr + 3)
        c1, c2 = max(0, zc - 2), min(WORLD_W, zc + 3)
        return np.any(rm[r1:r2, c1:c2])

    # Phase 5: Add lateral wires to connect zones to spine
    # For each wire row, extend wires left to left_zone_col and right to right_zone_col
    for wr in wire_rows_in_col:
        # Left lateral wires: from wire_col-1 down to left_zone_col+1
        for wc in range(wire_col - 1, left_zone_col, -1):
            if 0 <= wc < WORLD_W and em[wr, wc] and not wm[wr, wc]:
                return (Tool.WIRE, wc, wr)
        # Right lateral wires: from wire_col+1 up to right_zone_col-1
        for wc in range(wire_col + 1, right_zone_col):
            if 0 <= wc < WORLD_W and em[wr, wc] and not wm[wr, wc]:
                return (Tool.WIRE, wc, wr)

    # Phase 6: Place zones in rows matching wire spine, spaced by 3
    zone_rows = list(range(max(1, spine_top), min(WORLD_H - 1, spine_bot + 1), 3))

    for zr in zone_rows:
        powered = near_wire(zr, wire_col)
        if not powered:
            continue

        # Left zone
        zc = left_zone_col
        if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
            if not zone_exists_near(zr, zc, res_m) and not zone_exists_near(zr, zc, ind_m):
                if zone_clear(zr, zc) and near_road(zr, zc):
                    # Choose zone type based on ratios
                    if ind_count < max(1, res_count // 4):
                        return (Tool.INDUSTRIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

        # Right zone
        zc = right_zone_col
        if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
            if not zone_exists_near(zr, zc, res_m) and not zone_exists_near(zr, zc, com_m):
                if zone_clear(zr, zc) and near_road(zr, zc):
                    if com_count < max(1, res_count // 4):
                        return (Tool.COMMERCIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

    # Phase 7: Extend wire and road coverage if population growing
    if obs.city_pop > 100:
        new_spine_top = max(1, spine_top - 5)
        new_spine_bot = min(WORLD_H - 2, spine_bot + 5)
        if wire_rows_in_col:
            cur_min = min(wire_rows_in_col)
            cur_max = max(wire_rows_in_col)
            if cur_max < new_spine_bot:
                nr = cur_max + 1
                if nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                    return (Tool.WIRE, wire_col, nr)
            if cur_min > new_spine_top:
                nr = cur_min - 1
                if nr >= 0 and (em[nr, wire_col] or wm[nr, wire_col]):
                    return (Tool.WIRE, wire_col, nr)

    # Phase 8: Extra zone columns when city is growing well
    if obs.city_pop > 200:
        extra_left = left_zone_col - 4
        extra_right = right_zone_col + 4
        for zr in zone_rows:
            if not near_wire(zr, wire_col):
                continue
            for zc in [extra_left, extra_right]:
                if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                    all_zones = res_m | com_m | ind_m
                    if not zone_exists_near(zr, zc, all_zones):
                        if zone_clear(zr, zc) and near_road(zr, zc):
                            return (Tool.RESIDENTIAL, zc, zr)

    # Phase 9: Build horizontal roads to connect extra zones
    for wr in wire_rows_in_col:
        for rc in range(left_road_col, max(0, left_zone_col - 4), -1):
            if 0 <= rc < WORLD_W and not rm[wr, rc] and em[wr, rc]:
                return (Tool.ROAD, rc, wr)
        for rc in range(right_road_col, min(WORLD_W - 1, right_zone_col + 5)):
            if 0 <= rc < WORLD_W and not rm[wr, rc] and em[wr, rc]:
                return (Tool.ROAD, rc, wr)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder.
    Reads map every step, builds outward from what exists.
    Strategy:
    - Place coal power plant at fixed anchor
    - Wire spine extends vertically from plant
    - Two horizontal roads flank the wire spine
    - Zones fill the space between/around roads with wire+road access
    - Second plant added when zones grow
    - All decisions driven by current tile_map observation
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Anchor: plant placed near left-center
    PLANT_X, PLANT_Y = 28, 50

    # --- Phase 1: Place coal power plant if none exists ---
    if not np.any(pm):
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    # Find plant centroid
    plant_rows, plant_cols = np.where(pm)
    pcx = int(np.mean(plant_cols))
    pcy = int(np.mean(plant_rows))

    # Layout columns based on plant position
    wire_col = pcx + 3      # vertical wire spine just right of plant
    road_top_offset = -4    # road rows relative to plant center
    road_bot_offset = +4

    road_top_row = pcy + road_top_offset
    road_bot_row = pcy + road_bot_offset

    # Wire spine extent based on population
    pop = obs.city_pop
    if pop < 50:
        spine_half = 6
    elif pop < 200:
        spine_half = 12
    elif pop < 500:
        spine_half = 18
    else:
        spine_half = 24

    spine_min_r = max(1, pcy - spine_half)
    spine_max_r = min(WORLD_H - 2, pcy + spine_half)

    # Road extends rightward from wire col
    road_start_x = wire_col + 1
    road_end_x = min(wire_col + 40, WORLD_W - 4)

    # --- Phase 2: Extend vertical wire spine ---
    # Find current spine extent
    spine_rows = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])

    if not spine_rows:
        # Bootstrap: place wire adjacent to plant
        for dy in range(0, 4):
            for nr in [pcy + dy, pcy - dy]:
                if 0 <= nr < WORLD_H:
                    if not pm[nr, wire_col]:
                        if em[nr, wire_col] or wm[nr, wire_col]:
                            return (Tool.WIRE, wire_col, nr)
        return None

    min_sr = min(spine_rows)
    max_sr = max(spine_rows)

    # Extend spine downward
    if max_sr < spine_max_r:
        nr = max_sr + 1
        if 0 <= nr < WORLD_H and not pm[nr, wire_col]:
            if em[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Extend spine upward
    if min_sr > spine_min_r:
        nr = min_sr - 1
        if 0 <= nr < WORLD_H and not pm[nr, wire_col]:
            if em[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # --- Phase 3: Build top road row ---
    ry = road_top_row
    if 0 <= ry < WORLD_H:
        for rx in range(road_start_x, road_end_x + 1):
            if not in_bounds(rx, ry):
                break
            if pm[ry, rx]:
                break
            if not rm[ry, rx]:
                if em[ry, rx]:
                    return (Tool.ROAD, rx, ry)
                break  # blocked

    # --- Phase 4: Build bottom road row ---
    ry = road_bot_row
    if 0 <= ry < WORLD_H:
        for rx in range(road_start_x, road_end_x + 1):
            if not in_bounds(rx, ry):
                break
            if pm[ry, rx]:
                break
            if not rm[ry, rx]:
                if em[ry, rx]:
                    return (Tool.ROAD, rx, ry)
                break

    # --- Phase 5: Horizontal wire to connect spine to road region ---
    # Extend wire along road_top_row and road_bot_row from wire_col
    for wy in [road_top_row, road_bot_row]:
        if not (0 <= wy < WORLD_H):
            continue
        # Check if spine reaches this row
        if not (wm[wy, wire_col] or pm[wy, wire_col]):
            # Connect wire spine to this row via vertical bridge
            # Find nearest spine row to wy
            if spine_rows:
                nearest = min(spine_rows, key=lambda r: abs(r - wy))
                step_dir = 1 if wy > nearest else -1
                for yr in range(nearest + step_dir, wy + step_dir, step_dir):
                    if 0 <= yr < WORLD_H and not pm[yr, wire_col]:
                        if not wm[yr, wire_col] and em[yr, wire_col]:
                            return (Tool.WIRE, wire_col, yr)
                        elif not wm[yr, wire_col]:
                            break
        # Extend wire horizontally along the row
        for wx in range(wire_col, road_end_x + 1):
            if not in_bounds(wx, wy):
                break
            if pm[wy, wx]:
                break
            if not wm[wy, wx] and not rm[wy, wx]:
                if em[wy, wx]:
                    return (Tool.WIRE, wx, wy)
                break

    # --- Phase 6: Zone placement ---
    # Build adjacency maps: near road and near wire/plant
    # Use dilation approach
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            r0s = max(0, -dy); r1s = min(WORLD_H, WORLD_H - dy)
            c0s = max(0, -dx); c1s = min(WORLD_W, WORLD_W - dx)
            r0d = max(0, dy); r1d = min(WORLD_H, WORLD_H + dy)
            c0d = max(0, dx); c1d = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0d:r1d, c0d:c1d] |= rm[r0s:r1s, c0s:c1s]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            r0s = max(0, -dy); r1s = min(WORLD_H, WORLD_H - dy)
            c0s = max(0, -dx); c1s = min(WORLD_W, WORLD_W - dx)
            r0d = max(0, dy); r1d = min(WORLD_H, WORLD_H + dy)
            c0d = max(0, dx); c1d = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0d:r1d, c0d:c1d] |= wm[r0s:r1s, c0s:c1s]
            nbr_wire[r0d:r1d, c0d:c1d] |= pm[r0s:r1s, c0s:c1s]

    all_zone = resm | comm | indm

    def zone_area_clear(zx, zy):
        if zy < 1 or zy > WORLD_H - 2 or zx < 1 or zx > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zy + dr, zx + dc
                if not in_bounds(rc, rr):
                    return False
                if not em[rr, rc] and not all_zone[rr, rc]:
                    return False
        return True

    # Candidate zone centers: empty, near road, near wire, not too close to edge
    # Scan systematically: columns first within zone range
    zone_placed = False
    zone_x_start = wire_col + 1
    zone_x_end = road_end_x - 1

    # Scan row bands between roads
    # Top band: road_top_row-6 to road_top_row-1
    # Middle band: road_top_row+1 to road_bot_row-1
    # Bottom band: road_bot_row+1 to road_bot_row+6
    bands = [
        (road_top_row - 6, road_top_row - 1),
        (road_top_row + 1, road_bot_row - 1),
        (road_bot_row + 1, road_bot_row + 6),
    ]

    # Also consider zones to left of wire (connected by lateral wire)
    left_zone_x_start = max(2, pcx - 8)
    left_zone_x_end = wire_col - 1

    for band_min, band_max in bands:
        bmin = max(1, band_min)
        bmax = min(WORLD_H - 2, band_max)
        for zy in range(bmin, bmax + 1, 3):
            for zx in range(zone_x_start, zone_x_end + 1, 3):
                if nbr_road[zy, zx] and nbr_wire[zy, zx]:
                    if zone_area_clear(zx, zy):
                        return (pick_tool(), zx, zy)

    # Left-side zones (need lateral wire)
    for zy in range(max(1, pcy - spine_half), min(WORLD_H - 1, pcy + spine_half + 1), 3):
        for zx in range(left_zone_x_start, left_zone_x_end + 1, 3):
            if nbr_road[zy, zx] and nbr_wire[zy, zx]:
                if zone_area_clear(zx, zy):
                    return (pick_tool(), zx, zy)

    # --- Phase 7: Lateral wires leftward from spine to reach left zones ---
    for sr in spine_rows[::2]:
        for wc in range(wire_col - 1, max(pcx - 9, 0), -1):
            if pm[sr, wc]:
                break
            if wm[sr, wc]:
                break
            if em[sr, wc]:
                return (Tool.WIRE, wc, sr)
            break

    # --- Phase 8: Vertical connector roads ---
    if rm[road_top_row, wire_col + 1] and rm[road_bot_row, wire_col + 1]:
        # Build vertical roads connecting top and bottom roads at a few columns
        for cx2 in range(wire_col + 6, road_end_x, 9):
            if not in_bounds(cx2, road_top_row) or not in_bounds(cx2, road_bot_row):
                continue
            for ry2 in range(road_top_row, road_bot_row + 1):
                if not rm[ry2, cx2] and em[ry2, cx2] and not pm[ry2, cx2]:
                    return (Tool.ROAD, cx2, ry2)

    # --- Phase 9: Second power plant when needed ---
    n_plants = int(np.sum(pm)) // 9  # approximate number of 3x3 plants
    if total_zones > 8 or pop > 300:
        p2x = min(pcx + 20, WORLD_W - 5)
        p2y = pcy
        # Check no plant nearby
        nearby = False
        for dy2 in range(-6, 7):
            for dx2 in range(-6, 7):
                ny2, nx2 = p2y + dy2, p2x + dx2
                if in_bounds(nx2, ny2) and pm[ny2, nx2]:
                    nearby = True
                    break
            if nearby:
                break
        if not nearby and in_bounds(p2x, p2y) and em[p2y, p2x]:
            return (Tool.COALPOWER, p2x, p2y)

    # --- Phase 10: Services ---
    if pop > 100:
        fx, fy = pcx + 4, pcy - 9
        if in_bounds(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
        px2, py2 = pcx + 4, pcy + 9
        if in_bounds(px2, py2) and em[py2, px2]:
            return (Tool.POLICESTATION, px2, py2)

    # --- Phase 11: Extend spine further if nothing else to do ---
    if max_sr < min(WORLD_H - 2, pcy + 30):
        nr = max_sr + 1
        if 0 <= nr < WORLD_H and not pm[nr, wire_col] and em[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)
    if min_sr > max(1, pcy - 30):
        nr = min_sr - 1
        if 0 <= nr < WORLD_H and not pm[nr, wire_col] and em[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)

    return None

def act(obs, state):
    """
    Redesigned policy: horizontal layout with a compact power grid.
    - Coal plant near top-center
    - Horizontal wire spine from plant going right
    - Road rows above and below the wire spine
    - Zones placed above/below roads in columns
    - More balanced RES/COM/IND mix
    - Second power plant if needed
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    # Initialize state
    if 'phase' not in state:
        state['phase'] = 0
        state['step'] = 0
    state['step'] += 1

    # Fixed layout: horizontal design
    # Plant at (30, 30) - col 30, row 30
    plant_cx, plant_cy = 30, 30

    has_plant = np.any(pm)

    # Phase 1: Place coal power plant
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Find plant location from map
    plant_rows, plant_cols = np.where(pm)
    if len(plant_rows) > 0:
        plant_cy = int(plant_rows[0])
        plant_cx = int(plant_cols[0])

    # Horizontal wire spine row: just below plant footprint
    wire_row = plant_cy + 3  # below plant (plant occupies cy-1..cy+1)
    # Road rows above and below wire
    road_row_top = wire_row - 2
    road_row_bot = wire_row + 2

    # Wire extends from plant_cx - 2 to plant_cx + 30
    wire_start_col = plant_cx - 1
    wire_end_col = min(WORLD_W - 4, plant_cx + 35)

    # Check current wire coverage on wire_row
    wire_cols_on_row = sorted([c for (r, c) in zip(*np.where(wm)) if r == wire_row])
    road_top_cols = sorted([c for (r, c) in zip(*np.where(rm)) if r == road_row_top])
    road_bot_cols = sorted([c for (r, c) in zip(*np.where(rm)) if r == road_row_bot])

    # Build wire spine horizontally
    if not wire_cols_on_row or min(wire_cols_on_row) > wire_start_col:
        # Start wire adjacent to plant
        return (Tool.WIRE, plant_cx + 2, wire_row)

    max_wire_col = max(wire_cols_on_row) if wire_cols_on_row else wire_start_col
    min_wire_col = min(wire_cols_on_row) if wire_cols_on_row else wire_start_col

    # Extend wire spine to the right
    if max_wire_col < wire_end_col:
        return (Tool.WIRE, max_wire_col + 1, wire_row)

    # Also extend wire left a bit
    wire_left_end = max(2, plant_cx - 10)
    if min_wire_col > wire_left_end:
        return (Tool.WIRE, min_wire_col - 1, wire_row)

    # Build top road row (parallel to wire)
    if not road_top_cols or max(road_top_cols) < wire_end_col:
        if road_row_top >= 2:
            start_c = max(road_top_cols) + 1 if road_top_cols else wire_start_col
            if start_c <= wire_end_col:
                return (Tool.ROAD, start_c, road_row_top)

    # Build bottom road row
    if not road_bot_cols or max(road_bot_cols) < wire_end_col:
        if road_row_bot < WORLD_H - 2:
            start_c = max(road_bot_cols) + 1 if road_bot_cols else wire_start_col
            if start_c <= wire_end_col:
                return (Tool.ROAD, start_c, road_row_bot)

    # Now place zones in columns between wire_start_col and wire_end_col
    # Zones go: top zone row above top road, bottom zone row below bot road
    zone_row_top = road_row_top - 2   # center of top zone (row above road)
    zone_row_bot = road_row_bot + 2   # center of bottom zone

    res_mask_arr = res_mask(tm)
    com_mask_arr = com_mask(tm)
    ind_mask_arr = ind_mask(tm)

    res_pos = list(zip(*np.where(res_mask_arr)))
    com_pos = list(zip(*np.where(com_mask_arr)))
    ind_pos = list(zip(*np.where(ind_mask_arr)))

    res_count = len(res_pos)
    com_count = len(com_pos)
    ind_count = len(ind_pos)
    total_zones = res_count + com_count + ind_count

    def zone_clear(zr, zc):
        """Check 3x3 area is safe for zone placement"""
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if pm[rr, rc]:
                    return False
        return True

    def zone_exists_near(zr, zc, positions):
        return any(abs(zr - pr) <= 2 and abs(zc - pc) <= 2 for (pr, pc) in positions)

    all_zones = res_pos + com_pos + ind_pos

    def pick_zone_tool():
        """Pick zone type for balance: ~50% RES, 25% COM, 25% IND"""
        t = total_zones
        if ind_count * 4 <= t:
            return Tool.INDUSTRIAL
        elif com_count * 4 <= t:
            return Tool.COMMERCIAL
        else:
            return Tool.RESIDENTIAL

    # Place vertical wires connecting wire spine to road rows
    # At each zone column, add a short vertical wire segment connecting wire_row to road rows
    # Actually, connect wire_row vertically upward to road_row_top and downward to road_row_bot
    # via short wire stubs at each zone column

    # Zone columns spaced every 3 tiles, offset from wire_start
    zone_cols = list(range(wire_start_col + 1, wire_end_col - 1, 3))

    # Add vertical wire stubs at each zone column between wire_row and road rows
    for zc in zone_cols:
        if not (0 <= zc < WORLD_W):
            continue
        # Connect wire_row upward to road_row_top
        for wr in range(wire_row - 1, road_row_top - 1, -1):
            if 0 <= wr < WORLD_H and not wm[wr, zc] and not rm[wr, zc]:
                # Only place wire between road and wire spine
                if wr > road_row_top:
                    return (Tool.WIRE, zc, wr)
        # Connect wire_row downward to road_row_bot
        for wr in range(wire_row + 1, road_row_bot + 1):
            if 0 <= wr < WORLD_H and not wm[wr, zc] and not rm[wr, zc]:
                if wr < road_row_bot:
                    return (Tool.WIRE, zc, wr)

    # Now place zones above top road and below bottom road
    for zc in zone_cols:
        if not (1 <= zc < WORLD_W - 1):
            continue

        # Check road coverage near this column
        road_top_near = any(abs(zc - rc) <= 1 for rc in road_top_cols)
        road_bot_near = any(abs(zc - rc) <= 1 for rc in road_bot_cols)

        # Top zone
        if road_top_near and 1 <= zone_row_top < WORLD_H - 1:
            if not zone_exists_near(zone_row_top, zc, all_zones) and zone_clear(zone_row_top, zc):
                tool = pick_zone_tool()
                return (tool, zc, zone_row_top)

        # Bottom zone
        if road_bot_near and 1 <= zone_row_bot < WORLD_H - 1:
            if not zone_exists_near(zone_row_bot, zc, all_zones) and zone_clear(zone_row_bot, zc):
                tool = pick_zone_tool()
                return (tool, zc, zone_row_bot)

    # Second neighborhood if population growing
    if obs.city_pop > 100 or obs.step > obs.n_steps // 3:
        # Second cluster: shifted down
        wire2_row = wire_row + 12
        road2_top = wire2_row - 2
        road2_bot = wire2_row + 2
        zone2_top = road2_top - 2
        zone2_bot = road2_bot + 2

        wire2_cols = sorted([c for (r, c) in zip(*np.where(wm)) if r == wire2_row])
        road2_top_cols = sorted([c for (r, c) in zip(*np.where(rm)) if r == road2_top])
        road2_bot_cols = sorted([c for (r, c) in zip(*np.where(rm)) if r == road2_bot])

        # Connect second wire row to plant via vertical wire
        # Simple: run a vertical wire from wire_row down to wire2_row at plant_cx+2
        vert_col = plant_cx + 2
        for wr in range(wire_row + 1, wire2_row + 1):
            if 0 <= wr < WORLD_H and not wm[wr, vert_col] and not rm[wr, vert_col]:
                return (Tool.WIRE, vert_col, wr)

        # Extend wire2 row
        if not wire2_cols or max(wire2_cols) < wire_end_col:
            start_c = max(wire2_cols) + 1 if wire2_cols else wire_start_col
            if wire2_row < WORLD_H - 2:
                return (Tool.WIRE, start_c, wire2_row)

        # Road rows for second cluster
        if not road2_top_cols or max(road2_top_cols) < wire_end_col:
            if road2_top >= 2:
                start_c = max(road2_top_cols) + 1 if road2_top_cols else wire_start_col
                if start_c <= wire_end_col:
                    return (Tool.ROAD, start_c, road2_top)

        if not road2_bot_cols or max(road2_bot_cols) < wire_end_col:
            if road2_bot < WORLD_H - 2:
                start_c = max(road2_bot_cols) + 1 if road2_bot_cols else wire_start_col
                if start_c <= wire_end_col:
                    return (Tool.ROAD, start_c, road2_bot)

        # Zones for second cluster
        for zc in zone_cols:
            if not (1 <= zc < WORLD_W - 1):
                continue
            r2_top_near = any(abs(zc - rc) <= 1 for rc in road2_top_cols)
            r2_bot_near = any(abs(zc - rc) <= 1 for rc in road2_bot_cols)
            w2_near = any(abs(zc - wc) <= 1 for wc in wire2_cols)

            if r2_top_near and w2_near and 1 <= zone2_top < WORLD_H - 1:
                if not zone_exists_near(zone2_top, zc, all_zones) and zone_clear(zone2_top, zc):
                    return (pick_zone_tool(), zc, zone2_top)

            if r2_bot_near and w2_near and 1 <= zone2_bot < WORLD_H - 1:
                if not zone_exists_near(zone2_bot, zc, all_zones) and zone_clear(zone2_bot, zc):
                    return (pick_zone_tool(), zc, zone2_bot)

    # Add nuclear plant if large population
    if obs.city_pop > 300:
        nuke_x = plant_cx + 20
        nuke_y = plant_cy
        if 1 <= nuke_y < WORLD_H - 1 and 1 <= nuke_x < WORLD_W - 1:
            if not np.any(pm[nuke_y-1:nuke_y+2, nuke_x-1:nuke_x+2]):
                return (Tool.NUCLEARPOWER, nuke_x, nuke_y)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map every step to decide next action
    - Places coal plant, then extends wire spine vertically
    - Builds road column adjacent to wire
    - Places zones (RES/COM/IND) flanking the road
    - Extends coverage as population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # Use a wider build corridor centered slightly left
    cx, cy = 55, WORLD_H // 2

    has_plant = np.any(pm)
    res_count = int(np.sum(res_m))
    com_count = int(np.sum(com_m))
    ind_count = int(np.sum(ind_m))

    # Phase 1: Place coal power plant
    if not has_plant:
        # Plant is 3x3, center at (cx-5, cy)
        return (Tool.COALPOWER, cx - 5, cy)

    # Find plant center from tile_map
    plant_positions = list(zip(*np.where(pm)))
    if plant_positions:
        pr, pc = plant_positions[0]
        # Estimate plant center (pm marks many tiles in footprint, find centroid)
        pr_arr = np.array([p[0] for p in plant_positions])
        pc_arr = np.array([p[1] for p in plant_positions])
        plant_cy = int(np.mean(pr_arr))
        plant_cx = int(np.mean(pc_arr))
    else:
        plant_cy, plant_cx = cy, cx - 5

    # Wire spine is immediately right of plant footprint
    wire_col = plant_cx + 4  # one tile right of plant footprint (plant_cx-1 to plant_cx+1 are footprint? Actually 3x3 centered)
    # Plant footprint: plant_cx-1..plant_cx+1; wire_col = plant_cx + 2
    wire_col = plant_cx + 2
    road_col = wire_col + 2  # road 2 tiles right of wire

    wire_positions = list(zip(*np.where(wm)))
    road_positions = list(zip(*np.where(rm)))

    wire_col_rows = sorted([r for (r, c) in wire_positions if c == wire_col])
    road_col_rows = sorted([r for (r, c) in road_positions if c == road_col])

    # Determine vertical extent based on population
    pop = obs.city_pop
    half_extent = 10 + min(20, pop // 30)
    target_min = max(1, plant_cy - half_extent)
    target_max = min(WORLD_H - 2, plant_cy + half_extent)

    # Phase 2: Start wire spine adjacent to plant
    if not wire_col_rows:
        if 0 <= wire_col < WORLD_W and em[plant_cy, wire_col]:
            return (Tool.WIRE, wire_col, plant_cy)
        # Try adjacent rows
        for dy in range(1, 6):
            for nr in [plant_cy + dy, plant_cy - dy]:
                if 0 <= nr < WORLD_H and 0 <= wire_col < WORLD_W and em[nr, wire_col]:
                    return (Tool.WIRE, wire_col, nr)
        return None

    min_row = min(wire_col_rows)
    max_row = max(wire_col_rows)

    # Phase 3: Extend wire spine downward first, then upward
    if max_row < target_max:
        nr = max_row + 1
        if nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
            return (Tool.WIRE, wire_col, nr)

    if min_row > target_min:
        nr = min_row - 1
        if nr >= 0 and (em[nr, wire_col] or wm[nr, wire_col]):
            return (Tool.WIRE, wire_col, nr)

    # Phase 4: Build road column (scan from top of wire extent)
    # Road needs to align with wire rows for coverage
    for r in wire_col_rows:
        if 0 <= road_col < WORLD_W and 0 <= r < WORLD_H:
            if not rm[r, road_col] and em[r, road_col]:
                return (Tool.ROAD, road_col, r)
            # Also build a connector wire between wire_col and road_col
            mid_col = wire_col + 1
            if 0 <= mid_col < WORLD_W and em[r, mid_col] and not wm[r, mid_col]:
                return (Tool.WIRE, mid_col, r)

    # Phase 5: Place zones reactively
    # Left zone col (powered by wire spine via lateral wire)
    # Right zone col (adjacent to road)
    left_zone_col = wire_col - 3   # 3 tiles left of wire spine (center of 3x3 zone)
    right_zone_col = road_col + 3  # 3 tiles right of road

    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc2 = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc2 < WORLD_W):
                    return False
                if not em[rr, rc2]:
                    return False
        return True

    def has_zone_nearby(zr, zc, existing_zones):
        return any(abs(zr - pr) <= 2 and abs(zc - pc) <= 2 for (pr, pc) in existing_zones)

    res_positions = list(zip(*np.where(res_m)))
    com_positions = list(zip(*np.where(com_m)))
    ind_positions = list(zip(*np.where(ind_m)))
    all_zone_pos = res_positions + com_positions + ind_positions

    # Zone rows spaced by 4 for less overlap
    zone_rows = list(range(max(2, target_min), min(WORLD_H - 2, target_max + 1), 4))

    for zr in zone_rows:
        # Check if this row has wire or road coverage nearby
        wire_near = any(abs(zr - wr) <= 3 for wr in wire_col_rows)
        road_near_row = any(abs(zr - rr) <= 2 for rr in road_col_rows)

        if wire_near and road_near_row:
            # Try right zone first (road access)
            zc = right_zone_col
            if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                if not has_zone_nearby(zr, zc, all_zone_pos) and zone_area_free(zr, zc):
                    # Balance zone types
                    if com_count < res_count // 3:
                        return (Tool.COMMERCIAL, zc, zr)
                    elif ind_count < res_count // 3:
                        return (Tool.INDUSTRIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

            # Try left zone (powered via wire)
            zc = left_zone_col
            if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                if not has_zone_nearby(zr, zc, all_zone_pos) and zone_area_free(zr, zc):
                    return (Tool.RESIDENTIAL, zc, zr)

    # Phase 6: Build lateral wires to left zones
    for wr in wire_col_rows:
        for wc in range(wire_col - 1, max(0, left_zone_col - 2), -1):
            if 0 <= wc < WORLD_W and em[wr, wc]:
                return (Tool.WIRE, wc, wr)

    # Phase 7: Extend road to reach right zones
    for wr in wire_col_rows:
        for rc in range(road_col + 1, min(WORLD_W - 1, right_zone_col + 2)):
            if 0 <= rc < WORLD_W and em[wr, rc] and not rm[wr, rc]:
                return (Tool.ROAD, rc, wr)

    # Phase 8: If population growing, add a second road column further right
    if pop > 200:
        road_col2 = right_zone_col + 4
        right_zone_col2 = road_col2 + 3
        for r in wire_col_rows:
            if 0 <= road_col2 < WORLD_W and 0 <= r < WORLD_H:
                if not rm[r, road_col2] and em[r, road_col2]:
                    return (Tool.ROAD, road_col2, r)

        zone_rows2 = list(range(max(2, target_min), min(WORLD_H - 2, target_max + 1), 4))
        for zr in zone_rows2:
            road_near2 = any(abs(zr - rr) <= 2 for (rr, rc2) in road_positions if rc2 == road_col2)
            if road_near2:
                zc = right_zone_col2
                if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                    if not has_zone_nearby(zr, zc, all_zone_pos) and zone_area_free(zr, zc):
                        return (Tool.RESIDENTIAL, zc, zr)

    # Phase 9: Add lateral wires for right zones from wire spine
    if pop > 100:
        for wr in wire_col_rows:
            for wc in range(wire_col + 1, min(WORLD_W - 1, road_col + 1)):
                if 0 <= wc < WORLD_W and em[wr, wc] and not wm[wr, wc]:
                    return (Tool.WIRE, wc, wr)

    # Phase 10: Add more zones in gaps reactively
    if pop > 300:
        extra_cols = [left_zone_col - 4, right_zone_col + 4]
        for zc in extra_cols:
            for zr in zone_rows:
                if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                    if not has_zone_nearby(zr, zc, all_zone_pos) and zone_area_free(zr, zc):
                        road_near = any(abs(zr - rr) <= 3 and abs(zc - rc2) <= 5
                                        for (rr, rc2) in road_positions)
                        if road_near:
                            return (Tool.RESIDENTIAL, zc, zr)

    return None

def act(obs, state):
    """
    Variation: Grid-based layout instead of spine-based.
    Place power plant at top-left area, then build a GRID of roads (horizontal + vertical)
    with zones filling the grid cells. Wire runs along one road row.
    This creates a 2D city block instead of a vertical spine.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    # Initialize state
    if 'phase' not in state:
        state['phase'] = 0
        state['step'] = 0
    state['step'] += 1

    # City center area - use upper-left quadrant for compact grid
    base_x = 30  # left edge of our grid
    base_y = 20  # top edge of our grid

    # Power plant at left of grid
    plant_x = base_x - 6
    plant_y = base_y + 6

    # Grid layout:
    # Road columns at: base_x, base_x+8, base_x+16, base_x+24
    # Road rows at: base_y, base_y+8, base_y+16, base_y+24
    # Wire row at base_y (top horizontal road also has wire under/beside it)
    # Zones in 3x3 cells between road intersections

    road_cols = [base_x + i * 8 for i in range(5)]  # vertical roads
    road_rows = [base_y + i * 8 for i in range(5)]  # horizontal roads
    # Wire runs along the top road row
    wire_row = base_y

    # Zone centers between roads:
    # Between road_cols[i] and road_cols[i+1], center at road_cols[i]+4
    # Between road_rows[j] and road_rows[j+1], center at road_rows[j]+4
    zone_cols = [base_x + i * 8 + 4 for i in range(4)]
    zone_rows_list = [base_y + j * 8 + 4 for j in range(4)]

    def pick_tool(zc, zr):
        # Mix: vary by position
        r = resm[zr-1:zr+2, zc-1:zc+2].sum() if (1<=zr<WORLD_H-1 and 1<=zc<WORLD_W-1) else 0
        c = comm[zr-1:zr+2, zc-1:zc+2].sum() if (1<=zr<WORLD_H-1 and 1<=zc<WORLD_W-1) else 0
        i = indm[zr-1:zr+2, zc-1:zc+2].sum() if (1<=zr<WORLD_H-1 and 1<=zc<WORLD_W-1) else 0
        total = resm.sum() + comm.sum() + indm.sum()
        if total == 0:
            return Tool.RESIDENTIAL
        rt = resm.sum(); ct = comm.sum(); it = indm.sum()
        t = max(1, rt + ct + it)
        if it / t < 0.20:
            return Tool.INDUSTRIAL
        if ct / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        all_zone = resm | comm | indm
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone[rr, rc]:
                    return False
        return True

    def zone_there(zr, zc):
        all_zone = resm | comm | indm
        if not (0 <= zr < WORLD_H and 0 <= zc < WORLD_W):
            return True
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone[rr, rc]:
                        return True
        return False

    # Phase 1: Place power plant
    if not np.any(pm):
        if (2 <= plant_y <= WORLD_H-3 and 2 <= plant_x <= WORLD_W-3):
            return (Tool.COALPOWER, plant_x, plant_y)
        return (Tool.COALPOWER, 10, 25)

    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Phase 2: Wire horizontal from plant to grid area along wire_row
    # Wire row = base_y, connect from plant_cx+2 to road_cols[-1]+2
    wire_end = road_cols[-1] + 3
    wire_start = plant_cx + 2
    for wc in range(wire_start, wire_end + 1):
        if 0 <= wc < WORLD_W and 0 <= wire_row < WORLD_H:
            if not wm[wire_row, wc] and not pm[wire_row, wc]:
                if em[wire_row, wc] or rm[wire_row, wc]:
                    return (Tool.WIRE, wc, wire_row)

    # Also wire from plant down to wire_row if needed
    if plant_cy != wire_row:
        step_dir = 1 if wire_row > plant_cy else -1
        for wr in range(plant_cy + step_dir, wire_row + step_dir, step_dir):
            wc_col = plant_cx + 2
            if 0 <= wr < WORLD_H and 0 <= wc_col < WORLD_W:
                if not wm[wr, wc_col] and not pm[wr, wc_col]:
                    if em[wr, wc_col]:
                        return (Tool.WIRE, wc_col, wr)
                    break

    # Phase 3: Build vertical road columns
    for rc in road_cols:
        if not (0 <= rc < WORLD_W):
            continue
        for rr in road_rows:
            if not (0 <= rr < WORLD_H):
                continue
            # Build road from top road_row to bottom road_row along this col
        r_start = road_rows[0]
        r_end = road_rows[-1]
        for rr in range(r_start, r_end + 1):
            if 0 <= rr < WORLD_H:
                if not rm[rr, rc] and (em[rr, rc] or wm[rr, rc]):
                    # Don't place road on plant
                    if not pm[rr, rc]:
                        return (Tool.ROAD, rc, rr)

    # Phase 4: Build horizontal road rows
    for rr in road_rows:
        if not (0 <= rr < WORLD_H):
            continue
        c_start = road_cols[0]
        c_end = road_cols[-1]
        for rc in range(c_start, c_end + 1):
            if 0 <= rc < WORLD_W:
                if not rm[rr, rc] and (em[rr, rc] or wm[rr, rc]):
                    if not pm[rr, rc]:
                        return (Tool.ROAD, rc, rr)

    # Phase 5: Wire along top road row to power zones
    # Also wire down vertical road columns from top
    for rc in road_cols:
        if not (0 <= rc < WORLD_W):
            continue
        # Wire downward from wire_row
        for rr in range(wire_row, road_rows[-1] + 1):
            if 0 <= rr < WORLD_H:
                if not wm[rr, rc] and not pm[rr, rc] and (em[rr, rc] or rm[rr, rc]):
                    return (Tool.WIRE, rc, rr)

    # Phase 6: Place zones in grid cells
    for zr in zone_rows_list:
        for zc in zone_cols:
            if not (1 <= zr <= WORLD_H-2 and 1 <= zc <= WORLD_W-2):
                continue
            if zone_there(zr, zc):
                continue
            if not zone_area_ok(zr, zc):
                continue
            # Check wire and road nearby
            r0 = max(0, zr-4); r1 = min(WORLD_H, zr+5)
            c0 = max(0, zc-4); c1 = min(WORLD_W, zc+5)
            has_wire = np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])
            has_road = np.any(rm[r0:r1, c0:c1])
            if has_wire and has_road:
                return (pick_tool(zc, zr), zc, zr)

    # Phase 7: Second power plant if pop growing
    if obs.city_pop > 300 and int(np.sum(pm)) < 9:
        px2, py2 = plant_cx + 25, plant_cy
        if 2 <= py2 <= WORLD_H-3 and 2 <= px2 <= WORLD_W-3:
            area_clear = True
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if not (em[py2+dr, px2+dc] or pm[py2+dr, px2+dc]):
                        area_clear = False
            if area_clear:
                return (Tool.COALPOWER, px2, py2)

    # Phase 8: Extend grid downward for more zones
    if obs.city_pop > 150:
        ext_rows = [road_rows[-1] + 8, road_rows[-1] + 16]
        ext_zone_rows = [road_rows[-1] + 4, road_rows[-1] + 12]
        for rr in ext_rows:
            if 0 <= rr < WORLD_H:
                c_start = road_cols[0]; c_end = road_cols[-1]
                for rc in range(c_start, c_end+1):
                    if 0 <= rc < WORLD_W and not rm[rr, rc] and em[rr, rc] and not pm[rr, rc]:
                        return (Tool.ROAD, rc, rr)
        for rc in road_cols:
            if 0 <= rc < WORLD_W:
                for rr in range(road_rows[-1], min(road_rows[-1]+17, WORLD_H)):
                    if not rm[rr, rc] and em[rr, rc] and not pm[rr, rc]:
                        return (Tool.ROAD, rc, rr)
                    # Also wire
                    if not wm[rr, rc] and not pm[rr, rc] and (em[rr, rc] or rm[rr, rc]):
                        return (Tool.WIRE, rc, rr)
        for zr in ext_zone_rows:
            for zc in zone_cols:
                if not (1 <= zr <= WORLD_H-2 and 1 <= zc <= WORLD_W-2):
                    continue
                if zone_there(zr, zc):
                    continue
                if not zone_area_ok(zr, zc):
                    continue
                r0=max(0,zr-4); r1=min(WORLD_H,zr+5); c0=max(0,zc-4); c1=min(WORLD_W,zc+5)
                hw = np.any(wm[r0:r1,c0:c1]) or np.any(pm[r0:r1,c0:c1])
                hr = np.any(rm[r0:r1,c0:c1])
                if hw and hr:
                    return (pick_tool(zc, zr), zc, zr)

    # Phase 9: Extra zones to right if pop high
    if obs.city_pop > 400:
        ext_cols = [road_cols[-1] + 8, road_cols[-1] + 16]
        ext_zone_cols = [road_cols[-1] + 4, road_cols[-1] + 12]
        for rc in ext_cols:
            if 0 <= rc < WORLD_W:
                r_start = road_rows[0]; r_end = road_rows[-1]
                for rr in range(r_start, r_end+1):
                    if not rm[rr, rc] and em[rr, rc] and not pm[rr, rc]:
                        return (Tool.ROAD, rc, rr)
        for zc in ext_zone_cols:
            for zr in zone_rows_list:
                if not (1 <= zr <= WORLD_H-2 and 1 <= zc <= WORLD_W-2):
                    continue
                if zone_there(zr, zc):
                    continue
                if not zone_area_ok(zr, zc):
                    continue
                r0=max(0,zr-5); r1=min(WORLD_H,zr+6); c0=max(0,zc-5); c1=min(WORLD_W,zc+6)
                hw = np.any(wm[r0:r1,c0:c1]) or np.any(pm[r0:r1,c0:c1])
                hr = np.any(rm[r0:r1,c0:c1])
                if hw and hr:
                    return (pick_tool(zc, zr), zc, zr)

    return None

def act(obs, state):
    """
    Variation: horizontal spine instead of vertical.
    Road runs east-west, wire runs parallel above it.
    Zones placed above and below the road strip.
    Multiple clusters stacked vertically.
    Better zone mix (more COM/IND).
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        # Want roughly 40% RES, 30% COM, 30% IND
        if ind_count / t < 0.28:
            return Tool.INDUSTRIAL
        if com_count / t < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    all_zone_mask = resm | comm | indm

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    # Place power plant at top-left of center area
    plant_x = cx - 15
    plant_y = cy - 5

    if not np.any(pm):
        return (Tool.COALPOWER, plant_x, plant_y)

    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Horizontal layout:
    # wire_row runs horizontally just below the plant
    # road_row runs 2 below wire_row
    # zones above wire_row and below road_row

    wire_row = plant_cy + 2
    road_row = wire_row + 2
    top_zone_row = wire_row - 3    # zones above wire
    bot_zone_row = road_row + 3    # zones below road

    wire_row = max(1, min(WORLD_H - 2, wire_row))
    road_row = max(1, min(WORLD_H - 2, road_row))
    top_zone_row = max(1, min(WORLD_H - 2, top_zone_row))
    bot_zone_row = max(1, min(WORLD_H - 2, bot_zone_row))

    # Dynamic spine extent (horizontal)
    if obs.city_pop < 100:
        spine_extent = 12
    elif obs.city_pop < 300:
        spine_extent = 20
    elif obs.city_pop < 600:
        spine_extent = 30
    else:
        spine_extent = 40

    target_left = max(1, cx - spine_extent)
    target_right = min(WORLD_W - 2, cx + spine_extent)

    # Phase 2: Build wire row horizontally from plant
    wire_cols_on_spine = sorted([c for c in range(WORLD_W) if wm[wire_row, c]])

    if not wire_cols_on_spine:
        # Start wire adjacent to plant
        start_c = plant_cx + 2
        if 0 <= start_c < WORLD_W and (em[wire_row, start_c] or wm[wire_row, start_c]):
            return (Tool.WIRE, start_c, wire_row)
        return (Tool.WIRE, plant_cx, wire_row)

    min_wire_col = min(wire_cols_on_spine)
    max_wire_col = max(wire_cols_on_spine)

    # Phase 3: Extend wire right
    if max_wire_col < target_right:
        nc = max_wire_col + 1
        if nc < WORLD_W and not pm[wire_row, nc]:
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # Phase 4: Extend wire left
    if min_wire_col > target_left:
        nc = min_wire_col - 1
        if nc >= 0 and not pm[wire_row, nc]:
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # Phase 5: Build road row parallel to wire
    wire_cols_set = set(wire_cols_on_spine)
    for c in wire_cols_on_spine:
        if 0 <= c < WORLD_W and 0 <= road_row < WORLD_H:
            if not rm[road_row, c] and em[road_row, c]:
                return (Tool.ROAD, c, road_row)

    road_cols_on_row = sorted([c for c in range(WORLD_W) if rm[road_row, c]])

    # Phase 6: Place zones along the corridor
    zone_cols = list(range(max(1, target_left), min(WORLD_W - 1, target_right + 1), 3))

    for zc in zone_cols:
        wire_near = any(abs(zc - wc) <= 2 for wc in wire_cols_on_spine)
        road_near = any(abs(zc - rc) <= 2 for rc in road_cols_on_row)

        if wire_near and road_near:
            # Try top zone row
            zr = top_zone_row
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc, 5) and has_road_nearby(zr, zc, 5):
                    return (pick_tool(), zc, zr)

            # Try bottom zone row
            zr = bot_zone_row
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc, 5) and has_road_nearby(zr, zc, 5):
                    return (pick_tool(), zc, zr)

    # Phase 7: Lateral wires from spine to top/bottom zones
    for wc in wire_cols_on_spine:
        # Wire up toward top zones
        for wr in range(wire_row - 1, max(top_zone_row - 2, 0), -1):
            if wm[wr, wc]:
                break
            if em[wr, wc] and not pm[wr, wc]:
                return (Tool.WIRE, wc, wr)
            elif not em[wr, wc]:
                break

    # Phase 8: Road extensions to reach top zones
    for rc in wire_cols_on_spine:
        if not rm[road_row, rc]:
            continue
        # Road up to top zone
        for rr in range(road_row - 1, max(top_zone_row - 2, 0), -1):
            if rm[rr, rc]:
                break
            if em[rr, rc] and not pm[rr, rc]:
                return (Tool.ROAD, rc, rr)
            elif not em[rr, rc]:
                break
        # Road down to bottom zone
        for rr in range(road_row + 1, min(bot_zone_row + 2, WORLD_H)):
            if rm[rr, rc]:
                break
            if em[rr, rc] and not pm[rr, rc]:
                return (Tool.ROAD, rc, rr)
            elif not em[rr, rc]:
                break

    # Phase 9: Wire down to bottom zones
    for wc in wire_cols_on_spine:
        for wr in range(wire_row + 1, min(bot_zone_row + 2, WORLD_H)):
            if wm[wr, wc]:
                break
            if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                return (Tool.WIRE, wc, wr)
            elif not em[wr, wc] and not rm[wr, wc]:
                break

    # Phase 10: Second power plant when pop grows
    if obs.city_pop > 250 and int(np.sum(pm)) < 9:
        px2 = plant_cx + 25
        py2 = plant_cy
        if 2 <= py2 <= WORLD_H - 3 and 2 <= px2 <= WORLD_W - 3:
            area_clear = True
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if not (em[py2 + dr, px2 + dc] or pm[py2 + dr, px2 + dc]):
                        area_clear = False
            if area_clear:
                return (Tool.COALPOWER, px2, py2)

    # Phase 11: Second cluster row above when pop >= 150
    if obs.city_pop >= 150:
        wire_row2 = wire_row - 8
        road_row2 = wire_row2 - 2
        top_zone_row2 = wire_row2 + 3
        bot_zone_row2 = road_row2 - 3

        wire_row2 = max(1, min(WORLD_H - 2, wire_row2))
        road_row2 = max(1, min(WORLD_H - 2, road_row2))
        top_zone_row2 = max(1, min(WORLD_H - 2, top_zone_row2))
        bot_zone_row2 = max(1, min(WORLD_H - 2, bot_zone_row2))

        wire_cols2 = sorted([c for c in range(WORLD_W) if wm[wire_row2, c]])
        road_cols2 = set(c for c in range(WORLD_W) if rm[road_row2, c])

        if not wire_cols2:
            # Build vertical wire bridge from main spine to cluster2
            bridge_col = plant_cx + 2
            if 0 <= bridge_col < WORLD_W:
                for wr in range(wire_row - 1, wire_row2 - 1, -1):
                    if 0 <= wr < WORLD_H:
                        if not wm[wr, bridge_col] and em[wr, bridge_col] and not pm[wr, bridge_col]:
                            return (Tool.WIRE, bridge_col, wr)
                        elif not em[wr, bridge_col] and not wm[wr, bridge_col]:
                            break
        else:
            min_wc2 = min(wire_cols2)
            max_wc2 = max(wire_cols2)

            if max_wc2 < target_right:
                nc = max_wc2 + 1
                if nc < WORLD_W and em[wire_row2, nc]:
                    return (Tool.WIRE, nc, wire_row2)
            if min_wc2 > target_left:
                nc = min_wc2 - 1
                if nc >= 0 and em[wire_row2, nc]:
                    return (Tool.WIRE, nc, wire_row2)

            for wc in wire_cols2:
                if wc not in road_cols2 and em[road_row2, wc]:
                    return (Tool.ROAD, wc, road_row2)

            for zc in zone_cols:
                wire_near2 = any(abs(zc - wc) <= 2 for wc in wire_cols2)
                road_near2 = any(abs(zc - rc) <= 2 for rc in road_cols2)
                if wire_near2 and road_near2:
                    for zr in [top_zone_row2, bot_zone_row2]:
                        if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                            if has_wire_nearby(zr, zc, 6) and has_road_nearby(zr, zc, 5):
                                return (pick_tool(), zc, zr)

    # Phase 12: Third cluster row below when pop >= 350
    if obs.city_pop >= 350:
        wire_row3 = road_row + 8
        road_row3 = wire_row3 + 2
        top_zone_row3 = wire_row3 - 3
        bot_zone_row3 = road_row3 + 3

        wire_row3 = max(1, min(WORLD_H - 2, wire_row3))
        road_row3 = max(1, min(WORLD_H - 2, road_row3))
        top_zone_row3 = max(1, min(WORLD_H - 2, top_zone_row3))
        bot_zone_row3 = max(1, min(WORLD_H - 2, bot_zone_row3))

        wire_cols3 = sorted([c for c in range(WORLD_W) if wm[wire_row3, c]])
        road_cols3 = set(c for c in range(WORLD_W) if rm[road_row3, c])

        if not wire_cols3:
            bridge_col = plant_cx + 2
            if 0 <= bridge_col < WORLD_W:
                for wr in range(road_row + 1, wire_row3 + 1):
                    if 0 <= wr < WORLD_H:
                        if not wm[wr, bridge_col] and em[wr, bridge_col] and not pm[wr, bridge_col]:
                            return (Tool.WIRE, bridge_col, wr)
                        elif not em[wr, bridge_col] and not wm[wr, bridge_col]:
                            break
        else:
            min_wc3 = min(wire_cols3)
            max_wc3 = max(wire_cols3)

            if max_wc3 < target_right:
                nc = max_wc3 + 1
                if nc < WORLD_W and em[wire_row3, nc]:
                    return (Tool.WIRE, nc, wire_row3)
            if min_wc3 > target_left:
                nc = min_wc3 - 1
                if nc >= 0 and em[wire_row3, nc]:
                    return (Tool.WIRE, nc, wire_row3)

            for wc in wire_cols3:
                if wc not in road_cols3 and em[road_row3, wc]:
                    return (Tool.ROAD, wc, road_row3)

            for zc in zone_cols:
                wire_near3 = any(abs(zc - wc) <= 2 for wc in wire_cols3)
                road_near3 = any(abs(zc - rc) <= 2 for rc in road_cols3)
                if wire_near3 and road_near3:
                    for zr in [top_zone_row3, bot_zone_row3]:
                        if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                            if has_wire_nearby(zr, zc, 6) and has_road_nearby(zr, zc, 5):
                                return (pick_tool(), zc, zr)

    # Phase 13: Extra zone rows when pop > 300
    if obs.city_pop > 300:
        extra_rows = [top_zone_row - 5, bot_zone_row + 5]
        for zr in extra_rows:
            if 2 <= zr <= WORLD_H - 3:
                for zc in zone_cols:
                    if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                        if has_road_nearby(zr, zc, 6) and has_wire_nearby(zr, zc, 7):
                            return (pick_tool(), zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder combining best of both parents.
    - Reads tile_map every step to decide next action
    - Places coal plant, then wires, then roads, then zones
    - Zones placed wherever road+wire coverage exists
    - Second plant when needed
    - Services when population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        r = res_count / t
        c = com_count / t
        i = ind_count / t
        if c < 0.25:
            return Tool.COMMERCIAL
        if i < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Build a set of all zone tile positions for clearance checks
    zone_set = set()
    for ry, rx in zip(*np.where(resm | comm | indm)):
        zone_set.add((int(ry), int(rx)))

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    # === Step 1: Place first coal plant ===
    if not np.any(pm):
        # Place at fixed anchor - left-center area
        return (Tool.COALPOWER, 20, 50)

    plant_ys, plant_xs = np.where(pm)
    # Primary plant center
    px1 = int(plant_xs[0]) if len(plant_xs) > 0 else 20
    py1 = int(plant_ys[0]) if len(plant_ys) > 0 else 50

    # Road spine parameters derived from plant position
    spine_y = py1
    road_top = spine_y - 3
    road_bot = spine_y + 3
    road_start = px1 + 3
    road_end = min(px1 + 65, WORLD_W - 4)

    # === Step 2: Extend wire spine rightward from plant ===
    wire_end_x = road_end
    for wx in range(px1 + 2, wire_end_x + 1):
        wy = spine_y
        if not in_bounds(wx, wy):
            break
        if bool(pm[wy, wx]):
            continue
        if not bool(wm[wy, wx]):
            if bool(em[wy, wx]):
                return (Tool.WIRE, wx, wy)
            break  # blocked

    # === Step 3: Build top road row ===
    for rx in range(road_start, road_end + 1):
        ry = road_top
        if not in_bounds(rx, ry):
            break
        if bool(rm[ry, rx]) or bool(pm[ry, rx]):
            continue
        if bool(em[ry, rx]):
            return (Tool.ROAD, rx, ry)
        break

    # === Step 4: Build bottom road row ===
    for rx in range(road_start, road_end + 1):
        ry = road_bot
        if not in_bounds(rx, ry):
            break
        if bool(rm[ry, rx]) or bool(pm[ry, rx]):
            continue
        if bool(em[ry, rx]):
            return (Tool.ROAD, rx, ry)
        break

    # === Step 5: Vertical wire branches every 6 cols to reach zone rows ===
    wire_ys_arr, wire_xs_arr = np.where(wm)
    branch_cols = list(range(px1 + 6, wire_end_x + 1, 6))
    for bx in branch_cols:
        if not in_bounds(bx, spine_y):
            continue
        # Only branch from existing wire
        if not (bool(wm[spine_y, bx]) or bool(pm[spine_y, bx])):
            continue
        for sign in [-1, 1]:
            for dy in range(1, 5):
                wy2 = spine_y + sign * dy
                wx2 = bx
                if not in_bounds(wx2, wy2):
                    break
                if bool(wm[wy2, wx2]) or bool(pm[wy2, wx2]):
                    continue
                if bool(em[wy2, wx2]):
                    return (Tool.WIRE, wx2, wy2)
                break

    # === Step 6: Zone placement - scan for road+wire covered empty cells ===
    # Compute neighbor masks efficiently
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    # Keep safe margins
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        best = None
        best_score = -1
        # Scan a subset for efficiency
        step_mod = obs.step % max(len(cxs_arr), 1)
        n_check = min(len(cxs_arr), 80)
        for offset in range(n_check):
            k = (step_mod + offset * 7) % len(cxs_arr)
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                # Prefer locations close to spine_y, and further right (more developed)
                score = 100 - abs(zy - spine_y) + (zx - road_start) * 0.1
                if score > best_score:
                    best_score = score
                    best = (zx, zy)
        if best is not None:
            return (pick_tool(), best[0], best[1])

    # === Step 7: Second power plant when zones grow ===
    if total_zones > 8 or obs.city_pop > 150:
        p2x = min(px1 + 55, WORLD_W - 5)
        p2y = py1
        nearby_plant = any(
            in_bounds(p2x + dx, p2y + dy) and bool(pm[p2y + dy, p2x + dx])
            for dy in range(-5, 6) for dx in range(-5, 6)
        )
        if not nearby_plant and in_bounds(p2x, p2y) and bool(em[p2y, p2x]):
            return (Tool.COALPOWER, p2x, p2y)

    # === Step 8: Services for happiness ===
    if obs.city_pop > 100:
        # Fire station above top road
        fx, fy = road_start + 2, road_top - 4
        if in_bounds(fx, fy) and bool(em[fy, fx]):
            return (Tool.FIRESTATION, fx, fy)
        # Police station below bottom road
        px2, py2 = road_start + 8, road_bot + 4
        if in_bounds(px2, py2) and bool(em[py2, px2]):
            return (Tool.POLICESTATION, px2, py2)

    # === Step 9: Extend road frontier reactively ===
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = int(obs.step * 13) % max(len(road_xs_arr), 1)
        for attempt in range(min(len(road_xs_arr), 10)):
            k = (step_k + attempt * 3) % len(road_xs_arr)
            rx_s = int(road_xs_arr[k])
            ry_s = int(road_ys_arr[k])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = rx_s + dx2, ry_s + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    # Only extend along road rows
                    if ny2 == road_top or ny2 == road_bot:
                        return (Tool.ROAD, nx2, ny2)

    # === Step 10: Extend wire frontier reactively ===
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 11) % max(len(wire_xs_arr), 1)
        for attempt in range(min(len(wire_xs_arr), 10)):
            k = (step_k2 + attempt * 5) % len(wire_xs_arr)
            wx_s = int(wire_xs_arr[k])
            wy_s = int(wire_ys_arr[k])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = wx_s + dx2, wy_s + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    if ny2 == spine_y:
                        return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Improved policy: horizontal road spine with vertical wire connections.
    Plant placed first, then a horizontal road across map center,
    wire connects plant to road, zones placed above and below road.
    Two neighborhoods: left cluster (RES+IND) and right cluster (RES+COM).
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # Initialize state
    if 'phase' not in state:
        state['phase'] = 0
        state['step'] = 0
    state['step'] += 1

    # Layout constants
    # Two clusters: left cluster centered at x=35, right cluster at x=80
    # Horizontal road spine at y=50
    # Power plant at (20, 50)
    road_row = 50
    plant_x, plant_y = 20, 50

    # Wire column connecting plant to road spine area
    wire_col_main = 20  # same x as plant, runs vertically if needed

    # Left cluster: x=35, zones at rows 44,47,50,53,56
    left_cx = 35
    # Right cluster: x=80, zones at rows 44,47,50,53,56
    right_cx = 80

    # Road columns range
    road_col_start = 22
    road_col_end = 95

    has_plant = np.any(pm)

    res_count = int(np.sum(res_m))
    com_count = int(np.sum(com_m))
    ind_count = int(np.sum(ind_m))

    # Helper: check if zone footprint (3x3) is clear
    def zone_clear(zr, zc):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                r2, c2 = zr + dr, zc + dc
                if r2 < 0 or r2 >= WORLD_H or c2 < 0 or c2 >= WORLD_W:
                    return False
                if not em[r2, c2]:
                    return False
        return True

    def zone_exists_near(zr, zc, mask, radius=3):
        r1, r2 = max(0, zr - radius), min(WORLD_H, zr + radius + 1)
        c1, c2 = max(0, zc - radius), min(WORLD_W, zc + radius + 1)
        return np.any(mask[r1:r2, c1:c2])

    def near_wire(zr, zc, radius=3):
        r1, r2 = max(0, zr - radius), min(WORLD_H, zr + radius + 1)
        c1, c2 = max(0, zc - radius), min(WORLD_W, zc + radius + 1)
        return np.any(wm[r1:r2, c1:c2])

    def near_road(zr, zc, radius=3):
        r1, r2 = max(0, zr - radius), min(WORLD_H, zr + radius + 1)
        c1, c2 = max(0, zc - radius), min(WORLD_W, zc + radius + 1)
        return np.any(rm[r1:r2, c1:c2])

    # Phase 1: Place coal plant
    if not has_plant:
        return (Tool.COALPOWER, plant_x, plant_y)

    # Find actual plant position
    plant_positions = list(zip(*np.where(pm)))
    if plant_positions:
        pr, pc = plant_positions[0]
        plant_y = pr
        plant_x = pc

    # Phase 2: Wire from plant rightward to wire spine point
    # Wire runs from plant_x+3 (just right of plant) to left_cx-3
    # along plant_y row
    wire_row = plant_y
    wire_start = plant_x + 3  # right edge of plant + 1
    wire_end_left = left_cx + 3   # reaches left cluster
    wire_end_right = right_cx + 3  # reaches right cluster

    # Build wire along road_row from plant right edge to right cluster
    for wc in range(wire_start, wire_end_right + 1):
        if 0 <= wc < WORLD_W and not wm[wire_row, wc] and em[wire_row, wc]:
            return (Tool.WIRE, wc, wire_row)

    # Phase 3: Build horizontal road spine (skip wire cells and plant cells)
    for rc in range(road_col_start, road_col_end + 1):
        if not rm[road_row, rc] and not wm[road_row, rc]:
            # Don't bulldoze the wire spine
            if em[road_row, rc]:
                return (Tool.ROAD, rc, road_row)

    # Phase 4: Vertical roads at zone columns to connect zones to road spine
    # Left cluster vertical roads: x = left_cx-4 and left_cx+4
    left_road_col_a = left_cx - 4
    left_road_col_b = left_cx + 4
    right_road_col_a = right_cx - 4
    right_road_col_b = right_cx + 4

    zone_rows_above = [road_row - 3, road_row - 6, road_row - 9]
    zone_rows_below = [road_row + 3, road_row + 6, road_row + 9]
    all_zone_rows = zone_rows_above + zone_rows_below

    # Build vertical roads connecting zone rows to main road
    for vroad_col in [left_road_col_a, left_road_col_b, right_road_col_a, right_road_col_b]:
        if 0 <= vroad_col < WORLD_W:
            # Road from road_row - 10 to road_row + 10
            for vr in range(road_row - 10, road_row + 11):
                if 0 <= vr < WORLD_H and not rm[vr, vroad_col] and em[vr, vroad_col]:
                    return (Tool.ROAD, vroad_col, vr)

    # Phase 5: Wire laterals from main wire to zone columns
    # Wire to left cluster center
    for lr in all_zone_rows:
        if 0 <= lr < WORLD_H:
            # Wire from left_cx-2 to left_cx+2 at zone row (connect to zone center)
            for wc in range(left_cx - 2, left_cx + 3):
                if 0 <= wc < WORLD_W and em[lr, wc] and not wm[lr, wc]:
                    # Only place if adjacent to existing wire
                    adj_wire = False
                    for ddr, ddc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        rr, cc = lr+ddr, wc+ddc
                        if 0 <= rr < WORLD_H and 0 <= cc < WORLD_W and wm[rr, cc]:
                            adj_wire = True
                            break
                    if adj_wire:
                        return (Tool.WIRE, wc, lr)

    # Wire to right cluster center
    for lr in all_zone_rows:
        if 0 <= lr < WORLD_H:
            for wc in range(right_cx - 2, right_cx + 3):
                if 0 <= wc < WORLD_W and em[lr, wc] and not wm[lr, wc]:
                    adj_wire = False
                    for ddr, ddc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        rr, cc = lr+ddr, wc+ddc
                        if 0 <= rr < WORLD_H and 0 <= cc < WORLD_W and wm[rr, cc]:
                            adj_wire = True
                            break
                    if adj_wire:
                        return (Tool.WIRE, wc, lr)

    # Phase 6: Place zones
    # Left cluster: RES and IND alternating
    for zr in all_zone_rows:
        for zc in [left_cx - 6, left_cx, left_cx + 6]:
            if 1 <= zr < WORLD_H-1 and 1 <= zc < WORLD_W-1:
                all_zone_m = res_m | com_m | ind_m
                if not zone_exists_near(zr, zc, all_zone_m, 2):
                    if zone_clear(zr, zc) and near_road(zr, zc, 4):
                        if ind_count < max(2, res_count // 3):
                            return (Tool.INDUSTRIAL, zc, zr)
                        else:
                            return (Tool.RESIDENTIAL, zc, zr)

    # Right cluster: RES and COM alternating
    for zr in all_zone_rows:
        for zc in [right_cx - 6, right_cx, right_cx + 6]:
            if 1 <= zr < WORLD_H-1 and 1 <= zc < WORLD_W-1:
                all_zone_m = res_m | com_m | ind_m
                if not zone_exists_near(zr, zc, all_zone_m, 2):
                    if zone_clear(zr, zc) and near_road(zr, zc, 4):
                        if com_count < max(2, res_count // 3):
                            return (Tool.COMMERCIAL, zc, zr)
                        else:
                            return (Tool.RESIDENTIAL, zc, zr)

    # Phase 7: Add a second coal plant if population growing but unpowered zones
    if obs.city_pop > 50 and obs.powered_zones < 5:
        # Place second plant near right cluster
        p2x, p2y = right_cx + 10, road_row
        if em[p2y, p2x] and not pm[p2y, p2x]:
            return (Tool.COALPOWER, p2x, p2y)

    # Phase 8: Extend road and zones further
    if obs.city_pop > 100:
        extended_rows = [road_row - 12, road_row + 12]
        for zr in extended_rows:
            for zc in [left_cx, right_cx, (left_cx + right_cx) // 2]:
                if 1 <= zr < WORLD_H-1 and 1 <= zc < WORLD_W-1:
                    all_zone_m = res_m | com_m | ind_m
                    if not zone_exists_near(zr, zc, all_zone_m, 2):
                        if zone_clear(zr, zc) and near_road(zr, zc, 5) and near_wire(zr, zc, 5):
                            return (Tool.RESIDENTIAL, zc, zr)

    # Phase 9: Fill any gaps in road along main spine
    for rc in range(road_col_start, road_col_end + 1):
        if not rm[road_row, rc] and em[road_row, rc]:
            return (Tool.ROAD, rc, road_row)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map every step and reacts to current state.
    Strategy:
    - Place coal power plant at a fixed anchor
    - Build wire spine vertically from plant
    - Build road column parallel to wire spine
    - Place zones on both sides of the corridor
    - Add lateral wires to power zones
    - Dynamically expand based on city_pop
    - Add second power plant when needed
    - Build horizontal roads for connectivity
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    all_zone_mask = resm | comm | indm

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=3):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    # Phase 1: Place coal power plant if missing
    if not np.any(pm):
        # Place plant left of center
        px, py = cx - 10, cy
        return (Tool.COALPOWER, px, py)

    # Find plant centroid
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Layout columns
    wire_col = plant_cx + 3   # wire spine just right of plant
    road_col = wire_col + 2   # road column
    left_zone_col = wire_col - 3   # zones left of wire
    right_zone_col = road_col + 3  # zones right of road

    wire_col = max(3, min(WORLD_W - 4, wire_col))
    road_col = max(3, min(WORLD_W - 4, road_col))
    left_zone_col = max(2, min(WORLD_W - 3, left_zone_col))
    right_zone_col = max(2, min(WORLD_W - 3, right_zone_col))

    # Spine extent based on population
    if obs.city_pop < 100:
        spine_extent = 9
    elif obs.city_pop < 300:
        spine_extent = 15
    elif obs.city_pop < 600:
        spine_extent = 22
    else:
        spine_extent = 30

    target_min = max(1, cy - spine_extent)
    target_max = min(WORLD_H - 2, cy + spine_extent)

    wire_rows_on_spine = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])
    road_rows_on_col = sorted([r for r in range(WORLD_H) if rm[r, road_col]])

    # Phase 2: Bootstrap wire spine adjacent to plant
    if not wire_rows_on_spine:
        for dy in range(0, 6):
            for nr in [plant_cy + dy, plant_cy - dy]:
                if 0 <= nr < WORLD_H:
                    if em[nr, wire_col] or wm[nr, wire_col]:
                        return (Tool.WIRE, wire_col, nr)
        return None

    min_wire_row = min(wire_rows_on_spine)
    max_wire_row = max(wire_rows_on_spine)

    # Phase 3: Extend wire spine downward first, then upward
    # Prefer downward extension for determinism
    if max_wire_row < target_max:
        nr = max_wire_row + 1
        if nr < WORLD_H and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    if min_wire_row > target_min:
        nr = min_wire_row - 1
        if nr >= 0 and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Phase 4: Build road column alongside wire spine
    # Build road wherever wire exists and road is missing
    for r in wire_rows_on_spine:
        if 0 <= r < WORLD_H and 0 <= road_col < WORLD_W:
            if not rm[r, road_col] and em[r, road_col]:
                return (Tool.ROAD, road_col, r)

    # Phase 5: Place zones along the corridor
    zone_rows = list(range(max(1, target_min + 1), min(WORLD_H - 1, target_max), 3))

    for zr in zone_rows:
        wire_near = any(abs(zr - wr) <= 2 for wr in wire_rows_on_spine)
        road_near = any(abs(zr - rr) <= 2 for rr in road_rows_on_col)

        if wire_near and road_near:
            # Left zone (wire side)
            zc = left_zone_col
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc, 5) and has_road_nearby(zr, zc, 5):
                    return (pick_tool(), zc, zr)
                elif has_wire_nearby(zr, zc, 6):
                    return (Tool.RESIDENTIAL, zc, zr)

            # Right zone (road side)
            zc = right_zone_col
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_road_nearby(zr, zc, 5) and has_wire_nearby(zr, zc, 6):
                    return (pick_tool(), zc, zr)

    # Phase 6: Lateral wires from spine to left zones
    for wr in wire_rows_on_spine:
        # Walk leftward from wire_col to left_zone_col - 1
        for wc in range(wire_col - 1, left_zone_col - 2, -1):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc]:
                    break  # already connected
                if pm[wr, wc]:
                    break  # plant blocking
                if em[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                else:
                    break  # blocked by something

    # Phase 7: Road extensions rightward to reach right zone col
    for rr in wire_rows_on_spine:
        if not rm[rr, road_col]:
            continue
        for rc in range(road_col + 1, right_zone_col + 2):
            if 0 <= rc < WORLD_W:
                if rm[rr, rc]:
                    break
                if pm[rr, rc]:
                    break
                if em[rr, rc]:
                    return (Tool.ROAD, rc, rr)
                else:
                    break

    # Phase 8: Wires rightward to power right zones
    for wr in wire_rows_on_spine:
        for wc in range(wire_col + 1, right_zone_col + 2):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc] or pm[wr, wc]:
                    break
                if rm[wr, wc]:
                    # Road exists here - put wire under it? skip and continue
                    continue
                if em[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                else:
                    break

    # Phase 9: Second coal plant when city growing
    plant_count = int(np.sum(pm))
    if obs.city_pop > 350 and plant_count < 9:
        # Place second plant further right
        px2 = plant_cx + 20
        py2 = plant_cy
        if 2 <= px2 <= WORLD_W - 4 and 2 <= py2 <= WORLD_H - 4:
            # Check if area is empty
            if np.all(em[py2-1:py2+2, px2-1:px2+2]):
                return (Tool.COALPOWER, px2, py2)
        # Try above
        py2 = plant_cy - 12
        if 2 <= px2 <= WORLD_W - 4 and 2 <= py2 <= WORLD_H - 4:
            if np.all(em[py2-1:py2+2, px2-1:px2+2]):
                return (Tool.COALPOWER, px2, py2)

    # Phase 10: Expand zone columns outward
    if obs.city_pop > 200:
        extra_zone_cols = [left_zone_col - 4, right_zone_col + 4]
        for zc in extra_zone_cols:
            zc = max(2, min(WORLD_W - 3, zc))
            for zr in zone_rows:
                if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                    if has_road_nearby(zr, zc, 6) and has_wire_nearby(zr, zc, 7):
                        return (Tool.RESIDENTIAL, zc, zr)

    # Phase 11: Horizontal roads connecting corridor to expand access
    if obs.city_pop > 150:
        # Connect top and bottom of wire extent with horizontal road
        h_rows = [min_wire_row + 1, max_wire_row - 1, plant_cy]
        for rr in h_rows:
            if 0 <= rr < WORLD_H:
                for rc in range(max(0, left_zone_col - 2), min(WORLD_W, right_zone_col + 3)):
                    if em[rr, rc] and not pm[rr, rc] and not wm[rr, rc]:
                        return (Tool.ROAD, rc, rr)

    # Phase 12: Wire connection from first to second plant if exists
    if obs.city_pop > 350 and plant_count >= 18:
        # Try to draw wire between plants - check current wire coverage
        # Find any unwired gap in spine
        for r in range(target_min, target_max + 1):
            if not wm[r, wire_col] and not pm[r, wire_col] and em[r, wire_col]:
                return (Tool.WIRE, wire_col, r)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map each step to decide next action
    - Builds a compact cluster around map center
    - Coal plant -> wire spine -> road spine -> zones
    - Extends infrastructure based on what actually exists
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    pop = obs.city_pop

    # Layout constants (relative to center)
    plant_x = cx - 7
    plant_y = cy
    wire_col = cx - 1
    road_col = cx
    left_zcol = wire_col - 3
    right_zcol = road_col + 3

    # Clamp all
    def clamp(v, lo, hi): return max(lo, min(hi, v))
    wire_col   = clamp(wire_col,   2, WORLD_W - 3)
    road_col   = clamp(road_col,   2, WORLD_W - 3)
    left_zcol  = clamp(left_zcol,  2, WORLD_W - 3)
    right_zcol = clamp(right_zcol, 2, WORLD_W - 3)
    plant_x    = clamp(plant_x,    2, WORLD_W - 3)
    plant_y    = clamp(plant_y,    2, WORLD_H - 3)

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def safe(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def is_empty(x, y):
        return safe(x, y) and bool(em[y, x])

    def has_wire(x, y):
        return safe(x, y) and bool(wm[y, x])

    def has_road(x, y):
        return safe(x, y) and bool(rm[y, x])

    def has_plant(x, y):
        return safe(x, y) and bool(pm[y, x])

    # Compute spine length based on pop
    if pop < 50:
        spine_half = 8
    elif pop < 200:
        spine_half = 14
    elif pop < 500:
        spine_half = 20
    else:
        spine_half = 26

    spine_min = max(2, cy - spine_half)
    spine_max = min(WORLD_H - 3, cy + spine_half)
    spine_range = range(spine_min, spine_max + 1)

    # ---- Phase 0: Place first coal plant ----
    if not np.any(pm):
        return (Tool.COALPOWER, plant_x, plant_y)

    # Find actual plant location(s)
    plant_locs = list(zip(*np.where(pm)))  # (y, x) pairs

    # ---- Phase 1: Wire spine - grow FROM wire that's already adjacent to plant ----
    # First ensure wire starts adjacent to plant
    # Find wire column extent
    existing_wire_rows = sorted([r for r in spine_range if has_wire(wire_col, r)])

    if not existing_wire_rows:
        # Start wire adjacent to plant
        # Find plant y coord
        py_actual = plant_locs[0][0] if plant_locs else plant_y
        # Wire from wire_col at plant row
        start_y = clamp(py_actual, spine_min, spine_max)
        if is_empty(wire_col, start_y):
            return (Tool.WIRE, wire_col, start_y)
        # Try connecting wire from plant to wire_col
        for wc in range(plant_x + 4, wire_col + 1):
            if safe(wc, start_y) and not has_plant(wc, start_y):
                if is_empty(wc, start_y):
                    return (Tool.WIRE, wc, start_y)
                elif has_wire(wc, start_y):
                    continue
                else:
                    break

    # Extend wire spine: find gaps in wire_col within spine_range
    # Grow upward from lowest existing wire
    if existing_wire_rows:
        lo = existing_wire_rows[0]
        hi = existing_wire_rows[-1]
        # Extend downward
        if hi < spine_max and is_empty(wire_col, hi + 1):
            return (Tool.WIRE, wire_col, hi + 1)
        # Extend upward
        if lo > spine_min and is_empty(wire_col, lo - 1):
            return (Tool.WIRE, wire_col, lo - 1)

    # Fill any gaps in wire spine
    for dy in spine_range:
        if not has_wire(wire_col, dy) and not has_plant(wire_col, dy) and is_empty(wire_col, dy):
            return (Tool.WIRE, wire_col, dy)

    # ---- Phase 2: Road spine (adjacent to wire) ----
    existing_road_rows = sorted([r for r in spine_range if has_road(road_col, r)])

    if existing_road_rows:
        lo = existing_road_rows[0]
        hi = existing_road_rows[-1]
        if hi < spine_max and is_empty(road_col, hi + 1):
            return (Tool.ROAD, road_col, hi + 1)
        if lo > spine_min and is_empty(road_col, lo - 1):
            return (Tool.ROAD, road_col, lo - 1)

    for dy in spine_range:
        if not has_road(road_col, dy) and not has_plant(road_col, dy) and is_empty(road_col, dy):
            return (Tool.ROAD, road_col, dy)

    # ---- Phase 3: Lateral wires LEFT toward left_zcol ----
    # For each wire row, extend wire leftward until left_zcol+1
    wire_rows = [r for r in spine_range if has_wire(wire_col, r)]

    for wr in wire_rows[::2]:  # every other row to save steps
        # Find current leftmost wire in this row
        lw = wire_col
        while lw > 0 and has_wire(lw - 1, wr):
            lw -= 1
        target = left_zcol + 1
        if lw > target:
            nxt = lw - 1
            if safe(nxt, wr) and is_empty(nxt, wr):
                return (Tool.WIRE, nxt, wr)

    # ---- Phase 4: Lateral wires RIGHT toward right_zcol ----
    for wr in wire_rows[::2]:
        rw = wire_col
        while rw < WORLD_W - 1 and (has_wire(rw + 1, wr) or has_road(rw + 1, wr)):
            rw += 1
        # Actually find rightmost wire
        rw = wire_col
        while rw < WORLD_W - 1 and has_wire(rw + 1, wr):
            rw += 1
        target = right_zcol - 1
        if rw < target:
            nxt = rw + 1
            if safe(nxt, wr) and is_empty(nxt, wr):
                return (Tool.WIRE, nxt, wr)

    # ---- Phase 5: Place zones reactively ----
    all_zone_m = resm | comm | indm

    def zone_area_clear(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not safe(rc, rr):
                    return False
                if not em[rr, rc] and not all_zone_m[rr, rc]:
                    return False
        return True

    def zone_present_near(zr, zc):
        for dr in range(-2, 3):
            for dc in range(-2, 3):
                rr, rc = zr + dr, zc + dc
                if safe(rc, rr) and all_zone_m[rr, rc]:
                    return True
        return False

    def has_power_nearby(zr, zc, radius=3):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return bool(np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1]))

    def has_road_nearby(zr, zc, radius=3):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return bool(np.any(rm[r0:r1, c0:c1]))

    # Zone rows spaced by 4
    zone_rows = list(range(spine_min + 1, spine_max - 1, 4))

    road_rows = [r for r in spine_range if has_road(road_col, r)]

    for zr in zone_rows:
        # Check actual infrastructure exists nearby
        w_near = any(abs(zr - wr) <= 3 for wr in wire_rows)
        r_near = any(abs(zr - rr) <= 3 for rr in road_rows)
        if not (w_near and r_near):
            continue

        # Left zone
        zc = left_zcol
        if (has_power_nearby(zr, zc) and has_road_nearby(zr, zc)
                and not zone_present_near(zr, zc) and zone_area_clear(zr, zc)):
            return (pick_tool(), zc, zr)

        # Right zone
        zc = right_zcol
        if (has_power_nearby(zr, zc) and has_road_nearby(zr, zc)
                and not zone_present_near(zr, zc) and zone_area_clear(zr, zc)):
            return (pick_tool(), zc, zr)

    # ---- Phase 6: Second coal plant when pop grows ----
    n_plants = int(np.sum(pm))
    if pop > 150 and n_plants < 9:
        # Place second plant to right of center
        px2 = clamp(plant_x + 20, 2, WORLD_W - 3)
        py2 = plant_y
        if is_empty(px2, py2):
            # Connect via wire first
            # Find rightmost wire at py2 row
            rw = wire_col
            while rw < WORLD_W - 1 and has_wire(rw + 1, py2):
                rw += 1
            if rw < px2 - 4:
                nxt = rw + 1
                if safe(nxt, py2) and is_empty(nxt, py2):
                    return (Tool.WIRE, nxt, py2)
            return (Tool.COALPOWER, px2, py2)

    # ---- Phase 7: Outer zone tiers if population growing ----
    if pop > 100:
        left2  = clamp(left_zcol - 6, 2, WORLD_W - 3)
        right2 = clamp(right_zcol + 6, 2, WORLD_W - 3)

        for zr in zone_rows:
            for zc in [left2, right2]:
                if (has_power_nearby(zr, zc, 4) and has_road_nearby(zr, zc, 4)
                        and not zone_present_near(zr, zc) and zone_area_clear(zr, zc)):
                    return (pick_tool(), zc, zr)

    # ---- Phase 8: Horizontal connector roads ----
    if pop > 80:
        for rr in [spine_min, (spine_min + spine_max) // 2, spine_max]:
            if 0 <= rr < WORLD_H:
                for rc in range(max(0, left_zcol - 1), min(WORLD_W, right_zcol + 2)):
                    if is_empty(rc, rr) and not has_plant(rc, rr):
                        return (Tool.ROAD, rc, rr)

    # ---- Phase 9: Wire to connect plant to spine if not already done ----
    if plant_locs:
        py_act, px_act = plant_locs[0]
        # Check if any wire connects plant to spine
        row = py_act
        if safe(wire_col, row) and not has_wire(wire_col, row):
            pass  # spine handles it
        else:
            # Horizontal wire from plant to spine
            for wc in range(px_act + 4, wire_col):
                if safe(wc, row):
                    if is_empty(wc, row):
                        return (Tool.WIRE, wc, row)
                    elif has_wire(wc, row) or has_plant(wc, row):
                        break

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Read map each step, adapt to what exists
    - Place coal plant first, then wire spine outward from plant
    - Build roads parallel to wire spine
    - Place zones adjacent to roads with wire nearby
    - Expand as population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    # Anchor: plant center (slightly left of map center)
    plant_cx, plant_cy = 55, 50

    has_plant = np.any(pm)

    # Phase 1: place coal power plant
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Get current positions
    plant_positions = list(zip(*np.where(pm))) if has_plant else []
    wire_positions = set(zip(*np.where(wm))) if np.any(wm) else set()
    road_positions = set(zip(*np.where(rm))) if np.any(rm) else set()
    res_pos = set(zip(*np.where(res_mask(tm))))
    com_pos = set(zip(*np.where(com_mask(tm))))
    ind_pos = set(zip(*np.where(ind_mask(tm))))
    all_zones = res_pos | com_pos | ind_pos

    res_count = len(res_pos)
    com_count = len(com_pos)
    ind_count = len(ind_pos)
    total_zones = res_count + com_count + ind_count

    # Find actual plant center from map
    if plant_positions:
        # Use centroid of plant tiles
        prows = [r for (r, c) in plant_positions]
        pcols = [c for (r, c) in plant_positions]
        plant_cy = int(np.median(prows))
        plant_cx = int(np.median(pcols))

    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def already_zone_nearby(zr, zc, dist=3):
        return any(abs(zr - pr) <= dist and abs(zc - pc) <= dist for (pr, pc) in all_zones)

    def pick_zone_type():
        # Aim: ~50% res, ~25% com, ~25% ind
        if total_zones == 0:
            return Tool.INDUSTRIAL
        if ind_count * 4 < total_zones:
            return Tool.INDUSTRIAL
        if com_count * 4 < total_zones:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Wire spine: horizontal row through plant, extending left and right
    wire_row = plant_cy
    wire_cols_in_row = sorted(c for (r, c) in wire_positions if r == wire_row)

    # Compute target wire extent based on pop
    base_half = 15
    extra_half = min(25, obs.city_pop // 20)
    target_half = base_half + extra_half
    wire_left = max(2, plant_cx - target_half)
    wire_right = min(WORLD_W - 3, plant_cx + target_half)

    # Phase 2: build horizontal wire spine from plant
    if not wire_cols_in_row:
        # Start wire adjacent to plant (to the right)
        start_c = plant_cx + 2
        if 0 <= start_c < WORLD_W and (em[wire_row, start_c] or wm[wire_row, start_c]):
            return (Tool.WIRE, start_c, wire_row)
        # Try left
        start_c = plant_cx - 2
        if 0 <= start_c < WORLD_W and (em[wire_row, start_c] or wm[wire_row, start_c]):
            return (Tool.WIRE, start_c, wire_row)
    else:
        max_wc = max(wire_cols_in_row)
        min_wc = min(wire_cols_in_row)
        # Extend rightward
        if max_wc < wire_right:
            nc = max_wc + 1
            if 0 <= nc < WORLD_W and (em[wire_row, nc] or wm[wire_row, nc]):
                return (Tool.WIRE, nc, wire_row)
        # Extend leftward
        if min_wc > wire_left:
            nc = min_wc - 1
            if 0 <= nc < WORLD_W and (em[wire_row, nc] or wm[wire_row, nc]):
                return (Tool.WIRE, nc, wire_row)

    if not wire_cols_in_row:
        return None

    wire_cols_set = set(wire_cols_in_row)

    # Road rows: above and below wire spine
    road_row_above = wire_row - 3
    road_row_below = wire_row + 3

    road_start = min(wire_cols_in_row) if wire_cols_in_row else plant_cx - 5
    road_end = max(wire_cols_in_row) if wire_cols_in_row else plant_cx + 5

    # Phase 3: build road above wire spine
    if 0 <= road_row_above < WORLD_H:
        road_above_cols = set(c for (r, c) in road_positions if r == road_row_above)
        for wc in wire_cols_in_row:
            if wc not in road_above_cols and em[road_row_above, wc]:
                return (Tool.ROAD, wc, road_row_above)

    # Phase 4: build road below wire spine
    if 0 <= road_row_below < WORLD_H:
        road_below_cols = set(c for (r, c) in road_positions if r == road_row_below)
        for wc in wire_cols_in_row:
            if wc not in road_below_cols and em[road_row_below, wc]:
                return (Tool.ROAD, wc, road_row_below)

    # Phase 5: vertical wires connecting spine to zone areas (every 4 cols)
    zone_row_above = road_row_above - 3  # zone centers above upper road
    zone_row_below = road_row_below + 3  # zone centers below lower road

    road_above_cols = set(c for (r, c) in road_positions if r == road_row_above)
    road_below_cols = set(c for (r, c) in road_positions if r == road_row_below)

    # Build vertical wires from spine up/down to reach zone rows (every 4th wire col)
    for wc in wire_cols_in_row:
        if wc % 4 == 0:
            # Wire upward from wire_row to zone_row_above
            if 0 <= zone_row_above < WORLD_H:
                for r in range(wire_row - 1, zone_row_above - 1, -1):
                    if (r, wc) not in wire_positions and em[r, wc]:
                        return (Tool.WIRE, wc, r)
            # Wire downward from wire_row to zone_row_below
            if 0 <= zone_row_below < WORLD_H:
                for r in range(wire_row + 1, zone_row_below + 1):
                    if (r, wc) not in wire_positions and em[r, wc]:
                        return (Tool.WIRE, wc, r)

    # Helper: check wire reachable near a point
    def has_wire_nearby(zr, zc, dist=4):
        for (wr, wc) in wire_positions:
            if abs(wr - zr) <= dist and abs(wc - zc) <= dist:
                return True
        return False

    def has_road_nearby(zr, zc, dist=3):
        for (rr, rc) in road_positions:
            if abs(rr - zr) <= dist and abs(rc - zc) <= dist:
                return True
        return False

    # Phase 6: place zones above upper road (zone centers at zone_row_above)
    if 2 <= zone_row_above <= WORLD_H - 3:
        for zc in wire_cols_in_row:
            if not (2 <= zc <= WORLD_W - 3):
                continue
            if not has_road_nearby(zone_row_above, zc):
                continue
            if not has_wire_nearby(zone_row_above, zc):
                continue
            if not already_zone_nearby(zone_row_above, zc) and zone_area_free(zone_row_above, zc):
                return (pick_zone_type(), zc, zone_row_above)

    # Phase 7: place zones below lower road (zone centers at zone_row_below)
    if 2 <= zone_row_below <= WORLD_H - 3:
        for zc in wire_cols_in_row:
            if not (2 <= zc <= WORLD_W - 3):
                continue
            if not has_road_nearby(zone_row_below, zc):
                continue
            if not has_wire_nearby(zone_row_below, zc):
                continue
            if not already_zone_nearby(zone_row_below, zc) and zone_area_free(zone_row_below, zc):
                return (pick_zone_type(), zc, zone_row_below)

    # Phase 8: expand to second tier if pop growing
    if obs.city_pop > 150:
        zone_row_above2 = zone_row_above - 6
        zone_row_below2 = zone_row_below + 6
        road_row_above2 = zone_row_above2 + 3
        road_row_below2 = zone_row_below2 - 3

        # Build roads for second tier
        if 0 <= road_row_above2 < WORLD_H:
            road_above2_cols = set(c for (r, c) in road_positions if r == road_row_above2)
            for wc in wire_cols_in_row:
                if wc not in road_above2_cols and em[road_row_above2, wc]:
                    return (Tool.ROAD, wc, road_row_above2)

        if 0 <= road_row_below2 < WORLD_H:
            road_below2_cols = set(c for (r, c) in road_positions if r == road_row_below2)
            for wc in wire_cols_in_row:
                if wc not in road_below2_cols and em[road_row_below2, wc]:
                    return (Tool.ROAD, wc, road_row_below2)

        # Extend vertical wires further
        for wc in wire_cols_in_row:
            if wc % 4 == 0:
                if 0 <= zone_row_above2 < WORLD_H:
                    for r in range(zone_row_above - 1, zone_row_above2 - 1, -1):
                        if (r, wc) not in wire_positions and em[r, wc]:
                            return (Tool.WIRE, wc, r)
                if 0 <= zone_row_below2 < WORLD_H:
                    for r in range(zone_row_below + 1, zone_row_below2 + 1):
                        if (r, wc) not in wire_positions and em[r, wc]:
                            return (Tool.WIRE, wc, r)

        # Place second tier zones
        for (zrow, rrow) in [(zone_row_above2, road_row_above2), (zone_row_below2, road_row_below2)]:
            if not (2 <= zrow <= WORLD_H - 3):
                continue
            rrow_cols = set(c for (r, c) in road_positions if r == rrow)
            for zc in wire_cols_in_row:
                if not (2 <= zc <= WORLD_W - 3):
                    continue
                if not has_road_nearby(zrow, zc):
                    continue
                if not has_wire_nearby(zrow, zc):
                    continue
                if not already_zone_nearby(zrow, zc) and zone_area_free(zrow, zc):
                    return (pick_zone_type(), zc, zrow)

    # Phase 9: add second power plant if many zones but low powered
    if obs.city_pop > 300 and obs.powered_zones < total_zones // 2:
        p2x = plant_cx + 30
        if 2 <= p2x <= WORLD_W - 3 and zone_area_free(plant_cy, p2x):
            return (Tool.COALPOWER, p2x, plant_cy)

    # Phase 10: add services for happiness
    if obs.city_pop > 500 and obs.step % 100 == 50:
        for zr in [wire_row - 10, wire_row + 10]:
            for zc in [plant_cx - 10, plant_cx + 10]:
                if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W and em[zr, zc]:
                    return (Tool.POLICESTATION, zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop city builder: reads tile_map each step and reacts.
    Combines best of Parent A (road grid, zone placement logic) and
    Parent B (vertical wire spine, lateral connections, zone rows).

    Strategy:
    1. Place coal power plant if none exists
    2. Build vertical wire spine adjacent to plant
    3. Build road column next to wire spine
    4. Place zones (R/C/I) flanking road with wire access
    5. Extend laterally with wires/roads as city grows
    6. Add second plant + services at higher pop
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    # Anchor point
    BASE_X, BASE_Y = 55, 50  # center of map roughly

    # Key columns
    WIRE_COL = BASE_X - 3   # vertical wire spine
    ROAD_COL = BASE_X       # road spine (3 cols right of wire)
    LEFT_ZONE_COL = WIRE_COL - 4   # zones left of wire
    RIGHT_ZONE_COL = ROAD_COL + 4  # zones right of road

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Count zones
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(total_zones, 1)
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # --- Phase 1: Place power plant ---
    has_plant = np.any(pm)
    if not has_plant:
        return (Tool.COALPOWER, BASE_X - 6, BASE_Y)

    # Get plant centroid
    plant_ys, plant_xs = np.where(pm)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    # Precompute sets for fast lookup
    wire_positions = list(zip(*np.where(wm))) if np.any(wm) else []
    road_positions = list(zip(*np.where(rm))) if np.any(rm) else []
    wire_set = set(wire_positions)
    road_set = set(road_positions)

    wire_col_rows = sorted([r for (r, c) in wire_positions if c == WIRE_COL])
    road_col_rows = sorted([r for (r, c) in road_positions if c == ROAD_COL])

    # --- Phase 2: Start wire adjacent to plant if none on spine ---
    if not wire_col_rows:
        # Place first wire adjacent to plant
        for dy in range(0, 6):
            for nr in [py + dy, py - dy]:
                if in_bounds(WIRE_COL, nr) and em[nr, WIRE_COL]:
                    return (Tool.WIRE, WIRE_COL, nr)
        return None

    # --- Phase 3: Extend wire spine vertically ---
    target_min = max(2, py - 20)
    target_max = min(WORLD_H - 3, py + 20)

    min_wire_row = min(wire_col_rows)
    max_wire_row = max(wire_col_rows)

    if max_wire_row < target_max:
        nr = max_wire_row + 1
        if in_bounds(WIRE_COL, nr) and (em[nr, WIRE_COL] or wm[nr, WIRE_COL]):
            return (Tool.WIRE, WIRE_COL, nr)

    if min_wire_row > target_min:
        nr = min_wire_row - 1
        if in_bounds(WIRE_COL, nr) and (em[nr, WIRE_COL] or wm[nr, WIRE_COL]):
            return (Tool.WIRE, WIRE_COL, nr)

    # --- Phase 4: Build road spine adjacent to wire ---
    for r in wire_col_rows:
        if in_bounds(ROAD_COL, r) and not rm[r, ROAD_COL] and em[r, ROAD_COL]:
            return (Tool.ROAD, ROAD_COL, r)

    # --- Phase 5: Place zones where wire AND road coverage exists ---
    def zone_area_free(zy, zx):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zy + dr, zx + dc
                if not in_bounds(rc, rr):
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def has_wire_near(zy, zx, radius=5):
        for dr in range(-radius, radius + 1):
            for dc in range(-radius, radius + 1):
                nr, nc = zy + dr, zx + dc
                if in_bounds(nc, nr) and (wm[nr, nc] or pm[nr, nc]):
                    return True
        return False

    def has_road_near(zy, zx, radius=4):
        for dr in range(-radius, radius + 1):
            for dc in range(-radius, radius + 1):
                nr, nc = zy + dr, zx + dc
                if in_bounds(nc, nr) and rm[nr, nc]:
                    return True
        return False

    # Zone rows: every 3 rows through the wire spine extent
    zone_rows = list(range(max(2, min_wire_row + 1), min(WORLD_H - 2, max_wire_row), 3))

    for zr in zone_rows:
        wire_near = any(abs(zr - wr) <= 2 for wr in wire_col_rows)
        road_near = any(abs(zr - rr) <= 2 for (rr, rc) in road_positions if rc == ROAD_COL)

        if wire_near and road_near:
            # Try left zone column
            zc = LEFT_ZONE_COL
            if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                if zone_area_free(zr, zc):
                    if ind_count < max(1, res_count) // 3 and zr > py:
                        return (Tool.INDUSTRIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

            # Try right zone column
            zc = RIGHT_ZONE_COL
            if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                if zone_area_free(zr, zc):
                    if com_count < max(1, res_count) // 3:
                        return (Tool.COMMERCIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

    # --- Phase 6: Lateral wires to left zones ---
    for wr in wire_col_rows:
        # Extend wires leftward to reach LEFT_ZONE_COL
        for wc in range(WIRE_COL - 1, LEFT_ZONE_COL - 2, -1):
            if in_bounds(wc, wr) and em[wr, wc] and not wm[wr, wc] and not pm[wr, wc]:
                return (Tool.WIRE, wc, wr)

    # --- Phase 7: Lateral roads to right zones ---
    for wr in wire_col_rows:
        for rc in range(ROAD_COL + 1, RIGHT_ZONE_COL + 2):
            if in_bounds(rc, wr) and em[wr, rc] and not rm[wr, rc]:
                return (Tool.ROAD, rc, wr)

    # --- Phase 8: Expand coverage with extra zone columns ---
    if obs.city_pop > 100 or total_zones > 5:
        extra_left = LEFT_ZONE_COL - 5
        extra_right = RIGHT_ZONE_COL + 5
        for zr in zone_rows:
            for zc in [extra_left, extra_right]:
                if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                    if zone_area_free(zr, zc):
                        if has_road_near(zr, zc) and has_wire_near(zr, zc):
                            return (pick_tool(), zc, zr)

    # --- Phase 9: Wire horizontal extensions for wider coverage ---
    if obs.city_pop > 50:
        # Horizontal wires at top and bottom of spine
        for wc in range(WIRE_COL, min(ROAD_COL + 6, WORLD_W - 1)):
            if not in_bounds(wc, min_wire_row): continue
            if em[min_wire_row, wc] and not wm[min_wire_row, wc]:
                return (Tool.WIRE, wc, min_wire_row)
        for wc in range(WIRE_COL, min(ROAD_COL + 6, WORLD_W - 1)):
            if not in_bounds(wc, max_wire_row): continue
            if em[max_wire_row, wc] and not wm[max_wire_row, wc]:
                return (Tool.WIRE, wc, max_wire_row)

    # --- Phase 10: Second power plant if population growing ---
    if obs.city_pop > 300 and np.sum(pm) < 10:
        nx2, ny2 = px + 20, py
        if in_bounds(nx2, ny2) and em[ny2, nx2]:
            return (Tool.COALPOWER, nx2, ny2)
        # Try another location
        for dy in range(-5, 6):
            for dx in range(15, 25):
                nx2, ny2 = px + dx, py + dy
                if in_bounds(nx2, ny2) and em[ny2, nx2]:
                    return (Tool.COALPOWER, nx2, ny2)

    # --- Phase 11: Services ---
    if obs.city_pop > 150:
        fx, fy = WIRE_COL - 2, py - 12
        if in_bounds(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
        fx2, fy2 = WIRE_COL - 2, py + 12
        if in_bounds(fx2, fy2) and em[fy2, fx2]:
            return (Tool.POLICESTATION, fx2, fy2)

    # --- Phase 12: Reactive fill - find empty spots near roads and wire ---
    # Use dilated masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand = em & nbr_road & nbr_wire
    # Avoid edges
    cand[:2, :] = False; cand[-2:, :] = False
    cand[:, :2] = False; cand[:, -2:] = False
    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        # Deterministic pick based on step + map hash
        k = int((obs.step * 13 + int(tm[50, 55]))) % len(cxs)
        zx, zy = int(cxs[k]), int(cys[k])
        if zone_area_free(zy, zx):
            return (pick_tool(), zx, zy)

    # --- Last resort: extend road from existing frontier ---
    road_arr_list = [(r, c) for (r, c) in road_positions]
    if road_arr_list:
        k = int(obs.step * 7) % len(road_arr_list)
        rr, rc = road_arr_list[k]
        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rc + dx, rr + dy
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Revised strategy: horizontal road spine with vertical wire connections.
    - Place coal power plant at top-left area
    - Wire spine runs HORIZONTALLY across the map
    - Roads run VERTICALLY (N-S) from horizontal road spine
    - Zones placed in a grid pattern served by roads
