    all_zone_mask = resm | comm | indm

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        # 50% res, 30% com, 20% ind
        if com_count / t < 0.30:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Layout: two neighborhoods, side by side horizontally
    # Neighborhood 1: centered at (30, 35) - left side
    # Neighborhood 2: centered at (80, 35) - right side
    # Each neighborhood: power plant + horizontal wire spine + vertical roads + zones

    # Use state to track build phase
    if 'phase' not in state:
        state['phase'] = 0
        state['n1_done'] = False
        state['n2_done'] = False

    # Neighborhood 1 layout
    n1_cx, n1_cy = 30, 35  # center of neighborhood 1
    n1_plant_x, n1_plant_y = 18, 35  # power plant position
    n1_wire_row = n1_cy  # horizontal wire spine row
    n1_road_col_left = 25
    n1_road_col_right = 35
    n1_wire_start = n1_plant_x + 3  # start wire just right of plant
    n1_wire_end = 42

    # Neighborhood 2 layout
    n2_cx, n2_cy = 80, 35
    n2_plant_x, n2_plant_y = 65, 35
    n2_wire_row = n2_cy
    n2_road_col_left = 72
    n2_road_col_right = 85
    n2_wire_start = n2_plant_x + 3
    n2_wire_end = 92

    # Zone rows (above and below wire spine)
    zone_rows_above = [n1_cy - 4, n1_cy - 8, n1_cy - 12, n1_cy - 16]
    zone_rows_below = [n1_cy + 4, n1_cy + 8, n1_cy + 12, n1_cy + 16]
    zone_rows = zone_rows_above + zone_rows_below

    # Road rows (connect vertical roads to zones)
    road_rows_n1 = []
    for zr in zone_rows:
        if 0 < zr < WORLD_H:
            road_rows_n1.append(zr)

    # Step 1: Place power plant 1
    if not np.any(pm[n1_plant_y - 1:n1_plant_y + 2, n1_plant_x - 1:n1_plant_x + 2]):
        return (Tool.COALPOWER, n1_plant_x, n1_plant_y)

    # Step 2: Build horizontal wire spine for neighborhood 1
    for wc in range(n1_wire_start, n1_wire_end + 1):
        if 0 <= wc < WORLD_W:
            if not wm[n1_wire_row, wc] and not pm[n1_wire_row, wc]:
                if em[n1_wire_row, wc] or wm[n1_wire_row, wc]:
                    return (Tool.WIRE, wc, n1_wire_row)

    # Step 3: Build vertical roads for neighborhood 1
    # Left road column
    for rr in range(n1_cy - 17, n1_cy + 18):
        if 0 <= rr < WORLD_H and 0 <= n1_road_col_left < WORLD_W:
            if not rm[rr, n1_road_col_left] and em[rr, n1_road_col_left] and not pm[rr, n1_road_col_left]:
                return (Tool.ROAD, n1_road_col_left, rr)

    # Right road column
    for rr in range(n1_cy - 17, n1_cy + 18):
        if 0 <= rr < WORLD_H and 0 <= n1_road_col_right < WORLD_W:
            if not rm[rr, n1_road_col_right] and em[rr, n1_road_col_right] and not pm[rr, n1_road_col_right]:
                return (Tool.ROAD, n1_road_col_right, rr)

    # Step 4: Horizontal roads connecting left and right roads at zone rows
    for zr in zone_rows:
        if 0 <= zr < WORLD_H:
            for rc in range(n1_road_col_left, n1_road_col_right + 1):
                if 0 <= rc < WORLD_W:
                    if not rm[zr, rc] and em[zr, rc] and not pm[zr, rc] and not wm[zr, rc]:
                        return (Tool.ROAD, rc, zr)

    # Step 5: Vertical wires from wire spine to zone rows (every 4 rows)
    for zr in zone_rows:
        # Wire from wire spine up to zone row or down
        if zr < n1_wire_row:
            for wr in range(zr, n1_wire_row):
                if 0 <= wr < WORLD_H:
                    # wire at left road col and right road col
                    for wc in [n1_road_col_left + 1, n1_road_col_right - 1]:
                        if 0 <= wc < WORLD_W:
                            if not wm[wr, wc] and not pm[wr, wc] and em[wr, wc] and not rm[wr, wc]:
                                return (Tool.WIRE, wc, wr)
        elif zr > n1_wire_row:
            for wr in range(n1_wire_row + 1, zr + 1):
                if 0 <= wr < WORLD_H:
                    for wc in [n1_road_col_left + 1, n1_road_col_right - 1]:
                        if 0 <= wc < WORLD_W:
                            if not wm[wr, wc] and not pm[wr, wc] and em[wr, wc] and not rm[wr, wc]:
                                return (Tool.WIRE, wc, wr)

    # Step 6: Place zones in neighborhood 1
    # Zone columns: left of left road, between roads (multiple), right of right road
    n1_zone_cols = [n1_road_col_left - 3, n1_road_col_left + 3, n1_road_col_right - 3, n1_road_col_right + 3]
    for zr in zone_rows:
        for zc in n1_zone_cols:
            if 2 <= zc <= WORLD_W - 3 and 2 <= zr <= WORLD_H - 3:
                if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                    # Check road access nearby
                    r0, r1 = max(0, zr - 3), min(WORLD_H, zr + 4)
                    c0, c1 = max(0, zc - 3), min(WORLD_W, zc + 4)
                    has_road = np.any(rm[r0:r1, c0:c1])
                    has_wire = np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])
                    if has_road and has_wire:
                        return (pick_tool(), zc, zr)

    # Step 7: Place power plant 2 (neighborhood 2)
    if not np.any(pm[n2_plant_y - 1:n2_plant_y + 2, n2_plant_x - 1:n2_plant_x + 2]):
        return (Tool.COALPOWER, n2_plant_x, n2_plant_y)

    # Step 8: Build horizontal wire spine for neighborhood 2
    for wc in range(n2_wire_start, n2_wire_end + 1):
        if 0 <= wc < WORLD_W:
            if not wm[n2_wire_row, wc] and not pm[n2_wire_row, wc]:
                if em[n2_wire_row, wc] or wm[n2_wire_row, wc]:
                    return (Tool.WIRE, wc, n2_wire_row)

    # Step 9: Build vertical roads for neighborhood 2
    for rr in range(n2_cy - 17, n2_cy + 18):
        if 0 <= rr < WORLD_H and 0 <= n2_road_col_left < WORLD_W:
            if not rm[rr, n2_road_col_left] and em[rr, n2_road_col_left] and not pm[rr, n2_road_col_left]:
                return (Tool.ROAD, n2_road_col_left, rr)

    for rr in range(n2_cy - 17, n2_cy + 18):
        if 0 <= rr < WORLD_H and 0 <= n2_road_col_right < WORLD_W:
            if not rm[rr, n2_road_col_right] and em[rr, n2_road_col_right] and not pm[rr, n2_road_col_right]:
                return (Tool.ROAD, n2_road_col_right, rr)

    # Step 10: Horizontal roads for neighborhood 2
    zone_rows_n2 = [n2_cy - 4, n2_cy - 8, n2_cy - 12, n2_cy - 16,
