    for zr in zone_rows_n2:
        if 0 <= zr < WORLD_H:
            for rc in range(n2_road_col_left, n2_road_col_right + 1):
                if 0 <= rc < WORLD_W:
                    if not rm[zr, rc] and em[zr, rc] and not pm[zr, rc] and not wm[zr, rc]:
                        return (Tool.ROAD, rc, zr)

    # Step 11: Vertical wires for neighborhood 2
    for zr in zone_rows_n2:
        if zr < n2_wire_row:
            for wr in range(zr, n2_wire_row):
                if 0 <= wr < WORLD_H:
                    for wc in [n2_road_col_left + 1, n2_road_col_right - 1]:
                        if 0 <= wc < WORLD_W:
                            if not wm[wr, wc] and not pm[wr, wc] and em[wr, wc] and not rm[wr, wc]:
                                return (Tool.WIRE, wc, wr)
        elif zr > n2_wire_row:
            for wr in range(n2_wire_row + 1, zr + 1):
                if 0 <= wr < WORLD_H:
                    for wc in [n2_road_col_left + 1, n2_road_col_right - 1]:
                        if 0 <= wc < WORLD_W:
                            if not wm[wr, wc] and not pm[wr, wc] and em[wr, wc] and not rm[wr, wc]:
                                return (Tool.WIRE, wc, wr)

    # Step 12: Place zones in neighborhood 2
    n2_zone_cols = [n2_road_col_left - 3, n2_road_col_left + 3, n2_road_col_right - 3, n2_road_col_right + 3]
    for zr in zone_rows_n2:
        for zc in n2_zone_cols:
            if 2 <= zc <= WORLD_W - 3 and 2 <= zr <= WORLD_H - 3:
                if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                    r0, r1 = max(0, zr - 3), min(WORLD_H, zr + 4)
                    c0, c1 = max(0, zc - 3), min(WORLD_W, zc + 4)
                    has_road = np.any(rm[r0:r1, c0:c1])
                    has_wire = np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])
                    if has_road and has_wire:
                        return (pick_tool(), zc, zr)

    # Step 13: Add more zones between road columns for both neighborhoods
    inner_zone_cols_n1 = [n1_road_col_left - 6, n1_road_col_right + 6]
    for zr in zone_rows:
        for zc in inner_zone_cols_n1:
            if 2 <= zc <= WORLD_W - 3 and 2 <= zr <= WORLD_H - 3:
                if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                    r0, r1 = max(0, zr - 4), min(WORLD_H, zr + 5)
                    c0, c1 = max(0, zc - 4), min(WORLD_W, zc + 5)
                    has_road = np.any(rm[r0:r1, c0:c1])
                    has_wire = np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])
                    if has_road and has_wire:
                        return (pick_tool(), zc, zr)

    return None

def act(obs, state):
    """
    Variation: horizontal corridor layout instead of vertical spine.
    - Power plant on left side
    - Wire runs horizontally (east)
    - Road runs horizontally parallel (1 row below wire)
    - Zones placed above and below the corridor
    - Better zone mix: balanced RES/COM/IND
    - Two neighborhoods: one centered, one offset
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    all_zone_mask = resm | comm | indm

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        # Target: 40% RES, 35% COM, 25% IND
        if com_count / t < 0.30:
            return Tool.COMMERCIAL
        if ind_count / t < 0.22:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=3):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    # Anchor: horizontal corridor in upper-middle area
    # Plant at left, wire runs east along wire_row, road one row below
    anchor_x = 15
    wire_row = 35
    road_row = wire_row + 2   # road 2 rows below wire

    top_zone_row = wire_row - 3   # zones above wire
    bot_zone_row = road_row + 3   # zones below road

    # Phase 1: Place coal power plant if missing
    if not np.any(pm):
        return (Tool.COALPOWER, anchor_x, wire_row)

    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Corridor extent based on population
    if obs.city_pop < 100:
        corridor_end = anchor_x + 20
    elif obs.city_pop < 300:
        corridor_end = anchor_x + 35
    elif obs.city_pop < 600:
        corridor_end = anchor_x + 55
    else:
        corridor_end = anchor_x + 75
    corridor_end = min(corridor_end, WORLD_W - 4)

    wire_cols_on_row = sorted([c for c in range(WORLD_W) if wm[wire_row, c]])
    road_cols_on_row = sorted([c for c in range(WORLD_W) if rm[road_row, c]])

    # Phase 2: Bootstrap wire row adjacent to plant
    if not wire_cols_on_row:
        start_c = plant_cx + 2
        if 0 <= start_c < WORLD_W and (em[wire_row, start_c] or wm[wire_row, start_c]):
            return (Tool.WIRE, start_c, wire_row)
        return None

    max_wire_col = max(wire_cols_on_row)
    min_wire_col = min(wire_cols_on_row)

    # Phase 3: Extend wire eastward
    if max_wire_col < corridor_end:
        nc = max_wire_col + 1
        if nc < WORLD_W and not pm[wire_row, nc]:
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # Phase 4: Build road row parallel to wire
    for c in wire_cols_on_row:
        if 0 <= road_row < WORLD_H and 0 <= c < WORLD_W:
            if not rm[road_row, c] and em[road_row, c] and not pm[road_row, c]:
                return (Tool.ROAD, c, road_row)

    # Phase 5: Place zones above and below corridor
    zone_cols = list(range(max(2, min_wire_col + 2), min(WORLD_W - 2, max_wire_col - 1), 4))

    for zc in zone_cols:
        wire_near = any(abs(zc - wc) <= 2 for wc in wire_cols_on_row)
        road_near = any(abs(zc - rc) <= 2 for rc in road_cols_on_row)

        if wire_near:
            # Top zone (above wire)
            zr = top_zone_row
            if (not zone_already_there(zr, zc) and zone_area_ok(zr, zc)
                    and has_wire_nearby(zr, zc, 5)):
                if has_road_nearby(zr, zc, 5):
                    return (pick_tool(), zc, zr)
                else:
                    return (Tool.RESIDENTIAL, zc, zr)

        if wire_near and road_near:
            # Bottom zone (below road)
            zr = bot_zone_row
            if (not zone_already_there(zr, zc) and zone_area_ok(zr, zc)
                    and has_wire_nearby(zr, zc, 6) and has_road_nearby(zr, zc, 5)):
                return (pick_tool(), zc, zr)

    # Phase 6: Vertical wires from wire row up to top zones
    for wc in wire_cols_on_row:
        for wr in range(wire_row - 1, top_zone_row - 2, -1):
            if wr < 0:
                break
            if wm[wr, wc] or pm[wr, wc]:
                break
            if em[wr, wc]:
                return (Tool.WIRE, wc, wr)
            else:
                break

    # Phase 7: Vertical roads from road row down to bottom zones
    for rc in road_cols_on_row:
        for rr in range(road_row + 1, bot_zone_row + 2):
            if rr >= WORLD_H:
                break
            if rm[rr, rc] or pm[rr, rc]:
                break
            if em[rr, rc]:
                return (Tool.ROAD, rc, rr)
            else:
                break

    # Phase 8: Second horizontal corridor lower on map for second neighborhood
    if obs.city_pop > 250:
        wire_row2 = wire_row + 20
        road_row2 = wire_row2 + 2
        top_zone_row2 = wire_row2 - 3
        bot_zone_row2 = road_row2 + 3

        wire_cols2 = sorted([c for c in range(WORLD_W) if wm[wire_row2, c]])
        road_cols2 = sorted([c for c in range(WORLD_W) if rm[road_row2, c]])

        # Connect second corridor to plant via vertical wire
        if not wire_cols2:
            # Place wire to start second corridor near same x as plant
            start2_c = plant_cx + 2
            if (0 <= wire_row2 < WORLD_H and 0 <= start2_c < WORLD_W
                    and em[wire_row2, start2_c]):
                return (Tool.WIRE, start2_c, wire_row2)

        if wire_cols2:
            max_wire2 = max(wire_cols2)
            corridor_end2 = min(corridor_end, WORLD_W - 4)
            if max_wire2 < corridor_end2:
                nc = max_wire2 + 1
                if nc < WORLD_W and not pm[wire_row2, nc] and em[wire_row2, nc]:
                    return (Tool.WIRE, nc, wire_row2)

            # Build road2
            for c in wire_cols2:
                if (0 <= road_row2 < WORLD_H and em[road_row2, c]
                        and not rm[road_row2, c] and not pm[road_row2, c]):
                    return (Tool.ROAD, c, road_row2)

            # Zones for second corridor
            zone_cols2 = list(range(max(2, min(wire_cols2) + 2),
                                    min(WORLD_W - 2, max_wire2 - 1), 4))
            for zc in zone_cols2:
                wire_near2 = any(abs(zc - wc) <= 2 for wc in wire_cols2)
                road_near2 = any(abs(zc - rc) <= 2 for rc in road_cols2)
                if wire_near2:
                    zr = top_zone_row2
                    if (not zone_already_there(zr, zc) and zone_area_ok(zr, zc)
                            and has_wire_nearby(zr, zc, 5)):
                        return (pick_tool(), zc, zr)
                if wire_near2 and road_near2:
                    zr = bot_zone_row2
                    if (not zone_already_there(zr, zc) and zone_area_ok(zr, zc)
                            and has_wire_nearby(zr, zc, 6) and has_road_nearby(zr, zc, 5)):
                        return (pick_tool(), zc, zr)

        # Vertical wire bridge between corridor 1 and corridor 2
        bridge_col = plant_cx + 2
        for br in range(wire_row + 1, wire_row2):
            if not wm[br, bridge_col] and not pm[br, bridge_col] and em[br, bridge_col]:
                return (Tool.WIRE, bridge_col, br)

    # Phase 9: Second power plant when needed
    plant_count = int(np.sum(pm))
    if obs.city_pop > 400 and plant_count < 9:
        px2 = plant_cx + 30
        py2 = plant_cy
        if 2 <= px2 <= WORLD_W - 4 and 2 <= py2 <= WORLD_H - 4:
            if np.all(em[py2-1:py2+2, px2-1:px2+2]):
                return (Tool.COALPOWER, px2, py2)

    # Phase 10: Fill gaps in wire spine
    for r in range(min(10, wire_row - 1), wire_row):
        if not wm[r, plant_cx + 2] and not pm[r, plant_cx + 2] and em[r, plant_cx + 2]:
            return (Tool.WIRE, plant_cx + 2, r)

    return None

def act(obs, state):
    """
    Improved policy: horizontal road spine, zones on both sides, better power distribution.
    Strategy:
    - Place coal power plant near center
    - Build horizontal road spine across map center
    - Wire runs parallel to road spine (above it)
    - Place zones in columns above and below the road
    - Mix residential, commercial, industrial
    - Add second plant and expand when population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Phase 1: Place coal power plant if missing
    if not np.any(pm):
        return (Tool.COALPOWER, cx - 20, cy)

    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Horizontal layout: wire row above road row
    wire_row = cy - 1   # wire spine horizontal row
    road_row = cy + 1   # road spine horizontal row

    # Zones above wire spine and below road spine
    upper_zone_row = wire_row - 3  # zone centers above wire
    lower_zone_row = road_row + 3  # zone centers below road

    # Second tier zones
    upper_zone_row2 = wire_row - 7
    lower_zone_row2 = road_row + 7

    # Clamp rows
    wire_row = max(2, min(WORLD_H - 3, wire_row))
    road_row = max(2, min(WORLD_H - 3, road_row))
    upper_zone_row = max(1, min(WORLD_H - 2, upper_zone_row))
    lower_zone_row = max(1, min(WORLD_H - 2, lower_zone_row))
    upper_zone_row2 = max(1, min(WORLD_H - 2, upper_zone_row2))
    lower_zone_row2 = max(1, min(WORLD_H - 2, lower_zone_row2))

    # How far to extend spine based on population
    if obs.city_pop < 100:
        spine_extent = 12
    elif obs.city_pop < 300:
        spine_extent = 20
    elif obs.city_pop < 600:
        spine_extent = 30
    else:
        spine_extent = 40

    target_min_col = max(2, cx - spine_extent)
    target_max_col = min(WORLD_W - 3, cx + spine_extent)

    # Connect plant to wire spine: need wire from plant to the horizontal spine
    # Plant is at (plant_cx, plant_cy), wire spine is at row wire_row
    # First, connect plant vertically to wire_row if needed
    def connect_plant_to_spine():
        # Wire from plant_cy to wire_row along plant_cx
        col = plant_cx + 2  # just right of plant
        col = max(2, min(WORLD_W - 3, col))
        if plant_cy <= wire_row:
            for r in range(plant_cy, wire_row + 1):
                if not wm[r, col] and not pm[r, col]:
                    if em[r, col] or wm[r, col]:
                        return (Tool.WIRE, col, r)
        else:
            for r in range(plant_cy, wire_row - 1, -1):
                if not wm[r, col] and not pm[r, col]:
                    if em[r, col] or wm[r, col]:
                        return (Tool.WIRE, col, r)
        # Then wire horizontally to spine start
        if not wm[wire_row, col] and em[wire_row, col]:
            return (Tool.WIRE, col, wire_row)
        return None

    # Phase 2: Connect plant to spine
    plant_connected = wm[wire_row, plant_cx + 2] if 0 <= plant_cx + 2 < WORLD_W else False
    if not plant_connected and not np.any(wm[wire_row, max(0, plant_cx):min(WORLD_W, plant_cx + 10)]):
        result = connect_plant_to_spine()
        if result:
            return result

    # Phase 3: Extend horizontal wire spine
    wire_cols_on_spine = [c for c in range(WORLD_W) if wm[wire_row, c]]
    if wire_cols_on_spine:
        min_wc = min(wire_cols_on_spine)
        max_wc = max(wire_cols_on_spine)
    else:
        # Start wire near plant
        sc = plant_cx + 3
        sc = max(2, min(WORLD_W - 3, sc))
        if em[wire_row, sc]:
            return (Tool.WIRE, sc, wire_row)
        return None

    # Extend wire spine rightward
    if max_wc < target_max_col:
        nc = max_wc + 1
        if nc < WORLD_W and not pm[wire_row, nc] and em[wire_row, nc]:
            return (Tool.WIRE, nc, wire_row)

    # Extend wire spine leftward
    if min_wc > target_min_col:
        nc = min_wc - 1
        if nc >= 0 and not pm[wire_row, nc] and em[wire_row, nc]:
            return (Tool.WIRE, nc, wire_row)

    # Phase 4: Build horizontal road spine
    road_cols_on_spine = [c for c in range(WORLD_W) if rm[road_row, c]]

    # Build road parallel to wire, same extent
    for c in range(target_min_col, target_max_col + 1):
        if not rm[road_row, c] and em[road_row, c] and not pm[road_row, c]:
            return (Tool.ROAD, c, road_row)

    # Phase 5: Add vertical roads connecting spine to zones
    # Vertical connectors every 3 columns
    for c in range(target_min_col, target_max_col + 1, 3):
        # Connector from road_row to lower_zone_row
        for r in range(road_row, lower_zone_row + 2):
            if 0 <= r < WORLD_H and not rm[r, c] and em[r, c] and not pm[r, c]:
                # Only if road is nearby in same col
                if rm[road_row, c] or r == road_row:
                    return (Tool.ROAD, c, r)

    # Helper functions
    all_zone_mask = resm | comm | indm

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=3):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=3):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    def pick_tool(idx):
        # Cycle through: 2 residential, 1 commercial, 1 industrial, repeat
        pattern = [Tool.RESIDENTIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.INDUSTRIAL,
                   Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.RESIDENTIAL, Tool.INDUSTRIAL]
        return pattern[idx % len(pattern)]

    # Phase 6: Place zones along spine
    zone_idx = 0
    zone_cols = list(range(target_min_col + 1, target_max_col, 4))

    for zc in zone_cols:
        # Upper zones (above wire)
        zr = upper_zone_row
        if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
            if has_wire_nearby(zr, zc, 4) and has_road_nearby(zr, zc, 4):
                return (pick_tool(zone_idx), zc, zr)
            elif has_wire_nearby(zr, zc, 5):
                # Place anyway, road will come
                if has_road_nearby(zr, zc, 6):
                    return (pick_tool(zone_idx), zc, zr)
        zone_idx += 1

        # Lower zones (below road)
        zr = lower_zone_row
        if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
            if has_wire_nearby(zr, zc, 4) and has_road_nearby(zr, zc, 4):
                return (pick_tool(zone_idx), zc, zr)
        zone_idx += 1

    # Phase 7: Add wires from spine upward to power upper zones
    for wc in wire_cols_on_spine:
        for r in range(wire_row - 1, upper_zone_row - 2, -1):
            if 0 <= r < WORLD_H:
                if wm[r, wc]:
                    break
                if em[r, wc] and not pm[r, wc] and not rm[r, wc]:
                    return (Tool.WIRE, wc, r)
                elif not em[r, wc]:
                    break

    # Phase 8: Add wires from spine downward to power lower zones
    for wc in wire_cols_on_spine[::3]:  # every 3rd wire position
        for r in range(wire_row + 1, lower_zone_row + 2):
            if 0 <= r < WORLD_H:
                if wm[r, wc]:
                    break
                if em[r, wc] and not pm[r, wc] and not rm[r, wc]:
                    return (Tool.WIRE, wc, r)
                elif not em[r, wc] and not rm[r, wc]:
                    break

    # Phase 9: Second coal plant if population demands
    if obs.city_pop > 300 and np.sum(pm) < 9:
        px2 = plant_cx + 25
        py2 = plant_cy
        px2 = max(2, min(WORLD_W - 3, px2))
        py2 = max(2, min(WORLD_H - 3, py2))
        if em[py2, px2]:
            return (Tool.COALPOWER, px2, py2)

    # Phase 10: Second tier zones if growing
    if obs.city_pop > 200:
        for zc in zone_cols:
            zr = upper_zone_row2
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc, 5) and has_road_nearby(zr, zc, 6):
                    return (pick_tool(zone_idx), zc, zr)
            zone_idx += 1

            zr = lower_zone_row2
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc, 5) and has_road_nearby(zr, zc, 6):
                    return (pick_tool(zone_idx), zc, zr)
            zone_idx += 1

    # Phase 11: Police/fire stations for zone happiness
    if obs.city_pop > 500:
        for zc in [cx - 10, cx + 10]:
            zr = cy
            if 1 <= zr <= WORLD_H - 2 and 1 <= zc <= WORLD_W - 2:
                if em[zr, zc] and em[zr - 1, zc] and em[zr + 1, zc]:
                    return (Tool.FIRESTATION, zc, zr)

    # Phase 12: Extend road to second tier zones
    if obs.city_pop > 150:
        for c in range(target_min_col, target_max_col + 1, 3):
            for r in range(lower_zone_row, lower_zone_row2 + 2):
                if 0 <= r < WORLD_H and not rm[r, c] and em[r, c] and not pm[r, c]:
                    if rm[lower_zone_row, c] or rm[road_row, c]:
                        return (Tool.ROAD, c, r)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder.
    Each step reads the current tile_map and places the single most useful tile.
    Strategy:
    1. Place coal power plant if none exists
    2. Build road rows (top and bottom of spine) incrementally
    3. Wire spine from plant rightward, then vertical branches
    4. Place zones wherever road+wire coverage exists
    5. Second power plant when needed
    6. Services for pop growth
    7. React to gaps: extend roads/wires to uncovered zones
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    CX, CY = 20, 50  # plant anchor

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Collect zone info
    res_ys, res_xs = np.where(resm)
    com_ys, com_xs = np.where(comm)
    ind_ys, ind_xs = np.where(indm)
    zone_set = set()
    for r, c in zip(res_ys, res_xs): zone_set.add((int(r), int(c)))
    for r, c in zip(com_ys, com_xs): zone_set.add((int(r), int(c)))
    for r, c in zip(ind_ys, ind_xs): zone_set.add((int(r), int(c)))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not bool(em[nr, nc]) and (nr, nc) not in zone_set:
                    return False
        return True

    # --- Phase 1: Place coal power plant ---
    if not np.any(pm):
        return (Tool.COALPOWER, CX, CY)

    plant_ys, plant_xs = np.where(pm)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    road_ys, road_xs = np.where(rm)
    wire_ys, wire_xs = np.where(wm)

    spine_y = py
    road_top = spine_y - 3
    road_bot = spine_y + 3
    road_start = px + 4
    road_end = min(px + 65, WORLD_W - 4)

    # --- Phase 2: Build top road row ---
    for rx in range(road_start, road_end + 1):
        ry = road_top
        if not in_bounds(rx, ry):
            break
        if not bool(rm[ry, rx]) and not bool(pm[ry, rx]):
            if bool(em[ry, rx]):
                return (Tool.ROAD, rx, ry)
            break

    # --- Phase 3: Build bottom road row ---
    for rx in range(road_start, road_end + 1):
        ry = road_bot
        if not in_bounds(rx, ry):
            break
        if not bool(rm[ry, rx]) and not bool(pm[ry, rx]):
            if bool(em[ry, rx]):
                return (Tool.ROAD, rx, ry)
            break

    # --- Phase 4: Additional road rows for more zone density ---
    road_top2 = spine_y - 7
    road_bot2 = spine_y + 7
    for rx in range(road_start, road_end + 1):
        ry = road_top2
        if not in_bounds(rx, ry): break
        if not bool(rm[ry, rx]) and not bool(pm[ry, rx]):
            if bool(em[ry, rx]):
                return (Tool.ROAD, rx, ry)
            break
    for rx in range(road_start, road_end + 1):
        ry = road_bot2
        if not in_bounds(rx, ry): break
        if not bool(rm[ry, rx]) and not bool(pm[ry, rx]):
            if bool(em[ry, rx]):
                return (Tool.ROAD, rx, ry)
            break

    # --- Phase 5: Wire spine from plant rightward ---
    wire_end_x = road_end
    for wx in range(px + 2, wire_end_x + 1):
        wy = spine_y
        if not in_bounds(wx, wy): break
        if not bool(wm[wy, wx]) and not bool(pm[wy, wx]):
            if bool(em[wy, wx]):
                return (Tool.WIRE, wx, wy)
            break  # blocked

    # --- Phase 6: Vertical wire branches every 5 cols to reach road rows ---
    branch_cols = list(range(px + 5, wire_end_x + 1, 5))
    for bx in branch_cols:
        if not in_bounds(bx, spine_y): continue
        # Only branch if wire is present at spine
        if not (bool(wm[spine_y, bx]) or bool(pm[spine_y, bx])): continue
        # Extend up to road_top2 and down to road_bot2
        for sign in [-1, 1]:
            for dy in range(1, 9):
                wy2 = spine_y + sign * dy
                wx2 = bx
                if not in_bounds(wx2, wy2): break
                if bool(wm[wy2, wx2]) or bool(pm[wy2, wx2]): continue
                if bool(em[wy2, wx2]):
                    return (Tool.WIRE, wx2, wy2)
                break  # blocked by road or zone; stop

    # --- Phase 7: Zone placement wherever road+wire coverage exists ---
    # Build neighborhood masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);  r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);  c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);  r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);  c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    # Keep safe margins
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best = None
        best_score = -1
        step_mod = obs.step % max(len(cxs), 1)
        # Sample candidates deterministically
        n_check = min(len(cxs), 80)
        for offset in range(n_check):
            k = (step_mod + offset * 7) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                # Prefer close to spine, and close to center of road range
                score = 100 - abs(zy - spine_y) - abs(zx - (road_start + road_end) // 2) * 0.1
                if score > best_score:
                    best_score = score
                    best = (zx, zy)
        if best is not None:
            return (pick_tool(), best[0], best[1])

    # --- Phase 8: Second power plant when needed ---
    if total_zones > 8 or obs.city_pop > 200:
        p2x = min(px + 55, WORLD_W - 5)
        p2y = py
        # Check no existing plant nearby
        nearby_plant = False
        for dy in range(-5, 6):
            for dx in range(-5, 6):
                if in_bounds(p2x + dx, p2y + dy) and bool(pm[p2y + dy, p2x + dx]):
                    nearby_plant = True
                    break
            if nearby_plant: break
        if not nearby_plant and in_bounds(p2x, p2y) and bool(em[p2y, p2x]):
            return (Tool.COALPOWER, p2x, p2y)

    # --- Phase 9: Services ---
    if obs.city_pop > 50:
        fx, fy = px + 4, py - 11
        if in_bounds(fx, fy) and bool(em[fy, fx]):
            return (Tool.FIRESTATION, fx, fy)
        px2, py2 = px + 4, py + 11
        if in_bounds(px2, py2) and bool(em[py2, px2]):
            return (Tool.POLICESTATION, px2, py2)

    # --- Phase 10: Extend roads to reach uncovered candidate zones ---
    if len(road_xs) > 0:
        step_k = int(obs.step * 13) % max(len(road_xs), 1)
        rx_s = int(road_xs[step_k])
        ry_s = int(road_ys[step_k])
        # Prefer extending rightward along spine rows
        for dx2, dy2 in [(1, 0), (0, 1), (0, -1), (-1, 0)]:
            nx2, ny2 = rx_s + dx2, ry_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # --- Phase 11: Extend wires from frontier ---
    if len(wire_xs) > 0:
        step_k2 = int(obs.step * 11) % max(len(wire_xs), 1)
        wx_s = int(wire_xs[step_k2])
        wy_s = int(wire_ys[step_k2])
        for dx2, dy2 in [(1, 0), (0, 1), (0, -1), (-1, 0)]:
            nx2, ny2 = wx_s + dx2, wy_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Improved policy: horizontal road spine with vertical zone strips.
    - Coal plant at anchor, wire runs horizontally
    - Roads run vertically (north-south) branching from horizontal wire
    - Zones placed left/right of vertical roads
    - Better zone mix: ~40% res, ~30% com, ~30% ind
    - Two power plants for reliability
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    # Use state as a step counter / phase tracker
    step = obs.step

    # Anchor: plant center - place near left side
    plant_cx, plant_cy = 20, 50

    has_plant = np.any(pm)

    # Phase 0: place first coal power plant
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    wire_positions = set(zip(*np.where(wm))) if np.any(wm) else set()
    road_positions = set(zip(*np.where(rm))) if np.any(rm) else set()
    res_pos = set(zip(*np.where(res_mask(tm))))
    com_pos = set(zip(*np.where(com_mask(tm))))
    ind_pos = set(zip(*np.where(ind_mask(tm))))
    all_zones = res_pos | com_pos | ind_pos

    res_count = len(res_pos)
    com_count = len(com_pos)
    ind_count = len(ind_pos)
    total_zones = res_count + com_count + ind_count

    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def pick_zone():
        # ~40% res, ~30% com, ~30% ind
        if total_zones == 0:
            return Tool.RESIDENTIAL
        if ind_count * 10 < total_zones * 3:
            return Tool.INDUSTRIAL
        if com_count * 10 < total_zones * 3:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def already_zone_nearby(zr, zc, dist=3):
        return any(abs(zr - pr) <= dist and abs(zc - pc) <= dist for (pr, pc) in all_zones)

    # Layout: horizontal wire spine at row 50
    # Vertical roads at cols: 30, 40, 50, 60, 70, 80, 90
    # Zones at rows 44 and 56 (3 away from roads that run vertically)
    # Wire connects plant (col 20) to each road column via row 50

    wire_row = 50  # horizontal wire spine row
    road_row_N = 44  # road running east-west above wire
    road_row_S = 56  # road running east-west below wire

    # Road columns for vertical connection + zone placement
    road_cols = list(range(30, 95, 10))  # 30,40,50,60,70,80,90

    # Zone rows: zones centered at rows that are adjacent to roads
    # Zones above: center row = road_row_N - 3 = 41
    # Zones below: center row = road_row_S + 3 = 59
    zone_row_N = road_row_N - 3  # 41
    zone_row_S = road_row_S + 3  # 59

    # Step 1: Build horizontal wire spine from plant to rightmost road col
    # Wire at (wire_row, col) for col from plant_cx+3 to max(road_cols)+2
    wire_start_col = plant_cx + 3  # 23
    wire_end_col = max(road_cols) + 2  # 92

    wire_cols_in_row = sorted(c for (r, c) in wire_positions if r == wire_row)

    if not wire_cols_in_row:
        # Start wire adjacent to plant
        wc = plant_cx + 3
        if 0 <= wc < WORLD_W:
            return (Tool.WIRE, wc, wire_row)
    else:
        max_wc = max(wire_cols_in_row)
        if max_wc < wire_end_col:
            nc = max_wc + 1
            if 0 <= nc < WORLD_W and (em[wire_row, nc] or wm[wire_row, nc]):
                return (Tool.WIRE, nc, wire_row)

    wire_cols_set = set(c for (r, c) in wire_positions if r == wire_row)

    # Step 2: At each road column, build vertical wire down to road rows if needed
    # Then build the horizontal road rows
    for rc in road_cols:
        if rc not in wire_cols_set:
            continue  # wire hasn't reached here yet

        # Build short vertical wire connectors from spine down to road_row_S and up to road_row_N
        for wr_target in [road_row_N, road_row_S]:
            direction = -1 if wr_target < wire_row else 1
            rows_to_wire = range(wire_row + direction, wr_target + direction, direction)
            for wr in rows_to_wire:
                if 0 <= wr < WORLD_H:
                    if not wm[wr, rc] and not rm[wr, rc]:
                        if em[wr, rc]:
                            return (Tool.WIRE, rc, wr)
                        # else skip - something is there

    # Step 3: Build horizontal roads at road_row_N and road_row_S
    # Road from col 25 to col 93
    road_start_c = 25
    road_end_c = 93

    for road_row in [road_row_N, road_row_S]:
        road_cols_in_row = set(c for (r, c) in road_positions if r == road_row)
        for rc in range(road_start_c, road_end_c + 1):
            if rc not in road_cols_in_row and 0 <= rc < WORLD_W:
                if em[road_row, rc]:
                    return (Tool.ROAD, rc, road_row)

    # Step 4: Place zones adjacent to roads
    # Zones centered at zone_row_N (41) and zone_row_S (59), at each road column center
    road_cols_N = set(c for (r, c) in road_positions if r == road_row_N)
    road_cols_S = set(c for (r, c) in road_positions if r == road_row_S)

    for rc in road_cols:
        # North zones
        if road_cols_N and any(abs(rc - c) <= 5 for c in road_cols_N):
            zr, zc = zone_row_N, rc
            if (2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3 and
                    not already_zone_nearby(zr, zc) and zone_area_free(zr, zc)):
                return (pick_zone(), zc, zr)

        # South zones
        if road_cols_S and any(abs(rc - c) <= 5 for c in road_cols_S):
            zr, zc = zone_row_S, rc
            if (2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3 and
                    not already_zone_nearby(zr, zc) and zone_area_free(zr, zc)):
                return (pick_zone(), zc, zr)

    # Step 5: Second power plant if powered_zones > 10
    plant_positions = set(zip(*np.where(pm))) if np.any(pm) else set()
    if obs.powered_zones > 10 and len(plant_positions) < 9:
        # Place second coal plant at right side, connected to wire
        p2x, p2y = 90, 50
        # Check if it's already there
        if not any(abs(r - p2y) <= 1 and abs(c - p2x) <= 1 for (r, c) in plant_positions):
            if zone_area_free(p2y, p2x):
                return (Tool.COALPOWER, p2x, p2y)

    # Step 6: Add a second tier of roads and zones (rows 35 and 65) if pop growing
    if obs.city_pop > 100:
        road_row_N2 = 35
        road_row_S2 = 65
        zone_row_N2 = road_row_N2 - 3  # 32
        zone_row_S2 = road_row_S2 + 3  # 68

        # Wire vertically from spine up to road_row_N2 at each road col
        for rc in road_cols:
            if rc not in wire_cols_set:
                continue
            for wr_target in [road_row_N2, road_row_S2]:
                direction = -1 if wr_target < wire_row else 1
                rows_to_wire = range(wire_row + direction, wr_target + direction, direction)
                for wr in rows_to_wire:
                    if 0 <= wr < WORLD_H:
                        if not wm[wr, rc] and not rm[wr, rc]:
                            if em[wr, rc]:
                                return (Tool.WIRE, rc, wr)

        # Build outer horizontal roads
        for road_row in [road_row_N2, road_row_S2]:
            road_cols_in_row = set(c for (r, c) in road_positions if r == road_row)
            for rc in range(road_start_c, road_end_c + 1):
                if rc not in road_cols_in_row and 0 <= rc < WORLD_W:
                    if em[road_row, rc]:
                        return (Tool.ROAD, rc, road_row)

        road_cols_N2 = set(c for (r, c) in road_positions if r == road_row_N2)
        road_cols_S2 = set(c for (r, c) in road_positions if r == road_row_S2)

        for rc in road_cols:
            if road_cols_N2 and any(abs(rc - c) <= 5 for c in road_cols_N2):
                zr, zc = zone_row_N2, rc
                if (2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3 and
                        not already_zone_nearby(zr, zc) and zone_area_free(zr, zc)):
                    return (pick_zone(), zc, zr)
            if road_cols_S2 and any(abs(rc - c) <= 5 for c in road_cols_S2):
                zr, zc = zone_row_S2, rc
                if (2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3 and
                        not already_zone_nearby(zr, zc) and zone_area_free(zr, zc)):
                    return (pick_zone(), zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map each step to decide placement.
    Strategy:
    - Place coal power plant at a fixed anchor.
    - Grow a wire spine from the plant outward (scan actual wire positions).
    - Build a road column adjacent to the wire spine.
    - Connect zones to both wire and road via lateral wires/roads.
    - Scan existing infrastructure to decide next needed tile.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    # Fixed anchor in center of map
    PLANT_X, PLANT_Y = 50, 50
    WIRE_COL = PLANT_X + 4   # wire spine column
    ROAD_COL = WIRE_COL + 2  # road column
    LEFT_ZONE_COL = WIRE_COL - 3   # zones left of wire
    RIGHT_ZONE_COL = ROAD_COL + 3  # zones right of road

    # ---- Phase 1: Place power plant ----
    if not np.any(pm):
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    # Find actual plant center
    plant_rows, plant_cols = np.where(pm)
    if len(plant_rows):
        PLANT_Y = int(plant_rows[0])
        PLANT_X = int(plant_cols[0])
        WIRE_COL = PLANT_X + 4
        ROAD_COL = WIRE_COL + 2
        LEFT_ZONE_COL = WIRE_COL - 3
        RIGHT_ZONE_COL = ROAD_COL + 3

    # ---- Read current infrastructure ----
    wire_rows_on_col = sorted([int(r) for r in np.where(wm[:, WIRE_COL])[0]])
    road_rows_on_col = sorted([int(r) for r in np.where(rm[:, ROAD_COL])[0]])

    # Desired vertical extent of spine
    spine_min = max(1, PLANT_Y - 18)
    spine_max = min(WORLD_H - 2, PLANT_Y + 18)

    # ---- Phase 2: Start wire spine adjacent to plant ----
    if not wire_rows_on_col:
        # Place first wire adjacent to plant (right side)
        return (Tool.WIRE, WIRE_COL, PLANT_Y)

    # ---- Phase 3: Extend wire spine toward targets ----
    cur_min = wire_rows_on_col[0]
    cur_max = wire_rows_on_col[-1]

    if cur_max < spine_max:
        nr = cur_max + 1
        if 0 <= nr < WORLD_H:
            return (Tool.WIRE, WIRE_COL, nr)

    if cur_min > spine_min:
        nr = cur_min - 1
        if 0 <= nr >= 0:
            return (Tool.WIRE, WIRE_COL, nr)

    # ---- Phase 4: Build road column covering same rows as wire ----
    for r in wire_rows_on_col:
        if 0 <= ROAD_COL < WORLD_W and not rm[r, ROAD_COL]:
            return (Tool.ROAD, ROAD_COL, r)

    # ---- Phase 5: Lateral wires from spine to left zone column ----
    # For each wire row, ensure wire connects from WIRE_COL-1 to LEFT_ZONE_COL
    for r in wire_rows_on_col:
        for c in range(WIRE_COL - 1, LEFT_ZONE_COL - 1, -1):
            if 0 <= c < WORLD_W:
                # Don't overwrite plant tiles
                if pm[r, c]:
                    break
                if not wm[r, c] and not pm[r, c]:
                    return (Tool.WIRE, c, r)

    # ---- Phase 6: Lateral roads from road col to right zone column ----
    for r in road_rows_on_col:
        for c in range(ROAD_COL + 1, RIGHT_ZONE_COL + 2):
            if 0 <= c < WORLD_W and not rm[r, c]:
                return (Tool.ROAD, c, r)

    # ---- Helper: check zone placement area ----
    def zone_area_ok(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if pm[rr, rc]:
                    return False
        return True

    def zone_exists_near(zr, zc):
        # Check if any zone center within 2 tiles
        sub_res = res_mask(tm)[max(0, zr-2):zr+3, max(0, zc-2):zc+3]
        sub_com = com_mask(tm)[max(0, zr-2):zr+3, max(0, zc-2):zc+3]
        sub_ind = ind_mask(tm)[max(0, zr-2):zr+3, max(0, zc-2):zc+3]
        return np.any(sub_res) or np.any(sub_com) or np.any(sub_ind)

    # Zone counts
    res_cnt = int(np.sum(res_mask(tm)))
    com_cnt = int(np.sum(com_mask(tm)))
    ind_cnt = int(np.sum(ind_mask(tm)))
    total_zones = res_cnt + com_cnt + ind_cnt

    # ---- Phase 7: Place zones where infrastructure exists ----
    zone_rows = list(range(max(1, PLANT_Y - 17), min(WORLD_H - 2, PLANT_Y + 18), 3))

    # Read wire coverage on LEFT_ZONE_COL row-by-row
    for zr in zone_rows:
        # Check wire within 1 row of left zone col
        wire_near = any(
            abs(zr - r) <= 1 and (
                wm[r, LEFT_ZONE_COL] or
                (LEFT_ZONE_COL + 1 < WORLD_W and wm[r, LEFT_ZONE_COL + 1])
            )
            for r in range(max(0, zr - 1), min(WORLD_H, zr + 2))
        )
        # Actually just check wire presence in 3x3 around zone
        zr0, zr1 = max(0, zr - 1), min(WORLD_H, zr + 2)
        zc0_l, zc1_l = max(0, LEFT_ZONE_COL - 1), min(WORLD_W, LEFT_ZONE_COL + 2)
        wire_near_left = np.any(wm[zr0:zr1, zc0_l:zc1_l])

        zc0_r, zc1_r = max(0, RIGHT_ZONE_COL - 1), min(WORLD_W, RIGHT_ZONE_COL + 2)
        road_near_right = np.any(rm[zr0:zr1, zc0_r:zc1_r])
        wire_near_right = np.any(wm[zr0:zr1, zc0_r:zc1_r])

        # Left zone (wire powered)
        zc = LEFT_ZONE_COL
        if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
            if wire_near_left and not zone_exists_near(zr, zc) and zone_area_ok(zr, zc):
                # Balance: ~50% RES, 25% COM, 25% IND
                if ind_cnt * 4 < total_zones + 1:
                    return (Tool.INDUSTRIAL, zc, zr)
                elif com_cnt * 4 < total_zones + 1:
                    return (Tool.COMMERCIAL, zc, zr)
                else:
                    return (Tool.RESIDENTIAL, zc, zr)

        # Right zone (road + wire powered)
        zc = RIGHT_ZONE_COL
        if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
            if road_near_right and wire_near_right and not zone_exists_near(zr, zc) and zone_area_ok(zr, zc):
                if com_cnt * 4 < total_zones + 1:
                    return (Tool.COMMERCIAL, zc, zr)
                else:
                    return (Tool.RESIDENTIAL, zc, zr)

    # ---- Phase 8: Extend infrastructure further if growing ----
    if obs.city_pop > 100 or (obs.powered_zones > 3):
        ext_min = max(1, PLANT_Y - 24)
        ext_max = min(WORLD_H - 2, PLANT_Y + 24)

        if cur_max < ext_max:
            return (Tool.WIRE, WIRE_COL, cur_max + 1)
        if cur_min > ext_min:
            return (Tool.WIRE, WIRE_COL, cur_min - 1)

        # More zone rows
        ext_rows = list(range(max(1, PLANT_Y - 23), min(WORLD_H - 2, PLANT_Y + 24), 3))
        for zr in ext_rows:
            zr0, zr1 = max(0, zr - 1), min(WORLD_H, zr + 2)
            # Lateral wire/road to expanded zone cols
            FAR_LEFT = LEFT_ZONE_COL - 4
            FAR_RIGHT = RIGHT_ZONE_COL + 4

            for c in range(LEFT_ZONE_COL - 1, FAR_LEFT - 1, -1):
                if 0 <= c < WORLD_W and not np.any(wm[zr0:zr1, c:c+1]) and not pm[zr, c]:
                    return (Tool.WIRE, c, zr)

            for c in range(RIGHT_ZONE_COL + 1, FAR_RIGHT + 2):
                if 0 <= c < WORLD_W and not np.any(rm[zr0:zr1, c:c+1]):
                    return (Tool.ROAD, c, zr)

            for zc in [FAR_LEFT, FAR_RIGHT]:
                if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                    zc0, zc1 = max(0, zc - 1), min(WORLD_W, zc + 2)
                    has_w = np.any(wm[zr0:zr1, zc0:zc1])
                    has_r = np.any(rm[zr0:zr1, zc0:zc1])
                    if has_w and has_r and not zone_exists_near(zr, zc) and zone_area_ok(zr, zc):
                        return (Tool.RESIDENTIAL, zc, zr)

    # ---- Phase 9: Nuclear plant if large enough ----
    if obs.city_pop > 600:
        nuke_x = PLANT_X - 8
        nuke_y = PLANT_Y + 10
        if (1 <= nuke_y < WORLD_H - 1 and 1 <= nuke_x < WORLD_W - 1):
            if not np.any(pm[nuke_y - 1:nuke_y + 2, nuke_x - 1:nuke_x + 2]):
                return (Tool.NUCLEARPOWER, nuke_x, nuke_y)

    return None

def act(obs, state):
    """
    Variation: horizontal spine instead of vertical, with zones above and below.
    Wire row + road row side by side horizontally, zones placed above/below.
    Multiple power plants along the wire row.
    Better balanced R/C/I mix.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def has_tile(mask, x, y):
        if 0 <= y < WORLD_H and 0 <= x < WORLD_W:
            return bool(mask[y, x])
        return False

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        # Target: 40% R, 35% C, 25% I
        if com_count / t < 0.35:
            return Tool.COMMERCIAL
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    pop = obs.city_pop

    # Horizontal spine layout
    wire_row = cy - 1      # horizontal wire spine
    road_row = cy          # horizontal road spine (adjacent to wire)
    top_zrow = wire_row - 3   # top zone row center
    bot_zrow = road_row + 3   # bottom zone row center

    # Clamp rows
    wire_row  = max(2, min(WORLD_H - 3, wire_row))
    road_row  = max(2, min(WORLD_H - 3, road_row))
    top_zrow  = max(2, min(WORLD_H - 3, top_zrow))
    bot_zrow  = max(2, min(WORLD_H - 3, bot_zrow))

    # Plant position (left side of wire spine)
    plant_x = max(2, min(WORLD_W - 3, cx - 20))
    plant_y = wire_row

    # Adaptive spine half-length
    if pop < 50:
        spine_half = 12
    elif pop < 200:
        spine_half = 18
    elif pop < 500:
        spine_half = 25
    else:
        spine_half = 35

    spine_min = max(1, cx - spine_half)
    spine_max = min(WORLD_W - 2, cx + spine_half)
    spine_range = range(spine_min, spine_max + 1)

    all_zone_m = resm | comm | indm

    def zone_area_clear(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_m[rr, rc]:
                    return False
        return True

    def zone_present_near(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_m[rr, rc]:
                        return True
        return False

    # ---- Phase 0: Place first coal plant ----
    if not np.any(pm):
        return (Tool.COALPOWER, plant_x, plant_y)

    # ---- Phase 1: Wire spine (horizontal) ----
    for dc in spine_range:
        if not has_tile(wm, dc, wire_row) and not has_tile(pm, dc, wire_row) and not has_tile(rm, dc, wire_row):
            return (Tool.WIRE, dc, wire_row)

    # ---- Phase 2: Road row adjacent to wire ----
    for dc in spine_range:
        if not has_tile(rm, dc, road_row) and not has_tile(pm, dc, road_row) and not has_tile(wm, dc, road_row):
            return (Tool.ROAD, dc, road_row)

    # Precompute wire/road cols
    wire_cols = [c for c in spine_range if wm[wire_row, c]]
    road_cols = [c for c in spine_range if rm[road_row, c]]

    # ---- Phase 3: Lateral wires upward to power top zones ----
    target_top_wire = top_zrow + 2
    for wc in wire_cols:
        for wr in range(wire_row - 1, target_top_wire - 1, -1):
            if not (0 <= wr < WORLD_H):
                break
            if wm[wr, wc] or pm[wr, wc]:
                break
            if rm[wr, wc]:
                break
            if em[wr, wc]:
                return (Tool.WIRE, wc, wr)
            else:
                break

    # ---- Phase 4: Place zones above and below spine ----
    zone_cols = list(range(spine_min + 1, spine_max - 1, 3))

    for zc in zone_cols:
        wire_near = any(abs(zc - wc) <= 2 for wc in wire_cols)
        road_near = any(abs(zc - rc) <= 2 for rc in road_cols)
        if not (wire_near and road_near):
            continue

        # Top zone: check lateral wire reaches it
        zr = top_zrow
        lateral_wired = any(wm[wr, zc] for wr in range(zr - 1, wire_row) if 0 <= wr < WORLD_H)
        if lateral_wired and not zone_present_near(zr, zc) and zone_area_clear(zr, zc):
            return (pick_tool(), zc, zr)

        # Bottom zone: road adjacent, need wire too
        zr = bot_zrow
        bottom_wired = any(wm[wr, zc] for wr in range(road_row, zr + 2) if 0 <= wr < WORLD_H)
        if bottom_wired and not zone_present_near(zr, zc) and zone_area_clear(zr, zc):
            return (pick_tool(), zc, zr)

    # ---- Phase 5: Lateral wires downward to power bottom zones ----
    target_bot_wire = bot_zrow - 2
    for wc in wire_cols:
        for wr in range(road_row + 1, target_bot_wire + 2):
            if not (0 <= wr < WORLD_H):
                break
            if wm[wr, wc] or pm[wr, wc]:
                break
            if rm[wr, wc]:
                continue
            if em[wr, wc]:
                return (Tool.WIRE, wc, wr)
            else:
                break

    # ---- Phase 6: Second coal plant in middle of spine ----
    if pop > 100 and int(np.sum(pm)) < 9:
        px2 = cx
        py2 = wire_row
        px2 = max(2, min(WORLD_W - 3, px2))
        if em[py2, px2] and not wm[py2, px2]:
            return (Tool.COALPOWER, px2, py2)

    # ---- Phase 7: Second tier zones (further above/below) ----
    if pop > 150:
        top2_zrow = max(2, min(WORLD_H - 3, top_zrow - 5))
        bot2_zrow = max(2, min(WORLD_H - 3, bot_zrow + 5))

        for zc in zone_cols:
            wire_near = any(abs(zc - wc) <= 2 for wc in wire_cols)
            road_near = any(abs(zc - rc) <= 2 for rc in road_cols)
            if not (wire_near and road_near):
                continue
            for zr in [top2_zrow, bot2_zrow]:
                if not zone_present_near(zr, zc) and zone_area_clear(zr, zc):
                    r0 = max(0, zr - 5); r1 = min(WORLD_H, zr + 6)
                    c0 = max(0, zc - 5); c1 = min(WORLD_W, zc + 6)
                    if np.any(wm[r0:r1, c0:c1]) and np.any(rm[r0:r1, c0:c1]):
                        return (pick_tool(), zc, zr)

    # ---- Phase 8: Vertical roads at left/right ends for connectivity ----
    if pop > 100:
        for rc in [spine_min, spine_max]:
            if 0 <= rc < WORLD_W:
                for rr in range(max(0, top_zrow - 1), min(WORLD_H, bot_zrow + 2)):
                    if em[rr, rc] and not pm[rr, rc]:
                        return (Tool.ROAD, rc, rr)

    # ---- Phase 9: Third coal plant right side ----
    if pop > 300 and int(np.sum(pm)) < 18:
        px3 = max(2, min(WORLD_W - 3, cx + 20))
        py3 = wire_row
        if em[py3, px3]:
            return (Tool.COALPOWER, px3, py3)

    # ---- Phase 10: Extend spine if city growing ----
    if pop > 400:
        new_spine_min = max(1, spine_min - 5)
        new_spine_max = min(WORLD_W - 2, spine_max + 5)
        for dc in range(new_spine_min, new_spine_max + 1):
            if not has_tile(wm, dc, wire_row) and not has_tile(pm, dc, wire_row):
                return (Tool.WIRE, dc, wire_row)
            if not has_tile(rm, dc, road_row) and not has_tile(pm, dc, road_row):
                return (Tool.ROAD, dc, road_row)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Each step reads tile_map to find existing infrastructure
    - Builds outward from what's already there
    - Places plant, wires, roads, then zones adaptively
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # Target area: center of map
    cx, cy = 60, 50

    # ---- Phase 1: Place coal plant if none exists ----
    if not np.any(pm):
        # Place plant at a fixed spot
        return (Tool.COALPOWER, cx - 15, cy)

    # Find plant center (approximate from plant tiles)
    plant_rows, plant_cols = np.where(pm)
    if len(plant_rows) == 0:
        return (Tool.COALPOWER, cx - 15, cy)
    pr = int(np.mean(plant_rows))
    pc = int(np.mean(plant_cols))

    # ---- Layout derived from plant position ----
    # Wire spine runs vertically at pc+4 (right of plant)
    wire_col = min(pc + 4, WORLD_W - 2)
    # Two road columns flanking the wire
    road_left = max(1, wire_col - 4)
    road_right = min(WORLD_W - 2, wire_col + 4)
    # Zone columns outside the roads
    zone_left = max(1, road_left - 3)
    zone_right = min(WORLD_W - 2, road_right + 3)

    spine_top = max(2, pr - 18)
    spine_bot = min(WORLD_H - 3, pr + 18)

    # ---- Phase 2: Connect plant to wire spine ----
    # Place wire adjacent to plant going right until we reach wire_col
    # Find rightmost plant col
    plant_right = int(np.max(plant_cols))
    if plant_right < wire_col - 1:
        # Need to bridge from plant to wire_col
        for c in range(plant_right + 1, wire_col):
            if 0 <= c < WORLD_W and em[pr, c]:
                return (Tool.WIRE, c, pr)
            elif 0 <= c < WORLD_W and not wm[pr, c]:
                return (Tool.WIRE, c, pr)

    # ---- Phase 3: Extend wire spine vertically ----
    wire_in_col = [r for r in range(WORLD_H) if wm[r, wire_col]]

    if not wire_in_col:
        # Start wire spine at plant row
        if em[pr, wire_col] or not wm[pr, wire_col]:
            return (Tool.WIRE, wire_col, pr)
    else:
        cur_min = min(wire_in_col)
        cur_max = max(wire_in_col)
        # Extend upward
        if cur_min > spine_top:
            nr = cur_min - 1
            if 0 <= nr < WORLD_H:
                return (Tool.WIRE, wire_col, nr)
        # Extend downward
        if cur_max < spine_bot:
            nr = cur_max + 1
            if 0 <= nr < WORLD_H:
                return (Tool.WIRE, wire_col, nr)

    wire_in_col = [r for r in range(WORLD_H) if wm[r, wire_col]]
    if not wire_in_col:
        return (Tool.WIRE, wire_col, pr)

    # ---- Phase 4: Build road columns along wire spine rows ----
    for wr in wire_in_col:
        if 0 <= road_left < WORLD_W and not rm[wr, road_left]:
            return (Tool.ROAD, road_left, wr)
        if 0 <= road_right < WORLD_W and not rm[wr, road_right]:
            return (Tool.ROAD, road_right, wr)

    # ---- Phase 5: Lay lateral wires from spine to zone columns ----
    for wr in wire_in_col:
        # Left lateral: spine -> left zone area
        for wc in range(wire_col - 1, max(0, zone_left - 1), -1):
            if 0 <= wc < WORLD_W and not wm[wr, wc] and (em[wr, wc] or rm[wr, wc]):
                return (Tool.WIRE, wc, wr)
        # Right lateral: spine -> right zone area
        for wc in range(wire_col + 1, min(WORLD_W, zone_right + 2)):
            if 0 <= wc < WORLD_W and not wm[wr, wc] and (em[wr, wc] or rm[wr, wc]):
                return (Tool.WIRE, wc, wr)

    # ---- Phase 6: Place zones ----
    # Zone rows every 3 steps within spine
    zone_rows = list(range(spine_top + 1, spine_bot, 3))

    res_count = int(np.sum(res_m))
    com_count = int(np.sum(com_m))
    ind_count = int(np.sum(ind_m))

    def zone_clear(zr, zc):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                r2, c2 = zr + dr, zc + dc
                if r2 < 0 or r2 >= WORLD_H or c2 < 0 or c2 >= WORLD_W:
                    return False
                # Must be empty (not road/wire/plant/zone)
                if not em[r2, c2]:
                    return False
        return True

    def near_wire_fn(zr, zc, radius=3):
        r1 = max(0, zr - radius)
        r2 = min(WORLD_H, zr + radius + 1)
        c1 = max(0, zc - radius)
        c2 = min(WORLD_W, zc + radius + 1)
        return bool(np.any(wm[r1:r2, c1:c2]))

    def near_road_fn(zr, zc, radius=3):
        r1 = max(0, zr - radius)
        r2 = min(WORLD_H, zr + radius + 1)
        c1 = max(0, zc - radius)
        c2 = min(WORLD_W, zc + radius + 1)
        return bool(np.any(rm[r1:r2, c1:c2]))

    def zone_exists_near(zr, zc, mask, radius=3):
        r1 = max(0, zr - radius)
        r2 = min(WORLD_H, zr + radius + 1)
        c1 = max(0, zc - radius)
        c2 = min(WORLD_W, zc + radius + 1)
        return bool(np.any(mask[r1:r2, c1:c2]))

    all_zones = res_m | com_m | ind_m

    for zr in zone_rows:
        if not (1 <= zr <= WORLD_H - 2):
            continue

        for zc in [zone_left, zone_right]:
            if not (1 <= zc <= WORLD_W - 2):
                continue
            if zone_exists_near(zr, zc, all_zones, 2):
                continue
            if not zone_clear(zr, zc):
                continue
            if not near_wire_fn(zr, zc, 3):
                continue
            if not near_road_fn(zr, zc, 3):
                continue

            # Pick zone type based on current ratios
            if ind_count < max(2, res_count // 3):
                return (Tool.INDUSTRIAL, zc, zr)
            elif com_count < max(2, res_count // 3):
                return (Tool.COMMERCIAL, zc, zr)
            else:
                return (Tool.RESIDENTIAL, zc, zr)

    # ---- Phase 7: If city growing, extend spine and add more zones ----
    if obs.city_pop > 50:
        # Try to extend spine further
        if wire_in_col:
            cur_min = min(wire_in_col)
            cur_max = max(wire_in_col)
            new_top = max(2, spine_top - 10)
            new_bot = min(WORLD_H - 3, spine_bot + 10)
            if cur_min > new_top:
                return (Tool.WIRE, wire_col, cur_min - 1)
            if cur_max < new_bot:
                return (Tool.WIRE, wire_col, cur_max + 1)

    # ---- Phase 8: Fill extra zone columns further out ----
    if obs.city_pop > 100:
        extra_left = max(1, zone_left - 4)
        extra_right = min(WORLD_W - 2, zone_right + 4)
        # Need roads there too
        for wr in wire_in_col:
            for rc in range(road_left - 1, max(0, extra_left - 1), -1):
                if 0 <= rc < WORLD_W and not rm[wr, rc] and em[wr, rc]:
                    return (Tool.ROAD, rc, wr)
            for rc in range(road_right + 1, min(WORLD_W, extra_right + 2)):
                if 0 <= rc < WORLD_W and not rm[wr, rc] and em[wr, rc]:
                    return (Tool.ROAD, rc, wr)

        for zr in zone_rows:
            if not (1 <= zr <= WORLD_H - 2):
                continue
            for zc in [extra_left, extra_right]:
                if not (1 <= zc <= WORLD_W - 2):
                    continue
                if zone_exists_near(zr, zc, all_zones, 2):
                    continue
                if not zone_clear(zr, zc):
                    continue
                if not near_wire_fn(zr, zc, 4):
                    continue
                if not near_road_fn(zr, zc, 4):
                    continue
                return (Tool.RESIDENTIAL, zc, zr)

    return None

