def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map every step to find existing infrastructure
    - Grows wire spine from plant, then roads, then zones
    - Zones placed adjacent to existing road+power coverage
    - Balances RES/COM/IND based on current counts
    """
