    # Plant is 4x4 tiles, center at (pr_mean, pc_mean), footprint ±2
    wire_col = pc_mean + 3  # adjacent to plant right edge
    road_col = wire_col + 2  # road 2 tiles right of wire spine

    wire_positions = list(zip(*np.where(wm)))
    road_positions = list(zip(*np.where(rm)))

    wire_col_rows = sorted([r for (r, c) in wire_positions if c == wire_col])
    road_col_rows = sorted([r for (r, c) in road_positions if c == road_col])

    # Target vertical extent for wire spine
    target_min = max(1, cy - 18)
    target_max = min(WORLD_H - 2, cy + 18)

    # --- Phase 2: Start wire spine adjacent to plant ---
    if not wire_col_rows:
        # Start at plant row
        start_r = max(1, min(WORLD_H - 2, pr_mean))
        if 0 <= wire_col < WORLD_W:
            return (Tool.WIRE, wire_col, start_r)
        return None

    min_row = min(wire_col_rows)
    max_row = max(wire_col_rows)

    # --- Phase 3: Extend wire spine vertically ---
    if max_row < target_max:
        nr = max_row + 1
        if 0 <= nr < WORLD_H and wire_col < WORLD_W:
            return (Tool.WIRE, wire_col, nr)

    if min_row > target_min:
        nr = min_row - 1
        if 0 <= nr >= 0 and wire_col < WORLD_W:
            return (Tool.WIRE, wire_col, nr)

    # --- Phase 4: Build road column parallel to wire spine ---
    for r in wire_col_rows:
        if 0 <= r < WORLD_H and 0 <= road_col < WORLD_W:
            if not rm[r, road_col] and em[r, road_col]:
                return (Tool.ROAD, road_col, r)

    # --- Helper: check if 3x3 zone area is placeable ---
    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                # Must be empty (not road, wire, plant, or existing zone)
                if not em[rr, rc]:
                    return False
        return True

    def near_wire(zr, zc, radius=3):
        # Check if any wire is within radius of zone
        for dr in range(-radius, radius + 1):
            for dc in range(-radius, radius + 1):
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if wm[rr, rc] or pm[rr, rc]:
                        return True
        return False

    def near_road(zr, zc, radius=3):
        for dr in range(-radius, radius + 1):
            for dc in range(-radius, radius + 1):
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if rm[rr, rc]:
                        return True
        return False

    def zone_overlap(zr, zc):
        # Check if any existing zone overlaps with 3x3 area
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if resm[rr, rc] or comm[rr, rc] or indm[rr, rc]:
                        return True
        return False

    # --- Phase 5: Add lateral wires from spine to left zone column ---
    left_zone_col = wire_col - 4  # left zones, center 4 tiles left of wire
    right_zone_col = road_col + 3  # right zones, center 3 tiles right of road

    # Ensure lateral wire coverage: extend wire leftward for zone rows
    zone_rows = list(range(max(1, cy - 17), min(WORLD_H - 2, cy + 18), 3))

    for zr in zone_rows:
        if zr in wire_col_rows or any(abs(zr - wr) <= 0 for wr in wire_col_rows):
            # Lay lateral wire towards left zone
            for wc in range(wire_col - 1, max(0, left_zone_col - 2), -1):
                if 0 <= wc < WORLD_W and em[wc_ok := wc] and em[zr, wc_ok]:
                    if not wm[zr, wc_ok]:
                        return (Tool.WIRE, wc_ok, zr)
                    # already wire, continue
                    continue
                break

    # --- Phase 6: Place zones where wire AND road coverage exists ---
    for zr in zone_rows:
        w_near = near_wire(zr, left_zone_col, radius=4)
        r_near = near_road(zr, left_zone_col, radius=4)

        if w_near or r_near:
            # Left column zones
            zc = left_zone_col
            if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                if not zone_overlap(zr, zc) and zone_area_free(zr, zc):
                    # Choose zone type based on current balance
                    if ind_count * 3 < res_count:
                        return (Tool.INDUSTRIAL, zc, zr)
                    elif com_count * 3 < res_count:
                        return (Tool.COMMERCIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

        # Right column zones
        w_near2 = near_wire(zr, right_zone_col, radius=5)
        r_near2 = near_road(zr, right_zone_col, radius=4)

        if w_near2 or r_near2:
            zc = right_zone_col
            if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                if not zone_overlap(zr, zc) and zone_area_free(zr, zc):
                    if com_count * 3 < res_count:
                        return (Tool.COMMERCIAL, zc, zr)
                    elif ind_count * 3 < res_count:
                        return (Tool.INDUSTRIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

    # --- Phase 7: Extend road to right zone column ---
    for r in wire_col_rows:
        for rc2 in range(road_col + 1, min(right_zone_col + 3, WORLD_W)):
            if 0 <= r < WORLD_H and em[r, rc2] and not rm[r, rc2]:
                return (Tool.ROAD, rc2, r)

    # --- Phase 8: Second wire column further right for right zones ---
    wire2_col = right_zone_col - 1
    wire2_rows = sorted([r for (r, c) in wire_positions if c == wire2_col])

    if not wire2_rows and wire_col_rows:
        # Build horizontal wire bridge from spine to second column
        mid_r = wire_col_rows[len(wire_col_rows) // 2]
        for wc in range(wire_col + 1, wire2_col + 1):
            if 0 <= wc < WORLD_W and (em[mid_r, wc] or wm[mid_r, wc]):
                if not wm[mid_r, wc]:
                    return (Tool.WIRE, wc, mid_r)
    elif wire2_rows:
        # Extend second wire spine
        min2, max2 = min(wire2_rows), max(wire2_rows)
        if max2 < target_max:
            nr = max2 + 1
            if 0 <= nr < WORLD_H:
                return (Tool.WIRE, wire2_col, nr)
        if min2 > target_min:
            nr = min2 - 1
            if 0 <= nr < WORLD_H:
                return (Tool.WIRE, wire2_col, nr)

    # --- Phase 9: Expand with more zones if pop growing well ---
    if obs.city_pop > 200:
        extra_cols = [left_zone_col - 4, right_zone_col + 4, wire_col - 8]
        extra_rows = list(range(max(1, cy - 20), min(WORLD_H - 2, cy + 21), 3))
        for zr in extra_rows:
            for zc in extra_cols:
                if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                    if not zone_overlap(zr, zc) and zone_area_free(zr, zc):
                        if near_road(zr, zc, radius=5) and near_wire(zr, zc, radius=6):
                            if com_count * 2 < res_count:
                                return (Tool.COMMERCIAL, zc, zr)
                            elif ind_count * 2 < res_count:
                                return (Tool.INDUSTRIAL, zc, zr)
                            else:
                                return (Tool.RESIDENTIAL, zc, zr)

    # --- Phase 10: Add second power plant if funded and growing ---
    if obs.city_pop > 400 and obs.funds > 5000:
        p2x = cx + 15
        p2y = cy
        # Check if area is free
        area_free = all(
            em[p2y + dy, p2x + dx]
            for dy in range(-2, 3) for dx in range(-2, 3)
            if 0 <= p2y + dy < WORLD_H and 0 <= p2x + dx < WORLD_W
        )
        if area_free:
            return (Tool.COALPOWER, p2x, p2y)

    return None

def act(obs, state):
    """
    Hybrid policy:
    - Compact vertical spine: wire col + road col (from Parent A)
    - Lateral wires left and right to power flanking zones
    - Balanced R/C/I zones flanking spine
    - Adaptive spine length based on population
    - Multiple power plants as city grows
    - Reactive zone placement using dilated road/wire masks (from Parent B)
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def has_tile(mask, x, y):
        if in_bounds(x, y):
            return bool(mask[y, x])
        return False

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Layout constants
    plant_x = cx - 8
    plant_y = cy
    wire_col = cx - 1
    road_col = cx
    left_zcol = wire_col - 4
    right_zcol = road_col + 4

    wire_col   = max(2, min(WORLD_W - 3, wire_col))
    road_col   = max(2, min(WORLD_W - 3, road_col))
    left_zcol  = max(2, min(WORLD_W - 3, left_zcol))
    right_zcol = max(2, min(WORLD_W - 3, right_zcol))
    plant_x    = max(2, min(WORLD_W - 3, plant_x))

    pop = obs.city_pop
    if pop < 50:
        spine_half = 12
    elif pop < 200:
        spine_half = 18
    elif pop < 500:
        spine_half = 24
    else:
        spine_half = 30

    spine_min = max(1, cy - spine_half)
    spine_max = min(WORLD_H - 2, cy + spine_half)
    spine_range = range(spine_min, spine_max + 1)

    # ---- Phase 0: Place first coal plant ----
    if not np.any(pm):
        return (Tool.COALPOWER, plant_x, plant_y)

    # ---- Phase 1: Wire spine (vertical) ----
    for dy in spine_range:
        if not has_tile(wm, wire_col, dy) and not has_tile(pm, wire_col, dy):
            return (Tool.WIRE, wire_col, dy)

    # ---- Phase 2: Road column adjacent to wire ----
    for dy in spine_range:
        if not has_tile(rm, road_col, dy) and not has_tile(pm, road_col, dy) and not has_tile(wm, road_col, dy):
            return (Tool.ROAD, road_col, dy)

    wire_rows = [r for r in spine_range if wm[r, wire_col]]
    road_rows = [r for r in spine_range if rm[r, road_col]]

    # ---- Phase 3: Lateral wires leftward to power left zones ----
    target_left_wire = max(0, left_zcol - 1)
    for wr in wire_rows:
        for wc in range(wire_col - 1, target_left_wire - 1, -1):
            if not in_bounds(wc, wr):
                break
            if wm[wr, wc] or pm[wr, wc]:
                break
            if rm[wr, wc]:
                break
            if em[wr, wc]:
                return (Tool.WIRE, wc, wr)
            else:
                break

    # ---- Phase 4: Lateral wires rightward to power right zones ----
    target_right_wire = min(WORLD_W - 1, right_zcol + 2)
    for wr in wire_rows:
        for wc in range(road_col + 1, target_right_wire + 1):
            if not in_bounds(wc, wr):
                break
            if wm[wr, wc] or pm[wr, wc]:
                break
            if rm[wr, wc]:
                continue
            if em[wr, wc]:
                return (Tool.WIRE, wc, wr)
            else:
                break

    # ---- Phase 5: Place zones flanking spine ----
    zone_rows = list(range(spine_min + 1, spine_max - 1, 3))
    all_zone_m = resm | comm | indm

    def zone_area_clear(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not in_bounds(rc, rr):
                    return False
                if not em[rr, rc] and not all_zone_m[rr, rc]:
                    return False
        return True

    def zone_present_near(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if in_bounds(rc, rr) and all_zone_m[rr, rc]:
                    return True
        return False

    for zr in zone_rows:
        wire_near = any(abs(zr - wr) <= 2 for wr in wire_rows)
        road_near = any(abs(zr - rr) <= 2 for rr in road_rows)
        if not (wire_near and road_near):
            continue

        # Left zone
        zc = left_zcol
        lateral_wired = any(wm[zr, wc] for wc in range(zc - 1, wire_col) if in_bounds(wc, zr))
        if lateral_wired and not zone_present_near(zr, zc) and zone_area_clear(zr, zc):
            return (pick_tool(), zc, zr)

        # Right zone
        zc = right_zcol
        right_wired = any(wm[zr, wc] for wc in range(road_col, min(WORLD_W, zc + 2)) if in_bounds(wc, zr))
        if right_wired and not zone_present_near(zr, zc) and zone_area_clear(zr, zc):
            return (pick_tool(), zc, zr)

    # ---- Phase 6: Second coal plant ----
    if pop > 150 and int(np.sum(pm)) < 9:
        px2 = max(2, min(WORLD_W - 3, plant_x + 22))
        py2 = plant_y
        if in_bounds(px2, py2) and em[py2, px2]:
            # Wire connecting second plant toward spine
            for wc in range(px2 - 1, road_col - 1, -1):
                if in_bounds(wc, py2):
                    if wm[py2, wc] or pm[py2, wc]:
                        break
                    if em[py2, wc]:
                        return (Tool.WIRE, wc, py2)
                    else:
                        break
            return (Tool.COALPOWER, px2, py2)

    # ---- Phase 7: Second tier of zones ----
    if pop > 100:
        left2_zcol  = max(2, min(WORLD_W - 3, left_zcol - 5))
        right2_zcol = max(2, min(WORLD_W - 3, right_zcol + 5))

        for zr in zone_rows:
            wire_near = any(abs(zr - wr) <= 2 for wr in wire_rows)
            road_near = any(abs(zr - rr) <= 2 for rr in road_rows)
            if not (wire_near and road_near):
                continue
            for zc in [left2_zcol, right2_zcol]:
                if not zone_present_near(zr, zc) and zone_area_clear(zr, zc):
                    r0 = max(0, zr - 5); r1 = min(WORLD_H, zr + 6)
                    c0 = max(0, zc - 5); c1 = min(WORLD_W, zc + 6)
                    if np.any(wm[r0:r1, c0:c1]) and np.any(rm[r0:r1, c0:c1]):
                        return (pick_tool(), zc, zr)

    # ---- Phase 8: Reactive zone placement using dilated masks (from Parent B) ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            r0 = max(0, dy);   r1 = WORLD_H
            c0 = max(0, dx);   c1 = WORLD_W
            sr0 = max(0, -dy); sr1 = WORLD_H
            sc0 = max(0, -dx); sc1 = WORLD_W
            h = min(r1 - r0, sr1 - sr0)
            w = min(c1 - c0, sc1 - sc0)
            if h > 0 and w > 0:
                nbr_road[r0:r0+h, c0:c0+w] |= rm[sr0:sr0+h, sc0:sc0+w]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            r0 = max(0, dy);   r1 = WORLD_H
            c0 = max(0, dx);   c1 = WORLD_W
            sr0 = max(0, -dy); sr1 = WORLD_H
            sc0 = max(0, -dx); sc1 = WORLD_W
            h = min(r1 - r0, sr1 - sr0)
            w = min(c1 - c0, sc1 - sc0)
            if h > 0 and w > 0:
                nbr_wire[r0:r0+h, c0:c0+w] |= wm[sr0:sr0+h, sc0:sc0+w]
                nbr_wire[r0:r0+h, c0:c0+w] |= pm[sr0:sr0+h, sc0:sc0+w]

    cand = em & nbr_road & nbr_wire & ~pm
    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        k = int((obs.step * 17 + int(tm[cy, cx]) % 100)) % len(cxs)
        zx, zy = int(cxs[k]), int(cys[k])
        if zone_area_clear(zy, zx):
            return (pick_tool(), zx, zy)

    # ---- Phase 9: Horizontal roads for connectivity ----
    if pop > 80:
        for rr in [spine_min, spine_max]:
            if 0 <= rr < WORLD_H:
                for rc in range(max(0, left_zcol - 1), min(WORLD_W, right_zcol + 2)):
                    if em[rr, rc] and not pm[rr, rc]:
                        return (Tool.ROAD, rc, rr)

    # ---- Phase 10: Third coal plant ----
    if pop > 400 and int(np.sum(pm)) < 18:
        px3 = max(2, min(WORLD_W - 3, plant_x + 12))
        py3 = max(2, min(WORLD_H - 3, plant_y - 22))
        if in_bounds(px3, py3) and em[py3, px3]:
            return (Tool.COALPOWER, px3, py3)

    # ---- Phase 11: Services ----
    if pop > 200:
        fx, fy = max(2, wire_col - 6), max(2, cy - 8)
        if in_bounds(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
        px2, py2 = max(2, road_col + 6), max(2, cy + 8)
        if in_bounds(px2, py2) and em[py2, px2]:
            return (Tool.POLICESTATION, px2, py2)

    return None

def act(obs, state):
    """
    Variation: Use a HORIZONTAL spine (road runs east-west) instead of vertical.
    Place zones above and below the spine. Multiple clusters spread horizontally.
    Better zone mix (more commercial/industrial).
    Power plant on left, wire runs east along spine, road parallel.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        # Target: 35% res, 35% com, 30% ind
        if ind_count / t < 0.30:
            return Tool.INDUSTRIAL
        if com_count / t < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    all_zone_mask = resm | comm | indm

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    # Use horizontal spines
    # Power plant at left-center
    plant_x = cx - 30
    plant_y = cy

    # Phase 1: Place coal power plant
    if not np.any(pm):
        return (Tool.COALPOWER, plant_x, plant_y)

    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Horizontal spine layout
    # Wire row: plant_cy (same row as plant)
    # Road row: plant_cy + 2 (parallel, below wire)
    # Zones: above wire row (plant_cy - 3) and below road row (plant_cy + 5)

    wire_row = plant_cy
    road_row = plant_cy + 3
    top_zone_row = wire_row - 4    # zones above
    bot_zone_row = road_row + 4    # zones below

    wire_row = max(2, min(WORLD_H - 3, wire_row))
    road_row = max(2, min(WORLD_H - 3, road_row))
    top_zone_row = max(1, min(WORLD_H - 2, top_zone_row))
    bot_zone_row = max(1, min(WORLD_H - 2, bot_zone_row))

    # Dynamic spine extent (horizontal)
    if obs.city_pop < 100:
        spine_extent = 15
    elif obs.city_pop < 300:
        spine_extent = 25
    elif obs.city_pop < 600:
        spine_extent = 40
    else:
        spine_extent = 55

    target_min_col = max(1, plant_cx + 3)
    target_max_col = min(WORLD_W - 2, plant_cx + spine_extent)

    wire_cols_on_row = sorted([c for c in range(WORLD_W) if wm[wire_row, c]])
    road_cols_on_row = sorted([c for c in range(WORLD_W) if rm[road_row, c]])
    road_cols_set = set(road_cols_on_row)

    # Phase 2: Start wire adjacent to plant
    if not wire_cols_on_row:
        for dc in range(1, 6):
            nc = plant_cx + dc
            if 0 <= nc < WORLD_W and (em[wire_row, nc] or wm[wire_row, nc]):
                return (Tool.WIRE, nc, wire_row)
        return None

    min_wire_col = min(wire_cols_on_row)
    max_wire_col = max(wire_cols_on_row)

    # Phase 3: Extend wire spine rightward
    if max_wire_col < target_max_col:
        nc = max_wire_col + 1
        if nc < WORLD_W and not pm[wire_row, nc]:
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # Phase 4: Build road row parallel to wire
    for c in wire_cols_on_row:
        if 0 <= c < WORLD_W and 0 <= road_row < WORLD_H:
            if not rm[road_row, c] and em[road_row, c]:
                return (Tool.ROAD, c, road_row)

    # Phase 5: Place zones along the corridor (zone columns every 3 cols)
    zone_cols = list(range(max(1, target_min_col), min(WORLD_W - 1, target_max_col + 1), 3))

    for zc in zone_cols:
        wire_near = any(abs(zc - wc) <= 2 for wc in wire_cols_on_row)
        road_near = any(abs(zc - rc) <= 2 for rc in road_cols_on_row)

        if wire_near and road_near:
            # Try top zone
            zr = top_zone_row
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc, 5) and has_road_nearby(zr, zc, 6):
                    return (pick_tool(), zc, zr)

            # Try bottom zone
            zr = bot_zone_row
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc, 6) and has_road_nearby(zr, zc, 5):
                    return (pick_tool(), zc, zr)

    # Phase 6: Vertical wires from spine to top zones
    for wc in wire_cols_on_row:
        for wr in range(wire_row - 1, max(top_zone_row - 2, 0), -1):
            if 0 <= wr < WORLD_H:
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc]:
                    break

    # Phase 7: Road extensions to bottom zones
    for rc in road_cols_on_row:
        if not rm[road_row, rc]:
            continue
        for rr in range(road_row + 1, bot_zone_row + 2):
            if 0 <= rr < WORLD_H:
                if rm[rr, rc]:
                    break
                if em[rr, rc] and not pm[rr, rc]:
                    return (Tool.ROAD, rc, rr)
                elif not em[rr, rc]:
                    break

    # Phase 8: Wire extensions to bottom zones
    for wc in wire_cols_on_row:
        for wr in range(wire_row + 1, bot_zone_row + 2):
            if 0 <= wr < WORLD_H:
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc] and not rm[wr, wc]:
                    break

    # Phase 9: Second power plant when pop grows
    if obs.city_pop > 300 and int(np.sum(pm)) < 9:
        px2, py2 = plant_cx + spine_extent // 2, plant_cy
        if 2 <= py2 <= WORLD_H - 3 and 2 <= px2 <= WORLD_W - 3:
            area_clear = True
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    rr, rc = py2 + dr, px2 + dc
                    if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                        if not (em[rr, rc] or pm[rr, rc]):
                            area_clear = False
            if area_clear:
                return (Tool.COALPOWER, px2, py2)

    # Phase 10: Second horizontal cluster above when pop >= 200
    if obs.city_pop >= 200:
        wire_row2 = wire_row - 10
        road_row2 = wire_row2 - 3
        top_zone_row2 = wire_row2 + 4
        bot_zone_row2 = road_row2 - 4

        wire_row2 = max(2, min(WORLD_H - 3, wire_row2))
        road_row2 = max(2, min(WORLD_H - 3, road_row2))
        top_zone_row2 = max(1, min(WORLD_H - 2, top_zone_row2))
        bot_zone_row2 = max(1, min(WORLD_H - 2, bot_zone_row2))

        wire_cols2 = sorted([c for c in range(WORLD_W) if wm[wire_row2, c]])
        road_cols2 = set(c for c in range(WORLD_W) if rm[road_row2, c])

        if not wire_cols2:
            # Build vertical wire bridge from main spine up to cluster2
            for wr in range(wire_row - 1, wire_row2 - 1, -1):
                if 0 <= wr < WORLD_H:
                    wc = plant_cx + 5
                    if not wm[wr, wc] and em[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    elif not em[wr, wc] and not wm[wr, wc]:
                        break
        else:
            min_wc2 = min(wire_cols2)
            max_wc2 = max(wire_cols2)

            if max_wc2 < target_max_col:
                nc = max_wc2 + 1
                if nc < WORLD_W and em[wire_row2, nc]:
                    return (Tool.WIRE, nc, wire_row2)

            for c in wire_cols2:
                if c not in road_cols2 and em[road_row2, c]:
                    return (Tool.ROAD, c, road_row2)

            for zc in zone_cols:
                wire_near2 = any(abs(zc - wc) <= 2 for wc in wire_cols2)
                road_near2 = any(abs(zc - rc) <= 2 for rc in road_cols2)
                if wire_near2 and road_near2:
                    for zr in [top_zone_row2, bot_zone_row2]:
                        if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                            if has_wire_nearby(zr, zc, 6) and has_road_nearby(zr, zc, 5):
                                return (pick_tool(), zc, zr)

            # Wire up/down from cluster2 spine
            for wc in wire_cols2:
                for wr in range(wire_row2 + 1, top_zone_row2 + 2):
                    if 0 <= wr < WORLD_H:
                        if wm[wr, wc]: break
                        if em[wr, wc] and not pm[wr, wc]:
                            return (Tool.WIRE, wc, wr)
                        elif not em[wr, wc]: break

    # Phase 11: Third cluster below when pop >= 400
    if obs.city_pop >= 400:
        wire_row3 = road_row + 10
        road_row3 = wire_row3 + 3
        top_zone_row3 = wire_row3 - 4
        bot_zone_row3 = road_row3 + 4

        wire_row3 = max(2, min(WORLD_H - 3, wire_row3))
        road_row3 = max(2, min(WORLD_H - 3, road_row3))
        top_zone_row3 = max(1, min(WORLD_H - 2, top_zone_row3))
        bot_zone_row3 = max(1, min(WORLD_H - 2, bot_zone_row3))

        wire_cols3 = sorted([c for c in range(WORLD_W) if wm[wire_row3, c]])
        road_cols3 = set(c for c in range(WORLD_W) if rm[road_row3, c])

        if not wire_cols3:
            for wr in range(road_row + 1, wire_row3 + 1):
                if 0 <= wr < WORLD_H:
                    wc = plant_cx + 5
                    if not wm[wr, wc] and em[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    elif not em[wr, wc] and not wm[wr, wc]:
                        break
        else:
            max_wc3 = max(wire_cols3)
            if max_wc3 < target_max_col:
                nc = max_wc3 + 1
                if nc < WORLD_W and em[wire_row3, nc]:
                    return (Tool.WIRE, nc, wire_row3)

            for c in wire_cols3:
                if c not in road_cols3 and em[road_row3, c]:
                    return (Tool.ROAD, c, road_row3)

            for zc in zone_cols:
                wire_near3 = any(abs(zc - wc) <= 2 for wc in wire_cols3)
                road_near3 = any(abs(zc - rc) <= 2 for rc in road_cols3)
                if wire_near3 and road_near3:
                    for zr in [top_zone_row3, bot_zone_row3]:
                        if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                            if has_wire_nearby(zr, zc, 6) and has_road_nearby(zr, zc, 5):
                                return (pick_tool(), zc, zr)

            for wc in wire_cols3:
                for wr in range(wire_row3 - 1, max(top_zone_row3 - 2, 0), -1):
                    if 0 <= wr < WORLD_H:
                        if wm[wr, wc]: break
                        if em[wr, wc] and not pm[wr, wc]:
                            return (Tool.WIRE, wc, wr)
                        elif not em[wr, wc]: break

    return None

def act(obs, state):
    """
    Hybrid policy combining best of both parents:
    - Coal plant first, then wire spine, then dual road columns flanking wire
    - Zones placed on both sides with proper power+road access
    - Adaptive spine length based on population
    - Second cluster expansion when growing
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    cx, cy = 55, 50

    has_plant = np.any(pm)

    # Phase 1: Place coal power plant
    plant_cx, plant_cy = cx - 10, cy
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Gather positions
    wire_positions = list(zip(*np.where(wm))) if np.any(wm) else []
    road_positions = list(zip(*np.where(rm))) if np.any(rm) else []
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    res_positions = list(zip(*np.where(resm))) if np.any(resm) else []
    com_positions = list(zip(*np.where(comm))) if np.any(comm) else []
    ind_positions = list(zip(*np.where(indm))) if np.any(indm) else []
    all_zones = set(res_positions) | set(com_positions) | set(ind_positions)

    res_count = len(res_positions)
    com_count = len(com_positions)
    ind_count = len(ind_positions)
    total_zones = res_count + com_count + ind_count + 1

    # Spine layout: plant -> wire_col -> road_col_L, road_col_R -> zones
    wire_col = plant_cx + 4   # main wire spine (clear of plant footprint)
    road_col_R = wire_col + 1  # road to right of wire
    road_col_L = wire_col - 1  # road to left of wire
    zone_col_R = road_col_R + 3  # right zone column
    zone_col_L = road_col_L - 3  # left zone column

    # Adaptive vertical span
    base_span = 12
    extra_span = min(28, obs.city_pop // 20)
    target_span = base_span + extra_span
    tmin = max(2, cy - target_span)
    tmax = min(WORLD_H - 3, cy + target_span)

    # Phase 2: Extend wire spine vertically
    wire_rows_in_col = sorted(r for (r, c) in wire_positions if c == wire_col)

    if not wire_rows_in_col:
        # Place first wire adjacent to plant
        for dy in range(-1, 2):
            ny = plant_cy + dy
            if 0 <= ny < WORLD_H and 0 <= wire_col < WORLD_W and em[ny, wire_col]:
                return (Tool.WIRE, wire_col, ny)
    else:
        min_wr = min(wire_rows_in_col)
        max_wr = max(wire_rows_in_col)
        # Extend downward first
        if max_wr < tmax:
            nr = max_wr + 1
            if 0 <= nr < WORLD_H and 0 <= wire_col < WORLD_W:
                if em[nr, wire_col] or wm[nr, wire_col]:
                    return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if min_wr > tmin:
            nr = min_wr - 1
            if 0 <= nr < WORLD_H and 0 <= wire_col < WORLD_W:
                if em[nr, wire_col] or wm[nr, wire_col]:
                    return (Tool.WIRE, wire_col, nr)

    wire_rows_set = set(wire_rows_in_col)

    # Phase 3: Build road columns flanking wire
    if wire_rows_in_col:
        road_rows_R = set(r for (r, c) in road_positions if c == road_col_R)
        for wr in wire_rows_in_col:
            if wr not in road_rows_R and 0 <= road_col_R < WORLD_W:
                if em[wr, road_col_R]:
                    return (Tool.ROAD, road_col_R, wr)
        road_rows_L = set(r for (r, c) in road_positions if c == road_col_L)
        for wr in wire_rows_in_col:
            if wr not in road_rows_L and 0 <= road_col_L >= 0:
                if em[wr, road_col_L]:
                    return (Tool.ROAD, road_col_L, wr)

    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def already_zone_nearby(zr, zc):
        return any(abs(zr - pr) <= 1 and abs(zc - pc) <= 1 for (pr, pc) in all_zones)

    def choose_zone_type(side):
        # Aim for ~50% res, ~25% com, ~25% ind
        if ind_count * 4 < total_zones:
            return Tool.INDUSTRIAL if side == 'L' else Tool.INDUSTRIAL
        elif com_count * 4 < total_zones:
            return Tool.COMMERCIAL
        else:
            return Tool.RESIDENTIAL

    # Phase 4: Place zones adjacent to road columns
    road_rows_R2 = set(r for (r, c) in road_positions if c == road_col_R)
    road_rows_L2 = set(r for (r, c) in road_positions if c == road_col_L)

    for zr in wire_rows_in_col:
        road_nearby_R = any(abs(zr - rr) <= 2 for rr in road_rows_R2)
        road_nearby_L = any(abs(zr - rr) <= 2 for rr in road_rows_L2)
        wire_nearby = zr in wire_rows_set

        if not wire_nearby:
            continue

        if road_nearby_R:
            zc = zone_col_R
            if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                if not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                    return (choose_zone_type('R'), zc, zr)

        if road_nearby_L:
            zc = zone_col_L
            if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                if not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                    return (choose_zone_type('L'), zc, zr)

    # Phase 5: Add lateral roads to reach zone columns
    for wr in wire_rows_in_col:
        # Lateral road to right zone
        for rc in range(road_col_R + 1, zone_col_R):
            if 0 <= rc < WORLD_W and em[wr, rc]:
                return (Tool.ROAD, rc, wr)
        # Lateral wire to left zone (keep power reach)
        for wc in range(wire_col - 1, zone_col_L + 1, -1):
            if 0 <= wc < WORLD_W and em[wr, wc] and not rm[wr, wc]:
                return (Tool.WIRE, wc, wr)

    # Phase 6: Second expansion cluster to the right when population grows
    if obs.city_pop > 150:
        wire_col2 = zone_col_R + 5
        road_col2R = wire_col2 + 1
        road_col2L = wire_col2 - 1
        zone_col2R = road_col2R + 3
        zone_col2L = road_col2L - 3  # This overlaps zone_col_R, use right only

        wire_rows_col2 = sorted(r for (r, c) in wire_positions if c == wire_col2)

        if not wire_rows_col2:
            # Lay horizontal wire connection from main spine
            if 0 <= cy < WORLD_H:
                for wc in range(wire_col + 1, wire_col2 + 1):
                    if 0 <= wc < WORLD_W and em[cy, wc] and not rm[cy, wc]:
                        return (Tool.WIRE, wc, cy)
        else:
            min_wr2 = min(wire_rows_col2)
            max_wr2 = max(wire_rows_col2)
            tmax2 = min(WORLD_H - 3, cy + target_span)
            tmin2 = max(2, cy - target_span)

            if max_wr2 < tmax2:
                nr = max_wr2 + 1
                if 0 <= nr < WORLD_H and 0 <= wire_col2 < WORLD_W:
                    if em[nr, wire_col2] or wm[nr, wire_col2]:
                        return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > tmin2:
                nr = min_wr2 - 1
                if 0 <= nr < WORLD_H and 0 <= wire_col2 < WORLD_W:
                    if em[nr, wire_col2] or wm[nr, wire_col2]:
                        return (Tool.WIRE, wire_col2, nr)

            # Build road right of wire_col2
            road_rows_2R = set(r for (r, c) in road_positions if c == road_col2R)
            for wr in wire_rows_col2:
                if wr not in road_rows_2R and 0 <= road_col2R < WORLD_W:
                    if em[wr, road_col2R]:
                        return (Tool.ROAD, road_col2R, wr)

            road_rows_2R_list = sorted(r for (r, c) in road_positions if c == road_col2R)
            for zr in sorted(wire_rows_col2):
                wire_nearby2 = zr in set(wire_rows_col2)
                road_nearby2 = any(abs(zr - rr) <= 2 for rr in road_rows_2R_list)
                if wire_nearby2 and road_nearby2:
                    zc = zone_col2R
                    if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                        if not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                            if com_count * 4 < total_zones:
                                return (Tool.COMMERCIAL, zc, zr)
                            elif ind_count * 4 < total_zones:
                                return (Tool.INDUSTRIAL, zc, zr)
                            else:
                                return (Tool.RESIDENTIAL, zc, zr)

            # Lateral roads for second cluster
            for wr in wire_rows_col2:
                for rc in range(road_col2R + 1, zone_col2R):
                    if 0 <= rc < WORLD_W and em[wr, rc]:
                        return (Tool.ROAD, rc, wr)

    # Phase 7: Second coal plant for more power when large
    if obs.city_pop > 400 and not state.get("second_plant", False):
        plant2_cx = plant_cx + 25
        plant2_cy = plant_cy
        plant2_clear = True
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = plant2_cy + dr, plant2_cx + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if not em[rr, rc]:
                        plant2_clear = False
                        break
        if plant2_clear:
            state["second_plant"] = True
            return (Tool.COALPOWER, plant2_cx, plant2_cy)

    # Phase 8: Horizontal roads to improve connectivity
    if obs.city_pop > 200:
        for rr in [tmin + 1, tmax - 1, cy]:
            if 0 <= rr < WORLD_H:
                for rc in range(zone_col_L - 1, zone_col_R + 2):
                    if 0 <= rc < WORLD_W and em[rr, rc] and not pm[rr, rc]:
                        return (Tool.ROAD, rc, rr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Scan map each step to find where power/roads reach
    - Extend infrastructure adjacent to what exists
    - Place zones near road+power
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    all_zone = resm | comm | indm

    cx, cy = WORLD_W // 2, WORLD_H // 2

    # ---- Phase 1: Place power plant if none exists ----
    if not np.any(pm):
        # Place at a safe offset from center-left
        px, py = cx - 25, cy
        px = max(2, min(WORLD_W - 3, px))
        py = max(2, min(WORLD_H - 3, py))
        return (Tool.COALPOWER, px, py)

    # Find plant center
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Key rows: wire spine just above center, road spine just below
    wire_row = cy - 2
    road_row = cy + 2
    wire_row = max(2, min(WORLD_H - 3, wire_row))
    road_row = max(2, min(WORLD_H - 3, road_row))

    # ---- Phase 2: Wire from plant rightward to wire spine row ----
    # Connect plant's right edge to wire_row vertically first
    link_col = min(plant_cx + 2, WORLD_W - 2)

    # Vertical wire: from plant_cy down/up to wire_row along link_col
    if plant_cy != wire_row:
        r_range = range(min(plant_cy, wire_row), max(plant_cy, wire_row) + 1)
        for r in r_range:
            if not wm[r, link_col] and not pm[r, link_col] and em[r, link_col]:
                return (Tool.WIRE, link_col, r)

    # ---- Phase 3: Extend horizontal wire spine reactively ----
    # Find current wire extent on wire_row
    wire_on_row = np.where(wm[wire_row, :])[0]
    if len(wire_on_row) == 0:
        # Start wire from link_col on wire_row
        if em[wire_row, link_col] and not pm[wire_row, link_col]:
            return (Tool.WIRE, link_col, wire_row)
        # Try a neighbor
        for dc in range(1, 5):
            c = link_col + dc
            if 0 <= c < WORLD_W and em[wire_row, c]:
                return (Tool.WIRE, c, wire_row)
    else:
        min_wc = int(wire_on_row.min())
        max_wc = int(wire_on_row.max())

        # Determine target extent based on population
        pop = obs.city_pop
        if pop < 100:
            target_half = 15
        elif pop < 300:
            target_half = 25
        elif pop < 600:
            target_half = 35
        else:
            target_half = 45

        target_left = max(2, cx - target_half)
        target_right = min(WORLD_W - 3, cx + target_half)

        # Extend right first, then left
        if max_wc < target_right:
            nc = max_wc + 1
            if nc < WORLD_W and em[wire_row, nc] and not pm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)
        if min_wc > target_left:
            nc = min_wc - 1
            if nc >= 0 and em[wire_row, nc] and not pm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # ---- Phase 4: Build road spine reactively ----
    road_on_row = np.where(rm[road_row, :])[0]
    wire_on_row = np.where(wm[wire_row, :])[0]

    if len(wire_on_row) > 0:
        min_wc = int(wire_on_row.min())
        max_wc = int(wire_on_row.max())

        if len(road_on_row) == 0:
            # Start road at wire start
            rc = min_wc
            if em[road_row, rc] and not pm[road_row, rc]:
                return (Tool.ROAD, rc, road_row)
        else:
            min_rc = int(road_on_row.min())
            max_rc = int(road_on_row.max())
            # Extend road to match wire extent
            if max_rc < max_wc:
                nc = max_rc + 1
                if nc < WORLD_W and em[road_row, nc] and not pm[road_row, nc]:
                    return (Tool.ROAD, nc, road_row)
            if min_rc > min_wc:
                nc = min_rc - 1
                if nc >= 0 and em[road_row, nc] and not pm[road_row, nc]:
                    return (Tool.ROAD, nc, road_row)

    # ---- Phase 5: Place zones reactively ----
    # Zones go above wire row and below road row
    # Check each potential zone column and place if road+wire nearby

    def has_wire_near(r, c, rad=4):
        r0, r1 = max(0, r-rad), min(WORLD_H, r+rad+1)
        c0, c1 = max(0, c-rad), min(WORLD_W, c+rad+1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_near(r, c, rad=3):
        r0, r1 = max(0, r-rad), min(WORLD_H, r+rad+1)
        c0, c1 = max(0, c-rad), min(WORLD_W, c+rad+1)
        return np.any(rm[r0:r1, c0:c1])

    def area_clear(r, c):
        if r < 1 or r > WORLD_H-2 or c < 1 or c > WORLD_W-2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc2 = r+dr, c+dc
                if not (0 <= rr < WORLD_H and 0 <= rc2 < WORLD_W):
                    return False
                if not em[rr, rc2] and not all_zone[rr, rc2]:
                    return False
        return True

    def zone_present(r, c):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc2 = r+dr, c+dc
                if 0 <= rr < WORLD_H and 0 <= rc2 < WORLD_W:
                    if all_zone[rr, rc2]:
                        return True
        return False

    def pick_tool(idx):
        pattern = [Tool.RESIDENTIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL,
                   Tool.INDUSTRIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL,
                   Tool.RESIDENTIAL, Tool.RESIDENTIAL, Tool.INDUSTRIAL]
        return pattern[idx % len(pattern)]

    # Zone rows: above wire spine and below road spine
    upper_zr = wire_row - 3
    lower_zr = road_row + 3
    upper_zr2 = wire_row - 7
    lower_zr2 = road_row + 7

    upper_zr = max(2, min(WORLD_H-3, upper_zr))
    lower_zr = max(2, min(WORLD_H-3, lower_zr))
    upper_zr2 = max(2, min(WORLD_H-3, upper_zr2))
    lower_zr2 = max(2, min(WORLD_H-3, lower_zr2))

    # Scan existing road extent to determine zone columns
    road_on_row = np.where(rm[road_row, :])[0]
    if len(road_on_row) > 0:
        min_rc = int(road_on_row.min())
        max_rc = int(road_on_row.max())
    else:
        # Fall back to wire extent
        wire_on_row = np.where(wm[wire_row, :])[0]
        if len(wire_on_row) > 0:
            min_rc = int(wire_on_row.min())
            max_rc = int(wire_on_row.max())
        else:
            min_rc, max_rc = cx - 10, cx + 10

    zone_idx = 0
    for zc in range(min_rc + 1, max_rc, 4):
        zc = max(1, min(WORLD_W-2, zc))

        # ---- Vertical connector roads ----
        # Connect road_row down to lower_zr
        for r in range(road_row, lower_zr + 2):
            if 0 <= r < WORLD_H and not rm[r, zc] and em[r, zc] and not pm[r, zc]:
                if rm[road_row, zc] or r == road_row:
                    return (Tool.ROAD, zc, r)

        # Upper zone
        zr = upper_zr
        if not zone_present(zr, zc) and area_clear(zr, zc):
            if has_wire_near(zr, zc, 4) and has_road_near(zr, zc, 4):
                return (pick_tool(zone_idx), zc, zr)
        zone_idx += 1

        # Lower zone
        zr = lower_zr
        if not zone_present(zr, zc) and area_clear(zr, zc):
            if has_wire_near(zr, zc, 4) and has_road_near(zr, zc, 4):
                return (pick_tool(zone_idx), zc, zr)
        zone_idx += 1

    # ---- Phase 6: Vertical wires to power upper zones ----
    wire_on_row = np.where(wm[wire_row, :])[0]
    for wc in wire_on_row[::3]:
        wc = int(wc)
        for r in range(wire_row - 1, max(upper_zr - 2, 0), -1):
            if wm[r, wc]:
                break
            if em[r, wc] and not pm[r, wc] and not rm[r, wc]:
                return (Tool.WIRE, wc, r)
            elif not em[r, wc]:
                break

    # ---- Phase 7: Vertical wires downward to power lower zones ----
    for wc in wire_on_row[::3]:
        wc = int(wc)
        for r in range(wire_row + 1, min(lower_zr + 2, WORLD_H)):
            if wm[r, wc]:
                break
            if em[r, wc] and not pm[r, wc] and not rm[r, wc]:
                return (Tool.WIRE, wc, r)
            elif not em[r, wc] and not rm[r, wc]:
                break

    # ---- Phase 8: Second power plant if needed ----
    pop = obs.city_pop
    if pop > 200 and int(np.sum(pm)) < 9:
        px2 = plant_cx + 30
        py2 = plant_cy
        px2 = max(2, min(WORLD_W - 3, px2))
        py2 = max(2, min(WORLD_H - 3, py2))
        if em[py2, px2]:
            return (Tool.COALPOWER, px2, py2)

    # ---- Phase 9: Second tier zones ----
    if pop > 150:
        for zc in range(min_rc + 1, max_rc, 4):
            zc = max(1, min(WORLD_W-2, zc))

            zr = upper_zr2
            if not zone_present(zr, zc) and area_clear(zr, zc):
                if has_wire_near(zr, zc, 5) and has_road_near(zr, zc, 6):
                    return (pick_tool(zone_idx), zc, zr)
            zone_idx += 1

            zr = lower_zr2
            if not zone_present(zr, zc) and area_clear(zr, zc):
                if has_wire_near(zr, zc, 5) and has_road_near(zr, zc, 6):
                    return (pick_tool(zone_idx), zc, zr)
            zone_idx += 1

    # ---- Phase 10: Extend road to second tier ----
    if pop > 100:
        for zc in range(min_rc + 1, max_rc, 4):
            zc = max(1, min(WORLD_W-2, zc))
            for r in range(lower_zr, lower_zr2 + 2):
                if 0 <= r < WORLD_H and not rm[r, zc] and em[r, zc] and not pm[r, zc]:
                    if rm[lower_zr, zc] or rm[road_row, zc]:
                        return (Tool.ROAD, zc, r)

    # ---- Phase 11: Fire/police for happiness ----
    if pop > 400:
        for zc in [cx - 15, cx + 15]:
            zr = cy
            zc = max(1, min(WORLD_W-2, zc))
            if 1 <= zr <= WORLD_H-2:
                if em[zr, zc] and em[zr-1, zc] and em[zr+1, zc]:
                    return (Tool.FIRESTATION, zc, zr)

    return None

def act(obs, state):
    """
    Different approach: horizontal layout instead of vertical.
    - Power plant on left side
    - Horizontal wire spine running right
    - Road rows above and below the wire spine
    - Zones placed between road rows
    - Multiple rows of zones for a wider city footprint
    - Better zone mix: more commercial and industrial
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Center of map
    cx, cy = WORLD_W // 2, WORLD_H // 2

    # Layout: horizontal spine
    # Plant at left-center
    plant_x = 10
    plant_y = cy

    # Wire spine runs horizontally at cy
    wire_row = cy
    # Roads above and below wire spine
    upper_road_row = wire_row - 4
    lower_road_row = wire_row + 4
    # Zone rows between roads and wire
    upper_zone_row = wire_row - 2
    lower_zone_row = wire_row + 2
    # Far zone rows outside roads
    far_upper_zone_row = wire_row - 7
    far_lower_zone_row = wire_row + 7
    # Second road rows for expansion
    far_upper_road_row = wire_row - 8
    far_lower_road_row = wire_row + 8

    # Phase 1: Place coal power plant
    if not np.any(pm):
        return (Tool.COALPOWER, plant_x, plant_y)

    # Find plant location
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Wire spine starts just right of plant
    wire_start_col = plant_cx + 3

    # Determine extent of wire based on population
    if obs.city_pop < 100:
        wire_extent = 20
    elif obs.city_pop < 300:
        wire_extent = 35
    elif obs.city_pop < 600:
        wire_extent = 50
    else:
        wire_extent = 70

    wire_target_end = min(WORLD_W - 2, wire_start_col + wire_extent)

    # Current wire positions on horizontal spine
    wire_cols_on_spine = sorted([c for c in range(WORLD_W) if 0 <= wire_row < WORLD_H and wm[wire_row, c]])

    # Phase 2: Start wire if none on spine
    if not wire_cols_on_spine:
        c = wire_start_col
        if 0 <= c < WORLD_W and 0 <= wire_row < WORLD_H:
            if em[wire_row, c] or wm[wire_row, c]:
                return (Tool.WIRE, c, wire_row)
        return None

    min_wire_col = min(wire_cols_on_spine)
    max_wire_col = max(wire_cols_on_spine)

    # Phase 3: Extend wire spine rightward
    if max_wire_col < wire_target_end:
        nc = max_wire_col + 1
        if nc < WORLD_W and not pm[wire_row, nc]:
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # Phase 4: Build upper road row
    for c in wire_cols_on_spine:
        r = upper_road_row
        if 0 <= r < WORLD_H and 0 <= c < WORLD_W:
            if not rm[r, c] and em[r, c] and not pm[r, c] and not wm[r, c]:
                return (Tool.ROAD, c, r)

    # Phase 5: Build lower road row
    for c in wire_cols_on_spine:
        r = lower_road_row
        if 0 <= r < WORLD_H and 0 <= c < WORLD_W:
            if not rm[r, c] and em[r, c] and not pm[r, c] and not wm[r, c]:
                return (Tool.ROAD, c, r)

    # Helper: check if 3x3 zone area is clear
    all_zone_mask = resm | comm | indm

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=5):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    def pick_tool():
        # Aim for 50% res, 30% com, 20% ind
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        if com_count / t < 0.30:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Phase 6: Place vertical wires connecting spine to road rows
    # For each column on spine, wire from spine to upper road and lower road
    for sc in wire_cols_on_spine[::2]:  # every other col to save steps
        # Wire upward to upper road
        for r in range(wire_row - 1, upper_road_row - 1, -1):
            if 0 <= r < WORLD_H and 0 <= sc < WORLD_W:
                if wm[r, sc] or pm[r, sc]:
                    break
                if rm[r, sc]:
                    break
                if em[r, sc]:
                    return (Tool.WIRE, sc, r)
        # Wire downward to lower road
        for r in range(wire_row + 1, lower_road_row + 1):
            if 0 <= r < WORLD_H and 0 <= sc < WORLD_W:
                if wm[r, sc] or pm[r, sc]:
                    break
                if rm[r, sc]:
                    break
                if em[r, sc]:
                    return (Tool.WIRE, sc, r)

    # Phase 7: Place zones between wire spine and roads
    zone_cols = list(range(max(2, wire_start_col), min(WORLD_W - 2, wire_target_end + 1), 3))

    for zc in zone_cols:
        road_near_upper = any(abs(zc - rc) <= 2 for rc in [c for c in range(WORLD_W) if rm[upper_road_row, c]])
        road_near_lower = any(abs(zc - rc) <= 2 for rc in [c for c in range(WORLD_W) if rm[lower_road_row, c]])

        # Upper zone row (between wire and upper road)
        zr = upper_zone_row
        if 1 <= zr <= WORLD_H - 2:
            wire_near = any(abs(zc - wc) <= 3 for wc in wire_cols_on_spine)
            if wire_near and not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc) and has_road_nearby(zr, zc):
                    return (pick_tool(), zc, zr)

        # Lower zone row
        zr = lower_zone_row
        if 1 <= zr <= WORLD_H - 2:
            wire_near = any(abs(zc - wc) <= 3 for wc in wire_cols_on_spine)
            if wire_near and not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc) and has_road_nearby(zr, zc):
                    return (pick_tool(), zc, zr)

    # Phase 8: Second power plant for large cities
    if obs.city_pop > 200 and int(np.sum(pm)) < 18:
        px2 = plant_cx + 40
        py2 = plant_cy
        if 2 <= py2 <= WORLD_H - 3 and 2 <= px2 <= WORLD_W - 3:
            if em[py2, px2]:
                return (Tool.COALPOWER, px2, py2)

    # Phase 9: Expand to far zone rows with additional roads
    if obs.city_pop > 150:
        # Far upper road
        for c in wire_cols_on_spine:
            r = far_upper_road_row
            if 0 <= r < WORLD_H and 0 <= c < WORLD_W:
                if not rm[r, c] and em[r, c] and not pm[r, c]:
                    return (Tool.ROAD, c, r)

        # Far lower road
        for c in wire_cols_on_spine:
            r = far_lower_road_row
            if 0 <= r < WORLD_H and 0 <= c < WORLD_W:
                if not rm[r, c] and em[r, c] and not pm[r, c]:
                    return (Tool.ROAD, c, r)

        # Far upper zones
        for zc in zone_cols:
            zr = far_upper_zone_row
            if 1 <= zr <= WORLD_H - 2:
                if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                    if has_wire_nearby(zr, zc, 6) and has_road_nearby(zr, zc, 4):
                        return (pick_tool(), zc, zr)

        # Far lower zones
        for zc in zone_cols:
            zr = far_lower_zone_row
            if 1 <= zr <= WORLD_H - 2:
                if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                    if has_wire_nearby(zr, zc, 6) and has_road_nearby(zr, zc, 4):
                        return (pick_tool(), zc, zr)

    # Phase 10: Vertical connector roads at intervals
    if obs.city_pop > 100:
        for vc in wire_cols_on_spine[::8]:
            for r in range(far_upper_road_row, far_lower_road_row + 1):
                if 0 <= r < WORLD_H and 0 <= vc < WORLD_W:
                    if em[r, vc] and not wm[r, vc] and not pm[r, vc]:
                        return (Tool.ROAD, vc, r)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map each step to find existing infrastructure
    and extends it reactively. No precomputed plan.

    Strategy:
    - Place coal power plant first
    - Extend wire eastward from plant
    - Build road 2 rows below wire
    - Place zones adjacent to road/wire
    - Add second plant when wire reaches far enough
    - React to what's actually on the map
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    res_count = int(np.sum(res_m))
    com_count = int(np.sum(com_m))
    ind_count = int(np.sum(ind_m))
    zone_count = res_count + com_count + ind_count

    # Find all plant cells
    plant_cells = list(zip(*np.where(pm))) if np.any(pm) else []
    # Find all wire cells
    wire_cells = list(zip(*np.where(wm))) if np.any(wm) else []
    # Find all road cells
    road_cells = list(zip(*np.where(rm))) if np.any(rm) else []

    # --- STEP 1: Ensure at least one power plant ---
    # Plant 1 target: col 10, row 45
    P1_X, P1_Y = 10, 45
    P2_X, P2_Y = 70, 45

    def near_plant(cx, cy, r=4):
        return any(abs(pr - cy) <= r and abs(pc - cx) <= r for (pr, pc) in plant_cells)

    if not near_plant(P1_X, P1_Y):
        # Place first power plant
        return (Tool.COALPOWER, P1_X, P1_Y)

    # --- STEP 2: Build wire spine eastward at row 45 from plant ---
    WIRE_ROW = 45
    ROAD_ROW = 47  # road 2 rows below wire
    TOP_ZONE_ROW = 41   # zones above wire (center row, 3x3)
    BOT_ZONE_ROW = 51   # zones below road (center row, 3x3)

    # Find current wire extent in WIRE_ROW
    wire_in_row = sorted(c for (r, c) in wire_cells if r == WIRE_ROW)
    road_in_row = sorted(c for (r, c) in road_cells if r == ROAD_ROW)

    # Determine how far right we want wire to go
    # Start small, grow as population increases
    target_right = min(WORLD_W - 4, 15 + obs.city_pop // 5 + 20)
    target_right = max(target_right, 40)  # at least to col 40

    # Start wire adjacent to plant (plant occupies ~col 10, so wire starts at 13)
    WIRE_START = P1_X + 3

    if not wire_in_row:
        # Place first wire
        if em[WIRE_ROW, WIRE_START]:
            return (Tool.WIRE, WIRE_START, WIRE_ROW)
        else:
            # Try to bulldoze/place anyway (auto-bulldoze is on)
            return (Tool.WIRE, WIRE_START, WIRE_ROW)
    else:
        max_wc = max(wire_in_row)
        min_wc = min(wire_in_row)

        # Extend rightward
        if max_wc < target_right:
            nc = max_wc + 1
            # Don't overwrite plant or zone
            if 0 <= nc < WORLD_W:
                if em[WIRE_ROW, nc] or wm[WIRE_ROW, nc]:
                    return (Tool.WIRE, nc, WIRE_ROW)
                elif not pm[WIRE_ROW, nc]:  # don't bulldoze plant
                    return (Tool.WIRE, nc, WIRE_ROW)

    # --- STEP 3: Build road below wire ---
    if wire_in_row:
        wire_set = set(wire_in_row)
        road_set = set(road_in_row)
        for wc in sorted(wire_in_row):
            if wc not in road_set and 0 <= ROAD_ROW < WORLD_H:
                if em[ROAD_ROW, wc]:
                    return (Tool.ROAD, wc, ROAD_ROW)

    # --- STEP 4: Place zones adjacent to road/wire ---
    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def zone_near(zr, zc):
        # Check if a zone center is already near this position
        for r in range(max(0, zr-3), min(WORLD_H, zr+4)):
            for c in range(max(0, zc-3), min(WORLD_W, zc+4)):
                if res_m[r, c] or com_m[r, c] or ind_m[r, c]:
                    return True
        return False

    def pick_zone():
        total = res_count + com_count + ind_count
        if total == 0:
            return Tool.RESIDENTIAL
        # 40% res, 30% com, 30% ind
        r_frac = res_count / (total + 1)
        c_frac = com_count / (total + 1)
        i_frac = ind_count / (total + 1)
        if r_frac <= 0.40 and res_count <= com_count + ind_count + 2:
            return Tool.RESIDENTIAL
        elif i_frac < 0.30:
            return Tool.INDUSTRIAL
        elif c_frac < 0.30:
            return Tool.COMMERCIAL
        else:
            return Tool.RESIDENTIAL

    # Check road coverage for zone placement
    road_set = set(road_in_row)
    wire_set = set(wire_in_row) if wire_in_row else set()

    # Place top zones (above wire, centered at TOP_ZONE_ROW)
    # Zone center needs to be within 2 rows of wire for power access
    # Road access: road at ROAD_ROW is 6 rows below TOP_ZONE_ROW - might need connector road
    # Actually place zones beside road for easier access

    # Place zones above road (row 44, adjacent to road at 47? too far)
    # Let's place top zones at row 43 (3 above wire_row=45, center of 3x3 touching wire)
    # and bottom zones at row 50 (adjacent below road at 47)

    TOP_Z = 42   # center row for top zones (rows 41-43, adjacent to wire at 45)
    BOT_Z = 50   # center row for bot zones (rows 49-51, adjacent to road at 47)

    # Place zones every 4 columns along wire/road
    cols_with_infra = sorted(wire_set | road_set)
    for wc in cols_with_infra:
        if wc < 4 or wc > WORLD_W - 4:
            continue
        # Try top zone
        if not zone_near(TOP_Z, wc) and zone_area_free(TOP_Z, wc):
            return (pick_zone(), wc, TOP_Z)
        # Try bottom zone
        if not zone_near(BOT_Z, wc) and zone_area_free(BOT_Z, wc):
            return (pick_zone(), wc, BOT_Z)

    # --- STEP 5: Second power plant when wire extends far ---
    if wire_in_row and max(wire_in_row) >= 45 and not near_plant(P2_X, P2_Y):
        # Check wire reaches near second plant location
        if max(wire_in_row) >= P2_X - 3:
            return (Tool.COALPOWER, P2_X, P2_Y)

    # --- STEP 6: Connect second plant to wire if needed ---
    if near_plant(P2_X, P2_Y) and wire_in_row:
        max_wc = max(wire_in_row)
        if max_wc < P2_X - 3:
            nc = max_wc + 1
            if 0 <= nc < WORLD_W and em[WIRE_ROW, nc]:
                return (Tool.WIRE, nc, WIRE_ROW)

    # --- STEP 7: Extend wire further for more zones ---
    if wire_in_row:
        max_wc = max(wire_in_row)
        extended_target = min(WORLD_W - 4, max_wc + 2 + obs.city_pop // 20)
        if max_wc < extended_target:
            nc = max_wc + 1
            if 0 <= nc < WORLD_W and not pm[WIRE_ROW, nc]:
                return (Tool.WIRE, nc, WIRE_ROW)

    # --- STEP 8: Fill gaps in road ---
    if wire_in_row:
        for wc in sorted(wire_in_row):
            if wc not in road_set and 0 <= ROAD_ROW < WORLD_H and not pm[ROAD_ROW, wc]:
                return (Tool.ROAD, wc, ROAD_ROW)

    # --- STEP 9: Add vertical road spurs to reach more zones ---
    if obs.city_pop >= 100:
        # Add zones in a second row further out
        TOP_Z2 = 37
        BOT_Z2 = 55
        for wc in sorted(wire_set | road_set):
            if wc < 4 or wc > WORLD_W - 4:
                continue
            if not zone_near(TOP_Z2, wc) and zone_area_free(TOP_Z2, wc):
                # Need road connector
                for cr in range(TOP_Z2 + 2, WIRE_ROW):
                    if em[cr, wc] and not wm[cr, wc]:
                        return (Tool.ROAD, wc, cr)
                return (pick_zone(), wc, TOP_Z2)
            if not zone_near(BOT_Z2, wc) and zone_area_free(BOT_Z2, wc):
                for cr in range(ROAD_ROW + 1, BOT_Z2 - 1):
                    if em[cr, wc]:
                        return (Tool.ROAD, wc, cr)
                return (pick_zone(), wc, BOT_Z2)

    # --- STEP 10: Third cluster if high population ---
    if obs.city_pop >= 300:
        WIRE_ROW3 = 65
        ROAD_ROW3 = 67
        wire3 = sorted(c for (r, c) in wire_cells if r == WIRE_ROW3)
        road3 = set(c for (r, c) in road_cells if r == ROAD_ROW3)

        # Place plant 3
        P3_X, P3_Y = 10, 65
        if not near_plant(P3_X, P3_Y):
            return (Tool.COALPOWER, P3_X, P3_Y)

        if not wire3:
            ws = P3_X + 3
            if 0 <= ws < WORLD_W and em[WIRE_ROW3, ws]:
                return (Tool.WIRE, ws, WIRE_ROW3)
        else:
            max_wc3 = max(wire3)
            if max_wc3 < 100:
                nc = max_wc3 + 1
                if 0 <= nc < WORLD_W and em[WIRE_ROW3, nc]:
                    return (Tool.WIRE, nc, WIRE_ROW3)
            for wc in sorted(wire3):
                if wc not in road3 and em[ROAD_ROW3, wc]:
                    return (Tool.ROAD, wc, ROAD_ROW3)
            TOP_Z3 = 61
            BOT_Z3 = 71
            for wc in sorted(set(wire3) | road3):
                if wc < 4 or wc > WORLD_W - 4:
                    continue
                if not zone_near(TOP_Z3, wc) and zone_area_free(TOP_Z3, wc):
                    return (pick_zone(), wc, TOP_Z3)
                if not zone_near(BOT_Z3, wc) and zone_area_free(BOT_Z3, wc):
                    return (pick_zone(), wc, BOT_Z3)

    return None

def act(obs, state):
    """
    Revised policy: horizontal wire spine instead of vertical,
    zones placed above and below the spine,
    better road connectivity, balanced zone mix (res/com/ind ~3:1:1),
    two power plants for reliability.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    # Use state as a step counter / plan queue
    if 'plan' not in state:
        state['plan'] = []
        state['plan_idx'] = 0
        state['built'] = set()

    # ---- Layout constants ----
    # Power plant anchors
    P1x, P1y = 20, 50  # left plant
    P2x, P2y = 90, 50  # right plant (added later)

    # Horizontal wire spine: row 50
    wire_row = 50
    # Road rows above and below
    road_row_T = wire_row - 2  # row 48
    road_row_B = wire_row + 2  # row 52
    # Zone rows
    zone_row_T = wire_row - 5  # row 45
    zone_row_B = wire_row + 5  # row 55

    # Second tier
    road_row_T2 = wire_row - 9   # row 41
    road_row_B2 = wire_row + 9   # row 59
    zone_row_T2 = wire_row - 12  # row 38
    zone_row_B2 = wire_row + 12  # row 62

    has_plant = np.any(pm)
    has_plant1 = has_plant  # simplified check

    # Step 1: place first coal plant
    if not has_plant1:
        return (Tool.COALPOWER, P1x, P1y)

    # Check if second plant placed
    plant_tiles = np.argwhere(pm)
    has_plant2 = len(plant_tiles) >= 4  # coal plant is ~3x3 tiles

    # Build horizontal wire spine from plant outward
    wire_cols_present = set(c for (r, c) in zip(*np.where(wm)) if r == wire_row) if np.any(wm) else set()
    road_T_cols = set(c for (r, c) in zip(*np.where(rm)) if r == road_row_T) if np.any(rm) else set()
    road_B_cols = set(c for (r, c) in zip(*np.where(rm)) if r == road_row_B) if np.any(rm) else set()
    road_T2_cols = set(c for (r, c) in zip(*np.where(rm)) if r == road_row_T2) if np.any(rm) else set()
    road_B2_cols = set(c for (r, c) in zip(*np.where(rm)) if r == road_row_B2) if np.any(rm) else set()

    res_pos = set(zip(*np.where(res_mask(tm)))) if np.any(res_mask(tm)) else set()
    com_pos = set(zip(*np.where(com_mask(tm)))) if np.any(com_mask(tm)) else set()
    ind_pos = set(zip(*np.where(ind_mask(tm)))) if np.any(ind_mask(tm)) else set()
    all_zones = res_pos | com_pos | ind_pos
    res_count = len(res_pos)
    com_count = len(com_pos)
    ind_count = len(ind_pos)

    # Wire spine target: col 23 to col 87 (avoiding plants)
    wire_start = P1x + 3   # 23
    wire_end = P2x - 3     # 87

    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def already_zone_nearby(zr, zc, radius=4):
        return any(abs(zr - pr) <= radius and abs(zc - pc) <= radius for (pr, pc) in all_zones)

    def pick_zone(res_c, com_c, ind_c):
        total = res_c + com_c + ind_c
        if total == 0:
            return Tool.RESIDENTIAL
        # Target ratio: 3 res : 1 com : 1 ind
        if ind_c * 3 < total:
            return Tool.INDUSTRIAL
        elif com_c * 3 < total:
            return Tool.COMMERCIAL
        else:
            return Tool.RESIDENTIAL

    # Phase 2: extend wire spine horizontally
    if not wire_cols_present:
        # Start wire adjacent to plant
        if 0 <= wire_row < WORLD_H and 0 <= wire_start < WORLD_W:
            return (Tool.WIRE, wire_start, wire_row)
    else:
        max_wc = max(wire_cols_present)
        min_wc = min(wire_cols_present)
        # Extend rightward
        if max_wc < wire_end:
            nc = max_wc + 1
            if 0 <= nc < WORLD_W and (em[wire_row, nc] or wm[wire_row, nc]):
                return (Tool.WIRE, nc, wire_row)
        # Extend leftward toward plant (should already connect)
        if min_wc > wire_start:
            nc = min_wc - 1
            if 0 <= nc < WORLD_W and (em[wire_row, nc] or wm[wire_row, nc]):
                return (Tool.WIRE, nc, wire_row)

    if not wire_cols_present:
        return None

    # Phase 3: place second power plant when spine reaches mid
    if not has_plant2 and max(wire_cols_present) >= 70:
        # Check if area around P2 is usable
        if em[P2y, P2x]:
            return (Tool.COALPOWER, P2x, P2y)

    # Phase 4: build top road row
    for wc in sorted(wire_cols_present):
        if wc % 3 == 0:  # every 3 cols
            if wc not in road_T_cols and 0 <= road_row_T < WORLD_H and em[road_row_T, wc]:
                return (Tool.ROAD, wc, road_row_T)

    # Phase 5: build bottom road row
    for wc in sorted(wire_cols_present):
        if wc % 3 == 0:
            if wc not in road_B_cols and 0 <= road_row_B < WORLD_H and em[road_row_B, wc]:
                return (Tool.ROAD, wc, road_row_B)

    # Phase 6: connect roads to wire spine with vertical wires (every 6 cols)
    for wc in sorted(wire_cols_present):
        if wc % 6 == 0:
            # Vertical wire from wire_row up to road_row_T
            for wr in range(wire_row - 1, road_row_T - 1, -1):
                if em[wr, wc]:
                    return (Tool.WIRE, wc, wr)
            # Vertical wire from wire_row down to road_row_B
            for wr in range(wire_row + 1, road_row_B + 1):
                if em[wr, wc]:
                    return (Tool.WIRE, wc, wr)

    # Phase 7: place zones in zone rows, every 6 cols aligned with roads
    for wc in sorted(wire_cols_present):
        if wc % 6 == 3:  # offset to center zones between road verticals
            # Top zones
            if 2 <= zone_row_T <= WORLD_H - 3 and 2 <= wc <= WORLD_W - 3:
                if not already_zone_nearby(zone_row_T, wc) and zone_area_free(zone_row_T, wc):
                    return (pick_zone(res_count, com_count, ind_count), wc, zone_row_T)
            # Bottom zones
            if 2 <= zone_row_B <= WORLD_H - 3 and 2 <= wc <= WORLD_W - 3:
                if not already_zone_nearby(zone_row_B, wc) and zone_area_free(zone_row_B, wc):
                    return (pick_zone(res_count, com_count, ind_count), wc, zone_row_B)

    # Phase 8: second tier zones when pop grows
    if obs.city_pop > 100 or obs.powered_zones > 4:
        # Build second tier roads
        for wc in sorted(wire_cols_present):
            if wc % 6 == 0:
                # Extend vertical wires to second tier roads
                for wr in range(road_row_T - 1, road_row_T2 - 1, -1):
                    if em[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                for wr in range(road_row_B + 1, road_row_B2 + 1):
                    if em[wr, wc]:
                        return (Tool.WIRE, wc, wr)

        for wc in sorted(wire_cols_present):
            if wc % 3 == 0:
                if wc not in road_T2_cols and 0 <= road_row_T2 < WORLD_H and em[road_row_T2, wc]:
                    return (Tool.ROAD, wc, road_row_T2)
                if wc not in road_B2_cols and 0 <= road_row_B2 < WORLD_H and em[road_row_B2, wc]:
                    return (Tool.ROAD, wc, road_row_B2)

        for wc in sorted(wire_cols_present):
            if wc % 6 == 3:
                if 2 <= zone_row_T2 <= WORLD_H - 3 and 2 <= wc <= WORLD_W - 3:
                    if not already_zone_nearby(zone_row_T2, wc) and zone_area_free(zone_row_T2, wc):
                        return (pick_zone(res_count, com_count, ind_count), wc, zone_row_T2)
                if 2 <= zone_row_B2 <= WORLD_H - 3 and 2 <= wc <= WORLD_W - 3:
                    if not already_zone_nearby(zone_row_B2, wc) and zone_area_free(zone_row_B2, wc):
                        return (pick_zone(res_count, com_count, ind_count), wc, zone_row_B2)

    return None

def act(obs, state):
    """
    Improved policy: Build TWO neighborhoods side by side with better zone mix.
    - Left neighborhood: centered at (40, 50) with res/com/ind mix
    - Right neighborhood: centered at (80, 50) with res/com/ind mix
    - Each has its own coal plant connected via wire spine
    - Horizontal road running through both neighborhoods
    """
    tm = obs.tile_map
    step = obs.step

    em = empty_mask(tm)
    pm = plant_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    has_plant = np.any(pm)
    res_count = int(np.sum(res_m))
    com_count = int(np.sum(com_m))
    ind_count = int(np.sum(ind_m))

    # Two neighborhood centers
    # Left: plant at (30, 50), wire spine col 33, road col 34
    # Right: plant at (75, 50), wire spine col 78, road col 79

    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    # Phase 1: Place two coal power plants
    # Left plant at x=30, y=50
    # Right plant at x=75, y=50
    plant_positions = list(zip(*np.where(pm)))
    plant_xs = [pc for (pr, pc) in plant_positions]

    left_plant_placed = any(abs(pc - 30) <= 3 and abs(pr - 50) <= 3
                            for (pr, pc) in plant_positions)
    right_plant_placed = any(abs(pc - 75) <= 3 and abs(pr - 50) <= 3
                             for (pr, pc) in plant_positions)

    if not left_plant_placed:
        return (Tool.COALPOWER, 30, 50)
    if not right_plant_placed:
        return (Tool.COALPOWER, 75, 50)

    # Phase 2: Build wire spines (vertical) for each neighborhood
    # Left spine: col 33, rows 38..62
    # Right spine: col 78, rows 38..62
    left_wire_col = 33
    right_wire_col = 78
    spine_min_row = 38
    spine_max_row = 62

    for wc in [left_wire_col, right_wire_col]:
        col_wires = [r for (r, c) in zip(*np.where(wm)) if c == wc] if np.any(wm) else []
        if not col_wires:
            # Start wire adjacent to plant
            if em[50, wc]:
                return (Tool.WIRE, wc, 50)
        else:
            min_r = min(col_wires)
            max_r = max(col_wires)
            if max_r < spine_max_row:
                nr = max_r + 1
                if 0 <= nr < WORLD_H and (em[nr, wc] or wm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_r > spine_min_row:
                nr = min_r - 1
                if 0 <= nr < WORLD_H and (em[nr, wc] or wm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # Phase 3: Build road columns adjacent to wire spines
    # Left road: col 34, Right road: col 79
    left_road_col = 34
    right_road_col = 79

    wire_rows_left = sorted([r for (r, c) in zip(*np.where(wm)) if c == left_wire_col]) if np.any(wm) else []
    wire_rows_right = sorted([r for (r, c) in zip(*np.where(wm)) if c == right_wire_col]) if np.any(wm) else []

    for (road_col, wire_rows) in [(left_road_col, wire_rows_left), (right_road_col, wire_rows_right)]:
        for r in wire_rows:
            if 0 <= r < WORLD_H and 0 <= road_col < WORLD_W:
                if not rm[r, road_col] and em[r, road_col]:
                    return (Tool.ROAD, road_col, r)

    # Phase 4: Also add lateral wire to reach zones (left zones at col 30-2=need wire at 31,32)
    # Left zones at col 27 (center), wire from col 33 need lateral at 32, 31, 30? 
    # Actually let's connect plant directly: plant at 30 center => footprint 28..32
    # wire at 33 is adjacent. Zones left of wire at col 27 (center x=27), right at col 37

    # Lateral wires: from spine to left zone area
    for r in wire_rows_left:
        for wc in [32, 31]:
            if 0 <= wc < WORLD_W and em[r, wc]:
                return (Tool.WIRE, wc, r)
    for r in wire_rows_right:
        for wc in [77, 76]:
            if 0 <= wc < WORLD_W and em[r, wc]:
                return (Tool.WIRE, wc, r)

    # Phase 5: Place zones
    # Left neighborhood: zones at col 27 (left of plant/wire) and col 37 (right of road)
    # Right neighborhood: zones at col 72 (left) and col 82 (right)
    # Rows: 40..60 step 3

    # Zone configs: (zone_col, road_col_ref, wire_col_ref, side)
    zone_configs = [
        (27, left_road_col, left_wire_col),   # left of left neighborhood
        (37, left_road_col, left_wire_col),   # right of left neighborhood
        (72, right_road_col, right_wire_col), # left of right neighborhood
        (82, right_road_col, right_wire_col), # right of right neighborhood
    ]

    res_positions = list(zip(*np.where(res_m))) if np.any(res_m) else []
    com_positions = list(zip(*np.where(com_m))) if np.any(com_m) else []
    ind_positions = list(zip(*np.where(ind_m))) if np.any(ind_m) else []

    def already_zone_nearby(zr, zc, positions):
        return any(abs(zr - pr) <= 1 and abs(zc - pc) <= 1 for (pr, pc) in positions)

    for (zc, rc, wc) in zone_configs:
        wire_rows = wire_rows_left if wc == left_wire_col else wire_rows_right
        for zr in range(41, 62, 3):
            wire_ok = any(abs(zr - wr) <= 1 for wr in wire_rows)
            road_ok = rm[zr, rc] if 0 <= zr < WORLD_H and 0 <= rc < WORLD_W else False
            if wire_ok and road_ok:
                if not already_zone_nearby(zr, zc, res_positions + com_positions + ind_positions):
                    if zone_area_free(zr, zc):
                        # Zone type: balance res/com/ind roughly 2:1:1
                        total = res_count + com_count + ind_count
                        if com_count * 2 < res_count:
                            return (Tool.COMMERCIAL, zc, zr)
                        elif ind_count * 2 < res_count:
                            return (Tool.INDUSTRIAL, zc, zr)
                        else:
                            return (Tool.RESIDENTIAL, zc, zr)

    # Phase 6: Add horizontal road connecting both neighborhoods
    # Road at row 50 from col 34 to col 79
    for rc in range(34, 80):
        if not rm[50, rc] and em[50, rc]:
            return (Tool.ROAD, rc, 50)

    # Phase 7: Also wire from left plant to right plant along row 50
    for wc in range(33, 79):
        if not wm[50, wc] and em[50, wc]:
            return (Tool.WIRE, wc, 50)

    # Phase 8: Expand zones if population growing
    if obs.city_pop > 100:
        for (zc, rc, wc) in zone_configs:
            wire_rows = wire_rows_left if wc == left_wire_col else wire_rows_right
            for zr in range(38, 64, 3):
                if zone_area_free(zr, zc):
                    if not already_zone_nearby(zr, zc, res_positions + com_positions + ind_positions):
                        wire_ok = any(abs(zr - wr) <= 1 for wr in wire_rows)
                        road_ok = rm[zr, rc] if 0 <= zr < WORLD_H else False
                        if wire_ok and road_ok:
                            return (Tool.RESIDENTIAL, zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map every step to find existing infrastructure
    - Grows power grid and roads from existing edges
    - Places zones adjacent to powered+roaded areas
    - Adapts zone mix based on current counts
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        all_zone = resm | comm | indm
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        all_zone = resm | comm | indm
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone[rr, rc]:
                        return True
        return False

    # Phase 1: place coal plant if none exists
    if not np.any(pm):
        return (Tool.COALPOWER, cx, cy)

    # Find plant centroid
    plant_rows, plant_cols = np.where(pm)
    pcx = int(np.mean(plant_cols))
    pcy = int(np.mean(plant_rows))

    # Layout: wire spine 4 right of plant, roads 4 left/right of spine
    spine_col = pcx + 4
    spine_col = max(3, min(WORLD_W - 4, spine_col))

    left_road_col = spine_col - 4
    right_road_col = spine_col + 4
    left_road_col = max(1, min(WORLD_W - 2, left_road_col))
    right_road_col = max(1, min(WORLD_W - 2, right_road_col))

    # Spine vertical range based on pop
    pop = obs.city_pop
    if pop < 100:
        half = 8
    elif pop < 300:
        half = 14
    elif pop < 700:
        half = 20
    else:
        half = 28

    spine_min = max(1, pcy - half)
    spine_max = min(WORLD_H - 2, pcy + half)

    # Phase 2: Connect wire from plant to spine
    # Find if any wire exists on spine
    spine_wires = [r for r in range(WORLD_H) if wm[r, spine_col]]

    if not spine_wires:
        # Place wire adjacent to plant toward spine
        for c in range(pcx + 3, spine_col + 1):
            if 0 <= c < WORLD_W and em[pcy, c]:
                return (Tool.WIRE, c, pcy)
        # fallback: place wire at spine center
        if em[pcy, spine_col]:
            return (Tool.WIRE, spine_col, pcy)
        return None

    spine_min_r = min(spine_wires)
    spine_max_r = max(spine_wires)

    # Phase 3: Grow wire spine downward
    if spine_max_r < spine_max:
        nr = spine_max_r + 1
        if nr < WORLD_H and not pm[nr, spine_col] and (em[nr, spine_col] or wm[nr, spine_col]):
            return (Tool.WIRE, spine_col, nr)

    # Phase 4: Grow wire spine upward
    if spine_min_r > spine_min:
        nr = spine_min_r - 1
        if nr >= 0 and not pm[nr, spine_col] and (em[nr, spine_col] or wm[nr, spine_col]):
            return (Tool.WIRE, spine_col, nr)

    # Phase 5: Build roads alongside spine - scan for gaps reactively
    for r in spine_wires:
        if 0 <= r < WORLD_H:
            if 0 <= left_road_col < WORLD_W and not rm[r, left_road_col] and em[r, left_road_col] and not pm[r, left_road_col]:
                return (Tool.ROAD, left_road_col, r)
            if 0 <= right_road_col < WORLD_W and not rm[r, right_road_col] and em[r, right_road_col] and not pm[r, right_road_col]:
                return (Tool.ROAD, right_road_col, r)

    # Phase 6: Lay lateral wires from spine toward left/right zone areas
    # Zones will sit between roads and spine; wire from spine row to zone col
    # Left zones at left_road_col - 3, right zones at right_road_col + 3
    left_zone_col = left_road_col - 3
    right_zone_col = right_road_col + 3
    left_zone_col = max(2, min(WORLD_W - 3, left_zone_col))
    right_zone_col = max(2, min(WORLD_W - 3, right_zone_col))

    # Reactive lateral wire: for each spine row, extend wire outward if needed
    for wr in spine_wires:
        # Left lateral: from spine_col-1 toward left_zone_col
        for wc in range(spine_col - 1, left_zone_col - 2, -1):
            if not (0 <= wc < WORLD_W):
                break
            if wm[wr, wc] or pm[wr, wc]:
                break  # already connected
            if rm[wr, wc]:
                break  # road blocks wire extension here (skip row)
            if em[wr, wc]:
                return (Tool.WIRE, wc, wr)
            break  # blocked

        # Right lateral: from spine_col+1 toward right_zone_col
        for wc in range(spine_col + 1, right_zone_col + 2):
            if not (0 <= wc < WORLD_W):
                break
            if wm[wr, wc] or pm[wr, wc]:
                break
            if rm[wr, wc]:
                break
            if em[wr, wc]:
                return (Tool.WIRE, wc, wr)
            break

    # Phase 7: Place zones - scan rows along spine extent
    # Zones every 3 rows, try outer columns (beyond roads) first
    left_road_set = set(r for r in range(WORLD_H) if rm[r, left_road_col])
    right_road_set = set(r for r in range(WORLD_H) if rm[r, right_road_col])
    spine_set = set(spine_wires)

    for zr in range(spine_min + 1, spine_max, 3):
        wire_near = any(abs(zr - wr) <= 1 for wr in spine_set)
        if not wire_near:
            continue

        # Check road access
        left_road_near = any(abs(zr - rr) <= 1 for rr in left_road_set)
        right_road_near = any(abs(zr - rr) <= 1 for rr in right_road_set)

        # Inner left zone (between left road and spine)
        inner_left = spine_col - 2
        inner_left = max(2, min(WORLD_W - 3, inner_left))
        if left_road_near and not zone_already_there(zr, inner_left) and zone_area_ok(zr, inner_left):
            return (pick_tool(), inner_left, zr)

        # Inner right zone (between spine and right road)
        inner_right = spine_col + 2
        inner_right = max(2, min(WORLD_W - 3, inner_right))
        if right_road_near and not zone_already_there(zr, inner_right) and zone_area_ok(zr, inner_right):
            return (pick_tool(), inner_right, zr)

        # Outer left zone (left of left road)
        if left_road_near:
            if not zone_already_there(zr, left_zone_col) and zone_area_ok(zr, left_zone_col):
                # Check wire coverage
                wc0, wc1 = max(0, left_zone_col - 4), min(WORLD_W, left_zone_col + 5)
                wr0, wr1 = max(0, zr - 4), min(WORLD_H, zr + 5)
                if np.any(wm[wr0:wr1, wc0:wc1]) or np.any(pm[wr0:wr1, wc0:wc1]):
                    return (pick_tool(), left_zone_col, zr)

        # Outer right zone (right of right road)
        if right_road_near:
            if not zone_already_there(zr, right_zone_col) and zone_area_ok(zr, right_zone_col):
                wc0, wc1 = max(0, right_zone_col - 4), min(WORLD_W, right_zone_col + 5)
                wr0, wr1 = max(0, zr - 4), min(WORLD_H, zr + 5)
                if np.any(wm[wr0:wr1, wc0:wc1]) or np.any(pm[wr0:wr1, wc0:wc1]):
                    return (pick_tool(), right_zone_col, zr)

    # Phase 8: Second coal plant if lots of zones but low powered
    plant_tiles = int(np.sum(pm))
    if total_zones > 10 and obs.powered_zones < total_zones // 3 and plant_tiles < 32:
        # Place second plant further along
        px2, py2 = pcx + 22, pcy
        px2 = max(4, min(WORLD_W - 5, px2))
        py2 = max(4, min(WORLD_H - 5, py2))
        if np.all(em[py2-1:py2+2, px2-1:px2+2]):
            return (Tool.COALPOWER, px2, py2)

    # Phase 9: Add horizontal road connections at extremes of spine for extra access
    if pop > 200 and spine_wires:
        for h_row in [spine_min_r, spine_max_r]:
            if 0 <= h_row < WORLD_H:
                for rc in range(max(0, left_road_col - 1), min(WORLD_W, right_road_col + 2)):
                    if em[h_row, rc] and not pm[h_row, rc] and not wm[h_row, rc] and not rm[h_row, rc]:
                        return (Tool.ROAD, rc, h_row)

    # Phase 10: If spine fully built and zones placed, try to extend further
    if pop > 500:
        extended_max = min(WORLD_H - 2, spine_max + 6)
        extended_min = max(1, spine_min - 6)
        if spine_max_r < extended_max:
            nr = spine_max_r + 1
            if nr < WORLD_H and not pm[nr, spine_col] and em[nr, spine_col]:
                return (Tool.WIRE, spine_col, nr)
        if spine_min_r > extended_min:
            nr = spine_min_r - 1
            if nr >= 0 and not pm[nr, spine_col] and em[nr, spine_col]:
                return (Tool.WIRE, spine_col, nr)

    return None

def act(obs, state):
    """
    Grid-based city layout:
    - Two power plants (one left, one right)
    - Horizontal wire backbone connecting them
    - Multiple vertical road columns
    - Zones placed in a grid pattern with mixed RCI
    - Expands in phases based on population
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    # Use state to track build phase and position
    if 'plan' not in state:
        state['plan'] = []
        state['plan_idx'] = 0

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool(total, com_c, ind_c):
        if total == 0:
            return Tool.RESIDENTIAL
        if com_c / (total + 1) < 0.30:
            return Tool.COMMERCIAL
        if ind_c / (total + 1) < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    all_zone_mask = resm | comm | indm

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_present(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=5):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    # Layout constants - horizontal layout
    # Power plant left side
    p1x, p1y = 20, 50   # left plant center
    p2x, p2y = 90, 50   # right plant center
    wire_row = 50        # horizontal wire backbone row

    # Road columns spaced across the map
    road_cols = [28, 40, 52, 64, 76, 88]

    # Horizontal roads at regular intervals
    road_rows = [42, 46, 54, 58]

    # Zone rows (above and below wire backbone)
    zone_row_sets = [44, 48, 52, 56]
    # Zone columns between road columns
    zone_col_sets = [34, 46, 58, 70, 82]

    # Phase 1: Place left power plant
    if not np.any(pm):
        return (Tool.COALPOWER, p1x, p1y)

    plant_rows, plant_cols = np.where(pm)
    plant_count_tiles = len(plant_rows)

    # Place right power plant if we have enough population and only one plant
    if obs.city_pop > 200 and plant_count_tiles < 9:
        if em[p2y, p2x]:
            return (Tool.COALPOWER, p2x, p2y)

    # Phase 2: Build horizontal wire backbone
    # Connect from left plant to right plant along wire_row
    # Left plant is at ~(20,50), its right edge is at col 21
    wire_start = p1x + 2  # just right of plant
    wire_end = p2x - 2    # just left of right plant

    for wc in range(wire_start, wire_end + 1):
        if 0 <= wc < WORLD_W:
            if not wm[wire_row, wc] and not pm[wire_row, wc]:
                if em[wire_row, wc] or rm[wire_row, wc]:
                    return (Tool.WIRE, wc, wire_row)

    # Phase 3: Build vertical road columns
    road_row_min = 38
    road_row_max = 62
    for rc in road_cols:
        for rr in range(road_row_min, road_row_max + 1):
            if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                if not rm[rr, rc] and em[rr, rc] and not pm[rr, rc]:
                    return (Tool.ROAD, rc, rr)

    # Phase 4: Build horizontal road segments connecting vertical roads
    for rr in road_rows:
        for rc in range(road_cols[0] - 1, road_cols[-1] + 2):
            if 0 <= rc < WORLD_W and 0 <= rr < WORLD_H:
                if not rm[rr, rc] and em[rr, rc] and not pm[rr, rc]:
                    return (Tool.ROAD, rc, rr)

    # Phase 5: Vertical wires from backbone down/up to zone areas
    wire_col_branches = [34, 46, 58, 70, 82]
    for wc in wire_col_branches:
        for wr in range(wire_row - 8, wire_row + 9):
            if 0 <= wr < WORLD_H and 0 <= wc < WORLD_W:
                if not wm[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                    if em[wr, wc]:
                        return (Tool.WIRE, wc, wr)

    # Phase 6: Place zones in grid pattern
    zone_rows_list = [43, 47, 51, 55, 59]

    for zr in zone_rows_list:
        for zc in zone_col_sets:
            if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc, 6) and has_road_nearby(zr, zc, 5):
                    return (pick_tool(total_zones, com_count, ind_count), zc, zr)

    # Phase 7: Second row of zones further out
    if obs.city_pop > 150:
        outer_zone_rows = [37, 63]
        for zr in outer_zone_rows:
            for zc in zone_col_sets:
                if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                    if has_wire_nearby(zr, zc, 8) and has_road_nearby(zr, zc, 6):
                        return (pick_tool(total_zones, com_count, ind_count), zc, zr)

    # Phase 8: Extend roads further vertically
    if obs.city_pop > 300:
        ext_road_min = 32
        ext_road_max = 68
        for rc in road_cols:
            for rr in list(range(ext_road_min, road_row_min)) + list(range(road_row_max + 1, ext_road_max + 1)):
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if not rm[rr, rc] and em[rr, rc] and not pm[rr, rc]:
                        return (Tool.ROAD, rc, rr)

    # Phase 9: Add more zones further out
    if obs.city_pop > 400:
        far_zone_cols = [28, 40, 52, 64, 76]
        for zr in [34, 40, 44, 48, 52, 56, 60, 66]:
            for zc in far_zone_cols:
                if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                    if has_wire_nearby(zr, zc, 10) and has_road_nearby(zr, zc, 5):
                        return (pick_tool(total_zones, com_count, ind_count), zc, zr)

    # Phase 10: Third power plant if needed
    if obs.city_pop > 600 and plant_count_tiles < 18:
        p3x, p3y = 55, 30
        if em[p3y, p3x]:
            return (Tool.COALPOWER, p3x, p3y)

    # Phase 11: Wire from third plant
    if obs.city_pop > 600:
        # Connect third plant down to wire_row
        for wr in range(33, wire_row):
            if not wm[wr, 55] and not pm[wr, 55] and em[wr, 55]:
                return (Tool.WIRE, 55, wr)

    # Phase 12: More zones in upper area if pop high
    if obs.city_pop > 600:
        upper_zone_rows = [28, 32, 36]
        upper_zone_cols = [46, 55, 64]
        for zr in upper_zone_rows:
            for zc in upper_zone_cols:
                if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                    if has_wire_nearby(zr, zc, 8) and has_road_nearby(zr, zc, 6):
                        return (pick_tool(total_zones, com_count, ind_count), zc, zr)

    return None

def act(obs, state):
    """
    Hybrid policy:
    - Two coal power plants (one primary, one secondary)
    - Vertical wire spine per plant (proven from Parent B)
    - Bilateral road columns adjacent to each wire spine
    - Zones placed on both sides of roads
    - Lateral wires and roads to reach zone columns
    - Services for happiness
    - Progressive expansion based on population
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Power plant positions
    P1X, P1Y = 45, 50
    P2X, P2Y = 70, 50
    P3X, P3Y = 95, 50

    plant_ys, plant_xs = np.where(pm)
    has_plant1 = any(abs(px_ - P1X) <= 5 and abs(py_ - P1Y) <= 5
                     for py_, px_ in zip(plant_ys.tolist(), plant_xs.tolist()))
    has_plant2 = any(abs(px_ - P2X) <= 5 and abs(py_ - P2Y) <= 5
                     for py_, px_ in zip(plant_ys.tolist(), plant_xs.tolist()))
    has_plant3 = any(abs(px_ - P3X) <= 5 and abs(py_ - P3Y) <= 5
                     for py_, px_ in zip(plant_ys.tolist(), plant_xs.tolist()))

    # Phase 1: Place primary plant
    if not has_plant1:
        return (Tool.COALPOWER, P1X, P1Y)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))

    def pick_zone(zr):
        if ind_count == 0 or (ind_count * 4 < res_count and zr >= P1Y):
            return Tool.INDUSTRIAL
        if com_count == 0 or com_count * 4 < res_count:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not in_bounds(rc, rr):
                    return False
                if not bool(em[rr, rc]):
                    return False
        return True

    def build_corridor(wire_col, plant_cy, cy_ref):
        """Build a vertical corridor: wire spine, bilateral roads, zones, lateral connections."""
        road_col_L = wire_col - 1
        road_col_R = wire_col + 1
        # Zone columns: 3 and 6 tiles away on each side
        zone_cols_L = [wire_col - 4, wire_col - 8]
        zone_cols_R = [wire_col + 4, wire_col + 8]

        # Vertical span grows with pop
        base_span = 15
        extra_span = min(35, obs.city_pop // 15)
        target_span = base_span + extra_span
        tmin = max(2, cy_ref - target_span)
        tmax = min(WORLD_H - 3, cy_ref + target_span)

        wire_positions = set(zip(*np.where(wm))) if np.any(wm) else set()
        road_positions = set(zip(*np.where(rm))) if np.any(rm) else set()

        wire_rows_in_col = sorted(r for (r, c) in wire_positions if c == wire_col)

        # Step 1: Start wire spine at plant_cy
        if not wire_rows_in_col:
            if in_bounds(wire_col, plant_cy) and bool(em[plant_cy, wire_col]):
                return (Tool.WIRE, wire_col, plant_cy)
            # Try adjacent rows
            for dy in range(1, 5):
                for ny in [plant_cy + dy, plant_cy - dy]:
                    if in_bounds(wire_col, ny) and bool(em[ny, wire_col]):
                        return (Tool.WIRE, wire_col, ny)
            return None

        # Step 2: Extend wire spine up and down
        min_wr = min(wire_rows_in_col)
        max_wr = max(wire_rows_in_col)
        if max_wr < tmax:
            nr = max_wr + 1
            if in_bounds(wire_col, nr) and bool(em[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        if min_wr > tmin:
            nr = min_wr - 1
            if in_bounds(wire_col, nr) and bool(em[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

        wire_rows_set = set(wire_rows_in_col)
        road_rows_L_set = set(r for (r, c) in road_positions if c == road_col_L)
        road_rows_R_set = set(r for (r, c) in road_positions if c == road_col_R)

        # Step 3: Build roads adjacent to wire spine
        for wr in wire_rows_in_col:
            if wr not in road_rows_L_set and in_bounds(road_col_L, wr) and bool(em[wr, road_col_L]):
                return (Tool.ROAD, road_col_L, wr)
            if wr not in road_rows_R_set and in_bounds(road_col_R, wr) and bool(em[wr, road_col_R]):
                return (Tool.ROAD, road_col_R, wr)

        # Step 4: Lateral wires to left zone columns
        for wr in wire_rows_in_col:
            if wr < 2 or wr >= WORLD_H - 2:
                continue
            for wc in range(wire_col - 1, max(wire_col - 10, 0) - 1, -1):
                if in_bounds(wc, wr):
                    if bool(wm[wr, wc]) or bool(pm[wr, wc]):
                        break
                    if bool(rm[wr, wc]):
                        break
                    if bool(em[wr, wc]):
                        return (Tool.WIRE, wc, wr)
                    break

        # Step 5: Lateral roads to right zone columns
        for wr in wire_rows_in_col:
            if wr < 2 or wr >= WORLD_H - 2:
                continue
            for rc in range(road_col_R + 1, min(wire_col + 10, WORLD_W)):
                if in_bounds(rc, wr):
                    if bool(rm[wr, rc]) or bool(pm[wr, rc]):
                        break
                    if bool(wm[wr, rc]):
                        break
                    if bool(em[wr, rc]):
                        return (Tool.ROAD, rc, wr)
                    break

        # Step 6: Place zones
        for wr in wire_rows_in_col:
            if wr < 2 or wr >= WORLD_H - 2:
                continue
            road_L_nearby = any(abs(wr - rr) <= 1 for rr in road_rows_L_set)
            road_R_nearby = any(abs(wr - rr) <= 1 for rr in road_rows_R_set)

            # Check lateral wire/road reach
            # Left zones: need wire to reach
            for zc in zone_cols_L:
                if not in_bounds(zc, wr) or zc < 1 or zc >= WORLD_W - 1:
                    continue
                # Check if wire connects to this zone column row
                wire_reaches = any(bool(wm[wr, wc]) for wc in range(max(0, zc - 1), min(WORLD_W, wire_col)))
                if wire_reaches and zone_area_free(wr, zc):
                    return (pick_zone(wr), zc, wr)

            for zc in zone_cols_R:
                if not in_bounds(zc, wr) or zc < 1 or zc >= WORLD_W - 1:
                    continue
                road_reaches = any(bool(rm[wr, rc]) for rc in range(wire_col, min(WORLD_W, zc + 2)))
                if road_reaches and zone_area_free(wr, zc):
                    return (pick_zone(wr), zc, wr)

        return None

    # Build corridor 1
    wire_col1 = P1X + 4  # = 49
    action = build_corridor(wire_col1, P1Y, P1Y)
    if action is not None:
        return action

    # Phase 2: Second plant and corridor
    if obs.city_pop > 80:
        if not has_plant2:
            return (Tool.COALPOWER, P2X, P2Y)

        wire_col2 = P2X + 4  # = 74
        # Connect plant2 to its wire spine
        wire_positions2 = set(zip(*np.where(wm))) if np.any(wm) else set()
        wire_rows2 = sorted(r for (r, c) in wire_positions2 if c == wire_col2)
        if not wire_rows2:
            for wc in range(P2X + 2, wire_col2 + 1):
                if in_bounds(wc, P2Y) and bool(em[P2Y, wc]) and not bool(pm[P2Y, wc]):
                    return (Tool.WIRE, wc, P2Y)

        action2 = build_corridor(wire_col2, P2Y, P2Y)
        if action2 is not None:
            return action2

    # Phase 3: Third plant and corridor
    if obs.city_pop > 300:
        if not has_plant3:
            return (Tool.COALPOWER, P3X, P3Y)

        wire_col3 = P3X + 4  # = 99
        wire_positions3 = set(zip(*np.where(wm))) if np.any(wm) else set()
        wire_rows3 = sorted(r for (r, c) in wire_positions3 if c == wire_col3)
        if not wire_rows3:
            for wc in range(P3X + 2, wire_col3 + 1):
                if in_bounds(wc, P3Y) and bool(em[P3Y, wc]) and not bool(pm[P3Y, wc]):
                    return (Tool.WIRE, wc, P3Y)

        action3 = build_corridor(wire_col3, P3Y, P3Y)
        if action3 is not None:
            return action3

    # Left corridor: place a plant on the left side too
    if obs.city_pop > 200:
        P4X, P4Y = 20, 50
        has_plant4 = any(abs(px_ - P4X) <= 5 and abs(py_ - P4Y) <= 5
                         for py_, px_ in zip(plant_ys.tolist(), plant_xs.tolist()))
        if not has_plant4:
            return (Tool.COALPOWER, P4X, P4Y)
        wire_col4 = P4X + 4  # = 24
        wire_positions4 = set(zip(*np.where(wm))) if np.any(wm) else set()
        wire_rows4 = sorted(r for (r, c) in wire_positions4 if c == wire_col4)
        if not wire_rows4:
            for wc in range(P4X + 2, wire_col4 + 1):
                if in_bounds(wc, P4Y) and bool(em[P4Y, wc]) and not bool(pm[P4Y, wc]):
                    return (Tool.WIRE, wc, P4Y)
        action4 = build_corridor(wire_col4, P4Y, P4Y)
        if action4 is not None:
            return action4

    # Services
    if obs.city_pop > 400:
        fx, fy = wire_col1 + 6, P1Y - 10
        if in_bounds(fx, fy) and zone_area_free(fy, fx):
            return (Tool.FIRESTATION, fx, fy)

    if obs.city_pop > 600:
        px2, py2 = wire_col1 - 6, P1Y + 10
        if in_bounds(px2, py2) and zone_area_free(py2, px2):
            return (Tool.POLICESTATION, px2, py2)

    if obs.city_pop > 800:
        fx2, fy2 = wire_col1 + 10, P1Y + 15
        if in_bounds(fx2, fy2) and zone_area_free(fy2, fx2):
            return (Tool.FIRESTATION, fx2, fy2)

    # Fallback: extend existing roads
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (obs.step * 13) % max(len(road_xs), 1)
        rx_s, ry_s = int(road_xs[step_k]), int(road_ys[step_k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx_s + dx2, ry_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wires
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        step_k2 = (obs.step * 7) % max(len(wire_xs), 1)
        wx_s, wy_s = int(wire_xs[step_k2]), int(wire_ys[step_k2])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = wx_s + dx2, wy_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads the map each step and places the next thing
    based on what actually exists.

    Strategy:
    - Place coal power plant near center-left if none exists.
    - Grow wire rightward and vertically from plant to form a horizontal+vertical grid.
    - Build road column(s) parallel to wire.
    - Place zones adjacent to roads, alternating RES/COM/IND.
    - Reactively extend infrastructure as zones fill up.
    """
    tm = obs.tile_map
    step = obs.step

    # Map center
    cx, cy = WORLD_W // 2, WORLD_H // 2

    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    has_plant = np.any(pm)
    has_wire = np.any(wm)
    has_road = np.any(rm)

    # Phase 1: Place coal power plant if none exists
    # Place at (cx-8, cy) so we have room to wire rightward
    if not has_plant:
        return (Tool.COALPOWER, cx - 8, cy)

    # Find plant center (use centroid of plant tiles)
    plant_ys, plant_xs = np.where(pm)
    if len(plant_xs) == 0:
        return None
    plant_cx = int(np.mean(plant_xs))
    plant_cy = int(np.mean(plant_ys))

    # Wire spine: horizontal row at plant_cy, then vertical column
    # Wire goes right from plant to a vertical spine column
    spine_x = plant_cx + 5  # vertical wire spine at this x

    # Step A: lay horizontal wire from plant rightward to spine_x
    for wx in range(plant_cx + 2, spine_x + 1):
        if 0 <= wx < WORLD_W and 0 <= plant_cy < WORLD_H:
            if not wm[plant_cy, wx] and (em[plant_cy, wx] or False):
                return (Tool.WIRE, wx, plant_cy)

    # Step B: grow vertical wire spine from plant_cy up and down
    wire_spine_rows = [r for r in range(WORLD_H) if wm[r, spine_x]]

    if not wire_spine_rows:
        # Start spine
        if 0 <= spine_x < WORLD_W and em[plant_cy, spine_x]:
            return (Tool.WIRE, spine_x, plant_cy)
        elif 0 <= spine_x < WORLD_W:
            return (Tool.WIRE, spine_x, plant_cy)
    else:
        min_row = min(wire_spine_rows)
        max_row = max(wire_spine_rows)
        target_min = max(0, cy - 15)
        target_max = min(WORLD_H - 1, cy + 15)

        # Extend downward
        if max_row < target_max:
            nr = max_row + 1
            if 0 <= nr < WORLD_H:
                return (Tool.WIRE, spine_x, nr)
        # Extend upward
        if min_row > target_min:
            nr = min_row - 1
            if 0 <= nr >= 0:
                return (Tool.WIRE, spine_x, nr)

    # Step C: lay road column parallel to wire spine (one tile to the right)
    road_col = spine_x + 2
    wire_spine_rows = sorted([r for r in range(WORLD_H) if wm[r, spine_x]])

    if wire_spine_rows:
        for wr in wire_spine_rows:
            if 0 <= road_col < WORLD_W and 0 <= wr < WORLD_H:
                if not rm[wr, road_col]:
                    return (Tool.ROAD, road_col, wr)

    # Step D: lay a second road column to the left of spine for left-side zones
    road_col_left = spine_x - 2
    if wire_spine_rows:
        for wr in wire_spine_rows:
            if 0 <= road_col_left < WORLD_W and 0 <= wr < WORLD_H:
                if not rm[wr, road_col_left]:
                    return (Tool.ROAD, road_col_left, wr)

    # Helper: check if 3x3 zone area is placeable
    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    res_count = int(np.sum(res_mask(tm)))
    com_count = int(np.sum(com_mask(tm)))
    ind_count = int(np.sum(ind_mask(tm)))

    # Step E: place zones adjacent to roads, reactively
    # Right zones: center at road_col + 3
    # Left zones: center at road_col_left - 3
    zone_col_right = road_col + 3
    zone_col_left = road_col_left - 3

    # Only place zones where wire is reachable (within 2 tiles of spine)
    # and road exists at that row
    road_right_rows = [r for r in range(WORLD_H) if rm[r, road_col]]
    road_left_rows = [r for r in range(WORLD_H) if rm[r, road_col_left]]

    # Combine candidate zone placements
    candidates = []
    for zr in road_right_rows:
        # Zone center 3 rows spaced
        for zr_center in range(zr - 1, zr + 2):
            if 0 < zr_center < WORLD_H and abs(zr_center % 3) == 0:
                candidates.append((zr_center, zone_col_right))
    for zr in road_left_rows:
        for zr_center in range(zr - 1, zr + 2):
            if 0 < zr_center < WORLD_H and abs(zr_center % 3) == 0:
                candidates.append((zr_center, zone_col_left))

    # Deduplicate
    seen = set()
    unique_candidates = []
    for c in candidates:
        if c not in seen:
            seen.add(c)
            unique_candidates.append(c)

    # Check for existing zones nearby
    res_pos = list(zip(*np.where(res_mask(tm)))) if res_count > 0 else []
    com_pos = list(zip(*np.where(com_mask(tm)))) if com_count > 0 else []
    ind_pos = list(zip(*np.where(ind_mask(tm)))) if ind_count > 0 else []
    all_zone_pos = res_pos + com_pos + ind_pos

    for (zr, zc) in unique_candidates:
        if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
            # Check not already a zone within 2 tiles
            too_close = any(abs(zr - pr) <= 2 and abs(zc - pc) <= 2
                           for (pr, pc) in all_zone_pos)
            if not too_close and zone_area_free(zr, zc):
                # Assign type based on ratio
                total = res_count + com_count + ind_count + 1
                if com_count / total < 0.2:
                    return (Tool.COMMERCIAL, zc, zr)
                elif ind_count / total < 0.2:
                    return (Tool.INDUSTRIAL, zc, zr)
                else:
                    return (Tool.RESIDENTIAL, zc, zr)

    # Step F: extend wire laterally to reach left zone column if needed
    # Wire from spine_x leftward to cover road_col_left
    if wire_spine_rows:
        for wr in wire_spine_rows:
            for wx in range(spine_x - 1, road_col_left - 1, -1):
                if 0 <= wx < WORLD_W and 0 <= wr < WORLD_H:
                    if not wm[wr, wx] and em[wr, wx]:
                        return (Tool.WIRE, wx, wr)

    # Step G: if we have good population, expand the zone range
    if obs.city_pop > 300:
        extra_rows = list(range(cy - 20, cy + 21, 3))
        for zr in extra_rows:
            for zc in [zone_col_right, zone_col_left]:
                if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                    too_close = any(abs(zr - pr) <= 2 and abs(zc - pc) <= 2
                                   for (pr, pc) in all_zone_pos)
                    if not too_close and zone_area_free(zr, zc):
                        return (Tool.RESIDENTIAL, zc, zr)

    return None

def act(obs, state):
    """
    Combined policy: compact corridor with wire spine, bilateral roads,
    zones on both sides, expanding coverage based on population.

    Key ideas from Parent A: vertical wire spine, bilateral zone placement,
    phased expansion, lateral wires for left zones.
    Key ideas from Parent B: roads on BOTH sides of wire spine (left and right),
    better zone distribution, reactive gap-filling.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Phase 1: Place coal power plant
    if not np.any(pm):
        return (Tool.COALPOWER, cx - 10, cy)

    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Layout: wire spine, roads on both sides, zones on both sides
    wire_col = plant_cx + 3
    road_col_r = wire_col + 1   # road immediately right of wire
    road_col_l = wire_col - 1   # road immediately left of wire
    zone_col_r = road_col_r + 3  # zones right of right road
    zone_col_l = road_col_l - 3  # zones left of left road

    # Clamp all columns
    wire_col = max(2, min(WORLD_W - 3, wire_col))
    road_col_r = max(2, min(WORLD_W - 3, road_col_r))
    road_col_l = max(2, min(WORLD_W - 3, road_col_l))
    zone_col_r = max(2, min(WORLD_W - 3, zone_col_r))
    zone_col_l = max(2, min(WORLD_W - 3, zone_col_l))

    # Vertical extent of spine based on population
    if obs.city_pop < 100:
        spine_extent = 8
    elif obs.city_pop < 300:
        spine_extent = 14
    elif obs.city_pop < 600:
        spine_extent = 22
    else:
        spine_extent = 30

    target_min = max(2, cy - spine_extent)
    target_max = min(WORLD_H - 3, cy + spine_extent)

    wire_rows = sorted(r for r in range(WORLD_H) if wm[r, wire_col])
    road_rows_r = set(r for r in range(WORLD_H) if rm[r, road_col_r])
    road_rows_l = set(r for r in range(WORLD_H) if rm[r, road_col_l])

    # Phase 2: Start wire adjacent to plant
    if not wire_rows:
        for dy in range(0, 6):
            for nr in [plant_cy + dy, plant_cy - dy]:
                if 0 <= nr < WORLD_H and 0 <= wire_col < WORLD_W:
                    if em[nr, wire_col] or wm[nr, wire_col]:
                        return (Tool.WIRE, wire_col, nr)
        return None

    min_wr = min(wire_rows)
    max_wr = max(wire_rows)

    # Phase 3: Extend wire spine downward
    if max_wr < target_max:
        nr = max_wr + 1
        if nr < WORLD_H and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Phase 4: Extend wire spine upward
    if min_wr > target_min:
        nr = min_wr - 1
        if nr >= 0 and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Phase 5: Build BOTH road columns along wire spine
    for wr in wire_rows:
        # Right road
        if wr not in road_rows_r and 0 <= road_col_r < WORLD_W:
            if em[wr, road_col_r]:
                return (Tool.ROAD, road_col_r, wr)
        # Left road
        if wr not in road_rows_l and road_col_l >= 0:
            if em[wr, road_col_l]:
                return (Tool.ROAD, road_col_l, wr)

    # Helper functions
    all_zone_mask = resm | comm | indm

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Phase 6: Place zones on both sides
    zone_rows_list = list(range(max(2, target_min), min(WORLD_H - 2, target_max + 1), 3))

    for zr in zone_rows_list:
        wire_near = any(abs(zr - wr) <= 2 for wr in wire_rows)
        road_near_r = any(abs(zr - rr) <= 2 for rr in road_rows_r)
        road_near_l = any(abs(zr - rr) <= 2 for rr in road_rows_l)

        if not wire_near:
            continue

        # Right zones (need right road)
        if road_near_r:
            zc = zone_col_r
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                return (pick_tool(), zc, zr)

        # Left zones (need left road)
        if road_near_l:
            zc = zone_col_l
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                return (pick_tool(), zc, zr)

    # Phase 7: Lateral roads to reach zone columns
    for wr in wire_rows:
        if wr in road_rows_r:
            # Extend road rightward to zone column
            for rc in range(road_col_r + 1, zone_col_r + 2):
                if 0 <= rc < WORLD_W:
                    if rm[wr, rc]:
                        break
                    if em[wr, rc] and not pm[wr, rc]:
                        return (Tool.ROAD, rc, wr)
                    elif not em[wr, rc]:
                        break
        if wr in road_rows_l:
            # Extend road leftward to zone column
            for rc in range(road_col_l - 1, zone_col_l - 2, -1):
                if 0 <= rc < WORLD_W:
                    if rm[wr, rc]:
                        break
                    if em[wr, rc] and not pm[wr, rc]:
                        return (Tool.ROAD, rc, wr)
                    elif not em[wr, rc]:
                        break

    # Phase 8: Second coal plant when needed
    if obs.city_pop > 400 and int(np.sum(pm)) < 9:
        px2, py2 = plant_cx + 20, plant_cy
        if 2 <= py2 <= WORLD_H - 3 and 2 <= px2 <= WORLD_W - 3:
            area_ok = True
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    rr, rc = py2 + dr, px2 + dc
                    if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                        if not em[rr, rc]:
                            area_ok = False
            if area_ok:
                return (Tool.COALPOWER, px2, py2)

    # Phase 9: Expand to second cluster right side when population large
    if obs.city_pop > 300:
        wire_col2 = zone_col_r + 5
        wire_col2 = max(2, min(WORLD_W - 3, wire_col2))
        road_col2r = wire_col2 + 1
        zone_col2r = road_col2r + 3
        wire_col2 = max(2, min(WORLD_W - 3, wire_col2))
        road_col2r = max(2, min(WORLD_W - 3, road_col2r))
        zone_col2r = max(2, min(WORLD_W - 3, zone_col2r))

        wire_rows2 = sorted(r for r in range(WORLD_H) if wm[r, wire_col2])
        road_rows2r = set(r for r in range(WORLD_H) if rm[r, road_col2r])

        if not wire_rows2:
            # Horizontal wire connection from main spine at cy
            for wc in range(wire_col + 1, wire_col2 + 1):
                if 0 <= wc < WORLD_W and em[cy, wc] and not rm[cy, wc]:
                    return (Tool.WIRE, wc, cy)
        else:
            min_wr2 = min(wire_rows2)
            max_wr2 = max(wire_rows2)
            tmax2 = min(WORLD_H - 3, cy + spine_extent)
            tmin2 = max(2, cy - spine_extent)

            if max_wr2 < tmax2:
                nr = max_wr2 + 1
                if 0 <= nr < WORLD_H and (em[nr, wire_col2] or wm[nr, wire_col2]):
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > tmin2:
                nr = min_wr2 - 1
                if 0 <= nr < WORLD_H and (em[nr, wire_col2] or wm[nr, wire_col2]):
                    return (Tool.WIRE, wire_col2, nr)

            # Road along second spine
            for wr in wire_rows2:
                if wr not in road_rows2r and 0 <= road_col2r < WORLD_W:
                    if em[wr, road_col2r]:
                        return (Tool.ROAD, road_col2r, wr)

            # Zones for second cluster
            road_rows2r_list = sorted(road_rows2r)
            for zr in wire_rows2:
                wire_near2 = any(abs(zr - wr) <= 2 for wr in wire_rows2)
                road_near2 = any(abs(zr - rr) <= 2 for rr in road_rows2r_list)
                if wire_near2 and road_near2:
                    zc = zone_col2r
                    if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                        return (pick_tool(), zc, zr)

            # Lateral roads to second zone column
            for wr in wire_rows2:
                if wr in road_rows2r:
                    for rc in range(road_col2r + 1, zone_col2r + 2):
                        if 0 <= rc < WORLD_W:
                            if rm[wr, rc]:
                                break
                            if em[wr, rc] and not pm[wr, rc]:
                                return (Tool.ROAD, rc, wr)
                            elif not em[wr, rc]:
                                break

    # Phase 10: Fill any missing road segments (gap filling)
    for wr in wire_rows:
        if wr not in road_rows_r and 0 <= road_col_r < WORLD_W:
            if em[wr, road_col_r]:
                return (Tool.ROAD, road_col_r, wr)
        if wr not in road_rows_l and road_col_l >= 0:
            if em[wr, road_col_l]:
                return (Tool.ROAD, road_col_l, wr)

    return None

def act(obs, state):
    """
    Closed-loop city builder: each step reads the map and decides the next placement
    based on current state of infrastructure and zones.
    """
    tm = obs.tile_map
    emp = empty_mask(tm)
    res = res_mask(tm)
    com = com_mask(tm)
    ind = ind_mask(tm)
    road = road_mask(tm)
    wire = wire_mask(tm)
    plant = plant_mask(tm)
    any_zone = res | com | ind

    # Phase tracking
    if "phase" not in state:
        state["phase"] = 0
        state["step_in_phase"] = 0
        # Center of the map
        state["cx"] = WORLD_W // 2
        state["cy"] = WORLD_H // 2

    cx = state["cx"]
    cy = state["cy"]
    step = state["step_in_phase"]
    state["step_in_phase"] += 1

    # ---- PHASE 0: Place coal plant if no plant exists ----
    if state["phase"] == 0:
        if not plant.any():
            # Place coal plant at center
            return (Tool.COALPOWER, cx, cy)
        else:
            state["phase"] = 1
            state["step_in_phase"] = 0

    # ---- PHASE 1: Extend wire from plant outward (vertical spine) ----
    if state["phase"] == 1:
        # Find plant location
        plant_ys, plant_xs = np.where(plant)
        if len(plant_xs) == 0:
            state["phase"] = 0
            return (Tool.COALPOWER, cx, cy)
        px, py = int(plant_xs[0]), int(plant_ys[0])

        # Wire spine: extend vertically from plant up to 18 tiles
        # Check which wire tiles are missing along the spine
        for dy in range(-18, 19):
            wy = py + dy
            if wy < 1 or wy > 98:
                continue
            if not wire[wy, px] and not plant[wy, px]:
                return (Tool.WIRE, px, wy)

        # Also wire horizontally a bit from plant
        for dx in range(-2, 3):
            wx = px + dx
            if wx < 1 or wx > 118:
                continue
            if not wire[py, wx] and not plant[py, wx]:
                return (Tool.WIRE, wx, py)

        state["phase"] = 2
        state["step_in_phase"] = 0

    # ---- PHASE 2: Lay road spine adjacent to wire spine ----
    if state["phase"] == 2:
        plant_ys, plant_xs = np.where(plant)
        if len(plant_xs) == 0:
            state["phase"] = 0
            return None
        px, py = int(plant_xs[0]), int(plant_ys[0])

        # Road column to the right of wire spine
        for dy in range(-18, 19):
            ry = py + dy
            if ry < 1 or ry > 98:
                continue
            rx = px + 1
            if rx > 118:
                continue
            if not road[ry, rx] and not plant[ry, rx]:
                return (Tool.ROAD, rx, ry)

        # Road column to the left of wire spine
        for dy in range(-18, 19):
            ry = py + dy
            if ry < 1 or ry > 98:
                continue
            rx = px - 1
            if rx < 1:
                continue
            if not road[ry, rx] and not plant[ry, rx]:
                return (Tool.ROAD, rx, ry)

        # Horizontal road through center
        for dx in range(-8, 10):
            rx = px + dx
            if rx < 1 or rx > 118:
                continue
            if not road[py, rx] and not plant[py, rx]:
                return (Tool.ROAD, rx, py)

        state["phase"] = 3
        state["step_in_phase"] = 0

    # ---- PHASE 3: Reactive zone placement ----
    # Find empty tiles near roads AND near wire (powered)
    def neighbor_mask(mask, dist=1):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-dist, dist+1):
            for dx in range(-dist, dist+1):
                if dy == 0 and dx == 0:
                    continue
                sy = slice(max(0, -dy), min(WORLD_H, WORLD_H-dy))
                sx = slice(max(0, -dx), min(WORLD_W, WORLD_W-dx))
                dy_ = slice(max(0, dy), min(WORLD_H, WORLD_H+dy))
                dx_ = slice(max(0, dx), min(WORLD_W, WORLD_W+dx))
                result[dy_, dx_] |= mask[sy, sx]
        return result

    near_road = neighbor_mask(road, 1)
    near_wire = neighbor_mask(wire | plant, 2)
    near_zone = neighbor_mask(any_zone, 2)

    # Good candidate: empty, near road, near wire/plant, near existing zone
    cand_ideal = emp & near_road & near_wire & near_zone
    # Fallback: empty, near road, near wire
    cand_ok = emp & near_road & near_wire
    # Further fallback: just near road
    cand_any = emp & near_road

    # Choose candidate set
    if cand_ideal.any():
        cand = cand_ideal
    elif cand_ok.any():
        cand = cand_ok
    else:
        # Need more roads or wires - extend them
        # Find wire frontier and extend
        wire_frontier = wire & neighbor_mask(emp, 1)
        if wire_frontier.any():
            wys, wxs = np.where(wire_frontier)
            # Extend wire toward empty areas
            for i in range(len(wxs)):
                wx, wy = int(wxs[i]), int(wys[i])
                for dx, dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nx, ny = wx+dx, wy+dy
                    if 0 <= nx < WORLD_W and 0 <= ny < WORLD_H:
                        if emp[ny, nx]:
                            return (Tool.WIRE, nx, ny)

        # Extend road near wire
        road_near_wire = near_wire & emp & ~wire
        if road_near_wire.any():
            rys, rxs = np.where(road_near_wire)
            k = int(obs.step * 7 + tm.sum() % 100) % len(rxs)
            return (Tool.ROAD, int(rxs[k]), int(rys[k]))

        if not cand_any.any():
            return None
        cand = cand_any

    ys, xs = np.where(cand)
    if len(xs) == 0:
        return None

    # Pick deterministically but vary across steps
    k = int((obs.step * 31 + int(tm.sum()) % 1000)) % len(xs)
    x, y = int(xs[k]), int(ys[k])

    # Zone type decision based on current city state
    res_count = int(res.sum())
    com_count = int(com.sum())
    ind_count = int(ind.sum())
    total = res_count + com_count + ind_count + 1

    # Target ratio: 50% res, 30% com, 20% ind
    res_ratio = res_count / total
    com_ratio = com_count / total
    ind_ratio = ind_count / total

    # Add more of what's under-represented
    if res_ratio < 0.50:
        tool = Tool.RESIDENTIAL
    elif ind_ratio < 0.20:
        tool = Tool.INDUSTRIAL
    elif com_ratio < 0.30:
        tool = Tool.COMMERCIAL
    else:
        # Mix based on step
        r = obs.step % 10
        if r < 5:
            tool = Tool.RESIDENTIAL
        elif r < 8:
            tool = Tool.COMMERCIAL
        else:
            tool = Tool.INDUSTRIAL

    # Occasionally add services if city is large enough
    if obs.city_pop > 1000 and obs.step % 50 == 0:
        # Place police/fire station in empty area near roads
        if cand.any():
            tool = Tool.FIRESTATION if (obs.step % 100 < 50) else Tool.POLICESTATION

    return (tool, x, y)

def act(obs, state):
    """
    Combined policy:
    - Pre-planned action queue (from Parent B's approach)
    - Two neighborhoods with coal plants + wire spines
    - Horizontal road spines above/below zones
    - Balanced R/C/I zones
    - Zones placed ONLY after infrastructure is laid
    - Reactive expansion phase
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    if 'action_queue' not in state:
        state['action_queue'] = []
        state['built'] = False

    if not state['action_queue'] and not state['built']:
        actions = []

        # === LEFT NEIGHBORHOOD: centered around x=35, y=50 ===
        # Coal plant at (25, 50) - footprint 24-26, 49-51
        p1x, p1y = 25, 50
        actions.append((Tool.COALPOWER, p1x, p1y))

        # Vertical wire spine at x=29, from y=42 to y=60
        wc1 = 29
        for wy in range(42, 61):
            actions.append((Tool.WIRE, wc1, wy))

        # Horizontal wire at y=50 from wire spine to zones
        for wx in range(29, 50):
            actions.append((Tool.WIRE, wx, 50))

        # Horizontal road at y=45 (top road for left neighborhood)
        for rx in range(30, 50):
            actions.append((Tool.ROAD, rx, 45))

        # Horizontal road at y=55 (bottom road for left neighborhood)
        for rx in range(30, 50):
            actions.append((Tool.ROAD, rx, 55))

        # Vertical road at x=30 connecting top and bottom
        for ry in range(45, 56):
            actions.append((Tool.ROAD, 30, ry))

