            actions.append((Tool.ROAD, rx, 58))
        for zx in range(33, 50, 4):
            actions.append((Tool.RESIDENTIAL, zx, 56))  # centered between y=55 and y=58

        # === RIGHT NEIGHBORHOOD: centered around x=85, y=50 ===
        p2x, p2y = 95, 50
        actions.append((Tool.COALPOWER, p2x, p2y))

        wc2 = 91
        for wy in range(42, 61):
            actions.append((Tool.WIRE, wc2, wy))

        # Horizontal wire at y=50
        for wx in range(70, 92):
            actions.append((Tool.WIRE, wx, 50))

        # Horizontal roads
        for rx in range(70, 91):
            actions.append((Tool.ROAD, rx, 45))
        for rx in range(70, 91):
            actions.append((Tool.ROAD, rx, 55))
        for rx in range(70, 91):
            actions.append((Tool.ROAD, rx, 42))
        for rx in range(70, 91):
            actions.append((Tool.ROAD, rx, 58))

        # Vertical road at x=90
        for ry in range(42, 59):
            actions.append((Tool.ROAD, 90, ry))

        # Extra wire for right zones
        for wy in range(42, 55):
            actions.append((Tool.WIRE, 87, wy))

        # Right zones
        for zx in range(72, 90, 4):
            actions.append((Tool.RESIDENTIAL, zx, 48))
        for zx in range(72, 90, 4):
            actions.append((Tool.COMMERCIAL, zx, 52))
        for zx in range(72, 90, 4):
            actions.append((Tool.INDUSTRIAL, zx, 44))
        for zx in range(72, 90, 4):
            actions.append((Tool.RESIDENTIAL, zx, 56))

        # === CONNECT THE TWO NEIGHBORHOODS ===
        # Road at y=50 from x=50 to x=70
        for rx in range(50, 70):
            actions.append((Tool.ROAD, rx, 50))
        # Wire at y=50 from x=50 to x=70 (connecting power grids)
        for wx in range(50, 70):
            actions.append((Tool.WIRE, wx, 50))

        # Central zones along connection road
        for zx in range(53, 68, 4):
            actions.append((Tool.RESIDENTIAL, zx, 48))
        for zx in range(53, 68, 4):
            actions.append((Tool.COMMERCIAL, zx, 52))

        # Service buildings near center
        actions.append((Tool.FIRESTATION, 58, 45))
        actions.append((Tool.POLICESTATION, 62, 55))

        # === THIRD COAL PLANT in center for more power ===
        actions.append((Tool.COALPOWER, 60, 50))
        # (auto-bulldoze will clear road/wire there - place it offset)
        # Actually place it away from road spine
        # Let's use (60, 38) instead
        actions[-1] = (Tool.COALPOWER, 60, 38)
        # Wire from plant to grid
        for wy in range(39, 51):
            actions.append((Tool.WIRE, 60, wy))

        # More zones above: road at y=38 and y=35
        for rx in range(33, 90):
            actions.append((Tool.ROAD, rx, 40))
        for wx in range(33, 90):
            actions.append((Tool.WIRE, wx, 40))
        for zx in range(35, 90, 4):
            actions.append((Tool.RESIDENTIAL, zx, 37))

        state['action_queue'] = actions
        state['built'] = True

    # Execute queued actions
    if state['action_queue']:
        action = state['action_queue'].pop(0)
        tool, ax, ay = action
        ax = max(1, min(WORLD_W - 2, ax))
        ay = max(1, min(WORLD_H - 2, ay))

        # For zones, check if 3x3 area is clear
        if tool in (Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.INDUSTRIAL):
            clear = True
            for dy in range(-1, 2):
                for dx in range(-1, 2):
                    ny, nx = ay + dy, ax + dx
                    if 0 <= ny < WORLD_H and 0 <= nx < WORLD_W:
                        if not em[ny, nx]:
                            clear = False
                            break
                if not clear:
                    break
            if not clear:
                return None

        return (tool, ax, ay)

    # === Reactive expansion: place more zones near existing infrastructure ===
    res_pos = set(zip(*np.where(res_mask(tm))))
    com_pos = set(zip(*np.where(com_mask(tm))))
    ind_pos = set(zip(*np.where(ind_mask(tm))))
    all_zones = res_pos | com_pos | ind_pos
    res_count = len(res_pos)
    com_count = len(com_pos)
    ind_count = len(ind_pos)
    total = res_count + com_count + ind_count + 1

    for cy_s in range(35, 65, 3):
        for cx_s in range(30, 92, 3):
            # Check 3x3 area clear
            clear = True
            for dy in range(-1, 2):
                for dx in range(-1, 2):
                    ny, nx = cy_s + dy, cx_s + dx
                    if 0 <= ny < WORLD_H and 0 <= nx < WORLD_W:
                        if not em[ny, nx]:
                            clear = False
                            break
                if not clear:
                    break
            if not clear:
                continue

            # Check road and wire nearby
            road_near = False
            wire_near = False
            for dy in range(-2, 3):
                for dx in range(-2, 3):
                    ny, nx = cy_s + dy, cx_s + dx
                    if 0 <= ny < WORLD_H and 0 <= nx < WORLD_W:
                        if rm[ny, nx]:
                            road_near = True
                        if wm[ny, nx]:
                            wire_near = True

            if road_near and wire_near:
                too_close = any(abs(cy_s - pr) <= 2 and abs(cx_s - pc) <= 2
                                for (pr, pc) in all_zones)
                if not too_close:
                    if ind_count / total < 0.2:
                        return (Tool.INDUSTRIAL, cx_s, cy_s)
                    elif com_count / total < 0.3:
                        return (Tool.COMMERCIAL, cx_s, cy_s)
                    else:
                        return (Tool.RESIDENTIAL, cx_s, cy_s)

    return None

def act(obs, state):
    """
    Horizontal layout strategy: power plant on left, wire runs horizontally,
    roads run horizontally above/below the wire, zones packed in rows.
    Build TWO clusters: one upper, one lower, connected by vertical roads.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    all_zone_mask = resm | comm | indm

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool(zone_row_idx):
        # Alternate: RES heavy top, IND heavy bottom, COM mixed
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        # Aim: 50% RES, 30% COM, 20% IND
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        if com_count / t < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_center_occupied(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    # Fixed layout: horizontal spine approach
    # Upper cluster: rows 25-55, plant at col 10
    # Lower cluster: rows 60-85, second plant at col 10

    # Upper cluster layout
    plant1_x, plant1_y = 10, 38
    wire_row_upper = 38        # horizontal wire row
    road_row_upper_top = 35    # road above wire
    road_row_upper_bot = 41    # road below wire

    # Zone rows above and below road
    zone_row_u1 = 32  # above top road
    zone_row_u2 = 44  # below bottom road

    # Lower cluster layout
    plant2_x, plant2_y = 10, 68
    wire_row_lower = 68
    road_row_lower_top = 65
    road_row_lower_bot = 71

    zone_row_l1 = 62
    zone_row_l2 = 74

    # Column range for zones/roads/wires
    col_start = 14
    col_end = 90

    # Use state to track current build phase
    if 'phase' not in state:
        state['phase'] = 0
        state['step_actions'] = []
        state['built'] = set()

    def already_built(key):
        return key in state['built']

    def mark_built(key):
        state['built'].add(key)

    step = obs.step

    # Phase 0: Place first power plant
    if not np.any(pm[plant1_y-1:plant1_y+2, plant1_x-1:plant1_x+2]):
        if not np.any(pm):
            return (Tool.COALPOWER, plant1_x, plant1_y)

    plant_rows, plant_cols = np.where(pm)
    if len(plant_rows) == 0:
        return (Tool.COALPOWER, plant1_x, plant1_y)

    # Phase 1: Build horizontal wire spine for upper cluster
    # Wire from plant rightward along wire_row_upper
    for c in range(plant1_x + 2, col_end + 1):
        if not wm[wire_row_upper, c] and not pm[wire_row_upper, c]:
            if em[wire_row_upper, c] or rm[wire_row_upper, c]:
                return (Tool.WIRE, c, wire_row_upper)
            else:
                break

    # Phase 2: Build top road for upper cluster
    for c in range(plant1_x + 2, col_end + 1):
        if not rm[road_row_upper_top, c] and not pm[road_row_upper_top, c]:
            if em[road_row_upper_top, c]:
                return (Tool.ROAD, c, road_row_upper_top)
            else:
                break

    # Phase 3: Build bottom road for upper cluster
    for c in range(plant1_x + 2, col_end + 1):
        if not rm[road_row_upper_bot, c] and not pm[road_row_upper_bot, c]:
            if em[road_row_upper_bot, c]:
                return (Tool.ROAD, c, road_row_upper_bot)
            else:
                break

    # Phase 4: Place zones in upper cluster zone rows
    # Check if roads and wire are ready enough
    road_top_count = int(np.sum(rm[road_row_upper_top, col_start:col_end]))
    road_bot_count = int(np.sum(rm[road_row_upper_bot, col_start:col_end]))
    wire_count = int(np.sum(wm[wire_row_upper, col_start:col_end]))

    if wire_count > 5 and road_top_count > 5:
        # Place zones above top road (zone_row_u1)
        for c in range(col_start, col_end - 2, 4):
            zc, zr = c + 1, zone_row_u1
            if not zone_center_occupied(zr, zc) and zone_area_ok(zr, zc):
                # Need wire nearby
                w_near = np.any(wm[max(0,zr-3):min(WORLD_H,zr+4), max(0,zc-3):min(WORLD_W,zc+4)])
                r_near = np.any(rm[max(0,zr-3):min(WORLD_H,zr+4), max(0,zc-3):min(WORLD_W,zc+4)])
                if r_near and w_near:
                    return (pick_tool(0), zc, zr)

    if wire_count > 5 and road_bot_count > 5:
        # Place zones below bottom road (zone_row_u2)
        for c in range(col_start, col_end - 2, 4):
            zc, zr = c + 1, zone_row_u2
            if not zone_center_occupied(zr, zc) and zone_area_ok(zr, zc):
                w_near = np.any(wm[max(0,zr-4):min(WORLD_H,zr+5), max(0,zc-4):min(WORLD_W,zc+5)])
                r_near = np.any(rm[max(0,zr-4):min(WORLD_H,zr+5), max(0,zc-4):min(WORLD_W,zc+5)])
                if r_near and w_near:
                    return (pick_tool(1), zc, zr)

    # Phase 5: Vertical wires connecting wire row to zones above/below
    # Wire up from wire_row_upper to zone_row_u1
    for c in range(col_start, col_end, 4):
        for r in range(wire_row_upper - 1, zone_row_u1 - 2, -1):
            if wm[r, c]:
                break
            if pm[r, c]:
                break
            if em[r, c]:
                return (Tool.WIRE, c, r)
            break

    # Wire down from wire_row_upper to zone_row_u2
    for c in range(col_start, col_end, 4):
        for r in range(wire_row_upper + 1, zone_row_u2 + 3):
            if wm[r, c]:
                break
            if pm[r, c]:
                break
            if em[r, c]:
                return (Tool.WIRE, c, r)
            break

    # Phase 6: Place second power plant for lower cluster when pop growing
    plant_count = int(np.sum(pm))
    if obs.city_pop > 100 or obs.step > obs.n_steps // 3:
        if not np.any(pm[plant2_y-1:plant2_y+2, plant2_x-1:plant2_x+2]):
            if plant_count < 9:
                return (Tool.COALPOWER, plant2_x, plant2_y)

    # Phase 7: Build lower cluster if second plant exists
    if np.any(pm[plant2_y-1:plant2_y+2, plant2_x-1:plant2_x+2]):
        # Wire spine for lower cluster
        for c in range(plant2_x + 2, col_end + 1):
            if not wm[wire_row_lower, c] and not pm[wire_row_lower, c]:
                if em[wire_row_lower, c] or rm[wire_row_lower, c]:
                    return (Tool.WIRE, c, wire_row_lower)
                else:
                    break

        # Roads for lower cluster
        for c in range(plant2_x + 2, col_end + 1):
            if not rm[road_row_lower_top, c] and not pm[road_row_lower_top, c]:
                if em[road_row_lower_top, c]:
                    return (Tool.ROAD, c, road_row_lower_top)
                else:
                    break

        for c in range(plant2_x + 2, col_end + 1):
            if not rm[road_row_lower_bot, c] and not pm[road_row_lower_bot, c]:
                if em[road_row_lower_bot, c]:
                    return (Tool.ROAD, c, road_row_lower_bot)
                else:
                    break

        wire_lower_count = int(np.sum(wm[wire_row_lower, col_start:col_end]))
        road_lt_count = int(np.sum(rm[road_row_lower_top, col_start:col_end]))
        road_lb_count = int(np.sum(rm[road_row_lower_bot, col_start:col_end]))

        if wire_lower_count > 5 and road_lt_count > 5:
            for c in range(col_start, col_end - 2, 4):
                zc, zr = c + 1, zone_row_l1
                if not zone_center_occupied(zr, zc) and zone_area_ok(zr, zc):
                    w_near = np.any(wm[max(0,zr-4):min(WORLD_H,zr+5), max(0,zc-4):min(WORLD_W,zc+5)])
                    r_near = np.any(rm[max(0,zr-4):min(WORLD_H,zr+5), max(0,zc-4):min(WORLD_W,zc+5)])
                    if r_near and w_near:
                        return (pick_tool(2), zc, zr)

        if wire_lower_count > 5 and road_lb_count > 5:
            for c in range(col_start, col_end - 2, 4):
                zc, zr = c + 1, zone_row_l2
                if not zone_center_occupied(zr, zc) and zone_area_ok(zr, zc):
                    w_near = np.any(wm[max(0,zr-4):min(WORLD_H,zr+5), max(0,zc-4):min(WORLD_W,zc+5)])
                    r_near = np.any(rm[max(0,zr-4):min(WORLD_H,zr+5), max(0,zc-4):min(WORLD_W,zc+5)])
                    if r_near and w_near:
                        return (pick_tool(3), zc, zr)

        # Vertical wires for lower cluster
        for c in range(col_start, col_end, 4):
            for r in range(wire_row_lower - 1, zone_row_l1 - 2, -1):
                if wm[r, c]:
                    break
                if pm[r, c]:
                    break
                if em[r, c]:
                    return (Tool.WIRE, c, r)
                break

        for c in range(col_start, col_end, 4):
            for r in range(wire_row_lower + 1, zone_row_l2 + 3):
                if wm[r, c]:
                    break
                if pm[r, c]:
                    break
                if em[r, c]:
                    return (Tool.WIRE, c, r)
                break

    # Phase 8: Vertical road connecting upper and lower clusters
    if obs.city_pop > 200:
        vert_road_col = col_start + 2
        for r in range(road_row_upper_bot + 1, road_row_lower_top):
            if not rm[r, vert_road_col] and em[r, vert_road_col]:
                return (Tool.ROAD, vert_road_col, r)

    # Phase 9: Third power plant if really growing
    if obs.city_pop > 500 and plant_count < 18:
        px3, py3 = 70, 38
        if 2 <= px3 <= WORLD_W - 4 and 2 <= py3 <= WORLD_H - 4:
            if np.all(em[py3-1:py3+2, px3-1:px3+2]):
                return (Tool.COALPOWER, px3, py3)

    # Phase 10: More zones in extended columns
    if obs.city_pop > 300:
        for zr in [zone_row_u1, zone_row_u2, zone_row_l1, zone_row_l2]:
            for c in range(col_end, min(WORLD_W - 3, col_end + 20), 4):
                zc = c
                if not zone_center_occupied(zr, zc) and zone_area_ok(zr, zc):
                    w_near = np.any(wm[max(0,zr-5):min(WORLD_H,zr+6), max(0,zc-5):min(WORLD_W,zc+6)])
                    r_near = np.any(rm[max(0,zr-5):min(WORLD_H,zr+6), max(0,zc-5):min(WORLD_W,zc+6)])
                    if r_near and w_near:
                        return (pick_tool(4), zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder.
    Reads tile_map every step. Places power, wires, roads, zones reactively.
    Key changes from parent:
    - Single cluster at center (60,50) for density
    - Wire spine extends radially from plant
    - Roads laid in grid pattern around wire spine
    - Zone placement prioritizes RES heavily early, balanced later
    - Checks actual powered_zones to decide if more wire needed
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def adj_to(mask, x, y, dist=1):
        for ddx in range(-dist, dist+1):
            for ddy in range(-dist, dist+1):
                if ddx == 0 and ddy == 0:
                    continue
                nx, ny = x+ddx, y+ddy
                if in_bounds(nx, ny) and bool(mask[ny, nx]):
                    return True
        return False

    # Central cluster anchor
    CX, CY = 60, 50

    # Step 1: place coal power plant at anchor if not present
    plant_ys, plant_xs = np.where(pm)
    has_plant = len(plant_xs) > 0
    if not has_plant:
        return (Tool.COALPOWER, CX, CY)

    # Find primary plant location (first plant found)
    px0, py0 = int(plant_xs[0]), int(plant_ys[0])

    # Step 2: extend wire network from plant/wires
    # Wire plan: cross pattern from plant, then rings
    # Build list of desired wire locations ordered by distance from plant
    wire_targets = []
    # Horizontal and vertical spines
    for r in range(1, 20):
        for dx, dy in [(r,0),(-r,0),(0,r),(0,-r)]:
            wire_targets.append((px0+dx, py0+dy))
    # Diagonal extensions
    for r in range(1, 15):
        for dx, dy in [(r,r),(r,-r),(-r,r),(-r,-r)]:
            wire_targets.append((px0+dx, py0+dy))

    # Place next missing wire that is adjacent to power
    for (wx, wy) in wire_targets:
        if not in_bounds(wx, wy):
            continue
        if bool(pm[wy, wx]) or bool(wm[wy, wx]) or bool(rm[wy, wx]):
            continue
        if not bool(em[wy, wx]):
            continue
        # Only if adjacent to existing power source
        if adj_to(pm | wm, wx, wy, dist=1):
            return (Tool.WIRE, wx, wy)

    # Step 3: extend road network
    # Roads in grid: offset from plant, avoiding wire spine columns
    road_targets = []
    # Horizontal roads at intervals around plant
    for dy in [-4, -7, -10, 4, 7, 10, -1, 1]:
        for dx in range(-15, 16):
            road_targets.append((px0+dx, py0+dy))
    # Vertical roads at intervals
    for dx in [-3, -6, -9, -12, 3, 6, 9, 12]:
        for dy in range(-12, 13):
            road_targets.append((px0+dx, py0+dy))

    for (rx, ry) in road_targets:
        if not in_bounds(rx, ry):
            continue
        if bool(rm[ry, rx]):
            continue
        if bool(pm[ry, rx]) or bool(wm[ry, rx]):
            continue
        if not bool(em[ry, rx]):
            continue
        # Adjacent to existing road or plant
        if adj_to(rm, rx, ry, dist=1) or adj_to(pm, rx, ry, dist=2):
            return (Tool.ROAD, rx, ry)

    # Step 4: place zones near roads and power
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        # Early on build industry for jobs, then balance
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        if com_count / t < 0.20:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Neighbor masks for road and power proximity
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_mask = resm | comm | indm
    cand = em & nbr_road & nbr_power
    cand[0:2, :] = False
    cand[WORLD_H-2:, :] = False
    cand[:, 0:2] = False
    cand[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        # Sort candidates by distance to plant center for compact growth
        dists = np.abs(cxs - px0) + np.abs(cys - py0)
        order = np.argsort(dists)
        tool = pick_tool()
        checked = 0
        for idx in order:
            if checked > 120:
                break
            checked += 1
            zx, zy = int(cxs[idx]), int(cys[idx])
            ok = True
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    ny2, nx2 = zy+dr, zx+dc
                    if not in_bounds(nx2, ny2):
                        ok = False; break
                    if not (bool(em[ny2, nx2]) or bool(zone_mask[ny2, nx2])):
                        ok = False; break
                if not ok:
                    break
            if ok:
                return (tool, zx, zy)

    # Step 5: services
    if obs.city_pop > 150:
        for fx, fy in [(px0+5, py0-8), (px0-5, py0+8)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 300:
        for fx, fy in [(px0+8, py0+5), (px0-8, py0-5)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.POLICESTATION, fx, fy)

    # Fallback: extend road from any existing road tile
    rys, rxs = np.where(rm)
    if len(rxs) > 0:
        k = int(obs.step * 13 + 7) % len(rxs)
        for off in range(min(len(rxs), 20)):
            ri = (k + off) % len(rxs)
            rx2, ry2 = int(rxs[ri]), int(rys[ri])
            for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx2, ny2 = rx2+ddx, ry2+ddy
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and not bool(wm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wys, wxs = np.where(wm)
    if len(wxs) > 0:
        k = int(obs.step * 7 + 3) % len(wxs)
        wx2, wy2 = int(wxs[k]), int(wys[k])
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx2, ny2 = wx2+ddx, wy2+ddy
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop policy: each step reads tile_map and decides next placement.
    Strategy:
    - Place a coal power plant at a fixed position.
    - Grow a wire spine outward from the plant, one tile at a time.
    - Grow a road column adjacent to the wire spine.
    - Place lateral wires to the left and lateral roads to the right.
    - Place zones where both wire and road coverage exist.
    - Expand further as population grows.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res = res_mask(tm)
    com = com_mask(tm)
    ind = ind_mask(tm)

    cx, cy = 60, 50  # center of operations

    # Power plant center
    plant_x, plant_y = cx - 8, cy

    # Wire spine column (right of plant)
    wire_col = plant_x + 4
    # Road column (right of wire spine)
    road_col = wire_col + 2
    # Zone columns
    left_zone_col = wire_col - 3   # zones left, powered by lateral wire
    right_zone_col = road_col + 3  # zones right, accessed by road

    has_plant = np.any(pm)

    # Phase 1: Place coal power plant if not present
    if not has_plant:
        return (Tool.COALPOWER, plant_x, plant_y)

    # Find actual plant center from tile_map
    plant_rows, plant_cols = np.where(pm)
    if len(plant_rows) > 0:
        plant_y = int(np.mean(plant_rows))
        plant_x = int(np.mean(plant_cols))
        wire_col = plant_x + 4
        road_col = wire_col + 2
        left_zone_col = wire_col - 3
        right_zone_col = road_col + 3

    # Desired vertical range for spine
    spine_min = max(1, plant_y - 18)
    spine_max = min(WORLD_H - 2, plant_y + 18)

    # Phase 2: Connect plant to wire spine if not connected
    # Wire from plant right edge to wire_col at plant_y
    for c in range(plant_x + 2, wire_col + 1):
        if 0 <= c < WORLD_W and not wm[plant_y, c]:
            # Don't overwrite plant tiles
            if not pm[plant_y, c]:
                return (Tool.WIRE, c, plant_y)

    # Phase 3: Extend wire spine vertically from plant_y outward
    wire_col_rows = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])
    if not wire_col_rows:
        return (Tool.WIRE, wire_col, plant_y)

    min_row = min(wire_col_rows)
    max_row = max(wire_col_rows)

    # Extend one step at a time (closed-loop: check current state)
    if max_row < spine_max:
        nr = max_row + 1
        if 0 <= nr < WORLD_H and not pm[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)
    if min_row > spine_min:
        nr = min_row - 1
        if 0 <= nr >= 0 and not pm[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)

    # Phase 4: Build road spine column
    road_col_rows = sorted([r for r in range(WORLD_H) if rm[r, road_col]])
    if 0 <= road_col < WORLD_W:
        for r in wire_col_rows:
            if not rm[r, road_col] and not pm[r, road_col]:
                return (Tool.ROAD, road_col, r)

    # Phase 5: Lateral wires from spine to left zone column (one row at a time)
    for r in wire_col_rows:
        for c in range(wire_col - 1, left_zone_col - 1, -1):
            if 0 <= c < WORLD_W and not wm[r, c] and not pm[r, c]:
                return (Tool.WIRE, c, r)
        break  # one row per step to stay reactive

    # Phase 6: Lateral roads from road column to right zone column
    road_col_rows = sorted([r for r in range(WORLD_H) if rm[r, road_col]])
    for r in road_col_rows:
        for c in range(road_col + 1, right_zone_col + 2):
            if 0 <= c < WORLD_W and not rm[r, c] and not pm[r, c]:
                return (Tool.ROAD, c, r)
        break  # one row per step

    # Helper: check 3x3 area is clear of plants and in bounds
    def zone_area_ok(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if pm[rr, rc]:
                    return False
        return True

    def zone_exists_near(zr, zc):
        # Check if a zone center exists within 2 tiles
        sub_r = slice(max(0, zr-2), min(WORLD_H, zr+3))
        sub_c = slice(max(0, zc-2), min(WORLD_W, zc+3))
        return (res[sub_r, sub_c].any() or
                com[sub_r, sub_c].any() or
                ind[sub_r, sub_c].any())

    res_count = int(res.sum())
    com_count = int(com.sum())
    ind_count = int(ind.sum())
    total_zones = res_count + com_count + ind_count

    # Phase 7: Place zones where wire AND road coverage exists
    zone_rows = list(range(max(1, plant_y - 17), min(WORLD_H - 2, plant_y + 18), 3))

    all_wire_rows = set(wire_col_rows)
    all_road_rows = set(road_col_rows)

    for zr in zone_rows:
        # Wire nearby (within 3 rows)
        wire_near = any(abs(zr - wr) <= 3 for wr in all_wire_rows)
        road_near = any(abs(zr - rr) <= 3 for rr in all_road_rows)

        if not wire_near or not road_near:
            continue

        # Left zone
        zc = left_zone_col
        if (1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1
                and not zone_exists_near(zr, zc) and zone_area_ok(zr, zc)):
            # Balance: ~50% RES, 25% COM, 25% IND
            if ind_count * 4 < total_zones + 1:
                return (Tool.INDUSTRIAL, zc, zr)
            elif com_count * 4 < total_zones + 1:
                return (Tool.COMMERCIAL, zc, zr)
            else:
                return (Tool.RESIDENTIAL, zc, zr)

        # Right zone
        zc = right_zone_col
        if (1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1
                and not zone_exists_near(zr, zc) and zone_area_ok(zr, zc)):
            if com_count * 4 < total_zones + 1:
                return (Tool.COMMERCIAL, zc, zr)
            else:
                return (Tool.RESIDENTIAL, zc, zr)

    # Phase 8: Complete all lateral wires (catch-up)
    for r in wire_col_rows:
        for c in range(wire_col - 1, left_zone_col - 1, -1):
            if 0 <= c < WORLD_W and not wm[r, c] and not pm[r, c]:
                return (Tool.WIRE, c, r)

    # Phase 9: Complete all lateral roads (catch-up)
    for r in road_col_rows:
        for c in range(road_col + 1, right_zone_col + 2):
            if 0 <= c < WORLD_W and not rm[r, c] and not pm[r, c]:
                return (Tool.ROAD, c, r)

    # Phase 10: Expand further if growing
    if obs.city_pop > 200:
        far_left_col = left_zone_col - 4
        far_right_col = right_zone_col + 4
        road_col2 = road_col + 7

        # Extend wire left for far-left zones
        for r in wire_col_rows:
            for c in range(left_zone_col - 1, far_left_col - 1, -1):
                if 0 <= c < WORLD_W and not wm[r, c] and not pm[r, c]:
                    return (Tool.WIRE, c, r)
            break

        # Second road column
        for r in road_col_rows:
            if 0 <= road_col2 < WORLD_W and not rm[r, road_col2] and not pm[r, road_col2]:
                return (Tool.ROAD, road_col2, r)

        # Extra zones
        extra_rows = list(range(max(1, plant_y - 20), min(WORLD_H - 2, plant_y + 21), 3))
        for zr in extra_rows:
            for zc in [far_left_col, far_right_col]:
                if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                    if not zone_exists_near(zr, zc) and zone_area_ok(zr, zc):
                        # Check wire and road are anywhere nearby
                        wire_ok = any(abs(zr-wr) <= 4 and abs(wire_col-zc) <= 7
                                      for wr in all_wire_rows)
                        road_ok = any(abs(zr-rr) <= 4 and abs(road_col-zc) <= 7
                                      for rr in all_road_rows)
                        if wire_ok and road_ok:
                            return (Tool.RESIDENTIAL, zc, zr)

    # Phase 11: Add nuclear power if large enough
    if obs.city_pop > 600:
        nuke_x = plant_x - 8
        nuke_y = plant_y + 10
        if (1 <= nuke_y < WORLD_H - 1 and 1 <= nuke_x < WORLD_W - 1
                and not np.any(pm[nuke_y-1:nuke_y+2, nuke_x-1:nuke_x+2])):
            return (Tool.NUCLEARPOWER, nuke_x, nuke_y)

    return None

def act(obs, state):
    """
    Combined policy from Parent A and B:
    - Place coal power plant first
    - Build vertical wire spine adjacent to plant
    - Build road column next to wire spine
    - Place zones on both sides with proper power/road access
    - Extend lateral wires and roads to zones
    - Scale up corridor with population growth
    - Add second power plant when needed
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    all_zone_mask = resm | comm | indm

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool(zr=None, zc=None):
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return bool(np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1]))

    def has_road_nearby(zr, zc, radius=3):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return bool(np.any(rm[r0:r1, c0:c1]))

    # Phase 1: Place coal power plant if missing
    if not np.any(pm):
        px, py = cx - 6, cy
        return (Tool.COALPOWER, px, py)

    # Find plant centroid
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Layout: wire spine just right of plant, road next to wire
    wire_col = plant_cx + 4
    road_col = wire_col + 1
    left_zone_col = wire_col - 4   # zones left of wire
    right_zone_col = road_col + 3  # zones right of road

    wire_col = max(3, min(WORLD_W - 4, wire_col))
    road_col = max(3, min(WORLD_W - 4, road_col))
    left_zone_col = max(2, min(WORLD_W - 3, left_zone_col))
    right_zone_col = max(2, min(WORLD_W - 3, right_zone_col))

    # Spine extent based on population
    if obs.city_pop < 50:
        spine_extent = 8
    elif obs.city_pop < 150:
        spine_extent = 12
    elif obs.city_pop < 300:
        spine_extent = 16
    elif obs.city_pop < 600:
        spine_extent = 22
    else:
        spine_extent = 30

    target_min = max(1, cy - spine_extent)
    target_max = min(WORLD_H - 2, cy + spine_extent)

    wire_rows_on_spine = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])
    road_rows_on_col = sorted([r for r in range(WORLD_H) if rm[r, road_col]])

    # Phase 2: Bootstrap wire spine adjacent to plant
    if not wire_rows_on_spine:
        # Try to place wire right next to plant
        for dy in range(0, 6):
            for nr in [plant_cy + dy, plant_cy - dy]:
                if 0 <= nr < WORLD_H and 0 <= wire_col < WORLD_W:
                    if em[nr, wire_col] or wm[nr, wire_col]:
                        return (Tool.WIRE, wire_col, nr)
        return None

    min_wire_row = min(wire_rows_on_spine)
    max_wire_row = max(wire_rows_on_spine)

    # Phase 3: Extend wire spine downward first, then upward
    if max_wire_row < target_max:
        nr = max_wire_row + 1
        if nr < WORLD_H and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    if min_wire_row > target_min:
        nr = min_wire_row - 1
        if nr >= 0 and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Phase 4: Build road column alongside wire spine
    for r in wire_rows_on_spine:
        if 0 <= r < WORLD_H and 0 <= road_col < WORLD_W:
            if not rm[r, road_col] and em[r, road_col]:
                return (Tool.ROAD, road_col, r)

    # Phase 5: Lateral wires from spine to left zone column
    for wr in wire_rows_on_spine:
        for wc in range(wire_col - 1, left_zone_col - 2, -1):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc] or pm[wr, wc]:
                    break
                if em[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                else:
                    break

    # Phase 6: Road extensions rightward to right zone col
    for wr in wire_rows_on_spine:
        if not rm[wr, road_col]:
            continue
        for rc in range(road_col + 1, right_zone_col + 2):
            if 0 <= rc < WORLD_W:
                if rm[wr, rc]:
                    break
                if pm[wr, rc]:
                    break
                if em[wr, rc]:
                    return (Tool.ROAD, rc, wr)
                else:
                    break

    # Phase 7: Wires rightward to power right zones
    for wr in wire_rows_on_spine:
        for wc in range(wire_col + 1, right_zone_col + 2):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc] or pm[wr, wc]:
                    break
                if rm[wr, wc]:
                    continue  # skip road tiles, don't overwrite
                if em[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                else:
                    break

    # Phase 8: Place zones along the corridor
    zone_rows = list(range(max(1, target_min + 1), min(WORLD_H - 1, target_max), 3))

    for zr in zone_rows:
        wire_near = any(abs(zr - wr) <= 2 for wr in wire_rows_on_spine)
        road_near = any(abs(zr - rr) <= 2 for rr in road_rows_on_col)

        if wire_near and road_near:
            # Left zone
            zc = left_zone_col
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc, 5) and has_road_nearby(zr, zc, 5):
                    return (pick_tool(), zc, zr)
                elif has_wire_nearby(zr, zc, 6):
                    return (Tool.RESIDENTIAL, zc, zr)

            # Right zone
            zc = right_zone_col
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_road_nearby(zr, zc, 5) and has_wire_nearby(zr, zc, 6):
                    return (pick_tool(), zc, zr)

    # Phase 9: Second coal plant when population growing
    plant_count = int(np.sum(pm))
    if obs.city_pop > 300 and plant_count < 9:
        px2 = plant_cx + 22
        py2 = plant_cy
        if 2 <= px2 <= WORLD_W - 4 and 2 <= py2 <= WORLD_H - 4:
            if np.all(em[py2-1:py2+2, px2-1:px2+2]):
                return (Tool.COALPOWER, px2, py2)
        py2 = plant_cy - 15
        if 2 <= px2 <= WORLD_W - 4 and 2 <= py2 <= WORLD_H - 4:
            if np.all(em[py2-1:py2+2, px2-1:px2+2]):
                return (Tool.COALPOWER, px2, py2)
        # Try left side too
        px2 = plant_cx - 15
        py2 = plant_cy
        if 2 <= px2 <= WORLD_W - 4 and 2 <= py2 <= WORLD_H - 4:
            if np.all(em[py2-1:py2+2, px2-1:px2+2]):
                return (Tool.COALPOWER, px2, py2)

    # Phase 10: Expand zone columns outward with more population
    if obs.city_pop > 200:
        extra_left = left_zone_col - 4
        extra_right = right_zone_col + 4
        for zc in [extra_left, extra_right]:
            zc = max(2, min(WORLD_W - 3, zc))
            for zr in zone_rows:
                if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                    if has_road_nearby(zr, zc, 7) and has_wire_nearby(zr, zc, 8):
                        return (pick_tool(), zc, zr)

    # Phase 11: Fill any gaps in wire spine
    for r in range(target_min, target_max + 1):
        if not wm[r, wire_col] and not pm[r, wire_col] and em[r, wire_col]:
            return (Tool.WIRE, wire_col, r)

    # Phase 12: Horizontal roads for additional connectivity
    if obs.city_pop > 150:
        h_rows = [min_wire_row + 1, max_wire_row - 1, plant_cy]
        for rr in h_rows:
            if 0 <= rr < WORLD_H:
                for rc in range(max(0, left_zone_col - 2), min(WORLD_W, right_zone_col + 3)):
                    if em[rr, rc] and not pm[rr, rc] and not wm[rr, rc]:
                        return (Tool.ROAD, rc, rr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Each step reads the actual tile map to decide next action
    - Builds compact cluster: coal plant -> wire spine -> roads -> zones
    - Adapts based on what's actually on the map
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # Fixed anchor: plant at (40, 50), wire spine at col 44
    # roads at 47 and 50, zones at 44 (left of road) - adjusted
    PLANT_X, PLANT_Y = 40, 50
    WIRE_COL = 45
    LEFT_ROAD = 48
    RIGHT_ROAD = 52
    LEFT_ZONE_COL = 50   # between roads, actually right of left road
    RIGHT_ZONE_COL = 55  # right of right road
    EXTRA_LEFT_COL = 44  # left of left road
    SPINE_TOP = 32
    SPINE_BOT = 68

    has_plant = np.any(pm)

    # Phase 1: Place coal power plant
    if not has_plant:
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    # Find actual plant center from plant_mask
    plant_rows, plant_cols = np.where(pm)
    if len(plant_rows) > 0:
        # Use centroid
        pr = int(np.mean(plant_rows))
        pc = int(np.mean(plant_cols))
    else:
        pr, pc = PLANT_Y, PLANT_X

    # Dynamic wire col: just right of plant
    wire_col = pc + 5
    wire_col = max(4, min(WORLD_W - 5, wire_col))
    left_road = wire_col + 3
    right_road = wire_col + 7
    left_zone_col = wire_col + 5   # between left and right road
    right_zone_col = wire_col + 10  # right of right road
    extra_left_col = wire_col - 4  # left of wire col

    spine_top = max(1, pr - 18)
    spine_bot = min(WORLD_H - 2, pr + 18)

    # Wire rows currently present
    wire_rows = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])

    # Phase 2: Start wire adjacent to plant if none
    if not wire_rows:
        wy = pr
        if 0 <= wire_col < WORLD_W and 0 <= wy < WORLD_H:
            return (Tool.WIRE, wire_col, wy)

    # Phase 3: Extend wire spine vertically
    if wire_rows:
        cur_min = min(wire_rows)
        cur_max = max(wire_rows)
        if cur_max < spine_bot:
            nr = cur_max + 1
            if nr < WORLD_H:
                return (Tool.WIRE, wire_col, nr)
        if cur_min > spine_top:
            nr = cur_min - 1
            if nr >= 0:
                return (Tool.WIRE, wire_col, nr)

    # Phase 4: Build left and right road columns alongside wire spine
    for wr in wire_rows:
        if 0 <= left_road < WORLD_W and not rm[wr, left_road]:
            return (Tool.ROAD, left_road, wr)
        if 0 <= right_road < WORLD_W and not rm[wr, right_road]:
            return (Tool.ROAD, right_road, wr)

    # Phase 5: Lateral wires from spine to reach zone columns
    for wr in wire_rows:
        # Wire right to left_zone_col
        for wc in range(wire_col + 1, min(left_zone_col + 1, WORLD_W)):
            if em[wr, wc] and not wm[wr, wc]:
                return (Tool.WIRE, wc, wr)
        # Wire right to right_zone_col
        for wc in range(wire_col + 1, min(right_zone_col + 1, WORLD_W)):
            if em[wr, wc] and not wm[wr, wc]:
                return (Tool.WIRE, wc, wr)
        # Wire left for extra_left zones
        for wc in range(wire_col - 1, max(extra_left_col - 1, 0), -1):
            if em[wr, wc] and not wm[wr, wc]:
                return (Tool.WIRE, wc, wr)

    # Helpers
    def zone_clear(zr, zc):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                r2, c2 = zr + dr, zc + dc
                if r2 < 0 or r2 >= WORLD_H or c2 < 0 or c2 >= WORLD_W:
                    return False
                if not em[r2, c2]:
                    return False
        return True

    def near_mask(zr, zc, mask, radius=2):
        r1 = max(0, zr - radius)
        r2 = min(WORLD_H, zr + radius + 1)
        c1 = max(0, zc - radius)
        c2 = min(WORLD_W, zc + radius + 1)
        return bool(np.any(mask[r1:r2, c1:c2]))

    def zone_exists_near(zr, zc):
        all_z = res_m | com_m | ind_m
        return near_mask(zr, zc, all_z, radius=2)

    res_count = int(np.sum(res_m))
    com_count = int(np.sum(com_m))
    ind_count = int(np.sum(ind_m))

    # Phase 6: Place zones every 3 rows along spine
    zone_rows = list(range(spine_top + 1, spine_bot, 3))

    for zr in zone_rows:
        if not near_mask(zr, wire_col, wm, radius=3):
            continue

        # Between roads (left_zone_col area)
        zc = left_zone_col
        if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
            if not zone_exists_near(zr, zc) and zone_clear(zr, zc):
                if near_mask(zr, zc, rm, radius=2) and near_mask(zr, zc, wm, radius=3):
                    if ind_count < max(1, (res_count + 1) // 3):
                        return (Tool.INDUSTRIAL, zc, zr)
                    elif com_count < max(1, (res_count + 1) // 3):
                        return (Tool.COMMERCIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

        # Right of right road
        zc = right_zone_col
        if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
            if not zone_exists_near(zr, zc) and zone_clear(zr, zc):
                if near_mask(zr, zc, rm, radius=2) and near_mask(zr, zc, wm, radius=3):
                    if com_count < max(1, (res_count + 1) // 3):
                        return (Tool.COMMERCIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

        # Left of wire spine
        zc = extra_left_col
        if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
            if not zone_exists_near(zr, zc) and zone_clear(zr, zc):
                if near_mask(zr, zc, rm, radius=2) and near_mask(zr, zc, wm, radius=3):
                    return (Tool.RESIDENTIAL, zc, zr)

    # Phase 7: Build extra roads toward extra zone columns
    for wr in wire_rows:
        # Left extra road
        for rc in range(left_road - 1, max(0, extra_left_col - 4), -1):
            if 0 <= rc < WORLD_W and not rm[wr, rc]:
                return (Tool.ROAD, rc, wr)
        # Right extra road
        for rc in range(right_road + 1, min(WORLD_W - 1, right_zone_col + 4)):
            if 0 <= rc < WORLD_W and not rm[wr, rc]:
                return (Tool.ROAD, rc, wr)

    # Phase 8: If city growing, expand spine
    if obs.city_pop > 50 and wire_rows:
        cur_min = min(wire_rows)
        cur_max = max(wire_rows)
        new_top = max(1, spine_top - 8)
        new_bot = min(WORLD_H - 2, spine_bot + 8)
        if cur_max < new_bot:
            return (Tool.WIRE, wire_col, cur_max + 1)
        if cur_min > new_top:
            return (Tool.WIRE, wire_col, cur_min - 1)

    # Phase 9: Add more zone columns when population growing
    if obs.city_pop > 150:
        far_right = right_zone_col + 5
        for zr in zone_rows:
            zc = far_right
            if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                if not zone_exists_near(zr, zc) and zone_clear(zr, zc):
                    if near_mask(zr, zc, rm, radius=3):
                        return (Tool.RESIDENTIAL, zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map every step to find current infrastructure
    - Places coal plant, extends wire spine, builds road columns,
      then fills zones reactively based on actual power/road coverage.
    - More compact layout: plant at map center, wire spine runs vertically,
      roads flank at +/-2, zones at +/-5 from wire spine.
    - Zones placed every 3 rows for compactness.
    - Horizontal connecting wires ensure zones get power.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # Count zones
    res_count = int(np.sum(res_m))
    com_count = int(np.sum(com_m))
    ind_count = int(np.sum(ind_m))

    has_plant = np.any(pm)

    # ---- Layout parameters derived from plant position ----
    # Default if no plant yet
    plant_x, plant_y = 60, 50
    wire_col = 60
    left_road_col = 57
    right_road_col = 63
    left_zone_col = 54
    right_zone_col = 66

    if not has_plant:
        return (Tool.COALPOWER, plant_x, plant_y)

    # Find actual plant position
    plant_positions = list(zip(*np.where(pm)))
    if plant_positions:
        pr, pc = plant_positions[0]
        plant_y = int(pr)
        plant_x = int(pc)
        # Wire spine just to the right of plant footprint
        wire_col = plant_x + 4
        wire_col = max(5, min(WORLD_W - 6, wire_col))
        left_road_col = max(2, wire_col - 3)
        right_road_col = min(WORLD_W - 3, wire_col + 3)
        left_zone_col = max(2, wire_col - 6)
        right_zone_col = min(WORLD_W - 3, wire_col + 6)

    spine_top = max(1, plant_y - 25)
    spine_bot = min(WORLD_H - 2, plant_y + 25)

    # Current wire rows in spine column
    wire_rows_in_col = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])

    # ---- Phase 2: Start wire adjacent to plant ----
    if not wire_rows_in_col:
        if 0 <= wire_col < WORLD_W and 0 <= plant_y < WORLD_H:
            return (Tool.WIRE, wire_col, plant_y)

    # ---- Phase 3: Extend wire spine vertically ----
    if wire_rows_in_col:
        cur_min = min(wire_rows_in_col)
        cur_max = max(wire_rows_in_col)
        if cur_max < spine_bot:
            nr = cur_max + 1
            if nr < WORLD_H:
                return (Tool.WIRE, wire_col, nr)
        if cur_min > spine_top:
            nr = cur_min - 1
            if nr >= 0:
                return (Tool.WIRE, wire_col, nr)

    # ---- Phase 4: Build road columns alongside wire spine ----
    for wr in wire_rows_in_col:
        if 0 <= left_road_col < WORLD_W and not rm[wr, left_road_col]:
            return (Tool.ROAD, left_road_col, wr)
        if 0 <= right_road_col < WORLD_W and not rm[wr, right_road_col]:
            return (Tool.ROAD, right_road_col, wr)

    # ---- Helper functions ----
    def zone_clear(zr, zc):
        """Check if 3x3 footprint around (zr,zc) is empty."""
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                r2, c2 = zr + dr, zc + dc
                if r2 < 0 or r2 >= WORLD_H or c2 < 0 or c2 >= WORLD_W:
                    return False
                if not em[r2, c2]:
                    return False
        return True

    def zone_exists_near(zr, zc, mask):
        r1, r2 = max(0, zr - 2), min(WORLD_H, zr + 3)
        c1, c2 = max(0, zc - 2), min(WORLD_W, zc + 3)
        return bool(np.any(mask[r1:r2, c1:c2]))

    def near_wire(zr, zc, radius=3):
        r1, r2 = max(0, zr - radius), min(WORLD_H, zr + radius + 1)
        c1, c2 = max(0, zc - radius), min(WORLD_W, zc + radius + 1)
        return bool(np.any(wm[r1:r2, c1:c2]))

    def near_road(zr, zc, radius=3):
        r1, r2 = max(0, zr - radius), min(WORLD_H, zr + radius + 1)
        c1, c2 = max(0, zc - radius), min(WORLD_W, zc + radius + 1)
        return bool(np.any(rm[r1:r2, c1:c2]))

    # ---- Phase 5: Extend lateral wires to connect zone columns ----
    for wr in wire_rows_in_col:
        # Left lateral: wire_col-1 down to left_zone_col
        for wc in range(wire_col - 1, left_zone_col - 1, -1):
            if 0 <= wc < WORLD_W and not wm[wr, wc] and em[wr, wc]:
                return (Tool.WIRE, wc, wr)
        # Right lateral: wire_col+1 up to right_zone_col
        for wc in range(wire_col + 1, right_zone_col + 1):
            if 0 <= wc < WORLD_W and not wm[wr, wc] and em[wr, wc]:
                return (Tool.WIRE, wc, wr)

    # ---- Phase 6: Place zones ----
    # Zone rows spaced every 3 rows within spine range
    zone_rows = list(range(max(2, spine_top + 1), min(WORLD_H - 2, spine_bot), 3))

    for zr in zone_rows:
        # Left side zones
        zc = left_zone_col
        if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
            if not zone_exists_near(zr, zc, res_m) and not zone_exists_near(zr, zc, ind_m):
                if zone_clear(zr, zc) and near_wire(zr, zc) and near_road(zr, zc):
                    if ind_count < max(1, (res_count + com_count) // 4):
                        return (Tool.INDUSTRIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

        # Right side zones
        zc = right_zone_col
        if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
            if not zone_exists_near(zr, zc, res_m) and not zone_exists_near(zr, zc, com_m):
                if zone_clear(zr, zc) and near_wire(zr, zc) and near_road(zr, zc):
                    if com_count < max(1, res_count // 3):
                        return (Tool.COMMERCIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

    # ---- Phase 7: Grow extra zone columns when doing well ----
    if obs.city_pop > 50:
        extra_left = max(2, left_zone_col - 7)
        extra_right = min(WORLD_W - 3, right_zone_col + 7)

        # Extend wires to extra columns
        for wr in wire_rows_in_col:
            for wc in range(left_zone_col - 1, extra_left - 1, -1):
                if 0 <= wc < WORLD_W and not wm[wr, wc] and em[wr, wc]:
                    return (Tool.WIRE, wc, wr)
            for wc in range(right_zone_col + 1, extra_right + 1):
                if 0 <= wc < WORLD_W and not wm[wr, wc] and em[wr, wc]:
                    return (Tool.WIRE, wc, wr)

        # Extend roads to extra columns
        for wr in wire_rows_in_col:
            el_road = extra_left + 1
            er_road = extra_right - 1
            if 0 <= el_road < WORLD_W and not rm[wr, el_road] and em[wr, el_road]:
                return (Tool.ROAD, el_road, wr)
            if 0 <= er_road < WORLD_W and not rm[wr, er_road] and em[wr, er_road]:
                return (Tool.ROAD, er_road, wr)

        for zr in zone_rows:
            all_zones = res_m | com_m | ind_m
            for zc in [extra_left, extra_right]:
                if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                    if not zone_exists_near(zr, zc, all_zones):
                        if zone_clear(zr, zc) and near_wire(zr, zc) and near_road(zr, zc):
                            if ind_count < max(1, res_count // 4):
                                return (Tool.INDUSTRIAL, zc, zr)
                            elif com_count < max(1, res_count // 3):
                                return (Tool.COMMERCIAL, zc, zr)
                            else:
                                return (Tool.RESIDENTIAL, zc, zr)

    # ---- Phase 8: Extend spine if population growing ----
    if obs.city_pop > 200:
        new_top = max(1, spine_top - 10)
        new_bot = min(WORLD_H - 2, spine_bot + 10)
        if wire_rows_in_col:
            cur_min = min(wire_rows_in_col)
            cur_max = max(wire_rows_in_col)
            if cur_max < new_bot:
                return (Tool.WIRE, wire_col, cur_max + 1)
            if cur_min > new_top:
                return (Tool.WIRE, wire_col, cur_min - 1)

    return None

def act(obs, state):
    """
    Grid-based city builder: 
    - Place coal power plant at left-center
    - Build horizontal road spine (east-west) instead of vertical
    - Build vertical wire spine (north-south) crossing the road
    - Place zones in a grid pattern along the road spine
    - Better zone mix: 50% res, 30% com, 20% ind
    - Two neighborhoods: one above road spine, one below
    - Add second power plant when population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        if com_count / t < 0.30:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Phase 1: Place coal power plant if missing
    # Place plant at left side, mid-height
    plant_x, plant_y = 15, cy
    if not np.any(pm):
        return (Tool.COALPOWER, plant_x, plant_y)

    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Horizontal road spine row (just below plant center)
    road_row = plant_cy + 1
    road_row = max(3, min(WORLD_H - 4, road_row))

    # Vertical wire spine column (right of plant)
    wire_col = plant_cx + 2
    wire_col = max(3, min(WORLD_W - 4, wire_col))

    # How far to extend road and wire based on population
    if obs.city_pop < 100:
        road_extent = 15
        vert_extent = 10
    elif obs.city_pop < 300:
        road_extent = 25
        vert_extent = 15
    elif obs.city_pop < 600:
        road_extent = 35
        vert_extent = 20
    else:
        road_extent = 45
        vert_extent = 25

    road_start = max(1, plant_cx + 1)
    road_end = min(WORLD_W - 2, plant_cx + road_extent)
    wire_top = max(1, road_row - vert_extent)
    wire_bot = min(WORLD_H - 2, road_row + vert_extent)

    # Phase 2: Build wire spine (vertical) from plant up/down
    # Start adjacent to plant
    for r in range(plant_cy - 1, wire_top - 1, -1):
        if 0 <= r < WORLD_H and not wm[r, wire_col] and not pm[r, wire_col]:
            if em[r, wire_col]:
                return (Tool.WIRE, wire_col, r)
    for r in range(plant_cy + 2, wire_bot + 1):
        if 0 <= r < WORLD_H and not wm[r, wire_col] and not pm[r, wire_col]:
            if em[r, wire_col]:
                return (Tool.WIRE, wire_col, r)

    # Phase 3: Build horizontal road spine (west to east from plant)
    for c in range(road_start, road_end + 1):
        if 0 <= c < WORLD_W and not rm[road_row, c] and em[road_row, c] and not pm[road_row, c]:
            return (Tool.ROAD, c, road_row)

    # Phase 4: Build horizontal wires along road_row from wire_col outward
    # to power zones along the road spine
    wire_row = road_row  # wire runs along same row but on a parallel track
    # Actually run wire 1 row above road spine to not conflict
    w_row = road_row - 1
    if w_row >= 1:
        for c in range(wire_col, road_end + 2):
            if 0 <= c < WORLD_W and not wm[w_row, c] and not pm[w_row, c]:
                if em[w_row, c] or rm[w_row, c]:
                    if em[w_row, c]:
                        return (Tool.WIRE, c, w_row)

    # Phase 5: Place zones above and below road spine
    # Above: zone centers at road_row - 2 (just touching road)
    # Below: zone centers at road_row + 2
    # Zones every 4 columns along road

    all_zone_mask = resm | comm | indm

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=3):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    # Place zones: above road (row - 2), below road (row + 2)
    zone_cols = list(range(road_start + 2, road_end - 1, 4))
    zone_row_above = road_row - 2
    zone_row_below = road_row + 2

    for zc in zone_cols:
        if zc < 2 or zc > WORLD_W - 3:
            continue
        for zr in [zone_row_above, zone_row_below]:
            if zr < 2 or zr > WORLD_H - 3:
                continue
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_road_nearby(zr, zc) and has_wire_nearby(zr, zc):
                    return (pick_tool(), zc, zr)

    # Phase 6: Lateral wires to reach zones above road (wire at w_row may not be enough)
    # Add vertical wire segments from w_row up to zone_row_above
    for zc in zone_cols:
        if zc < 2 or zc > WORLD_W - 3:
            continue
        zr = zone_row_above
        if zr < 2:
            continue
        # Wire column at zc connecting w_row to zones
        for r in range(zr + 1, w_row):
            if 0 <= r < WORLD_H and 0 <= zc < WORLD_W:
                if not wm[r, zc] and em[r, zc] and not pm[r, zc]:
                    if has_wire_nearby(r + 1, zc, 1) or (r + 1 == w_row and wm[w_row, zc]):
                        return (Tool.WIRE, zc, r)

    # Phase 7: Wire below road to power lower zones
    w_row2 = road_row + 1
    if w_row2 < WORLD_H - 1:
        for c in range(wire_col, road_end + 2):
            if 0 <= c < WORLD_W and not wm[w_row2, c] and not pm[w_row2, c]:
                if em[w_row2, c]:
                    return (Tool.WIRE, c, w_row2)

    # Phase 8: Additional vertical roads for zone access
    # Add vertical road segments at zone column positions
    for zc in zone_cols[::2]:  # every other zone column
        if zc < 2 or zc > WORLD_W - 3:
            continue
        for r in range(max(1, zone_row_above - 1), min(WORLD_H - 1, zone_row_below + 2)):
            if 0 <= r < WORLD_H and not rm[r, zc] and em[r, zc] and not pm[r, zc]:
                return (Tool.ROAD, zc, r)

    # Phase 9: Second coal power plant when growing
    if obs.city_pop > 300 and np.sum(pm) < 9:
        # Place second plant far right
        px2 = min(WORLD_W - 5, road_end + 3)
        py2 = cy
        if em[py2, px2]:
            return (Tool.COALPOWER, px2, py2)
        # Try adjacent
        for dy in range(-3, 4):
            py3 = py2 + dy
            if 2 <= py3 <= WORLD_H - 3 and em[py3, px2]:
                return (Tool.COALPOWER, px2, py3)

    # Phase 10: Connect second plant to wire grid
    if np.sum(pm) >= 18:  # two plants exist
        plant_tiles = np.where(pm)
        # Find rightmost plant
        right_plant_c = int(np.max(plant_tiles[1]))
        right_plant_r = int(np.mean(plant_tiles[0][plant_tiles[1] >= right_plant_c - 1]))
        # Wire from right plant leftward to main wire
        for c in range(right_plant_c - 1, wire_col, -1):
            if 0 <= c < WORLD_W and not wm[right_plant_r, c] and not pm[right_plant_r, c]:
                if em[right_plant_r, c]:
                    return (Tool.WIRE, c, int(right_plant_r))
                else:
                    break

    # Phase 11: Expand zone rows further out
    if obs.city_pop > 400:
        zone_row_above2 = road_row - 5
        zone_row_below2 = road_row + 5
        for zc in zone_cols:
            if zc < 2 or zc > WORLD_W - 3:
                continue
            for zr in [zone_row_above2, zone_row_below2]:
                if zr < 2 or zr > WORLD_H - 3:
                    continue
                if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                    if has_road_nearby(zr, zc, 4) and has_wire_nearby(zr, zc, 5):
                        return (pick_tool(), zc, zr)

    # Phase 12: Police/fire stations for city services
    if obs.city_pop > 200:
        # Place police station near center
        ps_x, ps_y = cx + 5, cy - 5
        if 2 <= ps_x <= WORLD_W - 3 and 2 <= ps_y <= WORLD_H - 3:
            if em[ps_y, ps_x]:
                return (Tool.POLICESTATION, ps_x, ps_y)

    if obs.city_pop > 350:
        fs_x, fs_y = cx - 5, cy + 5
        if 2 <= fs_x <= WORLD_W - 3 and 2 <= fs_y <= WORLD_H - 3:
            if em[fs_y, fs_x]:
                return (Tool.FIRESTATION, fs_x, fs_y)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Each step reads tile_map to find where infrastructure already exists
    - Extends power/road/zones based on CURRENT map state
    - No fixed plan; adapts to what's actually there
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    # ---- Scan what exists ----
    has_plant = np.any(pm)
    has_wire = np.any(wm)
    has_road = np.any(rm)

    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    res_count = int(np.sum(res_m)) // 9 + 1
    com_count = int(np.sum(com_m)) // 9 + 1
    ind_count = int(np.sum(ind_m)) // 9 + 1

    # Phase 1: Place coal power plant if missing
    if not has_plant:
        # Place near left-center
        return (Tool.COALPOWER, 47, 50)

    # Find plant center
    plant_rows, plant_cols = np.where(pm)
    pcx = int(np.mean(plant_cols))
    pcy = int(np.mean(plant_rows))

    # ---- Determine spine positions from plant ----
    # Wire spine just right of plant
    wire_col = pcx + 3
    road_col_r = wire_col + 1   # road to the right of wire
    road_col_l = wire_col - 1   # road to the left of wire
    zone_col_r = road_col_r + 3  # zones right
    zone_col_l = road_col_l - 3  # zones left

    # Vertical extent based on current city pop
    cy = pcy
    half_span = min(35, max(8, 8 + obs.city_pop // 20))
    tmin = max(2, cy - half_span)
    tmax = min(WORLD_H - 3, cy + half_span)

    # ---- Phase 2: Extend wire spine vertically from plant ----
    wire_rows = sorted(r for r in range(WORLD_H) if wm[r, wire_col]) if 0 <= wire_col < WORLD_W else []

    if not wire_rows:
        # Place first wire adjacent to plant
        for dy in range(0, 4):
            ny = cy + dy
            if 0 <= ny < WORLD_H and 0 <= wire_col < WORLD_W:
                if em[ny, wire_col]:
                    return (Tool.WIRE, wire_col, ny)
        for dy in range(-3, 0):
            ny = cy + dy
            if 0 <= ny < WORLD_H and 0 <= wire_col < WORLD_W:
                if em[ny, wire_col]:
                    return (Tool.WIRE, wire_col, ny)
    else:
        min_wr = wire_rows[0]
        max_wr = wire_rows[-1]
        # Extend downward
        if max_wr < tmax:
            nr = max_wr + 1
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if min_wr > tmin:
            nr = min_wr - 1
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    wire_rows_set = set(wire_rows)

    # ---- Phase 3: Build road columns adjacent to wire ----
    if wire_rows:
        # Right road column
        if 0 <= road_col_r < WORLD_W:
            for wr in wire_rows:
                if not rm[wr, road_col_r] and em[wr, road_col_r]:
                    return (Tool.ROAD, road_col_r, wr)
        # Left road column
        if 0 <= road_col_l < WORLD_W:
            for wr in wire_rows:
                if not rm[wr, road_col_l] and em[wr, road_col_l]:
                    return (Tool.ROAD, road_col_l, wr)

    # ---- Zone placement helpers ----
    all_zone_m = res_m | com_m | ind_m

    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def nearby_zone(zr, zc, radius=2):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(all_zone_m[r0:r1, c0:c1])

    def pick_zone(col):
        # Balanced mix: ~50% res, 25% com, 25% ind
        if ind_count * 4 < res_count:
            return Tool.INDUSTRIAL
        elif com_count * 4 < res_count:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- Phase 4: Place zones adjacent to roads ----
    if wire_rows:
        road_rows_r = set(r for r in range(WORLD_H) if 0 <= road_col_r < WORLD_W and rm[r, road_col_r])
        road_rows_l = set(r for r in range(WORLD_H) if 0 <= road_col_l < WORLD_W and rm[r, road_col_l])

        for zr in wire_rows:
            wire_near = zr in wire_rows_set or (zr-1 in wire_rows_set) or (zr+1 in wire_rows_set)
            if not wire_near:
                continue

            # Right zones
            road_near_r = any(abs(zr - rr) <= 1 for rr in road_rows_r)
            if road_near_r and 0 <= zone_col_r < WORLD_W - 1:
                if not nearby_zone(zr, zone_col_r) and zone_area_free(zr, zone_col_r):
                    return (pick_zone(zone_col_r), zone_col_r, zr)

            # Left zones
            road_near_l = any(abs(zr - rr) <= 1 for rr in road_rows_l)
            if road_near_l and 1 <= zone_col_l < WORLD_W:
                if not nearby_zone(zr, zone_col_l) and zone_area_free(zr, zone_col_l):
                    return (pick_zone(zone_col_l), zone_col_l, zr)

    # ---- Phase 5: Second cluster when population grows ----
    if obs.city_pop > 150 and wire_rows:
        wire_col2 = zone_col_r + 5
        road_col_r2 = wire_col2 + 1
        road_col_l2 = wire_col2 - 1
        zone_col_r2 = road_col_r2 + 3
        zone_col_l2 = road_col_l2 - 3  # = zone_col_r + 1 approx

        if 0 <= wire_col2 < WORLD_W:
            wire_rows2 = sorted(r for r in range(WORLD_H) if wm[r, wire_col2])

            # Connect horizontal wire from spine to wire_col2
            if not wire_rows2:
                # Lay horizontal bridge at cy level
                for wc in range(wire_col + 1, wire_col2 + 1):
                    if 0 <= wc < WORLD_W and em[cy, wc]:
                        return (Tool.WIRE, wc, cy)
            else:
                min_wr2 = wire_rows2[0]
                max_wr2 = wire_rows2[-1]
                # Extend vertical
                if max_wr2 < tmax:
                    nr = max_wr2 + 1
                    if 0 <= nr < WORLD_H and (em[nr, wire_col2] or wm[nr, wire_col2]):
                        return (Tool.WIRE, wire_col2, nr)
                if min_wr2 > tmin:
                    nr = min_wr2 - 1
                    if 0 <= nr < WORLD_H and (em[nr, wire_col2] or wm[nr, wire_col2]):
                        return (Tool.WIRE, wire_col2, nr)

                # Right road for cluster 2
                if 0 <= road_col_r2 < WORLD_W:
                    for wr in wire_rows2:
                        if not rm[wr, road_col_r2] and em[wr, road_col_r2]:
                            return (Tool.ROAD, road_col_r2, wr)

                # Left road for cluster 2 (between wire_col and wire_col2)
                if 0 <= road_col_l2 < WORLD_W:
                    for wr in wire_rows2:
                        if not rm[wr, road_col_l2] and em[wr, road_col_l2]:
                            return (Tool.ROAD, road_col_l2, wr)

                # Zones for cluster 2
                road_rows_r2 = set(r for r in range(WORLD_H) if 0 <= road_col_r2 < WORLD_W and rm[r, road_col_r2])
                road_rows_l2 = set(r for r in range(WORLD_H) if 0 <= road_col_l2 < WORLD_W and rm[r, road_col_l2])
                wire_rows2_set = set(wire_rows2)

                for zr in wire_rows2:
                    wire_near2 = zr in wire_rows2_set or (zr-1 in wire_rows2_set) or (zr+1 in wire_rows2_set)
                    if not wire_near2:
                        continue
                    road_near_r2 = any(abs(zr - rr) <= 1 for rr in road_rows_r2)
                    if road_near_r2 and 0 <= zone_col_r2 < WORLD_W - 1:
                        if not nearby_zone(zr, zone_col_r2) and zone_area_free(zr, zone_col_r2):
                            return (pick_zone(zone_col_r2), zone_col_r2, zr)
                    road_near_l2 = any(abs(zr - rr) <= 1 for rr in road_rows_l2)
                    if road_near_l2 and 1 <= zone_col_l2 < WORLD_W:
                        if not nearby_zone(zr, zone_col_l2) and zone_area_free(zr, zone_col_l2):
                            return (pick_zone(zone_col_l2), zone_col_l2, zr)

    # ---- Phase 6: Second power plant if large city ----
    if obs.city_pop > 400 and not state.get("plant2_placed", False):
        px2 = pcx + 25
        py2 = pcy
        clear = all(
            0 <= py2+dr < WORLD_H and 0 <= px2+dc < WORLD_W and em[py2+dr, px2+dc]
            for dr in [-1, 0, 1] for dc in [-1, 0, 1]
        )
        if clear:
            state["plant2_placed"] = True
            return (Tool.COALPOWER, px2, py2)
        # try connecting wire to it
        for wc in range(wire_col + 1, min(px2 + 1, WORLD_W)):
            if em[pcy, wc]:
                return (Tool.WIRE, wc, pcy)

    return None

def act(obs, state):
    """
    Closed-loop policy: each step reads the current map and decides
    the single best placement based on what's actually there.

    Strategy:
    - Coal plant near center-left
    - Wire spine grows vertically from plant, detected by scanning
    - Roads grow adjacent to wire spine
    - Zones placed adjacent to roads, balanced R/C/I
    - All decisions based on current tile_map observation
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    cx, cy = 60, 50

    # Phase 1: Ensure we have a power plant
    has_plant = np.any(pm)
    if not has_plant:
        # Place coal plant - center is (plant_cx, plant_cy), footprint 3x3
        pcx, pcy = cx - 12, cy
        return (Tool.COALPOWER, pcx, pcy)

    # Find plant center by scanning for plant tiles
    plant_rows, plant_cols = np.where(pm)
    if len(plant_rows) > 0:
        # Use centroid of plant tiles
        pcx = int(np.median(plant_cols))
        pcy = int(np.median(plant_rows))
    else:
        pcx, pcy = cx - 12, cy

    # Wire spine column: just to the right of the plant footprint
    wire_col = pcx + 3
    # Clamp to valid range
    wire_col = max(5, min(wire_col, WORLD_W - 6))

    # Road columns adjacent to wire
    road_col_r = wire_col + 1
    road_col_l = wire_col - 1

    # Zone columns
    zone_col_r = wire_col + 4  # right of right road
    zone_col_l = wire_col - 4  # left of left road

    # Find existing wire in wire_col
    wire_in_col = sorted(r for r in range(WORLD_H) if wm[r, wire_col])

    # Determine vertical span based on population
    pop_bonus = min(30, obs.city_pop // 20)
    span = 12 + pop_bonus
    tmin = max(2, cy - span)
    tmax = min(WORLD_H - 3, cy + span)

    # Phase 2: Build/extend wire spine
    if not wire_in_col:
        # Start wire adjacent to plant - find a row near plant center
        for dy in range(0, 5):
            for sign in [0, 1, -1, 2, -2]:
                ny = pcy + sign * dy
                if 0 <= ny < WORLD_H and 0 <= wire_col < WORLD_W:
                    if em[ny, wire_col]:
                        return (Tool.WIRE, wire_col, ny)
    else:
        min_wr = wire_in_col[0]
        max_wr = wire_in_col[-1]
        # Extend downward
        if max_wr < tmax:
            nr = max_wr + 1
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if min_wr > tmin:
            nr = min_wr - 1
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    wire_set = set(wire_in_col)

    # Phase 3: Build roads adjacent to wire spine
    # Right road column
    if wire_in_col and 0 <= road_col_r < WORLD_W:
        for wr in wire_in_col:
            if 0 <= wr < WORLD_H and em[wr, road_col_r]:
                return (Tool.ROAD, road_col_r, wr)

    # Left road column
    if wire_in_col and 0 <= road_col_l >= 0:
        for wr in wire_in_col:
            if 0 <= wr < WORLD_H and em[wr, road_col_l]:
                return (Tool.ROAD, road_col_l, wr)

    # Phase 4: Place zones adjacent to roads
    # Scan current zones for balance
    rz = res_mask(tm)
    cz = com_mask(tm)
    iz = ind_mask(tm)
    res_count = int(np.sum(rz)) // 9 + 1
    com_count = int(np.sum(cz)) // 9 + 1
    ind_count = int(np.sum(iz)) // 9 + 1

    # Find road positions
    road_rows_r = set(r for r in range(WORLD_H) if rm[r, road_col_r]) if 0 <= road_col_r < WORLD_W else set()
    road_rows_l = set(r for r in range(WORLD_H) if rm[r, road_col_l]) if 0 <= road_col_l >= 0 else set()

    all_zone_mask = rz | cz | iz

    def zone_area_clear(zr, zc):
        """Check 3x3 area around zone center is empty"""
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def zone_nearby(zr, zc, radius=2):
        """Check if any zone center is within radius"""
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(all_zone_mask[r0:r1, c0:c1])

    def pick_zone_tool(prefer_side):
        """Pick zone type based on current counts"""
        if ind_count * 3 < res_count:
            return Tool.INDUSTRIAL
        elif com_count * 3 < res_count:
            return Tool.COMMERCIAL
        else:
            return Tool.RESIDENTIAL

    # Right zones
    if 0 <= zone_col_r < WORLD_W:
        for wr in wire_in_col:
            # Need road within 2 rows
            road_near = any(abs(wr - rr) <= 2 for rr in road_rows_r)
            wire_near = wr in wire_set or any(abs(wr - w) <= 1 for w in wire_set)
            if road_near and wire_near:
                if not zone_nearby(wr, zone_col_r) and zone_area_clear(wr, zone_col_r):
                    tool = pick_zone_tool("right")
                    return (tool, zone_col_r, wr)

    # Left zones
    if 0 <= zone_col_l < WORLD_W:
        for wr in wire_in_col:
            road_near = any(abs(wr - rr) <= 2 for rr in road_rows_l)
            wire_near = wr in wire_set or any(abs(wr - w) <= 1 for w in wire_set)
            if road_near and wire_near:
                if not zone_nearby(wr, zone_col_l) and zone_area_clear(wr, zone_col_l):
                    tool = pick_zone_tool("left")
                    return (tool, zone_col_l, wr)

    # Phase 5: Connect zones to roads with lateral roads if needed
    # Right side: road from road_col_r+1 to zone_col_r-1
    for wr in wire_in_col:
        for rc in range(road_col_r + 1, zone_col_r):
            if 0 <= rc < WORLD_W and 0 <= wr < WORLD_H and em[wr, rc]:
                return (Tool.ROAD, rc, wr)
    # Left side: road from zone_col_l+1 to road_col_l-1
    for wr in wire_in_col:
        for rc in range(road_col_l - 1, zone_col_l, -1):
            if 0 <= rc < WORLD_W and 0 <= wr < WORLD_H and em[wr, rc]:
                return (Tool.ROAD, rc, wr)

    # Phase 6: Second expansion cluster when population is sufficient
    if obs.city_pop > 150:
        wire_col2 = zone_col_r + 5
        road_col_r2 = wire_col2 + 1
        zone_col_r2 = wire_col2 + 4

        if 0 <= wire_col2 < WORLD_W:
            wire_in_col2 = sorted(r for r in range(WORLD_H) if wm[r, wire_col2])

            # Connect from main wire spine horizontally at cy
            if not wire_in_col2:
                # Lay horizontal wire from wire_col to wire_col2
                for wc in range(wire_col + 1, wire_col2 + 1):
                    if 0 <= wc < WORLD_W and em[cy, wc]:
                        return (Tool.WIRE, wc, cy)
            else:
                min_wr2 = wire_in_col2[0]
                max_wr2 = wire_in_col2[-1]
                if max_wr2 < tmax:
                    nr = max_wr2 + 1
                    if em[nr, wire_col2] or wm[nr, wire_col2]:
                        return (Tool.WIRE, wire_col2, nr)
                if min_wr2 > tmin:
                    nr = min_wr2 - 1
                    if em[nr, wire_col2] or wm[nr, wire_col2]:
                        return (Tool.WIRE, wire_col2, nr)

                # Road column 2
                if 0 <= road_col_r2 < WORLD_W:
                    for wr in wire_in_col2:
                        if 0 <= wr < WORLD_H and em[wr, road_col_r2]:
                            return (Tool.ROAD, road_col_r2, wr)

                # Zones in second cluster
                road_rows_r2 = set(r for r in range(WORLD_H) if rm[r, road_col_r2]) if 0 <= road_col_r2 < WORLD_W else set()
                if 0 <= zone_col_r2 < WORLD_W:
                    for wr in wire_in_col2:
                        road_near = any(abs(wr - rr) <= 2 for rr in road_rows_r2)
                        if road_near:
                            if not zone_nearby(wr, zone_col_r2) and zone_area_clear(wr, zone_col_r2):
                                tool = pick_zone_tool("right2")
                                return (tool, zone_col_r2, wr)

                # Lateral roads for second cluster
                for wr in wire_in_col2:
                    for rc in range(road_col_r2 + 1, zone_col_r2):
                        if 0 <= rc < WORLD_W and 0 <= wr < WORLD_H and em[wr, rc]:
                            return (Tool.ROAD, rc, wr)

    # Phase 7: Second power plant if population large enough
    if obs.city_pop > 400 and not state.get("plant2_placed", False):
        p2cx = cx + 25
        p2cy = cy
        # Check area
        all_clear = True
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = p2cy + dr, p2cx + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if not em[rr, rc]:
                        all_clear = False
        if all_clear:
            state["plant2_placed"] = True
            return (Tool.COALPOWER, p2cx, p2cy)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder.
    Each step reads the current tile_map and decides the next placement
    based on what already exists - no pre-planned sequence.

    Strategy:
    1. Ensure coal plant exists near map center
    2. Extend wires from existing power sources toward zone areas
    3. Extend roads from existing roads to serve zones
    4. Place zones (balanced R/C/I) near both roads and power
    5. Add services when population warrants
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Central anchor
    cx, cy = WORLD_W // 2, WORLD_H // 2  # 60, 50

    # ---- Phase 1: Ensure power plant exists ----
    plant_ys, plant_xs = np.where(pm)
    has_plant = len(plant_xs) > 0
    if not has_plant:
        return (Tool.COALPOWER, cx - 3, cy)

    # ---- Phase 2: Extend wires from existing power ----
    # Wire spine: vertical at cx, plus horizontal connector
    # We grow wire outward from existing power (plant or wire)
    power_map = pm | wm

    # Find frontier: empty tiles adjacent to power
    # Priority: extend vertically first (spine), then horizontally
    def find_wire_extension():
        pys, pxs = np.where(power_map)
        if len(pxs) == 0:
            return None

        # Build candidate wire positions: adjacent to power, empty, not already wire/plant
        candidates = []
        for dy in range(-18, 19):
            candidates.append((cx, cy + dy))       # vertical spine
        for dx in range(-3, 5):
            candidates.append((cx + dx, cy))       # horizontal connector
        for dx in range(-3, 5):
            candidates.append((cx + dx, cy - 1))   # slightly above center

        for (wx, wy) in candidates:
            if not in_bounds(wx, wy):
                continue
            if bool(wm[wy, wx]) or bool(pm[wy, wx]):
                continue
            if not bool(em[wy, wx]):
                continue
            # Check if adjacent to existing power
            for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx2, ny2 = wx+ddx, wy+ddy
                if in_bounds(nx2, ny2) and bool(power_map[ny2, nx2]):
                    return (Tool.WIRE, wx, wy)
        return None

    wire_action = find_wire_extension()

    # ---- Phase 3: Extend roads from existing roads ----
    def find_road_extension():
        # Road targets: vertical roads flanking wire spine, plus horizontal cross-roads
        candidates = []
        # Vertical roads at cx+1 and cx-1 (flanking the wire spine)
        for dy in range(-18, 19):
            candidates.append((cx + 1, cy + dy))
            candidates.append((cx - 1, cy + dy))
        # Horizontal roads at intervals
        for offset in [-9, -6, -3, 0, 3, 6, 9]:
            for dx in range(-9, 10):
                candidates.append((cx + dx, cy + offset))

        for (rx, ry) in candidates:
            if not in_bounds(rx, ry):
                continue
            if bool(rm[ry, rx]):
                continue
            if bool(pm[ry, rx]) or bool(wm[ry, rx]):
                continue
            if not bool(em[ry, rx]):
                continue
            # Adjacent to existing road?
            for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx2, ny2 = rx+ddx, ry+ddy
                if in_bounds(nx2, ny2) and bool(rm[ny2, nx2]):
                    return (Tool.ROAD, rx, ry)
            # Adjacent to power plant (seed road)
            for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1),(2,0),(-2,0),(0,2),(0,-2)]:
                nx2, ny2 = rx+ddx, ry+ddy
                if in_bounds(nx2, ny2) and bool(pm[ny2, nx2]):
                    return (Tool.ROAD, rx, ry)
        return None

    road_action = find_road_extension()

    # Count zones for balance
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        if com_count / total_zones < 0.22:
            return Tool.COMMERCIAL
        if ind_count / total_zones < 0.22:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # ---- Phase 4: Place zones near roads AND power ----
    def find_zone_placement():
        # Compute neighborhood masks efficiently
        nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1,0),(1,0),(0,-1),(0,1),(-2,0),(2,0),(0,-2),(0,2)]:
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

        nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-7, 8):
            for dx in range(-7, 8):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
                nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

        zone_mask = resm | comm | indm
        cand = em & nbr_road & nbr_power
        # Keep away from edges
        cand[:2, :] = False
        cand[WORLD_H-2:, :] = False
        cand[:, :2] = False
        cand[:, WORLD_W-2:] = False

        cys, cxs = np.where(cand)
        if len(cxs) == 0:
            return None

        # Deterministic but reactive selection using tile_map sum + pop
        key = int(obs.tile_map.sum() % max(len(cxs), 1))
        for offset in range(min(len(cxs), 60)):
            k = (key + offset * 13) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            # Check 3x3 clearance
            ok = True
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    ny2, nx2 = zy + dr, zx + dc
                    if not in_bounds(nx2, ny2):
                        ok = False; break
                    if not (bool(em[ny2, nx2]) or bool(zone_mask[ny2, nx2])):
                        ok = False; break
                if not ok:
                    break
            if ok:
                return (pick_tool(), zx, zy)
        return None

    # ---- Decision logic: prioritize based on what's needed ----
    wire_count = int(np.sum(wm))
    road_count = int(np.sum(rm))

    # Need enough wires to power zones - build wire spine first
    # Count how many wire spine positions are filled
    spine_filled = sum(1 for dy in range(-18, 19)
                      if in_bounds(cx, cy+dy) and bool(wm[cy+dy, cx]))

    # Prioritize: plant -> initial wire spine -> road -> wire expansion -> zones
    if spine_filled < 10 and wire_action is not None:
        return wire_action

    if road_count < 5 and road_action is not None:
        return road_action

    # Interleave wire and road extension with zone placement
    # Use step parity and population to decide
    step_mod = obs.step % 6

    if step_mod in (0, 1) and wire_action is not None:
        return wire_action

    if step_mod in (2, 3) and road_action is not None:
        return road_action

    # Try zone placement
    zone_action = find_zone_placement()
    if zone_action is not None:
        return zone_action

    # Fallbacks
    if wire_action is not None:
        return wire_action
    if road_action is not None:
        return road_action

    # Services when pop warrants
    if obs.city_pop > 300:
        for fx, fy in [(cx+5, cy-12), (cx-5, cy+12)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 500:
        for fx, fy in [(cx+5, cy+12), (cx-5, cy-12)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.POLICESTATION, fx, fy)

    # Last resort: grow road from any existing road tile
    rys, rxs = np.where(rm)
    if len(rxs) > 0:
        k2 = int(obs.step * 17 + int(obs.city_pop)) % len(rxs)
        rx2, ry2 = int(rxs[k2]), int(rys[k2])
        for ddx, ddy in [(0,1),(1,0),(0,-1),(-1,0)]:
            nx2, ny2 = rx2+ddx, ry2+ddy
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Each step reads the current map and decides next action based on what exists
    - Builds: coal plant -> wire spine -> road column -> zones
    - Adapts zone placement to where power/road actually reaches
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    all_zone_mask = resm | comm | indm
    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_area_clear(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if all_zone_mask[rr, rc]:
                    return False
                # Allow road/wire tiles to be near zone but not IN zone 3x3
                if not em[rr, rc] and not rm[rr, rc] and not wm[rr, rc] and not pm[rr, rc]:
                    return False
                # Actually zone needs all 9 cells empty for placement
                if not em[rr, rc]:
                    return False
        return True

    def has_power_near(zr, zc, radius=4):
        r0, r1 = max(0, zr - radius), min(WORLD_H, zr + radius + 1)
        c0, c1 = max(0, zc - radius), min(WORLD_W, zc + radius + 1)
        return bool(np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1]))

    def has_road_near(zr, zc, radius=3):
        r0, r1 = max(0, zr - radius), min(WORLD_H, zr + radius + 1)
        c0, c1 = max(0, zc - radius), min(WORLD_W, zc + radius + 1)
        return bool(np.any(rm[r0:r1, c0:c1]))

    # ---- Step 1: Ensure power plant exists ----
    if not np.any(pm):
        # Place coal plant left of center
        px, py = cx - 8, cy
        return (Tool.COALPOWER, px, py)

    # Find plant location
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Wire spine column: immediately right of plant
    wire_col = plant_cx + 4
    wire_col = max(3, min(WORLD_W - 4, wire_col))

    # Road column: one right of wire
    road_col = wire_col + 2
    road_col = max(3, min(WORLD_W - 4, road_col))

    # Zone columns on each side
    left_zone_col = wire_col - 4
    left_zone_col = max(2, min(WORLD_W - 3, left_zone_col))
    right_zone_col = road_col + 3
    right_zone_col = max(2, min(WORLD_W - 3, right_zone_col))

    # Dynamic spine extent based on current population
    pop = obs.city_pop
    if pop < 100:
        spine_half = 8
    elif pop < 300:
        spine_half = 14
    elif pop < 600:
        spine_half = 20
    else:
        spine_half = 28

    spine_top = max(1, plant_cy - spine_half)
    spine_bot = min(WORLD_H - 2, plant_cy + spine_half)

    # ---- Step 2: Scan current wire spine ----
    wire_on_spine = [r for r in range(WORLD_H) if wm[r, wire_col]]
    road_on_col = [r for r in range(WORLD_H) if rm[r, road_col]]

    # ---- Step 3: Bootstrap wire adjacent to plant if none ----
    if not wire_on_spine:
        # Find an empty cell adjacent to plant in wire_col
        for dy in range(0, 8):
            for nr in [plant_cy + dy, plant_cy - dy]:
                if 0 <= nr < WORLD_H:
                    if em[nr, wire_col]:
                        return (Tool.WIRE, wire_col, nr)
        return None

    min_wr = min(wire_on_spine)
    max_wr = max(wire_on_spine)

    # ---- Step 4: Extend wire spine to cover target range ----
    # Extend downward
    if max_wr < spine_bot:
        nr = max_wr + 1
        if nr < WORLD_H and em[nr, wire_col] and not pm[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)

    # Extend upward
    if min_wr > spine_top:
        nr = min_wr - 1
        if nr >= 0 and em[nr, wire_col] and not pm[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)

    # ---- Step 5: Build road column alongside existing wire ----
    # Only build road where wire exists (reactive: follow the wire)
    for wr in wire_on_spine:
        if 0 <= road_col < WORLD_W and not rm[wr, road_col] and em[wr, road_col]:
            return (Tool.ROAD, road_col, wr)

    # ---- Step 6: Lateral wires left from spine toward left zone column ----
    # For each wire row, extend wire leftward to left_zone_col+1
    for wr in wire_on_spine:
        # Check if this row needs lateral wire left
        for wc in range(wire_col - 1, left_zone_col - 2, -1):
            if wc < 0:
                break
            if wm[wr, wc] or pm[wr, wc]:
                break
            if em[wr, wc]:
                return (Tool.WIRE, wc, wr)
            break  # blocked

    # ---- Step 7: Lateral roads rightward from road_col to right zone col ----
    for wr in road_on_col:
        for rc in range(road_col + 1, right_zone_col + 3):
            if rc >= WORLD_W:
                break
            if rm[wr, rc]:
                break
            if pm[wr, rc]:
                break
            if em[wr, rc]:
                return (Tool.ROAD, rc, wr)
            break

    # ---- Step 8: Lateral wires rightward to power right zones ----
    for wr in wire_on_spine:
        for wc in range(wire_col + 1, right_zone_col + 3):
            if wc >= WORLD_W:
                break
            if wm[wr, wc] or pm[wr, wc]:
                break
            if rm[wr, wc]:
                continue  # skip road, don't overwrite
            if em[wr, wc]:
                return (Tool.WIRE, wc, wr)
            break

    # ---- Step 9: Place zones reactively ----
    # Scan rows where wire actually exists and try to place zones
    zone_rows = sorted(set(wr for wr in wire_on_spine))

    # Group wire rows into clusters spaced ~3 apart
    placed_zone_rows = []
    for zr_candidate in range(spine_top + 1, spine_bot, 3):
        # Check if wire covers this row (within 1)
        wire_near_row = any(abs(zr_candidate - wr) <= 1 for wr in zone_rows)
        road_near_row = any(abs(zr_candidate - rr) <= 2 for rr in road_on_col)
        if not wire_near_row:
            continue

        # Try left zone
        zc = left_zone_col
        if zone_area_clear(zr_candidate, zc):
            if has_power_near(zr_candidate, zc, 5) and has_road_near(zr_candidate, zc, 5):
                return (pick_tool(), zc, zr_candidate)

        # Try right zone
        zc = right_zone_col
        if zone_area_clear(zr_candidate, zc):
            if has_road_near(zr_candidate, zc, 5) and has_power_near(zr_candidate, zc, 6):
                return (pick_tool(), zc, zr_candidate)

    # ---- Step 10: Add second power plant if needed ----
    plant_count = int(np.sum(pm))
    if pop > 200 and plant_count < 9:
        # Try placing another plant to the right
        for px2_offset in [20, 25, 30]:
            px2 = plant_cx + px2_offset
            py2 = plant_cy
            if 2 <= px2 <= WORLD_W - 4 and 2 <= py2 <= WORLD_H - 4:
                region = em[py2 - 1:py2 + 3, px2 - 1:px2 + 3]
                if region.shape == (4, 4) and np.all(region):
                    return (Tool.COALPOWER, px2, py2)
        # Try above
        px2 = plant_cx
        py2 = plant_cy - 16
        if 2 <= px2 <= WORLD_W - 4 and 2 <= py2 <= WORLD_H - 4:
            if np.all(em[py2 - 1:py2 + 3, px2 - 1:px2 + 3]):
                return (Tool.COALPOWER, px2, py2)

    # ---- Step 11: Fill gaps in wire spine ----
    for r in range(spine_top, spine_bot + 1):
        if not wm[r, wire_col] and not pm[r, wire_col] and em[r, wire_col]:
            return (Tool.WIRE, wire_col, r)

    # ---- Step 12: Horizontal road for extra connectivity when pop growing ----
    if pop > 100:
        h_rows = [plant_cy - 6, plant_cy, plant_cy + 6]
        for rr in h_rows:
            if 0 <= rr < WORLD_H:
                for rc in range(max(0, left_zone_col - 1), min(WORLD_W, right_zone_col + 2)):
                    if em[rr, rc] and not pm[rr, rc]:
                        return (Tool.ROAD, rc, rr)

    # ---- Step 13: Expand zones outward if population justifies ----
    if pop > 300:
        extra_cols = [left_zone_col - 5, right_zone_col + 5]
        for zc in extra_cols:
            zc = max(2, min(WORLD_W - 3, zc))
            for zr in range(spine_top + 1, spine_bot, 3):
                if zone_area_clear(zr, zc):
                    if has_road_near(zr, zc, 8) and has_power_near(zr, zc, 8):
                        return (pick_tool(), zc, zr)

    return None

def act(obs, state):
    """
    Redesigned policy: horizontal road/wire layout instead of vertical spine.
    Places coal plant, runs wire horizontally, builds vertical road columns,
    and places zones in a grid pattern above and below the wire row.
    Uses proper zone spacing and mixed zone types.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # Use state to track build phase and progress
    if 'phase' not in state:
        state['phase'] = 0
        state['wire_progress'] = 0
        state['road_progress'] = 0

    # Layout constants - horizontal design
    # Plant at left side, wire runs horizontally through the middle
    plant_x, plant_y = 10, 50
    wire_row = 50          # horizontal wire row
    top_road_row = 44      # road row above wire
    bot_road_row = 56      # road row below wire

    # Zone columns: spaced every 6 across the map
    zone_cols = list(range(16, 100, 6))  # zone centers

    # Wire extends from plant rightward
    wire_start = plant_x + 4  # just past plant right edge
    wire_end = 102            # far right

    res_count = int(np.sum(res_m))
    com_count = int(np.sum(com_m))
    ind_count = int(np.sum(ind_m))
    has_plant = np.any(pm)

    # Phase 1: Place coal plant
    if not has_plant:
        return (Tool.COALPOWER, plant_x, plant_y)

    # Find actual plant position
    plant_positions = list(zip(*np.where(pm)))
    if plant_positions:
        pr, pc = plant_positions[0]
        plant_y = pr
        plant_x = pc
        wire_row = plant_y
        top_road_row = wire_row - 6
        bot_road_row = wire_row + 6
        wire_start = plant_x + 4

    # Clamp
    wire_row = max(4, min(WORLD_H - 5, wire_row))
    top_road_row = max(1, min(WORLD_H - 2, top_road_row))
    bot_road_row = max(1, min(WORLD_H - 2, bot_road_row))

    # Phase 2: Extend horizontal wire from plant
    # Find current wire extent
    wire_cols_in_row = sorted([c for c in range(WORLD_W) if wm[wire_row, c]])

    if not wire_cols_in_row:
        # Start wire adjacent to plant
        wc = wire_start
        if 0 <= wc < WORLD_W:
            return (Tool.WIRE, wc, wire_row)

    if wire_cols_in_row:
        cur_max = max(wire_cols_in_row)
        if cur_max < wire_end:
            nc = cur_max + 1
            if nc < WORLD_W and (em[wire_row, nc] or wm[wire_row, nc]):
                return (Tool.WIRE, nc, wire_row)

    # Phase 3: Build top and bottom road rows
    for zc in zone_cols:
        # Road segments at zone columns
        for c_off in range(-1, 2):
            rc = zc + c_off
            if 0 <= rc < WORLD_W:
                if not rm[top_road_row, rc]:
                    return (Tool.ROAD, rc, top_road_row)
                if not rm[bot_road_row, rc]:
                    return (Tool.ROAD, rc, bot_road_row)

    # Phase 4: Build vertical wire connectors from wire_row to road rows at each zone col
    for zc in zone_cols:
        if 0 <= zc < WORLD_W and wm[wire_row, zc]:
            # Connect upward to top road
            for r in range(wire_row - 1, top_road_row - 1, -1):
                if r >= 0 and not wm[r, zc]:
                    return (Tool.WIRE, zc, r)
            # Connect downward to bottom road
            for r in range(wire_row + 1, bot_road_row + 1):
                if r < WORLD_H and not wm[r, zc]:
                    return (Tool.WIRE, zc, r)

    # Helper functions
    def zone_clear(zr, zc):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                r2, c2 = zr + dr, zc + dc
                if r2 < 0 or r2 >= WORLD_H or c2 < 0 or c2 >= WORLD_W:
                    return False
                if not em[r2, c2]:
                    return False
        return True

    def zone_exists_near(zr, zc):
        r1, r2 = max(0, zr - 2), min(WORLD_H, zr + 3)
        c1, c2 = max(0, zc - 2), min(WORLD_W, zc + 3)
        return np.any(res_m[r1:r2, c1:c2]) or np.any(com_m[r1:r2, c1:c2]) or np.any(ind_m[r1:r2, c1:c2])

    def near_wire(zr, zc):
        r1, r2 = max(0, zr - 2), min(WORLD_H, zr + 3)
        c1, c2 = max(0, zc - 2), min(WORLD_W, zc + 3)
        return np.any(wm[r1:r2, c1:c2])

    def near_road(zr, zc):
        r1, r2 = max(0, zr - 2), min(WORLD_H, zr + 3)
        c1, c2 = max(0, zc - 2), min(WORLD_W, zc + 3)
        return np.any(rm[r1:r2, c1:c2])

    def pick_zone_type(idx):
        # Cycle through zone types based on position index and counts
        total = res_count + com_count + ind_count + 1
        if ind_count < total // 5:
            return Tool.INDUSTRIAL
        if com_count < total // 4:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Phase 5: Place zones above and below wire row
    top_zone_row = top_road_row - 3   # zone center above top road
    bot_zone_row = bot_road_row + 3   # zone center below bot road

    for i, zc in enumerate(zone_cols):
        if not (1 <= zc < WORLD_W - 1):
            continue

        # Top zones
        zr = top_zone_row
        if 1 <= zr < WORLD_H - 1:
            if not zone_exists_near(zr, zc):
                if zone_clear(zr, zc) and near_wire(zr, zc) and near_road(zr, zc):
                    return (pick_zone_type(i), zc, zr)

        # Bottom zones
        zr = bot_zone_row
        if 1 <= zr < WORLD_H - 1:
            if not zone_exists_near(zr, zc):
                if zone_clear(zr, zc) and near_wire(zr, zc) and near_road(zr, zc):
                    return (pick_zone_type(i + 1), zc, zr)

    # Phase 6: Add a second wire row above for expansion
    if obs.city_pop > 50 or obs.step > 200:
        wire_row2 = wire_row - 12
        if wire_row2 >= 4:
            wire_cols2 = sorted([c for c in range(WORLD_W) if wm[wire_row2, c]])
            if not wire_cols2:
                # Connect second wire row from plant area
                if wm[wire_row, wire_start]:
                    return (Tool.WIRE, wire_start, wire_row - 1)
            elif wire_cols2:
                # Extend it
                cur_max2 = max(wire_cols2)
                if cur_max2 < wire_end:
                    nc2 = cur_max2 + 1
                    if nc2 < WORLD_W and (em[wire_row2, nc2] or wm[wire_row2, nc2]):
                        return (Tool.WIRE, nc2, wire_row2)
                # Build vertical connector
                for wc2 in zone_cols:
                    if 0 <= wc2 < WORLD_W and wm[wire_row2, wc2]:
                        # Road row above wire2
                        road_row2 = wire_row2 - 6
                        if road_row2 >= 1:
                            for c_off in range(-1, 2):
                                rc = wc2 + c_off
                                if 0 <= rc < WORLD_W and not rm[road_row2, rc]:
                                    return (Tool.ROAD, rc, road_row2)
                        # Vertical wire from wire_row2 upward
                        for r in range(wire_row2 - 1, max(0, wire_row2 - 6), -1):
                            if not wm[r, wc2]:
                                return (Tool.WIRE, wc2, r)
                        # Zone above
                        zr2 = wire_row2 - 9
                        if 1 <= zr2 < WORLD_H - 1 and 1 <= wc2 < WORLD_W - 1:
                            if not zone_exists_near(zr2, wc2):
                                if zone_clear(zr2, wc2) and near_wire(zr2, wc2) and near_road(zr2, wc2):
                                    return (Tool.RESIDENTIAL, wc2, zr2)

    # Phase 7: Connect vertical segments between wire rows
    for wc in zone_cols:
        if 0 <= wc < WORLD_W:
            if wm[wire_row, wc]:
                wire_row2 = wire_row - 12
                if wire_row2 >= 0:
                    for r in range(wire_row - 1, wire_row2, -1):
                        if not wm[r, wc]:
                            return (Tool.WIRE, wc, r)

    # Phase 8: Extend roads between zone columns for connectivity
    for zc in zone_cols:
        if zc + 6 < WORLD_W:
            mid_c = zc + 3
            if not rm[top_road_row, mid_c] and em[top_road_row, mid_c]:
                return (Tool.ROAD, mid_c, top_road_row)
            if not rm[bot_road_row, mid_c] and em[bot_road_row, mid_c]:
                return (Tool.ROAD, mid_c, bot_road_row)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Each step reads the current tile_map and decides next action
    - Extends wire/road frontiers from existing infrastructure
    - Places zones where power and road are already present
    - Uses state only for minimal phase tracking
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    all_zone_mask = resm | comm | indm

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    # Step 1: Place coal plant if none exists
    if not np.any(pm):
        return (Tool.COALPOWER, cx - 8, cy)

    # Find plant center
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Layout: wire spine, road column, zone columns
    wire_col = plant_cx + 4
    road_col = wire_col + 2
    left_zone_col = wire_col - 3
    right_zone_col = road_col + 3

    wire_col = max(2, min(WORLD_W - 3, wire_col))
    road_col = max(2, min(WORLD_W - 3, road_col))
    left_zone_col = max(2, min(WORLD_W - 3, left_zone_col))
    right_zone_col = max(2, min(WORLD_W - 3, right_zone_col))

    # Dynamic spine extent based on current population
    pop = obs.city_pop
    if pop < 50:
        spine_extent = 8
    elif pop < 150:
        spine_extent = 14
    elif pop < 300:
        spine_extent = 20
    elif pop < 500:
        spine_extent = 28
    else:
        spine_extent = 36

    target_min = max(1, cy - spine_extent)
    target_max = min(WORLD_H - 2, cy + spine_extent)

    # Read current wire and road coverage on spine columns
    wire_rows_on_spine = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])
    road_rows_on_col = sorted([r for r in range(WORLD_H) if rm[r, road_col]])
    road_rows_set = set(road_rows_on_col)

    zone_rows = list(range(max(1, target_min), min(WORLD_H - 1, target_max + 1), 3))

    # Phase 2: Start wire from plant if none exists on spine
    if not wire_rows_on_spine:
        for dy in range(0, 8):
            for nr in [plant_cy + dy, plant_cy - dy]:
                if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                    return (Tool.WIRE, wire_col, nr)
        return None

    min_wire_row = min(wire_rows_on_spine)
    max_wire_row = max(wire_rows_on_spine)

    # Phase 3: Extend wire downward if needed
    if max_wire_row < target_max:
        nr = max_wire_row + 1
        if nr < WORLD_H and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Phase 4: Extend wire upward if needed
    if min_wire_row > target_min:
        nr = min_wire_row - 1
        if nr >= 0 and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Phase 5: Build road column reactively - place road where wire exists but road doesn't
    for r in wire_rows_on_spine:
        if 0 <= r < WORLD_H and 0 <= road_col < WORLD_W:
            if not rm[r, road_col] and (em[r, road_col] or wm[r, road_col]):
                return (Tool.ROAD, road_col, r)

    # Phase 6: Place lateral wires from spine toward left zone column
    # Only extend to rows where wire exists on spine
    for wr in wire_rows_on_spine:
        # Extend wire from spine leftward
        for wc in range(wire_col - 1, max(left_zone_col - 2, 0), -1):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc] and not wm[wr, wc]:
                    break

    # Phase 7: Extend road rightward to right zone column
    for rr in wire_rows_on_spine:
        if not rm[rr, road_col]:
            continue
        for rc in range(road_col + 1, right_zone_col + 2):
            if 0 <= rc < WORLD_W:
                if rm[rr, rc]:
                    break
                if em[rr, rc] and not pm[rr, rc]:
                    return (Tool.ROAD, rc, rr)
                elif not em[rr, rc]:
                    break

    # Phase 8: Extend wire rightward to power right zones
    for wr in wire_rows_on_spine:
        for wc in range(wire_col + 1, right_zone_col + 3):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc] or pm[wr, wc]:
                    break
                if rm[wr, wc]:
                    # Wire under road - skip, road already placed
                    continue
                if em[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc]:
                    break

    # Phase 9: Place zones where power and road are present
    for zr in zone_rows:
        wire_near = any(abs(zr - wr) <= 2 for wr in wire_rows_on_spine)
        road_near = any(abs(zr - rr) <= 2 for rr in road_rows_on_col)

        if wire_near and road_near:
            # Try left zone
            zc = left_zone_col
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc, 5) and has_road_nearby(zr, zc, 5):
                    return (pick_tool(), zc, zr)
                elif has_wire_nearby(zr, zc, 5) and has_road_nearby(zr, zc, 3):
                    return (Tool.RESIDENTIAL, zc, zr)

            # Try right zone
            zc = right_zone_col
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_road_nearby(zr, zc, 5) and has_wire_nearby(zr, zc, 6):
                    return (pick_tool(), zc, zr)

    # Phase 10: Second power plant when needed (check powered_zones vs total)
    if obs.city_pop > 200 and int(np.sum(pm)) < 9:
        # Place second plant offset from first
        px2 = plant_cx + 18
        py2 = plant_cy
        if 2 <= py2 <= WORLD_H - 3 and 2 <= px2 <= WORLD_W - 3:
            area_clear = all(
                em[py2 + dr, px2 + dc] or pm[py2 + dr, px2 + dc]
                for dr in [-1, 0, 1] for dc in [-1, 0, 1]
                if 0 <= py2 + dr < WORLD_H and 0 <= px2 + dc < WORLD_W
            )
            if area_clear:
                return (Tool.COALPOWER, px2, py2)

    # Phase 11: Second cluster to the right when pop >= 150
    if obs.city_pop >= 150:
        wire_col2 = road_col + 10
        road_col2 = wire_col2 + 2
        left_zone_col2 = wire_col2 - 3
        right_zone_col2 = road_col2 + 3

        wire_col2 = max(2, min(WORLD_W - 3, wire_col2))
        road_col2 = max(2, min(WORLD_W - 3, road_col2))
        left_zone_col2 = max(2, min(WORLD_W - 3, left_zone_col2))
        right_zone_col2 = max(2, min(WORLD_W - 3, right_zone_col2))

        wire_rows2 = sorted([r for r in range(WORLD_H) if wm[r, wire_col2]])
        road_rows2 = set(r for r in range(WORLD_H) if rm[r, road_col2])

        # Build horizontal wire bridge from main spine to cluster 2
        if not wire_rows2:
            bridge_row = plant_cy
            for wc in range(wire_col + 1, wire_col2 + 1):
                if 0 <= wc < WORLD_W:
                    if wm[bridge_row, wc] or pm[bridge_row, wc]:
                        continue
                    if em[bridge_row, wc]:
                        return (Tool.WIRE, wc, bridge_row)
                    else:
                        break
        else:
            min_wr2 = min(wire_rows2)
            max_wr2 = max(wire_rows2)

            if max_wr2 < target_max:
                nr = max_wr2 + 1
                if nr < WORLD_H and em[nr, wire_col2] and not pm[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > target_min:
                nr = min_wr2 - 1
                if nr >= 0 and em[nr, wire_col2] and not pm[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)

            for wr in wire_rows2:
                if wr not in road_rows2 and em[wr, road_col2]:
                    return (Tool.ROAD, road_col2, wr)

            for zr in zone_rows:
                wire_near2 = any(abs(zr - wr) <= 2 for wr in wire_rows2)
                road_near2 = any(abs(zr - rr) <= 2 for rr in road_rows2)
                if wire_near2 and road_near2:
                    for zc in [left_zone_col2, right_zone_col2]:
                        if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                            if has_wire_nearby(zr, zc, 6) and has_road_nearby(zr, zc, 5):
                                return (pick_tool(), zc, zr)

            # Lateral wire for left zones of cluster 2
            for wr in wire_rows2:
                for wc in range(wire_col2 - 1, max(left_zone_col2 - 2, 0), -1):
                    if wm[wr, wc]: break
                    if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    elif not em[wr, wc] and not wm[wr, wc]: break

            # Road extensions for right zones of cluster 2
            for wr in wire_rows2:
                if wr not in road_rows2: continue
                for rc in range(road_col2 + 1, right_zone_col2 + 2):
                    if 0 <= rc < WORLD_W:
                        if rm[wr, rc]: break
                        if em[wr, rc] and not pm[wr, rc]:
                            return (Tool.ROAD, rc, wr)
                        elif not em[wr, rc]: break

    # Phase 12: Left cluster when pop >= 300
    if obs.city_pop >= 300:
        wire_col3 = wire_col - 10
        road_col3 = wire_col3 - 2
        left_zone_col3 = road_col3 - 3
        right_zone_col3 = wire_col3 + 3

        wire_col3 = max(2, min(WORLD_W - 3, wire_col3))
        road_col3 = max(2, min(WORLD_W - 3, road_col3))
        left_zone_col3 = max(2, min(WORLD_W - 3, left_zone_col3))
        right_zone_col3 = max(2, min(WORLD_W - 3, right_zone_col3))

        wire_rows3 = sorted([r for r in range(WORLD_H) if wm[r, wire_col3]])
        road_rows3 = set(r for r in range(WORLD_H) if rm[r, road_col3])

        if not wire_rows3:
            bridge_row = plant_cy
            for wc in range(wire_col - 1, wire_col3 - 1, -1):
                if 0 <= wc < WORLD_W:
                    if wm[bridge_row, wc] or pm[bridge_row, wc]:
                        continue
                    if em[bridge_row, wc]:
                        return (Tool.WIRE, wc, bridge_row)
                    else:
                        break
        else:
            min_wr3 = min(wire_rows3)
            max_wr3 = max(wire_rows3)

            if max_wr3 < target_max:
                nr = max_wr3 + 1
                if nr < WORLD_H and em[nr, wire_col3] and not pm[nr, wire_col3]:
                    return (Tool.WIRE, wire_col3, nr)
            if min_wr3 > target_min:
                nr = min_wr3 - 1
                if nr >= 0 and em[nr, wire_col3] and not pm[nr, wire_col3]:
                    return (Tool.WIRE, wire_col3, nr)

            for wr in wire_rows3:
                if wr not in road_rows3 and em[wr, road_col3]:
                    return (Tool.ROAD, road_col3, wr)

            for zr in zone_rows:
                wire_near3 = any(abs(zr - wr) <= 2 for wr in wire_rows3)
                road_near3 = any(abs(zr - rr) <= 2 for rr in road_rows3)
                if wire_near3 and road_near3:
                    for zc in [right_zone_col3, left_zone_col3]:
                        if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                            if has_wire_nearby(zr, zc, 6) and has_road_nearby(zr, zc, 5):
                                return (pick_tool(), zc, zr)

            for wr in wire_rows3:
                for wc in range(wire_col3 + 1, min(right_zone_col3 + 2, WORLD_W)):
                    if wm[wr, wc]: break
                    if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    elif not em[wr, wc] and not wm[wr, wc]: break

            for wr in wire_rows3:
                if wr not in road_rows3: continue
                for rc in range(road_col3 - 1, max(left_zone_col3 - 2, 0), -1):
                    if 0 <= rc < WORLD_W:
                        if rm[wr, rc]: break
                        if em[wr, rc] and not pm[wr, rc]:
                            return (Tool.ROAD, rc, wr)
                        elif not em[wr, rc]: break

    # Phase 13: Fill gaps - look for unpowered zones and route wire to them
    if obs.city_pop > 100:
        # Find zones that have no wire nearby and try to extend wire to them
        zone_positions = np.argwhere(all_zone_mask)
        for pos in zone_positions[:20]:  # Check first 20 zones
            zr, zc = int(pos[0]), int(pos[1])
            if not has_wire_nearby(zr, zc, 3):
                # Find nearest wire point
                wire_positions = np.argwhere(wm)
                if len(wire_positions) > 0:
                    dists = np.abs(wire_positions[:, 0] - zr) + np.abs(wire_positions[:, 1] - zc)
                    nearest_idx = np.argmin(dists)
                    wr, wc_near = int(wire_positions[nearest_idx, 0]), int(wire_positions[nearest_idx, 1])
                    # Try to extend wire one step toward the zone
                    dr = np.sign(zr - wr)
                    dc = np.sign(zc - wc_near)
                    # Try row direction first
                    if dr != 0:
                        nr, nc = wr + int(dr), wc_near
                        if 0 <= nr < WORLD_H and 0 <= nc < WORLD_W and em[nr, nc]:
                            return (Tool.WIRE, nc, nr)
                    if dc != 0:
                        nr, nc = wr, wc_near + int(dc)
                        if 0 <= nr < WORLD_H and 0 <= nc < WORLD_W and em[nr, nc]:
                            return (Tool.WIRE, nc, nr)

    return None

def act(obs, state):
    """
    Horizontal corridor layout instead of vertical spine.
    Wire runs horizontally through the middle, roads above and below,
    zones placed in rows above/below the road strips.
    This creates a fundamentally different city shape than the vertical spine parent.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Phase 1: Place coal power plant in upper-left area
    if not np.any(pm):
        return (Tool.COALPOWER, 15, cy)

    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Horizontal layout: wire row in center, roads above and below
    wire_row = cy
    road_row_above = wire_row - 2   # road above wire
    road_row_below = wire_row + 2   # road below wire
    zone_row_above = road_row_above - 3  # zones above upper road
    zone_row_below = road_row_below + 3  # zones below lower road

    # Clamp all rows
    wire_row = max(2, min(WORLD_H - 3, wire_row))
    road_row_above = max(2, min(WORLD_H - 3, road_row_above))
    road_row_below = max(2, min(WORLD_H - 3, road_row_below))
    zone_row_above = max(2, min(WORLD_H - 3, zone_row_above))
    zone_row_below = max(2, min(WORLD_H - 3, zone_row_below))

    # Horizontal extent based on population
    if obs.city_pop < 100:
        corridor_half = 12
    elif obs.city_pop < 300:
        corridor_half = 20
    elif obs.city_pop < 600:
        corridor_half = 30
    else:
        corridor_half = 40

    # Start from right of plant
    start_x = plant_cx + 4
    end_x = min(WORLD_W - 3, start_x + corridor_half * 2)
    start_x = max(2, start_x)

    wire_cols = sorted(c for c in range(WORLD_W) if wm[wire_row, c])
    road_cols_above = set(c for c in range(WORLD_W) if rm[road_row_above, c])
    road_cols_below = set(c for c in range(WORLD_W) if rm[road_row_below, c])

    # Phase 2: Start wire adjacent to plant (horizontal)
    if not wire_cols:
        for dx in range(0, 6):
            for nc in [plant_cx + dx, plant_cx - dx]:
                if 0 <= nc < WORLD_W:
                    if em[wire_row, nc] or wm[wire_row, nc]:
                        return (Tool.WIRE, nc, wire_row)
        return None

    min_wc = min(wire_cols)
    max_wc = max(wire_cols)

    # Phase 3: Extend wire rightward
    if max_wc < end_x:
        nc = max_wc + 1
        if nc < WORLD_W and not pm[wire_row, nc]:
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # Phase 4: Extend wire leftward toward plant
    if min_wc > start_x:
        nc = min_wc - 1
        if nc >= 0 and not pm[wire_row, nc]:
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # Phase 5: Build road rows along wire corridor
    for wc in wire_cols:
        # Road above
        if wc not in road_cols_above and 0 <= road_row_above < WORLD_H:
            if em[road_row_above, wc]:
                return (Tool.ROAD, wc, road_row_above)
        # Road below
        if wc not in road_cols_below and 0 <= road_row_below < WORLD_H:
            if em[road_row_below, wc]:
                return (Tool.ROAD, wc, road_row_below)

    # Helper functions
    all_zone_mask = resm | comm | indm

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        # Balanced mix: 50% res, 30% com, 20% ind
        if com_count / t < 0.30:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Phase 6: Place zones above and below roads
    zone_cols_list = list(range(start_x, min(WORLD_W - 2, end_x + 1), 3))

    for zc in zone_cols_list:
        wire_near = any(abs(zc - wc) <= 2 for wc in wire_cols)
        road_near_above = any(abs(zc - rc) <= 2 for rc in road_cols_above)
        road_near_below = any(abs(zc - rc) <= 2 for rc in road_cols_below)

        if not wire_near:
            continue

        # Zones above upper road
        if road_near_above:
            zr = zone_row_above
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                return (pick_tool(), zc, zr)

        # Zones below lower road
        if road_near_below:
            zr = zone_row_below
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                return (pick_tool(), zc, zr)

    # Phase 7: Connect wire to plant with lateral wire
    if wire_cols and min(wire_cols) > plant_cx + 2:
        nc = min(wire_cols) - 1
        if 0 <= nc < WORLD_W and (em[wire_row, nc] or wm[wire_row, nc]):
            return (Tool.WIRE, nc, wire_row)

    # Phase 8: Second coal plant when zones grow large
    if obs.city_pop > 300 and int(np.sum(pm)) < 9:
        px2 = min(WORLD_W - 3, max_wc + 8) if wire_cols else cx + 20
        py2 = cy
        if 2 <= py2 <= WORLD_H - 3 and 2 <= px2 <= WORLD_W - 3:
            area_ok = True
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    rr, rc = py2 + dr, px2 + dc
                    if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                        if not em[rr, rc]:
                            area_ok = False
            if area_ok:
                return (Tool.COALPOWER, px2, py2)

    # Phase 9: Second horizontal corridor (offset vertically)
    if obs.city_pop > 400:
        wire_row2 = cy + 12
        road_row2_above = wire_row2 - 2
        road_row2_below = wire_row2 + 2
        zone_row2_above = road_row2_above - 3
        zone_row2_below = road_row2_below + 3

        wire_row2 = max(2, min(WORLD_H - 3, wire_row2))
        road_row2_above = max(2, min(WORLD_H - 3, road_row2_above))
        road_row2_below = max(2, min(WORLD_H - 3, road_row2_below))
        zone_row2_above = max(2, min(WORLD_H - 3, zone_row2_above))
        zone_row2_below = max(2, min(WORLD_H - 3, zone_row2_below))

        wire_cols2 = sorted(c for c in range(WORLD_W) if wm[wire_row2, c])
        road_cols2_above = set(c for c in range(WORLD_W) if rm[road_row2_above, c])
        road_cols2_below = set(c for c in range(WORLD_W) if rm[road_row2_below, c])

        if not wire_cols2:
            # Connect vertically from first corridor at plant_cx area
            connect_col = plant_cx + 2
            for wr in range(min(wire_row, wire_row2), max(wire_row, wire_row2) + 1):
                if not wm[wr, connect_col] and (em[wr, connect_col] or rm[wr, connect_col]):
                    return (Tool.WIRE, connect_col, wr)
        else:
            min_wc2 = min(wire_cols2)
            max_wc2 = max(wire_cols2)

            if max_wc2 < end_x:
                nc = max_wc2 + 1
                if nc < WORLD_W and not pm[wire_row2, nc]:
                    if em[wire_row2, nc] or wm[wire_row2, nc]:
                        return (Tool.WIRE, nc, wire_row2)

            # Roads along second corridor
            for wc in wire_cols2:
                if wc not in road_cols2_above:
                    if em[road_row2_above, wc]:
                        return (Tool.ROAD, wc, road_row2_above)
                if wc not in road_cols2_below:
                    if em[road_row2_below, wc]:
                        return (Tool.ROAD, wc, road_row2_below)

            # Zones for second corridor
            for zc in zone_cols_list:
                wire_near2 = any(abs(zc - wc) <= 2 for wc in wire_cols2)
                road_near2_a = any(abs(zc - rc) <= 2 for rc in road_cols2_above)
                road_near2_b = any(abs(zc - rc) <= 2 for rc in road_cols2_below)

                if not wire_near2:
                    continue

                if road_near2_a:
                    zr = zone_row2_above
                    if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                        return (pick_tool(), zc, zr)

                if road_near2_b:
                    zr = zone_row2_below
                    if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                        return (pick_tool(), zc, zr)

    # Phase 10: Fill missing road segments
    for wc in wire_cols:
        if wc not in road_cols_above and 0 <= road_row_above < WORLD_H:
            if em[road_row_above, wc]:
                return (Tool.ROAD, wc, road_row_above)
        if wc not in road_cols_below and 0 <= road_row_below < WORLD_H:
            if em[road_row_below, wc]:
                return (Tool.ROAD, wc, road_row_below)

    return None

def act(obs, state):
    """
    Improved policy: horizontal corridor instead of vertical spine.
    - Place coal power plant, then build horizontal road + wire rows
    - Place zones above and below the road corridor
    - Mix res/com/ind zones properly
    - Add second power plant when needed
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    all_zone_mask = resm | comm | indm

    # Use center-left area for our city cluster
    cx, cy = 35, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        if com_count / t < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return bool(np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1]))

    def has_road_nearby(zr, zc, radius=3):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return bool(np.any(rm[r0:r1, c0:c1]))

    # Phase 1: Place coal power plant if missing
    if not np.any(pm):
        # Place plant at left side, vertically centered
        px, py = cx - 8, cy
        return (Tool.COALPOWER, px, py)

    # Find plant centroid
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Horizontal layout: wire row just below plant, road row below wire
    wire_row = plant_cy + 4
    road_row = wire_row + 1
    top_zone_row = wire_row - 4   # zones above wire
    bottom_zone_row = road_row + 4  # zones below road

    wire_row = max(3, min(WORLD_H - 4, wire_row))
    road_row = max(3, min(WORLD_H - 4, road_row))
    top_zone_row = max(2, min(WORLD_H - 3, top_zone_row))
    bottom_zone_row = max(2, min(WORLD_H - 3, bottom_zone_row))

    # Corridor width based on population
    if obs.city_pop < 50:
        corridor_extent = 10
    elif obs.city_pop < 200:
        corridor_extent = 18
    elif obs.city_pop < 500:
        corridor_extent = 28
    else:
        corridor_extent = 40

    target_min_col = max(1, plant_cx + 2)
    target_max_col = min(WORLD_W - 2, plant_cx + 2 + corridor_extent)

    wire_cols_on_row = sorted([c for c in range(WORLD_W) if wm[wire_row, c]])
    road_cols_on_row = sorted([c for c in range(WORLD_W) if rm[road_row, c]])

    # Phase 2: Bootstrap wire row adjacent to plant (horizontally)
    if not wire_cols_on_row:
        for dc in range(0, 6):
            for nc in [plant_cx + dc, plant_cx - dc]:
                if target_min_col <= nc < WORLD_W and 0 <= wire_row < WORLD_H:
                    if em[wire_row, nc] or wm[wire_row, nc]:
                        return (Tool.WIRE, nc, wire_row)
        return None

    min_wire_col = min(wire_cols_on_row)
    max_wire_col = max(wire_cols_on_row)

    # Phase 3: Extend wire row rightward
    if max_wire_col < target_max_col:
        nc = max_wire_col + 1
        if nc < WORLD_W and not pm[wire_row, nc]:
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # Phase 4: Build road row parallel to wire row
    for c in range(target_min_col, target_max_col + 1):
        if 0 <= c < WORLD_W and 0 <= road_row < WORLD_H:
            if not rm[road_row, c] and em[road_row, c]:
                return (Tool.ROAD, c, road_row)

    # Phase 5: Vertical wires from wire row upward to power top zones
    for wc in wire_cols_on_row:
        for wr in range(wire_row - 1, top_zone_row - 2, -1):
            if 0 <= wr < WORLD_H:
                if wm[wr, wc] or pm[wr, wc]:
                    break
                if em[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                else:
                    break

    # Phase 6: Vertical roads upward to connect top zones
    for rc in wire_cols_on_row:
        if not rm[road_row, rc]:
            continue
        for rr in range(road_row - 1, top_zone_row - 2, -1):
            if 0 <= rr < WORLD_H:
                if rm[rr, rc]:
                    break
                if pm[rr, rc]:
                    break
                if em[rr, rc]:
                    return (Tool.ROAD, rc, rr)
                else:
                    break

    # Phase 7: Vertical wires downward to power bottom zones
    for wc in wire_cols_on_row:
        for wr in range(wire_row + 1, bottom_zone_row + 2):
            if 0 <= wr < WORLD_H:
                if wm[wr, wc] or pm[wr, wc]:
                    break
                if rm[wr, wc]:
                    continue
                if em[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                else:
                    break

    # Phase 8: Place zones along corridor
    zone_cols = list(range(max(1, target_min_col + 1), min(WORLD_W - 1, target_max_col), 4))

    for zc in zone_cols:
        wire_near = any(abs(zc - wc) <= 2 for wc in wire_cols_on_row)
        road_near = any(abs(zc - rc) <= 2 for rc in road_cols_on_row)

        if wire_near and road_near:
            # Top zone
            zr = top_zone_row
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc, 5) and has_road_nearby(zr, zc, 5):
                    return (pick_tool(), zc, zr)

            # Bottom zone
            zr = bottom_zone_row
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc, 5) and has_road_nearby(zr, zc, 5):
                    return (pick_tool(), zc, zr)

    # Phase 9: Second coal plant when population growing
    plant_count = int(np.sum(pm))
    if obs.city_pop > 200 and plant_count < 9:
        # Place second plant further right along wire row
        px2 = plant_cx + 25
        py2 = plant_cy
        if 2 <= px2 <= WORLD_W - 4 and 2 <= py2 <= WORLD_H - 4:
            region = tm[py2-1:py2+2, px2-1:px2+2]
            if np.all(em[py2-1:py2+2, px2-1:px2+2]):
                return (Tool.COALPOWER, px2, py2)
        # Try below
        px2 = plant_cx + 10
        py2 = plant_cy + 15
        if 2 <= px2 <= WORLD_W - 4 and 2 <= py2 <= WORLD_H - 4:
            if np.all(em[py2-1:py2+2, px2-1:px2+2]):
                return (Tool.COALPOWER, px2, py2)

    # Phase 10: Add second zone rows further from corridor
    if obs.city_pop > 300:
        far_top = top_zone_row - 5
        far_bottom = bottom_zone_row + 5
        for zc in zone_cols:
            for zr in [far_top, far_bottom]:
                zr = max(2, min(WORLD_H - 3, zr))
                if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                    if has_road_nearby(zr, zc, 7) and has_wire_nearby(zr, zc, 8):
                        return (pick_tool(), zc, zr)

    # Phase 11: Fill any gaps in wire row
    for c in range(target_min_col, target_max_col + 1):
        if not wm[wire_row, c] and not pm[wire_row, c] and em[wire_row, c]:
            return (Tool.WIRE, c, wire_row)

    # Phase 12: Vertical roads from road row down to bottom zones
    for rc in range(target_min_col, target_max_col + 1, 4):
        if 0 <= rc < WORLD_W and rm[road_row, rc]:
            for rr in range(road_row + 1, bottom_zone_row + 2):
                if 0 <= rr < WORLD_H:
                    if rm[rr, rc]:
                        break
                    if pm[rr, rc]:
                        break
                    if em[rr, rc]:
                        return (Tool.ROAD, rc, rr)
                    else:
                        break

    return None

def act(obs, state):
    """
    Hybrid policy combining Parent A's pre-planned layout with Parent B's reactive logic.
    Strategy:
    - Pre-plan a compact cluster: coal plant, wire spine, road grid, balanced zones
    - Use reactive fallback to keep expanding
    - Two neighborhoods connected with roads/wires
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Build the action queue on first call
    if 'queue' not in state:
        actions = []

        # === CENTER CLUSTER ===
        # Coal plant at (57, 50) - center of map
