        # Connect plant to spine: horizontal wire at y=50
        for wx in range(58, 61):
            actions.append((Tool.WIRE, wx, 50))

        # Horizontal roads at y=33, 40, 47, 54, 61, 68
        road_rows = [33, 40, 47, 54, 61, 68]
        for ry in road_rows:
            for rx in range(45, 76):
                actions.append((Tool.ROAD, rx, ry))

        # Vertical roads at x=45, x=52, x=59 (just left of spine), x=64, x=72
        road_cols = [45, 52, 63, 72]
        for rcx in road_cols:
            for rcy in range(33, 69):
                actions.append((Tool.ROAD, rcx, rcy))

        # Wire horizontal branches at each road row to distribute power
        for wy_b in road_rows:
            for wx_b in range(45, 76):
                actions.append((Tool.WIRE, wx_b, wy_b))

        # Place zones in the grid cells between roads
        # Zone centers between road rows and road cols
        zone_row_centers = [36, 43, 50, 57, 64]
        zone_col_centers = [48, 55, 66, 69]

        # Alternate zone types: R, C, I pattern
        zone_types = [Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.INDUSTRIAL,
                      Tool.RESIDENTIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL,
                      Tool.INDUSTRIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL,
                      Tool.INDUSTRIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL,
                      Tool.INDUSTRIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL,
                      Tool.INDUSTRIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL,
                      Tool.INDUSTRIAL, Tool.RESIDENTIAL]

        zidx = 0
        for zy in zone_row_centers:
            for zx in zone_col_centers:
                t = zone_types[zidx % len(zone_types)]
                actions.append((t, zx, zy))
                zidx += 1

        # Second coal plant on right side for more coverage
        px2, py2 = 80, 50
        actions.append((Tool.COALPOWER, px2, py2))
        # Wire connecting second plant to spine area
        for wx2 in range(73, 81):
            actions.append((Tool.WIRE, wx2, 50))

        # Extend spine and roads to right neighborhood
        spine_x2 = 78
        for wy in range(30, 71):
            actions.append((Tool.WIRE, spine_x2, wy))

        # More zones on the right
        zone_col_centers2 = [82, 85, 88, 91]
        road_rows2 = [33, 40, 47, 54, 61, 68]
        for ry in road_rows2:
            for rx in range(76, 96):
                actions.append((Tool.ROAD, rx, ry))
        road_cols2 = [82, 89, 94]
        for rcx in road_cols2:
            for rcy in range(33, 69):
                actions.append((Tool.ROAD, rcx, rcy))
        for wy_b in road_rows2:
            for wx_b in range(76, 96):
                actions.append((Tool.WIRE, wx_b, wy_b))

        zone_row_centers2 = [36, 43, 50, 57, 64]
        zone_col_centers2 = [84, 91]
        for zy in zone_row_centers2:
            for zx in zone_col_centers2:
                t = zone_types[zidx % len(zone_types)]
                actions.append((t, zx, zy))
                zidx += 1

        # Left neighborhood
        px3, py3 = 40, 50
        actions.append((Tool.COALPOWER, px3, py3))
        for wx3 in range(41, 46):
            actions.append((Tool.WIRE, wx3, 50))
        spine_x3 = 43
        for wy in range(30, 71):
            actions.append((Tool.WIRE, spine_x3, wy))

        for ry in road_rows:
            for rx in range(25, 46):
                actions.append((Tool.ROAD, rx, ry))
        road_cols3 = [26, 30, 36]
        for rcx in road_cols3:
            for rcy in range(33, 69):
                actions.append((Tool.ROAD, rcx, rcy))
        for wy_b in road_rows:
            for wx_b in range(25, 46):
                actions.append((Tool.WIRE, wx_b, wy_b))

        zone_col_centers3 = [28, 33, 38]
        for zy in zone_row_centers:
            for zx in zone_col_centers3:
                t = zone_types[zidx % len(zone_types)]
                actions.append((t, zx, zy))
