        # Fire and police stations
        actions.append((Tool.FIRESTATION, 60, 52))
        actions.append((Tool.POLICESTATION, 60, 46))

        state['queue'] = actions
        state['zidx'] = zidx

    # Execute queued actions
    if state['queue']:
        while state['queue']:
            action = state['queue'].pop(0)
            tool, ax, ay = action
            ax = max(0, min(WORLD_W - 1, ax))
            ay = max(0, min(WORLD_H - 1, ay))

            # For zones, check 3x3 clearance
            if tool in (Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.INDUSTRIAL):
                ok = True
                for dy in range(-1, 2):
                    for dx in range(-1, 2):
                        ny2, nx2 = ay + dy, ax + dx
                        if not in_bounds(nx2, ny2):
                            ok = False; break
                        # Allow placing on existing zone tiles or empty
                        if not (bool(em[ny2, nx2])):
                            ok = False; break
                    if not ok:
                        break
                if not ok:
                    continue  # Skip this zone, try next action
            return (tool, ax, ay)

    # === REACTIVE FALLBACK ===
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        if com_count / total_zones < 0.25:
            return Tool.COMMERCIAL
        if ind_count / total_zones < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Reactive: find wire extension
    def find_wire_ext():
        cx2, cy2 = 60, 50
        candidates = []
        for dy in range(-20, 21):
            candidates.append((60, cy2 + dy))
            candidates.append((78, cy2 + dy))
            candidates.append((43, cy2 + dy))
        for dx in range(-15, 16):
            for yr in [33, 40, 47, 54, 61, 68]:
                candidates.append((cx2 + dx, yr))
        power_map = pm | wm
        for (wx, wy) in candidates:
            if not in_bounds(wx, wy): continue
            if bool(wm[wy, wx]) or bool(pm[wy, wx]): continue
            if not bool(em[wy, wx]): continue
            for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx2, ny2 = wx+ddx, wy+ddy
                if in_bounds(nx2, ny2) and bool(power_map[ny2, nx2]):
                    return (Tool.WIRE, wx, wy)
        return None

    def find_road_ext():
        cx2, cy2 = 60, 50
        candidates = []
        for dy in range(-20, 21):
            for xoff in [45, 52, 63, 72, 82, 89, 26, 30, 36]:
                candidates.append((xoff, cy2 + dy))
        for yr in [33, 40, 47, 54, 61, 68]:
            for dx in range(-35, 36):
                candidates.append((cx2 + dx, yr))
        for (rx, ry) in candidates:
            if not in_bounds(rx, ry): continue
            if bool(rm[ry, rx]): continue
            if bool(pm[ry, rx]) or bool(wm[ry, rx]): continue
            if not bool(em[ry, rx]): continue
            for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx2, ny2 = rx+ddx, ry+ddy
                if in_bounds(nx2, ny2) and bool(rm[ny2, nx2]):
                    return (Tool.ROAD, rx, ry)
        return None

    def find_zone():
        nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1,0),(1,0),(0,-1),(0,1),(-2,0),(2,0),(0,-2),(0,2)]:
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H+dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W+dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

        nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-8, 9):
            for dx in range(-8, 9):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
                r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H+dy)
                c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W+dx)
                nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
                nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

        zone_mask = resm | comm | indm
        cand = em & nbr_road & nbr_power
        cand[:2, :] = False; cand[WORLD_H-2:, :] = False
        cand[:, :2] = False; cand[:, WORLD_W-2:] = False

        cys2, cxs2 = np.where(cand)
        if len(cxs2) == 0:
            return None

        key = int(obs.tile_map.sum() % max(len(cxs2), 1))
        for offset in range(min(len(cxs2), 80)):
            k = (key + offset * 17) % len(cxs2)
            zx, zy = int(cxs2[k]), int(cys2[k])
            ok = True
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    ny2, nx2 = zy+dr, zx+dc
                    if not in_bounds(nx2, ny2):
                        ok = False; break
                    if not bool(em[ny2, nx2]):
                        ok = False; break
                if not ok:
                    break
            if ok:
                return (pick_tool(), zx, zy)
        return None

    step_mod = obs.step % 5
    wire_act = find_wire_ext()
    road_act = find_road_ext()

    if step_mod in (0, 1) and wire_act:
        return wire_act
    if step_mod in (2, 3) and road_act:
        return road_act

    zone_act = find_zone()
    if zone_act:
        return zone_act
    if wire_act:
        return wire_act
    if road_act:
        return road_act

    if obs.city_pop > 400:
        for fx, fy in [(62, 52), (58, 46), (75, 52), (47, 46)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 700:
        for fx, fy in [(62, 46), (58, 52), (75, 46), (47, 52)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.POLICESTATION, fx, fy)

    return None

def act(obs, state):
