    if wire_cols:
        # Bottom road row
        if 0 <= road_row < WORLD_H:
            for wc in wire_cols:
                if 0 <= wc < WORLD_W and not rm[road_row, wc] and em[road_row, wc]:
                    return (Tool.ROAD, wc, road_row)
        # Top road row
        if 0 <= road_row2 < WORLD_H:
            for wc in wire_cols:
                if 0 <= wc < WORLD_W and not rm[road_row2, wc] and em[road_row2, wc]:
                    return (Tool.ROAD, wc, road_row2)

    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    all_zone_m = res_m | com_m | ind_m

    def nearby_zone(zr, zc, radius=2):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(all_zone_m[r0:r1, c0:c1])

    def pick_zone():
        # Target: 50% res, 30% com, 20% ind
        total = res_count + com_count + ind_count
        if ind_count / total < 0.20:
            return Tool.INDUSTRIAL
        if com_count / total < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Phase 4: Place zones off the road rows
    if wire_cols:
        road_cols_bot = set(c for c in range(WORLD_W) if 0 <= road_row < WORLD_H and rm[road_row, c])
        road_cols_top = set(c for c in range(WORLD_W) if 0 <= road_row2 < WORLD_H and rm[road_row2, c])

        # Place zones every 6 columns (zone width 3 + gap 3)
        for zc in range(wire_start + 3, wire_end - 2, 6):
            if not (0 <= zc < WORLD_W):
                continue
            road_near_bot = any(abs(zc - rc) <= 1 for rc in road_cols_bot)
            road_near_top = any(abs(zc - rc) <= 1 for rc in road_cols_top)

            # Bottom zones
            zr_bot = zone_row_bot
            if 0 <= zr_bot < WORLD_H and road_near_bot:
                if not nearby_zone(zr_bot, zc) and zone_area_free(zr_bot, zc):
                    return (pick_zone(), zc, zr_bot)

            # Top zones
            zr_top = zone_row_top
            if 0 <= zr_top < WORLD_H and road_near_top:
                if not nearby_zone(zr_top, zc) and zone_area_free(zr_top, zc):
                    return (pick_zone(), zc, zr_top)

    # Phase 5: Second horizontal cluster below, triggered by population
    if obs.city_pop > 100:
        wire_row2 = wire_row + 12
        road_row3 = wire_row2 + 1
        road_row4 = wire_row2 - 1
        zone_row_bot2 = road_row3 + 3
        zone_row_top2 = road_row4 - 3

        if wire_row2 < WORLD_H - 4:
            # Connect vertical wire from first spine to second spine at pcx+3
            link_col = wire_start
            if 0 <= link_col < WORLD_W:
                for wr in range(min(wire_row + 1, wire_row2), max(wire_row, wire_row2) + 1):
                    if 0 <= wr < WORLD_H and not wm[wr, link_col] and em[wr, link_col]:
                        return (Tool.WIRE, link_col, wr)

            wire_cols2 = sorted(c for c in range(WORLD_W) if wm[wire_row2, c])
            if not wire_cols2:
                for dx in range(0, 5):
                    nx = wire_start + dx
                    if 0 <= nx < WORLD_W and em[wire_row2, nx]:
                        return (Tool.WIRE, nx, wire_row2)
            else:
                max_wc2 = max(wire_cols2)
                if max_wc2 < wire_end:
                    nx = max_wc2 + 1
                    if 0 <= nx < WORLD_W and (em[wire_row2, nx] or wm[wire_row2, nx]):
                        return (Tool.WIRE, nx, wire_row2)

                # Roads for cluster 2
                if 0 <= road_row3 < WORLD_H:
                    for wc in wire_cols2:
                        if 0 <= wc < WORLD_W and not rm[road_row3, wc] and em[road_row3, wc]:
                            return (Tool.ROAD, wc, road_row3)
                if 0 <= road_row4 < WORLD_H:
                    for wc in wire_cols2:
                        if 0 <= wc < WORLD_W and not rm[road_row4, wc] and em[road_row4, wc]:
                            return (Tool.ROAD, wc, road_row4)

                road_cols_bot2 = set(c for c in range(WORLD_W) if 0 <= road_row3 < WORLD_H and rm[road_row3, c])
                road_cols_top2 = set(c for c in range(WORLD_W) if 0 <= road_row4 < WORLD_H and rm[road_row4, c])

                for zc in range(wire_start + 3, wire_end - 2, 6):
                    if not (0 <= zc < WORLD_W):
                        continue
                    road_near_b2 = any(abs(zc - rc) <= 1 for rc in road_cols_bot2)
                    road_near_t2 = any(abs(zc - rc) <= 1 for rc in road_cols_top2)
                    zr_b2 = zone_row_bot2
                    if 0 <= zr_b2 < WORLD_H and road_near_b2:
                        if not nearby_zone(zr_b2, zc) and zone_area_free(zr_b2, zc):
                            return (pick_zone(), zc, zr_b2)
                    zr_t2 = zone_row_top2
                    if 0 <= zr_t2 < WORLD_H and road_near_t2:
                        if not nearby_zone(zr_t2, zc) and zone_area_free(zr_t2, zc):
                            return (pick_zone(), zc, zr_t2)

    # Phase 6: Second power plant if needed
    if obs.city_pop > 300 and not state.get("plant2_placed", False):
        px2 = pcx + 30
        py2 = pcy
        clear = all(
            0 <= py2+dr < WORLD_H and 0 <= px2+dc < WORLD_W and em[py2+dr, px2+dc]
            for dr in [-1, 0, 1] for dc in [-1, 0, 1]
        )
        if clear:
            state["plant2_placed"] = True
            return (Tool.COALPOWER, px2, py2)
        # Lay wire toward plant2 position
        for wc in range(wire_start, min(px2 + 1, WORLD_W)):
            if em[pcy, wc] and not wm[pcy, wc]:
                return (Tool.WIRE, wc, pcy)

    return None

def act(obs, state):
    """
    Hybrid policy: vertical wire spine from Parent A + zone density from Parent B.
    - Coal plant placed first, wire spine runs vertically
    - Road columns on both sides of wire spine
    - Zones placed adjacent to roads, powered via wire
    - Multiple zone types balanced (RES/COM/IND)
    - Expands span as population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool(prefer=None):
        if prefer is not None:
            return prefer
        t = max(1, total_zones)
        # Target: 40% res, 35% com, 25% ind
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        if com_count / t < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Layout constants
    cx, cy = 55, 50
    plant_cx, plant_cy = cx - 10, cy

    # Main vertical spine columns
    wire_col = plant_cx + 4
    road_col_r = wire_col + 1
    road_col_l = wire_col - 1
    zone_col_r = road_col_r + 3   # right zone column center
    zone_col_l = road_col_l - 3   # left zone column center

    # Second spine further right
    wire_col2 = wire_col + 12
    road_col_r2 = wire_col2 + 1
    road_col_l2 = wire_col2 - 1
    zone_col_r2 = road_col_r2 + 3
    zone_col_l2 = road_col_l2 - 3

    # Vertical span based on population
    base_span = 12
    extra = min(30, obs.city_pop // 20)
    target_span = base_span + extra
    tmin = max(2, cy - target_span)
    tmax = min(WORLD_H - 3, cy + target_span)

    has_plant = np.any(pm)

    # Phase 1: Place coal power plant
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Get wire/road positions
    wire_rows1 = sorted(r for r in range(WORLD_H) if wm[r, wire_col])
    wire_rows2 = sorted(r for r in range(WORLD_H) if wm[r, wire_col2])
    road_rows_r = set(r for r in range(WORLD_H) if rm[r, road_col_r])
    road_rows_l = set(r for r in range(WORLD_H) if rm[r, road_col_l])
    road_rows_r2 = set(r for r in range(WORLD_H) if rm[r, road_col_r2])
    road_rows_l2 = set(r for r in range(WORLD_H) if rm[r, road_col_l2])

    all_zone_mask = resm | comm | indm

    def zone_area_free(zr, zc):
        """Check 3x3 area is all empty or existing zone tiles."""
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-2, -1, 0, 1, 2]:
            for dc in [-2, -1, 0, 1, 2]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    # Phase 2: Build wire spine 1
    if not wire_rows1:
        # Start wire adjacent to plant
        for dy in range(-2, 3):
            ny = plant_cy + dy
            if 0 <= ny < WORLD_H and 0 <= wire_col < WORLD_W:
                if em[ny, wire_col] or wm[ny, wire_col]:
                    return (Tool.WIRE, wire_col, ny)
    else:
        min_wr = min(wire_rows1)
        max_wr = max(wire_rows1)
        # Extend downward
        if max_wr < tmax:
            nr = max_wr + 1
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if min_wr > tmin:
            nr = min_wr - 1
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    # Phase 3: Build road columns adjacent to wire spine 1
    if wire_rows1:
        for wr in wire_rows1:
            if wr not in road_rows_r and 0 <= road_col_r < WORLD_W and em[wr, road_col_r]:
                return (Tool.ROAD, road_col_r, wr)
            if wr not in road_rows_l and 0 <= road_col_l >= 0 and em[wr, road_col_l]:
                return (Tool.ROAD, road_col_l, wr)

    # Phase 4: Place zones along spine 1
    if wire_rows1:
        wire_set1 = set(wire_rows1)
        for wr in wire_rows1:
            # Right zone
            zc = zone_col_r
            zr = wr
            if (0 <= zr < WORLD_H and 1 <= zc < WORLD_W - 1
                    and not zone_already_there(zr, zc)
                    and zone_area_free(zr, zc)):
                road_near = any(abs(wr - rr) <= 2 for rr in road_rows_r)
                wire_near = any(abs(wr - ww) <= 1 for ww in wire_set1)
                if road_near and wire_near:
                    return (pick_tool(), zc, zr)

            # Left zone
            zc = zone_col_l
            zr = wr
            if (0 <= zr < WORLD_H and 1 <= zc < WORLD_W - 1
                    and not zone_already_there(zr, zc)
                    and zone_area_free(zr, zc)):
                road_near = any(abs(wr - rr) <= 2 for rr in road_rows_l)
                wire_near = any(abs(wr - ww) <= 1 for ww in wire_set1)
                if road_near and wire_near:
                    return (pick_tool(), zc, zr)

    # Phase 5: Lateral roads from spine to zone cols
    if wire_rows1:
        for wr in wire_rows1:
            # Right lateral
            for rc in range(road_col_r + 1, zone_col_r):
                if 0 <= rc < WORLD_W and em[wr, rc]:
                    return (Tool.ROAD, rc, wr)
            # Left lateral wire
            for wc in range(wire_col - 1, zone_col_l, -1):
                if 0 <= wc < WORLD_W and em[wr, wc]:
                    return (Tool.WIRE, wc, wr)

    # Phase 6: Second wire spine (expand when pop grows)
    if obs.city_pop >= 100:
        if not wire_rows2:
            # Connect horizontally from main spine
            for wc in range(wire_col + 1, wire_col2 + 1):
                if 0 <= wc < WORLD_W:
                    wr = cy
                    if em[wr, wc] or wm[wr, wc]:
                        return (Tool.WIRE, wc, wr)
        else:
            min_wr2 = min(wire_rows2)
            max_wr2 = max(wire_rows2)
            if max_wr2 < tmax:
                nr = max_wr2 + 1
                if 0 <= nr < WORLD_H and (em[nr, wire_col2] or wm[nr, wire_col2]):
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > tmin:
                nr = min_wr2 - 1
                if 0 <= nr < WORLD_H and (em[nr, wire_col2] or wm[nr, wire_col2]):
                    return (Tool.WIRE, wire_col2, nr)

            # Roads for spine 2
            for wr in wire_rows2:
                if wr not in road_rows_r2 and 0 <= road_col_r2 < WORLD_W and em[wr, road_col_r2]:
                    return (Tool.ROAD, road_col_r2, wr)
                if wr not in road_rows_l2 and 0 <= road_col_l2 < WORLD_W and em[wr, road_col_l2]:
                    return (Tool.ROAD, road_col_l2, wr)

            # Zones for spine 2
            wire_set2 = set(wire_rows2)
            for wr in wire_rows2:
                for zc in [zone_col_r2, zone_col_l2]:
                    zr = wr
                    if (0 <= zr < WORLD_H and 1 <= zc < WORLD_W - 1
                            and not zone_already_there(zr, zc)
                            and zone_area_free(zr, zc)):
                        road_rows_ref = road_rows_r2 if zc == zone_col_r2 else road_rows_l2
                        road_near = any(abs(wr - rr) <= 2 for rr in road_rows_ref)
                        wire_near = any(abs(wr - ww) <= 1 for ww in wire_set2)
                        if road_near and wire_near:
                            return (pick_tool(), zc, zr)

            # Lateral roads for spine 2
            for wr in wire_rows2:
                for rc in range(road_col_r2 + 1, zone_col_r2):
                    if 0 <= rc < WORLD_W and em[wr, rc]:
                        return (Tool.ROAD, rc, wr)
                for wc in range(wire_col2 - 1, zone_col_l2, -1):
                    if 0 <= wc < WORLD_W and em[wr, wc]:
                        return (Tool.WIRE, wc, wr)

    # Phase 7: Second coal plant when population large
    if obs.city_pop > 400 and not state.get("second_plant", False):
        px, py = wire_col2 - 5, cy
        clear = True
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = py + dr, px + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if not (em[rr, rc] or pm[rr, rc]):
                        clear = False
                        break
        if clear:
            state["second_plant"] = True
            return (Tool.COALPOWER, px, py)

    return None

def act(obs, state):
    """
    Combined policy:
    - Reactive (reads tile_map each step like Parent B)
    - Compact cluster: plant + wire spine + road col + zones on both sides (Parent A layout)
    - Multiple power plants as city grows
    - Balanced R/C/I zones
    - Second cluster when population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_area_clear(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def nearby_zone(zr, zc, radius=2):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        all_zone_m = resm | comm | indm
        return bool(np.any(all_zone_m[r0:r1, c0:c1]))

    pop = obs.city_pop

    # ---- Phase 0: Place first coal plant ----
    # Fixed position near center-left
    plant_x, plant_y = 54, 50
    if not np.any(pm):
        return (Tool.COALPOWER, plant_x, plant_y)

    # Find plant center from map
    plant_rows, plant_cols = np.where(pm)
    pcx = int(np.mean(plant_cols))
    pcy = int(np.mean(plant_rows))

    # Spine layout relative to plant
    wire_col = pcx + 3
    road_col = wire_col + 1
    left_zcol = wire_col - 4   # left zone center
    right_zcol = road_col + 4  # right zone center

    wire_col   = max(2, min(WORLD_W - 3, wire_col))
    road_col   = max(2, min(WORLD_W - 3, road_col))
    left_zcol  = max(2, min(WORLD_W - 3, left_zcol))
    right_zcol = max(2, min(WORLD_W - 3, right_zcol))

    # Adaptive spine half-length
    if pop < 50:
        spine_half = 12
    elif pop < 200:
        spine_half = 18
    elif pop < 500:
        spine_half = 25
    else:
        spine_half = 30

    spine_min = max(1, pcy - spine_half)
    spine_max = min(WORLD_H - 2, pcy + spine_half)
    spine_range = range(spine_min, spine_max + 1)

    # ---- Phase 1: Wire spine (vertical) ----
    for dy in spine_range:
        if 0 <= dy < WORLD_H:
            if not wm[dy, wire_col] and not pm[dy, wire_col] and not rm[dy, wire_col]:
                return (Tool.WIRE, wire_col, dy)

    # ---- Phase 2: Road column adjacent to wire ----
    for dy in spine_range:
        if 0 <= dy < WORLD_H:
            if not rm[dy, road_col] and not pm[dy, road_col] and not wm[dy, road_col]:
                return (Tool.ROAD, road_col, dy)

    wire_rows = [r for r in spine_range if 0 <= r < WORLD_H and wm[r, wire_col]]
    road_rows = [r for r in spine_range if 0 <= r < WORLD_H and rm[r, road_col]]

    # ---- Phase 3: Lateral wires leftward from wire spine ----
    # Extend wire from wire_col-1 down to left_zcol+1 at each wire row
    for wr in wire_rows:
        for wc in range(wire_col - 1, left_zcol, -1):
            if not (0 <= wc < WORLD_W):
                break
            if wm[wr, wc] or pm[wr, wc]:
                break
            if rm[wr, wc]:
                break
            if em[wr, wc]:
                return (Tool.WIRE, wc, wr)
            else:
                break

    # ---- Phase 4: Lateral wires rightward from road col ----
    # Right zones need power too
    for wr in wire_rows:
        for wc in range(road_col + 1, right_zcol + 1):
            if not (0 <= wc < WORLD_W):
                break
            if wm[wr, wc] or pm[wr, wc]:
                break
            if rm[wr, wc]:
                continue
            if em[wr, wc]:
                return (Tool.WIRE, wc, wr)
            else:
                break

    # ---- Phase 5: Place zones flanking spine ----
    zone_rows = list(range(spine_min + 1, spine_max - 1, 3))

    for zr in zone_rows:
        wire_near = any(abs(zr - wr) <= 1 for wr in wire_rows)
        road_near = any(abs(zr - rr) <= 1 for rr in road_rows)
        if not (wire_near and road_near):
            continue

        # Left zone: needs lateral wire
        zc = left_zcol
        lateral_wired_l = any(
            0 <= wc < WORLD_W and wm[zr, wc]
            for wc in range(zc - 1, wire_col)
        )
        if lateral_wired_l and not nearby_zone(zr, zc) and zone_area_clear(zr, zc):
            return (pick_tool(), zc, zr)

        # Right zone: needs lateral wire on right
        zc = right_zcol
        lateral_wired_r = any(
            0 <= wc < WORLD_W and wm[zr, wc]
            for wc in range(road_col, zc + 2)
        )
        if lateral_wired_r and not nearby_zone(zr, zc) and zone_area_clear(zr, zc):
            return (pick_tool(), zc, zr)

    # ---- Phase 6: Second power plant when population grows ----
    if pop > 200 and int(np.sum(pm)) < 9 and not state.get("plant2_placed", False):
        # Place second plant further right or left
        px2 = pcx - 20
        py2 = pcy
        px2 = max(2, min(WORLD_W - 3, px2))
        py2 = max(2, min(WORLD_H - 3, py2))
        clear = all(
            0 <= py2 + dr < WORLD_H and 0 <= px2 + dc < WORLD_W and em[py2 + dr, px2 + dc]
            for dr in [-1, 0, 1] for dc in [-1, 0, 1]
        )
        if clear:
            state["plant2_placed"] = True
            return (Tool.COALPOWER, px2, py2)
        # Try to wire connect it first
        for wc in range(px2 + 2, wire_col):
            if 0 <= wc < WORLD_W and em[py2, wc] and not pm[py2, wc]:
                return (Tool.WIRE, wc, py2)

    # ---- Phase 7: Second cluster of zones when population grows ----
    if pop > 150:
        wire_col2 = right_zcol + 5
        road_col2 = wire_col2 + 1
        left_zcol2 = wire_col2 - 4
        right_zcol2 = road_col2 + 4

        wire_col2   = max(2, min(WORLD_W - 3, wire_col2))
        road_col2   = max(2, min(WORLD_W - 3, road_col2))
        left_zcol2  = max(2, min(WORLD_W - 3, left_zcol2))
        right_zcol2 = max(2, min(WORLD_W - 3, right_zcol2))

        wire_rows2 = [r for r in spine_range if 0 <= r < WORLD_H and wm[r, wire_col2]]

        if not wire_rows2:
            # Lay horizontal wire from first spine to second spine at mid level
            mid = pcy
            for wc in range(wire_col + 1, wire_col2 + 1):
                if 0 <= wc < WORLD_W and em[mid, wc] and not pm[mid, wc]:
                    return (Tool.WIRE, wc, mid)
        else:
            min_wr2 = wire_rows2[0]
            max_wr2 = wire_rows2[-1]
            # Extend vertical wire spine 2
            if max_wr2 < spine_max:
                nr = max_wr2 + 1
                if 0 <= nr < WORLD_H and (em[nr, wire_col2] or wm[nr, wire_col2]) and not pm[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > spine_min:
                nr = min_wr2 - 1
                if 0 <= nr < WORLD_H and (em[nr, wire_col2] or wm[nr, wire_col2]) and not pm[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)

            # Road column for cluster 2
            for wr in wire_rows2:
                if 0 <= road_col2 < WORLD_W and not rm[wr, road_col2] and em[wr, road_col2]:
                    return (Tool.ROAD, road_col2, wr)

            road_rows2 = [r for r in spine_range if 0 <= r < WORLD_H and 0 <= road_col2 < WORLD_W and rm[r, road_col2]]

            # Lateral wires for cluster 2
            for wr in wire_rows2:
                for wc in range(wire_col2 - 1, left_zcol2, -1):
                    if not (0 <= wc < WORLD_W): break
                    if wm[wr, wc] or pm[wr, wc]: break
                    if rm[wr, wc]: break
                    if em[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    else:
                        break
                for wc in range(road_col2 + 1, right_zcol2 + 1):
                    if not (0 <= wc < WORLD_W): break
                    if wm[wr, wc] or pm[wr, wc]: break
                    if rm[wr, wc]: continue
                    if em[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    else:
                        break

            # Zones for cluster 2
            for zr in zone_rows:
                wire_near2 = any(abs(zr - wr) <= 1 for wr in wire_rows2)
                road_near2 = any(abs(zr - rr) <= 1 for rr in road_rows2)
                if not (wire_near2 and road_near2):
                    continue
                zc = left_zcol2
                lat_l2 = any(0 <= wc < WORLD_W and wm[zr, wc] for wc in range(zc - 1, wire_col2))
                if lat_l2 and not nearby_zone(zr, zc) and zone_area_clear(zr, zc):
                    return (pick_tool(), zc, zr)
                zc = right_zcol2
                lat_r2 = any(0 <= wc < WORLD_W and wm[zr, wc] for wc in range(road_col2, zc + 2))
                if lat_r2 and not nearby_zone(zr, zc) and zone_area_clear(zr, zc):
                    return (pick_tool(), zc, zr)

    # ---- Phase 8: Third power plant for large city ----
    if pop > 500 and int(np.sum(pm)) < 18 and not state.get("plant3_placed", False):
        px3 = pcx + 15
        py3 = pcy - 20
        px3 = max(2, min(WORLD_W - 3, px3))
        py3 = max(2, min(WORLD_H - 3, py3))
        clear = all(
            0 <= py3 + dr < WORLD_H and 0 <= px3 + dc < WORLD_W and em[py3 + dr, px3 + dc]
            for dr in [-1, 0, 1] for dc in [-1, 0, 1]
        )
        if clear:
            state["plant3_placed"] = True
            return (Tool.COALPOWER, px3, py3)

    return None

def act(obs, state):
    """
    New policy: vertical spine layout with zones on left/right sides.
    Road runs north-south, wire runs parallel.
    Multiple power plants placed early.
    Better zone spacing and mixed zone types.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    wire_col = 55       # vertical wire spine
    road_col = 57       # vertical road
    left_zone_col = 51  # zones to left of wire
    right_zone_col = 61 # zones to right of road

    # Power plants placed along the spine
    plant1_cx, plant1_cy = 55, 20
    plant2_cx, plant2_cy = 55, 60

    wire_positions = set(zip(*np.where(wm))) if np.any(wm) else set()
    road_positions = set(zip(*np.where(rm))) if np.any(rm) else set()
    res_positions = set(zip(*np.where(res_m))) if np.any(res_m) else set()
    com_positions = set(zip(*np.where(com_m))) if np.any(com_m) else set()
    ind_positions = set(zip(*np.where(ind_m))) if np.any(ind_m) else set()
    all_zones = res_positions | com_positions | ind_positions
    plant_positions = set(zip(*np.where(pm))) if np.any(pm) else set()

    res_count = len(res_positions)
    com_count = len(com_positions)
    ind_count = len(ind_positions)

    def has_plant_near(cx, cy, r=3):
        return any(abs(pr - cy) <= r and abs(pc - cx) <= r for (pr, pc) in plant_positions)

    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def already_zone_nearby(zr, zc, zones, dist=3):
        return any(abs(zr - pr) <= dist and abs(zc - pc) <= dist for (pr, pc) in zones)

    def pick_zone_type():
        # Target: 40% res, 35% com, 25% ind
        if res_count == 0:
            return Tool.RESIDENTIAL
        if com_count == 0:
            return Tool.COMMERCIAL
        if ind_count == 0:
            return Tool.INDUSTRIAL
        total = res_count + com_count + ind_count
        r_ratio = res_count / total
        c_ratio = com_count / total
        i_ratio = ind_count / total
        if i_ratio < 0.25:
            return Tool.INDUSTRIAL
        elif c_ratio < 0.35:
            return Tool.COMMERCIAL
        else:
            return Tool.RESIDENTIAL

    # Phase 1: Place first power plant
    if not has_plant_near(plant1_cx, plant1_cy):
        return (Tool.COALPOWER, plant1_cx, plant1_cy)

    # Phase 2: Build vertical wire spine from plant downward
    wire_rows_in_col = sorted(r for (r, c) in wire_positions if c == wire_col)
    road_rows_in_col = sorted(r for (r, c) in road_positions if c == road_col)

    # Target extent: from y=5 to y=85
    y_top = 5
    y_bot = min(85, 20 + 5 + min(50, obs.city_pop // 5))
    if obs.city_pop >= 200:
        y_bot = 85

    if not wire_rows_in_col:
        # Start wire just below plant1
        for tr in [plant1_cy + 3, plant1_cy + 2]:
            if 0 <= tr < WORLD_H and em[tr, wire_col]:
                return (Tool.WIRE, wire_col, tr)
    else:
        max_wr = max(wire_rows_in_col)
        min_wr = min(wire_rows_in_col)
        if max_wr < y_bot:
            nr = max_wr + 1
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        if min_wr > y_top:
            nr = min_wr - 1
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    if not wire_rows_in_col:
        return None

    wire_rows_set = set(wire_rows_in_col)
    road_rows_set = set(road_rows_in_col)

    # Phase 3: Build vertical road parallel to wire
    for wr in wire_rows_in_col:
        if wr not in road_rows_set and 0 <= road_col < WORLD_W:
            if em[wr, road_col]:
                return (Tool.ROAD, road_col, wr)

    # Phase 4: Place zones left and right of the spines every 3 rows
    for wr in sorted(wire_rows_in_col):
        for zc in [left_zone_col, right_zone_col]:
            if 2 <= zc < WORLD_W - 2 and 2 <= wr < WORLD_H - 2:
                if not already_zone_nearby(wr, zc, all_zones) and zone_area_free(wr, zc):
                    zt = pick_zone_type()
                    return (zt, zc, wr)

    # Phase 5: Connect zones to wire/road via horizontal wires
    for wr in wire_rows_in_col:
        # Left zone connection: wire from wire_col leftward
        for wc in range(wire_col - 1, left_zone_col - 2, -1):
            if 0 <= wc < WORLD_W and em[wr, wc]:
                return (Tool.WIRE, wc, wr)
            elif wm[wr, wc]:
                continue
            else:
                break

    # Phase 6: Place second power plant when enough wire
    if obs.city_pop >= 100 or len(wire_rows_in_col) >= 20:
        if not has_plant_near(plant2_cx, plant2_cy):
            # Place plant2 adjacent to wire
            if wire_col + 0 == plant2_cx:
                return (Tool.COALPOWER, plant2_cx, plant2_cy)

    # Phase 7: Second spine to the right for higher population
    if obs.city_pop >= 200:
        wire_col2 = 80
        road_col2 = 82
        left_zone_col2 = 76
        right_zone_col2 = 86
        plant3_cx, plant3_cy = 80, 30

        wire_rows2 = sorted(r for (r, c) in wire_positions if c == wire_col2)
        road_rows2 = set(r for (r, c) in road_positions if c == road_col2)

        if not has_plant_near(plant3_cx, plant3_cy):
            return (Tool.COALPOWER, plant3_cx, plant3_cy)

        if not wire_rows2:
            for tr in [plant3_cy + 3, plant3_cy + 2]:
                if 0 <= tr < WORLD_H and em[tr, wire_col2]:
                    return (Tool.WIRE, wire_col2, tr)
        else:
            max_wr2 = max(wire_rows2)
            min_wr2 = min(wire_rows2)
            if max_wr2 < 85:
                nr = max_wr2 + 1
                if 0 <= nr < WORLD_H and (em[nr, wire_col2] or wm[nr, wire_col2]):
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > 5:
                nr = min_wr2 - 1
                if 0 <= nr < WORLD_H and (em[nr, wire_col2] or wm[nr, wire_col2]):
                    return (Tool.WIRE, wire_col2, nr)

            for wr in wire_rows2:
                if wr not in road_rows2 and em[wr, road_col2]:
                    return (Tool.ROAD, road_col2, wr)

            for wr in sorted(wire_rows2):
                for zc in [left_zone_col2, right_zone_col2]:
                    if 2 <= zc < WORLD_W - 2 and 2 <= wr < WORLD_H - 2:
                        if not already_zone_nearby(wr, zc, all_zones) and zone_area_free(wr, zc):
                            zt = pick_zone_type()
                            return (zt, zc, wr)

    # Phase 8: Third spine to the left for very high population
    if obs.city_pop >= 400:
        wire_col3 = 30
        road_col3 = 32
        left_zone_col3 = 26
        right_zone_col3 = 36
        plant4_cx, plant4_cy = 30, 30

        wire_rows3 = sorted(r for (r, c) in wire_positions if c == wire_col3)
        road_rows3 = set(r for (r, c) in road_positions if c == road_col3)

        if not has_plant_near(plant4_cx, plant4_cy):
            return (Tool.COALPOWER, plant4_cx, plant4_cy)

        if not wire_rows3:
            for tr in [plant4_cy + 3, plant4_cy + 2]:
                if 0 <= tr < WORLD_H and em[tr, wire_col3]:
                    return (Tool.WIRE, wire_col3, tr)
        else:
            max_wr3 = max(wire_rows3)
            min_wr3 = min(wire_rows3)
            if max_wr3 < 85:
                nr = max_wr3 + 1
                if 0 <= nr < WORLD_H and (em[nr, wire_col3] or wm[nr, wire_col3]):
                    return (Tool.WIRE, wire_col3, nr)
            if min_wr3 > 5:
                nr = min_wr3 - 1
                if 0 <= nr < WORLD_H and (em[nr, wire_col3] or wm[nr, wire_col3]):
                    return (Tool.WIRE, wire_col3, nr)

            for wr in wire_rows3:
                if wr not in road_rows3 and em[wr, road_col3]:
                    return (Tool.ROAD, road_col3, wr)

            for wr in sorted(wire_rows3):
                for zc in [left_zone_col3, right_zone_col3]:
                    if 2 <= zc < WORLD_W - 2 and 2 <= wr < WORLD_H - 2:
                        if not already_zone_nearby(wr, zc, all_zones) and zone_area_free(wr, zc):
                            zt = pick_zone_type()
                            return (zt, zc, wr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Read current map every step
    - Place coal plant, then grow wire spine outward from plant
    - Grow roads adjacent to wire spine
    - Place zones adjacent to roads with wire nearby
    - Adapt based on what's actually on the map
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    all_zone_mask = resm | comm | indm
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_area_clear(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_exists_near(zr, zc, rad=2):
        r0, r1 = max(0, zr - rad), min(WORLD_H, zr + rad + 1)
        c0, c1 = max(0, zc - rad), min(WORLD_W, zc + rad + 1)
        return np.any(all_zone_mask[r0:r1, c0:c1])

    def wire_near(zr, zc, rad=4):
        r0, r1 = max(0, zr - rad), min(WORLD_H, zr + rad + 1)
        c0, c1 = max(0, zc - rad), min(WORLD_W, zc + rad + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def road_near(zr, zc, rad=3):
        r0, r1 = max(0, zr - rad), min(WORLD_H, zr + rad + 1)
        c0, c1 = max(0, zc - rad), min(WORLD_W, zc + rad + 1)
        return np.any(rm[r0:r1, c0:c1])

    # --- Phase 1: Ensure coal plant exists ---
    if not np.any(pm):
        # Place plant at a good location: left of center
        px, py = WORLD_W // 2 - 8, WORLD_H // 2
        return (Tool.COALPOWER, px, py)

    # Find plant center
    pr, pc = np.where(pm)
    plant_cy = int(np.mean(pr))
    plant_cx = int(np.mean(pc))

    # --- Define layout columns reactively ---
    # Wire spine: 3 cells right of plant center
    wire_col = plant_cx + 3
    wire_col = max(3, min(WORLD_W - 4, wire_col))

    # Roads: 3 cells each side of wire
    left_road_col = wire_col - 3
    right_road_col = wire_col + 3
    left_road_col = max(1, min(WORLD_W - 2, left_road_col))
    right_road_col = max(1, min(WORLD_W - 2, right_road_col))

    # Zone cols: 3 cells outside roads
    left_zone_col = left_road_col - 3
    right_zone_col = right_road_col + 3
    left_zone_col = max(2, min(WORLD_W - 3, left_zone_col))
    right_zone_col = max(2, min(WORLD_W - 3, right_zone_col))

    # Determine spine extent based on population
    pop = obs.city_pop
    if pop < 100:
        half_ext = 8
    elif pop < 300:
        half_ext = 15
    elif pop < 700:
        half_ext = 25
    else:
        half_ext = 38

    spine_top = max(1, plant_cy - half_ext)
    spine_bot = min(WORLD_H - 2, plant_cy + half_ext)

    # --- Phase 2: Wire spine: connect plant to wire_col first ---
    # Check if wire exists adjacent to plant on wire_col
    wire_on_spine = [(r, c) for r in range(WORLD_H) for c in [wire_col] if wm[r, c]]
    wire_rows = sorted([r for (r, c) in wire_on_spine])

    if not wire_rows:
        # Plant tiles: find closest row to plant_cy on wire_col
        for dy in range(0, 8):
            for nr in [plant_cy + dy, plant_cy - dy]:
                if 0 <= nr < WORLD_H:
                    if em[nr, wire_col]:
                        return (Tool.WIRE, wire_col, nr)
                    # If plant tile is adjacent to wire_col, wire there
        # Try to connect: place wire on spine at plant row
        r = plant_cy
        c = wire_col
        if 0 <= r < WORLD_H and 0 <= c < WORLD_W and not pm[r, c]:
            return (Tool.WIRE, c, r)
        return None

    min_wr = min(wire_rows)
    max_wr = max(wire_rows)

    # --- Phase 3: Grow wire spine downward ---
    if max_wr < spine_bot:
        nr = max_wr + 1
        if nr < WORLD_H and not pm[nr, wire_col] and em[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)
        elif nr < WORLD_H and not pm[nr, wire_col] and wm[nr, wire_col]:
            pass  # already wired, skip
        elif nr < WORLD_H and not pm[nr, wire_col]:
            # something else there, bulldoze-place wire anyway (auto-bulldoze on)
            if not rm[nr, wire_col] and not all_zone_mask[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # --- Phase 4: Grow wire spine upward ---
    if min_wr > spine_top:
        nr = min_wr - 1
        if nr >= 0 and not pm[nr, wire_col] and em[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)

    # Active spine rows
    active_rows = [r for r in wire_rows if spine_top <= r <= spine_bot]
    if not active_rows:
        active_rows = wire_rows

    # --- Phase 5: Left road column ---
    for r in active_rows:
        if 0 <= r < WORLD_H and 0 <= left_road_col < WORLD_W:
            if not rm[r, left_road_col] and not pm[r, left_road_col] and not all_zone_mask[r, left_road_col]:
                return (Tool.ROAD, left_road_col, r)

    # --- Phase 6: Right road column ---
    for r in active_rows:
        if 0 <= r < WORLD_H and 0 <= right_road_col < WORLD_W:
            if not rm[r, right_road_col] and not pm[r, right_road_col] and not all_zone_mask[r, right_road_col]:
                return (Tool.ROAD, right_road_col, r)

    # --- Phase 7: Lateral wires from spine to zone columns ---
    # Only wire rows that align with every 3rd row for zone placement
    zone_rows = list(range(max(2, spine_top + 1), min(WORLD_H - 2, spine_bot), 3))

    for zr in zone_rows:
        # Find closest wire row
        if zr not in wire_rows:
            continue

        # Wire left from spine to left_zone_col
        for wc in range(wire_col - 1, left_zone_col - 1, -1):
            if not (0 <= wc < WORLD_W):
                break
            if wm[zr, wc] or pm[zr, wc]:
                break
            if rm[zr, wc] or all_zone_mask[zr, wc]:
                break
            if em[zr, wc]:
                return (Tool.WIRE, wc, zr)

        # Wire right from spine to right_zone_col
        for wc in range(wire_col + 1, right_zone_col + 2):
            if not (0 <= wc < WORLD_W):
                break
            if wm[zr, wc] or pm[zr, wc]:
                break
            if rm[zr, wc] or all_zone_mask[zr, wc]:
                break
            if em[zr, wc]:
                return (Tool.WIRE, wc, zr)

    # --- Phase 8: Place zones reactively ---
    left_road_rows = set(r for r in range(WORLD_H) if rm[r, left_road_col])
    right_road_rows = set(r for r in range(WORLD_H) if rm[r, right_road_col])

    for zr in zone_rows:
        has_wire = zr in wire_rows

        if not has_wire:
            continue

        # Left zone
        left_road_ok = any(abs(zr - rr) <= 2 for rr in left_road_rows)
        if left_road_ok:
            zc = left_zone_col
            if not zone_exists_near(zr, zc, 2) and zone_area_clear(zr, zc):
                if wire_near(zr, zc, 5) and road_near(zr, zc, 4):
                    return (pick_tool(), zc, zr)

        # Right zone
        right_road_ok = any(abs(zr - rr) <= 2 for rr in right_road_rows)
        if right_road_ok:
            zc = right_zone_col
            if not zone_exists_near(zr, zc, 2) and zone_area_clear(zr, zc):
                if wire_near(zr, zc, 5) and road_near(zr, zc, 4):
                    return (pick_tool(), zc, zr)

        # Inner left (between left road and spine)
        if left_road_ok and wire_col - left_road_col >= 6:
            zc = wire_col - 2
            zc = max(2, min(WORLD_W - 3, zc))
            if zc != wire_col and zc != left_road_col:
                if not zone_exists_near(zr, zc, 2) and zone_area_clear(zr, zc):
                    if wire_near(zr, zc, 3) and road_near(zr, zc, 5):
                        return (pick_tool(), zc, zr)

        # Inner right (between spine and right road)
        if right_road_ok and right_road_col - wire_col >= 6:
            zc = wire_col + 2
            zc = max(2, min(WORLD_W - 3, zc))
            if zc != wire_col and zc != right_road_col:
                if not zone_exists_near(zr, zc, 2) and zone_area_clear(zr, zc):
                    if wire_near(zr, zc, 3) and road_near(zr, zc, 5):
                        return (pick_tool(), zc, zr)

    # --- Phase 9: Second power plant if population growing ---
    plant_tiles = int(np.sum(pm))
    if pop > 200 and plant_tiles < 18:
        # Place second plant above first plant
        px2 = plant_cx
        py2 = plant_cy - 12
        py2 = max(3, min(WORLD_H - 4, py2))
        if em[py2, px2]:
            return (Tool.COALPOWER, px2, py2)
        # Try right of first
        px2 = plant_cx + 15
        py2 = plant_cy
        px2 = max(3, min(WORLD_W - 4, px2))
        if 0 <= py2 < WORLD_H and 0 <= px2 < WORLD_W and em[py2, px2]:
            return (Tool.COALPOWER, px2, py2)

    # --- Phase 10: Connect wire from second plant ---
    if plant_tiles >= 18:
        pr2, pc2 = np.where(pm)
        # Find if there are plant tiles far from first plant center
        for r, c in zip(pr2, pc2):
            if abs(r - plant_cy) > 8 or abs(c - plant_cx) > 8:
                # Connect this plant to wire spine
                # Wire horizontally toward wire_col
                if c < wire_col:
                    for wc in range(c + 1, wire_col):
                        if 0 <= wc < WORLD_W and em[r, wc] and not wm[r, wc]:
                            return (Tool.WIRE, wc, r)
                elif c > wire_col:
                    for wc in range(c - 1, wire_col, -1):
                        if 0 <= wc < WORLD_W and em[r, wc] and not wm[r, wc]:
                            return (Tool.WIRE, wc, r)
                break

    # --- Phase 11: Horizontal roads at top/bottom for connectivity ---
    if pop > 100 and wire_rows:
        for h_row in [min(active_rows), max(active_rows)]:
            if 0 <= h_row < WORLD_H:
                for rc in range(left_zone_col - 1, right_zone_col + 2):
                    if 0 <= rc < WORLD_W and em[h_row, rc] and not pm[h_row, rc] and not wm[h_row, rc]:
                        return (Tool.ROAD, rc, h_row)

    # --- Phase 12: Far zone columns for large pop ---
    if pop > 500:
        far_left = left_zone_col - 4
        far_right = right_zone_col + 4
        for zc in [far_left, far_right]:
            if 2 <= zc <= WORLD_W - 3:
                for zr in zone_rows:
                    if not zone_exists_near(zr, zc, 2) and zone_area_clear(zr, zc):
                        if road_near(zr, zc, 7) and wire_near(zr, zc, 8):
                            return (pick_tool(), zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads map each step to decide what to place next
    - Builds a compact cluster: coal plant -> wire spine -> road spine -> zones
    - Zones placed reactively based on what power/road already covers
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    has_plant = np.any(pm)
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))

    # Build around a cluster center
    cx, cy = 60, 50

    # --- Phase 1: Place coal power plant ---
    if not has_plant:
        # Place plant at cx-6, cy (center); footprint cx-8..cx-4, cy-1..cy+1
        return (Tool.COALPOWER, cx - 8, cy)

    # Find plant center by finding plant tiles bounding box
    plant_rows, plant_cols = np.where(pm)
    if len(plant_rows) > 0:
        pcx = int(np.mean(plant_cols))
        pcy = int(np.mean(plant_rows))
    else:
        pcx, pcy = cx - 8, cy

    # Wire spine: vertical column at pcx+3 (just right of plant footprint)
    wire_col = pcx + 3
    # Road spine: vertical column at wire_col + 2
    road_col = wire_col + 2

    # Target wire extent: cy-15 to cy+15
    target_min_r = cy - 15
    target_max_r = cy + 15

    # --- Phase 2: Ensure wire connects plant to wire_col at pcy ---
    # Wire must exist adjacent to plant first
    # Check wire at wire_col, pcy
    wire_rows_in_col = sorted([int(r) for r in np.where(wm[:, wire_col])[0]])

    if not wire_rows_in_col:
        # Place first wire adjacent to plant
        if 0 <= wire_col < WORLD_W and 0 <= pcy < WORLD_H:
            return (Tool.WIRE, wire_col, pcy)

    # --- Phase 3: Extend wire vertically ---
    if wire_rows_in_col:
        min_wr = wire_rows_in_col[0]
        max_wr = wire_rows_in_col[-1]

        # Extend downward
        if max_wr < target_max_r and max_wr + 1 < WORLD_H:
            nr = max_wr + 1
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)
            # Force place (bulldoze is auto)
            return (Tool.WIRE, wire_col, nr)

        # Extend upward
        if min_wr > target_min_r and min_wr - 1 >= 0:
            nr = min_wr - 1
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)
            return (Tool.WIRE, wire_col, nr)

    # --- Phase 4: Build road spine adjacent to wire ---
    if wire_rows_in_col and 0 <= road_col < WORLD_W:
        # For each wire row, place road at same row in road_col
        road_rows_in_col = set(int(r) for r in np.where(rm[:, road_col])[0])
        for wr in wire_rows_in_col:
            if wr not in road_rows_in_col:
                if 0 <= wr < WORLD_H:
                    return (Tool.ROAD, road_col, wr)

    # --- Helper: check if zone area is placeable (3x3 around center) ---
    def zone_area_ok(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
        return True

    def is_empty_area(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not em[rr, rc]:
                    return False
        return True

    # --- Phase 5: Place zones where wire and road coverage exist ---
    # Left zones: center at wire_col - 3 (just left of wire)
    # Right zones: center at road_col + 3 (just right of road)
    left_zc = wire_col - 3
    right_zc = road_col + 3

    # Get current covered rows (wire rows = powered, road rows = accessible)
    road_rows_in_col = set(int(r) for r in np.where(rm[:, road_col])[0]) if 0 <= road_col < WORLD_W else set()
    wire_set = set(wire_rows_in_col)

    # Find rows where both wire and road exist (with some tolerance)
    covered_rows = []
    for wr in wire_set:
        # Road must be within 2 rows
        if any(abs(wr - rr) <= 2 for rr in road_rows_in_col):
            covered_rows.append(wr)

    # Place zones at covered rows, spaced by 3
    zone_rows_placed_left = set()
    zone_rows_placed_right = set()

    # Check existing zones
    res_rows, res_cols = np.where(resm)
    com_rows, com_cols = np.where(comm)
    ind_rows, ind_cols = np.where(indm)

    def zone_nearby(zr, zc, rows, cols):
        for r, c in zip(rows, cols):
            if abs(r - zr) <= 1 and abs(c - zc) <= 1:
                return True
        return False

    # Sort covered rows
    covered_rows_sorted = sorted(set(covered_rows))

    # Try to place zones at each covered row (skip rows too close together)
    last_placed_r = -10
    for zr in covered_rows_sorted:
        if abs(zr - last_placed_r) < 3:
            continue
        # Try left zone
        if 0 <= left_zc < WORLD_W and zone_area_ok(zr, left_zc):
            if not zone_nearby(zr, left_zc, res_rows, res_cols) and \
               not zone_nearby(zr, left_zc, com_rows, com_cols) and \
               not zone_nearby(zr, left_zc, ind_rows, ind_cols):
                if is_empty_area(zr, left_zc):
                    # Lateral wire to connect zone to wire spine
                    # First check if wire exists between zone and spine
                    wire_ok = False
                    for wc in range(min(left_zc + 2, wire_col), wire_col + 1):
                        if wm[zr, wc]:
                            wire_ok = True
                            break
                    if not wire_ok:
                        # Place lateral wire
                        for wc in range(left_zc + 2, wire_col):
                            if em[zr, wc]:
                                return (Tool.WIRE, wc, zr)
                    # Decide zone type
                    if ind_count < max(1, res_count // 3):
                        return (Tool.INDUSTRIAL, left_zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, left_zc, zr)
                    last_placed_r = zr

        # Try right zone
        if 0 <= right_zc < WORLD_W and zone_area_ok(zr, right_zc):
            if not zone_nearby(zr, right_zc, res_rows, res_cols) and \
               not zone_nearby(zr, right_zc, com_rows, com_cols) and \
               not zone_nearby(zr, right_zc, ind_rows, ind_cols):
                if is_empty_area(zr, right_zc):
                    if com_count < max(1, res_count // 3):
                        return (Tool.COMMERCIAL, right_zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, right_zc, zr)
                    last_placed_r = zr

    # --- Phase 6: Add lateral wires to power left zones ---
    # For each wire row, check if lateral wire needed to reach left_zc
    for wr in wire_rows_in_col:
        # Check path from left_zc+1 to wire_col-1
        for wc in range(left_zc + 2, wire_col):
            if 0 <= wc < WORLD_W and 0 <= wr < WORLD_H:
                if not wm[wr, wc] and em[wr, wc]:
                    return (Tool.WIRE, wc, wr)

    # --- Phase 7: Extend road to serve more zone rows ---
    # Add horizontal roads connecting road spine to right zones
    for wr in wire_rows_in_col:
        for rc in range(road_col + 1, right_zc + 1):
            if 0 <= rc < WORLD_W and 0 <= wr < WORLD_H:
                if not rm[wr, rc] and em[wr, rc]:
                    return (Tool.ROAD, rc, wr)

    # --- Phase 8: Add a second power plant if city is growing ---
    if obs.city_pop > 300 and not state.get('second_plant', False):
        # Place second plant further right
        px2 = road_col + 10
        py2 = cy
        if 0 <= px2 + 2 < WORLD_W:
            state['second_plant'] = True
            return (Tool.COALPOWER, px2, py2)

    # --- Phase 9: Wire from second plant ---
    if state.get('second_plant', False):
        # Find second plant area and wire it back to road spine
        wire2_col = road_col + 8
        if 0 <= wire2_col < WORLD_W:
            for wr in wire_rows_in_col:
                if 0 <= wr < WORLD_H and not wm[wr, wire2_col] and em[wr, wire2_col]:
                    return (Tool.WIRE, wire2_col, wr)

    # --- Phase 10: Fill gaps in road spine ---
    if road_rows_in_col and wire_rows_in_col:
        for wr in wire_rows_in_col:
            if wr not in road_rows_in_col and 0 <= wr < WORLD_H and 0 <= road_col < WORLD_W:
                return (Tool.ROAD, road_col, wr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Each step reads the current tile_map to decide what to place next.
    - Phase 1: Place coal plant, then wire outward from it to a target zone cluster.
    - Phase 2: Lay roads adjacent to existing roads/wires to build a grid.
    - Phase 3: Place zones adjacent to existing roads+wires.
    - Continuously adapts based on what's actually on the map.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    step = obs.step
    n = obs.n_steps

    # Small phase counter in state
    if 'init' not in state:
        state['init'] = True
        state['phase'] = 0
        state['wire_step'] = 0
        state['road_phase'] = 0
        state['zone_idx'] = 0

    # ---- Configuration: city cluster centered around (60, 50) ----
    # Power plant location
    px, py = 20, 50

    # Zone cluster: a 5x5 grid of zone centers, spaced 4 apart
    # Zones centered at x = 40..56 step 4, y = 44..60 step 4
    zone_centers = []
    for zy in range(44, 65, 4):
        for zx in range(40, 75, 4):
            zone_centers.append((zx, zy))

    # Road columns/rows to lay
    # Horizontal roads at y=42, y=50, y=58, y=64 from x=38 to x=76
    # Vertical roads at x=38 and x=76 from y=42 to y=64
    road_actions = []
    for rx in range(38, 77):
        for ry in [42, 50, 58, 64]:
            road_actions.append((rx, ry))
    for ry in range(42, 65):
        for rx in [38, 76]:
            road_actions.append((rx, ry))

    # Wire path: from plant (px,py) rightward to zone cluster
    # Wire at y=50 from x=21 to x=39, then vertical at x=39 from y=42 to y=64
    wire_path = []
    for wx in range(21, 40):
        wire_path.append((wx, 50))
    for wy in range(42, 65):
        wire_path.append((39, wy))
    # Also wire horizontally inside cluster at y=50
    for wx in range(39, 77):
        wire_path.append((wx, 50))

    # ---- Step 1: Ensure power plant exists ----
    # Check if plant exists near (px, py)
    has_plant = np.any(pm[max(0,py-1):min(WORLD_H,py+2), max(0,px-1):min(WORLD_W,px+2)])
    if not has_plant:
        # Place coal plant - check area is mostly clear
        return (Tool.COALPOWER, px, py)

    # ---- Step 2: Lay wires from plant toward cluster ----
    # Find wire tiles that are needed but missing
    for (wx, wy) in wire_path:
        if 0 <= wx < WORLD_W and 0 <= wy < WORLD_H:
            if not wm[wy, wx] and not pm[wy, wx]:
                # Don't overwrite roads with wire
                if not rm[wy, wx]:
                    return (Tool.WIRE, wx, wy)
                # If road is there, place wire under/over by skipping (road acts as wire in adjacency)
                # Actually road does NOT conduct power, so we need wire even if road is there
                # But auto-bulldoze would remove the road. Skip road tiles on wire path for now
                # and rely on adjacency from nearby wire
                pass

    # ---- Step 3: Lay roads ----
    # Place roads that don't exist yet
    for (rx, ry) in road_actions:
        if 0 <= rx < WORLD_W and 0 <= ry < WORLD_H:
            if not rm[ry, rx]:
                # Don't overwrite plant or wire (wire can be bulldozed by road placement)
                if not pm[ry, rx]:
                    return (Tool.ROAD, rx, ry)

    # ---- Step 4: Place zones reactively ----
    # Count zone types
    res_count = int(np.sum(res_mask(tm)))
    com_count = int(np.sum(com_mask(tm)))
    ind_count = int(np.sum(ind_mask(tm)))
    total = res_count + com_count + ind_count + 1

    # Decide tool based on ratio
    if ind_count / total < 0.25:
        ztool = Tool.INDUSTRIAL
    elif com_count / total < 0.30:
        ztool = Tool.COMMERCIAL
    else:
        ztool = Tool.RESIDENTIAL

    # Try to place a zone at a zone_center that:
    # - 3x3 area is empty
    # - has road within 2 tiles
    # - has wire within 3 tiles (or plant adjacent)
    for (zx, zy) in zone_centers:
        if zx < 1 or zx > WORLD_W-2 or zy < 1 or zy > WORLD_H-2:
            continue
        # Check 3x3 clear
        block = tm[zy-1:zy+2, zx-1:zx+2]
        if not np.all(em[zy-1:zy+2, zx-1:zx+2]):
            continue
        # Check road nearby (within 2)
        y0, y1 = max(0, zy-2), min(WORLD_H, zy+3)
        x0, x1 = max(0, zx-2), min(WORLD_W, zx+3)
        road_near = np.any(rm[y0:y1, x0:x1])
        if not road_near:
            continue
        # Check wire or plant nearby (within 3)
        y0w, y1w = max(0, zy-3), min(WORLD_H, zy+4)
        x0w, x1w = max(0, zx-3), min(WORLD_W, zx+4)
        wire_near = np.any(wm[y0w:y1w, x0w:x1w]) or np.any(pm[y0w:y1w, x0w:x1w])
        if not wire_near:
            continue
        return (ztool, zx, zy)

    # ---- Phase 5: Add more infrastructure ----
    # Second coal plant for more power
    has_plant2 = np.any(pm[45:55, 75:85])
    if not has_plant2 and obs.city_pop > 50:
        return (Tool.COALPOWER, 80, 50)

    # Wire from second plant leftward to cluster
    for wx in range(79, 75, -1):
        if not wm[50, wx] and not pm[50, wx] and not rm[50, wx]:
            return (Tool.WIRE, wx, 50)

    # Extend zones further
    ext_zones = []
    for zy in range(44, 65, 4):
        for zx in range(76, 100, 4):
            ext_zones.append((zx, zy))
    ext_roads = []
    for rx in range(76, 100):
        for ry in [42, 50, 58, 64]:
            ext_roads.append((rx, ry))

    for (rx, ry) in ext_roads:
        if 0 <= rx < WORLD_W and 0 <= ry < WORLD_H:
            if not rm[ry, rx] and not pm[ry, rx]:
                return (Tool.ROAD, rx, ry)

    for (zx, zy) in ext_zones:
        if zx < 1 or zx > WORLD_W-2 or zy < 1 or zy > WORLD_H-2:
            continue
        if not np.all(em[zy-1:zy+2, zx-1:zx+2]):
            continue
        y0, y1 = max(0, zy-2), min(WORLD_H, zy+3)
        x0, x1 = max(0, zx-2), min(WORLD_W, zx+3)
        road_near = np.any(rm[y0:y1, x0:x1])
        if not road_near:
            continue
        y0w, y1w = max(0, zy-3), min(WORLD_H, zy+4)
        x0w, x1w = max(0, zx-3), min(WORLD_W, zx+4)
        wire_near = np.any(wm[y0w:y1w, x0w:x1w]) or np.any(pm[y0w:y1w, x0w:x1w])
        if not wire_near:
            continue
        return (ztool, zx, zy)

    # Add services if population growing
    if obs.city_pop > 200:
        fire_placed = False
        police_placed = False
        # Check for fire station
        for fy in range(44, 65, 8):
            for fx in range(55, 70, 8):
                if em[fy, fx] and em[fy-1, fx] and em[fy+1, fx]:
                    if not fire_placed:
                        return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 400:
        for fy in range(48, 65, 8):
            for fx in range(58, 72, 8):
                if em[fy, fx]:
                    return (Tool.POLICESTATION, fx, fy)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map every step to find current infrastructure
    - Builds a compact city cluster: coal plant + wire spine + road columns + zones
    - Fully reactive: each step scans current map state and places next needed tile
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # Use a more central position to avoid edges
    plant_x, plant_y = 55, 48

    has_plant = np.any(pm)

    # Phase 1: Place coal plant
    if not has_plant:
        return (Tool.COALPOWER, plant_x, plant_y)

    # Find plant center from tile_map
    plant_positions = list(zip(*np.where(pm)))
    if plant_positions:
        # Use centroid of plant tiles
        rows = [p[0] for p in plant_positions]
        cols = [p[1] for p in plant_positions]
        plant_y = int(np.mean(rows))
        plant_x = int(np.mean(cols))

    # Wire spine column: just to the right of plant
    wire_col = min(plant_x + 5, WORLD_W - 5)
    # Road columns flanking wire
    left_road_col = max(1, wire_col - 4)
    right_road_col = min(WORLD_W - 2, wire_col + 4)
    # Zone columns
    left_zone_col = max(2, wire_col - 8)
    right_zone_col = min(WORLD_W - 3, wire_col + 8)

    # Spine row range
    spine_top = max(2, plant_y - 18)
    spine_bot = min(WORLD_H - 3, plant_y + 18)

    # Find existing wire rows in spine column
    wire_rows_in_col = [r for r in range(WORLD_H) if wm[r, wire_col]]

    # Phase 2: Start wire adjacent to plant
    if not wire_rows_in_col:
        wy = plant_y
        if 0 <= wire_col < WORLD_W and 0 <= wy < WORLD_H:
            return (Tool.WIRE, wire_col, wy)
        return None

    cur_min = min(wire_rows_in_col)
    cur_max = max(wire_rows_in_col)

    # Phase 3: Extend wire spine upward and downward
    if cur_max < spine_bot:
        nr = cur_max + 1
        if 0 <= nr < WORLD_H:
            return (Tool.WIRE, wire_col, nr)
    if cur_min > spine_top:
        nr = cur_min - 1
        if 0 <= nr < WORLD_H:
            return (Tool.WIRE, wire_col, nr)

    # Phase 4: Build left and right road columns along wire rows
    for wr in wire_rows_in_col:
        if 0 <= left_road_col < WORLD_W and not rm[wr, left_road_col]:
            return (Tool.ROAD, left_road_col, wr)
        if 0 <= right_road_col < WORLD_W and not rm[wr, right_road_col]:
            return (Tool.ROAD, right_road_col, wr)

    # Phase 5: Extend lateral wires from spine to zone columns
    for wr in wire_rows_in_col:
        # Left lateral: from wire_col-1 to left_zone_col+1
        for wc in range(wire_col - 1, left_zone_col - 1, -1):
            if 0 <= wc < WORLD_W and not wm[wr, wc] and em[wr, wc]:
                return (Tool.WIRE, wc, wr)
        # Right lateral: from wire_col+1 to right_zone_col+1
        for wc in range(wire_col + 1, right_zone_col + 2):
            if 0 <= wc < WORLD_W and not wm[wr, wc] and em[wr, wc]:
                return (Tool.WIRE, wc, wr)

    # Helper: check if 3x3 zone area is clear
    def zone_clear(zr, zc):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                r2, c2 = zr + dr, zc + dc
                if r2 < 0 or r2 >= WORLD_H or c2 < 0 or c2 >= WORLD_W:
                    return False
                if not em[r2, c2]:
                    return False
        return True

    def zone_exists_near(zr, zc, mask):
        r1 = max(0, zr - 2)
        r2 = min(WORLD_H, zr + 3)
        c1 = max(0, zc - 2)
        c2 = min(WORLD_W, zc + 3)
        return np.any(mask[r1:r2, c1:c2])

    def near_wire(zr, zc):
        r1 = max(0, zr - 2)
        r2 = min(WORLD_H, zr + 3)
        c1 = max(0, zc - 2)
        c2 = min(WORLD_W, zc + 3)
        return np.any(wm[r1:r2, c1:c2])

    def near_road(zr, zc):
        r1 = max(0, zr - 2)
        r2 = min(WORLD_H, zr + 3)
        c1 = max(0, zc - 2)
        c2 = min(WORLD_W, zc + 3)
        return np.any(rm[r1:r2, c1:c2])

    # Count zone types
    res_count = int(np.sum(res_m))
    com_count = int(np.sum(com_m))
    ind_count = int(np.sum(ind_m))

    # Phase 6: Place zones at rows spaced by 3 along spine
    zone_rows = list(range(spine_top + 1, spine_bot, 3))

    for zr in zone_rows:
        if not (2 <= zr < WORLD_H - 2):
            continue

        # Left zone column
        zc = left_zone_col
        if 2 <= zc < WORLD_W - 2:
            all_z = res_m | com_m | ind_m
            if not zone_exists_near(zr, zc, all_z):
                if zone_clear(zr, zc) and near_wire(zr, zc) and near_road(zr, zc):
                    # Balance zone types: need industry for jobs
                    if ind_count < max(1, res_count // 3):
                        return (Tool.INDUSTRIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

        # Right zone column
        zc = right_zone_col
        if 2 <= zc < WORLD_W - 2:
            all_z = res_m | com_m | ind_m
            if not zone_exists_near(zr, zc, all_z):
                if zone_clear(zr, zc) and near_wire(zr, zc) and near_road(zr, zc):
                    if com_count < max(1, res_count // 3):
                        return (Tool.COMMERCIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

    # Phase 7: Extend horizontal roads between road cols and zone cols
    for wr in wire_rows_in_col:
        # Left side horizontal road
        for rc in range(left_road_col - 1, max(0, left_zone_col - 2), -1):
            if 0 <= rc < WORLD_W and not rm[wr, rc] and em[wr, rc]:
                return (Tool.ROAD, rc, wr)
        # Right side horizontal road
        for rc in range(right_road_col + 1, min(WORLD_W, right_zone_col + 3)):
            if 0 <= rc < WORLD_W and not rm[wr, rc] and em[wr, rc]:
                return (Tool.ROAD, rc, wr)

    # Phase 8: If city growing, add extra zone columns further out
    if obs.city_pop > 50:
        extra_left = max(2, left_zone_col - 6)
        extra_right = min(WORLD_W - 3, right_zone_col + 6)
        # First ensure roads reach there
        for wr in wire_rows_in_col:
            for rc in range(left_zone_col - 1, extra_left - 1, -1):
                if 0 <= rc < WORLD_W and not rm[wr, rc] and em[wr, rc]:
                    return (Tool.ROAD, rc, wr)
            for rc in range(right_zone_col + 1, extra_right + 2):
                if 0 <= rc < WORLD_W and not rm[wr, rc] and em[wr, rc]:
                    return (Tool.ROAD, rc, wr)

        for zr in zone_rows:
            if not (2 <= zr < WORLD_H - 2):
                continue
            for zc in [extra_left, extra_right]:
                if 2 <= zc < WORLD_W - 2:
                    all_z = res_m | com_m | ind_m
                    if not zone_exists_near(zr, zc, all_z):
                        if zone_clear(zr, zc) and near_road(zr, zc):
                            # Also need wire - extend wire if needed
                            if not near_wire(zr, zc):
                                # Place wire along this row from wire_col
                                if zc < wire_col:
                                    for wc in range(wire_col - 1, zc - 1, -1):
                                        if 0 <= wc < WORLD_W and not wm[zr, wc] and em[zr, wc]:
                                            return (Tool.WIRE, wc, zr)
                                else:
                                    for wc in range(wire_col + 1, zc + 2):
                                        if 0 <= wc < WORLD_W and not wm[zr, wc] and em[zr, wc]:
                                            return (Tool.WIRE, wc, zr)
                            else:
                                if res_count > 0 and com_count < res_count // 2:
                                    return (Tool.COMMERCIAL, zc, zr)
                                elif ind_count < res_count // 3:
                                    return (Tool.INDUSTRIAL, zc, zr)
                                else:
                                    return (Tool.RESIDENTIAL, zc, zr)

    # Phase 9: Add a police station or fire station for coverage if pop growing
    if obs.city_pop > 200:
        # Place police station near city center
        pc_r, pc_c = plant_y, wire_col + 1
        if em[pc_r, pc_c]:
            return (Tool.POLICESTATION, pc_c, pc_r)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder.
    Reads tile_map every step, extends infrastructure from what already exists.
    Strategy: single central cluster with coal plant, wire spine, road grid, zones.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Central cluster anchor
    CX, CY = 60, 50

    # Step 1: Place power plant if none exists
    if not np.any(pm):
        return (Tool.COALPOWER, CX, CY)

    # Find plant center
    plant_rows, plant_cols = np.where(pm)
    pcx = int(np.mean(plant_cols))
    pcy = int(np.mean(plant_rows))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Wire spine: horizontal at pcy-1 and vertical at pcx
    # Road spine: horizontal at pcy+1 and vertical at pcx+1
    wire_row = pcy - 1
    road_row = pcy + 2
    wire_col = pcx
    road_col = pcx + 2

    # Step 2: Extend wires reactively from existing power (plant or wire)
    # Find all tiles adjacent to power source that are empty - extend toward targets
    power_map = pm | wm

    # Wire target spine: horizontal line at wire_row from CX-30 to CX+30
    # plus vertical line at wire_col from CY-15 to CY+15
    w_extent = min(30, 10 + obs.city_pop // 20)
    wire_h_targets = [(x, wire_row) for x in range(CX - w_extent, CX + w_extent + 1)]
    wire_v_targets = [(wire_col, y) for y in range(CY - 15, CY + 16)]

    # Also extend wire vertically to power upper/lower zone rows
    upper_wire_rows = [(wire_col + dx*4, wire_row - r)
                       for dx in range(-6, 7)
                       for r in range(1, 8)]

    all_wire_targets = wire_h_targets + wire_v_targets

    for (wx, wy) in all_wire_targets:
        if not in_bounds(wx, wy):
            continue
        if bool(wm[wy, wx]) or bool(pm[wy, wx]) or bool(rm[wy, wx]):
            continue
        # Only place if adjacent to existing power
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx, ny = wx+ddx, wy+ddy
            if in_bounds(nx, ny) and bool(power_map[ny, nx]):
                if bool(em[wy, wx]):
                    return (Tool.WIRE, wx, wy)
                break

    # Step 3: Extend roads reactively from existing roads or near plant
    r_extent = min(25, 8 + obs.city_pop // 15)
    road_h_targets = [(x, road_row) for x in range(CX - r_extent, CX + r_extent + 1)]
    road_v_targets = [(road_col, y) for y in range(CY - 12, CY + 13)]

    # Cross-streets every 4 columns
    cross_roads = []
    for dx in range(-r_extent, r_extent + 1, 4):
        cx2 = CX + dx
        for dy in range(-8, 9):
            cross_roads.append((cx2, road_row + dy))

    all_road_targets = road_h_targets + road_v_targets + cross_roads

    for (rx, ry) in all_road_targets:
        if not in_bounds(rx, ry):
            continue
        if bool(rm[ry, rx]) or bool(pm[ry, rx]) or bool(wm[ry, rx]):
            continue
        if not bool(em[ry, rx]):
            continue
        # Place if adjacent to existing road or near plant
        adj_road = False
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx, ny = rx+ddx, ry+ddy
            if in_bounds(nx, ny) and bool(rm[ny, nx]):
                adj_road = True
                break
        adj_plant = False
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1),(2,0),(-2,0),(0,2),(0,-2)]:
            nx, ny = rx+ddx, ry+ddy
            if in_bounds(nx, ny) and bool(pm[ny, nx]):
                adj_plant = True
                break
        if adj_road or adj_plant:
            return (Tool.ROAD, rx, ry)

    # Step 4: Place zones near both roads AND power
    # Build neighbor masks efficiently
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_mask = resm | comm | indm
    cand = em & nbr_road & nbr_power
    # Exclude map edges (need 3x3)
    cand[0:2, :] = False
    cand[WORLD_H-2:, :] = False
    cand[:, 0:2] = False
    cand[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        key = int(obs.step * 17 + int(obs.city_pop * 3) + 1) % len(cxs)
        for offset in range(min(len(cxs), 60)):
            k = (key + offset * 13) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            ok = True
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    ny2, nx2 = zy + dr, zx + dc
                    if not in_bounds(nx2, ny2):
                        ok = False; break
                    if not (bool(em[ny2, nx2]) or bool(zone_mask[ny2, nx2])):
                        ok = False; break
                if not ok:
                    break
            if ok:
                return (pick_tool(), zx, zy)

    # Step 5: Add second power plant if population warrants
    if obs.city_pop > 250 and int(np.sum(pm)) < 9:
        p2x = pcx + 20
        p2y = pcy
        p2x = max(2, min(WORLD_W - 3, p2x))
        p2y = max(2, min(WORLD_H - 3, p2y))
        if bool(em[p2y, p2x]):
            return (Tool.COALPOWER, p2x, p2y)

    # Step 6: Services when population warrants
    if obs.city_pop > 200:
        for fx, fy in [(CX + 5, CY - 12), (CX - 5, CY + 12)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 400:
        for fx, fy in [(CX + 5, CY + 12), (CX - 5, CY - 12)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.POLICESTATION, fx, fy)

    # Fallback: extend wire from any wire frontier
    wys2, wxs2 = np.where(wm)
    if len(wxs2) > 0:
        k3 = int(obs.step * 7) % len(wxs2)
        wx2, wy2 = int(wxs2[k3]), int(wys2[k3])
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx, ny = wx2+ddx, wy2+ddy
            if in_bounds(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                return (Tool.WIRE, nx, ny)

    # Fallback: extend road from any road frontier
    rys2, rxs2 = np.where(rm)
    if len(rxs2) > 0:
        k2 = int(obs.step * 11) % len(rxs2)
        rx2, ry2 = int(rxs2[k2]), int(rys2[k2])
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx, ny = rx2+ddx, ry2+ddy
            if in_bounds(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                return (Tool.ROAD, nx, ny)

    return None

def act(obs, state):
    """
    Revised strategy: horizontal layout instead of vertical spine.
    - Place coal power plant near top-center
    - Run horizontal wire row from plant
    - Place road rows above and below wire row
    - Place zones in columns between road rows
    - Balanced RCI mix
    - Second power plant when needed
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    # Use a fixed anchor near upper portion of map
    anchor_x = WORLD_W // 2  # col 60
    anchor_y = 30             # row 30 (upper area)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = float(total_zones)
        # Target: 50% res, 30% com, 20% ind
        if com_count / t < 0.30:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Phase 1: Place coal power plant if missing
    if not np.any(pm):
        # Place plant at anchor, offset so wire row clears it
        px, py = anchor_x - 10, anchor_y - 4
        px = max(4, min(WORLD_W - 5, px))
        py = max(4, min(WORLD_H - 5, py))
        return (Tool.COALPOWER, px, py)

    # Find plant centroid
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Horizontal layout parameters
    wire_row = plant_cy + 3        # horizontal wire spine just below plant
    top_road_row = wire_row - 2    # road above wire
    bot_road_row = wire_row + 2    # road below wire
    top_zone_row = wire_row - 5    # zone centers above top road
    bot_zone_row = wire_row + 5    # zone centers below bot road

    # Clamp rows
    wire_row = max(2, min(WORLD_H - 3, wire_row))
    top_road_row = max(2, min(WORLD_H - 3, top_road_row))
    bot_road_row = max(2, min(WORLD_H - 3, bot_road_row))
    top_zone_row = max(2, min(WORLD_H - 3, top_zone_row))
    bot_zone_row = max(2, min(WORLD_H - 3, bot_zone_row))

    # Spine extent based on population
    if obs.city_pop < 50:
        spine_extent = 8
    elif obs.city_pop < 200:
        spine_extent = 16
    elif obs.city_pop < 500:
        spine_extent = 24
    elif obs.city_pop < 900:
        spine_extent = 36
    else:
        spine_extent = 48

    target_min = max(4, plant_cx - spine_extent)
    target_max = min(WORLD_W - 5, plant_cx + spine_extent)

    # Current wire positions on horizontal spine
    wire_cols_on_spine = sorted([c for c in range(WORLD_W) if wm[wire_row, c]])

    # Phase 2: Start wire adjacent to plant if none on spine
    if not wire_cols_on_spine:
        # Try columns near plant right edge
        for dc in range(0, 8):
            for nc in [plant_cx + 4 + dc, plant_cx - 1 - dc]:
                if 0 <= nc < WORLD_W:
                    if em[wire_row, nc] or wm[wire_row, nc]:
                        if not pm[wire_row, nc]:
                            return (Tool.WIRE, nc, wire_row)
        return None

    min_wire_col = min(wire_cols_on_spine)
    max_wire_col = max(wire_cols_on_spine)

    # Phase 3: Extend wire spine rightward
    if max_wire_col < target_max:
        nc = max_wire_col + 1
        if nc < WORLD_W and not pm[wire_row, nc]:
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # Phase 4: Extend wire spine leftward
    if min_wire_col > target_min:
        nc = min_wire_col - 1
        if nc >= 0 and not pm[wire_row, nc]:
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # Phase 5: Build top road row
    for c in wire_cols_on_spine:
        if 0 <= c < WORLD_W and 0 <= top_road_row < WORLD_H:
            if not rm[top_road_row, c] and em[top_road_row, c] and not pm[top_road_row, c]:
                return (Tool.ROAD, c, top_road_row)

    # Phase 6: Build bottom road row
    for c in wire_cols_on_spine:
        if 0 <= c < WORLD_W and 0 <= bot_road_row < WORLD_H:
            if not rm[bot_road_row, c] and em[bot_road_row, c] and not pm[bot_road_row, c]:
                return (Tool.ROAD, c, bot_road_row)

    all_zone_mask = resm | comm | indm

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=5):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    # Phase 7: Vertical wires from spine to zone rows (top and bottom)
    # Wire upward from spine to top zones
    for wc in wire_cols_on_spine:
        for wr in range(wire_row - 1, top_zone_row - 2, -1):
            if 0 <= wr < WORLD_H:
                if wm[wr, wc] or pm[wr, wc]:
                    break
                if em[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc] and not wm[wr, wc]:
                    break

    # Wire downward from spine to bottom zones
    for wc in wire_cols_on_spine:
        for wr in range(wire_row + 1, bot_zone_row + 2):
            if 0 <= wr < WORLD_H:
                if wm[wr, wc] or pm[wr, wc]:
                    break
                if em[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc] and not wm[wr, wc]:
                    break

    top_road_cols = sorted([c for c in range(WORLD_W) if rm[top_road_row, c]])
    bot_road_cols = sorted([c for c in range(WORLD_W) if rm[bot_road_row, c]])

    zone_cols = list(range(max(4, target_min + 1), min(WORLD_W - 4, target_max), 3))

    # Phase 8: Place zones in top and bottom rows
    for zc in zone_cols:
        wire_near = any(abs(zc - wc) <= 2 for wc in wire_cols_on_spine)
        if not wire_near:
            continue

        # Top zones
        top_road_near = any(abs(zc - rc) <= 2 for rc in top_road_cols)
        if top_road_near:
            zr = top_zone_row
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc) and has_road_nearby(zr, zc):
                    return (pick_tool(), zc, zr)

        # Bottom zones
        bot_road_near = any(abs(zc - rc) <= 2 for rc in bot_road_cols)
        if bot_road_near:
            zr = bot_zone_row
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc) and has_road_nearby(zr, zc):
                    return (pick_tool(), zc, zr)

        # Inner zones between road and wire (top side)
        inner_top_row = wire_row - 1
        inner_top_row = max(2, min(WORLD_H - 3, inner_top_row))
        if inner_top_row != wire_row and inner_top_row != top_road_row:
            if not zone_already_there(inner_top_row, zc) and zone_area_ok(inner_top_row, zc):
                if has_wire_nearby(inner_top_row, zc, 3) and has_road_nearby(inner_top_row, zc, 5):
                    return (pick_tool(), zc, inner_top_row)

        # Inner zones between wire and road (bottom side)
        inner_bot_row = wire_row + 1
        inner_bot_row = max(2, min(WORLD_H - 3, inner_bot_row))
        if inner_bot_row != wire_row and inner_bot_row != bot_road_row:
            if not zone_already_there(inner_bot_row, zc) and zone_area_ok(inner_bot_row, zc):
                if has_wire_nearby(inner_bot_row, zc, 3) and has_road_nearby(inner_bot_row, zc, 5):
                    return (pick_tool(), zc, inner_bot_row)

    # Phase 9: Second coal plant if needed
    if obs.city_pop > 300 and int(np.sum(pm)) < 18:
        px2 = plant_cx + 20
        py2 = plant_cy
        px2 = max(4, min(WORLD_W - 5, px2))
        py2 = max(4, min(WORLD_H - 5, py2))
        if em[py2, px2]:
            return (Tool.COALPOWER, px2, py2)

    # Phase 10: Add second neighborhood below (offset rows)
    if obs.city_pop > 400:
        wire_row2 = bot_zone_row + 8
        wire_row2 = max(2, min(WORLD_H - 3, wire_row2))
        bot_road2 = wire_row2 + 2
        bot_zone2 = wire_row2 + 5
        bot_road2 = max(2, min(WORLD_H - 3, bot_road2))
        bot_zone2 = max(2, min(WORLD_H - 3, bot_zone2))

        # Extend vertical wire down from spine
        if wire_cols_on_spine:
            mid_wc = wire_cols_on_spine[len(wire_cols_on_spine) // 2]
            for wr in range(wire_row + 1, wire_row2 + 1):
                if 0 <= wr < WORLD_H and not pm[wr, mid_wc]:
                    if em[wr, mid_wc] or wm[wr, mid_wc]:
                        if not wm[wr, mid_wc]:
                            return (Tool.WIRE, mid_wc, wr)

            # Extend horizontal wire on second spine
            wires2 = sorted([c for c in range(WORLD_W) if wm[wire_row2, c]])
            if wires2:
                if max(wires2) < target_max:
                    nc = max(wires2) + 1
                    if not pm[wire_row2, nc] and (em[wire_row2, nc] or wm[wire_row2, nc]):
                        return (Tool.WIRE, nc, wire_row2)
                if min(wires2) > target_min:
                    nc = min(wires2) - 1
                    if not pm[wire_row2, nc] and (em[wire_row2, nc] or wm[wire_row2, nc]):
                        return (Tool.WIRE, nc, wire_row2)

                # Road and zones for second neighborhood
                for c in wires2:
                    if 0 <= bot_road2 < WORLD_H and not rm[bot_road2, c] and em[bot_road2, c]:
                        return (Tool.ROAD, c, bot_road2)
                bot_road2_cols = sorted([c for c in range(WORLD_W) if rm[bot_road2, c]])
                for zc in zone_cols:
                    bot2_road_near = any(abs(zc - rc) <= 2 for rc in bot_road2_cols)
                    if bot2_road_near and any(abs(zc - wc) <= 2 for wc in wires2):
                        zr = bot_zone2
                        if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                            if has_wire_nearby(zr, zc) and has_road_nearby(zr, zc):
                                return (pick_tool(), zc, zr)

    # Phase 11: Connect roads vertically at ends of spine
    if obs.city_pop > 150 and wire_cols_on_spine:
        for v_col in [min_wire_col, max_wire_col]:
            if 0 <= v_col < WORLD_W:
                for rr in range(min(top_road_row, top_zone_row) - 1,
                                max(bot_road_row, bot_zone_row) + 2):
                    if 0 <= rr < WORLD_H and em[rr, v_col] and not pm[rr, v_col] and not wm[rr, v_col]:
                        return (Tool.ROAD, v_col, rr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map each step to decide what to place next
    - Builds a compact corridor: power plant -> wire spine -> road -> zones
    - Expands reactively based on what's already on the map
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    all_zone_mask = resm | comm | indm

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        # Aim: 55% RES, 25% COM, 20% IND
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_overlap(zr, zc):
        # Returns True if any zone tile already in 3x3 footprint
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def nearby_wire(zr, zc, radius=5):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def nearby_road(zr, zc, radius=3):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    # ---- Phase 1: Place coal power plant if none exists ----
    if not np.any(pm):
        px, py = cx - 12, cy
        px = max(2, min(WORLD_W - 4, px))
        py = max(2, min(WORLD_H - 4, py))
        return (Tool.COALPOWER, px, py)

    # Find plant location
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Layout: wire spine column, road column, zone columns
    wire_col = plant_cx + 4
    road_col = wire_col + 2
    left_zone_col = wire_col - 4
    right_zone_col = road_col + 4

    wire_col = max(3, min(WORLD_W - 4, wire_col))
    road_col = max(3, min(WORLD_W - 4, road_col))
    left_zone_col = max(2, min(WORLD_W - 3, left_zone_col))
    right_zone_col = max(2, min(WORLD_W - 3, right_zone_col))

    # Spine extent grows with population
    pop = obs.city_pop
    if pop < 50:
        spine_extent = 6
    elif pop < 150:
        spine_extent = 12
    elif pop < 400:
        spine_extent = 20
    elif pop < 800:
        spine_extent = 28
    else:
        spine_extent = 36

    target_min = max(1, cy - spine_extent)
    target_max = min(WORLD_H - 2, cy + spine_extent)

    # Scan existing wire and road on spine columns
    wire_on_spine = [r for r in range(WORLD_H) if wm[r, wire_col]]
    road_on_col = [r for r in range(WORLD_H) if rm[r, road_col]]

    # ---- Phase 2: Bootstrap wire adjacent to plant ----
    if not wire_on_spine:
        # Place wire at plant_cy on wire_col, scanning outward
        for dy in range(0, 8):
            for nr in [plant_cy + dy, plant_cy - dy]:
                if 0 <= nr < WORLD_H:
                    if (em[nr, wire_col] or wm[nr, wire_col]) and not pm[nr, wire_col]:
                        return (Tool.WIRE, wire_col, nr)
        return None

    min_wire_row = min(wire_on_spine)
    max_wire_row = max(wire_on_spine)

    # ---- Phase 3: Extend wire spine toward targets ----
    # Extend downward
    if max_wire_row < target_max:
        nr = max_wire_row + 1
        if nr < WORLD_H and not pm[nr, wire_col] and (em[nr, wire_col] or wm[nr, wire_col]):
            return (Tool.WIRE, wire_col, nr)

    # Extend upward
    if min_wire_row > target_min:
        nr = min_wire_row - 1
        if nr >= 0 and not pm[nr, wire_col] and (em[nr, wire_col] or wm[nr, wire_col]):
            return (Tool.WIRE, wire_col, nr)

    # ---- Phase 4: Build road parallel to wire spine ----
    # For every row with wire, ensure road exists at road_col
    for r in wire_on_spine:
        if target_min <= r <= target_max:
            if 0 <= road_col < WORLD_W and not rm[r, road_col] and em[r, road_col] and not pm[r, road_col]:
                return (Tool.ROAD, road_col, r)

    # ---- Phase 5: Lay lateral wires from spine to left zone column ----
    # Only do this for rows that have wire and are in range
    for wr in wire_on_spine:
        if not (target_min <= wr <= target_max):
            continue
        # Walk left from wire_col-1 to left_zone_col-1
        for wc in range(wire_col - 1, left_zone_col - 2, -1):
            if wc < 0:
                break
            if wm[wr, wc] or pm[wr, wc]:
                break  # already connected or blocked by plant
            if em[wr, wc]:
                return (Tool.WIRE, wc, wr)
            elif rm[wr, wc]:
                continue  # road is there, keep going
            else:
                break  # blocked by zone or something

    # ---- Phase 6: Place zones ----
    zone_rows = list(range(target_min + 1, target_max, 3))

    for zr in zone_rows:
        # Check if wire and road reach this row
        wire_near = any(abs(zr - wr) <= 2 for wr in wire_on_spine)
        road_near = any(abs(zr - rr) <= 2 for rr in road_on_col)

        if not (wire_near and road_near):
            continue

        # Left zone column
        zc = left_zone_col
        if not zone_overlap(zr, zc) and zone_area_ok(zr, zc):
            if nearby_wire(zr, zc, 6) and nearby_road(zr, zc, 5):
                return (pick_tool(), zc, zr)

        # Right zone column
        zc = right_zone_col
        if not zone_overlap(zr, zc) and zone_area_ok(zr, zc):
            if nearby_road(zr, zc, 5) and nearby_wire(zr, zc, 7):
                return (pick_tool(), zc, zr)

    # ---- Phase 7: Extend road rightward to reach right zone col ----
    for rr in road_on_col:
        if not (target_min <= rr <= target_max):
            continue
        for rc in range(road_col + 1, right_zone_col + 2):
            if rc >= WORLD_W:
                break
            if rm[rr, rc]:
                break
            if pm[rr, rc]:
                break
            if em[rr, rc]:
                return (Tool.ROAD, rc, rr)
            else:
                break

    # ---- Phase 8: Wire rightward to power right zones ----
    for wr in wire_on_spine:
        if not (target_min <= wr <= target_max):
            continue
        for wc in range(wire_col + 1, right_zone_col + 2):
            if wc >= WORLD_W:
                break
            if wm[wr, wc] or pm[wr, wc]:
                break
            if rm[wr, wc]:
                continue  # road here, skip (auto-bulldoze would kill road)
            if em[wr, wc]:
                return (Tool.WIRE, wc, wr)
            else:
                break

    # ---- Phase 9: Second power plant when needed ----
    plant_count = int(np.sum(pm))
    if pop > 300 and plant_count < 9:
        # Try placing second plant above or below the first cluster
        candidates = [
            (plant_cx + 18, plant_cy),
            (plant_cx + 18, plant_cy - 14),
            (plant_cx + 18, plant_cy + 14),
            (plant_cx - 18, plant_cy),
        ]
        for px2, py2 in candidates:
            px2 = max(2, min(WORLD_W - 4, px2))
            py2 = max(2, min(WORLD_H - 4, py2))
            if np.all(em[py2-1:py2+2, px2-1:px2+2]):
                return (Tool.COALPOWER, px2, py2)

    # ---- Phase 10: Horizontal roads for extra connectivity ----
    if pop > 100:
        # Add horizontal roads at top and bottom of spine
        for hr in [min_wire_row + 1, max_wire_row - 1]:
            if not (0 <= hr < WORLD_H):
                continue
            for hc in range(max(0, left_zone_col - 1), min(WORLD_W, right_zone_col + 2)):
                if em[hr, hc] and not pm[hr, hc] and not wm[hr, hc]:
                    return (Tool.ROAD, hc, hr)

    # ---- Phase 11: Extra zone columns when city is growing ----
    if pop > 250:
        extra_cols = [left_zone_col - 5, right_zone_col + 5]
        for zc in extra_cols:
            zc = max(2, min(WORLD_W - 3, zc))
            for zr in zone_rows:
                if not zone_overlap(zr, zc) and zone_area_ok(zr, zc):
                    if nearby_road(zr, zc, 7) and nearby_wire(zr, zc, 8):
                        return (Tool.RESIDENTIAL, zc, zr)

    # ---- Phase 12: Fill any wire gaps in spine ----
    for r in range(target_min, target_max + 1):
        if not wm[r, wire_col] and not pm[r, wire_col] and em[r, wire_col]:
            return (Tool.WIRE, wire_col, r)

    return None

def act(obs, state):
    """
    Combined policy:
    - Pre-planned layout (Parent B idea) with two clusters
    - Closed-loop wire/road/zone expansion (Parent A idea)
    - Each cluster: coal plant, wire distribution, road grid, mixed zones
    - Connect clusters with road + wire spine
    """

    def build_plan():
        p = []
        # Two clusters centered at (30, 50) and (75, 50)
        clusters = [(30, 50), (75, 50)]

        for cx, cy in clusters:
            # Coal power plant (3x3, placed by center)
            pp_x, pp_y = cx - 8, cy - 8
            pp_x = max(2, min(WORLD_W - 3, pp_x))
            pp_y = max(2, min(WORLD_H - 3, pp_y))
            p.append((Tool.COALPOWER, pp_x, pp_y))

            # Wire from plant rightward to wire column
            wire_x = cx - 3
            for dx in range(pp_x + 2, wire_x + 1):
                if 0 <= dx < WORLD_W:
                    p.append((Tool.WIRE, dx, pp_y))

            # Wire from plant level down to zone area
            for dy in range(pp_y + 1, cy + 9):
                if 0 <= dy < WORLD_H:
                    p.append((Tool.WIRE, wire_x, dy))
            # Wire up from plant
            for dy in range(pp_y - 1, cy - 9, -1):
                if 0 <= dy < WORLD_H:
                    p.append((Tool.WIRE, wire_x, dy))

            # Main horizontal road through cluster
            for dx in range(cx - 12, cx + 13):
                dx_ = max(0, min(WORLD_W - 1, dx))
                p.append((Tool.ROAD, dx_, cy))

            # Vertical roads flanking wire
            road_left = cx - 6
            road_right = cx + 3
            for dy in range(cy - 10, cy + 11):
                dy_ = max(0, min(WORLD_H - 1, dy))
                p.append((Tool.ROAD, road_left, dy_))
                p.append((Tool.ROAD, road_right, dy_))

            # Lateral wires at each zone row to ensure power
            zone_rows = [cy - 6, cy - 3, cy, cy + 3, cy + 6]
            for zr in zone_rows:
                if 0 <= zr < WORLD_H:
                    # Wire from wire_x leftward to left zones
                    for dx in range(wire_x - 1, road_left - 2, -1):
                        if 0 <= dx < WORLD_W:
                            p.append((Tool.WIRE, dx, zr))
                    # Wire from wire_x rightward to right zones
                    for dx in range(wire_x + 1, road_right + 3):
                        if 0 <= dx < WORLD_W:
                            p.append((Tool.WIRE, dx, zr))

            # Residential zones (left of wire)
            left_zone_x = cx - 9
            for zr in zone_rows:
                lx = max(1, min(WORLD_W - 2, left_zone_x))
                ly = max(1, min(WORLD_H - 2, zr))
                p.append((Tool.RESIDENTIAL, lx, ly))

            # Commercial zones (center)
            center_zone_x = cx
            for i, zr in enumerate(zone_rows):
                lx = max(1, min(WORLD_W - 2, center_zone_x))
                ly = max(1, min(WORLD_H - 2, zr))
                if i % 2 == 0:
                    p.append((Tool.COMMERCIAL, lx, ly))
                else:
                    p.append((Tool.RESIDENTIAL, lx, ly))

            # Industrial zones (right)
            right_zone_x = cx + 6
            for i, zr in enumerate(zone_rows):
                lx = max(1, min(WORLD_W - 2, right_zone_x))
                ly = max(1, min(WORLD_H - 2, zr))
                if i % 2 == 0:
                    p.append((Tool.INDUSTRIAL, lx, ly))
                else:
                    p.append((Tool.RESIDENTIAL, lx, ly))

        # Connect two clusters with road
        for x in range(clusters[0][0] + 4, clusters[1][0] - 3):
            x_ = max(0, min(WORLD_W - 1, x))
            p.append((Tool.ROAD, x_, 50))

        # Connect with wire too for power sharing
        for x in range(clusters[0][0] - 2, clusters[1][0] - 7):
            x_ = max(0, min(WORLD_W - 1, x))
            p.append((Tool.WIRE, x_, 49))

        return p

    if "plan" not in state:
        state["plan"] = build_plan()
        state["idx"] = 0

    # Execute pre-planned actions first
    if state["idx"] < len(state["plan"]):
        action = state["plan"][state["idx"]]
        state["idx"] += 1
        return action

    # Closed-loop expansion phase (from Parent A)
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    all_zones = resm | comm | indm

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr2, rc2 = zr + dr, zc + dc
                if not (0 <= rr2 < WORLD_H and 0 <= rc2 < WORLD_W):
                    return False
                if not em[rr2, rc2] and not all_zones[rr2, rc2]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr2, rc2 = zr + dr, zc + dc
                if 0 <= rr2 < WORLD_H and 0 <= rc2 < WORLD_W:
                    if all_zones[rr2, rc2]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=3):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    # If no power plant, place one at center-left
    if not np.any(pm):
        return (Tool.COALPOWER, WORLD_W // 2 - 15, WORLD_H // 2)

    # Try to add more zones in empty areas near power+road
    cy = WORLD_H // 2
    zone_y_candidates = list(range(max(1, cy - 20), min(WORLD_H - 1, cy + 21), 3))

    for x_cluster in [30, 75, 52]:
        for zc_offset in [-9, -6, 0, 6, 9, 12]:
            zc = x_cluster + zc_offset
            zc = max(2, min(WORLD_W - 3, zc))
            for zr in zone_y_candidates:
                if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                    if has_wire_nearby(zr, zc, 5) and has_road_nearby(zr, zc, 4):
                        return (pick_tool(), zc, zr)

    # Fill gaps in wire spine
    if np.any(pm):
        plant_rows, plant_cols = np.where(pm)
        plant_cy = int(np.mean(plant_rows))
        plant_cx = int(np.mean(plant_cols))
        wire_x = plant_cx + 5
        wire_x = max(0, min(WORLD_W - 1, wire_x))
        for dy in range(-15, 16):
            wr = plant_cy + dy
            if 0 <= wr < WORLD_H and em[wr, wire_x]:
                return (Tool.WIRE, wire_x, wr)

    # Add extra roads for connectivity gaps
    for zr in zone_y_candidates:
        if has_wire_nearby(zr, 52, 6) and not has_road_nearby(zr, 52, 2):
            for rc in range(45, 65):
                if em[zr, rc]:
                    return (Tool.ROAD, rc, zr)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map each step and reacts.
    Strategy:
    - Place coal power plant near center-left.
    - Extend wire rightward from plant, then build vertical wire spine.
    - Build road column adjacent to wire spine.
    - Place zones (RES/COM/IND) on both sides of road, checking real map state.
    - Reactively extend power/road to reach unpowered zones.
    """
    tm = obs.tile_map
    step = obs.step

    # Build zone at center of map, shift left for plant
    cx, cy = 62, 50  # slightly right of center to give room

    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    has_plant = np.any(pm)
    plant_cx, plant_cy = cx - 8, cy  # plant center

    # Phase 1: Place coal power plant
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Find all wire/road/zone positions
    wire_positions = set(zip(*np.where(wm))) if np.any(wm) else set()  # (row, col)
    road_positions = set(zip(*np.where(rm))) if np.any(rm) else set()
    res_positions = set(zip(*np.where(res_m))) if np.any(res_m) else set()
    com_positions = set(zip(*np.where(com_m))) if np.any(com_m) else set()
    ind_positions = set(zip(*np.where(ind_m))) if np.any(ind_m) else set()

    res_count = len(res_positions)
    com_count = len(com_positions)
    ind_count = len(ind_positions)

    # Wire spine column (connects plant to zones)
    wire_col = plant_cx + 5  # e.g. cx-3
    road_col = wire_col + 1  # road just right of wire
    left_zone_col = wire_col - 3   # zone centers left of wire
    right_zone_col = wire_col + 4  # zone centers right of road

    # Phase 2: Bridge wire from plant to spine column
    # Plant footprint: plant_cx-1..plant_cx+1, plant_cy-1..plant_cy+1 (approx)
    # Wire from plant_cx+2 to wire_col at row cy
    bridge_needed = []
    for bc in range(plant_cx + 2, wire_col + 1):
        if not wm[cy, bc]:
            bridge_needed.append((cy, bc))
    if bridge_needed:
        br, bc = bridge_needed[0]
        if em[br, bc] or wm[br, bc]:
            return (Tool.WIRE, bc, br)

    # Phase 3: Extend wire spine vertically
    wire_col_rows = sorted([r for (r, c) in wire_positions if c == wire_col])
    target_min = cy - 15
    target_max = cy + 15

    if not wire_col_rows:
        if 0 <= cy < WORLD_H and 0 <= wire_col < WORLD_W:
            return (Tool.WIRE, wire_col, cy)
    else:
        max_row = max(wire_col_rows)
        min_row = min(wire_col_rows)
        if max_row < target_max and max_row + 1 < WORLD_H:
            nr, nc = max_row + 1, wire_col
            if em[nr, nc] or wm[nr, nc]:
                return (Tool.WIRE, nc, nr)
        if min_row > target_min and min_row - 1 >= 0:
            nr, nc = min_row - 1, wire_col
            if em[nr, nc] or wm[nr, nc]:
                return (Tool.WIRE, nc, nr)

    # Phase 4: Build road spine vertically, aligned with wire spine
    road_col_rows = sorted([r for (r, c) in road_positions if c == road_col])
    if wire_col_rows:
        for r in wire_col_rows:
            if 0 <= r < WORLD_H and 0 <= road_col < WORLD_W:
                if not rm[r, road_col]:
                    if em[r, road_col]:
                        return (Tool.ROAD, road_col, r)

    # Helper: check if 3x3 area is clear
    def zone_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    # Check if zone already placed near (cr, cc)
    def zone_nearby(cr, cc, zone_set):
        return any(abs(cr - pr) <= 1 and abs(cc - pc) <= 1 for (pr, pc) in zone_set)

    # Phase 5: Place zones where wire and road exist at that row
    # Left side: wire at wire_col, zone center at left_zone_col
    # Right side: road at road_col, zone center at right_zone_col
    # Also add lateral wires to power left zones
    if wire_col_rows:
        wire_row_set = set(wire_col_rows)
        road_row_set = set(r for (r, c) in road_positions if c == road_col)

        # Sort zone rows by distance from center for compact growth
        zone_rows = sorted(wire_col_rows, key=lambda r: abs(r - cy))

        for zr in zone_rows:
            # Check road nearby for this row
            road_near = any(abs(zr - rr) <= 2 for rr in road_row_set)
            wire_near = any(abs(zr - wr) <= 2 for wr in wire_row_set)

            if not road_near or not wire_near:
                continue

            # Try left zone
            zc = left_zone_col
            if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                all_zones = res_positions | com_positions | ind_positions
                if not zone_nearby(zr, zc, all_zones) and zone_free(zr, zc):
                    # Lateral wire from wire_col to zc+1 (connect power)
                    # First check if lateral wire exists
                    lateral_needed = False
                    for lc in range(zc + 1, wire_col):
                        if not wm[zr, lc]:
                            lateral_needed = True
                            if em[zr, lc]:
                                return (Tool.WIRE, lc, zr)
                    if not lateral_needed:
                        # Decide type
                        if ind_count < max(1, res_count // 5):
                            return (Tool.INDUSTRIAL, zc, zr)
                        else:
                            return (Tool.RESIDENTIAL, zc, zr)

            # Try right zone
            zc = right_zone_col
            if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                all_zones = res_positions | com_positions | ind_positions
                if not zone_nearby(zr, zc, all_zones) and zone_free(zr, zc):
                    # Check lateral road from road_col to zone
                    lateral_road_needed = False
                    for lc in range(road_col + 1, zc):
                        if not rm[zr, lc]:
                            lateral_road_needed = True
                            if em[zr, lc]:
                                return (Tool.ROAD, lc, zr)
                    if not lateral_road_needed:
                        if com_count < max(1, res_count // 4):
                            return (Tool.COMMERCIAL, zc, zr)
                        else:
                            return (Tool.RESIDENTIAL, zc, zr)

    # Phase 6: Extend wire/road spine further if population growing
    if obs.city_pop > 100 and wire_col_rows:
        max_row = max(wire_col_rows)
        min_row = min(wire_col_rows)
        ext_min = cy - 20
        ext_max = cy + 20
        if max_row < ext_max and max_row + 1 < WORLD_H:
            nr, nc = max_row + 1, wire_col
            if em[nr, nc]:
                return (Tool.WIRE, nc, nr)
        if min_row > ext_min and min_row - 1 >= 0:
            nr, nc = min_row - 1, wire_col
            if em[nr, nc]:
                return (Tool.WIRE, nc, nr)

    # Phase 7: Add second road column for denser zone placement
    if obs.city_pop > 300:
        road_col2 = wire_col - 5
        for r in wire_col_rows:
            if 0 <= r < WORLD_H and 0 <= road_col2 < WORLD_W:
                if not rm[r, road_col2] and em[r, road_col2]:
                    return (Tool.ROAD, road_col2, r)
        # Zones on far left
        for zr in sorted(wire_col_rows, key=lambda r: abs(r - cy)):
            zc = road_col2 - 3
            if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                all_zones = res_positions | com_positions | ind_positions
                if not zone_nearby(zr, zc, all_zones) and zone_free(zr, zc):
                    return (Tool.RESIDENTIAL, zc, zr)

    return None

def act(obs, state):
    """
    Improved policy with horizontal layout:
    - Two power plants side by side
    - Horizontal road spine
    - Zones above and below road spine
    - Mixed zone types (RCI balance)
    - Wider coverage
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Use horizontal layout centered around row 50, col 30-90
    # Plant at (30, 50), road spine at row 50, zones above (row 45) and below (row 55)

    road_row = 50       # horizontal road spine
    wire_row = 49       # wire row just above road
    top_zone_row = 45   # zone centers above road
    bot_zone_row = 55   # zone centers below road

    plant_cx = 30
    plant_cy = 50

    # Phase 1: Place first coal power plant
    if not np.any(pm):
        return (Tool.COALPOWER, plant_cx, plant_cy)

    plant_rows, plant_cols = np.where(pm)
    plant_cy_actual = int(np.mean(plant_rows))
    plant_cx_actual = int(np.mean(plant_cols))

    # Phase 2: Extend horizontal road spine from plant rightward
    # Road runs from col 35 to col 90 at road_row
    road_start = plant_cx_actual + 5
    road_end = 90

    # Find existing road extent on road_row
    road_cols_on_row = sorted([c for c in range(WORLD_W) if rm[road_row, c]])

    if not road_cols_on_row:
        # Start road adjacent to plant
        rc = plant_cx_actual + 5
        if 0 <= rc < WORLD_W and em[road_row, rc]:
            return (Tool.ROAD, rc, road_row)
        return (Tool.ROAD, plant_cx_actual + 4, road_row)

    max_road_col = max(road_cols_on_row)
    min_road_col = min(road_cols_on_row)

    # Extend road rightward
    if max_road_col < road_end:
        nc = max_road_col + 1
        if 0 <= nc < WORLD_W:
            if not pm[road_row, nc]:
                return (Tool.ROAD, nc, road_row)

    # Phase 3: Wire spine parallel to road (just above)
    wire_cols_on_row = sorted([c for c in range(WORLD_W) if wm[wire_row, c]])

    # Start wire from plant
    if not wire_cols_on_row:
        wc = plant_cx_actual + 2
        if 0 <= wc < WORLD_W and (em[wire_row, wc] or wm[wire_row, wc]):
            return (Tool.WIRE, wc, wire_row)

    if wire_cols_on_row:
        max_wire_col = max(wire_cols_on_row)
        if max_wire_col < road_end:
            nc = max_wire_col + 1
            if 0 <= nc < WORLD_W and not pm[wire_row, nc] and not rm[wire_row, nc]:
                if em[wire_row, nc] or wm[wire_row, nc]:
                    return (Tool.WIRE, nc, wire_row)

    # Phase 4: Determine zone placement columns
    # Zones every 3 cols starting from road_start+2
    zone_cols = list(range(plant_cx_actual + 6, road_end - 2, 3))

    all_zone_mask = resm | comm | indm

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        # Target: 50% res, 25% com, 25% ind
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Phase 5: Place zones above and below road spine
    for zc in zone_cols:
        for zr in [top_zone_row, bot_zone_row]:
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc, 5) and has_road_nearby(zr, zc, 5):
                    return (pick_tool(), zc, zr)
                elif has_wire_nearby(zr, zc, 4) and has_road_nearby(zr, zc, 3):
                    return (Tool.RESIDENTIAL, zc, zr)

    # Phase 6: Second power plant if needed
    if obs.city_pop > 200 and int(np.sum(pm)) < 9:
        px2 = plant_cx_actual + 20
        py2 = plant_cy_actual
        if 2 <= px2 <= WORLD_W - 3 and 2 <= py2 <= WORLD_H - 3:
            if em[py2, px2]:
                return (Tool.COALPOWER, px2, py2)

    # Phase 7: Vertical connectors every few cols from wire to road
    for zc in zone_cols[::3]:
        for vr in range(min(wire_row, road_row), max(wire_row, road_row) + 1):
            if 0 <= vr < WORLD_H and 0 <= zc < WORLD_W:
                if em[vr, zc] and not pm[vr, zc]:
                    return (Tool.WIRE, zc, vr)

    # Phase 8: Extend zones further out (second row)
    top_zone_row2 = top_zone_row - 6
    bot_zone_row2 = bot_zone_row + 6

    # Add horizontal roads at outer zone rows
    if obs.city_pop > 100:
        for h_row in [top_zone_row2, bot_zone_row2]:
            if 1 <= h_row <= WORLD_H - 2:
                for rc in range(plant_cx_actual + 3, road_end):
                    if 0 <= rc < WORLD_W and em[h_row, rc] and not pm[h_row, rc]:
                        return (Tool.ROAD, rc, h_row)

    if obs.city_pop > 150:
        for zc in zone_cols:
            for zr in [top_zone_row2, bot_zone_row2]:
                if 1 <= zr <= WORLD_H - 2:
                    if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                        if has_road_nearby(zr, zc, 4) and has_wire_nearby(zr, zc, 6):
                            return (pick_tool(), zc, zr)

    # Phase 9: Add vertical wire columns to power outer zones
    if obs.city_pop > 100:
        for zc in zone_cols[::2]:
            for vr in range(top_zone_row2 - 1, wire_row + 1):
                if 0 <= vr < WORLD_H and 0 <= zc < WORLD_W:
                    if em[vr, zc] and not pm[vr, zc] and not rm[vr, zc]:
                        if not wm[vr, zc]:
                            return (Tool.WIRE, zc, vr)
            for vr in range(road_row, bot_zone_row2 + 2):
                if 0 <= vr < WORLD_H and 0 <= zc < WORLD_W:
                    if em[vr, zc] and not pm[vr, zc] and not rm[vr, zc]:
                        if not wm[vr, zc]:
                            return (Tool.WIRE, zc, vr)

    # Phase 10: Third power plant for large city
    if obs.city_pop > 500 and int(np.sum(pm)) < 18:
        px3 = plant_cx_actual + 45
        py3 = plant_cy_actual
        if 2 <= px3 <= WORLD_W - 3 and 2 <= py3 <= WORLD_H - 3:
            if em[py3, px3]:
                return (Tool.COALPOWER, px3, py3)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map every step to decide next action
    - Places coal plant, then extends wire spine from plant,
      adds parallel road, then places zones flanking the corridor
    - Adapts dynamically: spine length, zone mix, second cluster all
      driven by observed map state and city_pop
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(1, total_zones)
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    all_zone = resm | comm | indm

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone[rr, rc]:
                    return False
        return True

    def zone_exists_near(zr, zc):
        r0 = max(0, zr - 1); r1 = min(WORLD_H, zr + 2)
        c0 = max(0, zc - 1); c1 = min(WORLD_W, zc + 2)
        return np.any(all_zone[r0:r1, c0:c1])

    def wire_near(zr, zc, rad=5):
        r0 = max(0, zr - rad); r1 = min(WORLD_H, zr + rad + 1)
        c0 = max(0, zc - rad); c1 = min(WORLD_W, zc + rad + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def road_near(zr, zc, rad=4):
        r0 = max(0, zr - rad); r1 = min(WORLD_H, zr + rad + 1)
        c0 = max(0, zc - rad); c1 = min(WORLD_W, zc + rad + 1)
        return np.any(rm[r0:r1, c0:c1])

    # --- Phase 1: Place first power plant ---
    if not np.any(pm):
        return (Tool.COALPOWER, cx - 8, cy)

    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Layout columns relative to plant
    wire_col = plant_cx + 4
    road_col = wire_col + 2
    left_col = wire_col - 3
    right_col = road_col + 3

    wire_col = max(2, min(WORLD_W - 3, wire_col))
    road_col = max(2, min(WORLD_W - 3, road_col))
    left_col = max(2, min(WORLD_W - 3, left_col))
    right_col = max(2, min(WORLD_W - 3, right_col))

    # Dynamic spine extent based on current pop
    pop = obs.city_pop
    if pop < 100:
        extent = 10
    elif pop < 300:
        extent = 16
    elif pop < 600:
        extent = 22
    else:
        extent = 30

    t_min = max(1, cy - extent)
    t_max = min(WORLD_H - 2, cy + extent)

    # Read current wire spine and road column
    wire_rows = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])
    road_rows = set(r for r in range(WORLD_H) if rm[r, road_col])

    # --- Phase 2: Seed wire adjacent to plant ---
    if not wire_rows:
        for dy in range(0, 6):
            for nr in [plant_cy + dy, plant_cy - dy]:
                if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                    return (Tool.WIRE, wire_col, nr)
        return None

    min_wr = min(wire_rows)
    max_wr = max(wire_rows)

    # --- Phase 3: Extend wire spine downward ---
    if max_wr < t_max:
        nr = max_wr + 1
        if nr < WORLD_H and not pm[nr, wire_col] and (em[nr, wire_col] or wm[nr, wire_col]):
            return (Tool.WIRE, wire_col, nr)

    # --- Phase 4: Extend wire spine upward ---
    if min_wr > t_min:
        nr = min_wr - 1
        if nr >= 0 and not pm[nr, wire_col] and (em[nr, wire_col] or wm[nr, wire_col]):
            return (Tool.WIRE, wire_col, nr)

    # --- Phase 5: Build road column beside wire spine ---
    for r in wire_rows:
        if 0 <= r < WORLD_H and not rm[r, road_col] and em[r, road_col]:
            return (Tool.ROAD, road_col, r)

    # --- Phase 6: Place zones flanking the corridor ---
    zone_rows = list(range(max(1, t_min), min(WORLD_H - 1, t_max + 1), 3))

    for zr in zone_rows:
        w_near = any(abs(zr - wr) <= 2 for wr in wire_rows)
        r_near = zr in road_rows or any(abs(zr - rr) <= 2 for rr in road_rows)
        if not (w_near and r_near):
            continue

        # Left zone
        zc = left_col
        if not zone_exists_near(zr, zc) and zone_area_ok(zr, zc):
            if wire_near(zr, zc) and road_near(zr, zc):
                return (pick_tool(), zc, zr)

        # Right zone
        zc = right_col
        if not zone_exists_near(zr, zc) and zone_area_ok(zr, zc):
            if wire_near(zr, zc) and road_near(zr, zc):
                return (pick_tool(), zc, zr)

    # --- Phase 7: Lateral wires left to reach left zones ---
    for wr in wire_rows:
        for wc in range(wire_col - 1, max(left_col - 3, 0), -1):
            if wm[wr, wc]:
                break
            if em[wr, wc] and not pm[wr, wc]:
                return (Tool.WIRE, wc, wr)
            elif not em[wr, wc]:
                break

    # --- Phase 8: Road extensions right toward right zones ---
    for rr in sorted(road_rows):
        for rc in range(road_col + 1, right_col + 3):
            if 0 <= rc < WORLD_W:
                if rm[rr, rc]:
                    break
                if em[rr, rc] and not pm[rr, rc]:
                    return (Tool.ROAD, rc, rr)
                elif not em[rr, rc]:
                    break

    # --- Phase 9: Wire extensions right to power right zones ---
    for wr in wire_rows:
        for wc in range(wire_col + 1, right_col + 3):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc] and not rm[wr, wc]:
                    break

    # --- Phase 10: Second power plant when pop grows ---
    if pop > 300 and int(np.sum(pm)) < 9:
        px2, py2 = plant_cx + 18, plant_cy
        if 2 <= py2 <= WORLD_H - 3 and 2 <= px2 <= WORLD_W - 3:
            area_ok = all(
                em[py2 + dr, px2 + dc] or pm[py2 + dr, px2 + dc]
                for dr in [-1, 0, 1] for dc in [-1, 0, 1]
                if 0 <= py2 + dr < WORLD_H and 0 <= px2 + dc < WORLD_W
            )
            if area_ok:
                return (Tool.COALPOWER, px2, py2)

    # --- Phase 11: Second cluster to the right when pop >= 200 ---
    if pop >= 200:
        wc2 = road_col + 8
        rc2 = wc2 + 2
        lc2 = wc2 - 3
        rc2r = rc2 + 3

        wc2 = max(2, min(WORLD_W - 3, wc2))
        rc2 = max(2, min(WORLD_W - 3, rc2))
        lc2 = max(2, min(WORLD_W - 3, lc2))
        rc2r = max(2, min(WORLD_W - 3, rc2r))

        wire_rows2 = sorted([r for r in range(WORLD_H) if wm[r, wc2]])
        road_rows2 = set(r for r in range(WORLD_H) if rm[r, rc2])

        if not wire_rows2:
            # Bridge wire horizontally from main spine
            for c in range(wire_col + 1, wc2 + 1):
                if 0 <= c < WORLD_W:
                    if wm[plant_cy, c]:
                        break
                    if em[plant_cy, c]:
                        return (Tool.WIRE, c, plant_cy)
                    elif not em[plant_cy, c]:
                        break
        else:
            mn2, mx2 = min(wire_rows2), max(wire_rows2)
            if mx2 < t_max:
                nr = mx2 + 1
                if nr < WORLD_H and em[nr, wc2]:
                    return (Tool.WIRE, wc2, nr)
            if mn2 > t_min:
                nr = mn2 - 1
                if nr >= 0 and em[nr, wc2]:
                    return (Tool.WIRE, wc2, nr)

            for wr in wire_rows2:
                if wr not in road_rows2 and em[wr, rc2]:
                    return (Tool.ROAD, rc2, wr)

            for zr in zone_rows:
                w2 = any(abs(zr - wr) <= 2 for wr in wire_rows2)
                r2 = any(abs(zr - rr) <= 2 for rr in road_rows2)
                if w2 and r2:
                    for zc in [lc2, rc2r]:
                        if not zone_exists_near(zr, zc) and zone_area_ok(zr, zc):
                            if wire_near(zr, zc) and road_near(zr, zc):
                                return (pick_tool(), zc, zr)

            for wr in wire_rows2:
                for wcc in range(wc2 - 1, max(lc2 - 3, 0), -1):
                    if wm[wr, wcc]: break
                    if em[wr, wcc] and not pm[wr, wcc]:
                        return (Tool.WIRE, wcc, wr)
                    elif not em[wr, wcc]: break

            for wr in wire_rows2:
                if wr not in road_rows2: continue
                for rcc in range(rc2 + 1, rc2r + 3):
                    if 0 <= rcc < WORLD_W:
                        if rm[wr, rcc]: break
                        if em[wr, rcc] and not pm[wr, rcc]:
                            return (Tool.ROAD, rcc, wr)
                        elif not em[wr, rcc]: break

    # --- Phase 12: Third cluster to the left when pop >= 400 ---
    if pop >= 400:
        wc3 = wire_col - 10
        rc3 = wc3 - 2
        lc3 = rc3 - 3
        rc3r = wc3 + 3

        wc3 = max(2, min(WORLD_W - 3, wc3))
        rc3 = max(2, min(WORLD_W - 3, rc3))
        lc3 = max(2, min(WORLD_W - 3, lc3))
        rc3r = max(2, min(WORLD_W - 3, rc3r))

        wire_rows3 = sorted([r for r in range(WORLD_H) if wm[r, wc3]])
        road_rows3 = set(r for r in range(WORLD_H) if rm[r, rc3])

        if not wire_rows3:
            for c in range(wire_col - 1, wc3 - 1, -1):
                if 0 <= c < WORLD_W:
                    if wm[plant_cy, c]: break
                    if em[plant_cy, c]:
                        return (Tool.WIRE, c, plant_cy)
                    elif not em[plant_cy, c]: break
        else:
            mn3, mx3 = min(wire_rows3), max(wire_rows3)
            if mx3 < t_max:
                nr = mx3 + 1
                if nr < WORLD_H and em[nr, wc3]:
                    return (Tool.WIRE, wc3, nr)
            if mn3 > t_min:
                nr = mn3 - 1
                if nr >= 0 and em[nr, wc3]:
                    return (Tool.WIRE, wc3, nr)

            for wr in wire_rows3:
                if wr not in road_rows3 and em[wr, rc3]:
                    return (Tool.ROAD, rc3, wr)

            for zr in zone_rows:
                w3 = any(abs(zr - wr) <= 2 for wr in wire_rows3)
                r3 = any(abs(zr - rr) <= 2 for rr in road_rows3)
                if w3 and r3:
                    for zc in [lc3, rc3r]:
                        if not zone_exists_near(zr, zc) and zone_area_ok(zr, zc):
                            if wire_near(zr, zc) and road_near(zr, zc):
                                return (pick_tool(), zc, zr)

            for wr in wire_rows3:
                for wcc in range(wc3 + 1, min(rc3r + 3, WORLD_W)):
                    if wm[wr, wcc]: break
                    if em[wr, wcc] and not pm[wr, wcc]:
                        return (Tool.WIRE, wcc, wr)
                    elif not em[wr, wcc]: break

            for wr in wire_rows3:
                if wr not in road_rows3: continue
                for rcc in range(rc3 - 1, max(lc3 - 3, 0), -1):
                    if rm[wr, rcc]: break
                    if em[wr, rcc] and not pm[wr, rcc]:
                        return (Tool.ROAD, rcc, wr)
                    elif not em[wr, rcc]: break

    # --- Phase 13: Fill extra zone columns when pop > 300 ---
    if pop > 300:
        for zc in [left_col - 5, right_col + 5]:
            if 2 <= zc <= WORLD_W - 3:
                for zr in zone_rows:
                    if not zone_exists_near(zr, zc) and zone_area_ok(zr, zc):
                        if road_near(zr, zc, 6) and wire_near(zr, zc, 7):
                            return (pick_tool(), zc, zr)

    return None

