                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=5):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=5):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    # Phase 1: Place coal power plant
    if not np.any(pm):
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Dynamic extent based on population
    if obs.city_pop < 50:
        spine_extent = 12
    elif obs.city_pop < 200:
        spine_extent = 22
    elif obs.city_pop < 500:
        spine_extent = 35
    else:
        spine_extent = 50

    target_min_row = max(2, plant_cy + 3)
    target_max_row = min(WORLD_H - 3, plant_cy + spine_extent)

    wire_rows_in_col = sorted([r for r in range(WORLD_H) if wm[r, WIRE_COL]])
    road_rows_in_col = sorted([r for r in range(WORLD_H) if rm[r, ROAD_COL]])
    road_rows_set = set(road_rows_in_col)

    # Phase 2: Start wire just below plant
    if not wire_rows_in_col:
        for dr in range(1, 6):
            nr = plant_cy + dr
            if 0 <= nr < WORLD_H and (em[nr, WIRE_COL] or wm[nr, WIRE_COL]):
                return (Tool.WIRE, WIRE_COL, nr)
        return None

    max_wire_row = max(wire_rows_in_col)

    # Phase 3: Extend wire spine downward
    if max_wire_row < target_max_row:
        nr = max_wire_row + 1
        if nr < WORLD_H and not pm[nr, WIRE_COL]:
            if em[nr, WIRE_COL] or wm[nr, WIRE_COL]:
                return (Tool.WIRE, WIRE_COL, nr)

    # Phase 4: Build road column parallel to wire
    for r in wire_rows_in_col:
        if 0 <= r < WORLD_H and 0 <= ROAD_COL < WORLD_W:
            if not rm[r, ROAD_COL] and em[r, ROAD_COL]:
                return (Tool.ROAD, ROAD_COL, r)

    # Phase 5: Place zones along the corridor (zone rows every 3 rows)
    zone_rows = list(range(max(1, target_min_row), min(WORLD_H - 1, target_max_row + 1), 3))

    for zr in zone_rows:
        wire_near = any(abs(zr - wr) <= 2 for wr in wire_rows_in_col)
        road_near = any(abs(zr - rr) <= 2 for rr in road_rows_in_col)

        if wire_near and road_near:
            # Try left zone
            zc = LEFT_ZONE_COL
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc, 6) and has_road_nearby(zr, zc, 7):
                    return (pick_tool(), zc, zr)

            # Try right zone
            zc = RIGHT_ZONE_COL
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc, 5) and has_road_nearby(zr, zc, 6):
                    return (pick_tool(), zc, zr)

    # Phase 6: Horizontal wires from spine to left zones
    for wr in wire_rows_in_col:
        for wc in range(WIRE_COL - 1, max(LEFT_ZONE_COL - 2, 0), -1):
            if wm[wr, wc]:
                break
            if em[wr, wc] and not pm[wr, wc]:
                return (Tool.WIRE, wc, wr)
            elif not em[wr, wc]:
                break

    # Phase 7: Road extensions to right zones
    for rr in road_rows_in_col:
        for rc in range(ROAD_COL + 1, min(RIGHT_ZONE_COL + 2, WORLD_W)):
            if rm[rr, rc]:
                break
            if em[rr, rc] and not pm[rr, rc]:
                return (Tool.ROAD, rc, rr)
            elif not em[rr, rc]:
                break

    # Phase 8: Wire to right zones too
    for wr in wire_rows_in_col:
        for wc in range(WIRE_COL + 1, min(RIGHT_ZONE_COL + 2, WORLD_W)):
            if wm[wr, wc]:
                break
            if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                return (Tool.WIRE, wc, wr)
            elif not em[wr, wc] and not rm[wr, wc]:
                break

    # Phase 9: Second power plant when needed
    if obs.city_pop > 200 and int(np.sum(pm)) < 9:
        px2 = PLANT_X + 15
        py2 = plant_cy + spine_extent // 2
        py2 = max(2, min(WORLD_H - 3, py2))
        px2 = max(2, min(WORLD_W - 3, px2))
        area_clear = True
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = py2 + dr, px2 + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if not (em[rr, rc] or pm[rr, rc]):
                        area_clear = False
        if area_clear:
            return (Tool.COALPOWER, px2, py2)

    # Phase 10: Second vertical cluster to the right when pop >= 150
    if obs.city_pop >= 150:
        WIRE_COL2 = WIRE_COL + 18
        ROAD_COL2 = WIRE_COL2 + 3
        LEFT_ZONE_COL2 = WIRE_COL2 - 4
        RIGHT_ZONE_COL2 = ROAD_COL2 + 4

        if WIRE_COL2 >= WORLD_W or ROAD_COL2 >= WORLD_W:
            return None

        wire_rows2 = sorted([r for r in range(WORLD_H) if wm[r, WIRE_COL2]])
        road_rows2 = sorted([r for r in range(WORLD_H) if rm[r, ROAD_COL2]])

        if not wire_rows2:
            # Build horizontal wire bridge from main spine to cluster2
            connect_row = plant_cy
            for wc in range(WIRE_COL + 1, WIRE_COL2 + 1):
                if not wm[connect_row, wc] and (em[connect_row, wc] or False):
                    return (Tool.WIRE, wc, connect_row)
        else:
            max_wr2 = max(wire_rows2)
            if max_wr2 < target_max_row:
                nr = max_wr2 + 1
                if nr < WORLD_H and em[nr, WIRE_COL2]:
                    return (Tool.WIRE, WIRE_COL2, nr)

            for r in wire_rows2:
                if 0 <= r < WORLD_H and 0 <= ROAD_COL2 < WORLD_W:
                    if not rm[r, ROAD_COL2] and em[r, ROAD_COL2]:
                        return (Tool.ROAD, ROAD_COL2, r)

            for zr in zone_rows:
                wire_near2 = any(abs(zr - wr) <= 2 for wr in wire_rows2)
                road_near2 = any(abs(zr - rr) <= 2 for rr in road_rows2)
                if wire_near2 and road_near2:
                    for zc in [LEFT_ZONE_COL2, RIGHT_ZONE_COL2]:
                        if 1 <= zc <= WORLD_W - 2:
                            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                                if has_wire_nearby(zr, zc, 6) and has_road_nearby(zr, zc, 7):
                                    return (pick_tool(), zc, zr)

            # Wire left from cluster2 spine
            for wr in wire_rows2:
                for wc in range(WIRE_COL2 - 1, max(LEFT_ZONE_COL2 - 2, 0), -1):
                    if wm[wr, wc]:
                        break
                    if em[wr, wc] and not pm[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    elif not em[wr, wc]:
                        break

    # Phase 11: Third cluster even further right when pop >= 400
    if obs.city_pop >= 400:
        WIRE_COL3 = WIRE_COL + 36
        ROAD_COL3 = WIRE_COL3 + 3

        if WIRE_COL3 >= WORLD_W or ROAD_COL3 >= WORLD_W:
            return None

        wire_rows3 = sorted([r for r in range(WORLD_H) if wm[r, WIRE_COL3]])
        road_rows3 = sorted([r for r in range(WORLD_H) if rm[r, ROAD_COL3]])

        if not wire_rows3:
            connect_row = plant_cy
            for wc in range(WIRE_COL + 1, WIRE_COL3 + 1):
                if not wm[connect_row, wc] and em[connect_row, wc]:
                    return (Tool.WIRE, wc, connect_row)
        else:
            max_wr3 = max(wire_rows3)
            if max_wr3 < target_max_row:
                nr = max_wr3 + 1
                if nr < WORLD_H and em[nr, WIRE_COL3]:
                    return (Tool.WIRE, WIRE_COL3, nr)

            for r in wire_rows3:
                if not rm[r, ROAD_COL3] and em[r, ROAD_COL3]:
                    return (Tool.ROAD, ROAD_COL3, r)

            LEFT_ZONE_COL3 = WIRE_COL3 - 4
            RIGHT_ZONE_COL3 = ROAD_COL3 + 4
            for zr in zone_rows:
                wire_near3 = any(abs(zr - wr) <= 2 for wr in wire_rows3)
                road_near3 = any(abs(zr - rr) <= 2 for rr in road_rows3)
                if wire_near3 and road_near3:
                    for zc in [LEFT_ZONE_COL3, RIGHT_ZONE_COL3]:
                        if 1 <= zc <= WORLD_W - 2:
                            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                                if has_wire_nearby(zr, zc, 6) and has_road_nearby(zr, zc, 7):
                                    return (pick_tool(), zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map every step to decide next action
    - Places coal power plant, then extends wire spine vertically
    - Builds road column adjacent to wire
    - Places zones on both sides, adapting to current map state
    - Expands as population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    all_zone_mask = resm | comm | indm

    # Count zones
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # City center
    cx, cy = WORLD_W // 2, WORLD_H // 2

    # --- Phase 1: Place coal power plant if none exists ---
    if not np.any(pm):
        # Place plant slightly left of center, middle height
        px, py = cx - 10, cy
        return (Tool.COALPOWER, px, py)

    # Find plant centroid
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Layout columns relative to plant
    wire_col = plant_cx + 3   # wire spine just right of plant
    road_col = wire_col + 2   # road column 2 right of wire
    left_zone_col = wire_col - 4   # left zones
    right_zone_col = road_col + 4  # right zones

    # Clamp
    wire_col = max(2, min(WORLD_W - 3, wire_col))
    road_col = max(2, min(WORLD_W - 3, road_col))
    left_zone_col = max(3, min(WORLD_W - 4, left_zone_col))
    right_zone_col = max(3, min(WORLD_W - 4, right_zone_col))

    # Determine spine extent based on pop
    pop = obs.city_pop
    if pop < 50:
        spine_half = 6
    elif pop < 150:
        spine_half = 10
    elif pop < 400:
        spine_half = 16
    elif pop < 800:
        spine_half = 22
    else:
        spine_half = 28

    target_min = max(1, cy - spine_half)
    target_max = min(WORLD_H - 2, cy + spine_half)

    # Current wire rows on spine
    wire_rows_on_spine = [r for r in range(WORLD_H) if wm[r, wire_col]]
    road_rows_on_col = [r for r in range(WORLD_H) if rm[r, road_col]]

    # --- Phase 2: Bootstrap wire adjacent to plant ---
    if not wire_rows_on_spine:
        # Place wire adjacent to plant (right side of plant)
        for dy in range(-2, 5):
            nr = plant_cy + dy
            if 0 <= nr < WORLD_H:
                if (em[nr, wire_col] or wm[nr, wire_col]) and not pm[nr, wire_col]:
                    return (Tool.WIRE, wire_col, nr)
        return None

    min_wire_row = min(wire_rows_on_spine)
    max_wire_row = max(wire_rows_on_spine)

    # --- Phase 3: Extend wire spine downward ---
    if max_wire_row < target_max:
        nr = max_wire_row + 1
        if 0 <= nr < WORLD_H and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # --- Phase 4: Extend wire spine upward ---
    if min_wire_row > target_min:
        nr = min_wire_row - 1
        if 0 <= nr >= 0 and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # --- Phase 5: Build road column adjacent to wire ---
    for r in wire_rows_on_spine:
        if target_min <= r <= target_max:
            if 0 <= road_col < WORLD_W and not rm[r, road_col] and em[r, road_col]:
                return (Tool.ROAD, road_col, r)

    # Helper functions
    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_present(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def wire_near(zr, zc, radius=5):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def road_near(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Zone rows every 3 rows in covered range
    zone_rows = list(range(max(1, target_min), min(WORLD_H - 1, target_max + 1), 3))

    # --- Phase 6: Lateral wires from spine to left zone column ---
    for wr in wire_rows_on_spine:
        if target_min <= wr <= target_max:
            # Check if wire already reaches left_zone_col
            already_wired = False
            for wc in range(wire_col - 1, left_zone_col - 2, -1):
                if 0 <= wc < WORLD_W and wm[wr, wc]:
                    already_wired = True
                    break
            if not already_wired:
                for wc in range(wire_col - 1, left_zone_col - 2, -1):
                    if 0 <= wc < WORLD_W:
                        if wm[wr, wc]:
                            break
                        if em[wr, wc] and not pm[wr, wc]:
                            return (Tool.WIRE, wc, wr)
                        elif not em[wr, wc]:
                            break

    # --- Phase 7: Wire to right zone column ---
    for wr in wire_rows_on_spine:
        if target_min <= wr <= target_max:
            already_wired = False
            for wc in range(wire_col + 1, right_zone_col + 2):
                if 0 <= wc < WORLD_W and wm[wr, wc]:
                    already_wired = True
                    break
            if not already_wired:
                for wc in range(wire_col + 1, right_zone_col + 2):
                    if 0 <= wc < WORLD_W:
                        if wm[wr, wc]:
                            break
                        if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                            return (Tool.WIRE, wc, wr)
                        elif not em[wr, wc] and not rm[wr, wc]:
                            break

    # --- Phase 8: Road extensions to right zone column ---
    for rr in road_rows_on_col:
        if target_min <= rr <= target_max:
            for rc in range(road_col + 1, right_zone_col + 2):
                if 0 <= rc < WORLD_W:
                    if rm[rr, rc]:
                        break
                    if em[rr, rc] and not pm[rr, rc]:
                        return (Tool.ROAD, rc, rr)
                    elif not em[rr, rc]:
                        break

    # --- Phase 9: Place zones where powered and road-served ---
    for zr in zone_rows:
        wire_near_row = any(abs(zr - wr) <= 2 for wr in wire_rows_on_spine)
        road_near_row = any(abs(zr - rr) <= 2 for rr in road_rows_on_col)

        if wire_near_row and road_near_row:
            # Left zone
            zc = left_zone_col
            if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                if wire_near(zr, zc) and road_near(zr, zc):
                    return (pick_tool(), zc, zr)

            # Right zone
            zc = right_zone_col
            if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                if wire_near(zr, zc) and road_near(zr, zc):
                    return (pick_tool(), zc, zr)

    # --- Phase 10: Second coal plant if needed ---
    num_plant_tiles = int(np.sum(pm))
    if pop > 300 and num_plant_tiles < 9:
        px2 = plant_cx + 16
        py2 = plant_cy
        px2 = max(2, min(WORLD_W - 3, px2))
        py2 = max(2, min(WORLD_H - 3, py2))
        # Check area clear
        area_ok = True
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if not (0 <= py2+dr < WORLD_H and 0 <= px2+dc < WORLD_W):
                    area_ok = False
                elif not em[py2+dr, px2+dc] and not pm[py2+dr, px2+dc]:
                    area_ok = False
        if area_ok:
            return (Tool.COALPOWER, px2, py2)

    # --- Phase 11: Expand outer zone columns if growing ---
    if pop > 200:
        outer_left = left_zone_col - 4
        outer_right = right_zone_col + 4
        for zc in [outer_left, outer_right]:
            if 3 <= zc <= WORLD_W - 4:
                for zr in zone_rows:
                    if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                        if wire_near(zr, zc, 6) and road_near(zr, zc, 5):
                            return (Tool.RESIDENTIAL, zc, zr)

    # --- Phase 12: Horizontal roads at edges of spine to connect zones ---
    if pop > 100:
        for rr in [min_wire_row, max_wire_row]:
            if target_min <= rr <= target_max:
                for rc in range(left_zone_col - 1, right_zone_col + 2):
                    if 0 <= rc < WORLD_W and em[rr, rc] and not pm[rr, rc]:
                        return (Tool.ROAD, rc, rr)

    # --- Phase 13: Fill in any missing zones near existing infrastructure ---
    for zr in zone_rows:
        for zc in [left_zone_col, wire_col - 7, right_zone_col, road_col + 7]:
            zc = max(3, min(WORLD_W - 4, zc))
            if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                if wire_near(zr, zc, 7) and road_near(zr, zc, 6):
                    return (pick_tool(), zc, zr)

    return None

def act(obs, state):
    """
    Improved city builder with:
    - Two power plants (one on each side)
    - Road grid instead of just two rows
    - Better zone placement with proper R/C/I balance
    - Multiple neighborhood clusters
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    # Two anchors for two neighborhoods
    CX1, CY1 = 25, 45   # Left neighborhood
    CX2, CY2 = 70, 45   # Right neighborhood

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def has_plant_nearby(cx, cy, radius=8):
        for dy in range(-radius, radius+1):
            for dx in range(-radius, radius+1):
                ny, nx = cy+dy, cx+dx
                if in_bounds(nx, ny) and bool(pm[ny, nx]):
                    return True
        return False

    plant_ys, plant_xs = np.where(pm)
    n_plants = len(plant_xs)
    px1, py1 = (int(np.mean(plant_xs)), int(np.mean(plant_ys))) if n_plants > 0 else (CX1, CY1)

    wire_ys, wire_xs = np.where(wm)
    road_ys, road_xs = np.where(rm)
    res_ys, res_xs = np.where(resm)
    com_ys, com_xs = np.where(comm)
    ind_ys, ind_xs = np.where(indm)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    zone_set = set(zip(
        np.concatenate([res_ys, com_ys, ind_ys]).tolist(),
        np.concatenate([res_xs, com_xs, ind_xs]).tolist()
    ))

    def pick_tool():
        # Target: 50% res, 25% com, 25% ind
        t = max(total_zones, 1)
        c = com_count / t
        i = ind_count / t
        if c < 0.25:
            return Tool.COMMERCIAL
        if i < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    # Phase 1: Place first power plant
    if not np.any(pm):
        return (Tool.COALPOWER, CX1, CY1)

    # Phase 2: Place second power plant far from first
    if not has_plant_nearby(CX2, CY2, radius=10):
        if in_bounds(CX2, CY2) and bool(em[CY2, CX2]):
            return (Tool.COALPOWER, CX2, CY2)

    # Build wire spine from plant 1 rightward to connect both neighborhoods
    # Horizontal wire at CY1 from CX1+2 to CX2+2
    wire_spine_y = CY1
    for wx in range(CX1 + 2, CX2 + 3):
        wy = wire_spine_y
        if not in_bounds(wx, wy):
            break
        if not bool(wm[wy, wx]) and not bool(pm[wy, wx]) and not bool(rm[wy, wx]):
            if bool(em[wy, wx]):
                return (Tool.WIRE, wx, wy)
            # skip blocked
        # continue to find gaps

    # Vertical wire branches from spine upward and downward (every 5 cols)
    for bx in range(CX1 + 5, CX2 + 3, 5):
        if not in_bounds(bx, wire_spine_y):
            continue
        if not (bool(wm[wire_spine_y, bx]) or bool(pm[wire_spine_y, bx])):
            continue
        for sign in [-1, 1]:
            for dy in range(1, 10):
                wy, wx = wire_spine_y + sign * dy, bx
                if not in_bounds(wx, wy):
                    break
                if bool(wm[wy, wx]) or bool(pm[wy, wx]) or bool(rm[wy, wx]):
                    continue
                if bool(em[wy, wx]):
                    return (Tool.WIRE, wx, wy)
                break

    # Build road grid:
    # Horizontal roads at spine_y - 3 and spine_y + 3 (two lanes)
    # Vertical connectors every 4 columns
    road_rows = [wire_spine_y - 3, wire_spine_y + 3]
    road_start = CX1 - 2
    road_end = CX2 + 2

    for ry in road_rows:
        for rx in range(road_start, road_end + 1):
            if not in_bounds(rx, ry):
                continue
            if not bool(rm[ry, rx]) and not bool(pm[ry, rx]):
                if bool(em[ry, rx]) or bool(wm[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    # Vertical connector roads every 5 cols
    for vc in range(road_start, road_end + 1, 5):
        for vr in range(road_rows[0], road_rows[1] + 1):
            if not in_bounds(vc, vr):
                continue
            if not bool(rm[vr, vc]) and not bool(pm[vr, vc]):
                if bool(em[vr, vc]) or bool(wm[vr, vc]):
                    return (Tool.ROAD, vc, vr)

    # Also add roads closer to plant2
    road_rows2 = [CY2 - 3, CY2 + 3]
    road_start2 = CX2 - 5
    road_end2 = CX2 + 15
    for ry in road_rows2:
        for rx in range(road_start2, road_end2 + 1):
            if not in_bounds(rx, ry):
                continue
            if not bool(rm[ry, rx]) and not bool(pm[ry, rx]):
                if bool(em[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    # Build neighbor masks for zone placement
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        step_hash = int(obs.step * 17 + int(obs.city_pop * 3)) % max(len(cxs), 1)
        for offset in range(min(len(cxs), 60)):
            k = (step_hash + offset * 11) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # Services when population is growing
    if obs.city_pop > 200:
        fx, fy = CX1 + 3, CY1 - 10
        if in_bounds(fx, fy) and bool(em[fy, fx]):
            return (Tool.FIRESTATION, fx, fy)
        px2, py2 = CX2 + 3, CY2 - 10
        if in_bounds(px2, py2) and bool(em[py2, px2]):
            return (Tool.POLICESTATION, px2, py2)

    # Third power plant if needed
    if total_zones > 20 and not has_plant_nearby(CX2 + 30, CY1, radius=10):
        p3x, p3y = CX2 + 30, CY1
        if in_bounds(p3x, p3y) and bool(em[p3y, p3x]):
            return (Tool.COALPOWER, p3x, p3y)

    # Extend wire from existing wire frontier
    if len(wire_xs) > 0:
        step_k2 = int(obs.step * 7) % max(len(wire_xs), 1)
        wx_s, wy_s = int(wire_xs[step_k2]), int(wire_ys[step_k2])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = wx_s + dx2, wy_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)

    # Extend roads from existing road frontier
    if len(road_xs) > 0:
        step_k = int(obs.step * 13) % max(len(road_xs), 1)
        rx_s, ry_s = int(road_xs[step_k]), int(road_ys[step_k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx_s + dx2, ry_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads map each step, places next tile based on current state.
    Strategy:
    - Phase 0: Place coal power plant
    - Phase 1: Build horizontal wire spine from plant rightward
    - Phase 2: Build vertical road spine perpendicular to wire
    - Phase 3: Extend horizontal roads from spine to serve zones
    - Phase 4: Place zones (RES/COM/IND) adjacent to roads with power nearby
    Reactive: all decisions based on current obs.tile_map
    """
    tm = obs.tile_map
    emp = empty_mask(tm)
    res = res_mask(tm)
    com = com_mask(tm)
    ind = ind_mask(tm)
    road = road_mask(tm)
    wire = wire_mask(tm)
    plant = plant_mask(tm)

    # Anchor: plant goes near top-left of center area
    anchor_x, anchor_y = 35, 45

    # --- Phase 0: Place coal power plant if none exists ---
    if not np.any(plant):
        return (Tool.COALPOWER, anchor_x, anchor_y)

    # Find plant centroid
    plant_ys, plant_xs = np.where(plant)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    # Wire spine: horizontal row at py, extending right from plant
    wire_row = py
    wire_start_x = px + 2  # just right of plant
    wire_end_x = px + 25   # extend far right

    # Build wire spine: find leftmost gap in wire row that is adjacent to existing wire/plant
    for wx in range(wire_start_x, wire_end_x + 1):
        if 0 <= wx < WORLD_W and 0 <= wire_row < WORLD_H:
            if not wire[wire_row, wx] and not plant[wire_row, wx]:
                # Check adjacency to power
                adj = False
                for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]:
                    ny2, nx2 = wire_row+ddy, wx+ddx
                    if 0 <= ny2 < WORLD_H and 0 <= nx2 < WORLD_W:
                        if wire[ny2, nx2] or plant[ny2, nx2]:
                            adj = True
                            break
                if adj:
                    return (Tool.WIRE, wx, wire_row)
                # If wire_start_x and nothing adjacent yet, start from plant edge
                if wx == wire_start_x:
                    # plant occupies ~px-1..px+1, py-1..py+1; wire_start_x = px+2
                    # check if plant is adjacent
                    for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]:
                        ny2, nx2 = wire_row+ddy, wx+ddx
                        if 0 <= ny2 < WORLD_H and 0 <= nx2 < WORLD_W:
                            if plant[ny2, nx2]:
                                adj = True
                                break
                    if adj:
                        return (Tool.WIRE, wx, wire_row)

    # Road spine: vertical road column at wire_end_x + 1
    road_col = wire_end_x + 1
    road_span_top = py - 18
    road_span_bot = py + 18

    # Build vertical road spine
    for ry in range(road_span_top, road_span_bot + 1):
        if 0 <= ry < WORLD_H and 0 <= road_col < WORLD_W:
            if not road[ry, road_col]:
                # Check adjacency to existing road or wire
                adj = False
                for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]:
                    ny2, nx2 = ry+ddy, road_col+ddx
                    if 0 <= ny2 < WORLD_H and 0 <= nx2 < WORLD_W:
                        if road[ny2, nx2] or wire[ny2, nx2] or plant[ny2, nx2]:
                            adj = True
                            break
                if adj:
                    return (Tool.ROAD, road_col, ry)
                # Allow starting road at wire endpoint
                if ry == py and road_col == wire_end_x + 1:
                    # wire should be at wire_end_x, py
                    if wire[py, wire_end_x]:
                        return (Tool.ROAD, road_col, ry)

    # Horizontal road branches: extend left and right from road spine at intervals
    # Every 4 rows, build a horizontal branch
    branch_rows = list(range(road_span_top + 2, road_span_bot, 4))

    for br_y in branch_rows:
        if not (0 <= br_y < WORLD_H):
            continue
        # Extend left from road spine
        for bx in range(road_col - 1, road_col - 12, -1):
            if 0 <= bx < WORLD_W:
                if not road[br_y, bx]:
                    adj = False
                    for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]:
                        ny2, nx2 = br_y+ddy, bx+ddx
                        if 0 <= ny2 < WORLD_H and 0 <= nx2 < WORLD_W:
                            if road[ny2, nx2]:
                                adj = True
                                break
                    if adj:
                        return (Tool.ROAD, bx, br_y)
                    break  # gap in road, can't extend further without adjacency
        # Extend right from road spine
        for bx in range(road_col + 1, road_col + 12):
            if 0 <= bx < WORLD_W:
                if not road[br_y, bx]:
                    adj = False
                    for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]:
                        ny2, nx2 = br_y+ddy, bx+ddx
                        if 0 <= ny2 < WORLD_H and 0 <= nx2 < WORLD_W:
                            if road[ny2, nx2]:
                                adj = True
                                break
                    if adj:
                        return (Tool.ROAD, bx, br_y)
                    break

    # --- Phase: Place zones adjacent to roads with power coverage ---
    zones = res | com | ind
    n_res = int(np.sum(res))
    n_com = int(np.sum(com))
    n_ind = int(np.sum(ind))
    total = n_res + n_com + n_ind

    # Choose tool: ratio ~3 RES : 1 COM : 1 IND
    r = (obs.step * 13 + int(tm[py % WORLD_H, (px+1) % WORLD_W])) % 5
    if r < 3:
        tool = Tool.RESIDENTIAL
    elif r == 3:
        tool = Tool.COMMERCIAL
    else:
        tool = Tool.INDUSTRIAL

    # Build proximity maps
    road_near = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            road_near |= np.roll(np.roll(road, dy2, axis=0), dx2, axis=1)

    wire_near = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-4, 5):
        for dx2 in range(-4, 5):
            wire_near |= np.roll(np.roll(wire, dy2, axis=0), dx2, axis=1)
            wire_near |= np.roll(np.roll(plant, dy2, axis=0), dx2, axis=1)

    # Candidates: empty tiles with road nearby and power nearby
    cand = emp & road_near & wire_near
    # Keep away from edges
    cand[:2, :] = False
    cand[98:, :] = False
    cand[:, :2] = False
    cand[:, 118:] = False
    # Avoid placing on the road/wire columns themselves
    if 0 <= road_col < WORLD_W:
        cand[:, road_col] = False
    if 0 <= wire_end_x < WORLD_W:
        cand[:, wire_end_x] = False

    cand_ys, cand_xs = np.where(cand)
    if len(cand_xs) == 0:
        # Extend road spine further if no candidates
        for ry2 in range(road_span_bot + 1, road_span_bot + 6):
            if 0 <= ry2 < WORLD_H:
                if not road[ry2, road_col]:
                    if road[ry2-1, road_col]:
                        return (Tool.ROAD, road_col, ry2)
        return None

    # Score: prefer close to road spine, close to other zones, not too far from wire
    zone_near = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    if np.any(zones):
        for dy2 in range(-4, 5):
            for dx2 in range(-4, 5):
                zone_near |= np.roll(np.roll(zones, dy2, axis=0), dx2, axis=1)

    scores = np.zeros(len(cand_xs), dtype=float)
    for i in range(len(cand_xs)):
        x, y = int(cand_xs[i]), int(cand_ys[i])
        dist_col = abs(x - road_col)
        dist_py = abs(y - py)
        near_zone = 1 if zone_near[y, x] else 0
        # Prefer positions near branch roads
        on_branch = any(abs(y - br) <= 1 for br in branch_rows if 0 <= br < WORLD_H)
        scores[i] = near_zone * 8 + (3 if on_branch else 0) - dist_col * 0.5 - dist_py * 0.05

    max_s = np.max(scores)
    top = np.where(scores >= max_s - 0.5)[0]
    pick = top[obs.step % len(top)]
    bx, by = int(cand_xs[pick]), int(cand_ys[pick])
    return (tool, bx, by)

def act(obs, state):
    """
    Combined policy: vertical wire spine from Parent A + reactive zone placement from Parent B.
    - Coal plant placed first
    - Vertical wire spine column adjacent to plant
    - Road columns on both sides of wire spine
    - Zones placed reactively wherever road+wire access exists
    - Expansion when population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Step 1: Place coal power plant ---
    has_plant = np.any(pm)
    if not has_plant:
        return (Tool.COALPOWER, 47, 50)

    # Find plant location
    plant_ys, plant_xs = np.where(pm)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        r_r = res_count / t
        c_r = com_count / t
        i_r = ind_count / t
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Vertical wire spine column (just right of plant) ---
    wire_col = px + 2  # wire spine column

    # Vertical span: grow with population
    base_span = 12
    extra_span = min(30, obs.city_pop // 20)
    target_span = base_span + extra_span
    tmin = max(2, py - target_span)
    tmax = min(WORLD_H - 3, py + target_span)

    wire_rows_in_col = sorted(r for r in range(WORLD_H) if wm[r, wire_col])

    # Step 2: Build vertical wire spine
    if not wire_rows_in_col:
        # Start wire adjacent to plant
        for dy in range(-2, 3):
            ny = py + dy
            if in_bounds(wire_col, ny) and em[ny, wire_col]:
                return (Tool.WIRE, wire_col, ny)
    else:
        min_wr = min(wire_rows_in_col)
        max_wr = max(wire_rows_in_col)
        # Extend downward
        if max_wr < tmax:
            nr = max_wr + 1
            if in_bounds(wire_col, nr) and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if min_wr > tmin:
            nr = min_wr - 1
            if in_bounds(wire_col, nr) and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    wire_rows_set = set(wire_rows_in_col)

    # Road columns: one on each side of wire spine
    road_col_r = wire_col + 1
    road_col_l = wire_col - 1

    # Step 3: Build road columns along wire spine
    for wr in wire_rows_in_col:
        # Right road
        if in_bounds(road_col_r, wr) and em[wr, road_col_r]:
            return (Tool.ROAD, road_col_r, wr)
        # Left road
        if in_bounds(road_col_l, wr) and road_col_l >= 0 and em[wr, road_col_l]:
            return (Tool.ROAD, road_col_l, wr)

    # --- Reactive zone placement ---
    # Build neighbor masks for road and wire proximity
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Zone must be 3x3 clear
    zone_set = set(zip(
        np.concatenate([np.where(resm)[0], np.where(comm)[0], np.where(indm)[0]]).tolist(),
        np.concatenate([np.where(resm)[1], np.where(comm)[1], np.where(indm)[1]]).tolist()
    ))

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    # Candidate zone centers: near road AND wire, not too close to edge
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prefer positions near the wire spine, sorted by distance to spine column
        # Use step-based deterministic scan
        step_hash = int(obs.step * 17 + total_zones * 7) % max(len(cxs), 1)
        for offset in range(min(len(cxs), 60)):
            k = (step_hash + offset * 13) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # --- Lateral roads to expand zone access ---
    # From road columns, extend outward to reach more zone positions
    road_xs_arr, road_ys_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        # Extend roads sideways from existing road frontier
        for dy, dx in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            step_k = int(obs.step * 11) % max(len(road_xs_arr), 1)
            rx_s = int(road_xs_arr[step_k])
            ry_s = int(road_ys_arr[step_k])
            nx2, ny2 = rx_s + dx, ry_s + dy
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                # Only extend if it leads somewhere useful (near wire)
                if nbr_wire[ny2, nx2]:
                    return (Tool.ROAD, nx2, ny2)

    # --- Second power plant when many zones exist ---
    if total_zones > 15 or obs.city_pop > 400:
        # Place second plant far enough from first
        p2x = px + 25
        p2y = py
        if in_bounds(p2x, p2y):
            nearby_plant = False
            for dy in range(-6, 7):
                for dx in range(-6, 7):
                    ny2, nx2 = p2y + dy, p2x + dx
                    if in_bounds(nx2, ny2) and pm[ny2, nx2]:
                        nearby_plant = True
            if not nearby_plant and em[p2y, p2x]:
                return (Tool.COALPOWER, p2x, p2y)
            # Connect with wire
            # Wire from wire_col to p2x at py
            for wc in range(wire_col + 2, p2x - 1):
                if in_bounds(wc, py) and em[py, wc]:
                    return (Tool.WIRE, wc, py)

    # --- Add services for happiness ---
    if obs.city_pop > 150:
        fx, fy = px - 5, py - 6
        if in_bounds(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
        fx2, fy2 = px - 5, py + 6
        if in_bounds(fx2, fy2) and em[fy2, fx2]:
            return (Tool.POLICESTATION, fx2, fy2)

    # --- Extend wire frontier if stuck ---
    wire_xs_arr = np.where(wm)[1]
    wire_ys_arr = np.where(wm)[0]
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 7) % max(len(wire_xs_arr), 1)
        wx_s = int(wire_xs_arr[step_k2])
        wy_s = int(wire_ys_arr[step_k2])
        for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx2, ny2 = wx_s + dx2, wy_s + dy2
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Improved policy: builds a horizontal road spine with zones on both sides,
    wires running parallel, and a coal plant connected to the wire network.
    Uses a 2:1:1 RES:COM:IND ratio and places zones on both sides of the road.
    """
    tm = obs.tile_map
    emp = empty_mask(tm)
    res = res_mask(tm)
    com = com_mask(tm)
    ind = ind_mask(tm)
    road = road_mask(tm)
    wire = wire_mask(tm)
    plant = plant_mask(tm)

    # Anchor: place infrastructure in upper-center area
    anchor_x = WORLD_W // 2 - 10  # start x of horizontal spine
    anchor_y = WORLD_H // 2       # y of horizontal road spine
    wire_y = anchor_y - 1         # wire row just above road
    road_y = anchor_y             # road row

    # Phase 0: Place coal power plant if none exists
    if not np.any(plant):
        # Place plant to the left of the road spine
        return (Tool.COALPOWER, anchor_x - 4, anchor_y - 1)

    # Find plant centroid
    plant_ys, plant_xs = np.where(plant)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    # Phase 1: Build wire spine horizontally from plant rightward
    # Wire runs at wire_y from px+2 to anchor_x+25
    wire_start_x = px + 2
    wire_end_x = min(anchor_x + 30, WORLD_W - 2)

    for wx in range(wire_start_x, wire_end_x + 1):
        wy = wire_y
        if 0 <= wx < WORLD_W and 0 <= wy < WORLD_H:
            if not wire[wy, wx] and not plant[wy, wx]:
                # Check connectivity (adjacent to wire or plant)
                adj = False
                for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]:
                    ny2, nx2 = wy+ddy, wx+ddx
                    if 0 <= ny2 < WORLD_H and 0 <= nx2 < WORLD_W:
                        if wire[ny2, nx2] or plant[ny2, nx2]:
                            adj = True
                            break
                if adj:
                    return (Tool.WIRE, wx, wy)

    # Phase 2: Build road spine horizontally below wire
    road_start_x = px + 2
    road_end_x = min(anchor_x + 30, WORLD_W - 2)

    for rx in range(road_start_x, road_end_x + 1):
        ry = road_y
        if 0 <= rx < WORLD_W and 0 <= ry < WORLD_H:
            if not road[ry, rx]:
                # Allow starting near plant or adjacent to existing road/wire
                adj = False
                for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]:
                    ny2, nx2 = ry+ddy, rx+ddx
                    if 0 <= ny2 < WORLD_H and 0 <= nx2 < WORLD_W:
                        if road[ny2, nx2] or wire[ny2, nx2] or plant[ny2, nx2]:
                            adj = True
                            break
                if adj:
                    return (Tool.ROAD, rx, ry)

    # Phase 3: Add vertical cross-roads every 6 tiles for more coverage
    for base_x in range(road_start_x, road_end_x, 6):
        for vert_dy in range(1, 8):
            # Extend road downward
            ry2 = road_y + vert_dy
            rx2 = base_x
            if 0 <= ry2 < WORLD_H and 0 <= rx2 < WORLD_W:
                if not road[ry2, rx2]:
                    adj = False
                    for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]:
                        ny2, nx2 = ry2+ddy, rx2+ddx
                        if 0 <= ny2 < WORLD_H and 0 <= nx2 < WORLD_W:
                            if road[ny2, nx2]:
                                adj = True
                                break
                    if adj:
                        return (Tool.ROAD, rx2, ry2)
            # Extend road upward
            ry3 = road_y - vert_dy
            if 0 <= ry3 < WORLD_H and 0 <= rx2 < WORLD_W:
                if not road[ry3, rx2]:
                    adj = False
                    for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]:
                        ny2, nx2 = ry3+ddy, rx2+ddx
                        if 0 <= ny2 < WORLD_H and 0 <= nx2 < WORLD_W:
                            if road[ny2, nx2]:
                                adj = True
                                break
                    if adj:
                        return (Tool.ROAD, rx2, ry3)

    # Phase 4: Add vertical wires from main wire spine downward to power zones
    for base_x in range(wire_start_x, wire_end_x, 3):
        for vert_dy in range(1, 10):
            wy2 = wire_y + vert_dy
            wx2 = base_x
            if 0 <= wy2 < WORLD_H and 0 <= wx2 < WORLD_W:
                if not wire[wy2, wx2] and not plant[wy2, wx2] and not road[wy2, wx2]:
                    adj = False
                    for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]:
                        ny2, nx2 = wy2+ddy, wx2+ddx
                        if 0 <= ny2 < WORLD_H and 0 <= nx2 < WORLD_W:
                            if wire[ny2, nx2] or plant[ny2, nx2]:
                                adj = True
                                break
                    if adj:
                        return (Tool.WIRE, wx2, wy2)

    # Phase 5: Place zones adjacent to roads and powered by wires
    zones = res | com | ind
    n_res = int(np.sum(res))
    n_com = int(np.sum(com))
    n_ind = int(np.sum(ind))
    total_zones = n_res + n_com + n_ind

    # Zone tool selection: 2 RES : 1 COM : 1 IND
    r = (obs.step * 13 + obs.step // 4) % 4
    if r < 2:
        tool = Tool.RESIDENTIAL
    elif r < 3:
        tool = Tool.COMMERCIAL
    else:
        tool = Tool.INDUSTRIAL

    # Build proximity maps
    road_near = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            road_near |= np.roll(np.roll(road, dy2, axis=0), dx2, axis=1)

    wire_near = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            wire_near |= np.roll(np.roll(wire, dy2, axis=0), dx2, axis=1)
            wire_near |= np.roll(np.roll(plant, dy2, axis=0), dx2, axis=1)

    cand_mask = emp & road_near & wire_near
    # Keep away from wire/road spine rows
    cand_mask[wire_y, :] = False
    cand_mask[road_y, :] = False
    # Keep away from edges (3x3 zone needs margin)
    cand_mask[:1, :] = False
    cand_mask[WORLD_H-1:, :] = False
    cand_mask[:, :1] = False
    cand_mask[:, WORLD_W-1:] = False
    # Don't place on plant area
    cand_mask[py-1:py+2, px-1:px+2] = False

    cand_ys, cand_xs = np.where(cand_mask)

    if len(cand_xs) == 0:
        # Fallback: extend road further right
        for rx2 in range(road_end_x, min(road_end_x + 10, WORLD_W - 2)):
            if not road[road_y, rx2]:
                return (Tool.ROAD, rx2, road_y)
        return None

    # Score: prefer close to road spine y, close to wire spine, cluster near existing zones
    zone_near = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    if np.any(zones):
        for dy2 in range(-4, 5):
            for dx2 in range(-4, 5):
                zone_near |= np.roll(np.roll(zones, dy2, axis=0), dx2, axis=1)

    scores = []
    for i in range(len(cand_xs)):
        x, y = int(cand_xs[i]), int(cand_ys[i])
        dist_road_y = abs(y - road_y)
        dist_from_anchor = abs(x - (anchor_x + 10))
        near_zone = 5 if zone_near[y, x] else 0
        # Prefer zones spread along the road (not too close to edges)
        score = near_zone - dist_road_y * 0.5 - dist_from_anchor * 0.05
        scores.append(score)

    scores = np.array(scores)
    max_score = np.max(scores)
    top_mask = scores >= max_score - 1.0
    top_indices = np.where(top_mask)[0]
    pick = top_indices[obs.step % len(top_indices)]
    bx, by = int(cand_xs[pick]), int(cand_ys[pick])
    return (tool, bx, by)

def act(obs, state):
    """
    Combined policy:
    - Uses Parent A's reactive/closed-loop approach (reads map each step)
    - Uses Parent B's dual-neighborhood idea with two coal plants
    - Vertical wire spines + road columns + zones on both sides
    - Balanced R/C/I ratios
    - Expands based on population
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # Gather zone counts
    res_positions = set(zip(*np.where(res_m))) if np.any(res_m) else set()
    com_positions = set(zip(*np.where(com_m))) if np.any(com_m) else set()
    ind_positions = set(zip(*np.where(ind_m))) if np.any(ind_m) else set()
    all_zones = res_positions | com_positions | ind_positions
    res_count = len(res_positions)
    com_count = len(com_positions)
    ind_count = len(ind_positions)

    wire_positions = set(zip(*np.where(wm))) if np.any(wm) else set()
    road_positions = set(zip(*np.where(rm))) if np.any(rm) else set()

    # ---- Cluster definitions ----
    # Cluster A (left): plant at (40, 50), wire spine at col 44, road at col 46
    # Cluster B (right): plant at (75, 50), wire spine at col 71, road at col 69

    clusterA = {
        'plant_cx': 40, 'plant_cy': 50,
        'wire_col': 44,
        'road_col': 46,
        'left_zone_col': 41,
        'right_zone_col': 49,
    }
    clusterB = {
        'plant_cx': 75, 'plant_cy': 50,
        'wire_col': 71,
        'road_col': 69,
        'left_zone_col': 66,
        'right_zone_col': 74,
    }

    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def already_zone_nearby(zr, zc):
        return any(abs(zr - pr) <= 2 and abs(zc - pc) <= 2 for (pr, pc) in all_zones)

    def pick_zone_type():
        if res_count == 0:
            return Tool.RESIDENTIAL
        if ind_count * 4 < res_count:
            return Tool.INDUSTRIAL
        if com_count * 4 < res_count:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def plant_present_near(px, py):
        """Check if plant tiles exist near (px, py)"""
        for dr in range(-2, 3):
            for dc in range(-2, 3):
                rr, rc = py + dr, px + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if pm[rr, rc]:
                        return True
        return False

    def process_cluster(cl, pop_threshold=0):
        """Returns an action tuple or None for a given cluster."""
        if obs.city_pop < pop_threshold:
            return None

        plant_cx = cl['plant_cx']
        plant_cy = cl['plant_cy']
        wire_col = cl['wire_col']
        road_col = cl['road_col']
        left_zone_col = cl['left_zone_col']
        right_zone_col = cl['right_zone_col']

        # Dynamic span
        base_span = 12
        extra_span = min(20, obs.city_pop // 30)
        target_span = base_span + extra_span
        tmin = max(2, plant_cy - target_span)
        tmax = min(WORLD_H - 3, plant_cy + target_span)

        # Phase 1: Ensure plant placed
        if not plant_present_near(plant_cx, plant_cy):
            return (Tool.COALPOWER, plant_cx, plant_cy)

        # Wire rows in this cluster's wire_col
        wire_rows_in_col = sorted(r for (r, c) in wire_positions if c == wire_col)
        road_rows_in_col = sorted(r for (r, c) in road_positions if c == road_col)
        road_rows_set = set(road_rows_in_col)

        # Phase 2: Extend wire spine vertically
        if not wire_rows_in_col:
            # Start wire adjacent to plant
            for try_r in [plant_cy, plant_cy - 1, plant_cy + 1]:
                if 0 <= try_r < WORLD_H:
                    if em[try_r, wire_col]:
                        return (Tool.WIRE, wire_col, try_r)
        else:
            min_wr = min(wire_rows_in_col)
            max_wr = max(wire_rows_in_col)
            if max_wr < tmax:
                nr = max_wr + 1
                if 0 < nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                    return (Tool.WIRE, wire_col, nr)
            if min_wr > tmin:
                nr = min_wr - 1
                if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                    return (Tool.WIRE, wire_col, nr)

        if not wire_rows_in_col:
            return None

        # Phase 3: Build road column matching wire coverage
        for wr in wire_rows_in_col:
            if wr not in road_rows_set and 0 <= road_col < WORLD_W:
                if em[wr, road_col]:
                    return (Tool.ROAD, road_col, wr)

        # Phase 4: Place zones on both sides of wire/road
        for zr in sorted(wire_rows_in_col):
            road_nearby = any(abs(zr - rr) <= 2 for rr in road_rows_set)
            if not road_nearby:
                continue
            for zc in [left_zone_col, right_zone_col]:
                if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                    if not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                        return (pick_zone_type(), zc, zr)

        # Phase 5: Lateral wires from spine toward left zones
        for wr in wire_rows_in_col:
            step_dir = -1 if wire_col > left_zone_col else 1
            for wc in range(wire_col + step_dir, left_zone_col - step_dir, step_dir):
                if 0 <= wc < WORLD_W and em[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                break  # Only one per step to avoid long loops

        # Phase 6: Lateral roads from road col toward right zones
        step_dir = 1 if road_col < right_zone_col else -1
        for wr in wire_rows_in_col:
            for rc in range(road_col + step_dir, right_zone_col + step_dir, step_dir):
                if 0 <= rc < WORLD_W and em[wr, rc]:
                    return (Tool.ROAD, rc, wr)
                break

        return None

    # Try cluster A first (always active)
    result = process_cluster(clusterA, pop_threshold=0)
    if result is not None:
        return result

    # Try cluster B (activate early to build in parallel)
    result = process_cluster(clusterB, pop_threshold=0)
    if result is not None:
        return result

    # Connect the two clusters with wire at plant_cy level
    # Wire bridge from clusterA wire_col to clusterB wire_col at row 50
    bridge_row = 50
    a_wc = clusterA['wire_col']
    b_wc = clusterB['wire_col']
    for wc in range(a_wc + 1, b_wc):
        if em[bridge_row, wc]:
            return (Tool.WIRE, wc, bridge_row)

    # Connect with road bridge slightly offset
    bridge_road_row = 51
    a_rc = clusterA['road_col']
    b_rc = clusterB['road_col']
    for rc in range(min(a_rc, b_rc), max(a_rc, b_rc) + 1):
        if 0 <= rc < WORLD_W and em[bridge_road_row, rc]:
            return (Tool.ROAD, rc, bridge_road_row)

    # Add fire/police stations for land value
    if obs.city_pop >= 100:
        # Fire station near center
        fs_x, fs_y = 57, 50
        if zone_area_free(fs_y, fs_x):
            return (Tool.FIRESTATION, fs_x, fs_y)

    if obs.city_pop >= 200:
        ps_x, ps_y = 60, 55
        if zone_area_free(ps_y, ps_x):
            return (Tool.POLICESTATION, ps_x, ps_y)

    # Reactive: find any empty 3x3 spot near roads+wires to place more zones
    if obs.city_pop >= 50:
        for cy_s in range(35, 70, 3):
            for cx_s in range(35, 85, 3):
                clear = True
                for dy in range(-1, 2):
                    for dx in range(-1, 2):
                        ny, nx = cy_s + dy, cx_s + dx
                        if 0 <= ny < WORLD_H and 0 <= nx < WORLD_W:
                            if not em[ny, nx]:
                                clear = False
                                break
                    if not clear:
                        break
                if not clear:
                    continue
                road_near = any(
                    0 <= cy_s + dy < WORLD_H and 0 <= cx_s + dx < WORLD_W and rm[cy_s + dy, cx_s + dx]
                    for dy in range(-2, 3) for dx in range(-2, 3)
                )
                wire_near = any(
                    0 <= cy_s + dy < WORLD_H and 0 <= cx_s + dx < WORLD_W and wm[cy_s + dy, cx_s + dx]
                    for dy in range(-2, 3) for dx in range(-2, 3)
                )
                if road_near and wire_near and not already_zone_nearby(cy_s, cx_s):
                    return (pick_zone_type(), cx_s, cy_s)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder combining best of both parents.
    - Parent A: horizontal wire spine + parallel roads + reactive zone placement
    - Parent B: vertical wire spine + systematic corridor + phase-based expansion

    Strategy: Build a cross-shaped infrastructure (horizontal + vertical spines),
    power with coal plant, roads alongside wires, then pack zones densely.
    React to current tile_map every step.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    all_zone = resm | comm | indm

    # Anchor near center-left for good spread
    CX, CY = 35, 50

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Zone tool picker based on current balance
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        if com_count / t < 0.22:
            return Tool.COMMERCIAL
        if ind_count / t < 0.18:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_area_clear(zx, zy):
        """Check 3x3 zone is placeable (empty or already zone)."""
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zy + dr, zx + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone[rr, rc]:
                    return False
        return True

    def zone_exists_nearby(zx, zy, r=2):
        r0, r1 = max(0, zy-r), min(WORLD_H, zy+r+1)
        c0, c1 = max(0, zx-r), min(WORLD_W, zx+r+1)
        return np.any(all_zone[r0:r1, c0:c1])

    def wire_nearby(zx, zy, r=5):
        r0, r1 = max(0, zy-r), min(WORLD_H, zy+r+1)
        c0, c1 = max(0, zx-r), min(WORLD_W, zx+r+1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def road_nearby(zx, zy, r=3):
        r0, r1 = max(0, zy-r), min(WORLD_H, zy+r+1)
        c0, c1 = max(0, zx-r), min(WORLD_W, zx+r+1)
        return np.any(rm[r0:r1, c0:c1])

    # ---- Phase 1: Place coal power plant ----
    if not np.any(pm):
        return (Tool.COALPOWER, CX, CY)

    # Find plant centroid
    plant_ys, plant_xs = np.where(pm)
    pcx = int(np.mean(plant_xs))
    pcy = int(np.mean(plant_ys))

    # ---- Infrastructure layout ----
    # Horizontal wire spine at pcy, extending right
    h_wire_start = pcx + 2
    h_wire_end = min(pcx + 60, WORLD_W - 3)

    # Vertical wire spine at pcx+3, extending up and down
    v_wire_col = pcx + 3
    v_wire_top = max(2, pcy - 25)
    v_wire_bot = min(WORLD_H - 3, pcy + 25)

    # Road rows: parallel to horizontal spine at +/-3
    road_top_y = pcy - 3
    road_bot_y = pcy + 3
    road_start_x = pcx + 2
    road_end_x = min(pcx + 58, WORLD_W - 3)

    # Road col parallel to vertical spine
    road_right_col = v_wire_col + 2

    # ---- Phase 2: Build horizontal wire spine ----
    for wx in range(h_wire_start, h_wire_end + 1):
        wy = pcy
        if not in_bounds(wx, wy):
            break
        if not wm[wy, wx] and not pm[wy, wx]:
            if em[wy, wx]:
                return (Tool.WIRE, wx, wy)
            break  # blocked, stop trying

    # ---- Phase 3: Build vertical wire spine ----
    # Downward
    for wy in range(pcy + 1, v_wire_bot + 1):
        wx = v_wire_col
        if not in_bounds(wx, wy):
            break
        if not wm[wy, wx] and not pm[wy, wx]:
            if em[wy, wx]:
                return (Tool.WIRE, wx, wy)
            break

    # Upward
    for wy in range(pcy - 1, v_wire_top - 1, -1):
        wx = v_wire_col
        if not in_bounds(wx, wy):
            break
        if not wm[wy, wx] and not pm[wy, wx]:
            if em[wy, wx]:
                return (Tool.WIRE, wx, wy)
            break

    # ---- Phase 4: Build top road row ----
    for rx in range(road_start_x, road_end_x + 1):
        ry = road_top_y
        if not in_bounds(rx, ry):
            break
        if not rm[ry, rx] and not pm[ry, rx]:
            if em[ry, rx]:
                return (Tool.ROAD, rx, ry)
            break

    # ---- Phase 5: Build bottom road row ----
    for rx in range(road_start_x, road_end_x + 1):
        ry = road_bot_y
        if not in_bounds(rx, ry):
            break
        if not rm[ry, rx] and not pm[ry, rx]:
            if em[ry, rx]:
                return (Tool.ROAD, rx, ry)
            break

    # ---- Phase 6: Build road column alongside vertical wire spine ----
    for ry in range(v_wire_top, v_wire_bot + 1):
        rx = road_right_col
        if not in_bounds(rx, ry):
            continue
        if not rm[ry, rx] and not pm[ry, rx] and not wm[ry, rx]:
            if em[ry, rx]:
                return (Tool.ROAD, rx, ry)

    # ---- Phase 7: Lateral wires from vertical spine to zone area ----
    v_wire_rows = [r for r in range(WORLD_H) if wm[r, v_wire_col] or pm[r, v_wire_col]]
    for wr in v_wire_rows:
        # Wire rightward to reach right zones
        for wc in range(v_wire_col + 1, road_right_col + 4):
            if not in_bounds(wc, wr):
                break
            if wm[wr, wc] or pm[wr, wc]:
                break
            if rm[wr, wc]:
                continue  # skip road tiles
            if em[wr, wc]:
                return (Tool.WIRE, wc, wr)
            break

    # ---- Phase 8: Place zones reactively ----
    # Build neighbor masks for road and wire coverage
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Candidate centers: empty + road nearby + wire nearby + interior
    cand = em & nbr_road & nbr_wire
    cand[:2, :] = False; cand[WORLD_H-2:, :] = False
    cand[:, :2] = False; cand[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        # Reactive: shuffle based on step and pop to avoid getting stuck
        idx = (obs.step * 19 + int(obs.city_pop * 7)) % len(cxs)
        for off in range(min(len(cxs), 60)):
            k = (idx + off * 13) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_area_clear(zx, zy) and not zone_exists_nearby(zx, zy, 1):
                return (pick_tool(), zx, zy)

    # ---- Phase 9: Second power plant when zones growing ----
    plant_tiles = int(np.sum(pm))
    if (total_zones > 8 or obs.city_pop > 250) and plant_tiles < 9:
        # Try placing second plant
        for attempt in [(pcx + 20, pcy), (pcx + 20, pcy - 15), (pcx + 20, pcy + 15)]:
            px2, py2 = attempt
            if 2 <= px2 <= WORLD_W - 4 and 2 <= py2 <= WORLD_H - 4:
                if np.all(em[py2-1:py2+2, px2-1:px2+2]):
                    return (Tool.COALPOWER, px2, py2)

    # ---- Phase 10: Services ----
    if obs.city_pop > 80:
        svcs = [(Tool.FIRESTATION, pcx + 7, pcy - 10),
                (Tool.POLICESTATION, pcx + 7, pcy + 10)]
        for tool, sx, sy in svcs:
            if in_bounds(sx, sy) and em[sy, sx]:
                return (tool, sx, sy)

    # ---- Phase 11: Extend wires from existing frontier reactively ----
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        k = (obs.step * 7) % len(wire_xs)
        wx0, wy0 = int(wire_xs[k]), int(wire_ys[k])
        for dx2, dy2 in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx2, ny2 = wx0+dx2, wy0+dy2
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                # Only extend if it moves toward useful area
                if abs(nx2 - pcx) < 65 and abs(ny2 - pcy) < 30:
                    return (Tool.WIRE, nx2, ny2)

    # ---- Phase 12: Extend roads from existing frontier ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        k = (obs.step * 11) % len(road_xs)
        rx0, ry0 = int(road_xs[k]), int(road_ys[k])
        for dx2, dy2 in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx2, ny2 = rx0+dx2, ry0+dy2
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                if abs(nx2 - pcx) < 65 and abs(ny2 - pcy) < 30:
                    return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map each step and decides next action
    based on current state of the city.

    Strategy:
    - Phase 0: Place power plant
    - Phase 1: Extend wire network from plant toward city center
    - Phase 2: Place roads adjacent to wired areas
    - Phase 3: Place zones adjacent to roads that have wire nearby
    - Continuously scan and fill gaps reactively
    """

    tile = obs.tile_map  # (100, 120) uint16

    # Helper: check bounds
    def inbounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Helper: find nearest empty cell adjacent to a mask
    def find_adjacent_empty(mask, prefer_x=None, prefer_y=None):
        """Find empty cells adjacent to mask cells, closest to prefer point."""
        ys, xs = np.where(mask)
        if len(xs) == 0:
            return None
        candidates = []
        for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
            nxs = xs + dx
            nys = ys + dy
            valid = (nxs >= 0) & (nxs < WORLD_W) & (nys >= 0) & (nys < WORLD_H)
            nxs, nys = nxs[valid], nys[valid]
            em = empty_mask[nys, nxs]
            for x, y in zip(nxs[em], nys[em]):
                candidates.append((x, y))
        if not candidates:
            return None
        if prefer_x is None:
            prefer_x, prefer_y = WORLD_W // 2, WORLD_H // 2
        candidates = list(set(candidates))
        candidates.sort(key=lambda p: abs(p[0]-prefer_x) + abs(p[1]-prefer_y))
        return candidates[0]

    # Helper: cells with wire or plant (powered grid)
    def power_mask():
        return wire_mask | plant_mask

    # Helper: count neighbors of type in mask
    def has_neighbor(mask, x, y):
        for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
            nx, ny = x+dx, y+dy
            if inbounds(nx, ny) and mask[ny, nx]:
                return True
        return False

    step = obs.step

    # Target area: build around center
    cx, cy = 60, 50

    # Check current map state
    pm = power_mask()
    rm = road_mask
    zm = res_mask | com_mask | ind_mask

    n_plants = np.sum(plant_mask)
    n_wires = np.sum(wire_mask)
    n_roads = np.sum(rm)
    n_zones = np.sum(zm)

    # Phase 0: We need a power plant
    if n_plants == 0:
        # Place coal plant at fixed spot
        return (Tool.COALPOWER, 20, 50)

    # Phase 1: If not enough wire, extend wire toward cx,cy
    # Wire should form a path from plant toward city center
    if n_plants > 0 and n_wires < 60:
        # Find where wire/plant exists, extend toward center
        pos = find_adjacent_empty(pm, cx, cy)
        if pos is not None:
            x, y = pos
            # Only wire if not already a road or zone
            if empty_mask[y, x]:
                return (Tool.WIRE, x, y)

    # Phase 2: Roads - place roads adjacent to wire, extending network
    # We want a road grid: horizontal road at y=50, vertical roads at intervals
    # But do it reactively: place road adjacent to existing roads toward target

    # Find target road positions based on current state
    # Horizontal spine at y=50, from x=25 to x=95
    # Vertical roads every 8 columns

    # Check if we need horizontal spine road
    spine_y = 50
    for x in range(25, 96):
        if inbounds(x, spine_y) and empty_mask[spine_y, x]:
            # Check if adjacent to existing road or wire
            if has_neighbor(rm | pm, x, spine_y):
                return (Tool.ROAD, x, spine_y)

    # Vertical roads every 8 columns
    for vx in [32, 40, 48, 56, 64, 72, 80, 88]:
        for y in range(38, 63):
            if inbounds(vx, y) and empty_mask[vx, y]:
                if has_neighbor(rm | pm, vx, y):
                    return (Tool.ROAD, vx, y)

    # Phase 3: Wire - extend from plant to connect to road areas
    # Wire along spine_y from plant to road start
    for x in range(20, 26):
        if inbounds(x, spine_y) and empty_mask[spine_y, x]:
            if has_neighbor(pm, x, spine_y):
                return (Tool.WIRE, x, spine_y)

    # Wire vertical spines adjacent to road spines (for power to zones)
    for vx in [33, 41, 49, 57, 65, 73, 81, 89]:
        for y in range(38, 63):
            if inbounds(vx, y) and empty_mask[vx, y]:
                if has_neighbor(pm, vx, y):
                    return (Tool.WIRE, vx, y)

    # Phase 4: Place zones reactively
    # A zone needs: road access AND power nearby
    # Scan for good zone spots: empty 3x3 area adjacent to road with wire nearby

    # Determine zone type based on what we need
    r_pop = obs.res_pop
    c_pop = obs.com_pop  
    i_pop = obs.ind_pop

    # We want roughly 3R:1C:1I ratio
    total = r_pop + c_pop + i_pop + 1
    if c_pop / total < 0.15:
        preferred_zone = Tool.COMMERCIAL
    elif i_pop / total < 0.15:
        preferred_zone = Tool.INDUSTRIAL
    else:
        preferred_zone = Tool.RESIDENTIAL

    # Find a good spot for a zone
    # Look for empty cells adjacent to roads that also have wire nearby
    ry_arr, rx_arr = np.where(rm)

    best_zone_pos = None
    best_score = 9999

    # Sample road cells and look for adjacent zone spots
    if len(rx_arr) > 0:
        # Check positions adjacent to roads
        checked = set()
        for i in range(min(len(rx_arr), 200)):
            idx = i * (len(rx_arr) // min(len(rx_arr), 200))
            road_x, road_y = int(rx_arr[idx]), int(ry_arr[idx])

            for dx, dy in [(-2,0),(2,0),(0,-2),(0,2),(-2,-2),(2,2),(-2,2),(2,-2)]:
                zx, zy = road_x + dx, road_y + dy
                if not inbounds(zx, zy):
                    continue
                if (zx, zy) in checked:
                    continue
                checked.add((zx, zy))

                # Check 3x3 area is mostly empty (zone center)
                if not empty_mask[zy, zx]:
                    continue

                # Check has power nearby (within 3 cells)
                has_power = False
                for px in range(max(0,zx-3), min(WORLD_W,zx+4)):
                    for py in range(max(0,zy-3), min(WORLD_H,zy+4)):
                        if pm[py, px]:
                            has_power = True
                            break
                    if has_power:
                        break

                if not has_power:
                    continue

                # Score by distance from center
                score = abs(zx - cx) + abs(zy - cy)
                if score < best_score:
                    best_score = score
                    best_zone_pos = (zx, zy)

    if best_zone_pos is not None:
        x, y = best_zone_pos
        return (preferred_zone, x, y)

    # Phase 5: Add more infrastructure if zones aren't growing
    # Place second power plant if needed
    if n_plants < 2 and obs.powered_zones < 5 and n_zones > 5:
        return (Tool.COALPOWER, 95, 50)

    # Place fire station for happiness
    if 'fire_placed' not in state and n_zones > 10:
        state['fire_placed'] = True
        return (Tool.FIRESTATION, cx, cy - 15)

    if 'police_placed' not in state and n_zones > 15:
        state['police_placed'] = True
        return (Tool.POLICESTATION, cx, cy + 15)

    # Extend wire if zones not powered
    if obs.powered_zones < n_zones * 0.5:
        pos = find_adjacent_empty(pm, cx, cy)
        if pos is not None:
            x, y = pos
            if empty_mask[y, x]:
                return (Tool.WIRE, x, y)

    # Add more roads to improve connectivity
    for vx in [36, 44, 52, 60, 68, 76, 84]:
        for y in range(35, 66):
            if inbounds(vx, y) and empty_mask[vx, y]:
                if has_neighbor(rm, vx, y):
                    return (Tool.ROAD, vx, y)

    # Add more zones further out
    for dist in range(5, 25, 3):
        for angle_idx in range(8):
            dx = int(dist * math.cos(angle_idx * math.pi / 4))
            dy = int(dist * math.sin(angle_idx * math.pi / 4))
            zx, zy = cx + dx, cy + dy
            if inbounds(zx, zy) and empty_mask[zy, zx]:
                if has_neighbor(rm, zx, zy):
                    return (preferred_zone, zx, zy)

    return None

def act(obs, state):
    """
    Hybrid policy combining best of Parent A and Parent B:
    - Reactive closed-loop reading tile_map each step
    - Coal power plant near center-left
    - Vertical wire spine adjacent to plant
    - Road column adjacent to wire (like B: tight spacing)
    - Zones on both sides with proper typing
    - Lateral wires to left zones, lateral roads to right zones
    - Dynamic spine expansion based on population (like A)
    - Second power plant and expansion columns for large cities (like A)
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = 60, 50

    # Phase 1: place coal plant if none
    plant_cx, plant_cy = cx - 6, cy
    if not np.any(pm):
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Find plant centroid
    plant_rows, plant_cols = np.where(pm)
    actual_pcx = int(np.mean(plant_cols))
    actual_pcy = int(np.mean(plant_rows))

    # Wire spine column just right of plant, road column adjacent
    wire_col = actual_pcx + 3
    road_col = wire_col + 1
    left_zone_col = wire_col - 3
    right_zone_col = road_col + 3

    # Clamp columns
    wire_col = max(2, min(WORLD_W - 3, wire_col))
    road_col = max(2, min(WORLD_W - 3, road_col))
    left_zone_col = max(3, min(WORLD_W - 4, left_zone_col))
    right_zone_col = max(3, min(WORLD_W - 4, right_zone_col))

    pop = obs.city_pop

    # Dynamic spine span based on population
    base_span = 8
    extra_span = min(30, pop // 40)
    target_span = base_span + extra_span
    tmin = max(1, cy - target_span)
    tmax = min(WORLD_H - 2, cy + target_span)

    # Zone counts for tool selection
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool(zr, zc):
        if total_zones == 0:
            return Tool.RESIDENTIAL
        # Aim for ~50% res, 25% com, 25% ind
        if com_count * 4 < total_zones:
            return Tool.COMMERCIAL
        if ind_count * 4 < total_zones:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Phase 2: wire spine initialization and extension
    wire_rows_in_col = sorted(r for r in range(WORLD_H) if wm[r, wire_col])

    if not wire_rows_in_col:
        # First wire adjacent to plant
        for dy in range(-1, 3):
            nr = actual_pcy + dy
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        return None

    min_wr = min(wire_rows_in_col)
    max_wr = max(wire_rows_in_col)

    # Extend downward
    if max_wr < tmax:
        nr = max_wr + 1
        if 0 <= nr < WORLD_H and not pm[nr, wire_col] and (em[nr, wire_col] or wm[nr, wire_col]):
            return (Tool.WIRE, wire_col, nr)

    # Extend upward
    if min_wr > tmin:
        nr = min_wr - 1
        if 0 <= nr < WORLD_H and not pm[nr, wire_col] and (em[nr, wire_col] or wm[nr, wire_col]):
            return (Tool.WIRE, wire_col, nr)

    # Phase 3: build road column adjacent to wire spine
    road_rows_set = set(r for r in range(WORLD_H) if rm[r, road_col])
    wire_rows_set = set(wire_rows_in_col)

    for wr in wire_rows_in_col:
        if tmin <= wr <= tmax and wr not in road_rows_set:
            if 0 <= road_col < WORLD_W and em[wr, road_col]:
                return (Tool.ROAD, road_col, wr)

    # Phase 4: place zones adjacent to road/wire
    all_zone_mask = resm | comm | indm

    def zone_area_free(zr, zc):
        """Check if 3x3 area centered at (zr,zc) is empty."""
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def zone_nearby(zr, zc):
        """Check if any zone center is within 1 tile."""
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    # Place zones where wire and road coverage exists
    for zr in wire_rows_in_col:
        if not (tmin <= zr <= tmax):
            continue
        road_nearby = any(abs(zr - rr) <= 2 for rr in road_rows_set)
        wire_near = True  # wire_rows_in_col already is on wire col

        if not (road_nearby and wire_near):
            continue

        for zc in [left_zone_col, right_zone_col]:
            if 1 <= zr <= WORLD_H - 2 and 1 <= zc <= WORLD_W - 2:
                if not zone_nearby(zr, zc) and zone_area_free(zr, zc):
                    return (pick_tool(zr, zc), zc, zr)

    # Phase 5: lateral wires from spine to left zones
    for wr in wire_rows_in_col:
        if not (tmin <= wr <= tmax):
            continue
        # Check if wire already reaches left_zone_col area
        target_wc = left_zone_col + 1
        already_wired = any(wm[wr, wc] for wc in range(max(0, wire_col - 1), max(0, target_wc - 1), -1) if wc < WORLD_W)
        if not already_wired:
            for wc in range(wire_col - 1, max(0, left_zone_col - 1), -1):
                if 0 <= wc < WORLD_W:
                    if wm[wr, wc]:
                        break
                    if em[wr, wc] and not pm[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    elif not em[wr, wc] and not wm[wr, wc]:
                        break

    # Phase 6: lateral roads from road column to right zones
    for wr in wire_rows_in_col:
        if not (tmin <= wr <= tmax):
            continue
        for rc in range(road_col + 1, right_zone_col):
            if 0 <= rc < WORLD_W:
                if rm[wr, rc]:
                    break
                if em[wr, rc] and not pm[wr, rc]:
                    return (Tool.ROAD, rc, wr)
                elif not em[wr, rc]:
                    break

    # Phase 7: second coal plant if population > 300
    num_plant_tiles = int(np.sum(pm))
    if pop > 300 and num_plant_tiles < 9:
        px2 = actual_pcx + 16
        py2 = actual_pcy
        px2 = max(2, min(WORLD_W - 3, px2))
        py2 = max(2, min(WORLD_H - 3, py2))
        area_ok = True
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = py2 + dr, px2 + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    area_ok = False
                elif not em[rr, rc] and not pm[rr, rc]:
                    area_ok = False
        if area_ok:
            return (Tool.COALPOWER, px2, py2)

    # Phase 8: second road column further right for large cities
    if pop > 300:
        road_col2 = road_col + 7
        right_zone_col2 = road_col2 + 3
        road_col2 = max(2, min(WORLD_W - 3, road_col2))
        right_zone_col2 = max(3, min(WORLD_W - 4, right_zone_col2))

        # Extend wire to road_col2
        for wr in wire_rows_in_col:
            if not (tmin <= wr <= tmax):
                continue
            for wc in range(wire_col + 1, road_col2):
                if 0 <= wc < WORLD_W:
                    if wm[wr, wc]:
                        break
                    if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    elif not em[wr, wc] and not rm[wr, wc]:
                        break

        # Build road_col2
        road2_rows_set = set(r for r in range(WORLD_H) if rm[r, road_col2])
        for wr in wire_rows_in_col:
            if tmin <= wr <= tmax and wr not in road2_rows_set:
                if 0 <= road_col2 < WORLD_W and em[wr, road_col2]:
                    return (Tool.ROAD, road_col2, wr)

        # Zones at right_zone_col2
        for zr in wire_rows_in_col:
            if not (tmin <= zr <= tmax):
                continue
            road_nearby2 = any(abs(zr - rr) <= 2 for rr in road2_rows_set)
            if road_nearby2:
                for zc in [right_zone_col2]:
                    if 1 <= zr <= WORLD_H - 2 and 1 <= zc <= WORLD_W - 2:
                        if not zone_nearby(zr, zc) and zone_area_free(zr, zc):
                            return (Tool.RESIDENTIAL, zc, zr)

    # Phase 9: expand outer zone columns for large pop
    if pop > 200:
        outer_left = left_zone_col - 4
        outer_left = max(3, outer_left)
        for zr in wire_rows_in_col:
            if not (tmin <= zr <= tmax):
                continue
            # wire near enough?
            wn = any(abs(zr - wr) <= 3 for wr in wire_rows_in_col)
            rn = any(abs(zr - rr) <= 3 for rr in road_rows_set)
            if wn and rn and 1 <= zr <= WORLD_H - 2 and 1 <= outer_left <= WORLD_W - 2:
                if not zone_nearby(zr, outer_left) and zone_area_free(zr, outer_left):
                    return (Tool.RESIDENTIAL, outer_left, zr)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder combining best of both parents.
    Reads tile_map each step to decide next action based on current state.

    Strategy:
    1. Place coal plant near center
    2. Grow wire spine vertically from plant
    3. Grow roads flanking the wire spine
    4. Place zones (balanced R/C/I) adjacent to roads + power
    5. Expand horizontally when population grows
    6. Add services when warranted
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    cx, cy = 60, 50  # center anchor

    # ---- Phase 1: Place coal plant ----
    if not np.any(pm):
        return (Tool.COALPOWER, cx, cy)

    # Find plant center
    pys, pxs = np.where(pm)
    pcx, pcy = int(pxs[len(pxs)//2]), int(pys[len(pys)//2])

    # Wire spine column (just right of plant)
    wire_col = pcx + 4
    # Road columns flanking wire spine
    road_col_r = wire_col + 2
    road_col_l = wire_col - 2

    # Dynamic vertical span based on population
    pop = obs.city_pop
    half_span = min(22, 8 + pop // 50)
    tmin = max(2, cy - half_span)
    tmax = min(WORLD_H - 3, cy + half_span)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_zone_tool():
        r_frac = res_count / total_zones
        c_frac = com_count / total_zones
        i_frac = ind_count / total_zones
        if i_frac < 0.22:
            return Tool.INDUSTRIAL
        if c_frac < 0.22:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- Phase 2: Grow wire spine vertically ----
    power_map = pm | wm
    wire_rows = sorted(r for r in range(WORLD_H) if wm[r, wire_col])

    def try_wire_spine():
        # If no wire near plant yet, seed it
        if not wire_rows:
            for try_r in [pcy, pcy-1, pcy+1, pcy-2, pcy+2]:
                if in_bounds(wire_col, try_r) and em[try_r, wire_col]:
                    # Check adjacent to plant
                    for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
                        nx, ny = wire_col+ddx, try_r+ddy
                        if in_bounds(nx, ny) and pm[ny, nx]:
                            return (Tool.WIRE, wire_col, try_r)
            # Or just adjacent to any power
            for try_r in [pcy, pcy-1, pcy+1]:
                if in_bounds(wire_col, try_r) and em[try_r, wire_col]:
                    return (Tool.WIRE, wire_col, try_r)
            return None

        min_wr = min(wire_rows)
        max_wr = max(wire_rows)

        # Extend downward
        if max_wr < tmax:
            nr = max_wr + 1
            if in_bounds(wire_col, nr) and em[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if min_wr > tmin:
            nr = min_wr - 1
            if in_bounds(wire_col, nr) and em[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)
        return None

    # ---- Phase 3: Grow roads flanking wire spine ----
    road_rows_r = set(r for r in range(WORLD_H) if rm[r, road_col_r])
    road_rows_l = set(r for r in range(WORLD_H) if rm[r, road_col_l])

    def try_road_extension():
        # Seed roads adjacent to plant if none exist
        road_count = int(np.sum(rm))
        if road_count < 3:
            for try_col in [road_col_r, road_col_l]:
                for try_r in [pcy, pcy-1, pcy+1]:
                    if in_bounds(try_col, try_r) and em[try_r, try_col]:
                        return (Tool.ROAD, try_col, try_r)

        # Extend right road column along wire coverage
        for wr in wire_rows:
            if wr not in road_rows_r and in_bounds(road_col_r, wr) and em[wr, road_col_r]:
                return (Tool.ROAD, road_col_r, wr)
        # Extend left road column
        for wr in wire_rows:
            if wr not in road_rows_l and in_bounds(road_col_l, wr) and em[wr, road_col_l]:
                return (Tool.ROAD, road_col_l, wr)
        return None

    # ---- Phase 4: Place zones near roads and power ----
    def zone_area_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                ny, nx = zy+dr, zx+dc
                if not in_bounds(nx, ny):
                    return False
                if not em[ny, nx]:
                    return False
        return True

    def find_zone_placement():
        # Zones go adjacent to roads, powered by wire spine proximity
        zone_cols_r = [road_col_r + 3]
        zone_cols_l = [road_col_l - 3]
        all_zone_cols = zone_cols_l + zone_cols_r

        # Also try slightly wider placements as city grows
        if pop > 150:
            all_zone_cols += [road_col_r + 6, road_col_l - 6]
        if pop > 350:
            all_zone_cols += [road_col_r + 9, road_col_l - 9]

        for zr in wire_rows:
            if zr < 2 or zr >= WORLD_H - 2:
                continue
            # Check road nearby (within 2 tiles vertically or 1 horizontally)
            road_near = (zr in road_rows_r or zr in road_rows_l or
                        (zr-1) in road_rows_r or (zr+1) in road_rows_r or
                        (zr-1) in road_rows_l or (zr+1) in road_rows_l)
            if not road_near:
                continue
            for zc in all_zone_cols:
                if zc < 2 or zc >= WORLD_W - 2:
                    continue
                if zone_area_clear(zc, zr):
                    return (pick_zone_tool(), zc, zr)
        return None

    # ---- Phase 5: Horizontal expansion clusters ----
    def find_expansion():
        if pop < 200:
            return None

        # Right cluster: wire at wire_col+8, road at wire_col+10
        wire_col2 = wire_col + 8
        road_col2 = wire_col2 + 2
        zone_col2 = road_col2 + 3

        # Connect wire horizontally at pcy level
        wire_rows2 = [r for r in range(WORLD_H) if wm[r, wire_col2]]
        if not wire_rows2:
            # Build horizontal bridge
            for wc in range(wire_col + 1, wire_col2 + 1):
                if in_bounds(wc, pcy) and em[pcy, wc]:
                    return (Tool.WIRE, wc, pcy)
        else:
            # Extend spine2
            min_wr2, max_wr2 = min(wire_rows2), max(wire_rows2)
            if max_wr2 < tmax and in_bounds(wire_col2, max_wr2+1) and em[max_wr2+1, wire_col2]:
                return (Tool.WIRE, wire_col2, max_wr2+1)
            if min_wr2 > tmin and in_bounds(wire_col2, min_wr2-1) and em[min_wr2-1, wire_col2]:
                return (Tool.WIRE, wire_col2, min_wr2-1)

            road_rows2 = set(r for r in range(WORLD_H) if rm[r, road_col2])
            for wr in wire_rows2:
                if wr not in road_rows2 and in_bounds(road_col2, wr) and em[wr, road_col2]:
                    return (Tool.ROAD, road_col2, wr)
            for zr in wire_rows2:
                if zr < 2 or zr >= WORLD_H - 2 or zc2 < 2 if (zc2 := zone_col2) else False:
                    continue
                road_near2 = (zr in road_rows2 or (zr-1) in road_rows2 or (zr+1) in road_rows2)
                if road_near2 and in_bounds(zone_col2, zr) and zone_area_clear(zone_col2, zr):
                    return (pick_zone_tool(), zone_col2, zr)

        # Left cluster when pop > 400
        if pop < 400:
            return None
        wire_col3 = wire_col - 8
        road_col3 = wire_col3 - 2
        zone_col3 = road_col3 - 3

        wire_rows3 = [r for r in range(WORLD_H) if wm[r, wire_col3]]
        if not wire_rows3:
            for wc in range(wire_col - 1, wire_col3 - 1, -1):
                if in_bounds(wc, pcy) and em[pcy, wc]:
                    return (Tool.WIRE, wc, pcy)
        else:
            min_wr3, max_wr3 = min(wire_rows3), max(wire_rows3)
            if max_wr3 < tmax and in_bounds(wire_col3, max_wr3+1) and em[max_wr3+1, wire_col3]:
                return (Tool.WIRE, wire_col3, max_wr3+1)
            if min_wr3 > tmin and in_bounds(wire_col3, min_wr3-1) and em[min_wr3-1, wire_col3]:
                return (Tool.WIRE, wire_col3, min_wr3-1)

            road_rows3 = set(r for r in range(WORLD_H) if rm[r, road_col3])
            for wr in wire_rows3:
                if wr not in road_rows3 and in_bounds(road_col3, wr) and em[wr, road_col3]:
                    return (Tool.ROAD, road_col3, wr)
            for zr in wire_rows3:
                road_near3 = (zr in road_rows3 or (zr-1) in road_rows3 or (zr+1) in road_rows3)
                if road_near3 and in_bounds(zone_col3, zr) and zone_area_clear(zone_col3, zr):
                    return (pick_zone_tool(), zone_col3, zr)
        return None

    # ---- Decision logic ----
    wire_spine_count = len(wire_rows)
    road_count = int(np.sum(rm))

    # Ensure wire spine is built first
    if wire_spine_count < 8:
        wa = try_wire_spine()
        if wa:
            return wa

    # Seed roads early
    if road_count < 4:
        ra = try_road_extension()
        if ra:
            return ra

    # Interleave using step parity
    step_mod = obs.step % 7

    if step_mod in (0, 1):
        wa = try_wire_spine()
        if wa:
            return wa

    if step_mod in (2, 3):
        ra = try_road_extension()
        if ra:
            return ra

    if step_mod in (4, 5, 6):
        za = find_zone_placement()
        if za:
            return za

    # Try expansion
    ea = find_expansion()
    if ea:
        return ea

    # Fallbacks: wire, road, zone
    wa = try_wire_spine()
    if wa:
        return wa
    ra = try_road_extension()
    if ra:
        return ra
    za = find_zone_placement()
    if za:
        return za

    # Services
    if pop > 300:
        for fx, fy in [(cx+8, cy-12), (cx-8, cy+12)]:
            if in_bounds(fx, fy) and em[fy, fx]:
                return (Tool.FIRESTATION, fx, fy)
    if pop > 600:
        for fx, fy in [(cx+8, cy+12), (cx-8, cy-12)]:
            if in_bounds(fx, fy) and em[fy, fx]:
                return (Tool.POLICESTATION, fx, fy)

    # Last resort: extend any road
    rys, rxs = np.where(rm)
    if len(rxs) > 0:
        k = int(obs.step * 17) % len(rxs)
        ry2, rx2 = int(rys[k]), int(rxs[k])
        for ddx, ddy in [(0,1),(1,0),(0,-1),(-1,0)]:
            nx2, ny2 = rx2+ddx, ry2+ddy
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    New strategy: vertical road spine with zones on both sides,
    power plant at top connected via vertical wire,
    mixed zones (res/com/ind) in a compact cluster.
    Uses state to track placement phase and avoid redundant checks.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    all_zone_mask = resm | comm | indm

    # Use a vertical spine instead of horizontal
    # Center column for the road spine
    road_col = WORLD_W // 2      # col 60 - vertical road spine
    wire_col = road_col - 2      # col 58 - wire spine parallel to road
    wire_col2 = road_col + 2     # col 62 - second wire spine

    # Power plant location: top-left area
    plant_cx = 20
    plant_cy = 15

    # Zone rows: use a band from row 10 to row 85
    zone_start_row = 10
    zone_end_row = 85

    # Zone columns: left cluster and right cluster of the vertical road
    left_zone_cols = [road_col - 5, road_col - 9, road_col - 13]
    right_zone_cols = [road_col + 5, road_col + 9, road_col + 13]

    def zone_area_clear(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_exists_nearby(zr, zc):
        for dr in range(-2, 3):
            for dc in range(-2, 3):
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    def pick_tool(idx):
        # More industrial/commercial to create jobs and demand
        pattern = [Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.INDUSTRIAL,
                   Tool.RESIDENTIAL, Tool.INDUSTRIAL, Tool.COMMERCIAL,
                   Tool.RESIDENTIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.INDUSTRIAL]
        return pattern[idx % len(pattern)]

    # Phase 1: Place coal power plant
    if not np.any(pm):
        return (Tool.COALPOWER, plant_cx, plant_cy)

    plant_rows, plant_cols = np.where(pm)
    plant_cy_actual = int(np.mean(plant_rows))
    plant_cx_actual = int(np.mean(plant_cols))

    # Phase 2: Wire from plant to wire spine (horizontal then vertical)
    # First connect plant to wire_col vertically at plant row
    # Wire from plant right side (plant_cx+2) across to wire_col
    connect_row = plant_cy_actual
    # Horizontal wire from plant to wire_col
    pc_right = plant_cx_actual + 2
    if pc_right < wire_col:
        for c in range(pc_right, wire_col + 1):
            if 0 <= c < WORLD_W and not wm[connect_row, c] and not pm[connect_row, c]:
                if em[connect_row, c]:
                    return (Tool.WIRE, c, connect_row)

    # Vertical wire spine from connect_row downward
    wire_spine_top = connect_row
    wire_spine_bot = zone_end_row + 2
    wire_spine_bot = min(WORLD_H - 1, wire_spine_bot)

    for r in range(wire_spine_top, wire_spine_bot + 1):
        if not wm[r, wire_col] and not pm[r, wire_col] and em[r, wire_col]:
            return (Tool.WIRE, wire_col, r)

    # Also build second wire spine on right side
    # Connect from wire_col horizontally to wire_col2 at several rows
    for r in range(zone_start_row, zone_end_row, 6):
        for c in range(wire_col, wire_col2 + 1):
            if 0 <= c < WORLD_W and not wm[r, c] and not pm[r, c] and em[r, c]:
                return (Tool.WIRE, c, r)

    # Phase 3: Vertical road spine
    for r in range(zone_start_row - 2, zone_end_row + 3):
        if 0 <= r < WORLD_H and not rm[r, road_col] and em[r, road_col] and not pm[r, road_col]:
            return (Tool.ROAD, road_col, r)

    # Phase 4: Horizontal road connectors every 4 rows
    for r in range(zone_start_row, zone_end_row, 4):
        # Connect left zones to spine
        for zc in left_zone_cols:
            for c in range(zc - 1, road_col + 1):
                if 0 <= c < WORLD_W and not rm[r, c] and em[r, c] and not pm[r, c]:
                    if rm[road_col, r] or c == road_col:
                        return (Tool.ROAD, c, r)
        # Connect right zones to spine
        for zc in right_zone_cols:
            for c in range(road_col, zc + 2):
                if 0 <= c < WORLD_W and not rm[r, c] and em[r, c] and not pm[r, c]:
                    if rm[road_col, r] or c == road_col:
                        return (Tool.ROAD, c, r)

    # Phase 5: Place zones
    zone_idx = 0
    zone_rows = list(range(zone_start_row + 1, zone_end_row, 4))

    for zr in zone_rows:
        for zc in left_zone_cols + right_zone_cols:
            if not zone_exists_nearby(zr, zc) and zone_area_clear(zr, zc):
                if has_wire_nearby(zr, zc, 5) and has_road_nearby(zr, zc, 5):
                    return (pick_tool(zone_idx), zc, zr)
            zone_idx += 1

    # Phase 6: Wires from main spine to zones (horizontal connectors)
    for r in range(zone_start_row, zone_end_row, 4):
        if wm[r, wire_col]:
            for c in range(wire_col + 1, road_col):
                if not wm[r, c] and not pm[r, c] and em[r, c]:
                    return (Tool.WIRE, c, r)
            # Also wire rightward
            for c in range(wire_col2, road_col + 10):
                if c >= WORLD_W: break
                if not wm[r, c] and not pm[r, c] and em[r, c]:
                    return (Tool.WIRE, c, r)

    # Phase 7: Second coal plant if needed
    if obs.city_pop > 200 and np.sum(pm) < 9:
        px2 = 90
        py2 = 15
        if em[py2, px2]:
            return (Tool.COALPOWER, px2, py2)
        # Wire from second plant to right zones
        for c in range(px2 - 2, wire_col2 - 1, -1):
            if 0 <= c < WORLD_W and em[py2, c] and not pm[py2, c] and not wm[py2, c]:
                return (Tool.WIRE, c, py2)

    # Phase 8: Fire/police stations
    if obs.city_pop > 300:
        for zc, zr in [(road_col - 3, WORLD_H // 2), (road_col + 3, WORLD_H // 2)]:
            if 1 <= zr <= WORLD_H - 2 and 1 <= zc <= WORLD_W - 2:
                if em[zr, zc]:
                    return (Tool.FIRESTATION, zc, zr)

    if obs.city_pop > 500:
        for zc, zr in [(road_col - 7, WORLD_H // 2 + 5), (road_col + 7, WORLD_H // 2 - 5)]:
            if 1 <= zr <= WORLD_H - 2 and 1 <= zc <= WORLD_W - 2:
                if em[zr, zc]:
                    return (Tool.POLICESTATION, zc, zr)

    # Phase 9: More zones if population is growing - expand outward
    if obs.city_pop > 100:
        extra_cols = [road_col - 17, road_col + 17]
        for zr in zone_rows:
            for zc in extra_cols:
                if not zone_exists_nearby(zr, zc) and zone_area_clear(zr, zc):
                    if has_wire_nearby(zr, zc, 7) and has_road_nearby(zr, zc, 7):
                        return (pick_tool(zone_idx), zc, zr)
                zone_idx += 1

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder - improved variation.

    Key changes from parent:
    1. More aggressive road network (grid-based) for better zone coverage
    2. Wire placement prioritizes reaching zones that lack power
    3. Zone placement checks adjacency to road tiles directly
    4. Better phase management based on actual map state
    5. Build a proper grid: horizontal roads at intervals, vertical roads at intervals
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Build near map center, slightly left to leave room for plant on right
    cx, cy = 55, 50

    # ---- Phase 1: Ensure coal plant exists ----
    plant_ys, plant_xs = np.where(pm)
    has_plant = len(plant_xs) > 0
    if not has_plant:
        # Plant at cx+8, cy (right of city grid)
        return (Tool.COALPOWER, cx + 8, cy)

    # Find plant center
    plant_cx = int(plant_xs.mean())
    plant_cy = int(plant_ys.mean())

    power_map = pm | wm

    # ---- Phase 2: Wire from plant toward city grid ----
    def find_wire_extension():
        # Wire spine: run wire from plant leftward to cx, then up/down
        # Vertical spine at cx, horizontal at cy
        candidates = []

        # Horizontal wire from plant to city center
        step_x = -1 if plant_cx > cx else 1
        for x in range(cx, plant_cx + step_x, step_x):
            candidates.append((x, cy))

        # Vertical spine at cx
        for dy in range(-20, 21):
            candidates.append((cx, cy + dy))

        # Extra horizontal wires at road levels to distribute power
        for row_offset in [-12, -8, -4, 0, 4, 8, 12]:
            for x in range(cx - 12, cx + 13):
                candidates.append((x, cy + row_offset))

        for (wx, wy) in candidates:
            if not in_bounds(wx, wy):
                continue
            if bool(wm[wy, wx]) or bool(pm[wy, wx]):
                continue
            if not bool(em[wy, wx]):
                continue
            # Must be adjacent to existing power
            for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx2, ny2 = wx+ddx, wy+ddy
                if in_bounds(nx2, ny2) and bool(power_map[ny2, nx2]):
                    return (Tool.WIRE, wx, wy)
        return None

    # ---- Phase 3: Road grid ----
    # Build horizontal roads at cy + offsets, vertical roads at cx + offsets
    # Grid spacing: 4 tiles between roads (zones are 3x3, need road adjacent)
    def find_road_extension():
        candidates = []

        # Horizontal roads (rows)
        for row_offset in [-12, -8, -4, 0, 4, 8, 12]:
            ry = cy + row_offset
            for dx in range(-15, 16):
                candidates.append((cx + dx, ry))

        # Vertical roads (columns) 
        for col_offset in [-12, -8, -4, 0, 4, 8, 12]:
            rx = cx + col_offset
            for dy in range(-14, 15):
                candidates.append((rx, cy + dy))

        for (rx, ry) in candidates:
            if not in_bounds(rx, ry):
                continue
            if bool(rm[ry, rx]):
                continue
            if bool(pm[ry, rx]) or bool(wm[ry, rx]):
                continue
            if not bool(em[ry, rx]):
                continue
            # Adjacent to existing road or adjacent to plant
            for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx2, ny2 = rx+ddx, ry+ddy
                if in_bounds(nx2, ny2) and bool(rm[ny2, nx2]):
                    return (Tool.ROAD, rx, ry)
            # Seed road adjacent to plant
            for ddx, ddy in [(2,0),(-2,0),(0,2),(0,-2),(1,0),(-1,0),(0,1),(0,-1)]:
                nx2, ny2 = rx+ddx, ry+ddy
                if in_bounds(nx2, ny2) and bool(pm[ny2, nx2]):
                    return (Tool.ROAD, rx, ry)
        return None

    # Count zones for balance
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        # Target: ~50% R, 25% C, 25% I
        if com_count * 2 < total_zones * 0.45:
            return Tool.COMMERCIAL
        if ind_count * 2 < total_zones * 0.45:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # ---- Phase 4: Place zones in cells between roads ----
    def find_zone_placement():
        # Precompute: tiles adjacent to road (within 1 step)
        nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

        # Power neighborhood (wires and plant within 7 tiles)
        nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-8, 9):
            for dx in range(-8, 9):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                nbr_power[r0:r1, c0:c1] |= power_map[sr0:sr1, sc0:sc1]

        zone_mask = resm | comm | indm
        cand = em & nbr_road & nbr_power
        # Keep away from edges
        cand[:2, :] = False
        cand[WORLD_H-2:, :] = False
        cand[:, :2] = False
        cand[:, WORLD_W-2:] = False
        # Don't place on wire spine
        cand[:, cx] = False

        cys, cxs = np.where(cand)
        if len(cxs) == 0:
            return None

        # Sort candidates by distance to center (prefer dense core)
        dists = np.abs(cxs - cx) + np.abs(cys - cy)
        order = np.argsort(dists)

        tool = pick_tool()
        # Try candidates from closest to center outward
        for i in order[:80]:
            zx, zy = int(cxs[i]), int(cys[i])
            # Check 3x3 clearance
            ok = True
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    ny2, nx2 = zy + dr, zx + dc
                    if not in_bounds(nx2, ny2):
                        ok = False; break
                    cell = tm[ny2, nx2]
                    # Allow empty or same-type zone cells
                    if not (bool(em[ny2, nx2]) or bool(zone_mask[ny2, nx2])):
                        ok = False; break
                if not ok:
                    break
            if ok:
                return (tool, zx, zy)
        return None

    # ---- Decision Logic ----
    wire_count = int(np.sum(wm))
    road_count = int(np.sum(rm))

    # Count wire spine
    spine_filled = sum(1 for dy in range(-20, 21)
                      if in_bounds(cx, cy+dy) and bool(wm[cy+dy, cx]))
    # Count horizontal wire toward plant
    h_wire = sum(1 for x in range(min(cx, plant_cx), max(cx, plant_cx)+1)
                 if in_bounds(x, cy) and bool(wm[cy, x]))

    # Priority 1: Wire to connect plant to city
    if h_wire < abs(plant_cx - cx) and wire_count < 5:
        wact = find_wire_extension()
        if wact is not None:
            return wact

    # Priority 2: Need initial roads
    if road_count < 8:
        ract = find_road_extension()
        if ract is not None:
            return ract

    # Priority 3: Need wire spine
    if spine_filled < 8 and wire_count < 15:
        wact = find_wire_extension()
        if wact is not None:
            return wact

    # Main loop: use step modulo to interleave wire, road, zones
    step_mod = obs.step % 8

    if step_mod in (0, 1):
        wact = find_wire_extension()
        if wact is not None:
            return wact

    if step_mod in (2, 3):
        ract = find_road_extension()
        if ract is not None:
            return ract

    # Try zone placement most of the time
    zact = find_zone_placement()
    if zact is not None:
        return zact

    # Fallbacks
    wact = find_wire_extension()
    if wact is not None:
        return wact

    ract = find_road_extension()
    if ract is not None:
        return ract

    # Services based on population
    if obs.city_pop > 400:
        for fx, fy in [(cx-10, cy-10), (cx+5, cy+10), (cx-5, cy+10)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.FIRESTATION, fx, fy)

    if obs.city_pop > 800:
        for fx, fy in [(cx+10, cy-10), (cx-10, cy+5)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.POLICESTATION, fx, fy)

    # Last resort: extend road from any road tile
    rys, rxs = np.where(rm)
    if len(rxs) > 0:
        k2 = int(obs.step * 17 + int(obs.city_pop)) % len(rxs)
        rx2, ry2 = int(rxs[k2]), int(rys[k2])
        for ddx, ddy in [(0,1),(1,0),(0,-1),(-1,0)]:
            nx2, ny2 = rx2+ddx, ry2+ddy
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Redesigned policy: horizontal road/wire layout instead of vertical.
    - Coal power plant on the left side
    - Horizontal wire spine running right from plant
    - Horizontal road spine 2 rows below wire spine
    - Zones placed above and below the road spine
    - More balanced zone mix (RES/COM/IND)
    - Second power plant if needed
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    # Initialize state
    if 'phase' not in state:
        state['phase'] = 0
        state['build_queue'] = []

    # Central layout parameters
    wire_row = 45  # horizontal wire spine row
    road_row = 48  # horizontal road spine row (3 below wire)
    plant_x, plant_y = 10, 46  # power plant center (between wire and road rows)

    # Extent of wire/road spine
    spine_start = plant_x + 3  # start after plant footprint
    spine_end = 100  # go far right

    has_plant = np.any(pm)

    # Phase 1: Place coal power plant
    if not has_plant:
        return (Tool.COALPOWER, plant_x, plant_y)

    # Find actual plant position
    plant_positions = list(zip(*np.where(pm)))
    if plant_positions:
        pr, pc = plant_positions[0]
        plant_y, plant_x = pr, pc

    # Recalculate layout based on plant position
    wire_row = plant_y - 1
    road_row = plant_y + 2
    spine_start = plant_x + 3

    # Current wire/road extents on spine rows
    wire_row_cols = sorted([c for (r, c) in zip(*np.where(wm)) if r == wire_row])
    road_row_cols = sorted([c for (r, c) in zip(*np.where(rm)) if r == road_row])

    wire_max_col = max(wire_row_cols) if wire_row_cols else spine_start - 1
    road_max_col = max(road_row_cols) if road_row_cols else spine_start - 1

    res_positions = list(zip(*np.where(res_mask(tm))))
    com_positions = list(zip(*np.where(com_mask(tm))))
    ind_positions = list(zip(*np.where(ind_mask(tm))))
    all_zone_pos = res_positions + com_positions + ind_positions

    res_count = len(res_positions)
    com_count = len(com_positions)
    ind_count = len(ind_positions)

    # Phase 2: Extend wire spine horizontally
    target_extent = min(spine_end, spine_start + 70)
    if wire_max_col < target_extent:
        next_c = max(spine_start, wire_max_col + 1)
        if 0 <= next_c < WORLD_W:
            return (Tool.WIRE, next_c, wire_row)

    # Phase 3: Extend road spine horizontally
    if road_max_col < target_extent:
        next_c = max(spine_start, road_max_col + 1)
        if 0 <= next_c < WORLD_W:
            return (Tool.ROAD, next_c, road_row)

    # Phase 4: Connect wire spine to road with vertical wires periodically
    # Every 6 columns, add a vertical wire connector
    for c in range(spine_start, min(wire_max_col, road_max_col) + 1, 6):
        for r in range(wire_row + 1, road_row):
            if 0 <= r < WORLD_H and not wm[r, c]:
                return (Tool.WIRE, c, r)

    def zone_area_clear(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if pm[rr, rc]:
                    return False
        return True

    def zone_exists_near(zr, zc):
        return any(abs(zr - pr) <= 2 and abs(zc - pc) <= 2 for (pr, pc) in all_zone_pos)

    def pick_zone_type():
        total = res_count + com_count + ind_count + 1
        # Target: 50% RES, 30% COM, 20% IND
        if ind_count / total < 0.20:
            return Tool.INDUSTRIAL
        elif com_count / total < 0.30:
            return Tool.COMMERCIAL
        else:
            return Tool.RESIDENTIAL

    # Phase 5: Place zones above wire spine (zone center 3 rows above wire_row)
    zone_row_above = wire_row - 3
    # Place zones below road spine (zone center 3 rows below road_row)
    zone_row_below = road_row + 3

    # Place zones along the spine every 4 columns
    for c in range(spine_start + 1, min(wire_max_col, road_max_col) - 1, 4):
        # Above wire spine
        zr, zc = zone_row_above, c
        if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
            if not zone_exists_near(zr, zc) and zone_area_clear(zr, zc):
                # Need vertical wire from zone to spine
                # Add road access: lateral road from zone to road_row
                return (pick_zone_type(), zc, zr)

        # Below road spine
        zr, zc = zone_row_below, c
        if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
            if not zone_exists_near(zr, zc) and zone_area_clear(zr, zc):
                return (pick_zone_type(), zc, zr)

    # Phase 6: Add vertical wires from above zones to wire spine
    for zr, zc in res_positions + com_positions + ind_positions:
        if zr < wire_row:
            # Connect upward zone to wire spine
            for r in range(zr + 2, wire_row):
                if 0 <= r < WORLD_H and not wm[r, zc]:
                    return (Tool.WIRE, zc, r)
        elif zr > road_row:
            # Connect downward zone to road spine via road
            for r in range(road_row + 1, zr - 1):
                if 0 <= r < WORLD_H and not rm[r, zc]:
                    return (Tool.ROAD, zc, r)

    # Phase 7: Second neighborhood - offset vertically
    if obs.city_pop > 100 or (res_count + com_count + ind_count) > 5:
        wire_row2 = wire_row + 12
        road_row2 = wire_row2 + 3

        wire2_cols = sorted([c for (r, c) in zip(*np.where(wm)) if r == wire_row2])
        road2_cols = sorted([c for (r, c) in zip(*np.where(rm)) if r == road_row2])

        wire2_max = max(wire2_cols) if wire2_cols else spine_start - 1
        road2_max = max(road2_cols) if road2_cols else spine_start - 1

        target2 = min(spine_end, spine_start + 50)

        # Connect second wire spine to plant via vertical wire
        if not wire2_cols:
            # Start second wire spine near plant
            if 0 <= wire_row2 < WORLD_H:
                return (Tool.WIRE, plant_x, wire_row2)

        # Connect second spine to plant (vertical wire)
        for r in range(wire_row + 1, wire_row2):
            if 0 <= r < WORLD_H and not wm[r, plant_x]:
                return (Tool.WIRE, plant_x, r)

        if wire2_max < target2:
            next_c = max(spine_start, wire2_max + 1)
            if 0 <= next_c < WORLD_W:
                return (Tool.WIRE, next_c, wire_row2)

        if road2_max < target2:
            next_c = max(spine_start, road2_max + 1)
            if 0 <= next_c < WORLD_W:
                return (Tool.ROAD, next_c, road_row2)

        # Zones between second wire and road spines
        zone_row2_above = wire_row2 - 3
        zone_row2_below = road_row2 + 3

        for c in range(spine_start + 1, min(wire2_max, road2_max) - 1, 4):
            zr, zc = zone_row2_above, c
            if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                if not zone_exists_near(zr, zc) and zone_area_clear(zr, zc):
                    return (pick_zone_type(), zc, zr)

            zr, zc = zone_row2_below, c
            if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                if not zone_exists_near(zr, zc) and zone_area_clear(zr, zc):
                    return (pick_zone_type(), zc, zr)

    # Phase 8: Second power plant if growing
    if obs.city_pop > 300:
        plant2_x = 60
        plant2_y = plant_y
        if not np.any(pm[plant2_y-1:plant2_y+2, plant2_x-1:plant2_x+2]):
            return (Tool.COALPOWER, plant2_x, plant2_y)

    # Phase 9: Add stadium for demand boost
    if obs.city_pop > 500:
        stad_x, stad_y = 80, plant_y
        if not np.any(pm[stad_y-1:stad_y+2, stad_x-1:stad_x+2]):
            if not any(abs(stad_y - pr) <= 2 and abs(stad_x - pc) <= 2 for (pr, pc) in all_zone_pos):
                return (Tool.STADIUM, stad_x, stad_y)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map every step to decide next action.
    Strategy: build a compact grid with alternating road/wire columns and
    zone columns, extending outward from power plant as infrastructure grows.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    all_zone_mask = resm | comm | indm

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return bool(np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1]))

    def has_road_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return bool(np.any(rm[r0:r1, c0:c1]))

    # Step 1: Place coal power plant if none exists
    if not np.any(pm):
        return (Tool.COALPOWER, cx - 6, cy)

    # Find plant center
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Layout: wire spine at plant_cx+4, road at wire_col+2
    # zones left at wire_col-3, right at road_col+3
    wire_col = plant_cx + 4
    road_col = wire_col + 2
    left_zone_col = wire_col - 3
    right_zone_col = road_col + 3

    wire_col = max(2, min(WORLD_W - 3, wire_col))
    road_col = max(2, min(WORLD_W - 3, road_col))
    left_zone_col = max(2, min(WORLD_W - 3, left_zone_col))
    right_zone_col = max(2, min(WORLD_W - 3, right_zone_col))

    # Dynamic spine: grow based on what's already built and current pop
    if obs.city_pop < 50:
        spine_extent = 8
    elif obs.city_pop < 150:
        spine_extent = 14
    elif obs.city_pop < 350:
        spine_extent = 20
    else:
        spine_extent = 28

    target_min = max(1, cy - spine_extent)
    target_max = min(WORLD_H - 2, cy + spine_extent)

    # Read current wire spine state
    wire_rows_on_spine = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])
    road_rows_on_col = sorted([r for r in range(WORLD_H) if rm[r, road_col]])
    road_rows_set = set(road_rows_on_col)

    # Phase 2: Seed wire adjacent to plant if spine empty
    if not wire_rows_on_spine:
        for dy in range(0, 8):
            for nr in [plant_cy + dy, plant_cy - dy]:
                if 0 <= nr < WORLD_H:
                    if em[nr, wire_col] or wm[nr, wire_col]:
                        return (Tool.WIRE, wire_col, nr)
        return None

    min_wire_row = min(wire_rows_on_spine)
    max_wire_row = max(wire_rows_on_spine)

    # Phase 3: Extend wire spine - prioritize downward then upward
    if max_wire_row < target_max:
        nr = max_wire_row + 1
        if nr < WORLD_H and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    if min_wire_row > target_min:
        nr = min_wire_row - 1
        if nr >= 0 and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Phase 4: Build road column - scan wire rows, place road where missing
    for r in wire_rows_on_spine:
        if 0 <= r < WORLD_H and 0 <= road_col < WORLD_W:
            if not rm[r, road_col] and (em[r, road_col] or rm[r, road_col]):
                return (Tool.ROAD, road_col, r)

    # Phase 5: Place zones - scan zone rows along spine
    zone_rows = list(range(max(1, target_min), min(WORLD_H - 1, target_max + 1), 3))

    for zr in zone_rows:
        wire_near = any(abs(zr - wr) <= 2 for wr in wire_rows_on_spine)
        road_near = any(abs(zr - rr) <= 2 for rr in road_rows_on_col)

        if wire_near and road_near:
            # Try left zone first
            zc = left_zone_col
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc, 5) and has_road_nearby(zr, zc, 5):
                    return (pick_tool(), zc, zr)

            # Try right zone
            zc = right_zone_col
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_road_nearby(zr, zc, 5) and has_wire_nearby(zr, zc, 6):
                    return (pick_tool(), zc, zr)

    # Phase 6: Lateral wires from spine toward left zones
    for wr in wire_rows_on_spine:
        for wc in range(wire_col - 1, max(left_zone_col - 2, 0), -1):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc]:
                    break

    # Phase 7: Road extensions toward right zones
    for rr in wire_rows_on_spine:
        if not rm[rr, road_col]:
            continue
        for rc in range(road_col + 1, right_zone_col + 2):
            if 0 <= rc < WORLD_W:
                if rm[rr, rc]:
                    break
                if em[rr, rc] and not pm[rr, rc]:
                    return (Tool.ROAD, rc, rr)
                elif not em[rr, rc]:
                    break

    # Phase 8: Wire extensions toward right zones for power
    for wr in wire_rows_on_spine:
        for wc in range(wire_col + 1, right_zone_col + 2):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc] and not rm[wr, wc]:
                    break

    # Phase 9: Second power plant when population warrants it
    # Check by reading tile_map: count plant tiles
    plant_tile_count = int(np.sum(pm))
    if obs.city_pop > 250 and plant_tile_count < 9:
        px2 = plant_cx + 18
        py2 = plant_cy
        if 2 <= py2 <= WORLD_H - 3 and 2 <= px2 <= WORLD_W - 3:
            area_clear = True
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    rr, rc = py2 + dr, px2 + dc
                    if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                        if not (em[rr, rc] or pm[rr, rc]):
                            area_clear = False
            if area_clear:
                return (Tool.COALPOWER, px2, py2)

    # Phase 10: Second cluster to the right - build reactively
    if obs.city_pop >= 150:
        wire_col2 = road_col + 7
        road_col2 = wire_col2 + 2
        left_zone_col2 = wire_col2 - 3
        right_zone_col2 = road_col2 + 3

        wire_col2 = max(2, min(WORLD_W - 3, wire_col2))
        road_col2 = max(2, min(WORLD_W - 3, road_col2))
        left_zone_col2 = max(2, min(WORLD_W - 3, left_zone_col2))
        right_zone_col2 = max(2, min(WORLD_W - 3, right_zone_col2))

        wire_rows2 = sorted([r for r in range(WORLD_H) if wm[r, wire_col2]])
        road_rows2 = set(r for r in range(WORLD_H) if rm[r, road_col2])

        if not wire_rows2:
            # Bridge wire from main spine to cluster2 at plant_cy row
            for wc in range(wire_col + 1, wire_col2 + 1):
                if 0 <= wc < WORLD_W:
                    if wm[plant_cy, wc]:
                        continue
                    if em[plant_cy, wc] and not pm[plant_cy, wc]:
                        return (Tool.WIRE, wc, plant_cy)
                    elif not em[plant_cy, wc] and not wm[plant_cy, wc]:
                        break
        else:
            min_wr2 = min(wire_rows2)
            max_wr2 = max(wire_rows2)

            if max_wr2 < target_max:
                nr = max_wr2 + 1
                if nr < WORLD_H and em[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > target_min:
                nr = min_wr2 - 1
                if nr >= 0 and em[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)

            for wr in wire_rows2:
                if wr not in road_rows2 and em[wr, road_col2]:
                    return (Tool.ROAD, road_col2, wr)

            for zr in zone_rows:
                wire_near2 = any(abs(zr - wr) <= 2 for wr in wire_rows2)
                road_near2 = any(abs(zr - rr) <= 2 for rr in road_rows2)
                if wire_near2 and road_near2:
                    for zc in [left_zone_col2, right_zone_col2]:
                        if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                            if has_wire_nearby(zr, zc, 6) and has_road_nearby(zr, zc, 5):
                                return (pick_tool(), zc, zr)

            # Lateral wires for cluster2
            for wr in wire_rows2:
                for wc in range(wire_col2 - 1, max(left_zone_col2 - 2, 0), -1):
                    if 0 <= wc < WORLD_W:
                        if wm[wr, wc]: break
                        if em[wr, wc] and not pm[wr, wc]:
                            return (Tool.WIRE, wc, wr)
                        elif not em[wr, wc]: break

            for wr in wire_rows2:
                if not rm[wr, road_col2]: continue
                for rc in range(road_col2 + 1, right_zone_col2 + 2):
                    if 0 <= rc < WORLD_W:
                        if rm[wr, rc]: break
                        if em[wr, rc] and not pm[wr, rc]:
                            return (Tool.ROAD, rc, wr)
                        elif not em[wr, rc]: break

    # Phase 11: Left cluster when pop >= 300
    if obs.city_pop >= 300:
        wire_col3 = wire_col - 9
        road_col3 = wire_col3 - 2
        left_zone_col3 = road_col3 - 3
        right_zone_col3 = wire_col3 + 3

        wire_col3 = max(2, min(WORLD_W - 3, wire_col3))
        road_col3 = max(2, min(WORLD_W - 3, road_col3))
        left_zone_col3 = max(2, min(WORLD_W - 3, left_zone_col3))
        right_zone_col3 = max(2, min(WORLD_W - 3, right_zone_col3))

        wire_rows3 = sorted([r for r in range(WORLD_H) if wm[r, wire_col3]])
        road_rows3 = set(r for r in range(WORLD_H) if rm[r, road_col3])

        if not wire_rows3:
            for wc in range(wire_col - 1, wire_col3 - 1, -1):
                if 0 <= wc < WORLD_W:
                    if wm[plant_cy, wc]: continue
                    if em[plant_cy, wc] and not pm[plant_cy, wc]:
                        return (Tool.WIRE, wc, plant_cy)
                    elif not em[plant_cy, wc] and not wm[plant_cy, wc]:
                        break
        else:
            min_wr3 = min(wire_rows3)
            max_wr3 = max(wire_rows3)

            if max_wr3 < target_max:
                nr = max_wr3 + 1
                if nr < WORLD_H and em[nr, wire_col3]:
                    return (Tool.WIRE, wire_col3, nr)
            if min_wr3 > target_min:
                nr = min_wr3 - 1
                if nr >= 0 and em[nr, wire_col3]:
                    return (Tool.WIRE, wire_col3, nr)

            for wr in wire_rows3:
                if wr not in road_rows3 and em[wr, road_col3]:
                    return (Tool.ROAD, road_col3, wr)

            for zr in zone_rows:
                wire_near3 = any(abs(zr - wr) <= 2 for wr in wire_rows3)
                road_near3 = any(abs(zr - rr) <= 2 for rr in road_rows3)
                if wire_near3 and road_near3:
                    for zc in [right_zone_col3, left_zone_col3]:
                        if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                            if has_wire_nearby(zr, zc, 6) and has_road_nearby(zr, zc, 5):
                                return (pick_tool(), zc, zr)

            for wr in wire_rows3:
                for wc in range(wire_col3 + 1, min(right_zone_col3 + 2, WORLD_W)):
                    if 0 <= wc < WORLD_W:
                        if wm[wr, wc]: break
                        if em[wr, wc] and not pm[wr, wc]:
                            return (Tool.WIRE, wc, wr)
                        elif not em[wr, wc]: break

            for wr in wire_rows3:
                if not rm[wr, road_col3]: continue
                for rc in range(road_col3 - 1, max(left_zone_col3 - 2, 0), -1):
                    if 0 <= rc < WORLD_W:
                        if rm[wr, rc]: break
                        if em[wr, rc] and not pm[wr, rc]:
                            return (Tool.ROAD, rc, wr)
                        elif not em[wr, rc]: break

    # Phase 12: Fill any powered+roaded zone gaps reactively
    # Scan entire spine area for valid zone placements
    if obs.city_pop > 100:
        for zr in zone_rows:
            for zc in [left_zone_col - 4, right_zone_col + 4]:
                if 2 <= zc <= WORLD_W - 3:
                    if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                        if has_wire_nearby(zr, zc, 7) and has_road_nearby(zr, zc, 6):
                            return (pick_tool(), zc, zr)

    return None

def act(obs, state):
    """
    Hybrid policy combining Parent A's structured spine approach with
    Parent B's reactive placement scoring.

    Strategy:
    1. Place coal plant at fixed location
    2. Build vertical wire spine from plant (like Parent A)
    3. Build road column adjacent to wire (like Parent A)
    4. Place zones on both sides with proper spacing
    5. Expand to multiple clusters as population grows
    6. Use lateral wires to connect left zones to power
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # Fixed anchor
    plant_cx, plant_cy = 58, 50

    # Wire spine slightly right of plant, road next to it
    wire_col = plant_cx + 4   # col 62
    road_col = wire_col + 2   # col 64

    # Zone columns on each side
    left_zone_col  = wire_col - 4   # col 58 (but plant is at 58 so use 55)
    left_zone_col  = wire_col - 5   # col 57
    right_zone_col = road_col + 4   # col 68

    has_plant = np.any(pm)

    # Phase 1: Place coal power plant
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Gather masks
    wire_positions = set(zip(*np.where(wm))) if np.any(wm) else set()
    road_positions = set(zip(*np.where(rm))) if np.any(rm) else set()
    res_positions  = set(zip(*np.where(res_m))) if np.any(res_m) else set()
    com_positions  = set(zip(*np.where(com_m))) if np.any(com_m) else set()
    ind_positions  = set(zip(*np.where(ind_m))) if np.any(ind_m) else set()
    all_zones = res_positions | com_positions | ind_positions

    res_count = len(res_positions)
    com_count = len(com_positions)
    ind_count = len(ind_positions)

    # Dynamic span based on pop
    cy = plant_cy
    base_span = 12
    extra_span = min(30, obs.city_pop // 30)
    target_span = base_span + extra_span
    tmin = max(3, cy - target_span)
    tmax = min(WORLD_H - 4, cy + target_span)

    wire_rows_in_col = sorted(r for (r, c) in wire_positions if c == wire_col)
    road_rows_in_col = sorted(r for (r, c) in road_positions if c == road_col)
    road_rows_set = set(road_rows_in_col)

    # Helper: check if 3x3 zone area is clear
    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def no_nearby_zone(zr, zc):
        return not any(abs(zr - pr) <= 2 and abs(zc - pc) <= 2
                       for (pr, pc) in all_zones)

    def pick_zone_type():
        # Aim for ~50% res, ~25% com, ~25% ind
        if res_count == 0:
            return Tool.RESIDENTIAL
        elif ind_count * 4 < res_count:
            return Tool.INDUSTRIAL
        elif com_count * 4 < res_count:
            return Tool.COMMERCIAL
        else:
            return Tool.RESIDENTIAL

    # Phase 2: Extend wire spine vertically
    if not wire_rows_in_col:
        # Start wire adjacent to plant
        for try_r in [plant_cy, plant_cy - 1, plant_cy + 1]:
            if 0 <= try_r < WORLD_H and (em[try_r, wire_col]):
                return (Tool.WIRE, wire_col, try_r)
    else:
        min_wr = min(wire_rows_in_col)
        max_wr = max(wire_rows_in_col)
        # Extend downward
        if max_wr < tmax:
            nr = max_wr + 1
            if 0 < nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if min_wr > tmin:
            nr = min_wr - 1
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    if not wire_rows_in_col:
        return None

    # Phase 3: Build road column parallel to wire spine
    for wr in sorted(wire_rows_in_col):
        if wr not in road_rows_set:
            if 0 <= road_col < WORLD_W and em[wr, road_col]:
                return (Tool.ROAD, road_col, wr)

    # Phase 4: Build lateral wires from spine to left zone column
    # Need wires at each zone row from wire_col-1 down to left_zone_col
    for wr in sorted(wire_rows_in_col):
        for wc in range(wire_col - 1, max(left_zone_col - 2, 0), -1):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc]:
                    break  # already has wire here, covered
                if em[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                break  # blocked

    # Phase 5: Place zones on both sides of infrastructure
    for zr in sorted(wire_rows_in_col):
        # Need road nearby for the zone
        road_near = any(abs(zr - rr) <= 3 for rr in road_rows_set)
        if not road_near:
            continue

        for zc in [left_zone_col, right_zone_col]:
            if 2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3:
                if no_nearby_zone(zr, zc) and zone_area_free(zr, zc):
                    return (pick_zone_type(), zc, zr)

    # Phase 6: Lateral roads from road col to right zones
    for wr in sorted(wire_rows_in_col):
        for rc in range(road_col + 1, min(right_zone_col + 3, WORLD_W)):
            if rc == road_col:
                continue
            if rm[wr, rc]:
                break
            if em[wr, rc]:
                return (Tool.ROAD, rc, wr)
            break

    # Phase 7: Second cluster (right side) when pop >= 150
    if obs.city_pop >= 150:
        wire_col2  = road_col + 10   # col 74
        road_col2  = wire_col2 + 2   # col 76
        lzc2       = wire_col2 - 5   # col 69
        rzc2       = road_col2 + 4   # col 80

        wire_rows2 = sorted(r for (r, c) in wire_positions if c == wire_col2)
        road_rows2 = set(r for (r, c) in road_positions if c == road_col2)

        if not wire_rows2:
            # Bridge horizontally from first spine to second
            for wc in range(wire_col + 1, wire_col2 + 1):
                if em[plant_cy, wc]:
                    return (Tool.WIRE, wc, plant_cy)
                elif not wm[plant_cy, wc]:
                    break
        else:
            min_wr2 = min(wire_rows2)
            max_wr2 = max(wire_rows2)
            if max_wr2 < tmax:
                nr = max_wr2 + 1
                if 0 < nr < WORLD_H and em[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > tmin:
                nr = min_wr2 - 1
                if 0 <= nr < WORLD_H and em[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)

            for wr in sorted(wire_rows2):
                if wr not in road_rows2 and em[wr, road_col2]:
                    return (Tool.ROAD, road_col2, wr)

            for zr in sorted(wire_rows2):
                rn2 = any(abs(zr - rr) <= 3 for rr in road_rows2)
                if not rn2:
                    continue
                for zc in [lzc2, rzc2]:
                    if 2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3:
                        if no_nearby_zone(zr, zc) and zone_area_free(zr, zc):
                            return (pick_zone_type(), zc, zr)

            # lateral wires to left zone2
            for wr in sorted(wire_rows2):
                for wc in range(wire_col2 - 1, max(lzc2 - 2, 0), -1):
                    if wm[wr, wc]:
                        break
                    if em[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    break

            # lateral roads to right zone2
            for wr in sorted(wire_rows2):
                for rc in range(road_col2 + 1, min(rzc2 + 3, WORLD_W)):
                    if rm[wr, rc]:
                        break
                    if em[wr, rc]:
                        return (Tool.ROAD, rc, wr)
                    break

    # Phase 8: Third cluster (left side) when pop >= 350
    if obs.city_pop >= 350:
        wire_col3  = wire_col - 10   # col 52
        road_col3  = wire_col3 - 2   # col 50
        lzc3       = road_col3 - 4   # col 46
        rzc3       = wire_col3 + 5   # col 57

        wire_rows3 = sorted(r for (r, c) in wire_positions if c == wire_col3)
        road_rows3 = set(r for (r, c) in road_positions if c == road_col3)

        if not wire_rows3:
            for wc in range(wire_col - 1, wire_col3 - 1, -1):
                if em[plant_cy, wc]:
                    return (Tool.WIRE, wc, plant_cy)
                elif not wm[plant_cy, wc]:
                    break
        else:
            min_wr3 = min(wire_rows3)
            max_wr3 = max(wire_rows3)
            if max_wr3 < tmax:
                nr = max_wr3 + 1
                if 0 < nr < WORLD_H and em[nr, wire_col3]:
                    return (Tool.WIRE, wire_col3, nr)
            if min_wr3 > tmin:
                nr = min_wr3 - 1
                if 0 <= nr < WORLD_H and em[nr, wire_col3]:
                    return (Tool.WIRE, wire_col3, nr)

            for wr in sorted(wire_rows3):
                if wr not in road_rows3 and em[wr, road_col3]:
                    return (Tool.ROAD, road_col3, wr)

            for zr in sorted(wire_rows3):
                rn3 = any(abs(zr - rr) <= 3 for rr in road_rows3)
                if not rn3:
                    continue
                for zc in [lzc3, rzc3]:
                    if 2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3:
                        if no_nearby_zone(zr, zc) and zone_area_free(zr, zc):
                            return (pick_zone_type(), zc, zr)

            for wr in sorted(wire_rows3):
                for wc in range(wire_col3 - 1, max(lzc3 - 2, 0), -1):
                    if wm[wr, wc]:
                        break
                    if em[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    break

            for wr in sorted(wire_rows3):
                for rc in range(road_col3 + 1, min(rzc3 + 3, WORLD_W)):
                    if rm[wr, rc]:
                        break
                    if em[wr, rc]:
                        return (Tool.ROAD, rc, wr)
                    break

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Read current map each step, find existing infrastructure, extend from it.
    - Power plant -> wire spine -> roads -> zones, all grown reactively.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    # Key layout rows
    wire_row = cy - 2
    road_row = cy + 2
    upper_zone_row = wire_row - 4
    lower_zone_row = road_row + 4

    # Clamp
    wire_row = max(2, min(WORLD_H - 3, wire_row))
    road_row = max(2, min(WORLD_H - 3, road_row))
    upper_zone_row = max(1, min(WORLD_H - 2, upper_zone_row))
    lower_zone_row = max(1, min(WORLD_H - 2, lower_zone_row))

    # Dynamic spine extent based on population
    pop = obs.city_pop
    if pop < 50:
        extent = 10
    elif pop < 200:
        extent = 18
    elif pop < 500:
        extent = 28
    else:
        extent = 42

    spine_min = max(2, cx - extent)
    spine_max = min(WORLD_W - 3, cx + extent)

    # --- Phase 1: Power plant ---
    if not np.any(pm):
        # Place coal plant left of center
        px, py = cx - 18, cy
        px = max(2, min(WORLD_W - 3, px))
        py = max(2, min(WORLD_H - 3, py))
        return (Tool.COALPOWER, px, py)

    # Find plant center reactively
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # --- Phase 2: Connect plant to wire spine ---
    # Wire vertically from plant to wire_row, then horizontally
    conn_col = min(plant_cx + 3, WORLD_W - 3)

    # Check if wire spine is reachable from plant
    wire_on_spine = [c for c in range(WORLD_W) if wm[wire_row, c]]

    # Connect plant vertically to wire_row
    if not np.any(wm[wire_row, max(0, conn_col - 2):min(WORLD_W, conn_col + 3)]):
        # Place vertical wire from plant row to wire_row
        r_start = min(plant_cy + 2, wire_row)
        r_end = max(plant_cy + 2, wire_row)
        for r in range(r_start, r_end + 1):
            if 0 <= r < WORLD_H and not wm[r, conn_col] and not pm[r, conn_col]:
                if em[r, conn_col]:
                    return (Tool.WIRE, conn_col, r)

    # --- Phase 3: Extend wire spine reactively ---
    wire_on_spine = [c for c in range(WORLD_W) if wm[wire_row, c]]

    if not wire_on_spine:
        # Start wire near plant
        sc = conn_col
        if 0 <= sc < WORLD_W and em[wire_row, sc]:
            return (Tool.WIRE, sc, wire_row)
    else:
        min_wc = min(wire_on_spine)
        max_wc = max(wire_on_spine)
        # Extend right
        if max_wc < spine_max:
            nc = max_wc + 1
            if nc < WORLD_W and em[wire_row, nc] and not pm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)
        # Extend left
        if min_wc > spine_min:
            nc = min_wc - 1
            if nc >= 0 and em[wire_row, nc] and not pm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    wire_on_spine = [c for c in range(WORLD_W) if wm[wire_row, c]]

    # --- Phase 4: Build road spine reactively ---
    # Find existing road on road_row
    road_on_spine = [c for c in range(WORLD_W) if rm[road_row, c]]

    if not road_on_spine:
        # Start road near wire spine start
        if wire_on_spine:
            sc = wire_on_spine[len(wire_on_spine) // 2]
        else:
            sc = cx
        if em[road_row, sc] and not pm[road_row, sc]:
            return (Tool.ROAD, sc, road_row)
    else:
        min_rc = min(road_on_spine)
        max_rc = max(road_on_spine)
        # Extend road to match wire extent
        if wire_on_spine:
            target_min_road = max(spine_min, min(wire_on_spine))
            target_max_road = min(spine_max, max(wire_on_spine))
        else:
            target_min_road = spine_min
            target_max_road = spine_max

        if max_rc < target_max_road:
            nc = max_rc + 1
            if nc < WORLD_W and em[road_row, nc] and not pm[road_row, nc]:
                return (Tool.ROAD, nc, road_row)
        if min_rc > target_min_road:
            nc = min_rc - 1
            if nc >= 0 and em[road_row, nc] and not pm[road_row, nc]:
                return (Tool.ROAD, nc, road_row)

    # --- Helper: check zone placement ---
    all_zone_mask = resm | comm | indm

    def zone_area_empty(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_exists_near(zr, zc):
        r0, r1 = max(0, zr - 2), min(WORLD_H, zr + 3)
        c0, c1 = max(0, zc - 2), min(WORLD_W, zc + 3)
        return np.any(all_zone_mask[r0:r1, c0:c1])

    def has_wire_near(zr, zc, r=4):
        r0, r1 = max(0, zr - r), min(WORLD_H, zr + r + 1)
        c0, c1 = max(0, zc - r), min(WORLD_W, zc + r + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_near(zr, zc, r=4):
        r0, r1 = max(0, zr - r), min(WORLD_H, zr + r + 1)
        c0, c1 = max(0, zc - r), min(WORLD_W, zc + r + 1)
        return np.any(rm[r0:r1, c0:c1])

    def pick_tool(idx):
        pattern = [Tool.RESIDENTIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL,
                   Tool.INDUSTRIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL,
                   Tool.RESIDENTIAL, Tool.RESIDENTIAL, Tool.INDUSTRIAL]
        return pattern[idx % len(pattern)]

    # --- Phase 5: Vertical wires to reach upper zones ---
    # From wire spine, extend upward to upper_zone_row
    if wire_on_spine:
        # Every 4th wire position, run wire upward
        for wc in wire_on_spine[::4]:
            for r in range(wire_row - 1, upper_zone_row - 2, -1):
                if 0 <= r < WORLD_H:
                    if wm[r, wc] or pm[r, wc]:
                        break
                    if em[r, wc]:
                        return (Tool.WIRE, wc, r)
                    else:
                        break

    # --- Phase 6: Vertical roads to reach lower zones ---
    road_on_spine = [c for c in range(WORLD_W) if rm[road_row, c]]
    if road_on_spine:
        for rc in road_on_spine[::4]:
            for r in range(road_row + 1, lower_zone_row + 2):
                if 0 <= r < WORLD_H:
                    if rm[r, rc] or pm[r, rc]:
                        break
                    if em[r, rc]:
                        return (Tool.ROAD, rc, r)
                    else:
                        break

    # --- Phase 7: Place zones reactively ---
    # Scan zone columns that have both wire and road access
    zone_cols = list(range(spine_min + 1, spine_max, 4))
    zone_idx = 0

    for zc in zone_cols:
        # Upper zone row
        zr = upper_zone_row
        if not zone_exists_near(zr, zc) and zone_area_empty(zr, zc):
            if has_wire_near(zr, zc, 5) and has_road_near(zr, zc, 6):
                return (pick_tool(zone_idx), zc, zr)
        zone_idx += 1

        # Lower zone row
        zr = lower_zone_row
        if not zone_exists_near(zr, zc) and zone_area_empty(zr, zc):
            if has_wire_near(zr, zc, 5) and has_road_near(zr, zc, 5):
                return (pick_tool(zone_idx), zc, zr)
        zone_idx += 1

    # --- Phase 8: Second coal plant if needed ---
    n_plants = int(np.sum(pm))
    if pop > 200 and n_plants < 9:
        px2 = plant_cx + 28
        py2 = plant_cy
        px2 = max(2, min(WORLD_W - 3, px2))
        py2 = max(2, min(WORLD_H - 3, py2))
        # Check area is clear
        area_ok = True
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                rr, rc = py2 + dr, px2 + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if not em[rr, rc] and not pm[rr, rc]:
                        area_ok = False
        if area_ok:
            return (Tool.COALPOWER, px2, py2)

    # --- Phase 9: Extend wires to second plant ---
    if n_plants >= 9:
        plant_rows2, plant_cols2 = np.where(pm)
        # Connect all plant regions
        all_plant_cx = [int(c) for c in plant_cols2[::3]]
        for pcx in all_plant_cx:
            if not np.any(wm[wire_row, max(0, pcx - 3):min(WORLD_W, pcx + 4)]):
                cc = max(2, min(WORLD_W - 3, pcx))
                for r in range(min(wire_row, plant_cy), max(wire_row, plant_cy) + 1):
                    if 0 <= r < WORLD_H and em[r, cc] and not pm[r, cc]:
                        return (Tool.WIRE, cc, r)

    # --- Phase 10: Police/fire for happiness ---
    if pop > 300:
        for zc in [cx - 12, cx, cx + 12]:
            zr = cy
            zc = max(1, min(WORLD_W - 2, zc))
            zr = max(1, min(WORLD_H - 2, zr))
            if em[zr, zc]:
                return (Tool.FIRESTATION, zc, zr)

    # --- Phase 11: More zones at second tier ---
    if pop > 150:
        upper_zone_row2 = wire_row - 8
        lower_zone_row2 = road_row + 8
        upper_zone_row2 = max(1, min(WORLD_H - 2, upper_zone_row2))
        lower_zone_row2 = max(1, min(WORLD_H - 2, lower_zone_row2))

        for zc in zone_cols:
            zr = upper_zone_row2
            if not zone_exists_near(zr, zc) and zone_area_empty(zr, zc):
                if has_wire_near(zr, zc, 6) and has_road_near(zr, zc, 7):
                    return (pick_tool(zone_idx), zc, zr)
            zone_idx += 1
            zr = lower_zone_row2
            if not zone_exists_near(zr, zc) and zone_area_empty(zr, zc):
                if has_wire_near(zr, zc, 6) and has_road_near(zr, zc, 7):
                    return (pick_tool(zone_idx), zc, zr)
            zone_idx += 1

    return None

def act(obs, state):
    """
