    if plant_positions:
        pr, pc = plant_positions[0]
        plant_y = pr
        plant_x = pc
        wire_col_start = plant_x + 5
        wire_row = plant_y

    wire_col_start = max(5, min(WORLD_W - 10, wire_col_start))
    wire_col_end = min(WORLD_W - 5, wire_col_start + 50)
    road_row_above = max(3, wire_row - 3)
    road_row_below = min(WORLD_H - 4, wire_row + 3)
    zone_row_far_above = max(1, wire_row - 6)
    zone_row_far_below = min(WORLD_H - 2, wire_row + 6)

    # Phase 2: Build wire spine (horizontal)
    for wc in range(wire_col_start, wire_col_end + 1):
        if 0 <= wc < WORLD_W:
            if not wm[wire_row, wc] and (em[wire_row, wc] or True):
                # Don't overwrite the plant itself
                if not pm[wire_row, wc]:
                    if not wm[wire_row, wc]:
                        return (Tool.WIRE, wc, wire_row)

    # Phase 3: Build road rows above and below wire spine
    for rc in range(wire_col_start, wire_col_end + 1):
        if 0 <= rc < WORLD_W:
            if not rm[road_row_above, rc] and not pm[road_row_above, rc]:
                return (Tool.ROAD, rc, road_row_above)
            if not rm[road_row_below, rc] and not pm[road_row_below, rc]:
                return (Tool.ROAD, rc, road_row_below)

    # Phase 4: Build vertical wire connectors from spine to road rows
    # Connect wire spine to roads via vertical wires every 6 cols
    for wc in range(wire_col_start, wire_col_end + 1, 6):
        if 0 <= wc < WORLD_W:
            # Connect upward to road_row_above
            for wr in range(min(wire_row, road_row_above), max(wire_row, road_row_above) + 1):
                if not wm[wr, wc] and not pm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
            # Connect downward to road_row_below
            for wr in range(min(wire_row, road_row_below), max(wire_row, road_row_below) + 1):
                if not wm[wr, wc] and not pm[wr, wc]:
                    return (Tool.WIRE, wc, wr)

    # Helper functions
    def zone_clear(zr, zc):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                r2, c2 = zr + dr, zc + dc
                if r2 < 0 or r2 >= WORLD_H or c2 < 0 or c2 >= WORLD_W:
                    return False
                if pm[r2, c2]:
                    return False
                # Allow placing over empty, road, or wire (auto-bulldoze)
                # but not over zones or plants
                if res_m[r2, c2] or com_m[r2, c2] or ind_m[r2, c2]:
                    return False
        return True

    def zone_exists_near(zr, zc):
        r1, r2 = max(0, zr - 2), min(WORLD_H, zr + 3)
        c1, c2 = max(0, zc - 2), min(WORLD_W, zc + 3)
        return np.any(res_m[r1:r2, c1:c2]) or np.any(com_m[r1:r2, c1:c2]) or np.any(ind_m[r1:r2, c1:c2])

    def near_wire(zr, zc):
        r1, r2 = max(0, zr - 2), min(WORLD_H, zr + 3)
        c1, c2 = max(0, zc - 2), min(WORLD_W, zc + 3)
        return np.any(wm[r1:r2, c1:c2])

    def near_road(zr, zc):
        r1, r2 = max(0, zr - 2), min(WORLD_H, zr + 3)
        c1, c2 = max(0, zc - 2), min(WORLD_W, zc + 3)
        return np.any(rm[r1:r2, c1:c2])

    res_count = int(np.sum(res_m))
    com_count = int(np.sum(com_m))
    ind_count = int(np.sum(ind_m))
    total_zones = res_count + com_count + ind_count

    # Phase 5: Place zones along road rows
    # Zone cols: every 3 tiles from wire_col_start+3 to wire_col_end-3
    zone_cols = list(range(wire_col_start + 3, wire_col_end - 2, 3))

    # Zone rows to use: road rows themselves (zones placed AT road row = zone center on road)
    # Actually zones are 3x3, road should be adjacent not through center
    # Place zone centers at road_row_above-1 (zone bottom touches road) and road_row_below+1 (zone top touches road)
    # But let's use road_row as zone row if road is adjacent

    # Zones above: center at road_row_above - 1 (so bottom row of zone = road_row_above - 1 + 1 = road_row_above)
    # Wait: zone center at zr, footprint zr-1..zr+1. Road at road_row_above.
    # For road to touch zone: road_row_above == zr+1, so zr = road_row_above - 1
    # For wire to touch zone: wire_row == zr-1 or further... let's just use near_wire check

    zone_row_top = road_row_above - 1   # zones above road, touching road from above
    zone_row_bot = road_row_below + 1   # zones below road, touching road from below

    for zr, zrow_label in [(zone_row_top, 'top'), (zone_row_bot, 'bot')]:
        if zr < 1 or zr >= WORLD_H - 1:
            continue
        for zc in zone_cols:
            if zc < 1 or zc >= WORLD_W - 1:
                continue
            if zone_exists_near(zr, zc):
                continue
            if not zone_clear(zr, zc):
                continue
            if not near_road(zr, zc):
                continue
            if not near_wire(zr, zc):
                continue
            # Choose zone type: mix of res/com/ind
            # Ratio: 2 res : 1 com : 1 ind
            if ind_count * 4 < total_zones + 1:
                return (Tool.INDUSTRIAL, zc, zr)
            elif com_count * 4 < total_zones + 1:
                return (Tool.COMMERCIAL, zc, zr)
            else:
                return (Tool.RESIDENTIAL, zc, zr)

    # Phase 6: Extend infrastructure if city growing
    if obs.city_pop > 50:
        # Add a second cluster to the right
        new_wire_col_end = min(WORLD_W - 5, wire_col_end + 20)
        for wc in range(wire_col_end, new_wire_col_end + 1):
            if not wm[wire_row, wc] and not pm[wire_row, wc]:
                return (Tool.WIRE, wc, wire_row)
        # Extend roads
        for rc in range(wire_col_end, new_wire_col_end + 1):
            if 0 <= rc < WORLD_W:
                if not rm[road_row_above, rc] and not pm[road_row_above, rc]:
                    return (Tool.ROAD, rc, road_row_above)
                if not rm[road_row_below, rc] and not pm[road_row_below, rc]:
                    return (Tool.ROAD, rc, road_row_below)
        # Add connector wires for new section
        for wc in range(wire_col_end + 3, new_wire_col_end - 2, 6):
            if 0 <= wc < WORLD_W:
                for wr in range(min(wire_row, road_row_above), max(wire_row, road_row_above) + 1):
                    if not wm[wr, wc] and not pm[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                for wr in range(min(wire_row, road_row_below), max(wire_row, road_row_below) + 1):
                    if not wm[wr, wc] and not pm[wr, wc]:
                        return (Tool.WIRE, wc, wr)
        # Place zones in extended section
        ext_zone_cols = list(range(wire_col_end + 3, new_wire_col_end - 2, 3))
        for zr in [zone_row_top, zone_row_bot]:
            if zr < 1 or zr >= WORLD_H - 1:
                continue
            for zc in ext_zone_cols:
                if zc < 1 or zc >= WORLD_W - 1:
                    continue
                if zone_exists_near(zr, zc):
                    continue
                if not zone_clear(zr, zc):
                    continue
                if not near_road(zr, zc):
                    continue
                if not near_wire(zr, zc):
                    continue
                if ind_count * 4 < total_zones + 1:
                    return (Tool.INDUSTRIAL, zc, zr)
                elif com_count * 4 < total_zones + 1:
                    return (Tool.COMMERCIAL, zc, zr)
                else:
                    return (Tool.RESIDENTIAL, zc, zr)

    # Phase 7: Add more zone rows if city thriving
    if obs.city_pop > 200:
        # Add third and fourth road/zone rows further out
        road_row_far_above = max(2, wire_row - 9)
        road_row_far_below = min(WORLD_H - 3, wire_row + 9)
        zone_row_far_top = road_row_far_above - 1
        zone_row_far_bot = road_row_far_below + 1

        # Need wires connecting to these
        for wc in range(wire_col_start, wire_col_end + 1, 6):
            if 0 <= wc < WORLD_W:
                for wr in range(min(wire_row, road_row_far_above), max(wire_row, road_row_far_above) + 1):
                    if not wm[wr, wc] and not pm[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                for wr in range(min(wire_row, road_row_far_below), max(wire_row, road_row_far_below) + 1):
                    if not wm[wr, wc] and not pm[wr, wc]:
                        return (Tool.WIRE, wc, wr)

        # Extend roads on far rows
        for rc in range(wire_col_start, wire_col_end + 1):
            if 0 <= rc < WORLD_W:
                if 0 <= road_row_far_above < WORLD_H:
                    if not rm[road_row_far_above, rc] and not pm[road_row_far_above, rc]:
                        return (Tool.ROAD, rc, road_row_far_above)
                if 0 <= road_row_far_below < WORLD_H:
                    if not rm[road_row_far_below, rc] and not pm[road_row_far_below, rc]:
                        return (Tool.ROAD, rc, road_row_far_below)

        for zr in [zone_row_far_top, zone_row_far_bot]:
            if zr < 1 or zr >= WORLD_H - 1:
                continue
            for zc in zone_cols:
                if zc < 1 or zc >= WORLD_W - 1:
                    continue
                if zone_exists_near(zr, zc):
                    continue
                if not zone_clear(zr, zc):
                    continue
                if not near_road(zr, zc):
                    continue
                if not near_wire(zr, zc):
                    continue
                if ind_count * 4 < total_zones + 1:
                    return (Tool.INDUSTRIAL, zc, zr)
                elif com_count * 4 < total_zones + 1:
                    return (Tool.COMMERCIAL, zc, zr)
                else:
                    return (Tool.RESIDENTIAL, zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop policy: each step reads the current map and decides the next action.
    Strategy:
    - Place coal power plant near center if none exists
    - Grow wire spine from plant outward (vertically)
    - Grow road column adjacent to wire spine
    - Place zones adjacent to road+wire coverage
    - Add commercial/industrial to balance
    - Add second plant when needed
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    # Count zones for balance
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_zone():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        if com_count < total_zones * 0.25:
            return Tool.COMMERCIAL
        if ind_count < total_zones * 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Phase 1: Place coal power plant if none
    if not np.any(pm):
        # Place at center-left area
        px, py = cx - 3, cy
        px = max(1, min(WORLD_W - 2, px))
        py = max(1, min(WORLD_H - 2, py))
        return (Tool.COALPOWER, px, py)

    # Find plant position
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Wire spine column: just right of plant
    wire_col = plant_cx + 2
    wire_col = max(2, min(WORLD_W - 3, wire_col))
    # Road column: right of wire
    road_col = wire_col + 1
    road_col = max(2, min(WORLD_W - 3, road_col))
    # Zone column right of road
    right_zone_col = road_col + 3
    right_zone_col = max(2, min(WORLD_W - 3, right_zone_col))
    # Zone column left of wire
    left_zone_col = wire_col - 4
    left_zone_col = max(2, min(WORLD_W - 3, left_zone_col))

    # Determine spine extent based on population
    pop = obs.city_pop
    if pop < 100:
        spine_extent = 6
    elif pop < 300:
        spine_extent = 12
    elif pop < 600:
        spine_extent = 18
    else:
        spine_extent = 25

    spine_min = max(1, plant_cy - spine_extent)
    spine_max = min(WORLD_H - 2, plant_cy + spine_extent)

    # Find current wire on spine col
    wire_on_spine = [r for r in range(WORLD_H) if wm[r, wire_col]]
    road_on_col = [r for r in range(WORLD_H) if rm[r, road_col]]

    # Phase 2: Bootstrap wire - place first wire adjacent to plant
    if not wire_on_spine:
        # Place wire right next to plant
        for dy in range(0, 5):
            for nr in [plant_cy + dy, plant_cy - dy]:
                if 0 <= nr < WORLD_H and 0 <= wire_col < WORLD_W:
                    if em[nr, wire_col]:
                        return (Tool.WIRE, wire_col, nr)
        return None

    min_wire = min(wire_on_spine)
    max_wire = max(wire_on_spine)

    # Phase 3: Extend wire spine toward target extent
    # Extend downward
    if max_wire < spine_max:
        nr = max_wire + 1
        if nr < WORLD_H and em[nr, wire_col] and not pm[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)

    # Extend upward
    if min_wire > spine_min:
        nr = min_wire - 1
        if nr >= 0 and em[nr, wire_col] and not pm[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)

    # Phase 4: Build road alongside wire spine (closed-loop: check each wire row)
    for r in wire_on_spine:
        if 0 <= road_col < WORLD_W and em[r, road_col] and not pm[r, road_col]:
            return (Tool.ROAD, road_col, r)

    # Phase 5: Check if any zone can be placed right now
    # A zone is viable if within 2 rows of a road AND within 4 tiles of wire/plant
    def can_power(zr, zc):
        r0 = max(0, zr - 4); r1 = min(WORLD_H, zr + 5)
        c0 = max(0, zc - 4); c1 = min(WORLD_W, zc + 5)
        return bool(np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1]))

    def can_road(zr, zc):
        r0 = max(0, zr - 3); r1 = min(WORLD_H, zr + 4)
        c0 = max(0, zc - 3); c1 = min(WORLD_W, zc + 4)
        return bool(np.any(rm[r0:r1, c0:c1]))

    def zone_clear(zr, zc):
        # Zone is 3x3, center at (zr, zc)
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def has_nearby_zone(zr, zc):
        r0 = max(0, zr - 3); r1 = min(WORLD_H, zr + 4)
        c0 = max(0, zc - 4); c1 = min(WORLD_W, zc + 5)
        return bool(np.any(resm[r0:r1, c0:c1] | comm[r0:r1, c0:c1] | indm[r0:r1, c0:c1]))

    # Try to place zones along the spine
    zone_rows = list(range(spine_min + 1, spine_max, 3))
    for zr in zone_rows:
        # Right zone column
        zc = right_zone_col
        if zone_clear(zr, zc) and not has_nearby_zone(zr, zc):
            if can_power(zr, zc) and can_road(zr, zc):
                return (pick_zone(), zc, zr)

        # Left zone column
        zc = left_zone_col
        if zone_clear(zr, zc) and not has_nearby_zone(zr, zc):
            if can_power(zr, zc) and can_road(zr, zc):
                return (pick_zone(), zc, zr)

    # Phase 6: Extend roads rightward to reach right_zone_col
    for wr in wire_on_spine:
        for rc in range(road_col + 1, right_zone_col + 2):
            if rc >= WORLD_W:
                break
            if rm[wr, rc]:
                break
            if pm[wr, rc]:
                break
            if em[wr, rc]:
                return (Tool.ROAD, rc, wr)
            break

    # Phase 7: Extend wires leftward to reach left_zone_col
    for wr in wire_on_spine:
        for wc in range(wire_col - 1, left_zone_col - 2, -1):
            if wc < 0:
                break
            if wm[wr, wc] or pm[wr, wc]:
                break
            if em[wr, wc]:
                return (Tool.WIRE, wc, wr)
            break

    # Phase 8: Add second power plant when needed
    plant_count = int(np.sum(pm))
    if pop > 200 and plant_count < 9:
        # Try placing another coal plant further along
        candidates = [
            (plant_cx + 20, plant_cy),
            (plant_cx - 18, plant_cy),
            (plant_cx + 20, plant_cy + 15),
            (plant_cx + 20, plant_cy - 15),
        ]
        for px2, py2 in candidates:
            px2 = max(2, min(WORLD_W - 3, px2))
            py2 = max(2, min(WORLD_H - 3, py2))
            if py2 < 2 or py2 > WORLD_H - 3 or px2 < 2 or px2 > WORLD_W - 3:
                continue
            if np.all(em[py2-1:py2+2, px2-1:px2+2]):
                return (Tool.COALPOWER, px2, py2)

    # Phase 9: Expand zone corridor outward if city growing
    if pop > 150:
        extra_left = max(2, left_zone_col - 5)
        extra_right = min(WORLD_W - 3, right_zone_col + 5)
        for zc in [extra_left, extra_right]:
            for zr in zone_rows:
                if zone_clear(zr, zc) and not has_nearby_zone(zr, zc):
                    if can_power(zr, zc) and can_road(zr, zc):
                        return (pick_zone(), zc, zr)

    # Phase 10: Fill any gaps in wire spine
    for r in range(spine_min, spine_max + 1):
        if not wm[r, wire_col] and not pm[r, wire_col] and em[r, wire_col]:
            return (Tool.WIRE, wire_col, r)

    # Phase 11: Reactive zone placement - extend from existing zones
    # Find any empty tile adjacent to existing zones with road+power
    all_zone = resm | comm | indm
    if np.any(all_zone):
        # Build adjacency map
        nbr = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        nbr[1:, :] |= all_zone[:-1, :]
        nbr[:-1, :] |= all_zone[1:, :]
        nbr[:, 1:] |= all_zone[:, :-1]
        nbr[:, :-1] |= all_zone[:, 1:]
        cand_ys, cand_xs = np.where(em & nbr)
        for i in range(len(cand_xs)):
            zr, zc = int(cand_ys[i]), int(cand_xs[i])
            if zone_clear(zr, zc) and not has_nearby_zone(zr, zc):
                if can_power(zr, zc) and can_road(zr, zc):
                    return (pick_zone(), zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads current tile_map each step to decide next placement
    - Builds a compact cluster: power plant -> wire spine -> road columns -> zones
    - Adapts to actual map state rather than replaying a fixed plan
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    has_plant = np.any(pm)
    has_wire = np.any(wm)
    has_road = np.any(rm)

    res_count = max(1, int(np.sum(res_m)) // 9)
    com_count = max(1, int(np.sum(com_m)) // 9)
    ind_count = max(1, int(np.sum(ind_m)) // 9)

    # ---- Phase 1: Place coal power plant if missing ----
    if not has_plant:
        # Place at a fixed central location
        return (Tool.COALPOWER, 55, 50)

    # Find plant center
    plant_rows, plant_cols = np.where(pm)
    pcx = int(np.mean(plant_cols))
    pcy = int(np.mean(plant_rows))

    # Layout: wire spine 3 cols right of plant, roads on each side, zones further out
    wire_col = pcx + 3
    road_col_r = wire_col + 2
    road_col_l = wire_col - 2
    zone_col_r = road_col_r + 3
    zone_col_l = road_col_l - 3

    # Clamp to map
    wire_col = max(0, min(WORLD_W - 1, wire_col))
    road_col_r = max(0, min(WORLD_W - 1, road_col_r))
    road_col_l = max(0, min(WORLD_W - 1, road_col_l))
    zone_col_r = max(2, min(WORLD_W - 3, zone_col_r))
    zone_col_l = max(2, min(WORLD_W - 3, zone_col_l))

    # Vertical span: grow with population
    half_span = min(30, max(10, 10 + obs.city_pop // 15))
    tmin = max(2, pcy - half_span)
    tmax = min(WORLD_H - 3, pcy + half_span)

    # ---- Phase 2: Build wire spine vertically ----
    wire_rows = sorted(r for r in range(WORLD_H) if wm[r, wire_col]) if 0 <= wire_col < WORLD_W else []

    if not wire_rows:
        # Start wire adjacent to plant (right side)
        for dy in [0, 1, -1, 2, -2, 3]:
            ny = pcy + dy
            if 0 <= ny < WORLD_H and 0 <= wire_col < WORLD_W:
                if em[ny, wire_col]:
                    return (Tool.WIRE, wire_col, ny)
        # Fallback: try placing wire at plant row
        if 0 <= wire_col < WORLD_W:
            return (Tool.WIRE, wire_col, pcy)
    else:
        min_wr = wire_rows[0]
        max_wr = wire_rows[-1]
        # Extend downward first
        if max_wr < tmax:
            nr = max_wr + 1
            if 0 <= nr < WORLD_H and 0 <= wire_col < WORLD_W:
                if em[nr, wire_col] or wm[nr, wire_col]:
                    return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if min_wr > tmin:
            nr = min_wr - 1
            if 0 <= nr < WORLD_H and 0 <= wire_col < WORLD_W:
                if em[nr, wire_col] or wm[nr, wire_col]:
                    return (Tool.WIRE, wire_col, nr)

    wire_rows_set = set(wire_rows)

    # ---- Phase 3: Build road columns ----
    if wire_rows:
        # Right road column - fill gaps
        if 0 <= road_col_r < WORLD_W:
            for wr in wire_rows:
                if tmin <= wr <= tmax and not rm[wr, road_col_r] and em[wr, road_col_r]:
                    return (Tool.ROAD, road_col_r, wr)
        # Left road column
        if 0 <= road_col_l < WORLD_W:
            for wr in wire_rows:
                if tmin <= wr <= tmax and not rm[wr, road_col_l] and em[wr, road_col_l]:
                    return (Tool.ROAD, road_col_l, wr)

    # ---- Helper: check if 3x3 area is clear ----
    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    all_zone_m = res_m | com_m | ind_m

    def nearby_zone(zr, zc, radius=3):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(all_zone_m[r0:r1, c0:c1])

    def pick_zone():
        # Aim for ~60% res, 20% com, 20% ind
        total = res_count + com_count + ind_count
        if com_count * 3 < total:
            return Tool.COMMERCIAL
        if ind_count * 3 < total:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # ---- Phase 4: Place zones next to roads ----
    if wire_rows:
        road_rows_r = set(r for r in range(WORLD_H) if 0 <= road_col_r < WORLD_W and rm[r, road_col_r])
        road_rows_l = set(r for r in range(WORLD_H) if 0 <= road_col_l < WORLD_W and rm[r, road_col_l])

        # Place zones at wire rows adjacent to roads - alternate sides per row
        for zr in wire_rows:
            if not (tmin <= zr <= tmax):
                continue

            # Right zones (3 cols right of road_col_r)
            road_near_r = any(abs(zr - rr) <= 1 for rr in road_rows_r)
            if road_near_r and 2 <= zone_col_r <= WORLD_W - 3:
                if not nearby_zone(zr, zone_col_r, 2) and zone_area_free(zr, zone_col_r):
                    return (pick_zone(), zone_col_r, zr)

            # Left zones (3 cols left of road_col_l)
            road_near_l = any(abs(zr - rr) <= 1 for rr in road_rows_l)
            if road_near_l and 2 <= zone_col_l <= WORLD_W - 3:
                if not nearby_zone(zr, zone_col_l, 2) and zone_area_free(zr, zone_col_l):
                    return (pick_zone(), zone_col_l, zr)

        # Also place zones directly adjacent to road (1 col away)
        zone_col_r2 = road_col_r + 3
        zone_col_l2 = road_col_l - 3
        # Try inner zones too (between wire and road)
        for zr in wire_rows:
            if not (tmin <= zr <= tmax):
                continue
            road_near_r = any(abs(zr - rr) <= 1 for rr in road_rows_r)
            zone_col_inner_r = road_col_r - 3
            if road_near_r and 2 <= zone_col_inner_r <= WORLD_W - 3:
                if not nearby_zone(zr, zone_col_inner_r, 2) and zone_area_free(zr, zone_col_inner_r):
                    return (pick_zone(), zone_col_inner_r, zr)
            road_near_l = any(abs(zr - rr) <= 1 for rr in road_rows_l)
            zone_col_inner_l = road_col_l + 3
            if road_near_l and 2 <= zone_col_inner_l <= WORLD_W - 3:
                if not nearby_zone(zr, zone_col_inner_l, 2) and zone_area_free(zr, zone_col_inner_l):
                    return (pick_zone(), zone_col_inner_l, zr)

    # ---- Phase 5: Second cluster when city grows ----
    if obs.city_pop > 100 and wire_rows:
        # Second wire spine further right
        wire_col2 = pcx + 20
        wire_col2 = max(0, min(WORLD_W - 1, wire_col2))
        road_col_r2 = wire_col2 + 2
        road_col_l2 = wire_col2 - 2
        zone_col_r2 = road_col_r2 + 3
        zone_col_l2 = road_col_l2 - 3

        wire_rows2 = sorted(r for r in range(WORLD_H) if 0 <= wire_col2 < WORLD_W and wm[r, wire_col2])

        if not wire_rows2:
            # Bridge horizontally at pcy level from wire_col to wire_col2
            for wc in range(wire_col + 1, min(wire_col2 + 1, WORLD_W)):
                if 0 <= wc < WORLD_W and (em[pcy, wc] or wm[pcy, wc]):
                    return (Tool.WIRE, wc, pcy)
        else:
            min_wr2 = wire_rows2[0]
            max_wr2 = wire_rows2[-1]
            if max_wr2 < tmax:
                nr = max_wr2 + 1
                if 0 <= nr < WORLD_H and (em[nr, wire_col2] or wm[nr, wire_col2]):
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > tmin:
                nr = min_wr2 - 1
                if 0 <= nr < WORLD_H and (em[nr, wire_col2] or wm[nr, wire_col2]):
                    return (Tool.WIRE, wire_col2, nr)

            # Roads for cluster 2
            if 0 <= road_col_r2 < WORLD_W:
                for wr in wire_rows2:
                    if tmin <= wr <= tmax and not rm[wr, road_col_r2] and em[wr, road_col_r2]:
                        return (Tool.ROAD, road_col_r2, wr)
            if 0 <= road_col_l2 < WORLD_W:
                for wr in wire_rows2:
                    if tmin <= wr <= tmax and not rm[wr, road_col_l2] and em[wr, road_col_l2]:
                        return (Tool.ROAD, road_col_l2, wr)

            # Zones for cluster 2
            road_rows_r2 = set(r for r in range(WORLD_H) if 0 <= road_col_r2 < WORLD_W and rm[r, road_col_r2])
            road_rows_l2 = set(r for r in range(WORLD_H) if 0 <= road_col_l2 < WORLD_W and rm[r, road_col_l2])

            for zr in wire_rows2:
                if not (tmin <= zr <= tmax):
                    continue
                road_near_r2 = any(abs(zr - rr) <= 1 for rr in road_rows_r2)
                if road_near_r2 and 2 <= zone_col_r2 <= WORLD_W - 3:
                    if not nearby_zone(zr, zone_col_r2, 2) and zone_area_free(zr, zone_col_r2):
                        return (pick_zone(), zone_col_r2, zr)
                road_near_l2 = any(abs(zr - rr) <= 1 for rr in road_rows_l2)
                if road_near_l2 and 2 <= zone_col_l2 <= WORLD_W - 3:
                    if not nearby_zone(zr, zone_col_l2, 2) and zone_area_free(zr, zone_col_l2):
                        return (pick_zone(), zone_col_l2, zr)

    # ---- Phase 6: Second power plant when large ----
    if obs.city_pop > 300 and not state.get("plant2_placed", False):
        px2 = pcx + 22
        py2 = pcy
        px2 = max(2, min(WORLD_W - 3, px2))
        py2 = max(2, min(WORLD_H - 3, py2))
        clear = all(
            0 <= py2 + dr < WORLD_H and 0 <= px2 + dc < WORLD_W and em[py2 + dr, px2 + dc]
            for dr in [-1, 0, 1] for dc in [-1, 0, 1]
        )
        if clear:
            state["plant2_placed"] = True
            return (Tool.COALPOWER, px2, py2)
        # Connect wire bridge if plant not placed yet
        for wc in range(wire_col + 1, min(px2 + 1, WORLD_W)):
            if em[pcy, wc] or wm[pcy, wc]:
                return (Tool.WIRE, wc, pcy)

    # ---- Phase 7: Add horizontal road connectors for better connectivity ----
    if wire_rows and obs.city_pop > 50:
        # Add a horizontal road at center connecting left and right road columns
        hr = pcy
        if tmin <= hr <= tmax:
            if 0 <= road_col_l < WORLD_W and 0 <= road_col_r < WORLD_W:
                for rc in range(road_col_l, road_col_r + 1):
                    if 0 <= rc < WORLD_W and not rm[hr, rc] and em[hr, rc]:
                        return (Tool.ROAD, rc, hr)

    return None

def act(obs, state):
    """
    Improved city builder with a different layout strategy:
    - Place power plant at left-center
    - Build wire spine going RIGHT from plant
    - Build two horizontal roads parallel to wire spine (above and below)
    - Place zones in a dense grid pattern between roads
    - Mix residential, commercial, industrial evenly
    - Add second neighborhood further right
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    # Use state for phase tracking
    if 'initialized' not in state:
        state['initialized'] = True
        state['phase'] = 'plant'

    # Grid layout constants
    PX, PY = 20, 50   # Power plant center

    has_plant = np.any(pm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Phase 1: Place power plant ---
    if not has_plant:
        return (Tool.COALPOWER, PX, PY)

    # Recalculate plant center
    plant_ys, plant_xs = np.where(pm)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    wire_ys, wire_xs = np.where(wm)
    road_ys, road_xs = np.where(rm)
    res_ys, res_xs = np.where(resm)
    com_ys, com_xs = np.where(comm)
    ind_ys, ind_xs = np.where(indm)

    wire_set = set(zip(wire_ys.tolist(), wire_xs.tolist()))
    road_set = set(zip(road_ys.tolist(), road_xs.tolist()))
    zone_set = set(zip(
        np.concatenate([res_ys, com_ys, ind_ys]).tolist(),
        np.concatenate([res_xs, com_xs, ind_xs]).tolist()
    ))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def can_wire(x, y):
        return in_bounds(x, y) and bool(em[y, x]) and not bool(pm[y, x])

    def can_road(x, y):
        return in_bounds(x, y) and not bool(pm[y, x])

    def pick_tool():
        t = max(total_zones, 1)
        r_ratio = res_count / t
        c_ratio = com_count / t
        i_ratio = ind_count / t
        # Target: 50% R, 25% C, 25% I
        if c_ratio < 0.25:
            return Tool.COMMERCIAL
        if i_ratio < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Wire spine: horizontal from plant going right
    # Wire row = py (same row as plant center)
    wire_end = min(px + 80, WORLD_W - 5)

    # Build wire spine rightward
    for wx in range(px + 2, wire_end + 1):
        wy = py
        if not in_bounds(wx, wy):
            break
        if (wy, wx) not in wire_set and can_wire(wx, wy):
            return (Tool.WIRE, wx, wy)

    # Roads: two horizontal roads, 4 tiles above and below wire
    road_above = py - 4
    road_below = py + 4
    road_start = px + 2
    road_end = min(px + 78, WORLD_W - 3)

    # Build top road
    for rx in range(road_start, road_end + 1):
        if not in_bounds(rx, road_above):
            continue
        if (road_above, rx) not in road_set and can_road(rx, road_above):
            return (Tool.ROAD, rx, road_above)

    # Build bottom road
    for rx in range(road_start, road_end + 1):
        if not in_bounds(rx, road_below):
            continue
        if (road_below, rx) not in road_set and can_road(rx, road_below):
            return (Tool.ROAD, rx, road_below)

    # Vertical connector roads every 6 columns
    for vc in range(road_start, road_end + 1, 6):
        for vr in range(road_above, road_below + 1):
            if not in_bounds(vc, vr):
                continue
            if (vr, vc) not in road_set and can_road(vc, vr):
                return (Tool.ROAD, vc, vr)

    # Second wire spine for upper neighborhood
    upper_wire_y = road_above - 5
    for wx in range(road_start, road_end + 1):
        if not in_bounds(wx, upper_wire_y):
            break
        if (upper_wire_y, wx) not in wire_set and can_wire(wx, upper_wire_y):
            return (Tool.WIRE, wx, upper_wire_y)

    # Wire from plant up to upper spine
    for wy in range(py - 1, upper_wire_y - 1, -1):
        wx = road_start
        if not in_bounds(wx, wy):
            continue
        if (wy, wx) not in wire_set and can_wire(wx, wy):
            return (Tool.WIRE, wx, wy)

    # Second wire spine for lower neighborhood  
    lower_wire_y = road_below + 5
    for wx in range(road_start, road_end + 1):
        if not in_bounds(wx, lower_wire_y):
            break
        if (lower_wire_y, wx) not in wire_set and can_wire(wx, lower_wire_y):
            return (Tool.WIRE, wx, lower_wire_y)

    # Wire from plant down to lower spine
    for wy in range(py + 1, lower_wire_y + 2):
        wx = road_start
        if not in_bounds(wx, wy):
            continue
        if (wy, wx) not in wire_set and can_wire(wx, wy):
            return (Tool.WIRE, wx, wy)

    # Upper neighborhood roads
    upper_road_above = upper_wire_y - 4
    upper_road_below = upper_wire_y + 4
    for rx in range(road_start, road_end + 1):
        for rr in [upper_road_above, upper_road_below]:
            if not in_bounds(rx, rr):
                continue
            if (rr, rx) not in road_set and can_road(rx, rr):
                return (Tool.ROAD, rx, rr)

    # Lower neighborhood roads
    lower_road_above = lower_wire_y - 4
    lower_road_below = lower_wire_y + 4
    for rx in range(road_start, road_end + 1):
        for rr in [lower_road_above, lower_road_below]:
            if not in_bounds(rx, rr):
                continue
            if (rr, rx) not in road_set and can_road(rx, rr):
                return (Tool.ROAD, rx, rr)

    def has_road_near(zx, zy, r=3):
        for dr in range(-r, r + 1):
            for dc in range(-r, r + 1):
                if (zy + dr, zx + dc) in road_set:
                    return True
        return False

    def has_wire_near(zx, zy, r=5):
        for dr in range(-r, r + 1):
            for dc in range(-r, r + 1):
                nr, nc = zy + dr, zx + dc
                if (nr, nc) in wire_set:
                    return True
                if in_bounds(nc, nr) and pm[nr, nc]:
                    return True
        return False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    # Zone placement: between roads in main neighborhood
    zone_rows_main = [
        road_above - 2, road_above + 2,
        road_below - 2, road_below + 2,
        py,  # along wire spine
    ]
    zone_rows_upper = [
        upper_road_above - 2, upper_road_above + 2,
        upper_road_below - 2, upper_road_below + 2,
        upper_wire_y,
    ]
    zone_rows_lower = [
        lower_road_above - 2, lower_road_above + 2,
        lower_road_below - 2, lower_road_below + 2,
        lower_wire_y,
    ]

    all_zone_rows = zone_rows_main + zone_rows_upper + zone_rows_lower
    zone_cols = list(range(road_start + 3, road_end - 1, 6))

    for zr in all_zone_rows:
        for zc in zone_cols:
            if not (2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3):
                continue
            if zone_clear(zc, zr) and has_road_near(zc, zr) and has_wire_near(zc, zr):
                return (pick_tool(), zc, zr)

    # Dense zone filling using dilation approach
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand = em & nbr_road & nbr_wire
    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        k = int((obs.step * 13 + int(tm[50, 60]) % 50)) % len(cxs)
        zx, zy = int(cxs[k]), int(cys[k])
        if zone_clear(zx, zy):
            return (pick_tool(), zx, zy)

    # Second power plant when population grows
    if obs.city_pop > 200 and np.sum(pm) < 9:
        nx2, ny2 = px + 45, py
        if in_bounds(nx2, ny2) and em[ny2, nx2]:
            return (Tool.COALPOWER, nx2, ny2)

    # Services
    if obs.city_pop > 150:
        fx, fy = road_start + 5, road_above - 8
        if in_bounds(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
        fx2, fy2 = road_start + 15, road_below + 8
        if in_bounds(fx2, fy2) and em[fy2, fx2]:
            return (Tool.POLICESTATION, fx2, fy2)

    # Extend roads if needed
    if len(road_xs) > 0:
        k = int(obs.step * 11) % len(road_xs)
        rx2, ry2 = int(road_xs[k]), int(road_ys[k])
        for dx, dy in [(1, 0), (0, 1), (-1, 0), (0, -1)]:
            nx2, ny2 = rx2 + dx, ry2 + dy
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Hybrid policy combining best ideas from both parents:
    - Parent B's horizontal wire spine + parallel roads approach (cleaner than vertical)
    - Parent A's bilateral zone placement and phased expansion
    - Better zone placement with zone_clear checks
    - Second power plant when needed
    - Services for population boost
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Fixed anchor for plant
    CX, CY = 25, 50

    # Step 1: Place coal power plant
    if not np.any(pm):
        return (Tool.COALPOWER, CX, CY)

    plant_ys, plant_xs = np.where(pm)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    zone_set = set()
    for arr in [resm, comm, indm]:
        ys, xs = np.where(arr)
        for y, x in zip(ys.tolist(), xs.tolist()):
            zone_set.add((y, x))

    def pick_tool():
        t = max(total_zones, 1)
        if com_count / t < 0.22:
            return Tool.COMMERCIAL
        if ind_count / t < 0.22:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    # Layout: horizontal wire spine at py, roads above and below
    spine_y = py
    road_top = spine_y - 2
    road_bot = spine_y + 2

    # Extend wire spine based on population/phase
    if obs.city_pop < 200:
        wire_end_x = min(px + 40, WORLD_W - 4)
    elif obs.city_pop < 600:
        wire_end_x = min(px + 70, WORLD_W - 4)
    else:
        wire_end_x = min(px + 90, WORLD_W - 4)

    wire_start_x = px + 2

    # Phase 2: Extend horizontal wire spine
    for wx in range(wire_start_x, wire_end_x + 1):
        wy = spine_y
        if not in_bounds(wx, wy):
            break
        if not bool(wm[wy, wx]) and not bool(pm[wy, wx]):
            if bool(em[wy, wx]):
                return (Tool.WIRE, wx, wy)
            break  # blocked, stop

    # Phase 3: Vertical wire branches every 6 cols from spine
    branch_cols = list(range(wire_start_x + 4, wire_end_x + 1, 6))
    for bx in branch_cols:
        if not in_bounds(bx, spine_y):
            continue
        if not (bool(wm[spine_y, bx]) or bool(pm[spine_y, bx])):
            continue  # spine not wired here yet
        for sign in [-1, 1]:
            for dy in range(1, 5):
                wy = spine_y + sign * dy
                if not in_bounds(bx, wy):
                    break
                if bool(wm[wy, bx]) or bool(pm[wy, bx]):
                    continue
                if bool(em[wy, bx]):
                    return (Tool.WIRE, bx, wy)
                break

    # Phase 4: Build top road row
    road_start = px + 2
    road_end = min(px + wire_end_x - px - 2, WORLD_W - 4)
    road_end = max(road_end, road_start + 5)

    if 0 <= road_top < WORLD_H:
        for rx in range(road_start, road_end + 1):
            ry = road_top
            if not in_bounds(rx, ry):
                break
            if not bool(rm[ry, rx]) and not bool(pm[ry, rx]) and not bool(wm[ry, rx]):
                if bool(em[ry, rx]):
                    return (Tool.ROAD, rx, ry)
                break

    # Phase 5: Build bottom road row
    if 0 <= road_bot < WORLD_H:
        for rx in range(road_start, road_end + 1):
            ry = road_bot
            if not in_bounds(rx, ry):
                break
            if not bool(rm[ry, rx]) and not bool(pm[ry, rx]) and not bool(wm[ry, rx]):
                if bool(em[ry, rx]):
                    return (Tool.ROAD, rx, ry)
                break

    # Phase 6: Vertical connector roads every 6 cols between road rows
    for vc in range(road_start, road_end + 1, 6):
        for vr in range(road_top, road_bot + 1):
            if not in_bounds(vc, vr):
                continue
            if not bool(rm[vr, vc]) and not bool(pm[vr, vc]) and not bool(wm[vr, vc]):
                if bool(em[vr, vc]):
                    return (Tool.ROAD, vc, vr)

    # Phase 7: Zone placement using neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        step_hash = int(obs.step * 17 + int(obs.city_pop * 3)) % max(len(cxs_arr), 1)
        placed = False
        for offset in range(min(len(cxs_arr), 60)):
            k = (step_hash + offset * 11) % len(cxs_arr)
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # Phase 8: Second coal plant when many zones
    if total_zones > 12 or obs.city_pop > 300:
        p2x = min(px + 55, WORLD_W - 5)
        p2y = py
        nearby_plant = False
        for dy in range(-6, 7):
            for dx in range(-6, 7):
                ny2, nx2 = p2y + dy, p2x + dx
                if in_bounds(nx2, ny2) and bool(pm[ny2, nx2]):
                    nearby_plant = True
        if not nearby_plant and in_bounds(p2x, p2y) and bool(em[p2y, p2x]):
            return (Tool.COALPOWER, p2x, p2y)

    # Phase 9: Services
    if obs.city_pop > 150:
        fx, fy = px + 5, py - 8
        if in_bounds(fx, fy) and bool(em[fy, fx]):
            return (Tool.FIRESTATION, fx, fy)
        fx2, fy2 = px + 5, py + 8
        if in_bounds(fx2, fy2) and bool(em[fy2, fx2]):
            return (Tool.POLICESTATION, fx2, fy2)

    # Phase 10: Extend wire further to reach more area
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 7) % max(len(wire_xs_arr), 1)
        wx_s = int(wire_xs_arr[step_k2])
        wy_s = int(wire_ys_arr[step_k2])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = wx_s + dx2, wy_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)

    # Phase 11: Extend roads from existing frontier
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = int(obs.step * 13) % max(len(road_xs_arr), 1)
        rx_s = int(road_xs_arr[step_k])
        ry_s = int(road_ys_arr[step_k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx_s + dx2, ry_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map each step to decide next placement
    - Builds a compact city: power plant -> wire spine -> road -> zones
    - Adapts to current map state rather than following a fixed plan
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    has_plant = np.any(pm)
    has_wire = np.any(wm)
    has_road = np.any(rm)

    # City center - shifted slightly left to give room on right
    cx, cy = 55, 50

    # Phase 1: Place coal power plant if missing
    if not has_plant:
        # Place at cx-5, cy (footprint: cx-7..cx-3, cy-1..cy+1)
        return (Tool.COALPOWER, cx - 5, cy)

    # Find plant positions to anchor wire
    plant_positions = list(zip(*np.where(pm)))
    # Find plant bounding box to know where to start wire
    plant_cols = [c for (r, c) in plant_positions]
    plant_rows = [r for (r, c) in plant_positions]
    if plant_cols:
        plant_right = max(plant_cols)  # rightmost tile of plant
    else:
        plant_right = cx - 3

    # Wire spine column: right adjacent to plant
    wire_col = plant_right + 1
    # Road column: right adjacent to wire
    road_col = wire_col + 1

    # Zone columns: left of wire and right of road
    left_zone_col = wire_col - 3   # center 3 tiles left of wire
    right_zone_col = road_col + 3  # center 3 tiles right of road

    # Vertical range for wire/road/zones
    top_row = cy - 15
    bot_row = cy + 15

    # Phase 2: Extend wire spine vertically
    # Find current wire extent in wire_col
    wire_col_rows = sorted([r for (r, c) in zip(*np.where(wm)) if c == wire_col]) if has_wire else []

    # Ensure wire starts adjacent to plant
    if not wire_col_rows:
        # Place wire at plant_right+1, cy
        if 0 <= wire_col < WORLD_W and 0 <= cy < WORLD_H:
            return (Tool.WIRE, wire_col, cy)
    else:
        min_wr = min(wire_col_rows)
        max_wr = max(wire_col_rows)
        # Extend downward
        if max_wr < bot_row and max_wr + 1 < WORLD_H:
            nr = max_wr + 1
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if min_wr > top_row and min_wr - 1 >= 0:
            nr = min_wr - 1
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Phase 3: Build road column adjacent to wire spine
    road_col_rows = sorted([r for (r, c) in zip(*np.where(rm)) if c == road_col]) if has_road else []

    if wire_col_rows:
        for r in wire_col_rows:
            if 0 <= r < WORLD_H and 0 <= road_col < WORLD_W:
                if not rm[r, road_col] and em[r, road_col]:
                    return (Tool.ROAD, road_col, r)

    # Phase 4: Connect wire laterally to left zone column
    # Need wire at wire_col-1, wire_col-2 for rows where zones will go
    if wire_col_rows:
        for r in wire_col_rows:
            for wc in range(wire_col - 1, left_zone_col - 1, -1):
                if 0 <= wc < WORLD_W and 0 <= r < WORLD_H:
                    if not wm[r, wc] and em[r, wc]:
                        return (Tool.WIRE, wc, r)

    # Phase 5: Extend road laterally to right zone column
    if wire_col_rows:
        for r in wire_col_rows:
            for rc in range(road_col + 1, right_zone_col + 2):
                if 0 <= rc < WORLD_W and 0 <= r < WORLD_H:
                    if not rm[r, rc] and em[r, rc]:
                        return (Tool.ROAD, rc, r)

    # Helper: check if 3x3 zone area is free
    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    # Count zones
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))

    # Phase 6: Place zones where wire and road coverage exists
    # Scan rows where wire exists
    if wire_col_rows:
        # Determine zone rows (every 3 rows within range)
        zone_rows = list(range(cy - 12, cy + 13, 3))

        # Left zones (powered by lateral wire)
        for zr in zone_rows:
            zc = left_zone_col
            if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                # Check wire reaches this row laterally
                wire_lateral = wm[zr, zc] or wm[zr, zc+1] or wm[zr, zc+2] if zc+2 < WORLD_W else False
                # Check road nearby (within 2 cols)
                road_nearby = any(rm[zr, c] for c in range(max(0, zc-1), min(WORLD_W, road_col+2)))
                # Check wire nearby
                wire_nearby = any(wm[zr, c] for c in range(max(0, zc-2), min(WORLD_W, wire_col+2)))
                if wire_nearby and zone_area_free(zr, zc):
                    already_res = resm[zr, zc] or (zr-1 >= 0 and resm[zr-1, zc]) or (zr+1 < WORLD_H and resm[zr+1, zc])
                    if not already_res:
                        # Mix of zone types
                        if ind_count < res_count // 3 and zr > cy:
                            return (Tool.INDUSTRIAL, zc, zr)
                        else:
                            return (Tool.RESIDENTIAL, zc, zr)

        # Right zones (road access)
        for zr in zone_rows:
            zc = right_zone_col
            if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                road_nearby = any(rm[zr, c] for c in range(max(0, zc-3), min(WORLD_W, zc+3)))
                wire_nearby = any(wm[zr, c] for c in range(max(0, zc-4), min(WORLD_W, zc+1)))
                if road_nearby and zone_area_free(zr, zc):
                    already_zone = (resm[zr, zc] or comm[zr, zc] or indm[zr, zc] or
                                   (zr-1 >= 0 and (resm[zr-1, zc] or comm[zr-1, zc])) or
                                   (zr+1 < WORLD_H and (resm[zr+1, zc] or comm[zr+1, zc])))
                    if not already_zone:
                        if com_count < res_count // 3:
                            return (Tool.COMMERCIAL, zc, zr)
                        else:
                            return (Tool.RESIDENTIAL, zc, zr)

    # Phase 7: If population growing, expand zone range
    if obs.city_pop > 300:
        for zr in range(cy - 18, cy + 19, 3):
            for zc in [left_zone_col, right_zone_col]:
                if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                    if zone_area_free(zr, zc):
                        wire_nearby = any(wm[zr, c] for c in range(max(0, zc-3), min(WORLD_W, zc+4)))
                        road_nearby = any(rm[zr, c] for c in range(max(0, zc-3), min(WORLD_W, zc+4)))
                        if wire_nearby or road_nearby:
                            return (Tool.RESIDENTIAL, zc, zr)

    # Phase 8: Add wire/road extensions to reach new zone rows
    if wire_col_rows:
        for r in range(cy - 15, cy + 16):
            if 0 <= r < WORLD_H:
                if wire_col < WORLD_W and em[r, wire_col]:
                    return (Tool.WIRE, wire_col, r)
                if road_col < WORLD_W and em[r, road_col]:
                    return (Tool.ROAD, road_col, r)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder v2.
    Key changes from parent:
    - Single cluster centered at (60, 50) instead of two clusters
    - Denser road grid with zones packed tightly around power
    - Wire extends outward from plant in all 4 directions first
    - Zones placed closer to power spine (within 3 tiles of wire)
    - More balanced road/wire/zone interleaving
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Single central cluster
    CX, CY = 60, 50

    # Check if main power plant exists
    plant_ys, plant_xs = np.where(pm)
    has_plant = any(abs(px - CX) < 6 and abs(py - CY) < 6
                    for py, px in zip(plant_ys.tolist(), plant_xs.tolist()))

    # Phase 1: place power plant
    if not has_plant:
        return (Tool.COALPOWER, CX, CY)

    # Count zones
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Phase 2: Build wire cross/grid outward from plant
    # Wire spine: horizontal at CY, vertical at CX, radius 15
    wire_targets = []
    # Cross pattern first
    for d in range(-15, 16):
        wire_targets.append((CX + d, CY))
        wire_targets.append((CX, CY + d))
    # Then fill a grid at CX±4, CY±4
    for wx in [CX - 4, CX + 4]:
        for d in range(-12, 13):
            wire_targets.append((wx, CY + d))
    for wy in [CY - 4, CY + 4]:
        for d in range(-12, 13):
            wire_targets.append((CX + d, wy))

    for (wx, wy) in wire_targets:
        if not in_bounds(wx, wy):
            continue
        if bool(wm[wy, wx]) or bool(pm[wy, wx]) or bool(rm[wy, wx]):
            continue
        adj_power = False
        for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = wx + ddx, wy + ddy
            if in_bounds(nx2, ny2) and (bool(pm[ny2, nx2]) or bool(wm[ny2, nx2])):
                adj_power = True
                break
        if adj_power and bool(em[wy, wx]):
            return (Tool.WIRE, wx, wy)

    # Phase 3: Build road grid around center
    # Roads at offsets from center: columns at CX±2, CX±6, CX±10
    # Rows at CY±2, CY±6, CY±10
    road_targets = []
    road_cols = [CX - 10, CX - 6, CX - 2, CX + 2, CX + 6, CX + 10]
    road_rows = [CY - 10, CY - 6, CY - 2, CY + 2, CY + 6, CY + 10]

    # Vertical road columns
    for rx in road_cols:
        for dy in range(-12, 13):
            road_targets.append((rx, CY + dy))
    # Horizontal road rows
    for ry in road_rows:
        for dx in range(-12, 13):
            road_targets.append((CX + dx, ry))
    # Connecting road ring
    for dx in range(-12, 13):
        road_targets.append((CX + dx, CY - 12))
        road_targets.append((CX + dx, CY + 12))
    for dy in range(-12, 13):
        road_targets.append((CX - 12, CY + dy))
        road_targets.append((CX + 12, CY + dy))

    for (rx, ry) in road_targets:
        if not in_bounds(rx, ry):
            continue
        if bool(rm[ry, rx]) or bool(wm[ry, rx]) or bool(pm[ry, rx]):
            continue
        adj_road = False
        for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx + ddx, ry + ddy
            if in_bounds(nx2, ny2) and bool(rm[ny2, nx2]):
                adj_road = True
                break
        adj_plant = False
        for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1),
                          (2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = rx + ddx, ry + ddy
            if in_bounds(nx2, ny2) and bool(pm[ny2, nx2]):
                adj_plant = True
                break
        if (adj_road or adj_plant) and bool(em[ry, rx]):
            return (Tool.ROAD, rx, ry)

    # Phase 4: Place zones near roads and power
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_mask = resm | comm | indm
    cand = em & nbr_road & nbr_power
    cand[0:2, :] = False
    cand[WORLD_H - 2:, :] = False
    cand[:, 0:2] = False
    cand[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        # Sort candidates by distance to center (prefer dense cluster)
        dists = (cxs - CX) ** 2 + (cys - CY) ** 2
        order = np.argsort(dists)
        # Try closest candidates first with some variation
        key = int(obs.step * 7 + int(obs.city_pop) + 1) % max(1, min(len(order), 30))
        tried = 0
        for offset in range(min(len(cxs), 120)):
            k = order[(key + offset * 3) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            ok = True
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    ny2, nx2 = zy + dr, zx + dc
                    if not in_bounds(nx2, ny2):
                        ok = False; break
                    tile_ok = bool(em[ny2, nx2]) or bool(zone_mask[ny2, nx2])
                    if not tile_ok:
                        ok = False; break
                if not ok:
                    break
            if ok:
                return (pick_tool(), zx, zy)

    # Phase 5: services
    if obs.city_pop > 150:
        for fx, fy in [(CX + 8, CY - 8), (CX - 8, CY + 8)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 250:
        for fx, fy in [(CX + 8, CY + 8), (CX - 8, CY - 8)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.POLICESTATION, fx, fy)

    # Fallback: grow road from existing frontier
    rys, rxs = np.where(rm)
    if len(rxs) > 0:
        k2 = int(obs.step * 13) % len(rxs)
        rx2, ry2 = int(rxs[k2]), int(rys[k2])
        for ddx, ddy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nx2, ny2 = rx2 + ddx, ry2 + ddy
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # Fallback: grow wire
    wys, wxs = np.where(wm)
    if len(wxs) > 0:
        k3 = int(obs.step * 7) % len(wxs)
        wx2, wy2 = int(wxs[k3]), int(wys[k3])
        for ddx, ddy in [(1, 0), (0, 1), (-1, 0), (0, -1)]:
            nx2, ny2 = wx2 + ddx, wy2 + ddy
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map every step and reacts to what's there.
    Strategy:
    - Place coal plant near center
    - Extend wire spine vertically from plant
    - Build road column adjacent to wire spine
    - Place zones (R/C/I) flanking the road, powered by wire
    - Add lateral wires/roads to expand reach
    - Add second plant and clusters when population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    all_zone_mask = resm | comm | indm

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def wire_nearby(zr, zc, radius=5):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def road_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    # Step 1: Place coal power plant if none exists
    if not np.any(pm):
        return (Tool.COALPOWER, cx - 8, cy)

    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Core layout columns relative to plant
    wire_col = plant_cx + 4
    road_col = wire_col + 2
    left_zone_col = wire_col - 3
    right_zone_col = road_col + 3

    wire_col = max(2, min(WORLD_W - 3, wire_col))
    road_col = max(2, min(WORLD_W - 3, road_col))
    left_zone_col = max(2, min(WORLD_W - 3, left_zone_col))
    right_zone_col = max(2, min(WORLD_W - 3, right_zone_col))

    # Dynamic spine extent based on current population
    pop = obs.city_pop
    if pop < 50:
        spine_extent = 8
    elif pop < 150:
        spine_extent = 14
    elif pop < 350:
        spine_extent = 20
    elif pop < 600:
        spine_extent = 28
    else:
        spine_extent = 36

    target_min = max(1, cy - spine_extent)
    target_max = min(WORLD_H - 2, cy + spine_extent)

    # Find existing wire and road on spine columns
    wire_rows_on_spine = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])
    road_rows_set = set(r for r in range(WORLD_H) if rm[r, road_col])

    # Step 2: Start wire adjacent to plant
    if not wire_rows_on_spine:
        for dy in range(0, 8):
            for nr in [plant_cy + dy, plant_cy - dy]:
                if 0 <= nr < WORLD_H:
                    if em[nr, wire_col] or wm[nr, wire_col]:
                        return (Tool.WIRE, wire_col, nr)
        return None

    min_wire_row = min(wire_rows_on_spine)
    max_wire_row = max(wire_rows_on_spine)

    # Step 3: Extend wire spine downward
    if max_wire_row < target_max:
        nr = max_wire_row + 1
        if nr < WORLD_H and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Step 4: Extend wire spine upward
    if min_wire_row > target_min:
        nr = min_wire_row - 1
        if nr >= 0 and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Step 5: Build road column parallel to wire spine
    for r in wire_rows_on_spine:
        if 0 <= r < WORLD_H and 0 <= road_col < WORLD_W:
            if not rm[r, road_col] and em[r, road_col]:
                return (Tool.ROAD, road_col, r)

    # Step 6: Lateral wires from spine to left zones
    for wr in wire_rows_on_spine:
        for wc in range(wire_col - 1, max(left_zone_col - 3, 0), -1):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc]:
                    break

    # Step 7: Lateral road from road_col to right zones
    for rr in wire_rows_on_spine:
        if not rm[rr, road_col]:
            continue
        for rc in range(road_col + 1, right_zone_col + 3):
            if 0 <= rc < WORLD_W:
                if rm[rr, rc]:
                    break
                if em[rr, rc] and not pm[rr, rc]:
                    return (Tool.ROAD, rc, rr)
                elif not em[rr, rc]:
                    break

    # Step 8: Lateral wire to right zones for power
    for wr in wire_rows_on_spine:
        for wc in range(wire_col + 1, right_zone_col + 3):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc] and not rm[wr, wc]:
                    break

    # Step 9: Place zones along the corridor
    zone_rows = list(range(max(1, target_min), min(WORLD_H - 1, target_max + 1), 3))
    road_rows_list = sorted(road_rows_set)

    for zr in zone_rows:
        wire_near = any(abs(zr - wr) <= 2 for wr in wire_rows_on_spine)
        road_near = any(abs(zr - rr) <= 2 for rr in road_rows_list)

        if wire_near and road_near:
            # Try left zone
            for zc in [left_zone_col, left_zone_col - 4]:
                if 2 <= zc <= WORLD_W - 3:
                    if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                        if wire_nearby(zr, zc, 5) and road_nearby(zr, zc, 5):
                            return (pick_tool(), zc, zr)

            # Try right zone
            for zc in [right_zone_col, right_zone_col + 4]:
                if 2 <= zc <= WORLD_W - 3:
                    if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                        if wire_nearby(zr, zc, 6) and road_nearby(zr, zc, 5):
                            return (pick_tool(), zc, zr)

    # Step 10: Second power plant when population grows
    if pop > 300 and int(np.sum(pm)) < 9:
        # Check if a second plant is needed (few powered zones)
        px2 = plant_cx + 18
        py2 = plant_cy
        if 2 <= py2 <= WORLD_H - 3 and 2 <= px2 <= WORLD_W - 3:
            area_clear = all(
                em[py2 + dr, px2 + dc] or pm[py2 + dr, px2 + dc]
                for dr in [-1, 0, 1] for dc in [-1, 0, 1]
                if 0 <= py2 + dr < WORLD_H and 0 <= px2 + dc < WORLD_W
            )
            if area_clear:
                return (Tool.COALPOWER, px2, py2)

    # Step 11: Second vertical cluster (right side) when pop >= 200
    if pop >= 200:
        wire_col2 = road_col + 9
        road_col2 = wire_col2 + 2
        left_zone_col2 = wire_col2 - 3
        right_zone_col2 = road_col2 + 3

        wire_col2 = max(2, min(WORLD_W - 3, wire_col2))
        road_col2 = max(2, min(WORLD_W - 3, road_col2))
        left_zone_col2 = max(2, min(WORLD_W - 3, left_zone_col2))
        right_zone_col2 = max(2, min(WORLD_W - 3, right_zone_col2))

        wire_rows2 = sorted([r for r in range(WORLD_H) if wm[r, wire_col2]])
        road_rows2 = set(r for r in range(WORLD_H) if rm[r, road_col2])

        if not wire_rows2:
            # Build horizontal wire bridge
            for wc in range(wire_col + 1, wire_col2 + 1):
                if 0 <= wc < WORLD_W:
                    if not wm[plant_cy, wc] and em[plant_cy, wc]:
                        return (Tool.WIRE, wc, plant_cy)
                    elif not em[plant_cy, wc] and not wm[plant_cy, wc]:
                        break
        else:
            min_wr2 = min(wire_rows2)
            max_wr2 = max(wire_rows2)

            if max_wr2 < target_max:
                nr = max_wr2 + 1
                if nr < WORLD_H and em[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > target_min:
                nr = min_wr2 - 1
                if nr >= 0 and em[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)

            for wr in wire_rows2:
                if wr not in road_rows2 and em[wr, road_col2]:
                    return (Tool.ROAD, road_col2, wr)

            # Lateral wires left for cluster2
            for wr in wire_rows2:
                for wc in range(wire_col2 - 1, max(left_zone_col2 - 3, 0), -1):
                    if 0 <= wc < WORLD_W:
                        if wm[wr, wc]: break
                        if em[wr, wc] and not pm[wr, wc]:
                            return (Tool.WIRE, wc, wr)
                        elif not em[wr, wc]: break

            # Roads right for cluster2
            for wr in wire_rows2:
                if not rm[wr, road_col2]: continue
                for rc in range(road_col2 + 1, right_zone_col2 + 3):
                    if 0 <= rc < WORLD_W:
                        if rm[wr, rc]: break
                        if em[wr, rc] and not pm[wr, rc]:
                            return (Tool.ROAD, rc, wr)
                        elif not em[wr, rc]: break

            for zr in zone_rows:
                wire_near2 = any(abs(zr - wr) <= 2 for wr in wire_rows2)
                road_near2 = any(abs(zr - rr) <= 2 for rr in road_rows2)
                if wire_near2 and road_near2:
                    for zc in [left_zone_col2, right_zone_col2]:
                        if 2 <= zc <= WORLD_W - 3:
                            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                                if wire_nearby(zr, zc, 6) and road_nearby(zr, zc, 5):
                                    return (pick_tool(), zc, zr)

    # Step 12: Third cluster to the left when pop >= 400
    if pop >= 400:
        wire_col3 = wire_col - 11
        road_col3 = wire_col3 - 2
        left_zone_col3 = road_col3 - 3
        right_zone_col3 = wire_col3 + 3

        wire_col3 = max(2, min(WORLD_W - 3, wire_col3))
        road_col3 = max(2, min(WORLD_W - 3, road_col3))
        left_zone_col3 = max(2, min(WORLD_W - 3, left_zone_col3))
        right_zone_col3 = max(2, min(WORLD_W - 3, right_zone_col3))

        wire_rows3 = sorted([r for r in range(WORLD_H) if wm[r, wire_col3]])
        road_rows3 = set(r for r in range(WORLD_H) if rm[r, road_col3])

        if not wire_rows3:
            for wc in range(wire_col - 1, wire_col3 - 1, -1):
                if 0 <= wc < WORLD_W:
                    if not wm[plant_cy, wc] and em[plant_cy, wc]:
                        return (Tool.WIRE, wc, plant_cy)
                    elif not em[plant_cy, wc] and not wm[plant_cy, wc]:
                        break
        else:
            min_wr3 = min(wire_rows3)
            max_wr3 = max(wire_rows3)

            if max_wr3 < target_max:
                nr = max_wr3 + 1
                if nr < WORLD_H and em[nr, wire_col3]:
                    return (Tool.WIRE, wire_col3, nr)
            if min_wr3 > target_min:
                nr = min_wr3 - 1
                if nr >= 0 and em[nr, wire_col3]:
                    return (Tool.WIRE, wire_col3, nr)

            for wr in wire_rows3:
                if wr not in road_rows3 and em[wr, road_col3]:
                    return (Tool.ROAD, road_col3, wr)

            for wr in wire_rows3:
                for wc in range(wire_col3 + 1, min(right_zone_col3 + 3, WORLD_W)):
                    if wm[wr, wc]: break
                    if em[wr, wc] and not pm[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    elif not em[wr, wc]: break

            for wr in wire_rows3:
                if not rm[wr, road_col3]: continue
                for rc in range(road_col3 - 1, max(left_zone_col3 - 3, 0), -1):
                    if 0 <= rc < WORLD_W:
                        if rm[wr, rc]: break
                        if em[wr, rc] and not pm[wr, rc]:
                            return (Tool.ROAD, rc, wr)
                        elif not em[wr, rc]: break

            for zr in zone_rows:
                wire_near3 = any(abs(zr - wr) <= 2 for wr in wire_rows3)
                road_near3 = any(abs(zr - rr) <= 2 for rr in road_rows3)
                if wire_near3 and road_near3:
                    for zc in [left_zone_col3, right_zone_col3]:
                        if 2 <= zc <= WORLD_W - 3:
                            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                                if wire_nearby(zr, zc, 6) and road_nearby(zr, zc, 5):
                                    return (pick_tool(), zc, zr)

    # Step 13: Scan for any empty zone-able spot near existing power+road
    # This is the high-reactivity fallback: find any powered+roaded spot
    if total_zones < 60:
        for zr in range(2, WORLD_H - 2, 3):
            for zc in range(2, WORLD_W - 2, 3):
                if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                    if wire_nearby(zr, zc, 4) and road_nearby(zr, zc, 4):
                        return (pick_tool(), zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Each step reads tile_map and grows outward from what exists
    - Places coal plant first, then wires from plant, then roads adjacent to wires,
      then zones adjacent to roads, expanding dynamically
    - Tracks phase in state but all geometry comes from reading the map
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop

    # Zone mix: aim for 50% res, 30% com, 20% ind
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        if com_count * 10 < total_zones * 3:
            return Tool.COMMERCIAL
        if ind_count * 10 < total_zones * 2:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def zone_too_close(zr, zc):
        all_zone = resm | comm | indm
        for dr in range(-3, 4):
            for dc in range(-3, 4):
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone[rr, rc]:
                        return True
        return False

    # Step 1: Place coal power plant if none exists
    if not np.any(pm):
        # Place near center-left
        px, py = 54, 50
        return (Tool.COALPOWER, px, py)

    # Find plant location
    plant_rows, plant_cols = np.where(pm)
    pcx = int(np.mean(plant_cols))
    pcy = int(np.mean(plant_rows))

    # Step 2: Grow wire spine vertically from plant
    # Wire column: right edge of plant + 1
    wire_col = pcx + 4
    wire_col = max(2, min(WORLD_W - 3, wire_col))

    # Road column: one right of wire
    road_col = wire_col + 1
    road_col = max(2, min(WORLD_W - 3, road_col))

    # Dynamic vertical span
    base_span = 10
    extra = min(35, pop // 30)
    span = base_span + extra
    cy = pcy
    tmin = max(2, cy - span)
    tmax = min(WORLD_H - 3, cy + span)

    wire_rows = [r for r in range(WORLD_H) if wm[r, wire_col]]
    road_rows = [r for r in range(WORLD_H) if rm[r, road_col]]
    wire_set = set(wire_rows)
    road_set = set(road_rows)

    # If no wire at all, start wire adjacent to plant
    if not wire_rows:
        # Place first wire touching plant
        for dy in range(-2, 3):
            nr = pcy + dy
            if 0 <= nr < WORLD_H and em[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)
        return None

    min_wr = min(wire_rows)
    max_wr = max(wire_rows)

    # Extend wire spine downward
    if max_wr < tmax:
        nr = max_wr + 1
        if 0 <= nr < WORLD_H and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Extend wire spine upward
    if min_wr > tmin:
        nr = min_wr - 1
        if 0 <= nr < WORLD_H and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Step 3: Build road column adjacent to wire spine
    for wr in sorted(wire_rows, key=lambda r: abs(r - cy)):
        if tmin <= wr <= tmax and wr not in road_set:
            if 0 <= road_col < WORLD_W and em[wr, road_col]:
                return (Tool.ROAD, road_col, wr)

    # Step 4: Place zones on both sides of the road/wire corridor
    # Right side: zones at road_col + 2 (adjacent to road)
    right_zone_col = road_col + 2
    # Left side: zones at wire_col - 2 (need lateral wire)
    left_zone_col = wire_col - 2

    right_zone_col = max(3, min(WORLD_W - 4, right_zone_col))
    left_zone_col = max(3, min(WORLD_W - 4, left_zone_col))

    # Try right-side zones first (road access from road_col)
    for zr in sorted(wire_rows, key=lambda r: abs(r - cy)):
        if not (tmin <= zr <= tmax):
            continue
        road_near = any(abs(zr - rr) <= 1 for rr in road_set)
        if road_near:
            if 1 <= zr <= WORLD_H - 2 and 1 <= right_zone_col <= WORLD_W - 2:
                if not zone_too_close(zr, right_zone_col) and zone_area_free(zr, right_zone_col):
                    return (pick_tool(), right_zone_col, zr)

    # Step 5: Lateral wires to power left zones
    for wr in sorted(wire_rows, key=lambda r: abs(r - cy)):
        if not (tmin <= wr <= tmax):
            continue
        # Extend wire leftward to left_zone_col + 1
        for wc in range(wire_col - 1, max(0, left_zone_col - 1), -1):
            if wm[wr, wc]:
                break
            if em[wr, wc] and not pm[wr, wc]:
                return (Tool.WIRE, wc, wr)
            elif not em[wr, wc] and not wm[wr, wc]:
                break

    # Step 6: Left side zones (need lateral wire reaching them + road nearby)
    # Add a left road column
    left_road_col = wire_col - 3
    left_road_col = max(2, min(WORLD_W - 3, left_road_col))
    left_road_set = set(r for r in range(WORLD_H) if rm[r, left_road_col])

    # Build left road column
    for wr in sorted(wire_rows, key=lambda r: abs(r - cy)):
        if tmin <= wr <= tmax and wr not in left_road_set:
            # Check wire reaches here
            if any(wm[wr, wc] for wc in range(left_road_col, wire_col)):
                if 0 <= left_road_col < WORLD_W and em[wr, left_road_col]:
                    return (Tool.ROAD, left_road_col, wr)

    # Left side zones
    for zr in sorted(wire_rows, key=lambda r: abs(r - cy)):
        if not (tmin <= zr <= tmax):
            continue
        road_near = any(abs(zr - rr) <= 1 for rr in left_road_set)
        wire_near = any(wm[zr, wc] for wc in range(max(0, left_zone_col - 2), min(WORLD_W, left_zone_col + 3)))
        if road_near and wire_near:
            if 1 <= zr <= WORLD_H - 2 and 1 <= left_zone_col <= WORLD_W - 2:
                if not zone_too_close(zr, left_zone_col) and zone_area_free(zr, left_zone_col):
                    return (pick_tool(), left_zone_col, zr)

    # Step 7: Second power plant for large cities
    num_plant_tiles = int(np.sum(pm))
    if pop > 200 and num_plant_tiles < 18:
        # Place second plant further right
        px2 = pcx + 14
        py2 = pcy
        px2 = max(2, min(WORLD_W - 3, px2))
        py2 = max(2, min(WORLD_H - 3, py2))
        area_ok = True
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = py2 + dr, px2 + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    area_ok = False
                elif not em[rr, rc] and not pm[rr, rc]:
                    area_ok = False
        if area_ok:
            return (Tool.COALPOWER, px2, py2)

    # Step 8: Third road column further right for bigger cities
    if pop > 400:
        road_col3 = road_col + 6
        right_zone_col3 = road_col3 + 2
        road_col3 = max(2, min(WORLD_W - 3, road_col3))
        right_zone_col3 = max(3, min(WORLD_W - 4, right_zone_col3))
        road3_set = set(r for r in range(WORLD_H) if rm[r, road_col3])

        # Wire from existing spine to road_col3
        for wr in sorted(wire_rows, key=lambda r: abs(r - cy)):
            if not (tmin <= wr <= tmax):
                continue
            for wc in range(wire_col + 1, road_col3):
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc] and not wm[wr, wc]:
                    break

        for wr in sorted(wire_rows, key=lambda r: abs(r - cy)):
            if tmin <= wr <= tmax and wr not in road3_set:
                # wire coverage check
                wire_here = any(wm[wr, wc] for wc in range(wire_col, road_col3 + 1))
                if wire_here and 0 <= road_col3 < WORLD_W and em[wr, road_col3]:
                    return (Tool.ROAD, road_col3, wr)

        for zr in sorted(wire_rows, key=lambda r: abs(r - cy)):
            if not (tmin <= zr <= tmax):
                continue
            road_near = any(abs(zr - rr) <= 1 for rr in road3_set)
            if road_near:
                if 1 <= zr <= WORLD_H - 2 and 1 <= right_zone_col3 <= WORLD_W - 2:
                    if not zone_too_close(zr, right_zone_col3) and zone_area_free(zr, right_zone_col3):
                        return (pick_tool(), right_zone_col3, zr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Place coal power plant
    - Grow wire spine from plant, reading current wire positions each step
    - Build roads adjacent to wire, reading current road positions
    - Place zones where power+road already exist
    - Expand based on current population
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    pop = obs.city_pop

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # --- Phase 1: Place coal power plant near center-left ---
    if not np.any(pm):
        return (Tool.COALPOWER, cx - 8, cy)

    # Find plant location
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Wire spine runs vertically at plant_cx + 4
    wire_col = plant_cx + 4
    wire_col = max(3, min(WORLD_W - 4, wire_col))

    # Road columns: one left, one right of wire spine
    road_col_L = wire_col - 4
    road_col_R = wire_col + 4
    road_col_L = max(2, min(WORLD_W - 3, road_col_L))
    road_col_R = max(2, min(WORLD_W - 3, road_col_R))

    # Zone columns
    zone_col_L = road_col_L - 3
    zone_col_R = road_col_R + 3
    zone_col_L = max(2, min(WORLD_W - 3, zone_col_L))
    zone_col_R = max(2, min(WORLD_W - 3, zone_col_R))

    # Determine spine extent based on pop
    if pop < 100:
        spine_half = 8
    elif pop < 300:
        spine_half = 14
    elif pop < 600:
        spine_half = 20
    elif pop < 1000:
        spine_half = 28
    else:
        spine_half = 36

    spine_top = max(2, cy - spine_half)
    spine_bot = min(WORLD_H - 3, cy + spine_half)

    # Read current wire rows on spine
    wire_rows_set = set(r for r in range(WORLD_H) if wm[r, wire_col])

    # --- Phase 2: Seed wire adjacent to plant if none ---
    if not wire_rows_set:
        # Place wire right next to plant
        for dr in range(0, 8):
            for nr in [plant_cy + dr, plant_cy - dr]:
                if 0 <= nr < WORLD_H:
                    if em[nr, wire_col]:
                        return (Tool.WIRE, wire_col, nr)
        return None

    min_wr = min(wire_rows_set)
    max_wr = max(wire_rows_set)

    # --- Phase 3: Extend wire spine toward targets ---
    # Extend downward
    if max_wr < spine_bot:
        nr = max_wr + 1
        if nr < WORLD_H and not pm[nr, wire_col] and em[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)

    # Extend upward
    if min_wr > spine_top:
        nr = min_wr - 1
        if nr >= 0 and not pm[nr, wire_col] and em[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)

    # Current wire extent
    wire_rows = sorted(wire_rows_set)

    # --- Phase 4: Build left road column alongside wire ---
    for wr in wire_rows:
        if 0 <= wr < WORLD_H and 0 <= road_col_L < WORLD_W:
            if not rm[wr, road_col_L] and em[wr, road_col_L] and not pm[wr, road_col_L]:
                return (Tool.ROAD, road_col_L, wr)

    # --- Phase 5: Build right road column alongside wire ---
    for wr in wire_rows:
        if 0 <= wr < WORLD_H and 0 <= road_col_R < WORLD_W:
            if not rm[wr, road_col_R] and em[wr, road_col_R] and not pm[wr, road_col_R]:
                return (Tool.ROAD, road_col_R, wr)

    # --- Phase 6: Lay lateral wires from spine to zone columns ---
    # Only do rows where wire exists on spine
    for wr in wire_rows:
        # Left lateral: spine -> left zone col
        for wc in range(wire_col - 1, zone_col_L - 1, -1):
            if not (0 <= wc < WORLD_W):
                break
            if pm[wr, wc]:
                break
            if wm[wr, wc]:
                break  # already wired
            if rm[wr, wc]:
                break  # road blocks wire path (skip)
            if em[wr, wc]:
                return (Tool.WIRE, wc, wr)
            else:
                break

        # Right lateral: spine -> right zone col
        for wc in range(wire_col + 1, zone_col_R + 2):
            if not (0 <= wc < WORLD_W):
                break
            if pm[wr, wc]:
                break
            if wm[wr, wc]:
                break
            if rm[wr, wc]:
                break
            if em[wr, wc]:
                return (Tool.WIRE, wc, wr)
            else:
                break

    # --- Phase 7: Place zones where road + wire nearby ---
    all_zone = resm | comm | indm

    def zone_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone[rr, rc]:
                    return False
        return True

    def zone_exists(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone[rr, rc]:
                        return True
        return False

    def wire_near(zr, zc, r=5):
        r0, r1 = max(0, zr-r), min(WORLD_H, zr+r+1)
        c0, c1 = max(0, zc-r), min(WORLD_W, zc+r+1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def road_near(zr, zc, r=4):
        r0, r1 = max(0, zr-r), min(WORLD_H, zr+r+1)
        c0, c1 = max(0, zc-r), min(WORLD_W, zc+r+1)
        return np.any(rm[r0:r1, c0:c1])

    # Try placing zones every 3 rows along the wire extent
    zone_rows = list(range(max(2, min_wr + 1), min(WORLD_H - 2, max_wr), 3))

    left_road_rows = set(r for r in range(WORLD_H) if rm[r, road_col_L])
    right_road_rows = set(r for r in range(WORLD_H) if rm[r, road_col_R])

    for zr in zone_rows:
        for (zc, road_rows) in [(zone_col_L, left_road_rows), (zone_col_R, right_road_rows)]:
            road_adj = any(abs(zr - rr) <= 2 for rr in road_rows)
            wire_adj = any(abs(zr - wr) <= 3 for wr in wire_rows)
            if road_adj and wire_adj:
                if not zone_exists(zr, zc) and zone_ok(zr, zc):
                    if wire_near(zr, zc) and road_near(zr, zc):
                        return (pick_tool(), zc, zr)

        # Also try inner columns between road and spine
        for inner_zc in [road_col_L + 2, road_col_R - 2]:
            inner_zc = max(2, min(WORLD_W - 3, inner_zc))
            if inner_zc == wire_col or inner_zc == road_col_L or inner_zc == road_col_R:
                continue
            if any(abs(zr - wr) <= 2 for wr in wire_rows):
                if not zone_exists(zr, inner_zc) and zone_ok(zr, inner_zc):
                    if wire_near(zr, inner_zc, 4) and road_near(zr, inner_zc, 5):
                        return (pick_tool(), inner_zc, zr)

    # --- Phase 8: Second power plant if population warrants ---
    plant_tile_count = int(np.sum(pm))
    if pop > 400 and plant_tile_count < 16:
        px2 = plant_cx + 16
        py2 = plant_cy
        if 2 <= px2 <= WORLD_W - 5 and 2 <= py2 <= WORLD_H - 5:
            if em[py2, px2]:
                return (Tool.COALPOWER, px2, py2)

    # --- Phase 9: Horizontal connector roads at top/bottom of coverage ---
    if pop > 200 and wire_rows:
        for h_row in [min_wr, max_wr]:
            if 0 <= h_row < WORLD_H:
                for rc in range(min(road_col_L, zone_col_L) - 1,
                                max(road_col_R, zone_col_R) + 2):
                    if 0 <= rc < WORLD_W and em[h_row, rc] and not pm[h_row, rc] and not wm[h_row, rc]:
                        return (Tool.ROAD, rc, h_row)

    # --- Phase 10: Far outer zone columns for large pop ---
    if pop > 500:
        far_L = zone_col_L - 4
        far_R = zone_col_R + 4
        for fzc in [far_L, far_R]:
            if 2 <= fzc <= WORLD_W - 3:
                for zr in zone_rows:
                    if not zone_exists(zr, fzc) and zone_ok(zr, fzc):
                        if road_near(zr, fzc, 6) and wire_near(zr, fzc, 8):
                            return (pick_tool(), fzc, zr)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder.
    Each step reads the tile_map and reacts to current state.

    Strategy:
    1. Place coal power plant if none exists
    2. Build wire spine from plant outward (vertical)
    3. Build road columns adjacent to wire
    4. Place zones adjacent to roads with wire nearby
    5. Expand horizontally as population grows
    6. Add services and second plant when needed
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    # Cluster center
    cx, cy = 55, 50

    has_plant = np.any(pm)
    has_wire = np.any(wm)
    has_road = np.any(rm)

    # Phase 1: Place coal power plant
    plant_cx, plant_cy = 47, cy
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Find actual plant center
    plant_ys, plant_xs = np.where(pm)
    px = int(np.median(plant_xs))
    py = int(np.median(plant_ys))

    # Gather current positions
    wire_positions = set(zip(map(int, np.where(wm)[0]), map(int, np.where(wm)[1]))) if has_wire else set()
    road_positions = set(zip(map(int, np.where(rm)[0]), map(int, np.where(rm)[1]))) if has_road else set()
    res_pos = set(zip(map(int, np.where(resm)[0]), map(int, np.where(resm)[1])))
    com_pos = set(zip(map(int, np.where(comm)[0]), map(int, np.where(comm)[1])))
    ind_pos = set(zip(map(int, np.where(indm)[0]), map(int, np.where(indm)[1])))
    all_zones = res_pos | com_pos | ind_pos

    res_count = len(res_pos)
    com_count = len(com_pos)
    ind_count = len(ind_pos)
    total_zones = res_count + com_count + ind_count + 1

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Wire spine column (just right of plant)
    wire_col = px + 2
    # Road columns flanking wire
    road_col_r = wire_col + 1
    road_col_l = wire_col - 1
    # Zone columns
    zone_col_r = road_col_r + 3
    zone_col_l = road_col_l - 3

    # Vertical span based on population
    base_span = 12
    extra_span = min(28, obs.city_pop // 20)
    target_span = base_span + extra_span
    tmin = max(2, cy - target_span)
    tmax = min(WORLD_H - 3, cy + target_span)

    # Phase 2: Build wire spine vertically from plant
    wire_rows_main = sorted(r for (r, c) in wire_positions if c == wire_col)

    if not wire_rows_main:
        # Start wire adjacent to plant
        for dy in range(-2, 3):
            wy = py + dy
            if in_bounds(wire_col, wy) and em[wy, wire_col]:
                return (Tool.WIRE, wire_col, wy)
    else:
        min_wr = min(wire_rows_main)
        max_wr = max(wire_rows_main)
        # Extend downward
        if max_wr < tmax:
            nr = max_wr + 1
            if in_bounds(wire_col, nr) and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if min_wr > tmin:
            nr = min_wr - 1
            if in_bounds(wire_col, nr) and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    wire_rows_set = set(wire_rows_main)

    # Phase 3: Build road columns alongside wire
    if wire_rows_main:
        # Right road column
        road_rows_r = set(r for (r, c) in road_positions if c == road_col_r)
        for wr in wire_rows_main:
            if wr not in road_rows_r and in_bounds(road_col_r, wr):
                if em[wr, road_col_r] and not pm[wr, road_col_r]:
                    return (Tool.ROAD, road_col_r, wr)
        # Left road column
        road_rows_l = set(r for (r, c) in road_positions if c == road_col_l)
        for wr in wire_rows_main:
            if wr not in road_rows_l and in_bounds(road_col_l, wr):
                if em[wr, road_col_l] and not pm[wr, road_col_l]:
                    return (Tool.ROAD, road_col_l, wr)

    # Helper: check if 3x3 area is free for a zone
    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not in_bounds(rc, rr):
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def no_zone_nearby(zr, zc, dist=2):
        return not any(abs(zr - pr) <= dist and abs(zc - pc) <= dist for (pr, pc) in all_zones)

    def choose_tool():
        # Aim for ~50% R, ~25% C, ~25% I
        if ind_count * 4 < total_zones:
            return Tool.INDUSTRIAL
        if com_count * 4 < total_zones:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Phase 4: Place zones adjacent to roads with wire nearby
    road_rows_r2 = set(r for (r, c) in road_positions if c == road_col_r)
    road_rows_l2 = set(r for (r, c) in road_positions if c == road_col_l)

    if wire_rows_main:
        for zr in sorted(wire_rows_main):
            wire_close = any(abs(zr - wr) <= 2 for wr in wire_rows_set)
            if not wire_close:
                continue
            # Right zone column
            road_close_r = any(abs(zr - rr) <= 2 for rr in road_rows_r2)
            if road_close_r:
                zc = zone_col_r
                if in_bounds(zc, zr) and 1 < zr < WORLD_H - 2 and 1 < zc < WORLD_W - 2:
                    if no_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                        return (choose_tool(), zc, zr)
            # Left zone column
            road_close_l = any(abs(zr - rr) <= 2 for rr in road_rows_l2)
            if road_close_l:
                zc = zone_col_l
                if in_bounds(zc, zr) and 1 < zr < WORLD_H - 2 and 1 < zc < WORLD_W - 2:
                    if no_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                        return (choose_tool(), zc, zr)

    # Phase 5: Lateral connections (road/wire) between spine and zone columns
    if wire_rows_main:
        for wr in wire_rows_main:
            # Lateral road to right zone col
            for rc in range(road_col_r + 1, zone_col_r):
                if in_bounds(rc, wr) and em[wr, rc] and not pm[wr, rc]:
                    return (Tool.ROAD, rc, wr)
            # Lateral wire to left zone col
            for wc in range(wire_col - 1, zone_col_l - 1, -1):
                if in_bounds(wc, wr) and em[wr, wc] and not pm[wr, wc]:
                    return (Tool.WIRE, wc, wr)

    # Phase 6: Second expansion cluster when population growing
    if obs.city_pop > 150:
        wire_col2 = zone_col_r + 4
        road_col_r2 = wire_col2 + 1
        zone_col_r2 = road_col_r2 + 3

        wire_rows_col2 = sorted(r for (r, c) in wire_positions if c == wire_col2)

        if not wire_rows_col2:
            # Connect horizontally from main wire spine at cy
            for wc in range(wire_col + 1, wire_col2 + 1):
                if in_bounds(wc, cy) and (em[cy, wc] or wm[cy, wc]) and not pm[cy, wc]:
                    return (Tool.WIRE, wc, cy)
        else:
            min_wr2 = min(wire_rows_col2)
            max_wr2 = max(wire_rows_col2)
            if max_wr2 < tmax:
                nr = max_wr2 + 1
                if in_bounds(wire_col2, nr) and (em[nr, wire_col2] or wm[nr, wire_col2]):
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > tmin:
                nr = min_wr2 - 1
                if in_bounds(wire_col2, nr) and (em[nr, wire_col2] or wm[nr, wire_col2]):
                    return (Tool.WIRE, wire_col2, nr)

            # Road column for second cluster
            road_rows_r3 = set(r for (r, c) in road_positions if c == road_col_r2)
            for wr in wire_rows_col2:
                if wr not in road_rows_r3 and in_bounds(road_col_r2, wr):
                    if em[wr, road_col_r2] and not pm[wr, road_col_r2]:
                        return (Tool.ROAD, road_col_r2, wr)

            # Lateral roads
            for wr in wire_rows_col2:
                for rc in range(road_col_r2 + 1, zone_col_r2):
                    if in_bounds(rc, wr) and em[wr, rc] and not pm[wr, rc]:
                        return (Tool.ROAD, rc, wr)

            # Zones for second cluster
            road_rows_r3_list = sorted(r for (r, c) in road_positions if c == road_col_r2)
            for zr in sorted(wire_rows_col2):
                wire_close2 = any(abs(zr - wr) <= 2 for wr in wire_rows_col2)
                road_close2 = any(abs(zr - rr) <= 2 for rr in road_rows_r3_list)
                if wire_close2 and road_close2:
                    zc = zone_col_r2
                    if in_bounds(zc, zr) and 1 < zr < WORLD_H - 2 and 1 < zc < WORLD_W - 2:
                        if no_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                            return (choose_tool(), zc, zr)

    # Phase 7: Third expansion cluster (left side)
    if obs.city_pop > 400:
        wire_col3 = zone_col_l - 4
        road_col_l3 = wire_col3 - 1
        zone_col_l3 = road_col_l3 - 3

        wire_rows_col3 = sorted(r for (r, c) in wire_positions if c == wire_col3)

        if not wire_rows_col3:
            for wc in range(wire_col - 1, wire_col3 - 1, -1):
                if in_bounds(wc, cy) and (em[cy, wc] or wm[cy, wc]) and not pm[cy, wc]:
                    return (Tool.WIRE, wc, cy)
        else:
            min_wr3 = min(wire_rows_col3)
            max_wr3 = max(wire_rows_col3)
            if max_wr3 < tmax:
                nr = max_wr3 + 1
                if in_bounds(wire_col3, nr) and (em[nr, wire_col3] or wm[nr, wire_col3]):
                    return (Tool.WIRE, wire_col3, nr)
            if min_wr3 > tmin:
                nr = min_wr3 - 1
                if in_bounds(wire_col3, nr) and (em[nr, wire_col3] or wm[nr, wire_col3]):
                    return (Tool.WIRE, wire_col3, nr)

            road_rows_l4 = set(r for (r, c) in road_positions if c == road_col_l3)
            for wr in wire_rows_col3:
                if wr not in road_rows_l4 and in_bounds(road_col_l3, wr):
                    if em[wr, road_col_l3] and not pm[wr, road_col_l3]:
                        return (Tool.ROAD, road_col_l3, wr)

            road_rows_l4_list = sorted(r for (r, c) in road_positions if c == road_col_l3)
            for zr in sorted(wire_rows_col3):
                wire_close3 = any(abs(zr - wr) <= 2 for wr in wire_rows_col3)
                road_close3 = any(abs(zr - rr) <= 2 for rr in road_rows_l4_list)
                if wire_close3 and road_close3:
                    zc = zone_col_l3
                    if in_bounds(zc, zr) and 1 < zr < WORLD_H - 2 and 1 < zc < WORLD_W - 2:
                        if no_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                            return (choose_tool(), zc, zr)

    # Phase 8: Add second coal plant if population is large and powered zones low
    if obs.city_pop > 600 and not state.get("second_plant", False):
        p2x, p2y = px + 35, cy
        clear2 = all(
            in_bounds(p2x + dc, p2y + dr) and em[p2y + dr, p2x + dc]
            for dr in [-1, 0, 1] for dc in [-1, 0, 1]
        )
        if clear2:
            state["second_plant"] = True
            return (Tool.COALPOWER, p2x, p2y)

    # Phase 9: Services when population is big enough
    if obs.city_pop > 200:
        fx, fy = wire_col + 2, cy - target_span - 3
        if in_bounds(fx, fy) and em[fy, fx] and not state.get("fire1", False):
            state["fire1"] = True
            return (Tool.FIRESTATION, fx, fy)
        px2, py2 = wire_col + 2, cy + target_span + 3
        if in_bounds(px2, py2) and em[py2, px2] and not state.get("police1", False):
            state["police1"] = True
            return (Tool.POLICESTATION, px2, py2)

    # Phase 10: Reactive fill - find empty spots near road and wire
    # Build dilated masks reactively
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand = em & nbr_road & nbr_wire
    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        # Prioritize candidates near center
        dists = np.abs(cxs - cx) + np.abs(cys - cy)
        order = np.argsort(dists)
        for idx in order[:20]:
            zx, zy = int(cxs[idx]), int(cys[idx])
            if zone_area_free(zy, zx) and no_zone_nearby(zy, zx):
                return (choose_tool(), zx, zy)

    return None

def act(obs, state):
    """
    Horizontal spine variant: wire runs horizontally, roads above/below,
    zones placed in rows above and below the roads.
    Multiple clusters along horizontal spine for wider coverage.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Use state to track build queue
    if 'phase' not in state:
        state['phase'] = 0
        state['step'] = 0

    state['step'] += 1

    # Horizontal layout:
    # wire_row: horizontal wire spine
    # road_row_u: road row above wire
    # road_row_d: road row below wire
    # zone_row_u: zone centers above road_u
    # zone_row_d: zone centers below road_d
    # plant at left side of spine

    wire_row = cy
    road_row_u = wire_row - 1
    road_row_d = wire_row + 1
    zone_row_u = road_row_u - 2  # zone center 2 above road (zones are 3x3, center at road-2)
    zone_row_d = road_row_d + 2  # zone center 2 below road

    # Clamp rows
    wire_row = max(3, min(WORLD_H - 4, wire_row))
    road_row_u = max(1, min(WORLD_H - 2, road_row_u))
    road_row_d = max(1, min(WORLD_H - 2, road_row_d))
    zone_row_u = max(1, min(WORLD_H - 2, zone_row_u))
    zone_row_d = max(1, min(WORLD_H - 2, zone_row_d))

    # Power plant placement: top-left area, center y
    plant_x = 10
    plant_y = wire_row

    # Phase 1: Place coal power plant
    if not np.any(pm):
        return (Tool.COALPOWER, plant_x, plant_y)

    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Spine extent based on population
    if obs.city_pop < 50:
        spine_extent = 15
    elif obs.city_pop < 200:
        spine_extent = 25
    elif obs.city_pop < 500:
        spine_extent = 40
    else:
        spine_extent = 55

    spine_left = max(plant_cx + 4, cx - spine_extent)
    spine_right = min(WORLD_W - 3, cx + spine_extent)

    wire_cols = set(c for c in range(WORLD_W) if wm[wire_row, c])
    road_cols_u = set(c for c in range(WORLD_W) if rm[road_row_u, c])
    road_cols_d = set(c for c in range(WORLD_W) if rm[road_row_d, c])

    # Phase 2: Build wire from plant rightward
    # First connect plant to wire row with a short wire
    if not wire_cols:
        # Wire starts right of plant
        start_c = plant_cx + 4
        if 0 <= start_c < WORLD_W:
            if em[wire_row, start_c] or wm[wire_row, start_c]:
                return (Tool.WIRE, start_c, wire_row)
        return None

    # Find current wire extent
    min_wc = min(wire_cols)
    max_wc = max(wire_cols)

    # Phase 3: Extend wire rightward
    if max_wc < spine_right:
        nc = max_wc + 1
        if nc < WORLD_W and not pm[wire_row, nc]:
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # Phase 4: Extend wire leftward toward plant
    if min_wc > spine_left:
        nc = min_wc - 1
        if nc >= 0 and not pm[wire_row, nc]:
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # Phase 5: Build roads above and below wire spine
    for wc in sorted(wire_cols):
        if wc < spine_left or wc > spine_right:
            continue
        # Road above wire
        if wc not in road_cols_u and 0 <= road_row_u < WORLD_H:
            if em[road_row_u, wc]:
                return (Tool.ROAD, wc, road_row_u)
        # Road below wire
        if wc not in road_cols_d and 0 <= road_row_d < WORLD_H:
            if em[road_row_d, wc]:
                return (Tool.ROAD, wc, road_row_d)

    all_zone_mask = resm | comm | indm

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_at(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def pick_tool(zc):
        # Vary zone type based on column position for diversity
        t = max(1, total_zones)
        seg = (zc - spine_left) // 6
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Phase 6: Place zones along both sides of roads
    # Zones every 3 columns along spine
    for zc in range(int(spine_left) + 1, int(spine_right), 3):
        # Check road access
        road_near_u = any(abs(zc - rc) <= 1 for rc in road_cols_u)
        road_near_d = any(abs(zc - rc) <= 1 for rc in road_cols_d)

        # Upper zones
        if road_near_u and 1 <= zone_row_u <= WORLD_H - 2:
            if not zone_at(zone_row_u, zc) and zone_area_ok(zone_row_u, zc):
                return (pick_tool(zc), zc, zone_row_u)

        # Lower zones
        if road_near_d and 1 <= zone_row_d <= WORLD_H - 2:
            if not zone_at(zone_row_d, zc) and zone_area_ok(zone_row_d, zc):
                return (pick_tool(zc + 1), zc, zone_row_d)

    # Phase 7: Add second power plant when population grows
    if obs.city_pop > 300 and int(np.sum(pm)) < 9:
        px2 = plant_cx + 30
        py2 = plant_cy
        if 2 <= px2 <= WORLD_W - 3 and 2 <= py2 <= WORLD_H - 3:
            area_ok = True
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    rr, rc = py2 + dr, px2 + dc
                    if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                        if not em[rr, rc]:
                            area_ok = False
            if area_ok:
                return (Tool.COALPOWER, px2, py2)

    # Phase 8: Second horizontal cluster - wire row shifted down by 8
    if obs.city_pop > 200:
        wire_row2 = wire_row + 8
        road_row2_u = wire_row2 - 1
        road_row2_d = wire_row2 + 1
        zone_row2_u = road_row2_u - 2
        zone_row2_d = road_row2_d + 2

        wire_row2 = max(3, min(WORLD_H - 4, wire_row2))
        road_row2_u = max(1, min(WORLD_H - 2, road_row2_u))
        road_row2_d = max(1, min(WORLD_H - 2, road_row2_d))
        zone_row2_u = max(1, min(WORLD_H - 2, zone_row2_u))
        zone_row2_d = max(1, min(WORLD_H - 2, zone_row2_d))

        wire_cols2 = set(c for c in range(WORLD_W) if wm[wire_row2, c])
        road_cols2_u = set(c for c in range(WORLD_W) if rm[road_row2_u, c])
        road_cols2_d = set(c for c in range(WORLD_W) if rm[road_row2_d, c])

        # Connect second wire row to first with vertical wire
        if not wire_cols2:
            # Connect vertically from wire_row down to wire_row2 at cx
            for wr in range(wire_row + 1, wire_row2 + 1):
                if not wm[wr, cx] and (em[wr, cx] or wm[wr, cx]):
                    return (Tool.WIRE, cx, wr)

        if wire_cols2:
            min_wc2 = min(wire_cols2)
            max_wc2 = max(wire_cols2)
            spine2_right = min(WORLD_W - 3, cx + spine_extent)
            spine2_left = max(3, cx - spine_extent)

            if max_wc2 < spine2_right:
                nc = max_wc2 + 1
                if nc < WORLD_W and not pm[wire_row2, nc]:
                    if em[wire_row2, nc] or wm[wire_row2, nc]:
                        return (Tool.WIRE, nc, wire_row2)

            if min_wc2 > spine2_left:
                nc = min_wc2 - 1
                if nc >= 0 and not pm[wire_row2, nc]:
                    if em[wire_row2, nc] or wm[wire_row2, nc]:
                        return (Tool.WIRE, nc, wire_row2)

            for wc in sorted(wire_cols2):
                if wc < spine2_left or wc > spine2_right:
                    continue
                if wc not in road_cols2_u and 0 <= road_row2_u < WORLD_H:
                    if em[road_row2_u, wc]:
                        return (Tool.ROAD, wc, road_row2_u)
                if wc not in road_cols2_d and 0 <= road_row2_d < WORLD_H:
                    if em[road_row2_d, wc]:
                        return (Tool.ROAD, wc, road_row2_d)

            for zc in range(int(spine2_left) + 1, int(spine2_right), 3):
                road_near2_u = any(abs(zc - rc) <= 1 for rc in road_cols2_u)
                road_near2_d = any(abs(zc - rc) <= 1 for rc in road_cols2_d)

                if road_near2_u and 1 <= zone_row2_u <= WORLD_H - 2:
                    if not zone_at(zone_row2_u, zc) and zone_area_ok(zone_row2_u, zc):
                        return (pick_tool(zc + 2), zc, zone_row2_u)

                if road_near2_d and 1 <= zone_row2_d <= WORLD_H - 2:
                    if not zone_at(zone_row2_d, zc) and zone_area_ok(zone_row2_d, zc):
                        return (pick_tool(zc + 3), zc, zone_row2_d)

    # Phase 9: Third cluster above main spine
    if obs.city_pop > 400:
        wire_row3 = wire_row - 8
        road_row3_u = wire_row3 - 1
        road_row3_d = wire_row3 + 1
        zone_row3_u = road_row3_u - 2
        zone_row3_d = road_row3_d + 2

        wire_row3 = max(3, min(WORLD_H - 4, wire_row3))
        road_row3_u = max(1, min(WORLD_H - 2, road_row3_u))
        road_row3_d = max(1, min(WORLD_H - 2, road_row3_d))
        zone_row3_u = max(1, min(WORLD_H - 2, zone_row3_u))
        zone_row3_d = max(1, min(WORLD_H - 2, zone_row3_d))

        wire_cols3 = set(c for c in range(WORLD_W) if wm[wire_row3, c])
        road_cols3_u = set(c for c in range(WORLD_W) if rm[road_row3_u, c])
        road_cols3_d = set(c for c in range(WORLD_W) if rm[road_row3_d, c])

        if not wire_cols3:
            for wr in range(wire_row3, wire_row):
                if not wm[wr, cx] and (em[wr, cx] or wm[wr, cx]):
                    return (Tool.WIRE, cx, wr)

        if wire_cols3:
            min_wc3 = min(wire_cols3)
            max_wc3 = max(wire_cols3)
            spine3_right = min(WORLD_W - 3, cx + spine_extent)
            spine3_left = max(3, cx - spine_extent)

            if max_wc3 < spine3_right:
                nc = max_wc3 + 1
                if nc < WORLD_W and not pm[wire_row3, nc]:
                    if em[wire_row3, nc] or wm[wire_row3, nc]:
                        return (Tool.WIRE, nc, wire_row3)

            if min_wc3 > spine3_left:
                nc = min_wc3 - 1
                if nc >= 0 and not pm[wire_row3, nc]:
                    if em[wire_row3, nc] or wm[wire_row3, nc]:
                        return (Tool.WIRE, nc, wire_row3)

            for wc in sorted(wire_cols3):
                if wc < spine3_left or wc > spine3_right:
                    continue
                if wc not in road_cols3_u and 0 <= road_row3_u < WORLD_H:
                    if em[road_row3_u, wc]:
                        return (Tool.ROAD, wc, road_row3_u)
                if wc not in road_cols3_d and 0 <= road_row3_d < WORLD_H:
                    if em[road_row3_d, wc]:
                        return (Tool.ROAD, wc, road_row3_d)

            for zc in range(int(spine3_left) + 1, int(spine3_right), 3):
                road_near3_u = any(abs(zc - rc) <= 1 for rc in road_cols3_u)
                road_near3_d = any(abs(zc - rc) <= 1 for rc in road_cols3_d)

                if road_near3_u and 1 <= zone_row3_u <= WORLD_H - 2:
                    if not zone_at(zone_row3_u, zc) and zone_area_ok(zone_row3_u, zc):
                        return (pick_tool(zc), zc, zone_row3_u)

                if road_near3_d and 1 <= zone_row3_d <= WORLD_H - 2:
                    if not zone_at(zone_row3_d, zc) and zone_area_ok(zone_row3_d, zc):
                        return (pick_tool(zc + 1), zc, zone_row3_d)

    return None

def act(obs, state):
    """
    Revised city builder with a cleaner layout:
    1. Place coal power plant at a fixed spot
    2. Build wire spine rightward from plant
    3. Build two parallel horizontal roads (above/below wire)
    4. Place zones in a balanced R/C/I mix between and beyond roads
    5. Add vertical connector roads
    6. Add services when population grows
    Strategy changes vs parent:
    - Wire goes horizontally first (simpler, more direct)
    - Zones placed immediately adjacent to roads (within 2 tiles)
    - More balanced zone mix (R/C/I = 2:1:1)
    - Second cluster further right
    - Services placed earlier
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    # Initialize state
    if 'phase' not in state:
        state['phase'] = 0
        state['action_queue'] = []

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Build a comprehensive action queue on first call
    # Layout:
    #   Plant at (20, 50)
    #   Wire: row 50, cols 20->90
    #   Top road: row 46, cols 22->90
    #   Bot road: row 54, cols 22->90
    #   Vertical roads every 6 cols connecting top/bot roads
    #   Zones: rows 43,40,37 (above top road) and 57,60,63 (below bot road)
    #   Cols: 24,30,36,42,48,54,60,66,72,78,84

    PLANT_X, PLANT_Y = 20, 50
    WIRE_ROW = 50
    TOP_ROAD_ROW = 46
    BOT_ROAD_ROW = 54
    COL_START = 23
    COL_END = 90

    zone_cols = list(range(25, COL_END, 6))
    zone_rows_top = [43, 40, 37]
    zone_rows_bot = [57, 60, 63]

    has_plant = np.any(pm)

    # Phase 1: Power plant
    if not has_plant:
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    wire_set = set(zip(*np.where(wm))) if np.any(wm) else set()
    road_set = set(zip(*np.where(rm))) if np.any(rm) else set()
    res_ys, res_xs = np.where(resm)
    com_ys, com_xs = np.where(comm)
    ind_ys, ind_xs = np.where(indm)
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Phase 2: Wire spine horizontal
    for wx in range(PLANT_X + 2, COL_END + 1):
        if not in_bounds(wx, WIRE_ROW):
            break
        if (WIRE_ROW, wx) not in wire_set and em[WIRE_ROW, wx] and not pm[WIRE_ROW, wx]:
            return (Tool.WIRE, wx, WIRE_ROW)

    # Phase 3: Top horizontal road
    for rx in range(COL_START, COL_END + 1):
        if not in_bounds(rx, TOP_ROAD_ROW):
            break
        if (TOP_ROAD_ROW, rx) not in road_set and not pm[TOP_ROAD_ROW, rx]:
            return (Tool.ROAD, rx, TOP_ROAD_ROW)

    # Phase 4: Bottom horizontal road
    for rx in range(COL_START, COL_END + 1):
        if not in_bounds(rx, BOT_ROAD_ROW):
            break
        if (BOT_ROAD_ROW, rx) not in road_set and not pm[BOT_ROAD_ROW, rx]:
            return (Tool.ROAD, rx, BOT_ROAD_ROW)

    # Phase 5: Vertical connector roads every 6 cols
    for vc in range(COL_START, COL_END + 1, 6):
        for vr in range(TOP_ROAD_ROW, BOT_ROAD_ROW + 1):
            if not in_bounds(vc, vr):
                continue
            if (vr, vc) not in road_set and not pm[vr, vc]:
                return (Tool.ROAD, vc, vr)

    # Helper: check if zone position has road nearby (within 3)
    def has_road_near(zx, zy, r=3):
        for dr in range(-r, r + 1):
            for dc in range(-r, r + 1):
                if (zy + dr, zx + dc) in road_set:
                    return True
        return False

    # Helper: check wire/plant nearby
    def has_wire_near(zx, zy, r=6):
        for dr in range(-r, r + 1):
            for dc in range(-r, r + 1):
                nr, nc = zy + dr, zx + dc
                if (nr, nc) in wire_set:
                    return True
                if in_bounds(nc, nr) and pm[nr, nc]:
                    return True
        return False

    # Helper: zone area is clear
    zone_set = set(zip(
        np.concatenate([res_ys, com_ys, ind_ys]).tolist(),
        np.concatenate([res_xs, com_xs, ind_xs]).tolist()
    )) if total_zones > 0 else set()

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    # Balanced zone picker: 2R:1C:1I ratio
    def pick_tool():
        t = max(total_zones, 1)
        r_ratio = res_count / t
        c_ratio = com_count / t
        i_ratio = ind_count / t
        if c_ratio < 0.25:
            return Tool.COMMERCIAL
        if i_ratio < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Phase 6: Place zones above top road
    for zr in zone_rows_top:
        for zc in zone_cols:
            if not in_bounds(zc, zr):
                continue
            if not (2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3):
                continue
            if zone_clear(zc, zr) and has_road_near(zc, zr) and has_wire_near(zc, zr):
                return (pick_tool(), zc, zr)

    # Phase 7: Place zones below bot road
    for zr in zone_rows_bot:
        for zc in zone_cols:
            if not in_bounds(zc, zr):
                continue
            if not (2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3):
                continue
            if zone_clear(zc, zr) and has_road_near(zc, zr) and has_wire_near(zc, zr):
                return (pick_tool(), zc, zr)

    # Phase 8: Services when population grows
    plant_ys, plant_xs = np.where(pm)
    px = int(np.mean(plant_xs)) if len(plant_xs) else PLANT_X
    py = int(np.mean(plant_ys)) if len(plant_ys) else PLANT_Y

    if obs.city_pop > 50:
        fx, fy = px + 3, py - 8
        if in_bounds(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)

    if obs.city_pop > 100:
        fx2, fy2 = px + 3, py + 8
        if in_bounds(fx2, fy2) and em[fy2, fx2]:
            return (Tool.POLICESTATION, fx2, fy2)

    # Phase 9: Second power plant if needed
    if obs.city_pop > 200 and np.sum(pm) < 9:
        nx2, ny2 = 70, 50
        if in_bounds(nx2, ny2) and em[ny2, nx2]:
            return (Tool.COALPOWER, nx2, ny2)

    # Phase 10: Extend wire to second cluster area
    for wx in range(COL_END + 1, min(COL_END + 20, WORLD_W - 2)):
        if not in_bounds(wx, WIRE_ROW):
            break
        if (WIRE_ROW, wx) not in wire_set and em[WIRE_ROW, wx] and not pm[WIRE_ROW, wx]:
            return (Tool.WIRE, wx, WIRE_ROW)

    # Phase 11: Reactive zone placement using dilated road+wire masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand = em & nbr_road & nbr_wire
    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        k = int((obs.step * 13 + int(tm.sum()) % 200)) % len(cxs)
        zx, zy = int(cxs[k]), int(cys[k])
        if 2 <= zy <= WORLD_H - 3 and 2 <= zx <= WORLD_W - 3:
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # Phase 12: Extend road from frontier
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        k = int(obs.step * 11) % len(road_xs2)
        rx, ry = int(road_xs2[k]), int(road_ys2[k])
        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx + dx, ry + dy
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads current tile_map each step to decide next action
    - Builds power plant, then extends wire spine from existing wire edges
    - Builds roads adjacent to existing wire
    - Places zones adjacent to existing roads
    - Adapts to what's actually on the map
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def is_clear(x, y):
        return in_bounds(x, y) and bool(em[y, x])

    def zone_area_free(cx, cy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if not in_bounds(cx + dc, cy + dr):
                    return False
                if not bool(em[cy + dr, cx + dc]):
                    return False
        return True

    # Power plant target position
    PX, PY = 55, 50

    # Check if we have a plant
    plant_ys, plant_xs = np.where(pm)
    has_plant = len(plant_xs) > 0

    if not has_plant:
        return (Tool.COALPOWER, PX, PY)

    # Find actual plant location (centroid)
    px_actual = int(np.mean(plant_xs))
    py_actual = int(np.mean(plant_ys))

    # Count existing zones for balance
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_zone(cy):
        # Balance: aim for ~50% res, ~25% com, ~25% ind
        # More industrial in lower half
        if ind_count == 0:
            return Tool.INDUSTRIAL
        if com_count == 0:
            return Tool.COMMERCIAL
        if res_count == 0:
            return Tool.RESIDENTIAL
        # Maintain ratios
        if ind_count * 4 < total_zones:
            return Tool.INDUSTRIAL
        if com_count * 4 < total_zones:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # === STEP 1: Ensure wire spine exists and extends vertically ===
    # Wire spine: column = PX + 3
    WIRE_COL = PX + 3  # = 58

    wire_positions = list(zip(*np.where(wm))) if np.any(wm) else []
    wire_col_rows = sorted(r for (r, c) in wire_positions if c == WIRE_COL)

    # Grow span based on population
    base_half = 15
    pop_extra = min(35, obs.city_pop // 15)
    half_span = base_half + pop_extra
    tmin = max(2, PY - half_span)
    tmax = min(WORLD_H - 3, PY + half_span)

    if not wire_col_rows:
        # Start wire at plant level adjacent to plant
        if is_clear(WIRE_COL, py_actual):
            return (Tool.WIRE, WIRE_COL, py_actual)
        # Try connecting from plant
        for wc in range(px_actual + 2, WIRE_COL + 1):
            if in_bounds(wc, py_actual) and bool(em[py_actual, wc]) and not bool(pm[py_actual, wc]):
                return (Tool.WIRE, wc, py_actual)
    else:
        # Extend wire spine down
        max_wr = max(wire_col_rows)
        if max_wr < tmax:
            nr = max_wr + 1
            if is_clear(WIRE_COL, nr):
                return (Tool.WIRE, WIRE_COL, nr)
        # Extend wire spine up
        min_wr = min(wire_col_rows)
        if min_wr > tmin:
            nr = min_wr - 1
            if is_clear(WIRE_COL, nr):
                return (Tool.WIRE, WIRE_COL, nr)

    # === STEP 2: Build road columns adjacent to wire spine ===
    # Left road col: WIRE_COL - 1, Right road col: WIRE_COL + 1
    ROAD_L = WIRE_COL - 1
    ROAD_R = WIRE_COL + 1

    road_positions = set(zip(*np.where(rm))) if np.any(rm) else set()
    road_rows_L = set(r for (r, c) in road_positions if c == ROAD_L)
    road_rows_R = set(r for (r, c) in road_positions if c == ROAD_R)

    wire_col_rows_set = set(wire_col_rows)

    for wr in wire_col_rows:
        if wr < tmin or wr > tmax:
            continue
        if wr not in road_rows_L and in_bounds(ROAD_L, wr) and is_clear(ROAD_L, wr):
            return (Tool.ROAD, ROAD_L, wr)
        if wr not in road_rows_R and in_bounds(ROAD_R, wr) and is_clear(ROAD_R, wr):
            return (Tool.ROAD, ROAD_R, wr)

    # === STEP 3: Build lateral wires from spine to left zone areas ===
    # Zone columns: WIRE_COL - 4 and WIRE_COL - 7 (left), WIRE_COL + 4 and WIRE_COL + 7 (right)
    ZONE_COLS_L = [WIRE_COL - 4, WIRE_COL - 7]
    ZONE_COLS_R = [WIRE_COL + 4, WIRE_COL + 7]

    # For left zones, lay horizontal wires from WIRE_COL leftward
    for wr in wire_col_rows:
        if wr < tmin or wr > tmax:
            continue
        # Check if road is nearby for this row
        road_L_here = (wr in road_rows_L) or any(abs(wr - rr) <= 1 for rr in road_rows_L)
        road_R_here = (wr in road_rows_R) or any(abs(wr - rr) <= 1 for rr in road_rows_R)

        # Extend wire left for left zone columns
        if road_L_here:
            for wc in range(ROAD_L - 1, max(ZONE_COLS_L[-1] - 2, 0) - 1, -1):
                if not in_bounds(wc, wr):
                    break
                if bool(pm[wr, wc]):
                    break
                if bool(rm[wr, wc]):
                    break
                if not bool(wm[wr, wc]):
                    if bool(em[wr, wc]):
                        return (Tool.WIRE, wc, wr)
                    else:
                        break

        # Extend road right for right zone columns
        if road_R_here:
            for rc in range(ROAD_R + 1, min(ZONE_COLS_R[-1] + 2, WORLD_W)):
                if not in_bounds(rc, wr):
                    break
                if bool(pm[wr, rc]):
                    break
                if bool(wm[wr, rc]):
                    break
                if not bool(rm[wr, rc]):
                    if bool(em[wr, rc]):
                        return (Tool.ROAD, rc, wr)
                    else:
                        break

    # === STEP 4: Place zones adjacent to roads ===
    # Scan wire rows and try placing zones at zone columns if roads are nearby
    for wr in wire_col_rows:
        if wr < tmin or wr > tmax:
            continue
        if wr < 2 or wr >= WORLD_H - 2:
            continue

        road_L_nearby = any(abs(wr - rr) <= 1 for rr in road_rows_L)
        road_R_nearby = any(abs(wr - rr) <= 1 for rr in road_rows_R)

        # Also check for wires going left (which means power reaches left cols)
        wire_at_left = any(
            (wr, wc) in set(wire_positions) for wc in range(ROAD_L - 1, max(ZONE_COLS_L[-1] - 1, 0), -1)
        )
        road_at_right = any(
            (wr, rc) in road_positions for rc in range(ROAD_R + 1, min(ZONE_COLS_R[-1] + 2, WORLD_W))
        )

        for zc in ZONE_COLS_L:
            if in_bounds(zc, wr) and 2 <= zc < WORLD_W - 2:
                if road_L_nearby and zone_area_free(zc, wr):
                    return (pick_zone(wr), zc, wr)

        for zc in ZONE_COLS_R:
            if in_bounds(zc, wr) and 2 <= zc < WORLD_W - 2:
                if road_R_nearby and zone_area_free(zc, wr):
                    return (pick_zone(wr), zc, wr)

    # === STEP 5: Second power plant for larger cities ===
    if obs.city_pop > 200:
        P2X, P2Y = 35, 50
        plant_ys2, plant_xs2 = np.where(pm)
        has_plant2 = any(abs(px_ - P2X) <= 5 and abs(py_ - P2Y) <= 5
                        for py_, px_ in zip(plant_ys2.tolist(), plant_xs2.tolist()))
        if not has_plant2:
            # Check area is mostly empty
            if zone_area_free(P2X, P2Y):
                return (Tool.COALPOWER, P2X, P2Y)

    # === STEP 6: Services ===
    if obs.city_pop > 400:
        fx, fy = WIRE_COL + 8, PY - 12
        if in_bounds(fx, fy) and zone_area_free(fx, fy):
            return (Tool.FIRESTATION, fx, fy)

    if obs.city_pop > 600:
        px2, py2 = WIRE_COL - 10, PY + 12
        if in_bounds(px2, py2) and zone_area_free(px2, py2):
            return (Tool.POLICESTATION, px2, py2)

    # === FALLBACK: extend roads from any existing road ===
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        idx = int(obs.step * 17) % len(road_xs)
        rx, ry = int(road_xs[idx]), int(road_ys[idx])
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx, ny = rx + dx, ry + dy
            if in_bounds(nx, ny) and is_clear(nx, ny) and not bool(pm[ny, nx]):
                return (Tool.ROAD, nx, ny)

    # === FALLBACK: extend wires from any existing wire ===
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        idx = int(obs.step * 11) % len(wire_xs)
        wx, wy = int(wire_xs[idx]), int(wire_ys[idx])
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx, ny = wx + dx, wy + dy
            if in_bounds(nx, ny) and is_clear(nx, ny) and not bool(pm[ny, nx]):
                return (Tool.WIRE, nx, ny)

    return None

def act(obs, state):
    """
    Revised policy: compact grid layout with proper power connections.
    Key fixes from parent:
    - Wire runs directly FROM power plant to zones (not through roads)
    - Road grid is separate from wire grid
    - Zones placed AFTER infrastructure is confirmed
    - Simpler, more compact layout centered in map
    """
    if 'queue' not in state:
        state['queue'] = []
        state['built'] = False

    if not state['queue'] and not state['built']:
        actions = []
        state['built'] = True

        # Center of map roughly
        # Strategy: one coal plant, wire grid, road grid, then zones
        # All in a compact 30x30 area

        # === POWER PLANT at (20, 50) ===
        px, py = 20, 50
        actions.append((Tool.COALPOWER, px, py))

        # === WIRE horizontal from plant rightward ===
        # Wire at y=50 from x=22 to x=85
        for wx in range(22, 86):
            actions.append((Tool.WIRE, wx, 50))

        # === WIRE vertical branches at regular intervals ===
        # Vertical wires at x=25,30,35,40,45,50,55,60,65,70,75,80
        # going up from y=50 to y=30 and down to y=70
        wire_xs = list(range(25, 81, 5))
        for wx in wire_xs:
            for wy in range(31, 50):
                actions.append((Tool.WIRE, wx, wy))
            for wy in range(51, 70):
                actions.append((Tool.WIRE, wx, wy))

        # === ROAD GRID ===
        # Horizontal roads at y=33, 39, 45, 55, 61, 67
        road_ys = [33, 39, 45, 55, 61, 67]
        for ry in road_ys:
            for rx in range(23, 83):
                actions.append((Tool.ROAD, rx, ry))

        # Vertical roads at x=26, 32, 38, 44, 50, 56, 62, 68, 74, 80
        road_xs = list(range(26, 81, 6))
        for rx in road_xs:
            for ry in range(33, 68):
                actions.append((Tool.ROAD, rx, ry))

        # === ZONES ===
        # Place zones in 3x3 blocks (center coords) in the grid cells
        # Between horizontal roads and between vertical roads
        # Zone rows at y=36, 42, 58, 64
        # Zone cols at x=29, 35, 41, 47, 53, 59, 65, 71, 77
        zone_ys = [36, 42, 58, 64]
        zone_xs = [29, 35, 41, 47, 53, 59, 65, 71, 77]

        zone_idx = 0
        for zy in zone_ys:
            for zx in zone_xs:
                # Alternate R/C/I with heavy residential
                mod = zone_idx % 5
                if mod == 0 or mod == 1 or mod == 2:
                    tool = Tool.RESIDENTIAL
                elif mod == 3:
                    tool = Tool.COMMERCIAL
                else:
                    tool = Tool.INDUSTRIAL
                actions.append((tool, zx, zy))
                zone_idx += 1

        # === SECOND COAL PLANT for reliability ===
        actions.append((Tool.COALPOWER, 85, 50))

        # Wire from second plant leftward to connect grid
        # Already covered by main wire at y=50

        # === FIRE STATION and POLICE STATION ===
        actions.append((Tool.FIRESTATION, 50, 50))
        actions.append((Tool.POLICESTATION, 44, 50))

        # === EXTRA ZONES after services ===
        # More zones in a third cluster
        extra_ys = [36, 42, 58, 64]
        extra_xs = [30, 36, 42, 48, 54, 60, 66, 72, 78]
        # Actually place more variety
        for zy in [48, 52]:
            for zx in zone_xs:
                mod = zone_idx % 3
                if mod == 0:
                    tool = Tool.RESIDENTIAL
                elif mod == 1:
                    tool = Tool.COMMERCIAL
                else:
                    tool = Tool.INDUSTRIAL
                actions.append((tool, zx, zy))
                zone_idx += 1

        state['queue'] = actions

    if state['queue']:
        action = state['queue'].pop(0)
        tool, ax, ay = action
        ax = max(1, min(WORLD_W - 2, ax))
        ay = max(1, min(WORLD_H - 2, ay))

        # For zones, check if area is reasonably clear
        # (skip check to avoid getting stuck - let auto-bulldoze handle it)
        if tool in (Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.INDUSTRIAL):
            tm = obs.tile_map
            em = empty_mask(tm)
            # Only skip if a road or wire is in the 3x3 area
            blocked = False
            for dy in range(-1, 2):
                for dx in range(-1, 2):
                    ny, nx = ay + dy, ax + dx
                    if 0 <= ny < WORLD_H and 0 <= nx < WORLD_W:
                        # Block if road or wire is there (we don't want to demolish infra)
                        tile = tm[ny, nx]
                        if road_mask(tm)[ny, nx] or wire_mask(tm)[ny, nx] or plant_mask(tm)[ny, nx]:
                            blocked = True
                            break
                if blocked:
                    break
            if blocked:
                return None

        return (tool, ax, ay)

    # Reactive phase: add more zones if we have population
    if obs.city_pop > 50:
        tm = obs.tile_map
        em = empty_mask(tm)
        rm = road_mask(tm)
        wm = wire_mask(tm)

        # Try to find empty 3x3 areas near roads and wires
        for cy in range(34, 68, 3):
            for cx in range(24, 80, 3):
                if cy % 6 == 0:
                    continue  # skip road rows
                # Check 3x3 clear
                clear = True
                for dy in range(-1, 2):
                    for dx in range(-1, 2):
                        ny, nx = cy + dy, cx + dx
                        if not (0 <= ny < WORLD_H and 0 <= nx < WORLD_W):
                            clear = False
                            break
                        if not em[ny, nx]:
                            clear = False
                            break
                    if not clear:
                        break
                if not clear:
                    continue

                # Check road and wire nearby
                road_near = False
                wire_near = False
                for dy in range(-2, 3):
                    for dx in range(-2, 3):
                        ny2, nx2 = cy + dy, cx + dx
                        if 0 <= ny2 < WORLD_H and 0 <= nx2 < WORLD_W:
                            if rm[ny2, nx2]:
                                road_near = True
                            if wm[ny2, nx2]:
                                wire_near = True

                if road_near and wire_near:
                    res_c = np.sum(res_mask(tm))
                    com_c = np.sum(com_mask(tm))
                    ind_c = np.sum(ind_mask(tm))
                    total = res_c + com_c + ind_c + 1
                    if ind_c / total < 0.2:
                        return (Tool.INDUSTRIAL, cx, cy)
                    elif com_c / total < 0.3:
                        return (Tool.COMMERCIAL, cx, cy)
                    else:
                        return (Tool.RESIDENTIAL, cx, cy)

    return None

def act(obs, state):
    """
    Variation: Use a HORIZONTAL spine (road row + wire row) instead of vertical,
    with zones placed above and below. This creates a fundamentally different
    city shape. Add multiple power plants early, aggressive zone diversity.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        if com_count / t < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    all_zone_mask = resm | comm | indm

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    # Use horizontal layout: power plant on left, wire row and road row horizontal
    # Zones placed in columns above and below the road row

    # Phase 1: Place first coal power plant at left-center
    if not np.any(pm):
        return (Tool.COALPOWER, cx - 30, cy)

    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Horizontal spine layout
    wire_row = cy       # horizontal wire row
    road_row = cy + 2   # horizontal road row, 2 below wire
    upper_zone_row = wire_row - 3  # zones above wire
    lower_zone_row = road_row + 3  # zones below road

    wire_row = max(2, min(WORLD_H - 3, wire_row))
    road_row = max(2, min(WORLD_H - 3, road_row))
    upper_zone_row = max(1, min(WORLD_H - 2, upper_zone_row))
    lower_zone_row = max(1, min(WORLD_H - 2, lower_zone_row))

    # Dynamic spine extent (horizontal)
    if obs.city_pop < 100:
        spine_extent = 12
    elif obs.city_pop < 300:
        spine_extent = 20
    elif obs.city_pop < 600:
        spine_extent = 30
    else:
        spine_extent = 40

    target_min_col = max(1, cx - spine_extent)
    target_max_col = min(WORLD_W - 2, cx + spine_extent)

    # Current wire and road extents
    wire_cols_on_spine = sorted([c for c in range(WORLD_W) if wm[wire_row, c]])
    road_cols_on_row = sorted([c for c in range(WORLD_W) if rm[road_row, c]])
    road_cols_set = set(road_cols_on_row)

    # Phase 2: Start wire adjacent to plant (horizontal from plant)
    if not wire_cols_on_spine:
        # Place wire starting just right of plant
        start_c = plant_cx + 2
        for dc in range(0, 8):
            nc = start_c + dc
            if 0 <= nc < WORLD_W and (em[wire_row, nc] or wm[wire_row, nc]):
                return (Tool.WIRE, nc, wire_row)
        return None

    min_wire_col = min(wire_cols_on_spine)
    max_wire_col = max(wire_cols_on_spine)

    # Phase 3: Extend wire spine rightward
    if max_wire_col < target_max_col:
        nc = max_wire_col + 1
        if nc < WORLD_W and not pm[wire_row, nc]:
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # Phase 4: Extend wire spine leftward (toward plant)
    if min_wire_col > target_min_col:
        nc = min_wire_col - 1
        if nc >= 0 and not pm[wire_row, nc]:
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # Phase 5: Build road row parallel to wire
    for c in wire_cols_on_spine:
        if 0 <= c < WORLD_W and 0 <= road_row < WORLD_H:
            if not rm[road_row, c] and em[road_row, c]:
                return (Tool.ROAD, c, road_row)

    # Phase 6: Place zones along the corridor
    zone_cols = list(range(max(1, target_min_col), min(WORLD_W - 1, target_max_col + 1), 3))

    for zc in zone_cols:
        wire_near = any(abs(zc - wc) <= 2 for wc in wire_cols_on_spine)
        road_near = any(abs(zc - rc) <= 2 for rc in road_cols_on_row)

        if wire_near and road_near:
            # Try upper zone row
            zr = upper_zone_row
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc, 5) and has_road_nearby(zr, zc, 5):
                    return (pick_tool(), zc, zr)
                elif has_wire_nearby(zr, zc, 5):
                    return (Tool.RESIDENTIAL, zc, zr)

            # Try lower zone row
            zr = lower_zone_row
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_road_nearby(zr, zc, 5) and has_wire_nearby(zr, zc, 6):
                    return (pick_tool(), zc, zr)

    # Phase 7: Vertical wires from spine to upper zones
    for wc in wire_cols_on_spine:
        for wr in range(wire_row - 1, max(upper_zone_row - 2, 0), -1):
            if 0 <= wr < WORLD_H:
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc]:
                    break

    # Phase 8: Road extensions to lower zones
    for rc in wire_cols_on_spine:
        if not rm[road_row, rc]:
            continue
        for rr in range(road_row + 1, lower_zone_row + 2):
            if 0 <= rr < WORLD_H:
                if rm[rr, rc]:
                    break
                if em[rr, rc] and not pm[rr, rc]:
                    return (Tool.ROAD, rc, rr)
                elif not em[rr, rc]:
                    break

    # Phase 9: Wire extensions to lower zone for power
    for wc in wire_cols_on_spine:
        for wr in range(wire_row + 1, lower_zone_row + 2):
            if 0 <= wr < WORLD_H:
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc] and not rm[wr, wc]:
                    break

    # Phase 10: Second power plant when pop grows
    if obs.city_pop > 200 and int(np.sum(pm)) < 9:
        px2, py2 = plant_cx + 25, plant_cy
        if 2 <= py2 <= WORLD_H - 3 and 2 <= px2 <= WORLD_W - 3:
            area_clear = True
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if not (em[py2 + dr, px2 + dc] or pm[py2 + dr, px2 + dc]):
                        area_clear = False
            if area_clear:
                return (Tool.COALPOWER, px2, py2)

    # Phase 11: Second horizontal band above first when pop >= 200
    if obs.city_pop >= 200:
        wire_row2 = wire_row - 8
        road_row2 = wire_row2 - 2
        upper_zone_row2 = wire_row2 + 3
        lower_zone_row2 = road_row2 - 3

        wire_row2 = max(2, min(WORLD_H - 3, wire_row2))
        road_row2 = max(2, min(WORLD_H - 3, road_row2))
        upper_zone_row2 = max(1, min(WORLD_H - 2, upper_zone_row2))
        lower_zone_row2 = max(1, min(WORLD_H - 2, lower_zone_row2))

        wire_cols2 = sorted([c for c in range(WORLD_W) if wm[wire_row2, c]])
        road_cols2 = set(c for c in range(WORLD_W) if rm[road_row2, c])

        if not wire_cols2:
            # Build vertical wire bridge from main spine to band2
            for wr in range(wire_row - 1, wire_row2 - 1, -1):
                if 0 <= wr < WORLD_H:
                    wc = cx
                    if not wm[wr, wc] and em[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    elif not em[wr, wc] and not wm[wr, wc]:
                        break
        else:
            min_wc2 = min(wire_cols2)
            max_wc2 = max(wire_cols2)

            if max_wc2 < target_max_col:
                nc = max_wc2 + 1
                if nc < WORLD_W and em[wire_row2, nc]:
                    return (Tool.WIRE, nc, wire_row2)
            if min_wc2 > target_min_col:
                nc = min_wc2 - 1
                if nc >= 0 and em[wire_row2, nc]:
                    return (Tool.WIRE, nc, wire_row2)

            for wc in wire_cols2:
                if wc not in road_cols2 and em[road_row2, wc]:
                    return (Tool.ROAD, wc, road_row2)

            for zc in zone_cols:
                wire_near2 = any(abs(zc - wc) <= 2 for wc in wire_cols2)
                road_near2 = any(abs(zc - rc) <= 2 for rc in road_cols2)
                if wire_near2 and road_near2:
                    for zr in [upper_zone_row2, lower_zone_row2]:
                        if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                            if has_wire_nearby(zr, zc, 6) and has_road_nearby(zr, zc, 5):
                                return (pick_tool(), zc, zr)

            for wc in wire_cols2:
                for wr in range(wire_row2 + 1, min(upper_zone_row2 + 2, WORLD_H)):
                    if 0 <= wr < WORLD_H:
                        if wm[wr, wc]: break
                        if em[wr, wc] and not pm[wr, wc]:
                            return (Tool.WIRE, wc, wr)
                        elif not em[wr, wc]: break

    # Phase 12: Third horizontal band below first when pop >= 400
    if obs.city_pop >= 400:
        wire_row3 = road_row + 8
        road_row3 = wire_row3 + 2
        upper_zone_row3 = wire_row3 - 3
        lower_zone_row3 = road_row3 + 3

        wire_row3 = max(2, min(WORLD_H - 3, wire_row3))
        road_row3 = max(2, min(WORLD_H - 3, road_row3))
        upper_zone_row3 = max(1, min(WORLD_H - 2, upper_zone_row3))
        lower_zone_row3 = max(1, min(WORLD_H - 2, lower_zone_row3))

        wire_cols3 = sorted([c for c in range(WORLD_W) if wm[wire_row3, c]])
        road_cols3 = set(c for c in range(WORLD_W) if rm[road_row3, c])

        if not wire_cols3:
            for wr in range(road_row + 1, wire_row3 + 1):
                if 0 <= wr < WORLD_H:
                    wc = cx
                    if not wm[wr, wc] and em[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    elif not em[wr, wc] and not wm[wr, wc]:
                        break
        else:
            min_wc3 = min(wire_cols3)
            max_wc3 = max(wire_cols3)

            if max_wc3 < target_max_col:
                nc = max_wc3 + 1
                if nc < WORLD_W and em[wire_row3, nc]:
                    return (Tool.WIRE, nc, wire_row3)
            if min_wc3 > target_min_col:
                nc = min_wc3 - 1
                if nc >= 0 and em[wire_row3, nc]:
                    return (Tool.WIRE, nc, wire_row3)

            for wc in wire_cols3:
                if wc not in road_cols3 and em[road_row3, wc]:
                    return (Tool.ROAD, wc, road_row3)

            for zc in zone_cols:
                wire_near3 = any(abs(zc - wc) <= 2 for wc in wire_cols3)
                road_near3 = any(abs(zc - rc) <= 2 for rc in road_cols3)
                if wire_near3 and road_near3:
                    for zr in [upper_zone_row3, lower_zone_row3]:
                        if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                            if has_wire_nearby(zr, zc, 6) and has_road_nearby(zr, zc, 5):
                                return (pick_tool(), zc, zr)

            for wc in wire_cols3:
                for wr in range(wire_row3 - 1, max(upper_zone_row3 - 2, 0), -1):
                    if 0 <= wr < WORLD_H:
                        if wm[wr, wc]: break
                        if em[wr, wc] and not pm[wr, wc]:
                            return (Tool.WIRE, wc, wr)
                        elif not em[wr, wc]: break

    # Phase 13: Extra zone rows when pop > 300
    if obs.city_pop > 300:
        extra_rows = [upper_zone_row - 6, lower_zone_row + 6]
        for zr in extra_rows:
            if 1 <= zr <= WORLD_H - 2:
                for zc in zone_cols:
                    if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                        if has_road_nearby(zr, zc, 6) and has_wire_nearby(zr, zc, 7):
                            return (pick_tool(), zc, zr)

    return None

def act(obs, state):
    """
    Variation: Build TWO parallel neighborhoods side by side from the start,
    each with their own wire spine and road column, sharing a single coal plant.
    Better zone mix: ~40% RES, ~30% COM, ~30% IND spread across both clusters.
    Layout: plant at center-left, two wire spines, two road cols, zones on both sides.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    # Use state to track build queue index
    if 'q_idx' not in state:
        state['q_idx'] = 0

    has_plant = np.any(pm)
    has_wire = np.any(wm)
    has_road = np.any(rm)

    # Central anchor
    cx, cy = 60, 50

    # Plant position (3x3 footprint, center at plant_cx, plant_cy)
    plant_cx, plant_cy = cx, cy

    # Phase 1: Place coal power plant
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    wire_positions = set(zip(*np.where(wm))) if has_wire else set()
    road_positions = set(zip(*np.where(rm))) if has_road else set()
    res_positions = set(zip(*np.where(res_mask(tm))))
    com_positions = set(zip(*np.where(com_mask(tm))))
    ind_positions = set(zip(*np.where(ind_mask(tm))))
    all_zones = res_positions | com_positions | ind_positions

    res_count = len(res_positions)
    com_count = len(com_positions)
    ind_count = len(ind_positions)

    # Two wire spines: left and right of plant
    # Left cluster: wire at cx-5, road at cx-4, zones at cx-7 (left side)
    # Right cluster: wire at cx+5, road at cx+4, zones at cx+7 (right side)

    lwire_col = cx - 5   # left wire spine
    lroad_col = cx - 4   # left road col
    lzone_col = cx - 8   # left zone col

    rwire_col = cx + 5   # right wire spine
    rroad_col = cx + 4   # right road col
    rzone_col = cx + 8   # right zone col

    # Vertical span
    base_span = 12
    extra_span = min(20, obs.city_pop // 20)
    target_span = base_span + extra_span
    tmin = max(2, cy - target_span)
    tmax = min(WORLD_H - 3, cy + target_span)

    def extend_wire_col(col, tmin, tmax):
        """Try to extend wire in given column. Returns action or None."""
        rows_in_col = sorted(r for (r, c) in wire_positions if c == col)
        if not rows_in_col:
            # Start near cy, avoiding plant footprint
            for dy in range(0, 5):
                for ny in [cy + dy, cy - dy]:
                    if tmin <= ny <= tmax and 0 <= ny < WORLD_H:
                        if em[ny, col]:
                            return (Tool.WIRE, col, ny)
        else:
            max_r = max(rows_in_col)
            min_r = min(rows_in_col)
            if max_r < tmax:
                nr = max_r + 1
                if 0 <= nr < WORLD_H and (em[nr, col] or wm[nr, col]):
                    return (Tool.WIRE, col, nr)
            if min_r > tmin:
                nr = min_r - 1
                if 0 <= nr < WORLD_H and (em[nr, col] or wm[nr, col]):
                    return (Tool.WIRE, col, nr)
        return None

    def extend_road_col(road_col, wire_col, tmin, tmax):
        """Build road parallel to wire spine."""
        wire_rows = sorted(r for (r, c) in wire_positions if c == wire_col)
        road_rows = set(r for (r, c) in road_positions if c == road_col)
        for wr in wire_rows:
            if wr not in road_rows and tmin <= wr <= tmax:
                if 0 <= road_col < WORLD_W and em[wr, road_col]:
                    return (Tool.ROAD, road_col, wr)
        return None

    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def already_zone_nearby(zr, zc):
        return any(abs(zr - pr) <= 1 and abs(zc - pc) <= 1 for (pr, pc) in all_zones)

    def place_zones(zone_col, road_col, wire_col, side):
        """Place zones in zone_col adjacent to road. side: 'left' or 'right'."""
        wire_rows = sorted(r for (r, c) in wire_positions if c == wire_col)
        road_rows = set(r for (r, c) in road_positions if c == road_col)
        wire_set = set(wire_rows)
        for zr in wire_rows:
            road_nearby = any(abs(zr - rr) <= 2 for rr in road_rows)
            wire_nearby = any(abs(zr - wr) <= 1 for wr in wire_set)
            if not road_nearby or not wire_nearby:
                continue
            if 0 <= zr < WORLD_H and 0 <= zone_col < WORLD_W:
                if not already_zone_nearby(zr, zone_col) and zone_area_free(zr, zone_col):
                    # Zone type based on mix targets
                    total = res_count + com_count + ind_count + 1
                    if side == 'left':
                        # Left cluster: industrial + residential
                        if ind_count < total * 0.3:
                            return (Tool.INDUSTRIAL, zone_col, zr)
                        else:
                            return (Tool.RESIDENTIAL, zone_col, zr)
                    else:
                        # Right cluster: commercial + residential
                        if com_count < total * 0.3:
                            return (Tool.COMMERCIAL, zone_col, zr)
                        else:
                            return (Tool.RESIDENTIAL, zone_col, zr)
        return None

    # Connect plant to both wire spines with horizontal wires
    def connect_plant_to_wire(wire_col):
        """Lay horizontal wires from plant edge to wire spine column."""
        if wire_col < plant_cx:
            # left spine: connect from plant_cx-2 to wire_col
            for wc in range(plant_cx - 2, wire_col - 1, -1):
                if 0 <= wc < WORLD_W and em[plant_cy, wc]:
                    return (Tool.WIRE, wc, plant_cy)
        else:
            # right spine: connect from plant_cx+2 to wire_col
            for wc in range(plant_cx + 2, wire_col + 1):
                if 0 <= wc < WORLD_W and em[plant_cy, wc]:
                    return (Tool.WIRE, wc, plant_cy)
        return None

    # Check connection to left wire spine
    left_wire_rows = sorted(r for (r, c) in wire_positions if c == lwire_col)
    right_wire_rows = sorted(r for (r, c) in wire_positions if c == rwire_col)

    # Connect plant to left wire spine first
    # Wire at plant_cy must bridge from plant to lwire_col
    left_connected = any(wm[plant_cy, wc] for wc in range(lwire_col, plant_cx))
    if not left_connected:
        action = connect_plant_to_wire(lwire_col)
        if action:
            return action

    right_connected = any(wm[plant_cy, wc] for wc in range(plant_cx + 1, rwire_col + 1))
    if not right_connected:
        action = connect_plant_to_wire(rwire_col)
        if action:
            return action

    # Extend left wire spine
    action = extend_wire_col(lwire_col, tmin, tmax)
    if action:
        return action

    # Extend right wire spine
    action = extend_wire_col(rwire_col, tmin, tmax)
    if action:
        return action

    # Build left road column
    action = extend_road_col(lroad_col, lwire_col, tmin, tmax)
    if action:
        return action

    # Build right road column
    action = extend_road_col(rroad_col, rwire_col, tmin, tmax)
    if action:
        return action

    # Place zones left cluster
    action = place_zones(lzone_col, lroad_col, lwire_col, 'left')
    if action:
        return action

    # Place zones right cluster
    action = place_zones(rzone_col, rroad_col, rwire_col, 'right')
    if action:
        return action

    # Add lateral roads from road col to zone col
    def lateral_roads(road_col, zone_col, wire_col):
        wire_rows = sorted(r for (r, c) in wire_positions if c == wire_col)
        if zone_col < road_col:
            step = -1
        else:
            step = 1
        for wr in wire_rows:
            for rc in range(road_col + step, zone_col, step):
                if 0 <= rc < WORLD_W and 0 <= wr < WORLD_H and em[wr, rc]:
                    return (Tool.ROAD, rc, wr)
        return None

    action = lateral_roads(lroad_col, lzone_col, lwire_col)
    if action:
        return action

    action = lateral_roads(rroad_col, rzone_col, rwire_col)
    if action:
        return action

    # Add second coal plant when population large enough
    if obs.city_pop > 400 and not state.get('second_plant', False):
        p2x, p2y = cx, cy - 20
        clear = True
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = p2y + dr, p2x + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if not em[rr, rc]:
                        clear = False
        if clear:
            state['second_plant'] = True
            return (Tool.COALPOWER, p2x, p2y)

    # Add more zones further out if population growing
    if obs.city_pop > 300:
        lzone_col2 = lzone_col - 4
        action = place_zones(lzone_col2, lroad_col, lwire_col, 'left')
        if action:
            return action
        rzone_col2 = rzone_col + 4
        action = place_zones(rzone_col2, rroad_col, rwire_col, 'right')
        if action:
            return action

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder combining best of both parents.
    - Reads tile_map every step to decide next placement
    - Places coal plant, then wires out from plant, then roads parallel to wires
    - Places zones reactively where road+wire coverage exists
    - Expands second plant and services as city grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Gather positions
    plant_ys, plant_xs = np.where(pm)
    wire_ys, wire_xs = np.where(wm)
    road_ys, road_xs = np.where(rm)
    res_ys, res_xs = np.where(resm)
    com_ys, com_xs = np.where(comm)
    ind_ys, ind_xs = np.where(indm)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Starting anchor
    CX, CY = 28, 50

    # Step 1: Place first coal plant
    if not np.any(pm):
        return (Tool.COALPOWER, CX, CY)

    # Derive plant center
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    def pick_tool():
        t = max(total_zones, 1)
        r = res_count / t
        c = com_count / t
        i = ind_count / t
        if c < 0.20:
            return Tool.COMMERCIAL
        if i < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    zone_set = set(zip(
        np.concatenate([res_ys, com_ys, ind_ys]).tolist() if total_zones > 0 else [],
        np.concatenate([res_xs, com_xs, ind_xs]).tolist() if total_zones > 0 else []
    ))

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    # ---- Wire spine: extend horizontally from plant rightward ----
    spine_y = py
    wire_end_x = min(px + 62, WORLD_W - 5)

    # Find rightmost wire on spine row near plant
    spine_wires = wire_xs[(wire_ys == spine_y) & (wire_xs >= px)]
    if len(spine_wires) > 0:
        max_wx = int(np.max(spine_wires))
    else:
        max_wx = px + 1  # start just right of plant

    # Extend wire spine one step at a time
    if max_wx < wire_end_x:
        nx = max_wx + 1
        if in_bounds(nx, spine_y):
            if bool(em[spine_y, nx]):
                return (Tool.WIRE, nx, spine_y)
            # If blocked, skip and try next
            for nx2 in range(max_wx + 2, wire_end_x + 1):
                if in_bounds(nx2, spine_y) and bool(em[spine_y, nx2]):
                    return (Tool.WIRE, nx2, spine_y)

    # ---- Vertical wire branches from spine every 6 cols ----
    branch_cols = list(range(px + 6, wire_end_x + 1, 6))
    for bx in branch_cols:
        if not in_bounds(bx, spine_y):
            continue
        # Only branch if spine is wired here
        if not (bool(wm[spine_y, bx]) or bool(pm[spine_y, bx])):
            continue
        for sign in [-1, 1]:
            for dy in range(1, 9):
                wy = spine_y + sign * dy
                wx = bx
                if not in_bounds(wx, wy):
                    break
                if bool(wm[wy, wx]) or bool(pm[wy, wx]):
                    continue
                if bool(em[wy, wx]):
                    return (Tool.WIRE, wx, wy)
                break  # blocked

    # ---- Road rows parallel to spine ----
    road_top = spine_y - 2
    road_bot = spine_y + 2
    road_start = px + 2
    road_end = min(px + 60, WORLD_W - 5)

    # Extend top road row
    top_roads = road_xs[(road_ys == road_top) & (road_xs >= road_start)]
    max_top = int(np.max(top_roads)) if len(top_roads) > 0 else road_start - 1
    if max_top < road_end:
        nrx = max_top + 1
        if in_bounds(nrx, road_top) and bool(em[road_top, nrx]):
            return (Tool.ROAD, nrx, road_top)

    # Extend bottom road row
    bot_roads = road_xs[(road_ys == road_bot) & (road_xs >= road_start)]
    max_bot = int(np.max(bot_roads)) if len(bot_roads) > 0 else road_start - 1
    if max_bot < road_end:
        nrx = max_bot + 1
        if in_bounds(nrx, road_bot) and bool(em[road_bot, nrx]):
            return (Tool.ROAD, nrx, road_bot)

    # ---- Vertical connector roads every 6 cols ----
    for vc in range(road_start, road_end + 1, 6):
        for vr in range(road_top, road_bot + 1):
            if not in_bounds(vc, vr):
                continue
            if not bool(rm[vr, vc]) and not bool(pm[vr, vc]) and not bool(wm[vr, vc]):
                if bool(em[vr, vc]):
                    return (Tool.ROAD, vc, vr)

    # ---- Additional road rows further out for more zone coverage ----
    for extra_offset in [4, 6, 8, 10]:
        for sign in [-1, 1]:
            extra_row = spine_y + sign * extra_offset
            if not in_bounds(road_start, extra_row):
                continue
            ex_roads = road_xs[(road_ys == extra_row) & (road_xs >= road_start)]
            max_ex = int(np.max(ex_roads)) if len(ex_roads) > 0 else road_start - 1
            if max_ex < road_end:
                nrx = max_ex + 1
                if in_bounds(nrx, extra_row) and bool(em[extra_row, nrx]):
                    return (Tool.ROAD, nrx, extra_row)

    # ---- Build neighbor masks for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            if sr1 > sr0 and sc1 > sc0 and r1 > r0 and c1 > c0:
                nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            if sr1 > sr0 and sc1 > sc0 and r1 > r0 and c1 > c0:
                nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
                nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Candidate zone centers
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Deterministic reactive scan
        step_hash = int(obs.step * 17 + int(obs.city_pop * 3)) % max(len(cxs), 1)
        for offset in range(min(len(cxs), 60)):
            k = (step_hash + offset * 11) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # ---- Second power plant when city grows ----
    if total_zones > 8 or obs.city_pop > 200:
        p2x = min(px + 55, WORLD_W - 6)
        p2y = py
        # Check no existing plant nearby
        if len(plant_xs) > 0:
            dists = np.sqrt((plant_xs - p2x)**2 + (plant_ys - p2y)**2)
            too_close = bool(np.any(dists < 10))
        else:
            too_close = False
        if not too_close and in_bounds(p2x, p2y) and bool(em[p2y, p2x]):
            return (Tool.COALPOWER, p2x, p2y)

    # ---- Services for population ----
    if obs.city_pop > 150:
        fx, fy = px + 6, py - 10
        if in_bounds(fx, fy) and bool(em[fy, fx]):
            return (Tool.FIRESTATION, fx, fy)
        fx2, fy2 = px + 6, py + 10
        if in_bounds(fx2, fy2) and bool(em[fy2, fx2]):
            return (Tool.POLICESTATION, fx2, fy2)

    # ---- Fallback: extend wire from existing wire frontier ----
    if len(wire_xs) > 0:
        step_k = int(obs.step * 7) % max(len(wire_xs), 1)
        wx_s = int(wire_xs[step_k])
        wy_s = int(wire_ys[step_k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = wx_s + dx2, wy_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)

    # ---- Fallback: extend road from existing road frontier ----
    if len(road_xs) > 0:
        step_k = int(obs.step * 13) % max(len(road_xs), 1)
        rx_s = int(road_xs[step_k])
        ry_s = int(road_ys[step_k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx_s + dx2, ry_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Improved city builder with denser grid layout.
    - Single central power plant with wire grid
    - Dense road grid enabling many zones
    - Balanced RCI mix (40% res, 30% com, 30% ind)
    - Zones placed systematically on grid
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Initialize state
    if 'phase' not in state:
        state['phase'] = 0
        state['action_queue'] = []

    def build_action_queue():
        """Pre-compute the full build sequence"""
        actions = []

        # Central area: two power plants
        CX1, CY1 = 40, 45  # cluster 1 center
        CX2, CY2 = 75, 45  # cluster 2 center

        # Place coal power plants
        actions.append((Tool.COALPOWER, CX1, CY1))
        actions.append((Tool.COALPOWER, CX2, CY2))

        # Wire spines connecting plants (horizontal at y=45)
        for x in range(CX1 + 2, CX2 - 1):
            actions.append((Tool.WIRE, x, CY1))

        # Vertical wire spines for each cluster
        for dy in range(-12, 13):
            if dy != 0:
                actions.append((Tool.WIRE, CX1, CY1 + dy))
                actions.append((Tool.WIRE, CX2, CY2 + dy))

        # Horizontal wires branching from spines
        for offset in [-8, -4, 0, 4, 8]:
            for dx in range(-10, 11):
                if dx != 0:
                    actions.append((Tool.WIRE, CX1 + dx, CY1 + offset))
                    actions.append((Tool.WIRE, CX2 + dx, CY2 + offset))

        # Road grid: horizontal roads at intervals
        for offset in [-9, -6, -3, 0, 3, 6, 9]:
            ry = CY1 + offset
            for rx in range(CX1 - 11, CX1 + 12):
                actions.append((Tool.ROAD, rx, ry))
            for rx in range(CX2 - 11, CX2 + 12):
                actions.append((Tool.ROAD, rx, ry))

        # Road grid: vertical roads at intervals
        for offset in [-9, -6, -3, 0, 3, 6, 9]:
            rx = CX1 + offset
            for ry in range(CY1 - 11, CY1 + 12):
                actions.append((Tool.ROAD, rx, ry))
        for offset in [-9, -6, -3, 0, 3, 6, 9]:
            rx = CX2 + offset
            for ry in range(CY2 - 11, CY2 + 12):
                actions.append((Tool.ROAD, rx, ry))

        # Connecting highway between clusters
        for rx in range(CX1 + 12, CX2 - 11):
            actions.append((Tool.ROAD, rx, CY1))

        # Zone placement: fill grid cells between roads
        # For cluster 1: place zones in 3x3 gaps
        zone_idx = 0
        for col_off in [-8, -5, -2, 1, 4, 7]:
            for row_off in [-8, -5, -2, 1, 4, 7]:
                zx = CX1 + col_off
                zy = CY1 + row_off
                if in_bounds(zx, zy):
                    # Balanced RCI
                    t = zone_idx % 10
                    if t < 4:
                        tool = Tool.RESIDENTIAL
                    elif t < 7:
                        tool = Tool.COMMERCIAL
                    else:
                        tool = Tool.INDUSTRIAL
                    actions.append((tool, zx, zy))
                    zone_idx += 1

        # For cluster 2
        for col_off in [-8, -5, -2, 1, 4, 7]:
            for row_off in [-8, -5, -2, 1, 4, 7]:
                zx = CX2 + col_off
                zy = CY2 + row_off
                if in_bounds(zx, zy):
                    t = zone_idx % 10
                    if t < 4:
                        tool = Tool.RESIDENTIAL
                    elif t < 7:
                        tool = Tool.COMMERCIAL
                    else:
                        tool = Tool.INDUSTRIAL
                    actions.append((tool, zx, zy))
                    zone_idx += 1

        # Services
        actions.append((Tool.FIRESTATION, CX1 - 12, CY1))
        actions.append((Tool.FIRESTATION, CX2 + 12, CY2))
        actions.append((Tool.POLICESTATION, CX1, CY1 - 13))
        actions.append((Tool.POLICESTATION, CX2, CY2 + 13))

        return actions

    if not state['action_queue']:
        state['action_queue'] = build_action_queue()
        state['queue_idx'] = 0

    # Execute from queue but skip if tile already placed
    queue = state['action_queue']
    idx = state.get('queue_idx', 0)

    while idx < len(queue):
        action = queue[idx]
        tool, ax, ay = action
        idx += 1

        if not in_bounds(ax, ay):
            continue

        # Skip if already correct type
        if tool == Tool.WIRE and bool(wm[ay, ax]):
            continue
        if tool == Tool.ROAD and bool(rm[ay, ax]):
            continue
        if tool in (Tool.COALPOWER,) and bool(pm[ay, ax]):
            # Check nearby for plant
            found = False
            for dy in range(-2, 3):
                for dx in range(-2, 3):
                    nx, ny = ax + dx, ay + dy
                    if in_bounds(nx, ny) and bool(pm[ny, nx]):
                        found = True
                        break
                if found:
                    break
            if found:
                continue

        # Don't overwrite plants with wire/road
        if tool in (Tool.WIRE, Tool.ROAD):
            if bool(pm[ay, ax]):
                continue

        state['queue_idx'] = idx
        return action

    state['queue_idx'] = idx

    # Reactive fallback: place zones near roads+power
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    power_src = wm | pm
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    zone_existing = resm | comm | indm
    cand = em & nbr_road & nbr_power
    cand[0:2, :] = False
    cand[WORLD_H-2:, :] = False
    cand[:, 0:2] = False
    cand[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        res_count = int(np.sum(resm))
        com_count = int(np.sum(comm))
        ind_count = int(np.sum(indm))
        total = max(res_count + com_count + ind_count, 1)

        if com_count / total < 0.28:
            ztool = Tool.COMMERCIAL
        elif ind_count / total < 0.28:
            ztool = Tool.INDUSTRIAL
        else:
            ztool = Tool.RESIDENTIAL

        key = int(obs.step * 17 + int(obs.city_pop * 3) + 1) % len(cxs)
        for offset in range(min(len(cxs), 100)):
            k = (key + offset * 11) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            ok = True
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    ny2, nx2 = zy + dr, zx + dc
                    if not in_bounds(nx2, ny2):
                        ok = False; break
                    if not (bool(em[ny2, nx2]) or bool(zone_existing[ny2, nx2])):
                        ok = False; break
                if not ok:
                    break
            if ok:
                return (ztool, zx, zy)

    return None

def act(obs, state):
    """
    Closed-loop policy: every step reads tile_map and decides next action.
    Strategy:
    - Place coal power plant near center-left.
    - Build wire spine vertically from plant.
    - Build road column adjacent to wire spine.
    - Place zones (RES/COM/IND) on both sides of road/wire.
    - Expand reactively based on what's already on the map.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # Fixed anchor positions
    cx, cy = 60, 50
    plant_x, plant_y = cx - 4, cy
    wire_col = plant_x + 4   # column for vertical wire spine
    road_col = wire_col + 2  # column for vertical road

    # --- Phase 0: Place coal power plant if not yet present ---
    if not np.any(pm):
        return (Tool.COALPOWER, plant_x, plant_y)

    # Find actual plant center from map
    rows, cols = np.where(pm)
    if len(rows) > 0:
        plant_y = int(np.median(rows))
        plant_x = int(np.median(cols))
        wire_col = plant_x + 4
        road_col = wire_col + 2

    # Helper: is a position safe to overwrite (not plant)?
    def not_plant(r, c):
        pr, pc = np.where(pm)
        for i in range(len(pr)):
            if abs(pr[i] - r) <= 1 and abs(pc[i] - c) <= 1:
                return False
        return True

    # --- Phase 1: Ensure wire connects plant to wire spine ---
    # Wire from plant edge to wire_col at plant_y row
    for c in range(plant_x + 2, wire_col + 1):
        if 0 <= c < WORLD_W and not wm[plant_y, c] and not_plant(plant_y, c):
            return (Tool.WIRE, c, plant_y)

    # --- Phase 2: Build vertical wire spine ---
    # Find current extent of wire spine
    wire_rows = sorted([r for r in range(WORLD_H) if 0 <= wire_col < WORLD_W and wm[r, wire_col]])

    target_top = max(2, plant_y - 18)
    target_bot = min(WORLD_H - 3, plant_y + 18)

    if not wire_rows:
        return (Tool.WIRE, wire_col, plant_y)

    min_wr = min(wire_rows)
    max_wr = max(wire_rows)

    # Extend downward
    if max_wr < target_bot:
        nr = max_wr + 1
        if nr < WORLD_H and not_plant(nr, wire_col):
            return (Tool.WIRE, wire_col, nr)

    # Extend upward
    if min_wr > target_top:
        nr = min_wr - 1
        if nr >= 0 and not_plant(nr, wire_col):
            return (Tool.WIRE, wire_col, nr)

    # --- Phase 3: Build vertical road column ---
    road_rows = sorted([r for r in range(WORLD_H) if 0 <= road_col < WORLD_W and rm[r, road_col]])

    if not road_rows:
        return (Tool.ROAD, road_col, plant_y)

    min_rr = min(road_rows)
    max_rr = max(road_rows)

    # Road should match wire extent
    if max_rr < max_wr and max_rr + 1 < WORLD_H:
        return (Tool.ROAD, road_col, max_rr + 1)
    if min_rr > min_wr and min_rr - 1 >= 0:
        return (Tool.ROAD, road_col, min_rr - 1)

    # --- Phase 4: Lateral wires from spine to left zone column ---
    left_zone_col = wire_col - 3
    # For each row in wire spine, ensure lateral wire exists at left_zone_col
    for r in wire_rows:
        for c in range(wire_col - 1, left_zone_col - 1, -1):
            if 0 <= c < WORLD_W and not wm[r, c] and not_plant(r, c):
                return (Tool.WIRE, c, r)

    # --- Phase 5: Place zones ---
    # Gather existing zone positions
    res_pos = list(zip(*np.where(res_m))) if np.any(res_m) else []
    com_pos = list(zip(*np.where(com_m))) if np.any(com_m) else []
    ind_pos = list(zip(*np.where(ind_m))) if np.any(ind_m) else []
    all_zones = res_pos + com_pos + ind_pos

    res_count = len(res_pos)
    com_count = len(com_pos)
    ind_count = len(ind_pos)

    def zone_area_clear(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if pm[rr, rc]:
                    return False
        return True

    def zone_exists_near(zr, zc):
        return any(abs(zr - pr) <= 2 and abs(zc - pc) <= 2 for (pr, pc) in all_zones)

    # Zone rows: every 3 rows along the spine
    zone_rows_candidates = list(range(max(2, min_wr + 1), min(WORLD_H - 2, max_wr), 3))

    for zr in zone_rows_candidates:
        # Check wire and road coverage near this row
        wire_near = wm[zr, wire_col] if 0 <= wire_col < WORLD_W else False
        road_near = rm[zr, road_col] if 0 <= road_col < WORLD_W else False

        if not wire_near or not road_near:
            continue

        # Left zone: at left_zone_col (powered by lateral wire)
        zc = left_zone_col
        if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
            if not zone_exists_near(zr, zc) and zone_area_clear(zr, zc):
                total = res_count + com_count + ind_count + 1
                if ind_count * 4 < total:
                    return (Tool.INDUSTRIAL, zc, zr)
                elif com_count * 4 < total:
                    return (Tool.COMMERCIAL, zc, zr)
                else:
                    return (Tool.RESIDENTIAL, zc, zr)

        # Right zone: at road_col + 3 (powered via road-adjacent wire row)
        zc = road_col + 3
        if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
            if not zone_exists_near(zr, zc) and zone_area_clear(zr, zc):
                # Need lateral road for right zones
                # Place road segment road_col+1 .. road_col+3
                for rc in range(road_col + 1, road_col + 4):
                    if 0 <= rc < WORLD_W and not rm[zr, rc]:
                        return (Tool.ROAD, rc, zr)
                # Need lateral wire for right zones too
                for wc in range(wire_col + 1, road_col + 4):
                    if 0 <= wc < WORLD_W and not wm[zr, wc] and not_plant(zr, wc):
                        return (Tool.WIRE, wc, zr)
                total = res_count + com_count + ind_count + 1
                if com_count * 3 < total:
                    return (Tool.COMMERCIAL, zc, zr)
                else:
                    return (Tool.RESIDENTIAL, zc, zr)

    # --- Phase 6: Reactive expansion - grow adjacently from existing residential ---
    if obs.city_pop > 100:
        nbr = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        nbr[1:, :] |= res_m[:-1, :]
        nbr[:-1, :] |= res_m[1:, :]
        nbr[:, 1:] |= res_m[:, :-1]
        nbr[:, :-1] |= res_m[:, 1:]
        cand = em & nbr
        ys, xs = np.where(cand)
        if len(xs) > 0:
            # Pick candidate near road/wire
            best = None
            best_score = -1
            for i in range(len(xs)):
                yr, xr = int(ys[i]), int(xs[i])
                # Check nearby road and wire
                r_near = np.any(rm[max(0,yr-2):yr+3, max(0,xr-2):xr+3])
                w_near = np.any(wm[max(0,yr-2):yr+3, max(0,xr-2):xr+3])
                score = int(r_near) + int(w_near)
                if score > best_score:
                    best_score = score
                    best = (xr, yr)
            if best and best_score > 0:
                # Check zone area clear
                bx, by = best
                if zone_area_clear(by, bx) and not zone_exists_near(by, bx):
                    return (Tool.RESIDENTIAL, bx, by)

    # --- Phase 7: Add nuclear power if population is large enough ---
    if obs.city_pop > 400:
        nuke_x, nuke_y = plant_x - 8, plant_y
        if (2 <= nuke_y < WORLD_H - 2 and 2 <= nuke_x < WORLD_W - 2
                and not np.any(pm[nuke_y-1:nuke_y+2, nuke_x-1:nuke_x+2])):
            return (Tool.NUCLEARPOWER, nuke_x, nuke_y)

    # --- Phase 8: Fill any remaining wire gaps in spine ---
    for r in range(min_wr, max_wr + 1):
        if not wm[r, wire_col] and not_plant(r, wire_col):
            return (Tool.WIRE, wire_col, r)

    # --- Phase 9: Fill road gaps ---
    for r in range(min_wr, max_wr + 1):
        if not rm[r, road_col]:
            return (Tool.ROAD, road_col, r)

    return None

def act(obs, state):
    """
    Variation: Use a HORIZONTAL spine (road runs east-west) instead of vertical.
    Place power plant top-left, wire runs east along a row, road runs parallel.
    Zones are placed north and south of the road row.
    This creates a fundamentally different city layout.
    Also: more aggressive zone mix (more commercial/industrial early).
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        # More balanced: 30% ind, 35% com, 35% res
        if ind_count / t < 0.30:
            return Tool.INDUSTRIAL
        if com_count / t < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    all_zone_mask = resm | comm | indm

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=5):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    # Phase 1: Place first coal power plant near top-center
    if not np.any(pm):
        return (Tool.COALPOWER, cx - 10, cy - 20)

    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Horizontal layout:
    # wire_row: horizontal wire runs east from plant
    # road_row: road runs parallel, 2 rows below wire
    # zones: 3 rows above wire_row (north) or 3 rows below road_row (south)
    wire_row = plant_cy
    road_row = wire_row + 3
    north_zone_row = wire_row - 3
    south_zone_row = road_row + 3

    wire_row = max(3, min(WORLD_H - 4, wire_row))
    road_row = max(3, min(WORLD_H - 4, road_row))
    north_zone_row = max(1, min(WORLD_H - 2, north_zone_row))
    south_zone_row = max(1, min(WORLD_H - 2, south_zone_row))

    # Dynamic extent based on population
    if obs.city_pop < 100:
        spine_extent = 15
    elif obs.city_pop < 300:
        spine_extent = 25
    elif obs.city_pop < 600:
        spine_extent = 35
    else:
        spine_extent = 50

    target_left = max(1, plant_cx + 4)
    target_right = min(WORLD_W - 2, plant_cx + 4 + spine_extent)

    wire_cols_on_row = sorted([c for c in range(WORLD_W) if wm[wire_row, c]])
    road_cols_on_row = sorted([c for c in range(WORLD_W) if rm[road_row, c]])
    road_cols_set = set(road_cols_on_row)

    # Phase 2: Start wire adjacent to plant (going east)
    if not wire_cols_on_row:
        start_c = plant_cx + 4
        if 0 <= start_c < WORLD_W and (em[wire_row, start_c] or wm[wire_row, start_c]):
            return (Tool.WIRE, start_c, wire_row)
        return None

    min_wire_col = min(wire_cols_on_row)
    max_wire_col = max(wire_cols_on_row)

    # Phase 3: Extend wire spine eastward
    if max_wire_col < target_right:
        nc = max_wire_col + 1
        if nc < WORLD_W and not pm[wire_row, nc]:
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # Phase 4: Extend wire spine westward toward plant
    if min_wire_col > target_left:
        nc = min_wire_col - 1
        if nc >= 0 and not pm[wire_row, nc]:
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # Phase 5: Build road row parallel to wire
    for c in wire_cols_on_row:
        if 0 <= c < WORLD_W and 0 <= road_row < WORLD_H:
            if not rm[road_row, c] and em[road_row, c]:
                return (Tool.ROAD, c, road_row)

    # Phase 6: Place zones along the corridor (north and south)
    zone_cols = list(range(max(1, target_left), min(WORLD_W - 1, target_right + 1), 4))

    for zc in zone_cols:
        wire_near = any(abs(zc - wc) <= 2 for wc in wire_cols_on_row)
        road_near = any(abs(zc - rc) <= 2 for rc in road_cols_on_row)

        if wire_near and road_near:
            # North zones
            zr = north_zone_row
            if 1 <= zr <= WORLD_H - 2:
                if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                    if has_wire_nearby(zr, zc, 5) and has_road_nearby(zr, zc, 5):
                        return (pick_tool(), zc, zr)

            # South zones
            zr = south_zone_row
            if 1 <= zr <= WORLD_H - 2:
                if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                    if has_wire_nearby(zr, zc, 5) and has_road_nearby(zr, zc, 5):
                        return (pick_tool(), zc, zr)

    # Phase 7: Vertical wires from spine to reach north zones
    for wc in wire_cols_on_row:
        for wr in range(wire_row - 1, max(north_zone_row - 2, 0), -1):
            if 0 <= wr < WORLD_H:
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc]:
                    break

    # Phase 8: Vertical roads from road_row to south zones
    for rc in road_cols_on_row:
        for rr in range(road_row + 1, min(south_zone_row + 2, WORLD_H)):
            if 0 <= rr < WORLD_H:
                if rm[rr, rc]:
                    break
                if em[rr, rc] and not pm[rr, rc]:
                    return (Tool.ROAD, rc, rr)
                elif not em[rr, rc]:
                    break

    # Phase 9: Second horizontal cluster below when pop >= 150
    if obs.city_pop >= 150:
        wire_row2 = south_zone_row + 5
        road_row2 = wire_row2 + 3
        north_zone_row2 = wire_row2 - 3
        south_zone_row2 = road_row2 + 3

        wire_row2 = max(3, min(WORLD_H - 4, wire_row2))
        road_row2 = max(3, min(WORLD_H - 4, road_row2))
        north_zone_row2 = max(1, min(WORLD_H - 2, north_zone_row2))
        south_zone_row2 = max(1, min(WORLD_H - 2, south_zone_row2))

        wire_cols2 = sorted([c for c in range(WORLD_W) if wm[wire_row2, c]])
        road_cols2 = set(c for c in range(WORLD_W) if rm[road_row2, c])

        if not wire_cols2:
            # Build vertical wire bridge from main wire row to cluster2
            bridge_col = plant_cx + 4
            for wr in range(wire_row + 1, wire_row2 + 1):
                if 0 <= wr < WORLD_H:
                    if not wm[wr, bridge_col] and em[wr, bridge_col]:
                        return (Tool.WIRE, bridge_col, wr)
                    elif not em[wr, bridge_col] and not wm[wr, bridge_col]:
                        break
        else:
            min_wc2 = min(wire_cols2)
            max_wc2 = max(wire_cols2)

            if max_wc2 < target_right:
                nc = max_wc2 + 1
                if nc < WORLD_W and em[wire_row2, nc]:
                    return (Tool.WIRE, nc, wire_row2)
            if min_wc2 > target_left:
                nc = min_wc2 - 1
                if nc >= 0 and em[wire_row2, nc]:
                    return (Tool.WIRE, nc, wire_row2)

            for wc in wire_cols2:
                if wc not in road_cols2 and em[road_row2, wc]:
                    return (Tool.ROAD, wc, road_row2)

            road_cols2_list = sorted(list(road_cols2))
            for zc in zone_cols:
                wire_near2 = any(abs(zc - wc) <= 2 for wc in wire_cols2)
                road_near2 = any(abs(zc - rc) <= 2 for rc in road_cols2_list)
                if wire_near2 and road_near2:
                    for zr in [north_zone_row2, south_zone_row2]:
                        if 1 <= zr <= WORLD_H - 2:
                            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                                if has_wire_nearby(zr, zc, 6) and has_road_nearby(zr, zc, 5):
                                    return (pick_tool(), zc, zr)

            for wc in wire_cols2:
                for wr in range(wire_row2 - 1, max(north_zone_row2 - 2, 0), -1):
                    if 0 <= wr < WORLD_H:
                        if wm[wr, wc]: break
                        if em[wr, wc] and not pm[wr, wc]:
                            return (Tool.WIRE, wc, wr)
                        elif not em[wr, wc]: break

            for rc in road_cols2_list:
                for rr in range(road_row2 + 1, min(south_zone_row2 + 2, WORLD_H)):
                    if 0 <= rr < WORLD_H:
                        if rm[rr, rc]: break
                        if em[rr, rc] and not pm[rr, rc]:
                            return (Tool.ROAD, rc, rr)
                        elif not em[rr, rc]: break

    # Phase 10: Second power plant when pop > 300
    if obs.city_pop > 300 and int(np.sum(pm)) < 9:
        # Place east of existing plant
        px2 = plant_cx + 25
        py2 = plant_cy
        if 2 <= py2 <= WORLD_H - 3 and 2 <= px2 <= WORLD_W - 3:
            area_clear = True
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if not (em[py2 + dr, px2 + dc] or pm[py2 + dr, px2 + dc]):
                        area_clear = False
            if area_clear:
                return (Tool.COALPOWER, px2, py2)

    # Phase 11: Third cluster above main when pop >= 400
    if obs.city_pop >= 400:
        wire_row3 = north_zone_row - 5
        road_row3 = wire_row3 - 3
        north_zone_row3 = road_row3 - 3
        south_zone_row3 = wire_row3 + 3

        wire_row3 = max(3, min(WORLD_H - 4, wire_row3))
        road_row3 = max(3, min(WORLD_H - 4, road_row3))
        north_zone_row3 = max(1, min(WORLD_H - 2, north_zone_row3))
        south_zone_row3 = max(1, min(WORLD_H - 2, south_zone_row3))

        wire_cols3 = sorted([c for c in range(WORLD_W) if wm[wire_row3, c]])

        if not wire_cols3:
            bridge_col3 = plant_cx + 4
            for wr in range(wire_row - 1, wire_row3 - 1, -1):
                if 0 <= wr < WORLD_H:
                    if not wm[wr, bridge_col3] and em[wr, bridge_col3]:
                        return (Tool.WIRE, bridge_col3, wr)
                    elif not em[wr, bridge_col3] and not wm[wr, bridge_col3]:
                        break
        else:
            road_cols3 = set(c for c in range(WORLD_W) if rm[road_row3, c])
            road_cols3_list = sorted(list(road_cols3))
            min_wc3 = min(wire_cols3)
            max_wc3 = max(wire_cols3)

            if max_wc3 < target_right:
                nc = max_wc3 + 1
                if nc < WORLD_W and em[wire_row3, nc]:
                    return (Tool.WIRE, nc, wire_row3)
            if min_wc3 > target_left:
                nc = min_wc3 - 1
                if nc >= 0 and em[wire_row3, nc]:
                    return (Tool.WIRE, nc, wire_row3)

            for wc in wire_cols3:
                if wc not in road_cols3 and em[road_row3, wc]:
                    return (Tool.ROAD, wc, road_row3)

            for zc in zone_cols:
                wire_near3 = any(abs(zc - wc) <= 2 for wc in wire_cols3)
                road_near3 = any(abs(zc - rc) <= 2 for rc in road_cols3_list)
                if wire_near3 and road_near3:
                    for zr in [north_zone_row3, south_zone_row3]:
                        if 1 <= zr <= WORLD_H - 2:
                            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                                if has_wire_nearby(zr, zc, 6) and has_road_nearby(zr, zc, 5):
                                    return (pick_tool(), zc, zr)

    return None

def act(obs, state):
    """
    Revised policy: horizontal layout instead of vertical spine.
    - Power plant at left-center
    - Wire spine runs HORIZONTALLY from plant
    - Road runs horizontally below wire spine
    - Zones placed above and below road in a grid pattern
    - Better zone mix tracking
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    all_zone = resm | comm | indm

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(total_zones, 1)
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        if com_count / t < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone[rr, rc]:
                    return False
        return True

    def zone_exists_near(zr, zc, r=3):
        r0 = max(0, zr - r); r1 = min(WORLD_H, zr + r + 1)
        c0 = max(0, zc - r); c1 = min(WORLD_W, zc + r + 1)
        return np.any(all_zone[r0:r1, c0:c1])

    def wire_near(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def road_near(zr, zc, radius=3):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    # --- Phase 1: Place coal power plant if missing ---
    if not np.any(pm):
        # Place plant at left side, vertically centered
        px, py = cx - 30, cy
        return (Tool.COALPOWER, px, py)

    # Find plant location
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Horizontal layout geometry
    wire_row = plant_cy          # wire spine same row as plant center
    road_row = wire_row + 3      # road runs 3 below wire
    upper_zone_row = wire_row - 4  # zones above wire
    lower_zone_row = road_row + 4  # zones below road

    # Clamp rows
    wire_row = max(2, min(WORLD_H - 3, wire_row))
    road_row = max(2, min(WORLD_H - 3, road_row))
    upper_zone_row = max(2, min(WORLD_H - 3, upper_zone_row))
    lower_zone_row = max(2, min(WORLD_H - 3, lower_zone_row))

    pop = obs.city_pop
    if pop < 50:
        half = 8
    elif pop < 200:
        half = 16
    elif pop < 500:
        half = 24
    else:
        half = 35

    x_start = plant_cx + 2
    x_min = max(2, x_start)
    x_max = min(WORLD_W - 3, x_start + half * 2)

    # Current wire spine cols and road cols
    wire_cols = sorted([c for c in range(WORLD_W) if wm[wire_row, c]])
    road_cols = sorted([c for c in range(WORLD_W) if rm[road_row, c]])

    # --- Phase 2: Start wire spine adjacent to plant ---
    if not wire_cols:
        for dx in range(1, 10):
            nc = plant_cx + dx
            if 0 <= nc < WORLD_W and em[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)
        return None

    min_wc = min(wire_cols)
    max_wc = max(wire_cols)

    # --- Phase 3: Extend wire spine horizontally to the right ---
    if max_wc < x_max:
        nc = max_wc + 1
        if nc < WORLD_W and em[wire_row, nc] and not pm[wire_row, nc]:
            return (Tool.WIRE, nc, wire_row)

    # Also extend leftward if needed
    if min_wc > x_min:
        nc = min_wc - 1
        if nc >= 0 and em[wire_row, nc] and not pm[wire_row, nc]:
            return (Tool.WIRE, nc, wire_row)

    # --- Phase 4: Build road parallel to wire (horizontal) ---
    for c in wire_cols:
        if x_min <= c <= x_max:
            if 0 <= road_row < WORLD_H and em[road_row, c] and not pm[road_row, c]:
                return (Tool.ROAD, c, road_row)

    # --- Phase 5: Connect plant to wire if not connected ---
    connected = False
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            rr, rc = plant_cy + dr, plant_cx + dc
            if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                if wm[rr, rc]:
                    connected = True
    if not connected and wire_cols:
        bridge_c = plant_cx
        for br in range(plant_cy, wire_row - 1, -1):
            if 0 <= br < WORLD_H:
                if wm[br, bridge_c]:
                    break
                if em[br, bridge_c]:
                    return (Tool.WIRE, bridge_c, br)

    # --- Phase 6: Place zones above and below ---
    zone_cols = list(range(x_min, x_max + 1, 4))

    # Upper zones (above wire spine)
    for zc in zone_cols:
        zr = upper_zone_row
        w_close = any(abs(zc - wc) <= 3 for wc in wire_cols)
        r_close = any(abs(zc - rc) <= 3 for rc in road_cols)
        if w_close and r_close:
            if not zone_exists_near(zr, zc) and zone_area_ok(zr, zc):
                if wire_near(zr, zc) and road_near(zr, zc):
                    return (pick_tool(), zc, zr)

    # Lower zones (below road)
    for zc in zone_cols:
        zr = lower_zone_row
        w_close = any(abs(zc - wc) <= 3 for wc in wire_cols)
        r_close = any(abs(zc - rc) <= 3 for rc in road_cols)
        if w_close and r_close:
            if not zone_exists_near(zr, zc) and zone_area_ok(zr, zc):
                if wire_near(zr, zc) and road_near(zr, zc):
                    return (pick_tool(), zc, zr)

    # --- Phase 7: Vertical wires connecting spine to upper zones ---
    for wc in wire_cols:
        if x_min <= wc <= x_max:
            for wr in range(wire_row - 1, upper_zone_row - 2, -1):
                if wr < 0:
                    break
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc] and not wm[wr, wc]:
                    break

    # --- Phase 8: Vertical wires connecting spine down to road level ---
    for wc in wire_cols:
        if x_min <= wc <= x_max:
            for wr in range(wire_row + 1, road_row):
                if wr >= WORLD_H:
                    break
                if wm[wr, wc]:
                    break
                if rm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc] and not wm[wr, wc]:
                    break

    # --- Phase 9: Second power plant if population growing ---
    plant_count = max(1, int(np.sum(pm)) // 9)
    if pop > 200 and plant_count < 2:
        px2 = plant_cx
        py2 = plant_cy + 15
        if 2 <= px2 <= WORLD_W - 3 and 2 <= py2 <= WORLD_H - 3:
            area_ok = True
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if not em[py2 + dr, px2 + dc]:
                        area_ok = False
            if area_ok:
                return (Tool.COALPOWER, px2, py2)

    # --- Phase 10: Add second horizontal corridor below ---
    if pop > 300:
        wire_row2 = lower_zone_row + 5
        road_row2 = wire_row2 + 3
        wire_row2 = max(2, min(WORLD_H - 3, wire_row2))
        road_row2 = max(2, min(WORLD_H - 3, road_row2))

        wire_cols2 = sorted([c for c in range(WORLD_W) if wm[wire_row2, c]])
        road_cols2 = sorted([c for c in range(WORLD_W) if rm[road_row2, c]])

        # Extend wire in second corridor
        if not wire_cols2:
            # Start from x_min
            if em[wire_row2, x_min]:
                return (Tool.WIRE, x_min, wire_row2)
        else:
            mwc2 = max(wire_cols2)
            if mwc2 < x_max:
                nc = mwc2 + 1
                if nc < WORLD_W and em[wire_row2, nc]:
                    return (Tool.WIRE, nc, wire_row2)

        # Road in second corridor
        for c in wire_cols2:
            if x_min <= c <= x_max:
                if em[road_row2, c] and not pm[road_row2, c]:
                    return (Tool.ROAD, c, road_row2)

        # Zones in second corridor
        lower2_row = road_row2 + 4
        lower2_row = max(2, min(WORLD_H - 3, lower2_row))
        for zc in zone_cols:
            zr = lower2_row
            w2_close = any(abs(zc - wc) <= 3 for wc in wire_cols2)
            r2_close = any(abs(zc - rc) <= 3 for rc in road_cols2)
            if w2_close and r2_close:
                if not zone_exists_near(zr, zc) and zone_area_ok(zr, zc):
                    if wire_near(zr, zc, 6) and road_near(zr, zc, 5):
                        return (pick_tool(), zc, zr)

        # Connect corridor 2 wire to main via vertical wire
        if wire_cols2:
            bridge_c2 = min(wire_cols2)
            for br in range(wire_row + 1, wire_row2):
                if 0 <= br < WORLD_H and em[br, bridge_c2] and not pm[br, bridge_c2]:
                    if not wm[br, bridge_c2]:
                        return (Tool.WIRE, bridge_c2, br)

    # --- Phase 11: Horizontal roads for connectivity ---
    if pop > 150:
        # Add a second road row near upper zones
        upper_road_row = upper_zone_row - 4
        upper_road_row = max(2, min(WORLD_H - 3, upper_road_row))
        for c in wire_cols:
            if x_min <= c <= x_max and em[upper_road_row, c] and not pm[upper_road_row, c]:
                return (Tool.ROAD, c, upper_road_row)

    # --- Phase 12: Fill missed zones ---
    if pop > 100:
        for zr in [upper_zone_row - 4, lower_zone_row + 4]:
            zr_c = max(2, min(WORLD_H - 3, zr))
            for zc in zone_cols:
                if not zone_exists_near(zr_c, zc) and zone_area_ok(zr_c, zc):
                    if wire_near(zr_c, zc, 6) and road_near(zr_c, zc, 6):
                        return (pick_tool(), zc, zr_c)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder.
    Reads tile_map every step to decide next action.
    Strategy: single compact cluster, wire spine from coal plant,
    road columns flanking wire, zones adjacent to roads.
    All decisions based on current map state (high reactivity).
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Cluster center
    cx, cy = 55, 50

    # Plant anchor
    plant_cx, plant_cy = cx - 10, cy

    # Wire spine column
    wire_col = plant_cx + 3
    # Road columns flanking wire
    road_col_r = wire_col + 2
    road_col_l = wire_col - 2
    # Zone columns
    zone_col_r = road_col_r + 3
    zone_col_l = road_col_l - 3

    has_plant = bool(np.any(pm))

    # Phase 1: Place coal plant if missing
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Determine vertical span based on population
    base_span = 8
    extra_span = min(20, int(obs.city_pop) // 25)
    target_span = base_span + extra_span
    tmin = max(2, cy - target_span)
    tmax = min(WORLD_H - 3, cy + target_span)

    # Find existing wire rows in wire spine column
    wire_col_rows = [r for r in range(WORLD_H) if bool(wm[r, wire_col])]

    # Phase 2: Extend wire spine adjacent to power sources
    # Find all power (plant tiles + wire) positions
    power_map = pm | wm

    if not wire_col_rows:
        # Place first wire adjacent to plant
        for dy in range(-2, 3):
            ny = plant_cy + dy
            if in_bounds(wire_col, ny) and bool(em[ny, wire_col]):
                # Check adjacency to plant
                adj = False
                for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
                    nx2, ny2 = wire_col+ddx, ny+ddy
                    if in_bounds(nx2, ny2) and bool(pm[ny2, nx2]):
                        adj = True; break
                if adj:
                    return (Tool.WIRE, wire_col, ny)
        # Fallback: just place at plant_cy
        if in_bounds(wire_col, plant_cy) and bool(em[plant_cy, wire_col]):
            return (Tool.WIRE, wire_col, plant_cy)
    else:
        min_wr = min(wire_col_rows)
        max_wr = max(wire_col_rows)
        # Extend downward
        if max_wr < tmax:
            nr = max_wr + 1
            if in_bounds(wire_col, nr) and (bool(em[nr, wire_col]) or bool(wm[nr, wire_col])):
                return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if min_wr > tmin:
            nr = min_wr - 1
            if in_bounds(wire_col, nr) and (bool(em[nr, wire_col]) or bool(wm[nr, wire_col])):
                return (Tool.WIRE, wire_col, nr)

    wire_rows_set = set(wire_col_rows)

    # Phase 3: Build road columns adjacent to wire spine
    if wire_col_rows:
        # Right road column
        for wr in wire_col_rows:
            if in_bounds(road_col_r, wr) and bool(em[wr, road_col_r]):
                return (Tool.ROAD, road_col_r, wr)
        # Left road column
        for wr in wire_col_rows:
            if in_bounds(road_col_l, wr) and bool(em[wr, road_col_l]):
                return (Tool.ROAD, road_col_l, wr)

    # Collect zone info
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    all_zones_mask = resm | comm | indm
    zone_positions = set(zip(*np.where(all_zones_mask))) if np.any(all_zones_mask) else set()

    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not in_bounds(rc, rr):
                    return False
                # Allow empty or existing zone tiles (zones are 3x3)
                if not (bool(em[rr, rc]) or bool(all_zones_mask[rr, rc])):
                    return False
        return True

    def already_zone_nearby(zr, zc):
        for (pr, pc) in zone_positions:
            if abs(zr - pr) <= 2 and abs(zc - pc) <= 2:
                return True
        return False

    def choose_zone_tool():
        t = max(total_zones, 1)
        if com_count / t < 0.22:
            return Tool.COMMERCIAL
        if ind_count / t < 0.22:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Phase 4: Place zones adjacent to roads
    road_rows_r = set(r for r in range(WORLD_H) if bool(rm[r, road_col_r]))
    road_rows_l = set(r for r in range(WORLD_H) if bool(rm[r, road_col_l]))

    for zr in sorted(wire_rows_set):
        # Right zone column
        road_ok_r = any(abs(zr - rr) <= 2 for rr in road_rows_r)
        wire_ok = zr in wire_rows_set or any(abs(zr - wr) <= 1 for wr in wire_rows_set)
        if road_ok_r and wire_ok:
            zc = zone_col_r
            if in_bounds(zc, zr) and not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                return (choose_zone_tool(), zc, zr)
        # Left zone column
        road_ok_l = any(abs(zr - rr) <= 2 for rr in road_rows_l)
        if road_ok_l and wire_ok:
            zc = zone_col_l
            if in_bounds(zc, zr) and not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                return (choose_zone_tool(), zc, zr)

    # Phase 5: Second cluster when population is large
    if obs.city_pop > 150:
        wire_col2 = wire_col + 20
        road_col2_r = wire_col2 + 2
        zone_col2_r = road_col2_r + 3

        wire_col2_rows = [r for r in range(WORLD_H) if bool(wm[r, wire_col2])]

        if not wire_col2_rows:
            # Connect horizontally from main spine
            # Find a wire row near cy in main spine
            if wire_col_rows:
                base_r = min(wire_rows_set, key=lambda r: abs(r - cy))
                # Lay horizontal wire from main spine to new column
                for wc in range(wire_col + 1, wire_col2 + 1):
                    if in_bounds(wc, base_r):
                        # Check adjacency to existing power
                        adj = False
                        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
                            nx2, ny2 = wc+ddx, base_r+ddy
                            if in_bounds(nx2, ny2) and bool(power_map[ny2, nx2]):
                                adj = True; break
                        if adj and bool(em[base_r, wc]):
                            return (Tool.WIRE, wc, base_r)
        else:
            min_wr2 = min(wire_col2_rows)
            max_wr2 = max(wire_col2_rows)
            tmax2 = min(WORLD_H - 3, cy + target_span)
            tmin2 = max(2, cy - target_span)
            if max_wr2 < tmax2:
                nr = max_wr2 + 1
                if in_bounds(wire_col2, nr) and bool(em[nr, wire_col2]):
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > tmin2:
                nr = min_wr2 - 1
                if in_bounds(wire_col2, nr) and bool(em[nr, wire_col2]):
                    return (Tool.WIRE, wire_col2, nr)

            # Build road column
            for wr in wire_col2_rows:
                if in_bounds(road_col2_r, wr) and bool(em[wr, road_col2_r]):
                    return (Tool.ROAD, road_col2_r, wr)

            # Place zones
            road_rows2_r = set(r for r in range(WORLD_H) if bool(rm[r, road_col2_r]))
            wire2_set = set(wire_col2_rows)
            for zr in sorted(wire2_set):
                road_ok = any(abs(zr - rr) <= 2 for rr in road_rows2_r)
                wire_ok2 = zr in wire2_set
                if road_ok and wire_ok2:
                    zc = zone_col2_r
                    if in_bounds(zc, zr) and not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                        return (choose_zone_tool(), zc, zr)

    # Phase 6: Services when warranted
    if obs.city_pop > 300:
        for fx, fy in [(wire_col + 5, cy - 12), (wire_col - 5, cy + 12)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.FIRESTATION, fx, fy)

    # Fallback: find any empty tile adjacent to road and wire, place zone
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for shift in [-2, -1, 0, 1, 2]:
        if shift > 0:
            nbr_road[shift:, :] |= rm[:WORLD_H-shift, :]
            nbr_road[:, shift:] |= rm[:, :WORLD_W-shift]
        elif shift < 0:
            nbr_road[:WORLD_H+shift, :] |= rm[-shift:, :]
            nbr_road[:, :WORLD_W+shift] |= rm[:, -shift:]
        else:
            nbr_road |= rm

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for shift_r in range(-4, 5):
        for shift_c in range(-4, 5):
            sr0 = max(0, -shift_r); sr1 = min(WORLD_H, WORLD_H - shift_r)
            sc0 = max(0, -shift_c); sc1 = min(WORLD_W, WORLD_W - shift_c)
            r0 = max(0, shift_r); r1 = min(WORLD_H, WORLD_H + shift_r)
            c0 = max(0, shift_c); c1 = min(WORLD_W, WORLD_W + shift_c)
            nbr_power[r0:r1, c0:c1] |= (wm | pm)[sr0:sr1, sc0:sc1]

    cand = em & nbr_road & nbr_power
    cand[:2, :] = False
    cand[WORLD_H-2:, :] = False
    cand[:, :2] = False
    cand[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        key = int(obs.step * 17 + int(obs.city_pop) * 3 + 1) % len(cxs)
        for offset in range(min(len(cxs), 60)):
            k = (key + offset * 11) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            ok = True
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    ny2, nx2 = zy + dr, zx + dc
                    if not in_bounds(nx2, ny2):
                        ok = False; break
                    if not (bool(em[ny2, nx2]) or bool(all_zones_mask[ny2, nx2])):
                        ok = False; break
                if not ok:
                    break
            if ok and not already_zone_nearby(zy, zx):
                return (choose_zone_tool(), zx, zy)

    # Last resort: extend road from existing road
    rys, rxs = np.where(rm)
    if len(rxs) > 0:
        k2 = int(obs.step * 13) % len(rxs)
        rx2, ry2 = int(rxs[k2]), int(rys[k2])
        for ddx, ddy in [(0,1),(0,-1),(1,0),(-1,0)]:
            nx2, ny2 = rx2+ddx, ry2+ddy
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # Extend wire from existing wire
    wys, wxs = np.where(wm)
    if len(wxs) > 0:
        k3 = int(obs.step * 7) % len(wxs)
        wx2, wy2 = int(wxs[k3]), int(wys[k3])
        for ddx, ddy in [(0,1),(0,-1),(1,0),(-1,0)]:
            nx2, ny2 = wx2+ddx, wy2+ddy
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map every step and reacts to current state.
    Strategy:
    - Place coal power plant near center-left
    - Wire spine from plant rightward (horizontal spine instead of vertical)
    - Build road rows above and below spine
    - Place zones between roads and spine
    - Adapt based on what's actually on the map
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(total_zones, 1)
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Phase 1: Place coal power plant if missing
    if not np.any(pm):
        px, py = cx - 20, cy
        px = max(4, min(WORLD_W - 5, px))
        py = max(4, min(WORLD_H - 5, py))
        return (Tool.COALPOWER, px, py)

    # Find plant centroid
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Horizontal wire spine row
    wire_row = plant_cy
    # Roads above and below spine
    top_road_row = wire_row - 4
    bot_road_row = wire_row + 4
    # Zone rows (centered between roads and spine)
    top_zone_row = wire_row - 7
    bot_zone_row = wire_row + 7

    # Clamp
    wire_row = max(2, min(WORLD_H - 3, wire_row))
    top_road_row = max(2, min(WORLD_H - 3, top_road_row))
    bot_road_row = max(2, min(WORLD_H - 3, bot_road_row))
    top_zone_row = max(2, min(WORLD_H - 3, top_zone_row))
    bot_zone_row = max(2, min(WORLD_H - 3, bot_zone_row))

    # Spine extent based on population
    if obs.city_pop < 50:
        spine_extent = 8
    elif obs.city_pop < 200:
        spine_extent = 16
    elif obs.city_pop < 500:
        spine_extent = 24
    elif obs.city_pop < 900:
        spine_extent = 36
    else:
        spine_extent = 50

    target_left = max(1, plant_cx + 4)
    target_right = min(WORLD_W - 2, plant_cx + 4 + spine_extent)

    # Current wire positions on spine row
    wire_cols_on_spine = sorted([c for c in range(WORLD_W) if wm[wire_row, c]])

    # Phase 2: Start wire adjacent to plant if none on spine
    if not wire_cols_on_spine:
        # Place wire just right of plant
        for dc in range(3, 8):
            nc = plant_cx + dc
            if 0 <= nc < WORLD_W and (em[wire_row, nc] or wm[wire_row, nc]):
                return (Tool.WIRE, nc, wire_row)
        return None

    min_wire_col = min(wire_cols_on_spine)
    max_wire_col = max(wire_cols_on_spine)

    # Phase 3: Extend wire spine rightward
    if max_wire_col < target_right:
        nc = max_wire_col + 1
        if nc < WORLD_W and not pm[wire_row, nc]:
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # Phase 4: Extend wire spine leftward to plant if gap
    if min_wire_col > target_left:
        nc = min_wire_col - 1
        if nc >= 0 and not pm[wire_row, nc]:
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # Phase 5: Build top road row (columns where spine exists)
    for c in wire_cols_on_spine:
        if 0 <= c < WORLD_W and 0 <= top_road_row < WORLD_H:
            if not rm[top_road_row, c] and em[top_road_row, c] and not pm[top_road_row, c]:
                return (Tool.ROAD, c, top_road_row)

    # Phase 6: Build bottom road row
    for c in wire_cols_on_spine:
        if 0 <= c < WORLD_W and 0 <= bot_road_row < WORLD_H:
            if not rm[bot_road_row, c] and em[bot_road_row, c] and not pm[bot_road_row, c]:
                return (Tool.ROAD, c, bot_road_row)

    all_zone_mask = resm | comm | indm

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=5):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    # Phase 7: Vertical wires from spine up/down to zone rows
    # For each spine col, extend wire vertically toward zone rows
    for wr in wire_cols_on_spine:
        # Upward from spine
        for row in range(wire_row - 1, top_zone_row - 2, -1):
            if 0 <= row < WORLD_H:
                if wm[row, wr] or pm[row, wr]:
                    break
                if em[row, wr] and not rm[row, wr]:
                    return (Tool.WIRE, wr, row)
                elif not em[row, wr] and not wm[row, wr]:
                    break
        # Downward from spine
        for row in range(wire_row + 1, bot_zone_row + 2):
            if 0 <= row < WORLD_H:
                if wm[row, wr] or pm[row, wr]:
                    break
                if em[row, wr] and not rm[row, wr]:
                    return (Tool.WIRE, wr, row)
                elif not em[row, wr] and not wm[row, wr]:
                    break

    # Phase 8: Place zones along top and bottom zone rows
    top_road_cols = sorted([c for c in range(WORLD_W) if rm[top_road_row, c]])
    bot_road_cols = sorted([c for c in range(WORLD_W) if rm[bot_road_row, c]])

    zone_cols = list(range(max(1, target_left), min(WORLD_W - 1, target_right), 3))

    for zc in zone_cols:
        wire_near_col = any(abs(zc - wc) <= 2 for wc in wire_cols_on_spine)
        if not wire_near_col:
            continue

        # Top zone
        zr = top_zone_row
        road_near = any(abs(zc - rc) <= 2 for rc in top_road_cols)
        if road_near:
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc) and has_road_nearby(zr, zc):
                    return (pick_tool(), zc, zr)

        # Bottom zone
        zr = bot_zone_row
        road_near = any(abs(zc - rc) <= 2 for rc in bot_road_cols)
        if road_near:
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc) and has_road_nearby(zr, zc):
                    return (pick_tool(), zc, zr)

        # Inner top zone (between spine and top road)
        inner_top = wire_row - 2
        inner_top = max(2, min(WORLD_H - 3, inner_top))
        if inner_top != wire_row and inner_top != top_road_row:
            if not zone_already_there(inner_top, zc) and zone_area_ok(inner_top, zc):
                if has_wire_nearby(inner_top, zc, 3) and has_road_nearby(inner_top, zc, 5):
                    return (pick_tool(), zc, inner_top)

        # Inner bottom zone
        inner_bot = wire_row + 2
        inner_bot = max(2, min(WORLD_H - 3, inner_bot))
        if inner_bot != wire_row and inner_bot != bot_road_row:
            if not zone_already_there(inner_bot, zc) and zone_area_ok(inner_bot, zc):
                if has_wire_nearby(inner_bot, zc, 3) and has_road_nearby(inner_bot, zc, 5):
                    return (pick_tool(), zc, inner_bot)

    # Phase 9: Second coal plant if population demands more power
    if obs.city_pop > 300 and np.sum(pm) < 18:
        px2 = plant_cx
        py2 = plant_cy + 20
        if 4 <= py2 <= WORLD_H - 5 and 4 <= px2 <= WORLD_W - 5:
            if em[py2, px2]:
                return (Tool.COALPOWER, px2, py2)

    # Phase 10: Extend spine even further for large populations
    if obs.city_pop > 600:
        extended_right = min(WORLD_W - 2, target_right + 10)
        if max_wire_col < extended_right:
            nc = max_wire_col + 1
            if nc < WORLD_W and not pm[wire_row, nc] and (em[wire_row, nc] or wm[wire_row, nc]):
                return (Tool.WIRE, nc, wire_row)

    # Phase 11: Extra zone rows far out for large populations
    if obs.city_pop > 400:
        far_top = top_zone_row - 4
        far_bot = bot_zone_row + 4
        for zr in [far_top, far_bot]:
            if 2 <= zr <= WORLD_H - 3:
                for zc in zone_cols:
                    if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                        if has_road_nearby(zr, zc, 6) and has_wire_nearby(zr, zc, 7):
                            return (pick_tool(), zc, zr)

    # Phase 12: Connect vertical roads between top and bottom roads through spine
    if obs.city_pop > 150 and wire_cols_on_spine:
        for vc in [min(wire_cols_on_spine), max(wire_cols_on_spine)]:
            if 0 <= vc < WORLD_W:
                for rr in range(min(top_road_row, bot_road_row),
                                max(top_road_row, bot_road_row) + 1):
                    if 0 <= rr < WORLD_H and em[rr, vc] and not pm[rr, vc] and not wm[rr, vc]:
                        return (Tool.ROAD, vc, rr)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map each step to decide next action.
    Strategy: build a compact grid of zones with wire spine + road access,
    expanding reactively based on what's actually on the map.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    # Zone counts for balanced placement
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    all_zone_mask = resm | comm | indm

    def zone_area_ok(zr, zc):
        """Check 3x3 area around center is empty or zone only"""
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc, radius=2):
        for dr in range(-radius, radius+1):
            for dc in range(-radius, radius+1):
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def wire_nearby(zr, zc, r=5):
        r0 = max(0, zr-r); r1 = min(WORLD_H, zr+r+1)
        c0 = max(0, zc-r); c1 = min(WORLD_W, zc+r+1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def road_nearby(zr, zc, r=4):
        r0 = max(0, zr-r); r1 = min(WORLD_H, zr+r+1)
        c0 = max(0, zc-r); c1 = min(WORLD_W, zc+r+1)
        return np.any(rm[r0:r1, c0:c1])

    # === Phase 1: Place coal power plant ===
    if not np.any(pm):
        # Place near center-left
        px, py = cx - 10, cy
        return (Tool.COALPOWER, px, py)

    # Find plant center
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # === Core geometry: wire spine, road column, zone columns ===
    # Wire spine runs vertically at plant_cx + 4
    # Road runs at wire_col + 2
    # Zones on left and right of road
    wire_col = plant_cx + 4
    road_col = wire_col + 2
    zone_col_left = wire_col - 3
    zone_col_right = road_col + 3

    wire_col = max(2, min(WORLD_W - 3, wire_col))
    road_col = max(2, min(WORLD_W - 3, road_col))
    zone_col_left = max(2, min(WORLD_W - 3, zone_col_left))
    zone_col_right = max(2, min(WORLD_W - 3, zone_col_right))

    # Dynamic spine extent based on actual population
    pop = obs.city_pop
    if pop < 50:
        extent = 8
    elif pop < 150:
        extent = 14
    elif pop < 400:
        extent = 20
    else:
        extent = 28

    t_min = max(1, cy - extent)
    t_max = min(WORLD_H - 2, cy + extent)

    # Read current wire/road state from map
    wire_on_spine = [r for r in range(WORLD_H) if wm[r, wire_col]]
    road_on_col = [r for r in range(WORLD_H) if rm[r, road_col]]
    road_set = set(road_on_col)

    # === Phase 2: Start wire spine adjacent to plant ===
    if not wire_on_spine:
        for dy in range(0, 8):
            for nr in [plant_cy + dy, plant_cy - dy]:
                if 0 <= nr < WORLD_H:
                    if em[nr, wire_col] or wm[nr, wire_col]:
                        return (Tool.WIRE, wire_col, nr)
        return None

    min_wr = min(wire_on_spine)
    max_wr = max(wire_on_spine)

    # === Phase 3: Extend wire spine downward ===
    if max_wr < t_max:
        nr = max_wr + 1
        if 0 <= nr < WORLD_H and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # === Phase 4: Extend wire spine upward ===
    if min_wr > t_min:
        nr = min_wr - 1
        if 0 <= nr < WORLD_H and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # === Phase 5: Build road column alongside wire spine ===
    for r in wire_on_spine:
        if 0 <= r < WORLD_H and 0 <= road_col < WORLD_W:
            if not rm[r, road_col] and em[r, road_col]:
                return (Tool.ROAD, road_col, r)

    # === Phase 6: Lateral wires from spine toward left zones ===
    for wr in wire_on_spine:
        for wc in range(wire_col - 1, max(zone_col_left - 2, 0), -1):
            if wm[wr, wc]:
                break
            if em[wr, wc] and not pm[wr, wc]:
                return (Tool.WIRE, wc, wr)
            elif not em[wr, wc] and not all_zone_mask[wr, wc]:
                break

    # === Phase 7: Road extensions toward right zones ===
    for rr in wire_on_spine:
        if not rm[rr, road_col]:
            continue
        for rc in range(road_col + 1, zone_col_right + 3):
            if 0 <= rc < WORLD_W:
                if rm[rr, rc]:
                    break
                if em[rr, rc] and not pm[rr, rc]:
                    return (Tool.ROAD, rc, rr)
                elif not em[rr, rc] and not all_zone_mask[rr, rc]:
                    break

    # === Phase 8: Wire to right zones ===
    for wr in wire_on_spine:
        for wc in range(wire_col + 1, zone_col_right + 3):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc] and not rm[wr, wc] and not all_zone_mask[wr, wc]:
                    break

    # === Phase 9: Place zones reactively ===
    zone_rows = list(range(max(2, t_min), min(WORLD_H - 1, t_max + 1), 3))

    for zr in zone_rows:
        # Check if wire and road actually present near this row (from map)
        w_near = any(abs(zr - wr) <= 3 for wr in wire_on_spine)
        r_near = any(abs(zr - rr) <= 3 for rr in road_on_col)

        if not (w_near and r_near):
            continue

        # Try left zone
        zc = zone_col_left
        if 2 <= zc <= WORLD_W - 3:
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if wire_nearby(zr, zc, 5) and road_nearby(zr, zc, 5):
                    return (pick_tool(), zc, zr)

        # Try right zone
        zc = zone_col_right
        if 2 <= zc <= WORLD_W - 3:
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if wire_nearby(zr, zc, 6) and road_nearby(zr, zc, 5):
                    return (pick_tool(), zc, zr)

    # === Phase 10: Second power plant when city grows ===
    plant_count = int(np.sum(pm))
    if pop > 250 and plant_count < 9:
        # Check if we need more power (few powered zones)
        if obs.powered_zones < total_zones * 0.7:
            px2 = plant_cx - 15
            py2 = plant_cy
            if 2 <= px2 <= WORLD_W - 3 and 2 <= py2 <= WORLD_H - 3:
                area_ok = True
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if not em[py2+dr, px2+dc] and not pm[py2+dr, px2+dc]:
                            area_ok = False
                if area_ok:
                    return (Tool.COALPOWER, px2, py2)

    # === Phase 11: Expand second cluster to the right when pop >= 200 ===
    if pop >= 200:
        wire_col2 = road_col + 10
        road_col2 = wire_col2 + 2
        lzc2 = wire_col2 - 3
        rzc2 = road_col2 + 3

        wire_col2 = max(2, min(WORLD_W - 3, wire_col2))
        road_col2 = max(2, min(WORLD_W - 3, road_col2))
        lzc2 = max(2, min(WORLD_W - 3, lzc2))
        rzc2 = max(2, min(WORLD_W - 3, rzc2))

        wire_rows2 = [r for r in range(WORLD_H) if wm[r, wire_col2]]
        road_set2 = set(r for r in range(WORLD_H) if rm[r, road_col2])

        # Connect from main wire spine horizontally
        if not wire_rows2:
            for wc in range(wire_col + 1, wire_col2 + 1):
                if 0 <= wc < WORLD_W:
                    if wm[plant_cy, wc]:
                        continue
                    if em[plant_cy, wc] and not pm[plant_cy, wc]:
                        return (Tool.WIRE, wc, plant_cy)
                    elif not em[plant_cy, wc] and not wm[plant_cy, wc]:
                        break
        else:
            min_wr2 = min(wire_rows2)
            max_wr2 = max(wire_rows2)

            if max_wr2 < t_max:
                nr = max_wr2 + 1
                if nr < WORLD_H and em[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > t_min:
                nr = min_wr2 - 1
                if nr >= 0 and em[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)

            for wr in wire_rows2:
                if wr not in road_set2 and em[wr, road_col2]:
                    return (Tool.ROAD, road_col2, wr)

            for zr in zone_rows:
                w2_near = any(abs(zr - wr) <= 3 for wr in wire_rows2)
                r2_near = any(abs(zr - rr) <= 3 for rr in road_set2)
                if w2_near and r2_near:
                    for zc in [lzc2, rzc2]:
                        if 2 <= zc <= WORLD_W - 3:
                            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                                if wire_nearby(zr, zc, 6) and road_nearby(zr, zc, 5):
                                    return (pick_tool(), zc, zr)

            # Lateral wires for cluster 2
            for wr in wire_rows2:
                for wc in range(wire_col2 - 1, max(lzc2 - 2, 0), -1):
                    if wm[wr, wc]: break
                    if em[wr, wc] and not pm[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    elif not em[wr, wc] and not all_zone_mask[wr, wc]: break

            # Road to right zones of cluster 2
            for wr in wire_rows2:
                if wr not in road_set2: continue
                for rc in range(road_col2 + 1, rzc2 + 3):
                    if 0 <= rc < WORLD_W:
                        if rm[wr, rc]: break
                        if em[wr, rc] and not pm[wr, rc]:
                            return (Tool.ROAD, rc, wr)
                        elif not em[wr, rc] and not all_zone_mask[wr, rc]: break

    # === Phase 12: Left cluster when pop >= 350 ===
    if pop >= 350:
        wire_col3 = wire_col - 12
        road_col3 = wire_col3 - 2
        lzc3 = road_col3 - 3
        rzc3 = wire_col3 + 3

        wire_col3 = max(2, min(WORLD_W - 3, wire_col3))
        road_col3 = max(2, min(WORLD_W - 3, road_col3))
        lzc3 = max(2, min(WORLD_W - 3, lzc3))
        rzc3 = max(2, min(WORLD_W - 3, rzc3))

        wire_rows3 = [r for r in range(WORLD_H) if wm[r, wire_col3]]
        road_set3 = set(r for r in range(WORLD_H) if rm[r, road_col3])

        if not wire_rows3:
            for wc in range(wire_col - 1, wire_col3 - 1, -1):
                if 0 <= wc < WORLD_W:
                    if wm[plant_cy, wc]: continue
                    if em[plant_cy, wc] and not pm[plant_cy, wc]:
                        return (Tool.WIRE, wc, plant_cy)
                    elif not em[plant_cy, wc] and not wm[plant_cy, wc]: break
        else:
            min_wr3 = min(wire_rows3)
            max_wr3 = max(wire_rows3)

            if max_wr3 < t_max:
                nr = max_wr3 + 1
                if nr < WORLD_H and em[nr, wire_col3]:
                    return (Tool.WIRE, wire_col3, nr)
            if min_wr3 > t_min:
                nr = min_wr3 - 1
                if nr >= 0 and em[nr, wire_col3]:
                    return (Tool.WIRE, wire_col3, nr)

            for wr in wire_rows3:
                if wr not in road_set3 and em[wr, road_col3]:
                    return (Tool.ROAD, road_col3, wr)

            for zr in zone_rows:
                w3_near = any(abs(zr - wr) <= 3 for wr in wire_rows3)
                r3_near = any(abs(zr - rr) <= 3 for rr in road_set3)
                if w3_near and r3_near:
                    for zc in [lzc3, rzc3]:
                        if 2 <= zc <= WORLD_W - 3:
                            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                                if wire_nearby(zr, zc, 6) and road_nearby(zr, zc, 5):
                                    return (pick_tool(), zc, zr)

            for wr in wire_rows3:
                for wc in range(wire_col3 + 1, min(rzc3 + 2, WORLD_W)):
                    if wm[wr, wc]: break
                    if em[wr, wc] and not pm[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    elif not em[wr, wc] and not all_zone_mask[wr, wc]: break

            for wr in wire_rows3:
                if wr not in road_set3: continue
                for rc in range(road_col3 - 1, max(lzc3 - 2, 0), -1):
                    if 0 <= rc < WORLD_W:
                        if rm[wr, rc]: break
                        if em[wr, rc] and not pm[wr, rc]:
                            return (Tool.ROAD, rc, wr)
                        elif not em[wr, rc] and not all_zone_mask[wr, rc]: break

    # === Phase 13: Fill in missing roads adjacent to placed zones ===
    # Scan for zones without road access - place road adjacent reactively
    zone_locs = np.argwhere(all_zone_mask)
    for loc in zone_locs:
        zr, zc = int(loc[0]), int(loc[1])
        # Check if zone has road neighbor
        has_road = False
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1),(-2,0),(2,0),(0,-2),(0,2)]:
            nr, nc = zr+dr, zc+dc
            if 0 <= nr < WORLD_H and 0 <= nc < WORLD_W and rm[nr, nc]:
                has_road = True
                break
        if not has_road:
            # Place road at nearest empty neighbor
            for dr, dc in [(-2,0),(2,0),(0,-2),(0,2)]:
                nr, nc = zr+dr, zc+dc
                if 0 <= nr < WORLD_H and 0 <= nc < WORLD_W and em[nr, nc]:
                    return (Tool.ROAD, nc, nr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads current map each step to decide what to place next
    - Builds a compact cluster: coal plant -> wire spine -> road grid -> zones
    - Adapts placement based on what already exists
    """
    tm = obs.tile_map
    step = obs.step

    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    # Cluster center
    cx, cy = 55, 50

    # Power plant target position (left of cluster)
    plant_x, plant_y = 20, 50

    # --- Phase 1: Ensure we have a coal power plant ---
    if not np.any(pm):
        return (Tool.COALPOWER, plant_x, plant_y)

    # Find plant center (approximate: find a plant tile)
    plant_tiles = list(zip(*np.where(pm)))
    # Use centroid of plant tiles as reference
    if plant_tiles:
        pcy = int(np.mean([r for r, c in plant_tiles]))
        pcx = int(np.mean([c for r, c in plant_tiles]))
    else:
        pcx, pcy = plant_x, plant_y

    # --- Phase 2: Build horizontal wire spine from plant to right side of cluster ---
    # Wire spine at row cy, from pcx+2 to cx+25
    spine_row = cy
    wire_start = pcx + 2
    wire_end = cx + 30

    # Find rightmost wire on spine row
    spine_wires = [c for (r, c) in zip(*np.where(wm)) if r == spine_row] if np.any(wm) else []
    if spine_wires:
        max_wire_col = max(spine_wires)
    else:
        max_wire_col = wire_start - 1

    if max_wire_col < wire_end:
        nc = max_wire_col + 1
        if 0 <= nc < WORLD_W and 0 <= spine_row < WORLD_H:
            # Don't overwrite plant
            if em[spine_row, nc] or wm[spine_row, nc]:
                return (Tool.WIRE, nc, spine_row)
            else:
                # skip this col, try next
                for try_c in range(nc + 1, wire_end + 1):
                    if 0 <= try_c < WORLD_W and (em[spine_row, try_c] or wm[spine_row, try_c]):
                        return (Tool.WIRE, try_c, spine_row)

    # --- Phase 3: Build horizontal road at spine_row - 2 and spine_row + 2 ---
    road_cols_start = pcx + 2
    road_cols_end = wire_end + 2

    for road_row in [spine_row - 2, spine_row + 2]:
        if road_row < 0 or road_row >= WORLD_H:
            continue
        road_here = [c for (r, c) in zip(*np.where(rm)) if r == road_row] if np.any(rm) else []
        if road_here:
            max_rc = max(road_here)
        else:
            max_rc = road_cols_start - 1

        if max_rc < road_cols_end:
            nc = max_rc + 1
            if 0 <= nc < WORLD_W:
                return (Tool.ROAD, nc, road_row)

    # --- Phase 4: Build vertical connector roads every 6 cols ---
    for conn_col in range(road_cols_start, road_cols_end + 1, 6):
        for conn_row in range(spine_row - 2, spine_row + 3):
            if 0 <= conn_col < WORLD_W and 0 <= conn_row < WORLD_H:
                if not rm[conn_row, conn_col] and not wm[conn_row, conn_col] and not pm[conn_row, conn_col]:
                    return (Tool.ROAD, conn_col, conn_row)

    # --- Phase 5: Add vertical wires to reach zone rows ---
    zone_rows_above = [spine_row - 5, spine_row - 8, spine_row - 11, spine_row - 14]
    zone_rows_below = [spine_row + 5, spine_row + 8, spine_row + 11, spine_row + 14]
    zone_cols = list(range(road_cols_start + 1, road_cols_end, 6))

    # For each zone column, extend wire up/down from spine
    for zc in zone_cols:
        if not (0 <= zc < WORLD_W):
            continue
        # Upward wires
        for zr in zone_rows_above:
            if not (0 <= zr < WORLD_H):
                continue
            # Find topmost wire in this column above spine
            col_wires_above = [r for r in range(spine_row - 1, zr - 1, -1)
                               if wm[r, zc] or pm[r, zc]]
            if col_wires_above:
                bottom_wire = max(col_wires_above)  # closest to spine
                target_r = bottom_wire - 1
            else:
                target_r = spine_row - 1

            if target_r >= zr and 0 <= target_r < WORLD_H:
                if em[target_r, zc]:
                    return (Tool.WIRE, zc, target_r)

        # Downward wires
        for zr in zone_rows_below:
            if not (0 <= zr < WORLD_H):
                continue
            col_wires_below = [r for r in range(spine_row + 1, zr + 2)
                               if wm[r, zc] or pm[r, zc]]
            if col_wires_below:
                top_wire = min(col_wires_below)
                target_r = top_wire + 1
            else:
                target_r = spine_row + 1

            if target_r <= zr and 0 <= target_r < WORLD_H:
                if em[target_r, zc]:
                    return (Tool.WIRE, zc, target_r)

    # --- Phase 6: Place zones adjacent to roads and wires ---
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def pick_zone(zc, zr):
        # 50% res, 25% com, 25% ind
        t = total_zones + 1
        if ind_count / t < 0.25 and (zc + zr) % 4 == 0:
            return Tool.INDUSTRIAL
        elif com_count / t < 0.25 and (zc + zr) % 4 == 1:
            return Tool.COMMERCIAL
        else:
            return Tool.RESIDENTIAL

    def has_road_near(zr, zc, radius=3):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    def has_wire_near(zr, zc, radius=5):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    all_zone_rows = zone_rows_above + zone_rows_below
    for zr in all_zone_rows:
        for zc in zone_cols:
            if not (2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3):
                continue
            if has_road_near(zr, zc) and has_wire_near(zr, zc):
                if zone_area_free(zr, zc):
                    return (pick_zone(zc, zr), zc, zr)

    # --- Phase 7: If pop growing, extend zone rows further out ---
    if obs.city_pop > 50 or total_zones > 10:
        extra_rows = [spine_row - 17, spine_row + 17, spine_row - 20, spine_row + 20]
        for zr in extra_rows:
            for zc in zone_cols:
                if not (2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3):
                    continue
                if has_road_near(zr, zc, 5) and has_wire_near(zr, zc, 7):
                    if zone_area_free(zr, zc):
                        return (pick_zone(zc, zr), zc, zr)

    # --- Phase 8: Reactively fill gaps in road coverage ---
    # Scan for zones not near roads and add roads
    zone_positions = list(zip(*np.where(resm | comm | indm))) if np.any(resm | comm | indm) else []
    for (zr, zc) in zone_positions:
        if not has_road_near(zr, zc, 2):
            # Place road adjacent
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0), (2, 0), (-2, 0), (0, 2), (0, -2)]:
                nr, nc2 = zr + dr, zc + dc
                if 0 <= nr < WORLD_H and 0 <= nc2 < WORLD_W and em[nr, nc2]:
                    return (Tool.ROAD, nc2, nr)

    # --- Phase 9: Add second power plant if underpowered ---
    if obs.powered_zones < total_zones * 0.5 and total_zones > 5:
        # Place near right side of cluster
        p2x, p2y = cx + 25, cy
        if 0 <= p2x < WORLD_W and 0 <= p2y < WORLD_H:
            # Check 3x3 area
            ok = True
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    rr, rc = p2y + dr, p2x + dc
                    if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                        if pm[rr, rc]:
                            ok = False
            if ok:
                return (Tool.COALPOWER, p2x, p2y)

    # Fallback: place road to fill any remaining road gaps
    for road_row in [spine_row - 2, spine_row + 2]:
        if 0 <= road_row < WORLD_H:
            for nc2 in range(road_cols_start, road_cols_end + 2):
                if 0 <= nc2 < WORLD_W and not rm[road_row, nc2] and not pm[road_row, nc2]:
                    return (Tool.ROAD, nc2, road_row)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy.
    Each step reads tile_map, finds existing infrastructure, and extends it.
    Strategy: coal plant -> wire spine -> road columns -> zones on both sides,
    expanding vertically as pop grows, adding second cluster when ready.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # ---- Phase 1: Place coal power plant ----
    if not np.any(pm):
        return (Tool.COALPOWER, 55, 50)

    # Find plant center
    plant_rows, plant_cols = np.where(pm)
    pcx = int(np.mean(plant_cols))
    pcy = int(np.mean(plant_rows))

    # Layout columns relative to plant
    wire_col = pcx + 4   # wire spine
    road_col_r = wire_col + 2   # right road
    road_col_l = wire_col - 3   # left road (between plant and wire)
    zone_col_r = road_col_r + 3  # right zones
    zone_col_l = road_col_l - 3  # left zones

    # Clamp
    wire_col = max(1, min(WORLD_W - 2, wire_col))
    road_col_r = max(1, min(WORLD_W - 2, road_col_r))
    road_col_l = max(1, min(WORLD_W - 2, road_col_l))
    zone_col_r = max(2, min(WORLD_W - 3, zone_col_r))
    zone_col_l = max(2, min(WORLD_W - 3, zone_col_l))

    # Vertical span grows with population
    half_span = min(28, max(8, 8 + obs.city_pop // 20))
    tmin = max(2, pcy - half_span)
    tmax = min(WORLD_H - 3, pcy + half_span)

    # Zone counts
    res_count = max(1, int(np.sum(res_m)) // 9)
    com_count = max(1, int(np.sum(com_m)) // 9)
    ind_count = max(1, int(np.sum(ind_m)) // 9)

    def pick_zone():
        total = res_count + com_count + ind_count
        if ind_count * 4 < total:
            return Tool.INDUSTRIAL
        if com_count * 4 < total:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    all_zone_m = res_m | com_m | ind_m

    def nearby_zone(zr, zc, radius=2):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(all_zone_m[r0:r1, c0:c1])

    # ---- Phase 2: Build wire spine vertically ----
    wire_rows = []
    if 0 <= wire_col < WORLD_W:
        wire_rows = sorted(r for r in range(WORLD_H) if wm[r, wire_col])

    if not wire_rows:
        # Start wire adjacent to plant
        for dy in [0, 1, -1, 2, -2]:
            ny = pcy + dy
            if 0 <= ny < WORLD_H and 0 <= wire_col < WORLD_W and em[ny, wire_col]:
                return (Tool.WIRE, wire_col, ny)
        return (Tool.WIRE, wire_col, pcy)
    else:
        min_wr = wire_rows[0]
        max_wr = wire_rows[-1]
        if max_wr < tmax:
            nr = max_wr + 1
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        if min_wr > tmin:
            nr = min_wr - 1
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    wire_rows_set = set(wire_rows)

    # ---- Phase 3: Build road columns ----
    if wire_rows:
        if 0 <= road_col_r < WORLD_W:
            for wr in wire_rows:
                if tmin <= wr <= tmax and not rm[wr, road_col_r] and em[wr, road_col_r]:
                    return (Tool.ROAD, road_col_r, wr)
        if 0 <= road_col_l < WORLD_W:
            for wr in wire_rows:
                if tmin <= wr <= tmax and not rm[wr, road_col_l] and em[wr, road_col_l]:
                    return (Tool.ROAD, road_col_l, wr)

    # ---- Phase 4: Place zones adjacent to roads ----
    if wire_rows:
        road_rows_r = set(r for r in range(WORLD_H)
                         if 0 <= road_col_r < WORLD_W and rm[r, road_col_r])
        road_rows_l = set(r for r in range(WORLD_H)
                         if 0 <= road_col_l < WORLD_W and rm[r, road_col_l])

        for zr in wire_rows:
            if not (tmin <= zr <= tmax):
                continue
            # Right zones
            road_near_r = any(abs(zr - rr) <= 1 for rr in road_rows_r)
            if road_near_r and 2 <= zone_col_r <= WORLD_W - 3:
                if not nearby_zone(zr, zone_col_r) and zone_area_free(zr, zone_col_r):
                    return (pick_zone(), zone_col_r, zr)
            # Left zones
            road_near_l = any(abs(zr - rr) <= 1 for rr in road_rows_l)
            if road_near_l and 2 <= zone_col_l <= WORLD_W - 3:
                if not nearby_zone(zr, zone_col_l) and zone_area_free(zr, zone_col_l):
                    return (pick_zone(), zone_col_l, zr)

        # Inner zones between wire and road
        zone_col_inner_r = wire_col + 1  # just right of wire
        zone_col_inner_l = wire_col - 1  # just left of wire
        # Actually try zones right next to road columns
        zone_col_ir = road_col_r - 3
        zone_col_il = road_col_l + 3
        for zr in wire_rows:
            if not (tmin <= zr <= tmax):
                continue
            road_near_r = any(abs(zr - rr) <= 1 for rr in road_rows_r)
            if road_near_r and 2 <= zone_col_ir <= WORLD_W - 3 and zone_col_ir != wire_col:
                if not nearby_zone(zr, zone_col_ir) and zone_area_free(zr, zone_col_ir):
                    return (pick_zone(), zone_col_ir, zr)
            road_near_l = any(abs(zr - rr) <= 1 for rr in road_rows_l)
            if road_near_l and 2 <= zone_col_il <= WORLD_W - 3 and zone_col_il != wire_col:
                if not nearby_zone(zr, zone_col_il) and zone_area_free(zr, zone_col_il):
                    return (pick_zone(), zone_col_il, zr)

    # ---- Phase 5: Second cluster when city grows ----
    if obs.city_pop >= 150 and wire_rows:
        wire_col2 = pcx + 18
        wire_col2 = max(2, min(WORLD_W - 3, wire_col2))
        road_col_r2 = wire_col2 + 2
        road_col_l2 = wire_col2 - 2
        zone_col_r2 = road_col_r2 + 3
        zone_col_l2 = road_col_l2 - 3
        road_col_r2 = max(1, min(WORLD_W - 2, road_col_r2))
        road_col_l2 = max(1, min(WORLD_W - 2, road_col_l2))
        zone_col_r2 = max(2, min(WORLD_W - 3, zone_col_r2))
        zone_col_l2 = max(2, min(WORLD_W - 3, zone_col_l2))

        wire_rows2 = sorted(r for r in range(WORLD_H)
                           if 0 <= wire_col2 < WORLD_W and wm[r, wire_col2])

        if not wire_rows2:
            # Bridge horizontally at pcy
            for wc in range(wire_col + 1, min(wire_col2 + 1, WORLD_W)):
                if 0 <= wc < WORLD_W and (em[pcy, wc] or wm[pcy, wc]):
                    if em[pcy, wc]:
                        return (Tool.WIRE, wc, pcy)
        else:
            min_wr2 = wire_rows2[0]
            max_wr2 = wire_rows2[-1]
            if max_wr2 < tmax:
                nr = max_wr2 + 1
                if 0 <= nr < WORLD_H and (em[nr, wire_col2] or wm[nr, wire_col2]):
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > tmin:
                nr = min_wr2 - 1
                if 0 <= nr < WORLD_H and (em[nr, wire_col2] or wm[nr, wire_col2]):
                    return (Tool.WIRE, wire_col2, nr)

            if 0 <= road_col_r2 < WORLD_W:
                for wr in wire_rows2:
                    if tmin <= wr <= tmax and not rm[wr, road_col_r2] and em[wr, road_col_r2]:
                        return (Tool.ROAD, road_col_r2, wr)
            if 0 <= road_col_l2 < WORLD_W:
                for wr in wire_rows2:
                    if tmin <= wr <= tmax and not rm[wr, road_col_l2] and em[wr, road_col_l2]:
                        return (Tool.ROAD, road_col_l2, wr)

            road_rows_r2 = set(r for r in range(WORLD_H)
                               if 0 <= road_col_r2 < WORLD_W and rm[r, road_col_r2])
            road_rows_l2 = set(r for r in range(WORLD_H)
                               if 0 <= road_col_l2 < WORLD_W and rm[r, road_col_l2])

            for zr in wire_rows2:
                if not (tmin <= zr <= tmax):
                    continue
                road_near_r2 = any(abs(zr - rr) <= 1 for rr in road_rows_r2)
                if road_near_r2 and 2 <= zone_col_r2 <= WORLD_W - 3:
                    if not nearby_zone(zr, zone_col_r2) and zone_area_free(zr, zone_col_r2):
                        return (pick_zone(), zone_col_r2, zr)
                road_near_l2 = any(abs(zr - rr) <= 1 for rr in road_rows_l2)
                if road_near_l2 and 2 <= zone_col_l2 <= WORLD_W - 3:
                    if not nearby_zone(zr, zone_col_l2) and zone_area_free(zr, zone_col_l2):
                        return (pick_zone(), zone_col_l2, zr)

    # ---- Phase 6: Second power plant for large city ----
    if obs.city_pop >= 300 and not state.get("plant2_placed", False):
        px2 = pcx + 20
        py2 = pcy
        px2 = max(2, min(WORLD_W - 3, px2))
        py2 = max(2, min(WORLD_H - 3, py2))
        if all(0 <= py2 + dr < WORLD_H and 0 <= px2 + dc < WORLD_W
               and em[py2 + dr, px2 + dc]
               for dr in [-1, 0, 1] for dc in [-1, 0, 1]):
            state["plant2_placed"] = True
            return (Tool.COALPOWER, px2, py2)

    # ---- Phase 7: Third cluster to the left for high pop ----
    if obs.city_pop >= 400 and wire_rows:
        wire_col3 = pcx - 14
        wire_col3 = max(2, min(WORLD_W - 3, wire_col3))
        road_col_r3 = wire_col3 + 2
        road_col_l3 = wire_col3 - 2
        zone_col_r3 = road_col_r3 + 3
        zone_col_l3 = road_col_l3 - 3
        road_col_r3 = max(1, min(WORLD_W - 2, road_col_r3))
        road_col_l3 = max(1, min(WORLD_W - 2, road_col_l3))
        zone_col_r3 = max(2, min(WORLD_W - 3, zone_col_r3))
        zone_col_l3 = max(2, min(WORLD_W - 3, zone_col_l3))

        wire_rows3 = sorted(r for r in range(WORLD_H)
                           if 0 <= wire_col3 < WORLD_W and wm[r, wire_col3])

        if not wire_rows3:
            for wc in range(wire_col - 1, max(wire_col3 - 1, 0), -1):
                if 0 <= wc < WORLD_W and (em[pcy, wc] or wm[pcy, wc]):
                    if em[pcy, wc]:
                        return (Tool.WIRE, wc, pcy)
        else:
            min_wr3 = wire_rows3[0]
            max_wr3 = wire_rows3[-1]
            if max_wr3 < tmax:
                nr = max_wr3 + 1
                if 0 <= nr < WORLD_H and (em[nr, wire_col3] or wm[nr, wire_col3]):
                    return (Tool.WIRE, wire_col3, nr)
            if min_wr3 > tmin:
                nr = min_wr3 - 1
                if 0 <= nr < WORLD_H and (em[nr, wire_col3] or wm[nr, wire_col3]):
                    return (Tool.WIRE, wire_col3, nr)

            if 0 <= road_col_r3 < WORLD_W:
                for wr in wire_rows3:
                    if tmin <= wr <= tmax and not rm[wr, road_col_r3] and em[wr, road_col_r3]:
                        return (Tool.ROAD, road_col_r3, wr)
            if 0 <= road_col_l3 < WORLD_W:
                for wr in wire_rows3:
                    if tmin <= wr <= tmax and not rm[wr, road_col_l3] and em[wr, road_col_l3]:
                        return (Tool.ROAD, road_col_l3, wr)

            road_rows_r3 = set(r for r in range(WORLD_H)
                               if 0 <= road_col_r3 < WORLD_W and rm[r, road_col_r3])
            road_rows_l3 = set(r for r in range(WORLD_H)
                               if 0 <= road_col_l3 < WORLD_W and rm[r, road_col_l3])

            for zr in wire_rows3:
                if not (tmin <= zr <= tmax):
                    continue
                road_near_r3 = any(abs(zr - rr) <= 1 for rr in road_rows_r3)
                if road_near_r3 and 2 <= zone_col_r3 <= WORLD_W - 3:
                    if not nearby_zone(zr, zone_col_r3) and zone_area_free(zr, zone_col_r3):
                        return (pick_zone(), zone_col_r3, zr)
                road_near_l3 = any(abs(zr - rr) <= 1 for rr in road_rows_l3)
                if road_near_l3 and 2 <= zone_col_l3 <= WORLD_W - 3:
                    if not nearby_zone(zr, zone_col_l3) and zone_area_free(zr, zone_col_l3):
                        return (pick_zone(), zone_col_l3, zr)

    # ---- Phase 8: Horizontal road connector for better zone access ----
    if wire_rows and obs.city_pop > 80:
        hr = pcy
        if tmin <= hr <= tmax:
            for rc in range(road_col_l, road_col_r + 1):
                if 0 <= rc < WORLD_W and not rm[hr, rc] and em[hr, rc]:
                    return (Tool.ROAD, rc, hr)

    return None

def act(obs, state):
    """
    Hybrid policy combining best of both parents:
    - Parent A: vertical wire spine + road column, zones on both sides, reactive expansion
    - Parent B: horizontal wire spine, branch wires, road rows parallel to spine

    Strategy: 
    - Place coal plant at a fixed location
    - Build HORIZONTAL wire spine from plant eastward
    - Build road rows above and below spine (parent B style)
    - Add vertical branch wires to reach zones (parent B style)
    - Place zones in grid pattern beside roads with proper power/road access
    - Add second plant when needed
    - Add services when population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Place first coal plant
    PLANT_X, PLANT_Y = 20, 50
    if not np.any(pm):
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    # Find plant center
    plant_ys, plant_xs = np.where(pm)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(ind_mask(tm)))
    total_zones = res_count + com_count + ind_count

    def pick_tool(zx, zy):
        t = max(total_zones, 1)
        r = res_count / t
        c = com_count / t
        i = ind_count / t
        if c < 0.20:
            return Tool.COMMERCIAL
        if i < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    zone_centers = set()
    for mask, name in [(resm, 'r'), (comm, 'c'), (indm, 'i')]:
        ys, xs = np.where(mask)
        for y, x in zip(ys.tolist(), xs.tolist()):
            zone_centers.add((y, x))

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                # Allow if already a zone tile (zone overlapping)
                if not em[nr, nc] and (nr, nc) not in zone_centers:
                    return False
        return True

    # Horizontal wire spine at row py, from plant right edge to wire_end_x
    spine_y = py
    wire_start_x = px + 2
    wire_end_x = min(px + 80, WORLD_W - 4)

    # Extend horizontal wire spine first
    for wx in range(wire_start_x, wire_end_x + 1):
        wy = spine_y
        if not in_bounds(wx, wy):
            break
        if not bool(wm[wy, wx]) and not bool(pm[wy, wx]):
            if bool(em[wy, wx]):
                return (Tool.WIRE, wx, wy)
            break  # blocked, stop extending

    # Road rows parallel to spine (above and below by 3)
    road_top_y = spine_y - 3
    road_bot_y = spine_y + 3
    road_start_x = wire_start_x
    road_end_x = min(wire_end_x, WORLD_W - 4)

    # Build top road row
    for rx in range(road_start_x, road_end_x + 1):
        if not in_bounds(rx, road_top_y):
            break
        if not bool(rm[road_top_y, rx]) and not bool(pm[road_top_y, rx]) and not bool(wm[road_top_y, rx]):
            if bool(em[road_top_y, rx]):
                return (Tool.ROAD, rx, road_top_y)
            break

    # Build bottom road row
    for rx in range(road_start_x, road_end_x + 1):
        if not in_bounds(rx, road_bot_y):
            break
        if not bool(rm[road_bot_y, rx]) and not bool(pm[road_bot_y, rx]) and not bool(wm[road_bot_y, rx]):
            if bool(em[road_bot_y, rx]):
                return (Tool.ROAD, rx, road_bot_y)
            break

    # Vertical branch wires from spine to road rows (every 6 cols)
    branch_cols = list(range(wire_start_x + 3, road_end_x + 1, 6))
    for bx in branch_cols:
        if not in_bounds(bx, spine_y):
            continue
        if not (bool(wm[spine_y, bx]) or bool(pm[spine_y, bx])):
            continue  # spine not wired here yet
        # Wire down to road_bot_y
        for by in range(spine_y + 1, road_bot_y + 1):
            if not in_bounds(bx, by):
                break
            if bool(wm[by, bx]) or bool(pm[by, bx]) or bool(rm[by, bx]):
                continue
            if bool(em[by, bx]):
                return (Tool.WIRE, bx, by)
            break
        # Wire up to road_top_y
        for by in range(spine_y - 1, road_top_y - 1, -1):
            if not in_bounds(bx, by):
                break
            if bool(wm[by, bx]) or bool(pm[by, bx]) or bool(rm[by, bx]):
                continue
            if bool(em[by, bx]):
                return (Tool.WIRE, bx, by)
            break

    # Vertical connector roads at branch cols between road rows
    for vc in branch_cols:
        for vr in range(road_top_y, road_bot_y + 1):
            if not in_bounds(vc, vr):
                continue
            if not bool(rm[vr, vc]) and not bool(pm[vr, vc]) and not bool(wm[vr, vc]):
                if bool(em[vr, vc]):
                    return (Tool.ROAD, vc, vr)

    # Zone placement: place zones above top road and below bottom road
    # Zone centers at y = road_top_y - 2 (above top road) and road_bot_y + 2 (below bot road)
    # Also between road_top and road_bot at spine level? No - keep it clean.
    zone_rows = [road_top_y - 2, road_bot_y + 2]
    # Also add more rows further out if population growing
    if obs.city_pop > 200:
        zone_rows.extend([road_top_y - 5, road_bot_y + 5])
    if obs.city_pop > 500:
        zone_rows.extend([road_top_y - 8, road_bot_y + 8])

    # Build neighbor proximity masks for road and wire
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Place zones along zone rows at branch col positions
    for zr in zone_rows:
        if not in_bounds(0, zr):
            continue
        for bx in branch_cols:
            zx, zy = bx, zr
            if not in_bounds(zx, zy):
                continue
            if not (nbr_road[zy, zx] and nbr_wire[zy, zx]):
                continue
            if zone_clear(zx, zy):
                return (pick_tool(zx, zy), zx, zy)

    # Also try candidate scan approach for any empty+road+wire location
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    cys_c, cxs_c = np.where(cand_mask)
    if len(cxs_c) > 0:
        step_hash = int(obs.step * 17 + int(obs.city_pop * 3)) % max(len(cxs_c), 1)
        for offset in range(min(len(cxs_c), 60)):
            k = (step_hash + offset * 13) % len(cxs_c)
            zx, zy = int(cxs_c[k]), int(cys_c[k])
            if zone_clear(zx, zy):
                return (pick_tool(zx, zy), zx, zy)

    # Add second power plant when many zones exist
    if total_zones > 15 or obs.city_pop > 400:
        p2x = min(px + 70, WORLD_W - 5)
        p2y = py
        nearby_plant = False
        for dy in range(-7, 8):
            for dx in range(-7, 8):
                ny, nx2 = p2y + dy, p2x + dx
                if in_bounds(nx2, ny) and bool(pm[ny, nx2]):
                    nearby_plant = True
        if not nearby_plant and in_bounds(p2x, p2y) and bool(em[p2y, p2x]):
            return (Tool.COALPOWER, p2x, p2y)

    # Add fire station and police station
    if obs.city_pop > 150:
        fx, fy = px + 8, py - 10
        if in_bounds(fx, fy) and bool(em[fy, fx]):
            return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 250:
        px2, py2 = px + 8, py + 10
        if in_bounds(px2, py2) and bool(em[py2, px2]):
            return (Tool.POLICESTATION, px2, py2)

    # Extend wire spine further east if population growing
    if obs.city_pop > 300:
        new_end = min(wire_end_x + 20, WORLD_W - 4)
        for wx in range(wire_end_x + 1, new_end + 1):
            if not in_bounds(wx, spine_y):
                break
            if not bool(wm[spine_y, wx]) and not bool(pm[spine_y, wx]):
                if bool(em[spine_y, wx]):
                    return (Tool.WIRE, wx, spine_y)
                break

    # Extend roads further if needed
    if obs.city_pop > 300:
        new_road_end = min(road_end_x + 20, WORLD_W - 4)
        for rx in range(road_end_x + 1, new_road_end + 1):
            if not in_bounds(rx, road_top_y):
                break
            if not bool(rm[road_top_y, rx]) and bool(em[road_top_y, rx]):
                return (Tool.ROAD, rx, road_top_y)
            break
        for rx in range(road_end_x + 1, new_road_end + 1):
            if not in_bounds(rx, road_bot_y):
                break
            if not bool(rm[road_bot_y, rx]) and bool(em[road_bot_y, rx]):
                return (Tool.ROAD, rx, road_bot_y)
            break

    return None

def act(obs, state):
    """
    New policy: horizontal layout instead of vertical.
    - Power plant at top-left of center cluster
    - Horizontal wire spine (row-based)
    - Vertical road column next to wire spine
    - Zones above and below the wire spine
    - Better zone mix (RCI balance)
    - Two neighborhoods side by side
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    all_zone_mask = resm | comm | indm

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        # Aim for 50% RES, 30% COM, 20% IND
        if res_count / t < 0.50:
            return Tool.RESIDENTIAL
        if com_count / t < 0.30:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return bool(np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1]))

    def has_road_nearby(zr, zc, radius=3):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return bool(np.any(rm[r0:r1, c0:c1]))

    # Use horizontal wire spine at row cy, road at row cy+1
    # Plant at (cx-10, cy-1)
    plant_x = cx - 10
    plant_y = cy - 1

    wire_row = cy + 2       # horizontal wire spine
    road_row = wire_row + 1  # horizontal road next to wire
    above_zone_row = wire_row - 3  # zones above wire
    below_zone_row = road_row + 3  # zones below road

    wire_row = max(2, min(WORLD_H - 3, wire_row))
    road_row = max(2, min(WORLD_H - 3, road_row))
    above_zone_row = max(2, min(WORLD_H - 3, above_zone_row))
    below_zone_row = max(2, min(WORLD_H - 3, below_zone_row))

    # Spine extent based on population
    if obs.city_pop < 50:
        spine_extent = 10
    elif obs.city_pop < 150:
        spine_extent = 16
    elif obs.city_pop < 400:
        spine_extent = 22
    elif obs.city_pop < 800:
        spine_extent = 30
    else:
        spine_extent = 40

    target_min_col = max(2, cx - spine_extent)
    target_max_col = min(WORLD_W - 3, cx + spine_extent)

    # Phase 1: Place coal power plant
    if not np.any(pm):
        return (Tool.COALPOWER, plant_x, plant_y)

    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    wire_cols_on_spine = sorted([c for c in range(WORLD_W) if wm[wire_row, c]])
    road_cols_on_row = sorted([c for c in range(WORLD_W) if rm[road_row, c]])

    # Phase 2: Bootstrap wire spine adjacent to plant
    if not wire_cols_on_spine:
        # Place wire just right of plant
        for dx in range(0, 8):
            for nc in [plant_cx + dx, plant_cx - dx]:
                if 0 <= nc < WORLD_W and 0 <= wire_row < WORLD_H:
                    if em[wire_row, nc] or wm[wire_row, nc]:
                        return (Tool.WIRE, nc, wire_row)
        return None

    min_wire_col = min(wire_cols_on_spine)
    max_wire_col = max(wire_cols_on_spine)

    # Phase 3: Extend wire spine rightward then leftward
    if max_wire_col < target_max_col:
        nc = max_wire_col + 1
        if nc < WORLD_W and not pm[wire_row, nc]:
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    if min_wire_col > target_min_col:
        nc = min_wire_col - 1
        if nc >= 0 and not pm[wire_row, nc]:
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # Phase 4: Build road row alongside wire spine
    for c in wire_cols_on_spine:
        if 0 <= c < WORLD_W and 0 <= road_row < WORLD_H:
            if not rm[road_row, c] and em[road_row, c]:
                return (Tool.ROAD, c, road_row)

    # Phase 5: Vertical wires upward from spine to above zone row
    for wc in wire_cols_on_spine:
        for wr in range(wire_row - 1, above_zone_row - 2, -1):
            if 0 <= wr < WORLD_H:
                if wm[wr, wc] or pm[wr, wc]:
                    break
                if em[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                else:
                    break

    # Phase 6: Road extensions downward to below zone row
    for wc in wire_cols_on_spine:
        if not rm[road_row, wc]:
            continue
        for rr in range(road_row + 1, below_zone_row + 2):
            if 0 <= rr < WORLD_H:
                if rm[rr, wc]:
                    break
                if pm[rr, wc]:
                    break
                if em[rr, wc]:
                    return (Tool.ROAD, wc, rr)
                else:
                    break

    # Phase 7: Wires downward to power below zones
    for wc in wire_cols_on_spine:
        for wr in range(wire_row + 1, below_zone_row + 2):
            if 0 <= wr < WORLD_H:
                if wm[wr, wc] or pm[wr, wc]:
                    break
                if rm[wr, wc]:
                    continue  # skip road tiles
                if em[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                else:
                    break

    # Phase 8: Place zones along the corridor
    zone_cols = list(range(max(2, target_min_col + 1), min(WORLD_W - 2, target_max_col), 3))

    for zc in zone_cols:
        wire_near = any(abs(zc - wc) <= 2 for wc in wire_cols_on_spine)
        road_near = any(abs(zc - rc) <= 2 for rc in road_cols_on_row)

        if wire_near and road_near:
            # Above zone
            zr = above_zone_row
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc, 5) and has_road_nearby(zr, zc, 5):
                    return (pick_tool(), zc, zr)
                elif has_wire_nearby(zr, zc, 6):
                    return (Tool.RESIDENTIAL, zc, zr)

            # Below zone
            zr = below_zone_row
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_road_nearby(zr, zc, 5) and has_wire_nearby(zr, zc, 6):
                    return (pick_tool(), zc, zr)

    # Phase 9: Second coal plant when population growing
    plant_count = int(np.sum(pm))
    if obs.city_pop > 200 and plant_count < 9:
        # Place second plant above the cluster
        px2 = plant_cx
        py2 = plant_cy - 18
        if 2 <= px2 <= WORLD_W - 4 and 2 <= py2 <= WORLD_H - 4:
            if np.all(em[py2-1:py2+2, px2-1:px2+2]):
                return (Tool.COALPOWER, px2, py2)
        # Try right side
        px2 = plant_cx + 25
        py2 = plant_cy
        if 2 <= px2 <= WORLD_W - 4 and 2 <= py2 <= WORLD_H - 4:
            if np.all(em[py2-1:py2+2, px2-1:px2+2]):
                return (Tool.COALPOWER, px2, py2)

    # Phase 10: Second neighborhood - add another wire row below
    if obs.city_pop > 300:
        wire_row2 = below_zone_row + 4
        road_row2 = wire_row2 + 1
        above_zone2 = wire_row2 - 3
        below_zone2 = road_row2 + 3

        wire_row2 = max(2, min(WORLD_H - 3, wire_row2))
        road_row2 = max(2, min(WORLD_H - 3, road_row2))
        above_zone2 = max(2, min(WORLD_H - 3, above_zone2))
        below_zone2 = max(2, min(WORLD_H - 3, below_zone2))

        # Extend existing wire cols into second neighborhood
        for wc in wire_cols_on_spine:
            # Connect vertically from first to second wire row
            for wr in range(wire_row + 1, wire_row2 + 1):
                if 0 <= wr < WORLD_H:
                    if wm[wr, wc] or pm[wr, wc]:
                        break
                    if em[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    if rm[wr, wc]:
                        continue
                    break

        # Place zones in second neighborhood
        for zc in zone_cols:
            wire_near2 = any(abs(zc - wc) <= 2 for wc in wire_cols_on_spine)
            if wire_near2:
                for zr in [above_zone2, below_zone2]:
                    if 0 <= zr < WORLD_H:
                        if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                            if has_wire_nearby(zr, zc, 7) and has_road_nearby(zr, zc, 7):
                                return (pick_tool(), zc, zr)

    # Phase 11: Fill any gaps in wire spine
    for c in range(target_min_col, target_max_col + 1):
        if not wm[wire_row, c] and not pm[wire_row, c] and em[wire_row, c]:
            return (Tool.WIRE, c, wire_row)

    # Phase 12: Add vertical roads for extra connectivity
    if obs.city_pop > 150:
        v_cols = [min_wire_col + 1, max_wire_col - 1, plant_cx]
        for vc in v_cols:
            if 0 <= vc < WORLD_W:
                for rr in range(max(0, above_zone_row - 2), min(WORLD_H, below_zone_row + 3)):
                    if em[rr, vc] and not pm[rr, vc] and not wm[rr, vc]:
                        return (Tool.ROAD, vc, rr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy v2:
    - Reads tile_map every step to find existing infrastructure
    - Builds a compact grid: plant -> wire spine -> road grid -> zones
    - Key changes from parent:
      1. Road is placed FIRST along wire spine (before zones)
      2. Wire extends laterally to connect zones directly
      3. Zones placed between road and wire (both sides of road)
      4. More aggressive zone placement checking
      5. Uses horizontal road connections earlier
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    all_zone = resm | comm | indm

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone[rr, rc]:
                    return False
        return True

    def zone_exists_near(zr, zc, r=3):
        r0 = max(0, zr - r); r1 = min(WORLD_H, zr + r + 1)
        c0 = max(0, zc - r); c1 = min(WORLD_W, zc + r + 1)
        return np.any(all_zone[r0:r1, c0:c1])

    def wire_near(zr, zc, radius=3):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def road_near(zr, zc, radius=3):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    # --- Phase 1: Place coal power plant if missing ---
    if not np.any(pm):
        px, py = cx - 12, cy
        return (Tool.COALPOWER, px, py)

    # Find plant location
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Define corridor geometry
    # Wire runs vertically just right of plant
    wire_col = plant_cx + 3
    # Road runs parallel to wire, 3 cols to the right
    road_col = wire_col + 3
    # Zone columns on each side of the road
    left_zone_col  = wire_col + 1   # between wire and road (center)
    right_zone_col = road_col + 2   # right of road

    # Clamp all columns
    wire_col       = max(2, min(WORLD_W - 3, wire_col))
    road_col       = max(2, min(WORLD_W - 3, road_col))
    left_zone_col  = max(2, min(WORLD_W - 3, left_zone_col))
    right_zone_col = max(2, min(WORLD_W - 3, right_zone_col))

    # Vertical extent scales with population
    pop = obs.city_pop
    if pop < 50:
        half = 8
    elif pop < 200:
        half = 14
    elif pop < 500:
        half = 20
    else:
        half = 28

    y_min = max(1, cy - half)
    y_max = min(WORLD_H - 2, cy + half)

    wire_rows = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])
    road_rows = sorted([r for r in range(WORLD_H) if rm[r, road_col]])

    # --- Phase 2: Start wire spine adjacent to plant ---
    if not wire_rows:
        for dy in range(0, 8):
            for nr in [plant_cy + dy, plant_cy - dy]:
                if 0 <= nr < WORLD_H and 0 <= wire_col < WORLD_W:
                    if em[nr, wire_col]:
                        return (Tool.WIRE, wire_col, nr)
        return None

    min_wr = min(wire_rows)
    max_wr = max(wire_rows)

    # --- Phase 3: Ensure plant is connected to wire spine ---
    connected = False
    for dr in range(-2, 3):
        for dc in range(-2, 3):
            rr, rc = plant_cy + dr, plant_cx + dc
            if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                if wm[rr, rc]:
                    connected = True
    if not connected:
        bridge_r = plant_cy
        for bc in range(plant_cx + 1, wire_col + 1):
            if 0 <= bc < WORLD_W:
                if wm[bridge_r, bc]:
                    break
                if em[bridge_r, bc]:
                    return (Tool.WIRE, bc, bridge_r)

    # --- Phase 4: Extend wire spine vertically ---
    if max_wr < y_max:
        nr = max_wr + 1
        if nr < WORLD_H and em[nr, wire_col] and not pm[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)

    if min_wr > y_min:
        nr = min_wr - 1
        if nr >= 0 and em[nr, wire_col] and not pm[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)

    # --- Phase 5: Build road column parallel to wire spine ---
    # Build road at all rows where wire exists
    for r in wire_rows:
        if y_min <= r <= y_max:
            if 0 <= road_col < WORLD_W and em[r, road_col] and not pm[r, road_col]:
                return (Tool.ROAD, road_col, r)

    # --- Phase 6: Lateral wires from spine toward road column ---
    # Place horizontal wire segments connecting wire_col to road_col
    for wr in wire_rows:
        if y_min <= wr <= y_max:
            for wc in range(wire_col + 1, road_col):
                if wc >= WORLD_W:
                    break
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc] and not rm[wr, wc] and not wm[wr, wc]:
                    break

    # --- Phase 7: Place zones - left side (between wire and road) ---
    zone_rows = list(range(y_min + 1, y_max, 4))

    for zr in zone_rows:
        w_close = any(abs(zr - wr) <= 2 for wr in wire_rows)
        r_close = any(abs(zr - rr) <= 2 for rr in road_rows)

        if w_close and r_close:
            # Left zone: centered between wire and road
            zc = left_zone_col
            if not zone_exists_near(zr, zc) and zone_area_ok(zr, zc):
                if wire_near(zr, zc, 3) and road_near(zr, zc, 3):
                    return (pick_tool(), zc, zr)

    # --- Phase 8: Extend road rightward for right zones ---
    for rr in road_rows:
        if y_min <= rr <= y_max:
            for rc in range(road_col + 1, right_zone_col + 2):
                if rc >= WORLD_W:
                    break
                if rm[rr, rc]:
                    break
                if em[rr, rc] and not pm[rr, rc]:
                    return (Tool.ROAD, rc, rr)
                elif not em[rr, rc]:
                    break

    # --- Phase 9: Right-side zones (right of road) ---
    for zr in zone_rows:
        r_close = any(abs(zr - rr) <= 2 for rr in road_rows)
        if r_close:
            zc = right_zone_col
            if not zone_exists_near(zr, zc) and zone_area_ok(zr, zc):
                if road_near(zr, zc, 3) and wire_near(zr, zc, 6):
                    return (pick_tool(), zc, zr)

    # --- Phase 10: Wire rightward to cover right zones ---
    for wr in wire_rows:
        if y_min <= wr <= y_max:
            for wc in range(road_col + 1, right_zone_col + 3):
                if wc >= WORLD_W:
                    break
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc] and not rm[wr, wc] and not wm[wr, wc]:
                    break

    # --- Phase 11: Horizontal roads at top/bottom for connectivity ---
    if len(road_rows) > 2:
        for rr in [min_wr, max_wr]:
            if y_min <= rr <= y_max:
                for rc in range(wire_col - 1, right_zone_col + 3):
                    if 0 <= rc < WORLD_W and em[rr, rc] and not pm[rr, rc]:
                        return (Tool.ROAD, rc, rr)

    # --- Phase 12: Second power plant if population is large ---
    plant_count = max(1, int(np.sum(pm)) // 6)
    if pop > 250 and plant_count < 2:
        px2 = plant_cx - 8
        py2 = plant_cy
        if 2 <= px2 <= WORLD_W - 3 and 2 <= py2 <= WORLD_H - 3:
            area_ok = all(em[py2 + dr, px2 + dc]
                          for dr in [-1,0,1] for dc in [-1,0,1]
                          if 0 <= py2+dr < WORLD_H and 0 <= px2+dc < WORLD_W)
            if area_ok:
                return (Tool.COALPOWER, px2, py2)

    # --- Phase 13: Dense zone filling - scan for any good spot ---
    if pop > 100:
        for zr in range(y_min, y_max + 1, 3):
            for zc_off in [-4, 0, 4, 8]:
                zc = road_col + zc_off
                zc = max(2, min(WORLD_W - 3, zc))
                if not zone_exists_near(zr, zc, 2) and zone_area_ok(zr, zc):
                    if wire_near(zr, zc, 5) and road_near(zr, zc, 5):
                        return (pick_tool(), zc, zr)

    # --- Phase 14: Extend wire spine further if population growing ---
    if pop > 150:
        new_half = half + 6
        new_y_min = max(1, cy - new_half)
        new_y_max = min(WORLD_H - 2, cy + new_half)
        if wire_rows:
            if min_wr > new_y_min:
                nr = min_wr - 1
                if nr >= 0 and em[nr, wire_col]:
                    return (Tool.WIRE, wire_col, nr)
            if max_wr < new_y_max:
                nr = max_wr + 1
                if nr < WORLD_H and em[nr, wire_col]:
                    return (Tool.WIRE, wire_col, nr)

    return None

def act(obs, state):
    """
    New policy: Two separate neighborhoods connected by a road/wire corridor.
    Neighborhood A near (25, 35), Neighborhood B near (70, 65).
    Each has its own coal plant. Zones placed in a grid pattern around roads.
    Better zone mix: 40% res, 30% com, 30% ind.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def is_empty(x, y):
        return in_bounds(x, y) and bool(em[y, x])

    def is_wire(x, y):
        return in_bounds(x, y) and (bool(wm[y, x]) or bool(pm[y, x]))

    def is_road(x, y):
        return in_bounds(x, y) and bool(rm[y, x])

    def is_plant(x, y):
        return in_bounds(x, y) and bool(pm[y, x])

    # Initialize state
    if 'phase' not in state:
        state['phase'] = 0
        state['queue'] = []

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        r_ratio = res_count / t
        c_ratio = com_count / t
        i_ratio = ind_count / t
        if c_ratio < 0.30:
            return Tool.COMMERCIAL
        if i_ratio < 0.30:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Neighborhood A: plant at (20, 35), road row at y=35, wire at y=37
    A_PLANT = (20, 35)
    A_ROAD_Y = 33
    A_WIRE_Y = 36
    A_START_X = 23
    A_END_X = 55

    # Neighborhood B: plant at (70, 65), road row at y=65, wire at y=63
    B_PLANT = (70, 65)
    B_ROAD_Y = 63
    B_WIRE_Y = 66
    B_START_X = 73
    B_END_X = 105

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                # Check if any non-empty, non-zone tile is there
                if not bool(em[nr, nc]):
                    # Allow if it's a zone tile
                    if not (bool(resm[nr, nc]) or bool(comm[nr, nc]) or bool(indm[nr, nc])):
                        return False
        return True

    # Step 1: Place plant A
    if not np.any(pm):
        return (Tool.COALPOWER, A_PLANT[0], A_PLANT[1])

    plant_ys, plant_xs = np.where(pm)
    n_plants = len(np.unique(plant_xs))

    # Step 2: Wire from plant A horizontally
    ax, ay = A_PLANT
    for wx in range(ax + 2, A_END_X + 1):
        wy = A_WIRE_Y
        if not in_bounds(wx, wy): break
        if bool(pm[wy, wx]): continue
        if not bool(wm[wy, wx]):
            if bool(em[wy, wx]):
                return (Tool.WIRE, wx, wy)
            else:
                break

    # Step 3: Road above wire for neighborhood A (y = A_ROAD_Y)
    for rx in range(A_START_X, A_END_X + 1):
        ry = A_ROAD_Y
        if not in_bounds(rx, ry): break
        if not bool(rm[ry, rx]) and not bool(pm[ry, rx]) and not bool(wm[ry, rx]):
            if bool(em[ry, rx]):
                return (Tool.ROAD, rx, ry)
            else:
                break

    # Step 4: Second road row below wire for neighborhood A (y = A_WIRE_Y + 2)
    A_ROAD_Y2 = A_WIRE_Y + 2
    for rx in range(A_START_X, A_END_X + 1):
        ry = A_ROAD_Y2
        if not in_bounds(rx, ry): break
        if not bool(rm[ry, rx]) and not bool(pm[ry, rx]) and not bool(wm[ry, rx]):
            if bool(em[ry, rx]):
                return (Tool.ROAD, rx, ry)
            else:
                break

    # Step 5: Vertical connectors every 6 cols for neighborhood A
    for vc in range(A_START_X, A_END_X + 1, 6):
        for vr in range(A_ROAD_Y, A_ROAD_Y2 + 1):
            if not in_bounds(vc, vr): continue
            if not bool(rm[vr, vc]) and not bool(pm[vr, vc]) and not bool(wm[vr, vc]):
                if bool(em[vr, vc]):
                    return (Tool.ROAD, vc, vr)

    # Step 6: Plant B when neighborhood A has enough zones
    if total_zones >= 6 and not any(
        abs(plant_xs[i] - B_PLANT[0]) < 10 and abs(plant_ys[i] - B_PLANT[1]) < 10
        for i in range(len(plant_xs))
    ):
        bx, by = B_PLANT
        if is_empty(bx, by):
            return (Tool.COALPOWER, bx, by)

    # Check if plant B exists
    plant_b_exists = any(
        abs(plant_xs[i] - B_PLANT[0]) < 15 and abs(plant_ys[i] - B_PLANT[1]) < 15
        for i in range(len(plant_xs))
    )

    if plant_b_exists:
        # Step 7: Wire from plant B horizontally
        bx, by = B_PLANT
        for wx in range(bx + 2, B_END_X + 1):
            wy = B_WIRE_Y
            if not in_bounds(wx, wy): break
            if bool(pm[wy, wx]): continue
            if not bool(wm[wy, wx]):
                if bool(em[wy, wx]):
                    return (Tool.WIRE, wx, wy)
                else:
                    break

        # Step 8: Road for neighborhood B
        for rx in range(B_START_X, B_END_X + 1):
            ry = B_ROAD_Y
            if not in_bounds(rx, ry): break
            if not bool(rm[ry, rx]) and not bool(pm[ry, rx]) and not bool(wm[ry, rx]):
                if bool(em[ry, rx]):
                    return (Tool.ROAD, rx, ry)
                else:
                    break

        B_ROAD_Y2 = B_WIRE_Y + 2
        for rx in range(B_START_X, B_END_X + 1):
            ry = B_ROAD_Y2
            if not in_bounds(rx, ry): break
            if not bool(rm[ry, rx]) and not bool(pm[ry, rx]) and not bool(wm[ry, rx]):
                if bool(em[ry, rx]):
                    return (Tool.ROAD, rx, ry)
                else:
                    break

        # Vertical connectors for B
        for vc in range(B_START_X, B_END_X + 1, 6):
            for vr in range(B_ROAD_Y, B_ROAD_Y2 + 1):
                if not in_bounds(vc, vr): continue
                if not bool(rm[vr, vc]) and not bool(pm[vr, vc]) and not bool(wm[vr, vc]):
                    if bool(em[vr, vc]):
                        return (Tool.ROAD, vc, vr)

    # Step 9: Zone placement near roads + wires
    # Build neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        step_hash = int(obs.step * 17 + int(obs.city_pop * 3)) % max(len(cxs_arr), 1)
        for offset in range(min(len(cxs_arr), 80)):
            k = (step_hash + offset * 11) % len(cxs_arr)
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # Step 10: Services
    if obs.city_pop > 100:
        ax2, ay2 = A_PLANT
        fx, fy = ax2 + 3, ay2 - 8
        if in_bounds(fx, fy) and bool(em[fy, fx]):
            return (Tool.FIRESTATION, fx, fy)
        fx2, fy2 = ax2 + 3, ay2 + 8
        if in_bounds(fx2, fy2) and bool(em[fy2, fx2]):
            return (Tool.POLICESTATION, fx2, fy2)

    if obs.city_pop > 300 and plant_b_exists:
        bx2, by2 = B_PLANT
        fx3, fy3 = bx2 + 3, by2 - 8
        if in_bounds(fx3, fy3) and bool(em[fy3, fx3]):
            return (Tool.FIRESTATION, fx3, fy3)
        fx4, fy4 = bx2 + 3, by2 + 8
        if in_bounds(fx4, fy4) and bool(em[fy4, fx4]):
            return (Tool.POLICESTATION, fx4, fy4)

    # Step 11: Add vertical wire branches from spine for better coverage
    for spine_wire_y, start_x, end_x in [
        (A_WIRE_Y, A_START_X, A_END_X),
        (B_WIRE_Y, B_START_X, B_END_X)
    ]:
        for bx in range(start_x, end_x + 1, 6):
            if not in_bounds(bx, spine_wire_y): continue
            if not (bool(wm[spine_wire_y, bx]) or bool(pm[spine_wire_y, bx])): continue
            for sign in [-1, 1]:
                for dy in range(1, 6):
                    wy = spine_wire_y + sign * dy
                    if not in_bounds(bx, wy): break
                    if bool(wm[wy, bx]) or bool(pm[wy, bx]): continue
                    if bool(em[wy, bx]) and not bool(rm[wy, bx]):
                        return (Tool.WIRE, bx, wy)
                    break

    # Step 12: Extend roads to reach more zones
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = int(obs.step * 13) % max(len(road_xs_arr), 1)
        rx_s = int(road_xs_arr[step_k])
        ry_s = int(road_ys_arr[step_k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx_s + dx2, ry_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    New strategy: horizontal layout instead of vertical spine.
    - Place power plant near top-left area
    - Run horizontal wire row from plant
    - Run horizontal road row below wire
    - Place zones above and below the road in columns
    - Build multiple neighborhoods expanding rightward
    - Balance zone mix: 40% res, 35% com, 25% ind
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    all_zone_mask = resm | comm | indm

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        if com_count / t < 0.30:
            return Tool.COMMERCIAL
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    # Fixed layout parameters
    # Power plant at top-left cluster
    plant_x, plant_y = 10, 20  # center of plant
    wire_row = plant_y + 4      # horizontal wire row
    road_row = wire_row + 1     # horizontal road row
    top_zone_row = wire_row - 3  # zones above wire
    bot_zone_row = road_row + 3  # zones below road

    # Phase 1: Place coal power plant
    if not np.any(pm):
        return (Tool.COALPOWER, plant_x, plant_y)

    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Recalculate rows based on actual plant position
    wire_row = plant_cy + 4
    road_row = wire_row + 1
    top_zone_row = wire_row - 3
    bot_zone_row = road_row + 3

    wire_row = max(2, min(WORLD_H - 2, wire_row))
    road_row = max(2, min(WORLD_H - 2, road_row))
    top_zone_row = max(1, min(WORLD_H - 2, top_zone_row))
    bot_zone_row = max(1, min(WORLD_H - 2, bot_zone_row))

    # How far right to extend (grows with population)
    if obs.city_pop < 100:
        right_extent = plant_cx + 20
    elif obs.city_pop < 300:
        right_extent = plant_cx + 35
    elif obs.city_pop < 600:
        right_extent = plant_cx + 55
    else:
        right_extent = plant_cx + 75

    right_extent = min(WORLD_W - 4, right_extent)
    left_start = plant_cx + 2  # start wire/road just right of plant

    # Phase 2: Build horizontal wire row from plant rightward
    for c in range(left_start, right_extent + 1):
        if 0 <= c < WORLD_W:
            if not wm[wire_row, c] and not pm[wire_row, c]:
                if em[wire_row, c]:
                    return (Tool.WIRE, c, wire_row)
                # If blocked by zone, skip

    # Phase 3: Build horizontal road row
    for c in range(left_start, right_extent + 1):
        if 0 <= c < WORLD_W:
            if not rm[road_row, c] and not pm[road_row, c]:
                if em[road_row, c]:
                    return (Tool.ROAD, c, road_row)

    # Phase 4: Place vertical connector wires from wire row to zones above
    zone_cols = list(range(left_start + 1, right_extent, 4))
    for zc in zone_cols:
        if 0 <= zc < WORLD_W:
            # Wire from wire_row upward to top zone area
            for r in range(wire_row - 1, top_zone_row - 2, -1):
                if 0 <= r < WORLD_H:
                    if not wm[r, zc] and not pm[r, zc] and em[r, zc]:
                        return (Tool.WIRE, zc, r)
                    elif not em[r, zc] and not wm[r, zc]:
                        break

    # Phase 5: Place zones above wire row
    for zc in zone_cols:
        zr = top_zone_row
        if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
            # Check wire nearby
            r0 = max(0, zr - 4)
            r1 = min(WORLD_H, zr + 5)
            c0 = max(0, zc - 4)
            c1 = min(WORLD_W, zc + 5)
            has_wire = bool(np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1]))
            has_road = bool(np.any(rm[r0:r1, c0:c1]))
            if has_wire and has_road:
                return (pick_tool(), zc, zr)

    # Phase 6: Place zones below road row
    for zc in zone_cols:
        zr = bot_zone_row
        if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
            r0 = max(0, zr - 4)
            r1 = min(WORLD_H, zr + 5)
            c0 = max(0, zc - 4)
            c1 = min(WORLD_W, zc + 5)
            has_wire = bool(np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1]))
            has_road = bool(np.any(rm[r0:r1, c0:c1]))
            if has_wire and has_road:
                return (pick_tool(), zc, zr)

    # Phase 7: Wire connectors down to bottom zones
    for zc in zone_cols:
        for r in range(wire_row + 1, bot_zone_row + 2):
            if 0 <= r < WORLD_H:
                if rm[r, zc]:
                    continue  # don't overwrite road
                if not wm[r, zc] and not pm[r, zc] and em[r, zc]:
                    return (Tool.WIRE, zc, r)
                elif not em[r, zc] and not wm[r, zc] and not rm[r, zc]:
                    break

    # Phase 8: Second power plant when needed
    plant_count = int(np.sum(pm))
    if obs.city_pop > 200 and plant_count < 9:
        # Place second plant further right
        px2 = plant_cx + 30
        py2 = plant_cy
        if 2 <= px2 <= WORLD_W - 4 and 2 <= py2 <= WORLD_H - 4:
            area_clear = True
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    if not em[py2+dr, px2+dc]:
                        area_clear = False
            if area_clear:
                return (Tool.COALPOWER, px2, py2)

    # Phase 9: Second row of zones (double neighborhood vertically)
    if obs.city_pop > 150:
        top_zone_row2 = top_zone_row - 6
        bot_zone_row2 = bot_zone_row + 6
        top_zone_row2 = max(1, top_zone_row2)
        bot_zone_row2 = min(WORLD_H - 2, bot_zone_row2)

        for zc in zone_cols:
            # Wire connections for second rows
            for r in range(top_zone_row - 1, top_zone_row2 - 1, -1):
                if 0 <= r < WORLD_H and 0 <= zc < WORLD_W:
                    if not wm[r, zc] and not pm[r, zc] and em[r, zc]:
                        return (Tool.WIRE, zc, r)
                    elif not em[r, zc] and not wm[r, zc]:
                        break

        for zc in zone_cols:
            zr = top_zone_row2
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                r0, r1 = max(0,zr-5), min(WORLD_H, zr+6)
                c0, c1 = max(0,zc-5), min(WORLD_W, zc+6)
                has_wire = bool(np.any(wm[r0:r1,c0:c1]) or np.any(pm[r0:r1,c0:c1]))
                has_road = bool(np.any(rm[r0:r1,c0:c1]))
                if has_wire and has_road:
                    return (pick_tool(), zc, zr)

        for zc in zone_cols:
            for r in range(road_row + 1, bot_zone_row2 + 1):
                if 0 <= r < WORLD_H and 0 <= zc < WORLD_W:
                    if rm[r, zc]:
                        continue
                    if not wm[r, zc] and not pm[r, zc] and em[r, zc]:
                        return (Tool.WIRE, zc, r)
                    elif not em[r, zc] and not wm[r, zc] and not rm[r, zc]:
                        break

        for zc in zone_cols:
            zr = bot_zone_row2
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                r0, r1 = max(0,zr-5), min(WORLD_H, zr+6)
                c0, c1 = max(0,zc-5), min(WORLD_W, zc+6)
                has_wire = bool(np.any(wm[r0:r1,c0:c1]) or np.any(pm[r0:r1,c0:c1]))
                has_road = bool(np.any(rm[r0:r1,c0:c1]))
                if has_wire and has_road:
                    return (pick_tool(), zc, zr)

    # Phase 10: Fill any gaps in wire/road rows
    for c in range(left_start, right_extent + 1):
        if 0 <= c < WORLD_W:
            if not wm[wire_row, c] and not pm[wire_row, c] and em[wire_row, c]:
                return (Tool.WIRE, c, wire_row)
            if not rm[road_row, c] and not pm[road_row, c] and em[road_row, c]:
                return (Tool.ROAD, c, road_row)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Each step reads tile_map freshly to decide what to place next
    - Strategy: place coal plant, wire spine outward from plant, 
      roads parallel to wire, zones adjacent to roads
    - More compact layout with better power connectivity
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    has_plant = np.any(pm)

    # --- Phase 1: Place coal power plant ---
    if not has_plant:
        # Place at a clear spot near center-left
        return (Tool.COALPOWER, 40, 50)

    # Find plant center
    plant_rows, plant_cols = np.where(pm)
    pcx = int(np.mean(plant_cols))
    pcy = int(np.mean(plant_rows))

    # Layout constants (relative to plant)
    # Wire spine runs vertically at pcx+4
    # Roads at pcx+7 and pcx+1 (closer to plant)
    # Zones at pcx+10 and pcx-2 (between road and plant)
    spine_col = pcx + 4
    road_r = pcx + 7
    road_l = pcx + 1
    zone_r = road_r + 3
    zone_l = road_l - 3

    # Clamp
    spine_col = max(1, min(WORLD_W - 2, spine_col))
    road_r = max(1, min(WORLD_W - 2, road_r))
    road_l = max(1, min(WORLD_W - 2, road_l))
    zone_r = max(2, min(WORLD_W - 3, zone_r))
    zone_l = max(2, min(WORLD_W - 3, zone_l))

    # Vertical span grows with population
    half = min(35, max(12, 12 + obs.city_pop // 10))
    tmin = max(2, pcy - half)
    tmax = min(WORLD_H - 3, pcy + half)

    # --- Helper: check 3x3 zone area clear ---
    def zone_clear(zy, zx):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                rr, rc = zy + dr, zx + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    all_zone_m = res_m | com_m | ind_m

    def nearby_zone(zy, zx, r=3):
        r0 = max(0, zy - r); r1 = min(WORLD_H, zy + r + 1)
        c0 = max(0, zx - r); c1 = min(WORLD_W, zx + r + 1)
        return np.any(all_zone_m[r0:r1, c0:c1])

    res_count = max(1, int(np.sum(res_m)) // 9)
    com_count = max(1, int(np.sum(com_m)) // 9)
    ind_count = max(1, int(np.sum(ind_m)) // 9)

    def pick_zone():
        total = res_count + com_count + ind_count
        # Aim: 50% res, 25% com, 25% ind
        if com_count * 4 < total:
            return Tool.COMMERCIAL
        if ind_count * 4 < total:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # --- Phase 2: Wire spine from plant outward ---
    # First connect plant to spine horizontally
    # Wire from plant right edge (pcx+2) to spine_col
    for wc in range(pcx + 2, spine_col + 1):
        if 0 <= wc < WORLD_W:
            if not wm[pcy, wc] and (em[pcy, wc] or True):
                # Place wire if not already wire (auto-bulldoze handles other tiles)
                if not wm[pcy, wc]:
                    return (Tool.WIRE, wc, pcy)

    # Build vertical wire spine
    spine_wire_rows = [r for r in range(WORLD_H) if 0 <= spine_col < WORLD_W and wm[r, spine_col]]
    if not spine_wire_rows:
        # Start at pcy
        return (Tool.WIRE, spine_col, pcy)
    else:
        minr = spine_wire_rows[0]
        maxr = spine_wire_rows[-1]
        # Extend downward
        if maxr < tmax:
            nr = maxr + 1
            if 0 <= nr < WORLD_H:
                return (Tool.WIRE, spine_col, nr)
        # Extend upward
        if minr > tmin:
            nr = minr - 1
            if 0 <= nr < WORLD_H:
                return (Tool.WIRE, spine_col, nr)

    spine_set = set(spine_wire_rows)

    # --- Phase 3: Roads parallel to spine ---
    # Right road
    if 0 <= road_r < WORLD_W:
        for sr in spine_wire_rows:
            if tmin <= sr <= tmax and not rm[sr, road_r]:
                return (Tool.ROAD, road_r, sr)
    # Left road (closer to plant)
    if 0 <= road_l < WORLD_W:
        for sr in spine_wire_rows:
            if tmin <= sr <= tmax and not rm[sr, road_l]:
                return (Tool.ROAD, road_l, sr)

    # --- Phase 4: Horizontal road connectors every 6 rows ---
    if spine_wire_rows:
        for sr in spine_wire_rows:
            if tmin <= sr <= tmax and (sr - tmin) % 6 == 0:
                for rc in range(road_l, road_r + 1):
                    if 0 <= rc < WORLD_W and not rm[sr, rc] and em[sr, rc]:
                        return (Tool.ROAD, rc, sr)

    # --- Phase 5: Place zones adjacent to roads ---
    road_rows_r = set(r for r in range(WORLD_H) if 0 <= road_r < WORLD_W and rm[r, road_r])
    road_rows_l = set(r for r in range(WORLD_H) if 0 <= road_l < WORLD_W and rm[r, road_l])

    if spine_wire_rows:
        for sr in spine_wire_rows:
            if not (tmin <= sr <= tmax):
                continue
            # Right zone
            road_near_r = any(abs(sr - rr) <= 1 for rr in road_rows_r)
            if road_near_r and 2 <= zone_r <= WORLD_W - 3:
                if not nearby_zone(sr, zone_r, 2) and zone_clear(sr, zone_r):
                    return (pick_zone(), zone_r, sr)
            # Left zone
            road_near_l = any(abs(sr - rr) <= 1 for rr in road_rows_l)
            if road_near_l and 2 <= zone_l <= WORLD_W - 3:
                if not nearby_zone(sr, zone_l, 2) and zone_clear(sr, zone_l):
                    return (pick_zone(), zone_l, sr)
            # Inner right zone (between spine and road_r)
            inner_r = spine_col + 3
            if 2 <= inner_r <= WORLD_W - 3 and road_near_r:
                if not nearby_zone(sr, inner_r, 2) and zone_clear(sr, inner_r):
                    return (pick_zone(), inner_r, sr)

    # --- Phase 6: Second cluster when population grows ---
    if obs.city_pop > 150:
        # Second spine to the left of plant
        spine2 = pcx - 10
        spine2 = max(1, min(WORLD_W - 2, spine2))
        road_r2 = spine2 + 3
        road_l2 = spine2 - 3
        zone_r2 = road_r2 + 3
        zone_l2 = road_l2 - 3
        road_r2 = max(1, min(WORLD_W - 2, road_r2))
        road_l2 = max(1, min(WORLD_W - 2, road_l2))
        zone_r2 = max(2, min(WORLD_W - 3, zone_r2))
        zone_l2 = max(2, min(WORLD_W - 3, zone_l2))

        # Connect horizontally from plant to spine2
        for wc in range(max(0, spine2), pcx - 1):
            if 0 <= wc < WORLD_W and not wm[pcy, wc]:
                return (Tool.WIRE, wc, pcy)

        spine2_rows = [r for r in range(WORLD_H) if 0 <= spine2 < WORLD_W and wm[r, spine2]]
        if not spine2_rows:
            return (Tool.WIRE, spine2, pcy)
        else:
            minr2 = spine2_rows[0]; maxr2 = spine2_rows[-1]
            if maxr2 < tmax:
                return (Tool.WIRE, spine2, maxr2 + 1)
            if minr2 > tmin:
                return (Tool.WIRE, spine2, minr2 - 1)

            # Roads for cluster 2
            if 0 <= road_r2 < WORLD_W:
                for sr in spine2_rows:
                    if tmin <= sr <= tmax and not rm[sr, road_r2]:
                        return (Tool.ROAD, road_r2, sr)
            if 0 <= road_l2 < WORLD_W:
                for sr in spine2_rows:
                    if tmin <= sr <= tmax and not rm[sr, road_l2]:
                        return (Tool.ROAD, road_l2, sr)

            road_rows_r2 = set(r for r in range(WORLD_H) if 0 <= road_r2 < WORLD_W and rm[r, road_r2])
            road_rows_l2 = set(r for r in range(WORLD_H) if 0 <= road_l2 < WORLD_W and rm[r, road_l2])
            for sr in spine2_rows:
                if not (tmin <= sr <= tmax):
                    continue
                road_near_r2 = any(abs(sr - rr) <= 1 for rr in road_rows_r2)
                if road_near_r2 and 2 <= zone_r2 <= WORLD_W - 3:
                    if not nearby_zone(sr, zone_r2, 2) and zone_clear(sr, zone_r2):
                        return (pick_zone(), zone_r2, sr)
                road_near_l2 = any(abs(sr - rr) <= 1 for rr in road_rows_l2)
                if road_near_l2 and 2 <= zone_l2 <= WORLD_W - 3:
                    if not nearby_zone(sr, zone_l2, 2) and zone_clear(sr, zone_l2):
                        return (pick_zone(), zone_l2, sr)

    # --- Phase 7: Second power plant if large city ---
    if obs.city_pop > 400 and not state.get("plant2", False):
        px2 = pcx + 25
        py2 = pcy
        px2 = max(2, min(WORLD_W - 3, px2))
        clear2 = all(
            0 <= py2 + dr < WORLD_H and 0 <= px2 + dc < WORLD_W
            for dr in range(-1, 2) for dc in range(-1, 2)
        )
        if clear2:
            state["plant2"] = True
            return (Tool.COALPOWER, px2, py2)
        # Wire toward second plant location
        for wc in range(spine_col + 1, min(px2 + 1, WORLD_W)):
            if not wm[pcy, wc]:
                return (Tool.WIRE, wc, pcy)

    return None

def act(obs, state):
    """
    Improved policy with a horizontal road layout and better zone distribution.
    Strategy:
    - Place coal power plant at a fixed anchor
    - Run horizontal wire spine from plant
    - Run horizontal road above/below wire spine
    - Place zones (RES/COM/IND mix) on both sides of roads
    - Add second road/wire branch for more zones
    """
    tm = obs.tile_map
    emp = empty_mask(tm)
    res = res_mask(tm)
    com = com_mask(tm)
    ind = ind_mask(tm)
    road = road_mask(tm)
    wire = wire_mask(tm)
    plant = plant_mask(tm)

    # Use center-left anchor for plant
    cx, cy = 30, WORLD_H // 2  # anchor left side

    # Phase 0: Place coal power plant if none exists
    if not np.any(plant):
        return (Tool.COALPOWER, cx, cy)

    plant_ys, plant_xs = np.where(plant)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    # Wire spine: horizontal, same row as plant, extending right
    wire_row = py
    wire_start = px + 2  # just right of plant
    wire_end = px + 40   # extend far right

    # Check if wire spine needs extending (horizontal)
    for wx in range(wire_start, min(wire_end, WORLD_W)):
        if not wire[wire_row, wx] and not plant[wire_row, wx]:
            # Check adjacency to wire or plant
            adj = False
            for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]:
                ny2, nx2 = wire_row+ddy, wx+ddx
                if 0 <= ny2 < WORLD_H and 0 <= nx2 < WORLD_W:
                    if wire[ny2, nx2] or plant[ny2, nx2]:
                        adj = True
                        break
            if adj:
                return (Tool.WIRE, wx, wire_row)

    # Road spines: two horizontal roads, one above and one below wire spine
    road_rows = [wire_row - 4, wire_row + 4]
    road_start = px + 2
    road_end = px + 40

    for road_row in road_rows:
        if not (0 <= road_row < WORLD_H):
            continue
        for rx in range(road_start, min(road_end, WORLD_W)):
            if not road[road_row, rx]:
                # Need adjacency to existing road OR be near wire (bootstrap)
                adj = False
                for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]:
                    ny2, nx2 = road_row+ddy, rx+ddx
                    if 0 <= ny2 < WORLD_H and 0 <= nx2 < WORLD_W:
                        if road[ny2, nx2] or wire[ny2, nx2] or plant[ny2, nx2]:
                            adj = True
                            break
                if adj:
                    return (Tool.ROAD, rx, road_row)

    # Also add vertical connector roads linking the two horizontal roads
    # at intervals of ~8 tiles
    for connector_x in range(road_start + 3, min(road_end, WORLD_W), 8):
        for ry in range(min(road_rows), max(road_rows) + 1):
            if 0 <= ry < WORLD_H and not road[ry, connector_x]:
                adj = False
                for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]:
                    ny2, nx2 = ry+ddy, connector_x+ddx
                    if 0 <= ny2 < WORLD_H and 0 <= nx2 < WORLD_W:
                        if road[ny2, nx2] or wire[ny2, nx2] or plant[ny2, nx2]:
                            adj = True
                            break
                if adj:
                    return (Tool.ROAD, connector_x, ry)

    # Phase 3: Place zones
    zones = res | com | ind
    n_res = int(np.sum(res))
    n_com = int(np.sum(com))
    n_ind = int(np.sum(ind))
    total_zones = n_res + n_com + n_ind

    # Tool selection: balanced mix 2 RES : 1 COM : 1 IND
    step_mod = obs.step % 4
    if step_mod < 2:
        tool = Tool.RESIDENTIAL
    elif step_mod == 2:
        tool = Tool.COMMERCIAL
    else:
        tool = Tool.INDUSTRIAL

    # Build road_near and wire_near maps
    road_near = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            road_near |= np.roll(np.roll(road, dy2, axis=0), dx2, axis=1)

    wire_near = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-4, 5):
        for dx2 in range(-4, 5):
            wire_near |= np.roll(np.roll(wire, dy2, axis=0), dx2, axis=1)
            wire_near |= np.roll(np.roll(plant, dy2, axis=0), dx2, axis=1)

    cand_mask = emp & road_near & wire_near
    # Exclude wire/road rows to avoid blocking infrastructure
    cand_mask[wire_row, :] = False
    for rr in road_rows:
        if 0 <= rr < WORLD_H:
            cand_mask[rr, :] = False

    # Exclude map edges
    cand_mask[:2, :] = False
    cand_mask[98:, :] = False
    cand_mask[:, :2] = False
    cand_mask[:, 118:] = False

    cand_ys, cand_xs = np.where(cand_mask)

    if len(cand_xs) == 0:
        # Fallback: extend road further right
        for rr in road_rows:
            if not (0 <= rr < WORLD_H):
                continue
            for rx in range(road_end, min(road_end + 10, WORLD_W)):
                if 0 <= rx < WORLD_W and not road[rr, rx]:
                    adj = False
                    for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]:
                        ny2, nx2 = rr+ddy, rx+ddx
                        if 0 <= ny2 < WORLD_H and 0 <= nx2 < WORLD_W:
                            if road[ny2, nx2]:
                                adj = True
                                break
                    if adj:
                        return (Tool.ROAD, rx, rr)
        return None

    # Score: prefer positions near road, near existing zones, not too far from plant column
    zone_near = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    if np.any(zones):
        for dy2 in range(-5, 6):
            for dx2 in range(-5, 6):
                zone_near |= np.roll(np.roll(zones, dy2, axis=0), dx2, axis=1)

    scores = []
    for i in range(len(cand_xs)):
        x, y = int(cand_xs[i]), int(cand_ys[i])
        near_zone = 1 if zone_near[y, x] else 0
        dist_from_plant_x = abs(x - px)
        dist_from_wire_row = abs(y - wire_row)
        # Prefer clustered, not too far from plant, near road rows
        score = near_zone * 15 - dist_from_plant_x * 0.05 - dist_from_wire_row * 0.5
        scores.append(score)

    scores = np.array(scores)
    max_score = np.max(scores)
    top_mask = scores >= max_score - 1.0
    top_indices = np.where(top_mask)[0]
    pick = top_indices[obs.step % len(top_indices)]
    bx, by = int(cand_xs[pick]), int(cand_ys[pick])
    return (tool, bx, by)

def act(obs, state):
    """
    Improved policy with:
    - TWO neighborhoods (left cluster and right cluster)
    - Better road grid (horizontal + vertical roads)
    - More balanced zone mix (R:C:I ~ 2:1:1)
    - Wire spine connecting both clusters to power plant
    - Denser placement
    """
    tm = obs.tile_map
    step = obs.step

    # Two cluster centers, horizontally separated
    # Left cluster around (35, 50), right cluster around (80, 50)
    lcx, lcy = 38, 50  # left cluster center
    rcx, rcy = 80, 50  # right cluster center
    plant_x, plant_y = 58, 50  # power plant between clusters

    has_plant = np.any(plant_mask(tm))
    wm = wire_mask(tm)
    rm = road_mask(tm)
    em = empty_mask(tm)
    res_pos = list(zip(*np.where(res_mask(tm)))) if np.any(res_mask(tm)) else []
    com_pos = list(zip(*np.where(com_mask(tm)))) if np.any(com_mask(tm)) else []
    ind_pos = list(zip(*np.where(ind_mask(tm)))) if np.any(ind_mask(tm)) else []
    res_count = len(res_pos)
    com_count = len(com_pos)
    ind_count = len(ind_pos)

    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def near_existing(zr, zc, positions):
        return any(abs(zr - pr) <= 1 and abs(zc - pc) <= 1 for (pr, pc) in positions)

    # Phase 1: Place coal power plant
    if not has_plant:
        return (Tool.COALPOWER, plant_x, plant_y)

    # Phase 2: Build horizontal wire spine from plant leftward and rightward
    # Wire row at plant_y, from plant left edge to lcx+2, and from plant right to rcx-2
    # Plant footprint: plant_x-1 .. plant_x+1, plant_y-1 .. plant_y+1 (3x3)
    # Wire left spine: cols from plant_x-2 down to lcx+2
    wire_spine_row = plant_y
    # Build wire leftward
    for wc in range(plant_x - 2, lcx + 1, -1):
        if 0 <= wc < WORLD_W:
            if not wm[wire_spine_row, wc]:
                if em[wire_spine_row, wc]:
                    return (Tool.WIRE, wc, wire_spine_row)
    # Build wire rightward
    for wc in range(plant_x + 2, rcx):
        if 0 <= wc < WORLD_W:
            if not wm[wire_spine_row, wc]:
                if em[wire_spine_row, wc]:
                    return (Tool.WIRE, wc, wire_spine_row)

    # Phase 3: Build vertical wire spines at lcx+2 and rcx-2 for zone rows
    zone_rows = list(range(lcy - 12, lcy + 13, 4))
    left_wire_col = lcx + 2
    right_wire_col = rcx - 2

    for zr in zone_rows:
        if 0 <= zr < WORLD_H:
            if not wm[zr, left_wire_col]:
                if em[zr, left_wire_col]:
                    return (Tool.WIRE, left_wire_col, zr)
            if not wm[zr, right_wire_col]:
                if em[zr, right_wire_col]:
                    return (Tool.WIRE, right_wire_col, zr)

    # Also connect vertical wire spines to horizontal spine
    for r in range(min(zone_rows), max(zone_rows) + 1):
        if 0 <= r < WORLD_H:
            if not wm[r, left_wire_col] and em[r, left_wire_col]:
                return (Tool.WIRE, left_wire_col, r)
            if not wm[r, right_wire_col] and em[r, right_wire_col]:
                return (Tool.WIRE, right_wire_col, r)

    # Phase 4: Build roads adjacent to wire spines
    # Left cluster road at lcx+3, right cluster road at rcx-3
    left_road_col = lcx + 3
    right_road_col = rcx - 3

    for zr in zone_rows:
        if 0 <= zr < WORLD_H:
            if not rm[zr, left_road_col] and em[zr, left_road_col]:
                return (Tool.ROAD, left_road_col, zr)
            if not rm[zr, right_road_col] and em[zr, right_road_col]:
                return (Tool.ROAD, right_road_col, zr)

    # Also build horizontal cross-roads at zone rows
    for zr in zone_rows:
        if 0 <= zr < WORLD_H:
            # Left cluster: short horizontal road segment
            for rc in range(lcx - 1, lcx + 3):
                if 0 <= rc < WORLD_W and not rm[zr, rc] and em[zr, rc]:
                    return (Tool.ROAD, rc, zr)
            # Right cluster: short horizontal road segment
            for rc in range(rcx - 2, rcx + 2):
                if 0 <= rc < WORLD_W and not rm[zr, rc] and em[zr, rc]:
                    return (Tool.ROAD, rc, zr)

    # Phase 5: Place zones
    # Left cluster: zones at lcx-1 (center), rows = zone_rows
    # Right cluster: zones at rcx+1 (center), rows = zone_rows
    # Zone mix: 2R : 1C : 1I pattern cycling by row index

    def pick_zone_type(row_idx, side):
        # Pattern: R, R, C, I cycling
        pattern = [Tool.RESIDENTIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.INDUSTRIAL]
        return pattern[row_idx % 4]

    for i, zr in enumerate(zone_rows):
        # Left cluster zones (center at lcx-1, adjacent to road at lcx+3 via row road)
        lzc = lcx - 1
        if 0 <= zr < WORLD_H and 0 <= lzc < WORLD_W:
            ztype = pick_zone_type(i, 'left')
            all_pos = res_pos + com_pos + ind_pos
            if not near_existing(zr, lzc, all_pos) and zone_area_free(zr, lzc):
                return (ztype, lzc, zr)

        # Right cluster zones (center at rcx+1)
        rzc = rcx + 1
        if 0 <= zr < WORLD_H and 0 <= rzc < WORLD_W:
            ztype = pick_zone_type(i + 2, 'right')
            all_pos = res_pos + com_pos + ind_pos
            if not near_existing(zr, rzc, all_pos) and zone_area_free(zr, rzc):
                return (ztype, rzc, zr)

    # Phase 6: Additional zone columns for density
    # Left cluster second column at lcx-5
    for i, zr in enumerate(zone_rows):
        lzc2 = lcx - 5
        if 0 <= zr < WORLD_H and 0 <= lzc2 < WORLD_W:
            ztype = pick_zone_type(i + 1, 'left2')
            all_pos = res_pos + com_pos + ind_pos
            if not near_existing(zr, lzc2, all_pos) and zone_area_free(zr, lzc2):
                return (ztype, lzc2, zr)

        rzc2 = rcx + 5
        if 0 <= zr < WORLD_H and 0 <= rzc2 < WORLD_W:
            ztype = pick_zone_type(i + 3, 'right2')
            all_pos = res_pos + com_pos + ind_pos
            if not near_existing(zr, rzc2, all_pos) and zone_area_free(zr, rzc2):
                return (ztype, rzc2, zr)

    # Phase 7: Wire lateral connections to zone columns
    for zr in zone_rows:
        for wc in range(lcx - 2, left_wire_col):
            if 0 <= wc < WORLD_W and not wm[zr, wc] and em[zr, wc]:
                return (Tool.WIRE, wc, zr)
        for wc in range(right_wire_col + 1, rcx + 2):
            if 0 <= wc < WORLD_W and not wm[zr, wc] and em[zr, wc]:
                return (Tool.WIRE, wc, zr)

    # Phase 8: Expand zone rows if population growing
    extra_rows = list(range(lcy - 20, lcy - 12, 4)) + list(range(lcy + 13, lcy + 21, 4))
    for i, zr in enumerate(extra_rows):
        for zc in [lcx - 1, rcx + 1]:
            if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                all_pos = res_pos + com_pos + ind_pos
                if not near_existing(zr, zc, all_pos) and zone_area_free(zr, zc):
                    # Need wire and road at this row first
                    wc = left_wire_col if zc == lcx - 1 else right_wire_col
                    rc = left_road_col if zc == lcx - 1 else right_road_col
                    if not wm[zr, wc] and em[zr, wc]:
                        return (Tool.WIRE, wc, zr)
                    if not rm[zr, rc] and em[zr, rc]:
                        return (Tool.ROAD, rc, zr)
                    ztype = pick_zone_type(i, 'extra')
                    return (ztype, zc, zr)

    return None

def act(obs, state):
    """
    Hybrid policy combining best of both parents:
    - Two cluster approach from Parent B (better fitness)
    - Reactive/closed-loop logic from Parent A
    - Wire spine + road flanking from Parent B
    - Zone placement with 3x3 clearance check
    - Balanced zone types
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    zone_mask = resm | comm | indm

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Two cluster anchors
    P1X, P1Y = 30, 50
    P2X, P2Y = 85, 50

    # Phase 1: ensure power plants exist near anchors
    plant_ys, plant_xs = np.where(pm)
    has_plant1 = any(abs(int(px) - P1X) < 8 and abs(int(py) - P1Y) < 8
                     for py, px in zip(plant_ys.tolist(), plant_xs.tolist()))
    has_plant2 = any(abs(int(px) - P2X) < 8 and abs(int(py) - P2Y) < 8
                     for py, px in zip(plant_ys.tolist(), plant_xs.tolist()))

    if not has_plant1:
        return (Tool.COALPOWER, P1X, P1Y)
    if not has_plant2:
        return (Tool.COALPOWER, P2X, P2Y)

    # Phase 2: build wire spines from each plant
    # Vertical spine at each plant x, plus horizontal connecting wire
    wire_targets = []
    for dy in range(-15, 16):
        wire_targets.append((P1X, P1Y + dy))
        wire_targets.append((P2X, P2Y + dy))
    # Horizontal wire connection between spines at mid-level
    for x in range(P1X, P2X + 1):
        wire_targets.append((x, P1Y))

    for (wx, wy) in wire_targets:
        if not in_bounds(wx, wy):
            continue
        if bool(wm[wy, wx]) or bool(pm[wy, wx]) or bool(rm[wy, wx]):
            continue
        # Only place wire if adjacent to existing power
        adj_power = False
        for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = wx + ddx, wy + ddy
            if in_bounds(nx2, ny2) and (bool(pm[ny2, nx2]) or bool(wm[ny2, nx2])):
                adj_power = True
                break
        if adj_power and bool(em[wy, wx]):
            return (Tool.WIRE, wx, wy)

    # Phase 3: build roads flanking wire spines and cross-roads
    road_targets = []
    # Vertical roads flanking each spine
    for dy in range(-15, 16):
        road_targets.append((P1X + 3, P1Y + dy))
        road_targets.append((P1X - 3, P1Y + dy))
        road_targets.append((P2X + 3, P2Y + dy))
        road_targets.append((P2X - 3, P2Y + dy))
    # Horizontal cross-roads
    for offset in [-9, -6, -3, 0, 3, 6, 9]:
        for x in range(P1X - 15, P1X + 16):
            road_targets.append((x, P1Y + offset))
        for x in range(P2X - 15, P2X + 16):
            road_targets.append((x, P2Y + offset))
    # Highway connecting two clusters
    for x in range(P1X + 4, P2X - 3):
        road_targets.append((x, P1Y + 6))
        road_targets.append((x, P1Y - 6))

    for (rx, ry) in road_targets:
        if not in_bounds(rx, ry):
            continue
        if bool(rm[ry, rx]):
            continue
        if bool(pm[ry, rx]) or bool(wm[ry, rx]):
            continue
        # Only place road if adjacent to existing road or near plant
        adj_road = False
        for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx + ddx, ry + ddy
            if in_bounds(nx2, ny2) and bool(rm[ny2, nx2]):
                adj_road = True
                break
        adj_plant = False
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1),(2,0),(-2,0),(0,2),(0,-2),
                         (3,0),(-3,0),(0,3),(0,-3)]:
            nx2, ny2 = rx + ddx, ry + ddy
            if in_bounds(nx2, ny2) and bool(pm[ny2, nx2]):
                adj_plant = True
                break
        if (adj_road or adj_plant) and bool(em[ry, rx]):
            return (Tool.ROAD, rx, ry)

    # Phase 4: place zones near roads AND power
    # Build neighbor masks for road (radius 2) and power (radius 6)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand = em & nbr_road & nbr_power
    # Exclude map edges (need 3x3 clearance)
    cand[0:2, :] = False
    cand[WORLD_H-2:, :] = False
    cand[:, 0:2] = False
    cand[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        key = int(obs.step * 17 + int(obs.city_pop * 3) + 1) % len(cxs)
        for offset in range(min(len(cxs), 100)):
            k = (key + offset * 11) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            # Check 3x3 clearance: all cells must be empty or zone
            ok = True
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    ny2, nx2 = zy + dr, zx + dc
                    if not in_bounds(nx2, ny2):
                        ok = False; break
                    if not (bool(em[ny2, nx2]) or bool(zone_mask[ny2, nx2])):
                        ok = False; break
                if not ok:
                    break
            if ok:
                return (pick_tool(), zx, zy)

    # Phase 5: services when population warrants
    if obs.city_pop > 200:
        for fx, fy in [(P1X + 5, P1Y - 12), (P2X - 5, P2Y + 12)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 400:
        for fx, fy in [(P1X + 5, P1Y + 12), (P2X - 5, P2Y - 12)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.POLICESTATION, fx, fy)

    # Phase 6: add nuclear plant if large population
    if obs.city_pop > 600:
        for nx3, ny3 in [(60, 30), (60, 70)]:
            adj_p = any(abs(int(px) - nx3) < 8 and abs(int(py) - ny3) < 8
                        for py, px in zip(plant_ys.tolist(), plant_xs.tolist()))
            if not adj_p and in_bounds(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.NUCLEARPOWER, nx3, ny3)

    # Fallback: extend road from existing frontier
    rys2, rxs2 = np.where(rm)
    if len(rxs2) > 0:
        k2 = int(obs.step * 13) % len(rxs2)
        rx2, ry2 = int(rxs2[k2]), int(rys2[k2])
        for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx2 + ddx, ry2 + ddy
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire from existing frontier
    wys2, wxs2 = np.where(wm)
    if len(wxs2) > 0:
        k3 = int(obs.step * 7) % len(wxs2)
        wx2, wy2 = int(wxs2[k3]), int(wys2[k3])
        for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = wx2 + ddx, wy2 + ddy
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Improved policy: Use a grid-based approach with horizontal roads and vertical wires.
    Place power plant, run wire horizontally, roads vertically, zones in blocks.
    Mix R/C/I zones in a balanced ratio. Build denser and faster.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    step = obs.step

    # Use state to track a build queue
    if "queue" not in state:
        state["queue"] = []
        state["phase"] = 0
        state["built"] = set()

    # Helper: check if 3x3 area is free
    def area_free(cx, cy):
        for dy in [-1, 0, 1]:
            for dx in [-1, 0, 1]:
                r, c = cy + dy, cx + dx
                if r < 0 or r >= WORLD_H or c < 0 or c >= WORLD_W:
                    return False
                if not em[r, c]:
                    return False
        return True

    # Helper: pick zone type for balance
    def pick_zone(idx):
        # Cycle: R R C R I R C R R C I ...
        # Roughly 50% R, 25% C, 25% I
        pattern = [Tool.RESIDENTIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL,
                   Tool.RESIDENTIAL, Tool.INDUSTRIAL, Tool.RESIDENTIAL,
                   Tool.COMMERCIAL, Tool.RESIDENTIAL]
        return pattern[idx % len(pattern)]

    # Build plan: centered layout
    # Power plant at (30, 50), wire runs right from it
    # Roads run N-S at fixed columns, zones fill between

    cx0 = 30  # plant x
    cy0 = 50  # plant y

    # If no plant, place it
    if not np.any(pm):
        return (Tool.COALPOWER, cx0, cy0)

    plant_rows, plant_cols = np.where(pm)
    pcx = int(np.mean(plant_cols))
    pcy = int(np.mean(plant_rows))

    # Wire runs horizontally from plant rightward
    # Road columns at pcx+8, pcx+16, pcx+24, pcx+32
    # Zones between road columns

    wire_row = pcy  # horizontal wire at plant's row
    road_cols = [pcx + 8, pcx + 16, pcx + 24, pcx + 32, pcx + 40]
    road_cols = [c for c in road_cols if 2 <= c <= WORLD_W - 3]

    # Vertical span
    span = min(20, 6 + obs.city_pop // 30)
    tmin = max(2, pcy - span)
    tmax = min(WORLD_H - 3, pcy + span)

    # Phase 1: Lay horizontal wire from plant to rightmost road col
    if road_cols:
        rightmost = road_cols[-1]
        # Wire from plant edge to rightmost road
        for wc in range(pcx + 4, rightmost + 1):
            if 0 <= wc < WORLD_W and not wm[wire_row, wc] and em[wire_row, wc]:
                return (Tool.WIRE, wc, wire_row)

    # Phase 2: Lay vertical roads
    for rc in road_cols:
        for rr in range(tmin, tmax + 1):
            if not rm[rr, rc] and em[rr, rc]:
                return (Tool.ROAD, rc, rr)

    # Phase 3: Place horizontal connector roads every 6 rows
    connector_rows = list(range(tmin, tmax + 1, 6))
    if road_cols:
        for cr in connector_rows:
            for cc in range(road_cols[0], road_cols[-1] + 1):
                if not rm[cr, cc] and em[cr, cc]:
                    return (Tool.ROAD, cc, cr)

    # Phase 4: Place zones in slots between road columns
    zone_idx = state.get("zone_idx", 0)

    for i in range(len(road_cols) - 1):
        lc = road_cols[i]
        rc = road_cols[i + 1]
        # Zone center columns between roads
        gap = rc - lc
        if gap >= 6:
            zc = lc + gap // 2
            # Place zones vertically in this column
            for zr in range(tmin + 3, tmax - 2, 6):
                key = (zc, zr)
                if key in state["built"]:
                    continue
                # Check road access (within 1 tile of road)
                has_road = False
                for dr in [-1, 0, 1]:
                    for dc in [-3, -2, -1, 0, 1, 2, 3]:
                        nr, nc = zr + dr, zc + dc
                        if 0 <= nr < WORLD_H and 0 <= nc < WORLD_W and rm[nr, nc]:
                            has_road = True
                            break
                    if has_road:
                        break
                if has_road and area_free(zc, zr):
                    state["built"].add(key)
                    zt = pick_zone(zone_idx)
                    state["zone_idx"] = zone_idx + 1
                    return (zt, zc, zr)
                zone_idx = state.get("zone_idx", 0)

    # Phase 5: Also place zones just outside outermost roads
    if road_cols:
        # Left of first road
        lc_outer = road_cols[0] - 4
        if 2 <= lc_outer <= WORLD_W - 3:
            for zr in range(tmin + 3, tmax - 2, 6):
                key = ("L", lc_outer, zr)
                if key not in state["built"] and area_free(lc_outer, zr):
                    has_road = any(rm[zr + dr, road_cols[0]]
                                   for dr in range(-3, 4)
                                   if 0 <= zr + dr < WORLD_H)
                    if has_road:
                        state["built"].add(key)
                        return (pick_zone(zone_idx), lc_outer, zr)

        # Right of last road
        rc_outer = road_cols[-1] + 4
        if 2 <= rc_outer <= WORLD_W - 3:
            for zr in range(tmin + 3, tmax - 2, 6):
                key = ("R", rc_outer, zr)
                if key not in state["built"] and area_free(rc_outer, zr):
                    has_road = any(rm[zr + dr, road_cols[-1]]
                                   for dr in range(-3, 4)
                                   if 0 <= zr + dr < WORLD_H)
                    if has_road:
                        state["built"].add(key)
                        return (pick_zone(zone_idx), rc_outer, zr)

    # Phase 6: Second power plant when pop grows
    if obs.city_pop >= 200 and not state.get("plant2", False):
        px2 = pcx + 50
        py2 = pcy
        px2 = max(2, min(WORLD_W - 3, px2))
        if area_free(px2, py2):
            state["plant2"] = True
            return (Tool.COALPOWER, px2, py2)
        # Try to clear space
        state["plant2"] = True  # prevent infinite retry

    # Phase 7: Extend wire to second plant area
    if obs.city_pop >= 200:
        px2 = min(pcx + 50, WORLD_W - 3)
        for wc in range(rightmost + 1 if road_cols else pcx + 4, px2 + 1):
            if 0 <= wc < WORLD_W and not wm[wire_row, wc] and em[wire_row, wc]:
                return (Tool.WIRE, wc, wire_row)

        # More roads in second cluster
        road_cols2 = [px2 - 8, px2 + 8]
        road_cols2 = [c for c in road_cols2 if 2 <= c <= WORLD_W - 3]
        for rc in road_cols2:
            for rr in range(tmin, tmax + 1):
                if not rm[rr, rc] and em[rr, rc]:
                    return (Tool.ROAD, rc, rr)

        # Zones in second cluster
        for rc in road_cols2:
            zc2 = rc + 4 if rc < px2 else rc - 4
            if 2 <= zc2 <= WORLD_W - 3:
                for zr in range(tmin + 3, tmax - 2, 6):
                    key = ("P2", zc2, zr)
                    if key not in state["built"] and area_free(zc2, zr):
                        has_road = any(rm[zr + dr, rc]
                                       for dr in range(-3, 4)
                                       if 0 <= zr + dr < WORLD_H)
                        if has_road:
                            state["built"].add(key)
                            return (pick_zone(zone_idx + 1), zc2, zr)

    # Phase 8: Expand vertical span
    if obs.city_pop >= 100 and road_cols:
        new_tmin = max(2, pcy - min(30, span + 5))
        new_tmax = min(WORLD_H - 3, pcy + min(30, span + 5))
        for rc in road_cols:
            for rr in list(range(new_tmin, tmin)) + list(range(tmax + 1, new_tmax + 1)):
                if not rm[rr, rc] and em[rr, rc]:
                    return (Tool.ROAD, rc, rr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map every step to find current infrastructure
    - Places coal plant, extends wire spine, builds road columns,
      then fills zones reactively based on actual power/road coverage.
    - Key fix: wire must connect plant to zones (lateral wires at zone rows)
    - Road columns flank wire spine; zones placed adjacent to roads
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # Count zones
    res_count = int(np.sum(res_m))
    com_count = int(np.sum(com_m))
    ind_count = int(np.sum(ind_m))

    # --- Phase 1: Place coal power plant if none exists ---
    if not np.any(pm):
        # Plant at center-left area
        return (Tool.COALPOWER, 40, 50)

    # --- Find plant center ---
    plant_rows, plant_cols = np.where(pm)
    # Use centroid of plant tiles
    pr = int(np.mean(plant_rows))
    pc = int(np.mean(plant_cols))

    # Layout relative to plant:
    # wire spine at pc + 4 (just right of plant footprint)
    wire_col = pc + 4
    wire_col = max(5, min(WORLD_W - 6, wire_col))

    # Road columns flanking wire spine
    left_road_col = wire_col - 4
    right_road_col = wire_col + 4
    left_road_col = max(2, min(WORLD_W - 3, left_road_col))
    right_road_col = max(2, min(WORLD_W - 3, right_road_col))

    # Zone columns outside road columns
    left_zone_col = left_road_col - 4
    right_zone_col = right_road_col + 4
    left_zone_col = max(1, min(WORLD_W - 2, left_zone_col))
    right_zone_col = max(1, min(WORLD_W - 2, right_zone_col))

    # Wire spine vertical extent
    spine_top = max(1, pr - 18)
    spine_bot = min(WORLD_H - 2, pr + 18)

    # Scan existing wire in wire_col
    wire_rows_in_col = [r for r in range(WORLD_H) if wm[r, wire_col]]

    # --- Phase 2: Start wire adjacent to plant ---
    if not wire_rows_in_col:
        wy = pr
        if 0 <= wire_col < WORLD_W and 0 <= wy < WORLD_H:
            return (Tool.WIRE, wire_col, wy)

    # --- Phase 3: Extend wire spine up and down ---
    if wire_rows_in_col:
        cur_min = min(wire_rows_in_col)
        cur_max = max(wire_rows_in_col)
        if cur_max < spine_bot:
            nr = cur_max + 1
            if nr < WORLD_H:
                return (Tool.WIRE, wire_col, nr)
        if cur_min > spine_top:
            nr = cur_min - 1
            if nr >= 0:
                return (Tool.WIRE, wire_col, nr)

    # Helper functions
    def near_wire(zr, zc, radius=3):
        r1, r2 = max(0, zr - radius), min(WORLD_H, zr + radius + 1)
        c1, c2 = max(0, zc - radius), min(WORLD_W, zc + radius + 1)
        return np.any(wm[r1:r2, c1:c2])

    def near_road(zr, zc, radius=3):
        r1, r2 = max(0, zr - radius), min(WORLD_H, zr + radius + 1)
        c1, c2 = max(0, zc - radius), min(WORLD_W, zc + radius + 1)
        return np.any(rm[r1:r2, c1:c2])

    def zone_exists_near(zr, zc, mask, radius=3):
        r1, r2 = max(0, zr - radius), min(WORLD_H, zr + radius + 1)
        c1, c2 = max(0, zc - radius), min(WORLD_W, zc + radius + 1)
        return np.any(mask[r1:r2, c1:c2])

    def zone_footprint_clear(zr, zc):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                r2, c2 = zr + dr, zc + dc
                if not (0 <= r2 < WORLD_H and 0 <= c2 < WORLD_W):
                    return False
                if not em[r2, c2]:
                    return False
        return True

    # --- Phase 4: Build road columns along all wire rows ---
    for wr in wire_rows_in_col:
        if 0 <= left_road_col < WORLD_W and not rm[wr, left_road_col]:
            return (Tool.ROAD, left_road_col, wr)
        if 0 <= right_road_col < WORLD_W and not rm[wr, right_road_col]:
            return (Tool.ROAD, right_road_col, wr)

    # --- Phase 5: Lateral wires from spine to zone columns ---
    # Only at rows that are multiples of 3 from spine_top (zone rows)
    zone_rows = list(range(spine_top, spine_bot + 1, 3))

    for zr in zone_rows:
        if zr not in wire_rows_in_col:
            continue
        # Left lateral: wire_col-1 down to left_zone_col+1
        for wc in range(wire_col - 1, left_zone_col - 1, -1):
            if 0 <= wc < WORLD_W and not wm[zr, wc] and em[zr, wc]:
                return (Tool.WIRE, wc, zr)
        # Right lateral: wire_col+1 up to right_zone_col+1
        for wc in range(wire_col + 1, right_zone_col + 2):
            if 0 <= wc < WORLD_W and not wm[zr, wc] and em[zr, wc]:
                return (Tool.WIRE, wc, zr)

    # --- Phase 6: Place zones at zone rows, left and right of roads ---
    for zr in zone_rows:
        if not near_wire(zr, wire_col, radius=2):
            continue

        # Left zone
        zc = left_zone_col
        if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
            if (not zone_exists_near(zr, zc, res_m) and
                    not zone_exists_near(zr, zc, ind_m)):
                if zone_footprint_clear(zr, zc) and near_road(zr, zc):
                    if ind_count < max(1, res_count // 3):
                        return (Tool.INDUSTRIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

        # Right zone
        zc = right_zone_col
        if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
            if (not zone_exists_near(zr, zc, res_m) and
                    not zone_exists_near(zr, zc, com_m)):
                if zone_footprint_clear(zr, zc) and near_road(zr, zc):
                    if com_count < max(1, res_count // 3):
                        return (Tool.COMMERCIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

    # --- Phase 7: If city is growing, add more zone columns ---
    if obs.city_pop > 50:
        extra_left1 = left_zone_col - 5
        extra_right1 = right_zone_col + 5
        extra_left2 = left_zone_col - 10
        extra_right2 = right_zone_col + 10

        # Extend roads outward
        for wr in wire_rows_in_col:
            for rc in range(left_road_col - 1, max(0, extra_left2 - 2), -1):
                if 0 <= rc < WORLD_W and not rm[wr, rc] and em[wr, rc]:
                    return (Tool.ROAD, rc, wr)
            for rc in range(right_road_col + 1, min(WORLD_W - 1, extra_right2 + 3)):
                if 0 <= rc < WORLD_W and not rm[wr, rc] and em[wr, rc]:
                    return (Tool.ROAD, rc, wr)

        for zr in zone_rows:
            if not near_wire(zr, wire_col, radius=4):
                continue
            for zc in [extra_left1, extra_right1, extra_left2, extra_right2]:
                if not (1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1):
                    continue
                all_zones = res_m | com_m | ind_m
                if zone_exists_near(zr, zc, all_zones):
                    continue
                if zone_footprint_clear(zr, zc) and near_road(zr, zc, radius=4):
                    if ind_count < max(1, res_count // 3):
                        return (Tool.INDUSTRIAL, zc, zr)
                    elif com_count < max(1, res_count // 3):
                        return (Tool.COMMERCIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

    # --- Phase 8: Extend wire spine further if population growing ---
    if obs.city_pop > 100 and wire_rows_in_col:
        ext_top = max(1, spine_top - 8)
        ext_bot = min(WORLD_H - 2, spine_bot + 8)
        cur_min = min(wire_rows_in_col)
        cur_max = max(wire_rows_in_col)
        if cur_max < ext_bot:
            nr = cur_max + 1
            if nr < WORLD_H:
                return (Tool.WIRE, wire_col, nr)
        if cur_min > ext_top:
            nr = cur_min - 1
            if nr >= 0:
                return (Tool.WIRE, wire_col, nr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads current map state every step
    - Extends wire/road from existing frontier
    - Places zones adjacent to existing powered+roaded areas
    - Adapts to what's actually on the map
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # === Step 1: Ensure we have a coal power plant ===
    if not np.any(pm):
        return (Tool.COALPOWER, 20, 50)

    # Find plant center
    plant_ys, plant_xs = np.where(pm)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        if com_count / t < 0.22:
            return Tool.COMMERCIAL
        if ind_count / t < 0.22:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    zone_set = set()
    for arr in [resm, comm, indm]:
        ys, xs = np.where(arr)
        for y, x in zip(ys.tolist(), xs.tolist()):
            zone_set.add((int(y), int(x)))

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    # === Step 2: Build wire spine eastward from plant ===
    # Wire runs along py row, extending east
    # Find rightmost wire on spine row
    spine_y = py
    wire_on_spine = []
    for x in range(WORLD_W):
        if bool(wm[spine_y, x]) or bool(pm[spine_y, x]):
            wire_on_spine.append(x)

    # Determine target wire extent based on population
    if obs.city_pop < 100:
        target_wire_x = min(px + 30, WORLD_W - 4)
    elif obs.city_pop < 400:
        target_wire_x = min(px + 55, WORLD_W - 4)
    else:
        target_wire_x = min(px + 80, WORLD_W - 4)

    # Find next gap in wire spine and fill it
    if wire_on_spine:
        rightmost_wire = max(wire_on_spine)
        next_x = rightmost_wire + 1
        if next_x <= target_wire_x and in_bounds(next_x, spine_y):
            if bool(em[spine_y, next_x]):
                return (Tool.WIRE, next_x, spine_y)

    # === Step 3: Build roads parallel to wire spine ===
    road_top = spine_y - 2
    road_bot = spine_y + 2

    # Find rightmost wire extent to know how far roads should go
    if wire_on_spine:
        road_end_x = min(max(wire_on_spine) - 1, WORLD_W - 4)
    else:
        road_end_x = px + 5
    road_start_x = px + 3

    # Build top road
    if 0 <= road_top < WORLD_H:
        for rx in range(road_start_x, road_end_x + 1):
            if not in_bounds(rx, road_top):
                break
            if not bool(rm[road_top, rx]) and bool(em[road_top, rx]):
                return (Tool.ROAD, rx, road_top)

    # Build bottom road
    if 0 <= road_bot < WORLD_H:
        for rx in range(road_start_x, road_end_x + 1):
            if not in_bounds(rx, road_bot):
                break
            if not bool(rm[road_bot, rx]) and bool(em[road_bot, rx]):
                return (Tool.ROAD, rx, road_bot)

    # === Step 4: Vertical connector roads every 6 cols ===
    for vc in range(road_start_x, road_end_x + 1, 6):
        for vr in range(road_top, road_bot + 1):
            if not in_bounds(vc, vr):
                continue
            if not bool(rm[vr, vc]) and not bool(pm[vr, vc]) and bool(em[vr, vc]):
                return (Tool.ROAD, vc, vr)

    # === Step 5: Reactive zone placement ===
    # Compute neighbor masks: near road and near wire/plant
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    # Keep safe distance from borders
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Reactive: use current step + city_pop as hash to vary selection
        step_hash = int(obs.step * 17 + int(obs.city_pop * 3)) % len(cxs_arr)
        for offset in range(min(len(cxs_arr), 80)):
            k = (step_hash + offset * 11) % len(cxs_arr)
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # === Step 6: Second power plant when needed ===
    if total_zones > 10 or obs.city_pop > 250:
        # Place second plant near rightmost wired area
        if wire_on_spine:
            rw = max(wire_on_spine)
            p2x = min(rw + 5, WORLD_W - 5)
        else:
            p2x = min(px + 50, WORLD_W - 5)
        p2y = py
        # Check not too close to existing plant
        nearby = False
        for dy in range(-7, 8):
            for dx in range(-7, 8):
                ny, nx = p2y + dy, p2x + dx
                if in_bounds(nx, ny) and bool(pm[ny, nx]):
                    nearby = True
        if not nearby and in_bounds(p2x, p2y) and bool(em[p2y, p2x]):
            return (Tool.COALPOWER, p2x, p2y)

    # === Step 7: Reactive wire extension outward from any wire frontier ===
    # Find all wire frontier cells (wire adjacent to empty) and extend
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        # Pick based on current step to be reactive
        step_k = int(obs.step * 7 + int(obs.city_pop)) % len(wire_xs)
        for offset in range(min(len(wire_xs), 20)):
            k = (step_k + offset * 3) % len(wire_xs)
            wx = int(wire_xs[k])
            wy = int(wire_ys[k])
            # Prefer extending east or toward uncovered zones
            for dx2, dy2 in [(1, 0), (0, 1), (0, -1), (-1, 0)]:
                nx2, ny2 = wx + dx2, wy + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    # Only extend if it reaches new territory (not near existing wire)
                    near_wire = False
                    for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nnx, nny = nx2+ddx, ny2+ddy
                        if in_bounds(nnx, nny) and bool(wm[nny, nnx]):
                            near_wire = True
                    if not near_wire or dx2 == 1:  # prefer eastward extension
                        return (Tool.WIRE, nx2, ny2)

    # === Step 8: Services for population boost ===
    if obs.city_pop > 200:
        fx, fy = px + 5, py - 8
        if in_bounds(fx, fy) and bool(em[fy, fx]):
            return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 300:
        fx2, fy2 = px + 5, py + 8
        if in_bounds(fx2, fy2) and bool(em[fy2, fx2]):
            return (Tool.POLICESTATION, fx2, fy2)

    # === Step 9: Reactive road extension from frontier ===
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k2 = int(obs.step * 13 + int(obs.city_pop)) % len(road_xs)
        for offset in range(min(len(road_xs), 20)):
            k = (step_k2 + offset * 7) % len(road_xs)
            rx_s = int(road_xs[k])
            ry_s = int(road_ys[k])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = rx_s + dx2, ry_s + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop city builder. Reads tile_map each step and reacts.
    Key improvements over parent:
    - Wire placed ADJACENT to plant immediately (not from plant center)
    - Zones placed closer to plant/wire, not just on pre-computed grid
    - Road built incrementally from existing road frontier
    - Power verified before zone placement
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Find plant location
    plant_ys, plant_xs = np.where(pm)
    has_plant = len(plant_xs) > 0

    # --- Phase 1: Place coal power plant ---
    if not has_plant:
        return (Tool.COALPOWER, 30, 50)

    # Plant centroid
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    wire_ys, wire_xs = np.where(wm)
    road_ys, road_xs = np.where(rm)
    res_ys, res_xs = np.where(resm)
    com_ys, com_xs = np.where(comm)
    ind_ys, ind_xs = np.where(indm)

    wire_set = set(zip(wire_ys.tolist(), wire_xs.tolist()))
    road_set = set(zip(road_ys.tolist(), road_xs.tolist()))
    zone_set = set(zip(
        np.concatenate([res_ys, com_ys, ind_ys]).tolist(),
        np.concatenate([res_xs, com_xs, ind_xs]).tolist()
    ))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        r = res_count / t
        c = com_count / t
        i = ind_count / t
        if c < 0.25:
            return Tool.COMMERCIAL
        if i < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def has_wire_near(zx, zy, r=4):
        for dr in range(-r, r + 1):
            for dc in range(-r, r + 1):
                nr, nc = zy + dr, zx + dc
                if in_bounds(nc, nr) and (wm[nr, nc] or pm[nr, nc]):
                    return True
        return False

    def has_road_near(zx, zy, r=3):
        for dr in range(-r, r + 1):
            for dc in range(-r, r + 1):
                nr, nc = zy + dr, zx + dc
                if in_bounds(nc, nr) and rm[nr, nc]:
                    return True
        return False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    # --- Phase 2: Extend wire from plant in cross pattern ---
    # Wire above plant
    for dy in range(1, 20):
        wy, wx = py - dy, px
        if not in_bounds(wx, wy): break
        if wm[wy, wx] or pm[wy, wx]: continue
        if em[wy, wx]:
            return (Tool.WIRE, wx, wy)
        break

    # Wire below plant
    for dy in range(1, 20):
        wy, wx = py + dy, px
        if not in_bounds(wx, wy): break
        if wm[wy, wx] or pm[wy, wx]: continue
        if em[wy, wx]:
            return (Tool.WIRE, wx, wy)
        break

    # Wire right from plant (main spine)
    for dx in range(1, 50):
        wy, wx = py, px + dx
        if not in_bounds(wx, wy): break
        if wm[wy, wx] or pm[wy, wx]: continue
        if em[wy, wx]:
            return (Tool.WIRE, wx, wy)
        break

    # Wire left from plant
    for dx in range(1, 15):
        wy, wx = py, px - dx
        if not in_bounds(wx, wy): break
        if wm[wy, wx] or pm[wy, wx]: continue
        if em[wy, wx]:
            return (Tool.WIRE, wx, wy)
        break

    # --- Phase 3: Build road grid near wire ---
    # Road rows flanking wire spine (py-4 and py+4)
    road_row_top = py - 4
    road_row_bot = py + 4
    # Road runs from just right of plant to end of wire
    wire_max_x = int(np.max(wire_xs)) if len(wire_xs) > 0 else px
    road_start = px + 2
    road_end = min(wire_max_x + 2, WORLD_W - 3)

    # Build top road incrementally
    if in_bounds(road_start, road_row_top) and in_bounds(road_end, road_row_top):
        top_cols = [c for (r, c) in road_set if r == road_row_top and road_start <= c <= road_end]
        max_top = max(top_cols) if top_cols else road_start - 1
        if max_top < road_end:
            nc = max_top + 1
            if in_bounds(nc, road_row_top) and not pm[road_row_top, nc]:
                return (Tool.ROAD, nc, road_row_top)

    # Build bottom road incrementally
    if in_bounds(road_start, road_row_bot) and in_bounds(road_end, road_row_bot):
        bot_cols = [c for (r, c) in road_set if r == road_row_bot and road_start <= c <= road_end]
        max_bot = max(bot_cols) if bot_cols else road_start - 1
        if max_bot < road_end:
            nc = max_bot + 1
            if in_bounds(nc, road_row_bot) and not pm[road_row_bot, nc]:
                return (Tool.ROAD, nc, road_row_bot)

    # Vertical connector roads every 4 columns
    for vc in range(road_start, road_end + 1, 4):
        for vr in range(road_row_top, road_row_bot + 1):
            if not in_bounds(vc, vr): continue
            if (vr, vc) not in road_set and not pm[vr, vc]:
                return (Tool.ROAD, vc, vr)

    # --- Phase 4: Place zones reactively ---
    # Scan positions near wire+road and place zones
    # Check a grid of potential zone centers near our infrastructure
    best_zones = []
    for zy in range(py - 15, py + 16, 3):
        for zx in range(px + 2, min(road_end + 6, WORLD_W - 3), 3):
            if not (2 <= zy <= WORLD_H - 3 and 2 <= zx <= WORLD_W - 3):
                continue
            if has_road_near(zx, zy, 3) and has_wire_near(zx, zy, 5) and zone_clear(zx, zy):
                best_zones.append((zx, zy))

    if best_zones:
        # Pick first available
        zx, zy = best_zones[0]
        return (pick_tool(), zx, zy)

    # Also check rows above and below main road band
    for row_offset in [road_row_top - 3, road_row_top - 6, road_row_bot + 3, road_row_bot + 6]:
        for zx in range(road_start + 1, road_end, 4):
            zy = row_offset
            if not (2 <= zy <= WORLD_H - 3 and 2 <= zx <= WORLD_W - 3):
                continue
            if has_road_near(zx, zy, 3) and has_wire_near(zx, zy, 5) and zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # --- Phase 5: Extend wire toward unserved zones ---
    for (zyr, zxc) in list(zone_set)[:20]:
        if not has_wire_near(zxc, zyr, 4):
            if wire_set:
                closest_w = min(wire_set, key=lambda p: abs(p[0] - zyr) + abs(p[1] - zxc))
                wr, wc = closest_w
                step_r = (1 if zyr > wr else -1 if zyr < wr else 0)
                step_c = (1 if zxc > wc else -1 if zxc < wc else 0)
                for nr, nc in [(wr + step_r, wc), (wr, wc + step_c)]:
                    if in_bounds(nc, nr) and em[nr, nc] and not pm[nr, nc]:
                        return (Tool.WIRE, nc, nr)

    # --- Phase 6: Second power plant if needed ---
    if obs.city_pop > 200 and np.sum(pm) < 9:
        nx2, ny2 = px + 35, py
        if in_bounds(nx2, ny2) and em[ny2, nx2]:
            return (Tool.COALPOWER, nx2, ny2)

    # --- Phase 7: Services ---
    if obs.city_pop > 100:
        fx, fy = px + 5, py - 10
        if in_bounds(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
        fx2, fy2 = px + 5, py + 10
        if in_bounds(fx2, fy2) and em[fy2, fx2]:
            return (Tool.POLICESTATION, fx2, fy2)

    # --- Phase 8: Reactive zone placement using dilated masks ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            r0 = max(0, dy); r1 = WORLD_H
            c0 = max(0, dx); c1 = WORLD_W
            sr0 = max(0, -dy); sr1 = WORLD_H - max(0, dy)
            sc0 = max(0, -dx); sc1 = WORLD_W - max(0, dx)
            if r1 > r0 and c1 > c0 and sr1 > sr0 and sc1 > sc0:
                nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            r0 = max(0, dy); r1 = WORLD_H
            c0 = max(0, dx); c1 = WORLD_W
            sr0 = max(0, -dy); sr1 = WORLD_H - max(0, dy)
            sc0 = max(0, -dx); sc1 = WORLD_W - max(0, dx)
            if r1 > r0 and c1 > c0 and sr1 > sr0 and sc1 > sc0:
                nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
                nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand = em & nbr_road & nbr_wire
    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        # Try a few candidates
        step_hash = (obs.step * 17 + int(tm[py, px]) % 100) % max(1, len(cxs))
        for attempt in range(min(20, len(cxs))):
            k = (step_hash + attempt * 7) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # --- Phase 9: Extend road from frontier ---
    if len(road_xs) > 0:
        k = int(obs.step * 7) % len(road_xs)
        rx, ry = int(road_xs[k]), int(road_ys[k])
        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx + dx, ry + dy
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy v3:
    - Fully reactive: reads tile_map each step to find frontiers
    - Strategy: place plant near center-left, wire spine rightward,
      then road parallel, then zones between them
    - Key improvements over parent:
      1. Wire extends HORIZONTALLY from plant (not vertically)
      2. Road runs HORIZONTALLY parallel below wire
      3. Zones placed in rows between wire and road rows
      4. More compact initial build to ensure connectivity
      5. Scan actual tile_map to find frontiers each step
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    all_zone = resm | comm | indm

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                # Allow empty or already a zone tile (zones overlap during placement)
                if not em[rr, rc] and not all_zone[rr, rc]:
                    return False
        return True

    def zone_exists_near(zr, zc, r=3):
        r0 = max(0, zr - r); r1 = min(WORLD_H, zr + r + 1)
        c0 = max(0, zc - r); c1 = min(WORLD_W, zc + r + 1)
        return np.any(all_zone[r0:r1, c0:c1])

    def wire_near(zr, zc, radius=3):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def road_near(zr, zc, radius=3):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    pop = obs.city_pop

    # --- Phase 1: Place coal power plant near center-left ---
    if not np.any(pm):
        px, py = cx - 15, cy
        # Make sure placement area is clear
        px = max(2, min(WORLD_W - 3, px))
        py = max(2, min(WORLD_H - 3, py))
        return (Tool.COALPOWER, px, py)

    # Find plant centroid
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # We build TWO horizontal wire rows (one above, one below plant center)
    # Then roads between them, then zones between road and wire rows
    # Wire rows: plant_cy - 4 and plant_cy + 4
    wire_row_top = plant_cy - 4
    wire_row_bot = plant_cy + 4
    # Road rows just inside the wire rows
    road_row_top = plant_cy - 2
    road_row_bot = plant_cy + 2

    # Clamp rows
    wire_row_top = max(1, min(WORLD_H - 2, wire_row_top))
    wire_row_bot = max(1, min(WORLD_H - 2, wire_row_bot))
    road_row_top = max(1, min(WORLD_H - 2, road_row_top))
    road_row_bot = max(1, min(WORLD_H - 2, road_row_bot))

    # Horizontal extent based on population
    if pop < 50:
        x_end = plant_cx + 20
    elif pop < 200:
        x_end = plant_cx + 35
    elif pop < 500:
        x_end = plant_cx + 55
    else:
        x_end = plant_cx + 75

    x_start = plant_cx + 2
    x_end = max(x_start + 10, min(WORLD_W - 3, x_end))

    # --- Phase 2: Extend wire row TOP from plant rightward ---
    # Find rightmost wire in top wire row
    top_wire_cols = sorted([c for c in range(WORLD_W) if wm[wire_row_top, c]])
    if not top_wire_cols:
        # Start wire adjacent to plant
        wc = plant_cx + 2
        if 0 <= wc < WORLD_W and em[wire_row_top, wc]:
            return (Tool.WIRE, wc, wire_row_top)
        # Try connecting from plant row
        for dc in range(1, 5):
            wc = plant_cx + dc
            if 0 <= wc < WORLD_W and em[wire_row_top, wc]:
                return (Tool.WIRE, wc, wire_row_top)
        return None

    max_top_wire = max(top_wire_cols)
    # Extend top wire rightward
    if max_top_wire < x_end:
        nwc = max_top_wire + 1
        if nwc < WORLD_W and em[wire_row_top, nwc]:
            return (Tool.WIRE, nwc, wire_row_top)

    # --- Phase 3: Extend wire row BOTTOM from plant rightward ---
    bot_wire_cols = sorted([c for c in range(WORLD_W) if wm[wire_row_bot, c]])
    if not bot_wire_cols:
        wc = plant_cx + 2
        if 0 <= wc < WORLD_W and em[wire_row_bot, wc]:
            return (Tool.WIRE, wc, wire_row_bot)
        for dc in range(1, 5):
            wc = plant_cx + dc
            if 0 <= wc < WORLD_W and em[wire_row_bot, wc]:
                return (Tool.WIRE, wc, wire_row_bot)
        return None

    max_bot_wire = max(bot_wire_cols)
    if max_bot_wire < x_end:
        nwc = max_bot_wire + 1
        if nwc < WORLD_W and em[wire_row_bot, nwc]:
            return (Tool.WIRE, nwc, wire_row_bot)

    # Current wire coverage
    max_wire_reach = min(max_top_wire, max_bot_wire)

    # --- Phase 4: Connect plant to wire rows (vertical wire bridges) ---
    # Connect from plant to top wire row
    for r in range(min(plant_cy, wire_row_top), max(plant_cy, wire_row_top) + 1):
        if not wm[r, plant_cx + 1] and not pm[r, plant_cx + 1]:
            if em[r, plant_cx + 1]:
                return (Tool.WIRE, plant_cx + 1, r)

    # --- Phase 5: Build road row TOP ---
    top_road_cols = sorted([c for c in range(WORLD_W) if rm[road_row_top, c]])
    if top_road_cols:
        max_top_road = max(top_road_cols)
    else:
        max_top_road = x_start - 1

    road_target = min(max_wire_reach, x_end)
    if max_top_road < road_target:
        nrc = max_top_road + 1
        if nrc < WORLD_W and em[road_row_top, nrc]:
            return (Tool.ROAD, nrc, road_row_top)
        elif nrc >= x_start:
            # Start road from scratch
            for c in range(x_start, road_target + 1):
                if em[road_row_top, c]:
                    return (Tool.ROAD, c, road_row_top)

    # --- Phase 6: Build road row BOTTOM ---
    bot_road_cols = sorted([c for c in range(WORLD_W) if rm[road_row_bot, c]])
    if bot_road_cols:
        max_bot_road = max(bot_road_cols)
    else:
        max_bot_road = x_start - 1

    if max_bot_road < road_target:
        nrc = max_bot_road + 1
        if nrc < WORLD_W and em[road_row_bot, nrc]:
            return (Tool.ROAD, nrc, road_row_bot)
        elif nrc >= x_start:
            for c in range(x_start, road_target + 1):
                if em[road_row_bot, c]:
                    return (Tool.ROAD, c, road_row_bot)

    # Current road coverage
    top_road_cols2 = sorted([c for c in range(WORLD_W) if rm[road_row_top, c]])
    bot_road_cols2 = sorted([c for c in range(WORLD_W) if rm[road_row_bot, c]])

    # --- Phase 7: Place zones between wire row and road row ---
    # Zone rows: cy-3 (between wire_row_top and road_row_top)
    # and cy+3 (between wire_row_bot and road_row_bot)
    # Zone center row candidates
    zone_row_top = plant_cy - 3  # between wire_row_top=-4 and road_row_top=-2
    zone_row_mid = plant_cy      # center row
    zone_row_bot = plant_cy + 3  # between road_row_bot=+2 and wire_row_bot=+4

    zone_row_top = max(1, min(WORLD_H - 2, zone_row_top))
    zone_row_mid = max(1, min(WORLD_H - 2, zone_row_mid))
    zone_row_bot = max(1, min(WORLD_H - 2, zone_row_bot))

    # Place zones along zone rows where both wire and road are nearby
    for zr in [zone_row_top, zone_row_bot, zone_row_mid]:
        for zc in range(x_start + 1, x_end, 4):
            zc = max(2, min(WORLD_W - 3, zc))
            if zone_area_ok(zr, zc) and not zone_exists_near(zr, zc, 2):
                if wire_near(zr, zc, 4) and road_near(zr, zc, 4):
                    return (pick_tool(), zc, zr)

    # --- Phase 8: Vertical roads to connect top and bottom roads ---
    # Place vertical road segments at regular intervals
    if top_road_cols2 and bot_road_cols2:
        max_road_x = min(max(top_road_cols2), max(bot_road_cols2))
        for vc in range(x_start + 4, max_road_x + 1, 8):
            vc = max(2, min(WORLD_W - 3, vc))
            for vr in range(road_row_top, road_row_bot + 1):
                if em[vr, vc] and not rm[vr, vc]:
                    return (Tool.ROAD, vc, vr)

    # --- Phase 9: Extend infrastructure further if population growing ---
    if pop > 200:
        # Second wire row cluster further right
        x_end2 = min(WORLD_W - 3, x_end + 25)
        # Extend wires
        if max_top_wire < x_end2:
            nwc = max_top_wire + 1
            if nwc < WORLD_W and em[wire_row_top, nwc]:
                return (Tool.WIRE, nwc, wire_row_top)
        if max_bot_wire < x_end2:
            nwc = max_bot_wire + 1
            if nwc < WORLD_W and em[wire_row_bot, nwc]:
                return (Tool.WIRE, nwc, wire_row_bot)

    # --- Phase 10: Second power plant if large population ---
    plant_count = max(1, int(np.sum(pm)) // 6)
    if pop > 300 and plant_count < 2:
        px2 = plant_cx + 5
        py2 = plant_cy - 10
        px2 = max(2, min(WORLD_W - 3, px2))
        py2 = max(2, min(WORLD_H - 3, py2))
        area_ok = all(
            (em[py2 + dr, px2 + dc] or pm[py2 + dr, px2 + dc])
            for dr in [-1, 0, 1] for dc in [-1, 0, 1]
            if 0 <= py2 + dr < WORLD_H and 0 <= px2 + dc < WORLD_W
        )
        if area_ok:
            return (Tool.COALPOWER, px2, py2)

    # --- Phase 11: Dense zone scan for any open good spot ---
    for zr in range(max(1, plant_cy - 8), min(WORLD_H - 2, plant_cy + 9), 3):
        for zc in range(x_start, min(x_end + 1, WORLD_W - 2), 3):
            if zone_area_ok(zr, zc) and not zone_exists_near(zr, zc, 2):
                if wire_near(zr, zc, 5) and road_near(zr, zc, 5):
                    return (pick_tool(), zc, zr)

    # --- Phase 12: Extend wire upward/downward for more rows ---
    if pop > 100:
        # Add more horizontal wire rows above and below
        for extra_dy in [6, 8, 10, 12]:
            for sign in [-1, 1]:
                new_wire_row = plant_cy + sign * extra_dy
                new_wire_row = max(1, min(WORLD_H - 2, new_wire_row))
                row_wires = [c for c in range(WORLD_W) if wm[new_wire_row, c]]
                if not row_wires:
                    # Start from plant column
                    wc = plant_cx + 2
                    if 0 <= wc < WORLD_W and em[new_wire_row, wc]:
                        return (Tool.WIRE, wc, new_wire_row)
                else:
                    mw = max(row_wires)
                    ext = min(x_end, WORLD_W - 3)
                    if mw < ext:
                        nwc = mw + 1
                        if nwc < WORLD_W and em[new_wire_row, nwc]:
                            return (Tool.WIRE, nwc, new_wire_row)

    return None

def act(obs, state):
    """
    Evolved hybrid policy:
    - Reactive closed-loop reading tile_map each step
    - Coal power plant near center-left
    - Vertical wire spine adjacent to plant
    - Road column adjacent to wire
    - Zones on both sides with balanced typing (50% res, 25% com, 25% ind)
    - Lateral wires to left zones, lateral roads to right zones
    - Dynamic spine expansion based on population
    - Second power plant + expansion for large cities
    - Multiple zone columns for wider coverage
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = 60, 50

    # Phase 1: place coal plant if none
    plant_cx, plant_cy = cx - 6, cy
    if not np.any(pm):
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Find plant centroid
    plant_rows, plant_cols = np.where(pm)
    actual_pcx = int(np.mean(plant_cols))
    actual_pcy = int(np.mean(plant_rows))

    # Wire spine column just right of plant, road column adjacent
    wire_col = actual_pcx + 3
    road_col = wire_col + 1
    left_zone_col = wire_col - 3
    right_zone_col = road_col + 3

    # Clamp columns
    wire_col = max(2, min(WORLD_W - 3, wire_col))
    road_col = max(2, min(WORLD_W - 3, road_col))
    left_zone_col = max(3, min(WORLD_W - 4, left_zone_col))
    right_zone_col = max(3, min(WORLD_W - 4, right_zone_col))

    pop = obs.city_pop

    # Dynamic spine span based on population
    base_span = 10
    extra_span = min(35, pop // 30)
    target_span = base_span + extra_span
    tmin = max(1, cy - target_span)
    tmax = min(WORLD_H - 2, cy + target_span)

    # Zone counts for balanced tool selection
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool(zr, zc):
        if total_zones == 0:
            return Tool.RESIDENTIAL
        # Aim for ~50% res, 25% com, 25% ind
        if com_count * 4 < total_zones:
            return Tool.COMMERCIAL
        if ind_count * 4 < total_zones:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Phase 2: wire spine
    wire_rows_in_col = sorted(r for r in range(WORLD_H) if wm[r, wire_col])

    if not wire_rows_in_col:
        # First wire adjacent to plant
        for dy in range(-1, 3):
            nr = actual_pcy + dy
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        return None

    min_wr = min(wire_rows_in_col)
    max_wr = max(wire_rows_in_col)

    # Extend downward
    if max_wr < tmax:
        nr = max_wr + 1
        if 0 <= nr < WORLD_H and not pm[nr, wire_col] and (em[nr, wire_col] or wm[nr, wire_col]):
            return (Tool.WIRE, wire_col, nr)

    # Extend upward
    if min_wr > tmin:
        nr = min_wr - 1
        if 0 <= nr < WORLD_H and not pm[nr, wire_col] and (em[nr, wire_col] or wm[nr, wire_col]):
            return (Tool.WIRE, wire_col, nr)

    # Phase 3: build road column adjacent to wire spine
    road_rows_set = set(r for r in range(WORLD_H) if rm[r, road_col])

    for wr in wire_rows_in_col:
        if tmin <= wr <= tmax and wr not in road_rows_set:
            if 0 <= road_col < WORLD_W and em[wr, road_col]:
                return (Tool.ROAD, road_col, wr)

    # Phase 4: place zones adjacent to road/wire
    all_zone_mask = resm | comm | indm

    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def zone_nearby(zr, zc):
        for dr in [-2, -1, 0, 1, 2]:
            for dc in [-2, -1, 0, 1, 2]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    wire_rows_set = set(wire_rows_in_col)

    for zr in wire_rows_in_col:
        if not (tmin <= zr <= tmax):
            continue
        road_nearby = any(abs(zr - rr) <= 2 for rr in road_rows_set)
        wire_near = True

        if not (road_nearby and wire_near):
            continue

        for zc in [left_zone_col, right_zone_col]:
            if 1 <= zr <= WORLD_H - 2 and 1 <= zc <= WORLD_W - 2:
                if not zone_nearby(zr, zc) and zone_area_free(zr, zc):
                    return (pick_tool(zr, zc), zc, zr)

    # Phase 5: lateral wires from spine to left zones
    for wr in wire_rows_in_col:
        if not (tmin <= wr <= tmax):
            continue
        for wc in range(wire_col - 1, max(0, left_zone_col - 1), -1):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc] and not wm[wr, wc]:
                    break

    # Phase 6: lateral roads from road column to right zones
    for wr in wire_rows_in_col:
        if not (tmin <= wr <= tmax):
            continue
        for rc in range(road_col + 1, right_zone_col):
            if 0 <= rc < WORLD_W:
                if rm[wr, rc]:
                    break
                if em[wr, rc] and not pm[wr, rc]:
                    return (Tool.ROAD, rc, wr)
                elif not em[wr, rc]:
                    break

    # Phase 7: second coal plant if population > 200 and only one plant
    num_plant_tiles = int(np.sum(pm))
    if pop > 200 and num_plant_tiles < 9:
        px2 = actual_pcx + 14
        py2 = actual_pcy
        px2 = max(2, min(WORLD_W - 3, px2))
        py2 = max(2, min(WORLD_H - 3, py2))
        area_ok = True
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = py2 + dr, px2 + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    area_ok = False
                elif not em[rr, rc] and not pm[rr, rc]:
                    area_ok = False
        if area_ok:
            return (Tool.COALPOWER, px2, py2)

    # Phase 8: expand right with second road column for larger cities
    if pop > 150:
        road_col2 = road_col + 8
        right_zone_col2 = road_col2 + 3
        road_col2 = max(2, min(WORLD_W - 3, road_col2))
        right_zone_col2 = max(3, min(WORLD_W - 4, right_zone_col2))

        # Extend wire to road_col2
        for wr in wire_rows_in_col:
            if not (tmin <= wr <= tmax):
                continue
            for wc in range(wire_col + 1, road_col2):
                if 0 <= wc < WORLD_W:
                    if wm[wr, wc] or rm[wr, wc]:
                        break
                    if em[wr, wc] and not pm[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    elif not em[wr, wc]:
                        break

        # Build road_col2
        road2_rows_set = set(r for r in range(WORLD_H) if rm[r, road_col2])
        for wr in wire_rows_in_col:
            if tmin <= wr <= tmax and wr not in road2_rows_set:
                if 0 <= road_col2 < WORLD_W and em[wr, road_col2]:
                    return (Tool.ROAD, road_col2, wr)

        # Lateral roads from road_col2 to right_zone_col2
        for wr in wire_rows_in_col:
            if not (tmin <= wr <= tmax):
                continue
            for rc in range(road_col2 + 1, right_zone_col2):
                if 0 <= rc < WORLD_W:
                    if rm[wr, rc]:
                        break
                    if em[wr, rc] and not pm[wr, rc]:
                        return (Tool.ROAD, rc, wr)
                    elif not em[wr, rc]:
                        break

        # Zones at right_zone_col2
        for zr in wire_rows_in_col:
            if not (tmin <= zr <= tmax):
                continue
            road_nearby2 = any(abs(zr - rr) <= 2 for rr in road2_rows_set)
            if road_nearby2:
                if 1 <= zr <= WORLD_H - 2 and 1 <= right_zone_col2 <= WORLD_W - 2:
                    if not zone_nearby(zr, right_zone_col2) and zone_area_free(zr, right_zone_col2):
                        return (pick_tool(zr, right_zone_col2), right_zone_col2, zr)

    # Phase 9: expand left with outer left zone column for large pop
    if pop > 150:
        outer_left = left_zone_col - 4
        outer_left = max(3, outer_left)

        # Ensure wire reaches outer_left
        for wr in wire_rows_in_col:
            if not (tmin <= wr <= tmax):
                continue
            for wc in range(wire_col - 1, max(0, outer_left - 2), -1):
                if 0 <= wc < WORLD_W:
                    if wm[wr, wc]:
                        break
                    if em[wr, wc] and not pm[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    elif not em[wr, wc] and not wm[wr, wc]:
                        break

        # Lateral road to outer_left for road access
        for wr in wire_rows_in_col:
            if not (tmin <= wr <= tmax):
                continue
            for rc in range(road_col - 1, max(0, outer_left - 1), -1):
                if 0 <= rc < WORLD_W:
                    if rm[wr, rc]:
                        break
                    if em[wr, rc] and not pm[wr, rc]:
                        return (Tool.ROAD, rc, wr)
                    elif not em[wr, rc]:
                        break

        for zr in wire_rows_in_col:
            if not (tmin <= zr <= tmax):
                continue
            wn = any(wm[zr, wc] for wc in range(max(0, outer_left - 1), min(WORLD_W, wire_col + 1)))
            rn = any(rm[zr, rc] for rc in range(max(0, outer_left - 1), min(WORLD_W, road_col + 1)))
            if wn and rn and 1 <= zr <= WORLD_H - 2 and 1 <= outer_left <= WORLD_W - 2:
                if not zone_nearby(zr, outer_left) and zone_area_free(zr, outer_left):
                    return (pick_tool(zr, outer_left), outer_left, zr)

    return None

def act(obs, state):
    """
    Improved city builder with:
    - Two neighborhoods side by side
    - Better wire/road coverage
    - Mixed zones (RES/COM/IND balanced)
    - Second power plant placed early
    - Vertical road spine connecting two horizontal clusters
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Two cluster centers
    # Cluster A: left side
    AX, AY = 25, 35
    # Cluster B: right side
    BX, BY = 65, 35

    res_count = int(np.sum(resm)) // 9 + 1
    com_count = int(np.sum(comm)) // 9 + 1
    ind_count = int(np.sum(indm)) // 9 + 1
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        # Aim for ~50% res, 25% com, 25% ind
        r = res_count / total_zones
        c = com_count / total_zones
        i = ind_count / total_zones
        if c < 0.22:
            return Tool.COMMERCIAL
        if i < 0.22:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Initialize state
    if 'phase' not in state:
        state['phase'] = 'plant_a'
        state['wire_col'] = AX + 2
        state['road_col_a'] = AX + 2
        state['road_col_b'] = BX + 2
        state['wire_col_b'] = BX + 2

    plant_ys, plant_xs = np.where(pm)
    n_plants = len(plant_ys) // 9  # rough count

    # Step 1: Place plant A
    if not np.any(pm):
        return (Tool.COALPOWER, AX, AY)

    # Find plants
    plants = []
    visited = set()
    for py2, px2 in zip(plant_ys.tolist(), plant_xs.tolist()):
        # cluster nearby plant tiles
        key = (py2 // 3, px2 // 3)
        if key not in visited:
            visited.add(key)
            plants.append((int(px2), int(py2)))

    pAx, pAy = plants[0][0], plants[0][1]

    # Place second power plant for cluster B if not present
    need_plant_b = True
    for (ppx, ppy) in plants:
        if abs(ppx - BX) < 10 and abs(ppy - BY) < 10:
            need_plant_b = False
            break

    if need_plant_b and total_zones > 5:
        # Check if area is clear enough
        if in_bounds(BX, BY) and bool(em[BY, BX]):
            return (Tool.COALPOWER, BX, BY)

    # Build wire spine for cluster A: horizontal at row AY from pAx+2 to AX+40
    wire_end_a = min(AX + 45, 70)
    for wx in range(pAx + 2, wire_end_a + 1):
        wy = AY
        if not in_bounds(wx, wy):
            break
        if not bool(wm[wy, wx]) and not bool(pm[wy, wx]):
            if bool(em[wy, wx]):
                return (Tool.WIRE, wx, wy)
            break  # blocked, skip

    # Build wire spine for cluster B: horizontal at row BY from BX-2 to BX+40
    wire_end_b = min(BX + 45, WORLD_W - 4)
    for wx in range(BX - 2, wire_end_b + 1):
        wy = BY
        if not in_bounds(wx, wy):
            break
        if not bool(wm[wy, wx]) and not bool(pm[wy, wx]):
            if bool(em[wy, wx]):
                return (Tool.WIRE, wx, wy)
            break

    # Wire vertical branches for cluster A (up and down from AY)
    branch_cols_a = list(range(pAx + 4, wire_end_a + 1, 4))
    for bx in branch_cols_a:
        if not in_bounds(bx, AY):
            continue
        if not (bool(wm[AY, bx]) or bool(pm[AY, bx])):
            continue  # spine not ready here
        for sign in [-1, 1]:
            for dy in range(1, 10):
                wy2, wx2 = AY + sign * dy, bx
                if not in_bounds(wx2, wy2):
                    break
                if bool(wm[wy2, wx2]) or bool(pm[wy2, wx2]):
                    continue
                if bool(em[wy2, wx2]):
                    return (Tool.WIRE, wx2, wy2)
                break

    # Wire vertical branches for cluster B
    branch_cols_b = list(range(BX - 2, wire_end_b + 1, 4))
    for bx in branch_cols_b:
        if not in_bounds(bx, BY):
            continue
        if not (bool(wm[BY, bx]) or bool(pm[BY, bx])):
            continue
        for sign in [-1, 1]:
            for dy in range(1, 10):
                wy2, wx2 = BY + sign * dy, bx
                if not in_bounds(wx2, wy2):
                    break
                if bool(wm[wy2, wx2]) or bool(pm[wy2, wx2]):
                    continue
                if bool(em[wy2, wx2]):
                    return (Tool.WIRE, wx2, wy2)
                break

    # --- Roads for cluster A ---
    # Two parallel roads: AY-3 and AY+3
    road_start_a = pAx + 2
    road_end_a = min(pAx + 44, 72)

    for rx in range(road_start_a, road_end_a + 1):
        for ry in [AY - 3, AY + 3]:
            if not in_bounds(rx, ry):
                continue
            if not bool(rm[ry, rx]) and not bool(pm[ry, rx]) and not bool(wm[ry, rx]):
                if bool(em[ry, rx]):
                    return (Tool.ROAD, rx, ry)
                break

    # Vertical connectors for cluster A every 6 cols
    for vc in range(road_start_a, road_end_a + 1, 6):
        for vr in range(AY - 3, AY + 4):
            if not in_bounds(vc, vr):
                continue
            if not bool(rm[vr, vc]) and not bool(pm[vr, vc]) and not bool(wm[vr, vc]):
                if bool(em[vr, vc]):
                    return (Tool.ROAD, vc, vr)

    # --- Roads for cluster B ---
    road_start_b = BX - 2
    road_end_b = min(BX + 44, WORLD_W - 4)

    for rx in range(road_start_b, road_end_b + 1):
        for ry in [BY - 3, BY + 3]:
            if not in_bounds(rx, ry):
                continue
            if not bool(rm[ry, rx]) and not bool(pm[ry, rx]) and not bool(wm[ry, rx]):
                if bool(em[ry, rx]):
                    return (Tool.ROAD, rx, ry)
                break

    # Vertical connectors for cluster B
    for vc in range(road_start_b, road_end_b + 1, 6):
        for vr in range(BY - 3, BY + 4):
            if not in_bounds(vc, vr):
                continue
            if not bool(rm[vr, vc]) and not bool(pm[vr, vc]) and not bool(wm[vr, vc]):
                if bool(em[vr, vc]):
                    return (Tool.ROAD, vc, vr)

    # Connecting road between cluster A and B (at row AY)
    mid_y = (AY + BY) // 2
    cx_start = road_end_a + 1
    cx_end = road_start_b - 1
    for rx in range(cx_start, cx_end + 1):
        ry = AY
        if not in_bounds(rx, ry):
            continue
        if not bool(rm[ry, rx]) and not bool(pm[ry, rx]) and not bool(wm[ry, rx]):
            if bool(em[ry, rx]):
                return (Tool.ROAD, rx, ry)

    # --- Zone placement ---
    zone_set = set(zip(
        np.concatenate([np.where(resm)[0], np.where(comm)[0], np.where(indm)[0]]).tolist(),
        np.concatenate([np.where(resm)[1], np.where(comm)[1], np.where(indm)[1]]).tolist()
    ))

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    # Build neighbor masks for road and wire proximity
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        step_hash = int(obs.step * 17 + int(obs.city_pop * 3)) % max(len(cxs), 1)
        tool = pick_tool()
        for offset in range(min(len(cxs), 60)):
            k = (step_hash + offset * 13) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Services
    if obs.city_pop > 80:
        fx, fy = AX + 8, AY - 10
        if in_bounds(fx, fy) and bool(em[fy, fx]):
            return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 150:
        fx2, fy2 = BX + 5, BY - 10
        if in_bounds(fx2, fy2) and bool(em[fy2, fx2]):
            return (Tool.POLICESTATION, fx2, fy2)

    # Fallback: extend wires/roads from frontier
    wire_ys2, wire_xs2 = np.where(wm)
    if len(wire_xs2) > 0:
        k = int(obs.step * 7) % len(wire_xs2)
        wx2, wy2 = int(wire_xs2[k]), int(wire_ys2[k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = wx2 + dx2, wy2 + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)

    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        k = int(obs.step * 13) % len(road_xs2)
        rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx2 + dx2, ry2 + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Each step reads tile_map to decide next action
    - Layout: coal plant -> wire spine -> parallel roads -> zones between roads
    - Uses BFS-style expansion: extend from existing infrastructure
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # --- Phase 1: Place coal plant if missing ---
    if not np.any(pm):
        return (Tool.COALPOWER, 60, 50)

    # Find plant center
    plant_rows, plant_cols = np.where(pm)
    pcx = int(np.median(plant_cols))
    pcy = int(np.median(plant_rows))

    # Layout constants relative to plant
    # Wire spine runs vertically at pcx+4
    # Road left at pcx+1, road right at pcx+7
    # Zones between: pcx-2..pcx (left block) and pcx+8..pcx+10 (right block)
    wc = pcx + 4   # wire column
    rl = pcx + 1   # left road column
    rr = pcx + 7   # right road column
    # Vertical span
    span = min(25, max(8, 8 + obs.city_pop // 20))
    ytop = max(2, pcy - span)
    ybot = min(WORLD_H - 3, pcy + span)

    # Clamp columns
    wc = max(1, min(WORLD_W - 2, wc))
    rl = max(2, min(WORLD_W - 3, rl))
    rr = max(2, min(WORLD_W - 3, rr))

    # --- Phase 2: Extend wire spine from plant outward ---
    # Wire must be adjacent to plant or existing wire
    wire_ys = sorted(y for y in range(WORLD_H) if wm[y, wc])

    # Check adjacency to plant: plant occupies [pcy-1..pcy+1] x [pcx-1..pcx+1]
    plant_adj_to_wc = (wc >= pcx - 2 and wc <= pcx + 2)

    if not wire_ys:
        # Place first wire adjacent to plant
        for dy in [0, 1, -1, 2, -2]:
            ny = pcy + dy
            if 0 <= ny < WORLD_H and em[ny, wc]:
                return (Tool.WIRE, wc, ny)
        # fallback: place wire directly
        return (Tool.WIRE, wc, pcy)

    wire_top = wire_ys[0]
    wire_bot = wire_ys[-1]

    # Extend wire downward
    if wire_bot < ybot:
        ny = wire_bot + 1
        if 0 <= ny < WORLD_H and (em[ny, wc] or wm[ny, wc]):
            return (Tool.WIRE, wc, ny)

    # Extend wire upward
    if wire_top > ytop:
        ny = wire_top - 1
        if 0 <= ny >= 0 and (em[ny, wc] or wm[ny, wc]):
            return (Tool.WIRE, wc, ny)

    wire_set = set(wire_ys)

    # --- Phase 3: Build left road column where wire exists ---
    # Road at column rl for rows in wire range
    for wy in sorted(wire_set, key=lambda y: abs(y - pcy)):
        if ytop <= wy <= ybot:
            if rl < WORLD_W and not rm[wy, rl] and em[wy, rl]:
                return (Tool.ROAD, rl, wy)

    # --- Phase 4: Build right road column ---
    for wy in sorted(wire_set, key=lambda y: abs(y - pcy)):
        if ytop <= wy <= ybot:
            if rr < WORLD_W and not rm[wy, rr] and em[wy, rr]:
                return (Tool.ROAD, rr, wy)

    # --- Phase 5: Place zones adjacent to roads ---
    all_zone_m = res_m | com_m | ind_m
    res_count = max(1, int(np.sum(res_m)) // 9)
    com_count = max(1, int(np.sum(com_m)) // 9)
    ind_count = max(1, int(np.sum(ind_m)) // 9)

    def pick_zone():
        total = res_count + com_count + ind_count
        # Target 50% res, 25% com, 25% ind
        if com_count * 4 < total:
            return Tool.COMMERCIAL
        if ind_count * 4 < total:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_clear(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr2, rc2 = zr + dr, zc + dc
                if rr2 < 0 or rr2 >= WORLD_H or rc2 < 0 or rc2 >= WORLD_W:
                    return False
                if not em[rr2, rc2]:
                    return False
        return True

    def zone_nearby(zr, zc):
        r0 = max(0, zr - 2)
        r1 = min(WORLD_H, zr + 3)
        c0 = max(0, zc - 2)
        c1 = min(WORLD_W, zc + 3)
        return np.any(all_zone_m[r0:r1, c0:c1])

    # Left zones: column rl-3 (road on right side of zone)
    zl = rl - 3
    zl = max(2, min(WORLD_W - 3, zl))
    # Right zones: column rr+3 (road on left side of zone)
    zr_col = rr + 3
    zr_col = max(2, min(WORLD_W - 3, zr_col))

    # Also inner zones between wire and roads
    zl_inner = rl + 3  # between rl and wc, zones at rl+3
    zr_inner = rr - 3  # between wc and rr, zones at rr-3
    zl_inner = max(2, min(WORLD_W - 3, zl_inner))
    zr_inner = max(2, min(WORLD_W - 3, zr_inner))

    road_rows_l = set(y for y in range(WORLD_H) if rm[y, rl])
    road_rows_r = set(y for y in range(WORLD_H) if rm[y, rr])

    # Sort zone rows by proximity to center for compact growth
    candidate_rows = sorted(
        [wy for wy in wire_set if ytop <= wy <= ybot],
        key=lambda y: abs(y - pcy)
    )

    for zy in candidate_rows:
        near_l = any(abs(zy - ry) <= 1 for ry in road_rows_l)
        near_r = any(abs(zy - ry) <= 1 for ry in road_rows_r)

        # Left outer zones
        if near_l and 2 <= zl <= WORLD_W - 3:
            if not zone_nearby(zy, zl) and zone_clear(zy, zl):
                return (pick_zone(), zl, zy)

        # Right outer zones
        if near_r and 2 <= zr_col <= WORLD_W - 3:
            if not zone_nearby(zy, zr_col) and zone_clear(zy, zr_col):
                return (pick_zone(), zr_col, zy)

        # Left inner zones (between left road and wire)
        if near_l and 2 <= zl_inner <= WORLD_W - 3 and zl_inner != wc:
            if not zone_nearby(zy, zl_inner) and zone_clear(zy, zl_inner):
                return (pick_zone(), zl_inner, zy)

        # Right inner zones (between wire and right road)
        if near_r and 2 <= zr_inner <= WORLD_W - 3 and zr_inner != wc:
            if not zone_nearby(zy, zr_inner) and zone_clear(zy, zr_inner):
                return (pick_zone(), zr_inner, zy)

    # --- Phase 6: Add horizontal road connectors for better connectivity ---
    if obs.city_pop > 30 and road_rows_l and road_rows_r:
        # Connect roads horizontally at center row
        for hy in sorted(list(road_rows_l & road_rows_r), key=lambda y: abs(y - pcy))[:3]:
            for hx in range(min(rl, rr) + 1, max(rl, rr)):
                if 0 <= hx < WORLD_W and not rm[hy, hx] and em[hy, hx]:
                    return (Tool.ROAD, hx, hy)

    # --- Phase 7: Second power plant + cluster when population grows ---
    if obs.city_pop > 200 and not state.get("plant2", False):
        # Place second plant further right
        px2 = pcx + 25
        py2 = pcy
        px2 = max(2, min(WORLD_W - 3, px2))
        py2 = max(2, min(WORLD_H - 3, py2))
        # Check if we have wire bridge to it
        # First build wire bridge from wc to px2+4
        wc2 = px2 + 4
        wc2 = max(1, min(WORLD_W - 2, wc2))
        # Connect horizontally
        for wx in range(wc + 1, min(wc2 + 1, WORLD_W)):
            if em[pcy, wx] or wm[pcy, wx]:
                return (Tool.WIRE, wx, pcy)
        # If bridge is complete, place plant
        if wm[pcy, min(wc2, WORLD_W-1)] or wm[pcy, max(0, px2-1)]:
            clear2 = all(
                0 <= py2+dr < WORLD_H and 0 <= px2+dc < WORLD_W and em[py2+dr, px2+dc]
                for dr in [-1,0,1] for dc in [-1,0,1]
            )
            if clear2:
                state["plant2"] = True
                return (Tool.COALPOWER, px2, py2)

    # --- Phase 8: Extend span if funds allow ---
    if obs.city_pop > 100:
        # Try to extend wire further
        if wire_bot < ybot:
            ny = wire_bot + 1
            if 0 <= ny < WORLD_H and em[ny, wc]:
                return (Tool.WIRE, wc, ny)
        if wire_top > ytop:
            ny = wire_top - 1
            if ny >= 0 and em[ny, wc]:
                return (Tool.WIRE, wc, ny)

    return None

def act(obs, state):
    """
    Closed-loop hybrid policy:
    - Reads tile_map every step to decide next action
    - Vertical wire spine + parallel road column (Parent A style, proven)
    - Zones placed reactively based on what's powered/roaded
    - Dynamic spine growth based on city_pop
    - Multi-cluster expansion as population grows
    - Better zone mix from Parent B
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    all_zone_mask = resm | comm | indm

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        if ind_count / t < 0.28:
            return Tool.INDUSTRIAL
        if com_count / t < 0.33:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    cx, cy = WORLD_W // 2, WORLD_H // 2

    # Phase 1: Place first coal power plant if none exists
    if not np.any(pm):
        return (Tool.COALPOWER, cx - 8, cy)

    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Determine spine geometry based on first plant location
    # Wire column just right of plant, road column further right
    wire_col = plant_cx + 4
    road_col = wire_col + 2
    left_zone_col = wire_col - 3
    right_zone_col = road_col + 3

    wire_col = max(2, min(WORLD_W - 3, wire_col))
    road_col = max(2, min(WORLD_W - 3, road_col))
    left_zone_col = max(2, min(WORLD_W - 3, left_zone_col))
    right_zone_col = max(2, min(WORLD_W - 3, right_zone_col))

    # Dynamic spine extent based on population
    pop = obs.city_pop
    if pop < 50:
        spine_extent = 8
    elif pop < 150:
        spine_extent = 14
    elif pop < 300:
        spine_extent = 20
    elif pop < 600:
        spine_extent = 28
    else:
        spine_extent = 38

    target_min = max(1, cy - spine_extent)
    target_max = min(WORLD_H - 2, cy + spine_extent)

    # Read current wire and road state on spine columns
    wire_rows_on_spine = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])
    road_rows_on_col = sorted([r for r in range(WORLD_H) if rm[r, road_col]])
    road_rows_set = set(road_rows_on_col)

    # Phase 2: Start wire adjacent to plant
    if not wire_rows_on_spine:
        for dy in range(0, 8):
            for nr in [plant_cy + dy, plant_cy - dy]:
                if 0 <= nr < WORLD_H:
                    if em[nr, wire_col] or wm[nr, wire_col]:
                        return (Tool.WIRE, wire_col, nr)
        return None

    min_wire_row = min(wire_rows_on_spine)
    max_wire_row = max(wire_rows_on_spine)

    # Phase 3: Extend wire spine downward if needed
    if max_wire_row < target_max:
        nr = max_wire_row + 1
        if nr < WORLD_H and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Phase 4: Extend wire spine upward if needed
    if min_wire_row > target_min:
        nr = min_wire_row - 1
        if nr >= 0 and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Phase 5: Build road column alongside wire spine (reactively fill gaps)
    for r in wire_rows_on_spine:
        if 0 <= r < WORLD_H and 0 <= road_col < WORLD_W:
            if not rm[r, road_col] and em[r, road_col]:
                return (Tool.ROAD, road_col, r)

    zone_rows = list(range(max(1, target_min), min(WORLD_H - 1, target_max + 1), 3))

    # Phase 6: Lateral wires to left zones
    for wr in wire_rows_on_spine:
        for wc in range(wire_col - 1, max(left_zone_col - 3, 0), -1):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc]:
                    break

    # Phase 7: Road extensions to right zones
    for rr in wire_rows_on_spine:
        if rr not in road_rows_set:
            continue
        for rc in range(road_col + 1, right_zone_col + 2):
            if 0 <= rc < WORLD_W:
                if rm[rr, rc]:
                    break
                if em[rr, rc] and not pm[rr, rc]:
                    return (Tool.ROAD, rc, rr)
                elif not em[rr, rc]:
                    break

    # Phase 8: Wire extensions to right zones
    for wr in wire_rows_on_spine:
        for wc in range(wire_col + 1, right_zone_col + 3):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc] and not rm[wr, wc]:
                    break

    # Phase 9: Place zones - scan reactively for valid spots
    for zr in zone_rows:
        wire_near = any(abs(zr - wr) <= 2 for wr in wire_rows_on_spine)
        road_near = any(abs(zr - rr) <= 2 for rr in road_rows_on_col)

        if wire_near and road_near:
            for zc in [left_zone_col, right_zone_col]:
                if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                    if has_wire_nearby(zr, zc, 5) and has_road_nearby(zr, zc, 5):
                        return (pick_tool(), zc, zr)
        elif wire_near and not road_near:
            # Place zone with just wire if road not close but wire is
            zc = left_zone_col
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc, 4) and has_road_nearby(zr, zc, 6):
                    return (Tool.RESIDENTIAL, zc, zr)

    # Phase 10: Second power plant when city grows large
    if pop > 300 and int(np.sum(pm)) < 9:
        px2 = plant_cx + 22
        py2 = plant_cy
        if 2 <= py2 <= WORLD_H - 3 and 2 <= px2 <= WORLD_W - 3:
            area_clear = all(
                em[py2 + dr, px2 + dc] or pm[py2 + dr, px2 + dc]
                for dr in [-1, 0, 1] for dc in [-1, 0, 1]
                if 0 <= py2 + dr < WORLD_H and 0 <= px2 + dc < WORLD_W
            )
            if area_clear:
                return (Tool.COALPOWER, px2, py2)

    # Phase 11: Second cluster to the right when pop >= 200
    if pop >= 200:
        wire_col2 = road_col + 9
        road_col2 = wire_col2 + 2
        left_zone_col2 = wire_col2 - 3
        right_zone_col2 = road_col2 + 3

        wire_col2 = max(2, min(WORLD_W - 3, wire_col2))
        road_col2 = max(2, min(WORLD_W - 3, road_col2))
        left_zone_col2 = max(2, min(WORLD_W - 3, left_zone_col2))
        right_zone_col2 = max(2, min(WORLD_W - 3, right_zone_col2))

        wire_rows2 = sorted([r for r in range(WORLD_H) if wm[r, wire_col2]])
        road_rows2 = set(r for r in range(WORLD_H) if rm[r, road_col2])

        if not wire_rows2:
            # Build horizontal wire bridge from main spine to cluster2 at plant level
            bridge_row = plant_cy
            for wc in range(wire_col + 1, wire_col2 + 1):
                if 0 <= wc < WORLD_W:
                    if not wm[bridge_row, wc] and em[bridge_row, wc]:
                        return (Tool.WIRE, wc, bridge_row)
                    elif not em[bridge_row, wc] and not wm[bridge_row, wc]:
                        break
        else:
            min_wr2 = min(wire_rows2)
            max_wr2 = max(wire_rows2)

            if max_wr2 < target_max:
                nr = max_wr2 + 1
                if nr < WORLD_H and em[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > target_min:
                nr = min_wr2 - 1
                if nr >= 0 and em[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)

            for wr in wire_rows2:
                if wr not in road_rows2 and em[wr, road_col2]:
                    return (Tool.ROAD, road_col2, wr)

            # Lateral wires left from cluster2 spine
            for wr in wire_rows2:
                for wc in range(wire_col2 - 1, max(left_zone_col2 - 3, 0), -1):
                    if 0 <= wc < WORLD_W:
                        if wm[wr, wc]: break
                        if em[wr, wc] and not pm[wr, wc]:
                            return (Tool.WIRE, wc, wr)
                        elif not em[wr, wc]: break

            # Road extensions to right zone col2
            for rr in wire_rows2:
                if rr not in road_rows2: continue
                for rc in range(road_col2 + 1, right_zone_col2 + 2):
                    if 0 <= rc < WORLD_W:
                        if rm[rr, rc]: break
                        if em[rr, rc] and not pm[rr, rc]:
                            return (Tool.ROAD, rc, rr)
                        elif not em[rr, rc]: break

            for zr in zone_rows:
                wire_near2 = any(abs(zr - wr) <= 2 for wr in wire_rows2)
                road_near2 = any(abs(zr - rr) <= 2 for rr in road_rows2)
                if wire_near2 and road_near2:
                    for zc in [left_zone_col2, right_zone_col2]:
                        if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                            if has_wire_nearby(zr, zc, 6) and has_road_nearby(zr, zc, 5):
                                return (pick_tool(), zc, zr)

    # Phase 12: Third cluster to the left when pop >= 400
    if pop >= 400:
        wire_col3 = wire_col - 11
        road_col3 = wire_col3 - 2
        left_zone_col3 = road_col3 - 3
        right_zone_col3 = wire_col3 + 3

        wire_col3 = max(2, min(WORLD_W - 3, wire_col3))
        road_col3 = max(2, min(WORLD_W - 3, road_col3))
        left_zone_col3 = max(2, min(WORLD_W - 3, left_zone_col3))
        right_zone_col3 = max(2, min(WORLD_W - 3, right_zone_col3))

        wire_rows3 = sorted([r for r in range(WORLD_H) if wm[r, wire_col3]])
        road_rows3 = set(r for r in range(WORLD_H) if rm[r, road_col3])

        if not wire_rows3:
            bridge_row = plant_cy
            for wc in range(wire_col - 1, wire_col3 - 1, -1):
                if 0 <= wc < WORLD_W:
                    if not wm[bridge_row, wc] and em[bridge_row, wc]:
                        return (Tool.WIRE, wc, bridge_row)
                    elif not em[bridge_row, wc] and not wm[bridge_row, wc]:
                        break
        else:
            min_wr3 = min(wire_rows3)
            max_wr3 = max(wire_rows3)

            if max_wr3 < target_max:
                nr = max_wr3 + 1
                if nr < WORLD_H and em[nr, wire_col3]:
                    return (Tool.WIRE, wire_col3, nr)
            if min_wr3 > target_min:
                nr = min_wr3 - 1
                if nr >= 0 and em[nr, wire_col3]:
                    return (Tool.WIRE, wire_col3, nr)

            for wr in wire_rows3:
                if wr not in road_rows3 and em[wr, road_col3]:
                    return (Tool.ROAD, road_col3, wr)

            # Wires right from cluster3 spine
            for wr in wire_rows3:
                for wc in range(wire_col3 + 1, min(right_zone_col3 + 3, WORLD_W)):
                    if 0 <= wc < WORLD_W:
                        if wm[wr, wc]: break
                        if em[wr, wc] and not pm[wr, wc]:
                            return (Tool.WIRE, wc, wr)
                        elif not em[wr, wc]: break

            # Roads left from cluster3 spine
            for rr in wire_rows3:
                if rr not in road_rows3: continue
                for rc in range(road_col3 - 1, max(left_zone_col3 - 2, 0), -1):
                    if 0 <= rc < WORLD_W:
                        if rm[rr, rc]: break
                        if em[rr, rc] and not pm[rr, rc]:
                            return (Tool.ROAD, rc, rr)
                        elif not em[rr, rc]: break

            for zr in zone_rows:
                wire_near3 = any(abs(zr - wr) <= 2 for wr in wire_rows3)
                road_near3 = any(abs(zr - rr) <= 2 for rr in road_rows3)
                if wire_near3 and road_near3:
                    for zc in [left_zone_col3, right_zone_col3]:
                        if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                            if has_wire_nearby(zr, zc, 6) and has_road_nearby(zr, zc, 5):
                                return (pick_tool(), zc, zr)

    # Phase 13: Extra zone columns when pop > 300 (fill gaps)
    if pop > 300:
        extra_cols = [left_zone_col - 5, right_zone_col + 5]
        for zc in extra_cols:
            if 2 <= zc <= WORLD_W - 3:
                for zr in zone_rows:
                    if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                        if has_road_nearby(zr, zc, 6) and has_wire_nearby(zr, zc, 7):
                            return (pick_tool(), zc, zr)

    return None

def act(obs, state):
    """
    Revised policy: Simpler, more reliable city layout.
    - Place coal power plant
    - Build horizontal road directly below/adjacent to plant
    - Build wire spine horizontally from plant
    - Place zones in a grid pattern around road/wire
    - Focus on getting powered zones with road access quickly
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    # Initialize state
    if 'phase' not in state:
        state['phase'] = 0
        state['action_queue'] = []

    # Build action queue if empty
    def enqueue(actions):
        state['action_queue'].extend(actions)

    if state['action_queue']:
        return state['action_queue'].pop(0)

    # Fixed layout coordinates
    # Plant at (20, 50) - left side of map
    px, py = 20, 50

    has_plant = np.any(pm)

    # Step 1: Place power plant
    if not has_plant:
        return (Tool.COALPOWER, px, py)

    # Find actual plant location
    plant_cells = list(zip(*np.where(pm)))
    if plant_cells:
        pr, pc = plant_cells[0]
        py, px = pr, pc

    # Wire runs horizontally from plant eastward
    wire_row = py  # same row as plant center
    wire_start = px + 2  # just right of plant
    wire_end = px + 35   # extend 35 tiles east

    # Road runs parallel, one row below wire
    road_row = py + 2
    road_start = px + 2
    road_end = px + 35

    # Second road row above wire
    road_row2 = py - 2
    road_start2 = px + 2
    road_end2 = px + 35

    # Phase: Build wire spine first
    # Check wire coverage
    wire_built = [c for c in range(wire_start, wire_end + 1) if 0 <= wire_row < WORLD_H and 0 <= c < WORLD_W and wm[wire_row, c]]
    wire_needed = [c for c in range(wire_start, wire_end + 1) if 0 <= wire_row < WORLD_H and 0 <= c < WORLD_W and not wm[wire_row, c]]

    if wire_needed:
        c = wire_needed[0]
        return (Tool.WIRE, c, wire_row)

    # Build primary road (below wire)
    road_needed = [c for c in range(road_start, road_end + 1)
                   if 0 <= road_row < WORLD_H and 0 <= c < WORLD_W and not rm[road_row, c]]
    if road_needed:
        c = road_needed[0]
        return (Tool.ROAD, c, road_row)

    # Build secondary road (above wire)
    road2_needed = [c for c in range(road_start2, road_end2 + 1)
                    if 0 <= road_row2 < WORLD_H and 0 <= c < WORLD_W and not rm[road_row2, c]]
    if road2_needed:
        c = road2_needed[0]
        return (Tool.ROAD, c, road_row2)

    # Now place vertical connecting roads between road_row2, wire_row, road_row
    # at regular intervals to form a grid
    vert_cols = list(range(wire_start + 1, wire_end, 4))
    for vc in vert_cols:
        for r in range(road_row2, road_row + 1):
            if 0 <= r < WORLD_H and 0 <= vc < WORLD_W and not rm[r, vc]:
                return (Tool.ROAD, vc, r)

    # Place zones in the zones between roads
    res_pos = list(zip(*np.where(res_mask(tm))))
    com_pos = list(zip(*np.where(com_mask(tm))))
    ind_pos = list(zip(*np.where(ind_mask(tm))))
    all_zones = res_pos + com_pos + ind_pos

    def zone_exists_near(zr, zc):
        return any(abs(zr - r) <= 1 and abs(zc - c) <= 1 for (r, c) in all_zones)

    def zone_clear(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if pm[rr, rc]:
                    return False
        return True

    res_count = len(res_pos)
    com_count = len(com_pos)
    ind_count = len(ind_pos)
    total = res_count + com_count + ind_count + 1

    def pick_tool():
        # Target: 50% RES, 25% COM, 25% IND
        if ind_count * 4 < total:
            return Tool.INDUSTRIAL
        elif com_count * 4 < total:
            return Tool.COMMERCIAL
        else:
            return Tool.RESIDENTIAL

    # Zone rows: above road_row2 and below road_row
    # Zone centers should be 3 rows from road for road adjacency (within 2 tiles)
    # Upper zones: center at road_row2 - 2 (road adjacent at row road_row2)
    upper_zone_row = road_row2 - 2
    lower_zone_row = road_row + 2

    # Zone columns: every 4 tiles starting from wire_start+1
    zone_cols = list(range(wire_start + 3, wire_end - 1, 4))

    for zc in zone_cols:
        # Upper zone row
        zr = upper_zone_row
        if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
            if not zone_exists_near(zr, zc) and zone_clear(zr, zc):
                # Need wire nearby - add lateral wire if needed
                # Wire is at wire_row; upper zone is at upper_zone_row
                # Connect with vertical wire at zc
                for wr in range(min(wire_row, zr), max(wire_row, zr) + 1):
                    if not wm[wr, zc] and not rm[wr, zc]:
                        return (Tool.WIRE, zc, wr)
                return (pick_tool(), zc, zr)

        # Lower zone row
        zr = lower_zone_row
        if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
            if not zone_exists_near(zr, zc) and zone_clear(zr, zc):
                for wr in range(min(wire_row, zr), max(wire_row, zr) + 1):
                    if not wm[wr, zc] and not rm[wr, zc]:
                        return (Tool.WIRE, zc, wr)
                return (pick_tool(), zc, zr)

    # Extend layout eastward if we have good population
    if obs.city_pop > 100 or (obs.step > obs.n_steps // 3):
        new_wire_end = min(WORLD_W - 3, wire_end + 20)
        # Extend wire
        for c in range(wire_end + 1, new_wire_end + 1):
            if 0 <= c < WORLD_W and not wm[wire_row, c]:
                return (Tool.WIRE, c, wire_row)

        # Extend roads
        for c in range(road_end + 1, new_wire_end + 1):
            if 0 <= c < WORLD_W and not rm[road_row, c]:
                return (Tool.ROAD, c, road_row)
            if 0 <= c < WORLD_W and not rm[road_row2, c]:
                return (Tool.ROAD, c, road_row2)

        # Add more zones in extended area
        ext_zone_cols = list(range(wire_end + 3, new_wire_end - 1, 4))
        for zc in ext_zone_cols:
            for zr in [upper_zone_row, lower_zone_row]:
                if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                    if not zone_exists_near(zr, zc) and zone_clear(zr, zc):
                        for wr in range(min(wire_row, zr), max(wire_row, zr) + 1):
                            if not wm[wr, zc] and not rm[wr, zc]:
                                return (Tool.WIRE, zc, wr)
                        return (pick_tool(), zc, zr)

    # Add nuclear power if large enough
    if obs.city_pop > 300:
        nuke_x, nuke_y = px - 8, py + 8
        if 1 <= nuke_y < WORLD_H - 1 and 1 <= nuke_x < WORLD_W - 1:
            if not np.any(pm[nuke_y - 1:nuke_y + 2, nuke_x - 1:nuke_x + 2]):
                return (Tool.NUCLEARPOWER, nuke_x, nuke_y)

    # Second cluster: build another plant+zone cluster further east
    if obs.city_pop > 200 or obs.step > 2 * obs.n_steps // 3:
        px2, py2 = 75, 50
        if not np.any(pm[py2 - 1:py2 + 2, px2 - 1:px2 + 2]):
            # Check if we need a second plant
            second_plant = False
            for pr2, pc2 in plant_cells:
                if abs(pc2 - px2) < 40:
                    second_plant = True
            if not second_plant and len(plant_cells) < 2:
                return (Tool.COALPOWER, px2, py2)

    return None

def act(obs, state):
    """
    Improved policy: horizontal layout instead of vertical spine.
    - Coal power plant on the left
    - Horizontal wire spine going right from plant
    - Road row above and below wire spine
    - Zones placed above/below roads in a grid pattern
    - Better zone balancing (RES/COM/IND mix)
    - Two power plants if needed
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    # Initialize state
    if 'phase' not in state:
        state['phase'] = 0
        state['step'] = 0
    state['step'] += 1

    # Layout constants: horizontal wire row through center
    # Plant at left side
    plant_x, plant_y = 10, 50
    wire_row = plant_y  # horizontal wire spine
    road_row_above = wire_row - 2  # road above spine
    road_row_below = wire_row + 2  # road below spine

    has_plant = np.any(pm)

    # Phase 1: Place coal power plant
    if not has_plant:
        return (Tool.COALPOWER, plant_x, plant_y)

    # Find actual plant location
    plant_positions = list(zip(*np.where(pm)))
    if plant_positions:
        plant_row, plant_col = plant_positions[0]
        plant_y_actual, plant_x_actual = plant_row, plant_col
    else:
        plant_y_actual, plant_x_actual = plant_y, plant_x

    wire_row = plant_y_actual
    road_row_above = wire_row - 2
    road_row_below = wire_row + 2

    # Current wire extents on wire_row
    wire_cols_on_row = sorted([c for (r, c) in zip(*np.where(wm)) if r == wire_row])

    # Phase 2: Extend wire horizontally from plant rightward
    start_col = plant_x_actual + 2  # start after plant footprint
    target_end_col = min(WORLD_W - 2, plant_x_actual + 60)

    if not wire_cols_on_row:
        # Place first wire adjacent to plant
        return (Tool.WIRE, plant_x_actual + 2, wire_row)

    max_wire_col = max(wire_cols_on_row) if wire_cols_on_row else start_col
    if max_wire_col < target_end_col:
        next_c = max_wire_col + 1
        if 0 <= next_c < WORLD_W:
            return (Tool.WIRE, next_c, wire_row)

    # Phase 3: Build road rows (above and below wire spine)
    # Road above
    road_above_cols = sorted([c for (r, c) in zip(*np.where(rm)) if r == road_row_above])
    road_below_cols = sorted([c for (r, c) in zip(*np.where(rm)) if r == road_row_below])

    if road_row_above >= 0:
        max_road_above = max(road_above_cols) if road_above_cols else start_col - 1
        if max_road_above < target_end_col:
            nc = max_road_above + 1
            if start_col <= nc < WORLD_W:
                return (Tool.ROAD, nc, road_row_above)

    if road_row_below < WORLD_H:
        max_road_below = max(road_below_cols) if road_below_cols else start_col - 1
        if max_road_below < target_end_col:
            nc = max_road_below + 1
            if start_col <= nc < WORLD_W:
                return (Tool.ROAD, nc, road_row_below)

    # Phase 4: Vertical connector wires from wire spine to roads
    # Connect wire at each zone column position so zones can get power
    zone_cols = list(range(start_col + 1, target_end_col, 4))
    for zc in zone_cols:
        # Wire from wire_row up to road_row_above
        for r in range(road_row_above + 1, wire_row):
            if 0 <= r < WORLD_H and 0 <= zc < WORLD_W and not wm[r, zc]:
                return (Tool.WIRE, zc, r)
        # Wire from wire_row down to road_row_below
        for r in range(wire_row + 1, road_row_below):
            if 0 <= r < WORLD_H and 0 <= zc < WORLD_W and not wm[r, zc]:
                return (Tool.WIRE, zc, r)

    # Phase 5: Place zones above and below roads
    res_pos = list(zip(*np.where(res_mask(tm))))
    com_pos = list(zip(*np.where(com_mask(tm))))
    ind_pos = list(zip(*np.where(ind_mask(tm))))
    all_zone_pos = res_pos + com_pos + ind_pos

    res_count = len(res_pos)
    com_count = len(com_pos)
    ind_count = len(ind_pos)
    total_zones = res_count + com_count + ind_count

    def zone_clear(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if pm[rr, rc]:
                    return False
        return True

    def zone_exists_near(zr, zc):
        return any(abs(zr - pr) <= 1 and abs(zc - pc) <= 1 for (pr, pc) in all_zone_pos)

    def choose_zone(idx):
        # Rotate through IND, COM, RES in 1:2:4 ratio
        t = total_zones + idx
        if ind_count * 7 < total_zones + 1:
            return Tool.INDUSTRIAL
        elif com_count * 7 < (total_zones + 1) * 2:
            return Tool.COMMERCIAL
        else:
            return Tool.RESIDENTIAL

    zone_idx = 0
    # Place zones: 3 rows above road_row_above, 3 rows below road_row_below
    above_zone_row = road_row_above - 3  # zone center 3 rows above road
    below_zone_row = road_row_below + 3  # zone center 3 rows below road

    # Extended zone rows if population growing
    extra_above = above_zone_row - 4 if obs.city_pop > 100 else None
    extra_below = below_zone_row + 4 if obs.city_pop > 100 else None

    zone_rows_to_try = [above_zone_row, below_zone_row]
    if extra_above and extra_above >= 1:
        zone_rows_to_try.append(extra_above)
    if extra_below and extra_below < WORLD_H - 1:
        zone_rows_to_try.append(extra_below)

    for zr in zone_rows_to_try:
        if not (1 <= zr < WORLD_H - 1):
            continue
        for zc in zone_cols:
            if not (1 <= zc < WORLD_W - 1):
                continue
            if not zone_exists_near(zr, zc) and zone_clear(zr, zc):
                # Check if road nearby
                road_nearby = rm[road_row_above, zc] if 0 <= road_row_above < WORLD_H else False
                road_nearby = road_nearby or (rm[road_row_below, zc] if 0 <= road_row_below < WORLD_H else False)
                # Check wire nearby
                wire_nearby = any(
                    0 <= r < WORLD_H and 0 <= c < WORLD_W and wm[r, c]
                    for r in range(max(0, zr-2), min(WORLD_H, zr+3))
                    for c in range(max(0, zc-2), min(WORLD_W, zc+3))
                )
                if road_nearby and wire_nearby:
                    return (choose_zone(zone_idx), zc, zr)
                    zone_idx += 1

    # Phase 6: Wire connections from spine to zone rows (lateral verticals)
    for zc in zone_cols:
        for r in range(max(0, above_zone_row - 1), wire_row):
            if 0 <= r < WORLD_H and not wm[r, zc] and not rm[r, zc]:
                if not pm[r, zc]:
                    return (Tool.WIRE, zc, r)
        for r in range(wire_row + 1, min(WORLD_H, below_zone_row + 2)):
            if 0 <= r < WORLD_H and not wm[r, zc] and not rm[r, zc]:
                if not pm[r, zc]:
                    return (Tool.WIRE, zc, r)

    # Phase 7: Second power plant if population large
    if obs.city_pop > 300:
        nuke_x = plant_x_actual + 40
        nuke_y = plant_y_actual
        if 1 <= nuke_y < WORLD_H - 1 and 1 <= nuke_x < WORLD_W - 1:
            if not np.any(pm[nuke_y-1:nuke_y+2, nuke_x-1:nuke_x+2]):
                return (Tool.COALPOWER, nuke_x, nuke_y)

    # Phase 8: If zones placed without road, add roads
    for zr in zone_rows_to_try:
        if not (0 <= zr < WORLD_H):
            continue
        for zc in zone_cols:
            if not (0 <= zc < WORLD_W):
                continue
            # Ensure road exists at zone boundary
            road_r = road_row_above if zr < wire_row else road_row_below
            if 0 <= road_r < WORLD_H and not rm[road_r, zc]:
                return (Tool.ROAD, zc, road_r)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy v2.
    Changes from parent:
    - Use a horizontal road/wire backbone instead of vertical spine
    - Place zones above and below the backbone
    - Power plant on left side, wire runs east along backbone row
    - Expand backbone length reactively based on city_pop
    - Add second parallel road for more zone capacity
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    # Backbone row near center
    backbone_y = 50
    plant_cx, plant_cy = 10, backbone_y

    has_plant = np.any(pm)

    # Phase 1: place coal power plant
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Current map state
    wire_positions = set(zip(*np.where(wm))) if np.any(wm) else set()
    road_positions = set(zip(*np.where(rm))) if np.any(rm) else set()
    res_pos = set(zip(*np.where(res_mask(tm))))
    com_pos = set(zip(*np.where(com_mask(tm))))
    ind_pos = set(zip(*np.where(ind_mask(tm))))
    all_zones = res_pos | com_pos | ind_pos

    res_count = len(res_pos)
    com_count = len(com_pos)
    ind_count = len(ind_pos)

    # Wire row = backbone_y - 1 (row just above backbone)
    wire_row = backbone_y - 1
    road_row = backbone_y + 1  # road runs just below backbone

    # How far east to extend based on population
    base_reach = 20
    extra_reach = min(60, obs.city_pop // 10)
    target_x = min(WORLD_W - 4, plant_cx + 3 + base_reach + extra_reach)

    # Find current wire extent on wire_row
    wire_cols_on_row = sorted(c for (r, c) in wire_positions if r == wire_row)
    road_cols_on_row = sorted(c for (r, c) in road_positions if r == road_row)

    # Phase 2: extend wire eastward along wire_row from plant
    wire_start = plant_cx + 2  # just right of plant footprint
    if not wire_cols_on_row:
        # Place first wire
        if 0 <= wire_row < WORLD_H and 0 <= wire_start < WORLD_W:
            return (Tool.WIRE, wire_start, wire_row)
    else:
        max_wc = max(wire_cols_on_row)
        if max_wc < target_x:
            nwc = max_wc + 1
            if 0 <= nwc < WORLD_W:
                return (Tool.WIRE, nwc, wire_row)

    # Phase 3: extend road eastward along road_row
    road_start = plant_cx + 2
    if not road_cols_on_row:
        if 0 <= road_row < WORLD_H and 0 <= road_start < WORLD_W:
            return (Tool.ROAD, road_start, road_row)
    else:
        max_rc = max(road_cols_on_row)
        # Road should keep pace with wire
        wire_max = max(wire_cols_on_row) if wire_cols_on_row else wire_start
        road_target = min(wire_max, target_x)
        if max_rc < road_target:
            nrc = max_rc + 1
            if 0 <= nrc < WORLD_W:
                return (Tool.ROAD, nrc, road_row)

    # Helper: check 3x3 area free
    def zone_area_free(zy, zx):
        for dy in [-1, 0, 1]:
            for dx in [-1, 0, 1]:
                rr, rc = zy + dy, zx + dx
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def zone_nearby(zy, zx):
        return any(abs(zy - pz) <= 2 and abs(zx - px) <= 2 for (pz, px) in all_zones)

    # Phase 4: place zones above wire row and below road row
    # Zone centers: above = wire_row - 2, below = road_row + 2
    zone_row_above = wire_row - 2  # center row for zones above backbone
    zone_row_below = road_row + 2  # center row for zones below backbone

    # Available x positions: where wire or road coverage exists
    covered_cols = set(c for (r, c) in wire_positions if r == wire_row) | \
                   set(c for (r, c) in road_positions if r == road_row)

    # Place zones at every 4 columns where coverage exists
    for zx in range(wire_start + 1, target_x, 4):
        wire_nearby = any(abs(zx - c) <= 2 for c in (c for (r, c) in wire_positions if r == wire_row))
        road_nearby = any(abs(zx - c) <= 2 for c in (c for (r, c) in road_positions if r == road_row))

        if not (wire_nearby and road_nearby):
            continue

        for zy in [zone_row_above, zone_row_below]:
            if 0 <= zy < WORLD_H and 0 <= zx < WORLD_W:
                if not zone_nearby(zy, zx) and zone_area_free(zy, zx):
                    # Zone type selection: ~50% res, ~25% com, ~25% ind
                    if ind_count * 4 < res_count:
                        return (Tool.INDUSTRIAL, zx, zy)
                    elif com_count * 4 < res_count:
                        return (Tool.COMMERCIAL, zx, zy)
                    else:
                        return (Tool.RESIDENTIAL, zx, zy)

    # Phase 5: add vertical wires connecting wire_row to zones above
    for (zy, zx) in all_zones:
        if zy < wire_row:
            # Need vertical wire from zone down to wire_row
            for wy in range(zy + 2, wire_row):
                if 0 <= wy < WORLD_H and 0 <= zx < WORLD_W:
                    if em[wy, zx]:
                        return (Tool.WIRE, zx, wy)

    # Phase 6: second parallel wire/road for higher population
    if obs.city_pop > 200:
        wire_row2 = backbone_y - 6
        road_row2 = backbone_y + 6

        wire_cols2 = sorted(c for (r, c) in wire_positions if r == wire_row2)
        road_cols2 = sorted(c for (r, c) in road_positions if r == road_row2)

        wire_max1 = max(wire_cols_on_row) if wire_cols_on_row else wire_start
        target2 = min(wire_max1, target_x)

        if not wire_cols2:
            # Connect to first wire row first
            # Check if first wire row exists, place connecting wire
            if wire_cols_on_row:
                first_wc = wire_cols_on_row[0]
                for wy in range(wire_row2 + 1, wire_row):
                    if 0 <= wy < WORLD_H and 0 <= first_wc < WORLD_W and em[wy, first_wc]:
                        return (Tool.WIRE, first_wc, wy)
                return (Tool.WIRE, wire_start, wire_row2)
        else:
            max_wc2 = max(wire_cols2)
            if max_wc2 < target2:
                nwc2 = max_wc2 + 1
                if 0 <= nwc2 < WORLD_W:
                    return (Tool.WIRE, nwc2, wire_row2)

        if not road_cols2:
            return (Tool.ROAD, road_start, road_row2)
        else:
            max_rc2 = max(road_cols2)
            if max_rc2 < target2:
                nrc2 = max_rc2 + 1
                if 0 <= nrc2 < WORLD_W:
                    return (Tool.ROAD, nrc2, road_row2)

        # Zones for second backbone
        zone_row_above2 = wire_row2 - 2
        zone_row_below2 = road_row2 + 2

        for zx in range(wire_start + 1, target2, 4):
            w2_nearby = any(abs(zx - c) <= 2 for (r, c) in wire_positions if r == wire_row2)
            r2_nearby = any(abs(zx - c) <= 2 for (r, c) in road_positions if r == road_row2)
            if not (w2_nearby and r2_nearby):
                continue
            for zy in [zone_row_above2, zone_row_below2]:
                if 0 <= zy < WORLD_H and 0 <= zx < WORLD_W:
                    if not zone_nearby(zy, zx) and zone_area_free(zy, zx):
                        if ind_count * 4 < res_count:
                            return (Tool.INDUSTRIAL, zx, zy)
                        elif com_count * 4 < res_count:
                            return (Tool.COMMERCIAL, zx, zy)
                        else:
                            return (Tool.RESIDENTIAL, zx, zy)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy.
    Key improvements over parent:
    - More compact zone placement (tighter grid)
    - Place zones in a grid pattern scanning from road/wire adjacency
    - Add second power plant when funds allow and pop grows
    - Better balanced zone ratio (more residential early, add com/ind as pop grows)
    - Scan actual map state each step rather than using fixed positions
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # Core layout anchors
    plant_cx, plant_cy = 55, 50
    wire_col = 59   # spine column
    road_col = 61   # road column

    left_zone_col  = 56   # 3 left of wire
    right_zone_col = 64   # 3 right of road

    has_plant = np.any(pm)

    # Phase 1: Place coal power plant
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Gather current map state
    wire_yx = set(zip(*np.where(wm))) if np.any(wm) else set()
    road_yx = set(zip(*np.where(rm))) if np.any(rm) else set()
    res_yx  = set(zip(*np.where(res_m))) if np.any(res_m) else set()
    com_yx  = set(zip(*np.where(com_m))) if np.any(com_m) else set()
    ind_yx  = set(zip(*np.where(ind_m))) if np.any(ind_m) else set()
    all_zones = res_yx | com_yx | ind_yx

    res_count = len(res_yx)
    com_count = len(com_yx)
    ind_count = len(ind_yx)

    # Dynamic vertical span based on population
    base_span = 12
    extra_span = min(30, obs.city_pop // 30)
    target_span = base_span + extra_span
    tmin = max(2, plant_cy - target_span)
    tmax = min(WORLD_H - 3, plant_cy + target_span)

    # Current wire spine extent
    wire_rows_in_col = sorted(r for (r, c) in wire_yx if c == wire_col)
    road_rows_in_col = sorted(r for (r, c) in road_yx if c == road_col)
    road_rows_set = set(road_rows_in_col)

    # Helper: check if 3x3 area around center is completely empty
    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def zone_nearby(zr, zc, zones, dist=2):
        return any(abs(zr - pr) <= dist and abs(zc - pc) <= dist for (pr, pc) in zones)

    # Phase 2: Extend wire spine vertically
    if not wire_rows_in_col:
        # Place first wire adjacent to plant (right side of plant)
        for try_r in [plant_cy, plant_cy - 1, plant_cy + 1]:
            if 0 <= try_r < WORLD_H and em[try_r, wire_col]:
                return (Tool.WIRE, wire_col, try_r)
    else:
        min_wr = min(wire_rows_in_col)
        max_wr = max(wire_rows_in_col)

        # Extend downward first
        if max_wr < tmax:
            nr = max_wr + 1
            if 0 < nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if min_wr > tmin:
            nr = min_wr - 1
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    if not wire_rows_in_col:
        return None

    wire_rows_set = set(wire_rows_in_col)

    # Phase 3: Build road column matching wire spine
    for wr in sorted(wire_rows_in_col):
        if wr not in road_rows_set and 0 <= road_col < WORLD_W:
            if em[wr, road_col]:
                return (Tool.ROAD, road_col, wr)

    # Choose zone type based on current counts and population
    def pick_zone():
        pop = obs.city_pop
        if res_count == 0:
            return Tool.RESIDENTIAL
        # Target ratio: res:com:ind ~ 3:1:1 early, 2:1:1 later
        if pop < 300:
            if ind_count * 3 < res_count:
                return Tool.INDUSTRIAL
            if com_count * 3 < res_count:
                return Tool.COMMERCIAL
        else:
            if ind_count * 2 < res_count:
                return Tool.INDUSTRIAL
            if com_count * 2 < res_count:
                return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Phase 4: Place zones adjacent to road/wire - scan vertically
    # Prioritize rows where both wire and road exist
    for zr in sorted(wire_rows_in_col):
        # Road must be close for zone to get road access
        road_close = zr in road_rows_set or any(abs(zr - rr) <= 1 for rr in road_rows_set)
        if not road_close:
            continue

        for zc in [left_zone_col, right_zone_col]:
            if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                if not zone_nearby(zr, zc, all_zones, dist=1) and zone_area_free(zr, zc):
                    zt = pick_zone()
                    return (zt, zc, zr)

    # Phase 5: Lateral wires from spine to left zones (power them)
    for wr in sorted(wire_rows_in_col):
        # Check if left zone at this row needs wire connection
        for wc in range(wire_col - 1, max(left_zone_col - 2, 0), -1):
            if 0 <= wc < WORLD_W and em[wr, wc]:
                return (Tool.WIRE, wc, wr)
            elif wm[wr, wc]:
                break  # already wired up to here

    # Phase 6: Lateral roads from road col to right zones
    for wr in sorted(wire_rows_in_col):
        for rc in range(road_col + 1, min(right_zone_col + 2, WORLD_W)):
            if 0 <= rc < WORLD_W and em[wr, rc]:
                return (Tool.ROAD, rc, wr)
            elif rm[wr, rc]:
                break  # already roaded

    # Phase 7: Second cluster to the right when pop >= 150
    if obs.city_pop >= 150:
        wire_col2 = road_col + 9   # col 70
        road_col2 = wire_col2 + 2  # col 72
        left_zone_col2 = wire_col2 - 3   # col 67
        right_zone_col2 = road_col2 + 3  # col 75

        wire_rows2 = sorted(r for (r, c) in wire_yx if c == wire_col2)
        road_rows2 = set(r for (r, c) in road_yx if c == road_col2)

        if not wire_rows2:
            # Build horizontal bridge from main spine at plant_cy
            for wc in range(wire_col + 1, wire_col2 + 1):
                if em[plant_cy, wc]:
                    return (Tool.WIRE, wc, plant_cy)
                elif not wm[plant_cy, wc]:
                    break  # hit something non-wire
        else:
            min_wr2 = min(wire_rows2)
            max_wr2 = max(wire_rows2)
            if max_wr2 < tmax:
                nr = max_wr2 + 1
                if 0 < nr < WORLD_H and em[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > tmin:
                nr = min_wr2 - 1
                if 0 <= nr < WORLD_H and em[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)

            for wr in sorted(wire_rows2):
                if wr not in road_rows2:
                    if em[wr, road_col2]:
                        return (Tool.ROAD, road_col2, wr)

            for zr in sorted(wire_rows2):
                road_close2 = zr in road_rows2 or any(abs(zr - rr) <= 1 for rr in road_rows2)
                if not road_close2:
                    continue
                for zc in [left_zone_col2, right_zone_col2]:
                    if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                        if not zone_nearby(zr, zc, all_zones, dist=1) and zone_area_free(zr, zc):
                            return (pick_zone(), zc, zr)

            for wr in sorted(wire_rows2):
                for wc in range(wire_col2 - 1, max(left_zone_col2 - 2, 0), -1):
                    if 0 <= wc < WORLD_W and em[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    elif wm[wr, wc]:
                        break

            for wr in sorted(wire_rows2):
                for rc in range(road_col2 + 1, min(right_zone_col2 + 2, WORLD_W)):
                    if 0 <= rc < WORLD_W and em[wr, rc]:
                        return (Tool.ROAD, rc, wr)
                    elif rm[wr, rc]:
                        break

    # Phase 8: Third cluster to the left when pop >= 350
    if obs.city_pop >= 350:
        wire_col3 = wire_col - 9   # col 50
        road_col3 = wire_col3 - 2  # col 48
        left_zone_col3 = road_col3 - 3  # col 45
        right_zone_col3 = wire_col3 + 3  # col 53

        wire_rows3 = sorted(r for (r, c) in wire_yx if c == wire_col3)
        road_rows3 = set(r for (r, c) in road_yx if c == road_col3)

        if not wire_rows3:
            for wc in range(wire_col - 1, wire_col3 - 1, -1):
                if em[plant_cy, wc]:
                    return (Tool.WIRE, wc, plant_cy)
                elif not wm[plant_cy, wc]:
                    break
        else:
            min_wr3 = min(wire_rows3)
            max_wr3 = max(wire_rows3)
            if max_wr3 < tmax:
                nr = max_wr3 + 1
                if 0 < nr < WORLD_H and em[nr, wire_col3]:
                    return (Tool.WIRE, wire_col3, nr)
            if min_wr3 > tmin:
                nr = min_wr3 - 1
                if 0 <= nr < WORLD_H and em[nr, wire_col3]:
                    return (Tool.WIRE, wire_col3, nr)

            for wr in sorted(wire_rows3):
                if wr not in road_rows3:
                    if em[wr, road_col3]:
                        return (Tool.ROAD, road_col3, wr)

            for zr in sorted(wire_rows3):
                road_close3 = zr in road_rows3 or any(abs(zr - rr) <= 1 for rr in road_rows3)
                if not road_close3:
                    continue
                for zc in [left_zone_col3, right_zone_col3]:
                    if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                        if not zone_nearby(zr, zc, all_zones, dist=1) and zone_area_free(zr, zc):
                            return (pick_zone(), zc, zr)

            for wr in sorted(wire_rows3):
                for wc in range(wire_col3 - 1, max(left_zone_col3 - 2, 0), -1):
                    if 0 <= wc < WORLD_W and em[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    elif wm[wr, wc]:
                        break

            for wr in sorted(wire_rows3):
                for rc in range(road_col3 + 1, min(right_zone_col3 + 2, WORLD_W)):
                    if 0 <= rc < WORLD_W and em[wr, rc]:
                        return (Tool.ROAD, rc, wr)
                    elif rm[wr, rc]:
                        break

    # Phase 9: Add second coal plant if powered zones are low relative to zone count
    if obs.city_pop >= 500 and len(all_zones) > 0:
        powered_ratio = obs.powered_zones / max(len(all_zones), 1)
        if powered_ratio < 0.7:
            # Place second plant further right
            plant2_cx, plant2_cy = 75, 50
            plant2_area_clear = all(
                em[plant2_cy + dr, plant2_cx + dc]
                for dr in [-1, 0, 1] for dc in [-1, 0, 1]
                if 0 <= plant2_cy + dr < WORLD_H and 0 <= plant2_cx + dc < WORLD_W
            )
            if plant2_area_clear:
                return (Tool.COALPOWER, plant2_cx, plant2_cy)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder.
    Reads tile_map every step; uses state only for light phase tracking.
    Strategy:
    - One coal power plant at anchor, then extend wires outward
    - Build road grid adjacent to wires
    - Place balanced zones (res/com/ind) near roads + power
    - Adapt all decisions to current map state
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def adj_to(mask, x, y, r=1):
        for dy in range(-r, r+1):
            for dx in range(-r, r+1):
                if dx == 0 and dy == 0:
                    continue
                nx, ny = x+dx, y+dy
                if in_bounds(nx, ny) and mask[ny, nx]:
                    return True
        return False

    # Two cluster anchors
    ANCHORS = [(35, 50), (80, 50)]

    # --- Phase 1: Ensure power plants exist ---
    for (cx, cy) in ANCHORS:
        has_plant = False
        plant_ys, plant_xs = np.where(pm)
        for py, px in zip(plant_ys.tolist(), plant_xs.tolist()):
            if abs(px - cx) < 6 and abs(py - cy) < 6:
                has_plant = True
                break
        if not has_plant:
            # Place plant at anchor (adjust slightly to avoid edge)
            px_place = max(2, min(WORLD_W-3, cx - 6))
            py_place = max(2, min(WORLD_H-3, cy - 6))
            return (Tool.COALPOWER, px_place, py_place)

    # --- Phase 2: Extend wires from power sources ---
    # Wire plan: from each plant, extend a cross pattern to serve the cluster
    # Find all power-adjacent empty tiles and extend wire toward planned positions

    power_mask = pm | wm

    # Wire targets: vertical spine + horizontal arms for each cluster
    wire_targets = []
    for (cx, cy) in ANCHORS:
        # Vertical spine at cx
        for dy in range(-10, 11):
            wire_targets.append((cx, cy + dy))
        # Horizontal arm at cy
        for dx in range(-10, 11):
            wire_targets.append((cx + dx, cy))
        # Second horizontal at cy-3 and cy+3
        for dx in range(-10, 11):
            wire_targets.append((cx + dx, cy - 3))
            wire_targets.append((cx + dx, cy + 3))
    # Connect clusters horizontally with wire at mid-y
    mid_y = 50
    for x in range(ANCHORS[0][0], ANCHORS[1][0]+1):
        wire_targets.append((x, mid_y - 1))

    # Place next wire that is adjacent to existing power and not already wired
    for (wx, wy) in wire_targets:
        if not in_bounds(wx, wy):
            continue
        if bool(wm[wy, wx]) or bool(pm[wy, wx]):
            continue
        if not bool(em[wy, wx]):
            continue
        # Must be adjacent to existing power
        if adj_to(power_mask, wx, wy, 1):
            return (Tool.WIRE, wx, wy)

    # --- Phase 3: Extend roads from existing roads or near plants ---
    # Road plan: flanking roads parallel to wire spines
    road_targets = []
    for (cx, cy) in ANCHORS:
        # Vertical roads flanking the spine
        for dy in range(-10, 11):
            road_targets.append((cx + 2, cy + dy))
            road_targets.append((cx - 2, cy + dy))
        # Horizontal roads
        for offset in [-6, -3, 0, 3, 6]:
            for dx in range(-10, 11):
                road_targets.append((cx + dx, cy + offset))
    # Connecting highway between clusters
    for x in range(ANCHORS[0][0]+3, ANCHORS[1][0]-2):
        road_targets.append((x, mid_y + 3))
        road_targets.append((x, mid_y - 3))

    for (rx, ry) in road_targets:
        if not in_bounds(rx, ry):
            continue
        if bool(rm[ry, rx]):
            continue
        if bool(pm[ry, rx]) or bool(wm[ry, rx]):
            continue
        if not bool(em[ry, rx]):
            continue
        # Must be adjacent to existing road or plant
        if adj_to(rm, rx, ry, 1) or adj_to(pm, rx, ry, 2):
            return (Tool.ROAD, rx, ry)

    # --- Phase 4: Place zones near roads AND near power ---
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        # Target: ~50% res, 25% com, 25% ind
        if com_count / total_zones < 0.22:
            return Tool.COMMERCIAL
        if ind_count / total_zones < 0.22:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Build neighborhood masks: tiles within range of road and power
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H+dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W+dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H+dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W+dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_existing = resm | comm | indm
    # Candidate: empty, near road, near power, not edge
    cand = em & nbr_road & nbr_power
    cand[0:3, :] = False
    cand[WORLD_H-3:, :] = False
    cand[:, 0:3] = False
    cand[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        key = int(obs.step * 17 + int(obs.city_pop * 3) + 1) % len(cxs)
        for offset in range(min(len(cxs), 120)):
            k = (key + offset * 11) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            # Check 3x3 clearance
            ok = True
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    ny2, nx2 = zy+dr, zx+dc
                    if not in_bounds(nx2, ny2):
                        ok = False; break
                    if not (bool(em[ny2, nx2]) or bool(zone_existing[ny2, nx2])):
                        ok = False; break
                if not ok:
                    break
            if ok:
                return (pick_tool(), zx, zy)

    # --- Phase 5: Services when population warrants ---
    if obs.city_pop > 150:
        for fx, fy in [(ANCHORS[0][0]+5, ANCHORS[0][1]-8),
                       (ANCHORS[1][0]-5, ANCHORS[1][1]+8)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 300:
        for fx, fy in [(ANCHORS[0][0]-5, ANCHORS[0][1]+8),
                       (ANCHORS[1][0]+5, ANCHORS[1][1]-8)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.POLICESTATION, fx, fy)

    # --- Fallback: extend road from any existing road tile ---
    rys, rxs = np.where(rm)
    if len(rxs) > 0:
        k2 = int(obs.step * 13 + 7) % len(rxs)
        rx2, ry2 = int(rxs[k2]), int(rys[k2])
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx2, ny2 = rx2+ddx, ry2+ddy
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # --- Fallback: extend wire from any existing wire tile ---
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        k3 = int(obs.step * 7 + 3) % len(wxs_arr)
        wx2, wy2 = int(wxs_arr[k3]), int(wys_arr[k3])
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx2, ny2 = wx2+ddx, wy2+ddy
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder.
    Each step reads the current map and decides what to place next
    based on what already exists. Uses state only as a phase hint.

    Strategy:
    - Place coal plant near left-center
    - Grow wire spine vertically from plant
    - Grow horizontal road spine east from plant
    - Place zones adjacent to existing road+wire coverage
    - Add second plant when needed
    - All decisions based on current map observation
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        if com_count / t < 0.28:
            return Tool.COMMERCIAL
        if ind_count / t < 0.18:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # ---- Phase 1: Ensure power plant exists ----
    plant_x, plant_y = 12, cy
    if not np.any(pm):
        return (Tool.COALPOWER, plant_x, plant_y)

    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Key layout rows/cols derived from plant position
    road_row = max(3, min(WORLD_H - 4, plant_cy + 1))
    wire_col = max(3, min(WORLD_W - 4, plant_cx + 2))

    # Extent based on population
    if obs.city_pop < 50:
        road_extent = 18
        vert_extent = 8
    elif obs.city_pop < 200:
        road_extent = 28
        vert_extent = 12
    elif obs.city_pop < 500:
        road_extent = 40
        vert_extent = 18
    else:
        road_extent = 55
        vert_extent = 25

    road_start = max(1, plant_cx + 1)
    road_end = min(WORLD_W - 2, plant_cx + road_extent)
    wire_top = max(1, road_row - vert_extent)
    wire_bot = min(WORLD_H - 2, road_row + vert_extent)

    # ---- Phase 2: Grow vertical wire spine from plant outward ----
    # Check current wire extent on wire_col
    wire_rows_on_col = [r for r in range(WORLD_H) if wm[r, wire_col]]
    if wire_rows_on_col:
        cur_wire_top = min(wire_rows_on_col)
        cur_wire_bot = max(wire_rows_on_col)
    else:
        # Seed wire adjacent to plant
        seed_r = plant_cy - 1
        if 0 <= seed_r < WORLD_H and em[seed_r, wire_col] and not pm[seed_r, wire_col]:
            return (Tool.WIRE, wire_col, seed_r)
        seed_r = plant_cy + 1
        if 0 <= seed_r < WORLD_H and em[seed_r, wire_col] and not pm[seed_r, wire_col]:
            return (Tool.WIRE, wire_col, seed_r)
        return (Tool.WIRE, wire_col, road_row)

    # Extend wire upward if needed
    if cur_wire_top > wire_top:
        nr = cur_wire_top - 1
        if 0 <= nr < WORLD_H and em[nr, wire_col] and not pm[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)

    # Extend wire downward if needed
    if cur_wire_bot < wire_bot:
        nr = cur_wire_bot + 1
        if 0 <= nr < WORLD_H and em[nr, wire_col] and not pm[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)

    # ---- Phase 3: Grow horizontal road spine east from plant ----
    # Find current road extent on road_row
    road_cols_on_row = [c for c in range(WORLD_W) if rm[road_row, c]]
    if road_cols_on_row:
        cur_road_end = max(road_cols_on_row)
        cur_road_start = min(road_cols_on_row)
    else:
        # Seed road at start
        if em[road_row, road_start] and not pm[road_row, road_start]:
            return (Tool.ROAD, road_start, road_row)
        cur_road_end = road_start - 1
        cur_road_start = road_start

    # Extend road eastward
    if cur_road_end < road_end:
        nc = cur_road_end + 1
        if 0 <= nc < WORLD_W and em[road_row, nc] and not pm[road_row, nc]:
            return (Tool.ROAD, nc, road_row)

    # Extend road westward if needed
    if cur_road_start > road_start:
        nc = cur_road_start - 1
        if 0 <= nc < WORLD_W and em[road_row, nc] and not pm[road_row, nc]:
            return (Tool.ROAD, nc, road_row)

    # ---- Phase 4: Horizontal wire just above road spine ----
    w_row_above = road_row - 1
    if w_row_above >= 1:
        wire_cols_above = [c for c in range(WORLD_W) if wm[w_row_above, c]]
        if wire_cols_above:
            cur_wa_end = max(wire_cols_above)
            cur_wa_start = min(wire_cols_above)
        else:
            cur_wa_end = wire_col - 1
            cur_wa_start = wire_col + 1

        # Grow eastward
        if cur_wa_end < road_end:
            nc = cur_wa_end + 1
            if 0 <= nc < WORLD_W and em[w_row_above, nc] and not pm[w_row_above, nc]:
                return (Tool.WIRE, nc, w_row_above)
        # Grow westward to wire_col
        if cur_wa_start > max(wire_col, road_start):
            nc = cur_wa_start - 1
            if 0 <= nc < WORLD_W and em[w_row_above, nc] and not pm[w_row_above, nc]:
                return (Tool.WIRE, nc, w_row_above)

    # Horizontal wire just below road spine
    w_row_below = road_row + 1
    if w_row_below < WORLD_H - 1:
        wire_cols_below = [c for c in range(WORLD_W) if wm[w_row_below, c]]
        if wire_cols_below:
            cur_wb_end = max(wire_cols_below)
            cur_wb_start = min(wire_cols_below)
        else:
            cur_wb_end = wire_col - 1
            cur_wb_start = wire_col + 1

        if cur_wb_end < road_end:
            nc = cur_wb_end + 1
            if 0 <= nc < WORLD_W and em[w_row_below, nc] and not pm[w_row_below, nc]:
                return (Tool.WIRE, nc, w_row_below)
        if cur_wb_start > max(wire_col, road_start):
            nc = cur_wb_start - 1
            if 0 <= nc < WORLD_W and em[w_row_below, nc] and not pm[w_row_below, nc]:
                return (Tool.WIRE, nc, w_row_below)

    # ---- Helpers ----
    all_zone_mask = resm | comm | indm

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_present(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=4):
        r0, r1 = max(0, zr - radius), min(WORLD_H, zr + radius + 1)
        c0, c1 = max(0, zc - radius), min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=3):
        r0, r1 = max(0, zr - radius), min(WORLD_H, zr + radius + 1)
        c0, c1 = max(0, zc - radius), min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    # ---- Phase 5: Place zones reactively ----
    # Zone centers: 2 rows above road (above wire), 2 rows below road (below wire)
    zone_row_above = road_row - 2
    zone_row_below = road_row + 2

    # Zone columns: wherever road and wire already exist
    # Use actual road extent observed
    if road_cols_on_row:
        obs_road_end = max(road_cols_on_row)
        zone_cols = list(range(max(road_start + 2, wire_col + 2), obs_road_end - 1, 4))
    else:
        zone_cols = []

    for zc in zone_cols:
        if zc < 2 or zc > WORLD_W - 3:
            continue
        for zr in [zone_row_above, zone_row_below]:
            if zr < 2 or zr > WORLD_H - 3:
                continue
            if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                if has_road_nearby(zr, zc, 3) and has_wire_nearby(zr, zc, 4):
                    return (pick_tool(), zc, zr)

    # ---- Phase 6: Vertical roads to connect zones to spine ----
    for zc in (zone_cols[::2] if zone_cols else []):
        if zc < 2 or zc > WORLD_W - 3:
            continue
        # From road_row toward zone_row_above
        for r in range(road_row - 1, max(1, zone_row_above - 1), -1):
            if not rm[r, zc] and em[r, zc] and not pm[r, zc]:
                # Only extend if connected below
                if rm[r + 1, zc] or rm[road_row, zc]:
                    return (Tool.ROAD, zc, r)
                break
        # From road_row toward zone_row_below
        for r in range(road_row + 1, min(WORLD_H - 1, zone_row_below + 2)):
            if not rm[r, zc] and em[r, zc] and not pm[r, zc]:
                if rm[r - 1, zc] or rm[road_row, zc]:
                    return (Tool.ROAD, zc, r)
                break

    # ---- Phase 7: Outer zone rows for growth ----
    if obs.city_pop > 200:
        zone_row_above2 = road_row - 5
        zone_row_below2 = road_row + 5
        for zc in zone_cols:
            if zc < 2 or zc > WORLD_W - 3:
                continue
            for zr in [zone_row_above2, zone_row_below2]:
                if zr < 2 or zr > WORLD_H - 3:
                    continue
                if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                    if has_road_nearby(zr, zc, 5) and has_wire_nearby(zr, zc, 6):
                        return (pick_tool(), zc, zr)

    # ---- Phase 8: Second power plant ----
    if obs.city_pop > 250 and int(np.sum(pm)) < 9:
        # Place it near the far end of road
        if road_cols_on_row:
            px2 = min(WORLD_W - 4, max(road_cols_on_row) + 4)
        else:
            px2 = plant_cx + 30
        py2 = road_row
        px2 = max(3, min(WORLD_W - 4, px2))
        py2 = max(3, min(WORLD_H - 4, py2))
        if em[py2, px2]:
            return (Tool.COALPOWER, px2, py2)
        for dy in range(-3, 4):
            py3 = py2 + dy
            if 3 <= py3 <= WORLD_H - 4 and em[py3, px2]:
                return (Tool.COALPOWER, px2, py3)

    # ---- Phase 9: Wire to connect second plant ----
    plant_count = int(np.sum(pm))
    if plant_count >= 18:
        plant_tiles = np.where(pm)
        right_c = int(np.max(plant_tiles[1]))
        right_r = int(np.median(plant_tiles[0][plant_tiles[1] >= right_c - 1]))
        # Wire leftward from right plant toward wire_col
        for c in range(right_c - 1, wire_col, -1):
            if 0 < c < WORLD_W and not wm[right_r, c] and not pm[right_r, c]:
                if em[right_r, c]:
                    return (Tool.WIRE, c, int(right_r))
                else:
                    break

    # ---- Phase 10: Services ----
    if obs.city_pop > 300:
        ps_x = int(np.clip(cx, 3, WORLD_W - 4))
        ps_y = int(np.clip(road_row - 8, 3, WORLD_H - 4))
        if em[ps_y, ps_x] and has_road_nearby(ps_y, ps_x, 5):
            return (Tool.POLICESTATION, ps_x, ps_y)

    if obs.city_pop > 400:
        fs_x = int(np.clip(cx + 10, 3, WORLD_W - 4))
        fs_y = int(np.clip(road_row + 8, 3, WORLD_H - 4))
        if em[fs_y, fs_x] and has_road_nearby(fs_y, fs_x, 5):
            return (Tool.FIRESTATION, fs_x, fs_y)

    # ---- Phase 11: More wires upward from spine to reach outer zones ----
    if obs.city_pop > 150:
        zone_row_above2 = road_row - 5
        if zone_row_above2 >= 2:
            wire_rows_at_above = [c for c in range(WORLD_W) if wm[zone_row_above2 - 1, c] or wm[zone_row_above2, c]]
            for zc in zone_cols:
                if zc < 2 or zc > WORLD_W - 3:
                    continue
                # Wire upward from w_row_above toward outer zone
                for r in range(w_row_above - 1, zone_row_above2 - 1, -1):
                    if 0 <= r < WORLD_H and not wm[r, zc] and em[r, zc] and not pm[r, zc]:
                        if wm[r + 1, zc]:
                            return (Tool.WIRE, zc, r)
                        break

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Place coal power plant if none exists
    - Grow wire frontier from existing wire/plant
    - Grow road frontier from existing roads
    - Place zones adjacent to both wire and road coverage
    - Add second plant and services based on current city state
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Fixed anchor
    CX, CY = 28, 50

    # --- Phase 1: Place first coal power plant ---
    if not np.any(pm):
        return (Tool.COALPOWER, CX, CY)

    plant_ys, plant_xs = np.where(pm)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        if com_count / t < 0.22:
            return Tool.COMMERCIAL
        if ind_count / t < 0.22:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # --- Phase 2: Grow wire frontier reactively ---
    # Target: wire spine along py row, extending right from plant
    # Find current wire extent
    wire_count = int(np.sum(wm))

    # Determine target wire end based on population
    if obs.city_pop < 200:
        target_wire_end = min(px + 45, WORLD_W - 4)
    elif obs.city_pop < 600:
        target_wire_end = min(px + 75, WORLD_W - 4)
    else:
        target_wire_end = min(px + 95, WORLD_W - 4)

    wire_start_x = px + 3

    # Find rightmost wire on spine row
    spine_y = py
    spine_wire_cols = [c for c in range(WORLD_W) if wm[spine_y, c]]

    if not spine_wire_cols:
        # No wire on spine yet, place first wire adjacent to plant
        wx = px + 3
        if in_bounds(wx, spine_y) and em[spine_y, wx]:
            return (Tool.WIRE, wx, spine_y)
        # Try adjacent rows
        for dy in [-1, 1]:
            wy = spine_y + dy
            if in_bounds(wx, wy) and em[wy, wx]:
                return (Tool.WIRE, wx, wy)
    else:
        max_wire_x = max(spine_wire_cols)
        min_wire_x = min(spine_wire_cols)

        # Extend wire rightward along spine
        if max_wire_x < target_wire_end:
            nx = max_wire_x + 1
            if in_bounds(nx, spine_y) and em[spine_y, nx] and not pm[spine_y, nx]:
                return (Tool.WIRE, nx, spine_y)

    # --- Phase 3: Add vertical wire branches from spine ---
    # Every 6 cols, branch up and down 3 tiles
    branch_cols = list(range(wire_start_x + 3, target_wire_end + 1, 6))
    for bx in branch_cols:
        if not in_bounds(bx, spine_y):
            continue
        if not (bool(wm[spine_y, bx]) or bool(pm[spine_y, bx])):
            continue  # spine not wired here yet
        for sign in [-1, 1]:
            for dy in range(1, 4):
                wy = spine_y + sign * dy
                if not in_bounds(bx, wy):
                    break
                if bool(wm[wy, bx]) or bool(pm[wy, bx]):
                    continue
                if bool(em[wy, bx]):
                    return (Tool.WIRE, bx, wy)
                break  # blocked

    # --- Phase 4: Build road rows parallel to wire spine ---
    road_top = spine_y - 2
    road_bot = spine_y + 2

    # Find current road extent reactively
    road_top_cols = [c for c in range(WORLD_W) if 0 <= road_top < WORLD_H and rm[road_top, c]]
    road_bot_cols = [c for c in range(WORLD_W) if 0 <= road_bot < WORLD_H and rm[road_bot, c]]

    road_start = wire_start_x
    road_end = target_wire_end

    # Build top road
    if 0 <= road_top < WORLD_H:
        if not road_top_cols:
            rx = road_start
            if in_bounds(rx, road_top) and em[road_top, rx] and not wm[road_top, rx]:
                return (Tool.ROAD, rx, road_top)
        else:
            max_top = max(road_top_cols)
            if max_top < road_end:
                nx = max_top + 1
                if in_bounds(nx, road_top) and em[road_top, nx] and not wm[road_top, nx] and not pm[road_top, nx]:
                    return (Tool.ROAD, nx, road_top)

    # Build bottom road
    if 0 <= road_bot < WORLD_H:
        if not road_bot_cols:
            rx = road_start
            if in_bounds(rx, road_bot) and em[road_bot, rx] and not wm[road_bot, rx]:
                return (Tool.ROAD, rx, road_bot)
        else:
            max_bot = max(road_bot_cols)
            if max_bot < road_end:
                nx = max_bot + 1
                if in_bounds(nx, road_bot) and em[road_bot, nx] and not wm[road_bot, nx] and not pm[road_bot, nx]:
                    return (Tool.ROAD, nx, road_bot)

    # --- Phase 5: Vertical connector roads every 6 cols ---
    for vc in range(road_start, road_end + 1, 6):
        for vr in range(road_top, road_bot + 1):
            if not in_bounds(vc, vr):
                continue
            if not bool(rm[vr, vc]) and not bool(pm[vr, vc]) and not bool(wm[vr, vc]) and bool(em[vr, vc]):
                # Only if connected to existing road
                connected = False
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr2, nc2 = vr+dr, vc+dc
                    if in_bounds(nc2, nr2) and bool(rm[nr2, nc2]):
                        connected = True
                        break
                if connected:
                    return (Tool.ROAD, vc, vr)

    # --- Phase 6: Place zones reactively ---
    # Build neighborhood masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    all_zone = resm | comm | indm
    zone_set = set()
    for arr in [resm, comm, indm]:
        ys2, xs2 = np.where(arr)
        for y2, x2 in zip(ys2.tolist(), xs2.tolist()):
            zone_set.add((int(y2), int(x2)))

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Use step-based hash for variety, but scan multiple candidates
        step_hash = int(obs.step * 17 + int(obs.city_pop * 3)) % max(len(cxs_arr), 1)
        for offset in range(min(len(cxs_arr), 80)):
            k = (step_hash + offset * 11) % len(cxs_arr)
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # --- Phase 7: Second coal plant when needed ---
    if total_zones > 10 or obs.city_pop > 200:
        p2x = min(px + 55, WORLD_W - 5)
        p2y = py
        nearby_plant = False
        for dy in range(-7, 8):
            for dx in range(-7, 8):
                ny2, nx2 = p2y + dy, p2x + dx
                if in_bounds(nx2, ny2) and bool(pm[ny2, nx2]):
                    nearby_plant = True
        if not nearby_plant and in_bounds(p2x, p2y) and bool(em[p2y, p2x]):
            return (Tool.COALPOWER, p2x, p2y)

    # --- Phase 8: Services ---
    if obs.city_pop > 200:
        fx, fy = px + 6, py - 8
        if in_bounds(fx, fy) and bool(em[fy, fx]):
            return (Tool.FIRESTATION, fx, fy)
        fx2, fy2 = px + 6, py + 8
        if in_bounds(fx2, fy2) and bool(em[fy2, fx2]):
            return (Tool.POLICESTATION, fx2, fy2)

    # --- Phase 9: Extend wire from any existing wire frontier ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 7) % max(len(wire_xs_arr), 1)
        # Prefer extending rightward
        candidates = list(zip(wire_xs_arr.tolist(), wire_ys_arr.tolist()))
        candidates.sort(key=lambda t: -t[0])  # rightmost first
        for wx_s, wy_s in candidates[:10]:
            for dx2, dy2 in [(1, 0), (0, -1), (0, 1), (-1, 0)]:
                nx2, ny2 = wx_s + dx2, wy_s + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # --- Phase 10: Extend roads from frontier ---
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        candidates_r = list(zip(road_xs_arr.tolist(), road_ys_arr.tolist()))
        candidates_r.sort(key=lambda t: -t[0])
        for rx_s, ry_s in candidates_r[:10]:
            for dx2, dy2 in [(1, 0), (0, -1), (0, 1), (-1, 0)]:
                nx2, ny2 = rx_s + dx2, ry_s + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and not bool(wm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map each step to decide next action
    - Places power plant, extends wire/road from existing tiles, places zones near roads
    - Two corridors, expands based on observed population
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def zone_area_free(zy, zx):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zy + dr, zx + dc
                if not in_bounds(rc, rr):
                    return False
                if not bool(em[rr, rc]):
                    return False
        return True

    # Power plant anchor positions
    P1X, P1Y = 55, 50
    P2X, P2Y = 80, 50

    # Detect existing plants
    plant_ys, plant_xs = np.where(pm)
    has_p1 = any(abs(px - P1X) <= 5 and abs(py - P1Y) <= 5
                 for py, px in zip(plant_ys.tolist(), plant_xs.tolist()))
    has_p2 = any(abs(px - P2X) <= 5 and abs(py - P2Y) <= 5
                 for py, px in zip(plant_ys.tolist(), plant_xs.tolist()))

    # Step 1: Place primary plant
    if not has_p1:
        return (Tool.COALPOWER, P1X, P1Y)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))

    def pick_zone(zy):
        if ind_count == 0:
            return Tool.INDUSTRIAL
        if com_count == 0:
            return Tool.COMMERCIAL
        total = res_count + com_count + ind_count
        if total == 0:
            return Tool.RESIDENTIAL
        if ind_count / total < 0.25:
            return Tool.INDUSTRIAL
        if com_count / total < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def corridor_action(wire_col, plant_y, cy_ref):
        """Reactively build one corridor: wire spine, bilateral roads, zones."""
        road_L = wire_col - 1
        road_R = wire_col + 1
        zone_cols_L = [wire_col - 4, wire_col - 7]
        zone_cols_R = [wire_col + 4, wire_col + 7]

        # Span grows with pop
        extra = min(35, obs.city_pop // 15)
        tmin = max(2, cy_ref - 15 - extra)
        tmax = min(WORLD_H - 3, cy_ref + 15 + extra)

        # Current wire rows in this column
        wire_rows = sorted(int(r) for r in np.where(wm[:, wire_col])[0])
        road_rows_L = set(int(r) for r in np.where(rm[:, road_L])[0]) if in_bounds(road_L, 0) else set()
        road_rows_R = set(int(r) for r in np.where(rm[:, road_R])[0]) if in_bounds(road_R, 0) else set()

        # Seed wire from plant if none
        if not wire_rows:
            # Place wire adjacent to plant
            for dy in range(2, 6):
                ny = plant_y + dy
                if in_bounds(wire_col, ny) and bool(em[ny, wire_col]):
                    return (Tool.WIRE, wire_col, ny)
            for dy in range(2, 6):
                ny = plant_y - dy
                if in_bounds(wire_col, ny) and bool(em[ny, wire_col]):
                    return (Tool.WIRE, wire_col, ny)
            return None

        min_wr = min(wire_rows)
        max_wr = max(wire_rows)

        # Extend wire downward
        if max_wr < tmax:
            nr = max_wr + 1
            if in_bounds(wire_col, nr) and bool(em[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
            elif in_bounds(wire_col, nr) and bool(wm[nr, wire_col]):
                pass  # already wire, skip

        # Extend wire upward
        if min_wr > tmin:
            nr = min_wr - 1
            if in_bounds(wire_col, nr) and bool(em[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

        wire_set = set(wire_rows)

        # Build road L and R for each wire row
        for wr in wire_rows:
            if wr not in road_rows_L and in_bounds(road_L, wr) and bool(em[wr, road_L]):
                return (Tool.ROAD, road_L, wr)
            if wr not in road_rows_R and in_bounds(road_R, wr) and bool(em[wr, road_R]):
                return (Tool.ROAD, road_R, wr)

        # Place zones next to roads
        for wr in wire_rows:
            if wr < 2 or wr >= WORLD_H - 2:
                continue
            road_L_here = wr in road_rows_L
            road_R_here = wr in road_rows_R

            if road_L_here:
                for zc in zone_cols_L:
                    if in_bounds(zc, wr) and 2 <= zc < WORLD_W - 2:
                        if zone_area_free(wr, zc):
                            return (pick_zone(wr), zc, wr)

            if road_R_here:
                for zc in zone_cols_R:
                    if in_bounds(zc, wr) and 2 <= zc < WORLD_W - 2:
                        if zone_area_free(wr, zc):
                            return (pick_zone(wr), zc, wr)

        # Lateral wires to reach left zone columns
        for wr in wire_rows:
            for wc in range(wire_col - 2, max(wire_col - 9, 0) - 1, -1):
                if not in_bounds(wc, wr):
                    break
                if bool(wm[wr, wc]):
                    continue
                if bool(pm[wr, wc]) or bool(rm[wr, wc]):
                    break
                if bool(em[wr, wc]):
                    return (Tool.WIRE, wc, wr)
                break

        # Lateral roads to reach right zone columns
        for wr in wire_rows:
            for rc in range(road_R + 1, min(wire_col + 10, WORLD_W)):
                if not in_bounds(rc, wr):
                    break
                if bool(rm[wr, rc]):
                    continue
                if bool(pm[wr, rc]) or bool(wm[wr, rc]):
                    break
                if bool(em[wr, rc]):
                    return (Tool.ROAD, rc, wr)
                break

        return None

    # Corridor 1: wire at col 59 (P1X+4), center row P1Y
    wire_col1 = P1X + 4  # 59
    act1 = corridor_action(wire_col1, P1Y, P1Y)
    if act1 is not None:
        return act1

    # Corridor 2: activate after some population
    if obs.city_pop > 80:
        if not has_p2:
            return (Tool.COALPOWER, P2X, P2Y)
        # Connect P2 to its wire column
        wire_col2 = P2X + 4  # 84
        # Seed wire near plant2 if none
        wire_rows2 = sorted(int(r) for r in np.where(wm[:, wire_col2])[0])
        if not wire_rows2:
            # lay wire from plant2 to wire_col2
            for wc in range(P2X + 2, wire_col2 + 1):
                if in_bounds(wc, P2Y) and bool(em[P2Y, wc]):
                    return (Tool.WIRE, wc, P2Y)
        act2 = corridor_action(wire_col2, P2Y, P2Y)
        if act2 is not None:
            return act2

    # Services
    if obs.city_pop > 250:
        fx, fy = wire_col1 + 10, P1Y - 10
        if in_bounds(fx, fy) and zone_area_free(fy, fx):
            return (Tool.FIRESTATION, fx, fy)

    if obs.city_pop > 450:
        px2, py2 = wire_col1 - 10, P1Y + 10
        if in_bounds(px2, py2) and zone_area_free(py2, px2):
            return (Tool.POLICESTATION, px2, py2)

    # Third corridor on the left for very high pop
    if obs.city_pop > 300:
        P3X, P3Y = 30, 50
        has_p3 = any(abs(px - P3X) <= 5 and abs(py - P3Y) <= 5
                     for py, px in zip(plant_ys.tolist(), plant_xs.tolist()))
        if not has_p3:
            return (Tool.COALPOWER, P3X, P3Y)
        wire_col3 = P3X + 4  # 34
        act3 = corridor_action(wire_col3, P3Y, P3Y)
        if act3 is not None:
            return act3

    # Fallback: extend any existing road
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        idx = int(obs.step * 17) % len(road_xs)
        rx, ry = int(road_xs[idx]), int(road_ys[idx])
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx, ny = rx + dx, ry + dy
            if in_bounds(nx, ny) and bool(em[ny, nx]):
                return (Tool.ROAD, nx, ny)

    # Fallback: extend any existing wire
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        idx = int(obs.step * 11) % len(wire_xs)
        wx, wy = int(wire_xs[idx]), int(wire_ys[idx])
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx, ny = wx + dx, wy + dy
            if in_bounds(nx, ny) and bool(em[ny, nx]):
                return (Tool.WIRE, nx, ny)

    return None

def act(obs, state):
    """
    Variation: horizontal wire spine instead of vertical, with zones above/below.
    Uses a row-based layout: power plant on left, horizontal wire runs right,
    roads above and below wire, zones placed above/below roads.
    This creates a horizontal corridor rather than vertical.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        if com_count / t < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Phase 1: Place coal power plant at left-center
    if not np.any(pm):
        return (Tool.COALPOWER, 8, cy)

    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Horizontal layout
    wire_row = plant_cy          # horizontal wire spine row
    road_row_above = wire_row - 2  # road above wire
    road_row_below = wire_row + 2  # road below wire
    zone_row_above = road_row_above - 3  # zones above road
    zone_row_below = road_row_below + 3  # zones below road

    # Clamp rows
    wire_row = max(5, min(WORLD_H - 6, wire_row))
    road_row_above = max(2, min(WORLD_H - 3, wire_row - 2))
    road_row_below = max(2, min(WORLD_H - 3, wire_row + 2))
    zone_row_above = max(2, min(WORLD_H - 3, road_row_above - 3))
    zone_row_below = max(2, min(WORLD_H - 3, road_row_below + 3))

    # Horizontal extent based on population
    if obs.city_pop < 100:
        extent = 15
    elif obs.city_pop < 300:
        extent = 25
    elif obs.city_pop < 600:
        extent = 40
    else:
        extent = 55

    wire_start = plant_cx + 3
    target_min = max(2, wire_start)
    target_max = min(WORLD_W - 3, wire_start + extent)

    wire_cols = sorted(c for c in range(WORLD_W) if wm[wire_row, c])
    road_cols_above = set(c for c in range(WORLD_W) if rm[road_row_above, c])
    road_cols_below = set(c for c in range(WORLD_W) if rm[road_row_below, c])

    # Phase 2: Start wire adjacent to plant
    if not wire_cols:
        for dc in range(0, 6):
            for nc in [plant_cx + dc + 1, plant_cx + dc]:
                if 0 <= nc < WORLD_W and 0 <= wire_row < WORLD_H:
                    if em[wire_row, nc] or wm[wire_row, nc]:
                        return (Tool.WIRE, nc, wire_row)
        return None

    min_wc = min(wire_cols)
    max_wc = max(wire_cols)

    # Phase 3: Extend wire rightward
    if max_wc < target_max:
        nc = max_wc + 1
        if nc < WORLD_W and not pm[wire_row, nc]:
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # Phase 4: Extend wire leftward (toward plant)
    if min_wc > target_min:
        nc = min_wc - 1
        if nc >= 0 and not pm[wire_row, nc]:
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # Phase 5: Build roads above and below along wire
    for wc in wire_cols:
        if wc not in road_cols_above and 0 <= road_row_above < WORLD_H:
            if em[road_row_above, wc]:
                return (Tool.ROAD, wc, road_row_above)
        if wc not in road_cols_below and 0 <= road_row_below < WORLD_H:
            if em[road_row_below, wc]:
                return (Tool.ROAD, wc, road_row_below)

    # Helper: check if 3x3 zone area is clear
    all_zone_mask = resm | comm | indm

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    # Phase 6: Place zones above road (zone_row_above)
    zone_cols_list = list(range(target_min + 1, target_max, 3))

    for zc in zone_cols_list:
        wire_near = any(abs(zc - wc) <= 2 for wc in wire_cols)
        road_near_above = any(abs(zc - rc) <= 2 for rc in road_cols_above)
        road_near_below = any(abs(zc - rc) <= 2 for rc in road_cols_below)

        if not wire_near:
            continue

        if road_near_above:
            zr = zone_row_above
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                return (pick_tool(), zc, zr)

        if road_near_below:
            zr = zone_row_below
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                return (pick_tool(), zc, zr)

    # Phase 7: Vertical roads connecting wire row to road rows
    for wc in wire_cols:
        # Connect wire_row to road_row_above via vertical road segments
        if wc in road_cols_above:
            for rr in range(min(wire_row, road_row_above), max(wire_row, road_row_above) + 1):
                if rr != wire_row and 0 <= rr < WORLD_H:
                    if em[rr, wc] and not pm[rr, wc]:
                        return (Tool.ROAD, wc, rr)
        if wc in road_cols_below:
            for rr in range(min(wire_row, road_row_below), max(wire_row, road_row_below) + 1):
                if rr != wire_row and 0 <= rr < WORLD_H:
                    if em[rr, wc] and not pm[rr, wc]:
                        return (Tool.ROAD, wc, rr)

    # Phase 8: Second power plant when needed
    if obs.city_pop > 400 and int(np.sum(pm)) < 9:
        px2, py2 = plant_cx, plant_cy + 20
        if 2 <= py2 <= WORLD_H - 3 and 2 <= px2 <= WORLD_W - 3:
            area_ok = all(
                em[py2 + dr, px2 + dc]
                for dr in [-1, 0, 1] for dc in [-1, 0, 1]
                if 0 <= py2 + dr < WORLD_H and 0 <= px2 + dc < WORLD_W
            )
            if area_ok:
                return (Tool.COALPOWER, px2, py2)

    # Phase 9: Second horizontal corridor below first (for larger pop)
    if obs.city_pop > 300:
        wire_row2 = wire_row + 12
        wire_row2 = max(5, min(WORLD_H - 6, wire_row2))
        road_row2_above = max(2, wire_row2 - 2)
        road_row2_below = min(WORLD_H - 3, wire_row2 + 2)
        zone_row2_above = max(2, road_row2_above - 3)
        zone_row2_below = min(WORLD_H - 3, road_row2_below + 3)

        wire_cols2 = sorted(c for c in range(WORLD_W) if wm[wire_row2, c])
        road_cols2_above = set(c for c in range(WORLD_W) if rm[road_row2_above, c])
        road_cols2_below = set(c for c in range(WORLD_W) if rm[road_row2_below, c])

        if not wire_cols2:
            # Vertical wire connection from main spine
            for wr in range(min(wire_row, wire_row2), max(wire_row, wire_row2) + 1):
                if 0 <= wr < WORLD_H and (em[wr, plant_cx + 3] or wm[wr, plant_cx + 3]):
                    return (Tool.WIRE, plant_cx + 3, wr)
        else:
            max_wc2 = max(wire_cols2)
            if max_wc2 < target_max:
                nc = max_wc2 + 1
                if nc < WORLD_W and em[wire_row2, nc]:
                    return (Tool.WIRE, nc, wire_row2)

            for wc in wire_cols2:
                if wc not in road_cols2_above and 0 <= road_row2_above < WORLD_H:
                    if em[road_row2_above, wc]:
                        return (Tool.ROAD, wc, road_row2_above)
                if wc not in road_cols2_below and 0 <= road_row2_below < WORLD_H:
                    if em[road_row2_below, wc]:
                        return (Tool.ROAD, wc, road_row2_below)

            for zc in zone_cols_list:
                wire_near2 = any(abs(zc - wc) <= 2 for wc in wire_cols2)
                road_near2a = any(abs(zc - rc) <= 2 for rc in road_cols2_above)
                road_near2b = any(abs(zc - rc) <= 2 for rc in road_cols2_below)
                if not wire_near2:
                    continue
                if road_near2a:
                    if not zone_already_there(zone_row2_above, zc) and zone_area_ok(zone_row2_above, zc):
                        return (pick_tool(), zc, zone_row2_above)
                if road_near2b:
                    if not zone_already_there(zone_row2_below, zc) and zone_area_ok(zone_row2_below, zc):
                        return (pick_tool(), zc, zone_row2_below)

    # Phase 10: Gap fill roads
    for wc in wire_cols:
        if wc not in road_cols_above and 0 <= road_row_above < WORLD_H:
            if em[road_row_above, wc]:
                return (Tool.ROAD, wc, road_row_above)
        if wc not in road_cols_below and 0 <= road_row_below < WORLD_H:
            if em[road_row_below, wc]:
                return (Tool.ROAD, wc, road_row_below)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map each step to decide next action
    - Places coal plant, then grows wire spine outward from plant
    - Grows roads adjacent to wire spine
    - Places zones wherever road+wire coverage exists
    - Adds second plant and services reactively
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def safe_empty(x, y):
        return in_bounds(x, y) and em[y, x]

    # --- Place first coal plant if missing ---
    if not np.any(pm):
        return (Tool.COALPOWER, 60, 50)

    # Find plant center
    plant_ys, plant_xs = np.where(pm)
    px = int(np.median(plant_xs))
    py = int(np.median(plant_ys))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Wire spine: grow vertically from plant ---
    # Spine column = px + 2 (right of plant)
    wire_col = px + 2

    # Determine desired vertical extent based on pop
    pop_factor = min(40, obs.city_pop // 15)
    tmin = max(2, py - 14 - pop_factor)
    tmax = min(WORLD_H - 3, py + 14 + pop_factor)

    # Check current wire extent in spine column
    wire_in_col = [r for r in range(WORLD_H) if wm[r, wire_col]]

    if not wire_in_col:
        # Plant wire adjacent to plant
        for dy in range(-2, 3):
            ny = py + dy
            if in_bounds(wire_col, ny) and (em[ny, wire_col] or wm[ny, wire_col]):
                return (Tool.WIRE, wire_col, ny)
    else:
        min_wr = min(wire_in_col)
        max_wr = max(wire_in_col)
        # Extend downward first
        if max_wr < tmax:
            nr = max_wr + 1
            if in_bounds(wire_col, nr) and (em[nr, wire_col] or wm[nr, wire_col]) and not pm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if min_wr > tmin:
            nr = min_wr - 1
            if in_bounds(wire_col, nr) and (em[nr, wire_col] or wm[nr, wire_col]) and not pm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # --- Road columns flanking wire spine ---
    road_col_r = wire_col + 1
    road_col_l = wire_col - 1

    # Build roads at every wire row
    for wr in wire_in_col:
        if in_bounds(road_col_r, wr) and em[wr, road_col_r]:
            return (Tool.ROAD, road_col_r, wr)
        if in_bounds(road_col_l, wr) and em[wr, road_col_l]:
            return (Tool.ROAD, road_col_l, wr)

    # --- Reactive zone placement ---
    # Build proximity masks from current map
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                # Allow placing over existing zone cells of same 3x3
                if not em[nr, nc] and not zone_tiles[nr, nc]:
                    return False
        return True

    # Candidate zone centers
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Sort candidates by proximity to wire spine
        dists = np.abs(cxs - wire_col)
        order = np.argsort(dists)
        checked = 0
        step_off = int(obs.step * 3) % max(len(order), 1)
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 80:
                break

    # --- Extend roads outward from existing roads near wire ---
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 20)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx]:
                    if nbr_wire[ny, nx]:
                        return (Tool.ROAD, nx, ny)

    # --- Second power plant when city grows ---
    if total_zones > 12 or obs.city_pop > 300:
        # Place second plant to the right
        p2x = px + 22
        p2y = py
        if in_bounds(p2x, p2y):
            nearby = any(
                in_bounds(p2x + dx, p2y + dy) and pm[p2y + dy, p2x + dx]
                for dy in range(-5, 6) for dx in range(-5, 6)
            )
            if not nearby and em[p2y, p2x]:
                return (Tool.COALPOWER, p2x, p2y)
            # Wire horizontal bridge from spine to second plant
            for wc in range(wire_col + 2, p2x - 1):
                if in_bounds(wc, py) and em[py, wc]:
                    return (Tool.WIRE, wc, py)
            # Vertical wire spine for second plant
            wire_col2 = p2x - 2
            for wr in wire_in_col:
                if in_bounds(wire_col2, wr) and em[wr, wire_col2]:
                    return (Tool.WIRE, wire_col2, wr)

    # --- Services when pop is high enough ---
    if obs.city_pop > 120:
        # Fire station
        fsx, fsy = px - 6, py - 7
        if in_bounds(fsx, fsy) and em[fsy, fsx]:
            return (Tool.FIRESTATION, fsx, fsy)
        # Police station
        psx, psy = px - 6, py + 7
        if in_bounds(psx, psy) and em[psy, psx]:
            return (Tool.POLICESTATION, psx, psy)

    # --- Grow wire frontier laterally to reach new zones ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 15)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = wx + dx2, wy + dy2
                if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                    return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop city builder:
    - Scan map each step to find where power/roads reach
    - Extend infrastructure adjacently to what already exists
    - Place zones where both power and road are accessible
    - Adapt zone mix based on current counts
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    all_zone = resm | comm | indm

    ROAD_ROW = 50  # horizontal road spine row
    WIRE_ROW_ABOVE = 49  # wire 1 row above road
    WIRE_ROW_BELOW = 51  # wire 1 row below road

    res_count = int(np.sum(resm)) // 9 + 1
    com_count = int(np.sum(comm)) // 9 + 1
    ind_count = int(np.sum(indm)) // 9 + 1
    total_z = res_count + com_count + ind_count

    def pick_tool():
        if com_count / total_z < 0.28:
            return Tool.COMMERCIAL
        if ind_count / total_z < 0.18:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Phase 1: Place coal power plant if none exists
    if not np.any(pm):
        return (Tool.COALPOWER, 10, ROAD_ROW)

    # Find plant location
    pr, pc = np.where(pm)
    plant_cx = int(np.mean(pc))
    plant_cy = int(np.mean(pr))

    # Phase 2: Extend road spine rightward from existing road or plant
    # Find rightmost road on ROAD_ROW
    road_on_spine = np.where(rm[ROAD_ROW, :])[0]
    if len(road_on_spine) > 0:
        road_right = int(np.max(road_on_spine))
    else:
        road_right = plant_cx + 2

    # Target road extent based on population
    pop = obs.city_pop
    if pop < 200:
        target_road_end = min(60, WORLD_W - 4)
    elif pop < 500:
        target_road_end = min(80, WORLD_W - 4)
    elif pop < 1000:
        target_road_end = min(100, WORLD_W - 4)
    else:
        target_road_end = min(110, WORLD_W - 4)

    # Extend road if needed
    if road_right < target_road_end:
        next_r = road_right + 1
        if 0 <= next_r < WORLD_W:
            if em[ROAD_ROW, next_r] and not pm[ROAD_ROW, next_r]:
                return (Tool.ROAD, next_r, ROAD_ROW)
            elif not rm[ROAD_ROW, next_r] and not pm[ROAD_ROW, next_r]:
                return (Tool.ROAD, next_r, ROAD_ROW)  # bulldoze+place

    # Phase 3: Extend wire above road spine from existing wire or plant
    wire_above = np.where(wm[WIRE_ROW_ABOVE, :])[0]
    if len(wire_above) > 0:
        wire_right_above = int(np.max(wire_above))
    else:
        wire_right_above = plant_cx

    if wire_right_above < target_road_end + 1:
        next_c = wire_right_above + 1
        if 0 <= next_c < WORLD_W and WIRE_ROW_ABOVE >= 0:
            if em[WIRE_ROW_ABOVE, next_c] and not pm[WIRE_ROW_ABOVE, next_c]:
                return (Tool.WIRE, next_c, WIRE_ROW_ABOVE)

    # Phase 4: Extend wire below road spine
    wire_below = np.where(wm[WIRE_ROW_BELOW, :])[0]
    if len(wire_below) > 0:
        wire_right_below = int(np.max(wire_below))
    else:
        wire_right_below = plant_cx

    if wire_right_below < target_road_end + 1:
        next_c = wire_right_below + 1
        if 0 <= next_c < WORLD_W and WIRE_ROW_BELOW < WORLD_H:
            if em[WIRE_ROW_BELOW, next_c] and not pm[WIRE_ROW_BELOW, next_c]:
                return (Tool.WIRE, next_c, WIRE_ROW_BELOW)

    # Phase 5: Connect plant to wire spine if not connected
    # Wire from plant_cy up to WIRE_ROW_ABOVE at plant_cx+2
    wire_col = plant_cx + 2
    if 0 <= wire_col < WORLD_W:
        # Connect vertically from plant to wire rows
        for r in range(min(plant_cy - 1, WIRE_ROW_ABOVE + 1), WIRE_ROW_ABOVE - 1, -1):
            if 0 <= r < WORLD_H and not wm[r, wire_col] and not pm[r, wire_col] and em[r, wire_col]:
                return (Tool.WIRE, wire_col, r)
        for r in range(max(plant_cy + 2, WIRE_ROW_BELOW - 1), WIRE_ROW_BELOW + 2):
            if 0 <= r < WORLD_H and not wm[r, wire_col] and not pm[r, wire_col] and em[r, wire_col]:
                return (Tool.WIRE, wire_col, r)

    # Phase 6: Place zones adjacent to road with wire access
    # Zone centers above road: ROAD_ROW - 2, below: ROAD_ROW + 2
    # Scan existing road to find powered sections and place zones

    def has_wire_nearby(zr, zc, radius=3):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=2):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    def zone_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                # Allow empty or existing zone tiles
                if not em[rr, rc] and not all_zone[rr, rc]:
                    return False
        return True

    def zone_present(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone[rr, rc]:
                        return True
        return False

    # Find road extent for zone placement
    actual_road_end = int(np.max(road_on_spine)) if len(road_on_spine) > 0 else plant_cx + 2
    road_start = int(np.min(road_on_spine)) if len(road_on_spine) > 0 else plant_cx + 2

    # Try placing zones above and below road, scanning left to right
    for zc in range(road_start + 2, actual_road_end - 1, 4):
        if zc < 2 or zc > WORLD_W - 3:
            continue
        for zr in [ROAD_ROW - 2, ROAD_ROW + 2]:
            if zr < 2 or zr > WORLD_H - 3:
                continue
            if not zone_present(zr, zc) and zone_ok(zr, zc):
                if has_road_nearby(zr, zc) and has_wire_nearby(zr, zc):
                    return (pick_tool(), zc, zr)

    # Phase 7: Add vertical road spurs for zone access
    for zc in range(road_start + 2, actual_road_end - 1, 8):
        if zc < 2 or zc > WORLD_W - 3:
            continue
        for zr, direction in [(ROAD_ROW - 2, -1), (ROAD_ROW + 2, 1)]:
            if zr < 2 or zr > WORLD_H - 3:
                continue
            # Road spur from ROAD_ROW toward zone
            mid_r = ROAD_ROW + direction
            if 0 <= mid_r < WORLD_H and not rm[mid_r, zc] and em[mid_r, zc] and not pm[mid_r, zc]:
                return (Tool.ROAD, zc, mid_r)

    # Phase 8: Second coal power plant when pop grows
    if pop > 400 and int(np.sum(pm)) < 10:
        px2 = min(actual_road_end + 4, WORLD_W - 5)
        py2 = ROAD_ROW
        # Find empty spot near road end
        for dy in range(0, 5):
            for dx in range(0, 4):
                tx, ty = px2 + dx, py2 + dy
                if 2 <= tx <= WORLD_W - 3 and 2 <= ty <= WORLD_H - 3:
                    if em[ty, tx]:
                        return (Tool.COALPOWER, tx, ty)

    # Phase 9: Connect second plant via wire
    if int(np.sum(pm)) >= 18:
        pr2, pc2 = np.where(pm)
        # rightmost plant tiles
        right_col = int(np.max(pc2))
        right_row = int(np.mean(pr2[pc2 >= right_col - 1]))
        # Wire leftward to connect
        for c in range(right_col - 2, wire_col, -1):
            if 0 <= c < WORLD_W and not wm[right_row, c] and not pm[right_row, c] and em[right_row, c]:
                return (Tool.WIRE, c, int(right_row))

    # Phase 10: Expand zones further from road when pop grows
    if pop > 600:
        for zc in range(road_start + 2, actual_road_end - 1, 4):
            if zc < 2 or zc > WORLD_W - 3:
                continue
            for zr in [ROAD_ROW - 5, ROAD_ROW + 5]:
                if zr < 2 or zr > WORLD_H - 3:
                    continue
                if not zone_present(zr, zc) and zone_ok(zr, zc):
                    if has_road_nearby(zr, zc, 4) and has_wire_nearby(zr, zc, 4):
                        return (pick_tool(), zc, zr)

    # Phase 11: Services
    cx, cy = WORLD_W // 2, WORLD_H // 2
    if pop > 300:
        ps_x, ps_y = cx + 8, ROAD_ROW - 8
        if 2 <= ps_x <= WORLD_W - 3 and 2 <= ps_y <= WORLD_H - 3 and em[ps_y, ps_x]:
            return (Tool.POLICESTATION, ps_x, ps_y)
    if pop > 500:
        fs_x, fs_y = cx - 8, ROAD_ROW + 8
        if 2 <= fs_x <= WORLD_W - 3 and 2 <= fs_y <= WORLD_H - 3 and em[fs_y, fs_x]:
            return (Tool.FIRESTATION, fs_x, fs_y)

    # Phase 12: Wire vertical connectors to ensure zones get power
    # For each zone column, add wire from WIRE_ROW_ABOVE down to near zone
    for zc in range(road_start + 2, actual_road_end - 1, 4):
        if zc < 2 or zc > WORLD_W - 3:
            continue
        # Check if wire exists at WIRE_ROW_ABOVE at this column
        if wm[WIRE_ROW_ABOVE, zc] or pm[WIRE_ROW_ABOVE, zc]:
            # Extend wire vertically up toward zone center
            zr_above = ROAD_ROW - 2
            for r in range(WIRE_ROW_ABOVE - 1, zr_above - 1, -1):
                if 0 <= r < WORLD_H and not wm[r, zc] and em[r, zc] and not pm[r, zc]:
                    return (Tool.WIRE, zc, r)
        if wm[WIRE_ROW_BELOW, zc] or pm[WIRE_ROW_BELOW, zc]:
            zr_below = ROAD_ROW + 2
            for r in range(WIRE_ROW_BELOW + 1, zr_below + 2):
                if 0 <= r < WORLD_H and not wm[r, zc] and em[r, zc] and not pm[r, zc]:
                    return (Tool.WIRE, zc, r)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy: reads tile_map every step to decide next action.
    Layout: coal plant -> vertical wire spine -> roads on both sides -> zones beside roads.
    Expands based on observed state, not a fixed plan.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    all_zone = resm | comm | indm

    cx, cy = WORLD_W // 2, WORLD_H // 2

    # Phase 1: Place coal plant if missing
    if not np.any(pm):
        # Place near center-left so wire/roads have room to the right
        return (Tool.COALPOWER, cx - 8, cy)

    # Find plant center
    plant_rows, plant_cols = np.where(pm)
    pcx = int(np.mean(plant_cols))
    pcy = int(np.mean(plant_rows))

    # Layout relative to plant (all clamped)
    wire_col = max(2, min(WORLD_W - 3, pcx + 4))
    road_r = max(2, min(WORLD_W - 3, wire_col + 2))
    road_l = max(2, min(WORLD_W - 3, wire_col - 2))
    zone_r = max(2, min(WORLD_W - 3, road_r + 3))
    zone_l = max(2, min(WORLD_W - 3, road_l - 3))

    # Spine vertical extent grows with population
    if obs.city_pop < 50:
        extent = 8
    elif obs.city_pop < 200:
        extent = 14
    elif obs.city_pop < 500:
        extent = 22
    else:
        extent = 30

    spine_top = max(2, pcy - extent)
    spine_bot = min(WORLD_H - 3, pcy + extent)

    # Read current wire, road positions
    wire_rows = sorted(r for r in range(WORLD_H) if wm[r, wire_col])
    road_rows_r = set(r for r in range(WORLD_H) if rm[r, road_r])
    road_rows_l = set(r for r in range(WORLD_H) if rm[r, road_l])

    # Phase 2: Start wire spine adjacent to plant
    if not wire_rows:
        for dy in range(0, 8):
            for nr in [pcy + dy, pcy - dy]:
                if 0 <= nr < WORLD_H and 0 <= wire_col < WORLD_W:
                    if em[nr, wire_col] or wm[nr, wire_col]:
                        return (Tool.WIRE, wire_col, nr)
        return (Tool.WIRE, wire_col, pcy)

    min_wr = min(wire_rows)
    max_wr = max(wire_rows)

    # Phase 3: Extend wire spine downward
    if max_wr < spine_bot:
        nr = max_wr + 1
        if nr < WORLD_H and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Phase 4: Extend wire spine upward
    if min_wr > spine_top:
        nr = min_wr - 1
        if nr >= 0 and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Phase 5: Build road columns alongside wire spine
    # Prioritize rows closest to plant center first
    for wr in sorted(wire_rows, key=lambda y: abs(y - pcy)):
        if spine_top <= wr <= spine_bot:
            if wr not in road_rows_r and 0 <= road_r < WORLD_W and em[wr, road_r]:
                return (Tool.ROAD, road_r, wr)
            if wr not in road_rows_l and 0 <= road_l < WORLD_W and em[wr, road_l]:
                return (Tool.ROAD, road_l, wr)

    # Helper: check 3x3 area is all empty (or already same zone)
    def area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                r2, c2 = zr + dr, zc + dc
                if not (0 <= r2 < WORLD_H and 0 <= c2 < WORLD_W):
                    return False
                if not em[r2, c2]:
                    return False
        return True

    def zone_nearby(zr, zc, radius=2):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(all_zone[r0:r1, c0:c1])

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total = res_count + com_count + ind_count

    def pick_tool():
        if total == 0:
            return Tool.RESIDENTIAL
        t = max(1, total)
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Phase 6: Place zones beside roads (scan from center outward)
    cand_rows = sorted(wire_rows, key=lambda y: abs(y - pcy))
    for zr in cand_rows:
        if not (spine_top <= zr <= spine_bot):
            continue
        road_near_r = any(abs(zr - rr) <= 1 for rr in road_rows_r)
        road_near_l = any(abs(zr - rr) <= 1 for rr in road_rows_l)

        if road_near_r:
            if not zone_nearby(zr, zone_r) and area_ok(zr, zone_r):
                return (pick_tool(), zone_r, zr)
        if road_near_l:
            if not zone_nearby(zr, zone_l) and area_ok(zr, zone_l):
                return (pick_tool(), zone_l, zr)

    # Phase 7: Lateral roads to reach zone columns (extend outward from spine roads)
    for wr in sorted(wire_rows, key=lambda y: abs(y - pcy)):
        if wr in road_rows_r:
            for rc in range(road_r + 1, zone_r + 2):
                if rc >= WORLD_W:
                    break
                if rm[wr, rc]:
                    break
                if em[wr, rc] and not pm[wr, rc]:
                    return (Tool.ROAD, rc, wr)
                elif not em[wr, rc]:
                    break
        if wr in road_rows_l:
            for rc in range(road_l - 1, zone_l - 2, -1):
                if rc < 0:
                    break
                if rm[wr, rc]:
                    break
                if em[wr, rc] and not pm[wr, rc]:
                    return (Tool.ROAD, rc, wr)
                elif not em[wr, rc]:
                    break

    # Phase 8: Second power plant when city grows
    if obs.city_pop > 300 and int(np.sum(pm)) < 9:
        px2 = max(2, min(WORLD_W - 3, pcx + 22))
        py2 = pcy
        all_empty2 = all(
            0 <= py2 + dr < WORLD_H and 0 <= px2 + dc < WORLD_W and em[py2 + dr, px2 + dc]
            for dr in [-1, 0, 1] for dc in [-1, 0, 1]
        )
        if all_empty2:
            return (Tool.COALPOWER, px2, py2)

    # Phase 9: Horizontal wire bridge for second cluster when pop large
    if obs.city_pop > 300:
        wire_col2 = max(2, min(WORLD_W - 3, zone_r + 6))
        road_r2 = max(2, min(WORLD_W - 3, wire_col2 + 2))
        zone_r2 = max(2, min(WORLD_W - 3, road_r2 + 3))

        wire_rows2 = sorted(r for r in range(WORLD_H) if wm[r, wire_col2])
        road_rows_r2 = set(r for r in range(WORLD_H) if rm[r, road_r2])

        if not wire_rows2:
            # Build horizontal wire bridge at pcy from main spine to new spine
            for wc in range(wire_col + 1, wire_col2 + 1):
                if wc >= WORLD_W:
                    break
                if wm[pcy, wc]:
                    continue
                if em[pcy, wc] and not pm[pcy, wc]:
                    return (Tool.WIRE, wc, pcy)
                else:
                    break
        else:
            min_wr2 = min(wire_rows2)
            max_wr2 = max(wire_rows2)
            if max_wr2 < spine_bot:
                nr = max_wr2 + 1
                if nr < WORLD_H and (em[nr, wire_col2] or wm[nr, wire_col2]):
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > spine_top:
                nr = min_wr2 - 1
                if nr >= 0 and (em[nr, wire_col2] or wm[nr, wire_col2]):
                    return (Tool.WIRE, wire_col2, nr)

            for wr in sorted(wire_rows2, key=lambda y: abs(y - pcy)):
                if wr not in road_rows_r2 and 0 <= road_r2 < WORLD_W and em[wr, road_r2]:
                    return (Tool.ROAD, road_r2, wr)

            for zr in sorted(wire_rows2, key=lambda y: abs(y - pcy)):
                road_near2 = any(abs(zr - rr) <= 1 for rr in road_rows_r2)
                if road_near2 and not zone_nearby(zr, zone_r2) and area_ok(zr, zone_r2):
                    return (pick_tool(), zone_r2, zr)

            for wr in sorted(wire_rows2, key=lambda y: abs(y - pcy)):
                if wr in road_rows_r2:
                    for rc in range(road_r2 + 1, zone_r2 + 2):
                        if rc >= WORLD_W:
                            break
                        if rm[wr, rc]:
                            break
                        if em[wr, rc] and not pm[wr, rc]:
                            return (Tool.ROAD, rc, wr)
                        elif not em[wr, rc]:
                            break

    # Phase 10: Gap-fill any missing roads
    for wr in sorted(wire_rows, key=lambda y: abs(y - pcy)):
        if spine_top <= wr <= spine_bot:
            if wr not in road_rows_r and 0 <= road_r < WORLD_W and em[wr, road_r]:
                return (Tool.ROAD, road_r, wr)
            if wr not in road_rows_l and 0 <= road_l < WORLD_W and em[wr, road_l]:
                return (Tool.ROAD, road_l, wr)

    return None

def act(obs, state):
    """
    Closed-loop policy: each step reads the current map and decides
    what single tile to place next based on observed state.

    Strategy:
    1. If no power plant exists, place one near center
    2. Extend wires from power plant toward zones
    3. Build roads in a grid pattern near zones
    4. Place zones adjacent to roads that are powered
    5. Reactively balance res/com/ind ratios
    """
    tm = obs.tile_map
    emp = empty_mask(tm)
    res = res_mask(tm)
    com = com_mask(tm)
    ind = ind_mask(tm)
    roads = road_mask(tm)
    wires = wire_mask(tm)
    plants = plant_mask(tm)

    # Phase counter for initialization
    if "phase" not in state:
        state["phase"] = 0
        state["step"] = 0
    state["step"] += 1

    # Helper: find cells adjacent to a boolean mask
    def adjacent_to(mask):
        nb = np.zeros_like(mask)
        nb[1:, :] |= mask[:-1, :]
        nb[:-1, :] |= mask[1:, :]
        nb[:, 1:] |= mask[:, :-1]
        nb[:, :-1] |= mask[:, 1:]
        return nb

    # Helper: pick candidate from mask, prefer close to center
    def pick_from(mask, cx=55, cy=50):
        ys, xs = np.where(mask)
        if len(xs) == 0:
            return None
        # Score by distance to center
        dists = np.abs(xs - cx) + np.abs(ys - cy)
        k = np.argmin(dists)
        return int(xs[k]), int(ys[k])

    # Helper: pick candidate closest to a reference point
    def pick_nearest(mask, rx, ry):
        ys, xs = np.where(mask)
        if len(xs) == 0:
            return None
        dists = np.abs(xs - rx) + np.abs(ys - ry)
        k = np.argmin(dists)
        return int(xs[k]), int(ys[k])

    # Center of operations
    CX, CY = 55, 50

    # --- STEP 1: Ensure we have a power plant ---
    n_plants = int(plants.sum())
    if n_plants == 0:
        # Place coal power plant at a safe offset from center
        return (Tool.COALPOWER, CX - 15, CY - 10)

    # Find power plant location (approximate center of plant tiles)
    pys, pxs = np.where(plants)
    plant_cx = int(np.mean(pxs))
    plant_cy = int(np.mean(pys))

    # --- STEP 2: Build initial road grid if sparse ---
    n_roads = int(roads.sum())
    n_wires = int(wires.sum())
    n_zones = int((res | com | ind).sum())

    # Build a cross of roads centered at CX, CY
    # Horizontal road: y=CY, x in [CX-15, CX+15]
    # Vertical roads: x=CX-6, CX+6, y in [CY-12, CY+12]

    # Check if main horizontal road needs extension
    # Horizontal road target: y=CY, x from CX-15 to CX+15
    h_road_ys = np.ones(31, dtype=bool)
    for i, x in enumerate(range(CX-15, CX+16)):
        if 0 <= x < WORLD_W and 0 <= CY < WORLD_H:
            if roads[CY, x]:
                h_road_ys[i] = False

    # Build horizontal road first
    road_target_y = CY
    for x in range(CX-15, CX+16):
        if 0 <= x < WORLD_W and 0 <= road_target_y < WORLD_H:
            if not roads[road_target_y, x]:
                return (Tool.ROAD, x, road_target_y)

    # Build vertical roads
    for vx in [CX - 9, CX - 3, CX + 3, CX + 9]:
        for y in range(CY - 12, CY + 13):
            if 0 <= vx < WORLD_W and 0 <= y < WORLD_H:
                if not roads[y, vx]:
                    return (Tool.ROAD, vx, y)

    # --- STEP 3: Connect power plant to road grid via wires ---
    # Wire from plant toward the road grid
    # We want wires to reach from plant to zones/roads
    power_grid = plants | wires

    # Extend wires toward CX, CY from plant
    # Find wire/plant cell closest to CX, CY
    pg_adj = adjacent_to(power_grid) & emp

    if pg_adj.any():
        # Pick the one that moves closest to CX, CY
        result = pick_nearest(pg_adj, CX, CY)
        if result:
            wx, wy = result
            # Only place wire if it's not too far from the plant and moves toward center
            dist_to_center = abs(wx - CX) + abs(wy - CY)
            plant_dist = abs(plant_cx - CX) + abs(plant_cy - CY)

            # Place wire if power grid hasn't reached near zones yet
            # Check if zones near roads have power nearby
            road_near_zone = roads & adjacent_to(res | com | ind)
            powered_near = power_grid & adjacent_to(road_near_zone)

            if not powered_near.any() or (n_wires < 30 and dist_to_center < plant_dist):
                return (Tool.WIRE, wx, wy)

    # --- STEP 4: Place zones adjacent to roads ---
    # Count zone types
    n_res = int(res.sum())
    n_com = int(com.sum())
    n_ind = int(ind.sum())

    # Find road-adjacent empty cells (excluding road cells themselves)
    road_adj_emp = adjacent_to(roads) & emp

    # Also check power availability - prefer spots near wires
    power_adj = adjacent_to(power_grid)

    # Decide which zone type to place based on ratio
    # Target: ~3 res : 2 com : 2 ind
    total_zones = n_res + n_com + n_ind
    if total_zones == 0:
        tool = Tool.RESIDENTIAL
    elif n_res * 2 < total_zones * 3 // 3:
        tool = Tool.RESIDENTIAL
    elif n_com * 3 < total_zones * 2:
        tool = Tool.COMMERCIAL  
    elif n_ind * 3 < total_zones * 2:
        tool = Tool.INDUSTRIAL
    else:
        # Cycle through to maintain ratio
        cycle = state["step"] % 7
        if cycle < 3:
            tool = Tool.RESIDENTIAL
        elif cycle < 5:
            tool = Tool.COMMERCIAL
        else:
            tool = Tool.INDUSTRIAL

    # Prefer placing zones near power AND roads
    best_cand = road_adj_emp & power_adj
    if best_cand.any():
        result = pick_from(best_cand, CX, CY)
        if result:
            return (tool, result[0], result[1])

    # Fallback: near roads only
    if road_adj_emp.any():
        result = pick_from(road_adj_emp, CX, CY)
        if result:
            return (tool, result[0], result[1])

    # --- STEP 5: Extend wires to reach unpowered zones ---
    zones_all = res | com | ind
    if zones_all.any():
        # Find zones not near power
        unpowered_zones = zones_all & ~power_adj
        if unpowered_zones.any():
            # Place wire adjacent to power grid, toward unpowered zones
            uz_ys, uz_xs = np.where(unpowered_zones)
            if len(uz_xs) > 0:
                # Pick closest unpowered zone
                tgt_x, tgt_y = int(np.mean(uz_xs)), int(np.mean(uz_ys))
                result = pick_nearest(pg_adj, tgt_x, tgt_y)
                if result:
                    return (Tool.WIRE, result[0], result[1])

    # --- STEP 6: Add a second power plant if population stagnant ---
    if obs.city_pop < 100 and n_plants < 6 and state["step"] > 50:
        # Place another coal plant on the other side
        for px, py in [(CX + 20, CY - 10), (CX - 15, CY + 15), (CX + 20, CY + 15)]:
            if 0 <= px < WORLD_W - 3 and 0 <= py < WORLD_H - 3:
                if emp[py, px]:
                    return (Tool.COALPOWER, px, py)

    # --- STEP 7: Extend roads and wires to new areas ---
    # Extend roads outward
    road_adj_emp2 = adjacent_to(roads) & emp
    if road_adj_emp2.any():
        # Pick road extension closest to center
        result = pick_from(road_adj_emp2, CX, CY)
        if result:
            return (Tool.ROAD, result[0], result[1])

    # Last resort: place wire adjacent to existing power
    if pg_adj.any():
        result = pick_from(pg_adj, CX, CY)
        if result:
            return (Tool.WIRE, result[0], result[1])

    return None

def act(obs, state):
    """
    Closed-loop reactive policy: reads tile_map every step, builds
    a compact powered corridor with bilateral roads and zones.
    - Wire spine from plant
    - Roads on both sides of spine
    - Zones on both sides of roads
    - Expands based on current map state, not precomputed plan
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    all_zone = resm | comm | indm

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone[rr, rc]:
                        return True
        return False

    # Phase 1: Place coal power plant if missing
    if not np.any(pm):
        return (Tool.COALPOWER, cx - 10, cy)

    # Find plant center
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Layout geometry derived from plant position
    wire_col = plant_cx + 3
    road_col_r = wire_col + 1
    road_col_l = wire_col - 1
    zone_col_r = road_col_r + 3
    zone_col_l = road_col_l - 3

    # Clamp columns
    wire_col   = max(2, min(WORLD_W - 3, wire_col))
    road_col_r = max(2, min(WORLD_W - 3, road_col_r))
    road_col_l = max(2, min(WORLD_W - 3, road_col_l))
    zone_col_r = max(2, min(WORLD_W - 3, zone_col_r))
    zone_col_l = max(2, min(WORLD_W - 3, zone_col_l))

    # Spine extent based on current population (reactive)
    pop = obs.city_pop
    if pop < 50:
        spine_extent = 8
    elif pop < 150:
        spine_extent = 12
    elif pop < 400:
        spine_extent = 18
    elif pop < 800:
        spine_extent = 26
    else:
        spine_extent = 34

    target_min = max(2, cy - spine_extent)
    target_max = min(WORLD_H - 3, cy + spine_extent)

    # Read current wire spine
    wire_rows = sorted(r for r in range(WORLD_H) if wm[r, wire_col])
    road_rows_r = set(r for r in range(WORLD_H) if rm[r, road_col_r])
    road_rows_l = set(r for r in range(WORLD_H) if rm[r, road_col_l])

    # Phase 2: Start wire spine adjacent to plant
    if not wire_rows:
        for dy in range(0, 8):
            for nr in [plant_cy + dy, plant_cy - dy]:
                if 0 <= nr < WORLD_H and 0 <= wire_col < WORLD_W:
                    if em[nr, wire_col]:
                        return (Tool.WIRE, wire_col, nr)
        return None

    min_wr = min(wire_rows)
    max_wr = max(wire_rows)

    # Phase 3: Connect plant to wire spine if not connected
    # Check adjacency of plant to any wire
    plant_connected = False
    for dr in range(-2, 3):
        for dc in range(-2, 3):
            rr, rc = plant_cy + dr, plant_cx + dc
            if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                if wm[rr, rc]:
                    plant_connected = True
    if not plant_connected:
        bridge_r = plant_cy
        for bc in range(plant_cx + 1, wire_col + 1):
            if 0 <= bc < WORLD_W:
                if wm[bridge_r, bc]:
                    break
                if em[bridge_r, bc] and not pm[bridge_r, bc]:
                    return (Tool.WIRE, bc, bridge_r)

    # Phase 4: Extend wire spine downward
    if max_wr < target_max:
        nr = max_wr + 1
        if nr < WORLD_H and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Phase 5: Extend wire spine upward
    if min_wr > target_min:
        nr = min_wr - 1
        if nr >= 0 and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Phase 6: Build roads on both sides of wire spine
    for wr in wire_rows:
        if target_min <= wr <= target_max:
            if wr not in road_rows_r and 0 <= road_col_r < WORLD_W:
                if em[wr, road_col_r] and not pm[wr, road_col_r]:
                    return (Tool.ROAD, road_col_r, wr)
            if wr not in road_rows_l and 0 <= road_col_l < WORLD_W:
                if em[wr, road_col_l] and not pm[wr, road_col_l]:
                    return (Tool.ROAD, road_col_l, wr)

    # Phase 7: Place zones on both sides
    zone_rows_list = list(range(target_min, target_max + 1, 3))
    wire_rows_set = set(wire_rows)

    for zr in zone_rows_list:
        wire_near = any(abs(zr - wr) <= 2 for wr in wire_rows)
        if not wire_near:
            continue
        road_near_r = any(abs(zr - rr) <= 2 for rr in road_rows_r)
        road_near_l = any(abs(zr - rr) <= 2 for rr in road_rows_l)

        # Right zones
        if road_near_r:
            zc = zone_col_r
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                return (pick_tool(), zc, zr)

        # Left zones
        if road_near_l:
            zc = zone_col_l
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                return (pick_tool(), zc, zr)

    # Phase 8: Lateral roads toward zone columns
    for wr in wire_rows:
        if target_min <= wr <= target_max:
            if wr in road_rows_r:
                for rc in range(road_col_r + 1, zone_col_r + 2):
                    if rc >= WORLD_W:
                        break
                    if rm[wr, rc]:
                        break
                    if em[wr, rc] and not pm[wr, rc]:
                        return (Tool.ROAD, rc, wr)
                    elif not em[wr, rc]:
                        break
            if wr in road_rows_l:
                for rc in range(road_col_l - 1, zone_col_l - 2, -1):
                    if rc < 0:
                        break
                    if rm[wr, rc]:
                        break
                    if em[wr, rc] and not pm[wr, rc]:
                        return (Tool.ROAD, rc, wr)
                    elif not em[wr, rc]:
                        break

    # Phase 9: Second power plant if population needs it
    if pop > 300:
        plant_count = int(np.sum(pm)) // 9
        if plant_count < 2:
            px2 = plant_cx + 18
            py2 = plant_cy
            px2 = max(2, min(WORLD_W - 3, px2))
            py2 = max(2, min(WORLD_H - 3, py2))
            area_ok = True
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    rr, rc = py2 + dr, px2 + dc
                    if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                        if not em[rr, rc]:
                            area_ok = False
            if area_ok:
                return (Tool.COALPOWER, px2, py2)

    # Phase 10: Expand to second cluster on right when population large
    if pop > 400:
        wire_col2 = zone_col_r + 5
        wire_col2 = max(2, min(WORLD_W - 3, wire_col2))
        road_col2r = wire_col2 + 1
        zone_col2r = road_col2r + 3
        road_col2r = max(2, min(WORLD_W - 3, road_col2r))
        zone_col2r = max(2, min(WORLD_W - 3, zone_col2r))

        wire_rows2 = sorted(r for r in range(WORLD_H) if wm[r, wire_col2])
        road_rows2r = set(r for r in range(WORLD_H) if rm[r, road_col2r])

        if not wire_rows2:
            # Connect horizontally from main spine at cy
            for wc in range(wire_col + 1, wire_col2 + 1):
                if 0 <= wc < WORLD_W and em[cy, wc] and not rm[cy, wc]:
                    return (Tool.WIRE, wc, cy)
        else:
            min_wr2 = min(wire_rows2)
            max_wr2 = max(wire_rows2)
            if max_wr2 < target_max:
                nr = max_wr2 + 1
                if 0 <= nr < WORLD_H and (em[nr, wire_col2] or wm[nr, wire_col2]):
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > target_min:
                nr = min_wr2 - 1
                if 0 <= nr < WORLD_H and (em[nr, wire_col2] or wm[nr, wire_col2]):
                    return (Tool.WIRE, wire_col2, nr)
            for wr in wire_rows2:
                if wr not in road_rows2r and em[wr, road_col2r]:
                    return (Tool.ROAD, road_col2r, wr)
            for zr in wire_rows2:
                if any(abs(zr - rr) <= 2 for rr in road_rows2r):
                    zc = zone_col2r
                    if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                        return (pick_tool(), zc, zr)
            for wr in wire_rows2:
                if wr in road_rows2r:
                    for rc in range(road_col2r + 1, zone_col2r + 2):
                        if rc >= WORLD_W:
                            break
                        if rm[wr, rc]:
                            break
                        if em[wr, rc] and not pm[wr, rc]:
                            return (Tool.ROAD, rc, wr)
                        elif not em[wr, rc]:
                            break

    # Phase 11: Gap fill - roads for wire rows not yet covered
    for wr in wire_rows:
        if wr not in road_rows_r and 0 <= road_col_r < WORLD_W:
            if em[wr, road_col_r]:
                return (Tool.ROAD, road_col_r, wr)
        if wr not in road_rows_l and 0 <= road_col_l < WORLD_W:
            if em[wr, road_col_l]:
                return (Tool.ROAD, road_col_l, wr)

    # Phase 12: Wider zone columns when very populated
    if pop > 600:
        zone_col_rr = zone_col_r + 4
        zone_col_ll = zone_col_l - 4
        zone_col_rr = max(2, min(WORLD_W - 3, zone_col_rr))
        zone_col_ll = max(2, min(WORLD_W - 3, zone_col_ll))
        for zr in zone_rows_list:
            wire_near = any(abs(zr - wr) <= 2 for wr in wire_rows)
            road_near_r = any(abs(zr - rr) <= 2 for rr in road_rows_r)
            road_near_l = any(abs(zr - rr) <= 2 for rr in road_rows_l)
            if wire_near and road_near_r:
                zc = zone_col_rr
                if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                    return (pick_tool(), zc, zr)
            if wire_near and road_near_l:
                zc = zone_col_ll
                if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                    return (pick_tool(), zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads the map every step and reacts to current state.
    Strategy:
    - Place coal power plant near center-left if none exists.
    - Grow wire spine eastward from plant, then north/south.
    - Build a road column adjacent (east) to wire spine.
    - Place zones on both sides of the road, powered via wires.
    - Balance RES/COM/IND based on current counts.
    - React to powered_zones count to extend infrastructure further.
    """
    tm = obs.tile_map
    step = obs.step

    # Map center
    cx, cy = WORLD_W // 2, WORLD_H // 2

    # Current map state
    has_plant = np.any(plant_mask(tm))
    wm = wire_mask(tm)
    rm = road_mask(tm)
    em = empty_mask(tm)
    res_count = np.sum(res_mask(tm))
    com_count = np.sum(com_mask(tm))
    ind_count = np.sum(ind_mask(tm))

    # Phase 1: Place coal power plant if missing
    if not has_plant:
        # Place at cx-10, cy (well left of center so wire can go east)
        px, py = cx - 10, cy
        return (Tool.COALPOWER, px, py)

    # Find plant footprint to determine wire start
    pm = plant_mask(tm)
    plant_ys, plant_xs = np.where(pm)
    if len(plant_xs) == 0:
        return None
    # Approximate plant center from tiles
    pc_x = int(np.mean(plant_xs))
    pc_y = int(np.mean(plant_ys))
    # Plant is 4x4, center placed at cx-10 => footprint cols cx-12..cx-8
    # Wire should start just east of footprint: col = pc_x + 3
    wire_start_x = pc_x + 3
    wire_start_x = max(0, min(WORLD_W - 1, wire_start_x))

    # Wire spine: horizontal wire row at cy, then vertical extension
    wire_positions = list(zip(*np.where(wm)))  # (row, col)
    road_positions = list(zip(*np.where(rm)))   # (row, col)

    # Determine horizontal wire extent from plant eastward
    wire_row_cy = [c for (r, c) in wire_positions if r == cy]

    # Target: wire spine goes from wire_start_x east to cx+2
    wire_h_target = cx + 2

    # Phase 2: Build horizontal wire from plant to cx+2
    if not wire_row_cy or max(wire_row_cy) < wire_h_target:
        # Find rightmost wire on row cy
        if not wire_row_cy:
            start_c = wire_start_x
        else:
            start_c = max(wire_row_cy) + 1
        if start_c <= wire_h_target and start_c < WORLD_W:
            # Check it's either empty or wire
            if em[cy, start_c] or wm[cy, start_c]:
                return (Tool.WIRE, start_c, cy)

    # Phase 3: Build vertical wire spine at cx+1
    wire_spine_col = cx + 1
    wire_spine_rows = sorted([r for (r, c) in wire_positions if c == wire_spine_col])

    # Ensure horizontal wire connects to spine col
    if not wm[cy, wire_spine_col]:
        if em[cy, wire_spine_col]:
            return (Tool.WIRE, wire_spine_col, cy)

    if wm[cy, wire_spine_col]:
        # Extend spine vertically: target range cy-15 to cy+15
        target_min_r = cy - 15
        target_max_r = cy + 15

        if wire_spine_rows:
            min_r = min(wire_spine_rows)
            max_r = max(wire_spine_rows)
        else:
            min_r = max_r = cy

        # Extend downward first
        if max_r < target_max_r and max_r + 1 < WORLD_H:
            nr = max_r + 1
            if em[nr, wire_spine_col] or wm[nr, wire_spine_col]:
                return (Tool.WIRE, wire_spine_col, nr)
        # Extend upward
        if min_r > target_min_r and min_r - 1 >= 0:
            nr = min_r - 1
            if em[nr, wire_spine_col] or wm[nr, wire_spine_col]:
                return (Tool.WIRE, wire_spine_col, nr)

    # Phase 4: Build road column at cx+3 (east of wire spine at cx+1, gap at cx+2)
    road_col = cx + 3
    # For each row where wire spine exists, ensure road at road_col
    if wire_spine_rows:
        for r in wire_spine_rows:
            if 0 <= r < WORLD_H and not rm[r, road_col]:
                if em[r, road_col]:
                    return (Tool.ROAD, road_col, r)

    # Phase 5: Lateral wires from spine to west zone column
    # Zones west: center at cx-2, so we need wire at cx, cx-1 for those rows
    west_zone_col = cx - 2
    east_zone_col = cx + 6  # east of road at cx+3, zone center at cx+6

    if wire_spine_rows:
        for r in wire_spine_rows:
            # Wire laterally west from spine (cx+1) toward west zones (cx-2)
            for wc in [cx, cx - 1]:
                if 0 <= wc < WORLD_W:
                    if not wm[r, wc] and em[r, wc]:
                        return (Tool.WIRE, wc, r)
            # Road laterally east from road col (cx+3) toward east zones
            for rc in [cx + 4, cx + 5]:
                if 0 <= rc < WORLD_W:
                    if not rm[r, rc] and em[r, rc]:
                        return (Tool.ROAD, rc, r)

    # Phase 6: Place zones where road + wire coverage exists
    res_mask_arr = res_mask(tm)
    com_mask_arr = com_mask(tm)
    ind_mask_arr = ind_mask(tm)

    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def has_zone_nearby(cr, cc):
        r0, r1 = max(0, cr-2), min(WORLD_H, cr+3)
        c0, c1 = max(0, cc-2), min(WORLD_W, cc+3)
        return (np.any(res_mask_arr[r0:r1, c0:c1]) or
                np.any(com_mask_arr[r0:r1, c0:c1]) or
                np.any(ind_mask_arr[r0:r1, c0:c1]))

    def has_wire_nearby(cr, cc):
        r0, r1 = max(0, cr-2), min(WORLD_H, cr+3)
        c0, c1 = max(0, cc-2), min(WORLD_W, cc+3)
        return np.any(wm[r0:r1, c0:c1])

    def has_road_nearby(cr, cc):
        r0, r1 = max(0, cr-2), min(WORLD_H, cr+3)
        c0, c1 = max(0, cc-2), min(WORLD_W, cc+3)
        return np.any(rm[r0:r1, c0:c1])

    # Build zone candidates: west side (cx-2) and east side (cx+6)
    zone_rows = range(cy - 15, cy + 16, 3)

    # Determine zone type ratio
    total_zones = res_count + com_count + ind_count
    # Target: 50% res, 25% com, 25% ind (in zone-tile counts)

    for zr in zone_rows:
        for zc in [west_zone_col, east_zone_col]:
            if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                if has_wire_nearby(zr, zc) and has_road_nearby(zr, zc):
                    if not has_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                        # Choose zone type based on balance
                        if total_zones == 0:
                            return (Tool.RESIDENTIAL, zc, zr)
                        r_frac = res_count / max(total_zones, 1)
                        c_frac = com_count / max(total_zones, 1)
                        i_frac = ind_count / max(total_zones, 1)
                        if r_frac <= 0.5:
                            return (Tool.RESIDENTIAL, zc, zr)
                        elif c_frac < 0.25:
                            return (Tool.COMMERCIAL, zc, zr)
                        elif i_frac < 0.25:
                            return (Tool.INDUSTRIAL, zc, zr)
                        else:
                            return (Tool.RESIDENTIAL, zc, zr)

    # Phase 7: If population growing, extend wire spine further and add more zones
    if obs.city_pop > 100 or obs.powered_zones > 3:
        # Extend spine range
        extended_min = cy - 20
        extended_max = cy + 20
        if wire_spine_rows:
            min_r = min(wire_spine_rows)
            max_r = max(wire_spine_rows)
            if max_r < extended_max and max_r + 1 < WORLD_H:
                nr = max_r + 1
                if em[nr, wire_spine_col] or wm[nr, wire_spine_col]:
                    return (Tool.WIRE, wire_spine_col, nr)
            if min_r > extended_min and min_r - 1 >= 0:
                nr = min_r - 1
                if em[nr, wire_spine_col] or wm[nr, wire_spine_col]:
                    return (Tool.WIRE, wire_spine_col, nr)

    # Phase 8: Add a second parallel road+wire for denser coverage
    if obs.city_pop > 300:
        wire_spine2_col = cx - 5
        wire_spine2_rows = sorted([r for (r, c) in wire_positions if c == wire_spine2_col])
        # Connect horizontally from plant to second spine
        if not wm[cy, wire_spine2_col] and em[cy, wire_spine2_col]:
            return (Tool.WIRE, wire_spine2_col, cy)
        # Extend second spine
        if wire_spine2_rows:
            s2_min = min(wire_spine2_rows)
            s2_max = max(wire_spine2_rows)
            if s2_max < cy + 12 and s2_max + 1 < WORLD_H:
                nr = s2_max + 1
                if em[nr, wire_spine2_col]:
                    return (Tool.WIRE, wire_spine2_col, nr)
            if s2_min > cy - 12 and s2_min - 1 >= 0:
                nr = s2_min - 1
                if em[nr, wire_spine2_col]:
                    return (Tool.WIRE, wire_spine2_col, nr)

    return None

def act(obs, state):
    """
    Improved policy: horizontal road/wire layout instead of vertical,
    with balanced R/C/I zones above and below the spine.
    Two coal plants from the start for reliable power.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    # Use state as a build queue
    if 'queue' not in state:
        state['queue'] = []
        state['built'] = set()

    # Center of operations - use upper-center area
    cx, cy = 60, 40

    # Layout:
    # Plant at (cx-15, cy)
    # Wire row at cy (horizontal spine)
    # Road row at cy+1 (below wire) and cy-1 (above wire)
    # Zones at cy+4 (below road) and cy-4 (above road), centers
    # Zone columns at cx-9, cx-3, cx+3, cx+9, cx+15, cx+21

    plant_cx, plant_cy = cx - 18, cy
    plant2_cx, plant2_cy = cx + 20, cy

    has_plant = np.any(pm)

    # Phase 0: Place first coal plant
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Phase 0b: Place second coal plant early
    if obs.step > 5:
        plant_positions = list(zip(*np.where(pm)))
        if len(plant_positions) < 18:  # plant tiles ~9 each
            # Check if second plant area is clear enough
            area_ok = True
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    rr, rc = plant2_cy + dr, plant2_cx + dc
                    if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                        if pm[rr, rc]:
                            area_ok = False  # already a plant here
                        # Allow overbuilding empty tiles
            if area_ok and not state.get('plant2_placed', False):
                # Only place if plant2 area mostly empty
                empty_count = sum(
                    1 for dr in range(-1, 2) for dc in range(-1, 2)
                    if 0 <= plant2_cy+dr < WORLD_H and 0 <= plant2_cx+dc < WORLD_W
                    and em[plant2_cy+dr, plant2_cx+dc]
                )
                if empty_count >= 7:
                    state['plant2_placed'] = True
                    return (Tool.COALPOWER, plant2_cx, plant2_cy)

    # Wire spine: horizontal row at cy, from plant edge to right
    wire_row = cy
    wire_start = plant_cx + 2  # just right of plant
    wire_end = plant2_cx - 2   # just left of second plant

    # Road rows above and below wire
    road_row_below = cy + 2
    road_row_above = cy - 2

    # Zone center rows
    zone_row_below = cy + 5
    zone_row_above = cy - 5

    # Zone columns (x positions for zone centers)
    zone_cols = [cx - 12, cx - 6, cx, cx + 6, cx + 12]

    # Build horizontal wire spine
    for wc in range(wire_start, wire_end + 1):
        if 0 <= wc < WORLD_W and 0 <= wire_row < WORLD_H:
            if em[wire_row, wc]:
                return (Tool.WIRE, wc, wire_row)

    # Build road rows
    for rc in range(wire_start - 2, wire_end + 3):
        if 0 <= rc < WORLD_W:
            # Below road
            if 0 <= road_row_below < WORLD_H and em[road_row_below, rc]:
                return (Tool.ROAD, rc, road_row_below)
            # Above road
            if 0 <= road_row_above < WORLD_H and em[road_row_above, rc]:
                return (Tool.ROAD, rc, road_row_above)

    # Build vertical wire connectors from spine to near zones
    for zc in zone_cols:
        # Connect wire from spine row toward zone rows (short connectors)
        for yr in range(wire_row + 1, zone_row_below - 1):
            if 0 <= yr < WORLD_H and 0 <= zc < WORLD_W:
                if em[yr, zc]:
                    return (Tool.WIRE, zc, yr)
        for yr in range(wire_row - 1, zone_row_above + 2, -1):
            if 0 <= yr < WORLD_H and 0 <= zc < WORLD_W:
                if em[yr, zc]:
                    return (Tool.WIRE, zc, yr)

    # Zone placement helpers
    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    res_positions = set(zip(*np.where(res_mask(tm))))
    com_positions = set(zip(*np.where(com_mask(tm))))
    ind_positions = set(zip(*np.where(ind_mask(tm))))
    all_zones = res_positions | com_positions | ind_positions

    res_count = len(res_positions) // 9 + 1
    com_count = len(com_positions) // 9 + 1
    ind_count = len(ind_positions) // 9 + 1

    def zone_exists_near(zr, zc):
        return any(abs(zr - pr) <= 2 and abs(zc - pc) <= 2 for (pr, pc) in all_zones)

    def pick_zone(idx):
        # Cycle: RES RES IND RES RES COM
        pattern = [Tool.RESIDENTIAL, Tool.RESIDENTIAL, Tool.INDUSTRIAL,
                   Tool.RESIDENTIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL]
        return pattern[idx % len(pattern)]

    # Place zones below road
    for i, zc in enumerate(zone_cols):
        zr = zone_row_below
        if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
            if not zone_exists_near(zr, zc) and zone_area_free(zr, zc):
                return (pick_zone(i), zc, zr)

    # Place zones above road
    for i, zc in enumerate(zone_cols):
        zr = zone_row_above
        if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
            if not zone_exists_near(zr, zc) and zone_area_free(zr, zc):
                return (pick_zone(i + 3), zc, zr)

    # Second tier of zones further out
    zone_row_below2 = cy + 11
    zone_row_above2 = cy - 11

    # Extend roads further out
    for rc in range(wire_start - 2, wire_end + 3):
        if 0 <= rc < WORLD_W:
            if 0 <= road_row_below2 < WORLD_H and em[road_row_below2, rc]:
                return (Tool.ROAD, rc, road_row_below2)
            if 0 <= road_row_above2 < WORLD_H and em[road_row_above2, rc]:
                return (Tool.ROAD, rc, road_row_above2)

    # Wire connectors to second tier
    for zc in zone_cols:
        for yr in range(zone_row_below, zone_row_below2 - 1):
            if 0 <= yr < WORLD_H and 0 <= zc < WORLD_W and em[yr, zc]:
                return (Tool.WIRE, zc, yr)
        for yr in range(zone_row_above, zone_row_above2 + 2, -1):
            if 0 <= yr < WORLD_H and 0 <= zc < WORLD_W and em[yr, zc]:
                return (Tool.WIRE, zc, yr)

    for i, zc in enumerate(zone_cols):
        zr = zone_row_below2
        if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
            if not zone_exists_near(zr, zc) and zone_area_free(zr, zc):
                return (pick_zone(i + 1), zc, zr)

    for i, zc in enumerate(zone_cols):
        zr = zone_row_above2
        if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
            if not zone_exists_near(zr, zc) and zone_area_free(zr, zc):
                return (pick_zone(i + 2), zc, zr)

    # Third tier expansion if pop growing
    if obs.city_pop > 100:
        zone_row_below3 = cy + 17
        zone_row_above3 = cy - 17
        extra_cols = [cx - 18, cx - 12, cx - 6, cx, cx + 6, cx + 12, cx + 18]

        for rc in range(wire_start - 2, wire_end + 3):
            if 0 <= rc < WORLD_W:
                if 0 <= road_row_below3 < WORLD_H and em[road_row_below3, rc] \
                   if (road_row_below3 := cy + 14) else False:
                    return (Tool.ROAD, rc, road_row_below3)

        for i, zc in enumerate(extra_cols):
            if 0 <= zc < WORLD_W:
                for zr in [zone_row_below3, zone_row_above3]:
                    if 0 <= zr < WORLD_H:
                        # Wire connector
                        mid_y = (wire_row + zr) // 2
                        if em[mid_y, zc]:
                            return (Tool.WIRE, zc, mid_y)
                        if not zone_exists_near(zr, zc) and zone_area_free(zr, zc):
                            return (pick_zone(i + 2), zc, zr)

    # Police station to reduce crime when populated
    if obs.city_pop > 300 and not state.get('police_placed', False):
        pc_x, pc_y = cx, cy + 8
        if em[pc_y, pc_x]:
            state['police_placed'] = True
            return (Tool.POLICESTATION, pc_x, pc_y)

    # Fire station
    if obs.city_pop > 300 and not state.get('fire_placed', False):
        fc_x, fc_y = cx - 6, cy - 8
        if em[fc_y, fc_x]:
            state['fire_placed'] = True
            return (Tool.FIRESTATION, fc_x, fc_y)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads current map state each step and decides next action.
    Layout: coal plant near center-left, horizontal wire spine, roads above/below,
    zones placed adjacent to roads. Expands based on what's actually on the map.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    all_zone_mask = resm | comm | indm

    # Center of map
    cx, cy = 20, WORLD_H // 2  # start left-ish

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        if com_count / t < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_nearby(zr, zc, radius=1):
        for dr in range(-radius, radius+1):
            for dc in range(-radius, radius+1):
                rr, rc = zr+dr, zc+dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    # --- Step 1: Place power plant if none ---
    if not np.any(pm):
        return (Tool.COALPOWER, cx, cy)

    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Wire spine row = plant center row
    wire_row = plant_cy
    wire_row = max(5, min(WORLD_H - 6, wire_row))

    road_row_above = wire_row - 2
    road_row_below = wire_row + 2
    zone_row_above = road_row_above - 2  # zones centered 2 above road
    zone_row_below = road_row_below + 2

    # Clamp
    road_row_above = max(2, min(WORLD_H - 3, road_row_above))
    road_row_below = max(2, min(WORLD_H - 3, road_row_below))
    zone_row_above = max(2, min(WORLD_H - 3, zone_row_above))
    zone_row_below = max(2, min(WORLD_H - 3, zone_row_below))

    # Determine how far to extend wire based on pop
    if obs.city_pop < 50:
        target_max = min(WORLD_W - 3, plant_cx + 20)
    elif obs.city_pop < 200:
        target_max = min(WORLD_W - 3, plant_cx + 35)
    elif obs.city_pop < 500:
        target_max = min(WORLD_W - 3, plant_cx + 55)
    else:
        target_max = min(WORLD_W - 3, plant_cx + 75)

    wire_start = plant_cx + 2  # start wire just right of plant

    # Read current wire/road state
    wire_cols_set = set(c for c in range(WORLD_W) if wm[wire_row, c])
    road_cols_above = set(c for c in range(WORLD_W) if rm[road_row_above, c])
    road_cols_below = set(c for c in range(WORLD_W) if rm[road_row_below, c])

    # --- Step 2: Start wire adjacent to plant if none ---
    if not wire_cols_set:
        for nc in range(plant_cx + 2, plant_cx + 6):
            if 0 <= nc < WORLD_W and 0 <= wire_row < WORLD_H:
                if em[wire_row, nc] or wm[wire_row, nc]:
                    return (Tool.WIRE, nc, wire_row)
        return None

    max_wc = max(wire_cols_set) if wire_cols_set else wire_start
    min_wc = min(wire_cols_set) if wire_cols_set else wire_start

    # --- Step 3: Extend wire rightward to target ---
    if max_wc < target_max:
        nc = max_wc + 1
        if 0 <= nc < WORLD_W and not pm[wire_row, nc]:
            return (Tool.WIRE, nc, wire_row)

    # --- Step 4: Fill roads above and below wire, column by column ---
    for wc in sorted(wire_cols_set):
        if wc not in road_cols_above and 0 <= road_row_above < WORLD_H:
            if em[road_row_above, wc]:
                return (Tool.ROAD, wc, road_row_above)
        if wc not in road_cols_below and 0 <= road_row_below < WORLD_H:
            if em[road_row_below, wc]:
                return (Tool.ROAD, wc, road_row_below)

    # --- Step 5: Place zones adjacent to roads ---
    # Place zones every 3 columns along the wire
    for wc in sorted(wire_cols_set):
        # Try zone above road
        if wc in road_cols_above:
            zr = zone_row_above
            zc = wc
            if not zone_nearby(zr, zc) and zone_area_ok(zr, zc):
                return (pick_tool(), zc, zr)

        # Try zone below road
        if wc in road_cols_below:
            zr = zone_row_below
            zc = wc
            if not zone_nearby(zr, zc) and zone_area_ok(zr, zc):
                return (pick_tool(), zc, zr)

    # --- Step 6: Place zones staggered (every 3 cols) for density ---
    for base in range(wire_start, max_wc + 1, 3):
        zc = base
        # Above
        if any(abs(zc - rc) <= 1 for rc in road_cols_above):
            zr = zone_row_above
            if not zone_nearby(zr, zc) and zone_area_ok(zr, zc):
                return (pick_tool(), zc, zr)
        # Below
        if any(abs(zc - rc) <= 1 for rc in road_cols_below):
            zr = zone_row_below
            if not zone_nearby(zr, zc) and zone_area_ok(zr, zc):
                return (pick_tool(), zc, zr)

    # --- Step 7: Second power plant if population high and only one plant ---
    plant_count = int(np.sum(pm)) // 9  # approx
    if obs.city_pop > 300 and plant_count < 2:
        px2 = plant_cx
        py2 = plant_cy + 14
        py2 = max(2, min(WORLD_H - 3, py2))
        area_ok = all(
            em[py2 + dr, px2 + dc]
            for dr in [-1, 0, 1] for dc in [-1, 0, 1]
            if 0 <= py2 + dr < WORLD_H and 0 <= px2 + dc < WORLD_W
        )
        if area_ok:
            return (Tool.COALPOWER, px2, py2)

    # --- Step 8: Second corridor if pop warrants ---
    if obs.city_pop > 200:
        wire_row2 = wire_row + 12
        wire_row2 = max(5, min(WORLD_H - 6, wire_row2))
        road_row2a = max(2, wire_row2 - 2)
        road_row2b = min(WORLD_H - 3, wire_row2 + 2)
        zone_row2a = max(2, road_row2a - 2)
        zone_row2b = min(WORLD_H - 3, road_row2b + 2)

        wire_cols2 = set(c for c in range(WORLD_W) if wm[wire_row2, c])
        road_cols2a = set(c for c in range(WORLD_W) if rm[road_row2a, c])
        road_cols2b = set(c for c in range(WORLD_W) if rm[road_row2b, c])

        if not wire_cols2:
            # Connect via vertical wire from main spine
            for wr in range(min(wire_row, wire_row2), max(wire_row, wire_row2) + 1):
                if 0 <= wr < WORLD_H:
                    col = plant_cx + 2
                    if 0 <= col < WORLD_W:
                        if em[wr, col] or wm[wr, col]:
                            return (Tool.WIRE, col, wr)
        else:
            max_wc2 = max(wire_cols2)
            if max_wc2 < target_max:
                nc = max_wc2 + 1
                if nc < WORLD_W and em[wire_row2, nc]:
                    return (Tool.WIRE, nc, wire_row2)

            for wc in sorted(wire_cols2):
                if wc not in road_cols2a:
                    if 0 <= road_row2a < WORLD_H and em[road_row2a, wc]:
                        return (Tool.ROAD, wc, road_row2a)
                if wc not in road_cols2b:
                    if 0 <= road_row2b < WORLD_H and em[road_row2b, wc]:
                        return (Tool.ROAD, wc, road_row2b)

            for wc in sorted(wire_cols2):
                if wc in road_cols2a:
                    zr, zc = zone_row2a, wc
                    if not zone_nearby(zr, zc) and zone_area_ok(zr, zc):
                        return (pick_tool(), zc, zr)
                if wc in road_cols2b:
                    zr, zc = zone_row2b, wc
                    if not zone_nearby(zr, zc) and zone_area_ok(zr, zc):
                        return (pick_tool(), zc, zr)

    # --- Step 9: Extend wire further if stalled ---
    if max_wc < WORLD_W - 4:
        nc = max_wc + 1
        if em[wire_row, nc]:
            return (Tool.WIRE, nc, wire_row)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map every step and decides next placement
    based on what's currently on the map. Uses state only for light phase tracking.

    Strategy:
    - Place coal power plant near center
    - Extend wire spine vertically from plant
    - Build road column adjacent to wire spine
    - Place zones (RES/COM/IND mix) flanking the road
    - Extend laterally with wires to power left-side zones
    - Add second plant + second cluster when pop grows
    - All decisions driven by scanning current tile_map
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    all_zone_mask = resm | comm | indm

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=5):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    # ---- Phase 1: place first power plant if none exists ----
    if not np.any(pm):
        return (Tool.COALPOWER, cx - 8, cy)

    # Locate existing plant centroid
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Main cluster column layout relative to plant
    wire_col = plant_cx + 4
    road_col = wire_col + 2
    left_zone_col = wire_col - 3
    right_zone_col = road_col + 3

    wire_col = max(2, min(WORLD_W - 3, wire_col))
    road_col = max(2, min(WORLD_W - 3, road_col))
    left_zone_col = max(2, min(WORLD_W - 3, left_zone_col))
    right_zone_col = max(2, min(WORLD_W - 3, right_zone_col))

    # Dynamic spine extent based on current population
    pop = obs.city_pop
    if pop < 50:
        spine_extent = 8
    elif pop < 150:
        spine_extent = 14
    elif pop < 350:
        spine_extent = 20
    elif pop < 600:
        spine_extent = 28
    else:
        spine_extent = 36

    target_min = max(1, cy - spine_extent)
    target_max = min(WORLD_H - 2, cy + spine_extent)

    # Read current wire and road spine state from map
    wire_rows_on_spine = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])
    road_rows_set = set(r for r in range(WORLD_H) if rm[r, road_col])

    # ---- Phase 2: seed wire adjacent to plant if none ----
    if not wire_rows_on_spine:
        for dy in range(0, 8):
            for nr in [plant_cy + dy, plant_cy - dy]:
                if 0 <= nr < WORLD_H:
                    if em[nr, wire_col]:
                        return (Tool.WIRE, wire_col, nr)
        return None

    min_wire_row = min(wire_rows_on_spine)
    max_wire_row = max(wire_rows_on_spine)

    # ---- Phase 3: Extend wire spine downward ----
    if max_wire_row < target_max:
        nr = max_wire_row + 1
        if nr < WORLD_H and not pm[nr, wire_col]:
            if em[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # ---- Phase 4: Extend wire spine upward ----
    if min_wire_row > target_min:
        nr = min_wire_row - 1
        if nr >= 0 and not pm[nr, wire_col]:
            if em[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # ---- Phase 5: Build road column adjacent to wire spine ----
    # Prioritize placing roads where wire already is present
    for r in wire_rows_on_spine:
        if 0 <= r < WORLD_H and 0 <= road_col < WORLD_W:
            if not rm[r, road_col] and em[r, road_col] and not pm[r, road_col]:
                return (Tool.ROAD, road_col, r)

    road_rows_list = sorted(road_rows_set)

    # ---- Phase 6: Lateral wires from spine toward left zones ----
    # For each wire row, extend wire leftward toward left_zone_col
    for wr in wire_rows_on_spine:
        for wc in range(wire_col - 1, max(left_zone_col - 3, 0), -1):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc]:
                    break  # already wired this row
                if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc]:
                    break

    # ---- Phase 7: Place zones along the corridor ----
    zone_rows = list(range(max(1, target_min + 1), min(WORLD_H - 1, target_max), 3))

    for zr in zone_rows:
        # Check wire proximity from current spine
        wire_near = any(abs(zr - wr) <= 2 for wr in wire_rows_on_spine)
        road_near = any(abs(zr - rr) <= 2 for rr in road_rows_list)

        if wire_near and road_near:
            # Left zone
            zc = left_zone_col
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc, 5) and has_road_nearby(zr, zc, 5):
                    return (pick_tool(), zc, zr)
                elif has_wire_nearby(zr, zc, 5):
                    # Place zone anyway; road is close enough for future access
                    return (Tool.RESIDENTIAL, zc, zr)

            # Right zone
            zc = right_zone_col
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_road_nearby(zr, zc, 5) and has_wire_nearby(zr, zc, 6):
                    return (pick_tool(), zc, zr)

    # ---- Phase 8: Road extensions to right zones ----
    for rr in road_rows_list:
        for rc in range(road_col + 1, right_zone_col + 2):
            if 0 <= rc < WORLD_W:
                if rm[rr, rc]:
                    break
                if em[rr, rc] and not pm[rr, rc]:
                    return (Tool.ROAD, rc, rr)
                elif not em[rr, rc]:
                    break

    # ---- Phase 9: Wire extension to right zones ----
    for wr in wire_rows_on_spine:
        for wc in range(wire_col + 1, right_zone_col + 3):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc] and not rm[wr, wc]:
                    break

    # ---- Phase 10: Second power plant when population grows ----
    plant_count = int(np.sum(pm))
    if pop > 300 and plant_count < 9:
        px2, py2 = plant_cx + 22, plant_cy
        px2 = max(2, min(WORLD_W - 3, px2))
        py2 = max(2, min(WORLD_H - 3, py2))
        area_clear = all(
            em[py2 + dr, px2 + dc] or pm[py2 + dr, px2 + dc]
            for dr in [-1, 0, 1] for dc in [-1, 0, 1]
            if 0 <= py2 + dr < WORLD_H and 0 <= px2 + dc < WORLD_W
        )
        if area_clear:
            return (Tool.COALPOWER, px2, py2)

    # ---- Phase 11: Second cluster to the right ----
    if pop >= 150:
        wire_col2 = road_col + 10
        road_col2 = wire_col2 + 2
        left_zone_col2 = wire_col2 - 3
        right_zone_col2 = road_col2 + 3

        wire_col2 = max(2, min(WORLD_W - 3, wire_col2))
        road_col2 = max(2, min(WORLD_W - 3, road_col2))
        left_zone_col2 = max(2, min(WORLD_W - 3, left_zone_col2))
        right_zone_col2 = max(2, min(WORLD_W - 3, right_zone_col2))

        wire_rows2 = sorted([r for r in range(WORLD_H) if wm[r, wire_col2]])
        road_rows2 = set(r for r in range(WORLD_H) if rm[r, road_col2])

        if not wire_rows2:
            # Bridge wire from main spine to cluster2 at plant_cy row
            bridge_row = plant_cy
            for wc in range(wire_col + 1, wire_col2 + 1):
                if 0 <= wc < WORLD_W:
                    if wm[bridge_row, wc]:
                        continue
                    if em[bridge_row, wc] and not pm[bridge_row, wc]:
                        return (Tool.WIRE, wc, bridge_row)
                    else:
                        break
        else:
            min_wr2 = min(wire_rows2)
            max_wr2 = max(wire_rows2)

            if max_wr2 < target_max:
                nr = max_wr2 + 1
                if nr < WORLD_H and em[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > target_min:
                nr = min_wr2 - 1
                if nr >= 0 and em[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)

            for wr in wire_rows2:
                if wr not in road_rows2 and em[wr, road_col2]:
                    return (Tool.ROAD, road_col2, wr)

            road_rows2_list = sorted(road_rows2)
            for zr in zone_rows:
                wire_near2 = any(abs(zr - wr) <= 2 for wr in wire_rows2)
                road_near2 = any(abs(zr - rr) <= 2 for rr in road_rows2_list)
                if wire_near2 and road_near2:
                    for zc in [left_zone_col2, right_zone_col2]:
                        if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                            if has_wire_nearby(zr, zc, 6) and has_road_nearby(zr, zc, 5):
                                return (pick_tool(), zc, zr)

            for wr in wire_rows2:
                for wc in range(wire_col2 - 1, max(left_zone_col2 - 3, 0), -1):
                    if 0 <= wc < WORLD_W:
                        if wm[wr, wc]: break
                        if em[wr, wc] and not pm[wr, wc]: return (Tool.WIRE, wc, wr)
                        elif not em[wr, wc]: break

            for wr in wire_rows2:
                if wr not in road_rows2: continue
                for rc in range(road_col2 + 1, right_zone_col2 + 2):
                    if 0 <= rc < WORLD_W:
                        if rm[wr, rc]: break
                        if em[wr, rc] and not pm[wr, rc]: return (Tool.ROAD, rc, wr)
                        elif not em[wr, rc]: break

    # ---- Phase 12: Third cluster to the left ----
    if pop >= 350:
        wire_col3 = wire_col - 12
        road_col3 = wire_col3 - 2
        left_zone_col3 = road_col3 - 3
        right_zone_col3 = wire_col3 + 3

        wire_col3 = max(2, min(WORLD_W - 3, wire_col3))
        road_col3 = max(2, min(WORLD_W - 3, road_col3))
        left_zone_col3 = max(2, min(WORLD_W - 3, left_zone_col3))
        right_zone_col3 = max(2, min(WORLD_W - 3, right_zone_col3))

        wire_rows3 = sorted([r for r in range(WORLD_H) if wm[r, wire_col3]])
        road_rows3 = set(r for r in range(WORLD_H) if rm[r, road_col3])

        if not wire_rows3:
            bridge_row = plant_cy
            for wc in range(wire_col - 1, wire_col3 - 1, -1):
                if 0 <= wc < WORLD_W:
                    if wm[bridge_row, wc]: continue
                    if em[bridge_row, wc] and not pm[bridge_row, wc]:
                        return (Tool.WIRE, wc, bridge_row)
                    else:
                        break
        else:
            min_wr3 = min(wire_rows3)
            max_wr3 = max(wire_rows3)

            if max_wr3 < target_max:
                nr = max_wr3 + 1
                if nr < WORLD_H and em[nr, wire_col3]:
                    return (Tool.WIRE, wire_col3, nr)
            if min_wr3 > target_min:
                nr = min_wr3 - 1
                if nr >= 0 and em[nr, wire_col3]:
                    return (Tool.WIRE, wire_col3, nr)

            for wr in wire_rows3:
                if wr not in road_rows3 and em[wr, road_col3]:
                    return (Tool.ROAD, road_col3, wr)

            road_rows3_list = sorted(road_rows3)
            for zr in zone_rows:
                wire_near3 = any(abs(zr - wr) <= 2 for wr in wire_rows3)
                road_near3 = any(abs(zr - rr) <= 2 for rr in road_rows3_list)
                if wire_near3 and road_near3:
                    for zc in [right_zone_col3, left_zone_col3]:
                        if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                            if has_wire_nearby(zr, zc, 6) and has_road_nearby(zr, zc, 5):
                                return (pick_tool(), zc, zr)

            for wr in wire_rows3:
                for wc in range(wire_col3 + 1, min(right_zone_col3 + 3, WORLD_W)):
                    if 0 <= wc < WORLD_W:
                        if wm[wr, wc]: break
                        if em[wr, wc] and not pm[wr, wc]: return (Tool.WIRE, wc, wr)
                        elif not em[wr, wc]: break

            for wr in wire_rows3:
                if wr not in road_rows3: continue
                for rc in range(road_col3 - 1, max(left_zone_col3 - 2, 0), -1):
                    if 0 <= rc < WORLD_W:
                        if rm[wr, rc]: break
                        if em[wr, rc] and not pm[wr, rc]: return (Tool.ROAD, rc, wr)
                        elif not em[wr, rc]: break

    # ---- Phase 13: Fill extra zone columns near road for high pop ----
    if pop > 200:
        extra_cols = [left_zone_col - 6, right_zone_col + 6]
        for zc in extra_cols:
            zc = max(2, min(WORLD_W - 3, zc))
            for zr in zone_rows:
                if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                    if has_road_nearby(zr, zc, 7) and has_wire_nearby(zr, zc, 8):
                        return (Tool.RESIDENTIAL, zc, zr)

    return None

def act(obs, state):
    """
    Improved policy: horizontal road spine with zones on both sides,
    better zone mix, multiple power plants, wider coverage.
    Strategy:
    - Place coal power plant near center
    - Build horizontal road spine through center
    - Wire runs parallel to road
    - Place zones above and below the road spine
    - Better zone mix: 40% res, 35% com, 25% ind
    - Expand horizontally with more zones
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Phase 1: Place first coal power plant if missing
    if not np.any(pm):
        return (Tool.COALPOWER, cx - 15, cy - 5)

    # Find plant centroid
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Horizontal layout:
    # wire_row: horizontal wire spine just above road
    # road_row: horizontal road spine
    # zones above: zone_row_top (centers 3 rows above road)
    # zones below: zone_row_bot (centers 3 rows below road)

    road_row = cy          # horizontal road at center
    wire_row = cy - 1      # wire just above road
    zone_row_top = cy - 4  # zone centers above
    zone_row_bot = cy + 4  # zone centers below

    # Clamp
    road_row = max(1, min(WORLD_H - 2, road_row))
    wire_row = max(1, min(WORLD_H - 2, wire_row))
    zone_row_top = max(2, min(WORLD_H - 3, zone_row_top))
    zone_row_bot = max(2, min(WORLD_H - 3, zone_row_bot))

    # Horizontal extent based on population
    if obs.city_pop < 100:
        h_extent = 12
    elif obs.city_pop < 300:
        h_extent = 20
    elif obs.city_pop < 600:
        h_extent = 30
    else:
        h_extent = 40

    road_min_x = max(plant_cx + 3, cx - h_extent)
    road_max_x = min(WORLD_W - 2, cx + h_extent)

    # Phase 2: Connect wire from plant to wire spine row
    # First, place wire adjacent to plant going right
    # Then extend wire along wire_row
    wire_on_row = sorted([c for c in range(WORLD_W) if wm[wire_row, c]])
    road_on_row = sorted([c for c in range(WORLD_W) if rm[road_row, c]])

    # Connect plant to wire_row via vertical wire segment
    # plant is at plant_cy, plant_cx - build wire bridge
    if not wire_on_row:
        # Start wire next to plant
        start_c = plant_cx + 2
        start_r = plant_cy
        # Walk from plant row to wire_row
        if start_r == wire_row:
            if 0 <= start_c < WORLD_W and (em[wire_row, start_c] or wm[wire_row, start_c]):
                return (Tool.WIRE, start_c, wire_row)
        else:
            # Build vertical wire to connect
            step = 1 if wire_row > start_r else -1
            for r in range(start_r, wire_row + step, step):
                if 0 <= r < WORLD_H and 0 <= start_c < WORLD_W:
                    if not wm[r, start_c] and em[r, start_c]:
                        return (Tool.WIRE, start_c, r)
            # Also try placing on wire_row directly near plant
            for dc in range(0, 5):
                c = start_c + dc
                if 0 <= c < WORLD_W and em[wire_row, c]:
                    return (Tool.WIRE, c, wire_row)
        return None

    min_wire_c = min(wire_on_row)
    max_wire_c = max(wire_on_row)

    # Phase 3: Extend wire spine rightward
    if max_wire_c < road_max_x:
        nc = max_wire_c + 1
        if nc < WORLD_W and not pm[wire_row, nc] and (em[wire_row, nc] or wm[wire_row, nc]):
            return (Tool.WIRE, nc, wire_row)

    # Phase 4: Extend wire spine leftward
    if min_wire_c > road_min_x:
        nc = min_wire_c - 1
        if nc >= 0 and not pm[wire_row, nc] and (em[wire_row, nc] or wm[wire_row, nc]):
            return (Tool.WIRE, nc, wire_row)

    # Phase 5: Build road spine along road_row
    for c in wire_on_row:
        if 0 <= c < WORLD_W and 0 <= road_row < WORLD_H:
            if not rm[road_row, c] and em[road_row, c]:
                return (Tool.ROAD, c, road_row)

    # Helper functions
    all_zone_mask = resm | comm | indm

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        # Target: 40% res, 35% com, 25% ind
        if com_count / t < 0.35:
            return Tool.COMMERCIAL
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Phase 6: Place zones above and below road spine
    # Zone columns spaced every 3 tiles along the spine
    zone_cols = list(range(max(2, road_min_x + 1), min(WORLD_W - 2, road_max_x), 3))

    for zc in zone_cols:
        wire_near = any(abs(zc - wc) <= 2 for wc in wire_on_row)
        road_near = any(abs(zc - rc) <= 2 for rc in road_on_row)

        if wire_near and road_near:
            # Top zone
            zr = zone_row_top
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc) and has_road_nearby(zr, zc):
                    return (pick_tool(), zc, zr)

            # Bottom zone
            zr = zone_row_bot
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc) and has_road_nearby(zr, zc):
                    return (pick_tool(), zc, zr)

    # Phase 7: Vertical wires connecting spine to zones above/below
    for wc in wire_on_row:
        # Wire up to top zone row
        for wr in range(wire_row - 1, zone_row_top - 2, -1):
            if 0 <= wr < WORLD_H:
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not rm[wr, wc] and not pm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc]:
                    break

        # Wire down to bottom zone row
        for wr in range(wire_row + 1, zone_row_bot + 2):
            if 0 <= wr < WORLD_H:
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not rm[wr, wc] and not pm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc]:
                    break

    # Phase 8: Second coal plant if population growing
    if obs.city_pop > 300 and np.sum(pm) < 9:
        px2 = plant_cx + 20
        py2 = plant_cy
        if 2 <= py2 <= WORLD_H - 3 and 2 <= px2 <= WORLD_W - 3:
            if em[py2, px2]:
                return (Tool.COALPOWER, px2, py2)

    # Phase 9: Third coal plant for larger city
    if obs.city_pop > 700 and np.sum(pm) < 18:
        px3 = plant_cx - 20
        py3 = plant_cy
        if 2 <= py3 <= WORLD_H - 3 and 2 <= px3 <= WORLD_W - 3:
            if em[py3, px3]:
                return (Tool.COALPOWER, px3, py3)

    # Phase 10: Second road row above/below for more zone coverage
    if obs.city_pop > 400:
        road_row2 = cy - 8
        road_row3 = cy + 8
        for rrow in [road_row2, road_row3]:
            rrow = max(1, min(WORLD_H - 2, rrow))
            for c in wire_on_row:
                if 0 <= c < WORLD_W and 0 <= rrow < WORLD_H:
                    if not rm[rrow, c] and em[rrow, c]:
                        return (Tool.ROAD, c, rrow)

        # Extra zone rows further from center
        zone_row_top2 = cy - 11
        zone_row_bot2 = cy + 11
        road_on_row2 = [c for c in range(WORLD_W) if rm[max(1, cy-8), c]]
        road_on_row3 = [c for c in range(WORLD_W) if rm[min(WORLD_H-2, cy+8), c]]

        for zc in zone_cols:
            wire_near = any(abs(zc - wc) <= 2 for wc in wire_on_row)
            if wire_near:
                for zr, road_on in [(zone_row_top2, road_on_row2), (zone_row_bot2, road_on_row3)]:
                    zr2 = max(2, min(WORLD_H - 3, zr))
                    road_near = any(abs(zc - rc) <= 2 for rc in road_on)
                    if road_near:
                        if not zone_already_there(zr2, zc) and zone_area_ok(zr2, zc):
                            if has_wire_nearby(zr2, zc, 6) and has_road_nearby(zr2, zc, 4):
                                return (pick_tool(), zc, zr2)

    # Phase 11: Police/fire stations for larger cities
    if obs.city_pop > 500:
        # Place a police station near center
        ps_x, ps_y = cx + 5, cy + 8
        if 1 <= ps_y <= WORLD_H - 2 and 1 <= ps_x <= WORLD_W - 2:
            if em[ps_y, ps_x]:
                return (Tool.POLICESTATION, ps_x, ps_y)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder v2.
    Key changes from parent:
    - More structured grid layout: roads every 4 tiles, wires along road edges
    - Better zone placement: prefer positions with both road AND wire neighbors
    - Place second coal plant earlier and connect it
    - Build cross-streets more aggressively for denser zone coverage
    - Use distance-from-center priority for zone placement
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Central cluster anchor
    CX, CY = 60, 50

    # Step 1: Place coal power plant if none exists
    if not np.any(pm):
        return (Tool.COALPOWER, CX, CY)

    # Find plant center
    plant_rows, plant_cols = np.where(pm)
    pcx = int(np.mean(plant_cols))
    pcy = int(np.mean(plant_rows))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Grid layout:
    # Wires: columns every 4 tiles starting at pcx, rows pcx-1 and pcx+1
    # Roads: horizontal rows at pcy+2, pcy-2, cross streets at pcx+2, pcx-2, etc.

    # Wire spine: run along top and bottom of road corridors
    # Road grid: every 4 rows and every 8 cols

    # Build the desired wire and road targets based on current city size
    pop = obs.city_pop
    w_extent = min(28, 6 + pop // 15)
    h_extent = min(20, 5 + pop // 20)

    # Wire targets: vertical spine at pcx, horizontal at pcy-2
    wire_v_spine = [(pcx, y) for y in range(pcy - h_extent, pcy + h_extent + 1)]
    wire_h_spine = [(x, pcy - 2) for x in range(pcx - w_extent, pcx + w_extent + 1)]
    # Also wire along top of road rows to distribute power
    wire_h2 = [(x, pcy + 2) for x in range(pcx - w_extent, pcx + w_extent + 1)]
    # Vertical wires at every 4th column to branch to zones
    wire_branches = []
    for dx in range(-w_extent, w_extent + 1, 4):
        cx2 = pcx + dx
        for dy in range(-h_extent, h_extent + 1):
            wire_branches.append((cx2, pcy - 2 + dy))

    all_wire_targets = wire_v_spine + wire_h_spine + wire_h2

    power_map = pm | wm

    # Try to place wires connected to existing power
    for (wx, wy) in all_wire_targets:
        if not in_bounds(wx, wy):
            continue
        if bool(wm[wy, wx]) or bool(pm[wy, wx]):
            continue
        if bool(rm[wy, wx]):
            continue  # don't overwrite roads
        if not bool(em[wy, wx]):
            continue
        # Only place if adjacent to existing power
        adj_power = False
        for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = wx + ddx, wy + ddy
            if in_bounds(nx, ny) and bool(power_map[ny, nx]):
                adj_power = True
                break
        if adj_power:
            return (Tool.WIRE, wx, wy)

    # Road grid: horizontal roads at pcy+3, pcy-3, pcy+7, pcy-7...
    # Vertical roads at pcx+4, pcx-4, pcx+8, pcx-8...
    road_h_rows = []
    for dy in range(0, h_extent + 1, 4):
        road_h_rows.append(pcy + 3 + dy)
        road_h_rows.append(pcy - 3 - dy)

    road_v_cols = []
    for dx in range(0, w_extent + 1, 4):
        road_v_cols.append(pcx + 2 + dx)
        road_v_cols.append(pcx - 2 - dx)

    road_targets = []
    for ry in road_h_rows:
        for rx in range(pcx - w_extent, pcx + w_extent + 1):
            road_targets.append((rx, ry))
    for rx in road_v_cols:
        for ry in range(pcy - h_extent - 3, pcy + h_extent + 4):
            road_targets.append((rx, ry))

    # Sort road targets by distance from center
    road_targets = sorted(road_targets, key=lambda p: abs(p[0] - pcx) + abs(p[1] - pcy))

    for (rx, ry) in road_targets:
        if not in_bounds(rx, ry):
            continue
        if bool(rm[ry, rx]) or bool(pm[ry, rx]) or bool(wm[ry, rx]):
            continue
        if not bool(em[ry, rx]):
            continue
        # Place if adjacent to existing road or near plant
        adj_ok = False
        for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = rx + ddx, ry + ddy
            if in_bounds(nx, ny) and (bool(rm[ny, nx]) or bool(pm[ny, nx])):
                adj_ok = True
                break
        if adj_ok:
            return (Tool.ROAD, rx, ry)

    # Place zones near roads and power
    # Build neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_mask = resm | comm | indm
    cand = em & nbr_road & nbr_power
    cand[0:2, :] = False
    cand[WORLD_H - 2:, :] = False
    cand[:, 0:2] = False
    cand[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        # Sort candidates by closeness to center
        dists = np.abs(cxs - CX) + np.abs(cys - CY)
        order = np.argsort(dists)
        for idx in order[:80]:
            zx, zy = int(cxs[idx]), int(cys[idx])
            ok = True
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    ny2, nx2 = zy + dr, zx + dc
                    if not in_bounds(nx2, ny2):
                        ok = False
                        break
                    if not (bool(em[ny2, nx2]) or bool(zone_mask[ny2, nx2])):
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                return (pick_tool(), zx, zy)

    # Place second power plant if population warrants
    if obs.city_pop > 150 and int(np.sum(pm)) < 9:
        # Place in a different direction from first plant
        candidates_p2 = [
            (pcx + 15, pcy),
            (pcx - 15, pcy),
            (pcx, pcy + 12),
            (pcx, pcy - 12),
            (pcx + 10, pcy + 10),
        ]
        for p2x, p2y in candidates_p2:
            p2x = max(2, min(WORLD_W - 3, p2x))
            p2y = max(2, min(WORLD_H - 3, p2y))
            if bool(em[p2y, p2x]):
                return (Tool.COALPOWER, p2x, p2y)

    # Services
    if obs.city_pop > 150:
        for fx, fy in [(CX + 6, CY - 10), (CX - 6, CY + 10)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 350:
        for fx, fy in [(CX + 6, CY + 10), (CX - 6, CY - 10)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.POLICESTATION, fx, fy)

    # Fallback: extend wire from frontier
    wys2, wxs2 = np.where(wm)
    if len(wxs2) > 0:
        k3 = int(obs.step * 7) % len(wxs2)
        wx2, wy2 = int(wxs2[k3]), int(wys2[k3])
        for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = wx2 + ddx, wy2 + ddy
            if in_bounds(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                return (Tool.WIRE, nx, ny)

    # Fallback: extend road from frontier
    rys2, rxs2 = np.where(rm)
    if len(rxs2) > 0:
        k2 = int(obs.step * 11) % len(rxs2)
        rx2, ry2 = int(rxs2[k2]), int(rys2[k2])
        for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = rx2 + ddx, ry2 + ddy
            if in_bounds(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                return (Tool.ROAD, nx, ny)

    return None

def act(obs, state):
    """
    Variation: Build a horizontal road/wire layout instead of vertical.
    Use a wire row (horizontal spine) with road rows above and below,
    and place zones in rows further out. Mix res/com/ind more aggressively.
    Also start with two clusters side by side from the beginning.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    # Use state to track build queue
    if 'queue' not in state:
        state['queue'] = []
        state['built'] = set()

    # Center of map
    cx, cy = 60, 50

    has_plant = np.any(pm)
    has_wire = np.any(wm)
    has_road = np.any(rm)

    # Phase 1: Place coal power plant at left side
    plant_cx, plant_cy = cx - 20, cy
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Gather tile info
    wire_positions = set(zip(*np.where(wm))) if has_wire else set()
    road_positions = set(zip(*np.where(rm))) if has_road else set()
    res_positions = set(zip(*np.where(res_mask(tm))))
    com_positions = set(zip(*np.where(com_mask(tm))))
    ind_positions = set(zip(*np.where(ind_mask(tm))))
    all_zones = res_positions | com_positions | ind_positions

    res_count = len(res_positions)
    com_count = len(com_positions)
    ind_count = len(ind_positions)

    # Horizontal layout:
    # wire_row = cy (horizontal wire spine)
    # road_row_above = cy - 1
    # road_row_below = cy + 1
    # zone_row_above = cy - 4  (zones centered 4 rows above wire)
    # zone_row_below = cy + 4  (zones centered 4 rows below wire)

    wire_row = cy
    road_row_above = cy - 1
    road_row_below = cy + 1
    zone_row_above = cy - 4
    zone_row_below = cy + 4

    # Columns to span - start just right of plant
    wire_col_start = plant_cx + 3
    # Expand based on population
    base_cols = 15
    extra_cols = min(40, obs.city_pop // 10)
    wire_col_end = min(WORLD_W - 4, wire_col_start + base_cols + extra_cols)

    # Phase 2: Lay horizontal wire spine from plant outward
    wire_cols_in_row = sorted(c for (r, c) in wire_positions if r == wire_row)
    if not wire_cols_in_row:
        # Start wire adjacent to plant
        start_c = plant_cx + 2
        if 0 <= start_c < WORLD_W:
            return (Tool.WIRE, start_c, wire_row)
    else:
        max_wc = max(wire_cols_in_row)
        if max_wc < wire_col_end:
            nc = max_wc + 1
            if 0 <= nc < WORLD_W and (em[wire_row, nc] or wm[wire_row, nc]):
                return (Tool.WIRE, nc, wire_row)

    wire_cols_set = set(wire_cols_in_row) if wire_cols_in_row else set()

    # Phase 3: Lay road rows above and below the wire
    if wire_cols_in_row:
        road_above_cols = set(c for (r, c) in road_positions if r == road_row_above)
        for wc in wire_cols_in_row:
            if wc not in road_above_cols and 0 <= road_row_above < WORLD_H and 0 <= wc < WORLD_W:
                if em[road_row_above, wc]:
                    return (Tool.ROAD, wc, road_row_above)

        road_below_cols = set(c for (r, c) in road_positions if r == road_row_below)
        for wc in wire_cols_in_row:
            if wc not in road_below_cols and 0 <= road_row_below < WORLD_H and 0 <= wc < WORLD_W:
                if em[road_row_below, wc]:
                    return (Tool.ROAD, wc, road_row_below)

    # Helper: check if 3x3 zone area is free
    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def already_zone_nearby(zr, zc):
        return any(abs(zr - pr) <= 1 and abs(zc - pc) <= 1 for (pr, pc) in all_zones)

    def choose_zone_type(zr, zc):
        # Balance: 50% res, 25% com, 25% ind
        # Use position to vary type
        idx = (zc // 4) % 4
        if ind_count * 4 < res_count:
            return Tool.INDUSTRIAL
        elif com_count * 4 < res_count:
            return Tool.COMMERCIAL
        else:
            return Tool.RESIDENTIAL

    # Phase 4: Place zones in rows above and below road rows
    # Zones go every 4 columns (centers: wire_col_start+3, +7, +11, ...)
    if wire_cols_in_row:
        road_above_cols2 = set(c for (r, c) in road_positions if r == road_row_above)
        road_below_cols2 = set(c for (r, c) in road_positions if r == road_row_below)

        for zc in range(wire_col_start + 3, wire_col_end, 4):
            road_nearby_above = any(abs(zc - rc) <= 2 for rc in road_above_cols2)
            road_nearby_below = any(abs(zc - rc) <= 2 for rc in road_below_cols2)
            wire_nearby = any(abs(zc - wc) <= 1 for wc in wire_cols_set)

            if not wire_nearby:
                continue

            # Zone above road
            if road_nearby_above and 0 <= zone_row_above < WORLD_H and 0 <= zc < WORLD_W:
                if not already_zone_nearby(zone_row_above, zc) and zone_area_free(zone_row_above, zc):
                    tool = choose_zone_type(zone_row_above, zc)
                    return (tool, zc, zone_row_above)

            # Zone below road
            if road_nearby_below and 0 <= zone_row_below < WORLD_H and 0 <= zc < WORLD_W:
                if not already_zone_nearby(zone_row_below, zc) and zone_area_free(zone_row_below, zc):
                    tool = choose_zone_type(zone_row_below, zc)
                    return (tool, zc, zone_row_below)

    # Phase 5: Second horizontal cluster when population grows
    if obs.city_pop > 150:
        wire_row2 = cy + 12
        road_row2_above = wire_row2 - 1
        road_row2_below = wire_row2 + 1
        zone_row2_above = wire_row2 - 4
        zone_row2_below = wire_row2 + 4

        wire_cols_row2 = sorted(c for (r, c) in wire_positions if r == wire_row2)

        # Connect vertically from main wire at start column
        vert_col = wire_col_start
        # Lay vertical wire between wire_row and wire_row2
        for ry in range(wire_row + 1, wire_row2 + 1):
            if not wm[ry, vert_col] and em[ry, vert_col]:
                return (Tool.WIRE, vert_col, ry)

        if not wire_cols_row2:
            if 0 <= wire_row2 < WORLD_H and em[wire_row2, vert_col]:
                return (Tool.WIRE, vert_col, wire_row2)
        else:
            max_wc2 = max(wire_cols_row2)
            wire_col_end2 = min(WORLD_W - 4, wire_col_start + base_cols + extra_cols)
            if max_wc2 < wire_col_end2:
                nc = max_wc2 + 1
                if 0 <= nc < WORLD_W and (em[wire_row2, nc] or wm[wire_row2, nc]):
                    return (Tool.WIRE, nc, wire_row2)

            wire_cols_set2 = set(wire_cols_row2)

            # Roads
            road_above2_cols = set(c for (r, c) in road_positions if r == road_row2_above)
            for wc in wire_cols_row2:
                if wc not in road_above2_cols and 0 <= road_row2_above < WORLD_H:
                    if em[road_row2_above, wc]:
                        return (Tool.ROAD, wc, road_row2_above)

            road_below2_cols = set(c for (r, c) in road_positions if r == road_row2_below)
            for wc in wire_cols_row2:
                if wc not in road_below2_cols and 0 <= road_row2_below < WORLD_H:
                    if em[road_row2_below, wc]:
                        return (Tool.ROAD, wc, road_row2_below)

            road_above2_cols2 = set(c for (r, c) in road_positions if r == road_row2_above)
            road_below2_cols2 = set(c for (r, c) in road_positions if r == road_row2_below)

            for zc in range(wire_col_start + 3, wire_col_end2, 4):
                road_nearby_a = any(abs(zc - rc) <= 2 for rc in road_above2_cols2)
                road_nearby_b = any(abs(zc - rc) <= 2 for rc in road_below2_cols2)
                wire_near = any(abs(zc - wc) <= 1 for wc in wire_cols_set2)
                if not wire_near:
                    continue
                if road_nearby_a and 0 <= zone_row2_above < WORLD_H and 0 <= zc < WORLD_W:
                    if not already_zone_nearby(zone_row2_above, zc) and zone_area_free(zone_row2_above, zc):
                        tool = choose_zone_type(zone_row2_above, zc)
                        return (tool, zc, zone_row2_above)
                if road_nearby_b and 0 <= zone_row2_below < WORLD_H and 0 <= zc < WORLD_W:
                    if not already_zone_nearby(zone_row2_below, zc) and zone_area_free(zone_row2_below, zc):
                        tool = choose_zone_type(zone_row2_below, zc)
                        return (tool, zc, zone_row2_below)

    # Phase 6: Third cluster above center
    if obs.city_pop > 350:
        wire_row3 = cy - 12
        road_row3_above = wire_row3 - 1
        road_row3_below = wire_row3 + 1
        zone_row3_above = wire_row3 - 4
        zone_row3_below = wire_row3 + 4

        vert_col3 = wire_col_start
        for ry in range(wire_row3, wire_row - 1):
            if not wm[ry, vert_col3] and em[ry, vert_col3]:
                return (Tool.WIRE, vert_col3, ry)

        wire_cols_row3 = sorted(c for (r, c) in wire_positions if r == wire_row3)
        if not wire_cols_row3:
            if 0 <= wire_row3 < WORLD_H and em[wire_row3, vert_col3]:
                return (Tool.WIRE, vert_col3, wire_row3)
        else:
            max_wc3 = max(wire_cols_row3)
            wire_col_end3 = min(WORLD_W - 4, wire_col_start + base_cols + extra_cols)
            if max_wc3 < wire_col_end3:
                nc = max_wc3 + 1
                if 0 <= nc < WORLD_W and (em[wire_row3, nc] or wm[wire_row3, nc]):
                    return (Tool.WIRE, nc, wire_row3)

            wire_cols_set3 = set(wire_cols_row3)
            road_above3_cols = set(c for (r, c) in road_positions if r == road_row3_above)
            for wc in wire_cols_row3:
                if wc not in road_above3_cols and 0 <= road_row3_above < WORLD_H:
                    if em[road_row3_above, wc]:
                        return (Tool.ROAD, wc, road_row3_above)

            road_below3_cols = set(c for (r, c) in road_positions if r == road_row3_below)
            for wc in wire_cols_row3:
                if wc not in road_below3_cols and 0 <= road_row3_below < WORLD_H:
                    if em[road_row3_below, wc]:
                        return (Tool.ROAD, wc, road_row3_below)

            road_above3_cols2 = set(c for (r, c) in road_positions if r == road_row3_above)
            road_below3_cols2 = set(c for (r, c) in road_positions if r == road_row3_below)

            for zc in range(wire_col_start + 3, wire_col_end3, 4):
                road_nearby_a = any(abs(zc - rc) <= 2 for rc in road_above3_cols2)
                road_nearby_b = any(abs(zc - rc) <= 2 for rc in road_below3_cols2)
                wire_near = any(abs(zc - wc) <= 1 for wc in wire_cols_set3)
                if not wire_near:
                    continue
                if road_nearby_a and 0 <= zone_row3_above < WORLD_H and 0 <= zc < WORLD_W:
                    if not already_zone_nearby(zone_row3_above, zc) and zone_area_free(zone_row3_above, zc):
                        tool = choose_zone_type(zone_row3_above, zc)
                        return (tool, zc, zone_row3_above)
                if road_nearby_b and 0 <= zone_row3_below < WORLD_H and 0 <= zc < WORLD_W:
                    if not already_zone_nearby(zone_row3_below, zc) and zone_area_free(zone_row3_below, zc):
                        tool = choose_zone_type(zone_row3_below, zc)
                        return (tool, zc, zone_row3_below)

    # Phase 7: Add second coal plant if large enough
    if obs.city_pop > 600 and not state.get('plant2', False):
        p2x, p2y = plant_cx + 35, cy
        ok = True
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = p2y + dr, p2x + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W and not em[rr, rc]:
                    ok = False
        if ok:
            state['plant2'] = True
            return (Tool.COALPOWER, p2x, p2y)

    return None

def act(obs, state):
    """
    Improved city builder with:
    - Single central power plant + nuclear plant for more coverage
    - Grid road layout forming blocks
    - Balanced zone placement (more commercial/industrial)
    - Wire network covering all zones
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Single cluster centered at (60, 50) with grid layout
    CX, CY = 60, 50

    # Power plant positions - coal at center-left, nuclear at center-right
    COAL_X, COAL_Y = 42, 50
    NUC_X, NUC_Y = 78, 50

    plant_ys, plant_xs = np.where(pm)
    plant_list = list(zip(plant_xs.tolist(), plant_ys.tolist()))

    has_coal = any(abs(px - COAL_X) < 5 and abs(py - COAL_Y) < 5
                   for px, py in plant_list)
    has_nuc = any(abs(px - NUC_X) < 5 and abs(py - NUC_Y) < 5
                  for px, py in plant_list)

    # Phase 1: place power plants
    if not has_coal:
        return (Tool.COALPOWER, COAL_X, COAL_Y)
    if not has_nuc:
        return (Tool.NUCLEARPOWER, NUC_X, NUC_Y)

    # Count zones for balanced placement
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        # Target: 40% res, 30% com, 30% ind
        if ind_count / total_zones < 0.28:
            return Tool.INDUSTRIAL
        if com_count / total_zones < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Phase 2: build wire network
    # Horizontal wire spine at CY connecting both plants
    # Vertical branches at intervals
    wire_targets = []

    # Main horizontal spine from coal to nuclear
    for x in range(COAL_X - 2, NUC_X + 3):
        wire_targets.append((x, CY))

    # Vertical spines from horizontal at intervals
    for x in [COAL_X, COAL_X + 6, COAL_X + 12, CX, NUC_X - 12, NUC_X - 6, NUC_X]:
        for dy in range(-14, 15):
            wire_targets.append((x, CY + dy))

    for (wx, wy) in wire_targets:
        if not in_bounds(wx, wy):
            continue
        if bool(wm[wy, wx]) or bool(pm[wy, wx]):
            continue
        adj_power = False
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx2, ny2 = wx+ddx, wy+ddy
            if in_bounds(nx2, ny2) and (bool(pm[ny2, nx2]) or bool(wm[ny2, nx2])):
                adj_power = True
                break
        if adj_power and bool(em[wy, wx]):
            return (Tool.WIRE, wx, wy)

    # Phase 3: build grid road network
    # Horizontal roads at intervals of 4 from CY-12 to CY+12
    # Vertical roads at intervals of 4 from CX-18 to CX+18
    road_targets = []

    # Horizontal roads
    for ry_offset in range(-12, 13, 4):
        ry = CY + ry_offset
        for rx in range(COAL_X - 10, NUC_X + 11):
            road_targets.append((rx, ry))

    # Vertical roads
    for rx_offset in range(-18, 19, 4):
        rx = CX + rx_offset
        for ry in range(CY - 12, CY + 13):
            road_targets.append((rx, ry))

    # Seed roads adjacent to plants
    seed_roads = [
        (COAL_X + 2, COAL_Y - 2), (COAL_X + 2, COAL_Y + 2),
        (NUC_X - 2, NUC_Y - 2), (NUC_X - 2, NUC_Y + 2),
        (COAL_X + 2, COAL_Y), (NUC_X - 2, NUC_Y),
    ]
    road_targets = seed_roads + road_targets

    for (rx, ry) in road_targets:
        if not in_bounds(rx, ry):
            continue
        if bool(rm[ry, rx]):
            continue
        if bool(pm[ry, rx]) or bool(wm[ry, rx]):
            continue
        adj_road = False
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx2, ny2 = rx+ddx, ry+ddy
            if in_bounds(nx2, ny2) and bool(rm[ny2, nx2]):
                adj_road = True
                break
        adj_plant = False
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1),(2,0),(-2,0),(0,2),(0,-2)]:
            nx2, ny2 = rx+ddx, ry+ddy
            if in_bounds(nx2, ny2) and bool(pm[ny2, nx2]):
                adj_plant = True
                break
        if (adj_road or adj_plant) and bool(em[ry, rx]):
            return (Tool.ROAD, rx, ry)

    # Phase 4: place zones in grid blocks
    # Zones go in 3x3 cells between roads (road every 4 tiles, zones at offsets 1,2 within)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    power_source = wm | pm
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= power_source[sr0:sr1, sc0:sc1]

    zone_mask = resm | comm | indm
    cand = em & nbr_road & nbr_power
    cand[0:2, :] = False
    cand[WORLD_H-2:, :] = False
    cand[:, 0:2] = False
    cand[:, WORLD_W-2:] = False

    # Prefer zones in the planned cluster area
    cluster_cand = cand.copy()
    cluster_cand[:, :COAL_X-12] = False
    cluster_cand[:, NUC_X+12:] = False
    cluster_cand[:CY-14, :] = False
    cluster_cand[CY+14:, :] = False

    search_cand = cluster_cand if np.any(cluster_cand) else cand
    cys, cxs = np.where(search_cand)

    if len(cxs) > 0:
        key = int(obs.step * 17 + int(obs.city_pop * 3) + 1) % len(cxs)
        for offset in range(min(len(cxs), 120)):
            k = (key + offset * 11) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            ok = True
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    ny2, nx2 = zy + dr, zx + dc
                    if not in_bounds(nx2, ny2):
                        ok = False; break
                    tile_ok = bool(em[ny2, nx2]) or bool(zone_mask[ny2, nx2])
                    if not tile_ok:
                        ok = False; break
                if not ok:
                    break
            if ok:
                return (pick_tool(), zx, zy)

    # Phase 5: services
    if obs.city_pop > 150:
        for fx, fy in [(COAL_X + 4, COAL_Y - 8), (NUC_X - 4, NUC_Y + 8),
                       (CX - 6, CY - 10), (CX + 6, CY + 10)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 250:
        for fx, fy in [(CX - 6, CY + 10), (CX + 6, CY - 10)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.POLICESTATION, fx, fy)

    # Fallback: extend road
    rys, rxs = np.where(rm)
    if len(rxs) > 0:
        k2 = int(obs.step * 13) % len(rxs)
        rx2, ry2 = int(rxs[k2]), int(rys[k2])
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx2, ny2 = rx2+ddx, ry2+ddy
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wys, wxs = np.where(wm)
    if len(wxs) > 0:
        k3 = int(obs.step * 7) % len(wxs)
        wx2, wy2 = int(wxs[k3]), int(wys[k3])
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx2, ny2 = wx2+ddx, wy2+ddy
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder.
    Key differences from parent:
    - Simpler, more reliable wire/road connection logic
    - Zones placed directly adjacent to roads (not offset)
    - Power plant placed first, then wires extend from it step by step
    - Roads built parallel to wire spine, zones fill in between
    - Uses BFS-style frontier expansion tracked via state
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def inb(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Power plant location - fixed anchor
    PLANT_X, PLANT_Y = 20, 50

    # Step 1: Place power plant if none exists
    if not np.any(pm):
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    # Get plant center
    pys, pxs = np.where(pm)
    px = int(np.mean(pxs))
    py = int(np.mean(pys))

    wire_set = set(zip(map(int, np.where(wm)[0]), map(int, np.where(wm)[1])))
    road_set = set(zip(map(int, np.where(rm)[0]), map(int, np.where(rm)[1])))

    # Step 2: Extend horizontal wire spine from plant to the right
    # Wire runs along py row from px outward
    WIRE_END_X = 90
    # Find rightmost wire on spine row
    spine_wires = [c for (r, c) in wire_set if r == py]
    if spine_wires:
        max_wire_x = max(spine_wires)
    else:
        max_wire_x = px

    if max_wire_x < WIRE_END_X:
        nx = max_wire_x + 1
        # Skip if plant tile
        if inb(nx, py) and not pm[py, nx]:
            if not wm[py, nx]:
                return (Tool.WIRE, nx, py)

    # Step 3: Build road above and below spine
    # Road at py-4 and py+4, from px+2 to WIRE_END_X
    ROAD_START_X = px + 4
    ROAD_END_X = WIRE_END_X + 2

    road_top_y = py - 4
    road_bot_y = py + 4

    # Top road
    top_cols = [c for (r, c) in road_set if r == road_top_y and c >= ROAD_START_X]
    max_top = max(top_cols) if top_cols else ROAD_START_X - 1
    if max_top < ROAD_END_X:
        nc = max_top + 1
        if inb(nc, road_top_y) and not pm[road_top_y, nc]:
            return (Tool.ROAD, nc, road_top_y)

    # Bottom road
    bot_cols = [c for (r, c) in road_set if r == road_bot_y and c >= ROAD_START_X]
    max_bot = max(bot_cols) if bot_cols else ROAD_START_X - 1
    if max_bot < ROAD_END_X:
        nc = max_bot + 1
        if inb(nc, road_bot_y) and not pm[road_bot_y, nc]:
            return (Tool.ROAD, nc, road_bot_y)

    # Step 4: Add connector roads (vertical) every 6 columns
    for cx_v in range(ROAD_START_X, ROAD_END_X + 1, 6):
        for ry_v in range(road_top_y, road_bot_y + 1):
            if (ry_v, cx_v) not in road_set and inb(cx_v, ry_v) and not pm[ry_v, cx_v]:
                return (Tool.ROAD, cx_v, ry_v)

    # Step 5: Place zones adjacent to roads
    # Compute road neighbor mask
    road_arr = rm.copy()
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            nbr_road[r0:r1, c0:c1] |= road_arr[sr0:sr1, sc0:sc1]

    # Compute wire/plant neighbor mask (for power)
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not inb(nc, nr):
                    return False
                # Must be empty or already a zone tile
                if not em[nr, nc] and not resm[nr, nc] and not comm[nr, nc] and not indm[nr, nc]:
                    return False
        return True

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count + 1

    def pick_tool():
        if com_count / total_zones < 0.25:
            return Tool.COMMERCIAL
        if ind_count / total_zones < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Candidate zone positions: rows near roads (above top, below bot)
    zone_candidates = []
    for zr in [road_top_y - 2, road_top_y - 5, road_top_y - 8,
               road_bot_y + 2, road_bot_y + 5, road_bot_y + 8]:
        for zc in range(ROAD_START_X, ROAD_END_X + 1, 3):
            if 2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3:
                zone_candidates.append((zr, zc))

    for (zr, zc) in zone_candidates:
        if em[zr, zc] and nbr_road[zr, zc] and nbr_wire[zr, zc]:
            if zone_clear(zc, zr):
                return (pick_tool(), zc, zr)

    # Step 6: Also place zones between the two roads (belt between them)
    for zr in range(road_top_y + 1, road_bot_y):
        if zr == py:
            continue  # skip wire spine row
        for zc in range(ROAD_START_X, ROAD_END_X + 1, 4):
            if 2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3:
                if em[zr, zc] and nbr_road[zr, zc] and nbr_wire[zr, zc]:
                    if zone_clear(zc, zr):
                        return (pick_tool(), zc, zr)

    # Step 7: Second power plant once population grows
    if obs.city_pop > 500 and np.sum(pm) < 9:
        p2x, p2y = PLANT_X + 50, PLANT_Y
        if inb(p2x, p2y) and em[p2y, p2x]:
            return (Tool.COALPOWER, p2x, p2y)

    # Step 8: Wire to second plant if exists
    # Find any plant tiles not connected to main spine
    if np.sum(pm) > 9:
        # extend wire spine further or add branch
        spine2_x = max(spine_wires) if spine_wires else px
        if spine2_x < WORLD_W - 5:
            nx = spine2_x + 1
            if inb(nx, py) and not pm[py, nx] and not wm[py, nx]:
                return (Tool.WIRE, nx, py)

    # Step 9: Services
    if obs.city_pop > 200:
        fx, fy = px + 8, py - 12
        if inb(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 300:
        fx2, fy2 = px + 8, py + 12
        if inb(fx2, fy2) and em[fy2, fx2]:
            return (Tool.POLICESTATION, fx2, fy2)

    # Step 10: Reactive fill - scan for any empty tile near road+wire
    cand = em & nbr_road & nbr_wire
    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        # Iterate through candidates deterministically
        for i in range(min(50, len(cxs))):
            k = (obs.step * 13 + i * 7) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if 2 <= zy <= WORLD_H - 3 and 2 <= zx <= WORLD_W - 3:
                if zone_clear(zx, zy):
                    return (pick_tool(), zx, zy)

    # Step 11: Extend road network from existing frontier
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        k = obs.step % len(road_xs)
        rx, ry = int(road_xs[k]), int(road_ys[k])
        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx + dx, ry + dy
            if inb(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                # Only extend if it gets closer to wire spine
                if abs(ny2 - py) <= abs(ry - py) + 2:
                    return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy that reads tile_map each step.
    Places coal plant, extends wire spine, builds road, places zones.
    Adapts layout based on observed infrastructure each step.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    all_zones = resm | comm | indm

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    pop = obs.city_pop

    cx, cy = WORLD_W // 2, WORLD_H // 2

    # --- Phase 1: Place coal plant ---
    if not np.any(pm):
        return (Tool.COALPOWER, cx - 12, cy)

    # Find plant centroid
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Layout columns derived from plant position
    wire_col = plant_cx + 4
    wire_col = max(3, min(WORLD_W - 4, wire_col))
    road_col_r = wire_col + 3
    road_col_l = wire_col - 3
    road_col_r = max(3, min(WORLD_W - 4, road_col_r))
    road_col_l = max(3, min(WORLD_W - 4, road_col_l))
    zone_col_r = road_col_r + 3
    zone_col_l = road_col_l - 3
    zone_col_r = max(3, min(WORLD_W - 4, zone_col_r))
    zone_col_l = max(3, min(WORLD_W - 4, zone_col_l))

    # Spine extent based on population
    if pop < 50:
        spine_half = 8
    elif pop < 150:
        spine_half = 12
    elif pop < 400:
        spine_half = 18
    elif pop < 800:
        spine_half = 24
    else:
        spine_half = 30

    spine_top = max(1, plant_cy - spine_half)
    spine_bot = min(WORLD_H - 2, plant_cy + spine_half)

    # Current wire rows on spine column
    wire_rows = [r for r in range(WORLD_H) if wm[r, wire_col]]

    # --- Phase 2: Bootstrap wire adjacent to plant ---
    if not wire_rows:
        for dy in range(-2, 3):
            nr = plant_cy + dy
            if 0 <= nr < WORLD_H and 0 <= wire_col < WORLD_W:
                if not pm[nr, wire_col] and em[nr, wire_col]:
                    return (Tool.WIRE, wire_col, nr)
        return None

    min_wr = min(wire_rows)
    max_wr = max(wire_rows)

    # --- Phase 3: Extend wire spine downward ---
    if max_wr < spine_bot:
        nr = max_wr + 1
        if 0 <= nr < WORLD_H and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # --- Phase 4: Extend wire spine upward ---
    if min_wr > spine_top:
        nr = min_wr - 1
        if 0 <= nr < WORLD_H and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # --- Phase 5: Build left road column ---
    for r in wire_rows:
        if spine_top <= r <= spine_bot:
            if 0 <= road_col_l < WORLD_W and not rm[r, road_col_l] and em[r, road_col_l]:
                return (Tool.ROAD, road_col_l, r)

    # --- Phase 6: Build right road column ---
    for r in wire_rows:
        if spine_top <= r <= spine_bot:
            if 0 <= road_col_r < WORLD_W and not rm[r, road_col_r] and em[r, road_col_r]:
                return (Tool.ROAD, road_col_r, r)

    # Helper functions
    def zone_clear(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def zone_present(zr, zc):
        r0, r1 = max(0, zr - 2), min(WORLD_H, zr + 3)
        c0, c1 = max(0, zc - 2), min(WORLD_W, zc + 3)
        return np.any(all_zones[r0:r1, c0:c1])

    def wire_near(zr, zc, radius=4):
        r0, r1 = max(0, zr - radius), min(WORLD_H, zr + radius + 1)
        c0, c1 = max(0, zc - radius), min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def road_near(zr, zc, radius=4):
        r0, r1 = max(0, zr - radius), min(WORLD_H, zr + radius + 1)
        c0, c1 = max(0, zc - radius), min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        if ind_count < max(1, total_zones // 5):
            return Tool.INDUSTRIAL
        if com_count < max(1, total_zones // 4):
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Phase 7: Lateral wires to left zone column ---
    for wr in wire_rows:
        if spine_top <= wr <= spine_bot:
            # Extend wire leftward from wire_col to zone_col_l
            reached = False
            for wc in range(wire_col - 1, zone_col_l - 1, -1):
                if 0 <= wc < WORLD_W and wm[wr, wc]:
                    reached = True
                    break
            if not reached:
                for wc in range(wire_col - 1, zone_col_l - 1, -1):
                    if 0 <= wc < WORLD_W:
                        if wm[wr, wc]:
                            break
                        if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                            return (Tool.WIRE, wc, wr)
                        elif not em[wr, wc] and not rm[wr, wc]:
                            break

    # --- Phase 8: Lateral wires to right zone column ---
    for wr in wire_rows:
        if spine_top <= wr <= spine_bot:
            reached = False
            for wc in range(wire_col + 1, zone_col_r + 2):
                if 0 <= wc < WORLD_W and wm[wr, wc]:
                    reached = True
                    break
            if not reached:
                for wc in range(wire_col + 1, zone_col_r + 2):
                    if 0 <= wc < WORLD_W:
                        if wm[wr, wc]:
                            break
                        if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                            return (Tool.WIRE, wc, wr)
                        elif not em[wr, wc] and not rm[wr, wc]:
                            break

    # Zone placement rows spaced by 3
    zone_rows = list(range(max(2, spine_top + 1), min(WORLD_H - 2, spine_bot), 3))

    # --- Phase 9: Place zones ---
    for zr in zone_rows:
        # Check wire and road proximity
        if not wire_near(zr, wire_col, 3):
            continue

        # Left zone
        zc = zone_col_l
        if not zone_present(zr, zc) and zone_clear(zr, zc):
            if wire_near(zr, zc) and road_near(zr, zc):
                return (pick_tool(), zc, zr)

        # Right zone
        zc = zone_col_r
        if not zone_present(zr, zc) and zone_clear(zr, zc):
            if wire_near(zr, zc) and road_near(zr, zc):
                return (pick_tool(), zc, zr)

    # --- Phase 10: Second coal plant if city is large ---
    if pop > 300 and int(np.sum(pm)) < 18:
        px2 = plant_cx + 18
        py2 = plant_cy
        px2 = max(2, min(WORLD_W - 3, px2))
        py2 = max(2, min(WORLD_H - 3, py2))
        area_ok = True
        for dr in range(-2, 3):
            for dc in range(-2, 3):
                rr, rc = py2 + dr, px2 + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if not em[rr, rc] and not pm[rr, rc]:
                        area_ok = False
                else:
                    area_ok = False
        if area_ok:
            return (Tool.COALPOWER, px2, py2)

    # --- Phase 11: Extra outer zone columns when growing ---
    if pop > 150:
        outer_left = zone_col_l - 4
        outer_right = zone_col_r + 4
        for zc in [max(3, outer_left), min(WORLD_W - 4, outer_right)]:
            for zr in zone_rows:
                if not zone_present(zr, zc) and zone_clear(zr, zc):
                    if wire_near(zr, zc, 6) and road_near(zr, zc, 5):
                        return (Tool.RESIDENTIAL, zc, zr)

    # --- Phase 12: Horizontal roads connecting zone columns ---
    if pop > 80:
        for rr in wire_rows:
            if spine_top <= rr <= spine_bot:
                for rc in range(zone_col_l, zone_col_r + 1):
                    if 0 <= rc < WORLD_W and em[rr, rc] and not pm[rr, rc] and not rm[rr, rc]:
                        return (Tool.ROAD, rc, rr)

    # --- Phase 13: Fill extra zones near existing infra ---
    for zr in zone_rows:
        for zc in [zone_col_l, wire_col - 6, wire_col + 6, zone_col_r]:
            zc2 = max(3, min(WORLD_W - 4, zc))
            if not zone_present(zr, zc2) and zone_clear(zr, zc2):
                if wire_near(zr, zc2, 6) and road_near(zr, zc2, 5):
                    return (pick_tool(), zc2, zr)

    return None

def act(obs, state):
    """
    Improved policy: horizontal road spine with vertical zone columns.
    Power plant left side, wire runs horizontally, roads run vertically,
    zones placed on both sides of vertical roads.
    This creates a grid-like city rather than vertical spine layout.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    has_plant = np.any(pm)

    # Place coal power plant first
    if not has_plant:
        return (Tool.COALPOWER, 20, 50)

    plant_rows, plant_cols = np.where(pm)
    pcx = int(np.mean(plant_cols))
    pcy = int(np.mean(plant_rows))

    res_count = max(1, int(np.sum(res_m)) // 9)
    com_count = max(1, int(np.sum(com_m)) // 9)
    ind_count = max(1, int(np.sum(ind_m)) // 9)

    def pick_zone():
        total = res_count + com_count + ind_count
        # Aim for 50% res, 25% com, 25% ind
        if com_count * 4 < total:
            return Tool.COMMERCIAL
        if ind_count * 4 < total:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    all_zone_m = res_m | com_m | ind_m

    def nearby_zone(zr, zc, radius=2):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(all_zone_m[r0:r1, c0:c1])

    # Layout: horizontal wire rows at fixed y positions, vertical road columns
    # Wire rows: pcy-2, pcy, pcy+2 (3 horizontal wire spines)
    # Road columns spaced every 6 cols starting from pcx+5
    # Zones placed between road columns

    wire_rows_targets = [pcy - 6, pcy, pcy + 6]
    wire_rows_targets = [max(1, min(WORLD_H - 2, r)) for r in wire_rows_targets]

    # Phase 2: build horizontal wire spines from plant
    wire_x_start = pcx + 2  # start just right of plant
    wire_x_end = min(WORLD_W - 2, pcx + 60)

    for wr in wire_rows_targets:
        # Find existing wire on this row
        wire_cols_on_row = [c for c in range(WORLD_W) if wm[wr, c]]
        if not wire_cols_on_row:
            # Place first wire adjacent to plant
            cx = pcx + 2
            if 0 <= cx < WORLD_W and 0 <= wr < WORLD_H:
                return (Tool.WIRE, cx, wr)
        else:
            max_wc = max(wire_cols_on_row)
            if max_wc < wire_x_end:
                nc = max_wc + 1
                if 0 <= nc < WORLD_W and (em[wr, nc] or wm[wr, nc]):
                    return (Tool.WIRE, nc, wr)

    # Phase 3: vertical road columns
    road_cols = list(range(wire_x_start + 3, wire_x_end, 6))
    road_cols = [c for c in road_cols if 2 <= c <= WORLD_W - 3]

    road_y_min = min(wire_rows_targets) - 3
    road_y_max = max(wire_rows_targets) + 3
    road_y_min = max(1, road_y_min)
    road_y_max = min(WORLD_H - 2, road_y_max)

    for rc in road_cols:
        for ry in range(road_y_min, road_y_max + 1):
            if not rm[ry, rc] and em[ry, rc]:
                return (Tool.ROAD, rc, ry)

    # Phase 4: place zones between road columns, centered on wire rows
    # Zone centers: between consecutive road cols, at wire row y values
    for i in range(len(road_cols) - 1):
        cl = road_cols[i]
        cr = road_cols[i + 1]
        zc = (cl + cr) // 2  # center between roads
        if not (2 <= zc <= WORLD_W - 3):
            continue
        for wr in wire_rows_targets:
            if not (2 <= wr <= WORLD_H - 3):
                continue
            if not nearby_zone(wr, zc, 2) and zone_area_free(wr, zc):
                return (pick_zone(), zc, wr)

    # Phase 4b: zones to the right of rightmost road col
    if road_cols:
        rc_last = road_cols[-1]
        zc_right = rc_last + 3
        if 2 <= zc_right <= WORLD_W - 3:
            for wr in wire_rows_targets:
                if 2 <= wr <= WORLD_H - 3:
                    if not nearby_zone(wr, zc_right, 2) and zone_area_free(wr, zc_right):
                        return (pick_zone(), zc_right, wr)

        # Zones to the left of leftmost road col
        rc_first = road_cols[0]
        zc_left = rc_first - 3
        if 2 <= zc_left <= WORLD_W - 3:
            for wr in wire_rows_targets:
                if 2 <= wr <= WORLD_H - 3:
                    if not nearby_zone(wr, zc_left, 2) and zone_area_free(wr, zc_left):
                        return (pick_zone(), zc_left, wr)

    # Phase 5: expand wire span when city grows
    if obs.city_pop > 200:
        wire_x_end2 = min(WORLD_W - 2, pcx + 90)
        extra_wire_rows = [pcy - 12, pcy + 12]
        extra_wire_rows = [max(1, min(WORLD_H - 2, r)) for r in extra_wire_rows]

        # Bridge extra wire rows horizontally
        for wr in extra_wire_rows:
            wire_cols_on_row = [c for c in range(WORLD_W) if wm[wr, c]]
            if not wire_cols_on_row:
                cx = pcx + 2
                if 0 <= cx < WORLD_W:
                    return (Tool.WIRE, cx, wr)
            else:
                max_wc = max(wire_cols_on_row)
                if max_wc < wire_x_end2:
                    nc = max_wc + 1
                    if 0 <= nc < WORLD_W and (em[wr, nc] or wm[wr, nc]):
                        return (Tool.WIRE, nc, wr)

        # Extra road columns
        extra_road_cols = list(range(wire_x_start + 3, wire_x_end2, 6))
        extra_road_cols = [c for c in extra_road_cols if 2 <= c <= WORLD_W - 3 and c not in road_cols]
        road_y_min2 = min(extra_wire_rows + wire_rows_targets) - 3
        road_y_max2 = max(extra_wire_rows + wire_rows_targets) + 3
        road_y_min2 = max(1, road_y_min2)
        road_y_max2 = min(WORLD_H - 2, road_y_max2)

        for rc in extra_road_cols:
            for ry in range(road_y_min2, road_y_max2 + 1):
                if not rm[ry, rc] and em[ry, rc]:
                    return (Tool.ROAD, rc, ry)

        # Zones for extra rows
        all_wire_rows = wire_rows_targets + extra_wire_rows
        all_road_cols = sorted(set(road_cols + extra_road_cols))
        for i in range(len(all_road_cols) - 1):
            cl = all_road_cols[i]
            cr = all_road_cols[i + 1]
            zc = (cl + cr) // 2
            if not (2 <= zc <= WORLD_W - 3):
                continue
            for wr in extra_wire_rows:
                if not (2 <= wr <= WORLD_H - 3):
                    continue
                if not nearby_zone(wr, zc, 2) and zone_area_free(wr, zc):
                    return (pick_zone(), zc, wr)

    # Phase 6: second power plant when large
    if obs.city_pop > 400 and not state.get("plant2", False):
        px2 = pcx + 40
        py2 = pcy
        px2 = max(2, min(WORLD_W - 3, px2))
        py2 = max(2, min(WORLD_H - 3, py2))
        clear = all(
            0 <= py2 + dr < WORLD_H and 0 <= px2 + dc < WORLD_W and em[py2 + dr, px2 + dc]
            for dr in [-1, 0, 1] for dc in [-1, 0, 1]
        )
        if clear:
            state["plant2"] = True
            return (Tool.COALPOWER, px2, py2)

    # Phase 7: connect wire rows vertically near plant to ensure connectivity
    # Draw a vertical wire connector along pcx+2 between all wire rows
    vc = pcx + 2
    if 0 <= vc < WORLD_W:
        all_target_rows = sorted(wire_rows_targets)
        if all_target_rows:
            for ry in range(all_target_rows[0], all_target_rows[-1] + 1):
                if 0 <= ry < WORLD_H and not wm[ry, vc] and em[ry, vc]:
                    return (Tool.WIRE, vc, ry)

    return None

def act(obs, state):
    """
    Closed-loop policy: each step reads the current map and decides what to place next.
    Strategy:
    1. Ensure a coal power plant exists near center.
    2. Extend wires from the plant toward zones (closed-loop: follow existing wire/plant).
    3. Extend roads along a vertical corridor adjacent to wires.
    4. Place zones (RES, COM, IND mix) adjacent to existing zones or roads.
    """
    tm = obs.tile_map
    cx, cy = WORLD_W // 2, WORLD_H // 2

    # --- Phase 0: Place coal power plant if none exists ---
    plants = plant_mask(tm)
    if not plants.any():
        return (Tool.COALPOWER, cx, cy)

    # Find plant location (use centroid of plant tiles)
    py_arr, px_arr = np.where(plants)
    px_c = int(px_arr.mean())
    py_c = int(py_arr.mean())

    # --- Phase 1: Extend wires from plant outward (vertical corridor) ---
    # Wire column is cx (same as plant x)
    wires = wire_mask(tm)
    emp = empty_mask(tm)

    # Find furthest wire extent above and below plant
    wire_col_mask = wires[:, cx]
    if wire_col_mask.any():
        wire_ys = np.where(wire_col_mask)[0]
        wire_top = int(wire_ys.min())
        wire_bot = int(wire_ys.max())
    else:
        wire_top = py_c
        wire_bot = py_c

    # Extend wire if not reaching desired range (cy-12 to cy+12)
    desired_top = max(2, cy - 15)
    desired_bot = min(97, cy + 15)

    if wire_top > desired_top:
        # Try to place wire just above current top
        ny = wire_top - 1
        if 0 <= ny < WORLD_H and emp[ny, cx]:
            return (Tool.WIRE, cx, ny)
        elif 0 <= ny < WORLD_H:
            return (Tool.WIRE, cx, ny)  # auto-bulldoze handles it

    if wire_bot < desired_bot:
        ny = wire_bot + 1
        if 0 <= ny < WORLD_H:
            return (Tool.WIRE, cx, ny)

    # --- Phase 2: Extend roads adjacent to wires (road column = cx+1) ---
    road_col = cx + 1
    roads = road_mask(tm)
    road_col_mask = roads[:, road_col]

    if road_col_mask.any():
        road_ys = np.where(road_col_mask)[0]
        road_top = int(road_ys.min())
        road_bot = int(road_ys.max())
    else:
        road_top = cy
        road_bot = cy
        # seed road at center
        return (Tool.ROAD, road_col, cy)

    if road_top > desired_top + 1:
        ny = road_top - 1
        if 0 <= ny < WORLD_H:
            return (Tool.ROAD, road_col, ny)

    if road_bot < desired_bot - 1:
        ny = road_bot + 1
        if 0 <= ny < WORLD_H:
            return (Tool.ROAD, road_col, ny)

    # --- Phase 3: Also build road on left side of plant (cx-1) ---
    left_road_col = cx - 1
    left_road_mask = roads[:, left_road_col]
    if not left_road_mask.any():
        return (Tool.ROAD, left_road_col, cy)
    else:
        lroad_ys = np.where(left_road_mask)[0]
        l_top = int(lroad_ys.min())
        l_bot = int(lroad_ys.max())
        if l_top > desired_top + 1:
            return (Tool.ROAD, left_road_col, l_top - 1)
        if l_bot < desired_bot - 1:
            return (Tool.ROAD, left_road_col, l_bot + 1)

    # --- Phase 4: Place zones reactively ---
    # Zones on right side (cx+3): residential
    # Zones on left side (cx-3): mix of commercial and industrial
    res = res_mask(tm)
    com = com_mask(tm)
    ind = ind_mask(tm)

    # Helper: find empty 3x3 center near road
    def find_zone_spot(col, zone_mask_arr, offset=3):
        """Find y positions along the road where we can place a zone center."""
        # Zone center at (col, y): needs y in [1,98], col in [1,118]
        if not (1 <= col <= 118):
            return None
        # Look for road tiles nearby
        road_near = roads[:, col - 1] | roads[:, col + 1] if (0 <= col-1 and col+1 < WORLD_W) else roads[:, col]
        # Also check the road columns we built
        for road_c in [road_col, left_road_col]:
            if abs(road_c - col) <= 2 and 0 <= road_c < WORLD_W:
                road_near = road_near | roads[:, road_c]

        # Find y candidates: near existing zones or roads
        zone_exists = zone_mask_arr.any(axis=1)  # rows with any zone

        candidates = []
        for y in range(2, WORLD_H - 2):
            if not road_near[y]:
                continue
            # Check 3x3 area is roughly empty (allow auto-bulldoze but prefer empty)
            region = tm[y-1:y+2, col-1:col+2]
            # Count non-empty tiles (not strictly empty but don't overwrite plant/road)
            plant_in_region = plants[y-1:y+2, col-1:col+2].any()
            road_in_region = roads[y-1:y+2, col-1:col+2].any()
            wire_in_region = wires[y-1:y+2, col-1:col+2].any()
            if plant_in_region or road_in_region or wire_in_region:
                continue
            candidates.append(y)
        return candidates

    # Right side: residential zones at cx+4
    right_col = cx + 4
    r_candidates = find_zone_spot(right_col, res)
    if r_candidates:
        # Pick the one with most road-neighbors or least zones nearby
        # Use step-based selection for variety
        r_candidates_filtered = []
        for y in r_candidates:
            if not res[y-1:y+2, right_col-1:right_col+2].any():
                r_candidates_filtered.append(y)
        cands = r_candidates_filtered if r_candidates_filtered else r_candidates
        # Pick based on distance from existing res zones
        if res.any():
            res_ys, res_xs = np.where(res)
            # Find y with minimum distance to existing zone (to cluster)
            best_y = min(cands, key=lambda y: min(abs(y - ry) for ry in res_ys))
            # But avoid placing too close
            too_close = [y for y in cands if any(abs(y - ry) < 4 and abs(right_col - rx) < 4
                                                   for ry, rx in zip(res_ys, res_xs))]
            far_enough = [y for y in cands if y not in too_close]
            if far_enough:
                # Place nearest to existing cluster edge
                best_y = min(far_enough, key=lambda y: min(abs(y - ry) for ry in res_ys))
            else:
                best_y = cands[obs.step % len(cands)]
            return (Tool.RESIDENTIAL, right_col, best_y)
        else:
            return (Tool.RESIDENTIAL, right_col, cands[0])

    # Left side: commercial and industrial alternating
    left_col = cx - 4
    l_candidates = find_zone_spot(left_col, com)
    if l_candidates:
        # Alternate between commercial and industrial
        zone_type = Tool.COMMERCIAL if (obs.step // 3) % 2 == 0 else Tool.INDUSTRIAL
        # Filter out spots too close to existing zones
        all_zones = res | com | ind
        filtered = [y for y in l_candidates
                    if not all_zones[max(0,y-3):min(WORLD_H,y+4),
                                      max(0,left_col-3):min(WORLD_W,left_col+4)].any()]
        if filtered:
            return (zone_type, left_col, filtered[0])
        elif l_candidates:
            return (zone_type, left_col, l_candidates[obs.step % len(l_candidates)])

    # Further right column
    far_right = cx + 8
    fr_candidates = find_zone_spot(far_right, res)
    # Need road there too
    if not roads[:, far_right - 1].any() and not roads[:, far_right + 1].any():
        # Extend horizontal road from road_col to far_right
        for rx in range(road_col + 1, far_right):
            if emp[cy, rx]:
                return (Tool.ROAD, rx, cy)
            elif not roads[cy, rx]:
                return (Tool.ROAD, rx, cy)
    if fr_candidates:
        all_zones = res | com | ind
        filtered = [y for y in fr_candidates
                    if not all_zones[max(0,y-3):min(WORLD_H,y+4),
                                      max(0,far_right-3):min(WORLD_W,far_right+4)].any()]
        if filtered:
            return (Tool.RESIDENTIAL, far_right, filtered[0])

    # Fallback: place road extensions or more wires to power far zones
    # Check if any zones lack power (heuristic: place more wire horizontally)
    if obs.powered_zones < (res | com | ind).sum() // 9 + 1:
        # Add horizontal wire from plant to right
        for wx in range(cx + 1, min(cx + 10, WORLD_W - 1)):
            if not wires[cy, wx] and not plants[cy, wx]:
                if not roads[cy, wx]:
                    return (Tool.WIRE, wx, cy)

    # Final fallback: extend residential adjacent to any existing residential
    if res.any():
        nbr = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        nbr[1:, :] |= res[:-1, :]
        nbr[:-1, :] |= res[1:, :]
        nbr[:, 1:] |= res[:, :-1]
        nbr[:, :-1] |= res[:, 1:]
        cand = emp & nbr
        ys, xs = np.where(cand)
        if len(xs) > 0:
            k = (obs.step + int(tm.sum()) // 100) % len(xs)
            return (Tool.RESIDENTIAL, int(xs[k]), int(ys[k]))

    return None

def act(obs, state):
    """
    Variation: Use a HORIZONTAL spine instead of vertical.
    Wire runs horizontally through the center, roads run vertically from it.
    Zones placed above and below the horizontal spine.
    This creates a very different city shape.
    Also starts with nuclear power for more capacity.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        if com_count / t < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    all_zone_mask = resm | comm | indm

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    # Phase 1: Place coal power plant left of center
    if not np.any(pm):
        return (Tool.COALPOWER, cx - 15, cy)

    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Horizontal spine layout
    wire_row = plant_cy  # horizontal wire along plant row
    road_row_above = wire_row - 2  # road above the wire
    road_row_below = wire_row + 2  # road below the wire

    # Zone rows above and below roads
    zone_row_above1 = road_row_above - 3
    zone_row_above2 = road_row_above - 7
    zone_row_below1 = road_row_below + 3
    zone_row_below2 = road_row_below + 7

    # Clamp rows
    wire_row = max(2, min(WORLD_H - 3, wire_row))
    road_row_above = max(2, min(WORLD_H - 3, road_row_above))
    road_row_below = max(2, min(WORLD_H - 3, road_row_below))
    zone_row_above1 = max(2, min(WORLD_H - 3, zone_row_above1))
    zone_row_above2 = max(2, min(WORLD_H - 3, zone_row_above2))
    zone_row_below1 = max(2, min(WORLD_H - 3, zone_row_below1))
    zone_row_below2 = max(2, min(WORLD_H - 3, zone_row_below2))

    # Dynamic extent based on population
    if obs.city_pop < 100:
        spine_extent = 12
    elif obs.city_pop < 300:
        spine_extent = 20
    elif obs.city_pop < 600:
        spine_extent = 30
    else:
        spine_extent = 40

    target_min_col = max(1, plant_cx + 3)
    target_max_col = min(WORLD_W - 2, plant_cx + 3 + spine_extent)

    wire_cols_on_spine = sorted([c for c in range(WORLD_W) if wm[wire_row, c]])
    road_cols_above = set(c for c in range(WORLD_W) if rm[road_row_above, c])
    road_cols_below = set(c for c in range(WORLD_W) if rm[road_row_below, c])

    # Phase 2: Start wire adjacent to plant (horizontal)
    if not wire_cols_on_spine:
        start_c = plant_cx + 4
        if 0 <= start_c < WORLD_W and (em[wire_row, start_c] or wm[wire_row, start_c]):
            return (Tool.WIRE, start_c, wire_row)
        return None

    min_wire_col = min(wire_cols_on_spine)
    max_wire_col = max(wire_cols_on_spine)

    # Phase 3: Extend wire spine rightward
    if max_wire_col < target_max_col:
        nc = max_wire_col + 1
        if nc < WORLD_W and not pm[wire_row, nc]:
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # Phase 4: Extend wire spine leftward (toward plant)
    if min_wire_col > target_min_col:
        nc = min_wire_col - 1
        if nc >= 0 and not pm[wire_row, nc]:
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # Phase 5: Build road above the wire spine
    for c in wire_cols_on_spine:
        if 0 <= c < WORLD_W and 0 <= road_row_above < WORLD_H:
            if c not in road_cols_above and em[road_row_above, c]:
                return (Tool.ROAD, c, road_row_above)

    # Phase 6: Build road below the wire spine
    for c in wire_cols_on_spine:
        if 0 <= c < WORLD_W and 0 <= road_row_below < WORLD_H:
            if c not in road_cols_below and em[road_row_below, c]:
                return (Tool.ROAD, c, road_row_below)

    # Phase 7: Place zones along the corridor
    # Zone columns at intervals along the spine
    zone_cols = list(range(max(1, target_min_col), min(WORLD_W - 1, target_max_col + 1), 3))

    for zc in zone_cols:
        wire_near = any(abs(zc - wc) <= 2 for wc in wire_cols_on_spine)
        road_near_above = any(abs(zc - rc) <= 2 for rc in road_cols_above)
        road_near_below = any(abs(zc - rc) <= 2 for rc in road_cols_below)

        if wire_near:
            # Try zone above road
            if road_near_above:
                for zr in [zone_row_above1, zone_row_above2]:
                    if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                        if has_wire_nearby(zr, zc, 5) and has_road_nearby(zr, zc, 5):
                            return (pick_tool(), zc, zr)

            # Try zone below road
            if road_near_below:
                for zr in [zone_row_below1, zone_row_below2]:
                    if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                        if has_wire_nearby(zr, zc, 5) and has_road_nearby(zr, zc, 5):
                            return (pick_tool(), zc, zr)

    # Phase 8: Vertical wires from spine to zones above
    for wc in wire_cols_on_spine:
        for wr in range(wire_row - 1, max(zone_row_above1 - 2, 0), -1):
            if 0 <= wr < WORLD_H:
                if wm[wr, wc]:
                    break
                if rm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc]:
                    break

    # Phase 9: Vertical wires from spine to zones below
    for wc in wire_cols_on_spine:
        for wr in range(wire_row + 1, min(zone_row_below1 + 2, WORLD_H)):
            if 0 <= wr < WORLD_H:
                if wm[wr, wc]:
                    break
                if rm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc]:
                    break

    # Phase 10: Second power plant when pop grows
    if obs.city_pop > 300 and int(np.sum(pm)) < 9:
        px2, py2 = plant_cx + 30, plant_cy
        if 2 <= py2 <= WORLD_H - 3 and 2 <= px2 <= WORLD_W - 3:
            area_clear = True
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if not (em[py2 + dr, px2 + dc] or pm[py2 + dr, px2 + dc]):
                        area_clear = False
            if area_clear:
                return (Tool.COALPOWER, px2, py2)

    # Phase 11: Second horizontal spine (above first) when pop >= 250
    if obs.city_pop >= 250:
        wire_row2 = wire_row - 12
        road_row2_above = wire_row2 - 2
        road_row2_below = wire_row2 + 2
        zone_row2_above = road_row2_above - 3
        zone_row2_below = road_row2_below + 3

        wire_row2 = max(2, min(WORLD_H - 3, wire_row2))
        road_row2_above = max(2, min(WORLD_H - 3, road_row2_above))
        road_row2_below = max(2, min(WORLD_H - 3, road_row2_below))
        zone_row2_above = max(2, min(WORLD_H - 3, zone_row2_above))
        zone_row2_below = max(2, min(WORLD_H - 3, zone_row2_below))

        wire_cols2 = sorted([c for c in range(WORLD_W) if wm[wire_row2, c]])
        road_cols2_above = set(c for c in range(WORLD_W) if rm[road_row2_above, c])
        road_cols2_below = set(c for c in range(WORLD_W) if rm[road_row2_below, c])

        if not wire_cols2:
            # Build vertical wire bridge from main spine up to spine2
            for wr in range(wire_row - 1, wire_row2 - 1, -1):
                if 0 <= wr < WORLD_H:
                    c = plant_cx + 3
                    if not wm[wr, c] and em[wr, c]:
                        return (Tool.WIRE, c, wr)
                    elif not em[wr, c] and not wm[wr, c]:
                        break
        else:
            min_wc2 = min(wire_cols2)
            max_wc2 = max(wire_cols2)

            if max_wc2 < target_max_col:
                nc = max_wc2 + 1
                if nc < WORLD_W and em[wire_row2, nc]:
                    return (Tool.WIRE, nc, wire_row2)
            if min_wc2 > target_min_col:
                nc = min_wc2 - 1
                if nc >= 0 and em[wire_row2, nc]:
                    return (Tool.WIRE, nc, wire_row2)

            for c in wire_cols2:
                if c not in road_cols2_above and em[road_row2_above, c]:
                    return (Tool.ROAD, c, road_row2_above)
                if c not in road_cols2_below and em[road_row2_below, c]:
                    return (Tool.ROAD, c, road_row2_below)

            for zc in zone_cols:
                wire_near2 = any(abs(zc - wc) <= 2 for wc in wire_cols2)
                road_near2_a = any(abs(zc - rc) <= 2 for rc in road_cols2_above)
                road_near2_b = any(abs(zc - rc) <= 2 for rc in road_cols2_below)
                if wire_near2:
                    for zr, rn in [(zone_row2_above, road_near2_a), (zone_row2_below, road_near2_b)]:
                        if rn and not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                            if has_wire_nearby(zr, zc, 6) and has_road_nearby(zr, zc, 5):
                                return (pick_tool(), zc, zr)

    # Phase 12: Third spine (below first) when pop >= 400
    if obs.city_pop >= 400:
        wire_row3 = wire_row + 12
        road_row3_above = wire_row3 - 2
        road_row3_below = wire_row3 + 2
        zone_row3_above = road_row3_above - 3
        zone_row3_below = road_row3_below + 3

        wire_row3 = max(2, min(WORLD_H - 3, wire_row3))
        road_row3_above = max(2, min(WORLD_H - 3, road_row3_above))
        road_row3_below = max(2, min(WORLD_H - 3, road_row3_below))
        zone_row3_above = max(2, min(WORLD_H - 3, zone_row3_above))
        zone_row3_below = max(2, min(WORLD_H - 3, zone_row3_below))

        wire_cols3 = sorted([c for c in range(WORLD_W) if wm[wire_row3, c]])
        road_cols3_above = set(c for c in range(WORLD_W) if rm[road_row3_above, c])
        road_cols3_below = set(c for c in range(WORLD_W) if rm[road_row3_below, c])

        if not wire_cols3:
            for wr in range(wire_row + 1, wire_row3 + 1):
                if 0 <= wr < WORLD_H:
                    c = plant_cx + 3
                    if not wm[wr, c] and em[wr, c]:
                        return (Tool.WIRE, c, wr)
                    elif not em[wr, c] and not wm[wr, c]:
                        break
        else:
            min_wc3 = min(wire_cols3)
            max_wc3 = max(wire_cols3)

            if max_wc3 < target_max_col:
                nc = max_wc3 + 1
                if nc < WORLD_W and em[wire_row3, nc]:
                    return (Tool.WIRE, nc, wire_row3)
            if min_wc3 > target_min_col:
                nc = min_wc3 - 1
                if nc >= 0 and em[wire_row3, nc]:
                    return (Tool.WIRE, nc, wire_row3)

            for c in wire_cols3:
                if c not in road_cols3_above and em[road_row3_above, c]:
                    return (Tool.ROAD, c, road_row3_above)
                if c not in road_cols3_below and em[road_row3_below, c]:
                    return (Tool.ROAD, c, road_row3_below)

            for zc in zone_cols:
                wire_near3 = any(abs(zc - wc) <= 2 for wc in wire_cols3)
                road_near3_a = any(abs(zc - rc) <= 2 for rc in road_cols3_above)
                road_near3_b = any(abs(zc - rc) <= 2 for rc in road_cols3_below)
                if wire_near3:
                    for zr, rn in [(zone_row3_above, road_near3_a), (zone_row3_below, road_near3_b)]:
                        if rn and not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                            if has_wire_nearby(zr, zc, 6) and has_road_nearby(zr, zc, 5):
                                return (pick_tool(), zc, zr)

    return None

def act(obs, state):
    """
    Variation: Two separate neighborhoods connected by a longer road,
    with a vertical layout instead of horizontal spine.
    Each neighborhood has its own power plant + zone cluster.
    More balanced R/C/I mix with explicit ratios.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Initialize state
    if 'phase' not in state:
        state['phase'] = 0
        state['step'] = 0
    state['step'] += 1

    # Two neighborhoods:
    # Neighborhood 1: centered around (30, 30)
    # Neighborhood 2: centered around (70, 65)
    N1_PLANT = (30, 30)
    N2_PLANT = (70, 65)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    zone_set = set()
    for arr in [resm, comm, indm]:
        ys, xs = np.where(arr)
        for y, x in zip(ys.tolist(), xs.tolist()):
            zone_set.add((y, x))

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    def pick_tool():
        t = max(total_zones, 1)
        r_ratio = res_count / t
        c_ratio = com_count / t
        i_ratio = ind_count / t
        # Target: 50% res, 25% com, 25% ind
        if c_ratio < 0.25:
            return Tool.COMMERCIAL
        if i_ratio < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Step 1: Place first coal power plant
    plant_cells = np.where(pm)
    plant_count = len(plant_cells[0])

    if plant_count == 0:
        x1, y1 = N1_PLANT
        return (Tool.COALPOWER, x1, y1)

    plant_ys, plant_xs = plant_cells
    # Check if second plant exists near N2
    n2x, n2y = N2_PLANT
    has_n2_plant = False
    for pxi, pyi in zip(plant_xs, plant_ys):
        if abs(int(pxi) - n2x) < 10 and abs(int(pyi) - n2y) < 10:
            has_n2_plant = True
            break

    # Build N1 infrastructure: vertical wire spine at x=30, roads at x=27 and x=33
    # Wire spine from y=32 to y=15 (above plant) and y=28 to y=45 (below plant)
    n1x, n1y = N1_PLANT
    n1_wire_x = n1x  # vertical wire spine at x=30
    n1_road_left = n1x - 3   # x=27
    n1_road_right = n1x + 3  # x=33
    n1_wire_top = n1y - 15
    n1_wire_bot = n1y + 15

    # Build vertical wire spine for N1
    for wy in range(n1y + 2, min(n1_wire_bot + 1, WORLD_H - 1)):
        wx = n1_wire_x
        if not in_bounds(wx, wy):
            break
        if not bool(wm[wy, wx]) and not bool(pm[wy, wx]):
            if bool(em[wy, wx]):
                return (Tool.WIRE, wx, wy)
            break

    for wy in range(n1y - 2, max(n1_wire_top - 1, 1), -1):
        wx = n1_wire_x
        if not in_bounds(wx, wy):
            break
        if not bool(wm[wy, wx]) and not bool(pm[wy, wx]):
            if bool(em[wy, wx]):
                return (Tool.WIRE, wx, wy)
            break

    # Build left road for N1 (vertical road at x=27, from y=15 to y=45)
    n1_road_y_start = n1_wire_top + 1
    n1_road_y_end = n1_wire_bot - 1
    for ry in range(n1_road_y_start, min(n1_road_y_end + 1, WORLD_H - 1)):
        rx = n1_road_left
        if not in_bounds(rx, ry):
            continue
        if not bool(rm[ry, rx]) and not bool(pm[ry, rx]) and not bool(wm[ry, rx]):
            if bool(em[ry, rx]):
                return (Tool.ROAD, rx, ry)

    # Build right road for N1
    for ry in range(n1_road_y_start, min(n1_road_y_end + 1, WORLD_H - 1)):
        rx = n1_road_right
        if not in_bounds(rx, ry):
            continue
        if not bool(rm[ry, rx]) and not bool(pm[ry, rx]) and not bool(wm[ry, rx]):
            if bool(em[ry, rx]):
                return (Tool.ROAD, rx, ry)

    # Horizontal connector roads for N1 every 6 rows
    for hr in range(n1_road_y_start, n1_road_y_end + 1, 6):
        for hx in range(n1_road_left, n1_road_right + 1):
            if not in_bounds(hx, hr):
                continue
            if not bool(rm[hr, hx]) and not bool(pm[hr, hx]) and not bool(wm[hr, hx]):
                if bool(em[hr, hx]):
                    return (Tool.ROAD, hx, hr)

    # Horizontal wire branches for N1 every 6 rows
    for bwy in range(n1y + 4, n1_wire_bot, 6):
        for sign2 in [-1, 1]:
            for dx in range(1, 4):
                bwx = n1_wire_x + sign2 * dx
                if not in_bounds(bwx, bwy):
                    break
                if bool(wm[bwy, bwx]) or bool(pm[bwy, bwx]):
                    continue
                if bool(em[bwy, bwx]):
                    return (Tool.WIRE, bwx, bwy)
                break
    for bwy in range(n1y - 4, n1_wire_top, -6):
        for sign2 in [-1, 1]:
            for dx in range(1, 4):
                bwx = n1_wire_x + sign2 * dx
                if not in_bounds(bwx, bwy):
                    break
                if bool(wm[bwy, bwx]) or bool(pm[bwy, bwx]):
                    continue
                if bool(em[bwy, bwx]):
                    return (Tool.WIRE, bwx, bwy)
                break

    # Place zones near N1
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    # Restrict to N1 area first (when pop is low), then expand to N2
    if obs.city_pop < 400 or not has_n2_plant:
        # Focus on N1 area
        n1_cand = cand_mask.copy()
        n1_cand[:, n1x+12:] = False
        n1_cand[:, :max(n1x-12, 0)] = False
        cys_arr, cxs_arr = np.where(n1_cand)
    else:
        cys_arr, cxs_arr = np.where(cand_mask)

    if len(cxs_arr) > 0:
        step_hash = int(obs.step * 17 + int(obs.city_pop * 3)) % max(len(cxs_arr), 1)
        for offset in range(min(len(cxs_arr), 80)):
            k = (step_hash + offset * 11) % len(cxs_arr)
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # Second neighborhood - place plant
    if obs.city_pop > 200 and not has_n2_plant:
        if in_bounds(n2x, n2y) and bool(em[n2y, n2x]):
            return (Tool.COALPOWER, n2x, n2y)

    # N2 infrastructure
    if has_n2_plant:
        n2_wire_x = n2x
        n2_wire_top2 = n2y - 12
        n2_wire_bot2 = n2y + 12
        n2_road_l = n2x - 3
        n2_road_r = n2x + 3

        # Wire spine for N2
        for wy2 in range(n2y + 2, min(n2_wire_bot2 + 1, WORLD_H - 1)):
            wx2 = n2_wire_x
            if not in_bounds(wx2, wy2): break
            if not bool(wm[wy2, wx2]) and not bool(pm[wy2, wx2]):
                if bool(em[wy2, wx2]):
                    return (Tool.WIRE, wx2, wy2)
                break

        for wy2 in range(n2y - 2, max(n2_wire_top2 - 1, 1), -1):
            wx2 = n2_wire_x
            if not in_bounds(wx2, wy2): break
            if not bool(wm[wy2, wx2]) and not bool(pm[wy2, wx2]):
                if bool(em[wy2, wx2]):
                    return (Tool.WIRE, wx2, wy2)
                break

        # Roads for N2
        for ry2 in range(n2_wire_top2 + 1, min(n2_wire_bot2, WORLD_H - 1)):
            for rx2 in [n2_road_l, n2_road_r]:
                if not in_bounds(rx2, ry2): continue
                if not bool(rm[ry2, rx2]) and not bool(pm[ry2, rx2]) and not bool(wm[ry2, rx2]):
                    if bool(em[ry2, rx2]):
                        return (Tool.ROAD, rx2, ry2)

        # Wire branches for N2
        for bwy2 in range(n2y + 4, n2_wire_bot2, 6):
            for sign3 in [-1, 1]:
                for dx3 in range(1, 4):
                    bwx2 = n2_wire_x + sign3 * dx3
                    if not in_bounds(bwx2, bwy2): break
                    if bool(wm[bwy2, bwx2]) or bool(pm[bwy2, bwx2]): continue
                    if bool(em[bwy2, bwx2]):
                        return (Tool.WIRE, bwx2, bwy2)
                    break

        # Zone in N2 area
        n2_cand = cand_mask.copy()
        n2_cand[:, :max(n2x - 12, 0)] = False
        n2_cand[:, n2x + 12:] = False
        cys2, cxs2 = np.where(n2_cand)
        if len(cxs2) > 0:
            step_hash2 = int(obs.step * 19 + int(obs.city_pop * 5)) % max(len(cxs2), 1)
            for offset2 in range(min(len(cxs2), 80)):
                k2 = (step_hash2 + offset2 * 13) % len(cxs2)
                zx2, zy2 = int(cxs2[k2]), int(cys2[k2])
                if zone_clear(zx2, zy2):
                    return (pick_tool(), zx2, zy2)

    # Services
    if obs.city_pop > 200:
        fx, fy = n1x + 6, n1y - 10
        if in_bounds(fx, fy) and bool(em[fy, fx]):
            return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 300:
        px2, py2 = n1x - 6, n1y + 10
        if in_bounds(px2, py2) and bool(em[py2, px2]):
            return (Tool.POLICESTATION, px2, py2)

    # Fallback: extend roads from existing
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = int(obs.step * 13) % max(len(road_xs_arr), 1)
        rx_s = int(road_xs_arr[step_k])
        ry_s = int(road_ys_arr[step_k])
        for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx2, ny2 = rx_s + dx2, ry_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 7) % max(len(wire_xs_arr), 1)
        wx_s = int(wire_xs_arr[step_k2])
        wy_s = int(wire_ys_arr[step_k2])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = wx_s + dx2, wy_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Improved policy: horizontal road/wire spine with zones above and below.
    Key differences from parent:
    - Horizontal orientation (road runs east-west instead of north-south)
    - Zones placed above AND below the road spine
    - Better zone mix (res/com/ind balanced)
    - Multiple power plants as needed
    - More compact, wider coverage
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        # Target: 50% res, 30% com, 20% ind
        if com_count < t * 0.30:
            return Tool.COMMERCIAL
        if ind_count < t * 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                all_zone = resm[rr, rc] or comm[rr, rc] or indm[rr, rc]
                if not em[rr, rc] and not all_zone:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if resm[rr, rc] or comm[rr, rc] or indm[rr, rc]:
                        return True
        return False

    # Layout constants:
    # Power plant at (px, py), wire row just below, road row below wire
    # Zones above and below road row
    py = cy - 2   # plant y (center)
    px = cx - 20  # plant x (center), left side

    wire_row = py + 2   # horizontal wire spine row (just right of plant)
    road_row = wire_row + 2  # road row below wire

    above_zone_row = wire_row - 3  # zone centers above wire
    below_zone_row = road_row + 3  # zone centers below road

    # Clamp rows
    wire_row = max(2, min(WORLD_H - 3, wire_row))
    road_row = max(2, min(WORLD_H - 3, road_row))
    above_zone_row = max(2, min(WORLD_H - 3, above_zone_row))
    below_zone_row = max(2, min(WORLD_H - 3, below_zone_row))

    # Phase 1: Place coal power plant if missing
    if not np.any(pm):
        return (Tool.COALPOWER, px, py)

    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Determine horizontal extent of wire/road based on population
    if obs.city_pop < 100:
        extent = 15
    elif obs.city_pop < 300:
        extent = 25
    elif obs.city_pop < 600:
        extent = 40
    else:
        extent = 55

    wire_start = max(1, plant_cx + 2)  # just right of plant
    wire_end = min(WORLD_W - 2, plant_cx + extent)
    road_start = max(1, plant_cx - 2)
    road_end = min(WORLD_W - 2, plant_cx + extent)

    # Phase 2: Build horizontal wire spine
    wire_cols_on_spine = [c for c in range(WORLD_W) if wm[wire_row, c]]

    if not wire_cols_on_spine:
        # Start wire adjacent to plant
        wc = plant_cx + 2
        if 0 <= wc < WORLD_W and (em[wire_row, wc] or wm[wire_row, wc]):
            return (Tool.WIRE, wc, wire_row)
        return None

    max_wire_col = max(wire_cols_on_spine)
    min_wire_col = min(wire_cols_on_spine)

    # Extend wire rightward
    if max_wire_col < wire_end:
        nc = max_wire_col + 1
        if nc < WORLD_W and not pm[wire_row, nc]:
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # Phase 3: Build horizontal road spine below wire
    road_cols_on_spine = [c for c in range(WORLD_W) if rm[road_row, c]]

    for c in range(road_start, road_end + 1):
        if 0 <= c < WORLD_W and not rm[road_row, c] and em[road_row, c]:
            return (Tool.ROAD, c, road_row)

    # Phase 4: Place zones above and below the corridor
    # Zone columns spaced every 3 tiles starting from plant_cx
    zone_cols = list(range(max(2, plant_cx - 2), min(WORLD_W - 2, wire_end + 1), 3))

    def has_wire_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    for zc in zone_cols:
        # Only place zones where wire exists nearby (within extent of built wire)
        if not (min_wire_col - 2 <= zc <= max_wire_col + 2):
            continue

        # Above zone row
        for zr in [above_zone_row, below_zone_row]:
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc, 4) and has_road_nearby(zr, zc, 4):
                    return (pick_tool(), zc, zr)

    # Phase 5: Vertical wires from spine to zone columns (connect above zones)
    for zc in zone_cols:
        if not (min_wire_col - 1 <= zc <= max_wire_col + 1):
            continue
        # Wire from wire_row up to above_zone_row
        for vr in range(wire_row - 1, above_zone_row - 2, -1):
            if vr < 0:
                break
            if wm[vr, zc]:
                break
            if em[vr, zc] and not pm[vr, zc] and not rm[vr, zc]:
                return (Tool.WIRE, zc, vr)
            elif not em[vr, zc]:
                break

    # Phase 6: Vertical wires from spine down to below zones
    for zc in zone_cols:
        if not (min_wire_col - 1 <= zc <= max_wire_col + 1):
            continue
        for vr in range(wire_row + 1, below_zone_row + 2):
            if vr >= WORLD_H:
                break
            if wm[vr, zc]:
                break
            if em[vr, zc] and not pm[vr, zc] and not rm[vr, zc]:
                return (Tool.WIRE, zc, vr)
            elif not em[vr, zc] and not rm[vr, zc]:
                break

    # Phase 7: Second coal plant for more power if needed
    if obs.city_pop > 300 and int(np.sum(pm)) < 9:
        px2 = plant_cx + 25
        py2 = plant_cy
        if 2 <= py2 <= WORLD_H - 3 and 2 <= px2 <= WORLD_W - 3:
            # Check if area is empty
            area_empty = all(
                em[py2 + dr, px2 + dc]
                for dr in [-1, 0, 1]
                for dc in [-1, 0, 1]
                if 0 <= py2 + dr < WORLD_H and 0 <= px2 + dc < WORLD_W
            )
            if area_empty:
                return (Tool.COALPOWER, px2, py2)

    # Phase 8: Third power plant for large cities
    if obs.city_pop > 600 and int(np.sum(pm)) < 18:
        px3 = plant_cx + 45
        py3 = plant_cy
        if 2 <= py3 <= WORLD_H - 3 and 2 <= px3 <= WORLD_W - 3:
            area_empty = all(
                em[py3 + dr, px3 + dc]
                for dr in [-1, 0, 1]
                for dc in [-1, 0, 1]
                if 0 <= py3 + dr < WORLD_H and 0 <= px3 + dc < WORLD_W
            )
            if area_empty:
                return (Tool.COALPOWER, px3, py3)

    # Phase 9: Add second above/below zone row for bigger cities
    if obs.city_pop > 400:
        above2_row = above_zone_row - 4
        below2_row = below_zone_row + 4
        above2_row = max(2, above2_row)
        below2_row = min(WORLD_H - 3, below2_row)

        for zc in zone_cols:
            if not (min_wire_col - 2 <= zc <= max_wire_col + 2):
                continue
            for zr in [above2_row, below2_row]:
                if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                    if has_wire_nearby(zr, zc, 6) and has_road_nearby(zr, zc, 6):
                        return (pick_tool(), zc, zr)

    # Phase 10: Connect second plant to wire spine
    if int(np.sum(pm)) >= 9:
        plant_rows2, plant_cols2 = np.where(pm)
        # Find rightmost plant group
        right_plant_cols = [c for c in plant_cols2 if c > plant_cx + 15]
        if right_plant_cols:
            rpc = int(np.mean(right_plant_cols))
            # Wire from that plant to wire spine
            for wc in range(rpc - 2, min_wire_col - 1, -1):
                if 0 <= wc < WORLD_W:
                    if wm[wire_row, wc]:
                        break
                    if em[wire_row, wc] and not pm[wire_row, wc]:
                        return (Tool.WIRE, wc, wire_row)
                    elif not em[wire_row, wc]:
                        break

    return None

def act(obs, state):
    """
    Combined policy:
    - Coal plant placed first at fixed location
    - Vertical wire spine adjacent to plant
    - Road columns on BOTH sides of wire spine (wider spacing for zone access)
    - Horizontal roads to connect columns
    - Zones placed reactively near road+wire
    - Second plant + expansion when city grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Place coal power plant first ---
    has_plant = np.any(pm)
    if not has_plant:
        return (Tool.COALPOWER, 55, 50)

    plant_ys, plant_xs = np.where(pm)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        r_r = res_count / t
        c_r = com_count / t
        i_r = ind_count / t
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Wire spine column just right of plant
    wire_col = px + 2

    # Vertical span grows with population
    base_span = 15
    extra_span = min(35, obs.city_pop // 15)
    target_span = base_span + extra_span
    tmin = max(2, py - target_span)
    tmax = min(WORLD_H - 3, py + target_span)

    wire_rows_in_col = sorted(r for r in range(WORLD_H) if 0 <= wire_col < WORLD_W and wm[r, wire_col])

    # --- Build vertical wire spine ---
    if not wire_rows_in_col:
        for dy in range(-2, 3):
            ny = py + dy
            if in_bounds(wire_col, ny) and em[ny, wire_col]:
                return (Tool.WIRE, wire_col, ny)
    else:
        min_wr = min(wire_rows_in_col)
        max_wr = max(wire_rows_in_col)
        if max_wr < tmax:
            nr = max_wr + 1
            if in_bounds(wire_col, nr) and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        if min_wr > tmin:
            nr = min_wr - 1
            if in_bounds(wire_col, nr) and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    # Road columns: 2 cells each side of wire spine (gives 3-wide zone slots)
    road_col_r = wire_col + 2
    road_col_l = wire_col - 2

    # --- Build road columns along wire spine ---
    for wr in wire_rows_in_col:
        if not (tmin <= wr <= tmax):
            continue
        if in_bounds(road_col_r, wr) and em[wr, road_col_r]:
            return (Tool.ROAD, road_col_r, wr)
        if in_bounds(road_col_l, wr) and em[wr, road_col_l]:
            return (Tool.ROAD, road_col_l, wr)

    # --- Add horizontal connecting roads every 6 rows for better connectivity ---
    if wire_rows_in_col:
        for wr in wire_rows_in_col:
            if not (tmin <= wr <= tmax):
                continue
            if (wr - tmin) % 6 == 0:
                # Connect left road to right road through wire
                for rc in range(road_col_l, road_col_r + 1):
                    if in_bounds(rc, wr) and not rm[wr, rc] and em[wr, rc]:
                        return (Tool.ROAD, rc, wr)

    # --- Reactive zone placement ---
    # Build neighbor masks for road and wire proximity
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    all_zone_m = resm | comm | indm
    zone_rows, zone_cols = np.where(all_zone_m)
    zone_set = set(zip(zone_rows.tolist(), zone_cols.tolist()))

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    # Candidate zone centers: near road AND wire, not too close to edge
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Sort candidates by distance to wire spine (prefer close)
        dists = np.abs(cxs - wire_col) + np.abs(cys - py)
        sort_idx = np.argsort(dists)
        step_hash = int(obs.step * 17 + total_zones * 7) % max(len(cxs), 1)
        for i in range(min(len(cxs), 80)):
            # Mix deterministic sweep with distance priority
            if i < 40:
                k = int(sort_idx[i])
            else:
                k = (step_hash + (i - 40) * 13) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # --- Extend roads sideways from existing road to reach more zone positions ---
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        for dy, dx in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            step_k = int(obs.step * 11) % max(len(road_xs_arr), 1)
            rx_s = int(road_xs_arr[step_k])
            ry_s = int(road_ys_arr[step_k])
            nx2, ny2 = rx_s + dx, ry_s + dy
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                if nbr_wire[ny2, nx2]:
                    return (Tool.ROAD, nx2, ny2)

    # --- Second power plant when many zones exist ---
    if total_zones > 18 or obs.city_pop > 350:
        p2x = px + 22
        p2y = py
        if in_bounds(p2x, p2y):
            nearby_plant = any(
                in_bounds(p2x + dx, p2y + dy) and pm[p2y + dy, p2x + dx]
                for dy in range(-8, 9) for dx in range(-8, 9)
            )
            if not nearby_plant and em[p2y, p2x]:
                return (Tool.COALPOWER, p2x, p2y)
            # Connect second plant with wire bridge
            for wc in range(wire_col + 1, p2x):
                if in_bounds(wc, py) and (em[py, wc] or wm[py, wc]):
                    if not pm[py, wc]:
                        return (Tool.WIRE, wc, py)

    # --- Services for city happiness ---
    if obs.city_pop > 200:
        fx, fy = px - 6, py - 8
        if in_bounds(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
        px2, py2 = px - 6, py + 8
        if in_bounds(px2, py2) and em[py2, px2]:
            return (Tool.POLICESTATION, px2, py2)

    # --- Third plant and extended wire when very large ---
    if obs.city_pop > 700 and not state.get("plant3_placed", False):
        p3x = px - 22
        p3y = py
        if in_bounds(p3x, p3y):
            nearby_plant3 = any(
                in_bounds(p3x + dx, p3y + dy) and pm[p3y + dy, p3x + dx]
                for dy in range(-8, 9) for dx in range(-8, 9)
            )
            if not nearby_plant3 and em[p3y, p3x]:
                state["plant3_placed"] = True
                return (Tool.COALPOWER, p3x, p3y)
            # Connect with wire leftward
            for wc in range(wire_col - 1, p3x - 1, -1):
                if in_bounds(wc, py) and (em[py, wc] or wm[py, wc]) and not pm[py, wc]:
                    return (Tool.WIRE, wc, py)

    # --- Extend wire frontier if stuck ---
    wire_ys_arr2, wire_xs_arr2 = np.where(wm)
    if len(wire_xs_arr2) > 0:
        step_k2 = int(obs.step * 7) % max(len(wire_xs_arr2), 1)
        wx_s = int(wire_xs_arr2[step_k2])
        wy_s = int(wire_ys_arr2[step_k2])
        for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx2, ny2 = wx_s + dx2, wy_s + dy2
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder - improved version.
    Key changes from parent:
    - Better zone placement: place zones in a structured grid around roads
    - More aggressive wire extension to ensure power coverage
    - Place second power plant earlier
    - Better road grid with regular cross-streets
    - Use a larger cluster area
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Central anchor - slightly left-center to give more room
    CX, CY = 55, 50

    # Step 1: Place first power plant if none exists
    if not np.any(pm):
        return (Tool.COALPOWER, CX, CY)

    # Find plant center
    plant_rows, plant_cols = np.where(pm)
    pcx = int(np.mean(plant_cols))
    pcy = int(np.mean(plant_rows))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Layout: 
    # Wire spine: row at pcy-2, col at pcx+2
    # Road spine: row at pcy+3, col at pcx+4
    # Zones cluster around these roads

    wire_row = pcy - 2
    road_row = pcy + 3
    wire_col = pcx + 2
    road_col = pcx + 4

    power_map = pm | wm

    # Step 2: Place second power plant early if population growing
    if obs.city_pop > 150 and int(np.sum(pm)) < 9:
        # Place second plant to the right
        p2x = pcx + 25
        p2y = pcy
        p2x = max(4, min(WORLD_W - 5, p2x))
        p2y = max(4, min(WORLD_H - 5, p2y))
        if bool(em[p2y, p2x]):
            return (Tool.COALPOWER, p2x, p2y)

    if obs.city_pop > 400 and int(np.sum(pm)) < 18:
        # Place third plant above
        p3x = pcx
        p3y = pcy - 20
        p3x = max(4, min(WORLD_W - 5, p3x))
        p3y = max(4, min(WORLD_H - 5, p3y))
        if bool(em[p3y, p3x]):
            return (Tool.COALPOWER, p3x, p3y)

    # Step 3: Extend wires - connect all power plants together and out to zones
    # First build a wire grid: horizontal spines at wire_row and wire_row-10,
    # vertical spine at wire_col
    w_extent = min(35, 12 + obs.city_pop // 15)

    # Build wire targets: horizontal lines + vertical connectors
    wire_targets = []
    # Main horizontal wire spine
    for x in range(CX - w_extent, CX + w_extent + 1):
        wire_targets.append((x, wire_row))
    # Second horizontal wire (upper cluster)
    for x in range(CX - w_extent, CX + w_extent + 1):
        wire_targets.append((x, wire_row - 8))
    # Vertical wire spines connecting horizontal spines
    for dx in range(-w_extent, w_extent + 1, 6):
        col = CX + dx
        for y in range(wire_row - 8, wire_row + 1):
            wire_targets.append((col, y))
    # Wire down to road level to power zones
    for dx in range(-w_extent, w_extent + 1, 6):
        col = CX + dx
        for y in range(wire_row, road_row + 1):
            wire_targets.append((col, y))

    for (wx, wy) in wire_targets:
        if not in_bounds(wx, wy):
            continue
        if bool(wm[wy, wx]) or bool(pm[wy, wx]):
            continue
        # Only place if adjacent to existing power
        adj = False
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx, ny = wx+ddx, wy+ddy
            if in_bounds(nx, ny) and bool(power_map[ny, nx]):
                adj = True
                break
        if adj and bool(em[wy, wx]):
            return (Tool.WIRE, wx, wy)

    # Step 4: Build road grid
    r_extent = min(30, 10 + obs.city_pop // 12)

    road_targets = []
    # Main horizontal road
    for x in range(CX - r_extent, CX + r_extent + 1):
        road_targets.append((x, road_row))
    # Second horizontal road (above)
    for x in range(CX - r_extent, CX + r_extent + 1):
        road_targets.append((x, road_row - 8))
    # Third horizontal road (below)
