    # Find initial road seed - adjacent to power plant if no roads
    road_exists = np.any(rm)
    if not road_exists:
        # Place first road adjacent to plant
        rx0 = pcx + 4
        ry0 = pcy + 3
        if in_bounds(rx0, ry0) and bool(em[ry0, rx0]):
            return (Tool.ROAD, rx0, ry0)

    for (rx, ry) in road_targets:
        if not in_bounds(rx, ry):
            continue
        if bool(rm[ry, rx]) or bool(pm[ry, rx]) or bool(wm[ry, rx]):
            continue
        if not bool(em[ry, rx]):
            continue
        # Adjacent to existing road, or adjacent to plant
        adj_road = False
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx2, ny2 = rx+ddx, ry+ddy
            if in_bounds(nx2, ny2) and bool(rm[ny2, nx2]):
                adj_road = True
                break
        adj_plant = False
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1),(2,0),(-2,0),(0,2),(0,-2)]:
            nx2, ny2 = rx+ddx, ry+ddy
            if in_bounds(nx2, ny2) and bool(pm[ny2, nx2]):
                adj_plant = True
                break
        if adj_road or adj_plant:
            return (Tool.ROAD, rx, ry)

    # Step 5: Place zones in a structured grid
    # Zones go in 3x3 blocks, centered on tiles that are:
    # - Empty in a 3x3 neighborhood
    # - Adjacent to road (within 2)
    # - Near power (within 6)

    # Build neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_mask = resm | comm | indm
    cand = em & nbr_road & nbr_power
    cand[0:2, :] = False
    cand[WORLD_H-2:, :] = False
    cand[:, 0:2] = False
    cand[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        # Prefer positions on a 4-tile grid pattern for dense packing
        # and closer to city center
        best_k = -1
        best_score = -1e9
        key = int(obs.step * 17 + int(obs.city_pop * 3) + 1) % len(cxs)
        check_count = min(len(cxs), 80)
        for offset in range(check_count):
            k = (key + offset * 13) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            # Check 3x3 neighborhood is clear
            ok = True
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    ny2, nx2 = zy + dr, zx + dc
                    if not in_bounds(nx2, ny2):
                        ok = False; break
                    if not (bool(em[ny2, nx2]) or bool(zone_mask[ny2, nx2])):
                        ok = False; break
                if not ok:
                    break
            if ok:
                # Score: prefer on-grid positions and close to center
                grid_bonus = 1.0 if (zx % 4 == 0 and zy % 4 == 0) else 0.0
                dist = abs(zx - CX) + abs(zy - CY)
                score = grid_bonus * 10 - dist * 0.1
                if score > best_score:
                    best_score = score
                    best_k = k
        if best_k >= 0:
            zx, zy = int(cxs[best_k]), int(cys[best_k])
            return (pick_tool(), zx, zy)

    # Step 6: Services when population warrants
    if obs.city_pop > 300:
        for fx, fy in [(CX + 8, CY - 10), (CX - 8, CY + 10), (CX + 15, CY)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 500:
        for fx, fy in [(CX + 8, CY + 10), (CX - 8, CY - 10)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.POLICESTATION, fx, fy)

    # Fallback: extend wire from any wire frontier
    wys2, wxs2 = np.where(wm)
    if len(wxs2) > 0:
        k3 = int(obs.step * 7) % len(wxs2)
        wx2, wy2 = int(wxs2[k3]), int(wys2[k3])
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx, ny = wx2+ddx, wy2+ddy
            if in_bounds(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                return (Tool.WIRE, nx, ny)

    # Fallback: extend road from any road frontier
    rys2, rxs2 = np.where(rm)
    if len(rxs2) > 0:
        k2 = int(obs.step * 11) % len(rxs2)
        rx2, ry2 = int(rxs2[k2]), int(rys2[k2])
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx, ny = rx2+ddx, ry2+ddy
            if in_bounds(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                return (Tool.ROAD, nx, ny)

    return None

