    # Step 2: Place right power plant early (after step 30)
    plant_ys, plant_xs = np.where(pm)
    n_plants = len(plant_xs)
    # Check if second plant exists near P2X, P2Y
    second_plant = False
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            ny, nx = P2Y + dy, P2X + dx
            if in_bounds(nx, ny) and bool(pm[ny, nx]):
                second_plant = True
    if not second_plant and obs.step > 20:
        if in_bounds(P2X, P2Y):
            return (Tool.COALPOWER, P2X, P2Y)

    # Wire spine: horizontal wire connecting both plants along y=45
    # Left plant to right plant
    for wx in range(P1X + 2, P2X - 1):
        wy = P1Y
        if not in_bounds(wx, wy): break
        if not bool(wm[wy, wx]) and not bool(pm[wy, wx]):
            if bool(em[wy, wx]):
                return (Tool.WIRE, wx, wy)
            # If blocked by road, try to skip
            break

    # Also extend wire rightward from P2 to cover right neighborhood
    for wx in range(P2X + 2, min(P2X + 45, WORLD_W - 3)):
        wy = P2Y
        if not in_bounds(wx, wy): break
        if not bool(wm[wy, wx]) and not bool(pm[wy, wx]):
            if bool(em[wy, wx]):
                return (Tool.WIRE, wx, wy)
            break

    # Also extend wire leftward from P1 to cover left neighborhood
    for wx in range(P1X - 2, max(P1X - 25, 3), -1):
        wy = P1Y
        if not in_bounds(wx, wy): break
        if not bool(wm[wy, wx]) and not bool(pm[wy, wx]):
            if bool(em[wy, wx]):
                return (Tool.WIRE, wx, wy)
            break

    # Grid road layout:
    # Two clusters: left (x: 5..40, y: 35..57), right (x: 55..100, y: 35..57)
    # Horizontal roads at y=38, y=42, y=48, y=52 (avoiding wire spine at y=45)
    # Vertical roads every 6 cols within each cluster

    road_ys = [38, 42, 48, 52]
    left_road_start, left_road_end = 5, 42
    right_road_start, right_road_end = 55, 102

    # Build horizontal roads in left cluster
    for ry in road_ys:
        if not in_bounds(0, ry): continue
        for rx in range(left_road_start, left_road_end):
            if not in_bounds(rx, ry): break
            if not bool(rm[ry, rx]) and not bool(pm[ry, rx]) and not bool(wm[ry, rx]):
                if bool(em[ry, rx]):
                    return (Tool.ROAD, rx, ry)
                break  # blocked

    # Build horizontal roads in right cluster
    for ry in road_ys:
        if not in_bounds(0, ry): continue
        for rx in range(right_road_start, right_road_end):
            if not in_bounds(rx, ry): break
            if not bool(rm[ry, rx]) and not bool(pm[ry, rx]) and not bool(wm[ry, rx]):
                if bool(em[ry, rx]):
                    return (Tool.ROAD, rx, ry)
                break

    # Build vertical connector roads in left cluster
    left_vert_cols = list(range(left_road_start, left_road_end, 6))
    for vc in left_vert_cols:
        for vr in range(min(road_ys), max(road_ys) + 1):
            if not in_bounds(vc, vr): continue
            if not bool(rm[vr, vc]) and not bool(pm[vr, vc]) and not bool(wm[vr, vc]):
                if bool(em[vr, vc]):
                    return (Tool.ROAD, vc, vr)

    # Build vertical connector roads in right cluster
    right_vert_cols = list(range(right_road_start, right_road_end, 6))
    for vc in right_vert_cols:
        for vr in range(min(road_ys), max(road_ys) + 1):
            if not in_bounds(vc, vr): continue
            if not bool(rm[vr, vc]) and not bool(pm[vr, vc]) and not bool(wm[vr, vc]):
                if bool(em[vr, vc]):
                    return (Tool.ROAD, vc, vr)

    # Vertical wire branches from spine into road areas (every 6 cols)
    spine_y = P1Y
    for bx in range(P1X - 20, P2X + 40, 6):
        if not in_bounds(bx, spine_y): continue
        if not (bool(wm[spine_y, bx]) or bool(pm[spine_y, bx])): continue
        for sign in [-1, 1]:
            for dy in range(1, 8):
                wy = spine_y + sign * dy
                if not in_bounds(bx, wy): break
                if bool(wm[wy, bx]) or bool(pm[wy, bx]): continue
                if bool(em[wy, bx]):
                    return (Tool.WIRE, bx, wy)
                break

    # Zone placement using neighbor proximity
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        step_hash = int(obs.step * 17 + int(obs.city_pop * 3)) % max(len(cxs_arr), 1)
        for offset in range(min(len(cxs_arr), 80)):
            k = (step_hash + offset * 11) % len(cxs_arr)
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # Services
    if obs.city_pop > 100:
        # Fire station in left cluster
        fx, fy = P1X + 3, P1Y - 10
        if in_bounds(fx, fy) and bool(em[fy, fx]):
            return (Tool.FIRESTATION, fx, fy)
        # Police station in right cluster
        px2, py2 = P2X + 3, P2Y - 10
        if in_bounds(px2, py2) and bool(em[py2, px2]):
            return (Tool.POLICESTATION, px2, py2)

    if obs.city_pop > 300:
        # Additional fire/police
        fx2, fy2 = P1X + 3, P1Y + 10
        if in_bounds(fx2, fy2) and bool(em[fy2, fx2]):
            return (Tool.FIRESTATION, fx2, fy2)
        px3, py3 = P2X + 3, P2Y + 10
        if in_bounds(px3, py3) and bool(em[py3, px3]):
            return (Tool.POLICESTATION, px3, py3)

    # Third power plant if needed
    if obs.city_pop > 500 or total_zones > 25:
        P3X, P3Y = 45, 45
        third_plant = False
        for dy in range(-4, 5):
            for dx in range(-4, 5):
                ny, nx = P3Y + dy, P3X + dx
                if in_bounds(nx, ny) and bool(pm[ny, nx]):
                    third_plant = True
        if not third_plant and in_bounds(P3X, P3Y) and bool(em[P3Y, P3X]):
            return (Tool.COALPOWER, P3X, P3Y)

    # Fallback: extend roads from existing frontier
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = int(obs.step * 13) % max(len(road_xs_arr), 1)
        rx_s = int(road_xs_arr[step_k])
        ry_s = int(road_ys_arr[step_k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx_s + dx2, ry_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy with improved layout:
    - Coal plant placed first, then wire spine extends from it
    - Road column adjacent to wire spine
    - Zones placed on both sides with proper power/road access
    - Lateral wires connect spine to left zones
    - Lateral roads connect road col to right zones
    - Expands vertically and adds more zone columns as population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    cx, cy = 60, 50  # map center

    has_plant = np.any(pm)
    has_wire = np.any(wm)
    has_road = np.any(rm)

    # Plant location: slightly left of center
    plant_cx, plant_cy = cx - 10, cy

    # Phase 1: place coal power plant
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Gather positions
    wire_positions = set(zip(*np.where(wm))) if has_wire else set()
    road_positions = set(zip(*np.where(rm))) if has_road else set()
    res_pos = set(zip(*np.where(res_mask(tm))))
    com_pos = set(zip(*np.where(com_mask(tm))))
    ind_pos = set(zip(*np.where(ind_mask(tm))))

    res_count = len(res_pos)
    com_count = len(com_pos)
    ind_count = len(ind_pos)
    all_zones = res_pos | com_pos | ind_pos

    # Columns: wire spine just right of plant, road just right of wire
    wire_col = plant_cx + 4   # e.g., cx-6
    road_col = wire_col + 2   # one gap between wire and road

    # Target vertical span grows with population
    base_span = 10
    extra_span = min(30, obs.city_pop // 30)
    target_span = base_span + extra_span
    tmin = max(2, cy - target_span)
    tmax = min(WORLD_H - 3, cy + target_span)

    # Current wire coverage in spine column
    wire_rows_in_col = sorted(r for (r, c) in wire_positions if c == wire_col)

    # Phase 2: seed wire spine if missing
    if not wire_rows_in_col:
        # Place wire adjacent to plant (plant occupies plant_cx-1..plant_cx+1)
        seed_r = plant_cy
        seed_c = wire_col
        if 0 <= seed_c < WORLD_W:
            return (Tool.WIRE, seed_c, seed_r)

    # Phase 3: extend wire spine vertically
    if wire_rows_in_col:
        min_wr = min(wire_rows_in_col)
        max_wr = max(wire_rows_in_col)

        # Prefer extending downward first
        if max_wr < tmax:
            nr = max_wr + 1
            if 0 < nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        # Then upward
        if min_wr > tmin:
            nr = min_wr - 1
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    # Phase 4: build road column adjacent to wire spine
    if wire_rows_in_col:
        road_rows_in_col = set(r for (r, c) in road_positions if c == road_col)
        for wr in wire_rows_in_col:
            if wr not in road_rows_in_col and 0 <= road_col < WORLD_W:
                if em[wr, road_col]:
                    return (Tool.ROAD, road_col, wr)

    # Helper: check if 3x3 area is clear for zone placement
    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def zone_nearby(zr, zc):
        return any(abs(zr - pr) <= 2 and abs(zc - pc) <= 2 for (pr, pc) in all_zones)

    # Zone columns: left of wire spine and right of road col
    left_zone_col = wire_col - 4   # center 4 left of wire (touches wire on right edge)
    right_zone_col = road_col + 4  # center 4 right of road (touches road on left edge)

    wire_rows_set = set(wire_rows_in_col)
    road_rows_set = set(r for (r, c) in road_positions if c == road_col)

    zone_rows = sorted(wire_rows_in_col)

    # Phase 5: place zones
    for zr in zone_rows:
        road_nearby = any(abs(zr - rr) <= 2 for rr in road_rows_set)
        wire_nearby = any(abs(zr - wr) <= 2 for wr in wire_rows_set)

        if not (road_nearby and wire_nearby):
            continue

        # Left zones (powered by lateral wire from spine)
        zc = left_zone_col
        if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
            if not zone_nearby(zr, zc) and zone_area_free(zr, zc):
                # Mix: 50% RES, 25% IND (lower rows), 25% COM (upper rows)
                if ind_count * 4 < res_count and zr >= cy:
                    return (Tool.INDUSTRIAL, zc, zr)
                elif com_count * 4 < res_count and zr < cy:
                    return (Tool.COMMERCIAL, zc, zr)
                else:
                    return (Tool.RESIDENTIAL, zc, zr)

        # Right zones (served by road)
        zc = right_zone_col
        if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
            if not zone_nearby(zr, zc) and zone_area_free(zr, zc):
                if com_count * 3 < res_count:
                    return (Tool.COMMERCIAL, zc, zr)
                elif ind_count * 3 < res_count and zr >= cy:
                    return (Tool.INDUSTRIAL, zc, zr)
                else:
                    return (Tool.RESIDENTIAL, zc, zr)

    # Phase 6: lateral wires from spine to left zones
    for wr in wire_rows_in_col:
        for wc in range(wire_col - 1, left_zone_col, -1):
            if 0 <= wc < WORLD_W and em[wr, wc]:
                return (Tool.WIRE, wc, wr)

    # Phase 7: lateral roads from road col to right zones
    for wr in wire_rows_in_col:
        for rc in range(road_col + 1, right_zone_col):
            if 0 <= rc < WORLD_W and em[wr, rc]:
                return (Tool.ROAD, rc, wr)

    # Phase 8: second expansion cluster to the right when population grows
    if obs.city_pop > 200:
        wire_col2 = road_col + 8
        road_col2 = wire_col2 + 2
        left_zone_col2 = wire_col2 - 4
        right_zone_col2 = road_col2 + 4

        # Extend horizontal wire from spine to wire_col2
        for wr in wire_rows_in_col:
            for wc in range(wire_col + 1, wire_col2 + 1):
                if 0 <= wc < WORLD_W and em[wr, wc]:
                    return (Tool.WIRE, wc, wr)

        # Wire spine 2
        wire2_rows = sorted(r for (r, c) in wire_positions if c == wire_col2)
        if not wire2_rows and wire_rows_in_col:
            seed = wire_rows_in_col[len(wire_rows_in_col) // 2]
            if 0 <= wire_col2 < WORLD_W and em[seed, wire_col2]:
                return (Tool.WIRE, wire_col2, seed)

        if wire2_rows:
            min_w2 = min(wire2_rows)
            max_w2 = max(wire2_rows)
            if max_w2 < tmax:
                nr = max_w2 + 1
                if 0 < nr < WORLD_H and (em[nr, wire_col2] or wm[nr, wire_col2]):
                    return (Tool.WIRE, wire_col2, nr)
            if min_w2 > tmin:
                nr = min_w2 - 1
                if 0 <= nr < WORLD_H and (em[nr, wire_col2] or wm[nr, wire_col2]):
                    return (Tool.WIRE, wire_col2, nr)

            # Road col2
            road2_rows = set(r for (r, c) in road_positions if c == road_col2)
            for wr in wire2_rows:
                if wr not in road2_rows and 0 <= road_col2 < WORLD_W and em[wr, road_col2]:
                    return (Tool.ROAD, road_col2, wr)

            # Zones in second cluster
            road2_set = road2_rows
            for zr in wire2_rows:
                road_near2 = any(abs(zr - rr) <= 2 for rr in road2_set)
                wire_near2 = True  # we're iterating wire2_rows
                if not (road_near2 and wire_near2):
                    continue
                for zc in [left_zone_col2, right_zone_col2]:
                    if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                        if not zone_nearby(zr, zc) and zone_area_free(zr, zc):
                            return (Tool.RESIDENTIAL, zc, zr)

            # Lateral wires to left zones of cluster 2
            for wr in wire2_rows:
                for wc in range(wire_col2 - 1, left_zone_col2, -1):
                    if 0 <= wc < WORLD_W and em[wr, wc]:
                        return (Tool.WIRE, wc, wr)

            # Lateral roads to right zones of cluster 2
            for wr in wire2_rows:
                for rc in range(road_col2 + 1, right_zone_col2):
                    if 0 <= rc < WORLD_W and em[wr, rc]:
                        return (Tool.ROAD, rc, wr)

    return None

def act(obs, state):
    """
    Grid-based city builder: creates multiple neighborhoods in a grid pattern
    with explicit road network and power distribution.

    Key differences from parent:
    1. Pre-planned grid layout stored in state (not purely reactive)
    2. Two power plants for redundancy
    3. Explicit horizontal + vertical road grid (not just flanking spine)
    4. Better zone balance targeting 50% R, 25% C, 25% I
    5. Builds two separate clusters for spatial diversity
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Initialize action queue on first call
    if 'queue' not in state:
        state['queue'] = []
        state['queue_idx'] = 0
        q = state['queue']

        # Cluster 1: centered at (40, 35)
        # Cluster 2: centered at (80, 65)
        clusters = [
            {'cx': 40, 'cy': 35, 'plant': (40, 22), 'power_col': 40},
            {'cx': 80, 'cy': 65, 'plant': (80, 52), 'power_col': 80},
        ]

        for c in clusters:
            cx, cy = c['cx'], c['cy']
            px, py = c['plant']
            pcol = c['power_col']

            # Place coal power plant
            q.append((Tool.COALPOWER, px, py))

            # Wire spine: vertical from plant down to bottom of cluster
            for wy in range(py + 2, cy + 20):
                q.append((Tool.WIRE, pcol, wy))

            # Horizontal wires connecting spine to zone areas
            for wx in range(pcol - 12, pcol + 13):
                for wy_off in [cy - 9, cy, cy + 9]:
                    q.append((Tool.WIRE, wx, wy_off))

            # Road grid: vertical roads at cx-9, cx-3, cx+3, cx+9
            for rx in [cx - 9, cx - 3, cx + 3, cx + 9]:
                for ry in range(cy - 14, cy + 15):
                    q.append((Tool.ROAD, rx, ry))

            # Road grid: horizontal roads at cy-9, cy-3, cy+3, cy+9
            for ry in [cy - 9, cy - 3, cy + 3, cy + 9]:
                for rx in range(cx - 12, cx + 13):
                    q.append((Tool.ROAD, rx, ry))

            # Place zones in grid cells between roads
            # Each cell is ~6 wide, 6 tall; zone center at cell center
            zone_positions = []
            for row_i, ry_center in enumerate([cy - 6, cy, cy + 6]):
                for col_i, rx_center in enumerate([cx - 6, cx, cx + 6]):
                    zone_positions.append((rx_center, ry_center, row_i, col_i))

            # Also outer ring
            for ry_center in [cy - 12, cy + 12]:
                for rx_center in [cx - 6, cx, cx + 6]:
                    zone_positions.append((rx_center, ry_center, 99, 99))
            for rx_center in [cx - 12, cx + 12]:
                for ry_center in [cy - 6, cy, cy + 6]:
                    zone_positions.append((rx_center, ry_center, 99, 99))

            for i, (zx, zy, ri, ci) in enumerate(zone_positions):
                # Balance: 50% R, 25% C, 25% I based on position
                mod = i % 4
                if mod == 0:
                    tool = Tool.COMMERCIAL
                elif mod == 1:
                    tool = Tool.INDUSTRIAL
                else:
                    tool = Tool.RESIDENTIAL
                q.append((tool, zx, zy))

        # Connect the two clusters with a road
        for rx in range(40, 81):
            q.append((Tool.ROAD, rx, 50))
        # Wire connecting the two power plants
        for wx in range(40, 81):
            q.append((Tool.WIRE, wx, 50))

        # Fire and police stations
        for c in clusters:
            cx, cy = c['cx'], c['cy']
            q.append((Tool.FIRESTATION, cx + 12, cy))
            q.append((Tool.POLICESTATION, cx - 12, cy))

    # Execute queued actions, but skip if tile is already occupied by something useful
    q = state['queue']
    idx = state['queue_idx']

    while idx < len(q):
        tool, x, y = q[idx]
        idx += 1

        if not in_bounds(x, y):
            continue

        # Don't overwrite existing power plant
        if bool(pm[y, x]) and tool != Tool.COALPOWER:
            continue

        # Don't place wire/road on top of plant
        if bool(pm[y, x]) and tool in (Tool.WIRE, Tool.ROAD):
            continue

        # Skip if wire already there and we want wire
        if tool == Tool.WIRE and bool(wm[y, x]):
            continue

        # Skip if road already there and we want road
        if tool == Tool.ROAD and bool(rm[y, x]):
            continue

        # For zones, check 3x3 clearance (but allow overwriting other zones)
        if tool in (Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.INDUSTRIAL):
            ok = True
            zone_mask = resm | comm | indm
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    ny2, nx2 = y + dr, x + dc
                    if not in_bounds(nx2, ny2):
                        ok = False; break
                    # Only allow empty tiles or same-type zones
                    if not bool(em[ny2, nx2]) and not bool(zone_mask[ny2, nx2]):
                        # Check it's not road/wire/plant
                        if bool(rm[ny2, nx2]) or bool(wm[ny2, nx2]) or bool(pm[ny2, nx2]):
                            ok = False; break
                if not ok:
                    break
            if not ok:
                continue

        state['queue_idx'] = idx
        return (tool, x, y)

    state['queue_idx'] = idx

    # Reactive fallback: extend roads from existing roads
    rys, rxs = np.where(rm)
    if len(rxs) > 0:
        k = int(obs.step * 7 + int(obs.city_pop * 3)) % len(rxs)
        rx2, ry2 = int(rxs[k]), int(rys[k])
        for ddx, ddy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nx2, ny2 = rx2 + ddx, ry2 + ddy
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Improved policy with:
    - Two separate neighborhoods (left and right of center)
    - Each neighborhood has its own power plant
    - Better zone mix targeting 40% RES, 30% COM, 30% IND
    - Horizontal road spine with vertical zone columns
    - Police/fire stations for happiness bonus
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    step = obs.step
    pop = obs.city_pop

    # Initialize state
    if 'phase' not in state:
        state['phase'] = 0
        state['action_queue'] = []

    # Helper: check if 3x3 area centered at (cx,cy) is clear
    def area_free(cx, cy):
        for dy in [-1, 0, 1]:
            for dx in [-1, 0, 1]:
                r, c = cy + dy, cx + dx
                if r < 0 or r >= WORLD_H or c < 0 or c >= WORLD_W:
                    return False
                if not em[r, c]:
                    return False
        return True

    def zone_exists_near(cx, cy, zmask, radius=2):
        r0, r1 = max(0, cy - radius), min(WORLD_H, cy + radius + 1)
        c0, c1 = max(0, cx - radius), min(WORLD_W, cx + radius + 1)
        return np.any(zmask[r0:r1, c0:c1])

    # Two neighborhoods:
    # Left: centered around x=35, y=50
    # Right: centered around x=85, y=50
    neighborhoods = [
        {'plant': (35, 50), 'road_row': 50, 'zone_cols': [29, 32, 38, 41], 
         'wire_col': 35, 'road_cols': [28, 42]},
        {'plant': (85, 50), 'road_row': 50, 'zone_cols': [79, 82, 88, 91],
         'wire_col': 85, 'road_cols': [78, 92]},
    ]

    # Phase structure using action queue
    if state['action_queue']:
        action = state['action_queue'].pop(0)
        return action

    def queue(actions):
        state['action_queue'].extend(actions)

    # Build each neighborhood
    for n_idx, nb in enumerate(neighborhoods):
        px, py = nb['plant']
        wc = nb['wire_col']
        rrow = nb['road_row']

        # Check if plant exists near this neighborhood
        plant_region = pm[py-2:py+3, px-2:px+3] if (py >= 2 and py+3 <= WORLD_H and px >= 2 and px+3 <= WORLD_W) else np.zeros((5,5), dtype=bool)
        has_local_plant = np.any(plant_region)

        if not has_local_plant:
            # Place coal power plant
            if area_free(px, py):
                return (Tool.COALPOWER, px, py)
            else:
                # Try nearby
                for dy in range(-3, 4):
                    for dx in range(-3, 4):
                        npx, npy = px + dx, py + dy
                        if area_free(npx, npy):
                            return (Tool.COALPOWER, npx, npy)

        # Build horizontal wire row through plant column area
        # Wire from plant rightward/leftward along road_row
        wire_row = rrow
        # Wire span around neighborhood
        wire_start = px - 8
        wire_end = px + 8

        for ww in range(wire_start, wire_end + 1):
            if 0 <= ww < WORLD_W and 0 < wire_row < WORLD_H:
                if not wm[wire_row, ww] and em[wire_row, ww]:
                    return (Tool.WIRE, ww, wire_row)

        # Build road rows above and below wire row (for zone access)
        road_above = rrow - 5
        road_below = rrow + 5
        road_start = px - 10
        road_end = px + 10

        for road_row_target in [road_above, road_below]:
            if 0 < road_row_target < WORLD_H:
                for rc in range(road_start, road_end + 1):
                    if 0 <= rc < WORLD_W:
                        if not rm[road_row_target, rc] and em[road_row_target, rc]:
                            return (Tool.ROAD, rc, road_row_target)

        # Connect roads to wire with vertical road segments
        for rc in range(road_start, road_end + 1, 4):
            if 0 <= rc < WORLD_W:
                for ry in range(min(road_above, wire_row), max(road_above, wire_row) + 1):
                    if 0 <= ry < WORLD_H and not rm[ry, rc] and em[ry, rc]:
                        return (Tool.ROAD, rc, ry)
                for ry in range(min(wire_row, road_below), max(wire_row, road_below) + 1):
                    if 0 <= ry < WORLD_H and not rm[ry, rc] and em[ry, rc]:
                        return (Tool.ROAD, rc, ry)

        # Place zones between road rows
        # Zone rows: between road_above and road_below, centered
        zone_y_above = road_above + 3  # zone center above wire
        zone_y_below = road_below - 3  # zone center below wire

        rm_now = road_mask(tm)
        wm_now = wire_mask(tm)

        res_m = res_mask(tm)
        com_m = com_mask(tm)
        ind_m = ind_mask(tm)

        res_count = np.sum(res_m) // 9
        com_count = np.sum(com_m) // 9
        ind_count = np.sum(ind_m) // 9
        total_zones = res_count + com_count + ind_count + 1

        def pick_zone_type():
            # Target: 40% res, 30% com, 30% ind
            r_frac = res_count / total_zones
            c_frac = com_count / total_zones
            i_frac = ind_count / total_zones
            if r_frac < 0.40:
                return Tool.RESIDENTIAL
            elif c_frac < 0.30:
                return Tool.COMMERCIAL
            elif i_frac < 0.30:
                return Tool.INDUSTRIAL
            else:
                return Tool.RESIDENTIAL

        for zy in [zone_y_above, zone_y_below]:
            if 1 <= zy <= WORLD_H - 2:
                for zx in range(road_start + 2, road_end - 1, 4):
                    if 1 <= zx <= WORLD_W - 2:
                        if not zone_exists_near(zx, zy, res_m | com_m | ind_m, 1):
                            if area_free(zx, zy):
                                # Wire connection from nearest wire row
                                # Add wire from zone edge to wire row if needed
                                wire_needed = False
                                for wry in range(min(zy, wire_row), max(zy, wire_row) + 1):
                                    if 0 <= wry < WORLD_H and not wm[wry, zx] and em[wry, zx]:
                                        wire_needed = True
                                        break
                                if wire_needed:
                                    # Place wire vertically connecting zone to wire row
                                    for wry in range(min(zy+2, wire_row), max(zy-2, wire_row) + 1):
                                        if 0 <= wry < WORLD_H and em[wry, zx]:
                                            return (Tool.WIRE, zx, wry)
                                zt = pick_zone_type()
                                return (zt, zx, zy)

    # Add police/fire stations for city happiness if population warrants it
    if pop > 200:
        # Place police station near center of each neighborhood
        for px, py in [(35, 44), (85, 44)]:
            if area_free(px, py):
                # Check if any police station nearby
                pol_nearby = False
                for dy in range(-6, 7):
                    for dx in range(-6, 7):
                        r, c = py + dy, px + dx
                        if 0 <= r < WORLD_H and 0 <= c < WORLD_W:
                            # police station tiles are around 600-620 range
                            if tm[r, c] >= 600 and tm[r, c] <= 750:
                                pol_nearby = True
                if not pol_nearby:
                    return (Tool.POLICESTATION, px, py)

    if pop > 400:
        for px, py in [(35, 56), (85, 56)]:
            if area_free(px, py):
                return (Tool.FIRESTATION, px, py)

    # Expand zones further out if population is growing
    if pop > 300:
        # Try to place more zones in extended area
        for n_idx, nb in enumerate(neighborhoods):
            px = nb['plant'][0]
            py = nb['plant'][1]
            rrow = nb['road_row']
            res_m = res_mask(tm)
            com_m = com_mask(tm)
            ind_m = ind_mask(tm)

            for zy in [rrow - 9, rrow + 9]:
                if 1 <= zy <= WORLD_H - 2:
                    for zx in range(px - 12, px + 13, 4):
                        if 1 <= zx <= WORLD_W - 2:
                            if not zone_exists_near(zx, zy, res_m | com_m | ind_m, 1):
                                if area_free(zx, zy):
                                    return (Tool.RESIDENTIAL, zx, zy)

    return None

def act(obs, state):
    """
    Improved policy:
    - Build a horizontal road spine (east-west) instead of vertical wire spine
    - Place zones ABOVE and BELOW the road
    - Wire runs parallel to road for power
    - More compact cluster, better zone mix
    - Multiple clusters from the start
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    step = obs.step

    # Initialize state
    if "phase" not in state:
        state["phase"] = 0
        state["action_queue"] = []

    # Use a build queue for deterministic placement
    def enqueue(actions):
        state["action_queue"].extend(actions)

    if state["action_queue"]:
        act_item = state["action_queue"].pop(0)
        return act_item

    has_plant = np.any(pm)
    has_wire = np.any(wm)
    has_road = np.any(rm)

    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)
    all_zone_m = res_m | com_m | ind_m

    # Count zones (approximate)
    res_count = max(1, int(np.sum(res_m)) // 9)
    com_count = max(1, int(np.sum(com_m)) // 9)
    ind_count = max(1, int(np.sum(ind_m)) // 9)

    def zone_area_free(zr, zc):
        """Check 3x3 area is empty"""
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def nearby_zone(zr, zc, radius=3):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(all_zone_m[r0:r1, c0:c1])

    def pick_zone():
        # Target: 50% res, 30% com, 20% ind
        total = res_count + com_count + ind_count
        if ind_count / total < 0.20:
            return Tool.INDUSTRIAL
        elif com_count / total < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # === CLUSTER DEFINITIONS ===
    # Each cluster: (plant_x, plant_y, road_row, wire_row, x_start, x_end)
    # Zones above and below road row
    clusters = [
        # Cluster 1: left side
        {"px": 20, "py": 45, "road_y": 48, "wire_y": 47, "x0": 16, "x1": 50},
        # Cluster 2: center
        {"px": 65, "py": 45, "road_y": 48, "wire_y": 47, "x0": 56, "x1": 90},
    ]

    # Phase 0: Place power plants
    if not has_plant:
        # Place first power plant
        c = clusters[0]
        return (Tool.COALPOWER, c["px"], c["py"])

    plant_rows, plant_cols = np.where(pm)
    plant_positions = list(zip(plant_rows.tolist(), plant_cols.tolist()))

    # Check if we need second plant
    plant_xs = set(plant_cols.tolist())
    need_plant2 = clusters[1]["px"] not in plant_xs and all(
        abs(clusters[1]["px"] - px) > 5 for px in plant_xs
    )

    # === Build cluster infrastructure ===
    for ci, c in enumerate(clusters):
        px, py = c["px"], c["py"]
        road_y = c["road_y"]
        wire_y = c["wire_y"]
        x0, x1 = c["x0"], c["x1"]

        # Skip cluster 2 until cluster 1 is established or pop threshold
        if ci == 1:
            if obs.city_pop < 100 and not np.any(pm[py-1:py+2, px-1:px+2]):
                continue

        # Place plant if missing for this cluster
        plant_here = np.any(pm[max(0,py-1):min(WORLD_H,py+2), max(0,px-1):min(WORLD_W,px+2)])
        if not plant_here:
            # Check area is clear enough
            area_ok = True
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    rr, rc = py+dr, px+dc
                    if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                        if not em[rr, rc]:
                            area_ok = False
                            break
            if area_ok:
                return (Tool.COALPOWER, px, py)
            else:
                # Bulldoze and place
                return (Tool.COALPOWER, px, py)

        # Wire from plant to wire spine row
        # Connect plant (at py) down to wire_y via vertical wire at px
        if wire_y > py:
            for wy in range(py + 2, wire_y + 1):
                if 0 <= wy < WORLD_H and not wm[wy, px] and not pm[wy, px]:
                    return (Tool.WIRE, px, wy)
        elif wire_y < py:
            for wy in range(py - 2, wire_y - 1, -1):
                if 0 <= wy < WORLD_H and not wm[wy, px] and not pm[wy, px]:
                    return (Tool.WIRE, px, wy)

        # Horizontal wire spine from x0 to x1 at wire_y
        for wx in range(x0, x1 + 1):
            if 0 <= wx < WORLD_W:
                if not wm[wire_y, wx] and not pm[wire_y, wx]:
                    return (Tool.WIRE, wx, wire_y)

        # Horizontal road spine from x0 to x1 at road_y
        for rx in range(x0, x1 + 1):
            if 0 <= rx < WORLD_W:
                if not rm[road_y, rx] and not pm[road_y, rx]:
                    return (Tool.ROAD, rx, road_y)

        # Short vertical roads connecting wire to road at every 4 cols
        for rx in range(x0 + 2, x1 - 1, 4):
            if 0 <= rx < WORLD_W:
                # vertical connector at this col between wire_y and road_y
                miny = min(wire_y, road_y)
                maxy = max(wire_y, road_y)
                for ry in range(miny, maxy + 1):
                    if not rm[ry, rx] and not wm[ry, rx] and not pm[ry, rx]:
                        return (Tool.WIRE, rx, ry)

        # Place zones above road (row = road_y - 3)
        zone_y_above = road_y - 3
        # Place zones below road (row = road_y + 3)
        zone_y_below = road_y + 3

        for zx in range(x0 + 3, x1 - 2, 4):
            if 0 <= zx < WORLD_W:
                # Above road
                if 0 <= zone_y_above < WORLD_H:
                    if not nearby_zone(zone_y_above, zx, radius=2) and zone_area_free(zone_y_above, zx):
                        return (pick_zone(), zx, zone_y_above)
                # Below road
                if 0 <= zone_y_below < WORLD_H:
                    if not nearby_zone(zone_y_below, zx, radius=2) and zone_area_free(zone_y_below, zx):
                        return (pick_zone(), zx, zone_y_below)

        # Second row of zones further out
        zone_y_above2 = road_y - 7
        zone_y_below2 = road_y + 7

        for zx in range(x0 + 3, x1 - 2, 4):
            if 0 <= zx < WORLD_W:
                if 0 <= zone_y_above2 < WORLD_H:
                    if not nearby_zone(zone_y_above2, zx, radius=2) and zone_area_free(zone_y_above2, zx):
                        return (pick_zone(), zx, zone_y_above2)
                if 0 <= zone_y_below2 < WORLD_H:
                    if not nearby_zone(zone_y_below2, zx, radius=2) and zone_area_free(zone_y_below2, zx):
                        return (pick_zone(), zx, zone_y_below2)

    # === Connect the two clusters with a road ===
    if obs.city_pop > 50:
        road_y = clusters[0]["road_y"]
        x_bridge_start = clusters[0]["x1"]
        x_bridge_end = clusters[1]["x0"]
        for bx in range(x_bridge_start, x_bridge_end + 1):
            if 0 <= bx < WORLD_W and not rm[road_y, bx]:
                return (Tool.ROAD, bx, road_y)
        # Also bridge wire
        wire_y = clusters[0]["wire_y"]
        for bx in range(x_bridge_start, x_bridge_end + 1):
            if 0 <= bx < WORLD_W and not wm[wire_y, bx] and not pm[wire_y, bx]:
                return (Tool.WIRE, bx, wire_y)

    # === Third cluster if pop growing ===
    if obs.city_pop > 300:
        c3 = {"px": 100, "py": 30, "road_y": 33, "wire_y": 32, "x0": 91, "x1": 118}
        px, py = c3["px"], c3["py"]
        road_y = c3["road_y"]
        wire_y = c3["wire_y"]
        x0, x1 = c3["x0"], c3["x1"]

        plant_here = np.any(pm[max(0,py-1):min(WORLD_H,py+2), max(0,px-1):min(WORLD_W,px+2)])
        if not plant_here:
            return (Tool.COALPOWER, px, py)

        # Wire vertical from plant to wire_y
        for wy in range(py + 2, wire_y + 1):
            if 0 <= wy < WORLD_H and not wm[wy, px] and not pm[wy, px]:
                return (Tool.WIRE, px, wy)

        for wx in range(x0, x1 + 1):
            if 0 <= wx < WORLD_W and not wm[wire_y, wx] and not pm[wire_y, wx]:
                return (Tool.WIRE, wx, wire_y)

        for rx in range(x0, x1 + 1):
            if 0 <= rx < WORLD_W and not rm[road_y, rx] and not pm[road_y, rx]:
                return (Tool.ROAD, rx, road_y)

        zone_y_above = road_y - 3
        zone_y_below = road_y + 3
        for zx in range(x0 + 3, x1 - 2, 4):
            if 0 <= zx < WORLD_W:
                if 0 <= zone_y_above < WORLD_H:
                    if not nearby_zone(zone_y_above, zx, radius=2) and zone_area_free(zone_y_above, zx):
                        return (pick_zone(), zx, zone_y_above)
                if 0 <= zone_y_below < WORLD_H:
                    if not nearby_zone(zone_y_below, zx, radius=2) and zone_area_free(zone_y_below, zx):
                        return (pick_zone(), zx, zone_y_below)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder.
    Each step reads the current map and decides what to place next based on
    what already exists, adapting dynamically to the observed state.

    Strategy:
    - Find existing power plant or place one
    - Grow wire network outward from plant, following existing wires
    - Grow road spine outward from road start, following existing roads
    - Place zones adjacent to both road and wire coverage
    - Expand incrementally based on what's currently on the map
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    all_zones = resm | comm | indm

    # Step 1: Ensure we have a power plant
    if not np.any(pm):
        # Place coal plant at left-center area
        px, py = 12, WORLD_H // 2
        return (Tool.COALPOWER, px, py)

    # Find plant center
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Zone type picker based on current counts
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(total_zones, 1)
        if com_count / t < 0.28:
            return Tool.COMMERCIAL
        if ind_count / t < 0.18:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Road spine: horizontal, one row below plant center
    road_row = plant_cy + 1
    road_row = max(3, min(WORLD_H - 4, road_row))

    # Wire spine: vertical, just right of plant
    wire_col = plant_cx + 2
    wire_col = max(2, min(WORLD_W - 3, wire_col))

    # Helper: check if position is safe (not destroying plant)
    def safe(r, c):
        return 0 <= r < WORLD_H and 0 <= c < WORLD_W and not pm[r, c]

    # Helper: wire reachable means adjacent to existing wire or plant
    def wire_adjacent(r, c):
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < WORLD_H and 0 <= nc < WORLD_W:
                if wm[nr, nc] or pm[nr, nc]:
                    return True
        return False

    # Helper: road reachable means adjacent to existing road
    def road_adjacent(r, c):
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < WORLD_H and 0 <= nc < WORLD_W:
                if rm[nr, nc]:
                    return True
        return False

    # Determine current road/wire extents
    road_cols_on_row = np.where(rm[road_row, :])[0]
    if len(road_cols_on_row) > 0:
        road_max_col = int(np.max(road_cols_on_row))
        road_min_col = int(np.min(road_cols_on_row))
    else:
        road_max_col = plant_cx
        road_min_col = plant_cx + 1

    wire_rows_on_col = np.where(wm[:, wire_col])[0]
    if len(wire_rows_on_col) > 0:
        wire_min_row = int(np.min(wire_rows_on_col))
        wire_max_row = int(np.max(wire_rows_on_col))
    else:
        wire_min_row = plant_cy
        wire_max_row = plant_cy

    # Adaptive extents based on population
    pop = obs.city_pop
    if pop < 100:
        target_road_cols = 20
        target_wire_rows = 12
    elif pop < 300:
        target_road_cols = 35
        target_wire_rows = 18
    elif pop < 600:
        target_road_cols = 50
        target_wire_rows = 25
    else:
        target_road_cols = 65
        target_wire_rows = 32

    road_end = min(WORLD_W - 3, plant_cx + target_road_cols)
    wire_top = max(2, road_row - target_wire_rows)
    wire_bot = min(WORLD_H - 3, road_row + target_wire_rows)

    # Phase A: Extend wire vertically (up from plant)
    # Connect from plant upward
    if wire_min_row > wire_top:
        # find topmost wire, extend up
        next_r = wire_min_row - 1
        if safe(next_r, wire_col) and em[next_r, wire_col]:
            return (Tool.WIRE, wire_col, next_r)

    # Phase B: Extend wire vertically (down from plant)
    if wire_max_row < wire_bot:
        next_r = wire_max_row + 1
        if safe(next_r, wire_col) and em[next_r, wire_col]:
            return (Tool.WIRE, wire_col, next_r)

    # Phase C: Build initial wire connection from plant to wire_col
    # Check if wire_col has any wire at road_row level
    if not wm[road_row, wire_col] and not pm[road_row, wire_col]:
        # Walk wire from plant to wire_col at road_row
        for c in range(plant_cx + 1, wire_col + 1):
            if safe(road_row, c) and em[road_row, c] and not wm[road_row, c]:
                return (Tool.WIRE, c, road_row)

    # Phase D: Extend road east from plant (start right of plant)
    road_start_col = plant_cx + 1
    if road_max_col < road_end:
        # Extend from current max
        next_c = road_max_col + 1
        if next_c <= road_end and safe(road_row, next_c) and em[road_row, next_c]:
            return (Tool.ROAD, next_c, road_row)
        # If blocked, skip
        for nc in range(road_max_col + 1, road_end + 1):
            if safe(road_row, nc) and (em[road_row, nc] or True):
                if not rm[road_row, nc] and not pm[road_row, nc]:
                    return (Tool.ROAD, nc, road_row)
                elif not rm[road_row, nc]:
                    break
    elif len(road_cols_on_row) == 0:
        # No road yet, start it
        c = road_start_col
        if safe(road_row, c) and not pm[road_row, c]:
            return (Tool.ROAD, c, road_row)

    # Phase E: Extend horizontal wire 1 row above road (to power zones above)
    w_row_above = road_row - 1
    if w_row_above >= 1:
        wire_cols_above = np.where(wm[w_row_above, :])[0]
        if len(wire_cols_above) > 0:
            wire_above_max = int(np.max(wire_cols_above))
        else:
            wire_above_max = wire_col - 1

        # Extend wire above road eastward
        target_wire_above_end = road_end + 1
        if wire_above_max < target_wire_above_end:
            # Find next position: either start from wire_col or extend
            if len(wire_cols_above) == 0:
                # Place first wire above at wire_col
                if safe(w_row_above, wire_col) and em[w_row_above, wire_col]:
                    return (Tool.WIRE, wire_col, w_row_above)
            else:
                nc = wire_above_max + 1
                if nc <= target_wire_above_end and safe(w_row_above, nc) and em[w_row_above, nc]:
                    return (Tool.WIRE, nc, w_row_above)

    # Phase F: Extend horizontal wire 1 row below road (to power zones below)
    w_row_below = road_row + 1
    if w_row_below < WORLD_H - 1:
        wire_cols_below = np.where(wm[w_row_below, :])[0]
        if len(wire_cols_below) > 0:
            wire_below_max = int(np.max(wire_cols_below))
        else:
            wire_below_max = wire_col - 1

        target_wire_below_end = road_end + 1
        if wire_below_max < target_wire_below_end:
            if len(wire_cols_below) == 0:
                if safe(w_row_below, wire_col) and em[w_row_below, wire_col]:
                    return (Tool.WIRE, wire_col, w_row_below)
            else:
                nc = wire_below_max + 1
                if nc <= target_wire_below_end and safe(w_row_below, nc) and em[w_row_below, nc]:
                    return (Tool.WIRE, nc, w_row_below)

    # Phase G: Place zones reactively
    # Scan for positions that have both road and wire access, and are empty
    def zone_placeable(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        # Check 3x3 footprint is clear
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zones[rr, rc]:
                    return False
        return True

    def has_road_access(zr, zc, r=3):
        r0, r1 = max(0, zr-r), min(WORLD_H, zr+r+1)
        c0, c1 = max(0, zc-r), min(WORLD_W, zc+r+1)
        return np.any(rm[r0:r1, c0:c1])

    def has_power_access(zr, zc, r=4):
        r0, r1 = max(0, zr-r), min(WORLD_H, zr+r+1)
        c0, c1 = max(0, zc-r), min(WORLD_W, zc+r+1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def already_zoned(zr, zc):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                rr, rc = zr+dr, zc+dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zones[rr, rc]:
                        return True
        return False

    # Try to place zones in rows adjacent to road spine
    # Zone rows: road_row - 2 (above) and road_row + 2 (below)
    # Scan columns along road
    zone_rows = [road_row - 2, road_row + 2]
    # Also try further rows if expanding
    if pop > 200:
        zone_rows += [road_row - 5, road_row + 5]
    if pop > 500:
        zone_rows += [road_row - 8, road_row + 8]

    # Find current road extent for zone placement
    current_road_end = road_max_col

    for zr in zone_rows:
        if zr < 2 or zr > WORLD_H - 3:
            continue
        # Scan zone columns every 4 tiles along road
        for zc in range(plant_cx + 3, current_road_end - 1, 4):
            if zc < 2 or zc > WORLD_W - 3:
                continue
            if already_zoned(zr, zc):
                continue
            if zone_placeable(zr, zc) and has_road_access(zr, zc) and has_power_access(zr, zc):
                return (pick_tool(), zc, zr)

    # Phase H: Second power plant when population grows
    if pop > 250 and int(np.sum(pm)) < 10:
        # Place near right end of road
        px2 = min(WORLD_W - 5, road_end - 2)
        py2 = road_row - 4
        if 2 <= px2 <= WORLD_W - 4 and 2 <= py2 <= WORLD_H - 4:
            # Check area is mostly empty
            area = tm[py2-1:py2+2, px2-1:px2+2]
            if np.all(em[py2-1:py2+2, px2-1:px2+2]):
                return (Tool.COALPOWER, px2, py2)
            # Try other locations
            for dy in range(-2, 5):
                for dx in range(-2, 3):
                    px3, py3 = px2 + dx, py2 + dy
                    if 2 <= px3 <= WORLD_W - 4 and 2 <= py3 <= WORLD_H - 4:
                        if np.all(em[py3-1:py3+2, px3-1:px3+2]):
                            return (Tool.COALPOWER, px3, py3)

    # Phase I: Connect second plant to wire grid
    if int(np.sum(pm)) >= 18:
        plant_tiles_r, plant_tiles_c = np.where(pm)
        right_c = int(np.max(plant_tiles_c))
        rows_at_right = plant_tiles_r[plant_tiles_c >= right_c - 1]
        if len(rows_at_right) > 0:
            right_r = int(np.mean(rows_at_right))
            # Wire from this plant toward wire_col at right_r row
            if not wm[right_r, wire_col] and not pm[right_r, wire_col]:
                # find nearest wire to right plant
                wires_this_row = np.where(wm[right_r, :])[0]
                if len(wires_this_row) > 0:
                    nearest_w = wires_this_row[np.argmin(np.abs(wires_this_row - right_c))]
                    # Fill gap
                    lo, hi = min(nearest_w, right_c), max(nearest_w, right_c)
                    for c in range(lo + 1, hi):
                        if not wm[right_r, c] and not pm[right_r, c] and safe(right_r, c):
                            if em[right_r, c]:
                                return (Tool.WIRE, c, right_r)
                else:
                    # Wire downward from plant to road_row
                    for r in range(min(right_r, road_row), max(right_r, road_row) + 1):
                        if safe(r, right_c - 1) and em[r, right_c - 1] and not wm[r, right_c - 1]:
                            return (Tool.WIRE, right_c - 1, r)

    # Phase J: Services
    if pop > 200:
        cx_map = WORLD_W // 2
        cy_map = WORLD_H // 2
        ps_x = min(WORLD_W - 3, road_max_col - 5)
        ps_y = road_row - 3
        if 2 <= ps_x <= WORLD_W - 3 and 2 <= ps_y <= WORLD_H - 3:
            if em[ps_y, ps_x]:
                return (Tool.POLICESTATION, ps_x, ps_y)

    if pop > 400:
        fs_x = min(WORLD_W - 3, road_max_col - 10)
        fs_y = road_row + 3
        if 2 <= fs_x <= WORLD_W - 3 and 2 <= fs_y <= WORLD_H - 3:
            if em[fs_y, fs_x]:
                return (Tool.FIRESTATION, fs_x, fs_y)

    # Phase K: Add perpendicular roads for better zone access
    if pop > 150:
        # Add short vertical roads at zone columns to reach further zones
        for zc in range(plant_cx + 3, current_road_end - 1, 8):
            if zc < 2 or zc > WORLD_W - 3:
                continue
            # Road from road_row-1 to road_row-3
            for r in [road_row - 1, road_row - 2, road_row - 3]:
                if safe(r, zc) and em[r, zc] and not rm[r, zc]:
                    if road_adjacent(r, zc):
                        return (Tool.ROAD, zc, r)
            for r in [road_row + 1, road_row + 2, road_row + 3]:
                if safe(r, zc) and em[r, zc] and not rm[r, zc]:
                    if road_adjacent(r, zc):
                        return (Tool.ROAD, zc, r)

    return None

def act(obs, state):
    """
    Improved policy: builds TWO neighborhoods side by side,
    one on each side of center, each with its own road+wire column.
    Better zone mix: 40% RES, 30% COM, 30% IND.
    Larger vertical span from the start.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    cx, cy = 60, 50  # map center

    has_plant = np.any(pm)

    # Phase 1: place coal power plant at center
    plant_cx, plant_cy = cx, cy
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Gather positions
    wire_positions = set(zip(*np.where(wm))) if np.any(wm) else set()
    road_positions = set(zip(*np.where(rm))) if np.any(rm) else set()
    res_pos = set(zip(*np.where(res_mask(tm))))
    com_pos = set(zip(*np.where(com_mask(tm))))
    ind_pos = set(zip(*np.where(ind_mask(tm))))
    all_zones = res_pos | com_pos | ind_pos

    res_count = len(res_pos)
    com_count = len(com_pos)
    ind_count = len(ind_pos)
    total_zones = res_count + com_count + ind_count

    # Two neighborhoods: LEFT (west of plant) and RIGHT (east of plant)
    # Plant center at (cx, cy), footprint cx-1..cx+1, cy-1..cy+1
    # Left neighborhood: wire at cx-4, road at cx-5, zones at cx-8
    # Right neighborhood: wire at cx+4, road at cx+5, zones at cx+8

    left_wire_col = cx - 4
    left_road_col = cx - 5
    left_zone_col = cx - 8

    right_wire_col = cx + 4
    right_road_col = cx + 5
    right_zone_col = cx + 8

    # Vertical span grows with population
    base_span = 12
    extra_span = min(25, obs.city_pop // 30)
    target_span = base_span + extra_span
    tmin = max(2, cy - target_span)
    tmax = min(WORLD_H - 3, cy + target_span)

    def extend_wire_col(wcol):
        """Try to extend wire in wcol from cy outward to tmin..tmax. Returns action or None."""
        rows = sorted(r for (r, c) in wire_positions if c == wcol)
        if not rows:
            # Start at cy
            if em[cy, wcol] or wm[cy, wcol]:
                return (Tool.WIRE, wcol, cy)
            return None
        mn, mx = min(rows), max(rows)
        if mx < tmax:
            nr = mx + 1
            if 0 <= nr < WORLD_H and (em[nr, wcol] or wm[nr, wcol]):
                return (Tool.WIRE, wcol, nr)
        if mn > tmin:
            nr = mn - 1
            if 0 <= nr < WORLD_H and (em[nr, wcol] or wm[nr, wcol]):
                return (Tool.WIRE, wcol, nr)
        return None

    def extend_road_col(rcol, wire_rows):
        """Place road in rcol where wire_rows exist but road doesn't yet. Returns action or None."""
        road_rows_set = set(r for (r, c) in road_positions if c == rcol)
        for wr in sorted(wire_rows):
            if wr not in road_rows_set and 0 <= rcol < WORLD_W:
                if em[wr, rcol]:
                    return (Tool.ROAD, rcol, wr)
        return None

    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def already_zone_nearby(zr, zc):
        return any(abs(zr - pr) <= 1 and abs(zc - pc) <= 1 for (pr, pc) in all_zones)

    def pick_zone_type(zr, zc, side):
        # Target: ~40% RES, 30% COM, 30% IND
        # Use modular placement for diversity
        idx = total_zones
        if ind_count * 10 < total_zones * 3 + 1:
            # Need more industrial
            if side == 'right' and zr >= cy:
                return Tool.INDUSTRIAL
        if com_count * 10 < total_zones * 3 + 1:
            # Need more commercial
            if side == 'left' and zr <= cy:
                return Tool.COMMERCIAL
        # fallback by position
        seg = (zr // 3) % 3
        if seg == 0:
            return Tool.RESIDENTIAL
        elif seg == 1:
            return Tool.COMMERCIAL
        else:
            return Tool.INDUSTRIAL

    # Connect plant to left wire: wire from plant_cx-2 to left_wire_col
    # Connect plant to right wire: wire from plant_cx+2 to right_wire_col
    # Plant footprint: cols cx-1..cx+1, rows cy-1..cy+1
    # We need wire bridge from plant edge to wire columns

    def connect_plant_to_wire(target_col):
        """Place wire horizontally at cy between plant edge and target_col."""
        if target_col < cx:
            # going left: from cx-2 down to target_col+1
            for wc in range(cx - 2, target_col - 1, -1):
                if 0 <= wc < WORLD_W and (em[cy, wc] or wm[cy, wc]):
                    return (Tool.WIRE, wc, cy)
        else:
            # going right: from cx+2 up to target_col
            for wc in range(cx + 2, target_col + 1):
                if 0 <= wc < WORLD_W and (em[cy, wc] or wm[cy, wc]):
                    return (Tool.WIRE, wc, cy)
        return None

    # Check if left/right wire is connected to plant
    left_wire_rows = sorted(r for (r, c) in wire_positions if c == left_wire_col)
    right_wire_rows = sorted(r for (r, c) in wire_positions if c == right_wire_col)

    # Horizontal wire bridge at cy
    left_bridge_complete = all(wm[cy, wc] or pm[cy, wc] for wc in range(left_wire_col, cx - 1))
    right_bridge_complete = all(wm[cy, wc] or pm[cy, wc] for wc in range(cx + 2, right_wire_col + 1))

    # Step 1: build left bridge
    if not left_bridge_complete:
        act_ = connect_plant_to_wire(left_wire_col)
        if act_:
            return act_

    # Step 2: build right bridge
    if not right_bridge_complete:
        act_ = connect_plant_to_wire(right_wire_col)
        if act_:
            return act_

    # Step 3: extend left wire vertically
    act_ = extend_wire_col(left_wire_col)
    if act_:
        return act_

    # Step 4: extend right wire vertically
    act_ = extend_wire_col(right_wire_col)
    if act_:
        return act_

    # Step 5: build roads
    act_ = extend_road_col(left_road_col, left_wire_rows if left_wire_rows else [cy])
    if act_:
        return act_

    act_ = extend_road_col(right_road_col, right_wire_rows if right_wire_rows else [cy])
    if act_:
        return act_

    # Step 6: connect wire laterally to zone columns
    def add_lateral_wire(wire_col, from_col, to_col, wire_rows):
        """Add wire from wire_col toward zone column at zone rows."""
        step = 1 if to_col > from_col else -1
        for wr in wire_rows:
            for wc in range(from_col + step, to_col + step, step):
                if 0 <= wc < WORLD_W and em[wr, wc]:
                    return (Tool.WIRE, wc, wr)
        return None

    def add_lateral_road(road_col, from_col, to_col, road_rows):
        step = 1 if to_col > from_col else -1
        for rr in road_rows:
            for rc in range(from_col + step, to_col + step, step):
                if 0 <= rc < WORLD_W and em[rr, rc]:
                    return (Tool.ROAD, rc, rr)
        return None

    # Left lateral wire: from left_wire_col toward left_zone_col (going left)
    if left_wire_rows:
        act_ = add_lateral_wire(left_wire_col, left_wire_col, left_zone_col + 1, left_wire_rows)
        if act_:
            return act_

    # Right lateral wire: from right_wire_col toward right_zone_col (going right)
    if right_wire_rows:
        act_ = add_lateral_wire(right_wire_col, right_wire_col, right_zone_col - 1, right_wire_rows)
        if act_:
            return act_

    # Left lateral road: from left_road_col toward left_zone_col
    left_road_rows = sorted(r for (r, c) in road_positions if c == left_road_col)
    if left_road_rows:
        act_ = add_lateral_road(left_road_col, left_road_col, left_zone_col + 1, left_road_rows)
        if act_:
            return act_

    # Right lateral road
    right_road_rows = sorted(r for (r, c) in road_positions if c == right_road_col)
    if right_road_rows:
        act_ = add_lateral_road(right_road_col, right_road_col, right_zone_col - 1, right_road_rows)
        if act_:
            return act_

    # Step 7: place zones
    def place_zones(zone_col, wire_rows, road_rows_set, side):
        for zr in sorted(wire_rows):
            road_nearby = any(abs(zr - rr) <= 2 for rr in road_rows_set)
            wire_nearby = True  # wire_rows already from wire col
            if not road_nearby:
                continue
            if not already_zone_nearby(zr, zone_col) and zone_area_free(zr, zone_col):
                zt = pick_zone_type(zr, zone_col, side)
                return (zt, zone_col, zr)
        return None

    left_road_rows_set = set(r for (r, c) in road_positions if c == left_road_col)
    right_road_rows_set = set(r for (r, c) in road_positions if c == right_road_col)

    if left_wire_rows:
        act_ = place_zones(left_zone_col, left_wire_rows, left_road_rows_set, 'left')
        if act_:
            return act_

    if right_wire_rows:
        act_ = place_zones(right_zone_col, right_wire_rows, right_road_rows_set, 'right')
        if act_:
            return act_

    # Step 8: also place zones on the road-side of each neighborhood
    # Left inner zone col (between wire and road): left_wire_col - 2 maybe already covered
    # Additional outer columns for bigger neighborhoods
    if obs.city_pop > 200:
        left_zone_col2 = left_zone_col - 4
        right_zone_col2 = right_zone_col + 4
        if left_wire_rows and 0 <= left_zone_col2 < WORLD_W:
            # Extend lateral wire further
            for wr in left_wire_rows:
                for wc in range(left_zone_col, left_zone_col2 - 1, -1):
                    if em[wr, wc]:
                        return (Tool.WIRE, wc, wr)
            act_ = place_zones(left_zone_col2, left_wire_rows, left_road_rows_set, 'left')
            if act_:
                return act_
        if right_wire_rows and 0 <= right_zone_col2 < WORLD_W:
            for wr in right_wire_rows:
                for wc in range(right_zone_col, right_zone_col2 + 1):
                    if em[wr, wc]:
                        return (Tool.WIRE, wc, wr)
            act_ = place_zones(right_zone_col2, right_wire_rows, right_road_rows_set, 'right')
            if act_:
                return act_

    return None

def act(obs, state):
    """
    Grid-based city layout:
    - Place coal power plant first
    - Build horizontal road and wire rows
    - Place zones (RES/COM/IND) on both sides of roads
    - Connect power via wires
    - Use a compact grid pattern centered on the map
    """

    # Initialize state
    if 'plan' not in state:
        state['plan'] = []
        state['plan_idx'] = 0
        state['built'] = set()

        # Layout parameters
        cx, cy = 60, 50  # center of city

        # Power plant at top-left of cluster
        plant_x, plant_y = 45, 20

        actions = []

        # Place coal power plant
        actions.append((Tool.COALPOWER, plant_x, plant_y))

        # Build two horizontal road rows with wire above each
        # Road rows at y=30, y=42, y=54 (spacing 12 apart)
        # Wire rows at y=29, y=41, y=53 (just above road)
        # Zones at y=27,28 (above wire) and y=32,33 (below road)

        road_rows = [30, 42, 54, 66]
        x_start = 38
        x_end = 82  # road spans from x=38 to x=82

        # Connect plant to first wire row with vertical wire
        # Plant is at (45,20), first wire row at y=29
        # Wire from y=22 down to y=29 at x=45
        for wy in range(22, 30):
            actions.append((Tool.WIRE, plant_x, wy))

        # Horizontal wire along y=29 from x=38 to x=82
        for wx in range(x_start, x_end + 1):
            actions.append((Tool.WIRE, wx, 29))

        # For each road row, build road and connect wire vertically
        prev_wire_y = 29
        for road_y in road_rows:
            wire_y = road_y - 1

            # Vertical wire connecting from prev wire row to this wire row at x=45
            if wire_y != 29:
                for wy in range(prev_wire_y + 1, wire_y + 1):
                    actions.append((Tool.WIRE, 45, wy))

            # Horizontal wire at wire_y
            if wire_y != 29:
                for wx in range(x_start, x_end + 1):
                    actions.append((Tool.WIRE, wx, wire_y))

            # Horizontal road at road_y
            for rx in range(x_start, x_end + 1):
                actions.append((Tool.ROAD, rx, road_y))

            prev_wire_y = wire_y

        # Place zones above and below each road row
        # Zones are 3x3, placed by center
        # Zone centers above road: road_y - 3 (center), road_y - 2 (connects to road)
        # Zone centers below road: road_y + 3 (center), road_y + 2 (connects to road)

        zone_x_positions = list(range(x_start + 1, x_end, 6))  # every 6 cols

        for road_y in road_rows:
            for zx in zone_x_positions:
                if zx < 3 or zx > WORLD_W - 3:
                    continue
                # Zone above road (center at road_y - 3)
                zy_above = road_y - 3
                if zy_above >= 3:
                    actions.append(('zone_above', zx, zy_above))

                # Zone below road (center at road_y + 3)
                zy_below = road_y + 3
                if zy_below <= WORLD_H - 3:
                    actions.append(('zone_below', zx, zy_below))

        state['raw_actions'] = actions

    # Execute plan using tile_map awareness
    if 'raw_actions' not in state:
        return None

    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    res_count = int(np.sum(res_m))
    com_count = int(np.sum(com_m))
    ind_count = int(np.sum(ind_m))
    total_zones = res_count + com_count + ind_count

    def pick_zone():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        r = res_count / max(total_zones, 1)
        c = com_count / max(total_zones, 1)
        i = ind_count / max(total_zones, 1)
        # Target 40% res, 35% com, 25% ind
        if i < 0.25:
            return Tool.INDUSTRIAL
        elif c < 0.35:
            return Tool.COMMERCIAL
        else:
            return Tool.RESIDENTIAL

    def zone_area_free(cx, cy):
        for dy in [-1, 0, 1]:
            for dx in [-1, 0, 1]:
                ny, nx = cy + dy, cx + dx
                if ny < 0 or ny >= WORLD_H or nx < 0 or nx >= WORLD_W:
                    return False
                if not em[ny, nx]:
                    return False
        return True

    # Process actions in order
    idx = state.get('plan_idx', 0)
    raw = state['raw_actions']

    while idx < len(raw):
        action = raw[idx]

        if action[0] in ('zone_above', 'zone_below'):
            _, zx, zy = action
            if 2 <= zx <= WORLD_W - 3 and 2 <= zy <= WORLD_H - 3:
                # Check if already placed
                if not (res_m[zy, zx] or com_m[zy, zx] or ind_m[zy, zx]):
                    if zone_area_free(zx, zy):
                        zt = pick_zone()
                        state['plan_idx'] = idx + 1
                        return (zt, zx, zy)
                    else:
                        # Skip if can't place
                        idx += 1
                        state['plan_idx'] = idx
                        continue
                else:
                    idx += 1
                    state['plan_idx'] = idx
                    continue
            else:
                idx += 1
                state['plan_idx'] = idx
                continue
        else:
            tool, tx, ty = action

            if tool == Tool.COALPOWER:
                # Check if plant already exists nearby
                already = any(abs(r - ty) <= 3 and abs(c - tx) <= 3 
                             for (r, c) in zip(*np.where(pm))) if np.any(pm) else False
                if not already:
                    state['plan_idx'] = idx + 1
                    return (tool, tx, ty)
                else:
                    idx += 1
                    state['plan_idx'] = idx
                    continue
            elif tool == Tool.WIRE:
                if not wm[ty, tx] and not pm[ty, tx]:
                    state['plan_idx'] = idx + 1
                    return (tool, tx, ty)
                else:
                    idx += 1
                    state['plan_idx'] = idx
                    continue
            elif tool == Tool.ROAD:
                if not rm[ty, tx] and not pm[ty, tx]:
                    state['plan_idx'] = idx + 1
                    return (tool, tx, ty)
                else:
                    idx += 1
                    state['plan_idx'] = idx
                    continue
            else:
                state['plan_idx'] = idx + 1
                return (tool, tx, ty)

    # After main plan, add second power plant if needed
    if obs.city_pop > 50 and np.any(pm):
        plant_positions = list(zip(*np.where(pm)))
        if len(plant_positions) < 2:
            # Add second plant
            return (Tool.COALPOWER, 75, 20)

    # Connect second plant with wire
    if np.any(pm):
        plant_positions = list(zip(*np.where(pm)))
        if len(plant_positions) >= 2:
            # Wire from second plant down to wire network
            second_plant = plant_positions[1]
            py, px = second_plant
            for wy in range(py + 2, 30):
                if not wm[wy, px]:
                    return (Tool.WIRE, px, wy)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy v2:
    - Reads current map state each step to decide next action
    - Places coal plant -> wires -> roads -> zones in reactive fashion
    - Expands based on current city population
    - Uses wider zone placement with better road/wire coverage
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Fixed anchor - place plant slightly left of center-left area
    CX, CY = 25, 50

    # --- Phase 1: Place first coal power plant ---
    if not np.any(pm):
        return (Tool.COALPOWER, CX, CY)

    plant_ys, plant_xs = np.where(pm)
    # Use centroid of all plants
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Determine expansion radius based on population
    if obs.city_pop < 150:
        expand = 30
    elif obs.city_pop < 400:
        expand = 55
    elif obs.city_pop < 800:
        expand = 80
    else:
        expand = 95

    wire_start_x = px + 3
    target_wire_end = min(px + expand, WORLD_W - 4)
    spine_y = py

    # --- Phase 2: Grow horizontal wire spine ---
    spine_wire_cols = [c for c in range(WORLD_W) if wm[spine_y, c]]

    if not spine_wire_cols:
        wx = wire_start_x
        if in_bounds(wx, spine_y) and em[spine_y, wx]:
            return (Tool.WIRE, wx, spine_y)
        # Try row above/below
        for dy in [-1, 1]:
            wy = spine_y + dy
            if in_bounds(wx, wy) and em[wy, wx]:
                return (Tool.WIRE, wx, wy)
    else:
        max_wire_x = max(spine_wire_cols)
        if max_wire_x < target_wire_end:
            nx = max_wire_x + 1
            # Skip if it would overwrite a plant
            if in_bounds(nx, spine_y) and em[spine_y, nx] and not pm[spine_y, nx]:
                return (Tool.WIRE, nx, spine_y)

    # --- Phase 3: Vertical wire branches every 5 cols ---
    branch_cols = list(range(wire_start_x + 2, target_wire_end + 1, 5))
    for bx in branch_cols:
        if not in_bounds(bx, spine_y):
            continue
        if not (bool(wm[spine_y, bx]) or bool(pm[spine_y, bx])):
            continue
        # Branch up and down 4 tiles
        for sign in [-1, 1]:
            for dy in range(1, 5):
                wy = spine_y + sign * dy
                if not in_bounds(bx, wy):
                    break
                if bool(wm[wy, bx]) or bool(pm[wy, bx]):
                    continue
                if bool(em[wy, bx]):
                    return (Tool.WIRE, bx, wy)
                break

    # --- Phase 4: Build two road rows parallel to wire spine ---
    # Use rows 3 above and 3 below spine (to leave room for zones between)
    road_offsets = [-3, 3]
    road_start = wire_start_x
    road_end = target_wire_end

    for r_off in road_offsets:
        r_row = spine_y + r_off
        if not (0 <= r_row < WORLD_H):
            continue
        road_cols_here = [c for c in range(WORLD_W) if rm[r_row, c]]
        if not road_cols_here:
            rx = road_start
            if in_bounds(rx, r_row) and em[r_row, rx] and not wm[r_row, rx] and not pm[r_row, rx]:
                return (Tool.ROAD, rx, r_row)
        else:
            max_r = max(road_cols_here)
            if max_r < road_end:
                nx = max_r + 1
                if in_bounds(nx, r_row) and em[r_row, nx] and not wm[r_row, nx] and not pm[r_row, nx]:
                    return (Tool.ROAD, nx, r_row)

    # Also build a middle road row at spine_y offset +/- 6 for more coverage
    for r_off2 in [-6, 6]:
        r_row2 = spine_y + r_off2
        if not (0 <= r_row2 < WORLD_H):
            continue
        # Only add if we have decent expansion
        if target_wire_end < px + 20:
            continue
        road_cols2 = [c for c in range(WORLD_W) if rm[r_row2, c]]
        if not road_cols2:
            rx2 = road_start
            if in_bounds(rx2, r_row2) and em[r_row2, rx2] and not wm[r_row2, rx2] and not pm[r_row2, rx2]:
                return (Tool.ROAD, rx2, r_row2)
        else:
            max_r2 = max(road_cols2)
            if max_r2 < road_end:
                nx2 = max_r2 + 1
                if in_bounds(nx2, r_row2) and em[r_row2, nx2] and not wm[r_row2, nx2] and not pm[r_row2, nx2]:
                    return (Tool.ROAD, nx2, r_row2)

    # --- Phase 5: Vertical connector roads every 5 cols between road rows ---
    all_road_rows = [spine_y + r_off for r_off in road_offsets if 0 <= spine_y + r_off < WORLD_H]
    if all_road_rows:
        row_min = min(all_road_rows)
        row_max = max(all_road_rows)
        for vc in range(road_start, road_end + 1, 5):
            for vr in range(row_min, row_max + 1):
                if not in_bounds(vc, vr):
                    continue
                if bool(rm[vr, vc]) or bool(pm[vr, vc]) or bool(wm[vr, vc]):
                    continue
                if not bool(em[vr, vc]):
                    continue
                # Check if connected to existing road
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr2, nc2 = vr + dr, vc + dc
                    if in_bounds(nc2, nr2) and bool(rm[nr2, nc2]):
                        return (Tool.ROAD, vc, vr)
                        break

    # --- Phase 6: Second coal plant when zones grow ---
    if total_zones > 8 or obs.city_pop > 150:
        # Find a good location for second plant along the wire spine
        # Place it about halfway along the wire
        spine_wire_cols2 = [c for c in range(WORLD_W) if wm[spine_y, c]]
        if spine_wire_cols2:
            mid_x = int(np.median(spine_wire_cols2))
            p2x = min(mid_x + 25, WORLD_W - 5)
            p2y = py
            # Check no nearby plant
            nearby_plant = False
            for dy in range(-5, 6):
                for dx in range(-5, 6):
                    ny2, nx2 = p2y + dy, p2x + dx
                    if in_bounds(nx2, ny2) and bool(pm[ny2, nx2]):
                        nearby_plant = True
                        break
                if nearby_plant:
                    break
            if not nearby_plant and in_bounds(p2x, p2y) and bool(em[p2y, p2x]):
                return (Tool.COALPOWER, p2x, p2y)

    # --- Phase 7: Place zones reactively ---
    # Build neighbor masks for road proximity (within 2) and wire/plant (within 3)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Track zone centers for clearance check
    zone_set = set()
    for arr in [resm, comm, indm]:
        ys2, xs2 = np.where(arr)
        for y2, x2 in zip(ys2.tolist(), xs2.tolist()):
            zone_set.add((int(y2), int(x2)))

    def zone_clear(zx, zy):
        # All 9 tiles of 3x3 zone must be empty or existing zone center
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    cand_mask = em & nbr_road & nbr_wire
    # Keep away from edges
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Hash based on step and pop for variety
        step_hash = int(obs.step * 13 + int(obs.city_pop * 7)) % max(len(cxs_arr), 1)
        for offset in range(min(len(cxs_arr), 100)):
            k = (step_hash + offset * 7) % len(cxs_arr)
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # --- Phase 8: Services ---
    if obs.city_pop > 300:
        fx, fy = px + 5, py - 9
        if in_bounds(fx, fy) and bool(em[fy, fx]):
            return (Tool.FIRESTATION, fx, fy)
        fx2, fy2 = px + 5, py + 9
        if in_bounds(fx2, fy2) and bool(em[fy2, fx2]):
            return (Tool.POLICESTATION, fx2, fy2)

    # --- Phase 9: Extend wire from frontier if nothing else to do ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        candidates = sorted(zip(wire_xs_arr.tolist(), wire_ys_arr.tolist()), key=lambda t: -t[0])
        for wx_s, wy_s in candidates[:15]:
            for dx2, dy2 in [(1, 0), (0, 1), (0, -1), (-1, 0)]:
                nx2, ny2 = wx_s + dx2, wy_s + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # --- Phase 10: Extend roads from frontier ---
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        candidates_r = sorted(zip(road_xs_arr.tolist(), road_ys_arr.tolist()), key=lambda t: -t[0])
        for rx_s, ry_s in candidates_r[:15]:
            for dx2, dy2 in [(1, 0), (0, 1), (0, -1), (-1, 0)]:
                nx2, ny2 = rx_s + dx2, ry_s + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and not bool(wm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Each step scans the actual tile_map to find where power/roads reach
    - Extends infrastructure from what currently exists
    - Places zones adjacent to existing road+power coverage
    - No fixed plan; adapts to whatever is on the map
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- Step 1: Ensure power plant exists ----
    if not np.any(pm):
        # Place coal plant slightly left of center
        return (Tool.COALPOWER, cx - 8, cy)

    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # ---- Determine spine column (wire) just right of plant ----
    wire_col = plant_cx + 4
    wire_col = max(3, min(WORLD_W - 4, wire_col))

    # Road columns flanking the wire spine
    road_col_r = wire_col + 2
    road_col_l = wire_col - 2
    road_col_r = max(2, min(WORLD_W - 3, road_col_r))
    road_col_l = max(2, min(WORLD_W - 3, road_col_l))

    # Zone columns outside roads
    zone_col_r = road_col_r + 3
    zone_col_l = road_col_l - 3
    zone_col_r = max(2, min(WORLD_W - 4, zone_col_r))
    zone_col_l = max(3, min(WORLD_W - 3, zone_col_l))

    # ---- Step 2: Scan current wire extent on wire_col ----
    wire_present = [r for r in range(WORLD_H) if wm[r, wire_col]]
    road_r_present = set(r for r in range(WORLD_H) if rm[r, road_col_r])
    road_l_present = set(r for r in range(WORLD_H) if rm[r, road_col_l])

    # Spine extent scales with population
    pop = obs.city_pop
    if pop < 50:
        half_ext = 6
    elif pop < 200:
        half_ext = 12
    elif pop < 500:
        half_ext = 20
    elif pop < 1000:
        half_ext = 30
    else:
        half_ext = 40

    spine_top = max(2, cy - half_ext)
    spine_bot = min(WORLD_H - 3, cy + half_ext)

    # ---- Step 3: Bootstrap wire if none exists ----
    if not wire_present:
        # Find closest empty cell to plant on wire_col
        for dy in range(0, 8):
            for nr in [plant_cy + dy, plant_cy - dy]:
                if 0 <= nr < WORLD_H:
                    if em[nr, wire_col]:
                        return (Tool.WIRE, wire_col, nr)
        return None

    min_wr = min(wire_present)
    max_wr = max(wire_present)

    # ---- Step 4: Connect plant to wire spine if not adjacent ----
    # Check if wire is adjacent (within 1 cell) to plant
    plant_connected = False
    for pr, pc in zip(plant_rows, plant_cols):
        if abs(pc - wire_col) <= 2 and abs(pr - plant_cy) <= 4:
            plant_connected = True
            break

    if not plant_connected:
        # Lay wire horizontally from plant to wire_col at plant_cy row
        for wc in range(min(plant_cx + 2, wire_col), wire_col + 1):
            if 0 <= wc < WORLD_W and wc != wire_col:
                if em[plant_cy, wc]:
                    return (Tool.WIRE, wc, plant_cy)
        # Also try to lay wire vertically to connect
        if em[plant_cy, wire_col]:
            return (Tool.WIRE, wire_col, plant_cy)

    # ---- Step 5: Reactively extend wire spine toward targets ----
    # Extend downward if needed
    if max_wr < spine_bot:
        nr = max_wr + 1
        if 0 < nr < WORLD_H and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Extend upward if needed
    if min_wr > spine_top:
        nr = min_wr - 1
        if 0 <= nr < WORLD_H and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # ---- Step 6: Build roads flanking the wire spine ----
    for wr in wire_present:
        if wr < spine_top or wr > spine_bot:
            continue
        # Right road
        if wr not in road_r_present:
            if 0 <= road_col_r < WORLD_W and em[wr, road_col_r]:
                return (Tool.ROAD, road_col_r, wr)
        # Left road
        if wr not in road_l_present:
            if 0 <= road_col_l < WORLD_W and em[wr, road_col_l]:
                return (Tool.ROAD, road_col_l, wr)

    # ---- Zone placement helpers ----
    all_zone_mask = resm | comm | indm

    def zone_area_clear(zr, zc):
        """Check 3x3 area is all empty or already zone tiles."""
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not (em[rr, rc] or all_zone_mask[rr, rc]):
                    return False
        return True

    def zone_overlap(zr, zc):
        """Check if any zone tile is already in 3x3 area."""
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # ---- Step 7: Place zones next to existing roads ----
    # For each road tile that exists, try to place a zone in zone columns
    for wr in sorted(wire_present):
        if wr < spine_top or wr > spine_bot:
            continue

        # Zones to the right (centered on every 3rd row relative to center)
        if wr in road_r_present:
            zr = wr
            zc = zone_col_r
            if not zone_overlap(zr, zc) and zone_area_clear(zr, zc):
                return (pick_tool(), zc, zr)

        # Zones to the left
        if wr in road_l_present:
            zr = wr
            zc = zone_col_l
            if not zone_overlap(zr, zc) and zone_area_clear(zr, zc):
                return (pick_tool(), zc, zr)

    # ---- Step 8: Lateral roads to zone columns ----
    # Extend roads from road columns outward to reach zone columns
    for wr in wire_present:
        if wr < spine_top or wr > spine_bot:
            continue

        if wr in road_r_present:
            # Extend rightward from road_col_r to zone_col_r
            for rc in range(road_col_r + 1, zone_col_r + 2):
                if 0 <= rc < WORLD_W:
                    if rm[wr, rc]:
                        break
                    if em[wr, rc] and not pm[wr, rc] and not wm[wr, rc]:
                        return (Tool.ROAD, rc, wr)
                    elif not em[wr, rc]:
                        break

        if wr in road_l_present:
            # Extend leftward from road_col_l to zone_col_l
            for rc in range(road_col_l - 1, zone_col_l - 2, -1):
                if 0 <= rc < WORLD_W:
                    if rm[wr, rc]:
                        break
                    if em[wr, rc] and not pm[wr, rc] and not wm[wr, rc]:
                        return (Tool.ROAD, rc, wr)
                    elif not em[wr, rc]:
                        break

    # ---- Step 9: Second power plant when city grows ----
    if pop > 300 and int(np.sum(pm)) < 9:
        # Place second plant to the right
        px2 = plant_cx + 18
        py2 = plant_cy
        px2 = max(2, min(WORLD_W - 4, px2))
        py2 = max(2, min(WORLD_H - 4, py2))
        area_ok = True
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = py2 + dr, px2 + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if not em[rr, rc]:
                        area_ok = False
        if area_ok:
            return (Tool.COALPOWER, px2, py2)

    # ---- Step 10: Wire from plant to second spine or extend coverage ----
    if pop > 200:
        # Try to extend a second wire spine further right
        wire_col2 = zone_col_r + 6
        wire_col2 = max(3, min(WORLD_W - 4, wire_col2))
        wire_rows2 = [r for r in range(WORLD_H) if wm[r, wire_col2]]

        if not wire_rows2:
            # Lay horizontal wire bridge at cy from main spine to wire_col2
            for wc in range(wire_col + 1, wire_col2 + 1):
                if 0 <= wc < WORLD_W:
                    if wm[cy, wc]:
                        break
                    if em[cy, wc] and not rm[cy, wc]:
                        return (Tool.WIRE, wc, cy)
        else:
            min_wr2 = min(wire_rows2)
            max_wr2 = max(wire_rows2)
            road_col2r = wire_col2 + 2
            zone_col2r = road_col2r + 3
            road_col2r = max(2, min(WORLD_W - 3, road_col2r))
            zone_col2r = max(2, min(WORLD_W - 4, zone_col2r))
            road_rows2 = set(r for r in range(WORLD_H) if rm[r, road_col2r])

            if max_wr2 < spine_bot:
                nr = max_wr2 + 1
                if 0 < nr < WORLD_H and (em[nr, wire_col2] or wm[nr, wire_col2]):
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > spine_top:
                nr = min_wr2 - 1
                if 0 <= nr < WORLD_H and (em[nr, wire_col2] or wm[nr, wire_col2]):
                    return (Tool.WIRE, wire_col2, nr)

            for wr in wire_rows2:
                if wr not in road_rows2 and 0 <= road_col2r < WORLD_W:
                    if em[wr, road_col2r]:
                        return (Tool.ROAD, road_col2r, wr)

            for wr in wire_rows2:
                if wr in road_rows2:
                    zr = wr
                    zc = zone_col2r
                    if not zone_overlap(zr, zc) and zone_area_clear(zr, zc):
                        return (pick_tool(), zc, zr)

    # ---- Step 11: Reactive gap filling - add roads/wires where missing ----
    for wr in wire_present:
        if wr not in road_r_present and 0 <= road_col_r < WORLD_W:
            if em[wr, road_col_r]:
                return (Tool.ROAD, road_col_r, wr)
        if wr not in road_l_present and 0 <= road_col_l < WORLD_W:
            if em[wr, road_col_l]:
                return (Tool.ROAD, road_col_l, wr)

    # ---- Step 12: Densify zones - try more zone rows ----
    for offset in range(-half_ext, half_ext + 1, 2):
        zr = cy + offset
        if zr < 2 or zr > WORLD_H - 3:
            continue
        for zc in [zone_col_r, zone_col_l]:
            if not zone_overlap(zr, zc) and zone_area_clear(zr, zc):
                # Check road is nearby
                road_near = (
                    (0 <= road_col_r < WORLD_W and any(rm[zr + dr, road_col_r] for dr in [-1, 0, 1] if 0 <= zr + dr < WORLD_H)) or
                    (0 <= road_col_l < WORLD_W and any(rm[zr + dr, road_col_l] for dr in [-1, 0, 1] if 0 <= zr + dr < WORLD_H))
                )
                if road_near:
                    return (pick_tool(), zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy combining best ideas from both parents.
    Reads tile_map every step, adapts to what's actually built.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Phase 1: Place first coal plant ---
    if not np.any(pm):
        return (Tool.COALPOWER, 55, 50)

    # Find plant center
    plant_ys, plant_xs = np.where(pm)
    px = int(np.median(plant_xs))
    py = int(np.median(plant_ys))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Wire spine: grow vertically from plant ---
    wire_col = px + 2
    pop_factor = min(40, obs.city_pop // 12)
    tmin = max(2, py - 16 - pop_factor)
    tmax = min(WORLD_H - 3, py + 16 + pop_factor)

    wire_in_col = [r for r in range(WORLD_H) if 0 <= wire_col < WORLD_W and wm[r, wire_col]]

    if not wire_in_col:
        # Seed wire adjacent to plant
        for dy in range(-2, 3):
            ny = py + dy
            if in_bounds(wire_col, ny) and (em[ny, wire_col] or wm[ny, wire_col]) and not pm[ny, wire_col]:
                return (Tool.WIRE, wire_col, ny)
    else:
        min_wr = min(wire_in_col)
        max_wr = max(wire_in_col)
        if max_wr < tmax:
            nr = max_wr + 1
            if in_bounds(wire_col, nr) and (em[nr, wire_col] or wm[nr, wire_col]) and not pm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)
        if min_wr > tmin:
            nr = min_wr - 1
            if in_bounds(wire_col, nr) and (em[nr, wire_col] or wm[nr, wire_col]) and not pm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # --- Road columns flanking wire spine ---
    road_col_r = wire_col + 1
    road_col_l = wire_col - 1

    for wr in wire_in_col:
        if in_bounds(road_col_r, wr) and em[wr, road_col_r]:
            return (Tool.ROAD, road_col_r, wr)
        if in_bounds(road_col_l, wr) and em[wr, road_col_l]:
            return (Tool.ROAD, road_col_l, wr)

    # --- Build proximity masks for zone placement ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and not zone_tiles[nr, nc]:
                    return False
        return True

    # Candidate zone centers: empty, near road, near wire/plant
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        dists = np.abs(cxs - wire_col)
        order = np.argsort(dists)
        step_off = int(obs.step * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 80:
