def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map each step to adapt placements
    - Layout: coal plant at center-left, wire spine runs right, roads above/below spine
    - Zones placed adjacent to roads, powered via wire
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # --- Phase 1: Place coal plant if missing ---
    if not np.any(pm):
        # Place plant at a fixed anchor point
        return (Tool.COALPOWER, 30, 50)

    # Find plant center from tile_map
    plant_rows, plant_cols = np.where(pm)
    pcx = int(np.median(plant_cols))
    pcy = int(np.median(plant_rows))

    # Wire spine runs horizontally from plant rightward at row pcy
    # Roads run parallel: one row above (pcy-2) and one row below (pcy+2)
    # Zones at pcy-5 and pcy+5 centered
    wire_row = pcy
    road_top = pcy - 2
    road_bot = pcy + 2
    zone_top = pcy - 5
    zone_bot = pcy + 5

    # Horizontal span: start just right of plant, extend rightward
    x_start = pcx + 2  # just past plant right edge
    # Dynamic span: grow with population
    span = min(50, 10 + obs.city_pop // 10)
    x_end = min(WORLD_W - 4, x_start + span)

    # Clamp rows
    road_top = max(2, road_top)
    road_bot = min(WORLD_H - 3, road_bot)
    zone_top = max(2, zone_top)
    zone_bot = min(WORLD_H - 3, zone_bot)

    # --- Phase 2: Extend wire spine rightward from plant ---
    # Find rightmost wire on wire_row
    wire_cols = [c for c in range(WORLD_W) if wm[wire_row, c]]

    if not wire_cols:
        # First wire: place adjacent to plant
        wx = pcx + 2
        wx = max(0, min(WORLD_W - 1, wx))
        return (Tool.WIRE, wx, wire_row)

    wire_right = max(wire_cols)
    wire_left = min(wire_cols)

    # Extend rightward if not at target
    if wire_right < x_end:
        nx = wire_right + 1
        if 0 <= nx < WORLD_W and (em[wire_row, nx] or wm[wire_row, nx]):
            return (Tool.WIRE, nx, wire_row)

    # --- Phase 3: Build top road parallel to wire ---
    # Road at road_top row, from x_start to wire_right
    road_cols_top = set(c for c in range(WORLD_W) if rm[road_top, c])
    if road_top >= 0:
        for cx in range(x_start, min(wire_right + 1, WORLD_W)):
            if cx not in road_cols_top and em[road_top, cx]:
                return (Tool.ROAD, cx, road_top)

    # --- Phase 4: Build bottom road parallel to wire ---
    road_cols_bot = set(c for c in range(WORLD_W) if rm[road_bot, c])
    if road_bot < WORLD_H:
        for cx in range(x_start, min(wire_right + 1, WORLD_W)):
            if cx not in road_cols_bot and em[road_bot, cx]:
                return (Tool.ROAD, cx, road_bot)

    # --- Phase 5: Place vertical wire connectors to power zone rows ---
    # Connect wire spine to zone rows via vertical wires
    # At certain x positions, drop wire from wire_row to zone_top and zone_bot
    # Do this every 6 columns for power distribution
    for cx in range(x_start, min(wire_right + 1, WORLD_W), 6):
        # Upward connector
        for wy in range(wire_row - 1, zone_top - 1, -1):
            if wy < 0:
                break
            if wm[wy, cx]:
                break
            if em[wy, cx]:
                return (Tool.WIRE, cx, wy)
        # Downward connector
        for wy in range(wire_row + 1, zone_bot + 2):
            if wy >= WORLD_H:
                break
            if wm[wy, cx]:
                break
            if em[wy, cx]:
                return (Tool.WIRE, cx, wy)

    # --- Phase 6: Place zones adjacent to roads ---
    all_zone_m = res_m | com_m | ind_m
    res_count = max(1, int(np.sum(res_m)) // 9)
    com_count = max(1, int(np.sum(com_m)) // 9)
    ind_count = max(1, int(np.sum(ind_m)) // 9)

    def pick_zone():
        total = res_count + com_count + ind_count
        # Target 60% res, 20% com, 20% ind
        if ind_count * 5 < total:
            return Tool.INDUSTRIAL
        if com_count * 5 < total:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zrow, zcol):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                r2, c2 = zrow + dr, zcol + dc
                if r2 < 0 or r2 >= WORLD_H or c2 < 0 or c2 >= WORLD_W:
                    return False
                if not em[r2, c2]:
                    return False
        return True

    def zone_nearby(zrow, zcol):
        r0, r1 = max(0, zrow - 2), min(WORLD_H, zrow + 3)
        c0, c1 = max(0, zcol - 2), min(WORLD_W, zcol + 3)
        return np.any(all_zone_m[r0:r1, c0:c1])

    # Place zones above top road (at zone_top row) and below bottom road (at zone_bot)
    # Zone center at zone_top = road_top - 3, zone_bot = road_bot + 3
    road_cols_top_list = sorted(road_cols_top, key=lambda c: abs(c - (x_start + wire_right) // 2))
    road_cols_bot_list = sorted(road_cols_bot, key=lambda c: abs(c - (x_start + wire_right) // 2))

    # Top zones: center row = road_top - 3
    zt_row = road_top - 3
    zt_row = max(2, min(WORLD_H - 3, zt_row))
    for cx in road_cols_top_list:
        if 2 <= cx <= WORLD_W - 3:
            if not zone_nearby(zt_row, cx) and zone_clear(zt_row, cx):
                return (pick_zone(), cx, zt_row)

    # Bottom zones: center row = road_bot + 3
    zb_row = road_bot + 3
    zb_row = max(2, min(WORLD_H - 3, zb_row))
    for cx in road_cols_bot_list:
        if 2 <= cx <= WORLD_W - 3:
            if not zone_nearby(zb_row, cx) and zone_clear(zb_row, cx):
                return (pick_zone(), cx, zb_row)

    # Also zones between roads (at wire_row +/-0, but offset so they don't block wire)
    # Zones at wire_row, placed every 6 cols offset by 3 from connectors
    for cx in range(x_start + 3, min(wire_right + 1, WORLD_W), 6):
        if 2 <= cx <= WORLD_W - 3:
            # Only if adjacent to a road
            near_top = rm[road_top, cx] if 0 <= road_top < WORLD_H else False
            near_bot = rm[road_bot, cx] if 0 <= road_bot < WORLD_H else False
            if near_top or near_bot:
                if not zone_nearby(wire_row, cx) and zone_clear(wire_row, cx):
                    return (pick_zone(), cx, wire_row)

    # --- Phase 7: Vertical roads to connect zone rows to each other ---
    # Add short vertical roads at endpoints
    if wire_right > x_start + 2:
        rx = wire_right
        for ry in range(road_top, road_bot + 1):
            if 0 <= ry < WORLD_H and not rm[ry, rx] and em[ry, rx] and not wm[ry, rx]:
                return (Tool.ROAD, rx, ry)

    # --- Phase 8: Second coal plant when city needs more power ---
    if obs.city_pop > 300 and not state.get("plant2_done", False):
        # Place second plant far right
        px2 = min(WORLD_W - 3, x_end + 5)
        py2 = pcy
        # Bridge wire to it
        for wx in range(wire_right + 1, px2 + 1):
            wy = wire_row
            if 0 <= wx < WORLD_W and 0 <= wy < WORLD_H:
                if em[wy, wx] or wm[wy, wx]:
                    return (Tool.WIRE, wx, wy)
        # Plant placement
        clear2 = all(
            0 <= py2 + dr < WORLD_H and 0 <= px2 + dc < WORLD_W and em[py2 + dr, px2 + dc]
            for dr in [-1, 0, 1] for dc in [-1, 0, 1]
        )
        if clear2:
            state["plant2_done"] = True
            return (Tool.COALPOWER, px2, py2)

    # --- Phase 9: Extend span further if city is growing ---
    if obs.city_pop > 50 and wire_right < WORLD_W - 4:
        nx = wire_right + 1
        if em[wire_row, nx] or wm[wire_row, nx]:
            return (Tool.WIRE, nx, wire_row)

    return None

def act(obs, state):
    """
    Closed-loop policy: scan the map each step and place the next useful tile
    based on what's actually there. Uses a phase system but decisions within
    each phase are reactive to the current map state.
    """

    # Helper: check bounds
    def inbounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Helper: find empty cells adjacent to existing infrastructure
    def find_adjacent_empty(mask, empty):
        """Find empty cells adjacent to cells where mask is True."""
        candidates = []
        ys, xs = np.where(mask)
        for y, x in zip(ys, xs):
            for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
                nx, ny = x+dx, y+dy
                if inbounds(nx, ny) and empty[ny, nx]:
                    candidates.append((nx, ny))
        return candidates

    tile = obs.tile_map
    empty = empty_mask(tile)
    roads = road_mask(tile)
    wires = wire_mask(tile)
    plants = plant_mask(tile)
    res = res_mask(tile)
    com = com_mask(tile)
    ind = ind_mask(tile)

    step = obs.step
    n = obs.n_steps

    # Phase boundaries based on step fraction
    frac = step / max(n, 1)

    # --- PHASE 0: Place coal power plant (step 0) ---
    if step == 0:
        # Place power plant at a fixed good location
        state['plant_x'] = 20
        state['plant_y'] = 50
        state['road_col'] = 30  # main vertical road column
        state['wire_col'] = 29  # wire column next to road
        state['zone_y_min'] = 35
        state['zone_y_max'] = 65
        state['phase'] = 0
        return (Tool.COALPOWER, 20, 50)

    # --- Always ensure we have power plant ---
    n_plants = np.sum(plants)

    # Check if power plant exists
    if n_plants == 0 and step < 5:
        return (Tool.COALPOWER, 20, 50)

    # Determine current phase from state
    phase = state.get('phase', 0)

    px = state.get('plant_x', 20)
    py = state.get('plant_y', 50)
    road_col = state.get('road_col', 30)
    wire_col = state.get('wire_col', 29)
    zy_min = state.get('zone_y_min', 35)
    zy_max = state.get('zone_y_max', 65)

    # --- PHASE 1: Extend wire from plant to road column ---
    # Wire from plant (px+2) to wire_col at py
    if phase <= 1:
        state['phase'] = 1
        # Lay wire from plant rightward
        for wx in range(px + 2, wire_col + 1):
            if inbounds(wx, py) and not wires[py, wx] and not plants[py, wx]:
                return (Tool.WIRE, wx, py)
        # Wire is done, go to phase 2
        state['phase'] = 2

    # --- PHASE 2: Lay vertical road and wire along road column ---
    if phase <= 2:
        state['phase'] = 2
        # Lay vertical road at road_col from zy_min-1 to zy_max+1
        for wy in range(zy_min - 1, zy_max + 2):
            if inbounds(road_col, wy) and not roads[wy, road_col]:
                return (Tool.ROAD, road_col, wy)
        # Lay vertical wire at wire_col from zy_min-1 to zy_max+1
        for wy in range(zy_min - 1, zy_max + 2):
            if inbounds(wire_col, wy) and not wires[wy, wire_col] and not plants[wy, wire_col]:
                return (Tool.WIRE, wire_col, wy)
        state['phase'] = 3

    # --- PHASE 3: Place zones adjacent to road column ---
    # Residential left of wire, commercial right of road
    if phase <= 3:
        state['phase'] = 3
        # Place residential zones at wire_col-2 (center), spaced 3 apart vertically
        for zy in range(zy_min, zy_max, 3):
            cx, cy = wire_col - 2, zy
            if inbounds(cx, cy):
                # Check if zone center area is not already zoned
                if not res[cy, cx] and not com[cy, cx] and not ind[cy, cx]:
                    return (Tool.RESIDENTIAL, cx, cy)
        # Place commercial zones at road_col+2
        for zy in range(zy_min, zy_max, 3):
            cx, cy = road_col + 2, zy
            if inbounds(cx, cy):
                if not res[cy, cx] and not com[cy, cx] and not ind[cy, cx]:
                    return (Tool.COMMERCIAL, cx, cy)
        state['phase'] = 4

    # --- PHASE 4: Expand - second road + wire column to the right ---
    if phase <= 4:
        state['phase'] = 4
        road2_col = road_col + 8
        wire2_col = road2_col + 1
        # Wire from road_col to road2_col at py
        for wx in range(road_col, road2_col + 1):
            if inbounds(wx, py) and not wires[py, wx] and not plants[py, wx] and not roads[py, wx]:
                return (Tool.WIRE, wx, py)
        # Vertical road at road2_col
        for wy in range(zy_min - 1, zy_max + 2):
            if inbounds(road2_col, wy) and not roads[wy, road2_col]:
                return (Tool.ROAD, road2_col, wy)
        # Vertical wire at wire2_col
        for wy in range(zy_min - 1, zy_max + 2):
            if inbounds(wire2_col, wy) and not wires[wy, wire2_col] and not plants[wy, wire2_col]:
                return (Tool.WIRE, wire2_col, wy)
        # Industrial zones at road2_col + 2
        for zy in range(zy_min, zy_max, 3):
            cx, cy = road2_col + 2, zy
            if inbounds(cx, cy):
                if not res[cy, cx] and not com[cy, cx] and not ind[cy, cx]:
                    return (Tool.INDUSTRIAL, cx, cy)
        # More residential at wire2_col - 2 (between the two road systems)
        for zy in range(zy_min, zy_max, 3):
            cx, cy = wire2_col - 2, zy
            if inbounds(cx, cy):
                if not res[cy, cx] and not com[cy, cx] and not ind[cy, cx]:
                    return (Tool.RESIDENTIAL, cx, cy)
        state['phase'] = 5

    # --- PHASE 5: Second power plant on the right + connect ---
    if phase <= 5:
        state['phase'] = 5
        road2_col = road_col + 8
        plant2_x = road2_col + 12
        # Place second plant
        if n_plants < 2:
            if inbounds(plant2_x, py):
                return (Tool.COALPOWER, plant2_x, py)
        # Wire from road2_col+2 to plant2_x-2
        for wx in range(road2_col + 2, plant2_x):
            if inbounds(wx, py) and not wires[py, wx] and not plants[py, wx] and not roads[py, wx]:
                return (Tool.WIRE, wx, py)
        state['phase'] = 6

    # --- PHASE 6: Services (fire/police) and more zones ---
    if phase <= 6:
        state['phase'] = 6
        # Fire station
        if inbounds(road_col, zy_min - 4):
            fs_x, fs_y = road_col, zy_min - 4
            tm = tile[fs_y, fs_x]
            # Check if it's not already a service building (rough check)
            if empty[fs_y, fs_x]:
                return (Tool.FIRESTATION, fs_x, fs_y)
        # Police station
        ps_x, ps_y = road_col + 8, zy_max + 4
        if inbounds(ps_x, ps_y) and empty[ps_y, ps_x]:
            return (Tool.POLICESTATION, ps_x, ps_y)
        state['phase'] = 7

    # --- PHASE 7: Reactive expansion - find unpowered/unroaded zones and fix ---
    if phase >= 7:
        road2_col = road_col + 8
        wire2_col = road2_col + 1

        # Look for road tiles with no adjacent wire - extend wire there
        # Look for empty cells near existing roads and add more zones

        # Extend road coverage upward
        for wy in range(zy_min - 4, zy_min):
            if inbounds(road_col, wy) and not roads[wy, road_col]:
                return (Tool.ROAD, road_col, wy)
        for wy in range(zy_min - 4, zy_min):
            if inbounds(wire_col, wy) and not wires[wy, wire_col] and not plants[wy, wire_col]:
                return (Tool.WIRE, wire_col, wy)

        # Extend road coverage downward
        for wy in range(zy_max + 2, zy_max + 6):
            if inbounds(road_col, wy) and not roads[wy, road_col]:
                return (Tool.ROAD, road_col, wy)
        for wy in range(zy_max + 2, zy_max + 6):
            if inbounds(wire_col, wy) and not wires[wy, wire_col] and not plants[wy, wire_col]:
                return (Tool.WIRE, wire_col, wy)

        # Add more residential zones in extended area
        for zy in range(zy_min - 4, zy_min, 3):
            cx, cy = wire_col - 2, zy
            if inbounds(cx, cy) and not res[cy, cx] and not com[cy, cx] and not ind[cy, cx]:
                return (Tool.RESIDENTIAL, cx, cy)

        for zy in range(zy_max + 2, zy_max + 6, 3):
            cx, cy = wire_col - 2, zy
            if inbounds(cx, cy) and not res[cy, cx] and not com[cy, cx] and not ind[cy, cx]:
                return (Tool.RESIDENTIAL, cx, cy)

        # Add commercial on right side of road2_col
        for zy in range(zy_min, zy_max, 3):
            cx, cy = road2_col - 2, zy
            if inbounds(cx, cy) and not res[cy, cx] and not com[cy, cx] and not ind[cy, cx]:
                return (Tool.COMMERCIAL, cx, cy)

        # Horizontal roads to connect spines
        for hx in range(wire_col, road2_col + 1):
            for hy in [zy_min - 1, zy_max + 1]:
                if inbounds(hx, hy) and not roads[hy, hx] and not wires[hy, hx] and not plants[hy, hx]:
                    return (Tool.ROAD, hx, hy)

        # Additional zones between spines
        mid_x = (wire_col + road2_col) // 2
        for zy in range(zy_min, zy_max, 3):
            # Check if we have road access at mid_x
            has_road = False
            for dx in range(-2, 3):
                for dy_r in range(-2, 3):
                    nx, ny = mid_x + dx, zy + dy_r
                    if inbounds(nx, ny) and roads[ny, nx]:
                        has_road = True
            if has_road:
                if inbounds(mid_x, zy) and not res[zy, mid_x] and not com[zy, mid_x] and not ind[zy, mid_x]:
                    return (Tool.COMMERCIAL, mid_x, zy)

        # Reactive: if powered_zones is low, add more wire near existing roads
        if obs.powered_zones < 5:
            # Find road tiles without nearby wire
            road_ys, road_xs = np.where(roads)
            for ry_r, rx_r in zip(road_ys[:20], road_xs[:20]):
                # Check if there's wire nearby
                has_wire = False
                for dx in range(-2, 3):
                    for dy_w in range(-2, 3):
                        nx, ny = rx_r + dx, ry_r + dy_w
                        if inbounds(nx, ny) and (wires[ny, nx] or plants[ny, nx]):
                            has_wire = True
                if not has_wire:
                    # Add wire adjacent to this road
                    for dx, dy_w in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nx, ny = rx_r + dx, ry_r + dy_w
                        if inbounds(nx, ny) and empty[ny, nx]:
                            return (Tool.WIRE, nx, ny)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads current tile_map every step to decide next action
    - Builds a compact cluster: coal plant -> wire spine -> road grid -> zones
    - Adapts to what's already on the map
    """
    tm = obs.tile_map
    step = obs.step

    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # Cluster center
    cx, cy = 55, 50

    # Power plant target position (upper-left of cluster)
    plant_x, plant_y = cx - 20, cy

    # --- Phase 1: Ensure coal power plant exists ---
    if not np.any(pm):
        return (Tool.COALPOWER, plant_x, plant_y)

    # Find plant location (center tile of plant footprint)
    plant_rows, plant_cols = np.where(pm)
    # Use centroid of plant tiles
    pc_row = int(np.mean(plant_rows))
    pc_col = int(np.mean(plant_cols))

    # --- Phase 2: Build horizontal wire spine from plant to right ---
    # Spine at row cy, from plant rightward to cx+25
    spine_row = cy
    spine_col_start = pc_col + 2  # just right of plant
    spine_col_end = cx + 30

    # Find rightmost wire on spine row
    spine_wire_cols = [c for c in range(WORLD_W) if wm[spine_row, c]]
    if spine_wire_cols:
        max_wire_col = max(spine_wire_cols)
    else:
        max_wire_col = spine_col_start - 1

    if max_wire_col < spine_col_end:
        nc = max_wire_col + 1
        if 0 <= nc < WORLD_W:
            return (Tool.WIRE, nc, spine_row)

    # --- Phase 3: Build horizontal roads parallel to spine ---
    road_row_above = spine_row - 3
    road_row_below = spine_row + 3
    road_col_start = pc_col + 2
    road_col_end = spine_col_end

    for road_row in [road_row_above, road_row_below]:
        if road_row < 0 or road_row >= WORLD_H:
            continue
        road_cols_here = [c for c in range(WORLD_W) if rm[road_row, c]]
        if road_cols_here:
            max_rc = max(road_cols_here)
        else:
            max_rc = road_col_start - 1
        if max_rc < road_col_end:
            nc = max_rc + 1
            if 0 <= nc < WORLD_W:
                return (Tool.ROAD, nc, road_row)

    # --- Phase 4: Build vertical connector roads at intervals ---
    for conn_col in range(road_col_start, road_col_end + 1, 6):
        if conn_col < 0 or conn_col >= WORLD_W:
            continue
        for conn_row in range(road_row_above, road_row_below + 1):
            if conn_row < 0 or conn_row >= WORLD_H:
                continue
            if not rm[conn_row, conn_col] and not wm[conn_row, conn_col]:
                return (Tool.ROAD, conn_col, conn_row)

    # --- Phase 5: Branch wires up/down from spine to reach zones ---
    zone_rows_above = [spine_row - 6, spine_row - 10, spine_row - 14, spine_row - 18]
    zone_rows_below = [spine_row + 6, spine_row + 10, spine_row + 14, spine_row + 18]
    zone_cols = list(range(road_col_start, road_col_end + 1, 6))

    # Extend wires vertically at each zone column
    for zc in zone_cols:
        if zc < 0 or zc >= WORLD_W:
            continue
        # Upward wires
        for zr in zone_rows_above:
            if zr < 0 or zr >= WORLD_H:
                continue
            # Find topmost wire in this column above spine
            col_wires_above = [r for r in range(spine_row - 1, zr - 1, -1)
                                if wm[r, zc]]
            if col_wires_above:
                top_wire = min(col_wires_above)
            else:
                top_wire = spine_row
            # Extend wire upward if needed
            if top_wire > zr:
                nr = top_wire - 1
                if nr >= 0 and em[nr, zc]:
                    return (Tool.WIRE, zc, nr)
        # Downward wires
        for zr in zone_rows_below:
            if zr < 0 or zr >= WORLD_H:
                continue
            col_wires_below = [r for r in range(spine_row + 1, zr + 2)
                                if wm[r, zc]]
            if col_wires_below:
                bot_wire = max(col_wires_below)
            else:
                bot_wire = spine_row
            if bot_wire < zr:
                nr = bot_wire + 1
                if nr < WORLD_H and em[nr, zc]:
                    return (Tool.WIRE, zc, nr)

    # --- Phase 6: Place zones reactively ---
    # Count existing zones
    res_count = int(np.sum(res_m))
    com_count = int(np.sum(com_m))
    ind_count = int(np.sum(ind_m))
    total_zones = res_count + com_count + ind_count

    def is_area_clear(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def road_nearby(cr, cc, dist=4):
        r0 = max(0, cr - dist)
        r1 = min(WORLD_H, cr + dist + 1)
        c0 = max(0, cc - dist)
        c1 = min(WORLD_W, cc + dist + 1)
        return np.any(rm[r0:r1, c0:c1])

    def wire_nearby(cr, cc, dist=5):
        r0 = max(0, cr - dist)
        r1 = min(WORLD_H, cr + dist + 1)
        c0 = max(0, cc - dist)
        c1 = min(WORLD_W, cc + dist + 1)
        return np.any(wm[r0:r1, c0:c1])

    def pick_zone_type():
        t = total_zones + 1
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        elif ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        else:
            return Tool.RESIDENTIAL

    for zr in zone_rows_above + zone_rows_below:
        if zr < 0 or zr >= WORLD_H:
            continue
        for zc in zone_cols:
            if zc < 0 or zc >= WORLD_W:
                continue
            if road_nearby(zr, zc) and wire_nearby(zr, zc):
                if is_area_clear(zr, zc):
                    return (pick_zone_type(), zc, zr)

    # --- Phase 7: If population growing, extend zone rows further out ---
    if obs.city_pop > 50:
        extra_rows = []
        for base in zone_rows_above:
            extra_rows.append(base - 4)
        for base in zone_rows_below:
            extra_rows.append(base + 4)
        for zr in extra_rows:
            if zr < 0 or zr >= WORLD_H:
                continue
            for zc in zone_cols:
                if zc < 0 or zc >= WORLD_W:
                    continue
                if road_nearby(zr, zc, 5) and wire_nearby(zr, zc, 6):
                    if is_area_clear(zr, zc):
                        return (pick_zone_type(), zc, zr)

    # --- Phase 8: Add a second coal plant if underpowered ---
    if obs.powered_zones == 0 and np.any(res_m | com_m | ind_m):
        # Try placing another plant near the cluster
        p2x, p2y = cx + 25, cy
        if 0 <= p2x < WORLD_W and 0 <= p2y < WORLD_H:
            return (Tool.COALPOWER, p2x, p2y)

    # --- Phase 9: Extend road grid to improve connectivity ---
    for road_row in [road_row_above, road_row_below]:
        if road_row < 0 or road_row >= WORLD_H:
            continue
        for zc in zone_cols:
            if zc < 0 or zc >= WORLD_W:
                if not rm[road_row, zc]:
                    return (Tool.ROAD, zc, road_row)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map each step to find existing infrastructure
    - Builds a compact grid: power plant + wire spine + road columns + zones
    - More aggressive zone spacing and wider grid than parent
    """
