    def zone_clear(zr, zc):
        # 3x3 zone must be fully empty
        return area_free(zr, zc, 1)

    def nearby_zone(zr, zc, radius=3):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(all_zone_m[r0:r1, c0:c1])

    res_cnt = max(1, int(np.sum(res_m)) // 9)
    com_cnt = max(1, int(np.sum(com_m)) // 9)
    ind_cnt = max(1, int(np.sum(ind_m)) // 9)

    def pick_zone():
        # target ~2:1:1 res:com:ind
        if ind_cnt * 2 < com_cnt:
            return Tool.INDUSTRIAL
        if com_cnt * 2 < res_cnt:
            return Tool.COMMERCIAL
        if ind_cnt * 2 < res_cnt:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Phase 2: Build/extend wire spine vertically
    if 0 <= wire_col < WORLD_W:
        wire_rows = sorted(r for r in range(WORLD_H) if wm[r, wire_col])

        if not wire_rows:
            # Start wire adjacent to plant
            for dy in range(0, 5):
                ny = pcy + dy
                if 0 <= ny < WORLD_H and em[ny, wire_col]:
                    return (Tool.WIRE, wire_col, ny)
            for dy in range(-1, -5, -1):
                ny = pcy + dy
                if 0 <= ny < WORLD_H and em[ny, wire_col]:
                    return (Tool.WIRE, wire_col, ny)
        else:
            min_wr = wire_rows[0]
            max_wr = wire_rows[-1]
            # Extend downward first
            if max_wr < tmax:
                nr = max_wr + 1
                if em[nr, wire_col] or wm[nr, wire_col]:
                    return (Tool.WIRE, wire_col, nr)
            # Extend upward
            if min_wr > tmin:
                nr = min_wr - 1
                if em[nr, wire_col] or wm[nr, wire_col]:
                    return (Tool.WIRE, wire_col, nr)

    # Get current wire rows
    wire_rows = sorted(r for r in range(WORLD_H) if 0 <= wire_col < WORLD_W and wm[r, wire_col])
    if not wire_rows:
        return None

    # Phase 3: Build road columns alongside wire
    for rcol in [road_l, road_r]:
        if 0 <= rcol < WORLD_W:
            for wr in wire_rows:
                if not rm[wr, rcol] and em[wr, rcol]:
                    return (Tool.ROAD, rcol, wr)

    # Helper: get road rows for a column
    def road_rows_set(col):
        if 0 <= col < WORLD_W:
            return set(r for r in range(WORLD_H) if rm[r, col])
        return set()

    rrs_l = road_rows_set(road_l)
    rrs_r = road_rows_set(road_r)

    # Phase 4: Place zones adjacent to roads, striding every 4 rows for spacing
    # Left zones (col = zone_ll, next to road_l)
    if 1 <= zone_ll < WORLD_W:
        for zr in wire_rows:
            if any(abs(zr - rr) <= 1 for rr in rrs_l):
                if not nearby_zone(zr, zone_ll, 3) and zone_clear(zr, zone_ll):
                    return (pick_zone(), zone_ll, zr)

    # Right zones (col = zone_r, next to road_r)
    if 0 <= zone_r < WORLD_W:
        for zr in wire_rows:
            if any(abs(zr - rr) <= 1 for rr in rrs_r):
                if not nearby_zone(zr, zone_r, 3) and zone_clear(zr, zone_r):
                    return (pick_zone(), zone_r, zr)

    # Phase 5: Second cluster (far right) once population grows
    if obs.city_pop > 100:
        wire_col2 = zone_r + 5
        road_l2 = wire_col2 - 2
        road_r2 = wire_col2 + 2
        zone_r2 = road_r2 + 3
        zone_l2 = road_l2 - 3

        if 0 <= wire_col2 < WORLD_W:
            wire_rows2 = sorted(r for r in range(WORLD_H) if wm[r, wire_col2])

            if not wire_rows2:
                # Connect horizontal wire from spine to wire_col2 at center
                mid_y = pcy
                for wc in range(wire_col + 1, wire_col2 + 1):
                    if 0 <= wc < WORLD_W and (em[mid_y, wc] or wm[mid_y, wc]):
                        return (Tool.WIRE, wc, mid_y)
            else:
                min_wr2 = wire_rows2[0]
                max_wr2 = wire_rows2[-1]
                if max_wr2 < tmax:
                    nr = max_wr2 + 1
                    if 0 <= nr < WORLD_H and (em[nr, wire_col2] or wm[nr, wire_col2]):
                        return (Tool.WIRE, wire_col2, nr)
                if min_wr2 > tmin:
                    nr = min_wr2 - 1
                    if 0 <= nr < WORLD_H and (em[nr, wire_col2] or wm[nr, wire_col2]):
                        return (Tool.WIRE, wire_col2, nr)

                # Roads for cluster 2
                for rcol2 in [road_l2, road_r2]:
                    if 0 <= rcol2 < WORLD_W:
                        for wr in wire_rows2:
                            if not rm[wr, rcol2] and em[wr, rcol2]:
                                return (Tool.ROAD, rcol2, wr)

                rrs_l2 = road_rows_set(road_l2)
                rrs_r2 = road_rows_set(road_r2)

                # Zones for cluster 2
                for zcol2, rrs2 in [(zone_l2, rrs_l2), (zone_r2, rrs_r2)]:
                    if 1 <= zcol2 < WORLD_W - 1:
                        for zr in wire_rows2:
                            if any(abs(zr - rr) <= 1 for rr in rrs2):
                                if not nearby_zone(zr, zcol2, 3) and zone_clear(zr, zcol2):
                                    return (pick_zone(), zcol2, zr)

    # Phase 6: Second power plant for large city
    if obs.city_pop > 500 and not state.get("plant2", False):
        px2 = pcx + 30
        py2 = pcy
        if 0 <= px2 < WORLD_W - 1 and 0 <= py2 < WORLD_H - 1:
            if area_free(py2, px2, 1):
                state["plant2"] = True
                return (Tool.COALPOWER, px2, py2)
            else:
                # Try to wire path to it
                for wc in range(wire_col + 1, min(px2, WORLD_W)):
                    if em[py2, wc] or wm[py2, wc]:
                        return (Tool.WIRE, wc, py2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map every step to find existing infrastructure
    - Builds a compact city: coal plant -> wire spine -> road grid -> zones
    - Adapts to what's actually on the map each step
    - Key changes from parent:
      * Horizontal road grid (not just vertical) for better zone connectivity
      * Wire bridges run horizontally from plant through zone columns
      * Zones placed more densely around the road grid
      * Uses step-based priority to avoid thrashing
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    all_zone = resm | comm | indm

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    pop = obs.city_pop

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(total_zones, 1)
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr2, rc2 = zr + dr, zc + dc
                if not (0 <= rr2 < WORLD_H and 0 <= rc2 < WORLD_W):
                    return False
                # Allow empty or existing zone tiles only
                if not (em[rr2, rc2] or all_zone[rr2, rc2]):
                    return False
        return True

    def zone_exists_near(zr, zc, r=3):
        r0 = max(0, zr - r); r1 = min(WORLD_H, zr + r + 1)
        c0 = max(0, zc - r); c1 = min(WORLD_W, zc + r + 1)
        return np.any(all_zone[r0:r1, c0:c1])

    def has_wire_near(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_near(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    # === Phase 1: Place coal power plant if missing ===
    if not np.any(pm):
        px, py = cx - 12, cy
        return (Tool.COALPOWER, px, py)

    # Find plant centroid
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Layout: wire spine runs horizontally from plant, then vertical roads
    # wire_row = row of horizontal wire from plant
    # road_col_left, road_col_right = vertical roads flanking zone strips
    wire_row = plant_cy
    road_col_left  = plant_cx + 4
    road_col_right = plant_cx + 12
    zone_col_left  = road_col_left + 4    # zones right of left road
    zone_col_right = road_col_right + 4   # zones right of right road

    # Second vertical road further right for expansion
    road_col_right2 = road_col_right + 12
    zone_col_right2 = road_col_right2 + 4

    # Clamp all to valid range
    def clamp_col(c): return max(2, min(WORLD_W - 3, c))
    road_col_left   = clamp_col(road_col_left)
    road_col_right  = clamp_col(road_col_right)
    road_col_right2 = clamp_col(road_col_right2)
    zone_col_left   = clamp_col(zone_col_left)
    zone_col_right  = clamp_col(zone_col_right)
    zone_col_right2 = clamp_col(zone_col_right2)

    # Vertical extent based on population
    if pop < 50:
        half = 8
    elif pop < 200:
        half = 14
    elif pop < 600:
        half = 20
    else:
        half = 28

    y_min = max(1, cy - half)
    y_max = min(WORLD_H - 2, cy + half)

    # === Phase 2: Wire from plant rightward along wire_row ===
    # Build horizontal wire spine from plant to road_col_right2
    target_wire_right = road_col_right2 + 1
    # Find rightmost wire on wire_row
    wire_on_row = [c for c in range(WORLD_W) if wm[wire_row, c]]
    plant_on_row = [c for c in range(WORLD_W) if pm[wire_row, c]]

    rightmost_wire = max(wire_on_row + plant_on_row) if (wire_on_row or plant_on_row) else plant_cx

    if rightmost_wire < target_wire_right:
        nc = rightmost_wire + 1
        if nc < WORLD_W:
            if em[wire_row, nc] and not pm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)
            elif rm[wire_row, nc]:
                # Skip road tiles, continue next
                pass

    # === Phase 3: Vertical roads along road_col_left and road_col_right ===
    for rcol in [road_col_left, road_col_right, road_col_right2]:
        # Check if wire has reached this column on wire_row
        wire_reached = (wm[wire_row, rcol] or pm[wire_row, rcol] or
                        any(wm[wire_row, c] for c in range(plant_cx, rcol + 1)))

        if not wire_reached:
            continue  # Don't build road before wire reaches

        # Extend road downward from wire_row
        road_on_col = sorted([r for r in range(WORLD_H) if rm[r, rcol]])
        if not road_on_col:
            # Start road at wire_row
            if em[wire_row, rcol]:
                return (Tool.ROAD, rcol, wire_row)
        else:
            max_road = max(road_on_col)
            min_road = min(road_on_col)
            if max_road < y_max:
                nr = max_road + 1
                if nr < WORLD_H and em[nr, rcol]:
                    return (Tool.ROAD, rcol, nr)
            if min_road > y_min:
                nr = min_road - 1
                if nr >= 0 and em[nr, rcol]:
                    return (Tool.ROAD, rcol, nr)

    # === Phase 4: Wire vertically along road columns for power ===
    for rcol in [road_col_left, road_col_right, road_col_right2]:
        road_on_col = sorted([r for r in range(WORLD_H) if rm[r, rcol]])
        if not road_on_col:
            continue
        # Place wire alongside road (one col to the left of road) for zones
        wcol = rcol - 1
        if wcol < 1:
            continue
        for rr in road_on_col:
            if y_min <= rr <= y_max:
                if em[rr, wcol] and not rm[rr, wcol] and not pm[rr, wcol]:
                    return (Tool.WIRE, wcol, rr)

    # === Phase 5: Place zones in strips beside roads ===
    # For each road column, try placing zones to the right (zone strip)
    road_zone_pairs = [
        (road_col_left, zone_col_left),
        (road_col_right, zone_col_right),
        (road_col_right2, zone_col_right2),
    ]

    for rcol, zcol in road_zone_pairs:
        road_on_col = sorted([r for r in range(WORLD_H) if rm[r, rcol]])
        if not road_on_col:
            continue

        for zr in range(y_min, y_max + 1, 4):
            # Need road and wire nearby
            w_ok = has_wire_near(zr, zcol, 5)
            r_ok = has_road_near(zr, zcol, 4)
            if w_ok and r_ok:
                if not zone_exists_near(zr, zcol, 2) and zone_area_ok(zr, zcol):
                    return (pick_tool(), zcol, zr)

    # === Phase 6: Horizontal connector roads every ~6 rows ===
    if pop > 30:
        for hr in range(y_min, y_max + 1, 6):
            # Connect road_col_left to road_col_right
            for hc in range(road_col_left, road_col_right + 1):
                if em[hr, hc] and not pm[hr, hc]:
                    return (Tool.ROAD, hc, hr)

    # === Phase 7: More zones left of left road ===
    if pop > 80:
        left_zone_col = clamp_col(road_col_left - 5)
        for zr in range(y_min, y_max + 1, 4):
            w_ok = has_wire_near(zr, left_zone_col, 5)
            r_ok = has_road_near(zr, left_zone_col, 4)
            if w_ok and r_ok:
                if not zone_exists_near(zr, left_zone_col, 2) and zone_area_ok(zr, left_zone_col):
                    return (pick_tool(), left_zone_col, zr)

    # === Phase 8: Second power plant if large population ===
    plant_count = max(1, int(np.sum(pm)) // 6)
    if pop > 400 and plant_count < 2:
        px2 = clamp_col(plant_cx + 25)
        py2 = plant_cy
        if 2 <= px2 <= WORLD_W - 3 and 2 <= py2 <= WORLD_H - 3:
            if em[py2, px2]:
                return (Tool.COALPOWER, px2, py2)

    # === Phase 9: Wire lateral to reach far zones ===
    if pop > 50:
        for wr in range(y_min, y_max + 1, 3):
            # Extend wire from wire_row downward to cover zone rows
            # Actually extend wire horizontally at each zone row
            if wm[wire_row, road_col_left] or pm[wire_row, road_col_left]:
                for wc in range(road_col_left, zone_col_right + 3):
                    if wc >= WORLD_W: break
                    if wm[wr, wc]: break
                    if em[wr, wc] and not rm[wr, wc] and not pm[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    elif not em[wr, wc] and not wm[wr, wc] and not rm[wr, wc]:
                        break

    # === Phase 10: Dense zone fill anywhere with coverage ===
    if pop > 150:
        for zr in range(y_min, y_max + 1, 4):
            for zc in range(road_col_left - 4, road_col_right2 + 8, 4):
                zc2 = clamp_col(zc)
                if has_wire_near(zr, zc2, 4) and has_road_near(zr, zc2, 4):
                    if not zone_exists_near(zr, zc2, 2) and zone_area_ok(zr, zc2):
                        return (pick_tool(), zc2, zr)

    # === Phase 11: Extend wire spine further right if needed ===
    wire_on_row2 = [c for c in range(WORLD_W) if wm[wire_row, c]]
    if wire_on_row2:
        rmost = max(wire_on_row2)
        if rmost < WORLD_W - 3:
            nc = rmost + 1
            if em[wire_row, nc] and not pm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy combining best of both parents:
    - Reads tile_map every step to find existing infrastructure
    - Coal plant -> wire spine -> road columns -> zones
    - Adapts placement to what's actually on the map
    - Balanced zone mix, expanding corridor based on population
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    all_zone = resm | comm | indm

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(total_zones, 1)
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone[rr, rc]:
                    return False
        return True

    # --- Phase 1: Place coal power plant ---
    if not np.any(pm):
        return (Tool.COALPOWER, cx - 8, cy)

    # Find plant center
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Corridor geometry
    wire_col = plant_cx + 3
    road_col_r = wire_col + 3
    road_col_l = wire_col - 3
    wire_col  = max(3, min(WORLD_W - 4, wire_col))
    road_col_r = max(3, min(WORLD_W - 4, road_col_r))
    road_col_l = max(3, min(WORLD_W - 4, road_col_l))

    # Vertical extent scales with population
    pop = obs.city_pop
    if pop < 50:
        half = 8
    elif pop < 150:
        half = 12
    elif pop < 400:
        half = 18
    elif pop < 800:
        half = 26
    else:
        half = 34

    y_min = max(2, cy - half)
    y_max = min(WORLD_H - 3, cy + half)

    # Current wire spine coverage
    wire_rows = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])

    # --- Phase 2: Start wire spine adjacent to plant ---
    if not wire_rows:
        for dy in range(0, 8):
            for nr in [plant_cy + dy, plant_cy - dy]:
                if in_bounds(wire_col, nr) and em[nr, wire_col]:
                    return (Tool.WIRE, wire_col, nr)
        return None

    min_wr = min(wire_rows)
    max_wr = max(wire_rows)

    # --- Phase 3: Extend wire spine vertically (reactive to current extent) ---
    if max_wr < y_max:
        nr = max_wr + 1
        if in_bounds(wire_col, nr) and em[nr, wire_col] and not pm[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)
    if min_wr > y_min:
        nr = min_wr - 1
        if in_bounds(wire_col, nr) and em[nr, wire_col] and not pm[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)

    # --- Phase 4: Build road columns parallel to wire spine ---
    for r in wire_rows:
        if y_min <= r <= y_max:
            if in_bounds(road_col_r, r) and em[r, road_col_r] and not pm[r, road_col_r]:
                return (Tool.ROAD, road_col_r, r)
            if in_bounds(road_col_l, r) and em[r, road_col_l] and not pm[r, road_col_l]:
                return (Tool.ROAD, road_col_l, r)

    # --- Phase 5: Connect plant to wire spine if disconnected ---
    connected = False
    for dr in range(-2, 3):
        for dc in range(-2, 3):
            rr, rc = plant_cy + dr, plant_cx + dc
            if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                if wm[rr, rc]:
                    connected = True
    if not connected and wire_rows:
        bridge_r = plant_cy
        for bc in range(plant_cx + 1, wire_col + 1):
            if in_bounds(bc, bridge_r):
                if wm[bridge_r, bc]:
                    break
                if em[bridge_r, bc] and not pm[bridge_r, bc]:
                    return (Tool.WIRE, bc, bridge_r)

    # --- Phase 6: Place zones near road + wire coverage ---
    road_rows_r = sorted([r for r in range(WORLD_H) if rm[r, road_col_r]])
    road_rows_l = sorted([r for r in range(WORLD_H) if rm[r, road_col_l]])

    # Build proximity arrays
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Find candidate zone positions: empty, near road AND wire, not too close to edge
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, :2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Sort by distance to wire spine center
        dists = np.abs(cxs.astype(int) - wire_col) + np.abs(cys.astype(int) - cy)
        sort_idx = np.argsort(dists)
        for i in range(min(len(cxs), 60)):
            k = int(sort_idx[i])
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_area_ok(zy, zx):
                return (pick_tool(), zx, zy)

    # --- Phase 7: Horizontal connecting roads every 6 rows ---
    if wire_rows:
        for wr in wire_rows:
            if y_min <= wr <= y_max and (wr - y_min) % 6 == 0:
                for rc in range(road_col_l, road_col_r + 1):
                    if in_bounds(rc, wr) and em[wr, rc] and not pm[wr, rc] and not wm[wr, rc]:
                        return (Tool.ROAD, rc, wr)

    # --- Phase 8: Second power plant when population grows ---
    plant_tiles = int(np.sum(pm))
    plant_count = max(1, plant_tiles // 6)  # rough count
    if pop > 300 and plant_count < 2:
        p2x = plant_cx + 22
        p2y = plant_cy
        if in_bounds(p2x, p2y) and em[p2y, p2x]:
            # Check no nearby plant
            nearby = any(
                in_bounds(p2x + dx, p2y + dy) and pm[p2y + dy, p2x + dx]
                for dy in range(-6, 7) for dx in range(-6, 7)
            )
            if not nearby:
                return (Tool.COALPOWER, p2x, p2y)
        # Wire bridge to second plant location
        for wc in range(wire_col + 1, min(wire_col + 25, WORLD_W - 2)):
            if in_bounds(wc, plant_cy) and em[plant_cy, wc] and not pm[plant_cy, wc]:
                if not wm[plant_cy, wc]:
                    return (Tool.WIRE, wc, plant_cy)
                break

    # --- Phase 9: Third plant for large city ---
    if pop > 700 and not state.get("plant3_done", False):
        p3x = plant_cx - 22
        p3y = plant_cy
        if in_bounds(p3x, p3y) and em[p3y, p3x]:
            nearby = any(
                in_bounds(p3x + dx, p3y + dy) and pm[p3y + dy, p3x + dx]
                for dy in range(-6, 7) for dx in range(-6, 7)
            )
            if not nearby:
                state["plant3_done"] = True
                return (Tool.COALPOWER, p3x, p3y)
        # Wire leftward to connect
        for wc in range(wire_col - 1, max(wire_col - 25, 2), -1):
            if in_bounds(wc, plant_cy) and em[plant_cy, wc] and not pm[plant_cy, wc]:
                if not wm[plant_cy, wc]:
                    return (Tool.WIRE, wc, plant_cy)
                break

    # --- Phase 10: Services ---
    if pop > 300:
        fx, fy = wire_col - 8, cy - 10
        if in_bounds(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
        px2, py2 = wire_col + 8, cy + 10
        if in_bounds(px2, py2) and em[py2, px2]:
            return (Tool.POLICESTATION, px2, py2)

    # --- Phase 11: Extend wire frontier reactively ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k = int(obs.step * 7) % len(wire_xs_arr)
        wx_s = int(wire_xs_arr[step_k])
        wy_s = int(wire_ys_arr[step_k])
        for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx2, ny2 = wx_s + dx2, wy_s + dy2
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                # Only extend if it helps reach zones
                if y_min <= ny2 <= y_max:
                    return (Tool.WIRE, nx2, ny2)

    # --- Phase 12: Extend roads to reach more zone candidates ---
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = int(obs.step * 11) % len(road_xs_arr)
        rx_s = int(road_xs_arr[step_k])
        ry_s = int(road_ys_arr[step_k])
        for dy, dx in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx2, ny2 = rx_s + dx, ry_s + dy
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                if nbr_wire[ny2, nx2] and y_min <= ny2 <= y_max:
                    return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy combining best of both parents:
    - Reads tile_map every step
    - Places coal plant, extends wire spine from plant
    - Builds road columns flanking wire
    - Places zones where power+road coverage exists
    - Expands reactively based on observed map state
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    pop = obs.city_pop

    def pick_tool():
        t = max(total_zones, 1)
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Phase 1: Place first coal plant if none ---
    if not np.any(pm):
        return (Tool.COALPOWER, 60, 50)

    # Find plant centroid
    plant_ys, plant_xs = np.where(pm)
    px = int(np.median(plant_xs))
    py = int(np.median(plant_ys))

    # Layout columns relative to plant
    wire_col = px + 3
    wire_col = max(3, min(WORLD_W - 4, wire_col))
    road_col_r = wire_col + 2
    road_col_l = wire_col - 2
    road_col_r = max(3, min(WORLD_W - 4, road_col_r))
    road_col_l = max(3, min(WORLD_W - 4, road_col_l))

    # Spine extent based on pop
    if pop < 50:
        spine_half = 8
    elif pop < 150:
        spine_half = 14
    elif pop < 400:
        spine_half = 20
    elif pop < 800:
        spine_half = 26
    else:
        spine_half = 32

    target_min = max(2, py - spine_half)
    target_max = min(WORLD_H - 3, py + spine_half)

    wire_rows = [r for r in range(WORLD_H) if wm[r, wire_col]]

    # --- Phase 2: Bootstrap wire adjacent to plant ---
    if not wire_rows:
        for dy in range(-2, 3):
            nr = py + dy
            if in_bounds(wire_col, nr) and (em[nr, wire_col] or wm[nr, wire_col]) and not pm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)
        return None

    min_wr = min(wire_rows)
    max_wr = max(wire_rows)

    # --- Phase 3: Extend wire spine ---
    if max_wr < target_max:
        nr = max_wr + 1
        if in_bounds(wire_col, nr) and not pm[nr, wire_col] and (em[nr, wire_col] or wm[nr, wire_col]):
            return (Tool.WIRE, wire_col, nr)
    if min_wr > target_min:
        nr = min_wr - 1
        if in_bounds(wire_col, nr) and not pm[nr, wire_col] and (em[nr, wire_col] or wm[nr, wire_col]):
            return (Tool.WIRE, wire_col, nr)

    # --- Phase 4: Build road columns adjacent to wire ---
    for wr in wire_rows:
        if target_min <= wr <= target_max:
            if in_bounds(road_col_r, wr) and em[wr, road_col_r]:
                return (Tool.ROAD, road_col_r, wr)
            if in_bounds(road_col_l, wr) and em[wr, road_col_l]:
                return (Tool.ROAD, road_col_l, wr)

    # --- Build proximity masks ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and not zone_tiles[nr, nc]:
                    return False
        return True

    # --- Phase 5: Place zones near wire+road coverage ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prioritize candidates close to wire spine
        dists = np.abs(cxs - wire_col)
        order = np.argsort(dists)
        step_off = int(obs.step * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 80:
                break

    # --- Phase 6: Extend roads from existing roads near wire ---
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 20)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx]:
                    if nbr_wire[ny, nx]:
                        return (Tool.ROAD, nx, ny)

    # --- Phase 7: Second coal plant when growing ---
    num_plant_tiles = int(np.sum(pm))
    if pop > 200 and num_plant_tiles < 18:
        p2x = px + 22
        p2y = py
        p2x = max(3, min(WORLD_W - 4, p2x))
        p2y = max(3, min(WORLD_H - 4, p2y))
        area_ok = True
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = p2y + dr, p2x + dc
                if not in_bounds(rc, rr):
                    area_ok = False
                elif not em[rr, rc] and not pm[rr, rc]:
                    area_ok = False
        if area_ok:
            return (Tool.COALPOWER, p2x, p2y)
        # Wire horizontal bridge to second plant area
        for wc in range(wire_col + 1, p2x):
            if in_bounds(wc, py) and em[py, wc]:
                return (Tool.WIRE, wc, py)

    # --- Phase 8: Services when pop is high enough ---
    if pop > 150:
        fsx, fsy = px - 7, py - 8
        fsx = max(1, min(WORLD_W - 2, fsx))
        fsy = max(1, min(WORLD_H - 2, fsy))
        if in_bounds(fsx, fsy) and em[fsy, fsx]:
            return (Tool.FIRESTATION, fsx, fsy)
        psx, psy = px - 7, py + 8
        psx = max(1, min(WORLD_W - 2, psx))
        psy = max(1, min(WORLD_H - 2, psy))
        if in_bounds(psx, psy) and em[psy, psx]:
            return (Tool.POLICESTATION, psx, psy)

    # --- Phase 9: Extend wire laterally to reach new areas ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 15)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = wx + dx2, wy + dy2
                if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                    return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Variation: Horizontal wire spine instead of vertical.
    Two power plants placed early (left and right sides).
    Roads run vertically off horizontal spine.
    Mixed zones placed in a wide horizontal band.
    Two neighborhoods: one above and one below the spine.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def safe_empty(x, y):
        return in_bounds(x, y) and em[y, x]

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        r_r = res_count / t
        # target: 30% industrial, 30% commercial, 40% residential
        if i_r < 0.28:
            return Tool.INDUSTRIAL
        if c_r < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Place first coal plant at left-center if missing ---
    if not np.any(pm):
        return (Tool.COALPOWER, 20, 50)

    plant_ys, plant_xs = np.where(pm)
    # Find the leftmost plant
    left_plant_idx = np.argmin(plant_xs)
    px1 = int(plant_xs[left_plant_idx])
    py1 = int(plant_ys[left_plant_idx])

    # Horizontal wire spine row
    wire_row = 50  # horizontal center

    # Desired horizontal extent
    pop_factor = min(50, obs.city_pop // 10)
    hmin = max(2, 18 - pop_factor // 3)
    hmax = min(WORLD_W - 3, 22 + 60 + pop_factor)

    # --- Place second coal plant on the right when growing ---
    plant_count = len(np.unique(plant_xs // 5))  # rough count of separate plants
    num_plants = int(np.sum(pm)) // 9  # approximate (each plant is 3x3=9 tiles)
    # Check if second plant exists near x=90
    has_right_plant = any(
        pm[wire_row + dy, 90 + dx]
        for dy in range(-4, 5) for dx in range(-4, 5)
        if in_bounds(90 + dx, wire_row + dy)
    )
    if not has_right_plant and (total_zones > 8 or obs.city_pop > 100):
        if in_bounds(90, wire_row) and em[wire_row, 90]:
            return (Tool.COALPOWER, 90, wire_row)

    # --- Horizontal wire spine ---
    wire_in_row = [c for c in range(WORLD_W) if wm[wire_row, c]]

    if not wire_in_row:
        # Start wire adjacent to first plant
        for dx in range(-2, 3):
            nx = px1 + dx
            if in_bounds(nx, wire_row) and (em[wire_row, nx] or wm[wire_row, nx]):
                if not pm[wire_row, nx]:
                    return (Tool.WIRE, nx, wire_row)
    else:
        min_wc = min(wire_in_row)
        max_wc = max(wire_in_row)
        # Extend rightward first
        if max_wc < hmax:
            nc = max_wc + 1
            if in_bounds(nc, wire_row) and (em[wire_row, nc] or wm[wire_row, nc]) and not pm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)
        # Extend leftward
        if min_wc > hmin:
            nc = min_wc - 1
            if in_bounds(nc, wire_row) and (em[wire_row, nc] or wm[wire_row, nc]) and not pm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # --- Roads above and below spine ---
    road_row_up = wire_row - 1
    road_row_dn = wire_row + 1

    for wc in wire_in_row:
        if in_bounds(wc, road_row_up) and em[road_row_up, wc]:
            return (Tool.ROAD, wc, road_row_up)
        if in_bounds(wc, road_row_dn) and em[road_row_dn, wc]:
            return (Tool.ROAD, wc, road_row_dn)

    # --- Vertical road spurs every 4 columns for zone access ---
    for wc in wire_in_row:
        if wc % 4 == 0:
            # Spur upward
            for dr in range(2, 8):
                ny = wire_row - dr
                if in_bounds(wc, ny) and em[ny, wc]:
                    return (Tool.ROAD, wc, ny)
            # Spur downward
            for dr in range(2, 8):
                ny = wire_row + dr
                if in_bounds(wc, ny) and em[ny, wc]:
                    return (Tool.ROAD, wc, ny)

    # --- Reactive zone placement ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and not zone_tiles[nr, nc]:
                    return False
        return True

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Sort by distance from wire spine row
        dists = np.abs(cys - wire_row)
        order = np.argsort(dists)
        step_off = int(obs.step * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 80:
                break

    # --- Extend roads outward from existing roads near wire ---
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 20)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx]:
                    if nbr_wire[ny, nx]:
                        return (Tool.ROAD, nx, ny)

    # --- Wire from right plant toward center ---
    if has_right_plant:
        # Find right plant position
        right_plant_xs = [plant_xs[i] for i in range(len(plant_xs)) if plant_xs[i] > 60]
        if right_plant_xs:
            rpx = int(np.min(right_plant_xs))
            wire_col_right = rpx - 2
            for wc2 in range(wire_col_right, 60, -1):
                if in_bounds(wc2, wire_row) and em[wire_row, wc2]:
                    return (Tool.WIRE, wc2, wire_row)
            # Vertical spine for right plant
            for wr2 in wire_in_row:
                if in_bounds(wire_col_right, wr2) and em[wr2, wire_col_right]:
                    return (Tool.WIRE, wire_col_right, wr2)

    # --- Services when pop is high enough ---
    if obs.city_pop > 150:
        fsx, fsy = 20, wire_row - 10
        if in_bounds(fsx, fsy) and em[fsy, fsx]:
            return (Tool.FIRESTATION, fsx, fsy)
        psx, psy = 20, wire_row + 10
        if in_bounds(psx, psy) and em[psy, psx]:
            return (Tool.POLICESTATION, psx, psy)

    if obs.city_pop > 400:
        fsx2, fsy2 = 90, wire_row - 10
        if in_bounds(fsx2, fsy2) and em[fsy2, fsx2]:
            return (Tool.FIRESTATION, fsx2, fsy2)
        psx2, psy2 = 90, wire_row + 10
        if in_bounds(psx2, psy2) and em[psy2, psx2]:
            return (Tool.POLICESTATION, psx2, psy2)

    # --- Grow wire frontier laterally ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 15)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = wx + dx2, wy + dy2
                if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                    return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder.
    Each step reads the actual map state and decides what to place next.
    Strategy:
    - Coal plant at fixed anchor position
    - Wire spine grows outward from plant, guided by current wire_mask
    - Road spine grows east from plant area
    - Zones placed where wire AND road are already present nearby
    - Adapts zone mix based on current counts
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    # Fixed anchor positions
    PLANT_X, PLANT_Y = 12, 50
    ROAD_ROW = 51  # one below plant center
    WIRE_COL = 14  # just right of plant

    # === Phase 1: Ensure power plant exists ===
    if not np.any(pm):
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    # Find plant center from actual map
    pr, pc = np.where(pm)
    plant_cy = int(np.mean(pr))
    plant_cx = int(np.mean(pc))

    road_row = min(WORLD_H - 4, max(3, plant_cy + 1))
    wire_col = min(WORLD_W - 4, max(3, plant_cx + 2))

    # === Phase 2: Grow wire spine vertically from plant ===
    # Wire must be connected - grow from existing wire/plant adjacently
    def can_place_wire(r, c):
        if not (0 < r < WORLD_H - 1 and 0 < c < WORLD_W - 1):
            return False
        if not em[r, c]:
            return False
        if pm[r, c] or wm[r, c]:
            return False
        return True

    def wire_or_plant(r, c):
        if not (0 <= r < WORLD_H and 0 <= c < WORLD_W):
            return False
        return wm[r, c] or pm[r, c]

    # Grow wire column upward
    wire_top_target = max(1, road_row - 20)
    wire_bot_target = min(WORLD_H - 2, road_row + 20)

    # Find topmost wire in wire_col
    wire_rows_in_col = np.where(wm[:, wire_col] | pm[:, wire_col])[0]
    if len(wire_rows_in_col) == 0:
        # No wire yet in column - place adjacent to plant
        start_r = plant_cy - 1
        if can_place_wire(start_r, wire_col):
            return (Tool.WIRE, wire_col, start_r)
        start_r = plant_cy + 2
        if can_place_wire(start_r, wire_col):
            return (Tool.WIRE, wire_col, start_r)
    else:
        top_wire = int(np.min(wire_rows_in_col))
        bot_wire = int(np.max(wire_rows_in_col))

        # Extend upward
        if top_wire > wire_top_target:
            nr = top_wire - 1
            if can_place_wire(nr, wire_col):
                return (Tool.WIRE, wire_col, nr)

        # Extend downward
        if bot_wire < wire_bot_target:
            nr = bot_wire + 1
            if can_place_wire(nr, wire_col):
                return (Tool.WIRE, wire_col, nr)

    # === Phase 3: Grow road spine east from plant ===
    # How far to extend road based on pop
    if obs.city_pop < 150:
        road_end = min(WORLD_W - 3, plant_cx + 20)
    elif obs.city_pop < 400:
        road_end = min(WORLD_W - 3, plant_cx + 35)
    elif obs.city_pop < 800:
        road_end = min(WORLD_W - 3, plant_cx + 50)
    else:
        road_end = min(WORLD_W - 3, plant_cx + 65)

    road_start = plant_cx + 1

    # Find rightmost road in road_row
    road_cols_in_row = np.where(rm[road_row, :])[0]
    if len(road_cols_in_row) == 0:
        # No road yet - start just east of plant
        for c in range(road_start, road_start + 5):
            if 0 < c < WORLD_W - 1 and em[road_row, c] and not pm[road_row, c]:
                return (Tool.ROAD, c, road_row)
    else:
        right_road = int(np.max(road_cols_in_row))
        if right_road < road_end:
            nc = right_road + 1
            if 0 < nc < WORLD_W - 1 and em[road_row, nc] and not pm[road_row, nc]:
                return (Tool.ROAD, nc, road_row)

    # === Phase 4: Horizontal wire along row above road spine ===
    # Wire row just above road spine to carry power eastward
    w_row_above = road_row - 1
    w_row_below = road_row + 1

    # Find current road extent
    road_cols_in_row = np.where(rm[road_row, :])[0]
    current_road_end = int(np.max(road_cols_in_row)) if len(road_cols_in_row) > 0 else road_start

    # Grow wire above road eastward from wire_col
    wire_cols_above = np.where(wm[w_row_above, :] | pm[w_row_above, :])[0]
    if len(wire_cols_above) == 0:
        # Check if we can start from vertical wire
        if wire_or_plant(w_row_above, wire_col):
            pass  # already there
        else:
            # place at wire_col in w_row_above if adjacent to something
            if can_place_wire(w_row_above, wire_col):
                if wire_or_plant(w_row_above - 1, wire_col) or wire_or_plant(w_row_above + 1, wire_col):
                    return (Tool.WIRE, wire_col, w_row_above)
    else:
        right_wire_above = int(np.max(wire_cols_above))
        if right_wire_above < current_road_end + 1:
            nc = right_wire_above + 1
            if can_place_wire(nc, w_row_above):
                return (Tool.WIRE, nc, w_row_above)
            elif can_place_wire(w_row_above, nc):
                return (Tool.WIRE, nc, w_row_above)

    # Wire below road eastward
    wire_cols_below = np.where(wm[w_row_below, :] | pm[w_row_below, :])[0]
    if len(wire_cols_below) == 0:
        if can_place_wire(w_row_below, wire_col):
            if wire_or_plant(w_row_below - 1, wire_col) or wire_or_plant(w_row_below + 1, wire_col):
                return (Tool.WIRE, wire_col, w_row_below)
    else:
        right_wire_below = int(np.max(wire_cols_below))
        if right_wire_below < current_road_end + 1:
            nc = right_wire_below + 1
            if can_place_wire(w_row_below, nc):
                return (Tool.WIRE, nc, w_row_below)

    # === Phase 5: Place zones where road AND wire are already nearby ===
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(total_zones, 1)
        # Target: 50% res, 30% com, 20% ind
        if com_count / t < 0.30:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    all_zone_mask = resm | comm | indm

    def zone_area_clear(zr, zc):
        """Check 3x3 area around center is empty or already zone."""
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                tile = tm[rr, rc]
                if not (em[rr, rc] or all_zone_mask[rr, rc]):
                    return False
        return True

    def has_zone_nearby(zr, zc):
        r0, r1 = max(0, zr-2), min(WORLD_H, zr+3)
        c0, c1 = max(0, zc-2), min(WORLD_W, zc+3)
        return np.any(all_zone_mask[r0:r1, c0:c1])

    def has_road_adj(zr, zc, radius=2):
        r0, r1 = max(0, zr-radius), min(WORLD_H, zr+radius+1)
        c0, c1 = max(0, zc-radius), min(WORLD_W, zc+radius+1)
        return np.any(rm[r0:r1, c0:c1])

    def has_wire_adj(zr, zc, radius=3):
        r0, r1 = max(0, zr-radius), min(WORLD_H, zr+radius+1)
        c0, c1 = max(0, zc-radius), min(WORLD_W, zc+radius+1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    # Zone rows: above and below road
    zone_row_above = road_row - 2
    zone_row_below = road_row + 2

    # Scan for zone placement spots along road
    road_cols_now = np.where(rm[road_row, :])[0]
    if len(road_cols_now) > 0:
        r_start = int(np.min(road_cols_now))
        r_end = int(np.max(road_cols_now))
        for zc in range(r_start + 2, r_end - 1, 4):
            if zc < 2 or zc > WORLD_W - 3:
                continue
            for zr in [zone_row_above, zone_row_below]:
                if zr < 2 or zr > WORLD_H - 3:
                    continue
                if not has_zone_nearby(zr, zc) and zone_area_clear(zr, zc):
                    if has_road_adj(zr, zc) and has_wire_adj(zr, zc):
                        return (pick_tool(), zc, zr)

    # === Phase 6: Second power plant when needed ===
    if obs.city_pop > 200 and np.sum(pm) < 9:
        # Place second plant at east end of road
        if len(road_cols_now) > 0:
            px2 = min(WORLD_W - 5, int(np.max(road_cols_now)) + 4)
            py2 = road_row - 1
            if 2 <= px2 <= WORLD_W - 3 and 2 <= py2 <= WORLD_H - 3:
                if em[py2, px2]:
                    return (Tool.COALPOWER, px2, py2)
                # Try offsets
                for dy in range(-2, 3):
                    for dx in range(-2, 3):
                        ny, nx = py2 + dy, px2 + dx
                        if 2 <= nx <= WORLD_W - 3 and 2 <= ny <= WORLD_H - 3 and em[ny, nx]:
                            return (Tool.COALPOWER, nx, ny)

    # === Phase 7: Connect second plant to wire grid ===
    plant_tiles = np.where(pm)
    if len(plant_tiles[0]) >= 18:  # two plants
        # Find rightmost plant cluster
        right_col = int(np.max(plant_tiles[1]))
        right_rows = plant_tiles[0][plant_tiles[1] >= right_col - 2]
        rp_row = int(np.mean(right_rows))
        # Wire left from right plant to connect to wire grid
        for c in range(right_col - 1, wire_col, -1):
            if can_place_wire(rp_row, c):
                # Check adjacency
                if wire_or_plant(rp_row, c + 1) or wire_or_plant(rp_row, c - 1):
                    return (Tool.WIRE, c, rp_row)

    # === Phase 8: Add outer zone rows if pop growing ===
    if obs.city_pop > 300:
        zone_row_above2 = road_row - 5
        zone_row_below2 = road_row + 5
        if len(road_cols_now) > 0:
            r_start = int(np.min(road_cols_now))
            r_end = int(np.max(road_cols_now))
            for zc in range(r_start + 2, r_end - 1, 4):
                if zc < 2 or zc > WORLD_W - 3:
                    continue
                for zr in [zone_row_above2, zone_row_below2]:
                    if zr < 2 or zr > WORLD_H - 3:
                        continue
                    if not has_zone_nearby(zr, zc) and zone_area_clear(zr, zc):
                        if has_road_adj(zr, zc, 4) and has_wire_adj(zr, zc, 5):
                            return (pick_tool(), zc, zr)

    # === Phase 9: Services ===
    if obs.city_pop > 200:
        ps_x = min(WORLD_W - 3, plant_cx + 15)
        ps_y = road_row - 7
        if 2 <= ps_x <= WORLD_W - 3 and 2 <= ps_y <= WORLD_H - 3:
            if em[ps_y, ps_x]:
                return (Tool.POLICESTATION, ps_x, ps_y)

    if obs.city_pop > 350:
        fs_x = min(WORLD_W - 3, plant_cx + 25)
        fs_y = road_row + 7
        if 2 <= fs_x <= WORLD_W - 3 and 2 <= fs_y <= WORLD_H - 3:
            if em[fs_y, fs_x]:
                return (Tool.FIRESTATION, fs_x, fs_y)

    # === Phase 10: Vertical roads at zone columns for better access ===
    if len(road_cols_now) > 0:
        r_start = int(np.min(road_cols_now))
        r_end = int(np.max(road_cols_now))
        for zc in range(r_start + 2, r_end - 1, 8):
            if zc < 2 or zc > WORLD_W - 3:
                continue
            for r in range(max(1, zone_row_above - 1), min(WORLD_H - 1, zone_row_below + 2)):
                if not rm[r, zc] and em[r, zc] and not pm[r, zc]:
                    # Only place if adjacent to existing road
                    adj_road = (rm[r-1, zc] if r > 0 else False) or (rm[r+1, zc] if r < WORLD_H-1 else False) or \
                               (rm[r, zc-1] if zc > 0 else False) or (rm[r, zc+1] if zc < WORLD_W-1 else False)
                    if adj_road:
                        return (Tool.ROAD, zc, r)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map every step to determine what's already built
    - Places coal plant, then extends wire spine vertically
    - Builds road column adjacent to wire
    - Places zones beside road/wire
    - Adds lateral wires and roads to power/serve zones
    - Expands based on observed city_pop
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Phase 1: Place coal power plant if missing
    if not np.any(pm):
        # Place at center-left area
        return (Tool.COALPOWER, cx - 10, cy)

    # Find plant centroid
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Layout columns derived from plant position
    wire_col = plant_cx + 4   # wire spine just right of plant
    road_col = wire_col + 2   # road column
    left_zone_col = wire_col - 3   # zones left of wire
    right_zone_col = road_col + 3  # zones right of road

    # Clamp all columns
    wire_col = max(2, min(WORLD_W - 3, wire_col))
    road_col = max(2, min(WORLD_W - 3, road_col))
    left_zone_col = max(2, min(WORLD_W - 3, left_zone_col))
    right_zone_col = max(2, min(WORLD_W - 3, right_zone_col))

    # Scan wire spine
    wire_rows_on_spine = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])
    road_rows_on_col = sorted([r for r in range(WORLD_H) if rm[r, road_col]])

    # Spine extent scales with population
    if obs.city_pop < 50:
        spine_extent = 6
    elif obs.city_pop < 150:
        spine_extent = 10
    elif obs.city_pop < 400:
        spine_extent = 16
    elif obs.city_pop < 800:
        spine_extent = 22
    else:
        spine_extent = 30

    target_min = max(2, cy - spine_extent)
    target_max = min(WORLD_H - 3, cy + spine_extent)

    # Phase 2: Seed wire adjacent to plant if none on spine
    if not wire_rows_on_spine:
        for dy in range(0, 6):
            for nr in [plant_cy + dy, plant_cy - dy]:
                if 0 <= nr < WORLD_H:
                    cell = tm[nr, wire_col]
                    if em[nr, wire_col] or wm[nr, wire_col]:
                        return (Tool.WIRE, wire_col, nr)
        return None

    min_wire_row = min(wire_rows_on_spine)
    max_wire_row = max(wire_rows_on_spine)

    # Phase 3: Extend wire spine downward
    if max_wire_row < target_max:
        nr = max_wire_row + 1
        if nr < WORLD_H and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Phase 4: Extend wire spine upward
    if min_wire_row > target_min:
        nr = min_wire_row - 1
        if nr >= 0 and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Phase 5: Build road column alongside wire spine
    for r in wire_rows_on_spine:
        if 0 <= r < WORLD_H and 0 <= road_col < WORLD_W:
            if not rm[r, road_col] and em[r, road_col]:
                return (Tool.ROAD, road_col, r)

    all_zone_mask = resm | comm | indm

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        if com_count / t < 0.3:
            return Tool.COMMERCIAL
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Phase 6: Lay lateral wires from spine outward to left zone column
    # Do this BEFORE placing zones so power is available
    for wr in wire_rows_on_spine:
        # Only wire every 3rd row to avoid wasting steps
        if wr % 3 != 0:
            continue
        # Extend wire leftward from spine toward left_zone_col
        already_at_target = any(wm[wr, c] for c in range(left_zone_col - 1, left_zone_col + 2) if 0 <= c < WORLD_W)
        if not already_at_target:
            for wc in range(wire_col - 1, left_zone_col - 2, -1):
                if 0 <= wc < WORLD_W:
                    if wm[wr, wc]:
                        break
                    if em[wr, wc] and not pm[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    elif not em[wr, wc]:
                        break

    # Phase 7: Place zones where wire AND road coverage exists
    zone_rows = list(range(max(2, target_min), min(WORLD_H - 2, target_max + 1), 3))

    for zr in zone_rows:
        wire_near = any(abs(zr - wr) <= 2 for wr in wire_rows_on_spine)
        road_near = any(abs(zr - rr) <= 2 for rr in road_rows_on_col)

        if wire_near and road_near:
            # Try left zone
            zc = left_zone_col
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc, 5) and has_road_nearby(zr, zc, 5):
                    return (pick_tool(), zc, zr)

            # Try right zone
            zc = right_zone_col
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_road_nearby(zr, zc, 5) and has_wire_nearby(zr, zc, 5):
                    return (pick_tool(), zc, zr)

    # Phase 8: Extend wire rightward to power right zones
    for wr in wire_rows_on_spine:
        if wr % 3 != 0:
            continue
        already_right = any(wm[wr, c] for c in range(right_zone_col - 1, right_zone_col + 2) if 0 <= c < WORLD_W)
        if not already_right:
            for wc in range(wire_col + 1, right_zone_col + 2):
                if 0 <= wc < WORLD_W:
                    if wm[wr, wc]:
                        break
                    # Skip road tiles (place wire only on empty)
                    if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    elif rm[wr, wc]:
                        continue  # road is ok, skip
                    elif not em[wr, wc]:
                        break

    # Phase 9: Extend road horizontally to right zones
    for rr in wire_rows_on_spine:
        if not rm[rr, road_col]:
            continue
        for rc in range(road_col + 1, right_zone_col + 2):
            if 0 <= rc < WORLD_W:
                if rm[rr, rc]:
                    break
                if em[rr, rc] and not pm[rr, rc]:
                    return (Tool.ROAD, rc, rr)
                elif not em[rr, rc]:
                    break

    # Phase 10: Second coal plant if population is high
    plant_count = int(np.sum(pm)) // 9  # approx number of 3x3 plants
    if obs.city_pop > 350 and plant_count < 2:
        px2 = plant_cx + 20
        py2 = plant_cy
        if 2 <= py2 <= WORLD_H - 3 and 2 <= px2 <= WORLD_W - 3:
            if em[py2, px2]:
                return (Tool.COALPOWER, px2, py2)
            # Try nearby
            for dy in [-3, 3, -6, 6]:
                pyt = py2 + dy
                if 2 <= pyt <= WORLD_H - 3 and em[pyt, px2]:
                    return (Tool.COALPOWER, px2, pyt)

    # Phase 11: Connect second plant to grid with wire
    if np.sum(pm) > 9:  # more than one plant
        # Find all plant tile clusters
        p_rows, p_cols = np.where(pm)
        # Find rightmost plant
        right_plant_cx = int(np.max(p_cols))
        right_plant_cy = int(p_rows[np.argmax(p_cols)])
        # Wire from right plant toward wire spine
        for wc in range(right_plant_cx - 1, wire_col - 1, -1):
            if 0 <= wc < WORLD_W:
                if wm[right_plant_cy, wc] or pm[right_plant_cy, wc]:
                    break
                if em[right_plant_cy, wc]:
                    return (Tool.WIRE, wc, right_plant_cy)
                else:
                    break

    # Phase 12: Wider zone expansion as city grows
    if obs.city_pop > 200:
        extra_cols = [left_zone_col - 4, right_zone_col + 4]
        for zc in extra_cols:
            if 2 <= zc <= WORLD_W - 3:
                for zr in zone_rows:
                    if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                        if has_road_nearby(zr, zc, 6) and has_wire_nearby(zr, zc, 7):
                            return (pick_tool(), zc, zr)

    # Phase 13: Fill gaps in road column
    for r in range(target_min, target_max + 1):
        if 0 <= r < WORLD_H and 0 <= road_col < WORLD_W:
            if not rm[r, road_col] and em[r, road_col] and not pm[r, road_col]:
                # Only fill if adjacent road exists
                has_adj_road = (
                    (r > 0 and rm[r-1, road_col]) or
                    (r < WORLD_H-1 and rm[r+1, road_col])
                )
                if has_adj_road:
                    return (Tool.ROAD, road_col, r)

    # Phase 14: Fill gaps in wire spine
    for r in range(target_min, target_max + 1):
        if 0 <= r < WORLD_H and 0 <= wire_col < WORLD_W:
            if not wm[r, wire_col] and em[r, wire_col] and not pm[r, wire_col]:
                has_adj_wire = (
                    (r > 0 and wm[r-1, wire_col]) or
                    (r < WORLD_H-1 and wm[r+1, wire_col])
                )
                if has_adj_wire:
                    return (Tool.WIRE, wire_col, r)

    return None

def act(obs, state):
    """
    Variation: horizontal wire spine instead of vertical, two road rows above/below,
    zones placed in bands, more aggressive commercial/industrial mix,
    multiple power plants spaced horizontally from the start.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Initialize state
    if 'phase' not in state:
        state['phase'] = 'init'
        state['wire_col_start'] = 20
        state['wire_col_end'] = 100
        state['wire_row'] = 50  # horizontal wire spine row
        state['road_row_top'] = 47  # road above spine
        state['road_row_bot'] = 53  # road below spine
        state['plant_placed'] = []

    wire_row = state['wire_row']
    road_top = state['road_row_top']
    road_bot = state['road_row_bot']
    wcol_start = state['wire_col_start']
    wcol_end = state['wire_col_end']

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool(x):
        # Vary zone type by column position for diversity
        col_mod = (x // 8) % 5
        if col_mod == 0:
            return Tool.INDUSTRIAL
        elif col_mod == 1 or col_mod == 2:
            return Tool.COMMERCIAL
        else:
            return Tool.RESIDENTIAL

    # --- Phase 1: Place first coal plant ---
    if not np.any(pm):
        return (Tool.COALPOWER, 40, wire_row)

    plant_ys, plant_xs = np.where(pm)

    # --- Phase 2: Build horizontal wire spine ---
    # Wire along wire_row from wcol_start to wcol_end
    wire_in_row = [c for c in range(WORLD_W) if wm[wire_row, c]]

    if not wire_in_row:
        # Start wire next to plant
        px_c = int(np.mean(plant_xs))
        for dc in range(-1, 3):
            nc = px_c + dc
            if in_bounds(nc, wire_row) and em[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)
    else:
        min_wc = min(wire_in_row)
        max_wc = max(wire_in_row)
        # Extend wire rightward
        if max_wc < wcol_end:
            nc = max_wc + 1
            if in_bounds(nc, wire_row) and (em[wire_row, nc] or wm[wire_row, nc]) and not pm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)
        # Extend wire leftward
        if min_wc > wcol_start:
            nc = min_wc - 1
            if in_bounds(nc, wire_row) and (em[wire_row, nc] or wm[wire_row, nc]) and not pm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    wire_in_row = [c for c in range(WORLD_W) if wm[wire_row, c]]

    # --- Phase 3: Build road rows parallel to wire spine ---
    for wc in wire_in_row:
        if not (wcol_start <= wc <= wcol_end):
            continue
        # Top road row
        if in_bounds(wc, road_top) and em[road_top, wc]:
            return (Tool.ROAD, wc, road_top)
        # Bottom road row
        if in_bounds(wc, road_bot) and em[road_bot, wc]:
            return (Tool.ROAD, wc, road_bot)

    # --- Phase 4: Add vertical connecting roads every 8 columns ---
    for wc in wire_in_row:
        if not (wcol_start <= wc <= wcol_end):
            continue
        if (wc - wcol_start) % 8 == 0:
            for r in range(road_top, road_bot + 1):
                if in_bounds(wc, r) and not rm[r, wc] and em[r, wc] and not pm[r, wc]:
                    return (Tool.ROAD, wc, r)

    # --- Phase 5: Place second coal plant when needed ---
    if total_zones > 12 or obs.city_pop > 200:
        p2x, p2y = 75, wire_row
        if in_bounds(p2x, p2y):
            nearby = any(pm[wire_row + dy, p2x + dx]
                        for dy in range(-4, 5) for dx in range(-4, 5)
                        if in_bounds(p2x + dx, wire_row + dy))
            if not nearby and em[p2y, p2x]:
                return (Tool.COALPOWER, p2x, p2y)

    # --- Phase 6: Place zones reactively ---
    # Build neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    all_zone_m = resm | comm | indm
    zone_rows, zone_cols = np.where(all_zone_m)
    zone_set = set(zip(zone_rows.tolist(), zone_cols.tolist()))

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Sort by distance to wire spine center
        cx_center = (wcol_start + wcol_end) // 2
        dists = np.abs(cxs - cx_center) + np.abs(cys - wire_row) * 2
        sort_idx = np.argsort(dists)
        for i in range(min(len(cxs), 100)):
            k = int(sort_idx[i])
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(zx), zx, zy)

    # --- Phase 7: Third plant and second horizontal cluster offset vertically ---
    if obs.city_pop > 400 and not state.get('cluster2_started', False):
        state['cluster2_started'] = True
        state['wire_row2'] = wire_row - 12
        state['road_top2'] = wire_row - 15
        state['road_bot2'] = wire_row - 9

    if state.get('cluster2_started', False):
        wr2 = state['wire_row2']
        rt2 = state['road_top2']
        rb2 = state['road_bot2']
        # Plant for cluster 2
        p3x, p3y = 55, wr2
        if in_bounds(p3x, p3y):
            nearby3 = any(pm[wr2 + dy, p3x + dx]
                         for dy in range(-4, 5) for dx in range(-4, 5)
                         if in_bounds(p3x + dx, wr2 + dy))
            if not nearby3 and em[p3y, p3x]:
                return (Tool.COALPOWER, p3x, p3y)
        # Wire for cluster 2
        wire2 = [c for c in range(WORLD_W) if in_bounds(c, wr2) and wm[wr2, c]]
        if not wire2:
            for dc in range(-1, 3):
                nc = p3x + dc
                if in_bounds(nc, wr2) and em[wr2, nc]:
                    return (Tool.WIRE, nc, wr2)
        else:
            mxw2 = max(wire2)
            mnw2 = min(wire2)
            if mxw2 < wcol_end:
                nc = mxw2 + 1
                if in_bounds(nc, wr2) and (em[wr2, nc] or wm[wr2, nc]) and not pm[wr2, nc]:
                    return (Tool.WIRE, nc, wr2)
            if mnw2 > wcol_start:
                nc = mnw2 - 1
                if in_bounds(nc, wr2) and (em[wr2, nc] or wm[wr2, nc]) and not pm[wr2, nc]:
                    return (Tool.WIRE, nc, wr2)
        # Roads for cluster 2
        wire2 = [c for c in range(WORLD_W) if in_bounds(c, wr2) and wm[wr2, c]]
        for wc in wire2:
            if in_bounds(wc, rt2) and em[rt2, wc]:
                return (Tool.ROAD, wc, rt2)
            if in_bounds(wc, rb2) and em[rb2, wc]:
                return (Tool.ROAD, wc, rb2)

    # --- Services ---
    if obs.city_pop > 300:
        fx, fy = wcol_start + 5, wire_row - 8
        if in_bounds(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
        if in_bounds(fx + 8, fy) and em[fy, fx + 8]:
            return (Tool.POLICESTATION, fx + 8, fy)

    # --- Extend road sideways to reach more zones ---
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = int(obs.step * 11) % len(road_xs_arr)
        rx_s = int(road_xs_arr[step_k])
        ry_s = int(road_ys_arr[step_k])
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx2, ny2 = rx_s + dx, ry_s + dy
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                if nbr_wire[ny2, nx2]:
                    return (Tool.ROAD, nx2, ny2)

    # --- Extend wire if stuck ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 7) % len(wire_xs_arr)
        wx_s = int(wire_xs_arr[step_k2])
        wy_s = int(wire_ys_arr[step_k2])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = wx_s + dx2, wy_s + dy2
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy v2:
    - Reads tile_map each step
    - Builds a cross-shaped wire network from plant
    - Roads run parallel to wire
    - Zones placed wherever road+wire coverage found
    - Scales infrastructure with population
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Place first coal plant if missing ---
    if not np.any(pm):
        return (Tool.COALPOWER, 55, 45)

    # Find plant center
    plant_ys, plant_xs = np.where(pm)
    px = int(np.median(plant_xs))
    py = int(np.median(plant_ys))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Wire spines: vertical column to right of plant, horizontal row below plant
    wire_col_v = px + 2  # vertical spine column
    wire_row_h = py + 2  # horizontal spine row

    # Scale extent with population
    pop_ext = min(35, max(10, obs.city_pop // 20))
    v_tmin = max(2, py - 2 - pop_ext)
    v_tmax = min(WORLD_H - 3, py + 2 + pop_ext)
    h_lmin = max(2, px - 2 - pop_ext)
    h_rmax = min(WORLD_W - 3, px + 2 + pop_ext)

    # Check current wire extents
    wire_in_vcol = [r for r in range(WORLD_H) if wm[r, wire_col_v]]
    wire_in_hrow = [c for c in range(WORLD_W) if wm[wire_row_h, c]]

    # --- Build vertical wire spine ---
    if not wire_in_vcol:
        for dy in range(-2, 3):
            ny = py + dy
            if in_bounds(wire_col_v, ny) and (em[ny, wire_col_v] or wm[ny, wire_col_v]):
                return (Tool.WIRE, wire_col_v, ny)
    else:
        min_vw = min(wire_in_vcol)
        max_vw = max(wire_in_vcol)
        if max_vw < v_tmax:
            nr = max_vw + 1
            if in_bounds(wire_col_v, nr) and em[nr, wire_col_v] and not pm[nr, wire_col_v]:
                return (Tool.WIRE, wire_col_v, nr)
        if min_vw > v_tmin:
            nr = min_vw - 1
            if in_bounds(wire_col_v, nr) and em[nr, wire_col_v] and not pm[nr, wire_col_v]:
                return (Tool.WIRE, wire_col_v, nr)

    # --- Build horizontal wire spine ---
    if not wire_in_hrow:
        for dx in range(-2, 3):
            nx = px + dx
            if in_bounds(nx, wire_row_h) and (em[wire_row_h, nx] or wm[wire_row_h, nx]):
                return (Tool.WIRE, nx, wire_row_h)
    else:
        min_hw = min(wire_in_hrow)
        max_hw = max(wire_in_hrow)
        if max_hw < h_rmax:
            nc = max_hw + 1
            if in_bounds(nc, wire_row_h) and em[wire_row_h, nc] and not pm[wire_row_h, nc]:
                return (Tool.WIRE, nc, wire_row_h)
        if min_hw > h_lmin:
            nc = min_hw - 1
            if in_bounds(nc, wire_row_h) and em[wire_row_h, nc] and not pm[wire_row_h, nc]:
                return (Tool.WIRE, nc, wire_row_h)

    # --- Roads flanking wire spines ---
    road_col_r = wire_col_v + 1
    road_col_l = wire_col_v - 1
    road_row_above = wire_row_h - 1
    road_row_below = wire_row_h + 1

    # Build roads along vertical spine
    for wr in wire_in_vcol:
        if in_bounds(road_col_r, wr) and em[wr, road_col_r]:
            return (Tool.ROAD, road_col_r, wr)
        if in_bounds(road_col_l, wr) and em[wr, road_col_l]:
            return (Tool.ROAD, road_col_l, wr)

    # Build roads along horizontal spine
    for wc in wire_in_hrow:
        if in_bounds(wc, road_row_above) and em[road_row_above, wc]:
            return (Tool.ROAD, wc, road_row_above)
        if in_bounds(wc, road_row_below) and em[road_row_below, wc]:
            return (Tool.ROAD, wc, road_row_below)

    # --- Build proximity masks ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and not zone_tiles[nr, nc]:
                    return False
        return True

    # --- Candidate zone placement ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Sort candidates: prefer near both spines (cross pattern)
        dist_v = np.abs(cxs - wire_col_v)
        dist_h = np.abs(cys - wire_row_h)
        dists = np.minimum(dist_v, dist_h)
        order = np.argsort(dists)
        step_off = int(obs.step * 3) % max(len(order), 1)
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            if i > 80:
                break

    # --- Extend roads near wire ---
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 25)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx]:
                    if nbr_wire[ny, nx]:
                        return (Tool.ROAD, nx, ny)

    # --- Second power plant when city grows ---
    if total_zones > 15 or obs.city_pop > 350:
        # Place second plant below the first
        p2x = px
        p2y = py + 25
        if in_bounds(p2x, p2y):
            nearby = any(
                in_bounds(p2x + ddx, p2y + ddy) and pm[p2y + ddy, p2x + ddx]
                for ddy in range(-6, 7) for ddx in range(-6, 7)
            )
            if not nearby and em[p2y, p2x]:
                return (Tool.COALPOWER, p2x, p2y)
            # Wire vertical bridge from horizontal spine to second plant
            for wc2 in range(wire_row_h + 1, p2y - 1):
                if in_bounds(px + 2, wc2) and em[wc2, px + 2]:
                    return (Tool.WIRE, px + 2, wc2)

    # --- Third power plant for large city ---
    if obs.city_pop > 600:
        p3x = px + 25
        p3y = py
        if in_bounds(p3x, p3y):
            nearby = any(
                in_bounds(p3x + ddx, p3y + ddy) and pm[p3y + ddy, p3x + ddx]
                for ddy in range(-6, 7) for ddx in range(-6, 7)
            )
            if not nearby and em[p3y, p3x]:
                return (Tool.COALPOWER, p3x, p3y)
            # Wire horizontal bridge to third plant
            for wc3 in range(wire_col_v + 1, p3x - 1):
                if in_bounds(wc3, py) and em[py, wc3]:
                    return (Tool.WIRE, wc3, py)

    # --- Services when pop is high enough ---
    if obs.city_pop > 100:
        fsx, fsy = px - 7, py - 8
        if in_bounds(fsx, fsy) and em[fsy, fsx]:
            return (Tool.FIRESTATION, fsx, fsy)
        psx, psy = px + 8, py - 8
        if in_bounds(psx, psy) and em[psy, psx]:
            return (Tool.POLICESTATION, psx, psy)

    # --- Grow wire frontier laterally ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 20)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = wx + dx2, wy + dy2
                if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                    return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy.
    Strategy: place coal plant, wire spine horizontally, roads perpendicular,
    then zones adjacent to roads. Everything decided by reading current map.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    has_plant = np.any(pm)

    # ---- Phase 1: Place coal power plant ----
    if not has_plant:
        return (Tool.COALPOWER, 60, 50)

    # Find plant center
    plant_rows, plant_cols = np.where(pm)
    pcx = int(np.mean(plant_cols))
    pcy = int(np.mean(plant_rows))

    # Layout: horizontal wire spine at pcy-2, roads above/below, zones further
    wire_row = pcy - 2
    wire_row = max(2, min(WORLD_H - 3, wire_row))

    road_row_top = wire_row - 2
    road_row_bot = wire_row + 2
    zone_row_top = road_row_top - 3
    zone_row_bot = road_row_bot + 3

    road_row_top = max(2, min(WORLD_H - 3, road_row_top))
    road_row_bot = max(2, min(WORLD_H - 3, road_row_bot))
    zone_row_top = max(2, min(WORLD_H - 3, zone_row_top))
    zone_row_bot = max(2, min(WORLD_H - 3, zone_row_bot))

    # Horizontal span: grow with population
    half_span = min(40, max(12, 12 + obs.city_pop // 10))
    cmin = max(2, pcx - half_span)
    cmax = min(WORLD_W - 3, pcx + half_span)

    # ---- Phase 2: Build horizontal wire spine ----
    wire_cols = sorted(c for c in range(WORLD_W) if 0 <= wire_row < WORLD_H and wm[wire_row, c])

    if not wire_cols:
        # Start wire adjacent to plant
        for dx in [0, 1, -1, 2, -2, 3, -3]:
            nx = pcx + dx
            if 0 <= nx < WORLD_W and 0 <= wire_row < WORLD_H:
                if em[wire_row, nx]:
                    return (Tool.WIRE, nx, wire_row)
        return (Tool.WIRE, pcx, wire_row)
    else:
        min_wc = wire_cols[0]
        max_wc = wire_cols[-1]
        # Connect plant to wire if not adjacent
        # Extend rightward first
        if max_wc < cmax:
            nc = max_wc + 1
            if 0 <= nc < WORLD_W:
                return (Tool.WIRE, nc, wire_row)
        # Extend leftward
        if min_wc > cmin:
            nc = min_wc - 1
            if 0 <= nc < WORLD_W:
                return (Tool.WIRE, nc, wire_row)

    wire_cols_set = set(wire_cols)

    # ---- Helper: check if 3x3 area is clear ----
    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    all_zone_m = res_m | com_m | ind_m

    def nearby_zone(zr, zc, radius=2):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(all_zone_m[r0:r1, c0:c1])

    res_count = max(1, int(np.sum(res_m)) // 9)
    com_count = max(1, int(np.sum(com_m)) // 9)
    ind_count = max(1, int(np.sum(ind_m)) // 9)

    def pick_zone():
        total = res_count + com_count + ind_count
        if com_count * 4 < total:
            return Tool.COMMERCIAL
        if ind_count * 4 < total:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # ---- Phase 3: Build road rows (parallel to wire spine) ----
    if wire_cols:
        # Top road row
        if 0 <= road_row_top < WORLD_H:
            for wc in wire_cols:
                if cmin <= wc <= cmax and not rm[road_row_top, wc] and em[road_row_top, wc]:
                    return (Tool.ROAD, wc, road_row_top)
        # Bottom road row
        if 0 <= road_row_bot < WORLD_H:
            for wc in wire_cols:
                if cmin <= wc <= cmax and not rm[road_row_bot, wc] and em[road_row_bot, wc]:
                    return (Tool.ROAD, wc, road_row_bot)

    # ---- Phase 4: Place zones adjacent to roads ----
    if wire_cols:
        road_cols_top = set(c for c in range(WORLD_W) if 0 <= road_row_top < WORLD_H and rm[road_row_top, c])
        road_cols_bot = set(c for c in range(WORLD_W) if 0 <= road_row_bot < WORLD_H and rm[road_row_bot, c])

        # Zones above top road
        for zc in wire_cols:
            if not (cmin <= zc <= cmax):
                continue
            road_near = any(abs(zc - rc) <= 1 for rc in road_cols_top)
            if road_near and 2 <= zone_row_top <= WORLD_H - 3:
                if not nearby_zone(zone_row_top, zc) and zone_area_free(zone_row_top, zc):
                    return (pick_zone(), zc, zone_row_top)

        # Zones below bottom road
        for zc in wire_cols:
            if not (cmin <= zc <= cmax):
                continue
            road_near = any(abs(zc - rc) <= 1 for rc in road_cols_bot)
            if road_near and 2 <= zone_row_bot <= WORLD_H - 3:
                if not nearby_zone(zone_row_bot, zc) and zone_area_free(zone_row_bot, zc):
                    return (pick_zone(), zc, zone_row_bot)

        # Also place zones between wire and roads (inner zones)
        zone_row_inner_top = wire_row - 1
        zone_row_inner_bot = wire_row + 1
        for zc in wire_cols:
            if not (cmin <= zc <= cmax):
                continue
            # inner top
            if 2 <= zone_row_inner_top <= WORLD_H - 3:
                road_near = any(abs(zc - rc) <= 1 for rc in road_cols_top)
                if road_near and not nearby_zone(zone_row_inner_top, zc) and zone_area_free(zone_row_inner_top, zc):
                    return (pick_zone(), zc, zone_row_inner_top)
            # inner bot
            if 2 <= zone_row_inner_bot <= WORLD_H - 3:
                road_near = any(abs(zc - rc) <= 1 for rc in road_cols_bot)
                if road_near and not nearby_zone(zone_row_inner_bot, zc) and zone_area_free(zone_row_inner_bot, zc):
                    return (pick_zone(), zc, zone_row_inner_bot)

    # ---- Phase 5: Second cluster (second horizontal band) ----
    if obs.city_pop > 80 and wire_cols:
        wire_row2 = pcy + 8
        wire_row2 = max(2, min(WORLD_H - 3, wire_row2))
        road_row2_top = wire_row2 - 2
        road_row2_bot = wire_row2 + 2
        zone_row2_top = road_row2_top - 3
        zone_row2_bot = road_row2_bot + 3
        road_row2_top = max(2, min(WORLD_H - 3, road_row2_top))
        road_row2_bot = max(2, min(WORLD_H - 3, road_row2_bot))
        zone_row2_top = max(2, min(WORLD_H - 3, zone_row2_top))
        zone_row2_bot = max(2, min(WORLD_H - 3, zone_row2_bot))

        wire_cols2 = sorted(c for c in range(WORLD_W) if 0 <= wire_row2 < WORLD_H and wm[wire_row2, c])

        if not wire_cols2:
            # Bridge vertically from wire_row to wire_row2 at pcx
            for wr in range(min(wire_row, wire_row2) + 1, max(wire_row, wire_row2)):
                if 0 <= wr < WORLD_H and (em[wr, pcx] or wm[wr, pcx]):
                    return (Tool.WIRE, pcx, wr)
            if 0 <= wire_row2 < WORLD_H and em[wire_row2, pcx]:
                return (Tool.WIRE, pcx, wire_row2)
        else:
            min_wc2 = wire_cols2[0]
            max_wc2 = wire_cols2[-1]
            if max_wc2 < cmax:
                nc = max_wc2 + 1
                if 0 <= nc < WORLD_W:
                    return (Tool.WIRE, nc, wire_row2)
            if min_wc2 > cmin:
                nc = min_wc2 - 1
                if 0 <= nc < WORLD_W:
                    return (Tool.WIRE, nc, wire_row2)

            # Roads for cluster 2
            if 0 <= road_row2_top < WORLD_H:
                for wc in wire_cols2:
                    if cmin <= wc <= cmax and not rm[road_row2_top, wc] and em[road_row2_top, wc]:
                        return (Tool.ROAD, wc, road_row2_top)
            if 0 <= road_row2_bot < WORLD_H:
                for wc in wire_cols2:
                    if cmin <= wc <= cmax and not rm[road_row2_bot, wc] and em[road_row2_bot, wc]:
                        return (Tool.ROAD, wc, road_row2_bot)

            road_cols2_top = set(c for c in range(WORLD_W) if 0 <= road_row2_top < WORLD_H and rm[road_row2_top, c])
            road_cols2_bot = set(c for c in range(WORLD_W) if 0 <= road_row2_bot < WORLD_H and rm[road_row2_bot, c])

            for zc in wire_cols2:
                if not (cmin <= zc <= cmax):
                    continue
                road_near = any(abs(zc - rc) <= 1 for rc in road_cols2_top)
                if road_near and 2 <= zone_row2_top <= WORLD_H - 3:
                    if not nearby_zone(zone_row2_top, zc) and zone_area_free(zone_row2_top, zc):
                        return (pick_zone(), zc, zone_row2_top)
                road_near = any(abs(zc - rc) <= 1 for rc in road_cols2_bot)
                if road_near and 2 <= zone_row2_bot <= WORLD_H - 3:
                    if not nearby_zone(zone_row2_bot, zc) and zone_area_free(zone_row2_bot, zc):
                        return (pick_zone(), zc, zone_row2_bot)

    # ---- Phase 6: Second power plant when large ----
    if obs.city_pop > 400 and not state.get("plant2_placed", False):
        px2 = pcx + 25
        py2 = pcy
        px2 = max(2, min(WORLD_W - 3, px2))
        py2 = max(2, min(WORLD_H - 3, py2))
        clear = all(
            0 <= py2 + dr < WORLD_H and 0 <= px2 + dc < WORLD_W and em[py2 + dr, px2 + dc]
            for dr in [-1, 0, 1] for dc in [-1, 0, 1]
        )
        if clear:
            state["plant2_placed"] = True
            return (Tool.COALPOWER, px2, py2)
        # Wire bridge toward plant2 location
        for wc in range(max_wc if wire_cols else pcx, min(px2 + 1, WORLD_W)):
            if 0 <= wire_row < WORLD_H and (em[wire_row, wc] or wm[wire_row, wc]):
                return (Tool.WIRE, wc, wire_row)

    # ---- Phase 7: Vertical road connectors for better grid connectivity ----
    if wire_cols and obs.city_pop > 150:
        # Vertical road connecting road_row_top to road_row_bot at center column
        vc = pcx
        if 0 <= vc < WORLD_W:
            for vr in range(road_row_top, road_row_bot + 1):
                if 0 <= vr < WORLD_H and not rm[vr, vc] and em[vr, vc]:
                    return (Tool.ROAD, vc, vr)

    return None

def build_plan():
    # Use a different anchor point - upper-left quadrant
    cx, cy = 35, 40

    plan = []

    # Coal power plant
    plan.append((Tool.COALPOWER, cx, cy))

    # Horizontal wire spine from plant going right
    for dx in range(0, 20):
        plan.append((Tool.WIRE, cx + dx, cy))

    # Vertical road spines at multiple columns for zone access
    for dx in [4, 8, 12, 16]:
        for dy in range(-10, 11):
            plan.append((Tool.ROAD, cx + dx, cy + dy))
        # Wire connecting road column to horizontal spine
        plan.append((Tool.WIRE, cx + dx, cy))

    # Horizontal roads crossing the vertical spines
    for dy in [-9, -6, -3, 0, 3, 6, 9]:
        for dx in range(3, 18):
            plan.append((Tool.ROAD, cx + dx, cy + dy))

    # Residential zones in a grid pattern (3x3 centered)
    # Place between road columns
    for col_dx in [2, 6, 10, 14]:
        for row_dy in [-8, -5, -2, 1, 4, 7]:
            plan.append((Tool.RESIDENTIAL, cx + col_dx, cy + row_dy))

    # Commercial zones - mix in with residential grid
    for col_dx in [4, 8, 12]:
        for row_dy in [-7, -1, 5]:
            plan.append((Tool.COMMERCIAL, cx + col_dx, cy + row_dy))

    # Industrial zones on the far left near plant
    for row_dy in [-6, -3, 0, 3, 6]:
        plan.append((Tool.INDUSTRIAL, cx - 3, cy + row_dy))

    # Road connecting industrial to main grid
    for dy in range(-7, 8):
        plan.append((Tool.ROAD, cx + 1, cy + dy))

    # ---- Second neighborhood to the right ----
    cx2, cy2 = 80, 55

    # Wire connection from first plant area to second neighborhood
    # Horizontal wire bridge
    for x in range(cx + 18, cx2 + 1):
        plan.append((Tool.WIRE, x, cy))
    # Vertical wire to second neighborhood
    for y in range(cy, cy2 + 1):
        plan.append((Tool.WIRE, cx2, y))

    # Second power plant or just wire feed
    plan.append((Tool.COALPOWER, cx2, cy2))

    # Road spines for second neighborhood
    for dx in [4, 8, 12]:
        for dy in range(-8, 9):
            plan.append((Tool.ROAD, cx2 + dx, cy2 + dy))
        plan.append((Tool.WIRE, cx2 + dx, cy2))

    for dy in [-6, -3, 0, 3, 6]:
        for dx in range(3, 14):
            plan.append((Tool.ROAD, cx2 + dx, cy2 + dy))

    # Residential in second neighborhood
    for col_dx in [2, 6, 10]:
        for row_dy in [-5, -2, 1, 4]:
            plan.append((Tool.RESIDENTIAL, cx2 + col_dx, cy2 + row_dy))

    # Commercial in second neighborhood
    for col_dx in [4, 8]:
        for row_dy in [-4, 2]:
            plan.append((Tool.COMMERCIAL, cx2 + col_dx, cy2 + row_dy))

    # Industrial near second power plant
    for row_dy in [-4, -1, 2]:
        plan.append((Tool.INDUSTRIAL, cx2 - 3, cy2 + row_dy))

    return plan


def act(obs, state):
    if "plan" not in state:
        state["plan"] = build_plan()
        state["i"] = 0

    i = state["i"]
    plan = state["plan"]

    if i < len(plan):
        state["i"] = i + 1
        return plan[i]

    # Reactive phase: fill empty space near roads with zones
    tm = obs.tile_map
    emp = empty_mask(tm)
    road = road_mask(tm)
    res = res_mask(tm)
    com = com_mask(tm)
    ind = ind_mask(tm)

    # Neighbor masks
    def neighbors(mask):
        n = np.zeros_like(mask)
        n[1:, :] |= mask[:-1, :]
        n[:-1, :] |= mask[1:, :]
        n[:, 1:] |= mask[:, :-1]
        n[:, :-1] |= mask[:, 1:]
        return n

    nbr_road = neighbors(road)
    nbr_zone = neighbors(res | com | ind)

    # Good candidates: empty, near road, near existing zone
    cand = emp & nbr_road & nbr_zone
    if not cand.any():
        cand = emp & nbr_road
    if not cand.any():
        return None

    ys, xs = np.where(cand)
    k = int(tm.sum() + obs.step * 7) % len(xs)

    # Vary zone type: mostly residential, some commercial, some industrial
    r = (obs.step + k) % 10
    if r < 5:
        tool = Tool.RESIDENTIAL
    elif r < 8:
        tool = Tool.COMMERCIAL
    else:
        tool = Tool.INDUSTRIAL

    return (tool, int(xs[k]), int(ys[k]))

def act(obs, state):
    """
    Closed-loop policy: each step reads the current map and decides the next action
    based on what is actually there. Uses a phase system but each phase uses
    map observations to find valid placement locations.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    step = obs.step
    n = obs.n_steps

    # --- Helper: check if a 3x3 area centered at (cx, cy) is all empty ---
    def zone_clear(cx, cy):
        for dy in range(-1, 2):
            for dx in range(-1, 2):
                ny, nx = cy + dy, cx + dx
                if ny < 0 or ny >= WORLD_H or nx < 0 or nx >= WORLD_W:
                    return False
                if not em[ny, nx]:
                    return False
        return True

    def has_road_nearby(cx, cy, r=2):
        for dy in range(-r, r+1):
            for dx in range(-r, r+1):
                ny, nx = cy+dy, cx+dx
                if 0 <= ny < WORLD_H and 0 <= nx < WORLD_W:
                    if rm[ny, nx]:
                        return True
        return False

    def has_wire_nearby(cx, cy, r=2):
        for dy in range(-r, r+1):
            for dx in range(-r, r+1):
                ny, nx = cy+dy, cx+dx
                if 0 <= ny < WORLD_H and 0 <= nx < WORLD_W:
                    if wm[ny, nx]:
                        return True
        return False

    def has_plant_nearby(cx, cy, r=6):
        for dy in range(-r, r+1):
            for dx in range(-r, r+1):
                ny, nx = cy+dy, cx+dx
                if 0 <= ny < WORLD_H and 0 <= nx < WORLD_W:
                    if pm[ny, nx]:
                        return True
        return False

    # State init
    if 'seq' not in state:
        state['seq'] = 0
        state['zone_idx'] = 0
        state['road_col'] = 0

    # --- Core layout constants ---
    # Power plant placed first, then wires fan out, then roads, then zones
    # Plant 1: center (20, 50)
    P1X, P1Y = 20, 50
    # Plant 2: center (95, 50)
    P2X, P2Y = 95, 50

    # Main horizontal wire backbone at y=50
    # Roads at y=43 and y=57 (above and below zone rows)
    ROAD_TOP = 43
    ROAD_BOT = 57
    WIRE_Y = 50

    # Zone columns: every 3 from x=24 to x=92, centered between roads
    # Zones at y=46 (near top road) and y=54 (near bottom road)
    ZONE_Y1 = 47  # between top road (43) and wire (50)
    ZONE_Y2 = 53  # between wire (50) and bottom road (57)

    # Build zone x positions
    zone_cols = list(range(24, 93, 3))

    seq = state['seq']

    # Phase 0: Place plant 1
    if seq == 0:
        state['seq'] = 1
        return (Tool.COALPOWER, P1X, P1Y)

    # Phase 1: Place plant 2
    if seq == 1:
        state['seq'] = 2
        return (Tool.COALPOWER, P2X, P2Y)

    # Phase 2: Lay horizontal wire from plant1 to plant2 at y=WIRE_Y
    # Wire from x=23 to x=92 at y=50
    if seq == 2:
        # Find leftmost wire gap in the backbone
        for wx in range(23, 93):
            if not wm[WIRE_Y, wx]:
                return (Tool.WIRE, wx, WIRE_Y)
        state['seq'] = 3
        return None

    # Phase 3: Lay top road (y=ROAD_TOP) from x=23 to x=92
    if seq == 3:
        for rx in range(23, 93):
            if not rm[ROAD_TOP, rx]:
                return (Tool.ROAD, rx, ROAD_TOP)
        state['seq'] = 4
        return None

    # Phase 4: Lay bottom road (y=ROAD_BOT) from x=23 to x=92
    if seq == 4:
        for rx in range(23, 93):
            if not rm[ROAD_BOT, rx]:
                return (Tool.ROAD, rx, ROAD_BOT)
        state['seq'] = 5
        return None

    # Phase 5: Lay vertical roads every 6 columns connecting top to bottom road
    # Also connects to wire backbone
    if seq == 5:
        for vx in range(24, 93, 6):
            for vy in range(ROAD_TOP, ROAD_BOT+1):
                if not rm[vy, vx] and not pm[vy, vx]:
                    return (Tool.ROAD, vx, vy)
        state['seq'] = 6
        return None

    # Phase 6: Place wire verticals alongside road verticals to power zones
    # Wire at x=vx+1 from y=ROAD_TOP to y=ROAD_BOT (adjacent to vertical road)
    if seq == 6:
        for vx in range(24, 93, 6):
            wx = vx + 1
            if wx >= WORLD_W:
                continue
            for wy in range(ROAD_TOP, ROAD_BOT+1):
                if not wm[wy, wx] and not pm[wy, wx]:
                    # Only place if wire backbone or adjacent wire exists
                    if wm[WIRE_Y, wx] or has_wire_nearby(wx, wy, 1):
                        return (Tool.WIRE, wx, wy)
        state['seq'] = 7
        return None

    # Phase 7: Place zones row 1 (y=ZONE_Y1) across zone_cols
    if seq == 7:
        res_count = int(np.sum(res_mask(tm)))
        com_count = int(np.sum(com_mask(tm)))
        ind_count = int(np.sum(ind_mask(tm)))
        total = res_count + com_count + ind_count + 1

        for zx in zone_cols:
            if zone_clear(zx, ZONE_Y1):
                # pick zone type based on ratio
                if ind_count / total < 0.25:
                    return (Tool.INDUSTRIAL, zx, ZONE_Y1)
                elif com_count / total < 0.33:
                    return (Tool.COMMERCIAL, zx, ZONE_Y1)
                else:
                    return (Tool.RESIDENTIAL, zx, ZONE_Y1)
        state['seq'] = 8
        return None

    # Phase 8: Place zones row 2 (y=ZONE_Y2) across zone_cols
    if seq == 8:
        res_count = int(np.sum(res_mask(tm)))
        com_count = int(np.sum(com_mask(tm)))
        ind_count = int(np.sum(ind_mask(tm)))
        total = res_count + com_count + ind_count + 1

        for zx in zone_cols:
            if zone_clear(zx, ZONE_Y2):
                if ind_count / total < 0.25:
                    return (Tool.INDUSTRIAL, zx, ZONE_Y2)
                elif com_count / total < 0.33:
                    return (Tool.COMMERCIAL, zx, ZONE_Y2)
                else:
                    return (Tool.RESIDENTIAL, zx, ZONE_Y2)
        state['seq'] = 9
        return None

    # Phase 9: Add service buildings (fire, police) near center
    if seq == 9:
        # Fire station near center
        if zone_clear(55, 50):
            state['seq'] = 10
            return (Tool.FIRESTATION, 55, 50)
        state['seq'] = 10
        return None

    if seq == 10:
        if zone_clear(62, 50):
            state['seq'] = 11
            return (Tool.POLICESTATION, 62, 50)
        state['seq'] = 11
        return None

    # Phase 11+: Closed-loop expansion - scan for empty spots near roads+wires and place zones
    # Also extend roads and wires if needed
    res_count = int(np.sum(res_mask(tm)))
    com_count = int(np.sum(com_mask(tm)))
    ind_count = int(np.sum(ind_mask(tm)))
    total = res_count + com_count + ind_count + 1

    # Add a third zone row above top road if there's room
    ZONE_Y3 = 37
    ROAD_TOP2 = 33

    # Extend wire upward from wire backbone verticals
    for vx in range(24, 93, 6):
        wx = vx + 1
        if wx >= WORLD_W:
            continue
        # Check if wire exists at WIRE_Y
        if wm[WIRE_Y, wx]:
            # Extend wire upward toward y=33
            for wy in range(WIRE_Y - 1, ROAD_TOP2 - 1, -1):
                if not wm[wy, wx] and not pm[wy, wx] and em[wy, wx]:
                    return (Tool.WIRE, wx, wy)

    # Add second top road
    for rx in range(23, 93):
        if not rm[ROAD_TOP2, rx] and em[ROAD_TOP2, rx]:
            # Only extend if there's an existing road segment or wire nearby
            if rm[ROAD_TOP2, rx-1] if rx > 0 else False:
                return (Tool.ROAD, rx, ROAD_TOP2)
            if rx == 23 and has_road_nearby(rx, ROAD_TOP2, 3):
                return (Tool.ROAD, rx, ROAD_TOP2)

    # Place zones at y=37 (third row)
    for zx in zone_cols:
        if zone_clear(zx, ZONE_Y3):
            if has_road_nearby(zx, ZONE_Y3, 3) and has_wire_nearby(zx, ZONE_Y3, 3):
                if ind_count / total < 0.25:
                    return (Tool.INDUSTRIAL, zx, ZONE_Y3)
                elif com_count / total < 0.33:
                    return (Tool.COMMERCIAL, zx, ZONE_Y3)
                else:
                    return (Tool.RESIDENTIAL, zx, ZONE_Y3)

    # Reactive: scan for any empty spot near existing road+wire
    for cy in range(35, 65, 3):
        for cx in range(24, 93, 3):
            if zone_clear(cx, cy) and has_road_nearby(cx, cy, 2) and has_wire_nearby(cx, cy, 2):
                if ind_count / total < 0.25:
                    return (Tool.INDUSTRIAL, cx, cy)
                elif com_count / total < 0.33:
                    return (Tool.COMMERCIAL, cx, cy)
                else:
                    return (Tool.RESIDENTIAL, cx, cy)

    # If still steps remain and population is growing, add more wire/road extensions
    # Extend wire backbone further
    for wy in range(ROAD_TOP2, WIRE_Y):
        for wx in range(23, 93, 3):
            if not wm[wy, wx] and not pm[wy, wx] and em[wy, wx]:
                if has_wire_nearby(wx, wy, 1):
                    return (Tool.WIRE, wx, wy)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Every step reads tile_map to find existing infrastructure
    - Grows power/road/zone network from observed edges
    - More compact layout: road and wire closer together, zones on both sides
    - Adapts to what's already built rather than following a fixed plan
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    all_zone_mask = resm | comm | indm

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        if com_count / t < 0.30:
            return Tool.COMMERCIAL
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_area_clear(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc, radius=2):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(all_zone_mask[r0:r1, c0:c1])

    def near(mask, zr, zc, radius=4):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return bool(np.any(mask[r0:r1, c0:c1]))

    # Phase 1: Place coal plant if missing
    if not np.any(pm):
        px, py = cx - 8, cy
        return (Tool.COALPOWER, px, py)

    # Find plant centroid
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Layout: wire spine 2 right of plant, road 2 right of wire
    # zones 2 left of wire and 2 right of road
    wire_col = plant_cx + 4
    road_col = wire_col + 2
    left_zone_col = wire_col - 3
    right_zone_col = road_col + 3

    wire_col = max(3, min(WORLD_W - 4, wire_col))
    road_col = max(3, min(WORLD_W - 4, road_col))
    left_zone_col = max(3, min(WORLD_W - 4, left_zone_col))
    right_zone_col = max(3, min(WORLD_W - 4, right_zone_col))

    # Adaptive spine extent
    if obs.city_pop < 50:
        spine_extent = 8
    elif obs.city_pop < 200:
        spine_extent = 14
    elif obs.city_pop < 500:
        spine_extent = 20
    elif obs.city_pop < 1000:
        spine_extent = 28
    else:
        spine_extent = 36

    target_min = max(2, cy - spine_extent)
    target_max = min(WORLD_H - 3, cy + spine_extent)

    # Find current wire spine extent
    wire_rows_on_spine = [r for r in range(WORLD_H) if wm[r, wire_col]]
    road_rows_on_col = [r for r in range(WORLD_H) if rm[r, road_col]]

    # Phase 2: Seed wire adjacent to plant if none
    if not wire_rows_on_spine:
        # Connect plant to wire_col: lay wire row by row from plant
        for dy in range(0, 8):
            for nr in [plant_cy + dy, plant_cy - dy]:
                if 0 <= nr < WORLD_H:
                    if em[nr, wire_col] or wm[nr, wire_col]:
                        return (Tool.WIRE, wire_col, nr)
        # Try bridging from plant to wire_col horizontally
        for wc in range(plant_cx + 3, wire_col + 1):
            if 0 <= wc < WORLD_W and em[plant_cy, wc]:
                return (Tool.WIRE, wc, plant_cy)
        return None

    min_wire_row = min(wire_rows_on_spine)
    max_wire_row = max(wire_rows_on_spine)

    # Phase 3: Grow wire spine toward targets (extend whichever end is closer to its target)
    need_down = max_wire_row < target_max
    need_up = min_wire_row > target_min
    if need_down:
        nr = max_wire_row + 1
        if nr < WORLD_H and em[nr, wire_col] and not pm[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)
    if need_up:
        nr = min_wire_row - 1
        if nr >= 0 and em[nr, wire_col] and not pm[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)

    # Phase 4: Build road spine alongside wire, matching its extent
    if wire_rows_on_spine:
        for r in wire_rows_on_spine:
            if 0 <= r < WORLD_H and em[r, road_col]:
                return (Tool.ROAD, road_col, r)

    # Phase 5: Lay lateral wires from spine to left zone column (every 3rd row)
    for wr in wire_rows_on_spine:
        if wr % 3 != 0:
            continue
        # Check if wire already reaches left_zone_col area
        reached = any(wm[wr, c] for c in range(max(0, left_zone_col - 1), min(WORLD_W, left_zone_col + 2)))
        if not reached:
            # Extend leftward from wire_col
            for wc in range(wire_col - 1, left_zone_col - 2, -1):
                if 0 < wc < WORLD_W:
                    if wm[wr, wc]:
                        break
                    if em[wr, wc] and not pm[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    elif not em[wr, wc]:
                        break

    # Phase 6: Lay lateral wires rightward from spine to right zone column (every 3rd row)
    for wr in wire_rows_on_spine:
        if wr % 3 != 0:
            continue
        reached = any(wm[wr, c] for c in range(max(0, right_zone_col - 1), min(WORLD_W, right_zone_col + 2)))
        if not reached:
            for wc in range(wire_col + 1, right_zone_col + 2):
                if 0 <= wc < WORLD_W:
                    if wm[wr, wc]:
                        break
                    if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    elif rm[wr, wc]:
                        continue
                    elif not em[wr, wc]:
                        break

    # Phase 7: Extend road horizontally to right zone column (only from rows with road)
    for rr in road_rows_on_col:
        if rr % 3 != 0:
            continue
        for rc in range(road_col + 1, right_zone_col + 2):
            if 0 <= rc < WORLD_W:
                if rm[rr, rc]:
                    break
                if em[rr, rc] and not pm[rr, rc]:
                    return (Tool.ROAD, rc, rr)
                elif not em[rr, rc]:
                    break

    # Phase 8: Place zones reactively - find where wire AND road coverage exist
    zone_rows = list(range(max(2, target_min), min(WORLD_H - 2, target_max + 1), 3))

    for zr in zone_rows:
        wire_near = near(wm, zr, left_zone_col, 5) or near(pm, zr, left_zone_col, 5)
        road_near = near(rm, zr, left_zone_col, 5)
        if wire_near and road_near:
            zc = left_zone_col
            if not zone_already_there(zr, zc) and zone_area_clear(zr, zc):
                return (pick_tool(), zc, zr)

        wire_near = near(wm, zr, right_zone_col, 5) or near(pm, zr, right_zone_col, 5)
        road_near = near(rm, zr, right_zone_col, 5)
        if wire_near and road_near:
            zc = right_zone_col
            if not zone_already_there(zr, zc) and zone_area_clear(zr, zc):
                return (pick_tool(), zc, zr)

    # Phase 9: Second coal plant for larger cities
    plant_count = max(1, int(np.sum(pm)) // 9)
    if obs.city_pop > 300 and plant_count < 2:
        px2 = plant_cx + 18
        py2 = plant_cy
        if 2 <= py2 <= WORLD_H - 3 and 2 <= px2 <= WORLD_W - 3:
            if em[py2, px2]:
                return (Tool.COALPOWER, px2, py2)
            for dy in [-4, 4, -8, 8]:
                pyt = py2 + dy
                if 2 <= pyt <= WORLD_H - 3 and em[pyt, px2]:
                    return (Tool.COALPOWER, px2, pyt)

    # Phase 10: Connect second plant to grid
    if int(np.sum(pm)) > 9:
        p_rows, p_cols = np.where(pm)
        right_plant_cx = int(np.max(p_cols))
        right_plant_cy = int(p_rows[np.argmax(p_cols)])
        for wc in range(right_plant_cx - 1, wire_col - 1, -1):
            if 0 <= wc < WORLD_W:
                if wm[right_plant_cy, wc] or pm[right_plant_cy, wc]:
                    break
                if em[right_plant_cy, wc]:
                    return (Tool.WIRE, wc, right_plant_cy)
                else:
                    break

    # Phase 11: Wider expansion
    if obs.city_pop > 300:
        extra_left = left_zone_col - 4
        extra_right = right_zone_col + 4
        for zc in [extra_left, extra_right]:
            if 3 <= zc <= WORLD_W - 4:
                for zr in zone_rows:
                    wire_near = near(wm, zr, zc, 6) or near(pm, zr, zc, 6)
                    road_near = near(rm, zr, zc, 6)
                    if wire_near and road_near:
                        if not zone_already_there(zr, zc) and zone_area_clear(zr, zc):
                            return (pick_tool(), zc, zr)

    # Phase 12: Fill gaps in road column (gap = no road but adjacent road exists)
    for r in range(target_min, target_max + 1):
        if 0 <= r < WORLD_H and 0 <= road_col < WORLD_W:
            if not rm[r, road_col] and em[r, road_col] and not pm[r, road_col]:
                adj = ((r > 0 and rm[r-1, road_col]) or
                       (r < WORLD_H-1 and rm[r+1, road_col]))
                if adj:
                    return (Tool.ROAD, road_col, r)

    # Phase 13: Fill gaps in wire spine
    for r in range(target_min, target_max + 1):
        if 0 <= r < WORLD_H and 0 <= wire_col < WORLD_W:
            if not wm[r, wire_col] and em[r, wire_col] and not pm[r, wire_col]:
                adj = ((r > 0 and wm[r-1, wire_col]) or
                       (r < WORLD_H-1 and wm[r+1, wire_col]))
                if adj:
                    return (Tool.WIRE, wire_col, r)

    # Phase 14: Dense zone packing - try placing between existing zone rows
    for zr in range(max(2, target_min), min(WORLD_H - 2, target_max + 1)):
        for zc in [left_zone_col, right_zone_col]:
            if not zone_already_there(zr, zc, 1) and zone_area_clear(zr, zc):
                if (near(wm, zr, zc, 5) or near(pm, zr, zc, 5)) and near(rm, zr, zc, 5):
                    return (pick_tool(), zc, zr)

    return None

def act(obs, state):
    """
    Variation: Horizontal wire spine instead of vertical, with zones above/below.
    Two power plants connected by horizontal wire backbone.
    Roads run vertically from spine to serve zones.
    More commercial/industrial focus in lower half.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Power plant positions
    P1X, P1Y = 30, 50   # primary plant - left side
    P2X, P2Y = 70, 50   # secondary plant - right side

    plant_ys, plant_xs = np.where(pm)
    has_plant1 = False
    has_plant2 = False
    for py_, px_ in zip(plant_ys.tolist(), plant_xs.tolist()):
        if abs(px_ - P1X) <= 5 and abs(py_ - P1Y) <= 5:
            has_plant1 = True
        if abs(px_ - P2X) <= 5 and abs(py_ - P2Y) <= 5:
            has_plant2 = True

    if not has_plant1:
        return (Tool.COALPOWER, P1X, P1Y)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))

    def pick_zone(row):
        # More industrial/commercial than parent
        if ind_count == 0:
            return Tool.INDUSTRIAL
        if com_count == 0:
            return Tool.COMMERCIAL
        # rows above spine -> more residential, below -> more industrial/commercial
        if row < 50:
            # balanced above
            if res_count <= com_count + ind_count:
                return Tool.RESIDENTIAL
            elif com_count <= ind_count:
                return Tool.COMMERCIAL
            else:
                return Tool.INDUSTRIAL
        else:
            # more I/C below
            if ind_count * 2 < res_count:
                return Tool.INDUSTRIAL
            if com_count * 2 < res_count:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL

    def zone_area_free(zy, zx):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zy + dr, zx + dc
                if not in_bounds(rc, rr):
                    return False
                if not bool(em[rr, rc]):
                    return False
        return True

    # Horizontal wire spine row
    WIRE_ROW = 50  # horizontal spine at y=50

    # How far to extend the spine
    base_span = 15
    extra_span = min(35, obs.city_pop // 15)
    target_span = base_span + extra_span

    # Spine extends from P1X to P2X and beyond
    wire_cols_in_row = sorted(c for c in range(WORLD_W) if bool(wm[WIRE_ROW, c]))

    # Extend wire spine horizontally
    if not wire_cols_in_row:
        # Start wire adjacent to plant1
        wc = P1X + 2
        if in_bounds(wc, WIRE_ROW) and bool(em[WIRE_ROW, wc]):
            return (Tool.WIRE, wc, WIRE_ROW)
    else:
        min_wc = min(wire_cols_in_row)
        max_wc = max(wire_cols_in_row)
        left_target = max(3, P1X - target_span // 2)
        right_target = min(WORLD_W - 3, P2X + target_span // 2)

        # Extend rightward first
        if max_wc < right_target:
            nc = max_wc + 1
            if in_bounds(nc, WIRE_ROW) and bool(em[WIRE_ROW, nc]) and not bool(pm[WIRE_ROW, nc]):
                return (Tool.WIRE, nc, WIRE_ROW)
        # Extend leftward
        if min_wc > left_target:
            nc = min_wc - 1
            if in_bounds(nc, WIRE_ROW) and bool(em[WIRE_ROW, nc]) and not bool(pm[WIRE_ROW, nc]):
                return (Tool.WIRE, nc, WIRE_ROW)

    # Build vertical road columns above and below the spine
    # Roads at WIRE_ROW-1 and WIRE_ROW+1 running vertically
    ROAD_ROW_U = WIRE_ROW - 1  # road just above spine
    ROAD_ROW_D = WIRE_ROW + 1  # road just below spine

    road_positions = set(zip(*np.where(rm))) if np.any(rm) else set()

    # For each wire column, place road above and below
    for wc in wire_cols_in_row:
        if not bool(rm[ROAD_ROW_U, wc]) and in_bounds(wc, ROAD_ROW_U) and bool(em[ROAD_ROW_U, wc]):
            return (Tool.ROAD, wc, ROAD_ROW_U)
        if not bool(rm[ROAD_ROW_D, wc]) and in_bounds(wc, ROAD_ROW_D) and bool(em[ROAD_ROW_D, wc]):
            return (Tool.ROAD, wc, ROAD_ROW_D)

    # Extend vertical roads upward and downward from road rows
    road_cols_U = set(c for (r, c) in road_positions if r == ROAD_ROW_U)
    road_cols_D = set(c for (r, c) in road_positions if r == ROAD_ROW_D)

    # Zone rows: place zones 3 tiles away from road rows
    ZONE_ROW_U1 = WIRE_ROW - 4   # first zone row above
    ZONE_ROW_U2 = WIRE_ROW - 8   # second zone row above
    ZONE_ROW_D1 = WIRE_ROW + 4   # first zone row below
    ZONE_ROW_D2 = WIRE_ROW + 8   # second zone row below

    # Place zones adjacent to roads (every 3 columns for 3x3 zones)
    for wc in wire_cols_in_row:
        if wc < 3 or wc >= WORLD_W - 3:
            continue
        # Only place zones at columns divisible by 3 offset from a base
        if (wc - P1X) % 4 != 0:
            continue

        road_U_nearby = wc in road_cols_U
        road_D_nearby = wc in road_cols_D

        if road_U_nearby:
            for zrow in [ZONE_ROW_U1, ZONE_ROW_U2]:
                if 2 <= zrow < WORLD_H - 2 and in_bounds(wc, zrow):
                    if zone_area_free(zrow, wc):
                        return (pick_zone(zrow), wc, zrow)

        if road_D_nearby:
            for zrow in [ZONE_ROW_D1, ZONE_ROW_D2]:
                if 2 <= zrow < WORLD_H - 2 and in_bounds(wc, zrow):
                    if zone_area_free(zrow, wc):
                        return (pick_zone(zrow), wc, zrow)

    # Extend vertical roads from ROAD_ROW_U upward to reach ZONE_ROW_U2
    for wc in list(road_cols_U):
        for row in range(ROAD_ROW_U - 1, max(ZONE_ROW_U2 - 1, 0), -1):
            if not bool(rm[row, wc]) and in_bounds(wc, row) and bool(em[row, wc]) and not bool(pm[row, wc]):
                return (Tool.ROAD, wc, row)
            elif not bool(em[row, wc]) and not bool(pm[row, wc]):
                break

    # Extend vertical roads from ROAD_ROW_D downward
    for wc in list(road_cols_D):
        for row in range(ROAD_ROW_D + 1, min(ZONE_ROW_D2 + 2, WORLD_H)):
            if not bool(rm[row, wc]) and in_bounds(wc, row) and bool(em[row, wc]) and not bool(pm[row, wc]):
                return (Tool.ROAD, wc, row)
            elif not bool(em[row, wc]) and not bool(pm[row, wc]):
                break

    # Phase 2: second power plant
    if obs.city_pop > 80:
        if not has_plant2:
            return (Tool.COALPOWER, P2X, P2Y)
        # Connect plant2 to spine via wire
        for wc in range(P2X + 2, min(P2X + 10, WORLD_W)):
            if not bool(wm[WIRE_ROW, wc]) and in_bounds(wc, WIRE_ROW) and bool(em[WIRE_ROW, wc]):
                return (Tool.WIRE, wc, WIRE_ROW)

    # Services
    if obs.city_pop > 300:
        fx, fy = P1X + 10, WIRE_ROW - 12
        if in_bounds(fx, fy) and zone_area_free(fy, fx):
            return (Tool.FIRESTATION, fx, fy)

    if obs.city_pop > 500:
        px2, py2 = P2X - 10, WIRE_ROW + 12
        if in_bounds(px2, py2) and zone_area_free(py2, px2):
            return (Tool.POLICESTATION, px2, py2)

    # Also add lateral wires from spine toward zone columns to power them
    for wc in wire_cols_in_row:
        for dr in [-3, -6, 3, 6]:
            nr = WIRE_ROW + dr
            if in_bounds(wc, nr) and not bool(wm[nr, wc]) and bool(em[nr, wc]) and not bool(pm[nr, wc]) and not bool(rm[nr, wc]):
                return (Tool.WIRE, wc, nr)

    # Fallback: extend roads
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = int(obs.step * 13) % max(len(road_xs), 1)
        rx_s, ry_s = int(road_xs[step_k]), int(road_ys[step_k])
        for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx2, ny2 = rx_s + dx2, ry_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wires
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        step_k2 = int(obs.step * 7) % max(len(wire_xs), 1)
        wx_s, wy_s = int(wire_xs[step_k2]), int(wire_ys[step_k2])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = wx_s + dx2, wy_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads map every step to find existing infrastructure
    - Builds a wider grid: central wire spine + 2 road corridors on each side
    - Zones fill between roads, adapting to what's already placed
    - Multiple power plants scale with population
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    all_zone = resm | comm | indm

    cx, cy = WORLD_W // 2, WORLD_H // 2
    pop = obs.city_pop

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(total_zones, 1)
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zy, zx):
        if zy < 1 or zy > WORLD_H - 2 or zx < 1 or zx > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zy + dr, zx + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone[rr, rc]:
                    return False
        return True

    # Vertical extent scales with population
    if pop < 50:
        half = 10
    elif pop < 150:
        half = 16
    elif pop < 400:
        half = 22
    elif pop < 800:
        half = 30
    else:
        half = 38

    y_min = max(2, cy - half)
    y_max = min(WORLD_H - 3, cy + half)

    # --- Phase 1: Place first coal power plant ---
    if not np.any(pm):
        return (Tool.COALPOWER, cx - 6, cy)

    # Find plant center
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Corridor geometry: wire spine + 4 road columns (2 per side)
    wire_col = plant_cx + 4
    wire_col = max(3, min(WORLD_W - 4, wire_col))

    # Two road corridors on right, two on left
    road_r1 = wire_col + 3
    road_r2 = wire_col + 7
    road_l1 = wire_col - 3
    road_l2 = wire_col - 7
    road_r1 = max(3, min(WORLD_W - 4, road_r1))
    road_r2 = max(3, min(WORLD_W - 4, road_r2))
    road_l1 = max(3, min(WORLD_W - 4, road_l1))
    road_l2 = max(3, min(WORLD_W - 4, road_l2))

    road_cols = [road_l2, road_l1, road_r1, road_r2]

    # --- Phase 2: Build wire spine ---
    wire_rows = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])

    if not wire_rows:
        # Start wire adjacent to plant
        for dy in range(0, 10):
            for nr in [plant_cy + dy, plant_cy - dy]:
                if in_bounds(wire_col, nr) and em[nr, wire_col]:
                    return (Tool.WIRE, wire_col, nr)
        return None

    min_wr = min(wire_rows)
    max_wr = max(wire_rows)

    # Extend wire spine vertically
    if max_wr < y_max:
        nr = max_wr + 1
        if in_bounds(wire_col, nr) and em[nr, wire_col] and not pm[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)
    if min_wr > y_min:
        nr = min_wr - 1
        if in_bounds(wire_col, nr) and em[nr, wire_col] and not pm[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)

    # --- Phase 3: Connect plant to wire spine ---
    connected = any(
        0 <= plant_cy + dr < WORLD_H and 0 <= plant_cx + dc < WORLD_W and wm[plant_cy + dr, plant_cx + dc]
        for dr in range(-2, 3) for dc in range(-2, 3)
    )
    if not connected:
        for bc in range(plant_cx + 1, wire_col + 1):
            if in_bounds(bc, plant_cy):
                if wm[plant_cy, bc]:
                    break
                if em[plant_cy, bc] and not pm[plant_cy, bc]:
                    return (Tool.WIRE, bc, plant_cy)

    # --- Phase 4: Build road columns ---
    for r in wire_rows:
        if y_min <= r <= y_max:
            for rc in road_cols:
                if in_bounds(rc, r) and em[r, rc] and not pm[r, rc]:
                    return (Tool.ROAD, rc, r)

    # --- Phase 5: Build horizontal wires connecting road columns to spine ---
    # Every 4 rows, run a wire row connecting wire spine to road corridors
    for r in wire_rows:
        if y_min <= r <= y_max and (r - y_min) % 4 == 0:
            # Wire from spine to road_r1
            for rc in range(wire_col + 1, road_r1 + 1):
                if in_bounds(rc, r) and em[r, rc] and not pm[r, rc] and not wm[r, rc] and not rm[r, rc]:
                    return (Tool.WIRE, rc, r)
            # Wire from spine to road_l1
            for rc in range(wire_col - 1, road_l1 - 1, -1):
                if in_bounds(rc, r) and em[r, rc] and not pm[r, rc] and not wm[r, rc] and not rm[r, rc]:
                    return (Tool.WIRE, rc, r)

    # --- Phase 6: Build proximity arrays for zone placement ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Candidate zone positions
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, :2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        dists = np.abs(cxs_arr.astype(int) - wire_col) + np.abs(cys_arr.astype(int) - cy)
        sort_idx = np.argsort(dists)
        for i in range(min(len(cxs_arr), 80)):
            k = int(sort_idx[i])
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_area_ok(zy, zx):
                return (pick_tool(), zx, zy)

    # --- Phase 7: Horizontal connecting roads every 6 rows ---
    for r in wire_rows:
        if y_min <= r <= y_max and (r - y_min) % 6 == 0:
            # Connect l2 to l1 to spine area
            for rc in range(road_l2, road_r2 + 1):
                if in_bounds(rc, r) and em[r, rc] and not pm[r, rc] and not wm[r, rc]:
                    return (Tool.ROAD, rc, r)

    # --- Phase 8: Second power plant ---
    plant_tiles = int(np.sum(pm))
    plant_count = max(1, plant_tiles // 6)
    if pop > 200 and plant_count < 2:
        p2x = plant_cx + 20
        p2y = plant_cy
        if in_bounds(p2x, p2y) and em[p2y, p2x]:
            nearby = any(
                in_bounds(p2x + dx, p2y + dy) and pm[p2y + dy, p2x + dx]
                for dy in range(-6, 7) for dx in range(-6, 7)
            )
            if not nearby:
                return (Tool.COALPOWER, p2x, p2y)
        # Wire rightward to second plant
        for wc in range(wire_col + 1, min(wire_col + 22, WORLD_W - 2)):
            if in_bounds(wc, plant_cy) and not pm[plant_cy, wc]:
                if wm[plant_cy, wc]:
                    break
                if em[plant_cy, wc]:
                    return (Tool.WIRE, wc, plant_cy)
                break

    # --- Phase 9: Third power plant ---
    if pop > 500 and plant_count < 3 and not state.get("plant3_done", False):
        p3x = plant_cx - 20
        p3y = plant_cy
        if in_bounds(p3x, p3y) and em[p3y, p3x]:
            nearby = any(
                in_bounds(p3x + dx, p3y + dy) and pm[p3y + dy, p3x + dx]
                for dy in range(-6, 7) for dx in range(-6, 7)
            )
            if not nearby:
                state["plant3_done"] = True
                return (Tool.COALPOWER, p3x, p3y)
        # Wire leftward
        for wc in range(wire_col - 1, max(wire_col - 22, 2), -1):
            if in_bounds(wc, plant_cy) and not pm[plant_cy, wc]:
                if wm[plant_cy, wc]:
                    break
                if em[plant_cy, wc]:
                    return (Tool.WIRE, wc, plant_cy)
                break

    # --- Phase 10: Services when population warrants ---
    if pop > 250:
        fx, fy = wire_col - 10, cy - 12
        if in_bounds(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
        px2, py2 = wire_col + 10, cy + 12
        if in_bounds(px2, py2) and em[py2, px2]:
            return (Tool.POLICESTATION, px2, py2)

    # --- Phase 11: Extend wire frontier reactively ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k = int(obs.step * 7) % len(wire_xs_arr)
        wx_s = int(wire_xs_arr[step_k])
        wy_s = int(wire_ys_arr[step_k])
        for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx2, ny2 = wx_s + dx2, wy_s + dy2
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                if y_min <= ny2 <= y_max:
                    return (Tool.WIRE, nx2, ny2)

    # --- Phase 12: Extend roads to reach more zone candidates ---
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = int(obs.step * 11) % len(road_xs_arr)
        rx_s = int(road_xs_arr[step_k])
        ry_s = int(road_ys_arr[step_k])
        for dy, dx in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx2, ny2 = rx_s + dx, ry_s + dy
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                if nbr_wire[ny2, nx2] and y_min <= ny2 <= y_max:
                    return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Variation: Build TWO horizontal neighborhoods (one upper, one lower)
    connected by vertical road spines. Uses a different layout than parent
    (horizontal expansion instead of vertical spine).
    Place coal plant left-center, wire runs horizontally, roads run horizontally.
    Zones placed in rows above and below road/wire lines.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Initialize state
    if 'phase' not in state:
        state['phase'] = 0
        state['step'] = 0
    state['step'] += 1

    pop = obs.city_pop

    # Two neighborhoods: upper cluster around row 35, lower around row 65
    # Power plant at left side
    plant_x = 20
    plant_y = 50  # center vertically

    # Wire horizontal spine at rows 35 and 65
    upper_wire_row = 35
    lower_wire_row = 65

    # Road rows adjacent to wire (zones sit between road and wire)
    upper_road_row = 37
    lower_road_row = 63

    # Zone rows: above upper wire and below lower wire, plus between
    upper_zone_row1 = 32   # above upper wire
    upper_zone_row2 = 40   # below upper road
    lower_zone_row1 = 60   # above lower road
    lower_zone_row2 = 68   # below lower wire

    # Column range for zones/roads/wires
    # Wire starts from plant and extends right
    wire_start_x = plant_x + 5
    wire_end_x = min(WORLD_W - 4, wire_start_x + 60)

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        if com_count / t < 0.30:
            return Tool.COMMERCIAL
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        all_zone = resm | comm | indm
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone[rr, rc]:
                    return False
        return True

    def zone_exists_near(zr, zc):
        all_zone = resm | comm | indm
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone[rr, rc]:
                        return True
        return False

    # Phase 1: Place coal power plant
    if not np.any(pm):
        return (Tool.COALPOWER, plant_x, plant_y)

    # Find plant
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Phase 2: Connect plant to upper wire row with vertical wire
    # Wire from plant up to upper_wire_row
    # First lay vertical wire at plant_cx+4 from plant to upper wire row
    vert_wire_col = plant_cx + 4
    if vert_wire_col >= WORLD_W:
        vert_wire_col = plant_cx - 1

    # Connect plant vertically to upper wire row
    for r in range(min(plant_cy, upper_wire_row), max(plant_cy, upper_wire_row) + 1):
        if 0 <= r < WORLD_H and 0 <= vert_wire_col < WORLD_W:
            if not wm[r, vert_wire_col] and not pm[r, vert_wire_col]:
                if em[r, vert_wire_col]:
                    return (Tool.WIRE, vert_wire_col, r)

    # Connect vertically from upper wire row to lower wire row
    for r in range(upper_wire_row, lower_wire_row + 1):
        if 0 <= r < WORLD_H and 0 <= vert_wire_col < WORLD_W:
            if not wm[r, vert_wire_col] and not pm[r, vert_wire_col]:
                if em[r, vert_wire_col]:
                    return (Tool.WIRE, vert_wire_col, r)

    # Determine horizontal extent based on population
    if pop < 50:
        h_extent = 20
    elif pop < 150:
        h_extent = 35
    elif pop < 400:
        h_extent = 55
    else:
        h_extent = 75

    actual_end = min(WORLD_W - 4, vert_wire_col + h_extent)

    # Phase 3: Lay upper horizontal wire row
    for c in range(vert_wire_col, actual_end + 1):
        if 0 <= c < WORLD_W:
            if not wm[upper_wire_row, c] and not pm[upper_wire_row, c]:
                if em[upper_wire_row, c]:
                    return (Tool.WIRE, c, upper_wire_row)

    # Phase 4: Lay lower horizontal wire row
    for c in range(vert_wire_col, actual_end + 1):
        if 0 <= c < WORLD_W:
            if not wm[lower_wire_row, c] and not pm[lower_wire_row, c]:
                if em[lower_wire_row, c]:
                    return (Tool.WIRE, c, lower_wire_row)

    # Phase 5: Lay upper horizontal road row
    for c in range(vert_wire_col, actual_end + 1):
        if 0 <= c < WORLD_W:
            if not rm[upper_road_row, c] and em[upper_road_row, c]:
                return (Tool.ROAD, c, upper_road_row)

    # Phase 6: Lay lower horizontal road row
    for c in range(vert_wire_col, actual_end + 1):
        if 0 <= c < WORLD_W:
            if not rm[lower_road_row, c] and em[lower_road_row, c]:
                return (Tool.ROAD, c, lower_road_row)

    # Phase 7: Place zones in upper cluster (rows 32 and 40)
    # Zones at columns spaced by 3 starting from vert_wire_col+3
    for zc in range(vert_wire_col + 3, actual_end, 3):
        if zc > WORLD_W - 3:
            break
        # Check wire and road coverage
        has_wire = any(wm[upper_wire_row, max(0, zc-3):min(WORLD_W, zc+4)])
        has_road_upper = any(rm[upper_road_row, max(0, zc-3):min(WORLD_W, zc+4)])

        if has_wire and has_road_upper:
            for zr in [upper_zone_row1, upper_zone_row2]:
                if not zone_exists_near(zr, zc) and zone_area_ok(zr, zc):
                    return (pick_tool(), zc, zr)

    # Phase 8: Place zones in lower cluster
    for zc in range(vert_wire_col + 3, actual_end, 3):
        if zc > WORLD_W - 3:
            break
        has_wire = any(wm[lower_wire_row, max(0, zc-3):min(WORLD_W, zc+4)])
        has_road_lower = any(rm[lower_road_row, max(0, zc-3):min(WORLD_W, zc+4)])

        if has_wire and has_road_lower:
            for zr in [lower_zone_row1, lower_zone_row2]:
                if not zone_exists_near(zr, zc) and zone_area_ok(zr, zc):
                    return (pick_tool(), zc, zr)

    # Phase 9: Add middle zone row between upper road and lower road (row 50)
    mid_zone_row = 50
    if pop > 100:
        # Need vertical road connecting upper and lower roads
        vert_road_cols = list(range(vert_wire_col + 6, actual_end, 12))
        for vrc in vert_road_cols:
            if vrc >= WORLD_W - 2:
                break
            for r in range(upper_road_row, lower_road_row + 1):
                if not rm[r, vrc] and em[r, vrc]:
                    return (Tool.ROAD, vrc, r)

        # Place zones along vertical roads at mid row
        for vrc in vert_road_cols:
            if vrc >= WORLD_W - 2:
                break
            zc = vrc
            if not zone_exists_near(mid_zone_row, zc) and zone_area_ok(mid_zone_row, zc):
                has_road_near = np.any(rm[max(0,mid_zone_row-3):min(WORLD_H,mid_zone_row+4),
                                         max(0,zc-3):min(WORLD_W,zc+4)])
                has_wire_near = np.any(wm[max(0,mid_zone_row-15):min(WORLD_H,mid_zone_row+16),
                                         max(0,zc-3):min(WORLD_W,zc+4)])
                if has_road_near and has_wire_near:
                    return (pick_tool(), zc, mid_zone_row)

    # Phase 10: Second power plant for large cities
    if pop > 300:
        plant_count = int(np.sum(pm)) // 9
        if plant_count < 2:
            px2 = plant_cx + 40
            py2 = plant_cy
            if 2 <= px2 <= WORLD_W - 3 and em[py2, px2]:
                return (Tool.COALPOWER, px2, py2)
            # Try alt position
            for dy in [-5, 5, -10, 10]:
                pyt = py2 + dy
                if 2 <= pyt <= WORLD_H - 3 and 2 <= px2 <= WORLD_W - 3:
                    if em[pyt, px2]:
                        return (Tool.COALPOWER, px2, pyt)

    # Phase 11: Connect second plant to wire grid
    if int(np.sum(pm)) > 9:
        p_rows, p_cols = np.where(pm)
        right_plant_cx = int(np.max(p_cols))
        right_plant_cy = int(p_rows[np.argmax(p_cols)])
        # Wire from right plant toward vert_wire_col at upper_wire_row
        for r in range(min(right_plant_cy, upper_wire_row), max(right_plant_cy, upper_wire_row) + 1):
            if 0 <= r < WORLD_H:
                if not wm[r, right_plant_cx - 1] and not pm[r, right_plant_cx - 1]:
                    if em[r, right_plant_cx - 1]:
                        return (Tool.WIRE, right_plant_cx - 1, r)

    # Phase 12: Wider expansion - extend further right
    if pop > 500:
        extra_end = min(WORLD_W - 4, actual_end + 20)
        for c in range(actual_end, extra_end + 1):
            if not wm[upper_wire_row, c] and em[upper_wire_row, c]:
                return (Tool.WIRE, c, upper_wire_row)
            if not wm[lower_wire_row, c] and em[lower_wire_row, c]:
                return (Tool.WIRE, c, lower_wire_row)
            if not rm[upper_road_row, c] and em[upper_road_row, c]:
                return (Tool.ROAD, c, upper_road_row)
            if not rm[lower_road_row, c] and em[lower_road_row, c]:
                return (Tool.ROAD, c, lower_road_row)

    # Phase 13: Fill any gaps in wire rows
    for c in range(vert_wire_col, actual_end + 1):
        for wr in [upper_wire_row, lower_wire_row]:
            if 0 <= c < WORLD_W and 0 <= wr < WORLD_H:
                if not wm[wr, c] and not pm[wr, c] and em[wr, c]:
                    adj = ((c > 0 and wm[wr, c-1]) or
                           (c < WORLD_W-1 and wm[wr, c+1]) or
                           (wr > 0 and wm[wr-1, c]) or
                           (wr < WORLD_H-1 and wm[wr+1, c]))
                    if adj:
                        return (Tool.WIRE, c, wr)

    # Phase 14: Fill any gaps in road rows
    for c in range(vert_wire_col, actual_end + 1):
        for rr in [upper_road_row, lower_road_row]:
            if 0 <= c < WORLD_W and 0 <= rr < WORLD_H:
                if not rm[rr, c] and em[rr, c] and not pm[rr, c]:
                    adj = ((c > 0 and rm[rr, c-1]) or
                           (c < WORLD_W-1 and rm[rr, c+1]))
                    if adj:
                        return (Tool.ROAD, c, rr)

    return None

def act(obs, state):
    """
    Improved policy:
    - Horizontal wire spine instead of vertical
    - Roads run horizontally above and below spine
    - Zones placed in rows between roads
    - Better zone mix: more commercial/industrial
    - Two coal plants from the start
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # Initialize state
    if 'phase' not in state:
        state['phase'] = 0
        state['built_road1'] = False
        state['built_road2'] = False

    # Layout constants - horizontal design
    # Plant at (20, 50), wire runs right from x=23 to x=100
    # Road row above wire: y=47, Road row below wire: y=53
    # Zones at y=44 (above top road) and y=56 (below bottom road)
    # Also zones between roads and wire at y=49 and y=51

    PLANT1_X, PLANT1_Y = 20, 50
    PLANT2_X, PLANT2_Y = 90, 50
    WIRE_Y = 50
    WIRE_X_START = 23
    WIRE_X_END = 87
    ROAD_Y_TOP = 47
    ROAD_Y_BOT = 53
    ROAD_X_START = 14
    ROAD_X_END = 96

    # Zone rows and their road adjacency
    ZONE_ROWS = [44, 56]  # outer zones (adj to roads at 47, 53)
    ZONE_ROWS_INNER = [49, 51]  # inner zones (adj to roads)

    # Phase 0: Place first coal plant
    if not np.any(pm):
        return (Tool.COALPOWER, PLANT1_X, PLANT1_Y)

    # Count plants
    plant_rows, plant_cols = np.where(pm)
    plant_count = 0
    # Rough count: plant is 3x3
    plant_count = len(plant_cols) // 4 + 1

    # Phase 1: Build horizontal wire spine
    wire_cols_at_y = [x for x in range(WORLD_W) if wm[WIRE_Y, x]]
    wire_set = set(wire_cols_at_y)

    # Connect wire from plant rightward
    if not wire_set:
        # Start wire adjacent to plant
        return (Tool.WIRE, PLANT1_X + 2, WIRE_Y)

    wire_min = min(wire_set)
    wire_max = max(wire_set)

    # Extend wire rightward to WIRE_X_END
    if wire_max < WIRE_X_END:
        nx = wire_max + 1
        if 0 <= nx < WORLD_W:
            return (Tool.WIRE, nx, WIRE_Y)

    # Extend wire leftward to WIRE_X_START
    if wire_min > WIRE_X_START:
        nx = wire_min - 1
        if 0 <= nx >= 0:
            return (Tool.WIRE, nx, WIRE_Y)

    # Place second coal plant
    p2_placed = any(
        pm[PLANT2_Y + dr, PLANT2_X + dc]
        for dr in [-1,0,1] for dc in [-1,0,1]
        if 0 <= PLANT2_Y+dr < WORLD_H and 0 <= PLANT2_X+dc < WORLD_W
    )
    if not p2_placed:
        # Check if wire reaches near plant2
        if wire_max >= PLANT2_X - 3:
            clear2 = all(
                0 <= PLANT2_Y+dr < WORLD_H and 0 <= PLANT2_X+dc < WORLD_W
                and (em[PLANT2_Y+dr, PLANT2_X+dc] or pm[PLANT2_Y+dr, PLANT2_X+dc])
                for dr in [-1,0,1] for dc in [-1,0,1]
            )
            if clear2 or True:  # force place
                return (Tool.COALPOWER, PLANT2_X, PLANT2_Y)

    # Build top road row (horizontal)
    for rx in range(ROAD_X_START, ROAD_X_END + 1):
        if 0 <= rx < WORLD_W and 0 <= ROAD_Y_TOP < WORLD_H:
            if not rm[ROAD_Y_TOP, rx] and em[ROAD_Y_TOP, rx]:
                return (Tool.ROAD, rx, ROAD_Y_TOP)

    # Build bottom road row (horizontal)
    for rx in range(ROAD_X_START, ROAD_X_END + 1):
        if 0 <= rx < WORLD_W and 0 <= ROAD_Y_BOT < WORLD_H:
            if not rm[ROAD_Y_BOT, rx] and em[ROAD_Y_BOT, rx]:
                return (Tool.ROAD, rx, ROAD_Y_BOT)

    # Zone placement helper
    all_zone_m = res_m | com_m | ind_m
    res_count = max(1, int(np.sum(res_m)) // 9)
    com_count = max(1, int(np.sum(com_m)) // 9)
    ind_count = max(1, int(np.sum(ind_m)) // 9)

    def pick_zone(prefer=None):
        if prefer is not None:
            return prefer
        total = res_count + com_count + ind_count
        # Target: 40% res, 35% com, 25% ind
        if res_count * 10 < total * 4:
            return Tool.RESIDENTIAL
        if com_count * 10 < total * 3:
            return Tool.COMMERCIAL
        if ind_count * 10 < total * 2:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_clear(zy, zx):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr2, rc2 = zy + dr, zx + dc
                if rr2 < 0 or rr2 >= WORLD_H or rc2 < 0 or rc2 >= WORLD_W:
                    return False
                if not em[rr2, rc2]:
                    return False
        return True

    def zone_nearby(zy, zx, dist=4):
        r0 = max(0, zy - dist)
        r1 = min(WORLD_H, zy + dist + 1)
        c0 = max(0, zx - dist)
        c1 = min(WORLD_W, zx + dist + 1)
        return np.any(all_zone_m[r0:r1, c0:c1])

    # Check which road columns are built
    top_road_cols = set(x for x in range(WORLD_W) if rm[ROAD_Y_TOP, x])
    bot_road_cols = set(x for x in range(WORLD_W) if rm[ROAD_Y_BOT, x])

    # Place zones along top road (zone center at ROAD_Y_TOP - 3)
    ZY_TOP_OUTER = ROAD_Y_TOP - 3  # y=44
    ZY_BOT_OUTER = ROAD_Y_BOT + 3  # y=56
    ZY_TOP_INNER = ROAD_Y_TOP + 3  # y=50 - skip (wire is here)
    # Actually inner zones between top road and wire: y=49 (adj to road at 47 via gap=2? no, 49-47=2)
    # Zone at y=49: tiles 48,49,50 - road at 47 is adjacent (dist 1), wire at 50 overlaps!
    # Let's use y=48 for inner top (tiles 47,48,49 - road at 47 is center of zone edge)
    # Actually zone center at 48 means tiles 47..49, road at 47 overlaps -> skip
    # Use zones only at outer rows: 44 and 56
    # Plus a third row further out: 41 and 59
    ZY_TOP_FAR = ROAD_Y_TOP - 6   # y=41
    ZY_BOT_FAR = ROAD_Y_BOT + 6   # y=59

    zone_placements = []  # (zy, prefer_tool)
    for zy, pref in [(ZY_TOP_OUTER, Tool.RESIDENTIAL),
                     (ZY_BOT_OUTER, Tool.COMMERCIAL),
                     (ZY_TOP_FAR, Tool.INDUSTRIAL),
                     (ZY_BOT_FAR, Tool.RESIDENTIAL)]:
        if 2 <= zy <= WORLD_H - 3:
            zone_placements.append((zy, pref))

    # Place zones at columns with road access, starting from center
    center_x = (ROAD_X_START + ROAD_X_END) // 2
    # Candidate x positions for zone centers (spaced by 3 to avoid overlap)
    zone_xs = []
    x = center_x
    while x >= ROAD_X_START + 1:
        zone_xs.append(x)
        x -= 3
    x = center_x + 3
    while x <= ROAD_X_END - 1:
        zone_xs.append(x)
        x += 3
    zone_xs = sorted(zone_xs, key=lambda v: abs(v - center_x))

    for zx in zone_xs:
        for zy, pref in zone_placements:
            # Check road adjacency: road should be within 1 tile of zone edge
            road_y_near = ROAD_Y_TOP if zy < WIRE_Y else ROAD_Y_BOT
            road_x_ok = (zx in top_road_cols) or (zx in bot_road_cols) or \
                        any(abs(zx - rx) <= 1 for rx in (top_road_cols | bot_road_cols))
            zone_x_ok = any(rx in range(zx-1, zx+2) for rx in (top_road_cols | bot_road_cols))

            if zone_x_ok and zone_clear(zy, zx) and not zone_nearby(zy, zx, dist=3):
                return (pick_zone(pref), zx, zy)

    # Add vertical connector roads between top and bottom roads (every 6 cols)
    for vx in range(ROAD_X_START, ROAD_X_END + 1, 6):
        for vy in range(ROAD_Y_TOP, ROAD_Y_BOT + 1):
            if 0 <= vx < WORLD_W and 0 <= vy < WORLD_H:
                if not rm[vy, vx] and em[vy, vx] and not wm[vy, vx]:
                    return (Tool.ROAD, vx, vy)

    # Add more zones in additional rows if population growing
    if obs.city_pop > 50:
        extra_rows = [(ZY_TOP_FAR - 3, Tool.COMMERCIAL),
                      (ZY_BOT_FAR + 3, Tool.INDUSTRIAL)]
        for zy, pref in extra_rows:
            if 2 <= zy <= WORLD_H - 3:
                for zx in zone_xs:
                    if zone_clear(zy, zx) and not zone_nearby(zy, zx, dist=3):
                        return (pick_zone(pref), zx, zy)

    # Third coal plant if needed
    if obs.city_pop > 500 and not state.get('plant3', False):
        P3X, P3Y = 55, 25
        clear3 = all(
            0 <= P3Y+dr < WORLD_H and 0 <= P3X+dc < WORLD_W
            for dr in [-1,0,1] for dc in [-1,0,1]
        )
        if clear3:
            state['plant3'] = True
            return (Tool.COALPOWER, P3X, P3Y)
        # Wire to plant3
        for wy in range(WIRE_Y, P3Y - 1, -1):
            if not wm[wy, P3X] and em[wy, P3X]:
                return (Tool.WIRE, P3X, wy)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy v2:
    - Reads current tile_map every step
    - Builds a compact grid: power plant -> wire spine -> road grid -> zones
    - Adapts zone type to current population balance
    - Uses state only for lightweight counters
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    has_plant = np.any(pm)
    has_road = np.any(rm)

    # Count zones (divide by 9 for 3x3 zone tiles)
    res_count = max(1, int(np.sum(res_m)) // 9)
    com_count = max(1, int(np.sum(com_m)) // 9)
    ind_count = max(1, int(np.sum(ind_m)) // 9)

    # ---- Phase 1: Place coal power plant ----
    if not has_plant:
        return (Tool.COALPOWER, 30, 50)

    # Find plant center
    plant_rows, plant_cols = np.where(pm)
    pcx = int(np.mean(plant_cols))
    pcy = int(np.mean(plant_rows))

    # Layout: wire spine at pcx+3, road at pcx+5, zones at pcx+8
    # Also road at pcx+1 (left side), zones at pcx-2
    wire_col = pcx + 3
    road_col_r = wire_col + 2
    road_col_l = wire_col - 2
    zone_col_r = road_col_r + 3
    zone_col_l = road_col_l - 3

    # Vertical span grows with city pop
    half_span = min(30, max(10, 10 + obs.city_pop // 15))
    tmin = max(3, pcy - half_span)
    tmax = min(WORLD_H - 4, pcy + half_span)

    # ---- Phase 2: Build vertical wire spine ----
    if 0 <= wire_col < WORLD_W:
        wire_col_data = wm[:, wire_col]
        wire_rows_arr = np.where(wire_col_data)[0]

        if len(wire_rows_arr) == 0:
            # Start wire adjacent to plant
            for dy in range(0, 5):
                ny = pcy + dy
                if 0 <= ny < WORLD_H and em[ny, wire_col]:
                    return (Tool.WIRE, wire_col, ny)
            for dy in range(-4, 0):
                ny = pcy + dy
                if 0 <= ny < WORLD_H and em[ny, wire_col]:
                    return (Tool.WIRE, wire_col, ny)
        else:
            min_wr = int(wire_rows_arr[0])
            max_wr = int(wire_rows_arr[-1])
            # Extend downward first
            if max_wr < tmax:
                nr = max_wr + 1
                if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                    return (Tool.WIRE, wire_col, nr)
            # Extend upward
            if min_wr > tmin:
                nr = min_wr - 1
                if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                    return (Tool.WIRE, wire_col, nr)

    # ---- Phase 3: Build road columns alongside wire ----
    wire_rows_list = sorted(int(r) for r in np.where(wm[:, wire_col])[0]) if 0 <= wire_col < WORLD_W else []

    if wire_rows_list:
        # Build right road column
        if 0 <= road_col_r < WORLD_W:
            for wr in wire_rows_list:
                if not rm[wr, road_col_r] and em[wr, road_col_r]:
                    return (Tool.ROAD, road_col_r, wr)
        # Build left road column
        if 0 <= road_col_l < WORLD_W:
            for wr in wire_rows_list:
                if not rm[wr, road_col_l] and em[wr, road_col_l]:
                    return (Tool.ROAD, road_col_l, wr)

    # ---- Zone placement helpers ----
    all_zone_m = res_m | com_m | ind_m

    def zone_area_free(zr, zc):
        """Check 3x3 area is entirely empty"""
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def no_nearby_zone(zr, zc, radius=3):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return not np.any(all_zone_m[r0:r1, c0:c1])

    def pick_zone():
        # Target: ~60% res, 20% com, 20% ind
        total = res_count + com_count + ind_count
        if res_count / total < 0.55:
            return Tool.RESIDENTIAL
        if ind_count / total < 0.20:
            return Tool.INDUSTRIAL
        if com_count / total < 0.20:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- Phase 4: Place zones adjacent to roads ----
    if wire_rows_list:
        road_rows_r = set(int(r) for r in range(WORLD_H) if 0 <= road_col_r < WORLD_W and rm[r, road_col_r])
        road_rows_l = set(int(r) for r in range(WORLD_H) if 0 <= road_col_l < WORLD_W and rm[r, road_col_l])
        wire_rows_set = set(wire_rows_list)

        # Place zones every 3 rows to avoid overlap
        for zr in wire_rows_list:
            # Only place at intervals that don't overlap (every 3 rows from center)
            if (zr - pcy) % 3 != 0:
                continue

            wire_near = (zr in wire_rows_set) or ((zr-1) in wire_rows_set) or ((zr+1) in wire_rows_set)
            if not wire_near:
                continue

            # Right zone column
            road_near_r = any(abs(zr - rr) <= 1 for rr in road_rows_r)
            if road_near_r and 0 < zone_col_r < WORLD_W - 1:
                if no_nearby_zone(zr, zone_col_r) and zone_area_free(zr, zone_col_r):
                    return (pick_zone(), zone_col_r, zr)

            # Left zone column
            road_near_l = any(abs(zr - rr) <= 1 for rr in road_rows_l)
            if road_near_l and 1 < zone_col_l < WORLD_W - 1:
                if no_nearby_zone(zr, zone_col_l) and zone_area_free(zr, zone_col_l):
                    return (pick_zone(), zone_col_l, zr)

    # ---- Phase 5: Second cluster when population grows ----
    if obs.city_pop > 100 and wire_rows_list:
        wire_col2 = zone_col_r + 6
        road_col_r2 = wire_col2 + 2
        road_col_l2 = wire_col2 - 2
        zone_col_r2 = road_col_r2 + 3
        zone_col_l2 = road_col_l2 - 3

        if 0 <= wire_col2 < WORLD_W:
            wire_rows2 = sorted(int(r) for r in np.where(wm[:, wire_col2])[0])

            if not wire_rows2:
                # Lay horizontal wire bridge at pcy level from wire_col to wire_col2
                for wc in range(wire_col + 1, min(wire_col2 + 1, WORLD_W)):
                    if em[pcy, wc]:
                        return (Tool.WIRE, wc, pcy)
            else:
                min_wr2 = wire_rows2[0]
                max_wr2 = wire_rows2[-1]
                if max_wr2 < tmax:
                    nr = max_wr2 + 1
                    if 0 <= nr < WORLD_H and (em[nr, wire_col2] or wm[nr, wire_col2]):
                        return (Tool.WIRE, wire_col2, nr)
                if min_wr2 > tmin:
                    nr = min_wr2 - 1
                    if 0 <= nr < WORLD_H and (em[nr, wire_col2] or wm[nr, wire_col2]):
                        return (Tool.WIRE, wire_col2, nr)

                # Roads for cluster 2
                if 0 <= road_col_r2 < WORLD_W:
                    for wr in wire_rows2:
                        if not rm[wr, road_col_r2] and em[wr, road_col_r2]:
                            return (Tool.ROAD, road_col_r2, wr)
                if 0 <= road_col_l2 < WORLD_W:
                    for wr in wire_rows2:
                        if not rm[wr, road_col_l2] and em[wr, road_col_l2]:
                            return (Tool.ROAD, road_col_l2, wr)

                # Zones for cluster 2
                road_rows_r2 = set(int(r) for r in range(WORLD_H) if 0 <= road_col_r2 < WORLD_W and rm[r, road_col_r2])
                road_rows_l2 = set(int(r) for r in range(WORLD_H) if 0 <= road_col_l2 < WORLD_W and rm[r, road_col_l2])
                wire_rows2_set = set(wire_rows2)

                for zr in wire_rows2:
                    if (zr - pcy) % 3 != 0:
                        continue
                    wire_near2 = (zr in wire_rows2_set) or ((zr-1) in wire_rows2_set) or ((zr+1) in wire_rows2_set)
                    if not wire_near2:
                        continue
                    road_near_r2 = any(abs(zr - rr) <= 1 for rr in road_rows_r2)
                    if road_near_r2 and 0 < zone_col_r2 < WORLD_W - 1:
                        if no_nearby_zone(zr, zone_col_r2) and zone_area_free(zr, zone_col_r2):
                            return (pick_zone(), zone_col_r2, zr)
                    road_near_l2 = any(abs(zr - rr) <= 1 for rr in road_rows_l2)
                    if road_near_l2 and 1 < zone_col_l2 < WORLD_W - 1:
                        if no_nearby_zone(zr, zone_col_l2) and zone_area_free(zr, zone_col_l2):
                            return (pick_zone(), zone_col_l2, zr)

    # ---- Phase 6: Second power plant if large city ----
    if obs.city_pop > 300 and not state.get("plant2_placed", False):
        # Try placing another coal plant further right
        px2 = pcx + 30
        py2 = pcy
        if 0 <= px2 + 1 < WORLD_W and 0 <= py2 + 1 < WORLD_H:
            clear = all(
                0 <= py2 + dr < WORLD_H and 0 <= px2 + dc < WORLD_W and em[py2+dr, px2+dc]
                for dr in [-1, 0, 1] for dc in [-1, 0, 1]
            )
            if clear:
                state["plant2_placed"] = True
                return (Tool.COALPOWER, px2, py2)
            else:
                # Connect wire toward it
                for wc in range(wire_col, min(px2 + 1, WORLD_W)):
                    if em[pcy, wc] and not wm[pcy, wc]:
                        return (Tool.WIRE, wc, pcy)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy v2:
    - Reads current map state every step
    - Places power plant, wires, roads, zones based on what's observed
    - More aggressive expansion and better zone placement
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Fixed anchor - slightly different position for variety
    CX, CY = 30, 48

    # --- Phase 1: Place first coal power plant ---
    if not np.any(pm):
        return (Tool.COALPOWER, CX, CY)

    plant_ys, plant_xs = np.where(pm)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        # More balanced mix with slight residential preference
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Determine expansion scale based on current population
    if obs.city_pop < 100:
        target_wire_end = min(px + 35, WORLD_W - 4)
    elif obs.city_pop < 300:
        target_wire_end = min(px + 55, WORLD_W - 4)
    elif obs.city_pop < 700:
        target_wire_end = min(px + 80, WORLD_W - 4)
    else:
        target_wire_end = min(px + 100, WORLD_W - 4)

    wire_start_x = px + 3
    spine_y = py

    # --- Phase 2: Grow horizontal wire spine ---
    spine_wire_cols = [c for c in range(WORLD_W) if wm[spine_y, c]]

    if not spine_wire_cols:
        wx = wire_start_x
        if in_bounds(wx, spine_y) and em[spine_y, wx]:
            return (Tool.WIRE, wx, spine_y)
        for dy in [-1, 1]:
            wy = spine_y + dy
            if in_bounds(wx, wy) and em[wy, wx]:
                return (Tool.WIRE, wx, wy)
    else:
        max_wire_x = max(spine_wire_cols)
        if max_wire_x < target_wire_end:
            nx = max_wire_x + 1
            if in_bounds(nx, spine_y) and em[spine_y, nx] and not pm[spine_y, nx]:
                return (Tool.WIRE, nx, spine_y)

    # --- Phase 3: Vertical wire branches every 5 cols (denser than parent) ---
    branch_cols = list(range(wire_start_x + 2, target_wire_end + 1, 5))
    for bx in branch_cols:
        if not in_bounds(bx, spine_y):
            continue
        if not (bool(wm[spine_y, bx]) or bool(pm[spine_y, bx])):
            continue
        for sign in [-1, 1]:
            for dy in range(1, 5):  # Branch 4 tiles instead of 3
                wy = spine_y + sign * dy
                if not in_bounds(bx, wy):
                    break
                if bool(wm[wy, bx]) or bool(pm[wy, bx]):
                    continue
                if bool(em[wy, bx]):
                    return (Tool.WIRE, bx, wy)
                break

    # --- Phase 4: Build road rows parallel to wire spine ---
    # Use 3 road rows: top, middle-top, middle-bottom for denser zone coverage
    road_offsets = [-3, -1, 1, 3]  # Multiple road rows for more zone access
    road_rows = [spine_y + off for off in road_offsets
                 if 0 <= spine_y + off < WORLD_H]

    road_end = target_wire_end
    road_start = wire_start_x

    for road_y in road_rows:
        row_cols = [c for c in range(WORLD_W) if rm[road_y, c]]
        if not row_cols:
            rx = road_start
            if in_bounds(rx, road_y) and em[road_y, rx] and not pm[road_y, rx]:
                return (Tool.ROAD, rx, road_y)
        else:
            max_r = max(row_cols)
            if max_r < road_end:
                nx = max_r + 1
                if in_bounds(nx, road_y) and em[road_y, nx] and not pm[road_y, nx] and not wm[road_y, nx]:
                    return (Tool.ROAD, nx, road_y)

    # --- Phase 5: Vertical connector roads every 5 cols ---
    for vc in range(road_start, road_end + 1, 5):
        min_ry = min(road_rows) if road_rows else spine_y - 3
        max_ry = max(road_rows) if road_rows else spine_y + 3
        for vr in range(min_ry, max_ry + 1):
            if not in_bounds(vc, vr):
                continue
            if bool(rm[vr, vc]) or bool(pm[vr, vc]):
                continue
            # Don't overwrite wire on spine
            if bool(wm[vr, vc]) and vr == spine_y:
                continue
            if not bool(em[vr, vc]):
                continue
            connected = False
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr2, nc2 = vr + dr, vc + dc
                if in_bounds(nc2, nr2) and bool(rm[nr2, nc2]):
                    connected = True
                    break
            if connected:
                return (Tool.ROAD, vc, vr)

    # --- Phase 6: Place zones reactively ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_set = set()
    for arr in [resm, comm, indm]:
        ys2, xs2 = np.where(arr)
        for y2, x2 in zip(ys2.tolist(), xs2.tolist()):
            zone_set.add((int(y2), int(x2)))

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Use deterministic but reactive hash
        step_hash = int(obs.step * 13 + int(obs.city_pop * 7)) % max(len(cxs_arr), 1)
        for offset in range(min(len(cxs_arr), 100)):
            k = (step_hash + offset * 7) % len(cxs_arr)
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # --- Phase 7: Second coal plant when city grows ---
    if total_zones > 8 or obs.city_pop > 150:
        p2x = min(px + 50, WORLD_W - 5)
        p2y = py
        nearby_plant = any(
            bool(pm[p2y + dy, p2x + dx])
            for dy in range(-8, 9) for dx in range(-8, 9)
            if in_bounds(p2x + dx, p2y + dy)
        )
        if not nearby_plant and in_bounds(p2x, p2y) and bool(em[p2y, p2x]):
            return (Tool.COALPOWER, p2x, p2y)

    # Third plant for large cities
    if obs.city_pop > 500:
        p3x = min(px + 90, WORLD_W - 5)
        p3y = py
        nearby_plant3 = any(
            bool(pm[p3y + dy, p3x + dx])
            for dy in range(-8, 9) for dx in range(-8, 9)
            if in_bounds(p3x + dx, p3y + dy)
        )
        if not nearby_plant3 and in_bounds(p3x, p3y) and bool(em[p3y, p3x]):
            return (Tool.COALPOWER, p3x, p3y)

    # --- Phase 8: Services ---
    if obs.city_pop > 150:
        fx, fy = px + 8, py - 7
        if in_bounds(fx, fy) and bool(em[fy, fx]):
            return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 200:
        fx2, fy2 = px + 8, py + 7
        if in_bounds(fx2, fy2) and bool(em[fy2, fx2]):
            return (Tool.POLICESTATION, fx2, fy2)

    # --- Phase 9: Extend wire from frontier ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        candidates = list(zip(wire_xs_arr.tolist(), wire_ys_arr.tolist()))
        candidates.sort(key=lambda t: -t[0])
        for wx_s, wy_s in candidates[:15]:
            for dx2, dy2 in [(1, 0), (0, -1), (0, 1), (-1, 0)]:
                nx2, ny2 = wx_s + dx2, wy_s + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # --- Phase 10: Extend roads from frontier ---
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        candidates_r = list(zip(road_xs_arr.tolist(), road_ys_arr.tolist()))
        candidates_r.sort(key=lambda t: -t[0])
        for rx_s, ry_s in candidates_r[:15]:
            for dx2, dy2 in [(1, 0), (0, -1), (0, 1), (-1, 0)]:
                nx2, ny2 = rx_s + dx2, ry_s + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and not bool(wm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map every step to decide next action
    - Places coal plant(s), wires, roads, then zones
    - Adapts placement based on what already exists on map
    - Two-neighborhood strategy with vertical wire spine and horizontal roads
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    all_zones = resm | comm | indm

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def area_free(cx, cy):
        if cx < 1 or cx > WORLD_W - 2 or cy < 1 or cy > WORLD_H - 2:
            return False
        for dy in [-1, 0, 1]:
            for dx in [-1, 0, 1]:
                r, c = cy + dy, cx + dx
                if not (0 <= r < WORLD_H and 0 <= c < WORLD_W):
                    return False
                if not em[r, c]:
                    return False
        return True

    def zone_exists_near(cx, cy, radius=2):
        r0 = max(0, cy - radius)
        r1 = min(WORLD_H, cy + radius + 1)
        c0 = max(0, cx - radius)
        c1 = min(WORLD_W, cx + radius + 1)
        return np.any(all_zones[r0:r1, c0:c1])

    def has_wire_near(cx, cy, radius=5):
        r0 = max(0, cy - radius)
        r1 = min(WORLD_H, cy + radius + 1)
        c0 = max(0, cx - radius)
        c1 = min(WORLD_W, cx + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_near(cx, cy, radius=4):
        r0 = max(0, cy - radius)
        r1 = min(WORLD_H, cy + radius + 1)
        c0 = max(0, cx - radius)
        c1 = min(WORLD_W, cx + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    def pick_zone():
        t = total_zones + 1
        if res_count / t < 0.40:
            return Tool.RESIDENTIAL
        elif com_count / t < 0.30:
            return Tool.COMMERCIAL
        elif ind_count / t < 0.30:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Two neighborhoods: left around x=38, right around x=82
    # Each has a coal plant, vertical wire spine, horizontal roads, zones
    neighborhoods = [
        {'px': 38, 'py': 50, 'wire_col': 38, 'road_left': 33, 'road_right': 43},
        {'px': 82, 'py': 50, 'wire_col': 82, 'road_left': 77, 'road_right': 87},
    ]

    # Determine how far vertically to extend based on pop
    if pop < 100:
        v_extent = 8
    elif pop < 300:
        v_extent = 14
    elif pop < 600:
        v_extent = 20
    else:
        v_extent = 26

    cy = WORLD_H // 2

    for nb in neighborhoods:
        px, py = nb['px'], nb['py']
        wc = nb['wire_col']
        rl = nb['road_left']
        rr_col = nb['road_right']

        # Step 1: ensure plant exists near this neighborhood
        local_pm = pm[max(0, py-4):min(WORLD_H, py+5), max(0, px-4):min(WORLD_W, px+5)]
        has_plant = np.any(local_pm)

        if not has_plant:
            # Try to place plant
            for dy in range(-3, 4):
                for dx in range(-3, 4):
                    npx, npy = px + dx, py + dy
                    if area_free(npx, npy):
                        return (Tool.COALPOWER, npx, npy)
            continue

        # Find actual plant center for this neighborhood
        plant_rows, plant_cols = np.where(pm)
        # Filter to those near this neighborhood
        near = [(plant_rows[i], plant_cols[i]) for i in range(len(plant_rows))
                if abs(plant_cols[i] - px) <= 10 and abs(plant_rows[i] - py) <= 10]
        if near:
            plant_cy = int(np.mean([r for r, c in near]))
            plant_cx = int(np.mean([c for r, c in near]))
        else:
            plant_cy, plant_cx = py, px

        # Step 2: extend wire spine vertically from plant
        spine_top = max(2, cy - v_extent)
        spine_bot = min(WORLD_H - 3, cy + v_extent)

        wire_on_col = [r for r in range(WORLD_H) if wm[r, wc]]

        if not wire_on_col:
            # Start wire adjacent to plant
            for dy in range(0, 6):
                for nr in [plant_cy + dy, plant_cy - dy]:
                    if spine_top <= nr <= spine_bot and 0 <= nr < WORLD_H:
                        if em[nr, wc] or wm[nr, wc]:
                            return (Tool.WIRE, wc, nr)
        else:
            min_wr = min(wire_on_col)
            max_wr = max(wire_on_col)

            # Extend downward
            if max_wr < spine_bot:
                nr = max_wr + 1
                if 0 <= nr < WORLD_H and not pm[nr, wc] and (em[nr, wc] or wm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

            # Extend upward
            if min_wr > spine_top:
                nr = min_wr - 1
                if 0 <= nr < WORLD_H and not pm[nr, wc] and (em[nr, wc] or wm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

            # Step 3: build horizontal roads at fixed rows around cy
            road_rows = [cy - 4, cy + 4]
            road_span_start = min(rl - 2, wc - 8)
            road_span_end = max(rr_col + 2, wc + 8)

            for rrow in road_rows:
                if 0 < rrow < WORLD_H:
                    for rc in range(road_span_start, road_span_end + 1):
                        if 0 <= rc < WORLD_W and em[rrow, rc] and not pm[rrow, rc]:
                            return (Tool.ROAD, rc, rrow)

            # Step 4: vertical road connectors linking the two road rows
            for rc in [rl, rr_col]:
                if 0 <= rc < WORLD_W:
                    for ry in range(min(road_rows), max(road_rows) + 1):
                        if 0 <= ry < WORLD_H and em[ry, rc] and not pm[ry, rc]:
                            return (Tool.ROAD, rc, ry)

            # Step 5: extend lateral wires from spine to zone columns
            for wr in wire_on_col:
                # Wire leftward
                for wcc in range(wc - 1, rl - 3, -1):
                    if 0 <= wcc < WORLD_W:
                        if wm[wr, wcc]:
                            break
                        if pm[wr, wcc]:
                            break
                        if em[wr, wcc]:
                            return (Tool.WIRE, wcc, wr)
                        else:
                            break
                # Wire rightward
                for wcc in range(wc + 1, rr_col + 3):
                    if 0 <= wcc < WORLD_W:
                        if wm[wr, wcc]:
                            break
                        if pm[wr, wcc]:
                            break
                        if em[wr, wcc]:
                            return (Tool.WIRE, wcc, wr)
                        else:
                            break

            # Step 6: place zones between road rows, served by wires
            zone_cols = [rl - 3, rl + 3, wc, rr_col - 3, rr_col + 3]
            zone_ys = [cy - 4 - 3, cy + 4 + 3]  # just outside road rows

            # Also try zones straddling the roads (between them)
            inner_zone_ys = []
            if abs(road_rows[1] - road_rows[0]) >= 6:
                inner_zone_ys = [(road_rows[0] + road_rows[1]) // 2]

            all_zone_ys = zone_ys + inner_zone_ys

            for zy in all_zone_ys:
                if 1 <= zy <= WORLD_H - 2:
                    for zx in [rl - 3, rl + 3, wc - 6, wc + 6, rr_col - 3, rr_col + 3]:
                        if 1 <= zx <= WORLD_W - 2:
                            if not zone_exists_near(zx, zy, 2) and area_free(zx, zy):
                                if has_wire_near(zx, zy, 5) and has_road_near(zx, zy, 5):
                                    return (pick_zone(), zx, zy)

            # Step 7: also scan dynamically for any empty area near wires+roads
            wire_rows_set = set(wire_on_col)
            for zy in range(spine_top + 3, spine_bot - 2, 3):
                wire_near = any(abs(zy - wr) <= 3 for wr in wire_rows_set)
                road_near = has_road_near(wc, zy, 6)
                if wire_near and road_near:
                    for zx in [wc - 6, wc - 3, wc + 3, wc + 6]:
                        if 1 <= zx <= WORLD_W - 2:
                            if not zone_exists_near(zx, zy, 2) and area_free(zx, zy):
                                return (pick_zone(), zx, zy)

    # Second coal plant if needed for more power
    if pop > 350:
        plant_count = int(np.sum(pm)) // 9
        if plant_count < 2:
            for nb in neighborhoods:
                px, py = nb['px'] + 20, nb['py']
                if area_free(px, py):
                    return (Tool.COALPOWER, px, py)

    # Police/fire for happiness
    if pop > 300:
        for px, py in [(38, 43), (82, 43)]:
            if area_free(px, py):
                # Check no service building nearby
                near_tile = tm[max(0, py-5):min(WORLD_H, py+6), max(0, px-5):min(WORLD_W, px+6)]
                if not np.any((near_tile >= 600) & (near_tile <= 750)):
                    return (Tool.POLICESTATION, px, py)

    if pop > 500:
        for px, py in [(38, 57), (82, 57)]:
            if area_free(px, py):
                return (Tool.FIRESTATION, px, py)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy v2:
    - Reads tile_map every step to decide placement
    - Uses a grid-based approach: plant in center, wire grid, roads between zones
    - Places zones in a systematic expanding ring around power spine
    - Reactively adds more plants and services as city grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Place first coal plant if missing ---
    if not np.any(pm):
        return (Tool.COALPOWER, 60, 50)

    # Find plant center(s)
    plant_ys, plant_xs = np.where(pm)
    px = int(np.median(plant_xs))
    py = int(np.median(plant_ys))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Build proximity masks once
    def expand_mask(base, radius=2):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-radius, radius+1):
            for dx in range(-radius, radius+1):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                result[r0:r1, c0:c1] |= base[sr0:sr1, sc0:sc1]
        return result

    nbr_road = expand_mask(rm, 2)
    power_src = wm | pm
    nbr_wire = expand_mask(power_src, 2)

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and not zone_tiles[nr, nc]:
                    return False
        return True

    # === STRATEGY: Build a cross-shaped wire grid ===
    # Horizontal wire at py, vertical wire at px+2
    # Roads run parallel to wires at offset +/-1
    # Zones fill in the blocks

    wire_col = px + 2   # vertical spine column
    wire_row = py       # horizontal spine row

    # Determine extent based on population
    pop_factor = min(35, obs.city_pop // 20)
    y_extent = 12 + pop_factor
    x_extent = 12 + pop_factor

    tmin = max(2, py - y_extent)
    tmax = min(WORLD_H - 3, py + y_extent)
    lmin = max(2, px - x_extent)
    lmax = min(WORLD_W - 3, px + x_extent)

    # --- Step 1: Build vertical wire spine ---
    wire_in_col = [r for r in range(WORLD_H) if wm[r, wire_col]]
    if not wire_in_col:
        # Seed wire next to plant
        for dy in range(-2, 3):
            ny = py + dy
            if in_bounds(wire_col, ny) and (em[ny, wire_col] or wm[ny, wire_col]) and not pm[ny, wire_col]:
                return (Tool.WIRE, wire_col, ny)
    else:
        min_wr = min(wire_in_col)
        max_wr = max(wire_in_col)
        if max_wr < tmax:
            nr = max_wr + 1
            if in_bounds(wire_col, nr) and (em[nr, wire_col] or wm[nr, wire_col]) and not pm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)
        if min_wr > tmin:
            nr = min_wr - 1
            if in_bounds(wire_col, nr) and (em[nr, wire_col] or wm[nr, wire_col]) and not pm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    wire_in_col = [r for r in range(WORLD_H) if wm[r, wire_col]]

    # --- Step 2: Build horizontal wire spine ---
    wire_in_row = [c for c in range(WORLD_W) if wm[wire_row, c]]
    if not wire_in_row and wire_in_col:
        # Seed horizontal from vertical
        if in_bounds(wire_col, wire_row) and (em[wire_row, wire_col] or wm[wire_row, wire_col]):
            for dc in [1, -1]:
                nc = wire_col + dc
                if in_bounds(nc, wire_row) and (em[wire_row, nc] or wm[wire_row, nc]) and not pm[wire_row, nc]:
                    return (Tool.WIRE, nc, wire_row)
    elif wire_in_row:
        min_wc = min(wire_in_row)
        max_wc = max(wire_in_row)
        if max_wc < lmax:
            nc = max_wc + 1
            if in_bounds(nc, wire_row) and (em[wire_row, nc] or wm[wire_row, nc]) and not pm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)
        if min_wc > lmin:
            nc = min_wc - 1
            if in_bounds(nc, wire_row) and (em[wire_row, nc] or wm[wire_row, nc]) and not pm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    wire_in_row = [c for c in range(WORLD_W) if wm[wire_row, c]]

    # --- Step 3: Build roads adjacent to wire spine (both sides) ---
    road_col_r = wire_col + 1
    road_col_l = wire_col - 1

    for wr in wire_in_col:
        if in_bounds(road_col_r, wr) and em[wr, road_col_r] and not pm[wr, road_col_r]:
            return (Tool.ROAD, road_col_r, wr)
        if in_bounds(road_col_l, wr) and em[wr, road_col_l] and not pm[wr, road_col_l]:
            return (Tool.ROAD, road_col_l, wr)

    # Roads above and below horizontal wire
    road_row_u = wire_row - 1
    road_row_d = wire_row + 1
    for wc in wire_in_row:
        if in_bounds(wc, road_row_u) and em[road_row_u, wc] and not pm[road_row_u, wc] and not wm[road_row_u, wc]:
            return (Tool.ROAD, wc, road_row_u)
        if in_bounds(wc, road_row_d) and em[road_row_d, wc] and not pm[road_row_d, wc] and not wm[road_row_d, wc]:
            return (Tool.ROAD, wc, road_row_d)

    # --- Step 4: Place zones where road+wire coverage exists ---
    cand_mask = em & nbr_road & nbr_wire
    # Keep away from edges
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prefer zones close to both spines (cross intersection)
        dist_v = np.abs(cxs - wire_col)
        dist_h = np.abs(cys - wire_row)
        # Score: want spread but not too far; prioritize near spines
        scores = dist_v + dist_h
        # Rotate through candidates to get spread
        order = np.argsort(scores)
        step_off = int(obs.step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 60:
                break

    # --- Step 5: Extend roads from existing roads near wire ---
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 20)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx]:
                    if nbr_wire[ny, nx]:
                        return (Tool.ROAD, nx, ny)

    # --- Step 6: Second power plant when city grows ---
    if total_zones > 10 or obs.city_pop > 250:
        # Place second plant above horizontal spine
        p2x = px + 20
        p2y = py - 20
        p2x = max(2, min(WORLD_W - 4, p2x))
        p2y = max(2, min(WORLD_H - 4, p2y))
        nearby = any(
            in_bounds(p2x + dx, p2y + dy) and pm[p2y + dy, p2x + dx]
            for dy in range(-6, 7) for dx in range(-6, 7)
        )
        if not nearby and em[p2y, p2x]:
            return (Tool.COALPOWER, p2x, p2y)
        # Wire horizontal to connect second plant
        for wc in range(min(wire_col + 2, p2x - 1), max(wire_col + 2, p2x)):
            if in_bounds(wc, wire_row) and (em[wire_row, wc] or wm[wire_row, wc]) and not pm[wire_row, wc]:
                return (Tool.WIRE, wc, wire_row)

    # --- Step 7: Services when pop high enough ---
    if obs.city_pop > 150:
        fsx, fsy = px - 8, py - 8
        fsx = max(1, min(WORLD_W - 2, fsx))
        fsy = max(1, min(WORLD_H - 2, fsy))
        if em[fsy, fsx]:
            return (Tool.FIRESTATION, fsx, fsy)
        psx, psy = px - 8, py + 8
        psx = max(1, min(WORLD_W - 2, psx))
        psy = max(1, min(WORLD_H - 2, psy))
        if em[psy, psx]:
            return (Tool.POLICESTATION, psx, psy)

    # --- Step 8: Extend wire frontier outward from existing wire ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 15)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = wx + dx2, wy + dy2
                if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                    return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Variation: dual-corridor layout with horizontal wire spine,
