    wire_row = cy          # horizontal wire spine row
    road_row_above = cy - 4
    road_row_below = cy + 4
    plant_x = cx - 20
    plant_y = cy

    # Scale horizontal extent with population
    if pop < 50:
        x_half = 10
    elif pop < 200:
        x_half = 18
    elif pop < 500:
        x_half = 28
    elif pop < 900:
        x_half = 40
    else:
        x_half = 50

    x_min = max(3, cx - x_half)
