        # Try connecting from plant
        for dc in range(1, 8):
            c = plant_cx + dc
            if in_bounds(c, wire_row) and em[wire_row, c]:
                return (Tool.WIRE, c, wire_row)
        return None

    min_wc = min(wire_cols_on_row)
    max_wc = max(wire_cols_on_row)

    # --- Phase 3: Extend wire spine horizontally ---
    if max_wc < x_max:
        nc = max_wc + 1
        if in_bounds(nc, wire_row) and em[wire_row, nc] and not pm[wire_row, nc]:
            return (Tool.WIRE, nc, wire_row)
    if min_wc > x_min:
        nc = min_wc - 1
        if in_bounds(nc, wire_row) and em[wire_row, nc] and not pm[wire_row, nc]:
            return (Tool.WIRE, nc, wire_row)

    # --- Phase 4: Connect plant to wire spine ---
    connected = any(
        wm[plant_cy + dr, plant_cx + dc]
        for dr in range(-2, 3) for dc in range(-2, 3)
        if 0 <= plant_cy + dr < WORLD_H and 0 <= plant_cx + dc < WORLD_W
    )
    if not connected and wire_cols_on_row:
        # Horizontal bridge from plant to nearest wire
        bridge_y = wire_row
        for bc in range(plant_cx + 1, min_wc + 1):
            if in_bounds(bc, bridge_y):
                if wm[bridge_y, bc]:
                    break
                if em[bridge_y, bc] and not pm[bridge_y, bc]:
                    return (Tool.WIRE, bc, bridge_y)
        # Also try vertical bridge
        for br in range(min(plant_cy, wire_row), max(plant_cy, wire_row) + 1):
            c = plant_cx + 2
            if in_bounds(c, br) and em[br, c] and not pm[br, c] and not wm[br, c]:
                return (Tool.WIRE, c, br)

    # --- Phase 5: Build road rows parallel to wire spine ---
    for wc in wire_cols_on_row:
        if x_min <= wc <= x_max:
            # Road above
            if in_bounds(wc, road_row_above) and em[road_row_above, wc] and not pm[road_row_above, wc]:
                return (Tool.ROAD, wc, road_row_above)
            # Road below
            if in_bounds(wc, road_row_below) and em[road_row_below, wc] and not pm[road_row_below, wc]:
                return (Tool.ROAD, wc, road_row_below)

    # --- Phase 6: Vertical connector roads every 8 cols ---
    for wc in wire_cols_on_row:
        if x_min <= wc <= x_max and (wc - x_min) % 8 == 0:
            for wr in range(road_row_above, road_row_below + 1):
                if in_bounds(wc, wr) and em[wr, wc] and not pm[wr, wc] and not wm[wr, wc]:
                    return (Tool.ROAD, wc, wr)

    # --- Phase 7: Place zones near roads and wires ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, :2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys_a, cxs_a = np.where(cand_mask)
    if len(cxs_a) > 0:
        # Sort by distance to wire spine center
        dists = np.abs(cxs_a.astype(int) - cx) + np.abs(cys_a.astype(int) - wire_row)
        sort_idx = np.argsort(dists)
        for i in range(min(len(cxs_a), 80)):
            k = int(sort_idx[i])
            zx, zy = int(cxs_a[k]), int(cys_a[k])
            if zone_area_ok(zy, zx):
                return (pick_tool(), zx, zy)

    # --- Phase 8: Second power plant ---
    plant_tiles = int(np.sum(pm))
    plant_count = max(1, plant_tiles // 6)
    if pop > 200 and plant_count < 2:
        p2x = plant_cx + 40
        p2y = plant_cy
        if in_bounds(p2x, p2y) and em[p2y, p2x]:
            nearby = any(
                in_bounds(p2x + dx, p2y + dy) and pm[p2y + dy, p2x + dx]
                for dy in range(-6, 7) for dx in range(-6, 7)
            )
            if not nearby:
                return (Tool.COALPOWER, p2x, p2y)
        # Extend wire to second plant
        for wc2 in range(max_wc + 1, min(max_wc + 45, WORLD_W - 2)):
            if in_bounds(wc2, wire_row) and em[wire_row, wc2] and not pm[wire_row, wc2]:
                if not wm[wire_row, wc2]:
                    return (Tool.WIRE, wc2, wire_row)
                break

    # --- Phase 9: Third plant for larger city ---
    if pop > 600 and plant_count < 3:
        p3x = plant_cx - 1
        p3y = plant_cy + 15
        if in_bounds(p3x, p3y) and em[p3y, p3x]:
            nearby = any(
                in_bounds(p3x + dx, p3y + dy) and pm[p3y + dy, p3x + dx]
                for dy in range(-6, 7) for dx in range(-6, 7)
            )
            if not nearby:
                return (Tool.COALPOWER, p3x, p3y)
        # Wire downward to connect
        for wr2 in range(wire_row + 1, min(wire_row + 18, WORLD_H - 2)):
            wc3 = plant_cx + 2
            if in_bounds(wc3, wr2) and em[wr2, wc3] and not pm[wr2, wc3]:
                if not wm[wr2, wc3]:
                    return (Tool.WIRE, wc3, wr2)
                break

    # --- Phase 10: Services ---
    if pop > 200:
        fx, fy = cx, cy - 10
        if in_bounds(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
    if pop > 400:
        px2, py2 = cx + 10, cy + 10
        if in_bounds(px2, py2) and em[py2, px2]:
            return (Tool.POLICESTATION, px2, py2)

    # --- Phase 11: Extend roads reactively ---
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = int(obs.step * 11) % len(road_xs_arr)
        rx_s = int(road_xs_arr[step_k])
        ry_s = int(road_ys_arr[step_k])
        for dy, dx in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx2, ny2 = rx_s + dx, ry_s + dy
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                if nbr_wire[ny2, nx2] and x_min <= nx2 <= x_max:
                    return (Tool.ROAD, nx2, ny2)

    # --- Phase 12: Extend wire reactively ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k = int(obs.step * 7) % len(wire_xs_arr)
        wx_s = int(wire_xs_arr[step_k])
        wy_s = int(wire_ys_arr[step_k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = wx_s + dx2, wy_s + dy2
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                if x_min <= nx2 <= x_max:
                    return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Horizontal-spine layout instead of vertical:
    - Wire runs horizontally across the map at cy
    - Roads run vertically above and below the wire
    - Zones placed above/below roads
    - Two coal plants placed symmetrically
    - Denser zone placement with better COM/IND balance
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    pop = obs.city_pop

    # Wire runs horizontally at wire_row
    wire_row = cy
    # Roads run vertically at wire_row +/- 3
    road_row_u = wire_row - 3  # above
    road_row_d = wire_row + 3  # below
    # Zone rows: center at wire_row +/- 7
    zone_row_u = wire_row - 7
    zone_row_d = wire_row + 7

    road_row_u = max(2, min(WORLD_H - 3, road_row_u))
    road_row_d = max(2, min(WORLD_H - 3, road_row_d))
    zone_row_u = max(2, min(WORLD_H - 3, zone_row_u))
    zone_row_d = max(2, min(WORLD_H - 3, zone_row_d))

    # ---- Step 1: Place primary coal plant left of center ----
    if not np.any(pm):
        return (Tool.COALPOWER, cx - 20, cy)

    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Spine extent scales with population
    if pop < 50:
        half_ext = 8
    elif pop < 200:
        half_ext = 16
    elif pop < 500:
        half_ext = 25
    elif pop < 1000:
        half_ext = 35
    else:
        half_ext = 45

    spine_left = max(2, cx - half_ext)
    spine_right = min(WORLD_W - 3, cx + half_ext)

    # ---- Step 2: Check wire extent on wire_row ----
    wire_present = [c for c in range(WORLD_W) if wm[wire_row, c]]
    road_u_present = set(c for c in range(WORLD_W) if rm[road_row_u, c])
    road_d_present = set(c for c in range(WORLD_W) if rm[road_row_d, c])

    # ---- Step 3: Bootstrap wire near plant ----
    if not wire_present:
        # Start wire at plant location on wire_row
        for dc in range(0, 6):
            for nc in [plant_cx + 3 + dc, plant_cx + 2 + dc]:
                if 0 <= nc < WORLD_W and 0 <= wire_row < WORLD_H:
                    if em[wire_row, nc]:
                        return (Tool.WIRE, nc, wire_row)
        return (Tool.WIRE, plant_cx + 3, wire_row)

    min_wc = min(wire_present)
    max_wc = max(wire_present)

    # ---- Step 4: Connect plant to wire if not adjacent ----
    plant_connected = any(
        abs(pc - min_wc) <= 2 or wm[plant_cy, pc + 1] if pc + 1 < WORLD_W else False
        for pc in plant_cols
    )
    # Simpler: just check if wire exists adjacent to plant
    plant_connected = False
    for pr, pc in zip(plant_rows, plant_cols):
        if abs(pr - wire_row) <= 2 and abs(pc - min_wc) <= 3:
            plant_connected = True
            break

    if not plant_connected:
        # Lay horizontal wire from plant rightward to existing wire
        target_c = min_wc
        for wc in range(plant_cx + 2, target_c + 1):
            if 0 <= wc < WORLD_W:
                if not wm[wire_row, wc] and em[wire_row, wc]:
                    return (Tool.WIRE, wc, wire_row)
        # Lay vertical wire from plant to wire_row
        for wr in range(min(plant_cy + 1, wire_row), max(plant_cy, wire_row) + 1):
            if 0 <= wr < WORLD_H and not pm[wr, plant_cx]:
                if em[wr, plant_cx]:
                    return (Tool.WIRE, plant_cx, wr)

    # ---- Step 5: Extend wire spine horizontally ----
    if max_wc < spine_right:
        nc = max_wc + 1
        if 0 <= nc < WORLD_W and not pm[wire_row, nc]:
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    if min_wc > spine_left:
        nc = min_wc - 1
        if 0 <= nc < WORLD_W and not pm[wire_row, nc]:
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # ---- Step 6: Build roads above and below wire spine ----
    for wc in wire_present:
        if wc < spine_left or wc > spine_right:
            continue
        if wc not in road_u_present:
            if 0 <= road_row_u < WORLD_H and em[road_row_u, wc]:
                return (Tool.ROAD, wc, road_row_u)
        if wc not in road_d_present:
            if 0 <= road_row_d < WORLD_H and em[road_row_d, wc]:
                return (Tool.ROAD, wc, road_row_d)

    # ---- Zone helpers ----
    all_zone_mask = resm | comm | indm

    def zone_area_clear(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not (em[rr, rc] or all_zone_mask[rr, rc]):
                    return False
        return True

    def zone_overlap(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        # Aim for ~30% COM, ~25% IND, ~45% RES
        if com_count / t < 0.30:
            return Tool.COMMERCIAL
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # ---- Step 7: Place zones adjacent to roads ----
    for wc in sorted(wire_present):
        if wc < spine_left or wc > spine_right:
            continue

        # Zones above upper road
        if wc in road_u_present:
            zr = zone_row_u
            zc = wc
            if not zone_overlap(zr, zc) and zone_area_clear(zr, zc):
                return (pick_tool(), zc, zr)

        # Zones below lower road
        if wc in road_d_present:
            zr = zone_row_d
            zc = wc
            if not zone_overlap(zr, zc) and zone_area_clear(zr, zc):
                return (pick_tool(), zc, zr)

    # ---- Step 8: Second coal plant when city grows ----
    if pop > 200 and int(np.sum(pm)) < 9:
        # Place second plant to the right of center
        px2 = cx + 20
        py2 = cy
        px2 = max(2, min(WORLD_W - 4, px2))
        py2 = max(2, min(WORLD_H - 4, py2))
        area_ok = all(
            em[py2 + dr, px2 + dc]
            for dr in [-1, 0, 1]
            for dc in [-1, 0, 1]
            if 0 <= py2 + dr < WORLD_H and 0 <= px2 + dc < WORLD_W
        )
        if area_ok:
            return (Tool.COALPOWER, px2, py2)

    # ---- Step 9: Add second road row further out for more zones ----
    if pop > 150:
        road_row_u2 = wire_row - 11
        road_row_d2 = wire_row + 11
        zone_row_u2 = wire_row - 15
        zone_row_d2 = wire_row + 15

        road_row_u2 = max(2, min(WORLD_H - 3, road_row_u2))
        road_row_d2 = max(2, min(WORLD_H - 3, road_row_d2))
        zone_row_u2 = max(2, min(WORLD_H - 3, zone_row_u2))
        zone_row_d2 = max(2, min(WORLD_H - 3, zone_row_d2))

        road_u2_present = set(c for c in range(WORLD_W) if rm[road_row_u2, c])
        road_d2_present = set(c for c in range(WORLD_W) if rm[road_row_d2, c])

        # Need vertical connector roads to bring road access out
        # Place vertical roads connecting spine roads to outer roads
        for wc in wire_present:
            if wc < spine_left or wc > spine_right:
                continue
            # Connect upper road to outer upper road
            if wc in road_u_present and wc not in road_u2_present:
                for rr in range(road_row_u - 1, road_row_u2 - 1, -1):
                    if 0 <= rr < WORLD_H and em[rr, wc]:
                        return (Tool.ROAD, wc, rr)
                    elif rm[rr, wc]:
                        break
            # Connect lower road to outer lower road
            if wc in road_d_present and wc not in road_d2_present:
                for rr in range(road_row_d + 1, road_row_d2 + 2):
                    if 0 <= rr < WORLD_H and em[rr, wc]:
                        return (Tool.ROAD, wc, rr)
                    elif rm[rr, wc]:
                        break

        # Place zones in outer rows
        for wc in sorted(wire_present):
            if wc < spine_left or wc > spine_right:
                continue
            if wc in road_u2_present:
                zr = zone_row_u2
                if not zone_overlap(zr, wc) and zone_area_clear(zr, wc):
                    return (pick_tool(), wc, zr)
            if wc in road_d2_present:
                zr = zone_row_d2
                if not zone_overlap(zr, wc) and zone_area_clear(zr, wc):
                    return (pick_tool(), wc, zr)

    # ---- Step 10: Gap filling ----
    for wc in wire_present:
        if wc < spine_left or wc > spine_right:
            continue
        if wc not in road_u_present and 0 <= road_row_u < WORLD_H:
            if em[road_row_u, wc]:
                return (Tool.ROAD, wc, road_row_u)
        if wc not in road_d_present and 0 <= road_row_d < WORLD_H:
            if em[road_row_d, wc]:
                return (Tool.ROAD, wc, road_row_d)

    # ---- Step 11: Densify zones along existing roads ----
    for offset in range(-half_ext, half_ext + 1, 3):
        zc = cx + offset
        if zc < 2 or zc > WORLD_W - 3:
            continue
        for zr in [zone_row_u, zone_row_d]:
            if not zone_overlap(zr, zc) and zone_area_clear(zr, zc):
                road_near = (
                    any(rm[road_row_u, zc + dc] for dc in [-1, 0, 1] if 0 <= zc + dc < WORLD_W) or
                    any(rm[road_row_d, zc + dc] for dc in [-1, 0, 1] if 0 <= zc + dc < WORLD_W)
                )
                if road_near:
                    return (pick_tool(), zc, zr)

    return None

def act(obs, state):
    """
    Multi-neighborhood city builder with two clusters.
    Cluster A: left side (coal plant + RCI zones)
    Cluster B: right side (coal plant + RCI zones)
    Connected by a horizontal road/wire spine.
    Better zone mix: ~50% RES, 25% COM, 25% IND
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Two cluster anchors
    AX, AY = 35, 45   # left cluster
    BX, BY = 85, 45   # right cluster

    # State tracking
    if 'phase' not in state:
        state['phase'] = 0

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        r_frac = res_count / t
        c_frac = com_count / t
        i_frac = ind_count / t
        if i_frac < 0.22:
            return Tool.INDUSTRIAL
        if c_frac < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Step 1: Place plant A if no plant exists
    if not np.any(pm):
        return (Tool.COALPOWER, AX, AY)

    # Find all plant centers
    plant_rows, plant_cols = np.where(pm)
    plant_count = int(np.sum(pm))

    # Step 2: Place plant B if only one plant and pop > 100
    if plant_count < 9 and obs.city_pop > 80:
        # Check if plant B area is empty
        if bool(em[BY, BX]):
            return (Tool.COALPOWER, BX, BY)

    # Wire layout: horizontal spine at AY-1 connecting both clusters
    wire_spine_y = AY - 2
    road_spine_y = AY + 2

    # Wire columns: from AX-15 to BX+15
    wire_left = AX - 15
    wire_right = BX + 15

    # Build wire spine (horizontal)
    power_map = pm | wm

    # Horizontal wire at wire_spine_y
    wire_h_targets = [(x, wire_spine_y) for x in range(wire_left, wire_right + 1)]

    # Vertical wires down to plants from spine
    wire_v_a = [(AX + dx, wire_spine_y + dy)
                for dx in range(-1, 2) for dy in range(0, 8)]
    wire_v_b = [(BX + dx, wire_spine_y + dy)
                for dx in range(-1, 2) for dy in range(0, 8)]

    # Vertical wires up (for upper zones)
    wire_v_up = [(AX + dx * 4, wire_spine_y - dy)
                 for dx in range(-3, 4) for dy in range(1, 8)]
    wire_v_up_b = [(BX + dx * 4, wire_spine_y - dy)
                   for dx in range(-3, 4) for dy in range(1, 8)]

    all_wire_targets = wire_h_targets + wire_v_a + wire_v_b + wire_v_up + wire_v_up_b

    for (wx, wy) in all_wire_targets:
        if not in_bounds(wx, wy):
            continue
        if bool(wm[wy, wx]) or bool(pm[wy, wx]) or bool(rm[wy, wx]):
            continue
        if not bool(em[wy, wx]):
            continue
        for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = wx + ddx, wy + ddy
            if in_bounds(nx, ny) and bool(power_map[ny, nx]):
                return (Tool.WIRE, wx, wy)

    # Road layout: horizontal spine + cross streets at both clusters
    road_h_targets = [(x, road_spine_y) for x in range(wire_left, wire_right + 1)]

    # Cross streets every 4 cols around cluster A
    cross_a = []
    for dx in range(-12, 13, 4):
        cx2 = AX + dx
        for dy in range(-10, 11):
            cross_a.append((cx2, road_spine_y + dy))

    # Cross streets every 4 cols around cluster B
    cross_b = []
    for dx in range(-12, 13, 4):
        cx2 = BX + dx
        for dy in range(-10, 11):
            cross_b.append((cx2, road_spine_y + dy))

    # Vertical road spines at AX+2 and BX+2
    road_v_a = [(AX + 2, y) for y in range(AY - 12, AY + 13)]
    road_v_b = [(BX + 2, y) for y in range(BY - 12, BY + 13)]

    all_road_targets = road_h_targets + road_v_a + road_v_b + cross_a + cross_b

    for (rx, ry) in all_road_targets:
        if not in_bounds(rx, ry):
            continue
        if bool(rm[ry, rx]) or bool(pm[ry, rx]) or bool(wm[ry, rx]):
            continue
        if not bool(em[ry, rx]):
            continue
        adj_road = False
        for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = rx + ddx, ry + ddy
            if in_bounds(nx, ny) and bool(rm[ny, nx]):
                adj_road = True
                break
        adj_plant = False
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1),(2,0),(-2,0),(0,2),(0,-2)]:
            nx, ny = rx + ddx, ry + ddy
            if in_bounds(nx, ny) and bool(pm[ny, nx]):
                adj_plant = True
                break
        if adj_road or adj_plant:
            return (Tool.ROAD, rx, ry)

    # Zone placement near roads AND power
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_mask = resm | comm | indm
    cand = em & nbr_road & nbr_power
    cand[0:2, :] = False
    cand[WORLD_H-2:, :] = False
    cand[:, 0:2] = False
    cand[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        key = int(obs.step * 17 + int(obs.city_pop * 3) + 1) % len(cxs)
        for offset in range(min(len(cxs), 80)):
            k = (key + offset * 13) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            ok = True
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    ny2, nx2 = zy + dr, zx + dc
                    if not in_bounds(nx2, ny2):
                        ok = False; break
                    if not (bool(em[ny2, nx2]) or bool(zone_mask[ny2, nx2])):
                        ok = False; break
                if not ok:
                    break
            if ok:
                return (pick_tool(), zx, zy)

    # Add third power plant if large enough
    if obs.city_pop > 400 and plant_count < 18:
        p3x = (AX + BX) // 2
        p3y = AY + 15
        p3x = max(2, min(WORLD_W - 3, p3x))
        p3y = max(2, min(WORLD_H - 3, p3y))
        if bool(em[p3y, p3x]):
            return (Tool.COALPOWER, p3x, p3y)

    # Services
    if obs.city_pop > 150:
        for fx, fy in [(AX - 8, AY - 8), (BX + 8, BY - 8)]:
            fx = max(1, min(WORLD_W-2, fx))
            fy = max(1, min(WORLD_H-2, fy))
            if bool(em[fy, fx]):
                return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 350:
        for fx, fy in [(AX + 8, AY + 10), (BX - 8, BY + 10)]:
            fx = max(1, min(WORLD_W-2, fx))
            fy = max(1, min(WORLD_H-2, fy))
            if bool(em[fy, fx]):
                return (Tool.POLICESTATION, fx, fy)

    # Fallback: extend wire from frontier
    wys2, wxs2 = np.where(wm)
    if len(wxs2) > 0:
        k3 = int(obs.step * 7) % len(wxs2)
        wx2, wy2 = int(wxs2[k3]), int(wys2[k3])
        for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = wx2 + ddx, wy2 + ddy
            if in_bounds(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                return (Tool.WIRE, nx, ny)

    # Fallback: extend road from frontier
    rys2, rxs2 = np.where(rm)
    if len(rxs2) > 0:
        k2 = int(obs.step * 11) % len(rxs2)
        rx2, ry2 = int(rxs2[k2]), int(rys2[k2])
        for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = rx2 + ddx, ry2 + ddy
            if in_bounds(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                return (Tool.ROAD, nx, ny)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map every step to decide next action
    - Layout: coal plant at center, wire spine vertical, roads flanking, zones packed tightly
    - Key changes from parent:
      1. Connect wire directly to plant (no gap)
      2. Place zones closer to roads (distance 1 not 3)
      3. More aggressive road building before zones
      4. Fix wire extension logic (was checking wire_top > ytop but ny >= 0 only)
      5. Horizontal roads added earlier
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # --- Phase 1: Place coal plant if missing ---
    if not np.any(pm):
        return (Tool.COALPOWER, 60, 50)

    # Find plant center
    plant_rows, plant_cols = np.where(pm)
    pcx = int(np.median(plant_cols))
    pcy = int(np.median(plant_rows))

    # Layout constants:
    # Wire spine at pcx+3 (closer to plant so it's adjacent)
    # Roads at pcx (left road, also adjacent to plant) and pcx+6 (right road)
    wc = pcx + 3   # wire column
    rl = pcx       # left road column (adjacent to plant right edge)
    rr = pcx + 6   # right road column

    span = min(30, max(10, 10 + obs.city_pop // 15))
    ytop = max(2, pcy - span)
    ybot = min(WORLD_H - 3, pcy + span)

    # Clamp columns
    wc = max(1, min(WORLD_W - 2, wc))
    rl = max(2, min(WORLD_W - 3, rl))
    rr = max(2, min(WORLD_W - 3, rr))

    # --- Phase 2: Extend wire spine ---
    # Wire must connect to plant or existing wire
    # Plant occupies [pcy-1..pcy+1] x [pcx-1..pcx+1]
    # wc = pcx+3, so wc is 2 cols right of plant edge -> need to bridge

    wire_ys = sorted(y for y in range(WORLD_H) if wm[y, wc])

    if not wire_ys:
        # Place wire at pcy, wc - but need adjacency to plant
        # Plant right edge at pcx+1, wc = pcx+3 -> need wire at pcx+2 first
        # Actually: place wire adjacent to plant at pcx+2
        bridge_x = pcx + 2
        bridge_x = max(0, min(WORLD_W - 1, bridge_x))
        if not wm[pcy, bridge_x]:
            return (Tool.WIRE, bridge_x, pcy)
        # Then place wire at wc
        return (Tool.WIRE, wc, pcy)

    # Check if bridge wire exists (pcx+2)
    bridge_x = max(0, min(WORLD_W - 1, pcx + 2))
    if not wm[pcy, bridge_x] and not wm[pcy, wc]:
        return (Tool.WIRE, bridge_x, pcy)

    wire_top = wire_ys[0]
    wire_bot = wire_ys[-1]
    wire_set = set(wire_ys)

    # Extend wire downward
    if wire_bot < ybot:
        ny = wire_bot + 1
        if 0 <= ny < WORLD_H:
            return (Tool.WIRE, wc, ny)

    # Extend wire upward
    if wire_top > ytop:
        ny = wire_top - 1
        if 0 <= ny < WORLD_H:
            return (Tool.WIRE, wc, ny)

    # --- Phase 3: Build left road column ---
    # Road at column rl for all rows in wire span
    for wy in sorted(wire_set, key=lambda y: abs(y - pcy)):
        if ytop <= wy <= ybot:
            if not rm[wy, rl] and em[wy, rl]:
                return (Tool.ROAD, rl, wy)

    # --- Phase 4: Build right road column ---
    for wy in sorted(wire_set, key=lambda y: abs(y - pcy)):
        if ytop <= wy <= ybot:
            if not rm[wy, rr] and em[wy, rr]:
                return (Tool.ROAD, rr, wy)

    road_rows_l = set(y for y in range(WORLD_H) if rm[y, rl])
    road_rows_r = set(y for y in range(WORLD_H) if rm[y, rr])

    # --- Phase 5: Horizontal connectors early ---
    # Connect left and right roads at regular intervals
    connect_rows = sorted(
        [y for y in road_rows_l & road_rows_r if ytop <= y <= ybot],
        key=lambda y: abs(y - pcy)
    )
    for hy in connect_rows[::4]:  # every 4th shared row
        for hx in range(min(rl, rr) + 1, max(rl, rr)):
            if 0 <= hx < WORLD_W and not rm[hy, hx]:
                return (Tool.ROAD, hx, hy)

    # --- Phase 6: Place zones adjacent to roads ---
    all_zone_m = res_m | com_m | ind_m
    res_count = max(1, int(np.sum(res_m)) // 9)
    com_count = max(1, int(np.sum(com_m)) // 9)
    ind_count = max(1, int(np.sum(ind_m)) // 9)

    def pick_zone():
        total = res_count + com_count + ind_count
        if com_count * 4 < total:
            return Tool.COMMERCIAL
        if ind_count * 4 < total:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_clear(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr2, rc2 = zr + dr, zc + dc
                if rr2 < 0 or rr2 >= WORLD_H or rc2 < 0 or rc2 >= WORLD_W:
                    return False
                if not em[rr2, rc2]:
                    return False
        return True

    def zone_nearby(zr, zc):
        r0 = max(0, zr - 2)
        r1 = min(WORLD_H, zr + 3)
        c0 = max(0, zc - 2)
        c1 = min(WORLD_W, zc + 3)
        return np.any(all_zone_m[r0:r1, c0:c1])

    # Zone columns: one step away from roads (road is at edge of zone)
    # Left outer: zone center at rl-3 (road at rl is adjacent to right of zone)
    # Right outer: zone center at rr+3
    # Between road and wire: rl+3 (if gap allows), rr-3
    zl = rl - 3
    zr_col = rr + 3
    zl_inner = rl + 3
    zr_inner = rr - 3

    for col in [zl, zr_col, zl_inner, zr_inner]:
        col = max(2, min(WORLD_W - 3, col))

    zl = max(2, min(WORLD_W - 3, zl))
    zr_col = max(2, min(WORLD_W - 3, zr_col))
    zl_inner = max(2, min(WORLD_W - 3, zl_inner))
    zr_inner = max(2, min(WORLD_W - 3, zr_inner))

    candidate_rows = sorted(
        [wy for wy in wire_set if ytop <= wy <= ybot],
        key=lambda y: abs(y - pcy)
    )

    for zy in candidate_rows:
        near_l = any(abs(zy - ry) <= 1 for ry in road_rows_l)
        near_r = any(abs(zy - ry) <= 1 for ry in road_rows_r)

        # Left outer
        if near_l and 2 <= zl <= WORLD_W - 3:
            if not zone_nearby(zy, zl) and zone_clear(zy, zl):
                return (pick_zone(), zl, zy)

        # Right outer
        if near_r and 2 <= zr_col <= WORLD_W - 3:
            if not zone_nearby(zy, zr_col) and zone_clear(zy, zr_col):
                return (pick_zone(), zr_col, zy)

        # Left inner (between left road and wire)
        if near_l and 2 <= zl_inner <= WORLD_W - 3 and zl_inner != wc:
            if not zone_nearby(zy, zl_inner) and zone_clear(zy, zl_inner):
                return (pick_zone(), zl_inner, zy)

        # Right inner (between wire and right road)
        if near_r and 2 <= zr_inner <= WORLD_W - 3 and zr_inner != wc:
            if not zone_nearby(zy, zr_inner) and zone_clear(zy, zr_inner):
                return (pick_zone(), zr_inner, zy)

    # --- Phase 7: Second cluster when population grows ---
    if obs.city_pop > 150 and not state.get("cluster2", False):
        # New cluster offset by 20 to the left
        px2 = pcx - 20
        py2 = pcy
        px2 = max(4, min(WORLD_W - 4, px2))
        py2 = max(4, min(WORLD_H - 4, py2))
        wc2 = px2 + 3
        wc2 = max(1, min(WORLD_W - 2, wc2))

        # Build wire bridge from existing wire spine leftward at pcy
        # Connect from wc-1 down to wc2
        for wx in range(wc - 1, wc2 - 1, -1):
            if 0 <= wx < WORLD_W and not wm[pcy, wx]:
                return (Tool.WIRE, wx, pcy)

        # Place second coal plant
        clear2 = all(
            0 <= py2 + dr < WORLD_H and 0 <= px2 + dc < WORLD_W and em[py2 + dr, px2 + dc]
            for dr in [-1, 0, 1] for dc in [-1, 0, 1]
        )
        if clear2:
            state["cluster2"] = True
            return (Tool.COALPOWER, px2, py2)

    # --- Phase 8: Wire additional horizontal connections for power ---
    # Connect left road to wire spine via horizontal wire at pcy
    if not state.get("h_wire_done", False):
        for wx in range(min(rl, wc) + 1, max(rl, wc)):
            if 0 <= wx < WORLD_W and not wm[pcy, wx] and not rm[pcy, wx]:
                return (Tool.WIRE, wx, pcy)
        # Connect right road to wire
        for wx in range(min(rr, wc) + 1, max(rr, wc)):
            if 0 <= wx < WORLD_W and not wm[pcy, wx] and not rm[pcy, wx]:
                return (Tool.WIRE, wx, pcy)
        state["h_wire_done"] = True

    return None

def act(obs, state):
    """
    Combined policy: cross-shaped wire from plant + horizontal corridor
    - Coal plant near center-left
    - Vertical + horizontal wire spines from plant
    - Roads flank both spines
    - Aggressive zone placement wherever road+wire coverage exists
    - Scales infrastructure with population
    - Multiple power plants for growth
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    all_zone = resm | comm | indm

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    pop = obs.city_pop

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(total_zones, 1)
        # Target: 40% res, 30% com, 30% ind
        if ind_count / t < 0.28:
            return Tool.INDUSTRIAL
        if com_count / t < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zy, zx):
        if zy < 1 or zy > WORLD_H - 2 or zx < 1 or zx > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zy + dr, zx + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone[rr, rc]:
                    return False
        return True

    # --- Phase 1: Place first coal plant ---
    plant_x, plant_y = 55, 50
    if not np.any(pm):
        return (Tool.COALPOWER, plant_x, plant_y)

    # Find plant center
    plant_rows, plant_cols = np.where(pm)
    px = int(np.median(plant_cols))
    py = int(np.median(plant_rows))

    # Spine layout: wire column to the right of plant, wire row below plant
    wire_col_v = px + 3   # vertical spine column
    wire_row_h = py + 3   # horizontal spine row

    # Roads flanking spines
    road_col_r = wire_col_v + 1
    road_col_l = wire_col_v - 1
    road_row_above = wire_row_h - 1
    road_row_below = wire_row_h + 1

    # Scale extent with population
    pop_ext = min(40, max(12, pop // 15))
    v_tmin = max(2, py - pop_ext)
    v_tmax = min(WORLD_H - 3, py + pop_ext)
    h_lmin = max(2, px - pop_ext)
    h_rmax = min(WORLD_W - 3, px + pop_ext)

    # Current wire extent on each spine
    wire_in_vcol = sorted([r for r in range(WORLD_H) if wm[r, wire_col_v]])
    wire_in_hrow = sorted([c for c in range(WORLD_W) if wm[wire_row_h, c]])

    # --- Phase 2: Build vertical wire spine ---
    if not wire_in_vcol:
        # Seed near plant
        for dy in range(-2, 4):
            ny = py + dy
            if in_bounds(wire_col_v, ny) and (em[ny, wire_col_v] or wm[ny, wire_col_v]):
                return (Tool.WIRE, wire_col_v, ny)
    else:
        min_vw = wire_in_vcol[0]
        max_vw = wire_in_vcol[-1]
        if max_vw < v_tmax:
            nr = max_vw + 1
            if in_bounds(wire_col_v, nr) and em[nr, wire_col_v] and not pm[nr, wire_col_v]:
                return (Tool.WIRE, wire_col_v, nr)
        if min_vw > v_tmin:
            nr = min_vw - 1
            if in_bounds(wire_col_v, nr) and em[nr, wire_col_v] and not pm[nr, wire_col_v]:
                return (Tool.WIRE, wire_col_v, nr)

    # --- Phase 3: Build horizontal wire spine ---
    if not wire_in_hrow:
        for dx in range(-2, 4):
            nx = px + dx
            if in_bounds(nx, wire_row_h) and (em[wire_row_h, nx] or wm[wire_row_h, nx]):
                return (Tool.WIRE, nx, wire_row_h)
    else:
        min_hw = wire_in_hrow[0]
        max_hw = wire_in_hrow[-1]
        if max_hw < h_rmax:
            nc = max_hw + 1
            if in_bounds(nc, wire_row_h) and em[wire_row_h, nc] and not pm[wire_row_h, nc]:
                return (Tool.WIRE, nc, wire_row_h)
        if min_hw > h_lmin:
            nc = min_hw - 1
            if in_bounds(nc, wire_row_h) and em[wire_row_h, nc] and not pm[wire_row_h, nc]:
                return (Tool.WIRE, nc, wire_row_h)

    # --- Phase 4: Roads flanking vertical spine ---
    if wire_in_vcol:
        for wr in wire_in_vcol:
            if in_bounds(road_col_r, wr) and em[wr, road_col_r]:
                return (Tool.ROAD, road_col_r, wr)
            if in_bounds(road_col_l, wr) and em[wr, road_col_l]:
                return (Tool.ROAD, road_col_l, wr)

    # --- Phase 5: Roads flanking horizontal spine ---
    if wire_in_hrow:
        for wc in wire_in_hrow:
            if in_bounds(wc, road_row_above) and em[road_row_above, wc] and not pm[road_row_above, wc]:
                return (Tool.ROAD, wc, road_row_above)
            if in_bounds(wc, road_row_below) and em[road_row_below, wc] and not pm[road_row_below, wc]:
                return (Tool.ROAD, wc, road_row_below)

    # --- Phase 6: Vertical connector roads every 6 cols along horizontal spine ---
    if wire_in_hrow:
        for wc in wire_in_hrow:
            if (wc - h_lmin) % 6 == 0:
                for wr in range(road_row_above, road_row_below + 1):
                    if in_bounds(wc, wr) and em[wr, wc] and not pm[wr, wc] and not wm[wr, wc]:
                        return (Tool.ROAD, wc, wr)

    # --- Phase 7: Build proximity masks for zone placement ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # --- Phase 8: Zone placement ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, :2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys_a, cxs_a = np.where(cand_mask)
    if len(cxs_a) > 0:
        # Sort: prefer near both spines (cross center)
        dist_v = np.abs(cxs_a.astype(int) - wire_col_v)
        dist_h = np.abs(cys_a.astype(int) - wire_row_h)
        dists = np.minimum(dist_v, dist_h)
        sort_idx = np.argsort(dists)
        step_off = int(obs.step * 3) % max(len(sort_idx), 1)
        placed = 0
        for i in range(min(len(cxs_a), 100)):
            k = int(sort_idx[(step_off + i) % len(sort_idx)])
            zx, zy = int(cxs_a[k]), int(cys_a[k])
            if zone_area_ok(zy, zx):
                return (pick_tool(), zx, zy)
            placed += 1
            if placed > 80:
                break

    # --- Phase 9: Extend roads reactively near wire ---
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = int(obs.step * 11) % len(road_xs_arr)
        for offset in range(min(len(road_xs_arr), 25)):
            k = (step_k + offset * 7) % len(road_xs_arr)
            rx, ry = int(road_xs_arr[k]), int(road_ys_arr[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx]:
                    if nbr_wire[ny, nx]:
                        return (Tool.ROAD, nx, ny)

    # --- Phase 10: Second power plant ---
    plant_tile_count = int(np.sum(pm))
    plant_count = max(1, plant_tile_count // 6)
    if pop > 150 and plant_count < 2:
        p2x = px + 30
        p2y = py
        if in_bounds(p2x, p2y) and em[p2y, p2x]:
            nearby = any(
                in_bounds(p2x + ddx, p2y + ddy) and pm[p2y + ddy, p2x + ddx]
                for ddy in range(-6, 7) for ddx in range(-6, 7)
            )
            if not nearby:
                return (Tool.COALPOWER, p2x, p2y)
        # Wire bridge to second plant along horizontal spine
        for wc2 in range(max(wire_in_hrow, default=px) + 1, min(p2x + 5, WORLD_W - 2)):
            if in_bounds(wc2, wire_row_h) and em[wire_row_h, wc2] and not pm[wire_row_h, wc2]:
                return (Tool.WIRE, wc2, wire_row_h)

    # --- Phase 11: Third power plant ---
    if pop > 500 and plant_count < 3:
        p3x = px
        p3y = py + 30
        if in_bounds(p3x, p3y) and em[p3y, p3x]:
            nearby = any(
                in_bounds(p3x + ddx, p3y + ddy) and pm[p3y + ddy, p3x + ddx]
                for ddy in range(-6, 7) for ddx in range(-6, 7)
            )
            if not nearby:
                return (Tool.COALPOWER, p3x, p3y)
        # Wire downward along vertical spine
        for wr2 in range(max(wire_in_vcol, default=py) + 1, min(p3y + 5, WORLD_H - 2)):
            if in_bounds(wire_col_v, wr2) and em[wr2, wire_col_v] and not pm[wr2, wire_col_v]:
                return (Tool.WIRE, wire_col_v, wr2)

    # --- Phase 12: Services ---
    if pop > 150:
        fsx, fsy = px - 8, py - 8
        if in_bounds(fsx, fsy) and em[fsy, fsx]:
            return (Tool.FIRESTATION, fsx, fsy)
    if pop > 300:
        psx, psy = px + 10, py - 8
        if in_bounds(psx, psy) and em[psy, psx]:
            return (Tool.POLICESTATION, psx, psy)

    # --- Phase 13: Extend wire reactively ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 20)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = wx + dx2, wy + dy2
                if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                    return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy v3:
    - Reads tile_map each step, fully reactive
    - Uses BFS-style frontier expansion for wire and road
    - Denser zone placement with proper ratio management
    - Multiple power plants scaled to city size
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Place first coal plant if missing ---
    if not np.any(pm):
        return (Tool.COALPOWER, 58, 50)

    # Find plant center
    plant_ys, plant_xs = np.where(pm)
    px = int(np.median(plant_xs))
    py = int(np.median(plant_ys))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Scale extent with population
    pop_ext = min(40, max(12, obs.city_pop // 15))

    # Wire spines: cross pattern from plant
    wire_col_v = px + 4   # vertical spine column (right of plant)
    wire_row_h = py       # horizontal spine row (through plant center)

    v_tmin = max(2, py - pop_ext)
    v_tmax = min(WORLD_H - 3, py + pop_ext)
    h_lmin = max(2, px - pop_ext)
    h_rmax = min(WORLD_W - 3, px + pop_ext + 10)

    # --- Build cross wire network reactively ---
    # Vertical spine
    wire_in_vcol = sorted([r for r in range(WORLD_H) if wm[r, wire_col_v]])
    if not wire_in_vcol:
        # Bootstrap wire from plant area
        for dy in range(-4, 5):
            ny = py + dy
            if in_bounds(wire_col_v, ny) and (em[ny, wire_col_v] or wm[ny, wire_col_v]):
                return (Tool.WIRE, wire_col_v, ny)
    else:
        min_vw = wire_in_vcol[0]
        max_vw = wire_in_vcol[-1]
        if max_vw < v_tmax:
            nr = max_vw + 1
            if in_bounds(wire_col_v, nr) and em[nr, wire_col_v] and not pm[nr, wire_col_v]:
                return (Tool.WIRE, wire_col_v, nr)
        if min_vw > v_tmin:
            nr = min_vw - 1
            if in_bounds(wire_col_v, nr) and em[nr, wire_col_v] and not pm[nr, wire_col_v]:
                return (Tool.WIRE, wire_col_v, nr)

    # Horizontal spine
    wire_in_hrow = sorted([c for c in range(WORLD_W) if wm[wire_row_h, c]])
    if not wire_in_hrow:
        for dx in range(-4, 5):
            nx = px + dx
            if in_bounds(nx, wire_row_h) and (em[wire_row_h, nx] or wm[wire_row_h, nx]):
                return (Tool.WIRE, nx, wire_row_h)
    else:
        min_hw = wire_in_hrow[0]
        max_hw = wire_in_hrow[-1]
        if max_hw < h_rmax:
            nc = max_hw + 1
            if in_bounds(nc, wire_row_h) and em[wire_row_h, nc] and not pm[wire_row_h, nc]:
                return (Tool.WIRE, nc, wire_row_h)
        if min_hw > h_lmin:
            nc = min_hw - 1
            if in_bounds(nc, wire_row_h) and em[wire_row_h, nc] and not pm[wire_row_h, nc]:
                return (Tool.WIRE, nc, wire_row_h)

    # --- Second horizontal spine (above plant) ---
    wire_row_h2 = py - 8
    if obs.city_pop > 100 and in_bounds(0, wire_row_h2):
        wire_in_hrow2 = sorted([c for c in range(WORLD_W) if wm[wire_row_h2, c]])
        if not wire_in_hrow2:
            for dx in range(-2, 3):
                nx = px + dx
                if in_bounds(nx, wire_row_h2) and em[wire_row_h2, nx]:
                    return (Tool.WIRE, nx, wire_row_h2)
        else:
            min_h2 = wire_in_hrow2[0]
            max_h2 = wire_in_hrow2[-1]
            h2_rmax = min(WORLD_W - 3, px + pop_ext + 5)
            h2_lmin = max(2, px - pop_ext)
            if max_h2 < h2_rmax:
                nc = max_h2 + 1
                if in_bounds(nc, wire_row_h2) and em[wire_row_h2, nc] and not pm[wire_row_h2, nc]:
                    return (Tool.WIRE, nc, wire_row_h2)
            if min_h2 > h2_lmin:
                nc = min_h2 - 1
                if in_bounds(nc, wire_row_h2) and em[wire_row_h2, nc] and not pm[wire_row_h2, nc]:
                    return (Tool.WIRE, nc, wire_row_h2)

        # Connect vertical spine to second horizontal spine
        for conn_y in range(wire_row_h2 + 1, wire_row_h):
            if in_bounds(wire_col_v, conn_y) and em[conn_y, wire_col_v] and not pm[conn_y, wire_col_v]:
                if not wm[conn_y, wire_col_v]:
                    return (Tool.WIRE, wire_col_v, conn_y)

    # --- Roads flanking wire spines ---
    # Two roads flanking the vertical wire spine
    for road_col in [wire_col_v - 1, wire_col_v + 1]:
        for wr in wire_in_vcol:
            if in_bounds(road_col, wr) and em[wr, road_col] and not pm[wr, road_col]:
                return (Tool.ROAD, road_col, wr)

    # Two roads flanking the horizontal wire spine
    for road_row in [wire_row_h - 1, wire_row_h + 1]:
        for wc in wire_in_hrow:
            if in_bounds(wc, road_row) and em[road_row, wc] and not pm[road_row, wc]:
                return (Tool.ROAD, wc, road_row)

    # Roads flanking second horizontal spine
    if obs.city_pop > 100 and in_bounds(0, wire_row_h2):
        wire_in_hrow2 = [c for c in range(WORLD_W) if wm[wire_row_h2, c]]
        for road_row2 in [wire_row_h2 - 1, wire_row_h2 + 1]:
            for wc in wire_in_hrow2:
                if in_bounds(wc, road_row2) and em[road_row2, wc] and not pm[road_row2, wc]:
                    return (Tool.ROAD, wc, road_row2)

    # --- Build proximity masks ---
    def expand_mask(base, radius=2):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-radius, radius + 1):
            for dx in range(-radius, radius + 1):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                result[r0:r1, c0:c1] |= base[sr0:sr1, sc0:sc1]
        return result

    nbr_road = expand_mask(rm, 2)
    nbr_wire = expand_mask(wm | pm, 2)

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and not zone_tiles[nr, nc]:
                    return False
        return True

    # --- Candidate zone placement ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Sort by distance to nearest wire spine (prefer close to wire)
        dist_v = np.abs(cxs - wire_col_v)
        dist_h = np.abs(cys - wire_row_h)
        # Prefer candidates close to wire but offset by step for variety
        score = dist_v * 2 + dist_h
        order = np.argsort(score)
        step_off = int(obs.step * 7) % max(len(order), 1)
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            if i > 100:
                break

    # --- Extend roads near wire ---
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 30)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx]:
                    if nbr_wire[ny, nx]:
                        return (Tool.ROAD, nx, ny)

    # --- Additional power plants scaled to city size ---
    # Second plant: south of first
    if total_zones > 12 or obs.city_pop > 250:
        p2x, p2y = px, py + 20
        if in_bounds(p2x, p2y):
            nearby2 = any(
                in_bounds(p2x + ddx, p2y + ddy) and pm[p2y + ddy, p2x + ddx]
                for ddy in range(-8, 9) for ddx in range(-8, 9)
            )
            if not nearby2 and em[p2y, p2x]:
                return (Tool.COALPOWER, p2x, p2y)
            # Wire to connect south plant
            for wc2 in range(wire_row_h + 1, p2y - 1):
                if in_bounds(wire_col_v, wc2) and em[wc2, wire_col_v] and not pm[wc2, wire_col_v]:
                    return (Tool.WIRE, wire_col_v, wc2)

    # Third plant: east
    if obs.city_pop > 500:
        p3x, p3y = px + 30, py
        if in_bounds(p3x, p3y):
            nearby3 = any(
                in_bounds(p3x + ddx, p3y + ddy) and pm[p3y + ddy, p3x + ddx]
                for ddy in range(-8, 9) for ddx in range(-8, 9)
            )
            if not nearby3 and em[p3y, p3x]:
                return (Tool.COALPOWER, p3x, p3y)
            # Wire horizontal bridge to third plant
            for wc3 in range(wire_col_v + 1, p3x - 1):
                if in_bounds(wc3, wire_row_h) and em[wire_row_h, wc3] and not pm[wire_row_h, wc3]:
                    return (Tool.WIRE, wc3, wire_row_h)

    # --- Services ---
    if obs.city_pop > 80:
        fsx, fsy = px - 10, py - 10
        if in_bounds(fsx, fsy) and em[fsy, fsx]:
            return (Tool.FIRESTATION, fsx, fsy)
    if obs.city_pop > 120:
        psx, psy = px + 10, py - 10
        if in_bounds(psx, psy) and em[psy, psx]:
            return (Tool.POLICESTATION, psx, psy)

    # --- Grow wire frontier from existing wire ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 25)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = wx + dx2, wy + dy2
                if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                    # Only extend wire if it's toward a zone-candidate direction
                    if nbr_road[ny2, nx2] or abs(nx2 - wire_col_v) < 3 or abs(ny2 - wire_row_h) < 3:
                        return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map every step to decide next action
    - Builds a compact cluster: coal plant, wire spine, road, zones
    - Uses current map state to find next placement reactively
    - Expands based on observed population growth
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    all_zone_mask = resm | comm | indm

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    pop = obs.city_pop
    powered = obs.powered_zones

    # City center - slightly above middle for better layout
    cx, cy = WORLD_W // 2, WORLD_H // 2 - 5

    # --- Phase 1: Place coal power plant if none exists ---
    if not np.any(pm):
        px, py = cx - 8, cy
        px = max(2, min(WORLD_W - 3, px))
        py = max(2, min(WORLD_H - 3, py))
        return (Tool.COALPOWER, px, py)

    # Find plant centroid
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Layout: wire spine column, road column, zone columns
    wire_col = plant_cx + 4
    road_col = wire_col + 2
    left_zone_col = wire_col - 5
    right_zone_col = road_col + 5

    wire_col = max(2, min(WORLD_W - 3, wire_col))
    road_col = max(2, min(WORLD_W - 3, road_col))
    left_zone_col = max(3, min(WORLD_W - 4, left_zone_col))
    right_zone_col = max(3, min(WORLD_W - 4, right_zone_col))

    # Spine extent adapts to population
    if pop < 30:
        spine_half = 5
    elif pop < 100:
        spine_half = 9
    elif pop < 300:
        spine_half = 14
    elif pop < 700:
        spine_half = 20
    else:
        spine_half = 26

    target_min = max(1, cy - spine_half)
    target_max = min(WORLD_H - 2, cy + spine_half)

    # Current wire/road state
    wire_rows_on_spine = [r for r in range(WORLD_H) if wm[r, wire_col]]
    road_rows_on_col = [r for r in range(WORLD_H) if rm[r, road_col]]

    # --- Phase 2: Bootstrap wire adjacent to plant ---
    if not wire_rows_on_spine:
        for dy in range(-1, 4):
            nr = plant_cy + dy
            if 0 <= nr < WORLD_H:
                if not pm[nr, wire_col]:
                    if em[nr, wire_col]:
                        return (Tool.WIRE, wire_col, nr)
        # Try planting at cy if stuck
        if 0 <= cy < WORLD_H and em[cy, wire_col]:
            return (Tool.WIRE, wire_col, cy)
        return None

    min_wire_row = min(wire_rows_on_spine)
    max_wire_row = max(wire_rows_on_spine)

    # --- Phase 3: Extend wire spine toward target bounds ---
    # Extend downward
    if max_wire_row < target_max:
        nr = max_wire_row + 1
        if 0 <= nr < WORLD_H and not pm[nr, wire_col] and em[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)

    # Extend upward
    if min_wire_row > target_min:
        nr = min_wire_row - 1
        if 0 <= nr < WORLD_H and not pm[nr, wire_col] and em[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)

    # --- Phase 4: Build road column ---
    for r in wire_rows_on_spine:
        if target_min <= r <= target_max:
            if 0 <= road_col < WORLD_W and not rm[r, road_col] and em[r, road_col]:
                return (Tool.ROAD, road_col, r)

    # --- Helper functions ---
    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                # Only allow empty or same zone type
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_present(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def wire_near(zr, zc, radius=5):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def road_near(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        # Prefer residential, then commercial, then industrial
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Zone placement rows (every 4 rows for more spacing)
    zone_rows = list(range(max(2, target_min + 1), min(WORLD_H - 2, target_max), 4))

    # --- Phase 5: Lateral wires toward left zone column ---
    for wr in wire_rows_on_spine:
        if target_min <= wr <= target_max:
            # Walk left from wire spine to left_zone_col
            reached = False
            for wc in range(wire_col - 1, left_zone_col - 2, -1):
                if 0 <= wc < WORLD_W and wm[wr, wc]:
                    reached = True
                    break
            if not reached:
                for wc in range(wire_col - 1, left_zone_col - 2, -1):
                    if 0 <= wc < WORLD_W:
                        if wm[wr, wc]:
                            break
                        if em[wr, wc] and not pm[wr, wc]:
                            return (Tool.WIRE, wc, wr)
                        elif not em[wr, wc]:
                            break

    # --- Phase 6: Lateral wires toward right zone column ---
    for wr in wire_rows_on_spine:
        if target_min <= wr <= target_max:
            reached = False
            for wc in range(wire_col + 1, right_zone_col + 3):
                if 0 <= wc < WORLD_W and wm[wr, wc]:
                    reached = True
                    break
            if not reached:
                for wc in range(wire_col + 1, right_zone_col + 3):
                    if 0 <= wc < WORLD_W:
                        if wm[wr, wc]:
                            break
                        if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                            return (Tool.WIRE, wc, wr)
                        elif not em[wr, wc] and not rm[wr, wc]:
                            break

    # --- Phase 7: Road extensions to right zone column ---
    for rr in road_rows_on_col:
        if target_min <= rr <= target_max:
            for rc in range(road_col + 1, right_zone_col + 2):
                if 0 <= rc < WORLD_W:
                    if rm[rr, rc]:
                        break
                    if em[rr, rc] and not pm[rr, rc]:
                        return (Tool.ROAD, rc, rr)
                    elif not em[rr, rc]:
                        break

    # --- Phase 8: Place zones where powered and road-served ---
    for zr in zone_rows:
        wire_near_row = any(abs(zr - wr) <= 3 for wr in wire_rows_on_spine)
        road_near_row = any(abs(zr - rr) <= 3 for rr in road_rows_on_col)

        if wire_near_row and road_near_row:
            for zc in [left_zone_col, right_zone_col]:
                if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                    if wire_near(zr, zc, 6) and road_near(zr, zc, 5):
                        return (pick_tool(), zc, zr)

    # --- Phase 9: Second coal plant if many zones but low powered ---
    num_plant_tiles = int(np.sum(pm))
    if pop > 200 and num_plant_tiles < 9:
        # Check if we need more power by observing powered_zones vs total zones
        if powered < total_zones // 2 + 1 or pop > 400:
            px2 = plant_cx + 14
            py2 = plant_cy
            px2 = max(2, min(WORLD_W - 3, px2))
            py2 = max(2, min(WORLD_H - 3, py2))
            area_ok = True
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    rr, rc = py2 + dr, px2 + dc
                    if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                        area_ok = False
                    elif not em[rr, rc] and not pm[rr, rc]:
                        area_ok = False
            if area_ok:
                return (Tool.COALPOWER, px2, py2)

    # --- Phase 10: Horizontal roads connecting left and right at spine edges ---
    if pop > 80:
        for rr in [min_wire_row, max_wire_row]:
            if target_min <= rr <= target_max:
                for rc in range(left_zone_col - 1, right_zone_col + 2):
                    if 0 <= rc < WORLD_W and em[rr, rc] and not pm[rr, rc]:
                        return (Tool.ROAD, rc, rr)

    # --- Phase 11: Expand outer zone columns if growing ---
    if pop > 150:
        outer_left = left_zone_col - 5
        outer_right = right_zone_col + 5
        for zc in [outer_left, outer_right]:
            zc = max(3, min(WORLD_W - 4, zc))
            for zr in zone_rows:
                if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                    if wire_near(zr, zc, 7) and road_near(zr, zc, 6):
                        return (Tool.RESIDENTIAL, zc, zr)

    # --- Phase 12: Fill missing zones near infrastructure ---
    for zr in zone_rows:
        for zc_offset in [left_zone_col, wire_col - 8, right_zone_col, road_col + 8]:
            zc = max(3, min(WORLD_W - 4, zc_offset))
            if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                if wire_near(zr, zc, 8) and road_near(zr, zc, 7):
                    return (pick_tool(), zc, zr)

    # --- Phase 13: Wire spine to second plant if it exists ---
    if num_plant_tiles >= 18:
        plant_rows2, plant_cols2 = np.where(pm)
        # Find second plant cluster
        unique_cx = list(set(plant_cols2))
        if len(unique_cx) >= 2:
            cx2 = max(unique_cx)
            # Wire from wire_col toward cx2
            for wc in range(wire_col + 1, cx2):
                mid_r = cy
                if 0 <= mid_r < WORLD_H and em[mid_r, wc]:
                    return (Tool.WIRE, wc, mid_r)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map each step to find existing infrastructure
    - Extends wire/road/zones based on what's already there
    - More compact corridor with better zone/road/wire integration
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    all_zone_mask = resm | comm | indm
    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Phase 1: Place coal power plant if missing
    if not np.any(pm):
        # Place at left-center area
        px, py = cx - 15, cy
        return (Tool.COALPOWER, px, py)

    # Find plant centroid
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Define corridor layout relative to plant
    # Wire spine runs vertically, road runs parallel
    wire_col = plant_cx + 4
    road_col = wire_col + 2
    left_zone_col = wire_col - 3
    right_zone_col = road_col + 3

    wire_col = max(2, min(WORLD_W - 3, wire_col))
    road_col = max(2, min(WORLD_W - 3, road_col))
    left_zone_col = max(2, min(WORLD_W - 3, left_zone_col))
    right_zone_col = max(2, min(WORLD_W - 3, right_zone_col))

    # Scan current wire spine
    wire_rows_on_spine = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])
    road_rows_on_col = sorted([r for r in range(WORLD_H) if rm[r, road_col]])

    # Dynamic spine extent based on population
    if obs.city_pop < 50:
        spine_extent = 6
    elif obs.city_pop < 150:
        spine_extent = 10
    elif obs.city_pop < 350:
        spine_extent = 16
    elif obs.city_pop < 600:
        spine_extent = 22
    else:
        spine_extent = 30

    target_min = max(2, cy - spine_extent)
    target_max = min(WORLD_H - 3, cy + spine_extent)

    # Phase 2: Bootstrap wire adjacent to plant
    if not wire_rows_on_spine:
        # Find a cell adjacent to plant on the right side
        for dy in range(-2, 3):
            nr = plant_cy + dy
            if 0 <= nr < WORLD_H:
                # Check if we can place wire at wire_col connecting to plant
                if em[nr, wire_col] or wm[nr, wire_col]:
                    return (Tool.WIRE, wire_col, nr)
        # Fallback: place wire right next to plant
        return (Tool.WIRE, plant_cx + 2, plant_cy)

    min_wire_row = min(wire_rows_on_spine)
    max_wire_row = max(wire_rows_on_spine)

    # Phase 3: Connect wire spine to plant if gap exists
    # Check if wire at wire_col is connected to plant (adjacent columns)
    plant_connected = False
    for pc in range(plant_cx - 2, wire_col + 1):
        for pr in range(plant_cy - 2, plant_cy + 3):
            if 0 <= pr < WORLD_H and 0 <= pc < WORLD_W:
                if pm[pr, pc] or wm[pr, pc]:
                    # Check adjacency to wire_col
                    if abs(pc - wire_col) <= 1:
                        plant_connected = True

    if not plant_connected and wire_rows_on_spine:
        # Extend wire leftward from spine toward plant
        for wr in wire_rows_on_spine[:3]:
            for wc in range(wire_col - 1, plant_cx + 2, -1):
                if 0 <= wc < WORLD_W:
                    if pm[wr, wc] or wm[wr, wc]:
                        break  # connected
                    if em[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    else:
                        break

    # Phase 4: Extend wire spine downward
    if max_wire_row < target_max:
        nr = max_wire_row + 1
        if nr < WORLD_H and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Phase 5: Extend wire spine upward
    if min_wire_row > target_min:
        nr = min_wire_row - 1
        if nr >= 0 and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Phase 6: Build road column parallel to wire
    # Road connects at rows where wire exists
    for r in wire_rows_on_spine:
        if 0 <= r < WORLD_H and 0 <= road_col < WORLD_W:
            if not rm[r, road_col] and em[r, road_col] and not pm[r, road_col]:
                return (Tool.ROAD, road_col, r)

    # Helper functions
    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                # Allow empty or existing zone tiles only
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=4):
        r0, r1 = max(0, zr - radius), min(WORLD_H, zr + radius + 1)
        c0, c1 = max(0, zc - radius), min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=4):
        r0, r1 = max(0, zr - radius), min(WORLD_H, zr + radius + 1)
        c0, c1 = max(0, zc - radius), min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Phase 7: Place lateral wires to connect left zones to spine
    # Do this before placing zones so power is ready
    zone_rows = list(range(max(2, target_min), min(WORLD_H - 2, target_max + 1), 3))

    for wr in wire_rows_on_spine:
        # Only extend lateral wires at zone_rows intervals
        if wr not in zone_rows and (wr - 1) not in zone_rows and (wr + 1) not in zone_rows:
            continue
        # Extend wire leftward from spine toward left_zone_col + 1
        for wc in range(wire_col - 1, left_zone_col - 2, -1):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc] or pm[wr, wc]:
                    break
                if em[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                else:
                    break  # blocked

    # Phase 8: Place zones with road+wire access
    for zr in zone_rows:
        wire_near = any(abs(zr - wr) <= 3 for wr in wire_rows_on_spine)
        road_near = any(abs(zr - rr) <= 3 for rr in road_rows_on_col)

        if wire_near and road_near:
            # Left zone
            zc = left_zone_col
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc, 4) and has_road_nearby(zr, zc, 5):
                    return (pick_tool(), zc, zr)

            # Right zone  
            zc = right_zone_col
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_road_nearby(zr, zc, 4) and has_wire_nearby(zr, zc, 5):
                    return (pick_tool(), zc, zr)

    # Phase 9: Extend road to reach right zones
    for rr in wire_rows_on_spine:
        if not rm[rr, road_col]:
            continue
        for rc in range(road_col + 1, right_zone_col + 2):
            if 0 <= rc < WORLD_W:
                if rm[rr, rc]:
                    break
                if em[rr, rc] and not pm[rr, rc]:
                    return (Tool.ROAD, rc, rr)
                elif not em[rr, rc]:
                    break

    # Phase 10: Wire to power right zones
    for wr in wire_rows_on_spine:
        for wc in range(wire_col + 1, right_zone_col + 2):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc] or pm[wr, wc]:
                    break
                if rm[wr, wc]:
                    # Road doesn't carry power - place wire alongside
                    # Try row above/below
                    for nr in [wr - 1, wr + 1]:
                        if 0 <= nr < WORLD_H and em[nr, wc]:
                            return (Tool.WIRE, wc, nr)
                    break
                if em[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                else:
                    break

    # Phase 11: Second power plant if needed
    plant_count = int(np.sum(pm)) // 6  # roughly 6 tiles per plant footprint? Actually 4x4=16 but center matters
    plant_tile_count = int(np.sum(pm))
    if obs.city_pop > 300 and plant_tile_count < 20:
        # Place second plant adjacent to first, connected
        px2 = plant_cx + 10
        py2 = plant_cy
        if 2 <= py2 <= WORLD_H - 3 and 2 <= px2 <= WORLD_W - 3:
            if em[py2, px2]:
                return (Tool.COALPOWER, px2, py2)

    # Phase 12: Expand zone columns outward as population grows
    if obs.city_pop > 200:
        extra_cols = [left_zone_col - 4, right_zone_col + 4]
        for zc in extra_cols:
            if 2 <= zc <= WORLD_W - 3:
                for zr in zone_rows:
                    if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                        if has_road_nearby(zr, zc, 6) and has_wire_nearby(zr, zc, 7):
                            return (pick_tool(), zc, zr)

    # Phase 13: Add horizontal roads to improve zone access
    if obs.city_pop > 100 and road_rows_on_col:
        # Build horizontal road segment at center
        hr = cy
        for rc in range(left_zone_col - 1, right_zone_col + 2):
            if 0 <= rc < WORLD_W and em[hr, rc] and not pm[hr, rc] and not wm[hr, rc]:
                return (Tool.ROAD, rc, hr)

    # Phase 14: Place parks near zones to boost land value
    if obs.city_pop > 400:
        for zr in zone_rows:
            for zc in [left_zone_col + 2, right_zone_col - 2]:
                if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                    if em[zr, zc]:
                        return (Tool.PARK, zc, zr)

    return None

def act(obs, state):
    """
    Improved policy with:
    - Single dense neighborhood centered at (60, 50)
    - Grid road layout (horizontal + vertical roads every 6 tiles)
    - Coal plant placed first, then wires along roads, then zones
    - Better zone mix: 50% res, 25% com, 25% ind
    - More zones packed tightly around power+roads
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    all_zones = resm | comm | indm

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def area_free(cx, cy):
        if cx < 1 or cx > WORLD_W - 2 or cy < 1 or cy > WORLD_H - 2:
            return False
        for dy in [-1, 0, 1]:
            for dx in [-1, 0, 1]:
                r, c = cy + dy, cx + dx
                if not (0 <= r < WORLD_H and 0 <= c < WORLD_W):
                    return False
                if not em[r, c]:
                    return False
        return True

    def pick_zone():
        t = total_zones + 1
        if res_count / t < 0.50:
            return Tool.RESIDENTIAL
        elif com_count / t < 0.25:
            return Tool.COMMERCIAL
        elif ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def has_wire_near(cx, cy, radius=4):
        r0 = max(0, cy - radius)
        r1 = min(WORLD_H, cy + radius + 1)
        c0 = max(0, cx - radius)
        c1 = min(WORLD_W, cx + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_near(cx, cy, radius=3):
        r0 = max(0, cy - radius)
        r1 = min(WORLD_H, cy + radius + 1)
        c0 = max(0, cx - radius)
        c1 = min(WORLD_W, cx + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    # Center of our city grid
    cx0, cy0 = 60, 50

    # Phase 1: Place coal plant at (50, 50)
    plant_x, plant_y = 50, 50
    local_pm = pm[max(0, plant_y-5):min(WORLD_H, plant_y+6),
                  max(0, plant_x-5):min(WORLD_W, plant_x+6)]
    if not np.any(local_pm):
        if area_free(plant_x, plant_y):
            return (Tool.COALPOWER, plant_x, plant_y)
        # Try nearby
        for dy in range(-4, 5):
            for dx in range(-4, 5):
                npx, npy = plant_x + dx, plant_y + dy
                if area_free(npx, npy):
                    return (Tool.COALPOWER, npx, npy)

    # Find actual plant location
    plant_rows, plant_cols = np.where(pm)
    if len(plant_rows) > 0:
        actual_plant_cy = int(plant_rows[0])
        actual_plant_cx = int(plant_cols[0])
    else:
        actual_plant_cy, actual_plant_cx = plant_y, plant_x

    # Phase 2: Build a grid of roads
    # Horizontal roads at cy0-9, cy0-3, cy0+3, cy0+9
    # Vertical roads at cx0-12, cx0-6, cx0, cx0+6, cx0+12
    h_roads = [cy0 - 9, cy0 - 3, cy0 + 3, cy0 + 9]
    v_roads = [cx0 - 12, cx0 - 6, cx0, cx0 + 6, cx0 + 12]

    road_x_min = cx0 - 14
    road_x_max = cx0 + 14
    road_y_min = cy0 - 11
    road_y_max = cy0 + 11

    # Build horizontal roads first
    for ry in h_roads:
        if 0 < ry < WORLD_H:
            for rx in range(road_x_min, road_x_max + 1):
                if 0 <= rx < WORLD_W and em[ry, rx] and not pm[ry, rx]:
                    return (Tool.ROAD, rx, ry)

    # Build vertical roads
    for rx in v_roads:
        if 0 < rx < WORLD_W:
            for ry in range(road_y_min, road_y_max + 1):
                if 0 <= ry < WORLD_H and em[ry, rx] and not pm[ry, rx]:
                    return (Tool.ROAD, rx, ry)

    # Phase 3: Lay wires from plant to the road grid
    # Wire horizontally from plant to cx0
    wire_row = actual_plant_cy
    if actual_plant_cx < cx0:
        for wx in range(actual_plant_cx + 2, cx0 + 1):
            if 0 <= wx < WORLD_W and not wm[wire_row, wx] and not pm[wire_row, wx]:
                if em[wire_row, wx]:
                    return (Tool.WIRE, wx, wire_row)
                # Skip over roads
                elif rm[wire_row, wx]:
                    continue
                else:
                    break
    elif actual_plant_cx > cx0:
        for wx in range(actual_plant_cx - 2, cx0 - 1, -1):
            if 0 <= wx < WORLD_W and not wm[wire_row, wx] and not pm[wire_row, wx]:
                if em[wire_row, wx]:
                    return (Tool.WIRE, wx, wire_row)
                elif rm[wire_row, wx]:
                    continue
                else:
                    break

    # Wire along the vertical spine (cx0) from plant row to road grid
    spine_x = cx0
    wire_y_start = min(actual_plant_cy, road_y_min)
    wire_y_end = max(actual_plant_cy, road_y_max)
    for wy in range(wire_y_start, wire_y_end + 1):
        if 0 <= wy < WORLD_H and not wm[wy, spine_x] and not pm[wy, spine_x]:
            if em[wy, spine_x]:
                return (Tool.WIRE, spine_x, wy)

    # Wire along horizontal rows through road grid
    for wy in [cy0 - 6, cy0, cy0 + 6]:
        for wx in range(road_x_min, road_x_max + 1):
            if 0 <= wx < WORLD_W and 0 <= wy < WORLD_H:
                if not wm[wy, wx] and not pm[wy, wx] and em[wy, wx]:
                    return (Tool.WIRE, wx, wy)

    # Phase 4: Place zones in cells of the road grid
    # Zone centers are at midpoints between road lines
    # Between h_roads: cy0-9 and cy0-3 -> cy0-6
    # Between cy0-3 and cy0+3 -> cy0 (center row)
    # Between cy0+3 and cy0+9 -> cy0+6
    zone_ys = [cy0 - 6, cy0, cy0 + 6]
    # Between v_roads: at -9, -3, +3, +9 from cx0
    zone_xs = [cx0 - 9, cx0 - 3, cx0 + 3, cx0 + 9]

    for zy in zone_ys:
        for zx in zone_xs:
            if 1 <= zx <= WORLD_W - 2 and 1 <= zy <= WORLD_H - 2:
                if area_free(zx, zy):
                    if has_wire_near(zx, zy, 4) and has_road_near(zx, zy, 4):
                        return (pick_zone(), zx, zy)

    # Phase 5: Second coal plant if needed
    if pop > 200:
        all_pm = pm[max(0, cy0-15):min(WORLD_H, cy0+16),
                    max(0, cx0-20):min(WORLD_W, cx0+21)]
        plant_count = int(np.sum(all_pm)) // 9
        if plant_count < 2:
            for px2, py2 in [(cx0 + 20, cy0), (cx0 - 20, cy0)]:
                if area_free(px2, py2):
                    return (Tool.COALPOWER, px2, py2)

    # Phase 6: Additional zones in extended area
    if pop > 150:
        ext_zone_ys = [cy0 - 12, cy0 + 12]
        for zy in ext_zone_ys:
            for zx in zone_xs:
                if 1 <= zx <= WORLD_W - 2 and 1 <= zy <= WORLD_H - 2:
                    if area_free(zx, zy):
                        if has_wire_near(zx, zy, 5) and has_road_near(zx, zy, 5):
                            return (pick_zone(), zx, zy)

    # Phase 7: Police and fire stations
    if pop > 200:
        for sx, sy in [(cx0 - 15, cy0 - 6), (cx0 + 15, cy0 - 6)]:
            if 1 <= sx <= WORLD_W - 2 and 1 <= sy <= WORLD_H - 2:
                if area_free(sx, sy):
                    near = tm[max(0,sy-5):min(WORLD_H,sy+6), max(0,sx-5):min(WORLD_W,sx+6)]
                    if not np.any((near >= 600) & (near <= 750)):
                        return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        for sx, sy in [(cx0 - 15, cy0 + 6), (cx0 + 15, cy0 + 6)]:
            if 1 <= sx <= WORLD_W - 2 and 1 <= sy <= WORLD_H - 2:
                if area_free(sx, sy):
                    return (Tool.FIRESTATION, sx, sy)

    # Phase 8: Scan for any remaining empty spots near infrastructure
    for zy in range(road_y_min + 3, road_y_max - 2, 3):
        for zx in range(road_x_min + 3, road_x_max - 2, 3):
            if 1 <= zx <= WORLD_W - 2 and 1 <= zy <= WORLD_H - 2:
                if area_free(zx, zy):
                    if has_wire_near(zx, zy, 4) and has_road_near(zx, zy, 4):
                        # Check no zone too close
                        r0 = max(0, zy - 2); r1 = min(WORLD_H, zy + 3)
                        c0 = max(0, zx - 2); c1 = min(WORLD_W, zx + 3)
                        if not np.any(all_zones[r0:r1, c0:c1]):
                            return (pick_zone(), zx, zy)

    return None

def act(obs, state):
    """
    Improved policy: horizontal road spine with vertical zone branches.
    Uses a different layout than parent's vertical wire spine + vertical road.
    - Coal plant at left-center
    - Horizontal wire spine along a row
    - Horizontal road spine one row below
    - Zones placed above and below the road spine every 4 columns
    - Second cluster added earlier (pop >= 100)
    - Better zone mix: 2 res : 1 com : 1 ind ratio
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # Initialize state
    if 'phase' not in state:
        state['phase'] = 0
        state['wire_built'] = set()
        state['road_built'] = set()
        state['zones_placed'] = set()

    # Core layout: horizontal spines
    plant_cx, plant_cy = 20, 50  # plant on left side
    wire_row = 50   # horizontal wire spine row
    road_row = 52   # horizontal road spine row (2 below wire)

    # Zone rows above and below road
    zone_row_above = road_row - 4  # row 48
    zone_row_below = road_row + 4  # row 56

    # Horizontal extent
    x_start = plant_cx + 3   # start placing wire/road after plant
    x_end = 100              # extend rightward

    has_plant = np.any(pm)

    # Phase 1: Place coal power plant
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Collect current map state
    wire_cols_in_wire_row = set(c for (r, c) in zip(*np.where(wm)) if r == wire_row)
    road_cols_in_road_row = set(c for (r, c) in zip(*np.where(rm)) if r == road_row)
    res_positions = set(zip(*np.where(res_m))) if np.any(res_m) else set()
    com_positions = set(zip(*np.where(com_m))) if np.any(com_m) else set()
    ind_positions = set(zip(*np.where(ind_m))) if np.any(ind_m) else set()
    all_zones = res_positions | com_positions | ind_positions

    res_count = len(res_positions)
    com_count = len(com_positions)
    ind_count = len(ind_positions)

    # Dynamic horizontal extent based on population
    x_dynamic_end = min(x_end, x_start + 10 + min(60, obs.city_pop // 3))

    # Phase 2: Wire from plant to wire_row if needed
    # Connect plant vertically to wire_row
    if plant_cy != wire_row:
        for ry in range(min(plant_cy, wire_row), max(plant_cy, wire_row) + 1):
            if not wm[ry, plant_cx] and not pm[ry, plant_cx]:
                if em[ry, plant_cx]:
                    return (Tool.WIRE, plant_cx, ry)

    # Phase 3: Extend horizontal wire spine
    for xc in range(x_start, x_dynamic_end + 1):
        if xc not in wire_cols_in_wire_row:
            if 0 <= xc < WORLD_W and (em[wire_row, xc] or wm[wire_row, xc]):
                if em[wire_row, xc]:
                    return (Tool.WIRE, xc, wire_row)

    # Phase 4: Extend horizontal road spine
    for xc in range(x_start, x_dynamic_end + 1):
        if xc not in road_cols_in_road_row:
            if 0 <= xc < WORLD_W and em[road_row, xc]:
                return (Tool.ROAD, xc, road_row)

    # Helper: check if 3x3 area is clear
    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def already_zone_nearby(zr, zc):
        return any(abs(zr - pr) <= 1 and abs(zc - pc) <= 1 for (pr, pc) in all_zones)

    def pick_zone_type():
        # 2:1:1 ratio res:com:ind, but ensure all types present
        if res_count == 0:
            return Tool.RESIDENTIAL
        if ind_count == 0:
            return Tool.INDUSTRIAL
        if com_count == 0:
            return Tool.COMMERCIAL
        # ratio: 2 res : 1 com : 1 ind
        if ind_count * 2 < res_count:
            return Tool.INDUSTRIAL
        if com_count * 2 < res_count:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Phase 5: Place zones above and below road spine
    # Zones every 4 columns starting at x_start+2
    for xc in range(x_start + 2, x_dynamic_end - 1, 4):
        if xc < 2 or xc >= WORLD_W - 2:
            continue
        # Check road nearby (within 2 rows)
        road_close = xc in road_cols_in_road_row or (xc-1) in road_cols_in_road_row or (xc+1) in road_cols_in_road_row

        if not road_close:
            continue

        for zr in [zone_row_above, zone_row_below]:
            if 2 <= zr < WORLD_H - 2:
                if not already_zone_nearby(zr, xc) and zone_area_free(zr, xc):
                    return (pick_zone_type(), xc, zr)

    # Phase 6: Vertical wire connections from wire_row to zone columns
    # Place wire vertically to connect zones above/below to the spine
    for xc in range(x_start + 2, x_dynamic_end - 1, 4):
        if xc not in wire_cols_in_wire_row:
            continue
        # Wire down to zone_row_below area
        for ry in range(wire_row + 1, zone_row_below + 2):
            if ry >= WORLD_H:
                break
            if not wm[ry, xc] and not rm[ry, xc] and em[ry, xc]:
                return (Tool.WIRE, xc, ry)
        # Wire up to zone_row_above area
        for ry in range(wire_row - 1, zone_row_above - 2, -1):
            if ry < 0:
                break
            if not wm[ry, xc] and not rm[ry, xc] and em[ry, xc]:
                return (Tool.WIRE, xc, ry)

    # Phase 7: Second cluster (different rows) when pop >= 100
    if obs.city_pop >= 100:
        wire_row2 = 30
        road_row2 = 32
        zone_row2_above = 26
        zone_row2_below = 36

        wire_cols2 = set(c for (r, c) in zip(*np.where(wm)) if r == wire_row2)
        road_cols2 = set(c for (r, c) in zip(*np.where(rm)) if r == road_row2)

        # Connect first cluster to second cluster via vertical wire at x_start
        bridge_col = x_start
        for ry in range(min(wire_row, wire_row2), max(wire_row, wire_row2) + 1):
            if not wm[ry, bridge_col] and not pm[ry, bridge_col] and em[ry, bridge_col]:
                return (Tool.WIRE, bridge_col, ry)

        x_dynamic_end2 = min(x_end, x_start + 10 + min(60, (obs.city_pop - 100) // 3))

        # Wire spine 2
        for xc in range(x_start, x_dynamic_end2 + 1):
            if xc not in wire_cols2:
                if 0 <= xc < WORLD_W and em[wire_row2, xc]:
                    return (Tool.WIRE, xc, wire_row2)

        # Road spine 2
        for xc in range(x_start, x_dynamic_end2 + 1):
            if xc not in road_cols2:
                if 0 <= xc < WORLD_W and em[road_row2, xc]:
                    return (Tool.ROAD, xc, road_row2)

        # Zones for cluster 2
        for xc in range(x_start + 2, x_dynamic_end2 - 1, 4):
            if xc < 2 or xc >= WORLD_W - 2:
                continue
            road_close2 = xc in road_cols2 or (xc-1) in road_cols2 or (xc+1) in road_cols2
            if not road_close2:
                continue
            for zr in [zone_row2_above, zone_row2_below]:
                if 2 <= zr < WORLD_H - 2:
                    if not already_zone_nearby(zr, xc) and zone_area_free(zr, xc):
                        return (pick_zone_type(), xc, zr)

        # Vertical wires for cluster 2
        for xc in range(x_start + 2, x_dynamic_end2 - 1, 4):
            if xc not in wire_cols2:
                continue
            for ry in range(wire_row2 + 1, zone_row2_below + 2):
                if ry >= WORLD_H:
                    break
                if not wm[ry, xc] and not rm[ry, xc] and em[ry, xc]:
                    return (Tool.WIRE, xc, ry)
            for ry in range(wire_row2 - 1, zone_row2_above - 2, -1):
                if ry < 0:
                    break
                if not wm[ry, xc] and not rm[ry, xc] and em[ry, xc]:
                    return (Tool.WIRE, xc, ry)

    # Phase 8: Third cluster below when pop >= 300
    if obs.city_pop >= 300:
        wire_row3 = 68
        road_row3 = 70
        zone_row3_above = 64
        zone_row3_below = 74

        wire_cols3 = set(c for (r, c) in zip(*np.where(wm)) if r == wire_row3)
        road_cols3 = set(c for (r, c) in zip(*np.where(rm)) if r == road_row3)

        # Connect from wire_row down to wire_row3
        bridge_col3 = x_start
        for ry in range(wire_row + 1, wire_row3 + 1):
            if not wm[ry, bridge_col3] and not pm[ry, bridge_col3] and em[ry, bridge_col3]:
                return (Tool.WIRE, bridge_col3, ry)

        x_dynamic_end3 = min(x_end, x_start + 10 + min(60, (obs.city_pop - 300) // 3))

        for xc in range(x_start, x_dynamic_end3 + 1):
            if xc not in wire_cols3:
                if 0 <= xc < WORLD_W and em[wire_row3, xc]:
                    return (Tool.WIRE, xc, wire_row3)

        for xc in range(x_start, x_dynamic_end3 + 1):
            if xc not in road_cols3:
                if 0 <= xc < WORLD_W and em[road_row3, xc]:
                    return (Tool.ROAD, xc, road_row3)

        for xc in range(x_start + 2, x_dynamic_end3 - 1, 4):
            if xc < 2 or xc >= WORLD_W - 2:
                continue
            road_close3 = xc in road_cols3 or (xc-1) in road_cols3 or (xc+1) in road_cols3
            if not road_close3:
                continue
            for zr in [zone_row3_above, zone_row3_below]:
                if 2 <= zr < WORLD_H - 2:
                    if not already_zone_nearby(zr, xc) and zone_area_free(zr, xc):
                        return (pick_zone_type(), xc, zr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map every step to decide next action
    - Places coal plant, extends wire spine, builds roads, places zones
    - Uses multiple wire columns for wider coverage
    - Reactive: decisions based on observed map state
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    pop = obs.city_pop

    def pick_tool():
        if ind_count / total_zones < 0.20:
            return Tool.INDUSTRIAL
        if com_count / total_zones < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Phase 1: Place first coal plant if none ---
    if not np.any(pm):
        return (Tool.COALPOWER, 55, 50)

    # Find plant centroid
    plant_ys, plant_xs = np.where(pm)
    px = int(np.median(plant_xs))
    py = int(np.median(plant_ys))

    # Use TWO wire columns flanking plant, roads outside those
    wire_col_r = px + 4
    wire_col_l = px - 4
    wire_col_r = max(4, min(WORLD_W - 5, wire_col_r))
    wire_col_l = max(4, min(WORLD_W - 5, wire_col_l))

    road_col_rr = wire_col_r + 2
    road_col_ll = wire_col_l - 2
    road_col_rr = max(4, min(WORLD_W - 5, road_col_rr))
    road_col_ll = max(4, min(WORLD_W - 5, road_col_ll))

    # Spine extent based on pop
    if pop < 50:
        spine_half = 10
    elif pop < 150:
        spine_half = 16
    elif pop < 400:
        spine_half = 22
    elif pop < 800:
        spine_half = 28
    else:
        spine_half = 35

    target_min = max(2, py - spine_half)
    target_max = min(WORLD_H - 3, py + spine_half)

    # --- Phase 2: Bootstrap wire adjacent to plant (both columns) ---
    for wire_col in [wire_col_r, wire_col_l]:
        wire_rows = [r for r in range(WORLD_H) if wm[r, wire_col]]
        if not wire_rows:
            # Place first wire near plant row
            for dy in range(-2, 3):
                nr = py + dy
                if in_bounds(wire_col, nr) and not pm[nr, wire_col]:
                    if em[nr, wire_col] or wm[nr, wire_col]:
                        return (Tool.WIRE, wire_col, nr)

    # --- Phase 3: Extend wire spines ---
    for wire_col in [wire_col_r, wire_col_l]:
        wire_rows = [r for r in range(WORLD_H) if wm[r, wire_col]]
        if not wire_rows:
            continue
        min_wr = min(wire_rows)
        max_wr = max(wire_rows)
        if max_wr < target_max:
            nr = max_wr + 1
            if in_bounds(wire_col, nr) and not pm[nr, wire_col] and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        if min_wr > target_min:
            nr = min_wr - 1
            if in_bounds(wire_col, nr) and not pm[nr, wire_col] and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    # Gather all wire rows (both columns)
    all_wire_rows_r = [r for r in range(WORLD_H) if wm[r, wire_col_r]]
    all_wire_rows_l = [r for r in range(WORLD_H) if wm[r, wire_col_l]]

    # --- Phase 4: Build road columns ---
    for wr in all_wire_rows_r:
        if target_min <= wr <= target_max:
            if in_bounds(road_col_rr, wr) and em[wr, road_col_rr]:
                return (Tool.ROAD, road_col_rr, wr)
    for wr in all_wire_rows_l:
        if target_min <= wr <= target_max:
            if in_bounds(road_col_ll, wr) and em[wr, road_col_ll]:
                return (Tool.ROAD, road_col_ll, wr)

    # Also add road columns between wire columns (centered)
    road_col_mid = px
    road_col_mid = max(4, min(WORLD_W - 5, road_col_mid))
    combined_wire_rows = set(all_wire_rows_r) | set(all_wire_rows_l)
    for wr in sorted(combined_wire_rows):
        if target_min <= wr <= target_max:
            if in_bounds(road_col_mid, wr) and em[wr, road_col_mid]:
                return (Tool.ROAD, road_col_mid, wr)

    # --- Build proximity masks ---
    def make_nbr_mask(src_mask, radius=2):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-radius, radius + 1):
            for dx in range(-radius, radius + 1):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                result[r0:r1, c0:c1] |= src_mask[sr0:sr1, sc0:sc1]
        return result

    nbr_road = make_nbr_mask(rm, 2)
    nbr_wire = make_nbr_mask(wm | pm, 2)
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and not zone_tiles[nr, nc]:
                    return False
        return True

    # --- Phase 5: Place zones near wire+road coverage ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prioritize candidates close to either wire column
        dist_r = np.abs(cxs - wire_col_r)
        dist_l = np.abs(cxs - wire_col_l)
        dists = np.minimum(dist_r, dist_l)
        order = np.argsort(dists)
        step_off = int(obs.step * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 100:
                break

    # --- Phase 6: Extend roads from existing roads near wire ---
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 30)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx]:
                    if nbr_wire[ny, nx]:
                        return (Tool.ROAD, nx, ny)

    # --- Phase 7: Second coal plant when growing ---
    num_plant_tiles = int(np.sum(pm))
    if pop > 150 and num_plant_tiles < 18:
        # Place second plant to the left of existing cluster
        p2x = px - 20
        p2y = py
        p2x = max(3, min(WORLD_W - 4, p2x))
        p2y = max(3, min(WORLD_H - 4, p2y))
        area_ok = True
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = p2y + dr, p2x + dc
                if not in_bounds(rc, rr) or (not em[rr, rc] and not pm[rr, rc]):
                    area_ok = False
                    break
        if area_ok:
            return (Tool.COALPOWER, p2x, p2y)
        # Wire horizontal bridge to second plant area
        for wc in range(p2x + 1, wire_col_l):
            if in_bounds(wc, py) and em[py, wc]:
                return (Tool.WIRE, wc, py)

    # --- Phase 8: Third coal plant to the right when pop is high ---
    if pop > 400 and num_plant_tiles < 27:
        p3x = px + 20
        p3y = py
        p3x = max(3, min(WORLD_W - 4, p3x))
        p3y = max(3, min(WORLD_H - 4, p3y))
        area_ok = True
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = p3y + dr, p3x + dc
                if not in_bounds(rc, rr) or (not em[rr, rc] and not pm[rr, rc]):
                    area_ok = False
                    break
        if area_ok:
            return (Tool.COALPOWER, p3x, p3y)
        for wc in range(wire_col_r + 1, p3x):
            if in_bounds(wc, py) and em[py, wc]:
                return (Tool.WIRE, wc, py)

    # --- Phase 9: Services when pop is high enough ---
    if pop > 100:
        fsx, fsy = px - 10, py - 12
        fsx = max(1, min(WORLD_W - 2, fsx))
        fsy = max(1, min(WORLD_H - 2, fsy))
        if in_bounds(fsx, fsy) and em[fsy, fsx]:
            return (Tool.FIRESTATION, fsx, fsy)
        psx, psy = px + 10, py + 12
        psx = max(1, min(WORLD_W - 2, psx))
        psy = max(1, min(WORLD_H - 2, psy))
        if in_bounds(psx, psy) and em[psy, psx]:
            return (Tool.POLICESTATION, psx, psy)

    # --- Phase 10: Extend wire from existing wire into empty areas ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 20)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            # Prefer extending vertically along spine columns
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = wx + dx2, wy + dy2
                if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                    return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy v3:
    - Reads tile_map every step
    - Builds a compact grid: power plant -> wire spine -> roads -> zones
    - Fully reactive: each decision based on current map state
    - Improved: denser zone placement, better power extension, fire/police earlier
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Step 0: Place first coal plant if missing ---
    if not np.any(pm):
        return (Tool.COALPOWER, 60, 50)

    # Find plant centroid
    plant_ys, plant_xs = np.where(pm)
    px = int(np.median(plant_xs))
    py = int(np.median(plant_ys))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def expand_mask(base, radius=2):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-radius, radius+1):
            for dx in range(-radius, radius+1):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                result[r0:r1, c0:c1] |= base[sr0:sr1, sc0:sc1]
        return result

    nbr_road = expand_mask(rm, 2)
    power_src = wm | pm
    nbr_wire = expand_mask(power_src, 2)
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and not zone_tiles[nr, nc]:
                    return False
        return True

    # Wire spines: vertical at px+2, horizontal at py
    wire_col = px + 2
    wire_row = py

    pop_factor = min(40, obs.city_pop // 15)
    y_extent = 15 + pop_factor
    x_extent = 15 + pop_factor

    tmin = max(3, py - y_extent)
    tmax = min(WORLD_H - 4, py + y_extent)
    lmin = max(3, px - x_extent)
    lmax = min(WORLD_W - 4, px + x_extent)

    # --- Step 1: Grow vertical wire spine ---
    wire_in_col = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])
    if not wire_in_col:
        for dy in range(-2, 3):
            ny = py + dy
            if in_bounds(wire_col, ny) and (em[ny, wire_col] or wm[ny, wire_col]) and not pm[ny, wire_col]:
                return (Tool.WIRE, wire_col, ny)
    else:
        min_wr = wire_in_col[0]
        max_wr = wire_in_col[-1]
        if max_wr < tmax:
            nr = max_wr + 1
            if in_bounds(wire_col, nr) and (em[nr, wire_col] or wm[nr, wire_col]) and not pm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)
        if min_wr > tmin:
            nr = min_wr - 1
            if in_bounds(wire_col, nr) and (em[nr, wire_col] or wm[nr, wire_col]) and not pm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    wire_in_col = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])

    # --- Step 2: Grow horizontal wire spine ---
    wire_in_row = sorted([c for c in range(WORLD_W) if wm[wire_row, c]])
    if not wire_in_row and wire_in_col:
        for dc in [1, -1]:
            nc = wire_col + dc
            if in_bounds(nc, wire_row) and (em[wire_row, nc] or wm[wire_row, nc]) and not pm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)
    elif wire_in_row:
        min_wc = wire_in_row[0]
        max_wc = wire_in_row[-1]
        if max_wc < lmax:
            nc = max_wc + 1
            if in_bounds(nc, wire_row) and (em[wire_row, nc] or wm[wire_row, nc]) and not pm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)
        if min_wc > lmin:
            nc = min_wc - 1
            if in_bounds(nc, wire_row) and (em[wire_row, nc] or wm[wire_row, nc]) and not pm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    wire_in_row = sorted([c for c in range(WORLD_W) if wm[wire_row, c]])

    # --- Step 3: Roads adjacent to vertical wire spine ---
    for wr in wire_in_col:
        for road_col in [wire_col + 1, wire_col - 1]:
            if in_bounds(road_col, wr) and em[wr, road_col] and not pm[wr, road_col]:
                return (Tool.ROAD, road_col, wr)

    # Roads adjacent to horizontal wire spine
    for wc in wire_in_row:
        for road_row in [wire_row - 1, wire_row + 1]:
            if in_bounds(wc, road_row) and em[road_row, wc] and not pm[road_row, wc] and not wm[road_row, wc]:
                return (Tool.ROAD, wc, road_row)

    # --- Step 4: Add cross-roads every 6 tiles to improve zone coverage ---
    # Horizontal roads at intervals off the vertical spine
    for spacing in [6, 12, 18, 24]:
        for row_offset in [spacing, -spacing]:
            cross_row = wire_row + row_offset
            if tmin <= cross_row <= tmax:
                # Build road along this row near wire coverage
                for c in range(max(2, lmin), min(WORLD_W-2, lmax+1)):
                    if em[cross_row, c] and not pm[cross_row, c] and not wm[cross_row, c]:
                        # Only if near wire column or existing road
                        if abs(c - wire_col) < x_extent:
                            return (Tool.ROAD, c, cross_row)
        for col_offset in [spacing, -spacing]:
            cross_col = wire_col + col_offset
            if lmin <= cross_col <= lmax:
                for r in range(max(2, tmin), min(WORLD_H-2, tmax+1)):
                    if em[r, cross_col] and not pm[r, cross_col] and not wm[r, cross_col]:
                        if abs(r - wire_row) < y_extent:
                            return (Tool.ROAD, cross_col, r)

    # --- Step 5: Place zones where road+wire coverage exists ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        dist_v = np.abs(cxs - wire_col)
        dist_h = np.abs(cys - wire_row)
        scores = dist_v + dist_h
        order = np.argsort(scores)
        step_off = int(obs.step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 80:
                break

    # --- Step 6: Extend roads from existing roads near wire ---
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 30)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx]:
                    if nbr_wire[ny, nx]:
                        return (Tool.ROAD, nx, ny)

    # --- Step 7: Services earlier and more aggressively ---
    if obs.city_pop > 80:
        fsx, fsy = px - 8, py - 8
        fsx = max(1, min(WORLD_W - 2, fsx))
        fsy = max(1, min(WORLD_H - 2, fsy))
        if em[fsy, fsx]:
            return (Tool.FIRESTATION, fsx, fsy)
        psx, psy = px - 8, py + 8
        psx = max(1, min(WORLD_W - 2, psx))
        psy = max(1, min(WORLD_H - 2, psy))
        if em[psy, psx]:
            return (Tool.POLICESTATION, psx, psy)
        # Second fire station
        if obs.city_pop > 300:
            fsx2, fsy2 = px + 12, py - 8
            fsx2 = max(1, min(WORLD_W - 2, fsx2))
            fsy2 = max(1, min(WORLD_H - 2, fsy2))
            if em[fsy2, fsx2]:
                return (Tool.FIRESTATION, fsx2, fsy2)

    # --- Step 8: Second/third power plant as city grows ---
    if total_zones > 8 or obs.city_pop > 200:
        for attempt_idx, (off_x, off_y) in enumerate([(20, -20), (-20, 15), (0, 25)]):
            p2x = max(3, min(WORLD_W - 5, px + off_x))
            p2y = max(3, min(WORLD_H - 5, py + off_y))
            nearby = any(
                in_bounds(p2x + dx, p2y + dy) and pm[p2y + dy, p2x + dx]
                for dy in range(-8, 9) for dx in range(-8, 9)
            )
            if not nearby and em[p2y, p2x]:
                return (Tool.COALPOWER, p2x, p2y)
            # Wire to connect second plant toward main spine
            if not nearby:
                # try to extend wire horizontally toward new plant
                for wc in range(min(wire_col + 2, p2x - 1), max(wire_col + 2, p2x)):
                    yr = wire_row
                    if in_bounds(wc, yr) and (em[yr, wc] or wm[yr, wc]) and not pm[yr, wc]:
                        return (Tool.WIRE, wc, yr)

    # --- Step 9: Extend wire frontier from existing wires ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 20)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = wx + dx2, wy + dy2
                if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                    return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Redesigned policy: horizontal layout with multiple power plants,
    road grid, and aggressive zone placement.
    Key differences from parent:
    1. Uses a horizontal road/wire layout instead of vertical
    2. Places power plant in top-left area, zones spread rightward
    3. Uses a grid of horizontal roads connected by vertical roads
    4. Places zones systematically in grid cells
    5. Better power connectivity via wire grid
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    all_zone = resm | comm | indm

    pop = obs.city_pop

    # Initialize state
    if 'phase' not in state:
        state['phase'] = 0
        state['plan'] = []
        state['plan_idx'] = 0

    def pick_tool():
        res = int(np.sum(resm))
        com = int(np.sum(comm))
        ind = int(np.sum(indm))
        t = max(res + com + ind, 1)
        if com / t < 0.25:
            return Tool.COMMERCIAL
        if ind / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone[rr, rc]:
                    return False
        return True

    def near(arr, r, c, radius=3):
        r0 = max(0, r - radius); r1 = min(WORLD_H, r + radius + 1)
        c0 = max(0, c - radius); c1 = min(WORLD_W, c + radius + 1)
        return np.any(arr[r0:r1, c0:c1])

    # Layout parameters: build in left-center region
    # Power plant at (20, 30), then wire/road grid expanding right
    px, py = 20, 30   # power plant center

    # --- Phase 1: Place coal power plant ---
    if not np.any(pm):
        return (Tool.COALPOWER, px, py)

    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Grid layout:
    # Two horizontal road rows: road_row1 = plant_cy - 5, road_row2 = plant_cy + 5
    # Wire runs along: wire_row = plant_cy (horizontal from plant rightward)
    # Vertical road at intervals connecting horizontal roads
    # Zones placed in grid cells

    wire_row = plant_cy
    road_row1 = plant_cy - 5
    road_row2 = plant_cy + 5

    road_row1 = max(2, min(WORLD_H - 3, road_row1))
    road_row2 = max(2, min(WORLD_H - 3, road_row2))
    wire_row  = max(2, min(WORLD_H - 3, wire_row))

    # How far right to extend based on pop
    if pop < 50:
        x_max = plant_cx + 15
    elif pop < 200:
        x_max = plant_cx + 30
    elif pop < 500:
        x_max = plant_cx + 50
    else:
        x_max = plant_cx + 70
    x_max = min(WORLD_W - 3, x_max)
    x_start = plant_cx + 2  # start wire/road just right of plant

    # --- Phase 2: Extend wire rightward from plant ---
    for wc in range(x_start, x_max + 1):
        if 0 <= wc < WORLD_W:
            if not wm[wire_row, wc] and not pm[wire_row, wc]:
                if em[wire_row, wc]:
                    return (Tool.WIRE, wc, wire_row)
                # blocked, try to continue
            # once blocked by non-wire non-empty, stop this scan

    # --- Phase 3: Build road_row1 (upper road) ---
    for rc in range(x_start, x_max + 1):
        if 0 <= rc < WORLD_W:
            if not rm[road_row1, rc] and not pm[road_row1, rc]:
                if em[road_row1, rc]:
                    return (Tool.ROAD, rc, road_row1)

    # --- Phase 4: Build road_row2 (lower road) ---
    for rc in range(x_start, x_max + 1):
        if 0 <= rc < WORLD_W:
            if not rm[road_row2, rc] and not pm[road_row2, rc]:
                if em[road_row2, rc]:
                    return (Tool.ROAD, rc, road_row2)

    # --- Phase 5: Vertical roads connecting road_row1 to road_row2 at intervals ---
    vert_road_cols = list(range(x_start + 3, x_max + 1, 8))
    for vc in vert_road_cols:
        if 0 <= vc < WORLD_W:
            for vr in range(road_row1, road_row2 + 1):
                if 0 <= vr < WORLD_H:
                    if not rm[vr, vc] and em[vr, vc] and not pm[vr, vc]:
                        return (Tool.ROAD, vc, vr)

    # --- Phase 6: Wire branches to road rows for power ---
    # Extend wire downward from wire_row to road_row1 and road_row2 at vert_road_cols
    for vc in vert_road_cols:
        if 0 <= vc < WORLD_W:
            # upward to road_row1
            for vr in range(wire_row - 1, road_row1 - 1, -1):
                if 0 <= vr < WORLD_H:
                    if not wm[vr, vc] and not rm[vr, vc] and em[vr, vc] and not pm[vr, vc]:
                        return (Tool.WIRE, vc, vr)
            # downward to road_row2
            for vr in range(wire_row + 1, road_row2 + 1):
                if 0 <= vr < WORLD_H:
                    if not wm[vr, vc] and not rm[vr, vc] and em[vr, vc] and not pm[vr, vc]:
                        return (Tool.WIRE, vc, vr)

    # --- Phase 7: Place zones in grid cells ---
    # Zone centers: between road rows, between vertical road cols
    # Upper zones: row = road_row1 - 3 (above upper road)
    # Middle zones: row = (road_row1 + road_row2) // 2
    # Lower zones: row = road_row2 + 3 (below lower road)

    zone_rows_list = [road_row1 - 3, (road_row1 + road_row2) // 2, road_row2 + 3]
    zone_col_starts = list(range(x_start + 2, x_max, 4))

    for zr in zone_rows_list:
        zr = max(2, min(WORLD_H - 3, zr))
        for zc in zone_col_starts:
            zc = max(2, min(WORLD_W - 3, zc))
            if not near(all_zone, zr, zc, 2) and zone_area_ok(zr, zc):
                if near(wm, zr, zc, 5) or near(pm, zr, zc, 5):
                    if near(rm, zr, zc, 4):
                        return (pick_tool(), zc, zr)

    # --- Phase 8: Second power plant when pop grows ---
    plant_count = max(1, int(np.sum(pm)) // 6)
    if pop > 200 and plant_count < 2:
        px2 = plant_cx + 40
        py2 = plant_cy
        px2 = max(2, min(WORLD_W - 4, px2))
        py2 = max(2, min(WORLD_H - 4, py2))
        area_ok = all(
            em[py2 + dr, px2 + dc]
            for dr in [-1, 0, 1] for dc in [-1, 0, 1]
            if 0 <= py2 + dr < WORLD_H and 0 <= px2 + dc < WORLD_W
        )
        if area_ok:
            return (Tool.COALPOWER, px2, py2)

    # --- Phase 9: Extend layout further right if pop growing ---
    if pop > 300:
        new_x_max = min(WORLD_W - 3, x_max + 20)
        for wc in range(x_max + 1, new_x_max + 1):
            if 0 <= wc < WORLD_W and em[wire_row, wc] and not pm[wire_row, wc]:
                return (Tool.WIRE, wc, wire_row)
        for rc in range(x_max + 1, new_x_max + 1):
            if 0 <= rc < WORLD_W and em[road_row1, rc] and not pm[road_row1, rc]:
                return (Tool.ROAD, rc, road_row1)
        for rc in range(x_max + 1, new_x_max + 1):
            if 0 <= rc < WORLD_W and em[road_row2, rc] and not pm[road_row2, rc]:
                return (Tool.ROAD, rc, road_row2)

    # --- Phase 10: Add second neighborhood band above/below ---
    if pop > 150:
        # Upper band
        road_row3 = road_row1 - 10
        road_row3 = max(2, min(WORLD_H - 3, road_row3))
        for rc in range(x_start, min(x_max, plant_cx + 35) + 1):
            if 0 <= rc < WORLD_W and em[road_row3, rc] and not pm[road_row3, rc]:
                return (Tool.ROAD, rc, road_row3)
        # Wire along this band
        wire_row3 = road_row3 - 2
        wire_row3 = max(2, min(WORLD_H - 3, wire_row3))
        for wc in range(x_start, min(x_max, plant_cx + 35) + 1):
            if 0 <= wc < WORLD_W and em[wire_row3, wc] and not pm[wire_row3, wc]:
                return (Tool.WIRE, wc, wire_row3)
        # Connect wire_row3 to main wire
        for vc in vert_road_cols[:3]:
            if 0 <= vc < WORLD_W:
                for vr in range(wire_row3, wire_row):
                    if 0 <= vr < WORLD_H and em[vr, vc] and not pm[vr, vc]:
                        return (Tool.WIRE, vc, vr)
        # Zones above upper band
        for zc in range(x_start + 2, min(x_max, plant_cx + 35), 4):
            zr2 = road_row3 - 3
            zr2 = max(2, min(WORLD_H - 3, zr2))
            zc2 = max(2, min(WORLD_W - 3, zc))
            if not near(all_zone, zr2, zc2, 2) and zone_area_ok(zr2, zc2):
                if near(wm, zr2, zc2, 6) and near(rm, zr2, zc2, 5):
                    return (pick_tool(), zc2, zr2)

    # --- Phase 11: Dense fill pass ---
    if pop > 100:
        for zr in range(road_row1 - 6, road_row2 + 7, 3):
            zr = max(2, min(WORLD_H - 3, zr))
            for zc in range(x_start, x_max, 3):
                zc = max(2, min(WORLD_W - 3, zc))
                if not near(all_zone, zr, zc, 1) and zone_area_ok(zr, zc):
                    if (near(wm, zr, zc, 5) or near(pm, zr, zc, 5)) and near(rm, zr, zc, 4):
                        return (pick_tool(), zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map each step and decides next action
    based on what's actually present on the map.

    Strategy:
    - Phase 0: Place coal power plant
    - Phase 1: Extend wire from plant outward
    - Phase 2: Place roads along wire path
    - Phase 3: Place zones adjacent to roads+wires
    - Phase 4: Add more infrastructure as city grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    step = obs.step

    # Light state: just phase counter and a small counter
    if 'phase' not in state:
        state['phase'] = 0
        state['substep'] = 0
        state['plant_placed'] = False
        state['plant2_placed'] = False

    # Helper: check if tile is in bounds
    def inb(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Helper: count neighbors of a type
    def has_neighbor(x, y, mask, dist=1):
        for dy in range(-dist, dist+1):
            for dx in range(-dist, dist+1):
                nx, ny = x+dx, y+dy
                if inb(nx, ny) and mask[ny, nx]:
                    return True
        return False

    # Helper: find frontier of wire (empty cells adjacent to wire or plant)
    def wire_frontier():
        """Find empty cells adjacent to existing wire/plant."""
        result = []
        # Use plant_mask and wire_mask combined
        powered = wm | pm
        for y in range(WORLD_H):
            for x in range(WORLD_W):
                if em[y, x]:
                    # Check if adjacent to powered cell
                    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
                        ny, nx = y+dy, x+dx
                        if inb(nx, ny) and powered[ny, nx]:
                            result.append((x, y))
                            break
        return result

    # Helper: find good zone placements (3x3 area empty, near road and wire)
    def find_zone_spot(tool_preference=None):
        """Find a 3x3 empty area adjacent to road and wire."""
        # Scan systematically
        best = None
        for y in range(2, WORLD_H-2):
            for x in range(2, WORLD_W-2):
                # Check 3x3 clear
                clear = True
                for dy in range(-1, 2):
                    for dx in range(-1, 2):
                        if not em[y+dy, x+dx]:
                            clear = False
                            break
                    if not clear:
                        break
                if not clear:
                    continue
                # Check road within 2
                road_near = has_neighbor(x, y, rm, dist=2)
                # Check wire within 2
                wire_near = has_neighbor(x, y, wm | pm, dist=2)
                if road_near and wire_near:
                    return (x, y)
        return None

    # Count existing infrastructure
    n_plants = int(np.sum(pm))
    n_wires = int(np.sum(wm))
    n_roads = int(np.sum(rm))

    # Count zones
    n_res = int(np.sum(res_mask(tm)))
    n_com = int(np.sum(com_mask(tm)))
    n_ind = int(np.sum(ind_mask(tm)))
    n_zones = n_res + n_com + n_ind

    # === PHASE 0: Place first coal plant ===
    if n_plants == 0:
        # Place plant at a fixed good location
        px, py = 20, 50
        return (Tool.COALPOWER, px, py)

    # === PHASE 1: Build wire spine from plant ===
    # Extend wire rightward from plant area
    # Find rightmost wire x in a band around y=50
    plant_region_y = 50

    # Find the power plant location
    plant_locs = list(zip(*np.where(pm)))
    if plant_locs:
        ply, plx = plant_locs[0]
    else:
        ply, plx = 50, 20

    # If not enough wire, extend it
    if n_wires < 60:
        # Extend wire horizontally from plant toward right
        # Find rightmost wire near y=ply
        rightmost_wx = plx
        for wx in range(WORLD_W):
            if inb(wx, ply) and wm[ply, wx]:
                rightmost_wx = max(rightmost_wx, wx)
            # Also check ply+1, ply-1
            for dy in [-1, 0, 1]:
                if inb(wx, ply+dy) and wm[ply+dy, wx]:
                    rightmost_wx = max(rightmost_wx, wx)

        # Also extend vertically (wire spine)
        # Try to place wire to the right of rightmost
        target_wx = rightmost_wx + 1
        target_wy = ply

        # Make sure we're not overwriting plant
        if inb(target_wx, target_wy) and em[target_wy, target_wx]:
            return (Tool.WIRE, target_wx, target_wy)
        elif inb(target_wx, target_wy) and not pm[target_wy, target_wx]:
            # Not plant, try adjacent
            for dy in [-1, 1]:
                if inb(target_wx, target_wy+dy) and em[target_wy+dy, target_wx]:
                    return (Tool.WIRE, target_wx, target_wy+dy)

        # Try extending vertically if horizontal blocked
        for wy in range(max(0, ply-20), min(WORLD_H, ply+20)):
            if inb(rightmost_wx, wy) and em[wy, rightmost_wx]:
                if has_neighbor(rightmost_wx, wy, wm | pm, dist=1):
                    return (Tool.WIRE, rightmost_wx, wy)

    # === PHASE 2: Build roads alongside wires ===
    if n_roads < 40:
        # Place roads parallel to and near wire spine
        # Find wire cells and place road 2 tiles below
        wire_ys, wire_xs = np.where(wm)
        if len(wire_xs) > 0:
            # Road row: 2 below wire spine
            road_y = int(np.median(wire_ys)) + 3
            road_y = min(road_y, WORLD_H - 3)

            # Find range of wire x
            min_wx = int(wire_xs.min())
            max_wx = int(wire_xs.max())

            # Place road from min_wx to max_wx at road_y
            for rx in range(min_wx, max_wx + 1):
                if inb(rx, road_y) and not rm[road_y, rx]:
                    return (Tool.ROAD, rx, road_y)

            # Also place a road above wire
            road_y2 = int(np.median(wire_ys)) - 3
            road_y2 = max(road_y2, 2)
            for rx in range(min_wx, max_wx + 1):
                if inb(rx, road_y2) and not rm[road_y2, rx]:
                    return (Tool.ROAD, rx, road_y2)

    # === PHASE 3: Place zones near roads and wires ===
    # Determine what zone to place based on ratio
    total_z = n_res + n_com + n_ind + 1

    if n_res / total_z < 0.5:
        preferred_tool = Tool.RESIDENTIAL
    elif n_com / total_z < 0.25:
        preferred_tool = Tool.COMMERCIAL
    else:
        preferred_tool = Tool.INDUSTRIAL

    # Find zone spot reactively
    spot = find_zone_spot()
    if spot:
        zx, zy = spot
        return (preferred_tool, zx, zy)

    # === PHASE 4: Add second power plant if needed ===
    if n_plants < 2 and n_zones > 5:
        # Find empty 3x3 area far from first plant
        for py2 in range(10, WORLD_H-10, 5):
            for px2 in range(70, WORLD_W-10, 5):
                clear = True
                for dy in range(-1, 2):
                    for dx in range(-1, 2):
                        if not inb(px2+dx, py2+dy) or not em[py2+dy, px2+dx]:
                            clear = False
                            break
                    if not clear:
                        break
                if clear:
                    state['plant2_placed'] = True
                    return (Tool.COALPOWER, px2, py2)

    # === PHASE 5: Extend wire to second plant and new areas ===
    if n_plants >= 2:
        # Connect plants with wire
        plant_locs2 = list(zip(*np.where(pm)))
        if len(plant_locs2) >= 2:
            p1y, p1x = plant_locs2[0]
            p2y, p2x = plant_locs2[1]
            # Extend wire from p1 toward p2
            if p1x < p2x:
                for wx in range(p1x, p2x+1):
                    if inb(wx, p1y) and em[p1y, wx]:
                        return (Tool.WIRE, wx, p1y)
            # Also extend roads
            road_y = p1y + 3
            if inb(p1x, road_y):
                for rx in range(p1x, p2x+1):
                    if inb(rx, road_y) and not rm[road_y, rx]:
                        return (Tool.ROAD, rx, road_y)

    # === PHASE 6: More zones if we have roads/wires ===
    # Reactively scan for any zone opportunity
    for y in range(5, WORLD_H-5, 3):
        for x in range(5, WORLD_W-5, 3):
            clear = True
            for dy in range(-1, 2):
                for dx in range(-1, 2):
                    if not inb(x+dx, y+dy) or not em[y+dy, x+dx]:
                        clear = False
                        break
                if not clear:
                    break
            if not clear:
                continue
            road_near = has_neighbor(x, y, rm, dist=3)
            wire_near = has_neighbor(x, y, wm | pm, dist=3)
            if road_near and wire_near:
                # Place based on what's needed
                total_z2 = n_res + n_com + n_ind + 1
                if n_res / total_z2 < 0.5:
                    return (Tool.RESIDENTIAL, x, y)
                elif n_com / total_z2 < 0.3:
                    return (Tool.COMMERCIAL, x, y)
                else:
                    return (Tool.INDUSTRIAL, x, y)

    # === FALLBACK: Extend wire further ===
    # Find any wire cell and extend from its frontier
    frontier = wire_frontier()
    if frontier:
        # Pick frontier cell closest to center
        cx, cy = WORLD_W // 2, WORLD_H // 2
        frontier.sort(key=lambda p: abs(p[0]-cx) + abs(p[1]-cy))
        fx, fy = frontier[0]
        return (Tool.WIRE, fx, fy)

    # Last resort: extend road
    wire_ys2, wire_xs2 = np.where(wm)
    if len(wire_xs2) > 0:
        mid_x = int(np.median(wire_xs2))
        mid_y = int(np.median(wire_ys2))
        for dy in range(-5, 6):
            for dx in range(-5, 6):
                rx, ry = mid_x+dx, mid_y+dy+3
                if inb(rx, ry) and em[ry, rx]:
                    return (Tool.ROAD, rx, ry)

    return None

def act(obs, state):
    """
    Grid-based city builder: creates a horizontal road grid with vertical wire spine.
    Places zones in a checkerboard pattern with varied com/ind/res mix.
    Builds a more compact, denser cluster compared to parent.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    # City center - shifted to give more room
    cx, cy = 60, 50

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- Step 1: Place coal power plant ----
    if not np.any(pm):
        return (Tool.COALPOWER, cx - 12, cy)

    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # ---- Layout: horizontal spine approach ----
    # Wire spine runs horizontally at row cy
    # Roads run vertically at multiple columns
    # Zones placed between roads

    wire_row = cy  # horizontal wire at center row

    # Vertical road columns (spaced every 6 tiles)
    road_cols = [cx - 9, cx - 3, cx + 3, cx + 9, cx + 15]
    road_cols = [max(2, min(WORLD_W - 3, c)) for c in road_cols]

    # Zone columns between roads
    zone_col_centers = [(road_cols[i] + road_cols[i+1]) // 2 for i in range(len(road_cols) - 1)]

    # Wire extent (horizontal)
    if pop < 50:
        half_ext_x = 12
    elif pop < 200:
        half_ext_x = 18
    elif pop < 500:
        half_ext_x = 24
    else:
        half_ext_x = 30

    wire_left = max(3, cx - half_ext_x)
    wire_right = min(WORLD_W - 4, cx + half_ext_x)

    # Road extent (vertical, from wire row)
    if pop < 100:
        half_ext_y = 9
    elif pop < 400:
        half_ext_y = 15
    else:
        half_ext_y = 21

    road_top = max(2, cy - half_ext_y)
    road_bot = min(WORLD_H - 3, cy + half_ext_y)

    # ---- Step 2: Connect plant to wire spine ----
    if not np.any(wm):
        # Lay wire from plant toward wire_row
        if plant_cy != wire_row:
            step_dir = 1 if wire_row > plant_cy else -1
            nr = plant_cy + step_dir
            if 0 <= nr < WORLD_H and em[nr, plant_cx + 2]:
                return (Tool.WIRE, plant_cx + 2, nr)
        # Lay horizontal wire toward wire_left
        wc = plant_cx + 2
        if 0 <= wc < WORLD_W and em[wire_row, wc]:
            return (Tool.WIRE, wc, wire_row)

    # ---- Step 3: Extend horizontal wire spine ----
    wire_in_row = [c for c in range(WORLD_W) if wm[wire_row, c]]

    if wire_in_row:
        min_wc = min(wire_in_row)
        max_wc = max(wire_in_row)

        # Check plant connection
        plant_near_wire = any(
            abs(plant_cx + dc - c) <= 1 and abs(plant_cy - wire_row) <= 1
            for c in wire_in_row
            for dc in range(-1, 4)
        )

        # Connect plant column to wire row horizontally
        if plant_cy != wire_row:
            # Vertical wire from plant to wire_row
            step_dir = 1 if wire_row > plant_cy else -1
            for ry in range(plant_cy + step_dir, wire_row + step_dir, step_dir):
                if 0 <= ry < WORLD_H:
                    col = plant_cx + 2
                    if wm[ry, col]:
                        break
                    if em[ry, col] and not pm[ry, col]:
                        return (Tool.WIRE, col, ry)

        # Extend right
        if max_wc < wire_right:
            nc = max_wc + 1
            if 0 < nc < WORLD_W and not pm[wire_row, nc]:
                if em[wire_row, nc] or wm[wire_row, nc]:
                    return (Tool.WIRE, nc, wire_row)

        # Extend left
        if min_wc > wire_left:
            nc = min_wc - 1
            if 0 <= nc < WORLD_W and not pm[wire_row, nc]:
                if em[wire_row, nc] or wm[wire_row, nc]:
                    return (Tool.WIRE, nc, wire_row)
    else:
        # Bootstrap wire at plant
        pc = plant_cx + 2
        if 0 <= pc < WORLD_W and em[wire_row, pc]:
            return (Tool.WIRE, pc, wire_row)

    # ---- Step 4: Build vertical roads ----
    wire_in_row_set = set(wire_in_row)

    for rc in road_cols:
        if rc < wire_left or rc > wire_right:
            continue
        if rc not in wire_in_row_set:
            continue  # wire must pass through this column

        # Build road vertically at this column
        for ry in range(road_top, road_bot + 1):
            if not rm[ry, rc] and em[ry, rc] and not pm[ry, rc] and not wm[ry, rc]:
                return (Tool.ROAD, rc, ry)

    # ---- Step 5: Add horizontal connector roads every 6 rows ----
    horiz_road_rows = list(range(road_top, road_bot + 1, 6))

    for hr in horiz_road_rows:
        for rc in range(road_cols[0], road_cols[-1] + 1):
            if rc < wire_left or rc > wire_right:
                continue
            if not rm[hr, rc] and em[hr, rc] and not pm[hr, rc] and not wm[hr, rc]:
                return (Tool.ROAD, rc, hr)

    # ---- Zone placement helpers ----
    all_zone_mask = resm | comm | indm

    def zone_area_clear(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc2 = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc2 < WORLD_W):
                    return False
                if not (em[rr, rc2] or all_zone_mask[rr, rc2]):
                    return False
        return True

    def zone_overlap(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc2 = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc2 < WORLD_W:
                    if all_zone_mask[rr, rc2] or rm[rr, rc2] or pm[rr, rc2] or wm[rr, rc2]:
                        return True
        return False

    def pick_tool(zr, zc):
        # Vary zone type based on position for diversity
        t = max(1, total_zones)
        # More commercial near center, industrial on edges
        dist = abs(zc - cx) + abs(zr - cy)
        if dist > 15:
            if ind_count / t < 0.30:
                return Tool.INDUSTRIAL
        if com_count / t < 0.30:
            return Tool.COMMERCIAL
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # ---- Step 6: Place zones between road columns ----
    road_set = {(r, c) for r in range(WORLD_H) for c in range(WORLD_W) if rm[r, c]}

    def has_road_nearby(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-2, -1, 0, 1, 2]:
                rr, rc2 = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc2 < WORLD_W:
                    if rm[rr, rc2]:
                        return True
        return False

    # Place zones between road columns
    for i, zc in enumerate(zone_col_centers):
        for ry in range(road_top + 3, road_bot - 2, 3):
            zr = ry
            if zone_area_clear(zr, zc) and not zone_overlap(zr, zc) and has_road_nearby(zr, zc):
                return (pick_tool(zr, zc), zc, zr)

    # ---- Step 7: Second power plant for larger cities ----
    if pop > 400 and int(np.sum(pm)) < 9:
        px2 = cx + 20
        py2 = cy + 15
        px2 = max(2, min(WORLD_W - 4, px2))
        py2 = max(2, min(WORLD_H - 4, py2))
        area_ok = all(
            em[py2 + dr, px2 + dc]
            for dr in [-1, 0, 1] for dc in [-1, 0, 1]
            if 0 <= py2 + dr < WORLD_H and 0 <= px2 + dc < WORLD_W
        )
        if area_ok:
            return (Tool.COALPOWER, px2, py2)

    # ---- Step 8: Extend wire to second plant if it exists ----
    if int(np.sum(pm)) >= 9:
        plant_rows2, plant_cols2 = np.where(pm)
        # Find second cluster of plant tiles
        if len(plant_rows2) > 0:
            p2x = int(np.max(plant_cols2))
            p2y = int(plant_rows2[np.argmax(plant_cols2)])
            # Wire from wire_right toward second plant
            for wc in range(wire_right, p2x + 1):
                if 0 <= wc < WORLD_W and em[cy, wc] and not pm[cy, wc]:
                    if not wm[cy, wc]:
                        return (Tool.WIRE, wc, cy)

    # ---- Step 9: Densify by placing more zones near existing roads ----
    road_rows_near = set()
    for r in range(WORLD_H):
        for c in road_cols:
            if rm[r, c]:
                road_rows_near.add(r)

    for zr in sorted(road_rows_near):
        for zc in zone_col_centers:
            if zone_area_clear(zr, zc) and not zone_overlap(zr, zc):
                return (pick_tool(zr, zc), zc, zr)

    # ---- Step 10: Fill gaps in roads ----
    for rc in road_cols:
        for ry in range(road_top, road_bot + 1):
            if not rm[ry, rc] and em[ry, rc] and not pm[ry, rc]:
                # Check if we should place road here (between two road segments)
                above = any(rm[ry - d, rc] for d in range(1, 4) if ry - d >= 0)
                below = any(rm[ry + d, rc] for d in range(1, 4) if ry + d < WORLD_H)
                if above or below:
                    return (Tool.ROAD, rc, ry)

    return None

def act(obs, state):
    """
    Hybrid policy combining:
    - Parent A: Two clusters with horizontal spine, dual power plants
    - Parent B: Reactive closed-loop reading tile_map, vertical wire spine + road grid

    Strategy:
    1. Place coal power plant at center-left
    2. Build vertical wire spine adjacent to plant
    3. Build parallel road column
    4. Add lateral wires connecting spine to road
    5. Place zones (RCI balanced) served by both road and wire
    6. Add second power plant and expand as population grows
    7. Build horizontal road connections for better grid
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    all_zone = resm | comm | indm

    cx, cy = 45, WORLD_H // 2  # slightly left of center for first cluster

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    pop = obs.city_pop

    def pick_tool():
        t = max(total_zones, 1)
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone[rr, rc]:
                    return False
        return True

    def zone_exists_near(zr, zc, r=2):
        r0 = max(0, zr - r); r1 = min(WORLD_H, zr + r + 1)
        c0 = max(0, zc - r); c1 = min(WORLD_W, zc + r + 1)
        return np.any(all_zone[r0:r1, c0:c1])

    def wire_near(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def road_near(zr, zc, radius=3):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    # --- Phase 1: Place first coal power plant ---
    if not np.any(pm):
        return (Tool.COALPOWER, cx - 8, cy)

    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Identify if we have two distinct plants (for second cluster)
    plant_count_tiles = int(np.sum(pm))
    num_plants = plant_count_tiles // 6  # approx, each plant ~6 tiles

    # Define first cluster geometry
    wire_col1 = plant_cx + 3
    road_col1 = wire_col1 + 3
    left_zone_col1 = wire_col1 + 1
    right_zone_col1 = road_col1 + 3

    wire_col1 = max(2, min(WORLD_W - 3, wire_col1))
    road_col1 = max(2, min(WORLD_W - 3, road_col1))
    left_zone_col1 = max(2, min(WORLD_W - 3, left_zone_col1))
    right_zone_col1 = max(2, min(WORLD_W - 3, right_zone_col1))

    # Vertical extent
    if pop < 50:
        half = 10
    elif pop < 200:
        half = 16
    elif pop < 500:
        half = 22
    else:
        half = 30

    y_min = max(1, cy - half)
    y_max = min(WORLD_H - 2, cy + half)

    wire_rows1 = sorted([r for r in range(WORLD_H) if wm[r, wire_col1]])
    road_rows1 = sorted([r for r in range(WORLD_H) if rm[r, road_col1]])

    # --- Phase 2: Start wire spine adjacent to first plant ---
    if not wire_rows1:
        for dy in range(0, 8):
            for nr in [plant_cy + dy, plant_cy - dy]:
                if 0 <= nr < WORLD_H and 0 <= wire_col1 < WORLD_W:
                    if em[nr, wire_col1]:
                        return (Tool.WIRE, wire_col1, nr)
        return None

    min_wr1 = min(wire_rows1)
    max_wr1 = max(wire_rows1)

    # --- Phase 3: Connect plant to wire spine if not connected ---
    connected = False
    for dr in range(-2, 3):
        for dc in range(-2, 3):
            rr, rc = plant_cy + dr, plant_cx + dc
            if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                if wm[rr, rc]:
                    connected = True
    if not connected:
        bridge_r = plant_cy
        for bc in range(plant_cx + 1, wire_col1 + 1):
            if 0 <= bc < WORLD_W:
                if wm[bridge_r, bc]:
                    break
                if em[bridge_r, bc]:
                    return (Tool.WIRE, bc, bridge_r)

    # --- Phase 4: Extend wire spine vertically ---
    if max_wr1 < y_max:
        nr = max_wr1 + 1
        if nr < WORLD_H and em[nr, wire_col1] and not pm[nr, wire_col1]:
            return (Tool.WIRE, wire_col1, nr)

    if min_wr1 > y_min:
        nr = min_wr1 - 1
        if nr >= 0 and em[nr, wire_col1] and not pm[nr, wire_col1]:
            return (Tool.WIRE, wire_col1, nr)

    # --- Phase 5: Build road column parallel to wire spine ---
    for r in wire_rows1:
        if y_min <= r <= y_max:
            if 0 <= road_col1 < WORLD_W and em[r, road_col1] and not pm[r, road_col1]:
                return (Tool.ROAD, road_col1, r)

    # --- Phase 6: Lateral wires from spine toward road column ---
    for wr in wire_rows1:
        if y_min <= wr <= y_max:
            for wc in range(wire_col1 + 1, road_col1):
                if wc >= WORLD_W:
                    break
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc] and not rm[wr, wc] and not wm[wr, wc]:
                    break

    # --- Phase 7: Place zones - left side (between wire and road) ---
    zone_rows = list(range(y_min + 1, y_max, 4))

    for zr in zone_rows:
        w_close = any(abs(zr - wr) <= 2 for wr in wire_rows1)
        r_close = any(abs(zr - rr) <= 2 for rr in road_rows1)

        if w_close and r_close:
            zc = left_zone_col1
            if not zone_exists_near(zr, zc) and zone_area_ok(zr, zc):
                if wire_near(zr, zc, 3) and road_near(zr, zc, 3):
                    return (pick_tool(), zc, zr)

    # --- Phase 8: Extend road rightward for right zones ---
    for rr in road_rows1:
        if y_min <= rr <= y_max:
            for rc in range(road_col1 + 1, right_zone_col1 + 2):
                if rc >= WORLD_W:
                    break
                if rm[rr, rc]:
                    break
                if em[rr, rc] and not pm[rr, rc]:
                    return (Tool.ROAD, rc, rr)
                elif not em[rr, rc]:
                    break

    # --- Phase 9: Right-side zones ---
    for zr in zone_rows:
        r_close = any(abs(zr - rr) <= 2 for rr in road_rows1)
        if r_close:
            zc = right_zone_col1
            if not zone_exists_near(zr, zc) and zone_area_ok(zr, zc):
                if road_near(zr, zc, 3) and wire_near(zr, zc, 6):
                    return (pick_tool(), zc, zr)

    # --- Phase 10: Wire rightward to cover right zones ---
    for wr in wire_rows1:
        if y_min <= wr <= y_max:
            for wc in range(road_col1 + 1, right_zone_col1 + 3):
                if wc >= WORLD_W:
                    break
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc] and not rm[wr, wc] and not wm[wr, wc]:
                    break

    # --- Phase 11: Horizontal roads at top/bottom to connect grid ---
    if len(road_rows1) > 2:
        min_rr1 = min(road_rows1)
        max_rr1 = max(road_rows1)
        for hr in [min_rr1, max_rr1]:
            if y_min <= hr <= y_max:
                for rc in range(wire_col1 - 1, right_zone_col1 + 3):
                    if 0 <= rc < WORLD_W and em[hr, rc] and not pm[hr, rc]:
                        return (Tool.ROAD, rc, hr)

    # --- Phase 12: Second power plant for right cluster ---
    if pop > 100 and num_plants < 2:
        px2 = right_zone_col1 + 10
        py2 = cy
        px2 = max(2, min(WORLD_W - 4, px2))
        py2 = max(2, min(WORLD_H - 4, py2))
        area_ok = all(
            em[py2 + dr, px2 + dc]
            for dr in [-1, 0, 1] for dc in [-1, 0, 1]
            if 0 <= py2 + dr < WORLD_H and 0 <= px2 + dc < WORLD_W
        )
        if area_ok:
            return (Tool.COALPOWER, px2, py2)

    # --- Phase 13: Second cluster wiring and roads (right side) ---
    if pop > 100:
        # Find second plant if it exists
        # Use a fixed right cluster geometry
        rcx = right_zone_col1 + 10  # right cluster center x
        rcy = cy
        rcx = max(5, min(WORLD_W - 5, rcx))

        wire_col2 = rcx - 2
        road_col2 = rcx + 2
        left_zone_col2 = wire_col2 - 3
        right_zone_col2 = road_col2 + 3

        wire_col2 = max(2, min(WORLD_W - 3, wire_col2))
        road_col2 = max(2, min(WORLD_W - 3, road_col2))
        left_zone_col2 = max(2, min(WORLD_W - 3, left_zone_col2))
        right_zone_col2 = max(2, min(WORLD_W - 3, right_zone_col2))

        wire_rows2 = sorted([r for r in range(WORLD_H) if wm[r, wire_col2]])
        road_rows2 = sorted([r for r in range(WORLD_H) if rm[r, road_col2]])

        # Check if second plant is nearby
        plant2_near = np.any(pm[max(0, rcy-3):min(WORLD_H, rcy+4),
                                max(0, rcx-5):min(WORLD_W, rcx+5)])

        if plant2_near:
            # Extend wire spine for right cluster
            if not wire_rows2:
                for dy in range(0, 5):
                    for nr in [rcy + dy, rcy - dy]:
                        if 0 <= nr < WORLD_H and 0 <= wire_col2 < WORLD_W:
                            if em[nr, wire_col2]:
                                return (Tool.WIRE, wire_col2, nr)
            else:
                min_wr2 = min(wire_rows2)
                max_wr2 = max(wire_rows2)

                if max_wr2 < y_max:
                    nr = max_wr2 + 1
                    if nr < WORLD_H and em[nr, wire_col2] and not pm[nr, wire_col2]:
                        return (Tool.WIRE, wire_col2, nr)
                if min_wr2 > y_min:
                    nr = min_wr2 - 1
                    if nr >= 0 and em[nr, wire_col2] and not pm[nr, wire_col2]:
                        return (Tool.WIRE, wire_col2, nr)

                # Road for right cluster
                for r in wire_rows2:
                    if y_min <= r <= y_max:
                        if 0 <= road_col2 < WORLD_W and em[r, road_col2] and not pm[r, road_col2]:
                            return (Tool.ROAD, road_col2, r)

                # Lateral wires
                for wr in wire_rows2:
                    if y_min <= wr <= y_max:
                        for wc in range(wire_col2 + 1, road_col2):
                            if wc >= WORLD_W:
                                break
                            if wm[wr, wc]:
                                break
                            if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                                return (Tool.WIRE, wc, wr)
                            elif not em[wr, wc] and not rm[wr, wc] and not wm[wr, wc]:
                                break

                # Zones for right cluster
                for zr in zone_rows:
                    w_close = any(abs(zr - wr) <= 2 for wr in wire_rows2)
                    r_close = any(abs(zr - rr) <= 2 for rr in road_rows2)
                    if w_close and r_close:
                        for zc in [left_zone_col2, right_zone_col2]:
                            if not zone_exists_near(zr, zc) and zone_area_ok(zr, zc):
                                if wire_near(zr, zc, 4) and road_near(zr, zc, 4):
                                    return (pick_tool(), zc, zr)

    # --- Phase 14: Connect two clusters with horizontal wire spine ---
    if pop > 150:
        # Horizontal wire at cy connecting left cluster right edge to right cluster
        spine_y = cy
        # Find rightmost wire in first cluster
        wire_in_spine = [c for c in range(WORLD_W) if wm[spine_y, c]]
        if wire_in_spine:
            max_wc = max(wire_in_spine)
            # Extend rightward to connect clusters
            target_x = right_zone_col1 + 12
            target_x = min(WORLD_W - 3, target_x)
            if max_wc < target_x:
                nc = max_wc + 1
                if 0 <= nc < WORLD_W and (em[spine_y, nc] or rm[spine_y, nc]):
                    if not pm[spine_y, nc]:
                        return (Tool.WIRE, nc, spine_y)

    # --- Phase 15: Dense zone fill scan ---
    if pop > 50:
        for zr in range(y_min, y_max + 1, 3):
            for zc_off in [-3, 0, 3, 6, 9]:
                zc = road_col1 + zc_off
                zc = max(2, min(WORLD_W - 3, zc))
                if not zone_exists_near(zr, zc, 2) and zone_area_ok(zr, zc):
                    if wire_near(zr, zc, 5) and road_near(zr, zc, 4):
                        return (pick_tool(), zc, zr)

    # --- Phase 16: Extend wire spine further ---
    if pop > 200:
        new_half = half + 8
        new_y_min = max(1, cy - new_half)
        new_y_max = min(WORLD_H - 2, cy + new_half)
        if wire_rows1:
            if min_wr1 > new_y_min:
                nr = min_wr1 - 1
                if nr >= 0 and em[nr, wire_col1]:
                    return (Tool.WIRE, wire_col1, nr)
            if max_wr1 < new_y_max:
                nr = max_wr1 + 1
                if nr < WORLD_H and em[nr, wire_col1]:
                    return (Tool.WIRE, wire_col1, nr)

    return None

def act(obs, state):
    """
    Improved policy: horizontal layout with multiple neighborhoods.
    - Power plant on left, wire runs horizontally
    - Two road rows (top and bottom of zone band)
    - Zones fill between roads in columns
    - Better zone mix (RCI balance)
    - Second neighborhood offset vertically
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    all_zone_mask = resm | comm | indm

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    pop = obs.city_pop

    # Use state to track build phase
    if 'phase' not in state:
        state['phase'] = 0
        state['plant_placed'] = False

    # Neighborhood 1: centered at (cy1, cx_start..cx_end)
    # Horizontal wire row, two road rows flanking zones
    cy1 = 35  # center row of first neighborhood
    wire_row1 = cy1      # wire runs horizontally here
    road_row1a = cy1 - 4  # road above zones
    road_row1b = cy1 + 4  # road below zones
    zone_row1 = cy1       # zones centered here
    x_start = 15
    x_end = 95
    plant_x = 8
    plant_y = cy1

    # Neighborhood 2: offset
    cy2 = 65
    wire_row2 = cy2
    road_row2a = cy2 - 4
    road_row2b = cy2 + 4
    zone_row2 = cy2
    plant2_x = 8
    plant2_y = cy2

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        if com_count < 1 or (t > 0 and com_count / t < 0.30):
            return Tool.COMMERCIAL
        if ind_count < 1 or (t > 0 and ind_count / t < 0.25):
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_present(zr, zc, radius=2):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(all_zone_mask[r0:r1, c0:c1])

    def wire_near(zr, zc, radius=5):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def road_near(zr, zc, radius=5):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    # Determine how far to extend horizontally based on pop
    if pop < 100:
        x_extent = 40
    elif pop < 300:
        x_extent = 65
    else:
        x_extent = x_end

    cur_x_end = min(x_end, x_start + x_extent)

    # --- Step 1: Place power plant 1 ---
    if not np.any(pm):
        return (Tool.COALPOWER, plant_x, plant_y)

    plant_rows, plant_cols = np.where(pm)
    # Check if plant 1 area exists
    plant1_exists = np.any(pm[plant_y-1:plant_y+2, plant_x-1:plant_x+2])

    # --- Step 2: Wire from plant rightward (horizontal wire row 1) ---
    # Wire runs from plant_x+2 to cur_x_end along wire_row1
    wire_start_x = plant_x + 2
    for wx in range(wire_start_x, cur_x_end + 1):
        if 0 <= wx < WORLD_W and 0 <= wire_row1 < WORLD_H:
            if not wm[wire_row1, wx] and em[wire_row1, wx] and not pm[wire_row1, wx]:
                return (Tool.WIRE, wx, wire_row1)

    # --- Step 3: Road row above zones (road_row1a) ---
    for rx in range(x_start, cur_x_end + 1):
        if 0 <= rx < WORLD_W and 0 <= road_row1a < WORLD_H:
            if not rm[road_row1a, rx] and em[road_row1a, rx]:
                return (Tool.ROAD, rx, road_row1a)

    # --- Step 4: Road row below zones (road_row1b) ---
    for rx in range(x_start, cur_x_end + 1):
        if 0 <= rx < WORLD_W and 0 <= road_row1b < WORLD_H:
            if not rm[road_row1b, rx] and em[road_row1b, rx]:
                return (Tool.ROAD, rx, road_row1b)

    # --- Step 5: Vertical wires connecting wire_row1 to road rows ---
    # Place vertical wires at intervals to connect wire to roads
    for vx in range(x_start + 3, cur_x_end, 6):
        if 0 <= vx < WORLD_W:
            for vy in range(min(wire_row1, road_row1a), max(wire_row1, road_row1b) + 1):
                if 0 <= vy < WORLD_H:
                    if not wm[vy, vx] and em[vy, vx] and not pm[vy, vx] and not rm[vy, vx]:
                        return (Tool.WIRE, vx, vy)

    # --- Step 6: Place zones between the two road rows ---
    # Zone centers at zone_row1, columns every 3 starting from x_start+3
    zone_cols = list(range(x_start + 3, cur_x_end - 2, 6))
    for zc in zone_cols:
        zr = zone_row1
        if not zone_present(zr, zc, 1) and zone_area_ok(zr, zc):
            if wire_near(zr, zc, 6) and road_near(zr, zc, 5):
                return (pick_tool(), zc, zr)

    # --- Step 7: Second power plant for neighborhood 2 ---
    if pop > 50:
        # Check if second plant exists near plant2_x, plant2_y
        plant2_exists = np.any(pm[plant2_y-2:plant2_y+3, plant2_x-2:plant2_x+3])
        if not plant2_exists:
            # Only place if area is clear
            area_ok = True
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    rr, rc = plant2_y + dr, plant2_x + dc
                    if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                        if not em[rr, rc]:
                            area_ok = False
                    else:
                        area_ok = False
            if area_ok:
                return (Tool.COALPOWER, plant2_x, plant2_y)

        # Neighborhood 2 wire
        for wx in range(plant2_x + 2, cur_x_end + 1):
            if 0 <= wx < WORLD_W and 0 <= wire_row2 < WORLD_H:
                if not wm[wire_row2, wx] and em[wire_row2, wx] and not pm[wire_row2, wx]:
                    return (Tool.WIRE, wx, wire_row2)

        # Neighborhood 2 roads
        for rx in range(x_start, cur_x_end + 1):
            if 0 <= rx < WORLD_W and 0 <= road_row2a < WORLD_H:
                if not rm[road_row2a, rx] and em[road_row2a, rx]:
                    return (Tool.ROAD, rx, road_row2a)

        for rx in range(x_start, cur_x_end + 1):
            if 0 <= rx < WORLD_W and 0 <= road_row2b < WORLD_H:
                if not rm[road_row2b, rx] and em[road_row2b, rx]:
                    return (Tool.ROAD, rx, road_row2b)

        # Vertical wires for neighborhood 2
        for vx in range(x_start + 3, cur_x_end, 6):
            if 0 <= vx < WORLD_W:
                for vy in range(min(wire_row2, road_row2a), max(wire_row2, road_row2b) + 1):
                    if 0 <= vy < WORLD_H:
                        if not wm[vy, vx] and em[vy, vx] and not pm[vy, vx] and not rm[vy, vx]:
                            return (Tool.WIRE, vx, vy)

        # Zones neighborhood 2
        for zc in zone_cols:
            zr = zone_row2
            if not zone_present(zr, zc, 1) and zone_area_ok(zr, zc):
                if wire_near(zr, zc, 6) and road_near(zr, zc, 5):
                    return (pick_tool(), zc, zr)

    # --- Step 8: Connect the two neighborhoods with a vertical road ---
    if pop > 100:
        vert_road_x = x_start + 3
        for ry in range(road_row1b, road_row2a + 1):
            if 0 <= ry < WORLD_H and 0 <= vert_road_x < WORLD_W:
                if not rm[ry, vert_road_x] and em[ry, vert_road_x]:
                    return (Tool.ROAD, vert_road_x, ry)

    # --- Step 9: Third neighborhood if booming ---
    if pop > 400:
        cy3 = 85
        wire_row3 = cy3
        road_row3a = cy3 - 4
        road_row3b = cy3 + 4
        plant3_x = 8
        plant3_y = cy3

        plant3_exists = np.any(pm[plant3_y-2:plant3_y+3, plant3_x-2:plant3_x+3])
        if not plant3_exists:
            area_ok = True
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    rr, rc = plant3_y + dr, plant3_x + dc
                    if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                        if not em[rr, rc]:
                            area_ok = False
                    else:
                        area_ok = False
            if area_ok:
                return (Tool.COALPOWER, plant3_x, plant3_y)

        for wx in range(plant3_x + 2, cur_x_end + 1):
            if 0 <= wx < WORLD_W and 0 <= wire_row3 < WORLD_H:
                if not wm[wire_row3, wx] and em[wire_row3, wx] and not pm[wire_row3, wx]:
                    return (Tool.WIRE, wx, wire_row3)

        for rx in range(x_start, cur_x_end + 1):
            for road_r in [road_row3a, road_row3b]:
                if 0 <= rx < WORLD_W and 0 <= road_r < WORLD_H:
                    if not rm[road_r, rx] and em[road_r, rx]:
                        return (Tool.ROAD, rx, road_r)

        for zc in zone_cols:
            zr = cy3
            if not zone_present(zr, zc, 1) and zone_area_ok(zr, zc):
                if wire_near(zr, zc, 6) and road_near(zr, zc, 5):
                    return (pick_tool(), zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map every step to find existing infrastructure
    - Builds compact cluster: power plant -> wire spine -> road -> zones
    - Reacts to actual map state rather than precomputed plan
    - Key changes from parent:
      * Use horizontal layout (wire row, road row) instead of vertical columns
      * Place zones above and below road row for denser coverage
      * Wire connects horizontally from plant outward
      * More aggressive zone placement once infrastructure exists
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    all_zone_mask = resm | comm | indm

    pop = obs.city_pop
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    cx, cy = WORLD_W // 2, WORLD_H // 2

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(total_zones, 1)
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_present(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def wire_near(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return bool(np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1]))

    def road_near(zr, zc, radius=3):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return bool(np.any(rm[r0:r1, c0:c1]))

    # --- Phase 1: Place coal power plant if none exists ---
    if not np.any(pm):
        px, py = cx - 12, cy
        px = max(2, min(WORLD_W - 3, px))
        py = max(2, min(WORLD_H - 3, py))
        return (Tool.COALPOWER, px, py)

    # Find plant centroid
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Layout: wire runs horizontally at plant_cy, road at plant_cy + 3
    # Zones placed at rows plant_cy - 3, plant_cy + 6 (above wire, below road)
    wire_row = plant_cy
    road_row = plant_cy + 4
    zone_row_above = plant_cy - 4
    zone_row_below = road_row + 4

    # Clamp rows
    wire_row = max(2, min(WORLD_H - 3, wire_row))
    road_row = max(2, min(WORLD_H - 3, road_row))
    zone_row_above = max(2, min(WORLD_H - 3, zone_row_above))
    zone_row_below = max(2, min(WORLD_H - 3, zone_row_below))

    # Determine horizontal extent based on pop
    if pop < 50:
        spine_half = 8
    elif pop < 150:
        spine_half = 14
    elif pop < 400:
        spine_half = 20
    elif pop < 800:
        spine_half = 26
    else:
        spine_half = 32

    target_left = max(2, plant_cx + 3)
    target_right = min(WORLD_W - 3, plant_cx + 3 + spine_half * 2)

    # Find existing wire columns on wire_row
    wire_cols_on_row = [c for c in range(WORLD_W) if wm[wire_row, c]]
    road_cols_on_row = [c for c in range(WORLD_W) if rm[road_row, c]]

    # --- Phase 2: Bootstrap wire adjacent to plant (rightward) ---
    if not wire_cols_on_row:
        for dc in range(3, 8):
            nc = plant_cx + dc
            if 0 <= nc < WORLD_W and not pm[wire_row, nc]:
                if em[wire_row, nc] or wm[wire_row, nc]:
                    return (Tool.WIRE, nc, wire_row)
        return None

    min_wire_col = min(wire_cols_on_row)
    max_wire_col = max(wire_cols_on_row)

    # --- Phase 3: Extend wire rightward ---
    if max_wire_col < target_right:
        nc = max_wire_col + 1
        if 0 <= nc < WORLD_W and not pm[wire_row, nc]:
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # --- Phase 4: Extend wire leftward (from plant toward left) ---
    if min_wire_col > target_left:
        nc = min_wire_col - 1
        if 0 <= nc < WORLD_W and not pm[wire_row, nc]:
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # --- Phase 5: Build road row (horizontal) ---
    if not road_cols_on_row:
        # Start road near plant, on road_row
        for dc in range(3, 10):
            nc = plant_cx + dc
            if 0 <= nc < WORLD_W and em[road_row, nc] and not pm[road_row, nc]:
                return (Tool.ROAD, nc, road_row)

    if road_cols_on_row:
        min_road_col = min(road_cols_on_row)
        max_road_col = max(road_cols_on_row)
        # Extend road rightward
        if max_road_col < target_right:
            nc = max_road_col + 1
            if 0 <= nc < WORLD_W and em[road_row, nc] and not pm[road_row, nc]:
                return (Tool.ROAD, nc, road_row)
        # Extend road leftward
        if min_road_col > target_left:
            nc = min_road_col - 1
            if 0 <= nc < WORLD_W and em[road_row, nc] and not pm[road_row, nc]:
                return (Tool.ROAD, nc, road_row)

    # --- Phase 6: Vertical wires connecting wire_row to road_row ---
    # For columns that have wire, extend vertically down to road_row
    for wc in wire_cols_on_row:
        if target_left <= wc <= target_right:
            # Check if there's a gap between wire_row and road_row
            for vr in range(wire_row + 1, road_row):
                if 0 <= vr < WORLD_H and not wm[vr, wc] and not rm[vr, wc]:
                    if em[vr, wc] and not pm[vr, wc]:
                        return (Tool.WIRE, wc, vr)
                    elif not em[vr, wc] and not pm[vr, wc]:
                        break

    # --- Phase 7: Place zones above wire row ---
    zone_cols = list(range(max(2, target_left), min(WORLD_W - 2, target_right + 1), 4))

    for zc in zone_cols:
        zr = zone_row_above
        if not zone_present(zr, zc) and zone_area_ok(zr, zc):
            if wire_near(zr, zc, 5) and road_near(zr, zc, 6):
                return (pick_tool(), zc, zr)

    # --- Phase 8: Place zones below road row ---
    for zc in zone_cols:
        zr = zone_row_below
        if not zone_present(zr, zc) and zone_area_ok(zr, zc):
            if wire_near(zr, zc, 6) and road_near(zr, zc, 5):
                return (pick_tool(), zc, zr)

    # --- Phase 9: Wire down to zone_row_above from wire_row ---
    for zc in zone_cols:
        # Wire vertically upward from wire_row toward zone_row_above
        for vr in range(wire_row - 1, zone_row_above - 1, -1):
            if 0 <= vr < WORLD_H and not wm[vr, zc]:
                if em[vr, zc] and not pm[vr, zc]:
                    return (Tool.WIRE, zc, vr)
                elif not em[vr, zc] and not pm[vr, zc]:
                    break

    # --- Phase 10: Road extensions to zone_row_below ---
    if road_cols_on_row:
        for zc in zone_cols:
            if 0 <= zc < WORLD_W:
                # Vertical road from road_row down toward zone_row_below
                for vr in range(road_row + 1, zone_row_below + 1):
                    if 0 <= vr < WORLD_H and not rm[vr, zc]:
                        if em[vr, zc] and not pm[vr, zc]:
                            return (Tool.ROAD, zc, vr)
                        elif not em[vr, zc] and not pm[vr, zc]:
                            break

    # --- Phase 11: Second power plant if population growing ---
    if pop > 200:
        # Place another coal plant to the right if needed
        num_plants = int(np.sum(pm))
        if num_plants < 18:  # less than 2 plants
            px2 = plant_cx + 20
            py2 = plant_cy
            px2 = max(2, min(WORLD_W - 3, px2))
            py2 = max(2, min(WORLD_H - 3, py2))
            area_ok = True
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    rr2, rc2 = py2 + dr, px2 + dc
                    if not (0 <= rr2 < WORLD_H and 0 <= rc2 < WORLD_W):
                        area_ok = False
                    elif not em[rr2, rc2] and not pm[rr2, rc2]:
                        area_ok = False
            if area_ok:
                return (Tool.COALPOWER, px2, py2)

    # --- Phase 12: Extra zone rows for higher density ---
    if pop > 100:
        extra_rows = [zone_row_above - 4, zone_row_below + 4]
        for zr in extra_rows:
            zr = max(2, min(WORLD_H - 3, zr))
            for zc in zone_cols:
                if not zone_present(zr, zc) and zone_area_ok(zr, zc):
                    if wire_near(zr, zc, 7) and road_near(zr, zc, 7):
                        return (pick_tool(), zc, zr)

    # --- Phase 13: Fill gaps in zone placement ---
    # Try any empty zone-compatible spot near existing wire and road
    for zr in range(zone_row_above - 1, zone_row_below + 2, 3):
        zr_c = max(2, min(WORLD_H - 3, zr))
        for zc in zone_cols:
            if not zone_present(zr_c, zc) and zone_area_ok(zr_c, zc):
                if wire_near(zr_c, zc, 5) and road_near(zr_c, zc, 5):
                    return (pick_tool(), zc, zr_c)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy. Reads map each step and extends
    infrastructure/zones based on what exists. More compact grid layout:
    plant -> wire spine -> roads on both sides -> zones flanking roads.
    Uses a denser layout to get more powered road-adjacent zones quickly.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)
    all_zone_m = res_m | com_m | ind_m

    has_plant = np.any(pm)

    # ---- Phase 1: Place coal power plant ----
    if not has_plant:
        return (Tool.COALPOWER, 60, 50)

    # Find plant center
    plant_rows, plant_cols = np.where(pm)
    pcx = int(np.mean(plant_cols))
    pcy = int(np.mean(plant_rows))

    # Layout rows relative to plant
    # wire spine at pcy (same row as plant, plant occupies pcy-1..pcy+1)
    # Actually plant center is at pcy, so wire row should be offset
    wire_row = pcy - 4
    wire_row = max(3, min(WORLD_H - 4, wire_row))

    # Roads directly above and below wire spine (1 tile gap)
    road_row_top = wire_row - 1
    road_row_bot = wire_row + 1
    # Zones 2 rows from wire (centered in road's neighbor)
    zone_row_top = wire_row - 4  # 3 rows above road_row_top
    zone_row_bot = wire_row + 4  # 3 rows below road_row_bot

    road_row_top = max(3, min(WORLD_H - 4, road_row_top))
    road_row_bot = max(3, min(WORLD_H - 4, road_row_bot))
    zone_row_top = max(3, min(WORLD_H - 4, zone_row_top))
    zone_row_bot = max(3, min(WORLD_H - 4, zone_row_bot))

    # Horizontal span grows with population
    half_span = min(45, max(15, 12 + obs.city_pop // 8))
    cmin = max(3, pcx - half_span)
    cmax = min(WORLD_W - 4, pcx + half_span)

    # ---- Helper: check if 3x3 area is clear ----
    def zone_area_free(zr, zc):
        if zr < 1 or zr >= WORLD_H - 1 or zc < 1 or zc >= WORLD_W - 1:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def nearby_zone(zr, zc, radius=3):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(all_zone_m[r0:r1, c0:c1])

    res_count = max(1, int(np.sum(res_m)) // 9)
    com_count = max(1, int(np.sum(com_m)) // 9)
    ind_count = max(1, int(np.sum(ind_m)) // 9)

    def pick_zone():
        # Aim for roughly 2:1:1 res:com:ind ratio
        if res_count <= com_count + ind_count:
            return Tool.RESIDENTIAL
        if com_count <= ind_count:
            return Tool.COMMERCIAL
        return Tool.INDUSTRIAL

    # ---- Phase 2: Build wire spine connected to plant ----
    # First connect plant to wire row via vertical wire
    # Plant occupies rows pcy-1..pcy+1, cols pcx-1..pcx+1
    # Need wire from plant edge to wire_row
    if pcy - 1 > wire_row:
        # Connect downward from wire_row to plant
        for wr in range(wire_row + 1, pcy - 1):
            if 0 <= wr < WORLD_H and not wm[wr, pcx] and (em[wr, pcx] or rm[wr, pcx]):
                return (Tool.WIRE, pcx, wr)
    elif pcy + 1 < wire_row:
        for wr in range(pcy + 2, wire_row):
            if 0 <= wr < WORLD_H and not wm[wr, pcx] and (em[wr, pcx] or rm[wr, pcx]):
                return (Tool.WIRE, pcx, wr)

    # Build horizontal wire spine
    wire_cols = sorted(c for c in range(WORLD_W) if 0 <= wire_row < WORLD_H and wm[wire_row, c])

    if not wire_cols:
        # Start wire at plant column on wire row
        if 0 <= wire_row < WORLD_H:
            return (Tool.WIRE, pcx, wire_row)
    else:
        min_wc = wire_cols[0]
        max_wc = wire_cols[-1]
        # Extend right
        if max_wc < cmax:
            nc = max_wc + 1
            if 0 <= nc < WORLD_W:
                return (Tool.WIRE, nc, wire_row)
        # Extend left
        if min_wc > cmin:
            nc = min_wc - 1
            if 0 <= nc < WORLD_W:
                return (Tool.WIRE, nc, wire_row)

    # ---- Phase 3: Build road rows ----
    if wire_cols:
        # Top road
        if 0 <= road_row_top < WORLD_H:
            for wc in wire_cols:
                if cmin <= wc <= cmax and not rm[road_row_top, wc] and em[road_row_top, wc]:
                    return (Tool.ROAD, wc, road_row_top)
        # Bottom road
        if 0 <= road_row_bot < WORLD_H:
            for wc in wire_cols:
                if cmin <= wc <= cmax and not rm[road_row_bot, wc] and em[road_row_bot, wc]:
                    return (Tool.ROAD, wc, road_row_bot)

    # ---- Phase 4: Place zones adjacent to roads ----
    if wire_cols:
        road_cols_top = set(c for c in range(WORLD_W) if 0 <= road_row_top < WORLD_H and rm[road_row_top, c])
        road_cols_bot = set(c for c in range(WORLD_W) if 0 <= road_row_bot < WORLD_H and rm[road_row_bot, c])

        # Place zones in columns where road exists, centered at zone_row_top/bot
        # Zone center must be 2 tiles from road (zone edge touches road)
        # zone at zone_row_top: row above road_row_top by 2 (zone bottom edge = road_row_top - 1)
        # Actually zone center at zone_row_top = road_row_top - 2 means zone occupies
        # rows road_row_top-3..road_row_top-1, close to road at road_row_top. Good.

        # Zones above top road
        zone_top_adjacent = road_row_top - 2  # zone center 2 above road
        zone_top_adjacent = max(3, min(WORLD_H - 4, zone_top_adjacent))
        if road_cols_top:
            for zc in sorted(road_cols_top):
                if cmin <= zc <= cmax and 3 <= zone_top_adjacent <= WORLD_H - 4:
                    if not nearby_zone(zone_top_adjacent, zc) and zone_area_free(zone_top_adjacent, zc):
                        return (pick_zone(), zc, zone_top_adjacent)

        # Zones below bottom road
        zone_bot_adjacent = road_row_bot + 2  # zone center 2 below road
        zone_bot_adjacent = max(3, min(WORLD_H - 4, zone_bot_adjacent))
        if road_cols_bot:
            for zc in sorted(road_cols_bot):
                if cmin <= zc <= cmax and 3 <= zone_bot_adjacent <= WORLD_H - 4:
                    if not nearby_zone(zone_bot_adjacent, zc) and zone_area_free(zone_bot_adjacent, zc):
                        return (pick_zone(), zc, zone_bot_adjacent)

        # Second row of zones (further out) once pop grows
        if obs.city_pop > 30:
            zone_top2 = zone_top_adjacent - 4
            zone_top2 = max(3, min(WORLD_H - 4, zone_top2))
            for zc in sorted(road_cols_top):
                if cmin <= zc <= cmax and 3 <= zone_top2 <= WORLD_H - 4:
                    if not nearby_zone(zone_top2, zc) and zone_area_free(zone_top2, zc):
                        return (pick_zone(), zc, zone_top2)

            zone_bot2 = zone_bot_adjacent + 4
            zone_bot2 = max(3, min(WORLD_H - 4, zone_bot2))
            for zc in sorted(road_cols_bot):
                if cmin <= zc <= cmax and 3 <= zone_bot2 <= WORLD_H - 4:
                    if not nearby_zone(zone_bot2, zc) and zone_area_free(zone_bot2, zc):
                        return (pick_zone(), zc, zone_bot2)

    # ---- Phase 5: Second cluster lower down ----
    if obs.city_pop > 60 and wire_cols:
        wire_row2 = pcy + 6
        wire_row2 = max(3, min(WORLD_H - 4, wire_row2))
        road_row2_top = wire_row2 - 1
        road_row2_bot = wire_row2 + 1
        road_row2_top = max(3, min(WORLD_H - 4, road_row2_top))
        road_row2_bot = max(3, min(WORLD_H - 4, road_row2_bot))

        wire_cols2 = sorted(c for c in range(WORLD_W) if 0 <= wire_row2 < WORLD_H and wm[wire_row2, c])

        if not wire_cols2:
            # Bridge vertically from wire_row to wire_row2
            bridge_col = pcx
            for wr in range(min(wire_row, wire_row2) + 1, max(wire_row, wire_row2)):
                if 0 <= wr < WORLD_H and not wm[wr, bridge_col] and em[wr, bridge_col]:
                    return (Tool.WIRE, bridge_col, wr)
            if 0 <= wire_row2 < WORLD_H and em[wire_row2, bridge_col]:
                return (Tool.WIRE, bridge_col, wire_row2)
        else:
            min_wc2 = wire_cols2[0]
            max_wc2 = wire_cols2[-1]
            if max_wc2 < cmax:
                return (Tool.WIRE, max_wc2 + 1, wire_row2)
            if min_wc2 > cmin:
                return (Tool.WIRE, min_wc2 - 1, wire_row2)

            # Roads
            if 0 <= road_row2_top < WORLD_H:
                for wc in wire_cols2:
                    if cmin <= wc <= cmax and not rm[road_row2_top, wc] and em[road_row2_top, wc]:
                        return (Tool.ROAD, wc, road_row2_top)
            if 0 <= road_row2_bot < WORLD_H:
                for wc in wire_cols2:
                    if cmin <= wc <= cmax and not rm[road_row2_bot, wc] and em[road_row2_bot, wc]:
                        return (Tool.ROAD, wc, road_row2_bot)

            road_cols2_top = set(c for c in range(WORLD_W) if 0 <= road_row2_top < WORLD_H and rm[road_row2_top, c])
            road_cols2_bot = set(c for c in range(WORLD_W) if 0 <= road_row2_bot < WORLD_H and rm[road_row2_bot, c])

            zone_t2 = max(3, min(WORLD_H - 4, road_row2_top - 2))
            zone_b2 = max(3, min(WORLD_H - 4, road_row2_bot + 2))

            for zc in sorted(road_cols2_top):
                if cmin <= zc <= cmax and 3 <= zone_t2 <= WORLD_H - 4:
                    if not nearby_zone(zone_t2, zc) and zone_area_free(zone_t2, zc):
                        return (pick_zone(), zc, zone_t2)
            for zc in sorted(road_cols2_bot):
                if cmin <= zc <= cmax and 3 <= zone_b2 <= WORLD_H - 4:
                    if not nearby_zone(zone_b2, zc) and zone_area_free(zone_b2, zc):
                        return (pick_zone(), zc, zone_b2)

    # ---- Phase 6: Second power plant ----
    if obs.city_pop > 300 and not state.get("plant2_placed", False):
        px2 = max(3, min(WORLD_W - 4, pcx - 25))
        py2 = max(3, min(WORLD_H - 4, pcy))
        clear = all(
            0 <= py2 + dr < WORLD_H and 0 <= px2 + dc < WORLD_W and em[py2 + dr, px2 + dc]
            for dr in [-1, 0, 1] for dc in [-1, 0, 1]
        )
        if clear:
            state["plant2_placed"] = True
            return (Tool.COALPOWER, px2, py2)

    # ---- Phase 7: Vertical road connectors ----
    if wire_cols and obs.city_pop > 100:
        for vc in [pcx, pcx + 6, pcx - 6, pcx + 12, pcx - 12]:
            if not (cmin <= vc <= cmax):
                continue
            if 0 <= vc < WORLD_W:
                for vr in range(road_row_top, road_row_bot + 1):
                    if 0 <= vr < WORLD_H and not rm[vr, vc] and em[vr, vc]:
                        return (Tool.ROAD, vc, vr)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map each step and places next tile
    based on what already exists. Builds a compact powered city cluster.

    Strategy:
    - Detect plant/wire/road/zone positions from current map
    - Grow wire spine outward from plant
    - Grow roads adjacent to wire spine
    - Place zones adjacent to roads, with wire nearby for power
    - Expand laterally with second/third zone columns
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    # Prefer building near map center
    cx, cy = 58, 50

    has_plant = np.any(pm)

    # Phase 1: Place coal power plant if none exists
    if not has_plant:
        # Place plant so its right edge is at cx-6 (center at cx-8)
        return (Tool.COALPOWER, cx - 8, cy)

    # Gather current state from map
    plant_ys, plant_xs = np.where(pm)
    # Find plant center (approximate)
    if len(plant_xs) > 0:
        px = int(np.median(plant_xs))
        py = int(np.median(plant_ys))
    else:
        px, py = cx - 8, cy

    wire_ys, wire_xs = np.where(wm)
    road_ys, road_xs = np.where(rm)
    res_ys, res_xs = np.where(res_mask(tm))
    com_ys, com_xs = np.where(com_mask(tm))
    ind_ys, ind_xs = np.where(ind_mask(tm))

    wire_positions = set(zip(wire_ys.tolist(), wire_xs.tolist()))
    road_positions = set(zip(road_ys.tolist(), road_xs.tolist()))
    zone_positions = (set(zip(res_ys.tolist(), res_xs.tolist())) |
                      set(zip(com_ys.tolist(), com_xs.tolist())) |
                      set(zip(ind_ys.tolist(), ind_xs.tolist())))

    res_count = len(res_xs)
    com_count = len(com_xs)
    ind_count = len(ind_xs)

    # Wire spine: column just right of plant footprint
    wire_col = px + 2  # main vertical wire spine
    # Roads: one on each side of wire spine
    road_col_r = wire_col + 1
    road_col_l = wire_col - 1
    # Zone columns: 3 tiles from road
    zone_col_r = road_col_r + 3
    zone_col_l = road_col_l - 3

    # Dynamic vertical span based on population
    pop_span = min(30, max(8, obs.city_pop // 20))
    tmin = max(2, cy - pop_span)
    tmax = min(WORLD_H - 3, cy + pop_span)

    # --- Phase 2: Grow wire spine vertically ---
    wire_in_spine = sorted(r for (r, c) in wire_positions if c == wire_col)

    if not wire_in_spine:
        # Start wire adjacent to plant
        for dy in range(-2, 3):
            ny = py + dy
            if 0 <= ny < WORLD_H and 0 <= wire_col < WORLD_W:
                if em[ny, wire_col]:
                    return (Tool.WIRE, wire_col, ny)
        # Force place
        return (Tool.WIRE, wire_col, py)
    else:
        cur_min = min(wire_in_spine)
        cur_max = max(wire_in_spine)
        # Extend downward
        if cur_max < tmax:
            nr = cur_max + 1
            if 0 <= nr < WORLD_H:
                return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if cur_min > tmin:
            nr = cur_min - 1
            if 0 <= nr < WORLD_H:
                return (Tool.WIRE, wire_col, nr)

    wire_rows_set = set(wire_in_spine)

    # --- Phase 3: Build right road column adjacent to wire ---
    road_r_rows = set(r for (r, c) in road_positions if c == road_col_r)
    for wr in sorted(wire_in_spine):
        if wr not in road_r_rows and 0 <= road_col_r < WORLD_W:
            return (Tool.ROAD, road_col_r, wr)

    # --- Phase 4: Build left road column adjacent to wire ---
    road_l_rows = set(r for (r, c) in road_positions if c == road_col_l)
    for wr in sorted(wire_in_spine):
        if wr not in road_l_rows and road_col_l >= 0:
            return (Tool.ROAD, road_col_l, wr)

    # --- Helper: check if 3x3 area is free ---
    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def zone_nearby(zr, zc):
        return any(abs(zr - pr) <= 1 and abs(zc - pc) <= 1
                   for (pr, pc) in zone_positions)

    def pick_zone(zc):
        # Balance: ~50% res, ~25% com, ~25% ind
        if ind_count * 2 < com_count + 1:
            return Tool.INDUSTRIAL
        elif com_count * 2 < res_count + 1:
            return Tool.COMMERCIAL
        else:
            return Tool.RESIDENTIAL

    # --- Phase 5: Place zones on right side ---
    road_r_list = sorted(road_r_rows)
    for zr in sorted(wire_in_spine):
        # Need road access and wire nearby
        road_near = any(abs(zr - rr) <= 2 for rr in road_r_list)
        wire_near = zr in wire_rows_set or (zr-1) in wire_rows_set or (zr+1) in wire_rows_set
        if road_near and wire_near:
            zc = zone_col_r
            if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                if not zone_nearby(zr, zc) and zone_area_free(zr, zc):
                    return (pick_zone(zc), zc, zr)

    # --- Phase 5b: Fill lateral road to right zone col ---
    for wr in sorted(wire_in_spine):
        for rc in range(road_col_r + 1, zone_col_r):
            if 0 <= rc < WORLD_W and em[wr, rc]:
                return (Tool.ROAD, rc, wr)

    # --- Phase 6: Place zones on left side ---
    road_l_list = sorted(road_l_rows)
    for zr in sorted(wire_in_spine):
        road_near = any(abs(zr - rr) <= 2 for rr in road_l_list)
        wire_near = zr in wire_rows_set or (zr-1) in wire_rows_set or (zr+1) in wire_rows_set
        if road_near and wire_near:
            zc = zone_col_l
            if 0 <= zr < WORLD_H and zc >= 0:
                if not zone_nearby(zr, zc) and zone_area_free(zr, zc):
                    return (pick_zone(zc), zc, zr)

    # --- Phase 6b: Fill lateral wire to left zone col ---
    for wr in sorted(wire_in_spine):
        for wc in range(wire_col - 1, zone_col_l - 1, -1):
            if wc == road_col_l:
                continue  # skip road col, handled separately
            if 0 <= wc < WORLD_W and em[wr, wc]:
                return (Tool.WIRE, wc, wr)

    # --- Phase 7: Second cluster to the right when population grows ---
    if obs.city_pop > 150:
        wire_col2 = zone_col_r + 4
        road_col2r = wire_col2 + 1
        zone_col2r = road_col2r + 3

        wire_in_col2 = sorted(r for (r, c) in wire_positions if c == wire_col2)

        if not wire_in_col2:
            # Extend horizontal wire from main spine at cy
            for wc in range(wire_col + 1, wire_col2 + 1):
                if 0 <= wc < WORLD_W and em[cy, wc]:
                    return (Tool.WIRE, wc, cy)
        else:
            cur_min2 = min(wire_in_col2)
            cur_max2 = max(wire_in_col2)
            tmax2 = min(WORLD_H - 3, cy + pop_span)
            tmin2 = max(2, cy - pop_span)

            if cur_max2 < tmax2:
                nr = cur_max2 + 1
                if 0 <= nr < WORLD_H:
                    return (Tool.WIRE, wire_col2, nr)
            if cur_min2 > tmin2:
                nr = cur_min2 - 1
                if 0 <= nr < WORLD_H:
                    return (Tool.WIRE, wire_col2, nr)

            # Road column right of wire_col2
            road2r_rows = set(r for (r, c) in road_positions if c == road_col2r)
            for wr in sorted(wire_in_col2):
                if wr not in road2r_rows and 0 <= road_col2r < WORLD_W:
                    return (Tool.ROAD, road_col2r, wr)

            # Place zones
            road2r_list = sorted(road2r_rows)
            for zr in sorted(wire_in_col2):
                road_near = any(abs(zr - rr) <= 2 for rr in road2r_list)
                wire_near = any(abs(zr - wr) <= 1 for wr in wire_in_col2)
                if road_near and wire_near:
                    zc = zone_col2r
                    if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                        if not zone_nearby(zr, zc) and zone_area_free(zr, zc):
                            if com_count * 3 < res_count:
                                return (Tool.COMMERCIAL, zc, zr)
                            else:
                                return (Tool.RESIDENTIAL, zc, zr)

            # Lateral roads
            for wr in sorted(wire_in_col2):
                for rc in range(road_col2r + 1, zone_col2r):
                    if 0 <= rc < WORLD_W and em[wr, rc]:
                        return (Tool.ROAD, rc, wr)

    # --- Phase 8: Second coal plant if population is high ---
    if obs.city_pop > 400 and not state.get("plant2_placed", False):
        p2x, p2y = cx + 25, cy
        clear = True
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = p2y + dr, p2x + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if not em[rr, rc]:
                        clear = False
                        break
        if clear:
            state["plant2_placed"] = True
            return (Tool.COALPOWER, p2x, p2y)
        else:
            state["plant2_placed"] = True  # give up

    return None

def act(obs, state):
    """
    Combined policy:
    - Horizontal wire spine from power plant (Parent A's spine approach)
    - Vertical wire branches every 4 cols (Parent A)
    - Two parallel road rows flanking the spine (Parent A)
    - Zones placed reactively near power+road (Parent A)
    - Second power plant when needed
    - Services when population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Anchor: place plant at left-center
    CX, CY = 20, 50

    # --- Phase 1: Place first coal power plant ---
    if not np.any(pm):
        return (Tool.COALPOWER, CX, CY)

    plant_ys, plant_xs = np.where(pm)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Wire spine runs horizontally at py
    spine_y = py
    wire_start_x = px + 3  # just right of plant footprint

    # Target wire end based on population
    if obs.city_pop < 200:
        target_wire_end = min(px + 50, WORLD_W - 4)
    elif obs.city_pop < 600:
        target_wire_end = min(px + 80, WORLD_W - 4)
    else:
        target_wire_end = min(px + 100, WORLD_W - 4)

    # --- Phase 2: Extend horizontal wire spine ---
    spine_wire_cols = [c for c in range(WORLD_W) if in_bounds(c, spine_y) and wm[spine_y, c]]

    if not spine_wire_cols:
        wx = wire_start_x
        if in_bounds(wx, spine_y) and em[spine_y, wx]:
            return (Tool.WIRE, wx, spine_y)
        # Try offset row
        for dy in [-1, 1]:
            wy = spine_y + dy
            if in_bounds(wx, wy) and em[wy, wx]:
                return (Tool.WIRE, wx, wy)
    else:
        max_wire_x = max(spine_wire_cols)
        if max_wire_x < target_wire_end:
            nx = max_wire_x + 1
            if in_bounds(nx, spine_y) and em[spine_y, nx] and not pm[spine_y, nx]:
                return (Tool.WIRE, nx, spine_y)

    # --- Phase 3: Vertical wire branches from spine every 4 cols ---
    branch_cols = list(range(wire_start_x + 2, target_wire_end + 1, 4))
    for bx in branch_cols:
        if not in_bounds(bx, spine_y):
            continue
        if not (bool(wm[spine_y, bx]) or bool(pm[spine_y, bx])):
            continue
        for sign in [-1, 1]:
            for dy in range(1, 5):
                wy = spine_y + sign * dy
                if not in_bounds(bx, wy):
                    break
                if bool(wm[wy, bx]) or bool(pm[wy, bx]):
                    continue
                if bool(em[wy, bx]):
                    return (Tool.WIRE, bx, wy)
                break

    # --- Phase 4: Build two parallel road rows flanking spine ---
    road_top = spine_y - 3
    road_bot = spine_y + 3

    road_start = wire_start_x
    road_end = target_wire_end

    # Top road
    if 0 <= road_top < WORLD_H:
        road_top_cols = [c for c in range(WORLD_W) if rm[road_top, c]]
        if not road_top_cols:
            rx = road_start
            if in_bounds(rx, road_top) and em[road_top, rx] and not wm[road_top, rx]:
                return (Tool.ROAD, rx, road_top)
        else:
            max_top = max(road_top_cols)
            if max_top < road_end:
                nx = max_top + 1
                if in_bounds(nx, road_top) and em[road_top, nx] and not wm[road_top, nx] and not pm[road_top, nx]:
                    return (Tool.ROAD, nx, road_top)

    # Bottom road
    if 0 <= road_bot < WORLD_H:
        road_bot_cols = [c for c in range(WORLD_W) if rm[road_bot, c]]
        if not road_bot_cols:
            rx = road_start
            if in_bounds(rx, road_bot) and em[road_bot, rx] and not wm[road_bot, rx]:
                return (Tool.ROAD, rx, road_bot)
        else:
            max_bot = max(road_bot_cols)
            if max_bot < road_end:
                nx = max_bot + 1
                if in_bounds(nx, road_bot) and em[road_bot, nx] and not wm[road_bot, nx] and not pm[road_bot, nx]:
                    return (Tool.ROAD, nx, road_bot)

    # --- Phase 5: Vertical connector roads every 4 cols between road rows ---
    for vc in range(road_start, road_end + 1, 4):
        for vr in range(road_top, road_bot + 1):
            if not in_bounds(vc, vr):
                continue
            if bool(rm[vr, vc]) or bool(pm[vr, vc]) or bool(wm[vr, vc]) or not bool(em[vr, vc]):
                continue
            connected = any(
                in_bounds(vc + dc, vr + dr) and bool(rm[vr + dr, vc + dc])
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]
            )
            if connected:
                return (Tool.ROAD, vc, vr)

    # --- Phase 6: Place zones reactively near wire+road ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_set = set()
    for arr in [resm, comm, indm]:
        ys2, xs2 = np.where(arr)
        for y2, x2 in zip(ys2.tolist(), xs2.tolist()):
            zone_set.add((int(y2), int(x2)))

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        step_hash = int(obs.step * 13 + int(obs.city_pop * 5)) % max(len(cxs_arr), 1)
        for offset in range(min(len(cxs_arr), 100)):
            k = (step_hash + offset * 7) % len(cxs_arr)
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # --- Phase 7: Second coal plant when city grows ---
    if total_zones > 8 or obs.city_pop > 150:
        p2x = min(px + 50, WORLD_W - 5)
        p2y = py
        nearby_plant = any(
            in_bounds(p2x + dx, p2y + dy) and bool(pm[p2y + dy, p2x + dx])
            for dy in range(-8, 9) for dx in range(-8, 9)
        )
        if not nearby_plant and in_bounds(p2x, p2y) and bool(em[p2y, p2x]):
            return (Tool.COALPOWER, p2x, p2y)

    # Third plant if really growing
    if obs.city_pop > 500:
        p3x = min(px + 90, WORLD_W - 5)
        p3y = py
        nearby_plant = any(
            in_bounds(p3x + dx, p3y + dy) and bool(pm[p3y + dy, p3x + dx])
            for dy in range(-8, 9) for dx in range(-8, 9)
        )
        if not nearby_plant and in_bounds(p3x, p3y) and bool(em[p3y, p3x]):
            return (Tool.COALPOWER, p3x, p3y)

    # --- Phase 8: Services ---
    if obs.city_pop > 200:
        fx, fy = px + 8, py - 9
        if in_bounds(fx, fy) and bool(em[fy, fx]):
            return (Tool.FIRESTATION, fx, fy)
        px2, py2 = px + 8, py + 9
        if in_bounds(px2, py2) and bool(em[py2, px2]):
            return (Tool.POLICESTATION, px2, py2)

    # --- Phase 9: Fallback wire extension ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        candidates = sorted(zip(wire_xs_arr.tolist(), wire_ys_arr.tolist()), key=lambda t: -t[0])
        for wx_s, wy_s in candidates[:15]:
            for dx2, dy2 in [(1, 0), (0, -1), (0, 1), (-1, 0)]:
                nx2, ny2 = wx_s + dx2, wy_s + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # --- Phase 10: Fallback road extension ---
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        candidates_r = sorted(zip(road_xs_arr.tolist(), road_ys_arr.tolist()), key=lambda t: -t[0])
        for rx_s, ry_s in candidates_r[:15]:
            for dx2, dy2 in [(1, 0), (0, -1), (0, 1), (-1, 0)]:
                nx2, ny2 = rx_s + dx2, ry_s + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and not bool(wm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Improved policy: horizontal road/wire layout instead of vertical columns.
    Build two rows of zones (top and bottom of a horizontal wire spine),
    with road rows parallel to wire, giving denser zone coverage.
    Also uses a more balanced zone mix: 40% res, 30% com, 30% ind.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    # Center of operations - shifted left to give more room
    cx, cy = 50, 50

    has_plant = np.any(pm)
    has_wire = np.any(wm)
    has_road = np.any(rm)

    # Phase 1: Place coal power plant at top-left of our cluster
    plant_cx, plant_cy = cx - 15, cy
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    wire_positions = set(zip(*np.where(wm))) if has_wire else set()
    road_positions = set(zip(*np.where(rm))) if has_road else set()
    res_positions = set(zip(*np.where(res_mask(tm))))
    com_positions = set(zip(*np.where(com_mask(tm))))
    ind_positions = set(zip(*np.where(ind_mask(tm))))
    all_zones = res_positions | com_positions | ind_positions

    res_count = len(res_positions)
    com_count = len(com_positions)
    ind_count = len(ind_positions)

    # Horizontal wire spine row
    wire_row = cy
    road_row_top = cy - 1    # road above wire
    road_row_bot = cy + 1    # road below wire

    # Zone rows (centered 3 tiles away from road rows)
    zone_row_top = road_row_top - 3   # cy - 4
    zone_row_bot = road_row_bot + 3   # cy + 4

    # Horizontal extent based on population
    base_span = 12
    extra_span = min(30, obs.city_pop // 20)
    target_span = base_span + extra_span
    xmin = max(2, plant_cx + 3)
    xmax = min(WORLD_W - 3, plant_cx + 3 + target_span)

    # Phase 2: Extend wire spine horizontally
    wire_cols_in_row = sorted(c for (r, c) in wire_positions if r == wire_row)

    if not wire_cols_in_row:
        # Start wire adjacent to plant
        start_x = plant_cx + 2
        if 0 <= start_x < WORLD_W and 0 <= wire_row < WORLD_H:
            return (Tool.WIRE, start_x, wire_row)
    else:
        min_wc = min(wire_cols_in_row)
        max_wc = max(wire_cols_in_row)
        if max_wc < xmax:
            nc = max_wc + 1
            if 0 <= nc < WORLD_W and (em[wire_row, nc] or wm[wire_row, nc]):
                return (Tool.WIRE, nc, wire_row)
        if min_wc > xmin:
            nc = min_wc - 1
            if 0 <= nc < WORLD_W and (em[wire_row, nc] or wm[wire_row, nc]):
                return (Tool.WIRE, nc, wire_row)

    wire_cols_set = set(wire_cols_in_row)

    # Phase 3: Build road rows parallel to wire (top and bottom)
    if wire_cols_in_row:
        road_cols_top = set(c for (r, c) in road_positions if r == road_row_top)
        road_cols_bot = set(c for (r, c) in road_positions if r == road_row_bot)

        for wc in wire_cols_in_row:
            if wc not in road_cols_top and 0 <= road_row_top < WORLD_H and 0 <= wc < WORLD_W:
                if em[road_row_top, wc]:
                    return (Tool.ROAD, wc, road_row_top)
            if wc not in road_cols_bot and 0 <= road_row_bot < WORLD_H and 0 <= wc < WORLD_W:
                if em[road_row_bot, wc]:
                    return (Tool.ROAD, wc, road_row_bot)

    # Helper functions
    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def already_zone_nearby(zr, zc):
        return any(abs(zr - pr) <= 1 and abs(zc - pc) <= 1 for (pr, pc) in all_zones)

    def choose_zone_type(row_is_top):
        # Aim for ~40% res, ~30% com, ~30% ind
        total = res_count + com_count + ind_count + 1
        if ind_count / total < 0.28:
            return Tool.INDUSTRIAL
        elif com_count / total < 0.28:
            return Tool.COMMERCIAL
        else:
            return Tool.RESIDENTIAL

    # Phase 4: Place zones adjacent to road rows
    if wire_cols_in_row:
        road_cols_top = set(c for (r, c) in road_positions if r == road_row_top)
        road_cols_bot = set(c for (r, c) in road_positions if r == road_row_bot)

        for wc in sorted(wire_cols_in_row):
            wire_nearby = wc in wire_cols_set
            if not wire_nearby:
                continue

            # Top zone row
            road_nearby_top = any(abs(wc - rc) <= 2 for rc in road_cols_top)
            if road_nearby_top:
                zr = zone_row_top
                zc = wc
                if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                    if not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                        return (choose_zone_type(True), zc, zr)

            # Bottom zone row
            road_nearby_bot = any(abs(wc - rc) <= 2 for rc in road_cols_bot)
            if road_nearby_bot:
                zr = zone_row_bot
                zc = wc
                if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                    if not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                        return (choose_zone_type(False), zc, zr)

    # Phase 5: Add vertical connector roads/wires between road rows and zone rows
    if wire_cols_in_row:
        for wc in wire_cols_in_row:
            # Vertical road from road_row_top to zone_row_top
            for zr in range(zone_row_top + 2, road_row_top):
                if 0 <= zr < WORLD_H and 0 <= wc < WORLD_W and em[zr, wc]:
                    return (Tool.ROAD, wc, zr)
            # Vertical road from road_row_bot to zone_row_bot
            for zr in range(road_row_bot + 1, zone_row_bot - 1):
                if 0 <= zr < WORLD_H and 0 <= wc < WORLD_W and em[zr, wc]:
                    return (Tool.ROAD, wc, zr)

    # Phase 6: Second expansion - add another horizontal cluster below
    if obs.city_pop > 150:
        wire_row2 = cy + 12
        road_row2_top = wire_row2 - 1
        road_row2_bot = wire_row2 + 1
        zone_row2_top = wire_row2 - 4
        zone_row2_bot = wire_row2 + 4

        wire_cols2 = sorted(c for (r, c) in wire_positions if r == wire_row2)

        if not wire_cols2:
            # Connect vertically from main wire spine
            for vr in range(wire_row + 1, wire_row2 + 1):
                if 0 <= vr < WORLD_H and (em[vr, plant_cx + 3] or wm[vr, plant_cx + 3]):
                    return (Tool.WIRE, plant_cx + 3, vr)
        else:
            min_wc2 = min(wire_cols2)
            max_wc2 = max(wire_cols2)
            xmax2 = min(WORLD_W - 3, plant_cx + 3 + target_span)

            if max_wc2 < xmax2:
                nc = max_wc2 + 1
                if 0 <= nc < WORLD_W and (em[wire_row2, nc] or wm[wire_row2, nc]):
                    return (Tool.WIRE, nc, wire_row2)

            # Roads for second cluster
            road_cols2_top = set(c for (r, c) in road_positions if r == road_row2_top)
            road_cols2_bot = set(c for (r, c) in road_positions if r == road_row2_bot)

            for wc in wire_cols2:
                if wc not in road_cols2_top and 0 <= road_row2_top < WORLD_H:
                    if em[road_row2_top, wc]:
                        return (Tool.ROAD, wc, road_row2_top)
                if wc not in road_cols2_bot and 0 <= road_row2_bot < WORLD_H:
                    if em[road_row2_bot, wc]:
                        return (Tool.ROAD, wc, road_row2_bot)

            # Zones for second cluster
            road_cols2_top_set = set(c for (r, c) in road_positions if r == road_row2_top)
            road_cols2_bot_set = set(c for (r, c) in road_positions if r == road_row2_bot)
            wire_cols2_set = set(wire_cols2)

            for wc in sorted(wire_cols2):
                road_near_top2 = any(abs(wc - rc) <= 2 for rc in road_cols2_top_set)
                road_near_bot2 = any(abs(wc - rc) <= 2 for rc in road_cols2_bot_set)

                if road_near_top2:
                    zr, zc = zone_row2_top, wc
                    if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                        if not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                            return (choose_zone_type(True), zc, zr)
                if road_near_bot2:
                    zr, zc = zone_row2_bot, wc
                    if 0 <= zr < WORLD_H and 0 <= zc < WORLD_W:
                        if not already_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                            return (choose_zone_type(False), zc, zr)

    # Phase 7: Second coal plant when population demands it
    if obs.city_pop > 400 and not state.get("second_plant", False):
        plant2_cx, plant2_cy = cx + 20, cy - 10
        plant2_clear = all(
            em[plant2_cy + dr, plant2_cx + dc]
            for dr in [-1, 0, 1] for dc in [-1, 0, 1]
            if 0 <= plant2_cy + dr < WORLD_H and 0 <= plant2_cx + dc < WORLD_W
        )
        if plant2_clear:
            state["second_plant"] = True
            return (Tool.COALPOWER, plant2_cx, plant2_cy)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Each step reads tile_map to decide next action
    - Builds a compact city around x=60, y=50 with coal plant + wire spine + roads + zones
    - Adapts to what already exists on the map
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    all_zones = resm | comm | indm
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def area_free(cx, cy):
        if cx < 1 or cx > WORLD_W - 2 or cy < 1 or cy > WORLD_H - 2:
            return False
        for dy in [-1, 0, 1]:
            for dx in [-1, 0, 1]:
                r, c = cy + dy, cx + dx
                if not (0 <= r < WORLD_H and 0 <= c < WORLD_W):
                    return False
                if not em[r, c]:
                    return False
        return True

    def zone_exists_near(cx, cy, radius=2):
        r0 = max(0, cy - radius)
        r1 = min(WORLD_H, cy + radius + 1)
        c0 = max(0, cx - radius)
        c1 = min(WORLD_W, cx + radius + 1)
        return np.any(all_zones[r0:r1, c0:c1])

    def has_wire_near(cx, cy, radius=5):
        r0 = max(0, cy - radius)
        r1 = min(WORLD_H, cy + radius + 1)
        c0 = max(0, cx - radius)
        c1 = min(WORLD_W, cx + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_near(cx, cy, radius=4):
        r0 = max(0, cy - radius)
        r1 = min(WORLD_H, cy + radius + 1)
        c0 = max(0, cx - radius)
        c1 = min(WORLD_W, cx + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    def pick_zone():
        t = max(1, total_zones)
        if res_count / t < 0.45:
            return Tool.RESIDENTIAL
        elif com_count / t < 0.30:
            return Tool.COMMERCIAL
        elif ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Single central neighborhood centered around (60, 50)
    # with vertical wire spine at x=60, horizontal roads at y=44 and y=56
    # zones placed on left (x~52) and right (x~68) sides

    cx_center = 60
    cy_center = 50
    wire_col = 60
    road_y_top = 44
    road_y_bot = 56
    road_x_start = 50
    road_x_end = 70

    # Dynamic vertical extent based on population
    if pop < 50:
        v_extent = 6
    elif pop < 200:
        v_extent = 12
    elif pop < 500:
        v_extent = 18
    elif pop < 1000:
        v_extent = 24
    else:
        v_extent = 30

    spine_top = max(2, cy_center - v_extent)
    spine_bot = min(WORLD_H - 3, cy_center + v_extent)

    # ---- Step 1: Ensure coal plant exists ----
    # Look for any plant on the map
    plant_locs = np.argwhere(pm)
    has_plant = len(plant_locs) > 0

    if not has_plant:
        # Place coal plant at center
        for dy in range(-4, 5):
            for dx in range(-4, 5):
                npx, npy = cx_center + dx, cy_center + dy
                if area_free(npx, npy):
                    return (Tool.COALPOWER, npx, npy)
        return None

    # Find nearest plant to our center
    dists = [abs(r - cy_center) + abs(c - wire_col) for r, c in plant_locs]
    best_idx = int(np.argmin(dists))
    plant_cy, plant_cx = int(plant_locs[best_idx][0]), int(plant_locs[best_idx][1])

    # ---- Step 2: Build wire spine from plant outward ----
    wire_on_col = [r for r in range(WORLD_H) if wm[r, wire_col]]

    # First wire: connect from plant toward spine
    if not wire_on_col:
        # Place wire adjacent to plant on the spine column
        # Walk from plant row toward cy_center
        for nr in range(plant_cy, spine_top - 1, -1):
            if 0 <= nr < WORLD_H:
                if pm[nr, wire_col]:
                    continue
                if em[nr, wire_col] or wm[nr, wire_col]:
                    return (Tool.WIRE, wire_col, nr)
                else:
                    break
        for nr in range(plant_cy, spine_bot + 1):
            if 0 <= nr < WORLD_H:
                if pm[nr, wire_col]:
                    continue
                if em[nr, wire_col] or wm[nr, wire_col]:
                    return (Tool.WIRE, wire_col, nr)
                else:
                    break
    else:
        min_wr = min(wire_on_col)
        max_wr = max(wire_on_col)

        # Extend wire downward
        if max_wr < spine_bot:
            nr = max_wr + 1
            if 0 <= nr < WORLD_H and not pm[nr, wire_col] and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

        # Extend wire upward
        if min_wr > spine_top:
            nr = min_wr - 1
            if 0 <= nr < WORLD_H and not pm[nr, wire_col] and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

        # ---- Step 3: Build horizontal roads ----
        # Top road row
        for road_y in [road_y_top, road_y_bot]:
            for rc in range(road_x_start - 2, road_x_end + 3):
                if 0 <= rc < WORLD_W and 0 <= road_y < WORLD_H:
                    if em[road_y, rc] and not pm[road_y, rc]:
                        return (Tool.ROAD, rc, road_y)

        # Vertical road connectors on left and right sides
        for rc in [road_x_start, road_x_end]:
            for ry in range(road_y_top, road_y_bot + 1):
                if 0 <= rc < WORLD_W and 0 <= ry < WORLD_H:
                    if em[ry, rc] and not pm[ry, rc]:
                        return (Tool.ROAD, rc, ry)

        # ---- Step 4: Extend lateral wires from spine ----
        wire_rows_set = set(wire_on_col)
        # At road row heights, extend wires left and right
        for wr in wire_on_col:
            if abs(wr - road_y_top) <= 3 or abs(wr - road_y_bot) <= 3 or abs(wr - cy_center) <= 3:
                # Wire leftward to zone columns
                for wcc in range(wire_col - 1, road_x_start - 4, -1):
                    if 0 <= wcc < WORLD_W:
                        if wm[wr, wcc]:
                            break
                        if pm[wr, wcc]:
                            break
                        if em[wr, wcc]:
                            return (Tool.WIRE, wcc, wr)
                        else:
                            break
                # Wire rightward
                for wcc in range(wire_col + 1, road_x_end + 4):
                    if 0 <= wcc < WORLD_W:
                        if wm[wr, wcc]:
                            break
                        if pm[wr, wcc]:
                            break
                        if em[wr, wcc]:
                            return (Tool.WIRE, wcc, wr)
                        else:
                            break

        # ---- Step 5: Place zones ----
        # Zone columns on left and right of spine
        zone_x_left = [road_x_start - 3, road_x_start + 3, wire_col - 6]
        zone_x_right = [wire_col + 6, road_x_end - 3, road_x_end + 3]
        zone_xs = zone_x_left + [wire_col] + zone_x_right

        # Zone rows: above top road, between roads, below bot road
        zone_ys = [road_y_top - 3, (road_y_top + road_y_bot) // 2, road_y_bot + 3]

        # Add more rows as pop grows
        if pop > 100:
            zone_ys += [road_y_top - 6, road_y_bot + 6]
        if pop > 300:
            zone_ys += [road_y_top - 9, road_y_bot + 9]

        for zy in zone_ys:
            if 1 <= zy <= WORLD_H - 2:
                for zx in zone_xs:
                    if 1 <= zx <= WORLD_W - 2:
                        if not zone_exists_near(zx, zy, 2) and area_free(zx, zy):
                            if has_wire_near(zx, zy, 6) and has_road_near(zx, zy, 6):
                                return (pick_zone(), zx, zy)

        # Dynamic scan: any empty spot near wire + road
        for zy in range(spine_top + 3, spine_bot - 2, 3):
            wire_near = any(abs(zy - wr) <= 3 for wr in wire_rows_set)
            if wire_near and has_road_near(wire_col, zy, 8):
                for zx in [wire_col - 6, wire_col - 3, wire_col + 3, wire_col + 6,
                           wire_col - 9, wire_col + 9]:
                    if 1 <= zx <= WORLD_W - 2:
                        if not zone_exists_near(zx, zy, 2) and area_free(zx, zy):
                            return (pick_zone(), zx, zy)

    # ---- Step 6: Second coal plant if population demands more power ----
    if pop > 400:
        plant_count = int(np.sum(pm)) // 9
        if plant_count < 2:
            # Place second plant to the right of center
            for offset_x in [20, -20, 15, -15]:
                npx, npy = cx_center + offset_x, cy_center
                if area_free(npx, npy):
                    return (Tool.COALPOWER, npx, npy)

    # ---- Step 7: Wire up second plant if it exists ----
    if len(plant_locs) > 1:
        # Connect second plant to wire grid by placing wires
        for i, (pr, pc) in enumerate(plant_locs):
            # Check if plant is connected to a wire nearby
            r0, r1 = max(0, pr - 3), min(WORLD_H, pr + 4)
            c0, c1 = max(0, pc - 3), min(WORLD_W, pc + 4)
            if not np.any(wm[r0:r1, c0:c1]):
                # Place wire adjacent to this plant toward wire_col
                direction = 1 if pc < wire_col else -1
                wc = pc + direction * 2
                wr = pr
                if 0 <= wc < WORLD_W and 0 <= wr < WORLD_H and (em[wr, wc] or wm[wr, wc]):
                    return (Tool.WIRE, wc, wr)

    # ---- Step 8: Services for happiness ----
    if pop > 300:
        # Police station
        for px, py in [(cx_center - 15, cy_center - 8), (cx_center + 15, cy_center - 8)]:
            if 1 <= px <= WORLD_W - 2 and 1 <= py <= WORLD_H - 2:
                if area_free(px, py):
                    near = tm[max(0, py-5):min(WORLD_H, py+6), max(0, px-5):min(WORLD_W, px+6)]
                    if not np.any((near >= 600) & (near <= 750)):
                        return (Tool.POLICESTATION, px, py)

    if pop > 600:
        for px, py in [(cx_center - 15, cy_center + 8), (cx_center + 15, cy_center + 8)]:
            if 1 <= px <= WORLD_W - 2 and 1 <= py <= WORLD_H - 2:
                if area_free(px, py):
                    return (Tool.FIRESTATION, px, py)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy combining both parents:
    - Horizontal wire spine (Parent B) for easier layout
    - Two coal plants placed early
    - Vertical road spurs for zone access
    - Reactive zone placement reading actual map state
    - Expands coverage as population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.28:
            return Tool.INDUSTRIAL
        if c_r < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Wire spine row - horizontal
    wire_row = 50

    # ---- Phase 1: Place first coal plant if missing ----
    if not np.any(pm):
        return (Tool.COALPOWER, 20, wire_row)

    plant_ys, plant_xs = np.where(pm)

    # ---- Phase 2: Place second coal plant on the right ----
    has_right_plant = any(
        in_bounds(90 + dx, wire_row + dy) and pm[wire_row + dy, 90 + dx]
        for dy in range(-4, 5) for dx in range(-4, 5)
    )
    if not has_right_plant and (total_zones > 6 or obs.city_pop > 50):
        # First build wire bridge to right plant location
        wire_in_row = [c for c in range(WORLD_W) if wm[wire_row, c]]
        if wire_in_row and max(wire_in_row) >= 85:
            if in_bounds(90, wire_row) and (em[wire_row, 90] or wm[wire_row, 90]):
                if not pm[wire_row, 90]:
                    return (Tool.COALPOWER, 90, wire_row)
        # Otherwise extend wire toward right plant first (handled below)

    # ---- Phase 3: Horizontal wire spine ----
    pop_factor = min(60, obs.city_pop // 8)
    hmin = max(2, 15)
    hmax = min(WORLD_W - 3, 95 + min(20, pop_factor))

    wire_in_row = sorted(c for c in range(WORLD_W) if wm[wire_row, c])

    if not wire_in_row:
        # Start wire adjacent to plant
        px0 = int(plant_xs[0])
        py0 = int(plant_ys[0])
        for dx in range(1, 5):
            nx = px0 + dx
            if in_bounds(nx, wire_row) and em[wire_row, nx] and not pm[wire_row, nx]:
                return (Tool.WIRE, nx, wire_row)
        for dx in range(-1, -5, -1):
            nx = px0 + dx
            if in_bounds(nx, wire_row) and em[wire_row, nx] and not pm[wire_row, nx]:
                return (Tool.WIRE, nx, wire_row)
    else:
        min_wc = wire_in_row[0]
        max_wc = wire_in_row[-1]
        # Extend rightward
        if max_wc < hmax:
            nc = max_wc + 1
            if in_bounds(nc, wire_row) and (em[wire_row, nc] or wm[wire_row, nc]) and not pm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)
        # Extend leftward
        if min_wc > hmin:
            nc = min_wc - 1
            if in_bounds(nc, wire_row) and (em[wire_row, nc] or wm[wire_row, nc]) and not pm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    wire_set = set(wire_in_row)

    # ---- Phase 4: Roads directly above and below spine ----
    road_row_up = wire_row - 2
    road_row_dn = wire_row + 2

    for wc in wire_in_row:
        if hmin <= wc <= hmax:
            if in_bounds(wc, road_row_up) and em[road_row_up, wc]:
                return (Tool.ROAD, wc, road_row_up)
            if in_bounds(wc, road_row_dn) and em[road_row_dn, wc]:
                return (Tool.ROAD, wc, road_row_dn)

    # ---- Phase 5: Vertical road spurs every 6 columns ----
    spur_depth = min(12, 4 + obs.city_pop // 40)
    for wc in wire_in_row:
        if wc % 6 == 0 and hmin <= wc <= hmax:
            for dr in range(3, spur_depth):
                ny = wire_row - dr
                if in_bounds(wc, ny) and em[ny, wc]:
                    return (Tool.ROAD, wc, ny)
            for dr in range(3, spur_depth):
                ny = wire_row + dr
                if in_bounds(wc, ny) and em[ny, wc]:
                    return (Tool.ROAD, wc, ny)

    # ---- Phase 6: Reactive zone placement ----
    # Build neighbor-of-road and neighbor-of-wire/plant masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and not zone_tiles[nr, nc]:
                    return False
        return True

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False
    # Don't place zones on wire row itself
    cand_mask[wire_row, :] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        dists = np.abs(cys - wire_row)
        order = np.argsort(dists)
        step_off = int(obs.step * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 80:
                break

    # ---- Phase 7: Extend roads from existing roads near wire ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 20)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx]:
                    if nbr_wire[ny, nx]:
                        return (Tool.ROAD, nx, ny)

    # ---- Phase 8: Services when pop high enough ----
    if obs.city_pop > 200:
        for fsx, fsy in [(20, wire_row - 8), (90, wire_row - 8),
                         (20, wire_row + 8), (90, wire_row + 8)]:
            if in_bounds(fsx, fsy) and em[fsy, fsx]:
                return (Tool.FIRESTATION, fsx, fsy)

    if obs.city_pop > 400:
        for psx, psy in [(50, wire_row - 8), (50, wire_row + 8)]:
            if in_bounds(psx, psy) and em[psy, psx]:
                return (Tool.POLICESTATION, psx, psy)

    # ---- Phase 9: Third coal plant in center for large cities ----
    if obs.city_pop > 500 and not state.get("plant3_placed", False):
        cx3, cy3 = 55, wire_row
        if in_bounds(cx3, cy3) and em[cy3, cx3]:
            state["plant3_placed"] = True
            return (Tool.COALPOWER, cx3, cy3)

    # ---- Phase 10: Grow wire laterally if stuck ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 15)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = wx + dx2, wy + dy2
                if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                    if ny2 == wire_row:  # keep spine growing
                        return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Variation: Horizontal wire spine instead of vertical, with zones on both sides.
    Uses a grid-based approach: horizontal wire row, road rows above and below,
    zones packed horizontally. Second plant placed early. Better zone mix management.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Place coal power plant at a good location
    has_plant = np.any(pm)
    if not has_plant:
        return (Tool.COALPOWER, 30, 50)

    plant_ys, plant_xs = np.where(pm)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        r_r = res_count / t
        c_r = com_count / t
        i_r = ind_count / t
        # Target: 50% res, 25% com, 25% ind
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Horizontal wire spine row
    wire_row = py + 2  # just below plant center

    # Horizontal span: grows with population
    base_span = 15
    extra_span = min(35, obs.city_pop // 15)
    target_span = base_span + extra_span
    tmin_col = max(2, px - target_span)
    tmax_col = min(WORLD_W - 3, px + target_span)

    wire_cols_in_row = sorted(c for c in range(WORLD_W) if wm[wire_row, c])

    # Step 2: Build horizontal wire spine
    if not wire_cols_in_row:
        # Start wire adjacent to plant
        for dx in range(-2, 3):
            nx = px + dx
            if in_bounds(nx, wire_row) and em[wire_row, nx]:
                return (Tool.WIRE, nx, wire_row)
    else:
        min_wc = min(wire_cols_in_row)
        max_wc = max(wire_cols_in_row)
        # Extend rightward
        if max_wc < tmax_col:
            nc = max_wc + 1
            if in_bounds(nc, wire_row) and (em[wire_row, nc] or wm[wire_row, nc]):
                return (Tool.WIRE, nc, wire_row)
        # Extend leftward
        if min_wc > tmin_col:
            nc = min_wc - 1
            if in_bounds(nc, wire_row) and (em[wire_row, nc] or wm[wire_row, nc]):
                return (Tool.WIRE, nc, wire_row)

    # Road rows: one above and one below wire spine
    road_row_above = wire_row - 1
    road_row_below = wire_row + 1

    # Step 3: Build road rows along wire spine
    for wc in wire_cols_in_row:
        if in_bounds(wc, road_row_above) and em[road_row_above, wc]:
            return (Tool.ROAD, wc, road_row_above)
        if in_bounds(wc, road_row_below) and em[road_row_below, wc]:
            return (Tool.ROAD, wc, road_row_below)

    # Build neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_set = set(zip(
        np.concatenate([np.where(resm)[0], np.where(comm)[0], np.where(indm)[0]]).tolist(),
        np.concatenate([np.where(resm)[1], np.where(comm)[1], np.where(indm)[1]]).tolist()
    ))

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    # Candidate zone centers: near road AND wire
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        step_hash = int(obs.step * 17 + total_zones * 7) % max(len(cxs), 1)
        for offset in range(min(len(cxs), 80)):
            k = (step_hash + offset * 13) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # Extend roads outward from existing roads
    road_rows_arr, road_cols_arr = np.where(rm)
    if len(road_rows_arr) > 0:
        for dy, dx in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            step_k = int(obs.step * 11) % max(len(road_rows_arr), 1)
            ry_s = int(road_rows_arr[step_k])
            rx_s = int(road_cols_arr[step_k])
            nx2, ny2 = rx_s + dx, ry_s + dy
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                if nbr_wire[ny2, nx2]:
                    return (Tool.ROAD, nx2, ny2)

    # Second power plant - placed earlier and to the right
    if total_zones > 10 or obs.city_pop > 200:
        p2x = px + 30
        p2y = py
        if in_bounds(p2x, p2y):
            nearby_plant = False
            for dy in range(-6, 7):
                for dx in range(-6, 7):
                    ny2, nx2 = p2y + dy, p2x + dx
                    if in_bounds(nx2, ny2) and pm[ny2, nx2]:
                        nearby_plant = True
            if not nearby_plant and em[p2y, p2x]:
                return (Tool.COALPOWER, p2x, p2y)
            # Connect with horizontal wire at wire_row
            for wc in range(min(wire_cols_in_row) if wire_cols_in_row else px,
                           p2x - 1 if in_bounds(p2x - 1, wire_row) else px):
                if in_bounds(wc, wire_row) and em[wire_row, wc]:
                    return (Tool.WIRE, wc, wire_row)

    # Add a second horizontal wire row further from center for more zones
    if obs.city_pop > 300 or total_zones > 20:
        wire_row2 = py - 5  # second spine above
        wire_cols2 = sorted(c for c in range(WORLD_W) if wm[wire_row2, c])
        if not wire_cols2:
            # Connect vertically from wire_row to wire_row2
            for wy in range(wire_row2, wire_row):
                if in_bounds(px + 2, wy) and em[wy, px + 2]:
                    return (Tool.WIRE, px + 2, wy)
        else:
            min_wc2 = min(wire_cols2)
            max_wc2 = max(wire_cols2)
            if max_wc2 < tmax_col:
                nc = max_wc2 + 1
                if in_bounds(nc, wire_row2) and (em[wire_row2, nc] or wm[wire_row2, nc]):
                    return (Tool.WIRE, nc, wire_row2)
            if min_wc2 > tmin_col:
                nc = min_wc2 - 1
                if in_bounds(nc, wire_row2) and (em[wire_row2, nc] or wm[wire_row2, nc]):
                    return (Tool.WIRE, nc, wire_row2)
            # Road above and below wire_row2
            rr2a = wire_row2 - 1
            rr2b = wire_row2 + 1
            for wc in wire_cols2:
                if in_bounds(wc, rr2a) and em[rr2a, wc]:
                    return (Tool.ROAD, wc, rr2a)
                if in_bounds(wc, rr2b) and em[rr2b, wc]:
                    return (Tool.ROAD, wc, rr2b)

    # Services
    if obs.city_pop > 150:
        fx, fy = px - 5, py + 8
        if in_bounds(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
        fx2, fy2 = px + 8, py + 8
        if in_bounds(fx2, fy2) and em[fy2, fx2]:
            return (Tool.POLICESTATION, fx2, fy2)

    # Extend wire frontier
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 7) % max(len(wire_xs_arr), 1)
        wx_s = int(wire_xs_arr[step_k2])
        wy_s = int(wire_ys_arr[step_k2])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = wx_s + dx2, wy_s + dy2
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map every step to find where power/roads reach
    - Places coal plant, then wires north+south from plant
    - Builds roads adjacent to wire
    - Places zones where both wire and road coverage exist
    - Uses a horizontal wire arm to reach second cluster
    - Adapts to actual observed map state
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    pop = obs.city_pop

    def pick_tool():
        t = max(total_zones, 1)
        # aim: ~20% ind, ~25% com, rest res
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- Phase 1: Place coal plant if none ----
    if not np.any(pm):
        return (Tool.COALPOWER, 60, 50)

    plant_ys, plant_xs = np.where(pm)
    px = int(np.median(plant_xs))
    py = int(np.median(plant_ys))

    # Primary wire spine runs vertically at px+3
    wire_col = px + 3
    wire_col = max(3, min(WORLD_W - 4, wire_col))

    # Two road columns flanking wire
    road_col_l = wire_col - 2
    road_col_r = wire_col + 2
    road_col_l = max(3, min(WORLD_W - 4, road_col_l))
    road_col_r = max(3, min(WORLD_W - 4, road_col_r))

    # Spine extent grows with pop
    if pop < 50:
        spine_half = 10
    elif pop < 200:
        spine_half = 16
    elif pop < 500:
        spine_half = 24
    elif pop < 900:
        spine_half = 32
    else:
        spine_half = 38

    target_min = max(2, py - spine_half)
    target_max = min(WORLD_H - 3, py + spine_half)

    wire_rows = [r for r in range(WORLD_H) if wm[r, wire_col]]

    # ---- Phase 2: Bootstrap wire adjacent to plant ----
    if not wire_rows:
        # Try to place a wire next to the plant
        for dy in range(-2, 3):
            nr = py + dy
            if in_bounds(wire_col, nr) and not pm[nr, wire_col]:
                if em[nr, wire_col] or wm[nr, wire_col]:
                    return (Tool.WIRE, wire_col, nr)
        # If plant occupies wire_col row, place adjacent row
        return (Tool.WIRE, wire_col, py)

    min_wr = min(wire_rows)
    max_wr = max(wire_rows)

    # ---- Phase 3: Extend wire spine ----
    # Alternate extending up/down based on step parity
    if obs.step % 2 == 0:
        if max_wr < target_max:
            nr = max_wr + 1
            if in_bounds(wire_col, nr) and not pm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)
        if min_wr > target_min:
            nr = min_wr - 1
            if in_bounds(wire_col, nr) and not pm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)
    else:
        if min_wr > target_min:
            nr = min_wr - 1
            if in_bounds(wire_col, nr) and not pm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)
        if max_wr < target_max:
            nr = max_wr + 1
            if in_bounds(wire_col, nr) and not pm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # ---- Phase 4: Fill road columns next to wire spine ----
    for wr in range(target_min, target_max + 1):
        if wm[wr, wire_col]:
            if in_bounds(road_col_l, wr) and em[wr, road_col_l]:
                return (Tool.ROAD, road_col_l, wr)
            if in_bounds(road_col_r, wr) and em[wr, road_col_r]:
                return (Tool.ROAD, road_col_r, wr)

    # ---- Build proximity masks (5x5 neighborhood) ----
    def expand_mask(base, radius=2):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-radius, radius + 1):
            for dx in range(-radius, radius + 1):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                result[r0:r1, c0:c1] |= base[sr0:sr1, sc0:sc1]
        return result

    nbr_road = expand_mask(rm, 2)
    nbr_wire = expand_mask(wm | pm, 2)
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and not zone_tiles[nr, nc]:
                    return False
        return True

    # ---- Phase 5: Place zones near wire + road coverage ----
    cand_mask = em & nbr_road & nbr_wire
    # Keep away from edges
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Sort by distance to wire column to prefer well-powered spots
        dists = np.abs(cxs - wire_col)
        order = np.argsort(dists)
        step_off = int(obs.step * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 100:
                break

    # ---- Phase 6: Second coal plant + wire bridge when pop grows ----
    num_plant_tiles = int(np.sum(pm))
    if pop > 300 and num_plant_tiles < 18:
        p2x = px - 22  # place to the LEFT this time for variety
        p2y = py
        p2x = max(3, min(WORLD_W - 4, p2x))
        p2y = max(3, min(WORLD_H - 4, p2y))
        area_ok = True
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = p2y + dr, p2x + dc
                if not in_bounds(rc, rr) or (not em[rr, rc] and not pm[rr, rc]):
                    area_ok = False
                    break
        if area_ok:
            return (Tool.COALPOWER, p2x, p2y)
        # Lay horizontal wire bridge from wire spine to second plant area
        bridge_col = wire_col - 1
        if bridge_col > p2x:
            for wc in range(bridge_col, p2x, -1):
                if in_bounds(wc, py) and em[py, wc]:
                    return (Tool.WIRE, wc, py)

    # ---- Phase 7: Services ----
    if pop > 200:
        fsx, fsy = px - 8, py - 10
        fsx = max(1, min(WORLD_W - 2, fsx))
        fsy = max(1, min(WORLD_H - 2, fsy))
        if in_bounds(fsx, fsy) and em[fsy, fsx]:
            return (Tool.FIRESTATION, fsx, fsy)
        psx, psy = px - 8, py + 10
        psx = max(1, min(WORLD_W - 2, psx))
        psy = max(1, min(WORLD_H - 2, psy))
        if in_bounds(psx, psy) and em[psy, psx]:
            return (Tool.POLICESTATION, psx, psy)

    # ---- Phase 8: Extend roads from existing roads toward wire ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 30)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx]:
                    if nbr_wire[ny, nx]:
                        return (Tool.ROAD, nx, ny)

    # ---- Phase 9: Extend wire laterally from spine toward uncovered zones ----
    # Find zone tiles without wire coverage
    uncov_zones = zone_tiles & ~nbr_wire
    if np.any(uncov_zones):
        uz_ys, uz_xs = np.where(uncov_zones)
        # Pick nearest wire tile and extend toward the zone
        wire_ys_arr, wire_xs_arr = np.where(wm)
        if len(wire_xs_arr) > 0:
            k = int(obs.step * 7) % len(uz_xs)
            ux, uy = int(uz_xs[k]), int(uz_ys[k])
            # Find closest wire tile
            dists2 = np.abs(wire_xs_arr - ux) + np.abs(wire_ys_arr - uy)
            best = np.argmin(dists2)
            wx2, wy2 = int(wire_xs_arr[best]), int(wire_ys_arr[best])
            # Step one tile toward the uncovered zone
            dx2 = np.sign(ux - wx2)
            dy2 = np.sign(uy - wy2)
            if dx2 != 0:
                nx2, ny2 = wx2 + dx2, wy2
            else:
                nx2, ny2 = wx2, wy2 + dy2
            if in_bounds(nx2, ny2) and not pm[ny2, nx2]:
                return (Tool.WIRE, nx2, ny2)

    # ---- Phase 10: General wire extension ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 20)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx3, wy3 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx3, ny3 = wx3 + dx3, wy3 + dy3
                if in_bounds(nx3, ny3) and em[ny3, nx3] and not pm[ny3, nx3]:
                    return (Tool.WIRE, nx3, ny3)

    return None

def act(obs, state):
    """
    Hybrid policy combining Parent A's vertical wire spine + cluster expansion
    with Parent B's horizontal wire spine, compact zone placement, and early second plant.

    Strategy:
    1. Place coal plant near center-left
    2. Build BOTH a horizontal wire spine AND a vertical wire spine (cross pattern)
    3. Build road rows/cols adjacent to wire spines
    4. Pack zones near roads+wires using candidate mask approach (Parent B)
    5. Early second plant, multiple wire spines for more powered area
    6. Services when population warrants
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # ---- Place first coal power plant ----
    has_plant = np.any(pm)
    if not has_plant:
        return (Tool.COALPOWER, 35, 50)

    plant_ys, plant_xs = np.where(pm)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        r_r = res_count / t
        c_r = com_count / t
        i_r = ind_count / t
        # Target: 50% res, 25% com, 25% ind
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- Wire spine parameters ----
    # Horizontal spine row just below plant
    wire_row_h = py + 2
    # Vertical spine col just right of plant
    wire_col_v = px + 3

    # Span grows with population
    base_span = 18
    extra_span = min(40, obs.city_pop // 10)
    target_span = base_span + extra_span

    tmin_col = max(2, px - target_span)
    tmax_col = min(WORLD_W - 3, px + target_span)
    tmin_row = max(2, py - target_span)
    tmax_row = min(WORLD_H - 3, py + target_span)

    # ---- Build horizontal wire spine ----
    if 0 <= wire_row_h < WORLD_H:
        wire_cols_h = sorted(c for c in range(WORLD_W) if wm[wire_row_h, c])
        if not wire_cols_h:
            # Start wire adjacent to plant
            for dx in range(-2, 4):
                nx = px + dx
                if in_bounds(nx, wire_row_h) and em[wire_row_h, nx]:
                    return (Tool.WIRE, nx, wire_row_h)
        else:
            min_wc = min(wire_cols_h)
            max_wc = max(wire_cols_h)
            if max_wc < tmax_col:
                nc = max_wc + 1
                if in_bounds(nc, wire_row_h) and (em[wire_row_h, nc] or wm[wire_row_h, nc]):
                    return (Tool.WIRE, nc, wire_row_h)
            if min_wc > tmin_col:
                nc = min_wc - 1
                if in_bounds(nc, wire_row_h) and (em[wire_row_h, nc] or wm[wire_row_h, nc]):
                    return (Tool.WIRE, nc, wire_row_h)

    # ---- Build vertical wire spine ----
    if 0 <= wire_col_v < WORLD_W:
        wire_rows_v = sorted(r for r in range(WORLD_H) if wm[r, wire_col_v])
        if not wire_rows_v:
            for dy in range(-2, 4):
                ny = py + dy
                if in_bounds(wire_col_v, ny) and em[ny, wire_col_v]:
                    return (Tool.WIRE, wire_col_v, ny)
        else:
            min_wr = min(wire_rows_v)
            max_wr = max(wire_rows_v)
            if max_wr < tmax_row:
                nr = max_wr + 1
                if in_bounds(wire_col_v, nr) and (em[nr, wire_col_v] or wm[nr, wire_col_v]):
                    return (Tool.WIRE, wire_col_v, nr)
            if min_wr > tmin_row:
                nr = min_wr - 1
                if in_bounds(wire_col_v, nr) and (em[nr, wire_col_v] or wm[nr, wire_col_v]):
                    return (Tool.WIRE, wire_col_v, nr)

    # ---- Build road rows adjacent to horizontal wire spine ----
    if 0 <= wire_row_h < WORLD_H:
        wire_cols_h = sorted(c for c in range(WORLD_W) if wm[wire_row_h, c])
        road_row_above = wire_row_h - 1
        road_row_below = wire_row_h + 1
        # Build roads along wire
        for wc in wire_cols_h:
            if in_bounds(wc, road_row_above) and em[road_row_above, wc]:
                return (Tool.ROAD, wc, road_row_above)
            if in_bounds(wc, road_row_below) and em[road_row_below, wc]:
                return (Tool.ROAD, wc, road_row_below)

    # ---- Build road cols adjacent to vertical wire spine ----
    if 0 <= wire_col_v < WORLD_W:
        wire_rows_v = sorted(r for r in range(WORLD_H) if wm[r, wire_col_v])
        road_col_left = wire_col_v - 1
        road_col_right = wire_col_v + 1
        for wr in wire_rows_v:
            if in_bounds(road_col_left, wr) and em[wr, road_col_left]:
                return (Tool.ROAD, road_col_left, wr)
            if in_bounds(road_col_right, wr) and em[wr, road_col_right]:
                return (Tool.ROAD, road_col_right, wr)

    # ---- Build neighbor proximity masks ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Existing zone cells (so we can check overlap)
    zone_set_rows = np.concatenate([np.where(resm)[0], np.where(comm)[0], np.where(indm)[0]])
    zone_set_cols = np.concatenate([np.where(resm)[1], np.where(comm)[1], np.where(indm)[1]])
    zone_set = set(zip(zone_set_rows.tolist(), zone_set_cols.tolist()))

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    # ---- Place zones near roads AND wires ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        step_hash = int(obs.step * 17 + total_zones * 7) % max(len(cxs), 1)
        for offset in range(min(len(cxs), 100)):
            k = (step_hash + offset * 13) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # ---- Second power plant (placed early) ----
    if (total_zones > 8 or obs.city_pop > 100) and not state.get("plant2_placed", False):
        p2x = px + 28
        p2y = py
        if in_bounds(p2x, p2y):
            nearby_plant = False
            for dy in range(-6, 7):
                for dx in range(-6, 7):
                    ny2, nx2 = p2y + dy, p2x + dx
                    if in_bounds(nx2, ny2) and pm[ny2, nx2]:
                        nearby_plant = True
            if not nearby_plant:
                # Check 3x3 is mostly empty
                area_ok = all(
                    in_bounds(p2x + dc, p2y + dr) and (em[p2y + dr, p2x + dc] or not pm[p2y + dr, p2x + dc])
                    for dr in [-1, 0, 1] for dc in [-1, 0, 1]
                )
                if area_ok:
                    state["plant2_placed"] = True
                    return (Tool.COALPOWER, p2x, p2y)
            # Connect wire to second plant location
            wire_cols_h = sorted(c for c in range(WORLD_W) if wm[wire_row_h, c])
            start_c = max(wire_cols_h) if wire_cols_h else px
            for wc in range(start_c, min(p2x, WORLD_W)):
                if in_bounds(wc, wire_row_h) and em[wire_row_h, wc]:
                    return (Tool.WIRE, wc, wire_row_h)

    # ---- Third power plant for large city ----
    if obs.city_pop > 500 and not state.get("plant3_placed", False):
        p3x = px - 20
        p3y = py
        if in_bounds(p3x, p3y):
            nearby_plant = False
            for dy in range(-6, 7):
                for dx in range(-6, 7):
                    ny2, nx2 = p3y + dy, p3x + dx
                    if in_bounds(nx2, ny2) and pm[ny2, nx2]:
                        nearby_plant = True
            if not nearby_plant:
                area_ok = all(
                    in_bounds(p3x + dc, p3y + dr) and em[p3y + dr, p3x + dc]
                    for dr in [-1, 0, 1] for dc in [-1, 0, 1]
                )
                if area_ok:
                    state["plant3_placed"] = True
                    return (Tool.COALPOWER, p3x, p3y)

    # ---- Second horizontal wire spine (above plant) ----
    if obs.city_pop > 200 or total_zones > 15:
        wire_row_h2 = py - 5
        if 0 <= wire_row_h2 < WORLD_H:
            wire_cols_h2 = sorted(c for c in range(WORLD_W) if wm[wire_row_h2, c])
            if not wire_cols_h2:
                # Connect vertically from wire_row_h to wire_row_h2
                for wy in range(wire_row_h2, wire_row_h):
                    cx_conn = wire_col_v
                    if in_bounds(cx_conn, wy) and em[wy, cx_conn]:
                        return (Tool.WIRE, cx_conn, wy)
            else:
                min_wc2 = min(wire_cols_h2)
                max_wc2 = max(wire_cols_h2)
                if max_wc2 < tmax_col:
                    nc = max_wc2 + 1
                    if in_bounds(nc, wire_row_h2) and (em[wire_row_h2, nc] or wm[wire_row_h2, nc]):
                        return (Tool.WIRE, nc, wire_row_h2)
                if min_wc2 > tmin_col:
                    nc = min_wc2 - 1
                    if in_bounds(nc, wire_row_h2) and (em[wire_row_h2, nc] or wm[wire_row_h2, nc]):
                        return (Tool.WIRE, nc, wire_row_h2)
                # Road rows for second spine
                rr2a = wire_row_h2 - 1
                rr2b = wire_row_h2 + 1
                for wc in wire_cols_h2:
                    if in_bounds(wc, rr2a) and em[rr2a, wc]:
                        return (Tool.ROAD, wc, rr2a)
                    if in_bounds(wc, rr2b) and em[rr2b, wc]:
                        return (Tool.ROAD, wc, rr2b)

    # ---- Third horizontal wire spine (below plant) ----
    if obs.city_pop > 400 or total_zones > 30:
        wire_row_h3 = py + 9
        if 0 <= wire_row_h3 < WORLD_H:
            wire_cols_h3 = sorted(c for c in range(WORLD_W) if wm[wire_row_h3, c])
            if not wire_cols_h3:
                for wy in range(wire_row_h + 1, wire_row_h3 + 1):
                    cx_conn = wire_col_v
                    if in_bounds(cx_conn, wy) and em[wy, cx_conn]:
                        return (Tool.WIRE, cx_conn, wy)
            else:
                min_wc3 = min(wire_cols_h3)
                max_wc3 = max(wire_cols_h3)
                if max_wc3 < tmax_col:
                    nc = max_wc3 + 1
                    if in_bounds(nc, wire_row_h3) and (em[wire_row_h3, nc] or wm[wire_row_h3, nc]):
                        return (Tool.WIRE, nc, wire_row_h3)
                if min_wc3 > tmin_col:
                    nc = min_wc3 - 1
                    if in_bounds(nc, wire_row_h3) and (em[wire_row_h3, nc] or wm[wire_row_h3, nc]):
                        return (Tool.WIRE, nc, wire_row_h3)
                rr3a = wire_row_h3 - 1
                rr3b = wire_row_h3 + 1
                for wc in wire_cols_h3:
                    if in_bounds(wc, rr3a) and em[rr3a, wc]:
                        return (Tool.ROAD, wc, rr3a)
                    if in_bounds(wc, rr3b) and em[rr3b, wc]:
                        return (Tool.ROAD, wc, rr3b)

    # ---- Extend roads near existing wire (fill gaps) ----
    road_rows_arr, road_cols_arr = np.where(rm)
    if len(road_rows_arr) > 0:
        step_k = int(obs.step * 11) % max(len(road_rows_arr), 1)
        for offset in range(min(len(road_rows_arr), 20)):
            ki = (step_k + offset * 3) % len(road_rows_arr)
            ry_s = int(road_rows_arr[ki])
            rx_s = int(road_cols_arr[ki])
            for dy, dx in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx_s + dx, ry_s + dy
                if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                    if nbr_wire[ny2, nx2]:
                        return (Tool.ROAD, nx2, ny2)

    # ---- Services ----
    if obs.city_pop > 200 and not state.get("fire1", False):
        fx, fy = px - 6, py + 10
        if in_bounds(fx, fy) and em[fy, fx]:
            state["fire1"] = True
            return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 300 and not state.get("police1", False):
        fx2, fy2 = px + 10, py + 10
        if in_bounds(fx2, fy2) and em[fy2, fx2]:
            state["police1"] = True
            return (Tool.POLICESTATION, fx2, fy2)
    if obs.city_pop > 600 and not state.get("fire2", False):
        fx3, fy3 = px + 20, py - 8
        if in_bounds(fx3, fy3) and em[fy3, fx3]:
            state["fire2"] = True
            return (Tool.FIRESTATION, fx3, fy3)

    # ---- Fallback: extend any wire frontier ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 7) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 20)):
            ki2 = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx_s = int(wire_xs_arr[ki2])
            wy_s = int(wire_ys_arr[ki2])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = wx_s + dx2, wy_s + dy2
                if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                    return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Improved city builder with:
    - Horizontal road/wire layout instead of vertical spine
    - Multiple power plants for wider coverage
    - Better zone mix: ~40% res, 30% com, 30% ind
    - Compact grid layout with roads every 4 rows
    - Two horizontal corridors with zones above/below
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # Initialize state
    if 'phase' not in state:
        state['phase'] = 0
        state['action_queue'] = []

    # Build action queue if empty
    def enqueue(actions):
        state['action_queue'].extend(actions)

    # Pop from queue if available
    if state['action_queue']:
        while state['action_queue']:
            act_item = state['action_queue'].pop(0)
            tool, x, y = act_item
            if 0 <= x < WORLD_W and 0 <= y < WORLD_H:
                return (tool, x, y)

    # Live map analysis
    res_positions = set(zip(*np.where(res_m))) if np.any(res_m) else set()
    com_positions = set(zip(*np.where(com_m))) if np.any(com_m) else set()
    ind_positions = set(zip(*np.where(ind_m))) if np.any(ind_m) else set()
    all_zones = res_positions | com_positions | ind_positions
    res_count = len(res_positions)
    com_count = len(com_positions)
    ind_count = len(ind_positions)

    # Layout: horizontal corridors
    # Plant 1 at (30, 45), Plant 2 at (80, 45)
    # Road rows at y=40, y=50, y=60 (horizontal)
    # Wire rows at y=41, y=51, y=61 (one below each road row)
    # Zones in columns 20..100, centered between road rows

    plant1_x, plant1_y = 30, 45
    plant2_x, plant2_y = 80, 45

    has_plant1 = np.any(pm[plant1_y-1:plant1_y+2, plant1_x-1:plant1_x+2])
    has_plant2 = np.any(pm[plant2_y-1:plant2_y+2, plant2_x-1:plant2_x+2])

    # Phase: place plants first
    if not has_plant1:
        return (Tool.COALPOWER, plant1_x, plant1_y)
    if not has_plant2 and obs.city_pop >= 0:
        return (Tool.COALPOWER, plant2_x, plant2_y)

    # Road rows (horizontal)
    road_rows = [38, 48, 58]
    # Wire rows (horizontal, to carry power from plants to zones)
    wire_rows = [39, 49, 59]

    # Column range for roads/wires
    col_start = 18
    col_end = 102

    # Build horizontal roads
    for row in road_rows:
        for col in range(col_start, col_end):
            if 0 <= col < WORLD_W and 0 <= row < WORLD_H:
                if em[row, col]:
                    return (Tool.ROAD, col, row)

    # Build horizontal wires
    for row in wire_rows:
        for col in range(col_start, col_end):
            if 0 <= col < WORLD_W and 0 <= row < WORLD_H:
                if em[row, col]:
                    return (Tool.WIRE, col, row)

    # Connect plant1 to wire rows with vertical wires
    for wr in wire_rows:
        # Vertical wire from plant1_x connecting to wire row
        y_min = min(plant1_y, wr)
        y_max = max(plant1_y, wr)
        for yy in range(y_min, y_max + 1):
            if em[yy, plant1_x] or wm[yy, plant1_x]:
                if em[yy, plant1_x]:
                    return (Tool.WIRE, plant1_x, yy)

    for wr in wire_rows:
        y_min = min(plant2_y, wr)
        y_max = max(plant2_y, wr)
        for yy in range(y_min, y_max + 1):
            if em[yy, plant2_x] or wm[yy, plant2_x]:
                if em[yy, plant2_x]:
                    return (Tool.WIRE, plant2_x, yy)

    # Zone placement: place zones between road rows
    # Zone rows (centers): 34, 44, 54, 64 (spacing 4 from road rows with gap)
    # Actually between road rows: between 38 and 48 => zone_y=43, between 48 and 58 => zone_y=53
    # Above first road: zone_y=34, below last road: zone_y=63
    zone_row_centers = [33, 43, 53, 63]
    # Zone columns every 6 starting from col_start+3
    zone_cols = list(range(col_start + 3, col_end - 2, 6))

    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def near_road_or_wire(zr, zc):
        # Check if any adjacent tile is road or wire
        for dr in range(-2, 3):
            for dc in range(-2, 3):
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if rm[rr, rc] or wm[rr, rc]:
                        return True
        return False

    def pick_zone_type():
        # ~35% res, 35% com, 30% ind
        if res_count == 0:
            return Tool.RESIDENTIAL
        if com_count == 0:
            return Tool.COMMERCIAL
        if ind_count == 0:
            return Tool.INDUSTRIAL
        total = res_count + com_count + ind_count
        res_ratio = res_count / total
        com_ratio = com_count / total
        ind_ratio = ind_count / total
        if ind_ratio < 0.28:
            return Tool.INDUSTRIAL
        elif com_ratio < 0.30:
            return Tool.COMMERCIAL
        elif res_ratio < 0.38:
            return Tool.RESIDENTIAL
        else:
            return Tool.COMMERCIAL

    # Try to place zones
    for zr in zone_row_centers:
        for zc in zone_cols:
            if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                if zone_area_free(zr, zc) and near_road_or_wire(zr, zc):
                    return (pick_zone_type(), zc, zr)

    # Expand: add more road rows if pop growing
    if obs.city_pop >= 150:
        extra_road_rows = [28, 68]
        extra_wire_rows = [29, 69]
        for row in extra_road_rows:
            for col in range(col_start, col_end):
                if 0 <= col < WORLD_W and 0 <= row < WORLD_H:
                    if em[row, col]:
                        return (Tool.ROAD, col, row)
        for row in extra_wire_rows:
            for col in range(col_start, col_end):
                if 0 <= col < WORLD_W and 0 <= row < WORLD_H:
                    if em[row, col]:
                        return (Tool.WIRE, col, row)
        # Connect plant1 to extra wires
        for wr in extra_wire_rows:
            y_min = min(plant1_y, wr)
            y_max = max(plant1_y, wr)
            for yy in range(y_min, y_max + 1):
                if em[yy, plant1_x]:
                    return (Tool.WIRE, plant1_x, yy)
            for yy in range(y_min, y_max + 1):
                if em[yy, plant2_x]:
                    return (Tool.WIRE, plant2_x, yy)
        extra_zone_rows = [23, 73]
        for zr in extra_zone_rows:
            for zc in zone_cols:
                if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                    if zone_area_free(zr, zc) and near_road_or_wire(zr, zc):
                        return (pick_zone_type(), zc, zr)

    # Add a third power plant centrally if needed for high pop
    if obs.city_pop >= 300:
        plant3_x, plant3_y = 55, 45
        has_plant3 = np.any(pm[plant3_y-1:plant3_y+2, plant3_x-1:plant3_x+2])
        if not has_plant3 and em[plant3_y, plant3_x]:
            return (Tool.COALPOWER, plant3_x, plant3_y)

    return None

def act(obs, state):
    """
    Redesigned policy:
    - Uses a horizontal road spine instead of vertical wire spine
    - Places coal plant, then runs wire horizontally, roads above/below
    - Zones flanking roads, with IND/COM/RES mix
    - Two clusters: left and right of center
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # Initialize state
    if 'phase' not in state:
        state['phase'] = 0
        state['wire_progress'] = 0
        state['road1_progress'] = 0
        state['road2_progress'] = 0

    # Layout: horizontal spine near center
    # Plant at (30, 50)
    # Wire row: row 50, cols 35..90
    # Road rows: 47 and 53
    # Zones in rows 44 (top zones) and 56 (bottom zones)
    # Zone cols at 38, 44, 50, 56, 62, 68, 74, 80, 86

    plant_x, plant_y = 30, 50
    wire_row = 50
    road_row_top = wire_row - 3   # 47
    road_row_bot = wire_row + 3   # 53
    zone_row_top = wire_row - 6   # 44
    zone_row_bot = wire_row + 6   # 56

    wire_start = plant_x + 5   # 35
    wire_end = 90

    zone_cols = list(range(38, 88, 6))  # 38,44,50,56,62,68,74,80,86

    has_plant = np.any(pm)

    # Phase 0: Place coal plant
    if not has_plant:
        return (Tool.COALPOWER, plant_x, plant_y)

    # Find actual plant position
    plant_rows, plant_cols = np.where(pm)
    if len(plant_rows) > 0:
        pr, pc = plant_rows[0], plant_cols[0]
        plant_x, plant_y = pc, pr
        wire_start = plant_x + 5
        wire_row = plant_y

    # Phase 1: Build horizontal wire spine
    for wc in range(wire_start, wire_end + 1):
        if not wm[wire_row, wc]:
            return (Tool.WIRE, wc, wire_row)

    # Phase 2: Build top road row
    road_r = road_row_top
    if 0 <= road_r < WORLD_H:
        for rc in range(wire_start - 2, wire_end + 1):
            if 0 <= rc < WORLD_W and not rm[road_r, rc]:
                return (Tool.ROAD, rc, road_r)

    # Phase 3: Build bottom road row
    road_r = road_row_bot
    if 0 <= road_r < WORLD_H:
        for rc in range(wire_start - 2, wire_end + 1):
            if 0 <= rc < WORLD_W and not rm[road_r, rc]:
                return (Tool.ROAD, rc, road_r)

    # Helper: check 3x3 zone footprint clear
    def zone_clear(zr, zc):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                r2, c2 = zr + dr, zc + dc
                if r2 < 0 or r2 >= WORLD_H or c2 < 0 or c2 >= WORLD_W:
                    return False
                if not em[r2, c2]:
                    return False
        return True

    def zone_exists_near(zr, zc):
        r1 = max(0, zr - 2); r2 = min(WORLD_H, zr + 3)
        c1 = max(0, zc - 2); c2 = min(WORLD_W, zc + 3)
        return np.any(res_m[r1:r2, c1:c2] | com_m[r1:r2, c1:c2] | ind_m[r1:r2, c1:c2])

    def near_wire(zr, zc):
        r1 = max(0, zr - 2); r2 = min(WORLD_H, zr + 3)
        c1 = max(0, zc - 2); c2 = min(WORLD_W, zc + 3)
        return np.any(wm[r1:r2, c1:c2])

    def near_road(zr, zc):
        r1 = max(0, zr - 2); r2 = min(WORLD_H, zr + 3)
        c1 = max(0, zc - 2); c2 = min(WORLD_W, zc + 3)
        return np.any(rm[r1:r2, c1:c2])

    # Phase 4: Connect wire vertically to road rows
    # Place vertical wires from wire_row up to road_row_top and down to road_row_bot
    for zc in zone_cols:
        if 0 <= zc < WORLD_W:
            # Upward: wire_row-1 down to road_row_top+1
            for r in range(wire_row - 1, road_row_top - 1, -1):
                if 0 <= r < WORLD_H and not wm[r, zc] and em[r, zc]:
                    return (Tool.WIRE, zc, r)
            # Downward: wire_row+1 to road_row_bot+1
            for r in range(wire_row + 1, road_row_bot + 2):
                if 0 <= r < WORLD_H and not wm[r, zc] and em[r, zc]:
                    return (Tool.WIRE, zc, r)

    res_count = int(np.sum(res_m)) // 9 + 1
    com_count = int(np.sum(com_m)) // 9 + 1
    ind_count = int(np.sum(ind_m)) // 9 + 1

    # Phase 5: Place zones at top row
    for i, zc in enumerate(zone_cols):
        zr = zone_row_top
        if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
            if not zone_exists_near(zr, zc) and zone_clear(zr, zc):
                if near_wire(zr, zc) and near_road(zr, zc):
                    # Mix: IND first, then COM, then RES
                    if ind_count < max(2, res_count // 3):
                        return (Tool.INDUSTRIAL, zc, zr)
                    elif com_count < max(2, res_count // 2):
                        return (Tool.COMMERCIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

    # Phase 6: Place zones at bottom row
    for i, zc in enumerate(zone_cols):
        zr = zone_row_bot
        if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
            if not zone_exists_near(zr, zc) and zone_clear(zr, zc):
                if near_wire(zr, zc) and near_road(zr, zc):
                    if com_count < max(2, res_count // 2):
                        return (Tool.COMMERCIAL, zc, zr)
                    elif ind_count < max(2, res_count // 3):
                        return (Tool.INDUSTRIAL, zc, zr)
                    else:
                        return (Tool.RESIDENTIAL, zc, zr)

    # Phase 7: Add a second wire row above/below for more coverage
    wire_row2_top = wire_row - 12
    wire_row2_bot = wire_row + 12
    zone_row_top2 = wire_row2_top - 4
    zone_row_bot2 = wire_row2_bot + 4

    # Wire horizontal row 2 top
    if 0 <= wire_row2_top < WORLD_H:
        for wc in range(wire_start, wire_end + 1):
            if not wm[wire_row2_top, wc] and em[wire_row2_top, wc]:
                return (Tool.WIRE, wc, wire_row2_top)

    # Wire horizontal row 2 bot
    if 0 <= wire_row2_bot < WORLD_H:
        for wc in range(wire_start, wire_end + 1):
            if not wm[wire_row2_bot, wc] and em[wire_row2_bot, wc]:
                return (Tool.WIRE, wc, wire_row2_bot)

    # Connect wire rows vertically
    for zc in zone_cols:
        if 0 <= zc < WORLD_W:
            for r in range(wire_row2_top, wire_row):
                if not wm[r, zc] and em[r, zc]:
                    return (Tool.WIRE, zc, r)
            for r in range(wire_row, wire_row2_bot + 1):
                if not wm[r, zc] and em[r, zc]:
                    return (Tool.WIRE, zc, r)

    # Roads for second tier
    road_r = wire_row2_top - 2
    if 0 <= road_r < WORLD_H:
        for rc in range(wire_start - 2, wire_end + 1):
            if 0 <= rc < WORLD_W and not rm[road_r, rc] and em[road_r, rc]:
                return (Tool.ROAD, rc, road_r)

    road_r = wire_row2_bot + 2
    if 0 <= road_r < WORLD_H:
        for rc in range(wire_start - 2, wire_end + 1):
            if 0 <= rc < WORLD_W and not rm[road_r, rc] and em[road_r, rc]:
                return (Tool.ROAD, rc, road_r)

    # Second tier zones
    for zc in zone_cols:
        for zr in [zone_row_top2, zone_row_bot2]:
            if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                if not zone_exists_near(zr, zc) and zone_clear(zr, zc):
                    if near_wire(zr, zc) and near_road(zr, zc):
                        if res_count > (com_count + ind_count):
                            if com_count <= ind_count:
                                return (Tool.COMMERCIAL, zc, zr)
                            else:
                                return (Tool.INDUSTRIAL, zc, zr)
                        else:
                            return (Tool.RESIDENTIAL, zc, zr)

    # Phase 8: Add police/fire stations for coverage
    if obs.city_pop > 50:
        # Police station near center
        for zc in [55, 65]:
            zr = wire_row
            if 1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1:
                r1 = max(0, zr - 1); r2 = min(WORLD_H, zr + 2)
                c1 = max(0, zc - 1); c2 = min(WORLD_W, zc + 2)
                tile_slice = tm[r1:r2, c1:c2]
                # Check if area has only wire/road
                area_em = em[r1:r2, c1:c2]
                area_wm = wm[r1:r2, c1:c2]
                area_rm = rm[r1:r2, c1:c2]
                if np.all(area_em | area_wm | area_rm):
                    pass  # skip placing on infrastructure

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Each step reads tile_map fresh and decides next action
    - Single compact neighborhood centered around (60, 50)
    - Grows power spine outward from coal plant, then roads, then zones
    - Adapts placement based on current map state
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    all_zones = resm | comm | indm

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def area_free(cx, cy):
        if cx < 1 or cx > WORLD_W - 2 or cy < 1 or cy > WORLD_H - 2:
            return False
        for dy in [-1, 0, 1]:
            for dx in [-1, 0, 1]:
                r, c = cy + dy, cx + dx
                if not (0 <= r < WORLD_H and 0 <= c < WORLD_W):
                    return False
                if not em[r, c]:
                    return False
        return True

    def zone_exists_near(cx, cy, radius=3):
        r0 = max(0, cy - radius)
        r1 = min(WORLD_H, cy + radius + 1)
        c0 = max(0, cx - radius)
        c1 = min(WORLD_W, cx + radius + 1)
        return np.any(all_zones[r0:r1, c0:c1])

    def has_wire_near(cx, cy, radius=4):
        r0 = max(0, cy - radius)
        r1 = min(WORLD_H, cy + radius + 1)
        c0 = max(0, cx - radius)
        c1 = min(WORLD_W, cx + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_near(cx, cy, radius=4):
        r0 = max(0, cy - radius)
        r1 = min(WORLD_H, cy + radius + 1)
        c0 = max(0, cx - radius)
        c1 = min(WORLD_W, cx + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    def pick_zone():
        t = max(1, total_zones)
        if res_count / t < 0.45:
            return Tool.RESIDENTIAL
        elif com_count / t < 0.28:
            return Tool.COMMERCIAL
        elif ind_count / t < 0.27:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Central power plant target
    plant_cx, plant_cy = 60, 50

    # Check if any plant exists on map
    plant_rows, plant_cols = np.where(pm)
    has_plant = len(plant_rows) > 0

    # --- Step 1: Place coal plant if none exists ---
    if not has_plant:
        if area_free(plant_cx, plant_cy):
            return (Tool.COALPOWER, plant_cx, plant_cy)
        # Try nearby
        for dy in range(-4, 5):
            for dx in range(-4, 5):
                nx, ny = plant_cx + dx, plant_cy + dy
                if area_free(nx, ny):
                    return (Tool.COALPOWER, nx, ny)
        return None

    # Find actual plant center (centroid of plant tiles)
    plant_cy_actual = int(np.mean(plant_rows))
    plant_cx_actual = int(np.mean(plant_cols))

    # Determine growth extent based on pop
    if pop < 50:
        extent = 6
    elif pop < 150:
        extent = 10
    elif pop < 300:
        extent = 15
    elif pop < 500:
        extent = 20
    else:
        extent = 26

    # Wire spine: vertical column through plant_cx_actual
    spine_x = plant_cx_actual
    spine_top = max(2, plant_cy_actual - extent)
    spine_bot = min(WORLD_H - 3, plant_cy_actual + extent)

    # --- Step 2: Grow wire spine vertically ---
    wire_on_spine = [r for r in range(WORLD_H) if wm[r, spine_x]]

    if not wire_on_spine:
        # Start wire just above/below plant
        for dy in range(1, 8):
            for nr in [plant_cy_actual - dy, plant_cy_actual + dy]:
                if spine_top <= nr <= spine_bot and 0 <= nr < WORLD_H:
                    if em[nr, spine_x]:
                        return (Tool.WIRE, spine_x, nr)
    else:
        min_wr = min(wire_on_spine)
        max_wr = max(wire_on_spine)

        # Extend downward first
        if max_wr < spine_bot:
            nr = max_wr + 1
            if 0 <= nr < WORLD_H and not pm[nr, spine_x]:
                if em[nr, spine_x] or wm[nr, spine_x]:
                    return (Tool.WIRE, spine_x, nr)

        # Extend upward
        if min_wr > spine_top:
            nr = min_wr - 1
            if 0 <= nr < WORLD_H and not pm[nr, spine_x]:
                if em[nr, spine_x] or wm[nr, spine_x]:
                    return (Tool.WIRE, spine_x, nr)

    # --- Step 3: Extend lateral wires from spine to serve zones ---
    # Wire laterally at every 4th row of the spine
    wire_on_spine_set = set(wire_on_spine) if wire_on_spine else set()

    for wr in sorted(wire_on_spine_set):
        if wr < spine_top or wr > spine_bot:
            continue
        # Extend left
        for wcc in range(spine_x - 1, spine_x - 12, -1):
            if wcc < 0:
                break
            if wm[wr, wcc]:
                break
            if pm[wr, wcc]:
                break
            if rm[wr, wcc]:
                break  # don't overwrite roads
            if em[wr, wcc]:
                # Only extend if useful (every 4 steps left from spine)
                dist = spine_x - wcc
                if dist <= 10:
                    return (Tool.WIRE, wcc, wr)
            else:
                break
        # Extend right
        for wcc in range(spine_x + 1, spine_x + 12):
            if wcc >= WORLD_W:
                break
            if wm[wr, wcc]:
                break
            if pm[wr, wcc]:
                break
            if rm[wr, wcc]:
                break
            if em[wr, wcc]:
                dist = wcc - spine_x
                if dist <= 10:
                    return (Tool.WIRE, wcc, wr)
            else:
                break

    # --- Step 4: Build horizontal roads ---
    # Two horizontal roads: above and below center, spaced ~8 rows apart
    road_y_top = plant_cy_actual - 5
    road_y_bot = plant_cy_actual + 5

    road_x_left = spine_x - 9
    road_x_right = spine_x + 9

    for rrow in [road_y_top, road_y_bot]:
        if 1 <= rrow <= WORLD_H - 2:
            for rc in range(max(0, road_x_left), min(WORLD_W, road_x_right + 1)):
                if em[rrow, rc] and not pm[rrow, rc]:
                    return (Tool.ROAD, rc, rrow)

    # --- Step 5: Vertical road connectors ---
    for rc in [road_x_left + 2, spine_x - 4, spine_x + 4, road_x_right - 2]:
        if 0 <= rc < WORLD_W:
            for ry in range(min(road_y_top, road_y_bot), max(road_y_top, road_y_bot) + 1):
                if 0 <= ry < WORLD_H and em[ry, rc] and not pm[ry, rc]:
                    return (Tool.ROAD, rc, ry)

    # --- Step 6: Place zones near wires and roads ---
    # Zone slots: between the roads, and outside them
    zone_candidates = []
    for zy_offset in [-9, -3, 3, 9, 15, -15]:
        zy = plant_cy_actual + zy_offset
        for zx_offset in [-8, -4, 0, 4, 8]:
            zx = spine_x + zx_offset
            zone_candidates.append((zx, zy))

    for zx, zy in zone_candidates:
        if 1 <= zx <= WORLD_W - 2 and 1 <= zy <= WORLD_H - 2:
            if not zone_exists_near(zx, zy, 2) and area_free(zx, zy):
                if has_wire_near(zx, zy, 5) and has_road_near(zx, zy, 5):
                    return (pick_zone(), zx, zy)

    # --- Step 7: Dynamic scan for any empty zone spots near infrastructure ---
    for zy in range(spine_top + 2, spine_bot - 1, 3):
        if has_wire_near(spine_x, zy, 6) and has_road_near(spine_x, zy, 6):
            for zx_off in [-8, -5, -2, 2, 5, 8]:
                zx = spine_x + zx_off
                if 1 <= zx <= WORLD_W - 2 and 1 <= zy <= WORLD_H - 2:
                    if not zone_exists_near(zx, zy, 2) and area_free(zx, zy):
                        return (pick_zone(), zx, zy)

    # --- Step 8: Second power plant if pop growing ---
    if pop > 200:
        plant_count = int(np.sum(pm)) // 9
        if plant_count < 2:
            for dx in [20, -20, 25, -25]:
                nx, ny = plant_cx_actual + dx, plant_cy_actual
                if area_free(nx, ny):
                    return (Tool.COALPOWER, nx, ny)

    # --- Step 9: Services for happiness ---
    if pop > 200:
        for sx, sy in [(spine_x - 12, plant_cy_actual), (spine_x + 12, plant_cy_actual)]:
            if 1 <= sx <= WORLD_W - 2 and 1 <= sy <= WORLD_H - 2:
                if area_free(sx, sy):
                    near = tm[max(0, sy-6):min(WORLD_H, sy+7), max(0, sx-6):min(WORLD_W, sx+7)]
                    # Check no existing police/fire nearby (tile range ~600-800)
                    if not np.any((near >= 600) & (near <= 800)):
                        return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        for sx, sy in [(spine_x - 12, plant_cy_actual + 12), (spine_x + 12, plant_cy_actual + 12)]:
            if 1 <= sx <= WORLD_W - 2 and 1 <= sy <= WORLD_H - 2:
                if area_free(sx, sy):
                    return (Tool.FIRESTATION, sx, sy)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy combining both parents.
    - Vertical wire spine (Parent B style) for power distribution
    - Horizontal road rows (Parent A style) for zone access
    - Zones placed reactively based on current wire/road coverage
    - Adapts span/extent with population
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    # Phase 1: Place coal power plant near center-left
    if not np.any(pm):
        return (Tool.COALPOWER, cx - 10, cy)

    # Find plant centroid
    plant_rows, plant_cols = np.where(pm)
    pcx = int(np.mean(plant_cols))
    pcy = int(np.mean(plant_rows))

    # Layout constants derived from plant position
    wire_col = pcx + 2  # vertical wire spine just right of plant
    wire_col = max(2, min(WORLD_W - 3, wire_col))

    road_col_r = wire_col + 2  # road column right of wire spine
    road_col_r = max(2, min(WORLD_W - 3, road_col_r))

    # Horizontal road rows above and below center
    road_row_top = pcy - 4
    road_row_bot = pcy + 4
    road_row_top = max(2, min(WORLD_H - 3, road_row_top))
    road_row_bot = max(2, min(WORLD_H - 3, road_row_bot))

    # Zone rows adjacent to horizontal roads
    zone_row_above = road_row_top - 3
    zone_row_below = road_row_bot + 3
    zone_row_above = max(2, min(WORLD_H - 3, zone_row_above))
    zone_row_below = max(2, min(WORLD_H - 3, zone_row_below))

    # Spine extent grows with population
    if obs.city_pop < 100:
        spine_extent = 8
    elif obs.city_pop < 300:
        spine_extent = 14
    elif obs.city_pop < 600:
        spine_extent = 22
    else:
        spine_extent = 30

    target_min = max(2, cy - spine_extent)
    target_max = min(WORLD_H - 3, cy + spine_extent)

    # Horizontal span for roads/zones
    half_span = min(40, max(12, 12 + obs.city_pop // 8))
    col_min = max(2, pcx - half_span)
    col_max = min(WORLD_W - 3, pcx + half_span)

    # Current wire spine rows
    wire_rows = sorted(r for r in range(WORLD_H) if wm[r, wire_col])
    road_rows_r = sorted(r for r in range(WORLD_H) if rm[r, road_col_r])

    all_zone_mask = resm | comm | indm

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        if com_count / max(1, total_zones) < 0.25:
            return Tool.COMMERCIAL
        if ind_count / max(1, total_zones) < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Phase 2: Start vertical wire spine adjacent to plant if none
    if not wire_rows:
        for dy in range(0, 6):
            for nr in [pcy + dy, pcy - dy]:
                if 0 <= nr < WORLD_H and 0 <= wire_col < WORLD_W:
                    if em[nr, wire_col] or wm[nr, wire_col]:
                        return (Tool.WIRE, wire_col, nr)
        return None

    min_wr = min(wire_rows)
    max_wr = max(wire_rows)

    # Phase 3: Extend wire spine downward
    if max_wr < target_max:
        nr = max_wr + 1
        if nr < WORLD_H and not pm[nr, wire_col] and (em[nr, wire_col] or wm[nr, wire_col]):
            return (Tool.WIRE, wire_col, nr)

    # Phase 4: Extend wire spine upward
    if min_wr > target_min:
        nr = min_wr - 1
        if nr >= 0 and not pm[nr, wire_col] and (em[nr, wire_col] or wm[nr, wire_col]):
            return (Tool.WIRE, wire_col, nr)

    # Phase 5: Build horizontal road rows (top and bottom)
    # Top road row
    if 0 <= road_row_top < WORLD_H:
        for c in range(col_min, col_max + 1):
            if not rm[road_row_top, c] and em[road_row_top, c]:
                return (Tool.ROAD, c, road_row_top)

    # Bottom road row
    if 0 <= road_row_bot < WORLD_H:
        for c in range(col_min, col_max + 1):
            if not rm[road_row_bot, c] and em[road_row_bot, c]:
                return (Tool.ROAD, c, road_row_bot)

    # Phase 6: Lateral wires from vertical spine to reach zone columns
    # Extend left from spine toward col_min
    for wr in wire_rows:
        if target_min <= wr <= target_max:
            for wc in range(wire_col - 1, col_min - 1, -1):
                if 0 <= wc < WORLD_W:
                    if wm[wr, wc]:
                        break
                    if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    elif not em[wr, wc] and not wm[wr, wc]:
                        break

    # Phase 7: Extend road column rightward from spine
    for wr in wire_rows:
        if target_min <= wr <= target_max:
            if not rm[wr, road_col_r] and em[wr, road_col_r]:
                return (Tool.ROAD, road_col_r, wr)

    # Extend road rightward from road_col_r toward col_max
    for wr in wire_rows:
        if target_min <= wr <= target_max:
            if not rm[wr, road_col_r]:
                continue
            for rc in range(road_col_r + 1, min(col_max + 1, WORLD_W)):
                if rm[wr, rc]:
                    break
                if em[wr, rc] and not pm[wr, rc]:
                    return (Tool.ROAD, rc, wr)
                else:
                    break

    # Phase 8: Place zones above top road
    for c in range(col_min, col_max + 1, 3):
        zr = zone_row_above
        zc = c
        if 2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3:
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc, 5) and has_road_nearby(zr, zc, 5):
                    return (pick_tool(), zc, zr)

    # Place zones below bottom road
    for c in range(col_min, col_max + 1, 3):
        zr = zone_row_below
        zc = c
        if 2 <= zr <= WORLD_H - 3 and 2 <= zc <= WORLD_W - 3:
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc, 5) and has_road_nearby(zr, zc, 5):
                    return (pick_tool(), zc, zr)

    # Phase 9: Place zones along vertical wire spine (left and right)
    zone_rows_spine = list(range(target_min, target_max + 1, 3))
    left_zone_col = wire_col - 4
    right_zone_col = road_col_r + 3
    left_zone_col = max(2, min(WORLD_W - 3, left_zone_col))
    right_zone_col = max(2, min(WORLD_W - 3, right_zone_col))

    for zr in zone_rows_spine:
        # Left of wire spine
        if 2 <= left_zone_col <= WORLD_W - 3:
            if not zone_already_there(zr, left_zone_col) and zone_area_ok(zr, left_zone_col):
                if has_wire_nearby(zr, left_zone_col, 5) and has_road_nearby(zr, left_zone_col, 5):
                    return (pick_tool(), left_zone_col, zr)
        # Right of road col
        if 2 <= right_zone_col <= WORLD_W - 3:
            if not zone_already_there(zr, right_zone_col) and zone_area_ok(zr, right_zone_col):
                if has_wire_nearby(zr, right_zone_col, 5) and has_road_nearby(zr, right_zone_col, 5):
                    return (pick_tool(), right_zone_col, zr)

    # Phase 10: Wire to right zone column for power
    for wr in wire_rows:
        if target_min <= wr <= target_max:
            for wc in range(wire_col + 1, right_zone_col + 2):
                if 0 <= wc < WORLD_W:
                    if wm[wr, wc]:
                        break
                    if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    elif not em[wr, wc] and not wm[wr, wc] and not rm[wr, wc]:
                        break

    # Phase 11: Second coal plant when population is large
    if obs.city_pop > 400 and int(np.sum(pm)) < 18:
        px2 = pcx + 20
        py2 = pcy
        px2 = max(2, min(WORLD_W - 3, px2))
        py2 = max(2, min(WORLD_H - 3, py2))
        # Check if area is clear
        ok = all(
            0 <= py2 + dr < WORLD_H and 0 <= px2 + dc < WORLD_W and em[py2 + dr, px2 + dc]
            for dr in [-1, 0, 1] for dc in [-1, 0, 1]
        )
        if ok:
            return (Tool.COALPOWER, px2, py2)

    # Phase 12: Expand road and wire coverage further as city grows
    if obs.city_pop > 200:
        extra_left = col_min - 4
        extra_right = col_max + 4
        if extra_left >= 2:
            for zr in zone_rows_spine:
                if not zone_already_there(zr, extra_left) and zone_area_ok(zr, extra_left):
                    if has_road_nearby(zr, extra_left, 6) and has_wire_nearby(zr, extra_left, 7):
                        return (pick_tool(), extra_left, zr)
        if extra_right <= WORLD_W - 3:
            for zr in zone_rows_spine:
                if not zone_already_there(zr, extra_right) and zone_area_ok(zr, extra_right):
                    if has_road_nearby(zr, extra_right, 6) and has_wire_nearby(zr, extra_right, 7):
                        return (pick_tool(), extra_right, zr)

    # Phase 13: Vertical road connectors for grid connectivity
    if obs.city_pop > 100:
        for vc in range(col_min, col_max + 1, 6):
            for vr in range(road_row_top, road_row_bot + 1):
                if 0 <= vr < WORLD_H and 0 <= vc < WORLD_W:
                    if not rm[vr, vc] and em[vr, vc]:
                        return (Tool.ROAD, vc, vr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy. Reads tile_map every step and adapts.
    Key changes from parent:
    - Denser road grid (horizontal roads every 4 rows) for better zone access
    - More balanced zone placement with wider spread
    - Earlier second power plant
    - Smarter wire extension toward unserved zones
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Phase 1: Place first coal plant near center ---
    if not np.any(pm):
        return (Tool.COALPOWER, 60, 50)

    # Find plant center
    plant_ys, plant_xs = np.where(pm)
    px = int(np.median(plant_xs))
    py = int(np.median(plant_ys))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        # More industrial early (provides jobs), balanced later
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Wire spine: vertical column adjacent to plant ---
    wire_col = px + 2
    pop_factor = min(50, obs.city_pop // 8)
    tmin = max(2, py - 20 - pop_factor)
    tmax = min(WORLD_H - 3, py + 20 + pop_factor)

    wire_in_col = []
    if 0 <= wire_col < WORLD_W:
        wire_in_col = [r for r in range(WORLD_H) if wm[r, wire_col]]

    if not wire_in_col:
        # Seed wire adjacent to plant
        for dy in range(-2, 3):
            ny = py + dy
            if in_bounds(wire_col, ny) and not pm[ny, wire_col]:
                return (Tool.WIRE, wire_col, ny)
    else:
        min_wr = min(wire_in_col)
        max_wr = max(wire_in_col)
        if max_wr < tmax:
            nr = max_wr + 1
            if in_bounds(wire_col, nr) and not pm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)
        if min_wr > tmin:
            nr = min_wr - 1
            if in_bounds(wire_col, nr) and not pm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # --- Road columns flanking wire spine ---
    road_col_r = wire_col + 1
    road_col_l = wire_col - 1

    for wr in wire_in_col:
        if in_bounds(road_col_r, wr) and em[wr, road_col_r]:
            return (Tool.ROAD, road_col_r, wr)
        if in_bounds(road_col_l, wr) and em[wr, road_col_l]:
            return (Tool.ROAD, road_col_l, wr)

    # --- Horizontal roads every 4 rows to enable grid-based zone access ---
    if wire_in_col:
        min_wr = min(wire_in_col)
        max_wr = max(wire_in_col)
        # Place horizontal roads at regular intervals
        for row in range(min_wr, max_wr + 1):
            if (row - min_wr) % 4 == 0:
                # Extend roads left and right from the spine
                for spread in range(1, 15):
                    for sign in [1, -1]:
                        cx = wire_col + sign * spread
                        if in_bounds(cx, row) and em[row, cx] and not pm[row, cx]:
                            # Only place if connected to existing road
                            connected = False
                            for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
                                nx2, ny2 = cx+ddx, row+ddy
                                if in_bounds(nx2, ny2) and rm[ny2, nx2]:
                                    connected = True
                                    break
                            if connected:
                                return (Tool.ROAD, cx, row)

    # --- Build proximity masks for zone placement ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and not zone_tiles[nr, nc]:
                    return False
        return True

    # Candidate zone centers: near road AND near wire/plant
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Sort by distance to wire spine, prefer closer
        dists = np.abs(cxs - wire_col) + np.abs(cys - py) * 0.3
        order = np.argsort(dists)
        step_off = int(obs.step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 120:
                break

    # --- Second power plant earlier (when total_zones > 6) ---
    if total_zones > 6 or obs.city_pop > 150:
        p2x = px + 20
        p2y = py
        if in_bounds(p2x, p2y):
            nearby_plant = any(
                in_bounds(p2x + dx, p2y + dy) and pm[p2y + dy, p2x + dx]
                for dy in range(-5, 6) for dx in range(-5, 6)
            )
            if not nearby_plant and em[p2y, p2x]:
                return (Tool.COALPOWER, p2x, p2y)
            # Wire horizontal bridge from spine to second plant
            for wc in range(wire_col + 2, p2x - 1):
                if in_bounds(wc, py) and em[py, wc] and not pm[py, wc]:
                    return (Tool.WIRE, wc, py)
            # Second vertical wire spine
            wire_col2 = p2x - 2
            if wire_in_col:
                for wr in wire_in_col:
                    if in_bounds(wire_col2, wr) and em[wr, wire_col2]:
                        return (Tool.WIRE, wire_col2, wr)

    # --- Third power plant on the left side when city is large ---
    if total_zones > 20 or obs.city_pop > 400:
        p3x = px - 20
        p3y = py
        if in_bounds(p3x, p3y):
            nearby_plant = any(
                in_bounds(p3x + dx, p3y + dy) and pm[p3y + dy, p3x + dx]
                for dy in range(-5, 6) for dx in range(-5, 6)
            )
            if not nearby_plant and em[p3y, p3x]:
                return (Tool.COALPOWER, p3x, p3y)
            # Wire horizontal bridge from spine to third plant
            for wc in range(p3x + 2, wire_col - 1):
                if in_bounds(wc, py) and em[py, wc] and not pm[py, wc]:
                    return (Tool.WIRE, wc, py)

    # --- Extend roads near wire to fill gaps ---
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 30)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx] and nbr_wire[ny, nx]:
                    return (Tool.ROAD, nx, ny)

    # --- Services when pop is high enough ---
    if obs.city_pop > 80:
        fsx, fsy = px - 10, py - 10
        if in_bounds(fsx, fsy) and em[fsy, fsx]:
            return (Tool.FIRESTATION, fsx, fsy)
        psx, psy = px - 10, py + 10
        if in_bounds(psx, psy) and em[psy, psx]:
            return (Tool.POLICESTATION, psx, psy)

    # --- Expand wire laterally to reach new areas ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 20)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = wx + dx2, wy + dy2
                if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                    return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
