        for rx in range(62, 86):
            actions.append((Tool.ROAD, rx, 33))
        for wx in range(34, 87):
            actions.append((Tool.WIRE, wx, 36))
        for zx in range(38, 58, 3):
            actions.append((Tool.RESIDENTIAL, zx, 36))
        for zx in range(65, 85, 3):
            actions.append((Tool.COMMERCIAL, zx, 36))

        # === LOWER TIER: y=62..68 ===
        for wy in range(62, 68):
            actions.append((Tool.WIRE, wc1, wy))
        for wy in range(62, 68):
            actions.append((Tool.WIRE, wc2, wy))
        for rx in range(35, 60):
            actions.append((Tool.ROAD, rx, 67))
        for rx in range(62, 86):
            actions.append((Tool.ROAD, rx, 67))
        for wx in range(34, 87):
            actions.append((Tool.WIRE, wx, 64))
        for zx in range(38, 58, 3):
            actions.append((Tool.INDUSTRIAL, zx, 64))
        for zx in range(65, 85, 3):
            actions.append((Tool.RESIDENTIAL, zx, 64))

        # More residential fill-in
        for zx in range(38, 58, 3):
            actions.append((Tool.RESIDENTIAL, zx, 30))
        for zx in range(65, 85, 3):
            actions.append((Tool.RESIDENTIAL, zx, 30))
        for rx in range(35, 86):
            actions.append((Tool.ROAD, rx, 28))
        for wx in range(34, 87):
            actions.append((Tool.WIRE, wx, 30))

        state['queue'] = actions

    # Pop next queued action
    while state['queue']:
        action = state['queue'].pop(0)
        tool, ax, ay = action
        ax = max(0, min(WORLD_W - 1, ax))
        ay = max(0, min(WORLD_H - 1, ay))

        # For zones, check 3x3 area is mostly clear
        if tool in (Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.INDUSTRIAL):
            clear = True
            for dy in range(-1, 2):
                for dx in range(-1, 2):
                    ny, nx = ay + dy, ax + dx
                    if 0 <= ny < WORLD_H and 0 <= nx < WORLD_W:
                        if not em[ny, nx]:
                            clear = False
                            break
                if not clear:
                    break
            if not clear:
                continue  # skip blocked zone placements

        # Don't overwrite power plants with wire/road
        if tool in (Tool.WIRE, Tool.ROAD):
            if in_bounds(ax, ay) and pm[ay, ax]:
                continue

        return (tool, ax, ay)

    # === REACTIVE PHASE: fill remaining empty spots near infrastructure ===
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count + 1

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def expand_mask(base, radius=2):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-radius, radius + 1):
            for dx in range(-radius, radius + 1):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                result[r0:r1, c0:c1] |= base[sr0:sr1, sc0:sc1]
        return result

    nbr_road = expand_mask(rm, 2)
    power_src = wm | pm
    nbr_wire = expand_mask(power_src, 2)

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and not zone_tiles[nr, nc]:
                    return False
        return True

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        step_off = int(obs.step * 7) % max(len(cxs), 1)
        for i in range(min(len(cxs), 80)):
            k = (step_off + i) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # Extend roads if near wire
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 20)):
            k = (step_k + offset * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx2 + dx, ry2 + dy
                if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx]:
                    if nbr_wire[ny, nx]:
                        return (Tool.ROAD, nx, ny)

    # Add more services if population warrants
    if obs.city_pop > 300:
        plant_ys, plant_xs = np.where(pm)
        if len(plant_xs) < 3:
            p3x, p3y = 60, 30
            if in_bounds(p3x, p3y) and em[p3y, p3x]:
                return (Tool.COALPOWER, p3x, p3y)

    return None

def act(obs, state):
    """
    Closed-loop policy: each step reads the map and decides next placement.
    Strategy: compact vertical spine with power plant, wire column, road column,
    zones placed adjacent to existing infrastructure.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    all_zone_mask = resm | comm | indm

    # Count zones for mix decisions
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        if com_count / t < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zr, zc):
        # Check 3x3 area is empty or already zone
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_overlaps_existing(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    # Fixed anchor positions
    PLANT_X = 20
    PLANT_Y = 50
    WIRE_COL = 23   # wire runs vertically here
    ROAD_COL = 26   # road runs vertically here

    # Phase 1: Place coal power plant if none exists
    if not np.any(pm):
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    # Find actual plant position
    pr, pc = np.where(pm)
    plant_cy = int(np.mean(pr))
    plant_cx = int(np.mean(pc))

    # Phase 2: Connect wire from plant to wire column
    # Place wire adjacent to plant if not there
    wire_col = plant_cx + 3
    if wire_col >= WORLD_W:
        wire_col = plant_cx + 2

    # Scan for existing wire
    wire_rows = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])

    # Phase 2a: Start wire right of plant
    if not np.any(wm[plant_cy, plant_cx:plant_cx+8]):
        for dc in range(1, 8):
            nc = plant_cx + dc
            if 0 <= nc < WORLD_W and em[plant_cy, nc]:
                return (Tool.WIRE, nc, plant_cy)

    # Phase 2b: Extend wire vertically along wire_col
    # Determine vertical extent based on population
    if obs.city_pop < 50:
        spine_top = plant_cy - 6
        spine_bot = plant_cy + 6
    elif obs.city_pop < 200:
        spine_top = plant_cy - 15
        spine_bot = plant_cy + 15
    elif obs.city_pop < 500:
        spine_top = plant_cy - 25
        spine_bot = plant_cy + 25
    else:
        spine_top = plant_cy - 35
        spine_bot = plant_cy + 35

    spine_top = max(2, spine_top)
    spine_bot = min(WORLD_H - 3, spine_bot)

    # Extend wire spine downward from plant row
    if wire_rows:
        max_wr = max(wire_rows)
        min_wr = min(wire_rows)
        # Extend downward
        if max_wr < spine_bot:
            nr = max_wr + 1
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]) and not pm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if min_wr > spine_top:
            nr = min_wr - 1
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]) and not pm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)
    else:
        # Start wire at plant row
        if em[plant_cy, wire_col]:
            return (Tool.WIRE, wire_col, plant_cy)

    # Phase 3: Build road column parallel to wire
    road_col = wire_col + 3
    road_rows = sorted([r for r in range(WORLD_H) if rm[r, road_col]])

    if wire_rows:
        # Build road alongside wire rows
        for wr in sorted(wire_rows):
            if wr < spine_top or wr > spine_bot:
                continue
            if 0 <= road_col < WORLD_W and not rm[wr, road_col] and em[wr, road_col]:
                return (Tool.ROAD, road_col, wr)

    # Phase 4: Place zones adjacent to road column
    # Zones at wire_col+6 (right of road) and wire_col-3 (left of wire)
    zone_right_col = road_col + 3   # center of zone to right of road
    zone_left_col = wire_col - 3    # center of zone to left of wire

    # Place zones every 3 rows along the spine
    if wire_rows and road_rows:
        all_spine_rows = sorted(set(wire_rows) & set(road_rows))

        for zrow in all_spine_rows:
            if zrow < spine_top + 1 or zrow > spine_bot - 1:
                continue
            # Check every 3rd row
            if zrow % 3 != 0:
                continue

            # Try right zone
            zc = zone_right_col
            zr = zrow
            if (1 <= zc <= WORLD_W - 2 and 1 <= zr <= WORLD_H - 2
                    and not zone_overlaps_existing(zr, zc) and zone_area_ok(zr, zc)):
                # Check wire and road nearby
                r0, r1 = max(0, zr-4), min(WORLD_H, zr+5)
                c0, c1 = max(0, zc-4), min(WORLD_W, zc+5)
                if np.any(wm[r0:r1, c0:c1]) and np.any(rm[r0:r1, c0:c1]):
                    return (pick_tool(), zc, zr)

            # Try left zone
            zc = zone_left_col
            if (1 <= zc <= WORLD_W - 2 and 1 <= zr <= WORLD_H - 2
                    and not zone_overlaps_existing(zr, zc) and zone_area_ok(zr, zc)):
                r0, r1 = max(0, zr-4), min(WORLD_H, zr+5)
                c0, c1 = max(0, zc-4), min(WORLD_W, zc+5)
                if np.any(wm[r0:r1, c0:c1]) and np.any(rm[r0:r1, c0:c1]):
                    return (pick_tool(), zc, zr)

    # Phase 5: Horizontal wire connectors from wire_col to zones on left
    # Wire left zones need wire connection
    for zr in range(spine_top, spine_bot + 1, 3):
        if 0 <= zr < WORLD_H:
            # Check if there's a zone to the left that needs wire
            zc = zone_left_col
            if 0 <= zc < WORLD_W and all_zone_mask[zr, zc]:
                # Need wire between wire_col and zone
                for dc in range(wire_col - 1, zc + 1, -1):
                    if 0 <= dc < WORLD_W and not wm[zr, dc] and em[zr, dc]:
                        return (Tool.WIRE, dc, zr)

    # Phase 6: Road connectors from road_col to right zones
    for zr in range(spine_top, spine_bot + 1, 3):
        if 0 <= zr < WORLD_H:
            zc = zone_right_col
            if 0 <= zc < WORLD_W and all_zone_mask[zr, zc]:
                for dc in range(road_col + 1, zc):
                    if 0 <= dc < WORLD_W and not rm[zr, dc] and em[zr, dc]:
                        return (Tool.ROAD, dc, zr)

    # Phase 7: Second power plant when population grows
    if obs.city_pop > 400:
        plant2_x = plant_cx + 15
        plant2_y = plant_cy
        if 2 <= plant2_x <= WORLD_W - 3 and 2 <= plant2_y <= WORLD_H - 3:
            area_ok = True
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    rr, rc = plant2_y + dr, plant2_x + dc
                    if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                        if not (em[rr, rc] or pm[rr, rc]):
                            area_ok = False
            if area_ok and int(np.sum(pm)) < 18:
                return (Tool.COALPOWER, plant2_x, plant2_y)

    # Phase 8: Extend wire horizontally to reach second cluster
    if obs.city_pop > 600:
        wire2_row = plant_cy
        # Extend wire row to the right for a second cluster
        wire2_cols = sorted([c for c in range(wire_col + 1, WORLD_W) if wm[wire2_row, c]])
        if wire2_cols:
            max_wc2 = max(wire2_cols)
            if max_wc2 < wire_col + 30:
                nc = max_wc2 + 1
                if nc < WORLD_W and em[wire2_row, nc]:
                    return (Tool.WIRE, nc, wire2_row)
        else:
            # Start horizontal extension
            if wm[wire2_row, wire_col]:
                nc = wire_col + 1
                if nc < WORLD_W and em[wire2_row, nc]:
                    return (Tool.WIRE, nc, wire2_row)

    # Phase 9: Wire extensions to left-side zones (horizontal from wire col)
    for zr in range(spine_top, spine_bot + 1, 3):
        if 0 <= zr < WORLD_H and wm[zr, wire_col]:
            # Extend wire leftward for left-side zone connectivity
            for dc in range(1, 5):
                lc = wire_col - dc
                if 0 <= lc < WORLD_W:
                    if wm[zr, lc]:
                        break
                    if em[zr, lc]:
                        return (Tool.WIRE, lc, zr)
                    break

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder.
    Reads tile_map every step to decide next action.
    - Places coal power plants at two anchors
    - Extends wires from existing power sources
    - Extends roads from existing roads/plants
    - Places zones near roads AND power
    - Adds services when population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def area_free(cx, cy):
        for dy in [-1, 0, 1]:
            for dx in [-1, 0, 1]:
                r, c = cy + dy, cx + dx
                if not in_bounds(cx + dx, cy + dy):
                    return False
                if not em[r, c]:
                    return False
        return True

    # Two cluster anchors
    P1X, P1Y = 35, 50
    P2X, P2Y = 85, 50

    # --- Phase 1: Place power plants if missing ---
    def has_plant_near(cx, cy, radius=6):
        pys, pxs = np.where(pm)
        for py2, px2 in zip(pys.tolist(), pxs.tolist()):
            if abs(px2 - cx) < radius and abs(py2 - cy) < radius:
                return True
        return False

    if not has_plant_near(P1X, P1Y):
        for dy in range(-3, 4):
            for dx in range(-3, 4):
                nx, ny = P1X + dx, P1Y + dy
                if in_bounds(nx, ny) and area_free(nx, ny):
                    return (Tool.COALPOWER, nx, ny)
        return (Tool.COALPOWER, P1X, P1Y)

    if not has_plant_near(P2X, P2Y):
        for dy in range(-3, 4):
            for dx in range(-3, 4):
                nx, ny = P2X + dx, P2Y + dy
                if in_bounds(nx, ny) and area_free(nx, ny):
                    return (Tool.COALPOWER, nx, ny)
        return (Tool.COALPOWER, P2X, P2Y)

    # --- Zone type balancing ---
    res_count = int(np.sum(resm)) // 9 + 1
    com_count = int(np.sum(comm)) // 9
    ind_count = int(np.sum(indm)) // 9
    total_zones = res_count + com_count + ind_count

    def pick_zone_type():
        r_frac = res_count / total_zones
        c_frac = com_count / total_zones
        i_frac = ind_count / total_zones
        if r_frac < 0.40:
            return Tool.RESIDENTIAL
        elif c_frac < 0.30:
            return Tool.COMMERCIAL
        elif i_frac < 0.30:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # --- Phase 2: Extend wires from existing power ---
    # Build wire spines along plant columns and a horizontal connector
    power_src = pm | wm

    wire_targets = []
    # Vertical spines at each plant column
    for dy in range(-14, 15):
        wire_targets.append((P1X, P1Y + dy))
        wire_targets.append((P2X, P2Y + dy))
    # Horizontal wire connecting the two spines at road level
    for x in range(P1X, P2X + 1):
        wire_targets.append((x, P1Y))
    # Additional horizontal wires above and below
    for x in range(P1X - 10, P1X + 11):
        wire_targets.append((x, P1Y - 5))
        wire_targets.append((x, P1Y + 5))
    for x in range(P2X - 10, P2X + 11):
        wire_targets.append((x, P2Y - 5))
        wire_targets.append((x, P2Y + 5))

    for (wx, wy) in wire_targets:
        if not in_bounds(wx, wy):
            continue
        if wm[wy, wx] or pm[wy, wx]:
            continue
        if not em[wy, wx]:
            continue
        # Only place wire adjacent to existing power
        adj_power = False
        for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = wx + ddx, wy + ddy
            if in_bounds(nx2, ny2) and (pm[ny2, nx2] or wm[ny2, nx2]):
                adj_power = True
                break
        if adj_power:
            return (Tool.WIRE, wx, wy)

    # --- Phase 3: Build roads from existing road/plant ---
    road_targets = []
    # Horizontal roads flanking each cluster
    for offset in [-5, -8, 5, 8]:
        for x in range(P1X - 12, P1X + 13):
            road_targets.append((x, P1Y + offset))
        for x in range(P2X - 12, P2X + 13):
            road_targets.append((x, P2Y + offset))
    # Vertical roads flanking each cluster wire spine
    for dy in range(-12, 13):
        road_targets.append((P1X - 4, P1Y + dy))
        road_targets.append((P1X + 4, P1Y + dy))
        road_targets.append((P2X - 4, P2Y + dy))
        road_targets.append((P2X + 4, P2Y + dy))
    # Connecting highway between clusters
    for x in range(P1X + 5, P2X - 4):
        road_targets.append((x, P1Y + 8))
        road_targets.append((x, P1Y - 8))

    for (rx, ry) in road_targets:
        if not in_bounds(rx, ry):
            continue
        if rm[ry, rx]:
            continue
        if pm[ry, rx] or wm[ry, rx]:
            continue
        if not em[ry, rx]:
            continue
        # Adjacent to existing road or plant
        adj = False
        for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx + ddx, ry + ddy
            if in_bounds(nx2, ny2) and (rm[ny2, nx2] or pm[ny2, nx2]):
                adj = True
                break
        if adj:
            return (Tool.ROAD, rx, ry)

    # --- Phase 4: Place zones near roads AND power ---
    # Compute neighbor masks dynamically from current map
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-7, 8):
        for dx in range(-7, 8):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_any = resm | comm | indm
    cand = em & nbr_road & nbr_power
    # Exclude edges (zones are 3x3)
    cand[:2, :] = False
    cand[WORLD_H - 2:, :] = False
    cand[:, :2] = False
    cand[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        key = int(step * 17 + int(pop * 3) + 1) % len(cxs)
        for offset in range(min(len(cxs), 120)):
            k = (key + offset * 13) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            # Check 3x3 clearance
            ok = True
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    ny2, nx2 = zy + dr, zx + dc
                    if not in_bounds(nx2, ny2):
                        ok = False; break
                    if not (em[ny2, nx2] or zone_any[ny2, nx2]):
                        ok = False; break
                if not ok:
                    break
            if ok:
                return (pick_zone_type(), zx, zy)

    # --- Phase 5: Services for city happiness ---
    if pop > 200:
        for sx, sy in [(P1X - 5, P1Y - 12), (P2X + 5, P2Y - 12)]:
            if in_bounds(sx, sy) and area_free(sx, sy):
                # Check no police/fire nearby
                found = False
                for dr in range(-8, 9):
                    for dc in range(-8, 9):
                        r2, c2 = sy + dr, sx + dc
                        if in_bounds(c2, r2) and 600 <= int(tm[r2, c2]) <= 750:
                            found = True
                if not found:
                    return (Tool.POLICESTATION, sx, sy)

    if pop > 350:
        for sx, sy in [(P1X - 5, P1Y + 12), (P2X + 5, P2Y + 12)]:
            if in_bounds(sx, sy) and area_free(sx, sy):
                return (Tool.FIRESTATION, sx, sy)

    # --- Fallback: extend road from existing road frontier ---
    rys, rxs = np.where(rm)
    if len(rxs) > 0:
        k2 = int(step * 13 + 7) % len(rxs)
        rx2, ry2 = int(rxs[k2]), int(rys[k2])
        for ddx, ddy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nx2, ny2 = rx2 + ddx, ry2 + ddy
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                return (Tool.ROAD, nx2, ny2)

    # --- Fallback: extend wire from existing wire frontier ---
    wys2, wxs2 = np.where(wm)
    if len(wxs2) > 0:
        k3 = int(step * 7 + 3) % len(wxs2)
        wx2, wy2 = int(wxs2[k3]), int(wys2[k3])
        for ddx, ddy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nx2, ny2 = wx2 + ddx, wy2 + ddy
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map each step to determine what exists
    - Places power plant first, then extends wire from plant edge,
      builds road spine adjacent to wire, places zones adjacent to road,
      adds more power/infrastructure as city grows.
    - Uses state only as a small phase hint.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    all_zones = resm | comm | indm

    # --- Helper: is a 3x3 area (centered at zr,zc) safe to place a zone? ---
    def zone_area_free(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                # Allow empty or already a zone tile (overlap check)
                if not em[rr, rc] and not all_zones[rr, rc]:
                    return False
        return True

    def zone_center_already(zr, zc):
        # Check if a zone center is already nearby
        r0, r1 = max(0, zr - 3), min(WORLD_H, zr + 4)
        c0, c1 = max(0, zc - 3), min(WORLD_W, zc + 4)
        return np.any(all_zones[r0:r1, c0:c1])

    def wire_nearby(zr, zc, rad=4):
        r0, r1 = max(0, zr - rad), min(WORLD_H, zr + rad + 1)
        c0, c1 = max(0, zc - rad), min(WORLD_W, zc + rad + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def road_nearby(zr, zc, rad=3):
        r0, r1 = max(0, zr - rad), min(WORLD_H, zr + rad + 1)
        c0, c1 = max(0, zc - rad), min(WORLD_W, zc + rad + 1)
        return np.any(rm[r0:r1, c0:c1])

    def pick_tool():
        rc = int(np.sum(resm))
        cc = int(np.sum(comm))
        ic = int(np.sum(indm))
        total = rc + cc + ic
        if total == 0:
            return Tool.RESIDENTIAL
        # Target: 50% res, 25% com, 25% ind
        if cc / (total + 1) < 0.22:
            return Tool.COMMERCIAL
        if ic / (total + 1) < 0.22:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # === PHASE 1: Place primary coal power plant ===
    if not np.any(pm):
        # Place at a fixed good spot left-center
        return (Tool.COALPOWER, 28, 50)

    # Find plant center (mean of plant tiles)
    pr, pc = np.where(pm)
    plant_cy = int(np.mean(pr))
    plant_cx = int(np.mean(pc))

    # === PHASE 2: Extend wire from plant rightward to form wire spine ===
    # Wire spine row = plant_cy (same row as plant)
    wire_row = plant_cy
    road_row = plant_cy + 2   # road runs 2 rows below wire spine
    zone_row_above = wire_row - 4  # zones above wire
    zone_row_below = road_row + 4  # zones below road

    # 2nd tier
    zone_row_above2 = wire_row - 8
    zone_row_below2 = road_row + 8

    # How far to build spine (grow with population)
    pop = obs.city_pop
    if pop < 50:
        max_col = min(WORLD_W - 3, plant_cx + 15)
    elif pop < 200:
        max_col = min(WORLD_W - 3, plant_cx + 25)
    elif pop < 500:
        max_col = min(WORLD_W - 3, plant_cx + 40)
    else:
        max_col = min(WORLD_W - 3, plant_cx + 55)

    min_col = max(2, plant_cx - 5)

    # Find rightmost wire on spine row
    wire_on_row = np.where(wm[wire_row, :])[0]
    road_on_rrow = np.where(rm[road_row, :])[0]

    # Connect plant to wire spine: place wire just right of plant
    plant_right = plant_cx + 2
    plant_right = min(plant_right, WORLD_W - 1)

    if len(wire_on_row) == 0:
        # No wire yet, start right of plant
        c = plant_right
        if 0 <= c < WORLD_W and em[wire_row, c]:
            return (Tool.WIRE, c, wire_row)
        # Try adjacent rows
        for dc in range(0, 5):
            c = plant_cx + 2 + dc
            if 0 <= c < WORLD_W and em[wire_row, c]:
                return (Tool.WIRE, c, wire_row)
        return None

    max_wc = int(np.max(wire_on_row))
    min_wc = int(np.min(wire_on_row))

    # Extend wire rightward
    if max_wc < max_col:
        nc = max_wc + 1
        if 0 <= nc < WORLD_W and not pm[wire_row, nc]:
            if em[wire_row, nc] or wm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # === PHASE 3: Build road spine (2 rows below wire spine) ===
    if len(road_on_rrow) == 0:
        # Start road at min_col
        c = min_col
        if 0 <= c < WORLD_W and em[road_row, c] and not pm[road_row, c]:
            return (Tool.ROAD, c, road_row)
    else:
        max_rc = int(np.max(road_on_rrow))
        road_target = max_wc  # road follows wire extent
        if max_rc < road_target:
            nc = max_rc + 1
            if 0 <= nc < WORLD_W and not pm[road_row, nc]:
                if em[road_row, nc]:
                    return (Tool.ROAD, nc, road_row)

    # === PHASE 4: Add vertical connector roads (every 4 cols) from road to zone rows ===
    # Connect road_row down to zone_row_below
    for c in range(min_col, max_wc + 1, 4):
        if not rm[road_row, c]:
            continue
        # Downward connectors
        for r in range(road_row + 1, min(zone_row_below + 2, WORLD_H)):
            if not rm[r, c] and not pm[r, c]:
                if em[r, c]:
                    return (Tool.ROAD, c, r)
                break

    # === PHASE 5: Place zones along road spine ===
    # Zones just below road: zone_row_below
    # Zones above wire: zone_row_above
    zone_idx = state.get('zone_idx', 0)

    def try_place_zones(zrow, col_start, col_end, step=4):
        nonlocal zone_idx
        for zc in range(col_start, col_end + 1, step):
            zr = zrow
            if not (1 <= zr <= WORLD_H - 2 and 1 <= zc <= WORLD_W - 2):
                continue
            if zone_center_already(zr, zc):
                continue
            if not zone_area_free(zr, zc):
                continue
            if wire_nearby(zr, zc, 5) and road_nearby(zr, zc, 5):
                t = pick_tool()
                zone_idx += 1
                state['zone_idx'] = zone_idx
                return (t, zc, zr)
        return None

    # Try lower zones first (easier road access)
    result = try_place_zones(zone_row_below, min_col + 1, max_wc, step=4)
    if result:
        return result

    # Try upper zones
    if zone_row_above >= 1:
        # Need wires going up from wire spine
        # First extend wires upward at intervals
        for c in range(min_col, max_wc + 1, 4):
            if not wm[wire_row, c]:
                continue
            for r in range(wire_row - 1, max(zone_row_above - 2, 0), -1):
                if wm[r, c] or pm[r, c]:
                    break
                if em[r, c]:
                    return (Tool.WIRE, c, r)
                break

        result = try_place_zones(zone_row_above, min_col + 1, max_wc, step=4)
        if result:
            return result

    # === PHASE 6: Second power plant if pop growing ===
    if pop > 150 and np.sum(pm) < 9:
        px2 = min(WORLD_W - 3, plant_cx + 35)
        py2 = plant_cy
        py2 = max(2, min(WORLD_H - 3, py2))
        if 2 <= px2 <= WORLD_W - 3 and em[py2, px2]:
            return (Tool.COALPOWER, px2, py2)

    # === PHASE 7: Second tier zones if pop growing ===
    if pop > 200:
        result = try_place_zones(zone_row_below2, min_col + 1, max_wc, step=4)
        if result:
            return result

        if zone_row_above2 >= 1:
            result = try_place_zones(zone_row_above2, min_col + 1, max_wc, step=4)
            if result:
                return result

    # === PHASE 8: Wire downward to reach lower zones ===
    for c in range(min_col, max_wc + 1, 4):
        if not wm[wire_row, c]:
            continue
        for r in range(wire_row + 1, min(zone_row_below + 3, WORLD_H)):
            if wm[r, c] or pm[r, c] or rm[r, c]:
                break
            if em[r, c]:
                return (Tool.WIRE, c, r)
            break

    # === PHASE 9: Fire/police stations ===
    if pop > 400:
        for cx_s in [plant_cx + 10, plant_cx + 20]:
            for cy_s in [wire_row - 2, road_row + 2]:
                cy_s = max(1, min(WORLD_H - 2, cy_s))
                cx_s2 = max(1, min(WORLD_W - 2, cx_s))
                if em[cy_s, cx_s2]:
                    return (Tool.FIRESTATION, cx_s2, cy_s)

    # === PHASE 10: Keep extending spine ===
    # Re-check wire extension
    wire_on_row2 = np.where(wm[wire_row, :])[0]
    if len(wire_on_row2) > 0:
        mwc = int(np.max(wire_on_row2))
        if mwc < max_col:
            nc = mwc + 1
            if 0 <= nc < WORLD_W and em[wire_row, nc] and not pm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy v3:
    - Reads tile_map every step to decide next action
    - Cross-shaped wire network from plant
    - Roads flank wire spines
    - Zones placed wherever road+wire coverage found
    - Dual-side zone columns (inner and outer)
    - Scales with population
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Phase 1: Place coal plant if missing ---
    if not np.any(pm):
        return (Tool.COALPOWER, 55, 50)

    # Find plant center
    plant_ys, plant_xs = np.where(pm)
    px = int(np.median(plant_xs))
    py = int(np.median(plant_ys))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Wire spines: vertical column to right of plant, horizontal row below plant
    wire_col_v = px + 3   # vertical spine column
    wire_row_h = py + 3   # horizontal spine row

    # Scale extent with population
    pop_ext = min(40, max(12, obs.city_pop // 15))
    v_tmin = max(2, py - 2 - pop_ext)
    v_tmax = min(WORLD_H - 3, py + 2 + pop_ext)
    h_lmin = max(2, px - 2 - pop_ext)
    h_rmax = min(WORLD_W - 3, px + 2 + pop_ext)

    wire_col_v = max(2, min(WORLD_W - 3, wire_col_v))
    wire_row_h = max(2, min(WORLD_H - 3, wire_row_h))

    # Check current wire extents
    wire_in_vcol = [r for r in range(WORLD_H) if wm[r, wire_col_v]]
    wire_in_hrow = [c for c in range(WORLD_W) if wm[wire_row_h, c]]

    # --- Phase 2: Build vertical wire spine ---
    if not wire_in_vcol:
        # Start wire adjacent to plant
        for dy in range(-2, 4):
            ny = py + dy
            if in_bounds(wire_col_v, ny) and (em[ny, wire_col_v] or wm[ny, wire_col_v]):
                return (Tool.WIRE, wire_col_v, ny)
    else:
        min_vw = min(wire_in_vcol)
        max_vw = max(wire_in_vcol)
        if max_vw < v_tmax:
            nr = max_vw + 1
            if in_bounds(wire_col_v, nr) and em[nr, wire_col_v] and not pm[nr, wire_col_v]:
                return (Tool.WIRE, wire_col_v, nr)
        if min_vw > v_tmin:
            nr = min_vw - 1
            if in_bounds(wire_col_v, nr) and em[nr, wire_col_v] and not pm[nr, wire_col_v]:
                return (Tool.WIRE, wire_col_v, nr)

    # --- Phase 3: Build horizontal wire spine ---
    if not wire_in_hrow:
        for dx in range(-2, 4):
            nx = px + dx
            if in_bounds(nx, wire_row_h) and (em[wire_row_h, nx] or wm[wire_row_h, nx]):
                return (Tool.WIRE, nx, wire_row_h)
    else:
        min_hw = min(wire_in_hrow)
        max_hw = max(wire_in_hrow)
        if max_hw < h_rmax:
            nc = max_hw + 1
            if in_bounds(nc, wire_row_h) and em[wire_row_h, nc] and not pm[wire_row_h, nc]:
                return (Tool.WIRE, nc, wire_row_h)
        if min_hw > h_lmin:
            nc = min_hw - 1
            if in_bounds(nc, wire_row_h) and em[wire_row_h, nc] and not pm[wire_row_h, nc]:
                return (Tool.WIRE, nc, wire_row_h)

    # --- Phase 4: Build roads flanking wire spines ---
    road_col_r = wire_col_v + 1
    road_col_l = wire_col_v - 1

    # Clamp road columns
    road_col_r = max(1, min(WORLD_W - 2, road_col_r))
    road_col_l = max(1, min(WORLD_W - 2, road_col_l))

    for wr in sorted(wire_in_vcol, key=lambda r: abs(r - py)):
        if in_bounds(road_col_r, wr) and em[wr, road_col_r]:
            return (Tool.ROAD, road_col_r, wr)
        if in_bounds(road_col_l, wr) and em[wr, road_col_l]:
            return (Tool.ROAD, road_col_l, wr)

    road_row_above = wire_row_h - 1
    road_row_below = wire_row_h + 1
    road_row_above = max(1, min(WORLD_H - 2, road_row_above))
    road_row_below = max(1, min(WORLD_H - 2, road_row_below))

    for wc in sorted(wire_in_hrow, key=lambda c: abs(c - px)):
        if in_bounds(wc, road_row_above) and em[road_row_above, wc]:
            return (Tool.ROAD, wc, road_row_above)
        if in_bounds(wc, road_row_below) and em[road_row_below, wc]:
            return (Tool.ROAD, wc, road_row_below)

    # --- Build proximity masks for zone placement ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and not zone_tiles[nr, nc]:
                    return False
        return True

    # --- Phase 5: Place zones where road+wire coverage found ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prefer near spines
        dist_v = np.abs(cxs - wire_col_v)
        dist_h = np.abs(cys - wire_row_h)
        dists = np.minimum(dist_v, dist_h)
        order = np.argsort(dists)
        step_off = int(obs.step * 3) % max(len(order), 1)
        for i in range(min(len(order), 100)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # --- Phase 6: Extend roads near wire to expand zone coverage ---
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 30)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx]:
                    if nbr_wire[ny, nx]:
                        return (Tool.ROAD, nx, ny)

    # --- Phase 7: Second power plant when city grows ---
    if total_zones > 12 or obs.city_pop > 300:
        p2x = px
        p2y = py + 28
        if in_bounds(p2x, p2y):
            nearby = any(
                in_bounds(p2x + ddx, p2y + ddy) and pm[p2y + ddy, p2x + ddx]
                for ddy in range(-6, 7) for ddx in range(-6, 7)
            )
            if not nearby and em[p2y, p2x]:
                return (Tool.COALPOWER, p2x, p2y)
            # Wire bridge down to second plant
            bridge_col = wire_col_v
            for wc2 in range(wire_row_h + 1, p2y - 1):
                if in_bounds(bridge_col, wc2) and em[wc2, bridge_col]:
                    return (Tool.WIRE, bridge_col, wc2)

    # --- Phase 8: Third power plant for large city ---
    if obs.city_pop > 500:
        p3x = px + 28
        p3y = py
        if in_bounds(p3x, p3y):
            nearby = any(
                in_bounds(p3x + ddx, p3y + ddy) and pm[p3y + ddy, p3x + ddx]
                for ddy in range(-6, 7) for ddx in range(-6, 7)
            )
            if not nearby and em[p3y, p3x]:
                return (Tool.COALPOWER, p3x, p3y)
            # Wire horizontal bridge to third plant
            for wc3 in range(wire_col_v + 1, p3x - 1):
                if in_bounds(wc3, wire_row_h) and em[wire_row_h, wc3]:
                    return (Tool.WIRE, wc3, wire_row_h)

    # --- Phase 9: Services ---
    if obs.city_pop > 100:
        fsx, fsy = px - 8, py - 9
        if in_bounds(fsx, fsy) and em[fsy, fsx]:
            return (Tool.FIRESTATION, fsx, fsy)
        psx, psy = px + 9, py - 9
        if in_bounds(psx, psy) and em[psy, psx]:
            return (Tool.POLICESTATION, psx, psy)

    # --- Phase 10: Grow wire frontier to increase coverage ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 25)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = wx + dx2, wy + dy2
                if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                    return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy that reads the map every step.
    - Places coal power plants, extends wires from them, builds roads,
      then places zones adjacent to powered+road-served areas.
    - Adapts to current map state each step.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    all_zones = resm | comm | indm

    pop = obs.city_pop
    step = obs.step

    # Zone counts
    res_count = int(np.sum(resm)) // 9
    com_count = int(np.sum(comm)) // 9
    ind_count = int(np.sum(indm)) // 9
    total_zones = res_count + com_count + ind_count + 1

    def pick_zone():
        r_f = res_count / total_zones
        c_f = com_count / total_zones
        i_f = ind_count / total_zones
        if r_f < 0.40:
            return Tool.RESIDENTIAL
        elif c_f < 0.30:
            return Tool.COMMERCIAL
        elif i_f < 0.30:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def area_free(cx, cy):
        for dy in [-1, 0, 1]:
            for dx in [-1, 0, 1]:
                r, c = cy + dy, cx + dx
                if r < 0 or r >= WORLD_H or c < 0 or c >= WORLD_W:
                    return False
                if not em[r, c]:
                    return False
        return True

    def zone_present_near(cx, cy, radius=1):
        r0 = max(0, cy - radius); r1 = min(WORLD_H, cy + radius + 1)
        c0 = max(0, cx - radius); c1 = min(WORLD_W, cx + radius + 1)
        return np.any(all_zones[r0:r1, c0:c1])

    def wire_near(cx, cy, radius=4):
        r0 = max(0, cy - radius); r1 = min(WORLD_H, cy + radius + 1)
        c0 = max(0, cx - radius); c1 = min(WORLD_W, cx + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def road_near(cx, cy, radius=3):
        r0 = max(0, cy - radius); r1 = min(WORLD_H, cy + radius + 1)
        c0 = max(0, cx - radius); c1 = min(WORLD_W, cx + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    # Two neighborhoods: left (x~35) and right (x~82), both at y~50
    # Each has: power plant, wire spine (vertical), road column, zone columns
    neighborhoods = [
        {'px': 35, 'py': 50, 'wire_col': 41, 'road_col': 43,
         'zone_cols': [37, 47], 'spine_dir': 'vert'},
        {'px': 82, 'py': 50, 'wire_col': 88, 'road_col': 90,
         'zone_cols': [84, 94], 'spine_dir': 'vert'},
    ]

    # Spine extent based on pop
    if pop < 100:
        spine_half = 7
    elif pop < 300:
        spine_half = 12
    elif pop < 600:
        spine_half = 18
    else:
        spine_half = 24

    cy_center = WORLD_H // 2  # 50

    for nb in neighborhoods:
        px, py = nb['px'], nb['py']
        wc = nb['wire_col']
        rc = nb['road_col']
        zcols = nb['zone_cols']

        # --- Step 1: Ensure power plant exists ---
        # Check 5x5 region around plant center
        py2, px2 = py, px
        pr0 = max(0, py - 2); pr1 = min(WORLD_H, py + 3)
        pc0 = max(0, px - 2); pc1 = min(WORLD_W, px + 3)
        has_plant = np.any(pm[pr0:pr1, pc0:pc1])

        if not has_plant:
            if area_free(px, py):
                return (Tool.COALPOWER, px, py)
            # Try nearby spots
            for dy in range(-4, 5):
                for dx in range(-4, 5):
                    npx, npy = px + dx, py + dy
                    if 2 <= npx <= WORLD_W - 3 and 2 <= npy <= WORLD_H - 3:
                        if area_free(npx, npy):
                            return (Tool.COALPOWER, npx, npy)
            continue  # can't place plant, skip neighborhood

        # Find actual plant location for this neighborhood
        # Look for plant tiles in the neighborhood region
        search_r0 = max(0, py - 6); search_r1 = min(WORLD_H, py + 7)
        search_c0 = max(0, px - 6); search_c1 = min(WORLD_W, px + 7)
        plant_sub = pm[search_r0:search_r1, search_c0:search_c1]
        if np.any(plant_sub):
            rows_p, cols_p = np.where(plant_sub)
            actual_py = int(np.mean(rows_p)) + search_r0
            actual_px = int(np.mean(cols_p)) + search_c0
        else:
            actual_py, actual_px = py, px

        # --- Step 2: Build vertical wire spine from plant ---
        target_min = max(1, cy_center - spine_half)
        target_max = min(WORLD_H - 2, cy_center + spine_half)

        # Wire spine at wc (vertical column)
        wire_rows = [r for r in range(WORLD_H) if wm[r, wc]]

        if not wire_rows:
            # Bootstrap wire adjacent to plant (connect plant to wire col)
            # Plant is at actual_px, actual_py
            # Wire col is wc, try to place wire at plant row
            boot_r = actual_py
            if 0 <= boot_r < WORLD_H and 0 <= wc < WORLD_W:
                if em[boot_r, wc] or wm[boot_r, wc]:
                    if not pm[boot_r, wc]:
                        return (Tool.WIRE, wc, boot_r)
            # Try connecting via horizontal wire between plant and wire col
            # Place wire step by step from plant toward wire col
            direction = 1 if wc > actual_px else -1
            for col in range(actual_px + direction, wc + direction, direction):
                if 0 <= col < WORLD_W and 0 <= actual_py < WORLD_H:
                    if not wm[actual_py, col] and not pm[actual_py, col]:
                        if em[actual_py, col]:
                            return (Tool.WIRE, col, actual_py)
                        break
            continue

        min_wr = min(wire_rows)
        max_wr = max(wire_rows)

        # Extend wire spine downward
        if max_wr < target_max:
            nr = max_wr + 1
            if 0 <= nr < WORLD_H and 0 <= wc < WORLD_W and not pm[nr, wc]:
                if em[nr, wc]:
                    return (Tool.WIRE, wc, nr)

        # Extend wire spine upward
        if min_wr > target_min:
            nr = min_wr - 1
            if 0 <= nr < WORLD_H and 0 <= wc < WORLD_W and not pm[nr, wc]:
                if em[nr, wc]:
                    return (Tool.WIRE, wc, nr)

        # --- Step 3: Build road column adjacent to wire spine ---
        for wr in wire_rows:
            if target_min <= wr <= target_max:
                if 0 <= rc < WORLD_W and not rm[wr, rc]:
                    if em[wr, rc] and not pm[wr, rc]:
                        return (Tool.ROAD, rc, wr)

        road_rows = [r for r in range(WORLD_H) if rm[r, rc]]

        # --- Step 4: Lateral wires to zone columns ---
        for wr in wire_rows:
            if target_min <= wr <= target_max:
                for zc in zcols:
                    if zc < wc:
                        # Wire leftward from spine
                        for col in range(wc - 1, zc - 1, -1):
                            if 0 <= col < WORLD_W:
                                if wm[wr, col] or pm[wr, col]:
                                    break
                                if em[wr, col] and not rm[wr, col]:
                                    return (Tool.WIRE, col, wr)
                                elif not em[wr, col] and not rm[wr, col]:
                                    break
                    else:
                        # Wire rightward from spine (skip road col)
                        for col in range(wc + 1, zc + 2):
                            if 0 <= col < WORLD_W:
                                if wm[wr, col] or pm[wr, col]:
                                    break
                                if em[wr, col] and not rm[wr, col]:
                                    return (Tool.WIRE, col, wr)
                                elif not em[wr, col] and not rm[wr, col]:
                                    break

        # --- Step 5: Place zones at zone columns where powered+road-served ---
        zone_rows_list = list(range(max(2, target_min + 1), min(WORLD_H - 2, target_max), 4))

        for zr in zone_rows_list:
            for zc in zcols:
                if 1 <= zc <= WORLD_W - 2 and 1 <= zr <= WORLD_H - 2:
                    if not zone_present_near(zc, zr, 1):
                        if area_free(zc, zr):
                            if wire_near(zc, zr, 4) and road_near(zc, zr, 4):
                                return (pick_zone(), zc, zr)

        # --- Step 6: Horizontal road extensions to reach zone cols ---
        for rr in road_rows:
            if target_min <= rr <= target_max:
                for zc in zcols:
                    direction2 = 1 if zc > rc else -1
                    for col in range(rc + direction2, zc + direction2, direction2):
                        if 0 <= col < WORLD_W:
                            if rm[rr, col]:
                                break
                            if em[rr, col] and not pm[rr, col]:
                                return (Tool.ROAD, col, rr)
                            elif not em[rr, col] and not pm[rr, col]:
                                break

    # --- Police/fire stations for happiness ---
    if pop > 300:
        for spx, spy in [(35, 44), (82, 44)]:
            if area_free(spx, spy):
                # Check if police station nearby
                r0 = max(0, spy - 8); r1 = min(WORLD_H, spy + 9)
                c0 = max(0, spx - 8); c1 = min(WORLD_W, spx + 9)
                has_police = np.any((tm[r0:r1, c0:c1] >= 600) & (tm[r0:r1, c0:c1] <= 750))
                if not has_police:
                    return (Tool.POLICESTATION, spx, spy)

    if pop > 500:
        for spx, spy in [(35, 56), (82, 56)]:
            if area_free(spx, spy):
                r0 = max(0, spy - 8); r1 = min(WORLD_H, spy + 9)
                c0 = max(0, spx - 8); c1 = min(WORLD_W, spx + 9)
                has_fire = np.any((tm[r0:r1, c0:c1] >= 750) & (tm[r0:r1, c0:c1] <= 900))
                if not has_fire:
                    return (Tool.FIRESTATION, spx, spy)

    # --- Second power plant if pop growing and only one plant ---
    num_plants = int(np.sum(pm))
    if pop > 400 and num_plants < 18:
        # Try a third neighborhood in the middle
        for npx, npy in [(60, 50), (60, 35), (60, 65)]:
            if area_free(npx, npy):
                return (Tool.COALPOWER, npx, npy)

    # --- Expand zone columns outward if population is high ---
    if pop > 200:
        extra_zcols = [
            (35, 35, 50), (35, 29, 50),  # left neighborhood extra cols
            (82, 82, 50), (82, 76, 50),  # right neighborhood extra cols
        ]
        cy_c = WORLD_H // 2
        for nbpx, zc, _ in extra_zcols:
            for zr in range(max(2, cy_c - spine_half + 1), min(WORLD_H - 2, cy_c + spine_half), 4):
                if 1 <= zc <= WORLD_W - 2 and 1 <= zr <= WORLD_H - 2:
                    if not zone_present_near(zc, zr, 1) and area_free(zc, zr):
                        if wire_near(zc, zr, 6) and road_near(zc, zr, 5):
                            return (pick_zone(), zc, zr)

    return None

def act(obs, state):
    """
    Improved policy:
    - Places power plant near top-left area
    - Builds a horizontal road spine instead of vertical
    - Wires run vertically from spine to zones above and below
    - Mixed RCI zones in rows above and below the road
    - Second power plant added earlier
    - More aggressive expansion
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    all_zone_mask = resm | comm | indm

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    pop = obs.city_pop

    # Use state as a step counter / action queue
    if 'plan' not in state:
        state['plan'] = []
        state['phase'] = 0

    # City layout: horizontal road at row cy, power plant at (px, py)
    cx, cy = 30, WORLD_H // 2  # start left-center
    road_row = cy
    upper_zone_row = cy - 4   # zones above road
    lower_zone_row = cy + 4   # zones below road
    upper2_zone_row = cy - 8
    lower2_zone_row = cy + 8

    # Power plant position
    plant_px, plant_py = 8, cy

    # --- Phase 1: Place first coal power plant ---
    if not np.any(pm):
        return (Tool.COALPOWER, plant_px, plant_py)

    # Find plant location
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # How far to extend the road spine based on pop
    if pop < 50:
        road_max_x = 40
    elif pop < 150:
        road_max_x = 60
    elif pop < 400:
        road_max_x = 80
    elif pop < 800:
        road_max_x = 100
    else:
        road_max_x = 115

    road_min_x = plant_cx + 4  # start road just right of plant

    # --- Phase 2: Build wire from plant to road row ---
    # Wire vertically from plant to road row
    wire_col_from_plant = plant_cx + 3
    wire_col_from_plant = max(2, min(WORLD_W - 3, wire_col_from_plant))

    if not wm[plant_cy, wire_col_from_plant] and em[plant_cy, wire_col_from_plant]:
        return (Tool.WIRE, wire_col_from_plant, plant_cy)

    # Connect plant vertically to road row
    if plant_cy != road_row:
        step = 1 if road_row > plant_cy else -1
        for r in range(plant_cy, road_row + step, step):
            if 0 <= r < WORLD_H and not wm[r, wire_col_from_plant] and (em[r, wire_col_from_plant] or rm[r, wire_col_from_plant]):
                if not pm[r, wire_col_from_plant]:
                    return (Tool.WIRE, wire_col_from_plant, r)

    # --- Phase 3: Build horizontal road spine ---
    road_rows_present = [c for c in range(WORLD_W) if rm[road_row, c]]
    if not road_rows_present or max(road_rows_present) < road_max_x:
        for c in range(road_min_x, road_max_x + 1):
            if 0 <= c < WORLD_W and not rm[road_row, c] and em[road_row, c]:
                return (Tool.ROAD, c, road_row)

    # --- Phase 4: Build wire spine along road (parallel, one row above) ---
    wire_row = road_row - 1
    wire_cols_present = [c for c in range(WORLD_W) if wm[wire_row, c]]
    if not wire_cols_present or max(wire_cols_present) < road_max_x:
        for c in range(road_min_x, road_max_x + 1):
            if 0 <= c < WORLD_W and not wm[wire_row, c] and (em[wire_row, c] or rm[wire_row, c]):
                return (Tool.WIRE, c, wire_row)

    # Helper: check if 3x3 zone area is placeable
    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_present(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def wire_near(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def road_near(zr, zc, radius=4):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    def pick_tool(zr, zc):
        # Vary zone type by position for diversity
        t = total_zones
        if t == 0:
            return Tool.RESIDENTIAL
        # Alternate: residential on upper, commercial in middle, industrial on lower
        if zr == upper_zone_row or zr == upper2_zone_row:
            if com_count / max(1,t) < 0.30:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif zr == lower_zone_row or zr == lower2_zone_row:
            if ind_count / max(1,t) < 0.25:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL
        else:
            return Tool.RESIDENTIAL

    # --- Phase 5: Vertical wires from wire_row to zone rows ---
    zone_rows = [upper_zone_row, lower_zone_row]
    if pop > 100:
        zone_rows += [upper2_zone_row, lower2_zone_row]

    # Place vertical wires connecting wire spine to zone rows
    wire_cols_on_spine = [c for c in range(WORLD_W) if wm[wire_row, c]]
    # Every 3 columns, drop a vertical wire to each zone row
    for wc in wire_cols_on_spine:
        if wc % 3 == 0:
            for zr in zone_rows:
                step = 1 if zr > wire_row else -1
                for r in range(wire_row, zr + step, step):
                    if 0 <= r < WORLD_H and not wm[r, wc] and not pm[r, wc]:
                        if em[r, wc] or rm[r, wc]:
                            return (Tool.WIRE, wc, r)
                        else:
                            break

    # --- Phase 6: Place zones along zone rows ---
    zone_x_list = list(range(road_min_x, road_max_x + 1, 3))
    for zr in zone_rows:
        for zc in zone_x_list:
            if zone_area_ok(zr, zc) and not zone_present(zr, zc):
                if wire_near(zr, zc) and road_near(zr, zc):
                    return (pick_tool(zr, zc), zc, zr)

    # --- Phase 7: Second coal plant when pop growing ---
    num_plant_tiles = int(np.sum(pm))
    if pop > 100 and num_plant_tiles < 9:
        px2 = plant_px + 20
        py2 = plant_py
        px2 = max(2, min(WORLD_W - 3, px2))
        py2 = max(2, min(WORLD_H - 3, py2))
        area_ok = True
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = py2+dr, px2+dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    area_ok = False
                elif not em[rr, rc] and not pm[rr, rc]:
                    area_ok = False
        if area_ok:
            return (Tool.COALPOWER, px2, py2)

    # --- Phase 8: Third coal plant for big cities ---
    if pop > 300 and num_plant_tiles < 18:
        px3 = plant_px + 40
        py3 = plant_py
        px3 = max(2, min(WORLD_W - 3, px3))
        py3 = max(2, min(WORLD_H - 3, py3))
        area_ok = True
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = py3+dr, px3+dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    area_ok = False
                elif not em[rr, rc] and not pm[rr, rc]:
                    area_ok = False
        if area_ok:
            return (Tool.COALPOWER, px3, py3)

    # --- Phase 9: Add horizontal road for outer zone rows ---
    if pop > 150:
        for outer_row in [upper2_zone_row - 1, lower2_zone_row + 1]:
            if 2 <= outer_row <= WORLD_H - 3:
                for c in range(road_min_x, road_max_x + 1):
                    if 0 <= c < WORLD_W and not rm[outer_row, c] and em[outer_row, c]:
                        return (Tool.ROAD, c, outer_row)

    # --- Phase 10: More zones at outer rows if infrastructure present ---
    if pop > 200:
        extra_rows = [upper2_zone_row, lower2_zone_row, upper_zone_row - 8, lower_zone_row + 8]
        for zr in extra_rows:
            if 1 <= zr <= WORLD_H - 2:
                for zc in zone_x_list:
                    if zone_area_ok(zr, zc) and not zone_present(zr, zc):
                        if wire_near(zr, zc, 6) and road_near(zr, zc, 5):
                            return (pick_tool(zr, zc), zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads current map state each step
    - Extends wire/road/zones from what already exists
    - Places power plants reactively based on zone count
    - Balances zone types dynamically
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Step 1: Place initial coal plant if none exists ---
    if not np.any(pm):
        return (Tool.COALPOWER, 55, 50)

    # Find plant center
    plant_ys, plant_xs = np.where(pm)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        r_r = res_count / t
        c_r = com_count / t
        i_r = ind_count / t
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Wire spine column just right of plant
    wire_col = px + 2

    # Dynamic vertical span based on population
    base_span = 20
    extra_span = min(40, obs.city_pop // 10)
    target_span = base_span + extra_span
    tmin = max(2, py - target_span)
    tmax = min(WORLD_H - 3, py + target_span)

    # --- Step 2: Reactively extend wire spine based on current wire state ---
    # Find existing wire in the spine column
    wire_in_col = [r for r in range(WORLD_H) if wm[r, wire_col]]

    if not wire_in_col:
        # Start wire adjacent to plant
        for dy in range(-2, 3):
            ny = py + dy
            if in_bounds(wire_col, ny) and em[ny, wire_col]:
                return (Tool.WIRE, wire_col, ny)
    else:
        min_wr = min(wire_in_col)
        max_wr = max(wire_in_col)
        # Extend downward
        if max_wr < tmax:
            nr = max_wr + 1
            if in_bounds(wire_col, nr) and not pm[nr, wire_col]:
                if em[nr, wire_col] or wm[nr, wire_col]:
                    return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if min_wr > tmin:
            nr = min_wr - 1
            if in_bounds(wire_col, nr) and not pm[nr, wire_col]:
                if em[nr, wire_col] or wm[nr, wire_col]:
                    return (Tool.WIRE, wire_col, nr)

    # --- Step 3: Build road columns reactively from wire ---
    # Right road column (zones fit between wire and road)
    road_col_r = wire_col + 3
    road_col_l = wire_col - 3

    for wr in wire_in_col:
        if not (tmin <= wr <= tmax):
            continue
        # Place road on right side if missing
        if in_bounds(road_col_r, wr) and em[wr, road_col_r]:
            return (Tool.ROAD, road_col_r, wr)
        # Place road on left side if missing
        if in_bounds(road_col_l, wr) and em[wr, road_col_l]:
            return (Tool.ROAD, road_col_l, wr)

    # --- Step 4: Add horizontal roads every 4 rows (denser grid for connectivity) ---
    if wire_in_col:
        for wr in wire_in_col:
            if not (tmin <= wr <= tmax):
                continue
            if (wr - tmin) % 4 == 0:
                for rc in range(road_col_l, road_col_r + 1):
                    if in_bounds(rc, wr) and not rm[wr, rc] and em[wr, rc] and not pm[wr, rc]:
                        return (Tool.ROAD, rc, wr)

    # --- Step 5: Reactive zone placement ---
    # Build neighbor proximity masks from current map
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    all_zone_m = resm | comm | indm
    zone_rows, zone_cols = np.where(all_zone_m)
    zone_set = set(zip(zone_rows.tolist(), zone_cols.tolist()))

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    # Candidate zone centers: near road AND wire
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Sort by distance to wire spine
        dists = np.abs(cxs - wire_col) + np.abs(cys - py)
        sort_idx = np.argsort(dists)
        for i in range(min(len(cxs), 60)):
            k = int(sort_idx[i])
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # --- Step 6: Extend roads reactively from frontier ---
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        # Find road tiles near wire, extend outward
        for idx in range(min(len(road_xs_arr), 50)):
            k = (int(obs.step * 7 + idx * 13)) % len(road_xs_arr)
            rx = int(road_xs_arr[k])
            ry = int(road_ys_arr[k])
            if not nbr_wire[ry, rx]:
                continue
            for dy, dx in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx + dx, ry + dy
                if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                    return (Tool.ROAD, nx2, ny2)

    # --- Step 7: Place second power plant reactively when zones need power ---
    if total_zones > 15 or obs.city_pop > 300:
        # Check if powered zones lag behind total zones significantly
        # Place second plant to the right
        p2x = px + 20
        p2y = py
        if in_bounds(p2x, p2y):
            # Check no plant nearby
            nearby = any(
                in_bounds(p2x + dx, p2y + dy) and pm[p2y + dy, p2x + dx]
                for dy in range(-8, 9) for dx in range(-8, 9)
            )
            if not nearby and em[p2y, p2x]:
                return (Tool.COALPOWER, p2x, p2y)
            # Connect with horizontal wire bridge
            for wc in range(wire_col + 1, p2x):
                if in_bounds(wc, py) and (em[py, wc] or wm[py, wc]) and not pm[py, wc]:
                    return (Tool.WIRE, wc, py)

    # --- Step 8: Place third plant on left for more coverage ---
    if (total_zones > 30 or obs.city_pop > 600) and not state.get("plant3_placed", False):
        p3x = px - 20
        p3y = py
        if in_bounds(p3x, p3y):
            nearby3 = any(
                in_bounds(p3x + dx, p3y + dy) and pm[p3y + dy, p3x + dx]
                for dy in range(-8, 9) for dx in range(-8, 9)
            )
            if not nearby3 and em[p3y, p3x]:
                state["plant3_placed"] = True
                return (Tool.COALPOWER, p3x, p3y)
            # Connect leftward with wire
            for wc in range(wire_col - 1, p3x - 1, -1):
                if in_bounds(wc, py) and (em[py, wc] or wm[py, wc]) and not pm[py, wc]:
                    return (Tool.WIRE, wc, py)

    # --- Step 9: Services when population warrants ---
    if obs.city_pop > 150:
        fx, fy = px - 7, py - 10
        if in_bounds(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
        fx2, fy2 = px + 7, py - 10
        if in_bounds(fx2, fy2) and em[fy2, fx2]:
            return (Tool.POLICESTATION, fx2, fy2)

    # --- Step 10: Extend wire frontier reactively ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        k = int(obs.step * 7) % len(wire_xs_arr)
        wx = int(wire_xs_arr[k])
        wy = int(wire_ys_arr[k])
        # Prefer extending in wire column direction
        for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx2, ny2 = wx + dx2, wy + dy2
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                # Extend wire if near where zones could go
                if tmin <= ny2 <= tmax:
                    return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder.
    Each step reads the current map and decides what to place next
    based on what already exists (power, roads, zones).
    Strategy:
    - Start with a coal plant
    - Extend wires from existing power sources toward target zones
    - Extend roads from existing road network
    - Place zones where both road access and power exist
    - Add more power plants as city grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def safe_empty(x, y):
        return in_bounds(x, y) and bool(em[y, x])

    # Two cluster centers
    AX, AY = 35, 50
    BX, BY = 80, 50

    # Step 1: Place first coal plant if none exists
    if not np.any(pm):
        return (Tool.COALPOWER, AX, AY)

    # Current state of power and roads
    power_map = pm | wm  # tiles that conduct/provide power
    zone_map = resm | comm | indm

    # Count zones for mix decisions
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    plant_tiles = int(np.sum(pm))

    def pick_zone():
        t = max(total_zones, 1)
        if ind_count / t < 0.22:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Compute "near road" map (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Compute "near power" map (within 5 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= power_map[sr0:sr1, sc0:sc1]

    # Step 2: Add second plant if city is growing
    if plant_tiles < 9 and obs.city_pop > 50:
        if safe_empty(BX, BY):
            return (Tool.COALPOWER, BX, BY)

    # Step 3: Add third plant if city needs more power
    if plant_tiles < 18 and obs.city_pop > 300:
        cx, cy = (AX + BX) // 2, AY + 12
        if safe_empty(cx, cy):
            return (Tool.COALPOWER, cx, cy)

    # Step 4: Extend wires reactively
    # Find frontier: empty tiles adjacent to existing power
    pys, pxs = np.where(power_map)

    # Target wire path: horizontal spine connecting plants at spine_y
    spine_y = AY - 3

    # Wire targets: spine + verticals near plants
    wire_targets = []
    # Horizontal spine
    for x in range(AX - 12, BX + 13):
        wire_targets.append((x, spine_y))
    # Vertical wires from plants to spine
    for x in [AX + dx for dx in range(-1, 2)]:
        for y in range(spine_y, AY + 1):
            wire_targets.append((x, y))
    for x in [BX + dx for dx in range(-1, 2)]:
        for y in range(spine_y, BY + 1):
            wire_targets.append((x, y))
    # Vertical wires downward from spine to feed lower zone area
    for x in range(AX - 12, AX + 13, 4):
        for y in range(spine_y, spine_y + 16):
            wire_targets.append((x, y))
    for x in range(BX - 12, BX + 13, 4):
        for y in range(spine_y, spine_y + 16):
            wire_targets.append((x, y))

    for (wx, wy) in wire_targets:
        if not in_bounds(wx, wy):
            continue
        if bool(wm[wy, wx]) or bool(pm[wy, wx]) or bool(rm[wy, wx]):
            continue
        if not bool(em[wy, wx]):
            continue
        # Only place if adjacent to existing power
        for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = wx + ddx, wy + ddy
            if in_bounds(nx, ny) and bool(power_map[ny, nx]):
                return (Tool.WIRE, wx, wy)

    # Step 5: Extend roads reactively
    road_spine_y = AY + 3

    road_targets = []
    # Horizontal road spine
    for x in range(AX - 12, BX + 13):
        road_targets.append((x, road_spine_y))
    # Cross streets around cluster A every 4 cols
    for dx in range(-12, 13, 4):
        cx = AX + dx
        for dy in range(-8, 9):
            road_targets.append((cx, road_spine_y + dy))
    # Cross streets around cluster B every 4 cols
    for dx in range(-12, 13, 4):
        cx = BX + dx
        for dy in range(-8, 9):
            road_targets.append((cx, road_spine_y + dy))

    for (rx, ry) in road_targets:
        if not in_bounds(rx, ry):
            continue
        if bool(rm[ry, rx]) or bool(pm[ry, rx]):
            continue
        if not bool(em[ry, rx]):
            continue
        # Only place if adjacent to existing road or adjacent to plant
        adj = False
        for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = rx + ddx, ry + ddy
            if in_bounds(nx, ny) and (bool(rm[ny, nx]) or bool(pm[ny, nx])):
                adj = True
                break
        if adj:
            return (Tool.ROAD, rx, ry)

    # Step 6: Place zones where road + power exist
    cand = em & nbr_road & nbr_power
    # Avoid map edges
    cand[0:2, :] = False
    cand[WORLD_H-2:, :] = False
    cand[:, 0:2] = False
    cand[:, WORLD_W-2:] = False

    cys2, cxs2 = np.where(cand)
    if len(cxs2) > 0:
        # Use step + pop for deterministic but varying selection
        key = int(obs.step * 17 + int(obs.city_pop * 3) + 1) % len(cxs2)
        for offset in range(min(len(cxs2), 120)):
            k = (key + offset * 13) % len(cxs2)
            zx, zy = int(cxs2[k]), int(cys2[k])
            # Check 3x3 zone footprint is clear
            ok = True
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    ny2, nx2 = zy + dr, zx + dc
                    if not in_bounds(nx2, ny2):
                        ok = False; break
                    if not (bool(em[ny2, nx2]) or bool(zone_map[ny2, nx2])):
                        ok = False; break
                if not ok:
                    break
            if ok:
                return (pick_zone(), zx, zy)

    # Step 7: Services based on population
    if obs.city_pop > 200:
        for fx, fy in [(AX - 10, AY - 6), (BX + 10, BY - 6)]:
            fx = max(1, min(WORLD_W-2, fx))
            fy = max(1, min(WORLD_H-2, fy))
            if safe_empty(fx, fy):
                return (Tool.FIRESTATION, fx, fy)

    if obs.city_pop > 400:
        for fx, fy in [(AX + 10, AY + 8), (BX - 10, BY + 8)]:
            fx = max(1, min(WORLD_W-2, fx))
            fy = max(1, min(WORLD_H-2, fy))
            if safe_empty(fx, fy):
                return (Tool.POLICESTATION, fx, fy)

    # Fallback: extend wire from any existing wire/plant frontier
    if len(pxs) > 0:
        k = int(obs.step * 7) % len(pxs)
        wx2, wy2 = int(pxs[k]), int(pys[k])
        for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = wx2 + ddx, wy2 + ddy
            if in_bounds(nx, ny) and safe_empty(nx, ny):
                return (Tool.WIRE, nx, ny)

    # Fallback: extend road from any road frontier
    rys3, rxs3 = np.where(rm)
    if len(rxs3) > 0:
        k2 = int(obs.step * 11) % len(rxs3)
        rx2, ry2 = int(rxs3[k2]), int(rys3[k2])
        for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = rx2 + ddx, ry2 + ddy
            if in_bounds(nx, ny) and safe_empty(nx, ny):
                return (Tool.ROAD, nx, ny)

    return None

def act(obs, state):
    """
    Hybrid policy combining best ideas from both parents.
    - Compact cluster with vertical wire spine + flanking roads
    - Balanced zone placement (R/C/I)
    - Second power plant for growth
    - Services at appropriate thresholds
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Fixed anchor: place first coal plant at (58, 50)
    if not np.any(pm):
        return (Tool.COALPOWER, 58, 50)

    plant_ys, plant_xs = np.where(pm)
    # Primary plant center
    px = int(plant_xs[0]) if len(plant_xs) > 0 else 58
    py = int(plant_ys[0]) if len(plant_ys) > 0 else 50

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.22:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Wire spine column: just right of plant
    wire_col = px + 2
    # Road columns flanking the wire spine
    road_col_l = wire_col - 1
    road_col_r = wire_col + 1

    # Determine vertical extent of wire spine based on population
    pop_factor = min(30, obs.city_pop // 15)
    spine_top = max(3, py - 14 - pop_factor)
    spine_bot = min(WORLD_H - 4, py + 14 + pop_factor)

    # --- Build vertical wire spine ---
    wire_in_col = [r for r in range(WORLD_H)
                   if 0 <= wire_col < WORLD_W and bool(wm[r, wire_col])]

    if not wire_in_col:
        # Seed wire adjacent to plant
        for dy in range(-2, 3):
            ny = py + dy
            if in_bounds(wire_col, ny) and (bool(em[ny, wire_col]) or bool(wm[ny, wire_col])) and not bool(pm[ny, wire_col]):
                return (Tool.WIRE, wire_col, ny)
    else:
        min_wr = min(wire_in_col)
        max_wr = max(wire_in_col)
        # Grow downward
        if max_wr < spine_bot:
            nr = max_wr + 1
            if in_bounds(wire_col, nr) and (bool(em[nr, wire_col]) or bool(wm[nr, wire_col])) and not bool(pm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        # Grow upward
        if min_wr > spine_top:
            nr = min_wr - 1
            if in_bounds(wire_col, nr) and (bool(em[nr, wire_col]) or bool(wm[nr, wire_col])) and not bool(pm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    # --- Build road columns flanking the wire spine ---
    # For each wire row, ensure road on left and right
    if wire_in_col:
        step_mod3 = obs.step % 3
        rows_to_check = wire_in_col[::2] if step_mod3 < 2 else wire_in_col[1::2]
        for wr in rows_to_check:
            if in_bounds(road_col_l, wr) and bool(em[wr, road_col_l]) and not bool(pm[wr, road_col_l]):
                return (Tool.ROAD, road_col_l, wr)
            if in_bounds(road_col_r, wr) and bool(em[wr, road_col_r]) and not bool(pm[wr, road_col_r]):
                return (Tool.ROAD, road_col_r, wr)

    # --- Second power plant when city grows ---
    if total_zones > 8 or obs.city_pop > 200:
        p2x = px + 20
        p2y = py
        if in_bounds(p2x, p2y):
            nearby_plant = any(
                in_bounds(p2x + dx, p2y + dy) and bool(pm[p2y + dy, p2x + dx])
                for dy in range(-5, 6) for dx in range(-5, 6)
                if in_bounds(p2x + dx, p2y + dy)
            )
            if not nearby_plant and bool(em[p2y, p2x]):
                return (Tool.COALPOWER, p2x, p2y)
            # Wire horizontal bridge from spine to second plant
            if not nearby_plant:
                for wc in range(wire_col + 1, p2x - 1):
                    if in_bounds(wc, py) and bool(em[py, wc]) and not bool(pm[py, wc]):
                        return (Tool.WIRE, wc, py)
            # Second vertical wire spine
            wire_col2 = p2x - 2
            if wire_in_col:
                for wr in wire_in_col:
                    if in_bounds(wire_col2, wr) and bool(em[wr, wire_col2]) and not bool(pm[wr, wire_col2]):
                        return (Tool.WIRE, wire_col2, wr)

    # --- Build proximity masks for zone placement ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-7, 8):
        for dx in range(-7, 8):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not in_bounds(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # --- Place zones near roads and power ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prioritize candidates near wire column
        dists = np.abs(cxs - wire_col) + np.abs(cys - py) // 3
        order = np.argsort(dists)
        step_off = int(obs.step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 80:
                break

    # --- Extend roads near wire to fill gaps ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 20)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- Services when pop is high enough ---
    if obs.city_pop > 150:
        for fpos in [(px - 10, py - 10), (px + 10, py - 10)]:
            fsx, fsy = fpos
            if in_bounds(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)
    if obs.city_pop > 350:
        for ppos in [(px - 10, py + 10), (px + 10, py + 10)]:
            psx, psy = ppos
            if in_bounds(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    # --- Expand wire laterally as fallback ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 15)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if in_bounds(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def act(obs, state):
    """
    Hybrid policy:
    - Two coal power plants (primary at 45,50; secondary at 75,50)
    - Vertical wire spines adjacent to each plant
    - Road columns flanking each wire spine
    - Dense zone placement (RES/COM/IND) near road+wire
    - Progressive expansion based on population
    - Services (fire/police) when warranted
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    pop = obs.city_pop

    def pick_zone():
        if ind_count == 0 or ind_count / total_zones < 0.20:
            return Tool.INDUSTRIAL
        if com_count == 0 or com_count / total_zones < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_area_free(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zy + dr, zx + dc
                if not in_bounds(rc, rr):
                    return False
                if not bool(em[rr, rc]):
                    return False
        return True

    # Power plant targets
    P1X, P1Y = 45, 50
    P2X, P2Y = 75, 50

    plant_ys, plant_xs = np.where(pm)
    has_plant1 = any(abs(px_ - P1X) <= 5 and abs(py_ - P1Y) <= 5
                     for py_, px_ in zip(plant_ys.tolist(), plant_xs.tolist()))
    has_plant2 = any(abs(px_ - P2X) <= 5 and abs(py_ - P2Y) <= 5
                     for py_, px_ in zip(plant_ys.tolist(), plant_xs.tolist()))

    # Phase 1: place primary plant
    if not has_plant1:
        return (Tool.COALPOWER, P1X, P1Y)

    # Compute spine extent from pop
    if pop < 50:
        spine_half = 10
    elif pop < 150:
        spine_half = 16
    elif pop < 400:
        spine_half = 22
    elif pop < 800:
        spine_half = 28
    else:
        spine_half = 34

    def build_corridor(plant_x, plant_y, wire_col):
        """
        Build: wire spine at wire_col, roads at wire_col±2,
        zones at wire_col±4 and wire_col±7.
        Returns action or None.
        """
        road_col_L = wire_col - 2
        road_col_R = wire_col + 2
        zone_cols_L = [wire_col - 5, wire_col - 8]
        zone_cols_R = [wire_col + 5, wire_col + 8]

        tmin = max(2, plant_y - spine_half)
        tmax = min(WORLD_H - 3, plant_y + spine_half)

        wire_rows = sorted(r for r in range(WORLD_H) if bool(wm[r, wire_col]))

        # Extend or bootstrap wire spine
        if not wire_rows:
            # Bootstrap wire adjacent to plant
            for dy in range(-2, 3):
                nr = plant_y + dy
                if in_bounds(wire_col, nr) and bool(em[nr, wire_col]) and not bool(pm[nr, wire_col]):
                    return (Tool.WIRE, wire_col, nr)
            return None

        min_wr = min(wire_rows)
        max_wr = max(wire_rows)

        # Extend downward
        if max_wr < tmax:
            nr = max_wr + 1
            if in_bounds(wire_col, nr) and bool(em[nr, wire_col]) and not bool(pm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

        # Extend upward
        if min_wr > tmin:
            nr = min_wr - 1
            if in_bounds(wire_col, nr) and bool(em[nr, wire_col]) and not bool(pm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

        wire_rows_set = set(wire_rows)

        # Build road columns (L and R) alongside wire
        for wr in wire_rows:
            if tmin <= wr <= tmax:
                if in_bounds(road_col_L, wr) and bool(em[wr, road_col_L]):
                    return (Tool.ROAD, road_col_L, wr)
                if in_bounds(road_col_R, wr) and bool(em[wr, road_col_R]):
                    return (Tool.ROAD, road_col_R, wr)

        # Build proximity masks for road and wire (for zone placement)
        road_near = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        wire_near = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-2, 3):
            for dx in range(-2, 3):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                road_near[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]
                wire_near[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
                wire_near[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

        zone_tiles = resm | comm | indm

        # Place zones near wire and road
        for wr in wire_rows:
            if wr < 2 or wr >= WORLD_H - 2:
                continue
            if not (tmin <= wr <= tmax):
                continue
            for zc in zone_cols_L + zone_cols_R:
                if not in_bounds(zc, wr) or zc < 2 or zc >= WORLD_W - 2:
                    continue
                if bool(road_near[wr, zc]) and bool(wire_near[wr, zc]):
                    if zone_area_free(zc, wr):
                        return (pick_zone(), zc, wr)

        # Lateral wires from spine toward left zone columns
        for wr in wire_rows:
            if tmin <= wr <= tmax:
                for wc in range(wire_col - 1, max(wire_col - 9, 0) - 1, -1):
                    if in_bounds(wc, wr) and not bool(wm[wr, wc]) and not bool(pm[wr, wc]):
                        if bool(em[wr, wc]):
                            return (Tool.WIRE, wc, wr)
                        break

        # Lateral roads from right road col outward
        for wr in wire_rows:
            if tmin <= wr <= tmax:
                for rc in range(road_col_R + 1, min(wire_col + 10, WORLD_W)):
                    if in_bounds(rc, wr) and not bool(rm[wr, rc]) and not bool(pm[wr, rc]) and not bool(wm[wr, rc]):
                        if bool(em[wr, rc]):
                            return (Tool.ROAD, rc, wr)
                        break

        return None

    # Corridor 1: wire at P1X+3=48
    wire_col1 = P1X + 3
    action = build_corridor(P1X, P1Y, wire_col1)
    if action is not None:
        return action

    # Phase 2: second plant + corridor when pop > 100
    if pop > 100:
        if not has_plant2:
            return (Tool.COALPOWER, P2X, P2Y)

        # Connect plant2 area to wire_col2 with horizontal wire
        wire_col2 = P2X + 3
        # Check if wire exists near plant2
        wire_near_p2 = any(
            abs(r - P2Y) <= 3 and abs(c - wire_col2) <= 3
            for r, c in zip(plant_ys.tolist(), plant_xs.tolist())
        ) or any(
            bool(wm[P2Y + dy, wire_col2]) for dy in range(-3, 4)
            if in_bounds(wire_col2, P2Y + dy)
        )

        if not wire_near_p2:
            for wc in range(P2X + 2, wire_col2 + 1):
                if in_bounds(wc, P2Y) and bool(em[P2Y, wc]) and not bool(pm[P2Y, wc]):
                    return (Tool.WIRE, wc, P2Y)

        action2 = build_corridor(P2X, P2Y, wire_col2)
        if action2 is not None:
            return action2

    # Services
    if pop > 200:
        fsx, fsy = wire_col1 - 7, P1Y - 10
        fsx = max(2, min(WORLD_W - 3, fsx))
        fsy = max(2, min(WORLD_H - 3, fsy))
        if zone_area_free(fsx, fsy):
            return (Tool.FIRESTATION, fsx, fsy)

    if pop > 400:
        psx, psy = wire_col1 - 7, P1Y + 10
        psx = max(2, min(WORLD_W - 3, psx))
        psy = max(2, min(WORLD_H - 3, psy))
        if zone_area_free(psx, psy):
            return (Tool.POLICESTATION, psx, psy)

    # Fallback: extend existing roads near wire
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs_arr), 1)
        for offset in range(min(len(road_xs_arr), 20)):
            k = (step_k + offset * 7) % len(road_xs_arr)
            rx, ry = int(road_xs_arr[k]), int(road_ys_arr[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if in_bounds(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    # Check wire nearby
                    wire_near_here = False
                    for wy in range(-2, 3):
                        for wx in range(-2, 3):
                            if in_bounds(nx + wx, ny + wy) and bool(wm[ny + wy, nx + wx]):
                                wire_near_here = True
                                break
                    if wire_near_here:
                        return (Tool.ROAD, nx, ny)

    # Fallback: extend wires
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 15)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = wx + dx2, wy + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Grid-based city builder:
    - Uses a pre-planned grid layout stored in state
    - Places power plant, wire backbone, road grid, then zones
    - More aggressive zone placement with better road/wire coverage
    - Balanced zone mix with commercial and industrial emphasis
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Initialize plan in state
    if "plan" not in state:
        # Center of our city cluster
        cx, cy = 60, 50
        state["plan"] = {
            "cx": cx, "cy": cy,
            "plant1": (cx, cy),
            "plant2": (cx + 25, cy),
            "plant3": (cx - 25, cy),
            "phase": 0,
            "step_idx": 0,
        }
        # Pre-generate action sequence
        actions = []

        # Phase 0: Place main power plant
        actions.append((Tool.COALPOWER, cx, cy))

        # Phase 1: Horizontal wire backbone at cy
        # Wire from cx+3 to cx+22 (right side)
        for x in range(cx+3, cx+23):
            actions.append((Tool.WIRE, x, cy))
        # Wire from cx-3 to cx-22 (left side)
        for x in range(cx-3, cx-23, -1):
            actions.append((Tool.WIRE, x, cy))

        # Phase 2: Vertical roads on right cluster
        # Road columns at cx+7 and cx+14
        for y in range(cy-15, cy+16):
            if y != cy:  # skip plant row
                actions.append((Tool.ROAD, cx+7, y))
        for y in range(cy-15, cy+16):
            if y != cy:
                actions.append((Tool.ROAD, cx+14, y))

        # Phase 3: Vertical roads on left cluster  
        for y in range(cy-15, cy+16):
            if y != cy:
                actions.append((Tool.ROAD, cx-7, y))
        for y in range(cy-15, cy+16):
            if y != cy:
                actions.append((Tool.ROAD, cx-14, y))

        # Phase 4: Horizontal roads every 4 rows (right cluster)
        for yr in range(cy-15, cy+16, 4):
            for x in range(cx+3, cx+18):
                actions.append((Tool.ROAD, x, yr))

        # Phase 5: Horizontal roads every 4 rows (left cluster)
        for yr in range(cy-15, cy+16, 4):
            for x in range(cx-3, cx-18, -1):
                actions.append((Tool.ROAD, x, yr))

        # Phase 6: Vertical wire branches to power zones
        # Wire branches at cx+7 and cx+14 rows
        for y in range(cy-14, cy+15, 4):
            actions.append((Tool.WIRE, cx+4, y))
            actions.append((Tool.WIRE, cx+5, y))
            actions.append((Tool.WIRE, cx+6, y))
        for y in range(cy-14, cy+15, 4):
            actions.append((Tool.WIRE, cx-4, y))
            actions.append((Tool.WIRE, cx-5, y))
            actions.append((Tool.WIRE, cx-6, y))

        # Phase 7: Place second power plant (right)
        actions.append((Tool.COALPOWER, cx+25, cy))
        # Wire from backbone to right plant
        for x in range(cx+23, cx+24):
            actions.append((Tool.WIRE, x, cy))

        # Phase 8: More roads around right plant
        for y in range(cy-10, cy+11):
            actions.append((Tool.ROAD, cx+21, y))
            actions.append((Tool.ROAD, cx+28, y))
        for yr in range(cy-10, cy+11, 4):
            for x in range(cx+21, cx+30):
                actions.append((Tool.ROAD, x, yr))
        # Wire to zone areas around right plant
        for y in range(cy-10, cy+11, 4):
            for x in range(cx+22, cx+25):
                actions.append((Tool.WIRE, x, y))

        # Phase 9: Place zones - right inner cluster (between cx+8 and cx+13)
        # Mix: IND near plant, COM in middle, RES outer
        zone_actions_right = []
        for zy in range(cy-13, cy+14, 4):
            for zx in range(cx+8, cx+14, 3):
                if abs(zy - cy) < 4:
                    tool = Tool.INDUSTRIAL
                elif abs(zy - cy) < 9:
                    tool = Tool.COMMERCIAL
                else:
                    tool = Tool.RESIDENTIAL
                zone_actions_right.append((tool, zx, zy))

        # Phase 10: Zones in left cluster
        zone_actions_left = []
        for zy in range(cy-13, cy+14, 4):
            for zx in range(cx-8, cx-14, -3):
                if abs(zy - cy) < 4:
                    tool = Tool.INDUSTRIAL
                elif abs(zy - cy) < 9:
                    tool = Tool.COMMERCIAL
                else:
                    tool = Tool.RESIDENTIAL
                zone_actions_left.append((tool, zx, zy))

        # Phase 11: Zones around right plant
        zone_actions_right2 = []
        for zy in range(cy-9, cy+10, 4):
            for zx in range(cx+22, cx+29, 3):
                if abs(zy - cy) < 5:
                    tool = Tool.COMMERCIAL
                else:
                    tool = Tool.RESIDENTIAL
                zone_actions_right2.append((tool, zx, zy))

        # Third power plant (left)
        actions.append((Tool.COALPOWER, cx-25, cy))
        for x in range(cx-23, cx-24, -1):
            actions.append((Tool.WIRE, x, cy))

        # Roads around left plant
        for y in range(cy-10, cy+11):
            actions.append((Tool.ROAD, cx-21, y))
            actions.append((Tool.ROAD, cx-28, y))
        for yr in range(cy-10, cy+11, 4):
            for x in range(cx-21, cx-30, -1):
                actions.append((Tool.ROAD, x, yr))
        for y in range(cy-10, cy+11, 4):
            for x in range(cx-22, cx-25, -1):
                actions.append((Tool.WIRE, x, y))

        zone_actions_left2 = []
        for zy in range(cy-9, cy+10, 4):
            for zx in range(cx-22, cx-29, -3):
                if abs(zy - cy) < 5:
                    tool = Tool.COMMERCIAL
                else:
                    tool = Tool.RESIDENTIAL
                zone_actions_left2.append((tool, zx, zy))

        # Services
        actions.append((Tool.FIRESTATION, cx+1, cy-18))
        actions.append((Tool.POLICESTATION, cx-1, cy-18))
        actions.append((Tool.FIRESTATION, cx+20, cy-18))
        actions.append((Tool.POLICESTATION, cx-20, cy-18))

        # Interleave zone placements with infrastructure
        all_zones = zone_actions_right + zone_actions_left + zone_actions_right2 + zone_actions_left2

        # Add extra zones filling gaps
        for zy in range(cy-13, cy+14, 4):
            for zx in range(cx+15, cx+21, 3):
                all_zones.append((Tool.RESIDENTIAL, zx, zy))
            for zx in range(cx-15, cx-21, -3):
                all_zones.append((Tool.RESIDENTIAL, zx, zy))

        actions.extend(all_zones)

        # Dense repeat zone placement passes for reactive filling
        for _ in range(3):
            actions.extend(all_zones)

        state["actions"] = actions
        state["action_idx"] = 0

    # Execute pre-planned actions reactively
    actions = state["actions"]
    idx = state["action_idx"]

    # Reactive override: if we're early and no plant exists, place it first
    if not np.any(pm) and obs.step < 5:
        plan = state["plan"]
        return (Tool.COALPOWER, plan["cx"], plan["cy"])

    # Try to execute next planned action, skip if invalid
    attempts = 0
    while idx < len(actions) and attempts < 10:
        tool, x, y = actions[idx]
        idx += 1
        attempts += 1

        if not in_bounds(x, y):
            continue

        # Skip if placing would destroy plant
        if pm[y, x] and tool != Tool.COALPOWER:
            continue

        # For zones: check if center and surroundings are reasonably clear
        if tool in (Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.INDUSTRIAL):
            # Check 3x3 area is within bounds
            if not (in_bounds(x-1, y-1) and in_bounds(x+1, y+1)):
                continue
            # Check no plant tiles in 3x3
            if np.any(pm[y-1:y+2, x-1:x+2]):
                continue
            # Check not already a zone
            if resm[y, x] or comm[y, x] or indm[y, x]:
                continue

        state["action_idx"] = idx
        return (tool, x, y)

    state["action_idx"] = idx

    # Reactive fallback: scan map and fill empty areas near roads/wires with zones
    if idx >= len(actions) or attempts >= 10:
        res_count = int(np.sum(resm))
        com_count = int(np.sum(comm))
        ind_count = int(np.sum(indm))
        total_zones = max(res_count + com_count + ind_count, 1)

        def pick_tool():
            i_r = ind_count / total_zones
            c_r = com_count / total_zones
            if i_r < 0.25:
                return Tool.INDUSTRIAL
            if c_r < 0.30:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL

        # Find cells with road AND wire neighbors
        nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-2, 3):
            for dx in range(-2, 3):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

        nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-3, 4):
            for dx in range(-3, 4):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
                nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

        cand = em & nbr_road & nbr_wire
        cand[0:2, :] = False; cand[WORLD_H-2:, :] = False
        cand[:, 0:2] = False; cand[:, WORLD_W-2:] = False

        cys, cxs = np.where(cand)
        plan = state["plan"]
        cx, cy = plan["cx"], plan["cy"]

        if len(cxs) > 0:
            dists = np.abs(cxs - cx) + np.abs(cys - cy)
            sort_idx = np.argsort(dists)
            for i in range(min(len(cxs), 50)):
                k = int(sort_idx[i])
                zx, zy = int(cxs[k]), int(cys[k])
                if not in_bounds(zx-1, zy-1) or not in_bounds(zx+1, zy+1):
                    continue
                if np.any(pm[zy-1:zy+2, zx-1:zx+2]):
                    continue
                if resm[zy, zx] or comm[zy, zx] or indm[zy, zx]:
                    continue
                return (pick_tool(), zx, zy)

    return None

def act(obs, state):
    """
    Combined policy:
    - Coal plant at fixed central location
    - Vertical wire spine adjacent to plant (from Parent B)
    - Road columns on both sides of wire spine (Parent B)
    - Horizontal roads every 6 rows for connectivity (Parent B)
    - Reactive zone placement near road+wire (Parent B, proven effective)
    - Second/third power plants with wire bridges (Parent B)
    - Dynamic spine growth based on population (Parent B)
    - Zone mix targeting 40% res, 30% com, 30% ind
    - Services (fire/police) for city happiness
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Place coal power plant first at fixed location
    has_plant = np.any(pm)
    if not has_plant:
        return (Tool.COALPOWER, 55, 50)

    plant_ys, plant_xs = np.where(pm)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        r_r = res_count / t
        c_r = com_count / t
        i_r = ind_count / t
        if i_r < 0.28:
            return Tool.INDUSTRIAL
        if c_r < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Wire spine column just right of plant center
    wire_col = px + 2

    # Vertical span grows with population
    base_span = 18
    extra_span = min(38, obs.city_pop // 12)
    target_span = base_span + extra_span
    tmin = max(2, py - target_span)
    tmax = min(WORLD_H - 3, py + target_span)

    wire_rows_in_col = sorted(r for r in range(WORLD_H)
                               if in_bounds(wire_col, r) and wm[r, wire_col])

    # Build vertical wire spine
    if not wire_rows_in_col:
        for dy in range(-2, 3):
            ny = py + dy
            if in_bounds(wire_col, ny) and em[ny, wire_col]:
                return (Tool.WIRE, wire_col, ny)
    else:
        min_wr = min(wire_rows_in_col)
        max_wr = max(wire_rows_in_col)
        if max_wr < tmax:
            nr = max_wr + 1
            if in_bounds(wire_col, nr) and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        if min_wr > tmin:
            nr = min_wr - 1
            if in_bounds(wire_col, nr) and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    # Road columns: 2 cells each side of wire spine
    road_col_r = wire_col + 2
    road_col_l = wire_col - 2

    # Build road columns along wire spine
    for wr in wire_rows_in_col:
        if not (tmin <= wr <= tmax):
            continue
        if in_bounds(road_col_r, wr) and em[wr, road_col_r]:
            return (Tool.ROAD, road_col_r, wr)
        if in_bounds(road_col_l, wr) and em[wr, road_col_l]:
            return (Tool.ROAD, road_col_l, wr)

    # Add horizontal connecting roads every 6 rows
    if wire_rows_in_col:
        for wr in wire_rows_in_col:
            if not (tmin <= wr <= tmax):
                continue
            if (wr - tmin) % 6 == 0:
                for rc in range(road_col_l, road_col_r + 1):
                    if in_bounds(rc, wr) and not rm[wr, rc] and em[wr, rc]:
                        return (Tool.ROAD, rc, wr)

    # Build neighbor masks for road and wire proximity
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    all_zone_m = resm | comm | indm
    zone_rows_arr, zone_cols_arr = np.where(all_zone_m)
    zone_set = set(zip(zone_rows_arr.tolist(), zone_cols_arr.tolist()))

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    # Candidate zone centers: near road AND wire, not too close to edge
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        dists = np.abs(cxs - wire_col) + np.abs(cys - py)
        sort_idx = np.argsort(dists)
        step_hash = int(obs.step * 17 + total_zones * 7) % max(len(cxs), 1)
        for i in range(min(len(cxs), 100)):
            if i < 50:
                k = int(sort_idx[i])
            else:
                k = (step_hash + (i - 50) * 13) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # Extend roads sideways to reach more zone positions
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        for dy, dx in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            step_k = int(obs.step * 11) % max(len(road_xs_arr), 1)
            rx_s = int(road_xs_arr[step_k])
            ry_s = int(road_ys_arr[step_k])
            nx2, ny2 = rx_s + dx, ry_s + dy
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                if nbr_wire[ny2, nx2]:
                    return (Tool.ROAD, nx2, ny2)

    # Second power plant when many zones exist
    if total_zones > 15 or obs.city_pop > 300:
        p2x = px + 20
        p2y = py
        if in_bounds(p2x, p2y):
            nearby_plant = any(
                in_bounds(p2x + dx, p2y + dy) and pm[p2y + dy, p2x + dx]
                for dy in range(-8, 9) for dx in range(-8, 9)
            )
            if not nearby_plant and em[p2y, p2x]:
                return (Tool.COALPOWER, p2x, p2y)
            # Connect second plant with wire bridge
            for wc in range(wire_col + 1, p2x):
                if in_bounds(wc, py) and (em[py, wc] or wm[py, wc]):
                    if not pm[py, wc]:
                        return (Tool.WIRE, wc, py)

    # Services for city happiness
    if obs.city_pop > 200:
        fx, fy = px - 6, py - 8
        if in_bounds(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
        px2, py2 = px - 6, py + 8
        if in_bounds(px2, py2) and em[py2, px2]:
            return (Tool.POLICESTATION, px2, py2)

    # Third plant and extended wire when very large
    if obs.city_pop > 600 and not state.get("plant3_placed", False):
        p3x = px - 20
        p3y = py
        if in_bounds(p3x, p3y):
            nearby_plant3 = any(
                in_bounds(p3x + dx, p3y + dy) and pm[p3y + dy, p3x + dx]
                for dy in range(-8, 9) for dx in range(-8, 9)
            )
            if not nearby_plant3 and em[p3y, p3x]:
                state["plant3_placed"] = True
                return (Tool.COALPOWER, p3x, p3y)
            # Connect with wire leftward
            for wc in range(wire_col - 1, p3x - 1, -1):
                if in_bounds(wc, py) and (em[py, wc] or wm[py, wc]) and not pm[py, wc]:
                    return (Tool.WIRE, wc, py)

    # Fourth plant for very large cities
    if obs.city_pop > 900 and not state.get("plant4_placed", False):
        p4x = px + 40
        p4y = py
        if in_bounds(p4x, p4y):
            nearby_p4 = any(
                in_bounds(p4x + dx, p4y + dy) and pm[p4y + dy, p4x + dx]
                for dy in range(-8, 9) for dx in range(-8, 9)
            )
            if not nearby_p4 and em[p4y, p4x]:
                state["plant4_placed"] = True
                return (Tool.COALPOWER, p4x, p4y)
            for wc in range(wire_col + 1, p4x):
                if in_bounds(wc, py) and (em[py, wc] or wm[py, wc]) and not pm[py, wc]:
                    return (Tool.WIRE, wc, py)

    # Extend wire frontier if stuck
    wire_ys_arr2, wire_xs_arr2 = np.where(wm)
    if len(wire_xs_arr2) > 0:
        step_k2 = int(obs.step * 7) % max(len(wire_xs_arr2), 1)
        wx_s = int(wire_xs_arr2[step_k2])
        wy_s = int(wire_ys_arr2[step_k2])
        for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx2, ny2 = wx_s + dx2, wy_s + dy2
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Three-cluster city builder: left, center, right.
    Each cluster has its own coal plant.
    Road spine connects all three clusters horizontally.
    Wire network feeds power to all zones.
    Zone mix: ~40% RES, 30% COM, 30% IND for better balance.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Three cluster anchors - spread across map
    AX, AY = 25, 50   # left cluster
    BX, BY = 60, 50   # center cluster
    CX, CY = 95, 50   # right cluster

    if 'phase' not in state:
        state['phase'] = 0

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        r_frac = res_count / t
        c_frac = com_count / t
        i_frac = ind_count / t
        if i_frac < 0.28:
            return Tool.INDUSTRIAL
        if c_frac < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    plant_cells = pm
    plant_count = int(np.sum(plant_cells))

    # Step 1: Place plant A
    if plant_count < 9:
        if bool(em[AY, AX]):
            return (Tool.COALPOWER, AX, AY)

    # Step 2: Place plant B
    if plant_count < 18 and obs.city_pop > 50:
        if bool(em[BY, BX]):
            return (Tool.COALPOWER, BX, BY)

    # Step 3: Place plant C
    if plant_count < 27 and obs.city_pop > 150:
        if bool(em[CY, CX]):
            return (Tool.COALPOWER, CX, CY)

    power_map = pm | wm

    wire_spine_y = AY - 3  # horizontal wire spine above clusters

    # Wire horizontally across the full spine
    wire_targets = []
    # Main horizontal spine
    for x in range(AX - 12, CX + 13):
        wire_targets.append((x, wire_spine_y))

    # Vertical connectors from each plant up to spine
    for (px, py) in [(AX, AY), (BX, BY), (CX, CY)]:
        for dy in range(1, abs(py - wire_spine_y) + 2):
            for dx in range(-1, 2):
                wire_targets.append((px + dx, wire_spine_y + dy))

    # Spread wire downward from spine to reach zones below
    for px in [AX, BX, CX]:
        for dx in range(-12, 13, 4):
            for dy in range(0, 15):
                wire_targets.append((px + dx, wire_spine_y + dy))

    for (wx, wy) in wire_targets:
        if not in_bounds(wx, wy):
            continue
        if bool(wm[wy, wx]) or bool(pm[wy, wx]) or bool(rm[wy, wx]):
            continue
        if not bool(em[wy, wx]):
            continue
        for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = wx + ddx, wy + ddy
            if in_bounds(nx, ny) and bool(power_map[ny, nx]):
                return (Tool.WIRE, wx, wy)

    # Road layout
    road_spine_y = AY + 3  # horizontal road spine below clusters

    road_targets = []
    # Main horizontal road
    for x in range(AX - 12, CX + 13):
        road_targets.append((x, road_spine_y))

    # Cross streets every 4 cols around each cluster
    for (px, py) in [(AX, AY), (BX, BY), (CX, CY)]:
        for dx in range(-12, 13, 4):
            cx2 = px + dx
            for dy in range(-12, 13):
                road_targets.append((cx2, road_spine_y + dy))
        # Horizontal cross roads
        for dy in range(-8, 12, 4):
            for x in range(px - 12, px + 13):
                road_targets.append((x, road_spine_y + dy))

    for (rx, ry) in road_targets:
        if not in_bounds(rx, ry):
            continue
        if bool(rm[ry, rx]) or bool(pm[ry, rx]) or bool(wm[ry, rx]):
            continue
        if not bool(em[ry, rx]):
            continue
        adj = False
        for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = rx + ddx, ry + ddy
            if in_bounds(nx, ny) and (bool(rm[ny, nx]) or bool(pm[ny, nx])):
                adj = True
                break
        if adj:
            return (Tool.ROAD, rx, ry)

    # Zone placement near roads AND power
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_mask = resm | comm | indm
    cand = em & nbr_road & nbr_power
    cand[0:2, :] = False
    cand[WORLD_H-2:, :] = False
    cand[:, 0:2] = False
    cand[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        key = int(obs.step * 17 + int(obs.city_pop * 3) + 1) % len(cxs)
        for offset in range(min(len(cxs), 100)):
            k = (key + offset * 13) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            ok = True
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    ny2, nx2 = zy + dr, zx + dc
                    if not in_bounds(nx2, ny2):
                        ok = False; break
                    if not (bool(em[ny2, nx2]) or bool(zone_mask[ny2, nx2])):
                        ok = False; break
                if not ok:
                    break
            if ok:
                return (pick_tool(), zx, zy)

    # Services
    if obs.city_pop > 120:
        for fx, fy in [(AX - 8, AY - 6), (BX, BY - 10), (CX + 8, CY - 6)]:
            fx = max(1, min(WORLD_W-2, fx))
            fy = max(1, min(WORLD_H-2, fy))
            if bool(em[fy, fx]):
                return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 300:
        for fx, fy in [(AX + 8, AY + 10), (BX, BY + 12), (CX - 8, CY + 10)]:
            fx = max(1, min(WORLD_W-2, fx))
            fy = max(1, min(WORLD_H-2, fy))
            if bool(em[fy, fx]):
                return (Tool.POLICESTATION, fx, fy)

    # Add 4th plant if population is high
    if obs.city_pop > 500 and plant_count < 36:
        p4x = (AX + BX) // 2
        p4y = AY + 18
        p4x = max(2, min(WORLD_W-3, p4x))
        p4y = max(2, min(WORLD_H-3, p4y))
        if bool(em[p4y, p4x]):
            return (Tool.COALPOWER, p4x, p4y)

    # Fallback: extend wire from frontier
    wys2, wxs2 = np.where(wm)
    if len(wxs2) > 0:
        k3 = int(obs.step * 7) % len(wxs2)
        wx2, wy2 = int(wxs2[k3]), int(wys2[k3])
        for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = wx2 + ddx, wy2 + ddy
            if in_bounds(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                return (Tool.WIRE, nx, ny)

    # Fallback: extend road
    rys2, rxs2 = np.where(rm)
    if len(rxs2) > 0:
        k2 = int(obs.step * 11) % len(rxs2)
        rx2, ry2 = int(rxs2[k2]), int(rys2[k2])
        for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = rx2 + ddx, ry2 + ddy
            if in_bounds(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                return (Tool.ROAD, nx, ny)

    return None

def act(obs, state):
    """
    Closed-loop policy: each step reads the current map and decides
    what to place next based on observed state.
    """
    tm = obs.tile_map
    emp = empty_mask(tm)
    res = res_mask(tm)
    com = com_mask(tm)
    ind = ind_mask(tm)
    road = road_mask(tm)
    wire = wire_mask(tm)
    plant = plant_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    # Phase 0: Place coal power plant if none exists
    if not plant.any():
        return (Tool.COALPOWER, cx - 4, cy)

    # Find power plant location (centroid)
    plant_ys, plant_xs = np.where(plant)
    px, py = int(plant_xs.mean()), int(plant_ys.mean())

    # Phase 1: Ensure a wire spine connects plant to a vertical corridor
    # Wire spine at column cx, from plant row outward
    # Check if we need more wire on the spine
    spine_x = cx
    # We want wire from py up to cy-14 and down to cy+14
    wire_col = wire[:, spine_x]
    wire_rows = np.where(wire_col)[0]

    # First connect plant to spine with a wire bridge
    if not wire[py, spine_x]:
        # Draw wire horizontally from plant to spine
        # Find closest wire or plant tile in row py
        row_wire = wire[py, :]
        row_plant = plant[py, :]
        has_src = row_wire | row_plant
        if has_src.any():
            src_xs = np.where(has_src)[0]
            # Place wire one step closer to spine_x
            closest = src_xs[np.argmin(np.abs(src_xs - spine_x))]
            step_dir = 1 if spine_x > closest else -1
            target_x = int(closest) + step_dir
            if 0 <= target_x < WORLD_W:
                return (Tool.WIRE, target_x, py)
        else:
            # Place wire adjacent to plant
            wx = px + 1 if px < spine_x else px - 1
            return (Tool.WIRE, wx, py)

    # Extend wire spine vertically
    needed_rows = list(range(max(0, cy - 16), min(WORLD_H, cy + 17)))
    for r in needed_rows:
        if not wire[r, spine_x]:
            # Check if adjacent wire exists (to grow from)
            has_adj = (r > 0 and wire[r-1, spine_x]) or (r < WORLD_H-1 and wire[r+1, spine_x])
            if has_adj:
                return (Tool.WIRE, spine_x, r)

    # Phase 2: Road spine parallel to wire spine
    road_x = cx + 1
    for r in range(max(0, cy - 16), min(WORLD_H, cy + 17)):
        if not road[r, road_x]:
            return (Tool.ROAD, road_x, r)

    # Also road on left of wire spine
    road_x2 = cx - 1
    for r in range(max(0, cy - 16), min(WORLD_H, cy + 17)):
        if not road[r, road_x2]:
            return (Tool.ROAD, road_x2, r)

    # Phase 3: Horizontal roads to connect zones
    # Add horizontal roads at intervals
    for dy in range(-15, 16, 3):
        r = cy + dy
        if 0 <= r < WORLD_H:
            for c in range(max(0, cx - 8), min(WORLD_W, cx + 9)):
                if not road[r, c] and not wire[r, c]:
                    # Only place road if it connects two road segments or road exists nearby
                    has_road_nearby = (
                        (c > 0 and road[r, c-1]) or
                        (c < WORLD_W-1 and road[r, c+1]) or
                        (r > 0 and road[r-1, c]) or
                        (r < WORLD_H-1 and road[r+1, c])
                    )
                    if has_road_nearby:
                        return (Tool.ROAD, c, r)

    # Phase 4: Place zones adjacent to roads, powered by wire grid
    # Determine what zones exist
    zone = res | com | ind

    def has_road_nearby(x, y, radius=2):
        y0, y1 = max(0, y - radius), min(WORLD_H, y + radius + 1)
        x0, x1 = max(0, x - radius), min(WORLD_W, x + radius + 1)
        return road[y0:y1, x0:x1].any()

    def has_wire_nearby(x, y, radius=3):
        y0, y1 = max(0, y - radius), min(WORLD_H, y + radius + 1)
        x0, x1 = max(0, x - radius), min(WORLD_W, x + radius + 1)
        return wire[y0:y1, x0:x1].any() or plant[y0:y1, x0:x1].any()

    def is_valid_zone_center(x, y):
        # 3x3 zone, center at (x,y), all must be in bounds
        if x < 1 or x > WORLD_W - 2 or y < 1 or y > WORLD_H - 2:
            return False
        if not has_road_nearby(x, y):
            return False
        if not has_wire_nearby(x, y):
            return False
        return True

    # Count existing zones
    n_res = res.sum()
    n_com = com.sum()
    n_ind = ind.sum()

    # Strategy: ~60% res, 25% com, 15% ind
    # Choose tool based on ratios
    total = n_res + n_com + n_ind + 1
    if n_res / total < 0.55:
        preferred_tool = Tool.RESIDENTIAL
    elif n_com / total < 0.25:
        preferred_tool = Tool.COMMERCIAL
    else:
        preferred_tool = Tool.INDUSTRIAL

    # Find candidate zone centers near roads
    # Look for empty 3x3 areas near road access
    best_x, best_y = None, None
    best_score = -1

    # Sample candidate positions systematically based on step for variety
    step_offset = obs.step % 9

    for try_dy in range(-14, 15, 3):
        for try_dx in range(-8, 9, 3):
            cx2 = cx + try_dx
            cy2 = cy + try_dy
            # offset to avoid always same spot
            cx2 = cx2 + (step_offset // 3)
            cy2 = cy2 + (step_offset % 3)

            if not is_valid_zone_center(cx2, cy2):
                continue

            # Check if this 3x3 area is mostly empty (auto-bulldoze handles it but avoid overwriting zones)
            y0, y1 = cy2 - 1, cy2 + 2
            x0, x1 = cx2 - 1, cx2 + 2
            area_zone = zone[y0:y1, x0:x1]
            if area_zone.any():
                continue  # Don't overwrite existing zones

            # Score: prefer positions near existing zones (clustering) and near roads
            score = 0
            # Near existing zones
            y0e, y1e = max(0, cy2 - 4), min(WORLD_H, cy2 + 5)
            x0e, x1e = max(0, cx2 - 4), min(WORLD_W, cx2 + 5)
            score += int(zone[y0e:y1e, x0e:x1e].sum())
            # Near road
            score += int(road[max(0, cy2-2):min(WORLD_H, cy2+3), max(0, cx2-2):min(WORLD_W, cx2+3)].sum()) * 2
            # Prefer closer to center
            score -= int(abs(try_dx) + abs(try_dy)) // 2

            if score > best_score:
                best_score = score
                best_x, best_y = cx2, cy2

    if best_x is not None:
        return (preferred_tool, best_x, best_y)

    # Fallback: add more roads near existing zones to improve connectivity
    zone_ys, zone_xs = np.where(zone)
    if len(zone_xs) > 0:
        k = obs.step % len(zone_xs)
        zx, zy = int(zone_xs[k]), int(zone_ys[k])
        # Place road adjacent to this zone
        for dx, dy in [(0, 2), (2, 0), (0, -2), (-2, 0), (1, 2), (-1, 2)]:
            nx, ny = zx + dx, zy + dy
            if 0 <= nx < WORLD_W and 0 <= ny < WORLD_H:
                if not road[ny, nx] and not zone[ny, nx]:
                    return (Tool.ROAD, nx, ny)

    return None

def act(obs, state):
    """
    Improved policy: Build a grid-based city with multiple road columns,
    better power distribution, and balanced zone mix.
    Uses a horizontal road spine with vertical feeders and zones on both sides.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    step = obs.step
    pop = obs.city_pop

    # Initialize state
    if 'phase' not in state:
        state['phase'] = 0
        state['action_queue'] = []

    def enqueue(actions):
        state['action_queue'].extend(actions)

    # If we have queued actions, execute them
    if state['action_queue']:
        return state['action_queue'].pop(0)

    has_plant = np.any(pm)
    has_wire = np.any(wm)
    has_road = np.any(rm)

    # Plant location: upper-left area
    plant_cx, plant_cy = 30, 45

    # Phase 0: Place coal power plant
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    wire_positions = set(zip(*np.where(wm))) if has_wire else set()
    road_positions = set(zip(*np.where(rm))) if has_road else set()
    res_pos = set(zip(*np.where(res_mask(tm))))
    com_pos = set(zip(*np.where(com_mask(tm))))
    ind_pos = set(zip(*np.where(ind_mask(tm))))
    all_zones = res_pos | com_pos | ind_pos

    res_count = len(res_pos)
    com_count = len(com_pos)
    ind_count = len(ind_pos)

    # Layout: horizontal wire spine at row 45 (plant_cy)
    # Road at row 46, then zones above (rows 42, 39, 36...) and below (rows 49, 52, 55...)
    # Multiple road columns for more zones

    wire_row = plant_cy       # row 45
    road_row = plant_cy + 1   # row 46

    # Wire extends horizontally from plant to the right
    wire_col_start = plant_cx + 3  # col 33
    wire_col_end = min(90, wire_col_start + 40 + min(30, pop // 30))

    # Check wire coverage
    wire_cols_in_row = set(c for (r, c) in wire_positions if r == wire_row)

    # Phase 1: Extend horizontal wire spine
    if not wire_cols_in_row or max(wire_cols_in_row) < wire_col_end:
        start = max(wire_cols_in_row) + 1 if wire_cols_in_row else wire_col_start
        for wc in range(start, min(start + 3, wire_col_end + 1)):
            if 0 <= wc < WORLD_W:
                state['action_queue'].append((Tool.WIRE, wc, wire_row))
        if state['action_queue']:
            return state['action_queue'].pop(0)

    # Phase 2: Extend horizontal road spine
    road_cols_in_row = set(c for (r, c) in road_positions if r == road_row)
    if not road_cols_in_row or max(road_cols_in_row) < wire_col_end:
        start = max(road_cols_in_row) + 1 if road_cols_in_row else wire_col_start
        for rc in range(start, min(start + 3, wire_col_end + 1)):
            if 0 <= rc < WORLD_W:
                state['action_queue'].append((Tool.ROAD, rc, road_row))
        if state['action_queue']:
            return state['action_queue'].pop(0)

    # Phase 3: Place zones above and below the road/wire spine
    # Zone rows above: 43 (center), 40, 37, 34
    # Zone rows below: 48, 51, 54

    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def zone_nearby(zr, zc):
        return any(abs(zr - pr) <= 1 and abs(zc - pc) <= 1 for (pr, pc) in all_zones)

    # Zone columns: every 4 columns along wire spine
    available_zone_cols = sorted(wire_cols_in_row)

    # Zone placement rows: 43 above (close), 48 below (close), 40 above (far), 51 below (far)
    zone_row_offsets = [-2, 3, -5, 6, -8, 9]  # relative to wire_row

    for zone_col in available_zone_cols[::4]:  # every 4th wire col as zone anchor
        if zone_col < wire_col_start:
            continue
        zc = zone_col
        for offset in zone_row_offsets:
            zr = wire_row + offset
            if not (2 <= zr <= WORLD_H - 3):
                continue
            if zone_nearby(zr, zc):
                continue
            if not zone_area_free(zr, zc):
                continue

            # Need road connection: place road from road_row to zone
            # Connect vertically
            r_start = min(road_row, zr) + 1
            r_end = max(road_row, zr) - 1
            for rr in range(min(road_row, zr), max(road_row, zr) + 1):
                if road_mask(tm)[rr, zc] or wire_mask(tm)[rr, zc]:
                    continue
                if em[rr, zc]:
                    state['action_queue'].append((Tool.ROAD, zc, rr))

            # Decide zone type: aim for 2:1:1 res:com:ind ratio
            total = res_count + com_count + ind_count + 1
            r_frac = res_count / total
            c_frac = com_count / total
            i_frac = ind_count / total

            if i_frac < 0.20:
                ztype = Tool.INDUSTRIAL
            elif c_frac < 0.25:
                ztype = Tool.COMMERCIAL
            else:
                ztype = Tool.RESIDENTIAL

            state['action_queue'].append((ztype, zc, zr))
            if state['action_queue']:
                return state['action_queue'].pop(0)

    # Phase 4: Add vertical wire feeders to zones that need power
    # For zones far from wire row, add wire column
    for zone_col in available_zone_cols[::4]:
        zc = zone_col
        for offset in zone_row_offsets:
            zr = wire_row + offset
            if not (2 <= zr <= WORLD_H - 3):
                continue
            # Check if there's a zone here
            if not any(abs(zr - pr) <= 1 and abs(zc - pc) <= 1 for (pr, pc) in all_zones):
                continue
            # Ensure wire connection from wire_row to zone
            step_dir = 1 if zr > wire_row else -1
            for rr in range(wire_row + step_dir, zr, step_dir):
                if wm[rr, zc] or rm[rr, zc]:
                    continue
                if em[rr, zc]:
                    state['action_queue'].append((Tool.WIRE, zc, rr))
                    if state['action_queue']:
                        return state['action_queue'].pop(0)

    # Phase 5: Second power plant if population high enough
    if pop > 500 and not np.any(plant_mask(tm)[40:50, 60:70]):
        plant2_x, plant2_y = 65, 45
        area_free = all(em[plant2_y + dr, plant2_x + dc]
                        for dr in [-1, 0, 1] for dc in [-1, 0, 1]
                        if 0 <= plant2_y + dr < WORLD_H and 0 <= plant2_x + dc < WORLD_W)
        if area_free:
            return (Tool.COALPOWER, plant2_x, plant2_y)

    # Phase 6: Add more zones to the right if population growing
    if pop > 200:
        extra_col_end = min(95, wire_col_end + 10)
        extra_wire_cols = set(c for (r, c) in wire_positions if r == wire_row)
        if not extra_wire_cols or max(extra_wire_cols) < extra_col_end:
            wc = (max(extra_wire_cols) + 1) if extra_wire_cols else wire_col_end + 1
            if 0 <= wc < WORLD_W and em[wire_row, wc]:
                return (Tool.WIRE, wc, wire_row)
            if 0 <= wc < WORLD_W and em[road_row, wc]:
                return (Tool.ROAD, wc, road_row)

    # Phase 7: Fill in any missing road connections to existing zones
    for zr, zc in sorted(all_zones):
        # Check if zone needs road connection
        road_nearby = any(rm[zr + dr, zc + dc]
                         for dr in range(-2, 3) for dc in range(-2, 3)
                         if 0 <= zr + dr < WORLD_H and 0 <= zc + dc < WORLD_W)
        if not road_nearby:
            # Find nearest road and connect
            for dc in range(-3, 4):
                rc = zc + dc
                if 0 <= rc < WORLD_W and em[road_row, rc]:
                    state['action_queue'].append((Tool.ROAD, rc, road_row))
            for dr in range(min(road_row, zr), max(road_row, zr) + 1):
                if 0 <= dr < WORLD_H and em[dr, zc]:
                    state['action_queue'].append((Tool.ROAD, zc, dr))
            if state['action_queue']:
                return state['action_queue'].pop(0)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map every step to decide next action
    - Places coal plant first, then extends wire spine vertically
    - Builds road columns on both sides of wire
    - Places zones (balanced RCI) where power+road coverage exists
    - Expands infrastructure based on observed city state
    - Uses wider zone placement and more aggressive road extension
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    pop = obs.city_pop

    def pick_tool():
        t = max(total_zones, 1)
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Phase 1: Place first coal plant if none ---
    if not np.any(pm):
        return (Tool.COALPOWER, 55, 50)

    # Find plant centroid
    plant_ys, plant_xs = np.where(pm)
    px = int(np.median(plant_xs))
    py = int(np.median(plant_ys))

    # Wire spine runs vertically; roads flank it on both sides
    wire_col = px + 4
    wire_col = max(3, min(WORLD_W - 4, wire_col))
    road_col_r = wire_col + 3
    road_col_l = wire_col - 3
    road_col_r = max(3, min(WORLD_W - 4, road_col_r))
    road_col_l = max(3, min(WORLD_W - 4, road_col_l))

    # Also add a second pair of road columns further out for more zone coverage
    road_col_r2 = wire_col + 7
    road_col_l2 = wire_col - 7
    road_col_r2 = max(3, min(WORLD_W - 4, road_col_r2))
    road_col_l2 = max(3, min(WORLD_W - 4, road_col_l2))

    # Spine extent based on pop
    if pop < 50:
        spine_half = 10
    elif pop < 150:
        spine_half = 18
    elif pop < 400:
        spine_half = 26
    elif pop < 800:
        spine_half = 34
    else:
        spine_half = 40

    target_min = max(2, py - spine_half)
    target_max = min(WORLD_H - 3, py + spine_half)

    wire_rows = [r for r in range(WORLD_H) if wm[r, wire_col]]

    # --- Phase 2: Bootstrap wire adjacent to plant ---
    if not wire_rows:
        for dy in range(-3, 4):
            nr = py + dy
            if in_bounds(wire_col, nr) and (em[nr, wire_col] or wm[nr, wire_col]) and not pm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)
        # Try horizontal wire from plant to wire_col
        for dc in range(1, abs(wire_col - px) + 1):
            nx = px + dc if wire_col > px else px - dc
            if in_bounds(nx, py) and em[py, nx] and not pm[py, nx]:
                return (Tool.WIRE, nx, py)
        return None

    min_wr = min(wire_rows)
    max_wr = max(wire_rows)

    # --- Phase 3: Extend wire spine ---
    if max_wr < target_max:
        nr = max_wr + 1
        if in_bounds(wire_col, nr) and not pm[nr, wire_col] and (em[nr, wire_col] or wm[nr, wire_col]):
            return (Tool.WIRE, wire_col, nr)
    if min_wr > target_min:
        nr = min_wr - 1
        if in_bounds(wire_col, nr) and not pm[nr, wire_col] and (em[nr, wire_col] or wm[nr, wire_col]):
            return (Tool.WIRE, wire_col, nr)

    # --- Phase 4: Build road columns adjacent to wire ---
    for wr in wire_rows:
        if target_min <= wr <= target_max:
            for rc in [road_col_r, road_col_l]:
                if in_bounds(rc, wr) and em[wr, rc]:
                    return (Tool.ROAD, rc, wr)

    # Build second pair of road columns too
    for wr in wire_rows:
        if target_min <= wr <= target_max:
            for rc in [road_col_r2, road_col_l2]:
                if in_bounds(rc, wr) and em[wr, rc]:
                    return (Tool.ROAD, rc, wr)

    # --- Build proximity masks ---
    def expand_mask(base, radius=2):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-radius, radius + 1):
            for dx in range(-radius, radius + 1):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                result[r0:r1, c0:c1] |= base[sr0:sr1, sc0:sc1]
        return result

    nbr_road = expand_mask(rm, 2)
    nbr_wire = expand_mask(wm | pm, 2)

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and not zone_tiles[nr, nc]:
                    return False
        return True

    # --- Phase 5: Place zones near wire+road coverage ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prioritize candidates close to wire spine
        dists = np.abs(cxs - wire_col)
        order = np.argsort(dists)
        step_off = int(obs.step * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 100:
                break

    # --- Phase 6: Extend roads from existing roads near wire ---
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 30)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx]:
                    if nbr_wire[ny, nx]:
                        return (Tool.ROAD, nx, ny)

    # --- Phase 7: Second coal plant when growing ---
    num_plant_tiles = int(np.sum(pm))
    if pop > 150 and num_plant_tiles < 18:
        # Place second plant to the right
        p2x = px + 20
        p2y = py
        p2x = max(3, min(WORLD_W - 4, p2x))
        p2y = max(3, min(WORLD_H - 4, p2y))
        area_ok = True
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = p2y + dr, p2x + dc
                if not in_bounds(rc, rr):
                    area_ok = False
                elif not em[rr, rc] and not pm[rr, rc]:
                    area_ok = False
        if area_ok:
            return (Tool.COALPOWER, p2x, p2y)
        # Wire horizontal bridge to second plant area
        for wc in range(min(wire_col + 1, p2x), max(wire_col, p2x)):
            if in_bounds(wc, py) and em[py, wc]:
                return (Tool.WIRE, wc, py)

    # --- Phase 8: Third coal plant when city grows further ---
    if pop > 500 and num_plant_tiles < 27:
        p3x = px - 20
        p3y = py
        p3x = max(3, min(WORLD_W - 4, p3x))
        p3y = max(3, min(WORLD_H - 4, p3y))
        area_ok = True
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = p3y + dr, p3x + dc
                if not in_bounds(rc, rr):
                    area_ok = False
                elif not em[rr, rc] and not pm[rr, rc]:
                    area_ok = False
        if area_ok:
            return (Tool.COALPOWER, p3x, p3y)
        # Wire horizontal bridge to third plant
        step_dir = 1 if p3x > wire_col else -1
        for wc in range(wire_col, p3x, step_dir):
            if in_bounds(wc, py) and em[py, wc]:
                return (Tool.WIRE, wc, py)

    # --- Phase 9: Services when pop is high enough ---
    if pop > 100:
        fsx, fsy = px - 8, py - 10
        fsx = max(1, min(WORLD_W - 2, fsx))
        fsy = max(1, min(WORLD_H - 2, fsy))
        if in_bounds(fsx, fsy) and em[fsy, fsx]:
            return (Tool.FIRESTATION, fsx, fsy)
        psx, psy = px - 8, py + 10
        psx = max(1, min(WORLD_W - 2, psx))
        psy = max(1, min(WORLD_H - 2, psy))
        if in_bounds(psx, psy) and em[psy, psx]:
            return (Tool.POLICESTATION, psx, psy)

    # --- Phase 10: Add horizontal roads connecting road columns ---
    # This helps zones between columns get road access
    if len(wire_rows) > 0:
        mid_row = wire_rows[len(wire_rows) // 2]
        for step_r in range(road_col_l, road_col_r + 1):
            if in_bounds(step_r, mid_row) and em[mid_row, step_r]:
                return (Tool.ROAD, step_r, mid_row)

    # --- Phase 11: Extend wire laterally to reach new areas ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 20)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = wx + dx2, wy + dy2
                if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                    return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map each step and reacts to current state.
    Strategy:
    - Place coal power plant first
    - Extend wire spine horizontally from plant
    - Build parallel roads above/below wire spine
    - Place zones adjacent to roads + wire coverage
    - Add more plants and services as population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2
    pop = obs.city_pop

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Wire spine row and parallel road rows
    wire_row = cy
    road_above = cy - 4
    road_below = cy + 4

    # Zone placement rows (between roads and further out)
    zone_rows_above = [cy - 8, cy - 11]
    zone_rows_below = [cy + 8, cy + 11]

    # Target x range for development
    if pop < 100:
        x_half = 12
    elif pop < 300:
        x_half = 22
    elif pop < 600:
        x_half = 35
    elif pop < 1000:
        x_half = 45
    else:
        x_half = 55

    x_min = max(4, cx - x_half)
    x_max = min(WORLD_W - 5, cx + x_half)

    # --- Phase 1: Place first coal power plant ---
    if not np.any(pm):
        px = max(4, cx - x_half - 5)
        py = wire_row
        return (Tool.COALPOWER, px, py)

    # Find existing plants
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # --- Phase 2: Build horizontal wire spine ---
    # Find current wire extent on wire_row
    wire_on_row = [c for c in range(WORLD_W) if wm[wire_row, c]]

    if not wire_on_row:
        # Start wire just right of plant
        for dc in range(1, 10):
            c = plant_cx + dc
            if in_bounds(c, wire_row) and em[wire_row, c]:
                return (Tool.WIRE, c, wire_row)
        return None

    min_wc = min(wire_on_row)
    max_wc = max(wire_on_row)

    # Extend wire right
    if max_wc < x_max:
        nc = max_wc + 1
        if in_bounds(nc, wire_row) and em[wire_row, nc] and not pm[wire_row, nc]:
            return (Tool.WIRE, nc, wire_row)

    # Extend wire left toward plant
    if min_wc > x_min:
        nc = min_wc - 1
        if in_bounds(nc, wire_row) and em[wire_row, nc] and not pm[wire_row, nc]:
            return (Tool.WIRE, nc, wire_row)

    # --- Phase 3: Connect plant to wire spine if not connected ---
    # Check adjacency of plant to any wire
    plant_connected = False
    for pr, pc in zip(plant_rows, plant_cols):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc2 = pr + dr, pc + dc
                if in_bounds(nc2, nr) and wm[nr, nc2]:
                    plant_connected = True
    if not plant_connected and wire_on_row:
        # Draw wire horizontally from plant toward wire spine
        target_c = min_wc
        bridge_r = wire_row
        for bc in range(plant_cx + 1, target_c + 1):
            if in_bounds(bc, bridge_r):
                if wm[bridge_r, bc]:
                    break
                if em[bridge_r, bc] and not pm[bridge_r, bc]:
                    return (Tool.WIRE, bc, bridge_r)
        # Try vertical wire to connect plant to wire_row
        step_r = 1 if wire_row > plant_cy else -1
        for br in range(plant_cy + step_r, wire_row + step_r, step_r):
            bc2 = plant_cx + 2
            if in_bounds(bc2, br) and em[br, bc2] and not pm[br, bc2] and not wm[br, bc2]:
                return (Tool.WIRE, bc2, br)

    # --- Phase 4: Build road rows parallel to wire spine ---
    # Fill roads above and below the wire spine
    for wc in range(x_min, x_max + 1):
        if wm[wire_row, wc]:
            # Road above
            if in_bounds(wc, road_above) and em[road_above, wc] and not pm[road_above, wc]:
                return (Tool.ROAD, wc, road_above)
            # Road below
            if in_bounds(wc, road_below) and em[road_below, wc] and not pm[road_below, wc]:
                return (Tool.ROAD, wc, road_below)

    # --- Phase 5: Vertical connector roads every 8 columns ---
    for wc in range(x_min, x_max + 1, 8):
        if wm[wire_row, wc]:
            for wr2 in range(road_above, road_below + 1):
                if in_bounds(wc, wr2) and em[wr2, wc] and not pm[wr2, wc] and not wm[wr2, wc] and not rm[wr2, wc]:
                    return (Tool.ROAD, wc, wr2)

    # --- Determine zone tool based on current counts ---
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(total_zones, 1)
        # Target: 45% res, 30% com, 25% ind
        if ind_count / t < 0.22:
            return Tool.INDUSTRIAL
        if com_count / t < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zy, zx):
        if zy < 1 or zy > WORLD_H - 2 or zx < 1 or zx > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr2, rc2 = zy + dr, zx + dc
                if not (0 <= rr2 < WORLD_H and 0 <= rc2 < WORLD_W):
                    return False
                t2 = tm[rr2, rc2]
                # Allow empty or existing zone tiles
                if not (em[rr2, rc2] or resm[rr2, rc2] or comm[rr2, rc2] or indm[rr2, rc2]):
                    return False
        return True

    # --- Phase 6: Place zones near roads + wire coverage ---
    # Build neighbor masks for road and wire
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, :2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys_a, cxs_a = np.where(cand_mask)
    if len(cxs_a) > 0:
        # Sort candidates by proximity to wire spine center
        dists = np.abs(cxs_a.astype(int) - cx) + np.abs(cys_a.astype(int) - wire_row) * 2
        sort_idx = np.argsort(dists)
        for k_idx in range(min(len(cxs_a), 100)):
            k = int(sort_idx[k_idx])
            zx, zy = int(cxs_a[k]), int(cys_a[k])
            if x_min <= zx <= x_max and zone_area_ok(zy, zx):
                return (pick_tool(), zx, zy)

    # --- Phase 7: Second power plant if population growing ---
    plant_tiles = int(np.sum(pm))
    plant_count = max(1, plant_tiles // 6)

    if pop > 150 and plant_count < 2:
        p2x = min(WORLD_W - 5, plant_cx + 45)
        p2y = wire_row
        if in_bounds(p2x, p2y) and em[p2y, p2x]:
            nearby = any(
                in_bounds(p2x + dx2, p2y + dy2) and pm[p2y + dy2, p2x + dx2]
                for dy2 in range(-7, 8) for dx2 in range(-7, 8)
            )
            if not nearby:
                return (Tool.COALPOWER, p2x, p2y)
        # Extend wire rightward to reach second plant location
        if max_wc < p2x - 2:
            nc = max_wc + 1
            if in_bounds(nc, wire_row) and em[wire_row, nc] and not pm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    if pop > 500 and plant_count < 3:
        p3x = max(4, plant_cx - 1)
        p3y = wire_row + 18
        if in_bounds(p3x, p3y) and em[p3y, p3x]:
            nearby = any(
                in_bounds(p3x + dx2, p3y + dy2) and pm[p3y + dy2, p3x + dx2]
                for dy2 in range(-7, 8) for dx2 in range(-7, 8)
            )
            if not nearby:
                return (Tool.COALPOWER, p3x, p3y)

    # --- Phase 8: Services ---
    if pop > 200:
        fx, fy = cx, cy - 12
        if in_bounds(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
    if pop > 350:
        px2, py2 = cx + 12, cy + 12
        if in_bounds(px2, py2) and em[py2, px2]:
            return (Tool.POLICESTATION, px2, py2)
    if pop > 600:
        fx2, fy2 = cx - 12, cy + 12
        if in_bounds(fx2, fy2) and em[fy2, fx2]:
            return (Tool.FIRESTATION, fx2, fy2)

    # --- Phase 9: Extend roads reactively near unpowered zones ---
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = int(obs.step * 13) % len(road_xs_arr)
        rx_s = int(road_xs_arr[step_k])
        ry_s = int(road_ys_arr[step_k])
        for dy2, dx2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx2, ny2 = rx_s + dx2, ry_s + dy2
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                if nbr_wire[ny2, nx2] and x_min <= nx2 <= x_max:
                    return (Tool.ROAD, nx2, ny2)

    # --- Phase 10: Extend wire reactively ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k = int(obs.step * 7) % len(wire_xs_arr)
        wx_s = int(wire_xs_arr[step_k])
        wy_s = int(wire_ys_arr[step_k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = wx_s + dx2, wy_s + dy2
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                if x_min <= nx2 <= x_max:
                    return (Tool.WIRE, nx2, ny2)

    # --- Phase 11: Add second parallel wire row for more coverage ---
    wire2_row = cy + 10
    if pop > 400:
        for wc in range(x_min, x_max + 1):
            if wm[wire_row, wc]:
                if in_bounds(wc, wire2_row) and em[wire2_row, wc] and not pm[wire2_row, wc]:
                    return (Tool.WIRE, wc, wire2_row)
        # Connect them vertically
        for wc in range(x_min, x_max + 1, 10):
            if wm[wire_row, wc]:
                for wr3 in range(wire_row + 1, wire2_row + 1):
                    if in_bounds(wc, wr3) and em[wr3, wc] and not pm[wr3, wc] and not wm[wr3, wc]:
                        return (Tool.WIRE, wc, wr3)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder - improved version.
    Reads current map state every step and reacts to what's there.

    Key changes from parent:
    - More aggressive road network building (grid pattern)
    - Wire spine extended further before zone placement
    - Better zone clustering near road intersections
    - Earlier service buildings for faster growth
    - Nuclear plant consideration for larger cities
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Anchor slightly left of center to leave room for plant
    cx, cy = 55, 48

    # ---- Phase 1: Ensure coal power plant exists ----
    plant_ys, plant_xs = np.where(pm)
    has_plant = len(plant_xs) > 0
    if not has_plant:
        # Place plant at anchor, road/wire will extend from it
        return (Tool.COALPOWER, cx, cy)

    power_map = pm | wm

    # ---- Phase 2: Wire spine - extend vertically from plant ----
    def find_wire_extension():
        # Primary spine: vertical at plant x
        px = int(plant_xs[0])
        py = int(plant_ys[0])

        # Build vertical spine from plant
        spine_targets = []
        for dy in range(-20, 21):
            spine_targets.append((px, py + dy))
        # Horizontal arm through zone area
        for dx in range(-15, 16):
            spine_targets.append((px + dx, py))
            spine_targets.append((px + dx, py - 3))
            spine_targets.append((px + dx, py + 3))

        for (wx, wy) in spine_targets:
            if not in_bounds(wx, wy):
                continue
            if bool(wm[wy, wx]) or bool(pm[wy, wx]):
                continue
            if bool(rm[wy, wx]):
                continue
            if not bool(em[wy, wx]):
                continue
            # Must be adjacent to existing power
            for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx2, ny2 = wx+ddx, wy+ddy
                if in_bounds(nx2, ny2) and bool(power_map[ny2, nx2]):
                    return (Tool.WIRE, wx, wy)
        return None

    # ---- Phase 3: Road network - grid pattern ----
    def find_road_extension():
        px = int(plant_xs[0])
        py = int(plant_ys[0])

        # Build a grid of roads offset from plant
        # Horizontal roads every 4 rows, vertical roads every 4 cols
        # This creates zones that can be placed in the 3x3 gaps
        candidates = []

        # Horizontal roads at fixed y offsets from plant
        for row_off in [-12, -8, -4, 0, 4, 8, 12, 16]:
            ry = py + row_off
            for dx in range(-18, 19):
                candidates.append((px + dx, ry))

        # Vertical roads at fixed x offsets from plant
        for col_off in [-12, -8, -4, 0, 4, 8, 12]:
            rx = px + col_off
            for dy in range(-18, 19):
                candidates.append((rx, py + dy))

        for (rx, ry) in candidates:
            if not in_bounds(rx, ry):
                continue
            if bool(rm[ry, rx]):
                continue
            if bool(pm[ry, rx]) or bool(wm[ry, rx]):
                continue
            if not bool(em[ry, rx]):
                continue
            # Must be adjacent to existing road or adjacent to plant
            for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx2, ny2 = rx+ddx, ry+ddy
                if in_bounds(nx2, ny2) and bool(rm[ny2, nx2]):
                    return (Tool.ROAD, rx, ry)
            for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1),(2,0),(-2,0),(0,2),(0,-2)]:
                nx2, ny2 = rx+ddx, ry+ddy
                if in_bounds(nx2, ny2) and bool(pm[ny2, nx2]):
                    return (Tool.ROAD, rx, ry)
        return None

    # Count zones for balance
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        # Aim for ~55% R, 25% C, 20% I
        if ind_count / total_zones < 0.20:
            return Tool.INDUSTRIAL
        if com_count / total_zones < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- Phase 4: Place zones in gaps between roads ----
    def find_zone_placement():
        # Expand road influence by 2 tiles
        nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-2, 3):
            for dx in range(-2, 3):
                if abs(dy) + abs(dx) <= 2:
                    sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                    sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                    r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                    c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                    nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

        # Power influence: 8 tile radius from wire or plant
        nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-8, 9):
            for dx in range(-8, 9):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
                nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

        zone_mask = resm | comm | indm
        cand = em & nbr_road & nbr_power
        # Keep away from edges
        cand[:2, :] = False
        cand[WORLD_H-2:, :] = False
        cand[:, :2] = False
        cand[:, WORLD_W-2:] = False

        cys, cxs = np.where(cand)
        if len(cxs) == 0:
            return None

        # Prefer zones close to map center / plant
        px = int(plant_xs[0]) if len(plant_xs) > 0 else cx
        py = int(plant_ys[0]) if len(plant_ys) > 0 else cy

        # Sort candidates by distance to plant (prefer nearby)
        dists = np.abs(cxs - px) + np.abs(cys - py)
        order = np.argsort(dists)

        tool = pick_tool()

        # Use step-based offset for variety among nearest candidates
        offset_base = int(obs.step * 7 + int(obs.city_pop * 3)) % max(len(cxs), 1)

        for i in range(min(len(cxs), 80)):
            # Try near-optimal candidates first, with some variation
            if i < 40:
                k = order[i % len(order)]
            else:
                k = (offset_base + i) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            # Check 3x3 clearance (zone center needs 3x3 empty or already zone)
            ok = True
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    ny2, nx2 = zy + dr, zx + dc
                    if not in_bounds(nx2, ny2):
                        ok = False; break
                    cell = tm[ny2, nx2]
                    if not (bool(em[ny2, nx2]) or bool(zone_mask[ny2, nx2])):
                        ok = False; break
                if not ok:
                    break
            if ok:
                return (tool, zx, zy)
        return None

    # ---- Measure current infrastructure ----
    wire_count = int(np.sum(wm))
    road_count = int(np.sum(rm))

    # How many vertical spine wires do we have?
    px = int(plant_xs[0]) if len(plant_xs) > 0 else cx
    py = int(plant_ys[0]) if len(plant_ys) > 0 else cy
    spine_filled = sum(1 for dy in range(-20, 21)
                      if in_bounds(px, py+dy) and bool(wm[py+dy, px]))

    wire_action = find_wire_extension()
    road_action = find_road_extension()

    # ---- Decision priority ----

    # Must have wire spine before anything else
    if spine_filled < 15 and wire_action is not None:
        return wire_action

    # Must have initial roads
    if road_count < 8 and road_action is not None:
        return road_action

    # Use step modulo to interleave infrastructure and zones
    step_mod = obs.step % 10

    # More road-heavy early on, more zone-heavy later
    if obs.city_pop < 200:
        # Early game: 30% wire, 40% road, 30% zones
        if step_mod in (0, 1, 2) and wire_action is not None:
            return wire_action
        if step_mod in (3, 4, 5, 6) and road_action is not None:
            return road_action
        zone_action = find_zone_placement()
        if zone_action is not None:
            return zone_action
    elif obs.city_pop < 600:
        # Mid game: 20% wire, 30% road, 50% zones
        if step_mod in (0, 1) and wire_action is not None:
            return wire_action
        if step_mod in (2, 3, 4) and road_action is not None:
            return road_action
        zone_action = find_zone_placement()
        if zone_action is not None:
            return zone_action
    else:
        # Late game: mostly zones with some infrastructure
        if step_mod == 0 and wire_action is not None:
            return wire_action
        if step_mod in (1, 2) and road_action is not None:
            return road_action
        zone_action = find_zone_placement()
        if zone_action is not None:
            return zone_action

    # Services to boost growth
    if obs.city_pop > 200:
        # Place fire stations at key locations
        for fx, fy in [(px+8, py-10), (px-8, py+10), (px+10, py+8), (px-10, py-8)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.FIRESTATION, fx, fy)

    if obs.city_pop > 400:
        for fx, fy in [(px+8, py+10), (px-8, py-10), (px+12, py-5), (px-12, py+5)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.POLICESTATION, fx, fy)

    if obs.city_pop > 800:
        # Add second power plant if needed
        if len(plant_xs) < 2:
            for fx, fy in [(px+15, py), (px-15, py), (px, py+15), (px, py-15)]:
                if in_bounds(fx, fy) and bool(em[fy, fx]):
                    return (Tool.COALPOWER, fx, fy)

    # Fallbacks
    if wire_action is not None:
        return wire_action
    if road_action is not None:
        return road_action

    # Extend road from any existing road tile
    rys, rxs = np.where(rm)
    if len(rxs) > 0:
        k2 = int(obs.step * 17 + int(obs.city_pop)) % len(rxs)
        rx2, ry2 = int(rxs[k2]), int(rys[k2])
        for ddx, ddy in [(0,1),(1,0),(0,-1),(-1,0)]:
            nx2, ny2 = rx2+ddx, ry2+ddy
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and not bool(wm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy v3:
    - Reads tile_map every step
    - Builds a cross-shaped power+road grid
    - Reactively places zones where power+road coverage exists
    - Adapts to observed map state each step
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Phase 1: Place first coal plant if missing ---
    if not np.any(pm):
        return (Tool.COALPOWER, 60, 50)

    plant_ys, plant_xs = np.where(pm)
    px = int(np.median(plant_xs))
    py = int(np.median(plant_ys))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    pop = obs.city_pop

    def pick_tool():
        t = max(total_zones, 1)
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def expand_mask(base, radius=2):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-radius, radius + 1):
            for dx in range(-radius, radius + 1):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
                result[r0:r1, c0:c1] |= base[sr0:sr1, sc0:sc1]
        return result

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and not zone_tiles[nr, nc]:
                    return False
        return True

    # Spine layout: vertical wire at wire_col, horizontal wire at wire_row
    wire_col = px + 2
    wire_col = max(4, min(WORLD_W - 5, wire_col))
    wire_row = py
    wire_row = max(4, min(WORLD_H - 5, wire_row))

    # Spine extent grows with pop
    pop_factor = min(35, pop // 15)
    y_extent = 14 + pop_factor
    x_extent = 14 + pop_factor
    tmin = max(2, wire_row - y_extent)
    tmax = min(WORLD_H - 3, wire_row + y_extent)
    lmin = max(2, wire_col - x_extent)
    lmax = min(WORLD_W - 3, wire_col + x_extent)

    # --- Phase 2: Build vertical wire spine ---
    wire_in_col = [r for r in range(WORLD_H) if wm[r, wire_col]]
    if not wire_in_col:
        # Seed wire adjacent to plant
        for dy in range(-2, 3):
            ny = py + dy
            if in_bounds(wire_col, ny) and not pm[ny, wire_col]:
                if em[ny, wire_col] or wm[ny, wire_col]:
                    return (Tool.WIRE, wire_col, ny)
        return (Tool.WIRE, wire_col, py)
    else:
        min_wr = min(wire_in_col)
        max_wr = max(wire_in_col)
        # Alternate extending up/down based on step
        if obs.step % 2 == 0:
            if max_wr < tmax:
                nr = max_wr + 1
                if in_bounds(wire_col, nr) and not pm[nr, wire_col]:
                    return (Tool.WIRE, wire_col, nr)
            if min_wr > tmin:
                nr = min_wr - 1
                if in_bounds(wire_col, nr) and not pm[nr, wire_col]:
                    return (Tool.WIRE, wire_col, nr)
        else:
            if min_wr > tmin:
                nr = min_wr - 1
                if in_bounds(wire_col, nr) and not pm[nr, wire_col]:
                    return (Tool.WIRE, wire_col, nr)
            if max_wr < tmax:
                nr = max_wr + 1
                if in_bounds(wire_col, nr) and not pm[nr, wire_col]:
                    return (Tool.WIRE, wire_col, nr)

    wire_in_col = [r for r in range(WORLD_H) if wm[r, wire_col]]

    # --- Phase 3: Build horizontal wire spine ---
    wire_in_row = [c for c in range(WORLD_W) if wm[wire_row, c]]
    if not wire_in_row and wire_in_col:
        # Seed horizontal from vertical spine at wire_row
        for dc in [1, -1, 2, -2]:
            nc = wire_col + dc
            if in_bounds(nc, wire_row) and not pm[wire_row, nc]:
                if em[wire_row, nc] or wm[wire_row, nc]:
                    return (Tool.WIRE, nc, wire_row)
    elif wire_in_row:
        min_wc = min(wire_in_row)
        max_wc = max(wire_in_row)
        if obs.step % 2 == 0:
            if max_wc < lmax:
                nc = max_wc + 1
                if in_bounds(nc, wire_row) and not pm[wire_row, nc]:
                    return (Tool.WIRE, nc, wire_row)
            if min_wc > lmin:
                nc = min_wc - 1
                if in_bounds(nc, wire_row) and not pm[wire_row, nc]:
                    return (Tool.WIRE, nc, wire_row)
        else:
            if min_wc > lmin:
                nc = min_wc - 1
                if in_bounds(nc, wire_row) and not pm[wire_row, nc]:
                    return (Tool.WIRE, nc, wire_row)
            if max_wc < lmax:
                nc = max_wc + 1
                if in_bounds(nc, wire_row) and not pm[wire_row, nc]:
                    return (Tool.WIRE, nc, wire_row)

    wire_in_row = [c for c in range(WORLD_W) if wm[wire_row, c]]

    # --- Phase 4: Build roads adjacent to vertical wire spine ---
    road_col_r = wire_col + 1
    road_col_l = wire_col - 1
    for wr in wire_in_col:
        if in_bounds(road_col_r, wr) and em[wr, road_col_r] and not pm[wr, road_col_r]:
            return (Tool.ROAD, road_col_r, wr)
        if in_bounds(road_col_l, wr) and em[wr, road_col_l] and not pm[wr, road_col_l]:
            return (Tool.ROAD, road_col_l, wr)

    # --- Phase 5: Build roads adjacent to horizontal wire spine ---
    road_row_u = wire_row - 1
    road_row_d = wire_row + 1
    for wc in wire_in_row:
        if in_bounds(wc, road_row_u) and em[road_row_u, wc] and not pm[road_row_u, wc] and not wm[road_row_u, wc]:
            return (Tool.ROAD, wc, road_row_u)
        if in_bounds(wc, road_row_d) and em[road_row_d, wc] and not pm[road_row_d, wc] and not wm[road_row_d, wc]:
            return (Tool.ROAD, wc, road_row_d)

    # --- Build coverage masks ---
    nbr_road = expand_mask(rm, 2)
    nbr_wire = expand_mask(wm | pm, 2)

    # --- Phase 6: Place zones where road+wire coverage exists ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score: prefer close to cross intersection, with some step-based offset
        dist_v = np.abs(cxs - wire_col)
        dist_h = np.abs(cys - wire_row)
        scores = dist_v + dist_h
        order = np.argsort(scores)
        step_off = int(obs.step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 80:
                break

    # --- Phase 7: Second coal plant when city grows ---
    num_plant_tiles = int(np.sum(pm))
    if (pop > 200 or total_zones > 8) and num_plant_tiles < 18:
        # Try placing second plant to the right/above
        p2x = px + 20
        p2y = py - 18
        p2x = max(3, min(WORLD_W - 4, p2x))
        p2y = max(3, min(WORLD_H - 4, p2y))
        area_ok = all(
            in_bounds(p2x + dc, p2y + dr) and (em[p2y + dr, p2x + dc] or pm[p2y + dr, p2x + dc])
            for dr in [-1, 0, 1] for dc in [-1, 0, 1]
        )
        if area_ok and em[p2y, p2x]:
            return (Tool.COALPOWER, p2x, p2y)
        # Wire horizontal bridge toward second plant area
        for wc in range(min(wire_col + 2, p2x), max(wire_col + 2, p2x) + 1):
            if in_bounds(wc, wire_row) and not pm[wire_row, wc]:
                if em[wire_row, wc] or wm[wire_row, wc]:
                    return (Tool.WIRE, wc, wire_row)

    # --- Phase 8: Services when pop high enough ---
    if pop > 150:
        fsx, fsy = px - 8, py - 8
        fsx = max(1, min(WORLD_W - 2, fsx))
        fsy = max(1, min(WORLD_H - 2, fsy))
        if in_bounds(fsx, fsy) and em[fsy, fsx]:
            return (Tool.FIRESTATION, fsx, fsy)
    if pop > 200:
        psx, psy = px - 8, py + 8
        psx = max(1, min(WORLD_W - 2, psx))
        psy = max(1, min(WORLD_H - 2, psy))
        if in_bounds(psx, psy) and em[psy, psx]:
            return (Tool.POLICESTATION, psx, psy)

    # --- Phase 9: Extend roads from existing roads near wire ---
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 25)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx]:
                    if nbr_wire[ny, nx]:
                        return (Tool.ROAD, nx, ny)

    # --- Phase 10: Extend wire toward uncovered zones ---
    uncov_zones = zone_tiles & ~nbr_wire
    if np.any(uncov_zones):
        uz_ys, uz_xs = np.where(uncov_zones)
        wire_ys_arr, wire_xs_arr = np.where(wm)
        if len(wire_xs_arr) > 0:
            k = int(obs.step * 7) % len(uz_xs)
            ux, uy = int(uz_xs[k]), int(uz_ys[k])
            dists2 = np.abs(wire_xs_arr - ux) + np.abs(wire_ys_arr - uy)
            best = np.argmin(dists2)
            wx2, wy2 = int(wire_xs_arr[best]), int(wire_ys_arr[best])
            dx2 = int(np.sign(ux - wx2))
            dy2 = int(np.sign(uy - wy2))
            if dx2 != 0:
                nx2, ny2 = wx2 + dx2, wy2
            else:
                nx2, ny2 = wx2, wy2 + dy2
            if in_bounds(nx2, ny2) and not pm[ny2, nx2] and em[ny2, nx2]:
                return (Tool.WIRE, nx2, ny2)

    # --- Phase 11: General wire extension ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 20)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx3, wy3 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx3 + dx3, wy3 + dy3
                if in_bounds(nx3, ny3) and em[ny3, nx3] and not pm[ny3, nx3]:
                    return (Tool.WIRE, nx3, ny3)

    return None

def act(obs, state):
    """
    Variation: builds a HORIZONTAL layout with two neighborhoods side by side,
    connected by a horizontal road spine. Uses balanced R/C/I mix.
    Wire runs horizontally from plants; zones cluster above and below the road.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        r_r = res_count / t
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Phase 1: Place first coal plant at left cluster ---
    # Plant 1 at (25, 50), Plant 2 at (75, 50)
    p1x, p1y = 25, 50
    p2x, p2y = 75, 50

    if not np.any(pm):
        return (Tool.COALPOWER, p1x, p1y)

    plant_ys, plant_xs = np.where(pm)
    plant_count = len(set(zip(plant_xs.tolist(), plant_ys.tolist())))

    # Horizontal road spine at row 50 (through plants area), but we use row 44 and 56
    # Main road row: y=44 (above plants), y=56 (below plants)
    road_row_top = 44
    road_row_bot = 56
    # Road columns from x=10 to x=110
    road_x_min = 10
    road_x_max = 110

    # Wire row: y=50 (horizontal, through both plants)
    wire_row = 50

    # Step 1: extend wire horizontally from plant 1 to plant 2
    wire_in_row = [c for c in range(WORLD_W) if wm[wire_row, c] or pm[wire_row, c]]
    if wire_in_row:
        min_wc = min(wire_in_row)
        max_wc = max(wire_in_row)
        # Extend right toward p2x
        if max_wc < p2x - 2:
            nc = max_wc + 1
            if in_bounds(nc, wire_row) and em[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)
        # Extend left
        if min_wc > road_x_min:
            nc = min_wc - 1
            if in_bounds(nc, wire_row) and em[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)
        # Extend right past p2x to road_x_max
        if max_wc < road_x_max:
            nc = max_wc + 1
            if in_bounds(nc, wire_row) and (em[wire_row, nc] or pm[wire_row, nc]):
                if em[wire_row, nc]:
                    return (Tool.WIRE, nc, wire_row)

    # Place second plant
    nearby_p2 = any(
        in_bounds(p2x + dx, p2y + dy) and pm[p2y + dy, p2x + dx]
        for dy in range(-4, 5) for dx in range(-4, 5)
    )
    if not nearby_p2 and total_zones >= 6:
        if in_bounds(p2x, p2y) and (em[p2y, p2x] or wm[p2y, p2x]):
            return (Tool.COALPOWER, p2x, p2y)

    # Step 2: build horizontal road at road_row_top
    for cx in range(road_x_min, road_x_max + 1):
        if in_bounds(cx, road_row_top) and em[road_row_top, cx] and not pm[road_row_top, cx]:
            return (Tool.ROAD, cx, road_row_top)

    # Step 3: build horizontal road at road_row_bot
    for cx in range(road_x_min, road_x_max + 1):
        if in_bounds(cx, road_row_bot) and em[road_row_bot, cx] and not pm[road_row_bot, cx]:
            return (Tool.ROAD, cx, road_row_bot)

    # Step 4: vertical connector roads at x=20,40,60,80,100
    connector_xs = [20, 40, 60, 80, 100]
    for cx in connector_xs:
        for ry in range(road_row_top, road_row_bot + 1):
            if in_bounds(cx, ry) and em[ry, cx] and not pm[ry, cx]:
                return (Tool.ROAD, cx, ry)

    # Build proximity masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and not zone_tiles[nr, nc]:
                    return False
        return True

    # Also add vertical wire from wire_row toward road rows for power connectivity
    # Wire vertical connectors at connector_xs
    for cx in connector_xs:
        for ry in range(min(wire_row, road_row_top) - 1, max(wire_row, road_row_top) + 2):
            if in_bounds(cx, ry) and em[ry, cx] and not pm[ry, cx]:
                if wm[wire_row, cx] or pm[wire_row, cx]:
                    # wire toward top road
                    for vy in range(wire_row, road_row_top - 1, -1):
                        if in_bounds(cx, vy) and em[vy, cx] and not pm[vy, cx]:
                            return (Tool.WIRE, cx, vy)
                    for vy in range(wire_row, road_row_bot + 2):
                        if in_bounds(cx, vy) and em[vy, cx] and not pm[vy, cx]:
                            return (Tool.WIRE, cx, vy)

    # Candidate zone centers above road_row_top (rows 36-42) and below road_row_bot (rows 58-64)
    zone_band_top = (road_row_top - 8, road_row_top - 1)  # rows 36-43
    zone_band_bot = (road_row_bot + 1, road_row_bot + 8)  # rows 57-64

    cand_mask = em & nbr_road & nbr_wire
    # Focus on our zone bands
    band_mask = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    band_mask[zone_band_top[0]:zone_band_top[1]+1, road_x_min:road_x_max+1] = True
    band_mask[zone_band_bot[0]:zone_band_bot[1]+1, road_x_min:road_x_max+1] = True
    # Also allow between the roads
    band_mask[road_row_top+1:road_row_bot, road_x_min:road_x_max+1] = True

    cand_mask = cand_mask & band_mask
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prefer zones closer to a connector x
        def dist_to_connector(x):
            return min(abs(x - cx) for cx in connector_xs)
        dists = np.array([dist_to_connector(int(cxs[i])) for i in range(len(cxs))])
        order = np.argsort(dists)
        step_off = int(obs.step * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 100:
                break

    # Services
    if obs.city_pop > 200:
        for fsx, fsy in [(p1x - 10, p1y - 8), (p2x + 10, p2y + 8)]:
            if in_bounds(fsx, fsy) and em[fsy, fsx]:
                return (Tool.FIRESTATION, fsx, fsy)
    if obs.city_pop > 400:
        for psx, psy in [(p1x - 10, p1y + 8), (p2x + 10, p2y - 8)]:
            if in_bounds(psx, psy) and em[psy, psx]:
                return (Tool.POLICESTATION, psx, psy)

    # Expand wire laterally if gaps
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 20)):
            k = (step_k + offset * 7) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx + dx, wy + dy
                if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx]:
                    return (Tool.WIRE, nx, ny)

    # Extend roads near wire
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k2 = int(obs.step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 20)):
            k = (step_k2 + offset * 5) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx] and nbr_wire[ny, nx]:
                    return (Tool.ROAD, nx, ny)

    return None

def act(obs, state):
    """
    Evolved policy: builds a HORIZONTAL layout with two neighborhoods side-by-side.
    - First coal plant at (30, 50), second at (80, 50)
    - Horizontal wire spine connecting both plants
    - Roads above and below the wire spine
    - Dense zone placement with balanced R/C/I mix
    - Services placed reactively
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Count zones
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        # Aim for ~50% RES, 25% COM, 25% IND
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        r_r = res_count / t
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Step 1: Place first coal plant
    if not np.any(pm):
        return (Tool.COALPOWER, 30, 50)

    plant_ys, plant_xs = np.where(pm)
    plant_locs = list(zip(plant_xs.tolist(), plant_ys.tolist()))

    # Step 2: Place second coal plant if pop warrants
    has_second = any(px > 60 for px, py in plant_locs)
    if not has_second and total_zones > 8:
        p2x, p2y = 80, 50
        nearby = any(
            in_bounds(p2x + dx, p2y + dy) and pm[p2y + dy, p2x + dx]
            for dy in range(-6, 7) for dx in range(-6, 7)
        )
        if not nearby:
            # Check if area is clear enough
            if em[p2y, p2x]:
                return (Tool.COALPOWER, p2x, p2y)

    # Horizontal wire spine at row 50
    wire_row = 50

    # Determine horizontal extent of wire
    # Connect from plant1 (x=30) to plant2 (x=80) or just extend from plant1
    plant_xs_list = [px for px, py in plant_locs]
    min_px = min(plant_xs_list) if plant_xs_list else 30
    max_px = max(plant_xs_list) if plant_xs_list else 30

    # Wire extends from min_px+2 to max_px+2, plus expansion based on pop
    pop_factor = min(25, obs.city_pop // 20)
    wire_left = max(3, min_px - pop_factor)
    wire_right = min(WORLD_W - 4, max_px + 2 + pop_factor)

    # Build horizontal wire spine
    wire_in_row = [c for c in range(WORLD_W) if wm[wire_row, c]]
    if not wire_in_row:
        # Start wire adjacent to plant
        wx = min_px + 2
        if in_bounds(wx, wire_row) and (em[wire_row, wx] or wm[wire_row, wx]):
            if not pm[wire_row, wx]:
                return (Tool.WIRE, wx, wire_row)
    else:
        min_wc = min(wire_in_row)
        max_wc = max(wire_in_row)
        # Extend right first
        if max_wc < wire_right:
            nc = max_wc + 1
            if in_bounds(nc, wire_row) and (em[wire_row, nc] or wm[wire_row, nc]) and not pm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)
        # Extend left
        if min_wc > wire_left:
            nc = min_wc - 1
            if in_bounds(nc, wire_row) and (em[wire_row, nc] or wm[wire_row, nc]) and not pm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # Also build vertical wire at plant columns to power zones above/below
    if wire_in_row:
        min_wc = min(wire_in_row)
        max_wc = max(wire_in_row)
        # Vertical spines at x=32 and x=78
        v_cols = [min_px + 2]
        if max_px != min_px:
            v_cols.append(max_px + 2)

        v_extent = min(12, 4 + obs.city_pop // 30)
        for vc in v_cols:
            if not in_bounds(vc, wire_row):
                continue
            for dy in range(1, v_extent + 1):
                for sign in [1, -1]:
                    wy = wire_row + sign * dy
                    if in_bounds(vc, wy) and em[wy, vc] and not pm[wy, vc]:
                        return (Tool.WIRE, vc, wy)

    # Roads above and below wire spine
    road_row_above = wire_row - 1
    road_row_below = wire_row + 1

    for wc in wire_in_row:
        if in_bounds(wc, road_row_above) and em[road_row_above, wc]:
            return (Tool.ROAD, wc, road_row_above)
        if in_bounds(wc, road_row_below) and em[road_row_below, wc]:
            return (Tool.ROAD, wc, road_row_below)

    # Also build vertical roads flanking vertical wire spines
    plant_xs_list2 = [px for px, py in plant_locs]
    for px_val in plant_xs_list2:
        vc = px_val + 2
        v_extent2 = min(12, 4 + obs.city_pop // 30)
        for dy in range(1, v_extent2 + 1):
            for sign in [1, -1]:
                wy = wire_row + sign * dy
                # Road columns left and right of vertical wire
                for rx in [vc - 1, vc + 1]:
                    if in_bounds(rx, wy) and em[wy, rx]:
                        # Only if near wire
                        near_wire = any(
                            in_bounds(rx + ddx, wy + ddy) and (wm[wy + ddy, rx + ddx] or pm[wy + ddy, rx + ddx])
                            for ddx in range(-2, 3) for ddy in range(-2, 3)
                            if in_bounds(rx + ddx, wy + ddy)
                        )
                        if near_wire:
                            return (Tool.ROAD, rx, wy)

    # Build proximity masks for zone placement
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and not zone_tiles[nr, nc]:
                    return False
        return True

    # Candidate zone centers: need road AND wire nearby
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Sort by proximity to wire spine row (horizontal layout)
        dists = np.abs(cys - wire_row)
        order = np.argsort(dists)
        step_off = int(obs.step * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 80:
                break

    # Extend roads from existing roads near wire
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs_arr), 1)
        for offset in range(min(len(road_xs_arr), 20)):
            k = (step_k + offset * 7) % len(road_xs_arr)
            rx, ry = int(road_xs_arr[k]), int(road_ys_arr[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx]:
                    if nbr_wire[ny, nx]:
                        return (Tool.ROAD, nx, ny)

    # Services when pop is sufficient
    if obs.city_pop > 150:
        fsx, fsy = 30, 42
        if in_bounds(fsx, fsy) and em[fsy, fsx]:
            return (Tool.FIRESTATION, fsx, fsy)
        psx, psy = 80, 42
        if in_bounds(psx, psy) and em[psy, psx]:
            return (Tool.POLICESTATION, psx, psy)

    if obs.city_pop > 400:
        fsx2, fsy2 = 55, 42
        if in_bounds(fsx2, fsy2) and em[fsy2, fsx2]:
            return (Tool.FIRESTATION, fsx2, fsy2)

    # Extend wire laterally to reach more zones
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 15)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = wx + dx2, wy + dy2
                if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                    return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy: reads tile_map every step.
    Layout: coal plant at (20,50), horizontal wire spine, horizontal road spine,
    zones placed adjacent to road+wire coverage. Expands reactively.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Step 1: Place coal plant if missing ---
    if not np.any(pm):
        return (Tool.COALPOWER, 20, 50)

    # Find plant position
    plant_ys, plant_xs = np.where(pm)
    px = int(np.median(plant_xs))
    py = int(np.median(plant_ys))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if ind_count == 0:
            return Tool.INDUSTRIAL
        if com_count == 0:
            return Tool.COMMERCIAL
        if res_count == 0:
            return Tool.RESIDENTIAL
        t = max(total_zones, 1)
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Layout parameters
    wire_row = py       # horizontal wire spine along plant row
    road_row = py + 2   # road spine 2 below wire
    x_start = px + 3    # start after plant

    # Dynamic horizontal extent based on population
    pop_factor = min(70, obs.city_pop // 5)
    x_end = min(WORLD_W - 3, x_start + 20 + pop_factor)

    # --- Step 2: Wire from plant horizontally (wire spine) ---
    # First check if wire exists at plant row near plant
    wire_at_plant = wm[wire_row, px] if in_bounds(px, wire_row) else False
    if not wire_at_plant and not pm[wire_row, px]:
        if in_bounds(px, wire_row) and (em[wire_row, px] or wm[wire_row, px]):
            return (Tool.WIRE, px, wire_row)

    # Extend wire spine rightward
    wire_cols = set(int(c) for c in np.where(wm[wire_row, :])[0])
    for xc in range(x_start, x_end + 1):
        if xc not in wire_cols:
            if in_bounds(xc, wire_row) and em[wire_row, xc] and not pm[wire_row, xc]:
                return (Tool.WIRE, xc, wire_row)

    # Refresh wire_cols
    wire_cols = set(int(c) for c in np.where(wm[wire_row, :])[0])

    # --- Step 3: Road spine below wire ---
    road_cols = set(int(c) for c in np.where(rm[road_row, :])[0])
    for xc in range(x_start, x_end + 1):
        if xc not in road_cols:
            if in_bounds(xc, road_row) and em[road_row, xc] and not pm[road_row, xc]:
                return (Tool.ROAD, xc, road_row)

    road_cols = set(int(c) for c in np.where(rm[road_row, :])[0])

    # --- Step 4: Place zones near road+wire coverage ---
    # Zone rows above and below road
    zone_rows = [road_row - 3, road_row + 3]

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and not (resm | comm | indm)[nr, nc]:
                    return False
        return True

    # Build proximity masks
    def expand_mask(base, radius=2):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-radius, radius + 1):
            for dx in range(-radius, radius + 1):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                result[r0:r1, c0:c1] |= base[sr0:sr1, sc0:sc1]
        return result

    power_src = wm | pm
    nbr_wire = expand_mask(power_src, 2)
    nbr_road = expand_mask(rm, 2)

    # Place zones every 4 columns in zone rows
    for xc in range(x_start + 1, x_end, 4):
        if xc < 2 or xc >= WORLD_W - 2:
            continue
        for zr in zone_rows:
            if zr < 2 or zr >= WORLD_H - 2:
                continue
            if em[zr, xc] and nbr_road[zr, xc] and nbr_wire[zr, xc]:
                if zone_clear(xc, zr):
                    return (pick_tool(), xc, zr)

    # --- Step 5: Vertical wires to connect zones to wire spine ---
    for xc in range(x_start + 1, x_end, 4):
        if xc not in wire_cols:
            continue
        # Wire downward toward road and zone below
        for ry in range(wire_row + 1, min(road_row + 4, WORLD_H)):
            if not wm[ry, xc] and not rm[ry, xc] and em[ry, xc] and not pm[ry, xc]:
                return (Tool.WIRE, xc, ry)
        # Wire upward toward zone above
        for ry in range(wire_row - 1, max(road_row - 6, 0), -1):
            if not wm[ry, xc] and not rm[ry, xc] and em[ry, xc] and not pm[ry, xc]:
                return (Tool.WIRE, xc, ry)

    # --- Step 6: Second cluster when pop grows ---
    if obs.city_pop >= 150:
        wire_row2 = py - 18
        road_row2 = wire_row2 + 2
        if wire_row2 > 3 and road_row2 > 3:
            # Bridge wire from main spine to cluster 2
            bridge_col = x_start
            for ry in range(wire_row2, wire_row):
                if not wm[ry, bridge_col] and not pm[ry, bridge_col] and em[ry, bridge_col]:
                    return (Tool.WIRE, bridge_col, ry)

            x_end2 = min(WORLD_W - 3, x_start + 20 + min(60, (obs.city_pop - 150) // 5))
            wire_cols2 = set(int(c) for c in np.where(wm[wire_row2, :])[0])
            road_cols2 = set(int(c) for c in np.where(rm[road_row2, :])[0])

            for xc in range(x_start, x_end2 + 1):
                if xc not in wire_cols2 and in_bounds(xc, wire_row2) and em[wire_row2, xc]:
                    return (Tool.WIRE, xc, wire_row2)

            for xc in range(x_start, x_end2 + 1):
                if xc not in road_cols2 and in_bounds(xc, road_row2) and em[road_row2, xc]:
                    return (Tool.ROAD, xc, road_row2)

            zone_rows2 = [wire_row2 - 3, road_row2 + 3]
            for xc in range(x_start + 1, x_end2, 4):
                if xc < 2 or xc >= WORLD_W - 2:
                    continue
                for zr in zone_rows2:
                    if zr < 2 or zr >= WORLD_H - 2:
                        continue
                    if em[zr, xc] and nbr_road[zr, xc] and nbr_wire[zr, xc]:
                        if zone_clear(xc, zr):
                            return (pick_tool(), xc, zr)

            # Vertical wires for cluster 2
            for xc in range(x_start + 1, x_end2, 4):
                if xc not in wire_cols2:
                    continue
                for ry in range(wire_row2 + 1, min(road_row2 + 4, WORLD_H)):
                    if not wm[ry, xc] and not rm[ry, xc] and em[ry, xc] and not pm[ry, xc]:
                        return (Tool.WIRE, xc, ry)
                for ry in range(wire_row2 - 1, max(wire_row2 - 5, 0), -1):
                    if not wm[ry, xc] and not rm[ry, xc] and em[ry, xc] and not pm[ry, xc]:
                        return (Tool.WIRE, xc, ry)

    # --- Step 7: Third cluster below when pop >= 350 ---
    if obs.city_pop >= 350:
        wire_row3 = py + 18
        road_row3 = wire_row3 + 2
        if wire_row3 < WORLD_H - 5 and road_row3 < WORLD_H - 3:
            bridge_col3 = x_start
            for ry in range(wire_row + 1, wire_row3 + 1):
                if not wm[ry, bridge_col3] and not pm[ry, bridge_col3] and em[ry, bridge_col3]:
                    return (Tool.WIRE, bridge_col3, ry)

            x_end3 = min(WORLD_W - 3, x_start + 20 + min(60, (obs.city_pop - 350) // 5))
            wire_cols3 = set(int(c) for c in np.where(wm[wire_row3, :])[0])
            road_cols3 = set(int(c) for c in np.where(rm[road_row3, :])[0])

            for xc in range(x_start, x_end3 + 1):
                if xc not in wire_cols3 and in_bounds(xc, wire_row3) and em[wire_row3, xc]:
                    return (Tool.WIRE, xc, wire_row3)

            for xc in range(x_start, x_end3 + 1):
                if xc not in road_cols3 and in_bounds(xc, road_row3) and em[road_row3, xc]:
                    return (Tool.ROAD, xc, road_row3)

            zone_rows3 = [wire_row3 - 3, road_row3 + 3]
            for xc in range(x_start + 1, x_end3, 4):
