                    if em[zr, xc] and nbr_road[zr, xc] and nbr_wire[zr, xc]:
                        if zone_clear(xc, zr):
                            return (pick_tool(), xc, zr)

    # --- Step 8: Second power plant if city grows large ---
    if obs.city_pop >= 500 or total_zones > 20:
        p2x = min(WORLD_W - 4, x_start + 40)
        p2y = py
        nearby_plant = any(
            in_bounds(p2x + dx, p2y + dy) and pm[p2y + dy, p2x + dx]
            for dy in range(-5, 6) for dx in range(-5, 6)
        )
        if not nearby_plant and in_bounds(p2x, p2y) and em[p2y, p2x]:
            return (Tool.COALPOWER, p2x, p2y)

