    Each step scans current map state and places next tile based on what exists.
    Strategy: single dense cluster centered at (60, 50) with coal plant,
    wire grid, road grid, and RCI zones filling in reactively.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 2 <= x < WORLD_W - 2 and 2 <= y < WORLD_H - 2

    # Central cluster anchor
    CX, CY = 60, 50

    # ---- Phase 0: Place primary coal plant ----
    if not np.any(pm):
        return (Tool.COALPOWER, CX, CY)

    plant_tiles = int(np.sum(pm))

    # ---- Reactive wire extension ----
    # Wire should form a cross/grid pattern emanating from power plant
    # Find frontier: empty cells adjacent to existing power (wire or plant)
    power_map = pm | wm

    # Build wire outward from power in a planned cross pattern
    # Wire spine: horizontal at CY-2, vertical at CX-2
    # Then extend to cover zone areas
    wire_targets = []
    # Horizontal wire spine
    for x in range(CX - 25, CX + 26):
        wire_targets.append((x, CY - 2))
    # Vertical wire spine
    for y in range(CY - 25, CY + 26):
        wire_targets.append((CX - 2, y))
    # Secondary horizontals
    for x in range(CX - 25, CX + 26):
        wire_targets.append((x, CY - 14))
        wire_targets.append((x, CY + 10))
    # Secondary verticals
    for y in range(CY - 25, CY + 26):
        wire_targets.append((CX - 14, y))
        wire_targets.append((CX + 10, y))

    for (wx, wy) in wire_targets:
        if not in_bounds(wx, wy):
            continue
        if bool(wm[wy, wx]) or bool(pm[wy, wx]) or bool(rm[wy, wx]):
            continue
        if not bool(em[wy, wx]):
            continue
        # Only place if adjacent to existing power
        for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = wx + ddx, wy + ddy
            if in_bounds(nx, ny) and bool(power_map[ny, nx]):
                return (Tool.WIRE, wx, wy)

    # ---- Reactive road extension ----
    # Roads form a grid: horizontal at CY, CY+4, CY-4, CY+8, CY-8...
    # Vertical at CX, CX+4, CX-4...
    road_targets = []
    # Horizontal roads every 4 rows
    for dy in range(-20, 21, 4):
        ry = CY + dy
        for x in range(CX - 22, CX + 23):
            road_targets.append((x, ry))
    # Vertical roads every 4 cols
    for dx in range(-20, 21, 4):
        rx = CX + dx
        for y in range(CY - 22, CY + 23):
            road_targets.append((rx, y))

    for (rx, ry) in road_targets:
        if not in_bounds(rx, ry):
            continue
        if bool(rm[ry, rx]) or bool(pm[ry, rx]):
            continue
        if not bool(em[ry, rx]):
            continue
        # Only place if adjacent to existing road or plant
        adj = False
        for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = rx + ddx, ry + ddy
            if in_bounds(nx, ny) and (bool(rm[ny, nx]) or bool(pm[ny, nx])):
                adj = True
                break
        if adj:
            return (Tool.ROAD, rx, ry)

    # ---- Zone placement: reactive to current road+power coverage ----
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_frac = ind_count / total_zones
        c_frac = com_count / total_zones
        if i_frac < 0.20:
            return Tool.INDUSTRIAL
        if c_frac < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Compute neighbor road coverage (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Compute neighbor power coverage (within 4 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_mask = resm | comm | indm

    # Candidate zone positions: empty, near road, near power, away from edges
    cand = em & nbr_road & nbr_power
    cand[0:3, :] = False
    cand[WORLD_H-3:, :] = False
    cand[:, 0:3] = False
    cand[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        # Pick candidate: prefer close to center, use step for variety
        key = int(obs.step * 17 + int(obs.city_pop * 3) + 1) % len(cxs)
        for offset in range(min(len(cxs), 120)):
            k = (key + offset * 13) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            # Check 3x3 area is clear (empty or zone tiles only)
            ok = True
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    ny2, nx2 = zy + dr, zx + dc
                    if not (2 <= nx2 < WORLD_W - 2 and 2 <= ny2 < WORLD_H - 2):
                        ok = False; break
                    if not (bool(em[ny2, nx2]) or bool(zone_mask[ny2, nx2])):
                        ok = False; break
                if not ok:
                    break
            if ok:
                return (pick_tool(), zx, zy)

    # ---- Add second power plant when population grows ----
    if obs.city_pop > 200 and plant_tiles < 9:
        p2x, p2y = CX + 20, CY + 15
        if in_bounds(p2x, p2y) and bool(em[p2y, p2x]):
            return (Tool.COALPOWER, p2x, p2y)

    if obs.city_pop > 500 and plant_tiles < 18:
        p3x, p3y = CX - 20, CY + 15
        if in_bounds(p3x, p3y) and bool(em[p3y, p3x]):
            return (Tool.COALPOWER, p3x, p3y)

    # ---- Services based on current population ----
    if obs.city_pop > 150:
        for fx, fy in [(CX - 15, CY - 15), (CX + 15, CY + 15)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.FIRESTATION, fx, fy)

    if obs.city_pop > 400:
        for fx, fy in [(CX + 15, CY - 15), (CX - 15, CY + 15)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.POLICESTATION, fx, fy)

    # ---- Fallback: extend wire from any wire frontier ----
    wys2, wxs2 = np.where(wm)
    if len(wxs2) > 0:
        k3 = int(obs.step * 7) % len(wxs2)
        for off in range(min(len(wxs2), 20)):
            idx = (k3 + off) % len(wxs2)
            wx2, wy2 = int(wxs2[idx]), int(wys2[idx])
            for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx2 + ddx, wy2 + ddy
                if in_bounds(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    # ---- Fallback: extend road from any road frontier ----
    rys2, rxs2 = np.where(rm)
    if len(rxs2) > 0:
        k2 = int(obs.step * 11) % len(rxs2)
        for off in range(min(len(rxs2), 20)):
            idx = (k2 + off) % len(rxs2)
            rx2, ry2 = int(rxs2[idx]), int(rys2[idx])
            for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = rx2 + ddx, ry2 + ddy
                if in_bounds(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.ROAD, nx, ny)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Scan map each step to find existing infrastructure
    - Extend wire/road/zones based on what's already there
    - Two neighborhoods (left ~x=30, right ~x=80) with power plants
    - Horizontal road/wire spine connecting them
    - Place zones adjacent to existing road+wire coverage
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    all_zone = resm | comm | indm

    # Key layout parameters
    LX, LY = 30, 50   # left neighborhood center
    RX, RY = 85, 50   # right neighborhood center
    MX = (LX + RX) // 2  # ~57

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def is_clear(x, y):
        return in_bounds(x, y) and em[y, x]

    def has_wire(x, y):
        return in_bounds(x, y) and wm[y, x]

    def has_road(x, y):
        return in_bounds(x, y) and rm[y, x]

    def has_plant(x, y):
        return in_bounds(x, y) and pm[y, x]

    def near_wire(x, y, r=3):
        r0, r1 = max(0, y-r), min(WORLD_H, y+r+1)
        c0, c1 = max(0, x-r), min(WORLD_W, x+r+1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def near_road(x, y, r=2):
        r0, r1 = max(0, y-r), min(WORLD_H, y+r+1)
        c0, c1 = max(0, x-r), min(WORLD_W, x+r+1)
        return np.any(rm[r0:r1, c0:c1])

    def zone_clear(cx, cy):
        """Check if 3x3 area around (cx,cy) is placeable"""
        if cx < 1 or cx > WORLD_W-2 or cy < 1 or cy > WORLD_H-2:
            return False
        for dy in [-1, 0, 1]:
            for dx in [-1, 0, 1]:
                x2, y2 = cx+dx, cy+dy
                if not in_bounds(x2, y2):
                    return False
                # Allow empty or existing zone tiles (auto-bulldoze handles it)
                if not em[y2, x2] and not all_zone[y2, x2]:
                    return False
        return True

    def zone_exists_near(cx, cy):
        for dy in [-1, 0, 1]:
            for dx in [-1, 0, 1]:
                if in_bounds(cx+dx, cy+dy) and all_zone[cy+dy, cx+dx]:
                    return True
        return False

    def pick_zone_tool(x, y):
        # Balanced mix: near left=res/com, near right=ind/res, middle=com
        if x < MX - 10:
            # left side: mostly residential, some commercial
            idx = (x // 4 + y // 4) % 4
            return [Tool.RESIDENTIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.RESIDENTIAL][idx]
        elif x > MX + 10:
            # right side: industrial + residential
            idx = (x // 4 + y // 4) % 3
            return [Tool.INDUSTRIAL, Tool.RESIDENTIAL, Tool.INDUSTRIAL][idx]
        else:
            # middle: commercial
            idx = (x // 4 + y // 4) % 3
            return [Tool.COMMERCIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL][idx]

    # Phase tracking via state
    phase = state.get("phase", 0)

    # ---- PHASE 0: Place left power plant ----
    if phase == 0:
        if not np.any(pm[LY-1:LY+2, LX-9:LX-5]):
            return (Tool.COALPOWER, LX - 8, LY)
        state["phase"] = 1
        phase = 1

    # ---- PHASE 1: Place right power plant ----
    if phase == 1:
        if not np.any(pm[RY-1:RY+2, RX+5:RX+11]):
            return (Tool.COALPOWER, RX + 8, RY)
        state["phase"] = 2
        phase = 2

    # ---- REACTIVE INFRASTRUCTURE BUILDING ----
    # From here on: scan map and extend infrastructure reactively

    # Find existing plants
    plant_ys, plant_xs = np.where(pm)
    left_plant_x = int(np.min(plant_xs)) if len(plant_xs) > 0 else LX - 8
    right_plant_x = int(np.max(plant_xs)) if len(plant_xs) > 0 else RX + 8

    # --- Step A: Extend wire from left plant rightward along LY ---
    # Wire spine along row LY from left plant to right plant
    # Find current wire extent on row LY
    wire_on_ly = [x for x in range(WORLD_W) if wm[LY, x] or pm[LY, x]]
    if wire_on_ly:
        max_wire_x = max(wire_on_ly)
        min_wire_x = min(wire_on_ly)
    else:
        # Start wire just right of left plant
        wx = left_plant_x + 3
        if in_bounds(wx, LY) and (em[LY, wx] or wm[LY, wx]):
            return (Tool.WIRE, wx, LY)
        return None

    # Extend wire rightward to right plant
    target_wire_right = right_plant_x - 3
    if max_wire_x < target_wire_right:
        nxt = max_wire_x + 1
        if in_bounds(nxt, LY) and em[LY, nxt] and not pm[LY, nxt]:
            return (Tool.WIRE, nxt, LY)

    # Extend wire leftward from right plant to connect
    wire_on_ry = [x for x in range(WORLD_W) if wm[RY, x] or pm[RY, x]]
    if wire_on_ry:
        min_wire_rx = min(wire_on_ry)
        # Connect right plant wire leftward
        if min_wire_rx > max_wire_x + 2:
            nxt = min_wire_rx - 1
            if in_bounds(nxt, RY) and em[RY, nxt] and not pm[RY, nxt]:
                return (Tool.WIRE, nxt, RY)

    # --- Step B: Road spine along row LY+2 (just below wire spine) ---
    road_row = LY + 2
    road_on_rr = [x for x in range(WORLD_W) if rm[road_row, x]]
    if road_on_rr:
        max_road_x = max(road_on_rr)
        min_road_x = min(road_on_rr)
    else:
        # Start road near left neighborhood
        rx_start = LX - 4
        if in_bounds(rx_start, road_row) and em[road_row, rx_start]:
            return (Tool.ROAD, rx_start, road_row)
        return None

    # Extend road rightward
    target_road_right = RX + 6
    if max_road_x < target_road_right:
        nxt = max_road_x + 1
        if in_bounds(nxt, road_row) and em[road_row, nxt] and not pm[road_row, nxt]:
            return (Tool.ROAD, nxt, road_row)

    # Extend road leftward
    target_road_left = LX - 7
    if min_road_x > target_road_left:
        nxt = min_road_x - 1
        if in_bounds(nxt, road_row) and em[road_row, nxt] and not pm[road_row, nxt]:
            return (Tool.ROAD, nxt, road_row)

    # --- Step C: Vertical wire spines at key columns ---
    # Wire columns at LX, MX, RX going from LY-12 to LY+12
    spine_cols = [LX, MX, RX]
    for sc in spine_cols:
        # Check if wire spine exists at this col
        wire_here = [y for y in range(LY-14, LY+15) if in_bounds(sc, y) and (wm[y, sc] or pm[y, sc])]
        if not wire_here:
            # Place starting wire connected to horizontal wire
            if wm[LY, sc] or pm[LY, sc]:
                # Already has wire at LY, extend up
                if in_bounds(sc, LY-1) and em[LY-1, sc]:
                    return (Tool.WIRE, sc, LY-1)
            else:
                # Need to connect col to spine first
                continue
        else:
            max_wy = max(wire_here)
            min_wy = min(wire_here)
            # Extend upward
            if min_wy > LY - 13:
                ny = min_wy - 1
                if in_bounds(sc, ny) and em[ny, sc] and not rm[ny, sc]:
                    return (Tool.WIRE, sc, ny)
            # Extend downward
            if max_wy < LY + 13:
                ny = max_wy + 1
                if in_bounds(sc, ny) and em[ny, sc] and not rm[ny, sc]:
                    return (Tool.WIRE, sc, ny)

    # --- Step D: Vertical road spines at key columns ---
    road_cols = [LX + 1, MX + 1, RX - 1, LX - 4, RX + 4]
    for rc in road_cols:
        road_here = [y for y in range(LY-14, LY+15) if in_bounds(rc, y) and rm[y, rc]]
        if not road_here:
            # Check if horizontal road spine crosses this col
            if rm[road_row, rc]:
                if in_bounds(rc, road_row-1) and em[road_row-1, rc]:
                    return (Tool.ROAD, rc, road_row-1)
            continue
        else:
            max_ry2 = max(road_here)
            min_ry2 = min(road_here)
            if min_ry2 > LY - 13:
                ny = min_ry2 - 1
                if in_bounds(rc, ny) and em[ny, rc] and not pm[ny, rc]:
                    return (Tool.ROAD, rc, ny)
            if max_ry2 < LY + 13:
                ny = max_ry2 + 1
                if in_bounds(rc, ny) and em[ny, rc] and not pm[ny, rc]:
                    return (Tool.ROAD, rc, ny)

    # --- Step E: Place zones wherever road + wire coverage exists ---
    # Scan candidate zone positions in a grid pattern
    zone_cols_to_try = list(range(LX - 7, RX + 6, 4))
    zone_rows_to_try = list(range(LY - 12, LY + 13, 3))

    for zy in zone_rows_to_try:
        for zx in zone_cols_to_try:
            if zone_exists_near(zx, zy):
                continue
            if not zone_clear(zx, zy):
                continue
            if near_wire(zx, zy, 3) and near_road(zx, zy, 2):
                return (pick_zone_tool(zx, zy), zx, zy)

    # --- Step F: Add more wire coverage for unpowered zones ---
    # Find zones not near wire and try to extend wire toward them
    zone_ys, zone_xs = np.where(all_zone)
    for i in range(len(zone_xs)):
        zx, zy = int(zone_xs[i]), int(zone_ys[i])
        if not near_wire(zx, zy, 2):
            # Try to place wire adjacent
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = zx + dx, zy + dy
                if in_bounds(nx, ny) and em[ny, nx]:
                    # Check if this is adjacent to existing wire
                    for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                        if in_bounds(nx+dx2, ny+dy2) and (wm[ny+dy2, nx+dx2] or pm[ny+dy2, nx+dx2]):
                            return (Tool.WIRE, nx, ny)

    # --- Step G: Second power plant if needed ---
    plant_count = int(np.sum(pm))
    if obs.city_pop > 400 and plant_count < 9:
        # Add another plant
        for px, py in [(MX, LY - 20), (LX - 8, LY + 20), (RX + 8, RY + 20)]:
            if in_bounds(px, py) and em[py, px]:
                if not np.any(pm[py-2:py+3, px-2:px+3]):
                    return (Tool.COALPOWER, px, py)

    # --- Step H: Services for happiness ---
    if obs.city_pop > 300:
        for sx, sy in [(LX, LY - 18), (RX, RY - 18), (MX, LY + 18)]:
            if in_bounds(sx, sy) and em[sy, sx]:
                if not np.any(pm[sy-2:sy+3, sx-2:sx+3]):
                    service_count = state.get("service_count", 0)
                    if service_count % 2 == 0:
                        state["service_count"] = service_count + 1
                        return (Tool.FIRESTATION, sx, sy)
                    else:
                        state["service_count"] = service_count + 1
                        return (Tool.POLICESTATION, sx, sy)

    # --- Step I: Expand zone coverage if city is growing ---
    if obs.city_pop > 200:
        ext_rows = list(range(LY - 18, LY + 19, 3))
        for zy in ext_rows:
            for zx in zone_cols_to_try:
                if zone_exists_near(zx, zy):
                    continue
                if not zone_clear(zx, zy):
                    continue
                if near_wire(zx, zy, 4) and near_road(zx, zy, 3):
                    return (pick_zone_tool(zx, zy), zx, zy)

    # --- Step J: Extend wire to reach further zones ---
    # Wire horizontal at LY along full spine extent
    if np.any(wm[LY, :]):
        wire_row_xs = [x for x in range(WORLD_W) if wm[LY, x] or pm[LY, x]]
        max_wx = max(wire_row_xs)
        min_wx = min(wire_row_xs)
        # Push wire further
        if max_wx < RX + 5:
            nxt = max_wx + 1
            if in_bounds(nxt, LY) and em[LY, nxt]:
                return (Tool.WIRE, nxt, LY)
        if min_wx > LX - 8:
            nxt = min_wx - 1
            if in_bounds(nxt, LY) and em[LY, nxt]:
                return (Tool.WIRE, nxt, LY)

    return None

def act(obs, state):
    """
    Improved policy with:
    - Compact grid layout centered around x=60, y=50
    - Single large coal plant cluster with dense wire grid
    - Grid road network (both horizontal and vertical roads)
    - More balanced zone mix (40% res, 30% com, 30% ind)
    - Zones placed in a tight grid pattern around power+roads
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    all_zones = resm | comm | indm

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def area_free(cx, cy):
        if cx < 1 or cx > WORLD_W - 2 or cy < 1 or cy > WORLD_H - 2:
            return False
        for dy in [-1, 0, 1]:
            for dx in [-1, 0, 1]:
                r, c = cy + dy, cx + dx
                if not (0 <= r < WORLD_H and 0 <= c < WORLD_W):
                    return False
                if not em[r, c]:
                    return False
        return True

    def zone_exists_near(cx, cy, radius=2):
        r0 = max(0, cy - radius)
        r1 = min(WORLD_H, cy + radius + 1)
        c0 = max(0, cx - radius)
        c1 = min(WORLD_W, cx + radius + 1)
        return np.any(all_zones[r0:r1, c0:c1])

    def has_wire_near(cx, cy, radius=5):
        r0 = max(0, cy - radius)
        r1 = min(WORLD_H, cy + radius + 1)
        c0 = max(0, cx - radius)
        c1 = min(WORLD_W, cx + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_near(cx, cy, radius=4):
        r0 = max(0, cy - radius)
        r1 = min(WORLD_H, cy + radius + 1)
        c0 = max(0, cx - radius)
        c1 = min(WORLD_W, cx + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    def pick_zone():
        t = max(total_zones + 1, 1)
        r = res_count / t
        c = com_count / t
        i = ind_count / t
        if r < 0.40:
            return Tool.RESIDENTIAL
        elif c < 0.30:
            return Tool.COMMERCIAL
        elif i < 0.30:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Master plan stored in state
    if 'plan' not in state:
        state['plan'] = 'build'
        state['step_idx'] = 0

    step = obs.step

    # Central layout parameters
    # Plant at (20, 50) - left side
    # Wire grid covers x=20..70, roads on a grid pattern
    # Zones fill the interior

    plant_x, plant_y = 20, 50

    # Check if plant exists
    local_pm = pm[max(0, plant_y-5):min(WORLD_H, plant_y+6),
                  max(0, plant_x-5):min(WORLD_W, plant_x+6)]
    has_plant = np.any(local_pm)

    if not has_plant:
        for dy in range(-2, 3):
            for dx in range(-2, 3):
                npx, npy = plant_x + dx, plant_y + dy
                if area_free(npx, npy):
                    return (Tool.COALPOWER, npx, npy)
        # Fallback: try wider area
        for dy in range(-5, 6):
            for dx in range(-5, 6):
                npx, npy = plant_x + dx, plant_y + dy
                if area_free(npx, npy):
                    return (Tool.COALPOWER, npx, npy)
        return None

    # Find actual plant location
    plant_rows, plant_cols = np.where(pm)
    if len(plant_rows) > 0:
        # Use first plant found
        plant_cy = int(plant_rows[0])
        plant_cx = int(plant_cols[0])
    else:
        plant_cy, plant_cx = plant_y, plant_x

    # Build horizontal wire from plant rightward to x=75
    # Wire along y=plant_cy
    wire_y = plant_cy
    for wx in range(plant_cx + 2, 76):
        if 0 <= wx < WORLD_W:
            if not wm[wire_y, wx] and not pm[wire_y, wx]:
                if em[wire_y, wx]:
                    return (Tool.WIRE, wx, wire_y)
                # If blocked by something else, continue
            # If already wire, good

    # Build vertical wire spine at x=60 from y=30 to y=70
    spine_x = 60
    spine_top = 30
    spine_bot = 70

    for wy in range(spine_top, spine_bot + 1):
        if 0 <= wy < WORLD_H:
            if not wm[wy, spine_x] and not pm[wy, spine_x]:
                if em[wy, spine_x]:
                    return (Tool.WIRE, spine_x, wy)

    # Connect horizontal wire from plant to spine
    # Already done above if wire_y connects to spine_x

    # Build grid roads:
    # Horizontal roads at y=36, y=42, y=48, y=54, y=60, y=66
    # Vertical roads at x=33, x=42, x=51, x=60, x=69
    road_ys = [36, 42, 48, 54, 60, 66]
    road_xs = [33, 42, 51, 60, 69]

    road_x_start = 27
    road_x_end = 75

    road_y_start = 33
    road_y_end = 69

    for ry in road_ys:
        for rx in range(road_x_start, road_x_end + 1):
            if 0 <= rx < WORLD_W and 0 <= ry < WORLD_H:
                if em[ry, rx] and not pm[ry, rx]:
                    return (Tool.ROAD, rx, ry)

    for rx in road_xs:
        for ry in range(road_y_start, road_y_end + 1):
            if 0 <= rx < WORLD_W and 0 <= ry < WORLD_H:
                if em[ry, rx] and not pm[ry, rx]:
                    return (Tool.ROAD, rx, ry)

    # Extend wires from spine to cover zone areas
    # Lateral wires at every 3 rows from spine
    spine_wires = [r for r in range(WORLD_H) if wm[r, spine_x]]
    for wy in spine_wires:
        # Wire leftward
        for wx in range(spine_x - 1, road_x_start - 2, -1):
            if 0 <= wx < WORLD_W:
                if wm[wy, wx] or pm[wy, wx]:
                    break
                if em[wy, wx]:
                    return (Tool.WIRE, wx, wy)
                else:
                    break
        # Wire rightward
        for wx in range(spine_x + 1, road_x_end + 3):
            if 0 <= wx < WORLD_W:
                if wm[wy, wx] or pm[wy, wx]:
                    break
                if em[wy, wx]:
                    return (Tool.WIRE, wx, wy)
                else:
                    break

    # Add more vertical wires connecting horizontal wire to spine
    horiz_wire_row = wire_y
    if 0 <= spine_x < WORLD_W:
        for wy in range(min(horiz_wire_row, spine_top), max(horiz_wire_row, spine_top) + 1):
            if 0 <= wy < WORLD_H:
                if not wm[wy, spine_x] and not pm[wy, spine_x] and em[wy, spine_x]:
                    return (Tool.WIRE, spine_x, wy)

    # Place zones in grid cells between roads
    # Zone centers: between road rows and between road cols
    zone_ys = [39, 45, 51, 57, 63]  # midpoints between road_ys
    zone_xs = [37, 46, 55, 64]      # midpoints between road_xs

    # Also add outer columns
    zone_xs_ext = [30, 37, 46, 55, 64, 72]

    for zy in zone_ys:
        for zx in zone_xs_ext:
            if 1 <= zx <= WORLD_W - 2 and 1 <= zy <= WORLD_H - 2:
                if not zone_exists_near(zx, zy, 2) and area_free(zx, zy):
                    if has_wire_near(zx, zy, 5) and has_road_near(zx, zy, 4):
                        return (pick_zone(), zx, zy)

    # Dynamic scan for any good zone spots
    for zy in range(34, 68, 3):
        for zx in range(28, 74, 3):
            if 1 <= zx <= WORLD_W - 2 and 1 <= zy <= WORLD_H - 2:
                if not zone_exists_near(zx, zy, 2) and area_free(zx, zy):
                    if has_wire_near(zx, zy, 5) and has_road_near(zx, zy, 4):
                        return (pick_zone(), zx, zy)

    # Second coal plant if population growing
    if pop > 200:
        plant_count = int(np.sum(pm)) // 9
        if plant_count < 2:
            for px2, py2 in [(75, 50), (20, 35), (20, 65)]:
                if area_free(px2, py2):
                    return (Tool.COALPOWER, px2, py2)

    # Police station for happiness
    if pop > 200:
        for px, py in [(45, 38), (60, 38), (45, 68), (60, 68)]:
            if area_free(px, py):
                near_tile = tm[max(0, py-5):min(WORLD_H, py+6),
                               max(0, px-5):min(WORLD_W, px+6)]
                if not np.any((near_tile >= 600) & (near_tile <= 750)):
                    return (Tool.POLICESTATION, px, py)

    # Fire station
    if pop > 400:
        for px, py in [(35, 45), (65, 45), (35, 55), (65, 55)]:
            if area_free(px, py):
                return (Tool.FIRESTATION, px, py)

    # Third coal plant for large city
    if pop > 500:
        plant_count = int(np.sum(pm)) // 9
        if plant_count < 3:
            for px3, py3 in [(75, 35), (75, 65), (15, 42), (15, 58)]:
                if area_free(px3, py3):
                    return (Tool.COALPOWER, px3, py3)

    return None

def act(obs, state):
    """
    Variation: Grid-based layout with vertical wire spine and horizontal roads.
    Uses a denser zone pattern with proper R/C/I balance.
    Builds infrastructure first, then zones in a grid pattern.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    has_plant = np.any(pm)

    # ---- Phase 1: Place coal power plant at left side ----
    if not has_plant:
        return (Tool.COALPOWER, 15, 50)

    plant_rows, plant_cols = np.where(pm)
    pcx = int(np.mean(plant_cols))
    pcy = int(np.mean(plant_rows))

    # Vertical wire spine on left, roads horizontal, zones to the right
    wire_col = pcx + 4
    wire_col = max(2, min(WORLD_W - 3, wire_col))

    # Horizontal road rows spaced every 4 rows from center
    center_row = 50
    road_rows = [center_row - 8, center_row - 4, center_row, center_row + 4, center_row + 8]
    road_rows = [max(2, min(WORLD_H - 3, r)) for r in road_rows]

    # Zone columns to the right of wire spine
    zone_cols = [wire_col + 3, wire_col + 6, wire_col + 9, wire_col + 12,
                 wire_col + 15, wire_col + 18, wire_col + 21, wire_col + 24]
    zone_cols = [c for c in zone_cols if 2 <= c <= WORLD_W - 3]

    # Zone rows between roads
    zone_rows = [center_row - 6, center_row - 2, center_row + 2, center_row + 6]
    zone_rows = [r for r in zone_rows if 2 <= r <= WORLD_H - 3]

    row_extent_min = min(road_rows) - 1
    row_extent_max = max(road_rows) + 1

    # ---- Phase 2: Build vertical wire spine ----
    wire_cells = sorted(r for r in range(WORLD_H) if wm[r, wire_col])

    if not wire_cells:
        # Start wire adjacent to plant
        if em[pcy, wire_col]:
            return (Tool.WIRE, wire_col, pcy)
        return (Tool.WIRE, wire_col, pcy)
    else:
        min_wr = wire_cells[0]
        max_wr = wire_cells[-1]
        # Connect to plant if needed
        if min_wr > pcy + 1:
            nr = min_wr - 1
            if 0 <= nr < WORLD_H:
                return (Tool.WIRE, wire_col, nr)
        # Extend downward
        if max_wr < row_extent_max:
            nr = max_wr + 1
            if 0 <= nr < WORLD_H:
                return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if min_wr > row_extent_min:
            nr = min_wr - 1
            if 0 <= nr < WORLD_H:
                return (Tool.WIRE, wire_col, nr)

    wire_cells_set = set(wire_cells)

    # ---- Phase 3: Build horizontal roads ----
    col_extent_min = wire_col
    col_extent_max = max(zone_cols) + 1 if zone_cols else wire_col + 25

    for rr in road_rows:
        if 0 <= rr < WORLD_H:
            # Build road from wire col to right extent
            for rc in range(wire_col, min(col_extent_max + 1, WORLD_W)):
                if not rm[rr, rc] and em[rr, rc]:
                    return (Tool.ROAD, rc, rr)

    # ---- Helper: check if 3x3 area is clear ----
    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    all_zone_m = res_m | com_m | ind_m

    def nearby_zone(zr, zc, radius=2):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(all_zone_m[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=2):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    res_count = max(1, int(np.sum(res_m)) // 9)
    com_count = max(1, int(np.sum(com_m)) // 9)
    ind_count = max(1, int(np.sum(ind_m)) // 9)

    def pick_zone(zr, zc):
        # Top rows: industrial, middle: commercial, bottom: residential
        # Also balance by counts
        total = res_count + com_count + ind_count
        # Prefer balance: 50% res, 25% com, 25% ind
        if ind_count * 4 < total:
            return Tool.INDUSTRIAL
        if com_count * 4 < total:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- Phase 4: Place zones in grid ----
    # Zone rows between road rows
    for zr in zone_rows:
        if not (2 <= zr <= WORLD_H - 3):
            continue
        for zc in zone_cols:
            if not (2 <= zc <= WORLD_W - 3):
                continue
            if not nearby_zone(zr, zc) and zone_area_free(zr, zc):
                if has_road_nearby(zr, zc, 2):
                    return (pick_zone(zr, zc), zc, zr)

    # ---- Phase 5: Also place wire horizontally from spine to reach zones ----
    # Wire from spine to each zone column at road rows for power delivery
    for rr in road_rows:
        if rr in wire_cells_set:
            # Extend wire horizontally at this row to connect
            for wc in range(wire_col + 1, col_extent_max + 1, 6):
                if 0 <= wc < WORLD_W and em[rr, wc]:
                    return (Tool.WIRE, wc, rr)

    # ---- Phase 6: Additional zone rows ----
    extra_zone_rows = [center_row - 10, center_row + 10]
    extra_road_rows = [center_row - 12, center_row + 12]
    extra_road_rows = [max(2, min(WORLD_H - 3, r)) for r in extra_road_rows]
    extra_zone_rows = [max(2, min(WORLD_H - 3, r)) for r in extra_zone_rows]

    if obs.city_pop > 50:
        # Extend wire spine further
        if wire_cells:
            max_wr = max(wire_cells)
            min_wr = min(wire_cells)
            target_max = max(extra_road_rows) + 1
            target_min = min(extra_road_rows) - 1
            if max_wr < target_max:
                return (Tool.WIRE, wire_col, max_wr + 1)
            if min_wr > target_min:
                return (Tool.WIRE, wire_col, min_wr - 1)

        for rr in extra_road_rows:
            if 0 <= rr < WORLD_H:
                for rc in range(wire_col, min(col_extent_max + 1, WORLD_W)):
                    if not rm[rr, rc] and em[rr, rc]:
                        return (Tool.ROAD, rc, rr)

        for zr in extra_zone_rows:
            if not (2 <= zr <= WORLD_H - 3):
                continue
            for zc in zone_cols:
                if not (2 <= zc <= WORLD_W - 3):
                    continue
                if not nearby_zone(zr, zc) and zone_area_free(zr, zc):
                    if has_road_nearby(zr, zc, 2):
                        return (pick_zone(zr, zc), zc, zr)

    # ---- Phase 7: Second power plant ----
    if obs.city_pop > 200 and not state.get("plant2_placed", False):
        px2 = wire_col + 30
        py2 = pcy
        px2 = max(2, min(WORLD_W - 3, px2))
        py2 = max(2, min(WORLD_H - 3, py2))
        clear = all(
            0 <= py2 + dr < WORLD_H and 0 <= px2 + dc < WORLD_W and em[py2 + dr, px2 + dc]
            for dr in [-1, 0, 1] for dc in [-1, 0, 1]
        )
        if clear:
            state["plant2_placed"] = True
            return (Tool.COALPOWER, px2, py2)
        # Try to clear/find spot
        for offset in range(3, 10):
            px2t = wire_col + 30 + offset
            if px2t > WORLD_W - 3:
                break
            if all(
                0 <= py2 + dr < WORLD_H and 0 <= px2t + dc < WORLD_W and em[py2 + dr, px2t + dc]
                for dr in [-1, 0, 1] for dc in [-1, 0, 1]
            ):
                state["plant2_placed"] = True
                return (Tool.COALPOWER, px2t, py2)

    # ---- Phase 8: More zones to the right ----
    if obs.city_pop > 100:
        ext_zone_cols = [wire_col + 27, wire_col + 30, wire_col + 33]
        ext_zone_cols = [c for c in ext_zone_cols if 2 <= c <= WORLD_W - 3]
        ext_road_rows = road_rows + extra_road_rows

        for rr in ext_road_rows:
            if 0 <= rr < WORLD_H:
                for rc in range(wire_col, min(wire_col + 35, WORLD_W)):
                    if not rm[rr, rc] and em[rr, rc]:
                        return (Tool.ROAD, rc, rr)

        all_zone_rows = zone_rows + extra_zone_rows
        for zr in all_zone_rows:
            if not (2 <= zr <= WORLD_H - 3):
                continue
            for zc in ext_zone_cols:
                if not (2 <= zc <= WORLD_W - 3):
                    continue
                if not nearby_zone(zr, zc) and zone_area_free(zr, zc):
                    if has_road_nearby(zr, zc, 2):
                        return (pick_zone(zr, zc), zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder.
    Each step reads tile_map and reacts to current state.
    Strategy: plant -> wire spine -> road columns -> zones (balanced R/C/I)
    Everything is derived from current map observation, not pre-planned.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    all_zone = resm | comm | indm

    cx, cy = WORLD_W // 2, WORLD_H // 2  # 60, 50

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    pop = obs.city_pop

    def pick_tool():
        t = max(total_zones, 1)
        if ind_count / t < 0.22:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zy, zx):
        if zy < 1 or zy > WORLD_H - 2 or zx < 1 or zx > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zy + dr, zx + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone[rr, rc]:
                    return False
        return True

    # --- Phase 1: Place coal power plant ---
    if not np.any(pm):
        return (Tool.COALPOWER, cx - 8, cy)

    # Find plant centroid
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Corridor geometry derived from plant position
    wire_col = plant_cx + 4
    wire_col = max(4, min(WORLD_W - 5, wire_col))
    road_col_r = wire_col + 4
    road_col_l = wire_col - 4
    road_col_r = max(3, min(WORLD_W - 4, road_col_r))
    road_col_l = max(3, min(WORLD_W - 4, road_col_l))

    # Vertical extent scales with population
    if pop < 50:
        half = 8
    elif pop < 150:
        half = 14
    elif pop < 400:
        half = 20
    elif pop < 800:
        half = 28
    else:
        half = 36

    y_min = max(2, cy - half)
    y_max = min(WORLD_H - 3, cy + half)

    # --- Phase 2: Connect plant to wire spine if not connected ---
    # Check if any wire tile is adjacent (within 3) to any plant tile
    plant_connected = False
    for pr, pc in zip(plant_rows.tolist(), plant_cols.tolist()):
        for dr in range(-3, 4):
            for dc in range(-3, 4):
                rr, rc = pr + dr, pc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W and wm[rr, rc]:
                    plant_connected = True

    if not plant_connected:
        # Build wire from plant toward wire_col
        bridge_r = plant_cy
        for bc in range(plant_cx + 1, wire_col + 1):
            if in_bounds(bc, bridge_r):
                if pm[bridge_r, bc]:
                    continue  # don't bulldoze plant
                if wm[bridge_r, bc]:
                    break  # already have wire here
                if em[bridge_r, bc]:
                    return (Tool.WIRE, bc, bridge_r)
        # Also try one row up/down
        for delta in [1, -1, 2, -2]:
            bridge_r2 = plant_cy + delta
            for bc in range(plant_cx + 1, wire_col + 1):
                if in_bounds(bc, bridge_r2):
                    if pm[bridge_r2, bc]:
                        continue
                    if wm[bridge_r2, bc]:
                        break
                    if em[bridge_r2, bc]:
                        return (Tool.WIRE, bc, bridge_r2)

    # --- Phase 3: Extend wire spine vertically ---
    wire_at_col = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])

    if not wire_at_col:
        # Seed wire spine near plant
        for dy in range(0, 10):
            for nr in [plant_cy + dy, plant_cy - dy]:
                if in_bounds(wire_col, nr) and em[nr, wire_col]:
                    return (Tool.WIRE, wire_col, nr)
        return None

    min_wr = min(wire_at_col)
    max_wr = max(wire_at_col)

    # Extend downward
    if max_wr < y_max:
        nr = max_wr + 1
        if in_bounds(wire_col, nr) and em[nr, wire_col] and not pm[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)

    # Extend upward
    if min_wr > y_min:
        nr = min_wr - 1
        if in_bounds(wire_col, nr) and em[nr, wire_col] and not pm[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)

    # --- Phase 4: Build road columns parallel to wire spine ---
    # For each wire row, ensure road columns have road tiles
    for r in wire_at_col:
        if y_min <= r <= y_max:
            if in_bounds(road_col_r, r) and em[r, road_col_r] and not pm[r, road_col_r] and not wm[r, road_col_r]:
                return (Tool.ROAD, road_col_r, r)
            if in_bounds(road_col_l, r) and em[r, road_col_l] and not pm[r, road_col_l] and not wm[r, road_col_l]:
                return (Tool.ROAD, road_col_l, r)

    # --- Phase 5: Horizontal connecting roads every 6 rows ---
    if wire_at_col:
        for wr in wire_at_col:
            if y_min <= wr <= y_max and (wr - y_min) % 6 == 0:
                for rc in range(road_col_l, road_col_r + 1):
                    if in_bounds(rc, wr) and em[wr, rc] and not pm[wr, rc] and not wm[wr, rc]:
                        return (Tool.ROAD, rc, wr)

    # --- Phase 6: Place zones near road AND wire coverage ---
    # Build neighborhood proximity masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, :2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Sort by proximity to wire spine and corridor center
        dists = (np.abs(cxs_arr.astype(int) - wire_col) +
                 np.abs(cys_arr.astype(int) - cy))
        sort_idx = np.argsort(dists)
        for i in range(min(len(cxs_arr), 80)):
            k = int(sort_idx[i])
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_area_ok(zy, zx):
                return (pick_tool(), zx, zy)

    # --- Phase 7: Second power plant when pop grows ---
    plant_tile_count = int(np.sum(pm))
    plant_count = max(1, plant_tile_count // 6)
    if pop > 300 and plant_count < 2:
        p2x = plant_cx + 22
        p2y = plant_cy
        if in_bounds(p2x, p2y) and em[p2y, p2x]:
            nearby = any(
                in_bounds(p2x + dx, p2y + dy) and pm[p2y + dy, p2x + dx]
                for dy in range(-6, 7) for dx in range(-6, 7)
            )
            if not nearby:
                return (Tool.COALPOWER, p2x, p2y)
        # Wire bridge toward second plant
        for wc in range(wire_col + 1, min(wire_col + 25, WORLD_W - 3)):
            if in_bounds(wc, plant_cy) and em[plant_cy, wc] and not pm[plant_cy, wc]:
                if wm[plant_cy, wc]:
                    break
                return (Tool.WIRE, wc, plant_cy)

    # --- Phase 8: Third plant for large city ---
    if pop > 700 and not state.get("plant3_done", False):
        p3x = plant_cx - 22
        p3y = plant_cy
        if in_bounds(p3x, p3y) and em[p3y, p3x]:
            nearby = any(
                in_bounds(p3x + dx, p3y + dy) and pm[p3y + dy, p3x + dx]
                for dy in range(-6, 7) for dx in range(-6, 7)
            )
            if not nearby:
                state["plant3_done"] = True
                return (Tool.COALPOWER, p3x, p3y)
        # Wire leftward
        for wc in range(wire_col - 1, max(wire_col - 26, 2), -1):
            if in_bounds(wc, plant_cy) and em[plant_cy, wc] and not pm[plant_cy, wc]:
                if wm[plant_cy, wc]:
                    break
                return (Tool.WIRE, wc, plant_cy)

    # --- Phase 9: Services ---
    if pop > 300:
        for fx, fy in [(wire_col - 8, cy - 12), (wire_col + 8, cy + 12)]:
            if in_bounds(fx, fy) and em[fy, fx]:
                return (Tool.FIRESTATION, fx, fy)
    if pop > 500:
        for px2, py2 in [(wire_col + 8, cy - 12), (wire_col - 8, cy + 12)]:
            if in_bounds(px2, py2) and em[py2, px2]:
                return (Tool.POLICESTATION, px2, py2)

    # --- Phase 10: Extend wire to reach more zones ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        # Find wire tile closest to corridor center
        step_k = int(obs.step * 7) % len(wire_xs_arr)
        wx_s = int(wire_xs_arr[step_k])
        wy_s = int(wire_ys_arr[step_k])
        for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx2, ny2 = wx_s + dx2, wy_s + dy2
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                if y_min <= ny2 <= y_max:
                    return (Tool.WIRE, nx2, ny2)

    # --- Phase 11: Extend roads near wire ---
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = int(obs.step * 11) % len(road_xs_arr)
        rx_s = int(road_xs_arr[step_k])
        ry_s = int(road_ys_arr[step_k])
        for dy2, dx2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx2, ny2 = rx_s + dx2, ry_s + dy2
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2] and not wm[ny2, nx2]:
                if nbr_wire[ny2, nx2] and y_min <= ny2 <= y_max:
                    return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Read current map state each step
    - Extend power/road infrastructure from what already exists
    - Place zones adjacent to existing infrastructure
    - Adapt to actual map state rather than precomputed plan
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    all_zone_mask = resm | comm | indm

    # Count zones for ratio targeting
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        if res_count / t < 0.40:
            return Tool.RESIDENTIAL
        if com_count / t < 0.35:
            return Tool.COMMERCIAL
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zr, zc):
        """Check that a 3x3 zone footprint is placeable (empty or zone tiles only)"""
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    # Step 1: Place power plant if none exists
    if not np.any(pm):
        return (Tool.COALPOWER, 30, 50)

    # Find power plant center
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Step 2: Extend wire from existing wire/plant frontier
    # Find all wire tiles and plant tiles as power sources
    power_mask = wm | pm

    # Find frontier: empty cells adjacent to existing power
    power_frontier = []
    power_ys, power_xs = np.where(power_mask)

    # Build wire eastward from plant if no wire exists yet
    if not np.any(wm):
        # Place first wire adjacent to plant
        wx = plant_cx + 2
        wy = plant_cy
        if 0 <= wx < WORLD_W and em[wy, wx]:
            return (Tool.WIRE, wx, wy)
        # Try other directions
        for dx, dy in [(2,0),(-2,0),(0,2),(0,-2),(3,0)]:
            wx, wy = plant_cx + dx, plant_cy + dy
            if 0 <= wx < WORLD_W and 0 <= wy < WORLD_H and em[wy, wx]:
                return (Tool.WIRE, wx, wy)

    # Current wire extent
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        max_wire_x = int(np.max(wire_xs))
        min_wire_x = int(np.min(wire_xs))
        max_wire_y = int(np.max(wire_ys))
        min_wire_y = int(np.min(wire_ys))
    else:
        max_wire_x = plant_cx
        min_wire_x = plant_cx
        max_wire_y = plant_cy
        min_wire_y = plant_cy

    # Main wire spine row
    spine_row = plant_cy

    # How far should wire extend based on pop?
    pop = obs.city_pop
    if pop < 50:
        target_wire_x = plant_cx + 20
    elif pop < 200:
        target_wire_x = plant_cx + 35
    elif pop < 500:
        target_wire_x = plant_cx + 50
    else:
        target_wire_x = plant_cx + 65
    target_wire_x = min(target_wire_x, WORLD_W - 5)

    # Step 3: Extend main horizontal wire spine
    # Find rightmost wire on the spine row
    spine_wire_xs = [c for c in range(WORLD_W) if wm[spine_row, c]]
    if not spine_wire_xs:
        # Wire hasn't reached spine row yet - build from plant
        wx = plant_cx + 2
        if 0 <= wx < WORLD_W and (em[spine_row, wx] or wm[spine_row, wx]):
            if em[spine_row, wx]:
                return (Tool.WIRE, wx, spine_row)
    else:
        max_spine_wire_x = max(spine_wire_xs)
        if max_spine_wire_x < target_wire_x:
            nx = max_spine_wire_x + 1
            if nx < WORLD_W and em[spine_row, nx]:
                return (Tool.WIRE, nx, spine_row)
            elif nx < WORLD_W and not pm[spine_row, nx]:
                # Try to push past obstacles
                for skip in range(1, 4):
                    if nx + skip < WORLD_W and em[spine_row, nx + skip]:
                        return (Tool.WIRE, nx + skip, spine_row)

    # Step 4: Build road parallel to wire spine (one row below)
    road_row = spine_row + 2
    road_row = min(road_row, WORLD_H - 3)

    # Road should extend to match wire coverage
    spine_wire_xs_set = set(spine_wire_xs) if spine_wire_xs else set()
    road_on_road_row = [c for c in range(WORLD_W) if rm[road_row, c]]
    road_set = set(road_on_road_row)

    # Build road under each wire column on spine
    for wc in sorted(spine_wire_xs_set):
        if wc not in road_set and 0 <= road_row < WORLD_H:
            if em[road_row, wc]:
                return (Tool.ROAD, wc, road_row)

    # Step 5: Place zones - look for spots adjacent to both wire and road
    # Zone rows: above spine (spine_row - 3) and below road (road_row + 3)
    zone_rows_above = [spine_row - 3, spine_row - 6]
    zone_rows_below = [road_row + 3, road_row + 6]

    # For each wire column with road coverage, try to place zones
    candidates = sorted(spine_wire_xs_set)

    for zc in candidates[::3]:  # every 3rd column to space zones
        # Check road nearby
        road_near = any(abs(zc - rc) <= 3 for rc in road_on_road_row)
        if not road_near:
            continue

        # Try above spine
        for zr in zone_rows_above:
            zr = max(1, min(WORLD_H - 2, zr))
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                # Need wire nearby for power
                r0 = max(0, zr - 3); r1 = min(WORLD_H, zr + 4)
                c0 = max(0, zc - 3); c1 = min(WORLD_W, zc + 4)
                if np.any(power_mask[r0:r1, c0:c1]):
                    return (pick_tool(), zc, zr)

        # Try below road
        for zr in zone_rows_below:
            zr = max(1, min(WORLD_H - 2, zr))
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                r0 = max(0, zr - 3); r1 = min(WORLD_H, zr + 4)
                c0 = max(0, zc - 3); c1 = min(WORLD_W, zc + 4)
                if np.any(power_mask[r0:r1, c0:c1]):
                    # Need road too
                    rr0 = max(0, zr - 4); rr1 = min(WORLD_H, zr + 5)
                    if np.any(rm[rr0:rr1, c0:c1]):
                        return (pick_tool(), zc, zr)

    # Step 6: Extend wire vertically toward zones that need power
    # Check if zones exist without power nearby - wire toward them
    zone_ys, zone_xs = np.where(all_zone_mask)
    for i in range(len(zone_xs)):
        zy, zx = int(zone_ys[i]), int(zone_xs[i])
        r0 = max(0, zy - 2); r1 = min(WORLD_H, zy + 3)
        c0 = max(0, zx - 2); c1 = min(WORLD_W, zx + 3)
        if not np.any(power_mask[r0:r1, c0:c1]):
            # Find nearest wire and extend toward zone
            if len(wire_xs) > 0:
                dists = np.sqrt((wire_ys - zy)**2 + (wire_xs - zx)**2)
                nearest_idx = int(np.argmin(dists))
                wy_near, wx_near = int(wire_ys[nearest_idx]), int(wire_xs[nearest_idx])
                # Step one tile toward zone
                dy = np.sign(zy - wy_near)
                dx = np.sign(zx - wx_near)
                nwy, nwx = wy_near + dy, wx_near + dx
                if 0 <= nwy < WORLD_H and 0 <= nwx < WORLD_W and em[nwy, nwx]:
                    return (Tool.WIRE, nwx, nwy)

    # Step 7: Extend road toward zones that lack road access
    for i in range(len(zone_xs)):
        zy, zx = int(zone_ys[i]), int(zone_xs[i])
        r0 = max(0, zy - 3); r1 = min(WORLD_H, zy + 4)
        c0 = max(0, zx - 3); c1 = min(WORLD_W, zx + 4)
        if not np.any(rm[r0:r1, c0:c1]):
            # Extend road toward this zone
            road_ys, road_xs = np.where(rm)
            if len(road_xs) > 0:
                dists = np.sqrt((road_ys - zy)**2 + (road_xs - zx)**2)
                nearest_idx = int(np.argmin(dists))
                ry_near, rx_near = int(road_ys[nearest_idx]), int(road_xs[nearest_idx])
                dy = np.sign(zy - ry_near)
                dx = np.sign(zx - rx_near)
                nry, nrx = ry_near + dy, rx_near + dx
                if 0 <= nry < WORLD_H and 0 <= nrx < WORLD_W and em[nry, nrx]:
                    return (Tool.ROAD, nrx, nry)

    # Step 8: Second power plant when needed
    powered = obs.powered_zones
    num_plants = int(np.sum(pm)) // 9  # approx 3x3 = 9 tiles per plant
    if total_zones > 10 and powered < total_zones * 0.5 and num_plants < 2:
        # Place second plant near middle of wire spine
        if spine_wire_xs:
            mid_x = int(np.median(spine_wire_xs))
            px2 = mid_x
            py2 = spine_row - 8
            py2 = max(2, min(WORLD_H - 3, py2))
            px2 = max(2, min(WORLD_W - 3, px2))
            # Check area clear
            area_ok = True
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    rr, rc = py2 + dr, px2 + dc
                    if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                        if not (em[rr, rc] or pm[rr, rc]):
                            area_ok = False
            if area_ok:
                return (Tool.COALPOWER, px2, py2)

    # Step 9: Fill gaps - place road segments connecting existing road segments
    for c in sorted(spine_wire_xs_set):
        # If there's road at c-1 and c+1 but not c, fill it
        if (0 <= road_row < WORLD_H and 0 < c < WORLD_W - 1 and
                not rm[road_row, c] and em[road_row, c] and
                (rm[road_row, c-1] or rm[road_row, c+1])):
            return (Tool.ROAD, c, road_row)

    # Step 10: Try a vertical road toward bottom zones
    for wc in sorted(spine_wire_xs_set)[:10]:
        for rr in range(road_row + 1, min(road_row + 5, WORLD_H)):
            if not rm[rr, wc] and em[rr, wc]:
                return (Tool.ROAD, wc, rr)
            elif rm[rr, wc]:
                break

    return None

def act(obs, state):
    """
    Grid-based city builder:
    - Places a coal plant, then builds a horizontal road grid
    - Wires run along roads to power zones
    - Places zones in a grid pattern with balanced RCI mix
    - Two neighborhoods: one left, one right of center
    - Services placed reactively
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Initialize build plan in state
    if 'phase' not in state:
        state['phase'] = 0
        state['build_queue'] = []

    # --- Build queue execution ---
    if state['build_queue']:
        action = state['build_queue'].pop(0)
        return action

    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    res_count = int(np.sum(resm)) // 9  # approximate zone count
    com_count = int(np.sum(comm)) // 9
    ind_count = int(np.sum(indm)) // 9
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        # Target mix: 50% R, 30% C, 20% I
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Place first coal plant at center-left ---
    if not np.any(pm):
        return (Tool.COALPOWER, 40, 50)

    # Find plant location
    plant_ys, plant_xs = np.where(pm)
    px = int(np.median(plant_xs))
    py = int(np.median(plant_ys))

    # === GRID LAYOUT ===
    # Two neighborhoods flanking the plant
    # Plant at ~(40, 50)
    # Left neighborhood: x=20..38, roads at y=44,48,52,56
    # Right neighborhood: x=42..70, roads at y=44,48,52,56
    # Horizontal wire runs from plant along y=50 to both sides
    # Vertical roads connect rows

    # Wire horizontal spine at py (plant row)
    # Roads at py-6, py-2, py+2, py+6 (horizontal)
    # Vertical road at px-2 and px+2 connecting rows

    road_rows = [py - 8, py - 4, py, py + 4, py + 8]
    road_rows = [r for r in road_rows if 2 <= r <= WORLD_H - 3]

    # Left cluster: x from px-18 to px-3, wire col at px-2
    # Right cluster: x from px+3 to px+22, wire col at px+2
    left_wire_col = px - 2
    right_wire_col = px + 2

    # Horizontal wire at plant row connecting left and right
    # Wire from plant outward
    wire_row = py

    # Build horizontal wire spine
    # From plant leftward to px-20
    left_wire_end = max(3, px - 20)
    right_wire_end = min(WORLD_W - 3, px + 25)

    for wx in range(left_wire_end, right_wire_end + 1):
        if in_bounds(wx, wire_row) and em[wire_row, wx] and not pm[wire_row, wx]:
            # Check if wire already there
            if not wm[wire_row, wx]:
                return (Tool.WIRE, wx, wire_row)

    # Build horizontal roads at road_rows
    road_left = max(3, px - 20)
    road_right = min(WORLD_W - 3, px + 25)

    for rr in road_rows:
        for rx in range(road_left, road_right + 1):
            if in_bounds(rx, rr) and em[rr, rx] and not pm[rr, rx]:
                return (Tool.ROAD, rx, rr)

    # Build vertical roads connecting the rows
    # Vertical roads at several x positions
    v_road_cols = [px - 18, px - 12, px - 6, px + 6, px + 12, px + 18, px + 24]
    v_road_cols = [c for c in v_road_cols if 2 <= c <= WORLD_W - 3]

    rr_min = min(road_rows)
    rr_max = max(road_rows)
    for vc in v_road_cols:
        for ry in range(rr_min, rr_max + 1):
            if in_bounds(vc, ry) and em[ry, vc] and not pm[ry, vc]:
                return (Tool.ROAD, vc, ry)

    # Build vertical wires at left_wire_col and right_wire_col
    for vc in [left_wire_col, right_wire_col]:
        for ry in range(rr_min, rr_max + 1):
            if in_bounds(vc, ry) and em[ry, vc] and not pm[ry, vc]:
                if not wm[ry, vc]:
                    return (Tool.WIRE, vc, ry)

    # Also wire along each road row near wire cols
    for rr in road_rows:
        for wx in range(left_wire_end, right_wire_end + 1):
            if in_bounds(wx, rr) and (em[rr, wx]) and not pm[rr, wx]:
                if not wm[rr, wx] and not rm[rr, wx]:
                    return (Tool.WIRE, wx, rr)

    # --- Zone placement in grid ---
    # Compute proximity masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and not zone_tiles[nr, nc]:
                    return False
        return True

    # Grid zone centers: between road rows, between vertical road cols
    # Zone centers in bands between roads
    zone_centers = []
    # Between road rows (use midpoints)
    row_bands = []
    sorted_rr = sorted(road_rows)
    for i in range(len(sorted_rr) - 1):
        mid = (sorted_rr[i] + sorted_rr[i+1]) // 2
        row_bands.append(mid)
    # Also above first and below last
    row_bands.append(sorted_rr[0] - 3)
    row_bands.append(sorted_rr[-1] + 3)

    # X positions for zone centers: columns between vertical roads
    x_positions = list(range(road_left + 3, road_right - 2, 4))

    for zy in row_bands:
        for zx in x_positions:
            if in_bounds(zx, zy) and 2 <= zx <= WORLD_W - 3 and 2 <= zy <= WORLD_H - 3:
                zone_centers.append((zx, zy))

    # Candidate zone centers that have road and wire nearby
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    # Try grid-defined zone centers first
    for zx, zy in zone_centers:
        if (in_bounds(zx, zy) and cand_mask[zy, zx] and zone_clear(zx, zy)):
            return (pick_tool(), zx, zy)

    # Fall back to any candidate
    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Sort by proximity to plant
        dists = np.abs(cxs - px) + np.abs(cys - py)
        order = np.argsort(dists)
        step_off = int(obs.step * 3) % max(len(order), 1)
        for i in range(min(len(order), 60)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # --- Second coal plant when city grows ---
    if total_zones > 15 or obs.city_pop > 400:
        p2x = px + 30
        p2y = py - 10
        if in_bounds(p2x, p2y):
            nearby = any(
                in_bounds(p2x + dx, p2y + dy) and pm[p2y + dy, p2x + dx]
                for dy in range(-5, 6) for dx in range(-5, 6)
            )
            if not nearby and em[p2y, p2x]:
                return (Tool.COALPOWER, p2x, p2y)
            # Wire bridge to second plant
            for wc in range(right_wire_end + 1, p2x):
                if in_bounds(wc, py) and em[py, wc] and not wm[py, wc]:
                    return (Tool.WIRE, wc, py)

    # --- Services ---
    if obs.city_pop > 100:
        fsx, fsy = px - 8, py - 12
        if in_bounds(fsx, fsy) and em[fsy, fsx]:
            return (Tool.FIRESTATION, fsx, fsy)
        psx, psy = px + 8, py - 12
        if in_bounds(psx, psy) and em[psy, psx]:
            return (Tool.POLICESTATION, psx, psy)

    if obs.city_pop > 300:
        # Stadium
        stx, sty = px - 15, py + 15
        if in_bounds(stx, sty) and em[sty, stx]:
            return (Tool.STADIUM, stx, sty)

    # --- Extend wire frontier to reach isolated zones ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 10)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = wx + dx2, wy + dy2
                if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                    return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Variation: Vertical spine layout with power plant at top-center,
    vertical wire running down, roads on left/right of wire,
    zones placed left and right of roads.
    Multiple corridors expanding outward from center.
    Better zone mix and more aggressive expansion.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        # Target mix: 50% res, 25% com, 25% ind
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Phase 1: Place coal power plant near top-center
    if not np.any(pm):
        return (Tool.COALPOWER, cx, 8)

    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Vertical layout: wire spine runs down from plant
    wire_col = plant_cx          # vertical wire spine column
    road_col_left = wire_col - 3  # road left of wire
    road_col_right = wire_col + 3  # road right of wire
    zone_col_left = road_col_left - 3   # zones left of road
    zone_col_right = road_col_right + 3  # zones right of road

    # Clamp columns
    wire_col = max(6, min(WORLD_W - 7, wire_col))
    road_col_left = max(3, wire_col - 3)
    road_col_right = min(WORLD_W - 4, wire_col + 3)
    zone_col_left = max(2, road_col_left - 3)
    zone_col_right = min(WORLD_W - 3, road_col_right + 3)

    # Vertical extent based on population
    if obs.city_pop < 100:
        extent = 15
    elif obs.city_pop < 300:
        extent = 25
    elif obs.city_pop < 600:
        extent = 40
    else:
        extent = 60

    wire_start = plant_cy + 3
    target_min = max(2, wire_start)
    target_max = min(WORLD_H - 3, wire_start + extent)

    wire_rows = sorted(r for r in range(WORLD_H) if wm[r, wire_col])
    road_rows_left = set(r for r in range(WORLD_H) if rm[r, road_col_left])
    road_rows_right = set(r for r in range(WORLD_H) if rm[r, road_col_right])

    # Phase 2: Start wire adjacent to plant (going down)
    if not wire_rows:
        for dr in range(0, 6):
            nr = plant_cy + dr + 1
            if 0 <= nr < WORLD_H and 0 <= wire_col < WORLD_W:
                if em[nr, wire_col] or wm[nr, wire_col]:
                    return (Tool.WIRE, wire_col, nr)
        return None

    min_wr = min(wire_rows)
    max_wr = max(wire_rows)

    # Phase 3: Extend wire downward
    if max_wr < target_max:
        nr = max_wr + 1
        if nr < WORLD_H and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Phase 4: Extend wire upward (toward plant)
    if min_wr > target_min:
        nr = min_wr - 1
        if nr >= 0 and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Phase 5: Build roads left and right along wire
    for wr in wire_rows:
        if wr not in road_rows_left and 0 <= road_col_left < WORLD_W:
            if em[wr, road_col_left]:
                return (Tool.ROAD, road_col_left, wr)
        if wr not in road_rows_right and 0 <= road_col_right < WORLD_W:
            if em[wr, road_col_right]:
                return (Tool.ROAD, road_col_right, wr)

    # Helper: check if 3x3 zone area is clear
    all_zone_mask = resm | comm | indm

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    # Phase 6: Place zones left and right of roads
    zone_rows_list = list(range(target_min + 1, target_max, 3))

    for zr in zone_rows_list:
        wire_near = any(abs(zr - wr) <= 2 for wr in wire_rows)
        road_near_left = any(abs(zr - rr) <= 2 for rr in road_rows_left)
        road_near_right = any(abs(zr - rr) <= 2 for rr in road_rows_right)

        if not wire_near:
            continue

        if road_near_left:
            zc = zone_col_left
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                return (pick_tool(), zc, zr)

        if road_near_right:
            zc = zone_col_right
            if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                return (pick_tool(), zc, zr)

    # Phase 7: Horizontal roads connecting wire col to road cols
    for wr in wire_rows:
        if wr in road_rows_left:
            for rc in range(min(wire_col, road_col_left), max(wire_col, road_col_left) + 1):
                if rc != wire_col and 0 <= rc < WORLD_W:
                    if em[wr, rc] and not pm[wr, rc]:
                        return (Tool.ROAD, rc, wr)
        if wr in road_rows_right:
            for rc in range(min(wire_col, road_col_right), max(wire_col, road_col_right) + 1):
                if rc != wire_col and 0 <= rc < WORLD_W:
                    if em[wr, rc] and not pm[wr, rc]:
                        return (Tool.ROAD, rc, wr)

    # Phase 8: Second power plant when needed
    if obs.city_pop > 400 and int(np.sum(pm)) < 9:
        px2, py2 = plant_cx + 20, plant_cy
        if 2 <= py2 <= WORLD_H - 3 and 2 <= px2 <= WORLD_W - 3:
            area_ok = all(
                em[py2 + dr, px2 + dc]
                for dr in [-1, 0, 1] for dc in [-1, 0, 1]
                if 0 <= py2 + dr < WORLD_H and 0 <= px2 + dc < WORLD_W
            )
            if area_ok:
                return (Tool.COALPOWER, px2, py2)

    # Phase 9: Second vertical corridor to the right (for larger pop)
    if obs.city_pop > 200:
        wire_col2 = wire_col + 12
        wire_col2 = max(6, min(WORLD_W - 7, wire_col2))
        road_col2_left = max(3, wire_col2 - 3)
        road_col2_right = min(WORLD_W - 4, wire_col2 + 3)
        zone_col2_left = max(2, road_col2_left - 3)
        zone_col2_right = min(WORLD_W - 3, road_col2_right + 3)

        wire_rows2 = sorted(r for r in range(WORLD_H) if wm[r, wire_col2])
        road_rows2_left = set(r for r in range(WORLD_H) if rm[r, road_col2_left])
        road_rows2_right = set(r for r in range(WORLD_H) if rm[r, road_col2_right])

        if not wire_rows2:
            # Horizontal wire connection from main spine
            for wc in range(min(wire_col, wire_col2), max(wire_col, wire_col2) + 1):
                if 0 <= wc < WORLD_W and (em[plant_cy + 3, wc] or wm[plant_cy + 3, wc]):
                    if not pm[plant_cy + 3, wc]:
                        return (Tool.WIRE, wc, plant_cy + 3)
        else:
            max_wr2 = max(wire_rows2)
            if max_wr2 < target_max:
                nr = max_wr2 + 1
                if nr < WORLD_H and em[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)

            for wr in wire_rows2:
                if wr not in road_rows2_left and 0 <= road_col2_left < WORLD_W:
                    if em[wr, road_col2_left]:
                        return (Tool.ROAD, road_col2_left, wr)
                if wr not in road_rows2_right and 0 <= road_col2_right < WORLD_W:
                    if em[wr, road_col2_right]:
                        return (Tool.ROAD, road_col2_right, wr)

            for zr in zone_rows_list:
                wire_near2 = any(abs(zr - wr) <= 2 for wr in wire_rows2)
                road_near2l = any(abs(zr - rr) <= 2 for rr in road_rows2_left)
                road_near2r = any(abs(zr - rr) <= 2 for rr in road_rows2_right)
                if not wire_near2:
                    continue
                if road_near2l:
                    if not zone_already_there(zr, zone_col2_left) and zone_area_ok(zr, zone_col2_left):
                        return (pick_tool(), zone_col2_left, zr)
                if road_near2r:
                    if not zone_already_there(zr, zone_col2_right) and zone_area_ok(zr, zone_col2_right):
                        return (pick_tool(), zone_col2_right, zr)

    # Phase 10: Third vertical corridor to the left
    if obs.city_pop > 400:
        wire_col3 = wire_col - 12
        wire_col3 = max(6, min(WORLD_W - 7, wire_col3))
        road_col3_left = max(3, wire_col3 - 3)
        road_col3_right = min(WORLD_W - 4, wire_col3 + 3)
        zone_col3_left = max(2, road_col3_left - 3)
        zone_col3_right = min(WORLD_W - 3, road_col3_right + 3)

        wire_rows3 = sorted(r for r in range(WORLD_H) if wm[r, wire_col3])
        road_rows3_left = set(r for r in range(WORLD_H) if rm[r, road_col3_left])
        road_rows3_right = set(r for r in range(WORLD_H) if rm[r, road_col3_right])

        if not wire_rows3:
            for wc in range(min(wire_col3, wire_col), max(wire_col3, wire_col) + 1):
                if 0 <= wc < WORLD_W and (em[plant_cy + 3, wc] or wm[plant_cy + 3, wc]):
                    if not pm[plant_cy + 3, wc]:
                        return (Tool.WIRE, wc, plant_cy + 3)
        else:
            max_wr3 = max(wire_rows3)
            if max_wr3 < target_max:
                nr = max_wr3 + 1
                if nr < WORLD_H and em[nr, wire_col3]:
                    return (Tool.WIRE, wire_col3, nr)

            for wr in wire_rows3:
                if wr not in road_rows3_left and 0 <= road_col3_left < WORLD_W:
                    if em[wr, road_col3_left]:
                        return (Tool.ROAD, road_col3_left, wr)
                if wr not in road_rows3_right and 0 <= road_col3_right < WORLD_W:
                    if em[wr, road_col3_right]:
                        return (Tool.ROAD, road_col3_right, wr)

            for zr in zone_rows_list:
                wire_near3 = any(abs(zr - wr) <= 2 for wr in wire_rows3)
                road_near3l = any(abs(zr - rr) <= 2 for rr in road_rows3_left)
                road_near3r = any(abs(zr - rr) <= 2 for rr in road_rows3_right)
                if not wire_near3:
                    continue
                if road_near3l:
                    if not zone_already_there(zr, zone_col3_left) and zone_area_ok(zr, zone_col3_left):
                        return (pick_tool(), zone_col3_left, zr)
                if road_near3r:
                    if not zone_already_there(zr, zone_col3_right) and zone_area_ok(zr, zone_col3_right):
                        return (pick_tool(), zone_col3_right, zr)

    # Phase 11: Gap fill roads
    for wr in wire_rows:
        if wr not in road_rows_left and 0 <= road_col_left < WORLD_W:
            if em[wr, road_col_left]:
                return (Tool.ROAD, road_col_left, wr)
        if wr not in road_rows_right and 0 <= road_col_right < WORLD_W:
            if em[wr, road_col_right]:
                return (Tool.ROAD, road_col_right, wr)

    return None

def act(obs, state):
    """
    Hybrid policy combining best ideas from both parents.
    - Compact cluster around center
    - Vertical wire spine + horizontal road lanes
    - Multiple power plants as city grows
    - Reactive zone placement near road+wire
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Phase 1: Place first coal plant ---
    if not np.any(pm):
        return (Tool.COALPOWER, 55, 50)

    plant_ys, plant_xs = np.where(pm)
    px = int(np.median(plant_xs))
    py = int(np.median(plant_ys))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Wire spine column just to the right of plant
    wire_col = px + 2
    # Vertical extent based on population
    pop_factor = min(40, obs.city_pop // 10)
    tmin = max(2, py - 18 - pop_factor)
    tmax = min(WORLD_H - 3, py + 18 + pop_factor)

    wire_in_col = [r for r in range(WORLD_H) if 0 <= wire_col < WORLD_W and wm[r, wire_col]]

    # --- Phase 2: Build vertical wire spine ---
    if not wire_in_col:
        for dy in range(-2, 3):
            ny = py + dy
            if in_bounds(wire_col, ny) and (em[ny, wire_col] or wm[ny, wire_col]) and not pm[ny, wire_col]:
                return (Tool.WIRE, wire_col, ny)
    else:
        min_wr = min(wire_in_col)
        max_wr = max(wire_in_col)
        if max_wr < tmax:
            nr = max_wr + 1
            if in_bounds(wire_col, nr) and (em[nr, wire_col] or wm[nr, wire_col]) and not pm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)
        if min_wr > tmin:
            nr = min_wr - 1
            if in_bounds(wire_col, nr) and (em[nr, wire_col] or wm[nr, wire_col]) and not pm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # --- Phase 3: Build horizontal road lanes flanking wire spine ---
    # Road lanes at wire_col +1 and wire_col -1 (parallel to wire spine)
    road_col_r = wire_col + 1
    road_col_l = wire_col - 1

    for wr in wire_in_col:
        if in_bounds(road_col_r, wr) and em[wr, road_col_r]:
            return (Tool.ROAD, road_col_r, wr)
        if in_bounds(road_col_l, wr) and em[wr, road_col_l]:
            return (Tool.ROAD, road_col_l, wr)

    # Also build horizontal roads at fixed intervals for cross-street access
    if wire_in_col:
        cross_rows = list(range(tmin, tmax + 1, 4))
        for cr in cross_rows:
            if not in_bounds(wire_col, cr):
                continue
            # Extend horizontal road left and right from wire spine
            for side in [1, -1]:
                for dist in range(1, 12):
                    cx = wire_col + side * dist
                    if not in_bounds(cx, cr):
                        break
                    if pm[cr, cx]:
                        break
                    if em[cr, cx]:
                        return (Tool.ROAD, cx, cr)
                    elif not rm[cr, cx]:
                        break

    # --- Build proximity masks ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and not zone_tiles[nr, nc]:
                    return False
        return True

    # --- Phase 4: Place zones near road+wire ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prefer locations closer to wire spine
        dists = np.abs(cxs - wire_col)
        order = np.argsort(dists)
        step_off = int(obs.step * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 100:
                break

    # --- Phase 5: Extend roads near wire to fill gaps ---
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs_arr), 1)
        for offset in range(min(len(road_xs_arr), 20)):
            k = (step_k + offset * 7) % len(road_xs_arr)
            rx, ry = int(road_xs_arr[k]), int(road_ys_arr[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx] and nbr_wire[ny, nx]:
                    return (Tool.ROAD, nx, ny)

    # --- Phase 6: Second power plant when city grows ---
    if total_zones > 8 or obs.city_pop > 200:
        p2x = px + 20
        p2y = py
        if in_bounds(p2x, p2y):
            nearby_plant = any(
                in_bounds(p2x + dx, p2y + dy) and pm[p2y + dy, p2x + dx]
                for dy in range(-6, 7) for dx in range(-6, 7)
            )
            if not nearby_plant and em[p2y, p2x]:
                return (Tool.COALPOWER, p2x, p2y)
            else:
                # Wire horizontal bridge from spine to second plant
                for wc in range(wire_col + 2, p2x):
                    if in_bounds(wc, py) and (em[py, wc] or wm[py, wc]) and not pm[py, wc]:
                        if not wm[py, wc]:
                            return (Tool.WIRE, wc, py)
                        # Continue checking

    # Third plant even further out
    if total_zones > 25 or obs.city_pop > 600:
        p3x = px + 40
        p3y = py
        if in_bounds(p3x, p3y):
            nearby_plant3 = any(
                in_bounds(p3x + dx, p3y + dy) and pm[p3y + dy, p3x + dx]
                for dy in range(-6, 7) for dx in range(-6, 7)
            )
            if not nearby_plant3 and em[p3y, p3x]:
                return (Tool.COALPOWER, p3x, p3y)
            else:
                for wc in range(wire_col + 2, p3x):
                    if in_bounds(wc, py) and (em[py, wc] or wm[py, wc]) and not pm[py, wc]:
                        if not wm[py, wc]:
                            return (Tool.WIRE, wc, py)

    # --- Phase 7: Services ---
    if obs.city_pop > 100:
        fsx, fsy = px - 8, py - 8
        if in_bounds(fsx, fsy) and em[fsy, fsx]:
            return (Tool.FIRESTATION, fsx, fsy)
        psx, psy = px - 8, py + 8
        if in_bounds(psx, psy) and em[psy, psx]:
            return (Tool.POLICESTATION, psx, psy)

    # --- Phase 8: Expand wire laterally to reach new road areas ---
    wire_ys_arr2, wire_xs_arr2 = np.where(wm)
    if len(wire_xs_arr2) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr2), 1)
        for offset in range(min(len(wire_xs_arr2), 20)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr2)
            wx, wy = int(wire_xs_arr2[k]), int(wire_ys_arr2[k])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = wx + dx2, wy + dy2
                if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                    # Only extend wire near existing roads
                    if nbr_road[ny2, nx2]:
                        return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Improved policy with:
    - Two power plants for larger coverage
    - Horizontal road spine instead of vertical
    - Zones above and below the road spine
    - Better balanced zone mix (more commercial/industrial)
    - Multiple clusters expanding outward
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # Use state as memory
    if 'phase' not in state:
        state['phase'] = 0
        state['build_queue'] = []

    # Map center area
    cx, cy = 60, 50

    # Plant location - place two plants for more power coverage
    plant1_cx, plant1_cy = 55, 50
    plant2_cx, plant2_cy = 75, 50

    # Horizontal road spine at row cy
    road_row = cy
    wire_row = cy - 2  # wire runs parallel above road

    # Zone rows above and below
    zone_row_above = road_row - 5   # row 45
    zone_row_below = road_row + 5   # row 55

    # Zone columns spaced every 6 from col 45 to 95
    zone_cols = list(range(45, 96, 6))

    has_plant1 = np.any(pm[plant1_cy-1:plant1_cy+2, plant1_cx-1:plant1_cx+2])
    has_plant2 = np.any(pm[plant2_cy-1:plant2_cy+2, plant2_cx-1:plant2_cx+2])

    # Phase 1: Place first coal power plant
    if not has_plant1:
        return (Tool.COALPOWER, plant1_cx, plant1_cy)

    wire_positions = set(zip(*np.where(wm))) if np.any(wm) else set()
    road_positions = set(zip(*np.where(rm))) if np.any(rm) else set()
    res_positions = set(zip(*np.where(res_m))) if np.any(res_m) else set()
    com_positions = set(zip(*np.where(com_m))) if np.any(com_m) else set()
    ind_positions = set(zip(*np.where(ind_m))) if np.any(ind_m) else set()
    all_zones = res_positions | com_positions | ind_positions

    res_count = len(res_positions)
    com_count = len(com_positions)
    ind_count = len(ind_positions)

    # Phase 2: Build horizontal wire row from plant outward
    wire_cols_in_row = sorted(c for (r, c) in wire_positions if r == wire_row)

    # First wire adjacent to plant
    if not wire_cols_in_row:
        wc = plant1_cx + 2
        if 0 <= wc < WORLD_W and em[wire_row, wc]:
            return (Tool.WIRE, wc, wire_row)
        return (Tool.WIRE, plant1_cx, wire_row)

    min_wc = min(wire_cols_in_row)
    max_wc = max(wire_cols_in_row)

    # Dynamic expansion based on pop
    wire_target_left = max(35, 42 - min(10, obs.city_pop // 50))
    wire_target_right = min(95, 68 + min(20, obs.city_pop // 30))

    if max_wc < wire_target_right:
        nc = max_wc + 1
        if nc < WORLD_W and (em[wire_row, nc] or wm[wire_row, nc]):
            if em[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    if min_wc > wire_target_left:
        nc = min_wc - 1
        if nc >= 0 and (em[wire_row, nc] or wm[wire_row, nc]):
            if em[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    wire_cols_set = set(wire_cols_in_row)
    road_cols_in_row = set(c for (r, c) in road_positions if r == road_row)

    # Phase 3: Build horizontal road row matching wire coverage
    for wc in sorted(wire_cols_in_row):
        if wc not in road_cols_in_row and 0 <= wc < WORLD_W:
            if em[road_row, wc]:
                return (Tool.ROAD, wc, road_row)

    # Helper: check if 3x3 area is clear
    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def already_zone_nearby(zr, zc, zones, dist=2):
        return any(abs(zr - pr) <= dist and abs(zc - pc) <= dist for (pr, pc) in zones)

    def pick_zone_type(res_c, com_c, ind_c):
        # Target ratio: 2 res : 1 com : 1 ind
        if res_c == 0:
            return Tool.RESIDENTIAL
        if ind_c * 2 < res_c:
            return Tool.INDUSTRIAL
        if com_c * 2 < res_c:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Phase 4: Place vertical wires connecting road to zones above/below
    for zc in zone_cols:
        if zc not in wire_cols_set:
            continue
        # Wire from wire_row up to zone_row_above
        for vr in range(wire_row - 1, zone_row_above - 1, -1):
            if 0 <= vr < WORLD_H and em[vr, zc]:
                return (Tool.WIRE, zc, vr)
        # Wire from road_row down to zone_row_below
        for vr in range(road_row + 1, zone_row_below + 1):
            if 0 <= vr < WORLD_H and em[vr, zc]:
                return (Tool.WIRE, zc, vr)

    # Phase 5: Place zones above and below road
    for zc in zone_cols:
        if zc not in wire_cols_set:
            continue
        road_nearby = zc in road_cols_in_row or any(abs(zc - rc) <= 1 for rc in road_cols_in_row)
        if not road_nearby:
            continue

        for zr in [zone_row_above, zone_row_below]:
            if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                if not already_zone_nearby(zr, zc, all_zones) and zone_area_free(zr, zc):
                    zt = pick_zone_type(res_count, com_count, ind_count)
                    all_zones.add((zr, zc))
                    if zt == Tool.RESIDENTIAL:
                        res_count += 1
                    elif zt == Tool.COMMERCIAL:
                        com_count += 1
                    else:
                        ind_count += 1
                    return (zt, zc, zr)

    # Phase 6: Place second power plant when pop >= 100
    if obs.city_pop >= 100 and not has_plant2:
        return (Tool.COALPOWER, plant2_cx, plant2_cy)

    # Phase 7: Add second wire row further below for more zones
    if obs.city_pop >= 150:
        wire_row2 = cy + 12  # row 62
        road_row2 = cy + 14  # row 64
        zone_row2_below = road_row2 + 5  # row 69
        zone_row2_above = wire_row2 - 1  # just above wire

        wire_cols2 = sorted(c for (r, c) in wire_positions if r == wire_row2)
        road_cols2 = set(c for (r, c) in road_positions if r == road_row2)

        if not wire_cols2:
            # Connect down from main wire row via vertical wire at plant col
            conn_col = plant1_cx
            for vr in range(wire_row + 1, wire_row2 + 1):
                if em[vr, conn_col] or wm[vr, conn_col]:
                    if em[vr, conn_col]:
                        return (Tool.WIRE, conn_col, vr)
        else:
            min_wc2 = min(wire_cols2)
            max_wc2 = max(wire_cols2)
            w2_target_right = min(95, 50 + min(30, obs.city_pop // 20))
            w2_target_left = max(40, 55 - min(15, obs.city_pop // 40))

            if max_wc2 < w2_target_right:
                nc = max_wc2 + 1
                if nc < WORLD_W and em[wire_row2, nc]:
                    return (Tool.WIRE, nc, wire_row2)
            if min_wc2 > w2_target_left:
                nc = min_wc2 - 1
                if nc >= 0 and em[wire_row2, nc]:
                    return (Tool.WIRE, nc, wire_row2)

            # Road for second row
            for wc in sorted(wire_cols2):
                if wc not in road_cols2 and 0 <= wc < WORLD_W:
                    if em[road_row2, wc]:
                        return (Tool.ROAD, wc, road_row2)

            # Zones for second row
            for zc in zone_cols:
                if zc not in set(wire_cols2):
                    continue
                road_nearby2 = zc in road_cols2 or any(abs(zc - rc) <= 1 for rc in road_cols2)
                if not road_nearby2:
                    continue
                for zr in [zone_row2_below, road_row2 - 5]:
                    if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                        if not already_zone_nearby(zr, zc, all_zones) and zone_area_free(zr, zc):
                            zt = pick_zone_type(res_count, com_count, ind_count)
                            all_zones.add((zr, zc))
                            return (zt, zc, zr)

    # Phase 8: Add third row above for high pop
    if obs.city_pop >= 300:
        wire_row3 = cy - 12  # row 38
        road_row3 = cy - 14  # row 36

        wire_cols3 = sorted(c for (r, c) in wire_positions if r == wire_row3)
        road_cols3 = set(c for (r, c) in road_positions if r == road_row3)

        if not wire_cols3:
            conn_col = plant1_cx
            for vr in range(wire_row - 1, wire_row3 - 1, -1):
                if em[vr, conn_col] or wm[vr, conn_col]:
                    if em[vr, conn_col]:
                        return (Tool.WIRE, conn_col, vr)
        else:
            min_wc3 = min(wire_cols3)
            max_wc3 = max(wire_cols3)

            if max_wc3 < 90:
                nc = max_wc3 + 1
                if nc < WORLD_W and em[wire_row3, nc]:
                    return (Tool.WIRE, nc, wire_row3)
            if min_wc3 > 40:
                nc = min_wc3 - 1
                if nc >= 0 and em[wire_row3, nc]:
                    return (Tool.WIRE, nc, wire_row3)

            for wc in sorted(wire_cols3):
                if wc not in road_cols3 and 0 <= wc < WORLD_W:
                    if em[road_row3, wc]:
                        return (Tool.ROAD, wc, road_row3)

            for zc in zone_cols:
                if zc not in set(wire_cols3):
                    continue
                road_nearby3 = zc in road_cols3 or any(abs(zc - rc) <= 1 for rc in road_cols3)
                if not road_nearby3:
                    continue
                for zr in [road_row3 - 5, road_row3 + 5]:
                    if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                        if not already_zone_nearby(zr, zc, all_zones) and zone_area_free(zr, zc):
                            zt = pick_zone_type(res_count, com_count, ind_count)
                            all_zones.add((zr, zc))
                            return (zt, zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map each step and places next tile
    based on what already exists. Uses state only for a simple phase counter.

    Strategy:
    - Coal plant near center-left
    - Wire spine grows vertically from plant, detected each step
    - Roads grow adjacent to wire, detected each step
    - Zones placed adjacent to roads, with mix of R/C/I
    - Expand laterally when initial columns fill
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    cx, cy = 58, 50  # center of operations

    has_plant = np.any(pm)

    # --- Phase 1: Place coal power plant ---
    plant_cx, plant_cy = 47, 50
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Find plant center from map
    plant_rows, plant_cols = np.where(pm)
    if len(plant_rows) > 0:
        plant_cy_actual = int(np.mean(plant_rows))
        plant_cx_actual = int(np.mean(plant_cols))
    else:
        plant_cy_actual, plant_cx_actual = plant_cy, plant_cx

    # Wire spine column: just right of plant footprint
    wire_col = plant_cx_actual + 2  # main wire spine

    # Road columns flanking wire
    road_col_r = wire_col + 1
    road_col_l = wire_col - 1

    # Zone columns flanking roads
    zone_col_r = road_col_r + 2
    zone_col_l = road_col_l - 2

    # Vertical span to build
    pop_span = min(30, obs.city_pop // 20 + 8)
    tmin = max(2, cy - pop_span)
    tmax = min(WORLD_H - 3, cy + pop_span)

    # --- Phase 2: Grow wire spine vertically ---
    wire_in_col = sorted(r for r in range(WORLD_H) if wm[r, wire_col])

    if not wire_in_col:
        # Start wire adjacent to plant
        for dy in range(-1, 4):
            ny = plant_cy_actual + dy
            if 0 <= ny < WORLD_H and 0 <= wire_col < WORLD_W:
                if em[ny, wire_col]:
                    return (Tool.WIRE, wire_col, ny)
    else:
        max_wr = max(wire_in_col)
        min_wr = min(wire_in_col)
        # Extend downward first
        if max_wr < tmax:
            nr = max_wr + 1
            if 0 <= nr < WORLD_H:
                if em[nr, wire_col] or wm[nr, wire_col]:
                    return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if min_wr > tmin:
            nr = min_wr - 1
            if 0 <= nr < WORLD_H:
                if em[nr, wire_col] or wm[nr, wire_col]:
                    return (Tool.WIRE, wire_col, nr)

    wire_set = set(wire_in_col)

    # --- Phase 3: Grow roads adjacent to wire ---
    road_r_set = set(r for r in range(WORLD_H) if rm[r, road_col_r]) if 0 <= road_col_r < WORLD_W else set()
    road_l_set = set(r for r in range(WORLD_H) if rm[r, road_col_l]) if 0 <= road_col_l < WORLD_W else set()

    for wr in wire_in_col:
        if wr not in road_r_set and 0 <= road_col_r < WORLD_W:
            if em[wr, road_col_r]:
                return (Tool.ROAD, road_col_r, wr)
        if wr not in road_l_set and 0 <= road_col_l >= 0:
            if em[wr, road_col_l]:
                return (Tool.ROAD, road_col_l, wr)

    # --- Gather existing zones for ratio tracking ---
    res_count = int(np.sum(res_mask(tm)))
    com_count = int(np.sum(com_mask(tm)))
    ind_count = int(np.sum(ind_mask(tm)))
    all_z = res_mask(tm) | com_mask(tm) | ind_mask(tm)

    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def zone_nearby(zr, zc):
        r0, r1 = max(0, zr-2), min(WORLD_H, zr+3)
        c0, c1 = max(0, zc-2), min(WORLD_W, zc+3)
        return np.any(all_z[r0:r1, c0:c1])

    def pick_tool(prefer_ind=False, prefer_com=False):
        total = res_count + com_count + ind_count + 1
        if prefer_ind or (ind_count * 5 < total):
            return Tool.INDUSTRIAL
        if prefer_com or (com_count * 4 < total):
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Phase 4: Place zones adjacent to roads ---
    # Right side zones (commercial/residential)
    for zr in wire_in_col:
        road_nearby_r = any(abs(zr - rr) <= 1 for rr in road_r_set)
        if road_nearby_r and 0 <= zone_col_r < WORLD_W:
            if not zone_nearby(zr, zone_col_r) and zone_area_free(zr, zone_col_r):
                tool = pick_tool(prefer_com=(com_count * 3 < res_count))
                return (tool, zone_col_r, zr)

    # Left side zones (industrial/residential)
    for zr in wire_in_col:
        road_nearby_l = any(abs(zr - rr) <= 1 for rr in road_l_set)
        if road_nearby_l and 0 <= zone_col_l < WORLD_W:
            if not zone_nearby(zr, zone_col_l) and zone_area_free(zr, zone_col_l):
                tool = pick_tool(prefer_ind=(ind_count * 3 < res_count))
                return (tool, zone_col_l, zr)

    # --- Phase 5: Expand further right with a second cluster ---
    if obs.city_pop > 50 or len(wire_in_col) > 6:
        # Second wire column further right
        wire_col2 = zone_col_r + 4
        road_col2r = wire_col2 + 1
        zone_col2r = road_col2r + 2
        road_col2l = wire_col2 - 1
        zone_col2l = road_col2l - 2

        if 0 <= wire_col2 < WORLD_W:
            wire2_rows = sorted(r for r in range(WORLD_H) if wm[r, wire_col2])

            if not wire2_rows:
                # Lay horizontal wire connecting from wire_col to wire_col2 at plant_cy_actual
                for wc in range(wire_col + 1, wire_col2 + 1):
                    if 0 <= wc < WORLD_W and em[plant_cy_actual, wc]:
                        return (Tool.WIRE, wc, plant_cy_actual)
            else:
                max_wr2 = max(wire2_rows)
                min_wr2 = min(wire2_rows)
                if max_wr2 < tmax:
                    nr = max_wr2 + 1
                    if 0 <= nr < WORLD_H and (em[nr, wire_col2] or wm[nr, wire_col2]):
                        return (Tool.WIRE, wire_col2, nr)
                if min_wr2 > tmin:
                    nr = min_wr2 - 1
                    if 0 <= nr < WORLD_H and (em[nr, wire_col2] or wm[nr, wire_col2]):
                        return (Tool.WIRE, wire_col2, nr)

                road2r_set = set(r for r in range(WORLD_H) if rm[r, road_col2r]) if 0 <= road_col2r < WORLD_W else set()
                for wr in wire2_rows:
                    if wr not in road2r_set and 0 <= road_col2r < WORLD_W:
                        if em[wr, road_col2r]:
                            return (Tool.ROAD, road_col2r, wr)

                for zr in wire2_rows:
                    road_n = any(abs(zr - rr) <= 1 for rr in road2r_set)
                    if road_n and 0 <= zone_col2r < WORLD_W:
                        if not zone_nearby(zr, zone_col2r) and zone_area_free(zr, zone_col2r):
                            return (pick_tool(), zone_col2r, zr)

    # --- Phase 6: Expand left cluster ---
    if obs.city_pop > 100:
        wire_col3 = zone_col_l - 4
        road_col3r = wire_col3 + 1
        zone_col3r = road_col3r + 2

        if 0 <= wire_col3 < WORLD_W:
            wire3_rows = sorted(r for r in range(WORLD_H) if wm[r, wire_col3])

            if not wire3_rows:
                for wc in range(wire_col3, wire_col):
                    if 0 <= wc < WORLD_W and em[plant_cy_actual, wc]:
                        return (Tool.WIRE, wc, plant_cy_actual)
            else:
                max_wr3 = max(wire3_rows)
                min_wr3 = min(wire3_rows)
                if max_wr3 < tmax:
                    nr = max_wr3 + 1
                    if 0 <= nr < WORLD_H and (em[nr, wire_col3] or wm[nr, wire_col3]):
                        return (Tool.WIRE, wire_col3, nr)
                if min_wr3 > tmin:
                    nr = min_wr3 - 1
                    if 0 <= nr < WORLD_H and (em[nr, wire_col3] or wm[nr, wire_col3]):
                        return (Tool.WIRE, wire_col3, nr)

                road3_set = set(r for r in range(WORLD_H) if rm[r, road_col3r]) if 0 <= road_col3r < WORLD_W else set()
                for wr in wire3_rows:
                    if wr not in road3_set and 0 <= road_col3r < WORLD_W:
                        if em[wr, road_col3r]:
                            return (Tool.ROAD, road_col3r, wr)

                for zr in wire3_rows:
                    road_n = any(abs(zr - rr) <= 1 for rr in road3_set)
                    if road_n and 0 <= zone_col3r < WORLD_W:
                        if not zone_nearby(zr, zone_col3r) and zone_area_free(zr, zone_col3r):
                            return (Tool.RESIDENTIAL, zone_col3r, zr)

    # --- Phase 7: Second coal plant if very large ---
    if obs.city_pop > 400 and not state.get("plant2", False):
        p2x, p2y = plant_cx_actual + 30, plant_cy_actual
        if 0 <= p2x < WORLD_W and 0 <= p2y < WORLD_H:
            clear = all(
                em[p2y + dr, p2x + dc]
                for dr in [-1, 0, 1] for dc in [-1, 0, 1]
                if 0 <= p2y + dr < WORLD_H and 0 <= p2x + dc < WORLD_W
            )
            if clear:
                state["plant2"] = True
                return (Tool.COALPOWER, p2x, p2y)

    return None

def act(obs, state):
    """
    Improved city-building policy:
    - Builds TWO separate neighborhoods connected by roads
    - More aggressive zone placement with better road/wire coverage
    - Better balanced R/C/I mix
    - Uses a grid layout: roads every 4 tiles, wires along roads
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        # Balanced mix: 50% res, 25% com, 25% ind
        if total_zones == 0:
            return Tool.INDUSTRIAL
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Use state to track build phase
    if 'phase' not in state:
        state['phase'] = 0
        state['build_queue'] = []

    # ---- CLUSTER 1: centered at (40, 50), CLUSTER 2: centered at (80, 50) ----
    # Each cluster: coal plant + wire grid + road grid + zones
    clusters = [
        {'cx': 35, 'cy': 45, 'plant': (35, 45)},
        {'cx': 80, 'cy': 45, 'plant': (80, 45)},
    ]

    def expand_mask(base, radius=2):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        ys, xs = np.where(base)
        for y, x in zip(ys, xs):
            r0 = max(0, y - radius); r1 = min(WORLD_H, y + radius + 1)
            c0 = max(0, x - radius); c1 = min(WORLD_W, x + radius + 1)
            result[r0:r1, c0:c1] = True
        return result

    nbr_road = expand_mask(rm, 2)
    power_src = wm | pm
    nbr_wire = expand_mask(power_src, 2)
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and not zone_tiles[nr, nc]:
                    return False
        return True

    # Step 1: Place power plants
    for cl in clusters:
        px, py = cl['plant']
        nearby = any(
            in_bounds(px + dx, py + dy) and pm[py + dy, px + dx]
            for dy in range(-4, 5) for dx in range(-4, 5)
        )
        if not nearby:
            if in_bounds(px, py):
                return (Tool.COALPOWER, px, py)

    # Step 2: Build wire + road grid for each cluster
    # Each cluster: wire spine at cx, roads at cx-1, cx+1, cx-5, cx+5
    # Zones at cx+-3 (centered 3 away from wire)
    for cl in clusters:
        cx, cy = cl['cx'], cl['cy']
        extent = 15  # half-size of cluster

        # Vertical wire spine through cx
        for dy in range(-extent, extent + 1):
            wy = cy + dy
            if not in_bounds(cx, wy):
                continue
            if not wm[wy, cx] and not pm[wy, cx]:
                if em[wy, cx] or wm[wy, cx]:
                    # Check if connected to plant (within extent)
                    if abs(wy - cy) <= extent:
                        return (Tool.WIRE, cx, wy)

        # Horizontal wire spine through cy
        for dx in range(-extent, extent + 1):
            wx = cx + dx
            if not in_bounds(wx, cy):
                continue
            if not wm[cy, wx] and not pm[cy, wx]:
                if em[cy, wx] or wm[cy, wx]:
                    return (Tool.WIRE, wx, cy)

        # Roads parallel to vertical spine
        for road_offset in [-2, 2]:
            rx = cx + road_offset
            for dy in range(-extent, extent + 1):
                ry = cy + dy
                if not in_bounds(rx, ry):
                    continue
                if em[ry, rx] and not pm[ry, rx]:
                    return (Tool.ROAD, rx, ry)

        # Roads parallel to horizontal spine
        for road_offset in [-2, 2]:
            ry = cy + road_offset
            for dx in range(-extent, extent + 1):
                rx = cx + dx
                if not in_bounds(rx, ry):
                    continue
                if em[ry, rx] and not pm[ry, rx] and not wm[ry, rx]:
                    return (Tool.ROAD, rx, ry)

    # Step 3: Connect the two clusters with a road
    for rx in range(clusters[0]['cx'] + 3, clusters[1]['cx'] - 3):
        ry = clusters[0]['cy']
        if not in_bounds(rx, ry):
            continue
        if em[ry, rx] and not pm[ry, rx]:
            return (Tool.ROAD, rx, ry)

    # Also connect with wire
    for rx in range(clusters[0]['cx'] + 3, clusters[1]['cx'] - 3):
        ry = clusters[0]['cy'] + 1  # wire one row below road
        if not in_bounds(rx, ry):
            continue
        if (em[ry, rx] or wm[ry, rx]) and not pm[ry, rx]:
            if not wm[ry, rx]:
                return (Tool.WIRE, rx, ry)

    # Step 4: Place zones where road+wire coverage exists
    # Refresh coverage masks
    nbr_road = expand_mask(rm, 2)
    power_src = wm | pm
    nbr_wire = expand_mask(power_src, 2)

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prefer zones near cluster centers
        best_score = 1e9
        best_k = -1
        # Use step offset for variety
        step_off = int(obs.step * 7) % max(len(cxs), 1)
        for i in range(min(len(cxs), 80)):
            k = (step_off + i) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            # Distance to nearest cluster center
            min_d = min(abs(zx - cl['cx']) + abs(zy - cl['cy']) for cl in clusters)
            if min_d < best_score and zone_clear(zx, zy):
                best_score = min_d
                best_k = k
        if best_k >= 0:
            zx, zy = int(cxs[best_k]), int(cys[best_k])
            return (pick_tool(), zx, zy)

    # Step 5: Services when population grows
    if obs.city_pop > 200:
        # Fire station between clusters
        fsx, fsy = 57, 40
        if in_bounds(fsx, fsy) and em[fsy, fsx]:
            return (Tool.FIRESTATION, fsx, fsy)
        # Police station
        psx, psy = 57, 52
        if in_bounds(psx, psy) and em[psy, psx]:
            return (Tool.POLICESTATION, psx, psy)

    # Step 6: Third cluster if population high
    if obs.city_pop > 400:
        cl3 = {'cx': 58, 'cy': 20, 'plant': (58, 20)}
        px, py = cl3['plant']
        nearby = any(
            in_bounds(px + dx, py + dy) and pm[py + dy, px + dx]
            for dy in range(-4, 5) for dx in range(-4, 5)
        )
        if not nearby and in_bounds(px, py) and em[py, px]:
            return (Tool.COALPOWER, px, py)

        # Wire from main spine up to cl3
        cx3, cy3 = cl3['cx'], cl3['cy']
        for wy in range(cy3, clusters[0]['cy']):
            if not in_bounds(cx3, wy):
                continue
            if not wm[wy, cx3] and not pm[wy, cx3]:
                if em[wy, cx3] or wm[wy, cx3]:
                    return (Tool.WIRE, cx3, wy)

        # Roads in cl3
        for road_offset in [-2, 2]:
            rx = cx3 + road_offset
            for dy in range(-10, 11):
                ry = cy3 + dy
                if not in_bounds(rx, ry):
                    continue
                if em[ry, rx] and not pm[ry, rx]:
                    return (Tool.ROAD, rx, ry)

    # Step 7: Extend wire to unserved zones
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 15)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = wx + dx2, wy + dy2
                if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                    return (Tool.WIRE, nx2, ny2)

    # Step 8: Extend roads from existing roads
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 20)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx]:
                    if nbr_wire[ny, nx]:
                        return (Tool.ROAD, nx, ny)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map each step and reacts.
    Strategy improvements over parent:
    - Denser corridor: wire col + road col + zone cols closer together
    - Place zones on BOTH sides more aggressively
    - Connect zones to power with lateral wires more eagerly
    - Use a right-side road column too for wider coverage
    - Add second power plant sooner
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Phase 1: Place coal power plant if missing
    if not np.any(pm):
        # Place plant to the left of center
        return (Tool.COALPOWER, cx - 10, cy)

    # Find plant centroid
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Layout constants
    wire_col = plant_cx + 3      # wire spine just right of plant
    left_road_col = wire_col + 2  # road between wire and right zones
    right_road_col = wire_col - 2  # road between left zones and wire
    left_zone_col = right_road_col - 3   # zones left of right_road_col
    right_zone_col = left_road_col + 3   # zones right of left_road_col

    # Clamp
    wire_col = max(3, min(WORLD_W - 4, wire_col))
    left_road_col = max(3, min(WORLD_W - 4, left_road_col))
    right_road_col = max(3, min(WORLD_W - 4, right_road_col))
    left_zone_col = max(2, min(WORLD_W - 3, left_zone_col))
    right_zone_col = max(2, min(WORLD_W - 3, right_zone_col))

    wire_rows_on_spine = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])

    # How far to extend spine
    if obs.city_pop < 100:
        spine_extent = 10
    elif obs.city_pop < 300:
        spine_extent = 16
    elif obs.city_pop < 600:
        spine_extent = 22
    else:
        spine_extent = 30

    target_min = max(1, cy - spine_extent)
    target_max = min(WORLD_H - 2, cy + spine_extent)

    # Phase 2: Start wire adjacent to plant if none on spine
    if not wire_rows_on_spine:
        for dy in range(0, 6):
            for nr in [plant_cy + dy, plant_cy - dy]:
                if 0 <= nr < WORLD_H:
                    if (em[nr, wire_col] or wm[nr, wire_col]) and not pm[nr, wire_col]:
                        return (Tool.WIRE, wire_col, nr)
        return None

    min_wire_row = min(wire_rows_on_spine)
    max_wire_row = max(wire_rows_on_spine)

    # Phase 3: Extend wire spine downward
    if max_wire_row < target_max:
        nr = max_wire_row + 1
        if nr < WORLD_H and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Phase 4: Extend wire spine upward
    if min_wire_row > target_min:
        nr = min_wire_row - 1
        if nr >= 0 and not pm[nr, wire_col]:
            if em[nr, wire_col] or wm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # Phase 5: Build left road column (between wire and left zones)
    for r in wire_rows_on_spine:
        if 0 <= r < WORLD_H and 0 <= right_road_col < WORLD_W:
            if not rm[r, right_road_col] and em[r, right_road_col] and not pm[r, right_road_col]:
                return (Tool.ROAD, right_road_col, r)

    # Phase 5b: Build right road column (between wire and right zones)
    for r in wire_rows_on_spine:
        if 0 <= r < WORLD_H and 0 <= left_road_col < WORLD_W:
            if not rm[r, left_road_col] and em[r, left_road_col] and not pm[r, left_road_col]:
                return (Tool.ROAD, left_road_col, r)

    all_zone_mask = resm | comm | indm

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=3):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=3):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = total_zones
        # Balance: ~50% res, 25% com, 25% ind
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    left_road_rows = sorted([r for r in range(WORLD_H) if rm[r, right_road_col]])
    right_road_rows = sorted([r for r in range(WORLD_H) if rm[r, left_road_col]])

    zone_rows = list(range(max(1, target_min), min(WORLD_H - 1, target_max + 1), 3))

    # Phase 6: Place zones near wire and roads
    for zr in zone_rows:
        wire_near = any(abs(zr - wr) <= 2 for wr in wire_rows_on_spine)
        lroad_near = any(abs(zr - rr) <= 2 for rr in left_road_rows)
        rroad_near = any(abs(zr - rr) <= 2 for rr in right_road_rows)

        if wire_near:
            # Left zone (uses right_road_col as road access)
            if lroad_near:
                zc = left_zone_col
                if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                    if has_road_nearby(zr, zc) and has_wire_nearby(zr, zc, 4):
                        return (pick_tool(), zc, zr)

            # Right zone (uses left_road_col as road access)
            if rroad_near:
                zc = right_zone_col
                if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                    if has_road_nearby(zr, zc) and has_wire_nearby(zr, zc, 4):
                        return (pick_tool(), zc, zr)

    # Phase 7: Lateral wires from spine to left zones
    for wr in wire_rows_on_spine:
        # Wire left from spine to cover left_zone_col
        for wc in range(wire_col - 1, left_zone_col - 2, -1):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc] and not wm[wr, wc]:
                    break

    # Phase 8: Lateral wires from spine to right zones
    for wr in wire_rows_on_spine:
        for wc in range(wire_col + 1, right_zone_col + 2):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc] and not wm[wr, wc]:
                    break

    # Phase 9: Second coal plant sooner (when pop > 200)
    if obs.city_pop > 200 and int(np.sum(pm)) < 9:
        px2 = plant_cx + 20
        py2 = plant_cy
        if 2 <= py2 <= WORLD_H - 3 and 2 <= px2 <= WORLD_W - 3:
            if em[py2, px2]:
                return (Tool.COALPOWER, px2, py2)
        # Try above/below
        for dy in [-10, 10, -20, 20]:
            py2 = plant_cy + dy
            px2 = plant_cx + 15
            if 2 <= py2 <= WORLD_H - 3 and 2 <= px2 <= WORLD_W - 3:
                if em[py2, px2]:
                    return (Tool.COALPOWER, px2, py2)

    # Phase 10: Wire from second plant to spine if needed
    # Find all plant clusters
    if int(np.sum(pm)) >= 9:
        # Check for disconnected zones needing wire bridges
        plant_areas = np.where(pm)
        if len(plant_areas[0]) > 0:
            # Try to wire from any plant tile leftward/rightward to spine
            for prow, pcol in zip(plant_areas[0][::3], plant_areas[1][::3]):
                # Wire bridge from right plant to spine
                if pcol > wire_col:
                    for wc in range(pcol - 1, wire_col, -1):
                        if 0 <= wc < WORLD_W:
                            if wm[prow, wc]:
                                break
                            if em[prow, wc] and not rm[prow, wc]:
                                return (Tool.WIRE, wc, prow)
                            elif not em[prow, wc]:
                                break

    # Phase 11: Expand zone columns further out if city growing
    if obs.city_pop > 300:
        far_left_col = left_zone_col - 6
        far_right_col = right_zone_col + 6
        for zc in [far_left_col, far_right_col]:
            if 2 <= zc <= WORLD_W - 3:
                for zr in zone_rows:
                    if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                        if has_road_nearby(zr, zc, 5) and has_wire_nearby(zr, zc, 6):
                            return (Tool.RESIDENTIAL, zc, zr)

    # Phase 12: Fill gaps - zones without power but with roads, add wires
    if total_zones > 0 and obs.city_pop < 50:
        # Emergency: ensure zones have both wire and road
        zone_positions = np.where(all_zone_mask)
        if len(zone_positions[0]) > 0:
            zr = int(zone_positions[0][0])
            zc = int(zone_positions[1][0])
            if not has_wire_nearby(zr, zc, 3):
                # Wire toward spine
                mid_c = (zc + wire_col) // 2
                if em[zr, mid_c] and not pm[zr, mid_c]:
                    return (Tool.WIRE, mid_c, zr)
            if not has_road_nearby(zr, zc, 3):
                mid_c = (zc + right_road_col) // 2
                if em[zr, mid_c] and not pm[zr, mid_c]:
                    return (Tool.ROAD, mid_c, zr)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder.
    Each step reads the current map and places the next useful tile.
    Strategy: anchor near center, build coal plant, extend wire spine,
    build road grid, fill zones between roads.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Anchor: plant goes here
    CX, CY = 58, 50

    # ---- Phase 1: Place coal power plant ----
    plant_ys, plant_xs = np.where(pm)
    has_plant = len(plant_xs) > 0
    if not has_plant:
        return (Tool.COALPOWER, CX, CY)

    px = int(plant_xs[0])
    py = int(plant_ys[0])
    power_map = pm | wm

    # ---- Helper: is a cell powered (adjacent to power_map)? ----
    def is_powered(x, y):
        if bool(power_map[y, x]):
            return True
        for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx, ny = x+dx, y+dy
            if in_bounds(nx, ny) and bool(power_map[ny, nx]):
                return True
        return False

    # ---- Phase 2: Wire spine - build cross pattern from plant ----
    def find_wire_extension():
        # Build cross spine: vertical and horizontal through plant
        targets = []
        # Vertical spine
        for dy in range(-24, 25):
            targets.append((px, py + dy))
        # Horizontal arms at 3 y-offsets from plant
        for arm_dy in [0, -6, 6, -12, 12]:
            for dx in range(-20, 21):
                targets.append((px + dx, py + arm_dy))

        for (wx, wy) in targets:
            if not in_bounds(wx, wy):
                continue
            if bool(wm[wy, wx]) or bool(pm[wy, wx]):
                continue
            if bool(rm[wy, wx]):
                continue
            if not bool(em[wy, wx]):
                continue
            # Must connect to existing power
            for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx2, ny2 = wx+ddx, wy+ddy
                if in_bounds(nx2, ny2) and bool(power_map[ny2, nx2]):
                    return (Tool.WIRE, wx, wy)
        return None

    # ---- Phase 3: Road grid anchored at plant ----
    def find_road_extension():
        # Grid: horizontal roads every 4 rows, vertical roads every 4 cols
        # Offset from plant position
        candidates = []

        # Horizontal roads
        for row_off in range(-16, 17, 4):
            ry = py + row_off
            for dx in range(-20, 21):
                candidates.append((px + dx, ry))

        # Vertical roads
        for col_off in range(-16, 17, 4):
            rx = px + col_off
            for dy in range(-16, 17):
                candidates.append((rx, py + dy))

        for (rx, ry) in candidates:
            if not in_bounds(rx, ry):
                continue
            if bool(rm[ry, rx]):
                continue
            if bool(pm[ry, rx]) or bool(wm[ry, rx]):
                continue
            if not bool(em[ry, rx]):
                continue
            # Must connect to existing road or be near plant
            for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx2, ny2 = rx+ddx, ry+ddy
                if in_bounds(nx2, ny2) and bool(rm[ny2, nx2]):
                    return (Tool.ROAD, rx, ry)
            # Bootstrap first road from plant
            for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1),(2,0),(-2,0),(0,2),(0,-2),
                              (3,0),(-3,0),(0,3),(0,-3)]:
                nx2, ny2 = rx+ddx, ry+ddy
                if in_bounds(nx2, ny2) and bool(pm[ny2, nx2]):
                    return (Tool.ROAD, rx, ry)
        return None

    # ---- Phase 4: Place zones ----
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        # Aim for ~55% R, 25% C, 20% I
        r_frac = res_count / total_zones
        c_frac = com_count / total_zones
        i_frac = ind_count / total_zones
        if i_frac < 0.20:
            return Tool.INDUSTRIAL
        if c_frac < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def find_zone_placement():
        # Compute road influence (within 2 tiles Manhattan)
        nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-2, 3):
            for dx in range(-2, 3):
                if abs(dy) + abs(dx) <= 2:
                    sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                    sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                    r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                    c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                    nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

        # Compute power influence (within 6 tiles)
        nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-6, 7):
            for dx in range(-6, 7):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
                nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

        zone_mask = resm | comm | indm
        cand = em & nbr_road & nbr_power
        # Stay away from edges (3x3 zones need room)
        cand[:2, :] = False
        cand[WORLD_H-2:, :] = False
        cand[:, :2] = False
        cand[:, WORLD_W-2:] = False

        cys, cxs = np.where(cand)
        if len(cxs) == 0:
            return None

        # Sort by Manhattan distance to plant (closer = prefer)
        dists = np.abs(cxs - px).astype(np.int32) + np.abs(cys - py).astype(np.int32)
        order = np.argsort(dists)

        tool = pick_tool()

        for i in range(min(len(cxs), 120)):
            k = order[i]
            zx, zy = int(cxs[k]), int(cys[k])
            # Check 3x3 clearance
            ok = True
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    ny2, nx2 = zy + dr, zx + dc
                    if not in_bounds(nx2, ny2):
                        ok = False; break
                    if not (bool(em[ny2, nx2]) or bool(zone_mask[ny2, nx2])):
                        ok = False; break
                if not ok:
                    break
            if ok:
                return (tool, zx, zy)
        return None

    # ---- Measure current state ----
    wire_count = int(np.sum(wm))
    road_count = int(np.sum(rm))

    # Count vertical spine wires
    spine_filled = sum(1 for dy in range(-24, 25)
                      if in_bounds(px, py+dy) and bool(wm[py+dy, px]))

    wire_action = find_wire_extension()
    road_action = find_road_extension()

    # ---- Decision logic ----

    # Priority 1: Build wire spine first (so power reaches zones)
    if spine_filled < 20 and wire_action is not None:
        return wire_action

    # Priority 2: Bootstrap initial roads
    if road_count < 12 and road_action is not None:
        return road_action

    # Interleave based on step and city state
    step_mod = obs.step % 10
    pop = obs.city_pop

    if pop < 150:
        # Early: 30% wire, 40% road, 30% zones
        if step_mod in (0, 1, 2) and wire_action is not None:
            return wire_action
        if step_mod in (3, 4, 5, 6) and road_action is not None:
            return road_action
        zone = find_zone_placement()
        if zone is not None:
            return zone
        if road_action is not None:
            return road_action
        if wire_action is not None:
            return wire_action
    elif pop < 500:
        # Mid: 20% wire, 30% road, 50% zones
        if step_mod in (0, 1) and wire_action is not None:
            return wire_action
        if step_mod in (2, 3, 4) and road_action is not None:
            return road_action
        zone = find_zone_placement()
        if zone is not None:
            return zone
        if road_action is not None:
            return road_action
        if wire_action is not None:
            return wire_action
    else:
        # Late: mostly zones
        if step_mod == 0 and wire_action is not None:
            return wire_action
        if step_mod in (1, 2) and road_action is not None:
            return road_action
        zone = find_zone_placement()
        if zone is not None:
            return zone
        if road_action is not None:
            return road_action
        if wire_action is not None:
            return wire_action

    # Services to boost growth (placed reactively when pop thresholds hit)
    if pop > 150:
        for fx, fy in [(px+6, py-8), (px-6, py+8), (px+10, py+6), (px-10, py-6)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.FIRESTATION, fx, fy)

    if pop > 350:
        for fx, fy in [(px+6, py+8), (px-6, py-8), (px+10, py-6), (px-10, py+6)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.POLICESTATION, fx, fy)

    # Second power plant when first is overloaded
    if pop > 600 and len(plant_xs) < 2:
        for fx, fy in [(px+18, py), (px-18, py), (px, py+18), (px, py-18)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.COALPOWER, fx, fy)

    # Fallback: extend road from any road tile
    rys2, rxs2 = np.where(rm)
    if len(rxs2) > 0:
        k2 = int(obs.step * 13 + int(obs.city_pop)) % len(rxs2)
        rx2, ry2 = int(rxs2[k2]), int(rys2[k2])
        for ddx, ddy in [(0,1),(1,0),(0,-1),(-1,0)]:
            nx2, ny2 = rx2+ddx, ry2+ddy
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and not bool(wm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map each step to decide next placement.
    Strategy:
    - Phase 0: Place coal power plant at fixed anchor
    - Phase 1: Extend wires from existing power/wire tiles toward a road spine
    - Phase 2: Build road spine
    - Phase 3: Place zones adjacent to road+wire coverage
    - Phase 4: Expand reactively based on what's powered and roaded
    """

    # Anchor positions
    PLANT_X, PLANT_Y = 20, 50
    SPINE_X = 25  # vertical road+wire spine

    tm = obs.tile_map
    step = obs.step

    # --- Phase 0: ensure power plant exists ---
    if not state.get("plant_placed"):
        state["plant_placed"] = True
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    # --- Phase 1: extend wire from plant to spine ---
    # Wire horizontally from PLANT_X+2 to SPINE_X
    if not state.get("wire_h_done"):
        wx = state.get("wire_hx", PLANT_X + 2)
        if wx <= SPINE_X:
            state["wire_hx"] = wx + 1
            return (Tool.WIRE, wx, PLANT_Y)
        else:
            state["wire_h_done"] = True

    # --- Phase 2: build vertical wire+road spine ---
    if not state.get("spine_done"):
        sy = state.get("spine_y", 30)
        if sy <= 75:
            state["spine_y"] = sy + 1
            # Wire on spine_x, road on spine_x+1
            if not state.get("spine_wire_row"):
                state["spine_wire_row"] = True
                return (Tool.WIRE, SPINE_X, sy)
            else:
                state["spine_wire_row"] = False
                return (Tool.ROAD, SPINE_X + 1, sy)
        else:
            state["spine_done"] = True

    # Also connect wire horizontally at PLANT_Y from spine to zones
    if not state.get("wire_extend_done"):
        we = state.get("wire_ex", SPINE_X + 2)
        if we <= SPINE_X + 10:
            state["wire_ex"] = we + 1
            return (Tool.WIRE, we, PLANT_Y)
        else:
            state["wire_extend_done"] = True

    # --- Phase 3+: closed-loop zone/road/wire placement ---
    # Find existing wire tiles to expand from
    wm = wire_mask(tm)
    rm = road_mask(tm)
    em = empty_mask(tm)
    pm = plant_mask(tm)

    # Combine power sources: wire + plant
    powered_src = wm | pm

    # Helper: get neighbors
    def neighbors4(y, x):
        for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
            ny, nx = y+dy, x+dx
            if 0 <= ny < WORLD_H and 0 <= nx < WORLD_W:
                yield ny, nx

    # Find tiles adjacent to power
    def find_adj_to_power_and_empty():
        # Find empty tiles adjacent to wire/plant
        ys, xs = np.where(powered_src)
        for i in range(len(ys)):
            y, x = int(ys[i]), int(xs[i])
            for ny, nx in neighbors4(y, x):
                if em[ny, nx]:
                    return ny, nx
        return None

    # Find road tiles to extend from
    def find_adj_to_road_and_empty():
        ys, xs = np.where(rm)
        for i in range(len(ys)):
            y, x = int(ys[i]), int(xs[i])
            for ny, nx in neighbors4(y, x):
                if em[ny, nx]:
                    return ny, nx
        return None

    # Find tiles that have both road neighbor AND wire neighbor (good zone spot)
    def find_powered_roaded_empty():
        # A tile is good for a zone if adjacent to road AND adjacent to wire/plant
        ys, xs = np.where(em)
        for i in range(len(ys)):
            y, x = int(ys[i]), int(xs[i])
            has_road = False
            has_wire = False
            for ny, nx in neighbors4(y, x):
                if rm[ny, nx]: has_road = True
                if powered_src[ny, nx]: has_wire = True
            if has_road and has_wire:
                return y, x
        return None

    # Use a small phase counter in state to cycle behaviors
    phase = state.get("phase3_counter", 0)
    state["phase3_counter"] = phase + 1

    # Decide zone type based on what's already on map
    res_count = int(np.sum(res_mask(tm)))
    com_count = int(np.sum(com_mask(tm)))
    ind_count = int(np.sum(ind_mask(tm)))

    if res_count <= com_count and res_count <= ind_count:
        zone_tool = Tool.RESIDENTIAL
    elif com_count <= ind_count:
        zone_tool = Tool.COMMERCIAL
    else:
        zone_tool = Tool.INDUSTRIAL

    # Every 60 steps check if we need another power plant
    if phase % 60 == 59:
        # Find furthest wire extent and place plant nearby if needed
        powered_count = int(np.sum(powered_src))
        road_count = int(np.sum(rm))
        if road_count > powered_count * 3:
            # Need more power - extend wire spine further
            # Find rightmost wire and extend
            ys, xs = np.where(wm)
            if len(xs) > 0:
                rightmost_x = int(np.max(xs))
                rightmost_y = int(ys[np.argmax(xs)])
                if rightmost_x < 90:
                    return (Tool.WIRE, rightmost_x + 1, rightmost_y)

    # Every 80 steps: add a second power plant if population is low
    if phase % 80 == 40 and obs.city_pop < 500:
        plant_ys, plant_xs = np.where(pm)
        if len(plant_xs) < 2:
            # Place second plant
            return (Tool.COALPOWER, 70, 50)

    # Every 100 steps: connect second plant with wire
    if phase % 100 == 50:
        # Wire from plant2 toward zones
        return (Tool.WIRE, 65, 50)

    # Main logic: try to place a zone at a good spot
    if phase % 3 != 2:  # 2/3 of steps: place zones
        good = find_powered_roaded_empty()
        if good:
            y, x = good
            return (zone_tool, x, y)
        # If no good spot, try extending wire
        pos = find_adj_to_power_and_empty()
        if pos:
            ny, nx = pos
            return (Tool.WIRE, nx, ny)
    else:  # 1/3 of steps: extend road or wire
        # Try extending road
        pos = find_adj_to_road_and_empty()
        if pos:
            ny, nx = pos
            # Check if we should add wire here too
            if powered_src[ny, nx]:
                return (Tool.WIRE, nx, ny)
            return (Tool.ROAD, nx, ny)
        # Fallback: extend wire
        pos = find_adj_to_power_and_empty()
        if pos:
            ny, nx = pos
            return (Tool.WIRE, nx, ny)

    # Fallback: place zone anywhere near spine
    sy = state.get("fallback_y", 33)
    fx = SPINE_X + 4
    if sy < 75:
        state["fallback_y"] = sy + 3
        return (zone_tool, fx, sy)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Vertical wire spine + flanking roads (Parent A's best structure)
    - Reads actual tile_map each step to find frontier
    - Places next wire/road/zone adjacent to what already exists
    - Adapts zone mix based on current counts
    - Adds second power plant and services when population warrants
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Step 1: Place first coal plant if none exists ---
    if not np.any(pm):
        return (Tool.COALPOWER, 58, 48)

    # Find primary plant center
    plant_ys, plant_xs = np.where(pm)
    px = int(np.median(plant_xs))
    py = int(np.median(plant_ys))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        if ind_count / t < 0.22:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Wire spine column: just right of plant center
    wire_col = px + 2
    road_col_l = wire_col - 2
    road_col_r = wire_col + 2

    # Dynamic vertical extent based on population
    pop_factor = min(35, obs.city_pop // 12)
    spine_top = max(3, py - 15 - pop_factor)
    spine_bot = min(WORLD_H - 4, py + 15 + pop_factor)

    # --- Step 2: Grow vertical wire spine reactively ---
    # Scan current wire positions in the spine column
    wire_rows_in_col = [r for r in range(WORLD_H) if in_bounds(wire_col, r) and bool(wm[r, wire_col])]
    plant_rows_in_col = [r for r in range(WORLD_H) if in_bounds(wire_col, r) and bool(pm[r, wire_col])]

    if not wire_rows_in_col:
        # Seed wire adjacent to plant - find nearest empty cell in wire column
        for dy in range(-2, 3):
            ny = py + dy
            if in_bounds(wire_col, ny) and bool(em[ny, wire_col]) and not bool(pm[ny, wire_col]):
                return (Tool.WIRE, wire_col, ny)
        # If column blocked, try adjacent column
        for try_col in [wire_col + 1, wire_col - 1]:
            for dy in range(-2, 3):
                ny = py + dy
                if in_bounds(try_col, ny) and bool(em[ny, try_col]) and not bool(pm[ny, try_col]):
                    return (Tool.WIRE, try_col, ny)
    else:
        min_wr = min(wire_rows_in_col)
        max_wr = max(wire_rows_in_col)
        # Extend downward if needed
        if max_wr < spine_bot:
            nr = max_wr + 1
            if in_bounds(wire_col, nr) and bool(em[nr, wire_col]) and not bool(pm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        # Extend upward if needed
        if min_wr > spine_top:
            nr = min_wr - 1
            if in_bounds(wire_col, nr) and bool(em[nr, wire_col]) and not bool(pm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    # Re-read wire rows after potential placement
    wire_rows_in_col = [r for r in range(WORLD_H) if in_bounds(wire_col, r) and bool(wm[r, wire_col])]

    # --- Step 3: Second power plant when needed ---
    if obs.city_pop > 150 or total_zones > 10:
        p2x = px + 22
        p2y = py
        if in_bounds(p2x, p2y):
            nearby_plant = any(
                in_bounds(p2x + dx, p2y + dy) and bool(pm[p2y + dy, p2x + dx])
                for dy in range(-6, 7) for dx in range(-6, 7)
                if in_bounds(p2x + dx, p2y + dy)
            )
            if not nearby_plant:
                if bool(em[p2y, p2x]):
                    return (Tool.COALPOWER, p2x, p2y)
                # Bridge wire horizontally from spine to second plant position
                for wc in range(wire_col + 1, p2x):
                    if in_bounds(wc, py) and bool(em[py, wc]) and not bool(pm[py, wc]):
                        return (Tool.WIRE, wc, py)

    # --- Step 4: Road columns flanking wire spine - reactive fill ---
    # Check actual road coverage; place where wire exists but road doesn't
    if wire_rows_in_col:
        for wr in wire_rows_in_col:
            if in_bounds(road_col_l, wr) and bool(em[wr, road_col_l]) and not bool(pm[wr, road_col_l]):
                return (Tool.ROAD, road_col_l, wr)
            if in_bounds(road_col_r, wr) and bool(em[wr, road_col_r]) and not bool(pm[wr, road_col_r]):
                return (Tool.ROAD, road_col_r, wr)

    # --- Step 5: Place zones reactively ---
    # Build proximity masks from current tile_map
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not in_bounds(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prefer candidates close to wire spine, sorted by distance
        dists = np.abs(cxs - wire_col) * 2 + np.abs(cys - py)
        order = np.argsort(dists)
        # Rotate starting point each step for diversity
        step_off = (obs.step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 100:
                break

    # --- Step 6: Extend roads from existing road frontier near wire ---
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (obs.step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 25)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if in_bounds(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]) and bool(nbr_wire[ny, nx]):
                    return (Tool.ROAD, nx, ny)

    # --- Step 7: Services when population warrants ---
    if obs.city_pop > 200:
        for fpos in [(px - 12, py - 8), (px + 12, py - 8)]:
            fsx, fsy = fpos
            if in_bounds(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)
    if obs.city_pop > 400:
        for ppos in [(px - 12, py + 8), (px + 12, py + 8)]:
            psx, psy = ppos
            if in_bounds(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    # --- Step 8: Extend wire frontier from existing wire edges ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 20)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = wx + dx, wy + dy
                if in_bounds(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    return None

def act(obs, state):
    """
    Redesigned policy: vertical road/wire spines with zones on left and right.
    - Nuclear power plant (more capacity) at top-center
    - Vertical wire spine down center column
    - Two vertical road spines flanking the wire
    - Zones placed left and right of the roads
    - Compact initial cluster, expand as population grows
    - Better zone mix management
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    if 'init' not in state:
        state['init'] = True
        state['action_queue'] = []

    # Core layout parameters
    plant_cx, plant_cy = 60, 10  # nuclear plant at top center
    wire_col = 60                 # vertical wire spine
    road_col_left = 56            # left road spine
    road_col_right = 64           # right road spine

    # Zone columns
    zone_col_far_left = 52        # zones to the left of left road
    zone_col_near_left = 58       # zones between wire and left road (skip - road is there)
    zone_col_near_right = 62      # zones between wire and right road
    zone_col_far_right = 68       # zones to the right of right road

    # Actually place zones at col offsets from wire
    zone_cols_left = [52, 56]     # left side zone centers
    zone_cols_right = [64, 68]    # right side zone centers

    y_start = plant_cy + 4        # start below plant
    y_end = 90                    # extend downward

    has_plant = np.any(pm)

    # Place nuclear power plant
    if not has_plant:
        return (Tool.NUCLEARPOWER, plant_cx, plant_cy)

    # Count zones
    res_positions = list(zip(*np.where(res_m))) if np.any(res_m) else []
    com_positions = list(zip(*np.where(com_m))) if np.any(com_m) else []
    ind_positions = list(zip(*np.where(ind_m))) if np.any(ind_m) else []
    all_zones = set(res_positions) | set(com_positions) | set(ind_positions)

    res_count = len(res_positions)
    com_count = len(com_positions)
    ind_count = len(ind_positions)

    # Dynamic vertical extent
    y_dynamic_end = min(y_end, y_start + 12 + min(50, obs.city_pop // 5))

    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def already_zone_nearby(zr, zc):
        for (pr, pc) in all_zones:
            if abs(zr - pr) <= 2 and abs(zc - pc) <= 2:
                return True
        return False

    def pick_zone_type():
        # Target ratio: 3 res : 2 com : 2 ind
        if res_count == 0:
            return Tool.RESIDENTIAL
        if com_count == 0:
            return Tool.COMMERCIAL
        if ind_count == 0:
            return Tool.INDUSTRIAL
        total = res_count + com_count + ind_count
        if res_count * 7 < total * 3:
            return Tool.RESIDENTIAL
        if com_count * 7 < total * 2:
            return Tool.COMMERCIAL
        if ind_count * 7 < total * 2:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Connect plant to wire spine vertically (plant is centered at plant_cx=60=wire_col)
    # Wire from just below plant downward
    wire_rows_present = set(r for (r, c) in zip(*np.where(wm)) if c == wire_col) if np.any(wm) else set()
    road_rows_left = set(r for (r, c) in zip(*np.where(rm)) if c == road_col_left) if np.any(rm) else set()
    road_rows_right = set(r for (r, c) in zip(*np.where(rm)) if c == road_col_right) if np.any(rm) else set()

    # Step 1: Extend wire spine downward
    for yr in range(y_start, y_dynamic_end + 1):
        if yr not in wire_rows_present:
            if 0 <= yr < WORLD_H and (em[yr, wire_col] or wm[yr, wire_col]):
                if em[yr, wire_col]:
                    return (Tool.WIRE, wire_col, yr)

    # Step 2: Extend left road spine
    for yr in range(y_start, y_dynamic_end + 1):
        if yr not in road_rows_left:
            if 0 <= yr < WORLD_H and em[yr, road_col_left]:
                return (Tool.ROAD, road_col_left, yr)

    # Step 3: Extend right road spine
    for yr in range(y_start, y_dynamic_end + 1):
        if yr not in road_rows_right:
            if 0 <= yr < WORLD_H and em[yr, road_col_right]:
                return (Tool.ROAD, road_col_right, yr)

    # Step 4: Add horizontal connector roads every 6 rows (for road access to zones)
    for yr in range(y_start + 2, y_dynamic_end - 1, 6):
        if 0 <= yr < WORLD_H:
            # Connect left road to right road via horizontal road segment
            for xc in range(road_col_left, road_col_right + 1):
                if em[yr, xc]:
                    return (Tool.ROAD, xc, yr)

    # Step 5: Place zones on both sides
    for yr in range(y_start + 3, y_dynamic_end - 2, 4):
        if yr < 2 or yr >= WORLD_H - 2:
            continue
        # Check if this row has road access (nearby road spine)
        road_close = (yr in road_rows_left) or (yr in road_rows_right) or \
                     any(abs(yr - r) <= 1 for r in road_rows_left) or \
                     any(abs(yr - r) <= 1 for r in road_rows_right)
        if not road_close:
            continue

        # Left far zones
        for zc in [50, 54]:
            if 2 <= zc < WORLD_W - 2:
                if not already_zone_nearby(yr, zc) and zone_area_free(yr, zc):
                    return (pick_zone_type(), zc, yr)

        # Right far zones
        for zc in [66, 70]:
            if 2 <= zc < WORLD_W - 2:
                if not already_zone_nearby(yr, zc) and zone_area_free(yr, zc):
                    return (pick_zone_type(), zc, yr)

    # Step 6: Wire connections to zones on left side
    wire_target_cols_left = [50, 54]
    wire_target_cols_right = [66, 70]

    for zc in wire_target_cols_left:
        # Horizontal wire from wire_col to zc for rows where zones exist
        for yr in range(y_start + 3, y_dynamic_end - 2, 4):
            # Wire from wire_col toward zc
            step_dir = -1 if zc < wire_col else 1
            for xc in range(wire_col + step_dir, zc + step_dir, step_dir):
                if 0 <= xc < WORLD_W and 0 <= yr < WORLD_H:
                    if em[yr, xc] and not wm[yr, xc]:
                        return (Tool.WIRE, xc, yr)

    for zc in wire_target_cols_right:
        for yr in range(y_start + 3, y_dynamic_end - 2, 4):
            step_dir = -1 if zc < wire_col else 1
            for xc in range(wire_col + step_dir, zc + step_dir, step_dir):
                if 0 <= xc < WORLD_W and 0 <= yr < WORLD_H:
                    if em[yr, xc] and not wm[yr, xc]:
                        return (Tool.WIRE, xc, yr)

    # Step 7: Second cluster when population grows - expand horizontally
    if obs.city_pop >= 200:
        # Add zones further out
        y_ext_end = min(y_end, y_start + 20 + min(60, (obs.city_pop - 200) // 4))

        # Far left road at col 46
        road_col_far_left = 46
        road_rows_far_left = set(r for (r, c) in zip(*np.where(rm)) if c == road_col_far_left) if np.any(rm) else set()
        for yr in range(y_start, y_ext_end + 1):
            if yr not in road_rows_far_left:
                if 0 <= yr < WORLD_H and em[yr, road_col_far_left]:
                    return (Tool.ROAD, road_col_far_left, yr)

        # Far right road at col 74
        road_col_far_right = 74
        road_rows_far_right = set(r for (r, c) in zip(*np.where(rm)) if c == road_col_far_right) if np.any(rm) else set()
        for yr in range(y_start, y_ext_end + 1):
            if yr not in road_rows_far_right:
                if 0 <= yr < WORLD_H and em[yr, road_col_far_right]:
                    return (Tool.ROAD, road_col_far_right, yr)

        # Zones adjacent to far roads
        for yr in range(y_start + 3, y_ext_end - 2, 4):
            if yr < 2 or yr >= WORLD_H - 2:
                continue
            for zc in [42, 78]:
                if 2 <= zc < WORLD_W - 2:
                    if not already_zone_nearby(yr, zc) and zone_area_free(yr, zc):
                        return (pick_zone_type(), zc, yr)

        # Wire to far zones
        for yr in range(y_start + 3, y_ext_end - 2, 4):
            for xc in range(wire_col - 1, 40, -1):
                if 0 <= xc < WORLD_W and 0 <= yr < WORLD_H:
                    if em[yr, xc] and not wm[yr, xc]:
                        return (Tool.WIRE, xc, yr)
                    elif wm[yr, xc]:
                        break

    # Step 8: Add police/fire stations for city services
    if obs.city_pop >= 500:
        # Place police station
        ps_r, ps_c = y_start + 5, wire_col - 10
        if 0 <= ps_r < WORLD_H and 0 <= ps_c < WORLD_W:
            if em[ps_r, ps_c]:
                return (Tool.POLICESTATION, ps_c, ps_r)

    if obs.city_pop >= 800:
        fs_r, fs_c = y_start + 10, wire_col + 10
        if 0 <= fs_r < WORLD_H and 0 <= fs_c < WORLD_W:
            if em[fs_r, fs_c]:
                return (Tool.FIRESTATION, fs_c, fs_r)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy.
    Key changes from parent:
    - More compact layout: zones placed directly adjacent to road/wire
    - Better zone mix tracking
    - Vertical road connectors earlier
    - More aggressive zone placement
    - Connect zones to wire more carefully
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    has_plant = np.any(pm)

    # ---- Phase 1: Place coal power plant ----
    if not has_plant:
        return (Tool.COALPOWER, 60, 50)

    plant_rows, plant_cols = np.where(pm)
    pcx = int(np.mean(plant_cols))
    pcy = int(np.mean(plant_rows))

    # Layout constants - compact design
    wire_row = pcy - 1
    wire_row = max(2, min(WORLD_H - 3, wire_row))

    road_row_top = wire_row - 2
    road_row_bot = wire_row + 2
    zone_row_top = road_row_top - 3
    zone_row_bot = road_row_bot + 3

    road_row_top = max(2, min(WORLD_H - 3, road_row_top))
    road_row_bot = max(2, min(WORLD_H - 3, road_row_bot))
    zone_row_top = max(2, min(WORLD_H - 3, zone_row_top))
    zone_row_bot = max(2, min(WORLD_H - 3, zone_row_bot))

    # Expand span based on population
    half_span = min(50, max(15, 15 + obs.city_pop // 8))
    cmin = max(2, pcx - half_span)
    cmax = min(WORLD_W - 3, pcx + half_span)

    # ---- Phase 2: Build horizontal wire spine ----
    wire_cols = sorted(c for c in range(WORLD_W) if 0 <= wire_row < WORLD_H and wm[wire_row, c])

    if not wire_cols:
        # Start wire adjacent to plant
        for dx in range(-3, 4):
            nx = pcx + dx
            if 0 <= nx < WORLD_W and 0 <= wire_row < WORLD_H:
                if em[wire_row, nx]:
                    return (Tool.WIRE, nx, wire_row)
        return (Tool.WIRE, pcx, wire_row)
    else:
        min_wc = wire_cols[0]
        max_wc = wire_cols[-1]
        if max_wc < cmax:
            nc = max_wc + 1
            if 0 <= nc < WORLD_W:
                return (Tool.WIRE, nc, wire_row)
        if min_wc > cmin:
            nc = min_wc - 1
            if 0 <= nc < WORLD_W:
                return (Tool.WIRE, nc, wire_row)

    wire_cols_set = set(wire_cols)
    all_zone_m = res_m | com_m | ind_m

    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def nearby_zone(zr, zc, radius=3):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(all_zone_m[r0:r1, c0:c1])

    res_count = max(1, int(np.sum(res_m)) // 9)
    com_count = max(1, int(np.sum(com_m)) // 9)
    ind_count = max(1, int(np.sum(ind_m)) // 9)
    total_zones = res_count + com_count + ind_count

    def pick_zone():
        # Target ratio: 50% residential, 25% commercial, 25% industrial
        if com_count * 4 < total_zones:
            return Tool.COMMERCIAL
        if ind_count * 4 < total_zones:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # ---- Phase 3: Build road rows ----
    if wire_cols:
        if 0 <= road_row_top < WORLD_H:
            for wc in wire_cols:
                if cmin <= wc <= cmax and not rm[road_row_top, wc] and em[road_row_top, wc]:
                    return (Tool.ROAD, wc, road_row_top)
        if 0 <= road_row_bot < WORLD_H:
            for wc in wire_cols:
                if cmin <= wc <= cmax and not rm[road_row_bot, wc] and em[road_row_bot, wc]:
                    return (Tool.ROAD, wc, road_row_bot)

    # ---- Phase 4: Vertical road connectors (earlier than parent) ----
    if wire_cols and obs.city_pop > 20:
        # Place vertical roads every 6 columns to connect top and bottom roads
        for vc in range(cmin + 3, cmax, 6):
            if 0 <= vc < WORLD_W:
                for vr in range(road_row_top, road_row_bot + 1):
                    if 0 <= vr < WORLD_H and not rm[vr, vc] and em[vr, vc]:
                        return (Tool.ROAD, vc, vr)

    # ---- Phase 5: Place zones ----
    if wire_cols:
        road_cols_top = set(c for c in range(WORLD_W) if 0 <= road_row_top < WORLD_H and rm[road_row_top, c])
        road_cols_bot = set(c for c in range(WORLD_W) if 0 <= road_row_bot < WORLD_H and rm[road_row_bot, c])

        # Zones above top road (offset by 3 to center on road)
        for zc in sorted(wire_cols, key=lambda c: abs(c - pcx)):
            if not (cmin <= zc <= cmax):
                continue
            road_near_top = any(abs(zc - rc) <= 1 for rc in road_cols_top)
            if road_near_top and 2 <= zone_row_top <= WORLD_H - 3:
                if not nearby_zone(zone_row_top, zc, 2) and zone_area_free(zone_row_top, zc):
                    return (pick_zone(), zc, zone_row_top)

        # Zones below bottom road
        for zc in sorted(wire_cols, key=lambda c: abs(c - pcx)):
            if not (cmin <= zc <= cmax):
                continue
            road_near_bot = any(abs(zc - rc) <= 1 for rc in road_cols_bot)
            if road_near_bot and 2 <= zone_row_bot <= WORLD_H - 3:
                if not nearby_zone(zone_row_bot, zc, 2) and zone_area_free(zone_row_bot, zc):
                    return (pick_zone(), zc, zone_row_bot)

        # Also try a second row of zones further out
        zone_row_top2 = zone_row_top - 4
        zone_row_bot2 = zone_row_bot + 4
        zone_row_top2 = max(2, min(WORLD_H - 3, zone_row_top2))
        zone_row_bot2 = max(2, min(WORLD_H - 3, zone_row_bot2))

        if obs.city_pop > 50:
            # Need roads for second zone row
            road_row_top2 = zone_row_top2 + 1  # road between zone rows
            road_row_bot2 = zone_row_bot2 - 1
            road_row_top2 = max(2, min(WORLD_H - 3, road_row_top2))
            road_row_bot2 = max(2, min(WORLD_H - 3, road_row_bot2))

            # Build those roads
            if 0 <= road_row_top2 < WORLD_H:
                for wc in wire_cols:
                    if cmin <= wc <= cmax and not rm[road_row_top2, wc] and em[road_row_top2, wc]:
                        return (Tool.ROAD, wc, road_row_top2)
            if 0 <= road_row_bot2 < WORLD_H:
                for wc in wire_cols:
                    if cmin <= wc <= cmax and not rm[road_row_bot2, wc] and em[road_row_bot2, wc]:
                        return (Tool.ROAD, wc, road_row_bot2)

            road_cols_top2 = set(c for c in range(WORLD_W) if 0 <= road_row_top2 < WORLD_H and rm[road_row_top2, c])
            road_cols_bot2 = set(c for c in range(WORLD_W) if 0 <= road_row_bot2 < WORLD_H and rm[road_row_bot2, c])

            for zc in sorted(wire_cols, key=lambda c: abs(c - pcx)):
                if not (cmin <= zc <= cmax):
                    continue
                if any(abs(zc - rc) <= 1 for rc in road_cols_top2):
                    if 2 <= zone_row_top2 <= WORLD_H - 3:
                        if not nearby_zone(zone_row_top2, zc, 2) and zone_area_free(zone_row_top2, zc):
                            return (pick_zone(), zc, zone_row_top2)
                if any(abs(zc - rc) <= 1 for rc in road_cols_bot2):
                    if 2 <= zone_row_bot2 <= WORLD_H - 3:
                        if not nearby_zone(zone_row_bot2, zc, 2) and zone_area_free(zone_row_bot2, zc):
                            return (pick_zone(), zc, zone_row_bot2)

    # ---- Phase 6: Second cluster (second horizontal band) ----
    if obs.city_pop > 60 and wire_cols:
        wire_row2 = pcy + 10
        wire_row2 = max(2, min(WORLD_H - 3, wire_row2))
        road_row2_top = wire_row2 - 2
        road_row2_bot = wire_row2 + 2
        zone_row2_top = road_row2_top - 3
        zone_row2_bot = road_row2_bot + 3
        road_row2_top = max(2, min(WORLD_H - 3, road_row2_top))
        road_row2_bot = max(2, min(WORLD_H - 3, road_row2_bot))
        zone_row2_top = max(2, min(WORLD_H - 3, zone_row2_top))
        zone_row2_bot = max(2, min(WORLD_H - 3, zone_row2_bot))

        wire_cols2 = sorted(c for c in range(WORLD_W) if 0 <= wire_row2 < WORLD_H and wm[wire_row2, c])

        if not wire_cols2:
            # Bridge vertically from wire_row to wire_row2 at pcx
            bridge_x = pcx
            for wr in range(min(wire_row, wire_row2), max(wire_row, wire_row2) + 1):
                if 0 <= wr < WORLD_H and not wm[wr, bridge_x] and (em[wr, bridge_x] or rm[wr, bridge_x]):
                    return (Tool.WIRE, bridge_x, wr)
        else:
            min_wc2 = wire_cols2[0]
            max_wc2 = wire_cols2[-1]
            if max_wc2 < cmax:
                nc = max_wc2 + 1
                if 0 <= nc < WORLD_W:
                    return (Tool.WIRE, nc, wire_row2)
            if min_wc2 > cmin:
                nc = min_wc2 - 1
                if 0 <= nc < WORLD_W:
                    return (Tool.WIRE, nc, wire_row2)

            if 0 <= road_row2_top < WORLD_H:
                for wc in wire_cols2:
                    if cmin <= wc <= cmax and not rm[road_row2_top, wc] and em[road_row2_top, wc]:
                        return (Tool.ROAD, wc, road_row2_top)
            if 0 <= road_row2_bot < WORLD_H:
                for wc in wire_cols2:
                    if cmin <= wc <= cmax and not rm[road_row2_bot, wc] and em[road_row2_bot, wc]:
                        return (Tool.ROAD, wc, road_row2_bot)

            road_cols2_top = set(c for c in range(WORLD_W) if 0 <= road_row2_top < WORLD_H and rm[road_row2_top, c])
            road_cols2_bot = set(c for c in range(WORLD_W) if 0 <= road_row2_bot < WORLD_H and rm[road_row2_bot, c])

            for zc in sorted(wire_cols2, key=lambda c: abs(c - pcx)):
                if not (cmin <= zc <= cmax):
                    continue
                if any(abs(zc - rc) <= 1 for rc in road_cols2_top):
                    if 2 <= zone_row2_top <= WORLD_H - 3:
                        if not nearby_zone(zone_row2_top, zc, 2) and zone_area_free(zone_row2_top, zc):
                            return (pick_zone(), zc, zone_row2_top)
                if any(abs(zc - rc) <= 1 for rc in road_cols2_bot):
                    if 2 <= zone_row2_bot <= WORLD_H - 3:
                        if not nearby_zone(zone_row2_bot, zc, 2) and zone_area_free(zone_row2_bot, zc):
                            return (pick_zone(), zc, zone_row2_bot)

    # ---- Phase 7: Second power plant when large ----
    if obs.city_pop > 300 and not state.get("plant2_placed", False):
        px2 = pcx - 25
        py2 = pcy
        px2 = max(2, min(WORLD_W - 3, px2))
        py2 = max(2, min(WORLD_H - 3, py2))
        clear = all(
            0 <= py2 + dr < WORLD_H and 0 <= px2 + dc < WORLD_W and em[py2 + dr, px2 + dc]
            for dr in [-1, 0, 1] for dc in [-1, 0, 1]
        )
        if clear:
            state["plant2_placed"] = True
            return (Tool.COALPOWER, px2, py2)

    return None

def act(obs, state):
    """
    Improved city-building policy with a horizontal road grid and multiple zones.
    Strategy:
    1. Place coal power plant
    2. Build horizontal wire spine from plant
    3. Build two parallel horizontal roads above and below wire spine
    4. Place zones in rows adjacent to roads
    5. Mix RES/COM/IND more evenly
    """
    tm = obs.tile_map
    emp = empty_mask(tm)
    res = res_mask(tm)
    com = com_mask(tm)
    ind = ind_mask(tm)
    road = road_mask(tm)
    wire = wire_mask(tm)
    plant = plant_mask(tm)

    # Use center-left anchor for plant
    cx, cy = 30, WORLD_H // 2  # shift left so more room to right

    # --- Phase 0: Place coal power plant if none exists ---
    if not np.any(plant):
        return (Tool.COALPOWER, cx, cy)

    # Find plant centroid
    plant_ys, plant_xs = np.where(plant)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    # Wire spine: horizontal, at row py, extending right from plant
    wire_row = py
    # Extend wire horizontally from px+2 to px+50
    wire_start_x = px + 2
    wire_end_x = min(px + 55, WORLD_W - 2)

    # Check if we need to extend the wire
    for wx in range(wire_start_x, wire_end_x + 1):
        if 0 <= wx < WORLD_W and 0 <= wire_row < WORLD_H:
            if not wire[wire_row, wx] and not plant[wire_row, wx]:
                # Check adjacency to existing wire or plant
                adj = False
                for ddx, ddy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    ny2, nx2 = wire_row + ddy, wx + ddx
                    if 0 <= ny2 < WORLD_H and 0 <= nx2 < WORLD_W:
                        if wire[ny2, nx2] or plant[ny2, nx2]:
                            adj = True
                            break
                if adj:
                    return (Tool.WIRE, wx, wire_row)

    # Road rows: above and below wire spine
    road_row_top = py - 3
    road_row_bot = py + 3
    road_start_x = px + 3
    road_end_x = wire_end_x

    # Build top road row
    for rx in range(road_start_x, road_end_x + 1):
        if 0 <= rx < WORLD_W and 0 <= road_row_top < WORLD_H:
            if not road[road_row_top, rx]:
                adj = False
                for ddx, ddy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    ny2, nx2 = road_row_top + ddy, rx + ddx
                    if 0 <= ny2 < WORLD_H and 0 <= nx2 < WORLD_W:
                        if road[ny2, nx2] or wire[ny2, nx2] or plant[ny2, nx2]:
                            adj = True
                            break
                if adj:
                    return (Tool.ROAD, rx, road_row_top)

    # Build bottom road row
    for rx in range(road_start_x, road_end_x + 1):
        if 0 <= rx < WORLD_W and 0 <= road_row_bot < WORLD_H:
            if not road[road_row_bot, rx]:
                adj = False
                for ddx, ddy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    ny2, nx2 = road_row_bot + ddy, rx + ddx
                    if 0 <= ny2 < WORLD_H and 0 <= nx2 < WORLD_W:
                        if road[ny2, nx2] or wire[ny2, nx2] or plant[ny2, nx2]:
                            adj = True
                            break
                if adj:
                    return (Tool.ROAD, rx, road_row_bot)

    # Also add a second set of roads further out for more zones
    road_row_top2 = py - 8
    road_row_bot2 = py + 8

    for rx in range(road_start_x, road_end_x + 1):
        if 0 <= rx < WORLD_W and 0 <= road_row_top2 < WORLD_H:
            if not road[road_row_top2, rx]:
                adj = False
                for ddx, ddy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    ny2, nx2 = road_row_top2 + ddy, rx + ddx
                    if 0 <= ny2 < WORLD_H and 0 <= nx2 < WORLD_W:
                        if road[ny2, nx2]:
                            adj = True
                            break
                if adj:
                    return (Tool.ROAD, rx, road_row_top2)

    for rx in range(road_start_x, road_end_x + 1):
        if 0 <= rx < WORLD_W and 0 <= road_row_bot2 < WORLD_H:
            if not road[road_row_bot2, rx]:
                adj = False
                for ddx, ddy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    ny2, nx2 = road_row_bot2 + ddy, rx + ddx
                    if 0 <= ny2 < WORLD_H and 0 <= nx2 < WORLD_W:
                        if road[ny2, nx2]:
                            adj = True
                            break
                if adj:
                    return (Tool.ROAD, rx, road_row_bot2)

    # Add vertical connector roads every 6 tiles to connect road rows
    for vx in range(road_start_x + 3, road_end_x, 6):
        for ry in range(road_row_top2, road_row_bot2 + 1):
            if 0 <= ry < WORLD_H and 0 <= vx < WORLD_W:
                if not road[ry, vx] and not wire[ry, vx] and not plant[ry, vx]:
                    adj = False
                    for ddx, ddy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        ny2, nx2 = ry + ddy, vx + ddx
                        if 0 <= ny2 < WORLD_H and 0 <= nx2 < WORLD_W:
                            if road[ny2, nx2] or wire[ny2, nx2] or plant[ny2, nx2]:
                                adj = True
                                break
                    if adj:
                        return (Tool.ROAD, vx, ry)

    # --- Phase 3: Place zones ---
    zones = res | com | ind
    n_res = int(np.sum(res))
    n_com = int(np.sum(com))
    n_ind = int(np.sum(ind))
    total = n_res + n_com + n_ind

    # Zone mix: 2 RES : 1 COM : 1 IND
    r = obs.step % 4
    if r < 2:
        tool = Tool.RESIDENTIAL
    elif r == 2:
        tool = Tool.COMMERCIAL
    else:
        tool = Tool.INDUSTRIAL

    # Build road and wire proximity maps
    road_near = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            road_near |= np.roll(np.roll(road, dy2, axis=0), dx2, axis=1)

    wire_near = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-4, 5):
        for dx2 in range(-4, 5):
            wire_near |= np.roll(np.roll(wire, dy2, axis=0), dx2, axis=1)
            wire_near |= np.roll(np.roll(plant, dy2, axis=0), dx2, axis=1)

    cand_mask = emp & road_near & wire_near
    # Avoid edges
    cand_mask[:2, :] = False
    cand_mask[98:, :] = False
    cand_mask[:, :2] = False
    cand_mask[:, 118:] = False
    # Avoid wire spine row
    cand_mask[wire_row, :] = False
    # Avoid road rows exactly (zones need to be adjacent, not on road)
    cand_mask[road_row_top, :] = False
    cand_mask[road_row_bot, :] = False
    cand_mask[road_row_top2, :] = False
    cand_mask[road_row_bot2, :] = False

    cand_ys, cand_xs = np.where(cand_mask)

    if len(cand_xs) == 0:
        # Extend road further right
        for rx in range(road_end_x, min(road_end_x + 10, WORLD_W - 1)):
            for rrow in [road_row_top, road_row_bot]:
                if 0 <= rrow < WORLD_H and not road[rrow, rx]:
                    return (Tool.ROAD, rx, rrow)
        return None

    # Score: prefer near road rows (not exactly on them), near zone clusters
    zone_near = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    if np.any(zones):
        for dy2 in range(-4, 5):
            for dx2 in range(-4, 5):
                zone_near |= np.roll(np.roll(zones, dy2, axis=0), dx2, axis=1)

    scores = []
    for i in range(len(cand_xs)):
        x, y = int(cand_xs[i]), int(cand_ys[i])
        # Prefer to be adjacent (dist 1-2) to road rows
        dist_road = min(abs(y - road_row_top), abs(y - road_row_bot),
                        abs(y - road_row_top2), abs(y - road_row_bot2))
        near_zone = 5 if zone_near[y, x] else 0
        # Prefer to be in the x-range with infrastructure
        in_range = 3 if (road_start_x <= x <= road_end_x) else 0
        score = near_zone + in_range - dist_road
        scores.append(score)

    scores = np.array(scores)
    max_score = np.max(scores)
    top_mask = scores >= max_score - 0.5
    top_indices = np.where(top_mask)[0]
    pick = top_indices[obs.step % len(top_indices)]
    bx, by = int(cand_xs[pick]), int(cand_ys[pick])
    return (tool, bx, by)

def act(obs, state):
    """
    Variation: builds TWO separate neighborhoods side by side,
    uses a horizontal road spine instead of vertical wire spine,
    and balances RCI zones more aggressively.
    Left cluster: coal plant + zones at x~30, y~50
    Right cluster: coal plant + zones at x~80, y~50
    Both connected by horizontal road at y~50.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    pop = obs.city_pop

    def pick_tool():
        # More balanced: 50% res, 25% com, 25% ind
        ri = res_count / total_zones
        ci = com_count / total_zones
        ii = ind_count / total_zones
        if ii < 0.22:
            return Tool.INDUSTRIAL
        if ci < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Cluster centers
    L_PX, L_PY = 30, 50   # left plant center
    R_PX, R_PY = 82, 50   # right plant center
    ROAD_ROW = 50          # horizontal road spine row

    # Step counter for determinism
    step = obs.step

    # --- Phase 1: Place left coal plant ---
    if not np.any(pm[L_PY-1:L_PY+2, L_PX-1:L_PX+2]):
        return (Tool.COALPOWER, L_PX, L_PY)

    # --- Phase 2: Place right coal plant after enough steps ---
    if step > 20 and not np.any(pm[R_PY-1:R_PY+2, R_PX-1:R_PX+2]):
        return (Tool.COALPOWER, R_PX, R_PY)

    # Build horizontal wire row just above road spine for left cluster
    L_WIRE_ROW = L_PY - 4   # wire row above road
    R_WIRE_ROW = R_PY - 4

    # Wire from left plant upward to wire row
    for wy in range(L_PY - 1, L_WIRE_ROW - 1, -1):
        if in_bounds(L_PX, wy) and (em[wy, L_PX] or wm[wy, L_PX]) and not pm[wy, L_PX]:
            if not wm[wy, L_PX]:
                return (Tool.WIRE, L_PX, wy)

    # Horizontal wire spine for left cluster: columns 15..45 at L_WIRE_ROW
    L_WIRE_MIN, L_WIRE_MAX = 15, 47
    for wx in range(L_WIRE_MIN, L_WIRE_MAX + 1):
        if in_bounds(wx, L_WIRE_ROW) and not wm[L_WIRE_ROW, wx] and em[L_WIRE_ROW, wx] and not pm[L_WIRE_ROW, wx]:
            return (Tool.WIRE, wx, L_WIRE_ROW)

    # Wire from right plant upward to wire row
    for wy in range(R_PY - 1, R_WIRE_ROW - 1, -1):
        if in_bounds(R_PX, wy) and (em[wy, R_PX] or wm[wy, R_PX]) and not pm[wy, R_PX]:
            if not wm[wy, R_PX]:
                return (Tool.WIRE, R_PX, wy)

    # Horizontal wire spine for right cluster: columns 65..97 at R_WIRE_ROW
    R_WIRE_MIN, R_WIRE_MAX = 65, 97
    for wx in range(R_WIRE_MIN, R_WIRE_MAX + 1):
        if in_bounds(wx, R_WIRE_ROW) and not wm[R_WIRE_ROW, wx] and em[R_WIRE_ROW, wx] and not pm[R_WIRE_ROW, wx]:
            return (Tool.WIRE, wx, R_WIRE_ROW)

    # Horizontal road spine at ROAD_ROW for both clusters
    ROAD_MIN_L, ROAD_MAX_L = 15, 47
    ROAD_MIN_R, ROAD_MAX_R = 65, 97
    for rx in range(ROAD_MIN_L, ROAD_MAX_L + 1):
        if in_bounds(rx, ROAD_ROW) and em[ROAD_ROW, rx] and not pm[ROAD_ROW, rx]:
            return (Tool.ROAD, rx, ROAD_ROW)
    for rx in range(ROAD_MIN_R, ROAD_MAX_R + 1):
        if in_bounds(rx, ROAD_ROW) and em[ROAD_ROW, rx] and not pm[ROAD_ROW, rx]:
            return (Tool.ROAD, rx, ROAD_ROW)

    # Vertical road columns flanking each wire spine (2 cols each side)
    # Left cluster: cols 17, 19, 43, 45
    LEFT_VCOLS = [17, 19, 43, 45]
    RIGHT_VCOLS = [67, 69, 91, 93]
    V_ROAD_TOP = 40
    V_ROAD_BOT = 62

    for col in LEFT_VCOLS:
        for ry in range(V_ROAD_TOP, V_ROAD_BOT + 1):
            if in_bounds(col, ry) and em[ry, col] and not pm[ry, col]:
                return (Tool.ROAD, col, ry)

    for col in RIGHT_VCOLS:
        for ry in range(V_ROAD_TOP, V_ROAD_BOT + 1):
            if in_bounds(col, ry) and em[ry, col] and not pm[ry, col]:
                return (Tool.ROAD, col, ry)

    # Build proximity masks for road and wire
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and not zone_tiles[nr, nc]:
                    return False
        return True

    # Place zones where powered+road, within cluster bounds
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Restrict to cluster columns
    region = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    region[:, ROAD_MIN_L:ROAD_MAX_L+1] = True
    region[:, ROAD_MIN_R:ROAD_MAX_R+1] = True
    cand_mask &= region

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prioritize by distance to nearest wire row
        dists_l = np.abs(cys - L_WIRE_ROW)
        dists_r = np.abs(cys - R_WIRE_ROW)
        dists = np.minimum(dists_l, dists_r)
        order = np.argsort(dists)
        step_off = int(step * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 100:
                break

    # Services
    if pop > 100:
        # Fire station near left cluster
        fsx, fsy = 22, 43
        if in_bounds(fsx, fsy) and em[fsy, fsx]:
            return (Tool.FIRESTATION, fsx, fsy)
        # Police near right cluster
        psx, psy = 74, 43
        if in_bounds(psx, psy) and em[psy, psx]:
            return (Tool.POLICESTATION, psx, psy)

    if pop > 300:
        # Extra fire+police
        fsx2, fsy2 = 40, 58
        if in_bounds(fsx2, fsy2) and em[fsy2, fsx2]:
            return (Tool.FIRESTATION, fsx2, fsy2)
        psx2, psy2 = 88, 58
        if in_bounds(psx2, psy2) and em[psy2, psx2]:
            return (Tool.POLICESTATION, psx2, psy2)

    # Connect two clusters with wire bridge at wire row
    BRIDGE_ROW = 46
    for wx in range(ROAD_MAX_L + 1, ROAD_MIN_R):
        if in_bounds(wx, BRIDGE_ROW) and em[BRIDGE_ROW, wx] and not pm[BRIDGE_ROW, wx]:
            return (Tool.WIRE, wx, BRIDGE_ROW)

    # Extend roads if zones exist but coverage thin
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = int(step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 20)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx]:
                    if nbr_wire[ny, nx]:
                        return (Tool.ROAD, nx, ny)

    # Third power plant if pop is large
    if pop > 500:
        t3x, t3y = 56, 50
        if not np.any(pm[t3y-1:t3y+2, t3x-1:t3x+2]):
            area_ok = all(
                in_bounds(t3x+dc, t3y+dr) and (em[t3y+dr, t3x+dc] or pm[t3y+dr, t3x+dc])
                for dr in [-1,0,1] for dc in [-1,0,1]
            )
            if area_ok:
                return (Tool.COALPOWER, t3x, t3y)

    return None

def act(obs, state):
    """
    Redesigned policy: horizontal spine layout instead of vertical.
    - Coal power plant placed on left side
    - Horizontal wire spine extending right from plant
    - Road runs parallel (one row below wire spine)
    - Zones placed above and below the spine at regular intervals
    - Lateral wires connect zones above; lateral roads connect zones below
    - More balanced RES/COM/IND mix
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # Fixed layout parameters
    plant_x, plant_y = 10, 50  # power plant center
    wire_row = 50               # horizontal wire spine row
    road_row = 52               # road row (2 below wire)
    wire_start = plant_x + 4   # wire starts right of plant

    has_plant = np.any(pm)

    # Phase 1: Place coal power plant
    if not has_plant:
        return (Tool.COALPOWER, plant_x, plant_y)

    # Find plant actual location
    plant_positions = list(zip(*np.where(pm)))
    if plant_positions:
        pr, pc = plant_positions[0]
        plant_y, plant_x = pr, pc
        wire_row = plant_y
        road_row = plant_y + 2
        wire_start = plant_x + 4

    wire_row_cols = sorted([c for (r, c) in zip(*np.where(wm)) if r == wire_row])
    road_row_cols = sorted([c for (r, c) in zip(*np.where(rm)) if r == road_row])

    res_positions = list(zip(*np.where(res_m)))
    com_positions = list(zip(*np.where(com_m)))
    ind_positions = list(zip(*np.where(ind_m)))
    all_zone_pos = res_positions + com_positions + ind_positions

    res_count = len(res_positions)
    com_count = len(com_positions)
    ind_count = len(ind_positions)

    # Phase 2: Start wire spine if none
    if not wire_row_cols:
        return (Tool.WIRE, wire_start, wire_row)

    # Phase 3: Extend wire spine horizontally to the right
    target_max_col = min(WORLD_W - 2, plant_x + 50)
    max_wire_col = max(wire_row_cols)
    if max_wire_col < target_max_col:
        nc = max_wire_col + 1
        if nc < WORLD_W:
            return (Tool.WIRE, nc, wire_row)

    # Phase 4: Build road row parallel to wire
    for c in sorted(wire_row_cols):
        if 0 <= road_row < WORLD_H and not rm[road_row, c]:
            return (Tool.ROAD, c, road_row)

    # Helper: check if 3x3 zone area is safe to place
    def zone_area_clear(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if pm[rr, rc]:
                    return False
        return True

    def zone_exists_near(zr, zc):
        return any(abs(zr - pr) <= 1 and abs(zc - pc) <= 1 for (pr, pc) in all_zone_pos)

    # Phase 5: Place zones above and below spine at regular column intervals
    # Zones above wire_row: center at wire_row - 3, connected via lateral wire
    # Zones below road_row: center at road_row + 3, connected via lateral road
    zone_above_row = wire_row - 3
    zone_below_row = road_row + 3

    # Zone columns: every 4 cols starting from wire_start
    zone_cols = list(range(wire_start + 1, target_max_col, 4))

    # Phase 6: Lateral wires connecting spine to above zones
    for zc in zone_cols:
        if zc not in wire_row_cols:
            continue
        # Wire from wire_row upward to zone_above_row - 1
        for r in range(wire_row - 1, zone_above_row - 2, -1):
            if 0 <= r < WORLD_H and not wm[r, zc]:
                if abs(r - plant_y) > 1 or abs(zc - plant_x) > 1:
                    return (Tool.WIRE, zc, r)
        break

    # Phase 7: Lateral roads connecting road_row to below zones
    for zc in zone_cols:
        if zc not in road_row_cols:
            continue
        for r in range(road_row + 1, zone_below_row + 2):
            if 0 <= r < WORLD_H and not rm[r, zc]:
                return (Tool.ROAD, zc, r)
        break

    # Phase 8: Place zones
    # Determine zone type by ratio: 50% RES, 25% COM, 25% IND
    def pick_zone_type():
        total = res_count + com_count + ind_count + 1
        if ind_count * 4 < total:
            return Tool.INDUSTRIAL
        elif com_count * 4 < total:
            return Tool.COMMERCIAL
        else:
            return Tool.RESIDENTIAL

    wire_vert_cols = set()
    for zc in zone_cols:
        # Check wire connectivity to above
        wire_connected = all(wm[r, zc] for r in range(zone_above_row - 1, wire_row))
        if wire_connected:
            wire_vert_cols.add(zc)

    road_vert_cols = set()
    for zc in zone_cols:
        road_connected = all(rm[r, zc] for r in range(road_row, zone_below_row + 2))
        if road_connected:
            road_vert_cols.add(zc)

    for zc in zone_cols:
        # Above zone
        zr = zone_above_row
        if (1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1 and
                zc in wire_vert_cols and
                not zone_exists_near(zr, zc) and zone_area_clear(zr, zc)):
            return (pick_zone_type(), zc, zr)

        # Below zone
        zr = zone_below_row
        if (1 <= zr < WORLD_H - 1 and 1 <= zc < WORLD_W - 1 and
                zc in road_vert_cols and
                not zone_exists_near(zr, zc) and zone_area_clear(zr, zc)):
            # Below zones: more RES and COM
            total = res_count + com_count + ind_count + 1
            if com_count * 3 < total:
                tool = Tool.COMMERCIAL
            else:
                tool = Tool.RESIDENTIAL
            return (tool, zc, zr)

    # Phase 9: Complete missing lateral wires for all zone cols
    for zc in zone_cols:
        if zc not in wire_row_cols:
            continue
        for r in range(wire_row - 1, zone_above_row - 2, -1):
            if 0 <= r < WORLD_H and not wm[r, zc]:
                if abs(r - plant_y) > 1 or abs(zc - plant_x) > 1:
                    return (Tool.WIRE, zc, r)

    # Phase 10: Complete missing lateral roads for all zone cols
    for zc in zone_cols:
        if zc not in road_row_cols:
            continue
        for r in range(road_row + 1, zone_below_row + 2):
            if 0 <= r < WORLD_H and not rm[r, zc]:
                return (Tool.ROAD, zc, r)

    # Phase 11: Second power plant if growing well
    if obs.city_pop > 300:
        nuke_x = plant_x + 55
        nuke_y = plant_y
        if (1 <= nuke_y < WORLD_H - 1 and 1 <= nuke_x < WORLD_W - 1 and
                not np.any(pm[nuke_y - 1:nuke_y + 2, nuke_x - 1:nuke_x + 2])):
            return (Tool.NUCLEARPOWER, nuke_x, nuke_y)

    # Phase 12: Add second row of zones further out if population growing
    if obs.city_pop > 100:
        zone_above2 = wire_row - 7
        zone_below2 = road_row + 7

        # Wire from above zone to zone_above2
        for zc in zone_cols:
            if zc not in wire_vert_cols:
                continue
            for r in range(zone_above_row - 2, zone_above2 - 2, -1):
                if 0 <= r < WORLD_H and not wm[r, zc]:
                    return (Tool.WIRE, zc, r)
            zr2 = zone_above2
            if (1 <= zr2 < WORLD_H - 1 and 1 <= zc < WORLD_W - 1 and
                    not zone_exists_near(zr2, zc) and zone_area_clear(zr2, zc)):
                return (pick_zone_type(), zc, zr2)

        # Road further below
        for zc in zone_cols:
            if zc not in road_vert_cols:
                continue
            for r in range(zone_below_row + 2, zone_below2 + 2):
                if 0 <= r < WORLD_H and not rm[r, zc]:
                    return (Tool.ROAD, zc, r)
            zr2 = zone_below2
            if (1 <= zr2 < WORLD_H - 1 and 1 <= zc < WORLD_W - 1 and
                    not zone_exists_near(zr2, zc) and zone_area_clear(zr2, zc)):
                return (Tool.RESIDENTIAL, zc, zr2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy combining best ideas from both parents:
    - Two-neighborhood layout (from A) with reactive wire/road/zone placement (from B)
    - Reads tile_map every step to decide next placement
    - Adapts to what already exists on the map
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    all_zones = resm | comm | indm
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def area_free(cx, cy):
        if cx < 1 or cx > WORLD_W - 2 or cy < 1 or cy > WORLD_H - 2:
            return False
        for dy in [-1, 0, 1]:
            for dx in [-1, 0, 1]:
                r, c = cy + dy, cx + dx
                if not (0 <= r < WORLD_H and 0 <= c < WORLD_W):
                    return False
                if not em[r, c]:
                    return False
        return True

    def pick_zone():
        t = max(total_zones + 1, 1)
        if res_count / t < 0.40:
            return Tool.RESIDENTIAL
        elif com_count / t < 0.30:
            return Tool.COMMERCIAL
        elif ind_count / t < 0.30:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Neighborhood centers
    # Left neighborhood: plant at ~(35,50), wire spine x=35, roads at x=30,x=40
    # Right neighborhood: plant at ~(80,50), wire spine x=80, roads at x=75,x=85
    neighborhoods = [
        {'target_px': 35, 'target_py': 50, 'wire_col': 35, 'road_l': 30, 'road_r': 40},
        {'target_px': 80, 'target_py': 50, 'wire_col': 80, 'road_l': 75, 'road_r': 85},
    ]

    # Dynamic vertical extent based on population
    if pop < 100:
        v_extent = 10
    elif pop < 300:
        v_extent = 16
    elif pop < 600:
        v_extent = 22
    else:
        v_extent = 28

    cy = WORLD_H // 2  # 50

    # Build neighbor proximity masks for reactive zone placement
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    for nb in neighborhoods:
        tpx = nb['target_px']
        tpy = nb['target_py']
        wc = nb['wire_col']
        rl = nb['road_l']
        rr = nb['road_r']

        spine_top = max(2, cy - v_extent)
        spine_bot = min(WORLD_H - 3, cy + v_extent)

        # Check if a plant exists near this neighborhood
        local_pm = pm[max(0, tpy-6):min(WORLD_H, tpy+7),
                      max(0, tpx-6):min(WORLD_W, tpx+7)]
        has_plant = np.any(local_pm)

        # Step 1: Place plant if missing
        if not has_plant:
            for dy in range(-3, 4):
                for dx in range(-3, 4):
                    npx, npy = tpx + dx, tpy + dy
                    if area_free(npx, npy):
                        return (Tool.COALPOWER, npx, npy)
            continue

        # Find actual plant location for this neighborhood
        plant_rows, plant_cols = np.where(pm)
        near = [(plant_rows[i], plant_cols[i]) for i in range(len(plant_rows))
                if abs(int(plant_cols[i]) - tpx) <= 12 and abs(int(plant_rows[i]) - tpy) <= 12]
        if near:
            plant_cy = int(np.mean([r for r, c in near]))
            plant_cx = int(np.mean([c for r, c in near]))
        else:
            plant_cy, plant_cx = tpy, tpx

        # Step 2: Extend wire spine vertically from plant
        wire_in_col = [r for r in range(WORLD_H) if wm[r, wc]]

        if not wire_in_col:
            # Start wire near plant, adjacent to it
            for dy in range(0, 6):
                for nr in [plant_cy + dy, plant_cy - dy]:
                    if spine_top <= nr <= spine_bot and in_bounds(wc, nr):
                        if em[nr, wc] and not pm[nr, wc]:
                            return (Tool.WIRE, wc, nr)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)

            # Extend downward
            if max_wr < spine_bot:
                nr = max_wr + 1
                if in_bounds(wc, nr) and not pm[nr, wc] and (em[nr, wc] or wm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

            # Extend upward
            if min_wr > spine_top:
                nr = min_wr - 1
                if in_bounds(wc, nr) and not pm[nr, wc] and (em[nr, wc] or wm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

            # Step 3: Build road rows reactively at fixed offsets
            road_rows = [cy - 5, cy + 5]
            road_span_start = min(rl - 2, wc - 10)
            road_span_end = max(rr + 2, wc + 10)

            for rrow in road_rows:
                if 0 < rrow < WORLD_H:
                    for rc in range(road_span_start, road_span_end + 1):
                        if in_bounds(rc, rrow) and em[rrow, rc] and not pm[rrow, rc]:
                            return (Tool.ROAD, rc, rrow)

            # Step 4: Vertical road connectors between road rows
            for rc in [rl, rr]:
                if in_bounds(rc, 0):
                    for ry in range(min(road_rows), max(road_rows) + 1):
                        if in_bounds(rc, ry) and em[ry, rc] and not pm[ry, rc]:
                            return (Tool.ROAD, rc, ry)

            # Step 5: Extend lateral wires from spine to road columns
            wire_set = set(wire_in_col)
            for wr in sorted(wire_in_col):
                if not (spine_top <= wr <= spine_bot):
                    continue
                # Wire leftward to road_l
                for wcc in range(wc - 1, rl - 4, -1):
                    if not in_bounds(wcc, wr):
                        break
                    if wm[wr, wcc] or pm[wr, wcc]:
                        break
                    if rm[wr, wcc]:
                        break
                    if em[wr, wcc]:
                        return (Tool.WIRE, wcc, wr)
                    else:
                        break
                # Wire rightward to road_r
                for wcc in range(wc + 1, rr + 4):
                    if not in_bounds(wcc, wr):
                        break
                    if wm[wr, wcc] or pm[wr, wcc]:
                        break
                    if rm[wr, wcc]:
                        break
                    if em[wr, wcc]:
                        return (Tool.WIRE, wcc, wr)
                    else:
                        break

            # Step 6: Reactive zone placement near roads + wires
            cand_mask = em & nbr_road & nbr_wire
            cand_mask[0:2, :] = False
            cand_mask[WORLD_H-2:, :] = False
            cand_mask[:, 0:2] = False
            cand_mask[:, WORLD_W-2:] = False
            # Restrict to this neighborhood's x range
            x_left = max(0, rl - 6)
            x_right = min(WORLD_W, rr + 7)
            y_top = max(0, spine_top)
            y_bot = min(WORLD_H, spine_bot + 1)
            local_cand = cand_mask.copy()
            local_cand[:, :x_left] = False
            local_cand[:, x_right:] = False
            local_cand[:y_top, :] = False
            local_cand[y_bot:, :] = False

            cys_arr, cxs_arr = np.where(local_cand)
            if len(cxs_arr) > 0:
                dists = np.abs(cxs_arr - wc) + np.abs(cys_arr - cy)
                sort_idx = np.argsort(dists)
                for i in range(min(len(cxs_arr), 80)):
                    k = int(sort_idx[i])
                    zx, zy = int(cxs_arr[k]), int(cys_arr[k])
                    if area_free(zx, zy):
                        return (pick_zone(), zx, zy)

    # Step 7: Second coal plant if zones growing and need more power
    if pop > 200 or total_zones > 12:
        plant_count = max(1, int(np.sum(pm)) // 9)
        if plant_count < 2:
            for tpx, tpy in [(55, 50), (35, 50), (80, 50)]:
                local_pm = pm[max(0, tpy-8):min(WORLD_H, tpy+9),
                              max(0, tpx-8):min(WORLD_W, tpx+9)]
                if not np.any(local_pm):
                    for dy in range(-3, 4):
                        for dx in range(-3, 4):
                            npx, npy = tpx + dx, tpy + dy
                            if area_free(npx, npy):
                                return (Tool.COALPOWER, npx, npy)

    # Step 8: Wire bridge between neighborhoods if both have plants
    if np.sum(pm) > 9:  # more than one plant worth of tiles
        bridge_y = cy
        # Connect wire from x=35+1 to x=80-1
        for bx in range(36, 80):
            if in_bounds(bx, bridge_y) and em[bridge_y, bx] and not pm[bridge_y, bx]:
                # Only if there's wire on both sides eventually
                left_wire = np.any(wm[bridge_y, :36])
                right_wire = np.any(wm[bridge_y, 80:])
                if left_wire or right_wire:
                    return (Tool.WIRE, bx, bridge_y)

    # Step 9: Services
    if pop > 200:
        for sx, sy in [(35, 43), (80, 43), (35, 57), (80, 57)]:
            if area_free(sx, sy):
                near = tm[max(0, sy-6):min(WORLD_H, sy+7),
                          max(0, sx-6):min(WORLD_W, sx+7)]
                # Check no existing service building
                if not np.any((near >= 600) & (near <= 800)):
                    if pop > 300:
                        return (Tool.POLICESTATION, sx, sy)
                    return (Tool.FIRESTATION, sx, sy)

    # Step 10: Fallback - extend roads from any existing road toward wire
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = int(obs.step)
        for idx in range(min(len(road_xs_arr), 30)):
            k = (step_k * 7 + idx * 13) % len(road_xs_arr)
            rx = int(road_xs_arr[k])
            ry = int(road_ys_arr[k])
            if nbr_wire[ry, rx]:
                for dy, dx in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx2, ny2 = rx + dx, ry + dy
                    if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                        return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Improved city builder with denser grid layout.
    - Uses a grid-based zone placement with roads between zones
    - Better wire connectivity from power plants
    - More balanced zone mix with explicit ratios
    - Two clusters with proper road connections
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Use state to track build phase and progress
    if 'phase' not in state:
        state['phase'] = 0
        state['wire_idx'] = 0
        state['road_idx'] = 0
        state['zone_idx'] = 0

    # Single cluster centered at (60, 50) - middle of map
    # Power plant at (60, 30) - top of cluster
    # Grid of zones with roads between them

    P1X, P1Y = 25, 40   # Left power plant
    P2X, P2Y = 90, 40   # Right power plant

    plant_ys, plant_xs = np.where(pm)
    plant_list = list(zip(plant_xs.tolist(), plant_ys.tolist()))

    has_plant1 = any(abs(px - P1X) < 6 and abs(py - P1Y) < 6 for px, py in plant_list)
    has_plant2 = any(abs(px - P2X) < 6 and abs(py - P2Y) < 6 for px, py in plant_list)

    # Phase 1: ensure power plants exist
    if not has_plant1:
        return (Tool.COALPOWER, P1X, P1Y)
    if not has_plant2:
        return (Tool.COALPOWER, P2X, P2Y)

    # Count zones for balanced placement
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        # Target: 50% res, 30% com, 20% ind
        t = max(total_zones, 1)
        if ind_count / t < 0.18:
            return Tool.INDUSTRIAL
        if com_count / t < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Wire plan: from each plant, run horizontal wire toward center
    # then vertical spines to cover the zone area
    # Left cluster: x=20..40, y=35..65
    # Right cluster: x=75..95, y=35..65

    wire_targets = []
    # Left cluster wires - horizontal from plant
    for x in range(P1X - 8, P1X + 10):
        wire_targets.append((x, P1Y))
    # Left cluster - vertical spines at x=20, 24, 28, 32, 36, 40
    for x in [20, 24, 28, 32, 36, 40]:
        for y in range(35, 66):
            wire_targets.append((x, y))
    # Horizontal wire connectors at y=35, 45, 55, 65
    for y in [35, 45, 55, 65]:
        for x in range(18, 43):
            wire_targets.append((x, y))

    # Right cluster wires
    for x in range(P2X - 9, P2X + 9):
        wire_targets.append((x, P2Y))
    for x in [75, 79, 83, 87, 91, 95]:
        for y in range(35, 66):
            wire_targets.append((x, y))
    for y in [35, 45, 55, 65]:
        for x in range(73, 98):
            wire_targets.append((x, y))

    # Horizontal wire spine connecting both clusters
    for x in range(P1X, P2X + 1):
        wire_targets.append((x, P1Y))

    for (wx, wy) in wire_targets:
        if not in_bounds(wx, wy):
            continue
        if bool(wm[wy, wx]) or bool(pm[wy, wx]):
            continue
        # Only place wire if adjacent to existing power
        adj_power = False
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx2, ny2 = wx+ddx, wy+ddy
            if in_bounds(nx2, ny2) and (bool(pm[ny2, nx2]) or bool(wm[ny2, nx2])):
                adj_power = True
                break
        if adj_power and bool(em[wy, wx]):
            return (Tool.WIRE, wx, wy)

    # Road plan: grid roads for both clusters
    # Left cluster roads at x=22, 26, 30, 34, 38 (between zone columns)
    # and y=38, 42, 46, 50, 54, 58, 62 (between zone rows)
    road_targets = []

    # Left cluster - vertical roads
    for x in [22, 26, 30, 34, 38]:
        for y in range(36, 65):
            road_targets.append((x, y))
    # Left cluster - horizontal roads
    for y in [38, 42, 46, 50, 54, 58, 62]:
        for x in range(19, 42):
            road_targets.append((x, y))

    # Right cluster - vertical roads
    for x in [77, 81, 85, 89, 93]:
        for y in range(36, 65):
            road_targets.append((x, y))
    # Right cluster - horizontal roads
    for y in [38, 42, 46, 50, 54, 58, 62]:
        for x in range(74, 97):
            road_targets.append((x, y))

    # Connecting highway between clusters at y=50
    for x in range(40, 78):
        road_targets.append((x, 50))

    for (rx, ry) in road_targets:
        if not in_bounds(rx, ry):
            continue
        if bool(rm[ry, rx]):
            continue
        if bool(pm[ry, rx]) or bool(wm[ry, rx]):
            continue
        adj_road = False
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx2, ny2 = rx+ddx, ry+ddy
            if in_bounds(nx2, ny2) and bool(rm[ny2, nx2]):
                adj_road = True
                break
        adj_plant = False
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1),(2,0),(-2,0),(0,2),(0,-2),
                         (3,0),(-3,0),(0,3),(0,-3)]:
            nx2, ny2 = rx+ddx, ry+ddy
            if in_bounds(nx2, ny2) and bool(pm[ny2, nx2]):
                adj_plant = True
                break
        if (adj_road or adj_plant) and bool(em[ry, rx]):
            return (Tool.ROAD, rx, ry)

    # Phase 4: place zones near roads AND wires (power)
    # Build neighbor masks for road proximity
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_mask = resm | comm | indm
    cand = em & nbr_road & nbr_power
    cand[0:2, :] = False
    cand[WORLD_H-2:, :] = False
    cand[:, 0:2] = False
    cand[:, WORLD_W-2:] = False

    # Prefer zones in cluster areas (prioritize by distance to cluster centers)
    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        # Score candidates: prefer those inside cluster bounds
        key = int(obs.step * 13 + int(obs.city_pop) * 7 + 1) % len(cxs)
        tried = 0
        for offset in range(min(len(cxs), 120)):
            k = (key + offset * 7) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            # Check if in cluster zones
            in_left = (18 <= zx <= 41) and (36 <= zy <= 64)
            in_right = (73 <= zx <= 96) and (36 <= zy <= 64)
            if not (in_left or in_right):
                tried += 1
                if tried < 60:
                    continue
            # Check 3x3 clearance
            ok = True
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    ny2, nx2 = zy + dr, zx + dc
                    if not in_bounds(nx2, ny2):
                        ok = False; break
                    tile_ok = bool(em[ny2, nx2]) or bool(zone_mask[ny2, nx2])
                    if not tile_ok:
                        ok = False; break
                if not ok:
                    break
            if ok:
                return (pick_tool(), zx, zy)

    # Services when population warrants
    if obs.city_pop > 300:
        for fx, fy in [(P1X + 5, P1Y + 12), (P2X - 5, P2Y + 12)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 500:
        for fx, fy in [(P1X + 5, P1Y - 8), (P2X - 5, P2Y - 8)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.POLICESTATION, fx, fy)

    # Fallback: extend road from existing frontier
    rys, rxs = np.where(rm)
    if len(rxs) > 0:
        k2 = int(obs.step * 11) % len(rxs)
        rx2, ry2 = int(rxs[k2]), int(rys[k2])
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx2, ny2 = rx2+ddx, ry2+ddy
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wys, wxs = np.where(wm)
    if len(wxs) > 0:
        k3 = int(obs.step * 7) % len(wxs)
        wx2, wy2 = int(wxs[k3]), int(wys[k3])
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx2, ny2 = wx2+ddx, wy2+ddy
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy. Reads tile_map each step and adapts.
    Key changes from parent:
    - Uses horizontal road/wire layout instead of vertical spine
    - Places zones on both sides of road more aggressively
    - More power plants placed earlier
    - Services placed more proactively
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Phase 1: Place first coal plant at a good central location
    if not np.any(pm):
        return (Tool.COALPOWER, 60, 50)

    # Find plant center
    plant_ys, plant_xs = np.where(pm)
    px = int(np.median(plant_xs))
    py = int(np.median(plant_ys))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Horizontal wire spine row, extending from plant ---
    wire_row = py + 2  # wire runs horizontally 2 below plant center
    wire_row = max(3, min(WORLD_H - 3, wire_row))

    pop_factor = min(35, obs.city_pop // 15)
    lmin = max(3, px - 18 - pop_factor)
    lmax = min(WORLD_W - 3, px + 18 + pop_factor)

    wire_in_row = [c for c in range(WORLD_W) if 0 <= wire_row < WORLD_H and wm[wire_row, c]]

    if not wire_in_row:
        # Seed wire adjacent to plant
        for dc in range(-2, 3):
            nc = px + dc
            if in_bounds(nc, wire_row) and (em[wire_row, nc] or wm[wire_row, nc]) and not pm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)
    else:
        min_wc = min(wire_in_row)
        max_wc = max(wire_in_row)
        if max_wc < lmax:
            nc = max_wc + 1
            if in_bounds(nc, wire_row) and (em[wire_row, nc] or wm[wire_row, nc]) and not pm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)
        if min_wc > lmin:
            nc = min_wc - 1
            if in_bounds(nc, wire_row) and (em[wire_row, nc] or wm[wire_row, nc]) and not pm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # --- Road rows flanking wire spine (above and below) ---
    road_row_above = wire_row - 1
    road_row_below = wire_row + 1

    for wc in wire_in_row:
        if in_bounds(wc, road_row_above) and em[road_row_above, wc]:
            return (Tool.ROAD, wc, road_row_above)
        if in_bounds(wc, road_row_below) and em[road_row_below, wc]:
            return (Tool.ROAD, wc, road_row_below)

    # --- Build proximity masks for zone placement ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and not zone_tiles[nr, nc]:
                    return False
        return True

    # Candidate zone centers: near road and wire
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prefer zones close to the wire row center
        dists = np.abs(cys - wire_row) * 2 + np.abs(cxs - px)
        order = np.argsort(dists)
        step_off = int(obs.step * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 80:
                break

    # --- Extend roads near wire to fill gaps ---
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 20)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx] and nbr_wire[ny, nx]:
                    return (Tool.ROAD, nx, ny)

    # --- Second power plant earlier (when 6+ zones) ---
    if total_zones > 6 or obs.city_pop > 150:
        # Place second plant above the wire row
        p2x = px
        p2y = py - 22
        p2y = max(3, p2y)
        if in_bounds(p2x, p2y):
            nearby_plant = any(
                in_bounds(p2x + dx, p2y + dy) and pm[p2y + dy, p2x + dx]
                for dy in range(-6, 7) for dx in range(-6, 7)
            )
            if not nearby_plant and em[p2y, p2x]:
                return (Tool.COALPOWER, p2x, p2y)
            # Wire vertical bridge from spine up to second plant
            for wr in range(py - 1, p2y + 2, -1):
                if in_bounds(px, wr) and em[wr, px]:
                    return (Tool.WIRE, px, wr)
            # Horizontal wire spine above
            wire_row2 = p2y + 2
            if 0 <= wire_row2 < WORLD_H:
                for wc in wire_in_row:
                    if in_bounds(wc, wire_row2) and em[wire_row2, wc]:
                        return (Tool.WIRE, wc, wire_row2)

    # --- Third plant to the right for further expansion ---
    if total_zones > 18 or obs.city_pop > 500:
        p3x = px + 25
        p3y = py
        if in_bounds(p3x, p3y):
            nearby_plant = any(
                in_bounds(p3x + dx, p3y + dy) and pm[p3y + dy, p3x + dx]
                for dy in range(-6, 7) for dx in range(-6, 7)
            )
            if not nearby_plant and em[p3y, p3x]:
                return (Tool.COALPOWER, p3x, p3y)
            # Wire horizontal from spine to third plant
            for wc in range(px + 2, p3x - 1):
                if in_bounds(wc, wire_row) and em[wire_row, wc]:
                    return (Tool.WIRE, wc, wire_row)

    # --- Services when pop is high enough ---
    if obs.city_pop > 80:
        fsx, fsy = px - 10, py - 4
        if in_bounds(fsx, fsy) and em[fsy, fsx]:
            return (Tool.FIRESTATION, fsx, fsy)
    if obs.city_pop > 120:
        psx, psy = px + 10, py - 4
        if in_bounds(psx, psy) and em[psy, psx]:
            return (Tool.POLICESTATION, psx, psy)

    # --- Expand wire laterally to reach new areas ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 15)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = wx + dx2, wy + dy2
                if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                    return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy.
    Reads current map each step to decide next action.
    Strategy:
    - Place coal plant first
    - Build wire spine rightward from plant, then vertical
    - Build parallel road column
    - Place zones with wire/road connections
    - Expand as population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # Use a more centered layout
    plant_cx, plant_cy = 60, 50

    # Wire spine runs vertically at column wire_col
    wire_col = plant_cx + 3   # col 63
    road_col = wire_col + 2   # col 65

    # Zone columns flanking road and wire
    left_zone_col = wire_col - 3   # col 60
    right_zone_col = road_col + 3  # col 68

    has_plant = np.any(pm)

    # Phase 1: Place coal power plant
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Gather current state from map
    wire_positions = set(zip(*np.where(wm))) if np.any(wm) else set()
    road_positions = set(zip(*np.where(rm))) if np.any(rm) else set()
    res_positions = set(zip(*np.where(res_m))) if np.any(res_m) else set()
    com_positions = set(zip(*np.where(com_m))) if np.any(com_m) else set()
    ind_positions = set(zip(*np.where(ind_m))) if np.any(ind_m) else set()
    all_zones = res_positions | com_positions | ind_positions

    res_count = len(res_positions)
    com_count = len(com_positions)
    ind_count = len(ind_positions)
    total_zones = res_count + com_count + ind_count

    # Dynamic vertical span based on population
    base_span = 12
    extra_span = min(30, obs.city_pop // 30)
    target_span = base_span + extra_span
    tmin = max(2, plant_cy - target_span)
    tmax = min(WORLD_H - 3, plant_cy + target_span)

    # Phase 2: Ensure wire connects plant to wire_col
    # First build horizontal wire bridge from plant to wire_col at plant_cy
    plant_row = plant_cy
    for wc in range(plant_cx + 2, wire_col + 1):
        if 0 <= wc < WORLD_W and em[plant_row, wc]:
            return (Tool.WIRE, wc, plant_row)

    # Wire spine vertical extension
    wire_rows_in_col = sorted(r for (r, c) in wire_positions if c == wire_col)
    road_rows_in_col = sorted(r for (r, c) in road_positions if c == road_col)
    road_rows_set = set(road_rows_in_col)

    # Phase 3: Extend wire spine vertically
    if not wire_rows_in_col:
        # Place first wire at plant row in wire_col
        if em[plant_cy, wire_col]:
            return (Tool.WIRE, wire_col, plant_cy)
        return None
    else:
        min_wr = min(wire_rows_in_col)
        max_wr = max(wire_rows_in_col)

        # Extend downward
        if max_wr < tmax:
            nr = max_wr + 1
            if 0 < nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if min_wr > tmin:
            nr = min_wr - 1
            if 0 <= nr < WORLD_H and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    if not wire_rows_in_col:
        return None

    wire_rows_set = set(wire_rows_in_col)

    # Phase 4: Build road column matching wire coverage
    for wr in sorted(wire_rows_in_col, key=lambda r: abs(r - plant_cy)):
        if wr not in road_rows_set and 0 <= road_col < WORLD_W:
            if em[wr, road_col]:
                return (Tool.ROAD, road_col, wr)

    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def already_zone_nearby(zr, zc, zones):
        return any(abs(zr - pr) <= 2 and abs(zc - pc) <= 2 for (pr, pc) in zones)

    def pick_zone_type():
        if res_count == 0:
            return Tool.RESIDENTIAL
        ratio_ind = ind_count / max(res_count, 1)
        ratio_com = com_count / max(res_count, 1)
        if ratio_ind < 0.3:
            return Tool.INDUSTRIAL
        elif ratio_com < 0.3:
            return Tool.COMMERCIAL
        else:
            return Tool.RESIDENTIAL

    # Phase 5: Place lateral wires from spine toward left zone column
    for wr in sorted(wire_rows_in_col, key=lambda r: abs(r - plant_cy)):
        road_nearby = any(abs(wr - rr) <= 2 for rr in road_rows_set)
        if not road_nearby:
            continue
        # Check if left zone placement is viable, if so place lateral wire
        for wc in range(wire_col - 1, max(left_zone_col - 2, 0), -1):
            if 0 <= wc < WORLD_W and em[wr, wc]:
                # Only fill gaps - don't over-wire
                if not wm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
            elif not em[wr, wc] and not wm[wr, wc]:
                break  # blocked

    # Phase 6: Place zones on both sides
    for zr in sorted(wire_rows_in_col, key=lambda r: abs(r - plant_cy)):
        road_nearby = any(abs(zr - rr) <= 2 for rr in road_rows_set)
        if not road_nearby:
            continue

        for zc in [left_zone_col, right_zone_col]:
            if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                if not already_zone_nearby(zr, zc, all_zones) and zone_area_free(zr, zc):
                    return (pick_zone_type(), zc, zr)

    # Phase 7: Lateral roads to right zone column
    for wr in sorted(wire_rows_in_col, key=lambda r: abs(r - plant_cy)):
        for rc in range(road_col + 1, min(right_zone_col + 2, WORLD_W)):
            if 0 <= rc < WORLD_W and em[wr, rc]:
                return (Tool.ROAD, rc, wr)

    # Phase 8: Second cluster to the right when pop >= 150
    if obs.city_pop >= 150:
        wire_col2 = road_col + 9    # col 74
        road_col2 = wire_col2 + 2   # col 76
        left_zone_col2 = wire_col2 - 3   # col 71
        right_zone_col2 = road_col2 + 3  # col 79

        wire_rows2 = sorted(r for (r, c) in wire_positions if c == wire_col2)
        road_rows2 = set(r for (r, c) in road_positions if c == road_col2)

        if not wire_rows2:
            # Build horizontal bridge at plant_cy from wire_col to wire_col2
            for wc in range(wire_col + 1, wire_col2 + 1):
                if em[plant_cy, wc]:
                    return (Tool.WIRE, wc, plant_cy)
        else:
            min_wr2 = min(wire_rows2)
            max_wr2 = max(wire_rows2)
            if max_wr2 < tmax:
                nr = max_wr2 + 1
                if 0 < nr < WORLD_H and em[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > tmin:
                nr = min_wr2 - 1
                if 0 <= nr < WORLD_H and em[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)

            # Road2
            for wr in sorted(wire_rows2, key=lambda r: abs(r - plant_cy)):
                if wr not in road_rows2 and 0 <= road_col2 < WORLD_W:
                    if em[wr, road_col2]:
                        return (Tool.ROAD, road_col2, wr)

            # Lateral wires to left zone2
            for wr in sorted(wire_rows2, key=lambda r: abs(r - plant_cy)):
                road_nearby2 = any(abs(wr - rr) <= 2 for rr in road_rows2)
                if not road_nearby2:
                    continue
                for wc in range(wire_col2 - 1, max(left_zone_col2 - 2, 0), -1):
                    if 0 <= wc < WORLD_W and em[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    elif not em[wr, wc] and not wm[wr, wc]:
                        break

            # Zones around second cluster
            for zr in sorted(wire_rows2, key=lambda r: abs(r - plant_cy)):
                road_nearby2 = any(abs(zr - rr) <= 2 for rr in road_rows2)
                if not road_nearby2:
                    continue
                for zc in [left_zone_col2, right_zone_col2]:
                    if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                        if not already_zone_nearby(zr, zc, all_zones) and zone_area_free(zr, zc):
                            return (pick_zone_type(), zc, zr)

            # Lateral roads to right zone2
            for wr in sorted(wire_rows2, key=lambda r: abs(r - plant_cy)):
                for rc in range(road_col2 + 1, min(right_zone_col2 + 2, WORLD_W)):
                    if 0 <= rc < WORLD_W and em[wr, rc]:
                        return (Tool.ROAD, rc, wr)

    # Phase 9: Third cluster to the left when pop >= 300
    if obs.city_pop >= 300:
        wire_col3 = wire_col - 9    # col 54
        road_col3 = wire_col3 - 2   # col 52
        left_zone_col3 = road_col3 - 3  # col 49
        right_zone_col3 = wire_col3 + 3  # col 57

        wire_rows3 = sorted(r for (r, c) in wire_positions if c == wire_col3)
        road_rows3 = set(r for (r, c) in road_positions if c == road_col3)

        if not wire_rows3:
            for wc in range(wire_col - 1, wire_col3 - 1, -1):
                if em[plant_cy, wc]:
                    return (Tool.WIRE, wc, plant_cy)
        else:
            min_wr3 = min(wire_rows3)
            max_wr3 = max(wire_rows3)
            if max_wr3 < tmax:
                nr = max_wr3 + 1
                if 0 < nr < WORLD_H and em[nr, wire_col3]:
                    return (Tool.WIRE, wire_col3, nr)
            if min_wr3 > tmin:
                nr = min_wr3 - 1
                if 0 <= nr < WORLD_H and em[nr, wire_col3]:
                    return (Tool.WIRE, wire_col3, nr)

            for wr in sorted(wire_rows3, key=lambda r: abs(r - plant_cy)):
                if wr not in road_rows3 and 0 <= road_col3 < WORLD_W:
                    if em[wr, road_col3]:
                        return (Tool.ROAD, road_col3, wr)

            for wr in sorted(wire_rows3, key=lambda r: abs(r - plant_cy)):
                road_nearby3 = any(abs(wr - rr) <= 2 for rr in road_rows3)
                if not road_nearby3:
                    continue
                for wc in range(wire_col3 + 1, min(right_zone_col3 + 2, WORLD_W)):
                    if 0 <= wc < WORLD_W and em[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    elif not em[wr, wc] and not wm[wr, wc]:
                        break

            for zr in sorted(wire_rows3, key=lambda r: abs(r - plant_cy)):
                road_nearby3 = any(abs(zr - rr) <= 2 for rr in road_rows3)
                if not road_nearby3:
                    continue
                for zc in [left_zone_col3, right_zone_col3]:
                    if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                        if not already_zone_nearby(zr, zc, all_zones) and zone_area_free(zr, zc):
                            return (pick_zone_type(), zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Each step reads tile_map to find existing infrastructure and extends it
    - Layout: coal plant center, wire spine grows vertically from plant,
      roads flank the wire, zones fill areas adjacent to roads+wire
    - Adapts every step based on what's actually present on map
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Phase 1: Place first coal plant if missing ---
    if not np.any(pm):
        return (Tool.COALPOWER, 58, 50)

    # Find plant center from actual tile_map
    plant_ys, plant_xs = np.where(pm)
    px = int(np.median(plant_xs))
    py = int(np.median(plant_ys))

    # Zone counts for ratio-based selection
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.22:
            return Tool.INDUSTRIAL
        if c_r < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Phase 2: Grow wire spine vertically from plant ---
    # Wire spine at px+2 (right side of plant footprint)
    wire_col = px + 2
    wire_col = max(1, min(WORLD_W - 2, wire_col))

    pop_factor = min(35, obs.city_pop // 10)
    tmin = max(2, py - 18 - pop_factor)
    tmax = min(WORLD_H - 3, py + 18 + pop_factor)

    wire_in_col = [r for r in range(WORLD_H) if 0 <= wire_col < WORLD_W and wm[r, wire_col]]

    if not wire_in_col:
        # Seed first wire adjacent to plant
        for dy in range(-2, 3):
            ny = py + dy
            if in_bounds(wire_col, ny) and (em[ny, wire_col] or wm[ny, wire_col]) and not pm[ny, wire_col]:
                return (Tool.WIRE, wire_col, ny)
        return (Tool.WIRE, wire_col, py)
    else:
        min_wr = min(wire_in_col)
        max_wr = max(wire_in_col)
        # Extend downward first
        if max_wr < tmax:
            nr = max_wr + 1
            if in_bounds(wire_col, nr) and (em[nr, wire_col] or wm[nr, wire_col]) and not pm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if min_wr > tmin:
            nr = min_wr - 1
            if in_bounds(wire_col, nr) and (em[nr, wire_col] or wm[nr, wire_col]) and not pm[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    # --- Phase 3: Road columns flanking wire spine ---
    # Two road lanes: one each side of wire
    road_col_r = wire_col + 1
    road_col_l = wire_col - 1
    road_col_r = max(1, min(WORLD_W - 2, road_col_r))
    road_col_l = max(1, min(WORLD_W - 2, road_col_l))

    # Build roads adjacent to existing wire rows
    wire_set = set(wire_in_col)
    # Sort by proximity to plant center
    sorted_wire = sorted(wire_set, key=lambda y: abs(y - py))

    for wy in sorted_wire:
        if in_bounds(road_col_r, wy) and em[wy, road_col_r]:
            return (Tool.ROAD, road_col_r, wy)
        if in_bounds(road_col_l, wy) and em[wy, road_col_l]:
            return (Tool.ROAD, road_col_l, wy)

    # --- Phase 4: Build proximity maps for smart zone placement ---
    # Near-road mask: any cell within 2 tiles of a road
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Near-wire/plant mask
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        # 3x3 footprint must be all empty or zone
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not in_bounds(nc2, nr2):
                    return False
                if not em[nr2, nc2] and not zone_tiles[nr2, nc2]:
                    return False
        return True

    # --- Phase 5: Place zones near roads and wire ---
    cand_mask = em & nbr_road & nbr_wire
    # Keep away from borders
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prioritize by closeness to wire spine (more likely to be powered)
        dists = np.abs(cxs - wire_col) + np.abs(cys - py) * 0.3
        order = np.argsort(dists)
        # Vary starting offset per step to avoid getting stuck
        step_off = int(obs.step * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 100:
                break

    # --- Phase 6: Extend roads to fill coverage gaps ---
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 30)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx] and nbr_wire[ny, nx]:
                    return (Tool.ROAD, nx, ny)

    # --- Phase 7: Second power plant when city grows ---
    if total_zones > 8 or obs.city_pop > 200:
        p2x = px + 22
        p2y = py
        p2x = max(2, min(WORLD_W - 3, p2x))
        p2y = max(2, min(WORLD_H - 3, p2y))

        # Check no plant already nearby
        nearby_plant = np.any(pm[max(0, p2y-4):min(WORLD_H, p2y+5),
                                  max(0, p2x-4):min(WORLD_W, p2x+5)])
        if not nearby_plant:
            # Build horizontal wire bridge first
            wire_col2 = p2x - 2
            # Find if bridge exists
            bridge_done = False
            for wbx in range(wire_col + 1, wire_col2):
                if in_bounds(wbx, py) and wm[py, wbx]:
                    continue
                elif in_bounds(wbx, py) and em[py, wbx]:
                    return (Tool.WIRE, wbx, py)
                else:
                    break
            else:
                bridge_done = True

            if bridge_done or (in_bounds(wire_col2, py) and (wm[py, wire_col2] or em[py, wire_col2])):
                # Place second plant
                if all(in_bounds(p2x + dc, p2y + dr) and em[p2y + dr, p2x + dc]
                       for dr in [-1, 0, 1] for dc in [-1, 0, 1]):
                    return (Tool.COALPOWER, p2x, p2y)
                # Otherwise extend wire spine for second cluster
                if in_bounds(wire_col2, py) and em[py, wire_col2]:
                    return (Tool.WIRE, wire_col2, py)

    # --- Phase 8: Services for population health ---
    if obs.city_pop > 120:
        fsx, fsy = px - 10, py - 8
        fsx = max(2, min(WORLD_W - 3, fsx))
        fsy = max(2, min(WORLD_H - 3, fsy))
        if in_bounds(fsx, fsy) and all(
            in_bounds(fsx + dc, fsy + dr) and em[fsy + dr, fsx + dc]
            for dr in [-1, 0, 1] for dc in [-1, 0, 1]
        ):
            return (Tool.FIRESTATION, fsx, fsy)

    if obs.city_pop > 200:
        psx, psy = px - 10, py + 8
        psx = max(2, min(WORLD_W - 3, psx))
        psy = max(2, min(WORLD_H - 3, psy))
        if in_bounds(psx, psy) and all(
            in_bounds(psx + dc, psy + dr) and em[psy + dr, psx + dc]
            for dr in [-1, 0, 1] for dc in [-1, 0, 1]
        ):
            return (Tool.POLICESTATION, psx, psy)

    # --- Phase 9: Expand wire laterally to open new zone areas ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 20)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = wx + dx2, wy + dy2
                if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                    return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy v3:
    - Reads tile_map each step to find existing infrastructure
    - Extends wire frontier from plant outward (BFS-style, one tile per step)
    - Roads placed adjacent to wire
    - Zones placed where road+wire coverage exists
    - Multiple power plants as city grows
    - Services and stadiums for late-game boosts
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Place first coal plant if missing ---
    if not np.any(pm):
        return (Tool.COALPOWER, 55, 45)

    # Find plant center(s)
    plant_ys, plant_xs = np.where(pm)
    px = int(np.median(plant_xs))
    py = int(np.median(plant_ys))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Build wire frontier: extend wire adjacent to existing wire/plant ---
    # Priority: extend outward from power sources
    # Build a cross-shaped wire network, then branch out

    # Find all wire+plant tiles
    powered_tiles = wm | pm
    pow_ys, pow_xs = np.where(powered_tiles)

    # Scale extent with population
    pop_ext = min(40, max(12, obs.city_pop // 15))
    target_x_min = max(2, px - pop_ext)
    target_x_max = min(WORLD_W - 3, px + pop_ext)
    target_y_min = max(2, py - pop_ext)
    target_y_max = min(WORLD_H - 3, py + pop_ext)

    # Try to extend wire to uncovered empty tiles adjacent to powered tiles
    # Use step as offset to vary which tile we extend from
    if len(pow_xs) > 0:
        step_k = int(obs.step * 7) % len(pow_xs)
        tried = 0
        for offset in range(len(pow_xs)):
            k = (step_k + offset) % len(pow_xs)
            wx, wy = int(pow_xs[k]), int(pow_ys[k])
            # Prefer extending in directions that reach target area
            dirs = []
            if wx > target_x_min:
                dirs.append((-1, 0))
            if wx < target_x_max:
                dirs.append((1, 0))
            if wy > target_y_min:
                dirs.append((0, -1))
            if wy < target_y_max:
                dirs.append((0, 1))
            # Shuffle dirs based on step
            dirs_order = [(d, (abs(wx + d[0] - px) + abs(wy + d[1] - py))) for d in dirs]
            dirs_order.sort(key=lambda x: x[1])
            for (dx, dy), _ in dirs_order:
                nx, ny = wx + dx, wy + dy
                if in_bounds(nx, ny) and em[ny, nx]:
                    # Only place wire if it's in our target zone
                    if target_x_min <= nx <= target_x_max and target_y_min <= ny <= target_y_max:
                        return (Tool.WIRE, nx, ny)
            tried += 1
            if tried > 30:
                break

    # --- Build roads adjacent to wire ---
    # Roads one tile away from wire, in empty spaces
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        step_k2 = int(obs.step * 11) % len(wire_xs)
        for offset in range(min(len(wire_xs), 40)):
            k = (step_k2 + offset * 3) % len(wire_xs)
            wx, wy = int(wire_xs[k]), int(wire_ys[k])
            # Place road adjacent to wire (perpendicular directions for grid roads)
            # Prefer row-wise roads (horizontal strips)
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx + dx, wy + dy
                if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx]:
                    # Check it's not already a wire
                    if not wm[ny, nx]:
                        return (Tool.ROAD, nx, ny)

    # --- Proximity masks for zone placement ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and not zone_tiles[nr, nc]:
                    return False
        return True

    # --- Candidate zone placement ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Sort by proximity to plant (compact city)
        dist_to_plant = np.sqrt((cxs - px)**2 + (cys - py)**2)
        order = np.argsort(dist_to_plant)
        step_off = int(obs.step * 3) % max(len(order), 1)
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            if i > 80:
                break

    # --- Extend roads near wire (fallback) ---
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 25)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx]:
                    if nbr_wire[ny, nx]:
                        return (Tool.ROAD, nx, ny)

    # --- Second power plant when city grows ---
    if total_zones > 12 or obs.city_pop > 300:
        p2x = px + 20
        p2y = py - 5
        if in_bounds(p2x, p2y):
            nearby = any(
                in_bounds(p2x + ddx, p2y + ddy) and pm[p2y + ddy, p2x + ddx]
                for ddy in range(-7, 8) for ddx in range(-7, 8)
            )
            if not nearby and em[p2y, p2x]:
                return (Tool.COALPOWER, p2x, p2y)
            # Wire bridge to second plant
            for wc2 in range(min(px + 2, p2x - 2), p2x + 3):
                for wr2 in range(min(py - 2, p2y - 2), max(py + 2, p2y + 3)):
                    if in_bounds(wc2, wr2) and em[wr2, wc2]:
                        return (Tool.WIRE, wc2, wr2)

    # --- Third power plant for large city ---
    if obs.city_pop > 500:
        p3x = px - 20
        p3y = py + 10
        if in_bounds(p3x, p3y):
            nearby = any(
                in_bounds(p3x + ddx, p3y + ddy) and pm[p3y + ddy, p3x + ddx]
                for ddy in range(-7, 8) for ddx in range(-7, 8)
            )
            if not nearby and em[p3y, p3x]:
                return (Tool.COALPOWER, p3x, p3y)

    # --- Services when pop is high enough ---
    if obs.city_pop > 150:
        fsx, fsy = px - 8, py - 10
        if in_bounds(fsx, fsy) and em[fsy, fsx]:
            return (Tool.FIRESTATION, fsx, fsy)
        psx, psy = px + 10, py - 10
        if in_bounds(psx, psy) and em[psy, psx]:
            return (Tool.POLICESTATION, psx, psy)

    if obs.city_pop > 800:
        stx, sty = px + 15, py + 15
        if in_bounds(stx, sty) and em[sty, stx]:
            return (Tool.STADIUM, stx, sty)

    # --- Fallback: extend wire frontier aggressively ---
    if len(pow_xs) > 0:
        step_k3 = int(obs.step * 17) % len(pow_xs)
        for offset in range(len(pow_xs)):
            k = (step_k3 + offset * 3) % len(pow_xs)
            wx, wy = int(pow_xs[k]), int(pow_ys[k])
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx + dx, wy + dy
                if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx]:
                    return (Tool.WIRE, nx, ny)

    return None

def act(obs, state):
    """
    Modified policy: horizontal wire spine instead of vertical,
    roads above and below the spine, more spread-out cluster,
    two power plants from early on, balanced R/C/I mix.
    """
