    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Place first coal plant at (30, 50) - left side
    if not np.any(pm):
        return (Tool.COALPOWER, 30, 50)

    plant_ys, plant_xs = np.where(pm)
    px = int(plant_xs[0]) if len(plant_xs) > 0 else 30
    py = int(plant_ys[0]) if len(plant_ys) > 0 else 50

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        # Want roughly 30% industrial, 30% commercial, 40% residential
        if i_r < 0.28:
            return Tool.INDUSTRIAL
        if c_r < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # HORIZONTAL wire spine row: just below plant center
    wire_row = py + 2
    # Road rows flanking the wire spine
    road_row_u = wire_row - 1
    road_row_d = wire_row + 1

