    pop_factor = min(35, obs.city_pop // 10)
    spine_left = max(3, px - 5)
    spine_right = min(WORLD_W - 4, px + 20 + pop_factor)

    # --- Build horizontal wire spine ---
    wire_in_row = [c for c in range(WORLD_W)
                   if 0 <= wire_row < WORLD_H and bool(wm[wire_row, c])]

    if not wire_in_row:
        # Seed wire adjacent to plant
        for dx in range(-2, 3):
            nx = px + dx
            if in_bounds(nx, wire_row) and (bool(em[wire_row, nx]) or bool(wm[wire_row, nx])) and not bool(pm[wire_row, nx]):
                return (Tool.WIRE, nx, wire_row)
    else:
        min_wc = min(wire_in_row)
        max_wc = max(wire_in_row)
        # Grow rightward
        if max_wc < spine_right:
            nc = max_wc + 1
            if in_bounds(nc, wire_row) and (bool(em[wire_row, nc]) or bool(wm[wire_row, nc])) and not bool(pm[wire_row, nc]):
                return (Tool.WIRE, nc, wire_row)
        # Grow leftward
        if min_wc > spine_left:
            nc = min_wc - 1
            if in_bounds(nc, wire_row) and (bool(em[wire_row, nc]) or bool(wm[wire_row, nc])) and not bool(pm[wire_row, nc]):
                return (Tool.WIRE, nc, wire_row)

    # --- Build road rows flanking the wire spine ---
    if wire_in_row:
        step_mod3 = obs.step % 3
        cols_to_check = wire_in_row[::2] if step_mod3 < 2 else wire_in_row[1::2]
        for wc in cols_to_check:
            if in_bounds(wc, road_row_u) and bool(em[road_row_u, wc]) and not bool(pm[road_row_u, wc]):
                return (Tool.ROAD, wc, road_row_u)
            if in_bounds(wc, road_row_d) and bool(em[road_row_d, wc]) and not bool(pm[road_row_d, wc]):
                return (Tool.ROAD, wc, road_row_d)

