                    if in_bounds(nc, wire_row2) and (bool(em[wire_row2, nc]) or bool(wm[wire_row2, nc])) and not bool(pm[wire_row2, nc]):
                        return (Tool.WIRE, nc, wire_row2)
                if min_wc2 > spine_left:
                    nc = min_wc2 - 1
