                        return (Tool.WIRE, nc, wire_row2)
                # Roads for second spine
                cols2_check = wire_in_row2[::2] if obs.step % 2 == 0 else wire_in_row2[1::2]
                for wc in cols2_check:
                    if in_bounds(wc, road_row2_u) and bool(em[road_row2_u, wc]) and not bool(pm[road_row2_u, wc]):
                        return (Tool.ROAD, wc, road_row2_u)
                    if in_bounds(wc, road_row2_d) and bool(em[road_row2_d, wc]) and not bool(pm[road_row2_d, wc]):
