    """
    Closed-loop policy: scan current map each step, extend infrastructure
    adjacent to what already exists. Compact vertical-spine layout:
    - Coal plant at left-center
    - Wire spine runs down from plant
    - Road parallel to wire (one column right)
    - Zones placed left and right of spine
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    all_zones = resm | comm | indm

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        if com_count / t < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zr, zc):
        """Check 3x3 area is clear of non-zone obstacles"""
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zones[rr, rc]:
                    return False
        return True

    def zone_present(zr, zc, radius=2):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(all_zones[r0:r1, c0:c1])

    # --- Phase 0: Place power plant if none exists ---
    if not np.any(pm):
        # Place plant at fixed anchor
        px, py = 45, 50
        return (Tool.COALPOWER, px, py)

    # Find plant center
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Layout constants (relative to plant)
    wire_col = plant_cx + 3   # wire spine column
    road_col = plant_cx + 5   # road column (parallel)
    left_zone_col = plant_cx - 3   # zones to the left
    right_zone_col = plant_cx + 9  # zones to the right

    # Clamp
    wire_col = max(1, min(WORLD_W - 2, wire_col))
    road_col = max(1, min(WORLD_W - 2, road_col))
    left_zone_col = max(1, min(WORLD_W - 2, left_zone_col))
    right_zone_col = max(1, min(WORLD_W - 2, right_zone_col))

    # Determine how far down to build (adaptive to population)
    if obs.city_pop < 50:
        extent = 10
    elif obs.city_pop < 150:
        extent = 20
    elif obs.city_pop < 400:
        extent = 35
    elif obs.city_pop < 800:
        extent = 55
    else:
        extent = 75

    spine_top = plant_cy + 3   # start below plant
    spine_bot = min(WORLD_H - 3, plant_cy + extent)

    # --- Phase 1: Extend wire spine downward from plant ---
    # Find lowest existing wire on wire_col
    wire_rows_on_col = [r for r in range(WORLD_H) if wm[r, wire_col]]
    if not wire_rows_on_col:
        # Start wire adjacent to plant (below)
        for dr in range(1, 5):
            nr = plant_cy + dr
            nc = wire_col
            if 0 <= nr < WORLD_H and 0 <= nc < WORLD_W:
                if em[nr, nc] or wm[nr, nc]:
                    return (Tool.WIRE, nc, nr)
        # Try placing wire right next to plant
        return (Tool.WIRE, wire_col, plant_cy + 2)

    max_wire_row = max(wire_rows_on_col)
    if max_wire_row < spine_bot:
        nr = max_wire_row + 1
        if 0 <= nr < WORLD_H and em[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)
        elif 0 <= nr < WORLD_H and not pm[nr, wire_col]:
            # Something in the way, skip one
            if nr + 1 < WORLD_H and em[nr + 1, wire_col]:
                return (Tool.WIRE, wire_col, nr + 1)

    # --- Phase 2: Extend road spine parallel to wire ---
    road_rows_on_col = [r for r in range(WORLD_H) if rm[r, road_col]]
    if not road_rows_on_col:
        # Start road at spine_top
        if em[spine_top, road_col]:
            return (Tool.ROAD, road_col, spine_top)
        return (Tool.ROAD, road_col, spine_top + 1)

    max_road_row = max(road_rows_on_col)
    current_road_extent = min(max_wire_row, spine_bot)
    if max_road_row < current_road_extent:
        nr = max_road_row + 1
        if 0 <= nr < WORLD_H and em[nr, road_col]:
            return (Tool.ROAD, road_col, nr)

    # --- Phase 3: Place zones adjacent to wire+road spine ---
    # Scan wire rows and try to place zones on both sides
    zone_rows = sorted(wire_rows_on_col)
    road_rows_set = set(road_rows_on_col)

    for wr in zone_rows:
        # Need road access nearby
        road_near = any(abs(wr - rr) <= 2 for rr in road_rows_set)
        if not road_near:
            continue

        # Left zone
        zr, zc = wr, left_zone_col
        if not zone_present(zr, zc) and zone_area_ok(zr, zc):
            # Check wire within 5
            r0 = max(0, zr - 5); r1 = min(WORLD_H, zr + 6)
            c0 = max(0, zc - 5); c1 = min(WORLD_W, zc + 6)
            if np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1]):
                r0r = max(0, zr - 5); r1r = min(WORLD_H, zr + 6)
                c0r = max(0, zc - 5); c1r = min(WORLD_W, zc + 6)
                if np.any(rm[r0r:r1r, c0r:c1r]):
                    return (pick_tool(), zc, zr)

        # Right zone (further right)
        zr2, zc2 = wr, right_zone_col
        if not zone_present(zr2, zc2) and zone_area_ok(zr2, zc2):
            r0 = max(0, zr2 - 5); r1 = min(WORLD_H, zr2 + 6)
            c0 = max(0, zc2 - 5); c1 = min(WORLD_W, zc2 + 6)
            if np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1]):
                r0r = max(0, zr2 - 5); r1r = min(WORLD_H, zr2 + 6)
                c0r = max(0, zc2 - 5); c1r = min(WORLD_W, zc2 + 6)
                if np.any(rm[r0r:r1r, c0r:c1r]):
                    return (pick_tool(), zc2, zr2)

    # --- Phase 4: Connect zones to wire via horizontal wires ---
    # Extend wire horizontally to reach left zones
    for wr in zone_rows:
        # Horizontal wire leftward from spine to left_zone_col
        for wc in range(wire_col - 1, left_zone_col - 2, -1):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc]:
                    break

    # Extend wire rightward to reach right zones
    for wr in zone_rows:
        for wc in range(wire_col + 1, right_zone_col + 3):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc] and not rm[wr, wc]:
                    break

    # --- Phase 5: Extend road horizontally to serve zones ---
    for rr in road_rows_set:
        # Road leftward
        for rc in range(road_col - 1, left_zone_col - 2, -1):
            if 0 <= rc < WORLD_W:
                if rm[rr, rc]:
                    break
                if em[rr, rc] and not pm[rr, rc]:
                    return (Tool.ROAD, rc, rr)
                elif not em[rr, rc]:
                    break

    # --- Phase 6: Second power plant when needed ---
    if obs.city_pop > 500 and int(np.sum(pm)) < 9:
        # Place second plant below the first spine
        px2 = plant_cx
        py2 = min(WORLD_H - 3, plant_cy + extent // 2 + 5)
        area_ok = True
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = py2 + dr, px2 + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if not (em[rr, rc] or pm[rr, rc]):
                        area_ok = False
        if area_ok:
            return (Tool.COALPOWER, px2, py2)

    # --- Phase 7: Second wire column for more coverage ---
    if obs.city_pop >= 200:
        wire_col2 = plant_cx - 4
        wire_col2 = max(1, min(WORLD_W - 2, wire_col2))
        wire_rows2 = [r for r in range(WORLD_H) if wm[r, wire_col2]]
        if not wire_rows2:
            # Connect from plant
            if em[plant_cy, wire_col2]:
                return (Tool.WIRE, wire_col2, plant_cy)
        else:
            max_wr2 = max(wire_rows2)
            if max_wr2 < spine_bot:
                nr = max_wr2 + 1
                if 0 <= nr < WORLD_H and em[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)

        # More zones on left side using wire_col2
        road_col2 = plant_cx - 6
        road_col2 = max(1, min(WORLD_W - 2, road_col2))
        road_rows2 = set(r for r in range(WORLD_H) if rm[r, road_col2])
        left_zone_col2 = plant_cx - 10
        left_zone_col2 = max(1, min(WORLD_W - 2, left_zone_col2))

        for wr in wire_rows2:
            road_near2 = any(abs(wr - rr) <= 2 for rr in road_rows2)
            if not road_near2:
                if em[wr, road_col2]:
                    return (Tool.ROAD, road_col2, wr)
                continue
            zr3, zc3 = wr, left_zone_col2
            if not zone_present(zr3, zc3) and zone_area_ok(zr3, zc3):
                r0 = max(0, zr3 - 5); r1 = min(WORLD_H, zr3 + 6)
                c0 = max(0, zc3 - 5); c1 = min(WORLD_W, zc3 + 6)
                if np.any(wm[r0:r1, c0:c1]):
                    if np.any(rm[r0:r1, c0:c1]):
                        return (pick_tool(), zc3, zr3)

    # --- Phase 8: Additional zone rows (every 3 rows along spine) ---
    # Try placing zones at every 3rd wire row
    if len(zone_rows) > 0:
        for wr in range(spine_top, spine_bot, 3):
            # Is there wire near this row?
            wire_near_row = any(abs(wr - wr2) <= 1 for wr2 in zone_rows)
            road_near_row = any(abs(wr - rr) <= 1 for rr in road_rows_set)
            if wire_near_row and road_near_row:
                for zc in [left_zone_col, right_zone_col]:
                    if not zone_present(wr, zc) and zone_area_ok(wr, zc):
                        r0 = max(0, wr - 5); r1 = min(WORLD_H, wr + 6)
                        c0 = max(0, zc - 5); c1 = min(WORLD_W, zc + 6)
                        if np.any(wm[r0:r1, c0:c1]) and np.any(rm[r0:r1, c0:c1]):
                            return (pick_tool(), zc, wr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Each step reads the actual tile_map to decide next placement
    - Extends power/road/zones from what already exists
    - Compact cluster around center of map
    - Phase counter in state for coarse ordering
    """
    tm = obs.tile_map
    step = obs.step

    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # Cluster center
    cx, cy = 60, 50

    # Count existing structures
    n_plants = int(np.sum(pm))
    n_wire = int(np.sum(wm))
    n_road = int(np.sum(rm))
    n_res = int(np.sum(res_m))
    n_com = int(np.sum(com_m))
    n_ind = int(np.sum(ind_m))
    n_zones = n_res + n_com + n_ind

    def is_valid(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def area_empty(cx, cy, r=1):
        for dy in range(-r, r+1):
            for dx in range(-r, r+1):
                if not is_valid(cx+dx, cy+dy):
                    return False
                if not em[cy+dy, cx+dx]:
                    return False
        return True

    # --- Phase 1: Place first coal power plant ---
    if n_plants == 0:
        # Place at left of cluster
        px, py = cx - 15, cy
        return (Tool.COALPOWER, px, py)

    # Find plant position(s)
    plant_ys, plant_xs = np.where(pm)
    # Use first plant as anchor
    p0x, p0y = int(plant_xs[0]), int(plant_ys[0])

    # --- Phase 2: Build wire spine from plant rightward along cy ---
    # Wire row = cy, from plant rightward to cx+20
    wire_target_x = cx + 20
    # Find rightmost wire in spine row
    spine_row = cy
    wire_in_spine = [(int(plant_xs[i]), int(plant_ys[i])) for i in range(len(plant_xs))
                     if int(plant_ys[i]) == spine_row]
    # Also find wires anywhere in spine_row
    spine_wire_cols = [c for c in range(WORLD_W) if wm[spine_row, c]]
    if spine_wire_cols:
        max_wire_x = max(spine_wire_cols)
    else:
        max_wire_x = p0x  # start from plant

    if max_wire_x < wire_target_x:
        nx = max_wire_x + 1
        if is_valid(nx, spine_row) and em[spine_row, nx]:
            return (Tool.WIRE, nx, spine_row)
        # If blocked, try to bulldoze? No - just skip ahead
        # find next empty in spine
        for nx in range(max_wire_x + 1, wire_target_x + 1):
            if is_valid(nx, spine_row) and em[spine_row, nx]:
                return (Tool.WIRE, nx, spine_row)

    # --- Phase 3: Build two horizontal roads parallel to wire spine ---
    # Road at cy-2 and cy+2, from cx-10 to cx+20
    road_start_x = cx - 10
    road_end_x = cx + 20
    for road_row in [cy - 2, cy + 2]:
        road_cols_here = [c for c in range(WORLD_W) if rm[road_row, c]]
        if road_cols_here:
            max_rc = max(road_cols_here)
        else:
            max_rc = road_start_x - 1
        if max_rc < road_end_x:
            nc = max_rc + 1
            if is_valid(nc, road_row) and em[road_row, nc]:
                return (Tool.ROAD, nc, road_row)
            # find next empty
            for nc in range(max_rc + 1, road_end_x + 1):
                if is_valid(nc, road_row) and em[road_row, nc]:
                    return (Tool.ROAD, nc, road_row)

    # --- Phase 4: Build vertical connector roads at intervals ---
    # Connect road rows to each other every 6 cols
    for conn_col in range(road_start_x, road_end_x + 1, 6):
        for conn_row in range(cy - 2, cy + 3):
            if is_valid(conn_col, conn_row):
                if not rm[conn_row, conn_col] and em[conn_row, conn_col]:
                    return (Tool.ROAD, conn_col, conn_row)

    # --- Phase 5: Branch wires from spine up/down to zone rows ---
    # Zone rows: cy-5, cy-8, cy-11, cy+5, cy+8, cy+11
    zone_rows = [cy - 5, cy - 8, cy - 11, cy + 5, cy + 8, cy + 11]
    zone_cols = list(range(cx - 8, cx + 22, 6))

    # Build vertical wires from spine to zone rows
    for zc in zone_cols:
        if not is_valid(zc, spine_row):
            continue
        # Check if spine wire present at this col
        if not wm[spine_row, zc]:
            continue
        # Extend wire upward
        for zr in [cy - 5, cy - 8, cy - 11]:
            if not is_valid(zc, zr):
                continue
            # trace from spine upward
            for wr in range(spine_row - 1, zr - 1, -1):
                if not is_valid(zc, wr):
                    break
                if wm[wr, zc] or rm[wr, zc]:
                    continue
                if em[wr, zc]:
                    return (Tool.WIRE, zc, wr)
                break
        # Extend wire downward
        for zr in [cy + 5, cy + 8, cy + 11]:
            if not is_valid(zc, zr):
                continue
            for wr in range(spine_row + 1, zr + 2):
                if not is_valid(zc, wr):
                    break
                if wm[wr, zc] or rm[wr, zc]:
                    continue
                if em[wr, zc]:
                    return (Tool.WIRE, zc, wr)
                break

    # --- Phase 6: Place zones near roads and wires ---
    def has_road_nearby(zx, zy, dist=3):
        for dy in range(-dist, dist+1):
            for dx in range(-dist, dist+1):
                nx, ny = zx+dx, zy+dy
                if is_valid(nx, ny) and rm[ny, nx]:
                    return True
        return False

    def has_wire_nearby(zx, zy, dist=4):
        for dy in range(-dist, dist+1):
            for dx in range(-dist, dist+1):
                nx, ny = zx+dx, zy+dy
                if is_valid(nx, ny) and wm[ny, nx]:
                    return True
        return False

    def pick_zone():
        total = n_zones + 1
        r_frac = n_res / total
        c_frac = n_com / total
        i_frac = n_ind / total
        if c_frac < 0.25:
            return Tool.COMMERCIAL
        elif i_frac < 0.25:
            return Tool.INDUSTRIAL
        else:
            return Tool.RESIDENTIAL

    for zr in zone_rows:
        for zc in zone_cols:
            if not is_valid(zc, zr):
                continue
            if not has_road_nearby(zc, zr):
                continue
            if not has_wire_nearby(zc, zr):
                continue
            if area_empty(zc, zr, 1):
                return (pick_zone(), zc, zr)

    # --- Phase 7: Second power plant if zones are numerous ---
    if n_zones > 10 and n_plants < 2:
        px2, py2 = cx + 22, cy
        if area_empty(px2, py2, 2):
            return (Tool.COALPOWER, px2, py2)

    # --- Phase 8: Extend infrastructure further if pop growing ---
    if obs.city_pop > 50 or n_zones > 8:
        extra_zone_rows = [cy - 14, cy + 14, cy - 17, cy + 17]
        extra_zone_cols = list(range(cx - 8, cx + 22, 6))

        # Extend roads further
        for road_row in [cy - 2, cy + 2]:
            ext_end = road_end_x + 12
            road_cols_here = [c for c in range(WORLD_W) if rm[road_row, c]]
            if road_cols_here:
                max_rc = max(road_cols_here)
                if max_rc < ext_end:
                    nc = max_rc + 1
                    if is_valid(nc, road_row) and em[road_row, nc]:
                        return (Tool.ROAD, nc, road_row)

        # Place extra zones
        for zr in extra_zone_rows:
            for zc in extra_zone_cols:
                if not is_valid(zc, zr):
                    continue
                if has_road_nearby(zc, zr, 4) and has_wire_nearby(zc, zr, 6):
                    if area_empty(zc, zr, 1):
                        return (pick_zone(), zc, zr)

    # --- Phase 9: Reactive gap-fill: find any zone tile adjacent to road ---
    # Scan around existing roads for empty 3x3 spots
    road_ys, road_xs = np.where(rm)
    for i in range(min(len(road_xs), 200)):
        rx_i, ry_i = int(road_xs[i]), int(road_ys[i])
        for dy in [-4, -7, 4, 7]:
            zx, zy = rx_i, ry_i + dy
            if is_valid(zx, zy) and area_empty(zx, zy, 1):
                if has_wire_nearby(zx, zy, 5):
                    return (pick_zone(), zx, zy)

    # Extend wire spine further if needed
    for nx in range(wire_target_x + 1, wire_target_x + 15):
        if is_valid(nx, spine_row) and em[spine_row, nx]:
            return (Tool.WIRE, nx, spine_row)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy v3:
    - Reads tile_map every step
    - Builds a denser grid: horizontal road/wire lanes every 6 rows
    - Connects lanes with vertical roads
    - Places zones between road lanes
    - Adds more coal plants as city grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Place first coal plant if missing ---
    if not np.any(pm):
        return (Tool.COALPOWER, 60, 50)

    plant_ys, plant_xs = np.where(pm)
    px = int(np.median(plant_xs))
    py = int(np.median(plant_ys))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def expand_mask(base, radius=2):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        ys, xs = np.where(base)
        for dy in range(-radius, radius+1):
            for dx in range(-radius, radius+1):
                ny = np.clip(ys + dy, 0, WORLD_H-1)
                nx = np.clip(xs + dx, 0, WORLD_W-1)
                result[ny, nx] = True
        return result

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and not zone_tiles[nr, nc]:
                    return False
        return True

    # Grid layout:
    # Use horizontal wire rows at py, py-6, py+6, py-12, py+12...
    # Road rows at py-1, py+1, py-7, py+7... (adjacent to wires)
    # Vertical connecting roads at regular columns

    # Expand coverage based on pop
    pop_factor = min(4, obs.city_pop // 100)
    n_bands = 2 + pop_factor  # number of wire rows above and below center

    wire_rows = []
    for k in range(-n_bands, n_bands+1):
        wr = py + k * 6
        if 3 <= wr <= WORLD_H - 4:
            wire_rows.append(wr)

    # Wire cols: extend from px-20 to px+40 roughly
    x_extent = 15 + min(30, obs.city_pop // 15)
    wire_x_min = max(3, px - x_extent)
    wire_x_max = min(WORLD_W - 4, px + x_extent)

    # Vertical connector columns at intervals of 8
    vert_cols = []
    c = px
    while c >= wire_x_min:
        vert_cols.append(c)
        c -= 8
    c = px + 8
    while c <= wire_x_max:
        vert_cols.append(c)
        c += 8

    # --- Step 1: Extend horizontal wire rows ---
    for wr in wire_rows:
        wire_in_row = [c for c in range(WORLD_W) if wm[wr, c]]
        if not wire_in_row:
            # Check if plant is nearby, seed wire from plant area
            if abs(wr - py) <= 3:
                # Seed adjacent to plant
                for dc in range(-3, 4):
                    nc = px + dc
                    if in_bounds(nc, wr) and (em[wr, nc] or wm[wr, nc]) and not pm[wr, nc]:
                        return (Tool.WIRE, nc, wr)
            else:
                # Try to extend from existing wire at adjacent rows
                for adj_wr in [wr-1, wr+1, wr-2, wr+2]:
                    if 0 <= adj_wr < WORLD_H:
                        for c in range(WORLD_W):
                            if wm[adj_wr, c] and in_bounds(c, wr) and (em[wr, c] or wm[wr, c]) and not pm[wr, c]:
                                return (Tool.WIRE, c, wr)
        else:
            min_wc = min(wire_in_row)
            max_wc = max(wire_in_row)
            if max_wc < wire_x_max:
                nc = max_wc + 1
                if in_bounds(nc, wr) and (em[wr, nc] or wm[wr, nc]) and not pm[wr, nc]:
                    return (Tool.WIRE, nc, wr)
            if min_wc > wire_x_min:
                nc = min_wc - 1
                if in_bounds(nc, wr) and (em[wr, nc] or wm[wr, nc]) and not pm[wr, nc]:
                    return (Tool.WIRE, nc, wr)

    # --- Step 2: Build roads adjacent to wire rows (both sides) ---
    for wr in wire_rows:
        for road_row in [wr - 1, wr + 1]:
            if not in_bounds(0, road_row):
                continue
            wire_in_row = [c for c in range(WORLD_W) if wm[wr, c]]
            for wc in wire_in_row:
                if wire_x_min <= wc <= wire_x_max:
                    if in_bounds(wc, road_row) and em[road_row, wc] and not pm[road_row, wc]:
                        return (Tool.ROAD, wc, road_row)

    # --- Step 3: Vertical connector roads between wire rows ---
    if len(wire_rows) >= 2:
        for vc in vert_cols:
            for i in range(len(wire_rows) - 1):
                r1 = wire_rows[i]
                r2 = wire_rows[i+1]
                # Connect with road from r1+1 to r2-1 at column vc
                for row in range(r1 + 1, r2):
                    if in_bounds(vc, row) and em[row, vc] and not pm[row, vc]:
                        # Check if road or wire nearby
                        has_conn = False
                        for dr in [-1, 1]:
                            nr2 = row + dr
                            if in_bounds(vc, nr2) and (rm[nr2, vc] or wm[nr2, vc]):
                                has_conn = True
                        if has_conn:
                            return (Tool.ROAD, vc, row)

    # --- Step 4: Place zones where road+wire coverage exists ---
    power_src = wm | pm
    nbr_wire = expand_mask(power_src, 2)
    nbr_road = expand_mask(rm, 2)

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by proximity to plant center and wire rows
        dist_to_wire = np.min(np.abs(cys[:, None] - np.array(wire_rows)[None, :]), axis=1) if wire_rows else np.abs(cys - py)
        dist_to_px = np.abs(cxs - px)
        scores = dist_to_wire * 2 + dist_to_px
        order = np.argsort(scores)
        step_off = int(obs.step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 80:
                break

    # --- Step 5: Additional coal plants as city grows ---
    n_plants_needed = 1 + total_zones // 15
    n_plants_actual = int(np.sum(pm)) // 9  # approx 3x3
    if n_plants_actual < n_plants_needed:
        # Place next plant offset from existing ones
        attempt_positions = [
            (px + 20, py),
            (px - 20, py),
            (px, py + 20),
            (px, py - 20),
            (px + 20, py + 20),
        ]
        for p2x, p2y in attempt_positions:
            p2x = max(3, min(WORLD_W - 4, p2x))
            p2y = max(3, min(WORLD_H - 4, p2y))
            nearby = any(
                in_bounds(p2x + dx, p2y + dy) and pm[p2y + dy, p2x + dx]
                for dy in range(-5, 6) for dx in range(-5, 6)
            )
            if not nearby and em[p2y, p2x]:
                return (Tool.COALPOWER, p2x, p2y)
            # Wire to connect new plant: lay wire from new plant toward existing wire
            if not nearby:
                # Try to bridge
                for wc in range(min(px, p2x), max(px, p2x) + 1):
                    if in_bounds(wc, p2y) and (em[p2y, wc] or wm[p2y, wc]) and not pm[p2y, wc]:
                        if not wm[p2y, wc]:
                            return (Tool.WIRE, wc, p2y)

    # --- Step 6: Services ---
    if obs.city_pop > 200:
        fsx = max(2, min(WORLD_W - 3, px - 12))
        fsy = max(2, min(WORLD_H - 3, py - 6))
        if em[fsy, fsx]:
            return (Tool.FIRESTATION, fsx, fsy)
    if obs.city_pop > 300:
        psx = max(2, min(WORLD_W - 3, px + 12))
        psy = max(2, min(WORLD_H - 3, py + 6))
        if em[psy, psx]:
            return (Tool.POLICESTATION, psx, psy)

    # --- Step 7: Extend any wire frontier to reach unserved empty areas ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 20)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = wx + dx2, wy + dy2
                if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                    # Only extend if in planned area
                    if wire_x_min <= nx2 <= wire_x_max:
                        return (Tool.WIRE, nx2, ny2)

    # --- Step 8: Extend roads from existing roads ---
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 20)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx]:
                    if nbr_wire[ny, nx]:
                        return (Tool.ROAD, nx, ny)

    return None

def act(obs, state):
    """
    Hybrid policy combining best of Parent A and Parent B.
    Strategy:
    - Coal plant -> wire spine -> dual road columns -> zones (R/C/I balanced)
    - Lateral wires to reach zones on both sides
    - Expand vertically based on population
    - Additional power plants when needed
    - Services for large cities
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    all_zone = resm | comm | indm

    cx, cy = WORLD_W // 2, WORLD_H // 2  # 60, 50

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    pop = obs.city_pop

    def pick_tool():
        t = max(total_zones, 1)
        if ind_count / t < 0.22:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zy, zx):
        if zy < 1 or zy > WORLD_H - 2 or zx < 1 or zx > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zy + dr, zx + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone[rr, rc]:
                    return False
        return True

    # --- Phase 1: Place coal power plant ---
    if not np.any(pm):
        return (Tool.COALPOWER, cx - 10, cy)

    # Find plant centroid
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Layout: wire spine right of plant, road columns on both sides
    wire_col = plant_cx + 4
    wire_col = max(4, min(WORLD_W - 5, wire_col))
    road_col_r = wire_col + 3   # road to the right of wire
    road_col_l = wire_col - 4   # road to the left of wire
    zone_col_r = road_col_r + 4  # right zone column
    zone_col_l = wire_col - 8    # left zone column

    road_col_r = max(3, min(WORLD_W - 4, road_col_r))
    road_col_l = max(3, min(WORLD_W - 4, road_col_l))
    zone_col_r = max(3, min(WORLD_W - 4, zone_col_r))
    zone_col_l = max(3, min(WORLD_W - 4, zone_col_l))

    # Vertical extent scales with population
    if pop < 50:
        half = 8
    elif pop < 150:
        half = 14
    elif pop < 400:
        half = 20
    elif pop < 800:
        half = 28
    else:
        half = 36

    y_min = max(2, cy - half)
    y_max = min(WORLD_H - 3, cy + half)

    # --- Phase 2: Connect plant to wire spine if not connected ---
    plant_connected = False
    for pr, pc in zip(plant_rows.tolist(), plant_cols.tolist()):
        for dr in range(-3, 4):
            for dc in range(-3, 4):
                rr, rc = pr + dr, pc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W and wm[rr, rc]:
                    plant_connected = True

    if not plant_connected:
        bridge_r = plant_cy
        for bc in range(plant_cx + 1, wire_col + 1):
            if in_bounds(bc, bridge_r):
                if pm[bridge_r, bc]:
                    continue
                if wm[bridge_r, bc]:
                    break
                if em[bridge_r, bc]:
                    return (Tool.WIRE, bc, bridge_r)
        for delta in [1, -1, 2, -2]:
            bridge_r2 = plant_cy + delta
            for bc in range(plant_cx + 1, wire_col + 1):
                if in_bounds(bc, bridge_r2):
                    if pm[bridge_r2, bc]:
                        continue
                    if wm[bridge_r2, bc]:
                        break
                    if em[bridge_r2, bc]:
                        return (Tool.WIRE, bc, bridge_r2)

    # --- Phase 3: Extend wire spine vertically ---
    wire_at_col = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])

    if not wire_at_col:
        for dy in range(0, 10):
            for nr in [plant_cy + dy, plant_cy - dy]:
                if in_bounds(wire_col, nr) and em[nr, wire_col]:
                    return (Tool.WIRE, wire_col, nr)
        return None

    min_wr = min(wire_at_col)
    max_wr = max(wire_at_col)

    # Extend downward
    if max_wr < y_max:
        nr = max_wr + 1
        if in_bounds(wire_col, nr) and em[nr, wire_col] and not pm[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)

    # Extend upward
    if min_wr > y_min:
        nr = min_wr - 1
        if in_bounds(wire_col, nr) and em[nr, wire_col] and not pm[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)

    # --- Phase 4: Build right road column along wire spine ---
    for r in wire_at_col:
        if y_min <= r <= y_max:
            if in_bounds(road_col_r, r) and em[r, road_col_r] and not pm[r, road_col_r] and not wm[r, road_col_r]:
                return (Tool.ROAD, road_col_r, r)

    # --- Phase 5: Build left road column along wire spine ---
    for r in wire_at_col:
        if y_min <= r <= y_max:
            if in_bounds(road_col_l, r) and em[r, road_col_l] and not pm[r, road_col_l] and not wm[r, road_col_l]:
                return (Tool.ROAD, road_col_l, r)

    # --- Phase 6: Horizontal connecting roads every 6 rows ---
    for wr in wire_at_col:
        if y_min <= wr <= y_max and (wr - y_min) % 6 == 0:
            for rc in range(road_col_l, road_col_r + 1):
                if in_bounds(rc, wr) and em[wr, rc] and not pm[wr, rc] and not wm[wr, rc]:
                    return (Tool.ROAD, rc, wr)

    # --- Phase 7: Lateral wires from spine toward zone columns ---
    # Wire leftward toward left zone column
    for wr in wire_at_col:
        if y_min <= wr <= y_max:
            already_wired = any(
                0 <= wc < WORLD_W and wm[wr, wc]
                for wc in range(wire_col - 1, max(zone_col_l - 1, 0), -1)
            )
            if not already_wired:
                for wc in range(wire_col - 1, max(zone_col_l - 2, 0), -1):
                    if 0 <= wc < WORLD_W:
                        if wm[wr, wc]:
                            break
                        if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                            return (Tool.WIRE, wc, wr)
                        elif not em[wr, wc] and not rm[wr, wc]:
                            break

    # Wire rightward toward right zone column
    for wr in wire_at_col:
        if y_min <= wr <= y_max:
            already_wired = any(
                0 <= wc < WORLD_W and wm[wr, wc]
                for wc in range(wire_col + 1, min(zone_col_r + 2, WORLD_W))
            )
            if not already_wired:
                for wc in range(wire_col + 1, min(zone_col_r + 2, WORLD_W)):
                    if 0 <= wc < WORLD_W:
                        if wm[wr, wc]:
                            break
                        if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                            return (Tool.WIRE, wc, wr)
                        elif not em[wr, wc] and not rm[wr, wc]:
                            break

    # --- Phase 8: Place zones near road AND wire coverage ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, :2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        dists = (np.abs(cxs_arr.astype(int) - wire_col) +
                 np.abs(cys_arr.astype(int) - cy))
        sort_idx = np.argsort(dists)
        for i in range(min(len(cxs_arr), 80)):
            k = int(sort_idx[i])
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_area_ok(zy, zx):
                return (pick_tool(), zx, zy)

    # --- Phase 9: Second power plant when pop grows ---
    plant_tile_count = int(np.sum(pm))
    plant_count = max(1, plant_tile_count // 6)
    if pop > 250 and plant_count < 2:
        p2x = plant_cx + 22
        p2y = plant_cy
        if in_bounds(p2x, p2y) and em[p2y, p2x]:
            nearby = any(
                in_bounds(p2x + dx, p2y + dy) and pm[p2y + dy, p2x + dx]
                for dy in range(-6, 7) for dx in range(-6, 7)
            )
            if not nearby:
                return (Tool.COALPOWER, p2x, p2y)
        # Wire bridge toward second plant
        for wc in range(wire_col + 1, min(wire_col + 25, WORLD_W - 3)):
            if in_bounds(wc, plant_cy) and em[plant_cy, wc] and not pm[plant_cy, wc]:
                if wm[plant_cy, wc]:
                    break
                return (Tool.WIRE, wc, plant_cy)

    # --- Phase 10: Third plant for large city ---
    if pop > 600 and not state.get("plant3_done", False):
        p3x = plant_cx - 22
        p3y = plant_cy
        if in_bounds(p3x, p3y) and em[p3y, p3x]:
            nearby = any(
                in_bounds(p3x + dx, p3y + dy) and pm[p3y + dy, p3x + dx]
                for dy in range(-6, 7) for dx in range(-6, 7)
            )
            if not nearby:
                state["plant3_done"] = True
                return (Tool.COALPOWER, p3x, p3y)
        for wc in range(wire_col - 1, max(wire_col - 26, 2), -1):
            if in_bounds(wc, plant_cy) and em[plant_cy, wc] and not pm[plant_cy, wc]:
                if wm[plant_cy, wc]:
                    break
                return (Tool.WIRE, wc, plant_cy)

    # --- Phase 11: Services ---
    if pop > 300:
        for fx, fy in [(wire_col - 8, cy - 12), (wire_col + 8, cy + 12)]:
            if in_bounds(fx, fy) and em[fy, fx]:
                return (Tool.FIRESTATION, fx, fy)
    if pop > 500:
        for px2, py2 in [(wire_col + 8, cy - 12), (wire_col - 8, cy + 12)]:
            if in_bounds(px2, py2) and em[py2, px2]:
                return (Tool.POLICESTATION, px2, py2)

    # --- Phase 12: Extend wire to reach more zones ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k = int(obs.step * 7) % len(wire_xs_arr)
        wx_s = int(wire_xs_arr[step_k])
        wy_s = int(wire_ys_arr[step_k])
        for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx2, ny2 = wx_s + dx2, wy_s + dy2
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                if y_min <= ny2 <= y_max:
                    return (Tool.WIRE, nx2, ny2)

    # --- Phase 13: Extend roads near wire ---
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = int(obs.step * 11) % len(road_xs_arr)
        rx_s = int(road_xs_arr[step_k])
        ry_s = int(road_ys_arr[step_k])
        for dy2, dx2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx2, ny2 = rx_s + dx2, ry_s + dy2
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2] and not wm[ny2, nx2]:
                if nbr_wire[ny2, nx2] and y_min <= ny2 <= y_max:
                    return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy.
    Reads map each step to decide next placement.
    Key changes from parent:
    - Zones placed directly adjacent to road (on grid points off road)
    - More balanced RCI ratio
    - Wire runs alongside road (not separate spine)
    - Compact 4-wide lanes: wire row, road row, zone row (above+below)
    - Vertical connectors earlier
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    has_plant = np.any(pm)

    # Phase 1: Place coal power plant near center
    if not has_plant:
        return (Tool.COALPOWER, 60, 50)

    # Find plant center
    plant_rows, plant_cols = np.where(pm)
    pcx = int(np.mean(plant_cols))
    pcy = int(np.mean(plant_rows))

    # Layout (relative to plant center pcy):
    # wire_row = pcy (same row as plant, horizontal wire spine)
    # road_row_top = pcy - 4
    # road_row_bot = pcy + 4
    # zone_row_top = pcy - 7  (zones: center 3 rows above road)
    # zone_row_bot = pcy + 7  (zones: center 3 rows below road)

    wire_row = pcy
    road_row_top = pcy - 4
    road_row_bot = pcy + 4
    zone_row_top = pcy - 7
    zone_row_bot = pcy + 7

    # Clamp
    wire_row    = max(2, min(WORLD_H - 3, wire_row))
    road_row_top = max(2, min(WORLD_H - 3, road_row_top))
    road_row_bot = max(2, min(WORLD_H - 3, road_row_bot))
    zone_row_top = max(2, min(WORLD_H - 3, zone_row_top))
    zone_row_bot = max(2, min(WORLD_H - 3, zone_row_bot))

    # Horizontal span grows with population
    half_span = min(45, max(10, 10 + obs.city_pop // 8))
    cmin = max(2, pcx - half_span)
    cmax = min(WORLD_W - 3, pcx + half_span)

    # Helper: check if 3x3 area is fully empty
    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc]:
                    return False
        return True

    all_zone_m = res_m | com_m | ind_m

    def nearby_zone(zr, zc, radius=3):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(all_zone_m[r0:r1, c0:c1])

    res_count = max(1, int(np.sum(res_m)) // 9)
    com_count = max(1, int(np.sum(com_m)) // 9)
    ind_count = max(1, int(np.sum(ind_m)) // 9)

    def pick_zone():
        # Aim for ~50% RES, 25% COM, 25% IND
        total = res_count + com_count + ind_count
        if ind_count * 4 < total:
            return Tool.INDUSTRIAL
        if com_count * 4 < total:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- Phase 2: Build horizontal wire spine at wire_row ----
    wire_cols = sorted(c for c in range(WORLD_W) if 0 <= wire_row < WORLD_H and wm[wire_row, c])

    if not wire_cols:
        # Start wire adjacent to plant
        for dx in range(0, 5):
            for sign in [1, -1]:
                nx = pcx + sign * dx
                if 0 <= nx < WORLD_W and 0 <= wire_row < WORLD_H:
                    if em[wire_row, nx]:
                        return (Tool.WIRE, nx, wire_row)
        return (Tool.WIRE, pcx, wire_row)
    else:
        min_wc = wire_cols[0]
        max_wc = wire_cols[-1]
        # Extend rightward
        if max_wc < cmax:
            nc = max_wc + 1
            if 0 <= nc < WORLD_W:
                return (Tool.WIRE, nc, wire_row)
        # Extend leftward
        if min_wc > cmin:
            nc = min_wc - 1
            if 0 <= nc < WORLD_W:
                return (Tool.WIRE, nc, wire_row)

    wire_cols_set = set(wire_cols)

    # ---- Phase 3: Build road rows ----
    # Top road row
    if 0 <= road_row_top < WORLD_H:
        for wc in wire_cols:
            if cmin <= wc <= cmax and not rm[road_row_top, wc] and em[road_row_top, wc]:
                return (Tool.ROAD, wc, road_row_top)
    # Bottom road row
    if 0 <= road_row_bot < WORLD_H:
        for wc in wire_cols:
            if cmin <= wc <= cmax and not rm[road_row_bot, wc] and em[road_row_bot, wc]:
                return (Tool.ROAD, wc, road_row_bot)

    # ---- Phase 4: Vertical road connectors every 6 cols ----
    road_cols_top = set(c for c in range(WORLD_W) if 0 <= road_row_top < WORLD_H and rm[road_row_top, c])
    road_cols_bot = set(c for c in range(WORLD_W) if 0 <= road_row_bot < WORLD_H and rm[road_row_bot, c])

    # Connect road_row_top to road_row_bot with vertical roads at intervals
    for vc in range(cmin, cmax + 1, 6):
        if vc in road_cols_top and vc in road_cols_bot:
            for vr in range(road_row_top, road_row_bot + 1):
                if 0 <= vr < WORLD_H and not rm[vr, vc] and em[vr, vc]:
                    return (Tool.ROAD, vc, vr)

    # ---- Phase 5: Place zones ----
    # Place zones above top road and below bottom road
    if wire_cols:
        # Zones above top road (zone center at zone_row_top)
        for zc in range(cmin, cmax + 1, 3):
            if zc in wire_cols_set or any(abs(zc - wc) <= 1 for wc in wire_cols_set):
                road_near = any(abs(zc - rc) <= 2 for rc in road_cols_top)
                if road_near and 2 <= zone_row_top <= WORLD_H - 3:
                    if not nearby_zone(zone_row_top, zc) and zone_area_free(zone_row_top, zc):
                        return (pick_zone(), zc, zone_row_top)

        # Zones below bottom road (zone center at zone_row_bot)
        for zc in range(cmin, cmax + 1, 3):
            if zc in wire_cols_set or any(abs(zc - wc) <= 1 for wc in wire_cols_set):
                road_near = any(abs(zc - rc) <= 2 for rc in road_cols_bot)
                if road_near and 2 <= zone_row_bot <= WORLD_H - 3:
                    if not nearby_zone(zone_row_bot, zc) and zone_area_free(zone_row_bot, zc):
                        return (pick_zone(), zc, zone_row_bot)

        # Inner zones between wire and top road
        inner_top = wire_row - 2
        inner_bot = wire_row + 2
        for zc in range(cmin, cmax + 1, 3):
            if zc in wire_cols_set:
                road_near_t = any(abs(zc - rc) <= 2 for rc in road_cols_top)
                road_near_b = any(abs(zc - rc) <= 2 for rc in road_cols_bot)
                if road_near_t and 2 <= inner_top <= WORLD_H - 3:
                    if not nearby_zone(inner_top, zc) and zone_area_free(inner_top, zc):
                        return (pick_zone(), zc, inner_top)
                if road_near_b and 2 <= inner_bot <= WORLD_H - 3:
                    if not nearby_zone(inner_bot, zc) and zone_area_free(inner_bot, zc):
                        return (pick_zone(), zc, inner_bot)

    # ---- Phase 6: Second power plant when large ----
    if obs.city_pop > 300 and not state.get("plant2_placed", False):
        px2 = max(2, min(WORLD_W - 3, pcx + 20))
        py2 = max(2, min(WORLD_H - 3, pcy))
        clear = all(
            0 <= py2 + dr < WORLD_H and 0 <= px2 + dc < WORLD_W and em[py2 + dr, px2 + dc]
            for dr in [-1, 0, 1] for dc in [-1, 0, 1]
        )
        if clear:
            state["plant2_placed"] = True
            return (Tool.COALPOWER, px2, py2)
        # Wire toward that location
        target_c = min(px2, cmax)
        for wc in range((wire_cols[-1] if wire_cols else pcx) + 1, target_c + 1):
            if 0 <= wire_row < WORLD_H and (em[wire_row, wc]):
                return (Tool.WIRE, wc, wire_row)

    # ---- Phase 7: Second band (second cluster) for large pop ----
    if obs.city_pop > 150:
        wire_row2 = pcy + 14
        wire_row2 = max(2, min(WORLD_H - 3, wire_row2))
        road_row2_top = wire_row2 - 4
        road_row2_bot = wire_row2 + 4
        zone_row2_top = wire_row2 - 7
        zone_row2_bot = wire_row2 + 7
        road_row2_top = max(2, min(WORLD_H - 3, road_row2_top))
        road_row2_bot = max(2, min(WORLD_H - 3, road_row2_bot))
        zone_row2_top = max(2, min(WORLD_H - 3, zone_row2_top))
        zone_row2_bot = max(2, min(WORLD_H - 3, zone_row2_bot))

        wire_cols2 = sorted(c for c in range(WORLD_W) if 0 <= wire_row2 < WORLD_H and wm[wire_row2, c])

        if not wire_cols2:
            # Vertical bridge from wire_row to wire_row2 at pcx
            for vr in range(wire_row + 1, wire_row2):
                if 0 <= vr < WORLD_H and em[vr, pcx]:
                    return (Tool.WIRE, pcx, vr)
            if 0 <= wire_row2 < WORLD_H and em[wire_row2, pcx]:
                return (Tool.WIRE, pcx, wire_row2)
        else:
            min_wc2 = wire_cols2[0]
            max_wc2 = wire_cols2[-1]
            if max_wc2 < cmax:
                return (Tool.WIRE, max_wc2 + 1, wire_row2)
            if min_wc2 > cmin:
                return (Tool.WIRE, min_wc2 - 1, wire_row2)

            # Roads
            if 0 <= road_row2_top < WORLD_H:
                for wc in wire_cols2:
                    if cmin <= wc <= cmax and not rm[road_row2_top, wc] and em[road_row2_top, wc]:
                        return (Tool.ROAD, wc, road_row2_top)
            if 0 <= road_row2_bot < WORLD_H:
                for wc in wire_cols2:
                    if cmin <= wc <= cmax and not rm[road_row2_bot, wc] and em[road_row2_bot, wc]:
                        return (Tool.ROAD, wc, road_row2_bot)

            road_c2_top = set(c for c in range(WORLD_W) if 0 <= road_row2_top < WORLD_H and rm[road_row2_top, c])
            road_c2_bot = set(c for c in range(WORLD_W) if 0 <= road_row2_bot < WORLD_H and rm[road_row2_bot, c])
            wcs2 = set(wire_cols2)

            for zc in range(cmin, cmax + 1, 3):
                road_near = any(abs(zc - rc) <= 2 for rc in road_c2_top)
                if road_near and 2 <= zone_row2_top <= WORLD_H - 3:
                    if not nearby_zone(zone_row2_top, zc) and zone_area_free(zone_row2_top, zc):
                        return (pick_zone(), zc, zone_row2_top)
                road_near = any(abs(zc - rc) <= 2 for rc in road_c2_bot)
                if road_near and 2 <= zone_row2_bot <= WORLD_H - 3:
                    if not nearby_zone(zone_row2_bot, zc) and zone_area_free(zone_row2_bot, zc):
                        return (pick_zone(), zc, zone_row2_bot)

    return None

def act(obs, state):
    """
    Closed-loop policy: every step reads the current tile_map and decides
    the next action reactively. Uses light phase memory only.
    Strategy:
    - Place coal power plant near center
    - Extend wire spine from plant
    - Build roads parallel to wire spine
    - Place zones (RCI mix) adjacent to roads+wire
    - Add more plants/services as population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2
    pop = obs.city_pop

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    wire_row = cy
    road_above = cy - 4
    road_below = cy + 4

    # Dynamic x range based on population
    if pop < 50:
        x_half = 10
    elif pop < 200:
        x_half = 18
    elif pop < 500:
        x_half = 30
    elif pop < 1000:
        x_half = 42
    else:
        x_half = 55

    x_min = max(3, cx - x_half)
    x_max = min(WORLD_W - 4, cx + x_half)

    # --- Phase 1: Place first coal power plant ---
    if not np.any(pm):
        px = max(4, cx - x_half - 4)
        py = wire_row
        return (Tool.COALPOWER, px, py)

    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # --- Phase 2: Build wire spine from plant rightward ---
    wire_on_row = np.where(wm[wire_row, :])[0]

    if len(wire_on_row) == 0:
        # Start wire adjacent to plant
        for dc in range(1, 12):
            c = plant_cx + dc
            if ib(c, wire_row) and em[wire_row, c]:
                return (Tool.WIRE, c, wire_row)
        return None

    min_wc = int(wire_on_row.min())
    max_wc = int(wire_on_row.max())

    # Extend wire right
    if max_wc < x_max:
        nc = max_wc + 1
        if ib(nc, wire_row) and em[wire_row, nc] and not pm[wire_row, nc]:
            return (Tool.WIRE, nc, wire_row)

    # Extend wire left
    if min_wc > x_min:
        nc = min_wc - 1
        if ib(nc, wire_row) and em[wire_row, nc] and not pm[wire_row, nc]:
            return (Tool.WIRE, nc, wire_row)

    # --- Phase 3: Ensure plant is connected to wire spine ---
    plant_connected = False
    for pr, pc in zip(plant_rows, plant_cols):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc2 = pr + dr, pc + dc
                if ib(nc2, nr) and wm[nr, nc2]:
                    plant_connected = True
    if not plant_connected:
        # Connect horizontally
        for bc in range(plant_cx + 1, min_wc + 1):
            if ib(bc, wire_row):
                if wm[wire_row, bc]:
                    break
                if em[wire_row, bc] and not pm[wire_row, bc]:
                    return (Tool.WIRE, bc, wire_row)

    # --- Phase 4: Roads parallel to wire spine ---
    for wc in range(x_min, x_max + 1):
        if wm[wire_row, wc]:
            if ib(wc, road_above) and em[road_above, wc] and not pm[road_above, wc]:
                return (Tool.ROAD, wc, road_above)
            if ib(wc, road_below) and em[road_below, wc] and not pm[road_below, wc]:
                return (Tool.ROAD, wc, road_below)

    # --- Phase 5: Vertical connector roads every 8 cols ---
    for wc in range(x_min, x_max + 1, 8):
        if wm[wire_row, wc]:
            for wr2 in range(road_above, road_below + 1):
                if ib(wc, wr2) and em[wr2, wc] and not pm[wr2, wc] and not wm[wr2, wc] and not rm[wr2, wc]:
                    return (Tool.ROAD, wc, wr2)

    # --- Compute neighbor masks for road and wire coverage ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # --- Phase 6: Place zones reactively near existing zones/roads ---
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(total_zones, 1)
        if ind_count / t < 0.22:
            return Tool.INDUSTRIAL
        if com_count / t < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zy, zx):
        if zy < 1 or zy > WORLD_H - 2 or zx < 1 or zx > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr2, rc2 = zy + dr, zx + dc
                if not (0 <= rr2 < WORLD_H and 0 <= rc2 < WORLD_W):
                    return False
                if not (em[rr2, rc2] or resm[rr2, rc2] or comm[rr2, rc2] or indm[rr2, rc2]):
                    return False
        return True

    # Candidate: empty, near road, near wire/plant, in x range
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, :2] = False
    cand_mask[:, WORLD_W - 2:] = False

    # Also prefer candidates adjacent to existing zones (closed-loop growth)
    any_zone = resm | comm | indm
    nbr_zone = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    nbr_zone[1:, :] |= any_zone[:-1, :]
    nbr_zone[:-1, :] |= any_zone[1:, :]
    nbr_zone[:, 1:] |= any_zone[:, :-1]
    nbr_zone[:, :-1] |= any_zone[:, 1:]

    # Priority: adjacent to existing zones first
    prio_cand = cand_mask & nbr_zone
    cys_p, cxs_p = np.where(prio_cand)
    if len(cxs_p) > 0:
        dists = np.abs(cxs_p.astype(int) - cx) + np.abs(cys_p.astype(int) - wire_row) * 2
        sort_idx = np.argsort(dists)
        for k_idx in range(min(len(cxs_p), 80)):
            k = int(sort_idx[k_idx])
            zx, zy = int(cxs_p[k]), int(cys_p[k])
            if x_min <= zx <= x_max and zone_area_ok(zy, zx):
                return (pick_tool(), zx, zy)

    # Fallback: any candidate near road+wire
    cys_a, cxs_a = np.where(cand_mask)
    if len(cxs_a) > 0:
        dists = np.abs(cxs_a.astype(int) - cx) + np.abs(cys_a.astype(int) - wire_row) * 2
        sort_idx = np.argsort(dists)
        for k_idx in range(min(len(cxs_a), 100)):
            k = int(sort_idx[k_idx])
            zx, zy = int(cxs_a[k]), int(cys_a[k])
            if x_min <= zx <= x_max and zone_area_ok(zy, zx):
                return (pick_tool(), zx, zy)

    # --- Phase 7: Second power plant ---
    plant_tiles = int(np.sum(pm))
    plant_count = max(1, plant_tiles // 6)

    if pop > 150 and plant_count < 2:
        p2x = min(WORLD_W - 5, cx + x_half + 3)
        p2y = wire_row
        if ib(p2x, p2y) and em[p2y, p2x]:
            nearby = any(
                ib(p2x + ddx, p2y + ddy) and pm[p2y + ddy, p2x + ddx]
                for ddy in range(-7, 8) for ddx in range(-7, 8)
            )
            if not nearby:
                return (Tool.COALPOWER, p2x, p2y)
        # Extend wire to reach it
        if max_wc < p2x - 2:
            nc = max_wc + 1
            if ib(nc, wire_row) and em[wire_row, nc] and not pm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    if pop > 500 and plant_count < 3:
        p3x = max(4, plant_cx - 1)
        p3y = wire_row + 18
        if ib(p3x, p3y) and em[p3y, p3x]:
            nearby = any(
                ib(p3x + ddx, p3y + ddy) and pm[p3y + ddy, p3x + ddx]
                for ddy in range(-7, 8) for ddx in range(-7, 8)
            )
            if not nearby:
                return (Tool.COALPOWER, p3x, p3y)

    # --- Phase 8: Services ---
    if pop > 200:
        fx, fy = cx, cy - 12
        if ib(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
    if pop > 350:
        px2, py2 = cx + 12, cy + 12
        if ib(px2, py2) and em[py2, px2]:
            return (Tool.POLICESTATION, px2, py2)
    if pop > 600:
        fx2, fy2 = cx - 12, cy + 12
        if ib(fx2, fy2) and em[fy2, fx2]:
            return (Tool.FIRESTATION, fx2, fy2)

    # --- Phase 9: Reactively extend road near existing roads ---
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = int(obs.step * 13) % len(road_xs_arr)
        rx_s = int(road_xs_arr[step_k])
        ry_s = int(road_ys_arr[step_k])
        for dy2, dx2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx2, ny2 = rx_s + dx2, ry_s + dy2
            if ib(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                if nbr_wire[ny2, nx2] and x_min <= nx2 <= x_max:
                    return (Tool.ROAD, nx2, ny2)

    # --- Phase 10: Reactively extend wire ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k = int(obs.step * 7) % len(wire_xs_arr)
        wx_s = int(wire_xs_arr[step_k])
        wy_s = int(wire_ys_arr[step_k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = wx_s + dx2, wy_s + dy2
            if ib(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                if x_min <= nx2 <= x_max:
                    return (Tool.WIRE, nx2, ny2)

    # --- Phase 11: Second wire row for more coverage at high pop ---
    if pop > 400:
        wire2_row = cy + 10
        for wc in range(x_min, x_max + 1):
            if wm[wire_row, wc]:
                if ib(wc, wire2_row) and em[wire2_row, wc] and not pm[wire2_row, wc]:
                    return (Tool.WIRE, wc, wire2_row)
        for wc in range(x_min, x_max + 1, 10):
            if wm[wire_row, wc]:
                for wr3 in range(wire_row + 1, wire2_row + 1):
                    if ib(wc, wr3) and em[wr3, wc] and not pm[wr3, wc] and not wm[wr3, wc]:
                        return (Tool.WIRE, wc, wr3)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder.
    Reads current tile_map every step and adapts placements.
    Strategy:
    1. Place coal plant if none exists
    2. Grow wire spine vertically from plant
    3. Grow flanking roads adjacent to wire spine
    4. Place balanced zones (R/C/I) near roads+power
    5. Add second plant and services as city grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # ---- Phase 1: Ensure power plant ----
    plant_ys, plant_xs = np.where(pm)
    if len(plant_xs) == 0:
        return (Tool.COALPOWER, 60, 50)

    # Primary plant center (centroid of plant tiles)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    # Zone counts for balance
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Wire spine just to the right of plant center
    wire_col = px + 2

    # Dynamic spine extent based on population
    pop_ext = min(25, obs.city_pop // 10)
    spine_top = max(3, py - 15 - pop_ext)
    spine_bot = min(WORLD_H - 4, py + 15 + pop_ext)

    # ---- Phase 2: Grow wire spine (closed-loop: check current wire positions) ----
    wire_rows = [r for r in range(WORLD_H)
                 if in_bounds(wire_col, r) and bool(wm[r, wire_col])]

    power_map = pm | wm

    if len(wire_rows) == 0:
        # Seed wire adjacent to plant
        for dy in range(-2, 3):
            ny = py + dy
            if in_bounds(wire_col, ny) and bool(em[ny, wire_col]) and not bool(pm[ny, wire_col]):
                # Check adjacency to plant
                for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
                    nx2, ny2 = wire_col+ddx, ny+ddy
                    if in_bounds(nx2, ny2) and bool(pm[ny2, nx2]):
                        return (Tool.WIRE, wire_col, ny)
        # Force seed at plant row
        if in_bounds(wire_col, py) and bool(em[py, wire_col]) and not bool(pm[py, wire_col]):
            return (Tool.WIRE, wire_col, py)
    else:
        min_wr = min(wire_rows)
        max_wr = max(wire_rows)
        # Grow spine - alternate up/down based on step parity
        if obs.step % 2 == 0 and max_wr < spine_bot:
            nr = max_wr + 1
            if in_bounds(wire_col, nr) and bool(em[nr, wire_col]) and not bool(pm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        if min_wr > spine_top:
            nr = min_wr - 1
            if in_bounds(wire_col, nr) and bool(em[nr, wire_col]) and not bool(pm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        if max_wr < spine_bot:
            nr = max_wr + 1
            if in_bounds(wire_col, nr) and bool(em[nr, wire_col]) and not bool(pm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    # ---- Phase 3: Grow flanking roads (closed-loop: read current road positions) ----
    road_col_l = wire_col - 1
    road_col_r = wire_col + 1

    # Find wire rows that lack flanking roads
    if len(wire_rows) > 0:
        # Deterministic but reactive: cycle through wire rows
        step_k = obs.step % max(len(wire_rows), 1)
        for off in range(min(len(wire_rows), 4)):
            wr = wire_rows[(step_k + off) % len(wire_rows)]
            if in_bounds(road_col_l, wr) and bool(em[wr, road_col_l]) and not bool(pm[wr, road_col_l]):
                return (Tool.ROAD, road_col_l, wr)
            if in_bounds(road_col_r, wr) and bool(em[wr, road_col_r]) and not bool(pm[wr, road_col_r]):
                return (Tool.ROAD, road_col_r, wr)

    # ---- Phase 4: Place zones near roads+power ----
    # Compute neighborhood proximity masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-7, 8):
        for dx in range(-7, 8):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not in_bounds(nc2, nr2):
                    return False
                if not (bool(em[nr2, nc2]) or bool(zone_tiles[nr2, nc2])):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, :3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Reactive key: changes as map evolves
        key = int(obs.tile_map[45:55, 55:70].sum()) % max(len(cxs), 1)
        # Also prioritize by distance to wire column
        dists = np.abs(cxs - wire_col) + np.abs(cys - py) // 4
        order = np.argsort(dists)
        checked = 0
        for i in range(len(order)):
            k = order[(key + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 60:
                break

    # ---- Phase 5: Second power plant when city grows ----
    if obs.city_pop > 300 or total_zones > 12:
        p2x = px + 18
        p2y = py
        if in_bounds(p2x, p2y):
            nearby = any(
                in_bounds(p2x+dx, p2y+dy) and bool(pm[p2y+dy, p2x+dx])
                for dy in range(-6, 7) for dx in range(-6, 7)
                if in_bounds(p2x+dx, p2y+dy)
            )
            if not nearby:
                if bool(em[p2y, p2x]):
                    return (Tool.COALPOWER, p2x, p2y)
                # Wire bridge to second plant location
                for wc in range(wire_col + 1, p2x):
                    if in_bounds(wc, py) and bool(em[py, wc]) and not bool(pm[py, wc]):
                        return (Tool.WIRE, wc, py)

    # ---- Phase 6: Services ----
    if obs.city_pop > 200:
        for fsx, fsy in [(px - 8, py - 10), (px + 10, py - 10)]:
            if in_bounds(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)
    if obs.city_pop > 500:
        for psx, psy in [(px - 8, py + 10), (px + 10, py + 10)]:
            if in_bounds(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    # ---- Fallback: extend roads from existing road tiles near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (obs.step * 11 + int(obs.city_pop * 3)) % len(road_xs2)
        for off in range(min(len(road_xs2), 20)):
            k = (step_k + off * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- Fallback: expand wire from existing wires ----
    wire_ys2, wire_xs2 = np.where(wm)
    if len(wire_xs2) > 0:
        step_k2 = (obs.step * 13) % len(wire_xs2)
        for off in range(min(len(wire_xs2), 15)):
            k = (step_k2 + off * 5) % len(wire_xs2)
            wx2, wy2 = int(wire_xs2[k]), int(wire_ys2[k])
            for dx3, dy3 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if in_bounds(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def act(obs, state):
    """
    Closed-loop policy: each step reads the current map and decides what to place next.
    Strategy: compact grid layout with coal plant, wire spine, road spine, and zones.
    More reactive: scans existing infrastructure each step to decide next action.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    all_zones = resm | comm | indm
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        if com_count / t < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_area_clear(zr, zc):
        """3x3 area free of plants/roads/wires (zones ok, empty ok)"""
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                tile = tm[rr, rc]
                # Block if road, wire, or plant is in the way
                if rm[rr, rc] or wm[rr, rc] or pm[rr, rc]:
                    return False
        return True

    def zone_nearby(zr, zc, radius=3):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(all_zones[r0:r1, c0:c1])

    def has_wire_nearby(zr, zc, radius=5):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=5):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    # Fixed anchor: plant at (60, 50) - center of map
    PLANT_X, PLANT_Y = 60, 50

    # --- Phase 0: Place coal power plant ---
    if not np.any(pm):
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    # Find plant center from map
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Layout columns relative to plant
    wire_col = plant_cx + 3    # wire spine (east of plant)
    road_col = plant_cx + 5    # road spine
    zone_col_r = plant_cx + 9  # right zone column
    zone_col_l = plant_cx - 2  # left zone column (close to plant)

    wire_col = max(2, min(WORLD_W - 3, wire_col))
    road_col = max(2, min(WORLD_W - 3, road_col))
    zone_col_r = max(2, min(WORLD_W - 3, zone_col_r))
    zone_col_l = max(2, min(WORLD_W - 3, zone_col_l))

    # Adaptive extent based on population
    pop = obs.city_pop
    if pop < 100:
        extent = 15
    elif pop < 300:
        extent = 30
    elif pop < 600:
        extent = 50
    elif pop < 1000:
        extent = 70
    else:
        extent = 85

    spine_top = plant_cy + 3
    spine_bot = min(WORLD_H - 4, plant_cy + extent)

    # --- Phase 1: Connect wire from plant to wire_col ---
    # Check if wire_col already has wire adjacent to plant
    wire_connected = False
    for dc in range(1, wire_col - plant_cx + 1):
        cc = plant_cx + dc
        if 0 <= cc < WORLD_W:
            if wm[plant_cy, cc] or pm[plant_cy, cc]:
                if cc >= wire_col:
                    wire_connected = True
                    break
                # partial - need to extend
                break

    # Horizontal bridge from plant to wire_col at plant_cy row
    for cc in range(plant_cx + 3, wire_col + 1):
        if 0 <= cc < WORLD_W:
            if not wm[plant_cy, cc] and not pm[plant_cy, cc]:
                if em[plant_cy, cc]:
                    return (Tool.WIRE, cc, plant_cy)

    # --- Phase 2: Extend wire spine downward ---
    wire_rows_on_col = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])
    if not wire_rows_on_col:
        # Start wire at plant_cy (should be connected already, just place)
        if 0 <= spine_top < WORLD_H and em[spine_top, wire_col]:
            return (Tool.WIRE, wire_col, spine_top)
        return (Tool.WIRE, wire_col, plant_cy)

    max_wire_row = max(wire_rows_on_col)
    if max_wire_row < spine_bot:
        nr = max_wire_row + 1
        if 0 <= nr < WORLD_H:
            if em[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)
            elif not pm[nr, wire_col]:
                # Try skipping obstacle
                for skip in range(2, 5):
                    if nr + skip < WORLD_H and em[nr + skip, wire_col]:
                        return (Tool.WIRE, wire_col, nr + skip)

    # --- Phase 3: Extend road spine downward ---
    road_rows_on_col = sorted([r for r in range(WORLD_H) if rm[r, road_col]])
    target_road_bot = min(max_wire_row + 1, spine_bot)

    if not road_rows_on_col:
        if 0 <= spine_top < WORLD_H and em[spine_top, road_col]:
            return (Tool.ROAD, road_col, spine_top)
        return (Tool.ROAD, road_col, spine_top + 1)

    max_road_row = max(road_rows_on_col)
    if max_road_row < target_road_bot:
        nr = max_road_row + 1
        if 0 <= nr < WORLD_H:
            if em[nr, road_col]:
                return (Tool.ROAD, road_col, nr)
            elif not pm[nr, road_col]:
                for skip in range(2, 4):
                    if nr + skip < WORLD_H and em[nr + skip, road_col]:
                        return (Tool.ROAD, road_col, nr + skip)

    road_rows_set = set(road_rows_on_col)

    # --- Phase 4: Place zones adjacent to wire+road spine ---
    # For each wire row, try placing zones on right and left
    for wr in wire_rows_on_col:
        if wr < spine_top or wr > spine_bot:
            continue
        # Need road access
        road_near = any(abs(wr - rr) <= 3 for rr in road_rows_set)
        if not road_near:
            continue

        # Try right zone column
        for zc in [zone_col_r, zone_col_l]:
            if zone_area_clear(wr, zc) and not zone_nearby(wr, zc, 2):
                if has_wire_nearby(wr, zc) and has_road_nearby(wr, zc):
                    return (pick_tool(), zc, wr)

    # --- Phase 5: Horizontal wires to connect right zones to spine ---
    for wr in wire_rows_on_col:
        if wr < spine_top or wr > spine_bot:
            continue
        # Extend right from wire_col toward zone_col_r
        for wc in range(wire_col + 1, zone_col_r + 2):
            if 0 <= wc < WORLD_W:
                if wm[wr, wc]:
                    break
                if em[wr, wc] and not rm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc] and not wm[wr, wc]:
                    break

    # --- Phase 6: Horizontal roads to connect right zones ---
    for rr in list(road_rows_set):
        if rr < spine_top or rr > spine_bot:
            continue
        for rc in range(road_col + 1, zone_col_r + 2):
            if 0 <= rc < WORLD_W:
                if rm[rr, rc]:
                    break
                if em[rr, rc] and not pm[rr, rc] and not wm[rr, rc]:
                    return (Tool.ROAD, rc, rr)
                elif not em[rr, rc]:
                    break

    # --- Phase 7: Second coal plant if needed ---
    n_plant_tiles = int(np.sum(pm))
    if pop > 400 and n_plant_tiles < 9:
        # Try placing second plant above first
        px2, py2 = plant_cx, max(4, plant_cy - 8)
        area_ok = True
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = py2 + dr, px2 + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if not (em[rr, rc] or pm[rr, rc]):
                        area_ok = False
        if area_ok:
            return (Tool.COALPOWER, px2, py2)

    # --- Phase 8: Extend wire upward for more coverage ---
    if pop >= 150:
        wire_rows_up = [r for r in range(WORLD_H) if wm[r, wire_col] and r < plant_cy]
        min_wire_row = min(wire_rows_on_col) if wire_rows_on_col else plant_cy
        spine_top_up = max(4, plant_cy - extent // 2)
        if min_wire_row > spine_top_up:
            nr = min_wire_row - 1
            if 0 <= nr < WORLD_H and em[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

        # Road upward too
        min_road_row = min(road_rows_on_col) if road_rows_on_col else plant_cy
        if min_road_row > spine_top_up + 1:
            nr = min_road_row - 1
            if 0 <= nr < WORLD_H and em[nr, road_col]:
                return (Tool.ROAD, road_col, nr)

        # Place zones above plant
        wire_rows_all = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])
        road_rows_all = set(r for r in range(WORLD_H) if rm[r, road_col])
        for wr in wire_rows_all:
            if wr >= plant_cy:
                continue
            road_near = any(abs(wr - rr) <= 3 for rr in road_rows_all)
            if not road_near:
                continue
            for zc in [zone_col_r, zone_col_l]:
                if zone_area_clear(wr, zc) and not zone_nearby(wr, zc, 2):
                    if has_wire_nearby(wr, zc) and has_road_nearby(wr, zc):
                        return (pick_tool(), zc, wr)

    # --- Phase 9: Dense zone filling - try every 3 rows along wire ---
    wire_rows_all = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])
    road_rows_all = set(r for r in range(WORLD_H) if rm[r, road_col])
    if wire_rows_all:
        for wr in range(wire_rows_all[0], wire_rows_all[-1] + 1, 3):
            wire_near = any(abs(wr - wr2) <= 2 for wr2 in wire_rows_all)
            road_near = any(abs(wr - rr) <= 2 for rr in road_rows_all)
            if wire_near and road_near:
                for zc in [zone_col_r, zone_col_l, zone_col_r - 4, zone_col_l - 4]:
                    zc = max(2, min(WORLD_W - 3, zc))
                    if zone_area_clear(wr, zc) and not zone_nearby(wr, zc, 2):
                        if has_wire_nearby(wr, zc) and has_road_nearby(wr, zc):
                            return (pick_tool(), zc, wr)

    return None

def act(obs, state):
    """
    Hybrid policy combining best of both parents:
    - Two neighborhoods (left ~x=35, right ~x=85) each with their own coal plant
    - Vertical wire spine from plant, road column adjacent
    - Zones on both sides of road/wire with proper power connections
    - Dynamic expansion based on population
    - Police/fire stations for happiness
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    pop = obs.city_pop

    res_count = int(np.sum(res_m)) // 9
    com_count = int(np.sum(com_m)) // 9
    ind_count = int(np.sum(ind_m)) // 9
    total_zones = res_count + com_count + ind_count + 1

    def pick_zone_type():
        r_frac = res_count / total_zones
        c_frac = com_count / total_zones
        i_frac = ind_count / total_zones
        if r_frac < 0.40:
            return Tool.RESIDENTIAL
        elif c_frac < 0.30:
            return Tool.COMMERCIAL
        elif i_frac < 0.30:
            return Tool.INDUSTRIAL
        else:
            return Tool.RESIDENTIAL

    def area_free(cx, cy):
        for dy in [-1, 0, 1]:
            for dx in [-1, 0, 1]:
                r, c = cy + dy, cx + dx
                if r < 0 or r >= WORLD_H or c < 0 or c >= WORLD_W:
                    return False
                if not em[r, c]:
                    return False
        return True

    def zone_exists_near(cx, cy, zmask, radius=2):
        r0, r1 = max(0, cy - radius), min(WORLD_H, cy + radius + 1)
        c0, c1 = max(0, cx - radius), min(WORLD_W, cx + radius + 1)
        return np.any(zmask[r0:r1, c0:c1])

    # Define two neighborhoods
    neighborhoods = [
        {'plant': (35, 50), 'wire_col': 37, 'road_col': 39,
         'left_zone_col': 34, 'right_zone_col': 42, 'cy': 50},
        {'plant': (82, 50), 'wire_col': 84, 'road_col': 86,
         'left_zone_col': 81, 'right_zone_col': 89, 'cy': 50},
    ]

    # Dynamic vertical span
    base_span = 12
    extra_span = min(22, pop // 30)
    target_span = base_span + extra_span

    for nb in neighborhoods:
        px, py = nb['plant']
        wire_col = nb['wire_col']
        road_col = nb['road_col']
        left_zone_col = nb['left_zone_col']
        right_zone_col = nb['right_zone_col']
        cy = nb['cy']

        tmin = max(2, cy - target_span)
        tmax = min(WORLD_H - 3, cy + target_span)

        # Check if plant exists near this neighborhood
        p0r = max(0, py - 2); p1r = min(WORLD_H, py + 3)
        p0c = max(0, px - 2); p1c = min(WORLD_W, px + 3)
        has_local_plant = np.any(pm[p0r:p1r, p0c:p1c])

        if not has_local_plant:
            if area_free(px, py):
                return (Tool.COALPOWER, px, py)
            else:
                for dy in range(-4, 5):
                    for dx in range(-4, 5):
                        npx, npy = px + dx, py + dy
                        if 1 <= npx <= WORLD_W - 2 and 1 <= npy <= WORLD_H - 2:
                            if area_free(npx, npy):
                                return (Tool.COALPOWER, npx, npy)
            continue

        # Wire spine: vertical column
        wire_rows_in_col = [r for r in range(WORLD_H) if wm[r, wire_col]]
        wire_rows_set = set(wire_rows_in_col)

        if not wire_rows_in_col:
            # Place first wire adjacent to plant
            for try_r in [py, py - 1, py + 1]:
                if 0 <= try_r < WORLD_H and (em[try_r, wire_col] or wm[try_r, wire_col]):
                    if em[try_r, wire_col]:
                        return (Tool.WIRE, wire_col, try_r)
            continue

        min_wr = min(wire_rows_in_col)
        max_wr = max(wire_rows_in_col)

        # Extend wire spine downward
        if max_wr < tmax:
            nr = max_wr + 1
            if 0 < nr < WORLD_H and em[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)
        # Extend wire spine upward
        if min_wr > tmin:
            nr = min_wr - 1
            if 0 <= nr < WORLD_H and em[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

        # Road column parallel to wire
        road_rows_set = set(r for r in range(WORLD_H) if rm[r, road_col])

        for wr in wire_rows_in_col:
            if wr not in road_rows_set and 0 <= road_col < WORLD_W:
                if em[wr, road_col]:
                    return (Tool.ROAD, road_col, wr)

        # Place zones on both sides
        for zr in sorted(wire_rows_in_col):
            road_nearby = any(abs(zr - rr) <= 2 for rr in road_rows_set)
            if not road_nearby:
                continue
            for zc in [left_zone_col, right_zone_col]:
                if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                    if not zone_exists_near(zc, zr, res_m | com_m | ind_m, 1):
                        if area_free(zc, zr):
                            return (pick_zone_type(), zc, zr)

        # Lateral wires from spine to left zones (power connection)
        for wr in wire_rows_in_col:
            for wc in range(wire_col - 1, max(left_zone_col - 2, 0), -1):
                if 0 <= wc < WORLD_W and em[wr, wc] and not wm[wr, wc]:
                    return (Tool.WIRE, wc, wr)

        # Lateral roads from road col to right zones
        for wr in wire_rows_in_col:
            for rc in range(road_col + 1, min(right_zone_col + 2, WORLD_W)):
                if 0 <= rc < WORLD_W and em[wr, rc] and not rm[wr, rc]:
                    return (Tool.ROAD, rc, wr)

    # Police/fire stations for happiness
    if pop > 150:
        for px, py in [(35, 44), (82, 44)]:
            pol_nearby = False
            for dy in range(-8, 9):
                for dx in range(-8, 9):
                    r, c = py + dy, px + dx
                    if 0 <= r < WORLD_H and 0 <= c < WORLD_W:
                        if 600 <= int(tm[r, c]) <= 750:
                            pol_nearby = True
                            break
                if pol_nearby:
                    break
            if not pol_nearby and area_free(px, py):
                return (Tool.POLICESTATION, px, py)

    if pop > 300:
        for px, py in [(35, 57), (82, 57)]:
            fire_nearby = False
            for dy in range(-8, 9):
                for dx in range(-8, 9):
                    r, c = py + dy, px + dx
                    if 0 <= r < WORLD_H and 0 <= c < WORLD_W:
                        if 519 <= int(tm[r, c]) <= 598:
                            fire_nearby = True
                            break
                if fire_nearby:
                    break
            if not fire_nearby and area_free(px, py):
                return (Tool.FIRESTATION, px, py)

    # Third cluster in middle when pop is high
    if pop >= 350:
        wire_col3 = 59
        road_col3 = 61
        left_zone_col3 = 56
        right_zone_col3 = 64
        cy3 = 50

        tmin3 = max(2, cy3 - target_span)
        tmax3 = min(WORLD_H - 3, cy3 + target_span)

        # Check plant
        has_plant3 = np.any(pm[max(0, cy3-2):min(WORLD_H, cy3+3),
                               max(0, wire_col3-4):min(WORLD_W, wire_col3+2)])

        if not has_plant3:
            px3, py3 = wire_col3 - 3, cy3
            if area_free(px3, py3):
                return (Tool.COALPOWER, px3, py3)
        else:
            wire_rows3 = [r for r in range(WORLD_H) if wm[r, wire_col3]]
            if not wire_rows3:
                if em[cy3, wire_col3]:
                    return (Tool.WIRE, wire_col3, cy3)
            else:
                min_wr3 = min(wire_rows3)
                max_wr3 = max(wire_rows3)
                if max_wr3 < tmax3:
                    nr = max_wr3 + 1
                    if 0 < nr < WORLD_H and em[nr, wire_col3]:
                        return (Tool.WIRE, wire_col3, nr)
                if min_wr3 > tmin3:
                    nr = min_wr3 - 1
                    if 0 <= nr < WORLD_H and em[nr, wire_col3]:
                        return (Tool.WIRE, wire_col3, nr)

                road_rows3 = set(r for r in range(WORLD_H) if rm[r, road_col3])
                for wr in wire_rows3:
                    if wr not in road_rows3 and em[wr, road_col3]:
                        return (Tool.ROAD, road_col3, wr)

                for zr in sorted(wire_rows3):
                    road_nearby3 = any(abs(zr - rr) <= 2 for rr in road_rows3)
                    if not road_nearby3:
                        continue
                    for zc in [left_zone_col3, right_zone_col3]:
                        if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                            if not zone_exists_near(zc, zr, res_m | com_m | ind_m, 1):
                                if area_free(zc, zr):
                                    return (pick_zone_type(), zc, zr)

                for wr in wire_rows3:
                    for wc in range(wire_col3 - 1, max(left_zone_col3 - 2, 0), -1):
                        if 0 <= wc < WORLD_W and em[wr, wc]:
                            return (Tool.WIRE, wc, wr)
                for wr in wire_rows3:
                    for rc in range(road_col3 + 1, min(right_zone_col3 + 2, WORLD_W)):
                        if 0 <= rc < WORLD_W and em[wr, rc]:
                            return (Tool.ROAD, rc, wr)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads current map each step and places next tile
    based on what already exists. Uses a simple phase counter in state.

    Strategy:
    - One coal power plant at fixed location
    - Grow wire outward from plant, following BFS-like frontier
    - Grow road parallel to wire
    - Place zones adjacent to roads that have wire nearby
    """
    tm = obs.tile_map
    step = obs.step

    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    # Fixed anchor points
    PLANT_X, PLANT_Y = 20, 50  # power plant center
    ROAD_Y1 = 47  # road above spine
    ROAD_Y2 = 53  # road below spine
    WIRE_Y = 50   # wire spine row

    # ---- Phase 0: Place power plant ----
    if not np.any(pm):
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    # ---- Phase 1: Extend wire spine rightward from plant ----
    # Find rightmost wire on WIRE_Y row
    wire_row = wm[WIRE_Y, :]
    plant_row = pm[WIRE_Y, :]  # plant tiles on wire row

    # Find rightmost occupied (wire or plant) on wire spine row
    occupied_spine = np.where(wm[WIRE_Y, :] | pm[WIRE_Y, :])[0]
    if len(occupied_spine) == 0:
        # Place wire just right of plant (plant center at PLANT_X, footprint PLANT_X-1..PLANT_X+1)
        return (Tool.WIRE, PLANT_X + 2, WIRE_Y)

    rightmost_wire = occupied_spine.max()
    # Extend wire to col 100
    TARGET_WIRE_END = 100
    if rightmost_wire < TARGET_WIRE_END:
        nx = rightmost_wire + 1
        if 0 <= nx < WORLD_W and em[WIRE_Y, nx]:
            return (Tool.WIRE, nx, WIRE_Y)
        elif 0 <= nx < WORLD_W and not wm[WIRE_Y, nx]:
            # bulldoze and place wire - just place (auto-bulldoze on)
            return (Tool.WIRE, nx, WIRE_Y)

    # ---- Phase 2: Extend road spines ----
    for road_y in [ROAD_Y1, ROAD_Y2]:
        road_row_occ = np.where(rm[road_y, :] | pm[road_y, :])[0]
        if len(road_row_occ) == 0:
            # Start road near plant
            return (Tool.ROAD, PLANT_X + 2, road_y)
        rightmost_road = road_row_occ.max()
        if rightmost_road < TARGET_WIRE_END + 2:
            nx = rightmost_road + 1
            if 0 <= nx < WORLD_W:
                return (Tool.ROAD, nx, road_y)

    # ---- Phase 3: Add vertical connector roads every 6 cols ----
    for cx in range(PLANT_X + 3, TARGET_WIRE_END + 3, 6):
        if cx >= WORLD_W:
            break
        for cy in range(ROAD_Y1, ROAD_Y2 + 1):
            if not rm[cy, cx] and not wm[cy, cx] and 0 <= cy < WORLD_H:
                return (Tool.ROAD, cx, cy)

    # ---- Phase 4: Add vertical wires from spine to zone rows ----
    # Zone rows above: WIRE_Y - 5, -8, -11, -14
    # Zone rows below: WIRE_Y + 5, +8, +11, +14
    zone_rows_above = [WIRE_Y - 5, WIRE_Y - 8, WIRE_Y - 11]
    zone_rows_below = [WIRE_Y + 5, WIRE_Y + 8, WIRE_Y + 11]
    zone_cols = list(range(PLANT_X + 3, TARGET_WIRE_END + 3, 6))

    # Extend wire vertically at zone columns
    for zc in zone_cols:
        if zc >= WORLD_W:
            break
        # Check wire exists on spine at this col
        if not wm[WIRE_Y, zc]:
            continue
        # Extend upward
        for zr in zone_rows_above:
            if zr < 0:
                continue
            # Check if wire branch exists
            # Walk from spine up to zr
            for wy in range(WIRE_Y - 1, zr - 1, -1):
                if not wm[wy, zc] and not pm[wy, zc]:
                    if em[wy, zc]:
                        return (Tool.WIRE, zc, wy)
                    break  # blocked, skip
        # Extend downward
        for zr in zone_rows_below:
            if zr >= WORLD_H:
                continue
            for wy in range(WIRE_Y + 1, zr + 2):
                if wy >= WORLD_H:
                    break
                if not wm[wy, zc] and not pm[wy, zc]:
                    if em[wy, zc]:
                        return (Tool.WIRE, zc, wy)
                    break

    # ---- Phase 5: Place zones adjacent to roads with wire nearby ----
    res_pos = list(zip(*np.where(res_mask(tm)))) if np.any(res_mask(tm)) else []
    com_pos = list(zip(*np.where(com_mask(tm)))) if np.any(com_mask(tm)) else []
    ind_pos = list(zip(*np.where(ind_mask(tm)))) if np.any(ind_mask(tm)) else []
    all_zones = set((r, c) for r, c in res_pos + com_pos + ind_pos)

    res_count = len(res_pos)
    com_count = len(com_pos)
    ind_count = len(ind_pos)
    total_zones = res_count + com_count + ind_count + 1

    def pick_zone_type(zr, zc):
        if com_count / total_zones < 0.25:
            return Tool.COMMERCIAL
        elif ind_count / total_zones < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def has_road_nearby(zr, zc, radius=3):
        r0, r1 = max(0, zr - radius), min(WORLD_H, zr + radius + 1)
        c0, c1 = max(0, zc - radius), min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    def has_wire_nearby(zr, zc, radius=5):
        r0, r1 = max(0, zr - radius), min(WORLD_H, zr + radius + 1)
        c0, c1 = max(0, zc - radius), min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    # Try placing zones at candidate positions
    all_zone_rows = zone_rows_above + zone_rows_below
    for zr in all_zone_rows:
        if zr < 1 or zr >= WORLD_H - 1:
            continue
        for zc in zone_cols:
            if zc < 1 or zc >= WORLD_W - 1:
                continue
            # Skip if zone already nearby
            already = any(abs(zr - er) <= 2 and abs(zc - ec) <= 2 for er, ec in all_zones)
            if already:
                continue
            if zone_area_free(zr, zc) and has_road_nearby(zr, zc) and has_wire_nearby(zr, zc):
                return (pick_zone_type(zr, zc), zc, zr)

    # ---- Phase 6: If city is growing, add more zone rows ----
    if obs.city_pop > 50 or step > obs.n_steps // 2:
        extra_rows = [WIRE_Y - 14, WIRE_Y + 14, WIRE_Y - 17, WIRE_Y + 17]
        for zr in extra_rows:
            if zr < 1 or zr >= WORLD_H - 1:
                continue
            for zc in zone_cols:
                if zc < 1 or zc >= WORLD_W - 1:
                    continue
                already = any(abs(zr - er) <= 2 and abs(zc - ec) <= 2 for er, ec in all_zones)
                if already:
                    continue
                if zone_area_free(zr, zc) and has_road_nearby(zr, zc, radius=5) and has_wire_nearby(zr, zc, radius=7):
                    return (pick_zone_type(zr, zc), zc, zr)

    # ---- Phase 7: Add more road connectors to improve access ----
    # Add roads from zone cols toward zone rows
    for zc in zone_cols:
        if zc >= WORLD_W:
            break
        for zr in zone_rows_above + zone_rows_below:
            if zr < 0 or zr >= WORLD_H:
                continue
            # Road just outside zone footprint (zone center zr, footprint zr-1..zr+1)
            # Place road at zr+2 (below above-zones) or zr-2 (above below-zones)
            if zr < WIRE_Y:
                road_access_r = zr + 2
            else:
                road_access_r = zr - 2
            if 0 <= road_access_r < WORLD_H and not rm[road_access_r, zc]:
                if em[road_access_r, zc]:
                    return (Tool.ROAD, zc, road_access_r)

    # ---- Default: scan for any unpowered zone and lay wire toward it ----
    # Find zones that might not have wire nearby
    for zr, zc in res_pos + com_pos + ind_pos:
        if not has_wire_nearby(zr, zc, radius=3):
            # Find nearest wire
            wire_positions = list(zip(*np.where(wm)))
            if wire_positions:
                dists = [(abs(zr - wr) + abs(zc - wc), wr, wc) for wr, wc in wire_positions]
                dists.sort()
                _, wr, wc = dists[0]
                # Step toward zone from wire
                if wr < zr and em[wr + 1, wc]:
                    return (Tool.WIRE, wc, wr + 1)
                elif wr > zr and em[wr - 1, wc]:
                    return (Tool.WIRE, wc, wr - 1)
                elif wc < zc and em[wr, wc + 1]:
                    return (Tool.WIRE, wc + 1, wr)
                elif wc > zc and em[wr, wc - 1]:
                    return (Tool.WIRE, wc - 1, wr)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Read current map state each step
    - Extend wire/road from existing frontier, don't precompute
    - Place zones adjacent to existing road+wire coverage
    - Scale power plants based on observed zone count
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Step 1: Ensure at least one power plant exists ---
    if not np.any(pm):
        return (Tool.COALPOWER, 60, 50)

    plant_ys, plant_xs = np.where(pm)
    # Primary plant center
    px0 = int(plant_xs[0])
    py0 = int(plant_ys[0])
    # Use mean for multi-plant scenarios
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Step 2: Wire spine column just right of plant ---
    wire_col = px0 + 2

    # Dynamic vertical span based on city pop
    base_span = 18
    extra_span = min(30, obs.city_pop // 12)
    target_span = base_span + extra_span
    tmin = max(2, py0 - target_span)
    tmax = min(WORLD_H - 3, py0 + target_span)

    # Find current wire extent in the wire column
    wire_in_col = [r for r in range(WORLD_H) if 0 <= wire_col < WORLD_W and wm[r, wire_col]]

    # --- Build vertical wire spine reactively ---
    if not wire_in_col:
        # Start wire adjacent to plant
        for dy in range(-2, 3):
            ny = py0 + dy
            if in_bounds(wire_col, ny) and (em[ny, wire_col] or wm[ny, wire_col]) and not pm[ny, wire_col]:
                return (Tool.WIRE, wire_col, ny)
    else:
        min_wr = min(wire_in_col)
        max_wr = max(wire_in_col)
        # Extend downward if needed
        if max_wr < tmax:
            nr = max_wr + 1
            if in_bounds(wire_col, nr) and not pm[nr, wire_col] and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        # Extend upward if needed
        if min_wr > tmin:
            nr = min_wr - 1
            if in_bounds(wire_col, nr) and not pm[nr, wire_col] and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    # --- Step 3: Road columns flanking wire spine ---
    # Right road at wire_col+3, left road at wire_col-3
    # This gives 3-wide zone slots on each side
    road_col_r = wire_col + 3
    road_col_l = wire_col - 3

    # Build road columns along wire rows
    for wr in wire_in_col:
        if not (tmin <= wr <= tmax):
            continue
        if in_bounds(road_col_r, wr) and em[wr, road_col_r]:
            return (Tool.ROAD, road_col_r, wr)
        if in_bounds(road_col_l, wr) and em[wr, road_col_l]:
            return (Tool.ROAD, road_col_l, wr)

    # --- Step 4: Horizontal connecting roads every 4 rows ---
    if wire_in_col:
        for wr in wire_in_col:
            if not (tmin <= wr <= tmax):
                continue
            if (wr - tmin) % 4 == 0:
                for rc in range(road_col_l, road_col_r + 1):
                    if in_bounds(rc, wr) and not rm[wr, rc] and em[wr, rc] and not pm[wr, rc]:
                        return (Tool.ROAD, rc, wr)

    # --- Step 5: Compute proximity masks from current map state ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    all_zone_m = resm | comm | indm
    zone_rows, zone_cols = np.where(all_zone_m)
    zone_set = set(zip(zone_rows.tolist(), zone_cols.tolist()))

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    # --- Step 6: Place zones reactively near road+wire coverage ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Sort by distance to wire spine center (prefer compact cluster)
        dists = np.abs(cxs - wire_col) + np.abs(cys - py0)
        sort_idx = np.argsort(dists)
        # Use step to add some variation
        step_hash = int(obs.step * 13 + total_zones * 11) % max(len(cxs), 1)
        for i in range(min(len(cxs), 100)):
            if i < 50:
                k = int(sort_idx[i])
            else:
                k = (step_hash + (i - 50) * 17) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # --- Step 7: Extend roads from existing road frontier near wire ---
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs_arr), 1)
        # Try multiple road cells
        for attempt in range(min(len(road_xs_arr), 20)):
            idx = (step_k + attempt * 7) % len(road_xs_arr)
            rx_s = int(road_xs_arr[idx])
            ry_s = int(road_ys_arr[idx])
            for dy, dx in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx_s + dx, ry_s + dy
                if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                    if nbr_wire[ny2, nx2]:
                        return (Tool.ROAD, nx2, ny2)

    # --- Step 8: Second power plant based on observed zone count ---
    if total_zones > 16 or obs.city_pop > 300:
        p2x = px0 + 24
        p2y = py0
        if in_bounds(p2x, p2y):
            # Check if second plant already exists nearby
            nearby_plant2 = any(
                in_bounds(p2x + dx, p2y + dy) and pm[p2y + dy, p2x + dx]
                for dy in range(-8, 9) for dx in range(-8, 9)
            )
            if not nearby_plant2 and em[p2y, p2x]:
                return (Tool.COALPOWER, p2x, p2y)
            # Connect with horizontal wire bridge
            for wc in range(wire_col + 1, p2x):
                if in_bounds(wc, py0) and not pm[py0, wc] and (em[py0, wc] or wm[py0, wc]):
                    return (Tool.WIRE, wc, py0)

    # --- Step 9: Third plant on left side when large ---
    if obs.city_pop > 600 and not state.get("plant3_placed", False):
        p3x = px0 - 24
        p3y = py0
        if in_bounds(p3x, p3y):
            nearby_plant3 = any(
                in_bounds(p3x + dx, p3y + dy) and pm[p3y + dy, p3x + dx]
                for dy in range(-8, 9) for dx in range(-8, 9)
            )
            if not nearby_plant3 and em[p3y, p3x]:
                state["plant3_placed"] = True
                return (Tool.COALPOWER, p3x, p3y)
            # Connect leftward
            for wc in range(wire_col - 1, p3x - 1, -1):
                if in_bounds(wc, py0) and not pm[py0, wc] and (em[py0, wc] or wm[py0, wc]):
                    return (Tool.WIRE, wc, py0)

    # --- Step 10: Services based on observed population ---
    if obs.city_pop > 150:
        # Fire station - check if already placed (look for non-zone non-road non-wire non-plant)
        fx, fy = px0 - 7, py0 - 10
        if in_bounds(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
        polx, poly = px0 - 7, py0 + 10
        if in_bounds(polx, poly) and em[poly, polx]:
            return (Tool.POLICESTATION, polx, poly)

    # --- Step 11: Extend wire frontier reactively ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        # Find wire cells at the frontier (not all 4 neighbors are wire/plant)
        step_k2 = int(obs.step * 7) % max(len(wire_xs_arr), 1)
        for attempt in range(min(len(wire_xs_arr), 20)):
            idx = (step_k2 + attempt * 9) % len(wire_xs_arr)
            wx_s = int(wire_xs_arr[idx])
            wy_s = int(wire_ys_arr[idx])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = wx_s + dx2, wy_s + dy2
                if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                    # Only extend in useful directions (toward zone candidates)
                    if nbr_road[ny2, nx2]:
                        return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Scan existing infrastructure each step
    - Place power plant if none exists
    - Extend wire from plant outward toward zones
    - Build roads adjacent to wires
    - Place zones adjacent to roads+wires
    - Scale up with population
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    all_zone = resm | comm | indm

    cx, cy = WORLD_W // 2, WORLD_H // 2
    pop = obs.city_pop

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(total_zones, 1)
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        if com_count / t < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zy, zx):
        if zy < 1 or zy > WORLD_H - 2 or zx < 1 or zx > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zy + dr, zx + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone[rr, rc]:
                    return False
        return True

    # --- Phase 1: Place coal power plant if none ---
    if not np.any(pm):
        return (Tool.COALPOWER, cx - 20, cy)

    # Find plant center
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Scale horizontal extent with population
    if pop < 50:
        x_half = 12
    elif pop < 200:
        x_half = 20
    elif pop < 500:
        x_half = 32
    elif pop < 900:
        x_half = 44
    else:
        x_half = 55

    x_min = max(3, cx - x_half)
    x_max = min(WORLD_W - 4, cx + x_half)

    # Wire spine row and parallel road rows
    wire_row = cy
    road_above = cy - 4
    road_below = cy + 4

    # --- Phase 2: Build wire spine from plant outward ---
    # Find existing wire extent on wire_row
    wire_on_row = [c for c in range(WORLD_W) if wm[wire_row, c]]

    if not wire_on_row:
        # Place first wire adjacent to plant
        start_c = plant_cx + 3
        for dc in range(0, 10):
            c = start_c + dc
            if in_bounds(c, wire_row) and em[wire_row, c]:
                return (Tool.WIRE, c, wire_row)
        return None

    min_wc = min(wire_on_row)
    max_wc = max(wire_on_row)

    # Extend wire rightward
    if max_wc < x_max:
        nc = max_wc + 1
        if in_bounds(nc, wire_row) and em[wire_row, nc] and not pm[wire_row, nc]:
            return (Tool.WIRE, nc, wire_row)

    # Extend wire leftward toward plant
    if min_wc > x_min:
        nc = min_wc - 1
        if in_bounds(nc, wire_row) and em[wire_row, nc] and not pm[wire_row, nc]:
            return (Tool.WIRE, nc, wire_row)

    # --- Phase 3: Connect plant to wire spine if not connected ---
    # Check adjacency: any wire within 2 tiles of plant?
    connected = False
    for dr in range(-3, 4):
        for dc in range(-3, 4):
            rr, rc = plant_cy + dr, plant_cx + dc
            if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                if wm[rr, rc]:
                    connected = True
    if not connected:
        # Bridge horizontally from plant to nearest wire
        for bc in range(plant_cx + 3, min_wc + 1):
            if in_bounds(bc, wire_row) and not pm[wire_row, bc] and not wm[wire_row, bc]:
                if em[wire_row, bc]:
                    return (Tool.WIRE, bc, wire_row)
                break
        # Bridge vertically then horizontally
        for br in range(plant_cy, wire_row + 1):
            c = plant_cx + 2
            if in_bounds(c, br) and em[br, c] and not pm[br, c] and not wm[br, c]:
                return (Tool.WIRE, c, br)

    # --- Phase 4: Road rows ---
    # Build roads at road_above and road_below where wire exists
    for wc in wire_on_row:
        if x_min <= wc <= x_max:
            if in_bounds(wc, road_above) and em[road_above, wc] and not pm[road_above, wc]:
                return (Tool.ROAD, wc, road_above)
            if in_bounds(wc, road_below) and em[road_below, wc] and not pm[road_below, wc]:
                return (Tool.ROAD, wc, road_below)

    # Vertical connectors every 8 cols
    for wc in wire_on_row:
        if x_min <= wc <= x_max and (wc - x_min) % 8 == 0:
            for wr in range(road_above, road_below + 1):
                if in_bounds(wc, wr) and em[wr, wc] and not pm[wr, wc] and not wm[wr, wc]:
                    return (Tool.ROAD, wc, wr)

    # --- Phase 5: Place zones near roads AND wires ---
    # Compute neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = r0 + (sr1 - sr0)
            c0 = max(0, dx); c1 = c0 + (sc1 - sc0)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = r0 + (sr1 - sr0)
            c0 = max(0, dx); c1 = c0 + (sc1 - sc0)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, :2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys_a, cxs_a = np.where(cand_mask)
    if len(cxs_a) > 0:
        # Sort by closeness to wire spine
        dists = np.abs(cxs_a.astype(int) - cx) + 2 * np.abs(cys_a.astype(int) - wire_row)
        sort_idx = np.argsort(dists)
        for i in range(min(len(cxs_a), 100)):
            k = int(sort_idx[i])
            zx, zy = int(cxs_a[k]), int(cys_a[k])
            if zone_area_ok(zy, zx):
                return (pick_tool(), zx, zy)

    # --- Phase 6: Second power plant ---
    plant_tiles = int(np.sum(pm))
    plant_count = max(1, plant_tiles // 6)
    if pop > 150 and plant_count < 2:
        p2x = plant_cx + 42
        p2y = plant_cy
        if in_bounds(p2x, p2y) and em[p2y, p2x]:
            nearby = any(
                in_bounds(p2x + dx, p2y + dy) and pm[p2y + dy, p2x + dx]
                for dy in range(-6, 7) for dx in range(-6, 7)
            )
            if not nearby:
                return (Tool.COALPOWER, p2x, p2y)
        # Extend wire toward second plant
        if max_wc < p2x - 3:
            nc = max_wc + 1
            if in_bounds(nc, wire_row) and em[wire_row, nc] and not pm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # --- Phase 7: Third power plant ---
    if pop > 500 and plant_count < 3:
        p3x = cx
        p3y = plant_cy + 18
        if in_bounds(p3x, p3y) and em[p3y, p3x]:
            nearby = any(
                in_bounds(p3x + dx, p3y + dy) and pm[p3y + dy, p3x + dx]
                for dy in range(-6, 7) for dx in range(-6, 7)
            )
            if not nearby:
                return (Tool.COALPOWER, p3x, p3y)
        # Wire downward from spine to third plant
        for wr2 in range(wire_row + 1, min(wire_row + 22, WORLD_H - 2)):
            wc3 = cx
            if in_bounds(wc3, wr2) and em[wr2, wc3] and not pm[wr2, wc3] and not wm[wr2, wc3]:
                return (Tool.WIRE, wc3, wr2)

    # --- Phase 8: Services ---
    if pop > 150:
        fx, fy = cx + 2, cy - 9
        if in_bounds(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
    if pop > 350:
        px2, py2 = cx + 12, cy + 9
        if in_bounds(px2, py2) and em[py2, px2]:
            return (Tool.POLICESTATION, px2, py2)

    # --- Phase 9: Reactively extend roads from existing road tiles ---
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = int(obs.step * 13) % len(road_xs_arr)
        rx_s = int(road_xs_arr[step_k])
        ry_s = int(road_ys_arr[step_k])
        for dy, dx in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx2, ny2 = rx_s + dx, ry_s + dy
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                if nbr_wire[ny2, nx2] and x_min <= nx2 <= x_max:
                    return (Tool.ROAD, nx2, ny2)

    # --- Phase 10: Reactively extend wires ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k = int(obs.step * 7) % len(wire_xs_arr)
        wx_s = int(wire_xs_arr[step_k])
        wy_s = int(wire_ys_arr[step_k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = wx_s + dx2, wy_s + dy2
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                if x_min <= nx2 <= x_max:
                    return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map every step to decide next action
    - Scans existing infrastructure and extends it organically
    - Single neighborhood focused around center with adaptive expansion
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    all_zones = resm | comm | indm

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def area_free(cx, cy):
        if cx < 1 or cx > WORLD_W - 2 or cy < 1 or cy > WORLD_H - 2:
            return False
        for dy in [-1, 0, 1]:
            for dx in [-1, 0, 1]:
                r, c = cy + dy, cx + dx
                if not (0 <= r < WORLD_H and 0 <= c < WORLD_W):
                    return False
                if not em[r, c]:
                    return False
        return True

    def zone_exists_near(cx, cy, radius=3):
        r0 = max(0, cy - radius)
        r1 = min(WORLD_H, cy + radius + 1)
        c0 = max(0, cx - radius)
        c1 = min(WORLD_W, cx + radius + 1)
        return np.any(all_zones[r0:r1, c0:c1])

    def has_wire_near(cx, cy, radius=4):
        r0 = max(0, cy - radius)
        r1 = min(WORLD_H, cy + radius + 1)
        c0 = max(0, cx - radius)
        c1 = min(WORLD_W, cx + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_near(cx, cy, radius=4):
        r0 = max(0, cy - radius)
        r1 = min(WORLD_H, cy + radius + 1)
        c0 = max(0, cx - radius)
        c1 = min(WORLD_W, cx + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    def pick_zone():
        t = max(1, total_zones)
        if res_count / t < 0.45:
            return Tool.RESIDENTIAL
        elif com_count / t < 0.28:
            return Tool.COMMERCIAL
        elif ind_count / t < 0.27:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Primary neighborhood centered at (60, 50)
    # Secondary neighborhood at (30, 50) and (90, 50)
    neighborhoods = [
        {'cx': 60, 'cy': 50},
        {'cx': 30, 'cy': 50},
        {'cx': 90, 'cy': 50},
    ]

    # Use only first neighborhood early, expand as pop grows
    if pop < 200:
        active_nb = neighborhoods[:1]
    elif pop < 500:
        active_nb = neighborhoods[:2]
    else:
        active_nb = neighborhoods

    for nb in active_nb:
        cx, cy = nb['cx'], nb['cy']

        # Check if plant exists near this neighborhood
        local_pm = pm[max(0, cy-8):min(WORLD_H, cy+9), max(0, cx-8):min(WORLD_W, cx+9)]
        has_plant = np.any(local_pm)

        if not has_plant:
            # Place coal plant near center of neighborhood
            for r in range(0, 6):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dy) == r or abs(dx) == r:
                            npx, npy = cx + dx, cy + dy
                            if area_free(npx, npy):
                                return (Tool.COALPOWER, npx, npy)
            continue

        # Find plant location(s) near this neighborhood
        plant_rows, plant_cols = np.where(pm)
        near_plants = [(plant_rows[i], plant_cols[i]) for i in range(len(plant_rows))
                       if abs(plant_cols[i] - cx) <= 12 and abs(plant_rows[i] - cy) <= 12]

        if not near_plants:
            continue

        plant_cy = int(np.mean([r for r, c in near_plants]))
        plant_cx = int(np.mean([c for r, c in near_plants]))

        # Wire spine: vertical column at cx, horizontal row at cy
        # Connect plant to spine first
        # Vertical wire spine at cx
        wire_on_vcol = [r for r in range(WORLD_H) if wm[r, cx]]
        wire_on_hrow = [c for c in range(WORLD_W) if wm[cy, c]]

        # Adaptive extent based on pop
        if pop < 100:
            extent = 6
        elif pop < 300:
            extent = 10
        elif pop < 600:
            extent = 14
        else:
            extent = 18

        v_top = max(2, cy - extent)
        v_bot = min(WORLD_H - 3, cy + extent)
        h_left = max(2, cx - extent)
        h_right = min(WORLD_W - 3, cx + extent)

        # Step 1: Connect plant to vertical spine with wire
        if not wire_on_vcol:
            # Place initial wire adjacent to plant toward spine
            # Try plant row at spine column
            if em[plant_cy, cx] or wm[plant_cy, cx]:
                if not pm[plant_cy, cx]:
                    return (Tool.WIRE, cx, plant_cy)
            # Bridge horizontally from plant to spine col
            step = 1 if cx > plant_cx else -1
            for wcc in range(plant_cx + step, cx + step, step):
                if 0 <= wcc < WORLD_W:
                    if pm[plant_cy, wcc]:
                        break
                    if em[plant_cy, wcc]:
                        return (Tool.WIRE, wcc, plant_cy)
                    elif not wm[plant_cy, wcc]:
                        break
        else:
            # Extend vertical spine
            min_wr = min(wire_on_vcol)
            max_wr = max(wire_on_vcol)

            if max_wr < v_bot:
                nr = max_wr + 1
                if 0 < nr < WORLD_H and not pm[nr, cx] and (em[nr, cx] or wm[nr, cx]):
                    return (Tool.WIRE, cx, nr)

            if min_wr > v_top:
                nr = min_wr - 1
                if 0 < nr < WORLD_H and not pm[nr, cx] and (em[nr, cx] or wm[nr, cx]):
                    return (Tool.WIRE, cx, nr)

        # Step 2: Horizontal wire at cy from v_spine
        if wire_on_vcol:
            # Extend horizontal wire leftward from spine
            for wcc in range(cx - 1, h_left - 1, -1):
                if 0 <= wcc < WORLD_W:
                    if wm[cy, wcc]:
                        break
                    if pm[cy, wcc]:
                        break
                    if em[cy, wcc]:
                        return (Tool.WIRE, wcc, cy)
                    else:
                        break
            # Extend horizontal wire rightward from spine
            for wcc in range(cx + 1, h_right + 1):
                if 0 <= wcc < WORLD_W:
                    if wm[cy, wcc]:
                        break
                    if pm[cy, wcc]:
                        break
                    if em[cy, wcc]:
                        return (Tool.WIRE, wcc, cy)
                    else:
                        break

        # Step 3: Roads - horizontal roads above and below spine
        road_rows = [cy - 4, cy + 4]
        road_span = range(h_left - 2, h_right + 3)

        for rrow in road_rows:
            if 0 < rrow < WORLD_H:
                for rc in road_span:
                    if 0 <= rc < WORLD_W and em[rrow, rc] and not pm[rrow, rc]:
                        return (Tool.ROAD, rc, rrow)

        # Step 4: Vertical road connectors at left and right ends
        for rc in [h_left, h_right]:
            if 0 <= rc < WORLD_W:
                for ry in range(min(road_rows), max(road_rows) + 1):
                    if 0 <= ry < WORLD_H and em[ry, rc] and not pm[ry, rc]:
                        return (Tool.ROAD, rc, ry)

        # Step 5: Also add a vertical road at cx for connectivity
        for ry in range(min(road_rows), max(road_rows) + 1):
            if 0 <= ry < WORLD_H and em[ry, cx] and not pm[ry, cx] and not wm[ry, cx]:
                return (Tool.ROAD, cx, ry)

        # Step 6: Lateral wires from vertical spine to zone columns
        if wire_on_vcol:
            for wr in wire_on_vcol:
                if v_top <= wr <= v_bot:
                    # Wire leftward
                    for wcc in range(cx - 1, h_left - 3, -1):
                        if 0 <= wcc < WORLD_W:
                            if wm[wr, wcc]:
                                break
                            if pm[wr, wcc]:
                                break
                            if em[wr, wcc]:
                                return (Tool.WIRE, wcc, wr)
                            else:
                                break
                    # Wire rightward
                    for wcc in range(cx + 1, h_right + 3):
                        if 0 <= wcc < WORLD_W:
                            if wm[wr, wcc]:
                                break
                            if pm[wr, wcc]:
                                break
                            if em[wr, wcc]:
                                return (Tool.WIRE, wcc, wr)
                            else:
                                break

        # Step 7: Place zones - scan for suitable spots near roads and wires
        # Try regular grid of candidate zone centers
        zone_step = 4
        for zy in range(v_top + 2, v_bot - 1, zone_step):
            if road_rows[0] - 1 <= zy <= road_rows[0] + 1:
                continue  # skip on road rows
            if road_rows[1] - 1 <= zy <= road_rows[1] + 1:
                continue
            for zx in range(h_left + 1, h_right - 1, zone_step):
                if 1 <= zx <= WORLD_W - 2 and 1 <= zy <= WORLD_H - 2:
                    if not zone_exists_near(zx, zy, 2) and area_free(zx, zy):
                        if has_wire_near(zx, zy, 4) and has_road_near(zx, zy, 5):
                            return (pick_zone(), zx, zy)

        # Step 8: Wider scan for any viable zone placement
        for zy in range(v_top + 1, v_bot, 3):
            for zx in range(h_left, h_right + 1, 3):
                if 1 <= zx <= WORLD_W - 2 and 1 <= zy <= WORLD_H - 2:
                    if not zone_exists_near(zx, zy, 2) and area_free(zx, zy):
                        if has_wire_near(zx, zy, 5) and has_road_near(zx, zy, 6):
                            return (pick_zone(), zx, zy)

    # Extra power plant if zones are growing but power insufficient
    if total_zones > 8 and obs.powered_zones < total_zones * 0.7:
        plant_count = int(np.sum(pm)) // 9
        if plant_count < 3:
            for try_cx, try_cy in [(45, 50), (75, 50), (60, 35), (60, 65)]:
                if area_free(try_cx, try_cy):
                    return (Tool.COALPOWER, try_cx, try_cy)

    # Services for larger cities
    if pop > 400:
        for px, py in [(55, 42), (65, 42), (55, 58), (65, 58)]:
            if area_free(px, py):
                near_tile = tm[max(0, py-6):min(WORLD_H, py+7), max(0, px-6):min(WORLD_W, px+7)]
                has_service = np.any((near_tile >= 600) & (near_tile <= 800))
                if not has_service:
                    return (Tool.POLICESTATION, px, py)

    if pop > 700:
        for px, py in [(40, 50), (80, 50)]:
            if area_free(px, py):
                return (Tool.FIRESTATION, px, py)

    return None

def act(obs, state):
    """
    Improved policy: builds a grid-based neighborhood with horizontal road spines
    and vertical wire connections. Creates a denser zone layout with better
    commercial/industrial mix. Places two power plants from the start.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Initialize state
    if 'phase' not in state:
        state['phase'] = 'init'
        state['build_queue'] = []

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Layout: two power plants at (45,50) and (75,50)
    # Wire spine: horizontal at y=50, from x=40 to x=80
    # Road spines: horizontal at y=44, y=47, y=53, y=56
    # Zones fill the rows between roads

    plant1_x, plant1_y = 45, 50
    plant2_x, plant2_y = 73, 50

    # Step 1: Place power plants
    if not np.any(pm):
        return (Tool.COALPOWER, plant1_x, plant1_y)

    plant_ys, plant_xs = np.where(pm)
    n_plants = len(set(plant_xs // 3))  # rough count

    # Place second plant if not there yet
    p1_there = any(abs(px - plant1_x) < 4 and abs(py - plant1_y) < 4
                   for px, py in zip(plant_xs, plant_ys))
    p2_there = any(abs(px - plant2_x) < 4 and abs(py - plant2_y) < 4
                   for px, py in zip(plant_xs, plant_ys))

    if not p2_there and total_zones >= 0:
        # Check if area is clear enough
        if in_bounds(plant2_x, plant2_y) and not pm[plant2_y, plant2_x]:
            return (Tool.COALPOWER, plant2_x, plant2_y)

    # Wire spine: horizontal connecting both plants
    wire_row = 50
    wire_start = plant1_x + 2
    wire_end = plant2_x - 2

    # Build horizontal wire spine
    for wx in range(wire_start, wire_end + 1):
        if in_bounds(wx, wire_row) and em[wire_row, wx]:
            return (Tool.WIRE, wx, wire_row)

    # Vertical wire extensions from spine
    wire_col_l = plant1_x + 2  # left vertical wire
    wire_col_r = plant2_x - 2  # right vertical wire
    wire_col_m = (wire_start + wire_end) // 2  # middle vertical

    vertical_extent = min(20, 10 + obs.city_pop // 20)
    wire_top = max(2, wire_row - vertical_extent)
    wire_bot = min(WORLD_H - 3, wire_row + vertical_extent)

    for col in [wire_col_l, wire_col_r, wire_col_m]:
        for wy in range(wire_top, wire_bot + 1):
            if in_bounds(col, wy) and em[wy, col] and not pm[wy, col]:
                return (Tool.WIRE, col, wy)

    # Build horizontal roads at regular intervals
    road_rows = []
    for row in range(wire_top + 1, wire_bot, 3):
        if row != wire_row:
            road_rows.append(row)

    for rrow in road_rows:
        road_x_start = min(wire_col_l, wire_col_r) - 2
        road_x_end = max(wire_col_l, wire_col_r) + 2
        for rx in range(road_x_start, road_x_end + 1):
            if in_bounds(rx, rrow) and em[rrow, rx] and not pm[rrow, rx]:
                return (Tool.ROAD, rx, rrow)

    # Build vertical roads connecting horizontal roads
    vert_road_cols = list(range(wire_col_l - 2, wire_col_r + 3, 4))
    for vc in vert_road_cols:
        for vy in range(wire_top, wire_bot + 1):
            if in_bounds(vc, vy) and em[vy, vc] and not pm[vy, vc]:
                return (Tool.ROAD, vc, vy)

    # Proximity masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and not zone_tiles[nr, nc]:
                    return False
        return True

    # Zone placement
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Sort by distance to center of layout
        center_x = (wire_col_l + wire_col_r) // 2
        center_y = wire_row
        dists = np.abs(cxs - center_x) + np.abs(cys - center_y)
        order = np.argsort(dists)
        step_off = int(obs.step * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 100:
                break

    # Services
    if obs.city_pop > 150:
        fsx, fsy = wire_col_l - 8, wire_row - 5
        if in_bounds(fsx, fsy) and em[fsy, fsx]:
            return (Tool.FIRESTATION, fsx, fsy)
        psx, psy = wire_col_r + 4, wire_row - 5
        if in_bounds(psx, psy) and em[psy, psx]:
            return (Tool.POLICESTATION, psx, psy)

    if obs.city_pop > 400:
        stx, sty = wire_col_m, wire_row - 12
        if in_bounds(stx, sty) and em[sty, stx]:
            return (Tool.STADIUM, stx, sty)

    # Extend wires to new areas when growing
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 10)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = wx + dx2, wy + dy2
                if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                    return (Tool.WIRE, nx2, ny2)

    # Extend roads from existing
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 15)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx]:
                    if nbr_wire[ny, nx]:
                        return (Tool.ROAD, nx, ny)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder v2.
    Key changes from parent:
    - More aggressive zone placement: lower power-neighbor radius requirement
    - Better wire routing: extend wires toward zones that lack power
    - Add cross-road streets more densely
    - Place second power plant earlier and connect with wire
    - Services placed reactively based on zone counts
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    CX, CY = 55, 50

    # Step 1: Place first power plant if none exists
    if not np.any(pm):
        return (Tool.COALPOWER, CX, CY)

    plant_rows, plant_cols = np.where(pm)
    pcx = int(np.mean(plant_cols))
    pcy = int(np.mean(plant_rows))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        if ind_count / t < 0.18:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Wire and road spines relative to plant
    wire_row = pcy - 1
    road_row = pcy + 2
    wire_col = pcx
    road_col = pcx + 1

    power_map = pm | wm

    # Step 2: Place second power plant early when needed
    plant_count = int(np.sum(pm))
    if obs.city_pop > 150 and plant_count < 9:
        # Try to place second plant to the right or below
        for p2x, p2y in [(pcx + 18, pcy), (pcx - 18, pcy), (pcx, pcy + 18)]:
            p2x = max(2, min(WORLD_W - 3, p2x))
            p2y = max(2, min(WORLD_H - 3, p2y))
            # Check 3x3 area is mostly empty
            area = tm[p2y-1:p2y+2, p2x-1:p2x+2]
            if bool(em[p2y, p2x]) and not bool(pm[p2y, p2x]):
                # Also place if the area is clear
                return (Tool.COALPOWER, p2x, p2y)

    # Step 3: Extend wires from existing power to build a grid
    # Horizontal wire at wire_row, vertical at wire_col
    w_extent = min(35, 12 + obs.city_pop // 15)
    wire_h_targets = [(x, wire_row) for x in range(CX - w_extent, CX + w_extent + 1)]
    wire_v_targets = [(wire_col, y) for y in range(CY - 20, CY + 21)]
    # Additional wire rows for second plant connectivity
    wire_targets_extra = []
    if plant_count >= 9:
        # Connect plants with wires
        plant_rows2, plant_cols2 = np.where(pm)
        for pr, pc in zip(plant_rows2, plant_cols2):
            # wire from this plant toward main wire col
            for wx in range(min(pc, wire_col), max(pc, wire_col) + 1):
                wire_targets_extra.append((wx, pr - 1))
            for wy in range(min(pr, pcy), max(pr, pcy) + 1):
                wire_targets_extra.append((wire_col, wy))

    all_wire_targets = wire_h_targets + wire_v_targets + wire_targets_extra

    for (wx, wy) in all_wire_targets:
        if not in_bounds(wx, wy):
            continue
        if bool(wm[wy, wx]) or bool(pm[wy, wx]):
            continue
        # Place if adjacent to existing power
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx, ny = wx+ddx, wy+ddy
            if in_bounds(nx, ny) and bool(power_map[ny, nx]):
                if bool(em[wy, wx]) and not bool(rm[wy, wx]):
                    return (Tool.WIRE, wx, wy)
                break

    # Step 4: Extend roads
    r_extent = min(30, 10 + obs.city_pop // 12)
    road_h_targets = [(x, road_row) for x in range(CX - r_extent, CX + r_extent + 1)]
    road_v_targets = [(road_col, y) for y in range(CY - 18, CY + 19)]

    # Dense cross-streets every 3 columns
    cross_roads = []
    for dx in range(-r_extent, r_extent + 1, 3):
        cx2 = CX + dx
        for dy in range(-10, 11):
            cross_roads.append((cx2, road_row + dy))
    # Also horizontal roads every 3 rows
    for dy2 in range(-9, 10, 3):
        for dx in range(-r_extent, r_extent + 1):
            cross_roads.append((CX + dx, road_row + dy2))

    all_road_targets = road_h_targets + road_v_targets + cross_roads

    for (rx, ry) in all_road_targets:
        if not in_bounds(rx, ry):
            continue
        if bool(rm[ry, rx]) or bool(pm[ry, rx]):
            continue
        if not bool(em[ry, rx]):
            continue
        # Place if adjacent to existing road or adjacent to plant
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx, ny = rx+ddx, ry+ddy
            if in_bounds(nx, ny) and bool(rm[ny, nx]):
                return (Tool.ROAD, rx, ry)
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1),(2,0),(-2,0),(0,2),(0,-2)]:
            nx, ny = rx+ddx, ry+ddy
            if in_bounds(nx, ny) and bool(pm[ny, nx]):
                return (Tool.ROAD, rx, ry)

    # Step 5: Place zones near roads AND power
    # Build neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_mask = resm | comm | indm
    cand = em & nbr_road & nbr_power
    cand[0:2, :] = False
    cand[WORLD_H-2:, :] = False
    cand[:, 0:2] = False
    cand[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        # Prefer candidates closer to center
        dists = (cxs - CX)**2 + (cys - CY)**2
        order = np.argsort(dists)
        checked = 0
        for idx in order:
            if checked > 80:
                break
            checked += 1
            zx, zy = int(cxs[idx]), int(cys[idx])
            ok = True
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    ny2, nx2 = zy + dr, zx + dc
                    if not in_bounds(nx2, ny2):
                        ok = False; break
                    if not (bool(em[ny2, nx2]) or bool(zone_mask[ny2, nx2])):
                        ok = False; break
                if not ok:
                    break
            if ok:
                return (pick_tool(), zx, zy)

    # Step 6: Services based on zone count
    if res_count > 20:
        for fx, fy in [(CX + 6, CY - 10), (CX - 6, CY + 10), (CX + 10, CY + 6)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.FIRESTATION, fx, fy)
    if res_count > 50:
        for fx, fy in [(CX - 6, CY - 10), (CX + 6, CY + 10)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.POLICESTATION, fx, fy)

    # Fallback: extend wire frontier
    wys2, wxs2 = np.where(wm)
    if len(wxs2) > 0:
        k3 = int(obs.step * 7 + 3) % len(wxs2)
        wx2, wy2 = int(wxs2[k3]), int(wys2[k3])
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx, ny = wx2+ddx, wy2+ddy
            if in_bounds(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                return (Tool.WIRE, nx, ny)

    # Fallback: extend road frontier
    rys2, rxs2 = np.where(rm)
    if len(rxs2) > 0:
        k2 = int(obs.step * 11 + 5) % len(rxs2)
        rx2, ry2 = int(rxs2[k2]), int(rys2[k2])
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx, ny = rx2+ddx, ry2+ddy
            if in_bounds(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                return (Tool.ROAD, nx, ny)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map each step to decide next action
    - Extends power wire from existing wire/plant frontier
    - Extends roads from existing road frontier
    - Places zones adjacent to powered+roaded areas
    - Uses state only for small phase tracking
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)
    zone_m = res_m | com_m | ind_m

    step = obs.step
    pop = obs.city_pop
    n_steps = obs.n_steps

    # ---- helpers ----
    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def area_free(cx, cy, radius=1):
        for dy in range(-radius, radius + 1):
            for dx in range(-radius, radius + 1):
                r, c = cy + dy, cx + dx
                if not in_bounds(c, r):
                    return False
                if not em[r, c]:
                    return False
        return True

    def has_wire_adjacent(cx, cy):
        for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx, ny = cx+dx, cy+dy
            if in_bounds(nx, ny) and (wm[ny, nx] or pm[ny, nx]):
                return True
        return False

    def has_road_adjacent(cx, cy):
        for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx, ny = cx+dx, cy+dy
            if in_bounds(nx, ny) and rm[ny, nx]:
                return True
        return False

    def zone_near(cx, cy, radius=2):
        r0, r1 = max(0, cy-radius), min(WORLD_H, cy+radius+1)
        c0, c1 = max(0, cx-radius), min(WORLD_W, cx+radius+1)
        return np.any(zone_m[r0:r1, c0:c1])

    # ---- zone ratio helper ----
    res_count = int(np.sum(res_m)) // 9 + 1
    com_count = int(np.sum(com_m)) // 9 + 1
    ind_count = int(np.sum(ind_m)) // 9 + 1
    total = res_count + com_count + ind_count

    def pick_zone():
        r_f = res_count / total
        c_f = com_count / total
        i_f = ind_count / total
        if r_f < 0.45:
            return Tool.RESIDENTIAL
        elif c_f < 0.30:
            return Tool.COMMERCIAL
        elif i_f < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # ---- STEP 1: Ensure a coal power plant exists ----
    has_plant = np.any(pm)
    if not has_plant:
        # Place coal plant near (40, 50)
        for dy in range(-5, 6):
            for dx in range(-5, 6):
                cx, cy = 40+dx, 50+dy
                if area_free(cx, cy):
                    return (Tool.COALPOWER, cx, cy)

    # ---- STEP 2: Extend wire from plant/wire frontier ----
    # Find wire/plant cells and try to extend wire toward target spine
    # Target: horizontal wire spine at y=50, from x=30 to x=90
    WIRE_Y = 50
    WIRE_X_START = 30
    WIRE_X_END = 90

    # First: connect plant to wire spine if not connected
    # Find plant location
    plant_ys, plant_xs = np.where(pm)
    if len(plant_xs) > 0:
        px0 = int(plant_xs[0])
        py0 = int(plant_ys[0])
    else:
        px0, py0 = 40, 50

    # Extend wire horizontally along WIRE_Y
    for wx in range(WIRE_X_START, WIRE_X_END + 1):
        if not wm[WIRE_Y, wx] and not pm[WIRE_Y, wx]:
            if em[WIRE_Y, wx]:
                # Check connectivity: adjacent wire or plant?
                adj_powered = False
                for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
                    nx2, ny2 = wx+ddx, WIRE_Y+ddy
                    if in_bounds(nx2, ny2) and (wm[ny2, nx2] or pm[ny2, nx2]):
                        adj_powered = True
                        break
                if adj_powered:
                    return (Tool.WIRE, wx, WIRE_Y)

    # Connect plant to spine: vertical wire from plant to WIRE_Y
    if py0 != WIRE_Y:
        step_dir = 1 if WIRE_Y > py0 else -1
        for wy in range(py0, WIRE_Y + step_dir, step_dir):
            if not wm[wy, px0] and not pm[wy, px0] and em[wy, px0]:
                # Check adjacent powered
                adj = False
                for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
                    nx2, ny2 = px0+ddx, wy+ddy
                    if in_bounds(nx2, ny2) and (wm[ny2, nx2] or pm[ny2, nx2]):
                        adj = True
                        break
                if adj:
                    return (Tool.WIRE, px0, wy)

    # Also extend wire horizontally from WIRE_X_START leftward to plant if needed
    if px0 < WIRE_X_START:
        for wx in range(WIRE_X_START, px0 - 1, -1):
            if not wm[WIRE_Y, wx] and not pm[WIRE_Y, wx] and em[WIRE_Y, wx]:
                adj = False
                for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
                    nx2, ny2 = wx+ddx, WIRE_Y+ddy
                    if in_bounds(nx2, ny2) and (wm[ny2, nx2] or pm[ny2, nx2]):
                        adj = True
                        break
                if adj:
                    return (Tool.WIRE, wx, WIRE_Y)

    # ---- STEP 3: Build road spine above and below wire spine ----
    ROAD_Y_ABOVE = WIRE_Y - 4
    ROAD_Y_BELOW = WIRE_Y + 4
    ROAD_X_START = WIRE_X_START - 2
    ROAD_X_END = WIRE_X_END + 2

    for road_y in [ROAD_Y_ABOVE, ROAD_Y_BELOW]:
        if 0 < road_y < WORLD_H:
            for rx in range(ROAD_X_START, ROAD_X_END + 1):
                if 0 <= rx < WORLD_W:
                    if not rm[road_y, rx] and em[road_y, rx]:
                        # Try to connect from adjacent road or start from x that has road
                        adj_road = False
                        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
                            nx2, ny2 = rx+ddx, road_y+ddy
                            if in_bounds(nx2, ny2) and rm[ny2, nx2]:
                                adj_road = True
                                break
                        if adj_road or (rx == ROAD_X_START and not np.any(rm[road_y, :])):
                            return (Tool.ROAD, rx, road_y)
                        # Seed: just start placing if no road on that row yet
                        if not np.any(rm[road_y, ROAD_X_START:ROAD_X_END+1]):
                            return (Tool.ROAD, ROAD_X_START, road_y)

    # ---- STEP 4: Add vertical connector roads between road rows ----
    # Every 4 columns, connect road_above and road_below through wire row
    # But skip wire row itself (place road only above and below it)
    for rx in range(ROAD_X_START, ROAD_X_END + 1, 4):
        if 0 <= rx < WORLD_W:
            # vertical from road_above to road_below, skipping WIRE_Y (don't overwrite wire)
            for ry in range(ROAD_Y_ABOVE, ROAD_Y_BELOW + 1):
                if 0 <= ry < WORLD_H:
                    if ry == WIRE_Y:
                        continue  # don't bulldoze wire
                    if not rm[ry, rx] and em[ry, rx]:
                        # Check adjacency
                        adj = False
                        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
                            nx2, ny2 = rx+ddx, ry+ddy
                            if in_bounds(nx2, ny2) and rm[ny2, nx2]:
                                adj = True
                                break
                        if adj:
                            return (Tool.ROAD, rx, ry)

    # ---- STEP 5: Place zones between road rows, powered and road-adjacent ----
    # Zone rows: ROAD_Y_ABOVE - 3 (above road) and ROAD_Y_BELOW + 3 (below road)
    ZONE_Y_ABOVE = ROAD_Y_ABOVE - 3  # center of zone above upper road
    ZONE_Y_BELOW = ROAD_Y_BELOW + 3  # center of zone below lower road

    # Also zones between the two road rows near center - not ideal but try flanks
    for zone_y in [ZONE_Y_ABOVE, ZONE_Y_BELOW]:
        if 1 <= zone_y <= WORLD_H - 2:
            for zx in range(ROAD_X_START + 2, ROAD_X_END - 1, 4):
                if 1 <= zx <= WORLD_W - 2:
                    if not zone_near(zx, zone_y, 1):
                        if area_free(zx, zone_y):
                            # Need road adjacent (within 1 of zone edge = within 2 of center)
                            road_ok = False
                            for dy2 in range(-2, 3):
                                for dx2 in range(-2, 3):
                                    nx2, ny2 = zx+dx2, zone_y+dy2
                                    if in_bounds(nx2, ny2) and rm[ny2, nx2]:
                                        road_ok = True
                            # Need wire adjacent to zone
                            wire_ok = has_wire_adjacent(zx, zone_y)
                            if not wire_ok:
                                # Place wire connecting zone to spine
                                # Go vertically toward WIRE_Y
                                step_d = 1 if WIRE_Y > zone_y else -1
                                for wy2 in range(zone_y + step_d * 2, WIRE_Y + step_d, step_d):
                                    if in_bounds(zx, wy2) and em[wy2, zx]:
                                        if has_wire_adjacent(zx, wy2):
                                            return (Tool.WIRE, zx, wy2)
                            if road_ok and wire_ok:
                                return (pick_zone(), zx, zone_y)

    # ---- STEP 6: Extend infrastructure further and add more zones reactively ----
    # If wire spine is complete, extend it and add more zone rows
    wire_coverage = int(np.sum(wm[WIRE_Y, WIRE_X_START:WIRE_X_END+1]))
    total_span = WIRE_X_END - WIRE_X_START + 1

    if wire_coverage > total_span * 0.8:
        # Try second wire spine
        WIRE_Y2 = WIRE_Y - 12
        WIRE_Y2b = WIRE_Y + 12
        for wy2 in [WIRE_Y2, WIRE_Y2b]:
            if 0 < wy2 < WORLD_H:
                for wx2 in range(WIRE_X_START, WIRE_X_END + 1):
                    if not wm[wy2, wx2] and not pm[wy2, wx2] and em[wy2, wx2]:
                        # connect vertically if possible
                        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
                            nx2, ny2 = wx2+ddx, wy2+ddy
                            if in_bounds(nx2, ny2) and (wm[ny2, nx2] or pm[ny2, nx2]):
                                return (Tool.WIRE, wx2, wy2)

    # ---- STEP 7: Police/fire for happiness ----
    if pop > 300:
        for spx, spy in [(40, 43), (70, 43), (40, 57), (70, 57)]:
            if area_free(spx, spy):
                # Check no station nearby
                has_station = False
                for dy2 in range(-8, 9):
                    for dx2 in range(-8, 9):
                        r2, c2 = spy+dy2, spx+dx2
                        if in_bounds(c2, r2) and 600 <= int(tm[r2, c2]) <= 800:
                            has_station = True
                if not has_station:
                    return (Tool.POLICESTATION, spx, spy)

    if pop > 200:
        for spx, spy in [(55, 43), (55, 57)]:
            if area_free(spx, spy):
                has_station = False
                for dy2 in range(-8, 9):
                    for dx2 in range(-8, 9):
                        r2, c2 = spy+dy2, spx+dx2
                        if in_bounds(c2, r2) and 800 <= int(tm[r2, c2]) <= 950:
                            has_station = True
                if not has_station:
                    return (Tool.FIRESTATION, spx, spy)

    # ---- STEP 8: Fill any empty zone spots adjacent to existing roads+wires ----
    # Scan for empty 3x3 areas near roads and wires
    for zy in range(3, WORLD_H - 3, 3):
        for zx in range(3, WORLD_W - 3, 3):
            if not zone_near(zx, zy, 1) and area_free(zx, zy):
                road_near = False
                wire_near = False
                for dy2 in range(-3, 4):
                    for dx2 in range(-3, 4):
                        nx2, ny2 = zx+dx2, zy+dy2
                        if in_bounds(nx2, ny2):
                            if rm[ny2, nx2]:
                                road_near = True
                            if wm[ny2, nx2] or pm[ny2, nx2]:
                                wire_near = True
                if road_near and wire_near:
                    return (pick_zone(), zx, zy)

    return None

def act(obs, state):
    """
    Improved policy with a horizontal road spine, multiple power connections,
    and a balanced zone mix placed on both sides of the road.
    Key changes from parent:
    - Horizontal road spine (east-west) instead of vertical
    - Wire runs parallel above the road
    - Zones placed both north and south of road
    - Better zone mix: 2 RES : 1 COM : 1 IND
    - Two power plants for better coverage
    - Zones placed in a grid pattern around the road
    """
    tm = obs.tile_map
    emp = empty_mask(tm)
    res = res_mask(tm)
    com = com_mask(tm)
    ind = ind_mask(tm)
    road = road_mask(tm)
    wire = wire_mask(tm)
    plant = plant_mask(tm)

    # Use a fixed anchor in lower-left quadrant for variety
    anchor_x, anchor_y = 20, 60

    # Initialize state
    if 'phase' not in state:
        state['phase'] = 0
        state['plant1_placed'] = False
        state['plant2_placed'] = False

    # --- Phase 0: Place first coal power plant ---
    if not np.any(plant):
        return (Tool.COALPOWER, anchor_x, anchor_y)

    plant_ys, plant_xs = np.where(plant)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    # --- Phase 1: Place second power plant to the east for more coverage ---
    # Second plant ~30 tiles east
    plant2_x, plant2_y = anchor_x + 40, anchor_y
    plant_tiles_count = int(np.sum(plant))
    # If only one plant cluster (roughly), place second
    if plant_tiles_count < 15:  # one plant = ~9 tiles
        # Check if plant2 area is empty enough
        if emp[plant2_y, plant2_x]:
            return (Tool.COALPOWER, plant2_x, plant2_y)

    # Horizontal wire spine: row = anchor_y - 2, from anchor_x to anchor_x+60
    wire_row = anchor_y - 2
    road_row = anchor_y + 2

    # --- Phase 2: Extend wire horizontally from plant ---
    wire_start_x = anchor_x - 1
    wire_end_x = anchor_x + 65

    # Find leftmost gap in wire spine that's adjacent to existing wire or plant
    wire_target = None
    for wx in range(wire_start_x, min(wire_end_x, WORLD_W - 1)):
        wy = wire_row
        if 0 <= wy < WORLD_H and 0 <= wx < WORLD_W:
            if not wire[wy, wx] and not plant[wy, wx]:
                # Check adjacency to powered tile
                adj = False
                for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]:
                    ny2, nx2 = wy+ddy, wx+ddx
                    if 0 <= ny2 < WORLD_H and 0 <= nx2 < WORLD_W:
                        if wire[ny2, nx2] or plant[ny2, nx2]:
                            adj = True
                            break
                if adj:
                    wire_target = (wx, wy)
                    break

    # Also extend wire from plant2 area: vertical connectors from plant to wire row
    # Connect plant at anchor_x to wire_row
    if wire_target is None:
        # Connect plant2 to wire row vertically
        conn_x = plant2_x
        for wy in range(min(plant2_y - 1, wire_row), max(plant2_y - 1, wire_row) - 1, -1):
            if 0 <= wy < WORLD_H and 0 <= conn_x < WORLD_W:
                if not wire[wy, conn_x] and not plant[wy, conn_x]:
                    adj = False
                    for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]:
                        ny2, nx2 = wy+ddy, conn_x+ddx
                        if 0 <= ny2 < WORLD_H and 0 <= nx2 < WORLD_W:
                            if wire[ny2, nx2] or plant[ny2, nx2]:
                                adj = True
                                break
                    if adj:
                        wire_target = (conn_x, wy)
                        break

    if wire_target is not None:
        return (Tool.WIRE, wire_target[0], wire_target[1])

    # --- Phase 3: Extend road horizontally ---
    road_target = None
    for rx in range(anchor_x - 1, min(wire_end_x, WORLD_W - 1)):
        ry = road_row
        if 0 <= ry < WORLD_H and 0 <= rx < WORLD_W:
            if not road[ry, rx]:
                adj = False
                for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]:
                    ny2, nx2 = ry+ddy, rx+ddx
                    if 0 <= ny2 < WORLD_H and 0 <= nx2 < WORLD_W:
                        if road[ny2, nx2] or wire[ny2, nx2] or plant[ny2, nx2]:
                            adj = True
                            break
                if adj:
                    road_target = (rx, ry)
                    break

    if road_target is not None:
        return (Tool.ROAD, road_target[0], road_target[1])

    # --- Phase 4: Add cross-roads (vertical spurs) every 6 tiles ---
    spur_xs = list(range(anchor_x + 3, anchor_x + 63, 6))
    for sx in spur_xs:
        if sx >= WORLD_W:
            break
        # Extend spur upward (north) from road_row
        for dy in range(1, 8):
            ry2 = road_row - dy
            if 0 <= ry2 < WORLD_H and 0 <= sx < WORLD_W:
                if not road[ry2, sx]:
                    # Check adjacency
                    adj = False
                    for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]:
                        ny2, nx2 = ry2+ddy, sx+ddx
                        if 0 <= ny2 < WORLD_H and 0 <= nx2 < WORLD_W:
                            if road[ny2, nx2]:
                                adj = True
                                break
                    if adj:
                        return (Tool.ROAD, sx, ry2)
                        break
        # Extend spur downward (south) from road_row
        for dy in range(1, 8):
            ry2 = road_row + dy
            if 0 <= ry2 < WORLD_H and 0 <= sx < WORLD_W:
                if not road[ry2, sx]:
                    adj = False
                    for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]:
                        ny2, nx2 = ry2+ddy, sx+ddx
                        if 0 <= ny2 < WORLD_H and 0 <= nx2 < WORLD_W:
                            if road[ny2, nx2]:
                                adj = True
                                break
                    if adj:
                        return (Tool.ROAD, sx, ry2)

    # --- Phase 5: Place zones ---
    zones = res | com | ind
    n_res = int(np.sum(res))
    n_com = int(np.sum(com))
    n_ind = int(np.sum(ind))
    total_zones = n_res + n_com + n_ind

    # Zone mix: 2 RES : 1 COM : 1 IND
    r = obs.step % 4
    if r < 2:
        tool = Tool.RESIDENTIAL
    elif r == 2:
        tool = Tool.COMMERCIAL
    else:
        tool = Tool.INDUSTRIAL

    # Build proximity maps
    road_near = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            road_near |= np.roll(np.roll(road, dy2, axis=0), dx2, axis=1)

    wire_near = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-4, 5):
        for dx2 in range(-4, 5):
            wire_near |= np.roll(np.roll(wire, dy2, axis=0), dx2, axis=1)
            wire_near |= np.roll(np.roll(plant, dy2, axis=0), dx2, axis=1)

    # Candidate zone centers
    cand_mask = emp & road_near & wire_near
    cand_mask[:2, :] = False
    cand_mask[98:, :] = False
    cand_mask[:, :2] = False
    cand_mask[:, 118:] = False
    # Avoid road and wire rows
    cand_mask[road_row, :] = False
    cand_mask[wire_row, :] = False

    cand_ys, cand_xs = np.where(cand_mask)

    if len(cand_xs) == 0:
        # Fallback: extend road further east
        for rx2 in range(anchor_x, WORLD_W - 1):
            if not road[road_row, rx2]:
                return (Tool.ROAD, rx2, road_row)
        return None

    # Score: prefer near road_row (within 4 rows), near anchor_x..anchor_x+60
    zone_near = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    if np.any(zones):
        for dy2 in range(-4, 5):
            for dx2 in range(-4, 5):
                zone_near |= np.roll(np.roll(zones, dy2, axis=0), dx2, axis=1)

    scores = []
    for i in range(len(cand_xs)):
        x, y = int(cand_xs[i]), int(cand_ys[i])
        dist_road = abs(y - road_row)
        dist_x = max(0, x - (anchor_x + 62)) + max(0, anchor_x - x)
        near_zone = 5 if zone_near[y, x] else 0
        score = near_zone - dist_road * 0.5 - dist_x * 0.2
        scores.append(score)

    scores = np.array(scores)
    max_score = np.max(scores)
    top_mask = scores >= max_score - 1.0
    top_indices = np.where(top_mask)[0]
    pick = top_indices[obs.step % len(top_indices)]
    bx, by = int(cand_xs[pick]), int(cand_ys[pick])
    return (tool, bx, by)

def act(obs, state):
    """
    Closed-loop reactive policy.
    Layout: coal plant at fixed position, wire spine extends right from plant,
    roads above/below wire, zones placed adjacent to roads.
    All decisions based on current tile_map observation.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    all_zone_mask = resm | comm | indm

    # Fixed layout parameters
    PLANT_X, PLANT_Y = 10, 50
    WIRE_ROW = 50
    ROAD_ABOVE = 47
    ROAD_BELOW = 53
    ZONE_ABOVE = 44
    ZONE_BELOW = 56

    # How far to extend wire based on population
    pop = obs.city_pop
    if pop < 50:
        max_wire_x = 25
    elif pop < 150:
        max_wire_x = 40
    elif pop < 400:
        max_wire_x = 60
    elif pop < 800:
        max_wire_x = 85
    else:
        max_wire_x = 110

    # Zone tool selection based on current ratios
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total = res_count + com_count + ind_count

    def pick_tool():
        if total == 0:
            return Tool.RESIDENTIAL
        t = float(total)
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        if com_count / t < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Phase 1: Place coal power plant if not present
    if not np.any(pm):
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    # Find plant center
    plant_rows, plant_cols = np.where(pm)
    plant_cx = int(np.mean(plant_cols))
    plant_cy = int(np.mean(plant_rows))

    # Phase 2: Extend wire from plant rightward
    # Find current wire extent on WIRE_ROW
    wire_on_row = sorted(c for c in range(WORLD_W) if wm[WIRE_ROW, c])

    if not wire_on_row:
        # Start wire immediately right of plant
        start_x = plant_cx + 2
        for x in range(start_x, start_x + 5):
            if 0 <= x < WORLD_W and WIRE_ROW != plant_cy:
                if em[WIRE_ROW, x] or wm[WIRE_ROW, x]:
                    return (Tool.WIRE, x, WIRE_ROW)
        return (Tool.WIRE, plant_cx + 2, WIRE_ROW)

    max_wire = max(wire_on_row)
    min_wire = min(wire_on_row)

    # Extend wire rightward if needed
    if max_wire < max_wire_x:
        nx = max_wire + 1
        if nx < WORLD_W and not pm[WIRE_ROW, nx]:
            if em[WIRE_ROW, nx] or wm[WIRE_ROW, nx]:
                return (Tool.WIRE, nx, WIRE_ROW)

    # Extend wire leftward toward plant if gap
    if min_wire > plant_cx + 2:
        nx = min_wire - 1
        if nx >= 0 and not pm[WIRE_ROW, nx]:
            if em[WIRE_ROW, nx] or wm[WIRE_ROW, nx]:
                return (Tool.WIRE, nx, WIRE_ROW)

    # Phase 3: Build roads above and below wire spine
    # For each wired column, ensure road exists at ROAD_ABOVE and ROAD_BELOW
    for wc in wire_on_row:
        if wc < 2 or wc > WORLD_W - 3:
            continue
        # Road above
        if 0 <= ROAD_ABOVE < WORLD_H:
            if em[ROAD_ABOVE, wc] and not rm[ROAD_ABOVE, wc]:
                return (Tool.ROAD, wc, ROAD_ABOVE)
        # Road below
        if 0 <= ROAD_BELOW < WORLD_H:
            if em[ROAD_BELOW, wc] and not rm[ROAD_BELOW, wc]:
                return (Tool.ROAD, wc, ROAD_BELOW)

    # Phase 4: Place zones adjacent to roads
    # Scan for zone placement spots
    road_above_cols = set(c for c in range(WORLD_W) if 0 <= ROAD_ABOVE < WORLD_H and rm[ROAD_ABOVE, c])
    road_below_cols = set(c for c in range(WORLD_W) if 0 <= ROAD_BELOW < WORLD_H and rm[ROAD_BELOW, c])

    def zone_area_clear(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                # Allow placement on empty or existing zone tiles
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_exists_near(zr, zc):
        for dr in range(-2, 3):
            for dc in range(-2, 3):
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    # Zone rows: ZONE_ABOVE and ZONE_BELOW
    for zc in range(14, min(max_wire + 1, WORLD_W - 3), 4):
        # Try zone above road
        if zc in road_above_cols:
            zr = ZONE_ABOVE
            if 1 <= zr <= WORLD_H - 2 and not zone_exists_near(zr, zc):
                if zone_area_clear(zr, zc):
                    return (pick_tool(), zc, zr)
        # Try zone below road
        if zc in road_below_cols:
            zr = ZONE_BELOW
            if 1 <= zr <= WORLD_H - 2 and not zone_exists_near(zr, zc):
                if zone_area_clear(zr, zc):
                    return (pick_tool(), zc, zr)

    # Phase 5: Second power plant for more zones
    num_plants = int(np.sum(pm)) // 9  # rough estimate
    if pop > 300 and num_plants < 2:
        p2x, p2y = PLANT_X, PLANT_Y + 20
        if 2 <= p2y <= WORLD_H - 3:
            area_ok = all(
                em[p2y + dr, p2x + dc]
                for dr in [-1, 0, 1] for dc in [-1, 0, 1]
                if 0 <= p2y + dr < WORLD_H and 0 <= p2x + dc < WORLD_W
            )
            if area_ok:
                return (Tool.COALPOWER, p2x, p2y)

    # Phase 6: Second wire corridor above (pop > 400)
    if pop > 400:
        WIRE_ROW2 = 38
        ROAD2_ABOVE = 35
        ROAD2_BELOW = 41
        ZONE2_ABOVE = 32
        ZONE2_BELOW = 44

        wire2_on_row = sorted(c for c in range(WORLD_W) if wm[WIRE_ROW2, c])

        if not wire2_on_row:
            # Connect vertically from WIRE_ROW to WIRE_ROW2
            conn_x = plant_cx + 2
            for rr in range(min(WIRE_ROW, WIRE_ROW2), max(WIRE_ROW, WIRE_ROW2) + 1):
                if 0 <= rr < WORLD_H and (em[rr, conn_x] or wm[rr, conn_x]):
                    if not wm[rr, conn_x]:
                        return (Tool.WIRE, conn_x, rr)
        else:
            max_wire2 = max(wire2_on_row)
            if max_wire2 < max_wire_x:
                nx = max_wire2 + 1
                if nx < WORLD_W and (em[WIRE_ROW2, nx] or wm[WIRE_ROW2, nx]):
                    return (Tool.WIRE, nx, WIRE_ROW2)

            for wc in wire2_on_row:
                if wc < 2 or wc > WORLD_W - 3:
                    continue
                if 0 <= ROAD2_ABOVE < WORLD_H and em[ROAD2_ABOVE, wc]:
                    return (Tool.ROAD, wc, ROAD2_ABOVE)
                if 0 <= ROAD2_BELOW < WORLD_H and em[ROAD2_BELOW, wc]:
                    return (Tool.ROAD, wc, ROAD2_BELOW)

            road2a_cols = set(c for c in range(WORLD_W) if 0 <= ROAD2_ABOVE < WORLD_H and rm[ROAD2_ABOVE, c])
            road2b_cols = set(c for c in range(WORLD_W) if 0 <= ROAD2_BELOW < WORLD_H and rm[ROAD2_BELOW, c])

            for zc in range(14, min(max_wire2 + 1, WORLD_W - 3), 4):
                if zc in road2a_cols:
                    zr = ZONE2_ABOVE
                    if 1 <= zr <= WORLD_H - 2 and not zone_exists_near(zr, zc):
                        if zone_area_clear(zr, zc):
                            return (pick_tool(), zc, zr)
                if zc in road2b_cols:
                    zr = ZONE2_BELOW
                    if 1 <= zr <= WORLD_H - 2 and not zone_exists_near(zr, zc):
                        if zone_area_clear(zr, zc):
                            return (pick_tool(), zc, zr)

    # Phase 7: Fill any remaining gaps in roads
    for wc in wire_on_row:
        if wc < 2 or wc > WORLD_W - 3:
            continue
        if 0 <= ROAD_ABOVE < WORLD_H and em[ROAD_ABOVE, wc]:
            return (Tool.ROAD, wc, ROAD_ABOVE)
        if 0 <= ROAD_BELOW < WORLD_H and em[ROAD_BELOW, wc]:
            return (Tool.ROAD, wc, ROAD_BELOW)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy: reads tile_map every step, places the next
    tile based on what currently exists. Uses state only for light phase tracking.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    all_zone = resm | comm | indm

    pop = obs.city_pop
    cx, cy = 58, 50  # center of operations

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                # Allow empty OR existing zone tiles
                if not em[rr, rc] and not all_zone[rr, rc]:
                    return False
        return True

    def zone_exists_near(zr, zc, r=3):
        r0 = max(0, zr - r); r1 = min(WORLD_H, zr + r + 1)
        c0 = max(0, zc - r); c1 = min(WORLD_W, zc + r + 1)
        return bool(np.any(all_zone[r0:r1, c0:c1]))

    def wire_near(zr, zc, radius=3):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return bool(np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1]))

    def road_near(zr, zc, radius=3):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return bool(np.any(rm[r0:r1, c0:c1]))

    # --- Phase 1: Place coal power plant ---
    if not np.any(pm):
        px, py = cx - 10, cy
        return (Tool.COALPOWER, px, py)

    # Find plant center
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Define layout geometry relative to found plant
    wire_col = plant_cx + 3
    road_col_r = wire_col + 2   # road column to the right of wire
    road_col_l = wire_col - 2   # road column to the left of wire
    zone_col_r = road_col_r + 3 # zones right of right road
    zone_col_l = road_col_l - 3 # zones left of left road

    # Clamp
    wire_col   = max(2, min(WORLD_W - 3, wire_col))
    road_col_r = max(2, min(WORLD_W - 3, road_col_r))
    road_col_l = max(2, min(WORLD_W - 3, road_col_l))
    zone_col_r = max(2, min(WORLD_W - 3, zone_col_r))
    zone_col_l = max(2, min(WORLD_W - 3, zone_col_l))

    # Vertical extent scales with population
    if pop < 50:
        half = 10
    elif pop < 150:
        half = 16
    elif pop < 400:
        half = 24
    else:
        half = 32

    y_min = max(1, cy - half)
    y_max = min(WORLD_H - 2, cy + half)

    # Read current infrastructure positions
    wire_rows = sorted([r for r in range(WORLD_H) if wm[r, wire_col]])
    road_rows_r = sorted([r for r in range(WORLD_H) if rm[r, road_col_r]])
    road_rows_l = sorted([r for r in range(WORLD_H) if rm[r, road_col_l]])

    # --- Phase 2: Start wire spine adjacent to plant ---
    if not wire_rows:
        for dy in range(0, 8):
            for nr in [plant_cy + dy, plant_cy - dy]:
                if 0 <= nr < WORLD_H and 0 <= wire_col < WORLD_W:
                    if em[nr, wire_col]:
                        return (Tool.WIRE, wire_col, nr)
        return None

    min_wr = min(wire_rows)
    max_wr = max(wire_rows)

    # --- Phase 3: Ensure plant is connected to wire spine ---
    # Check adjacency between plant tiles and wire tiles
    connected = False
    for pr, pc in zip(plant_rows, plant_cols):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = pr + dr, pc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if wm[rr, rc]:
                        connected = True
    if not connected:
        bridge_r = plant_cy
        for bc in range(plant_cx + 1, wire_col + 1):
            if 0 <= bc < WORLD_W:
                if wm[bridge_r, bc]:
                    break
                if em[bridge_r, bc]:
                    return (Tool.WIRE, bc, bridge_r)

    # --- Phase 4: Extend wire spine vertically ---
    if max_wr < y_max:
        nr = max_wr + 1
        if nr < WORLD_H and em[nr, wire_col] and not pm[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)
    if min_wr > y_min:
        nr = min_wr - 1
        if nr >= 0 and em[nr, wire_col] and not pm[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)

    wire_set = set(wire_rows)

    # --- Phase 5: Build right road column along wire rows ---
    for r in wire_rows:
        if y_min <= r <= y_max:
            if 0 <= road_col_r < WORLD_W and em[r, road_col_r]:
                return (Tool.ROAD, road_col_r, r)

    # --- Phase 6: Build left road column along wire rows ---
    for r in wire_rows:
        if y_min <= r <= y_max:
            if 0 <= road_col_l < WORLD_W and em[r, road_col_l]:
                return (Tool.ROAD, road_col_l, r)

    road_set_r = set(road_rows_r)
    road_set_l = set(road_rows_l)

    # --- Phase 7: Place RIGHT zones (adjacent to right road, near wire) ---
    # Step through every 4 rows for zone centers
    zone_step = 4
    for zr in range(y_min + 1, y_max - 1, zone_step):
        w_close = any(abs(zr - wr) <= 3 for wr in wire_rows)
        r_close = any(abs(zr - rr) <= 3 for rr in road_rows_r)
        if w_close and r_close:
            zc = zone_col_r
            if not zone_exists_near(zr, zc, 2) and zone_area_ok(zr, zc):
                return (pick_tool(), zc, zr)

    # --- Phase 8: Place LEFT zones ---
    for zr in range(y_min + 1, y_max - 1, zone_step):
        w_close = any(abs(zr - wr) <= 3 for wr in wire_rows)
        r_close = any(abs(zr - rr) <= 3 for rr in road_rows_l)
        if w_close and r_close:
            zc = zone_col_l
            if not zone_exists_near(zr, zc, 2) and zone_area_ok(zr, zc):
                return (pick_tool(), zc, zr)

    # --- Phase 9: Extend road rightward to reach right zone col ---
    for rr in road_rows_r:
        if y_min <= rr <= y_max:
            for rc in range(road_col_r + 1, zone_col_r + 2):
                if rc >= WORLD_W:
                    break
                if rm[rr, rc]:
                    break
                if em[rr, rc] and not pm[rr, rc]:
                    return (Tool.ROAD, rc, rr)
                elif not em[rr, rc]:
                    break

    # --- Phase 10: Extend road leftward to reach left zone col ---
    for rr in road_rows_l:
        if y_min <= rr <= y_max:
            for rc in range(road_col_l - 1, zone_col_l - 2, -1):
                if rc < 0:
                    break
                if rm[rr, rc]:
                    break
                if em[rr, rc] and not pm[rr, rc]:
                    return (Tool.ROAD, rc, rr)
                elif not em[rr, rc]:
                    break

    # --- Phase 11: Wire rightward to power right zones ---
    for wr in wire_rows:
        if y_min <= wr <= y_max:
            for wc in range(wire_col + 1, zone_col_r + 3):
                if wc >= WORLD_W:
                    break
                if wm[wr, wc]:
                    break
                if rm[wr, wc]:
                    # skip road tile, wire can't go here but keep going
                    continue
                if em[wr, wc] and not pm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc] and not rm[wr, wc] and not wm[wr, wc]:
                    break

    # --- Phase 12: Wire leftward to power left zones ---
    for wr in wire_rows:
        if y_min <= wr <= y_max:
            for wc in range(wire_col - 1, zone_col_l - 3, -1):
                if wc < 0:
                    break
                if wm[wr, wc]:
                    break
                if rm[wr, wc]:
                    continue
                if em[wr, wc] and not pm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                elif not em[wr, wc] and not rm[wr, wc] and not wm[wr, wc]:
                    break

    # --- Phase 13: Dense fill - scan for any valid zone spot near infra ---
    if pop > 50:
        for zr in range(y_min, y_max + 1, 3):
            for zc_off in [zone_col_r, zone_col_l, zone_col_r - 3, zone_col_l + 3]:
                zc = max(2, min(WORLD_W - 3, zc_off))
                if not zone_exists_near(zr, zc, 2) and zone_area_ok(zr, zc):
                    if wire_near(zr, zc, 5) and road_near(zr, zc, 5):
                        return (pick_tool(), zc, zr)

    # --- Phase 14: Second power plant when population grows ---
    plant_count = max(1, int(np.sum(pm)) // 6)
    if pop > 300 and plant_count < 2:
        # Place second plant to the right
        px2 = plant_cx + 20
        py2 = plant_cy
        if 2 <= px2 <= WORLD_W - 3 and 2 <= py2 <= WORLD_H - 3:
            area_ok = all(
                em[py2 + dr, px2 + dc]
                for dr in [-1, 0, 1] for dc in [-1, 0, 1]
                if 0 <= py2 + dr < WORLD_H and 0 <= px2 + dc < WORLD_W
            )
            if area_ok:
                return (Tool.COALPOWER, px2, py2)

    # --- Phase 15: Extend wire spine further if population growing ---
    if pop > 100:
        extra_half = half + 8
        new_y_min = max(1, cy - extra_half)
        new_y_max = min(WORLD_H - 2, cy + extra_half)
        if min_wr > new_y_min:
            nr = min_wr - 1
            if nr >= 0 and em[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)
        if max_wr < new_y_max:
            nr = max_wr + 1
            if nr < WORLD_H and em[nr, wire_col]:
                return (Tool.WIRE, wire_col, nr)

    return None

def act(obs, state):
    """
    Hybrid policy combining best ideas from both parents:
    - Parent B's simple, effective linear wire+road spine approach
    - Parent A's multi-neighborhood expansion at higher populations
    - Reactive zone placement with road+wire proximity checks
    - Multiple power plants as city grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def area_free(cx, cy):
        if cx < 1 or cx > WORLD_W - 2 or cy < 1 or cy > WORLD_H - 2:
            return False
        for dy in [-1, 0, 1]:
            for dx in [-1, 0, 1]:
                r, c = cy + dy, cx + dx
                if not (0 <= r < WORLD_H and 0 <= c < WORLD_W):
                    return False
                if not em[r, c]:
                    return False
        return True

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # --- Phase 1: Place first coal power plant ---
    if not np.any(pm):
        return (Tool.COALPOWER, 20, 50)

    plant_ys, plant_xs = np.where(pm)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    # --- Determine expansion scale based on pop ---
    pop = obs.city_pop
    if pop < 300:
        target_wire_end = min(px + 50, WORLD_W - 4)
    elif pop < 700:
        target_wire_end = min(px + 80, WORLD_W - 4)
    else:
        target_wire_end = min(px + 100, WORLD_W - 4)

    wire_start_x = px + 3
    spine_y = py

    # --- Phase 2: Build horizontal wire spine along spine_y ---
    spine_wire_cols = [c for c in range(WORLD_W) if wm[spine_y, c]]

    if not spine_wire_cols:
        wx = px + 3
        if in_bounds(wx, spine_y) and em[spine_y, wx]:
            return (Tool.WIRE, wx, spine_y)
        for dy in [-1, 1]:
            wy = spine_y + dy
            if in_bounds(wx, wy) and em[wy, wx]:
                return (Tool.WIRE, wx, wy)
    else:
        max_wire_x = max(spine_wire_cols)
        if max_wire_x < target_wire_end:
            nx = max_wire_x + 1
            if in_bounds(nx, spine_y) and em[spine_y, nx] and not pm[spine_y, nx]:
                return (Tool.WIRE, nx, spine_y)

    # --- Phase 3: Vertical wire branches every 6 cols ---
    branch_cols = list(range(wire_start_x + 3, target_wire_end + 1, 6))
    for bx in branch_cols:
        if not in_bounds(bx, spine_y):
            continue
        if not (bool(wm[spine_y, bx]) or bool(pm[spine_y, bx])):
            continue
        for sign in [-1, 1]:
            for dy in range(1, 5):
                wy = spine_y + sign * dy
                if not in_bounds(bx, wy):
                    break
                if bool(wm[wy, bx]) or bool(pm[wy, bx]):
                    continue
                if bool(em[wy, bx]):
                    return (Tool.WIRE, bx, wy)
                break

    # --- Phase 4: Build road rows parallel to wire spine ---
    road_top = spine_y - 3
    road_bot = spine_y + 3
    road_start = wire_start_x
    road_end = target_wire_end

    road_top_cols = [c for c in range(WORLD_W) if 0 <= road_top < WORLD_H and rm[road_top, c]]
    road_bot_cols = [c for c in range(WORLD_W) if 0 <= road_bot < WORLD_H and rm[road_bot, c]]

    if 0 <= road_top < WORLD_H:
        if not road_top_cols:
            rx = road_start
            if in_bounds(rx, road_top) and em[road_top, rx] and not wm[road_top, rx]:
                return (Tool.ROAD, rx, road_top)
        else:
            max_top = max(road_top_cols)
            if max_top < road_end:
                nx = max_top + 1
                if in_bounds(nx, road_top) and em[road_top, nx] and not wm[road_top, nx] and not pm[road_top, nx]:
                    return (Tool.ROAD, nx, road_top)

    if 0 <= road_bot < WORLD_H:
        if not road_bot_cols:
            rx = road_start
            if in_bounds(rx, road_bot) and em[road_bot, rx] and not wm[road_bot, rx]:
                return (Tool.ROAD, rx, road_bot)
        else:
            max_bot = max(road_bot_cols)
            if max_bot < road_end:
                nx = max_bot + 1
                if in_bounds(nx, road_bot) and em[road_bot, nx] and not wm[road_bot, nx] and not pm[road_bot, nx]:
                    return (Tool.ROAD, nx, road_bot)

    # --- Phase 5: Vertical connector roads every 6 cols ---
    for vc in range(road_start, road_end + 1, 6):
        for vr in range(road_top, road_bot + 1):
            if not in_bounds(vc, vr):
                continue
            if not bool(rm[vr, vc]) and not bool(pm[vr, vc]) and not bool(wm[vr, vc]) and bool(em[vr, vc]):
                connected = False
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr2, nc2 = vr + dr, vc + dc
                    if in_bounds(nc2, nr2) and bool(rm[nr2, nc2]):
                        connected = True
                        break
                if connected:
                    return (Tool.ROAD, vc, vr)

    # --- Phase 6: Place zones reactively near road+wire ---
    # Build neighborhood proximity masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    all_zone = resm | comm | indm
    zone_set = set()
    for arr in [resm, comm, indm]:
        ys2, xs2 = np.where(arr)
        for y2, x2 in zip(ys2.tolist(), xs2.tolist()):
            zone_set.add((int(y2), int(x2)))

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and (nr, nc) not in zone_set:
                    return False
        return True

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        step_hash = int(obs.step * 17 + int(obs.city_pop * 3)) % max(len(cxs_arr), 1)
        for offset in range(min(len(cxs_arr), 100)):
            k = (step_hash + offset * 11) % len(cxs_arr)
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # --- Phase 7: Add second coal plant when city grows ---
    if total_zones > 8 or pop > 150:
        p2x = min(px + 55, WORLD_W - 5)
        p2y = py
        nearby_plant = False
        for dy in range(-8, 9):
            for dx in range(-8, 9):
                ny2, nx2 = p2y + dy, p2x + dx
                if in_bounds(nx2, ny2) and bool(pm[ny2, nx2]):
                    nearby_plant = True
        if not nearby_plant and area_free(p2x, p2y):
            return (Tool.COALPOWER, p2x, p2y)

    # --- Phase 8: Third plant for large cities ---
    if total_zones > 20 or pop > 500:
        p3x = min(px + 100, WORLD_W - 5)
        p3y = py
        nearby_plant3 = False
        for dy in range(-8, 9):
            for dx in range(-8, 9):
                ny2, nx2 = p3y + dy, p3x + dx
                if in_bounds(nx2, ny2) and bool(pm[ny2, nx2]):
                    nearby_plant3 = True
        if not nearby_plant3 and area_free(p3x, p3y):
            return (Tool.COALPOWER, p3x, p3y)

    # --- Phase 9: Services ---
    if pop > 200:
        fx, fy = px + 6, py - 9
        if in_bounds(fx, fy) and area_free(fx, fy):
            return (Tool.FIRESTATION, fx, fy)
        fx2, fy2 = px + 6, py + 9
        if in_bounds(fx2, fy2) and area_free(fx2, fy2):
            return (Tool.POLICESTATION, fx2, fy2)

    if pop > 500:
        for sx, sy in [(px + 30, py - 9), (px + 50, py + 9), (px + 70, py - 9)]:
            if in_bounds(sx, sy) and area_free(sx, sy):
                return (Tool.FIRESTATION, sx, sy)

    # --- Phase 10: Extend wire frontier ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        candidates = list(zip(wire_xs_arr.tolist(), wire_ys_arr.tolist()))
        candidates.sort(key=lambda t: -t[0])
        for wx_s, wy_s in candidates[:10]:
            for dx2, dy2 in [(1, 0), (0, -1), (0, 1), (-1, 0)]:
                nx2, ny2 = wx_s + dx2, wy_s + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # --- Phase 11: Extend road frontier ---
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        candidates_r = list(zip(road_xs_arr.tolist(), road_ys_arr.tolist()))
        candidates_r.sort(key=lambda t: -t[0])
        for rx_s, ry_s in candidates_r[:10]:
            for dx2, dy2 in [(1, 0), (0, -1), (0, 1), (-1, 0)]:
                nx2, ny2 = rx_s + dx2, ry_s + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and not bool(wm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Hybrid policy combining best ideas from both parents:
    - Two neighborhoods (from Parent A) for more coverage
    - Horizontal wire spine + parallel roads (from Parent B)
    - Reactive zone placement with proximity checks
    - Multiple power plants, services as population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    all_zones = resm | comm | indm
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def area_free(cx, cy):
        if cx < 1 or cx > WORLD_W - 2 or cy < 1 or cy > WORLD_H - 2:
            return False
        for dy in [-1, 0, 1]:
            for dx in [-1, 0, 1]:
                r, c = cy + dy, cx + dx
                if not (0 <= r < WORLD_H and 0 <= c < WORLD_W):
                    return False
                if not em[r, c]:
                    return False
        return True

    def pick_zone():
        t = max(total_zones, 1)
        if ind_count / t < 0.22:
            return Tool.INDUSTRIAL
        if com_count / t < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Two neighborhoods, each with its own plant, wire spine, roads, zones
    # Left neighborhood around x=38, right around x=82
    neighborhoods = [
        {'cx': 38, 'cy': 50},
        {'cx': 82, 'cy': 50},
    ]

    # Adaptive x_half based on population
    if pop < 100:
        x_half = 10
    elif pop < 300:
        x_half = 16
    elif pop < 600:
        x_half = 22
    else:
        x_half = 28

    for nb in neighborhoods:
        ncx, ncy = nb['cx'], nb['cy']
        x_min = max(2, ncx - x_half)
        x_max = min(WORLD_W - 3, ncx + x_half)
        wire_row = ncy
        road_above = ncy - 4
        road_below = ncy + 4

        # Check for plant near this neighborhood
        local_pm = pm[max(0, ncy-8):min(WORLD_H, ncy+9),
                      max(0, ncx-x_half-6):min(WORLD_W, ncx+x_half+6)]
        has_plant = np.any(local_pm)

        if not has_plant:
            # Place plant at left edge of neighborhood
            px, py = x_min + 2, wire_row
            if area_free(px, py):
                return (Tool.COALPOWER, px, py)
            # Try nearby positions
            for dy in range(-3, 4):
                for dx in range(-3, 4):
                    npx, npy = px + dx, py + dy
                    if area_free(npx, npy):
                        return (Tool.COALPOWER, npx, npy)
            continue

        # Find plant location for this neighborhood
        plant_rows, plant_cols = np.where(pm)
        near = [(plant_rows[i], plant_cols[i]) for i in range(len(plant_rows))
                if abs(plant_cols[i] - ncx) <= x_half + 6 and abs(plant_rows[i] - ncy) <= 10]
        if not near:
            continue
        plant_cy_nb = int(np.mean([r for r, c in near]))
        plant_cx_nb = int(np.mean([c for r, c in near]))

        # Wire spine: horizontal row at wire_row
        wire_on_row = [c for c in range(WORLD_W) if wm[wire_row, c]
                       and x_min - 5 <= c <= x_max + 5]

        if not wire_on_row:
            # Start wire just right of plant
            for dc in range(1, 12):
                c = plant_cx_nb + dc
                if in_bounds(c, wire_row) and em[wire_row, c] and not pm[wire_row, c]:
                    return (Tool.WIRE, c, wire_row)
            continue

        min_wc = min(wire_on_row)
        max_wc = max(wire_on_row)

        # Extend wire right
        if max_wc < x_max:
            nc = max_wc + 1
            if in_bounds(nc, wire_row) and em[wire_row, nc] and not pm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

        # Extend wire left toward plant
        if min_wc > x_min:
            nc = min_wc - 1
            if in_bounds(nc, wire_row) and (em[wire_row, nc] or wm[wire_row, nc]) and not pm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

        # Connect plant to wire spine if not connected
        plant_connected = False
        for pr, pc in zip(plant_rows, plant_cols):
            if abs(pc - ncx) > x_half + 6:
                continue
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    nr2, nc2 = pr + dr, pc + dc
                    if in_bounds(nc2, nr2) and (wm[nr2, nc2] or rm[nr2, nc2]):
                        plant_connected = True
        if not plant_connected:
            for bc in range(plant_cx_nb + 1, min_wc + 1):
                if in_bounds(bc, wire_row):
                    if wm[wire_row, bc]:
                        break
                    if em[wire_row, bc] and not pm[wire_row, bc]:
                        return (Tool.WIRE, bc, wire_row)

        # Build road rows parallel to wire spine
        for wc in range(x_min, x_max + 1):
            if wm[wire_row, wc]:
                if in_bounds(wc, road_above) and em[road_above, wc] and not pm[road_above, wc]:
                    return (Tool.ROAD, wc, road_above)
                if in_bounds(wc, road_below) and em[road_below, wc] and not pm[road_below, wc]:
                    return (Tool.ROAD, wc, road_below)

        # Vertical connector roads every 8 columns
        for wc in range(x_min, x_max + 1, 8):
            if wm[wire_row, wc]:
                for wr2 in range(road_above, road_below + 1):
                    if in_bounds(wc, wr2) and em[wr2, wc] and not pm[wr2, wc] and not wm[wr2, wc] and not rm[wr2, wc]:
                        return (Tool.ROAD, wc, wr2)

        # Lateral wires from spine to zone columns
        for wc in wire_on_row:
            # Wire leftward
            for wcc in range(wc - 1, x_min - 1, -1):
                if not in_bounds(wcc, wire_row):
                    break
                if wm[wire_row, wcc] or pm[wire_row, wcc]:
                    break
                if em[wire_row, wcc]:
                    return (Tool.WIRE, wcc, wire_row)
                break
            # Wire rightward
            for wcc in range(wc + 1, x_max + 2):
                if not in_bounds(wcc, wire_row):
                    break
                if wm[wire_row, wcc] or pm[wire_row, wcc]:
                    break
                if em[wire_row, wcc]:
                    return (Tool.WIRE, wcc, wire_row)
                break

        # Build neighbor masks for road and wire coverage
        nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-2, 3):
            for dx in range(-2, 3):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

        nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-4, 5):
            for dx in range(-4, 5):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
                nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

        cand_mask = em & nbr_road & nbr_wire
        cand_mask[:2, :] = False
        cand_mask[WORLD_H-2:, :] = False
        cand_mask[:, :2] = False
        cand_mask[:, WORLD_W-2:] = False

        cys_a, cxs_a = np.where(cand_mask)
        if len(cxs_a) > 0:
            # Focus on this neighborhood's x range
            mask_nb = (cxs_a >= x_min) & (cxs_a <= x_max)
            cys_nb = cys_a[mask_nb]
            cxs_nb = cxs_a[mask_nb]
            if len(cxs_nb) > 0:
                dists = np.abs(cxs_nb.astype(int) - ncx) + np.abs(cys_nb.astype(int) - wire_row) * 2
                sort_idx = np.argsort(dists)
                for k_idx in range(min(len(cxs_nb), 80)):
                    k = int(sort_idx[k_idx])
                    zx, zy = int(cxs_nb[k]), int(cys_nb[k])
                    if area_free(zx, zy):
                        return (pick_zone(), zx, zy)

        # Second wire row below for more coverage when pop grows
        if pop > 300:
            wire_row2 = ncy + 12
            wire_on_row2 = [c for c in range(WORLD_W) if wm[wire_row2, c]
                            and x_min - 2 <= c <= x_max + 2]
            if not wire_on_row2:
                # Connect vertically first
                for wr3 in range(wire_row + 1, wire_row2 + 1):
                    wc3 = ncx
                    if in_bounds(wc3, wr3) and em[wr3, wc3] and not pm[wr3, wc3] and not wm[wr3, wc3]:
                        return (Tool.WIRE, wc3, wr3)
            else:
                max_wc2 = max(wire_on_row2)
                min_wc2 = min(wire_on_row2)
                if max_wc2 < x_max:
                    nc = max_wc2 + 1
                    if in_bounds(nc, wire_row2) and em[wire_row2, nc] and not pm[wire_row2, nc]:
                        return (Tool.WIRE, nc, wire_row2)
                if min_wc2 > x_min:
                    nc = min_wc2 - 1
                    if in_bounds(nc, wire_row2) and em[wire_row2, nc] and not pm[wire_row2, nc]:
                        return (Tool.WIRE, nc, wire_row2)

    # Second coal plant if needed
    if pop > 200:
        plant_count = max(1, int(np.sum(pm)) // 6)
        if plant_count < 2:
            for nb in neighborhoods:
                ncx, ncy = nb['cx'], nb['cy']
                for dx in range(-5, 6):
                    for dy in range(-5, 6):
                        px2, py2 = ncx + dx, ncy + dy + 15
                        if area_free(px2, py2):
                            # Check no other plant too close
                            pr2, pc2 = np.where(pm)
                            too_close = any(
                                abs(pc2[i] - px2) < 8 and abs(pr2[i] - py2) < 8
                                for i in range(len(pr2))
                            )
                            if not too_close:
                                return (Tool.COALPOWER, px2, py2)

    # Services
    if pop > 250:
        for sx, sy in [(38, 38), (82, 38)]:
            if area_free(sx, sy):
                return (Tool.FIRESTATION, sx, sy)
    if pop > 400:
        for sx, sy in [(38, 62), (82, 62)]:
            if area_free(sx, sy):
                return (Tool.POLICESTATION, sx, sy)
    if pop > 600:
        for sx, sy in [(60, 50)]:
            if area_free(sx, sy):
                return (Tool.STADIUM, sx, sy)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy combining Parent A (horizontal wire spine + parallel roads)
    and Parent B (vertical wire spine + zone columns).

    Strategy:
    - Place coal plant near center-left
    - Build vertical wire spine from plant
    - Build parallel road column adjacent to wire
    - Place zones on both sides of road/wire
    - Expand with second/third clusters as population grows
    - Add lateral wires/roads to connect zones
    - React entirely to observed tile_map each step
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    pop = obs.city_pop

    # Fixed anchor positions
    plant_cx, plant_cy = 54, 50
    wire_col = 58    # vertical wire spine
    road_col = 61    # parallel road column
    left_zone_col = 55   # zones left of wire
    right_zone_col = 64  # zones right of road

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Dynamic vertical span
    base_span = 12
    extra_span = min(30, pop // 30)
    target_span = base_span + extra_span
    tmin = max(2, plant_cy - target_span)
    tmax = min(WORLD_H - 3, plant_cy + target_span)

    has_plant = np.any(pm)

    # Phase 1: Place coal power plant
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Gather wire and road positions
    wire_positions = list(zip(*np.where(wm))) if np.any(wm) else []
    road_positions = list(zip(*np.where(rm))) if np.any(rm) else []

    wire_rows_in_col = sorted(r for (r, c) in wire_positions if c == wire_col)
    road_rows_in_col = sorted(r for (r, c) in road_positions if c == road_col)
    road_rows_set = set(road_rows_in_col)

    # Phase 2: Extend vertical wire spine
    if not wire_rows_in_col:
        # Start wire adjacent to plant
        for try_r in [plant_cy, plant_cy - 1, plant_cy + 1]:
            if in_bounds(wire_col, try_r) and em[try_r, wire_col]:
                return (Tool.WIRE, wire_col, try_r)
        return None
    else:
        min_wr = min(wire_rows_in_col)
        max_wr = max(wire_rows_in_col)
        if max_wr < tmax:
            nr = max_wr + 1
            if in_bounds(wire_col, nr) and (em[nr, wire_col] or wm[nr, wire_col]):
                if em[nr, wire_col]:
                    return (Tool.WIRE, wire_col, nr)
        if min_wr > tmin:
            nr = min_wr - 1
            if in_bounds(wire_col, nr) and (em[nr, wire_col] or wm[nr, wire_col]):
                if em[nr, wire_col]:
                    return (Tool.WIRE, wire_col, nr)

    if not wire_rows_in_col:
        return None

    wire_rows_set = set(wire_rows_in_col)

    # Phase 3: Build road column matching wire coverage
    for wr in wire_rows_in_col:
        if wr not in road_rows_set and in_bounds(road_col, wr):
            if em[wr, road_col]:
                return (Tool.ROAD, road_col, wr)

    # Zone placement helpers
    res_positions = list(zip(*np.where(res_m))) if np.any(res_m) else []
    com_positions = list(zip(*np.where(com_m))) if np.any(com_m) else []
    ind_positions = list(zip(*np.where(ind_m))) if np.any(ind_m) else []
    all_zones = set(res_positions) | set(com_positions) | set(ind_positions)
    res_count = len(res_positions)
    com_count = len(com_positions)
    ind_count = len(ind_positions)

    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def no_zone_nearby(zr, zc):
        return not any(abs(zr - pr) <= 1 and abs(zc - pc) <= 1 for (pr, pc) in all_zones)

    def pick_zone(res_c, com_c, ind_c):
        total = res_c + com_c + ind_c
        if total == 0 or res_c == 0:
            return Tool.RESIDENTIAL
        if ind_c * 4 < res_c:
            return Tool.INDUSTRIAL
        if com_c * 4 < res_c:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Phase 4: Place zones adjacent to wire/road spine
    for zr in sorted(wire_rows_in_col):
        # Must have road nearby
        road_nearby = any(abs(zr - rr) <= 2 for rr in road_rows_set)
        if not road_nearby:
            continue
        for zc in [left_zone_col, right_zone_col]:
            if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                if no_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                    return (pick_zone(res_count, com_count, ind_count), zc, zr)

    # Phase 5: Lateral wires from spine to left zones
    for wr in wire_rows_in_col:
        for wc in range(wire_col - 1, max(left_zone_col - 2, 0), -1):
            if in_bounds(wc, wr) and em[wr, wc]:
                return (Tool.WIRE, wc, wr)
            elif in_bounds(wc, wr) and wm[wr, wc]:
                break  # already wired this row

    # Phase 6: Lateral roads from road col to right zones
    for wr in wire_rows_in_col:
        for rc in range(road_col + 1, min(right_zone_col + 2, WORLD_W)):
            if in_bounds(rc, wr) and em[wr, rc]:
                return (Tool.ROAD, rc, wr)
            elif in_bounds(rc, wr) and rm[wr, rc]:
                break

    # Phase 7: Second cluster (right) when pop >= 150
    if pop >= 150:
        wire_col2 = road_col + 9   # col 70
        road_col2 = wire_col2 + 2  # col 72
        left_zone_col2 = wire_col2 - 3  # col 67
        right_zone_col2 = road_col2 + 3  # col 75

        wire_rows2 = sorted(r for (r, c) in wire_positions if c == wire_col2)
        road_rows2 = set(r for (r, c) in road_positions if c == road_col2)

        if not wire_rows2:
            # Bridge horizontally at plant_cy to reach wire_col2
            for wc in range(wire_col + 1, wire_col2 + 1):
                if in_bounds(wc, plant_cy) and em[plant_cy, wc]:
                    return (Tool.WIRE, wc, plant_cy)
        else:
            min_wr2 = min(wire_rows2)
            max_wr2 = max(wire_rows2)
            if max_wr2 < tmax:
                nr = max_wr2 + 1
                if in_bounds(wire_col2, nr) and em[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > tmin:
                nr = min_wr2 - 1
                if in_bounds(wire_col2, nr) and em[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)

            for wr in wire_rows2:
                if wr not in road_rows2 and in_bounds(road_col2, wr):
                    if em[wr, road_col2]:
                        return (Tool.ROAD, road_col2, wr)

            for zr in sorted(wire_rows2):
                rn2 = any(abs(zr - rr) <= 2 for rr in road_rows2)
                if not rn2:
                    continue
                for zc in [left_zone_col2, right_zone_col2]:
                    if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                        if no_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                            return (pick_zone(res_count, com_count, ind_count), zc, zr)

            for wr in wire_rows2:
                for wc in range(wire_col2 - 1, max(left_zone_col2 - 2, 0), -1):
                    if in_bounds(wc, wr) and em[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    elif in_bounds(wc, wr) and wm[wr, wc]:
                        break
            for wr in wire_rows2:
                for rc in range(road_col2 + 1, min(right_zone_col2 + 2, WORLD_W)):
                    if in_bounds(rc, wr) and em[wr, rc]:
                        return (Tool.ROAD, rc, wr)
                    elif in_bounds(rc, wr) and rm[wr, rc]:
                        break

    # Phase 8: Third cluster (left) when pop >= 350
    if pop >= 350:
        wire_col3 = wire_col - 9   # col 49
        road_col3 = wire_col3 - 2  # col 47
        left_zone_col3 = road_col3 - 3  # col 44
        right_zone_col3 = wire_col3 + 3  # col 52

        wire_rows3 = sorted(r for (r, c) in wire_positions if c == wire_col3)
        road_rows3 = set(r for (r, c) in road_positions if c == road_col3)

        if not wire_rows3:
            for wc in range(wire_col - 1, wire_col3 - 1, -1):
                if in_bounds(wc, plant_cy) and em[plant_cy, wc]:
                    return (Tool.WIRE, wc, plant_cy)
        else:
            min_wr3 = min(wire_rows3)
            max_wr3 = max(wire_rows3)
            if max_wr3 < tmax:
                nr = max_wr3 + 1
                if in_bounds(wire_col3, nr) and em[nr, wire_col3]:
                    return (Tool.WIRE, wire_col3, nr)
            if min_wr3 > tmin:
                nr = min_wr3 - 1
                if in_bounds(wire_col3, nr) and em[nr, wire_col3]:
                    return (Tool.WIRE, wire_col3, nr)

            for wr in wire_rows3:
                if wr not in road_rows3 and in_bounds(road_col3, wr):
                    if em[wr, road_col3]:
                        return (Tool.ROAD, road_col3, wr)

            for zr in sorted(wire_rows3):
                rn3 = any(abs(zr - rr) <= 2 for rr in road_rows3)
                if not rn3:
                    continue
                for zc in [left_zone_col3, right_zone_col3]:
                    if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                        if no_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                            return (pick_zone(res_count, com_count, ind_count), zc, zr)

            for wr in wire_rows3:
                for wc in range(wire_col3 - 1, max(left_zone_col3 - 2, 0), -1):
                    if in_bounds(wc, wr) and em[wr, wc]:
                        return (Tool.WIRE, wc, wr)
                    elif in_bounds(wc, wr) and wm[wr, wc]:
                        break
            for wr in wire_rows3:
                for rc in range(road_col3 + 1, min(right_zone_col3 + 2, WORLD_W)):
                    if in_bounds(rc, wr) and em[wr, rc]:
                        return (Tool.ROAD, rc, wr)
                    elif in_bounds(rc, wr) and rm[wr, rc]:
                        break

    # Phase 9: Second power plant if pop > 400
    if pop > 400:
        plant_rows, plant_cols = np.where(pm)
        plant_count = max(1, len(plant_rows) // 6)
        if plant_count < 2:
            p2x, p2y = wire_col2 if pop >= 150 else wire_col, plant_cy
            # Try placing it further right
            p2x = 80
            p2y = plant_cy
            if in_bounds(p2x, p2y) and em[p2y, p2x]:
                nearby = any(
                    in_bounds(p2x + dx, p2y + dy) and pm[p2y + dy, p2x + dx]
                    for dy in range(-5, 6) for dx in range(-5, 6)
                )
                if not nearby:
                    return (Tool.COALPOWER, p2x, p2y)

    # Phase 10: Services
    if pop > 250:
        fx, fy = 58, plant_cy - 14
        if in_bounds(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
    if pop > 400:
        px2, py2 = 65, plant_cy + 16
        if in_bounds(px2, py2) and em[py2, px2]:
            return (Tool.POLICESTATION, px2, py2)
    if pop > 600:
        fx2, fy2 = 52, plant_cy + 16
        if in_bounds(fx2, fy2) and em[fy2, fx2]:
            return (Tool.FIRESTATION, fx2, fy2)

    # Phase 11: Fill remaining empty candidate spots near wire/road
    # Build neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand = em & nbr_road & nbr_wire
    cand[:2, :] = False; cand[WORLD_H-2:, :] = False
    cand[:, :2] = False; cand[:, WORLD_W-2:] = False
    cys_a, cxs_a = np.where(cand)
    if len(cxs_a) > 0:
        dists = np.abs(cxs_a.astype(int) - plant_cx) + np.abs(cys_a.astype(int) - plant_cy)
        sort_idx = np.argsort(dists)
        for k in sort_idx[:80]:
            zx, zy = int(cxs_a[k]), int(cys_a[k])
            if zone_area_free(zy, zx) and no_zone_nearby(zy, zx):
                return (pick_zone(res_count, com_count, ind_count), zx, zy)

    return None

def act(obs, state):
    """
    Hybrid policy combining Parent A's horizontal wire spine with road rows
    and Parent B's vertical wire spine with flanking roads and zone columns.
    Strategy:
    - Horizontal wire spine at cy (Parent A style)
    - Vertical roads above and below spine (Parent A)
    - Zone placement using Parent B's proximity checks
    - Second vertical spine expansion (Parent B)
    - Reactive gap filling and densification
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2
    pop = obs.city_pop

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    all_zone_mask = resm | comm | indm

    def zone_area_clear(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not (em[rr, rc] or all_zone_mask[rr, rc]):
                    return False
        return True

    def zone_overlap(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    # ---- Phase 1: Ensure power plant ----
    if not np.any(pm):
        return (Tool.COALPOWER, cx - 15, cy)

    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Horizontal wire spine row
    wire_row = cy
    road_above = cy - 4
    road_below = cy + 4

    # Population-scaled extent
    if pop < 100:
        x_half = 14
    elif pop < 300:
        x_half = 24
    elif pop < 600:
        x_half = 36
    elif pop < 1000:
        x_half = 48
    else:
        x_half = 56

    x_min = max(4, cx - x_half)
    x_max = min(WORLD_W - 5, cx + x_half)

    # ---- Phase 2: Build horizontal wire spine ----
    wire_on_row = [c for c in range(WORLD_W) if wm[wire_row, c]]

    if not wire_on_row:
        # Start wire just right of plant
        for dc in range(1, 12):
            c = plant_cx + dc
            if in_bounds(c, wire_row) and em[wire_row, c]:
                return (Tool.WIRE, c, wire_row)
        return None

    min_wc = min(wire_on_row)
    max_wc = max(wire_on_row)

    # Extend wire right
    if max_wc < x_max:
        nc = max_wc + 1
        if in_bounds(nc, wire_row) and not pm[wire_row, nc]:
            if em[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # Extend wire left toward plant area
    if min_wc > x_min:
        nc = min_wc - 1
        if in_bounds(nc, wire_row) and not pm[wire_row, nc]:
            if em[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # ---- Phase 3: Connect plant to wire spine ----
    plant_connected = False
    for pr, pc in zip(plant_rows, plant_cols):
        for dr in range(-2, 3):
            for dc in range(-2, 3):
                nr, nc2 = pr + dr, pc + dc
                if in_bounds(nc2, nr) and (wm[nr, nc2] or rm[nr, nc2]):
                    plant_connected = True
    if not plant_connected and wire_on_row:
        target_c = min_wc
        for bc in range(plant_cx + 1, target_c + 1):
            if in_bounds(bc, wire_row):
                if wm[wire_row, bc]:
                    break
                if em[wire_row, bc] and not pm[wire_row, bc]:
                    return (Tool.WIRE, bc, wire_row)
        # Vertical connector
        step_r = 1 if wire_row > plant_cy else -1
        bc2 = plant_cx + 2
        for br in range(plant_cy + step_r, wire_row + step_r, step_r):
            if in_bounds(bc2, br) and em[br, bc2] and not pm[br, bc2]:
                return (Tool.WIRE, bc2, br)

    # ---- Phase 4: Build parallel road rows ----
    for wc in range(x_min, x_max + 1):
        if not wm[wire_row, wc]:
            continue
        if in_bounds(wc, road_above) and em[road_above, wc] and not pm[road_above, wc]:
            return (Tool.ROAD, wc, road_above)
        if in_bounds(wc, road_below) and em[road_below, wc] and not pm[road_below, wc]:
            return (Tool.ROAD, wc, road_below)

    # ---- Phase 5: Vertical connector roads every 6 columns ----
    for wc in range(x_min, x_max + 1, 6):
        if wm[wire_row, wc]:
            for wr2 in range(road_above, road_below + 1):
                if in_bounds(wc, wr2) and em[wr2, wc] and not pm[wr2, wc] and not wm[wr2, wc] and not rm[wr2, wc]:
                    return (Tool.ROAD, wc, wr2)

    # ---- Phase 6: Place zones adjacent to roads with wire coverage ----
    # Build neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, :2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys_a, cxs_a = np.where(cand_mask)
    if len(cxs_a) > 0:
        dists = np.abs(cxs_a.astype(int) - cx) + np.abs(cys_a.astype(int) - wire_row) * 2
        sort_idx = np.argsort(dists)
        for k_idx in range(min(len(cxs_a), 150)):
            k = int(sort_idx[k_idx])
            zx, zy = int(cxs_a[k]), int(cys_a[k])
            if x_min <= zx <= x_max and zone_area_clear(zy, zx) and not zone_overlap(zy, zx):
                return (pick_tool(), zx, zy)

    # ---- Phase 7: Second power plant ----
    plant_tiles = int(np.sum(pm))
    plant_count = max(1, plant_tiles // 6)

    if pop > 200 and plant_count < 2:
        p2x = min(WORLD_W - 5, plant_cx + 40)
        p2y = wire_row
        if in_bounds(p2x, p2y) and em[p2y, p2x]:
            nearby = any(
                in_bounds(p2x + dx2, p2y + dy2) and pm[p2y + dy2, p2x + dx2]
                for dy2 in range(-6, 7) for dx2 in range(-6, 7)
            )
            if not nearby:
                return (Tool.COALPOWER, p2x, p2y)
        # Extend wire to reach second plant
        if max_wc < p2x - 2:
            nc = max_wc + 1
            if in_bounds(nc, wire_row) and em[wire_row, nc] and not pm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    if pop > 500 and plant_count < 3:
        p3x = max(4, plant_cx - 2)
        p3y = wire_row + 20
        if in_bounds(p3x, p3y) and em[p3y, p3x]:
            nearby = any(
                in_bounds(p3x + dx2, p3y + dy2) and pm[p3y + dy2, p3x + dx2]
                for dy2 in range(-6, 7) for dx2 in range(-6, 7)
            )
            if not nearby:
                return (Tool.COALPOWER, p3x, p3y)

    # ---- Phase 8: Services ----
    if pop > 200:
        fx, fy = cx, cy - 12
        if in_bounds(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
    if pop > 350:
        px2, py2 = cx + 15, cy + 12
        if in_bounds(px2, py2) and em[py2, px2]:
            return (Tool.POLICESTATION, px2, py2)
    if pop > 600:
        fx2, fy2 = cx - 15, cy + 12
        if in_bounds(fx2, fy2) and em[fy2, fx2]:
            return (Tool.FIRESTATION, fx2, fy2)

    # ---- Phase 9: Second wire spine (Parent B style, vertical) ----
    if pop > 300:
        wire2_col = x_max + 6
        wire2_col = max(3, min(WORLD_W - 4, wire2_col))
        wire_rows2 = [r for r in range(WORLD_H) if wm[r, wire2_col]]

        if not wire_rows2:
            # Bridge horizontally from main spine at cy
            for wc in range(max_wc + 1, wire2_col + 1):
                if in_bounds(wc, cy):
                    if wm[cy, wc]:
                        break
                    if em[cy, wc] and not rm[cy, wc] and not pm[cy, wc]:
                        return (Tool.WIRE, wc, cy)
        else:
            min_wr2 = min(wire_rows2)
            max_wr2 = max(wire_rows2)
            road2_r = wire2_col + 2
            road2_l = wire2_col - 2
            road2_r = max(2, min(WORLD_W - 3, road2_r))
            road2_l = max(2, min(WORLD_W - 3, road2_l))

            spine_top2 = max(2, cy - x_half // 2)
            spine_bot2 = min(WORLD_H - 3, cy + x_half // 2)

            if max_wr2 < spine_bot2:
                nr = max_wr2 + 1
                if in_bounds(wire2_col, nr) and not pm[nr, wire2_col]:
                    if em[nr, wire2_col] or wm[nr, wire2_col]:
                        return (Tool.WIRE, wire2_col, nr)
            if min_wr2 > spine_top2:
                nr = min_wr2 - 1
                if in_bounds(wire2_col, nr) and not pm[nr, wire2_col]:
                    if em[nr, wire2_col] or wm[nr, wire2_col]:
                        return (Tool.WIRE, wire2_col, nr)

            road2r_present = set(r for r in range(WORLD_H) if rm[r, road2_r])
            road2l_present = set(r for r in range(WORLD_H) if rm[r, road2_l])

            for wr in wire_rows2:
                if spine_top2 <= wr <= spine_bot2:
                    if wr not in road2r_present and in_bounds(road2_r, wr) and em[wr, road2_r]:
                        return (Tool.ROAD, road2_r, wr)
                    if wr not in road2l_present and in_bounds(road2_l, wr) and em[wr, road2_l]:
                        return (Tool.ROAD, road2_l, wr)

            zone2_r = road2_r + 3
            zone2_l = road2_l - 3
            zone2_r = max(2, min(WORLD_W - 4, zone2_r))
            zone2_l = max(3, min(WORLD_W - 3, zone2_l))

            for wr in wire_rows2:
                if wr in road2r_present:
                    if not zone_overlap(wr, zone2_r) and zone_area_clear(wr, zone2_r):
                        return (pick_tool(), zone2_r, wr)
                if wr in road2l_present:
                    if not zone_overlap(wr, zone2_l) and zone_area_clear(wr, zone2_l):
                        return (pick_tool(), zone2_l, wr)

    # ---- Phase 10: Second parallel wire row for more coverage ----
    if pop > 400:
        wire2_row = cy + 12
        wire_on_row2 = [c for c in range(WORLD_W) if wm[wire2_row, c]]
        if not wire_on_row2:
            # Connect from first spine at a vertical point
            for wc in range(x_min, x_max + 1, 8):
                if wm[wire_row, wc]:
                    for wr3 in range(wire_row + 1, wire2_row + 1):
                        if in_bounds(wc, wr3) and em[wr3, wc] and not pm[wr3, wc] and not wm[wr3, wc]:
                            return (Tool.WIRE, wc, wr3)
        else:
            max_wc2 = max(wire_on_row2)
            if max_wc2 < x_max:
                nc = max_wc2 + 1
                if in_bounds(nc, wire2_row) and em[wire2_row, nc] and not pm[wire2_row, nc]:
                    return (Tool.WIRE, nc, wire2_row)

            road_above2 = wire2_row - 4
            road_below2 = wire2_row + 4
            for wc in range(x_min, x_max + 1):
                if not wm[wire2_row, wc]:
                    continue
                if in_bounds(wc, road_above2) and em[road_above2, wc] and not pm[road_above2, wc]:
                    return (Tool.ROAD, wc, road_above2)
                if in_bounds(wc, road_below2) and em[road_below2, wc] and not pm[road_below2, wc]:
                    return (Tool.ROAD, wc, road_below2)

            # Place zones off second wire row
            cand_mask2 = em & nbr_road & nbr_wire
            cand_mask2[:2, :] = False
            cand_mask2[WORLD_H - 2:, :] = False
            cand_mask2[:, :2] = False
            cand_mask2[:, WORLD_W - 2:] = False
            cys2, cxs2 = np.where(cand_mask2)
            if len(cxs2) > 0:
                dists2 = np.abs(cxs2.astype(int) - cx) + np.abs(cys2.astype(int) - wire2_row) * 2
                sort_idx2 = np.argsort(dists2)
                for k_idx in range(min(len(cxs2), 80)):
                    k = int(sort_idx2[k_idx])
                    zx2, zy2 = int(cxs2[k]), int(cys2[k])
                    if x_min <= zx2 <= x_max and zy2 > wire_row + 2:
                        if zone_area_clear(zy2, zx2) and not zone_overlap(zy2, zx2):
                            return (pick_tool(), zx2, zy2)

    # ---- Phase 11: Reactive road/wire extension ----
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = int(obs.step * 13) % len(road_xs_arr)
        rx_s = int(road_xs_arr[step_k])
        ry_s = int(road_ys_arr[step_k])
        for dy2, dx2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx2, ny2 = rx_s + dx2, ry_s + dy2
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                if nbr_wire[ny2, nx2] and x_min <= nx2 <= x_max:
                    return (Tool.ROAD, nx2, ny2)

    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k = int(obs.step * 7) % len(wire_xs_arr)
        wx_s = int(wire_xs_arr[step_k])
        wy_s = int(wire_ys_arr[step_k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = wx_s + dx2, wy_s + dy2
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                if x_min <= nx2 <= x_max:
                    return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder.
    Reads tile_map every step to adapt placement.
    Strategy: two clusters (left+right) with coal plants,
    wire spines connecting them, road grid, then zones.
    Every decision is based on current map state.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    all_zone = resm | comm | indm

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def near(mask, r, c, radius):
        r0 = max(0, r - radius); r1 = min(WORLD_H, r + radius + 1)
        c0 = max(0, c - radius); c1 = min(WORLD_W, c + radius + 1)
        return bool(np.any(mask[r0:r1, c0:c1]))

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone[rr, rc]:
                    return False
        return True

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        if ind_count / total_zones < 0.22:
            return Tool.INDUSTRIAL
        if com_count / total_zones < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    pop = obs.city_pop

    # Two cluster centers
    AX, AY = 30, 50
    BX, BY = 85, 50
    # Wire spine row (horizontal)
    SPINE_Y = 48
    # Road row (horizontal, just below spine)
    ROAD_Y = 52

    power_map = pm | wm

    # --- Step 1: Ensure plant A exists ---
    if not np.any(pm):
        return (Tool.COALPOWER, AX, AY)

    plant_rows, plant_cols = np.where(pm)
    plant_count_tiles = int(np.sum(pm))
    # Each coal plant is 3x3 = 9 tiles
    num_plants = max(1, plant_count_tiles // 6)

    # --- Step 2: Wire from plant A toward spine ---
    # Check if plant A is connected to any wire
    a_connected = near(wm, AY, AX, 4)
    if not a_connected:
        # Place wire bridging plant A to spine
        for step_y in range(AY - 1, SPINE_Y - 1, -1):
            if in_bounds(AX, step_y) and em[step_y, AX]:
                return (Tool.WIRE, AX, step_y)
        for step_y in range(AY + 1, SPINE_Y + 1):
            if in_bounds(AX, step_y) and em[step_y, AX]:
                return (Tool.WIRE, AX, step_y)

    # --- Step 3: Build horizontal wire spine ---
    # Extend wire spine from AX to BX at SPINE_Y
    spine_wires = [c for c in range(WORLD_W) if in_bounds(c, SPINE_Y) and wm[SPINE_Y, c]]
    if not spine_wires:
        # Start spine near plant A
        for dc in range(0, 6):
            cx2 = AX + dc
            if in_bounds(cx2, SPINE_Y) and em[SPINE_Y, cx2]:
                return (Tool.WIRE, cx2, SPINE_Y)
    else:
        min_wc = min(spine_wires)
        max_wc = max(spine_wires)
        target_left = AX - 10
        target_right = BX + 10
        # Extend rightward first (toward cluster B)
        if max_wc < target_right:
            nc = max_wc + 1
            if in_bounds(nc, SPINE_Y) and em[SPINE_Y, nc] and not pm[SPINE_Y, nc]:
                return (Tool.WIRE, nc, SPINE_Y)
        # Extend leftward
        if min_wc > target_left:
            nc = min_wc - 1
            if in_bounds(nc, SPINE_Y) and em[SPINE_Y, nc] and not pm[SPINE_Y, nc]:
                return (Tool.WIRE, nc, SPINE_Y)

    # --- Step 4: Plant B if spine reaches cluster B area ---
    spine_reach = max([c for c in range(WORLD_W) if wm[SPINE_Y, c]], default=AX)
    if spine_reach >= BX - 5 and num_plants < 2 and pop >= 0:
        if in_bounds(BX, BY) and em[BY, BX]:
            return (Tool.COALPOWER, BX, BY)

    # --- Step 5: Connect plant B to spine with wire ---
    b_connected = near(wm, BY, BX, 4)
    if np.any(pm) and int(np.mean(plant_cols)) > (AX + BX) // 2 - 10:
        # Plant B may exist, connect it
        if not b_connected and near(pm, BY, BX, 5):
            for step_y in range(BY - 1, SPINE_Y - 1, -1):
                if in_bounds(BX, step_y) and em[step_y, BX]:
                    return (Tool.WIRE, BX, step_y)

    # --- Step 6: Build horizontal road spine ---
    road_wires = [c for c in range(WORLD_W) if in_bounds(c, ROAD_Y) and rm[ROAD_Y, c]]
    if not road_wires:
        # Start road near plant A
        for dc in range(0, 6):
            cx2 = AX + dc
            if in_bounds(cx2, ROAD_Y) and em[ROAD_Y, cx2]:
                return (Tool.ROAD, cx2, ROAD_Y)
    else:
        min_rc = min(road_wires)
        max_rc = max(road_wires)
        target_left_r = AX - 10
        target_right_r = BX + 10
        if max_rc < target_right_r:
            nc = max_rc + 1
            if in_bounds(nc, ROAD_Y) and em[ROAD_Y, nc] and not pm[ROAD_Y, nc]:
                return (Tool.ROAD, nc, ROAD_Y)
        if min_rc > target_left_r:
            nc = min_rc - 1
            if in_bounds(nc, ROAD_Y) and em[ROAD_Y, nc] and not pm[ROAD_Y, nc]:
                return (Tool.ROAD, nc, ROAD_Y)

    # --- Step 7: Build vertical roads/wires in cluster columns ---
    # For cluster A: vertical road at AX, wire at AX-3
    # For cluster B: vertical road at BX, wire at BX+3
    for (cx3, wy3, ry3, dy_range) in [
        (AX, AX - 4, AX, range(SPINE_Y - 12, SPINE_Y + 12)),
        (BX, BX + 4, BX, range(SPINE_Y - 12, SPINE_Y + 12)),
    ]:
        for row in dy_range:
            if not in_bounds(wy3, row):
                continue
            # Wire column
            if em[row, wy3] and not pm[row, wy3]:
                # Only if adjacent to existing wire/plant
                if near(power_map, row, wy3, 2):
                    return (Tool.WIRE, wy3, row)
            # Road column
            if not in_bounds(ry3, row):
                continue
            if em[row, ry3] and not pm[row, ry3] and not wm[row, ry3]:
                if near(rm, row, ry3, 2) or near(pm, row, ry3, 3):
                    return (Tool.ROAD, ry3, row)

    # --- Step 8: Reactive zone placement ---
    # Scan entire map for spots near both road and power
    # Build neighbor maps efficiently
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= power_map[sr0:sr1, sc0:sc1]

    cand = em & nbr_road & nbr_power
    # Keep away from borders
    cand[:2, :] = False; cand[WORLD_H-2:, :] = False
    cand[:, :2] = False; cand[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        # Deterministic but responsive to map state
        key = int(obs.step * 17 + int(pop * 3) + 1) % len(cxs)
        for offset in range(min(len(cxs), 120)):
            k = (key + offset * 13) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_area_ok(zy, zx):
                return (pick_tool(), zx, zy)

    # --- Step 9: Additional power plant if needed ---
    if pop > 300 and num_plants < 3:
        mx = (AX + BX) // 2
        my = AY + 10
        mx = max(2, min(WORLD_W - 3, mx))
        my = max(2, min(WORLD_H - 3, my))
        if em[my, mx]:
            return (Tool.COALPOWER, mx, my)

    # --- Step 10: Services ---
    if pop > 200:
        for fx, fy in [(AX - 8, AY - 8), (BX + 8, BY - 8),
                       (AX + 8, AY + 10), (BX - 8, BY + 10)]:
            fx = max(1, min(WORLD_W - 2, fx))
            fy = max(1, min(WORLD_H - 2, fy))
            if em[fy, fx]:
                return (Tool.FIRESTATION, fx, fy)
    if pop > 400:
        for fx, fy in [(AX, AY + 12), (BX, BY + 12)]:
            fx = max(1, min(WORLD_W - 2, fx))
            fy = max(1, min(WORLD_H - 2, fy))
            if em[fy, fx]:
                return (Tool.POLICESTATION, fx, fy)

    # --- Fallback: grow wire from any existing wire ---
    wys2, wxs2 = np.where(wm)
    if len(wxs2) > 0:
        k3 = int(obs.step * 7) % len(wxs2)
        wx2, wy2 = int(wxs2[k3]), int(wys2[k3])
        for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = wx2 + ddx, wy2 + ddy
            if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx]:
                return (Tool.WIRE, nx, ny)

    # --- Fallback: grow road from any existing road ---
    rys2, rxs2 = np.where(rm)
    if len(rxs2) > 0:
        k2 = int(obs.step * 11) % len(rxs2)
        rx2, ry2 = int(rxs2[k2]), int(rys2[k2])
        for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = rx2 + ddx, ry2 + ddy
            if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx]:
                return (Tool.ROAD, nx, ny)

    return None

def act(obs, state):
    """
    Improved policy: horizontal spine layout instead of vertical.
    - Coal plant at left side
    - Wire runs horizontally from plant
    - Road runs parallel below wire
    - Zones placed above and below the spine in columns
    - Better zone mix (RCI balance)
    - Multiple clusters
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    all_zones = resm | comm | indm

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(1, total_zones)
        if ind_count / t < 0.25:
            return Tool.INDUSTRIAL
        if com_count / t < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zones[rr, rc]:
                    return False
        return True

    def zone_present(zr, zc, radius=2):
        r0 = max(0, zr - radius); r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius); c1 = min(WORLD_W, zc + radius + 1)
        return np.any(all_zones[r0:r1, c0:c1])

    # --- Phase 0: Place power plant if none exists ---
    if not np.any(pm):
        # Place plant at top-left area with some margin
        return (Tool.COALPOWER, 10, 20)

    # Find plant center
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Horizontal spine layout
    wire_row = plant_cy       # wire spine row (horizontal)
    road_row = plant_cy + 2   # road row parallel to wire, below
    above_zone_row = plant_cy - 5  # zones above spine
    below_zone_row = plant_cy + 7  # zones below spine

    # Second cluster offset
    wire_row2 = plant_cy + 20
    road_row2 = plant_cy + 22
    above_zone_row2 = plant_cy + 15
    below_zone_row2 = plant_cy + 27

    # Clamp rows
    wire_row = max(1, min(WORLD_H - 2, wire_row))
    road_row = max(1, min(WORLD_H - 2, road_row))
    above_zone_row = max(1, min(WORLD_H - 2, above_zone_row))
    below_zone_row = max(1, min(WORLD_H - 2, below_zone_row))
    wire_row2 = max(1, min(WORLD_H - 2, wire_row2))
    road_row2 = max(1, min(WORLD_H - 2, road_row2))
    above_zone_row2 = max(1, min(WORLD_H - 2, above_zone_row2))
    below_zone_row2 = max(1, min(WORLD_H - 2, below_zone_row2))

    # Determine horizontal extent based on population
    if obs.city_pop < 50:
        extent = 15
    elif obs.city_pop < 200:
        extent = 30
    elif obs.city_pop < 500:
        extent = 50
    elif obs.city_pop < 1000:
        extent = 70
    else:
        extent = 90

    spine_left = plant_cx + 3
    spine_right = min(WORLD_W - 3, plant_cx + extent)

    # --- Phase 1: Extend wire spine rightward from plant ---
    wire_cols_on_row = [c for c in range(WORLD_W) if wm[wire_row, c]]
    if not wire_cols_on_row:
        # Start wire adjacent to plant
        for dc in range(1, 5):
            nc = plant_cx + dc
            nr = wire_row
            if 0 <= nc < WORLD_W and 0 <= nr < WORLD_H:
                if em[nr, nc] or wm[nr, nc]:
                    return (Tool.WIRE, nc, nr)
        return (Tool.WIRE, plant_cx + 2, wire_row)

    max_wire_col = max(wire_cols_on_row)
    if max_wire_col < spine_right:
        nc = max_wire_col + 1
        if 0 <= nc < WORLD_W and em[wire_row, nc]:
            return (Tool.WIRE, nc, wire_row)
        elif 0 <= nc < WORLD_W and not pm[wire_row, nc]:
            if nc + 1 < WORLD_W and em[wire_row, nc + 1]:
                return (Tool.WIRE, nc + 1, wire_row)

    # --- Phase 2: Extend road spine parallel to wire ---
    road_cols_on_row = [c for c in range(WORLD_W) if rm[road_row, c]]
    current_road_extent = min(max_wire_col, spine_right)

    if not road_cols_on_row:
        if 0 <= spine_left < WORLD_W and em[road_row, spine_left]:
            return (Tool.ROAD, spine_left, road_row)
        return (Tool.ROAD, spine_left + 1, road_row)

    max_road_col = max(road_cols_on_row)
    if max_road_col < current_road_extent:
        nc = max_road_col + 1
        if 0 <= nc < WORLD_W and em[road_row, nc]:
            return (Tool.ROAD, nc, road_row)

    # --- Phase 3: Place zones above and below spine ---
    wire_cols_set = set(wire_cols_on_row)
    road_cols_set = set(road_cols_on_row)

    # Place zones at every ~4 columns along the spine
    for wc in sorted(wire_cols_set):
        if wc < spine_left:
            continue
        # Need road access nearby
        road_near = any(abs(wc - rc) <= 2 for rc in road_cols_set)
        if not road_near:
            continue

        # Above zone
        zr, zc = above_zone_row, wc
        if not zone_present(zr, zc) and zone_area_ok(zr, zc):
            r0 = max(0, zr - 5); r1 = min(WORLD_H, zr + 6)
            c0 = max(0, zc - 5); c1 = min(WORLD_W, zc + 6)
            if np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1]):
                if np.any(rm[r0:r1, c0:c1]):
                    return (pick_tool(), zc, zr)

        # Below zone
        zr2, zc2 = below_zone_row, wc
        if not zone_present(zr2, zc2) and zone_area_ok(zr2, zc2):
            r0 = max(0, zr2 - 5); r1 = min(WORLD_H, zr2 + 6)
            c0 = max(0, zc2 - 5); c1 = min(WORLD_W, zc2 + 6)
            if np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1]):
                if np.any(rm[r0:r1, c0:c1]):
                    return (pick_tool(), zc2, zr2)

    # --- Phase 4: Connect zones to wire via vertical wires ---
    # Wire from spine row up to above_zone_row
    for wc in sorted(wire_cols_set):
        if wc < spine_left:
            continue
        for wr in range(wire_row - 1, above_zone_row - 2, -1):
            if wr < 0:
                break
            if wm[wr, wc]:
                break
            if em[wr, wc] and not pm[wr, wc]:
                return (Tool.WIRE, wc, wr)
            elif not em[wr, wc]:
                break

    # Wire from spine row down to below_zone_row
    for wc in sorted(wire_cols_set):
        if wc < spine_left:
            continue
        for wr in range(wire_row + 1, below_zone_row + 3):
            if wr >= WORLD_H:
                break
            if wm[wr, wc]:
                break
            if em[wr, wc] and not pm[wr, wc] and not rm[wr, wc]:
                return (Tool.WIRE, wc, wr)
            elif not em[wr, wc] and not rm[wr, wc]:
                break

    # --- Phase 5: Second power plant for second cluster ---
    if obs.city_pop > 300 and int(np.sum(pm)) < 9:
        px2 = plant_cx + extent // 2
        py2 = wire_row2
        px2 = max(2, min(WORLD_W - 3, px2))
        py2 = max(2, min(WORLD_H - 3, py2))
        area_ok = True
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = py2 + dr, px2 + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if not (em[rr, rc] or pm[rr, rc]):
                        area_ok = False
        if area_ok:
            return (Tool.COALPOWER, px2, py2)

    # --- Phase 6: Second cluster wire spine ---
    if obs.city_pop >= 300:
        plant_rows2, plant_cols2 = np.where(pm)
        if len(plant_rows2) >= 9:  # second plant placed (3x3=9 tiles)
            # Find second plant (the one with higher row)
            max_pr = int(np.max(plant_rows2))
            if max_pr > plant_cy + 5:
                # Second cluster exists
                wire_cols2 = [c for c in range(WORLD_W) if wm[wire_row2, c]]
                if not wire_cols2:
                    # Connect second plant to wire row2
                    anchor_c = plant_cx + extent // 2
                    if 0 <= anchor_c < WORLD_W and em[wire_row2, anchor_c]:
                        return (Tool.WIRE, anchor_c, wire_row2)
                else:
                    max_wc2 = max(wire_cols2)
                    if max_wc2 < spine_right:
                        nc = max_wc2 + 1
                        if 0 <= nc < WORLD_W and em[wire_row2, nc]:
                            return (Tool.WIRE, nc, wire_row2)

                road_cols2 = [c for c in range(WORLD_W) if rm[road_row2, c]]
                wire_cols2_set = set(wire_cols2)
                road_cols2_set = set(road_cols2)

                if not road_cols2:
                    start_c = plant_cx + extent // 2 + 3
                    if 0 <= start_c < WORLD_W and em[road_row2, start_c]:
                        return (Tool.ROAD, start_c, road_row2)
                elif wire_cols2:
                    max_rc2 = max(road_cols2)
                    max_wc2_now = max(wire_cols2) if wire_cols2 else 0
                    if max_rc2 < min(max_wc2_now, spine_right):
                        nc = max_rc2 + 1
                        if 0 <= nc < WORLD_W and em[road_row2, nc]:
                            return (Tool.ROAD, nc, road_row2)

                # Place zones in second cluster
                for wc in sorted(wire_cols2_set):
                    road_near2 = any(abs(wc - rc) <= 2 for rc in road_cols2_set)
                    if not road_near2:
                        continue
                    for zr_try in [above_zone_row2, below_zone_row2]:
                        if not zone_present(zr_try, wc) and zone_area_ok(zr_try, wc):
                            r0 = max(0, zr_try - 5); r1 = min(WORLD_H, zr_try + 6)
                            c0 = max(0, wc - 5); c1 = min(WORLD_W, wc + 6)
                            if np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1]):
                                if np.any(rm[r0:r1, c0:c1]):
                                    return (pick_tool(), wc, zr_try)

    # --- Phase 7: Fill in more zones densely every 3 cols ---
    if len(wire_cols_on_row) > 0:
        for wc in range(spine_left, spine_right, 3):
            road_near = any(abs(wc - rc) <= 3 for rc in road_cols_set)
            wire_near = any(abs(wc - wrc) <= 1 for wrc in wire_cols_set)
            if wire_near and road_near:
                for zr_try in [above_zone_row, below_zone_row]:
                    if not zone_present(zr_try, wc) and zone_area_ok(zr_try, wc):
                        r0 = max(0, zr_try - 5); r1 = min(WORLD_H, zr_try + 6)
                        c0 = max(0, wc - 5); c1 = min(WORLD_W, wc + 6)
                        if np.any(wm[r0:r1, c0:c1]) and np.any(rm[r0:r1, c0:c1]):
                            return (pick_tool(), wc, zr_try)

    # --- Phase 8: Road extends leftward to serve zones better ---
    for rc_try in range(road_cols_set and min(road_cols_set) - 1 or spine_left - 1,
                        spine_left - 1, -1):
        if rc_try < 0:
            break
        if rm[road_row, rc_try]:
            break
        if em[road_row, rc_try] and not pm[road_row, rc_try]:
            return (Tool.ROAD, rc_try, road_row)
        break

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Phase 0: Place coal power plant if none exists
    - Phase 1: Extend wire from plant toward city center
    - Phase 2: Extend road grid
    - Phase 3: Place zones adjacent to powered+roaded areas
    Reads tile_map each step to decide what to do next.
    """

    tile_map = obs.tile_map
    step = obs.step

    # Helper: check if coords are valid
    def valid(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Get masks
    empty = empty_mask(tile_map)
    has_wire = wire_mask(tile_map)
    has_road = road_mask(tile_map)
    has_plant = plant_mask(tile_map)
    has_res = res_mask(tile_map)
    has_com = com_mask(tile_map)
    has_ind = ind_mask(tile_map)

    # Target center area
    CX, CY = 60, 50

    # --- Phase 0: Ensure we have a power plant ---
    if not np.any(has_plant):
        # Place coal power plant at a fixed spot
        return (Tool.COALPOWER, 20, 50)

    # Find plant location
    plant_ys, plant_xs = np.where(has_plant)
    if len(plant_xs) == 0:
        return (Tool.COALPOWER, 20, 50)
    # Use first plant as anchor
    px, py = int(plant_xs[0]), int(plant_ys[0])

    # --- Phase 1: Extend wire network from plant toward center ---
    # Find frontier of wire: wire tiles with empty neighbor, expand toward CX,CY
    wire_ys, wire_xs = np.where(has_wire)

    # If no wire, start adjacent to plant
    if len(wire_xs) == 0:
        # Wire starts just to the right of the plant (plant is 4x4, center placed)
        wx = px + 3
        wy = py
        if valid(wx, wy):
            return (Tool.WIRE, wx, wy)
        return (Tool.WIRE, px + 1, py)

    # Check if wire reaches near center (within 15 tiles)
    wire_center_dist = min(abs(wire_xs - CX) + abs(wire_ys - CY))

    if wire_center_dist > 10:
        # Extend wire toward center: find wire tile closest to center, extend it
        dists = np.abs(wire_xs - CX) + np.abs(wire_ys - CY)
        best_idx = np.argmin(dists)
        bwx, bwy = int(wire_xs[best_idx]), int(wire_ys[best_idx])

        # Step toward center
        dx = np.sign(CX - bwx)
        dy = np.sign(CY - bwy)

        # Try horizontal first, then vertical
        candidates = []
        if dx != 0:
            candidates.append((bwx + int(dx), bwy))
        if dy != 0:
            candidates.append((bwx, bwy + int(dy)))

        for (nx, ny) in candidates:
            if valid(nx, ny) and not has_wire[ny, nx] and not has_plant[ny, nx]:
                return (Tool.WIRE, nx, ny)

    # --- Phase 2: Build road grid around center ---
    # We want a road grid: horizontal roads at cy=44,47,50,53,56
    # and vertical roads at cx=50,55,60,65,70,75
    road_rows = list(range(41, 62, 3))  # y: 41,44,47,50,53,56,59
    road_cols = list(range(45, 80, 5))  # x: 45,50,55,60,65,70,75

    # Check for missing road segments near existing wire/road
    # Horizontal roads
    for ry in road_rows:
        for rx in range(45, 80):
            if valid(rx, ry) and not has_road[ry, rx] and not has_plant[ry, rx]:
                # Check if adjacent to existing road or wire
                adj_road_wire = False
                for dx2, dy2 in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nx2, ny2 = rx+dx2, ry+dy2
                    if valid(nx2, ny2) and (has_road[ny2, nx2] or has_wire[ny2, nx2] or has_plant[ny2, nx2]):
                        adj_road_wire = True
                        break
                if adj_road_wire:
                    return (Tool.ROAD, rx, ry)

    # Vertical roads
    for rcx in road_cols:
        for ry2 in range(41, 62):
            if valid(rcx, ry2) and not has_road[ry2, rcx] and not has_plant[ry2, rcx]:
                adj_road_wire = False
                for dx2, dy2 in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nx2, ny2 = rcx+dx2, ry2+dy2
                    if valid(nx2, ny2) and (has_road[ny2, nx2] or has_wire[ny2, nx2] or has_plant[ny2, nx2]):
                        adj_road_wire = True
                        break
                if adj_road_wire:
                    return (Tool.ROAD, rcx, ry2)

    # Start road from wire if no road exists yet near center
    if not np.any(has_road):
        # Find wire near center
        dists = np.abs(wire_xs - CX) + np.abs(wire_ys - CY)
        best_idx = np.argmin(dists)
        bwx, bwy = int(wire_xs[best_idx]), int(wire_ys[best_idx])
        # Place road adjacent
        for dx2, dy2 in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx2, ny2 = bwx+dx2, bwy+dy2
            if valid(nx2, ny2) and empty[ny2, nx2]:
                return (Tool.ROAD, nx2, ny2)

    # --- Phase 3: Place zones adjacent to road+wire coverage ---
    # Scan grid positions for zone placement (zones are 3x3, center placement)
    # Zone center must be within 2 tiles of road AND within 2 tiles of wire

    # Count zones for balance
    n_res = int(np.sum(has_res))
    n_com = int(np.sum(has_com))
    n_ind = int(np.sum(has_ind))
    total = n_res + n_com + n_ind

    # Target ratio: 50% res, 25% com, 25% ind (by zone count)
    if total == 0:
        target_tool = Tool.RESIDENTIAL
    elif n_res / max(total, 1) < 0.45:
        target_tool = Tool.RESIDENTIAL
    elif n_com / max(total, 1) < 0.25:
        target_tool = Tool.COMMERCIAL
    elif n_ind / max(total, 1) < 0.20:
        target_tool = Tool.INDUSTRIAL
    else:
        target_tool = Tool.RESIDENTIAL

    # Find a good spot: near road, near wire, empty center
    best_score = 1e9
    best_action = None

    # Sample candidate zone centers on a 3-step grid
    for zy in range(43, 60, 3):
        for zx in range(47, 78, 3):
            if not valid(zx, zy):
                continue
            # Check center and surrounding 3x3 area roughly empty
            # (auto-bulldoze is on, but we want empty for safety)
            # Check no plant in 3x3
            plant_conflict = False
            for ddy in range(-1, 2):
                for ddx in range(-1, 2):
                    nx2, ny2 = zx+ddx, zy+ddy
                    if valid(nx2, ny2) and has_plant[ny2, nx2]:
                        plant_conflict = True
            if plant_conflict:
                continue

            # Check if already a zone here
            if has_res[zy, zx] or has_com[zy, zx] or has_ind[zy, zx]:
                continue

            # Check proximity to road (within 2)
            road_near = False
            for ddy in range(-2, 3):
                for ddx in range(-2, 3):
                    nx2, ny2 = zx+ddx, zy+ddy
                    if valid(nx2, ny2) and has_road[ny2, nx2]:
                        road_near = True

            # Check proximity to wire or plant (within 3)
            wire_near = False
            for ddy in range(-3, 4):
                for ddx in range(-3, 4):
                    nx2, ny2 = zx+ddx, zy+ddy
                    if valid(nx2, ny2) and (has_wire[ny2, nx2] or has_plant[ny2, nx2]):
                        wire_near = True

            if road_near and wire_near:
                dist_center = abs(zx - CX) + abs(zy - CY)
                if dist_center < best_score:
                    best_score = dist_center
                    best_action = (target_tool, zx, zy)

    if best_action is not None:
        return best_action

    # --- Fallback: extend wire one more step toward center ---
    if len(wire_xs) > 0:
        dists = np.abs(wire_xs - CX) + np.abs(wire_ys - CY)
        best_idx = np.argmin(dists)
        bwx, bwy = int(wire_xs[best_idx]), int(wire_ys[best_idx])
        dx = int(np.sign(CX - bwx))
        dy = int(np.sign(CY - bwy))
        for (nx, ny) in [(bwx+dx, bwy), (bwx, bwy+dy)]:
            if valid(nx, ny) and not has_wire[ny, nx] and not has_plant[ny, nx]:
                return (Tool.WIRE, nx, ny)

    # Add another power plant if underpowered
    if obs.powered_zones < max(1, (n_res + n_com + n_ind) // 4):
        return (Tool.COALPOWER, 95, 50)

    # Place fire station for service
    if step % 50 == 0 and valid(62, 43):
        if empty[43, 62]:
            return (Tool.FIRESTATION, 62, 43)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy.
    Reads tile_map every step to decide next action.
    Strategy:
    - Place coal power plant at fixed anchor
    - Grow wire spine reactively from plant/existing wires
    - Build roads adjacent to wire coverage
    - Place zones adjacent to roads+wire
    - Add more plants when population warrants
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    cx, cy = 60, 50  # map center

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def safe(x, y):
        return in_bounds(x, y) and em[y, x] and not pm[y, x]

    # --- Phase 1: Place first coal power plant if none exists ---
    if not np.any(pm):
        # Place at left side near center
        px, py = cx - 20, cy
        return (Tool.COALPOWER, px, py)

    plant_ys, plant_xs = np.where(pm)
    plant_cx = int(np.mean(plant_xs))
    plant_cy = int(np.mean(plant_ys))

    # Active development x-range scales with pop
    if pop < 100:
        x_half = 15
    elif pop < 300:
        x_half = 25
    elif pop < 600:
        x_half = 38
    elif pop < 1000:
        x_half = 50
    else:
        x_half = 58

    x_min = max(2, cx - x_half)
    x_max = min(WORLD_W - 3, cx + x_half)

    # Wire spine runs along cy, roads at cy-4 and cy+4
    wire_row = cy
    road_above = cy - 4
    road_below = cy + 4

    # --- Phase 2: Grow wire spine reactively from existing wire/plant ---
    # Find wire on wire_row
    wire_on_row = np.where(wm[wire_row, :])[0]

    if len(wire_on_row) == 0:
        # Start wire adjacent to plant
        # Try rightward from plant center
        for dc in range(1, 15):
            c = plant_cx + dc
            if in_bounds(c, wire_row) and safe(c, wire_row):
                return (Tool.WIRE, c, wire_row)
        # Try at plant row
        for dc in range(1, 15):
            c = plant_cx + dc
            if in_bounds(c, plant_cy) and safe(c, plant_cy):
                return (Tool.WIRE, c, plant_cy)
        return None

    min_wc = int(wire_on_row.min())
    max_wc = int(wire_on_row.max())

    # Extend wire rightward
    if max_wc < x_max:
        nc = max_wc + 1
        if safe(nc, wire_row):
            return (Tool.WIRE, nc, wire_row)

    # Extend wire leftward toward plant
    if min_wc > x_min:
        nc = min_wc - 1
        if safe(nc, wire_row):
            return (Tool.WIRE, nc, wire_row)

    # --- Phase 3: Connect plant to wire if not connected ---
    # Check if any plant tile is adjacent to wire
    plant_connected = False
    for pr, pc in zip(plant_ys, plant_xs):
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc2 = pr+dr, pc+dc
            if in_bounds(nc2, nr) and wm[nr, nc2]:
                plant_connected = True
    if not plant_connected:
        # Bridge horizontally from plant to nearest wire on wire_row
        target_c = min_wc
        for bc in range(plant_cx+1, target_c+1):
            if in_bounds(bc, wire_row):
                if wm[wire_row, bc]:
                    break
                if safe(bc, wire_row):
                    return (Tool.WIRE, bc, wire_row)
        # Vertical bridge if plant not on wire_row
        step_r = 1 if wire_row > plant_cy else -1
        for br in range(plant_cy + step_r, wire_row + step_r, step_r):
            bc2 = plant_cx + 2
            if in_bounds(bc2, br) and safe(bc2, br) and not wm[br, bc2]:
                return (Tool.WIRE, bc2, br)

    # --- Phase 4: Build roads reactively where wire coverage exists ---
    # For each column with wire, place roads above and below
    for wc in range(x_min, x_max+1):
        if wm[wire_row, wc]:
            if in_bounds(wc, road_above) and safe(wc, road_above):
                return (Tool.ROAD, wc, road_above)
            if in_bounds(wc, road_below) and safe(wc, road_below):
                return (Tool.ROAD, wc, road_below)

    # --- Phase 5: Vertical connector roads every 6 cols ---
    for wc in range(x_min, x_max+1, 6):
        if wm[wire_row, wc] or rm[wire_row, wc]:
            for wr2 in range(road_above, road_below+1):
                if in_bounds(wc, wr2) and em[wr2, wc] and not pm[wr2, wc] and not wm[wr2, wc] and not rm[wr2, wc]:
                    return (Tool.ROAD, wc, wr2)

    # --- Compute neighbor coverage masks ---
    # nbr_road: any road within 2 tiles
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # nbr_wire: wire or plant within 3 tiles
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # --- Zone tool selection ---
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(total_zones, 1)
        if ind_count / t < 0.22:
            return Tool.INDUSTRIAL
        if com_count / t < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zy, zx):
        if zy < 1 or zy > WORLD_H - 2 or zx < 1 or zx > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr2, rc2 = zy+dr, zx+dc
                if not (0 <= rr2 < WORLD_H and 0 <= rc2 < WORLD_W):
                    return False
                if not (em[rr2, rc2] or resm[rr2, rc2] or comm[rr2, rc2] or indm[rr2, rc2]):
                    return False
        return True

    # --- Phase 6: Place zones reactively ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, :2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys_a, cxs_a = np.where(cand_mask)
    if len(cxs_a) > 0:
        # Sort by closeness to wire spine center
        dists = np.abs(cxs_a.astype(int) - cx) + np.abs(cys_a.astype(int) - wire_row) * 2
        sort_idx = np.argsort(dists)
        for k_idx in range(min(len(cxs_a), 80)):
            k = int(sort_idx[k_idx])
            zx, zy = int(cxs_a[k]), int(cys_a[k])
            if x_min <= zx <= x_max and zone_area_ok(zy, zx):
                return (pick_tool(), zx, zy)

    # --- Phase 7: Second power plant ---
    plant_count = max(1, int(np.sum(pm)) // 6)

    if pop > 150 and plant_count < 2:
        p2x = min(WORLD_W-5, cx + 22)
        p2y = wire_row
        if in_bounds(p2x, p2y) and safe(p2x, p2y):
            nearby = any(
                in_bounds(p2x+dx2, p2y+dy2) and pm[p2y+dy2, p2x+dx2]
                for dy2 in range(-7,8) for dx2 in range(-7,8)
            )
            if not nearby:
                return (Tool.COALPOWER, p2x, p2y)
        # Extend wire toward second plant
        if max_wc < p2x - 2:
            nc = max_wc + 1
            if in_bounds(nc, wire_row) and safe(nc, wire_row):
                return (Tool.WIRE, nc, wire_row)

    if pop > 500 and plant_count < 3:
        p3x = cx - 10
        p3y = wire_row + 16
        if in_bounds(p3x, p3y) and safe(p3x, p3y):
            nearby = any(
                in_bounds(p3x+dx2, p3y+dy2) and pm[p3y+dy2, p3x+dx2]
                for dy2 in range(-7,8) for dx2 in range(-7,8)
            )
            if not nearby:
                return (Tool.COALPOWER, p3x, p3y)

    # --- Phase 8: Services reactively ---
    if pop > 200:
        fx, fy = cx, cy - 10
        if in_bounds(fx, fy) and em[fy, fx] and not pm[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
    if pop > 350:
        px2, py2 = cx + 14, cy + 10
        if in_bounds(px2, py2) and em[py2, px2] and not pm[py2, px2]:
            return (Tool.POLICESTATION, px2, py2)
    if pop > 600:
        fx2, fy2 = cx - 14, cy + 10
        if in_bounds(fx2, fy2) and em[fy2, fx2] and not pm[fy2, fx2]:
            return (Tool.FIRESTATION, fx2, fy2)

    # --- Phase 9: Reactively extend roads from existing road endpoints ---
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = (step * 17) % len(road_xs_arr)
        rx_s = int(road_xs_arr[step_k])
        ry_s = int(road_ys_arr[step_k])
        for dy2, dx2 in [(0,1),(0,-1),(1,0),(-1,0)]:
            nx2, ny2 = rx_s+dx2, ry_s+dy2
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                if nbr_wire[ny2, nx2] and x_min <= nx2 <= x_max:
                    return (Tool.ROAD, nx2, ny2)

    # --- Phase 10: Second wire row for more zone coverage ---
    if pop > 300:
        wire2_row = cy + 12
        road3 = cy + 16
        for wc in range(x_min, x_max+1):
            if wm[wire_row, wc] and in_bounds(wc, wire2_row) and safe(wc, wire2_row):
                return (Tool.WIRE, wc, wire2_row)
        # Connect vertically
        for wc in range(x_min, x_max+1, 8):
            if wm[wire_row, wc]:
                for wr3 in range(wire_row+1, wire2_row+1):
                    if in_bounds(wc, wr3) and safe(wc, wr3) and not wm[wr3, wc]:
                        return (Tool.WIRE, wc, wr3)
        # Road along second wire row
        for wc in range(x_min, x_max+1):
            if in_bounds(wc, wire2_row) and wm[wire2_row, wc]:
                if in_bounds(wc, road3) and safe(wc, road3):
                    return (Tool.ROAD, wc, road3)

    # --- Phase 11: Reactively extend wire from any existing wire ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k = (step * 11) % len(wire_xs_arr)
        wx_s = int(wire_xs_arr[step_k])
        wy_s = int(wire_ys_arr[step_k])
        for dx2, dy2 in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx2, ny2 = wx_s+dx2, wy_s+dy2
            if in_bounds(nx2, ny2) and safe(nx2, ny2):
                if x_min <= nx2 <= x_max:
                    return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Improved policy: 
    - Horizontal wire spine instead of vertical
    - Two road rows (above and below wire)
    - Zones placed in rows adjacent to roads
    - Mixed zone types with better ratios
    - Second coal plant when population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    if 'plan' not in state:
        # Fix a horizontal layout centered at (50, 50)
        # Plant at (10, 50), wire spine runs horizontally at row 50
        # Roads at row 47 and row 53
        # Zones at rows 44 and 56 (centers)
        state['plan'] = {
            'plant_x': 10, 'plant_y': 50,
            'wire_row': 50,
            'road_top': 47,
            'road_bot': 53,
            'zone_top': 44,
            'zone_bot': 56,
            'wire_xstart': 13,
            'wire_xend': 90,
            'road_xstart': 13,
            'road_xend': 90,
        }
        state['phase'] = 0
        state['plant2'] = False

    p = state['plan']
    px, py = p['plant_x'], p['plant_y']
    wr = p['wire_row']
    rt = p['road_top']
    rb = p['road_bot']
    zt = p['zone_top']
    zb = p['zone_bot']
    wxs = p['wire_xstart']
    wxe = p['wire_xend']
    rxs = p['road_xstart']
    rxe = p['road_xend']

    # Phase 1: Place coal plant
    if not np.any(pm):
        return (Tool.COALPOWER, px, py)

    # Phase 2: Build horizontal wire spine from plant outward
    # Wire at row wr, from wxs to wxe
    for wx in range(wxs, wxe + 1):
        if not wm[wr, wx] and (em[wr, wx] or True):
            return (Tool.WIRE, wx, wr)

    # Phase 3: Build top road row
    for rx in range(rxs, rxe + 1):
        if not rm[rt, rx] and em[rt, rx]:
            return (Tool.ROAD, rx, rt)

    # Phase 4: Build bottom road row
    for rx in range(rxs, rxe + 1):
        if not rm[rb, rx] and em[rb, rx]:
            return (Tool.ROAD, rx, rb)

    # Phase 5: Connect wire to roads with vertical wire segments at intervals
    # Place vertical wires every 6 columns to connect wire spine to roads
    for vx in range(wxs, wxe + 1, 6):
        # Connect wire row to top road
        for vy in range(min(wr, rt), max(wr, rt) + 1):
            if not wm[vy, vx] and not rm[vy, vx]:
                if em[vy, vx]:
                    return (Tool.WIRE, vx, vy)
        # Connect wire row to bottom road
        for vy in range(min(wr, rb), max(wr, rb) + 1):
            if not wm[vy, vx] and not rm[vy, vx]:
                if em[vy, vx]:
                    return (Tool.WIRE, vx, vy)

    # Count existing zones for mix calculation
    res_count = max(1, int(np.sum(res_m)) // 9)
    com_count = max(1, int(np.sum(com_m)) // 9)
    ind_count = max(1, int(np.sum(ind_m)) // 9)

    def pick_zone(col_idx):
        # Cycle through: RES RES COM RES RES IND
        pattern = [Tool.RESIDENTIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL,
                   Tool.RESIDENTIAL, Tool.RESIDENTIAL, Tool.INDUSTRIAL]
        return pattern[col_idx % 6]

    def zone_clear(zrow, zcol):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                r2, c2 = zrow + dr, zcol + dc
                if r2 < 0 or r2 >= WORLD_H or c2 < 0 or c2 >= WORLD_W:
                    return False
                if not em[r2, c2]:
                    return False
        return True

    all_zone_m = res_m | com_m | ind_m

    def zone_occupied(zrow, zcol):
        r0 = max(0, zrow - 1)
        r1 = min(WORLD_H, zrow + 2)
        c0 = max(0, zcol - 1)
        c1 = min(WORLD_W, zcol + 2)
        return np.any(all_zone_m[r0:r1, c0:c1])

    # Phase 6: Place zones in top row (row zt = road_top - 3)
    # Zone centers at zt, spaced every 4 columns starting at rxs+1
    col_idx = 0
    for zx in range(rxs + 1, rxe, 4):
        if 2 <= zx <= WORLD_W - 3 and 2 <= zt <= WORLD_H - 3:
            if not zone_occupied(zt, zx) and zone_clear(zt, zx):
                return (pick_zone(col_idx), zx, zt)
        col_idx += 1

    # Phase 7: Place zones in bottom row (row zb = road_bot + 3)
    col_idx = 0
    for zx in range(rxs + 1, rxe, 4):
        if 2 <= zx <= WORLD_W - 3 and 2 <= zb <= WORLD_H - 3:
            if not zone_occupied(zb, zx) and zone_clear(zb, zx):
                return (pick_zone(col_idx + 1), zx, zb)
        col_idx += 1

    # Phase 8: Second cluster when population grows
    if obs.city_pop > 150 and not state['plant2']:
        # Second plant above first cluster
        px2, py2 = 10, 20
        if not any(pm[py2+dr, px2+dc] for dr in [-1,0,1] for dc in [-1,0,1]):
            if all(em[py2+dr, px2+dc] for dr in [-1,0,1] for dc in [-1,0,1]
                   if 0 <= py2+dr < WORLD_H and 0 <= px2+dc < WORLD_W):
                state['plant2'] = True
                return (Tool.COALPOWER, px2, py2)
        # Wire from plant2 to main wire spine
        wr2 = 20
        rt2 = 17
        rb2 = 23
        zt2 = 14
        zb2 = 26
        # Wire row 20
        for wx in range(13, 91):
            if not wm[wr2, wx] and em[wr2, wx]:
                return (Tool.WIRE, wx, wr2)
        for rx in range(13, 91):
            if not rm[rt2, rx] and em[rt2, rx]:
                return (Tool.ROAD, rx, rt2)
        for rx in range(13, 91):
            if not rm[rb2, rx] and em[rb2, rx]:
                return (Tool.ROAD, rx, rb2)
        # Vertical connectors for cluster 2
        for vx in range(13, 91, 6):
            for vy in range(min(wr2, rt2), max(wr2, rt2) + 1):
                if not wm[vy, vx] and not rm[vy, vx] and em[vy, vx]:
                    return (Tool.WIRE, vx, vy)
            for vy in range(min(wr2, rb2), max(wr2, rb2) + 1):
                if not wm[vy, vx] and not rm[vy, vx] and em[vy, vx]:
                    return (Tool.WIRE, vx, vy)
        col_idx = 0
        for zx in range(14, 90, 4):
            if 2 <= zx <= WORLD_W - 3 and 2 <= zt2 <= WORLD_H - 3:
                if not zone_occupied(zt2, zx) and zone_clear(zt2, zx):
                    return (pick_zone(col_idx), zx, zt2)
            col_idx += 1
        col_idx = 0
        for zx in range(14, 90, 4):
            if 2 <= zx <= WORLD_W - 3 and 2 <= zb2 <= WORLD_H - 3:
                if not zone_occupied(zb2, zx) and zone_clear(zb2, zx):
                    return (pick_zone(col_idx + 2), zx, zb2)
            col_idx += 1

    # Phase 9: Connect two clusters with vertical wire if both exist
    if state['plant2'] and obs.city_pop > 300:
        # Vertical wire at x=10 from y=23 to y=47
        for vy in range(23, 47):
            if not wm[vy, 10] and em[vy, 10]:
                return (Tool.WIRE, 10, vy)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map each step and reacts.
    Strategy:
    - Coal plant near center
    - Vertical wire spine from plant, extended each step
    - Parallel road column
    - Zones placed adjacent to wire+road coverage
    - Second cluster expands rightward when pop grows
    - All decisions based on current observed map
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    pop = obs.city_pop

    # Fixed layout anchors
    PLANT_X, PLANT_Y = 54, 50
    WIRE_COL = 58
    ROAD_COL = 61
    LEFT_ZONE_COL = 55
    RIGHT_ZONE_COL = 65

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Dynamic vertical span
    extra = min(35, pop // 20)
    tmin = max(3, PLANT_Y - 12 - extra)
    tmax = min(WORLD_H - 4, PLANT_Y + 12 + extra)

    # --- Phase 1: Place coal plant if missing ---
    if not np.any(pm):
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    # Gather wire/road info for primary spine
    wire_on_col = sorted(r for r in range(WORLD_H) if wm[r, WIRE_COL])
    road_on_col = sorted(r for r in range(WORLD_H) if rm[r, ROAD_COL])
    road_set = set(road_on_col)

    # --- Phase 2: Extend vertical wire spine ---
    if not wire_on_col:
        # Start wire adjacent to plant
        for try_r in [PLANT_Y, PLANT_Y - 1, PLANT_Y + 1, PLANT_Y + 2]:
            if in_bounds(WIRE_COL, try_r) and em[try_r, WIRE_COL]:
                return (Tool.WIRE, WIRE_COL, try_r)
        return (Tool.WIRE, WIRE_COL, PLANT_Y)
    else:
        min_wr = min(wire_on_col)
        max_wr = max(wire_on_col)
        # Extend downward
        if max_wr < tmax:
            nr = max_wr + 1
            if in_bounds(WIRE_COL, nr) and em[nr, WIRE_COL]:
                return (Tool.WIRE, WIRE_COL, nr)
        # Extend upward
        if min_wr > tmin:
            nr = min_wr - 1
            if in_bounds(WIRE_COL, nr) and em[nr, WIRE_COL]:
                return (Tool.WIRE, WIRE_COL, nr)

    if not wire_on_col:
        return None

    wire_set = set(wire_on_col)

    # --- Phase 3: Build road column matching wire coverage ---
    for wr in wire_on_col:
        if wr not in road_set and in_bounds(ROAD_COL, wr) and em[wr, ROAD_COL]:
            return (Tool.ROAD, ROAD_COL, wr)

    # Zone helpers
    all_res = list(zip(*np.where(res_m))) if np.any(res_m) else []
    all_com = list(zip(*np.where(com_m))) if np.any(com_m) else []
    all_ind = list(zip(*np.where(ind_m))) if np.any(ind_m) else []
    all_zones_set = set(all_res) | set(all_com) | set(all_ind)
    rc = len(all_res)
    cc = len(all_com)
    ic = len(all_ind)

    def zone_area_free(cr, ccol):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr2, rc2 = cr + dr, ccol + dc
                if not (0 <= rr2 < WORLD_H and 0 <= rc2 < WORLD_W):
                    return False
                if not em[rr2, rc2]:
                    return False
        return True

    def no_zone_near(zr, zc, dist=2):
        r0 = max(0, zr - dist); r1 = min(WORLD_H, zr + dist + 1)
        c0 = max(0, zc - dist); c1 = min(WORLD_W, zc + dist + 1)
        return not (np.any(res_m[r0:r1, c0:c1]) or np.any(com_m[r0:r1, c0:c1]) or np.any(ind_m[r0:r1, c0:c1]))

    def pick_zone(r, c, i):
        total = r + c + i
        if total == 0 or r == 0:
            return Tool.RESIDENTIAL
        if i * 4 < r:
            return Tool.INDUSTRIAL
        if c * 3 < r:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Check if a zone location has wire+road nearby
    def has_power_and_road_near(zr, zc, wr=5, rr=5):
        r0w = max(0, zr - wr); r1w = min(WORLD_H, zr + wr + 1)
        c0w = max(0, zc - wr); c1w = min(WORLD_W, zc + wr + 1)
        pw = np.any(wm[r0w:r1w, c0w:c1w]) or np.any(pm[r0w:r1w, c0w:c1w])
        r0r = max(0, zr - rr); r1r = min(WORLD_H, zr + rr + 1)
        c0r = max(0, zc - rr); c1r = min(WORLD_W, zc + rr + 1)
        pr = np.any(rm[r0r:r1r, c0r:c1r])
        return pw and pr

    # --- Phase 4: Place zones adjacent to primary spine ---
    for zr in sorted(wire_on_col):
        road_near = any(abs(zr - rr2) <= 2 for rr2 in road_set)
        if not road_near:
            continue
        for zc in [LEFT_ZONE_COL, RIGHT_ZONE_COL]:
            if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                if no_zone_near(zr, zc) and zone_area_free(zr, zc):
                    return (pick_zone(rc, cc, ic), zc, zr)

    # --- Phase 5: Lateral wires to left zones ---
    for wr2 in wire_on_col:
        for wc in range(WIRE_COL - 1, max(LEFT_ZONE_COL - 3, 0), -1):
            if not in_bounds(wc, wr2):
                break
            if wm[wr2, wc]:
                break
            if em[wr2, wc]:
                return (Tool.WIRE, wc, wr2)
            else:
                break

    # --- Phase 6: Lateral roads to right zones ---
    for wr2 in wire_on_col:
        for rc2 in range(ROAD_COL + 1, min(RIGHT_ZONE_COL + 3, WORLD_W)):
            if not in_bounds(rc2, wr2):
                break
            if rm[wr2, rc2]:
                break
            if em[wr2, rc2]:
                return (Tool.ROAD, rc2, wr2)
            else:
                break

    # --- Phase 7: Second cluster (right) when pop >= 100 ---
    if pop >= 100:
        WIRE_COL2 = 71
        ROAD_COL2 = 74
        LZ2 = 68
        RZ2 = 77

        wire_on_col2 = sorted(r for r in range(WORLD_H) if wm[r, WIRE_COL2])
        road_on_col2 = sorted(r for r in range(WORLD_H) if rm[r, ROAD_COL2])
        road_set2 = set(road_on_col2)

        if not wire_on_col2:
            # Bridge from primary wire spine at PLANT_Y
            for wc in range(WIRE_COL + 1, WIRE_COL2 + 1):
                if in_bounds(wc, PLANT_Y) and em[PLANT_Y, wc]:
                    return (Tool.WIRE, wc, PLANT_Y)
        else:
            min_wr2 = min(wire_on_col2)
            max_wr2 = max(wire_on_col2)
            if max_wr2 < tmax:
                nr = max_wr2 + 1
                if in_bounds(WIRE_COL2, nr) and em[nr, WIRE_COL2]:
                    return (Tool.WIRE, WIRE_COL2, nr)
            if min_wr2 > tmin:
                nr = min_wr2 - 1
                if in_bounds(WIRE_COL2, nr) and em[nr, WIRE_COL2]:
                    return (Tool.WIRE, WIRE_COL2, nr)

            for wr2 in wire_on_col2:
                if wr2 not in road_set2 and in_bounds(ROAD_COL2, wr2) and em[wr2, ROAD_COL2]:
                    return (Tool.ROAD, ROAD_COL2, wr2)

            for zr in sorted(wire_on_col2):
                road_near2 = any(abs(zr - rr2) <= 2 for rr2 in road_set2)
                if not road_near2:
                    continue
                for zc in [LZ2, RZ2]:
                    if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                        if no_zone_near(zr, zc) and zone_area_free(zr, zc):
                            return (pick_zone(rc, cc, ic), zc, zr)

            for wr2 in wire_on_col2:
                for wc in range(WIRE_COL2 - 1, max(LZ2 - 3, 0), -1):
                    if not in_bounds(wc, wr2): break
                    if wm[wr2, wc]: break
                    if em[wr2, wc]:
                        return (Tool.WIRE, wc, wr2)
                    else: break

            for wr2 in wire_on_col2:
                for rc2 in range(ROAD_COL2 + 1, min(RZ2 + 3, WORLD_W)):
                    if not in_bounds(rc2, wr2): break
                    if rm[wr2, rc2]: break
                    if em[wr2, rc2]:
                        return (Tool.ROAD, rc2, wr2)
                    else: break

    # --- Phase 8: Third cluster (left) when pop >= 300 ---
    if pop >= 300:
        WIRE_COL3 = 47
        ROAD_COL3 = 44
        LZ3 = 41
        RZ3 = 50

        wire_on_col3 = sorted(r for r in range(WORLD_H) if wm[r, WIRE_COL3])
        road_on_col3 = sorted(r for r in range(WORLD_H) if rm[r, ROAD_COL3])
        road_set3 = set(road_on_col3)

        if not wire_on_col3:
            for wc in range(WIRE_COL - 1, WIRE_COL3 - 1, -1):
                if in_bounds(wc, PLANT_Y) and em[PLANT_Y, wc]:
                    return (Tool.WIRE, wc, PLANT_Y)
        else:
            min_wr3 = min(wire_on_col3)
            max_wr3 = max(wire_on_col3)
            if max_wr3 < tmax:
                nr = max_wr3 + 1
                if in_bounds(WIRE_COL3, nr) and em[nr, WIRE_COL3]:
                    return (Tool.WIRE, WIRE_COL3, nr)
            if min_wr3 > tmin:
                nr = min_wr3 - 1
                if in_bounds(WIRE_COL3, nr) and em[nr, WIRE_COL3]:
                    return (Tool.WIRE, WIRE_COL3, nr)

            for wr3 in wire_on_col3:
                if wr3 not in road_set3 and in_bounds(ROAD_COL3, wr3) and em[wr3, ROAD_COL3]:
                    return (Tool.ROAD, ROAD_COL3, wr3)

            for zr in sorted(wire_on_col3):
                road_near3 = any(abs(zr - rr3) <= 2 for rr3 in road_set3)
                if not road_near3:
                    continue
                for zc in [LZ3, RZ3]:
                    if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                        if no_zone_near(zr, zc) and zone_area_free(zr, zc):
                            return (pick_zone(rc, cc, ic), zc, zr)

            for wr3 in wire_on_col3:
                for wc in range(WIRE_COL3 - 1, max(LZ3 - 3, 0), -1):
                    if not in_bounds(wc, wr3): break
                    if wm[wr3, wc]: break
                    if em[wr3, wc]:
                        return (Tool.WIRE, wc, wr3)
                    else: break

            for wr3 in wire_on_col3:
                for rc3 in range(ROAD_COL3 + 1, min(RZ3 + 3, WORLD_W)):
                    if not in_bounds(rc3, wr3): break
                    if rm[wr3, rc3]: break
                    if em[wr3, rc3]:
                        return (Tool.ROAD, rc3, wr3)
                    else: break

    # --- Phase 9: Second power plant when pop > 400 ---
    if pop > 400:
        plant_rows_arr, plant_cols_arr = np.where(pm)
        if len(plant_rows_arr) < 9:  # roughly 1 plant = ~9 tiles
            p2x, p2y = 80, PLANT_Y
            if in_bounds(p2x, p2y):
                r0p = max(0, p2y - 5); r1p = min(WORLD_H, p2y + 6)
                c0p = max(0, p2x - 5); c1p = min(WORLD_W, p2x + 6)
                if not np.any(pm[r0p:r1p, c0p:c1p]) and em[p2y, p2x]:
                    return (Tool.COALPOWER, p2x, p2y)

    # --- Phase 10: Services ---
    if pop > 300:
        fx, fy = WIRE_COL, PLANT_Y - 16
        if in_bounds(fx, fy) and zone_area_free(fy, fx):
            return (Tool.FIRESTATION, fx, fy)
    if pop > 500:
        px2, py2 = ROAD_COL, PLANT_Y + 18
        if in_bounds(px2, py2) and zone_area_free(py2, px2):
            return (Tool.POLICESTATION, px2, py2)

    # --- Phase 11: Fill any candidate spots with power+road nearby ---
    # Build neighbor masks for road (radius 2) and wire (radius 3)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            r_src0 = max(0, -dy); r_src1 = min(WORLD_H, WORLD_H - dy)
            c_src0 = max(0, -dx); c_src1 = min(WORLD_W, WORLD_W - dx)
            r_dst0 = max(0, dy); r_dst1 = min(WORLD_H, WORLD_H + dy)
            c_dst0 = max(0, dx); c_dst1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r_dst0:r_dst1, c_dst0:c_dst1] |= rm[r_src0:r_src1, c_src0:c_src1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            r_src0 = max(0, -dy); r_src1 = min(WORLD_H, WORLD_H - dy)
            c_src0 = max(0, -dx); c_src1 = min(WORLD_W, WORLD_W - dx)
            r_dst0 = max(0, dy); r_dst1 = min(WORLD_H, WORLD_H + dy)
            c_dst0 = max(0, dx); c_dst1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r_dst0:r_dst1, c_dst0:c_dst1] |= wm[r_src0:r_src1, c_src0:c_src1]
            nbr_wire[r_dst0:r_dst1, c_dst0:c_dst1] |= pm[r_src0:r_src1, c_src0:c_src1]

    cand = em & nbr_road & nbr_wire
    cand[:2, :] = False; cand[WORLD_H - 2:, :] = False
    cand[:, :2] = False; cand[:, WORLD_W - 2:] = False

    cys_a, cxs_a = np.where(cand)
    if len(cxs_a) > 0:
        dists = (np.abs(cxs_a.astype(int) - PLANT_X) +
                 np.abs(cys_a.astype(int) - PLANT_Y))
        sort_idx = np.argsort(dists)
        for k in sort_idx[:60]:
            zx, zy = int(cxs_a[k]), int(cys_a[k])
            if zone_area_free(zy, zx) and no_zone_near(zy, zx):
                return (pick_zone(rc, cc, ic), zx, zy)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy - improved version.
    Key changes from parent:
    - More aggressive initial zone placement
    - Better power/road layout: road directly adjacent to wire for easier zone access
    - Multiple wire columns to power wider area
    - Prioritize placing zones systematically in a grid pattern
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    pop = obs.city_pop

    def pick_tool():
        t = max(total_zones, 1)
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    zone_tiles = resm | comm | indm

    # ---- Phase 1: Place coal plant if none ----
    if not np.any(pm):
        return (Tool.COALPOWER, 55, 50)

    plant_ys, plant_xs = np.where(pm)
    px = int(np.median(plant_xs))
    py = int(np.median(plant_ys))

    # Layout: plant at (55,50), road col at 58, wire col at 61, zones at 63-66 and 55-52
    # Horizontal layout: [zones][road][wire][plant][wire][road][zones]
    # plant center ~(55,50)
    # Right side: wire at 58, road at 60, zones at 62
    # Left side: wire at 52, road at 50, zones at 48

    wire_col_r = px + 3
    wire_col_r = max(3, min(WORLD_W - 4, wire_col_r))
    road_col_r = wire_col_r + 2
    road_col_r = max(3, min(WORLD_W - 4, road_col_r))

    wire_col_l = px - 3
    wire_col_l = max(3, min(WORLD_W - 4, wire_col_l))
    road_col_l = wire_col_l - 2
    road_col_l = max(3, min(WORLD_W - 4, road_col_l))

    # Vertical extent based on pop
    if pop < 100:
        spine_half = 12
    elif pop < 300:
        spine_half = 20
    elif pop < 600:
        spine_half = 30
    else:
        spine_half = 40

    row_min = max(2, py - spine_half)
    row_max = min(WORLD_H - 3, py + spine_half)

    # ---- Phase 2: Build wire spine on right side ----
    wire_rows_r = [r for r in range(WORLD_H) if wm[r, wire_col_r]]

    if not wire_rows_r:
        for dy in range(-3, 4):
            nr = py + dy
            if in_bounds(wire_col_r, nr) and not pm[nr, wire_col_r]:
                return (Tool.WIRE, wire_col_r, nr)
        return (Tool.WIRE, wire_col_r, py)

    min_wr_r = min(wire_rows_r)
    max_wr_r = max(wire_rows_r)

    # Extend right wire spine
    if max_wr_r < row_max:
        nr = max_wr_r + 1
        if in_bounds(wire_col_r, nr) and not pm[nr, wire_col_r]:
            return (Tool.WIRE, wire_col_r, nr)
    if min_wr_r > row_min:
        nr = min_wr_r - 1
        if in_bounds(wire_col_r, nr) and not pm[nr, wire_col_r]:
            return (Tool.WIRE, wire_col_r, nr)

    # ---- Phase 3: Build wire spine on left side ----
    wire_rows_l = [r for r in range(WORLD_H) if wm[r, wire_col_l]]

    if not wire_rows_l:
        for dy in range(-3, 4):
            nr = py + dy
            if in_bounds(wire_col_l, nr) and not pm[nr, wire_col_l]:
                return (Tool.WIRE, wire_col_l, nr)
        return (Tool.WIRE, wire_col_l, py)

    min_wr_l = min(wire_rows_l)
    max_wr_l = max(wire_rows_l)

    # Extend left wire spine
    if max_wr_l < row_max:
        nr = max_wr_l + 1
        if in_bounds(wire_col_l, nr) and not pm[nr, wire_col_l]:
            return (Tool.WIRE, wire_col_l, nr)
    if min_wr_l > row_min:
        nr = min_wr_l - 1
        if in_bounds(wire_col_l, nr) and not pm[nr, wire_col_l]:
            return (Tool.WIRE, wire_col_l, nr)

    # ---- Phase 4: Fill road columns ----
    # Road on right side
    for wr in range(row_min, row_max + 1):
        if wm[wr, wire_col_r]:
            if in_bounds(road_col_r, wr) and em[wr, road_col_r]:
                return (Tool.ROAD, road_col_r, wr)
    # Road on left side
    for wr in range(row_min, row_max + 1):
        if wm[wr, wire_col_l]:
            if in_bounds(road_col_l, wr) and em[wr, road_col_l]:
                return (Tool.ROAD, road_col_l, wr)

    # ---- Build proximity masks ----
    def expand_mask(base, radius=2):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        ys, xs = np.where(base)
        for i in range(len(xs)):
            r, c = ys[i], xs[i]
            r0 = max(0, r - radius); r1 = min(WORLD_H, r + radius + 1)
            c0 = max(0, c - radius); c1 = min(WORLD_W, c + radius + 1)
            result[r0:r1, c0:c1] = True
        return result

    nbr_road = expand_mask(rm, 2)
    nbr_wire = expand_mask(wm | pm, 2)

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and not zone_tiles[nr, nc]:
                    return False
        return True

    # ---- Phase 5: Place zones with good coverage ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Sort by: nearest to road+wire overlap first
        road_wire_overlap = nbr_road & nbr_wire
        # Score: distance to both wire columns
        dist_r = np.abs(cxs - wire_col_r)
        dist_l = np.abs(cxs - wire_col_l)
        dist_min = np.minimum(dist_r, dist_l)
        order = np.argsort(dist_min)
        step_off = int(obs.step * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 80:
                break

    # ---- Phase 6: Second coal plant when needed ----
    num_plant_tiles = int(np.sum(pm))
    if pop > 400 and num_plant_tiles < 18:
        p2x = px + 22
        p2y = py
        p2x = max(3, min(WORLD_W - 4, p2x))
        p2y = max(3, min(WORLD_H - 4, p2y))
        area_ok = True
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = p2y + dr, p2x + dc
                if not in_bounds(rc, rr) or (not em[rr, rc] and not pm[rr, rc]):
                    area_ok = False
                    break
        if area_ok:
            return (Tool.COALPOWER, p2x, p2y)
        # Bridge wire to second plant
        bridge_row = py
        for wc in range(wire_col_r + 1, p2x):
            if in_bounds(wc, bridge_row) and em[bridge_row, wc]:
                return (Tool.WIRE, wc, bridge_row)

    # ---- Phase 7: Services ----
    if pop > 150:
        fsx, fsy = px + 8, py - 12
        fsx = max(1, min(WORLD_W - 2, fsx))
        fsy = max(1, min(WORLD_H - 2, fsy))
        if in_bounds(fsx, fsy) and em[fsy, fsx]:
            return (Tool.FIRESTATION, fsx, fsy)
    if pop > 200:
        psx, psy = px - 8, py + 12
        psx = max(1, min(WORLD_W - 2, psx))
        psy = max(1, min(WORLD_H - 2, psy))
        if in_bounds(psx, psy) and em[psy, psx]:
            return (Tool.POLICESTATION, psx, psy)

    # ---- Phase 8: Extend roads from existing roads toward wire ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 40)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx]:
                    if nbr_wire[ny, nx]:
                        return (Tool.ROAD, nx, ny)

    # ---- Phase 9: Extend wire toward uncovered zones ----
    uncov_zones = zone_tiles & ~nbr_wire
    if np.any(uncov_zones):
        uz_ys, uz_xs = np.where(uncov_zones)
        wire_ys_arr, wire_xs_arr = np.where(wm)
        if len(wire_xs_arr) > 0:
            k = int(obs.step * 7) % len(uz_xs)
            ux, uy = int(uz_xs[k]), int(uz_ys[k])
            dists2 = np.abs(wire_xs_arr - ux) + np.abs(wire_ys_arr - uy)
            best = np.argmin(dists2)
            wx2, wy2 = int(wire_xs_arr[best]), int(wire_ys_arr[best])
            dx2 = int(np.sign(ux - wx2))
            dy2 = int(np.sign(uy - wy2))
            if dx2 != 0:
                nx2, ny2 = wx2 + dx2, wy2
            else:
                nx2, ny2 = wx2, wy2 + dy2
            if in_bounds(nx2, ny2) and not pm[ny2, nx2]:
                return (Tool.WIRE, nx2, ny2)

    # ---- Phase 10: Extend wire laterally to expand coverage ----
    # Try placing wire adjacent to existing wire toward empty areas
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 20)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx3, wy3 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx3 + dx3, wy3 + dy3
                if in_bounds(nx3, ny3) and em[ny3, nx3] and not pm[ny3, nx3]:
                    return (Tool.WIRE, nx3, ny3)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder.
    Reads the current map each step and reacts to what's actually there.

    Key improvements over parent:
    - Build a denser road grid first (more road connectivity)
    - Place wires along multiple corridors, not just vertical spine
    - Smarter zone placement that checks actual adjacency
    - Better zone density by expanding in multiple directions
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Use a offset from center to avoid edge issues
    cx, cy = 60, 48

    # ---- Phase 1: Ensure coal plant exists ----
    plant_ys, plant_xs = np.where(pm)
    has_plant = len(plant_xs) > 0
    if not has_plant:
        return (Tool.COALPOWER, cx, cy)

    # Get plant center for reference
    px, py = int(plant_xs[0]), int(plant_ys[0])

    power_src = pm | wm

    # ---- Count existing infrastructure ----
    wire_count = int(np.sum(wm))
    road_count = int(np.sum(rm))
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # ---- Find wire extension: grow from existing power ----
    def find_wire_extension():
        # Multiple wire corridors radiating from plant
        # Horizontal: left and right from plant
        # Vertical: up and down from plant
        targets = []

        # Horizontal wire corridor at py
        for dx in range(-20, 21):
            targets.append((px + dx, py))
        # Vertical wire corridor at px  
        for dy in range(-20, 21):
            targets.append((px, py + dy))
        # Diagonal helpers
        for d in range(-15, 16):
            targets.append((px + d, py + 5))
            targets.append((px + d, py - 5))
            targets.append((px + 8, py + d))
            targets.append((px - 8, py + d))

        for (wx, wy) in targets:
            if not in_bounds(wx, wy):
                continue
            if bool(wm[wy, wx]) or bool(pm[wy, wx]):
                continue
            if not bool(em[wy, wx]):
                continue
            # Check adjacency to existing power
            for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx2, ny2 = wx+ddx, wy+ddy
                if in_bounds(nx2, ny2) and bool(power_src[ny2, nx2]):
                    return (Tool.WIRE, wx, wy)
        return None

    # ---- Find road extension: grow from existing roads ----
    def find_road_extension():
        # Create a richer road grid: parallel roads every 4 tiles
        targets = []

        # Horizontal roads at multiple y offsets from plant
        for y_off in [-8, -4, 0, 4, 8, 12, -12]:
            ry = py + y_off
            for dx in range(-16, 17):
                targets.append((px + dx, ry))

        # Vertical roads flanking wire corridors
        for x_off in [-9, -5, -1, 1, 5, 9]:
            rx2 = px + x_off
            for dy in range(-14, 15):
                targets.append((rx2, py + dy))

        for (rx, ry) in targets:
            if not in_bounds(rx, ry):
                continue
            if bool(rm[ry, rx]):
                continue
            if bool(pm[ry, rx]) or bool(wm[ry, rx]):
                continue
            if not bool(em[ry, rx]):
                continue
            # Must be adjacent to existing road OR adjacent to plant (seed road)
            for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx2, ny2 = rx+ddx, ry+ddy
                if in_bounds(nx2, ny2) and bool(rm[ny2, nx2]):
                    return (Tool.ROAD, rx, ry)
            for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1),(2,0),(-2,0),(0,2),(0,-2)]:
                nx2, ny2 = rx+ddx, ry+ddy
                if in_bounds(nx2, ny2) and bool(pm[ny2, nx2]):
                    return (Tool.ROAD, rx, ry)
        return None

    def pick_tool():
        if com_count / total_zones < 0.20:
            return Tool.COMMERCIAL
        if ind_count / total_zones < 0.22:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # ---- Zone placement: near both roads and power ----
    def find_zone_placement():
        # Compute neighbor masks for road and power proximity
        nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1,0),(1,0),(0,-1),(0,1),(-2,0),(2,0),(0,-2),(0,2)]:
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H+dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W+dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

        nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-6, 7):
            for dx in range(-6, 7):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
                r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H+dy)
                c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W+dx)
                nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

        zone_mask = resm | comm | indm
        cand = em & nbr_road & nbr_power
        # Keep away from edges (need 3x3 footprint)
        cand[:2, :] = False
        cand[WORLD_H-2:, :] = False
        cand[:, :2] = False
        cand[:, WORLD_W-2:] = False

        cys, cxs = np.where(cand)
        if len(cxs) == 0:
            return None

        # Reactive selection: use current map checksum for determinism
        # that changes as city grows
        key = int((obs.tile_map.sum() + obs.city_pop * 7 + obs.step * 3) % max(len(cxs), 1))
        tool = pick_tool()

        for offset in range(min(len(cxs), 80)):
            k = (key + offset * 11) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            # Check 3x3 clearance: only empty or existing zones
            ok = True
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    ny2, nx2 = zy+dr, zx+dc
                    if not in_bounds(nx2, ny2):
                        ok = False; break
                    cell_ok = bool(em[ny2, nx2]) or bool(zone_mask[ny2, nx2])
                    if not cell_ok:
                        ok = False; break
                if not ok:
                    break
            if ok:
                return (tool, zx, zy)
        return None

    # ---- Compute wire spine coverage ----
    spine_wire = sum(1 for dy in range(-20, 21)
                    if in_bounds(px, py+dy) and bool(wm[py+dy, px]))
    horiz_wire = sum(1 for dx in range(-20, 21)
                    if in_bounds(px+dx, py) and bool(wm[py, px+dx]))
    total_wire_spine = spine_wire + horiz_wire

    wire_action = find_wire_extension()
    road_action = find_road_extension()

    # ---- Priority logic ----
    # 1. Build wire cross first (enough to power a zone cluster)
    if total_wire_spine < 15 and wire_action is not None:
        return wire_action

    # 2. Seed the road network
    if road_count < 8 and road_action is not None:
        return road_action

    # 3. Interleave: more roads relative to wires for better zone coverage
    step_mod = obs.step % 8

    if step_mod in (0, 1) and wire_action is not None:
        return wire_action

    if step_mod in (2, 3, 4) and road_action is not None:
        return road_action

    # 4. Try zone placement
    zone_action = find_zone_placement()
    if zone_action is not None:
        return zone_action

    # 5. Fallbacks
    if wire_action is not None:
        return wire_action
    if road_action is not None:
        return road_action

    # 6. Services based on population
    if obs.city_pop > 400:
        for fx, fy in [(px+10, py-10), (px-10, py+10), (px+10, py+10)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 700:
        for fx, fy in [(px-10, py-10), (px+15, py), (px-15, py)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.POLICESTATION, fx, fy)

    # 7. Last resort: extend road from any existing road tile
    rys, rxs = np.where(rm)
    if len(rxs) > 0:
        k2 = int((obs.step * 19 + int(obs.city_pop) * 3)) % len(rxs)
        rx2, ry2 = int(rxs[k2]), int(rys[k2])
        for ddx, ddy in [(0,1),(1,0),(0,-1),(-1,0)]:
            nx2, ny2 = rx2+ddx, ry2+ddy
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Hybrid policy combining best ideas from both parents:
    - Two neighborhoods with coal plants (Parent B layout)
    - Vertical wire spines from plants (Parent B)
    - Horizontal road grid with vertical connectors (Parent B)
    - Lateral wires for coverage (Parent B)
    - Dynamic zone placement scanning (Parent A + B combined)
    - Adaptive vertical extent based on population (Parent B)
    - Balanced zone ratios (Parent A)
    - Services when population warrants (Parent A)
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    all_zones = resm | comm | indm

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def area_free(cx, cy):
        if cx < 1 or cx > WORLD_W - 2 or cy < 1 or cy > WORLD_H - 2:
            return False
        for dy in [-1, 0, 1]:
            for dx in [-1, 0, 1]:
                r, c = cy + dy, cx + dx
                if not (0 <= r < WORLD_H and 0 <= c < WORLD_W):
                    return False
                if not em[r, c]:
                    return False
        return True

    def zone_exists_near(cx, cy, radius=2):
        r0 = max(0, cy - radius)
        r1 = min(WORLD_H, cy + radius + 1)
        c0 = max(0, cx - radius)
        c1 = min(WORLD_W, cx + radius + 1)
        return np.any(all_zones[r0:r1, c0:c1])

    def has_wire_near(cx, cy, radius=5):
        r0 = max(0, cy - radius)
        r1 = min(WORLD_H, cy + radius + 1)
        c0 = max(0, cx - radius)
        c1 = min(WORLD_W, cx + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_near(cx, cy, radius=4):
        r0 = max(0, cy - radius)
        r1 = min(WORLD_H, cy + radius + 1)
        c0 = max(0, cx - radius)
        c1 = min(WORLD_W, cx + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    def pick_zone():
        # Target: ~50% res, 25% com, 25% ind
        t = total_zones + 1
        if res_count / t < 0.45:
            return Tool.RESIDENTIAL
        elif com_count / t < 0.27:
            return Tool.COMMERCIAL
        elif ind_count / t < 0.27:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Adaptive vertical extent
    if pop < 100:
        v_extent = 10
    elif pop < 300:
        v_extent = 16
    elif pop < 600:
        v_extent = 22
    else:
        v_extent = 28

    cy = WORLD_H // 2  # = 50

    # Two neighborhoods
    neighborhoods = [
        {'px': 35, 'py': 50, 'wire_col': 35, 'road_left': 29, 'road_right': 41},
        {'px': 80, 'py': 50, 'wire_col': 80, 'road_left': 74, 'road_right': 86},
    ]

    for nb in neighborhoods:
        px, py = nb['px'], nb['py']
        wc = nb['wire_col']
        rl = nb['road_left']
        rr_col = nb['road_right']

        # Step 1: ensure plant exists near this neighborhood
        local_pm = pm[max(0, py-5):min(WORLD_H, py+6), max(0, px-5):min(WORLD_W, px+6)]
        has_plant = np.any(local_pm)

        if not has_plant:
            for dy in range(-3, 4):
                for dx in range(-3, 4):
                    npx, npy = px + dx, py + dy
                    if area_free(npx, npy):
                        return (Tool.COALPOWER, npx, npy)
            continue

        # Find actual plant center
        plant_rows, plant_cols = np.where(pm)
        near = [(plant_rows[i], plant_cols[i]) for i in range(len(plant_rows))
                if abs(plant_cols[i] - px) <= 12 and abs(plant_rows[i] - py) <= 12]
        if near:
            plant_cy = int(np.mean([r for r, c in near]))
            plant_cx = int(np.mean([c for r, c in near]))
        else:
            plant_cy, plant_cx = py, px

        # Step 2: extend wire spine vertically from plant
        spine_top = max(2, cy - v_extent)
        spine_bot = min(WORLD_H - 3, cy + v_extent)

        wire_on_col = [r for r in range(WORLD_H) if wm[r, wc]]

        if not wire_on_col:
            # Start wire adjacent to plant
            for dy in range(0, 7):
                for nr in [plant_cy + dy, plant_cy - dy]:
                    if spine_top <= nr <= spine_bot and 0 <= nr < WORLD_H:
                        if 0 <= wc < WORLD_W and (em[nr, wc] or wm[nr, wc]):
                            return (Tool.WIRE, wc, nr)
        else:
            min_wr = min(wire_on_col)
            max_wr = max(wire_on_col)

            # Extend downward
            if max_wr < spine_bot:
                nr = max_wr + 1
                if 0 <= nr < WORLD_H and 0 <= wc < WORLD_W and not pm[nr, wc] and (em[nr, wc] or wm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

            # Extend upward
            if min_wr > spine_top:
                nr = min_wr - 1
                if 0 <= nr < WORLD_H and 0 <= wc < WORLD_W and not pm[nr, wc] and (em[nr, wc] or wm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

            # Step 3: horizontal roads at multiple rows for dense coverage
            road_rows = [cy - 6, cy - 2, cy + 2, cy + 6]
            road_span_start = min(rl - 3, wc - 9)
            road_span_end = max(rr_col + 3, wc + 9)

            for rrow in road_rows:
                if 0 < rrow < WORLD_H:
                    for rc in range(road_span_start, road_span_end + 1):
                        if 0 <= rc < WORLD_W and em[rrow, rc] and not pm[rrow, rc] and not wm[rrow, rc]:
                            return (Tool.ROAD, rc, rrow)

            # Step 4: vertical road connectors
            for rc in [rl, wc - 4, wc + 4, rr_col]:
                if 0 <= rc < WORLD_W:
                    for ry in range(min(road_rows), max(road_rows) + 1):
                        if 0 <= ry < WORLD_H and em[ry, rc] and not pm[ry, rc] and not wm[ry, rc]:
                            return (Tool.ROAD, rc, ry)

            # Step 5: lateral wires from spine to zone columns
            for wr in wire_on_col:
                # Wire leftward
                for wcc in range(wc - 1, rl - 4, -1):
                    if 0 <= wcc < WORLD_W:
                        if wm[wr, wcc]:
                            break
                        if pm[wr, wcc]:
                            break
                        if rm[wr, wcc]:
                            # cross road with wire
                            continue
                        if em[wr, wcc]:
                            return (Tool.WIRE, wcc, wr)
                        else:
                            break
                # Wire rightward
                for wcc in range(wc + 1, rr_col + 4):
                    if 0 <= wcc < WORLD_W:
                        if wm[wr, wcc]:
                            break
                        if pm[wr, wcc]:
                            break
                        if rm[wr, wcc]:
                            continue
                        if em[wr, wcc]:
                            return (Tool.WIRE, wcc, wr)
                        else:
                            break

            # Step 6: place zones at strategic positions
            zone_cols_left = [rl - 3, rl, rl + 3]
            zone_cols_right = [rr_col - 3, rr_col, rr_col + 3]
            zone_cols_mid = [wc - 5, wc + 5]
            all_zone_cols = zone_cols_left + zone_cols_mid + zone_cols_right

            # Zones above and below road rows, and between them
            zone_row_offsets = [cy - 9, cy - 4, cy, cy + 4, cy + 9]

            for zy in zone_row_offsets:
                if 1 <= zy <= WORLD_H - 2:
                    for zx in all_zone_cols:
                        if 1 <= zx <= WORLD_W - 2:
                            if (not zone_exists_near(zx, zy, 1) and area_free(zx, zy)
                                    and has_wire_near(zx, zy, 6) and has_road_near(zx, zy, 5)):
                                return (pick_zone(), zx, zy)

            # Step 7: dynamic scan for any empty area near wires+roads
            wire_rows_set = set(wire_on_col)
            for zy in range(spine_top + 3, spine_bot - 2, 3):
                wire_near = any(abs(zy - wr) <= 4 for wr in wire_rows_set)
                road_near = has_road_near(wc, zy, 7)
                if wire_near and road_near:
                    for zx in [wc - 7, wc - 4, wc - 1, wc + 1, wc + 4, wc + 7]:
                        if 1 <= zx <= WORLD_W - 2:
                            if not zone_exists_near(zx, zy, 1) and area_free(zx, zy):
                                return (pick_zone(), zx, zy)

    # Additional coal plant when population demands more power
    if pop > 300:
        plant_count = int(np.sum(pm)) // 9
        if plant_count < 3:
            extra_plants = [(58, 50), (58, 36), (58, 64)]
            for epx, epy in extra_plants:
                local = pm[max(0, epy-5):min(WORLD_H, epy+6), max(0, epx-5):min(WORLD_W, epx+6)]
                if not np.any(local) and area_free(epx, epy):
                    return (Tool.COALPOWER, epx, epy)

    # Wire from center plant to both neighborhoods if extra plant placed
    if pop > 300:
        # Connect center area (x=58) with wires toward neighborhoods
        for cx_wire in range(36, 80):
            wy_mid = cy
            if in_bounds(cx_wire, wy_mid) and em[wy_mid, cx_wire]:
                # Check adjacent wire/plant
                adj = False
                for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
                    nx2, ny2 = cx_wire+ddx, wy_mid+ddy
                    if in_bounds(nx2, ny2) and (bool(pm[ny2,nx2]) or bool(wm[ny2,nx2])):
                        adj = True; break
                if adj:
                    return (Tool.WIRE, cx_wire, wy_mid)

    # Police/fire services
    if pop > 400:
        for fx, fy in [(35, 38), (80, 38), (35, 62), (80, 62)]:
            if area_free(fx, fy):
                near_tile = tm[max(0, fy-6):min(WORLD_H, fy+7), max(0, fx-6):min(WORLD_W, fx+7)]
                if not np.any((near_tile >= 600) & (near_tile <= 800)):
                    return (Tool.POLICESTATION, fx, fy)

    if pop > 600:
        for fx, fy in [(35, 42), (80, 42), (35, 58), (80, 58)]:
            if area_free(fx, fy):
                return (Tool.FIRESTATION, fx, fy)

    # Fallback: extend road from existing road frontier
    rys, rxs = np.where(rm)
    if len(rxs) > 0:
        k2 = int(obs.step * 13 + 7) % len(rxs)
        rx2, ry2 = int(rxs[k2]), int(rys[k2])
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx2, ny2 = rx2+ddx, ry2+ddy
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire from existing wire frontier
    wys, wxs = np.where(wm)
    if len(wxs) > 0:
        k3 = int(obs.step * 7 + 3) % len(wxs)
        wx2, wy2 = int(wxs[k3]), int(wys[k3])
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx2, ny2 = wx2+ddx, wy2+ddy
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Hybrid policy combining Parent A's multi-cluster vertical spine approach
    with Parent B's reactive closed-loop wire/road/zone placement.

    Strategy:
    1. Place coal power plant near map center
    2. Build vertical wire spine from plant (Parent A style)
    3. Build flanking road columns (Parent A style)  
    4. Place balanced zones near roads AND power (Parent B's efficient zone finder)
    5. Expand to second cluster when city grows
    6. Add services when population warrants
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Central anchor
    cx, cy = 57, 50  # slightly left of center

    # ---- Phase 1: Place coal power plant ----
    plant_ys, plant_xs = np.where(pm)
    has_plant = len(plant_xs) > 0
    if not has_plant:
        return (Tool.COALPOWER, cx, cy)

    pcx = int(np.mean(plant_xs))
    pcy = int(np.mean(plant_ys))

    # ---- Define spine geometry from plant ----
    wire_col = pcx + 3   # vertical wire spine just right of plant
    road_col_r = wire_col + 2   # road right of wire
    road_col_l = wire_col - 2   # road left of wire
    zone_col_r = road_col_r + 2  # zones right of right road
    zone_col_l = road_col_l - 2  # zones left of left road

    half_span = min(20, max(10, 10 + obs.city_pop // 30))
    tmin = max(2, pcy - half_span)
    tmax = min(WORLD_H - 3, pcy + half_span)

    # ---- Phase 2: Build vertical wire spine ----
    wire_rows = sorted(r for r in range(WORLD_H) if 0 <= wire_col < WORLD_W and wm[r, wire_col])

    if not wire_rows:
        # Place first wire adjacent to plant
        for dy in range(0, 5):
            ny = pcy + dy
            if in_bounds(wire_col, ny) and (em[ny, wire_col] or wm[ny, wire_col]):
                return (Tool.WIRE, wire_col, ny)
        for dy in range(-4, 0):
            ny = pcy + dy
            if in_bounds(wire_col, ny) and (em[ny, wire_col] or wm[ny, wire_col]):
                return (Tool.WIRE, wire_col, ny)
    else:
        min_wr = wire_rows[0]
        max_wr = wire_rows[-1]
        # Extend downward
        if max_wr < tmax:
            nr = max_wr + 1
            if in_bounds(wire_col, nr) and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if min_wr > tmin:
            nr = min_wr - 1
            if in_bounds(wire_col, nr) and (em[nr, wire_col] or wm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    wire_rows_set = set(wire_rows)

    # ---- Phase 3: Build road columns flanking wire spine ----
    road_count = int(np.sum(rm))
    if wire_rows:
        # Right road
        if 0 <= road_col_r < WORLD_W:
            for wr in wire_rows:
                if not rm[wr, road_col_r] and em[wr, road_col_r]:
                    return (Tool.ROAD, road_col_r, wr)
        # Left road
        if 0 <= road_col_l < WORLD_W:
            for wr in wire_rows:
                if not rm[wr, road_col_l] and em[wr, road_col_l]:
                    return (Tool.ROAD, road_col_l, wr)

    # ---- Zone placement using Parent B's efficient neighborhood method ----
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        if com_count / total_zones < 0.22:
            return Tool.COMMERCIAL
        if ind_count / total_zones < 0.22:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def find_zone_placement():
        # Efficient neighborhood mask for roads
        nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1,0),(1,0),(0,-1),(0,1),(-2,0),(2,0),(0,-2),(0,2)]:
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

        # Efficient neighborhood mask for power (wire or plant within 5 tiles)
        nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-6, 7):
            for dx in range(-6, 7):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
                nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

        zone_mask = resm | comm | indm
        cand = em & nbr_road & nbr_power
        # Keep away from edges (need 3x3 space)
        cand[:2, :] = False
        cand[WORLD_H-2:, :] = False
        cand[:, :2] = False
        cand[:, WORLD_W-2:] = False

        cys2, cxs2 = np.where(cand)
        if len(cxs2) == 0:
            return None

        # Deterministic reactive selection
        key = int(obs.tile_map.sum() % max(len(cxs2), 1))
        for offset in range(min(len(cxs2), 80)):
            k = (key + offset * 13) % len(cxs2)
            zx, zy = int(cxs2[k]), int(cys2[k])
            # Check 3x3 clearance
            ok = True
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    ny2, nx2 = zy + dr, zx + dc
                    if not in_bounds(nx2, ny2):
                        ok = False; break
                    if not (bool(em[ny2, nx2]) or bool(zone_mask[ny2, nx2])):
                        ok = False; break
                if not ok:
                    break
            if ok:
                return (pick_tool(), zx, zy)
        return None

    # ---- Phase 4: Place zones ----
    spine_filled = len(wire_rows)
    step_mod = obs.step % 5

    # Build spine first, then interleave road/zone
    if spine_filled < 8 and wire_rows is not None:
        pass  # handled above in Phase 2

    zone_action = find_zone_placement()

    if step_mod in (0, 1):
        # Try zone first if we have enough infrastructure
        if road_count > 8 and zone_action is not None:
            return zone_action
    elif step_mod == 2:
        # Road extension
        if wire_rows:
            if 0 <= road_col_r < WORLD_W:
                for wr in wire_rows:
                    if not rm[wr, road_col_r] and em[wr, road_col_r]:
                        return (Tool.ROAD, road_col_r, wr)
    elif step_mod == 3:
        if zone_action is not None:
            return zone_action

    if zone_action is not None:
        return zone_action

    # ---- Phase 5: Second cluster when population grows ----
    if obs.city_pop > 200 and wire_rows:
        wire_col2 = pcx + 15
        road_col_r2 = wire_col2 + 2
        road_col_l2 = wire_col2 - 2

        if 0 <= wire_col2 < WORLD_W:
            wire_rows2 = sorted(r for r in range(WORLD_H) if wm[r, wire_col2])

            if not wire_rows2:
                # Lay horizontal bridge from spine to wire_col2
                for wc in range(wire_col + 1, wire_col2 + 1):
                    if in_bounds(wc, pcy) and em[pcy, wc]:
                        return (Tool.WIRE, wc, pcy)
            else:
                min_wr2 = wire_rows2[0]
                max_wr2 = wire_rows2[-1]
                if max_wr2 < tmax:
                    nr = max_wr2 + 1
                    if in_bounds(wire_col2, nr) and (em[nr, wire_col2] or wm[nr, wire_col2]):
                        return (Tool.WIRE, wire_col2, nr)
                if min_wr2 > tmin:
                    nr = min_wr2 - 1
                    if in_bounds(wire_col2, nr) and (em[nr, wire_col2] or wm[nr, wire_col2]):
                        return (Tool.WIRE, wire_col2, nr)
                if 0 <= road_col_r2 < WORLD_W:
                    for wr in wire_rows2:
                        if not rm[wr, road_col_r2] and em[wr, road_col_r2]:
                            return (Tool.ROAD, road_col_r2, wr)
                if 0 <= road_col_l2 < WORLD_W:
                    for wr in wire_rows2:
                        if not rm[wr, road_col_l2] and em[wr, road_col_l2]:
                            return (Tool.ROAD, road_col_l2, wr)

    # ---- Phase 6: Second power plant for large city ----
    if obs.city_pop > 500 and not state.get("plant2_placed", False):
        px2 = pcx + 20
        py2 = pcy
        clear = all(
            in_bounds(px2 + dc, py2 + dr) and em[py2 + dr, px2 + dc]
            for dr in [-1, 0, 1] for dc in [-1, 0, 1]
        )
        if clear:
            state["plant2_placed"] = True
            return (Tool.COALPOWER, px2, py2)
        # Connect wire to it
        for wc in range(wire_col + 1, min(px2 + 1, WORLD_W)):
            if in_bounds(wc, pcy) and em[pcy, wc]:
                return (Tool.WIRE, wc, pcy)

    # ---- Services when population warrants ----
    if obs.city_pop > 300:
        for fx, fy in [(cx + 8, cy - 10), (cx - 8, cy + 10)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 600:
        for fx, fy in [(cx + 8, cy + 10), (cx - 8, cy - 10)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.POLICESTATION, fx, fy)

    # Last resort: extend any existing road
    rys2, rxs2 = np.where(rm)
    if len(rxs2) > 0:
        k2 = int(obs.step * 17 + int(obs.city_pop)) % len(rxs2)
        rx2, ry2 = int(rxs2[k2]), int(rys2[k2])
        for ddx, ddy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nx2, ny2 = rx2 + ddx, ry2 + ddy
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop policy: scan the map each step and place the next useful tile
    based on what's already there. Uses a phase system but each phase decision
    reads the current map state.

    Strategy:
    - Phase 0: Place coal power plant if none exists
    - Phase 1: Extend wires from plant outward along a spine
    - Phase 2: Lay roads parallel to wire spine
    - Phase 3: Place zones (R/C/I) adjacent to roads, powered areas
    - Phase 4: Add more infrastructure reactively
    """

    tile = obs.tile_map  # (100, 120)

    # Helper: check bounds
    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Helper: find nearest empty cell adjacent to existing infrastructure
    def find_adjacent_empty(mask, direction='any'):
        positions = np.argwhere(mask)  # (N, 2) in (row, col) = (y, x)
        if len(positions) == 0:
            return None
        emp = empty_mask(tile)
        for pos in positions:
            ry, rx = pos
            for dy, dx in [(0,1),(0,-1),(1,0),(-1,0)]:
                ny, nx = ry+dy, rx+dx
                if in_bounds(nx, ny) and emp[ny, nx]:
                    return (nx, ny)
        return None

    # Count existing infrastructure
    plants = plant_mask(tile)
    wires = wire_mask(tile)
    roads = road_mask(tile)
    res = res_mask(tile)
    com = com_mask(tile)
    ind = ind_mask(tile)

    n_plants = np.sum(plants)
    n_wires = np.sum(wires)
    n_roads = np.sum(roads)
    n_res = np.sum(res)
    n_com = np.sum(com)
    n_ind = np.sum(ind)

    step = obs.step

    # Core layout constants
    CX, CY = 60, 50  # center of city

    # Phase 0: Ensure we have power plants
    # Place two coal plants
    plant_positions = [(25, 50), (95, 50)]
    for px, py in plant_positions:
        if in_bounds(px, py) and not plants[py, px]:
            # Check if it's empty or non-critical
            return (Tool.COALPOWER, px, py)

    # Phase 1: Wire spine - horizontal wire connecting plants through center
    # Wire from left plant rightward to center, and center to right plant
    # Left plant at x=25, right at x=95
    # Main wire spine at y=50, x from 25 to 95
    for wx in range(26, 95):
        if in_bounds(wx, 50) and not wires[50, wx] and not plants[50, wx]:
            # Place wire along spine
            return (Tool.WIRE, wx, 50)

    # Vertical wire spines at x=35 and x=85
    for wy in range(38, 63):
        if not wires[wy, 35] and not plants[wy, 35] and not roads[wy, 35]:
            return (Tool.WIRE, 35, wy)
    for wy in range(38, 63):
        if not wires[wy, 85] and not plants[wy, 85] and not roads[wy, 85]:
            return (Tool.WIRE, 85, wy)

    # Also wire at x=60 vertical
    for wy in range(38, 63):
        if not wires[wy, 60] and not plants[wy, 60] and not roads[wy, 60]:
            return (Tool.WIRE, 60, wy)

    # Phase 2: Roads - place roads parallel to wire spines
    # Vertical roads at x=36, x=84, x=61
    road_cols = [(36, 38, 63), (84, 38, 63), (61, 38, 63)]
    for rx_col, r_start, r_end in road_cols:
        for ry in range(r_start, r_end):
            if not roads[ry, rx_col] and not plants[ry, rx_col] and not wires[ry, rx_col]:
                return (Tool.ROAD, rx_col, ry)

    # Horizontal road at y=51 (just below wire spine)
    for hx in range(26, 95):
        if not roads[51, hx] and not plants[51, hx] and not wires[51, hx]:
            return (Tool.ROAD, hx, 51)

    # Also horizontal roads at y=40 and y=60
    for hx in range(26, 95):
        if not roads[40, hx] and not plants[40, hx]:
            return (Tool.ROAD, hx, 40)
    for hx in range(26, 95):
        if not roads[60, hx] and not plants[60, hx]:
            return (Tool.ROAD, hx, 60)

    # Phase 3: Place zones reactively based on road coverage
    # Find road positions and place zones adjacent to them
    # Scan the map for good zone placement spots

    # Count existing zones
    total_zones = n_res + n_com + n_ind

    # Target ratio: 3:1:1 R:C:I
    target_res = total_zones * 3 // 5 + 1
    target_com = total_zones // 5 + 1
    target_ind = total_zones // 5 + 1

    # Determine what zone type to place next
    if n_res < target_res:
        next_zone = Tool.RESIDENTIAL
    elif n_com < target_com:
        next_zone = Tool.COMMERCIAL
    else:
        next_zone = Tool.INDUSTRIAL

    # Zone placement grid: place zones centered 3 apart, adjacent to roads
    # Left cluster: x=30-44, y=38-62
    # Middle cluster: x=55-70, y=38-62  
    # Right cluster: x=75-90, y=38-62

    def can_place_zone(cx, cy):
        """Check if a 3x3 zone centered at cx,cy can be placed (no critical infra)"""
        if not in_bounds(cx, cy):
            return False
        # Check the center and surroundings are not plants or roads
        for dy in range(-1, 2):
            for dx in range(-1, 2):
                nx, ny = cx+dx, cy+dy
                if not in_bounds(nx, ny):
                    return False
                if plants[ny, nx]:
                    return False
        return True

    def has_road_nearby(cx, cy, radius=3):
        """Check if road exists within radius of zone center"""
        for dy in range(-radius, radius+1):
            for dx in range(-radius, radius+1):
                nx, ny = cx+dx, cy+dy
                if in_bounds(nx, ny) and roads[ny, nx]:
                    return True
        return False

    def has_power_nearby(cx, cy, radius=4):
        """Check if wire or plant exists within radius"""
        for dy in range(-radius, radius+1):
            for dx in range(-radius, radius+1):
                nx, ny = cx+dx, cy+dy
                if in_bounds(nx, ny) and (wires[ny, nx] or plants[ny, nx]):
                    return True
        return False

    def zone_exists(cx, cy):
        """Check if a zone already occupies this area"""
        for dy in range(-1, 2):
            for dx in range(-1, 2):
                nx, ny = cx+dx, cy+dy
                if in_bounds(nx, ny):
                    t = tile[ny, nx]
                    if (res[ny, nx] or com[ny, nx] or ind[ny, nx]):
                        return True
        return False

    # Zone columns and rows
    zone_x_centers = list(range(29, 44, 3)) + list(range(55, 68, 3)) + list(range(72, 93, 3))
    zone_y_centers = list(range(41, 61, 3))

    # Prioritize zones with road AND power nearby
    best_powered_road = None
    best_road_only = None

    zone_counter = state.get('zone_counter', 0)

    for yi, zy in enumerate(zone_y_centers):
        for xi, zx in enumerate(zone_x_centers):
            if not can_place_zone(zx, zy):
                continue
            if zone_exists(zx, zy):
                continue
            has_r = has_road_nearby(zx, zy)
            has_p = has_power_nearby(zx, zy)
            if has_r and has_p:
                if best_powered_road is None:
                    best_powered_road = (zx, zy)
            elif has_r:
                if best_road_only is None:
                    best_road_only = (zx, zy)

    # Determine zone type cyclically based on position
    def zone_type_for(zx, zy):
        # Left area: residential, middle: commercial, right: industrial
        if zx < 50:
            return Tool.RESIDENTIAL
        elif zx < 72:
            return Tool.COMMERCIAL
        else:
            return Tool.INDUSTRIAL

    if best_powered_road is not None:
        zx, zy = best_powered_road
        state['zone_counter'] = zone_counter + 1
        return (zone_type_for(zx, zy), zx, zy)

    if best_road_only is not None:
        # Place wire to bring power here
        zx, zy = best_road_only
        # Find closest wire and extend toward zone
        wire_positions = np.argwhere(wires | plants)
        if len(wire_positions) > 0:
            dists = np.abs(wire_positions[:,1] - zx) + np.abs(wire_positions[:,0] - zy)
            closest_idx = np.argmin(dists)
            wy, wx = wire_positions[closest_idx]
            # Step one tile toward zone
            dx = np.sign(zx - wx)
            dy = np.sign(zy - wy)
            nx, ny = wx + dx, wy + dy
            if in_bounds(nx, ny) and not plants[ny, nx] and not roads[ny, nx]:
                return (Tool.WIRE, nx, ny)
        state['zone_counter'] = zone_counter + 1
        return (zone_type_for(zx, zy), zx, zy)

    # Phase 4: Services and extra zones
    # Place fire stations and police stations
    service_spots = [
        (Tool.FIRESTATION, 36, 35),
        (Tool.POLICESTATION, 84, 35),
        (Tool.FIRESTATION, 60, 65),
        (Tool.POLICESTATION, 36, 65),
    ]
    for tool, sx, sy in service_spots:
        if in_bounds(sx, sy) and empty_mask(tile)[sy, sx]:
            # Check no plant nearby
            if not plants[sy, sx]:
                return (tool, sx, sy)

    # Extend city with more zones further out
    extended_xs = list(range(20, 28, 3)) + list(range(95, 110, 3))
    extended_ys = list(range(41, 61, 3))

    # First ensure roads reach
    for ex in extended_xs:
        for wy in range(38, 63):
            if not roads[wy, ex] and not plants[wy, ex] and in_bounds(ex, wy):
                return (Tool.ROAD, ex, wy)

    for ey in extended_ys:
        for ex in extended_xs:
            if not can_place_zone(ex, ey):
                continue
            if zone_exists(ex, ey):
                continue
            return (Tool.RESIDENTIAL if ex < 60 else Tool.INDUSTRIAL, ex, ey)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads the current map each step and decides what to place next.
    Strategy:
    - One coal power plant at a fixed anchor
    - Grow a vertical wire spine from the plant upward and downward
    - For each wire row, place roads on left/right of spine
    - Place zones adjacent to roads, balanced RES/COM/IND
    - Second plant + corridor when population warrants
    - All decisions based on current observed map state
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def zone_area_free(cy, cx):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                r, c = cy + dr, cx + dc
                if not in_bounds(c, r):
                    return False
                if not bool(em[r, c]):
                    return False
        return True

    def pick_zone(row):
        res_c = int(np.sum(resm))
        com_c = int(np.sum(comm))
        ind_c = int(np.sum(indm))
        # Need some IND for jobs
        if ind_c == 0:
            return Tool.INDUSTRIAL
        if com_c == 0:
            return Tool.COMMERCIAL
        # Balance: ~50% RES, 25% COM, 25% IND
        total = res_c + com_c + ind_c
        if total == 0:
            return Tool.RESIDENTIAL
        if ind_c * 4 < total:
            return Tool.INDUSTRIAL
        if com_c * 4 < total:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Phase 1: Ensure primary power plant exists ---
    P1X, P1Y = 60, 50  # center of map
    SPINE1 = P1X + 4   # wire spine column = 64

    # Check for plant near P1
    plant_ys, plant_xs = np.where(pm)
    has_plant1 = any(abs(px - P1X) <= 5 and abs(py - P1Y) <= 5
                     for py, px in zip(plant_ys.tolist(), plant_xs.tolist()))

    if not has_plant1:
        return (Tool.COALPOWER, P1X, P1Y)

    # --- Closed-loop spine building ---
    # Read current wire positions in spine column
    def get_wire_rows(col):
        return sorted(int(r) for r in np.where(wm[:, col])[0])

    def get_road_rows(col):
        return set(int(r) for r in np.where(rm[:, col])[0])

    def build_spine_and_city(spine_col, plant_cy, cy_ref, label):
        """
        Observe current state and return next action for this corridor.
        Spine grows to cover cy_ref ± span based on current population.
        """
        road_L = spine_col - 1
        road_R = spine_col + 1
        # Zone columns: 3 tiles from road (so center is at road±4 from spine)
        zone_cols_L = [spine_col - 4, spine_col - 8]
        zone_cols_R = [spine_col + 4, spine_col + 8]

        # Adaptive span
        pop_extra = min(35, obs.city_pop // 15)
        span = 14 + pop_extra
        tmin = max(2, cy_ref - span)
        tmax = min(WORLD_H - 3, cy_ref + span)

        wire_rows = get_wire_rows(spine_col)

        # Step 1: Start wire at plant row if no wire yet
        if not wire_rows:
            if in_bounds(spine_col, plant_cy):
                return (Tool.WIRE, spine_col, plant_cy)
            return None

        min_wr = wire_rows[0]
        max_wr = wire_rows[-1]

        # Step 2: Extend spine downward
        if max_wr < tmax:
            nr = max_wr + 1
            if in_bounds(spine_col, nr):
                # Don't overwrite plant
                if bool(em[nr, spine_col]):
                    return (Tool.WIRE, spine_col, nr)

        # Step 3: Extend spine upward
        if min_wr > tmin:
            nr = min_wr - 1
            if in_bounds(spine_col, nr):
                if bool(em[nr, spine_col]):
                    return (Tool.WIRE, spine_col, nr)

        # Step 4: For each wire row, build adjacent roads if missing
        road_rows_L = get_road_rows(road_L)
        road_rows_R = get_road_rows(road_R)

        for wr in wire_rows:
            if wr < tmin or wr > tmax:
                continue
            # Left road
            if wr not in road_rows_L and in_bounds(road_L, wr):
                if bool(em[wr, road_L]):
                    return (Tool.ROAD, road_L, wr)
            # Right road
            if wr not in road_rows_R and in_bounds(road_R, wr):
                if bool(em[wr, road_R]):
                    return (Tool.ROAD, road_R, wr)

        # Step 5: Place lateral wires to zone columns (for power)
        # Left lateral wires
        for wr in wire_rows:
            if wr < tmin or wr > tmax:
                continue
            for wc in range(spine_col - 2, max(spine_col - 10, 0) - 1, -1):
                if not in_bounds(wc, wr):
                    break
                if bool(pm[wr, wc]):
                    break  # don't cross plant
                if bool(rm[wr, wc]):
                    break  # road blocks wire run
                if not bool(wm[wr, wc]):
                    if bool(em[wr, wc]):
                        return (Tool.WIRE, wc, wr)
                    break

        # Right lateral wires
        for wr in wire_rows:
            if wr < tmin or wr > tmax:
                continue
            for wc in range(spine_col + 2, min(spine_col + 10, WORLD_W)):
                if not in_bounds(wc, wr):
                    break
                if bool(pm[wr, wc]):
                    break
                if bool(rm[wr, wc]):
                    break
                if not bool(wm[wr, wc]):
                    if bool(em[wr, wc]):
                        return (Tool.WIRE, wc, wr)
                    break

        # Step 6: Place lateral roads to zone columns
        for wr in wire_rows:
            if wr < tmin or wr > tmax:
                continue
            # Left road extension
            for rc in range(road_L - 1, max(spine_col - 10, 0) - 1, -1):
                if not in_bounds(rc, wr):
                    break
                if bool(pm[wr, rc]):
                    break
                if not bool(rm[wr, rc]):
                    if bool(em[wr, rc]):
                        return (Tool.ROAD, rc, wr)
                    break
            # Right road extension
            for rc in range(road_R + 1, min(spine_col + 10, WORLD_W)):
                if not in_bounds(rc, wr):
                    break
                if bool(pm[wr, rc]):
                    break
                if not bool(rm[wr, rc]):
                    if bool(em[wr, rc]):
                        return (Tool.ROAD, rc, wr)
                    break

        # Step 7: Place zones adjacent to roads
        # Read current road state
        for wr in wire_rows:
            if wr < tmin or wr > tmax:
                continue
            if wr < 2 or wr >= WORLD_H - 2:
                continue

            # Check road proximity (within 1 row)
            road_L_nearby = any(bool(rm[wr + dr, road_L])
                                for dr in [-1, 0, 1]
                                if in_bounds(road_L, wr + dr))
            road_R_nearby = any(bool(rm[wr + dr, road_R])
                                for dr in [-1, 0, 1]
                                if in_bounds(road_R, wr + dr))

            for zc in zone_cols_L:
                if road_L_nearby and in_bounds(zc, wr) and 2 <= zc < WORLD_W - 2:
                    if zone_area_free(wr, zc):
                        return (pick_zone(wr), zc, wr)

            for zc in zone_cols_R:
                if road_R_nearby and in_bounds(zc, wr) and 2 <= zc < WORLD_W - 2:
                    if zone_area_free(wr, zc):
                        return (pick_zone(wr), zc, wr)

        return None

    # Build primary corridor
    action = build_spine_and_city(SPINE1, P1Y, P1Y, 'primary')
    if action is not None:
        return action

    # --- Phase 2: Second power plant + corridor when pop > 80 ---
    P2X, P2Y = 60, 25   # upper corridor plant
    SPINE2 = P2X + 4    # = 64 (same column, different section)

    if obs.city_pop > 80:
        has_plant2 = any(abs(px - P2X) <= 5 and abs(py - P2Y) <= 5
                         for py, px in zip(plant_ys.tolist(), plant_xs.tolist()))

        if not has_plant2:
            # Only place if area is clear
            if zone_area_free(P2Y, P2X):
                return (Tool.COALPOWER, P2X, P2Y)

        # Connect plant2 via wire to spine2
        # Check if spine2 has wire near plant2
        wire_rows2 = get_wire_rows(SPINE2)
        near_plant2 = any(abs(wr - P2Y) <= 6 for wr in wire_rows2)
        if not near_plant2:
            # Lay wire from plant2 toward spine
            for wc in range(P2X + 2, SPINE2 + 1):
                if in_bounds(wc, P2Y) and bool(em[P2Y, wc]) and not bool(pm[P2Y, wc]):
                    return (Tool.WIRE, wc, P2Y)

        # Build lower corridor (south half)
        P3X, P3Y = 60, 75
        has_plant3 = any(abs(px - P3X) <= 5 and abs(py - P3Y) <= 5
                         for py, px in zip(plant_ys.tolist(), plant_xs.tolist()))

        if obs.city_pop > 200 and not has_plant3:
            if zone_area_free(P3Y, P3X):
                return (Tool.COALPOWER, P3X, P3Y)

        # Try upper corridor
        action2 = build_spine_and_city(SPINE2, P2Y, P2Y, 'upper')
        if action2 is not None:
            return action2

    # --- Services based on current population ---
    if obs.city_pop > 250:
        fx, fy = SPINE1 + 8, P1Y - 10
        if in_bounds(fx, fy) and zone_area_free(fy, fx):
            return (Tool.FIRESTATION, fx, fy)

    if obs.city_pop > 450:
        px2, py2 = SPINE1 - 8, P1Y + 10
        if in_bounds(px2, py2) and zone_area_free(py2, px2):
            return (Tool.POLICESTATION, px2, py2)

    # --- Fallback: scan existing roads and extend ---
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        idx = int(obs.step * 17) % len(road_xs)
        rx, ry = int(road_xs[idx]), int(road_ys[idx])
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx, ny = rx + dx, ry + dy
            if in_bounds(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                return (Tool.ROAD, nx, ny)

    # --- Fallback: extend wires ---
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        idx = int(obs.step * 11) % len(wire_xs)
        wx, wy = int(wire_xs[idx]), int(wire_ys[idx])
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx, ny = wx + dx, wy + dy
            if in_bounds(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                return (Tool.WIRE, nx, ny)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads the current map each step and places the next
    most-needed element based on what's actually there.

    Strategy:
    - Phase 0: Place coal power plant at anchor
    - Phase 1: Extend wire from plant toward zone area
    - Phase 2: Build road grid in zone area
    - Phase 3: Place zones adjacent to roads (and near wire)
    - Phase 4: Fill in more zones reactively

    All decisions read obs.tile_map to find what's already placed.
    """

    # Anchor positions
    PLANT_X, PLANT_Y = 20, 50
    ZONE_START_X = 28
    ZONE_END_X = 90
    ZONE_Y_CENTER = 50

    tile = obs.tile_map

    # Helper: check if position is in bounds
    def inbounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Helper: is position empty (no road, wire, zone, plant)
    def is_empty(x, y):
        if not inbounds(x, y):
            return False
        return empty_mask[y, x]

    # Helper: is position a wire
    def is_wire(x, y):
        if not inbounds(x, y):
            return False
        return wire_mask[y, x]

    # Helper: is position a road
    def is_road(x, y):
        if not inbounds(x, y):
            return False
        return road_mask[y, x]

    # Helper: is position a plant
    def is_plant(x, y):
        if not inbounds(x, y):
            return False
        return plant_mask[y, x]

    # Step 1: Ensure power plant exists
    # Check if plant is near anchor
    plant_exists = np.any(plant_mask[PLANT_Y-2:PLANT_Y+3, PLANT_X-2:PLANT_X+3])
    if not plant_exists:
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    # Step 2: Ensure second power plant for right side
    PLANT2_X, PLANT2_Y = 95, 50
    plant2_exists = np.any(plant_mask[PLANT2_Y-2:PLANT2_Y+3, PLANT2_X-2:PLANT2_X+3])

    # Step 3: Extend wire from plant toward zone area
    # Wire should run from plant to cover zone columns
    # Find the rightmost wire in row PLANT_Y
    wire_row = wire_mask[PLANT_Y, :]
    road_row = road_mask[PLANT_Y, :]
    plant_row = plant_mask[PLANT_Y, :]

    # Find connected wire extent from plant
    # Scan from plant rightward to find first gap
    wire_frontier = PLANT_X + 2  # start just right of plant
    for x in range(PLANT_X + 2, ZONE_END_X + 5):
        if wire_mask[PLANT_Y, x] or plant_mask[PLANT_Y, x]:
            wire_frontier = x + 1
        else:
            break

    # If wire hasn't reached zone end, extend it
    if wire_frontier <= ZONE_END_X + 2 and wire_frontier < WORLD_W:
        # Don't place wire on a road - place parallel
        if not road_mask[PLANT_Y, wire_frontier] and not plant_mask[PLANT_Y, wire_frontier]:
            return (Tool.WIRE, wire_frontier, PLANT_Y)
        else:
            # Place wire one row above
            if not road_mask[PLANT_Y - 1, wire_frontier] and not plant_mask[PLANT_Y - 1, wire_frontier]:
                return (Tool.WIRE, wire_frontier, PLANT_Y - 1)

    # Step 4: Place second power plant
    if not plant2_exists:
        # Make sure we don't overwrite wire
        if not wire_mask[PLANT2_Y, PLANT2_X]:
            return (Tool.COALPOWER, PLANT2_X, PLANT2_Y)

    # Connect second plant with wire leftward
    if plant2_exists:
        wire2_frontier = PLANT2_X - 2
        for x in range(PLANT2_X - 2, ZONE_END_X - 1, -1):
            if wire_mask[PLANT_Y, x] or plant_mask[PLANT_Y, x]:
                wire2_frontier = x - 1
            else:
                break
        if wire2_frontier >= ZONE_END_X and wire2_frontier >= 0:
            if not road_mask[PLANT_Y, wire2_frontier] and not plant_mask[PLANT_Y, wire2_frontier]:
                return (Tool.WIRE, wire2_frontier, PLANT_Y)

    # Step 5: Build road grid reactively
    # We want vertical roads at regular intervals, horizontal road at y=50
    # Road columns: every 8 columns starting from ZONE_START_X
    road_cols = list(range(ZONE_START_X + 1, ZONE_END_X, 8))  # e.g. 29, 37, 45, ...

    # Horizontal road at y=ZONE_Y_CENTER
    for x in range(ZONE_START_X, ZONE_END_X + 1):
        if not road_mask[ZONE_Y_CENTER, x] and not wire_mask[ZONE_Y_CENTER, x] and not plant_mask[ZONE_Y_CENTER, x]:
            # Only place if adjacent road or we're starting from the left
            left_has_road = (x == ZONE_START_X) or road_mask[ZONE_Y_CENTER, x-1] or plant_mask[ZONE_Y_CENTER, x-1]
            if left_has_road:
                return (Tool.ROAD, x, ZONE_Y_CENTER)

    # Vertical roads at road_cols
    for rcol in road_cols:
        for y in range(ZONE_Y_CENTER - 15, ZONE_Y_CENTER + 16):
            if not inbounds(rcol, y):
                continue
            if not road_mask[y, rcol] and not wire_mask[y, rcol] and not plant_mask[y, rcol]:
                # Place if adjacent road exists
                above = road_mask[y-1, rcol] if y > 0 else False
                below = road_mask[y+1, rcol] if y < WORLD_H-1 else False
                at_center = (y == ZONE_Y_CENTER)
                if above or below or at_center:
                    return (Tool.ROAD, rcol, y)

    # Step 6: Place vertical wires between road columns (for power distribution)
    wire_cols = list(range(ZONE_START_X + 3, ZONE_END_X, 8))  # offset from road cols
    for wcol in wire_cols:
        for y in range(ZONE_Y_CENTER - 15, ZONE_Y_CENTER + 16):
            if not inbounds(wcol, y):
                continue
            if not wire_mask[y, wcol] and not road_mask[y, wcol] and not plant_mask[y, wcol]:
                # Connect downward from horizontal wire
                above_wire = wire_mask[y-1, wcol] if y > 0 else False
                at_horiz = (y == ZONE_Y_CENTER) and wire_mask[y, wcol-1]
                if above_wire or at_horiz or (y == ZONE_Y_CENTER and wire_mask[ZONE_Y_CENTER, wcol-1]):
                    return (Tool.WIRE, wcol, y)

    # Step 7: Place zones reactively - scan for empty spots adjacent to roads
    # Zone types in rotation
    if "zone_seq" not in state:
        state["zone_seq"] = 0

    zone_tools = [Tool.RESIDENTIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL, 
                  Tool.RESIDENTIAL, Tool.INDUSTRIAL, Tool.COMMERCIAL]

    # Find best empty spot for a zone (3x3, center needs road neighbor)
    best_zone = None
    best_score = -1

    # Scan zone area for empty 3x3 centers near roads
    scan_count = 0
    for y in range(ZONE_Y_CENTER - 14, ZONE_Y_CENTER + 15, 3):
        for x in range(ZONE_START_X + 2, ZONE_END_X - 1, 3):
            if not inbounds(x, y):
                continue
            # Check if center is empty
            if not empty_mask[y, x]:
                continue

            # Check if any neighbor in 5x5 has road
            road_near = False
            wire_near = False
            for dy in range(-2, 3):
                for dx in range(-2, 3):
                    nx, ny = x + dx, y + dy
                    if inbounds(nx, ny):
                        if road_mask[ny, nx]:
                            road_near = True
                        if wire_mask[ny, nx] or plant_mask[ny, nx]:
                            wire_near = True

            if road_near and wire_near:
                # Count how many of the 3x3 tiles are empty
                empty_count = 0
                for dy in range(-1, 2):
                    for dx in range(-1, 2):
                        nx, ny = x + dx, y + dy
                        if inbounds(nx, ny) and empty_mask[ny, nx]:
                            empty_count += 1

                score = empty_count
                if score > best_score:
                    best_score = score
                    best_zone = (x, y)

            scan_count += 1
            if scan_count > 200:
                break
        if scan_count > 200:
            break

    if best_zone is not None:
        x, y = best_zone
        tool = zone_tools[state["zone_seq"] % len(zone_tools)]
        state["zone_seq"] += 1
        return (tool, x, y)

    # Step 8: Add services if city has population
    if obs.city_pop > 200:
        if not np.any(tile[35:41, 25:31] == 0):  # rough check for fire station
            # Place fire station if no services near left side
            fs_x, fs_y = ZONE_START_X + 4, ZONE_Y_CENTER - 18
            if inbounds(fs_x, fs_y) and empty_mask[fs_y, fs_x]:
                return (Tool.FIRESTATION, fs_x, fs_y)

    if obs.city_pop > 400:
        ps_x, ps_y = ZONE_START_X + 4, ZONE_Y_CENTER + 18
        if inbounds(ps_x, ps_y) and empty_mask[ps_y, ps_x]:
            return (Tool.POLICESTATION, ps_x, ps_y)

    # Step 9: Extend zone area - try placing zones with only road nearby (no wire req)
    for y in range(ZONE_Y_CENTER - 14, ZONE_Y_CENTER + 15, 3):
        for x in range(ZONE_START_X + 2, ZONE_END_X - 1, 3):
            if not inbounds(x, y):
                continue
            if not empty_mask[y, x]:
                continue
            road_near = False
            for dy in range(-2, 3):
                for dx in range(-2, 3):
                    nx, ny = x + dx, y + dy
                    if inbounds(nx, ny) and road_mask[ny, nx]:
                        road_near = True
                        break
            if road_near:
                tool = zone_tools[state["zone_seq"] % len(zone_tools)]
                state["zone_seq"] += 1
                return (tool, x, y)

    # Step 10: More wire to reach unserved zones
    # Find a zone without wire nearby and trace wire to it
    for y in range(ZONE_Y_CENTER - 14, ZONE_Y_CENTER + 15):
        for x in range(ZONE_START_X, ZONE_END_X):
            if not inbounds(x, y):
                continue
            if res_mask[y, x] or com_mask[y, x] or ind_mask[y, x]:
                # Zone exists - check if powered (wire nearby)
                wire_near = False
                for dy in range(-3, 4):
                    for dx in range(-3, 4):
                        nx, ny = x + dx, y + dy
                        if inbounds(nx, ny) and (wire_mask[ny, nx] or plant_mask[ny, nx]):
                            wire_near = True
                if not wire_near:
                    # Place wire adjacent to this zone toward the main wire line
                    # Move toward PLANT_Y wire
                    wx = x
                    wy = y + (1 if y < ZONE_Y_CENTER else -1)
                    if inbounds(wx, wy) and not road_mask[wy, wx] and not plant_mask[wy, wx]:
                        return (Tool.WIRE, wx, wy)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Each step reads tile_map freshly and decides next placement
    - Builds a compact powered city cluster around a central coal plant
    - Extends wire spine, road, and zones reactively based on observed state
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    all_zone_mask = resm | comm | indm

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    pop = obs.city_pop
    powered = obs.powered_zones

    # City anchor point
    cx, cy = 60, 50

    # --- Phase 1: Place coal power plant if none exists ---
    if not np.any(pm):
        return (Tool.COALPOWER, cx - 8, cy)

    # Find plant centroid
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Layout: wire spine runs vertically, road runs parallel
    wire_col = plant_cx + 4
    road_col = wire_col + 2
    wire_col = max(2, min(WORLD_W - 3, wire_col))
    road_col = max(2, min(WORLD_W - 3, road_col))

    # Zone columns on each side
    left_zone_col = wire_col - 4
    right_zone_col = road_col + 4
    left_zone_col = max(3, min(WORLD_W - 4, left_zone_col))
    right_zone_col = max(3, min(WORLD_W - 4, right_zone_col))

    # Spine extent scales with population
    if pop < 30:
        spine_half = 5
    elif pop < 100:
        spine_half = 9
    elif pop < 300:
        spine_half = 14
    elif pop < 700:
        spine_half = 20
    else:
        spine_half = 26

    target_min = max(2, cy - spine_half)
    target_max = min(WORLD_H - 3, cy + spine_half)

    # Read current wire and road positions on spine columns
    wire_rows = [r for r in range(WORLD_H) if wm[r, wire_col]]
    road_rows = [r for r in range(WORLD_H) if rm[r, road_col]]

    # --- Phase 2: Bootstrap wire from plant ---
    if not wire_rows:
        # Connect wire adjacent to plant
        for dy in range(-1, 3):
            nr = plant_cy + dy
            if 0 <= nr < WORLD_H and 0 <= wire_col < WORLD_W:
                if not pm[nr, wire_col]:
                    return (Tool.WIRE, wire_col, nr)
        return None

    min_wr = min(wire_rows)
    max_wr = max(wire_rows)

    # --- Phase 3: Extend wire spine toward target_max ---
    if max_wr < target_max:
        nr = max_wr + 1
        if 0 <= nr < WORLD_H and not pm[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)

    # --- Phase 4: Extend wire spine toward target_min ---
    if min_wr > target_min:
        nr = min_wr - 1
        if 0 <= nr < WORLD_H and not pm[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)

    # --- Phase 5: Build road parallel to wire ---
    for r in range(target_min, target_max + 1):
        if wm[r, wire_col] and not rm[r, road_col] and em[r, road_col]:
            return (Tool.ROAD, road_col, r)

    # --- Helper: check if area around zone center is placeable ---
    def zone_area_clear(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_occupied(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def wire_nearby(zr, zc, r=5):
        r0 = max(0, zr - r); r1 = min(WORLD_H, zr + r + 1)
        c0 = max(0, zc - r); c1 = min(WORLD_W, zc + r + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def road_nearby(zr, zc, r=4):
        r0 = max(0, zr - r); r1 = min(WORLD_H, zr + r + 1)
        c0 = max(0, zc - r); c1 = min(WORLD_W, zc + r + 1)
        return np.any(rm[r0:r1, c0:c1])

    def pick_tool(t):
        if t == 0:
            return Tool.RESIDENTIAL
        rc_ratio = com_count / t if t > 0 else 0
        ri_ratio = ind_count / t if t > 0 else 0
        if rc_ratio < 0.25:
            return Tool.COMMERCIAL
        if ri_ratio < 0.20:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    # Zone rows spaced every 3 rows in the spine range
    zone_rows = list(range(max(2, target_min), min(WORLD_H - 2, target_max + 1), 3))

    # --- Phase 6: Lateral wires from spine to left zone column ---
    for wr in wire_rows:
        if target_min <= wr <= target_max:
            # Check leftward from wire_col-1 to left_zone_col-1
            # Find first gap going left
            for wc in range(wire_col - 1, left_zone_col - 2, -1):
                if not (0 <= wc < WORLD_W):
                    break
                if wm[wr, wc]:
                    break  # already wired here, stop
                if em[wr, wc] and not pm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                else:
                    break  # blocked

    # --- Phase 7: Lateral wires from spine to right zone column ---
    for wr in wire_rows:
        if target_min <= wr <= target_max:
            for wc in range(wire_col + 1, right_zone_col + 3):
                if not (0 <= wc < WORLD_W):
                    break
                if wm[wr, wc] or rm[wr, wc]:
                    break
                if em[wr, wc] and not pm[wr, wc]:
                    return (Tool.WIRE, wc, wr)
                else:
                    break

    # --- Phase 8: Road extensions from road column toward right zone column ---
    for rr in road_rows:
        if target_min <= rr <= target_max:
            for rc in range(road_col + 1, right_zone_col + 3):
                if not (0 <= rc < WORLD_W):
                    break
                if rm[rr, rc]:
                    break
                if em[rr, rc] and not pm[rr, rc]:
                    return (Tool.ROAD, rc, rr)
                else:
                    break

    # --- Phase 9: Place zones where powered and road-served ---
    for zr in zone_rows:
        wire_near_row = any(abs(zr - wr) <= 3 for wr in wire_rows)
        road_near_row = any(abs(zr - rr) <= 3 for rr in road_rows)

        if wire_near_row and road_near_row:
            for zc in [left_zone_col, right_zone_col]:
                if not zone_occupied(zr, zc) and zone_area_clear(zr, zc):
                    if wire_nearby(zr, zc) and road_nearby(zr, zc):
                        return (pick_tool(total_zones), zc, zr)

    # --- Phase 10: Second coal plant when population demands more power ---
    num_plant_tiles = int(np.sum(pm))
    if pop > 200 and num_plant_tiles < 9:
        px2 = plant_cx + 14
        py2 = plant_cy
        px2 = max(2, min(WORLD_W - 3, px2))
        py2 = max(2, min(WORLD_H - 3, py2))
        area_ok = True
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = py2 + dr, px2 + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    area_ok = False
                elif not em[rr, rc] and not pm[rr, rc]:
                    area_ok = False
        if area_ok:
            return (Tool.COALPOWER, px2, py2)

    # --- Phase 11: Connect second plant to wire spine if it exists ---
    if num_plant_tiles >= 9:
        # Find second plant cluster (tiles far from first plant)
        dists = np.sqrt((plant_rows - plant_cy)**2 + (plant_cols - plant_cx)**2)
        far = dists > 8
        if np.any(far):
            p2cy = int(np.mean(plant_rows[far]))
            p2cx = int(np.mean(plant_cols[far]))
            # Wire from second plant to wire_col
            if p2cx > wire_col:
                for wc in range(p2cx - 1, wire_col - 1, -1):
                    if 0 <= wc < WORLD_W and not wm[p2cy, wc] and em[p2cy, wc] and not pm[p2cy, wc]:
                        return (Tool.WIRE, wc, p2cy)
            else:
                for wc in range(p2cx + 1, wire_col + 1):
                    if 0 <= wc < WORLD_W and not wm[p2cy, wc] and em[p2cy, wc] and not pm[p2cy, wc]:
                        return (Tool.WIRE, wc, p2cy)

    # --- Phase 12: Expand outer zone columns when city is growing ---
    if pop > 150:
        for col_offset, base_col in [(-4, left_zone_col), (+4, right_zone_col)]:
            outer_col = max(3, min(WORLD_W - 4, base_col + col_offset))
            for zr in zone_rows:
                if not zone_occupied(zr, outer_col) and zone_area_clear(zr, outer_col):
                    if wire_nearby(zr, outer_col, 7) and road_nearby(zr, outer_col, 6):
                        return (pick_tool(total_zones), outer_col, zr)

    # --- Phase 13: Horizontal roads to connect zones to road spine ---
    if pop > 80:
        for zr in zone_rows:
            if any(abs(zr - wr) <= 1 for wr in wire_rows):
                # Road from left_zone_col to road_col at zone row
                for rc in range(left_zone_col, road_col + 1):
                    if 0 <= rc < WORLD_W and em[zr, rc] and not pm[zr, rc]:
                        return (Tool.ROAD, rc, zr)

    # --- Phase 14: Fill any missing zones along zone columns ---
    for zr in zone_rows:
        for zc in [left_zone_col, right_zone_col, wire_col - 7, road_col + 7]:
            zc = max(3, min(WORLD_W - 4, zc))
            if not zone_occupied(zr, zc) and zone_area_clear(zr, zc):
                if wire_nearby(zr, zc, 8) and road_nearby(zr, zc, 7):
                    return (pick_tool(total_zones), zc, zr)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder.
    Improvements over parent:
    - Better zone placement: ensure 3x3 clearing before placing zones
    - More aggressive road grid with cross-streets every 3 cols
    - Wire runs THROUGH road grid (on alternate tiles) to power more zones
    - Second power plant placed earlier and connected
    - Services placed more strategically
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Central anchor - slightly off-center to give more room
    CX, CY = 58, 48

    # Step 1: Place coal power plant if none exists
    if not np.any(pm):
        return (Tool.COALPOWER, CX, CY)

    # Find plant location
    plant_rows, plant_cols = np.where(pm)
    pcx = int(np.mean(plant_cols))
    pcy = int(np.mean(plant_rows))

    res_count = int(np.sum(resm)) // 9  # approximate zone count
    com_count = int(np.sum(comm)) // 9
    ind_count = int(np.sum(indm)) // 9
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        if ind_count / t < 0.18:
            return Tool.INDUSTRIAL
        if com_count / t < 0.22:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Layout: 
    # Wire spine at row pcy-1 (horizontal) and col pcx (vertical)
    # Road grid: horizontal roads every 4 rows, vertical roads every 4 cols
    # Zones fill the 3x3 blocks between roads
    wire_row = pcy - 1
    road_row_main = pcy + 2

    # Power map: all tiles that have power
    power_map = pm | wm

    # === WIRE EXTENSION ===
    # Horizontal wire at wire_row
    # Vertical wire at pcx from wire_row to road area
    w_extent = min(35, 12 + obs.city_pop // 15)

    wire_targets = []
    # Horizontal wire spine
    for x in range(CX - w_extent, CX + w_extent + 1):
        wire_targets.append((x, wire_row))
    # Vertical wire from plant up and down
    for y in range(CY - 18, CY + 18):
        wire_targets.append((pcx, y))
    # Branch wires to reach road grid rows
    for dx_step in range(-w_extent, w_extent + 1, 4):
        col = CX + dx_step
        for y in range(wire_row - 2, wire_row + 8):
            wire_targets.append((col, y))

    for (wx, wy) in wire_targets:
        if not in_bounds(wx, wy):
            continue
        if bool(wm[wy, wx]) or bool(pm[wy, wx]):
            continue
        # Don't wire over roads (we want roads separate)
        if bool(rm[wy, wx]):
            continue
        if not bool(em[wy, wx]):
            continue
        # Only place if adjacent to existing power
        for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = wx + ddx, wy + ddy
            if in_bounds(nx, ny) and bool(power_map[ny, nx]):
                return (Tool.WIRE, wx, wy)

    # === ROAD EXTENSION ===
    r_extent = min(30, 10 + obs.city_pop // 12)

    road_targets = []
    # Main horizontal road
    for x in range(CX - r_extent, CX + r_extent + 1):
        road_targets.append((x, road_row_main))
    # Additional horizontal roads every 4 rows above and below
    for dy_off in range(-16, 17, 4):
        ry = road_row_main + dy_off
        if ry == wire_row:
            continue
        for x in range(CX - r_extent, CX + r_extent + 1):
            road_targets.append((x, ry))
    # Vertical roads (cross-streets) every 4 cols
    for dx_off in range(-r_extent, r_extent + 1, 4):
        cx2 = CX + dx_off
        for y in range(road_row_main - 16, road_row_main + 17):
            if y == wire_row:
                continue
            road_targets.append((cx2, y))

    for (rx, ry) in road_targets:
        if not in_bounds(rx, ry):
            continue
        if bool(rm[ry, rx]) or bool(pm[ry, rx]):
            continue
        if bool(wm[ry, rx]):
            continue
        if not bool(em[ry, rx]):
            continue
        # Place if adjacent to existing road or near plant
        adj_road = False
        for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = rx + ddx, ry + ddy
            if in_bounds(nx, ny) and bool(rm[ny, nx]):
                adj_road = True
                break
        adj_plant = False
        for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1),
                         (2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx, ny = rx + ddx, ry + ddy
            if in_bounds(nx, ny) and bool(pm[ny, nx]):
                adj_plant = True
                break
        if adj_road or adj_plant:
            return (Tool.ROAD, rx, ry)

    # === ZONE PLACEMENT ===
    # Build neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_mask_all = resm | comm | indm
    cand = em & nbr_road & nbr_power
    # Exclude map edges (need 3x3)
    cand[0:2, :] = False
    cand[WORLD_H - 2:, :] = False
    cand[:, 0:2] = False
    cand[:, WORLD_W - 2:] = False
    # Don't place on wire or road rows
    cand[wire_row, :] = False

    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        # Prefer candidates closer to center
        dists = np.abs(cxs - CX) + np.abs(cys - CY)
        order = np.argsort(dists)

        key = int(obs.step * 17 + int(obs.city_pop * 3) + 1) % max(len(order), 1)
        # Try candidates sorted by distance, with some randomness
        tried = 0
        for i in range(len(order)):
            idx = order[(key + i * 7) % len(order)]
            zx, zy = int(cxs[idx]), int(cys[idx])
            # Check 3x3 area is clear (empty or already zone - allow overwrite of zones only if empty)
            ok = True
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    ny2, nx2 = zy + dr, zx + dc
                    if not in_bounds(nx2, ny2):
                        ok = False
                        break
                    tile = tm[ny2, nx2]
                    # Must be empty or already a zone tile (no roads/wires/plants)
                    if not (bool(em[ny2, nx2]) or bool(zone_mask_all[ny2, nx2])):
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                return (pick_tool(), zx, zy)
            tried += 1
            if tried > 80:
                break

    # === SECOND POWER PLANT ===
    # Place earlier (pop > 150) and connect it via wire
    n_plant_tiles = int(np.sum(pm))
    if obs.city_pop > 150 and n_plant_tiles < 9:
        p2x = pcx + 22
        p2y = pcy
        p2x = max(2, min(WORLD_W - 3, p2x))
        p2y = max(2, min(WORLD_H - 3, p2y))
        if bool(em[p2y, p2x]):
            return (Tool.COALPOWER, p2x, p2y)

    if obs.city_pop > 400 and n_plant_tiles < 18:
        p3x = pcx - 22
        p3y = pcy
        p3x = max(2, min(WORLD_W - 3, p3x))
        p3y = max(2, min(WORLD_H - 3, p3y))
        if bool(em[p3y, p3x]):
            return (Tool.COALPOWER, p3x, p3y)

    # === SERVICES ===
    if obs.city_pop > 150:
        for fx, fy in [(CX + 8, CY - 10), (CX - 8, CY + 10),
                       (CX + 8, CY + 10), (CX - 8, CY - 10)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 300:
        for fx, fy in [(CX + 12, CY - 8), (CX - 12, CY + 8)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.POLICESTATION, fx, fy)

    # === FALLBACK: extend wire from frontier ===
    wys2, wxs2 = np.where(wm)
    if len(wxs2) > 0:
        k3 = int(obs.step * 7) % len(wxs2)
        wx2, wy2 = int(wxs2[k3]), int(wys2[k3])
        for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = wx2 + ddx, wy2 + ddy
            if in_bounds(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                return (Tool.WIRE, nx, ny)

    # === FALLBACK: extend road from frontier ===
    rys2, rxs2 = np.where(rm)
    if len(rxs2) > 0:
        k2 = int(obs.step * 11) % len(rxs2)
        rx2, ry2 = int(rxs2[k2]), int(rys2[k2])
        for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = rx2 + ddx, ry2 + ddy
            if in_bounds(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                return (Tool.ROAD, nx, ny)

    return None

def act(obs, state):
    """
    Hybrid policy combining Parent A's reactive closed-loop approach with
    Parent B's structured base plan. Key improvements:
    - Start with a compact, well-connected base plan
    - Then switch to reactive placement for zones/roads/wires
    - Better power coverage with wires along roads
    - Mix of R/C/I zones for balanced growth
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    CX, CY = 60, 50  # center anchor

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Build a structured base plan once
    if "plan" not in state:
        p = []
        cx, cy = CX, CY

        # 1. Coal power plant
        p.append((Tool.COALPOWER, cx, cy))

        # 2. Wire spine: vertical through plant center
        for dy in range(-15, 16):
            p.append((Tool.WIRE, cx, cy + dy))

        # 3. Horizontal wire arms at key rows
        for arm_dy in [-6, 6, -12, 12]:
            for dx in range(-12, 13):
                p.append((Tool.WIRE, cx + dx, cy + arm_dy))

        # 4. Road grid: horizontal roads offset from plant
        for row_dy in [-4, -8, -12, 4, 8, 12]:
            for dx in range(-14, 15):
                p.append((Tool.ROAD, cx + dx, cy + row_dy))

        # 5. Vertical roads
        for col_dx in [-4, 4, -8, 8, -12, 12]:
            for dy in range(-13, 14):
                p.append((Tool.ROAD, cx + col_dx, cy + dy))

        # 6. Seed zones in pockets between roads
        # R zones
        for row_dy in [-6, 6, -10, 10]:
            for col_dx in [-6, 6, -10, 10, -2, 2]:
                p.append((Tool.RESIDENTIAL, cx + col_dx, cy + row_dy))

        # I zones (inner)
        for col_dx in [-6, 6]:
            for row_dy in [-2, 2]:
                p.append((Tool.INDUSTRIAL, cx + col_dx, cy + row_dy))

        # C zones
        for col_dx in [-2, 2]:
            for row_dy in [-6, 6, -10, 10]:
                p.append((Tool.COMMERCIAL, cx + col_dx, cy + row_dy))

        # Fire station
        p.append((Tool.FIRESTATION, cx + 14, cy))
        p.append((Tool.FIRESTATION, cx - 14, cy))

        # Police station
        p.append((Tool.POLICESTATION, cx, cy + 14))
        p.append((Tool.POLICESTATION, cx, cy - 14))

        state["plan"] = p
        state["plan_idx"] = 0

    # Phase 1: Execute base plan
    if state["plan_idx"] < len(state["plan"]):
        idx = state["plan_idx"]
        action = state["plan"][idx]
        state["plan_idx"] += 1
        tool, ax, ay = action
        if in_bounds(ax, ay):
            return action
        else:
            state["plan_idx"] = len(state["plan"])  # skip rest if OOB

    # Phase 2: Reactive closed-loop
    plant_ys, plant_xs = np.where(pm)
    if len(plant_xs) == 0:
        return (Tool.COALPOWER, CX, CY)

    px = int(plant_xs[0])
    py = int(plant_ys[0])
    power_map = pm | wm

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    pop = obs.city_pop

    def pick_tool():
        r_frac = res_count / total_zones
        c_frac = com_count / total_zones
        i_frac = ind_count / total_zones
        if i_frac < 0.18:
            return Tool.INDUSTRIAL
        if c_frac < 0.22:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Road influence (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            if abs(dy) + abs(dx) <= 2:
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Power influence (within 5 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_mask = resm | comm | indm

    def find_zone():
        cand = em & nbr_road & nbr_power
        cand[:3, :] = False; cand[WORLD_H-3:, :] = False
        cand[:, :3] = False; cand[:, WORLD_W-3:] = False
        cys, cxs = np.where(cand)
        if len(cxs) == 0:
            return None
        dists = np.abs(cxs.astype(np.int32) - px) + np.abs(cys.astype(np.int32) - py)
        order = np.argsort(dists)
        tool = pick_tool()
        for i in range(min(len(cxs), 200)):
            k = order[i]
            zx, zy = int(cxs[k]), int(cys[k])
            ok = True
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    ny2, nx2 = zy + dr, zx + dc
                    if not in_bounds(nx2, ny2):
                        ok = False; break
                    if not (bool(em[ny2, nx2]) or bool(zone_mask[ny2, nx2])):
                        ok = False; break
                if not ok:
                    break
            if ok:
                return (tool, zx, zy)
        return None

    def find_wire_extension():
        # Extend wire grid
        targets = []
        for dy in range(-16, 17):
            targets.append((px, py + dy))
        for arm_dy in [0, -6, 6, -12, 12]:
            for dx in range(-16, 17):
                targets.append((px + dx, py + arm_dy))
        for (wx, wy) in targets:
            if not in_bounds(wx, wy): continue
            if bool(wm[wy, wx]) or bool(pm[wy, wx]): continue
            if bool(rm[wy, wx]): continue
            if not bool(em[wy, wx]): continue
            for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx2, ny2 = wx+ddx, wy+ddy
                if in_bounds(nx2, ny2) and bool(power_map[ny2, nx2]):
                    return (Tool.WIRE, wx, wy)
        return None

    def find_road_extension():
        candidates = []
        for row_off in range(-14, 15, 4):
            ry = py + row_off
            for dx in range(-16, 17):
                candidates.append((px + dx, ry))
        for col_off in range(-14, 15, 4):
            rx = px + col_off
            for dy in range(-14, 15):
                candidates.append((rx, py + dy))
        for (rx, ry) in candidates:
            if not in_bounds(rx, ry): continue
            if bool(rm[ry, rx]): continue
            if bool(pm[ry, rx]) or bool(wm[ry, rx]): continue
            if not bool(em[ry, rx]): continue
            for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx2, ny2 = rx+ddx, ry+ddy
                if in_bounds(nx2, ny2) and bool(rm[ny2, nx2]):
                    return (Tool.ROAD, rx, ry)
            for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1),(2,0),(-2,0),(0,2),(0,-2)]:
                nx2, ny2 = rx+ddx, ry+ddy
                if in_bounds(nx2, ny2) and bool(pm[ny2, nx2]):
                    return (Tool.ROAD, rx, ry)
        return None

    wire_action = find_wire_extension()
    road_action = find_road_extension()
    zone_action = find_zone()

    step_mod = obs.step % 8

    # Second power plant when population is high
    if pop > 800 and len(plant_xs) < 2:
        for fx, fy in [(px+20, py), (px-20, py), (px, py+20), (px, py-20)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.COALPOWER, fx, fy)

    # Services reactively
    if pop > 200 and step_mod == 7:
        for fx, fy in [(px+10, py-10), (px-10, py+10), (px+16, py+8), (px-16, py-8)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.FIRESTATION, fx, fy)

    if pop > 400 and step_mod == 6:
        for fx, fy in [(px+10, py+10), (px-10, py-10), (px+16, py-8), (px-16, py+8)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.POLICESTATION, fx, fy)

    # Main interleaving logic
    wire_count = int(np.sum(wm))
    road_count = int(np.sum(rm))

    if wire_count < 30 and wire_action is not None:
        return wire_action
    if road_count < 20 and road_action is not None:
        return road_action

    if pop < 200:
        if step_mod in (0, 1) and wire_action is not None:
            return wire_action
        if step_mod in (2, 3, 4) and road_action is not None:
            return road_action
        if zone_action is not None:
            return zone_action
        if road_action is not None:
            return road_action
        if wire_action is not None:
            return wire_action
    elif pop < 600:
        if step_mod == 0 and wire_action is not None:
            return wire_action
        if step_mod in (1, 2) and road_action is not None:
            return road_action
        if zone_action is not None:
            return zone_action
        if road_action is not None:
            return road_action
        if wire_action is not None:
            return wire_action
    else:
        if step_mod == 0 and wire_action is not None:
            return wire_action
        if step_mod == 1 and road_action is not None:
            return road_action
        if zone_action is not None:
            return zone_action
        if road_action is not None:
            return road_action
        if wire_action is not None:
            return wire_action

    # Fallback: extend road from any road tile
    rys2, rxs2 = np.where(rm)
    if len(rxs2) > 0:
        k2 = int(obs.step * 17 + pop) % len(rxs2)
        rx2, ry2 = int(rxs2[k2]), int(rys2[k2])
        for ddx, ddy in [(0,1),(1,0),(0,-1),(-1,0)]:
            nx2, ny2 = rx2+ddx, ry2+ddy
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and not bool(wm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop policy: reads tile_map each step and places next tile
    based on what already exists. Uses a small phase counter in state.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # --- Helper: check if 3x3 zone area is fully empty ---
    def zone_clear(cx, cy):
        for dy in range(-1, 2):
            for dx in range(-1, 2):
                r, c = cy + dy, cx + dx
                if r < 0 or r >= WORLD_H or c < 0 or c >= WORLD_W:
                    return False
                if not em[r, c]:
                    return False
        return True

    # --- Helper: count neighbors of type mask ---
    def count_neighbors(mask, y, x, dist=2):
        y0, y1 = max(0, y - dist), min(WORLD_H, y + dist + 1)
        x0, x1 = max(0, x - dist), min(WORLD_W, x + dist + 1)
        return np.sum(mask[y0:y1, x0:x1])

    # City layout constants
    # Primary cluster: center at (60, 50)
    # Coal plant at (45, 50), second coal at (75, 50)
    # Wire spine: horizontal at y=50 from x=43 to x=77
    # Road spine: horizontal at y=52 from same range
    # Zones above (y=47, y=44) and below (y=55, y=58)

    PLANT1 = (45, 50)  # (x, y)
    PLANT2 = (75, 50)
    WIRE_Y = 50
    ROAD_Y = 52
    WIRE_X_START = 43
    WIRE_X_END = 77
    ZONE_YS_ABOVE = [47, 44, 41]
    ZONE_YS_BELOW = [55, 58, 61]
    ZONE_XS = list(range(46, 76, 6))  # x=46,52,58,64,70,76

    # Check plant existence
    def has_plant(px, py):
        r0, r1 = max(0, py - 1), min(WORLD_H, py + 2)
        c0, c1 = max(0, px - 1), min(WORLD_W, px + 2)
        return np.any(pm[r0:r1, c0:c1])

    plant1_exists = has_plant(*PLANT1)
    plant2_exists = has_plant(*PLANT2)

    # --- PHASE 1: Place plant 1 if missing ---
    if not plant1_exists:
        return (Tool.COALPOWER, PLANT1[0], PLANT1[1])

    # --- PHASE 2: Extend horizontal wire spine ---
    # Wire runs at WIRE_Y from WIRE_X_START to WIRE_X_END
    # Find current wire extent in that row
    wire_in_row = np.where(wm[WIRE_Y, :])[0]
    if len(wire_in_row) == 0:
        # Start wire adjacent to plant
        return (Tool.WIRE, PLANT1[0] + 2, WIRE_Y)

    min_wx = int(wire_in_row.min())
    max_wx = int(wire_in_row.max())

    # Extend right
    if max_wx < WIRE_X_END:
        nx = max_wx + 1
        if nx < WORLD_W and em[WIRE_Y, nx]:
            return (Tool.WIRE, nx, WIRE_Y)
        elif nx < WORLD_W and not wm[WIRE_Y, nx]:
            return (Tool.WIRE, nx, WIRE_Y)  # bulldoze if needed

    # Extend left
    if min_wx > WIRE_X_START:
        nx = min_wx - 1
        if nx >= 0 and em[WIRE_Y, nx]:
            return (Tool.WIRE, nx, WIRE_Y)

    # --- PHASE 3: Build road spine ---
    road_in_row = np.where(rm[ROAD_Y, :])[0]
    road_set = set(int(c) for c in road_in_row)

    # Road should cover same x range as wire
    for x in range(WIRE_X_START, WIRE_X_END + 1):
        if x not in road_set and em[ROAD_Y, x]:
            return (Tool.ROAD, x, ROAD_Y)

    # --- PHASE 4: Connect wire to road with vertical wires ---
    # Wire at WIRE_Y, road at ROAD_Y=52, need vertical wire at WIRE_Y+1=51
    for x in range(WIRE_X_START, WIRE_X_END + 1):
        if wm[WIRE_Y, x] and rm[ROAD_Y, x]:
            # Connect vertically if gap
            for vy in range(WIRE_Y + 1, ROAD_Y):
                if not wm[vy, x] and em[vy, x]:
                    return (Tool.WIRE, x, vy)

    # --- PHASE 5: Place vertical wires to zone rows ---
    # For each zone column, extend wire up and down from spine
    wire_set = set(int(c) for c in wire_in_row)
    all_zone_ys = ZONE_YS_ABOVE + ZONE_YS_BELOW

    for zx in ZONE_XS:
        if zx not in wire_set:
            continue
        # Wire upward to top zone rows
        for zy in ZONE_YS_ABOVE:
            # Check if wire reaches this y at this x
            if not wm[zy, zx]:
                # Find lowest missing wire going up from WIRE_Y
                for vy in range(WIRE_Y - 1, zy - 1, -1):
                    if not wm[vy, zx] and em[vy, zx]:
                        return (Tool.WIRE, zx, vy)
                    elif not wm[vy, zx]:
                        break
        # Wire downward
        for zy in ZONE_YS_BELOW:
            if not wm[zy, zx]:
                for vy in range(ROAD_Y + 1, zy + 1):
                    if not wm[vy, zx] and em[vy, zx]:
                        return (Tool.WIRE, zx, vy)
                    elif not wm[vy, zx]:
                        break

    # --- PHASE 6: Place road connections to zones ---
    # Vertical roads at zone columns connecting to ROAD_Y
    for zx in ZONE_XS:
        if zx not in road_set:
            continue
        for zy in ZONE_YS_ABOVE:
            # Road one tile from zone center toward road spine
            road_bridge_y = zy + 2  # just below zone
            for ry in range(ROAD_Y - 1, road_bridge_y - 1, -1):
                if not rm[ry, zx] and em[ry, zx]:
                    return (Tool.ROAD, zx, ry)
                elif not rm[ry, zx]:
                    break
        for zy in ZONE_YS_BELOW:
            road_bridge_y = zy - 2
            for ry in range(ROAD_Y + 1, road_bridge_y + 1):
                if not rm[ry, zx] and em[ry, zx]:
                    return (Tool.ROAD, zx, ry)
                elif not rm[ry, zx]:
                    break

    # --- PHASE 7: Place zones ---
    res_count = int(np.sum(res_m))
    com_count = int(np.sum(com_m))
    ind_count = int(np.sum(ind_m))
    total_zones = res_count + com_count + ind_count

    def pick_zone():
        # Target 3 res : 2 com : 1 ind
        if total_zones == 0:
            return Tool.RESIDENTIAL
        r = res_count / max(1, total_zones)
        c = com_count / max(1, total_zones)
        i = ind_count / max(1, total_zones)
        if r < 0.45:
            return Tool.RESIDENTIAL
        elif i < 0.20:
            return Tool.INDUSTRIAL
        elif c < 0.30:
            return Tool.COMMERCIAL
        else:
            return Tool.RESIDENTIAL

    # Try placing zones at each zone position (prioritize powered+road-adjacent)
    any_zone_m = res_m | com_m | ind_m

    for zy in ZONE_YS_ABOVE + ZONE_YS_BELOW:
        for zx in ZONE_XS:
            # Must be in wire coverage
            if not wm[zy, zx]:
                continue
            # Must have road nearby (within 3 tiles)
            road_nearby = np.any(rm[max(0, zy - 3):min(WORLD_H, zy + 4),
                                     max(0, zx - 3):min(WORLD_W, zx + 4)])
            if not road_nearby:
                continue
            # Must be empty 3x3
            if zone_clear(zx, zy):
                # Check not already a zone nearby
                zone_nearby = np.any(any_zone_m[max(0, zy - 3):min(WORLD_H, zy + 4),
                                                 max(0, zx - 3):min(WORLD_W, zx + 4)])
                if not zone_nearby:
                    return (pick_zone(), zx, zy)

    # --- PHASE 8: Place second plant when pop warrants ---
    if obs.city_pop >= 100 and not plant2_exists:
        return (Tool.COALPOWER, PLANT2[0], PLANT2[1])

    # Extend wire and road to plant2 area
    if plant2_exists:
        # Connect plant2 to wire spine
        wire_in_row2 = np.where(wm[WIRE_Y, :])[0]
        if len(wire_in_row2) > 0:
            max_wx2 = int(wire_in_row2.max())
            if max_wx2 < PLANT2[0] - 2:
                nx = max_wx2 + 1
                if nx < WORLD_W and em[WIRE_Y, nx]:
                    return (Tool.WIRE, nx, WIRE_Y)

    # --- PHASE 9: Police/Fire stations for city services ---
    if obs.city_pop >= 200:
        # Place fire station
        fs_x, fs_y = 60, 65
        if em[fs_y, fs_x] and not np.any(any_zone_m[fs_y - 1:fs_y + 2, fs_x - 1:fs_x + 2]):
            return (Tool.FIRESTATION, fs_x, fs_y)

    if obs.city_pop >= 300:
        ps_x, ps_y = 60, 37
        if em[ps_y, ps_x] and not np.any(any_zone_m[ps_y - 1:ps_y + 2, ps_x - 1:ps_x + 2]):
            return (Tool.POLICESTATION, ps_x, ps_y)

    # --- PHASE 10: Reactive expansion - find empty tiles near roads+wires ---
    # Look for additional zone spots near existing infrastructure
    # Build neighbor maps
    road_nbr = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    wire_nbr = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1),
                   (-2, 0), (2, 0), (0, -2), (0, 2),
                   (-3, 0), (3, 0), (0, -3), (0, 3)]:
        sy = slice(max(0, -dy), min(WORLD_H, WORLD_H - dy))
        sx = slice(max(0, -dx), min(WORLD_W, WORLD_W - dx))
        ty = slice(max(0, dy), min(WORLD_H, WORLD_H + dy))
        tx = slice(max(0, dx), min(WORLD_W, WORLD_W + dx))
        road_nbr[ty, tx] |= rm[sy, sx]
        wire_nbr[ty, tx] |= wm[sy, sx]

    # Candidates: empty, near road, near wire
    cand = em & road_nbr & wire_nbr
    # Avoid edges
    cand[:2, :] = False
    cand[-2:, :] = False
    cand[:, :2] = False
    cand[:, -2:] = False

    ys, xs = np.where(cand)
    if len(xs) == 0:
        return None

    # Pick candidate that doesn't overlap existing zones
    step_seed = obs.step
    for attempt in range(min(20, len(xs))):
        k = (step_seed * 7 + attempt * 13) % len(xs)
        x, y = int(xs[k]), int(ys[k])
        if zone_clear(x, y):
            zone_nb = np.any(any_zone_m[max(0, y - 3):min(WORLD_H, y + 4),
                                         max(0, x - 3):min(WORLD_W, x + 4)])
            if not zone_nb:
                return (pick_zone(), x, y)

    # Last resort: extend road along spine
    for x in range(WIRE_X_START - 5, WIRE_X_END + 6):
        if 0 <= x < WORLD_W and em[ROAD_Y, x]:
            if x < WIRE_X_START or x > WIRE_X_END:
                return (Tool.ROAD, x, ROAD_Y)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Reads tile_map each step to find where power/roads reach
    - Grows infrastructure organically from existing tiles
    - Places zones adjacent to powered+roaded areas
    - Adapts zone mix and expansion based on current population
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2
    pop = obs.city_pop

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Dynamic expansion radius based on population
    if pop < 50:
        x_half = 10
    elif pop < 200:
        x_half = 20
    elif pop < 500:
        x_half = 35
    elif pop < 1000:
        x_half = 50
    else:
        x_half = 58

    x_min = max(3, cx - x_half)
    x_max = min(WORLD_W - 4, cx + x_half)

    # Wire spine and road rows - relative to center
    wire_row = cy
    road_above = cy - 4
    road_below = cy + 4

    # --- Phase 1: Place first coal power plant if none exists ---
    if not np.any(pm):
        px = max(4, cx - x_half - 3)
        py = wire_row
        return (Tool.COALPOWER, px, py)

    # Locate plant
    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # --- Phase 2: Grow wire spine reactively from existing wire ---
    wire_ys, wire_xs = np.where(wm)

    if len(wire_xs) == 0:
        # No wire yet - start adjacent to plant
        for dc in range(1, 8):
            c = plant_cx + dc
            if in_bounds(c, wire_row) and em[wire_row, c] and not pm[wire_row, c]:
                return (Tool.WIRE, c, wire_row)
        return None

    # Find wire extent on wire_row
    wire_on_row = [c for c in range(WORLD_W) if in_bounds(c, wire_row) and wm[wire_row, c]]

    if wire_on_row:
        min_wc = min(wire_on_row)
        max_wc = max(wire_on_row)

        # Extend wire right toward x_max
        if max_wc < x_max:
            nc = max_wc + 1
            if in_bounds(nc, wire_row) and em[wire_row, nc] and not pm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

        # Extend wire left toward x_min
        if min_wc > x_min:
            nc = min_wc - 1
            if in_bounds(nc, wire_row) and em[wire_row, nc] and not pm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)
    else:
        # Wire exists elsewhere - bridge to wire_row from nearest wire tile
        # Find wire tile closest to wire_row in x range
        valid = [(wire_xs[i], wire_ys[i]) for i in range(len(wire_xs))
                 if x_min <= wire_xs[i] <= x_max]
        if valid:
            # Pick one closest to wire_row
            valid.sort(key=lambda p: abs(p[1] - wire_row))
            wx0, wy0 = valid[0]
            # Move vertically toward wire_row
            step = 1 if wire_row > wy0 else -1
            ny = wy0 + step
            if in_bounds(wx0, ny) and em[ny, wx0] and not pm[ny, wx0]:
                return (Tool.WIRE, wx0, ny)

    # --- Phase 3: Ensure plant is connected to wire ---
    # Check if any plant tile is adjacent to wire
    plant_connected = False
    for pr, pc in zip(plant_rows, plant_cols):
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = pr+dr, pc+dc
            if in_bounds(nc, nr) and wm[nr, nc]:
                plant_connected = True
                break
        if plant_connected:
            break

    if not plant_connected and wire_on_row:
        min_wc = min(wire_on_row)
        # Bridge wire from plant_cx to wire spine
        for bc in range(plant_cx + 1, min_wc + 1):
            if in_bounds(bc, wire_row) and wm[wire_row, bc]:
                break
            if in_bounds(bc, wire_row) and em[wire_row, bc] and not pm[wire_row, bc]:
                return (Tool.WIRE, bc, wire_row)

    # --- Phase 4: Build roads reactively along wire coverage ---
    # For each wire tile on spine, build road above and below
    if wire_on_row:
        for wc in sorted(wire_on_row):
            if x_min <= wc <= x_max:
                # Road above
                if in_bounds(wc, road_above) and em[road_above, wc] and not pm[road_above, wc]:
                    return (Tool.ROAD, wc, road_above)
                # Road below
                if in_bounds(wc, road_below) and em[road_below, wc] and not pm[road_below, wc]:
                    return (Tool.ROAD, wc, road_below)

    # --- Phase 5: Vertical connector roads ---
    if wire_on_row:
        for wc in range(x_min, x_max + 1, 8):
            if wc in wire_on_row:
                for wr2 in range(road_above, road_below + 1):
                    if in_bounds(wc, wr2) and em[wr2, wc] and not pm[wr2, wc] and not wm[wr2, wc] and not rm[wr2, wc]:
                        return (Tool.ROAD, wc, wr2)

    # --- Compute neighbor masks for road and wire coverage ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # --- Determine zone tool based on reactive population ratios ---
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        t = max(total_zones, 1)
        # Reactive: watch powered_zones ratio
        # Target: 45% res, 30% com, 25% ind
        if ind_count / t < 0.22:
            return Tool.INDUSTRIAL
        if com_count / t < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_area_ok(zy, zx):
        if zy < 1 or zy > WORLD_H - 2 or zx < 1 or zx > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr2, rc2 = zy + dr, zx + dc
                if not (0 <= rr2 < WORLD_H and 0 <= rc2 < WORLD_W):
                    return False
                if not (em[rr2, rc2] or resm[rr2, rc2] or comm[rr2, rc2] or indm[rr2, rc2]):
                    return False
        return True

    # --- Phase 6: Place zones reactively near roads + wire ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, :2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys_a, cxs_a = np.where(cand_mask)
    if len(cxs_a) > 0:
        # Sort by closeness to center, weighted toward spreading left-right
        dists = np.abs(cxs_a.astype(int) - cx) + np.abs(cys_a.astype(int) - wire_row) * 3
        sort_idx = np.argsort(dists)
        placed = False
        for k_idx in range(min(len(cxs_a), 150)):
            k = int(sort_idx[k_idx])
            zx, zy = int(cxs_a[k]), int(cys_a[k])
            if x_min <= zx <= x_max and zone_area_ok(zy, zx):
                return (pick_tool(), zx, zy)

    # --- Phase 7: Add more power plants reactively ---
    plant_tiles = int(np.sum(pm))
    plant_count = max(1, plant_tiles // 6)

    wire_on_row_list = sorted([c for c in range(WORLD_W) if in_bounds(c, wire_row) and wm[wire_row, c]])
    max_wc2 = wire_on_row_list[-1] if wire_on_row_list else plant_cx
    min_wc2 = wire_on_row_list[0] if wire_on_row_list else plant_cx

    if pop > 100 and plant_count < 2:
        # Place second plant on right side of wire spine
        p2x = min(WORLD_W - 5, max_wc2 + 4)
        p2y = wire_row
        if in_bounds(p2x, p2y) and em[p2y, p2x]:
            nearby = any(
                in_bounds(p2x+dx2, p2y+dy2) and pm[p2y+dy2, p2x+dx2]
                for dy2 in range(-7, 8) for dx2 in range(-7, 8)
            )
            if not nearby:
                return (Tool.COALPOWER, p2x, p2y)
        # If plant location blocked, extend wire to reach it
        if max_wc2 < p2x - 3:
            nc = max_wc2 + 1
            if in_bounds(nc, wire_row) and em[wire_row, nc] and not pm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    if pop > 400 and plant_count < 3:
        # Third plant below center
        p3x = cx
        p3y = min(WORLD_H - 5, cy + 20)
        if in_bounds(p3x, p3y) and em[p3y, p3x]:
            nearby = any(
                in_bounds(p3x+dx2, p3y+dy2) and pm[p3y+dy2, p3x+dx2]
                for dy2 in range(-7, 8) for dx2 in range(-7, 8)
            )
            if not nearby:
                return (Tool.COALPOWER, p3x, p3y)

    if pop > 800 and plant_count < 4:
        p4x = cx - 25
        p4y = cy
        if in_bounds(p4x, p4y) and em[p4y, p4x]:
            nearby = any(
                in_bounds(p4x+dx2, p4y+dy2) and pm[p4y+dy2, p4x+dx2]
                for dy2 in range(-8, 9) for dx2 in range(-8, 9)
            )
            if not nearby:
                return (Tool.COALPOWER, p4x, p4y)

    # --- Phase 8: Extend wire to reach unpowered zones ---
    # Find zones that are not near wire - extend wire toward them
    zone_mask = resm | comm | indm
    unpowered_zones = zone_mask & ~nbr_wire
    uz_ys, uz_xs = np.where(unpowered_zones)
    if len(uz_xs) > 0:
        # Pick the closest unpowered zone to existing wire
        best_dist = 9999
        best_target = None
        for i in range(min(len(uz_xs), 20)):
            zx2, zy2 = int(uz_xs[i]), int(uz_ys[i])
            for wy_i, wx_i in zip(wire_ys[:100], wire_xs[:100]):
                d = abs(zx2 - wx_i) + abs(zy2 - wy_i)
                if d < best_dist:
                    best_dist = d
                    best_target = (zx2, zy2, int(wx_i), int(wy_i))
        if best_target:
            tzx, tzy, swx, swy = best_target
            # Move wire one step toward target
            dx_step = np.sign(tzx - swx)
            dy_step = np.sign(tzy - swy)
            # Prefer horizontal movement
            nx, ny = swx + dx_step, swy
            if dx_step == 0:
                nx, ny = swx, swy + dy_step
            if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx] and not wm[ny, nx]:
                return (Tool.WIRE, nx, ny)
            # Try vertical
            nx, ny = swx, swy + dy_step
            if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx] and not wm[ny, nx]:
                return (Tool.WIRE, nx, ny)

    # --- Phase 9: Second wire row for larger city ---
    if pop > 300:
        wire2_row = cy + 12
        wire_on_row2 = [c for c in range(WORLD_W) if in_bounds(c, wire2_row) and wm[wire2_row, c]]
        wire_on_row_cur = [c for c in range(WORLD_W) if in_bounds(c, wire_row) and wm[wire_row, c]]
        if wire_on_row_cur:
            max_wc_cur = max(wire_on_row_cur)
            min_wc_cur = min(wire_on_row_cur)
            target_wc2 = max_wc_cur
            if not wire_on_row2:
                # Start second wire row at cx
                if in_bounds(cx, wire2_row) and em[wire2_row, cx]:
                    return (Tool.WIRE, cx, wire2_row)
            else:
                max_wc2_row = max(wire_on_row2)
                min_wc2_row = min(wire_on_row2)
                if max_wc2_row < target_wc_cur if (wire_on_row_cur := [c for c in range(WORLD_W) if in_bounds(c, wire_row) and wm[wire_row, c]]) else False:
                    nc = max_wc2_row + 1
                    if in_bounds(nc, wire2_row) and em[wire2_row, nc] and not pm[wire2_row, nc]:
                        return (Tool.WIRE, nc, wire2_row)
                if min_wc2_row > min_wc_cur:
                    nc = min_wc2_row - 1
                    if in_bounds(nc, wire2_row) and em[wire2_row, nc] and not pm[wire2_row, nc]:
                        return (Tool.WIRE, nc, wire2_row)
            # Connect wire rows vertically
            for wc in range(x_min, x_max + 1, 12):
                if wm[wire_row, wc]:
                    for wr3 in range(wire_row + 1, wire2_row + 1):
                        if in_bounds(wc, wr3) and em[wr3, wc] and not pm[wr3, wc] and not wm[wr3, wc]:
                            return (Tool.WIRE, wc, wr3)
            # Road along second wire row
            for wc in (wire_on_row2[:60] if wire_on_row2 else []):
                rb = wire2_row - 4
                if in_bounds(wc, rb) and em[rb, wc] and not pm[rb, wc]:
                    return (Tool.ROAD, wc, rb)

    # --- Phase 10: Services reactively ---
    if pop > 150:
        fx, fy = cx, cy - 14
        if in_bounds(fx, fy) and em[fy, fx] and nbr_road[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
    if pop > 300:
        ppx, ppy = cx + 15, cy + 14
        if in_bounds(ppx, ppy) and em[ppy, ppx] and nbr_road[ppy, ppx]:
            return (Tool.POLICESTATION, ppx, ppy)
    if pop > 600:
        fx2, fy2 = cx - 15, cy + 14
        if in_bounds(fx2, fy2) and em[fy2, fx2] and nbr_road[fy2, fx2]:
            return (Tool.FIRESTATION, fx2, fy2)

    # --- Phase 11: Reactively extend road from existing road tiles ---
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = int(obs.step * 17) % len(road_xs_arr)
        rx_s = int(road_xs_arr[step_k])
        ry_s = int(road_ys_arr[step_k])
        for dy2, dx2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx2, ny2 = rx_s + dx2, ry_s + dy2
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                if nbr_wire[ny2, nx2] and x_min <= nx2 <= x_max:
                    return (Tool.ROAD, nx2, ny2)

    # --- Phase 12: Reactively extend wire from existing wire ---
    if len(wire_xs) > 0:
        step_k = int(obs.step * 11) % len(wire_xs)
        wx_s = int(wire_xs[step_k])
        wy_s = int(wire_ys[step_k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = wx_s + dx2, wy_s + dy2
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                if x_min <= nx2 <= x_max and abs(ny2 - wire_row) < 20:
                    return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Hybrid policy v3:
    - Two power plants (primary at 45,50; secondary at 75,50)
    - Vertical wire spine per corridor
    - Bilateral road columns adjacent to wire
    - Zones placed on both sides, 4 and 7 tiles from wire spine
    - Lateral wires connecting spine to left zone columns
    - Lateral roads connecting spine to right zone columns
    - Progressive expansion based on population
    - Services when population warrants
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Two power plant anchor positions
    P1X, P1Y = 45, 50
    P2X, P2Y = 75, 50

    plant_ys, plant_xs = np.where(pm)
    has_plant1 = False
    has_plant2 = False
    for py_, px_ in zip(plant_ys.tolist(), plant_xs.tolist()):
        if abs(px_ - P1X) <= 5 and abs(py_ - P1Y) <= 5:
            has_plant1 = True
        if abs(px_ - P2X) <= 5 and abs(py_ - P2Y) <= 5:
            has_plant2 = True

    # Phase 1: place primary power plant
    if not has_plant1:
        return (Tool.COALPOWER, P1X, P1Y)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_zone(zr):
        # ~50% RES, ~25% COM, ~25% IND
        if ind_count == 0 or (ind_count * 4 < res_count):
            return Tool.INDUSTRIAL
        if com_count == 0 or (com_count * 4 < res_count):
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not in_bounds(rc, rr):
                    return False
                if not bool(em[rr, rc]):
                    return False
        return True

    def build_corridor(wire_col, plant_cy, cy_ref):
        """Build one vertical corridor: wire spine, roads, zones, lateral wires/roads."""
        road_col_L = wire_col - 1
        road_col_R = wire_col + 1
        # Zone columns at offset 4 and 7 from wire spine
        zone_cols_L = [wire_col - 4, wire_col - 7]
        zone_cols_R = [wire_col + 4, wire_col + 7]

        # Vertical span grows with pop
        base_span = 14
        extra_span = min(28, obs.city_pop // 15)
        target_span = base_span + extra_span
        tmin = max(2, cy_ref - target_span)
        tmax = min(WORLD_H - 3, cy_ref + target_span)

        wire_rows_in_col = sorted(r for r in range(WORLD_H) if wm[r, wire_col])
        road_rows_L = set(r for r in range(WORLD_H) if rm[r, road_col_L]) if in_bounds(road_col_L, 0) else set()
        road_rows_R = set(r for r in range(WORLD_H) if rm[r, road_col_R]) if in_bounds(road_col_R, 0) else set()

        # --- Extend wire spine ---
        if not wire_rows_in_col:
            # Seed wire adjacent to plant
            for dy in range(-2, 3):
                ny = plant_cy + dy
                if in_bounds(wire_col, ny) and (bool(em[ny, wire_col]) or bool(wm[ny, wire_col])) and not bool(pm[ny, wire_col]):
                    return (Tool.WIRE, wire_col, ny)
        else:
            min_wr = min(wire_rows_in_col)
            max_wr = max(wire_rows_in_col)
            if max_wr < tmax:
                nr = max_wr + 1
                if in_bounds(wire_col, nr) and bool(em[nr, wire_col]) and not bool(pm[nr, wire_col]):
                    return (Tool.WIRE, wire_col, nr)
            if min_wr > tmin:
                nr = min_wr - 1
                if in_bounds(wire_col, nr) and bool(em[nr, wire_col]) and not bool(pm[nr, wire_col]):
                    return (Tool.WIRE, wire_col, nr)

        if not wire_rows_in_col:
            return None

        # --- Build road columns adjacent to wire spine ---
        for wr in wire_rows_in_col:
            if wr not in road_rows_L and in_bounds(road_col_L, wr) and bool(em[wr, road_col_L]) and not bool(pm[wr, road_col_L]):
                return (Tool.ROAD, road_col_L, wr)
            if wr not in road_rows_R and in_bounds(road_col_R, wr) and bool(em[wr, road_col_R]) and not bool(pm[wr, road_col_R]):
                return (Tool.ROAD, road_col_R, wr)

        # --- Lateral wires from spine to left zone columns ---
        for wr in wire_rows_in_col:
            if wr < 2 or wr >= WORLD_H - 2:
                continue
            for wc in range(wire_col - 1, max(wire_col - 9, -1), -1):
                if not in_bounds(wc, wr):
                    break
                if bool(pm[wr, wc]):
                    break
                if bool(rm[wr, wc]):
                    break
                if not bool(wm[wr, wc]):
                    if bool(em[wr, wc]):
                        return (Tool.WIRE, wc, wr)
                    else:
                        break

        # --- Lateral roads from right road col to right zone columns ---
        for wr in wire_rows_in_col:
            if wr < 2 or wr >= WORLD_H - 2:
                continue
            for rc in range(road_col_R + 1, min(wire_col + 9, WORLD_W)):
                if not in_bounds(rc, wr):
                    break
                if bool(pm[wr, rc]):
                    break
                if bool(wm[wr, rc]):
                    break
                if not bool(rm[wr, rc]):
                    if bool(em[wr, rc]):
                        return (Tool.ROAD, rc, wr)
                    else:
                        break

        # --- Place zones adjacent to roads ---
        for wr in wire_rows_in_col:
            if wr < 2 or wr >= WORLD_H - 2:
                continue
            road_L_nearby = any(abs(wr - rr) <= 1 for rr in road_rows_L)
            road_R_nearby = any(abs(wr - rr) <= 1 for rr in road_rows_R)

            for zc in zone_cols_L:
                if road_L_nearby and in_bounds(zc, wr) and 2 <= zc < WORLD_W - 2:
                    if zone_area_free(wr, zc):
                        return (pick_zone(wr), zc, wr)

            for zc in zone_cols_R:
                if road_R_nearby and in_bounds(zc, wr) and 2 <= zc < WORLD_W - 2:
                    if zone_area_free(wr, zc):
                        return (pick_zone(wr), zc, wr)

        # --- Also try placing zones near wire with road proximity (reactive) ---
        def expand_mask_small(base, radius=2):
            result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
            for dy in range(-radius, radius+1):
                for dx in range(-radius, radius+1):
                    sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                    sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                    r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                    c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                    result[r0:r1, c0:c1] |= base[sr0:sr1, sc0:sc1]
            return result

        nbr_road = expand_mask_small(rm, 2)
        power_src = wm | pm
        nbr_wire = expand_mask_small(power_src, 2)
        cand = em & nbr_road & nbr_wire
        cand[0:2, :] = False
        cand[WORLD_H-2:, :] = False
        cand[:, 0:2] = False
        cand[:, WORLD_W-2:] = False

        # Restrict to corridor x-range
        x_min_c = max(0, wire_col - 10)
        x_max_c = min(WORLD_W, wire_col + 10)
        cand[:, :x_min_c] = False
        cand[:, x_max_c:] = False

        cys, cxs = np.where(cand)
        if len(cxs) > 0:
            dist_v = np.abs(cxs - wire_col)
            dist_h = np.abs(cys - cy_ref)
            scores = dist_v + dist_h
            order = np.argsort(scores)
            step_off = int(obs.step * 7) % max(len(order), 1)
            for i in range(min(len(order), 40)):
                k = order[(step_off + i) % len(order)]
                zx, zy = int(cxs[k]), int(cys[k])
                if zone_area_free(zy, zx):
                    return (pick_zone(zy), zx, zy)

        return None

    # Build corridor 1 (primary)
    wire_col1 = P1X + 4  # = 49
    action = build_corridor(wire_col1, P1Y, P1Y)
    if action is not None:
        return action

    # Phase 2: second plant and corridor once pop grows
    if obs.city_pop > 80:
        if not has_plant2:
            return (Tool.COALPOWER, P2X, P2Y)

        # Connect plant2 to its wire spine
        wire_col2 = P2X + 4  # = 79
        wire_rows2 = [r for r in range(WORLD_H) if wm[r, wire_col2]]
        if not wire_rows2:
            # Lay wire from plant2 area toward wire_col2
            for wc in range(P2X + 2, wire_col2 + 1):
                if in_bounds(wc, P2Y) and bool(em[P2Y, wc]) and not bool(pm[P2Y, wc]):
                    return (Tool.WIRE, wc, P2Y)

        action2 = build_corridor(wire_col2, P2Y, P2Y)
        if action2 is not None:
            return action2

    # Phase 3: third plant and corridor for very large cities
    P3X, P3Y = 20, 50
    wire_col3 = P3X + 4  # = 24
    if obs.city_pop > 300:
        plant_ys3, plant_xs3 = np.where(pm)
        has_plant3 = any(abs(px_ - P3X) <= 5 and abs(py_ - P3Y) <= 5
                         for py_, px_ in zip(plant_ys3.tolist(), plant_xs3.tolist()))
        if not has_plant3:
            return (Tool.COALPOWER, P3X, P3Y)

        wire_rows3 = [r for r in range(WORLD_H) if wm[r, wire_col3]]
        if not wire_rows3:
            for wc in range(P3X + 2, wire_col3 + 1):
                if in_bounds(wc, P3Y) and bool(em[P3Y, wc]) and not bool(pm[P3Y, wc]):
                    return (Tool.WIRE, wc, P3Y)

        action3 = build_corridor(wire_col3, P3Y, P3Y)
        if action3 is not None:
            return action3

    # Services
    if obs.city_pop > 250:
        fx, fy = wire_col1 + 6, P1Y - 10
        if in_bounds(fx, fy) and zone_area_free(fy, fx):
            return (Tool.FIRESTATION, fx, fy)
        fx2, fy2 = wire_col1 - 6, P1Y - 10
        if in_bounds(fx2, fy2) and zone_area_free(fy2, fx2):
            return (Tool.FIRESTATION, fx2, fy2)

    if obs.city_pop > 400:
        px2, py2 = wire_col1 + 6, P1Y + 10
        if in_bounds(px2, py2) and zone_area_free(py2, px2):
            return (Tool.POLICESTATION, px2, py2)

    # Fallback: extend roads from existing road tiles near wire
    def expand_mask_small2(base, radius=2):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-radius, radius+1):
            for dx in range(-radius, radius+1):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                result[r0:r1, c0:c1] |= base[sr0:sr1, sc0:sc1]
        return result

    nbr_wire2 = expand_mask_small2(wm | pm, 2)
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = int(obs.step * 13) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 20)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx2, ry + dy2
                if in_bounds(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]) and nbr_wire2[ny, nx]:
                    return (Tool.ROAD, nx, ny)

    # Fallback: extend wires
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        step_k2 = int(obs.step * 7) % max(len(wire_xs), 1)
        wx_s, wy_s = int(wire_xs[step_k2]), int(wire_ys[step_k2])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = wx_s + dx2, wy_s + dy2
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Grid-based city builder with multiple neighborhoods.
    - Uses a planned grid layout with roads and wires
    - Places zones in a balanced mix (RES/COM/IND)
    - Builds multiple power plants connected by wire grid
    - Creates a denser, more connected city
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def expand_mask(base, radius=2):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        ys, xs = np.where(base)
        for y, x in zip(ys, xs):
            r0 = max(0, y - radius); r1 = min(WORLD_H, y + radius + 1)
            c0 = max(0, x - radius); c1 = min(WORLD_W, x + radius + 1)
            result[r0:r1, c0:c1] = True
        return result

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and not zone_tiles[nr, nc]:
                    return False
        return True

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        # Aim for ~50% RES, 25% COM, 25% IND
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # === PLANNED LAYOUT ===
    # Two neighborhoods side by side
    # Left neighborhood: center at (35, 50)
    # Right neighborhood: center at (75, 50)
    # Each has a coal plant, wire grid, and road grid

    # Use state to track build phase
    if 'phase' not in state:
        state['phase'] = 0
        state['build_queue'] = []

    # Build queue: precomputed list of (tool, x, y) actions
    def build_neighborhood(cx, cy, prefix=''):
        """Generate a sequence of actions for one neighborhood"""
        actions = []
        # Power plant at center
        actions.append((Tool.COALPOWER, cx, cy))
        # Wire grid: horizontal and vertical spines
        # Vertical wire at cx+2
        for dy in range(-15, 16):
            ny = cy + dy
            if in_bounds(cx+2, ny):
                actions.append((Tool.WIRE, cx+2, ny))
        # Horizontal wire at cy
        for dx in range(-15, 16):
            nx = cx + dx
            if in_bounds(nx, cy):
                actions.append((Tool.WIRE, nx, cy))
        # Roads: parallel to wire spines at +/-1
        for dy in range(-15, 16):
            ny = cy + dy
            if in_bounds(cx+3, ny):
                actions.append((Tool.ROAD, cx+3, ny))
            if in_bounds(cx+1, ny):
                actions.append((Tool.ROAD, cx+1, ny))
        for dx in range(-15, 16):
            nx = cx + dx
            if in_bounds(nx, cy+1):
                actions.append((Tool.ROAD, nx, cy+1))
            if in_bounds(nx, cy-1):
                actions.append((Tool.ROAD, nx, cy-1))
        return actions

    # Initialize build queues for both neighborhoods
    if 'left_done' not in state:
        state['left_done'] = False
        state['right_done'] = False
        state['action_idx'] = 0
        # Pre-build left neighborhood actions
        state['left_actions'] = build_neighborhood(35, 45)
        state['right_actions'] = build_neighborhood(78, 55)
        state['connect_actions'] = []
        # Wire connecting the two neighborhoods
        for x in range(38, 78):
            state['connect_actions'].append((Tool.WIRE, x, 50))
        # Road connecting them
        for x in range(38, 78):
            state['connect_actions'].append((Tool.ROAD, x, 51))

    # Execute pre-planned infrastructure from queue
    if 'infra_queue' not in state:
        state['infra_queue'] = (
            state['left_actions'] +
            state['right_actions'] +
            state['connect_actions']
        )
        state['infra_idx'] = 0

    if state['infra_idx'] < len(state['infra_queue']):
        tool, x, y = state['infra_queue'][state['infra_idx']]
        state['infra_idx'] += 1
        if in_bounds(x, y):
            return (tool, x, y)

    # === ZONE PLACEMENT (reactive) ===
    nbr_road = expand_mask(rm, 2)
    power_src = wm | pm
    nbr_wire = expand_mask(power_src, 2)

    cand_mask = em & nbr_road & nbr_wire
    # Keep away from edges
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prefer locations near either neighborhood center
        d1 = np.sqrt((cxs - 35)**2 + (cys - 45)**2)
        d2 = np.sqrt((cxs - 78)**2 + (cys - 55)**2)
        scores = np.minimum(d1, d2)
        order = np.argsort(scores)
        step_off = int(obs.step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 80:
                break

    # === EXTEND ROADS FROM EXISTING ===
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 20)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx]:
                    if nbr_wire[ny, nx]:
                        return (Tool.ROAD, nx, ny)

    # === ADD THIRD POWER PLANT if needed ===
    if obs.city_pop > 300 or total_zones > 20:
        p3x, p3y = 57, 30
        nearby = any(
            in_bounds(p3x+dx, p3y+dy) and pm[p3y+dy, p3x+dx]
            for dy in range(-5, 6) for dx in range(-5, 6)
        )
        if not nearby and in_bounds(p3x, p3y) and em[p3y, p3x]:
            return (Tool.COALPOWER, p3x, p3y)
        # Wire from p3 down to horizontal spine
        for wy in range(p3y+2, 51):
            if in_bounds(p3x, wy) and (em[wy, p3x] or wm[wy, p3x]) and not pm[wy, p3x]:
                return (Tool.WIRE, p3x, wy)

    # === SERVICES ===
    if obs.city_pop > 100:
        fsx, fsy = 35, 62
        if in_bounds(fsx, fsy) and em[fsy, fsx]:
            return (Tool.FIRESTATION, fsx, fsy)
    if obs.city_pop > 200:
        psx, psy = 78, 42
        if in_bounds(psx, psy) and em[psy, psx]:
            return (Tool.POLICESTATION, psx, psy)
    if obs.city_pop > 400:
        fsx2, fsy2 = 55, 65
        if in_bounds(fsx2, fsy2) and em[fsy2, fsx2]:
            return (Tool.FIRESTATION, fsx2, fsy2)

    # === EXTEND WIRE FRONTIER ===
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 15)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = wx + dx2, wy + dy2
                if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                    return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy v4:
    - More compact initial build near center
    - Wire runs horizontally, roads run on both sides of wire
    - Zones placed reactively near existing road+wire coverage
    - Multiple power plants added as city grows
    - Vertical roads connect horizontal lanes
    - Services added when population warrants
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Place first coal plant near center if none exists ---
    if not np.any(pm):
        return (Tool.COALPOWER, 60, 50)

    plant_ys, plant_xs = np.where(pm)
    px = int(np.median(plant_xs))
    py = int(np.median(plant_ys))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def expand_mask(base, radius=2):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        ys, xs = np.where(base)
        if len(ys) == 0:
            return result
        for dy in range(-radius, radius+1):
            for dx in range(-radius, radius+1):
                ny = np.clip(ys + dy, 0, WORLD_H-1)
                nx = np.clip(xs + dx, 0, WORLD_W-1)
                result[ny, nx] = True
        return result

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and not zone_tiles[nr, nc]:
                    return False
        return True

    # Determine grid layout based on current plant position
    pop_factor = min(5, obs.city_pop // 80)
    n_bands = 2 + pop_factor

    wire_rows = []
    for k in range(-n_bands, n_bands+1):
        wr = py + k * 6
        if 3 <= wr <= WORLD_H - 4:
            wire_rows.append(wr)

    x_extent = 20 + min(35, obs.city_pop // 10)
    wire_x_min = max(3, px - x_extent)
    wire_x_max = min(WORLD_W - 4, px + x_extent)

    # Vertical connector columns every 8 tiles
    vert_cols = []
    c = px
    while c >= wire_x_min:
        vert_cols.append(c)
        c -= 8
    c = px + 8
    while c <= wire_x_max:
        vert_cols.append(c)
        c += 8

    # --- Step 1: Ensure wire extends from plant to first wire row ---
    # Seed wires adjacent to plant if no wire exists near plant
    if not np.any(wm):
        # Lay wire immediately to the left/right of plant
        for dc in range(-3, 4):
            nc = px + dc
            if in_bounds(nc, py) and em[py, nc]:
                return (Tool.WIRE, nc, py)

    # --- Step 2: Extend horizontal wire rows ---
    for wr in wire_rows:
        wire_in_row = np.where(wm[wr, :])[0]
        if len(wire_in_row) == 0:
            # Try to find a column with wire in adjacent rows to seed from
            for adj_offset in range(1, 8):
                for sign in [1, -1]:
                    adj_wr = wr + sign * adj_offset
                    if 0 <= adj_wr < WORLD_H:
                        adj_wire = np.where(wm[adj_wr, :])[0]
                        if len(adj_wire) > 0:
                            # Use median column from adjacent wire
                            seed_c = int(np.median(adj_wire))
                            if in_bounds(seed_c, wr) and (em[wr, seed_c] or wm[wr, seed_c]) and not pm[wr, seed_c]:
                                return (Tool.WIRE, seed_c, wr)
        else:
            min_wc = int(np.min(wire_in_row))
            max_wc = int(np.max(wire_in_row))
            # Extend right
            if max_wc < wire_x_max:
                nc = max_wc + 1
                if in_bounds(nc, wr) and (em[wr, nc] or wm[wr, nc]) and not pm[wr, nc]:
                    return (Tool.WIRE, nc, wr)
            # Extend left
            if min_wc > wire_x_min:
                nc = min_wc - 1
                if in_bounds(nc, wr) and (em[wr, nc] or wm[wr, nc]) and not pm[wr, nc]:
                    return (Tool.WIRE, nc, wr)

    # --- Step 3: Build roads adjacent to wire rows (both sides) ---
    for wr in wire_rows:
        wire_in_row = np.where(wm[wr, :])[0]
        for road_row in [wr - 1, wr + 1]:
            if not in_bounds(0, road_row):
                continue
            for wc in wire_in_row:
                wc = int(wc)
                if wire_x_min <= wc <= wire_x_max:
                    if in_bounds(wc, road_row) and em[road_row, wc] and not pm[road_row, wc]:
                        return (Tool.ROAD, wc, road_row)

    # --- Step 4: Vertical connector roads between wire rows ---
    if len(wire_rows) >= 2:
        for vc in vert_cols:
            for i in range(len(wire_rows) - 1):
                r1 = wire_rows[i]
                r2 = wire_rows[i+1]
                for row in range(r1 + 2, r2 - 1):
                    if in_bounds(vc, row) and em[row, vc] and not pm[row, vc]:
                        has_conn = False
                        for dr in [-1, 1]:
                            nr2 = row + dr
                            if in_bounds(vc, nr2) and (rm[nr2, vc] or wm[nr2, vc]):
                                has_conn = True
                        if has_conn:
                            return (Tool.ROAD, vc, row)

    # --- Step 5: Place zones where road+wire coverage exists ---
    power_src = wm | pm
    nbr_wire = expand_mask(power_src, 2)
    nbr_road = expand_mask(rm, 2)

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        dist_to_wire = (np.min(np.abs(cys[:, None] - np.array(wire_rows)[None, :]), axis=1)
                        if wire_rows else np.abs(cys - py))
        dist_to_px = np.abs(cxs - px)
        scores = dist_to_wire * 3 + dist_to_px
        order = np.argsort(scores)
        step_off = int(obs.step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 100:
                break

    # --- Step 6: Additional coal plants as city grows ---
    n_plants_needed = 1 + total_zones // 12
    # Count plants by counting plant tiles / 9 (approx 3x3 footprint)
    n_plants_actual = max(1, int(np.sum(pm)) // 9)
    if n_plants_actual < n_plants_needed:
        offsets = [
            (px + 18, py),
            (px - 18, py),
            (px, py + 18),
            (px, py - 18),
            (px + 18, py + 18),
            (px - 18, py + 18),
            (px + 18, py - 18),
            (px - 18, py - 18),
        ]
        for p2x, p2y in offsets:
            p2x = max(3, min(WORLD_W - 4, p2x))
            p2y = max(3, min(WORLD_H - 4, p2y))
            nearby = any(
                in_bounds(p2x + dx, p2y + dy) and pm[p2y + dy, p2x + dx]
                for dy in range(-5, 6) for dx in range(-5, 6)
            )
            if not nearby and em[p2y, p2x]:
                return (Tool.COALPOWER, p2x, p2y)
            # Bridge wire from new plant to existing wire
            if not nearby:
                step_dir = 1 if px > p2x else -1
                for wc in range(p2x, px + step_dir, step_dir):
                    if in_bounds(wc, p2y) and (em[p2y, wc] or wm[p2y, wc]) and not pm[p2y, wc]:
                        if not wm[p2y, wc]:
                            return (Tool.WIRE, wc, p2y)

    # --- Step 7: Services ---
    if obs.city_pop > 150:
        fsx = max(2, min(WORLD_W - 3, px - 10))
        fsy = max(2, min(WORLD_H - 3, py - 4))
        if em[fsy, fsx]:
            return (Tool.FIRESTATION, fsx, fsy)
    if obs.city_pop > 250:
        psx = max(2, min(WORLD_W - 3, px + 10))
        psy = max(2, min(WORLD_H - 3, py + 4))
        if em[psy, psx]:
            return (Tool.POLICESTATION, psx, psy)

    # --- Step 8: Extend wire frontier reactively ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 30)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = wx + dx2, wy + dy2
                if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                    if wire_x_min <= nx2 <= wire_x_max:
                        return (Tool.WIRE, nx2, ny2)

    # --- Step 9: Extend roads from existing roads reactively ---
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 30)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx]:
                    if nbr_wire[ny, nx]:
                        return (Tool.ROAD, nx, ny)

    return None

def act(obs, state):
    """
    Closed-loop reactive city builder.
    Reads tile_map every step to find power/road frontiers and expand them.
    Uses a single compact cluster with better zone density.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Single compact cluster anchor
    CX, CY = 55, 50  # center of map

    # ---- Phase 1: Place coal power plant if none exists ----
    plant_ys, plant_xs = np.where(pm)
    if len(plant_xs) == 0:
        return (Tool.COALPOWER, CX, CY)

    # ---- Helper: adjacency check ----
    def adj_to(mask, x, y):
        for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx, ny = x+dx, y+dy
            if in_bounds(nx, ny) and bool(mask[ny, nx]):
                return True
        return False

    def nbr_within(mask, x, y, r):
        x0, x1 = max(0, x-r), min(WORLD_W, x+r+1)
        y0, y1 = max(0, y-r), min(WORLD_H, y+r+1)
        return bool(np.any(mask[y0:y1, x0:x1]))

    # ---- Phase 2: Extend wires from power sources ----
    # Wire plan: cross pattern from power plant(s)
    # Horizontal wire at plant row, vertical wire at plant col
    # For each plant, extend wires outward reactively
    power_src = pm | wm

    # Find all empty tiles adjacent to power that aren't already wired/powered
    # Prefer extending toward CX, CY area
    # Build wire spine: horizontal line at CY and vertical line at CX
    # from plant location outward

    px0, py0 = int(plant_xs[0]), int(plant_ys[0])

    # Wire targets: horizontal spine at plant y, vertical spine at plant x
    # Extend 18 tiles in each direction
    wire_targets = []
    for dx in range(-18, 19):
        wire_targets.append((px0 + dx, py0))
    for dy in range(-18, 19):
        wire_targets.append((px0, py0 + dy))
    # Also a horizontal wire 2 rows above and below
    for dx in range(-14, 15):
        wire_targets.append((px0 + dx, py0 - 2))
        wire_targets.append((px0 + dx, py0 + 2))

    for (wx, wy) in wire_targets:
        if not in_bounds(wx, wy):
            continue
        if bool(wm[wy, wx]) or bool(pm[wy, wx]):
            continue
        if not bool(em[wy, wx]):
            continue
        if adj_to(power_src, wx, wy):
            return (Tool.WIRE, wx, wy)

    # ---- Phase 3: Extend roads reactively ----
    # Road plan: grid of roads every 4 tiles around the cluster
    # Roads at CY-8, CY-4, CY, CY+4, CY+8 (horizontal)
    # Roads at CX-8, CX-4, CX, CX+4, CX+8 (vertical)
    # But only place if adjacent to existing road OR adjacent to plant

    road_targets = []
    # Horizontal roads
    for row_offset in [-8, -4, 0, 4, 8]:
        ry = py0 + row_offset
        for dx in range(-16, 17):
            road_targets.append((px0 + dx, ry))
    # Vertical roads
    for col_offset in [-8, -4, 0, 4, 8]:
        rx = px0 + col_offset
        for dy in range(-16, 17):
            road_targets.append((rx, py0 + dy))

    for (rx, ry) in road_targets:
        if not in_bounds(rx, ry):
            continue
        if bool(rm[ry, rx]):
            continue
        if bool(pm[ry, rx]) or bool(wm[ry, rx]):
            continue
        if not bool(em[ry, rx]):
            continue
        # Adjacent to existing road or near plant
        if adj_to(rm, rx, ry) or nbr_within(pm, rx, ry, 3):
            return (Tool.ROAD, rx, ry)

    # ---- Phase 4: Place zones near roads AND power ----
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Build neighbor masks for road and power proximity
    def dilate(mask, r):
        out = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-r, r+1):
            for dx in range(-r, r+1):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                out[r0:r1, c0:c1] |= mask[sr0:sr1, sc0:sc1]
        return out

    nbr_road = dilate(rm, 2)
    nbr_power = dilate(pm | wm, 5)

    zone_existing = resm | comm | indm
    cand = em & nbr_road & nbr_power
    # Exclude map edges (zones are 3x3)
    cand[0:2, :] = False
    cand[WORLD_H-2:, :] = False
    cand[:, 0:2] = False
    cand[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        # Sort candidates by distance to cluster center (prefer compact city)
        dists = (cxs - px0)**2 + (cys - py0)**2
        order = np.argsort(dists)
        # Add step-based offset to vary selection
        offset_base = int(obs.step * 7 + int(obs.city_pop) * 3) % max(1, len(cxs))

        for i in range(min(len(cxs), 60)):
            k = order[(offset_base + i * 13) % len(cxs)]
            zx, zy = int(cxs[k]), int(cys[k])
            # Check 3x3 clearance: only empty or existing zone tiles
            ok = True
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    ny2, nx2 = zy + dr, zx + dc
                    if not in_bounds(nx2, ny2):
                        ok = False; break
                    if not (bool(em[ny2, nx2]) or bool(zone_existing[ny2, nx2])):
                        ok = False; break
                if not ok:
                    break
            if ok:
                return (pick_tool(), zx, zy)

    # ---- Phase 5: Services ----
    if obs.city_pop > 150:
        for fx, fy in [(px0+5, py0-10), (px0-5, py0+10)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.FIRESTATION, fx, fy)
    if obs.city_pop > 300:
        for fx, fy in [(px0+5, py0+10), (px0-5, py0-10)]:
            if in_bounds(fx, fy) and bool(em[fy, fx]):
                return (Tool.POLICESTATION, fx, fy)

    # ---- Fallback: extend road from any road frontier ----
    rys, rxs = np.where(rm)
    if len(rxs) > 0:
        k2 = int(obs.step * 13 + 1) % len(rxs)
        for i in range(min(20, len(rxs))):
            idx = (k2 + i) % len(rxs)
            rx2, ry2 = int(rxs[idx]), int(rys[idx])
            for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx2, ny2 = rx2+ddx, ry2+ddy
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- Fallback: extend wire from existing wire ----
    wys, wxs = np.where(wm)
    if len(wxs) > 0:
        k3 = int(obs.step * 7 + 3) % len(wxs)
        wx2, wy2 = int(wxs[k3]), int(wys[k3])
        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx2, ny2 = wx2+ddx, wy2+ddy
            if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Hybrid policy combining best ideas from both parents:
    - Multiple horizontal clusters (Parent B's approach) but with better coverage
    - Two power plants (Parent A's idea) for coverage
    - Immediate zone placement near roads (don't wait for pop threshold)
    - 3 clusters built from the start, each with wire+road spine
    - Better zone density: every 4 cols, both above and below
    - Vertical wire connections to ensure power reaches all zones
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    # Count zones
    res_count = int(np.sum(res_m))
    com_count = int(np.sum(com_m))
    ind_count = int(np.sum(ind_m))
    all_zone_m = res_m | com_m | ind_m

    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def zone_nearby(zr, zc):
        # Check if any zone tile within 2 of center
        r0 = max(0, zr - 2)
        r1 = min(WORLD_H, zr + 3)
        c0 = max(0, zc - 2)
        c1 = min(WORLD_W, zc + 3)
        return np.any(all_zone_m[r0:r1, c0:c1])

    def pick_zone_type():
        if res_count == 0:
            return Tool.RESIDENTIAL
        if ind_count == 0:
            return Tool.INDUSTRIAL
        if com_count == 0:
            return Tool.COMMERCIAL
        # 2:1:1 res:com:ind
        total = res_count + com_count + ind_count
        if ind_count * 2 < res_count:
            return Tool.INDUSTRIAL
        if com_count * 2 < res_count:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Layout: 3 clusters
    # Cluster 1: center rows ~50 (wire_row=49, road_row=51)
    # Cluster 2: center rows ~30 (wire_row=29, road_row=31)
    # Cluster 3: center rows ~70 (wire_row=69, road_row=71)
    # Power plant 1 at (15, 49), Power plant 2 at (15, 69)
    # x range: 22..100 for zones/spines

    clusters = [
        # (wire_row, road_row, zone_above, zone_below)
        (49, 51, 46, 54),
        (29, 31, 26, 34),
        (69, 71, 66, 74),
    ]

    plant1_cx, plant1_cy = 15, 49
    plant2_cx, plant2_cy = 15, 69

    x_start = 22
    x_end = 105

    num_plants = int(np.sum(pm))
    has_plant1 = bool(np.any(pm[plant1_cy-1:plant1_cy+2, plant1_cx-1:plant1_cx+2]))
    has_plant2 = bool(np.any(pm[plant2_cy-1:plant2_cy+2, plant2_cx-1:plant2_cx+2]))

    # Phase 1: Place power plants
    if not has_plant1 and num_plants == 0:
        return (Tool.COALPOWER, plant1_cx, plant1_cy)

    if not has_plant2 and num_plants < 2:
        return (Tool.COALPOWER, plant2_cx, plant2_cy)

    # Build vertical wire from plant1 to cluster1 wire_row
    # plant1 is at row 49 = wire_row of cluster 1, so already on spine
    # Connect plant2 (row 69) to cluster3 wire_row (69) - same row

    # Connect plant1 to cluster2 (row 29): need wire from row 29..49 at col 15
    # Connect plant2 to cluster3 (row 69) - same row, already connected
    # Connect cluster1 to cluster2: wire at col x_start from row 29..49
    # Connect cluster1 to cluster3: wire at col x_start from row 49..69

    # Build the vertical bridge wires at x_start col connecting all clusters
    bridge_col = x_start
    # Wire from cluster2 wire_row (29) to cluster3 wire_row (69) through cluster1 (49)
    for ry in range(29, 70):
        if not wm[ry, bridge_col] and not pm[ry, bridge_col] and em[ry, bridge_col]:
            return (Tool.WIRE, bridge_col, ry)

    # Also wire from plant1 col to bridge_col at cluster1 wire_row
    c1_wire_row = clusters[0][0]  # 49
    for cx in range(plant1_cx + 3, bridge_col + 1):
        if not wm[c1_wire_row, cx] and not pm[c1_wire_row, cx] and em[c1_wire_row, cx]:
            return (Tool.WIRE, cx, c1_wire_row)

    # Wire from plant2 to bridge_col at cluster3 wire_row
    c3_wire_row = clusters[2][0]  # 69
    for cx in range(plant2_cx + 3, bridge_col + 1):
        if not wm[c3_wire_row, cx] and not pm[c3_wire_row, cx] and em[c3_wire_row, cx]:
            return (Tool.WIRE, cx, c3_wire_row)

    # For each cluster, build wire spine, road spine, then zones
    for ci, (wr, rr, za, zb) in enumerate(clusters):
        wire_cols = set(int(c) for (row, c) in zip(*np.where(wm)) if row == wr)
        road_cols = set(int(c) for (row, c) in zip(*np.where(rm)) if row == rr)

        # Dynamic extent: all clusters build to full extent
        cur_x_end = min(x_end, x_start + 15 + max(0, obs.city_pop // 4))

        # Build wire spine
        for xc in range(x_start, cur_x_end + 1):
            if xc not in wire_cols and 0 <= xc < WORLD_W and em[wr, xc]:
                return (Tool.WIRE, xc, wr)

        # Build road spine
        for xc in range(x_start, cur_x_end + 1):
            if xc not in road_cols and 0 <= xc < WORLD_W and em[rr, xc]:
                return (Tool.ROAD, xc, rr)

        # Build vertical wires to zone rows (above and below)
        for xc in range(x_start + 2, cur_x_end, 4):
            if xc not in wire_cols:
                continue
            # Wire up to zone_above
            for ry2 in range(wr - 1, za - 2, -1):
                if ry2 < 0:
                    break
                if not wm[ry2, xc] and not rm[ry2, xc] and em[ry2, xc]:
                    return (Tool.WIRE, xc, ry2)
                elif rm[ry2, xc]:
                    break  # road blocks wire but that's ok, zone is powered via road adjacency? No - need wire
            # Wire down to zone_below
            for ry2 in range(wr + 1, zb + 2):
                if ry2 >= WORLD_H:
                    break
                if not wm[ry2, xc] and not rm[ry2, xc] and em[ry2, xc]:
                    return (Tool.WIRE, xc, ry2)
                elif rm[ry2, xc]:
                    break

        # Place zones above and below road spine
        for xc in range(x_start + 2, cur_x_end - 1, 4):
            if xc < 2 or xc >= WORLD_W - 2:
                continue
            # Road must be nearby
            road_close = (xc in road_cols or (xc - 1) in road_cols or
                          (xc + 1) in road_cols)
            if not road_close:
                continue
            for zr in [za, zb]:
                if 2 <= zr < WORLD_H - 2:
                    if not zone_nearby(zr, xc) and zone_area_free(zr, xc):
                        return (pick_zone_type(), xc, zr)

    # Extra: place more zones at denser spacing if we have steps left
    for ci, (wr, rr, za, zb) in enumerate(clusters):
        road_cols = set(int(c) for (row, c) in zip(*np.where(rm)) if row == rr)
        for xc in range(x_start, x_end, 4):
            if xc < 2 or xc >= WORLD_W - 2:
                continue
            road_close = (xc in road_cols or (xc - 1) in road_cols or
                          (xc + 1) in road_cols)
            if not road_close:
                continue
            # Also try rows 3 away from zone rows
            for zr in [za - 4, zb + 4]:
                if 2 <= zr < WORLD_H - 2:
                    if not zone_nearby(zr, xc) and zone_area_free(zr, xc):
                        return (pick_zone_type(), xc, zr)

    return None

def act(obs, state):
    """
    Hybrid policy combining best ideas from both parents:
    - Parent B's grid-based horizontal wire lanes + road adjacency (proven ~640 pop)
    - Parent A's explicit phase structure for initialization
    - Denser zone placement with zone_clear check
    - Multiple coal plants as city grows
    - Services for population boost
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Place first coal plant if missing ---
    if not np.any(pm):
        return (Tool.COALPOWER, 55, 50)

    plant_ys, plant_xs = np.where(pm)
    px = int(np.median(plant_xs))
    py = int(np.median(plant_ys))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def expand_mask(base, radius=2):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        ys, xs = np.where(base)
        if len(ys) == 0:
            return result
        for dy in range(-radius, radius+1):
            for dx in range(-radius, radius+1):
                ny = np.clip(ys + dy, 0, WORLD_H-1)
                nx = np.clip(xs + dx, 0, WORLD_W-1)
                result[ny, nx] = True
        return result

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and not zone_tiles[nr, nc]:
                    return False
        return True

    # Grid layout: wire rows every 6 rows, road rows adjacent to wires
    # Expand coverage based on population
    pop_factor = min(5, obs.city_pop // 80)
    n_bands = 3 + pop_factor

    wire_rows = []
    for k in range(-n_bands, n_bands+1):
        wr = py + k * 6
        if 3 <= wr <= WORLD_H - 4:
            wire_rows.append(wr)
    wire_rows = sorted(wire_rows)

    x_extent = 20 + min(35, obs.city_pop // 10)
    wire_x_min = max(3, px - x_extent)
    wire_x_max = min(WORLD_W - 4, px + x_extent)

    # Vertical connector columns at intervals of 8
    vert_cols = []
    c = px
    while c >= wire_x_min:
        vert_cols.append(c)
        c -= 8
    c = px + 8
    while c <= wire_x_max:
        vert_cols.append(c)
        c += 8

    # --- Step 1: Ensure wire extends from plant to first wire rows ---
    # First make sure plant row has wire adjacent
    for dc in range(-3, 4):
        nc = px + dc
        if in_bounds(nc, py) and em[py, nc] and not pm[py, nc]:
            if not wm[py, nc]:
                return (Tool.WIRE, nc, py)

    # --- Step 2: Extend horizontal wire rows ---
    for wr in wire_rows:
        wire_in_row = [c for c in range(WORLD_W) if wm[wr, c]]
        if not wire_in_row:
            # Try to extend from plant area if close, else from adjacent wire rows
            if abs(wr - py) <= 3:
                for dc in range(-3, 4):
                    nc = px + dc
                    if in_bounds(nc, wr) and (em[wr, nc] or wm[wr, nc]) and not pm[wr, nc]:
                        return (Tool.WIRE, nc, wr)
            else:
                for adj_wr in [wr-1, wr+1, wr-2, wr+2, wr-6, wr+6]:
                    if 0 <= adj_wr < WORLD_H:
                        for c in range(WORLD_W):
                            if wm[adj_wr, c] and in_bounds(c, wr) and (em[wr, c] or wm[wr, c]) and not pm[wr, c]:
                                return (Tool.WIRE, c, wr)
        else:
            min_wc = min(wire_in_row)
            max_wc = max(wire_in_row)
            if max_wc < wire_x_max:
                nc = max_wc + 1
                if in_bounds(nc, wr) and (em[wr, nc] or wm[wr, nc]) and not pm[wr, nc]:
                    return (Tool.WIRE, nc, wr)
            if min_wc > wire_x_min:
                nc = min_wc - 1
                if in_bounds(nc, wr) and (em[wr, nc] or wm[wr, nc]) and not pm[wr, nc]:
                    return (Tool.WIRE, nc, wr)

    # --- Step 3: Build roads adjacent to wire rows (both sides) ---
    for wr in wire_rows:
        for road_row in [wr - 1, wr + 1]:
            if not in_bounds(0, road_row):
                continue
            wire_in_row = [c for c in range(WORLD_W) if wm[wr, c]]
            for wc in wire_in_row:
                if wire_x_min <= wc <= wire_x_max:
                    if in_bounds(wc, road_row) and em[road_row, wc] and not pm[road_row, wc]:
                        return (Tool.ROAD, wc, road_row)

    # --- Step 4: Vertical connector roads between wire rows ---
    if len(wire_rows) >= 2:
        for vc in vert_cols:
            for i in range(len(wire_rows) - 1):
                r1 = wire_rows[i]
                r2 = wire_rows[i+1]
                for row in range(r1 + 1, r2):
                    if in_bounds(vc, row) and em[row, vc] and not pm[row, vc]:
                        has_conn = False
                        for dr in [-1, 1]:
                            nr2 = row + dr
                            if in_bounds(vc, nr2) and (rm[nr2, vc] or wm[nr2, vc]):
                                has_conn = True
                        if has_conn:
                            return (Tool.ROAD, vc, row)

    # --- Step 5: Place zones where road+wire coverage exists ---
    power_src = wm | pm
    nbr_wire = expand_mask(power_src, 2)
    nbr_road = expand_mask(rm, 2)

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        dist_to_wire = np.min(np.abs(cys[:, None] - np.array(wire_rows)[None, :]), axis=1) if wire_rows else np.abs(cys - py)
        dist_to_px = np.abs(cxs - px)
        scores = dist_to_wire * 2 + dist_to_px
        order = np.argsort(scores)
        step_off = int(obs.step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 100:
                break

    # --- Step 6: Additional coal plants as city grows ---
    n_plants_needed = 1 + total_zones // 12
    # Count plants: each coal plant is 3x3=9 tiles
    n_plants_actual = max(1, int(np.sum(pm)) // 9)
    if n_plants_actual < n_plants_needed:
        attempt_positions = [
            (px + 20, py),
            (px - 20, py),
            (px, py + 20),
            (px, py - 20),
            (px + 20, py + 20),
            (px - 20, py - 20),
            (px + 20, py - 20),
            (px - 20, py + 20),
        ]
        for p2x, p2y in attempt_positions:
            p2x = max(3, min(WORLD_W - 4, p2x))
            p2y = max(3, min(WORLD_H - 4, p2y))
            nearby = any(
                in_bounds(p2x + dx, p2y + dy) and pm[p2y + dy, p2x + dx]
                for dy in range(-6, 7) for dx in range(-6, 7)
            )
            if not nearby and em[p2y, p2x]:
                return (Tool.COALPOWER, p2x, p2y)
            if not nearby:
                # Try to bridge with wire
                for wc in range(min(px, p2x), max(px, p2x) + 1):
                    if in_bounds(wc, p2y) and (em[p2y, wc] or wm[p2y, wc]) and not pm[p2y, wc]:
                        if not wm[p2y, wc]:
                            return (Tool.WIRE, wc, p2y)

    # --- Step 7: Services for population growth ---
    if obs.city_pop > 150 and not state.get("firestation_placed"):
        fsx = max(2, min(WORLD_W - 3, px - 14))
        fsy = max(2, min(WORLD_H - 3, py))
        if em[fsy, fsx]:
            state["firestation_placed"] = True
            return (Tool.FIRESTATION, fsx, fsy)
    if obs.city_pop > 250 and not state.get("police_placed"):
        psx = max(2, min(WORLD_W - 3, px + 14))
        psy = max(2, min(WORLD_H - 3, py))
        if em[psy, psx]:
            state["police_placed"] = True
            return (Tool.POLICESTATION, psx, psy)
    if obs.city_pop > 500 and not state.get("firestation2_placed"):
        fsx = max(2, min(WORLD_W - 3, px))
        fsy = max(2, min(WORLD_H - 3, py - 20))
        if em[fsy, fsx]:
            state["firestation2_placed"] = True
            return (Tool.FIRESTATION, fsx, fsy)

    # --- Step 8: Extend wire frontier to reach unserved empty areas ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 20)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = wx + dx2, wy + dy2
                if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                    if wire_x_min <= nx2 <= wire_x_max:
                        return (Tool.WIRE, nx2, ny2)

    # --- Step 9: Extend roads from existing roads near wire ---
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 20)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx]:
                    if nbr_wire[ny, nx]:
                        return (Tool.ROAD, nx, ny)

    return None

def act(obs, state):
    """
    Improved policy: builds a horizontal strip city with proper road/wire grid.
    Uses a checkerboard-style zone placement with dedicated road rows and wire rows.
    Places multiple power plants to ensure good coverage.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Initialize state
    if 'phase' not in state:
        state['phase'] = 0
        state['build_queue'] = []

    # Count zones
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Zone selection: balanced mix
    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        r_r = res_count / t
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Layout: two horizontal neighborhoods
    # Neighborhood 1: centered at (60, 35)
    # Neighborhood 2: centered at (60, 65)
    # Each neighborhood has:
    #   - power plant at left
    #   - horizontal wire row through center
    #   - road rows above and below center wire
    #   - zones in 3x3 blocks between road rows

    neighborhoods = [
        {'cx': 60, 'cy': 35, 'plant_x': 25, 'plant_placed': False},
        {'cx': 60, 'cy': 65, 'plant_x': 30, 'plant_placed': False},
    ]

    # For each neighborhood: wire at cy, roads at cy-2 and cy+2
    # Zones at cy (served by wire adjacency) -- actually zones at cy-1, cy, cy+1
    # Better: wire at cy, road at cy+3 and cy-3, zones fill between

    # Simple grid layout:
    # Wire rows at: 33, 50, 67
    # Road rows at: 30, 36, 47, 53, 64, 70
    # Zone centers at rows: 33 (between roads 30,36), 50 (between 47,53), 67 (between 64,70)
    # Zone centers at cols every 4 starting from col 10

    wire_rows = [33, 50, 67]
    road_rows_above = [30, 47, 64]  # road above zone row
    road_rows_below = [36, 53, 70]  # road below zone row
    zone_rows = [33, 50, 67]        # zone center rows (same as wire)

    # Actually zones are 3x3 centered, so zone at row 33 occupies rows 32-34
    # Wire at 33, roads at 30 and 36 -> zone at 33 is between roads -> has road access

    # Zone cols: start at 10, every 4 cols -> 10,14,18,...,110
    zone_cols = list(range(10, 111, 4))

    # Power plants: 2 plants to cover the area
    # Plant 1 at (5, 50) - center vertically
    # Plant 2 at (85, 50) - right side

    # Step 1: Ensure power plants exist
    plant_positions = [(5, 50), (85, 50)]
    for ppx, ppy in plant_positions:
        if not np.any(pm[ppy-1:ppy+2, ppx-1:ppx+2]):
            return (Tool.COALPOWER, ppx, ppy)

    # Step 2: Build horizontal wire rows
    for wr in wire_rows:
        for wc in range(5, 115):
            if not in_bounds(wc, wr):
                continue
            if not wm[wr, wc] and not pm[wr, wc]:
                # Only place if empty or already wire
                if em[wr, wc]:
                    return (Tool.WIRE, wc, wr)

    # Step 3: Connect plants vertically to wire rows
    for ppx, ppy in plant_positions:
        for wr in wire_rows:
            # Vertical wire from plant to wire row
            y_start = min(ppy, wr)
            y_end = max(ppy, wr)
            for wy in range(y_start, y_end + 1):
                if in_bounds(ppx, wy) and em[wy, ppx] and not pm[wy, ppx]:
                    return (Tool.WIRE, ppx, wy)

    # Step 4: Build road rows
    all_road_rows = road_rows_above + road_rows_below
    for rr in all_road_rows:
        for rc in range(5, 115):
            if not in_bounds(rc, rr):
                continue
            if not rm[rr, rc] and not wm[rr, rc] and not pm[rr, rc]:
                if em[rr, rc]:
                    return (Tool.ROAD, rc, rr)

    # Step 5: Place zones
    # Check road and wire proximity
    def expand_mask_fast(base, radius=2):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-radius, radius+1):
            for dx in range(-radius, radius+1):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                result[r0:r1, c0:c1] |= base[sr0:sr1, sc0:sc1]
        return result

    nbr_road = expand_mask_fast(rm, 2)
    power_src = wm | pm
    nbr_wire = expand_mask_fast(power_src, 2)

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                if not em[nr, nc] and not zone_tiles[nr, nc]:
                    return False
        return True

    # Try placing zones at the grid positions
    step_offset = obs.step % max(len(zone_cols), 1)
    for z_row in zone_rows:
        for i in range(len(zone_cols)):
            zc = zone_cols[(i + step_offset) % len(zone_cols)]
            zy = z_row
            if not in_bounds(zc, zy):
                continue
            if not nbr_road[zy, zc] or not nbr_wire[zy, zc]:
                continue
            if zone_clear(zc, zy):
                return (pick_tool(), zc, zy)

    # Step 6: Add fire/police stations for larger cities
    if obs.city_pop > 200:
        # Fire station
        fsx, fsy = 45, 50
        if em[fsy, fsx]:
            return (Tool.FIRESTATION, fsx, fsy)
    if obs.city_pop > 400:
        psx, psy = 75, 50
        if em[psy, psx]:
            return (Tool.POLICESTATION, psx, psy)

    # Step 7: Add third power plant if needed
    if obs.city_pop > 300 and total_zones > 20:
        p3x, p3y = 45, 20
        if not np.any(pm[p3y-2:p3y+3, p3x-2:p3x+3]):
            return (Tool.COALPOWER, p3x, p3y)

    # Step 8: Extend zones anywhere with road+wire coverage
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False
    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        step_off = int(obs.step * 7) % max(len(cxs), 1)
        checked = 0
        for i in range(len(cxs)):
            k = (step_off + i) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 50:
                break

    # Step 9: Extend roads from existing network
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 20)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx]:
                    if nbr_wire[ny, nx]:
                        return (Tool.ROAD, nx, ny)

    # Step 10: Extend wire to reach more areas
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 15)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = wx + dx2, wy + dy2
                if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                    return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy. Reads map every step, builds adaptively.
    Key changes from parent:
    - More aggressive zone placement (less restrictive zone_clear)
    - Horizontal road spine instead of vertical wire+road columns
    - More zones placed per wire segment
    - Better second plant connection
    - Wider search for zone candidates
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Phase 1: Place coal plant ---
    if not np.any(pm):
        return (Tool.COALPOWER, 60, 50)

    # Find plant center
    plant_ys, plant_xs = np.where(pm)
    px = int(np.median(plant_xs))
    py = int(np.median(plant_ys))

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Wire spine: grow horizontally from plant left and right ---
    wire_row = py
    pop_factor = min(30, obs.city_pop // 10)
    lmin = max(2, px - 20 - pop_factor)
    rmax = min(WORLD_W - 3, px + 20 + pop_factor)

    wire_in_row = [c for c in range(WORLD_W) if 0 <= wire_row < WORLD_H and wm[wire_row, c]]

    if not wire_in_row:
        # Seed wire adjacent to plant
        for dx in range(-2, 3):
            nx = px + dx
            if in_bounds(nx, wire_row) and (em[wire_row, nx] or wm[wire_row, nx]) and not pm[wire_row, nx]:
                return (Tool.WIRE, nx, wire_row)
    else:
        min_wc = min(wire_in_row)
        max_wc = max(wire_in_row)
        if max_wc < rmax:
            nc = max_wc + 1
            if in_bounds(nc, wire_row) and (em[wire_row, nc] or wm[wire_row, nc]) and not pm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)
        if min_wc > lmin:
            nc = min_wc - 1
            if in_bounds(nc, wire_row) and (em[wire_row, nc] or wm[wire_row, nc]) and not pm[wire_row, nc]:
                return (Tool.WIRE, nc, wire_row)

    # --- Road rows above and below wire spine ---
    road_row_u = wire_row - 1
    road_row_d = wire_row + 1

    for wc in wire_in_row:
        if in_bounds(wc, road_row_u) and em[road_row_u, wc]:
            return (Tool.ROAD, wc, road_row_u)
        if in_bounds(wc, road_row_d) and em[road_row_d, wc]:
            return (Tool.ROAD, wc, road_row_d)

    # --- Also add vertical road segments to reach zones further away ---
    # For each wire column, extend roads up/down
    for wc in wire_in_row:
        # Try to extend road up
        for dr in range(2, 6):
            nr = wire_row - dr
            if in_bounds(wc, nr):
                if rm[nr, wc]:
                    break  # already road here
                if em[nr, wc] and rm[nr + 1, wc]:
                    return (Tool.ROAD, wc, nr)
        # Try to extend road down
        for dr in range(2, 6):
            nr = wire_row + dr
            if in_bounds(wc, nr):
                if rm[nr, wc]:
                    break
                if em[nr, wc] and rm[nr - 1, wc]:
                    return (Tool.ROAD, wc, nr)

    # --- Build proximity masks for zone placement ---
