                nr, nc = zy + dr, zx + dc
                if not in_bounds(nc, nr):
                    return False
                # Block if it's road, wire, or plant
                if rm[nr, nc] or wm[nr, nc] or pm[nr, nc]:
                    return False
        return True

    # Candidate zone centers: empty, near road, near wire/plant
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Sort by distance to wire row (prefer close zones)
        dists = np.abs(cys - wire_row) + np.abs(cxs - px) // 4
        order = np.argsort(dists)
        step_off = int(obs.step * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 120:
                break

    # --- Extend roads near wire to fill gaps ---
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 30)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if in_bounds(nx, ny) and em[ny, nx] and not pm[ny, nx] and nbr_wire[ny, nx]:
                    return (Tool.ROAD, nx, ny)

    # --- Second power plant when city grows ---
    if total_zones > 8 or obs.city_pop > 200:
        # Place second plant above wire row
        p2x = px
        p2y = py - 20
        if not in_bounds(p2x, p2y):
            p2y = py + 20
        if in_bounds(p2x, p2y):
            nearby_plant = any(
                in_bounds(p2x + dx, p2y + dy) and pm[p2y + dy, p2x + dx]
                for dy in range(-5, 6) for dx in range(-5, 6)
            )
            if not nearby_plant and em[p2y, p2x]:
                return (Tool.COALPOWER, p2x, p2y)
            # Wire vertical bridge from spine to second plant
            wy_start = min(py, p2y) + 1
            wy_end = max(py, p2y)
            for wy in range(wy_start, wy_end):
                if in_bounds(p2x, wy) and em[wy, p2x]:
                    return (Tool.WIRE, p2x, wy)

    # --- Services when pop is high enough ---
    if obs.city_pop > 80:
        fsx, fsy = px - 10, py - 10
        if in_bounds(fsx, fsy) and em[fsy, fsx]:
            return (Tool.FIRESTATION, fsx, fsy)
        psx, psy = px + 10, py - 10
        if in_bounds(psx, psy) and em[psy, psx]:
            return (Tool.POLICESTATION, psx, psy)

    # --- Expand wire to reach new empty areas ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 20)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = wx + dx2, wy + dy2
                if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2]:
                    return (Tool.WIRE, nx2, ny2)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy:
    - Vertical wire spine from coal plant
    - Road column adjacent to wire
    - Zones placed where wire+road both reachable
    - Expands dynamically based on observed map state
    - Multiple clusters triggered by pop thresholds
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    pop = obs.city_pop

    # Fixed layout constants
    PLANT_X, PLANT_Y = 54, 50
    WIRE_COL = 58
    ROAD_COL = 61
    LEFT_ZONE_COL = 55
    RIGHT_ZONE_COL = 64

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def zone_area_free(cy, cx):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cy + dr, cx + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc]:
                    return False
        return True

    # Collect all zone centers
    res_pos = list(zip(*np.where(res_m))) if np.any(res_m) else []
    com_pos = list(zip(*np.where(com_m))) if np.any(com_m) else []
    ind_pos = list(zip(*np.where(ind_m))) if np.any(ind_m) else []
    all_zones = set(res_pos) | set(com_pos) | set(ind_pos)
    res_count = len(res_pos)
    com_count = len(com_pos)
    ind_count = len(ind_pos)

    def no_zone_nearby(zy, zx, dist=2):
        return not any(abs(zy - pr) <= dist and abs(zx - pc) <= dist for (pr, pc) in all_zones)

    def pick_zone():
        # Target: 2 res : 1 com : 1 ind
        if res_count == 0:
            return Tool.RESIDENTIAL
        if ind_count * 2 < res_count:
            return Tool.INDUSTRIAL
        if com_count * 2 < res_count:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Determine vertical span based on pop
    base_span = 14
    extra = min(28, pop // 20)
    target_span = base_span + extra
    tmin = max(2, PLANT_Y - target_span)
    tmax = min(WORLD_H - 3, PLANT_Y + target_span)

    # ---- PHASE 1: Plant ----
    if not np.any(pm):
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    # Get wire and road rows in the main columns
    wire_in_col = sorted(r for r in range(WORLD_H) if wm[r, WIRE_COL])
    road_in_col = sorted(r for r in range(WORLD_H) if rm[r, ROAD_COL])
    road_set = set(road_in_col)

    # ---- PHASE 2: Start wire spine adjacent to plant ----
    if not wire_in_col:
        # Place first wire adjacent to plant at wire col
        for try_r in [PLANT_Y, PLANT_Y - 1, PLANT_Y + 1]:
            if in_bounds(WIRE_COL, try_r) and em[try_r, WIRE_COL]:
                return (Tool.WIRE, WIRE_COL, try_r)
        return None

    min_wr = min(wire_in_col)
    max_wr = max(wire_in_col)

    # ---- PHASE 3: Extend wire spine ----
    if max_wr < tmax:
        nr = max_wr + 1
        if in_bounds(WIRE_COL, nr) and em[nr, WIRE_COL]:
            return (Tool.WIRE, WIRE_COL, nr)
    if min_wr > tmin:
        nr = min_wr - 1
        if in_bounds(WIRE_COL, nr) and em[nr, WIRE_COL]:
            return (Tool.WIRE, WIRE_COL, nr)

    # ---- PHASE 4: Build road column matching wire coverage ----
    for wr in wire_in_col:
        if wr not in road_set and in_bounds(ROAD_COL, wr):
            if em[wr, ROAD_COL]:
                return (Tool.ROAD, ROAD_COL, wr)

    # ---- PHASE 5: Place zones adjacent to wire+road ----
    # Check road proximity via actual road rows
    road_arr = np.array(sorted(road_set)) if road_set else np.array([])

    def road_nearby(zy):
        if len(road_arr) == 0:
            return False
        return np.any(np.abs(road_arr - zy) <= 2)

    for zr in sorted(wire_in_col):
        if not road_nearby(zr):
            continue
        for zc in [LEFT_ZONE_COL, RIGHT_ZONE_COL]:
            if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                if no_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                    return (pick_zone(), zc, zr)

    # ---- PHASE 6: Lateral wires to left zones ----
    for wr in wire_in_col:
        for wc in range(WIRE_COL - 1, max(LEFT_ZONE_COL - 3, 0), -1):
            if in_bounds(wc, wr) and wm[wr, wc]:
                break
            if in_bounds(wc, wr) and em[wr, wc]:
                return (Tool.WIRE, wc, wr)

    # ---- PHASE 7: Lateral roads to right zones ----
    for wr in wire_in_col:
        for rc in range(ROAD_COL + 1, min(RIGHT_ZONE_COL + 3, WORLD_W)):
            if in_bounds(rc, wr) and rm[wr, rc]:
                break
            if in_bounds(rc, wr) and em[wr, rc]:
                return (Tool.ROAD, rc, wr)

    # ---- PHASE 8: Second cluster (right side) when pop >= 120 ----
    if pop >= 120:
        W2_WIRE = 70
        W2_ROAD = 73
        W2_LEFT = 67
        W2_RIGHT = 76

        wire_in_col2 = sorted(r for r in range(WORLD_H) if wm[r, W2_WIRE])
        road_in_col2 = set(r for r in range(WORLD_H) if rm[r, W2_ROAD])

        # Bridge wire horizontally from main spine to second spine
        if not wire_in_col2:
            bridge_r = PLANT_Y
            for wc in range(WIRE_COL + 1, W2_WIRE + 1):
                if in_bounds(wc, bridge_r) and em[bridge_r, wc]:
                    return (Tool.WIRE, wc, bridge_r)
        else:
            min_wr2 = min(wire_in_col2)
            max_wr2 = max(wire_in_col2)
            if max_wr2 < tmax:
                nr = max_wr2 + 1
                if in_bounds(W2_WIRE, nr) and em[nr, W2_WIRE]:
                    return (Tool.WIRE, W2_WIRE, nr)
            if min_wr2 > tmin:
                nr = min_wr2 - 1
                if in_bounds(W2_WIRE, nr) and em[nr, W2_WIRE]:
                    return (Tool.WIRE, W2_WIRE, nr)

            for wr in wire_in_col2:
                if wr not in road_in_col2 and in_bounds(W2_ROAD, wr):
                    if em[wr, W2_ROAD]:
                        return (Tool.ROAD, W2_ROAD, wr)

            road_arr2 = np.array(sorted(road_in_col2)) if road_in_col2 else np.array([])
            def road_nearby2(zy):
                if len(road_arr2) == 0:
                    return False
                return np.any(np.abs(road_arr2 - zy) <= 2)

            for zr in sorted(wire_in_col2):
                if not road_nearby2(zr):
                    continue
                for zc in [W2_LEFT, W2_RIGHT]:
                    if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                        if no_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                            return (pick_zone(), zc, zr)

            for wr in wire_in_col2:
                for wc in range(W2_WIRE - 1, max(W2_LEFT - 3, 0), -1):
                    if in_bounds(wc, wr) and wm[wr, wc]:
                        break
                    if in_bounds(wc, wr) and em[wr, wc]:
                        return (Tool.WIRE, wc, wr)
            for wr in wire_in_col2:
                for rc in range(W2_ROAD + 1, min(W2_RIGHT + 3, WORLD_W)):
                    if in_bounds(rc, wr) and rm[wr, rc]:
                        break
                    if in_bounds(rc, wr) and em[wr, rc]:
                        return (Tool.ROAD, rc, wr)

    # ---- PHASE 9: Third cluster (left side) when pop >= 300 ----
    if pop >= 300:
        W3_WIRE = 46
        W3_ROAD = 43
        W3_LEFT = 40
        W3_RIGHT = 49

        wire_in_col3 = sorted(r for r in range(WORLD_H) if wm[r, W3_WIRE])
        road_in_col3 = set(r for r in range(WORLD_H) if rm[r, W3_ROAD])

        if not wire_in_col3:
            bridge_r = PLANT_Y
            for wc in range(WIRE_COL - 1, W3_WIRE - 1, -1):
                if in_bounds(wc, bridge_r) and em[bridge_r, wc]:
                    return (Tool.WIRE, wc, bridge_r)
        else:
            min_wr3 = min(wire_in_col3)
            max_wr3 = max(wire_in_col3)
            if max_wr3 < tmax:
                nr = max_wr3 + 1
                if in_bounds(W3_WIRE, nr) and em[nr, W3_WIRE]:
                    return (Tool.WIRE, W3_WIRE, nr)
            if min_wr3 > tmin:
                nr = min_wr3 - 1
                if in_bounds(W3_WIRE, nr) and em[nr, W3_WIRE]:
                    return (Tool.WIRE, W3_WIRE, nr)

            for wr in wire_in_col3:
                if wr not in road_in_col3 and in_bounds(W3_ROAD, wr):
                    if em[wr, W3_ROAD]:
                        return (Tool.ROAD, W3_ROAD, wr)

            road_arr3 = np.array(sorted(road_in_col3)) if road_in_col3 else np.array([])
            def road_nearby3(zy):
                if len(road_arr3) == 0:
                    return False
                return np.any(np.abs(road_arr3 - zy) <= 2)

            for zr in sorted(wire_in_col3):
                if not road_nearby3(zr):
                    continue
                for zc in [W3_LEFT, W3_RIGHT]:
                    if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                        if no_zone_nearby(zr, zc) and zone_area_free(zr, zc):
                            return (pick_zone(), zc, zr)

    # ---- PHASE 10: Second power plant when pop >= 400 ----
    if pop >= 400:
        # Check if we need another plant
        plant_tiles = np.where(pm)
        plant_count = max(1, len(plant_tiles[0]) // 6)
        if plant_count < 2:
            p2x, p2y = 80, PLANT_Y
            if in_bounds(p2x, p2y) and em[p2y, p2x]:
                nearby_plant = any(
                    in_bounds(p2x + dx, p2y + dy) and pm[p2y + dy, p2x + dx]
                    for dy in range(-5, 6) for dx in range(-5, 6)
                )
                if not nearby_plant:
                    return (Tool.COALPOWER, p2x, p2y)

    # ---- PHASE 11: Services ----
    if pop > 200:
        fx, fy = WIRE_COL, PLANT_Y - 16
        if in_bounds(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
    if pop > 350:
        px2, py2 = ROAD_COL, PLANT_Y + 18
        if in_bounds(px2, py2) and em[py2, px2]:
            return (Tool.POLICESTATION, px2, py2)

    # ---- PHASE 12: Reactive fill - find any empty spot near wire+road ----
    # Build proximity masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand = em & nbr_road & nbr_wire
    cand[:2, :] = False; cand[WORLD_H-2:, :] = False
    cand[:, :2] = False; cand[:, WORLD_W-2:] = False
    cys_a, cxs_a = np.where(cand)
    if len(cxs_a) > 0:
        dists = np.abs(cxs_a.astype(int) - PLANT_X) + np.abs(cys_a.astype(int) - PLANT_Y)
        sort_idx = np.argsort(dists)
        for k in sort_idx[:60]:
            zx, zy = int(cxs_a[k]), int(cys_a[k])
            if zone_area_free(zy, zx) and no_zone_nearby(zy, zx):
                return (pick_zone(), zx, zy)

    return None

def act(obs, state):
    """
    Improved city-building policy with a cleaner layout:
    - Place coal plant at left side
    - Run horizontal wire from plant rightward
    - Place roads above and below the wire spine
    - Place zones in rows flanking the roads (R/C/I mix)
    - Expand with a second horizontal strip when population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)

    # Initialize state
    if "phase" not in state:
        state["phase"] = 0
        state["wire_x"] = 0
        state["step_log"] = []

    # Fixed layout parameters
    plant_x, plant_y = 10, 50  # coal plant center
    wire_row = 50               # horizontal wire spine row
    road_row_above = 48         # road above wire
    road_row_below = 52         # road below wire
    zone_row_above = 46         # zones above road (center of 3x3)
    zone_row_below = 54         # zones below road (center of 3x3)
    wire_start_x = 13           # wire starts right of plant footprint
    wire_end_x = 100            # wire extends to here

    has_plant = np.any(pm)

    # Phase 0: Place coal power plant
    if not has_plant:
        return (Tool.COALPOWER, plant_x, plant_y)

    # Find actual plant location
    plant_rows, plant_cols = np.where(pm)
    if len(plant_rows) > 0:
        plant_cy_actual = int(np.mean(plant_rows))
        plant_cx_actual = int(np.mean(plant_cols))
    else:
        plant_cy_actual, plant_cx_actual = plant_y, plant_x

    # Recalculate based on actual plant position
    wire_row = plant_cy_actual
    road_row_above = wire_row - 2
    road_row_below = wire_row + 2
    zone_row_above = wire_row - 5
    zone_row_below = wire_row + 5
    wire_start_x = plant_cx_actual + 2

    # Build horizontal wire spine
    wire_cols = sorted(c for c in range(WORLD_W) if wm[wire_row, c] and c >= wire_start_x)

    if not wire_cols:
        # Start wire right next to plant
        for c in range(wire_start_x, wire_start_x + 5):
            if 0 <= c < WORLD_W and (em[wire_row, c] or wm[wire_row, c]):
                return (Tool.WIRE, c, wire_row)
    else:
        max_wc = max(wire_cols)
        if max_wc < wire_end_x:
            nc = max_wc + 1
            if 0 <= nc < WORLD_W and (em[wire_row, nc] or wm[wire_row, nc]):
                return (Tool.WIRE, nc, wire_row)

    wire_col_set = set(c for c in range(WORLD_W) if wm[wire_row, c])

    # Build roads above and below wire
    road_above_cols = set(c for c in range(WORLD_W) if rm[road_row_above, c]) if 0 <= road_row_above < WORLD_H else set()
    road_below_cols = set(c for c in range(WORLD_W) if rm[road_row_below, c]) if 0 <= road_row_below < WORLD_H else set()

    for wc in sorted(wire_col_set):
        if wc < wire_start_x:
            continue
        if 0 <= road_row_above < WORLD_H and wc not in road_above_cols:
            if em[road_row_above, wc]:
                return (Tool.ROAD, wc, road_row_above)
        if 0 <= road_row_below < WORLD_H and wc not in road_below_cols:
            if em[road_row_below, wc]:
                return (Tool.ROAD, wc, road_row_below)

    # Count existing zone types for ratio control
    res_count = int(np.sum(res_mask(tm)))
    com_count = int(np.sum(com_mask(tm)))
    ind_count = int(np.sum(ind_mask(tm)))
    all_z = res_mask(tm) | com_mask(tm) | ind_mask(tm)

    def zone_area_free(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if rr < 0 or rr >= WORLD_H or rc < 0 or rc >= WORLD_W:
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def zone_nearby(zr, zc, radius=4):
        r0, r1 = max(0, zr - radius), min(WORLD_H, zr + radius + 1)
        c0, c1 = max(0, zc - radius), min(WORLD_W, zc + radius + 1)
        return np.any(all_z[r0:r1, c0:c1])

    def pick_tool(col_idx):
        """Pick zone type based on column position and ratios."""
        total = res_count + com_count + ind_count + 1
        # Industrial at start (leftmost), commercial in middle, residential elsewhere
        if ind_count * 4 < total:
            return Tool.INDUSTRIAL
        if com_count * 3 < total:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Place zones above the road (zone centers at zone_row_above)
    if 0 <= zone_row_above < WORLD_H:
        for wc in sorted(wire_col_set):
            if wc < wire_start_x + 1:
                continue
            # Zone center needs to be at wc, zone_row_above
            if wc not in road_above_cols:
                continue
            if not zone_nearby(zone_row_above, wc, 3) and zone_area_free(zone_row_above, wc):
                tool = pick_tool(wc)
                return (tool, wc, zone_row_above)

    # Place zones below the road (zone centers at zone_row_below)
    if 0 <= zone_row_below < WORLD_H:
        for wc in sorted(wire_col_set):
            if wc < wire_start_x + 1:
                continue
            if wc not in road_below_cols:
                continue
            if not zone_nearby(zone_row_below, wc, 3) and zone_area_free(zone_row_below, wc):
                tool = pick_tool(wc)
                return (tool, wc, zone_row_below)

    # Second horizontal strip when population grows
    if obs.city_pop > 100 or obs.step > 200:
        wire_row2 = wire_row - 14
        road2_above = wire_row2 - 2
        road2_below = wire_row2 + 2
        zone2_above = wire_row2 - 5
        zone2_below = wire_row2 + 5

        if 0 <= wire_row2 < WORLD_H:
            wire2_cols = set(c for c in range(WORLD_W) if wm[wire_row2, c])

            if not wire2_cols:
                # Connect horizontal wire from plant level to wire_row2 first
                # Place vertical wire connector
                for r in range(min(wire_row, wire_row2), max(wire_row, wire_row2) + 1):
                    if 0 <= r < WORLD_H and em[r, wire_start_x]:
                        return (Tool.WIRE, wire_start_x, r)
            else:
                max_wc2 = max(wire2_cols) if wire2_cols else wire_start_x - 1
                if max_wc2 < wire_end_x:
                    nc = max_wc2 + 1
                    if 0 <= nc < WORLD_W and (em[wire_row2, nc] or wm[wire_row2, nc]):
                        return (Tool.WIRE, nc, wire_row2)

                road2a_cols = set(c for c in range(WORLD_W) if rm[road2_above, c]) if 0 <= road2_above < WORLD_H else set()
                road2b_cols = set(c for c in range(WORLD_W) if rm[road2_below, c]) if 0 <= road2_below < WORLD_H else set()

                for wc in sorted(wire2_cols):
                    if wc < wire_start_x:
                        continue
                    if 0 <= road2_above < WORLD_H and wc not in road2a_cols:
                        if em[road2_above, wc]:
                            return (Tool.ROAD, wc, road2_above)
                    if 0 <= road2_below < WORLD_H and wc not in road2b_cols:
                        if em[road2_below, wc]:
                            return (Tool.ROAD, wc, road2_below)

                for wc in sorted(wire2_cols):
                    if wc < wire_start_x + 1:
                        continue
                    if 0 <= zone2_above < WORLD_H and wc in road2a_cols:
                        if not zone_nearby(zone2_above, wc, 3) and zone_area_free(zone2_above, wc):
                            return (pick_tool(wc), wc, zone2_above)
                    if 0 <= zone2_below < WORLD_H and wc in road2b_cols:
                        if not zone_nearby(zone2_below, wc, 3) and zone_area_free(zone2_below, wc):
                            return (pick_tool(wc), wc, zone2_below)

    # Third strip below
    if obs.city_pop > 300 or obs.step > 400:
        wire_row3 = wire_row + 14
        road3_above = wire_row3 - 2
        road3_below = wire_row3 + 2
        zone3_above = wire_row3 - 5
        zone3_below = wire_row3 + 5

        if 0 <= wire_row3 < WORLD_H:
            wire3_cols = set(c for c in range(WORLD_W) if wm[wire_row3, c])

            if not wire3_cols:
                for r in range(min(wire_row, wire_row3), max(wire_row, wire_row3) + 1):
                    if 0 <= r < WORLD_H and em[r, wire_start_x]:
                        return (Tool.WIRE, wire_start_x, r)
            else:
                max_wc3 = max(wire3_cols) if wire3_cols else wire_start_x - 1
                if max_wc3 < wire_end_x:
                    nc = max_wc3 + 1
                    if 0 <= nc < WORLD_W and (em[wire_row3, nc] or wm[wire_row3, nc]):
                        return (Tool.WIRE, nc, wire_row3)

                road3a_cols = set(c for c in range(WORLD_W) if rm[road3_above, c]) if 0 <= road3_above < WORLD_H else set()
                road3b_cols = set(c for c in range(WORLD_W) if rm[road3_below, c]) if 0 <= road3_below < WORLD_H else set()

                for wc in sorted(wire3_cols):
                    if wc < wire_start_x:
                        continue
                    if 0 <= road3_above < WORLD_H and wc not in road3a_cols:
                        if em[road3_above, wc]:
                            return (Tool.ROAD, wc, road3_above)
                    if 0 <= road3_below < WORLD_H and wc not in road3b_cols:
                        if em[road3_below, wc]:
                            return (Tool.ROAD, wc, road3_below)

                for wc in sorted(wire3_cols):
                    if wc < wire_start_x + 1:
                        continue
                    if 0 <= zone3_above < WORLD_H and wc in road3a_cols:
                        if not zone_nearby(zone3_above, wc, 3) and zone_area_free(zone3_above, wc):
                            return (pick_tool(wc), wc, zone3_above)
                    if 0 <= zone3_below < WORLD_H and wc in road3b_cols:
                        if not zone_nearby(zone3_below, wc, 3) and zone_area_free(zone3_below, wc):
                            return (pick_tool(wc), wc, zone3_below)

    # Second coal plant if needed
    if obs.city_pop > 500 and not state.get("plant2", False):
        p2x = plant_cx_actual + 40
        p2y = plant_cy_actual
        if 0 <= p2x + 1 < WORLD_W and 0 <= p2y < WORLD_H:
            clear = all(
                (0 <= p2y + dr < WORLD_H and 0 <= p2x + dc < WORLD_W and em[p2y + dr, p2x + dc])
                for dr in [-1, 0, 1] for dc in [-1, 0, 1]
            )
            if clear:
                state["plant2"] = True
                return (Tool.COALPOWER, p2x, p2y)

    return None

def act(obs, state):
    """
    Variation: Two clusters side by side with horizontal road spines
    and vertical wire connections. More balanced R/C/I mix.
    Cluster 1 centered ~(35, 50), Cluster 2 centered ~(80, 50).
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Phase tracking ---
    if 'phase' not in state:
        state['phase'] = 'init'

    # Step 1: Place first coal plant at (35, 50)
    if not np.any(pm):
        return (Tool.COALPOWER, 35, 50)

    plant_ys, plant_xs = np.where(pm)
    px1 = int(plant_xs[0])
    py1 = int(plant_ys[0])

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        # Target: 40% R, 30% C, 30% I
        if total_zones == 0:
            return Tool.RESIDENTIAL
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        r_r = res_count / total_zones
        if i_r < 0.28:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Cluster 1: plant at (35, 50), horizontal road spine at row 50+2=52
    # Wire column at x=35 (through plant vicinity), road row at y=52
    # Zones placed above and below road row

    # Cluster 2: plant at (80, 50), road row at y=48
    # Wire column at x=80

    # --- Place second power plant ---
    if total_zones > 6 or obs.city_pop > 100:
        px2, py2 = 80, 50
        near_plant2 = any(
            in_bounds(px2 + dx, py2 + dy) and bool(pm[py2 + dy, px2 + dx])
            for dy in range(-4, 5) for dx in range(-4, 5)
            if in_bounds(px2 + dx, py2 + dy)
        ) if in_bounds(px2, py2) else True
        if not near_plant2 and in_bounds(px2, py2) and bool(em[py2, px2]):
            return (Tool.COALPOWER, px2, py2)

    # --- Build horizontal wire bridge between plants ---
    # Wire at row py1 from x=37 to x=78
    for wx in range(px1 + 3, 79):
        if in_bounds(wx, py1) and (bool(em[py1, wx]) or bool(wm[py1, wx])) and not bool(pm[py1, wx]):
            if not bool(wm[py1, wx]):
                return (Tool.WIRE, wx, py1)

    # --- Build vertical wire spines for each cluster ---
    # Spine 1: x=35, rows py1-14 to py1+14
    spine1_x = px1
    spine1_top = max(3, py1 - 16)
    spine1_bot = min(WORLD_H - 4, py1 + 16)

    for sy in range(spine1_top, spine1_bot + 1):
        if in_bounds(spine1_x, sy) and not bool(pm[sy, spine1_x]) and not bool(wm[sy, spine1_x]):
            if bool(em[sy, spine1_x]):
                return (Tool.WIRE, spine1_x, sy)

    # Spine 2: x=80, same vertical extent
    spine2_x = 80
    spine2_top = max(3, py1 - 16)
    spine2_bot = min(WORLD_H - 4, py1 + 16)

    if np.any(pm[py1, 75:85]):  # second plant exists
        for sy in range(spine2_top, spine2_bot + 1):
            if in_bounds(spine2_x, sy) and not bool(pm[sy, spine2_x]) and not bool(wm[sy, spine2_x]):
                if bool(em[sy, spine2_x]):
                    return (Tool.WIRE, spine2_x, sy)

    # --- Build horizontal road spines ---
    # Road row at y=py1+2 (cluster 1 zone access) from x=28 to x=42
    road_row1 = py1 + 2
    road_row1b = py1 - 2  # second road above plant
    # Road row at y=py1+2 and py1-2 for cluster 2, x=73 to x=87

    for rx in range(spine1_x - 7, spine1_x + 8):
        if in_bounds(rx, road_row1) and bool(em[road_row1, rx]) and not bool(pm[road_row1, rx]):
            return (Tool.ROAD, rx, road_row1)
        if in_bounds(rx, road_row1b) and bool(em[road_row1b, rx]) and not bool(pm[road_row1b, rx]):
            return (Tool.ROAD, rx, road_row1b)

    if np.any(pm[py1, 75:85]):
        road_row2 = py1 + 2
        road_row2b = py1 - 2
        for rx in range(spine2_x - 7, spine2_x + 8):
            if in_bounds(rx, road_row2) and bool(em[road_row2, rx]) and not bool(pm[road_row2, rx]):
                return (Tool.ROAD, rx, road_row2)
            if in_bounds(rx, road_row2b) and bool(em[road_row2b, rx]) and not bool(pm[road_row2b, rx]):
                return (Tool.ROAD, rx, road_row2b)

    # --- Vertical connecting roads for each cluster ---
    for ry in range(spine1_top, spine1_bot + 1):
        road_col_l = spine1_x - 4
        road_col_r = spine1_x + 4
        if in_bounds(road_col_l, ry) and bool(em[ry, road_col_l]) and not bool(pm[ry, road_col_l]):
            if bool(wm[ry, spine1_x]) or bool(pm[ry, spine1_x]):  # near wire
                return (Tool.ROAD, road_col_l, ry)
        if in_bounds(road_col_r, ry) and bool(em[ry, road_col_r]) and not bool(pm[ry, road_col_r]):
            if bool(wm[ry, spine1_x]) or bool(pm[ry, spine1_x]):
                return (Tool.ROAD, road_col_r, ry)

    # --- Proximity masks ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not in_bounds(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # --- Place zones near roads and power ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prioritize near either cluster center
        d1 = np.abs(cxs - spine1_x) + np.abs(cys - py1) // 2
        d2 = np.abs(cxs - spine2_x) + np.abs(cys - py1) // 2
        dists = np.minimum(d1, d2)
        order = np.argsort(dists)
        step_off = int(obs.step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 100:
                break

    # --- Extend roads near wire to fill gaps ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 20)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- Services when pop is high enough ---
    if obs.city_pop > 200:
        for fpos in [(spine1_x - 8, py1), (spine1_x + 8, py1), (spine2_x - 8, py1)]:
            fsx, fsy = fpos
            if in_bounds(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)
    if obs.city_pop > 500:
        for ppos in [(spine1_x, py1 + 12), (spine2_x, py1 + 12)]:
            psx, psy = ppos
            if in_bounds(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    # --- Expand wire laterally as fallback ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 15)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if in_bounds(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def act(obs, state):
    """
    Closed-loop reactive policy.
    Strategy:
    - Coal plant at fixed anchor
    - Grow wire spine vertically from plant, reacting to where wire already is
    - Grow road column adjacent to wire spine
    - Place zones adjacent to road+wire coverage
    - Expand horizontally when population grows
    - All decisions based on current tile_map observation
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    res_m = res_mask(tm)
    com_m = com_mask(tm)
    ind_m = ind_mask(tm)

    pop = obs.city_pop

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # ---- Plant placement ----
    plant_cx, plant_cy = 55, 50
    has_plant = np.any(pm)
    if not has_plant:
        return (Tool.COALPOWER, plant_cx, plant_cy)

    # Find plant center from map
    plant_rows, plant_cols = np.where(pm)
    if len(plant_rows) > 0:
        # Use centroid of plant tiles
        plant_cy_actual = int(np.median(plant_rows))
        plant_cx_actual = int(np.median(plant_cols))
    else:
        plant_cy_actual = plant_cy
        plant_cx_actual = plant_cx

    # ---- Configuration ----
    wire_col = plant_cx_actual + 3   # wire spine col
    road_col = wire_col + 3          # road col
    zone_col_left = wire_col - 3     # zones left of wire
    zone_col_right = road_col + 3    # zones right of road

    # Vertical span grows with population
    span = 10 + min(35, pop // 20)
    tmin = max(2, plant_cy_actual - span)
    tmax = min(WORLD_H - 3, plant_cy_actual + span)

    # ---- Read current wire in spine column ----
    wire_in_col = sorted(r for r in range(WORLD_H) if wm[r, wire_col])
    road_in_col = sorted(r for r in range(WORLD_H) if rm[r, road_col])
    road_set = set(road_in_col)

    # ---- Phase 2: Extend wire spine vertically ----
    if not wire_in_col:
        # Start wire adjacent to plant
        for dr in [0, -1, 1, -2, 2]:
            wr = plant_cy_actual + dr
            if in_bounds(wire_col, wr) and em[wr, wire_col]:
                return (Tool.WIRE, wire_col, wr)
        return None

    min_wr = min(wire_in_col)
    max_wr = max(wire_in_col)

    # Extend downward first, then upward
    if max_wr < tmax:
        nr = max_wr + 1
        if in_bounds(wire_col, nr) and em[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)
    if min_wr > tmin:
        nr = min_wr - 1
        if in_bounds(wire_col, nr) and em[nr, wire_col]:
            return (Tool.WIRE, wire_col, nr)

    wire_set = set(wire_in_col)

    # ---- Phase 3: Build road column matching wire coverage ----
    for wr in wire_in_col:
        if wr not in road_set and in_bounds(road_col, wr) and em[wr, road_col]:
            return (Tool.ROAD, road_col, wr)

    # ---- Zone placement helpers ----
    res_tiles = list(zip(*np.where(res_m))) if np.any(res_m) else []
    com_tiles = list(zip(*np.where(com_m))) if np.any(com_m) else []
    ind_tiles = list(zip(*np.where(ind_m))) if np.any(ind_m) else []
    all_zones = set(res_tiles) | set(com_tiles) | set(ind_tiles)
    res_count = len(res_tiles)
    com_count = len(com_tiles)
    ind_count = len(ind_tiles)

    def zone_area_free(cr, cc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = cr + dr, cc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc]:
                    return False
        return True

    def no_zone_nearby(zr, zc, dist=2):
        return not any(abs(zr - pr) <= dist and abs(zc - pc) <= dist for (pr, pc) in all_zones)

    def pick_zone(rc, cc, ic):
        total = rc + cc + ic
        if total == 0 or rc == 0:
            return Tool.RESIDENTIAL
        # Aim for roughly 4:2:1 res:com:ind ratio
        if ic * 4 < rc:
            return Tool.INDUSTRIAL
        if cc * 2 < rc:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- Phase 4: Place zones near wire+road ----
    # Check road coverage: row within 2 of road spine
    for zr in sorted(wire_in_col):
        road_near = any(abs(zr - rr) <= 2 for rr in road_in_col)
        if not road_near:
            continue
        for zc in [zone_col_left, zone_col_right]:
            if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                if zone_area_free(zr, zc) and no_zone_nearby(zr, zc):
                    return (pick_zone(res_count, com_count, ind_count), zc, zr)

    # ---- Phase 5: Connect left zones with lateral wires ----
    for wr in wire_in_col:
        for wc in range(wire_col - 1, max(zone_col_left - 2, 0), -1):
            if not in_bounds(wc, wr):
                break
            if em[wr, wc]:
                return (Tool.WIRE, wc, wr)
            elif wm[wr, wc]:
                break  # already wired

    # ---- Phase 6: Connect right zones with lateral roads ----
    for wr in wire_in_col:
        for rc2 in range(road_col + 1, min(zone_col_right + 2, WORLD_W)):
            if not in_bounds(rc2, wr):
                break
            if em[wr, rc2]:
                return (Tool.ROAD, rc2, wr)
            elif rm[wr, rc2]:
                break

    # ---- Phase 7: Horizontal expansion - second cluster ----
    if pop >= 100:
        wire_col2 = wire_col + 12
        road_col2 = wire_col2 + 3
        zone_col_l2 = wire_col2 - 3
        zone_col_r2 = road_col2 + 3

        wire_in_col2 = sorted(r for r in range(WORLD_H) if wm[r, wire_col2])
        road_in_col2 = sorted(r for r in range(WORLD_H) if rm[r, road_col2])
        road_set2 = set(road_in_col2)

        # Bridge wire horizontally from main spine
        if not wire_in_col2:
            # Find current rightmost wire at plant_cy_actual row
            row_wires = sorted(c for c in range(WORLD_W) if wm[plant_cy_actual, c])
            if row_wires:
                rightmost = max(row_wires)
                nc = rightmost + 1
                if nc <= wire_col2 and in_bounds(nc, plant_cy_actual) and em[plant_cy_actual, nc]:
                    return (Tool.WIRE, nc, plant_cy_actual)
            else:
                # Start bridging from wire_col
                for wc in range(wire_col + 1, wire_col2 + 1):
                    if in_bounds(wc, plant_cy_actual) and em[plant_cy_actual, wc]:
                        return (Tool.WIRE, wc, plant_cy_actual)
        else:
            min_wr2 = min(wire_in_col2)
            max_wr2 = max(wire_in_col2)
            if max_wr2 < tmax:
                nr = max_wr2 + 1
                if in_bounds(wire_col2, nr) and em[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)
            if min_wr2 > tmin:
                nr = min_wr2 - 1
                if in_bounds(wire_col2, nr) and em[nr, wire_col2]:
                    return (Tool.WIRE, wire_col2, nr)

            for wr in wire_in_col2:
                if wr not in road_set2 and in_bounds(road_col2, wr) and em[wr, road_col2]:
                    return (Tool.ROAD, road_col2, wr)

            for zr in sorted(wire_in_col2):
                road_near2 = any(abs(zr - rr) <= 2 for rr in road_in_col2)
                if not road_near2:
                    continue
                for zc in [zone_col_l2, zone_col_r2]:
                    if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                        if zone_area_free(zr, zc) and no_zone_nearby(zr, zc):
                            return (pick_zone(res_count, com_count, ind_count), zc, zr)

            for wr in wire_in_col2:
                for wc in range(wire_col2 - 1, max(zone_col_l2 - 2, 0), -1):
                    if not in_bounds(wc, wr): break
                    if em[wr, wc]: return (Tool.WIRE, wc, wr)
                    elif wm[wr, wc]: break
            for wr in wire_in_col2:
                for rc2 in range(road_col2 + 1, min(zone_col_r2 + 2, WORLD_W)):
                    if not in_bounds(rc2, wr): break
                    if em[wr, rc2]: return (Tool.ROAD, rc2, wr)
                    elif rm[wr, rc2]: break

    # ---- Phase 8: Left expansion cluster ----
    if pop >= 200:
        wire_col3 = wire_col - 12
        road_col3 = wire_col3 - 3
        zone_col_l3 = road_col3 - 3
        zone_col_r3 = wire_col3 + 3

        wire_in_col3 = sorted(r for r in range(WORLD_H) if wm[r, wire_col3])
        road_in_col3 = sorted(r for r in range(WORLD_H) if rm[r, road_col3])
        road_set3 = set(road_in_col3)

        if not wire_in_col3:
            row_wires = sorted(c for c in range(WORLD_W) if wm[plant_cy_actual, c])
            if row_wires:
                leftmost = min(row_wires)
                nc = leftmost - 1
                if nc >= wire_col3 and in_bounds(nc, plant_cy_actual) and em[plant_cy_actual, nc]:
                    return (Tool.WIRE, nc, plant_cy_actual)
            else:
                for wc in range(wire_col - 1, wire_col3 - 1, -1):
                    if in_bounds(wc, plant_cy_actual) and em[plant_cy_actual, wc]:
                        return (Tool.WIRE, wc, plant_cy_actual)
        else:
            min_wr3 = min(wire_in_col3)
            max_wr3 = max(wire_in_col3)
            if max_wr3 < tmax:
                nr = max_wr3 + 1
                if in_bounds(wire_col3, nr) and em[nr, wire_col3]:
                    return (Tool.WIRE, wire_col3, nr)
            if min_wr3 > tmin:
                nr = min_wr3 - 1
                if in_bounds(wire_col3, nr) and em[nr, wire_col3]:
                    return (Tool.WIRE, wire_col3, nr)

            for wr in wire_in_col3:
                if wr not in road_set3 and in_bounds(road_col3, wr) and em[wr, road_col3]:
                    return (Tool.ROAD, road_col3, wr)

            for zr in sorted(wire_in_col3):
                road_near3 = any(abs(zr - rr) <= 2 for rr in road_in_col3)
                if not road_near3:
                    continue
                for zc in [zone_col_l3, zone_col_r3]:
                    if 2 <= zr < WORLD_H - 2 and 2 <= zc < WORLD_W - 2:
                        if zone_area_free(zr, zc) and no_zone_nearby(zr, zc):
                            return (pick_zone(res_count, com_count, ind_count), zc, zr)

            for wr in wire_in_col3:
                for wc in range(wire_col3 - 1, max(zone_col_l3 - 2, 0), -1):
                    if not in_bounds(wc, wr): break
                    if em[wr, wc]: return (Tool.WIRE, wc, wr)
                    elif wm[wr, wc]: break
            for wr in wire_in_col3:
                for rc3 in range(road_col3 + 1, min(zone_col_r3 + 2, WORLD_W)):
                    if not in_bounds(rc3, wr): break
                    if em[wr, rc3]: return (Tool.ROAD, rc3, wr)
                    elif rm[wr, rc3]: break

    # ---- Phase 9: Second power plant if needed ----
    if pop > 300:
        # Count plant tiles to estimate if we have one plant
        n_plant_tiles = int(np.sum(pm))
        if n_plant_tiles < 12:  # one coal plant is ~6 tiles
            # Place second plant to right
            p2x, p2y = plant_cx_actual + 20, plant_cy_actual
            if in_bounds(p2x, p2y):
                near = any(
                    in_bounds(p2x + dx, p2y + dy) and pm[p2y + dy, p2x + dx]
                    for dy in range(-4, 5) for dx in range(-4, 5)
                )
                if not near and em[p2y, p2x]:
                    return (Tool.COALPOWER, p2x, p2y)

    # ---- Phase 10: Services ----
    if pop > 150:
        fx, fy = wire_col, plant_cy_actual - 15
        if in_bounds(fx, fy) and em[fy, fx]:
            return (Tool.FIRESTATION, fx, fy)
    if pop > 300:
        px2, py2 = wire_col, plant_cy_actual + 15
        if in_bounds(px2, py2) and em[py2, px2]:
            return (Tool.POLICESTATION, px2, py2)

    # ---- Phase 11: Reactive fill - find empty spots near road+wire ----
    # Dilate road and wire masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand = em & nbr_road & nbr_wire
    cand[:2, :] = False; cand[WORLD_H-2:, :] = False
    cand[:, :2] = False; cand[:, WORLD_W-2:] = False

    cys_a, cxs_a = np.where(cand)
    if len(cxs_a) > 0:
        dists = np.abs(cxs_a.astype(int) - plant_cx_actual) + np.abs(cys_a.astype(int) - plant_cy_actual)
        sort_idx = np.argsort(dists)
        for k in sort_idx[:60]:
            zx, zy = int(cxs_a[k]), int(cys_a[k])
            if zone_area_free(zy, zx) and no_zone_nearby(zy, zx):
                return (pick_zone(res_count, com_count, ind_count), zx, zy)

    return None

def act(obs, state):
    """
    Combined policy: horizontal wire+road spine with zones on both sides,
    proper plant-to-spine connection, closed-loop zone placement.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    cx, cy = WORLD_W // 2, WORLD_H // 2

    # Layout constants
    PLANT_X = cx - 25
    PLANT_Y = cy
    wire_row = cy - 2
    road_row = cy + 2
    upper_zone_row = wire_row - 3
    lower_zone_row = road_row + 3
    upper_zone_row2 = wire_row - 7
    lower_zone_row2 = road_row + 7

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))

    def pick_tool(idx):
        pattern = [Tool.RESIDENTIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL,
                   Tool.INDUSTRIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL,
                   Tool.RESIDENTIAL, Tool.INDUSTRIAL]
        return pattern[idx % len(pattern)]

    # Phase 0: Place coal power plant
    if not np.any(pm):
        return (Tool.COALPOWER, PLANT_X, PLANT_Y)

    plant_rows, plant_cols = np.where(pm)
    plant_cy = int(np.mean(plant_rows))
    plant_cx = int(np.mean(plant_cols))

    # Phase 1: Wire from plant rightward to wire_row level
    # Connect plant vertically down/up to wire_row
    connect_col = plant_cx + 2
    connect_col = max(2, min(WORLD_W - 3, connect_col))

    if not state.get("vert_wire_done"):
        # Wire vertically from plant to wire_row
        if plant_cy >= wire_row:
            for r in range(wire_row, plant_cy + 1):
                if not wm[r, connect_col] and not pm[r, connect_col]:
                    if em[r, connect_col]:
                        return (Tool.WIRE, connect_col, r)
            state["vert_wire_done"] = True
        else:
            for r in range(plant_cy, wire_row + 1):
                if not wm[r, connect_col] and not pm[r, connect_col]:
                    if em[r, connect_col]:
                        return (Tool.WIRE, connect_col, r)
            state["vert_wire_done"] = True

    # Determine spine extent based on population
    if obs.city_pop < 100:
        spine_extent = 15
    elif obs.city_pop < 300:
        spine_extent = 25
    elif obs.city_pop < 600:
        spine_extent = 35
    else:
        spine_extent = 45

    target_min_col = max(2, cx - spine_extent)
    target_max_col = min(WORLD_W - 3, cx + spine_extent)

    # Phase 2: Extend horizontal wire spine
    wire_on_spine = [c for c in range(WORLD_W) if wm[wire_row, c]]
    if not wire_on_spine:
        # Seed wire near connect_col on wire_row
        sc = connect_col
        if em[wire_row, sc]:
            return (Tool.WIRE, sc, wire_row)
        return None

    min_wc = min(wire_on_spine)
    max_wc = max(wire_on_spine)

    if max_wc < target_max_col:
        nc = max_wc + 1
        if nc < WORLD_W and em[wire_row, nc] and not pm[wire_row, nc]:
            return (Tool.WIRE, nc, wire_row)

    if min_wc > target_min_col:
        nc = min_wc - 1
        if nc >= 0 and em[wire_row, nc] and not pm[wire_row, nc]:
            return (Tool.WIRE, nc, wire_row)

    # Phase 3: Build horizontal road spine
    for c in range(target_min_col, target_max_col + 1):
        if not rm[road_row, c] and em[road_row, c] and not pm[road_row, c]:
            return (Tool.ROAD, c, road_row)

    # Phase 4: Wire upward from spine to power upper zones
    for wc in wire_on_spine[::2]:
        for r in range(wire_row - 1, upper_zone_row - 2, -1):
            if 0 <= r < WORLD_H:
                if wm[r, wc]:
                    break
                if em[r, wc] and not pm[r, wc]:
                    return (Tool.WIRE, wc, r)
                elif not em[r, wc]:
                    break

    # Phase 5: Wire downward from spine to power lower zones
    for wc in wire_on_spine[::2]:
        for r in range(wire_row + 1, lower_zone_row + 2):
            if 0 <= r < WORLD_H:
                if wm[r, wc]:
                    break
                if em[r, wc] and not pm[r, wc] and not rm[r, wc]:
                    return (Tool.WIRE, wc, r)
                elif not em[r, wc] and not rm[r, wc]:
                    break

    # Zone helper functions
    all_zone_mask = resm | comm | indm

    def zone_area_ok(zr, zc):
        if zr < 1 or zr > WORLD_H - 2 or zc < 1 or zc > WORLD_W - 2:
            return False
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if not (0 <= rr < WORLD_H and 0 <= rc < WORLD_W):
                    return False
                if not em[rr, rc] and not all_zone_mask[rr, rc]:
                    return False
        return True

    def zone_already_there(zr, zc):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                rr, rc = zr + dr, zc + dc
                if 0 <= rr < WORLD_H and 0 <= rc < WORLD_W:
                    if all_zone_mask[rr, rc]:
                        return True
        return False

    def has_wire_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(wm[r0:r1, c0:c1]) or np.any(pm[r0:r1, c0:c1])

    def has_road_nearby(zr, zc, radius=4):
        r0 = max(0, zr - radius)
        r1 = min(WORLD_H, zr + radius + 1)
        c0 = max(0, zc - radius)
        c1 = min(WORLD_W, zc + radius + 1)
        return np.any(rm[r0:r1, c0:c1])

    # Phase 6: Place zones along spine (upper and lower)
    zone_cols = list(range(target_min_col + 1, target_max_col, 4))
    zone_idx = 0

    for zc in zone_cols:
        # Upper zones
        zr = upper_zone_row
        if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
            if has_wire_nearby(zr, zc, 4) and has_road_nearby(zr, zc, 5):
                return (pick_tool(zone_idx), zc, zr)
        zone_idx += 1

        # Lower zones
        zr = lower_zone_row
        if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
            if has_wire_nearby(zr, zc, 4) and has_road_nearby(zr, zc, 4):
                return (pick_tool(zone_idx), zc, zr)
        zone_idx += 1

    # Phase 7: Vertical roads from road_row down to lower zones
    for c in range(target_min_col, target_max_col + 1, 4):
        for r in range(road_row, lower_zone_row + 2):
            if 0 <= r < WORLD_H and not rm[r, c] and em[r, c] and not pm[r, c]:
                if rm[road_row, c] or r == road_row:
                    return (Tool.ROAD, c, r)

    # Vertical roads from road_row up to upper zones
    for c in range(target_min_col, target_max_col + 1, 4):
        for r in range(road_row, upper_zone_row - 2, -1):
            if 0 <= r < WORLD_H and not rm[r, c] and em[r, c] and not pm[r, c]:
                if rm[road_row, c] or r == road_row:
                    return (Tool.ROAD, c, r)

    # Phase 8: Second coal plant if needed
    if obs.city_pop > 200 and int(np.sum(pm)) < 9:
        px2 = plant_cx + 30
        py2 = plant_cy
        px2 = max(2, min(WORLD_W - 3, px2))
        py2 = max(2, min(WORLD_H - 3, py2))
        if em[py2, px2]:
            return (Tool.COALPOWER, px2, py2)

    # Phase 9: Connect second plant with wire
    if int(np.sum(pm)) >= 9:
        # Find any plant cell not adjacent to wire
        pr, pc = np.where(pm)
        if len(pr) > 0:
            for i in range(len(pr)):
                py, px = int(pr[i]), int(pc[i])
                # Try to wire from this plant toward spine
                for nx in range(px, min(px + 10, WORLD_W)):
                    if wm[wire_row, nx]:
                        break
                    if em[wire_row, nx]:
                        return (Tool.WIRE, nx, wire_row)

    # Phase 10: Second tier zones if growing
    if obs.city_pop > 200:
        for zc in zone_cols:
            zr = upper_zone_row2
            if zr >= 1 and not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc, 5) and has_road_nearby(zr, zc, 6):
                    return (pick_tool(zone_idx), zc, zr)
            zone_idx += 1

            zr = lower_zone_row2
            if zr < WORLD_H - 1 and not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                if has_wire_nearby(zr, zc, 5) and has_road_nearby(zr, zc, 6):
                    return (pick_tool(zone_idx), zc, zr)
            zone_idx += 1

    # Phase 11: Extend road to second tier zones
    if obs.city_pop > 150:
        for c in range(target_min_col, target_max_col + 1, 4):
            for r in range(lower_zone_row, lower_zone_row2 + 2):
                if 0 <= r < WORLD_H and not rm[r, c] and em[r, c] and not pm[r, c]:
                    if rm[lower_zone_row, c] or rm[road_row, c]:
                        return (Tool.ROAD, c, r)

    # Phase 12: Police/fire stations
    if obs.city_pop > 500:
        for zc in [cx - 15, cx + 15]:
            zr = cy
            if 1 <= zr <= WORLD_H - 2 and 1 <= zc <= WORLD_W - 2:
                if em[zr, zc]:
                    return (Tool.FIRESTATION, zc, zr)

    # Fallback: closed-loop zone placement near any wire+road intersection
    powered_src = wm | pm
    for dy in range(0, 20, 4):
        for dx in range(target_min_col, target_max_col, 4):
            for zr in [upper_zone_row + dy, lower_zone_row - dy]:
                zc = dx
                if not zone_already_there(zr, zc) and zone_area_ok(zr, zc):
                    if has_wire_nearby(zr, zc, 5) and has_road_nearby(zr, zc, 5):
                        return (pick_tool(zone_idx), zc, zr)
                zone_idx += 1

    return None
